void pt_intr_post(struct vcpu *v, struct hvm_intack intack)
{
struct periodic_time *pt;
time_cb *cb;
void *cb_priv;
if ( intack.source == hvm_intsrc_vector )
return;
spin_lock(&v->arch.hvm.tm_lock);
pt = is_pt_irq(v, intack);
if ( pt == NULL )
{
spin_unlock(&v->arch.hvm.tm_lock);
return;
}
pt_irq_fired(v, pt);
cb = pt->cb;
cb_priv = pt->priv;
spin_unlock(&v->arch.hvm.tm_lock);
if ( cb != NULL )
cb(v, cb_priv);
}

static gboolean
canonify_unencrypted_header(guchar *buff, guint32 *offset, guint32 buffsize)
{
const TOP_ELEMENT_CONTROL *t = canonifyTable;
guint32 len;
for (t = canonifyTable; t->element != NULL; t++)
{
len = *(t->length);
if (t->required && *(t->element) == NULL)
return FALSE;
if (*(t->element) != NULL) {
if (t->addtag) {
buff[(*offset)++] = t->tag;
(*offset) += encode_ber_len(&buff[*offset], len, 4);
}
if (t->truncate) {
len = 3+2*get_ber_len_size(len);
}
if (buffsize < *offset + len) {
return FALSE;
}
memcpy(&buff[*offset], *(t->element), len);
(*offset) += len;
if (t->addtag) {
*(t->element) = NULL;
}
}
}
return TRUE;
}

PIX *
pixBlockconvTiled(PIX     *pix,
l_int32  wc,
l_int32  hc,
l_int32  nx,
l_int32  ny)
{
l_int32     i, j, w, h, d, xrat, yrat;
PIX        *pixs, *pixd, *pixc, *pixt;
PIX        *pixr, *pixrc, *pixg, *pixgc, *pixb, *pixbc;
PIXTILING  *pt;
PROCNAME("pixBlockconvTiled");
if (!pix)
return (PIX *)ERROR_PTR("pix not defined", procName, NULL);
if (wc < 0) wc = 0;
if (hc < 0) hc = 0;
pixGetDimensions(pix, &w, &h, &d);
if (w < 2 * wc + 3 || h < 2 * hc + 3) {
wc = L_MAX(0, L_MIN(wc, (w - 3) / 2));
hc = L_MAX(0, L_MIN(hc, (h - 3) / 2));
L_WARNING("kernel too large; reducing!\n", procName);
L_INFO("wc = %d, hc = %d\n", procName, wc, hc);
}
if (wc == 0 && hc == 0)   
return pixCopy(NULL, pix);
if (nx <= 1 && ny <= 1)
return pixBlockconv(pix, wc, hc);
xrat = w / nx;
yrat = h / ny;
if (xrat < wc + 2) {
nx = w / (wc + 2);
L_WARNING("tile width too small; nx reduced to %d\n", procName, nx);
}
if (yrat < hc + 2) {
ny = h / (hc + 2);
L_WARNING("tile height too small; ny reduced to %d\n", procName, ny);
}
if ((d == 2 || d == 4 || d == 8) && pixGetColormap(pix)) {
L_WARNING("pix has colormap; removing\n", procName);
pixs = pixRemoveColormap(pix, REMOVE_CMAP_BASED_ON_SRC);
d = pixGetDepth(pixs);
} else {
pixs = pixClone(pix);
}
if (d != 8 && d != 32) {
pixDestroy(&pixs);
return (PIX *)ERROR_PTR("depth not 8 or 32 bpp", procName, NULL);
}
if ((pixd = pixCreateTemplate(pixs)) == NULL) {
pixDestroy(&pixs);
return (PIX *)ERROR_PTR("pixd not made", procName, NULL);
}
pt = pixTilingCreate(pixs, nx, ny, 0, 0, wc + 2, hc + 2);
for (i = 0; i < ny; i++) {
for (j = 0; j < nx; j++) {
pixt = pixTilingGetTile(pt, i, j);
if (d == 8) {
pixc = pixBlockconvGrayTile(pixt, NULL, wc, hc);
} else { 
pixr = pixGetRGBComponent(pixt, COLOR_RED);
pixrc = pixBlockconvGrayTile(pixr, NULL, wc, hc);
pixDestroy(&pixr);
pixg = pixGetRGBComponent(pixt, COLOR_GREEN);
pixgc = pixBlockconvGrayTile(pixg, NULL, wc, hc);
pixDestroy(&pixg);
pixb = pixGetRGBComponent(pixt, COLOR_BLUE);
pixbc = pixBlockconvGrayTile(pixb, NULL, wc, hc);
pixDestroy(&pixb);
pixc = pixCreateRGBImage(pixrc, pixgc, pixbc);
pixDestroy(&pixrc);
pixDestroy(&pixgc);
pixDestroy(&pixbc);
}
pixTilingPaintTile(pixd, i, j, pixc, pt);
pixDestroy(&pixt);
pixDestroy(&pixc);
}
}
pixDestroy(&pixs);
pixTilingDestroy(&pt);
return pixd;
}

static uint64_t unpack_timestamp(const struct efi_time *timestamp)
{
uint64_t val = 0;
uint16_t year = le32_to_cpu(timestamp->year);
val |= ((uint64_t) timestamp->pad1 & 0xFF) << 0;
val |= ((uint64_t) timestamp->second & 0xFF) << (1*8);
val |= ((uint64_t) timestamp->minute & 0xFF) << (2*8);
val |= ((uint64_t) timestamp->hour & 0xFF) << (3*8);
val |= ((uint64_t) timestamp->day & 0xFF) << (4*8);
val |= ((uint64_t) timestamp->month & 0xFF) << (5*8);
val |= ((uint64_t) year) << (6*8);
return val;
}

