if (av_id == MSV_AV_EOL) break;
}
if (av_id != MSV_AV_EOL || av_len != 0) {
ret = ERR_DECODE;
}
done:
if (ret) {
ntlm_free_buffer_data(&sh);
ntlm_free_buffer_data(&cb);
safefree(nb_computer);
safefree(nb_domain);
safefree(dns_computer);
safefree(dns_domain);
safefree(dns_tree);
safefree(av_target);
} else {
if (nb_computer_name) *nb_computer_name = nb_computer;
if (nb_domain_name) *nb_domain_name = nb_domain;
if (dns_computer_name) *dns_computer_name = dns_computer;
if (dns_domain_name) *dns_domain_name = dns_domain;
if (dns_tree_name) *dns_tree_name = dns_tree;
if (av_target_name) *av_target_name = av_target;
if (av_timestamp) *av_timestamp = timestamp;
if (av_single_host) *av_single_host = sh;
if (av_flags) *av_flags = flags;
if (av_cb) *av_cb = cb;
}
return ret;
}

static unsigned create_oops_dump_dirs(GList *oops_list, unsigned oops_cnt)
{
unsigned countdown = MAX_DUMPED_DD_COUNT; 
log_notice("Saving %u oopses as problem dirs", oops_cnt >= countdown ? countdown : oops_cnt);
char *cmdline_str = xmalloc_fopen_fgetline_fclose("/proc/cmdline");
char *fips_enabled = xmalloc_fopen_fgetline_fclose("/proc/sys/crypto/fips_enabled");
char *proc_modules = xmalloc_open_read_close("/proc/modules",  NULL);
char *suspend_stats = xmalloc_open_read_close("/sys/kernel/debug/suspend_stats",  NULL);
time_t t = time(NULL);
const char *iso_date = iso_date_string(&t);
uid_t my_euid = (uid_t)-1L;
mode_t mode = DEFAULT_DUMP_DIR_MODE | S_IROTH;
if (!world_readable_dump)
{
mode = DEFAULT_DUMP_DIR_MODE;
my_euid = geteuid();
}
pid_t my_pid = getpid();
unsigned idx = 0;
unsigned errors = 0;
while (idx < oops_cnt)
{
char base[sizeof("oops-YYYY-MM-DD-hh:mm:ss-%lu-%lu") + 2 * sizeof(long)*3];
sprintf(base, "oops-%s-%lu-%lu", iso_date, (long)my_pid, (long)idx);
char *path = concat_path_file(debug_dumps_dir, base);
struct dump_dir *dd = dd_create(path,  my_euid, mode);
if (dd)
{
dd_create_basic_files(dd,  my_euid, NULL);
save_oops_data_in_dump_dir(dd, (char*)g_list_nth_data(oops_list, idx++), proc_modules);
dd_save_text(dd, FILENAME_ABRT_VERSION, VERSION);
dd_save_text(dd, FILENAME_ANALYZER, "Kerneloops");
dd_save_text(dd, FILENAME_TYPE, "Kerneloops");
if (cmdline_str)
dd_save_text(dd, FILENAME_CMDLINE, cmdline_str);
if (proc_modules)
dd_save_text(dd, "proc_modules", proc_modules);
if (fips_enabled && strcmp(fips_enabled, "0") != 0)
dd_save_text(dd, "fips_enabled", fips_enabled);
if (suspend_stats)
dd_save_text(dd, "suspend_stats", suspend_stats);
dd_close(dd);
notify_new_path(path);
}
else
errors++;
free(path);
if (--countdown == 0)
break;
if (dd && throttle_dd_creation)
sleep(1);
}
free(cmdline_str);
free(proc_modules);
free(fips_enabled);
free(suspend_stats);
return errors;
}

GF_EXPORT
GF_Err gf_sg_vrml_mf_remove(void *mf, u32 FieldType, u32 RemoveFrom)
{
char *buffer;
u32 FieldSize, i, k;
GenMFField *mffield = (GenMFField *)mf;
FieldSize = gf_sg_vrml_get_sf_size(FieldType);
if (!FieldSize) return GF_BAD_PARAM;
if (!mffield->count || RemoveFrom >= mffield->count) return GF_BAD_PARAM;
if (mffield->count == 1) {
gf_free(mffield->array);
mffield->array = NULL;
mffield->count = 0;
return GF_OK;
}
k=0;
buffer = (char*)gf_malloc(sizeof(char)*(mffield->count-1)*FieldSize);
for (i=0; i<mffield->count; i++) {
if (RemoveFrom == i) {
k = 1;
} else {
memcpy(buffer + (i-k)*FieldSize, mffield->array + i*FieldSize, FieldSize);
}
}
gf_free(mffield->array);
mffield->array = buffer;
mffield->count -= 1;
return GF_OK;
}

static char *get_object(
FILE         *fp,
int           obj_id,
const xref_t *xref,
size_t       *size,
int          *is_stream)
{
static const int    blk_sz = 256;
int                 i, total_sz, read_sz, n_blks, search, stream;
size_t              obj_sz;
char               *c, *data;
long                start;
const xref_entry_t *entry;
if (size)
*size = 0;
if (is_stream)
*is_stream = 0;
start = ftell(fp);
entry = NULL;
for (i=0; i<xref->n_entries; i++)
if (xref->entries[i].obj_id == obj_id)
{
entry = &xref->entries[i];
break;
}
if (!entry)
return NULL;
fseek(fp, entry->offset, SEEK_SET);
obj_sz = 0;    
total_sz = 0;  
n_blks = 1;
data = malloc(blk_sz * n_blks);
memset(data, 0, blk_sz * n_blks);
stream = 0;
while ((read_sz = fread(data+total_sz, 1, blk_sz-1, fp)) && !ferror(fp))
{
total_sz += read_sz;
*(data + total_sz) = '\0';
if (total_sz + blk_sz >= (blk_sz * n_blks))
data = realloc(data, blk_sz * (++n_blks));
search = total_sz - read_sz;
if (search < 0)
search = 0;
if ((c = strstr(data + search, "endobj")))
{
*(c + strlen("endobj") + 1) = '\0';
obj_sz = (void *)strstr(data + search, "endobj") - (void *)data;
obj_sz += strlen("endobj") + 1;
break;
}
else if (strstr(data, "stream"))
stream = 1;
}
clearerr(fp);
fseek(fp, start, SEEK_SET);
if (size)
*size = obj_sz;
if (is_stream)
*is_stream = stream;
return data;
}

