void
getvcol(
win_T*wp,
pos_T*pos,
colnr_T*start,
colnr_T*cursor,
colnr_T*end)
{
colnr_Tvcol;
char_u*ptr;    char_u*posptr;    char_u*line;    intincr;
inthead;
#ifdef FEAT_VARTABS
int*vts = wp->w_buffer->b_p_vts_array;
#endif
intts = wp->w_buffer->b_p_ts;
intc;
vcol = 0;
line = ptr = ml_get_buf(wp->w_buffer, pos->lnum, FALSE);
if (pos->col == MAXCOL)
posptr = NULL;      else
{
if (*ptr == NUL)
pos->col = 0;
