return -1;
}
pch = strtok(NULL, ",");
if (pch != NULL) {
dp->ligand = pch;
} else {
log_messages.printf(MSG_CRITICAL, "Seek ligand failed\n");
return -1;
}
pch = strtok(NULL, ",");
