void ext4_es_remove_extent(struct inode *inode, ext4_lblk_t lblk,
ext4_lblk_t len)
{
ext4_lblk_t end;
int err = 0;
int reserved = 0;
struct extent_status *es = NULL;
if (EXT4_SB(inode->i_sb)->s_mount_state & EXT4_FC_REPLAY)
return;
trace_ext4_es_remove_extent(inode, lblk, len);
es_debug("remove [%u/%u) from extent status tree of inode %lu\n",
lblk, len, inode->i_ino);
if (!len)
return;
end = lblk + len - 1;
BUG_ON(end < lblk);
retry:
if (err && !es)
es = __es_alloc_extent(true);
write_lock(&EXT4_I(inode)->i_es_lock);
err = __es_remove_extent(inode, lblk, end, &reserved, es);
if (es && !es->es_len)
__es_free_extent(es);
write_unlock(&EXT4_I(inode)->i_es_lock);
if (err)
goto retry;
ext4_es_print_tree(inode);
ext4_da_release_space(inode, reserved);
return;
}

static bool unpack_file_for_central_directory_index(off_t central_directory_index, const MappedFile& file)
{
enum CentralFileDirectoryHeaderOffsets {
CFDHCompressionMethodOffset = 10,
CFDHLocalFileHeaderIndexOffset = 42,
};
enum LocalFileHeaderOffsets {
LFHCompressionMethodOffset = 8,
LFHCompressedSizeOffset = 18,
LFHFileNameLengthOffset = 26,
LFHExtraFieldLengthOffset = 28,
LFHFileNameBaseOffset = 30,
};
enum CompressionMethod {
None = 0,
Shrunk = 1,
Factor1 = 2,
Factor2 = 3,
Factor3 = 4,
Factor4 = 5,
Implode = 6,
Deflate = 8,
EnhancedDeflate = 9,
PKWareDCLImplode = 10,
BZIP2 = 12,
LZMA = 14,
TERSE = 18,
LZ77 = 19,
};
u8 buffer[4];
if (!seek_and_read(buffer, file, central_directory_index + CFDHLocalFileHeaderIndexOffset, 4))
return false;
off_t local_file_header_index = buffer[3] << 24 | buffer[2] << 16 | buffer[1] << 8 | buffer[0];
if (!seek_and_read(buffer, file, local_file_header_index + LFHCompressionMethodOffset, 2))
return false;
auto compression_method = buffer[1] << 8 | buffer[0];
VERIFY(compression_method == None);
if (!seek_and_read(buffer, file, local_file_header_index + LFHCompressedSizeOffset, 4))
return false;
off_t compressed_file_size = buffer[3] << 24 | buffer[2] << 16 | buffer[1] << 8 | buffer[0];
if (!seek_and_read(buffer, file, local_file_header_index + LFHFileNameLengthOffset, 2))
return false;
off_t file_name_length = buffer[1] << 8 | buffer[0];
if (!seek_and_read(buffer, file, local_file_header_index + LFHExtraFieldLengthOffset, 2))
return false;
off_t extra_field_length = buffer[1] << 8 | buffer[0];
char file_name[file_name_length + 1];
if (!seek_and_read((u8*)file_name, file, local_file_header_index + LFHFileNameBaseOffset, file_name_length))
return false;
file_name[file_name_length] = '\0';
if (file_name[file_name_length - 1] == '/') {
if (mkdir(file_name, 0755) < 0) {
perror("mkdir");
return false;
}
} else {
auto new_file = Core::File::construct(String { file_name });
if (!new_file->open(Core::IODevice::WriteOnly)) {
fprintf(stderr, "Can't write file %s: %s\n", file_name, new_file->error_string());
return false;
}
printf(" extracting: %s\n", file_name);
u8 raw_file_contents[compressed_file_size];
if (!seek_and_read(raw_file_contents, file, local_file_header_index + LFHFileNameBaseOffset + file_name_length + extra_field_length, compressed_file_size))
return false;
if (!new_file->write(raw_file_contents, compressed_file_size)) {
fprintf(stderr, "Can't write file contents in %s: %s\n", file_name, new_file->error_string());
return false;
}
if (!new_file->close()) {
fprintf(stderr, "Can't close file %s: %s\n", file_name, new_file->error_string());
return false;
}
}
return true;
}

SQLWCHAR* _multi_string_alloc_and_expand( LPCSTR in )
{
SQLWCHAR *chr;
int len = 0;
if ( !in )
{
return in;
}
while ( in[ len ] != 0 || in[ len + 1 ] != 0 )
{
len ++;
}
chr = malloc(sizeof( SQLWCHAR ) * ( len + 2 ));
len = 0;
while ( in[ len ] != 0 || in[ len + 1 ] != 0 )
{
chr[ len ] = in[ len ];
len ++;
}
chr[ len ++ ] = 0;
chr[ len ++ ] = 0;
return chr;
}

long do_memory_op(unsigned long cmd, XEN_GUEST_HANDLE_PARAM(void) arg)
{
struct domain *d, *curr_d = current->domain;
long rc;
struct xen_memory_reservation reservation;
struct memop_args args;
domid_t domid;
unsigned long start_extent = cmd >> MEMOP_EXTENT_SHIFT;
int op = cmd & MEMOP_CMD_MASK;
switch ( op )
{
case XENMEM_increase_reservation:
case XENMEM_decrease_reservation:
case XENMEM_populate_physmap:
if ( copy_from_guest(&reservation, arg, 1) )
return start_extent;
if ( reservation.nr_extents > (UINT_MAX >> MEMOP_EXTENT_SHIFT) )
return start_extent;
if ( unlikely(start_extent >= reservation.nr_extents) )
return start_extent;
d = rcu_lock_domain_by_any_id(reservation.domid);
if ( d == NULL )
return start_extent;
args.domain = d;
if ( construct_memop_from_reservation(&reservation, &args) )
{
rcu_unlock_domain(d);
return start_extent;
}
args.nr_done   = start_extent;
args.preempted = 0;
if ( op == XENMEM_populate_physmap
&& (reservation.mem_flags & XENMEMF_populate_on_demand) )
args.memflags |= MEMF_populate_on_demand;
if ( xsm_memory_adjust_reservation(XSM_TARGET, curr_d, d) )
{
rcu_unlock_domain(d);
return start_extent;
}
switch ( op )
{
case XENMEM_increase_reservation:
increase_reservation(&args);
break;
case XENMEM_decrease_reservation:
decrease_reservation(&args);
break;
default: 
populate_physmap(&args);
break;
}
rcu_unlock_domain(d);
rc = args.nr_done;
if ( args.preempted )
return hypercall_create_continuation(
__HYPERVISOR_memory_op, "lh",
op | (rc << MEMOP_EXTENT_SHIFT), arg);
break;
case XENMEM_exchange:
if ( unlikely(start_extent) )
return -EINVAL;
rc = memory_exchange(guest_handle_cast(arg, xen_memory_exchange_t));
break;
case XENMEM_maximum_ram_page:
if ( unlikely(start_extent) )
return -EINVAL;
rc = max_page;
break;
case XENMEM_current_reservation:
case XENMEM_maximum_reservation:
case XENMEM_maximum_gpfn:
if ( unlikely(start_extent) )
return -EINVAL;
if ( copy_from_guest(&domid, arg, 1) )
return -EFAULT;
d = rcu_lock_domain_by_any_id(domid);
if ( d == NULL )
return -ESRCH;
rc = xsm_memory_stat_reservation(XSM_TARGET, curr_d, d);
if ( rc )
{
rcu_unlock_domain(d);
return rc;
}
switch ( op )
{
case XENMEM_current_reservation:
rc = d->tot_pages;
break;
case XENMEM_maximum_reservation:
rc = d->max_pages;
break;
default:
ASSERT(op == XENMEM_maximum_gpfn);
rc = domain_get_maximum_gpfn(d);
break;
}
rcu_unlock_domain(d);
break;
case XENMEM_add_to_physmap:
{
struct xen_add_to_physmap xatp;
BUILD_BUG_ON((typeof(xatp.size))-1 > (UINT_MAX >> MEMOP_EXTENT_SHIFT));
if ( start_extent != (typeof(xatp.size))start_extent )
return -EDOM;
if ( copy_from_guest(&xatp, arg, 1) )
return -EFAULT;
if ( xatp.space == XENMAPSPACE_gmfn_foreign )
return -ENOSYS;
d = rcu_lock_domain_by_any_id(xatp.domid);
if ( d == NULL )
return -ESRCH;
rc = xatp_permission_check(d, xatp.space);
if ( rc )
{
rcu_unlock_domain(d);
return rc;
}
rc = xenmem_add_to_physmap(d, &xatp, start_extent);
rcu_unlock_domain(d);
if ( xatp.space == XENMAPSPACE_gmfn_range && rc > 0 )
rc = hypercall_create_continuation(
__HYPERVISOR_memory_op, "lh",
op | (rc << MEMOP_EXTENT_SHIFT), arg);
return rc;
}
case XENMEM_add_to_physmap_batch:
{
struct xen_add_to_physmap_batch xatpb;
BUILD_BUG_ON((typeof(xatpb.size))-1 >
(UINT_MAX >> MEMOP_EXTENT_SHIFT));
if ( start_extent != (typeof(xatpb.size))start_extent )
return -EDOM;
if ( copy_from_guest(&xatpb, arg, 1) ||
!guest_handle_okay(xatpb.idxs, xatpb.size) ||
!guest_handle_okay(xatpb.gpfns, xatpb.size) ||
!guest_handle_okay(xatpb.errs, xatpb.size) )
return -EFAULT;
if ( xatpb.space == XENMAPSPACE_gmfn_range )
return -EOPNOTSUPP;
d = rcu_lock_domain_by_any_id(xatpb.domid);
if ( d == NULL )
return -ESRCH;
rc = xatp_permission_check(d, xatpb.space);
if ( rc )
{
rcu_unlock_domain(d);
return rc;
}
rc = xenmem_add_to_physmap_batch(d, &xatpb, start_extent);
rcu_unlock_domain(d);
if ( rc > 0 )
rc = hypercall_create_continuation(
__HYPERVISOR_memory_op, "lh",
op | (rc << MEMOP_EXTENT_SHIFT), arg);
return rc;
}
case XENMEM_remove_from_physmap:
{
struct xen_remove_from_physmap xrfp;
struct page_info *page;
if ( unlikely(start_extent) )
return -EINVAL;
if ( copy_from_guest(&xrfp, arg, 1) )
return -EFAULT;
d = rcu_lock_domain_by_any_id(xrfp.domid);
if ( d == NULL )
return -ESRCH;
rc = xsm_remove_from_physmap(XSM_TARGET, curr_d, d);
if ( rc )
{
rcu_unlock_domain(d);
return rc;
}
page = get_page_from_gfn(d, xrfp.gpfn, NULL, P2M_ALLOC);
if ( page )
{
guest_physmap_remove_page(d, _gfn(xrfp.gpfn),
_mfn(page_to_mfn(page)), 0);
put_page(page);
}
else
rc = -ENOENT;
rcu_unlock_domain(d);
break;
}
case XENMEM_access_op:
rc = mem_access_memop(cmd, guest_handle_cast(arg, xen_mem_access_op_t));
break;
case XENMEM_claim_pages:
if ( unlikely(start_extent) )
return -EINVAL;
if ( copy_from_guest(&reservation, arg, 1) )
return -EFAULT;
if ( !guest_handle_is_null(reservation.extent_start) )
return -EINVAL;
if ( reservation.extent_order != 0 )
return -EINVAL;
if ( reservation.mem_flags != 0 )
return -EINVAL;
d = rcu_lock_domain_by_id(reservation.domid);
if ( d == NULL )
return -EINVAL;
rc = xsm_claim_pages(XSM_PRIV, d);
if ( !rc )
rc = domain_set_outstanding_pages(d, reservation.nr_extents);
rcu_unlock_domain(d);
break;
case XENMEM_get_vnumainfo:
{
struct xen_vnuma_topology_info topology;
unsigned int dom_vnodes, dom_vranges, dom_vcpus;
struct vnuma_info tmp;
if ( unlikely(start_extent) )
return -EINVAL;
if ( copy_from_guest(&topology, arg, 1 ))
return -EFAULT;
if ( topology.pad != 0 )
return -EINVAL;
if ( (d = rcu_lock_domain_by_any_id(topology.domid)) == NULL )
return -ESRCH;
rc = xsm_get_vnumainfo(XSM_TARGET, d);
if ( rc )
{
rcu_unlock_domain(d);
return rc;
}
read_lock(&d->vnuma_rwlock);
if ( d->vnuma == NULL )
{
read_unlock(&d->vnuma_rwlock);
rcu_unlock_domain(d);
return -EOPNOTSUPP;
}
dom_vnodes = d->vnuma->nr_vnodes;
dom_vranges = d->vnuma->nr_vmemranges;
dom_vcpus = d->max_vcpus;
if ( topology.nr_vnodes < dom_vnodes      ||
topology.nr_vcpus < dom_vcpus        ||
topology.nr_vmemranges < dom_vranges )
{
read_unlock(&d->vnuma_rwlock);
rcu_unlock_domain(d);
topology.nr_vnodes = dom_vnodes;
topology.nr_vcpus = dom_vcpus;
topology.nr_vmemranges = dom_vranges;
return __copy_to_guest(arg, &topology, 1) ? -EFAULT : -ENOBUFS;
}
read_unlock(&d->vnuma_rwlock);
tmp.vdistance = xmalloc_array(unsigned int, dom_vnodes * dom_vnodes);
tmp.vmemrange = xmalloc_array(xen_vmemrange_t, dom_vranges);
tmp.vcpu_to_vnode = xmalloc_array(unsigned int, dom_vcpus);
if ( tmp.vdistance == NULL ||
tmp.vmemrange == NULL ||
tmp.vcpu_to_vnode == NULL )
{
rc = -ENOMEM;
goto vnumainfo_out;
}
read_lock(&d->vnuma_rwlock);
if ( dom_vnodes < d->vnuma->nr_vnodes ||
dom_vranges < d->vnuma->nr_vmemranges ||
dom_vcpus < d->max_vcpus )
{
read_unlock(&d->vnuma_rwlock);
rc = -EAGAIN;
goto vnumainfo_out;
}
dom_vnodes = d->vnuma->nr_vnodes;
dom_vranges = d->vnuma->nr_vmemranges;
dom_vcpus = d->max_vcpus;
memcpy(tmp.vmemrange, d->vnuma->vmemrange,
sizeof(*d->vnuma->vmemrange) * dom_vranges);
memcpy(tmp.vdistance, d->vnuma->vdistance,
sizeof(*d->vnuma->vdistance) * dom_vnodes * dom_vnodes);
memcpy(tmp.vcpu_to_vnode, d->vnuma->vcpu_to_vnode,
sizeof(*d->vnuma->vcpu_to_vnode) * dom_vcpus);
read_unlock(&d->vnuma_rwlock);
rc = -EFAULT;
if ( copy_to_guest(topology.vmemrange.h, tmp.vmemrange,
dom_vranges) != 0 )
goto vnumainfo_out;
if ( copy_to_guest(topology.vdistance.h, tmp.vdistance,
dom_vnodes * dom_vnodes) != 0 )
goto vnumainfo_out;
if ( copy_to_guest(topology.vcpu_to_vnode.h, tmp.vcpu_to_vnode,
dom_vcpus) != 0 )
goto vnumainfo_out;
topology.nr_vnodes = dom_vnodes;
topology.nr_vcpus = dom_vcpus;
topology.nr_vmemranges = dom_vranges;
rc = __copy_to_guest(arg, &topology, 1) ? -EFAULT : 0;
vnumainfo_out:
rcu_unlock_domain(d);
xfree(tmp.vdistance);
xfree(tmp.vmemrange);
xfree(tmp.vcpu_to_vnode);
break;
}
#ifdef CONFIG_HAS_PASSTHROUGH
case XENMEM_reserved_device_memory_map:
{
struct get_reserved_device_memory grdm;
if ( unlikely(start_extent) )
return -EINVAL;
if ( copy_from_guest(&grdm.map, arg, 1) ||
!guest_handle_okay(grdm.map.buffer, grdm.map.nr_entries) )
return -EFAULT;
if ( grdm.map.flags & ~XENMEM_RDM_ALL )
return -EINVAL;
grdm.used_entries = 0;
rc = iommu_get_reserved_device_memory(get_reserved_device_memory,
&grdm);
if ( !rc && grdm.map.nr_entries < grdm.used_entries )
rc = -ENOBUFS;
grdm.map.nr_entries = grdm.used_entries;
if ( __copy_to_guest(arg, &grdm.map, 1) )
rc = -EFAULT;
break;
}
#endif
default:
rc = arch_memory_op(cmd, arg);
break;
}
return rc;
}

static int parse_line(char *str)
{
uint8_t array[256];
uint16_t value, pskey, length = 0;
char *off, *end;
pskey = strtol(str + 1, NULL, 16);
off = strstr(str, "=");
if (!off)
return -EIO;
off++;
while (1) {
value = strtol(off, &end, 16);
if (value == 0 && off == end)
break;
array[length++] = value & 0xff;
array[length++] = value >> 8;
if (*end == '\0')
break;
off = end + 1;
}
return psr_put(pskey, array, length);
}

