Status ConstantFolding::CreateNodeDef(const string& name,
const TensorValue& tensor, NodeDef* node,
size_t original_size) {
node->set_name(name);
node->set_op("Const");
AttrValue attr_type;
attr_type.set_type(tensor->dtype());
node->mutable_attr()->insert({"dtype", attr_type});
AttrValue attr_tensor;
TensorProto* t = attr_tensor.mutable_tensor();
bool optimized = false;
size_t encoded_size;
if (tensor->NumElements() > 4) {
#define POPULATE_TENSOR_PROTO(tensor, t, TYPE, FIELDTYPE)                      \
{                                                                            \
const auto* val_ptr = tensor->flat<TYPE>().data();                         \
auto last = *val_ptr;                                                      \
int64_t last_index = 0;                                                    \
for (int64_t i = 0; i < tensor->NumElements(); ++i) {                      \
TYPE cur = *val_ptr++;                                                   \
if (PackedValuesNotEqual(cur, last)) {                                   \
last = cur;                                                            \
last_index = i;                                                        \
}                                                                        \
}                                                                          \
encoded_size = (last_index + 1) * sizeof(FIELDTYPE);                       \
if (encoded_size < kint32max) {                                            \
optimized = true;                                                        \
t->mutable_##FIELDTYPE##_val()->Reserve(last_index + 1);                 \
const auto* src_ptr = tensor->flat<TYPE>().data();                       \
auto* dst_ptr =                                                          \
t->mutable_##FIELDTYPE##_val()->AddNAlreadyReserved(last_index + 1); \
std::copy(src_ptr, src_ptr + last_index + 1, dst_ptr);                   \
}                                                                          \
}                                                                            \
break
switch (tensor->dtype()) {
case DT_FLOAT:
POPULATE_TENSOR_PROTO(tensor, t, float, float);
case DT_DOUBLE:
POPULATE_TENSOR_PROTO(tensor, t, double, double);
case DT_INT64:
POPULATE_TENSOR_PROTO(tensor, t, int64_t, int64);
case DT_UINT64:
POPULATE_TENSOR_PROTO(tensor, t, uint64, uint64);
case DT_INT32:
POPULATE_TENSOR_PROTO(tensor, t, int32_t, int);
case DT_UINT32:
POPULATE_TENSOR_PROTO(tensor, t, uint32, uint32);
case DT_INT16:
POPULATE_TENSOR_PROTO(tensor, t, int16_t, int);
case DT_UINT16:
POPULATE_TENSOR_PROTO(tensor, t, uint16, int);
case DT_INT8:
POPULATE_TENSOR_PROTO(tensor, t, int8_t, int);
case DT_UINT8:
POPULATE_TENSOR_PROTO(tensor, t, uint8, int);
case DT_BOOL:
POPULATE_TENSOR_PROTO(tensor, t, bool, bool);
default:
break;
}
}
if (optimized) {
t->set_dtype(tensor->dtype());
tensor->shape().AsProto(t->mutable_tensor_shape());
} else {
tensor->AsProtoTensorContent(t);
encoded_size = t->tensor_content().size();
}
node->mutable_attr()->insert({"value", attr_tensor});
if (encoded_size > original_size && encoded_size >= kMaxConstantSize) {
return errors::InvalidArgument(
strings::StrCat("Can't fold ", name, ", its size would be too large (",
encoded_size, " >= ", kMaxConstantSize, " bytes)"));
}
return Status::OK();
}
Status ConstantFolding::EvaluateNode(const NodeDef& node,
const TensorVector& inputs,
TensorVector* output) const {
return ::tensorflow::grappler::EvaluateNode(node, inputs, cpu_device_,
resource_mgr_.get(), output);
}
Status ConstantFolding::EvaluateOneFoldable(const NodeDef& node,
std::vector<NodeDef>* outputs,
bool* result_too_large) {
TensorVector inputs;
TensorVector output_tensors;
auto inputs_cleanup = gtl::MakeCleanup([&inputs, &output_tensors] {
for (const auto& input : inputs) {
delete input.tensor;
}
for (const auto& output : output_tensors) {
if (output.tensor) {
delete output.tensor;
}
}
});
size_t total_inputs_size = 0;
for (const auto& input : node.input()) {
const TensorId input_tensor = ParseTensorName(input);
if (input_tensor.index() < 0) {
break;
}
const NodeDef* input_node = node_map_->GetNode(input);
if (!IsReallyConstant(*input_node)) {
return Status(error::INVALID_ARGUMENT,
strings::StrCat("Can't fold ", node.name(), ", its ", input,
" isn't constant"));
}
TF_RETURN_IF_ERROR(CheckAttrExists(*input_node, "value"));
const TensorProto& raw_val = input_node->attr().at("value").tensor();
if (raw_val.dtype() == DT_INVALID) {
return Status(
error::INVALID_ARGUMENT,
strings::StrCat("A tensor in the input node, with TensorId of ",
input_tensor.ToString(),
" has a dtype of DT_INVALID."));
}
Tensor* value = new Tensor(raw_val.dtype(), raw_val.tensor_shape());
if (!value->FromProto(raw_val)) {
delete (value);
return errors::InvalidArgument("Unable to make Tensor from proto for ",
node.name(), " with shape ",
raw_val.tensor_shape().DebugString());
}
inputs.emplace_back(value);
total_inputs_size += value->TotalBytes();
}
TF_RETURN_IF_ERROR(EvaluateNode(node, inputs, &output_tensors));
if (output_tensors.empty()) {
return Status(error::INVALID_ARGUMENT, "Expected at least one output.");
}
outputs->resize(output_tensors.size());
for (size_t i = 0; i < output_tensors.size(); i++) {
string node_name = OptimizedNodeName(node, "-folded");
if (output_tensors.size() > 1) {
node_name = strings::StrCat(node_name, "-", i);
}
if (output_tensors[i].tensor) {
Status s = CreateNodeDef(node_name, output_tensors[i], &outputs->at(i),
total_inputs_size);
if (!s.ok()) {
*result_too_large = true;
return s;
}
} else {
outputs->at(i) = NodeDef();
}
}
return Status::OK();
}
Status ConstantFolding::FoldMergeNode(NodeDef* node, GraphDef* output_graph) {
for (int input_index = 0; input_index < node->input_size(); ++input_index) {
const auto& input = node->input(input_index);
if (IsControlInput(input)) {
continue;
}
NodeDef* input_node = node_map_->GetNode(input);
if (!IsReallyConstant(*input_node)) {
continue;
}
bool valid_input = true;
for (const string& fanin_of_input : input_node->input()) {
if (IsControlInput(fanin_of_input)) {
valid_input = false;
break;
}
}
if (!valid_input) {
continue;
}
string const_out_name = OptimizedNodeName(*node, "_const");
string const_index_name = OptimizedNodeName(*node, "_index");
if (node_map_->GetNode(const_out_name) ||
node_map_->GetNode(const_index_name)) {
return errors::AlreadyExists(
strings::StrCat(const_out_name, " or ", const_index_name,
" already present in the graph"));
}
NodeDef* const_out = output_graph->add_node();
*const_out = *input_node;
const_out->set_name(const_out_name);
const_out->set_device(node->device());
*const_out->add_input() = AsControlDependency(*node);
node_map_->AddNode(const_out->name(), const_out);
node_map_->AddOutput(node->name(), const_out->name());
NodeDef* const_index = output_graph->add_node();
const_index->set_op("Const");
Tensor index(DT_INT32, TensorShape({}));
index.flat<int32>()(0) = input_index;
(*const_index->mutable_attr())["dtype"].set_type(DT_INT32);
index.AsProtoTensorContent(
(*const_index->mutable_attr())["value"].mutable_tensor());
const_index->set_name(const_index_name);
const_index->set_device(node->device());
*const_index->add_input() = AsControlDependency(*node);
node_map_->AddNode(const_index->name(), const_index);
node_map_->AddOutput(node->name(), const_index->name());
auto outputs = node_map_->GetOutputs(node->name());
for (NodeDef* output : outputs) {
for (int i = 0; i < output->input_size(); i++) {
int port;
string node_name = ParseNodeName(output->input(i), &port);
if (node_name == node->name()) {
if (port == 0) {
*output->mutable_input(i) = const_out->name();
node_map_->AddOutput(const_out->name(), output->name());
} else if (port == 1) {
*output->mutable_input(i) = const_index->name();
node_map_->AddOutput(const_index->name(), output->name());
} else {
}
}
}
}
return Status::OK();
}
return Status::OK();
}
Status ConstantFolding::FoldNode(NodeDef* node, GraphDef* output_graph,
bool* result_too_large) {
*result_too_large = false;
if (IsMerge(*node)) {
return FoldMergeNode(node, output_graph);
}
std::vector<NodeDef> const_nodes;
TF_RETURN_IF_ERROR(
EvaluateOneFoldable(*node, &const_nodes, result_too_large));
VLOG(2) << "Folded node: " << SummarizeNodeDef(*node);
NodeDef* constant_output = nullptr;
for (int i = 0, end = const_nodes.size(); i < end; i++) {
NodeDef* const_node = &const_nodes[i];
VLOG(3) << "Generated constant node: " << SummarizeNodeDef(*const_node);
if (const_node->name().empty()) {
continue;
}
const auto is_duplicate_control_input = [&](const string& input) -> bool {
auto it = absl::c_find(const_node->input(), input);
return it != const_node->input().end();
};
for (const string& input : node->input()) {
if (IsControlInput(input)) {
if (!is_duplicate_control_input(input)) {
*const_node->add_input() = input;
}
}
if (!IsControlInput(input)) {
NodeDef* input_node = node_map_->GetNode(input);
for (const string& fanin_of_input : input_node->input()) {
if (!is_duplicate_control_input(fanin_of_input)) {
*const_node->add_input() = fanin_of_input;
}
}
}
}
if (const_nodes.size() == 1) {
node->set_op("Const");
node_map_->RemoveInputs(node->name());
node->clear_input();
*node->mutable_input() = const_node->input();
for (const auto& input : node->input()) {
node_map_->AddOutput(NodeName(input), node->name());
}
*node->mutable_attr() = const_node->attr();
break;
} else {
if (node_map_->GetNode(const_node->name())) {
return errors::AlreadyExists(strings::StrCat(
const_node->name(), " already present in the graph"));
}
NodeDef* added_node = output_graph->add_node();
*added_node = *const_node;
added_node->set_device(node->device());
node_map_->AddNode(added_node->name(), added_node);
for (const auto& input : added_node->input()) {
node_map_->AddOutput(NodeName(input), added_node->name());
}
constant_output = added_node;
}
}
if (const_nodes.size() > 1) {
auto outputs = node_map_->GetOutputs(node->name());
for (NodeDef* output : outputs) {
for (int i = 0; i < output->input_size(); i++) {
int port;
string node_name = ParseNodeName(output->input(i), &port);
if (node_name == node->name()) {
if (port < 0) {
if (constant_output != nullptr) {
node_map_->UpdateInput(node_name, NodeName(output->input(i)),
constant_output->name());
*output->mutable_input(i) = AsControlDependency(*constant_output);
}
} else if (port < static_cast<int>(const_nodes.size()) &&
!const_nodes[port].name().empty()) {
node_map_->UpdateInput(output->name(), NodeName(output->input(i)),
const_nodes[port].name());
*output->mutable_input(i) = const_nodes[port].name();
} else {
VLOG(3) << "Preserving edge from " << node->name() << ":" << port
<< "[" << node->op() << "] to " << output->name() << ":"
<< i << "[" << output->op() << "]";
}
}
}
}
outputs = node_map_->GetOutputs(node->name());
if (outputs.empty() && has_fetch_ &&
nodes_to_preserve_.find(node->name()) == nodes_to_preserve_.end()) {
node_map_->RemoveInputs(node->name());
node->clear_input();
}
}
return Status::OK();
}
Status ConstantFolding::FoldGraph(
const GraphProperties& properties, GraphDef* optimized_graph,
absl::flat_hash_set<string>* nodes_to_not_simplify) {
absl::flat_hash_set<string> processed_nodes;
std::deque<NodeDef*> queue;
for (int i = 0; i < graph_->node_size(); i++) {
const NodeDef& node = graph_->node(i);
if (IsFoldable(node, &properties) &&
!nodes_to_not_simplify->count(node.name())) {
queue.push_back(graph_->mutable_node(i));
}
}
while (!queue.empty()) {
NodeDef* node = queue.front();
queue.pop_front();
if (processed_nodes.count(node->name())) {
continue;
}
std::vector<NodeDef*> fanout =
node_map_->GetOutputsOrderedByNodeName(node->name());
bool result_too_large = false;
Status s = FoldNode(node, optimized_graph, &result_too_large);
processed_nodes.insert(node->name());
if (!s.ok()) {
VLOG(1) << "Failed to fold node " << node->DebugString()
<< "\nError message: " << s;
if (result_too_large) {
nodes_to_not_simplify->emplace(node->name());
}
} else {
for (auto& fanout_node : fanout) {
if (IsFoldable(*fanout_node, &properties) &&
!nodes_to_not_simplify->count(fanout_node->name())) {
queue.push_back(fanout_node);
}
}
}
}
std::vector<int> nodes_to_delete;
for (int i = 0; i < optimized_graph->node_size(); i++) {
const auto& fanout = node_map_->GetOutputs(optimized_graph->node(i).name());
if (fanout.empty()) nodes_to_delete.push_back(i);
}
EraseNodesFromGraph(std::move(nodes_to_delete), optimized_graph);
for (int i = 0; i < graph_->node_size(); ++i) {
NodeDef* node = graph_->mutable_node(i);
const auto& fanout = node_map_->GetOutputs(node->name());
if (!fanout.empty() || !has_fetch_ ||
nodes_to_preserve_.find(node->name()) != nodes_to_preserve_.end()) {
*(optimized_graph->add_node()) = std::move(*node);
}
}
return Status::OK();
}
Status ConstantFolding::IsSimplifiableReshape(
const NodeDef& node, const GraphProperties& properties) const {
if (!IsReshape(node)) {
return errors::Internal("Node ", node.name(), " is not a Reshape node");
}
CHECK_LE(2, node.input_size());
const NodeDef* new_shape = node_map_->GetNode(node.input(1));
if (!IsReallyConstant(*new_shape)) {
return errors::Internal("Node ", node.name(), " has shape ",
new_shape->DebugString(),
" which is not a constant");
}
TensorVector outputs;
auto outputs_cleanup = gtl::MakeCleanup([&outputs] {
for (const auto& output : outputs) {
delete output.tensor;
}
});
Status s = EvaluateNode(*new_shape, TensorVector(), &outputs);
if (!s.ok()) {
return errors::Internal("Could not evaluate node ", node.name());
}
CHECK_EQ(1, outputs.size());
const std::vector<OpInfo::TensorProperties>& props =
properties.GetInputProperties(node.name());
if (props.empty()) {
return errors::Internal("Node ", node.name(), " has no properties");
}
const OpInfo::TensorProperties& prop = props[0];
if (prop.dtype() == DT_INVALID) {
return errors::Internal("Node ", node.name(), " has property ",
prop.DebugString(), " with invalid dtype");
}
const PartialTensorShape shape(prop.shape());
if (!shape.IsFullyDefined()) {
return errors::Internal("Node ", node.name(), " has property ",
prop.DebugString(), " with shape ",
shape.DebugString(), " which is not fully defined");
}
PartialTensorShape new_dims;
if (outputs[0]->dtype() == DT_INT32) {
std::vector<int32> shp;
for (int i = 0; i < outputs[0]->NumElements(); ++i) {
int32_t dim = outputs[0]->flat<int32>()(i);
shp.push_back(dim);
}
TF_CHECK_OK(TensorShapeUtils::MakeShape(shp, &new_dims));
} else {
std::vector<int64_t> shp;
for (int i = 0; i < outputs[0]->NumElements(); ++i) {
int64_t dim = outputs[0]->flat<int64_t>()(i);
shp.push_back(dim);
}
TF_CHECK_OK(TensorShapeUtils::MakeShape(shp, &new_dims));
}
if (!shape.IsCompatibleWith(new_dims)) {
return errors::Internal("Expected shape ", shape.DebugString(),
"to be compatible with ", new_dims.DebugString());
}
return Status::OK();
}
#define IS_VALUE_CASE(DTYPE, VALUE)                   \
case DTYPE:                                         \
return AllValuesAre<EnumToDataType<DTYPE>::Type>( \
node.attr().at("value").tensor(), EnumToDataType<DTYPE>::Type(VALUE))
#define IS_ONES_CASE(TYPE) IS_VALUE_CASE(TYPE, 1)
#define IS_ZEROS_CASE(TYPE) IS_VALUE_CASE(TYPE, 0)
bool ConstantFolding::IsOnes(const NodeDef& node) const {
if (feed_nodes_.find(node.name()) != feed_nodes_.end()) {
return false;
}
if (IsOnesLike(node)) return true;
if (IsZerosLike(node)) return false;
if (node.op() == "Fill") {
NodeDef* values = node_map_->GetNode(NodeName(node.input(1)));
return values != nullptr && IsOnes(*values);
}
if (node.op() != "Const") return false;
if (node.attr().count("dtype") == 0) return false;
const auto dtype = node.attr().at("dtype").type();
switch (dtype) {
IS_ONES_CASE(DT_BOOL);
IS_ONES_CASE(DT_HALF);
IS_ONES_CASE(DT_BFLOAT16);
IS_ONES_CASE(DT_FLOAT);
IS_ONES_CASE(DT_DOUBLE);
IS_ONES_CASE(DT_COMPLEX64);
IS_ONES_CASE(DT_COMPLEX128);
IS_ONES_CASE(DT_UINT8);
IS_ONES_CASE(DT_INT8);
IS_ONES_CASE(DT_UINT16);
IS_ONES_CASE(DT_INT16);
IS_ONES_CASE(DT_INT32);
IS_ONES_CASE(DT_INT64);
IS_ONES_CASE(DT_QINT32);
IS_ONES_CASE(DT_QINT16);
IS_ONES_CASE(DT_QUINT16);
IS_ONES_CASE(DT_QINT8);
IS_ONES_CASE(DT_QUINT8);
default:
VLOG(1) << "Unsupported type " << DataTypeString(dtype);
return false;
}
return false;
}

static int _lldp_send(struct lldpd *global,
struct lldpd_hardware *hardware,
u_int8_t c_id_subtype,
char *c_id,
int c_id_len,
u_int8_t p_id_subtype,
char *p_id,
int p_id_len,
int shutdown)
{
struct lldpd_port *port;
struct lldpd_chassis *chassis;
struct lldpd_frame *frame;
int length;
u_int8_t *packet, *pos, *tlv;
struct lldpd_mgmt *mgmt;
int proto;
u_int8_t mcastaddr[] = LLDP_MULTICAST_ADDR;
#ifdef ENABLE_DOT1
const u_int8_t dot1[] = LLDP_TLV_ORG_DOT1;
struct lldpd_vlan *vlan;
struct lldpd_ppvid *ppvid;
struct lldpd_pi *pi;
#endif
#ifdef ENABLE_DOT3
const u_int8_t dot3[] = LLDP_TLV_ORG_DOT3;
#endif
#ifdef ENABLE_LLDPMED
int i;
const u_int8_t med[] = LLDP_TLV_ORG_MED;
#endif
#ifdef ENABLE_CUSTOM
struct lldpd_custom *custom;
#endif
port = &hardware->h_lport;
chassis = port->p_chassis;
length = hardware->h_mtu;
if ((packet = (u_int8_t*)calloc(1, length)) == NULL)
return ENOMEM;
pos = packet;
if (!(
POKE_BYTES(mcastaddr, sizeof(mcastaddr)) &&
POKE_BYTES(&hardware->h_lladdr, ETHER_ADDR_LEN) &&
POKE_UINT16(ETHERTYPE_LLDP)))
goto toobig;
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_CHASSIS_ID) &&
POKE_UINT8(c_id_subtype) &&
POKE_BYTES(c_id, c_id_len) &&
POKE_END_LLDP_TLV))
goto toobig;
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_PORT_ID) &&
POKE_UINT8(p_id_subtype) &&
POKE_BYTES(p_id, p_id_len) &&
POKE_END_LLDP_TLV))
goto toobig;
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_TTL) &&
POKE_UINT16(shutdown?0:chassis->c_ttl) &&
POKE_END_LLDP_TLV))
goto toobig;
if (shutdown)
goto end;
if (chassis->c_name && *chassis->c_name != '\0') {
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_SYSTEM_NAME) &&
POKE_BYTES(chassis->c_name, strlen(chassis->c_name)) &&
POKE_END_LLDP_TLV))
goto toobig;
}
if (chassis->c_descr && *chassis->c_descr != '\0') {
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_SYSTEM_DESCR) &&
POKE_BYTES(chassis->c_descr, strlen(chassis->c_descr)) &&
POKE_END_LLDP_TLV))
goto toobig;
}
if (global->g_config.c_cap_advertise && chassis->c_cap_available) {
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_SYSTEM_CAP) &&
POKE_UINT16(chassis->c_cap_available) &&
POKE_UINT16(chassis->c_cap_enabled) &&
POKE_END_LLDP_TLV))
goto toobig;
}
TAILQ_FOREACH(mgmt, &chassis->c_mgmt, m_entries) {
proto = lldpd_af_to_lldp_proto(mgmt->m_family);
assert(proto != LLDP_MGMT_ADDR_NONE);
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_MGMT_ADDR) &&
POKE_UINT8(mgmt->m_addrsize + 1) &&
POKE_UINT8(proto) &&
POKE_BYTES(&mgmt->m_addr, mgmt->m_addrsize)))
goto toobig;
if (mgmt->m_iface == 0) {
if (!(
POKE_UINT8(LLDP_MGMT_IFACE_UNKNOWN) &&
POKE_UINT32(0)))
goto toobig;
} else {
if (!(
POKE_UINT8(LLDP_MGMT_IFACE_IFINDEX) &&
POKE_UINT32(mgmt->m_iface)))
goto toobig;
}
if (!(
POKE_UINT8(0) &&
POKE_END_LLDP_TLV))
goto toobig;
}
if (port->p_descr && *port->p_descr != '\0') {
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_PORT_DESCR) &&
POKE_BYTES(port->p_descr, strlen(port->p_descr)) &&
POKE_END_LLDP_TLV))
goto toobig;
}
#ifdef ENABLE_DOT1
if(port->p_pvid != 0) {
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_ORG) &&
POKE_BYTES(dot1, sizeof(dot1)) &&
POKE_UINT8(LLDP_TLV_DOT1_PVID) &&
POKE_UINT16(port->p_pvid) &&
POKE_END_LLDP_TLV)) {
goto toobig;
}
}
TAILQ_FOREACH(ppvid, &port->p_ppvids, p_entries) {
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_ORG) &&
POKE_BYTES(dot1, sizeof(dot1)) &&
POKE_UINT8(LLDP_TLV_DOT1_PPVID) &&
POKE_UINT8(ppvid->p_cap_status) &&
POKE_UINT16(ppvid->p_ppvid) &&
POKE_END_LLDP_TLV)) {
goto toobig;
}
}
TAILQ_FOREACH(vlan, &port->p_vlans, v_entries) {
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_ORG) &&
POKE_BYTES(dot1, sizeof(dot1)) &&
POKE_UINT8(LLDP_TLV_DOT1_VLANNAME) &&
POKE_UINT16(vlan->v_vid) &&
POKE_UINT8(strlen(vlan->v_name)) &&
POKE_BYTES(vlan->v_name, strlen(vlan->v_name)) &&
POKE_END_LLDP_TLV))
goto toobig;
}
TAILQ_FOREACH(pi, &port->p_pids, p_entries) {
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_ORG) &&
POKE_BYTES(dot1, sizeof(dot1)) &&
POKE_UINT8(LLDP_TLV_DOT1_PI) &&
POKE_UINT8(pi->p_pi_len) &&
POKE_BYTES(pi->p_pi, pi->p_pi_len) &&
POKE_END_LLDP_TLV))
goto toobig;
}
#endif
#ifdef ENABLE_DOT3
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_ORG) &&
POKE_BYTES(dot3, sizeof(dot3)) &&
POKE_UINT8(LLDP_TLV_DOT3_LA) &&
POKE_UINT8((port->p_aggregid) ? 3:1) &&
POKE_UINT32(port->p_aggregid) &&
POKE_END_LLDP_TLV))
goto toobig;
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_ORG) &&
POKE_BYTES(dot3, sizeof(dot3)) &&
POKE_UINT8(LLDP_TLV_DOT3_MAC) &&
POKE_UINT8(port->p_macphy.autoneg_support |
(port->p_macphy.autoneg_enabled << 1)) &&
POKE_UINT16(port->p_macphy.autoneg_advertised) &&
POKE_UINT16(port->p_macphy.mau_type) &&
POKE_END_LLDP_TLV))
goto toobig;
if (port->p_mfs) {
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_ORG) &&
POKE_BYTES(dot3, sizeof(dot3)) &&
POKE_UINT8(LLDP_TLV_DOT3_MFS) &&
POKE_UINT16(port->p_mfs) &&
POKE_END_LLDP_TLV))
goto toobig;
}
if (port->p_power.devicetype) {
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_ORG) &&
POKE_BYTES(dot3, sizeof(dot3)) &&
POKE_UINT8(LLDP_TLV_DOT3_POWER) &&
POKE_UINT8((
(((2 - port->p_power.devicetype)    %(1<< 1))<<0) |
(( port->p_power.supported          %(1<< 1))<<1) |
(( port->p_power.enabled            %(1<< 1))<<2) |
(( port->p_power.paircontrol        %(1<< 1))<<3))) &&
POKE_UINT8(port->p_power.pairs) &&
POKE_UINT8(port->p_power.class)))
goto toobig;
if (port->p_power.powertype != LLDP_DOT3_POWER_8023AT_OFF) {
if (!(
POKE_UINT8((
(((port->p_power.powertype ==
LLDP_DOT3_POWER_8023AT_TYPE1)?1:0) << 7) |
(((port->p_power.devicetype ==
LLDP_DOT3_POWER_PSE)?0:1) << 6) |
((port->p_power.source   %(1<< 2))<<4) |
((port->p_power.priority %(1<< 2))<<0))) &&
POKE_UINT16(port->p_power.requested) &&
POKE_UINT16(port->p_power.allocated)))
goto toobig;
}
if (!(POKE_END_LLDP_TLV))
goto toobig;
}
#endif
#ifdef ENABLE_LLDPMED
if (port->p_med_cap_enabled) {
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_ORG) &&
POKE_BYTES(med, sizeof(med)) &&
POKE_UINT8(LLDP_TLV_MED_CAP) &&
POKE_UINT16(chassis->c_med_cap_available) &&
POKE_UINT8(chassis->c_med_type) &&
POKE_END_LLDP_TLV))
goto toobig;
#define LLDP_INVENTORY(value, subtype)\
if (value) {\
if (!(\
POKE_START_LLDP_TLV(LLDP_TLV_ORG) &&\
POKE_BYTES(med, sizeof(med)) &&\
POKE_UINT8(subtype) &&\
POKE_BYTES(value,\
(strlen(value)>32)?32:strlen(value)) &&\
POKE_END_LLDP_TLV))\
goto toobig;\
}
if (port->p_med_cap_enabled & LLDP_MED_CAP_IV) {
LLDP_INVENTORY(chassis->c_med_hw,
LLDP_TLV_MED_IV_HW);
LLDP_INVENTORY(chassis->c_med_fw,
LLDP_TLV_MED_IV_FW);
LLDP_INVENTORY(chassis->c_med_sw,
LLDP_TLV_MED_IV_SW);
LLDP_INVENTORY(chassis->c_med_sn,
LLDP_TLV_MED_IV_SN);
LLDP_INVENTORY(chassis->c_med_manuf,
LLDP_TLV_MED_IV_MANUF);
LLDP_INVENTORY(chassis->c_med_model,
LLDP_TLV_MED_IV_MODEL);
LLDP_INVENTORY(chassis->c_med_asset,
LLDP_TLV_MED_IV_ASSET);
}
for (i = 0; i < LLDP_MED_LOCFORMAT_LAST; i++) {
if (port->p_med_location[i].format == i + 1) {
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_ORG) &&
POKE_BYTES(med, sizeof(med)) &&
POKE_UINT8(LLDP_TLV_MED_LOCATION) &&
POKE_UINT8(port->p_med_location[i].format) &&
POKE_BYTES(port->p_med_location[i].data,
port->p_med_location[i].data_len) &&
POKE_END_LLDP_TLV))
goto toobig;
}
}
for (i = 0; i < LLDP_MED_APPTYPE_LAST; i++) {
if (port->p_med_policy[i].type == i + 1) {
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_ORG) &&
POKE_BYTES(med, sizeof(med)) &&
POKE_UINT8(LLDP_TLV_MED_POLICY) &&
POKE_UINT32((
((port->p_med_policy[i].type     %(1<< 8))<<24) |
((port->p_med_policy[i].unknown  %(1<< 1))<<23) |
((port->p_med_policy[i].tagged   %(1<< 1))<<22) |
((port->p_med_policy[i].vid      %(1<<12))<< 9) |
((port->p_med_policy[i].priority %(1<< 3))<< 6) |
((port->p_med_policy[i].dscp     %(1<< 6))<< 0) )) &&
POKE_END_LLDP_TLV))
goto toobig;
}
}
if ((port->p_med_power.devicetype == LLDP_MED_POW_TYPE_PSE) ||
(port->p_med_power.devicetype == LLDP_MED_POW_TYPE_PD)) {
int devicetype = 0, source = 0;
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_ORG) &&
POKE_BYTES(med, sizeof(med)) &&
POKE_UINT8(LLDP_TLV_MED_MDI)))
goto toobig;
switch (port->p_med_power.devicetype) {
case LLDP_MED_POW_TYPE_PSE:
devicetype = 0;
switch (port->p_med_power.source) {
case LLDP_MED_POW_SOURCE_PRIMARY: source = 1; break;
case LLDP_MED_POW_SOURCE_BACKUP: source = 2; break;
case LLDP_MED_POW_SOURCE_RESERVED: source = 3; break;
default: source = 0; break;
}
break;
case LLDP_MED_POW_TYPE_PD:
devicetype = 1;
switch (port->p_med_power.source) {
case LLDP_MED_POW_SOURCE_PSE: source = 1; break;
case LLDP_MED_POW_SOURCE_LOCAL: source = 2; break;
case LLDP_MED_POW_SOURCE_BOTH: source = 3; break;
default: source = 0; break;
}
break;
}
if (!(
POKE_UINT8((
((devicetype                   %(1<< 2))<<6) |
((source                       %(1<< 2))<<4) |
((port->p_med_power.priority   %(1<< 4))<<0) )) &&
POKE_UINT16(port->p_med_power.val) &&
POKE_END_LLDP_TLV))
goto toobig;
}
}
#endif
#ifdef ENABLE_CUSTOM
TAILQ_FOREACH(custom, &port->p_custom_list, next) {
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_ORG) &&
POKE_BYTES(custom->oui, sizeof(custom->oui)) &&
POKE_UINT8(custom->subtype) &&
POKE_BYTES(custom->oui_info, custom->oui_info_len) &&
POKE_END_LLDP_TLV))
goto toobig;
}
#endif
end:
if (!(
POKE_START_LLDP_TLV(LLDP_TLV_END) &&
POKE_END_LLDP_TLV))
goto toobig;
if (interfaces_send_helper(global, hardware,
(char *)packet, pos - packet) == -1) {
log_warn("lldp", "unable to send packet on real device for %s",
hardware->h_ifname);
free(packet);
return ENETDOWN;
}
hardware->h_tx_cnt++;
if (!shutdown && (frame = (struct lldpd_frame*)malloc(
sizeof(int) + pos - packet)) != NULL) {
frame->size = pos - packet;
memcpy(&frame->frame, packet, frame->size);
if ((hardware->h_lport.p_lastframe == NULL) ||
(hardware->h_lport.p_lastframe->size != frame->size) ||
(memcmp(hardware->h_lport.p_lastframe->frame, frame->frame,
frame->size) != 0)) {
free(hardware->h_lport.p_lastframe);
hardware->h_lport.p_lastframe = frame;
hardware->h_lport.p_lastchange = time(NULL);
} else free(frame);
}
free(packet);
return 0;
toobig:
free(packet);
return E2BIG;
}

static void php_wddx_push_element(void *user_data, const XML_Char *name, const XML_Char **atts)
{
st_entry ent;
wddx_stack *stack = (wddx_stack *)user_data;
if (!strcmp(name, EL_PACKET)) {
int i;
if (atts) for (i=0; atts[i]; i++) {
if (!strcmp(atts[i], EL_VERSION)) {
}
}
} else if (!strcmp(name, EL_STRING)) {
ent.type = ST_STRING;
SET_STACK_VARNAME;
ALLOC_ZVAL(ent.data);
INIT_PZVAL(ent.data);
Z_TYPE_P(ent.data) = IS_STRING;
Z_STRVAL_P(ent.data) = STR_EMPTY_ALLOC();
Z_STRLEN_P(ent.data) = 0;
wddx_stack_push((wddx_stack *)stack, &ent, sizeof(st_entry));
} else if (!strcmp(name, EL_BINARY)) {
ent.type = ST_BINARY;
SET_STACK_VARNAME;
ALLOC_ZVAL(ent.data);
INIT_PZVAL(ent.data);
Z_TYPE_P(ent.data) = IS_STRING;
Z_STRVAL_P(ent.data) = STR_EMPTY_ALLOC();
Z_STRLEN_P(ent.data) = 0;
wddx_stack_push((wddx_stack *)stack, &ent, sizeof(st_entry));
} else if (!strcmp(name, EL_CHAR)) {
int i;
if (atts) for (i = 0; atts[i]; i++) {
if (!strcmp(atts[i], EL_CHAR_CODE) && atts[++i] && atts[i][0]) {
char tmp_buf[2];
snprintf(tmp_buf, sizeof(tmp_buf), "%c", (char)strtol(atts[i], NULL, 16));
php_wddx_process_data(user_data, tmp_buf, strlen(tmp_buf));
break;
}
}
} else if (!strcmp(name, EL_NUMBER)) {
ent.type = ST_NUMBER;
SET_STACK_VARNAME;
ALLOC_ZVAL(ent.data);
INIT_PZVAL(ent.data);
Z_TYPE_P(ent.data) = IS_LONG;
Z_LVAL_P(ent.data) = 0;
wddx_stack_push((wddx_stack *)stack, &ent, sizeof(st_entry));
} else if (!strcmp(name, EL_BOOLEAN)) {
int i;
if (atts) for (i = 0; atts[i]; i++) {
if (!strcmp(atts[i], EL_VALUE) && atts[++i] && atts[i][0]) {
ent.type = ST_BOOLEAN;
SET_STACK_VARNAME;
ALLOC_ZVAL(ent.data);
INIT_PZVAL(ent.data);
Z_TYPE_P(ent.data) = IS_BOOL;
wddx_stack_push((wddx_stack *)stack, &ent, sizeof(st_entry));
php_wddx_process_data(user_data, atts[i], strlen(atts[i]));
break;
}
}
} else if (!strcmp(name, EL_NULL)) {
ent.type = ST_NULL;
SET_STACK_VARNAME;
ALLOC_ZVAL(ent.data);
INIT_PZVAL(ent.data);
ZVAL_NULL(ent.data);
wddx_stack_push((wddx_stack *)stack, &ent, sizeof(st_entry));
} else if (!strcmp(name, EL_ARRAY)) {
ent.type = ST_ARRAY;
SET_STACK_VARNAME;
ALLOC_ZVAL(ent.data);
array_init(ent.data);
INIT_PZVAL(ent.data);
wddx_stack_push((wddx_stack *)stack, &ent, sizeof(st_entry));
} else if (!strcmp(name, EL_STRUCT)) {
ent.type = ST_STRUCT;
SET_STACK_VARNAME;
ALLOC_ZVAL(ent.data);
array_init(ent.data);
INIT_PZVAL(ent.data);
wddx_stack_push((wddx_stack *)stack, &ent, sizeof(st_entry));
} else if (!strcmp(name, EL_VAR)) {
int i;
if (atts) for (i = 0; atts[i]; i++) {
if (!strcmp(atts[i], EL_NAME) && atts[++i] && atts[i][0]) {
if (stack->varname) efree(stack->varname);
stack->varname = estrdup(atts[i]);
break;
}
}
} else if (!strcmp(name, EL_RECORDSET)) {
int i;
ent.type = ST_RECORDSET;
SET_STACK_VARNAME;
MAKE_STD_ZVAL(ent.data);
array_init(ent.data);
if (atts) for (i = 0; atts[i]; i++) {
if (!strcmp(atts[i], "fieldNames") && atts[++i] && atts[i][0]) {
zval *tmp;
char *key;
char *p1, *p2, *endp;
endp = (char *)atts[i] + strlen(atts[i]);
p1 = (char *)atts[i];
while ((p2 = php_memnstr(p1, ",", sizeof(",")-1, endp)) != NULL) {
key = estrndup(p1, p2 - p1);
MAKE_STD_ZVAL(tmp);
array_init(tmp);
add_assoc_zval_ex(ent.data, key, p2 - p1 + 1, tmp);
p1 = p2 + sizeof(",")-1;
efree(key);
}
if (p1 <= endp) {
MAKE_STD_ZVAL(tmp);
array_init(tmp);
add_assoc_zval_ex(ent.data, p1, endp - p1 + 1, tmp);
}
break;
}
}
wddx_stack_push((wddx_stack *)stack, &ent, sizeof(st_entry));
} else if (!strcmp(name, EL_FIELD)) {
int i;
st_entry ent;
ent.type = ST_FIELD;
ent.varname = NULL;
ent.data = NULL;
if (atts) for (i = 0; atts[i]; i++) {
if (!strcmp(atts[i], EL_NAME) && atts[++i] && atts[i][0]) {
st_entry *recordset;
zval **field;
if (wddx_stack_top(stack, (void**)&recordset) == SUCCESS &&
recordset->type == ST_RECORDSET &&
zend_hash_find(Z_ARRVAL_P(recordset->data), (char*)atts[i], strlen(atts[i])+1, (void**)&field) == SUCCESS) {
ent.data = *field;
}
break;
}
}
wddx_stack_push((wddx_stack *)stack, &ent, sizeof(st_entry));
} else if (!strcmp(name, EL_DATETIME)) {
ent.type = ST_DATETIME;
SET_STACK_VARNAME;
ALLOC_ZVAL(ent.data);
INIT_PZVAL(ent.data);
Z_TYPE_P(ent.data) = IS_LONG;
wddx_stack_push((wddx_stack *)stack, &ent, sizeof(st_entry));
}
}

GF_Err naludmx_set_hevc_oinf(GF_NALUDmxCtx *ctx, u8 *max_temporal_id)
{
GF_OperatingPointsInformation *oinf;
GF_BitStream *bs;
u8 *data;
u32 data_size;
u32 i;
HEVC_VPS *vps;
GF_NALUFFParam *vps_sl = gf_list_get(ctx->vps, 0);
if (!vps_sl) return GF_SERVICE_ERROR;
vps = &ctx->hevc_state->vps[vps_sl->id];
if (!vps->vps_extension_found) return GF_OK;
if (vps->max_layers<2) return GF_OK;
oinf = gf_isom_oinf_new_entry();
if (!oinf) return GF_OUT_OF_MEM;
oinf->scalability_mask = 0;
for (i = 0; i < 16; i++) {
if (vps->scalability_mask[i])
oinf->scalability_mask |= 1 << i;
}
for (i = 0; i < vps->num_profile_tier_level; i++) {
HEVC_ProfileTierLevel ptl = (i == 0) ? vps->ptl : vps->ext_ptl[i-1];
LHEVC_ProfileTierLevel *lhevc_ptl;
GF_SAFEALLOC(lhevc_ptl, LHEVC_ProfileTierLevel);
if (!lhevc_ptl) return GF_OUT_OF_MEM;
lhevc_ptl->general_profile_space = ptl.profile_space;
lhevc_ptl->general_tier_flag = ptl.tier_flag;
lhevc_ptl->general_profile_idc = ptl.profile_idc;
lhevc_ptl->general_profile_compatibility_flags = ptl.profile_compatibility_flag;
lhevc_ptl->general_constraint_indicator_flags = 0;
if (ptl.general_progressive_source_flag)
lhevc_ptl->general_constraint_indicator_flags |= ((u64)1) << 47;
if (ptl.general_interlaced_source_flag)
lhevc_ptl->general_constraint_indicator_flags |= ((u64)1) << 46;
if (ptl.general_non_packed_constraint_flag)
lhevc_ptl->general_constraint_indicator_flags |= ((u64)1) << 45;
if (ptl.general_frame_only_constraint_flag)
lhevc_ptl->general_constraint_indicator_flags |= ((u64)1) << 44;
lhevc_ptl->general_constraint_indicator_flags |= ptl.general_reserved_44bits;
lhevc_ptl->general_level_idc = ptl.level_idc;
gf_list_add(oinf->profile_tier_levels, lhevc_ptl);
}
for (i = 0; i < vps->num_output_layer_sets; i++) {
LHEVC_OperatingPoint *op;
u32 j;
u16 minPicWidth, minPicHeight, maxPicWidth, maxPicHeight;
u8 maxChromaFormat, maxBitDepth;
u8 maxTemporalId;
GF_SAFEALLOC(op, LHEVC_OperatingPoint);
if (!op) return GF_OUT_OF_MEM;
op->output_layer_set_idx = i;
op->layer_count = vps->num_necessary_layers[i];
minPicWidth = minPicHeight = maxPicWidth = maxPicHeight = maxTemporalId = 0;
maxChromaFormat = maxBitDepth = 0;
for (j = 0; j < op->layer_count; j++) {
u32 format_idx;
u32 bitDepth;
op->layers_info[j].ptl_idx = vps->profile_tier_level_idx[i][j];
op->layers_info[j].layer_id = j;
op->layers_info[j].is_outputlayer = vps->output_layer_flag[i][j];
op->layers_info[j].is_alternate_outputlayer = GF_FALSE;
if (max_temporal_id) {
if (!maxTemporalId || (maxTemporalId < max_temporal_id[op->layers_info[j].layer_id]))
maxTemporalId = max_temporal_id[op->layers_info[j].layer_id];
} else {
maxTemporalId = vps->max_sub_layers;
}
format_idx = vps->rep_format_idx[op->layers_info[j].layer_id];
if (!minPicWidth || (minPicWidth > vps->rep_formats[format_idx].pic_width_luma_samples))
minPicWidth = vps->rep_formats[format_idx].pic_width_luma_samples;
if (!minPicHeight || (minPicHeight > vps->rep_formats[format_idx].pic_height_luma_samples))
minPicHeight = vps->rep_formats[format_idx].pic_height_luma_samples;
if (!maxPicWidth || (maxPicWidth < vps->rep_formats[format_idx].pic_width_luma_samples))
maxPicWidth = vps->rep_formats[format_idx].pic_width_luma_samples;
if (!maxPicHeight || (maxPicHeight < vps->rep_formats[format_idx].pic_height_luma_samples))
maxPicHeight = vps->rep_formats[format_idx].pic_height_luma_samples;
if (!maxChromaFormat || (maxChromaFormat < vps->rep_formats[format_idx].chroma_format_idc))
maxChromaFormat = vps->rep_formats[format_idx].chroma_format_idc;
bitDepth = vps->rep_formats[format_idx].bit_depth_chroma > vps->rep_formats[format_idx].bit_depth_luma ? vps->rep_formats[format_idx].bit_depth_chroma : vps->rep_formats[format_idx].bit_depth_luma;
if (!maxChromaFormat || (maxChromaFormat < bitDepth))
maxChromaFormat = bitDepth;
}
op->max_temporal_id = maxTemporalId;
op->minPicWidth = minPicWidth;
op->minPicHeight = minPicHeight;
op->maxPicWidth = maxPicWidth;
op->maxPicHeight = maxPicHeight;
op->maxChromaFormat = maxChromaFormat;
op->maxBitDepth = maxBitDepth;
op->frame_rate_info_flag = GF_FALSE; op->bit_rate_info_flag = GF_FALSE; gf_list_add(oinf->operating_points, op);
}
for (i = 0; i < vps->max_layers; i++) {
LHEVC_DependentLayer *dep;
u32 j, k;
GF_SAFEALLOC(dep, LHEVC_DependentLayer);
if (!dep) return GF_OUT_OF_MEM;
dep->dependent_layerID = vps->layer_id_in_nuh[i];
for (j = 0; j < vps->max_layers; j++) {
if (vps->direct_dependency_flag[dep->dependent_layerID][j]) {
dep->dependent_on_layerID[dep->num_layers_dependent_on] = j;
dep->num_layers_dependent_on ++;
}
}
k = 0;
for (j = 0; j < 16; j++) {
if (oinf->scalability_mask & (1 << j)) {
dep->dimension_identifier[j] = vps->dimension_id[i][k];
k++;
}
}
gf_list_add(oinf->dependency_layers, dep);
}
bs = gf_bs_new(NULL, 0, GF_BITSTREAM_WRITE);
gf_isom_oinf_write_entry(oinf, bs);
gf_bs_get_content(bs, &data, &data_size);
gf_bs_del(bs);
gf_isom_oinf_del_entry(oinf);
gf_filter_pid_set_info_str(ctx->opid, "hevc:oinf", &PROP_DATA_NO_COPY(data, data_size) );
return GF_OK;
}

static int tower_probe (struct usb_interface *interface, const struct usb_device_id *id)
{
struct device *idev = &interface->dev;
struct usb_device *udev = interface_to_usbdev(interface);
struct lego_usb_tower *dev = NULL;
struct usb_host_interface *iface_desc;
struct usb_endpoint_descriptor* endpoint;
struct tower_get_version_reply get_version_reply;
int i;
int retval = -ENOMEM;
int result;
dev = kmalloc (sizeof(struct lego_usb_tower), GFP_KERNEL);
if (!dev)
goto exit;
mutex_init(&dev->lock);
dev->udev = udev;
dev->open_count = 0;
dev->read_buffer = NULL;
dev->read_buffer_length = 0;
dev->read_packet_length = 0;
spin_lock_init (&dev->read_buffer_lock);
dev->packet_timeout_jiffies = msecs_to_jiffies(packet_timeout);
dev->read_last_arrival = jiffies;
init_waitqueue_head (&dev->read_wait);
init_waitqueue_head (&dev->write_wait);
dev->interrupt_in_buffer = NULL;
dev->interrupt_in_endpoint = NULL;
dev->interrupt_in_urb = NULL;
dev->interrupt_in_running = 0;
dev->interrupt_in_done = 0;
dev->interrupt_out_buffer = NULL;
dev->interrupt_out_endpoint = NULL;
dev->interrupt_out_urb = NULL;
dev->interrupt_out_busy = 0;
iface_desc = interface->cur_altsetting;
for (i = 0; i < iface_desc->desc.bNumEndpoints; ++i) {
endpoint = &iface_desc->endpoint[i].desc;
if (usb_endpoint_xfer_int(endpoint)) {
if (usb_endpoint_dir_in(endpoint))
dev->interrupt_in_endpoint = endpoint;
else
dev->interrupt_out_endpoint = endpoint;
}
}
if(dev->interrupt_in_endpoint == NULL) {
dev_err(idev, "interrupt in endpoint not found\n");
goto error;
}
if (dev->interrupt_out_endpoint == NULL) {
dev_err(idev, "interrupt out endpoint not found\n");
goto error;
}
dev->read_buffer = kmalloc (read_buffer_size, GFP_KERNEL);
if (!dev->read_buffer)
goto error;
dev->interrupt_in_buffer = kmalloc (usb_endpoint_maxp(dev->interrupt_in_endpoint), GFP_KERNEL);
if (!dev->interrupt_in_buffer)
goto error;
dev->interrupt_in_urb = usb_alloc_urb(0, GFP_KERNEL);
if (!dev->interrupt_in_urb)
goto error;
dev->interrupt_out_buffer = kmalloc (write_buffer_size, GFP_KERNEL);
if (!dev->interrupt_out_buffer)
goto error;
dev->interrupt_out_urb = usb_alloc_urb(0, GFP_KERNEL);
if (!dev->interrupt_out_urb)
goto error;
dev->interrupt_in_interval = interrupt_in_interval ? interrupt_in_interval : dev->interrupt_in_endpoint->bInterval;
dev->interrupt_out_interval = interrupt_out_interval ? interrupt_out_interval : dev->interrupt_out_endpoint->bInterval;
usb_set_intfdata (interface, dev);
retval = usb_register_dev (interface, &tower_class);
if (retval) {
dev_err(idev, "Not able to get a minor for this device.\n");
usb_set_intfdata (interface, NULL);
goto error;
}
dev->minor = interface->minor;
dev_info(&interface->dev, "LEGO USB Tower #%d now attached to major "
"%d minor %d\n", (dev->minor - LEGO_USB_TOWER_MINOR_BASE),
USB_MAJOR, dev->minor);
result = usb_control_msg (udev,
usb_rcvctrlpipe(udev, 0),
LEGO_USB_TOWER_REQUEST_GET_VERSION,
USB_TYPE_VENDOR | USB_DIR_IN | USB_RECIP_DEVICE,
0,
0,
&get_version_reply,
sizeof(get_version_reply),
1000);
if (result < 0) {
dev_err(idev, "LEGO USB Tower get version control request failed\n");
retval = result;
goto error;
}
dev_info(&interface->dev, "LEGO USB Tower firmware version is %d.%d "
"build %d\n", get_version_reply.major,
get_version_reply.minor,
le16_to_cpu(get_version_reply.build_no));
exit:
return retval;
error:
tower_delete(dev);
return retval;
}

char *LibRaw_buffer_datastream::gets(char *s, int sz)
{
unsigned char *psrc, *pdest, *str;
str = (unsigned char *)s;
psrc = buf + streampos;
pdest = str;
if(streampos >= streamsize) return NULL;
while ((size_t(psrc - buf) < streamsize) && ((pdest - str) < (sz-1)))
{
*pdest = *psrc;
if (*psrc == '\n')
break;
psrc++;
pdest++;
}
if (size_t(psrc - buf) < streamsize)
psrc++;
if ((pdest - str) < sz-1)
*(++pdest) = 0;
else
s[sz - 1] = 0; 
streampos = psrc - buf;
return s;
}

static void parse_media(pj_scanner *scanner, pjmedia_sdp_media *med,
volatile parse_context *ctx)
{
pj_str_t str;
ctx->last_error = PJMEDIA_SDP_EINMEDIA;
if (*(scanner->curptr+1) != '=') {
on_scanner_error(scanner);
return;
}
pj_scan_advance_n(scanner, 2, SKIP_WS);
pj_scan_get_until_ch(scanner, ' ', &med->desc.media);
pj_scan_get_char(scanner);
pj_scan_get(scanner, &cs_token, &str);
med->desc.port = (unsigned short)pj_strtoul(&str);
if (*scanner->curptr == '/') {
pj_scan_get_char(scanner);
pj_scan_get(scanner, &cs_token, &str);
med->desc.port_count = pj_strtoul(&str);
} else {
med->desc.port_count = 0;
}
if (pj_scan_get_char(scanner) != ' ') {
PJ_THROW(SYNTAX_ERROR);
}
pj_scan_get_until_chr(scanner, " \t\r\n", &med->desc.transport);
med->desc.fmt_count = 0;
while (*scanner->curptr == ' ') {
pj_str_t fmt;
pj_scan_get_char(scanner);
if ((*scanner->curptr == '\r') || (*scanner->curptr == '\n'))
break;
pj_scan_get(scanner, &cs_token, &fmt);
if (med->desc.fmt_count < PJMEDIA_MAX_SDP_FMT)
med->desc.fmt[med->desc.fmt_count++] = fmt;
else
PJ_PERROR(2,(THIS_FILE, PJ_ETOOMANY, 
"Error adding SDP media format %.*s, "
"format is ignored",
(int)fmt.slen, fmt.ptr));
}
pj_scan_skip_line(scanner);
}

static void *stbi__gif_load(stbi__context *s, int *x, int *y, int *comp, int req_comp, stbi__result_info *ri)
{
stbi_uc *u = 0;
stbi__gif g;
memset(&g, 0, sizeof(g));
STBI_NOTUSED(ri);
u = stbi__gif_load_next(s, &g, comp, req_comp, 0);
if (u == (stbi_uc *) s) u = 0;     if (u) {
*x = g.w;
*y = g.h;
if (req_comp && req_comp != 4)
u = stbi__convert_format(u, 4, req_comp, g.w, g.h);
}
STBI_FREE(g.history);
STBI_FREE(g.background); 
return u;
}

