const char *dep_representation_id;
const char *dep_representation_file = NULL;
GF_ESD* esd = NULL;
strcpy(dash_input->szMime, "video/mp4");
dash_input->dasher_create_init_segment = dasher_isom_create_init_segment;
dash_input->dasher_input_classify = dasher_isom_classify_input;
dash_input->dasher_get_components_info = dasher_isom_get_components_info;
dash_input->dasher_segment_file = dasher_isom_segment_file;
file = gf_isom_open(dash_input->file_name, GF_ISOM_OPEN_READ, NULL);
if (!file) return gf_isom_last_error(NULL);
nb_track = gf_isom_get_track_count(file);
if ((nb_track == 1) || !gf_isom_needs_layer_reconstruction(file)) {
u32 track_num = nb_track;
if (uri_frag) {
u32 id = 0;
if (!strnicmp(uri_frag+1, "trackID=", 8))
id = atoi(uri_frag+9);
else if (!strnicmp(uri_frag+1, "ID=", 3))
id = atoi(uri_frag+4);
else if (!stricmp(uri_frag+1, "audio") || !stricmp(uri_frag+1, "video")) {
Bool check_video = !stricmp(uri_frag+1, "video") ? GF_TRUE : GF_FALSE;
Bool check_auxv = !stricmp(uri_frag+1, "auxv") ? GF_TRUE : GF_FALSE;
Bool check_pict = !stricmp(uri_frag+1, "pict") ? GF_TRUE : GF_FALSE;
u32 i;
for (i=0; i<nb_track; i++) {
switch (gf_isom_get_media_type(file, i+1)) {
case GF_ISOM_MEDIA_AUXV:
if (check_auxv) id = gf_isom_get_track_id(file, i+1);
break;
case GF_ISOM_MEDIA_PICT:
if (check_pict) id = gf_isom_get_track_id(file, i+1);
break;
case GF_ISOM_MEDIA_VISUAL:
if (check_video) id = gf_isom_get_track_id(file, i+1);
break;
case GF_ISOM_MEDIA_AUDIO:
if (!check_video) id = gf_isom_get_track_id(file, i+1);
break;
}
if (id) break;
}
}
dash_input->single_track_num = gf_isom_get_track_by_id(file, id);
track_num = dash_input->single_track_num;
if (nb_track==1) dash_input->single_track_num = 0;
}
dash_input->protection_scheme_type = gf_isom_is_media_encrypted(file, track_num, 0);
#if !defined(GPAC_DISABLE_AV_PARSERS) && !defined(GPAC_DISABLE_HEVC)
for (j = 0; j < nb_track; j++) {
esd = gf_isom_get_esd(file, j+1, 1);
if (esd && (esd->decoderConfig->objectTypeIndication == GPAC_OTI_VIDEO_HEVC || esd->decoderConfig->objectTypeIndication == GPAC_OTI_VIDEO_LHVC)) {
GF_HEVCConfig* hevccfg = gf_isom_hevc_config_get(file, j+1, 1);
if (hevccfg) {
HEVCState hevc;
HEVC_SPS* sps = NULL;
memset(&hevc, 0, sizeof(HEVCState));
gf_media_hevc_parse_ps(hevccfg, &hevc, GF_HEVC_NALU_VID_PARAM);
gf_media_hevc_parse_ps(hevccfg, &hevc, GF_HEVC_NALU_SEQ_PARAM);
sps = &hevc.sps[hevc.sps_active_idx];
if (sps && sps->colour_description_present_flag) {
if (sps->colour_primaries == 9 && sps->matrix_coeffs == 9) {
if (sps->transfer_characteristic == 14) dash_input->isHdrHlg = GF_TRUE; if (sps->transfer_characteristic == 16) dash_input->isHdrPq10 = GF_TRUE;
}
}
gf_odf_hevc_cfg_del(hevccfg);
}
}
gf_odf_desc_del((GF_Descriptor*)esd);
}
#endif
dash_input->moof_seqnum_increase = 0;
gf_isom_close(file);
return GF_OK;
}
max_nb_deps = 0;
for (j = 0; j < nb_track; j++) {
u32 mtype = gf_isom_get_media_type(file, j+1);
if (gf_isom_is_video_subtype(mtype) ) {
u32 c1 = gf_isom_get_reference_count(file, j+1, GF_ISOM_REF_BASE);
u32 c2 = gf_isom_get_reference_count(file, j+1, GF_ISOM_REF_TBAS);
if (c2) has_tiling = GF_TRUE;
if (c1 + c2) {
max_nb_deps ++;
}
}
}
#ifdef GENERATE_VIRTUAL_REP_SRD
if (has_tiling) max_nb_deps++;
#endif
j = *nb_dash_inputs + max_nb_deps;
dash_inputs = (GF_DashSegInput*)gf_realloc(dash_inputs, sizeof(GF_DashSegInput) * j);
memset(&dash_inputs[*nb_dash_inputs], 0, sizeof(GF_DashSegInput) * max_nb_deps);
(*io_dash_inputs) = dash_inputs;
dash_input = & dash_inputs[idx];
dash_input->nb_representations = 1 + max_nb_deps;
dash_input->idx_representations=0;
rep_idx = 1;
cur_idx = idx+1;
dep_representation_id = dash_input->representationID;
for (j = 0; j < nb_track; j++) {
u32 default_sample_group_index, id, independent;
Bool full_frame;
GF_DashSegInput *di;
u32 count = gf_isom_get_reference_count(file, j+1, GF_ISOM_REF_BASE);
count += gf_isom_get_reference_count(file, j+1, GF_ISOM_REF_TBAS);
if (!count) {
u32 x, y, w, h;
Bool found_same_base = GF_FALSE;
count = gf_isom_get_reference_count(file, j+1, GF_ISOM_REF_SABT);
count += gf_isom_get_reference_count(file, j+1, GF_ISOM_REF_SCAL);
if (!count) {
switch (gf_isom_get_media_subtype(file, j+1, 1)) {
case GF_ISOM_SUBTYPE_LHE1:
case GF_ISOM_SUBTYPE_LHV1:
case GF_ISOM_SUBTYPE_HEV2:
case GF_ISOM_SUBTYPE_HVC2:
count = gf_isom_get_reference_count(file, j+1, GF_ISOM_REF_BASE);
break;
}
}
if (!has_tiling || !count) {
dash_input->trackNum = j+1;
continue;
}
w = h = 0;
gf_isom_get_tile_info(file, j+1, 1, &default_sample_group_index, &id, &independent, &full_frame, &x, &y, &w, &h);
if (!w && !h) {
gf_isom_get_visual_info(file, j+1, 1, &w, &h);
x = y = 0;
}
for (k=0; k<idx; k++) {
GF_DashSegInput *prev_dash_input = & dash_inputs[k];
if ( (prev_dash_input->x==x) && (prev_dash_input->y==y) && (prev_dash_input->w==w) && (prev_dash_input->h==h) ) {
GF_ISOFile *temp = gf_isom_open(prev_dash_input->file_name, GF_ISOM_OPEN_READ, NULL);
if (gf_isom_is_same_sample_description(file, j+1, 1, temp, prev_dash_input->trackNum, 1)) {
found_same_base = GF_TRUE;
dep_representation_id = prev_dash_input->representationID;
dep_representation_file=prev_dash_input->file_name;
}
gf_isom_delete(temp);
if (found_same_base) break;
}
}
if (found_same_base) {
cur_idx --;
(*nb_dash_inputs) --;
continue;
}
dash_input->trackNum = j+1;
continue;
}
di = &dash_inputs [cur_idx];
*nb_dash_inputs += 1;
cur_idx++;
memcpy(di, dash_input, sizeof(GF_DashSegInput));
snprintf(di->representationID, sizeof(di->representationID), "%s_%u", dep_representation_id, cur_idx);
di->trackNum = j+1;
di->protection_scheme_type = gf_isom_is_media_encrypted(file, di->trackNum, 0);
di->idx_representations = rep_idx;
rep_idx ++;
if (gf_isom_get_reference_count(file, di->trackNum, GF_ISOM_REF_TBAS)) {
gf_isom_get_tile_info(file, di->trackNum, 1, &default_sample_group_index, &id, &independent, &full_frame, &di->x, &di->y, &di->w, &di->h);
if (!dash_input->w) {
gf_isom_get_visual_info(file, dash_input->trackNum, 1, &dash_input->w, &dash_input->h);
}
}
}
#ifdef GENERATE_VIRTUAL_REP_SRD
if (has_tiling) {
GF_DashSegInput *di = &dash_inputs [cur_idx];
*nb_dash_inputs += 1;
cur_idx++;
memcpy(di, dash_input, sizeof(GF_DashSegInput));
sprintf(di->representationID, "%s_%d", dep_representation_id, cur_idx);
di->trackNum = 0;
for (k = 0; k < nb_track; k++) {
u32 mtype = gf_isom_get_media_type(file, k+1);
if (gf_isom_is_video_subtype(mtype) ) {
if (gf_isom_get_reference_count(file, k+1, GF_ISOM_REF_SABT)) {
di->trackNum = k+1;
break;
}
}
}
di->protection_scheme_type = gf_isom_is_media_encrypted(file, di->trackNum, 0);
di->idx_representations = rep_idx;
rep_idx ++;
di->virtual_representation = GF_TRUE;
}
#endif
for (k=0; k<2; k++) {
for (j = idx; j < *nb_dash_inputs; j++) {
GF_DashSegInput *di;
u32 count, t, ref_track;
char *depID = NULL;
u32 dep_type;
di = &dash_inputs[j];
if (di->dependencyID) continue;
#ifdef GENERATE_VIRTUAL_REP_SRD
if (k==1) dep_type = (di->virtual_representation) ? GF_ISOM_REF_SABT : GF_ISOM_REF_TBAS;
#else
if (k==1) dep_type = GF_ISOM_REF_TBAS;
#endif
else dep_type = GF_ISOM_REF_SCAL;
count = gf_isom_get_reference_count(file, di->trackNum, dep_type);
if (!count) {
if (k==1) {
switch (gf_isom_get_media_subtype(file, j+1, 1)) {
case GF_ISOM_SUBTYPE_LHE1:
case GF_ISOM_SUBTYPE_LHV1:
case GF_ISOM_SUBTYPE_HEV2:
case GF_ISOM_SUBTYPE_HVC2:
dep_type = GF_ISOM_REF_BASE;
count = gf_isom_get_reference_count(file, j+1, GF_ISOM_REF_BASE);
break;
}
}
if (!count)
continue;
}
di->lower_layer_track = dash_input->trackNum;
depID = (char*)gf_malloc(2);
strcpy(depID, "");
for (t=0; t < count; t++) {
u32 al_len = 0;
char *rid;
if (t) al_len++;
gf_isom_get_reference(file, di->trackNum, dep_type, t+1, &ref_track);
rid = gf_dash_get_representationID(dash_inputs, *nb_dash_inputs, dep_representation_file ? dep_representation_file : di->file_name, ref_track);
if (!rid) continue;
al_len += (u32) strlen(rid);
al_len += (u32) strlen(depID)+1;
depID = (char*)gf_realloc(depID, sizeof(char)*al_len);
if (t)
strcat(depID, " ");
strcat(depID, rid);
di->lower_layer_track = ref_track;
}
if (di->dependencyID) gf_free(di->dependencyID);
di->dependencyID = depID;
}
}
gf_isom_close(file);
return GF_OK;
}
#endif 
dash_input->moof_seqnum_increase = 0;
#ifndef GPAC_DISABLE_MPEG2TS
if (gf_m2ts_probe_file(dash_input->file_name)) {
GF_TSSegmenter ts_seg;
u32 count = 0;
GF_Err e = dasher_get_ts_demux(&ts_seg, dash_input->file_name, 1);
if (e) return e;
count = gf_list_count(ts_seg.ts->programs);
dasher_del_ts_demux(&ts_seg);
if (count>1) {
GF_LOG(GF_LOG_ERROR, GF_LOG_DASH, ("[DASH] MPEG-2 TS file %s has several programs - this is not supported in MPEG-DASH - skipping\n", dash_input->file_name));
return GF_NOT_SUPPORTED;
}
strcpy(dash_input->szMime, "video/mp2t");
dash_input->dasher_create_init_segment = NULL;
dash_input->dasher_input_classify = dasher_generic_classify_input;
dash_input->dasher_get_components_info = dasher_mp2t_get_components_info;
dash_input->dasher_segment_file = dasher_mp2t_segment_file;
return GF_OK;
}
#endif
GF_LOG(GF_LOG_ERROR, GF_LOG_DASH, ("[DASH] File %s not supported for dashing - skipping\n", dash_input->file_name));
return GF_NOT_SUPPORTED;
}

void
parseSWF_MORPHGRADIENT (FILE * f, struct SWF_MORPHGRADIENT *gradient)
{
int i;
gradient->NumGradients = readUInt8 (f);
if( gradient->NumGradients > 8 ) {
fprintf(stderr, "%d gradients in SWF_MORPHGRADiENT, expected a max of 8", gradient->NumGradients);
}
for (i = 0; i < gradient->NumGradients; i++)
parseSWF_MORPHGRADIENTRECORD (f, &(gradient->GradientRecords[i]));
}

void CLASS kodak_c603_load_raw()
{
uchar *pixel;
int row, col, y, cb, cr, rgb[3], c;
pixel = (uchar *)calloc(raw_width, 3 * sizeof *pixel);
merror(pixel, "kodak_c603_load_raw()");
#ifdef LIBRAW_LIBRARY_BUILD
try
{
#endif
for (row = 0; row < height; row++)
{
#ifdef LIBRAW_LIBRARY_BUILD
checkCancel();
#endif
if (~row & 1)
if (fread(pixel, raw_width, 3, ifp) < 3)
derror();
for (col = 0; col < width; col++)
{
y = pixel[width * 2 * (row & 1) + col];
cb = pixel[width + (col & -2)] - 128;
cr = pixel[width + (col & -2) + 1] - 128;
rgb[1] = y - ((cb + cr + 2) >> 2);
rgb[2] = rgb[1] + cb;
rgb[0] = rgb[1] + cr;
FORC3 image[row * width + col][c] = curve[LIM(rgb[c], 0, 255)];
}
}
#ifdef LIBRAW_LIBRARY_BUILD
}
catch (...)
{
free(pixel);
throw;
}
#endif
free(pixel);
maximum = curve[0xff];
}

Status QuantizeV2Shape(InferenceContext* c) {
int axis = -1;
Status s = c->GetAttr("axis", &axis);
if (!s.ok() && s.code() != error::NOT_FOUND) {
return s;
}
const int minmax_rank = (axis == -1) ? 0 : 1;
TF_RETURN_IF_ERROR(shape_inference::UnchangedShape(c));
ShapeHandle minmax;
TF_RETURN_IF_ERROR(c->WithRank(c->input(1), minmax_rank, &minmax));
TF_RETURN_IF_ERROR(c->WithRank(c->input(2), minmax_rank, &minmax));
if (axis != -1) {
ShapeHandle input;
TF_RETURN_IF_ERROR(c->WithRankAtLeast(c->input(0), axis + 1, &input));
DimensionHandle depth;
TF_RETURN_IF_ERROR(
c->Merge(c->Dim(minmax, 0), c->Dim(input, axis), &depth));
}
c->set_output(1, minmax);
c->set_output(2, minmax);
return Status::OK();
}

static void balloon_process(struct work_struct *work)
{
enum bp_state state = BP_DONE;
long credit;
do {
mutex_lock(&balloon_mutex);
credit = current_credit();
if (credit > 0) {
if (balloon_is_inflated())
state = increase_reservation(credit);
else
state = reserve_additional_memory();
}
if (credit < 0)
state = decrease_reservation(-credit, GFP_BALLOON);
state = update_schedule(state);
mutex_unlock(&balloon_mutex);
cond_resched();
} while (credit && state == BP_DONE);
if (state == BP_EAGAIN)
schedule_delayed_work(&balloon_worker, balloon_stats.schedule_delay * HZ);
}

struct mtk_vcodec_fw *mtk_vcodec_fw_vpu_init(struct mtk_vcodec_dev *dev,
enum mtk_vcodec_fw_use fw_use)
{
struct platform_device *fw_pdev;
struct mtk_vcodec_fw *fw;
enum rst_id rst_id;
switch (fw_use) {
case ENCODER:
rst_id = VPU_RST_ENC;
break;
case DECODER:
default:
rst_id = VPU_RST_DEC;
break;
}
fw_pdev = vpu_get_plat_device(dev->plat_dev);
if (!fw_pdev) {
mtk_v4l2_err("firmware device is not ready");
return ERR_PTR(-EINVAL);
}
vpu_wdt_reg_handler(fw_pdev, mtk_vcodec_vpu_reset_handler, dev, rst_id);
fw = devm_kzalloc(&dev->plat_dev->dev, sizeof(*fw), GFP_KERNEL);
fw->type = VPU;
fw->ops = &mtk_vcodec_vpu_msg;
fw->pdev = fw_pdev;
return fw;
}

int seq_buf_putmem_hex(struct seq_buf *s, const void *mem,
unsigned int len)
{
unsigned char hex[HEX_CHARS];
const unsigned char *data = mem;
unsigned int start_len;
int i, j;
WARN_ON(s->size == 0);
while (len) {
start_len = min(len, HEX_CHARS - 1);
#ifdef __BIG_ENDIAN
for (i = 0, j = 0; i < start_len; i++) {
#else
for (i = start_len-1, j = 0; i >= 0; i--) {
#endif
hex[j++] = hex_asc_hi(data[i]);
hex[j++] = hex_asc_lo(data[i]);
}
if (WARN_ON_ONCE(j == 0 || j/2 > len))
break;
len -= j / 2;
hex[j++] = ' ';
seq_buf_putmem(s, hex, j);
if (seq_buf_has_overflowed(s))
return -1;
}
return 0;
}

void Compute(OpKernelContext* context) override {
const Tensor& input_sizes = context->input(0);
const Tensor& filter = context->input(1);
const Tensor& out_backprop = context->input(2);
TensorShape input_shape;
OP_REQUIRES_OK(context,
Conv2DBackpropComputeInputShape(input_sizes, filter.shape(),
out_backprop.shape(),
data_format_, &input_shape));
ConvBackpropDimensions dims;
OP_REQUIRES_OK(context,
ConvBackpropComputeDimensionsV2(
"Conv2DCustomBackpropInput", 2,
input_shape, filter.shape(), out_backprop.shape(),
{1, 1, 1, 1}, strides_, padding_,
explicit_paddings_, data_format_, &dims));
OP_REQUIRES(context, dims.in_depth == filter.shape().dim_size(2),
errors::InvalidArgument("Computed input depth ", dims.in_depth,
" doesn't match filter input depth ",
filter.shape().dim_size(2)));
OP_REQUIRES(
context, dims.out_depth == filter.shape().dim_size(3),
errors::InvalidArgument("Computed output depth ", dims.out_depth,
" doesn't match filter output depth ",
filter.shape().dim_size(3)));
Tensor* in_backprop = nullptr;
OP_REQUIRES_OK(context,
context->allocate_output(0, input_shape, &in_backprop));
if (input_shape.num_elements() == 0) {
return;
}
#if defined TENSORFLOW_USE_LIBXSMM_CONVOLUTIONS && \
defined TENSORFLOW_USE_LIBXSMM_BACKWARD_CONVOLUTIONS
int64 pad_top, pad_bottom;
int64 pad_left, pad_right;
OP_REQUIRES_OK(
context,
GetWindowedOutputSizeVerbose(
dims.spatial_dims[0].input_size, dims.spatial_dims[0].filter_size,
dims.spatial_dims[0].stride, padding_,
&dims.spatial_dims[0].output_size, &pad_top, &pad_bottom));
OP_REQUIRES_OK(
context,
GetWindowedOutputSizeVerbose(
dims.spatial_dims[1].input_size, dims.spatial_dims[1].filter_size,
dims.spatial_dims[1].stride, padding_,
&dims.spatial_dims[1].output_size, &pad_left, &pad_right));
if (pad_left == pad_right && pad_top == pad_bottom) {
if (LaunchXsmmBackwardInputConvolution<Device, T>()(
context, context->eigen_device<Device>(),
in_backprop->tensor<T, 4>(), filter.tensor<T, 4>(),
out_backprop.tensor<T, 4>(), dims.spatial_dims[0].input_size,
dims.spatial_dims[1].input_size,
static_cast<int>(dims.spatial_dims[0].stride),
static_cast<int>(dims.spatial_dims[1].stride),
static_cast<int>(pad_top), static_cast<int>(pad_left),
data_format_)) {
return;
}
}
#else
int64 pad_top, pad_bottom;
int64 pad_left, pad_right;
#endif
if (padding_ == Padding::EXPLICIT) {
pad_top = explicit_paddings_[2];
pad_bottom = explicit_paddings_[3];
pad_left = explicit_paddings_[4];
pad_right = explicit_paddings_[5];
}
OP_REQUIRES_OK(
context,
GetWindowedOutputSizeVerbose(
dims.spatial_dims[0].input_size, dims.spatial_dims[0].filter_size,
dims.spatial_dims[0].stride, padding_,
&dims.spatial_dims[0].output_size, &pad_top, &pad_bottom));
OP_REQUIRES_OK(
context,
GetWindowedOutputSizeVerbose(
dims.spatial_dims[1].input_size, dims.spatial_dims[1].filter_size,
dims.spatial_dims[1].stride, padding_,
&dims.spatial_dims[1].output_size, &pad_left, &pad_right));
const int filter_total_size = dims.spatial_dims[0].filter_size *
dims.spatial_dims[1].filter_size *
dims.in_depth;
const int output_image_size =
dims.spatial_dims[0].output_size * dims.spatial_dims[1].output_size;
const size_t l2_cache_size = 256LL << 10;
const size_t l3_cache_size = 30LL << 20;
const size_t target_working_set_size = l3_cache_size / sizeof(T);
const size_t size_A = output_image_size * dims.out_depth;
const size_t size_B = filter_total_size * dims.out_depth;
const size_t size_C = output_image_size * filter_total_size;
const size_t work_unit_size = size_A + size_B + size_C;
auto worker_threads = *(context->device()->tensorflow_cpu_worker_threads());
const size_t thread_work_unit_size =
work_unit_size / worker_threads.num_threads;
const size_t min_thread_work_unit_size = l2_cache_size / sizeof(T);
const bool use_parallel_contraction =
dims.batch_size == 1 ||
thread_work_unit_size >= min_thread_work_unit_size;
const size_t shard_size =
use_parallel_contraction
? 1
: (target_working_set_size + work_unit_size - 1) / work_unit_size;
Tensor col_buffer;
OP_REQUIRES_OK(context,
context->allocate_temp(
DataTypeToEnum<T>::value,
TensorShape({static_cast<int64>(shard_size),
static_cast<int64>(output_image_size),
static_cast<int64>(filter_total_size)}),
&col_buffer));
const int input_offset = dims.spatial_dims[0].input_size *
dims.spatial_dims[1].input_size * dims.in_depth;
const int output_offset = dims.spatial_dims[0].output_size *
dims.spatial_dims[1].output_size * dims.out_depth;
const T* filter_data = filter.template flat<T>().data();
T* col_buffer_data = col_buffer.template flat<T>().data();
const T* out_backprop_data = out_backprop.template flat<T>().data();
auto in_backprop_flat = in_backprop->template flat<T>();
T* input_backprop_data = in_backprop_flat.data();
in_backprop_flat.device(context->eigen_device<Device>()) =
in_backprop_flat.constant(T(0));
if (use_parallel_contraction) {
typedef Eigen::TensorMap<Eigen::Tensor<T, 2, Eigen::RowMajor>,
Eigen::Unaligned>
TensorMap;
typedef Eigen::TensorMap<Eigen::Tensor<const T, 2, Eigen::RowMajor>,
Eigen::Unaligned>
ConstTensorMap;
Eigen::array<Eigen::IndexPair<Eigen::DenseIndex>, 1> contract_dims;
contract_dims[0].first = 1;
contract_dims[0].second = 1;
for (int image_id = 0; image_id < dims.batch_size; ++image_id) {
TensorMap C(col_buffer_data, output_image_size, filter_total_size);
ConstTensorMap A(out_backprop_data + output_offset * image_id,
output_image_size, dims.out_depth);
ConstTensorMap B(filter_data, filter_total_size, dims.out_depth);
C.device(context->eigen_cpu_device()) = A.contract(B, contract_dims);
Col2im<T>(
col_buffer_data, dims.in_depth, dims.spatial_dims[0].input_size,
dims.spatial_dims[1].input_size, dims.spatial_dims[0].filter_size,
dims.spatial_dims[1].filter_size, pad_top, pad_left, pad_bottom,
pad_right, dims.spatial_dims[0].stride, dims.spatial_dims[1].stride,
input_backprop_data);
input_backprop_data += input_offset;
}
} else {
for (int image_id = 0; image_id < dims.batch_size;
image_id += shard_size) {
const int shard_limit =
std::min(static_cast<int>(shard_size),
static_cast<int>(dims.batch_size) - image_id);
auto shard = [&context, &dims, &pad_top, &pad_left, &pad_bottom,
&pad_right, &output_image_size, &filter_total_size,
&input_backprop_data, &col_buffer_data,
&out_backprop_data, &filter_data, &input_offset,
&output_offset, &size_C](int64 start, int64 limit) {
for (int shard_id = start; shard_id < limit; ++shard_id) {
T* im2col_buf = col_buffer_data + shard_id * size_C;
T* input_data = input_backprop_data + shard_id * input_offset;
const T* out_data = out_backprop_data + shard_id * output_offset;
Conv2DCustomBackpropInputMatMulFunctor<T>()(
context, out_data, filter_data, filter_total_size,
output_image_size, dims.out_depth, im2col_buf);
Col2im<T>(im2col_buf, dims.in_depth,
dims.spatial_dims[0].input_size,
dims.spatial_dims[1].input_size,
dims.spatial_dims[0].filter_size,
dims.spatial_dims[1].filter_size, pad_top, pad_left,
pad_bottom, pad_right, dims.spatial_dims[0].stride,
dims.spatial_dims[1].stride, input_data);
}
};
Shard(worker_threads.num_threads, worker_threads.workers, shard_limit,
work_unit_size, shard);
input_backprop_data += input_offset * shard_limit;
out_backprop_data += output_offset * shard_limit;
}
}
}

void CLASS kodak_65000_load_raw()
{
short buf[256];
int row, col, len, pred[2], ret, i;
for (row=0; row < height; row++)
{
#ifdef LIBRAW_LIBRARY_BUILD
checkCancel();
#endif
for (col=0; col < width; col+=256) {
pred[0] = pred[1] = 0;
len = MIN (256, width-col);
ret = kodak_65000_decode (buf, len);
for (i=0; i < len; i++)
if ((RAW(row,col+i) =curve[ret ? buf[i] :
(pred[i & 1] += buf[i])]) >> 12) derror();
}
}
}

static cJSON *
JSON_read(int fd)
{
uint32_t hsize, nsize;
char *str;
cJSON *json = NULL;
int rc;
if (Nread(fd, (char*) &nsize, sizeof(nsize), Ptcp) >= 0) {
hsize = ntohl(nsize);
str = (char *) calloc(sizeof(char), hsize+1);
if (str != NULL) {
rc = Nread(fd, str, hsize, Ptcp);
if (rc >= 0) {
if (rc == hsize) {
json = cJSON_Parse(str);
}
else {
printf("WARNING:  Size of data read does not correspond to offered length\n");
}
}
}
free(str);
}
return json;
}

static int
zsetcolor(i_ctx_t * i_ctx_p)
{
os_ptr                  op = osp;
es_ptr ep;
const gs_color_space *  pcs = gs_currentcolorspace(igs);
gs_client_color         cc;
int                     n_comps, n_numeric_comps, num_offset = 0, code, depth;
PS_colour_space_t *space;
cc.pattern = 0;
if ((n_comps = cs_num_components(pcs)) < 0) {
n_comps = -n_comps;
if (r_has_type(op, t_dictionary)) {
ref     *pImpl, pPatInst;
code = dict_find_string(op, "Implementation", &pImpl);
if (code != 0) {
code = array_get(imemory, pImpl, 0, &pPatInst);
if (code < 0)
return code;
cc.pattern = r_ptr(&pPatInst, gs_pattern_instance_t);
n_numeric_comps = ( pattern_instance_uses_base_space(cc.pattern)
? n_comps - 1
: 0 );
} else
n_numeric_comps = 0;
} else
n_numeric_comps = 0;
num_offset = 1;
} else
n_numeric_comps = n_comps;
code = float_params(op - num_offset, n_numeric_comps, cc.paint.values);
if (code < 0)
return code;
memset(cc.paint.values + n_numeric_comps, 0,
sizeof(cc.paint.values) - sizeof(*cc.paint.values)*n_numeric_comps);
code = get_space_object(i_ctx_p, &istate->colorspace[0].array, &space);
if (code < 0)
return code;
if (space->validatecomponents) {
code = space->validatecomponents(i_ctx_p,
&istate->colorspace[0].array,
cc.paint.values, n_numeric_comps);
if (code < 0)
return code;
}
if ((code = gs_setcolor(igs, &cc)) >= 0) {
if (n_comps > n_numeric_comps) {
istate->pattern[0] = *op;      
}
}
code = validate_spaces(i_ctx_p, &istate->colorspace[0].array, &depth);
if (code < 0)
return code;
check_estack(5);
ep = esp += 1;
make_int(ep, 0);
ep = esp += 1;
make_int(ep, 0);
ep = esp += 1;
make_int(ep, 0);
ep = esp += 1;
*ep = istate->colorspace[0].array;
push_op_estack(setcolor_cont);
return o_push_estack;
}

