bool ID3::removeUnsynchronizationV2_4(bool iTunesHack) {
size_t oldSize = mSize;
size_t offset = 0;
while (mSize >= 10 && offset <= mSize - 10) {
if (!memcmp(&mData[offset], "\0\0\0\0", 4)) {
break;
}
size_t dataSize;
if (iTunesHack) {
dataSize = U32_AT(&mData[offset + 4]);
} else if (!ParseSyncsafeInteger(&mData[offset + 4], &dataSize)) {
return false;
}
if (dataSize > mSize - 10 - offset) {
return false;
}
uint16_t flags = U16_AT(&mData[offset + 8]);
uint16_t prevFlags = flags;
if (flags & 1) {
if (mSize < 14 || mSize - 14 < offset || dataSize < 4) {
return false;
}
memmove(&mData[offset + 10], &mData[offset + 14], mSize - offset - 14);
mSize -= 4;
dataSize -= 4;
flags &= ~1;
}
if ((flags & 2) && (dataSize >= 2)) {
size_t readOffset = offset + 11;
size_t writeOffset = offset + 11;
for (size_t i = 0; i + 1 < dataSize; ++i) {
if (mData[readOffset - 1] == 0xff
&& mData[readOffset] == 0x00) {
++readOffset;
--mSize;
--dataSize;
}
mData[writeOffset++] = mData[readOffset++];
}
if (readOffset <= oldSize) {
memmove(&mData[writeOffset], &mData[readOffset], oldSize - readOffset);
} else {
ALOGE("b/34618607 (%zu %zu %zu %zu)", readOffset, writeOffset, oldSize, mSize);
android_errorWriteLog(0x534e4554, "34618607");
}
}
flags &= ~2;
if (flags != prevFlags || iTunesHack) {
WriteSyncsafeInteger(&mData[offset + 4], dataSize);
mData[offset + 8] = flags >> 8;
mData[offset + 9] = flags & 0xff;
}
offset += 10 + dataSize;
}
memset(&mData[mSize], 0, oldSize - mSize);
return true;
}

bool StelScriptMgr::prepareScript( QString &script, const QString &fileName, const QString &includePath)
{
QString absPath;
if (QFileInfo(fileName).isAbsolute())
absPath = fileName;
else
absPath = StelFileMgr::findFile("scripts/" + fileName);
if (absPath.isEmpty())
{
QString msg = QString("WARNING: could not find script file %1").arg(QDir::toNativeSeparators(fileName));
emit scriptDebug(msg);
qWarning() << msg;
return false;
}
QString scriptDir = QFileInfo(absPath).dir().path();
QFile fic(absPath);
if (!fic.open(QIODevice::ReadOnly))
{
QString msg = QString("WARNING: cannot open script: %1").arg(QDir::toNativeSeparators(fileName));
emit scriptDebug(msg);
qWarning() << msg;
return false;
}
if (!includePath.isEmpty())
scriptDir = includePath;
bool ok = false;
if (fileName.endsWith(".ssc"))
ok = preprocessFile(absPath, fic, script, scriptDir);
if (!ok)
{
return false;
}
return true;
}

static void tcp_collapse_ofo_queue(struct sock *sk)
{
struct tcp_sock *tp = tcp_sk(sk);
struct sk_buff *skb, *head;
u32 start, end;
skb = skb_rb_first(&tp->out_of_order_queue);
new_range:
if (!skb) {
tp->ooo_last_skb = skb_rb_last(&tp->out_of_order_queue);
return;
}
start = TCP_SKB_CB(skb)->seq;
end = TCP_SKB_CB(skb)->end_seq;
for (head = skb;;) {
skb = skb_rb_next(skb);
if (!skb ||
after(TCP_SKB_CB(skb)->seq, end) ||
before(TCP_SKB_CB(skb)->end_seq, start)) {
tcp_collapse(sk, NULL, &tp->out_of_order_queue,
head, skb, start, end);
goto new_range;
}
if (unlikely(before(TCP_SKB_CB(skb)->seq, start)))
start = TCP_SKB_CB(skb)->seq;
if (after(TCP_SKB_CB(skb)->end_seq, end))
end = TCP_SKB_CB(skb)->end_seq;
}
}

void comps_objrtree_unite(COMPS_ObjRTree *rt1, COMPS_ObjRTree *rt2) {
COMPS_HSList *tmplist, *tmp_subnodes;
COMPS_HSListItem *it;
struct Pair {
COMPS_HSList * subnodes;
char * key;
char added;
} *pair, *parent_pair;
pair = malloc(sizeof(struct Pair));
pair->subnodes = rt2->subnodes;
pair->key = NULL;
tmplist = comps_hslist_create();
comps_hslist_init(tmplist, NULL, NULL, &free);
comps_hslist_append(tmplist, pair, 0);
while (tmplist->first != NULL) {
it = tmplist->first;
comps_hslist_remove(tmplist, tmplist->first);
tmp_subnodes = ((struct Pair*)it->data)->subnodes;
parent_pair = (struct Pair*) it->data;
free(it);
for (it = tmp_subnodes->first; it != NULL; it=it->next) {
pair = malloc(sizeof(struct Pair));
pair->subnodes = ((COMPS_ObjRTreeData*)it->data)->subnodes;
if (parent_pair->key != NULL) {
pair->key = malloc(sizeof(char)
* (strlen(((COMPS_ObjRTreeData*)it->data)->key)
+ strlen(parent_pair->key) + 1));
memcpy(pair->key, parent_pair->key,
sizeof(char) * strlen(parent_pair->key));
memcpy(pair->key + strlen(parent_pair->key),
((COMPS_ObjRTreeData*)it->data)->key,
sizeof(char)*(strlen(((COMPS_ObjRTreeData*)it->data)->key)+1));
} else {
pair->key = malloc(sizeof(char)*
(strlen(((COMPS_ObjRTreeData*)it->data)->key) +1));
memcpy(pair->key, ((COMPS_ObjRTreeData*)it->data)->key,
sizeof(char)*(strlen(((COMPS_ObjRTreeData*)it->data)->key)+1));
}
if (((COMPS_ObjRTreeData*)it->data)->data != NULL) {
comps_objrtree_set(rt1, pair->key,
(((COMPS_ObjRTreeData*)it->data)->data));
}
if (((COMPS_ObjRTreeData*)it->data)->subnodes->first) {
comps_hslist_append(tmplist, pair, 0);
} else {
free(pair->key);
free(pair);
}
}
free(parent_pair->key);
free(parent_pair);
}
comps_hslist_destroy(&tmplist);
}

static Jsi_RC jsi_ArrayFilterCmd(Jsi_Interp *interp, Jsi_Value *args, Jsi_Value *_this,Jsi_Value **ret, Jsi_Func *funcPtr) {
if (_this->vt != JSI_VT_OBJECT || !Jsi_ObjIsArray(interp, _this->d.obj))
return Jsi_LogError("expected array object");
Jsi_RC rc = JSI_OK;
int curlen, nsiz, i, fval, n = 0, maa = 0;
Jsi_Obj *obj, *nobj;
Jsi_Value *func, *vpargs, *nthis = NULL, *sthis, *nrPtr = NULL;
Jsi_Func *fptr = NULL;
func = Jsi_ValueArrayIndex(interp, args, 0);
if (!Jsi_ValueIsFunction(interp, func)) 
return Jsi_LogError("expected function");
sthis = Jsi_ValueArrayIndex(interp, args, 1);
if (!sthis)
sthis = nthis = Jsi_ValueNew1(interp);
obj = _this->d.obj;
curlen = Jsi_ObjGetLength(interp, obj);    
if (curlen < 0) {
Jsi_ObjSetLength(interp, obj, 0);
}
Jsi_ObjListifyArray(interp, obj);
nobj = Jsi_ObjNewType(interp, JSI_OT_ARRAY);
nsiz = obj->arrCnt;
if (nsiz<=0) nsiz = 1;
if (Jsi_ObjArraySizer(interp, nobj, nsiz) <= 0) {
Jsi_LogError("index too large: %d", nsiz);
rc = JSI_ERROR;
goto bail;
}
Jsi_ValueMakeArrayObject(interp, ret, nobj);
nrPtr = Jsi_ValueNew1(interp);
Jsi_Value *vobjs[4];
fptr = func->d.obj->d.fobj->func;
maa = (fptr->argnames?fptr->argnames->argCnt:0);
if (maa>3)
maa = 3;
for (i = 0; i < curlen; i++) {
if (!obj->arr[i]) continue;
vobjs[0] = obj->arr[i];
vobjs[1] = (maa>1?Jsi_ValueNewNumber(interp, i):NULL);
vobjs[2] = _this;
vpargs = Jsi_ValueMakeObject(interp, NULL, Jsi_ObjNewArray(interp, vobjs, maa, 0));
Jsi_IncrRefCount(interp, vpargs);
rc = Jsi_FunctionInvoke(interp, func, vpargs, &nrPtr, sthis);
Jsi_DecrRefCount(interp, vpargs);
fval = Jsi_ValueIsTrue(interp, nrPtr);
Jsi_ValueMakeUndef(interp, &nrPtr);
if( JSI_OK!=rc ) {
goto bail;
}
if (fval) {
nobj->arr[n++] = obj->arr[i];
Jsi_IncrRefCount(interp, obj->arr[i]);
}
}
if (nthis)
Jsi_DecrRefCount(interp, nthis);
Jsi_DecrRefCount(interp, nrPtr);
Jsi_ObjSetLength(interp, nobj, n);
return JSI_OK;
bail:
if (nthis)
Jsi_DecrRefCount(interp, nthis);
if (nrPtr)
Jsi_DecrRefCount(interp, nrPtr);
Jsi_ValueMakeNull(interp, ret);
return rc;
}

NAN_METHOD(XmlDocument::FromXml)
{
Nan::HandleScope scope;
v8::Local<v8::Array> errors = Nan::New<v8::Array>();
xmlResetLastError();
xmlSetStructuredErrorFunc(reinterpret_cast<void *>(&errors),
XmlSyntaxError::PushToArray);
v8::Local<v8::Object> options = Nan::To<v8::Object>(info[1]).ToLocalChecked();
v8::Local<v8::Value>  baseUrlOpt  = Nan::Get(options,
Nan::New<v8::String>("baseUrl").ToLocalChecked()).ToLocalChecked();
v8::Local<v8::Value>  encodingOpt = Nan::Get(options,
Nan::New<v8::String>("encoding").ToLocalChecked()).ToLocalChecked();
Nan::Utf8String baseUrl_(Nan::To<v8::String>(baseUrlOpt).ToLocalChecked());
const char * baseUrl = *baseUrl_;
if (!baseUrlOpt->IsString()) {
baseUrl = NULL;
}
Nan::Utf8String encoding_(Nan::To<v8::String>(encodingOpt).ToLocalChecked());
const char * encoding = *encoding_;
if (!encodingOpt->IsString()) {
encoding = NULL;
}
int opts = (int) getParserOptions(options);
xmlDocPtr doc;
if (!node::Buffer::HasInstance(info[0])) {
Nan::Utf8String str(Nan::To<v8::String>(info[0]).ToLocalChecked());
doc = xmlReadMemory(*str, str.length(), baseUrl, "UTF-8", opts);
}
else {
v8::Local<v8::Object> buf = Nan::To<v8::Object>(info[0]).ToLocalChecked();
doc = xmlReadMemory(node::Buffer::Data(buf), node::Buffer::Length(buf),
baseUrl, encoding, opts);
}
xmlSetStructuredErrorFunc(NULL, NULL);
if (!doc) {
xmlError* error = xmlGetLastError();
if (error) {
return Nan::ThrowError(XmlSyntaxError::BuildSyntaxError(error));
}
return Nan::ThrowError("Could not parse XML string");
}
v8::Local<v8::Object> doc_handle = XmlDocument::New(doc);
Nan::Set(doc_handle, Nan::New<v8::String>("errors").ToLocalChecked(), errors);
xmlNode* root_node = xmlDocGetRootElement(doc);
if (root_node == NULL) {
return Nan::ThrowError("parsed document has no root element");
}
return info.GetReturnValue().Set(doc_handle);
}

static int nut_read_header(AVFormatContext *s)
{
NUTContext *nut = s->priv_data;
AVIOContext *bc = s->pb;
int64_t pos;
int initialized_stream_count;
nut->avf = s;
pos = 0;
do {
pos = find_startcode(bc, MAIN_STARTCODE, pos) + 1;
if (pos < 0 + 1) {
av_log(s, AV_LOG_ERROR, "No main startcode found.\n");
return AVERROR_INVALIDDATA;
