static int yc_poly_emulator(char* decryptor_offset, char* code, unsigned int ecx)
{
unsigned char al;
unsigned char cl = ecx & 0xff;
unsigned int j,i;
for(i=0;i<ecx;i++) 
{
al = code[i];
for(j=0;j<0x30;j++)   
{
switch(decryptor_offset[j])
{
case '\xEB':
j++;
j = j + decryptor_offset[j];
break;
case '\xFE':
al--;
j++;
break;
case '\x2A':
al = al - cl;
j++;
break;
case '\x02':
al = al + cl;
j++;
break
;
case '\x32':
al = al ^ cl;
j++;
break;
;
case '\x04':
j++;
al = al + decryptor_offset[j];
break;
;
case '\x34':
j++;
al = al ^ decryptor_offset[j];
break;
case '\x2C':
j++;
al = al - decryptor_offset[j];
break;
case '\xC0':
j++;
if(decryptor_offset[j]=='\xC0') 
{
j++;
CLI_ROL(al,decryptor_offset[j]);
}
else
{
j++;
CLI_ROR(al,decryptor_offset[j]);
}
break;
case '\xD2':
j++;
if(decryptor_offset[j]=='\xC8') 
{
j++;
CLI_ROR(al,cl);
}
else
{
j++;
CLI_ROL(al,cl);
}
break;
case '\x90':
case '\xf8':
case '\xf9':
break;
default:
cli_dbgmsg("yC: Unhandled opcode %x\n", (unsigned char)decryptor_offset[j]);
return 1;
}
}
cl--;
code[i] = al;
}
return 0;
}

