void
decnet_print(netdissect_options *ndo,
register const u_char *ap, register u_int length,
register u_int caplen)
{
register const union routehdr *rhp;
register int mflags;
int dst, src, hops;
u_int nsplen, pktlen;
const u_char *nspp;
if (length < sizeof(struct shorthdr)) {
ND_PRINT((ndo, "%s", tstr));
return;
}
ND_TCHECK2(*ap, sizeof(short));
pktlen = EXTRACT_LE_16BITS(ap);
if (pktlen < sizeof(struct shorthdr)) {
ND_PRINT((ndo, "%s", tstr));
return;
}
if (pktlen > length) {
ND_PRINT((ndo, "%s", tstr));
return;
}
length = pktlen;
rhp = (const union routehdr *)&(ap[sizeof(short)]);
ND_TCHECK(rhp->rh_short.sh_flags);
mflags = EXTRACT_LE_8BITS(rhp->rh_short.sh_flags);
if (mflags & RMF_PAD) {
u_int padlen = mflags & RMF_PADMASK;
if (ndo->ndo_vflag)
ND_PRINT((ndo, "[pad:%d] ", padlen));
if (length < padlen + 2) {
ND_PRINT((ndo, "%s", tstr));
return;
}
ND_TCHECK2(ap[sizeof(short)], padlen);
ap += padlen;
length -= padlen;
caplen -= padlen;
rhp = (const union routehdr *)&(ap[sizeof(short)]);
mflags = EXTRACT_LE_8BITS(rhp->rh_short.sh_flags);
}
if (mflags & RMF_FVER) {
ND_PRINT((ndo, "future-version-decnet"));
ND_DEFAULTPRINT(ap, min(length, caplen));
return;
}
if (mflags & RMF_CTLMSG) {
if (!print_decnet_ctlmsg(ndo, rhp, length, caplen))
goto trunc;
return;
}
switch (mflags & RMF_MASK) {
case RMF_LONG:
if (length < sizeof(struct longhdr)) {
ND_PRINT((ndo, "%s", tstr));
return;
}
ND_TCHECK(rhp->rh_long);
dst =
EXTRACT_LE_16BITS(rhp->rh_long.lg_dst.dne_remote.dne_nodeaddr);
src =
EXTRACT_LE_16BITS(rhp->rh_long.lg_src.dne_remote.dne_nodeaddr);
hops = EXTRACT_LE_8BITS(rhp->rh_long.lg_visits);
nspp = &(ap[sizeof(short) + sizeof(struct longhdr)]);
nsplen = length - sizeof(struct longhdr);
break;
case RMF_SHORT:
ND_TCHECK(rhp->rh_short);
dst = EXTRACT_LE_16BITS(rhp->rh_short.sh_dst);
src = EXTRACT_LE_16BITS(rhp->rh_short.sh_src);
hops = (EXTRACT_LE_8BITS(rhp->rh_short.sh_visits) & VIS_MASK)+1;
nspp = &(ap[sizeof(short) + sizeof(struct shorthdr)]);
nsplen = length - sizeof(struct shorthdr);
break;
default:
ND_PRINT((ndo, "unknown message flags under mask"));
ND_DEFAULTPRINT((const u_char *)ap, min(length, caplen));
return;
}
ND_PRINT((ndo, "%s > %s %d ",
dnaddr_string(ndo, src), dnaddr_string(ndo, dst), pktlen));
if (ndo->ndo_vflag) {
if (mflags & RMF_RQR)
ND_PRINT((ndo, "RQR "));
if (mflags & RMF_RTS)
ND_PRINT((ndo, "RTS "));
if (mflags & RMF_IE)
ND_PRINT((ndo, "IE "));
ND_PRINT((ndo, "%d hops ", hops));
}
if (!print_nsp(ndo, nspp, nsplen))
goto trunc;
return;
trunc:
ND_PRINT((ndo, "%s", tstr));
return;
}

static SIXELSTATUS
sixel_encode_highcolor(
unsigned char *pixels, int width, int height,
sixel_dither_t *dither, sixel_output_t *output
)
{
SIXELSTATUS status = SIXEL_FALSE;
unsigned char *paletted_pixels = NULL;
unsigned char *normalized_pixels = NULL;
unsigned char *marks;
unsigned char *rgbhit;
unsigned char *rgb2pal;
unsigned char palhitcount[256];
unsigned char palstate[256];
int output_count;
int const maxcolors = 1 << 15;
int whole_size = width * height  
+ maxcolors       
+ maxcolors       
+ width * 6;      
int x, y;
unsigned char *dst;
unsigned char *mptr;
int dirty;
int mod_y;
int nextpal;
int threshold;
int pix;
int orig_height;
unsigned char *pal;
if (dither->pixelformat != SIXEL_PIXELFORMAT_RGB888) {
normalized_pixels = (unsigned char *)sixel_allocator_malloc(dither->allocator,
(size_t)(width * height * 3));
if (normalized_pixels == NULL) {
goto error;
}
status = sixel_helper_normalize_pixelformat(normalized_pixels,
&dither->pixelformat,
pixels,
dither->pixelformat,
width, height);
if (SIXEL_FAILED(status)) {
goto error;
}
pixels = normalized_pixels;
}
paletted_pixels = (unsigned char *)sixel_allocator_malloc(dither->allocator,
(size_t)whole_size);
if (paletted_pixels == NULL) {
goto error;
}
rgbhit = paletted_pixels + width * height;
memset(rgbhit, 0, (size_t)(maxcolors * 2 + width * 6));
rgb2pal = rgbhit + maxcolors;
marks = rgb2pal + maxcolors;
output_count = 0;
next:
dst = paletted_pixels;
nextpal = 0;
threshold = 1;
dirty = 0;
mptr = marks;
memset(palstate, 0, sizeof(palstate));
y = mod_y = 0;
while (1) {
for (x = 0; x < width; x++, mptr++, dst++, pixels += 3) {
if (*mptr) {
*dst = 255;
} else {
sixel_apply_15bpp_dither(pixels,
x, y, width, height,
dither->method_for_diffuse);
pix = ((pixels[0] & 0xf8) << 7) |
((pixels[1] & 0xf8) << 2) |
((pixels[2] >> 3) & 0x1f);
if (!rgbhit[pix]) {
while (1) {
if (nextpal >= 255) {
if (threshold >= 255) {
break;
} else {
threshold = (threshold == 1) ? 9: 255;
nextpal = 0;
}
} else if (palstate[nextpal] ||
palhitcount[nextpal] > threshold) {
nextpal++;
} else {
break;
}
}
if (nextpal >= 255) {
dirty = 1;
*dst = 255;
} else {
pal = dither->palette + (nextpal * 3);
rgbhit[pix] = 1;
if (output_count > 0) {
rgbhit[((pal[0] & 0xf8) << 7) |
((pal[1] & 0xf8) << 2) |
((pal[2] >> 3) & 0x1f)] = 0;
}
*dst = rgb2pal[pix] = nextpal++;
*mptr = 1;
palstate[*dst] = PALETTE_CHANGE;
palhitcount[*dst] = 1;
*(pal++) = pixels[0];
*(pal++) = pixels[1];
*(pal++) = pixels[2];
}
} else {
*dst = rgb2pal[pix];
*mptr = 1;
if (!palstate[*dst]) {
palstate[*dst] = PALETTE_HIT;
}
if (palhitcount[*dst] < 255) {
palhitcount[*dst]++;
}
}
}
}
if (++y >= height) {
if (dirty) {
mod_y = 5;
} else {
goto end;
}
}
if (dirty && mod_y == 5) {
orig_height = height;
if (output_count++ == 0) {
status = sixel_encode_header(width, height, output);
if (SIXEL_FAILED(status)) {
goto error;
}
}
height = y;
status = sixel_encode_body(paletted_pixels,
width,
height,
dither->palette,
255,
255,
dither->bodyonly,
output,
palstate,
dither->allocator);
if (SIXEL_FAILED(status)) {
goto error;
}
pixels -= (6 * width * 3);
height = orig_height - height + 6;
goto next;
}
if (++mod_y == 6) {
mptr = (unsigned char *)memset(marks, 0, (size_t)(width * 6));
mod_y = 0;
}
}
goto next;
end:
if (output_count == 0) {
status = sixel_encode_header(width, height, output);
if (SIXEL_FAILED(status)) {
goto error;
}
}
status = sixel_encode_body(paletted_pixels,
width,
height,
dither->palette,
255,
255,
dither->bodyonly,
output,
palstate,
dither->allocator);
if (SIXEL_FAILED(status)) {
goto error;
}
status = sixel_encode_footer(output);
if (SIXEL_FAILED(status)) {
goto error;
}
error:
sixel_allocator_free(dither->allocator, paletted_pixels);
sixel_allocator_free(dither->allocator, normalized_pixels);
return status;
}

int
initconn (void)
{
char *p = NULL, *a = NULL;
int result, tmpno = 0;
int good_epsv = 0, good_lpsv = 0, j;
socklen_t len;
int on = 1;
uint32_t a0, a1, a2, a3, p0, p1, port;
uint32_t af, hal, h[16], pal; 
struct sockaddr_in *data_addr_sa4 = (struct sockaddr_in *) &data_addr;
struct sockaddr_in6 *data_addr_sa6 = (struct sockaddr_in6 *) &data_addr;
if (passivemode)
{
data = socket (myctladdr.ss_family, SOCK_STREAM, 0);
if (data < 0)
{
perror ("ftp: socket");
return (1);
}
if ((options & SO_DEBUG) &&
setsockopt (data, SOL_SOCKET, SO_DEBUG, (char *) &on,
sizeof (on)) < 0)
if (errno != EACCES)
error (0, errno, "setsockopt DEBUG (ignored)");
switch (myctladdr.ss_family)
{
case AF_INET:
if (doepsv4 && command ("EPSV") == COMPLETE)
{
good_epsv = 1;
break;
}
if (doepsv4)
{
doepsv4 = 0;
}
if (command ("PASV") == COMPLETE)
break;
if (command ("LPSV") == COMPLETE)
{
good_lpsv = 1;
break;
}
printf ("Passive mode refused.\n");
goto bad;
break;
case AF_INET6:
if (command ("EPSV") == COMPLETE)
{
good_epsv = 1;
break;
}
if (command ("LPSV") == COMPLETE)
{
good_lpsv = 1;
break;
}
printf ("Passive mode refused.\n");
goto bad;
break;
}
if (good_epsv)
{
if (sscanf (pasv, "%u|", &port) != 1)
{
printf ("Extended passive mode scan failure. "
"Should not happen!\n");
(void) command ("ABOR");
goto bad;
}
data_addr = hisctladdr;
switch (data_addr.ss_family)
{
case AF_INET:
data_addr_sa4->sin_port = htons (port);
break;
case AF_INET6:
data_addr_sa6->sin6_port = htons (port);
break;
}
} 
else if (good_lpsv)
{
if (myctladdr.ss_family == AF_INET)
{
if ((sscanf (pasv, "%u," 
"%u,%u,%u,%u,%u," 
"%u,%u,%u", 
&af, &hal, &h[0], &h[1], &h[2], &h[3], &pal, &p0, &p1) != 9)
|| ( af != 4 || hal != 4 || pal != 2) )
{
printf ("Passive mode address scan failure. "
"Shouldn't happen!\n");
(void) command ("ABOR");
goto bad;
}
for (j = 0; j < 4; ++j)
h[j] &= 0xff; 
data_addr.ss_family = AF_INET;
data_addr_sa4->sin_port =
htons (((p0 & 0xff) << 8) | (p1 & 0xff));
{
uint32_t *pu32 = (uint32_t *) &data_addr_sa4->sin_addr.s_addr;
pu32[0] = htonl ( (h[0] << 24) | (h[1] << 16) | (h[2] << 8) | h[3]);
}
} 
else 
{
if ((sscanf (pasv, "%u," 
"%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u," 
"%u,%u,%u", 
&af, &hal, &h[0], &h[1], &h[2], &h[3], &h[4], &h[5], &h[6], &h[7],
&h[8], &h[9], &h[10], &h[11], &h[12], &h[13], &h[14], &h[15],
&pal, &p0, &p1) != 21)
|| ( af != 6 || hal != 16 || pal != 2) )
{
printf ("Passive mode address scan failure. "
"Shouldn't happen!\n");
(void) command ("ABOR");
goto bad;
}
for (j = 0; j < 16; ++j)
h[j] &= 0xff; 
data_addr.ss_family = AF_INET6;
data_addr_sa6->sin6_port =
htons (((p0 & 0xff) << 8) | (p1 & 0xff));
{
uint32_t *pu32 = (uint32_t *) &data_addr_sa6->sin6_addr.s6_addr;
pu32[0] = htonl ( (h[0] << 24) | (h[1] << 16) | (h[2] << 8) | h[3]);
pu32[1] = htonl ( (h[4] << 24) | (h[5] << 16) | (h[6] << 8) | h[7]);
pu32[2] = htonl ( (h[8] << 24) | (h[9] << 16) | (h[10] << 8) | h[11]);
pu32[3] = htonl ( (h[12] << 24) | (h[13] << 16) | (h[14] << 8) | h[15]);
}
} 
}
else 
{ 
if (myctladdr.ss_family == AF_INET)
{ 
if (sscanf (pasv, "%u,%u,%u,%u,%u,%u",
&a0, &a1, &a2, &a3, &p0, &p1) != 6)
{
printf ("Passive mode address scan failure. "
"Shouldn't happen!\n");
(void) command ("ABOR");
goto bad;
}
data_addr.ss_family = AF_INET;
data_addr_sa4->sin_addr.s_addr =
htonl ( (a0 << 24) | ((a1 & 0xff) << 16)
| ((a2 & 0xff) << 8) | (a3 & 0xff) );
data_addr_sa4->sin_port =
htons (((p0 & 0xff) << 8) | (p1 & 0xff));
} 
else
{
printf ("Passive mode address scan failure. Shouldn't happen!\n");
goto bad;
}
} 
if (connect (data, (struct sockaddr *) &data_addr, ctladdrlen) < 0)
{
perror ("ftp: connect");
goto bad;
}
#if defined IP_TOS && defined IPPROTO_IP && defined IPTOS_THROUGHPUT
on = IPTOS_THROUGHPUT;
if (data_addr.ss_family == AF_INET &&
setsockopt (data, IPPROTO_IP, IP_TOS, (char *) &on,
sizeof (int)) < 0)
perror ("ftp: setsockopt TOS (ignored)");
#endif
return (0);
}
noport:
data_addr = myctladdr;
if (sendport)
switch (myctladdr.ss_family)
{
case AF_INET:
data_addr_sa4->sin_port = 0;
break;
case AF_INET6:
data_addr_sa6->sin6_port = 0;
break;
}
if (data != -1)
close (data);
data = socket (myctladdr.ss_family, SOCK_STREAM, 0);
if (data < 0)
{
error (0, errno, "socket");
if (tmpno)
sendport = 1;
return (1);
}
if (!sendport)
if (setsockopt (data, SOL_SOCKET, SO_REUSEADDR, (char *) &on, sizeof (on))
< 0)
{
error (0, errno, "setsockopt (reuse address)");
goto bad;
}
if (bind (data, (struct sockaddr *) &data_addr, ctladdrlen) < 0)
{
error (0, errno, "bind");
goto bad;
}
if (options & SO_DEBUG
&& setsockopt (data, SOL_SOCKET, SO_DEBUG,
(char *) &on, sizeof (on)) < 0)
if (errno != EACCES)
error (0, errno, "setsockopt DEBUG (ignored)");
len = sizeof (data_addr);
if (getsockname (data, (struct sockaddr *) &data_addr, &len) < 0)
{
error (0, errno, "getsockname");
goto bad;
}
if (listen (data, 1) < 0)
error (0, errno, "listen");
if (sendport)
{
#define UC(b)(((int)b)&0xff)
result = ERROR;
if (data_addr.ss_family != AF_INET || doepsv4)
{
getnameinfo ((struct sockaddr *) &data_addr, ctladdrlen,
ia, sizeof (ia), portstr, sizeof (portstr),
NI_NUMERICHOST | NI_NUMERICSERV);
result = command ("EPRT |%d|%s|%s|",
(data_addr.ss_family == AF_INET) ? 1 : 2,
ia, portstr);
}
if (data_addr.ss_family == AF_INET && doepsv4 && result != COMPLETE)
doepsv4 = 0;
if (data_addr.ss_family == AF_INET && result != COMPLETE)
{
a = (char *) &data_addr_sa4->sin_addr;
p = (char *) &data_addr_sa4->sin_port;
result = command ("PORT %d,%d,%d,%d,%d,%d",
UC (a[0]), UC (a[1]), UC (a[2]), UC (a[3]),
UC (p[0]), UC (p[1]));
}
if (result != COMPLETE)
{
uint8_t *h, *p;
switch (data_addr.ss_family)
{
case AF_INET:
h = (uint8_t *) &data_addr_sa4->sin_addr;
p = (uint8_t *) &data_addr_sa4->sin_port;
result = command ("LPRT 4,4,%u,%u,%u,%u,2,%u,%u",
h[0], h[1], h[2], h[3], p[0], p[1]);
break;
case AF_INET6:
h = (uint8_t *) &data_addr_sa6->sin6_addr;
p = (uint8_t *) &data_addr_sa6->sin6_port;
result = command ("LPRT 6,16," 
"%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u," 
"2,%u,%u", 
h[0], h[1], h[2], h[3], h[4], h[5], h[6], h[7],
h[8], h[9], h[10], h[11], h[12], h[13], h[14], h[15],
p[0], p[1]);
break;
}
}
if (result == ERROR && sendport == -1)
{
sendport = 0;
tmpno = 1;
goto noport;
}
return (result != COMPLETE);
}
if (tmpno)
sendport = 1;
#if defined IP_TOS && defined IPPROTO_IP && defined IPTOS_THROUGHPUT
on = IPTOS_THROUGHPUT;
if (data_addr.ss_family == AF_INET &&
setsockopt (data, IPPROTO_IP, IP_TOS, (char *) &on, sizeof (int)) < 0)
error (0, errno, "setsockopt TOS (ignored)");
#endif
return (0);
bad:
close (data), data = -1;
if (tmpno)
sendport = 1;
return (1);
}

