GF_EXPORT
GF_Err gf_hinter_finalize(GF_ISOFile *file, GF_SDP_IODProfile IOD_Profile, u32 bandwidth)
{
u32 i, sceneT, odT, descIndex, size, size64;
GF_InitialObjectDescriptor *iod;
GF_SLConfig slc;
GF_ISOSample *samp;
Bool remove_ocr;
u8 *buffer;
char buf64[5000], sdpLine[5100];
gf_isom_sdp_clean(file);
if (bandwidth) {
sprintf(buf64, "b=AS:%d", bandwidth);
gf_isom_sdp_add_line(file, buf64);
}
if (gf_sys_is_test_mode()) {
sprintf(buf64, "a=x-copyright: %s", "MP4/3GP File hinted with GPAC - (c) Telecom ParisTech (http:    } else {
sprintf(buf64, "a=x-copyright: MP4/3GP File hinted with GPAC %s - %s", gf_gpac_version(), gf_gpac_copyright() );
}
gf_isom_sdp_add_line(file, buf64);
if (IOD_Profile == GF_SDP_IOD_NONE) return GF_OK;
odT = sceneT = 0;
for (i=0; i<gf_isom_get_track_count(file); i++) {
if (!gf_isom_is_track_in_root_od(file, i+1)) continue;
switch (gf_isom_get_media_type(file,i+1)) {
case GF_ISOM_MEDIA_OD:
odT = i+1;
break;
case GF_ISOM_MEDIA_SCENE:
sceneT = i+1;
break;
}
}
remove_ocr = 0;
if (IOD_Profile == GF_SDP_IOD_ISMA_STRICT) {
IOD_Profile = GF_SDP_IOD_ISMA;
remove_ocr = 1;
}
if ( (IOD_Profile == GF_SDP_IOD_ISMA) && !sceneT ) return GF_BAD_PARAM;
iod = (GF_InitialObjectDescriptor *) gf_isom_get_root_od(file);
if (!iod) return GF_NOT_SUPPORTED;
if (IOD_Profile == GF_SDP_IOD_ISMA) {
GF_ESD *esd;
Bool is_ok = 1;
while (gf_list_count(iod->ESDescriptors)) {
esd = (GF_ESD*)gf_list_get(iod->ESDescriptors, 0);
gf_odf_desc_del((GF_Descriptor *) esd);
gf_list_rem(iod->ESDescriptors, 0);
}
if (odT) {
esd = gf_isom_get_esd(file, odT, 1);
if (gf_isom_get_sample_count(file, odT)==1) {
samp = gf_isom_get_sample(file, odT, 1, &descIndex);
if (samp && gf_hinter_can_embbed_data(samp->data, samp->dataLength, GF_STREAM_OD)) {
InitSL_NULL(&slc);
slc.predefined = 0;
slc.hasRandomAccessUnitsOnlyFlag = 1;
slc.timeScale = slc.timestampResolution = gf_isom_get_media_timescale(file, odT);
slc.OCRResolution = 1000;
slc.startCTS = samp->DTS+samp->CTS_Offset;
slc.startDTS = samp->DTS;
gf_isom_set_extraction_slc(file, odT, 1, &slc);
size64 = gf_base64_encode(samp->data, samp->dataLength, buf64, 2000);
buf64[size64] = 0;
sprintf(sdpLine, "data:application/mpeg4-od-au;base64,%s", buf64);
esd->decoderConfig->avgBitrate = 0;
esd->decoderConfig->bufferSizeDB = samp->dataLength;
esd->decoderConfig->maxBitrate = 0;
size64 = (u32) strlen(sdpLine)+1;
esd->URLString = (char*)gf_malloc(sizeof(char) * size64);
strcpy(esd->URLString, sdpLine);
} else {
GF_LOG(GF_LOG_WARNING, GF_LOG_RTP, ("[rtp hinter] OD sample too large to be embedded in IOD - ISMA disabled\n"));
is_ok = 0;
}
gf_isom_sample_del(&samp);
}
if (remove_ocr) esd->OCRESID = 0;
else if (esd->OCRESID == esd->ESID) esd->OCRESID = 0;
gf_list_add(iod->ESDescriptors, esd);
}
esd = gf_isom_get_esd(file, sceneT, 1);
if (gf_isom_get_sample_count(file, sceneT)==1) {
samp = gf_isom_get_sample(file, sceneT, 1, &descIndex);
if (gf_hinter_can_embbed_data(samp->data, samp->dataLength, GF_STREAM_SCENE)) {
slc.timeScale = slc.timestampResolution = gf_isom_get_media_timescale(file, sceneT);
slc.OCRResolution = 1000;
slc.startCTS = samp->DTS+samp->CTS_Offset;
slc.startDTS = samp->DTS;
gf_isom_set_extraction_slc(file, sceneT, 1, &slc);
size64 = gf_base64_encode(samp->data, samp->dataLength, buf64, 2000);
buf64[size64] = 0;
sprintf(sdpLine, "data:application/mpeg4-bifs-au;base64,%s", buf64);
esd->decoderConfig->avgBitrate = 0;
esd->decoderConfig->bufferSizeDB = samp->dataLength;
esd->decoderConfig->maxBitrate = 0;
esd->URLString = (char*)gf_malloc(sizeof(char) * (strlen(sdpLine)+1));
strcpy(esd->URLString, sdpLine);
} else {
GF_LOG(GF_LOG_ERROR, GF_LOG_RTP, ("[rtp hinter] Scene description sample too large to be embedded in IOD - ISMA disabled\n"));
is_ok = 0;
}
gf_isom_sample_del(&samp);
}
if (remove_ocr) esd->OCRESID = 0;
else if (esd->OCRESID == esd->ESID) esd->OCRESID = 0;
gf_list_add(iod->ESDescriptors, esd);
if (is_ok) {
u32 has_a, has_v, has_i_a, has_i_v;
has_a = has_v = has_i_a = has_i_v = 0;
for (i=0; i<gf_isom_get_track_count(file); i++) {
esd = gf_isom_get_esd(file, i+1, 1);
if (!esd) continue;
if (esd->decoderConfig->streamType==GF_STREAM_VISUAL) {
if (esd->decoderConfig->objectTypeIndication==GF_CODECID_MPEG4_PART2) has_i_v ++;
else has_v++;
} else if (esd->decoderConfig->streamType==GF_STREAM_AUDIO) {
if (esd->decoderConfig->objectTypeIndication==GF_CODECID_AAC_MPEG4) has_i_a ++;
else has_a++;
}
gf_odf_desc_del((GF_Descriptor *)esd);
}
if (!has_v && !has_a && (has_i_v<=1) && (has_i_a<=1)) {
sprintf(sdpLine, "a=isma-compliance:1,1.0,1");
gf_isom_sdp_add_line(file, sdpLine);
}
}
}
buffer = NULL;
size = 0;
gf_odf_desc_write((GF_Descriptor *) iod, &buffer, &size);
gf_odf_desc_del((GF_Descriptor *)iod);
size64 = gf_base64_encode(buffer, size, buf64, 2000);
buf64[size64] = 0;
gf_free(buffer);
sprintf(sdpLine, "a=mpeg4-iod:\"data:application/mpeg4-iod;base64,%s\"", buf64);
gf_isom_sdp_add_line(file, sdpLine);
return GF_OK;
}

static void btif_av_event_free_data(btif_sm_event_t event, void* p_data) {
switch (event) {
case BTA_AV_META_MSG_EVT: {
tBTA_AV* av = (tBTA_AV*)p_data;
osi_free_and_reset((void**)&av->meta_msg.p_data);
if (av->meta_msg.p_msg) {
if (av->meta_msg.p_msg->hdr.opcode == AVRC_OP_VENDOR) {
osi_free(av->meta_msg.p_msg->vendor.p_vendor_data);
}
osi_free_and_reset((void**)&av->meta_msg.p_msg);
}
} break;
default:
break;
}
}

void WasmBinaryBuilder::visitRefAs(RefAs* curr, uint8_t code) {
BYN_TRACE("zz node: RefAs\n");
switch (code) {
case BinaryConsts::RefAsNonNull:
curr->op = RefAsNonNull;
break;
case BinaryConsts::RefAsFunc:
curr->op = RefAsFunc;
break;
case BinaryConsts::RefAsData:
curr->op = RefAsData;
break;
case BinaryConsts::RefAsI31:
curr->op = RefAsI31;
break;
default:
WASM_UNREACHABLE("invalid code for ref.as_*");
}
curr->value = popNonVoidExpression();
curr->finalize();
}

static int
dissect_dnp3_message(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void* data _U_)
{
proto_item  *ti, *tdl, *tc, *hidden_item;
proto_tree  *dnp3_tree, *dl_tree, *field_tree;
int          offset = 0, temp_offset = 0;
gboolean     dl_prm;
guint8       dl_len, dl_ctl, dl_func;
const gchar *func_code_str;
guint16      dl_dst, dl_src, calc_dl_crc;
col_set_str(pinfo->cinfo, COL_PROTOCOL, "DNP 3.0");
col_clear(pinfo->cinfo, COL_INFO);
temp_offset += 2;
dl_len = tvb_get_guint8(tvb, temp_offset);
temp_offset += 1;
dl_ctl = tvb_get_guint8(tvb, temp_offset);
temp_offset += 1;
dl_dst = tvb_get_letohs(tvb, temp_offset);
temp_offset += 2;
dl_src = tvb_get_letohs(tvb, temp_offset);
dl_func = dl_ctl & DNP3_CTL_FUNC;
dl_prm = dl_ctl & DNP3_CTL_PRM;
func_code_str = val_to_str(dl_func, dl_prm ? dnp3_ctl_func_pri_vals : dnp3_ctl_func_sec_vals,
"Unknown function (0x%02x)");
col_append_fstr(pinfo->cinfo, COL_INFO, "from %u to %u", dl_src, dl_dst);
col_append_sep_fstr(pinfo->cinfo, COL_INFO, NULL, "len=%u, %s", dl_len, func_code_str);
ti = proto_tree_add_item(tree, proto_dnp3, tvb, offset, -1, ENC_NA);
dnp3_tree = proto_item_add_subtree(ti, ett_dnp3);
dl_tree = proto_tree_add_subtree_format(dnp3_tree, tvb, offset, DNP_HDR_LEN, ett_dnp3_dl, &tdl,
"Data Link Layer, Len: %u, From: %u, To: %u, ", dl_len, dl_src, dl_dst);
if (dl_prm) {
if (dl_ctl & DNP3_CTL_DIR) proto_item_append_text(tdl, "DIR, ");
if (dl_ctl & DNP3_CTL_PRM) proto_item_append_text(tdl, "PRM, ");
if (dl_ctl & DNP3_CTL_FCB) proto_item_append_text(tdl, "FCB, ");
if (dl_ctl & DNP3_CTL_FCV) proto_item_append_text(tdl, "FCV, ");
}
else {
if (dl_ctl & DNP3_CTL_DIR) proto_item_append_text(tdl, "DIR, ");
if (dl_ctl & DNP3_CTL_PRM) proto_item_append_text(tdl, "PRM, ");
if (dl_ctl & DNP3_CTL_RES) proto_item_append_text(tdl, "RES, ");
if (dl_ctl & DNP3_CTL_DFC) proto_item_append_text(tdl, "DFC, ");
}
proto_item_append_text(tdl, "%s", func_code_str);
proto_tree_add_item(dl_tree, hf_dnp3_start, tvb, offset, 2, ENC_BIG_ENDIAN);
offset += 2;
proto_tree_add_item(dl_tree, hf_dnp3_len, tvb, offset, 1, ENC_BIG_ENDIAN);
offset += 1;
tc = proto_tree_add_uint_format_value(dl_tree, hf_dnp3_ctl, tvb, offset, 1, dl_ctl,
"0x%02x (", dl_ctl);
if (dl_prm) {
if (dl_ctl & DNP3_CTL_DIR) proto_item_append_text(tc, "DIR, ");
if (dl_ctl & DNP3_CTL_PRM) proto_item_append_text(tc, "PRM, ");
if (dl_ctl & DNP3_CTL_FCB) proto_item_append_text(tc, "FCB, ");
if (dl_ctl & DNP3_CTL_FCV) proto_item_append_text(tc, "FCV, ");
}
else {
if (dl_ctl & DNP3_CTL_DIR) proto_item_append_text(tc, "DIR, ");
if (dl_ctl & DNP3_CTL_PRM) proto_item_append_text(tc, "PRM, ");
if (dl_ctl & DNP3_CTL_RES) proto_item_append_text(tc, "RES, ");
if (dl_ctl & DNP3_CTL_DFC) proto_item_append_text(tc, "DFC, ");
}
proto_item_append_text(tc, "%s)", func_code_str );
field_tree = proto_item_add_subtree(tc, ett_dnp3_dl_ctl);
if (dl_prm) {
proto_tree_add_item(field_tree, hf_dnp3_ctl_dir, tvb, offset, 1, ENC_LITTLE_ENDIAN);
proto_tree_add_item(field_tree, hf_dnp3_ctl_prm, tvb, offset, 1, ENC_LITTLE_ENDIAN);
proto_tree_add_item(field_tree, hf_dnp3_ctl_fcb, tvb, offset, 1, ENC_LITTLE_ENDIAN);
proto_tree_add_item(field_tree, hf_dnp3_ctl_fcv, tvb, offset, 1, ENC_LITTLE_ENDIAN);
proto_tree_add_item(field_tree, hf_dnp3_ctl_prifunc, tvb, offset, 1, ENC_BIG_ENDIAN);
}
else {
proto_tree_add_item(field_tree, hf_dnp3_ctl_dir, tvb, offset, 1, ENC_LITTLE_ENDIAN);
proto_tree_add_item(field_tree, hf_dnp3_ctl_prm, tvb, offset, 1, ENC_LITTLE_ENDIAN);
proto_tree_add_item(field_tree, hf_dnp3_ctl_dfc, tvb, offset, 1, ENC_LITTLE_ENDIAN);
proto_tree_add_item(field_tree, hf_dnp3_ctl_secfunc, tvb, offset, 1, ENC_BIG_ENDIAN);
}
offset += 1;
proto_tree_add_item(dl_tree, hf_dnp3_dst, tvb, offset, 2, ENC_LITTLE_ENDIAN);
hidden_item = proto_tree_add_item(dl_tree, hf_dnp3_addr, tvb, offset, 2, ENC_LITTLE_ENDIAN);
proto_item_set_hidden(hidden_item);
offset += 2;
proto_tree_add_item(dl_tree, hf_dnp3_src, tvb, offset, 2, ENC_LITTLE_ENDIAN);
hidden_item = proto_tree_add_item(dl_tree, hf_dnp3_addr, tvb, offset, 2, ENC_LITTLE_ENDIAN);
proto_item_set_hidden(hidden_item);
offset += 2;
calc_dl_crc = calculateCRCtvb(tvb, 0, DNP_HDR_LEN - 2);
proto_tree_add_checksum(dl_tree, tvb, offset, hf_dnp3_data_hdr_crc,
hf_dnp3_data_hdr_crc_status, &ei_dnp3_data_hdr_crc_incorrect,
pinfo, calc_dl_crc, ENC_LITTLE_ENDIAN, PROTO_CHECKSUM_VERIFY);
offset += 2;
if ((dl_func != DL_FUNC_LINK_STAT) && (dl_func != DL_FUNC_STAT_LINK) &&
(dl_func != DL_FUNC_RESET_LINK) && (dl_func != DL_FUNC_ACK))
{
proto_tree *data_tree;
proto_item *data_ti;
guint8      tr_ctl, tr_seq;
gboolean    tr_fir, tr_fin;
guint8     *al_buffer, *al_buffer_ptr;
guint8      data_len;
int         data_start = offset;
int         tl_offset;
gboolean    crc_OK = FALSE;
tvbuff_t   *next_tvb;
guint       i;
static int * const transport_flags[] = {
&hf_dnp3_tr_fin,
&hf_dnp3_tr_fir,
&hf_dnp3_tr_seq,
NULL
};
tr_ctl = tvb_get_guint8(tvb, offset);
tr_seq = tr_ctl & DNP3_TR_SEQ;
tr_fir = tr_ctl & DNP3_TR_FIR;
tr_fin = tr_ctl & DNP3_TR_FIN;
tc = proto_tree_add_bitmask(dnp3_tree, tvb, offset, hf_dnp3_tr_ctl, ett_dnp3_tr_ctl, transport_flags, ENC_BIG_ENDIAN);
proto_item_append_text(tc, "(");
if (tr_fir) proto_item_append_text(tc, "FIR, ");
if (tr_fin) proto_item_append_text(tc, "FIN, ");
proto_item_append_text(tc, "Sequence %u)", tr_seq);
data_tree = proto_tree_add_subtree(dnp3_tree, tvb, offset, -1, ett_dnp3_dl_data, &data_ti, "Data Chunks");
data_len = dl_len - 5;
al_buffer = (guint8 *)wmem_alloc(pinfo->pool, data_len);
al_buffer_ptr = al_buffer;
i = 0;
tl_offset = 1;  
while (data_len > 0)
{
guint8        chk_size;
const guint8 *chk_ptr;
proto_tree   *chk_tree;
proto_item   *chk_len_ti;
guint16       calc_crc, act_crc;
chk_size = MIN(data_len, AL_MAX_CHUNK_SIZE);
chk_ptr  = tvb_get_ptr(tvb, offset, chk_size);
memcpy(al_buffer_ptr, chk_ptr + tl_offset, chk_size - tl_offset);
al_buffer_ptr += chk_size - tl_offset;
chk_tree = proto_tree_add_subtree_format(data_tree, tvb, offset, chk_size + 2, ett_dnp3_dl_chunk, NULL, "Data Chunk: %u", i);
proto_tree_add_item(chk_tree, hf_dnp3_data_chunk, tvb, offset, chk_size, ENC_NA);
chk_len_ti = proto_tree_add_uint(chk_tree, hf_dnp3_data_chunk_len, tvb, offset, 0, chk_size);
proto_item_set_generated(chk_len_ti);
offset  += chk_size;
calc_crc = calculateCRC(chk_ptr, chk_size);
proto_tree_add_checksum(chk_tree, tvb, offset, hf_dnp3_data_chunk_crc,
hf_dnp3_data_chunk_crc_status, &ei_dnp3_data_chunk_crc_incorrect,
pinfo, calc_crc, ENC_LITTLE_ENDIAN, PROTO_CHECKSUM_VERIFY);
act_crc  = tvb_get_letohs(tvb, offset);
offset  += 2;
crc_OK   = calc_crc == act_crc;
if (!crc_OK)
{
break;
}
data_len -= chk_size;
i++;
tl_offset = 0;  
}
proto_item_set_len(data_ti, offset - data_start);
if (crc_OK)
{
tvbuff_t *al_tvb;
gboolean  save_fragmented;
al_tvb = tvb_new_child_real_data(tvb, al_buffer, (guint) (al_buffer_ptr-al_buffer), (gint) (al_buffer_ptr-al_buffer));
save_fragmented = pinfo->fragmented;
static guint al_max_fragments = 60;
static guint al_fragment_aging = 64; 
fragment_head *frag_al = NULL;
pinfo->fragmented = TRUE;
if (!pinfo->fd->visited)
{
frag_al = fragment_add_seq_single_aging(&al_reassembly_table,
al_tvb, 0, pinfo, tr_seq, NULL,
tvb_reported_length(al_tvb), 
tr_fir, tr_fin,
al_max_fragments, al_fragment_aging);
}
else
{
frag_al = fragment_get_reassembled_id(&al_reassembly_table, pinfo, tr_seq);
}
next_tvb = process_reassembled_data(al_tvb, 0, pinfo,
"Reassembled DNP 3.0 Application Layer message", frag_al, &dnp3_frag_items,
NULL, dnp3_tree);
if (frag_al)
{
if (pinfo->num == frag_al->reassembled_in && pinfo->curr_layer_num == frag_al->reas_in_layer_num)
{
dissect_dnp3_al(next_tvb, pinfo, dnp3_tree);
}
else
{
col_set_fence(pinfo->cinfo, COL_INFO);
col_append_fstr(pinfo->cinfo, COL_INFO,
" (Application Layer fragment %u, reassembled in packet %u)",
tr_seq, frag_al->reassembled_in);
proto_tree_add_item(dnp3_tree, hf_al_frag_data, al_tvb, 0, -1, ENC_NA);
}
}
else
{
col_append_fstr(pinfo->cinfo, COL_INFO,
" (Application Layer Unreassembled fragment %u)",
tr_seq);
proto_tree_add_item(dnp3_tree, hf_al_frag_data, al_tvb, 0, -1, ENC_NA);
}
pinfo->fragmented = save_fragmented;
}
else
{
g_free(al_buffer);
next_tvb = NULL;
}
}
proto_item_set_len(ti, offset);
return offset;
}

bool XRef::readXRefTable(Parser *parser, Goffset *pos, std::vector<Goffset> *followedXRefStm, std::vector<int> *xrefStreamObjsNum)
{
XRefEntry entry;
bool more;
Object obj, obj2;
Goffset pos2;
int first, n;
while (true) {
obj = parser->getObj(true);
if (obj.isCmd("trailer")) {
break;
}
if (!obj.isInt()) {
goto err0;
}
first = obj.getInt();
obj = parser->getObj(true);
if (!obj.isInt()) {
goto err0;
}
n = obj.getInt();
if (first < 0 || n < 0 || first > INT_MAX - n) {
goto err0;
}
if (first + n > size) {
if (resize(first + n) != first + n) {
error(errSyntaxError, -1, "Invalid 'obj' parameters'");
goto err0;
}
}
for (int i = first; i < first + n; ++i) {
obj = parser->getObj(true);
if (obj.isInt()) {
entry.offset = obj.getInt();
} else if (obj.isInt64()) {
entry.offset = obj.getInt64();
} else {
goto err0;
}
obj = parser->getObj(true);
if (!obj.isInt()) {
goto err0;
}
entry.gen = obj.getInt();
entry.flags = 0;
obj = parser->getObj(true);
if (obj.isCmd("n")) {
entry.type = xrefEntryUncompressed;
} else if (obj.isCmd("f")) {
entry.type = xrefEntryFree;
} else {
goto err0;
}
if (entries[i].offset == -1) {
entries[i].offset = entry.offset;
entries[i].gen = entry.gen;
entries[i].type = entry.type;
entries[i].flags = entry.flags;
entries[i].obj.setToNull();
if (i == 1 && first == 1 && entries[1].offset == 0 && entries[1].gen == 65535 && entries[1].type == xrefEntryFree) {
i = first = 0;
entries[0].offset = 0;
entries[0].gen = 65535;
entries[0].type = xrefEntryFree;
entries[0].flags = entries[1].flags;
entries[0].obj = std::move(entries[1].obj);
entries[1].offset = -1;
entries[1].obj.setToNull();
}
}
}
}
obj = parser->getObj();
if (!obj.isDict()) {
goto err0;
}
obj2 = obj.getDict()->lookupNF("Prev").copy();
if (obj2.isInt() || obj2.isInt64()) {
if (obj2.isInt())
pos2 = obj2.getInt();
else
pos2 = obj2.getInt64();
if (pos2 != *pos) {
*pos = pos2;
more = true;
} else {
error(errSyntaxWarning, -1, "Infinite loop in xref table");
more = false;
}
} else if (obj2.isRef()) {
pos2 = (unsigned int)obj2.getRefNum();
if (pos2 != *pos) {
*pos = pos2;
more = true;
} else {
error(errSyntaxWarning, -1, "Infinite loop in xref table");
more = false;
}
} else {
more = false;
}
if (trailerDict.isNone()) {
trailerDict = obj.copy();
}
obj2 = obj.getDict()->lookup("XRefStm");
if (obj2.isInt() || obj2.isInt64()) {
if (obj2.isInt())
pos2 = obj2.getInt();
else
pos2 = obj2.getInt64();
for (size_t i = 0; ok == true && i < followedXRefStm->size(); ++i) {
if (followedXRefStm->at(i) == pos2) {
ok = false;
}
}
if (ok) {
followedXRefStm->push_back(pos2);
readXRef(&pos2, followedXRefStm, xrefStreamObjsNum);
}
if (!ok) {
goto err0;
}
}
return more;
err0:
ok = false;
return false;
}

static void async_polkit_query_free(AsyncPolkitQuery *q) {
if (!q)
return;
sd_bus_slot_unref(q->slot);
if (q->registry && q->request)
hashmap_remove(q->registry, q->request);
sd_bus_message_unref(q->request);
sd_bus_message_unref(q->reply);
free(q->action);
strv_free(q->details);
free(q);
}

static void
DeepCopyPointerClasses(DeviceIntPtr from, DeviceIntPtr to)
{
ClassesPtr classes;
if (from->ptrfeed) {
PtrFeedbackPtr *p, it;
if (!to->ptrfeed) {
classes = to->unused_classes;
to->ptrfeed = classes->ptrfeed;
classes->ptrfeed = NULL;
}
p = &to->ptrfeed;
for (it = from->ptrfeed; it; it = it->next) {
if (!(*p)) {
*p = calloc(1, sizeof(PtrFeedbackClassRec));
if (!*p) {
ErrorF("[Xi] Cannot alloc memory for class copy.");
return;
}
}
(*p)->CtrlProc = it->CtrlProc;
(*p)->ctrl = it->ctrl;
p = &(*p)->next;
}
}
else if (to->ptrfeed && !from->ptrfeed) {
classes = to->unused_classes;
classes->ptrfeed = to->ptrfeed;
to->ptrfeed = NULL;
}
if (from->valuator) {
ValuatorClassPtr v;
if (!to->valuator) {
classes = to->unused_classes;
to->valuator = classes->valuator;
if (to->valuator)
classes->valuator = NULL;
}
v = AllocValuatorClass(to->valuator, from->valuator->numAxes);
if (!v)
FatalError("[Xi] no memory for class shift.\n");
to->valuator = v;
memcpy(v->axes, from->valuator->axes, v->numAxes * sizeof(AxisInfo));
v->sourceid = from->id;
}
else if (to->valuator && !from->valuator) {
classes = to->unused_classes;
classes->valuator = to->valuator;
to->valuator = NULL;
}
if (from->button) {
if (!to->button) {
classes = to->unused_classes;
to->button = classes->button;
if (!to->button) {
to->button = calloc(1, sizeof(ButtonClassRec));
if (!to->button)
FatalError("[Xi] no memory for class shift.\n");
}
else
classes->button = NULL;
}
if (from->button->xkb_acts) {
if (!to->button->xkb_acts) {
to->button->xkb_acts = calloc(1, sizeof(XkbAction));
if (!to->button->xkb_acts)
FatalError("[Xi] not enough memory for xkb_acts.\n");
}
memcpy(to->button->xkb_acts, from->button->xkb_acts,
sizeof(XkbAction));
}
else {
free(to->button->xkb_acts);
to->button->xkb_acts = NULL;
}
memcpy(to->button->labels, from->button->labels,
from->button->numButtons * sizeof(Atom));
to->button->sourceid = from->id;
}
else if (to->button && !from->button) {
classes = to->unused_classes;
classes->button = to->button;
to->button = NULL;
}
if (from->proximity) {
if (!to->proximity) {
classes = to->unused_classes;
to->proximity = classes->proximity;
if (!to->proximity) {
to->proximity = calloc(1, sizeof(ProximityClassRec));
if (!to->proximity)
FatalError("[Xi] no memory for class shift.\n");
}
else
classes->proximity = NULL;
}
memcpy(to->proximity, from->proximity, sizeof(ProximityClassRec));
to->proximity->sourceid = from->id;
}
else if (to->proximity) {
classes = to->unused_classes;
classes->proximity = to->proximity;
to->proximity = NULL;
}
if (from->touch) {
TouchClassPtr t, f;
if (!to->touch) {
classes = to->unused_classes;
to->touch = classes->touch;
if (!to->touch) {
int i;
to->touch = calloc(1, sizeof(TouchClassRec));
if (!to->touch)
FatalError("[Xi] no memory for class shift.\n");
to->touch->num_touches = from->touch->num_touches;
to->touch->touches = calloc(to->touch->num_touches,
sizeof(TouchPointInfoRec));
for (i = 0; i < to->touch->num_touches; i++)
TouchInitTouchPoint(to->touch, to->valuator, i);
if (!to->touch)
FatalError("[Xi] no memory for class shift.\n");
}
else
classes->touch = NULL;
}
t = to->touch;
f = from->touch;
t->sourceid = f->sourceid;
t->max_touches = f->max_touches;
t->mode = f->mode;
t->buttonsDown = f->buttonsDown;
t->state = f->state;
t->motionMask = f->motionMask;
}
if (from->gesture) {
if (!to->gesture) {
classes = to->unused_classes;
to->gesture = classes->gesture;
if (!to->gesture) {
if (!InitGestureClassDeviceStruct(to, from->gesture->max_touches))
FatalError("[Xi] no memory for class shift.\n");
}
else
classes->gesture = NULL;
}
to->gesture->sourceid = from->gesture->sourceid;
}
}

struct edid *drm_load_edid_firmware(struct drm_connector *connector)
{
const char *connector_name = connector->name;
char *edidname, *last, *colon, *fwstr, *edidstr, *fallback = NULL;
struct edid *edid;
if (edid_firmware[0] == '\0')
return ERR_PTR(-ENOENT);
fwstr = kstrdup(edid_firmware, GFP_KERNEL);
edidstr = fwstr;
while ((edidname = strsep(&edidstr, ","))) {
colon = strchr(edidname, ':');
if (colon != NULL) {
if (strncmp(connector_name, edidname, colon - edidname))
continue;
edidname = colon + 1;
break;
}
if (*edidname != '\0') 
fallback = edidname;
}
if (!edidname) {
if (!fallback) {
kfree(fwstr);
return ERR_PTR(-ENOENT);
}
edidname = fallback;
}
last = edidname + strlen(edidname) - 1;
if (*last == '\n')
*last = '\0';
edid = edid_load(connector, edidname, connector_name);
kfree(fwstr);
return edid;
}

int 
dlt_en10mb_encode(tcpeditdlt_t *ctx, u_char *packet, int pktlen, tcpr_dir_t dir)
{
tcpeditdlt_plugin_t *plugin = NULL;
struct tcpr_ethernet_hdr *eth = NULL;
struct tcpr_802_1q_hdr *vlan = NULL;
en10mb_config_t *config = NULL;
en10mb_extra_t *extra = NULL;
int newl2len = 0;
assert(ctx);
assert(packet);
if (pktlen < TCPR_802_1Q_H) {
tcpedit_seterr(ctx->tcpedit, 
"Unable to process packet #" COUNTER_SPEC " since it is less then 14 bytes.", 
ctx->tcpedit->runtime.packetnum);
return TCPEDIT_ERROR;
}
plugin = tcpedit_dlt_getplugin(ctx, dlt_value);
if (!plugin)
return TCPEDIT_ERROR;
config = plugin->config;
if (plugin->config_size < sizeof(*config))
return TCPEDIT_ERROR;
extra = (en10mb_extra_t *)ctx->decoded_extra;
if (ctx->decoded_extra_size < sizeof(*extra))
return TCPEDIT_ERROR;
if (ctx->decoder->dlt == dlt_value) {
if ((ctx->l2len == TCPR_802_1Q_H && config->vlan == TCPEDIT_VLAN_OFF) ||
(config->vlan == TCPEDIT_VLAN_ADD)) {
newl2len = TCPR_802_1Q_H;
} else if ((ctx->l2len == TCPR_802_3_H && config->vlan == TCPEDIT_VLAN_OFF) ||
(config->vlan == TCPEDIT_VLAN_DEL)) {
newl2len = TCPR_802_3_H;
}
} 
else {
newl2len = config->vlan == TCPEDIT_VLAN_ADD ? TCPR_802_1Q_H : TCPR_802_3_H;
}
if (pktlen < newl2len) {
tcpedit_seterr(ctx->tcpedit,
"Unable to process packet #" COUNTER_SPEC " since its new length less then %d bytes.",
ctx->tcpedit->runtime.packetnum, newl2len);
return TCPEDIT_ERROR;
}
if (newl2len != ctx->l2len)
memmove(packet + newl2len, packet + ctx->l2len, pktlen - ctx->l2len);
pktlen += newl2len - ctx->l2len;
eth = (struct tcpr_ethernet_hdr *)packet;
if (dir == TCPR_DIR_C2S) {
if (config->mac_mask & TCPEDIT_MAC_MASK_SMAC1) {
if ((ctx->addr_type == ETHERNET && 
((ctx->skip_broadcast && 
is_unicast_ethernet(ctx, ctx->srcaddr.ethernet)) || !ctx->skip_broadcast))
|| ctx->addr_type != ETHERNET) {
memcpy(eth->ether_shost, config->intf1_smac, ETHER_ADDR_LEN);
} else {
memcpy(eth->ether_shost, ctx->srcaddr.ethernet, ETHER_ADDR_LEN);                
}
} else if (ctx->addr_type == ETHERNET) {
memcpy(eth->ether_shost, ctx->srcaddr.ethernet, ETHER_ADDR_LEN);
} else {
tcpedit_seterr(ctx->tcpedit, "%s", "Please provide a source address");
return TCPEDIT_ERROR;
}
if (config->mac_mask & TCPEDIT_MAC_MASK_DMAC1) {
if ((ctx->addr_type == ETHERNET && 
((ctx->skip_broadcast && is_unicast_ethernet(ctx, ctx->dstaddr.ethernet)) || !ctx->skip_broadcast))
|| ctx->addr_type != ETHERNET) {
memcpy(eth->ether_dhost, config->intf1_dmac, ETHER_ADDR_LEN);
} else {
memcpy(eth->ether_dhost, ctx->dstaddr.ethernet, ETHER_ADDR_LEN);
}
} else if (ctx->addr_type == ETHERNET) {
memcpy(eth->ether_dhost, ctx->dstaddr.ethernet, ETHER_ADDR_LEN);
} else {
tcpedit_seterr(ctx->tcpedit, "%s", "Please provide a destination address");
return TCPEDIT_ERROR;            
}
} else if (dir == TCPR_DIR_S2C) {
if (config->mac_mask & TCPEDIT_MAC_MASK_SMAC2) {
if ((ctx->addr_type == ETHERNET && 
((ctx->skip_broadcast && is_unicast_ethernet(ctx, ctx->srcaddr.ethernet)) || !ctx->skip_broadcast))
|| ctx->addr_type != ETHERNET) {
memcpy(eth->ether_shost, config->intf2_smac, ETHER_ADDR_LEN);
} else {
memcpy(eth->ether_shost, ctx->srcaddr.ethernet, ETHER_ADDR_LEN);
}
} else if (ctx->addr_type == ETHERNET) {
memcpy(eth->ether_shost, ctx->srcaddr.ethernet, ETHER_ADDR_LEN);            
} else {
tcpedit_seterr(ctx->tcpedit, "%s", "Please provide a source address");
return TCPEDIT_ERROR;
}
if (config->mac_mask & TCPEDIT_MAC_MASK_DMAC2) {
if ((ctx->addr_type == ETHERNET && 
((ctx->skip_broadcast && is_unicast_ethernet(ctx, ctx->dstaddr.ethernet)) || !ctx->skip_broadcast))
|| ctx->addr_type != ETHERNET) {
memcpy(eth->ether_dhost, config->intf2_dmac, ETHER_ADDR_LEN);
} else {
memcpy(eth->ether_dhost, ctx->dstaddr.ethernet, ETHER_ADDR_LEN);                
}
} else if (ctx->addr_type == ETHERNET) {
memcpy(eth->ether_dhost, ctx->dstaddr.ethernet, ETHER_ADDR_LEN);
} else {
tcpedit_seterr(ctx->tcpedit, "%s", "Please provide a destination address");
return TCPEDIT_ERROR;
}
} else {
tcpedit_seterr(ctx->tcpedit, "%s", "Encoders only support C2S or C2S!");
return TCPEDIT_ERROR;
}
if (config->subs.entries) {
int  entry = 0;
for (entry = 0 ; entry < config->subs.count; entry++) {
en10mb_sub_entry_t *current = &config->subs.entries[entry];
if (!memcmp(eth->ether_dhost, current->target, ETHER_ADDR_LEN)) {
memcpy(eth->ether_dhost, current->rewrite, ETHER_ADDR_LEN);
}
if (!memcmp(eth->ether_shost, current->target, ETHER_ADDR_LEN)) {
memcpy(eth->ether_shost, current->rewrite, ETHER_ADDR_LEN);
}
}
}
if (config->random.set) {
int unicast_src = is_unicast_ethernet(ctx, eth->ether_shost);
int unicast_dst = is_unicast_ethernet(ctx, eth->ether_dhost);
int i = config->random.keep;
for ( ; i < ETHER_ADDR_LEN; i++) {
eth->ether_shost[i] = MAC_MASK_APPLY(eth->ether_shost[i], config->random.mask[i], unicast_src);
eth->ether_dhost[i] = MAC_MASK_APPLY(eth->ether_dhost[i], config->random.mask[i], unicast_dst);
}
if (!config->random.keep) {
eth->ether_shost[0] &= ~(0x01 * unicast_src);
eth->ether_dhost[0] &= ~(0x01 * unicast_dst);
}
}
if (newl2len == TCPR_802_3_H) {
eth->ether_type = ctx->proto;
} else if (newl2len == TCPR_802_1Q_H) {
vlan = (struct tcpr_802_1q_hdr *)packet;
vlan->vlan_len = ctx->proto;
vlan->vlan_tpi = htons(ETHERTYPE_VLAN);
if (config->vlan_tag < 65535) {
vlan->vlan_priority_c_vid = 
htons((uint16_t)config->vlan_tag & TCPR_802_1Q_VIDMASK);
} else if (extra->vlan) {
vlan->vlan_priority_c_vid = extra->vlan_tag;
} else {
tcpedit_seterr(ctx->tcpedit, "%s", "Non-VLAN tagged packet requires --enet-vlan-tag");
return TCPEDIT_ERROR;
}
if (config->vlan_pri < 255) {
vlan->vlan_priority_c_vid += htons((uint16_t)config->vlan_pri << 13);
} else if (extra->vlan) {
vlan->vlan_priority_c_vid += extra->vlan_pri;
} else {
tcpedit_seterr(ctx->tcpedit, "%s", "Non-VLAN tagged packet requires --enet-vlan-pri");
return TCPEDIT_ERROR;
}
if (config->vlan_cfi < 255) {
vlan->vlan_priority_c_vid += htons((uint16_t)config->vlan_cfi << 12);
} else if (extra->vlan) {
vlan->vlan_priority_c_vid += extra->vlan_cfi;
} else {
tcpedit_seterr(ctx->tcpedit, "%s", "Non-VLAN tagged packet requires --enet-vlan-cfi");
return TCPEDIT_ERROR;            
}        
} else {
tcpedit_seterr(ctx->tcpedit, "Unsupported new layer 2 length: %d", newl2len);
return TCPEDIT_ERROR;
}
return pktlen;
}

bool CWallet::CommitTransaction(CWalletTx& wtxNew, CReserveKey& reservekey)
{
{
LOCK2(cs_main, cs_wallet);
printf("CommitTransaction:\n%s", wtxNew.ToString().c_str());
{
CWalletDB* pwalletdb = fFileBacked ? new CWalletDB(strWalletFile,"r") : NULL;
reservekey.KeepKey();
AddToWallet(wtxNew);
set<CWalletTx*> setCoins;
BOOST_FOREACH(const CTxIn& txin, wtxNew.vin)
{
CWalletTx &coin = mapWallet[txin.prevout.hash];
coin.BindWallet(this);
coin.MarkSpent(txin.prevout.n);
coin.WriteToDisk();
NotifyTransactionChanged(this, coin.GetHash(), CT_UPDATED);
}
if (fFileBacked)
delete pwalletdb;
}
mapRequestCount[wtxNew.GetHash()] = 0;
if (!wtxNew.AcceptToMemoryPool())
{
printf("CommitTransaction() : Error: Transaction not valid");
return false;
}
wtxNew.RelayWalletTransaction();
}
return true;
}

const char *
Tss2_RC_Decode(TSS2_RC rc)
{
static __thread char buf[TSS2_ERR_LAYER_NAME_MAX + TSS2_ERR_LAYER_ERROR_STR_MAX + 1];
clearbuf(buf);
UINT8 layer = tss2_rc_layer_number_get(rc);
TSS2_RC_HANDLER handler = layer_handler[layer].handler;
const char *lname = layer_handler[layer].name;
if (lname[0]) {
catbuf(buf, "%s:", lname);
} else {
catbuf(buf, "%u:", layer);
}
handler = !handler ? unknown_layer_handler : handler;
UINT16 err_bits = tpm2_error_get(rc);
const char *e = err_bits ? handler(err_bits) : "success";
if (e) {
catbuf(buf, "%s", e);
} else {
catbuf(buf, "0x%X", err_bits);
}
return buf;
}

bool MakeSnippets ( CSphString sIndex, CSphVector<ExcerptQueryChained_t> & dQueries, CSphString & sError, ThdDesc_t & tThd )
{
SnippetsRemote_t dRemoteSnippets ( dQueries );
ExcerptQuery_t &q = *dQueries.begin ();
auto bScattered = !!( q.m_uFilesMode & 2 );
auto bNeedAllFiles = !!( q.m_uFilesMode & 1 );
auto pDist = GetDistr ( sIndex );
if ( pDist )
for ( auto * pAgent : pDist->m_dAgents )
{
auto * pConn = new AgentConn_t;
pConn->SetMultiAgent ( sIndex, pAgent );
pConn->m_iMyConnectTimeout = pDist->m_iAgentConnectTimeout;
pConn->m_iMyQueryTimeout = pDist->m_iAgentQueryTimeout;
dRemoteSnippets.m_dAgents.Add ( pConn );
}
bool bRemote = !dRemoteSnippets.m_dAgents.IsEmpty ();
if ( bRemote )
{
if ( pDist->m_dLocal.GetLength()!=1 )
{
sError.SetSprintf ( "%s", "The distributed index for snippets must have exactly one local agent" );
return false;
}
if ( !q.m_uFilesMode )
{
sError.SetSprintf ( "%s", "The distributed index for snippets available only when using external files" );
return false;
}
if ( g_iDistThreads<=1 && bScattered )
{
sError.SetSprintf ( "%s", "load_files_scattered works only together with dist_threads>1" );
return false;
}
sIndex = *pDist->m_dLocal.begin();
}
ServedDescRPtr_c pServed ( GetServed ( sIndex ) );
if ( !pServed || !pServed->m_pIndex )
{
sError.SetSprintf ( "unknown local index '%s' in search request", sIndex.cstr() );
return false;
}
CSphIndex * pIndex = pServed->m_pIndex;
assert ( pIndex );
SnippetContext_t tCtx;
if ( !tCtx.Setup ( pIndex, q, sError ) ) return false;
StringBuilder_c sErrors ( "; " );
if ( g_iDistThreads<=1 || dQueries.GetLength()<2 )
{
for ( auto & dQuery: dQueries )
{
tCtx.BuildExcerpt ( dQuery, pIndex );
sErrors << dQuery.m_sError;
}
sErrors.MoveTo (sError);
return sError.IsEmpty ();
}
ARRAY_FOREACH ( i, dQueries )
dQueries[i].m_iSeq = i;
for ( auto & dQuery : dQueries )
{
assert ( dQuery.m_iNext == PROCESSED_ITEM );
if ( dQuery.m_uFilesMode )
{
CSphString sFilename, sStatError;
sFilename.SetSprintf ( "%s%s", g_sSnippetsFilePrefix.cstr(), dQuery.m_sSource.scstr() );
auto iFileSize = sphGetFileSize (sFilename, &sStatError);
if ( iFileSize<0 )
{
if ( !bScattered )
{
sError = sStatError;
return false;
}
dQuery.m_iNext = EOF_ITEM;
} else
dQuery.m_iSize = -iFileSize; } else
dQuery.m_iSize = -dQuery.m_sSource.Length();
}
tThd.SetThreadInfo ( R"(snippet datasize=%.1Dk query="%s")",
GetSnippetDataSize ( dQueries ), dQueries[0].m_sWords.scstr () );
if ( !bScattered )
dQueries.Sort ( bind ( &ExcerptQueryChained_t::m_iSize ) );
int iAbsentHead = EOF_ITEM;
ARRAY_FOREACH ( i, dQueries )
if ( dQueries[i].m_iNext==EOF_ITEM )
{
dQueries[i].m_iNext = iAbsentHead;
iAbsentHead = i;
if ( bNeedAllFiles )
dQueries[i].m_sError.SetSprintf ( "absenthead: failed to stat %s: %s",
dQueries[i].m_sSource.cstr(), strerrorm(errno) );
}
if ( bScattered && iAbsentHead==EOF_ITEM )
bRemote = false;
auto * pPool = sphThreadPoolCreate ( g_iDistThreads - 1, "snippets", sError );
if ( !pPool )
sphWarning ( "failed to create thread_pool, single thread snippets used: %s", sError.cstr () );
CrashQuery_t tCrashQuery = SphCrashLogger_c::GetQuery (); CSphAtomic iCurQuery;
CSphVector<SnippetJob_t> dThreads ( Min ( 1, g_iDistThreads ) );
SnippetJob_t * pJobLocal = nullptr;
if ( !bRemote )
{
for ( auto & t : dThreads )
{
t.m_iQueries = dQueries.GetLength ();
t.m_pQueries = dQueries.Begin ();
t.m_pCurQuery = &iCurQuery;
t.m_pIndex = pIndex;
t.m_tCrashQuery = tCrashQuery;
if ( !pJobLocal )
pJobLocal = &t;
else if ( pPool )
pPool->AddJob ( &t );
}
if ( pJobLocal )
pJobLocal->Call();
SafeDelete ( pPool );
if ( !bScattered )
dQueries.Sort ( bind ( &ExcerptQueryChained_t::m_iSeq ) );
dQueries.Apply ( [&] ( const ExcerptQuery_t &dQuery ) { sErrors << dQuery.m_sError; } );
sErrors.MoveTo ( sError );
return sError.IsEmpty ();
}
int iRemoteAgents = dRemoteSnippets.m_dAgents.GetLength();
dRemoteSnippets.m_dTasks.Resize ( iRemoteAgents );
if ( bScattered )
{
assert ( iAbsentHead!=EOF_ITEM ); for ( auto & dTask : dRemoteSnippets.m_dTasks )
dTask.m_iHead = iAbsentHead;
} else
{
ARRAY_FOREACH ( i, dQueries )
{
auto & dHeadTask = *dRemoteSnippets.m_dTasks.begin();
dHeadTask.m_iTotal -= dQueries[i].m_iSize; dQueries[i].m_iNext = dHeadTask.m_iHead;
dHeadTask.m_iHead = i;
dRemoteSnippets.m_dTasks.Sort ( bind ( &SnippetChain_t::m_iTotal ) );
}
}
for ( auto &t : dThreads )
{
t.m_iQueries = dQueries.GetLength();
t.m_pQueries = dQueries.Begin();
t.m_pCurQuery = &iCurQuery;
t.m_pIndex = pIndex;
t.m_tCrashQuery = tCrashQuery;
if ( !pJobLocal )
pJobLocal = &t;
else if ( pPool )
pPool->AddJob ( &t );
}
SnippetRequestBuilder_c tReqBuilder ( &dRemoteSnippets );
SnippetReplyParser_c tParser ( &dRemoteSnippets );
CSphRefcountedPtr<RemoteAgentsObserver_i> tReporter ( GetObserver() );
ScheduleDistrJobs ( dRemoteSnippets.m_dAgents, &tReqBuilder, &tParser, tReporter );
if ( pJobLocal )
pJobLocal->Call ();
SafeDelete ( pPool );
tReporter->Finish ();
auto iSuccesses = ( int ) tReporter->GetSucceeded ();
auto iAgentsDone = ( int ) tReporter->GetFinished ();
if ( iSuccesses!=dRemoteSnippets.m_dAgents.GetLength() )
{
sphWarning ( "Remote snippets: some of the agents didn't answered: %d queried, %d finished, %d succeeded",
dRemoteSnippets.m_dAgents.GetLength(), iAgentsDone,iSuccesses );
if ( !bScattered )
{
int iFailed = 0;
dQueries.Apply ( [&] ( ExcerptQueryChained_t &dQuery ) {
if ( dQuery.m_iNext!=PROCESSED_ITEM )
{
dQuery.m_iNext = PROCESSED_ITEM;
++iFailed;
} else
dQuery.m_iNext = 0;
} );
if ( iFailed )
{
sphWarning ( "Snippets: failsafe for %d failed items", iFailed );
auto & t = dThreads[0];
t.m_pQueries = dQueries.Begin();
iCurQuery = 0;
t.Call();
}
}
}
if ( !bScattered )
dQueries.Sort ( bind ( &ExcerptQueryChained_t::m_iSeq ) );
dQueries.Apply ( [&] ( const ExcerptQuery_t &dQuery ) { sErrors << dQuery.m_sError;});
sErrors.MoveTo ( sError );
return sError.IsEmpty ();
}

R_API RBinJavaAttrInfo *r_bin_java_line_number_table_attr_new(ut8 *buffer, ut64 sz, ut64 buf_offset) {
ut32 i = 0;
ut64 curpos, offset = 0;
RBinJavaLineNumberAttribute *lnattr;
RBinJavaAttrInfo *attr = r_bin_java_default_attr_new (buffer, sz, buf_offset);
if (!attr) {
return NULL;
}
offset += 6;
attr->type = R_BIN_JAVA_ATTR_TYPE_LINE_NUMBER_TABLE_ATTR;
attr->info.line_number_table_attr.line_number_table_length = R_BIN_JAVA_USHORT (buffer, offset);
offset += 2;
attr->info.line_number_table_attr.line_number_table = r_list_newf (free);
ut32 linenum_len = attr->info.line_number_table_attr.line_number_table_length;
RList *linenum_list = attr->info.line_number_table_attr.line_number_table;
if (linenum_len > sz) {
free (attr);
return NULL;
}
for (i = 0; i < linenum_len; i++) {
curpos = buf_offset + offset;
lnattr = R_NEW0 (RBinJavaLineNumberAttribute);
if (!lnattr) {
break;
}
lnattr->start_pc = R_BIN_JAVA_USHORT (buffer, offset);
offset += 2;
lnattr->line_number = R_BIN_JAVA_USHORT (buffer, offset);
offset += 2;
lnattr->file_offset = curpos;
lnattr->size = 4;
r_list_append (linenum_list, lnattr);
}
attr->size = offset;
return attr;
}

int rpmPackageFilesInstall(rpmts ts, rpmte te, rpmfiles files,
rpmpsm psm, char ** failedFile)
{
FD_t payload = rpmtePayload(te);
rpmfi fi = NULL;
rpmfs fs = rpmteGetFileStates(te);
rpmPlugins plugins = rpmtsPlugins(ts);
int rc = 0;
int fx = -1;
int fc = rpmfilesFC(files);
int nodigest = (rpmtsFlags(ts) & RPMTRANS_FLAG_NOFILEDIGEST) ? 1 : 0;
int nofcaps = (rpmtsFlags(ts) & RPMTRANS_FLAG_NOCAPS) ? 1 : 0;
FD_t firstlinkfile = NULL;
char *tid = NULL;
struct filedata_s *fdata = xcalloc(fc, sizeof(*fdata));
struct filedata_s *firstlink = NULL;
rasprintf(&tid, ";%08x", (unsigned)rpmtsGetTid(ts));
fi = rpmfilesIter(files, RPMFI_ITER_FWD);
while (!rc && (fx = rpmfiNext(fi)) >= 0) {
struct filedata_s *fp = &fdata[fx];
if (rpmfiFFlags(fi) & RPMFILE_GHOST)
fp->action = FA_SKIP;
else
fp->action = rpmfsGetAction(fs, fx);
fp->skip = XFA_SKIPPING(fp->action);
fp->setmeta = 1;
if (XFA_CREATING(fp->action) && !S_ISDIR(rpmfiFMode(fi)))
fp->suffix = tid;
fp->fpath = fsmFsPath(fi, fp->suffix);
rc = rpmfiStat(fi, 1, &fp->sb);
setFileState(fs, fx);
fsmDebug(fp->fpath, fp->action, &fp->sb);
rc = rpmpluginsCallFsmFilePre(plugins, fi, fp->fpath,
fp->sb.st_mode, fp->action);
fp->stage = FILE_PRE;
}
fi = rpmfiFree(fi);
if (rc)
goto exit;
if (rpmteType(te) == TR_ADDED)
fi = rpmfiNewArchiveReader(payload, files, RPMFI_ITER_READ_ARCHIVE);
else
fi = rpmfilesIter(files, RPMFI_ITER_FWD);
if (fi == NULL) {
rc = RPMERR_BAD_MAGIC;
goto exit;
}
if (!rc)
rc = fsmMkdirs(files, fs, plugins);
while (!rc && (fx = rpmfiNext(fi)) >= 0) {
struct filedata_s *fp = &fdata[fx];
if (!fp->skip) {
if (!fp->suffix) {
rc = fsmBackup(fi, fp->action);
}
if (!fp->suffix) {
if (fp->action == FA_TOUCH) {
struct stat sb;
rc = fsmStat(fp->fpath, 1, &sb);
} else {
rc = fsmVerify(fp->fpath, fi);
}
} else {
rc = RPMERR_ENOENT;
}
if (rc == RPMERR_ENOENT && fp->action == FA_TOUCH) {
rpmlog(RPMLOG_DEBUG, "file %s vanished unexpectedly\n",
fp->fpath);
fp->action = FA_CREATE;
fsmDebug(fp->fpath, fp->action, &fp->sb);
}
if (fp->action == FA_TOUCH)
continue;
if (S_ISREG(fp->sb.st_mode)) {
if (rc == RPMERR_ENOENT) {
rc = fsmMkfile(fi, fp, files, psm, nodigest,
&firstlink, &firstlinkfile);
}
} else if (S_ISDIR(fp->sb.st_mode)) {
if (rc == RPMERR_ENOENT) {
mode_t mode = fp->sb.st_mode;
mode &= ~07777;
mode |=  00700;
rc = fsmMkdir(fp->fpath, mode);
}
} else if (S_ISLNK(fp->sb.st_mode)) {
if (rc == RPMERR_ENOENT) {
rc = fsmSymlink(rpmfiFLink(fi), fp->fpath);
}
} else if (S_ISFIFO(fp->sb.st_mode)) {
if (rc == RPMERR_ENOENT) {
rc = fsmMkfifo(fp->fpath, 0000);
}
} else if (S_ISCHR(fp->sb.st_mode) ||
S_ISBLK(fp->sb.st_mode) ||
S_ISSOCK(fp->sb.st_mode))
{
if (rc == RPMERR_ENOENT) {
rc = fsmMknod(fp->fpath, fp->sb.st_mode, fp->sb.st_rdev);
}
} else {
if (!IS_DEV_LOG(fp->fpath))
rc = RPMERR_UNKNOWN_FILETYPE;
}
} else if (firstlink && rpmfiArchiveHasContent(fi)) {
rc = fsmMkfile(fi, firstlink, files, psm, nodigest,
&firstlink, &firstlinkfile);
}
if (rc)
*failedFile = xstrdup(fp->fpath);
else
rpmpsmNotify(psm, RPMCALLBACK_INST_PROGRESS, rpmfiArchiveTell(fi));
fp->stage = FILE_UNPACK;
}
fi = rpmfiFree(fi);
if (!rc && fx < 0 && fx != RPMERR_ITER_END)
rc = fx;
fi = rpmfilesIter(files, RPMFI_ITER_FWD);
while (!rc && (fx = rpmfiNext(fi)) >= 0) {
struct filedata_s *fp = &fdata[fx];
if (!fp->skip && fp->setmeta) {
rc = fsmSetmeta(fp->fpath, fi, plugins, fp->action,
&fp->sb, nofcaps);
}
if (rc)
*failedFile = xstrdup(fp->fpath);
fp->stage = FILE_PREP;
}
fi = rpmfiFree(fi);
fi = rpmfilesIter(files, RPMFI_ITER_FWD);
while (!rc && (fx = rpmfiNext(fi)) >= 0) {
struct filedata_s *fp = &fdata[fx];
if (!fp->skip) {
if (!rc && fp->suffix)
rc = fsmBackup(fi, fp->action);
if (!rc)
rc = fsmCommit(&fp->fpath, fi, fp->action, fp->suffix);
if (!rc)
fp->stage = FILE_COMMIT;
else
*failedFile = xstrdup(fp->fpath);
}
}
fi = rpmfiFree(fi);
fi = rpmfilesIter(files, RPMFI_ITER_BACK);
while ((fx = rpmfiNext(fi)) >= 0) {
struct filedata_s *fp = &fdata[fx];
if (fp->stage) {
rpmpluginsCallFsmFilePost(plugins, fi, fp->fpath,
fp->sb.st_mode, fp->action, rc);
}
if (rc && fp->stage > FILE_NONE && !fp->skip) {
(void) fsmRemove(fp->fpath, fp->sb.st_mode);
}
}
rpmswAdd(rpmtsOp(ts, RPMTS_OP_UNCOMPRESS), fdOp(payload, FDSTAT_READ));
rpmswAdd(rpmtsOp(ts, RPMTS_OP_DIGEST), fdOp(payload, FDSTAT_DIGEST));
exit:
fi = rpmfiFree(fi);
Fclose(payload);
free(tid);
for (int i = 0; i < fc; i++)
free(fdata[i].fpath);
free(fdata);
return rc;
}

