void bta_av_rc_msg(tBTA_AV_CB* p_cb, tBTA_AV_DATA* p_data) {
tBTA_AV_EVT evt = 0;
tBTA_AV av;
BT_HDR* p_pkt = NULL;
tAVRC_MSG_VENDOR* p_vendor = &p_data->rc_msg.msg.vendor;
bool is_inquiry = ((p_data->rc_msg.msg.hdr.ctype == AVRC_CMD_SPEC_INQ) ||
p_data->rc_msg.msg.hdr.ctype == AVRC_CMD_GEN_INQ);
uint8_t ctype = 0;
tAVRC_RESPONSE rc_rsp;
rc_rsp.rsp.status = BTA_AV_STS_NO_RSP;
if (NULL == p_data) {
APPL_TRACE_ERROR("%s: Message from peer with no data", __func__);
return;
}
APPL_TRACE_DEBUG("%s: opcode=%x, ctype=%x", __func__, p_data->rc_msg.opcode,
p_data->rc_msg.msg.hdr.ctype);
if (p_data->rc_msg.opcode == AVRC_OP_PASS_THRU) {
if ((p_data->rc_msg.msg.hdr.ctype == AVRC_CMD_CTRL) ||
(p_data->rc_msg.msg.hdr.ctype == AVRC_CMD_SPEC_INQ) ||
(p_data->rc_msg.msg.hdr.ctype == AVRC_CMD_GEN_INQ)) {
char avrcp_ct_support[PROPERTY_VALUE_MAX];
osi_property_get("bluetooth.pts.avrcp_ct.support", avrcp_ct_support,
"false");
if (p_data->rc_msg.msg.pass.op_id == AVRC_ID_VENDOR) {
p_data->rc_msg.msg.hdr.ctype = AVRC_RSP_NOT_IMPL;
if (p_cb->features & BTA_AV_FEAT_METADATA)
p_data->rc_msg.msg.hdr.ctype = bta_av_group_navi_supported(
p_data->rc_msg.msg.pass.pass_len,
p_data->rc_msg.msg.pass.p_pass_data, is_inquiry);
} else if (((p_data->rc_msg.msg.pass.op_id == AVRC_ID_VOL_UP) ||
(p_data->rc_msg.msg.pass.op_id == AVRC_ID_VOL_DOWN)) &&
!strcmp(avrcp_ct_support, "true")) {
p_data->rc_msg.msg.hdr.ctype = AVRC_RSP_ACCEPT;
} else {
p_data->rc_msg.msg.hdr.ctype =
bta_av_op_supported(p_data->rc_msg.msg.pass.op_id, is_inquiry);
}
APPL_TRACE_DEBUG("%s: ctype %d", __func__, p_data->rc_msg.msg.hdr.ctype)
if (p_data->rc_msg.msg.hdr.ctype != AVRC_RSP_INTERIM)
AVRC_PassRsp(p_data->rc_msg.handle, p_data->rc_msg.label,
&p_data->rc_msg.msg.pass);
if (p_data->rc_msg.msg.hdr.ctype == AVRC_RSP_ACCEPT ||
p_data->rc_msg.msg.hdr.ctype == AVRC_RSP_INTERIM) {
evt = BTA_AV_REMOTE_CMD_EVT;
av.remote_cmd.rc_id = p_data->rc_msg.msg.pass.op_id;
av.remote_cmd.key_state = p_data->rc_msg.msg.pass.state;
av.remote_cmd.p_data = p_data->rc_msg.msg.pass.p_pass_data;
av.remote_cmd.len = p_data->rc_msg.msg.pass.pass_len;
memcpy(&av.remote_cmd.hdr, &p_data->rc_msg.msg.hdr, sizeof(tAVRC_HDR));
av.remote_cmd.label = p_data->rc_msg.label;
}
}
else if (p_data->rc_msg.msg.hdr.ctype >= AVRC_RSP_NOT_IMPL) {
evt = BTA_AV_REMOTE_RSP_EVT;
av.remote_rsp.rc_id = p_data->rc_msg.msg.pass.op_id;
av.remote_rsp.key_state = p_data->rc_msg.msg.pass.state;
av.remote_rsp.rsp_code = p_data->rc_msg.msg.hdr.ctype;
av.remote_rsp.label = p_data->rc_msg.label;
if ((p_data->rc_msg.msg.pass.op_id == AVRC_ID_VENDOR) &&
(p_data->rc_msg.msg.pass.pass_len > 0)) {
av.remote_rsp.p_data =
(uint8_t*)osi_malloc(p_data->rc_msg.msg.pass.pass_len);
APPL_TRACE_DEBUG("%s: Vendor Unique data len = %d", __func__,
p_data->rc_msg.msg.pass.pass_len);
memcpy(av.remote_rsp.p_data, p_data->rc_msg.msg.pass.p_pass_data,
p_data->rc_msg.msg.pass.pass_len);
}
}
else {
p_data->rc_msg.msg.hdr.ctype = AVRC_RSP_REJ;
AVRC_PassRsp(p_data->rc_msg.handle, p_data->rc_msg.label,
&p_data->rc_msg.msg.pass);
}
}
else if (p_data->rc_msg.opcode == AVRC_OP_VENDOR) {
av.vendor_cmd.code = p_data->rc_msg.msg.hdr.ctype;
av.vendor_cmd.company_id = p_vendor->company_id;
av.vendor_cmd.label = p_data->rc_msg.label;
av.vendor_cmd.p_data = p_vendor->p_vendor_data;
av.vendor_cmd.len = p_vendor->vendor_len;
if ((p_cb->features & BTA_AV_FEAT_VENDOR) &&
p_data->rc_msg.msg.hdr.ctype <= AVRC_CMD_GEN_INQ) {
if ((p_cb->features & BTA_AV_FEAT_METADATA) &&
(p_vendor->company_id == AVRC_CO_METADATA)) {
av.meta_msg.p_msg = &p_data->rc_msg.msg;
rc_rsp.rsp.status = BTA_AV_STS_NO_RSP;
evt = bta_av_proc_meta_cmd(&rc_rsp, &p_data->rc_msg, &ctype);
} else {
evt = BTA_AV_VENDOR_CMD_EVT;
}
} else if ((p_cb->features & BTA_AV_FEAT_VENDOR) &&
p_data->rc_msg.msg.hdr.ctype >= AVRC_RSP_NOT_IMPL) {
if ((p_cb->features & BTA_AV_FEAT_METADATA) &&
(p_vendor->company_id == AVRC_CO_METADATA)) {
av.meta_msg.p_msg = &p_data->rc_msg.msg;
evt = BTA_AV_META_MSG_EVT;
} else {
evt = BTA_AV_VENDOR_RSP_EVT;
}
} else if (!(p_cb->features & BTA_AV_FEAT_VENDOR) &&
p_data->rc_msg.msg.hdr.ctype <= AVRC_CMD_GEN_INQ) {
if (p_data->rc_msg.msg.vendor.p_vendor_data[0] == AVRC_PDU_INVALID) {
p_data->rc_msg.msg.hdr.ctype = AVRC_RSP_REJ;
p_data->rc_msg.msg.vendor.p_vendor_data[4] = AVRC_STS_BAD_CMD;
} else {
p_data->rc_msg.msg.hdr.ctype = AVRC_RSP_NOT_IMPL;
}
AVRC_VendorRsp(p_data->rc_msg.handle, p_data->rc_msg.label,
&p_data->rc_msg.msg.vendor);
}
} else if (p_data->rc_msg.opcode == AVRC_OP_BROWSE) {
av.meta_msg.rc_handle = p_data->rc_msg.handle;
av.meta_msg.company_id = p_vendor->company_id;
av.meta_msg.code = p_data->rc_msg.msg.hdr.ctype;
av.meta_msg.label = p_data->rc_msg.label;
av.meta_msg.p_msg = &p_data->rc_msg.msg;
av.meta_msg.p_data = p_data->rc_msg.msg.browse.p_browse_data;
av.meta_msg.len = p_data->rc_msg.msg.browse.browse_len;
evt = BTA_AV_META_MSG_EVT;
}
if (evt == 0 && rc_rsp.rsp.status != BTA_AV_STS_NO_RSP) {
if (!p_pkt) {
rc_rsp.rsp.opcode = p_data->rc_msg.opcode;
AVRC_BldResponse(0, &rc_rsp, &p_pkt);
}
if (p_pkt)
AVRC_MsgReq(p_data->rc_msg.handle, p_data->rc_msg.label, ctype, p_pkt);
}
if (evt != 0) {
av.remote_cmd.rc_handle = p_data->rc_msg.handle;
(*p_cb->p_cback)(evt, &av);
bta_av_rc_free_browse_msg(p_cb, p_data);
}
}

static int
decode_R13_R2000 (Bit_Chain *restrict dat, Dwg_Data *restrict dwg)
{
Dwg_Object *obj = NULL;
unsigned int section_size = 0;
unsigned char sgdc[2];
unsigned int crc, crc2;
long unsigned int size;
long unsigned int endpos;
long unsigned int lastmap;
long unsigned int startpos;
long unsigned int object_begin;
long unsigned int object_end;
long unsigned int pvz;
BITCODE_BL j, k;
int error = 0;
const char *section_names[]
= { "AcDb:Header", "AcDb:Classes",  "AcDb:Handles",
"2NDHEADER",   "AcDb:Template", "AcDb:AuxHeader" };
{
int i;
Dwg_Header *_obj = &dwg->header;
Bit_Chain *hdl_dat = dat;
dat->byte = 0x06;
#include "header.spec"
}
if (dat->byte != 0x15)
{
LOG_ERROR ("Wrong HEADER Section Locator Records at %lu", dat->byte)
return DWG_ERR_INVALIDDWG;
}
assert (dat->byte == 0x15);
dwg->header.numsections = bit_read_RL (dat);
LOG_TRACE ("\nnum_sections: " FORMAT_RL " [RL]\n", dwg->header.numsections)
if ((error = dwg_sections_init (dwg)))
return error;
for (j = 0; j < dwg->header.numsections; j++)
{
dwg->header.section[j].number = bit_read_RC (dat);
dwg->header.section[j].address = bit_read_RL (dat);
dwg->header.section[j].size = bit_read_RL (dat);
if (j < 6)
strcpy (dwg->header.section[j].name, section_names[j]);
LOG_TRACE ("section[%u].number:  %4d [RC] %s\n", j,
(int)dwg->header.section[j].number,
dwg->header.section[j].name)
LOG_TRACE ("section[%u].address: %4u [RL]\n", j,
(unsigned)dwg->header.section[j].address)
LOG_TRACE ("section[%u].size:    %4u [RL]\n", j,
(unsigned)dwg->header.section[j].size);
if (dwg->header.section[j].address + dwg->header.section[j].size
> dat->size)
{
LOG_ERROR ("section[%u] address or size overflow: %lu + %u > %lu", j,
(unsigned long)dwg->header.section[j].address,
dwg->header.section[j].size, dat->size);
return DWG_ERR_INVALIDDWG;
}
}
crc2 = bit_calc_CRC (0xC0C1, &dat->chain[0], dat->byte);   crc = bit_read_RS (dat);
LOG_TRACE ("crc: %04X [RSx] from 0-%lu\n", crc, dat->byte - 2);
if (crc != crc2)
{
LOG_ERROR ("Header CRC mismatch %04X <=> %04X", crc, crc2);
error |= DWG_ERR_WRONGCRC;
}
if (bit_search_sentinel (dat, dwg_sentinel (DWG_SENTINEL_HEADER_END)))
LOG_TRACE ("         HEADER (end):    %4u\n", (unsigned)dat->byte)
if (dwg->header.numsections == 6 && dwg->header.version >= R_13c3)
{
int i;
Dwg_AuxHeader *_obj = &dwg->auxheader;
Bit_Chain *hdl_dat = dat;
BITCODE_BL end_address
= dwg->header.section[SECTION_AUXHEADER_R2000].address
+ dwg->header.section[SECTION_AUXHEADER_R2000].size;
obj = NULL;
dat->byte = dwg->header.section[SECTION_AUXHEADER_R2000].address;
LOG_TRACE ("\n"
"=======> AuxHeader:       %4u\n",
(unsigned)dat->byte)
LOG_TRACE ("         AuxHeader (end): %4u\n", (unsigned)end_address)
if (dat->size < end_address)
{
LOG_ERROR ("Invalid AuxHeader size: buffer overflow")
error |= DWG_ERR_SECTIONNOTFOUND;
}
else
{
BITCODE_BL old_size = dat->size;
BITCODE_BL vcount;
dat->size = end_address;
#include "auxheader.spec"
dat->size = old_size;
}
}
if (bit_search_sentinel (dat, dwg_sentinel (DWG_SENTINEL_THUMBNAIL_BEGIN)))
{
unsigned long int start_address;
dat->bit = 0;
start_address = dat->byte;
LOG_TRACE ("\n=======> Thumbnail:       %4u\n",
(unsigned int)start_address - 16);
if (dwg->header.thumbnail_address
&& dwg->header.thumbnail_address != dat->byte - 16)
LOG_WARN ("Illegal HEADER.thumbnail_address: %i != %lu",
dwg->header.thumbnail_address, dat->byte - 16)
dwg->header.thumbnail_address = dat->byte - 16;
if (bit_search_sentinel (dat, dwg_sentinel (DWG_SENTINEL_THUMBNAIL_END)))
{
BITCODE_RL bmpsize;
LOG_TRACE ("         Thumbnail (end): %4u\n",
(unsigned int)dat->byte)
if ((dat->byte - 16) < start_address)
{
LOG_ERROR ("Illegal HEADER.thumbnail_size: %lu < %lu",
dat->byte - 16, start_address);
}
else if ((dat->byte - 16) - start_address < 10)
{
LOG_TRACE ("No HEADER.thumbnail: %lu < 10",
dat->byte - 16 - start_address);
}
else
{
assert ((dat->byte - 16) >= start_address);
dwg->thumbnail.size = (dat->byte - 16) - start_address;
dwg->thumbnail.chain
= (unsigned char *)calloc (dwg->thumbnail.size, 1);
dwg->thumbnail.byte = 0;
if (!dwg->thumbnail.chain)
{
LOG_ERROR ("Out of memory");
return DWG_ERR_OUTOFMEM;
}
memcpy (dwg->thumbnail.chain, &dat->chain[start_address],
dwg->thumbnail.size);
dat->byte += dwg->thumbnail.size;
dwg_bmp (dwg, &bmpsize);
if (bmpsize > dwg->thumbnail.size)
LOG_ERROR ("BMP size overflow: %i > %lu\n", bmpsize,
dwg->thumbnail.size)
}
}
}
LOG_INFO ("\n"
"=======> Header Variables:         %4u\n",
(unsigned int)dwg->header.section[SECTION_HEADER_R13].address)
LOG_INFO ("         Header Variables   (end): %4u\n",
(unsigned int)(dwg->header.section[SECTION_HEADER_R13].address
+ dwg->header.section[SECTION_HEADER_R13].size))
if (dwg->header.section[SECTION_HEADER_R13].address < 58
|| dwg->header.section[SECTION_HEADER_R13].address
+ dwg->header.section[SECTION_HEADER_R13].size
> dat->size)
{
LOG_ERROR ("Invalid Header section, skipped")
error |= DWG_ERR_SECTIONNOTFOUND;
goto classes_section;
}
dat->byte = pvz = dwg->header.section[SECTION_HEADER_R13].address + 16;
#define MAX_HEADER_SIZE 2048
dwg->header_vars.size = bit_read_RL (dat);
LOG_TRACE ("         Length: " FORMAT_RL " [RL]\n", dwg->header_vars.size)
if (dwg->header_vars.size > MAX_HEADER_SIZE)
{
LOG_WARN ("Fixup illegal Header Length");
dwg->header_vars.size = dwg->header.section[SECTION_HEADER_R13].size;
if (dwg->header_vars.size > 20)
dwg->header_vars.size -= 16 + 4;
}
dat->bit = 0;
error |= dwg_decode_header_variables (dat, dat, dat, dwg);
if (dwg->header_vars.size < MAX_HEADER_SIZE)
{
unsigned long crcpos = pvz + dwg->header_vars.size + 4;
if (dat->bit || dat->byte != crcpos)
{
unsigned char r = 8 - dat->bit;
LOG_HANDLE (" padding: %ld byte, %d bits\n", crcpos - dat->byte, r);
}
LOG_HANDLE (" crc pos: %lu\n", crcpos);
bit_set_position (dat, crcpos * 8);
crc = bit_read_RS (dat);
LOG_TRACE ("crc: %04X [RSx] from %lu-%lu=%ld\n", crc, pvz, dat->byte - 2,
dat->byte - 2 - pvz);
}
else
{
LOG_WARN ("Skip crc with illegal Header Length");
error |= DWG_ERR_SECTIONNOTFOUND;
goto classes_section;
}
crc2 = 0;
if (dwg->header.section[SECTION_HEADER_R13].size > 34
&& dwg->header.section[SECTION_HEADER_R13].size < 0xfff
&& pvz < dat->byte
&& pvz + dwg->header.section[SECTION_HEADER_R13].size < dat->size)
{
BITCODE_RL crc_size = dwg->header.section[SECTION_HEADER_R13].size - 34;
LOG_HANDLE (" calc Header crc size: " FORMAT_RL "\n", crc_size);
crc2 = bit_calc_CRC (0xC0C1, &dat->chain[pvz], crc_size);
}
if (crc != crc2)
{
LOG_WARN ("Header Section[%ld] CRC mismatch %04X <=> %04X",
(long)dwg->header.section[SECTION_HEADER_R13].number, crc,
crc2);
error |= DWG_ERR_WRONGCRC;
}
classes_section:
LOG_INFO ("\n"
"=======> Classes (start): %4lu\n",
(long)dwg->header.section[SECTION_CLASSES_R13].address)
LOG_INFO ("         Classes (end)  : %4lu\n",
(long)(dwg->header.section[SECTION_CLASSES_R13].address
+ dwg->header.section[SECTION_CLASSES_R13].size))
LOG_INFO ("         Length         : %4lu\n",
(long)dwg->header.section[SECTION_CLASSES_R13].size)
dat->byte = dwg->header.section[SECTION_CLASSES_R13].address;
if (dat->byte + 16 > dat->size
|| dwg->header.section[SECTION_CLASSES_R13].address
+ dwg->header.section[SECTION_CLASSES_R13].size
> dat->size)
{
LOG_ERROR ("Invalid Classes section, skipped")
error |= DWG_ERR_SECTIONNOTFOUND;
goto handles_section;
}
if (memcmp (dwg_sentinel (DWG_SENTINEL_CLASS_BEGIN), &dat->chain[dat->byte],
16)
== 0)
dat->byte += 16;
else
LOG_TRACE ("no class sentinel\n");
dat->bit = 0;
size = bit_read_RL (dat);
LOG_TRACE ("         Size : %lu [RL]\n", size)
if (size != dwg->header.section[SECTION_CLASSES_R13].size - 38)
{
endpos = dwg->header.section[SECTION_CLASSES_R13].address
+ dwg->header.section[SECTION_CLASSES_R13].size - 16;
LOG_WARN ("Invalid size %lu, should be: " FORMAT_RL ", endpos: %lu\n",
size, dwg->header.section[SECTION_CLASSES_R13].size - 38,
endpos)
}
else
endpos = dat->byte + size;
LOG_INSANE ("endpos: %lu", endpos);
LOG_POS_ (INSANE);
dwg->layout_type = 0;
dwg->num_classes = 0;
#if 0
SINCE (R_2004) {     BITCODE_B btrue;
BITCODE_BL max_num = bit_read_BL (dat);
LOG_TRACE ("2004 max_num: " FORMAT_BL " [BL]\n", max_num);
btrue = bit_read_B (dat);     LOG_TRACE ("2004 btrue: " FORMAT_B " [B]\n", btrue);
}
#endif
while (dat->byte < endpos - 1)
{
BITCODE_BS i;
Dwg_Class *klass;
i = dwg->num_classes;
if (i == 0)
dwg->dwg_class = (Dwg_Class *)malloc (sizeof (Dwg_Class));
else
dwg->dwg_class = (Dwg_Class *)realloc (dwg->dwg_class,
(i + 1) * sizeof (Dwg_Class));
if (!dwg->dwg_class)
{
LOG_ERROR ("Out of memory");
return DWG_ERR_OUTOFMEM;
}
klass = &dwg->dwg_class[i];
memset (klass, 0, sizeof (Dwg_Class));
klass->number = bit_read_BS (dat);
LOG_HANDLE ("number: " FORMAT_BS " [BS] ", klass->number);
LOG_POS_ (HANDLE);
klass->proxyflag = bit_read_BS (dat);
LOG_HANDLE ("proxyflag: " FORMAT_BS " [BS] ", klass->proxyflag);
LOG_POS_ (HANDLE);
dwg_log_proxyflag (DWG_LOGLEVEL, DWG_LOGLEVEL_HANDLE, klass->proxyflag);
if (dat->byte >= endpos)
break;
klass->appname = bit_read_TV (dat);
LOG_HANDLE ("appname: %s [TV] ", klass->appname);
LOG_POS_ (HANDLE);
if (dat->byte >= endpos)
{
free (klass->appname);
break;
}
LOG_HANDLE ("\n  ");
klass->cppname = bit_read_TV (dat);
LOG_HANDLE ("cppname: %s [TV] ", klass->cppname);
LOG_POS_ (HANDLE);
klass->dxfname = bit_read_TV (dat);
LOG_HANDLE ("dxfname: %s [TV] ", klass->dxfname);
LOG_POS_ (HANDLE);
klass->is_zombie = bit_read_B (dat);       LOG_HANDLE ("is_zombie: " FORMAT_B " [B] ", klass->is_zombie);
LOG_POS_ (HANDLE);
klass->item_class_id = bit_read_BS (dat);
LOG_HANDLE ("item_class_id: " FORMAT_BS " [BS]", klass->item_class_id);
LOG_POS_ (HANDLE);
LOG_HANDLE ("\n");
if (DWG_LOGLEVEL == DWG_LOGLEVEL_TRACE)
{
LOG (TRACE,
"Class %d 0x%x %s\n"
" %s \"%s\" %d 0x%x\n",
klass->number, klass->proxyflag, klass->dxfname, klass->cppname,
klass->appname, klass->is_zombie, klass->item_class_id)
}
#if 0
SINCE (R_2007)       {
klass->num_instances = bit_read_BL (dat);
LOG_HANDLE ("num_instances: " FORMAT_BL " [BL]", klass->num_instances); LOG_POS_ (HANDLE);
klass->dwg_version = bit_read_BL (dat);         klass->maint_version = bit_read_BL (dat);
klass->unknown_1 = bit_read_BL (dat);
klass->unknown_2 = bit_read_BL (dat);
LOG_TRACE (
" num_instances: %d, dwg/maint version: %d/%d, unk: %d/%d\n",
klass->num_instances, klass->dwg_version, klass->maint_version,
klass->unknown_1, klass->unknown_2);
}
#endif
if (klass->dxfname && strEQc ((const char *)klass->dxfname, "LAYOUT"))
dwg->layout_type = klass->number;
dwg->num_classes++;
if (dwg->num_classes > 500)
{
LOG_ERROR ("number of classes is greater than 500");
break;
}
}
dat->byte = dwg->header.section[SECTION_CLASSES_R13].address
+ dwg->header.section[SECTION_CLASSES_R13].size - 18;
dat->bit = 0;
pvz = dwg->header.section[SECTION_CLASSES_R13].address + 16;
if (!bit_check_CRC (dat, pvz, 0xC0C1))
error |= DWG_ERR_WRONGCRC;
dat->byte += 16;           pvz = bit_read_RL (dat);   LOG_TRACE ("unknown: 0x%04lx [RL] @%lu\n", pvz, dat->byte - 4)
LOG_INFO ("Number of classes read: %u\n", dwg->num_classes)
handles_section:
dat->byte = dwg->header.section[SECTION_HANDLES_R13].address;
dat->bit = 0;
lastmap = dat->byte + dwg->header.section[SECTION_HANDLES_R13].size;   dwg->num_objects = 0;
object_begin = dat->size;
object_end = 0;
LOG_INFO ("\n"
"=======> Handles (start) : %8u\n",
(unsigned int)dwg->header.section[SECTION_HANDLES_R13].address)
LOG_INFO ("         Handles (end)   : %8u\n",
(unsigned int)(dwg->header.section[SECTION_HANDLES_R13].address
+ dwg->header.section[SECTION_HANDLES_R13].size))
LOG_INFO ("         Length: %u\n",
(unsigned int)dwg->header.section[SECTION_HANDLES_R13].size)
do
{
long unsigned int last_offset = 0;
long unsigned int last_handle = 0;
long unsigned int oldpos = 0;
long unsigned int maxh
= (unsigned long)dwg->header.section[SECTION_HANDLES_R13].size << 1;
BITCODE_BL max_handles
= maxh < INT32_MAX ? (BITCODE_BL)maxh
: dwg->header.section[SECTION_HANDLES_R13].size;
int added;
startpos = dat->byte;
section_size = bit_read_RS_LE (dat);
LOG_TRACE ("Handles page size: %u [RS_LE] @%lu\n", section_size,
startpos);
if (section_size > 2040)
{
LOG_ERROR ("Object-map section size greater than 2040!")
return DWG_ERR_VALUEOUTOFBOUNDS;
}
while (dat->byte - startpos < section_size)
{
BITCODE_UMC handleoff;
BITCODE_MC offset;
oldpos = dat->byte;
handleoff = bit_read_UMC (dat);
offset = bit_read_MC (dat);
if ((handleoff == 0) || (handleoff > (max_handles - last_handle)))
{
BITCODE_MC prevsize
= dwg->num_objects ? dwg->object[dwg->num_objects - 1].size
: 0L;
LOG_WARN ("handleoff %lu looks wrong, max_handles %u - "
"last_handle %lu = %lu (@%lu)",
handleoff, (unsigned)max_handles, last_handle,
max_handles - last_handle, oldpos);
if (offset == 1
|| (offset > 0 && offset < prevsize && prevsize > 0)
|| (offset < 0 && labs ((long)offset) < prevsize
&& prevsize > 0))
{
if (offset != prevsize)
LOG_WARN ("offset %ld looks wrong, should be prevsize %ld",
offset, prevsize);
}
}
last_offset += offset;
LOG_TRACE ("\nNext object: %lu ", (unsigned long)dwg->num_objects)
LOG_TRACE ("Handleoff: %lX [UMC] Offset: " FORMAT_MC " [MC]",
handleoff, offset)
LOG_HANDLE (" @%lu", last_offset)
LOG_TRACE ("\n")
if (dat->byte == oldpos)
break;
if (object_end < last_offset)
object_end = last_offset;
if (object_begin > last_offset)
object_begin = last_offset;
added = dwg_decode_add_object (dwg, dat, dat, last_offset);
if (added > 0)
error |= added;           if (dwg->num_objects)
last_handle = dwg->object[dwg->num_objects - 1].handle.value;
}
if (dat->byte == oldpos)
break;
if (dat->bit > 0)
{
dat->byte += 1;
dat->bit = 0;
}
if (dat->byte >= dat->size)
{
LOG_ERROR ("Handles overflow @%lu", dat->byte)
return DWG_ERR_VALUEOUTOFBOUNDS;
}
crc = bit_read_RS_LE (dat);
LOG_TRACE ("\nHandles page crc: %04X [RS_LE] (%lu-%lu = %u)\n", crc,
startpos, startpos + section_size, section_size);
crc2 = bit_calc_CRC (0xC0C1, dat->chain + startpos, section_size);
if (crc != crc2)
{
LOG_ERROR ("Handles Section[%ld] page CRC mismatch %04X <=> %04X",
(long)dwg->header.section[SECTION_HANDLES_R13].number,
crc, crc2);
if (dat->from_version != R_14)
error |= DWG_ERR_WRONGCRC;
}
if (dat->byte >= lastmap)
break;
}
while (section_size > 2);
LOG_INFO ("Num objects: %lu\n", (unsigned long)dwg->num_objects)
LOG_INFO ("\n"
"=======> Last Object      : %8lu\n",
(unsigned long)object_begin)
if (object_end <= dat->size)
dat->byte = object_end;
object_begin = bit_read_MS (dat);
LOG_TRACE ("last object size: %lu [MS] (@%lu)\n", object_begin, object_end)
LOG_INFO ("         Last Object (end): %8lu\n",
(unsigned long)(object_end + object_begin + 2))
if (bit_search_sentinel (dat,
dwg_sentinel (DWG_SENTINEL_SECOND_HEADER_BEGIN)))
{
BITCODE_RL i;
BITCODE_RC sig, sig2;
BITCODE_BL vcount;
long unsigned int pvzadr;
struct _dwg_second_header *_obj = &dwg->second_header;
obj = NULL;
LOG_INFO ("\n"
"=======> Second Header 3 (start): %8u\n",
(unsigned int)dat->byte - 16)
pvzadr = dat->byte;
LOG_TRACE ("pvzadr: %lx\n", pvzadr)
FIELD_RL (size, 0);
FIELD_BLx (address, 0);
if (dwg->header.numsections <= SECTION_2NDHEADER_R13)
{
LOG_WARN (
"Only %d num_sections, but 2ndheader found, extending to 4",
dwg->header.numsections);
dwg->header.numsections = SECTION_2NDHEADER_R13 + 1; 
dwg->header.section = (Dwg_Section *)realloc (
dwg->header.section,
dwg->header.numsections * sizeof (Dwg_Section));
memset (&dwg->header.section[SECTION_2NDHEADER_R13], 0,
sizeof (Dwg_Section));
}
if (!dwg->header.section[SECTION_2NDHEADER_R13].address)
{
dwg->header.section[SECTION_2NDHEADER_R13].address
= dwg->second_header.address;
dwg->header.section[SECTION_2NDHEADER_R13].size
= dwg->second_header.size;
}
bit_read_fixed (dat, _obj->version, 12);
LOG_TRACE ("version: %s [TFF 12]\n", _obj->version)
for (i = 0; i < 4; i++)
FIELD_B (null_b[i], 0);
FIELD_RC (unknown_10, 0);       for (i = 0; i < 4; i++)
FIELD_RC (unknown_rc4[i], 0);
if (dat->from_version < R_2000 && FIELD_VALUE (unknown_10) == 0x18
&& FIELD_VALUE (unknown_rc4[0]) == 0x78)
dat->byte -= 2;
UNTIL (R_2000)
{
FIELD_RC (num_sections, 0);         for (i = 0; i < MIN (6, FIELD_VALUE (num_sections)); i++)
{
FIELD_RC (section[i].nr, 0);
FIELD_BLx (section[i].address, 0);
FIELD_BL (section[i].size, 0);
}
if (DWG_LOGLEVEL >= DWG_LOGLEVEL_HANDLE)
{
LOG_HANDLE ("1st header was:\n");
for (i = 0; i < dwg->header.numsections; i++)
{
LOG_HANDLE ("section[" FORMAT_RL "] " FORMAT_RLd " " FORMAT_RLL
" " FORMAT_RL " \n",
i, dwg->header.section[i].number,
dwg->header.section[i].address,
dwg->header.section[i].size);
}
LOG_HANDLE ("start 3: %lu\n", pvzadr - 16);
}
FIELD_BS (num_handlers, 0);         if (FIELD_VALUE (num_handlers) > 16)
{
LOG_ERROR ("Second header num_handlers > 16: %d\n",
FIELD_VALUE (num_handlers));
FIELD_VALUE (num_handlers) = 14;
}
for (i = 0; i < FIELD_VALUE (num_handlers); i++)
{
FIELD_RC (handlers[i].size, 0);
FIELD_RC (handlers[i].nr, 0);
FIELD_VECTOR (handlers[i].data, RC, handlers[i].size, 0);
}
crc = bit_read_CRC (dat);
LOG_TRACE ("crc: %04X\n", crc);
VERSION (R_14)
{
FIELD_RL (junk_r14_1, 0);
FIELD_RL (junk_r14_2, 0);
}
}
if (bit_search_sentinel (dat,
dwg_sentinel (DWG_SENTINEL_SECOND_HEADER_END)))
LOG_INFO ("         Second Header 3 (end)  : %8u\n",
(unsigned int)dat->byte)
}
if (dwg->header.numsections > 4)
{
BITCODE_RL v;
LOG_INFO ("\n"
"=======> MEASUREMENT 4 (start)  : %8u\n",
(unsigned int)dwg->header.section[4].address)
LOG_INFO ("         MEASUREMENT 4 (end)    : %8u\n",
(unsigned int)(dwg->header.section[4].address
+ dwg->header.section[4].size))
dat->byte = dwg->header.section[4].address;
dat->bit = 0;
v = bit_read_RL_LE (dat);
LOG_TRACE ("MEASUREMENT: " FORMAT_RL " [RL_LE] (0 English/256 Metric)\n",
v);
dwg->header_vars.MEASUREMENT = v ? 1 : 0;
}
LOG_INFO ("\nnum_objects: %lu\n", (unsigned long)dwg->num_objects)
LOG_TRACE ("num_object_refs: %lu\n", (unsigned long)dwg->num_object_refs)
LOG_TRACE ("Resolving pointers from ObjectRef vector:\n")
error |= resolve_objectref_vector (dat, dwg);
return error;
}

static ut64 estimate_slide(RBinFile *bf, RDyldCache *cache, ut64 value_mask, ut64 value_add) {
ut64 slide = 0;
if (cache->n_hdr > 1) {
return slide;
}
ut64 *classlist = malloc (64);
if (!classlist) {
goto beach;
}
RListIter *iter;
RDyldBinImage *bin;
r_list_foreach (cache->bins, iter, bin) {
bool found_sample = false;
struct MACH0_(opts_t) opts = {0};
opts.verbose = bf->rbin->verbose;
opts.header_at = bin->header_at;
opts.symbols_off = 0;
struct MACH0_(obj_t) *mach0 = MACH0_(new_buf) (cache->buf, &opts);
if (!mach0) {
goto beach;
}
struct section_t *sections = NULL;
if (!(sections = MACH0_(get_sections) (mach0))) {
MACH0_(mach0_free) (mach0);
goto beach;
}
int i;
int incomplete = 2;
int classlist_idx = 0, data_idx = 0;
for (i = 0; !sections[i].last && incomplete; i++) {
if (sections[i].size == 0) {
continue;
}
if (strstr (sections[i].name, "__objc_classlist")) {
incomplete--;
classlist_idx = i;
continue;
}
if (strstr (sections[i].name, "__objc_data")) {
incomplete--;
data_idx = i;
continue;
}
}
if (incomplete) {
goto next_bin;
}
int classlist_sample_size = R_MIN (64, sections[classlist_idx].size);
int n_classes = classlist_sample_size / 8;
ut64 sect_offset = sections[classlist_idx].offset + bin->hdr_offset;
if (r_buf_fread_at (cache->buf, sect_offset, (ut8*) classlist, "l", n_classes) < classlist_sample_size) {
goto next_bin;
}
ut64 data_addr = sections[data_idx].addr;
ut64 data_tail = data_addr & 0xfff;
ut64 data_tail_end = (data_addr + sections[data_idx].size) & 0xfff;
for (i = 0; i < n_classes; i++) {
ut64 cl_addr = (classlist[i] & value_mask) + value_add;
ut64 cl_tail = cl_addr & 0xfff;
if (cl_tail >= data_tail && cl_tail < data_tail_end) {
ut64 off = cl_tail - data_tail;
slide = ((cl_addr - off) & value_mask) - (data_addr & value_mask);
found_sample = true;
break;
}
}
next_bin:
MACH0_(mach0_free) (mach0);
R_FREE (sections);
if (found_sample) {
break;
}
}
beach:
R_FREE (classlist);
return slide;
}

void Compile(XlaOpKernelContext* ctx) override {
if (ctx->num_inputs() != 3) {
OP_REQUIRES(
ctx, ctx->num_inputs() == 5,
errors::InvalidArgument("Must supply ksize and stride arguments."));
const TensorShape ksize_shape = ctx->InputShape(3);
OP_REQUIRES(ctx, TensorShapeUtils::IsVector(ksize_shape),
errors::InvalidArgument("ksize must be a vector, not shape ",
ksize_shape.DebugString()));
OP_REQUIRES_OK(ctx, ctx->ConstantInputAsIntVector(3, &ksize_));
const TensorShape stride_shape = ctx->InputShape(4);
OP_REQUIRES(ctx, TensorShapeUtils::IsVector(stride_shape),
errors::InvalidArgument("stride must be a vector, not shape ",
stride_shape.DebugString()));
OP_REQUIRES_OK(ctx, ctx->ConstantInputAsIntVector(4, &stride_));
}
OP_REQUIRES(ctx, ksize_.size() == num_dims(),
errors::InvalidArgument("Sliding window ksize field must "
"specify ",
num_dims(), " dimensions"));
OP_REQUIRES(ctx, stride_.size() == num_dims(),
errors::InvalidArgument("Sliding window strides field must "
"specify ",
num_dims(), " dimensions"));
const TensorShape tensor_in_shape = ctx->InputShape(0);
const TensorShape tensor_out_shape = ctx->InputShape(1);
const TensorShape out_backprop_shape = ctx->InputShape(2);
OP_REQUIRES(ctx, tensor_in_shape.dims() == num_dims(),
errors::InvalidArgument("tensor_in must be ", num_dims(),
"-dimensional"));
OP_REQUIRES(ctx, tensor_out_shape.dims() == num_dims(),
errors::InvalidArgument("tensor_out must be ", num_dims(),
"-dimensional"));
OP_REQUIRES(ctx, out_backprop_shape.dims() == num_dims(),
errors::InvalidArgument("out_backprop must be ", num_dims(),
"-dimensional"));
auto input = ctx->Input(0);
auto out_backprop = ctx->Input(2);
auto b = ctx->builder();
auto sixteen = xla::ConstantR0<uint32>(b, 16);
auto in_hi = xla::BitcastConvertType(
xla::ReducePrecision(input, 8, 7),
xla::U32);
auto bp_int = xla::BitcastConvertType(out_backprop, xla::U32);
auto bp_hi = xla::ShiftRightLogical(bp_int, sixteen);
auto bp_lo =
xla::ShiftRightLogical(xla::ShiftLeft(bp_int, sixteen), sixteen);
auto in_hi_bp_hi = xla::Add(in_hi, bp_hi);      auto in_hi_bp_lo = xla::Add(in_hi, bp_lo);  
auto init_value = xla::MinValue(b, xla::F32);
auto rb = b->CreateSubBuilder("GreaterOrEqOf_ByFirst16Bits");
{
const xla::Shape scalar = xla::ShapeUtil::MakeShape(xla::F32, {});
auto lhs = xla::Parameter(rb.get(), 0, scalar, "lhs");
auto rhs = xla::Parameter(rb.get(), 1, scalar, "rhs");
auto sixteen = xla::ConstantR0<int32>(rb.get(), 16);
auto lhs_criteria =
xla::ShiftLeft(xla::ShiftRightLogical(
xla::BitcastConvertType(lhs, xla::S32), sixteen),
sixteen);
auto rhs_criteria =
xla::ShiftLeft(xla::ShiftRightLogical(
xla::BitcastConvertType(rhs, xla::S32), sixteen),
sixteen);
xla::Select(xla::Ge(xla::BitcastConvertType(lhs_criteria, xla::F32),
xla::BitcastConvertType(rhs_criteria, xla::F32)),
lhs, rhs);
}
auto reduce = rb->BuildAndNoteError();
xla::Padding xla_padding =
(padding_ == VALID) ? xla::Padding::kValid : xla::Padding::kSame;
auto pooled_hi =
xla::ReduceWindow(xla::BitcastConvertType(in_hi_bp_hi, xla::F32),
init_value, reduce, ksize_, stride_, xla_padding);
auto pooled_lo =
xla::ReduceWindow(xla::BitcastConvertType(in_hi_bp_lo, xla::F32),
init_value, reduce, ksize_, stride_, xla_padding);
auto grads_hi =
xla::ShiftLeft(xla::BitcastConvertType(pooled_hi, xla::U32), sixteen);
auto grads_lo = xla::ShiftRightLogical(
xla::ShiftLeft(xla::BitcastConvertType(pooled_lo, xla::U32), sixteen),
sixteen);
auto grads = xla::Add(grads_hi, grads_lo);  
xla::PrimitiveType element_type;
OP_REQUIRES_OK(ctx, DataTypeToPrimitiveType(input_type(2), &element_type));
ctx->SetOutput(0, xla::BitcastConvertType(grads, element_type));
}

