static Http2Error
rcv_priority_frame(Http2ConnectionState &cstate, const Http2Frame &frame)
{
const Http2StreamId stream_id = frame.header().streamid;
const uint32_t payload_length = frame.header().length;
Http2StreamDebug(cstate.session, stream_id, "Received PRIORITY frame");
if (cstate.get_zombie_event()) {
Warning("Priority frame for zombied session %" PRId64, cstate.session->get_connection_id());
}
if (stream_id == 0) {
return Http2Error(Http2ErrorClass::HTTP2_ERROR_CLASS_CONNECTION, Http2ErrorCode::HTTP2_ERROR_PROTOCOL_ERROR,
"priority 0 stream_id");
}
if (payload_length != HTTP2_PRIORITY_LEN) {
return Http2Error(Http2ErrorClass::HTTP2_ERROR_CLASS_STREAM, Http2ErrorCode::HTTP2_ERROR_FRAME_SIZE_ERROR,
"priority bad length");
}
uint8_t buf[HTTP2_PRIORITY_LEN] = {0};
frame.reader()->memcpy(buf, HTTP2_PRIORITY_LEN, 0);
Http2Priority priority;
if (!http2_parse_priority_parameter(make_iovec(buf, HTTP2_PRIORITY_LEN), priority)) {
return Http2Error(Http2ErrorClass::HTTP2_ERROR_CLASS_CONNECTION, Http2ErrorCode::HTTP2_ERROR_PROTOCOL_ERROR,
"priority parse error");
}
if (stream_id == priority.stream_dependency) {
return Http2Error(Http2ErrorClass::HTTP2_ERROR_CLASS_STREAM, Http2ErrorCode::HTTP2_ERROR_PROTOCOL_ERROR,
"PRIORITY frame depends on itself");
}
if (!Http2::stream_priority_enabled) {
return Http2Error(Http2ErrorClass::HTTP2_ERROR_CLASS_NONE);
}
cstate.increment_received_priority_frame_count();
if (Http2::max_priority_frames_per_minute != 0 &&
cstate.get_received_priority_frame_count() > Http2::max_priority_frames_per_minute) {
HTTP2_INCREMENT_THREAD_DYN_STAT(HTTP2_STAT_MAX_PRIORITY_FRAMES_PER_MINUTE_EXCEEDED, this_ethread());
Http2StreamDebug(cstate.session, stream_id, "Observed too frequent priority changes: %u priority changes within a last minute",
cstate.get_received_priority_frame_count());
return Http2Error(Http2ErrorClass::HTTP2_ERROR_CLASS_CONNECTION, Http2ErrorCode::HTTP2_ERROR_ENHANCE_YOUR_CALM,
"recv priority too frequent priority changes");
}
Http2StreamDebug(cstate.session, stream_id, "PRIORITY - dep: %d, weight: %d, excl: %d, tree size: %d", priority.stream_dependency,
priority.weight, priority.exclusive_flag, cstate.dependency_tree->size());
Http2DependencyTree::Node *node = cstate.dependency_tree->find(stream_id);
if (node != nullptr) {
Http2StreamDebug(cstate.session, stream_id, "Reprioritize");
cstate.dependency_tree->reprioritize(node, priority.stream_dependency, priority.exclusive_flag);
if (is_debug_tag_set("http2_priority")) {
std::stringstream output;
cstate.dependency_tree->dump_tree(output);
Debug("http2_priority", "[%" PRId64 "] reprioritize %s", cstate.session->get_connection_id(), output.str().c_str());
}
} else {
if (Http2::max_concurrent_streams_in > cstate.dependency_tree->size() - cstate.get_client_stream_count() + 1) {
cstate.dependency_tree->add(priority.stream_dependency, stream_id, priority.weight, priority.exclusive_flag, nullptr);
}
}
return Http2Error(Http2ErrorClass::HTTP2_ERROR_CLASS_NONE);
}

packet_t *
capture_packet_reasm_ip(capture_info_t *capinfo, const struct pcap_pkthdr *header, u_char *packet, uint32_t *size, uint32_t *caplen)
{
struct ip *ip4;
#ifdef USE_IPV6
struct ip6_hdr *ip6;
#endif
uint32_t ip_ver;
uint8_t ip_proto;
uint32_t ip_hl = 0;
uint16_t ip_off = 0;
uint16_t ip_len = 0;
uint16_t ip_frag = 0;
uint32_t ip_id = 0;
uint16_t ip_frag_off = 0;
address_t src = { };
address_t dst = { };
vector_iter_t it;
packet_t *pkt;
frame_t *frame;
uint32_t len_data = 0;
uint16_t link_hl = capinfo->link_hl;
#ifdef USE_IPV6
struct ip6_frag *ip6f;
#endif
if (capinfo->link == DLT_EN10MB) {
struct ether_header *eth = (struct ether_header *) packet;
if (ntohs(eth->ether_type) == ETHERTYPE_8021Q) {
link_hl += 4;
}
}
#ifdef SLL_HDR_LEN
if (capinfo->link == DLT_LINUX_SLL) {
struct sll_header *sll = (struct sll_header *) packet;
if (ntohs(sll->sll_protocol) == ETHERTYPE_8021Q) {
link_hl += 4;
}
}
#endif
if (capinfo->link == DLT_NFLOG) {
while (link_hl + 8 <= *caplen) {
nflog_tlv_t *tlv = (nflog_tlv_t *) (packet + link_hl);
if (!tlv) break;
if (tlv->tlv_type == NFULA_PAYLOAD) {
link_hl += 4;
break;
}
if (tlv->tlv_length >= 4) {
link_hl += ((tlv->tlv_length + 3) & ~3); 
}
}
}
while (*size >= sizeof(struct ip)) {
ip4 = (struct ip *) (packet + link_hl);
#ifdef USE_IPV6
ip6 = (struct ip6_hdr *) (packet + link_hl);
#endif
ip_ver = ip4->ip_v;
switch (ip_ver) {
case 4:
ip_hl = ip4->ip_hl * 4;
ip_proto = ip4->ip_p;
ip_off = ntohs(ip4->ip_off);
ip_len = ntohs(ip4->ip_len);
ip_frag = ip_off & (IP_MF | IP_OFFMASK);
ip_frag_off = (ip_frag) ? (ip_off & IP_OFFMASK) * 8 : 0;
ip_id = ntohs(ip4->ip_id);
inet_ntop(AF_INET, &ip4->ip_src, src.ip, sizeof(src.ip));
inet_ntop(AF_INET, &ip4->ip_dst, dst.ip, sizeof(dst.ip));
break;
#ifdef USE_IPV6
case 6:
ip_hl = sizeof(struct ip6_hdr);
ip_proto = ip6->ip6_nxt;
ip_len = ntohs(ip6->ip6_ctlun.ip6_un1.ip6_un1_plen) + ip_hl;
if (ip_proto == IPPROTO_FRAGMENT) {
ip_frag = 1;
ip6f = (struct ip6_frag *) (packet + link_hl + ip_hl);
ip_frag_off = ntohs(ip6f->ip6f_offlg & IP6F_OFF_MASK);
ip_id = ntohl(ip6f->ip6f_ident);
}
inet_ntop(AF_INET6, &ip6->ip6_src, src.ip, sizeof(src.ip));
inet_ntop(AF_INET6, &ip6->ip6_dst, dst.ip, sizeof(dst.ip));
break;
#endif
default:
return NULL;
}
*caplen = link_hl + ip_len;
*size = *caplen - link_hl - ip_hl;
if (ip_proto == IPPROTO_IPIP) {
link_hl += ip_hl;
} else {
break;
}
}
if (*caplen > MAX_CAPTURE_LEN)
return NULL;
if (ip_frag == 0) {
pkt = packet_create(ip_ver, ip_proto, src, dst, ip_id);
packet_add_frame(pkt, header, packet);
return pkt;
}
it = vector_iterator(capinfo->ip_reasm);
while ((pkt = vector_iterator_next(&it))) {
if (addressport_equals(pkt->src, src)
&& addressport_equals(pkt->dst, dst)
&& pkt->ip_id == ip_id) {
break;
}
}
if (pkt) {
packet_add_frame(pkt, header, packet);
} else {
pkt = packet_create(ip_ver, ip_proto, src, dst, ip_id);
packet_add_frame(pkt, header, packet);
vector_append(capinfo->ip_reasm, pkt);
}
pkt->ip_cap_len += ip_len - ip_hl;
#ifdef USE_IPV6
if (ip_ver == 6 && ip_frag) {
pkt->ip_cap_len -= sizeof(struct ip6_frag);
}
#endif
if (ip_ver == 4 && (ip_off & IP_MF) == 0) {
pkt->ip_exp_len = ip_frag_off + ip_len - ip_hl;
}
#ifdef USE_IPV6
if (ip_ver == 6 && ip_frag && (ip6f->ip6f_offlg & htons(0x01)) == 0) {
pkt->ip_exp_len = ip_frag_off + ip_len - ip_hl - sizeof(struct ip6_frag);
}
#endif
if (pkt->ip_cap_len == pkt->ip_exp_len) {
it = vector_iterator(pkt->frames);
while ((frame = vector_iterator_next(&it))) {
switch (ip_ver) {
case 4: {
struct ip *frame_ip = (struct ip *) (frame->data + link_hl);
len_data += ntohs(frame_ip->ip_len) - frame_ip->ip_hl * 4;
break;
}
#ifdef USE_IPV6
case 6: {
struct ip6_hdr *frame_ip6 = (struct ip6_hdr *) (frame->data + link_hl);
len_data += ntohs(frame_ip6->ip6_ctlun.ip6_un1.ip6_un1_plen);
break;
}
#endif
default:
break;
}
}
if (len_data > MAX_CAPTURE_LEN)
return NULL;
memset(packet, 0, link_hl + ip_hl + len_data);
it = vector_iterator(pkt->frames);
while ((frame = vector_iterator_next(&it))) {
switch (ip_ver) {
case 4: {
struct ip *frame_ip = (struct ip *) (frame->data + link_hl);
memcpy(packet + link_hl + ip_hl + (ntohs(frame_ip->ip_off) & IP_OFFMASK) * 8,
frame->data + link_hl + frame_ip->ip_hl * 4,
ntohs(frame_ip->ip_len) - frame_ip->ip_hl * 4);
}
break;
#ifdef USE_IPV6
case 6: {
struct ip6_hdr *frame_ip6 = (struct ip6_hdr*)(frame->data + link_hl);
struct ip6_frag *frame_ip6f = (struct ip6_frag *)(frame->data + link_hl + ip_hl);
uint16_t frame_ip_frag_off = ntohs(frame_ip6f->ip6f_offlg & IP6F_OFF_MASK);
memcpy(packet + link_hl + ip_hl + sizeof(struct ip6_frag) + frame_ip_frag_off,
frame->data + link_hl + ip_hl + sizeof (struct ip6_frag),
ntohs(frame_ip6->ip6_ctlun.ip6_un1.ip6_un1_plen));
pkt->proto = frame_ip6f->ip6f_nxt;
}
break;
#endif
default:
break;
}
}
*caplen = link_hl + ip_hl + len_data;
#ifdef USE_IPV6
if (ip_ver == 6) {
*caplen += sizeof(struct ip6_frag);
}
#endif
*size = len_data;
vector_remove(capinfo->ip_reasm, pkt);
return pkt;
}
return NULL;
}

static u32 __ipv6_select_ident(struct net *net,
const struct in6_addr *dst,
const struct in6_addr *src)
{
const struct {
struct in6_addr dst;
struct in6_addr src;
} __aligned(SIPHASH_ALIGNMENT) combined = {
.dst = *dst,
.src = *src,
};
u32 hash, id;
if (unlikely(siphash_key_is_zero(&net->ipv4.ip_id_key)))
get_random_bytes(&net->ipv4.ip_id_key,
sizeof(net->ipv4.ip_id_key));
hash = siphash(&combined, sizeof(combined), &net->ipv4.ip_id_key);
id = ip_idents_reserve(hash, 1);
if (unlikely(!id))
id = 1 << 31;
return id;
}

