void fx_DataView(txMachine* the)
{
txSlot* slot;
txBoolean flag = 0;
txInteger offset, size;
txSlot* info;
txSlot* instance;
txSlot* view;
txSlot* buffer;
if (mxIsUndefined(mxTarget))
mxTypeError("call: DataView");
if ((mxArgc > 0) && (mxArgv(0)->kind == XS_REFERENCE_KIND)) {
slot = mxArgv(0)->value.reference->next;
if (slot && ((slot->kind == XS_ARRAY_BUFFER_KIND) || (slot->kind == XS_HOST_KIND))) {
flag = 1;
}
}
if (!flag)
mxTypeError("buffer is no ArrayBuffer instance");
offset = fxArgToByteLength(the, 1, 0);
info = fxGetBufferInfo(the, mxArgv(0));
if (info->value.bufferInfo.length < offset)
mxRangeError("out of range byteOffset %ld", offset);
size = fxArgToByteLength(the, 2, -1);
if (size >= 0) {
if (info->value.bufferInfo.length < (offset + size))
mxRangeError("out of range byteLength %ld", size);
}
else {
if (info->value.bufferInfo.maxLength < 0)
size = info->value.bufferInfo.length - offset;
}
mxPushSlot(mxTarget);
fxGetPrototypeFromConstructor(the, &mxDataViewPrototype);
instance = fxNewDataViewInstance(the);
mxPullSlot(mxResult);
view = instance->next;
buffer = view->next;
buffer->kind = XS_REFERENCE_KIND;
buffer->value.reference = mxArgv(0)->value.reference;
info = fxGetBufferInfo(the, buffer);
if (info->value.bufferInfo.maxLength >= 0) {
if (info->value.bufferInfo.length < offset)
mxRangeError("out of range byteOffset %ld", offset);
else if (size >= 0) {
if (info->value.bufferInfo.length < (offset + size))
mxRangeError("out of range byteLength %ld", size);
}
}
view->value.dataView.offset = offset;
view->value.dataView.size = size;
}

PJ_DEF(pj_status_t) pjmedia_vid_conf_remove_port( pjmedia_vid_conf *vid_conf,
unsigned slot)
{
vconf_port *cport;
PJ_ASSERT_RETURN(vid_conf && slot<vid_conf->opt.max_slot_cnt, PJ_EINVAL);
pj_mutex_lock(vid_conf->mutex);
cport = vid_conf->ports[slot];
if (cport == NULL) {
pj_mutex_unlock(vid_conf->mutex);
return PJ_EINVAL;
}
while (cport->listener_cnt) {
pjmedia_vid_conf_disconnect_port(vid_conf, slot,
cport->listener_slots[0]);
}
while (cport->transmitter_cnt) {
pjmedia_vid_conf_disconnect_port(vid_conf,
cport->transmitter_slots[0], slot);
}
vid_conf->ports[slot] = NULL;
--vid_conf->port_cnt;
PJ_LOG(4,(THIS_FILE,"Removed port %d (%.*s)",
slot, (int)cport->name.slen, cport->name.ptr));
pj_pool_safe_release(&cport->pool);
if (AUTO_STOP_CLOCK && vid_conf->connect_cnt == 0) {
pj_status_t status;
status = pjmedia_clock_stop(vid_conf->clock);
if (status != PJ_SUCCESS) {
PJ_PERROR(4, (THIS_FILE, status, "Failed to stop clock"));
return status;
}
}
pj_mutex_unlock(vid_conf->mutex);
return PJ_SUCCESS;
}

