int CPDF_DIBSource::CreateDecoder() {
const CFX_ByteString& decoder = m_pStreamAcc->GetImageDecoder();
if (decoder.IsEmpty()) {
return 1;
}
if (m_bDoBpcCheck && m_bpc == 0) {
return 0;
}
const uint8_t* src_data = m_pStreamAcc->GetData();
uint32_t src_size = m_pStreamAcc->GetSize();
const CPDF_Dictionary* pParams = m_pStreamAcc->GetImageParam();
if (decoder == "CCITTFaxDecode") {
m_pDecoder.reset(FPDFAPI_CreateFaxDecoder(src_data, src_size, m_Width,
m_Height, pParams));
} else if (decoder == "DCTDecode") {
m_pDecoder.reset(CPDF_ModuleMgr::Get()->GetJpegModule()->CreateDecoder(
src_data, src_size, m_Width, m_Height, m_nComponents,
pParams ? pParams->GetIntegerBy("ColorTransform", 1) : 1));
if (!m_pDecoder) {
FX_BOOL bTransform = FALSE;
int comps;
int bpc;
CCodec_JpegModule* pJpegModule = CPDF_ModuleMgr::Get()->GetJpegModule();
if (pJpegModule->LoadInfo(src_data, src_size, m_Width, m_Height, comps,
bpc, bTransform)) {
if (m_nComponents != static_cast<uint32_t>(comps)) {
FX_Free(m_pCompData);
m_nComponents = static_cast<uint32_t>(comps);
if (m_Family == PDFCS_LAB && m_nComponents != 3) {
m_pCompData = nullptr;
return 0;
}
m_pCompData = GetDecodeAndMaskArray(m_bDefaultDecode, m_bColorKey);
if (!m_pCompData) {
return 0;
}
}
m_bpc = bpc;
m_pDecoder.reset(CPDF_ModuleMgr::Get()->GetJpegModule()->CreateDecoder(
src_data, src_size, m_Width, m_Height, m_nComponents, bTransform));
}
}
} else if (decoder == "FlateDecode") {
m_pDecoder.reset(FPDFAPI_CreateFlateDecoder(
src_data, src_size, m_Width, m_Height, m_nComponents, m_bpc, pParams));
} else if (decoder == "JPXDecode") {
LoadJpxBitmap();
return m_pCachedBitmap ? 1 : 0;
} else if (decoder == "JBIG2Decode") {
m_pCachedBitmap.reset(new CFX_DIBitmap);
if (!m_pCachedBitmap->Create(
m_Width, m_Height, m_bImageMask ? FXDIB_1bppMask : FXDIB_1bppRgb)) {
m_pCachedBitmap.reset();
return 0;
}
m_Status = 1;
return 2;
} else if (decoder == "RunLengthDecode") {
m_pDecoder.reset(CPDF_ModuleMgr::Get()
->GetCodecModule()
->GetBasicModule()
->CreateRunLengthDecoder(src_data, src_size, m_Width,
m_Height, m_nComponents,
m_bpc));
}
if (!m_pDecoder)
return 0;
FX_SAFE_UINT32 requested_pitch =
CalculatePitch8(m_bpc, m_nComponents, m_Width);
if (!requested_pitch.IsValid()) {
return 0;
}
FX_SAFE_UINT32 provided_pitch = CalculatePitch8(
m_pDecoder->GetBPC(), m_pDecoder->CountComps(), m_pDecoder->GetWidth());
if (!provided_pitch.IsValid()) {
return 0;
}
if (provided_pitch.ValueOrDie() < requested_pitch.ValueOrDie()) {
return 0;
}
return 1;
}

int
psf_binheader_writef (SF_PRIVATE *psf, const char *format, ...)
{va_listargptr ;
sf_count_t countdata ;
unsigned long longdata ;
unsigned int data ;
floatfloatdata ;
doubledoubledata ;
void*bindata ;
size_tsize ;
charc, *strptr ;
intcount = 0, trunc_8to4 ;
trunc_8to4 = SF_FALSE ;
va_start (argptr, format) ;
while ((c = *format++))
{
if (psf->header.indx + 16 >= psf->header.len && psf_bump_header_allocation (psf, 16))
return count ;
switch (c)
{case ' ' : 
break ;
case 'e' : 
psf->rwf_endian = SF_ENDIAN_LITTLE ;
break ;
case 'E' : 
psf->rwf_endian = SF_ENDIAN_BIG ;
break ;
case 't' : 
trunc_8to4 = SF_TRUE ;
break ;
case 'T' : 
trunc_8to4 = SF_FALSE ;
break ;
case 'm' :
data = va_arg (argptr, unsigned int) ;
header_put_marker (psf, data) ;
count += 4 ;
break ;
case '1' :
data = va_arg (argptr, unsigned int) ;
header_put_byte (psf, data) ;
count += 1 ;
break ;
case '2' :
data = va_arg (argptr, unsigned int) ;
if (psf->rwf_endian == SF_ENDIAN_BIG)
{header_put_be_short (psf, data) ;
}
else
{header_put_le_short (psf, data) ;
} ;
count += 2 ;
break ;
case '3' : 
data = va_arg (argptr, unsigned int) ;
if (psf->rwf_endian == SF_ENDIAN_BIG)
{header_put_be_3byte (psf, data) ;
}
else
{header_put_le_3byte (psf, data) ;
} ;
count += 3 ;
break ;
case '4' :
data = va_arg (argptr, unsigned int) ;
if (psf->rwf_endian == SF_ENDIAN_BIG)
{header_put_be_int (psf, data) ;
}
else
{header_put_le_int (psf, data) ;
} ;
count += 4 ;
break ;
case '8' :
countdata = va_arg (argptr, sf_count_t) ;
if (psf->rwf_endian == SF_ENDIAN_BIG && trunc_8to4 == SF_FALSE)
{header_put_be_8byte (psf, countdata) ;
count += 8 ;
}
else if (psf->rwf_endian == SF_ENDIAN_LITTLE && trunc_8to4 == SF_FALSE)
{header_put_le_8byte (psf, countdata) ;
count += 8 ;
}
else if (psf->rwf_endian == SF_ENDIAN_BIG && trunc_8to4 == SF_TRUE)
{longdata = countdata & 0xFFFFFFFF ;
header_put_be_int (psf, longdata) ;
count += 4 ;
}
else if (psf->rwf_endian == SF_ENDIAN_LITTLE && trunc_8to4 == SF_TRUE)
{longdata = countdata & 0xFFFFFFFF ;
header_put_le_int (psf, longdata) ;
count += 4 ;
}
break ;
case 'f' :
floatdata = (float) va_arg (argptr, double) ;
if (psf->rwf_endian == SF_ENDIAN_BIG)
float32_be_write (floatdata, psf->header.ptr + psf->header.indx) ;
else
float32_le_write (floatdata, psf->header.ptr + psf->header.indx) ;
psf->header.indx += 4 ;
count += 4 ;
break ;
case 'd' :
doubledata = va_arg (argptr, double) ;
if (psf->rwf_endian == SF_ENDIAN_BIG)
double64_be_write (doubledata, psf->header.ptr + psf->header.indx) ;
else
double64_le_write (doubledata, psf->header.ptr + psf->header.indx) ;
psf->header.indx += 8 ;
count += 8 ;
break ;
case 's' :
strptr = va_arg (argptr, char *) ;
size = strlen (strptr) + 1 ;
size += (size & 1) ;
if (psf->header.indx + (sf_count_t) size >= psf->header.len && psf_bump_header_allocation (psf, 16))
return count ;
if (psf->rwf_endian == SF_ENDIAN_BIG)
header_put_be_int (psf, size) ;
else
header_put_le_int (psf, size) ;
memcpy (&(psf->header.ptr [psf->header.indx]), strptr, size) ;
psf->header.indx += size ;
psf->header.ptr [psf->header.indx - 1] = 0 ;
count += 4 + size ;
break ;
case 'S' :
strptr = va_arg (argptr, char *) ;
size = strlen (strptr) ;
if (psf->header.indx + (sf_count_t) size > psf->header.len && psf_bump_header_allocation (psf, size))
return count ;
if (psf->rwf_endian == SF_ENDIAN_BIG)
header_put_be_int (psf, size) ;
else
header_put_le_int (psf, size) ;
memcpy (&(psf->header.ptr [psf->header.indx]), strptr, size + 1) ;
size += (size & 1) ;
psf->header.indx += size ;
psf->header.ptr [psf->header.indx] = 0 ;
count += 4 + size ;
break ;
case 'p' :
strptr = va_arg (argptr, char *) ;
size = strlen (strptr) ;
size = (size & 1) ? size : size + 1 ;
size = (size > 254) ? 254 : size ;
if (psf->header.indx + (sf_count_t) size > psf->header.len && psf_bump_header_allocation (psf, size))
return count ;
header_put_byte (psf, size) ;
memcpy (&(psf->header.ptr [psf->header.indx]), strptr, size) ;
psf->header.indx += size ;
count += 1 + size ;
break ;
case 'b' :
bindata= va_arg (argptr, void *) ;
size= va_arg (argptr, size_t) ;
if (psf->header.indx + (sf_count_t) size > psf->header.len && psf_bump_header_allocation (psf, size))
return count ;
memcpy (&(psf->header.ptr [psf->header.indx]), bindata, size) ;
psf->header.indx += size ;
count += size ;
break ;
case 'z' :
size = va_arg (argptr, size_t) ;
if (psf->header.indx + (sf_count_t) size > psf->header.len && psf_bump_header_allocation (psf, size))
return count ;
count += size ;
while (size)
{psf->header.ptr [psf->header.indx] = 0 ;
psf->header.indx ++ ;
size -- ;
} ;
break ;
case 'h' :
bindata = va_arg (argptr, void *) ;
memcpy (&(psf->header.ptr [psf->header.indx]), bindata, 16) ;
psf->header.indx += 16 ;
count += 16 ;
break ;
case 'j' :
size = va_arg (argptr, size_t) ;
if (psf->header.indx + (sf_count_t) size > psf->header.len && psf_bump_header_allocation (psf, size))
return count ;
psf->header.indx += size ;
count += size ;
break ;
case 'o' :
size = va_arg (argptr, size_t) ;
if ((sf_count_t) size >= psf->header.len && psf_bump_header_allocation (psf, size))
return count ;
psf->header.indx = size ;
break ;
default :
psf_log_printf (psf, "*** Invalid format specifier `%c'\n", c) ;
psf->error = SFE_INTERNAL ;
break ;
} ;
} ;
va_end (argptr) ;
return count ;
}

static ecma_value_t
ecma_module_create_namespace_object (ecma_module_t *module_p) 
{
ecma_value_t result = ECMA_VALUE_EMPTY;
if (module_p->namespace_object_p != NULL)
{
return result;
}
JERRY_ASSERT (module_p->state == ECMA_MODULE_STATE_EVALUATED);
ecma_module_resolve_set_t *resolve_set_p = NULL;
ecma_module_resolve_stack_t *stack_p = NULL;
module_p->namespace_object_p = ecma_create_object (ecma_builtin_get (ECMA_BUILTIN_ID_OBJECT_PROTOTYPE),
0,
ECMA_OBJECT_TYPE_GENERAL);
ecma_module_resolve_stack_push (&stack_p, module_p, ecma_get_magic_string (LIT_MAGIC_STRING_ASTERIX_CHAR));
while (stack_p != NULL)
{
ecma_module_resolve_stack_t *current_frame_p = stack_p;
ecma_module_t *current_module_p = current_frame_p->module_p;
ecma_module_context_t *context_p = current_module_p->context_p;
ecma_module_resolve_stack_pop (&stack_p);
if (!ecma_module_resolve_set_insert (&resolve_set_p,
current_module_p,
ecma_get_magic_string (LIT_MAGIC_STRING_ASTERIX_CHAR)))
{
continue;
}
if (context_p->local_exports_p != NULL)
{
JERRY_ASSERT (context_p->local_exports_p->next_p == NULL);
ecma_module_names_t *export_names_p = context_p->local_exports_p->module_names_p;
while (export_names_p != NULL && ecma_is_value_empty (result))
{
result = ecma_module_namespace_object_add_export_if_needed (module_p,
export_names_p->imex_name_p);
export_names_p = export_names_p->next_p;
}
}
ecma_module_node_t *indirect_export_p = context_p->indirect_exports_p;
while (indirect_export_p != NULL && ecma_is_value_empty (result))
{
ecma_module_names_t *export_names_p = indirect_export_p->module_names_p;
while (export_names_p != NULL && ecma_is_value_empty (result))
{
result = ecma_module_namespace_object_add_export_if_needed (module_p,
export_names_p->imex_name_p);
export_names_p = export_names_p->next_p;
}
indirect_export_p = indirect_export_p->next_p;
}
ecma_module_node_t *star_export_p = context_p->star_exports_p;
while (star_export_p != NULL && ecma_is_value_empty (result))
{
JERRY_ASSERT (star_export_p->module_names_p == NULL);
ecma_module_resolve_stack_push (&stack_p,
star_export_p->module_request_p,
ecma_get_magic_string (LIT_MAGIC_STRING_ASTERIX_CHAR));
star_export_p = star_export_p->next_p;
}
}
ecma_module_resolve_set_cleanup (resolve_set_p);
while (stack_p)
{
ecma_module_resolve_stack_pop (&stack_p);
}
return result;
}

void allocate_channel_framebuffer(int desired_cmp,
BlockBasedImageBase<force_memory_optimized> *framebuffer,
bool memory_optimized=force_memory_optimized) const {
uint64_t total_req_blocks = 0;
for (int cmp = 0; cmp < (int)header_.size() && cmp < cmpc_; cmp++) {
total_req_blocks += header_[cmp].info_.bcv * header_[cmp].info_.bch;
}
for (int cmp = 0; cmp < (int)header_.size() && cmp < cmpc_; cmp++) {
int bc_allocated = header_[cmp].info_.bc;
int64_t max_cmp_bc = max_number_of_blocks;
max_cmp_bc *= header_[cmp].info_.bcv;
max_cmp_bc *= header_[cmp].info_.bch;
max_cmp_bc /= total_req_blocks;
if (bc_allocated > max_cmp_bc) {
bc_allocated = max_cmp_bc - (max_cmp_bc % header_[cmp].info_.bch);
}
if (cmp == desired_cmp) {
framebuffer->init(header_[cmp].info_.bch,
header_[cmp].info_.bcv,
bc_allocated,
memory_optimized);
break;
}
}
}

void ElfFile<ElfFileParamNames>::modifyRPath(RPathOp op,
const std::vector<std::string> & allowedRpathPrefixes, std::string newRPath)
{
auto shdrDynamic = findSectionHeader(".dynamic");
if (rdi(shdrDynamic.sh_type) == SHT_NOBITS) {
debug("no dynamic section\n");
return;
}
auto shdrDynStr = findSectionHeader(".dynstr");
char * strTab = (char *) fileContents->data() + rdi(shdrDynStr.sh_offset);
std::vector<std::string> neededLibs;
auto dyn = (Elf_Dyn *)(fileContents->data() + rdi(shdrDynamic.sh_offset));
Elf_Dyn *dynRPath = nullptr, *dynRunPath = nullptr;
char * rpath = nullptr;
for ( ; rdi(dyn->d_tag) != DT_NULL; dyn++) {
if (rdi(dyn->d_tag) == DT_RPATH) {
dynRPath = dyn;
if (!dynRunPath)
rpath = strTab + rdi(dyn->d_un.d_val);
}
else if (rdi(dyn->d_tag) == DT_RUNPATH) {
dynRunPath = dyn;
rpath = strTab + rdi(dyn->d_un.d_val);
}
else if (rdi(dyn->d_tag) == DT_NEEDED)
neededLibs.push_back(std::string(strTab + rdi(dyn->d_un.d_val)));
}
switch (op) {
case rpPrint: {
printf("%s\n", rpath ? rpath : "");
return;
};
case rpRemove: {
if (!rpath) {
debug("no RPATH to delete\n");
return;
}
removeRPath(shdrDynamic);
return;
}
case rpShrink: {
if (!rpath) {
debug("no RPATH to shrink\n");
return;
;}
newRPath = shrinkRPath(rpath, neededLibs, allowedRpathPrefixes);
break;
}
case rpAdd: {
auto temp = std::string(rpath ? rpath : "");
appendRPath(temp, newRPath);
newRPath = temp;
break;
}
case rpSet: { break; } 
}
if (!forceRPath && dynRPath && !dynRunPath) { 
wri(dynRPath->d_tag, DT_RUNPATH);
dynRunPath = dynRPath;
dynRPath = nullptr;
changed = true;
} else if (forceRPath && dynRunPath) { 
wri(dynRunPath->d_tag, DT_RPATH);
dynRPath = dynRunPath;
dynRunPath = nullptr;
changed = true;
}
if (rpath && rpath == newRPath) {
return;
}
changed = true;
size_t rpathSize = 0;
if (rpath) {
rpathSize = strlen(rpath);
memset(rpath, 'X', rpathSize);
}
debug("new rpath is '%s'\n", newRPath.c_str());
if (newRPath.size() <= rpathSize) {
if (rpath) memcpy(rpath, newRPath.c_str(), newRPath.size() + 1);
return;
}
debug("rpath is too long, resizing...\n");
std::string & newDynStr = replaceSection(".dynstr",
rdi(shdrDynStr.sh_size) + newRPath.size() + 1);
setSubstr(newDynStr, rdi(shdrDynStr.sh_size), newRPath + '\0');
if (dynRunPath || dynRPath) {
if (dynRunPath) dynRunPath->d_un.d_val = shdrDynStr.sh_size;
if (dynRPath) dynRPath->d_un.d_val = shdrDynStr.sh_size;
}
else {
std::string & newDynamic = replaceSection(".dynamic",
rdi(shdrDynamic.sh_size) + sizeof(Elf_Dyn));
unsigned int idx = 0;
for ( ; rdi(((Elf_Dyn *) newDynamic.c_str())[idx].d_tag) != DT_NULL; idx++) ;
debug("DT_NULL index is %d\n", idx);
setSubstr(newDynamic, sizeof(Elf_Dyn),
std::string(newDynamic, 0, sizeof(Elf_Dyn) * (idx + 1)));
Elf_Dyn newDyn;
wri(newDyn.d_tag, forceRPath ? DT_RPATH : DT_RUNPATH);
newDyn.d_un.d_val = shdrDynStr.sh_size;
setSubstr(newDynamic, 0, std::string((char *) &newDyn, sizeof(Elf_Dyn)));
}
this->rewriteSections();
}

static bool r_bin_mdmp_init_directory(struct r_bin_mdmp_obj *obj) {
