J9ROMFieldShape *field;
J9Class *definingClass;
J9ROMNameAndSignature *nameAndSig;
J9UTF8 *name;
J9UTF8 *signature;
IDATA checkResult = J9_VISIBILITY_NON_MODULE_ACCESS_ERROR;
IDATA badMemberModifier = 0;
