tvb_get_guint16(tvb, offset, encoding);
offset += 2;
LONG_ALIGN(offset);
tvb_get_guint32(tvb, offset, encoding);
offset += 4;
baseTypeCodeLength = tvb_get_guint32(tvb, offset, encoding);
offset += 4;
offset += baseTypeCodeLength;
} else {
typecode_name = "struct";
}
if (seq_max_len != -1) {
snprintf(type_name, 40, "%s", struct_name);
break;
}
proto_tree_add_string_format(tree, hf_rtps_struct, tvb, original_offset, retVal, struct_name,
"%s%s %s {", indent_string, typecode_name, struct_name);
LONG_ALIGN(offset);
num_members = tvb_get_guint32(tvb, offset, encoding);
offset += 4;
next_offset = offset;
for (i = 0; i < num_members; ++i) {
guint8  *member_name;
guint32  member_name_len;
guint16  member_length;
guint32  field_offset_begin;
field_offset_begin = offset = next_offset;
SHORT_ALIGN(offset);
member_length = tvb_get_guint16(tvb, offset, encoding);
offset += 2;
next_offset = offset + member_length;
LONG_ALIGN(offset);
member_name_len = tvb_get_guint32(tvb, offset, encoding);
offset += 4;
member_name = tvb_get_string_enc(wmem_packet_scope(), tvb, offset, member_name_len, ENC_ASCII);
offset += member_name_len;
if (tk_id == RTI_CDR_TK_ENUM) {
guint32 ordinal_number;
LONG_ALIGN(offset);
ordinal_number = tvb_get_guint32(tvb, offset, encoding);
offset += 4;
proto_tree_add_string_format(tree, hf_rtps_member_name, tvb, field_offset_begin, (offset-field_offset_begin), member_name,
"%s  %s = %d;", indent_string, member_name, ordinal_number);
} else {
guint16 member_bitfield;
guint8  member_is_pointer;
guint8  member_is_key;
member_is_pointer = tvb_get_guint8(tvb, offset);
offset++;
SHORT_ALIGN(offset);
member_bitfield = tvb_get_guint16(tvb, offset, encoding);
offset += 2; 
member_is_key = tvb_get_guint8(tvb, offset);
offset++;
offset += rtps_util_add_typecode(tree, tvb, offset, encoding,
indent_level+1, member_is_pointer, member_bitfield, member_is_key,
field_offset_begin, member_name, -1, NULL, ndds_40_hack);
}
}
(void) g_strlcpy(type_name, "}", 40);
break;
}
case RTI_CDR_TK_WSTRING:
case RTI_CDR_TK_STRING: {
guint32 string_length;
LONG_ALIGN(offset);
string_length = tvb_get_guint32(tvb, offset, encoding);
offset += 4;
snprintf(type_name, 40, "%s<%d>",
(tk_id == RTI_CDR_TK_STRING) ? "string" : "wstring",
string_length);
break;
}
case RTI_CDR_TK_SEQUENCE: {
guint32 seq_max_len2;
LONG_ALIGN(offset);
seq_max_len2 = tvb_get_guint32(tvb, offset, encoding);
offset += 4;
rtps_util_add_typecode(tree, tvb, offset, encoding, indent_level,
is_pointer, bitfield, is_key, offset_begin, name,
seq_max_len2, NULL, ndds_40_hack);
return retVal;
}
case RTI_CDR_TK_ARRAY: {
guint32 size[MAX_ARRAY_DIMENSION]; 
guint32 dim_max;
LONG_ALIGN(offset);
dim_max = tvb_get_guint32(tvb, offset, encoding);
offset += 4;
if (dim_max > MAX_ARRAY_DIMENSION) {
dim_max = MAX_ARRAY_DIMENSION;
}
for (i = 0; i < MAX_ARRAY_DIMENSION; ++i) size[i] = 0;
for (i = 0; i < dim_max; ++i) {
size[i] = tvb_get_guint32(tvb, offset, encoding);
offset += 4;
}
rtps_util_add_typecode(tree, tvb, offset, encoding,
indent_level, is_pointer, bitfield, is_key, offset_begin,
name, -1, size, ndds_40_hack);
return retVal;
}
case RTI_CDR_TK_ALIAS: {
guint32 alias_name_length;
guint8 *alias_name;
LONG_ALIGN(offset);
alias_name_length = tvb_get_guint32(tvb, offset, encoding);
offset += 4;
alias_name = tvb_get_string_enc(wmem_packet_scope(), tvb, offset, alias_name_length, ENC_ASCII);
offset += alias_name_length;
(void) g_strlcpy(type_name, alias_name, 40);
break;
}
case RTI_CDR_TK_VALUE_PARAM:
case RTI_CDR_TK_VALUE: {
guint32 value_name_len;
gint8 *value_name;
const char *type_id_name = "valuetype";
LONG_ALIGN(offset);
value_name_len = tvb_get_guint32(tvb, offset, encoding);
offset += 4;
value_name = tvb_get_string_enc(wmem_packet_scope(), tvb, offset, value_name_len, ENC_ASCII);
offset += value_name_len;
if (tk_id == RTI_CDR_TK_VALUE_PARAM) {
type_id_name = "valueparam";
}
snprintf(type_name, 40, "%s '%s'", type_id_name, value_name);
break;
}
} 
if (seq_max_len != -1) {
proto_tree_add_string_format(tree, hf_rtps_sequence, tvb, offset_begin, (offset-offset_begin), type_name,
"%ssequence<%s, %d> %s%s;%s", indent_string, type_name, seq_max_len,
is_pointer ? "*" : "",
name ? name : "",
is_key ? KEY_COMMENT : "");
return retVal;
}
if (arr_dimension != NULL) {
wmem_strbuf_t *dim_str = wmem_strbuf_create(wmem_packet_scope());
for (i = 0; i < MAX_ARRAY_DIMENSION; ++i) {
if (arr_dimension[i] != 0) {
wmem_strbuf_append_printf(dim_str, "[%d]", arr_dimension[i]);
} else {
break;
}
}
proto_tree_add_string_format(tree, hf_rtps_array, tvb, offset_begin, (offset-offset_begin), type_name,
"%s%s %s%s;%s", indent_string, type_name, name ? name : "",
wmem_strbuf_get_str(dim_str), is_key ? KEY_COMMENT : "");
return retVal;
}
if (bitfield != 0xffff && name != NULL && is_pointer == 0) {
proto_tree_add_string_format(tree, hf_rtps_bitfield, tvb, offset_begin, (offset-offset_begin), type_name,
"%s%s %s:%d;%s", indent_string, type_name, name,
bitfield, is_key ? KEY_COMMENT : "");
return retVal;
}
proto_tree_add_string_format(tree, hf_rtps_datatype, tvb, offset_begin, (offset-offset_begin), type_name,
"%s%s%s%s%s;%s", indent_string, type_name,
name ? " " : "",
is_pointer ? "*" : "",
name ? name : "",
is_key ? KEY_COMMENT : "");
return retVal;
}

int zfp_acc_compress(const uint8_t *input, int32_t input_len, uint8_t *output,
int32_t output_len, uint8_t meta, blosc2_cparams *cparams, const void *chunk) {
BLOSC_UNUSED_PARAM(chunk);
ZFP_ERROR_NULL(input);
ZFP_ERROR_NULL(output);
ZFP_ERROR_NULL(cparams);
double tol = (int8_t) meta;
int8_t ndim;
int64_t *shape = malloc(8 * sizeof(int64_t));
int32_t *chunkshape = malloc(8 * sizeof(int32_t));
int32_t *blockshape = malloc(8 * sizeof(int32_t));
uint8_t *smeta;
int32_t smeta_len;
if (blosc2_meta_get(cparams->schunk, "b2nd", &smeta, &smeta_len) < 0) {
free(shape);
free(chunkshape);
free(blockshape);
BLOSC_TRACE_ERROR("b2nd layer not found!");
return BLOSC2_ERROR_FAILURE;
}
deserialize_meta(smeta, smeta_len, &ndim, shape, chunkshape, blockshape);
free(smeta);
for(int i = 0; i < ndim; i++) {
if (blockshape[i] < 4) {
BLOSC_TRACE_ERROR("ZFP does not support blocks smaller than cells (4x...x4");
return BLOSC2_ERROR_FAILURE;
}
}
zfp_type type;     
zfp_field *field;  
zfp_stream *zfp;   
zfp_stream *zfp_aux;   
bitstream *stream; 
bitstream *stream_aux; 
size_t zfpsize;    
double tolerance = pow(10, tol);
int32_t typesize = cparams->typesize;
switch (typesize) {
case sizeof(float):
type = zfp_type_float;
break;
case sizeof(double):
type = zfp_type_double;
break;
default:
free(shape);
free(chunkshape);
free(blockshape);
BLOSC_TRACE_ERROR("ZFP is not available for typesize: %d", typesize);
return BLOSC2_ERROR_FAILURE;
}
zfp = zfp_stream_open(NULL);
zfp_stream_set_accuracy(zfp, tolerance);
stream = stream_open(output, output_len);
zfp_stream_set_bit_stream(zfp, stream);
zfp_stream_rewind(zfp);
switch (ndim) {
case 1:
field = zfp_field_1d((void *) input, type, blockshape[0]);
break;
case 2:
field = zfp_field_2d((void *) input, type, blockshape[1], blockshape[0]);
break;
case 3:
field = zfp_field_3d((void *) input, type, blockshape[2], blockshape[1], blockshape[0]);
break;
case 4:
field = zfp_field_4d((void *) input, type, blockshape[3], blockshape[2], blockshape[1], blockshape[0]);
break;
default:
free(shape);
free(chunkshape);
free(blockshape);
BLOSC_TRACE_ERROR("ZFP is not available for ndims: %d", ndim);
return BLOSC2_ERROR_FAILURE;
}
int zfp_maxout = (int) zfp_stream_maximum_size(zfp, field);
zfp_stream_close(zfp);
stream_close(stream);
uint8_t *aux_out = malloc(zfp_maxout);
zfp_aux = zfp_stream_open(NULL);
zfp_stream_set_accuracy(zfp_aux, tolerance);
stream_aux = stream_open(aux_out, zfp_maxout);
zfp_stream_set_bit_stream(zfp_aux, stream_aux);
zfp_stream_rewind(zfp_aux);
zfpsize = zfp_compress(zfp_aux, field);
zfp_field_free(field);
zfp_stream_close(zfp_aux);
stream_close(stream_aux);
free(shape);
free(chunkshape);
free(blockshape);
if (zfpsize == 0) {
BLOSC_TRACE_ERROR("\n ZFP: Compression failed\n");
free(aux_out);
return (int) zfpsize;
}
if ((int32_t) zfpsize >= input_len) {
BLOSC_TRACE_ERROR("\n ZFP: Compressed data is bigger than input! \n");
free(aux_out);
return 0;
}
memcpy(output, aux_out, zfpsize);
free(aux_out);
return (int) zfpsize;
}

int arch_iommu_populate_page_table(struct domain *d)
{
struct page_info *page;
int rc = 0, n = 0;
spin_lock(&d->page_alloc_lock);
if ( unlikely(d->is_dying) )
rc = -ESRCH;
while ( !rc && (page = page_list_remove_head(&d->page_list)) )
{
if ( is_hvm_domain(d) ||
(page->u.inuse.type_info & PGT_type_mask) == PGT_writable_page )
{
unsigned long mfn = mfn_x(page_to_mfn(page));
unsigned long gfn = mfn_to_gmfn(d, mfn);
unsigned int flush_flags = 0;
if ( gfn != gfn_x(INVALID_GFN) )
{
ASSERT(!(gfn >> DEFAULT_DOMAIN_ADDRESS_WIDTH));
BUG_ON(SHARED_M2P(gfn));
rc = iommu_map(d, _dfn(gfn), _mfn(mfn), PAGE_ORDER_4K,
IOMMUF_readable | IOMMUF_writable,
&flush_flags);
}
if ( rc )
{
page_list_add(page, &d->page_list);
break;
}
}
page_list_add_tail(page, &d->arch.relmem_list);
if ( !(++n & 0xff) && !page_list_empty(&d->page_list) &&
hypercall_preempt_check() )
rc = -ERESTART;
}
if ( !rc )
{
page_list_move(&d->page_list, &d->arch.relmem_list);
while ( !page_list_empty(&d->page_list) &&
(page = page_list_first(&d->page_list),
(page->count_info & (PGC_state|PGC_broken))) )
{
page_list_del(page, &d->page_list);
page_list_add_tail(page, &d->arch.relmem_list);
}
}
spin_unlock(&d->page_alloc_lock);
if ( !rc )
rc = iommu_iotlb_flush_all(
d, IOMMU_FLUSHF_added | IOMMU_FLUSHF_modified);
if ( rc && rc != -ERESTART )
iommu_teardown(d);
return rc;
}

int
xmlRemoveID(xmlDocPtr doc, xmlAttrPtr attr) {
xmlIDTablePtr table;
xmlIDPtr id;
xmlChar *ID;
if (doc == NULL) return(-1);
if (attr == NULL) return(-1);
table = (xmlIDTablePtr) doc->ids;
if (table == NULL)
return(-1);
ID = xmlNodeListGetString(doc, attr->children, 1);
if (ID == NULL)
return(-1);
id = xmlHashLookup(table, ID);
if (id == NULL || id->attr != attr) {
xmlFree(ID);
return(-1);
}
xmlHashRemoveEntry(table, ID, xmlFreeIDTableEntry);
xmlFree(ID);
attr->atype = 0;
return(0);
}

int btrfs_init_dev_replace(struct btrfs_fs_info *fs_info)
{
struct btrfs_key key;
struct btrfs_root *dev_root = fs_info->dev_root;
struct btrfs_dev_replace *dev_replace = &fs_info->dev_replace;
struct extent_buffer *eb;
int slot;
int ret = 0;
struct btrfs_path *path = NULL;
int item_size;
struct btrfs_dev_replace_item *ptr;
u64 src_devid;
path = btrfs_alloc_path();
if (!path) {
ret = -ENOMEM;
goto out;
}
key.objectid = 0;
key.type = BTRFS_DEV_REPLACE_KEY;
key.offset = 0;
ret = btrfs_search_slot(NULL, dev_root, &key, path, 0, 0);
if (ret) {
no_valid_dev_replace_entry_found:
ret = 0;
dev_replace->replace_state =
BTRFS_DEV_REPLACE_ITEM_STATE_NEVER_STARTED;
dev_replace->cont_reading_from_srcdev_mode =
BTRFS_DEV_REPLACE_ITEM_CONT_READING_FROM_SRCDEV_MODE_ALWAYS;
dev_replace->time_started = 0;
dev_replace->time_stopped = 0;
atomic64_set(&dev_replace->num_write_errors, 0);
atomic64_set(&dev_replace->num_uncorrectable_read_errors, 0);
dev_replace->cursor_left = 0;
dev_replace->committed_cursor_left = 0;
dev_replace->cursor_left_last_write_of_item = 0;
dev_replace->cursor_right = 0;
dev_replace->srcdev = NULL;
dev_replace->tgtdev = NULL;
dev_replace->is_valid = 0;
dev_replace->item_needs_writeback = 0;
goto out;
}
slot = path->slots[0];
eb = path->nodes[0];
item_size = btrfs_item_size_nr(eb, slot);
ptr = btrfs_item_ptr(eb, slot, struct btrfs_dev_replace_item);
if (item_size != sizeof(struct btrfs_dev_replace_item)) {
btrfs_warn(fs_info,
"dev_replace entry found has unexpected size, ignore entry");
goto no_valid_dev_replace_entry_found;
}
src_devid = btrfs_dev_replace_src_devid(eb, ptr);
dev_replace->cont_reading_from_srcdev_mode =
btrfs_dev_replace_cont_reading_from_srcdev_mode(eb, ptr);
dev_replace->replace_state = btrfs_dev_replace_replace_state(eb, ptr);
dev_replace->time_started = btrfs_dev_replace_time_started(eb, ptr);
dev_replace->time_stopped =
btrfs_dev_replace_time_stopped(eb, ptr);
atomic64_set(&dev_replace->num_write_errors,
btrfs_dev_replace_num_write_errors(eb, ptr));
atomic64_set(&dev_replace->num_uncorrectable_read_errors,
btrfs_dev_replace_num_uncorrectable_read_errors(eb, ptr));
dev_replace->cursor_left = btrfs_dev_replace_cursor_left(eb, ptr);
dev_replace->committed_cursor_left = dev_replace->cursor_left;
dev_replace->cursor_left_last_write_of_item = dev_replace->cursor_left;
dev_replace->cursor_right = btrfs_dev_replace_cursor_right(eb, ptr);
dev_replace->is_valid = 1;
dev_replace->item_needs_writeback = 0;
switch (dev_replace->replace_state) {
case BTRFS_IOCTL_DEV_REPLACE_STATE_NEVER_STARTED:
case BTRFS_IOCTL_DEV_REPLACE_STATE_FINISHED:
case BTRFS_IOCTL_DEV_REPLACE_STATE_CANCELED:
dev_replace->srcdev = NULL;
dev_replace->tgtdev = NULL;
break;
case BTRFS_IOCTL_DEV_REPLACE_STATE_STARTED:
case BTRFS_IOCTL_DEV_REPLACE_STATE_SUSPENDED:
dev_replace->srcdev = btrfs_find_device(fs_info->fs_devices,
src_devid, NULL, NULL);
dev_replace->tgtdev = btrfs_find_device(fs_info->fs_devices,
BTRFS_DEV_REPLACE_DEVID,
NULL, NULL);
if (!dev_replace->srcdev &&
!btrfs_test_opt(fs_info, DEGRADED)) {
ret = -EIO;
btrfs_warn(fs_info,
"cannot mount because device replace operation is ongoing and");
btrfs_warn(fs_info,
"srcdev (devid %llu) is missing, need to run 'btrfs dev scan'?",
src_devid);
}
if (!dev_replace->tgtdev &&
!btrfs_test_opt(fs_info, DEGRADED)) {
ret = -EIO;
btrfs_warn(fs_info,
"cannot mount because device replace operation is ongoing and");
btrfs_warn(fs_info,
"tgtdev (devid %llu) is missing, need to run 'btrfs dev scan'?",
BTRFS_DEV_REPLACE_DEVID);
}
if (dev_replace->tgtdev) {
if (dev_replace->srcdev) {
dev_replace->tgtdev->total_bytes =
dev_replace->srcdev->total_bytes;
dev_replace->tgtdev->disk_total_bytes =
dev_replace->srcdev->disk_total_bytes;
dev_replace->tgtdev->commit_total_bytes =
dev_replace->srcdev->commit_total_bytes;
dev_replace->tgtdev->bytes_used =
dev_replace->srcdev->bytes_used;
dev_replace->tgtdev->commit_bytes_used =
dev_replace->srcdev->commit_bytes_used;
}
set_bit(BTRFS_DEV_STATE_REPLACE_TGT,
&dev_replace->tgtdev->dev_state);
WARN_ON(fs_info->fs_devices->rw_devices == 0);
dev_replace->tgtdev->io_width = fs_info->sectorsize;
dev_replace->tgtdev->io_align = fs_info->sectorsize;
dev_replace->tgtdev->sector_size = fs_info->sectorsize;
dev_replace->tgtdev->fs_info = fs_info;
set_bit(BTRFS_DEV_STATE_IN_FS_METADATA,
&dev_replace->tgtdev->dev_state);
}
break;
}
out:
btrfs_free_path(path);
return ret;
}

void Compute(OpKernelContext* context) override {
const Tensor& contents = context->input(0);
OP_REQUIRES(context, TensorShapeUtils::IsScalar(contents.shape()),
errors::InvalidArgument("contents must be scalar, got shape ",
contents.shape().DebugString()));
const StringPiece input = contents.scalar<string>()();
OP_REQUIRES(context, (32 <= input.size()),
errors::InvalidArgument("Incomplete bmp content, requires at "
"least 32 bytes to find the header "
"size, width, height, and bpp, got ",
input.size(), " bytes"));
const uint8* img_bytes = reinterpret_cast<const uint8*>(input.data());
int32 header_size_ = internal::SubtleMustCopy(
*(reinterpret_cast<const int32*>(img_bytes + 10)));
const int32 header_size = ByteSwapInt32ForBigEndian(header_size_);
int32 width_ = internal::SubtleMustCopy(
*(reinterpret_cast<const int32*>(img_bytes + 18)));
const int32 width = ByteSwapInt32ForBigEndian(width_);
int32 height_ = internal::SubtleMustCopy(
*(reinterpret_cast<const int32*>(img_bytes + 22)));
const int32 height = ByteSwapInt32ForBigEndian(height_);
int32 bpp_ = internal::SubtleMustCopy(
*(reinterpret_cast<const int32*>(img_bytes + 28)));
const int32 bpp = ByteSwapInt32ForBigEndian(bpp_);
if (channels_) {
OP_REQUIRES(context, (channels_ == bpp / 8),
errors::InvalidArgument(
"channels attribute ", channels_,
" does not match bits per pixel from file ", bpp / 8));
} else {
channels_ = bpp / 8;
}
OP_REQUIRES(context, (channels_ == 1 || channels_ == 3 || channels_ == 4),
errors::InvalidArgument(
"Number of channels must be 1, 3 or 4, was ", channels_));
const int row_size = (8 * channels_ * width + 31) / 32 * 4;
const int last_pixel_offset =
header_size + (abs(height) - 1) * row_size + (width - 1) * channels_;
const int expected_file_size = last_pixel_offset + channels_;
OP_REQUIRES(
context, (expected_file_size <= input.size()),
errors::InvalidArgument("Incomplete bmp content, requires at least ",
expected_file_size, " bytes, got ",
input.size(), " bytes"));
bool top_down = (height < 0);
Tensor* output = nullptr;
OP_REQUIRES_OK(
context, context->allocate_output(
0, TensorShape({abs(height), width, channels_}), &output));
const uint8* bmp_pixels = &img_bytes[header_size];
Decode(bmp_pixels, row_size, output->flat<uint8>().data(), width,
abs(height), channels_, top_down);
}

TfLiteStatus EvalScatterNd(TfLiteContext* context, const TfLiteTensor* indices,
const TfLiteTensor* updates,
const TfLiteTensor* shape, TfLiteTensor* output) {
if (IsDynamicTensor(output)) {
TF_LITE_ENSURE_OK(
context, CheckShapes<IndicesT>(
context, GetTensorShape(indices), GetTensorShape(updates),
GetTensorShape(shape), GetTensorData<IndicesT>(shape)));
TF_LITE_ENSURE_OK(context,
ResizeOutputTensor<IndicesT>(context, shape, output));
}
switch (updates->type) {
case kTfLiteFloat32:
return ScatterNd<IndicesT, float>(indices, updates, output);
case kTfLiteUInt8:
return ScatterNd<IndicesT, uint8_t>(indices, updates, output);
case kTfLiteBool:
return ScatterNd<IndicesT, bool>(indices, updates, output);
case kTfLiteInt8:
return ScatterNd<IndicesT, int8_t>(indices, updates, output);
case kTfLiteInt32:
return ScatterNd<IndicesT, int32_t>(indices, updates, output);
case kTfLiteInt64:
return ScatterNd<IndicesT, int64_t>(indices, updates, output);
default:
TF_LITE_KERNEL_LOG(
context, "Updates of type '%s' are not supported by scatter_nd.",
TfLiteTypeGetName(updates->type));
return kTfLiteError;
}
}

static void srpt_handle_tsk_mgmt(struct srpt_rdma_ch *ch,
struct srpt_recv_ioctx *recv_ioctx,
struct srpt_send_ioctx *send_ioctx)
{
struct srp_tsk_mgmt *srp_tsk;
struct se_cmd *cmd;
struct se_session *sess = ch->sess;
uint64_t unpacked_lun;
uint32_t tag = 0;
int tcm_tmr;
int rc;
BUG_ON(!send_ioctx);
srp_tsk = recv_ioctx->ioctx.buf;
cmd = &send_ioctx->cmd;
pr_debug("recv tsk_mgmt fn %d for task_tag %lld and cmd tag %lld"
" cm_id %p sess %p\n", srp_tsk->tsk_mgmt_func,
srp_tsk->task_tag, srp_tsk->tag, ch->cm_id, ch->sess);
srpt_set_cmd_state(send_ioctx, SRPT_STATE_MGMT);
send_ioctx->cmd.tag = srp_tsk->tag;
tcm_tmr = srp_tmr_to_tcm(srp_tsk->tsk_mgmt_func);
if (tcm_tmr < 0) {
send_ioctx->cmd.se_tmr_req->response =
TMR_TASK_MGMT_FUNCTION_NOT_SUPPORTED;
goto fail;
}
unpacked_lun = srpt_unpack_lun((uint8_t *)&srp_tsk->lun,
sizeof(srp_tsk->lun));
if (srp_tsk->tsk_mgmt_func == SRP_TSK_ABORT_TASK) {
rc = srpt_rx_mgmt_fn_tag(send_ioctx, srp_tsk->task_tag);
if (rc < 0) {
send_ioctx->cmd.se_tmr_req->response =
TMR_TASK_DOES_NOT_EXIST;
goto fail;
}
tag = srp_tsk->task_tag;
}
rc = target_submit_tmr(&send_ioctx->cmd, sess, NULL, unpacked_lun,
srp_tsk, tcm_tmr, GFP_KERNEL, tag,
TARGET_SCF_ACK_KREF);
if (rc != 0) {
send_ioctx->cmd.se_tmr_req->response = TMR_FUNCTION_REJECTED;
goto fail;
}
return;
fail:
transport_send_check_condition_and_sense(cmd, 0, 0); }

static int dxtory_decode_v1_410(AVCodecContext *avctx, AVFrame *pic,
const uint8_t *src, int src_size)
{
int h, w;
uint8_t *Y1, *Y2, *Y3, *Y4, *U, *V;
int ret;
if (src_size < avctx->width * avctx->height * 18 / 16) {
av_log(avctx, AV_LOG_ERROR, "packet too small\n");
return AVERROR_INVALIDDATA;
}
avctx->pix_fmt = AV_PIX_FMT_YUV410P;
if ((ret = ff_get_buffer(avctx, pic, 0)) < 0)
return ret;
Y1 = pic->data[0];
Y2 = pic->data[0] + pic->linesize[0];
Y3 = pic->data[0] + pic->linesize[0] * 2;
Y4 = pic->data[0] + pic->linesize[0] * 3;
U  = pic->data[1];
V  = pic->data[2];
for (h = 0; h < avctx->height; h += 4) {
for (w = 0; w < avctx->width; w += 4) {
AV_COPY32(Y1 + w, src);
AV_COPY32(Y2 + w, src + 4);
AV_COPY32(Y3 + w, src + 8);
AV_COPY32(Y4 + w, src + 12);
U[w >> 2] = src[16] + 0x80;
V[w >> 2] = src[17] + 0x80;
src += 18;
}
Y1 += pic->linesize[0] << 2;
Y2 += pic->linesize[0] << 2;
Y3 += pic->linesize[0] << 2;
Y4 += pic->linesize[0] << 2;
U  += pic->linesize[1];
V  += pic->linesize[2];
}
return 0;
}

