static int hyper_rescan_scsi(void)
{
struct dirent **list;
struct dirent *dir;
int fd = -1, i, num;
char path[256];
num = scandir("/sys/class/scsi_host/", &list, NULL, NULL);
if (num < 0) {
perror("scan /sys/class/scsi_host/ failed");
return -1;
}
memset(path, 0, sizeof(path));
for (i = 0; i < num; i++) {
dir = list[i];
if (dir->d_name[0] == '.')
continue;
if (snprintf(path, sizeof(path), "/sys/class/scsi_host/%s/scan",
dir->d_name) < 0) {
fprintf(stderr, "get scsi host device %s path failed\n",
dir->d_name);
continue;
}
fprintf(stdout, "path %s\n", path);
fd = open(path, O_WRONLY);
if (fd < 0) {
perror("open path failed");
continue;
}
if (write(fd, "- - - \n", 7) < 0)
perror("write to scan failed");
close(fd);
}
fprintf(stdout, "finish scan scsi\n");
return 0;
free(list);
}

static VALUE
fiddle_handle_sym(void *handle, const char *name)
{
#if defined(HAVE_DLERROR)
const char *err;
# define CHECK_DLERROR if( err = dlerror() ){ func = 0; }
#else
# define CHECK_DLERROR
#endif
void (*func)();
rb_secure(2);
#ifdef HAVE_DLERROR
dlerror();
#endif
func = (void (*)())(VALUE)dlsym(handle, name);
CHECK_DLERROR;
#if defined(FUNC_STDCALL)
if( !func ){
int  i;
int  len = (int)strlen(name);
char *name_n;
#if defined(__CYGWIN__) || defined(_WIN32) || defined(__MINGW32__)
{
char *name_a = (char*)xmalloc(len+2);
strcpy(name_a, name);
name_n = name_a;
name_a[len]   = 'A';
name_a[len+1] = '\0';
func = dlsym(handle, name_a);
CHECK_DLERROR;
if( func ) goto found;
name_n = xrealloc(name_a, len+6);
}
#else
name_n = (char*)xmalloc(len+6);
#endif
memcpy(name_n, name, len);
name_n[len++] = '@';
for( i = 0; i < 256; i += 4 ){
sprintf(name_n + len, "%d", i);
func = dlsym(handle, name_n);
CHECK_DLERROR;
if( func ) break;
}
if( func ) goto found;
name_n[len-1] = 'A';
name_n[len++] = '@';
for( i = 0; i < 256; i += 4 ){
sprintf(name_n + len, "%d", i);
func = dlsym(handle, name_n);
CHECK_DLERROR;
if( func ) break;
}
found:
xfree(name_n);
}
#endif
if( !func ){
rb_raise(rb_eFiddleError, "unknown symbol \"%s\"", name);
}
return PTR2NUM(func);
}

