return WDRR_BUCKET_FOR_HH;
}
for (i = 0; i < HHF_ARRAYS_CNT; i++) {
if (q->hhf_arrays[i][filter_pos[i]] < min_hhf_val)
q->hhf_arrays[i][filter_pos[i]] = min_hhf_val;
}
return WDRR_BUCKET_FOR_NON_HH;
}

GF_Err audio_sample_entry_AddBox(GF_Box *s, GF_Box *a)
{
GF_MPEGAudioSampleEntryBox *ptr = (GF_MPEGAudioSampleEntryBox *)s;
switch (a->type) {
case GF_ISOM_BOX_TYPE_ESDS:
if (ptr->esd) ERROR_ON_DUPLICATED_BOX(a, ptr)
ptr->esd = (GF_ESDBox *)a;
break;
case GF_ISOM_BOX_TYPE_SINF:
gf_list_add(ptr->protections, a);
break;
case GF_ISOM_BOX_TYPE_DAMR:
case GF_ISOM_BOX_TYPE_DEVC:
case GF_ISOM_BOX_TYPE_DQCP:
case GF_ISOM_BOX_TYPE_DSMV:
ptr->cfg_3gpp = (GF_3GPPConfigBox *) a;
ptr->cfg_3gpp->cfg.type = ptr->type;
break;
case GF_ISOM_BOX_TYPE_DAC3:
ptr->cfg_ac3 = (GF_AC3ConfigBox *) a;
break;
case GF_ISOM_BOX_TYPE_DEC3:
ptr->cfg_ac3 = (GF_AC3ConfigBox *) a;
break;
case GF_ISOM_BOX_TYPE_MHA1:
case GF_ISOM_BOX_TYPE_MHA2:
case GF_ISOM_BOX_TYPE_MHM1:
case GF_ISOM_BOX_TYPE_MHM2:
ptr->cfg_mha = (GF_MHAConfigBox *) a;
break;
case GF_ISOM_BOX_TYPE_UNKNOWN:
if (ptr->esd) ERROR_ON_DUPLICATED_BOX(a, ptr)
{
GF_UnknownBox *wave = (GF_UnknownBox *)a;
if ((wave->original_4cc == GF_ISOM_BOX_TYPE_WAVE) && gf_list_count(wave->other_boxes)) {
u32 i;
for (i =0; i<gf_list_count(wave->other_boxes); i++) {
GF_Box *inner_box = (GF_Box *)gf_list_get(wave->other_boxes, i);
if (inner_box->type == GF_ISOM_BOX_TYPE_ESDS) {
ptr->esd = (GF_ESDBox *)inner_box;
}
}
return gf_isom_box_add_default(s, a);
}
else if (wave->data != NULL) {
u32 offset = 0;
while ((wave->data[offset + 4] != 'e') && (wave->data[offset + 5] != 's')) {
offset++;
if (offset == wave->dataSize) break;
}
if (offset < wave->dataSize) {
GF_Box *a;
GF_Err e;
GF_BitStream *bs = gf_bs_new(wave->data + offset, wave->dataSize - offset, GF_BITSTREAM_READ);
e = gf_isom_box_parse(&a, bs);
gf_bs_del(bs);
if (e) return e;
ptr->esd = (GF_ESDBox *)a;
gf_isom_box_add_for_dump_mode((GF_Box *)ptr, a);
}
GF_LOG(GF_LOG_WARNING, GF_LOG_CONTAINER, ("[iso file] Cannot process box %s!\n", gf_4cc_to_str(wave->original_4cc)));
return gf_isom_box_add_default(s, a);
}
gf_isom_box_del(a);
return GF_ISOM_INVALID_MEDIA;
}
break;
default:
return gf_isom_box_add_default(s, a);
}
return GF_OK;
}

Status
XAllocNamedColor(
register Display *dpy,
Colormap cmap,
_Xconst char *colorname, 
XColor *hard_def, 
XColor *exact_def) 
{
long nbytes;
xAllocNamedColorReply rep;
xAllocNamedColorReq *req;
XcmsCCC ccc;
XcmsColor cmsColor_exact;
Status ret;
#ifdef XCMS
if ((ccc = XcmsCCCOfColormap(dpy, cmap)) != (XcmsCCC)NULL) {
const char *tmpName = colorname;
switch (_XcmsResolveColorString(ccc, &tmpName, &cmsColor_exact,
XcmsRGBFormat)) {
case XcmsSuccess:
case XcmsSuccessWithCompression:
_XcmsRGB_to_XColor(&cmsColor_exact, exact_def, 1);
memcpy((char *)hard_def, (char *)exact_def, sizeof(XColor));
ret = XAllocColor(dpy, cmap, hard_def);
exact_def->pixel = hard_def->pixel;
return(ret);
case XcmsFailure:
case _XCMS_NEWNAME:
break;
}
}
#endif
LockDisplay(dpy);
GetReq(AllocNamedColor, req);
req->cmap = cmap;
nbytes = req->nbytes = (CARD16) strlen(colorname);
req->length += (nbytes + 3) >> 2; 
_XSend(dpy, colorname, nbytes);
if (!_XReply (dpy, (xReply *) &rep, 0, xTrue)) {
UnlockDisplay(dpy);
SyncHandle();
return (0);
}
exact_def->red = rep.exactRed;
exact_def->green = rep.exactGreen;
exact_def->blue = rep.exactBlue;
hard_def->red = rep.screenRed;
hard_def->green = rep.screenGreen;
hard_def->blue = rep.screenBlue;
exact_def->pixel = hard_def->pixel = rep.pixel;
UnlockDisplay(dpy);
SyncHandle();
return (1);
}

void ishtp_cl_release_dma_acked_mem(struct ishtp_device *dev,
void *msg_addr,
uint8_t size)
{
unsigned longflags;
int acked_slots = (size / DMA_SLOT_SIZE)
+ 1 * (size % DMA_SLOT_SIZE != 0);
int i, j;
if ((msg_addr - dev->ishtp_host_dma_tx_buf) % DMA_SLOT_SIZE) {
dev_err(dev->devc, "Bad DMA Tx ack address\n");
return;
}
i = (msg_addr - dev->ishtp_host_dma_tx_buf) / DMA_SLOT_SIZE;
spin_lock_irqsave(&dev->ishtp_dma_tx_lock, flags);
for (j = 0; j < acked_slots; j++) {
if ((i + j) >= dev->ishtp_dma_num_slots ||
!dev->ishtp_dma_tx_map[i+j]) {
spin_unlock_irqrestore(&dev->ishtp_dma_tx_lock, flags);
dev_err(dev->devc, "Bad DMA Tx ack address\n");
return;
}
dev->ishtp_dma_tx_map[i+j] = 0;
}
spin_unlock_irqrestore(&dev->ishtp_dma_tx_lock, flags);
}

void PngImage::printStructure(std::ostream& out, PrintStructureOption option, int depth)
{
if (io_->open() != 0) {
throw Error(kerDataSourceOpenFailed, io_->path(), strError());
}
if (!isPngType(*io_, true)) {
throw Error(kerNotAnImage, "PNG");
}
char    chType[5];
chType[0]=0;
chType[4]=0;
if ( option == kpsBasic || option == kpsXMP || option == kpsIccProfile || option == kpsRecursive ) {
const std::string xmpKey  = "XML:com.adobe.xmp";
const std::string exifKey = "Raw profile type exif";
const std::string app1Key = "Raw profile type APP1";
const std::string iptcKey = "Raw profile type iptc";
const std::string iccKey  = "icc";
const std::string softKey = "Software";
const std::string commKey = "Comment";
const std::string descKey = "Description";
bool bPrint = option == kpsBasic || option == kpsRecursive ;
if ( bPrint ) {
out << "STRUCTURE OF PNG FILE: " << io_->path() << std::endl;
out << " address | chunk |  length | data                           | checksum" << std::endl;
}
const long imgSize = (long) io_->size();
DataBuf    cheaderBuf(8);
while( !io_->eof() && ::strcmp(chType,"IEND") ) {
size_t address = io_->tell();
std::memset(cheaderBuf.pData_, 0x0, cheaderBuf.size_);
long bufRead = io_->read(cheaderBuf.pData_, cheaderBuf.size_);
if (io_->error()) throw Error(kerFailedToReadImageData);
if (bufRead != cheaderBuf.size_) throw Error(kerInputDataReadFailed);
uint32_t dataOffset = Exiv2::getULong(cheaderBuf.pData_, Exiv2::bigEndian);
for (int i = 4; i < 8; i++) {
chType[i-4]=cheaderBuf.pData_[i];
}
long restore = io_->tell();
if(  restore == -1
||  dataOffset > uint32_t(0x7FFFFFFF)
||  static_cast<long>(dataOffset) > imgSize - restore
){
throw Exiv2::Error(kerFailedToReadImageData);
}
DataBuf   buff(dataOffset);
io_->read(buff.pData_,dataOffset);
io_->seek(restore, BasicIo::beg);
const int    iMax = 30 ;
const uint32_t blen = dataOffset > iMax ? iMax : dataOffset ;
std::string dataString = "";
if (blen > 0) {
std::stringstream ss;
ss << Internal::binaryToString(makeSlice(buff, 0, blen));
dataString = ss.str();
}
while (      dataString.size() < iMax ) dataString += ' ';
dataString = dataString.substr(0,iMax);
if ( bPrint ) {
io_->seek(dataOffset, BasicIo::cur);                    byte checksum[4];
io_->read(checksum,4);
io_->seek(restore, BasicIo::beg)   ;
out << Internal::stringFormat("%8d | %-5s |%8d | "
,(uint32_t)address, chType,dataOffset)
<< dataString
<< Internal::stringFormat(" | 0x%02x%02x%02x%02x"
,checksum[0],checksum[1],checksum[2],checksum[3])
<< std::endl;
}
bool tEXt  = std::strcmp(chType,"tEXt")== 0;
bool zTXt  = std::strcmp(chType,"zTXt")== 0;
bool iCCP  = std::strcmp(chType,"iCCP")== 0;
bool iTXt  = std::strcmp(chType,"iTXt")== 0;
bool bXMP  = option == kpsXMP        && findi(dataString,xmpKey)==0;
bool bICC  = option == kpsIccProfile && findi(dataString,iccKey)==0;
bool bExif = option == kpsRecursive  &&(findi(dataString,exifKey)==0 || findi(dataString,app1Key)==0);
bool bIptc = option == kpsRecursive  && findi(dataString,iptcKey)==0;
bool bSoft = option == kpsRecursive  && findi(dataString,softKey)==0;
bool bComm = option == kpsRecursive  && findi(dataString,commKey)==0;
bool bDesc = option == kpsRecursive  && findi(dataString,descKey)==0;
bool bDump = bXMP || bICC || bExif || bIptc || bSoft || bComm || bDesc ;
if( bDump ) {
DataBuf   dataBuf;
byte*     data   = new byte[dataOffset+1];
data[dataOffset] = 0;
io_->read(data,dataOffset);
io_->seek(restore, BasicIo::beg);
uint32_t  name_l = (uint32_t) std::strlen((const char*)data)+1;                     uint32_t  start  = name_l;
bool      bLF    = false;
bool bGood = false;
if ( tEXt ) {
bGood = tEXtToDataBuf(data+name_l,dataOffset-name_l,dataBuf);
}
if ( zTXt || iCCP ) {
bGood = zlibToDataBuf(data+name_l+1,dataOffset-name_l-1,dataBuf);                     }
if ( iTXt ) {
bGood = (start+3) < dataOffset ;                        }
if ( bGood ) {
if ( bXMP ) {
while ( !data[start] && start < dataOffset) start++;                             out <<  data+start;                                     }
if ( bExif || bIptc ) {
DataBuf parsedBuf = PngChunk::readRawProfile(dataBuf,tEXt);
#if DEBUG
std::cerr << Exiv2::Internal::binaryToString(parsedBuf.pData_, parsedBuf.size_>50?50:parsedBuf.size_,0) << std::endl;
#endif
if ( parsedBuf.size_ ) {
if ( bExif ) {
BasicIo::AutoPtr p = BasicIo::AutoPtr(new MemIo(parsedBuf.pData_+6,parsedBuf.size_-6));
printTiffStructure(*p,out,option,depth);
}
if ( bIptc ) {
IptcData::printStructure(out, makeSlice(parsedBuf.pData_, 0, parsedBuf.size_), depth);
}
}
}
if ( bSoft && dataBuf.size_ > 0) {
DataBuf     s(dataBuf.size_+1);                                           memcpy(s.pData_,dataBuf.pData_,dataBuf.size_);                            s.pData_[dataBuf.size_] = 0 ;                                             const char* str = (const char*) s.pData_;                                 out << Internal::indent(depth) << (const char*) buff.pData_ << ": " << str ;
bLF=true;
}
if ( bICC || bComm ) {
out.write((const char*) dataBuf.pData_,dataBuf.size_);
bLF = bComm ;
}
if ( bDesc && iTXt ) {
DataBuf decoded = PngChunk::decodeTXTChunk(buff,PngChunk::iTXt_Chunk );
out.write((const char*)decoded.pData_,decoded.size_);
bLF = true;
}
if ( bLF ) out << std::endl;
}
delete[] data;
}
io_->seek(dataOffset+4, BasicIo::cur);                if (io_->error()) throw Error(kerFailedToReadImageData);
}
}
}

void Compute(OpKernelContext* ctx) override {
try {
const Tensor& input = ctx->input(kInputTensorIndex);
const Tensor& input_min_vec = ctx->input(kInputMinVecIndex);
float* input_min_vec_data = (float*)const_cast<void*>(
static_cast<const void*>(input_min_vec.flat<float>().data()));
const Tensor& input_max_vec = ctx->input(kInputMaxVecIndex);
float* input_max_vec_data = (float*)const_cast<void*>(
static_cast<const void*>(input_max_vec.flat<float>().data()));
const Tensor& input_requested_min = ctx->input(this->kRequestMinIndex);
const float input_requested_min_float =
input_requested_min.flat<float>()(0);
const Tensor& input_requested_max = ctx->input(this->kRequestMaxIndex);
const float input_requested_max_float =
input_requested_max.flat<float>()(0);
size_t depth = input_min_vec.NumElements();
OP_REQUIRES(
ctx, input.dims() == 4,
errors::InvalidArgument("Current RequantizePerChannel operator"
"supports 4D tensors only."));
OP_REQUIRES(
ctx, input_min_vec.dim_size(0) == depth,
errors::InvalidArgument("input_min has incorrect size, expected ",
depth, " was ", input_min_vec.dim_size(0)));
OP_REQUIRES(
ctx, input_max_vec.dim_size(0) == depth,
errors::InvalidArgument("input_max has incorrect size, expected ",
depth, " was ", input_max_vec.dim_size(0)));
if (out_type_ == DT_QINT8) DCHECK(input_requested_min_float < 0.0f);
const float factor = (out_type_ == DT_QINT8) ? 127.0f : 255.0f;
const float requested_min_max =
std::max(std::abs(input_requested_min_float),
std::abs(input_requested_max_float));
Tensor* output = nullptr;
OP_REQUIRES_OK(ctx, ctx->allocate_output(kOutputTensorIndex,
input.shape(), &output));
std::vector<float> scales(depth);
for (int i = 0; i < depth; ++i) {
float min_max_from_vec = std::max(std::abs(input_min_vec_data[i]),
std::abs(input_max_vec_data[i]));
scales[i] = factor * (min_max_from_vec / requested_min_max /
static_cast<float>(1L << 31));
}
mkldnn::primitive_attr reorder_attr;
reorder_attr.set_output_scales(2, scales);
memory::dims dims_mkl_order =
TFShapeToMklDnnDimsInNCHW(input.shape(), FORMAT_NHWC);
memory::desc input_md = memory::desc(dims_mkl_order, MklDnnType<qint32>(),
memory::format_tag::nhwc);
memory::desc output_md =
(out_type_ == DT_QINT8)
? memory::desc(dims_mkl_order, MklDnnType<qint8>(),
memory::format_tag::nhwc)
: memory::desc(dims_mkl_order, MklDnnType<quint8>(),
memory::format_tag::nhwc);
void* input_buf =
static_cast<void*>(const_cast<qint32*>(input.flat<qint32>().data()));
void* output_buf;
if (out_type_ == DT_QINT8) {
output_buf = static_cast<void*>(
const_cast<qint8*>(output->flat<qint8>().data()));
} else {
output_buf = static_cast<void*>(
const_cast<quint8*>(output->flat<quint8>().data()));
}
std::unique_ptr<memory> input_mem_prim(
new memory(input_md, cpu_engine_, input_buf));
std::unique_ptr<memory> output_mem_prim(
new memory(output_md, cpu_engine_, output_buf));
mkldnn::reorder::primitive_desc reorder_pd =
ReorderPd(cpu_engine_, input_mem_prim->get_desc(), cpu_engine_,
output_mem_prim->get_desc(), reorder_attr);
std::shared_ptr<stream> reorder_stream;
MklDnnThreadPool eigen_tp(ctx);
reorder_stream.reset(CreateStream(&eigen_tp, cpu_engine_));
std::unordered_map<int, mkldnn::memory> reorder_args = {
{MKLDNN_ARG_FROM, *input_mem_prim},
{MKLDNN_ARG_TO, *output_mem_prim}};
std::unique_ptr<mkldnn::primitive> reorder_prim(
new mkldnn::reorder(reorder_pd));
reorder_prim->execute(*reorder_stream, reorder_args);
Tensor* output_min = nullptr;
Tensor* output_max = nullptr;
OP_REQUIRES_OK(ctx,
ctx->allocate_output(kOutputMinIndex, {}, &output_min));
OP_REQUIRES_OK(ctx,
ctx->allocate_output(kOutputMaxIndex, {}, &output_max));
output_min->flat<float>()(0) = input_requested_min_float;
output_max->flat<float>()(0) = input_requested_max_float;
} catch (mkldnn::error& e) {
string error_msg = "Status: " + std::to_string(e.status) +
", message: " + std::string(e.message) + ", in file " +
std::string(__FILE__) + ":" + std::to_string(__LINE__);
OP_REQUIRES_OK(
ctx, errors::Aborted("Operation received an exception:", error_msg));
}
}

static GF_Err gf_dump_vrml_route(GF_SceneDumper *sdump, GF_Route *r, u32 dump_type)
{
char toNode[512], fromNode[512];
const char *node_name;
u32 id;
if (!r->is_setup) {
gf_node_get_field(r->FromNode, r->FromField.fieldIndex, &r->FromField);
gf_node_get_field(r->ToNode, r->ToField.fieldIndex, &r->ToField);
r->is_setup = 1;
}
if (!r->FromNode || !r->ToNode) return GF_BAD_PARAM;
if (sdump->XMLDump || !dump_type) DUMP_IND(sdump);
node_name = gf_node_get_name_and_id(r->FromNode, &id);
if (node_name) {
const char *to_name;
strcpy(fromNode, node_name);
to_name = gf_node_get_name(r->ToNode);
if (to_name) {
strcpy(toNode, to_name);
} else {
char str[100];
id = gf_node_get_id(r->ToNode);
sprintf(str, "node_%d", id);
strcpy(toNode, str);
}
} else {
sprintf(fromNode, "N%d", id-1);
sprintf(toNode, "N%d", gf_node_get_id(r->ToNode) - 1);
}
if (sdump->XMLDump) {
gf_fprintf(sdump->trace, "<ROUTE");
if (r->ID) {
StartAttribute(sdump, "DEF");
scene_dump_vrml_route_id(sdump, r->ID, r->name);
EndAttribute(sdump);
}
gf_fprintf(sdump->trace, " fromNode=\"%s\" fromField=\"%s\" toNode=\"%s\" toField=\"%s\"/>\n", fromNode, r->FromField.name, toNode, r->ToField.name);
} else {
if (dump_type==2) gf_fprintf(sdump->trace, "ROUTE ");
if (r->ID) {
gf_fprintf(sdump->trace, "DEF ");
scene_dump_vrml_route_id(sdump, r->ID, r->name);
gf_fprintf(sdump->trace, " ");
}
if (dump_type==1) {
gf_fprintf(sdump->trace, "%s.%s TO %s.%s\n", fromNode, r->FromField.name, toNode, r->ToField.name);
} else {
if (dump_type!=2) gf_fprintf(sdump->trace, "ROUTE ");
gf_fprintf(sdump->trace, "%s.%s TO %s.%s\n", fromNode, r->FromField.name, toNode, r->ToField.name);
}
}
return GF_OK;
}

