static njs_ret_t
njs_string_replace_regexp(njs_vm_t *vm, njs_value_t *args,
njs_string_replace_t *r)
{
int                        *captures;
u_char                     *p, *start;
njs_ret_t                  ret;
const u_char               *end;
njs_regexp_pattern_t       *pattern;
njs_string_replace_part_t  replace;
pattern = args[1].data.u.regexp->pattern;
end = r->part[0].start + r->part[0].size;
replace = r->part[1];
do {
ret = njs_regexp_match(vm, &pattern->regex[r->type],
r->part[0].start, r->part[0].size,
r->match_data);
if (ret >= 0) {
captures = nxt_regex_captures(r->match_data);
if (r->substitutions != NULL) {
ret = njs_string_replace_substitute(vm, r, captures);
if (nxt_slow_path(ret != NXT_OK)) {
return ret;
}
if (!pattern->global) {
return njs_string_replace_regexp_join(vm, r);
}
} else {
if (r->part != r->parts.start) {
r->part = nxt_array_add(&r->parts, &njs_array_mem_proto,
vm->mem_pool);
if (nxt_slow_path(r->part == NULL)) {
return NXT_ERROR;
}
r->part = nxt_array_add(&r->parts, &njs_array_mem_proto,
vm->mem_pool);
if (nxt_slow_path(r->part == NULL)) {
return NXT_ERROR;
}
r->part -= 2;
}
if (captures[1] == 0) {
start = r->part[0].start;
if (start < end) {
p = (u_char *) nxt_utf8_next(start, end);
r->part[1].start = start;
r->part[1].size = p - start;
r->part[2].start = p;
r->part[2].size = end - p;
} else {
r->part[1].size = 0;
r->part[2].size = 0;
r->part[2].start = start + 1;
}
r->part[0] = replace;
} else {
r->part[2].start = r->part[0].start + captures[1];
r->part[2].size = r->part[0].size - captures[1];
njs_set_invalid(&r->part[2].value);
if (r->function != NULL) {
return njs_string_replace_regexp_function(vm, args, r,
captures, ret);
}
r->part[0].size = captures[0];
r->part[1] = replace;
}
if (!pattern->global) {
return njs_string_replace_regexp_join(vm, r);
}
r->part += 2;
}
} else if (ret == NXT_REGEX_NOMATCH) {
break;
} else {
return NXT_ERROR;
}
} while (r->part[0].start <= end);
if (r->part != r->parts.start) {
return njs_string_replace_regexp_join(vm, r);
}
nxt_regex_match_data_free(r->match_data, vm->regex_context);
nxt_array_destroy(&r->parts, &njs_array_mem_proto, vm->mem_pool);
njs_string_copy(&vm->retval, &args[0]);
return NXT_OK;
}

static void read_in_new_ascii(struct new_cpio_header *file_hdr, int in_des)
{
char ascii_header[13*8], *ah, hexbuf[9];
int i;
tape_buffered_read(ascii_header, in_des, 13*8);
ah = ascii_header;
hexbuf[8] = '\0';
for (i = 0; i < 13; i++) {
memcpy(hexbuf, ah, 8);
file_hdr->c_hdr[i] = strtoul(hexbuf, NULL, 16);
ah += 8;
}
free(file_hdr->c_name);
file_hdr->c_name = (char *)xmalloc(file_hdr->c_namesize);
tape_buffered_read(file_hdr->c_name, in_des,
(long)file_hdr->c_namesize);
tape_skip_padding(in_des, file_hdr->c_namesize + 110);
}

static js_Ast *bitxor(js_State *J, int notin)
{
js_Ast *a = bitand(J, notin);
while (jsP_accept(J, '^'))
a = EXP2(BITXOR, a, bitand(J, notin));
return a;
}

static gboolean
xcf_load_channel_props (XcfInfo      *info,
GimpImage    *image,
GimpChannel **channel)
{
PropType prop_type;
guint32  prop_size;
while (TRUE)
{
if (! xcf_load_prop (info, &prop_type, &prop_size))
return FALSE;
switch (prop_type)
{
case PROP_END:
return TRUE;
case PROP_ACTIVE_CHANNEL:
info->active_channel = *channel;
break;
case PROP_SELECTION:
{
GimpChannel *mask;
mask =
gimp_selection_new (image,
gimp_item_get_width  (GIMP_ITEM (*channel)),
gimp_item_get_height (GIMP_ITEM (*channel)));
gimp_image_take_mask (image, mask);
tile_manager_unref (GIMP_DRAWABLE (mask)->private->tiles);
GIMP_DRAWABLE (mask)->private->tiles =
GIMP_DRAWABLE (*channel)->private->tiles;
GIMP_DRAWABLE (*channel)->private->tiles = NULL;
g_object_unref (*channel);
*channel = mask;
(*channel)->boundary_known = FALSE;
(*channel)->bounds_known   = FALSE;
}
break;
case PROP_OPACITY:
{
guint32 opacity;
info->cp += xcf_read_int32 (info->fp, &opacity, 1);
gimp_channel_set_opacity (*channel, opacity / 255.0, FALSE);
}
break;
case PROP_VISIBLE:
{
gboolean visible;
info->cp += xcf_read_int32 (info->fp, (guint32 *) &visible, 1);
gimp_item_set_visible (GIMP_ITEM (*channel),
visible ? TRUE : FALSE, FALSE);
}
break;
case PROP_LINKED:
{
gboolean linked;
info->cp += xcf_read_int32 (info->fp, (guint32 *) &linked, 1);
gimp_item_set_linked (GIMP_ITEM (*channel),
linked ? TRUE : FALSE, FALSE);
}
break;
case PROP_LOCK_CONTENT:
{
gboolean lock_content;
info->cp += xcf_read_int32 (info->fp, (guint32 *) &lock_content, 1);
gimp_item_set_lock_content (GIMP_ITEM (*channel),
lock_content ? TRUE : FALSE, FALSE);
}
break;
case PROP_SHOW_MASKED:
{
gboolean show_masked;
info->cp += xcf_read_int32 (info->fp, (guint32 *) &show_masked, 1);
gimp_channel_set_show_masked (*channel, show_masked);
}
break;
case PROP_COLOR:
{
guchar col[3];
info->cp += xcf_read_int8 (info->fp, (guint8 *) col, 3);
gimp_rgb_set_uchar (&(*channel)->color, col[0], col[1], col[2]);
}
break;
case PROP_TATTOO:
{
GimpTattoo tattoo;
info->cp += xcf_read_int32 (info->fp, (guint32 *) &tattoo, 1);
gimp_item_set_tattoo (GIMP_ITEM (*channel), tattoo);
}
break;
case PROP_PARASITES:
{
glong base = info->cp;
while ((info->cp - base) < prop_size)
{
GimpParasite *p = xcf_load_parasite (info);
if (! p)
return FALSE;
gimp_item_parasite_attach (GIMP_ITEM (*channel), p, FALSE);
gimp_parasite_free (p);
}
if (info->cp - base != prop_size)
gimp_message_literal (info->gimp, G_OBJECT (info->progress),
GIMP_MESSAGE_WARNING,
"Error while loading a channel's parasites");
}
break;
default:
#ifdef GIMP_UNSTABLE
g_printerr ("unexpected/unknown channel property: %d (skipping)\n",
prop_type);
#endif
if (! xcf_skip_unknown_prop (info, prop_size))
return FALSE;
break;
}
}
return FALSE;
}

