void gf_isom_delete_movie(GF_ISOFile *mov)
{
if (!mov) return;
if (mov->movieFileMap) gf_isom_datamap_del(mov->movieFileMap);
#ifndef GPAC_DISABLE_ISOM_WRITE
if (mov->editFileMap) {
gf_isom_datamap_del(mov->editFileMap);
}
if (mov->finalName) gf_free(mov->finalName);
#endif
gf_isom_box_array_del(mov->TopBoxes);
#ifndef GPAC_DISABLE_ISOM_FRAGMENTS
gf_isom_box_array_del(mov->moof_list);
if (mov->mfra)
gf_isom_box_del((GF_Box*)mov->mfra);
if (mov->sidx_pts_store)
gf_free(mov->sidx_pts_store);
if (mov->sidx_pts_next_store)
gf_free(mov->sidx_pts_next_store);
if (mov->main_sidx)
gf_isom_box_del((GF_Box*)mov->main_sidx);
if (mov->block_buffer)
gf_free(mov->block_buffer);
#endif
if (mov->last_producer_ref_time)
gf_isom_box_del((GF_Box *) mov->last_producer_ref_time);
if (mov->fileName) gf_free(mov->fileName);
gf_free(mov);
}

static void fz_cached_color_convert(fz_context *ctx, fz_color_converter *cc_, const float *ss, float *ds)
{
fz_cached_color_converter *cc = cc_->opaque;
float *val = fz_hash_find(ctx, cc->hash, ss);
int n = cc->base.ds->n * sizeof(float);
if (val)
{
memcpy(ds, val, n);
return;
}
cc->base.convert(ctx, &cc->base, ss, ds);
val = Memento_label(fz_malloc_array(ctx, cc->base.ds->n, float), "cached_color_convert");
memcpy(val, ds, n);
fz_try(ctx)
fz_hash_insert(ctx, cc->hash, ss, val);
fz_catch(ctx)
fz_free(ctx, val);
}

static OPJ_BOOL opj_j2k_update_image_dimensions(opj_image_t* p_image,
opj_event_mgr_t * p_manager)
{
OPJ_UINT32 it_comp;
OPJ_INT32 l_comp_x1, l_comp_y1;
opj_image_comp_t* l_img_comp = NULL;
l_img_comp = p_image->comps;
for (it_comp = 0; it_comp < p_image->numcomps; ++it_comp) {
OPJ_INT32 l_h, l_w;
l_img_comp->x0 = (OPJ_UINT32)opj_int_ceildiv((OPJ_INT32)p_image->x0,
(OPJ_INT32)l_img_comp->dx);
l_img_comp->y0 = (OPJ_UINT32)opj_int_ceildiv((OPJ_INT32)p_image->y0,
(OPJ_INT32)l_img_comp->dy);
l_comp_x1 = opj_int_ceildiv((OPJ_INT32)p_image->x1, (OPJ_INT32)l_img_comp->dx);
l_comp_y1 = opj_int_ceildiv((OPJ_INT32)p_image->y1, (OPJ_INT32)l_img_comp->dy);
l_w = opj_int_ceildivpow2(l_comp_x1, (OPJ_INT32)l_img_comp->factor)
- opj_int_ceildivpow2((OPJ_INT32)l_img_comp->x0, (OPJ_INT32)l_img_comp->factor);
if (l_w < 0) {
opj_event_msg(p_manager, EVT_ERROR,
"Size x of the decoded component image is incorrect (comp[%d].w=%d).\n",
it_comp, l_w);
return OPJ_FALSE;
}
l_img_comp->w = (OPJ_UINT32)l_w;
l_h = opj_int_ceildivpow2(l_comp_y1, (OPJ_INT32)l_img_comp->factor)
- opj_int_ceildivpow2((OPJ_INT32)l_img_comp->y0, (OPJ_INT32)l_img_comp->factor);
if (l_h < 0) {
opj_event_msg(p_manager, EVT_ERROR,
"Size y of the decoded component image is incorrect (comp[%d].h=%d).\n",
it_comp, l_h);
return OPJ_FALSE;
}
l_img_comp->h = (OPJ_UINT32)l_h;
l_img_comp++;
}
return OPJ_TRUE;
}

int LibRaw::unpack_thumb(void)
{
CHECK_ORDER_LOW(LIBRAW_PROGRESS_IDENTIFY);
CHECK_ORDER_BIT(LIBRAW_PROGRESS_THUMB_LOAD);
try
{
if (!libraw_internal_data.internal_data.input)
return LIBRAW_INPUT_CLOSED;
int t_colors = libraw_internal_data.unpacker_data.thumb_misc >> 5 & 7;
int t_bytesps = (libraw_internal_data.unpacker_data.thumb_misc & 31) / 8;
if (!ID.toffset && !(imgdata.thumbnail.tlength > 0 &&
load_raw == &LibRaw::broadcom_load_raw)     )
{
return LIBRAW_NO_THUMBNAIL;
}
else if (thumb_load_raw)
{
kodak_thumb_loader();
T.tformat = LIBRAW_THUMBNAIL_BITMAP;
SET_PROC_FLAG(LIBRAW_PROGRESS_THUMB_LOAD);
return 0;
}
else
{
#ifdef USE_X3FTOOLS
if (write_thumb == &LibRaw::x3f_thumb_loader)
{
INT64 tsize = x3f_thumb_size();
if (tsize < 2048 || INT64(ID.toffset) + tsize < 1)
throw LIBRAW_EXCEPTION_IO_CORRUPT;
if (INT64(ID.toffset) + tsize > ID.input->size() + THUMB_READ_BEYOND)
throw LIBRAW_EXCEPTION_IO_EOF;
}
#else
if (0) {}
#endif
else
{
if (INT64(ID.toffset) + INT64(T.tlength) < 1)
throw LIBRAW_EXCEPTION_IO_CORRUPT;
if (INT64(ID.toffset) + INT64(T.tlength) >
ID.input->size() + THUMB_READ_BEYOND)
throw LIBRAW_EXCEPTION_IO_EOF;
}
ID.input->seek(ID.toffset, SEEK_SET);
if (write_thumb == &LibRaw::jpeg_thumb)
{
if (T.thumb)
free(T.thumb);
T.thumb = (char *)malloc(T.tlength);
merror(T.thumb, "jpeg_thumb()");
ID.input->read(T.thumb, 1, T.tlength);
unsigned char *tthumb = (unsigned char *)T.thumb;
tthumb[0] = 0xff;
tthumb[1] = 0xd8;
#ifdef NO_JPEG
T.tcolors = 3;
#else
{
jpegErrorManager jerr;
struct jpeg_decompress_struct cinfo;
cinfo.err = jpeg_std_error(&jerr.pub);
jerr.pub.error_exit = jpegErrorExit;
if (setjmp(jerr.setjmp_buffer))
{
err2:
jpeg_destroy_decompress(&cinfo);
T.tcolors = 3;
T.tformat = LIBRAW_THUMBNAIL_UNKNOWN;
ID.input->seek(ID.toffset, SEEK_SET);
ID.input->read(T.thumb, 1, T.tlength);
SET_PROC_FLAG(LIBRAW_PROGRESS_THUMB_LOAD);
return 0;
}
jpeg_create_decompress(&cinfo);
jpeg_mem_src(&cinfo, (unsigned char *)T.thumb, T.tlength);
int rc = jpeg_read_header(&cinfo, TRUE);
if (rc != 1)
goto err2;
T.tcolors = (cinfo.num_components > 0 && cinfo.num_components <= 3)
? cinfo.num_components
: 3;
jpeg_destroy_decompress(&cinfo);
}
#endif
T.tformat = LIBRAW_THUMBNAIL_JPEG;
SET_PROC_FLAG(LIBRAW_PROGRESS_THUMB_LOAD);
return 0;
}
else if (write_thumb == &LibRaw::layer_thumb)
{
int colors = libraw_internal_data.unpacker_data.thumb_misc >> 5 & 7;
if (colors != 1 && colors != 3)
return LIBRAW_UNSUPPORTED_THUMBNAIL;
int tlength = T.twidth * T.theight;
if (T.thumb)
free(T.thumb);
T.thumb = (char *)calloc(colors, tlength);
merror(T.thumb, "layer_thumb()");
unsigned char *tbuf = (unsigned char *)calloc(colors, tlength);
merror(tbuf, "layer_thumb()");
ID.input->read(tbuf, colors, T.tlength);
if (libraw_internal_data.unpacker_data.thumb_misc >> 8 &&
colors == 3)           for (int i = 0; i < tlength; i++)
{
T.thumb[i * 3] = tbuf[i + tlength];
T.thumb[i * 3 + 1] = tbuf[i];
T.thumb[i * 3 + 2] = tbuf[i + 2 * tlength];
}
else if (colors == 3)           for (int i = 0; i < tlength; i++)
{
T.thumb[i * 3] = tbuf[i];
T.thumb[i * 3 + 1] = tbuf[i + tlength];
T.thumb[i * 3 + 2] = tbuf[i + 2 * tlength];
}
else if (colors == 1)
{
free(T.thumb);
T.thumb = (char *)tbuf;
tbuf = 0;
}
if (tbuf)
free(tbuf);
T.tcolors = colors;
T.tlength = colors * tlength;
T.tformat = LIBRAW_THUMBNAIL_BITMAP;
SET_PROC_FLAG(LIBRAW_PROGRESS_THUMB_LOAD);
return 0;
}
else if (write_thumb == &LibRaw::rollei_thumb)
{
int i;
int tlength = T.twidth * T.theight;
if (T.thumb)
free(T.thumb);
T.tcolors = 3;
T.thumb = (char *)calloc(T.tcolors, tlength);
merror(T.thumb, "layer_thumb()");
unsigned short *tbuf = (unsigned short *)calloc(2, tlength);
merror(tbuf, "layer_thumb()");
read_shorts(tbuf, tlength);
for (i = 0; i < tlength; i++)
{
T.thumb[i * 3] = (tbuf[i] << 3) & 0xff;
T.thumb[i * 3 + 1] = (tbuf[i] >> 5 << 2) & 0xff;
T.thumb[i * 3 + 2] = (tbuf[i] >> 11 << 3) & 0xff;
}
free(tbuf);
T.tlength = T.tcolors * tlength;
T.tformat = LIBRAW_THUMBNAIL_BITMAP;
SET_PROC_FLAG(LIBRAW_PROGRESS_THUMB_LOAD);
return 0;
}
else if (write_thumb == &LibRaw::ppm_thumb)
{
if (t_bytesps > 1)
throw LIBRAW_EXCEPTION_IO_CORRUPT;                                                      int t_length = T.twidth * T.theight * t_colors;
if (T.tlength &&
(int)T.tlength < t_length)         {
int pifd = find_ifd_by_offset(libraw_internal_data.internal_data.toffset);
if (pifd >= 0 && tiff_ifd[pifd].strip_offsets_count &&
tiff_ifd[pifd].strip_byte_counts_count)
{
unsigned total_size = 0;
for (int i = 0; i < tiff_ifd[pifd].strip_byte_counts_count; i++)
total_size += tiff_ifd[pifd].strip_byte_counts[i];
if (total_size != (unsigned)t_length)             {
if (total_size == T.twidth * T.tlength * 3)
T.tcolors = 3;
else if (total_size == T.twidth * T.tlength)
T.tcolors = 1;
}
T.tlength = total_size;
if (T.thumb)
free(T.thumb);
T.thumb = (char *)malloc(T.tlength);
merror(T.thumb, "ppm_thumb()");
char *dest = T.thumb;
INT64 pos = ID.input->tell();
for (int i = 0; i < tiff_ifd[pifd].strip_byte_counts_count &&
i < tiff_ifd[pifd].strip_offsets_count;
i++)
{
int remain = T.tlength;
int sz = tiff_ifd[pifd].strip_byte_counts[i];
int off = tiff_ifd[pifd].strip_offsets[i];
if (off >= 0 && off + sz <= ID.input->size() && sz <= remain)
{
ID.input->seek(off, SEEK_SET);
ID.input->read(dest, sz, 1);
remain -= sz;
dest += sz;
}
}
ID.input->seek(pos, SEEK_SET);
T.tformat = LIBRAW_THUMBNAIL_BITMAP;
SET_PROC_FLAG(LIBRAW_PROGRESS_THUMB_LOAD);
return 0;
}
}
if (!T.tlength)
T.tlength = t_length;
if (T.thumb)
free(T.thumb);
T.thumb = (char *)malloc(T.tlength);
if (!T.tcolors)
T.tcolors = t_colors;
merror(T.thumb, "ppm_thumb()");
ID.input->read(T.thumb, 1, T.tlength);
T.tformat = LIBRAW_THUMBNAIL_BITMAP;
SET_PROC_FLAG(LIBRAW_PROGRESS_THUMB_LOAD);
return 0;
}
else if (write_thumb == &LibRaw::ppm16_thumb)
{
if (t_bytesps > 2)
throw LIBRAW_EXCEPTION_IO_CORRUPT;                                                      int o_bps = (imgdata.params.raw_processing_options &
LIBRAW_PROCESSING_USE_PPM16_THUMBS)
? 2
: 1;
int o_length = T.twidth * T.theight * t_colors * o_bps;
int i_length = T.twidth * T.theight * t_colors * 2;
if (!T.tlength)
T.tlength = o_length;
ushort *t_thumb = (ushort *)calloc(i_length, 1);
ID.input->read(t_thumb, 1, i_length);
if ((libraw_internal_data.unpacker_data.order == 0x4949) ==
(ntohs(0x1234) == 0x1234))
swab((char *)t_thumb, (char *)t_thumb, i_length);
if (T.thumb)
free(T.thumb);
if ((imgdata.params.raw_processing_options &
LIBRAW_PROCESSING_USE_PPM16_THUMBS))
{
T.thumb = (char *)t_thumb;
T.tformat = LIBRAW_THUMBNAIL_BITMAP16;
}
else
{
T.thumb = (char *)malloc(o_length);
merror(T.thumb, "ppm_thumb()");
for (int i = 0; i < o_length; i++)
T.thumb[i] = t_thumb[i] >> 8;
free(t_thumb);
T.tformat = LIBRAW_THUMBNAIL_BITMAP;
}
SET_PROC_FLAG(LIBRAW_PROGRESS_THUMB_LOAD);
return 0;
}
#ifdef USE_X3FTOOLS
else if (write_thumb == &LibRaw::x3f_thumb_loader)
{
x3f_thumb_loader();
SET_PROC_FLAG(LIBRAW_PROGRESS_THUMB_LOAD);
return 0;
}
#endif
else
{
return LIBRAW_UNSUPPORTED_THUMBNAIL;
}
}
return LIBRAW_UNSUPPORTED_THUMBNAIL;
}
catch (LibRaw_exceptions err)
{
EXCEPTION_HANDLER(err);
}
}

static int
set_acl(struct archive *a, int fd, const char *name,
struct archive_acl *abstract_acl,
int ae_requested_type, const char *tname)
{
int acl_type = 0;
int ae_type, ae_permset, ae_tag, ae_id;
uid_t ae_uid;
gid_t ae_gid;
const char*ae_name;
int entries;
int i;
int ret;
acl_t acl = NULL;
acl_entry_t acl_entry;
acl_permset_t acl_permset;
ret = ARCHIVE_OK;
entries = archive_acl_reset(abstract_acl, ae_requested_type);
if (entries == 0)
return (ARCHIVE_OK);
switch (ae_requested_type) {
case ARCHIVE_ENTRY_ACL_TYPE_ACCESS:
acl_type = ACL_TYPE_ACCESS;
break;
case ARCHIVE_ENTRY_ACL_TYPE_DEFAULT:
acl_type = ACL_TYPE_DEFAULT;
break;
default:
errno = ENOENT;
archive_set_error(a, errno, "Unsupported ACL type");
return (ARCHIVE_FAILED);
}
acl = acl_init(entries);
if (acl == (acl_t)NULL) {
archive_set_error(a, errno,
"Failed to initialize ACL working storage");
return (ARCHIVE_FAILED);
}
while (archive_acl_next(a, abstract_acl, ae_requested_type, &ae_type,
&ae_permset, &ae_tag, &ae_id, &ae_name) == ARCHIVE_OK) {
if (acl_create_entry(&acl, &acl_entry) != 0) {
archive_set_error(a, errno,
"Failed to create a new ACL entry");
ret = ARCHIVE_FAILED;
goto exit_free;
}
switch (ae_tag) {
case ARCHIVE_ENTRY_ACL_USER:
ae_uid = archive_write_disk_uid(a, ae_name, ae_id);
acl_set_tag_type(acl_entry, ACL_USER);
acl_set_qualifier(acl_entry, &ae_uid);
break;
case ARCHIVE_ENTRY_ACL_GROUP:
ae_gid = archive_write_disk_gid(a, ae_name, ae_id);
acl_set_tag_type(acl_entry, ACL_GROUP);
acl_set_qualifier(acl_entry, &ae_gid);
break;
case ARCHIVE_ENTRY_ACL_USER_OBJ:
acl_set_tag_type(acl_entry, ACL_USER_OBJ);
break;
case ARCHIVE_ENTRY_ACL_GROUP_OBJ:
acl_set_tag_type(acl_entry, ACL_GROUP_OBJ);
break;
case ARCHIVE_ENTRY_ACL_MASK:
acl_set_tag_type(acl_entry, ACL_MASK);
break;
case ARCHIVE_ENTRY_ACL_OTHER:
acl_set_tag_type(acl_entry, ACL_OTHER);
break;
default:
archive_set_error(a, ARCHIVE_ERRNO_MISC,
"Unsupported ACL tag");
ret = ARCHIVE_FAILED;
goto exit_free;
}
if (acl_get_permset(acl_entry, &acl_permset) != 0) {
archive_set_error(a, errno,
"Failed to get ACL permission set");
ret = ARCHIVE_FAILED;
goto exit_free;
}
if (acl_clear_perms(acl_permset) != 0) {
archive_set_error(a, errno,
"Failed to clear ACL permissions");
ret = ARCHIVE_FAILED;
goto exit_free;
}
for (i = 0; i < acl_posix_perm_map_size; ++i) {
if (ae_permset & acl_posix_perm_map[i].a_perm) {
if (acl_add_perm(acl_permset,
acl_posix_perm_map[i].p_perm) != 0) {
archive_set_error(a, errno,
"Failed to add ACL permission");
ret = ARCHIVE_FAILED;
goto exit_free;
}
}
}
}
if (fd >= 0 && ae_requested_type == ARCHIVE_ENTRY_ACL_TYPE_ACCESS) {
if (acl_set_fd(fd, acl) == 0)
ret = ARCHIVE_OK;
else {
if (errno == EOPNOTSUPP) {
ret = ARCHIVE_OK;
} else {
archive_set_error(a, errno,
"Failed to set acl on fd: %s", tname);
ret = ARCHIVE_WARN;
}
}
} else if (acl_set_file(name, acl_type, acl) != 0) {
if (errno == EOPNOTSUPP) {
ret = ARCHIVE_OK;
} else {
archive_set_error(a, errno, "Failed to set acl: %s",
tname);
ret = ARCHIVE_WARN;
}
}
exit_free:
acl_free(acl);
return (ret);
}

