uint
bjc_compress(const byte *row, uint raster, byte *compressed)
{
const byte *end_row = row;
register const byte *exam = row;
register byte *cptr = compressed; 
end_row += raster;
while ( exam < end_row ) {
const byte *compr = exam;
const byte *end_dis;
const byte *next;
register byte test, test2;
test = *exam;
while ( exam < end_row ) {
test2 = *++exam;
if ( test == test2 )
break;
test = test2;
}
end_dis = exam - 1;
if ( exam == end_row ) { 
next = --end_row;
} else {
next = exam + 1;
while ( next < end_row && *next == test ) next++;
}
for ( ; ; ) { 
uint count = end_dis - compr; 
switch ( count ) { 
case 6: cptr[6] = compr[5];
case 5: cptr[5] = compr[4];
case 4: cptr[4] = compr[3];
case 3: cptr[3] = compr[2];
case 2: cptr[2] = compr[1];
case 1: cptr[1] = compr[0];
*cptr = count - 1;
cptr += count + 1;
case 0: 
break;
default:
if ( count > 128 ) count = 128;
*cptr++ = count - 1;
memcpy(cptr, compr, count);
cptr += count, compr += count;
continue;
}
break;
}
{ 
int count = next - end_dis;
if (next < end_row || test != 0)
while ( count > 0 ) {
int this = (count > 128 ? 128 : count);
*cptr++ = 257 - this;
*cptr++ = (byte)test;
count -= this;
}
exam = next;
}
}
return (uint)(cptr - compressed);
}

static int
read_2004_compressed_section (Bit_Chain *dat, Dwg_Data *restrict dwg,
Bit_Chain *sec_dat, Dwg_Section_Type type)
{
uint32_t address, sec_mask, initial_address;
uint32_t max_decomp_size;
long bytes_left;
Dwg_Section_Info *info = NULL;
encrypted_section_header es;
BITCODE_RC *decomp;
BITCODE_BL i, j;
int error = 0;
for (i = 0; i < dwg->header.section_infohdr.num_desc && !info; ++i)
{
if (dwg->header.section_info[i].fixedtype == type)
{
info = &dwg->header.section_info[i];
break;
}
}
sec_dat->chain = NULL;   if (!info)
{
if (type < SECTION_REVHISTORY
&& type != SECTION_TEMPLATE
&& type != SECTION_OBJFREESPACE)
{
LOG_WARN ("Failed to find section_info[%u] with type %d", i, type)
}
else
{
LOG_TRACE ("Found no section_info[%u] with type %d\n", i, type)
}
return DWG_ERR_SECTIONNOTFOUND;
}
else
{
LOG_TRACE ("\nFound section_info[" FORMAT_BL
"] %s type %d with %d sections (%scompressed):\n",
i, info->name, type, info->num_sections,
info->compressed == 2 ? "" : "un");
}
max_decomp_size = info->num_sections * info->max_decomp_size;
if (info->num_sections == 0)
return 0;
if (max_decomp_size == 0 || max_decomp_size > 0x2f000000)     {
LOG_ERROR ("Invalid section %s count or max decompression size. "
"Sections: %u, Max size: %u",
info->name, info->num_sections, info->max_decomp_size);
return DWG_ERR_INVALIDDWG;
}
decomp = (BITCODE_RC *)calloc (max_decomp_size, sizeof (BITCODE_RC));
if (!decomp)
{
LOG_ERROR ("Out of memory with %u sections", info->num_sections);
return DWG_ERR_OUTOFMEM;
}
bytes_left = max_decomp_size;
initial_address = info->sections[0] ? info->sections[0]->address : 0;
sec_dat->bit = 0;
sec_dat->byte = 0;
sec_dat->version = dat->version;
sec_dat->from_version = dat->from_version;
sec_dat->chain = decomp;
for (i = 0; i < info->num_sections; ++i)
{
if (!info->sections[i])
{
LOG_WARN ("Skip empty section %u %s", i, info->name);
continue;
}
address = info->sections[i]->address;
dat->byte = address;
bit_read_fixed (dat, es.char_data, 32);
sec_mask = 0x4164536b ^ address;
for (j = 0; j < 8; ++j)
es.long_data[j] ^= sec_mask;
LOG_INFO ("=== Section %s (%u) @%u ===\n", info->name, i, address)
if (es.fields.tag != 0x4163043b)
{
LOG_WARN ("Section Tag:      0x%x  (should be 0x4163043b)",
(unsigned)es.fields.tag);
}
else
{
LOG_INFO ("Section Tag:      0x%x\n", (unsigned)es.fields.tag);
}
LOG_INFO ("Section Type:     %u\n", (unsigned)es.fields.section_type)
LOG_INFO ("Data size:        0x%x/%u\n", (unsigned)es.fields.data_size,
(unsigned)es.fields.data_size)
LOG_INFO ("Comp data size:   0x%x\n", (unsigned)es.fields.section_size)
LOG_TRACE ("StartOffset:      0x%x\n", (unsigned)es.fields.address)
LOG_HANDLE ("Unknown:          0x%x\n", (unsigned)es.fields.unknown)
LOG_HANDLE ("Checksum1:        0x%x\n", (unsigned)es.fields.checksum_1)
LOG_HANDLE ("Checksum2:        0x%x\n", (unsigned)es.fields.checksum_2)
LOG_TRACE ("Section start:    %lu\n\n", dat->byte);
LOG_INSANE ("info[%d]->max_decomp_size: %lu (0x%lx)\n", i,
(unsigned long)info->max_decomp_size,
(unsigned long)info->max_decomp_size)
LOG_INSANE ("max_decomp_size:          %lu (0x%lx)\n",
(unsigned long)max_decomp_size,
(unsigned long)max_decomp_size)
LOG_INSANE ("bytes_left:               %ld\n", bytes_left);
if (info->compressed == 2
&& bytes_left > 0
&& (i * info->max_decomp_size) <= max_decomp_size)
{
error = decompress_R2004_section (
dat, &decomp[i * info->max_decomp_size],               info->max_decomp_size, es.fields.data_size);
if (error > DWG_ERR_CRITICAL)
{
sec_dat->chain = NULL;               free (decomp);
return error;
}
bytes_left -= info->max_decomp_size;
sec_dat->size = max_decomp_size;
}
else
{
if (info->compressed == 2
|| info->size > max_decomp_size
|| bytes_left < 0
)
{
LOG_ERROR ("Some section size out of bounds")
sec_dat->chain = NULL;
free (decomp);
return type < SECTION_REVHISTORY ? DWG_ERR_INVALIDDWG
: DWG_ERR_VALUEOUTOFBOUNDS;
}
memcpy (&decomp[i * info->size],
&dat->chain[address + es.fields.address + 32],
MIN (bytes_left, info->size));
bytes_left -= info->size;
sec_dat->size = max_decomp_size;
}
}
return error;
}

void *XMLCALL
XML_GetBuffer(XML_Parser parser, int len) {
if (parser == NULL)
return NULL;
if (len < 0) {
parser->m_errorCode = XML_ERROR_NO_MEMORY;
return NULL;
}
switch (parser->m_parsingStatus.parsing) {
case XML_SUSPENDED:
parser->m_errorCode = XML_ERROR_SUSPENDED;
return NULL;
case XML_FINISHED:
parser->m_errorCode = XML_ERROR_FINISHED;
return NULL;
default:;
}
if (len > EXPAT_SAFE_PTR_DIFF(parser->m_bufferLim, parser->m_bufferEnd)) {
#ifdef XML_CONTEXT_BYTES
int keep;
#endif 
int neededSize = (int)((unsigned)len
+ (unsigned)EXPAT_SAFE_PTR_DIFF(
parser->m_bufferEnd, parser->m_bufferPtr));
if (neededSize < 0) {
parser->m_errorCode = XML_ERROR_NO_MEMORY;
return NULL;
}
#ifdef XML_CONTEXT_BYTES
keep = (int)EXPAT_SAFE_PTR_DIFF(parser->m_bufferPtr, parser->m_buffer);
if (keep > XML_CONTEXT_BYTES)
keep = XML_CONTEXT_BYTES;
neededSize += keep;
#endif 
if (neededSize
<= EXPAT_SAFE_PTR_DIFF(parser->m_bufferLim, parser->m_buffer)) {
#ifdef XML_CONTEXT_BYTES
if (keep < EXPAT_SAFE_PTR_DIFF(parser->m_bufferPtr, parser->m_buffer)) {
int offset
= (int)EXPAT_SAFE_PTR_DIFF(parser->m_bufferPtr, parser->m_buffer)
- keep;
memmove(parser->m_buffer, &parser->m_buffer[offset],
parser->m_bufferEnd - parser->m_bufferPtr + keep);
parser->m_bufferEnd -= offset;
parser->m_bufferPtr -= offset;
}
#else
if (parser->m_buffer && parser->m_bufferPtr) {
memmove(parser->m_buffer, parser->m_bufferPtr,
EXPAT_SAFE_PTR_DIFF(parser->m_bufferEnd, parser->m_bufferPtr));
parser->m_bufferEnd
= parser->m_buffer
+ EXPAT_SAFE_PTR_DIFF(parser->m_bufferEnd, parser->m_bufferPtr);
parser->m_bufferPtr = parser->m_buffer;
}
#endif 
} else {
char *newBuf;
int bufferSize
= (int)EXPAT_SAFE_PTR_DIFF(parser->m_bufferLim, parser->m_bufferPtr);
if (bufferSize == 0)
bufferSize = INIT_BUFFER_SIZE;
do {
bufferSize = (int)(2U * (unsigned)bufferSize);
} while (bufferSize < neededSize && bufferSize > 0);
if (bufferSize <= 0) {
parser->m_errorCode = XML_ERROR_NO_MEMORY;
return NULL;
}
newBuf = (char *)MALLOC(parser, bufferSize);
if (newBuf == 0) {
parser->m_errorCode = XML_ERROR_NO_MEMORY;
return NULL;
}
parser->m_bufferLim = newBuf + bufferSize;
#ifdef XML_CONTEXT_BYTES
if (parser->m_bufferPtr) {
memcpy(newBuf, &parser->m_bufferPtr[-keep],
EXPAT_SAFE_PTR_DIFF(parser->m_bufferEnd, parser->m_bufferPtr)
+ keep);
FREE(parser, parser->m_buffer);
parser->m_buffer = newBuf;
parser->m_bufferEnd
= parser->m_buffer
+ EXPAT_SAFE_PTR_DIFF(parser->m_bufferEnd, parser->m_bufferPtr)
+ keep;
parser->m_bufferPtr = parser->m_buffer + keep;
} else {
parser->m_bufferEnd = newBuf;
parser->m_bufferPtr = parser->m_buffer = newBuf;
}
#else
if (parser->m_bufferPtr) {
memcpy(newBuf, parser->m_bufferPtr,
EXPAT_SAFE_PTR_DIFF(parser->m_bufferEnd, parser->m_bufferPtr));
FREE(parser, parser->m_buffer);
parser->m_bufferEnd
= newBuf
+ EXPAT_SAFE_PTR_DIFF(parser->m_bufferEnd, parser->m_bufferPtr);
} else {
parser->m_bufferEnd = newBuf;
}
parser->m_bufferPtr = parser->m_buffer = newBuf;
#endif 
}
parser->m_eventPtr = parser->m_eventEndPtr = NULL;
parser->m_positionPtr = NULL;
}
return parser->m_bufferEnd;
}

void  process_command_opts (int argc, char *argv[], char *mp, char *mode, uint32_t *dirnum,
uint16_t *defconfig, uint16_t *deffillorder, uint32_t *deftilewidth,
uint32_t *deftilelength, uint32_t *defrowsperstrip,
struct crop_mask *crop_data, struct pagedef *page,
struct dump_opts *dump,
unsigned int     *imagelist, unsigned int   *image_count )
{
int   c, good_args = 0;
char *opt_offset   = NULL;    
char *opt_ptr      = NULL;    
char *sep          = NULL;    
unsigned int  i, j, start, end;
#if !HAVE_DECL_OPTARG
extern int   optind;
extern char* optarg;
#endif
*mp++ = 'w';
*mp = '\0';
while ((c = getopt(argc, argv,
"ac:d:e:f:hik:l:m:p:r:stvw:z:BCD:E:F:H:I:J:K:LMN:O:P:R:S:U:V:X:Y:Z:")) != -1)
{
good_args++;
switch (c) {
case 'a': mode[0] = 'a';
break;
case 'c':if (!processCompressOptions(optarg)) 
{
TIFFError ("Unknown compression option", "%s", optarg);
TIFFError ("For valid options type", "tiffcrop -h");
exit (EXIT_FAILURE);
}
break;
case 'd':start = strtoul(optarg, NULL, 0); 
if (start == 0)
{
TIFFError ("","Directory offset must be greater than zero");
TIFFError ("For valid options type", "tiffcrop -h");
exit (EXIT_FAILURE);
}
*dirnum = start - 1;
break;
case 'e': switch (tolower((int) optarg[0])) 
{
case 'c': crop_data->exp_mode = ONE_FILE_COMPOSITE;
crop_data->img_mode = COMPOSITE_IMAGES;
break; 
case 'd': crop_data->exp_mode = ONE_FILE_SEPARATED;
crop_data->img_mode = SEPARATED_IMAGES;
break; 
case 'i': crop_data->exp_mode = FILE_PER_IMAGE_COMPOSITE;
crop_data->img_mode = COMPOSITE_IMAGES;
break; 
case 'm': crop_data->exp_mode = FILE_PER_IMAGE_SEPARATED;
crop_data->img_mode = SEPARATED_IMAGES;
break; 
case 's': crop_data->exp_mode = FILE_PER_SELECTION;
crop_data->img_mode = SEPARATED_IMAGES;
break; 
default:  TIFFError ("Unknown export mode","%s", optarg);
TIFFError ("For valid options type", "tiffcrop -h");
exit (EXIT_FAILURE);
}
break;
case 'f':if (streq(optarg, "lsb2msb"))   
*deffillorder = FILLORDER_LSB2MSB;
else if (streq(optarg, "msb2lsb"))
*deffillorder = FILLORDER_MSB2LSB;
else
{
TIFFError ("Unknown fill order", "%s", optarg);
TIFFError ("For valid options type", "tiffcrop -h");
exit (EXIT_FAILURE);
}
break;
case 'h':usage(EXIT_SUCCESS);
break;
case 'i':ignore = TRUE;
break;
case 'k':maxMalloc = (tmsize_t)strtoul(optarg, NULL, 0) << 20;
break;
case 'l':outtiled = TRUE; 
*deftilelength = atoi(optarg);
break;
case 'p': 
if (streq(optarg, "separate"))
*defconfig = PLANARCONFIG_SEPARATE;
else if (streq(optarg, "contig"))
*defconfig = PLANARCONFIG_CONTIG;
else
{
TIFFError ("Unknown planar configuration", "%s", optarg);
TIFFError ("For valid options type", "tiffcrop -h");
exit (EXIT_FAILURE);
}
break;
case 'r':
*defrowsperstrip = atol(optarg);
break;
case 's':
outtiled = FALSE;
break;
case 't':
outtiled = TRUE;
break;
case 'v': printf("Library Release: %s\n", TIFFGetVersion());
printf("Tiffcrop version: %s, last updated: %s\n",
tiffcrop_version_id, tiffcrop_rev_date);
printf("Tiffcp code: Copyright (c) 1988-1997 Sam Leffler\n");
printf("           : Copyright (c) 1991-1997 Silicon Graphics, Inc\n");
printf("Tiffcrop additions: Copyright (c) 2007-2010 Richard Nolde\n");
exit (EXIT_SUCCESS);
break;
case 'w':
outtiled = TRUE;
*deftilewidth = atoi(optarg);
break;
case 'z': 
crop_data->crop_mode |= CROP_REGIONS;
for (i = 0, opt_ptr = strtok (optarg, ":");
((opt_ptr != NULL) &&  (i < MAX_REGIONS));
(opt_ptr = strtok (NULL, ":")), i++)
{
crop_data->regions++;
if (sscanf(opt_ptr, "%lf,%lf,%lf,%lf",
&crop_data->corners[i].X1, &crop_data->corners[i].Y1,
&crop_data->corners[i].X2, &crop_data->corners[i].Y2) != 4)
{
TIFFError ("Unable to parse coordinates for region", "%u %s", i, optarg);
TIFFError ("For valid options type", "tiffcrop -h");
exit (EXIT_FAILURE);
}
}
if ((opt_ptr != NULL) && (i >= MAX_REGIONS))
{
TIFFError ("Region list exceeds limit of", "%d regions %s", MAX_REGIONS, optarg);
TIFFError ("For valid options type", "tiffcrop -h");
exit (EXIT_FAILURE);;
}
break;
case 'B': *mp++ = 'b'; *mp = '\0';
break;
case 'L': *mp++ = 'l'; *mp = '\0';
break;
case 'M': *mp++ = 'm'; *mp = '\0';
break;
case 'C': *mp++ = 'c'; *mp = '\0';
break;
case 'D': for (i = 0, opt_ptr = strtok (optarg, ",");
(opt_ptr != NULL);
(opt_ptr = strtok (NULL, ",")), i++)
{
opt_offset = strpbrk(opt_ptr, ":=");
if (opt_offset == NULL)
{
TIFFError("Invalid dump option", "%s", optarg);
TIFFError ("For valid options type", "tiffcrop -h");
exit (EXIT_FAILURE);
}
*opt_offset = '\0';
end = strlen (opt_ptr);
for (i = 0; i < end; i++)
*(opt_ptr + i) = tolower((int) *(opt_ptr + i));
if (strncmp(opt_ptr, "for", 3) == 0)
{
end = strlen (opt_offset + 1);
for (i = 1; i <= end; i++)
*(opt_offset + i) = tolower((int) *(opt_offset + i));
if (strncmp (opt_offset + 1, "txt", 3) == 0)
{
dump->format = DUMP_TEXT;
strcpy (dump->mode, "w");
}
else
{
if (strncmp(opt_offset + 1, "raw", 3) == 0)
{
dump->format = DUMP_RAW;
strcpy (dump->mode, "wb");
}
else
{
TIFFError("parse_command_opts", "Unknown dump format %s", opt_offset + 1);
TIFFError ("For valid options type", "tiffcrop -h");
exit (EXIT_FAILURE);
}
}
}
else
{ 
if (strncmp (opt_ptr, "lev", 3) == 0)
dump->level = atoi(opt_offset + 1);
if (strncmp (opt_ptr, "in", 2) == 0)
{
strncpy (dump->infilename, opt_offset + 1, PATH_MAX - 20);
dump->infilename[PATH_MAX - 20] = '\0';
}
if (strncmp (opt_ptr, "out", 3) == 0)
{
strncpy (dump->outfilename, opt_offset + 1, PATH_MAX - 20);
dump->outfilename[PATH_MAX - 20] = '\0';
}
if (strncmp (opt_ptr, "deb", 3) == 0)
dump->debug = atoi(opt_offset + 1);
}
}
if ((strlen(dump->infilename)) || (strlen(dump->outfilename)))
{
if (dump->level == 1)
TIFFError("","Defaulting to dump level 1, no data.");
if (dump->format == DUMP_NONE)
{
TIFFError("", "You must specify a dump format for dump files");
TIFFError ("For valid options type", "tiffcrop -h");
exit (EXIT_FAILURE);
}
}
break;
case 'm': 
crop_data->crop_mode |= CROP_MARGINS;
for (i = 0, opt_ptr = strtok (optarg, ",:");
((opt_ptr != NULL) &&  (i < 4));
(opt_ptr = strtok (NULL, ",:")), i++)
{
crop_data->margins[i] = atof(opt_ptr);
}
break;
case 'E':
switch (tolower((int) optarg[0]))
{
case 't': crop_data->edge_ref = EDGE_TOP;
break;
case 'b': crop_data->edge_ref = EDGE_BOTTOM;
break;
case 'l': crop_data->edge_ref = EDGE_LEFT;
break;
case 'r': crop_data->edge_ref = EDGE_RIGHT;
break;
default:  TIFFError ("Edge reference must be top, bottom, left, or right", "%s", optarg);
TIFFError ("For valid options type", "tiffcrop -h");
exit (EXIT_FAILURE);
}
break;
case 'F': 
crop_data->crop_mode |= CROP_MIRROR;
switch (tolower((int) optarg[0]))
{
case  'h': crop_data->mirror = MIRROR_HORIZ;
break;
case  'v': crop_data->mirror = MIRROR_VERT;
break;
case  'b': crop_data->mirror = MIRROR_BOTH;
break;
default:   TIFFError ("Flip mode must be horiz, vert, or both", "%s", optarg);
TIFFError ("For valid options type", "tiffcrop -h");
exit (EXIT_FAILURE);
}
break;
case 'H': 
page->hres = atof (optarg);
page->mode |= PAGE_MODE_RESOLUTION;
break;
case 'I': 
crop_data->crop_mode |= CROP_INVERT;
if (streq(optarg, "black"))
{
crop_data->photometric = PHOTOMETRIC_MINISBLACK;
continue;
}
if (streq(optarg, "white"))
{
crop_data->photometric = PHOTOMETRIC_MINISWHITE;
continue;
}
if (streq(optarg, "data")) 
{
crop_data->photometric = INVERT_DATA_ONLY;
continue;
}
if (streq(optarg, "both"))
{
crop_data->photometric = INVERT_DATA_AND_TAG;
continue;
}
TIFFError("Missing or unknown option for inverting PHOTOMETRIC_INTERPRETATION", "%s", optarg);
TIFFError ("For valid options type", "tiffcrop -h");
exit (EXIT_FAILURE);
break;
case 'J': 
page->hmargin = atof(optarg);
page->mode |= PAGE_MODE_MARGINS;
break;
case 'K': 
page->vmargin = atof(optarg);
page->mode |= PAGE_MODE_MARGINS;
break;
case 'N':
for (i = 0, opt_ptr = strtok (optarg, ",");
((opt_ptr != NULL) &&  (i < MAX_IMAGES));
(opt_ptr = strtok (NULL, ",")))
{ 
if (streq(opt_ptr, "odd"))
{
for (j = 1; j <= MAX_IMAGES; j += 2)
imagelist[i++] = j;
*image_count = (MAX_IMAGES - 1) / 2;
break;
}
else
{
if (streq(opt_ptr, "even"))
{
for (j = 2; j <= MAX_IMAGES; j += 2)
imagelist[i++] = j;
*image_count = MAX_IMAGES / 2;
break;
}
else
{
if (streq(opt_ptr, "last"))
imagelist[i++] = MAX_IMAGES;
else  
{
sep = strpbrk(opt_ptr, ":-");
if (!sep)
imagelist[i++] = atoi(opt_ptr);
else
{
*sep = '\0';
start = atoi (opt_ptr);
if (!strcmp((sep + 1), "last"))
end = MAX_IMAGES;
else
end = atoi (sep + 1);
for (j = start; j <= end && j - start + i < MAX_IMAGES; j++)
imagelist[i++] = j;
}
}
}
}
}
*image_count = i;
break;
case 'O':  
switch (tolower((int) optarg[0]))
{
case  'a': page->orient = ORIENTATION_AUTO;
break;
case  'p': page->orient = ORIENTATION_PORTRAIT;
break;
case  'l': page->orient = ORIENTATION_LANDSCAPE;
break;
default:  TIFFError ("Orientation must be portrait, landscape, or auto.", "%s", optarg);
TIFFError ("For valid options type", "tiffcrop -h");
exit (EXIT_FAILURE);
}
break;
case 'P':  
if (sscanf(optarg, "%lfx%lf", &page->width, &page->length) == 2)
{
strcpy (page->name, "Custom"); 
page->mode |= PAGE_MODE_PAPERSIZE;
break;
}
if (get_page_geometry (optarg, page))
{
if (!strcmp(optarg, "list"))
{
TIFFError("", "Name            Width   Length (in inches)");
for (i = 0; i < MAX_PAPERNAMES - 1; i++)
TIFFError ("", "%-15.15s %5.2f   %5.2f", 
PaperTable[i].name, PaperTable[i].width, 
PaperTable[i].length);
exit (EXIT_FAILURE);
}
TIFFError ("Invalid paper size", "%s", optarg);
TIFFError ("", "Select one of:");
TIFFError("", "Name            Width   Length (in inches)");
for (i = 0; i < MAX_PAPERNAMES - 1; i++)
TIFFError ("", "%-15.15s %5.2f   %5.2f", 
PaperTable[i].name, PaperTable[i].width, 
PaperTable[i].length);
exit (EXIT_FAILURE);
}
else
{
page->mode |= PAGE_MODE_PAPERSIZE;
}
break;
case 'R': 
crop_data->crop_mode |= CROP_ROTATE;
switch (strtoul(optarg, NULL, 0))
{
case  90:  crop_data->rotation = (uint16_t)90;
break;
case  180: crop_data->rotation = (uint16_t)180;
break;
case  270: crop_data->rotation = (uint16_t)270;
break;
default:   TIFFError ("Rotation must be 90, 180, or 270 degrees clockwise", "%s", optarg);
TIFFError ("For valid options type", "tiffcrop -h");
exit (EXIT_FAILURE);
}
break;
case 'S':
sep = strpbrk(optarg, ",:");
if (sep)
{
*sep = '\0';
page->cols = atoi(optarg);
page->rows = atoi(sep +1);
}
else
{
page->cols = atoi(optarg);
page->rows = atoi(optarg);
}
if ((page->cols * page->rows) > MAX_SECTIONS)
{
TIFFError ("Limit for subdivisions, ie rows x columns, exceeded", "%d", MAX_SECTIONS);
exit (EXIT_FAILURE);
}
page->mode |= PAGE_MODE_ROWSCOLS;
break;
case 'U':
if (streq(optarg, "in"))
{
crop_data->res_unit = RESUNIT_INCH;
page->res_unit = RESUNIT_INCH;
}
else if (streq(optarg, "cm"))
{
crop_data->res_unit = RESUNIT_CENTIMETER;
page->res_unit = RESUNIT_CENTIMETER;
}
else if (streq(optarg, "px"))
{
crop_data->res_unit = RESUNIT_NONE;
page->res_unit = RESUNIT_NONE;
}
else
{
TIFFError ("Illegal unit of measure","%s", optarg);
TIFFError ("For valid options type", "tiffcrop -h");
exit (EXIT_FAILURE);
}
break;
case 'V': 
page->vres = atof (optarg);
page->mode |= PAGE_MODE_RESOLUTION;
break;
case 'X':
crop_data->crop_mode |= CROP_WIDTH;
crop_data->width = atof(optarg);
break;
case 'Y':
crop_data->crop_mode |= CROP_LENGTH;
crop_data->length = atof(optarg);
break;
case 'Z': 
crop_data->crop_mode |= CROP_ZONES;
for (i = 0, opt_ptr = strtok (optarg, ",");
((opt_ptr != NULL) &&  (i < MAX_REGIONS));
(opt_ptr = strtok (NULL, ",")), i++)
{
crop_data->zones++;
opt_offset = strchr(opt_ptr, ':');
if (!opt_offset) {
TIFFError("Wrong parameter syntax for -Z", "tiffcrop -h");
exit(EXIT_FAILURE);
}
*opt_offset = '\0';
crop_data->zonelist[i].position = atoi(opt_ptr);
crop_data->zonelist[i].total    = atoi(opt_offset + 1);
}
if ((opt_ptr != NULL) && (i >= MAX_REGIONS))
{
TIFFError("Zone list exceeds region limit", "%d",  MAX_REGIONS);
exit (EXIT_FAILURE);
}
break;
case '?':TIFFError ("For valid options type", "tiffcrop -h");
exit (EXIT_FAILURE);
}
}
char XY, Z, R, S;
XY = ((crop_data->crop_mode & CROP_WIDTH) || (crop_data->crop_mode & CROP_LENGTH)) ? 1 : 0;
Z = (crop_data->crop_mode & CROP_ZONES) ? 1 : 0;
R = (crop_data->crop_mode & CROP_REGIONS) ? 1 : 0;
S = (page->mode & PAGE_MODE_ROWSCOLS) ? 1 : 0;
if (XY + Z + R + S > 1) {
TIFFError("tiffcrop input error", "The crop options(-X|-Y), -Z, -z and -S are mutually exclusive.->Exit");
exit(EXIT_FAILURE);
}
}

void
QPDF::initializeEncryption()
{
if (this->m->encryption_initialized)
{
return;
}
this->m->encryption_initialized = true;
if (! this->m->trailer.hasKey("/Encrypt"))
{
return;
}
this->m->encrypted = true;
std::string id1;
QPDFObjectHandle id_obj = this->m->trailer.getKey("/ID");
if ((id_obj.isArray() &&
(id_obj.getArrayNItems() == 2) &&
id_obj.getArrayItem(0).isString()))
{
id1 = id_obj.getArrayItem(0).getStringValue();
}
else
{
warn(QPDFExc(qpdf_e_damaged_pdf, this->m->file->getName(),
"trailer", this->m->file->getLastOffset(),
"invalid /ID in trailer dictionary"));
}
QPDFObjectHandle encryption_dict = this->m->trailer.getKey("/Encrypt");
if (! encryption_dict.isDictionary())
{
throw QPDFExc(qpdf_e_damaged_pdf, this->m->file->getName(),
this->m->last_object_description,
this->m->file->getLastOffset(),
"/Encrypt in trailer dictionary is not a dictionary");
}
if (! (encryption_dict.getKey("/Filter").isName() &&
(encryption_dict.getKey("/Filter").getName() == "/Standard")))
{
throw QPDFExc(qpdf_e_damaged_pdf, this->m->file->getName(),
"encryption dictionary", this->m->file->getLastOffset(),
"unsupported encryption filter");
}
if (! encryption_dict.getKey("/SubFilter").isNull())
{
warn(QPDFExc(qpdf_e_unsupported, this->m->file->getName(),
"encryption dictionary", this->m->file->getLastOffset(),
"file uses encryption SubFilters,"
" which qpdf does not support"));
}
if (! (encryption_dict.getKey("/V").isInteger() &&
encryption_dict.getKey("/R").isInteger() &&
encryption_dict.getKey("/O").isString() &&
encryption_dict.getKey("/U").isString() &&
encryption_dict.getKey("/P").isInteger()))
{
throw QPDFExc(qpdf_e_damaged_pdf, this->m->file->getName(),
"encryption dictionary", this->m->file->getLastOffset(),
"some encryption dictionary parameters are missing "
"or the wrong type");
}
int V = encryption_dict.getKey("/V").getIntValue();
int R = encryption_dict.getKey("/R").getIntValue();
std::string O = encryption_dict.getKey("/O").getStringValue();
std::string U = encryption_dict.getKey("/U").getStringValue();
unsigned int P = encryption_dict.getKey("/P").getIntValue();
if (! (((R >= 2) && (R <= 6)) &&
((V == 1) || (V == 2) || (V == 4) || (V == 5))))
{
throw QPDFExc(qpdf_e_unsupported, this->m->file->getName(),
"encryption dictionary", this->m->file->getLastOffset(),
"Unsupported /R or /V in encryption dictionary; R = " +
QUtil::int_to_string(R) + " (max 6), V = " +
QUtil::int_to_string(V) + " (max 5)");
}
this->m->encryption_V = V;
this->m->encryption_R = R;
std::string OE;
std::string UE;
std::string Perms;
if (V < 5)
{
pad_short_parameter(O, key_bytes);
pad_short_parameter(U, key_bytes);
if (! ((O.length() == key_bytes) && (U.length() == key_bytes)))
{
throw QPDFExc(qpdf_e_damaged_pdf, this->m->file->getName(),
"encryption dictionary",
this->m->file->getLastOffset(),
"incorrect length for /O and/or /U in "
"encryption dictionary");
}
}
else
{
if (! (encryption_dict.getKey("/OE").isString() &&
encryption_dict.getKey("/UE").isString() &&
encryption_dict.getKey("/Perms").isString()))
{
throw QPDFExc(qpdf_e_damaged_pdf, this->m->file->getName(),
"encryption dictionary",
this->m->file->getLastOffset(),
"some V=5 encryption dictionary parameters are "
"missing or the wrong type");
}
OE = encryption_dict.getKey("/OE").getStringValue();
UE = encryption_dict.getKey("/UE").getStringValue();
Perms = encryption_dict.getKey("/Perms").getStringValue();
pad_short_parameter(O, OU_key_bytes_V5);
pad_short_parameter(U, OU_key_bytes_V5);
pad_short_parameter(OE, OUE_key_bytes_V5);
pad_short_parameter(UE, OUE_key_bytes_V5);
pad_short_parameter(Perms, Perms_key_bytes_V5);
if ((O.length() < OU_key_bytes_V5) ||
(U.length() < OU_key_bytes_V5) ||
(OE.length() < OUE_key_bytes_V5) ||
(UE.length() < OUE_key_bytes_V5) ||
(Perms.length() < Perms_key_bytes_V5))
{
throw QPDFExc(qpdf_e_damaged_pdf, this->m->file->getName(),
"encryption dictionary",
this->m->file->getLastOffset(),
"incorrect length for some of"
" /O, /U, /OE, /UE, or /Perms in"
" encryption dictionary");
}
}
int Length = 40;
if (encryption_dict.getKey("/Length").isInteger())
{
Length = encryption_dict.getKey("/Length").getIntValue();
if ((Length % 8) || (Length < 40) || (Length > 256))
{
throw QPDFExc(qpdf_e_damaged_pdf, this->m->file->getName(),
"encryption dictionary",
this->m->file->getLastOffset(),
"invalid /Length value in encryption dictionary");
}
}
this->m->encrypt_metadata = true;
if ((V >= 4) && (encryption_dict.getKey("/EncryptMetadata").isBool()))
{
this->m->encrypt_metadata =
encryption_dict.getKey("/EncryptMetadata").getBoolValue();
}
if ((V == 4) || (V == 5))
{
QPDFObjectHandle CF = encryption_dict.getKey("/CF");
std::set<std::string> keys = CF.getKeys();
for (std::set<std::string>::iterator iter = keys.begin();
iter != keys.end(); ++iter)
{
std::string const& filter = *iter;
QPDFObjectHandle cdict = CF.getKey(filter);
if (cdict.isDictionary())
{
encryption_method_e method = e_none;
if (cdict.getKey("/CFM").isName())
{
std::string method_name = cdict.getKey("/CFM").getName();
if (method_name == "/V2")
{
QTC::TC("qpdf", "QPDF_encryption CFM V2");
method = e_rc4;
}
else if (method_name == "/AESV2")
{
QTC::TC("qpdf", "QPDF_encryption CFM AESV2");
method = e_aes;
}
else if (method_name == "/AESV3")
{
QTC::TC("qpdf", "QPDF_encryption CFM AESV3");
method = e_aesv3;
}
else
{
method = e_unknown;
}
}
this->m->crypt_filters[filter] = method;
}
}
QPDFObjectHandle StmF = encryption_dict.getKey("/StmF");
QPDFObjectHandle StrF = encryption_dict.getKey("/StrF");
QPDFObjectHandle EFF = encryption_dict.getKey("/EFF");
this->m->cf_stream = interpretCF(StmF);
this->m->cf_string = interpretCF(StrF);
if (EFF.isName())
{
this->m->cf_file = interpretCF(EFF);
}
else
{
this->m->cf_file = this->m->cf_stream;
}
}
EncryptionData data(V, R, Length / 8, P, O, U, OE, UE, Perms,
id1, this->m->encrypt_metadata);
if (check_owner_password(
this->m->user_password, this->m->provided_password, data))
{
}
else if (check_user_password(this->m->provided_password, data))
{
this->m->user_password = this->m->provided_password;
}
else
{
throw QPDFExc(qpdf_e_password, this->m->file->getName(),
"", 0, "invalid password");
}
if (V < 5)
{
this->m->encryption_key = compute_encryption_key(
this->m->user_password, data);
}
else
{
bool perms_valid;
this->m->encryption_key = recover_encryption_key_with_password(
this->m->provided_password, data, perms_valid);
if (! perms_valid)
{
warn(QPDFExc(qpdf_e_damaged_pdf, this->m->file->getName(),
"encryption dictionary",
this->m->file->getLastOffset(),
"/Perms field in encryption dictionary"
" doesn't match expected value"));
}
}
}

tport_t *tport_tsend(tport_t *self,
msg_t *msg,
tp_name_t const *_tpn,
tag_type_t tag, tag_value_t value, ...)
{
ta_list ta;
tagi_t const *t;
int reuse, sdwn_after, close_after, resolved = 0, fresh;
unsigned mtu;
su_addrinfo_t *ai;
tport_primary_t *primary;
tp_name_t tpn[1];
struct sigcomp_compartment *cc;
assert(self);
if (!self || !msg || !_tpn) {
msg_set_errno(msg, EINVAL);
return NULL;
}
*tpn = *_tpn;
SU_DEBUG_7(("tport_tsend(%p) tpn = " TPN_FORMAT "\n",
(void *)self, TPN_ARGS(tpn)));
if (tport_is_master(self)) {
primary = (tport_primary_t *)tport_primary_by_name(self, tpn);
if (!primary) {
msg_set_errno(msg, EPROTONOSUPPORT);
return NULL;
}
}
else {
primary = self->tp_pri;
}
ta_start(ta, tag, value);
reuse = primary->pri_primary->tp_reusable && self->tp_reusable;
fresh = 0;
sdwn_after = 0;
close_after = 0;
mtu = 0;
cc = NULL;
for (t = ta_args(ta); t; t = tl_next(t)) {
tag_type_t tt = t->t_tag;
if (tptag_reuse == tt)
reuse = t->t_value != 0;
else if (tptag_mtu == tt)
mtu = t->t_value;
else if (tptag_sdwn_after == tt)
sdwn_after = t->t_value != 0;
else if (tptag_close_after == tt)
close_after = t->t_value != 0;
else if (tptag_fresh == tt)
fresh = t->t_value != 0;
else if (tptag_compartment == tt)
cc = (struct sigcomp_compartment *)t->t_value;
}
ta_end(ta);
fresh = fresh || !reuse;
ai = msg_addrinfo(msg);
ai->ai_flags = 0;
tpn->tpn_comp = tport_canonize_comp(tpn->tpn_comp);
if (tpn->tpn_comp) {
ai->ai_flags |= TP_AI_COMPRESSED;
SU_DEBUG_9(("%s: compressed msg(%p) with %s\n",
__func__, (void *)msg, tpn->tpn_comp));
}
if (!tpn->tpn_comp || cc == NONE)
cc = NULL;
if (sdwn_after)
ai->ai_flags |= TP_AI_SHUTDOWN;
if (close_after)
ai->ai_flags |= TP_AI_CLOSE;
if (fresh) {
self = primary->pri_primary;
}
else if (tport_is_secondary(self) && tport_is_clear_to_send(self)) {
;
}
else {
if (tport_resolve(primary->pri_primary, msg, tpn) < 0) {
return NULL;
}
resolved = 1;
tport_t* secondary = NULL ;
tport_t* tp = tport_primaries( self ) ;
if (tp) {
do {
secondary = tport_by_addrinfo((tport_primary_t *)tp, msg_addrinfo(msg), tpn);
if (secondary) break;
} while(NULL != (tp = tport_next(tp)));
}
if( secondary ) {
self = secondary ;
}
else {
self = primary->pri_primary;      
}
}
if (tport_is_primary(self)) {
if (!resolved && tport_resolve(self, msg, tpn) < 0) {
return NULL;
}
if (tport_is_connection_oriented(self)
|| self->tp_params->tpp_conn_orient) {
#if 0 && HAVE_UPNP 
if (upnp_register_upnp_client(1) != 0) {
upnp_check_for_nat();
}
#endif
tpn->tpn_proto = self->tp_protoname;
if (!cc)
tpn->tpn_comp = NULL;
