uint32_t result = 0;
TType keyType;
TType valType;
uint32_t i, size;
bool sizeUnknown;
result += prot.readMapBegin(keyType, valType, size, sizeUnknown);
if (!sizeUnknown) {
for (i = 0; i < size; i++) {
result += skip(prot, keyType);
result += skip(prot, valType);
}
} else {
while (prot.peekMap()) {
result += skip(prot, keyType);
result += skip(prot, valType);
}
}
result += prot.readMapEnd();
return result;
}
case T_SET: {
uint32_t result = 0;
TType elemType;
uint32_t i, size;
bool sizeUnknown;
result += prot.readSetBegin(elemType, size, sizeUnknown);
if (!sizeUnknown) {
for (i = 0; i < size; i++) {
result += skip(prot, elemType);
}
} else {
while (prot.peekSet()) {
result += skip(prot, elemType);
}
}
result += prot.readSetEnd();
return result;
}
case T_LIST: {
uint32_t result = 0;
TType elemType;
