last = last->next;
ws_pending = is_email_wsp (*s);
if ((nl = mutt_strlen (s)))
nl = s[nl - 1] == '\n';
s = skip_email_wsp(s);
#ifdef EXACT_ADDRESS
begin = s;
#endif
while (*s)
{
if (*s == ',')
{
if (phraselen)
{
terminate_buffer (phrase, phraselen);
add_addrspec (&top, &last, phrase, comment, &commentlen, sizeof (comment) - 1);
}
else if (commentlen && last && !last->personal)
{
terminate_buffer (comment, commentlen);
last->personal = safe_strdup (comment);
}
#ifdef EXACT_ADDRESS
if (last && !last->val)
last->val = mutt_substrdup (begin, s);
#endif
commentlen = 0;
phraselen = 0;
s++;
#ifdef EXACT_ADDRESS
begin = skip_email_wsp(s);
#endif
}
else if (*s == '(')
{
if (commentlen && commentlen < sizeof (comment) - 1)
comment[commentlen++] = ' ';
if ((ps = next_token (s, comment, &commentlen, sizeof (comment) - 1)) == NULL)
{
rfc822_free_address (&top);
return NULL;
}
s = ps;
}
else if (*s == '"')
{
if (phraselen && phraselen < sizeof (phrase) - 1)
phrase[phraselen++] = ' ';
if ((ps = parse_quote (s + 1, phrase, &phraselen, sizeof (phrase) - 1)) == NULL)
{
rfc822_free_address (&top);
return NULL;
}
s = ps;
}
else if (*s == '[')
{
if (phraselen && phraselen < sizeof (phrase) - 1 && ws_pending)
phrase[phraselen++] = ' ';
if (phraselen < sizeof (phrase) - 1)
phrase[phraselen++] = '[';
if ((ps = parse_literal (s + 1, phrase, &phraselen, sizeof (phrase) - 1)) == NULL)
{
rfc822_free_address (&top);
return NULL;
}
s = ps;
}
else if (*s == ':')
{
cur = rfc822_new_address ();
terminate_buffer (phrase, phraselen);
cur->mailbox = safe_strdup (phrase);
cur->group = 1;
in_group = 1;
if (last)
last->next = cur;
else
top = cur;
last = cur;
#ifdef EXACT_ADDRESS
last->val = mutt_substrdup (begin, s);
#endif
phraselen = 0;
commentlen = 0;
s++;
#ifdef EXACT_ADDRESS
begin = skip_email_wsp(s);
#endif
}
else if (*s == ';')
{
if (phraselen)
{
terminate_buffer (phrase, phraselen);
add_addrspec (&top, &last, phrase, comment, &commentlen, sizeof (comment) - 1);
}
else if (commentlen && last && !last->personal)
{
terminate_buffer (comment, commentlen);
last->personal = safe_strdup (comment);
}
#ifdef EXACT_ADDRESS
if (last && !last->val)
last->val = mutt_substrdup (begin, s);
#endif
if (last && in_group)
{
last->next = rfc822_new_address ();
last = last->next;
}
in_group = 0;
phraselen = 0;
commentlen = 0;
#ifdef EXACT_ADDRESS
begin = s;
#endif
s++;
}
else if (*s == '<')
{
terminate_buffer (phrase, phraselen);
cur = rfc822_new_address ();
if (phraselen)
cur->personal = safe_strdup (phrase);
if ((ps = parse_route_addr (s + 1, comment, &commentlen, sizeof (comment) - 1, cur)) == NULL)
{
rfc822_free_address (&top);
rfc822_free_address (&cur);
return NULL;
}
if (last)
last->next = cur;
else
top = cur;
last = cur;
phraselen = 0;
commentlen = 0;
s = ps;
}
else
{
if (phraselen && phraselen < sizeof (phrase) - 1 && ws_pending)
phrase[phraselen++] = ' ';
if ((ps = next_token (s, phrase, &phraselen, sizeof (phrase) - 1)) == NULL)
{
rfc822_free_address (&top);
return NULL;
}
s = ps;
}
ws_pending = is_email_wsp(*s);
s = skip_email_wsp(s);
}
if (phraselen)
{
terminate_buffer (phrase, phraselen);
terminate_buffer (comment, commentlen);
add_addrspec (&top, &last, phrase, comment, &commentlen, sizeof (comment) - 1);
}
else if (commentlen && last && !last->personal)
{
terminate_buffer (comment, commentlen);
last->personal = safe_strdup (comment);
}
#ifdef EXACT_ADDRESS
if (last && !last->val)
last->val = mutt_substrdup (begin, s - nl < begin ? begin : s - nl);
#endif
return top;
}

static MagickBooleanType ProcessMSLScript(const ImageInfo *image_info,
Image **image,ExceptionInfo *exception)
{
char
message[MaxTextExtent];
Image
*msl_image;
int
status;
ssize_t
n;
MSLInfo
msl_info;
xmlSAXHandler
sax_modules;
xmlSAXHandlerPtr
sax_handler;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickCoreSignature);
if (image_info->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
image_info->filename);
assert(image != (Image **) NULL);
msl_image=AcquireImage(image_info);
status=OpenBlob(image_info,msl_image,ReadBinaryBlobMode,exception);
if (status == MagickFalse)
{
ThrowFileException(exception,FileOpenError,"UnableToOpenFile",
msl_image->filename);
msl_image=DestroyImageList(msl_image);
return(MagickFalse);
}
msl_image->columns=1;
msl_image->rows=1;
(void) ResetMagickMemory(&msl_info,0,sizeof(msl_info));
msl_info.exception=exception;
msl_info.image_info=(ImageInfo **) AcquireMagickMemory(
sizeof(*msl_info.image_info));
msl_info.draw_info=(DrawInfo **) AcquireMagickMemory(
sizeof(*msl_info.draw_info));
msl_info.image=(Image **) AcquireMagickMemory(sizeof(*msl_info.image));
msl_info.attributes=(Image **) AcquireMagickMemory(
sizeof(*msl_info.attributes));
msl_info.group_info=(MSLGroupInfo *) AcquireMagickMemory(
sizeof(*msl_info.group_info));
if ((msl_info.image_info == (ImageInfo **) NULL) ||
(msl_info.image == (Image **) NULL) ||
(msl_info.attributes == (Image **) NULL) ||
(msl_info.group_info == (MSLGroupInfo *) NULL))
ThrowFatalException(ResourceLimitFatalError,"UnableToInterpretMSLImage");
*msl_info.image_info=CloneImageInfo(image_info);
*msl_info.draw_info=CloneDrawInfo(image_info,(DrawInfo *) NULL);
*msl_info.attributes=AcquireImage(image_info);
msl_info.group_info[0].numImages=0;
*msl_info.image=msl_image;
if (*image != (Image *) NULL)
MSLPushImage(&msl_info,*image);
(void) xmlSubstituteEntitiesDefault(1);
(void) ResetMagickMemory(&sax_modules,0,sizeof(sax_modules));
sax_modules.internalSubset=MSLInternalSubset;
sax_modules.isStandalone=MSLIsStandalone;
sax_modules.hasInternalSubset=MSLHasInternalSubset;
sax_modules.hasExternalSubset=MSLHasExternalSubset;
sax_modules.resolveEntity=MSLResolveEntity;
sax_modules.getEntity=MSLGetEntity;
sax_modules.entityDecl=MSLEntityDeclaration;
sax_modules.notationDecl=MSLNotationDeclaration;
sax_modules.attributeDecl=MSLAttributeDeclaration;
sax_modules.elementDecl=MSLElementDeclaration;
sax_modules.unparsedEntityDecl=MSLUnparsedEntityDeclaration;
sax_modules.setDocumentLocator=MSLSetDocumentLocator;
sax_modules.startDocument=MSLStartDocument;
sax_modules.endDocument=MSLEndDocument;
sax_modules.startElement=MSLStartElement;
sax_modules.endElement=MSLEndElement;
sax_modules.reference=MSLReference;
sax_modules.characters=MSLCharacters;
sax_modules.ignorableWhitespace=MSLIgnorableWhitespace;
sax_modules.processingInstruction=MSLProcessingInstructions;
sax_modules.comment=MSLComment;
sax_modules.warning=MSLWarning;
sax_modules.error=MSLError;
sax_modules.fatalError=MSLError;
sax_modules.getParameterEntity=MSLGetParameterEntity;
sax_modules.cdataBlock=MSLCDataBlock;
sax_modules.externalSubset=MSLExternalSubset;
sax_handler=(&sax_modules);
msl_info.parser=xmlCreatePushParserCtxt(sax_handler,&msl_info,(char *) NULL,0,
msl_image->filename);
while (ReadBlobString(msl_image,message) != (char *) NULL)
{
n=(ssize_t) strlen(message);
if (n == 0)
continue;
status=xmlParseChunk(msl_info.parser,message,(int) n,MagickFalse);
if (status != 0)
break;
(void) xmlParseChunk(msl_info.parser," ",1,MagickFalse);
if (msl_info.exception->severity >= ErrorException)
break;
}
if (msl_info.exception->severity == UndefinedException)
(void) xmlParseChunk(msl_info.parser," ",1,MagickTrue);
xmlFreeParserCtxt(msl_info.parser);
(void) LogMagickEvent(CoderEvent,GetMagickModule(),"end SAX");
msl_info.group_info=(MSLGroupInfo *) RelinquishMagickMemory(
msl_info.group_info);
if (*image == (Image *) NULL)
*image=(*msl_info.image);
*msl_info.image_info=DestroyImageInfo(*msl_info.image_info);
msl_info.image_info=(ImageInfo **) RelinquishMagickMemory(
msl_info.image_info);
*msl_info.draw_info=DestroyDrawInfo(*msl_info.draw_info);
msl_info.draw_info=(DrawInfo **) RelinquishMagickMemory(msl_info.draw_info);
msl_info.image=(Image **) RelinquishMagickMemory(msl_info.image);
*msl_info.attributes=DestroyImage(*msl_info.attributes);
msl_info.attributes=(Image **) RelinquishMagickMemory(msl_info.attributes);
msl_info.group_info=(MSLGroupInfo *) RelinquishMagickMemory(
msl_info.group_info);
if ((*msl_info.image)->exception.severity != UndefinedException)
return(MagickFalse);
return(MagickTrue);
}

static PyArray_Descr *
_convert_from_str(PyObject *obj, int align)
{
Py_ssize_t len = 0;
char const *type = PyUnicode_AsUTF8AndSize(obj, &len);
if (type == NULL) {
return NULL;
}
if (len == 0) {
goto fail;
}
if (_check_for_commastring(type, len)) {
return _convert_from_commastring(obj, align);
}
char endian = '=';
switch (type[0]) {
case '>':
case '<':
case '=':
endian = type[0];
++type;
--len;
break;
case '|':
endian = '=';
++type;
--len;
break;
}
if (len == 0) {
goto fail;
}
if (is_datetime_typestr(type, len)) {
PyArray_Descr *ret = parse_dtype_from_datetime_typestr(type, len);
if (ret == NULL) {
return NULL;
}
if (!PyArray_ISNBO(endian)) {
ret->byteorder = endian;
}
return ret;
}
int check_num = NPY_NOTYPE + 10;
int elsize = 0;
if (len == 1) {
check_num = (unsigned char) type[0];
}
else {
char *typeend = NULL;
int kind;
elsize = (int)strtol(type + 1, &typeend, 10);
if (typeend - type == len) {
kind = type[0];
switch (kind) {
case NPY_STRINGLTR:
case NPY_STRINGLTR2:
check_num = NPY_STRING;
break;
case NPY_UNICODELTR:
check_num = NPY_UNICODE;
elsize <<= 2;
break;
case NPY_VOIDLTR:
check_num = NPY_VOID;
break;
default:
if (elsize == 0) {
check_num = NPY_NOTYPE+10;
}
else {
check_num = PyArray_TypestrConvert(elsize, kind);
if (check_num == NPY_NOTYPE) {
check_num += 10;
}
elsize = 0;
}
}
}
}
if (PyErr_Occurred()) {
goto fail;
}
PyArray_Descr *ret;
if ((check_num == NPY_NOTYPE + 10) ||
(ret = PyArray_DescrFromType(check_num)) == NULL) {
PyErr_Clear();
if (typeDict == NULL) {
goto fail;
}
PyObject *item = PyDict_GetItemWithError(typeDict, obj);
if (item == NULL) {
if (PyErr_Occurred()) {
return NULL;
}
goto fail;
}
char *dep_tps[] = {"Bytes", "Datetime64", "Str", "Uint"};
int ndep_tps = sizeof(dep_tps) / sizeof(dep_tps[0]);
for (int i = 0; i < ndep_tps; ++i) {
char *dep_tp = dep_tps[i];
if (strncmp(type, dep_tp, strlen(dep_tp)) == 0) {
if (DEPRECATE("Numeric-style type codes are "
"deprecated and will result in "
"an error in the future.") < 0) {
goto fail;
}
}
}
return _convert_from_any(item, align);
}
if (PyDataType_ISUNSIZED(ret) && ret->elsize != elsize) {
PyArray_DESCR_REPLACE(ret);
if (ret == NULL) {
return NULL;
}
ret->elsize = elsize;
}
if (endian != '=' && PyArray_ISNBO(endian)) {
endian = '=';
}
if (endian != '=' && ret->byteorder != '|' && ret->byteorder != endian) {
PyArray_DESCR_REPLACE(ret);
if (ret == NULL) {
return NULL;
}
ret->byteorder = endian;
}
return ret;
fail:
PyErr_Format(PyExc_TypeError, "data type %R not understood", obj);
return NULL;
}

