static void mctp_unregister(struct net_device *dev)
{
struct mctp_dev *mdev;
mdev = mctp_dev_get_rtnl(dev);
if (mdev && !mctp_known(dev)) {
netdev_warn(dev, "%s: BUG mctp_ptr set for unknown type %d",
__func__, dev->type);
return;
}
if (!mdev)
return;
RCU_INIT_POINTER(mdev->dev->mctp_ptr, NULL);
mctp_route_remove_dev(mdev);
mctp_neigh_remove_dev(mdev);
kfree(mdev->addrs);
mctp_dev_put(mdev);
}

static void
parse_paragraph(tree_t *t,
float  left,
float  right,
float  bottom,
float  top,
float  *x,
float  *y,
int    *page,
int    needspace)
{
intwhitespace;
tree_t*flat,
*start,
*end,
*prev,
*temp;
floatwidth,
height,
offset,
spacing,
borderspace,
temp_y,
temp_width,
temp_height;
floatformat_width, image_y, image_left, image_right;
intimage_page = *page;
floatchar_spacing;
intnum_chars;
render_t*r;
uchar*align,
*hspace,
*vspace,
*link,
*border;
floatrgb[3];
ucharline[10240],
*lineptr,
*dataptr;
tree_t*linetype;
floatlinex,
linewidth;
intfirstline;
DEBUG_printf(("parse_paragraph(t=%p, left=%.1f, right=%.1f, bottom=%.1f, top=%.1f, x=%.1f, y=%.1f, page=%d, needspace=%d\n",
(void *)t, left, right, bottom, top, *x, *y, *page, needspace));
flat        = flatten_tree(t->child);
image_left  = left;
image_right = right;
image_y     = 0;
if (flat == NULL)
DEBUG_puts("parse_paragraph: flat == NULL!");
if (*y < top && needspace)
*y -= _htmlSpacings[SIZE_P];
for (temp = flat, prev = NULL; temp != NULL;)
{
if (temp->markup == MARKUP_IMG)
update_image_size(temp);
if (temp->markup == MARKUP_IMG &&
(align = htmlGetVariable(temp, (uchar *)"ALIGN")))
{
if ((border = htmlGetVariable(temp, (uchar *)"BORDER")) != NULL)
borderspace = (float)atof((char *)border);
else if (temp->link)
borderspace = 1;
else
borderspace = 0;
borderspace *= PagePrintWidth / _htmlBrowserWidth;
if (strcasecmp((char *)align, "LEFT") == 0)
{
if ((vspace = htmlGetVariable(temp, (uchar *)"VSPACE")) != NULL)
*y -= atoi((char *)vspace);
if (*y < (bottom + temp->height + 2 * borderspace))
{
(*page) ++;
*y = top;
if (Verbosity)
progress_show("Formatting page %d", *page);
}
if (borderspace > 0.0f)
{
if (temp->link && PSLevel == 0)
memcpy(rgb, link_color, sizeof(rgb));
else
{
rgb[0] = temp->red / 255.0f;
rgb[1] = temp->green / 255.0f;
rgb[2] = temp->blue / 255.0f;
}
new_render(*page, RENDER_BOX, image_left, *y - borderspace,
temp->width + 2 * borderspace, borderspace, rgb);
new_render(*page, RENDER_BOX, image_left,
*y - temp->height - 2 * borderspace,
borderspace, temp->height + 2 * borderspace, rgb);
new_render(*page, RENDER_BOX, image_left + temp->width + borderspace,
*y - temp->height - 2 * borderspace,
borderspace, temp->height + 2 * borderspace, rgb);
new_render(*page, RENDER_BOX, image_left,
*y - temp->height - 2 * borderspace,
temp->width + 2 * borderspace, borderspace, rgb);
}
*y -= borderspace;
new_render(*page, RENDER_IMAGE, image_left + borderspace,
*y - temp->height, temp->width, temp->height,
image_find((char *)htmlGetVariable(temp, (uchar *)"REALSRC")));
if (temp->link &&
(link = htmlGetVariable(temp->link, (uchar *)"_HD_FULL_HREF")) != NULL)
{
new_render(*page, RENDER_LINK, image_left + borderspace, *y - temp->height, temp->width, temp->height, link);
}
*y -= borderspace;
if (vspace != NULL)
*y -= atoi((char *)vspace);
image_left += temp->width + 2 * borderspace;
temp_y     = *y - temp->height;
image_page = *page;
if (temp_y < image_y || image_y == 0)
image_y = temp_y;
if ((hspace = htmlGetVariable(temp, (uchar *)"HSPACE")) != NULL)
image_left += atoi((char *)hspace);
if (prev != NULL)
prev->next = temp->next;
else
flat = temp->next;
free(temp);
temp = prev;
}
else if (strcasecmp((char *)align, "RIGHT") == 0)
{
if ((vspace = htmlGetVariable(temp, (uchar *)"VSPACE")) != NULL)
*y -= atoi((char *)vspace);
if (*y < (bottom + temp->height + 2 * borderspace))
{
(*page) ++;
*y = top;
if (Verbosity)
progress_show("Formatting page %d", *page);
}
image_right -= temp->width + 2 * borderspace;
image_page = *page;
if (borderspace > 0.0f)
{
if (temp->link && PSLevel == 0)
memcpy(rgb, link_color, sizeof(rgb));
else
{
rgb[0] = temp->red / 255.0f;
rgb[1] = temp->green / 255.0f;
rgb[2] = temp->blue / 255.0f;
}
new_render(*page, RENDER_BOX, image_right, *y - borderspace,
temp->width + 2 * borderspace, borderspace, rgb);
new_render(*page, RENDER_BOX, image_right,
*y - temp->height - 2 * borderspace,
borderspace, temp->height + 2 * borderspace, rgb);
new_render(*page, RENDER_BOX, image_right + temp->width + borderspace,
*y - temp->height - 2 * borderspace,
borderspace, temp->height + 2 * borderspace, rgb);
new_render(*page, RENDER_BOX, image_right, *y - temp->height - 2 * borderspace,
temp->width + 2 * borderspace, borderspace, rgb);
}
*y -= borderspace;
new_render(*page, RENDER_IMAGE, image_right + borderspace,
*y - temp->height, temp->width, temp->height,
image_find((char *)htmlGetVariable(temp, (uchar *)"REALSRC")));
if (temp->link &&
(link = htmlGetVariable(temp->link, (uchar *)"_HD_FULL_HREF")) != NULL)
{
new_render(*page, RENDER_LINK, image_right + borderspace, *y - temp->height, temp->width, temp->height, link);
}
*y -= borderspace;
if (vspace != NULL)
*y -= atoi((char *)vspace);
temp_y = *y - temp->height;
if (temp_y < image_y || image_y == 0)
image_y = temp_y;
if ((hspace = htmlGetVariable(temp, (uchar *)"HSPACE")) != NULL)
image_right -= atoi((char *)hspace);
if (prev != NULL)
prev->next = temp->next;
else
flat = temp->next;
free(temp);
temp = prev;
}
}
if (temp != NULL)
{
prev = temp;
temp = temp->next;
}
else
temp = flat;
}
format_width = image_right - image_left;
firstline    = 1;
DEBUG_printf(("format_width = %.1f\n", format_width));
offset      = 0.0f;
temp_width  = 0.0f;
temp_height = 0.0f;
lineptr     = NULL;
linex       = 0.0f;
linewidth   = 0.0f;
while (flat != NULL)
{
start = flat;
end   = flat;
width = 0.0;
while (flat != NULL)
{
temp_width = 0.0;
temp       = flat;
whitespace = 0;
while (temp != NULL && !whitespace)
{
if (temp->markup == MARKUP_NONE && temp->data[0] == ' ')
{
if (temp == start)
temp_width -= _htmlWidths[temp->typeface][temp->style][' '] *
_htmlSizes[temp->size] * 0.001f;
else if (temp_width > 0.0f)
whitespace = 1;
}
else
whitespace = 0;
if (whitespace)
break;
if (temp->markup == MARKUP_IMG)
{
if ((border = htmlGetVariable(temp, (uchar *)"BORDER")) != NULL)
borderspace = (float)atof((char *)border);
else if (temp->link)
borderspace = 1;
else
borderspace = 0;
borderspace *= PagePrintWidth / _htmlBrowserWidth;
temp_width += 2 * borderspace;
}
prev       = temp;
temp       = temp->next;
temp_width += prev->width;
if ((temp_width >= format_width && prev->markup == MARKUP_IMG) ||
prev->markup == MARKUP_BR)
{
break;
}
else if (prev->markup == MARKUP_NONE)
{
intch = prev->data[strlen((char *)prev->data) - 1];
if (_htmlUTF8)
ch = _htmlUnicode[ch];
if (ch == 173)
break;
}
}
if ((width + temp_width) <= format_width)
{
width += temp_width;
end  = temp;
flat = temp;
if (prev->markup == MARKUP_BR)
break;
}
else if (width == 0.0)
{
width += temp_width;
end  = temp;
flat = temp;
break;
}
else
break;
}
if (start == end)
{
end   = start->next;
flat  = start->next;
width = start->width;
}
for (height = 0.0, num_chars = 0, temp = prev = start;
temp != end;
temp = temp->next)
{
prev = temp;
if (temp->markup == MARKUP_NONE)
num_chars += strlen((char *)temp->data);
if (temp->height > height)
height = temp->height;
}
for (spacing = 0.0, temp = prev = start;
temp != end;
temp = temp->next)
{
prev = temp;
if (temp->markup != MARKUP_IMG)
temp_height = (float)(temp->height * _htmlSpacings[0] / _htmlSizes[0]);
else
{
if ((border = htmlGetVariable(temp, (uchar *)"BORDER")) != NULL)
borderspace = (float)atof((char *)border);
else if (temp->link)
borderspace = 1;
else
borderspace = 0;
borderspace *= PagePrintWidth / _htmlBrowserWidth;
temp_height = temp->height + 2 * borderspace;
}
if (temp_height > spacing)
spacing = temp_height;
}
if (firstline && end != NULL && *y < (bottom + height + _htmlSpacings[t->size]))
{
(*page) ++;
*y = top;
if (Verbosity)
progress_show("Formatting page %d", *page);
}
firstline = 0;
if (height == 0.0f)
height = spacing;
for (temp = start; temp != end; temp = temp->next)
if (temp->markup != MARKUP_A)
break;
if (temp != NULL && temp->markup == MARKUP_NONE && temp->data[0] == ' ')
{
for (dataptr = temp->data; *dataptr; dataptr ++)
*dataptr = dataptr[1];
*dataptr = '\0';
temp_width = _htmlWidths[temp->typeface][temp->style][' '] * _htmlSizes[temp->size] * 0.001f;
temp->width -= temp_width;
num_chars --;
}
if (end != NULL)
temp = end->prev;
else
temp = NULL;
DEBUG_printf(("    BEFORE page=%d, y=%.1f, height=%.1f, spacing=%.1f, bottom=%.1f\n", *page, *y, height, spacing, bottom));
if (*y < (spacing + bottom))
{
(*page) ++;
*y = top;
if (Verbosity)
progress_show("Formatting page %d", *page);
}
*y -= height;
DEBUG_printf(("    page=%d, y=%.1f, width=%.1f, height=%.1f\n", *page, *y, width, height));
if (Verbosity)
progress_update(100 - (int)(100 * (*y) / PagePrintLength));
char_spacing = 0.0f;
whitespace   = 0;
temp         = start;
linetype     = NULL;
rgb[0] = temp->red / 255.0f;
rgb[1] = temp->green / 255.0f;
rgb[2] = temp->blue / 255.0f;
switch (t->halignment)
{
case ALIGN_LEFT :
linex = image_left;
break;
case ALIGN_CENTER :
linex = image_left + 0.5f * (format_width - width);
break;
case ALIGN_RIGHT :
linex = image_right - width;
break;
case ALIGN_JUSTIFY :
linex = image_left;
if (flat != NULL && flat->prev->markup != MARKUP_BR && num_chars > 1)
char_spacing = (format_width - width) / (num_chars - 1);
break;
}
while (temp != end)
{
if (temp->link != NULL && PSLevel == 0 && Links &&
temp->markup == MARKUP_NONE)
{
temp->red   = (uchar)(link_color[0] * 255.0);
temp->green = (uchar)(link_color[1] * 255.0);
temp->blue  = (uchar)(link_color[2] * 255.0);
}
if (linetype != NULL &&
(temp->markup != MARKUP_NONE ||
temp->typeface != linetype->typeface ||
temp->style != linetype->style ||
temp->size != linetype->size ||
temp->superscript != linetype->superscript ||
temp->subscript != linetype->subscript ||
temp->red != linetype->red ||
temp->green != linetype->green ||
temp->blue != linetype->blue))
{
r = new_render(*page, RENDER_TEXT, linex - linewidth, *y,
linewidth, linetype->height, line);
r->data.text.typeface = linetype->typeface;
r->data.text.style    = linetype->style;
r->data.text.size     = (float)_htmlSizes[linetype->size];
r->data.text.spacing  = char_spacing;
memcpy(r->data.text.rgb, rgb, sizeof(rgb));
if (linetype->superscript)
r->y += height - linetype->height;
else if (linetype->subscript)
r->y -= height - linetype->height;
free(linetype);
linetype = NULL;
}
if ((link = htmlGetVariable(temp, (uchar *)"ID")) != NULL)
{
add_link(link, *page, (int)(*y + height));
}
switch (temp->markup)
{
case MARKUP_A :
if ((link = htmlGetVariable(temp, (uchar *)"NAME")) != NULL)
{
add_link(link, *page, (int)(*y + height));
}
default :
temp_width = temp->width;
break;
case MARKUP_NONE :
if (temp->data == NULL)
break;
if (((temp->width - right + left) > 0.001 ||
(temp->height - top + bottom) > 0.001)  && OverflowErrors)
progress_error(HD_ERROR_CONTENT_TOO_LARGE,
"Text on page %d too large - "
"truncation or overlapping may occur!", *page + 1);
if (linetype == NULL)
{
linetype  = temp;
lineptr   = line;
linewidth = 0.0;
rgb[0] = temp->red / 255.0f;
rgb[1] = temp->green / 255.0f;
rgb[2] = temp->blue / 255.0f;
}
strlcpy((char *)lineptr, (char *)temp->data, sizeof(line) - (size_t)(lineptr - line));
temp_width = temp->width + char_spacing * strlen((char *)lineptr);
if (temp->underline || (temp->link && LinkStyle && PSLevel == 0))
new_render(*page, RENDER_BOX, linex, *y - 1, temp_width, 0, rgb);
if (temp->strikethrough)
new_render(*page, RENDER_BOX, linex, *y + temp->height * 0.25f,
temp_width, 0, rgb);
linewidth  += temp_width;
lineptr    += strlen((char *)lineptr);
if (lineptr > line && lineptr[-1] == ' ')
whitespace = 1;
else
whitespace = 0;
break;
case MARKUP_IMG :
if (((temp->width - right + left) > 0.001 ||
(temp->height - top + bottom) > 0.001) && OverflowErrors)
{
DEBUG_printf(("IMAGE: %.3fx%.3f > %.3fx%.3f\n",
temp->width, temp->height,
right - left, top - bottom));
progress_error(HD_ERROR_CONTENT_TOO_LARGE,
"Image on page %d too large - "
"truncation or overlapping may occur!", *page + 1);
}
if ((border = htmlGetVariable(temp, (uchar *)"BORDER")) != NULL)
borderspace = (float)atof((char *)border);
else if (temp->link)
borderspace = 1;
else
borderspace = 0;
borderspace *= PagePrintWidth / _htmlBrowserWidth;
temp_width += 2 * borderspace;
switch (temp->valignment)
{
case ALIGN_TOP :
offset = height - temp->height - 2 * borderspace;
break;
case ALIGN_MIDDLE :
offset = 0.5f * (height - temp->height) - borderspace;
break;
case ALIGN_BOTTOM :
offset = 0.0f;
}
if (borderspace > 0.0f)
{
new_render(*page, RENDER_BOX, linex,
*y + offset + temp->height + borderspace,
temp->width + 2 * borderspace, borderspace, rgb);
new_render(*page, RENDER_BOX, linex, *y + offset,
borderspace, temp->height + 2 * borderspace, rgb);
new_render(*page, RENDER_BOX, linex + temp->width + borderspace,
*y + offset, borderspace,
temp->height + 2 * borderspace, rgb);
new_render(*page, RENDER_BOX, linex, *y + offset,
temp->width + 2 * borderspace, borderspace, rgb);
}
new_render(*page, RENDER_IMAGE, linex + borderspace,
*y + offset + borderspace, temp->width, temp->height,
image_find((char *)htmlGetVariable(temp, (uchar *)"REALSRC")));
whitespace = 0;
temp_width = temp->width + 2 * borderspace;
break;
}
if (temp->link != NULL &&
(link = htmlGetVariable(temp->link, (uchar *)"_HD_FULL_HREF")) != NULL)
{
new_render(*page, RENDER_LINK, linex, *y + offset, temp->width, temp->height, link);
}
linex += temp_width;
prev = temp;
temp = temp->next;
if (prev != linetype)
free(prev);
}
if (linetype != NULL)
{
r = new_render(*page, RENDER_TEXT, linex - linewidth, *y,
linewidth, linetype->height, line);
r->data.text.typeface = linetype->typeface;
r->data.text.style    = linetype->style;
r->data.text.spacing  = char_spacing;
r->data.text.size     = (float)_htmlSizes[linetype->size];
memcpy(r->data.text.rgb, rgb, sizeof(rgb));
if (linetype->superscript)
r->y += height - linetype->height;
else if (linetype->subscript)
r->y -= height - linetype->height;
free(linetype);
}
*y -= spacing - height;
DEBUG_printf(("    AFTER y=%.1f, bottom=%.1f\n", *y, bottom));
if (*y < bottom)
{
(*page) ++;
*y = top;
if (Verbosity)
progress_show("Formatting page %d", *page);
}
if (*y < image_y || *page > image_page)
{
image_y      = 0.0f;
image_left   = left;
image_right  = right;
format_width = image_right - image_left;
}
}
*x = left;
if (*y > image_y && image_y > 0.0f && image_page == *page)
*y = image_y;
DEBUG_printf(("LEAVING parse_paragraph(), x = %.1f, y = %.1f, page = %d, image_y = %.1f\n", *x, *y, *page, image_y));
}

BIO *BIO_new_NDEF(BIO *out, ASN1_VALUE *val, const ASN1_ITEM *it)
{
NDEF_SUPPORT *ndef_aux = NULL;
BIO *asn_bio = NULL;
const ASN1_AUX *aux = it->funcs;
ASN1_STREAM_ARG sarg;
if (!aux || !aux->asn1_cb) {
ERR_raise(ERR_LIB_ASN1, ASN1_R_STREAMING_NOT_SUPPORTED);
return NULL;
}
ndef_aux = OPENSSL_zalloc(sizeof(*ndef_aux));
asn_bio = BIO_new(BIO_f_asn1());
if (ndef_aux == NULL || asn_bio == NULL)
goto err;
out = BIO_push(asn_bio, out);
if (out == NULL)
goto err;
BIO_asn1_set_prefix(asn_bio, ndef_prefix, ndef_prefix_free);
BIO_asn1_set_suffix(asn_bio, ndef_suffix, ndef_suffix_free);
sarg.out = out;
sarg.ndef_bio = NULL;
sarg.boundary = NULL;
if (aux->asn1_cb(ASN1_OP_STREAM_PRE, &val, it, &sarg) <= 0)
goto err;
ndef_aux->val = val;
ndef_aux->it = it;
ndef_aux->ndef_bio = sarg.ndef_bio;
ndef_aux->boundary = sarg.boundary;
ndef_aux->out = out;
BIO_ctrl(asn_bio, BIO_C_SET_EX_ARG, 0, ndef_aux);
return sarg.ndef_bio;
err:
BIO_free(asn_bio);
OPENSSL_free(ndef_aux);
return NULL;
}

bool HdrDecoder::checkSignature( const String& signature ) const
{
if(signature.size() >= m_signature.size() &&
(!memcmp(signature.c_str(), m_signature.c_str(), m_signature.size()) ||
!memcmp(signature.c_str(), m_signature_alt.c_str(), m_signature_alt.size())))
return true;
return false;
}

static krb5_error_code
get_matching_data(krb5_context context,
pkinit_plg_crypto_context plg_cryptoctx,
pkinit_req_crypto_context req_cryptoctx, X509 *cert,
pkinit_cert_matching_data **md_out)
{
krb5_error_code ret = ENOMEM;
pkinit_cert_matching_data *md = NULL;
krb5_principal *pkinit_sans = NULL, *upn_sans = NULL;
size_t i, j;
char buf[DN_BUF_LEN];
unsigned int bufsize = sizeof(buf);
*md_out = NULL;
md = calloc(1, sizeof(*md));
if (md == NULL)
goto cleanup;
X509_NAME_oneline_ex(X509_get_subject_name(cert), buf, &bufsize,
XN_FLAG_SEP_COMMA_PLUS);
md->subject_dn = strdup(buf);
if (md->subject_dn == NULL) {
ret = ENOMEM;
goto cleanup;
}
X509_NAME_oneline_ex(X509_get_issuer_name(cert), buf, &bufsize,
XN_FLAG_SEP_COMMA_PLUS);
md->issuer_dn = strdup(buf);
if (md->issuer_dn == NULL) {
ret = ENOMEM;
goto cleanup;
}
ret = crypto_retrieve_X509_sans(context, plg_cryptoctx, req_cryptoctx,
cert, &pkinit_sans, &upn_sans, NULL);
if (ret)
goto cleanup;
j = 0;
if (pkinit_sans != NULL) {
for (i = 0; pkinit_sans[i] != NULL; i++)
j++;
}
if (upn_sans != NULL) {
for (i = 0; upn_sans[i] != NULL; i++)
j++;
}
if (j != 0) {
md->sans = calloc((size_t)j+1, sizeof(*md->sans));
if (md->sans == NULL) {
ret = ENOMEM;
goto cleanup;
}
j = 0;
if (pkinit_sans != NULL) {
for (i = 0; pkinit_sans[i] != NULL; i++)
md->sans[j++] = pkinit_sans[i];
free(pkinit_sans);
}
if (upn_sans != NULL) {
for (i = 0; upn_sans[i] != NULL; i++)
md->sans[j++] = upn_sans[i];
free(upn_sans);
}
md->sans[j] = NULL;
} else
md->sans = NULL;
ret = crypto_retrieve_X509_key_usage(context, plg_cryptoctx,
req_cryptoctx, cert, &md->ku_bits,
&md->eku_bits);
if (ret)
goto cleanup;
*md_out = md;
md = NULL;
cleanup:
crypto_cert_free_matching_data(context, md);
return ret;
}

GF_Err vobsub_read_idx(FILE *file, vobsub_file *vobsub, s32 *version)
{
char  strbuf[256];
char *str, *pos, *entry;
s32   line, id =-1, delay = 0;
Bool  error = 0;
for (line = 0; !error && gf_fgets(strbuf, sizeof(strbuf), file); line++)
{
str = strtrim(strbuf);
if (line == 0)
{
char *buf = "VobSub index file, v";
pos = strstr(str, buf);
if (pos == NULL || sscanf(pos + strlen(buf), "%d", version) != 1 || *version > VOBSUBIDXVER)
{
error = 1;
continue;
}
}
else if (strlen(str) == 0)
{
continue;
}
else if (str[0] == '#')
{
continue;
}
pos = strchr(str, ':');
if (pos == NULL || pos == str)
{
continue;
}
entry = str;
*pos  = '\0';
str = strtrim(pos + 1);
if (strlen(str) == 0)
{
continue;
}
if (stricmp(entry, "size") == 0)
{
s32 w, h;
if (sscanf(str, "%dx%d", &w, &h) != 2)
{
error = 1;
}
vobsub->width  = w;
vobsub->height = h;
}
else if (stricmp(entry, "palette") == 0)
{
s32 c;
u8  palette[16][4];
if (sscanf(str, "%x,%x,%x,%x,%x,%x,%x,%x,%x,%x,%x,%x,%x,%x,%x,%x",
(u32 *) &palette[0], (u32 *) &palette[1], (u32 *) &palette[2], (u32 *) &palette[3],
(u32 *) &palette[4], (u32 *) &palette[5], (u32 *) &palette[6], (u32 *) &palette[7],
(u32 *) &palette[8], (u32 *) &palette[9], (u32 *) &palette[10], (u32 *) &palette[11],
(u32 *) &palette[12],(u32 *) &palette[13],(u32 *) &palette[14], (u32 *) &palette[15]) != 16)
{
error = 1;
continue;
}
for (c = 0; c < 16; c++)
{
u8 r, g, b;
r = palette[c][2];
g = palette[c][1];
b = palette[c][0];
vobsub->palette[c][0] = 0;
vobsub->palette[c][1] = (( 66 * r + 129 * g +  25 * b + 128 +  4096) >> 8) & 0xff;
vobsub->palette[c][2] = ((112 * r -  94 * g -  18 * b + 128 + 32768) >> 8) & 0xff;
vobsub->palette[c][3] = ((-38 * r -  74 * g + 112 * b + 128 + 32768) >> 8) & 0xff;
}
}
else if (stricmp(entry, "id") == 0)
{
char *buf = "index:";
s32   lang_id;
strlwr(str);
lang_id = ((str[0] & 0xff) << 8) | (str[1] & 0xff);
pos = strstr(str, buf);
if (pos == NULL)
{
error = 1;
continue;
}
if (sscanf(pos + strlen(buf), "%d", &id) != 1 || id < 0 || id >= 32)
{
error = 1;
continue;
}
vobsub->langs[id].id   = lang_id;
vobsub->langs[id].name = lang_table[vobsub_lang_name((u16)lang_id)].lang;
vobsub->langs[id].idx = id;
vobsub->langs[id].subpos = gf_list_new();
if (vobsub->langs[id].subpos == NULL)
{
error = 1;
continue;
}
delay = 0;
vobsub->num_langs++;
}
else if (id >= 0 && stricmp(entry, "delay") == 0)
{
s32  hh, mm, ss, ms;
char c;
s32  sign = (str[0] == '-') ? -1 : 1;
pos = str;
while (*pos == '-' || *pos == '+') pos++;
if (sscanf(pos, "%d%c%d%c%d%c%d", &hh, &c, &mm, &c, &ss, &c, &ms) != 7)
{
error = 1;
continue;
}
delay += (hh*60*60*1000 + mm*60*1000 + ss*1000 + ms) * sign;
}
else if (id >= 0 && stricmp(entry, "timestamp") == 0)
{
vobsub_pos *vspos;
s32         sign;
char        c;
s32         hh, mm, ss, ms;
char       *buf = "filepos:";
vspos = (vobsub_pos*)gf_calloc(1, sizeof(vobsub_pos));
if (vspos == NULL) {
error = 1;
continue;
}
sign = (str[0] == '-') ? -1 : 1;
while (*str == '-' || *str == '+') str++;
if (sscanf(str, "%d%c%d%c%d%c%d", &hh, &c, &mm, &c, &ss, &c, &ms) != 7)
{
gf_free(vspos);
error = 1;
continue;
}
vspos->start = (((hh*60 + mm)*60 + ss)*1000 + ms) * sign + delay;
pos = strstr(str, buf);
if (pos == NULL)
{
gf_free(vspos);
error = 1;
continue;
}
if (sscanf(pos + strlen(buf), LLX, &vspos->filepos) != 1)
{
gf_free(vspos);
error = 1;
continue;
}
if (delay < 0 && gf_list_count(vobsub->langs[id].subpos) > 0)
{
vobsub_pos *vspos_next;
vspos_next = (vobsub_pos*)gf_list_get(vobsub->langs[id].subpos, gf_list_count(vobsub->langs[id].subpos) - 1);
if (vspos->start < vspos_next->start)
{
delay += (s32)(vspos_next->start - vspos->start);
vspos->start = vspos_next->start;
}
}
if (gf_list_add(vobsub->langs[id].subpos, vspos) != GF_OK)
{
gf_free(vspos);
error = 1;
continue;
}
}
}
return error ? GF_CORRUPTED_DATA : GF_OK;
}

static void
fz_append_display_node(
fz_context *ctx,
fz_device *dev,
fz_display_command cmd,
int flags,
const fz_rect *rect,
const fz_path *path,
const float *color,
fz_colorspace *colorspace,
const float *alpha,
const fz_matrix *ctm,
const fz_stroke_state *stroke,
const void *private_data,
int private_data_len)
{
fz_display_node node = { 0 };
fz_display_node *node_ptr;
fz_list_device *writer = (fz_list_device *)dev;
fz_display_list *list = writer->list;
int size;
int rect_off = 0;
int path_off = 0;
int color_off = 0;
int colorspace_off = 0;
int alpha_off = 0;
int ctm_off = 0;
int stroke_off = 0;
int rect_for_updates = 0;
int private_off = 0;
fz_path *my_path = NULL;
fz_stroke_state *my_stroke = NULL;
fz_rect local_rect;
int path_size = 0;
switch (cmd)
{
case FZ_CMD_CLIP_PATH:
case FZ_CMD_CLIP_STROKE_PATH:
case FZ_CMD_CLIP_TEXT:
case FZ_CMD_CLIP_STROKE_TEXT:
case FZ_CMD_CLIP_IMAGE_MASK:
if (writer->top < STACK_SIZE)
{
rect_for_updates = 1;
writer->stack[writer->top].rect = fz_empty_rect;
}
writer->top++;
break;
case FZ_CMD_END_MASK:
if (writer->top < STACK_SIZE)
{
writer->stack[writer->top].update = NULL;
writer->stack[writer->top].rect = fz_empty_rect;
}
writer->top++;
break;
case FZ_CMD_BEGIN_TILE:
writer->tiled++;
if (writer->top > 0 && writer->top <= STACK_SIZE)
{
writer->stack[writer->top-1].rect = fz_infinite_rect;
}
break;
case FZ_CMD_END_TILE:
writer->tiled--;
break;
case FZ_CMD_END_GROUP:
break;
case FZ_CMD_POP_CLIP:
if (writer->top > STACK_SIZE)
{
writer->top--;
rect = &fz_infinite_rect;
}
else if (writer->top > 0)
{
fz_rect *update;
writer->top--;
update = writer->stack[writer->top].update;
if (writer->tiled == 0)
{
if (update)
{
*update = fz_intersect_rect(*update, writer->stack[writer->top].rect);
local_rect = *update;
rect = &local_rect;
}
else
rect = &writer->stack[writer->top].rect;
}
else
rect = &fz_infinite_rect;
}
default:
if (writer->top > 0 && writer->tiled == 0 && writer->top <= STACK_SIZE && rect)
writer->stack[writer->top-1].rect = fz_union_rect(writer->stack[writer->top-1].rect, *rect);
break;
}
size = 1; 
node.cmd = cmd;
if (rect_for_updates || (rect != NULL && (writer->rect.x0 != rect->x0 || writer->rect.y0 != rect->y0 || writer->rect.x1 != rect->x1 || writer->rect.y1 != rect->y1)))
{
node.rect = 1;
rect_off = size;
size += SIZE_IN_NODES(sizeof(fz_rect));
}
if (color || colorspace)
{
if (colorspace != writer->colorspace)
{
assert(color);
if (colorspace == fz_device_gray(ctx))
{
if (color[0] == 0.0f)
node.cs = CS_GRAY_0, color = NULL;
else
{
node.cs = CS_GRAY_1;
if (color[0] == 1.0f)
color = NULL;
}
}
else if (colorspace == fz_device_rgb(ctx))
{
if (color[0] == 0.0f && color[1] == 0.0f && color[2] == 0.0f)
node.cs = CS_RGB_0, color = NULL;
else
{
node.cs = CS_RGB_1;
if (color[0] == 1.0f && color[1] == 1.0f && color[2] == 1.0f)
color = NULL;
}
}
else if (colorspace == fz_device_cmyk(ctx))
{
node.cs = CS_CMYK_0;
if (color[0] == 0.0f && color[1] == 0.0f && color[2] == 0.0f)
{
if (color[3] == 0.0f)
color = NULL;
else
{
node.cs = CS_CMYK_1;
if (color[3] == 1.0f)
color = NULL;
}
}
}
else
{
int i;
int n = fz_colorspace_n(ctx, colorspace);
colorspace_off = size;
size += SIZE_IN_NODES(sizeof(fz_colorspace *));
node.cs = CS_OTHER_0;
for (i = 0; i < n; i++)
if (color[i] != 0.0f)
break;
if (i == n)
color = NULL;
memset(writer->color, 0, sizeof(float)*n);
}
}
else
{
if (colorspace == fz_device_gray(ctx))
{
if (writer->color[0] != color[0])
{
if (color[0] == 0.0f)
{
node.cs = CS_GRAY_0;
color = NULL;
}
else if (color[0] == 1.0f)
{
node.cs = CS_GRAY_1;
color = NULL;
}
}
}
else if (colorspace == fz_device_rgb(ctx))
{
if (writer->color[0] != color[0] || writer->color[1] != color[1] || writer->color[2] != color[2])
{
if (color[0] == 0.0f && color[1] == 0.0f && color[2] == 0.0f)
{
node.cs = CS_RGB_0;
color = NULL;
}
else if (color[0] == 1.0f && color[1] == 1.0f && color[2] == 1.0f)
{
node.cs = CS_RGB_1;
color = NULL;
}
}
}
else if (colorspace == fz_device_cmyk(ctx))
{
if (writer->color[0] != color[0] || writer->color[1] != color[1] || writer->color[2] != color[2] || writer->color[3] != color[3])
{
if (color[0] == 0.0f && color[1] == 0.0f && color[2] == 0.0f)
{
if (color[3] == 0.0f)
{
node.cs = CS_CMYK_0;
color = NULL;
}
else if (color[3] == 1.0f)
{
node.cs = CS_CMYK_1;
color = NULL;
}
}
}
}
else
{
int i;
int n = fz_colorspace_n(ctx, colorspace);
for (i=0; i < n; i++)
if (color[i] != 0.0f)
break;
if (i == n)
{
node.cs = CS_OTHER_0;
colorspace_off = size;
size += SIZE_IN_NODES(sizeof(fz_colorspace *));
color = NULL;
}
}
}
}
if (color)
{
int i, n;
const float *wc = &writer->color[0];
assert(colorspace != NULL);
n = fz_colorspace_n(ctx, colorspace);
i = 0;
if (colorspace == writer->colorspace)
for (; i < n; i++)
if (color[i] != wc[i])
break;
if (i != n)
{
node.color = 1;
color_off = size;
size += n * SIZE_IN_NODES(sizeof(float));
}
}
if (alpha && (*alpha != writer->alpha))
{
if (*alpha >= 1.0f)
node.alpha = ALPHA_1;
else if (*alpha <= 0.0f)
node.alpha = ALPHA_0;
else
{
alpha_off = size;
size += SIZE_IN_NODES(sizeof(float));
node.alpha = ALPHA_PRESENT;
}
}
if (ctm && (ctm->a != writer->ctm.a || ctm->b != writer->ctm.b || ctm->c != writer->ctm.c || ctm->d != writer->ctm.d || ctm->e != writer->ctm.e || ctm->f != writer->ctm.f))
{
int ctm_flags;
ctm_off = size;
ctm_flags = CTM_UNCHANGED;
if (ctm->a != writer->ctm.a || ctm->d != writer->ctm.d)
ctm_flags = CTM_CHANGE_AD, size += SIZE_IN_NODES(2*sizeof(float));
if (ctm->b != writer->ctm.b || ctm->c != writer->ctm.c)
ctm_flags |= CTM_CHANGE_BC, size += SIZE_IN_NODES(2*sizeof(float));
if (ctm->e != writer->ctm.e || ctm->f != writer->ctm.f)
ctm_flags |= CTM_CHANGE_EF, size += SIZE_IN_NODES(2*sizeof(float));
node.ctm = ctm_flags;
}
if (stroke && (writer->stroke == NULL || stroke != writer->stroke))
{
stroke_off = size;
size += SIZE_IN_NODES(sizeof(fz_stroke_state *));
node.stroke = 1;
}
if (path && (writer->path == NULL || path != writer->path))
{
int max = SIZE_IN_NODES(MAX_NODE_SIZE) - size - SIZE_IN_NODES(private_data_len);
path_size = SIZE_IN_NODES(fz_pack_path(ctx, NULL, max, path));
node.path = 1;
path_off = size;
size += path_size;
}
if (private_data != NULL)
{
private_off = size;
size += SIZE_IN_NODES(private_data_len);
}
if (list->len + size > list->max)
{
int newsize = list->max * 2;
fz_display_node *old = list->list;
ptrdiff_t diff;
int i, n;
if (newsize < 256)
newsize = 256;
list->list = fz_realloc_array(ctx, list->list, newsize, fz_display_node);
list->max = newsize;
diff = (char *)(list->list) - (char *)old;
n = (writer->top < STACK_SIZE ? writer->top : STACK_SIZE);
for (i = 0; i < n; i++)
{
if (writer->stack[i].update != NULL)
writer->stack[i].update = (fz_rect *)(((char *)writer->stack[i].update) + diff);
}
if (writer->path)
writer->path = (fz_path *)(((char *)writer->path) + diff);
}
node.size = size;
node.flags = flags;
assert(size < (1<<9));
node_ptr = &list->list[list->len];
*node_ptr = node;
if (path_off)
{
my_path = (void *)(&node_ptr[path_off]);
(void)fz_pack_path(ctx, (void *)my_path, path_size * sizeof(fz_display_node), path);
}
if (stroke_off)
{
fz_try(ctx)
{
my_stroke = fz_keep_stroke_state(ctx, stroke);
}
fz_catch(ctx)
{
fz_drop_path(ctx, my_path);
fz_rethrow(ctx);
}
}
if (rect_off)
{
fz_rect *out_rect = (fz_rect *)(void *)(&node_ptr[rect_off]);
writer->rect = *rect;
*out_rect = *rect;
if (rect_for_updates)
writer->stack[writer->top-1].update = out_rect;
}
if (path_off)
{
fz_drop_path(ctx, writer->path);
writer->path = fz_keep_path(ctx, my_path); 
}
if (node.cs)
{
fz_drop_colorspace(ctx, writer->colorspace);
switch(node.cs)
{
case CS_GRAY_0:
writer->colorspace = fz_keep_colorspace(ctx, fz_device_gray(ctx));
writer->color[0] = 0;
break;
case CS_GRAY_1:
writer->colorspace = fz_keep_colorspace(ctx, fz_device_gray(ctx));
writer->color[0] = 1;
break;
case CS_RGB_0:
writer->color[0] = 0;
writer->color[1] = 0;
writer->color[2] = 0;
writer->colorspace = fz_keep_colorspace(ctx, fz_device_rgb(ctx));
break;
case CS_RGB_1:
writer->color[0] = 1;
writer->color[1] = 1;
writer->color[2] = 1;
writer->colorspace = fz_keep_colorspace(ctx, fz_device_rgb(ctx));
break;
case CS_CMYK_0:
writer->color[0] = 0;
writer->color[1] = 0;
writer->color[2] = 0;
writer->color[3] = 0;
writer->colorspace = fz_keep_colorspace(ctx, fz_device_cmyk(ctx));
break;
case CS_CMYK_1:
writer->color[0] = 0;
writer->color[1] = 0;
writer->color[2] = 0;
writer->color[3] = 1;
writer->colorspace = fz_keep_colorspace(ctx, fz_device_cmyk(ctx));
break;
default:
{
fz_colorspace **out_colorspace = (fz_colorspace **)(void *)(&node_ptr[colorspace_off]);
int i, n;
n = fz_colorspace_n(ctx, colorspace);
*out_colorspace = fz_keep_colorspace(ctx, colorspace);
writer->colorspace = fz_keep_colorspace(ctx, colorspace);
for (i = 0; i < n; i++)
writer->color[i] = 0;
break;
}
}
}
if (color_off)
{
int n = fz_colorspace_n(ctx, colorspace);
float *out_color = (float *)(void *)(&node_ptr[color_off]);
memcpy(writer->color, color, n * sizeof(float));
memcpy(out_color, color, n * sizeof(float));
}
if (node.alpha)
{
writer->alpha = *alpha;
if (alpha_off)
{
float *out_alpha = (float *)(void *)(&node_ptr[alpha_off]);
*out_alpha = *alpha;
}
}
if (ctm_off)
{
float *out_ctm = (float *)(void *)(&node_ptr[ctm_off]);
if (node.ctm & CTM_CHANGE_AD)
{
writer->ctm.a = *out_ctm++ = ctm->a;
writer->ctm.d = *out_ctm++ = ctm->d;
}
if (node.ctm & CTM_CHANGE_BC)
{
writer->ctm.b = *out_ctm++ = ctm->b;
writer->ctm.c = *out_ctm++ = ctm->c;
}
if (node.ctm & CTM_CHANGE_EF)
{
writer->ctm.e = *out_ctm++ = ctm->e;
writer->ctm.f = *out_ctm = ctm->f;
}
}
if (stroke_off)
{
fz_stroke_state **out_stroke = (fz_stroke_state **)(void *)(&node_ptr[stroke_off]);
*out_stroke = my_stroke;
fz_drop_stroke_state(ctx, writer->stroke);
writer->stroke = fz_keep_stroke_state(ctx, my_stroke);
}
if (private_off)
{
char *out_private = (char *)(void *)(&node_ptr[private_off]);
memcpy(out_private, private_data, private_data_len);
}
list->len += size;
}

static void
print_attr_string(netdissect_options *ndo,
register const u_char *data, u_int length, u_short attr_code)
{
register u_int i;
ND_TCHECK2(data[0],length);
switch(attr_code)
{
case TUNNEL_PASS:
if (length < 3)
{
ND_PRINT((ndo, "%s", tstr));
return;
}
if (*data && (*data <=0x1F) )
ND_PRINT((ndo, "Tag[%u] ", *data));
else
ND_PRINT((ndo, "Tag[Unused] "));
data++;
length--;
ND_PRINT((ndo, "Salt %u ", EXTRACT_16BITS(data)));
data+=2;
length-=2;
break;
case TUNNEL_CLIENT_END:
case TUNNEL_SERVER_END:
case TUNNEL_PRIV_GROUP:
case TUNNEL_ASSIGN_ID:
case TUNNEL_CLIENT_AUTH:
case TUNNEL_SERVER_AUTH:
if (*data <= 0x1F)
{
if (length < 1)
{
ND_PRINT((ndo, "%s", tstr));
return;
}
if (*data)
ND_PRINT((ndo, "Tag[%u] ", *data));
else
ND_PRINT((ndo, "Tag[Unused] "));
data++;
length--;
}
break;
case EGRESS_VLAN_NAME:
ND_PRINT((ndo, "%s (0x%02x) ",
tok2str(rfc4675_tagged,"Unknown tag",*data),
*data));
data++;
length--;
break;
}
for (i=0; *data && i < length ; i++, data++)
ND_PRINT((ndo, "%c", (*data < 32 || *data > 126) ? '.' : *data));
return;
trunc:
ND_PRINT((ndo, "%s", tstr));
}

char_u *
str2special(
char_u**sp,
intfrom){
intc;
static char_ubuf[7];
char_u*str = *sp;
intmodifiers = 0;
intspecial = FALSE;
if (has_mbyte)
{
char_u*p;
p = mb_unescape(sp);
if (p != NULL)
return p;
}
c = *str;
if (c == K_SPECIAL && str[1] != NUL && str[2] != NUL)
{
if (str[1] == KS_MODIFIER)
{
modifiers = str[2];
str += 3;
c = *str;
}
if (c == K_SPECIAL && str[1] != NUL && str[2] != NUL)
{
c = TO_SPECIAL(str[1], str[2]);
str += 2;
}
if (IS_SPECIAL(c) || modifiers)    special = TRUE;
}
if (has_mbyte && !IS_SPECIAL(c) && MB_BYTE2LEN(c) > 1)
{
char_u*p;
*sp = str;
p = mb_unescape(sp);
if (p != NULL)
c = (*mb_ptr2char)(p);
else
*sp = str + 1;
}
else
*sp = str + 1;
if (special || c < ' ' || (from && c == ' '))
return get_special_key_name(c, modifiers);
buf[0] = c;
buf[1] = NUL;
return buf;
}

static const ut8 *r_bin_dwarf_parse_comp_unit(Sdb *s, const ut8 *obuf,
RBinDwarfCompUnit *cu, const RBinDwarfDebugAbbrev *da,
size_t offset, const ut8 *debug_str, size_t debug_str_len) {
const ut8 *buf = obuf, *buf_end = obuf + (cu->hdr.length - 7);
ut64 abbr_code;
size_t i;
if (cu->hdr.length > debug_str_len) {
return NULL;
}
while (buf && buf < buf_end && buf >= obuf) {
if (cu->length && cu->capacity == cu->length) {
r_bin_dwarf_expand_cu (cu);
}
buf = r_uleb128 (buf, buf_end - buf, &abbr_code);
if (abbr_code > da->length || !buf) {
return NULL;
}
r_bin_dwarf_init_die (&cu->dies[cu->length]);
if (!abbr_code) {
cu->dies[cu->length].abbrev_code = 0;
cu->length++;
buf++;
continue;
}
cu->dies[cu->length].abbrev_code = abbr_code;
cu->dies[cu->length].tag = da->decls[abbr_code - 1].tag;
abbr_code += offset;
if (da->capacity < abbr_code) {
return NULL;
}
for (i = 0; i < da->decls[abbr_code - 1].length; i++) {
if (cu->dies[cu->length].length == cu->dies[cu->length].capacity) {
r_bin_dwarf_expand_die (&cu->dies[cu->length]);
}
if (i >= cu->dies[cu->length].capacity || i >= da->decls[abbr_code - 1].capacity) {
eprintf ("Warning: malformed dwarf attribute capacity doesn't match length\n");
break;
}
memset (&cu->dies[cu->length].attr_values[i], 0, sizeof (cu->dies[cu->length].attr_values[i]));
buf = r_bin_dwarf_parse_attr_value (buf, buf_end - buf,
&da->decls[abbr_code - 1].specs[i],
&cu->dies[cu->length].attr_values[i],
&cu->hdr, debug_str, debug_str_len);
if (cu->dies[cu->length].attr_values[i].name == DW_AT_comp_dir) {
const char *name = cu->dies[cu->length].attr_values[i].encoding.str_struct.string;
sdb_set (s, "DW_AT_comp_dir", name, 0);
}
cu->dies[cu->length].length++;
}
cu->length++;
}
return buf;
}

GF_EXPORT
GF_Err gf_hinter_track_finalize(GF_RTPHinter *tkHint, Bool AddSystemInfo)
{
u32 Width, Height;
GF_ESD *esd;
char sdpLine[20000];
char mediaName[30], payloadName[30];
u32 mtype;
Width = Height = 0;
gf_isom_sdp_clean_track(tkHint->file, tkHint->TrackNum);
mtype = gf_isom_get_media_type(tkHint->file, tkHint->TrackNum);
if (gf_isom_is_video_handler_type(mtype))
gf_isom_get_visual_info(tkHint->file, tkHint->TrackNum, 1, &Width, &Height);
gf_rtp_builder_get_payload_name(tkHint->rtp_p, payloadName, mediaName);
sprintf(sdpLine, "m=%s 0 RTP/%s %d", mediaName, tkHint->rtp_p->slMap.IV_length ? "SAVP" : "AVP", tkHint->rtp_p->PayloadType);
gf_isom_sdp_add_track_line(tkHint->file, tkHint->HintTrack, sdpLine);
if (tkHint->bandwidth) {
sprintf(sdpLine, "b=AS:%d", tkHint->bandwidth);
gf_isom_sdp_add_track_line(tkHint->file, tkHint->HintTrack, sdpLine);
}
if (tkHint->nb_chan) {
sprintf(sdpLine, "a=rtpmap:%d %s/%d/%d", tkHint->rtp_p->PayloadType, payloadName, tkHint->rtp_p->sl_config.timestampResolution, tkHint->nb_chan);
} else {
sprintf(sdpLine, "a=rtpmap:%d %s/%d", tkHint->rtp_p->PayloadType, payloadName, tkHint->rtp_p->sl_config.timestampResolution);
}
gf_isom_sdp_add_track_line(tkHint->file, tkHint->HintTrack, sdpLine);
if (AddSystemInfo) {
sprintf(sdpLine, "a=mpeg4-esid:%d", gf_isom_get_track_id(tkHint->file, tkHint->TrackNum));
gf_isom_sdp_add_track_line(tkHint->file, tkHint->HintTrack, sdpLine);
}
sprintf(sdpLine, "a=control:trackID=%d", gf_isom_get_track_id(tkHint->file, tkHint->HintTrack));
gf_isom_sdp_add_track_line(tkHint->file, tkHint->HintTrack, sdpLine);
if (tkHint->rtp_p->rtp_payt == GF_RTP_PAYT_H263) {
sprintf(sdpLine, "a=cliprect:0,0,%d,%d", Height, Width);
gf_isom_sdp_add_track_line(tkHint->file, tkHint->HintTrack, sdpLine);
}
else if ((tkHint->rtp_p->rtp_payt == GF_RTP_PAYT_AMR) || (tkHint->rtp_p->rtp_payt == GF_RTP_PAYT_AMR_WB)) {
sprintf(sdpLine, "a=fmtp:%d octet-align=1", tkHint->rtp_p->PayloadType);
gf_isom_sdp_add_track_line(tkHint->file, tkHint->HintTrack, sdpLine);
}
else if (tkHint->rtp_p->rtp_payt == GF_RTP_PAYT_3GPP_TEXT) {
u32 w, h, i, m_w, m_h;
s32 tx, ty;
s16 l;
gf_isom_get_track_layout_info(tkHint->file, tkHint->TrackNum, &w, &h, &tx, &ty, &l);
m_w = w;
m_h = h;
for (i=0; i<gf_isom_get_track_count(tkHint->file); i++) {
switch (gf_isom_get_media_type(tkHint->file, i+1)) {
case GF_ISOM_MEDIA_SCENE:
case GF_ISOM_MEDIA_VISUAL:
case GF_ISOM_MEDIA_AUXV:
case GF_ISOM_MEDIA_PICT:
gf_isom_get_track_layout_info(tkHint->file, i+1, &w, &h, &tx, &ty, &l);
if (w>m_w) m_w = w;
if (h>m_h) m_h = h;
break;
default:
break;
}
}
gf_media_format_ttxt_sdp(tkHint->rtp_p, payloadName, sdpLine, w, h, tx, ty, l, m_w, m_h, NULL);
strcat(sdpLine, "; tx3g=");
for (i=0; i<gf_isom_get_sample_description_count(tkHint->file, tkHint->TrackNum); i++) {
u8 *tx3g;
char buffer[2000];
u32 tx3g_len, len;
gf_isom_text_get_encoded_tx3g(tkHint->file, tkHint->TrackNum, i+1, GF_RTP_TX3G_SIDX_OFFSET, &tx3g, &tx3g_len);
len = gf_base64_encode(tx3g, tx3g_len, buffer, 2000);
gf_free(tx3g);
buffer[len] = 0;
if (i) strcat(sdpLine, ", ");
strcat(sdpLine, buffer);
}
gf_isom_sdp_add_track_line(tkHint->file, tkHint->HintTrack, sdpLine);
}
else if ((tkHint->rtp_p->rtp_payt == GF_RTP_PAYT_EVRC_SMV) && (tkHint->rtp_p->auh_size>1)) {
sprintf(sdpLine, "a=fmtp:%d maxptime=%d", tkHint->rtp_p->PayloadType, tkHint->rtp_p->auh_size*20);
gf_isom_sdp_add_track_line(tkHint->file, tkHint->HintTrack, sdpLine);
}
else if ((tkHint->rtp_p->rtp_payt == GF_RTP_PAYT_H264_AVC) || (tkHint->rtp_p->rtp_payt == GF_RTP_PAYT_H264_SVC))  {
GF_AVCConfig *avcc = gf_isom_avc_config_get(tkHint->file, tkHint->TrackNum, 1);
GF_AVCConfig *svcc = gf_isom_svc_config_get(tkHint->file, tkHint->TrackNum, 1);
if (avcc) {
sprintf(sdpLine, "a=fmtp:%d profile-level-id=%02X%02X%02X; packetization-mode=1", tkHint->rtp_p->PayloadType, avcc->AVCProfileIndication, avcc->profile_compatibility, avcc->AVCLevelIndication);
} else {
if (!svcc)
return GF_ISOM_INVALID_FILE;
sprintf(sdpLine, "a=fmtp:%d profile-level-id=%02X%02X%02X; packetization-mode=1", tkHint->rtp_p->PayloadType, svcc->AVCProfileIndication, svcc->profile_compatibility, svcc->AVCLevelIndication);
}
write_avc_config(sdpLine, avcc, svcc);
gf_isom_sdp_add_track_line(tkHint->file, tkHint->HintTrack, sdpLine);
gf_odf_avc_cfg_del(avcc);
gf_odf_avc_cfg_del(svcc);
}
else if (tkHint->rtp_p->rtp_payt==GF_RTP_PAYT_MPEG4) {
esd = gf_isom_get_esd(tkHint->file, tkHint->TrackNum, 1);
if (esd && esd->decoderConfig && esd->decoderConfig->decoderSpecificInfo && esd->decoderConfig->decoderSpecificInfo->data) {
gf_rtp_builder_format_sdp(tkHint->rtp_p, payloadName, sdpLine, esd->decoderConfig->decoderSpecificInfo->data, esd->decoderConfig->decoderSpecificInfo->dataLength);
} else {
gf_rtp_builder_format_sdp(tkHint->rtp_p, payloadName, sdpLine, NULL, 0);
}
if (esd) gf_odf_desc_del((GF_Descriptor *)esd);
if (tkHint->rtp_p->slMap.IV_length) {
const char *kms;
gf_isom_get_ismacryp_info(tkHint->file, tkHint->TrackNum, 1, NULL, NULL, NULL, NULL, &kms, NULL, NULL, NULL);
if (!strnicmp(kms, "(key)", 5) || !strnicmp(kms, "(ipmp)", 6) || !strnicmp(kms, "(uri)", 5)) {
strcat(sdpLine, "; ISMACrypKey=");
} else {
strcat(sdpLine, "; ISMACrypKey=(uri)");
}
strcat(sdpLine, kms);
}
gf_isom_sdp_add_track_line(tkHint->file, tkHint->HintTrack, sdpLine);
}
else if (tkHint->rtp_p->rtp_payt==GF_RTP_PAYT_LATM) {
GF_BitStream *bs;
u8 *config_bytes;
u32 config_size;
bs = gf_bs_new(NULL, 32, GF_BITSTREAM_WRITE);
gf_bs_write_int(bs, 0, 1); 
gf_bs_write_int(bs, 1, 1); 
gf_bs_write_int(bs, 0, 6); 
gf_bs_write_int(bs, 0, 4); 
gf_bs_write_int(bs, 0, 3); 
esd = gf_isom_get_esd(tkHint->file, tkHint->TrackNum, 1);
if (esd && esd->decoderConfig && esd->decoderConfig->decoderSpecificInfo) {
gf_bs_write_data(bs, esd->decoderConfig->decoderSpecificInfo->data, MIN(esd->decoderConfig->decoderSpecificInfo->dataLength, 2) );
}
if (esd) gf_odf_desc_del((GF_Descriptor *)esd);
gf_bs_write_int(bs, 0, 3); 
gf_bs_write_int(bs, 0xff, 8); 
gf_bs_write_int(bs, 0, 1); 
gf_bs_write_int(bs, 0, 1); 
gf_bs_get_content(bs, &config_bytes, &config_size);
gf_bs_del(bs);
gf_rtp_builder_format_sdp(tkHint->rtp_p, payloadName, sdpLine, config_bytes, config_size);
gf_isom_sdp_add_track_line(tkHint->file, tkHint->HintTrack, sdpLine);
gf_free(config_bytes);
}
#if GPAC_ENABLE_3GPP_DIMS_RTP
else if (tkHint->rtp_p->rtp_payt==GF_RTP_PAYT_3GPP_DIMS) {
GF_DIMSDescription dims;
gf_isom_get_visual_info(tkHint->file, tkHint->TrackNum, 1, &Width, &Height);
gf_isom_get_dims_description(tkHint->file, tkHint->TrackNum, 1, &dims);
sprintf(sdpLine, "a=fmtp:%d Version-profile=%d", tkHint->rtp_p->PayloadType, dims.profile);
if (! dims.fullRequestHost) {
char fmt[200];
strcat(sdpLine, ";useFullRequestHost=0");
sprintf(fmt, ";pathComponents=%d", dims.pathComponents);
strcat(sdpLine, fmt);
}
if (!dims.streamType) strcat(sdpLine, ";stream-type=secondary");
if (dims.containsRedundant == 1) strcat(sdpLine, ";contains-redundant=main");
else if (dims.containsRedundant == 2) strcat(sdpLine, ";contains-redundant=redundant");
if (dims.textEncoding && strlen(dims.textEncoding)) {
strcat(sdpLine, ";text-encoding=");
strcat(sdpLine, dims.textEncoding);
}
if (dims.contentEncoding && strlen(dims.contentEncoding)) {
strcat(sdpLine, ";content-coding=");
strcat(sdpLine, dims.contentEncoding);
}
if (dims.contentEncoding && dims.content_script_types && strlen(dims.content_script_types) ) {
strcat(sdpLine, ";content-script-types=");
strcat(sdpLine, dims.contentEncoding);
}
gf_isom_sdp_add_track_line(tkHint->file, tkHint->HintTrack, sdpLine);
}
#endif
if (Width && Height) {
sprintf(sdpLine, "a=framesize:%d %d-%d", tkHint->rtp_p->PayloadType, Width, Height);
gf_isom_sdp_add_track_line(tkHint->file, tkHint->HintTrack, sdpLine);
}
esd = gf_isom_get_esd(tkHint->file, tkHint->TrackNum, 1);
if (esd && esd->decoderConfig && (esd->decoderConfig->rvc_config || esd->decoderConfig->predefined_rvc_config)) {
if (esd->decoderConfig->predefined_rvc_config) {
sprintf(sdpLine, "a=rvc-config-predef:%d", esd->decoderConfig->predefined_rvc_config);
} else {
if ((esd->decoderConfig->objectTypeIndication==GF_CODECID_AVC) || (esd->decoderConfig->objectTypeIndication==GF_CODECID_SVC)) {
sprintf(sdpLine, "a=rvc-config:%s", "http:} else {
sprintf(sdpLine, "a=rvc-config:%s", "http:}
}
gf_isom_sdp_add_track_line(tkHint->file, tkHint->HintTrack, sdpLine);
}
if (esd) gf_odf_desc_del((GF_Descriptor *)esd);
gf_isom_set_track_enabled(tkHint->file, tkHint->HintTrack, GF_TRUE);
return GF_OK;
}

MagickExport Image *SampleImage(const Image *image,const size_t columns,
const size_t rows,ExceptionInfo *exception)
{
#define SampleImageTag  "Sample/Image"
CacheView
*image_view,
*sample_view;
Image
*sample_image;
MagickBooleanType
status;
MagickOffsetType
progress;
register ssize_t
x1;
ssize_t
*x_offset,
y;
PointInfo
sample_offset;
assert(image != (const Image *) NULL);
assert(image->signature == MagickCoreSignature);
if (image->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",image->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
if ((columns == 0) || (rows == 0))
ThrowImageException(ImageError,"NegativeOrZeroImageSize");
if ((columns == image->columns) && (rows == image->rows))
return(CloneImage(image,0,0,MagickTrue,exception));
sample_image=CloneImage(image,columns,rows,MagickTrue,exception);
if (sample_image == (Image *) NULL)
return((Image *) NULL);
sample_offset.x=sample_offset.y=0.5-MagickEpsilon;
{
const char
*value;
value=GetImageArtifact(image,"sample:offset");
if (value != (char *) NULL)
{
GeometryInfo
geometry_info;
MagickStatusType
flags;
(void) ParseGeometry(value,&geometry_info);
flags=ParseGeometry(value,&geometry_info);
sample_offset.x=sample_offset.y=geometry_info.rho/100.0-MagickEpsilon;
if ((flags & SigmaValue) != 0)
sample_offset.y=geometry_info.sigma/100.0-MagickEpsilon;
}
}
x_offset=(ssize_t *) AcquireQuantumMemory((size_t) sample_image->columns,
sizeof(*x_offset));
if (x_offset == (ssize_t *) NULL)
{
sample_image=DestroyImage(sample_image);
ThrowImageException(ResourceLimitError,"MemoryAllocationFailed");
}
for (x1=0; x1 < (ssize_t) sample_image->columns; x1++)
x_offset[x1]=(ssize_t) ((((double) x1+sample_offset.x)*image->columns)/
sample_image->columns);
status=MagickTrue;
progress=0;
image_view=AcquireVirtualCacheView(image,exception);
sample_view=AcquireAuthenticCacheView(sample_image,exception);
#if defined(MAGICKCORE_OPENMP_SUPPORT)
#pragma omp parallel for schedule(static,4) shared(status) \
magick_threads(image,sample_image,1,1)
#endif
for (y=0; y < (ssize_t) sample_image->rows; y++)
{
register const Quantum
*magick_restrict p;
register Quantum
*magick_restrict q;
register ssize_t
x;
ssize_t
y_offset;
if (status == MagickFalse)
continue;
y_offset=(ssize_t) ((((double) y+sample_offset.y)*image->rows)/
sample_image->rows);
p=GetCacheViewVirtualPixels(image_view,0,y_offset,image->columns,1,
exception);
q=QueueCacheViewAuthenticPixels(sample_view,0,y,sample_image->columns,1,
exception);
if ((p == (const Quantum *) NULL) || (q == (Quantum *) NULL))
{
status=MagickFalse;
continue;
}
for (x=0; x < (ssize_t) sample_image->columns; x++)
{
register ssize_t
i;
if (GetPixelWriteMask(sample_image,q) <= (QuantumRange/2))
{
q+=GetPixelChannels(sample_image);
continue;
}
for (i=0; i < (ssize_t) GetPixelChannels(sample_image); i++)
{
PixelChannel
channel;
PixelTrait
sample_traits,
traits;
channel=GetPixelChannelChannel(image,i);
traits=GetPixelChannelTraits(image,channel);
sample_traits=GetPixelChannelTraits(sample_image,channel);
if ((traits == UndefinedPixelTrait) ||
(sample_traits == UndefinedPixelTrait))
continue;
SetPixelChannel(sample_image,channel,p[x_offset[x]*GetPixelChannels(
image)+i],q);
}
q+=GetPixelChannels(sample_image);
}
if (SyncCacheViewAuthenticPixels(sample_view,exception) == MagickFalse)
status=MagickFalse;
if (image->progress_monitor != (MagickProgressMonitor) NULL)
{
MagickBooleanType
proceed;
#if defined(MAGICKCORE_OPENMP_SUPPORT)
#pragma omp critical (MagickCore_SampleImage)
#endif
proceed=SetImageProgress(image,SampleImageTag,progress++,image->rows);
if (proceed == MagickFalse)
status=MagickFalse;
}
}
image_view=DestroyCacheView(image_view);
sample_view=DestroyCacheView(sample_view);
x_offset=(ssize_t *) RelinquishMagickMemory(x_offset);
sample_image->type=image->type;
if (status == MagickFalse)
sample_image=DestroyImage(sample_image);
return(sample_image);
}

MG_INTERNAL int parse_mqtt(struct mbuf *io, struct mg_mqtt_message *mm) {
uint8_t header;
size_t len = 0, len_len = 0;
const char *p, *end;
unsigned char lc = 0;
int cmd;
if (io->len < 2) return MG_MQTT_ERROR_INCOMPLETE_MSG;
header = io->buf[0];
cmd = header >> 4;
len = len_len = 0;
p = io->buf + 1;
while ((size_t)(p - io->buf) < io->len) {
lc = *((const unsigned char *) p++);
len += (lc & 0x7f) << 7 * len_len;
len_len++;
if (!(lc & 0x80)) break;
if (len_len > 4) return MG_MQTT_ERROR_MALFORMED_MSG;
}
end = p + len;
if (lc & 0x80 || len > (io->len - (p - io->buf))) {
return MG_MQTT_ERROR_INCOMPLETE_MSG;
}
mm->cmd = cmd;
mm->qos = MG_MQTT_GET_QOS(header);
switch (cmd) {
case MG_MQTT_CMD_CONNECT: {
p = scanto(p, &mm->protocol_name);
if (p > end - 4) return MG_MQTT_ERROR_MALFORMED_MSG;
mm->protocol_version = *(uint8_t *) p++;
mm->connect_flags = *(uint8_t *) p++;
mm->keep_alive_timer = getu16(p);
p += 2;
if (p >= end) return MG_MQTT_ERROR_MALFORMED_MSG;
p = scanto(p, &mm->client_id);
if (p > end) return MG_MQTT_ERROR_MALFORMED_MSG;
if (mm->connect_flags & MG_MQTT_HAS_WILL) {
if (p >= end) return MG_MQTT_ERROR_MALFORMED_MSG;
p = scanto(p, &mm->will_topic);
}
if (mm->connect_flags & MG_MQTT_HAS_WILL) {
if (p >= end) return MG_MQTT_ERROR_MALFORMED_MSG;
p = scanto(p, &mm->will_message);
}
if (mm->connect_flags & MG_MQTT_HAS_USER_NAME) {
if (p >= end) return MG_MQTT_ERROR_MALFORMED_MSG;
p = scanto(p, &mm->user_name);
}
if (mm->connect_flags & MG_MQTT_HAS_PASSWORD) {
if (p >= end) return MG_MQTT_ERROR_MALFORMED_MSG;
p = scanto(p, &mm->password);
}
if (p != end) return MG_MQTT_ERROR_MALFORMED_MSG;
LOG(LL_DEBUG,
("%d %2x %d proto [%.*s] client_id [%.*s] will_topic [%.*s] "
"will_msg [%.*s] user_name [%.*s] password [%.*s]",
(int) len, (int) mm->connect_flags, (int) mm->keep_alive_timer,
(int) mm->protocol_name.len, mm->protocol_name.p,
(int) mm->client_id.len, mm->client_id.p, (int) mm->will_topic.len,
mm->will_topic.p, (int) mm->will_message.len, mm->will_message.p,
(int) mm->user_name.len, mm->user_name.p, (int) mm->password.len,
mm->password.p));
break;
}
case MG_MQTT_CMD_CONNACK:
if (end - p < 2) return MG_MQTT_ERROR_MALFORMED_MSG;
mm->connack_ret_code = p[1];
break;
case MG_MQTT_CMD_PUBACK:
case MG_MQTT_CMD_PUBREC:
case MG_MQTT_CMD_PUBREL:
case MG_MQTT_CMD_PUBCOMP:
case MG_MQTT_CMD_SUBACK:
mm->message_id = getu16(p);
break;
case MG_MQTT_CMD_PUBLISH: {
p = scanto(p, &mm->topic);
if (p > end) return MG_MQTT_ERROR_MALFORMED_MSG;
if (mm->qos > 0) {
if (end - p < 2) return MG_MQTT_ERROR_MALFORMED_MSG;
mm->message_id = getu16(p);
p += 2;
}
mm->payload.p = p;
mm->payload.len = end - p;
break;
}
case MG_MQTT_CMD_SUBSCRIBE:
if (end - p < 2) return MG_MQTT_ERROR_MALFORMED_MSG;
mm->message_id = getu16(p);
p += 2;
mm->payload.p = p;
mm->payload.len = end - p;
break;
default:
break;
}
mm->len = end - io->buf;
return mm->len;
}

void BrowsingDataRemover::RemoveImpl(
const TimeRange& time_range,
int remove_mask,
const BrowsingDataFilterBuilder& filter_builder,
int origin_type_mask) {
DCHECK_CURRENTLY_ON(BrowserThread::UI);
DCHECK_NE(base::Time(), time_range.end);
SetRemoving(true);
delete_begin_ = time_range.begin;
delete_end_ = time_range.end;
remove_mask_ = remove_mask;
origin_type_mask_ = origin_type_mask;
base::Callback<bool(const GURL& url)> filter =
filter_builder.BuildGeneralFilter();
base::Callback<bool(const ContentSettingsPattern& url)> same_pattern_filter =
filter_builder.BuildWebsiteSettingsPatternMatchesFilter();
PrefService* prefs = profile_->GetPrefs();
bool may_delete_history = prefs->GetBoolean(
prefs::kAllowDeletingBrowserHistory);
DCHECK(may_delete_history || (remove_mask & REMOVE_NOCHECKS) ||
(!(remove_mask & REMOVE_HISTORY) && !(remove_mask & REMOVE_DOWNLOADS)));
if (origin_type_mask_ & BrowsingDataHelper::UNPROTECTED_WEB) {
content::RecordAction(
UserMetricsAction("ClearBrowsingData_MaskContainsUnprotectedWeb"));
}
if (origin_type_mask_ & BrowsingDataHelper::PROTECTED_WEB) {
content::RecordAction(
UserMetricsAction("ClearBrowsingData_MaskContainsProtectedWeb"));
}
if (origin_type_mask_ & BrowsingDataHelper::EXTENSION) {
content::RecordAction(
UserMetricsAction("ClearBrowsingData_MaskContainsExtension"));
}
static_assert(
BrowsingDataHelper::ALL == (BrowsingDataHelper::UNPROTECTED_WEB |
BrowsingDataHelper::PROTECTED_WEB |
BrowsingDataHelper::EXTENSION),
"OriginTypeMask has been updated without updating user metrics");
if ((remove_mask & REMOVE_HISTORY) && may_delete_history) {
history::HistoryService* history_service =
HistoryServiceFactory::GetForProfile(
profile_, ServiceAccessType::EXPLICIT_ACCESS);
if (history_service) {
content::RecordAction(UserMetricsAction("ClearBrowsingData_History"));
waiting_for_clear_history_ = true;
history_service->ExpireLocalAndRemoteHistoryBetween(
WebHistoryServiceFactory::GetForProfile(profile_), std::set<GURL>(),
delete_begin_, delete_end_,
base::Bind(&BrowsingDataRemover::OnHistoryDeletionDone,
weak_ptr_factory_.GetWeakPtr()),
&history_task_tracker_);
#if defined(ENABLE_EXTENSIONS)
extensions::ActivityLog::GetInstance(profile_)->RemoveURLs(
std::set<GURL>());
#endif
}
#if defined(ENABLE_EXTENSIONS)
extensions::ExtensionPrefs* extension_prefs =
extensions::ExtensionPrefs::Get(profile_);
extension_prefs->ClearLastLaunchTimes();
#endif
power::OriginPowerMap* origin_power_map =
power::OriginPowerMapFactory::GetForBrowserContext(profile_);
if (origin_power_map)
origin_power_map->ClearOriginMap();
if (g_browser_process->io_thread()) {
waiting_for_clear_hostname_resolution_cache_ = true;
BrowserThread::PostTaskAndReply(
BrowserThread::IO, FROM_HERE,
base::Bind(&ClearHostnameResolutionCacheOnIOThread,
g_browser_process->io_thread()),
base::Bind(&BrowsingDataRemover::OnClearedHostnameResolutionCache,
weak_ptr_factory_.GetWeakPtr()));
}
if (profile_->GetNetworkPredictor()) {
waiting_for_clear_network_predictor_ = true;
BrowserThread::PostTaskAndReply(
BrowserThread::IO, FROM_HERE,
base::Bind(&ClearNetworkPredictorOnIOThread,
profile_->GetNetworkPredictor()),
base::Bind(&BrowsingDataRemover::OnClearedNetworkPredictor,
weak_ptr_factory_.GetWeakPtr()));
}
TemplateURLService* keywords_model =
TemplateURLServiceFactory::GetForProfile(profile_);
if (keywords_model && !keywords_model->loaded()) {
template_url_sub_ = keywords_model->RegisterOnLoadedCallback(
base::Bind(&BrowsingDataRemover::OnKeywordsLoaded,
weak_ptr_factory_.GetWeakPtr()));
keywords_model->Load();
waiting_for_clear_keyword_data_ = true;
} else if (keywords_model) {
keywords_model->RemoveAutoGeneratedForOriginBetween(GURL(), delete_begin_,
delete_end_);
}
prerender::PrerenderManager* prerender_manager =
prerender::PrerenderManagerFactory::GetForProfile(profile_);
if (prerender_manager) {
prerender_manager->ClearData(
prerender::PrerenderManager::CLEAR_PRERENDER_CONTENTS |
prerender::PrerenderManager::CLEAR_PRERENDER_HISTORY);
}
if (filter_builder.IsEmptyBlacklist()) {
sessions::TabRestoreService* tab_service =
TabRestoreServiceFactory::GetForProfile(profile_);
if (tab_service) {
tab_service->ClearEntries();
tab_service->DeleteLastSession();
}
#if defined(ENABLE_SESSION_SERVICE)
SessionService* session_service =
SessionServiceFactory::GetForProfile(profile_);
if (session_service)
session_service->DeleteLastSession();
#endif
}
scoped_refptr<autofill::AutofillWebDataService> web_data_service =
WebDataServiceFactory::GetAutofillWebDataForProfile(
profile_, ServiceAccessType::EXPLICIT_ACCESS);
if (web_data_service.get()) {
waiting_for_clear_autofill_origin_urls_ = true;
web_data_service->RemoveOriginURLsModifiedBetween(
delete_begin_, delete_end_);
BrowserThread::PostTaskAndReply(
BrowserThread::DB, FROM_HERE, base::Bind(&base::DoNothing),
base::Bind(&BrowsingDataRemover::OnClearedAutofillOriginURLs,
weak_ptr_factory_.GetWeakPtr()));
autofill::PersonalDataManager* data_manager =
autofill::PersonalDataManagerFactory::GetForProfile(profile_);
if (data_manager)
data_manager->Refresh();
}
#if defined(ENABLE_WEBRTC)
waiting_for_clear_webrtc_logs_ = true;
BrowserThread::PostTaskAndReply(
BrowserThread::FILE, FROM_HERE,
base::Bind(
&WebRtcLogUtil::DeleteOldAndRecentWebRtcLogFiles,
WebRtcLogList::GetWebRtcLogDirectoryForProfile(profile_->GetPath()),
delete_begin_),
base::Bind(&BrowsingDataRemover::OnClearedWebRtcLogs,
weak_ptr_factory_.GetWeakPtr()));
#endif
if (profile_->GetSSLHostStateDelegate())
profile_->GetSSLHostStateDelegate()->Clear();
#if BUILDFLAG(ANDROID_JAVA_UI)
precache::PrecacheManager* precache_manager =
precache::PrecacheManagerFactory::GetForBrowserContext(profile_);
if (!precache_manager) {
waiting_for_clear_precache_history_ = true;
precache_manager->ClearHistory();
BrowserThread::PostTaskAndReply(
BrowserThread::DB, FROM_HERE, base::Bind(&base::DoNothing),
base::Bind(&BrowsingDataRemover::OnClearedPrecacheHistory,
weak_ptr_factory_.GetWeakPtr()));
}
waiting_for_clear_webapp_history_ = true;
webapp_registry_->ClearWebappHistory(
base::Bind(&BrowsingDataRemover::OnClearedWebappHistory,
weak_ptr_factory_.GetWeakPtr()));
#endif
data_reduction_proxy::DataReductionProxySettings*
data_reduction_proxy_settings =
DataReductionProxyChromeSettingsFactory::GetForBrowserContext(
profile_);
if (data_reduction_proxy_settings) {
data_reduction_proxy::DataReductionProxyService*
data_reduction_proxy_service =
data_reduction_proxy_settings->data_reduction_proxy_service();
if (data_reduction_proxy_service) {
data_reduction_proxy_service->compression_stats()
->DeleteBrowsingHistory(delete_begin_, delete_end_);
}
}
}
if ((remove_mask & REMOVE_DOWNLOADS) && may_delete_history) {
content::RecordAction(UserMetricsAction("ClearBrowsingData_Downloads"));
content::DownloadManager* download_manager =
BrowserContext::GetDownloadManager(profile_);
download_manager->RemoveDownloadsByURLAndTime(filter,
delete_begin_, delete_end_);
DownloadPrefs* download_prefs = DownloadPrefs::FromDownloadManager(
download_manager);
download_prefs->SetSaveFilePath(download_prefs->DownloadPath());
}
uint32_t storage_partition_remove_mask = 0;
if (remove_mask & REMOVE_COOKIES &&
origin_type_mask_ & BrowsingDataHelper::UNPROTECTED_WEB) {
content::RecordAction(UserMetricsAction("ClearBrowsingData_Cookies"));
storage_partition_remove_mask |=
content::StoragePartition::REMOVE_DATA_MASK_COOKIES;
if (delete_begin_ == base::Time()) {
safe_browsing::SafeBrowsingService* sb_service =
g_browser_process->safe_browsing_service();
if (sb_service) {
scoped_refptr<net::URLRequestContextGetter> sb_context =
sb_service->url_request_context();
++waiting_for_clear_cookies_count_;
if (filter_builder.IsEmptyBlacklist()) {
BrowserThread::PostTask(
BrowserThread::IO, FROM_HERE,
base::Bind(&ClearCookiesOnIOThread, delete_begin_, delete_end_,
