if (remove_mask & REMOVE_INDEXEDDB) {
storage_partition_remove_mask |=
content::StoragePartition::REMOVE_DATA_MASK_INDEXEDDB;
}
if (remove_mask & REMOVE_WEBSQL) {
storage_partition_remove_mask |=
