}
rc = rpmfiStat(fi, 1, &sb);
fsmDebug(fpath, action, &sb);
if (rc)
break;
rc = rpmpluginsCallFsmFilePre(plugins, fi, fpath,
sb.st_mode, action);
if (rc) {
skip = 1;
} else {
setFileState(fs, rpmfiFX(fi));
}
if (!skip) {
int setmeta = 1;
if (!suffix) {
rc = fsmBackup(fi, action);
}
if (!suffix) {
rc = fsmVerify(fpath, fi);
} else {
rc = (action == FA_TOUCH) ? 0 : RPMERR_ENOENT;
}
if (S_ISREG(sb.st_mode)) {
if (rc == RPMERR_ENOENT) {
rc = fsmMkfile(fi, fpath, files, psm, nodigest,
&setmeta, &firsthardlink);
}
} else if (S_ISDIR(sb.st_mode)) {
if (rc == RPMERR_ENOENT) {
mode_t mode = sb.st_mode;
mode &= ~07777;
mode |=  00700;
rc = fsmMkdir(fpath, mode);
}
} else if (S_ISLNK(sb.st_mode)) {
if (rc == RPMERR_ENOENT) {
rc = fsmSymlink(rpmfiFLink(fi), fpath);
}
} else if (S_ISFIFO(sb.st_mode)) {
if (rc == RPMERR_ENOENT) {
rc = fsmMkfifo(fpath, 0000);
}
} else if (S_ISCHR(sb.st_mode) ||
S_ISBLK(sb.st_mode) ||
S_ISSOCK(sb.st_mode))
{
if (rc == RPMERR_ENOENT) {
rc = fsmMknod(fpath, sb.st_mode, sb.st_rdev);
}
} else {
if (!IS_DEV_LOG(fpath))
rc = RPMERR_UNKNOWN_FILETYPE;
}
if (!rc && setmeta) {
rc = fsmSetmeta(fpath, fi, plugins, action, &sb, nofcaps);
}
} else if (firsthardlink >= 0 && rpmfiArchiveHasContent(fi)) {
char *fn = rpmfilesFN(files, firsthardlink);
rc = expandRegular(fi, fn, psm, 0, nodigest, 0);
firsthardlink = -1;
free(fn);
}
if (rc) {
if (!skip) {
if (suffix && (action != FA_TOUCH)) {
(void) fsmRemove(fpath, sb.st_mode);
}
errno = saveerrno;
}
} else {
rpmpsmNotify(psm, RPMCALLBACK_INST_PROGRESS, rpmfiArchiveTell(fi));
if (!skip) {
if (suffix)
rc = fsmBackup(fi, action);
if (!rc)
rc = fsmCommit(&fpath, fi, action, suffix);
}
}
if (rc)
*failedFile = xstrdup(fpath);
rpmpluginsCallFsmFilePost(plugins, fi, fpath,
sb.st_mode, action, rc);
fpath = _free(fpath);
}
rpmswAdd(rpmtsOp(ts, RPMTS_OP_UNCOMPRESS), fdOp(payload, FDSTAT_READ));
rpmswAdd(rpmtsOp(ts, RPMTS_OP_DIGEST), fdOp(payload, FDSTAT_DIGEST));
exit:
rpmfiArchiveClose(fi);
rpmfiFree(fi);
Fclose(payload);
free(tid);
free(fpath);
return rc;
}

matvar_t *
Mat_VarReadNextInfo5( mat_t *mat )
{
int err;
mat_int32_t data_type, nBytes;
long fpos;
matvar_t *matvar = NULL;
mat_uint32_t array_flags;
if ( mat == NULL )
return NULL;
fpos = ftell((FILE*)mat->fp);
if ( fpos == -1L ) {
Mat_Critical("Couldn't determine file position");
return NULL;
}
err = fread(&data_type,4,1,(FILE*)mat->fp);
if ( err == 0 )
return NULL;
err = fread(&nBytes,4,1,(FILE*)mat->fp);
if ( mat->byteswap ) {
(void)Mat_int32Swap(&data_type);
(void)Mat_int32Swap(&nBytes);
}
switch ( data_type ) {
case MAT_T_COMPRESSED:
{
#if defined(HAVE_ZLIB)
mat_uint32_t uncomp_buf[16] = {0,};
int      nbytes;
long     bytesread = 0;
matvar = Mat_VarCalloc();
if ( NULL == matvar ) {
Mat_Critical("Couldn't allocate memory");
break;
}
matvar->compression = MAT_COMPRESSION_ZLIB;
matvar->internal->z = (z_streamp)calloc(1,sizeof(z_stream));
err = inflateInit(matvar->internal->z);
if ( err != Z_OK ) {
Mat_VarFree(matvar);
matvar = NULL;
Mat_Critical("inflateInit returned %s",zError(err));
break;
}
bytesread += InflateVarTag(mat,matvar,uncomp_buf);
if ( mat->byteswap ) {
(void)Mat_uint32Swap(uncomp_buf);
(void)Mat_uint32Swap(uncomp_buf+1);
}
nbytes = uncomp_buf[1];
if ( uncomp_buf[0] != MAT_T_MATRIX ) {
(void)fseek((FILE*)mat->fp,nBytes-bytesread,SEEK_CUR);
Mat_VarFree(matvar);
matvar = NULL;
Mat_Critical("Uncompressed type not MAT_T_MATRIX");
break;
}
bytesread += InflateArrayFlags(mat,matvar,uncomp_buf);
if ( mat->byteswap ) {
(void)Mat_uint32Swap(uncomp_buf);
(void)Mat_uint32Swap(uncomp_buf+2);
(void)Mat_uint32Swap(uncomp_buf+3);
}
if ( uncomp_buf[0] == MAT_T_UINT32 ) {
array_flags = uncomp_buf[2];
matvar->class_type = CLASS_FROM_ARRAY_FLAGS(array_flags);
matvar->isComplex  = (array_flags & MAT_F_COMPLEX);
matvar->isGlobal   = (array_flags & MAT_F_GLOBAL);
matvar->isLogical  = (array_flags & MAT_F_LOGICAL);
if ( matvar->class_type == MAT_C_SPARSE ) {
matvar->nbytes = uncomp_buf[3];
}
}
if ( matvar->class_type != MAT_C_OPAQUE ) {
mat_uint32_t* dims = NULL;
int do_clean = 0;
bytesread += InflateRankDims(mat,matvar,uncomp_buf,sizeof(uncomp_buf),&dims);
if ( NULL == dims )
dims = uncomp_buf + 2;
else
do_clean = 1;
if ( mat->byteswap ) {
(void)Mat_uint32Swap(uncomp_buf);
(void)Mat_uint32Swap(uncomp_buf+1);
}
if ( uncomp_buf[0] == MAT_T_INT32 ) {
int j;
nbytes = uncomp_buf[1];
matvar->rank = nbytes / 4;
matvar->dims = (size_t*)malloc(matvar->rank*sizeof(*matvar->dims));
if ( mat->byteswap ) {
for ( j = 0; j < matvar->rank; j++ )
matvar->dims[j] = Mat_uint32Swap(dims + j);
} else {
for ( j = 0; j < matvar->rank; j++ )
matvar->dims[j] = dims[j];
}
}
if ( do_clean )
free(dims);
bytesread += InflateVarTag(mat,matvar,uncomp_buf);
if ( mat->byteswap )
(void)Mat_uint32Swap(uncomp_buf);
if ( uncomp_buf[0] == MAT_T_INT8 ) {    
mat_uint32_t len, len_pad;
if ( mat->byteswap )
len = Mat_uint32Swap(uncomp_buf+1);
else
len = uncomp_buf[1];
if ( len % 8 == 0 )
len_pad = len;
else
len_pad = len + 8 - (len % 8);
matvar->name = (char*)malloc(len_pad + 1);
if ( NULL != matvar->name ) {
bytesread += InflateVarName(mat,matvar,matvar->name,len_pad);
matvar->name[len] = '\0';
}
} else {
mat_uint32_t len = (uncomp_buf[0] & 0xffff0000) >> 16;
if ( ((uncomp_buf[0] & 0x0000ffff) == MAT_T_INT8) && len > 0 && len <= 4 ) {
matvar->name = (char*)malloc(len+1);
if ( NULL != matvar->name ) {
memcpy(matvar->name,uncomp_buf+1,len);
matvar->name[len] = '\0';
}
}
}
if ( matvar->class_type == MAT_C_STRUCT )
(void)ReadNextStructField(mat,matvar);
else if ( matvar->class_type == MAT_C_CELL )
(void)ReadNextCell(mat,matvar);
(void)fseek((FILE*)mat->fp,-(int)matvar->internal->z->avail_in,SEEK_CUR);
matvar->internal->datapos = ftell((FILE*)mat->fp);
if ( matvar->internal->datapos == -1L ) {
Mat_Critical("Couldn't determine file position");
}
}
(void)fseek((FILE*)mat->fp,nBytes+8+fpos,SEEK_SET);
break;
#else
Mat_Critical("Compressed variable found in \"%s\", but matio was "
"built without zlib support",mat->filename);
(void)fseek((FILE*)mat->fp,nBytes+8+fpos,SEEK_SET);
return NULL;
#endif
}
case MAT_T_MATRIX:
{
mat_uint32_t buf[6];
size_t readresult;
readresult = fread(buf, 4, 6, (FILE*)mat->fp);
if ( 6 != readresult ) {
(void)fseek((FILE*)mat->fp, fpos, SEEK_SET);
break;
}
if ( mat->byteswap ) {
(void)Mat_uint32Swap(buf);
(void)Mat_uint32Swap(buf+1);
(void)Mat_uint32Swap(buf+2);
(void)Mat_uint32Swap(buf+3);
(void)Mat_uint32Swap(buf+4);
(void)Mat_uint32Swap(buf+5);
}
matvar = Mat_VarCalloc();
if ( NULL == matvar ) {
Mat_Critical("Couldn't allocate memory");
break;
}
if ( buf[0] == MAT_T_UINT32 ) {
array_flags = buf[2];
matvar->class_type = CLASS_FROM_ARRAY_FLAGS(array_flags);
matvar->isComplex  = (array_flags & MAT_F_COMPLEX);
matvar->isGlobal   = (array_flags & MAT_F_GLOBAL);
matvar->isLogical  = (array_flags & MAT_F_LOGICAL);
if ( matvar->class_type == MAT_C_SPARSE ) {
matvar->nbytes = buf[3];
}
}
readresult = ReadRankDims(mat, matvar, (enum matio_types)buf[4], buf[5]);
if ( 0 == readresult && 0 < matvar->rank ) {
Mat_VarFree(matvar);
matvar = NULL;
(void)fseek((FILE*)mat->fp, fpos, SEEK_SET);
break;
}
readresult = fread(buf, 4, 2, (FILE*)mat->fp);
if ( 2 != readresult ) {
Mat_VarFree(matvar);
matvar = NULL;
(void)fseek((FILE*)mat->fp, fpos, SEEK_SET);
break;
}
if ( mat->byteswap )
(void)Mat_uint32Swap(buf);
if ( buf[0] == MAT_T_INT8 ) {    
mat_uint32_t len, len_pad;
if ( mat->byteswap )
len = Mat_uint32Swap(buf+1);
else
len = buf[1];
if ( len % 8 == 0 )
len_pad = len;
else
len_pad = len + 8 - (len % 8);
matvar->name = (char*)malloc(len_pad + 1);
if ( NULL != matvar->name ) {
readresult = fread(matvar->name, 1, len_pad, (FILE*)mat->fp);
if ( readresult == len_pad ) {
matvar->name[len] = '\0';
} else {
Mat_VarFree(matvar);
matvar = NULL;
(void)fseek((FILE*)mat->fp, fpos, SEEK_SET);
break;
}
}
} else {
mat_uint32_t len = (buf[0] & 0xffff0000) >> 16;
if ( ((buf[0] & 0x0000ffff) == MAT_T_INT8) && len > 0 && len <= 4 ) {
matvar->name = (char*)malloc(len+1);
if ( NULL != matvar->name ) {
memcpy(matvar->name, buf+1, len);
matvar->name[len] = '\0';
}
}
}
if ( matvar->class_type == MAT_C_STRUCT )
(void)ReadNextStructField(mat,matvar);
else if ( matvar->class_type == MAT_C_CELL )
(void)ReadNextCell(mat,matvar);
else if ( matvar->class_type == MAT_C_FUNCTION )
(void)ReadNextFunctionHandle(mat,matvar);
matvar->internal->datapos = ftell((FILE*)mat->fp);
if ( matvar->internal->datapos == -1L ) {
Mat_Critical("Couldn't determine file position");
}
(void)fseek((FILE*)mat->fp,nBytes+8+fpos,SEEK_SET);
break;
}
default:
Mat_Critical("%d is not valid (MAT_T_MATRIX or MAT_T_COMPRESSED)",
data_type);
return NULL;
}
return matvar;
}

static void
cairo_ft_apply_variations (FT_Face                 face,
cairo_ft_scaled_font_t *scaled_font)
{
FT_MM_Var *ft_mm_var;
FT_Error ret;
unsigned int instance_id = scaled_font->unscaled->id >> 16;
ret = FT_Get_MM_Var (face, &ft_mm_var);
if (ret == 0) {
FT_Fixed *current_coords;
FT_Fixed *coords;
unsigned int i;
const char *p;
coords = malloc (sizeof (FT_Fixed) * ft_mm_var->num_axis);
if (scaled_font->unscaled->variations)
{
memcpy (coords, scaled_font->unscaled->variations, ft_mm_var->num_axis * sizeof (*coords));
}
else if (instance_id && instance_id <= ft_mm_var->num_namedstyles)
{
FT_Var_Named_Style *instance = &ft_mm_var->namedstyle[instance_id - 1];
memcpy (coords, instance->coords, ft_mm_var->num_axis * sizeof (*coords));
}
else
for (i = 0; i < ft_mm_var->num_axis; i++)
coords[i] = ft_mm_var->axis[i].def;
p = scaled_font->ft_options.base.variations;
while (p && *p) {
const char *start;
const char *end, *end2;
FT_ULong tag;
double value;
while (_cairo_isspace (*p)) p++;
start = p;
end = strchr (p, ',');
if (end && (end - p < 6))
goto skip;
tag = FT_MAKE_TAG(p[0], p[1], p[2], p[3]);
p += 4;
while (_cairo_isspace (*p)) p++;
if (*p == '=') p++;
if (p - start < 5)
goto skip;
value = _cairo_strtod (p, (char **) &end2);
while (end2 && _cairo_isspace (*end2)) end2++;
if (end2 && (*end2 != ',' && *end2 != '\0'))
goto skip;
for (i = 0; i < ft_mm_var->num_axis; i++) {
if (ft_mm_var->axis[i].tag == tag) {
coords[i] = (FT_Fixed)(value*65536);
break;
}
}
skip:
p = end ? end + 1 : NULL;
}
current_coords = malloc (sizeof (FT_Fixed) * ft_mm_var->num_axis);
#ifdef HAVE_FT_GET_VAR_DESIGN_COORDINATES
ret = FT_Get_Var_Design_Coordinates (face, ft_mm_var->num_axis, current_coords);
if (ret == 0) {
for (i = 0; i < ft_mm_var->num_axis; i++) {
if (coords[i] != current_coords[i])
break;
}
if (i == ft_mm_var->num_axis)
goto done;
}
#endif
FT_Set_Var_Design_Coordinates (face, ft_mm_var->num_axis, coords);
done:
free (coords);
free (current_coords);
free (ft_mm_var);
}
}

static int
dissect_application_isup(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void* data)
{
proto_item *ti;
proto_tree *isup_tree = NULL;
tvbuff_t   *message_tvb;
guint8      message_type;
char       *version, *base;
guint8      itu_isup_variant = ISUP_ITU_STANDARD_VARIANT; 
if (data) {
http_message_info_t *message_info = (http_message_info_t *)data;
if (message_info->media_str) {
version = ws_find_media_type_parameter(message_info->media_str, "version");
base = ws_find_media_type_parameter(message_info->media_str, "base");
if ((version && g_ascii_strncasecmp(version, "ansi", 4) == 0) ||
(base && g_ascii_strncasecmp(base, "ansi", 4) == 0)) {
isup_standard = ANSI_STANDARD;
col_append_str(pinfo->cinfo, COL_PROTOCOL, "/ISUP(ANSI)");
message_type = tvb_get_guint8(tvb, 0);
col_append_sep_fstr(pinfo->cinfo, COL_INFO, ", ",
"ISUP:%s",
val_to_str_ext_const(message_type, &ansi_isup_message_type_value_acro_ext, "reserved"));
if (tree) {
ti = proto_tree_add_item(tree, proto_isup, tvb, 0, -1, ENC_NA);
isup_tree = proto_item_add_subtree(ti, ett_isup);
}
message_tvb = tvb_new_subset_remaining(tvb, 0);
dissect_ansi_isup_message(message_tvb, pinfo, isup_tree, ISUP_ITU_STANDARD_VARIANT, 0);
return tvb_reported_length(tvb);
} else if ((version && g_ascii_strcasecmp(version, "spirou") == 0) ||
(base && g_ascii_strcasecmp(base, "spirou") == 0)) {
isup_standard    = ITU_STANDARD;
itu_isup_variant = ISUP_FRENCH_VARIANT;
} else {
isup_standard = ITU_STANDARD;
}
g_free(version);
g_free(base);
} else {
isup_standard = ITU_STANDARD;
}
} else {
isup_standard = ITU_STANDARD;
}
message_type = tvb_get_guint8(tvb, 0);
switch (itu_isup_variant) {
case ISUP_ITU_STANDARD_VARIANT:
col_append_str(pinfo->cinfo, COL_PROTOCOL, "/ISUP(ITU)");
col_append_sep_fstr(pinfo->cinfo, COL_INFO, ", ",
"ISUP:%s",
val_to_str_ext_const(message_type, &isup_message_type_value_acro_ext, "reserved"));
break;
case ISUP_FRENCH_VARIANT:
col_append_str(pinfo->cinfo, COL_PROTOCOL, "/ISUP(French)");
col_append_sep_fstr(pinfo->cinfo, COL_INFO, ", ",
"ISUP:%s",
val_to_str_ext_const(message_type, &french_isup_message_type_value_acro_ext, "reserved"));
break;
#if 0
case ISUP_ISRAELI_VARIANT:
col_append_str(pinfo->cinfo, COL_PROTOCOL, "/ISUP(Israeli)");
col_append_sep_fstr(pinfo->cinfo, COL_INFO, ", ",
"ISUP:%s",
val_to_str_ext_const(message_type, &israeli_isup_message_type_value_acro_ext, "reserved"));
break;
#endif
default:
col_append_sep_fstr(pinfo->cinfo, COL_INFO, ", ",
"ISUP: Unknown variant %d", itu_isup_variant);
break;
}
if (tree) {
ti = proto_tree_add_item(tree, proto_isup, tvb, 0, -1, ENC_NA);
isup_tree = proto_item_add_subtree(ti, ett_isup);
}
message_tvb = tvb_new_subset_remaining(tvb, 0);
dissect_isup_message(message_tvb, pinfo, isup_tree, itu_isup_variant, 0);
return tvb_reported_length(tvb);
}

