Expression*
flexibleCopy(Expression* original, Module& wasm, CustomCopier custom) {
struct Copier : public OverriddenVisitor<Copier, Expression*> {
Module& wasm;
CustomCopier custom;
Builder builder;
Copier(Module& wasm, CustomCopier custom)
: wasm(wasm), custom(custom), builder(wasm) {}
Expression* copy(Expression* curr) {
if (!curr) {
return nullptr;
}
auto* ret = custom(curr);
if (ret) {
return ret;
}
return OverriddenVisitor<Copier, Expression*>::visit(curr);
}
Expression* visitBlock(Block* curr) {
ExpressionList list(wasm.allocator);
for (Index i = 0; i < curr->list.size(); i++) {
list.push_back(copy(curr->list[i]));
}
return builder.makeBlock(curr->name, list, curr->type);
}
Expression* visitIf(If* curr) {
return builder.makeIf(copy(curr->condition),
copy(curr->ifTrue),
copy(curr->ifFalse),
curr->type);
}
Expression* visitLoop(Loop* curr) {
return builder.makeLoop(curr->name, copy(curr->body));
}
Expression* visitBreak(Break* curr) {
return builder.makeBreak(
curr->name, copy(curr->value), copy(curr->condition));
}
Expression* visitSwitch(Switch* curr) {
return builder.makeSwitch(curr->targets,
curr->default_,
copy(curr->condition),
copy(curr->value));
}
Expression* visitCall(Call* curr) {
auto* ret =
builder.makeCall(curr->target, {}, curr->type, curr->isReturn);
for (Index i = 0; i < curr->operands.size(); i++) {
ret->operands.push_back(copy(curr->operands[i]));
}
return ret;
}
Expression* visitCallIndirect(CallIndirect* curr) {
auto* ret = builder.makeCallIndirect(
curr->fullType, copy(curr->target), {}, curr->type, curr->isReturn);
for (Index i = 0; i < curr->operands.size(); i++) {
ret->operands.push_back(copy(curr->operands[i]));
}
return ret;
}
Expression* visitLocalGet(LocalGet* curr) {
return builder.makeLocalGet(curr->index, curr->type);
}
Expression* visitLocalSet(LocalSet* curr) {
if (curr->isTee()) {
return builder.makeLocalTee(curr->index, copy(curr->value));
} else {
return builder.makeLocalSet(curr->index, copy(curr->value));
}
}
Expression* visitGlobalGet(GlobalGet* curr) {
return builder.makeGlobalGet(curr->name, curr->type);
}
Expression* visitGlobalSet(GlobalSet* curr) {
return builder.makeGlobalSet(curr->name, copy(curr->value));
}
Expression* visitLoad(Load* curr) {
if (curr->isAtomic) {
return builder.makeAtomicLoad(
curr->bytes, curr->offset, copy(curr->ptr), curr->type);
}
return builder.makeLoad(curr->bytes,
LoadUtils::isSignRelevant(curr) ? curr->signed_
: false,
curr->offset,
curr->align,
copy(curr->ptr),
curr->type);
}
Expression* visitStore(Store* curr) {
if (curr->isAtomic) {
return builder.makeAtomicStore(curr->bytes,
curr->offset,
copy(curr->ptr),
copy(curr->value),
curr->valueType);
}
return builder.makeStore(curr->bytes,
curr->offset,
curr->align,
copy(curr->ptr),
copy(curr->value),
curr->valueType);
}
Expression* visitAtomicRMW(AtomicRMW* curr) {
return builder.makeAtomicRMW(curr->op,
curr->bytes,
curr->offset,
copy(curr->ptr),
copy(curr->value),
curr->type);
}
Expression* visitAtomicCmpxchg(AtomicCmpxchg* curr) {
return builder.makeAtomicCmpxchg(curr->bytes,
curr->offset,
copy(curr->ptr),
copy(curr->expected),
copy(curr->replacement),
curr->type);
}
Expression* visitAtomicWait(AtomicWait* curr) {
return builder.makeAtomicWait(copy(curr->ptr),
copy(curr->expected),
copy(curr->timeout),
curr->expectedType,
curr->offset);
}
Expression* visitAtomicNotify(AtomicNotify* curr) {
return builder.makeAtomicNotify(
copy(curr->ptr), copy(curr->notifyCount), curr->offset);
}
Expression* visitSIMDExtract(SIMDExtract* curr) {
return builder.makeSIMDExtract(curr->op, copy(curr->vec), curr->index);
}
Expression* visitSIMDReplace(SIMDReplace* curr) {
return builder.makeSIMDReplace(
curr->op, copy(curr->vec), curr->index, copy(curr->value));
}
Expression* visitSIMDShuffle(SIMDShuffle* curr) {
return builder.makeSIMDShuffle(
copy(curr->left), copy(curr->right), curr->mask);
}
Expression* visitSIMDBitselect(SIMDBitselect* curr) {
return builder.makeSIMDBitselect(
copy(curr->left), copy(curr->right), copy(curr->cond));
}
Expression* visitSIMDShift(SIMDShift* curr) {
return builder.makeSIMDShift(
curr->op, copy(curr->vec), copy(curr->shift));
}
Expression* visitConst(Const* curr) {
return builder.makeConst(curr->value);
}
Expression* visitMemoryInit(MemoryInit* curr) {
return builder.makeMemoryInit(
curr->segment, copy(curr->dest), copy(curr->offset), copy(curr->size));
}
Expression* visitDataDrop(DataDrop* curr) {
return builder.makeDataDrop(curr->segment);
}
Expression* visitMemoryCopy(MemoryCopy* curr) {
return builder.makeMemoryCopy(
copy(curr->dest), copy(curr->source), copy(curr->size));
}
Expression* visitMemoryFill(MemoryFill* curr) {
return builder.makeMemoryFill(
copy(curr->dest), copy(curr->value), copy(curr->size));
}
Expression* visitUnary(Unary* curr) {
return builder.makeUnary(curr->op, copy(curr->value));
}
Expression* visitBinary(Binary* curr) {
return builder.makeBinary(curr->op, copy(curr->left), copy(curr->right));
}
Expression* visitSelect(Select* curr) {
return builder.makeSelect(
copy(curr->condition), copy(curr->ifTrue), copy(curr->ifFalse));
}
Expression* visitDrop(Drop* curr) {
return builder.makeDrop(copy(curr->value));
}
Expression* visitReturn(Return* curr) {
return builder.makeReturn(copy(curr->value));
}
Expression* visitHost(Host* curr) {
std::vector<Expression*> operands;
for (Index i = 0; i < curr->operands.size(); i++) {
operands.push_back(copy(curr->operands[i]));
}
auto* ret =
builder.makeHost(curr->op, curr->nameOperand, std::move(operands));
return ret;
}
Expression* visitNop(Nop* curr) { return builder.makeNop(); }
Expression* visitUnreachable(Unreachable* curr) {
return builder.makeUnreachable();
}
Expression* visitPush(Push* curr) {
return builder.makePush(curr->value);
}
Expression* visitPop(Pop* curr) {
return builder.makePop(curr->type);
}
};
Copier copier(wasm, custom);
return copier.copy(original);
}

static ssize_t copy_event_to_user(struct fsnotify_group *group,
struct fanotify_event *event,
char __user *buf, size_t count)
{
struct fanotify_event_metadata metadata;
struct path *path = fanotify_event_path(event);
struct fanotify_info *info = fanotify_event_info(event);
unsigned int info_mode = FAN_GROUP_FLAG(group, FANOTIFY_INFO_MODES);
unsigned int pidfd_mode = info_mode & FAN_REPORT_PIDFD;
struct file *f = NULL;
int ret, pidfd = FAN_NOPIDFD, fd = FAN_NOFD;
pr_debug("%s: group=%p event=%p\n", __func__, group, event);
metadata.event_len = fanotify_event_len(info_mode, event);
metadata.metadata_len = FAN_EVENT_METADATA_LEN;
metadata.vers = FANOTIFY_METADATA_VERSION;
metadata.reserved = 0;
metadata.mask = event->mask & FANOTIFY_OUTGOING_EVENTS;
metadata.pid = pid_vnr(event->pid);
if (FAN_GROUP_FLAG(group, FANOTIFY_UNPRIV) &&
task_tgid(current) != event->pid)
metadata.pid = 0;
if (!FAN_GROUP_FLAG(group, FANOTIFY_UNPRIV) &&
path && path->mnt && path->dentry) {
fd = create_fd(group, path, &f);
if (fd < 0)
return fd;
}
metadata.fd = fd;
if (pidfd_mode) {
WARN_ON_ONCE(FAN_GROUP_FLAG(group, FAN_REPORT_TID));
if (metadata.pid == 0 ||
!pid_has_task(event->pid, PIDTYPE_TGID)) {
pidfd = FAN_NOPIDFD;
} else {
pidfd = pidfd_create(event->pid, 0);
if (pidfd < 0)
pidfd = FAN_EPIDFD;
}
}
ret = -EFAULT;
if (WARN_ON_ONCE(metadata.event_len > count))
goto out_close_fd;
if (copy_to_user(buf, &metadata, FAN_EVENT_METADATA_LEN))
goto out_close_fd;
buf += FAN_EVENT_METADATA_LEN;
count -= FAN_EVENT_METADATA_LEN;
if (fanotify_is_perm_event(event->mask))
FANOTIFY_PERM(event)->fd = fd;
if (f)
fd_install(fd, f);
if (info_mode) {
ret = copy_info_records_to_user(event, info, info_mode, pidfd,
buf, count);
if (ret < 0)
goto out_close_fd;
}
return metadata.event_len;
out_close_fd:
if (fd != FAN_NOFD) {
put_unused_fd(fd);
fput(f);
}
if (pidfd >= 0)
close_fd(pidfd);
return ret;
}

GF_Err adts_dmx_process(GF_Filter *filter)
{
GF_ADTSDmxCtx *ctx = gf_filter_get_udta(filter);
GF_FilterPacket *pck, *dst_pck;
u8 *data, *output;
u8 *start;
u32 pck_size, remain, prev_pck_size;
u64 cts = GF_FILTER_NO_TS;
if (!ctx->duration.num)
adts_dmx_check_dur(filter, ctx);
if (ctx->opid && !ctx->is_playing)
return GF_OK;
pck = gf_filter_pid_get_packet(ctx->ipid);
if (!pck) {
if (gf_filter_pid_is_eos(ctx->ipid)) {
if (!ctx->adts_buffer_size) {
if (ctx->opid)
gf_filter_pid_set_eos(ctx->opid);
if (ctx->src_pck) gf_filter_pck_unref(ctx->src_pck);
ctx->src_pck = NULL;
return GF_EOS;
}
} else {
return GF_OK;
}
}
prev_pck_size = ctx->adts_buffer_size;
if (pck && !ctx->resume_from) {
data = (char *) gf_filter_pck_get_data(pck, &pck_size);
if (!pck_size) {
gf_filter_pid_drop_packet(ctx->ipid);
return GF_OK;
}
if (ctx->byte_offset != GF_FILTER_NO_BO) {
u64 byte_offset = gf_filter_pck_get_byte_offset(pck);
if (!ctx->adts_buffer_size) {
ctx->byte_offset = byte_offset;
} else if (ctx->byte_offset + ctx->adts_buffer_size != byte_offset) {
ctx->byte_offset = GF_FILTER_NO_BO;
if ((byte_offset != GF_FILTER_NO_BO) && (byte_offset>ctx->adts_buffer_size) ) {
ctx->byte_offset = byte_offset - ctx->adts_buffer_size;
}
}
}
if (ctx->adts_buffer_size + pck_size > ctx->adts_buffer_alloc) {
ctx->adts_buffer_alloc = ctx->adts_buffer_size + pck_size;
ctx->adts_buffer = gf_realloc(ctx->adts_buffer, ctx->adts_buffer_alloc);
}
memcpy(ctx->adts_buffer + ctx->adts_buffer_size, data, pck_size);
ctx->adts_buffer_size += pck_size;
}
if (ctx->timescale && pck) {
cts = gf_filter_pck_get_cts(pck);
}
if (cts == GF_FILTER_NO_TS) {
prev_pck_size = 0;
}
remain = ctx->adts_buffer_size;
start = ctx->adts_buffer;
if (ctx->resume_from) {
start += ctx->resume_from - 1;
remain -= ctx->resume_from - 1;
ctx->resume_from = 0;
}
while (remain) {
u8 *sync;
u32 sync_pos, size, offset, bytes_to_drop=0, nb_blocks_per_frame;
if (!ctx->tag_size && (remain>3)) {
if (start[0] == 'I' && start[1] == 'D' && start[2] == '3') {
if (remain<10)
return GF_OK;
ctx->tag_size = ((start[9] & 0x7f) + ((start[8] & 0x7f) << 7) + ((start[7] & 0x7f) << 14) + ((start[6] & 0x7f) << 21));
bytes_to_drop = 10;
if (ctx->id3_buffer_alloc < ctx->tag_size+10) {
ctx->id3_buffer = gf_realloc(ctx->id3_buffer, ctx->tag_size+10);
ctx->id3_buffer_alloc = ctx->tag_size+10;
}
memcpy(ctx->id3_buffer, start, 10);
ctx->id3_buffer_size = 10;
goto drop_byte;
}
}
if (ctx->tag_size) {
if (ctx->tag_size>remain) {
bytes_to_drop = remain;
ctx->tag_size-=remain;
} else {
bytes_to_drop = ctx->tag_size;
ctx->tag_size = 0;
}
memcpy(ctx->id3_buffer + ctx->id3_buffer_size, start, bytes_to_drop);
ctx->id3_buffer_size += bytes_to_drop;
if (!ctx->tag_size && ctx->opid) {
id3dmx_flush(filter, ctx->id3_buffer, ctx->id3_buffer_size, ctx->opid, ctx->expart ? &ctx->vpid : NULL);
ctx->id3_buffer_size = 0;
}
goto drop_byte;
}
sync = memchr(start, 0xFF, remain);
sync_pos = (u32) (sync ? sync - start : remain);
if (remain - sync_pos < 7) {
break;
}
if ((sync[1] & 0xF0) != 0xF0) {
GF_LOG(ctx->nb_frames ? GF_LOG_WARNING : GF_LOG_DEBUG, GF_LOG_PARSER, ("[ADTSDmx] invalid ADTS sync bytes, resyncing\n"));
ctx->nb_frames = 0;
goto drop_byte;
}
if (!ctx->bs) {
ctx->bs = gf_bs_new(sync + 1, remain - sync_pos - 1, GF_BITSTREAM_READ);
} else {
gf_bs_reassign_buffer(ctx->bs, sync + 1, remain - sync_pos - 1);
}
gf_bs_read_int(ctx->bs, 4);
ctx->hdr.is_mp2 = (Bool)gf_bs_read_int(ctx->bs, 1);
ctx->hdr.is_mp2 = 0;
gf_bs_read_int(ctx->bs, 2);
ctx->hdr.no_crc = (Bool)gf_bs_read_int(ctx->bs, 1);
ctx->hdr.profile = 1 + gf_bs_read_int(ctx->bs, 2);
ctx->hdr.sr_idx = gf_bs_read_int(ctx->bs, 4);
gf_bs_read_int(ctx->bs, 1);
ctx->hdr.nb_ch = gf_bs_read_int(ctx->bs, 3);
gf_bs_read_int(ctx->bs, 4);
ctx->hdr.frame_size = gf_bs_read_int(ctx->bs, 13);
gf_bs_read_int(ctx->bs, 11);
nb_blocks_per_frame = gf_bs_read_int(ctx->bs, 2);
ctx->hdr.hdr_size = 7;
if (!ctx->hdr.no_crc) {
u32 skip;
if (!nb_blocks_per_frame) {
skip = 2;
} else {
skip = 2 + 2*nb_blocks_per_frame; }
ctx->hdr.hdr_size += skip;
gf_bs_skip_bytes(ctx->bs, skip);
}
if (!ctx->hdr.frame_size || !GF_M4ASampleRates[ctx->hdr.sr_idx]) {
GF_LOG(GF_LOG_DEBUG, GF_LOG_PARSER, ("[ADTSDmx] Invalid ADTS frame header, resyncing\n"));
ctx->nb_frames = 0;
goto drop_byte;
}
if ((nb_blocks_per_frame>2) || (nb_blocks_per_frame && ctx->hdr.nb_ch)) {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[ADTSDmx] Unsupported multi-block ADTS frame header - patch welcome\n"));
ctx->nb_frames = 0;
goto drop_byte;
} else if (!nb_blocks_per_frame) {
if (ctx->aacchcfg<0)
ctx->hdr.nb_ch = -ctx->aacchcfg;
else if (!ctx->hdr.nb_ch)
ctx->hdr.nb_ch = ctx->aacchcfg;
if (!ctx->hdr.nb_ch) {
GF_LOG(GF_LOG_WARNING, GF_LOG_PARSER, ("[ADTSDmx] Missing channel configuration in ADTS frame header, defaulting to stereo - use `--aacchcfg` to force config\n"));
ctx->hdr.nb_ch = ctx->aacchcfg = 2;
}
}
if (nb_blocks_per_frame==2) {
u32 pos = (u32) gf_bs_get_position(ctx->bs);
gf_m4a_parse_program_config_element(ctx->bs, &ctx->acfg);
if (!ctx->hdr.no_crc)
gf_bs_skip_bytes(ctx->bs, 2);  
ctx->hdr.hdr_size += (u32) gf_bs_get_position(ctx->bs) - pos;
}
if (ctx->hdr.nb_ch==7)
ctx->hdr.nb_ch = 8;
if (ctx->hdr.frame_size + 1 < remain) {
u32 next_frame = ctx->hdr.frame_size;
if ((sync[next_frame] !=0xFF) || ((sync[next_frame+1] & 0xF0) !=0xF0) ) {
GF_LOG(ctx->nb_frames ? GF_LOG_WARNING : GF_LOG_DEBUG, GF_LOG_PARSER, ("[ADTSDmx] invalid next ADTS frame sync, resyncing\n"));
ctx->nb_frames = 0;
goto drop_byte;
}
}
else if (pck) {
if (ctx->timescale && !prev_pck_size &&  (cts != GF_FILTER_NO_TS) ) {
ctx->cts = cts;
}
break;
}
adts_dmx_check_pid(filter, ctx);
if (!ctx->is_playing) {
ctx->resume_from = 1 + ctx->adts_buffer_size - remain;
return GF_OK;
}
ctx->nb_frames++;
size = ctx->hdr.frame_size - ctx->hdr.hdr_size;
offset = ctx->hdr.hdr_size;
if ((nb_blocks_per_frame==2) && !ctx->hdr.no_crc)
size -= 2;
if (ctx->in_seek) {
u64 nb_samples_at_seek = (u64) (ctx->start_range * GF_M4ASampleRates[ctx->sr_idx]);
if (ctx->cts + ctx->dts_inc >= nb_samples_at_seek) {
ctx->in_seek = GF_FALSE;
}
}
bytes_to_drop = ctx->hdr.frame_size;
if (ctx->timescale && !prev_pck_size &&  (cts != GF_FILTER_NO_TS) ) {
ctx->cts = cts;
cts = GF_FILTER_NO_TS;
}
if (!ctx->in_seek) {
dst_pck = gf_filter_pck_new_alloc(ctx->opid, size, &output);
if (ctx->src_pck) gf_filter_pck_merge_properties(ctx->src_pck, dst_pck);
memcpy(output, sync + offset, size);
gf_filter_pck_set_dts(dst_pck, ctx->cts);
gf_filter_pck_set_cts(dst_pck, ctx->cts);
gf_filter_pck_set_duration(dst_pck, ctx->dts_inc);
gf_filter_pck_set_framing(dst_pck, GF_TRUE, GF_TRUE);
gf_filter_pck_set_sap(dst_pck, GF_FILTER_SAP_1);
if (ctx->byte_offset != GF_FILTER_NO_BO) {
gf_filter_pck_set_byte_offset(dst_pck, ctx->byte_offset + ctx->hdr.hdr_size);
}
gf_filter_pck_send(dst_pck);
}
adts_dmx_update_cts(ctx);
if (bytes_to_drop>remain) {
GF_LOG(GF_LOG_WARNING, GF_LOG_PARSER, ("[ADTSDmx] truncated ADTS frame!\n"));
bytes_to_drop=remain;
}
drop_byte:
if (!bytes_to_drop) {
bytes_to_drop = 1;
}
start += bytes_to_drop;
remain -= bytes_to_drop;
if (prev_pck_size) {
if (prev_pck_size > bytes_to_drop) prev_pck_size -= bytes_to_drop;
else {
prev_pck_size=0;
if (ctx->src_pck) gf_filter_pck_unref(ctx->src_pck);
ctx->src_pck = pck;
if (pck)
gf_filter_pck_ref_props(&ctx->src_pck);
}
}
if (ctx->byte_offset != GF_FILTER_NO_BO)
ctx->byte_offset += bytes_to_drop;
}
if (!pck) {
ctx->adts_buffer_size = 0;
return adts_dmx_process(filter);
} else {
if (remain) {
memmove(ctx->adts_buffer, start, remain);
}
ctx->adts_buffer_size = remain;
gf_filter_pid_drop_packet(ctx->ipid);
}
return GF_OK;
}

static uint8_t
yaffsfs_istat(TSK_FS_INFO *fs, TSK_FS_ISTAT_FLAG_ENUM flags, FILE * hFile, TSK_INUM_T inum,
TSK_DADDR_T numblock, int32_t sec_skew)
{
TSK_FS_META *fs_meta;
TSK_FS_FILE *fs_file;
YAFFSFS_INFO *yfs = (YAFFSFS_INFO *)fs;
char ls[12];
YAFFSFS_PRINT_ADDR print;
char timeBuf[32];
YaffsCacheObject * obj = NULL;
YaffsCacheVersion * version = NULL;
YaffsHeader * header = NULL;
yaffscache_version_find_by_inode(yfs, inum, &version, &obj);
if ((fs_file = tsk_fs_file_open_meta(fs, NULL, inum)) == NULL) {
return 1;
}
fs_meta = fs_file->meta;
tsk_fprintf(hFile, "inode: %" PRIuINUM "\n", inum);
tsk_fprintf(hFile, "%sAllocated\n",
(fs_meta->flags & TSK_FS_META_FLAG_ALLOC) ? "" : "Not ");
if (fs_meta->link)
tsk_fprintf(hFile, "symbolic link to: %s\n", fs_meta->link);
tsk_fprintf(hFile, "uid / gid: %" PRIuUID " / %" PRIuGID "\n",
fs_meta->uid, fs_meta->gid);
tsk_fs_meta_make_ls(fs_meta, ls, sizeof(ls));
tsk_fprintf(hFile, "mode: %s\n", ls);
tsk_fprintf(hFile, "size: %" PRIdOFF "\n", fs_meta->size);
tsk_fprintf(hFile, "num of links: %d\n", fs_meta->nlink);
if(version != NULL){
yaffsfs_read_header(yfs, &header, version->ycv_header_chunk->ycc_offset);
if(header != NULL){
tsk_fprintf(hFile, "Name: %s\n", header->name);
}
}
if (sec_skew != 0) {
tsk_fprintf(hFile, "\nAdjusted Inode Times:\n");
fs_meta->mtime -= sec_skew;
fs_meta->atime -= sec_skew;
fs_meta->ctime -= sec_skew;
tsk_fprintf(hFile, "Accessed:\t%s\n",
tsk_fs_time_to_str(fs_meta->atime, timeBuf));
tsk_fprintf(hFile, "File Modified:\t%s\n",
tsk_fs_time_to_str(fs_meta->mtime, timeBuf));
tsk_fprintf(hFile, "Inode Modified:\t%s\n",
tsk_fs_time_to_str(fs_meta->ctime, timeBuf));
fs_meta->mtime += sec_skew;
fs_meta->atime += sec_skew;
fs_meta->ctime += sec_skew;
tsk_fprintf(hFile, "\nOriginal Inode Times:\n");
}
else {
tsk_fprintf(hFile, "\nInode Times:\n");
}
tsk_fprintf(hFile, "Accessed:\t%s\n",
tsk_fs_time_to_str(fs_meta->atime, timeBuf));
tsk_fprintf(hFile, "File Modified:\t%s\n",
tsk_fs_time_to_str(fs_meta->mtime, timeBuf));
tsk_fprintf(hFile, "Inode Modified:\t%s\n",
tsk_fs_time_to_str(fs_meta->ctime, timeBuf));
if(version != NULL){
tsk_fprintf(hFile, "\nHeader Chunk:\n");
tsk_fprintf(hFile, "%" PRIuDADDR "\n", (version->ycv_header_chunk->ycc_offset / (yfs->page_size + yfs->spare_size)));
}
if (numblock > 0) {
TSK_OFF_T lower_size = numblock * fs->block_size;
fs_meta->size = (lower_size < fs_meta->size)?(lower_size):(fs_meta->size);
}
tsk_fprintf(hFile, "\nData Chunks:\n");
if (flags & TSK_FS_ISTAT_RUNLIST){
const TSK_FS_ATTR *fs_attr_default =
tsk_fs_file_attr_get_type(fs_file,
TSK_FS_ATTR_TYPE_DEFAULT, 0, 0);
if (fs_attr_default && (fs_attr_default->flags & TSK_FS_ATTR_NONRES)) {
if (tsk_fs_attr_print(fs_attr_default, hFile)) {
tsk_fprintf(hFile, "\nError creating run lists  ");
tsk_error_print(hFile);
tsk_error_reset();
}
}
}
else {
print.idx = 0;
print.hFile = hFile;
if (tsk_fs_file_walk(fs_file, TSK_FS_FILE_WALK_FLAG_AONLY,
(TSK_FS_FILE_WALK_CB)print_addr_act, (void *)&print)) {
tsk_fprintf(hFile, "\nError reading file:  ");
tsk_error_print(hFile);
tsk_error_reset();
}
else if (print.idx != 0) {
tsk_fprintf(hFile, "\n");
}
}
tsk_fs_file_close(fs_file);
return 0;
}

static inline std::system_error
FormatLastError(DWORD code, const char *fmt, Args&&... args) noexcept
{
char buffer[512];
const auto end = buffer + sizeof(buffer);
size_t length = snprintf(buffer, sizeof(buffer) - 128,
fmt, std::forward<Args>(args)...);
char *p = buffer + length;
*p++ = ':';
*p++ = ' ';
FormatMessageA(FORMAT_MESSAGE_FROM_SYSTEM |
FORMAT_MESSAGE_IGNORE_INSERTS,
nullptr, code, 0, p, end - p, nullptr);
return MakeLastError(code, buffer);
}

struct r_bin_dyldcache_lib_t *r_bin_dyldcache_extract(struct r_bin_dyldcache_obj_t* bin, int idx, int *nlib) {
ut64 liboff, linkedit_offset;
ut64 dyld_vmbase;
ut32 addend = 0;
struct r_bin_dyldcache_lib_t *ret = NULL;
struct dyld_cache_image_info* image_infos = NULL;
struct mach_header *mh;
ut8 *data, *cmdptr;
int cmd, libsz = 0;
RBuffer* dbuf;
char *libname;
if (!bin) {
return NULL;
}
if (bin->size < 1) {
eprintf ("Empty file? (%s)\n", bin->file? bin->file: "(null)");
return NULL;
}
if (bin->nlibs < 0 || idx < 0 || idx >= bin->nlibs) {
return NULL;
}
*nlib = bin->nlibs;
ret = R_NEW0 (struct r_bin_dyldcache_lib_t);
if (!ret) {
perror ("malloc (ret)");
return NULL;
}
if (bin->hdr.startaddr > bin->size) {
eprintf ("corrupted dyldcache");
free (ret);
return NULL;
}
if (bin->hdr.startaddr > bin->size || bin->hdr.baseaddroff > bin->size) {
eprintf ("corrupted dyldcache");
free (ret);
return NULL;
}
image_infos = (struct dyld_cache_image_info*) (bin->b->buf + bin->hdr.startaddr);
dyld_vmbase = *(ut64 *)(bin->b->buf + bin->hdr.baseaddroff);
liboff = image_infos[idx].address - dyld_vmbase;
if (liboff > bin->size) {
eprintf ("Corrupted file\n");
free (ret);
return NULL;
}
ret->offset = liboff;
if (image_infos[idx].pathFileOffset > bin->size) {
eprintf ("corrupted file\n");
free (ret);
return NULL;
}
libname = (char *)(bin->b->buf + image_infos[idx].pathFileOffset);
data = bin->b->buf + liboff;
mh = (struct mach_header *)data;
if (mh->magic != MH_MAGIC && mh->magic != MH_MAGIC_64) {
if (mh->magic == 0xbebafeca) { eprintf ("FAT Binary\n");
}
eprintf ("Not mach-o\n");
free (ret);
return NULL;
}
if (!(dbuf = r_buf_new ())) {
eprintf ("new (dbuf)\n");
free (ret);
return NULL;
}
addend = mh->magic == MH_MAGIC? sizeof (struct mach_header) : sizeof (struct mach_header_64);
r_buf_set_bytes (dbuf, data, addend);
cmdptr = data + addend;
for (cmd = 0; cmd < mh->ncmds; cmd++) {
struct load_command *lc = (struct load_command *)cmdptr;
r_buf_append_bytes (dbuf, (ut8*)lc, lc->cmdsize);
cmdptr += lc->cmdsize;
}
cmdptr = data + addend;
for (cmd = linkedit_offset = 0; cmd < mh->ncmds; cmd++) {
struct load_command *lc = (struct load_command *)cmdptr;
cmdptr += lc->cmdsize;
switch (lc->cmd) {
case LC_SEGMENT:
{
struct segment_command *seg = (struct segment_command *)lc;
int t = seg->filesize;
if (seg->fileoff + seg->filesize > bin->size || seg->fileoff > bin->size) {
eprintf ("malformed dyldcache\n");
free (ret);
r_buf_free (dbuf);
return NULL;
}
r_buf_append_bytes (dbuf, bin->b->buf+seg->fileoff, t);
r_bin_dyldcache_apply_patch (dbuf, dbuf->length, (ut64)((size_t)&seg->fileoff - (size_t)data));
int sect_offset = seg->fileoff - libsz;
libsz = dbuf->length;
if (!strcmp (seg->segname, "__LINKEDIT")) {
linkedit_offset = sect_offset;
}
if (seg->nsects > 0) {
struct section *sects = (struct section *)((ut8 *)seg + sizeof(struct segment_command));
int nsect;
for (nsect = 0; nsect < seg->nsects; nsect++) {
if (sects[nsect].offset > libsz) {
r_bin_dyldcache_apply_patch (dbuf, sects[nsect].offset - sect_offset,
(ut64)((size_t)&sects[nsect].offset - (size_t)data));
}
}
}
}
break;
case LC_SYMTAB:
{
struct symtab_command *st = (struct symtab_command *)lc;
NZ_OFFSET (st->symoff);
NZ_OFFSET (st->stroff);
}
break;
case LC_DYSYMTAB:
{
struct dysymtab_command *st = (struct dysymtab_command *)lc;
NZ_OFFSET (st->tocoff);
NZ_OFFSET (st->modtaboff);
NZ_OFFSET (st->extrefsymoff);
NZ_OFFSET (st->indirectsymoff);
NZ_OFFSET (st->extreloff);
NZ_OFFSET (st->locreloff);
}
break;
case LC_DYLD_INFO:
case LC_DYLD_INFO_ONLY:
{
struct dyld_info_command *st = (struct dyld_info_command *)lc;
NZ_OFFSET (st->rebase_off);
NZ_OFFSET (st->bind_off);
NZ_OFFSET (st->weak_bind_off);
NZ_OFFSET (st->lazy_bind_off);
NZ_OFFSET (st->export_off);
}
break;
}
}
ret->b = dbuf;
strncpy (ret->path, libname, sizeof (ret->path) - 1);
ret->size = libsz;
return ret;
}

static int f2fs_move_inline_dirents(struct inode *dir, struct page *ipage,
struct f2fs_inline_dentry *inline_dentry)
{
struct page *page;
struct dnode_of_data dn;
struct f2fs_dentry_block *dentry_blk;
int err;
page = grab_cache_page(dir->i_mapping, 0);
if (!page) {
f2fs_put_page(ipage, 1);
return -ENOMEM;
}
set_new_dnode(&dn, dir, ipage, NULL, 0);
err = f2fs_reserve_block(&dn, 0);
if (err)
goto out;
f2fs_wait_on_page_writeback(page, DATA);
zero_user_segment(page, MAX_INLINE_DATA, PAGE_CACHE_SIZE);
dentry_blk = kmap_atomic(page);
memcpy(dentry_blk->dentry_bitmap, inline_dentry->dentry_bitmap,
INLINE_DENTRY_BITMAP_SIZE);
memset(dentry_blk->dentry_bitmap + INLINE_DENTRY_BITMAP_SIZE, 0,
SIZE_OF_DENTRY_BITMAP - INLINE_DENTRY_BITMAP_SIZE);
memcpy(dentry_blk->dentry, inline_dentry->dentry,
sizeof(struct f2fs_dir_entry) * NR_INLINE_DENTRY);
memcpy(dentry_blk->filename, inline_dentry->filename,
NR_INLINE_DENTRY * F2FS_SLOT_LEN);
kunmap_atomic(dentry_blk);
SetPageUptodate(page);
set_page_dirty(page);
truncate_inline_inode(ipage, 0);
stat_dec_inline_dir(dir);
clear_inode_flag(F2FS_I(dir), FI_INLINE_DENTRY);
if (i_size_read(dir) < PAGE_CACHE_SIZE) {
i_size_write(dir, PAGE_CACHE_SIZE);
set_inode_flag(F2FS_I(dir), FI_UPDATE_DIR);
}
sync_inode_page(&dn);
out:
f2fs_put_page(page, 1);
return err;
}

