static int decodeAACfile(char *aacfile, char *sndfile, char *adts_fn, int to_stdout,
int def_srate, int object_type, int outputFormat, int fileType,
int downMatrix, int infoOnly, int adts_out, int old_format,
float *song_length)
{
int tagsize;
unsigned long samplerate;
unsigned char channels;
void *sample_buffer;
audio_file *aufile = NULL;
FILE *adtsFile = NULL;
unsigned char *adtsData;
int adtsDataSize;
NeAACDecHandle hDecoder;
NeAACDecFrameInfo frameInfo;
NeAACDecConfigurationPtr config;
char percents[MAX_PERCENTS];
int percent, old_percent = -1;
int bread, fileread;
int header_type = 0;
int bitrate = 0;
float length = 0;
int first_time = 1;
int retval;
int streaminput = 0;
aac_buffer b;
memset(&b, 0, sizeof(aac_buffer));
if (adts_out)
{
adtsFile = faad_fopen(adts_fn, "wb");
if (adtsFile == NULL)
{
faad_fprintf(stderr, "Error opening file: %s\n", adts_fn);
return 1;
}
}
if (0 == strcmp(aacfile, "-"))
{
b.infile = stdin;
#ifdef _WIN32
_setmode(_fileno(stdin), O_BINARY);
#endif
}
else
{
b.infile = faad_fopen(aacfile, "rb");
if (b.infile == NULL)
{
faad_fprintf(stderr, "Error opening file: %s\n", aacfile);
return 1;
}
}
retval = fseek(b.infile, 0, SEEK_END);
#ifdef _WIN32
if (0 == strcmp(aacfile, "-")) {
retval = -1;
}
#endif
if (retval )
{
faad_fprintf(stderr, "Input not seekable %s\n", aacfile);
fileread = -1;
streaminput = 1;
} else {
fileread = ftell(b.infile);
fseek(b.infile, 0, SEEK_SET);
};
if (!(b.buffer = (unsigned char*)malloc(FAAD_MIN_STREAMSIZE*MAX_CHANNELS)))
{
faad_fprintf(stderr, "Memory allocation error\n");
return 0;
}
memset(b.buffer, 0, FAAD_MIN_STREAMSIZE*MAX_CHANNELS);
bread = fread(b.buffer, 1, FAAD_MIN_STREAMSIZE*MAX_CHANNELS, b.infile);
b.bytes_into_buffer = bread;
b.bytes_consumed = 0;
b.file_offset = 0;
if (bread != FAAD_MIN_STREAMSIZE*MAX_CHANNELS)
b.at_eof = 1;
tagsize = 0;
if (!memcmp(b.buffer, "ID3", 3))
{
tagsize = (b.buffer[6] << 21) | (b.buffer[7] << 14) |
(b.buffer[8] <<  7) | (b.buffer[9] <<  0);
tagsize += 10;
advance_buffer(&b, tagsize);
fill_buffer(&b);
}
hDecoder = NeAACDecOpen();
config = NeAACDecGetCurrentConfiguration(hDecoder);
if (def_srate)
config->defSampleRate = def_srate;
config->defObjectType = object_type;
config->outputFormat = outputFormat;
config->downMatrix = downMatrix;
config->useOldADTSFormat = old_format;
NeAACDecSetConfiguration(hDecoder, config);
header_type = 0;
if (streaminput == 1)
lookforheader(&b);
if ((b.buffer[0] == 0xFF) && ((b.buffer[1] & 0xF6) == 0xF0))
{
if (streaminput == 1)
{
int  frame_length;
int samplerate;
float frames_per_sec, bytes_per_frame;
channels = 2;
samplerate = adts_sample_rates[(b.buffer[2]&0x3c)>>2];
frame_length = ((((unsigned int)b.buffer[3] & 0x3)) << 11)
| (((unsigned int)b.buffer[4]) << 3) | (b.buffer[5] >> 5);
frames_per_sec = (float)samplerate/1024.0f;
bytes_per_frame = (float)frame_length/(float)(1000);
bitrate = (int)(8. * bytes_per_frame * frames_per_sec + 0.5);
length = 1;
faad_fprintf(stderr, "Streamed input format  samplerate %d channels %d.\n", samplerate, channels);
} else {
adts_parse(&b, &bitrate, &length);
fseek(b.infile, tagsize, SEEK_SET);
bread = fread(b.buffer, 1, FAAD_MIN_STREAMSIZE*MAX_CHANNELS, b.infile);
if (bread != FAAD_MIN_STREAMSIZE*MAX_CHANNELS)
b.at_eof = 1;
else
b.at_eof = 0;
b.bytes_into_buffer = bread;
b.bytes_consumed = 0;
b.file_offset = tagsize;
}
header_type = 1;
}
else if (memcmp(b.buffer, "ADIF", 4) == 0)
{
int skip_size = (b.buffer[4] & 0x80) ? 9 : 0;
bitrate = ((unsigned int)(b.buffer[4 + skip_size] & 0x0F)<<19) |
((unsigned int)b.buffer[5 + skip_size]<<11) |
((unsigned int)b.buffer[6 + skip_size]<<3) |
((unsigned int)b.buffer[7 + skip_size] & 0xE0);
length = (float)fileread;
if (length != 0)
{
length = ((float)length*8.f)/((float)bitrate) + 0.5f;
}
bitrate = (int)((float)bitrate/1000.0f + 0.5f);
header_type = 2;
}
*song_length = length;
fill_buffer(&b);
if ((bread = NeAACDecInit(hDecoder, b.buffer,
b.bytes_into_buffer, &samplerate, &channels)) < 0)
{
faad_fprintf(stderr, "Error initializing decoder library.\n");
if (b.buffer)
free(b.buffer);
NeAACDecClose(hDecoder);
if (b.infile != stdin)
fclose(b.infile);
return 1;
}
advance_buffer(&b, bread);
fill_buffer(&b);
faad_fprintf(stderr, "%s file info:\n", aacfile);
switch (header_type)
{
case 0:
faad_fprintf(stderr, "RAW\n\n");
break;
case 1:
faad_fprintf(stderr, "ADTS, %.3f sec, %d kbps, %d Hz\n\n",
length, bitrate, samplerate);
break;
case 2:
faad_fprintf(stderr, "ADIF, %.3f sec, %d kbps, %d Hz\n\n",
length, bitrate, samplerate);
break;
}
if (infoOnly)
{
NeAACDecClose(hDecoder);
if (b.infile != stdin)
fclose(b.infile);
if (b.buffer)
free(b.buffer);
return 0;
}
do
{
sample_buffer = NeAACDecDecode(hDecoder, &frameInfo,
b.buffer, b.bytes_into_buffer);
if (adts_out == 1)
{
int skip = (old_format) ? 8 : 7;
adtsData = MakeAdtsHeader(&adtsDataSize, &frameInfo, old_format);
fwrite(adtsData, 1, adtsDataSize, adtsFile);
if (frameInfo.header_type == ADTS)
fwrite(b.buffer + skip, 1, frameInfo.bytesconsumed - skip, adtsFile);
else
fwrite(b.buffer, 1, frameInfo.bytesconsumed, adtsFile);
}
advance_buffer(&b, frameInfo.bytesconsumed);
if (frameInfo.error > 0)
{
faad_fprintf(stderr, "Error: %s\n",
NeAACDecGetErrorMessage(frameInfo.error));
}
if (first_time && !frameInfo.error)
{
print_channel_info(&frameInfo);
if (!adts_out)
{
if (!to_stdout)
{
aufile = open_audio_file(sndfile, frameInfo.samplerate, frameInfo.channels,
outputFormat, fileType, aacChannelConfig2wavexChannelMask(&frameInfo));
} else {
aufile = open_audio_file("-", frameInfo.samplerate, frameInfo.channels,
outputFormat, fileType, aacChannelConfig2wavexChannelMask(&frameInfo));
}
if (aufile == NULL)
{
if (b.buffer)
free(b.buffer);
NeAACDecClose(hDecoder);
if (b.infile != stdin)
fclose(b.infile);
return 0;
}
} else {
faad_fprintf(stderr, "Writing output MPEG-4 AAC ADTS file.\n\n");
}
first_time = 0;
}
percent = min((int)(b.file_offset*100)/fileread, 100);
if (percent > old_percent)
{
old_percent = percent;
snprintf(percents, MAX_PERCENTS, "%d%% decoding %s.", percent, aacfile);
faad_fprintf(stderr, "%s\r", percents);
#ifdef _WIN32
SetConsoleTitle(percents);
#endif
}
if ((frameInfo.error == 0) && (frameInfo.samples > 0) && (!adts_out))
{
if (write_audio_file(aufile, sample_buffer, frameInfo.samples, 0) == 0)
break;
}
fill_buffer(&b);
if (b.bytes_into_buffer == 0)
sample_buffer = NULL; 
} while (sample_buffer != NULL);
NeAACDecClose(hDecoder);
if (adts_out == 1)
{
fclose(adtsFile);
}
if (b.infile != stdin)
fclose(b.infile);
if (!first_time && !adts_out)
close_audio_file(aufile);
if (b.buffer)
free(b.buffer);
return frameInfo.error;
}

static Image *ReadPESImage(const ImageInfo *image_info,ExceptionInfo *exception)
{
char
filename[MagickPathExtent];
FILE
*file;
Image
*image;
ImageInfo
*read_info;
int
delta_x,
delta_y,
j,
unique_file,
x,
y;
MagickBooleanType
status;
PESBlockInfo
blocks[256];
PointInfo
*stitches;
SegmentInfo
bounds;
register ssize_t
i;
size_t
number_blocks,
number_colors,
number_stitches;
ssize_t
count,
offset;
unsigned char
magick[4],
version[4];
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickCoreSignature);
if (image_info->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
image_info->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
image=AcquireImage(image_info,exception);
status=OpenBlob(image_info,image,ReadBinaryBlobMode,exception);
if (status == MagickFalse)
{
image=DestroyImageList(image);
return((Image *) NULL);
}
count=ReadBlob(image,4,magick);
if ((count != 4) || (LocaleNCompare((char *) magick,"#PES",4) != 0))
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
count=ReadBlob(image,4,version);
offset=ReadBlobLSBSignedLong(image);
if (DiscardBlobBytes(image,offset+36) == MagickFalse)
ThrowFileException(exception,CorruptImageError,"UnexpectedEndOfFile",
image->filename);
if (EOFBlob(image) != MagickFalse)
ThrowReaderException(CorruptImageError,"UnexpectedEndOfFile");
number_colors=(size_t) ReadBlobByte(image)+1;
for (i=0; i < (ssize_t) number_colors; i++)
{
j=ReadBlobByte(image);
blocks[i].color=PESColor+(j < 0 ? 0 : j);
blocks[i].offset=0;
}
for ( ; i < 256L; i++)
{
blocks[i].offset=0;
blocks[i].color=PESColor;
}
if (DiscardBlobBytes(image,532L-number_colors-21) == MagickFalse)
ThrowFileException(exception,CorruptImageError,"UnexpectedEndOfFile",
image->filename);
if (EOFBlob(image) != MagickFalse)
ThrowReaderException(CorruptImageError,"UnexpectedEndOfFile");
number_stitches=64;
stitches=(PointInfo *) AcquireQuantumMemory(number_stitches,
sizeof(*stitches));
if (stitches == (PointInfo *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
bounds.x1=65535.0;
bounds.y1=65535.0;
bounds.x2=(-65535.0);
bounds.y2=(-65535.0);
i=0;
j=0;
delta_x=0;
delta_y=0;
while (EOFBlob(image) != EOF)
{
x=ReadBlobByte(image);
y=ReadBlobByte(image);
if ((x == 0xff) && (y == 0))
break;
if ((x == 254) && (y == 176))
{
j++;
blocks[j].offset=(ssize_t) i;
if (j >= 256)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
(void) ReadBlobByte(image);
continue;
}
if ((x & 0x80) == 0)
{
if ((x & 0x40) != 0)
x-=0x80;
}
else
{
x=((x & 0x0f) << 8)+y;
if ((x & 0x800) != 0)
x-=0x1000;
y=ReadBlobByte(image);
}
if ((y & 0x80) == 0)
{
if ((y & 0x40) != 0)
y-=0x80;
}
else
{
y=((y & 0x0f) << 8)+ReadBlobByte(image);
if ((y & 0x800) != 0)
y-=0x1000;
}
x+=delta_x;
y+=delta_y;
delta_x=x;
delta_y=y;
stitches[i].x=(double) x;
stitches[i].y=(double) y;
if ((double) x < bounds.x1)
bounds.x1=(double) x;
if ((double) x > bounds.x2)
bounds.x2=(double) x;
if ((double) y < bounds.y1)
bounds.y1=(double) y;
if ((double) y > bounds.y2)
bounds.y2=(double) y;
i++;
if (i >= (ssize_t) number_stitches)
{
number_stitches<<=1;
stitches=(PointInfo *)  ResizeQuantumMemory(stitches,(size_t)
number_stitches,sizeof(*stitches));
if (stitches == (PointInfo *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
}
}
j++;
blocks[j].offset=(ssize_t) i;
number_blocks=(size_t) j;
file=(FILE *) NULL;
unique_file=AcquireUniqueFileResource(filename);
if (unique_file != -1)
file=fdopen(unique_file,"wb");
if ((unique_file == -1) || (file == (FILE *) NULL))
ThrowImageException(FileOpenError,"UnableToCreateTemporaryFile");
(void) FormatLocaleFile(file,"<?xml version=\"1.0\"?>\n");
(void) FormatLocaleFile(file,"<svg xmlns=\"http:    "xlink=\"http:    "ev=\"http:    "baseProfile=\"full\" width=\"%g\" height=\"%g\">\n",bounds.x2-bounds.x1,
bounds.y2-bounds.y1);
for (i=0; i < (ssize_t) number_blocks; i++)
{
offset=blocks[i].offset;
(void) FormatLocaleFile(file,"  <path stroke=\"#%02x%02x%02x\" "
"fill=\"none\" d=\"M %g %g",blocks[i].color->red,blocks[i].color->green,
blocks[i].color->blue,stitches[offset].x-bounds.x1,
stitches[offset].y-bounds.y1);
for (j=1; j < (ssize_t) (blocks[i+1].offset-offset); j++)
(void) FormatLocaleFile(file," L %g %g",stitches[offset+j].x-bounds.x1,
stitches[offset+j].y-bounds.y1);
(void) FormatLocaleFile(file,"\"/>\n");
}
(void) FormatLocaleFile(file,"</svg>\n");
(void) fclose(file);
(void) CloseBlob(image);
image=DestroyImage(image);
read_info=CloneImageInfo(image_info);
SetImageInfoBlob(read_info,(void *) NULL,0);
(void) FormatLocaleString(read_info->filename,MagickPathExtent,"svg:%s",
filename);
image=ReadImage(read_info,exception);
if (image != (Image *) NULL)
{
(void) CopyMagickString(image->filename,image_info->filename,
MagickPathExtent);
(void) CopyMagickString(image->magick_filename,image_info->filename,
MagickPathExtent);
(void) CopyMagickString(image->magick,"PES",MagickPathExtent);
}
read_info=DestroyImageInfo(read_info);
(void) RelinquishUniqueFileResource(filename);
return(GetFirstImageInList(image));
}

