p->peak_pos = 0;
p->win = new_aubio_window ("hanningz", bufsize);
p->weight = new_fvec (bufsize / 2 + 1);
for (i = 0; i < p->weight->length; i++) {
freq = (smpl_t) i / (smpl_t) bufsize *(smpl_t) samplerate;
while (freq > freqs[j]) {
j += 1;
}
a0 = weight[j - 1];
f0 = freqs[j - 1];
a1 = weight[j];
f1 = freqs[j];
if (f0 == f1) {                 p->weight->data[i] = a0;
} else if (f0 == 0) {           p->weight->data[i] = (a1 - a0) / f1 * freq + a0;
} else {
p->weight->data[i] = (a1 - a0) / (f1 - f0) * freq +
(a0 - (a1 - a0) / (f1 / f0 - 1.));
}
while (freq > freqs[j]) {
j += 1;
}
p->weight->data[i] = DB2LIN (p->weight->data[i]);
}
p->short_period = (uint_t)ROUND(samplerate / 1300.);
return p;
beach:
if (p->winput) del_fvec(p->winput);
AUBIO_FREE(p);
return NULL;
}

