MagickExport Image *ComplexImages(const Image *images,const ComplexOperator op,
ExceptionInfo *exception)
{
#define ComplexImageTag  "Complex/Image"
CacheView
*Ai_view,
*Ar_view,
*Bi_view,
*Br_view,
*Ci_view,
*Cr_view;
const char
*artifact;
const Image
*Ai_image,
*Ar_image,
*Bi_image,
*Br_image;
double
snr;
Image
*Ci_image,
*complex_images,
*Cr_image,
*image;
MagickBooleanType
status;
MagickOffsetType
progress;
ssize_t
y;
assert(images != (Image *) NULL);
assert(images->signature == MagickCoreSignature);
if (images->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",images->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
if (images->next == (Image *) NULL)
{
(void) ThrowMagickException(exception,GetMagickModule(),ImageError,
"ImageSequenceRequired","`%s'",images->filename);
return((Image *) NULL);
}
image=CloneImage(images,0,0,MagickTrue,exception);
if (image == (Image *) NULL)
return((Image *) NULL);
if (SetImageStorageClass(image,DirectClass,exception) == MagickFalse)
{
image=DestroyImageList(image);
return(image);
}
image->depth=32UL;
complex_images=NewImageList();
AppendImageToList(&complex_images,image);
image=CloneImage(images,0,0,MagickTrue,exception);
if (image == (Image *) NULL)
{
complex_images=DestroyImageList(complex_images);
return(complex_images);
}
AppendImageToList(&complex_images,image);
artifact=GetImageArtifact(image,"complex:snr");
snr=0.0;
if (artifact != (const char *) NULL)
snr=StringToDouble(artifact,(char **) NULL);
Ar_image=images;
Ai_image=images->next;
Br_image=images;
Bi_image=images->next;
if ((images->next->next != (Image *) NULL) &&
(images->next->next->next != (Image *) NULL))
{
Br_image=images->next->next;
Bi_image=images->next->next->next;
}
Cr_image=complex_images;
Ci_image=complex_images->next;
Ar_view=AcquireVirtualCacheView(Ar_image,exception);
Ai_view=AcquireVirtualCacheView(Ai_image,exception);
Br_view=AcquireVirtualCacheView(Br_image,exception);
Bi_view=AcquireVirtualCacheView(Bi_image,exception);
Cr_view=AcquireAuthenticCacheView(Cr_image,exception);
Ci_view=AcquireAuthenticCacheView(Ci_image,exception);
status=MagickTrue;
progress=0;
#if defined(MAGICKCORE_OPENMP_SUPPORT)
#pragma omp parallel for schedule(static) shared(progress,status) \
magick_number_threads(images,complex_images,images->rows,1L)
#endif
for (y=0; y < (ssize_t) images->rows; y++)
{
register const Quantum
*magick_restrict Ai,
*magick_restrict Ar,
*magick_restrict Bi,
*magick_restrict Br;
register Quantum
*magick_restrict Ci,
*magick_restrict Cr;
register ssize_t
x;
if (status == MagickFalse)
continue;
Ar=GetCacheViewVirtualPixels(Ar_view,0,y,Ar_image->columns,1,exception);
Ai=GetCacheViewVirtualPixels(Ai_view,0,y,Ai_image->columns,1,exception);
Br=GetCacheViewVirtualPixels(Br_view,0,y,Br_image->columns,1,exception);
Bi=GetCacheViewVirtualPixels(Bi_view,0,y,Bi_image->columns,1,exception);
Cr=QueueCacheViewAuthenticPixels(Cr_view,0,y,Cr_image->columns,1,exception);
Ci=QueueCacheViewAuthenticPixels(Ci_view,0,y,Ci_image->columns,1,exception);
if ((Ar == (const Quantum *) NULL) || (Ai == (const Quantum *) NULL) || 
(Br == (const Quantum *) NULL) || (Bi == (const Quantum *) NULL) ||
(Cr == (Quantum *) NULL) || (Ci == (Quantum *) NULL))
{
status=MagickFalse;
continue;
}
for (x=0; x < (ssize_t) images->columns; x++)
{
register ssize_t
i;
for (i=0; i < (ssize_t) GetPixelChannels(images); i++)
{
switch (op)
{
case AddComplexOperator:
{
Cr[i]=Ar[i]+Br[i];
Ci[i]=Ai[i]+Bi[i];
break;
}
case ConjugateComplexOperator:
default:
{
Cr[i]=Ar[i];
Ci[i]=(-Bi[i]);
break;
}
case DivideComplexOperator:
{
double
gamma;
gamma=PerceptibleReciprocal(Br[i]*Br[i]+Bi[i]*Bi[i]+snr);
Cr[i]=gamma*(Ar[i]*Br[i]+Ai[i]*Bi[i]);
Ci[i]=gamma*(Ai[i]*Br[i]-Ar[i]*Bi[i]);
break;
}
case MagnitudePhaseComplexOperator:
{
Cr[i]=sqrt(Ar[i]*Ar[i]+Ai[i]*Ai[i]);
Ci[i]=atan2(Ai[i],Ar[i])/(2.0*MagickPI)+0.5;
break;
}
case MultiplyComplexOperator:
{
Cr[i]=QuantumScale*(Ar[i]*Br[i]-Ai[i]*Bi[i]);
Ci[i]=QuantumScale*(Ai[i]*Br[i]+Ar[i]*Bi[i]);
break;
}
case RealImaginaryComplexOperator:
{
Cr[i]=Ar[i]*cos(2.0*MagickPI*(Ai[i]-0.5));
Ci[i]=Ar[i]*sin(2.0*MagickPI*(Ai[i]-0.5));
break;
}
case SubtractComplexOperator:
{
Cr[i]=Ar[i]-Br[i];
Ci[i]=Ai[i]-Bi[i];
break;
}
}
}
Ar+=GetPixelChannels(Ar_image);
Ai+=GetPixelChannels(Ai_image);
Br+=GetPixelChannels(Br_image);
Bi+=GetPixelChannels(Bi_image);
Cr+=GetPixelChannels(Cr_image);
Ci+=GetPixelChannels(Ci_image);
}
if (SyncCacheViewAuthenticPixels(Ci_view,exception) == MagickFalse)
status=MagickFalse;
if (SyncCacheViewAuthenticPixels(Cr_view,exception) == MagickFalse)
status=MagickFalse;
if (images->progress_monitor != (MagickProgressMonitor) NULL)
{
MagickBooleanType
proceed;
#if defined(MAGICKCORE_OPENMP_SUPPORT)
#pragma omp atomic
#endif
progress++;
proceed=SetImageProgress(images,ComplexImageTag,progress,images->rows);
if (proceed == MagickFalse)
status=MagickFalse;
}
}
Cr_view=DestroyCacheView(Cr_view);
Ci_view=DestroyCacheView(Ci_view);
Br_view=DestroyCacheView(Br_view);
Bi_view=DestroyCacheView(Bi_view);
Ar_view=DestroyCacheView(Ar_view);
Ai_view=DestroyCacheView(Ai_view);
if (status == MagickFalse)
complex_images=DestroyImageList(complex_images);
return(complex_images);
}

int ntlm_decode_target_info(struct ntlm_ctx *ctx, struct ntlm_buffer *buffer,
char **nb_computer_name, char **nb_domain_name,
char **dns_computer_name, char **dns_domain_name,
char **dns_tree_name, char **av_target_name,
uint32_t *av_flags, uint64_t *av_timestamp,
struct ntlm_buffer *av_single_host,
struct ntlm_buffer *av_cb)
{
struct wire_av_pair *av_pair;
uint16_t av_id = (uint16_t)-1;
uint16_t av_len = (uint16_t)-1;
struct ntlm_buffer sh = { NULL, 0 };
struct ntlm_buffer cb = { NULL, 0 };
char *nb_computer = NULL;
char *nb_domain = NULL;
char *dns_computer = NULL;
char *dns_domain = NULL;
char *dns_tree = NULL;
char *av_target = NULL;
size_t data_offs = 0;
uint64_t timestamp = 0;
uint32_t flags = 0;
int ret = 0;
while (data_offs + 4 <= buffer->length) {
av_pair = (struct wire_av_pair *)&buffer->data[data_offs];
data_offs += 4;
av_id = le16toh(av_pair->av_id);
av_len = le16toh(av_pair->av_len);
if (av_len > buffer->length - data_offs) {
ret = ERR_DECODE;
goto done;
}
data_offs += av_len;
switch (av_id) {
case MSV_AV_CHANNEL_BINDINGS:
if (!av_cb) continue;
cb.data = av_pair->value;
cb.length = av_len;
break;
case MSV_AV_TARGET_NAME:
if (!av_target_name) continue;
ret = ntlm_decode_av_pair_u16l_str(ctx, av_pair, &av_target);
if (ret) goto done;
break;
case MSV_AV_SINGLE_HOST:
if (!av_single_host) continue;
sh.data = av_pair->value;
sh.length = av_len;
break;
case MSV_AV_TIMESTAMP:
if (!av_timestamp) continue;
memcpy(&timestamp, av_pair->value, sizeof(timestamp));
timestamp = le64toh(timestamp);
break;
case MSV_AV_FLAGS:
if (!av_flags) continue;
memcpy(&flags, av_pair->value, sizeof(flags));
flags = le32toh(flags);
break;
case MSV_AV_DNS_TREE_NAME:
if (!dns_tree_name) continue;
ret = ntlm_decode_av_pair_u16l_str(ctx, av_pair, &dns_tree);
if (ret) goto done;
break;
case MSV_AV_DNS_DOMAIN_NAME:
if (!dns_domain_name) continue;
ret = ntlm_decode_av_pair_u16l_str(ctx, av_pair, &dns_domain);
if (ret) goto done;
break;
case MSV_AV_DNS_COMPUTER_NAME:
if (!dns_computer_name) continue;
ret = ntlm_decode_av_pair_u16l_str(ctx, av_pair, &dns_computer);
if (ret) goto done;
break;
case MSV_AV_NB_DOMAIN_NAME:
if (!nb_domain_name) continue;
ret = ntlm_decode_av_pair_u16l_str(ctx, av_pair, &nb_domain);
if (ret) goto done;
break;
case MSV_AV_NB_COMPUTER_NAME:
if (!nb_computer_name) continue;
ret = ntlm_decode_av_pair_u16l_str(ctx, av_pair, &nb_computer);
if (ret) goto done;
break;
default:
break;
}
if (av_id == MSV_AV_EOL) break;
}
if (av_id != MSV_AV_EOL || av_len != 0) {
ret = ERR_DECODE;
}
done:
if (ret) {
safefree(nb_computer);
safefree(nb_domain);
safefree(dns_computer);
safefree(dns_domain);
safefree(dns_tree);
safefree(av_target);
} else {
if (nb_computer_name) *nb_computer_name = nb_computer;
if (nb_domain_name) *nb_domain_name = nb_domain;
if (dns_computer_name) *dns_computer_name = dns_computer;
if (dns_domain_name) *dns_domain_name = dns_domain;
if (dns_tree_name) *dns_tree_name = dns_tree;
if (av_target_name) *av_target_name = av_target;
if (av_timestamp) *av_timestamp = timestamp;
if (av_single_host) *av_single_host = sh;
if (av_flags) *av_flags = flags;
if (av_cb) *av_cb = cb;
}
return ret;
}

