BOOL update_write_cache_brush_order(wStream* s, const CACHE_BRUSH_ORDER* cache_brush, UINT16* flags)
{
int i;
BYTE iBitmapFormat;
BOOL compressed = FALSE;
if (!Stream_EnsureRemainingCapacity(s,
update_approximate_cache_brush_order(cache_brush, flags)))
return FALSE;
iBitmapFormat = BPP_BMF[cache_brush->bpp];
Stream_Write_UINT8(s, cache_brush->index);  
Stream_Write_UINT8(s, iBitmapFormat);       
Stream_Write_UINT8(s, cache_brush->cx);     
Stream_Write_UINT8(s, cache_brush->cy);     
Stream_Write_UINT8(s, cache_brush->style);  
Stream_Write_UINT8(s, cache_brush->length); 
if ((cache_brush->cx == 8) && (cache_brush->cy == 8))
{
if (cache_brush->bpp == 1)
{
if (cache_brush->length != 8)
{
WLog_ERR(TAG, "incompatible 1bpp brush of length:%" PRIu32 "", cache_brush->length);
return FALSE;
}
for (i = 7; i >= 0; i--)
{
Stream_Write_UINT8(s, cache_brush->data[i]);
}
}
else
{
if ((iBitmapFormat == BMF_8BPP) && (cache_brush->length == 20))
compressed = TRUE;
else if ((iBitmapFormat == BMF_16BPP) && (cache_brush->length == 24))
compressed = TRUE;
else if ((iBitmapFormat == BMF_32BPP) && (cache_brush->length == 32))
compressed = TRUE;
if (compressed != FALSE)
{
if (!update_compress_brush(s, cache_brush->data, cache_brush->bpp))
return FALSE;
}
else
{
int scanline = (cache_brush->bpp / 8) * 8;
for (i = 7; i >= 0; i--)
{
Stream_Write(s, &cache_brush->data[i * scanline], scanline);
}
}
}
}
return TRUE;
}

static struct sk_buff *napi_frags_skb(struct napi_struct *napi)
{
struct sk_buff *skb = napi->skb;
const struct ethhdr *eth;
unsigned int hlen = sizeof(*eth);
napi->skb = NULL;
skb_reset_mac_header(skb);
skb_gro_reset_offset(skb);
eth = skb_gro_header_fast(skb, 0);
if (unlikely(skb_gro_header_hard(skb, hlen))) {
eth = skb_gro_header_slow(skb, hlen, 0);
if (unlikely(!eth)) {
net_warn_ratelimited("%s: dropping impossible skb from %s\n",
__func__, napi->dev->name);
napi_reuse_skb(napi, skb);
return NULL;
}
} else {
gro_pull_from_frag0(skb, hlen);
NAPI_GRO_CB(skb)->frag0 += hlen;
NAPI_GRO_CB(skb)->frag0_len -= hlen;
}
__skb_pull(skb, hlen);
skb->protocol = eth->h_proto;
return skb;
}

static js_Ast *bitor(js_State *J, int notin)
{
js_Ast *a = bitxor(J, notin);
while (jsP_accept(J, '|'))
a = EXP2(BITOR, a, bitxor(J, notin));
return a;
}

gravity_function_t *gravity_function_deserialize (gravity_vm *vm, json_value *json) {
gravity_function_t *f = gravity_function_new(vm, NULL, 0, 0, 0, NULL);
DEBUG_DESERIALIZE("DESERIALIZE FUNCTION: %p\n", f);
uint32_t n = json->u.object.length;
for (uint32_t i=1; i<n; ++i) { const char *label = json->u.object.values[i].name;
json_value *value = json->u.object.values[i].value;
size_t label_size = strlen(label);
if (string_casencmp(label, GRAVITY_JSON_LABELIDENTIFIER, label_size) == 0) {
assert(value->type == json_string);
if (strncmp(value->u.string.ptr, "$anon", 5) != 0) {
f->identifier = string_dup(value->u.string.ptr);
DEBUG_DESERIALIZE("IDENTIFIER: %s\n", value->u.string.ptr);
}
continue;
}
if (string_casencmp(label, GRAVITY_JSON_LABELTAG, label_size) == 0) {
assert(value->type == json_integer);
f->tag = (uint16_t)value->u.integer;
continue;
}
if (string_casencmp(label, GRAVITY_JSON_LABELINDEX, label_size) == 0) {
assert(value->type == json_integer);
assert(f->tag == EXEC_TYPE_SPECIAL);
f->index = (uint16_t)value->u.integer;
continue;
}
if (string_casencmp(label, GRAVITY_JSON_GETTER, strlen(GRAVITY_JSON_GETTER)) == 0) {
assert(f->tag == EXEC_TYPE_SPECIAL);
gravity_function_t *getter = gravity_function_deserialize(vm, value);
f->special[0] = gravity_closure_new(vm, getter);
continue;
}
if (string_casencmp(label, GRAVITY_JSON_SETTER, strlen(GRAVITY_JSON_SETTER)) == 0) {
assert(f->tag == EXEC_TYPE_SPECIAL);
gravity_function_t *setter = gravity_function_deserialize(vm, value);
f->special[1] = gravity_closure_new(vm, setter);
continue;
}
if (string_casencmp(label, GRAVITY_JSON_LABELNPARAM, label_size) == 0) {
assert(value->type == json_integer);
f->nparams = (uint16_t)value->u.integer;
continue;
}
if (string_casencmp(label, GRAVITY_JSON_LABELNLOCAL, label_size) == 0) {
assert(value->type == json_integer);
f->nlocals = (uint16_t)value->u.integer;
continue;
}
if (string_casencmp(label, GRAVITY_JSON_LABELNTEMP, label_size) == 0) {
assert(value->type == json_integer);
f->ntemps = (uint16_t)value->u.integer;
continue;
}
if (string_casencmp(label, GRAVITY_JSON_LABELNUPV, label_size) == 0) {
assert(value->type == json_integer);
f->nupvalues = (uint16_t)value->u.integer;
continue;
}
if (string_casencmp(label, GRAVITY_JSON_LABELARGS, label_size) == 0) {
assert(value->type == json_boolean);
f->useargs = (bool)value->u.boolean;
continue;
}
if (string_casencmp(label, GRAVITY_JSON_LABELBYTECODE, label_size) == 0) {
if (value->type == json_null) continue;
assert(value->type == json_string);
f->bytecode = gravity_bytecode_deserialize(value->u.string.ptr, value->u.string.length, &f->ninsts);
continue;
}
if (string_casencmp(label, GRAVITY_JSON_LABELPOOL, label_size) == 0) {
assert(value->type == json_array);
uint32_t m = value->u.array.length;
for (uint32_t j=0; j<m; ++j) {
json_value *r = value->u.array.values[j];
switch (r->type) {
case json_integer:
gravity_function_cpool_add(NULL, f, VALUE_FROM_INT((gravity_int_t)r->u.integer));
break;
case json_double:
gravity_function_cpool_add(NULL, f, VALUE_FROM_FLOAT((gravity_float_t)r->u.dbl));
break;
case json_boolean:
gravity_function_cpool_add(NULL, f, VALUE_FROM_BOOL(r->u.boolean));
break;
case json_string:
gravity_function_cpool_add(vm, f, VALUE_FROM_STRING(NULL, r->u.string.ptr, r->u.string.length));
break;
case json_object: {
gravity_object_t *obj = gravity_object_deserialize(vm, r);
if (!obj) goto abort_load;
gravity_function_cpool_add(NULL, f, VALUE_FROM_OBJECT(obj));
break;
}
case json_array: {
uint32_t count = r->u.array.length;
gravity_list_t *list = gravity_list_new(NULL, count);
for (uint32_t k=0; k<count; ++k) {
json_value *jsonv = r->u.array.values[k];
gravity_value_t v;
switch (jsonv->type) {
case json_integer: v = VALUE_FROM_INT((gravity_int_t)jsonv->u.integer); break;
case json_double: v = VALUE_FROM_FLOAT((gravity_float_t)jsonv->u.dbl); break;
case json_boolean: v = VALUE_FROM_BOOL(jsonv->u.boolean); break;
case json_string: v = VALUE_FROM_STRING(vm, jsonv->u.string.ptr, jsonv->u.string.length); break;
default:assert(0);
}
marray_push(gravity_value_t, list->array, v);
}
gravity_function_cpool_add(vm, f, VALUE_FROM_OBJECT(list));
}
case json_none:
case json_null:
gravity_function_cpool_add(NULL, f, VALUE_FROM_NULL);
break;
}
}
}
}
return f;
abort_load:
if (f) gravity_function_free(vm, f);
return NULL;
}

static bfd_boolean
process_mips_specific (FILE * file)
{
Elf_Internal_Dyn * entry;
Elf_Internal_Shdr *sect = NULL;
size_t liblist_offset = 0;
size_t liblistno = 0;
size_t conflictsno = 0;
size_t options_offset = 0;
size_t conflicts_offset = 0;
size_t pltrelsz = 0;
size_t pltrel = 0;
bfd_vma pltgot = 0;
bfd_vma mips_pltgot = 0;
bfd_vma jmprel = 0;
bfd_vma local_gotno = 0;
bfd_vma gotsym = 0;
bfd_vma symtabno = 0;
bfd_boolean res = TRUE;
if (! process_attributes (file, NULL, SHT_GNU_ATTRIBUTES, NULL,
display_mips_gnu_attribute))
res = FALSE;
sect = find_section (".MIPS.abiflags");
if (sect != NULL)
{
Elf_External_ABIFlags_v0 *abiflags_ext;
Elf_Internal_ABIFlags_v0 abiflags_in;
if (sizeof (Elf_External_ABIFlags_v0) != sect->sh_size)
{
error (_("Corrupt MIPS ABI Flags section.\n"));
res = FALSE;
}
else
{
abiflags_ext = get_data (NULL, file, sect->sh_offset, 1,
sect->sh_size, _("MIPS ABI Flags section"));
if (abiflags_ext)
{
abiflags_in.version = BYTE_GET (abiflags_ext->version);
abiflags_in.isa_level = BYTE_GET (abiflags_ext->isa_level);
abiflags_in.isa_rev = BYTE_GET (abiflags_ext->isa_rev);
abiflags_in.gpr_size = BYTE_GET (abiflags_ext->gpr_size);
abiflags_in.cpr1_size = BYTE_GET (abiflags_ext->cpr1_size);
abiflags_in.cpr2_size = BYTE_GET (abiflags_ext->cpr2_size);
abiflags_in.fp_abi = BYTE_GET (abiflags_ext->fp_abi);
abiflags_in.isa_ext = BYTE_GET (abiflags_ext->isa_ext);
abiflags_in.ases = BYTE_GET (abiflags_ext->ases);
abiflags_in.flags1 = BYTE_GET (abiflags_ext->flags1);
abiflags_in.flags2 = BYTE_GET (abiflags_ext->flags2);
printf ("\nMIPS ABI Flags Version: %d\n", abiflags_in.version);
printf ("\nISA: MIPS%d", abiflags_in.isa_level);
if (abiflags_in.isa_rev > 1)
printf ("r%d", abiflags_in.isa_rev);
printf ("\nGPR size: %d",
get_mips_reg_size (abiflags_in.gpr_size));
printf ("\nCPR1 size: %d",
get_mips_reg_size (abiflags_in.cpr1_size));
printf ("\nCPR2 size: %d",
get_mips_reg_size (abiflags_in.cpr2_size));
fputs ("\nFP ABI: ", stdout);
print_mips_fp_abi_value (abiflags_in.fp_abi);
fputs ("ISA Extension: ", stdout);
print_mips_isa_ext (abiflags_in.isa_ext);
fputs ("\nASEs:", stdout);
print_mips_ases (abiflags_in.ases);
printf ("\nFLAGS 1: %8.8lx", abiflags_in.flags1);
printf ("\nFLAGS 2: %8.8lx", abiflags_in.flags2);
fputc ('\n', stdout);
free (abiflags_ext);
}
}
}
if (dynamic_section == NULL)
return res;
for (entry = dynamic_section;
entry < dynamic_section + dynamic_nent && entry->d_tag != DT_NULL;
++entry)
switch (entry->d_tag)
{
case DT_MIPS_LIBLIST:
liblist_offset
= offset_from_vma (file, entry->d_un.d_val,
liblistno * sizeof (Elf32_External_Lib));
break;
case DT_MIPS_LIBLISTNO:
liblistno = entry->d_un.d_val;
break;
case DT_MIPS_OPTIONS:
options_offset = offset_from_vma (file, entry->d_un.d_val, 0);
break;
case DT_MIPS_CONFLICT:
conflicts_offset
= offset_from_vma (file, entry->d_un.d_val,
conflictsno * sizeof (Elf32_External_Conflict));
break;
case DT_MIPS_CONFLICTNO:
conflictsno = entry->d_un.d_val;
break;
case DT_PLTGOT:
pltgot = entry->d_un.d_ptr;
break;
case DT_MIPS_LOCAL_GOTNO:
local_gotno = entry->d_un.d_val;
break;
case DT_MIPS_GOTSYM:
gotsym = entry->d_un.d_val;
break;
case DT_MIPS_SYMTABNO:
