int
ssh_packet_get_state(struct ssh *ssh, struct sshbuf *m)
{
struct session_state *state = ssh->state;
u_char *p;
size_t slen, rlen;
int r, ssh1cipher;
if (!compat20) {
ssh1cipher = cipher_ctx_get_number(state->receive_context);
slen = cipher_get_keyiv_len(state->send_context);
rlen = cipher_get_keyiv_len(state->receive_context);
if ((r = sshbuf_put_u32(m, state->remote_protocol_flags)) != 0 ||
(r = sshbuf_put_u32(m, ssh1cipher)) != 0 ||
(r = sshbuf_put_string(m, state->ssh1_key, state->ssh1_keylen)) != 0 ||
(r = sshbuf_put_u32(m, slen)) != 0 ||
(r = sshbuf_reserve(m, slen, &p)) != 0 ||
(r = cipher_get_keyiv(state->send_context, p, slen)) != 0 ||
(r = sshbuf_put_u32(m, rlen)) != 0 ||
(r = sshbuf_reserve(m, rlen, &p)) != 0 ||
(r = cipher_get_keyiv(state->receive_context, p, rlen)) != 0)
return r;
} else {
if ((r = kex_to_blob(m, ssh->kex)) != 0 ||
(r = newkeys_to_blob(m, ssh, MODE_OUT)) != 0 ||
(r = newkeys_to_blob(m, ssh, MODE_IN)) != 0 ||
(r = sshbuf_put_u64(m, state->rekey_limit)) != 0 ||
(r = sshbuf_put_u32(m, state->rekey_interval)) != 0 ||
(r = sshbuf_put_u32(m, state->p_send.seqnr)) != 0 ||
(r = sshbuf_put_u64(m, state->p_send.blocks)) != 0 ||
(r = sshbuf_put_u32(m, state->p_send.packets)) != 0 ||
(r = sshbuf_put_u64(m, state->p_send.bytes)) != 0 ||
(r = sshbuf_put_u32(m, state->p_read.seqnr)) != 0 ||
(r = sshbuf_put_u64(m, state->p_read.blocks)) != 0 ||
(r = sshbuf_put_u32(m, state->p_read.packets)) != 0 ||
(r = sshbuf_put_u64(m, state->p_read.bytes)) != 0)
return r;
}
slen = cipher_get_keycontext(state->send_context, NULL);
rlen = cipher_get_keycontext(state->receive_context, NULL);
if ((r = sshbuf_put_u32(m, slen)) != 0 ||
(r = sshbuf_reserve(m, slen, &p)) != 0)
return r;
if (cipher_get_keycontext(state->send_context, p) != (int)slen)
return SSH_ERR_INTERNAL_ERROR;
if ((r = sshbuf_put_u32(m, rlen)) != 0 ||
(r = sshbuf_reserve(m, rlen, &p)) != 0)
return r;
if (cipher_get_keycontext(state->receive_context, p) != (int)rlen)
return SSH_ERR_INTERNAL_ERROR;
if ((r = ssh_packet_get_compress_state(m, ssh)) != 0 ||
(r = sshbuf_put_stringb(m, state->input)) != 0 ||
(r = sshbuf_put_stringb(m, state->output)) != 0)
return r;
return 0;
}

void check_tensor(const TensorProto& tensor, const CheckerContext& ctx) {
enforce_has_field(tensor, data_type);
if (tensor.data_type() == TensorProto::UNDEFINED) {
fail_check("setting data_type field (tensor name: ", tensor.name(), ") to UNDEFINED is not allowed");
}
int num_value_fields = 0;
const char* value_field = nullptr;
#define check_data_field(field)             \
bool has_##field = tensor.field().size(); \
if (has_##field) {                        \
++num_value_fields;                     \
value_field = #field;                   \
}
check_data_field(float_data);
check_data_field(int32_data);
check_data_field(string_data);
check_data_field(int64_data);
check_data_field(raw_data);
check_data_field(double_data);
check_data_field(uint64_data);
#undef check_data_field
bool stored_externally = tensor.has_data_location() && tensor.data_location() == TensorProto::EXTERNAL;
if (stored_externally) {
if (num_value_fields != 0) {
fail_check(
"Data of TensorProto ( tensor name: ",
tensor.name(),
") is stored externally and should not have data field.",
value_field);
}
bool has_location = false;
for (const StringStringEntryProto& entry : tensor.external_data()) {
if (entry.has_key() && entry.has_value() && entry.key() == "location") {
has_location = true;
std::string data_path = path_join(ctx.get_model_dir(), entry.value());
struct stat buffer;
if (stat((data_path).c_str(), &buffer) != 0) {
fail_check(
"Data of TensorProto ( tensor name: ",
tensor.name(),
") should be stored in ",
data_path,
", but it doesn't exist or is not accessible.");
}
}
}
if (!has_location) {
fail_check("TensorProto ( tensor name: ", tensor.name(), ") is stored externally but doesn't have a location.");
}
return;
}
int64_t nelem = 1;
for (auto x : tensor.dims()) {
nelem *= x;
}
if (nelem == 0 && num_value_fields != 0) {
fail_check("TensorProto (tensor name: ", tensor.name(), ") is 0-element but contains data!");
}
if (nelem != 0 && num_value_fields != 1) {
fail_check("TensorProto (tensor name: ", tensor.name(), ") should contain one and only one value field.");
}
if (has_raw_data) {
if (tensor.data_type() == TensorProto::STRING) {
fail_check("STRING data (tensor name: ", tensor.name(), ") should not be stored in raw_data field");
}
return;
} else {
#define check_field(field)               \
if (nelem != 0 && !has_##field) {      \
fail_check(                          \
"values of data_type '",         \
tensor.data_type(),              \
"' should be stored in field '", \
#field,                          \
"' instead of '",                \
value_field,                     \
"'");                            \
}
switch (tensor.data_type()) {
case TensorProto::FLOAT:
case TensorProto::COMPLEX64:
check_field(float_data);
break;
case TensorProto::DOUBLE:
case TensorProto::COMPLEX128:
check_field(double_data);
break;
case TensorProto::INT32:
case TensorProto::UINT8:
case TensorProto::INT8:
case TensorProto::UINT16:
case TensorProto::INT16:
case TensorProto::BOOL:
case TensorProto::FLOAT16:
case TensorProto::BFLOAT16:
check_field(int32_data);
break;
case TensorProto::INT64:
check_field(int64_data);
break;
case TensorProto::UINT32:
case TensorProto::UINT64:
check_field(uint64_data);
break;
case TensorProto::STRING:
check_field(string_data);
break;
default:
fail_check("Unrecognized data_type (tensor name: ", tensor.name(), "): ", tensor.data_type());
}
}
#undef check_field
}

bool zx_confirmZxLiquidTx(uint32_t data_total, const EthereumSignTx *msg) {
(void)data_total;
const TokenType *token;
char constr1[40], constr2[40], *arStr = "";
uint8_t *tokenAddress, *deadlineBytes;
bignum256 tokenAmount, tokenMinAmount, ethMinAmount;
uint64_t deadline;
if (isAddLiquidityEthCall(msg)) {
arStr = "uniswap add liquidity";
} else if (isRemoveLiquidityEthCall(msg)) {
arStr = "uniswap remove liquidity";
} else {
return false;
}
tokenAddress = (uint8_t *)(msg->data_initial_chunk.bytes + 4 + 32 - 20);
token = tokenByChainAddress(msg->chain_id, tokenAddress);
bn_from_bytes(msg->data_initial_chunk.bytes + 4 + 32, 32, &tokenAmount);
bn_from_bytes(msg->data_initial_chunk.bytes + 4 + 2*32, 32, &tokenMinAmount);
bn_from_bytes(msg->data_initial_chunk.bytes + 4 + 3*32, 32, &ethMinAmount);
deadlineBytes = (uint8_t *)(msg->data_initial_chunk.bytes + 4 + 6*32 - 8);
deadline = ((uint64_t)deadlineBytes[0] << 8*7) |
((uint64_t)deadlineBytes[1] << 8*6) |
((uint64_t)deadlineBytes[2] << 8*5) |
((uint64_t)deadlineBytes[3] << 8*4) |
((uint64_t)deadlineBytes[4] << 8*3) |
((uint64_t)deadlineBytes[5] << 8*2) |
((uint64_t)deadlineBytes[6] << 8*1) |
((uint64_t)deadlineBytes[7]);
char tokbuf[32];
ethereumFormatAmount(&tokenAmount, token, msg->chain_id, tokbuf, sizeof(tokbuf));
snprintf(constr1, 32, "%s", tokbuf);
ethereumFormatAmount(&tokenMinAmount, token, msg->chain_id, tokbuf, sizeof(tokbuf));
snprintf(constr2, 32, "%s", tokbuf);
confirm(ButtonRequestType_ButtonRequest_ConfirmOutput, arStr,
"%s\nMinimum %s", constr1, constr2);
if (!confirmFromAccountMatch(msg, arStr)) {
return false;
}
ethereumFormatAmount(&ethMinAmount, NULL, msg->chain_id, tokbuf, sizeof(tokbuf));
snprintf(constr1, 32, "%s", tokbuf);
confirm(ButtonRequestType_ButtonRequest_ConfirmOutput, arStr,
"Minimum %s", constr1);
snprintf(constr1, 32, "%lld", deadline);
confirm(ButtonRequestType_ButtonRequest_ConfirmOutput, arStr,
"Deadline %s", ctime((const time_t *)&deadline));
return true;
}

