static void pci_write(void *opaque, hwaddr addr, uint64_t data,
unsigned int size)
{
int slot;
PCIBus *bus;
BusChild *kid, *next;
AcpiPciHpState *s = opaque;
s->acpi_index = 0;
switch (addr) {
case PCI_AIDX_BASE:
slot = ctz32(data);
if (s->hotplug_select >= ACPI_PCIHP_MAX_HOTPLUG_BUS) {
break;
}
bus = acpi_pcihp_find_hotplug_bus(s, s->hotplug_select);
QTAILQ_FOREACH_SAFE(kid, &bus->qbus.children, sibling, next) {
Object *o = OBJECT(kid->child);
PCIDevice *dev = PCI_DEVICE(o);
if (PCI_SLOT(dev->devfn) == slot) {
s->acpi_index = object_property_get_uint(o, "acpi-index", NULL);
break;
}
}
trace_acpi_pci_acpi_index_write(s->hotplug_select, slot, s->acpi_index);
break;
case PCI_EJ_BASE:
if (s->hotplug_select >= ACPI_PCIHP_MAX_HOTPLUG_BUS) {
break;
}
acpi_pcihp_eject_slot(s, s->hotplug_select, data);
trace_acpi_pci_ej_write(addr, data);
break;
case PCI_SEL_BASE:
s->hotplug_select = s->legacy_piix ? ACPI_PCIHP_BSEL_DEFAULT : data;
trace_acpi_pci_sel_write(addr, data);
default:
break;
}
}

void*
xmlNanoHTTPMethodRedir(const char *URL, const char *method, const char *input,
char **contentType, char **redir,
const char *headers, int ilen ) {
xmlNanoHTTPCtxtPtr ctxt;
char *bp, *p;
int blen;
SOCKET ret;
int nbRedirects = 0;
char *redirURL = NULL;
#ifdef DEBUG_HTTP
int xmt_bytes;
#endif
if (URL == NULL) return(NULL);
if (method == NULL) method = "GET";
xmlNanoHTTPInit();
retry:
if (redirURL == NULL) {
ctxt = xmlNanoHTTPNewCtxt(URL);
if (ctxt == NULL)
return(NULL);
} else {
ctxt = xmlNanoHTTPNewCtxt(redirURL);
if (ctxt == NULL)
return(NULL);
ctxt->location = xmlMemStrdup(redirURL);
}
if ((ctxt->protocol == NULL) || (strcmp(ctxt->protocol, "http"))) {
__xmlIOErr(XML_FROM_HTTP, XML_HTTP_URL_SYNTAX, "Not a valid HTTP URI");
xmlNanoHTTPFreeCtxt(ctxt);
if (redirURL != NULL) xmlFree(redirURL);
return(NULL);
}
if (ctxt->hostname == NULL) {
__xmlIOErr(XML_FROM_HTTP, XML_HTTP_UNKNOWN_HOST,
"Failed to identify host in URI");
xmlNanoHTTPFreeCtxt(ctxt);
if (redirURL != NULL) xmlFree(redirURL);
return(NULL);
}
if (proxy) {
blen = strlen(ctxt->hostname) * 2 + 16;
ret = xmlNanoHTTPConnectHost(proxy, proxyPort);
}
else {
blen = strlen(ctxt->hostname);
ret = xmlNanoHTTPConnectHost(ctxt->hostname, ctxt->port);
}
if (ret == INVALID_SOCKET) {
xmlNanoHTTPFreeCtxt(ctxt);
if (redirURL != NULL) xmlFree(redirURL);
return(NULL);
}
ctxt->fd = ret;
if (input == NULL)
ilen = 0;
else
blen += 36;
if (headers != NULL)
blen += strlen(headers) + 2;
if (contentType && *contentType)
blen += strlen(*contentType) + 16;
if (ctxt->query != NULL)
blen += strlen(ctxt->query) + 1;
blen += strlen(method) + strlen(ctxt->path) + 24;
#ifdef HAVE_ZLIB_H
blen += 23;
#endif
if (ctxt->port != 80) {
if (proxy)
blen += 12;
else
blen += 6;
}
bp = (char*)xmlMallocAtomic(blen);
if ( bp == NULL ) {
xmlNanoHTTPFreeCtxt( ctxt );
xmlHTTPErrMemory("allocating header buffer");
return ( NULL );
}
p = bp;
if (proxy) {
if (ctxt->port != 80) {
p += snprintf( p, blen - (p - bp), "%s http:method, ctxt->hostname,
ctxt->port, ctxt->path );
}
else
p += snprintf( p, blen - (p - bp), "%s http:ctxt->hostname, ctxt->path);
}
else
p += snprintf( p, blen - (p - bp), "%s %s", method, ctxt->path);
if (ctxt->query != NULL)
p += snprintf( p, blen - (p - bp), "?%s", ctxt->query);
if (ctxt->port == 80) {
p += snprintf( p, blen - (p - bp), " HTTP/1.0\r\nHost: %s\r\n",
ctxt->hostname);
} else {
p += snprintf( p, blen - (p - bp), " HTTP/1.0\r\nHost: %s:%d\r\n",
ctxt->hostname, ctxt->port);
}
#ifdef HAVE_ZLIB_H
p += snprintf(p, blen - (p - bp), "Accept-Encoding: gzip\r\n");
#endif
if (contentType != NULL && *contentType)
p += snprintf(p, blen - (p - bp), "Content-Type: %s\r\n", *contentType);
if (headers != NULL)
p += snprintf( p, blen - (p - bp), "%s", headers );
if (input != NULL)
snprintf(p, blen - (p - bp), "Content-Length: %d\r\n\r\n", ilen );
else
snprintf(p, blen - (p - bp), "\r\n");
#ifdef DEBUG_HTTP
xmlGenericError(xmlGenericErrorContext,
"-> %s%s", proxy? "(Proxy) " : "", bp);
if ((blen -= strlen(bp)+1) < 0)
xmlGenericError(xmlGenericErrorContext,
"ERROR: overflowed buffer by %d bytes\n", -blen);
#endif
ctxt->outptr = ctxt->out = bp;
ctxt->state = XML_NANO_HTTP_WRITE;
blen = strlen( ctxt->out );
#ifdef DEBUG_HTTP
xmt_bytes = xmlNanoHTTPSend(ctxt, ctxt->out, blen );
if ( xmt_bytes != blen )
xmlGenericError( xmlGenericErrorContext,
"xmlNanoHTTPMethodRedir:  Only %d of %d %s %s\n",
xmt_bytes, blen,
"bytes of HTTP headers sent to host",
ctxt->hostname );
#else
xmlNanoHTTPSend(ctxt, ctxt->out, blen );
#endif
if ( input != NULL ) {
#ifdef DEBUG_HTTP
xmt_bytes = xmlNanoHTTPSend( ctxt, input, ilen );
if ( xmt_bytes != ilen )
xmlGenericError( xmlGenericErrorContext,
"xmlNanoHTTPMethodRedir:  Only %d of %d %s %s\n",
xmt_bytes, ilen,
"bytes of HTTP content sent to host",
ctxt->hostname );
#else
xmlNanoHTTPSend( ctxt, input, ilen );
#endif
}
ctxt->state = XML_NANO_HTTP_READ;
while ((p = xmlNanoHTTPReadLine(ctxt)) != NULL) {
if (*p == 0) {
ctxt->content = ctxt->inrptr;
xmlFree(p);
break;
}
xmlNanoHTTPScanAnswer(ctxt, p);
#ifdef DEBUG_HTTP
xmlGenericError(xmlGenericErrorContext, "<- %s\n", p);
#endif
xmlFree(p);
}
if ((ctxt->location != NULL) && (ctxt->returnValue >= 300) &&
(ctxt->returnValue < 400)) {
#ifdef DEBUG_HTTP
xmlGenericError(xmlGenericErrorContext,
"\nRedirect to: %s\n", ctxt->location);
#endif
while ( xmlNanoHTTPRecv(ctxt) > 0 ) ;
if (nbRedirects < XML_NANO_HTTP_MAX_REDIR) {
nbRedirects++;
if (redirURL != NULL)
xmlFree(redirURL);
redirURL = xmlMemStrdup(ctxt->location);
xmlNanoHTTPFreeCtxt(ctxt);
goto retry;
}
xmlNanoHTTPFreeCtxt(ctxt);
if (redirURL != NULL) xmlFree(redirURL);
#ifdef DEBUG_HTTP
xmlGenericError(xmlGenericErrorContext,
"xmlNanoHTTPMethodRedir: Too many redirects, aborting ...\n");
#endif
return(NULL);
}
if (contentType != NULL) {
if (ctxt->contentType != NULL)
*contentType = xmlMemStrdup(ctxt->contentType);
else
*contentType = NULL;
}
if ((redir != NULL) && (redirURL != NULL)) {
*redir = redirURL;
} else {
if (redirURL != NULL)
xmlFree(redirURL);
if (redir != NULL)
*redir = NULL;
}
#ifdef DEBUG_HTTP
if (ctxt->contentType != NULL)
xmlGenericError(xmlGenericErrorContext,
"\nCode %d, content-type '%s'\n\n",
ctxt->returnValue, ctxt->contentType);
else
xmlGenericError(xmlGenericErrorContext,
"\nCode %d, no content-type\n\n",
ctxt->returnValue);
#endif
return((void *) ctxt);
}

static int stub_send_ret_submit(struct stub_device *sdev)
{
unsigned long flags;
struct stub_priv *priv, *tmp;
struct msghdr msg;
size_t txsize;
size_t total_size = 0;
while ((priv = dequeue_from_priv_tx(sdev)) != NULL) {
int ret;
struct urb *urb = priv->urb;
struct usbip_header pdu_header;
struct usbip_iso_packet_descriptor *iso_buffer = NULL;
struct kvec *iov = NULL;
int iovnum = 0;
txsize = 0;
memset(&pdu_header, 0, sizeof(pdu_header));
memset(&msg, 0, sizeof(msg));
if (usb_pipetype(urb->pipe) == PIPE_ISOCHRONOUS)
iovnum = 2 + urb->number_of_packets;
else
iovnum = 2;
iov = kcalloc(iovnum, sizeof(struct kvec), GFP_KERNEL);
if (!iov) {
usbip_event_add(&sdev->ud, SDEV_EVENT_ERROR_MALLOC);
return -1;
}
iovnum = 0;
setup_ret_submit_pdu(&pdu_header, urb);
usbip_dbg_stub_tx("setup txdata seqnum: %d urb: %p\n",
pdu_header.base.seqnum, urb);
usbip_header_correct_endian(&pdu_header, 1);
iov[iovnum].iov_base = &pdu_header;
iov[iovnum].iov_len  = sizeof(pdu_header);
iovnum++;
txsize += sizeof(pdu_header);
if (usb_pipein(urb->pipe) &&
usb_pipetype(urb->pipe) != PIPE_ISOCHRONOUS &&
urb->actual_length > 0) {
iov[iovnum].iov_base = urb->transfer_buffer;
iov[iovnum].iov_len  = urb->actual_length;
iovnum++;
txsize += urb->actual_length;
} else if (usb_pipein(urb->pipe) &&
usb_pipetype(urb->pipe) == PIPE_ISOCHRONOUS) {
int i;
for (i = 0; i < urb->number_of_packets; i++) {
iov[iovnum].iov_base = urb->transfer_buffer +
urb->iso_frame_desc[i].offset;
iov[iovnum].iov_len =
urb->iso_frame_desc[i].actual_length;
iovnum++;
txsize += urb->iso_frame_desc[i].actual_length;
}
if (txsize != sizeof(pdu_header) + urb->actual_length) {
dev_err(&sdev->udev->dev,
"actual length of urb %d does not match iso packet sizes %zu\n",
urb->actual_length,
txsize-sizeof(pdu_header));
kfree(iov);
usbip_event_add(&sdev->ud,
SDEV_EVENT_ERROR_TCP);
return -1;
}
}
if (usb_pipetype(urb->pipe) == PIPE_ISOCHRONOUS) {
ssize_t len = 0;
iso_buffer = usbip_alloc_iso_desc_pdu(urb, &len);
if (!iso_buffer) {
usbip_event_add(&sdev->ud,
SDEV_EVENT_ERROR_MALLOC);
kfree(iov);
return -1;
}
iov[iovnum].iov_base = iso_buffer;
iov[iovnum].iov_len  = len;
txsize += len;
iovnum++;
}
ret = kernel_sendmsg(sdev->ud.tcp_socket, &msg,
iov,  iovnum, txsize);
if (ret != txsize) {
dev_err(&sdev->udev->dev,
"sendmsg failed!, retval %d for %zd\n",
ret, txsize);
kfree(iov);
kfree(iso_buffer);
usbip_event_add(&sdev->ud, SDEV_EVENT_ERROR_TCP);
return -1;
}
kfree(iov);
kfree(iso_buffer);
total_size += txsize;
}
spin_lock_irqsave(&sdev->priv_lock, flags);
list_for_each_entry_safe(priv, tmp, &sdev->priv_free, list) {
stub_free_priv_and_urb(priv);
}
spin_unlock_irqrestore(&sdev->priv_lock, flags);
return total_size;
}

static PyMemoEntry *
_PyMemoTable_Lookup(PyMemoTable *self, PyObject *key)
{
size_t i;
size_t perturb;
size_t mask = (size_t)self->mt_mask;
PyMemoEntry *table = self->mt_table;
PyMemoEntry *entry;
Py_hash_t hash = (Py_hash_t)key >> 3;
i = hash & mask;
entry = &table[i];
if (entry->me_key == NULL || entry->me_key == key)
return entry;
for (perturb = hash; ; perturb >>= PERTURB_SHIFT) {
i = (i << 2) + i + perturb + 1;
entry = &table[i & mask];
if (entry->me_key == NULL || entry->me_key == key)
return entry;
}
Py_UNREACHABLE();
}

static bool reconstruct_chained_fixup(struct MACH0_(obj_t) *bin) {
if (!bin->dyld_info) {
return false;
}
if (!bin->nsegs) {
return false;
}
bin->chained_starts = R_NEWS0 (struct r_dyld_chained_starts_in_segment *, bin->nsegs);
if (!bin->chained_starts) {
return false;
}
size_t wordsize = get_word_size (bin);
ut8 *p = NULL;
size_t j, count, skip, bind_size;
int seg_idx = 0;
ut64 seg_off = 0;
bind_size = bin->dyld_info->bind_size;
if (!bind_size || bind_size < 1) {
return false;
}
if (bin->dyld_info->bind_off > bin->size) {
return false;
}
if (bin->dyld_info->bind_off + bind_size > bin->size) {
return false;
}
ut8 *opcodes = calloc (1, bind_size + 1);
if (!opcodes) {
return false;
}
if (r_buf_read_at (bin->b, bin->dyld_info->bind_off, opcodes, bind_size) != bind_size) {
bprintf ("Error: read (dyld_info bind) at 0x%08"PFMT64x"\n", (ut64)(size_t)bin->dyld_info->bind_off);
R_FREE (opcodes);
return false;
}
struct r_dyld_chained_starts_in_segment *cur_seg = NULL;
size_t cur_seg_idx = 0;
ut8 *end;
bool done = false;
for (p = opcodes, end = opcodes + bind_size; !done && p < end;) {
ut8 imm = *p & BIND_IMMEDIATE_MASK, op = *p & BIND_OPCODE_MASK;
p++;
switch (op) {
case BIND_OPCODE_DONE:
done = true;
break;
case BIND_OPCODE_THREADED: {
switch (imm) {
case BIND_SUBOPCODE_THREADED_SET_BIND_ORDINAL_TABLE_SIZE_ULEB: {
read_uleb128 (&p, end);
break;
}
case BIND_SUBOPCODE_THREADED_APPLY: {
const size_t ps = 0x1000;
if (!cur_seg || cur_seg_idx != seg_idx) {
cur_seg_idx = seg_idx;
cur_seg = bin->chained_starts[seg_idx];
if (!cur_seg) {
cur_seg = R_NEW0 (struct r_dyld_chained_starts_in_segment);
if (!cur_seg) {
break;
}
bin->chained_starts[seg_idx] = cur_seg;
cur_seg->pointer_format = DYLD_CHAINED_PTR_ARM64E;
cur_seg->page_size = ps;
cur_seg->page_count = ((bin->segs[seg_idx].vmsize + (ps - 1)) & ~(ps - 1)) / ps;
if (cur_seg->page_count > 0) {
cur_seg->page_start = malloc (sizeof (ut16) * cur_seg->page_count);
if (!cur_seg->page_start) {
break;
}
memset (cur_seg->page_start, 0xff, sizeof (ut16) * cur_seg->page_count);
}
}
}
if (cur_seg) {
ut32 page_index = (ut32)(seg_off / ps);
size_t maxsize = cur_seg->page_count * sizeof (ut16);
if (page_index < maxsize && cur_seg->page_start) {
cur_seg->page_start[page_index] = seg_off & 0xfff;
}
}
break;
}
default:
bprintf ("Error: Unexpected BIND_OPCODE_THREADED sub-opcode: 0x%x\n", imm);
}
break;
}
case BIND_OPCODE_SET_DYLIB_ORDINAL_IMM:
case BIND_OPCODE_SET_DYLIB_SPECIAL_IMM:
case BIND_OPCODE_SET_TYPE_IMM:
break;
case BIND_OPCODE_SET_DYLIB_ORDINAL_ULEB:
read_uleb128 (&p, end);
break;
case BIND_OPCODE_SET_SYMBOL_TRAILING_FLAGS_IMM:
while (*p++ && p < end) {
}
break;
case BIND_OPCODE_SET_ADDEND_SLEB:
r_sleb128 ((const ut8 **)&p, end);
break;
case BIND_OPCODE_SET_SEGMENT_AND_OFFSET_ULEB:
seg_idx = imm;
if (seg_idx >= bin->nsegs) {
bprintf ("Error: BIND_OPCODE_SET_SEGMENT_AND_OFFSET_ULEB"
" has unexistent segment %d\n", seg_idx);
R_FREE (opcodes);
return false;
} else {
seg_off = read_uleb128 (&p, end);
}
break;
case BIND_OPCODE_ADD_ADDR_ULEB:
seg_off += read_uleb128 (&p, end);
break;
case BIND_OPCODE_DO_BIND:
break;
case BIND_OPCODE_DO_BIND_ADD_ADDR_ULEB:
seg_off += read_uleb128 (&p, end) + wordsize;
break;
case BIND_OPCODE_DO_BIND_ADD_ADDR_IMM_SCALED:
seg_off += (ut64)imm * (ut64)wordsize + wordsize;
break;
case BIND_OPCODE_DO_BIND_ULEB_TIMES_SKIPPING_ULEB:
count = read_uleb128 (&p, end);
skip = read_uleb128 (&p, end);
for (j = 0; j < count; j++) {
seg_off += skip + wordsize;
}
break;
default:
bprintf ("Error: unknown bind opcode 0x%02x in dyld_info\n", *p);
R_FREE (opcodes);
return false;
}
}
R_FREE (opcodes);
return true;
}

long do_mmuext_op(
XEN_GUEST_HANDLE_PARAM(mmuext_op_t) uops,
unsigned int count,
XEN_GUEST_HANDLE_PARAM(uint) pdone,
unsigned int foreigndom)
{
struct mmuext_op op;
unsigned long type;
unsigned int i, done = 0;
struct vcpu *curr = current;
struct domain *currd = curr->domain;
struct domain *pg_owner;
int rc = put_old_guest_table(curr);
if ( unlikely(rc) )
{
if ( likely(rc == -ERESTART) )
rc = hypercall_create_continuation(
__HYPERVISOR_mmuext_op, "hihi", uops, count, pdone,
foreigndom);
return rc;
}
if ( unlikely(count == MMU_UPDATE_PREEMPTED) &&
likely(guest_handle_is_null(uops)) )
{
return (int)foreigndom;
}
if ( unlikely(count & MMU_UPDATE_PREEMPTED) )
{
count &= ~MMU_UPDATE_PREEMPTED;
if ( unlikely(!guest_handle_is_null(pdone)) )
(void)copy_from_guest(&done, pdone, 1);
}
else
perfc_incr(calls_to_mmuext_op);
if ( unlikely(!guest_handle_okay(uops, count)) )
return -EFAULT;
if ( (pg_owner = get_pg_owner(foreigndom)) == NULL )
return -ESRCH;
if ( !is_pv_domain(pg_owner) )
{
put_pg_owner(pg_owner);
return -EINVAL;
}
rc = xsm_mmuext_op(XSM_TARGET, currd, pg_owner);
if ( rc )
{
put_pg_owner(pg_owner);
return rc;
}
for ( i = 0; i < count; i++ )
{
if ( curr->arch.old_guest_table || (i && hypercall_preempt_check()) )
{
rc = -ERESTART;
break;
}
if ( unlikely(__copy_from_guest(&op, uops, 1) != 0) )
{
rc = -EFAULT;
break;
}
if ( is_hvm_domain(currd) )
{
switch ( op.cmd )
{
case MMUEXT_PIN_L1_TABLE:
case MMUEXT_PIN_L2_TABLE:
case MMUEXT_PIN_L3_TABLE:
case MMUEXT_PIN_L4_TABLE:
case MMUEXT_UNPIN_TABLE:
break;
default:
rc = -EOPNOTSUPP;
goto done;
}
}
rc = 0;
switch ( op.cmd )
{
struct page_info *page;
p2m_type_t p2mt;
case MMUEXT_PIN_L1_TABLE:
type = PGT_l1_page_table;
goto pin_page;
case MMUEXT_PIN_L2_TABLE:
type = PGT_l2_page_table;
goto pin_page;
case MMUEXT_PIN_L3_TABLE:
type = PGT_l3_page_table;
goto pin_page;
case MMUEXT_PIN_L4_TABLE:
if ( is_pv_32bit_domain(pg_owner) )
break;
type = PGT_l4_page_table;
pin_page:
if ( (op.cmd - MMUEXT_PIN_L1_TABLE) > (CONFIG_PAGING_LEVELS - 1) )
break;
if ( paging_mode_refcounts(pg_owner) )
break;
page = get_page_from_gfn(pg_owner, op.arg1.mfn, NULL, P2M_ALLOC);
if ( unlikely(!page) )
{
rc = -EINVAL;
break;
}
rc = get_page_type_preemptible(page, type);
if ( unlikely(rc) )
{
if ( rc == -EINTR )
rc = -ERESTART;
else if ( rc != -ERESTART )
gdprintk(XENLOG_WARNING,
"Error %d while pinning mfn %" PRI_mfn "\n",
rc, mfn_x(page_to_mfn(page)));
if ( page != curr->arch.old_guest_table )
put_page(page);
break;
}
rc = xsm_memory_pin_page(XSM_HOOK, currd, pg_owner, page);
if ( !rc && unlikely(test_and_set_bit(_PGT_pinned,
&page->u.inuse.type_info)) )
{
gdprintk(XENLOG_WARNING,
"mfn %" PRI_mfn " already pinned\n",
mfn_x(page_to_mfn(page)));
rc = -EINVAL;
}
if ( unlikely(rc) )
goto pin_drop;
paging_mark_dirty(pg_owner, page_to_mfn(page));
if ( unlikely(pg_owner != currd) )
{
bool drop_ref;
spin_lock(&pg_owner->page_alloc_lock);
drop_ref = (pg_owner->is_dying &&
test_and_clear_bit(_PGT_pinned,
&page->u.inuse.type_info));
spin_unlock(&pg_owner->page_alloc_lock);
if ( drop_ref )
{
pin_drop:
if ( type == PGT_l1_page_table )
put_page_and_type(page);
else
curr->arch.old_guest_table = page;
}
}
break;
case MMUEXT_UNPIN_TABLE:
if ( paging_mode_refcounts(pg_owner) )
break;
page = get_page_from_gfn(pg_owner, op.arg1.mfn, NULL, P2M_ALLOC);
if ( unlikely(!page) )
{
gdprintk(XENLOG_WARNING,
"mfn %" PRI_mfn " bad, or bad owner d%d\n",
op.arg1.mfn, pg_owner->domain_id);
rc = -EINVAL;
break;
}
if ( !test_and_clear_bit(_PGT_pinned, &page->u.inuse.type_info) )
{
put_page(page);
gdprintk(XENLOG_WARNING,
"mfn %" PRI_mfn " not pinned\n", op.arg1.mfn);
rc = -EINVAL;
break;
}
switch ( rc = put_page_and_type_preemptible(page) )
{
case -EINTR:
case -ERESTART:
curr->arch.old_guest_table = page;
rc = 0;
break;
default:
BUG_ON(rc);
break;
}
put_page(page);
paging_mark_dirty(pg_owner, page_to_mfn(page));
break;
case MMUEXT_NEW_BASEPTR:
if ( unlikely(currd != pg_owner) )
rc = -EPERM;
else if ( unlikely(paging_mode_translate(currd)) )
rc = -EINVAL;
else
rc = new_guest_cr3(_mfn(op.arg1.mfn));
break;
case MMUEXT_NEW_USER_BASEPTR: {
unsigned long old_mfn;
if ( unlikely(currd != pg_owner) )
rc = -EPERM;
else if ( unlikely(paging_mode_translate(currd)) )
rc = -EINVAL;
if ( unlikely(rc) )
break;
old_mfn = pagetable_get_pfn(curr->arch.guest_table_user);
if ( old_mfn == op.arg1.mfn )
break;
if ( op.arg1.mfn != 0 )
{
rc = get_page_and_type_from_mfn(
_mfn(op.arg1.mfn), PGT_root_page_table, currd, 0, 1);
if ( unlikely(rc) )
{
if ( rc == -EINTR )
rc = -ERESTART;
else if ( rc != -ERESTART )
gdprintk(XENLOG_WARNING,
"Error %d installing new mfn %" PRI_mfn "\n",
rc, op.arg1.mfn);
break;
}
if ( VM_ASSIST(currd, m2p_strict) )
zap_ro_mpt(_mfn(op.arg1.mfn));
}
curr->arch.guest_table_user = pagetable_from_pfn(op.arg1.mfn);
if ( old_mfn != 0 )
{
page = mfn_to_page(_mfn(old_mfn));
switch ( rc = put_page_and_type_preemptible(page) )
{
case -EINTR:
rc = -ERESTART;
case -ERESTART:
curr->arch.old_guest_table = page;
break;
default:
BUG_ON(rc);
break;
}
}
break;
}
case MMUEXT_TLB_FLUSH_LOCAL:
if ( likely(currd == pg_owner) )
flush_tlb_local();
else
rc = -EPERM;
break;
case MMUEXT_INVLPG_LOCAL:
if ( unlikely(currd != pg_owner) )
rc = -EPERM;
else
paging_invlpg(curr, op.arg1.linear_addr);
break;
case MMUEXT_TLB_FLUSH_MULTI:
case MMUEXT_INVLPG_MULTI:
{
cpumask_t *mask = this_cpu(scratch_cpumask);
if ( unlikely(currd != pg_owner) )
rc = -EPERM;
else if ( unlikely(vcpumask_to_pcpumask(currd,
guest_handle_to_param(op.arg2.vcpumask,
const_void),
mask)) )
rc = -EINVAL;
if ( unlikely(rc) )
break;
if ( op.cmd == MMUEXT_TLB_FLUSH_MULTI )
flush_tlb_mask(mask);
else if ( __addr_ok(op.arg1.linear_addr) )
flush_tlb_one_mask(mask, op.arg1.linear_addr);
break;
}
case MMUEXT_TLB_FLUSH_ALL:
if ( likely(currd == pg_owner) )
flush_tlb_mask(currd->domain_dirty_cpumask);
else
rc = -EPERM;
break;
case MMUEXT_INVLPG_ALL:
if ( unlikely(currd != pg_owner) )
rc = -EPERM;
else if ( __addr_ok(op.arg1.linear_addr) )
flush_tlb_one_mask(currd->domain_dirty_cpumask,
op.arg1.linear_addr);
break;
case MMUEXT_FLUSH_CACHE:
if ( unlikely(currd != pg_owner) )
rc = -EPERM;
else if ( unlikely(!cache_flush_permitted(currd)) )
rc = -EACCES;
else
wbinvd();
break;
case MMUEXT_FLUSH_CACHE_GLOBAL:
if ( unlikely(currd != pg_owner) )
rc = -EPERM;
else if ( likely(cache_flush_permitted(currd)) )
{
unsigned int cpu;
cpumask_t *mask = this_cpu(scratch_cpumask);
cpumask_clear(mask);
for_each_online_cpu(cpu)
if ( !cpumask_intersects(mask,
per_cpu(cpu_sibling_mask, cpu)) )
__cpumask_set_cpu(cpu, mask);
flush_mask(mask, FLUSH_CACHE);
}
else
rc = -EINVAL;
break;
case MMUEXT_SET_LDT:
{
unsigned int ents = op.arg2.nr_ents;
unsigned long ptr = ents ? op.arg1.linear_addr : 0;
if ( unlikely(currd != pg_owner) )
rc = -EPERM;
else if ( paging_mode_external(currd) )
rc = -EINVAL;
else if ( ((ptr & (PAGE_SIZE - 1)) != 0) || !__addr_ok(ptr) ||
(ents > 8192) )
{
gdprintk(XENLOG_WARNING,
"Bad args to SET_LDT: ptr=%lx, ents=%x\n", ptr, ents);
rc = -EINVAL;
}
else if ( (curr->arch.pv_vcpu.ldt_ents != ents) ||
(curr->arch.pv_vcpu.ldt_base != ptr) )
{
invalidate_shadow_ldt(curr, 0);
flush_tlb_local();
curr->arch.pv_vcpu.ldt_base = ptr;
curr->arch.pv_vcpu.ldt_ents = ents;
load_LDT(curr);
}
break;
}
case MMUEXT_CLEAR_PAGE:
page = get_page_from_gfn(pg_owner, op.arg1.mfn, &p2mt, P2M_ALLOC);
if ( unlikely(p2mt != p2m_ram_rw) && page )
{
put_page(page);
page = NULL;
}
if ( !page || !get_page_type(page, PGT_writable_page) )
{
if ( page )
put_page(page);
gdprintk(XENLOG_WARNING,
"Error clearing mfn %" PRI_mfn "\n", op.arg1.mfn);
rc = -EINVAL;
break;
}
paging_mark_dirty(pg_owner, page_to_mfn(page));
clear_domain_page(page_to_mfn(page));
put_page_and_type(page);
break;
case MMUEXT_COPY_PAGE:
{
struct page_info *src_page, *dst_page;
src_page = get_page_from_gfn(pg_owner, op.arg2.src_mfn, &p2mt,
P2M_ALLOC);
if ( unlikely(p2mt != p2m_ram_rw) && src_page )
{
put_page(src_page);
src_page = NULL;
}
if ( unlikely(!src_page) )
{
gdprintk(XENLOG_WARNING,
"Error copying from mfn %" PRI_mfn "\n",
op.arg2.src_mfn);
rc = -EINVAL;
break;
}
dst_page = get_page_from_gfn(pg_owner, op.arg1.mfn, &p2mt,
P2M_ALLOC);
if ( unlikely(p2mt != p2m_ram_rw) && dst_page )
{
put_page(dst_page);
dst_page = NULL;
}
rc = (dst_page &&
get_page_type(dst_page, PGT_writable_page)) ? 0 : -EINVAL;
if ( unlikely(rc) )
{
put_page(src_page);
if ( dst_page )
put_page(dst_page);
gdprintk(XENLOG_WARNING,
"Error copying to mfn %" PRI_mfn "\n", op.arg1.mfn);
break;
}
paging_mark_dirty(pg_owner, page_to_mfn(dst_page));
copy_domain_page(page_to_mfn(dst_page), page_to_mfn(src_page));
put_page_and_type(dst_page);
put_page(src_page);
break;
}
case MMUEXT_MARK_SUPER:
case MMUEXT_UNMARK_SUPER:
rc = -EOPNOTSUPP;
break;
default:
rc = -ENOSYS;
break;
}
done:
if ( unlikely(rc) )
break;
guest_handle_add_offset(uops, 1);
}
if ( rc == -ERESTART )
{
ASSERT(i < count);
rc = hypercall_create_continuation(
__HYPERVISOR_mmuext_op, "hihi",
uops, (count - i) | MMU_UPDATE_PREEMPTED, pdone, foreigndom);
}
else if ( curr->arch.old_guest_table )
{
XEN_GUEST_HANDLE_PARAM(void) null;
ASSERT(rc || i == count);
set_xen_guest_handle(null, NULL);
rc = hypercall_create_continuation(
__HYPERVISOR_mmuext_op, "hihi", null,
MMU_UPDATE_PREEMPTED, null, rc);
}
put_pg_owner(pg_owner);
perfc_add(num_mmuext_ops, i);
if ( unlikely(!guest_handle_is_null(pdone)) )
{
done += i;
copy_to_guest(pdone, &done, 1);
}
return rc;
}

static uint8_t excluded_channels(bitfile *ld, drc_info *drc)
{
uint8_t i, n = 0;
uint8_t num_excl_chan = 7;
for (i = 0; i < 7; i++)
{
drc->exclude_mask[i] = faad_get1bit(ld
DEBUGVAR(1,103,"excluded_channels(): exclude_mask"));
}
n++;
while ((drc->additional_excluded_chns[n-1] = faad_get1bit(ld
DEBUGVAR(1,104,"excluded_channels(): additional_excluded_chns"))) == 1)
{
for (i = num_excl_chan; i < num_excl_chan+7; i++)
{
drc->exclude_mask[i] = faad_get1bit(ld
DEBUGVAR(1,105,"excluded_channels(): exclude_mask"));
}
n++;
num_excl_chan += 7;
}
return n;
}

static int sockfs_setattr(struct dentry *dentry, struct iattr *iattr)
