void id3dmx_flush(GF_Filter *filter, u8 *id3_buf, u32 id3_buf_size, GF_FilterPid *audio_pid, GF_FilterPid **video_pid_p)
{
GF_BitStream *bs = gf_bs_new(id3_buf, id3_buf_size, GF_BITSTREAM_READ);
char *sep_desc;
char *_buf=NULL;
u32 buf_alloc=0;
gf_bs_skip_bytes(bs, 3);
gf_bs_read_u8(bs);
gf_bs_read_u8(bs);
gf_bs_read_int(bs, 1);
u8 ext_hdr = gf_bs_read_int(bs, 1);
gf_bs_read_int(bs, 6);
u32 size = gf_id3_read_size(bs);
if (ext_hdr) {
}
while (size && (gf_bs_available(bs)>=10) ) {
char *buf;
char szTag[1024];
char *sep;
s32 tag_idx;
u32 pic_size;
u32 ftag = gf_bs_read_u32(bs);
u32 fsize = gf_id3_read_size(bs);
gf_bs_read_u16(bs);
size -= 10;
if (!fsize)
break;
if (size<fsize) {
GF_LOG(GF_LOG_ERROR, GF_LOG_MEDIA, ("[MP3Dmx] Broken ID3 frame tag %s, size %d but remaining bytes %d\n", gf_4cc_to_str(ftag), fsize, size));
break;
}
if (buf_alloc<=fsize) {
_buf = gf_realloc(_buf, fsize+3);
buf_alloc = fsize+3;
}
gf_bs_read_data(bs, _buf+1, fsize);
_buf[fsize+1]=0;
_buf[fsize+2]=0;
buf = _buf+1;
tag_idx = gf_itags_find_by_id3tag(ftag);
if (ftag==GF_ID3V2_FRAME_TXXX) {
sep = memchr(buf, 0, fsize);
if (sep) {
if (!stricmp(buf+1, "comment")) {
id3dmx_set_string(audio_pid, "comment", sep+1, GF_FALSE);
} else {
strcpy(szTag, "tag_");
strncat(szTag, buf+1, 1019);
id3dmx_set_string(audio_pid, szTag, sep+1, GF_TRUE);
}
}
} else if (ftag == GF_ID3V2_FRAME_APIC) {
sep = memchr(buf+1, 0, fsize-1);
sep_desc = memchr(sep+2, 0, fsize-1);
if (sep_desc) {
GF_Err e;
pic_size = (u32) ( (sep_desc + 1) - buf);
pic_size = fsize - pic_size;
if (video_pid_p) {
e = gf_filter_pid_raw_new(filter, NULL, NULL, buf+1, NULL, sep_desc+1, pic_size, GF_FALSE, video_pid_p);
if (e) {
GF_LOG(GF_LOG_ERROR, GF_LOG_MEDIA, ("[MP3Dmx] error setting up video pid for cover art: %s\n", gf_error_to_string(e) ));
}
if (*video_pid_p) {
u8 *out_buffer;
GF_FilterPacket *dst_pck;
gf_filter_pid_set_name(*video_pid_p, "CoverArt");
gf_filter_pid_set_property(*video_pid_p, GF_PROP_PID_COVER_ART, &PROP_BOOL(GF_TRUE));
dst_pck = gf_filter_pck_new_alloc(*video_pid_p, pic_size, &out_buffer);
if (dst_pck) {
gf_filter_pck_set_framing(dst_pck, GF_TRUE, GF_TRUE);
memcpy(out_buffer, sep_desc+1, pic_size);
gf_filter_pck_send(dst_pck);
}
gf_filter_pid_set_eos(*video_pid_p);
}
} else {
gf_filter_pid_set_property(audio_pid, GF_PROP_PID_COVER_ART, &PROP_DATA(sep_desc+1, pic_size) );
}
}
} else if (tag_idx>=0) {
const char *tag_name = gf_itags_get_name((u32) tag_idx);
id3dmx_set_string(audio_pid, (char *) tag_name, buf+1, GF_FALSE);
} else {
sprintf(szTag, "tag_%s", gf_4cc_to_str(ftag));
if ((ftag>>24) == 'T') {
id3dmx_set_string(audio_pid, szTag, buf+1, GF_TRUE);
} else {
gf_filter_pid_set_property_dyn(audio_pid, szTag, &PROP_DATA(buf, fsize) );
}
}
size -= fsize;
}
gf_bs_del(bs);
if (_buf) gf_free(_buf);
}

void RGWCivetWeb::init_env(CephContext *cct)
{
env.init(cct);
const struct mg_request_info* info = mg_get_request_info(conn);
if (! info) {
return;
}
for (int i = 0; i < info->num_headers; i++) {
const struct mg_request_info::mg_header* header = &info->http_headers[i];
const boost::string_ref name(header->name);
const auto& value = header->value;
if (boost::algorithm::iequals(name, "content-length")) {
env.set("CONTENT_LENGTH", value);
continue;
}
if (boost::algorithm::iequals(name, "content-type")) {
env.set("CONTENT_TYPE", value);
continue;
}
if (boost::algorithm::iequals(name, "connection")) {
explicit_keepalive = boost::algorithm::iequals(value, "keep-alive");
explicit_conn_close = boost::algorithm::iequals(value, "close");
}
static const boost::string_ref HTTP_{"HTTP_"};
char buf[name.size() + HTTP_.size() + 1];
auto dest = std::copy(std::begin(HTTP_), std::end(HTTP_), buf);
for (auto src = name.begin(); src != name.end(); ++src, ++dest) {
if (*src == '-') {
*dest = '_';
} else {
*dest = std::toupper(*src);
}
}
*dest = '\0';
env.set(buf, value);
}
env.set("REMOTE_ADDR", info->remote_addr);
env.set("REQUEST_METHOD", info->request_method);
env.set("HTTP_VERSION", info->http_version);
env.set("REQUEST_URI", info->request_uri);   env.set("SCRIPT_URI", info->uri); 
if (info->query_string) {
env.set("QUERY_STRING", info->query_string);
}
if (info->remote_user) {
env.set("REMOTE_USER", info->remote_user);
}
if (port <= 0)
lderr(cct) << "init_env: bug: invalid port number" << dendl;
char port_buf[16];
snprintf(port_buf, sizeof(port_buf), "%d", port);
env.set("SERVER_PORT", port_buf);
if (info->is_ssl) {
env.set("SERVER_PORT_SECURE", port_buf);
}
}

ecma_value_t
ecma_regexp_match_helper (ecma_value_t this_arg, 
ecma_value_t string_arg) 
{
if (!ecma_is_value_object (this_arg))
{
return ecma_raise_type_error (ECMA_ERR_MSG ("Argument 'this' is not an object"));
}
ecma_string_t *str_p = ecma_op_to_string (string_arg);
if (JERRY_UNLIKELY (str_p == NULL))
{
return ECMA_VALUE_ERROR;
}
ecma_object_t *obj_p = ecma_get_object_from_value (this_arg);
ecma_value_t global_value = ecma_op_object_get_by_magic_id (obj_p, LIT_MAGIC_STRING_GLOBAL);
if (ECMA_IS_VALUE_ERROR (global_value))
{
ecma_deref_ecma_string (str_p);
return global_value;
}
bool global = ecma_op_to_boolean (global_value);
ecma_free_value (global_value);
if (!global)
{
ecma_value_t result = ecma_op_regexp_exec (this_arg, str_p);
ecma_deref_ecma_string (str_p);
return result;
}
#if JERRY_ESNEXT
ecma_value_t full_unicode_value = ecma_op_object_get_by_magic_id (obj_p, LIT_MAGIC_STRING_UNICODE);
if (ECMA_IS_VALUE_ERROR (full_unicode_value))
{
ecma_deref_ecma_string (str_p);
return full_unicode_value;
}
bool full_unicode = ecma_op_to_boolean (full_unicode_value);
ecma_free_value (full_unicode_value);
#endif 
ecma_value_t set_status = ecma_op_object_put (obj_p,
ecma_get_magic_string (LIT_MAGIC_STRING_LASTINDEX_UL),
ecma_make_uint32_value (0),
true);
if (ECMA_IS_VALUE_ERROR (set_status))
{
ecma_deref_ecma_string (str_p);
return set_status;
}
ecma_value_t ret_value = ECMA_VALUE_ERROR;
ecma_object_t *result_array_p = ecma_op_new_array_object (0);
uint32_t n = 0;
while (true)
{
ecma_value_t result_value = ecma_op_regexp_exec (this_arg, str_p);
if (ECMA_IS_VALUE_ERROR (result_value))
{
goto result_cleanup;
}
if (ecma_is_value_null (result_value))
{
if (n == 0)
{
ret_value = ECMA_VALUE_NULL;
goto result_cleanup;
}
ecma_deref_ecma_string (str_p);
return ecma_make_object_value (result_array_p);
}
ecma_object_t *result_value_p = ecma_get_object_from_value (result_value);
ecma_value_t match_value = ecma_op_object_get_by_index (result_value_p, 0);
ecma_deref_object (result_value_p);
if (ECMA_IS_VALUE_ERROR (match_value))
{
goto result_cleanup;
}
ecma_string_t *match_str_p = ecma_op_to_string (match_value);
ecma_free_value (match_value);
if (JERRY_UNLIKELY (match_str_p == NULL))
{
goto result_cleanup;
}
ecma_value_t new_prop = ecma_builtin_helper_def_prop_by_index (result_array_p,
n,
ecma_make_string_value (match_str_p),
ECMA_PROPERTY_CONFIGURABLE_ENUMERABLE_WRITABLE);
JERRY_ASSERT (!ECMA_IS_VALUE_ERROR (new_prop));
const bool is_match_empty = ecma_string_is_empty (match_str_p);
ecma_deref_ecma_string (match_str_p);
if (is_match_empty)
{
ecma_value_t last_index = ecma_op_object_get_by_magic_id (obj_p, LIT_MAGIC_STRING_LASTINDEX_UL);
if (ECMA_IS_VALUE_ERROR (last_index))
{
goto result_cleanup;
}
#if JERRY_ESNEXT
ecma_length_t index;
ecma_value_t length_value = ecma_op_to_length (last_index, &index);
ecma_free_value (last_index);
if (ECMA_IS_VALUE_ERROR (length_value))
{
goto result_cleanup;
}
index = ecma_op_advance_string_index (str_p, index, full_unicode);
last_index = ecma_make_length_value (index);
ecma_value_t next_set_status = ecma_op_object_put (obj_p,
ecma_get_magic_string (LIT_MAGIC_STRING_LASTINDEX_UL),
ecma_make_length_value (index),
true);
#else 
ecma_number_t index = ecma_get_number_from_value (last_index);
ecma_free_value (last_index);
last_index = ecma_make_number_value (index + 1);
ecma_value_t next_set_status = ecma_op_object_put (obj_p,
ecma_get_magic_string (LIT_MAGIC_STRING_LASTINDEX_UL),
last_index,
true);
#endif 
ecma_free_value (last_index);
if (ECMA_IS_VALUE_ERROR (next_set_status))
{
goto result_cleanup;
}
}
n++;
}
result_cleanup:
ecma_deref_ecma_string (str_p);
ecma_deref_object (result_array_p);
return ret_value;
}

