hook_call(isis_hook_lsp_error, circuit, lsp_id, raw_pdu, raw_pdu_len);
nb_notification_send(xpath, arguments);
}

static int dalvik_op(RAnal *anal, RAnalOp *op, ut64 addr, const ut8 *data, int len) {
int sz = dalvik_opcodes[data[0]].len;
if (!op) {
return sz;
}
memset (op, '\0', sizeof (RAnalOp));
op->type = R_ANAL_OP_TYPE_UNK;
op->ptr = UT64_MAX;
op->val = UT64_MAX;
op->jump = UT64_MAX;
op->fail = UT64_MAX;
op->refptr = 0;
op->size = sz;
op->nopcode = 1; op->id = data[0];
switch (data[0]) {
case 0xca: op->family = R_ANAL_OP_FAMILY_FPU;
case 0x1b: case 0x14: case 0x15: case 0x16: case 0x17: case 0x42: case 0x12: op->type = R_ANAL_OP_TYPE_MOV;
{
ut32 vB = (data[1] & 0x0f);
ut32 vA = (data[1] & 0xf0) >> 4;
op->ptr = -vA; op->val = vA;
esilprintf (op, "0x%"PFMT64x",v%d,=", vA, vB);
}
break;
case 0x01: case 0x07: case 0x04: op->type = R_ANAL_OP_TYPE_MOV;
{
ut32 vB = (data[1] & 0x0f);
ut32 vA = (data[1] & 0xf0) >> 4;
op->stackop = R_ANAL_STACK_SET;
op->ptr = -vA;
esilprintf (op, "v%d,v%d,=", vA, vB);
}
break;
case 0x02: case 0x03: case 0x05: case 0x06: case 0x08: case 0x09: case 0x13: case 0x18: case 0x19: op->type = R_ANAL_OP_TYPE_MOV;
{
int vA = (int) data[1];
ut32 vB = (data[3] << 8) | data[2];
esilprintf (op, "v%d,v%d,=", vA, vB);
op->val = vB;
}
break;
case 0x0a: case 0x0d: case 0x0c: case 0x0b:  op->type = R_ANAL_OP_TYPE_MOV;
{
ut32 vA = data[1];
esilprintf (op, "sp,v%d,=[8],8,sp,+=,8", vA);
}
break;
case 0x1a: op->type = R_ANAL_OP_TYPE_MOV;
{
ut32 vA = data[1];
ut32 vB = (data[3]<<8) | data[2];
ut64 offset = R_ANAL_GET_OFFSET (anal, 's', vB);
op->ptr = offset;
esilprintf (op, "0x%"PFMT64x",v%d,=", offset, vA);
}
break;
case 0x1c: op->type = R_ANAL_OP_TYPE_MOV;
break;
case 0x85: case 0x8e: case 0x89: case 0x8a: case 0x87: case 0x8c: case 0x8b: case 0x88: case 0x86: op->family = R_ANAL_OP_FAMILY_FPU;
case 0x81: case 0x82: case 0x83: case 0x84: case 0x8d: case 0x8f: case 0x20: op->type = R_ANAL_OP_TYPE_CAST;
break;
case 0x21: op->type = R_ANAL_OP_TYPE_LENGTH;
break;
case 0x44: case 0x45: case 0x46:
case 0x47: case 0x48: case 0x49: case 0x4a: case 0x52: case 0x58: case 0x53: case 0x56: case 0x57: case 0xea: case 0x63: case 0xf4: case 0x66: case 0xfd: case 0x55: case 0x60: case 0x61: case 0x62: case 0x64: case 0x65: case 0xe3: case 0xe4: case 0xe5: case 0xe6: case 0x54: case 0xe7: case 0xe8: case 0xf3: case 0xf8: case 0xf2: op->type = R_ANAL_OP_TYPE_LOAD;
break;
case 0x6b: case 0x6d: case 0xeb: case 0x4b: case 0x4c: case 0x4d: case 0x4e: case 0x4f: case 0x5e: case 0xfc: case 0xf5: case 0x5c: case 0x69: case 0x5f: case 0xe9: case 0xf6: case 0xf7: case 0x67: case 0x59: case 0x5a: case 0x5b: case 0x5d: case 0x50: case 0x51: case 0x68: case 0x6a: case 0x6c: case 0xfe: op->type = R_ANAL_OP_TYPE_STORE;
{
ut32 vA = (data[1] & 0x0f);
ut32 vB = (data[1] & 0xf0) >> 4;
esilprintf (op, "v%d,v%d,=", vA, vB);
}
break;
case 0x9d:
case 0xad: case 0xc8: op->family = R_ANAL_OP_FAMILY_FPU;
case 0xcd:
case 0xd2:
case 0x92:
case 0xb2:
op->type = R_ANAL_OP_TYPE_MUL;
break;
case 0x7c: case 0x7e: op->type = R_ANAL_OP_TYPE_NOT;
break;
case 0xa4: case 0xba: case 0xe2: case 0xa5: case 0x9a: case 0xc5: case 0xc4: case 0xe1: case 0x99: op->type = R_ANAL_OP_TYPE_SHR;
break;
case 0xaa: case 0xcf: case 0xaf: op->family = R_ANAL_OP_FAMILY_FPU;
case 0xb4: case 0xdc: case 0xd4: case 0xbf: case 0x9f: case 0x94: op->type = R_ANAL_OP_TYPE_MOD; break;
case 0xd7:
case 0xd9:
case 0xda:
case 0xde:
case 0xdf:
case 0x96:
case 0xc2: case 0x97: case 0xa2: op->type = R_ANAL_OP_TYPE_XOR;
break;
case 0xc9: op->family = R_ANAL_OP_FAMILY_FPU;
case 0x93: case 0xd3: case 0xdb: case 0xce: case 0x9e: case 0xbe: case 0xae: case 0xa9: case 0xb3: op->type = R_ANAL_OP_TYPE_DIV;
break;
case 0x0e: case 0x0f: case 0x10: case 0x11: case 0xf1: op->type = R_ANAL_OP_TYPE_RET;
op->eob = true;
if (data[0] == 0x0e) {esilprintf (op, "sp,[8],ip,=,8,sp,+=");
} else {
ut32 vA = data[1];
esilprintf (op, "sp,[8],ip,=,8,sp,+=,8,sp,-=,v%d,sp,=[8]", vA);
}
break;
case 0x28: op->jump = addr + ((char)data[1])*2;
op->type = R_ANAL_OP_TYPE_JMP;
op->eob = true;
esilprintf (op, "0x%"PFMT64x",ip,=", op->jump);
break;
case 0x29: op->jump = addr + (short)(data[2]|data[3]<<8)*2;
op->type = R_ANAL_OP_TYPE_JMP;
op->eob = true;
esilprintf (op, "0x%"PFMT64x",ip,=", op->jump);
break;
case 0x2a: op->jump = addr + (int)(data[2]|(data[3]<<8)|(data[4]<<16)|(data[5]<<24))*2;
op->type = R_ANAL_OP_TYPE_JMP;
op->eob = true;
esilprintf (op, "0x%"PFMT64x",ip,=", op->jump);
break;
case 0x2c:
case 0x2b:
op->type = R_ANAL_OP_TYPE_SWITCH;
break;
case 0x2d: case 0x2e: case 0x3f: case 0x2f: case 0x30: case 0x31: case 0x1f: op->type = R_ANAL_OP_TYPE_CMP;
break;
case 0x32: case 0x33: case 0x34: case 0x35: case 0x36: case 0x37: case 0x38: case 0x39: case 0x3a: case 0x3b: case 0x3c: case 0x3d: op->type = R_ANAL_OP_TYPE_CJMP;
op->jump = addr + (len>3?(short)(data[2]|data[3]<<8)*2 : 0);
op->fail = addr + sz;
op->eob = true;
break;
case 0xec: case 0x1d: op->type = R_ANAL_OP_TYPE_UPUSH;
break;
case 0x1e: op->type = R_ANAL_OP_TYPE_POP;
break;
case 0x6f: case 0xfa: case 0x70: case 0x71: case 0x72: case 0x73: case 0x74: case 0x75: case 0x76: case 0x77: case 0x78: case 0xb9: case 0xb7: case 0xb8: case 0xb6: case 0x6e: case 0xf0: case 0xf9: case 0xfb: {
ut32 vB = len > 3?(data[3] << 8) | data[2] : 0;
op->jump = anal->binb.get_offset (anal->binb.bin, 'm', vB);
op->fail = addr + sz;
op->type = R_ANAL_OP_TYPE_CALL;
esilprintf (op, "8,sp,-=,0x%"PFMT64x",sp,=[8],0x%"PFMT64x",ip,=", addr);
}
break;
case 0x27: case 0xee: case 0xef: case 0xed: op->type = R_ANAL_OP_TYPE_SWI;
break;
#if 0
case 0xbb: case 0xbc: case 0xc5: #endif
case 0x22: case 0x23: case 0x24: case 0x25: case 0x26: op->type = R_ANAL_OP_TYPE_NEW;
{
int vB = (data[3] << 8) | data[2];
ut64 off = R_ANAL_GET_OFFSET (anal, 't', vB);
op->ptr = off;
}
break;
case 0x00: op->type = R_ANAL_OP_TYPE_NOP;
break;
case 0x90: case 0x9b: case 0xa6: case 0xac: case 0xb0: case 0xbb: case 0xc6: case 0xcb: case 0xd0: case 0xd8: op->type = R_ANAL_OP_TYPE_ADD;
break;
case 0xa7: case 0xcc: op->family = R_ANAL_OP_FAMILY_FPU;
case 0xc7:
case 0xbc:
case 0x91:
case 0xb1: case 0xd1: case 0x9c: op->type = R_ANAL_OP_TYPE_SUB;
break;
case 0x7b: case 0x7d: case 0x7f: case 0x80: op->type = R_ANAL_OP_TYPE_NOT;
break;
case 0xa0: case 0xc0: case 0xdd: case 0xd5: case 0x95:
case 0xb5: op->type = R_ANAL_OP_TYPE_AND;
break;
case 0xd6: case 0xc1: case 0xa1: op->type = R_ANAL_OP_TYPE_OR;
break;
case 0xe0: case 0xc3: case 0xa3: case 0x98: op->type = R_ANAL_OP_TYPE_SHL;
break;
}
return sz;
}

static void
diffuse_burkes(unsigned char *data, int width, int height,
int x, int y, int depth, int error)
{
int pos;
pos = y * width + x;
if (pos < (height - 1) * width - 2) {
error_diffuse(data, pos + width * 0 + 1, depth, error, 1, 4);
error_diffuse(data, pos + width * 0 + 2, depth, error, 1, 8);
error_diffuse(data, pos + width * 1 - 2, depth, error, 1, 16);
error_diffuse(data, pos + width * 1 - 1, depth, error, 1, 8);
error_diffuse(data, pos + width * 1 + 0, depth, error, 1, 4);
error_diffuse(data, pos + width * 1 + 1, depth, error, 1, 8);
error_diffuse(data, pos + width * 1 + 2, depth, error, 1, 16);
}
}

EC_GROUP *EC_GROUP_new_from_ecparameters(const ECPARAMETERS *params)
{
int ok = 0, tmp;
EC_GROUP *ret = NULL, *dup = NULL;
BIGNUM *p = NULL, *a = NULL, *b = NULL;
EC_POINT *point = NULL;
long field_bits;
int curve_name = NID_undef;
BN_CTX *ctx = NULL;
if (!params->fieldID || !params->fieldID->fieldType ||
!params->fieldID->p.ptr) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, EC_R_ASN1_ERROR);
goto err;
}
if (!params->curve || !params->curve->a ||
!params->curve->a->data || !params->curve->b ||
!params->curve->b->data) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, EC_R_ASN1_ERROR);
goto err;
}
a = BN_bin2bn(params->curve->a->data, params->curve->a->length, NULL);
if (a == NULL) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, ERR_R_BN_LIB);
goto err;
}
b = BN_bin2bn(params->curve->b->data, params->curve->b->length, NULL);
if (b == NULL) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, ERR_R_BN_LIB);
goto err;
}
tmp = OBJ_obj2nid(params->fieldID->fieldType);
if (tmp == NID_X9_62_characteristic_two_field)
#ifdef OPENSSL_NO_EC2M
{
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, EC_R_GF2M_NOT_SUPPORTED);
goto err;
}
#else
{
X9_62_CHARACTERISTIC_TWO *char_two;
char_two = params->fieldID->p.char_two;
field_bits = char_two->m;
if (field_bits > OPENSSL_ECC_MAX_FIELD_BITS) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, EC_R_FIELD_TOO_LARGE);
goto err;
}
if ((p = BN_new()) == NULL) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, ERR_R_MALLOC_FAILURE);
goto err;
}
tmp = OBJ_obj2nid(char_two->type);
if (tmp == NID_X9_62_tpBasis) {
long tmp_long;
if (!char_two->p.tpBasis) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, EC_R_ASN1_ERROR);
goto err;
}
tmp_long = ASN1_INTEGER_get(char_two->p.tpBasis);
if (!(char_two->m > tmp_long && tmp_long > 0)) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS,
EC_R_INVALID_TRINOMIAL_BASIS);
goto err;
}
if (!BN_set_bit(p, (int)char_two->m))
goto err;
if (!BN_set_bit(p, (int)tmp_long))
goto err;
if (!BN_set_bit(p, 0))
goto err;
} else if (tmp == NID_X9_62_ppBasis) {
X9_62_PENTANOMIAL *penta;
penta = char_two->p.ppBasis;
if (!penta) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, EC_R_ASN1_ERROR);
goto err;
}
if (!
(char_two->m > penta->k3 && penta->k3 > penta->k2
&& penta->k2 > penta->k1 && penta->k1 > 0)) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS,
EC_R_INVALID_PENTANOMIAL_BASIS);
goto err;
}
if (!BN_set_bit(p, (int)char_two->m))
goto err;
if (!BN_set_bit(p, (int)penta->k1))
goto err;
if (!BN_set_bit(p, (int)penta->k2))
goto err;
if (!BN_set_bit(p, (int)penta->k3))
goto err;
if (!BN_set_bit(p, 0))
goto err;
} else if (tmp == NID_X9_62_onBasis) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, EC_R_NOT_IMPLEMENTED);
goto err;
} else {                
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, EC_R_ASN1_ERROR);
goto err;
}
ret = EC_GROUP_new_curve_GF2m(p, a, b, NULL);
}
#endif
else if (tmp == NID_X9_62_prime_field) {
if (!params->fieldID->p.prime) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, EC_R_ASN1_ERROR);
goto err;
}
p = ASN1_INTEGER_to_BN(params->fieldID->p.prime, NULL);
if (p == NULL) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, ERR_R_ASN1_LIB);
goto err;
}
if (BN_is_negative(p) || BN_is_zero(p)) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, EC_R_INVALID_FIELD);
goto err;
}
field_bits = BN_num_bits(p);
if (field_bits > OPENSSL_ECC_MAX_FIELD_BITS) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, EC_R_FIELD_TOO_LARGE);
goto err;
}
ret = EC_GROUP_new_curve_GFp(p, a, b, NULL);
} else {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, EC_R_INVALID_FIELD);
goto err;
}
if (ret == NULL) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, ERR_R_EC_LIB);
goto err;
}
if (params->curve->seed != NULL) {
OPENSSL_free(ret->seed);
if ((ret->seed = OPENSSL_malloc(params->curve->seed->length)) == NULL) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, ERR_R_MALLOC_FAILURE);
goto err;
}
memcpy(ret->seed, params->curve->seed->data,
params->curve->seed->length);
ret->seed_len = params->curve->seed->length;
}
if (!params->order || !params->base || !params->base->data) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, EC_R_ASN1_ERROR);
goto err;
}
if ((point = EC_POINT_new(ret)) == NULL)
goto err;
EC_GROUP_set_point_conversion_form(ret, (point_conversion_form_t)
(params->base->data[0] & ~0x01));
if (!EC_POINT_oct2point(ret, point, params->base->data,
params->base->length, NULL)) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, ERR_R_EC_LIB);
goto err;
}
if ((a = ASN1_INTEGER_to_BN(params->order, a)) == NULL) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, ERR_R_ASN1_LIB);
goto err;
}
if (BN_is_negative(a) || BN_is_zero(a)) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, EC_R_INVALID_GROUP_ORDER);
goto err;
}
if (BN_num_bits(a) > (int)field_bits + 1) { 
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, EC_R_INVALID_GROUP_ORDER);
goto err;
}
if (params->cofactor == NULL) {
BN_free(b);
b = NULL;
} else if ((b = ASN1_INTEGER_to_BN(params->cofactor, b)) == NULL) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, ERR_R_ASN1_LIB);
goto err;
}
if (!EC_GROUP_set_generator(ret, point, a, b)) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, ERR_R_EC_LIB);
goto err;
}
if ((ctx = BN_CTX_new()) == NULL) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, ERR_R_BN_LIB);
goto err;
}
if ((dup = EC_GROUP_dup(ret)) == NULL
|| EC_GROUP_set_seed(dup, NULL, 0) != 1
|| !EC_GROUP_set_generator(dup, point, a, NULL)) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, ERR_R_EC_LIB);
goto err;
}
if ((curve_name = ec_curve_nid_from_params(dup, ctx)) != NID_undef) {
EC_GROUP *named_group = NULL;
#ifndef OPENSSL_NO_EC_NISTP_64_GCC_128
if (curve_name == NID_wap_wsg_idm_ecid_wtls12)
curve_name = NID_secp224r1;
#endif 
if ((named_group = EC_GROUP_new_by_curve_name(curve_name)) == NULL) {
ECerr(EC_F_EC_GROUP_NEW_FROM_ECPARAMETERS, ERR_R_EC_LIB);
goto err;
}
EC_GROUP_free(ret);
ret = named_group;
EC_GROUP_set_asn1_flag(ret, OPENSSL_EC_EXPLICIT_CURVE);
if (params->curve->seed == NULL) {
if (EC_GROUP_set_seed(ret, NULL, 0) != 1)
goto err;
}
}
ok = 1;
err:
if (!ok) {
EC_GROUP_free(ret);
ret = NULL;
}
EC_GROUP_free(dup);
BN_free(p);
BN_free(a);
BN_free(b);
EC_POINT_free(point);
BN_CTX_free(ctx);
return ret;
}

static debug_type
stab_xcoff_builtin_type (void *dhandle, struct stab_handle *info,
int typenum)
{
debug_type rettype;
const char *name;
if (typenum >= 0 || typenum < -XCOFF_TYPE_COUNT)
{
fprintf (stderr, _("Unrecognized XCOFF type %d\n"), typenum);
return DEBUG_TYPE_NULL;
}
if (info->xcoff_types[-typenum] != NULL)
return info->xcoff_types[-typenum];
switch (-typenum)
{
case 1:
name = "int";
rettype = debug_make_int_type (dhandle, 4, false);
break;
case 2:
name = "char";
rettype = debug_make_int_type (dhandle, 1, false);
break;
case 3:
name = "short";
rettype = debug_make_int_type (dhandle, 2, false);
break;
case 4:
name = "long";
rettype = debug_make_int_type (dhandle, 4, false);
break;
case 5:
name = "unsigned char";
rettype = debug_make_int_type (dhandle, 1, true);
break;
case 6:
name = "signed char";
rettype = debug_make_int_type (dhandle, 1, false);
break;
case 7:
name = "unsigned short";
rettype = debug_make_int_type (dhandle, 2, true);
break;
case 8:
name = "unsigned int";
rettype = debug_make_int_type (dhandle, 4, true);
break;
case 9:
name = "unsigned";
rettype = debug_make_int_type (dhandle, 4, true);
break;
case 10:
name = "unsigned long";
rettype = debug_make_int_type (dhandle, 4, true);
break;
case 11:
name = "void";
rettype = debug_make_void_type (dhandle);
break;
case 12:
name = "float";
rettype = debug_make_float_type (dhandle, 4);
break;
case 13:
name = "double";
rettype = debug_make_float_type (dhandle, 8);
break;
case 14:
name = "long double";
rettype = debug_make_float_type (dhandle, 8);
break;
case 15:
name = "integer";
rettype = debug_make_int_type (dhandle, 4, false);
break;
case 16:
name = "boolean";
rettype = debug_make_bool_type (dhandle, 4);
break;
case 17:
name = "short real";
rettype = debug_make_float_type (dhandle, 4);
break;
case 18:
name = "real";
rettype = debug_make_float_type (dhandle, 8);
break;
case 19:
name = "stringptr";
rettype = NULL;
break;
case 20:
name = "character";
rettype = debug_make_int_type (dhandle, 1, true);
break;
case 21:
name = "logical*1";
rettype = debug_make_bool_type (dhandle, 1);
break;
case 22:
name = "logical*2";
rettype = debug_make_bool_type (dhandle, 2);
break;
case 23:
name = "logical*4";
rettype = debug_make_bool_type (dhandle, 4);
break;
case 24:
name = "logical";
rettype = debug_make_bool_type (dhandle, 4);
break;
case 25:
name = "complex";
rettype = debug_make_complex_type (dhandle, 8);
break;
case 26:
name = "double complex";
rettype = debug_make_complex_type (dhandle, 16);
break;
case 27:
name = "integer*1";
rettype = debug_make_int_type (dhandle, 1, false);
break;
case 28:
name = "integer*2";
rettype = debug_make_int_type (dhandle, 2, false);
break;
case 29:
name = "integer*4";
rettype = debug_make_int_type (dhandle, 4, false);
break;
case 30:
name = "wchar";
rettype = debug_make_int_type (dhandle, 2, false);
break;
case 31:
name = "long long";
rettype = debug_make_int_type (dhandle, 8, false);
break;
case 32:
name = "unsigned long long";
rettype = debug_make_int_type (dhandle, 8, true);
break;
case 33:
name = "logical*8";
rettype = debug_make_bool_type (dhandle, 8);
break;
case 34:
name = "integer*8";
rettype = debug_make_int_type (dhandle, 8, false);
break;
default:
abort ();
}
rettype = debug_name_type (dhandle, name, rettype);
info->xcoff_types[-typenum] = rettype;
return rettype;
}

void ati_2d_blt(ATIVGAState *s)
{
DisplaySurface *ds = qemu_console_surface(s->vga.con);
DPRINTF("%p %u ds: %p %d %d rop: %x\n", s->vga.vram_ptr,
s->vga.vbe_start_addr, surface_data(ds), surface_stride(ds),
surface_bits_per_pixel(ds),
(s->regs.dp_mix & GMC_ROP3_MASK) >> 16);
int dst_x = (s->regs.dp_cntl & DST_X_LEFT_TO_RIGHT ?
s->regs.dst_x : s->regs.dst_x + 1 - s->regs.dst_width);
int dst_y = (s->regs.dp_cntl & DST_Y_TOP_TO_BOTTOM ?
s->regs.dst_y : s->regs.dst_y + 1 - s->regs.dst_height);
int bpp = ati_bpp_from_datatype(s);
int dst_stride = DEFAULT_CNTL ? s->regs.dst_pitch : s->regs.default_pitch;
uint8_t *dst_bits = s->vga.vram_ptr + (DEFAULT_CNTL ?
s->regs.dst_offset : s->regs.default_offset);
if (s->dev_id == PCI_DEVICE_ID_ATI_RAGE128_PF) {
dst_bits += s->regs.crtc_offset & 0x07ffffff;
dst_stride *= bpp;
}
uint8_t *end = s->vga.vram_ptr + s->vga.vram_size;
if (dst_bits >= end || dst_bits + dst_x + (dst_y + s->regs.dst_height) *
dst_stride >= end) {
qemu_log_mask(LOG_UNIMP, "blt outside vram not implemented\n");
return;
}
DPRINTF("%d %d %d, %d %d %d, (%d,%d) -> (%d,%d) %dx%d %c %c\n",
s->regs.src_offset, s->regs.dst_offset, s->regs.default_offset,
s->regs.src_pitch, s->regs.dst_pitch, s->regs.default_pitch,
s->regs.src_x, s->regs.src_y, s->regs.dst_x, s->regs.dst_y,
s->regs.dst_width, s->regs.dst_height,
(s->regs.dp_cntl & DST_X_LEFT_TO_RIGHT ? '>' : '<'),
(s->regs.dp_cntl & DST_Y_TOP_TO_BOTTOM ? 'v' : '^'));
switch (s->regs.dp_mix & GMC_ROP3_MASK) {
case ROP3_SRCCOPY:
{
int src_x = (s->regs.dp_cntl & DST_X_LEFT_TO_RIGHT ?
s->regs.src_x : s->regs.src_x + 1 - s->regs.dst_width);
int src_y = (s->regs.dp_cntl & DST_Y_TOP_TO_BOTTOM ?
s->regs.src_y : s->regs.src_y + 1 - s->regs.dst_height);
int src_stride = DEFAULT_CNTL ?
s->regs.src_pitch : s->regs.default_pitch;
uint8_t *src_bits = s->vga.vram_ptr + (DEFAULT_CNTL ?
s->regs.src_offset : s->regs.default_offset);
if (s->dev_id == PCI_DEVICE_ID_ATI_RAGE128_PF) {
src_bits += s->regs.crtc_offset & 0x07ffffff;
src_stride *= bpp;
}
if (src_bits >= end || src_bits + src_x +
(src_y + s->regs.dst_height) * src_stride >= end) {
qemu_log_mask(LOG_UNIMP, "blt outside vram not implemented\n");
return;
}
src_stride /= sizeof(uint32_t);
dst_stride /= sizeof(uint32_t);
DPRINTF("pixman_blt(%p, %p, %d, %d, %d, %d, %d, %d, %d, %d, %d, %d)\n",
src_bits, dst_bits, src_stride, dst_stride, bpp, bpp,
src_x, src_y, dst_x, dst_y,
s->regs.dst_width, s->regs.dst_height);
if (s->regs.dp_cntl & DST_X_LEFT_TO_RIGHT &&
s->regs.dp_cntl & DST_Y_TOP_TO_BOTTOM) {
pixman_blt((uint32_t *)src_bits, (uint32_t *)dst_bits,
src_stride, dst_stride, bpp, bpp,
src_x, src_y, dst_x, dst_y,
s->regs.dst_width, s->regs.dst_height);
} else {
int llb = s->regs.dst_width * (bpp / 8);
int tmp_stride = DIV_ROUND_UP(llb, sizeof(uint32_t));
uint32_t *tmp = g_malloc(tmp_stride * sizeof(uint32_t) *
s->regs.dst_height);
pixman_blt((uint32_t *)src_bits, tmp,
src_stride, tmp_stride, bpp, bpp,
src_x, src_y, 0, 0,
s->regs.dst_width, s->regs.dst_height);
pixman_blt(tmp, (uint32_t *)dst_bits,
tmp_stride, dst_stride, bpp, bpp,
0, 0, dst_x, dst_y,
s->regs.dst_width, s->regs.dst_height);
g_free(tmp);
}
if (dst_bits >= s->vga.vram_ptr + s->vga.vbe_start_addr &&
dst_bits < s->vga.vram_ptr + s->vga.vbe_start_addr +
s->vga.vbe_regs[VBE_DISPI_INDEX_YRES] * s->vga.vbe_line_offset) {
memory_region_set_dirty(&s->vga.vram, s->vga.vbe_start_addr +
s->regs.dst_offset +
dst_y * surface_stride(ds),
s->regs.dst_height * surface_stride(ds));
}
s->regs.dst_x += s->regs.dst_width;
s->regs.dst_y += s->regs.dst_height;
break;
}
case ROP3_PATCOPY:
case ROP3_BLACKNESS:
case ROP3_WHITENESS:
{
uint32_t filler = 0;
switch (s->regs.dp_mix & GMC_ROP3_MASK) {
case ROP3_PATCOPY:
filler = s->regs.dp_brush_frgd_clr;
break;
case ROP3_BLACKNESS:
filler = 0xffUL << 24 | rgb_to_pixel32(s->vga.palette[0],
s->vga.palette[1], s->vga.palette[2]);
break;
case ROP3_WHITENESS:
filler = 0xffUL << 24 | rgb_to_pixel32(s->vga.palette[3],
s->vga.palette[4], s->vga.palette[5]);
break;
}
dst_stride /= sizeof(uint32_t);
DPRINTF("pixman_fill(%p, %d, %d, %d, %d, %d, %d, %x)\n",
dst_bits, dst_stride, bpp,
s->regs.dst_x, s->regs.dst_y,
s->regs.dst_width, s->regs.dst_height,
filler);
pixman_fill((uint32_t *)dst_bits, dst_stride, bpp,
s->regs.dst_x, s->regs.dst_y,
s->regs.dst_width, s->regs.dst_height,
filler);
if (dst_bits >= s->vga.vram_ptr + s->vga.vbe_start_addr &&
dst_bits < s->vga.vram_ptr + s->vga.vbe_start_addr +
s->vga.vbe_regs[VBE_DISPI_INDEX_YRES] * s->vga.vbe_line_offset) {
memory_region_set_dirty(&s->vga.vram, s->vga.vbe_start_addr +
s->regs.dst_offset +
dst_y * surface_stride(ds),
s->regs.dst_height * surface_stride(ds));
}
s->regs.dst_y += s->regs.dst_height;
break;
}
default:
qemu_log_mask(LOG_UNIMP, "Unimplemented ati_2d blt op %x\n",
(s->regs.dp_mix & GMC_ROP3_MASK) >> 16);
}
}

static int read_next_pam_token(struct iwpnmrcontext *rctx,
const char *linebuf, char *tokenbuf, int tokenbuflen, int *curpos)
{
iw_byte b;
int token_len = 0;
int linepos;
token_len = 0;
linepos = *curpos;
while(1) {
if(token_len >= tokenbuflen) {
return 0;
}
b = linebuf[linepos++];
if(b==0) break; 
if(iwpnm_is_whitespace(b)) {
if(token_len>0) {
break;
}
else {
continue;
}
}
else {
tokenbuf[token_len] = b;
token_len++;
}
}
tokenbuf[token_len] = '\0';
*curpos = linepos;
return 1;
}

static void stub_disconnect(struct usb_device *udev)
{
struct stub_device *sdev;
const char *udev_busid = dev_name(&udev->dev);
struct bus_id_priv *busid_priv;
int rc;
dev_dbg(&udev->dev, "Enter disconnect\n");
busid_priv = get_busid_priv(udev_busid);
if (!busid_priv) {
BUG();
return;
}
sdev = dev_get_drvdata(&udev->dev);
if (!sdev) {
dev_err(&udev->dev, "could not get device");
return;
}
dev_set_drvdata(&udev->dev, NULL);
stub_remove_files(&udev->dev);
rc = usb_hub_release_port(udev->parent, udev->portnum,
(struct usb_dev_state *) udev);
if (rc) {
dev_dbg(&udev->dev, "unable to release port\n");
return;
}
if (usbip_in_eh(current))
return;
shutdown_busid(busid_priv);
usb_put_dev(sdev->udev);
busid_priv->sdev = NULL;
stub_device_free(sdev);
if (busid_priv->status == STUB_BUSID_ALLOC)
busid_priv->status = STUB_BUSID_ADDED;
}

static gint
read_creator_block (FILE     *f,
gint      image_ID,
guint     total_len,
PSPimage *ia)
{
long          data_start;
guchar        buf[4];
guint16       keyword;
guint32       length;
gchar        *string;
gchar        *title = NULL, *artist = NULL, *copyright = NULL, *description = NULL;
guint32       dword;
guint32       __attribute__((unused))cdate = 0;
guint32       __attribute__((unused))mdate = 0;
guint32       __attribute__((unused))appid;
guint32       __attribute__((unused))appver;
GString      *comment;
GimpParasite *comment_parasite;
data_start = ftell (f);
comment = g_string_new (NULL);
while (ftell (f) < data_start + total_len)
{
if (fread (buf, 4, 1, f) < 1
|| fread (&keyword, 2, 1, f) < 1
|| fread (&length, 4, 1, f) < 1)
{
g_message ("Error reading creator keyword chunk");
return -1;
}
if (memcmp (buf, "~FL\0", 4) != 0)
{
g_message ("Invalid keyword chunk header");
return -1;
}
keyword = GUINT16_FROM_LE (keyword);
length = GUINT32_FROM_LE (length);
switch (keyword)
{
case PSP_CRTR_FLD_TITLE:
case PSP_CRTR_FLD_ARTIST:
case PSP_CRTR_FLD_CPYRGHT:
case PSP_CRTR_FLD_DESC:
string = g_malloc (length + 1);
if (fread (string, length, 1, f) < 1)
{
g_message ("Error reading creator keyword data");
g_free (string);
return -1;
}
switch (keyword)
{
case PSP_CRTR_FLD_TITLE:
g_free (title); title = string; break;
case PSP_CRTR_FLD_ARTIST:
g_free (artist); artist = string; break;
case PSP_CRTR_FLD_CPYRGHT:
g_free (copyright); copyright = string; break;
case PSP_CRTR_FLD_DESC:
g_free (description); description = string; break;
default:
g_free (string);
}
break;
case PSP_CRTR_FLD_CRT_DATE:
case PSP_CRTR_FLD_MOD_DATE:
case PSP_CRTR_FLD_APP_ID:
case PSP_CRTR_FLD_APP_VER:
if (fread (&dword, 4, 1, f) < 1)
{
g_message ("Error reading creator keyword data");
return -1;
}
switch (keyword)
{
case PSP_CRTR_FLD_CRT_DATE:
cdate = dword; break;
case PSP_CRTR_FLD_MOD_DATE:
mdate = dword; break;
case PSP_CRTR_FLD_APP_ID:
appid = dword; break;
case PSP_CRTR_FLD_APP_VER:
appver = dword; break;
}
break;
default:
if (try_fseek (f, length, SEEK_CUR) < 0)
{
return -1;
}
break;
}
}
if (title)
{
g_string_append (comment, title);
g_free (title);
g_string_append (comment, "\n");
}
if (artist)
{
g_string_append (comment, artist);
g_free (artist);
g_string_append (comment, "\n");
}
if (copyright)
{
g_string_append (comment, "Copyright ");
g_string_append (comment, copyright);
g_free (copyright);
g_string_append (comment, "\n");
}
if (description)
{
g_string_append (comment, description);
g_free (description);
g_string_append (comment, "\n");
}
if (comment->len > 0)
{
comment_parasite = gimp_parasite_new ("gimp-comment",
GIMP_PARASITE_PERSISTENT,
strlen (comment->str) + 1,
comment->str);
gimp_image_attach_parasite (image_ID, comment_parasite);
gimp_parasite_free (comment_parasite);
}
g_string_free (comment, FALSE);
return 0;
}

