static int
ep_print_image(gp_file *prn_stream, ep_globals *eg, char cmd, byte *data, int size)
{
int i, real_rows;
static const char color[4] = {4,1,2,0};
switch (cmd) {
case 3:
case 2:
case 1:
case 0:
memcpy(eg->raster_buf[((int) cmd)][eg->ln_idx+eg->vskip2], data, size);
return 0;
case 'B':
if (!eg->ln_idx) {
eg->vskip1 += size;
} else if (size >= eg->img_rows - (eg->ln_idx+eg->vskip2) || eg->ln_idx+eg->vskip2 >= min_rows) {
eg->vskip2 += size;
ep_print_image(prn_stream, eg, 'F', 0, 0); 
} else {
eg->vskip2 += size;
}
return 0;
case 'I':
eg->ln_idx += eg->vskip2 + 1;
eg->vskip2 = 0;
if (eg->ln_idx < eg->img_rows) return 0;
case 'F':
if (!eg->ln_idx) return 0;
while (eg->vskip1 >= (255*2)) {
gp_fputs("\033J\377", prn_stream); 
eg->vskip1 -= (255*2);
}
if (eg->vskip1 > 255) {
gp_fputs("\033J\200", prn_stream);
eg->vskip1 -= 256;
}
if (eg->vskip1) {
gp_fputs("\033|J", prn_stream); gp_fputc(0, prn_stream); gp_fputc(eg->vskip1, prn_stream);
}
if (eg->ln_idx > 56) {
real_rows = 64;
} else if (eg->ln_idx > 48) {
real_rows = 56;
} else if (eg->ln_idx > 32) {
real_rows = 48;
} else {
real_rows = 32;
}
for (i = 0; i < eg->num_comps; i++) {
int lnum, hskip, print_size, img_rows;
byte *p0, *p1, *p2, *p3;
byte *inp, *inbuf, *outp, *outbuf;
img_rows = real_rows;
outbuf = eg->print_buf;
for (lnum=0; lnum < img_rows; lnum+=8, outbuf++) {
inbuf = inp = eg->raster_buf[i][lnum];
for (outp = outbuf; inp < inbuf+eg->plane_size; inp++, outp += img_rows) {
memflip8x8(inp, eg->plane_size, outp, row_bytes);
}
}
if (eg->num_comps == 1) {
gp_fputc('\015', prn_stream);
} else {
gp_fputs("\015\033r", prn_stream);
gp_fputc(color[i], prn_stream);
}
*(outp = eg->print_buf + eg->plane_size * img_rows) = 1; 
p0 = p3 = eg->print_buf;
while (p0 < outp) {
static const word zeros[8] = {0,0,0,0,0,0,0,0};
if (p3 < outp) {
for (p1 = p3; !memcmp(p3, zeros, row_bytes*2); p3 += row_bytes*2);
p2 = p3;
redo:
for (p3 += row_bytes; memcmp(p3, zeros, row_bytes); p3 += row_bytes);
if (p3 < outp && memcmp(p3+row_bytes, zeros, row_bytes)) goto redo;
} else p1 = p2 = outp;
if (p0 < p1) {
print_size = ((p1 < outp) ? p1 : outp) - p0;
gp_fputs("\033|B", prn_stream); gp_fputc(img_rows, prn_stream);
fputshort(print_size, prn_stream);
gp_fwrite(p0, sizeof(byte), print_size, prn_stream);
}
if (p1 < p2) {
hskip = (((p2 < outp) ? p2 : outp) - p1) / row_bytes / 2;
gp_fputs("\033\\", prn_stream);
fputshort(hskip, prn_stream);
}
p0 = p2;
}
}
return ep_print_image(prn_stream, eg, 'R', 0, eg->vskip2 + eg->ln_idx);
case 'R':
eg->ln_idx = 0;
eg->vskip1 = size;
eg->vskip2 = 0;
memset(eg->storage, 0, eg->storage_size_words * W);
return 0;
default:
errprintf(eg->mem, "ep_print_image: illegal command character `%c'.\n", cmd);
return 1;
}
}

static GF_Err mp4_mux_configure_pid(GF_Filter *filter, GF_FilterPid *pid, Bool is_remove)
{
GF_MP4MuxCtx *ctx = gf_filter_get_udta(filter);
if (is_remove) {
TrackWriter *tkw = gf_filter_pid_get_udta(pid);
if (tkw) {
gf_list_del_item(ctx->tracks, tkw);
gf_free(tkw);
}
if (ctx->opid && !gf_list_count(ctx->tracks)) {
if (ctx->file) {
if (!ctx->init_movie_done) {
mp4_mux_done(ctx, GF_TRUE);
}
} else {
#ifndef GPAC_DISABLE_ISOM_FRAGMENTS
while (ctx->flush_size) {
GF_Err e = mp4_mux_flush_fragmented(ctx);
if (e) break;
}
#endif
}
gf_filter_pid_remove(ctx->opid);
ctx->opid = NULL;
}
return GF_OK;
}
return mp4_mux_setup_pid(filter, pid, GF_TRUE);
}

static void
dissect_rsvp_common(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, gboolean e2ei)
{
guint8 message_type;
int    session_off, tempfilt_off;
rsvp_conversation_info  *rsvph;
conversation_t          *conversation;
struct rsvp_request_key  request_key, *new_request_key;
struct rsvp_request_val *request_val;
col_clear(pinfo->cinfo, COL_INFO);
message_type = tvb_get_guint8(tvb, 1);
rsvph = wmem_new0(wmem_packet_scope(), rsvp_conversation_info);
set_address(&rsvph->source, pinfo->src.type, pinfo->src.len, pinfo->src.data);
set_address(&rsvph->destination, pinfo->dst.type, pinfo->dst.len, pinfo->dst.data);
col_add_str(pinfo->cinfo, COL_INFO,
val_to_str_ext(message_type, &message_type_vals_ext, "Unknown (%u). "));
if (message_type == RSVP_MSG_BUNDLE) {
col_set_str(pinfo->cinfo, COL_INFO,
rsvp_bundle_dissect ?
"Component Messages Dissected" :
"Component Messages Not Dissected");
} else {
find_rsvp_session_tempfilt(tvb, 0, &session_off, &tempfilt_off);
if (session_off)
col_append_str(pinfo->cinfo, COL_INFO, summary_session(tvb, session_off));
if (tempfilt_off)
col_append_str(pinfo->cinfo, COL_INFO, summary_template(tvb, tempfilt_off));
}
dissect_rsvp_msg_tree(tvb, pinfo, tree, TREE(TT_RSVP), rsvph, e2ei);
if ((message_type == RSVP_MSG_ACK)      ||
(message_type == RSVP_MSG_SREFRESH) ||
(message_type == RSVP_MSG_HELLO))
return;
conversation = find_or_create_conversation(pinfo);
memset(&request_key, 0, sizeof(request_key));
request_key.conversation = conversation->index;
request_key.session_type = rsvph->session_type;
switch (request_key.session_type) {
case RSVP_SESSION_TYPE_IPV4:
set_address(&request_key.u.session_ipv4.destination,
rsvph->destination.type, rsvph->destination.len,
rsvph->destination.data);
request_key.u.session_ipv4.protocol = rsvph->protocol;
request_key.u.session_ipv4.udp_dest_port = rsvph->udp_dest_port;
break;
case RSVP_SESSION_TYPE_IPV6:
break;
case RSVP_SESSION_TYPE_IPV4_LSP:
set_address(&request_key.u.session_ipv4_lsp.destination,
rsvph->destination.type, rsvph->destination.len,
rsvph->destination.data);
request_key.u.session_ipv4_lsp.udp_dest_port = rsvph->udp_dest_port;
request_key.u.session_ipv4_lsp.ext_tunnel_id = rsvph->ext_tunnel_id;
break;
case RSVP_SESSION_TYPE_AGGREGATE_IPV4:
set_address(&request_key.u.session_agg_ipv4.destination,
rsvph->destination.type, rsvph->destination.len,
rsvph->destination.data);
request_key.u.session_agg_ipv4.dscp = rsvph->dscp;
break;
case RSVP_SESSION_TYPE_IPV4_UNI:
set_address(&request_key.u.session_ipv4_uni.destination,
rsvph->destination.type, rsvph->destination.len,
rsvph->destination.data);
request_key.u.session_ipv4_uni.udp_dest_port = rsvph->udp_dest_port;
request_key.u.session_ipv4_uni.ext_tunnel_id = rsvph->ext_tunnel_id;
break;
case RSVP_SESSION_TYPE_IPV4_E_NNI:
set_address(&request_key.u.session_ipv4_enni.destination,
rsvph->destination.type, rsvph->destination.len,
rsvph->destination.data);
request_key.u.session_ipv4_enni.udp_dest_port = rsvph->udp_dest_port;
request_key.u.session_ipv4_enni.ext_tunnel_id = rsvph->ext_tunnel_id;
break;
default:
proto_tree_add_expert(tree, pinfo, &ei_rsvp_session_type, tvb, 0, 0);
break;
}
copy_address_wmem(wmem_file_scope(), &request_key.source_info.source, &rsvph->source);
request_key.source_info.udp_source_port = rsvph->udp_source_port;
request_val =
(struct rsvp_request_val *) g_hash_table_lookup(rsvp_request_hash,
&request_key);
if (!request_val) {
new_request_key = (struct rsvp_request_key *)wmem_memdup(
wmem_file_scope(), &request_key, sizeof(struct rsvp_request_key));
request_val = wmem_new(wmem_file_scope(), struct rsvp_request_val);
request_val->value = conversation->index;
g_hash_table_insert(rsvp_request_hash, new_request_key, request_val);
}
tap_queue_packet(rsvp_tap, pinfo, rsvph);
}

void Compute(OpKernelContext* context) override {
CHECK_EQ(4, context->num_inputs());
const Tensor& gradient = context->input(0);
const Tensor& input = context->input(1);
OP_REQUIRES(context, input.IsSameSize(gradient),
InvalidArgument("gradient and input must be the same size"));
const int depth = input.dim_size(input.dims() - 1);      const Tensor& min = context->input(2);
OP_REQUIRES(context, min.dim_size(0) == depth,
InvalidArgument("min has incorrect size, expected ", depth,
" was ", min.dim_size(0)));
const Tensor& max = context->input(3);
OP_REQUIRES(context, max.dim_size(0) == depth,
InvalidArgument("max has incorrect size, expected ", depth,
" was ", max.dim_size(0)));
Tensor* grad_wrt_input;
OP_REQUIRES_OK(context,
context->allocate_output(0, input.shape(), &grad_wrt_input));
TensorShape min_max_shape({input.dim_size(input.dims() - 1)});
Tensor* grad_wrt_min;
OP_REQUIRES_OK(context,
context->allocate_output(1, min_max_shape, &grad_wrt_min));
Tensor* grad_wrt_max;
OP_REQUIRES_OK(context,
context->allocate_output(2, min_max_shape, &grad_wrt_max));
FakeQuantWithMinMaxVarsPerChannelGradientFunctor<Device> functor;
functor(
context->eigen_device<Device>(), gradient.flat_inner_dims<float, 2>(),
input.flat_inner_dims<float, 2>(), min.vec<float>(), max.vec<float>(),
quant_min_, quant_max_, grad_wrt_input->flat_inner_dims<float, 2>(),
grad_wrt_min->vec<float>(), grad_wrt_max->vec<float>());
}

static int
brcmf_cfg80211_mgmt_tx(struct wiphy *wiphy, struct wireless_dev *wdev,
struct cfg80211_mgmt_tx_params *params, u64 *cookie)
{
struct brcmf_cfg80211_info *cfg = wiphy_to_cfg(wiphy);
struct ieee80211_channel *chan = params->chan;
const u8 *buf = params->buf;
size_t len = params->len;
const struct ieee80211_mgmt *mgmt;
struct brcmf_cfg80211_vif *vif;
s32 err = 0;
s32 ie_offset;
s32 ie_len;
struct brcmf_fil_action_frame_le *action_frame;
struct brcmf_fil_af_params_le *af_params;
bool ack;
s32 chan_nr;
u32 freq;
brcmf_dbg(TRACE, "Enter\n");
*cookie = 0;
mgmt = (const struct ieee80211_mgmt *)buf;
if (!ieee80211_is_mgmt(mgmt->frame_control)) {
brcmf_err("Driver only allows MGMT packet type\n");
return -EPERM;
}
vif = container_of(wdev, struct brcmf_cfg80211_vif, wdev);
if (ieee80211_is_probe_resp(mgmt->frame_control)) {
ie_offset =  DOT11_MGMT_HDR_LEN +
DOT11_BCN_PRB_FIXED_LEN;
ie_len = len - ie_offset;
if (vif == cfg->p2p.bss_idx[P2PAPI_BSSCFG_PRIMARY].vif)
vif = cfg->p2p.bss_idx[P2PAPI_BSSCFG_DEVICE].vif;
err = brcmf_vif_set_mgmt_ie(vif,
BRCMF_VNDR_IE_PRBRSP_FLAG,
&buf[ie_offset],
ie_len);
cfg80211_mgmt_tx_status(wdev, *cookie, buf, len, true,
GFP_KERNEL);
} else if (ieee80211_is_action(mgmt->frame_control)) {
af_params = kzalloc(sizeof(*af_params), GFP_KERNEL);
if (af_params == NULL) {
brcmf_err("unable to allocate frame\n");
err = -ENOMEM;
goto exit;
}
action_frame = &af_params->action_frame;
action_frame->packet_id = cpu_to_le32(*cookie);
memcpy(&action_frame->da[0], &mgmt->da[0], ETH_ALEN);
memcpy(&af_params->bssid[0], &mgmt->bssid[0], ETH_ALEN);
action_frame->len = cpu_to_le16(len - DOT11_MGMT_HDR_LEN);
if (chan)
freq = chan->center_freq;
else
brcmf_fil_cmd_int_get(vif->ifp, BRCMF_C_GET_CHANNEL,
&freq);
chan_nr = ieee80211_frequency_to_channel(freq);
af_params->channel = cpu_to_le32(chan_nr);
memcpy(action_frame->data, &buf[DOT11_MGMT_HDR_LEN],
le16_to_cpu(action_frame->len));
brcmf_dbg(TRACE, "Action frame, cookie=%lld, len=%d, freq=%d\n",
*cookie, le16_to_cpu(action_frame->len), freq);
ack = brcmf_p2p_send_action_frame(cfg, cfg_to_ndev(cfg),
af_params);
cfg80211_mgmt_tx_status(wdev, *cookie, buf, len, ack,
GFP_KERNEL);
kfree(af_params);
} else {
brcmf_dbg(TRACE, "Unhandled, fc=%04x!!\n", mgmt->frame_control);
brcmf_dbg_hex_dump(true, buf, len, "payload, len=%zu\n", len);
}
exit:
return err;
}

static int io_rw_init_file(struct io_kiocb *req, fmode_t mode)
{
struct kiocb *kiocb = &req->rw.kiocb;
struct io_ring_ctx *ctx = req->ctx;
struct file *file = req->file;
int ret;
if (unlikely(!file || !(file->f_mode & mode)))
return -EBADF;
if (!io_req_ffs_set(req))
req->flags |= io_file_get_flags(file) << REQ_F_SUPPORT_NOWAIT_BIT;
kiocb->ki_flags = iocb_flags(file);
ret = kiocb_set_rw_flags(kiocb, req->rw.flags);
if (unlikely(ret))
return ret;
if ((kiocb->ki_flags & IOCB_NOWAIT) ||
((file->f_flags & O_NONBLOCK) && !io_file_supports_nowait(req)))
req->flags |= REQ_F_NOWAIT;
if (ctx->flags & IORING_SETUP_IOPOLL) {
if (!(kiocb->ki_flags & IOCB_DIRECT) || !file->f_op->iopoll)
return -EOPNOTSUPP;
kiocb->ki_flags |= IOCB_HIPRI | IOCB_ALLOC_CACHE;
kiocb->ki_complete = io_complete_rw_iopoll;
req->iopoll_completed = 0;
} else {
if (kiocb->ki_flags & IOCB_HIPRI)
return -EINVAL;
kiocb->ki_complete = io_complete_rw;
}
return 0;
}

