int igmp6_event_query(struct sk_buff *skb)
{
struct inet6_dev *idev = __in6_dev_get(skb->dev);
if (!idev)
return -EINVAL;
if (idev->dead) {
kfree_skb(skb);
return -ENODEV;
}
spin_lock_bh(&idev->mc_query_lock);
if (skb_queue_len(&idev->mc_query_queue) < MLD_MAX_SKBS) {
__skb_queue_tail(&idev->mc_query_queue, skb);
if (!mod_delayed_work(mld_wq, &idev->mc_query_work, 0))
in6_dev_hold(idev);
}
spin_unlock_bh(&idev->mc_query_lock);
return 0;
}

int caca_resize(caca_canvas_t *cv, int width, int height)
{
int x, y, f, old_width, old_height, new_size, old_size;
old_width = cv->width;
old_height = cv->height;
old_size = old_width * old_height;
_caca_save_frame_info(cv);
cv->width = width;
cv->height = height;
new_size = width * height;
if(width < old_width || height < old_height)
_caca_clip_dirty_rect_list(cv);
if(new_size > old_size)
{
for(f = 0; f < cv->framecount; f++)
{
cv->frames[f].chars = realloc(cv->frames[f].chars,
new_size * sizeof(uint32_t));
cv->frames[f].attrs = realloc(cv->frames[f].attrs,
new_size * sizeof(uint32_t));
if(new_size && (!cv->frames[f].chars || !cv->frames[f].attrs))
{
seterrno(ENOMEM);
return -1;
}
}
}
if(width == old_width)
{
;
}
else if(width > old_width)
{
for(f = 0; f < cv->framecount; f++)
{
uint32_t *chars = cv->frames[f].chars;
uint32_t *attrs = cv->frames[f].attrs;
for(y = height < old_height ? height : old_height; y--; )
{
uint32_t attr = cv->frames[f].curattr;
for(x = old_width; x--; )
{
chars[y * width + x] = chars[y * old_width + x];
attrs[y * width + x] = attrs[y * old_width + x];
}
for(x = width - old_width; x--; )
{
chars[y * width + old_width + x] = (uint32_t)' ';
attrs[y * width + old_width + x] = attr;
}
}
}
if(!cv->dirty_disabled)
caca_add_dirty_rect(cv, old_width, 0,
width - old_width, old_height);
}
else
{
int lines = height < old_height ? height : old_height;
for(f = 0; f < cv->framecount; f++)
{
uint32_t *chars = cv->frames[f].chars;
uint32_t *attrs = cv->frames[f].attrs;
for(y = 1; y < lines; y++)
{
for(x = 0; x < width; x++)
{
chars[y * width + x] = chars[y * old_width + x];
attrs[y * width + x] = attrs[y * old_width + x];
}
}
}
}
if(height > old_height)
{
for(f = 0; f < cv->framecount; f++)
{
uint32_t *chars = cv->frames[f].chars;
uint32_t *attrs = cv->frames[f].attrs;
uint32_t attr = cv->frames[f].curattr;
for(x = (height - old_height) * width; x--; )
{
chars[old_height * width + x] = (uint32_t)' ';
attrs[old_height * width + x] = attr;
}
}
if(!cv->dirty_disabled)
caca_add_dirty_rect(cv, 0, old_height,
old_width, height - old_height);
}
if(!cv->dirty_disabled &&
width > old_width && height > old_height)
caca_add_dirty_rect(cv, old_width, old_height,
width - old_width, height - old_height);
if(new_size < old_size)
{
for(f = 0; f < cv->framecount; f++)
{
cv->frames[f].chars = realloc(cv->frames[f].chars,
new_size * sizeof(uint32_t));
cv->frames[f].attrs = realloc(cv->frames[f].attrs,
new_size * sizeof(uint32_t));
if(new_size && (!cv->frames[f].chars || !cv->frames[f].attrs))
{
seterrno(ENOMEM);
return -1;
}
}
}
for(f = 0; f < cv->framecount; f++)
{
if(cv->frames[f].x > (int)width)
cv->frames[f].x = width;
if(cv->frames[f].y > (int)height)
cv->frames[f].y = height;
cv->frames[f].width = width;
cv->frames[f].height = height;
}
_caca_load_frame_info(cv);
return 0;
}

void LibRaw::parseSonySR2(uchar *cbuf_SR2, unsigned SR2SubIFDOffset,
unsigned SR2SubIFDLength, unsigned dng_writer)
{
unsigned c;
unsigned entries, tag_id, tag_type, tag_datalen;
INT64 sr2_offset, tag_offset, tag_data, tag_dataoffset;
int TagProcessed;
int tag_dataunitlen;
float num;
int i;
int WBCTC_count;
entries = sget2(cbuf_SR2);
if (entries > 1000)
return;
tag_offset = 2;
WBCTC_count = 0;
while (entries--) {
if (tiff_sget (SR2SubIFDOffset, cbuf_SR2, SR2SubIFDLength,
&tag_offset, &tag_id, &tag_type, &tag_dataoffset,
&tag_datalen, &tag_dataunitlen) == 0) {
TagProcessed = 0;
if (dng_writer == nonDNG) {
switch (tag_id) {
case 0x7300:
FORC4 cblack[c] = sget2(cbuf_SR2 + tag_dataoffset + tag_dataunitlen * c);
TagProcessed = 1;
break;
case 0x7303:
FORC4 cam_mul[GRBG_2_RGBG(c)] = sget2(cbuf_SR2 + tag_dataoffset + tag_dataunitlen * c);
TagProcessed = 1;
break;
case 0x7310:
FORC4 cblack[RGGB_2_RGBG(c)] = sget2(cbuf_SR2 + tag_dataoffset + tag_dataunitlen * c);
i = cblack[3];
FORC3 if (i > cblack[c]) i = cblack[c];
FORC4 cblack[c] -= i;
black = i;
TagProcessed = 1;
break;
case 0x7313:
FORC4 cam_mul[RGGB_2_RGBG(c)] = sget2(cbuf_SR2 + tag_dataoffset + tag_dataunitlen * c);
TagProcessed = 1;
break;
case 0x74a0:
ilm.MaxAp4MaxFocal = sgetreal(tag_type, cbuf_SR2 + tag_dataoffset);
TagProcessed = 1;
break;
case 0x74a1:
ilm.MaxAp4MinFocal = sgetreal(tag_type, cbuf_SR2 + tag_dataoffset);
TagProcessed = 1;
break;
case 0x74a2:
ilm.MaxFocal = sgetreal(tag_type, cbuf_SR2 + tag_dataoffset);
TagProcessed = 1;
break;
case 0x74a3:
ilm.MinFocal = sgetreal(tag_type, cbuf_SR2 + tag_dataoffset);
TagProcessed = 1;
break;
case 0x7800:
for (i = 0; i < 3; i++)
{
num = 0.0;
for (c = 0; c < 3; c++)
{
imgdata.color.ccm[i][c] =
(float)((short)sget2(cbuf_SR2 + tag_dataoffset + tag_dataunitlen * (i * 3 + c)));
num += imgdata.color.ccm[i][c];
}
if (num > 0.01)
FORC3 imgdata.color.ccm[i][c] = imgdata.color.ccm[i][c] / num;
}
TagProcessed = 1;
break;
case 0x787f:
if (tag_datalen == 3)
{
FORC3 imgdata.color.linear_max[c] = sget2(cbuf_SR2 + tag_dataoffset + tag_dataunitlen * c);
imgdata.color.linear_max[3] = imgdata.color.linear_max[1];
}
else if (tag_datalen == 1)
{
imgdata.color.linear_max[0] = imgdata.color.linear_max[1] =
imgdata.color.linear_max[2] = imgdata.color.linear_max[3] =
sget2(cbuf_SR2 + tag_dataoffset);
}
TagProcessed = 1;
break;
}
}
if (!TagProcessed) {
if ((tag_id >= 0x7480) && (tag_id <= 0x7486)) {
i = tag_id - 0x7480;
if (Sony_SR2_wb_list[i] > 255) {
icWBCCTC[WBCTC_count][0] = Sony_SR2_wb_list[i];
FORC3 icWBCCTC[WBCTC_count][c + 1] = sget2(cbuf_SR2 + tag_dataoffset + tag_dataunitlen * c);
icWBCCTC[WBCTC_count][4] = icWBCCTC[WBCTC_count][2];
WBCTC_count++;
} else {
FORC3 icWBC[Sony_SR2_wb_list[i]][c] = sget2(cbuf_SR2 + tag_dataoffset + tag_dataunitlen * c);
icWBC[Sony_SR2_wb_list[i]][3] = icWBC[Sony_SR2_wb_list[i]][1];
}
} else if ((tag_id >= 0x7820) && (tag_id <= 0x782d)) {
i = tag_id - 0x7820;
if (Sony_SR2_wb_list1[i] > 255) {
icWBCCTC[WBCTC_count][0] = Sony_SR2_wb_list1[i];
FORC3 icWBCCTC[WBCTC_count][c + 1] = sget2(cbuf_SR2 + tag_dataoffset + tag_dataunitlen * c);
icWBCCTC[WBCTC_count][4] = icWBCCTC[WBCTC_count][2];
if (Sony_SR2_wb_list1[i] == 3200) {
FORC3 icWBC[LIBRAW_WBI_StudioTungsten][c] = icWBCCTC[WBCTC_count][c + 1];
icWBC[LIBRAW_WBI_StudioTungsten][3] = icWBC[LIBRAW_WBI_StudioTungsten][1];
}
WBCTC_count++;
} else {
FORC3 icWBC[Sony_SR2_wb_list1[i]][c] = sget2(cbuf_SR2 + tag_dataoffset + tag_dataunitlen * c);
icWBC[Sony_SR2_wb_list1[i]][3] = icWBC[Sony_SR2_wb_list1[i]][1];
}
} else if (tag_id == 0x7302) {
FORC4 icWBC[LIBRAW_WBI_Auto][GRBG_2_RGBG(c)] = sget2(cbuf_SR2 + tag_dataoffset + tag_dataunitlen * c);
} else if (tag_id == 0x7312) {
FORC4 icWBC[LIBRAW_WBI_Auto][RGGB_2_RGBG(c)] = sget2(cbuf_SR2 + tag_dataoffset + tag_dataunitlen * c);
}
}
}
}
}

static inline ut32 r_read_le32(const void *src) {
const ut8 *s = (const ut8*)src;
return (((ut32)s[3]) << 24) | (((ut32)s[2]) << 16) |
(((ut32)s[1]) << 8) | (((ut32)s[0]) << 0);
}

void WebPImage::decodeChunks(uint64_t filesize)
{
DataBuf   chunkId(5);
byte      size_buff[WEBP_TAG_SIZE];
bool      has_canvas_data = false;
#ifdef DEBUG
std::cout << "Reading metadata" << std::endl;
#endif
chunkId.pData_[4] = '\0' ;
while ( !io_->eof() && (uint64_t) io_->tell() < filesize) {
io_->read(chunkId.pData_, WEBP_TAG_SIZE);
io_->read(size_buff, WEBP_TAG_SIZE);
const uint32_t size = Exiv2::getULong(size_buff, littleEndian);
enforce(size <= (filesize - io_->tell()), Exiv2::kerCorruptedMetadata);
DataBuf payload(size);
if (equalsWebPTag(chunkId, WEBP_CHUNK_HEADER_VP8X) && !has_canvas_data) {
has_canvas_data = true;
byte size_buf[WEBP_TAG_SIZE];
io_->read(payload.pData_, payload.size_);
memcpy(&size_buf, &payload.pData_[4], 3);
size_buf[3] = 0;
pixelWidth_ = Exiv2::getULong(size_buf, littleEndian) + 1;
memcpy(&size_buf, &payload.pData_[7], 3);
size_buf[3] = 0;
pixelHeight_ = Exiv2::getULong(size_buf, littleEndian) + 1;
} else if (equalsWebPTag(chunkId, WEBP_CHUNK_HEADER_VP8) && !has_canvas_data) {
has_canvas_data = true;
io_->read(payload.pData_, payload.size_);
byte size_buf[WEBP_TAG_SIZE];
memcpy(&size_buf, &payload.pData_[6], 2);
size_buf[2] = 0;
size_buf[3] = 0;
pixelWidth_ = Exiv2::getULong(size_buf, littleEndian) & 0x3fff;
memcpy(&size_buf, &payload.pData_[8], 2);
size_buf[2] = 0;
size_buf[3] = 0;
pixelHeight_ = Exiv2::getULong(size_buf, littleEndian) & 0x3fff;
} else if (equalsWebPTag(chunkId, WEBP_CHUNK_HEADER_VP8L) && !has_canvas_data) {
has_canvas_data = true;
byte size_buf_w[2];
byte size_buf_h[3];
io_->read(payload.pData_, payload.size_);
memcpy(&size_buf_w, &payload.pData_[1], 2);
size_buf_w[1] &= 0x3F;
pixelWidth_ = Exiv2::getUShort(size_buf_w, littleEndian) + 1;
memcpy(&size_buf_h, &payload.pData_[2], 3);
size_buf_h[0] = ((size_buf_h[0] >> 6) & 0x3) | ((size_buf_h[1]  & 0x3F) << 0x2);
size_buf_h[1] = ((size_buf_h[1] >> 6) & 0x3) | ((size_buf_h[2] & 0xF) << 0x2);
pixelHeight_ = Exiv2::getUShort(size_buf_h, littleEndian) + 1;
} else if (equalsWebPTag(chunkId, WEBP_CHUNK_HEADER_ANMF) && !has_canvas_data) {
has_canvas_data = true;
byte size_buf[WEBP_TAG_SIZE];
io_->read(payload.pData_, payload.size_);
memcpy(&size_buf, &payload.pData_[6], 3);
size_buf[3] = 0;
pixelWidth_ = Exiv2::getULong(size_buf, littleEndian) + 1;
memcpy(&size_buf, &payload.pData_[9], 3);
size_buf[3] = 0;
pixelHeight_ = Exiv2::getULong(size_buf, littleEndian) + 1;
} else if (equalsWebPTag(chunkId, WEBP_CHUNK_HEADER_ICCP)) {
io_->read(payload.pData_, payload.size_);
this->setIccProfile(payload);
} else if (equalsWebPTag(chunkId, WEBP_CHUNK_HEADER_EXIF)) {
io_->read(payload.pData_, payload.size_);
byte  size_buff[2];
byte  exifLongHeader[]   = { 0xFF, 0x01, 0xFF, 0xE1 };
byte  exifShortHeader[]  = { 0x45, 0x78, 0x69, 0x66, 0x00, 0x00 };
byte  exifTiffLEHeader[] = { 0x49, 0x49, 0x2A };                       byte  exifTiffBEHeader[] = { 0x4D, 0x4D, 0x00, 0x2A };                 byte* rawExifData = NULL;
long  offset = 0;
bool  s_header = false;
bool  le_header = false;
bool  be_header = false;
long  pos = -1;
pos = getHeaderOffset (payload.pData_, payload.size_, (byte*)&exifLongHeader, 4);
if (pos == -1) {
pos = getHeaderOffset (payload.pData_, payload.size_, (byte*)&exifLongHeader, 6);
if (pos != -1) {
s_header = true;
}
}
if (pos == -1) {
pos = getHeaderOffset (payload.pData_, payload.size_, (byte*)&exifTiffLEHeader, 3);
if (pos != -1) {
le_header = true;
}
}
if (pos == -1) {
pos = getHeaderOffset (payload.pData_, payload.size_, (byte*)&exifTiffBEHeader, 4);
if (pos != -1) {
be_header = true;
}
}
if (s_header) {
offset += 6;
}
if (be_header || le_header) {
offset += 12;
}
const long size = payload.size_ + offset;
rawExifData = (byte*)malloc(size);
if (s_header) {
us2Data(size_buff, (uint16_t) (size - 6), bigEndian);
memcpy(rawExifData, (char*)&exifLongHeader, 4);
memcpy(rawExifData + 4, (char*)&size_buff, 2);
}
if (be_header || le_header) {
us2Data(size_buff, (uint16_t) (size - 6), bigEndian);
memcpy(rawExifData, (char*)&exifLongHeader, 4);
memcpy(rawExifData + 4, (char*)&size_buff, 2);
memcpy(rawExifData + 6, (char*)&exifShortHeader, 6);
}
memcpy(rawExifData + offset, payload.pData_, payload.size_);
#ifdef DEBUG
std::cout << "Display Hex Dump [size:" << (unsigned long)size << "]" << std::endl;
std::cout << Internal::binaryToHex(rawExifData, size);
#endif
if (pos != -1) {
XmpData  xmpData;
ByteOrder bo = ExifParser::decode(exifData_,
payload.pData_ + pos,
payload.size_ - pos);
setByteOrder(bo);
}
else
{
#ifndef SUPPRESS_WARNINGS
EXV_WARNING << "Failed to decode Exif metadata." << std::endl;
#endif
exifData_.clear();
}
if (rawExifData) free(rawExifData);
} else if (equalsWebPTag(chunkId, WEBP_CHUNK_HEADER_XMP)) {
io_->read(payload.pData_, payload.size_);
xmpPacket_.assign(reinterpret_cast<char*>(payload.pData_), payload.size_);
if (xmpPacket_.size() > 0 && XmpParser::decode(xmpData_, xmpPacket_)) {
#ifndef SUPPRESS_WARNINGS
EXV_WARNING << "Failed to decode XMP metadata." << std::endl;
#endif
} else {
#ifdef DEBUG
std::cout << "Display Hex Dump [size:" << (unsigned long)payload.size_ << "]" << std::endl;
std::cout << Internal::binaryToHex(payload.pData_, payload.size_);
#endif
}
} else {
io_->seek(size, BasicIo::cur);
}
if ( io_->tell() % 2 ) io_->seek(+1, BasicIo::cur);
}
}

