static guint
dissect_amqp_1_0_list(tvbuff_t *tvb,
packet_info *pinfo,
int offset,
int bound,
proto_item *item,
int hf_amqp_type,
guint32 hf_amqp_subtype_count,
const int **hf_amqp_subtypes,
const char *name)
{
proto_item *list_tree;
guint8      type;
guint8      count_len;
guint32     element_count;
guint32     element_size;
guint32     decoded_element_size;
guint32     orig_offset;
guint32     decoded_elements;
int         hf_amqp_item;
list_tree = 0;
decoded_elements = 0;
orig_offset = offset;
if (proto_registrar_get_ftype(hf_amqp_type) != FT_NONE)
{
expert_add_info_format(pinfo, item, &ei_amqp_unknown_amqp_type,
"Unexpected list type at frame position %d of field \"%s\"",
offset,
name ? name : proto_registrar_get_name(hf_amqp_type));
return bound-orig_offset;
}
type = tvb_get_guint8(tvb, offset);
AMQP_INCREMENT(offset, 1, bound);
switch (type) {
case AMQP_1_0_TYPE_LIST0:
count_len = 0;
element_size = 0;
element_count = 0;
break;
case AMQP_1_0_TYPE_LIST8:
count_len = 1;
element_size = tvb_get_guint8(tvb, offset);
element_count = tvb_get_guint8(tvb, offset+count_len);
break;
case AMQP_1_0_TYPE_LIST32:
count_len = 4;
element_size = tvb_get_ntohl(tvb, offset);
element_count = tvb_get_ntohl(tvb, offset+count_len);
break;
default:
proto_tree_add_none_format(list_tree, hf_amqp_1_0_list, tvb,
offset-1,
1,
"(unknown type %d)",
type);
expert_add_info_format(pinfo,
list_tree,
&ei_amqp_unknown_amqp_type,
"Unknown AMQP list type %d",
type);
return bound-orig_offset;
}
list_tree = proto_tree_add_none_format(item,
hf_amqp_type,
tvb,
offset-1,
element_size+1+count_len,
"%s",
name ? name : proto_registrar_get_name(hf_amqp_type));
AMQP_INCREMENT(offset, count_len*2, bound);
if (element_count > 0)
list_tree = proto_item_add_subtree(list_tree, ett_amqp_1_0_list);
if (hf_amqp_subtype_count == 0)
proto_item_append_text(list_tree, " (list of %d element%s)", element_count, element_suffix[element_count!=1]);
if (element_count > element_size)
{
expert_add_info_format(pinfo,
list_tree,
&ei_amqp_invalid_number_of_params,
"Number of list elements (%d) bigger than list size (%d)",
element_count, element_size);
return bound-orig_offset;
}
while ((element_count > 0) && (offset < bound)) {
decoded_element_size = 0;
if (decoded_elements<hf_amqp_subtype_count)
hf_amqp_item = *(hf_amqp_subtypes[decoded_elements]);
else
hf_amqp_item = hf_amqp_1_0_list; 
get_amqp_1_0_type_value_formatter(tvb,
pinfo,
offset,
bound,
hf_amqp_item,
NULL,
&decoded_element_size,
list_tree);
element_count -= 1;
decoded_elements += 1;
AMQP_INCREMENT(offset, decoded_element_size, bound);
}
if (element_count > 0)
expert_add_info_format(pinfo,
list_tree,
&ei_amqp_invalid_number_of_params,
"Number of list elements (%d) not matching number of decoded elements (%d)",
element_count+decoded_elements, decoded_elements);
return offset-orig_offset;
}

int hns_nic_net_xmit_hw(struct net_device *ndev,
struct sk_buff *skb,
struct hns_nic_ring_data *ring_data)
{
struct hns_nic_priv *priv = netdev_priv(ndev);
struct hnae_ring *ring = ring_data->ring;
struct device *dev = ring_to_dev(ring);
struct netdev_queue *dev_queue;
struct skb_frag_struct *frag;
int buf_num;
int seg_num;
dma_addr_t dma;
int size, next_to_use;
int i;
switch (priv->ops.maybe_stop_tx(&skb, &buf_num, ring)) {
case -EBUSY:
ring->stats.tx_busy++;
goto out_net_tx_busy;
case -ENOMEM:
ring->stats.sw_err_cnt++;
netdev_err(ndev, "no memory to xmit!\n");
goto out_err_tx_ok;
default:
break;
}
seg_num = skb_shinfo(skb)->nr_frags + 1;
next_to_use = ring->next_to_use;
size = skb_headlen(skb);
dma = dma_map_single(dev, skb->data, size, DMA_TO_DEVICE);
if (dma_mapping_error(dev, dma)) {
netdev_err(ndev, "TX head DMA map failed\n");
ring->stats.sw_err_cnt++;
goto out_err_tx_ok;
}
priv->ops.fill_desc(ring, skb, size, dma, seg_num == 1 ? 1 : 0,
buf_num, DESC_TYPE_SKB, ndev->mtu);
for (i = 1; i < seg_num; i++) {
frag = &skb_shinfo(skb)->frags[i - 1];
size = skb_frag_size(frag);
dma = skb_frag_dma_map(dev, frag, 0, size, DMA_TO_DEVICE);
if (dma_mapping_error(dev, dma)) {
netdev_err(ndev, "TX frag(%d) DMA map failed\n", i);
ring->stats.sw_err_cnt++;
goto out_map_frag_fail;
}
priv->ops.fill_desc(ring, skb_frag_page(frag), size, dma,
seg_num - 1 == i ? 1 : 0, buf_num,
DESC_TYPE_PAGE, ndev->mtu);
}
dev_queue = netdev_get_tx_queue(ndev, skb->queue_mapping);
netdev_tx_sent_queue(dev_queue, skb->len);
wmb(); 
assert(skb->queue_mapping < priv->ae_handle->q_num);
hnae_queue_xmit(priv->ae_handle->qs[skb->queue_mapping], buf_num);
ring->stats.tx_pkts++;
ring->stats.tx_bytes += skb->len;
return NETDEV_TX_OK;
out_map_frag_fail:
while (ring->next_to_use != next_to_use) {
unfill_desc(ring);
if (ring->next_to_use != next_to_use)
dma_unmap_page(dev,
ring->desc_cb[ring->next_to_use].dma,
ring->desc_cb[ring->next_to_use].length,
DMA_TO_DEVICE);
else
dma_unmap_single(dev,
ring->desc_cb[next_to_use].dma,
ring->desc_cb[next_to_use].length,
DMA_TO_DEVICE);
}
out_err_tx_ok:
dev_kfree_skb_any(skb);
return NETDEV_TX_OK;
out_net_tx_busy:
netif_stop_subqueue(ndev, skb->queue_mapping);
smp_mb();
return NETDEV_TX_BUSY;
}

static void
pdf_run_xobject(fz_context *ctx, pdf_run_processor *proc, pdf_xobject *xobj, pdf_obj *page_resources, const fz_matrix *transform)
{
pdf_run_processor *pr = (pdf_run_processor *)proc;
pdf_gstate *gstate = NULL;
int oldtop = 0;
fz_matrix local_transform = *transform;
softmask_save softmask = { NULL };
int gparent_save;
fz_matrix gparent_save_ctm;
int cleanup_state = 0;
char errmess[256] = "";
pdf_obj *resources;
fz_rect xobj_bbox;
fz_matrix xobj_matrix;
int transparency;
pdf_document *doc;
if (xobj == NULL || pdf_mark_obj(ctx, xobj->obj))
return;
fz_var(cleanup_state);
fz_var(gstate);
fz_var(oldtop);
gparent_save = pr->gparent;
pr->gparent = pr->gtop;
fz_try(ctx)
{
pdf_gsave(ctx, pr);
gstate = pr->gstate + pr->gtop;
oldtop = pr->gtop;
pdf_xobject_bbox(ctx, xobj, &xobj_bbox);
pdf_xobject_matrix(ctx, xobj, &xobj_matrix);
transparency = pdf_xobject_transparency(ctx, xobj);
fz_concat(&local_transform, &xobj_matrix, &local_transform);
fz_concat(&gstate->ctm, &local_transform, &gstate->ctm);
gparent_save_ctm = pr->gstate[pr->gparent].ctm;
pr->gstate[pr->gparent].ctm = gstate->ctm;
if (transparency)
{
fz_rect bbox;
bbox = xobj_bbox;
fz_transform_rect(&bbox, &gstate->ctm);
cleanup_state = 1;
gstate = begin_softmask(ctx, pr, &softmask);
cleanup_state = 2;
fz_begin_group(ctx, pr->dev, &bbox,
pdf_xobject_isolated(ctx, xobj),
pdf_xobject_knockout(ctx, xobj),
gstate->blendmode, gstate->fill.alpha);
gstate->blendmode = 0;
gstate->stroke.alpha = 1;
gstate->fill.alpha = 1;
}
cleanup_state = 3;
pdf_gsave(ctx, pr); 
fz_moveto(ctx, pr->path, xobj_bbox.x0, xobj_bbox.y0);
fz_lineto(ctx, pr->path, xobj_bbox.x1, xobj_bbox.y0);
fz_lineto(ctx, pr->path, xobj_bbox.x1, xobj_bbox.y1);
fz_lineto(ctx, pr->path, xobj_bbox.x0, xobj_bbox.y1);
fz_closepath(ctx, pr->path);
pr->clip = 1;
pdf_show_path(ctx, pr, 0, 0, 0, 0);
resources = pdf_xobject_resources(ctx, xobj);
if (!resources)
resources = page_resources;
doc = pdf_get_bound_document(ctx, xobj->obj);
pdf_process_contents(ctx, (pdf_processor*)pr, doc, resources, xobj->obj, NULL);
}
fz_always(ctx)
{
if (cleanup_state >= 3)
pdf_grestore(ctx, pr); 
if (transparency)
{
if (cleanup_state >= 2)
{
fz_try(ctx)
{
fz_end_group(ctx, pr->dev);
}
fz_catch(ctx)
{
strcpy(errmess, fz_caught_message(ctx));
}
}
if (cleanup_state >= 1)
{
fz_try(ctx)
{
end_softmask(ctx, pr, &softmask);
}
fz_catch(ctx)
{
strcpy(errmess, fz_caught_message(ctx));
}
}
}
pr->gstate[pr->gparent].ctm = gparent_save_ctm;
pr->gparent = gparent_save;
if (gstate)
{
while (oldtop < pr->gtop)
pdf_grestore(ctx, pr);
pdf_grestore(ctx, pr);
}
pdf_unmark_obj(ctx, xobj->obj);
}
fz_catch(ctx)
{
fz_rethrow(ctx);
}
if (errmess[0])
fz_throw(ctx, FZ_ERROR_GENERIC, "%s", errmess);
}

char_u *
compile_redir(char_u *line, exarg_T *eap, cctx_T *cctx)
{
char_u  *arg = eap->arg;
lhs_T   *lhs = &cctx->ctx_redir_lhs;
if (lhs->lhs_name != NULL)
{
if (STRNCMP(arg, "END", 3) == 0)
{
if (lhs->lhs_append)
{
if (compile_load_lhs_with_index(lhs, lhs->lhs_whole,
cctx) == FAIL)
return NULL;
}
generate_instr_type(cctx, ISN_REDIREND, &t_string);
if (lhs->lhs_append)
generate_CONCAT(cctx, 2);
if (lhs->lhs_has_index)
{
if (compile_assign_unlet(lhs->lhs_whole, lhs, TRUE,
&t_string, cctx) == FAIL)
return NULL;
}
else if (generate_store_lhs(cctx, lhs, -1, FALSE) == FAIL)
return NULL;
VIM_CLEAR(lhs->lhs_name);
VIM_CLEAR(lhs->lhs_whole);
return arg + 3;
}
emsg(_(e_cannot_nest_redir));
return NULL;
}
if (arg[0] == '=' && arg[1] == '>')
{
int    append = FALSE;
arg += 2;
if (*arg == '>')
{
++arg;
append = TRUE;
}
arg = skipwhite(arg);
if (compile_assign_lhs(arg, lhs, CMD_redir,
FALSE, FALSE, FALSE, 1, cctx) == FAIL)
return NULL;
if (need_type(&t_string, lhs->lhs_member_type,
-1, 0, cctx, FALSE, FALSE) == FAIL)
return NULL;
generate_instr(cctx, ISN_REDIRSTART);
lhs->lhs_append = append;
if (lhs->lhs_has_index)
{
lhs->lhs_whole = vim_strnsave(arg, lhs->lhs_varlen_total);
if (lhs->lhs_whole == NULL)
return NULL;
}
return arg + lhs->lhs_varlen_total;
}
return compile_exec(line, eap, cctx);
}

