void gnrc_sixlowpan_iphc_recv(gnrc_pktsnip_t *sixlo, void *rbuf_ptr,
unsigned page)
{
assert(sixlo != NULL);
gnrc_pktsnip_t *ipv6, *netif;
gnrc_netif_t *iface;
ipv6_hdr_t *ipv6_hdr;
uint8_t *iphc_hdr = sixlo->data;
size_t payload_offset;
size_t uncomp_hdr_len = sizeof(ipv6_hdr_t);
gnrc_sixlowpan_frag_rb_t *rbuf = rbuf_ptr;
#ifdef MODULE_GNRC_SIXLOWPAN_FRAG_VRB
gnrc_sixlowpan_frag_vrb_t *vrbe = NULL;
#endif  
if (rbuf != NULL) {
ipv6 = rbuf->pkt;
assert(ipv6 != NULL);
}
else {
ipv6 = gnrc_pktbuf_add(NULL, NULL, sizeof(ipv6_hdr_t),
GNRC_NETTYPE_IPV6);
if (ipv6 == NULL) {
gnrc_pktbuf_release(sixlo);
return;
}
}
assert(ipv6->size >= sizeof(ipv6_hdr_t));
netif = gnrc_pktsnip_search_type(sixlo, GNRC_NETTYPE_NETIF);
assert(netif != NULL);
iface = gnrc_netif_hdr_get_netif(netif->data);
payload_offset = _iphc_ipv6_decode(iphc_hdr, netif->data, iface,
ipv6->data);
if (payload_offset == 0) {
_recv_error_release(sixlo, ipv6, rbuf);
return;
}
#ifdef MODULE_GNRC_SIXLOWPAN_IPHC_NHC
if (iphc_hdr[IPHC1_IDX] & SIXLOWPAN_IPHC1_NH) {
bool nhc_header = true;
ipv6_hdr = ipv6->data;
size_t prev_nh_offset = (&ipv6_hdr->nh) - ((uint8_t *)ipv6->data);
while (nhc_header) {
switch (iphc_hdr[payload_offset] & NHC_ID_MASK) {
case NHC_IPV6_EXT_ID:
case NHC_IPV6_EXT_ID_ALT:
payload_offset = _iphc_nhc_ipv6_decode(sixlo,
payload_offset,
rbuf,
&prev_nh_offset,
ipv6,
&uncomp_hdr_len);
if (payload_offset == 0) {
_recv_error_release(sixlo, ipv6, rbuf);
return;
}
nhc_header = (prev_nh_offset > 0);
break;
case NHC_UDP_ID: {
payload_offset = _iphc_nhc_udp_decode(sixlo,
payload_offset,
rbuf,
prev_nh_offset,
ipv6,
&uncomp_hdr_len);
if (payload_offset == 0) {
_recv_error_release(sixlo, ipv6, rbuf);
return;
}
nhc_header = false;
break;
}
default:
nhc_header = false;
break;
}
}
}
#endif
uint16_t payload_len;
if (rbuf != NULL) {
if (_is_rfrag(sixlo)) {
DEBUG("6lo iphc: calculating payload length for SFR\n");
DEBUG(" - rbuf->super.datagram_size: %u\n",
rbuf->super.datagram_size);
DEBUG(" - payload_offset: %u\n", (unsigned)payload_offset);
DEBUG(" - uncomp_hdr_len: %u\n", (unsigned)uncomp_hdr_len);
payload_len = (rbuf->super.datagram_size - payload_offset) +
(uncomp_hdr_len - sizeof(ipv6_hdr_t));
DEBUG("   => %u\n", payload_len);
#ifdef MODULE_GNRC_SIXLOWPAN_FRAG_SFR
rbuf->offset_diff += (uncomp_hdr_len - payload_offset);
rbuf->super.datagram_size += rbuf->offset_diff;
#endif  
}
else {
payload_len = (uint16_t)(rbuf->super.datagram_size - sizeof(ipv6_hdr_t));
}
#ifdef MODULE_GNRC_SIXLOWPAN_FRAG_VRB
DEBUG("6lo iphc: VRB present, trying to create entry for dst %s\n",
ipv6_addr_to_str(addr_str, &ipv6_hdr->dst, sizeof(addr_str)));
ipv6_hdr = ipv6->data;
if ((rbuf->super.current_size <= sixlo->size) && (ipv6_hdr->hl > 1U) &&
(rbuf->super.current_size <= iface->sixlo.max_frag_size) &&
(vrbe = gnrc_sixlowpan_frag_vrb_from_route(&rbuf->super, iface,
ipv6))) {
sixlo = gnrc_pkt_delete(sixlo, netif);
ipv6 = gnrc_pkt_append(ipv6, netif);
if (gnrc_pktbuf_realloc_data(ipv6, uncomp_hdr_len + sixlo->size -
payload_offset) != 0) {
DEBUG("6lo iphc: no space left to copy payload\n");
gnrc_sixlowpan_frag_vrb_rm(vrbe);
_recv_error_release(sixlo, ipv6, rbuf);
return;
}
}
else if (gnrc_pktbuf_realloc_data(ipv6, rbuf->super.datagram_size) != 0) {
DEBUG("6lo iphc: no space left to reassemble payload\n");
_recv_error_release(sixlo, ipv6, rbuf);
return;
}
#endif  
}
else {
payload_len = (sixlo->size + uncomp_hdr_len -
payload_offset - sizeof(ipv6_hdr_t));
}
if ((rbuf == NULL) &&
(gnrc_pktbuf_realloc_data(ipv6, uncomp_hdr_len + payload_len) != 0)) {
DEBUG("6lo iphc: no space left to copy payload\n");
_recv_error_release(sixlo, ipv6, rbuf);
return;
}
ipv6_hdr = ipv6->data;
ipv6_hdr->len = byteorder_htons(payload_len);
memcpy(((uint8_t *)ipv6->data) + uncomp_hdr_len,
((uint8_t *)sixlo->data) + payload_offset,
sixlo->size - payload_offset);
if (rbuf != NULL) {
rbuf->super.current_size += (uncomp_hdr_len - payload_offset);
#ifdef MODULE_GNRC_SIXLOWPAN_FRAG_VRB
if (vrbe != NULL) {
int res = -1;
DEBUG("6lo iphc: found route, trying to forward\n");
ipv6_hdr->hl--;
vrbe->super.current_size = rbuf->super.current_size;
if ((ipv6 = _encode_frag_for_forwarding(ipv6, vrbe))) {
#ifdef MODULE_GNRC_SIXLOWPAN_FRAG_SFR
if (_is_rfrag(sixlo)) {
vrbe->in_netif = iface;
vrbe->offset_diff = ((int)gnrc_pkt_len(ipv6->next)) -
sixlo->size;
}
#endif  
if ((res = _forward_frag(ipv6, sixlo->next, vrbe, page)) == 0) {
DEBUG("6lo iphc: successfully recompressed and forwarded "
"1st fragment\n");
rbuf->super.ints = NULL;
}
}
if ((ipv6 == NULL) || (res < 0)) {
gnrc_sixlowpan_frag_vrb_rm(vrbe);
}
gnrc_pktbuf_release(sixlo);
gnrc_sixlowpan_frag_rb_remove(rbuf);
return;
}
DEBUG("6lo iphc: no route found, reassemble datagram normally\n");
#endif  
}
else {
sixlo = gnrc_pkt_delete(sixlo, netif);
ipv6 = gnrc_pkt_append(ipv6, netif);
gnrc_sixlowpan_dispatch_recv(ipv6, NULL, page);
}
gnrc_pktbuf_release(sixlo);
return;
}

static int rxrpc_krb5_decode_tagged_data(struct krb5_tagged_data *td,
size_t max_data_size,
const __be32 **_xdr,
unsigned int *_toklen)
{
const __be32 *xdr = *_xdr;
unsigned int toklen = *_toklen, len;
if (toklen <= 8)
return -EINVAL;
_enter(",%zu,{%x,%x},%u",
max_data_size, ntohl(xdr[0]), ntohl(xdr[1]), toklen);
td->tag = ntohl(*xdr++);
len = ntohl(*xdr++);
toklen -= 8;
if (len > max_data_size)
return -EINVAL;
td->data_len = len;
if (len > 0) {
td->data = kmemdup(xdr, len, GFP_KERNEL);
if (!td->data)
return -ENOMEM;
len = (len + 3) & ~3;
toklen -= len;
xdr += len >> 2;
}
_debug("tag %x len %x", td->tag, td->data_len);
*_xdr = xdr;
*_toklen = toklen;
_leave(" = 0 [toklen=%u]", toklen);
return 0;
}

static njs_int_t
njs_json_stringify_iterator(njs_vm_t *vm, njs_json_stringify_t *stringify,
njs_value_t *object)
{
u_char            *p;
int64_t           size, length;
njs_int_t         ret;
njs_chb_t         chain;
njs_value_t       *key, *value, index, wrapper;
njs_object_t      *obj;
njs_json_state_t  *state;
obj = njs_json_wrap_value(vm, &wrapper, object);
if (njs_slow_path(obj == NULL)) {
goto memory_error;
}
state = njs_json_push_stringify_state(vm, stringify, &wrapper);
if (njs_slow_path(state == NULL)) {
goto memory_error;
}
njs_chb_init(&chain, vm->mem_pool);
for ( ;; ) {
switch (state->type) {
case NJS_JSON_OBJECT:
if (state->index == 0) {
njs_chb_append(&chain, state->array ? "[" : "{", 1);
njs_json_stringify_indent(stringify, &chain, 0);
}
if ((state->array && state->index >= state->length)
|| (!state->array && state->index >= state->keys->length))
{
njs_json_stringify_indent(stringify, &chain, -1);
njs_chb_append(&chain, state->array ? "]" : "}", 1);
state = njs_json_pop_stringify_state(stringify);
if (state == NULL) {
goto done;
}
break;
}
value = &stringify->retval;
if (state->array) {
njs_set_number(&index, state->index++);
key = &index;
} else {
key = &state->keys->start[state->index++];
}
ret = njs_value_property(vm, &state->value, key, value);
if (njs_slow_path(ret == NJS_ERROR)) {
return ret;
}
if (state->array && ret == NJS_DECLINED) {
njs_set_null(value);
}
ret = njs_json_stringify_to_json(stringify, state, key, value);
if (njs_slow_path(ret != NJS_OK)) {
return ret;
}
ret = njs_json_stringify_replacer(stringify, state, key, value);
if (njs_slow_path(ret != NJS_OK)) {
return ret;
}
if (njs_is_undefined(value)
|| njs_is_symbol(value)
|| njs_is_function(value)
|| !njs_is_valid(value))
{
break;
}
if (state->written) {
njs_chb_append_literal(&chain,",");
njs_json_stringify_indent(stringify, &chain, 0);
}
state->written = 1;
if (!state->array) {
njs_json_append_string(&chain, key, '\"');
njs_chb_append_literal(&chain,":");
if (stringify->space.length != 0) {
njs_chb_append_literal(&chain," ");
}
}
if (njs_json_is_object(value)) {
state = njs_json_push_stringify_state(vm, stringify, value);
if (njs_slow_path(state == NULL)) {
return NJS_ERROR;
}
break;
}
ret = njs_json_append_value(vm, &chain, value);
if (njs_slow_path(ret != NJS_OK)) {
return ret;
}
break;
case NJS_JSON_ARRAY:
if (state->index == 0) {
njs_chb_append_literal(&chain,"[");
njs_json_stringify_indent(stringify, &chain, 0);
}
if (state->index >= njs_array_len(&state->value)) {
njs_json_stringify_indent(stringify, &chain, -1);
njs_chb_append_literal(&chain,"]");
state = njs_json_pop_stringify_state(stringify);
if (state == NULL) {
goto done;
}
break;
}
if (state->written) {
njs_chb_append_literal(&chain,",");
njs_json_stringify_indent(stringify, &chain, 0);
}
stringify->retval = njs_array_start(&state->value)[state->index++];
value = &stringify->retval;
ret = njs_json_stringify_to_json(stringify, state, NULL, value);
if (njs_slow_path(ret != NJS_OK)) {
return ret;
}
ret = njs_json_stringify_replacer(stringify, state, NULL, value);
if (njs_slow_path(ret != NJS_OK)) {
return ret;
}
if (njs_json_is_object(value)) {
state = njs_json_push_stringify_state(vm, stringify, value);
if (state == NULL) {
return NJS_ERROR;
}
break;
}
state->written = 1;
ret = njs_json_append_value(vm, &chain, value);
if (njs_slow_path(ret != NJS_OK)) {
return ret;
}
break;
}
}
done:
njs_chb_drain(&chain, njs_length("{\"\":"));
njs_chb_drop(&chain, njs_length("}"));
if (stringify->space.length != 0) {
njs_chb_drain(&chain, njs_length("\n "));
njs_chb_drop(&chain, njs_length("\n"));
}
size = njs_chb_size(&chain);
if (njs_slow_path(size < 0)) {
njs_chb_destroy(&chain);
goto memory_error;
}
if (size == 0) {
njs_set_undefined(&vm->retval);
goto release;
}
length = njs_chb_utf8_length(&chain);
p = njs_string_alloc(vm, &vm->retval, size, length);
if (njs_slow_path(p == NULL)) {
njs_chb_destroy(&chain);
goto memory_error;
}
njs_chb_join_to(&chain, p);
release:
njs_chb_destroy(&chain);
return NJS_OK;
memory_error:
njs_memory_error(vm);
return NJS_ERROR;
}

int steal_page(
struct domain *d, struct page_info *page, unsigned int memflags)
{
unsigned long x, y;
bool drop_dom_ref = false;
const struct domain *owner;
int rc;
if ( paging_mode_external(d) )
return -EOPNOTSUPP;
rc = -EINVAL;
if ( !(owner = page_get_owner_and_reference(page)) )
goto fail;
if ( owner != d || is_xen_heap_page(page) )
goto fail_put;
y = page->count_info;
do {
x = y;
if ( (x & (PGC_count_mask|PGC_allocated)) != (2 | PGC_allocated) )
goto fail_put;
y = cmpxchg(&page->count_info, x, x & ~(PGC_count_mask|PGC_allocated));
} while ( y != x );
if ( (rc = cleanup_page_cacheattr(page)) )
{
page->count_info |= PGC_allocated | 1;
goto fail;
}
spin_lock(&d->page_alloc_lock);
BUG_ON(page->u.inuse.type_info & (PGT_count_mask | PGT_locked |
PGT_pinned));
page->u.inuse.type_info = 0;
page_set_owner(page, NULL);
page_list_del(page, &d->page_list);
if ( !(memflags & MEMF_no_refcount) && !domain_adjust_tot_pages(d, -1) )
drop_dom_ref = true;
spin_unlock(&d->page_alloc_lock);
if ( unlikely(drop_dom_ref) )
put_domain(d);
return 0;
fail_put:
put_page(page);
fail:
gdprintk(XENLOG_WARNING, "Bad steal mfn %" PRI_mfn
" from d%d (owner d%d) caf=%08lx taf=%" PRtype_info "\n",
mfn_x(page_to_mfn(page)), d->domain_id,
owner ? owner->domain_id : DOMID_INVALID,
page->count_info, page->u.inuse.type_info);
return rc;
}

