static int ehci_process_itd(EHCIState *ehci,
EHCIitd *itd,
uint32_t addr)
{
USBDevice *dev;
USBEndpoint *ep;
uint32_t i, len, pid, dir, devaddr, endp;
uint32_t pg, off, ptr1, ptr2, max, mult;
ehci->periodic_sched_active = PERIODIC_ACTIVE;
dir =(itd->bufptr[1] & ITD_BUFPTR_DIRECTION);
devaddr = get_field(itd->bufptr[0], ITD_BUFPTR_DEVADDR);
endp = get_field(itd->bufptr[0], ITD_BUFPTR_EP);
max = get_field(itd->bufptr[1], ITD_BUFPTR_MAXPKT);
mult = get_field(itd->bufptr[2], ITD_BUFPTR_MULT);
for(i = 0; i < 8; i++) {
if (itd->transact[i] & ITD_XACT_ACTIVE) {
pg   = get_field(itd->transact[i], ITD_XACT_PGSEL);
off  = itd->transact[i] & ITD_XACT_OFFSET_MASK;
len  = get_field(itd->transact[i], ITD_XACT_LENGTH);
if (len > max * mult) {
len = max * mult;
}
if (len > BUFF_SIZE || pg > 6) {
return -1;
}
ptr1 = (itd->bufptr[pg] & ITD_BUFPTR_MASK);
qemu_sglist_init(&ehci->isgl, ehci->device, 2, ehci->as);
if (off + len > 4096) {
if (pg == 6) {
return -1;  
}
ptr2 = (itd->bufptr[pg + 1] & ITD_BUFPTR_MASK);
uint32_t len2 = off + len - 4096;
uint32_t len1 = len - len2;
qemu_sglist_add(&ehci->isgl, ptr1 + off, len1);
qemu_sglist_add(&ehci->isgl, ptr2, len2);
} else {
qemu_sglist_add(&ehci->isgl, ptr1 + off, len);
}
pid = dir ? USB_TOKEN_IN : USB_TOKEN_OUT;
dev = ehci_find_device(ehci, devaddr);
ep = usb_ep_get(dev, pid, endp);
if (ep && ep->type == USB_ENDPOINT_XFER_ISOC) {
usb_packet_setup(&ehci->ipacket, pid, ep, 0, addr, false,
(itd->transact[i] & ITD_XACT_IOC) != 0);
usb_packet_map(&ehci->ipacket, &ehci->isgl);
usb_handle_packet(dev, &ehci->ipacket);
usb_packet_unmap(&ehci->ipacket, &ehci->isgl);
} else {
DPRINTF("ISOCH: attempt to addess non-iso endpoint\n");
ehci->ipacket.status = USB_RET_NAK;
ehci->ipacket.actual_length = 0;
}
qemu_sglist_destroy(&ehci->isgl);
switch (ehci->ipacket.status) {
case USB_RET_SUCCESS:
break;
default:
fprintf(stderr, "Unexpected iso usb result: %d\n",
ehci->ipacket.status);
case USB_RET_IOERROR:
case USB_RET_NODEV:
if (dir) {
itd->transact[i] |= ITD_XACT_XACTERR;
ehci_raise_irq(ehci, USBSTS_ERRINT);
}
break;
case USB_RET_BABBLE:
itd->transact[i] |= ITD_XACT_BABBLE;
ehci_raise_irq(ehci, USBSTS_ERRINT);
break;
case USB_RET_NAK:
ehci->ipacket.actual_length = 0;
break;
}
if (!dir) {
set_field(&itd->transact[i], len - ehci->ipacket.actual_length,
ITD_XACT_LENGTH); 
} else {
set_field(&itd->transact[i], ehci->ipacket.actual_length,
ITD_XACT_LENGTH); 
}
if (itd->transact[i] & ITD_XACT_IOC) {
ehci_raise_irq(ehci, USBSTS_INT);
}
itd->transact[i] &= ~ITD_XACT_ACTIVE;
}
}
return 0;
}

static bool w2p(char *ip, char *op) {
FILE *fp = openr(ip);
if(!fp) return 1;
bool openwdone = 0;
uint8_t *x = 0, *b = 0;
png_struct *p = 0;
png_info *n = 0;
uint8_t i[12];
char *k[] = {"Out of memory", "Broken config, file a bug report",
"Invalid WebP", "???", "???", "???", "I/O error"};
if(!fread(i, 12, 1, fp)) {
PF("ERROR reading %s: %s", IP, k[6]);
goto w2p_close;
}
if(memcmp(i, (char[4]){"RIFF"}, 4) || memcmp(i + 8, (char[4]){"WEBP"}, 4)) {
PF("ERROR reading %s: %s", IP, k[2]);
goto w2p_close;
}
size_t l = ((uint32_t)(i[4] | (i[5] << 8) | (i[6] << 16) | (i[7] << 24))) + 8;
x = malloc(l);
if(!x) {
PF("ERROR reading %s: %s", IP, *k);
goto w2p_close;
}
memcpy(x, i, 12);   if(!fread(x + 12, l - 12, 1, fp)) {
PF("ERROR reading %s: %s", IP, k[6]);
goto w2p_close;
}
fclose(fp);
#if defined LOSSYISERROR || defined NOTHREADS
WebPBitstreamFeatures I;
#else
WebPDecoderConfig c = {.options.use_threads = 1};
#define I c.input
#endif
VP8StatusCode r = WebPGetFeatures(x, l, &I);
if(r) {
PF("ERROR reading %s: %s", IP, k[r - 1]);
goto w2p_free;
}
#define V I.format
#define W ((uint32_t)I.width)
#define H ((uint32_t)I.height)
#define A I.has_alpha
#ifdef LOSSYISERROR
#define FMTSTR
#define FMTARG
#define ANMSTR "%s"
#define ANMARG , "animat"
#else
char *f[] = {"undefined/mixed", "lossy", "lossless"};
#define FMTSTR "\nFormat: %s"
#define FMTARG , f[V]
#define ANMSTR "animat"
#define ANMARG
#endif
PFV("Info: %s:\nDimensions: %" PRIu32 " x %" PRIu32
"\nSize: %zu bytes (%.15g bpp)\nUses alpha: %s" FMTSTR,
IP, W, H, l, (double)l * 8 / (W * H), A ? "yes" : "no" FMTARG);
if(I.has_animation) {
PF("ERROR reading %s: Unsupported feature: " ANMSTR "ion", IP ANMARG);
goto w2p_free;
}
#ifdef LOSSYISERROR
if(V != 2) {
PF("ERROR reading %s: Unsupported feature: %sion", IP, "lossy compress");
goto w2p_free;
}
#endif
#define B ((unsigned)(3 + A))
b = malloc(W * H * B);
if(!b) {
PF("ERROR reading %s: %s", IP, *k);
goto w2p_free;
}
#if defined LOSSYISERROR || defined NOTHREADS
if(!(A ? WebPDecodeRGBAInto : WebPDecodeRGBInto)(
x, l, b, W * H * B, (int)(W * B))) {
PF("ERROR reading %s: %s", IP, k[2]);
goto w2p_free;
}
#else
c.output.colorspace = A ? MODE_RGBA : MODE_RGB;
c.output.is_external_memory = 1;
#define D c.output.u.RGBA
D.rgba = b;
D.stride = (int)(W * B);
D.size = W * H * B;
r = WebPDecode(x, l, &c);
if(r) {
PF("ERROR reading %s: %s", IP, k[r - 1]);
goto w2p_free;
}
#endif
free(x);
x = 0;
if(!(fp = openw(op))) goto w2p_free;
openwdone = !!op;
p = png_create_write_struct(PNG_LIBPNG_VER_STRING, op, pngwerr, pngwarn);
if(!p) {
PF("ERROR writing %s: %s", OP, *k);
goto w2p_close;
}
n = png_create_info_struct(p);
if(!n) {
PF("ERROR writing %s: %s", OP, *k);
goto w2p_close;
}
if(setjmp(png_jmpbuf(p))) {
w2p_close:
fclose(fp);
w2p_free:
if(openwdone) remove(op);
free(x);
free(b);
png_destroy_write_struct(&p, &n);
return 1;
}
pnglen = 0;
png_set_write_fn(p, fp, pngwrite, pngflush);
png_set_filter(p, 0, PNG_ALL_FILTERS);
png_set_compression_level(p, 9);
png_set_IHDR(p, n, W, H, 8, A ? 6 : 2, 0, 0, 0);
png_write_info(p, n);
uint8_t *w = b;
for(unsigned y = H; y; y--) {
png_write_row(p, w);
w += W * B;
}
png_write_end(p, n);
png_destroy_write_struct(&p, &n);
p = 0;
n = 0;
free(b);
b = 0;
if(fclose(fp)) {
PF("ERROR closing %s: %s", OP, strerror(errno));
goto w2p_free;
}
PFV("Info: %s:\nDimensions: %" PRIu32 " x %" PRIu32
"\nSize: %zu bytes (%.15g bpp)\nFormat: %u-bit %s%s%s\nGamma: %.5g",
OP, W, H, pnglen, (double)pnglen * 8 / (W * H), 8, A ? "RGBA" : "RGB", "",
"", 1 / 2.2);
return 0;
}

static void removeduplicateobjs(fz_context *ctx, pdf_document *doc, pdf_write_state *opts)
{
int num, other;
int xref_len = pdf_xref_len(ctx, doc);
for (num = 1; num < xref_len; num++)
{
for (other = 1; other < num; other++)
{
pdf_obj *a, *b;
int newnum, streama = 0, streamb = 0, differ = 0;
if (num == other || !opts->use_list[num] || !opts->use_list[other])
continue;
fz_try(ctx)
{
streama = pdf_obj_num_is_stream(ctx, doc, num);
streamb = pdf_obj_num_is_stream(ctx, doc, other);
differ = streama || streamb;
if (streama && streamb && opts->do_garbage >= 4)
differ = 0;
}
fz_catch(ctx)
{
differ = 1;
}
if (differ)
continue;
a = pdf_get_xref_entry(ctx, doc, num)->obj;
b = pdf_get_xref_entry(ctx, doc, other)->obj;
if (pdf_objcmp(ctx, a, b))
continue;
if (streama && streamb)
{
fz_buffer *sa = NULL;
fz_buffer *sb = NULL;
fz_var(sa);
fz_var(sb);
differ = 1;
fz_try(ctx)
{
unsigned char *dataa, *datab;
size_t lena, lenb;
sa = pdf_load_raw_stream_number(ctx, doc, num);
sb = pdf_load_raw_stream_number(ctx, doc, other);
