ND_PRINT((ndo, ", rsv=0x%0x",
EXTRACT_32BITS(&dp0->ip6r0_reserved)));
}
if (len % 2 == 1)
goto trunc;
len >>= 1;
addr = &dp0->ip6r0_addr[0];
for (i = 0; i < len; i++) {
if ((const u_char *)(addr + 1) > ep)
goto trunc;
ND_PRINT((ndo, ", [%d]%s", i, ip6addr_string(ndo, addr)));
addr++;
}
ND_PRINT((ndo, ") "));
return((dp0->ip6r0_len + 1) << 3);
break;
default:
goto trunc;
break;
}
trunc:
ND_PRINT((ndo, "[|srcrt]"));
return -1;
}

void
spell_add_word(
char_u*word,
intlen,
intwhat,        intidx,            intundo)    {
FILE*fd = NULL;
buf_T*buf = NULL;
intnew_spf = FALSE;
char_u*fname;
char_u*fnamebuf = NULL;
char_uline[MAXWLEN * 2];
longfpos, fpos_next = 0;
inti;
char_u*spf;
if (enc_utf8 && !utf_valid_string(word, NULL))
{
emsg(_(e_illegal_character_in_word));
return;
}
if (idx == 0)        {
if (int_wordlist == NULL)
{
int_wordlist = vim_tempname('s', FALSE);
if (int_wordlist == NULL)
return;
}
fname = int_wordlist;
}
else
{
if (*curwin->w_s->b_p_spf == NUL)
{
init_spellfile();
new_spf = TRUE;
}
if (*curwin->w_s->b_p_spf == NUL)
{
semsg(_(e_option_str_is_not_set), "spellfile");
return;
}
fnamebuf = alloc(MAXPATHL);
if (fnamebuf == NULL)
return;
for (spf = curwin->w_s->b_p_spf, i = 1; *spf != NUL; ++i)
{
copy_option_part(&spf, fnamebuf, MAXPATHL, ",");
if (i == idx)
break;
if (*spf == NUL)
{
semsg(_(e_spellfile_does_not_have_nr_entries), idx);
vim_free(fnamebuf);
return;
}
}
buf = buflist_findname_exp(fnamebuf);
if (buf != NULL && buf->b_ml.ml_mfp == NULL)
buf = NULL;
if (buf != NULL && bufIsChanged(buf))
{
emsg(_(e_file_is_loaded_in_another_buffer));
vim_free(fnamebuf);
return;
}
fname = fnamebuf;
}
if (what == SPELL_ADD_BAD || undo)
{
fd = mch_fopen((char *)fname, "r");
if (fd != NULL)
{
while (!vim_fgets(line, MAXWLEN * 2, fd))
{
fpos = fpos_next;
fpos_next = ftell(fd);
if (fpos_next < 0)
break;  if (STRNCMP(word, line, len) == 0
&& (line[len] == '/' || line[len] < ' '))
{
fclose(fd);
fd = mch_fopen((char *)fname, "r+");
if (fd == NULL)
break;
if (fseek(fd, fpos, SEEK_SET) == 0)
{
fputc('#', fd);
if (undo)
{
home_replace(NULL, fname, NameBuff, MAXPATHL, TRUE);
smsg(_("Word '%.*s' removed from %s"),
len, word, NameBuff);
}
}
if (fseek(fd, fpos_next, SEEK_SET) != 0)
{
PERROR(_("Seek error in spellfile"));
break;
}
}
}
if (fd != NULL)
fclose(fd);
}
}
if (!undo)
{
fd = mch_fopen((char *)fname, "a");
if (fd == NULL && new_spf)
{
char_u *p;
if (!dir_of_file_exists(fname) && (p = gettail_sep(fname)) != fname)
{
int c = *p;
*p = NUL;
vim_mkdir(fname, 0755);
*p = c;
fd = mch_fopen((char *)fname, "a");
}
}
if (fd == NULL)
semsg(_(e_cant_open_file_str), fname);
else
{
if (what == SPELL_ADD_BAD)
fprintf(fd, "%.*s/!\n", len, word);
else if (what == SPELL_ADD_RARE)
fprintf(fd, "%.*s/?\n", len, word);
else
fprintf(fd, "%.*s\n", len, word);
fclose(fd);
home_replace(NULL, fname, NameBuff, MAXPATHL, TRUE);
smsg(_("Word '%.*s' added to %s"), len, word, NameBuff);
}
}
if (fd != NULL)
{
mkspell(1, &fname, FALSE, TRUE, TRUE);
if (buf != NULL)
buf_reload(buf, buf->b_orig_mode, FALSE);
redraw_all_later(SOME_VALID);
}
vim_free(fnamebuf);
}

static GF_Err ttml_embed_data(GF_XMLNode *node, u8 *aux_data, u32 aux_data_size, u8 *subs_data, u32 subs_data_size)
{
u32 i=0;
GF_XMLNode *child;
u32 subs_idx=0;
GF_XMLAttribute *att;
Bool is_source = GF_FALSE;
Bool has_src_att = GF_FALSE;
if (!node || node->type) return GF_BAD_PARAM;
if (!strcmp(node->name, "source")) {
is_source = GF_TRUE;
}
while ((att = gf_list_enum(node->attributes, &i))) {
char *sep, *fext;
if (strcmp(att->name, "src")) continue;
has_src_att = GF_TRUE;
if (strncmp(att->value, "urn:", 4)) continue;
sep = strrchr(att->value, ':');
if (!sep) continue;
sep++;
fext = gf_file_ext_start(sep);
if (fext) fext[0] = 0;
subs_idx = atoi(sep);
if (fext) fext[0] = '.';
if (!subs_idx || ((subs_idx-1) * 14 > subs_data_size)) {
subs_idx = 0;
continue;
}
break;
}
if (subs_idx) {
GF_XMLNode *data;
u32 subs_offset = 0;
u32 subs_size = 0;
u32 idx = 1;
for (i=0; i<subs_data_size; i+=14) {
u32 a_subs_size = subs_data[i+4];
a_subs_size <<= 8;
a_subs_size |= subs_data[i+5];
a_subs_size <<= 8;
a_subs_size |= subs_data[i+6];
a_subs_size <<= 8;
a_subs_size |= subs_data[i+7];
if (idx==subs_idx) {
subs_size = a_subs_size;
break;
}
subs_offset += a_subs_size;
idx++;
}
if (!subs_size || (subs_offset + subs_size > aux_data_size)) {
if (!subs_size) {
GF_LOG(GF_LOG_ERROR, GF_LOG_MEDIA, ("No subsample with index %u in sample\n", subs_idx));
} else {
GF_LOG(GF_LOG_ERROR, GF_LOG_MEDIA, ("Corrupted subsample %u info, size %u offset %u but sample size %u\n", subs_idx, subs_size, subs_offset, aux_data_size));
}
return GF_NON_COMPLIANT_BITSTREAM;
}
gf_list_del_item(node->attributes, att);
if (att->name) gf_free(att->name);
if (att->value) gf_free(att->value);
gf_free(att);
if (!is_source) {
GF_XMLNode *s;
GF_SAFEALLOC(s, GF_XMLNode);
if (!s) return GF_OUT_OF_MEM;
s->attributes = gf_list_new();
s->content = gf_list_new();
s->name = gf_strdup("source");
gf_list_add(node->content, s);
if (!s->name || !s->content || !s->attributes) return GF_OUT_OF_MEM;
att = ttml_get_attr(node, "type");
if (att) {
gf_list_del_item(node->attributes, att);
gf_list_add(s->attributes, att);
}
node = s;
}
GF_SAFEALLOC(data, GF_XMLNode);
if (!data) return GF_OUT_OF_MEM;
data->attributes = gf_list_new();
data->content = gf_list_new();
data->name = gf_strdup("data");
gf_list_add(node->content, data);
if (!data->name || !data->content || !data->attributes) return GF_OUT_OF_MEM;
att = ttml_get_attr(node, "type");
if (att) {
gf_list_del_item(node->attributes, att);
gf_list_add(data->attributes, att);
}
GF_SAFEALLOC(node, GF_XMLNode)
if (!node) return GF_OUT_OF_MEM;
node->type = GF_XML_TEXT_TYPE;
node->name = gf_malloc(sizeof(u8) * subs_size * 2);
if (!node->name) {
gf_free(node);
return GF_OUT_OF_MEM;
}
subs_size = gf_base64_encode(aux_data + subs_offset, subs_size, (u8*) node->name, subs_size * 2);
node->name[subs_size] = 0;
return gf_list_add(data->content, node);
}
if (has_src_att) return GF_OK;
i=0;
while ((child = gf_list_enum(node->content, &i))) {
if (child->type) continue;
ttml_embed_data(child, aux_data, aux_data_size, subs_data, subs_data_size);
}
return GF_OK;
}

inline int ComputeOutSize(TfLitePadding padding, int image_size,
int filter_size, int stride, int dilation_rate = 1) {
int effective_filter_size = (filter_size - 1) * dilation_rate + 1;
switch (padding) {
case kTfLitePaddingSame:
return (image_size + stride - 1) / stride;
case kTfLitePaddingValid:
return (image_size + stride - effective_filter_size) / stride;
default:
return 0;
}
}

int DecodeTunnel(ThreadVars *tv, DecodeThreadVars *dtv, Packet *p,
uint8_t *pkt, uint32_t len, PacketQueue *pq, enum DecodeTunnelProto proto)
{
switch (proto) {
case DECODE_TUNNEL_PPP:
return DecodePPP(tv, dtv, p, pkt, len, pq);
case DECODE_TUNNEL_IPV4:
return DecodeIPV4(tv, dtv, p, pkt, len, pq);
case DECODE_TUNNEL_IPV6:
return DecodeIPV6(tv, dtv, p, pkt, len, pq);
case DECODE_TUNNEL_VLAN:
return DecodeVLAN(tv, dtv, p, pkt, len, pq);
case DECODE_TUNNEL_ETHERNET:
return DecodeEthernet(tv, dtv, p, pkt, len, pq);
case DECODE_TUNNEL_ERSPAN:
return DecodeERSPAN(tv, dtv, p, pkt, len, pq);
default:
SCLogInfo("FIXME: DecodeTunnel: protocol %" PRIu32 " not supported.", proto);
break;
}
return TM_ECODE_OK;
}

