free(chassis);
return -1;
}
#  ifdef ENABLE_DOT1
TAILQ_INIT(&port->p_vlans);
#  endif
length = s;
pos = (u_int8_t *)frame;
if (length < 2 * ETHER_ADDR_LEN + sizeof(u_int16_t)  +
8  + 4 ) {
