}
memcpy(chassis->c_id, chassis->c_name, tlv_len);
chassis->c_id_len = tlv_len;
break;
case CDP_TLV_ADDRESSES:
CHECK_TLV_SIZE(4, "Address");
addresses_len = tlv_len - 4;
for (nb = PEEK_UINT32; nb > 0; nb--) {
(void)PEEK_SAVE(pos_address);
if (addresses_len < 2) {
log_warn("cdp",
"too short address subframe "
"received on %s",
hardware->h_ifname);
goto malformed;
}
PEEK_DISCARD_UINT8;
addresses_len--;
address_len = PEEK_UINT8;
addresses_len--;
if (addresses_len < address_len + 2) {
log_warn("cdp",
"too short address subframe "
"received on %s",
hardware->h_ifname);
goto malformed;
}
PEEK_DISCARD(address_len);
addresses_len -= address_len;
address_len = PEEK_UINT16;
addresses_len -= 2;
if (addresses_len < address_len) {
log_warn("cdp",
"too short address subframe "
"received on %s",
hardware->h_ifname);
goto malformed;
}
PEEK_DISCARD(address_len);
(void)PEEK_SAVE(pos_next_address);
PEEK_RESTORE(pos_address);
if ((PEEK_UINT8 == 1) && (PEEK_UINT8 == 1) &&
(PEEK_UINT8 == CDP_ADDRESS_PROTO_IP) &&
(PEEK_UINT16 == sizeof(struct in_addr))) {
PEEK_BYTES(&addr, sizeof(struct in_addr));
mgmt = lldpd_alloc_mgmt(LLDPD_AF_IPV4, &addr,
sizeof(struct in_addr), 0);
if (mgmt == NULL) {
if (errno == ENOMEM)
log_warn("cdp",
"unable to allocate memory for management address");
else
log_warn("cdp",
"too large management address received on %s",
hardware->h_ifname);
goto malformed;
}
TAILQ_INSERT_TAIL(&chassis->c_mgmt, mgmt,
m_entries);
}
PEEK_RESTORE(pos_next_address);
}
break;
case CDP_TLV_PORT:
if (tlv_len == 0) {
log_warn("cdp", "too short port description received");
goto malformed;
}
free(port->p_descr);
if ((port->p_descr = (char *)calloc(1, tlv_len + 1)) == NULL) {
log_warn("cdp",
"unable to allocate memory for port description");
goto malformed;
}
PEEK_BYTES(port->p_descr, tlv_len);
port->p_id_subtype = LLDP_PORTID_SUBTYPE_IFNAME;
free(port->p_id);
if ((port->p_id = (char *)calloc(1, tlv_len)) == NULL) {
log_warn("cdp",
"unable to allocate memory for port ID");
goto malformed;
}
memcpy(port->p_id, port->p_descr, tlv_len);
port->p_id_len = tlv_len;
break;
case CDP_TLV_CAPABILITIES:
#  ifdef ENABLE_FDP
if (fdp) {
if (!strncmp("Router", (char *)pos, tlv_len))
chassis->c_cap_enabled = LLDP_CAP_ROUTER;
else if (!strncmp("Switch", (char *)pos, tlv_len))
chassis->c_cap_enabled = LLDP_CAP_BRIDGE;
else if (!strncmp("Bridge", (char *)pos, tlv_len))
chassis->c_cap_enabled = LLDP_CAP_REPEATER;
else
chassis->c_cap_enabled = LLDP_CAP_STATION;
chassis->c_cap_available = chassis->c_cap_enabled;
break;
}
#  endif
CHECK_TLV_SIZE(4, "Capabilities");
caps = PEEK_UINT32;
if (caps & CDP_CAP_ROUTER)
chassis->c_cap_enabled |= LLDP_CAP_ROUTER;
if (caps & 0x0e) chassis->c_cap_enabled |= LLDP_CAP_BRIDGE;
if (chassis->c_cap_enabled == 0)
chassis->c_cap_enabled = LLDP_CAP_STATION;
chassis->c_cap_available = chassis->c_cap_enabled;
break;
case CDP_TLV_SOFTWARE:
software_len = tlv_len;
(void)PEEK_SAVE(software);
break;
case CDP_TLV_PLATFORM:
platform_len = tlv_len;
(void)PEEK_SAVE(platform);
break;
#  ifdef ENABLE_DOT1
case CDP_TLV_NATIVEVLAN:
CHECK_TLV_SIZE(2, "Native VLAN");
if ((vlan = (struct lldpd_vlan *)calloc(1,
sizeof(struct lldpd_vlan))) == NULL) {
log_warn("cdp",
"unable to alloc vlan "
"structure for "
"tlv received on %s",
hardware->h_ifname);
goto malformed;
}
vlan->v_vid = port->p_pvid = PEEK_UINT16;
if (asprintf(&vlan->v_name, "VLAN #%d", vlan->v_vid) == -1) {
log_warn("cdp",
"unable to alloc VLAN name for "
"TLV received on %s",
hardware->h_ifname);
free(vlan);
goto malformed;
}
TAILQ_INSERT_TAIL(&port->p_vlans, vlan, v_entries);
break;
#  endif
#  ifdef ENABLE_DOT3
case CDP_TLV_POWER_AVAILABLE:
CHECK_TLV_SIZE(12, "Power Available");
if (PEEK_UINT16 > 0) {
port->p_cdp_power.management_id = PEEK_UINT16;
port->p_power.allocated = PEEK_UINT32;
port->p_power.allocated /= 100;
port->p_power.supported = 1;
port->p_power.enabled = 1;
port->p_power.devicetype = LLDP_DOT3_POWER_PSE;
port->p_power.powertype = LLDP_DOT3_POWER_8023AT_TYPE2;
log_debug("cdp", "Allocated power %d00",
port->p_power.allocated);
if (port->p_power.allocated > CDP_CLASS_3_MAX_PSE_POE) {
port->p_power.allocated -=
CDP_SWITCH_POE_CLASS_4_OFFSET;
} else if (port->p_power.allocated >
CDP_SWITCH_POE_CLASS_3_OFFSET) {
port->p_power.allocated -=
CDP_SWITCH_POE_CLASS_3_OFFSET;
} else {
port->p_power.allocated = 0;
}
port->p_power.requested =
hardware->h_lport.p_power.requested;
}
break;
#  endif
default:
log_debug("cdp", "unknown CDP/FDP TLV type (%d) received on %s",
ntohs(tlv_type), hardware->h_ifname);
hardware->h_rx_unrecognized_cnt++;
}
PEEK_DISCARD(tlv + tlv_len - pos);
}
if (!software && platform) {
if ((chassis->c_descr = (char *)calloc(1, platform_len + 1)) == NULL) {
log_warn("cdp",
"unable to allocate memory for chassis description");
goto malformed;
}
memcpy(chassis->c_descr, platform, platform_len);
} else if (software && !platform) {
if ((chassis->c_descr = (char *)calloc(1, software_len + 1)) == NULL) {
log_warn("cdp",
"unable to allocate memory for chassis description");
goto malformed;
}
memcpy(chassis->c_descr, software, software_len);
} else if (software && platform) {
#  define CONCAT_PLATFORM " running on\n"
if ((chassis->c_descr = (char *)calloc(1,
software_len + platform_len + strlen(CONCAT_PLATFORM) + 1)) ==
NULL) {
log_warn("cdp",
"unable to allocate memory for chassis description");
goto malformed;
}
memcpy(chassis->c_descr, platform, platform_len);
memcpy(chassis->c_descr + platform_len, CONCAT_PLATFORM,
strlen(CONCAT_PLATFORM));
memcpy(chassis->c_descr + platform_len + strlen(CONCAT_PLATFORM),
software, software_len);
}
if ((chassis->c_id == NULL) || (port->p_id == NULL) ||
(chassis->c_name == NULL) || (chassis->c_descr == NULL) ||
(port->p_descr == NULL) || (port->p_ttl == 0) ||
(chassis->c_cap_enabled == 0)) {
log_warnx("cdp",
"some mandatory CDP/FDP tlv are missing for frame received on %s",
hardware->h_ifname);
goto malformed;
}
*newchassis = chassis;
*newport = port;
return 1;
malformed:
lldpd_chassis_cleanup(chassis, 1);
lldpd_port_cleanup(port, 1);
free(port);
return -1;
}

void WT_InterpolateNoLoop (S_WT_VOICE *pWTVoice, S_WT_INT_FRAME *pWTIntFrame)
{
EAS_PCM *pOutputBuffer;
EAS_I32 phaseInc;
EAS_I32 phaseFrac;
EAS_I32 acc0;
const EAS_SAMPLE *pSamples;
EAS_I32 samp1;
EAS_I32 samp2;
EAS_I32 numSamples;
numSamples = pWTIntFrame->numSamples;
if (numSamples <= 0) {
ALOGE("b/26366256");
return;
}
pOutputBuffer = pWTIntFrame->pAudioBuffer;
phaseInc = pWTIntFrame->frame.phaseIncrement;
pSamples = (const EAS_SAMPLE*) pWTVoice->phaseAccum;
phaseFrac = (EAS_I32)pWTVoice->phaseFrac;
#if defined(_8_BIT_SAMPLES)
samp1 = pSamples[0] << 8;
samp2 = pSamples[1] << 8;
#else
samp1 = pSamples[0];
samp2 = pSamples[1];
#endif
while (numSamples--) {
acc0 = samp2 - samp1;
acc0 = acc0 * phaseFrac;
acc0 = samp1 + (acc0 >> NUM_PHASE_FRAC_BITS);
*pOutputBuffer++ = (EAS_I16)(acc0 >> 2);
phaseFrac += phaseInc;
acc0 = phaseFrac >> NUM_PHASE_FRAC_BITS;
if (acc0 > 0) {
pSamples += acc0;
phaseFrac = (EAS_I32)((EAS_U32)phaseFrac & PHASE_FRAC_MASK);
#if defined(_8_BIT_SAMPLES)
samp1 = pSamples[0] << 8;
samp2 = pSamples[1] << 8;
#else
samp1 = pSamples[0];
samp2 = pSamples[1];
#endif
}
}
pWTVoice->phaseAccum = (EAS_U32) pSamples;
pWTVoice->phaseFrac = (EAS_U32) phaseFrac;
}

wc_uint32
wc_any_to_ucs(wc_wchar_t cc)
{
int f;
wc_uint16 *map = NULL;
wc_uint32 map_size = 0x80;
wc_map *map2;
f = WC_CCS_INDEX(cc.ccs);
switch (WC_CCS_TYPE(cc.ccs)) {
case WC_CCS_A_CS94:
if (cc.ccs == WC_CCS_US_ASCII)
return cc.code;
if (f < WC_F_ISO_BASE || f > WC_F_CS94_END)
return WC_C_UCS4_ERROR;
map = cs94_ucs_map[f - WC_F_ISO_BASE];
cc.code &= 0x7f;
break;
case WC_CCS_A_CS94W:
if (cc.ccs == WC_CCS_GB_2312 && WcOption.use_gb12345_map) {
cc.ccs = WC_CCS_GB_12345;
return wc_any_to_ucs(cc);
} else if (cc.ccs == WC_CCS_JIS_X_0213_1) {
map2 = wc_map_search((wc_uint16)(cc.code & 0x7f7f),
jisx02131_ucs_p2_map, N_jisx02131_ucs_p2_map);
if (map2)
return map2->code2 | WC_C_UCS4_PLANE2;
} else if (cc.ccs == WC_CCS_JIS_X_0213_2) {
map2 = wc_map_search((wc_uint16)(cc.code & 0x7f7f),
jisx02132_ucs_p2_map, N_jisx02132_ucs_p2_map);
if (map2)
return map2->code2 | WC_C_UCS4_PLANE2;
}
if (f < WC_F_ISO_BASE || f > WC_F_CS94W_END)
return 0;
map = cs94w_ucs_map[f - WC_F_ISO_BASE];
map_size = cs94w_ucs_map_size[f - WC_F_ISO_BASE];
cc.code = WC_CS94W_N(cc.code);
break;
case WC_CCS_A_CS96:
if (f < WC_F_ISO_BASE || f > WC_F_CS96_END)
return WC_C_UCS4_ERROR;
map = cs96_ucs_map[f - WC_F_ISO_BASE];
cc.code &= 0x7f;
break;
case WC_CCS_A_CS96W:
if (f < WC_F_ISO_BASE || f > WC_F_CS96W_END)
return WC_C_UCS4_ERROR;
map = cs96w_ucs_map[f - WC_F_ISO_BASE];
map_size = cs96w_ucs_map_size[f - WC_F_ISO_BASE];
cc.code = WC_CS96W_N(cc.code);
break;
case WC_CCS_A_CS942:
if (f < WC_F_ISO_BASE || f > WC_F_CS942_END)
return WC_C_UCS4_ERROR;
map = cs942_ucs_map[f - WC_F_ISO_BASE];
cc.code &= 0x7f;
break;
case WC_CCS_A_PCS:
if (f < WC_F_PCS_BASE || f > WC_F_PCS_END)
return WC_C_UCS4_ERROR;
switch (cc.ccs) {
case WC_CCS_CP1258_2:
map2 = wc_map_search((wc_uint16)cc.code,
cp12582_ucs_map, N_cp12582_ucs_map);
if (map2)
return map2->code2;
return WC_C_UCS4_ERROR;
case WC_CCS_TCVN_5712_3:
return wc_any_to_ucs(wc_tcvn57123_to_tcvn5712(cc));
case WC_CCS_GBK_80:
return WC_C_UCS2_EURO;
}
map = pcs_ucs_map[f - WC_F_PCS_BASE];
cc.code &= 0x7f;
break;
case WC_CCS_A_PCSW:
if (f < WC_F_PCS_BASE || f > WC_F_PCSW_END)
return WC_C_UCS4_ERROR;
map = pcsw_ucs_map[f - WC_F_PCS_BASE];
map_size = pcsw_ucs_map_size[f - WC_F_PCS_BASE];
switch (cc.ccs) {
case WC_CCS_BIG5:
cc.code = WC_BIG5_N(cc.code);
break;
case WC_CCS_BIG5_2:
cc.code = WC_CS94W_N(cc.code) + WC_C_BIG5_2_BASE;
break;
case WC_CCS_HKSCS_1:
case WC_CCS_HKSCS_2:
cc = wc_cs128w_to_hkscs(cc);
case WC_CCS_HKSCS:
map2 = wc_map_search((wc_uint16)cc.code,
hkscs_ucs_p2_map, N_hkscs_ucs_p2_map);
if (map2)
return map2->code2 | WC_C_UCS4_PLANE2;
cc.code = wc_hkscs_to_N(cc.code);
break;
case WC_CCS_JOHAB:
return wc_any_to_ucs(wc_johab_to_cs128w(cc));
case WC_CCS_JOHAB_1:
return WC_CS94x128_N(cc.code) + WC_C_UCS2_HANGUL;
case WC_CCS_JOHAB_2:
cc.code = WC_CS128W_N(cc.code);
cc.code = WC_N_JOHAB2(cc.code);
map2 = wc_map_search((wc_uint16)cc.code,
johab2_ucs_map, N_johab2_ucs_map);
if (map2)
return map2->code2;
return WC_C_UCS4_ERROR;
case WC_CCS_JOHAB_3:
if ((cc.code & 0x7f7f) < 0x2121)
return WC_C_UCS4_ERROR;
case WC_CCS_SJIS_EXT:
return wc_any_to_ucs(wc_sjis_ext_to_cs94w(cc));
case WC_CCS_SJIS_EXT_1:
cc.code = wc_sjis_ext1_to_N(cc.code);
if (cc.code == WC_C_SJIS_ERROR)
return WC_C_UCS4_ERROR;
break;
case WC_CCS_SJIS_EXT_2:
cc.code = wc_sjis_ext2_to_N(cc.code);
if (cc.code == WC_C_SJIS_ERROR)
return WC_C_UCS4_ERROR;
break;
case WC_CCS_GBK_1:
case WC_CCS_GBK_2:
cc = wc_cs128w_to_gbk(cc);
case WC_CCS_GBK:
cc.code = wc_gbk_to_N(cc.code);
break;
case WC_CCS_GBK_EXT:
case WC_CCS_GBK_EXT_1:
case WC_CCS_GBK_EXT_2:
return wc_gb18030_to_ucs(cc);
case WC_CCS_UHC_1:
case WC_CCS_UHC_2:
cc = wc_cs128w_to_uhc(cc);
case WC_CCS_UHC:
if (cc.code > WC_C_UHC_END)
return WC_C_UCS4_ERROR;
cc.code = wc_uhc_to_N(cc.code);
break;
default:
cc.code = WC_CS94W_N(cc.code);
break;
}
break;
case WC_CCS_A_WCS16:
switch (WC_CCS_SET(cc.ccs)) {
case WC_CCS_UCS2:
return cc.code;
}
return WC_C_UCS4_ERROR;
case WC_CCS_A_WCS32:
switch (WC_CCS_SET(cc.ccs)) {
case WC_CCS_UCS4:
return cc.code;
case WC_CCS_UCS_TAG:
return wc_ucs_tag_to_ucs(cc.code);
case WC_CCS_GB18030:
return wc_gb18030_to_ucs(cc);
}
return WC_C_UCS4_ERROR;
case WC_CCS_A_UNKNOWN:
if (cc.ccs == WC_CCS_C1)
return (cc.code | 0x80);
default:
return WC_C_UCS4_ERROR;
}
if (map == NULL)
return WC_C_UCS4_ERROR;
if (map_size == 0 || cc.code > map_size - 1)
return WC_C_UCS4_ERROR;
cc.code = map[cc.code];
return cc.code ? cc.code : WC_C_UCS4_ERROR;
}

static INT
AirPDcapDecryptWPABroadcastKey(const EAPOL_RSN_KEY *pEAPKey, guint8  *decryption_key, PAIRPDCAP_SEC_ASSOCIATION sa, gboolean group_hshake)
{
guint8 key_version;
guint8  *szEncryptedKey;
guint16 key_bytes_len = 0; 
guint16 key_len;           
static AIRPDCAP_KEY_ITEM dummy_key; 
AIRPDCAP_SEC_ASSOCIATION *tmp_sa;
key_version = AIRPDCAP_EAP_KEY_DESCR_VER(pEAPKey->key_information[1]);
if (key_version == AIRPDCAP_WPA_KEY_VER_NOT_CCMP){
key_bytes_len = pntoh16(pEAPKey->key_length);
}else if (key_version == AIRPDCAP_WPA_KEY_VER_AES_CCMP){
key_bytes_len = pntoh16(pEAPKey->key_data_len);
if (key_bytes_len < 16) {
return AIRPDCAP_RET_NO_VALID_HANDSHAKE;
}
}
if (key_bytes_len > TKIP_GROUP_KEYBYTES_LEN_MAX || key_bytes_len == 0) { 
return AIRPDCAP_RET_NO_VALID_HANDSHAKE;
}
szEncryptedKey = (guint8 *)wmem_memdup(wmem_packet_scope(), pEAPKey->ie, key_bytes_len);
DEBUG_DUMP("Encrypted Broadcast key:", szEncryptedKey, key_bytes_len);
DEBUG_DUMP("KeyIV:", pEAPKey->key_iv, 16);
DEBUG_DUMP("decryption_key:", decryption_key, 16);
tmp_sa=(AIRPDCAP_SEC_ASSOCIATION *)g_malloc(sizeof(AIRPDCAP_SEC_ASSOCIATION));
memcpy(tmp_sa, sa, sizeof(AIRPDCAP_SEC_ASSOCIATION));
sa->next=tmp_sa;
if (key_version == AIRPDCAP_WPA_KEY_VER_NOT_CCMP){
guint8 new_key[32];
guint8 dummy[256];
rc4_state_struct rc4_state;
sa->wpa.key_ver = (key_bytes_len >=TKIP_GROUP_KEY_LEN)?AIRPDCAP_WPA_KEY_VER_NOT_CCMP:AIRPDCAP_WPA_KEY_VER_AES_CCMP;
memcpy(new_key, pEAPKey->key_iv, 16);
memcpy(new_key+16, decryption_key, 16);
DEBUG_DUMP("FullDecrKey:", new_key, 32);
crypt_rc4_init(&rc4_state, new_key, sizeof(new_key));
crypt_rc4(&rc4_state, dummy, 256);
crypt_rc4(&rc4_state, szEncryptedKey, key_bytes_len);
} else if (key_version == AIRPDCAP_WPA_KEY_VER_AES_CCMP){
guint8 key_found;
guint16 key_index;
guint8 *decrypted_data;
if (group_hshake)
sa->wpa.key_ver = (key_bytes_len >= (TKIP_GROUP_KEYBYTES_LEN_GKEY))?AIRPDCAP_WPA_KEY_VER_NOT_CCMP:AIRPDCAP_WPA_KEY_VER_AES_CCMP;
else
sa->wpa.key_ver = (key_bytes_len >= (TKIP_GROUP_KEYBYTES_LEN))?AIRPDCAP_WPA_KEY_VER_NOT_CCMP:AIRPDCAP_WPA_KEY_VER_AES_CCMP;
decrypted_data = AES_unwrap(decryption_key, 16, szEncryptedKey,  key_bytes_len);
key_found = FALSE;
key_index = 0;
while(key_index < key_bytes_len && !key_found){
guint8 rsn_id;
rsn_id = decrypted_data[key_index];
if (rsn_id != 0xdd){
if (key_index+1 >= key_bytes_len){
return AIRPDCAP_RET_NO_VALID_HANDSHAKE;
}
key_index += decrypted_data[key_index+1]+2;
}else{
key_found = TRUE;
}
}
if (key_found){
if (key_index+8 >= key_bytes_len)
return AIRPDCAP_RET_NO_VALID_HANDSHAKE;
memcpy(szEncryptedKey, decrypted_data+key_index+8, key_bytes_len-key_index-8);
}
g_free(decrypted_data);
}
key_len = (sa->wpa.key_ver==AIRPDCAP_WPA_KEY_VER_NOT_CCMP)?TKIP_GROUP_KEY_LEN:CCMP_GROUP_KEY_LEN;
DEBUG_DUMP("Broadcast key:", szEncryptedKey, key_len);
sa->key = &dummy_key;  
sa->validKey = TRUE;
memset(sa->wpa.ptk, 0, sizeof(sa->wpa.ptk));
memcpy(sa->wpa.ptk+32, szEncryptedKey, key_len);
return AIRPDCAP_RET_SUCCESS_HANDSHAKE;
}

static Image *ReadXCFImage(const ImageInfo *image_info,ExceptionInfo *exception)
{
char
magick[14];
Image
*image;
int
foundPropEnd = 0;
MagickBooleanType
status;
MagickOffsetType
offset;
register ssize_t
i;
size_t
image_type,
length;
ssize_t
count;
XCFDocInfo
doc_info;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickSignature);
if (image_info->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
image_info->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickSignature);
image=AcquireImage(image_info);
status=OpenBlob(image_info,image,ReadBinaryBlobMode,exception);
if (status == MagickFalse)
{
image=DestroyImageList(image);
return((Image *) NULL);
}
count=ReadBlob(image,14,(unsigned char *) magick);
if ((count != 14) ||
(LocaleNCompare((char *) magick,"gimp xcf",8) != 0))
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
(void) ResetMagickMemory(&doc_info,0,sizeof(XCFDocInfo));
doc_info.exception=exception;
doc_info.width=ReadBlobMSBLong(image);
doc_info.height=ReadBlobMSBLong(image);
if ((doc_info.width > 262144) || (doc_info.height > 262144))
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
doc_info.image_type=ReadBlobMSBLong(image);
image->columns=doc_info.width;
image->rows=doc_info.height;
image_type=doc_info.image_type;
doc_info.file_size=GetBlobSize(image);
image->compression=NoCompression;
image->depth=8;
status=SetImageExtent(image,image->columns,image->rows);
if (status == MagickFalse)
{
InheritException(exception,&image->exception);
return(DestroyImageList(image));
}
if (image_type == GIMP_RGB)
;
else
if (image_type == GIMP_GRAY)
image->colorspace=GRAYColorspace;
else
if (image_type == GIMP_INDEXED)
ThrowReaderException(CoderError,"ColormapTypeNotSupported");
(void) SetImageOpacity(image,OpaqueOpacity); 
(void) SetImageBackgroundColor(image);
while ((foundPropEnd == MagickFalse) && (EOFBlob(image) == MagickFalse))
{
PropType prop_type = (PropType) ReadBlobMSBLong(image);
size_t prop_size = ReadBlobMSBLong(image);
switch (prop_type)
{
case PROP_END:
foundPropEnd=1;
break;
case PROP_COLORMAP:
{
size_t num_colours = ReadBlobMSBLong(image);
if (DiscardBlobBytes(image,3*num_colours) == MagickFalse)
ThrowFileException(&image->exception,CorruptImageError,
"UnexpectedEndOfFile",image->filename);
break;
}
case PROP_COMPRESSION:
{
doc_info.compression = ReadBlobByte(image);
if ((doc_info.compression != COMPRESS_NONE) &&
(doc_info.compression != COMPRESS_RLE) &&
(doc_info.compression != COMPRESS_ZLIB) &&
(doc_info.compression != COMPRESS_FRACTAL))
ThrowReaderException(CorruptImageError,"UnrecognizedImageCompression");
}
break;
case PROP_GUIDES:
{
if (DiscardBlobBytes(image,prop_size) == MagickFalse)
ThrowFileException(&image->exception,CorruptImageError,
"UnexpectedEndOfFile",image->filename);
}
break;
case PROP_RESOLUTION:
{
(void) ReadBlobMSBLong(image);
