PJ_DEF(void) pjsip_auth_create_digestSHA256(pj_str_t *result,
const pj_str_t *nonce,
const pj_str_t *nc,
const pj_str_t *cnonce,
const pj_str_t *qop,
const pj_str_t *uri,
const pj_str_t *realm,
const pjsip_cred_info *cred_info,
const pj_str_t *method)
{
#if PJSIP_AUTH_HAS_DIGEST_SHA256
char ha1[PJSIP_SHA256STRLEN];
char ha2[PJSIP_SHA256STRLEN];
unsigned char digest[32];
SHA256_CTX pms;
pj_assert(result->slen >= PJSIP_SHA256STRLEN);
AUTH_TRACE_((THIS_FILE, "Begin creating digest"));
if ((cred_info->data_type & PASSWD_MASK) == PJSIP_CRED_DATA_PLAIN_PASSWD)
{
SHA256_Init(&pms);
SHA256_Update( &pms, cred_info->username.ptr,
cred_info->username.slen);
SHA256_Update( &pms, ":", 1);
SHA256_Update( &pms, realm->ptr, realm->slen);
SHA256_Update( &pms, ":", 1);
SHA256_Update( &pms, cred_info->data.ptr, cred_info->data.slen);
SHA256_Final(digest, &pms);
digestNtoStr(digest, 32, ha1);
} else if ((cred_info->data_type & PASSWD_MASK) == PJSIP_CRED_DATA_DIGEST)
{
pj_assert(cred_info->data.slen == 32);
pj_memcpy( ha1, cred_info->data.ptr, cred_info->data.slen );
} else {
pj_assert(!"Invalid data_type");
}
AUTH_TRACE_((THIS_FILE, " ha1=%.64s", ha1));
SHA256_Init(&pms);
SHA256_Update( &pms, method->ptr, method->slen);
SHA256_Update( &pms, ":", 1);
SHA256_Update( &pms, uri->ptr, uri->slen);
SHA256_Final( digest, &pms);
digestNtoStr(digest, 32, ha2);
AUTH_TRACE_((THIS_FILE, " ha2=%.64s", ha2));
SHA256_Init(&pms);
SHA256_Update( &pms, ha1, PJSIP_SHA256STRLEN);
SHA256_Update( &pms, ":", 1);
SHA256_Update( &pms, nonce->ptr, nonce->slen);
if (qop && qop->slen != 0) {
SHA256_Update( &pms, ":", 1);
SHA256_Update( &pms, nc->ptr, nc->slen);
SHA256_Update( &pms, ":", 1);
SHA256_Update( &pms, cnonce->ptr, cnonce->slen);
SHA256_Update( &pms, ":", 1);
SHA256_Update( &pms, qop->ptr, qop->slen);
}
SHA256_Update( &pms, ":", 1);
SHA256_Update( &pms, ha2, PJSIP_SHA256STRLEN);
SHA256_Final(digest, &pms);
result->slen = PJSIP_SHA256STRLEN;
digestNtoStr(digest, 32, result->ptr);
AUTH_TRACE_((THIS_FILE, " digest=%.64s", result->ptr));
AUTH_TRACE_((THIS_FILE, "Digest created"));
#else
PJ_UNUSED_ARG(result);
PJ_UNUSED_ARG(nonce);
PJ_UNUSED_ARG(nc);
PJ_UNUSED_ARG(cnonce);
PJ_UNUSED_ARG(qop);
PJ_UNUSED_ARG(uri);
PJ_UNUSED_ARG(realm);
PJ_UNUSED_ARG(cred_info);
PJ_UNUSED_ARG(method);
#endif
}

static int skcipher_accept_parent(void *private, struct sock *sk)
{
struct skcipher_ctx *ctx;
struct alg_sock *ask = alg_sk(sk);
unsigned int len = sizeof(*ctx) + crypto_skcipher_reqsize(private);
ctx = sock_kmalloc(sk, len, GFP_KERNEL);
if (!ctx)
return -ENOMEM;
ctx->iv = sock_kmalloc(sk, crypto_skcipher_ivsize(private),
GFP_KERNEL);
if (!ctx->iv) {
sock_kfree_s(sk, ctx, len);
return -ENOMEM;
}
memset(ctx->iv, 0, crypto_skcipher_ivsize(private));
INIT_LIST_HEAD(&ctx->tsgl);
ctx->len = len;
ctx->used = 0;
ctx->more = 0;
ctx->merge = 0;
ctx->enc = 0;
atomic_set(&ctx->inflight, 0);
af_alg_init_completion(&ctx->completion);
ask->private = ctx;
skcipher_request_set_tfm(&ctx->req, private);
skcipher_request_set_callback(&ctx->req, CRYPTO_TFM_REQ_MAY_BACKLOG,
af_alg_complete, &ctx->completion);
sk->sk_destruct = skcipher_sock_destruct;
return 0;
}

void Compute(OpKernelContext* context) override {
const Tensor& x = context->input(0);
const Tensor& y = context->input(1);
const float min_x = context->input(2).flat<float>()(0);
const float max_x = context->input(3).flat<float>()(0);
const float min_y = context->input(4).flat<float>()(0);
const float max_y = context->input(5).flat<float>()(0);
BCast bcast(BCast::FromShape(x.shape()), BCast::FromShape(y.shape()));
if (!bcast.IsValid()) {
context->SetStatus(errors::InvalidArgument(
"Incompatible shapes: ", x.shape().DebugString(), " vs. ",
y.shape().DebugString()));
return;
}
Tensor* z;
OP_REQUIRES_OK(context, context->allocate_output(
0, BCast::ToShape(bcast.output_shape()), &z));
OP_REQUIRES(context, (max_x > min_x),
errors::InvalidArgument("max_x must be larger than min_x."));
OP_REQUIRES(context, (max_y > min_y),
errors::InvalidArgument("max_y must be larger than min_y."));
const T* x_data = x.flat<T>().data();
const T* y_data = y.flat<T>().data();
Toutput* z_data = z->flat<Toutput>().data();
const float smallest_min = std::min(min_x, min_y);
const float largest_max = std::max(max_x, max_y);
const float biggest_range =
std::max(std::abs(smallest_min), std::abs(largest_max));
const float output_range = (biggest_range * (1 << 14));
const float min_z_value = -output_range;
const float max_z_value = output_range;
const int ndims = bcast.x_reshape().size();
if (ndims <= 1) {
if (x.NumElements() == 1) {
ScalarAddition<T, Toutput>(context, y_data, min_y, max_y,
y.NumElements(), x_data[0], min_x, max_x,
min_z_value, max_z_value, z_data);
} else if (y.NumElements() == 1) {
ScalarAddition<T, Toutput>(context, x_data, min_x, max_x,
x.NumElements(), y_data[0], min_y, max_y,
min_z_value, max_z_value, z_data);
} else {
VectorAddition<T, Toutput>(context, x_data, min_x, max_x, y_data, min_y,
max_y, x.NumElements(), min_z_value,
max_z_value, z_data);
}
} else if (ndims == 2) {
const T* vector_data;
int64_t vector_num_elements;
float vector_min;
float vector_max;
const T* tensor_data;
int64_t tensor_num_elements;
float tensor_min;
float tensor_max;
if (x.NumElements() < y.NumElements()) {
vector_data = x_data;
vector_num_elements = x.NumElements();
vector_min = min_x;
vector_max = max_x;
tensor_data = y_data;
tensor_num_elements = y.NumElements();
tensor_min = min_y;
tensor_max = max_y;
} else {
vector_data = y_data;
vector_num_elements = y.NumElements();
vector_min = min_y;
vector_max = max_y;
tensor_data = x_data;
tensor_num_elements = x.NumElements();
tensor_min = min_x;
tensor_max = max_x;
}
OP_REQUIRES(context, vector_num_elements > 0,
errors::InvalidArgument("Must have some elements to add"));
VectorTensorAddition<T, Toutput>(
vector_data, vector_min, vector_max, vector_num_elements, tensor_data,
tensor_min, tensor_max, tensor_num_elements, min_z_value, max_z_value,
z_data);
} else {
LOG(INFO) << "ndims=" << ndims;
LOG(INFO) << "bcast.x_reshape()="
<< TensorShape(bcast.x_reshape()).DebugString();
LOG(INFO) << "bcast.y_reshape()="
<< TensorShape(bcast.y_reshape()).DebugString();
LOG(INFO) << "bcast.x_bcast()="
<< TensorShape(bcast.x_bcast()).DebugString();
LOG(INFO) << "bcast.y_bcast()="
<< TensorShape(bcast.y_bcast()).DebugString();
context->SetStatus(errors::Unimplemented(
"Broadcast between ", context->input(0).shape().DebugString(),
" and ", context->input(1).shape().DebugString(),
" is not supported yet."));
return;
}
Tensor* z_min = nullptr;
OP_REQUIRES_OK(context, context->allocate_output(1, {}, &z_min));
z_min->flat<float>()(0) = min_z_value;
Tensor* z_max = nullptr;
OP_REQUIRES_OK(context, context->allocate_output(2, {}, &z_max));
z_max->flat<float>()(0) = max_z_value;
}

static bfd_boolean
ihex_read_section (bfd *abfd, asection *section, bfd_byte *contents)
{
int c;
bfd_byte *p;
bfd_byte *buf = NULL;
size_t bufsize;
bfd_boolean error;
if (bfd_seek (abfd, section->filepos, SEEK_SET) != 0)
goto error_return;
p = contents;
bufsize = 0;
error = FALSE;
while ((c = ihex_get_byte (abfd, &error)) != EOF)
{
char hdr[8];
unsigned int len;
unsigned int type;
unsigned int i;
if (c == '\r' || c == '\n')
continue;
BFD_ASSERT (c == ':');
if (bfd_bread (hdr, (bfd_size_type) 8, abfd) != 8)
goto error_return;
len = HEX2 (hdr);
type = HEX2 (hdr + 6);
if (type != 0)
{
(*_bfd_error_handler)
(_("%B: internal error in ihex_read_section"), abfd);
bfd_set_error (bfd_error_bad_value);
goto error_return;
}
if (len * 2 > bufsize)
{
buf = (bfd_byte *) bfd_realloc (buf, (bfd_size_type) len * 2);
if (buf == NULL)
goto error_return;
bufsize = len * 2;
}
if (bfd_bread (buf, (bfd_size_type) len * 2, abfd) != len * 2)
goto error_return;
for (i = 0; i < len; i++)
*p++ = HEX2 (buf + 2 * i);
if ((bfd_size_type) (p - contents) >= section->size)
{
if (buf != NULL)
free (buf);
return TRUE;
}
if (bfd_bread (buf, (bfd_size_type) 2, abfd) != 2)
goto error_return;
}
if ((bfd_size_type) (p - contents) < section->size)
{
(*_bfd_error_handler)
(_("%B: bad section length in ihex_read_section"), abfd);
bfd_set_error (bfd_error_bad_value);
goto error_return;
}
if (buf != NULL)
free (buf);
return TRUE;
error_return:
if (buf != NULL)
free (buf);
return FALSE;
}

void
vi_pci_write(UNUSED int vcpu, struct pci_devinst *pi, int baridx,
uint64_t offset, int size, uint64_t value)
{
struct virtio_softc *vs = pi->pi_arg;
struct vqueue_info *vq;
struct virtio_consts *vc;
struct config_reg *cr;
uint64_t virtio_config_size, max;
const char *name;
uint32_t newoff;
int error;
if (vs->vs_flags & VIRTIO_USE_MSIX) {
if (baridx == pci_msix_table_bar(pi) ||
baridx == pci_msix_pba_bar(pi)) {
pci_emul_msix_twrite(pi, offset, size, value);
return;
}
}
assert(baridx == 0);
if (vs->vs_mtx)
pthread_mutex_lock(vs->vs_mtx);
vc = vs->vs_vc;
name = vc->vc_name;
if (size != 1 && size != 2 && size != 4)
goto bad;
if (pci_msix_enabled(pi))
virtio_config_size = VTCFG_R_CFG1;
else
virtio_config_size = VTCFG_R_CFG0;
if (offset >= virtio_config_size) {
newoff = (uint32_t) (offset - virtio_config_size);
max = vc->vc_cfgsize ? vc->vc_cfgsize : 0x100000000;
if ((newoff + ((unsigned) size)) > max)
goto bad;
error = (*vc->vc_cfgwrite)(DEV_SOFTC(vs), ((int) newoff), size,
((uint32_t) value));
if (!error)
goto done;
}
bad:
cr = vi_find_cr((int) offset);
if (cr == NULL || cr->cr_size != size || cr->cr_ro) {
if (cr != NULL) {
if (cr->cr_size != size)
fprintf(stderr,
"%s: write to %s: bad size %d\r\n",
name, cr->cr_name, size);
if (cr->cr_ro)
fprintf(stderr,
"%s: write to read-only reg %s\r\n",
name, cr->cr_name);
} else {
fprintf(stderr,
"%s: write to bad offset/size %jd/%d\r\n",
name, (uintmax_t)offset, size);
}
goto done;
}
switch (offset) {
case VTCFG_R_GUESTCAP:
vs->vs_negotiated_caps = (uint32_t) (value & vc->vc_hv_caps);
if (vc->vc_apply_features)
(*vc->vc_apply_features)(DEV_SOFTC(vs),
vs->vs_negotiated_caps);
break;
case VTCFG_R_PFN:
if (vs->vs_curq >= vc->vc_nvq)
goto bad_qindex;
vi_vq_init(vs, ((uint32_t) value));
break;
case VTCFG_R_QSEL:
vs->vs_curq = (int) value;
break;
case VTCFG_R_QNOTIFY:
if (value >= ((uint64_t) vc->vc_nvq)) {
fprintf(stderr, "%s: queue %d notify out of range\r\n",
name, (int)value);
goto done;
}
vq = &vs->vs_queues[value];
if (vq->vq_notify)
(*vq->vq_notify)(DEV_SOFTC(vs), vq);
else if (vc->vc_qnotify)
(*vc->vc_qnotify)(DEV_SOFTC(vs), vq);
else
fprintf(stderr,
"%s: qnotify queue %d: missing vq/vc notify\r\n",
name, (int)value);
break;
case VTCFG_R_STATUS:
vs->vs_status = (uint8_t) value;
if (value == 0)
(*vc->vc_reset)(DEV_SOFTC(vs));
break;
case VTCFG_R_CFGVEC:
vs->vs_msix_cfg_idx = (uint16_t) value;
break;
case VTCFG_R_QVEC:
if (vs->vs_curq >= vc->vc_nvq)
goto bad_qindex;
vq = &vs->vs_queues[vs->vs_curq];
vq->vq_msix_idx = (uint16_t) value;
break;
}
goto done;
bad_qindex:
fprintf(stderr,
"%s: write config reg %s: curq %d >= max %d\r\n",
name, cr->cr_name, vs->vs_curq, vc->vc_nvq);
done:
if (vs->vs_mtx)
pthread_mutex_unlock(vs->vs_mtx);
}

static size_t _iphc_ipv6_encode(gnrc_pktsnip_t *pkt,
const gnrc_netif_hdr_t *netif_hdr,
gnrc_netif_t *iface,
uint8_t *iphc_hdr)
{
gnrc_sixlowpan_ctx_t *src_ctx = NULL, *dst_ctx = NULL;
ipv6_hdr_t *ipv6_hdr = pkt->next->data;
bool addr_comp = false;
uint16_t inline_pos = SIXLOWPAN_IPHC_HDR_LEN;
assert(iface != NULL);
iphc_hdr[IPHC1_IDX] = SIXLOWPAN_IPHC1_DISP;
iphc_hdr[IPHC2_IDX] = 0;
if (!ipv6_addr_is_unspecified(&(ipv6_hdr->src))) {
src_ctx = gnrc_sixlowpan_ctx_lookup_addr(&(ipv6_hdr->src));
if (src_ctx && !(src_ctx->flags_id & GNRC_SIXLOWPAN_CTX_FLAGS_COMP)) {
src_ctx = NULL;
}
if (src_ctx &&
ipv6_addr_match_prefix(&src_ctx->prefix, &ipv6_hdr->src) < SIXLOWPAN_IPHC_PREFIX_LEN) {
src_ctx = NULL;
}
}
if (!ipv6_addr_is_multicast(&ipv6_hdr->dst)) {
dst_ctx = gnrc_sixlowpan_ctx_lookup_addr(&(ipv6_hdr->dst));
if (dst_ctx && !(dst_ctx->flags_id & GNRC_SIXLOWPAN_CTX_FLAGS_COMP)) {
dst_ctx = NULL;
}
if (dst_ctx &&
ipv6_addr_match_prefix(&dst_ctx->prefix, &ipv6_hdr->dst) < SIXLOWPAN_IPHC_PREFIX_LEN) {
dst_ctx = NULL;
}
}
if (((src_ctx != NULL) &&
((src_ctx->flags_id & GNRC_SIXLOWPAN_CTX_FLAGS_CID_MASK) != 0)) ||
((dst_ctx != NULL) &&
((dst_ctx->flags_id & GNRC_SIXLOWPAN_CTX_FLAGS_CID_MASK) != 0))) {
iphc_hdr[IPHC2_IDX] |= SIXLOWPAN_IPHC2_CID_EXT;
iphc_hdr[CID_EXT_IDX] = 0;
inline_pos += SIXLOWPAN_IPHC_CID_EXT_LEN;
}
if (ipv6_hdr_get_fl(ipv6_hdr) == 0) {
if (ipv6_hdr_get_tc(ipv6_hdr) == 0) {
iphc_hdr[IPHC1_IDX] |= IPHC_TF_ECN_ELIDE;
}
else {
iphc_hdr[IPHC1_IDX] |= IPHC_TF_ECN_DSCP;
iphc_hdr[inline_pos++] = ipv6_hdr_get_tc(ipv6_hdr);
}
}
else {
if (ipv6_hdr_get_tc_dscp(ipv6_hdr) == 0) {
iphc_hdr[IPHC1_IDX] |= IPHC_TF_ECN_FL;
iphc_hdr[inline_pos++] = (uint8_t)((ipv6_hdr_get_tc_ecn(ipv6_hdr) << 6) |
((ipv6_hdr_get_fl(ipv6_hdr) & 0x000f0000) >> 16));
}
else {
iphc_hdr[IPHC1_IDX] |= IPHC_TF_ECN_DSCP_FL;
iphc_hdr[inline_pos++] = ipv6_hdr_get_tc(ipv6_hdr);
iphc_hdr[inline_pos++] = (uint8_t)((ipv6_hdr_get_fl(ipv6_hdr) & 0x000f0000) >> 16);
}
iphc_hdr[inline_pos++] = (uint8_t)((ipv6_hdr_get_fl(ipv6_hdr) & 0x0000ff00) >> 8);
iphc_hdr[inline_pos++] = (uint8_t)(ipv6_hdr_get_fl(ipv6_hdr) & 0x000000ff);
}
if (_compressible_nh(ipv6_hdr->nh)) {
iphc_hdr[IPHC1_IDX] |= SIXLOWPAN_IPHC1_NH;
}
else {
iphc_hdr[inline_pos++] = ipv6_hdr->nh;
}
switch (ipv6_hdr->hl) {
case 1:
iphc_hdr[IPHC1_IDX] |= IPHC_HL_1;
break;
case 64:
iphc_hdr[IPHC1_IDX] |= IPHC_HL_64;
break;
case 255:
iphc_hdr[IPHC1_IDX] |= IPHC_HL_255;
break;
default:
iphc_hdr[IPHC1_IDX] |= IPHC_HL_INLINE;
iphc_hdr[inline_pos++] = ipv6_hdr->hl;
break;
}
if (ipv6_addr_is_unspecified(&(ipv6_hdr->src))) {
iphc_hdr[IPHC2_IDX] |= IPHC_SAC_SAM_UNSPEC;
}
else {
if (src_ctx != NULL) {
iphc_hdr[IPHC2_IDX] |= SIXLOWPAN_IPHC2_SAC;
if (((src_ctx->flags_id & GNRC_SIXLOWPAN_CTX_FLAGS_CID_MASK) != 0)) {
iphc_hdr[CID_EXT_IDX] |= ((src_ctx->flags_id & GNRC_SIXLOWPAN_CTX_FLAGS_CID_MASK) << 4);
}
}
if ((src_ctx != NULL) || ipv6_addr_is_link_local(&(ipv6_hdr->src))) {
eui64_t iid;
iid.uint64.u64 = 0;
gnrc_netif_acquire(iface);
if (gnrc_netif_ipv6_get_iid(iface, &iid) < 0) {
DEBUG("6lo iphc: could not get interface's IID\n");
gnrc_netif_release(iface);
return 0;
}
gnrc_netif_release(iface);
if ((ipv6_hdr->src.u64[1].u64 == iid.uint64.u64) ||
_context_overlaps_iid(src_ctx, &ipv6_hdr->src, &iid)) {
iphc_hdr[IPHC2_IDX] |= IPHC_SAC_SAM_L2;
addr_comp = true;
}
else if ((byteorder_ntohl(ipv6_hdr->src.u32[2]) == 0x000000ff) &&
(byteorder_ntohs(ipv6_hdr->src.u16[6]) == 0xfe00)) {
iphc_hdr[IPHC2_IDX] |= IPHC_SAC_SAM_16;
memcpy(iphc_hdr + inline_pos, ipv6_hdr->src.u16 + 7, 2);
inline_pos += 2;
addr_comp = true;
}
else {
iphc_hdr[IPHC2_IDX] |= IPHC_SAC_SAM_64;
memcpy(iphc_hdr + inline_pos, ipv6_hdr->src.u64 + 1, 8);
inline_pos += 8;
addr_comp = true;
}
}
if (!addr_comp) {
iphc_hdr[IPHC2_IDX] |= IPHC_SAC_SAM_FULL;
memcpy(iphc_hdr + inline_pos, &ipv6_hdr->src, 16);
inline_pos += 16;
}
}
addr_comp = false;
if (ipv6_addr_is_multicast(&(ipv6_hdr->dst))) {
iphc_hdr[IPHC2_IDX] |= SIXLOWPAN_IPHC2_M;
if ((ipv6_hdr->dst.u16[1].u16 == 0) &&
(ipv6_hdr->dst.u32[1].u32 == 0) &&
(ipv6_hdr->dst.u16[4].u16 == 0)) {
if ((ipv6_hdr->dst.u8[1] == 0x02) &&
(ipv6_hdr->dst.u32[2].u32 == 0) &&
(ipv6_hdr->dst.u16[6].u16 == 0) &&
(ipv6_hdr->dst.u8[14] == 0)) {
iphc_hdr[IPHC2_IDX] |= IPHC_M_DAC_DAM_M_8;
iphc_hdr[inline_pos++] = ipv6_hdr->dst.u8[15];
addr_comp = true;
}
else if ((ipv6_hdr->dst.u16[5].u16 == 0) &&
(ipv6_hdr->dst.u8[12] == 0)) {
iphc_hdr[IPHC2_IDX] |= IPHC_M_DAC_DAM_M_32;
iphc_hdr[inline_pos++] = ipv6_hdr->dst.u8[1];
memcpy(iphc_hdr + inline_pos, ipv6_hdr->dst.u8 + 13, 3);
inline_pos += 3;
addr_comp = true;
}
else if (ipv6_hdr->dst.u8[10] == 0) {
iphc_hdr[IPHC2_IDX] |= IPHC_M_DAC_DAM_M_48;
iphc_hdr[inline_pos++] = ipv6_hdr->dst.u8[1];
memcpy(iphc_hdr + inline_pos, ipv6_hdr->dst.u8 + 11, 5);
inline_pos += 5;
addr_comp = true;
}
}
else {
gnrc_sixlowpan_ctx_t *ctx;
ipv6_addr_t unicast_prefix;
unicast_prefix.u16[0] = ipv6_hdr->dst.u16[2];
unicast_prefix.u16[1] = ipv6_hdr->dst.u16[3];
unicast_prefix.u16[2] = ipv6_hdr->dst.u16[4];
unicast_prefix.u16[3] = ipv6_hdr->dst.u16[5];
ctx = gnrc_sixlowpan_ctx_lookup_addr(&unicast_prefix);
if ((ctx != NULL) && (ctx->flags_id & GNRC_SIXLOWPAN_CTX_FLAGS_COMP) &&
(ctx->prefix_len == ipv6_hdr->dst.u8[3])) {
iphc_hdr[IPHC2_IDX] |= SIXLOWPAN_IPHC2_DAC;
if ((ctx->flags_id & GNRC_SIXLOWPAN_CTX_FLAGS_CID_MASK) != 0) {
iphc_hdr[CID_EXT_IDX] |= (ctx->flags_id & GNRC_SIXLOWPAN_CTX_FLAGS_CID_MASK);
}
iphc_hdr[inline_pos++] = ipv6_hdr->dst.u8[1];
iphc_hdr[inline_pos++] = ipv6_hdr->dst.u8[2];
memcpy(iphc_hdr + inline_pos, ipv6_hdr->dst.u16 + 6, 4);
inline_pos += 4;
addr_comp = true;
}
}
}
else if (((dst_ctx != NULL) ||
ipv6_addr_is_link_local(&ipv6_hdr->dst)) && (netif_hdr->dst_l2addr_len > 0)) {
eui64_t iid;
if (dst_ctx != NULL) {
iphc_hdr[IPHC2_IDX] |= SIXLOWPAN_IPHC2_DAC;
if (((dst_ctx->flags_id & GNRC_SIXLOWPAN_CTX_FLAGS_CID_MASK) != 0)) {
iphc_hdr[CID_EXT_IDX] |= (dst_ctx->flags_id & GNRC_SIXLOWPAN_CTX_FLAGS_CID_MASK);
}
}
if (gnrc_netif_hdr_ipv6_iid_from_dst(iface, netif_hdr, &iid) < 0) {
DEBUG("6lo iphc: could not get destination's IID\n");
return 0;
}
if ((ipv6_hdr->dst.u64[1].u64 == iid.uint64.u64) ||
_context_overlaps_iid(dst_ctx, &(ipv6_hdr->dst), &iid)) {
iphc_hdr[IPHC2_IDX] |= IPHC_M_DAC_DAM_U_L2;
addr_comp = true;
}
else if ((byteorder_ntohl(ipv6_hdr->dst.u32[2]) == 0x000000ff) &&
(byteorder_ntohs(ipv6_hdr->dst.u16[6]) == 0xfe00)) {
iphc_hdr[IPHC2_IDX] |= IPHC_M_DAC_DAM_U_16;
memcpy(&(iphc_hdr[inline_pos]), &(ipv6_hdr->dst.u16[7]), 2);
inline_pos += 2;
addr_comp = true;
}
else {
iphc_hdr[IPHC2_IDX] |= IPHC_M_DAC_DAM_U_64;
memcpy(&(iphc_hdr[inline_pos]), &(ipv6_hdr->dst.u8[8]), 8);
inline_pos += 8;
addr_comp = true;
}
}
if (!addr_comp) {
iphc_hdr[IPHC2_IDX] |= IPHC_SAC_SAM_FULL;
memcpy(iphc_hdr + inline_pos, &ipv6_hdr->dst, 16);
inline_pos += 16;
}
return inline_pos;
}

sds utf16le_to_utf8(const uint8_t *inb, int inlenb) {
uint16_t *in = (uint16_t *)inb;
uint16_t *inend;
uint32_t c, d, inlen;
int bits;
if ((inlenb % 2) == 1) (inlenb)--;
inlen = inlenb / 2;
inend = in + inlen;
uint32_t bytesNeeded = 0;
while (in < inend) {
c = *in++;
if ((c & 0xFC00) == 0xD800) { if (in >= inend) {        break;
}
d = *in++;
if ((d & 0xFC00) == 0xDC00) {
c &= 0x03FF;
c <<= 10;
c |= d & 0x03FF;
c += 0x10000;
}
}
if (c < 0x80) {
bytesNeeded += 1;
} else if (c < 0x800) {
bytesNeeded += 2;
} else if (c < 0x10000) {
bytesNeeded += 3;
} else {
bytesNeeded += 4;
}
}
in = (uint16_t *)inb;
sds out = sdsnewlen("", bytesNeeded);
sds out0 = out;
while (in < inend) {
c = *in++;
if ((c & 0xFC00) == 0xD800) {
if (in >= inend) { break; }
d = *in++;
if ((d & 0xFC00) == 0xDC00) {
c &= 0x03FF;
c <<= 10;
c |= d & 0x03FF;
c += 0x10000;
}
}
if (c < 0x80) {
*out++ = c;
bits = -6;
} else if (c < 0x800) {
*out++ = ((c >> 6) & 0x1F) | 0xC0;
bits = 0;
} else if (c < 0x10000) {
*out++ = ((c >> 12) & 0x0F) | 0xE0;
bits = 6;
} else {
*out++ = ((c >> 18) & 0x07) | 0xF0;
bits = 12;
}
for (; bits >= 0; bits -= 6) {
*out++ = ((c >> bits) & 0x3F) | 0x80;
}
}
return out0;
}

