goto err_put;
}
if ((attr->flags & BPF_F_LOCK) &&
!map_value_has_spin_lock(map)) {
err = -EINVAL;
goto err_put;
}
key = __bpf_copy_key(ukey, map->key_size);
if (IS_ERR(key)) {
err = PTR_ERR(key);
goto err_put;
}
value_size = bpf_map_value_size(map);
err = -ENOMEM;
value = kvmalloc(value_size, GFP_USER | __GFP_NOWARN);
if (!value)
goto free_key;
err = -ENOTSUPP;
if (map->map_type == BPF_MAP_TYPE_QUEUE ||
map->map_type == BPF_MAP_TYPE_STACK) {
err = map->ops->map_pop_elem(map, value);
} else if (map->map_type == BPF_MAP_TYPE_HASH ||
map->map_type == BPF_MAP_TYPE_PERCPU_HASH ||
map->map_type == BPF_MAP_TYPE_LRU_HASH ||
map->map_type == BPF_MAP_TYPE_LRU_PERCPU_HASH) {
if (!bpf_map_is_dev_bound(map)) {
bpf_disable_instrumentation();
rcu_read_lock();
err = map->ops->map_lookup_and_delete_elem(map, key, value, attr->flags);
rcu_read_unlock();
bpf_enable_instrumentation();
}
}
if (err)
goto free_value;
if (copy_to_user(uvalue, value, value_size) != 0) {
err = -EFAULT;
goto free_value;
}
err = 0;
free_value:
kvfree(value);
free_key:
kvfree(key);
err_put:
fdput(f);
return err;
}

AP4_Result
AP4_AtomSampleTable::GetSample(AP4_Ordinal index, 
AP4_Sample& sample)
{
AP4_Result result;
if (m_StcoAtom == NULL && m_Co64Atom == NULL) {
return AP4_ERROR_INVALID_FORMAT;
}
index++;
AP4_Ordinal chunk, skip, desc;
result = m_StscAtom->GetChunkForSample(index, chunk, skip, desc);
if (AP4_FAILED(result)) return result;
if (skip > index) return AP4_ERROR_INTERNAL;
AP4_UI64 offset;
if (m_StcoAtom) {
AP4_UI32 offset_32;
result = m_StcoAtom->GetChunkOffset(chunk, offset_32);
offset = offset_32;
} else {
result = m_Co64Atom->GetChunkOffset(chunk, offset);
}
if (AP4_FAILED(result)) return result;
for (unsigned int i = index-skip; i < index; i++) {
AP4_Size size = 0;
if (m_StszAtom) {
result = m_StszAtom->GetSampleSize(i, size); 
} else if (m_Stz2Atom) {
result = m_Stz2Atom->GetSampleSize(i, size); 
} else {
result = AP4_ERROR_INVALID_FORMAT;
}
if (AP4_FAILED(result)) return result;
offset += size;
}
sample.SetDescriptionIndex(desc-1); 
AP4_UI32 cts_offset = 0;
AP4_UI64 dts        = 0;
AP4_UI32 duration   = 0;
result = m_SttsAtom->GetDts(index, dts, &duration);
if (AP4_FAILED(result)) return result;
sample.SetDuration(duration);
sample.SetDts(dts);
if (m_CttsAtom == NULL) {
sample.SetCts(dts);
} else {
result = m_CttsAtom->GetCtsOffset(index, cts_offset); 
if (AP4_FAILED(result)) return result;
sample.SetCtsDelta(cts_offset);
}     
AP4_Size sample_size = 0;
if (m_StszAtom) {
result = m_StszAtom->GetSampleSize(index, sample_size); 
} else if (m_Stz2Atom) {
result = m_Stz2Atom->GetSampleSize(index, sample_size); 
} else {
result = AP4_ERROR_INVALID_FORMAT;
}
if (AP4_FAILED(result)) return result;
sample.SetSize(sample_size);
if (m_StssAtom == NULL) {
sample.SetSync(true);
} else {
sample.SetSync(m_StssAtom->IsSampleSync(index));
}
sample.SetOffset(offset);
sample.SetDataStream(m_SampleStream);
return AP4_SUCCESS;
}

void get_cmdln_options(int argc, char *argv[]) {
int o;
#if CONFIG_FILE && HAVE_GETPWUID
static struct passwd *pwd_entry;
char *str;
#endif
#ifdef LONG_OPTIONS
int option_index = 0;
static struct option long_options[] = {
{"timeout", 1, 0, 't'},
#ifdef PROC_NET_DEV
{"procfile",1,0,'f'},
#endif
#ifdef PROC_DISKSTATS
{"diskstatsfile",1,0,1000},
{"partitionsfile",1,0,1001},
#endif  
#if NETSTAT && ALLOW_NETSTATPATH
{"netstat",1,0,'n'},
#endif
#if IOSERVICE_IN
{"longdisknames",0,0,1002},
#endif
{"input",1,0,'i'},
{"dynamic",1,0,'d'},
{"help", 0, 0, 'h'},
{"version",0,0,'V'},
{"allif",1,0,'a'},
{"unit",1,0,'u'},
{"ansiout",0,0,'N'},
#if EXTENDED_STATS        
{"type",1,0,'T'},
{"avglength",1,0,'A'},
#endif        
{"interfaces",1,0,'I'},
{"sumhidden",1,0,'S'},
{"output",1,0,'o'},
#ifdef CSV
{"csvchar",1,0,'C'},
{"csvfile",1,0,'F'},
#endif
{"count",1,0,'c'},
{"daemon",1,0,'D'},
#ifdef HTML
{"htmlrefresh",1,0,'R'},
{"htmlheader",1,0,'H'},
#endif
{0,0,0,0}
};
#endif
#ifdef CONFIG_FILE
opterr=0;
while (1) {
#ifdef LONG_OPTIONS
o=getopt_long (argc,argv,SHORT_OPTIONS,long_options, &option_index);
#else
o=getopt (argc,argv,SHORT_OPTIONS);
#endif
if (o==-1) break;
}
opterr=1;
if (optind < argc) {
read_config(argv[optind]);
} else {
read_config("/etc/bwm-ng.conf");
#ifdef HAVE_GETPWUID    
pwd_entry=getpwuid(getuid());
if (pwd_entry!=NULL) {
str=(char*)malloc(strlen(pwd_entry->pw_dir)+14);
snprintf(str,strlen(pwd_entry->pw_dir)+14,"%s/.bwm-ng.conf",pwd_entry->pw_dir);
read_config(str);
free(str);
}
#endif    
}
optind=1;
#endif
while (1) {
#ifdef LONG_OPTIONS
o=getopt_long (argc,argv,SHORT_OPTIONS,long_options, &option_index);
#else
o=getopt (argc,argv,SHORT_OPTIONS);
#endif
if (o==-1) break;
switch (o) {
case '?': printf("unknown option: %s\n",argv[optind-1]);
exit(EXIT_FAILURE);
break;
case ':': if (!strcmp(argv[optind-1],"-a") || !strcasecmp(argv[optind-1],"--allif")) 
show_all_if=1;
else if (!strcmp(argv[optind-1],"-d") || !strcasecmp(argv[optind-1],"--dynamic"))
dynamic=1;
else if (!strcmp(argv[optind-1],"-D") || !strcasecmp(argv[optind-1],"--daemon"))
daemonize=1;
#ifdef HTML                      
else if (!strcmp(argv[optind-1],"-H") || !strcasecmp(argv[optind-1],"--htmlheader"))
html_header=1;
#endif                      
else if (!strcmp(argv[optind-1],"-S") || !strcasecmp(argv[optind-1],"--sumhidden"))
sumhidden=1;    
else {
printf("%s requires an argument!\n",argv[optind-1]);
exit(EXIT_FAILURE);
}
break;
#ifdef PROC_DISKSTATS
case 1000:
if (strlen(optarg)<PATH_MAX) 
strcpy(PROC_DISKSTATS_FILE,optarg);
break;
case 1001:
if (strlen(optarg)<PATH_MAX)
strcpy(PROC_PARTITIONS_FILE,optarg);
break;
#endif
#if IOSERVICE_IN
case 1002:
long_darwin_disk_names=!long_darwin_disk_names;
break;
#endif
case 'D':
if (optarg) daemonize=atoi(optarg);
break;
#ifdef HTML
case 'R':
if ((optarg) && atol(optarg)>0) { html_refresh=atol(optarg); }
break;
case 'H':
if (optarg) html_header=atoi(optarg);
break;
#endif
case 'c':
if (optarg) output_count=atol(optarg);
break;
#if CSV || HTML
case 'F':
if (optarg) { 
if (out_file) fclose(out_file);
out_file=fopen(optarg,"a"); 
if (!out_file) deinit(1, "failed to open outfile\n");
if (out_file_path) free(out_file_path);
out_file_path=(char *)strdup(optarg);
}
break;
#endif
#ifdef CSV
case 'C':
if (optarg) csv_char=optarg[0];
break;
#endif
case 'h':
cmdln_printhelp();
break;
#ifdef PROC_NET_DEV
case 'f':
if (optarg && (strlen(optarg)<PATH_MAX)) strcpy(PROC_FILE,optarg);
break;
#endif
case 'i':
if (optarg) {
input_method=str2in_method(optarg);
}
break;
case 'I':
if (optarg) iface_list=(char *)strdup(optarg);
break;
case 'S':
if (optarg) sumhidden=atoi(optarg);
break;
case 'o':
if (optarg) {
output_method=str2out_method(optarg);
}
break;
case 'N':
ansi_output=!ansi_output;
case 'a':
if (optarg) show_all_if=atoi(optarg);
break;
case 't':
if ((optarg) && atol(optarg)>0) { delay=atol(optarg); }
break;
#if EXTENDED_STATS                
case 'T':
output_type=str2output_type(optarg);
break;
case 'A':
if (optarg) avg_length=atoi(optarg)*1000;
break;
#endif                
case 'd':
if (optarg) dynamic=atoi(optarg);
break;
case 'u':
output_unit=str2output_unit(optarg);
break;
#if NETSTAT && ALLOW_NETSTATPATH
case 'n':
if (optarg && (strlen(optarg)<PATH_MAX)) strcpy(NETSTAT_FILE,optarg);
break;
#endif                
case 'V':
print_version;
exit(EXIT_SUCCESS);
break;
}
}
if (iface_list==NULL && show_all_if==1) show_all_if=2;
#if EXTENDED_STATS    
if (avg_length==0) {
if (delay<AVG_LENGTH/2) 
avg_length=AVG_LENGTH; 
else  
avg_length=(delay*2)+1;
} else 
if (delay*2>=avg_length) deinit(1, "avglength needs to be a least twice the value of timeout\n");
#endif    
if ((output_unit==ERRORS_OUT && !net_input_method(input_method)) || 
(output_unit==PACKETS_OUT && input_method==LIBSTATDISK_IN)) 
output_unit=BYTES_OUT;
return;
}

u_int
juniper_es_print(netdissect_options *ndo,
const struct pcap_pkthdr *h, register const u_char *p)
{
struct juniper_l2info_t l2info;
struct juniper_ipsec_header {
uint8_t sa_index[2];
uint8_t ttl;
uint8_t type;
uint8_t spi[4];
uint8_t src_ip[4];
uint8_t dst_ip[4];
};
u_int rewrite_len,es_type_bundle;
const struct juniper_ipsec_header *ih;
l2info.pictype = DLT_JUNIPER_ES;
if (juniper_parse_header(ndo, p, h, &l2info) == 0)
return l2info.header_len;
p+=l2info.header_len;
ih = (const struct juniper_ipsec_header *)p;
switch (ih->type) {
case JUNIPER_IPSEC_O_ESP_ENCRYPT_ESP_AUTHEN_TYPE:
case JUNIPER_IPSEC_O_ESP_ENCRYPT_AH_AUTHEN_TYPE:
rewrite_len = 0;
es_type_bundle = 1;
break;
case JUNIPER_IPSEC_O_ESP_AUTHENTICATION_TYPE:
case JUNIPER_IPSEC_O_AH_AUTHENTICATION_TYPE:
case JUNIPER_IPSEC_O_ESP_ENCRYPTION_TYPE:
rewrite_len = 16;
es_type_bundle = 0;
break;
default:
ND_PRINT((ndo, "ES Invalid type %u, length %u",
ih->type,
l2info.length));
return l2info.header_len;
}
l2info.length-=rewrite_len;
p+=rewrite_len;
if (ndo->ndo_eflag) {
if (!es_type_bundle) {
ND_PRINT((ndo, "ES SA, index %u, ttl %u type %s (%u), spi %u, Tunnel %s > %s, length %u\n",
EXTRACT_16BITS(&ih->sa_index),
ih->ttl,
tok2str(juniper_ipsec_type_values,"Unknown",ih->type),
ih->type,
EXTRACT_32BITS(&ih->spi),
ipaddr_string(ndo, &ih->src_ip),
ipaddr_string(ndo, &ih->dst_ip),
l2info.length));
} else {
ND_PRINT((ndo, "ES SA, index %u, ttl %u type %s (%u), length %u\n",
EXTRACT_16BITS(&ih->sa_index),
ih->ttl,
tok2str(juniper_ipsec_type_values,"Unknown",ih->type),
ih->type,
l2info.length));
}
}
ip_print(ndo, p, l2info.length);
return l2info.header_len;
}

static void Sp_replace_regexp(js_State *J)
{
js_Regexp *re;
const char *source, *s, *r;
js_Buffer *sb = NULL;
int n, x;
Resub m;
source = checkstring(J, 0);
re = js_toregexp(J, 1);
if (js_regexec(re->prog, source, &m, 0)) {
js_copy(J, 0);
return;
}
re->last = 0;
loop:
s = m.sub[0].sp;
n = m.sub[0].ep - m.sub[0].sp;
if (js_iscallable(J, 2)) {
js_copy(J, 2);
js_pushundefined(J);
for (x = 0; m.sub[x].sp; ++x) 
js_pushlstring(J, m.sub[x].sp, m.sub[x].ep - m.sub[x].sp);
js_pushnumber(J, s - source); 
js_copy(J, 0); 
js_call(J, 2 + x);
r = js_tostring(J, -1);
js_putm(J, &sb, source, s);
js_puts(J, &sb, r);
js_pop(J, 1);
} else {
r = js_tostring(J, 2);
js_putm(J, &sb, source, s);
while (*r) {
if (*r == '$') {
switch (*(++r)) {
case 0: --r; 
case '$': js_putc(J, &sb, '$'); break;
case '`': js_putm(J, &sb, source, s); break;
case '\'': js_puts(J, &sb, s + n); break;
case '&':
js_putm(J, &sb, s, s + n);
break;
case '0': case '1': case '2': case '3': case '4':
case '5': case '6': case '7': case '8': case '9':
x = *r - '0';
if (r[1] >= '0' && r[1] <= '9')
x = x * 10 + *(++r) - '0';
if (x > 0 && x < m.nsub) {
js_putm(J, &sb, m.sub[x].sp, m.sub[x].ep);
} else {
js_putc(J, &sb, '$');
if (x > 10) {
js_putc(J, &sb, '0' + x / 10);
js_putc(J, &sb, '0' + x % 10);
} else {
js_putc(J, &sb, '0' + x);
}
}
break;
default:
js_putc(J, &sb, '$');
js_putc(J, &sb, *r);
break;
}
++r;
} else {
js_putc(J, &sb, *r++);
}
}
}
if (re->flags & JS_REGEXP_G) {
source = m.sub[0].ep;
if (n == 0) {
if (*source)
js_putc(J, &sb, *source++);
else
goto end;
}
if (!js_regexec(re->prog, source, &m, REG_NOTBOL))
goto loop;
}
end:
js_puts(J, &sb, s + n);
js_putc(J, &sb, 0);
if (js_try(J)) {
js_free(J, sb);
js_throw(J);
}
js_pushstring(J, sb ? sb->s : "");
js_endtry(J);
js_free(J, sb);
}

static int userfaultfd_register(struct userfaultfd_ctx *ctx,
unsigned long arg)
{
struct mm_struct *mm = ctx->mm;
struct vm_area_struct *vma, *prev, *cur;
int ret;
struct uffdio_register uffdio_register;
struct uffdio_register __user *user_uffdio_register;
unsigned long vm_flags, new_flags;
bool found;
bool basic_ioctls;
unsigned long start, end, vma_end;
user_uffdio_register = (struct uffdio_register __user *) arg;
ret = -EFAULT;
if (copy_from_user(&uffdio_register, user_uffdio_register,
sizeof(uffdio_register)-sizeof(__u64)))
goto out;
ret = -EINVAL;
if (!uffdio_register.mode)
goto out;
if (uffdio_register.mode & ~(UFFDIO_REGISTER_MODE_MISSING|
UFFDIO_REGISTER_MODE_WP))
goto out;
vm_flags = 0;
if (uffdio_register.mode & UFFDIO_REGISTER_MODE_MISSING)
vm_flags |= VM_UFFD_MISSING;
if (uffdio_register.mode & UFFDIO_REGISTER_MODE_WP) {
vm_flags |= VM_UFFD_WP;
ret = -EINVAL;
goto out;
}
ret = validate_range(mm, uffdio_register.range.start,
uffdio_register.range.len);
if (ret)
goto out;
start = uffdio_register.range.start;
end = start + uffdio_register.range.len;
ret = -ENOMEM;
if (!mmget_not_zero(mm))
goto out;
down_write(&mm->mmap_sem);
vma = find_vma_prev(mm, start, &prev);
if (!vma)
goto out_unlock;
ret = -EINVAL;
if (vma->vm_start >= end)
goto out_unlock;
if (is_vm_hugetlb_page(vma)) {
unsigned long vma_hpagesize = vma_kernel_pagesize(vma);
if (start & (vma_hpagesize - 1))
goto out_unlock;
}
found = false;
basic_ioctls = false;
for (cur = vma; cur && cur->vm_start < end; cur = cur->vm_next) {
cond_resched();
BUG_ON(!!cur->vm_userfaultfd_ctx.ctx ^
!!(cur->vm_flags & (VM_UFFD_MISSING | VM_UFFD_WP)));
ret = -EINVAL;
if (!vma_can_userfault(cur))
goto out_unlock;
if (is_vm_hugetlb_page(cur) && end <= cur->vm_end &&
end > cur->vm_start) {
unsigned long vma_hpagesize = vma_kernel_pagesize(cur);
ret = -EINVAL;
if (end & (vma_hpagesize - 1))
goto out_unlock;
}
ret = -EBUSY;
if (cur->vm_userfaultfd_ctx.ctx &&
cur->vm_userfaultfd_ctx.ctx != ctx)
goto out_unlock;
if (is_vm_hugetlb_page(cur))
basic_ioctls = true;
found = true;
}
BUG_ON(!found);
if (vma->vm_start < start)
prev = vma;
ret = 0;
do {
cond_resched();
BUG_ON(!vma_can_userfault(vma));
BUG_ON(vma->vm_userfaultfd_ctx.ctx &&
vma->vm_userfaultfd_ctx.ctx != ctx);
if (vma->vm_userfaultfd_ctx.ctx == ctx &&
(vma->vm_flags & vm_flags) == vm_flags)
goto skip;
if (vma->vm_start > start)
start = vma->vm_start;
vma_end = min(end, vma->vm_end);
new_flags = (vma->vm_flags & ~vm_flags) | vm_flags;
prev = vma_merge(mm, prev, start, vma_end, new_flags,
vma->anon_vma, vma->vm_file, vma->vm_pgoff,
vma_policy(vma),
((struct vm_userfaultfd_ctx){ ctx }));
if (prev) {
vma = prev;
goto next;
}
if (vma->vm_start < start) {
ret = split_vma(mm, vma, start, 1);
if (ret)
break;
}
if (vma->vm_end > end) {
ret = split_vma(mm, vma, end, 0);
if (ret)
break;
}
next:
vma->vm_flags = new_flags;
vma->vm_userfaultfd_ctx.ctx = ctx;
skip:
prev = vma;
start = vma->vm_end;
vma = vma->vm_next;
} while (vma && vma->vm_start < end);
out_unlock:
up_write(&mm->mmap_sem);
mmput(mm);
if (!ret) {
if (put_user(basic_ioctls ? UFFD_API_RANGE_IOCTLS_BASIC :
UFFD_API_RANGE_IOCTLS,
&user_uffdio_register->ioctls))
ret = -EFAULT;
}
out:
return ret;
}

