void StartAdvertisingSet(int reg_id, IdTxPowerStatusCallback register_cb,
AdvertiseParameters params,
std::vector<uint8_t> advertise_data,
std::vector<uint8_t> scan_response_data,
PeriodicAdvertisingParameters periodic_params,
std::vector<uint8_t> periodic_data,
uint16_t duration, uint8_t maxExtAdvEvents,
IdStatusCallback timeout_cb) {
LOG(INFO) << __func__ << " in shim layer";
bluetooth::hci::ExtendedAdvertisingConfig config{};
parse_parameter(config, params);
bluetooth::hci::PeriodicAdvertisingParameters periodic_parameters;
periodic_parameters.max_interval = periodic_params.max_interval;
periodic_parameters.min_interval = periodic_params.min_interval;
periodic_parameters.properties =
periodic_params.periodic_advertising_properties;
config.periodic_advertising_parameters = periodic_parameters;
size_t offset = 0;
while (offset < advertise_data.size()) {
GapData gap_data;
uint8_t len = advertise_data[offset];
auto begin = advertise_data.begin() + offset;
auto end = begin + len + 1;        auto data_copy = std::make_shared<std::vector<uint8_t>>(begin, end);
bluetooth::packet::PacketView<bluetooth::packet::kLittleEndian> packet(
data_copy);
GapData::Parse(&gap_data, packet.begin());
config.advertisement.push_back(gap_data);
offset += len + 1;      }
offset = 0;
while (offset < scan_response_data.size()) {
GapData gap_data;
uint8_t len = scan_response_data[offset];
auto begin = scan_response_data.begin() + offset;
auto end = begin + len + 1;        auto data_copy = std::make_shared<std::vector<uint8_t>>(begin, end);
bluetooth::packet::PacketView<bluetooth::packet::kLittleEndian> packet(
data_copy);
GapData::Parse(&gap_data, packet.begin());
config.scan_response.push_back(gap_data);
offset += len + 1;      }
offset = 0;
while (offset < periodic_data.size()) {
GapData gap_data;
uint8_t len = periodic_data[offset];
auto begin = periodic_data.begin() + offset;
auto end = begin + len + 1;        auto data_copy = std::make_shared<std::vector<uint8_t>>(begin, end);
bluetooth::packet::PacketView<bluetooth::packet::kLittleEndian> packet(
data_copy);
GapData::Parse(&gap_data, packet.begin());
config.periodic_data.push_back(gap_data);
offset += len + 1;      }
bluetooth::hci::AdvertiserId id =
bluetooth::shim::GetAdvertising()->ExtendedCreateAdvertiser(
reg_id, config, scan_callback, set_terminated_callback, duration,
maxExtAdvEvents, bluetooth::shim::GetGdShimHandler());
LOG(INFO) << "create advertising set, reg_id:" << reg_id
<< ", id:" << (uint16_t)id;
BTM_LogHistory(kBtmLogTag, RawAddress::kEmpty, "Le advert started",
base::StringPrintf("advert_id:%d", reg_id));
}

static int
server_input_global_request(int type, u_int32_t seq, void *ctxt)
{
char *rtype;
int want_reply;
int r, success = 0, allocated_listen_port = 0;
struct sshbuf *resp = NULL;
rtype = packet_get_string(NULL);
want_reply = packet_get_char();
debug("server_input_global_request: rtype %s want_reply %d", rtype, want_reply);
if (strcmp(rtype, "tcpip-forward") == 0) {
struct passwd *pw;
struct Forward fwd;
pw = the_authctxt->pw;
if (pw == NULL || !the_authctxt->valid)
fatal("server_input_global_request: no/invalid user");
memset(&fwd, 0, sizeof(fwd));
fwd.listen_host = packet_get_string(NULL);
fwd.listen_port = (u_short)packet_get_int();
debug("server_input_global_request: tcpip-forward listen %s port %d",
fwd.listen_host, fwd.listen_port);
if ((options.allow_tcp_forwarding & FORWARD_REMOTE) == 0 ||
no_port_forwarding_flag || options.disable_forwarding ||
(!want_reply && fwd.listen_port == 0) ||
(fwd.listen_port != 0 &&
!bind_permitted(fwd.listen_port, pw->pw_uid))) {
success = 0;
packet_send_debug("Server has disabled port forwarding.");
} else {
success = channel_setup_remote_fwd_listener(&fwd,
&allocated_listen_port, &options.fwd_opts);
}
free(fwd.listen_host);
if ((resp = sshbuf_new()) == NULL)
fatal("%s: sshbuf_new", __func__);
if (allocated_listen_port != 0 &&
(r = sshbuf_put_u32(resp, allocated_listen_port)) != 0)
fatal("%s: sshbuf_put_u32: %s", __func__, ssh_err(r));
} else if (strcmp(rtype, "cancel-tcpip-forward") == 0) {
struct Forward fwd;
memset(&fwd, 0, sizeof(fwd));
fwd.listen_host = packet_get_string(NULL);
fwd.listen_port = (u_short)packet_get_int();
debug("%s: cancel-tcpip-forward addr %s port %d", __func__,
fwd.listen_host, fwd.listen_port);
success = channel_cancel_rport_listener(&fwd);
free(fwd.listen_host);
} else if (strcmp(rtype, "streamlocal-forward@openssh.com") == 0) {
struct Forward fwd;
memset(&fwd, 0, sizeof(fwd));
fwd.listen_path = packet_get_string(NULL);
debug("server_input_global_request: streamlocal-forward listen path %s",
fwd.listen_path);
if ((options.allow_streamlocal_forwarding & FORWARD_REMOTE) == 0
|| no_port_forwarding_flag || options.disable_forwarding) {
success = 0;
packet_send_debug("Server has disabled port forwarding.");
} else {
success = channel_setup_remote_fwd_listener(
&fwd, NULL, &options.fwd_opts);
}
free(fwd.listen_path);
} else if (strcmp(rtype, "cancel-streamlocal-forward@openssh.com") == 0) {
struct Forward fwd;
memset(&fwd, 0, sizeof(fwd));
fwd.listen_path = packet_get_string(NULL);
debug("%s: cancel-streamlocal-forward path %s", __func__,
fwd.listen_path);
success = channel_cancel_rport_listener(&fwd);
free(fwd.listen_path);
} else if (strcmp(rtype, "no-more-sessions@openssh.com") == 0) {
no_more_sessions = 1;
success = 1;
} else if (strcmp(rtype, "hostkeys-prove-00@openssh.com") == 0) {
success = server_input_hostkeys_prove(&resp);
}
if (want_reply) {
packet_start(success ?
SSH2_MSG_REQUEST_SUCCESS : SSH2_MSG_REQUEST_FAILURE);
if (success && resp != NULL)
ssh_packet_put_raw(active_state, sshbuf_ptr(resp),
sshbuf_len(resp));
packet_send();
packet_write_wait();
}
free(rtype);
sshbuf_free(resp);
return 0;
}

void CalculateOutputIndexValueRowID(
const RowPartitionTensor& value_rowids,
const vector<INDEX_TYPE>& parent_output_index,
INDEX_TYPE output_index_multiplier, INDEX_TYPE output_size,
vector<INDEX_TYPE>* result) {
const INDEX_TYPE index_size = value_rowids.size();
result->reserve(index_size);
if (index_size == 0) {
return;
}
INDEX_TYPE current_output_column = 0;
INDEX_TYPE current_value_rowid = value_rowids(0);
DCHECK_LT(current_value_rowid, parent_output_index.size());
INDEX_TYPE current_output_index = parent_output_index[current_value_rowid];
result->push_back(current_output_index);
for (INDEX_TYPE i = 1; i < index_size; ++i) {
INDEX_TYPE next_value_rowid = value_rowids(i);
if (next_value_rowid == current_value_rowid) {
if (current_output_index >= 0) {
++current_output_column;
if (current_output_column < output_size) {
current_output_index += output_index_multiplier;
} else {
current_output_index = -1;
}
}
} else {
current_output_column = 0;
current_value_rowid = next_value_rowid;
DCHECK_LT(next_value_rowid, parent_output_index.size());
current_output_index = parent_output_index[next_value_rowid];
}
result->push_back(current_output_index);
}
DCHECK_EQ(result->size(), value_rowids.size());
}

