static char *
_XcursorThemeInherits (const char *full)
{
char    line[8192];
char    *result = NULL;
FILE    *f;
if (!full)
return NULL;
f = fopen (full, "r");
if (f)
{
while (fgets (line, sizeof (line), f))
{
if (!strncmp (line, "Inherits", 8))
{
char    *l = line + 8;
char    *r;
while (*l == ' ') l++;
if (*l != '=') continue;
l++;
while (*l == ' ') l++;
result = malloc (strlen (l));
if (result)
{
r = result;
while (*l)
{
while (XcursorSep(*l) || XcursorWhite (*l)) l++;
if (!*l)
break;
if (r != result)
*r++ = ':';
while (*l && !XcursorWhite(*l) &&
!XcursorSep(*l))
*r++ = *l++;
}
*r++ = '\0';
}
break;
}
}
fclose (f);
}
return result;
}

int ds_is_in_list(struct sip_msg *_m, str *_ip, int port, int set,
ds_partition_t *partition, int active_only, str *pattern_s)
{
pv_value_t val;
ds_set_p list;
struct ip_addr *ip;
int_str avp_val;
int j,k;
char *pattern = NULL;
if (!(ip = str2ip(_ip)) && !(ip = str2ip6(_ip))) {
LM_ERR("IP val is not IP <%.*s>\n",val.rs.len,val.rs.s);
return -1;
}
if (pattern_s) {
pattern = pkg_malloc(pattern_s->len + 1);
if (!pattern) {
LM_ERR("oom for pattern!\n");
return -1;
}
memcpy(pattern, pattern_s->s, pattern_s->len);
pattern[pattern_s->len] = '\0';
}
memset(&val, 0, sizeof(pv_value_t));
val.flags = PV_VAL_INT|PV_TYPE_INT;
lock_start_read( partition->lock );
for(list = (*partition->data)->sets ; list!= NULL; list= list->next) {
if ((set == -1) || (set == list->id)) {
for(j=0; j<list->nr; j++) {
for(k=0 ; k<list->dlist[j].ips_cnt ; k++ ) {
if ( (list->dlist[j].ports[k]==0 || port==0
|| port==list->dlist[j].ports[k]) &&
ip_addr_cmp( ip, &list->dlist[j].ips[k]) ) {
if (active_only && !dst_is_active(list->dlist[j]) )
continue;
if (pattern) {
if (!list->dlist[j].attrs.s)
continue;
if (fnmatch(pattern, list->dlist[j].attrs.s, FNM_PERIOD) != 0)
continue;
}
if(set==-1 && ds_setid_pvname.s!=0) {
val.ri = list->id;
if(pv_set_value(_m, &ds_setid_pv,
(int)EQ_T, &val)<0)
{
LM_ERR("setting PV failed\n");
goto error;
}
}
if (partition->attrs_avp_name>= 0) {
avp_val.s = list->dlist[j].attrs;
if(add_avp(AVP_VAL_STR|partition->attrs_avp_type,
partition->attrs_avp_name,avp_val)!=0)
goto error;
}
if (partition->script_attrs_avp_name>= 0) {
avp_val.s = list->dlist[j].script_attrs;
if(add_avp(AVP_VAL_STR|partition->script_attrs_avp_type,
partition->script_attrs_avp_name,avp_val)!=0)
goto error;
}
lock_stop_read( partition->lock );
if (pattern)
pkg_free(pattern);
return 1;
}
}
}
}
}
error:
lock_stop_read( partition->lock );
if (pattern)
pkg_free(pattern);
return -1;
}

EbmlElement * EbmlElement::FindNextElement(IOCallback & DataStream, const EbmlSemanticContext & Context, int & UpperLevel,
uint64 MaxDataSize, bool AllowDummyElt, unsigned int MaxLowerLevel)
{
int PossibleID_Length = 0;
binary PossibleIdNSize[16];
int PossibleSizeLength;
uint64 SizeUnknown;
int ReadIndex = 0;   uint32 ReadSize = 0;
uint64 SizeFound;
int SizeIdx;
bool bFound;
int UpperLevel_original = UpperLevel;
do {
do {
assert(ReadIndex < 16);
bFound = false;
binary IdBitMask = 1 << 7;
for (SizeIdx = 0; SizeIdx < ReadIndex && SizeIdx < 4; SizeIdx++) {
if (PossibleIdNSize[0] & (IdBitMask >> SizeIdx)) {
PossibleID_Length = SizeIdx + 1;
IdBitMask >>= SizeIdx;
bFound = true;
break;
}
}
if (bFound) {
break;
}
if (ReadIndex >= 4) {
memmove(&PossibleIdNSize[0],&PossibleIdNSize[1], --ReadIndex);
}
if (MaxDataSize <= ReadSize)
break;
if (DataStream.read(&PossibleIdNSize[ReadIndex++], 1) == 0) {
return NULL;       }
ReadSize++;
} while (!bFound);
if (!bFound)
return NULL;
SizeIdx = ReadIndex;
ReadIndex -= PossibleID_Length;
uint32 _SizeLength;
PossibleSizeLength = ReadIndex;
while (1) {
_SizeLength = PossibleSizeLength;
SizeFound = ReadCodedSizeValue(&PossibleIdNSize[PossibleID_Length], _SizeLength, SizeUnknown);
if (_SizeLength != 0) {
bFound = true;
break;
}
if (PossibleSizeLength >= 8) {
bFound = false;
break;
}
if (MaxDataSize <= ReadSize) {
bFound = false;
break;
}
if( DataStream.read( &PossibleIdNSize[SizeIdx++], 1 ) == 0 ) {
return NULL;       }
ReadSize++;
PossibleSizeLength++;
}
if (bFound) {
EbmlId PossibleID(PossibleIdNSize, PossibleID_Length);
EbmlElement * Result = CreateElementUsingContext(PossibleID, Context, UpperLevel, false, AllowDummyElt, MaxLowerLevel);
if (Result != NULL) {
if (AllowDummyElt || !Result->IsDummy()) {
Result->SetSizeLength(_SizeLength);
Result->Size = SizeFound;
if (Result->ValidateSize() && (SizeFound == SizeUnknown || UpperLevel > 0 || MaxDataSize == 0 || MaxDataSize >= (PossibleID_Length + PossibleSizeLength + SizeFound))) {
if (SizeFound != SizeUnknown || Result->SetSizeInfinite()) {
Result->SizePosition = DataStream.getFilePointer() - SizeIdx + EBML_ID_LENGTH(PossibleID);
Result->ElementPosition = Result->SizePosition - EBML_ID_LENGTH(PossibleID);
DataStream.setFilePointer(Result->SizePosition + _SizeLength);
return Result;
}
}
}
delete Result;
}
}
ReadIndex = SizeIdx - 1;
memmove(&PossibleIdNSize[0], &PossibleIdNSize[1], ReadIndex);
UpperLevel = UpperLevel_original;
} while ( MaxDataSize > DataStream.getFilePointer() - SizeIdx + PossibleID_Length );
return NULL;
}

static const char *
vips_utf8_strcasestr( const char *haystack_start, const char *needle_start, 
int len_bytes )
{
int needle_len = g_utf8_strlen( needle_start, -1 );
int needle_len_bytes = strlen( needle_start );
const char *haystack;
for( haystack = haystack_start; 
haystack - haystack_start <= len_bytes - needle_len_bytes; 
haystack = g_utf8_find_next_char( haystack, NULL ) ) {
const char *needle_char;
const char *haystack_char;
int i;
haystack_char = haystack;
needle_char = needle_start;
for( i = 0; i < needle_len; i++ ) {
gunichar a = 
g_utf8_get_char_validated( haystack_char, 
haystack_start + len_bytes - haystack );
gunichar b = 
g_utf8_get_char_validated( needle_char, -1 );
if( a == (gunichar) -1 ||
a == (gunichar) -2 ||
b == (gunichar) -1 ||
b == (gunichar) -2 )
return( NULL );
if( a == (gunichar) 0 )
return( NULL );
if( g_unichar_tolower( a ) != g_unichar_tolower( b ) )
break;
haystack_char = 
g_utf8_find_next_char( haystack_char, 
haystack_start + len_bytes );
needle_char = 
g_utf8_find_next_char( needle_char, NULL );
}
if( i == needle_len )
return( haystack );
}
return( NULL );
}

static void dump_od_to_saf(GF_SceneDumper *dumper, GF_AUContext *au, u32 indent)
{
u32 i, count;
count = gf_list_count(au->commands);
for (i=0; i<count; i++) {
u32 j, c2;
GF_ODUpdate *com = (GF_ODUpdate *)gf_list_get(au->commands, i);
if (com->tag != GF_ODF_OD_UPDATE_TAG) continue;
c2 = gf_list_count(com->objectDescriptors);
for (j=0; j<c2; j++) {
GF_ObjectDescriptor *od = (GF_ObjectDescriptor *)gf_list_get(com->objectDescriptors, j);
GF_ESD *esd = (GF_ESD *) gf_list_get(od->ESDescriptors, 0);
GF_MuxInfo *mux;
if (!esd || (esd->tag != GF_ODF_ESD_TAG)) {
if (od->URLString) {
gf_fprintf(dumper->trace, "<saf:RemoteStreamHeader streamID=\"stream%d\" url=\"%s\"", au->owner->ESID, od->URLString);
if (au->timing) gf_fprintf(dumper->trace, " time=\""LLD"\"", au->timing);
gf_fprintf(dumper->trace, "/>\n");
}
continue;
}
mux = (GF_MuxInfo *)gf_list_get(esd->extensionDescriptors, 0);
if (!mux || (mux->tag!=GF_ODF_MUXINFO_TAG)) mux = NULL;
gf_fprintf(dumper->trace, "<saf:mediaHeader streamID=\"stream%d\"", esd->ESID);
gf_fprintf(dumper->trace, " streamType=\"%d\" objectTypeIndication=\"%d\" timeStampResolution=\"%d\"", esd->decoderConfig->streamType, esd->decoderConfig->objectTypeIndication, au->owner->timeScale);
if (au->timing) gf_fprintf(dumper->trace, " time=\""LLD"\"", au->timing);
if (mux && mux->file_name) gf_fprintf(dumper->trace, " source=\"%s\"", mux->file_name);
gf_fprintf(dumper->trace, "/>\n");
}
}
gf_fprintf(dumper->trace, "</saf:mediaUnit>\n");
}

int __ext4_journal_stop(const char *where, unsigned int line, handle_t *handle)
{
struct super_block *sb;
int err;
int rc;
if (!ext4_handle_valid(handle)) {
ext4_put_nojournal(handle);
return 0;
}
if (!handle->h_transaction) {
err = jbd2_journal_stop(handle);
return handle->h_err ? handle->h_err : err;
}
sb = handle->h_transaction->t_journal->j_private;
err = handle->h_err;
rc = jbd2_journal_stop(handle);
if (!err)
err = rc;
if (err)
__ext4_std_error(sb, where, line, err);
return err;
}

static int tree_link_matching_nodes(X509_POLICY_LEVEL *curr,
X509_POLICY_DATA *data)
{
X509_POLICY_LEVEL *last = curr - 1;
int i, matched = 0;
for (i = 0; i < sk_X509_POLICY_NODE_num(last->nodes); i++) {
X509_POLICY_NODE *node = sk_X509_POLICY_NODE_value(last->nodes, i);
if (ossl_policy_node_match(last, node, data->valid_policy)) {
if (ossl_policy_level_add_node(curr, data, node, NULL) == NULL)
return 0;
matched = 1;
}
}
if (!matched && last->anyPolicy) {
if (ossl_policy_level_add_node(curr, data, last->anyPolicy, NULL) == NULL)
return 0;
}
return 1;
}

int
op_yank(oparg_T *oap, int deleting, int mess)
{
longy_idx;    yankreg_T*curr;    yankreg_Tnewreg;    char_u**new_ptr;
linenr_Tlnum;    longj;
intyanktype = oap->motion_type;
longyanklines = oap->line_count;
linenr_Tyankendlnum = oap->end.lnum;
char_u*p;
char_u*pnew;
struct block_defbd;
#if defined(FEAT_CLIPBOARD) && defined(FEAT_X11)
intdid_star = FALSE;
#endif
if (oap->regname != 0 && !valid_yank_reg(oap->regname, TRUE))
{
beep_flush();
return FAIL;
}
if (oap->regname == '_')    return OK;
#ifdef FEAT_CLIPBOARD
if (!clip_star.available && oap->regname == '*')
oap->regname = 0;
else if (!clip_plus.available && oap->regname == '+')
oap->regname = 0;
#endif
if (!deleting)    get_yank_register(oap->regname, TRUE);
curr = y_current;
if (y_append && y_current->y_array != NULL)
y_current = &newreg;
else
free_yank_all();    
if (       oap->motion_type == MCHAR
&& oap->start.col == 0
&& !oap->inclusive
&& (!oap->is_VIsual || *p_sel == 'o')
&& !oap->block_mode
&& oap->end.col == 0
&& yanklines > 1)
{
yanktype = MLINE;
--yankendlnum;
--yanklines;
}
y_current->y_size = yanklines;
y_current->y_type = yanktype;       y_current->y_width = 0;
y_current->y_array = lalloc_clear(sizeof(char_u *) * yanklines, TRUE);
if (y_current->y_array == NULL)
{
y_current = curr;
return FAIL;
}
#ifdef FEAT_VIMINFO
y_current->y_time_set = vim_time();
#endif
y_idx = 0;
lnum = oap->start.lnum;
if (oap->block_mode)
{
y_current->y_type = MBLOCK;    y_current->y_width = oap->end_vcol - oap->start_vcol;
if (curwin->w_curswant == MAXCOL && y_current->y_width > 0)
y_current->y_width--;
}
for ( ; lnum <= yankendlnum; lnum++, y_idx++)
{
switch (y_current->y_type)
{
case MBLOCK:
block_prep(oap, &bd, lnum, FALSE);
if (yank_copy_line(&bd, y_idx, oap->excl_tr_ws) == FAIL)
goto fail;
break;
case MLINE:
if ((y_current->y_array[y_idx] =
vim_strsave(ml_get(lnum))) == NULL)
goto fail;
break;
case MCHAR:
{
colnr_T startcol = 0, endcol = MAXCOL;
int    is_oneChar = FALSE;
colnr_T cs, ce;
p = ml_get(lnum);
bd.startspaces = 0;
bd.endspaces = 0;
if (lnum == oap->start.lnum)
{
startcol = oap->start.col;
if (virtual_op)
{
getvcol(curwin, &oap->start, &cs, NULL, &ce);
if (ce != cs && oap->start.coladd > 0)
{
bd.startspaces = (ce - cs + 1)
- oap->start.coladd;
startcol++;
}
}
}
if (lnum == oap->end.lnum)
{
endcol = oap->end.col;
if (virtual_op)
{
getvcol(curwin, &oap->end, &cs, NULL, &ce);
if (p[endcol] == NUL || (cs + oap->end.coladd < ce
&& (*mb_head_off)(p, p + endcol) == 0))
{
if (oap->start.lnum == oap->end.lnum
&& oap->start.col == oap->end.col)
{
is_oneChar = TRUE;
bd.startspaces = oap->end.coladd
- oap->start.coladd + oap->inclusive;
endcol = startcol;
}
else
{
bd.endspaces = oap->end.coladd
+ oap->inclusive;
endcol -= oap->inclusive;
}
}
}
}
if (endcol == MAXCOL)
endcol = (colnr_T)STRLEN(p);
if (startcol > endcol || is_oneChar)
bd.textlen = 0;
else
bd.textlen = endcol - startcol + oap->inclusive;
bd.textstart = p + startcol;
if (yank_copy_line(&bd, y_idx, FALSE) == FAIL)
goto fail;
break;
}
}
}
if (curr != y_current)    {
new_ptr = ALLOC_MULT(char_u *, curr->y_size + y_current->y_size);
if (new_ptr == NULL)
goto fail;
for (j = 0; j < curr->y_size; ++j)
new_ptr[j] = curr->y_array[j];
vim_free(curr->y_array);
curr->y_array = new_ptr;
#ifdef FEAT_VIMINFO
curr->y_time_set = vim_time();
#endif
if (yanktype == MLINE)    curr->y_type = MLINE;
if (curr->y_type == MCHAR && vim_strchr(p_cpo, CPO_REGAPPEND) == NULL)
{
pnew = alloc(STRLEN(curr->y_array[curr->y_size - 1])
+ STRLEN(y_current->y_array[0]) + 1);
if (pnew == NULL)
{
y_idx = y_current->y_size - 1;
goto fail;
}
STRCPY(pnew, curr->y_array[--j]);
STRCAT(pnew, y_current->y_array[0]);
vim_free(curr->y_array[j]);
vim_free(y_current->y_array[0]);
curr->y_array[j++] = pnew;
y_idx = 1;
}
else
y_idx = 0;
while (y_idx < y_current->y_size)
curr->y_array[j++] = y_current->y_array[y_idx++];
curr->y_size = j;
vim_free(y_current->y_array);
y_current = curr;
}
if (mess)    {
if (yanktype == MCHAR
&& !oap->block_mode
&& yanklines == 1)
yanklines = 0;
if (yanklines > p_report)
{
char namebuf[100];
if (oap->regname == NUL)
*namebuf = NUL;
else
vim_snprintf(namebuf, sizeof(namebuf),
_(" into \"%c"), oap->regname);
update_topline_redraw();
if (oap->block_mode)
{
smsg(NGETTEXT("block of %ld line yanked%s",
"block of %ld lines yanked%s", yanklines),
yanklines, namebuf);
}
else
{
smsg(NGETTEXT("%ld line yanked%s",
"%ld lines yanked%s", yanklines),
yanklines, namebuf);
}
}
}
if ((cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0)
{
curbuf->b_op_start = oap->start;
curbuf->b_op_end = oap->end;
if (yanktype == MLINE && !oap->block_mode)
{
curbuf->b_op_start.col = 0;
curbuf->b_op_end.col = MAXCOL;
}
}
#ifdef FEAT_CLIPBOARD
if (clip_star.available
&& (curr == &(y_regs[STAR_REGISTER])
|| (!deleting && oap->regname == 0
&& ((clip_unnamed | clip_unnamed_saved) & CLIP_UNNAMED))))
{
if (curr != &(y_regs[STAR_REGISTER]))
copy_yank_reg(&(y_regs[STAR_REGISTER]));
clip_own_selection(&clip_star);
clip_gen_set_selection(&clip_star);
# ifdef FEAT_X11
did_star = TRUE;
# endif
}
# ifdef FEAT_X11
if (clip_plus.available
&& (curr == &(y_regs[PLUS_REGISTER])
|| (!deleting && oap->regname == 0
&& ((clip_unnamed | clip_unnamed_saved) &
CLIP_UNNAMED_PLUS))))
{
if (curr != &(y_regs[PLUS_REGISTER]))
copy_yank_reg(&(y_regs[PLUS_REGISTER]));
clip_own_selection(&clip_plus);
clip_gen_set_selection(&clip_plus);
if (!clip_isautosel_star()
&& !clip_isautosel_plus()
&& !((clip_unnamed | clip_unnamed_saved) == CLIP_UNNAMED_PLUS)
&& !(deleting && (clip_unnamed | clip_unnamed_saved)
== (CLIP_UNNAMED | CLIP_UNNAMED_PLUS))
&& !did_star
&& curr == &(y_regs[PLUS_REGISTER]))
{
copy_yank_reg(&(y_regs[STAR_REGISTER]));
clip_own_selection(&clip_star);
clip_gen_set_selection(&clip_star);
}
}
# endif
#endif
#if defined(FEAT_EVAL)
if (!deleting && has_textyankpost())
yank_do_autocmd(oap, y_current);
#endif
return OK;
fail:    free_yank(y_idx + 1);
y_current = curr;
return FAIL;
}

