}
else if (dir == BACKWARD)
--lnum;
new_cursor = curwin->w_cursor;
if (y_type == MCHAR && y_size == 1)
{
linenr_Tend_lnum = 0;     linenr_Tstart_lnum = lnum;
intfirst_byte_off = 0;
if (VIsual_active)
{
