BOOL license_read_new_or_upgrade_license_packet(rdpLicense* license, wStream* s)
{
UINT32 os_major;
UINT32 os_minor;
UINT32 cbScope, cbCompanyName, cbProductId, cbLicenseInfo;
wStream* licenseStream = NULL;
BOOL ret = FALSE;
BYTE computedMac[16];
LICENSE_BLOB* calBlob;
DEBUG_LICENSE("Receiving Server New/Upgrade License Packet");
calBlob = license_new_binary_blob(BB_DATA_BLOB);
if (!calBlob)
return FALSE;
if (!license_read_encrypted_blob(license, s, calBlob))
goto out_free_blob;
if (Stream_GetRemainingLength(s) < 16)
goto out_free_blob;
if (!security_mac_data(license->MacSaltKey, calBlob->data, calBlob->length, computedMac))
goto out_free_blob;
if (memcmp(computedMac, Stream_Pointer(s), sizeof(computedMac)) != 0)
{
WLog_ERR(TAG, "new or upgrade license MAC mismatch");
goto out_free_blob;
}
if (!Stream_SafeSeek(s, 16))
goto out_free_blob;
licenseStream = Stream_New(calBlob->data, calBlob->length);
if (!licenseStream)
goto out_free_blob;
Stream_Read_UINT16(licenseStream, os_minor);
Stream_Read_UINT16(licenseStream, os_major);
Stream_Read_UINT32(licenseStream, cbScope);
if (Stream_GetRemainingLength(licenseStream) < cbScope)
goto out_free_stream;
#ifdef WITH_DEBUG_LICENSE
WLog_DBG(TAG, "Scope:");
winpr_HexDump(TAG, WLOG_DEBUG, Stream_Pointer(licenseStream), cbScope);
#endif
Stream_Seek(licenseStream, cbScope);
Stream_Read_UINT32(licenseStream, cbCompanyName);
if (Stream_GetRemainingLength(licenseStream) < cbCompanyName)
goto out_free_stream;
#ifdef WITH_DEBUG_LICENSE
WLog_DBG(TAG, "Company name:");
winpr_HexDump(TAG, WLOG_DEBUG, Stream_Pointer(licenseStream), cbCompanyName);
#endif
Stream_Seek(licenseStream, cbCompanyName);
Stream_Read_UINT32(licenseStream, cbProductId);
if (Stream_GetRemainingLength(licenseStream) < cbProductId)
goto out_free_stream;
#ifdef WITH_DEBUG_LICENSE
WLog_DBG(TAG, "Product id:");
winpr_HexDump(TAG, WLOG_DEBUG, Stream_Pointer(licenseStream), cbProductId);
#endif
Stream_Seek(licenseStream, cbProductId);
Stream_Read_UINT32(licenseStream, cbLicenseInfo);
if (Stream_GetRemainingLength(licenseStream) < cbLicenseInfo)
goto out_free_stream;
license->state = LICENSE_STATE_COMPLETED;
ret = TRUE;
if (!license->rdp->settings->OldLicenseBehaviour)
ret = saveCal(license->rdp->settings, Stream_Pointer(licenseStream), cbLicenseInfo,
license->rdp->settings->ClientHostname);
out_free_stream:
Stream_Free(licenseStream, FALSE);
out_free_blob:
license_free_binary_blob(calBlob);
return ret;
}

MYSOFA_EXPORT int mysofa_check(struct MYSOFA_HRTF *hrtf) {
if (!verifyAttribute(hrtf->attributes, "Conventions", "SOFA") ||
!verifyAttribute(hrtf->attributes, "SOFAConventions",
"SimpleFreeFieldHRIR") ||
!verifyAttribute(hrtf->attributes, "DataType", "FIR"))
return MYSOFA_INVALID_ATTRIBUTES; 
if (!verifyAttribute(hrtf->attributes, "RoomType", "free field") &&
!verifyAttribute(hrtf->attributes, "RoomType", "reverberant") &&
!verifyAttribute(hrtf->attributes, "RoomType", "shoebox"))
return MYSOFA_INVALID_ATTRIBUTES; 
if (hrtf->C != 3 || hrtf->I != 1 || hrtf->E != 1 || hrtf->R != 2)
return MYSOFA_INVALID_DIMENSIONS; 
if (hrtf->ListenerView.values) {
int m = 1;
if (!verifyAttribute(hrtf->ListenerView.attributes, "DIMENSION_LIST",
"I,C")) {
if (!verifyAttribute(hrtf->ListenerView.attributes, "DIMENSION_LIST",
"M,C")) {
return MYSOFA_INVALID_DIMENSION_LIST;       }
m = hrtf->M;
}
if (verifyAttribute(hrtf->ListenerView.attributes, "Type", "cartesian")) {
if (!compareValues(&hrtf->ListenerView, array100, 3, m))
return MYSOFA_INVALID_FORMAT;     } else if (verifyAttribute(hrtf->ListenerView.attributes, "Type",
"spherical")) {
if (!compareValues(&hrtf->ListenerView, array001, 3, m))
return MYSOFA_INVALID_FORMAT;     } else
return MYSOFA_INVALID_COORDINATE_TYPE;   }
#if 0
if(hrtf->ListenerUp.values) {
if(!verifyAttribute(hrtf->ListenerUp.attributes,"DIMENSION_LIST","I,C"))
return MYSOFA_INVALID_FORMAT;
if(verifyAttribute(hrtf->ListenerUp.attributes,"Type","cartesian")) {
if(!compareValues(&hrtf->ListenerUp,array001,3))
return MYSOFA_INVALID_FORMAT;
}
else if(verifyAttribute(hrtf->ListenerUp.attributes,"Type","spherical")) {
if(!compareValues(&hrtf->ListenerUp,array0901,3))
return MYSOFA_INVALID_FORMAT;
}
}
if(!verifyAttribute(hrtf->ListenerPosition.attributes,"DIMENSION_LIST","I,C"))
return MYSOFA_INVALID_FORMAT;
if(!compareValues(&hrtf->ListenerPosition,array000,3))
return MYSOFA_INVALID_FORMAT;
#endif
int m = 1;
if (!verifyAttribute(hrtf->EmitterPosition.attributes, "DIMENSION_LIST",
"E,C,I")) {
if (!verifyAttribute(hrtf->EmitterPosition.attributes, "DIMENSION_LIST",
"E,C,M")) {
return MYSOFA_ONLY_EMITTER_WITH_ECI_SUPPORTED;     }
m = hrtf->M;
}
if (!compareValues(&hrtf->EmitterPosition, array000, 3, m))
return MYSOFA_ONLY_EMITTER_WITH_ECI_SUPPORTED; 
if (hrtf->DataDelay.values) {
if (!verifyAttribute(hrtf->DataDelay.attributes, "DIMENSION_LIST", "I,R") &&
!verifyAttribute(hrtf->DataDelay.attributes, "DIMENSION_LIST", "M,R"))
return MYSOFA_ONLY_DELAYS_WITH_IR_OR_MR_SUPPORTED;   }
if (!verifyAttribute(hrtf->DataSamplingRate.attributes, "DIMENSION_LIST",
"I"))
return MYSOFA_ONLY_THE_SAME_SAMPLING_RATE_SUPPORTED; 
double receiverPositions[6];
if (verifyAttribute(hrtf->ReceiverPosition.attributes, "DIMENSION_LIST",
"R,C,I")) {
memcpy(receiverPositions, hrtf->ReceiverPosition.values,
6 * sizeof(double));
} else if (verifyAttribute(hrtf->ReceiverPosition.attributes,
"DIMENSION_LIST", "R,C,M")) {
for (int i = 0; i < 6; i++) {
int offset = i * hrtf->M;
receiverPositions[i] = hrtf->ReceiverPosition.values[offset];
for (int j = 1; j < hrtf->M; j++)
if (!fequals(receiverPositions[i],
hrtf->ReceiverPosition.values[offset + j]))
return MYSOFA_RECEIVERS_WITH_RCI_SUPPORTED;     }
} else {
return MYSOFA_RECEIVERS_WITH_RCI_SUPPORTED;   }
if (!verifyAttribute(hrtf->ReceiverPosition.attributes, "Type", "cartesian"))
return MYSOFA_RECEIVERS_WITH_CARTESIAN_SUPPORTED; 
if (!fequals(hrtf->ReceiverPosition.values[0], 0.) ||
!fequals(hrtf->ReceiverPosition.values[2], 0.) ||
!fequals(hrtf->ReceiverPosition.values[3], 0.) ||
!fequals(hrtf->ReceiverPosition.values[5], 0.)) {
return MYSOFA_INVALID_RECEIVER_POSITIONS;   }
if (!fequals(hrtf->ReceiverPosition.values[4],
-hrtf->ReceiverPosition.values[1]))
return MYSOFA_INVALID_RECEIVER_POSITIONS;   if (hrtf->ReceiverPosition.values[1] < 0) {
if (!verifyAttribute(hrtf->attributes, "APIName",
"ARI SOFA API for Matlab/Octave"))
return MYSOFA_INVALID_RECEIVER_POSITIONS; 
const char *version = mysofa_getAttribute(hrtf->attributes, "APIVersion");
if (version == NULL)
return MYSOFA_INVALID_RECEIVER_POSITIONS; 
int a, b, c;
int res = sscanf(version, "%d.%d.%d", &a, &b, &c);
if (res != 3)
return MYSOFA_INVALID_RECEIVER_POSITIONS;     if (a > 1)
return MYSOFA_INVALID_RECEIVER_POSITIONS;     if (a == 1 && b > 1)
return MYSOFA_INVALID_RECEIVER_POSITIONS;     if (a == 1 && b == 1 && c > 0)
return MYSOFA_INVALID_RECEIVER_POSITIONS; 
if (hrtf->ReceiverPosition.values[1] >= 0)
return MYSOFA_INVALID_RECEIVER_POSITIONS; 
mylog("WARNING: SOFA file is written with wrong receiver positions. %d "
"%d.%d.%d %f<>%f\n",
res, a, b, c, hrtf->ReceiverPosition.values[1],
hrtf->ReceiverPosition.values[4]);
}
if (!verifyAttribute(hrtf->SourcePosition.attributes, "DIMENSION_LIST",
"M,C"))
return MYSOFA_ONLY_SOURCES_WITH_MC_SUPPORTED; 
return MYSOFA_OK;
}

int
gerbv_open_image(gerbv_project_t *gerbvProject, gchar const* filename, int idx, int reload,
gerbv_HID_Attribute *fattr, int n_fattr, gboolean forceLoadFile)
{
gerb_file_t *fd;
gerbv_image_t *parsed_image = NULL, *parsed_image2 = NULL;
gint retv = -1;
gboolean isPnpFile = FALSE, foundBinary;
gerbv_HID_Attribute *attr_list = NULL;
int n_attr = 0;
if (reload)
{
attr_list =  gerbvProject->file[idx]->image->info->attr_list;
n_attr =  gerbvProject->file[idx]->image->info->n_attr;
}
else
{
attr_list = fattr;
n_attr = n_fattr;
}
if ((idx+1) >= gerbvProject->max_files) {
gerbvProject->file = g_renew (gerbv_fileinfo_t *,
gerbvProject->file, gerbvProject->max_files + 2);
gerbvProject->file[gerbvProject->max_files] = NULL;
gerbvProject->file[gerbvProject->max_files+1] = NULL;
gerbvProject->max_files += 2;
}
dprintf("In open_image, about to try opening filename = %s\n", filename);
fd = gerb_fopen(filename);
if (fd == NULL) {
GERB_COMPILE_ERROR(_("Trying to open \"%s\": %s"),
filename, strerror(errno));
return -1;
}
fd->filename = g_strdup(filename);
dprintf("In open_image, successfully opened file.  Now check its type....\n");
if (gerber_is_rs274x_p(fd, &foundBinary)) {
dprintf("Found RS-274X file\n");
if (!foundBinary || forceLoadFile) {
gchar *currentLoadDirectory = g_path_get_dirname (filename);
parsed_image = parse_gerb(fd, currentLoadDirectory);
g_free (currentLoadDirectory);
}
} else if(drill_file_p(fd, &foundBinary)) {
dprintf("Found drill file\n");
if (!foundBinary || forceLoadFile)
parsed_image = parse_drillfile(fd, attr_list, n_attr, reload);
} else if (pick_and_place_check_file_type(fd, &foundBinary)) {
dprintf("Found pick-n-place file\n");
if (!foundBinary || forceLoadFile) {
if (!reload) {
pick_and_place_parse_file_to_images(fd, &parsed_image, &parsed_image2);
} else {
switch (gerbvProject->file[idx]->image->layertype) {
case GERBV_LAYERTYPE_PICKANDPLACE_TOP:
parsed_image2 = (void *)!NULL;
pick_and_place_parse_file_to_images(fd, &parsed_image, &parsed_image2);
parsed_image2 = NULL;
break;
case GERBV_LAYERTYPE_PICKANDPLACE_BOT:
parsed_image2 = (void *)!NULL;
pick_and_place_parse_file_to_images(fd, &parsed_image2, &parsed_image);
parsed_image2 = NULL;
break;
default:
GERB_COMPILE_ERROR(_("%s: unknown pick-and-place board side to reload"), filename);
}
}
isPnpFile = TRUE;
}
} else if (gerber_is_rs274d_p(fd)) {
gchar *str = g_strdup_printf(_("Most likely found a RS-274D file "
"\"%s\" ... trying to open anyways\n"), filename);
dprintf("%s", str);
g_warning("%s", str);
g_free (str);
if (!foundBinary || forceLoadFile) {
gchar *currentLoadDirectory = g_path_get_dirname (filename);
parsed_image = parse_gerb(fd, currentLoadDirectory);
g_free (currentLoadDirectory);
}
} else {
dprintf("Unknown filetype");
GERB_COMPILE_ERROR(_("%s: Unknown file type."), filename);
parsed_image = NULL;
}
g_free(fd->filename);
gerb_fclose(fd);
if (parsed_image == NULL) {
return -1;
}
if (parsed_image) {
gchar *baseName = g_path_get_basename (filename);
gchar *displayedName;
if (isPnpFile)
displayedName = g_strconcat (baseName, _(" (top)"), NULL);
else
displayedName = g_strdup (baseName);
retv = gerbv_add_parsed_image_to_project (gerbvProject, parsed_image, filename, displayedName, idx, reload);
g_free (baseName);
g_free (displayedName);
}
gerbvProject->file[idx]->layer_dirty = FALSE;
if (parsed_image2) {
gchar *baseName = g_path_get_basename (filename);
gchar *displayedName;
displayedName = g_strconcat (baseName, _(" (bottom)"), NULL);
retv = gerbv_add_parsed_image_to_project (gerbvProject, parsed_image2, filename, displayedName, idx + 1, reload);
g_free (baseName);
g_free (displayedName);
}
return retv;
}

