void TiffDecoder::decodeCanonAFInfo(const TiffEntryBase* object) {
TiffDecoder::decodeStdTiffEntry(object);
if ( object->pValue()->count() < 3 || object->pValue()->typeId() != unsignedShort ) return; 
std::vector<int16_t>  ints;
std::vector<uint16_t> uint;
for (int i = 0; i < object->pValue()->count(); i++) {
ints.push_back((int16_t) object->pValue()->toLong(i));
uint.push_back((uint16_t) object->pValue()->toLong(i));
}
if ( ints[0] != object->pValue()->count()*2 ) return ;
std::string familyGroup(std::string("Exif.") + groupName(object->group()) + ".");
const uint16_t nPoints = uint.at(2);
const uint16_t nMasks  = (nPoints+15)/(sizeof(uint16_t) * 8);
int            nStart  = 0;
struct {
uint16_t tag    ;
uint16_t size   ;
bool     bSigned;
} records[] = {
{ 0x2600 , 1       , true  },             { 0x2601 , 1       , true  },             { 0x2602 , 1       , true  },             { 0x2603 , 1       , true  },             { 0x2604 , 1       , true  },             { 0x2605 , 1       , true  },             { 0x2606 , 1       , true  },             { 0x2607 , 1       , true  },             { 0x2608 , nPoints , true  },             { 0x2609 , nPoints , true  },             { 0x260a , nPoints , true  },             { 0x260b , nPoints , true  },             { 0x260c , nMasks  , false },             { 0x260d , nMasks  , false },             { 0x260e , nMasks  , false },             { 0xffff , 0       , true  }          };
uint16_t count = 0;
for ( uint16_t i = 0; records[i].tag != 0xffff ; i++) count += records[i].size ;
if  ( count > ints.size() ) return ;
for ( uint16_t i = 0; records[i].tag != 0xffff ; i++) {
const TagInfo* pTags = ExifTags::tagList("Canon") ;
const TagInfo* pTag  = findTag(pTags,records[i].tag);
if ( pTag ) {
Exiv2::Value::AutoPtr v = Exiv2::Value::create(records[i].bSigned?Exiv2::signedShort:Exiv2::unsignedShort);
std::ostringstream    s;
if ( records[i].bSigned ) {
for ( int16_t k = 0 ; k < records[i].size ; k++ ) s << " " << ints.at(nStart++);
} else {
for ( int16_t k = 0 ; k < records[i].size ; k++ ) s << " " << uint.at(nStart++);
}
v->read(s.str());
exifData_[familyGroup + pTag->name_] = *v;
}
}
}

int
main(int argc, char* argv[])
{
uint16_t defconfig = (uint16_t) -1;
uint16_t deffillorder = 0;
uint32_t deftilewidth = (uint32_t) -1;
uint32_t deftilelength = (uint32_t) -1;
uint32_t defrowsperstrip = (uint32_t) 0;
uint64_t diroff = 0;
TIFF* in;
TIFF* out;
char mode[10];
char* mp = mode;
int c;
#if !HAVE_DECL_OPTARG
extern int optind;
extern char* optarg;
#endif
*mp++ = 'w';
*mp = '\0';
while ((c = getopt(argc, argv, "m:,:b:c:f:l:o:p:r:w:aistBLMC8xh")) != -1)
switch (c) {
case 'm':
maxMalloc = (tmsize_t)strtoul(optarg, NULL, 0) << 20;
break;
case ',':
if (optarg[0] != '=') usage(EXIT_FAILURE);
comma = optarg[1];
break;
case 'b':   
if (bias) {
fputs ("Only 1 bias image may be specified\n", stderr);
exit (EXIT_FAILURE);
}
{
uint16_t samples = (uint16_t) -1;
char **biasFn = &optarg;
bias = openSrcImage (biasFn);
if (!bias) exit (EXIT_FAILURE);
if (TIFFIsTiled (bias)) {
fputs ("Bias image must be organized in strips\n", stderr);
exit (EXIT_FAILURE);
}
TIFFGetField(bias, TIFFTAG_SAMPLESPERPIXEL, &samples);
if (samples != 1) {
fputs ("Bias image must be monochrome\n", stderr);
exit (EXIT_FAILURE);
}
}
break;
case 'a':   
mode[0] = 'a';
break;
case 'c':   
if (!processCompressOptions(optarg))
usage(EXIT_FAILURE);
break;
case 'f':   
if (streq(optarg, "lsb2msb"))
deffillorder = FILLORDER_LSB2MSB;
else if (streq(optarg, "msb2lsb"))
deffillorder = FILLORDER_MSB2LSB;
else
usage(EXIT_FAILURE);
break;
case 'i':   
ignore = TRUE;
break;
case 'l':   
outtiled = TRUE;
deftilelength = atoi(optarg);
break;
case 'o':   
diroff = strtoul(optarg, NULL, 0);
break;
case 'p':   
if (streq(optarg, "separate"))
defconfig = PLANARCONFIG_SEPARATE;
else if (streq(optarg, "contig"))
defconfig = PLANARCONFIG_CONTIG;
else
usage(EXIT_FAILURE);
break;
case 'r':   
defrowsperstrip = atol(optarg);
break;
case 's':   
outtiled = FALSE;
break;
case 't':   
outtiled = TRUE;
break;
case 'w':   
outtiled = TRUE;
deftilewidth = atoi(optarg);
break;
case 'B':
*mp++ = 'b'; *mp = '\0';
break;
case 'L':
*mp++ = 'l'; *mp = '\0';
break;
case 'M':
*mp++ = 'm'; *mp = '\0';
break;
case 'C':
*mp++ = 'c'; *mp = '\0';
break;
case '8':
*mp++ = '8'; *mp = '\0';
break;
case 'x':
pageInSeq = 1;
break;
case 'h':
usage(EXIT_SUCCESS);
break;
case '?':
usage(EXIT_FAILURE);
break;
}
if (argc - optind < 2)
usage(EXIT_FAILURE);
out = TIFFOpen(argv[argc-1], mode);
if (out == NULL)
return (EXIT_FAILURE);
if ((argc - optind) == 2)
pageNum = -1;
for (; optind < argc-1 ; optind++) {
char *imageCursor = argv[optind];
in = openSrcImage (&imageCursor);
if (in == NULL) {
(void) TIFFClose(out);
return (EXIT_FAILURE);
}
if (diroff != 0 && !TIFFSetSubDirectory(in, diroff)) {
TIFFError(TIFFFileName(in),
"Error, setting subdirectory at %" PRIu64, diroff);
(void) TIFFClose(in);
(void) TIFFClose(out);
return (EXIT_FAILURE);
}
for (;;) {
config = defconfig;
compression = defcompression;
predictor = defpredictor;
preset = defpreset;
fillorder = deffillorder;
rowsperstrip = defrowsperstrip;
tilewidth = deftilewidth;
tilelength = deftilelength;
g3opts = defg3opts;
if (!tiffcp(in, out) || !TIFFWriteDirectory(out)) {
(void) TIFFClose(in);
(void) TIFFClose(out);
return (EXIT_FAILURE);
}
if (imageCursor) { 
if (!nextSrcImage(in, &imageCursor)) break;
}else
if (!TIFFReadDirectory(in)) break;
}
(void) TIFFClose(in);
}
(void) TIFFClose(out);
return (EXIT_SUCCESS);
}

