int
eval_string(char_u **arg, typval_T *rettv, int evaluate, int interpolate)
{
char_u*p;
char_u*end;
intextra = interpolate ? 1 : 0;
intoff = interpolate ? 0 : 1;
intlen;
for (p = *arg + off; *p != NUL && *p != '"'; MB_PTR_ADV(p))
{
if (*p == '\\' && p[1] != NUL)
{
++p;
if (*p == '<')
extra += 5;
}
else if (interpolate && (*p == '{' || *p == '}'))
{
if (*p == '{' && p[1] != '{') break;
++p;
if (p[-1] == '}' && *p != '}')     {
semsg(_(e_stray_closing_curly_str), *arg);
return FAIL;
}
--extra;  }
}
if (*p != '"' && !(interpolate && *p == '{'))
{
semsg(_(e_missing_double_quote_str), *arg);
return FAIL;
}
if (!evaluate)
{
*arg = p + off;
return OK;
}
rettv->v_type = VAR_STRING;
len = (int)(p - *arg + extra);
rettv->vval.v_string = alloc(len);
if (rettv->vval.v_string == NULL)
return FAIL;
end = rettv->vval.v_string;
for (p = *arg + off; *p != NUL && *p != '"'; )
{
if (*p == '\\')
{
switch (*++p)
{
case 'b': *end++ = BS; ++p; break;
case 'e': *end++ = ESC; ++p; break;
case 'f': *end++ = FF; ++p; break;
case 'n': *end++ = NL; ++p; break;
case 'r': *end++ = CAR; ++p; break;
case 't': *end++ = TAB; ++p; break;
case 'X': case 'x':
case 'u': case 'U':
if (vim_isxdigit(p[1]))
{
intn, nr;
intc = toupper(*p);
if (c == 'X')
n = 2;
else if (*p == 'u')
n = 4;
else
n = 8;
nr = 0;
while (--n >= 0 && vim_isxdigit(p[1]))
{
++p;
nr = (nr << 4) + hex2nr(*p);
}
++p;
if (c != 'X')
end += (*mb_char2bytes)(nr, end);
else
*end++ = nr;
}
break;
case '0':
case '1':
case '2':
case '3':
case '4':
case '5':
case '6':
case '7': *end = *p++ - '0';
if (*p >= '0' && *p <= '7')
{
*end = (*end << 3) + *p++ - '0';
if (*p >= '0' && *p <= '7')
*end = (*end << 3) + *p++ - '0';
}
++end;
break;
case '<':
{
int flags = FSK_KEYCODE | FSK_IN_STRING;
if (p[1] != '*')
flags |= FSK_SIMPLIFY;
extra = trans_special(&p, end, flags, FALSE, NULL);
if (extra != 0)
{
end += extra;
if (end >= rettv->vval.v_string + len)
iemsg("eval_string() used more space than allocated");
break;
}
}
default: MB_COPY_CHAR(p, end);
break;
}
}
else
{
if (interpolate && (*p == '{' || *p == '}'))
{
if (*p == '{' && p[1] != '{')     break;
++p;      }
MB_COPY_CHAR(p, end);
}
}
*end = NUL;
if (*p == '"' && !interpolate)
++p;
*arg = p;
return OK;
}

static void ppp_cp_parse_cr(struct net_device *dev, u16 pid, u8 id,
unsigned int req_len, const u8 *data)
{
static u8 const valid_accm[6] = { LCP_OPTION_ACCM, 6, 0, 0, 0, 0 };
const u8 *opt;
u8 *out;
unsigned int len = req_len, nak_len = 0, rej_len = 0;
if (!(out = kmalloc(len, GFP_ATOMIC))) {
dev->stats.rx_dropped++;
return;
}
for (opt = data; len; len -= opt[1], opt += opt[1]) {
if (len < 2 || len < opt[1]) {
dev->stats.rx_errors++;
kfree(out);
return; 
}
if (pid == PID_LCP)
switch (opt[0]) {
case LCP_OPTION_MRU:
continue; 
case LCP_OPTION_ACCM: 
if (!memcmp(opt, valid_accm,
sizeof(valid_accm)))
continue;
if (!rej_len) { 
memcpy(out + nak_len, valid_accm,
sizeof(valid_accm));
nak_len += sizeof(valid_accm);
continue;
}
break;
case LCP_OPTION_MAGIC:
if (opt[1] != 6 || (!opt[2] && !opt[3] &&
!opt[4] && !opt[5]))
break; 
continue;
}
memcpy(out + rej_len, opt, opt[1]);
rej_len += opt[1];
}
if (rej_len)
ppp_cp_event(dev, pid, RCR_BAD, CP_CONF_REJ, id, rej_len, out);
else if (nak_len)
ppp_cp_event(dev, pid, RCR_BAD, CP_CONF_NAK, id, nak_len, out);
else
ppp_cp_event(dev, pid, RCR_GOOD, CP_CONF_ACK, id, req_len, data);
kfree(out);
}

static void dissect_parametrized_serialized_data(proto_tree *tree, tvbuff_t *tvb,
gint offset_input, int size, const guint encoding)
{
guint32 member_id, member_length;
proto_item * ti;
proto_tree * data_tree, * member_tree;
gint offset = offset_input;
gint deserialized_size = 0;
data_tree = proto_tree_add_subtree_format(tree, tvb, offset, -1,
ett_rtps_serialized_data, &ti, "serializedData");
while (deserialized_size < size) {
ALIGN_ZERO(offset, 2, offset_input);
member_id = tvb_get_guint16(tvb, offset, encoding);
member_length = tvb_get_guint16(tvb, offset+2, encoding);
if ((member_id & PID_EXTENDED) == PID_EXTENDED) {
member_id = tvb_get_guint32(tvb, offset+4, encoding);
member_length = tvb_get_guint32(tvb, offset+8, encoding);
member_tree = proto_tree_add_subtree_format(data_tree, tvb, offset, member_length + 12,
ett_rtps_data_member, NULL, "Member (id = %u, len = %u)", member_id, member_length);
proto_tree_add_item(member_tree, hf_rtps_pl_cdr_member_id_ext, tvb, offset+4, 4, encoding);
proto_tree_add_item(member_tree, hf_rtps_pl_cdr_member_length_ext, tvb, offset+8, 4, encoding);
offset += 12;
deserialized_size += 12;
} else if ((member_id & PID_LIST_END) == PID_LIST_END){
deserialized_size += 4;
break;
} else {
member_tree = proto_tree_add_subtree_format(data_tree, tvb, offset, member_length + 4,
ett_rtps_data_member, NULL, "Member (id = %u, len = %u)", member_id, member_length);
proto_tree_add_item(member_tree, hf_rtps_pl_cdr_member_id, tvb, offset, 2, encoding);
proto_tree_add_item(member_tree, hf_rtps_pl_cdr_member_length, tvb, offset+2, 2, encoding);
offset += 4;
deserialized_size += 4;
}
proto_tree_add_item(member_tree, hf_rtps_pl_cdr_member, tvb, offset,
member_length, encoding);
offset += member_length;
deserialized_size += member_length;
}
proto_item_set_len(ti, deserialized_size);
}

static GstBuffer *
gst_avi_demux_invert (GstAviStream * stream, GstBuffer * buf)
{
gint y, w, h;
gint bpp, stride;
guint8 *tmp = NULL;
GstMapInfo map;
guint32 fourcc;
if (stream->strh->type != GST_RIFF_FCC_vids)
return buf;
if (stream->strf.vids == NULL) {
GST_WARNING ("Failed to retrieve vids for stream");
return buf;
}
fourcc = (stream->strf.vids->compression) ?
stream->strf.vids->compression : stream->strh->fcc_handler;
if (!gst_avi_demux_is_uncompressed (fourcc)) {
return buf;                 
}
if (((gint32) stream->strf.vids->height) < 0)
return buf;
h = stream->strf.vids->height;
w = stream->strf.vids->width;
bpp = stream->strf.vids->bit_cnt ? stream->strf.vids->bit_cnt : 8;
stride = GST_ROUND_UP_4 (w * (bpp / 8));
buf = gst_buffer_make_writable (buf);
gst_buffer_map (buf, &map, GST_MAP_READWRITE);
if (map.size < (stride * h)) {
GST_WARNING ("Buffer is smaller than reported Width x Height x Depth");
gst_buffer_unmap (buf, &map);
return buf;
}
tmp = g_malloc (stride);
for (y = 0; y < h / 2; y++) {
swap_line (map.data + stride * y, map.data + stride * (h - 1 - y), tmp,
stride);
}
g_free (tmp);
gst_buffer_unmap (buf, &map);
if (stream->rgb8_palette != NULL)
buf = gst_buffer_append (buf, gst_buffer_ref (stream->rgb8_palette));
return buf;
}

static void
dissect_cip_safety_data( proto_tree *tree, proto_item *item, tvbuff_t *tvb, int item_length, packet_info *pinfo)
{
int base_length, io_data_size;
gboolean multicast = (((pntoh32(pinfo->dst.data)) & 0xf0000000) == 0xe0000000);
gboolean server_dir = FALSE;
enum enip_connid_type conn_type = ECIDT_UNKNOWN;
enum cip_safety_format_type format = CIP_SAFETY_BASE_FORMAT;
cip_safety_info_t* safety_info = (cip_safety_info_t*)p_get_proto_data(wmem_file_scope(), pinfo, proto_cipsafety, 0 );
col_set_str(pinfo->cinfo, COL_PROTOCOL, "CIP Safety");
if (safety_info != NULL)
{
conn_type = safety_info->conn_type;
format = safety_info->format;
server_dir = safety_info->server_dir;
}
base_length = multicast ? 12 : 6;
if (((conn_type == ECIDT_O2T) && (server_dir == FALSE)) ||
((conn_type == ECIDT_T2O) && (server_dir == TRUE)))
{
dissect_ack_byte(tree, tvb, 0, pinfo);
proto_tree_add_item(tree, hf_cipsafety_consumer_time_value, tvb, 1, 2, ENC_LITTLE_ENDIAN);
switch (format)
