(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
image_info->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
image=AcquireImage(image_info);
status=OpenBlob(image_info,image,ReadBinaryBlobMode,exception);
if (status == MagickFalse)
{
image=DestroyImageList(image);
return((Image *) NULL);
}
(void) ResetMagickMemory(&rla_info,0,sizeof(rla_info));
rla_info.window.left=(short) ReadBlobMSBShort(image);
rla_info.window.right=(short) ReadBlobMSBShort(image);
rla_info.window.bottom=(short) ReadBlobMSBShort(image);
rla_info.window.top=(short) ReadBlobMSBShort(image);
rla_info.active_window.left=(short) ReadBlobMSBShort(image);
rla_info.active_window.right=(short) ReadBlobMSBShort(image);
rla_info.active_window.bottom=(short) ReadBlobMSBShort(image);
rla_info.active_window.top=(short) ReadBlobMSBShort(image);
rla_info.frame=(short) ReadBlobMSBShort(image);
rla_info.storage_type=(short) ReadBlobMSBShort(image);
rla_info.number_channels=(short) ReadBlobMSBShort(image);
rla_info.number_matte_channels=(short) ReadBlobMSBShort(image);
if (rla_info.number_channels == 0)
rla_info.number_channels=3;
rla_info.number_channels+=rla_info.number_matte_channels;
rla_info.number_auxiliary_channels=(short) ReadBlobMSBShort(image);
rla_info.revision=(short) ReadBlobMSBShort(image);
count=ReadBlob(image,16,(unsigned char *) rla_info.gamma);
count=ReadBlob(image,24,(unsigned char *) rla_info.red_primary);
count=ReadBlob(image,24,(unsigned char *) rla_info.green_primary);
count=ReadBlob(image,24,(unsigned char *) rla_info.blue_primary);
count=ReadBlob(image,24,(unsigned char *) rla_info.white_point);
rla_info.job_number=ReadBlobMSBSignedLong(image);
count=ReadBlob(image,128,(unsigned char *) rla_info.name);
count=ReadBlob(image,128,(unsigned char *) rla_info.description);
rla_info.description[127]='\0';
count=ReadBlob(image,64,(unsigned char *) rla_info.program);
count=ReadBlob(image,32,(unsigned char *) rla_info.machine);
count=ReadBlob(image,32,(unsigned char *) rla_info.user);
count=ReadBlob(image,20,(unsigned char *) rla_info.date);
count=ReadBlob(image,24,(unsigned char *) rla_info.aspect);
count=ReadBlob(image,8,(unsigned char *) rla_info.aspect_ratio);
count=ReadBlob(image,32,(unsigned char *) rla_info.chan);
rla_info.field=(short) ReadBlobMSBShort(image);
count=ReadBlob(image,12,(unsigned char *) rla_info.time);
count=ReadBlob(image,32,(unsigned char *) rla_info.filter);
rla_info.bits_per_channel=(short) ReadBlobMSBShort(image);
rla_info.matte_type=(short) ReadBlobMSBShort(image);
rla_info.matte_bits=(short) ReadBlobMSBShort(image);
rla_info.auxiliary_type=(short) ReadBlobMSBShort(image);
rla_info.auxiliary_bits=(short) ReadBlobMSBShort(image);
count=ReadBlob(image,32,(unsigned char *) rla_info.auxiliary);
count=ReadBlob(image,36,(unsigned char *) rla_info.space);
if ((size_t) count != 36)
ThrowReaderException(CorruptImageError,"UnableToReadImageData");
rla_info.next=ReadBlobMSBSignedLong(image);
image->matte=rla_info.number_matte_channels != 0 ? MagickTrue : MagickFalse;
image->columns=(size_t) (rla_info.active_window.right-
rla_info.active_window.left+1);
image->rows=(size_t) (rla_info.active_window.top-
rla_info.active_window.bottom+1);
if (image_info->ping != MagickFalse)
{
(void) CloseBlob(image);
return(GetFirstImageInList(image));
}
status=SetImageExtent(image,image->columns,image->rows);
if (status == MagickFalse)
{
InheritException(exception,&image->exception);
return(DestroyImageList(image));
}
scanlines=(MagickOffsetType *) AcquireQuantumMemory(image->rows,
sizeof(*scanlines));
if (scanlines == (MagickOffsetType *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
if (*rla_info.description != '\0')
(void) SetImageProperty(image,"comment",(char *) rla_info.description);
for (i=0; i < (ssize_t) image->rows; i++)
scanlines[i]=(MagickOffsetType) ReadBlobMSBSignedLong(image);
x=0;
for (y=0; y < (ssize_t) image->rows; y++)
{
offset=SeekBlob(image,scanlines[image->rows-y-1],SEEK_SET);
if (offset < 0)
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
for (channel=0; channel < (int) rla_info.number_channels; channel++)
{
length=ReadBlobMSBSignedShort(image);
while (length > 0)
{
byte=(unsigned char) ReadBlobByte(image);
runlength=byte;
if (byte > 127)
runlength=byte-256;
length--;
if (length == 0)
break;
if (runlength < 0)
{
while (runlength < 0)
{
q=GetAuthenticPixels(image,(ssize_t) (x % image->columns),
(ssize_t) (y % image->rows),1,1,exception);
if (q == (PixelPacket *) NULL)
break;
byte=(unsigned char) ReadBlobByte(image);
length--;
switch (channel)
{
case 0:
{
SetPixelRed(q,ScaleCharToQuantum(byte));
break;
}
case 1:
{
SetPixelGreen(q,ScaleCharToQuantum(byte));
break;
}
case 2:
{
SetPixelBlue(q,ScaleCharToQuantum(byte));
break;
}
case 3:
default:
{
SetPixelAlpha(q,ScaleCharToQuantum(byte));
break;
}
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
x++;
runlength++;
}
continue;
}
byte=(unsigned char) ReadBlobByte(image);
length--;
runlength++;
do
{
q=GetAuthenticPixels(image,(ssize_t) (x % image->columns),
(ssize_t) (y % image->rows),1,1,exception);
if (q == (PixelPacket *) NULL)
break;
switch (channel)
{
case 0:
{
SetPixelRed(q,ScaleCharToQuantum(byte));
break;
}
case 1:
{
SetPixelGreen(q,ScaleCharToQuantum(byte));
break;
}
case 2:
{
SetPixelBlue(q,ScaleCharToQuantum(byte));
break;
}
case 3:
default:
{
SetPixelAlpha(q,ScaleCharToQuantum(byte));
break;
}
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
x++;
runlength--;
}
while (runlength > 0);
}
}
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
scanlines=(MagickOffsetType *) RelinquishMagickMemory(scanlines);
if (EOFBlob(image) != MagickFalse)
ThrowFileException(exception,CorruptImageError,"UnexpectedEndOfFile",
image->filename);
(void) CloseBlob(image);
return(GetFirstImageInList(image));
}

int x509_decode_time(time64_t *_t,  size_t hdrlen,
unsigned char tag,
const unsigned char *value, size_t vlen)
{
static const unsigned char month_lengths[] = { 31, 29, 31, 30, 31, 30,
31, 31, 30, 31, 30, 31 };
const unsigned char *p = value;
unsigned year, mon, day, hour, min, sec, mon_len;
#define dec2bin(X) ({ unsigned char x = (X) - '0'; if (x > 9) goto invalid_time; x; })
#define DD2bin(P) ({ unsigned x = dec2bin(P[0]) * 10 + dec2bin(P[1]); P += 2; x; })
if (tag == ASN1_UNITIM) {
if (vlen != 13)
goto unsupported_time;
year = DD2bin(p);
if (year >= 50)
year += 1900;
else
year += 2000;
} else if (tag == ASN1_GENTIM) {
if (vlen != 15)
goto unsupported_time;
year = DD2bin(p) * 100 + DD2bin(p);
if (year >= 1950 && year <= 2049)
goto invalid_time;
} else {
goto unsupported_time;
}
mon  = DD2bin(p);
day = DD2bin(p);
hour = DD2bin(p);
min  = DD2bin(p);
sec  = DD2bin(p);
if (*p != 'Z')
goto unsupported_time;
mon_len = month_lengths[mon];
if (mon == 2) {
if (year % 4 == 0) {
mon_len = 29;
if (year % 100 == 0) {
year /= 100;
if (year % 4 != 0)
mon_len = 28;
}
}
}
if (year < 1970 ||
mon < 1 || mon > 12 ||
day < 1 || day > mon_len ||
hour > 23 ||
min > 59 ||
sec > 59)
goto invalid_time;
*_t = mktime64(year, mon, day, hour, min, sec);
return 0;
unsupported_time:
pr_debug("Got unsupported time [tag %02x]: '%*phN'\n",
tag, (int)vlen, value);
return -EBADMSG;
invalid_time:
pr_debug("Got invalid time [tag %02x]: '%*phN'\n",
tag, (int)vlen, value);
return -EBADMSG;
}

void Compute(OpKernelContext* ctx) final {
const CSRSparseMatrix* input_matrix;
OP_REQUIRES_OK(ctx, ExtractVariantFromInput(ctx, 0, &input_matrix));
const Tensor& input_permutation_indices = ctx->input(1);
int64 num_rows;
int batch_size;
ValidateInputs(ctx, *input_matrix, input_permutation_indices, &batch_size,
&num_rows);
Tensor batch_ptr(cpu_allocator(), DT_INT32, TensorShape({batch_size + 1}));
auto batch_ptr_vec = batch_ptr.vec<int32>();
batch_ptr_vec(0) = 0;
std::vector<SparseMatrix> sparse_cholesky_factors(batch_size);
const double nnz_per_row =
(input_matrix->total_nnz() / batch_size) / num_rows;
const int64 sparse_cholesky_cost_per_batch =
nnz_per_row * nnz_per_row * num_rows;
auto worker_threads = *(ctx->device()->tensorflow_cpu_worker_threads());
std::atomic<int64> invalid_input_index(-1);
Shard(worker_threads.num_threads, worker_threads.workers, batch_size,
sparse_cholesky_cost_per_batch,
[&](int64 batch_begin, int64 batch_end) {
for (int64 batch_index = batch_begin; batch_index < batch_end;
++batch_index) {
Eigen::Map<const SparseMatrix> sparse_matrix(
num_rows, num_rows, input_matrix->nnz(batch_index),
input_matrix->row_pointers_vec(batch_index).data(),
input_matrix->col_indices_vec(batch_index).data(),
input_matrix->values_vec<T>(batch_index).data());
Eigen::SimplicialLLT<SparseMatrix, Eigen::Upper,
Eigen::NaturalOrdering<int>>
solver;
auto permutation_indices_flat =
input_permutation_indices.flat<int32>().data();
Eigen::Map<
Eigen::PermutationMatrix<Eigen::Dynamic, Eigen::Dynamic, int>>
permutation(permutation_indices_flat + batch_index * num_rows,
num_rows);
auto permutation_inverse = permutation.inverse();
SparseMatrix permuted_sparse_matrix;
permuted_sparse_matrix.template selfadjointView<Eigen::Upper>() =
sparse_matrix.template selfadjointView<Eigen::Upper>()
.twistedBy(permutation_inverse);
solver.compute(permuted_sparse_matrix);
if (solver.info() != Eigen::Success) {
invalid_input_index = batch_index;
return;
}
sparse_cholesky_factors[batch_index] =
std::move(solver.matrixU());
batch_ptr_vec(batch_index + 1) =
sparse_cholesky_factors[batch_index].nonZeros();
}
});
OP_REQUIRES(
ctx, invalid_input_index == -1,
errors::InvalidArgument(
"Sparse Cholesky factorization failed for batch index ",
invalid_input_index.load(), ". The input might not be valid."));
std::partial_sum(batch_ptr_vec.data(),
batch_ptr_vec.data() + batch_size + 1,
batch_ptr_vec.data());
const int64 total_nnz = batch_ptr_vec(batch_size);
Tensor output_row_ptr(cpu_allocator(), DT_INT32,
TensorShape({(num_rows + 1) * batch_size}));
Tensor output_col_ind(cpu_allocator(), DT_INT32, TensorShape({total_nnz}));
Tensor output_values(cpu_allocator(), DataTypeToEnum<T>::value,
TensorShape({total_nnz}));
auto output_row_ptr_ptr = output_row_ptr.flat<int32>().data();
auto output_col_ind_ptr = output_col_ind.flat<int32>().data();
auto output_values_ptr = output_values.flat<T>().data();
Shard(worker_threads.num_threads, worker_threads.workers, batch_size,
(3 * total_nnz) / batch_size ,
[&](int64 batch_begin, int64 batch_end) {
for (int64 batch_index = batch_begin; batch_index < batch_end;
++batch_index) {
const SparseMatrix& cholesky_factor =
sparse_cholesky_factors[batch_index];
const int64 nnz = cholesky_factor.nonZeros();
std::copy(cholesky_factor.outerIndexPtr(),
cholesky_factor.outerIndexPtr() + num_rows + 1,
output_row_ptr_ptr + batch_index * (num_rows + 1));
std::copy(cholesky_factor.innerIndexPtr(),
cholesky_factor.innerIndexPtr() + nnz,
output_col_ind_ptr + batch_ptr_vec(batch_index));
std::copy(cholesky_factor.valuePtr(),
cholesky_factor.valuePtr() + nnz,
output_values_ptr + batch_ptr_vec(batch_index));
}
});
CSRSparseMatrix output_csr_matrix;
OP_REQUIRES_OK(
ctx,
CSRSparseMatrix::CreateCSRSparseMatrix(
DataTypeToEnum<T>::value, input_matrix->dense_shape(), batch_ptr,
output_row_ptr, output_col_ind, output_values, &output_csr_matrix));
Tensor* output_csr_matrix_tensor;
AllocatorAttributes cpu_alloc;
cpu_alloc.set_on_host(true);
OP_REQUIRES_OK(
ctx, ctx->allocate_output(0, TensorShape({}), &output_csr_matrix_tensor,
cpu_alloc));
output_csr_matrix_tensor->scalar<Variant>()() =
std::move(output_csr_matrix);
}

static void
sraSpanInsertBefore(sraSpan *newspan, sraSpan *before) {
newspan->_next = before;
newspan->_prev = before->_prev;
before->_prev->_next = newspan;
before->_prev = newspan;
}

static Image *ReadPESImage(const ImageInfo *image_info,ExceptionInfo *exception)
{
char
filename[MagickPathExtent];
FILE
*file;
Image
*image;
ImageInfo
*read_info;
int
delta_x,
delta_y,
j,
unique_file,
x,
y;
MagickBooleanType
status;
PESBlockInfo
blocks[256];
PointInfo
*stitches;
SegmentInfo
bounds;
register ssize_t
i;
size_t
number_blocks,
number_colors,
number_stitches;
ssize_t
count,
offset;
unsigned char
magick[4],
version[4];
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickCoreSignature);
if (image_info->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
image_info->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
image=AcquireImage(image_info,exception);
status=OpenBlob(image_info,image,ReadBinaryBlobMode,exception);
if (status == MagickFalse)
{
image=DestroyImageList(image);
return((Image *) NULL);
}
count=ReadBlob(image,4,magick);
if ((count != 4) || (LocaleNCompare((char *) magick,"#PES",4) != 0))
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
count=ReadBlob(image,4,version);
offset=ReadBlobLSBSignedLong(image);
if (DiscardBlobBytes(image,offset+36) == MagickFalse)
ThrowFileException(exception,CorruptImageError,"UnexpectedEndOfFile",
image->filename);
if (EOFBlob(image) != MagickFalse)
ThrowReaderException(CorruptImageError,"UnexpectedEndOfFile");
number_colors=(size_t) ReadBlobByte(image)+1;
for (i=0; i < (ssize_t) number_colors; i++)
{
j=ReadBlobByte(image);
blocks[i].color=PESColor+(j < 0 ? 0 : j);
blocks[i].offset=0;
}
for ( ; i < 256L; i++)
{
blocks[i].offset=0;
blocks[i].color=PESColor;
}
if (DiscardBlobBytes(image,532L-number_colors-21) == MagickFalse)
ThrowFileException(exception,CorruptImageError,"UnexpectedEndOfFile",
image->filename);
if (EOFBlob(image) != MagickFalse)
ThrowReaderException(CorruptImageError,"UnexpectedEndOfFile");
number_stitches=64;
stitches=(PointInfo *) AcquireQuantumMemory(number_stitches,
sizeof(*stitches));
if (stitches == (PointInfo *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
bounds.x1=65535.0;
bounds.y1=65535.0;
bounds.x2=(-65535.0);
bounds.y2=(-65535.0);
i=0;
j=0;
delta_x=0;
delta_y=0;
while (EOFBlob(image) == MagickFalse)
{
x=ReadBlobByte(image);
y=ReadBlobByte(image);
if ((x == 0xff) && (y == 0))
break;
if ((x == 254) && (y == 176))
{
j++;
blocks[j].offset=(ssize_t) i;
if (j >= 256)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
(void) ReadBlobByte(image);
continue;
}
if ((x & 0x80) == 0)
{
if ((x & 0x40) != 0)
x-=0x80;
}
else
{
x=((x & 0x0f) << 8)+y;
if ((x & 0x800) != 0)
x-=0x1000;
y=ReadBlobByte(image);
}
if ((y & 0x80) == 0)
{
if ((y & 0x40) != 0)
y-=0x80;
}
else
{
y=((y & 0x0f) << 8)+ReadBlobByte(image);
if ((y & 0x800) != 0)
y-=0x1000;
}
x+=delta_x;
y+=delta_y;
delta_x=x;
delta_y=y;
stitches[i].x=(double) x;
stitches[i].y=(double) y;
if ((double) x < bounds.x1)
bounds.x1=(double) x;
if ((double) x > bounds.x2)
bounds.x2=(double) x;
if ((double) y < bounds.y1)
bounds.y1=(double) y;
if ((double) y > bounds.y2)
bounds.y2=(double) y;
i++;
if (i >= (ssize_t) number_stitches)
{
number_stitches<<=1;
stitches=(PointInfo *)  ResizeQuantumMemory(stitches,(size_t)
number_stitches,sizeof(*stitches));
if (stitches == (PointInfo *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
}
}
j++;
blocks[j].offset=(ssize_t) i;
number_blocks=(size_t) j;
image->columns=bounds.x2-bounds.x1;
image->rows=bounds.y2-bounds.y1;
status=SetImageExtent(image,image->columns,image->rows,exception);
if (status == MagickFalse)
return(DestroyImageList(image));
file=(FILE *) NULL;
unique_file=AcquireUniqueFileResource(filename);
if (unique_file != -1)
file=fdopen(unique_file,"wb");
if ((unique_file == -1) || (file == (FILE *) NULL))
ThrowImageException(FileOpenError,"UnableToCreateTemporaryFile");
(void) FormatLocaleFile(file,"<?xml version=\"1.0\"?>\n");
(void) FormatLocaleFile(file,"<svg xmlns=\"http:    "xlink=\"http:    "ev=\"http:    "baseProfile=\"full\" width=\"%g\" height=\"%g\">\n",(double)
image->columns,(double) image->rows);
for (i=0; i < (ssize_t) number_blocks; i++)
{
offset=blocks[i].offset;
(void) FormatLocaleFile(file,"  <path stroke=\"#%02x%02x%02x\" "
"fill=\"none\" d=\"M %g %g",blocks[i].color->red,blocks[i].color->green,
blocks[i].color->blue,stitches[offset].x-bounds.x1,
stitches[offset].y-bounds.y1);
for (j=1; j < (ssize_t) (blocks[i+1].offset-offset); j++)
(void) FormatLocaleFile(file," L %g %g",stitches[offset+j].x-bounds.x1,
stitches[offset+j].y-bounds.y1);
(void) FormatLocaleFile(file,"\"/>\n");
}
(void) FormatLocaleFile(file,"</svg>\n");
(void) fclose(file);
(void) CloseBlob(image);
image=DestroyImage(image);
read_info=CloneImageInfo(image_info);
SetImageInfoBlob(read_info,(void *) NULL,0);
(void) FormatLocaleString(read_info->filename,MagickPathExtent,"svg:%s",
filename);
image=ReadImage(read_info,exception);
if (image != (Image *) NULL)
{
(void) CopyMagickString(image->filename,image_info->filename,
MagickPathExtent);
(void) CopyMagickString(image->magick_filename,image_info->filename,
MagickPathExtent);
(void) CopyMagickString(image->magick,"PES",MagickPathExtent);
}
read_info=DestroyImageInfo(read_info);
(void) RelinquishUniqueFileResource(filename);
return(GetFirstImageInList(image));
}

static struct jsontree_value *
find_next(struct jsontree_context *js_ctx)
{
struct jsontree_value *v;
int index;
do {
v = js_ctx->values[js_ctx->depth];
switch(v->type) {
case JSON_TYPE_OBJECT:
case JSON_TYPE_ARRAY: {
struct jsontree_array *o = (struct jsontree_array *)v;
struct jsontree_value *ov;
index = js_ctx->index[js_ctx->depth];
if(index >= o->count) {
break;
}
if(v->type == JSON_TYPE_OBJECT) {
ov = ((struct jsontree_object *)o)->pairs[index].value;
} else {
ov = o->values[index];
}
js_ctx->depth++;        
js_ctx->index[js_ctx->depth] = 0;       
js_ctx->values[js_ctx->depth] = ov;
return ov;
}
default:
break;
}
if(js_ctx->depth > 0) {
js_ctx->depth--;
js_ctx->index[js_ctx->depth]++;
} else {
return NULL;
}
} while(1);
}

fm_mgr_config_errno_t
fm_mgr_config_mgr_connect
(
fm_config_conx_hdl*hdl, 
fm_mgr_type_t mgr
)
{
char                    s_path[256];
char                    c_path[256];
char                    *mgr_prefix;
p_hsm_com_client_hdl_t  *mgr_hdl;
pid_t                   pid;
memset(s_path,0,sizeof(s_path));
memset(c_path,0,sizeof(c_path));
pid = getpid();
switch ( mgr )
{
case FM_MGR_SM:
mgr_prefix  = HSM_FM_SCK_SM;
mgr_hdl     = &hdl->sm_hdl;
break;
case FM_MGR_PM:
mgr_prefix  = HSM_FM_SCK_PM;
mgr_hdl     = &hdl->pm_hdl;
break;
case FM_MGR_FE:
mgr_prefix  = HSM_FM_SCK_FE;
mgr_hdl     = &hdl->fe_hdl;
break;
default:
return FM_CONF_INIT_ERR;
}
sprintf(s_path,"%s%s%d",HSM_FM_SCK_PREFIX,mgr_prefix,hdl->instance);
sprintf(c_path,"%s%s%d_C_%lu",HSM_FM_SCK_PREFIX,mgr_prefix,
hdl->instance, (long unsigned)pid);
if ( *mgr_hdl == NULL )
{
if ( hcom_client_init(mgr_hdl,s_path,c_path,32768) != HSM_COM_OK )
{
return FM_CONF_INIT_ERR;
}
}
if ( hcom_client_connect(*mgr_hdl) == HSM_COM_OK )
{
hdl->conx_mask |= mgr;
return FM_CONF_OK;
}
return FM_CONF_CONX_ERR;
}

