} else {
new_place_recovery_on = 0;
actual_element = new_place_recovery_father;
}
if (!actual_element) state= ST_END;
}
}

static Image *ReadPALMImage(const ImageInfo *image_info,
ExceptionInfo *exception)
{
Image
*image;
MagickBooleanType
status;
MagickOffsetType
totalOffset,
seekNextDepth;
PixelInfo
transpix;
Quantum
index;
register ssize_t
i,
x;
register Quantum
*q;
size_t
bytes_per_row,
flags,
bits_per_pixel,
version,
nextDepthOffset,
transparentIndex,
compressionType,
byte,
mask,
redbits,
greenbits,
bluebits,
one,
pad,
size,
bit;
ssize_t
count,
y;
unsigned char
*lastrow,
*one_row,
*ptr;
unsigned short
color16;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickCoreSignature);
if (image_info->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
image_info->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
image=AcquireImage(image_info,exception);
status=OpenBlob(image_info,image,ReadBinaryBlobMode,exception);
if (status == MagickFalse)
{
(void) DestroyImageList(image);
return((Image *) NULL);
}
totalOffset=0;
do
{
image->columns=ReadBlobMSBShort(image);
image->rows=ReadBlobMSBShort(image);
if (EOFBlob(image) != MagickFalse)
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
if ((image->columns == 0) || (image->rows == 0))
ThrowReaderException(CorruptImageError,"NegativeOrZeroImageSize");
status=SetImageExtent(image,image->columns,image->rows,exception);
if (status == MagickFalse)
return(DestroyImageList(image));
bytes_per_row=ReadBlobMSBShort(image);
flags=ReadBlobMSBShort(image);
bits_per_pixel=(size_t) ReadBlobByte(image);
if ((bits_per_pixel != 1) && (bits_per_pixel != 2) &&
(bits_per_pixel != 4) && (bits_per_pixel != 8) &&
(bits_per_pixel != 16))
ThrowReaderException(CorruptImageError,"UnrecognizedBitsPerPixel");
version=(size_t) ReadBlobByte(image);
if ((version != 0) && (version != 1) && (version != 2))
ThrowReaderException(CorruptImageError,"FileFormatVersionMismatch");
nextDepthOffset=(size_t) ReadBlobMSBShort(image);
transparentIndex=(size_t) ReadBlobByte(image);
compressionType=(size_t) ReadBlobByte(image);
if ((compressionType != PALM_COMPRESSION_NONE) &&
(compressionType != PALM_COMPRESSION_SCANLINE ) &&
(compressionType != PALM_COMPRESSION_RLE))
ThrowReaderException(CorruptImageError,"UnrecognizedImageCompression");
pad=ReadBlobMSBShort(image);
(void) pad;
one=1;
if ((bits_per_pixel < 16) &&
(AcquireImageColormap(image,one << bits_per_pixel,exception) == MagickFalse))
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
GetPixelInfo(image,&transpix);
if (bits_per_pixel == 16)  
{
redbits=(size_t) ReadBlobByte(image);  
(void) redbits;
greenbits=(size_t) ReadBlobByte(image);  
(void) greenbits;
bluebits=(size_t) ReadBlobByte(image);  
(void) bluebits;
ReadBlobByte(image);  
ReadBlobByte(image);  
transpix.red=(double) (QuantumRange*ReadBlobByte(image)/31);
transpix.green=(double) (QuantumRange*ReadBlobByte(image)/63);
transpix.blue=(double) (QuantumRange*ReadBlobByte(image)/31);
}
if (bits_per_pixel == 8)
{
ssize_t
index;
if (flags & PALM_HAS_COLORMAP_FLAG)
{
count=(ssize_t) ReadBlobMSBShort(image);
for (i=0; i < (ssize_t) count; i++)
{
ReadBlobByte(image);
index=ConstrainColormapIndex(image,255-i,exception);
image->colormap[index].red=(MagickRealType)
ScaleCharToQuantum((unsigned char) ReadBlobByte(image));
image->colormap[index].green=(MagickRealType)
ScaleCharToQuantum((unsigned char) ReadBlobByte(image));
image->colormap[index].blue=(MagickRealType)
ScaleCharToQuantum((unsigned char) ReadBlobByte(image));
}
}
else
for (i=0; i < (ssize_t) (1L << bits_per_pixel); i++)
{
index=ConstrainColormapIndex(image,255-i,exception);
image->colormap[index].red=(MagickRealType)
ScaleCharToQuantum(PalmPalette[i][0]);
image->colormap[index].green=(MagickRealType)
ScaleCharToQuantum(PalmPalette[i][1]);
image->colormap[index].blue=(MagickRealType)
ScaleCharToQuantum(PalmPalette[i][2]);
}
}
if (flags & PALM_IS_COMPRESSED_FLAG)
size=ReadBlobMSBShort(image);
(void) size;
image->storage_class=DirectClass;
if (bits_per_pixel < 16)
{
image->storage_class=PseudoClass;
image->depth=8;
}
if (image_info->ping != MagickFalse)
{
(void) CloseBlob(image);
return(image);
}
status=SetImageExtent(image,image->columns,image->rows,exception);
if (status == MagickFalse)
return(DestroyImageList(image));
one_row=(unsigned char *) AcquireQuantumMemory(MagickMax(bytes_per_row,
2*image->columns),sizeof(*one_row));
if (one_row == (unsigned char *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
lastrow=(unsigned char *) NULL;
if (compressionType == PALM_COMPRESSION_SCANLINE)
{
lastrow=(unsigned char *) AcquireQuantumMemory(MagickMax(bytes_per_row,
2*image->columns),sizeof(*lastrow));
if (lastrow == (unsigned char *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
}
mask=(size_t) (1U << bits_per_pixel)-1;
for (y=0; y < (ssize_t) image->rows; y++)
{
if ((flags & PALM_IS_COMPRESSED_FLAG) == 0)
{
image->compression=NoCompression;
count=ReadBlob(image,bytes_per_row,one_row);
if (count != (ssize_t) bytes_per_row)
break;
}
else
{
if (compressionType == PALM_COMPRESSION_RLE)
{ 
image->compression=RLECompression;
for (i=0; i < (ssize_t) bytes_per_row; )
{
count=(ssize_t) ReadBlobByte(image);
if (count < 0)
break;
count=MagickMin(count,(ssize_t) bytes_per_row-i);
byte=(size_t) ReadBlobByte(image);
(void) ResetMagickMemory(one_row+i,(int) byte,(size_t) count);
i+=count;
}
}
else
if (compressionType == PALM_COMPRESSION_SCANLINE)
{
size_t
one;
one=1;
image->compression=FaxCompression;
for (i=0; i < (ssize_t) bytes_per_row; i+=8)
{
count=(ssize_t) ReadBlobByte(image);
if (count < 0)
break;
byte=(size_t) MagickMin((ssize_t) bytes_per_row-i,8);
for (bit=0; bit < byte; bit++)
{
if ((y == 0) || (count & (one << (7 - bit))))
one_row[i+bit]=(unsigned char) ReadBlobByte(image);
else
one_row[i+bit]=lastrow[i+bit];
}
}
(void) CopyMagickMemory(lastrow, one_row, bytes_per_row);
}
}
ptr=one_row;
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
if (bits_per_pixel == 16)
{
if (image->columns > (2*bytes_per_row))
{
one_row=(unsigned char *) RelinquishMagickMemory(one_row);
if (compressionType == PALM_COMPRESSION_SCANLINE)
lastrow=(unsigned char *) RelinquishMagickMemory(lastrow);
ThrowReaderException(CorruptImageError,"CorruptImage");
}
for (x=0; x < (ssize_t) image->columns; x++)
{
color16=(*ptr++ << 8);
color16|=(*ptr++);
SetPixelRed(image,(Quantum) ((QuantumRange*((color16 >> 11) &
0x1f))/0x1f),q);
SetPixelGreen(image,(Quantum) ((QuantumRange*((color16 >> 5) &
0x3f))/0x3f),q);
SetPixelBlue(image,(Quantum) ((QuantumRange*((color16 >> 0) &
0x1f))/0x1f),q);
SetPixelAlpha(image,OpaqueAlpha,q);
q+=GetPixelChannels(image);
}
}
else
{
bit=8-bits_per_pixel;
for (x=0; x < (ssize_t) image->columns; x++)
{
if ((size_t) (ptr-one_row) >= bytes_per_row)
{
one_row=(unsigned char *) RelinquishMagickMemory(one_row);
if (compressionType == PALM_COMPRESSION_SCANLINE)
lastrow=(unsigned char *) RelinquishMagickMemory(lastrow);
ThrowReaderException(CorruptImageError,"CorruptImage");
}
index=(Quantum) (mask-(((*ptr) & (mask << bit)) >> bit));
SetPixelIndex(image,index,q);
SetPixelViaPixelInfo(image,image->colormap+(ssize_t) index,q);
if (bit)
bit-=bits_per_pixel;
else
{
ptr++;
bit=8-bits_per_pixel;
}
q+=GetPixelChannels(image);
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
}
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
if (flags & PALM_HAS_TRANSPARENCY_FLAG)
{
ssize_t index=ConstrainColormapIndex(image,(ssize_t) (mask-
transparentIndex),exception);
if (bits_per_pixel != 16)
transpix=image->colormap[index];
(void) TransparentPaintImage(image,&transpix,(Quantum) TransparentAlpha,
MagickFalse,exception);
}
one_row=(unsigned char *) RelinquishMagickMemory(one_row);
if (compressionType == PALM_COMPRESSION_SCANLINE)
lastrow=(unsigned char *) RelinquishMagickMemory(lastrow);
if (EOFBlob(image) != MagickFalse)
{
ThrowFileException(exception,CorruptImageError,"UnexpectedEndOfFile",
image->filename);
break;
}
if (image_info->number_scenes != 0)
if (image->scene >= (image_info->scene+image_info->number_scenes-1))
break;
if (nextDepthOffset != 0)
{ 
totalOffset+=(MagickOffsetType) (nextDepthOffset*4);
if (totalOffset >= (MagickOffsetType) GetBlobSize(image))
ThrowReaderException(CorruptImageError,"ImproperImageHeader")
else
seekNextDepth=SeekBlob(image,totalOffset,SEEK_SET);
if (seekNextDepth != totalOffset)
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
AcquireNextImage(image_info,image,exception);
if (GetNextImageInList(image) == (Image *) NULL)
{
(void) DestroyImageList(image);
return((Image *) NULL);
}
image=SyncNextImageInList(image);
status=SetImageProgress(image,LoadImagesTag,TellBlob(image),
GetBlobSize(image));
if (status == MagickFalse)
break;
}
} while (nextDepthOffset != 0);
(void) CloseBlob(image);
return(GetFirstImageInList(image));
}

Status GraphDefImporter::ConvertNodeDef(OpBuilder &builder, ConversionState &s,
const NodeDef &node) {
VLOG(4) << "Importing: " << node.name();
OperationState state(ConvertLocation(node), absl::StrCat("tfg.", node.op()));
const OpDef *op_def;
const OpRegistrationData *op_reg_data = nullptr;
if ((op_reg_data = registry_.LookUp(node.op()))) {
op_def = &op_reg_data->op_def;
} else {
auto it = function_op_defs_.find(node.op());
if (it == function_op_defs_.end())
return InvalidArgument("Unable to find OpDef for ", node.op());
op_def = it->second;
}
state.attributes.reserve(node.attr_size() + 3);
if (!node.device().empty()) {
state.addAttribute(dialect_->getDeviceAttrIdentifier(),
b_.getStringAttr(node.device()));
}
if (!node.name().empty()) {
state.addAttribute(dialect_->getNameAttrIdentifier(),
b_.getStringAttr(node.name()));
}
const auto add_full_type = [&](const FullTypeDef &full_type_def) {
TF_ASSIGN_OR_RETURN(tf_type::FullTypeAttr full_type,
ConvertAttribute(full_type_def, b_, dialect_));
state.addAttribute(dialect_->getFullTypeAttrIdentifier(), full_type);
return ::tensorflow::OkStatus();
};
if (node.has_experimental_type()) {
TF_RETURN_IF_ERROR(add_full_type(node.experimental_type()));
} else if (op_reg_data && op_reg_data->type_ctor) {
FullTypeDef full_type_def;
TF_RETURN_IF_ERROR(
tensorflow::full_type::SpecializeType(node, *op_def, full_type_def));
TF_RETURN_IF_ERROR(add_full_type(full_type_def));
}
for (auto &name_attr : node.attr()) {
if (name_attr.first.empty())
return InvalidArgument("Node ", node.name(), " has an empty attr name");
TF_ASSIGN_OR_RETURN(Attribute attr,
ConvertAttributeValue(name_attr.second, b_, dialect_));
state.addAttribute(name_attr.first, attr);
}
for (const auto &attr_def : op_def->attr()) {
if (attr_def.has_default_value() &&
!state.attributes.get(attr_def.name())) {
TF_ASSIGN_OR_RETURN(
Attribute attr,
ConvertAttributeValue(attr_def.default_value(), b_, dialect_));
state.addAttribute(attr_def.name(), attr);
}
}
SmallVector<std::pair<unsigned, unsigned>> result_segments;
result_segments.reserve(op_def->output_arg_size());
state.types.reserve(op_def->output_arg_size() + 1);
for (const OpDef::ArgDef &def : op_def->output_arg()) {
unsigned index = state.types.size();
TF_ASSIGN_OR_RETURN(unsigned size,
ArgNumType(state.attributes, def, state.types));
result_segments.emplace_back(index, size);
}
state.types.push_back(dialect_->getControlType());
state.operands.reserve(node.input_size());
SmallVector<Value> control_operands;
struct BackedgeResolution {
ResultInfo *info;
size_t operand_index;
ResultId id;
};
SmallVector<BackedgeResolution> unresolved_data_operands,
unresolved_control_operands;
for (const std::string &input : node.input()) {
TF_ASSIGN_OR_RETURN(Result result, GetResult(s, input));
if (result.control) {
if (result.info) {
unresolved_control_operands.push_back(BackedgeResolution{
result.info, control_operands.size(), result.id});
}
control_operands.push_back(result.control);
} else {
if (result.info) {
unresolved_data_operands.push_back(
BackedgeResolution{result.info, state.operands.size(), result.id});
}
state.operands.push_back(result.data);
}
}
unsigned num_data_operands = state.operands.size();
state.addOperands(control_operands);
Operation *op = builder.create(state);
for (const BackedgeResolution &r : unresolved_data_operands) {
r.info->backedges.push_back(
Backedge{r.id, &op->getOpOperand(r.operand_index)});
}
for (const BackedgeResolution &r : unresolved_control_operands) {
r.info->backedges.push_back(
Backedge{r.id, &op->getOpOperand(num_data_operands + r.operand_index)});
}
std::unique_ptr<ResultInfo> &info = s[node.name()];
if (!info) {
info = std::make_unique<ResultInfo>();
}
info->resolved = true;
info->control = *std::prev(op->result_end());
info->data = op->getResults().drop_back();
for (auto it : llvm::zip(result_segments, op_def->output_arg())) {
const std::pair<unsigned, unsigned> &segment = std::get<0>(it);
info->outputs.emplace(std::get<1>(it).name(),
info->data.slice(segment.first, segment.second));
}
for (const Backedge &backedge : info->backedges) {
Value value;
if (backedge.id.IsControl()) {
value = info->control;
} else {
TF_ASSIGN_OR_RETURN(value, ResolveDataResult(backedge.id, info.get()));
}
backedge.operand->set(value);
}
info->backedges.clear();
return ::tensorflow::OkStatus();
}

static void
pdf_filter_BDC(fz_context *ctx, pdf_processor *proc, const char *tag, pdf_obj *raw, pdf_obj *cooked)
{
pdf_filter_processor *p = (pdf_filter_processor*)proc;
tag_record *bdc = fz_malloc_struct(ctx, tag_record);
pdf_obj *mcid;
fz_try(ctx)
{
bdc->bdc = 1;
bdc->tag = fz_strdup(ctx, tag);
bdc->raw = pdf_keep_obj(ctx, raw);
bdc->cooked = pdf_keep_obj(ctx, raw);
}
fz_catch(ctx)
{
fz_free(ctx, bdc->tag);
pdf_drop_obj(ctx, bdc->raw);
pdf_drop_obj(ctx, bdc->cooked);
fz_free(ctx, bdc);
fz_rethrow(ctx);
}
bdc->prev = p->pending_tags;
p->pending_tags = bdc;
mcid = pdf_dict_get(ctx, cooked, PDF_NAME(MCID));
if (!pdf_is_number(ctx, mcid))
return;
bdc->mcid_num = pdf_to_int(ctx, mcid);
bdc->mcid_obj = pdf_keep_obj(ctx, pdf_array_get(ctx, p->structarray, bdc->mcid_num));
bdc->alt.utf8 = pdf_new_utf8_from_pdf_string_obj(ctx, pdf_dict_get(ctx, bdc->mcid_obj, PDF_NAME(Alt)));
bdc->actualtext.utf8 = pdf_new_utf8_from_pdf_string_obj(ctx, pdf_dict_get(ctx, bdc->mcid_obj, PDF_NAME(ActualText)));
}

