static inline int sh_get_ref(struct domain *d, mfn_t smfn, paddr_t entry_pa)
{
u32 x, nx;
struct page_info *sp = mfn_to_page(smfn);
ASSERT(mfn_valid(smfn));
ASSERT(sp->u.sh.head);
x = sp->u.sh.count;
nx = x + 1;
if ( unlikely(nx >= 1U<<26) )
{
SHADOW_PRINTK("shadow ref overflow, gmfn=%lx smfn=%lx\n",
__backpointer(sp), mfn_x(smfn));
return 0;
}
sp->u.sh.count = nx;
if ( entry_pa != 0
&& sh_type_has_up_pointer(d, sp->u.sh.type)
&& sp->up == 0 )
sp->up = entry_pa;
return 1;
}

packet_t *
capture_packet_reasm_ip(capture_info_t *capinfo, const struct pcap_pkthdr *header, u_char *packet, uint32_t *size, uint32_t *caplen)
{
struct ip *ip4;
#ifdef USE_IPV6
struct ip6_hdr *ip6;
#endif
uint32_t ip_ver;
uint8_t ip_proto;
uint32_t ip_hl = 0;
uint16_t ip_off = 0;
uint16_t ip_len = 0;
uint16_t ip_frag = 0;
uint32_t ip_id = 0;
uint16_t ip_frag_off = 0;
address_t src = { };
address_t dst = { };
vector_iter_t it;
packet_t *pkt;
frame_t *frame;
uint32_t len_data = 0;
uint16_t link_hl = capinfo->link_hl;
#ifdef USE_IPV6
struct ip6_frag *ip6f;
#endif
if (capinfo->link == DLT_EN10MB) {
struct ether_header *eth = (struct ether_header *) packet;
if (ntohs(eth->ether_type) == ETHERTYPE_8021Q) {
link_hl += 4;
}
}
#ifdef SLL_HDR_LEN
if (capinfo->link == DLT_LINUX_SLL) {
struct sll_header *sll = (struct sll_header *) packet;
if (ntohs(sll->sll_protocol) == ETHERTYPE_8021Q) {
link_hl += 4;
}
}
#endif
if (capinfo->link == DLT_NFLOG) {
while (link_hl + 8 <= *caplen) {
nflog_tlv_t *tlv = (nflog_tlv_t *) (packet + link_hl);
if (!tlv) break;
if (tlv->tlv_type == NFULA_PAYLOAD) {
link_hl += 4;
break;
}
if (tlv->tlv_length >= 4) {
link_hl += ((tlv->tlv_length + 3) & ~3); 
}
}
}
while (*size >= sizeof(struct ip)) {
ip4 = (struct ip *) (packet + link_hl);
#ifdef USE_IPV6
ip6 = (struct ip6_hdr *) (packet + link_hl);
#endif
ip_ver = ip4->ip_v;
switch (ip_ver) {
case 4:
ip_hl = ip4->ip_hl * 4;
ip_proto = ip4->ip_p;
ip_off = ntohs(ip4->ip_off);
ip_len = ntohs(ip4->ip_len);
ip_frag = ip_off & (IP_MF | IP_OFFMASK);
ip_frag_off = (ip_frag) ? (ip_off & IP_OFFMASK) * 8 : 0;
ip_id = ntohs(ip4->ip_id);
inet_ntop(AF_INET, &ip4->ip_src, src.ip, sizeof(src.ip));
inet_ntop(AF_INET, &ip4->ip_dst, dst.ip, sizeof(dst.ip));
break;
#ifdef USE_IPV6
case 6:
ip_hl = sizeof(struct ip6_hdr);
ip_proto = ip6->ip6_nxt;
ip_len = ntohs(ip6->ip6_ctlun.ip6_un1.ip6_un1_plen) + ip_hl;
if (ip_proto == IPPROTO_FRAGMENT) {
ip_frag = 1;
ip6f = (struct ip6_frag *) (packet + link_hl + ip_hl);
ip_frag_off = ntohs(ip6f->ip6f_offlg & IP6F_OFF_MASK);
ip_id = ntohl(ip6f->ip6f_ident);
}
inet_ntop(AF_INET6, &ip6->ip6_src, src.ip, sizeof(src.ip));
inet_ntop(AF_INET6, &ip6->ip6_dst, dst.ip, sizeof(dst.ip));
break;
#endif
default:
return NULL;
}
*caplen = link_hl + ip_len;
*size = *caplen - link_hl - ip_hl;
if (ip_proto == IPPROTO_IPIP) {
link_hl += ip_hl;
} else {
break;
}
}
if (ip_frag == 0) {
pkt = packet_create(ip_ver, ip_proto, src, dst, ip_id);
packet_add_frame(pkt, header, packet);
return pkt;
}
it = vector_iterator(capinfo->ip_reasm);
while ((pkt = vector_iterator_next(&it))) {
if (addressport_equals(pkt->src, src)
&& addressport_equals(pkt->dst, dst)
&& pkt->ip_id == ip_id) {
break;
}
}
if (pkt) {
packet_add_frame(pkt, header, packet);
} else {
pkt = packet_create(ip_ver, ip_proto, src, dst, ip_id);
packet_add_frame(pkt, header, packet);
vector_append(capinfo->ip_reasm, pkt);
}
pkt->ip_cap_len += ip_len - ip_hl;
#ifdef USE_IPV6
if (ip_ver == 6 && ip_frag) {
pkt->ip_cap_len -= sizeof(struct ip6_frag);
}
#endif
if (ip_ver == 4 && (ip_off & IP_MF) == 0) {
pkt->ip_exp_len = ip_frag_off + ip_len - ip_hl;
}
#ifdef USE_IPV6
if (ip_ver == 6 && ip_frag && (ip6f->ip6f_offlg & htons(0x01)) == 0) {
pkt->ip_exp_len = ip_frag_off + ip_len - ip_hl - sizeof(struct ip6_frag);
}
#endif
if (pkt->ip_cap_len == pkt->ip_exp_len) {
it = vector_iterator(pkt->frames);
while ((frame = vector_iterator_next(&it))) {
switch (ip_ver) {
case 4: {
struct ip *frame_ip = (struct ip *) (frame->data + link_hl);
len_data += ntohs(frame_ip->ip_len) - frame_ip->ip_hl * 4;
break;
}
#ifdef USE_IPV6
case 6: {
struct ip6_hdr *frame_ip6 = (struct ip6_hdr *) (frame->data + link_hl);
len_data += ntohs(frame_ip6->ip6_ctlun.ip6_un1.ip6_un1_plen);
break;
}
#endif
default:
break;
}
}
if (len_data > MAX_CAPTURE_LEN)
return NULL;
memset(packet, 0, link_hl + ip_hl + len_data);
it = vector_iterator(pkt->frames);
while ((frame = vector_iterator_next(&it))) {
switch (ip_ver) {
case 4: {
struct ip *frame_ip = (struct ip *) (frame->data + link_hl);
memcpy(packet + link_hl + ip_hl + (ntohs(frame_ip->ip_off) & IP_OFFMASK) * 8,
frame->data + link_hl + frame_ip->ip_hl * 4,
ntohs(frame_ip->ip_len) - frame_ip->ip_hl * 4);
}
break;
#ifdef USE_IPV6
case 6: {
struct ip6_hdr *frame_ip6 = (struct ip6_hdr*)(frame->data + link_hl);
struct ip6_frag *frame_ip6f = (struct ip6_frag *)(frame->data + link_hl + ip_hl);
uint16_t frame_ip_frag_off = ntohs(frame_ip6f->ip6f_offlg & IP6F_OFF_MASK);
memcpy(packet + link_hl + ip_hl + sizeof(struct ip6_frag) + frame_ip_frag_off,
frame->data + link_hl + ip_hl + sizeof (struct ip6_frag),
ntohs(frame_ip6->ip6_ctlun.ip6_un1.ip6_un1_plen));
pkt->proto = frame_ip6f->ip6f_nxt;
}
break;
#endif
default:
break;
}
}
*caplen = link_hl + ip_hl + len_data;
#ifdef USE_IPV6
if (ip_ver == 6) {
*caplen += sizeof(struct ip6_frag);
}
#endif
*size = len_data;
vector_remove(capinfo->ip_reasm, pkt);
return pkt;
}
return NULL;
}

void pdf_load_pages_kids(FILE *fp, pdf_t *pdf)
{
int     i, id, dummy;
char   *buf, *c;
long    start, sz;
start = ftell(fp);
for (i=0; i<pdf->n_xrefs; i++)
{
if (pdf->xrefs[i].version && (pdf->xrefs[i].end != 0))
{
fseek(fp, pdf->xrefs[i].start, SEEK_SET);
while (SAFE_F(fp, (fgetc(fp) != 't')))
; 
sz = pdf->xrefs[i].end - ftell(fp);
buf = malloc(sz + 1);
SAFE_E(fread(buf, 1, sz, fp), sz, "Failed to load /Root.\n");
buf[sz] = '\0';
if (!(c = strstr(buf, "/Root")))
{
free(buf);
continue;
}
id = atoi(c + strlen("/Root") + 1);
free(buf);
buf = get_object(fp, id, &pdf->xrefs[i], NULL, &dummy);
if (!buf || !(c = strstr(buf, "/Pages")))
{
free(buf);
continue;
}
id = atoi(c + strlen("/Pages") + 1);
load_kids(fp, id, &pdf->xrefs[i]);
free(buf); 
}
}
fseek(fp, start, SEEK_SET);
}

int Tar::ExtractData(std::istream& aTarStreamIn, wxString destdir, wxProgressDialog* aProgressDialog)
{
int lError = 0;
unsigned long lTotalBytes = 0;
unsigned long lTotalBytesRead = 0;
aTarStreamIn.seekg(0, std::ios::end);
unsigned long lEnd = static_cast<unsigned long>(aTarStreamIn.tellg());
aTarStreamIn.seekg(0, std::ios::beg);
lTotalBytes = lEnd - static_cast<unsigned long>(aTarStreamIn.tellg());
wxString lPreviousWorkingDirectory(::wxGetCwd());
::wxSetWorkingDirectory(destdir);
int ebufsiz = 8192;
char buffer[ebufsiz];
for (unsigned int lTarRecordIndex = 0; lTarRecordIndex < TarRecords.size(); ++lTarRecordIndex)
{
TarRecord lCurrentTarRecord = TarRecords.at(lTarRecordIndex);
wxString lCurrentFilePath = wxString(lCurrentTarRecord.Name, wxConvUTF8);
if (lCurrentFilePath.IsEmpty())
{
lCurrentFilePath = wxString(lCurrentTarRecord.Name, wxConvISO8859_1);
}
wxString lCurrentDirectory(lCurrentFilePath.substr(0, lCurrentFilePath.find_last_of('/')));
if (lCurrentFilePath.compare(_T("\xFF")) == 0)         {
if (lTarRecordIndex != TarRecords.size() - 1)
{
lError = 1;
wxLogError(_("Got bad file %d/%d.  Skipping."), lTarRecordIndex, TarRecords.size() );
}
}
else
{
if (::wxDirExists(lCurrentDirectory) == false)
{
wxFileName::Mkdir(lCurrentDirectory, 0777, wxPATH_MKDIR_FULL);
}
char lLastCharacter = lCurrentFilePath[lCurrentFilePath.length() - 1];
if (lLastCharacter != '\\' && lLastCharacter != '/')
{
wxFile wx_Out(lCurrentFilePath, wxFile::write);
if (!wx_Out.IsOpened())
{
wxLogError(_("Error: Improperly archived file '%s'.  Skipping."), lCurrentFilePath);
lError = 1;
continue;
}
__gnu_cxx::stdio_filebuf<char> filebuf(wx_Out.fd(), std::ios::out);
std::ostream lStreamOut(&filebuf);
aTarStreamIn.seekg(lCurrentTarRecord.iFilePosBegin, std::ios::beg);
long remaining = lCurrentTarRecord.iFileSize;
while (remaining > 0)
{
int bufsiz = remaining;
if (bufsiz > ebufsiz) bufsiz = ebufsiz;
aTarStreamIn.read(buffer, bufsiz);
lStreamOut.write(buffer, bufsiz);
remaining -= bufsiz;
}
lTotalBytesRead += lCurrentTarRecord.iFileSize;
lStreamOut.flush();
wx_Out.Close();
}
if( aProgressDialog != NULL )
{
double lPercent( 100.0 * lTotalBytesRead / lTotalBytes ) ;
if ( lPercent >= 100 )
{
lPercent = 99.0;
}
aProgressDialog->Update(static_cast<int>(lPercent), lCurrentFilePath);
::wxYield();
}
}
}
aProgressDialog->Update(100, _("Done."));
::wxSetWorkingDirectory(lPreviousWorkingDirectory);
return lError;
}

void GrpcHealthCheckerImpl::GrpcActiveHealthCheckSession::onRpcComplete(
Grpc::Status::GrpcStatus grpc_status, const std::string& grpc_message, bool end_stream) {
