int nfc_llcp_send_cc(struct nfc_llcp_sock *sock)
{
struct nfc_llcp_local *local;
struct sk_buff *skb;
u8 *miux_tlv = NULL, miux_tlv_length;
u8 *rw_tlv = NULL, rw_tlv_length, rw;
int err;
u16 size = 0;
__be16 miux;
pr_debug("Sending CC\n");
local = sock->local;
if (local == NULL)
return -ENODEV;
miux = be16_to_cpu(sock->miux) > LLCP_MAX_MIUX ?
local->miux : sock->miux;
rw = sock->rw > LLCP_MAX_RW ? local->rw : sock->rw;
miux_tlv = nfc_llcp_build_tlv(LLCP_TLV_MIUX, (u8 *)&miux, 0,
&miux_tlv_length);
size += miux_tlv_length;
rw_tlv = nfc_llcp_build_tlv(LLCP_TLV_RW, &rw, 0, &rw_tlv_length);
size += rw_tlv_length;
skb = llcp_allocate_pdu(sock, LLCP_PDU_CC, size);
if (skb == NULL) {
err = -ENOMEM;
goto error_tlv;
}
llcp_add_tlv(skb, miux_tlv, miux_tlv_length);
llcp_add_tlv(skb, rw_tlv, rw_tlv_length);
skb_queue_tail(&local->tx_queue, skb);
err = 0;
error_tlv:
if (err)
pr_err("error %d\n", err);
kfree(miux_tlv);
kfree(rw_tlv);
return err;
}

static struct clk ** __init sunxi_divs_clk_setup(struct device_node *node,
const struct divs_data *data)
{
struct clk_onecell_data *clk_data;
const char *parent;
const char *clk_name;
struct clk **clks, *pclk;
struct clk_hw *gate_hw, *rate_hw;
const struct clk_ops *rate_ops;
struct clk_gate *gate = NULL;
struct clk_fixed_factor *fix_factor;
struct clk_divider *divider;
struct factors_data factors = *data->factors;
char *derived_name = NULL;
void __iomem *reg;
int ndivs = SUNXI_DIVS_MAX_QTY, i = 0;
int flags, clkflags;
if (data->ndivs)
ndivs = data->ndivs;
for (i = 0; i < ndivs; i++) {
if (data->div[i].self) {
of_property_read_string_index(node, "clock-output-names",
i, &factors.name);
break;
}
}
if (factors.name == NULL) {
char *endp;
of_property_read_string_index(node, "clock-output-names",
0, &clk_name);
endp = strchr(clk_name, '_');
if (endp) {
derived_name = kstrndup(clk_name, endp - clk_name,
GFP_KERNEL);
factors.name = derived_name;
} else {
factors.name = clk_name;
}
}
pclk = sunxi_factors_clk_setup(node, &factors);
if (!pclk)
return NULL;
parent = __clk_get_name(pclk);
kfree(derived_name);
reg = of_iomap(node, 0);
if (!reg) {
pr_err("Could not map registers for divs-clk: %pOF\n", node);
return NULL;
}
clk_data = kmalloc(sizeof(struct clk_onecell_data), GFP_KERNEL);
if (!clk_data)
goto out_unmap;
clks = kcalloc(ndivs, sizeof(*clks), GFP_KERNEL);
if (!clks)
goto free_clkdata;
clk_data->clks = clks;
clkflags = !strcmp("pll5", parent) ? 0 : CLK_SET_RATE_PARENT;
for (i = 0; i < ndivs; i++) {
if (of_property_read_string_index(node, "clock-output-names",
i, &clk_name) != 0)
break;
if (data->div[i].self) {
clk_data->clks[i] = pclk;
continue;
}
gate_hw = NULL;
rate_hw = NULL;
rate_ops = NULL;
if (data->div[i].gate) {
gate = kzalloc(sizeof(*gate), GFP_KERNEL);
if (!gate)
goto free_clks;
gate->reg = reg;
gate->bit_idx = data->div[i].gate;
gate->lock = &clk_lock;
gate_hw = &gate->hw;
}
if (data->div[i].fixed) {
fix_factor = kzalloc(sizeof(*fix_factor), GFP_KERNEL);
if (!fix_factor)
goto free_gate;
fix_factor->mult = 1;
fix_factor->div = data->div[i].fixed;
rate_hw = &fix_factor->hw;
rate_ops = &clk_fixed_factor_ops;
} else {
divider = kzalloc(sizeof(*divider), GFP_KERNEL);
if (!divider)
goto free_gate;
flags = data->div[i].pow ? CLK_DIVIDER_POWER_OF_TWO : 0;
divider->reg = reg;
divider->shift = data->div[i].shift;
divider->width = SUNXI_DIVISOR_WIDTH;
divider->flags = flags;
divider->lock = &clk_lock;
divider->table = data->div[i].table;
rate_hw = &divider->hw;
rate_ops = &clk_divider_ops;
}
clks[i] = clk_register_composite(NULL, clk_name, &parent, 1,
NULL, NULL,
rate_hw, rate_ops,
gate_hw, &clk_gate_ops,
clkflags |
data->div[i].critical ?
CLK_IS_CRITICAL : 0);
WARN_ON(IS_ERR(clk_data->clks[i]));
}
clk_data->clk_num = i;
if (of_clk_add_provider(node, of_clk_src_onecell_get, clk_data)) {
pr_err("%s: failed to add clock provider for %s\n",
__func__, clk_name);
goto free_gate;
}
return clks;
free_gate:
kfree(gate);
free_clks:
kfree(clks);
free_clkdata:
kfree(clk_data);
out_unmap:
iounmap(reg);
return NULL;
}

static void FixSDTPInTRAF(GF_MovieFragmentBox *moof)
{
u32 k;
if (!moof)
return;
for (k = 0; k < gf_list_count(moof->TrackList); k++) {
GF_TrackFragmentBox *traf = gf_list_get(moof->TrackList, k);
if (traf->sdtp) {
GF_TrackFragmentRunBox *trun;
u32 j = 0, sample_index = 0;
if (traf->sdtp->sampleCount == gf_list_count(traf->TrackRuns)) {
GF_LOG(GF_LOG_WARNING, GF_LOG_CONTAINER, ("[iso file] Warning: TRAF box of track id=%u contains a SDTP. Converting to TRUN sample flags.\n", traf->tfhd->trackID));
}
while ((trun = (GF_TrackFragmentRunBox*)gf_list_enum(traf->TrackRuns, &j))) {
u32 i;
trun->flags |= GF_ISOM_TRUN_FLAGS;
trun->flags &= ~GF_ISOM_TRUN_FIRST_FLAG;
for (i=0; i<trun->nb_samples; i++) {
GF_TrunEntry *entry = &trun->samples[i];
const u8 info = traf->sdtp->sample_info[sample_index];
entry->flags |= GF_ISOM_GET_FRAG_DEPEND_FLAGS(info >> 6, info >> 4, info >> 2, info);
sample_index++;
if (sample_index > traf->sdtp->sampleCount) {
GF_LOG(GF_LOG_ERROR, GF_LOG_CONTAINER, ("[iso file] Error: TRAF box of track id=%u contained an inconsistent SDTP.\n", traf->tfhd->trackID));
return;
}
}
}
if (sample_index < traf->sdtp->sampleCount) {
GF_LOG(GF_LOG_ERROR, GF_LOG_CONTAINER, ("[iso file] Error: TRAF box of track id=%u list less samples than SDTP.\n", traf->tfhd->trackID));
}
gf_isom_box_del_parent(&traf->child_boxes, (GF_Box*)traf->sdtp);
traf->sdtp = NULL;
}
}
}

void
send_dual_packets(tcpreplay_t *ctx, pcap_t *pcap1, int cache_file_idx1, pcap_t *pcap2, int cache_file_idx2)
{
struct timeval print_delta, now, last_pkt_ts;
tcpreplay_opt_t *options = ctx->options;
tcpreplay_stats_t *stats = &ctx->stats;
COUNTER packetnum = 0;
COUNTER limit_send = options->limit_send;
int cache_file_idx;
struct pcap_pkthdr pkthdr1, pkthdr2;
u_char *pktdata1 = NULL, *pktdata2 = NULL, *pktdata = NULL;
sendpacket_t *sp;
COUNTER pktlen;
packet_cache_t *cached_packet1 = NULL, *cached_packet2 = NULL;
packet_cache_t **prev_packet1 = NULL, **prev_packet2 = NULL;
struct pcap_pkthdr *pkthdr_ptr;
int datalink;
COUNTER end_us;
COUNTER skip_length = 0;
bool top_speed = (options->speed.mode == speed_topspeed ||
(options->speed.mode == speed_mbpsrate && options->speed.speed == 0));
bool now_is_now = true;
gettimeofday(&now, NULL);
if (!timerisset(&stats->start_time)) {
TIMEVAL_SET(&stats->start_time, &now);
if (ctx->options->stats >= 0) {
char buf[64];
if (format_date_time(&stats->start_time, buf, sizeof(buf)) > 0)
printf("Dual test start: %s ...\n", buf);
}
}
ctx->skip_packets = 0;
timerclear(&last_pkt_ts);
if (options->limit_time > 0)
end_us = TIMEVAL_TO_MICROSEC(&stats->start_time) +
SEC_TO_MICROSEC(options->limit_time);
else
end_us = 0;
if (options->preload_pcap) {
prev_packet1 = &cached_packet1;
prev_packet2 = &cached_packet2;
} else {
prev_packet1 = NULL;
prev_packet2 = NULL;
}
pktdata1 = get_next_packet(ctx, pcap1, &pkthdr1, cache_file_idx1, prev_packet1);
pktdata2 = get_next_packet(ctx, pcap2, &pkthdr2, cache_file_idx2, prev_packet2);
while (!ctx->abort &&
!(pktdata1 == NULL && pktdata2 == NULL)) {
now_is_now = false;
packetnum++;
if (pktdata1 == NULL) {
sp = ctx->intf2;
datalink = options->file_cache[cache_file_idx2].dlt;
pkthdr_ptr = &pkthdr2;
cache_file_idx = cache_file_idx2;
pktdata = pktdata2;
} else if (pktdata2 == NULL) {
sp = ctx->intf1;
datalink = options->file_cache[cache_file_idx1].dlt;
pkthdr_ptr = &pkthdr1;
cache_file_idx = cache_file_idx1;
pktdata = pktdata1;
} else if (timercmp(&pkthdr1.ts, &pkthdr2.ts, <=)) {
sp = ctx->intf1;
datalink = options->file_cache[cache_file_idx1].dlt;
pkthdr_ptr = &pkthdr1;
cache_file_idx = cache_file_idx1;
pktdata = pktdata1;
} else {
sp = ctx->intf2;
datalink = options->file_cache[cache_file_idx2].dlt;
pkthdr_ptr = &pkthdr2;
cache_file_idx = cache_file_idx2;
pktdata = pktdata2;
}
#if defined TCPREPLAY || defined TCPREPLAY_EDIT
pktlen = options->use_pkthdr_len ? (COUNTER)pkthdr_ptr->len : (COUNTER)pkthdr_ptr->caplen;
#elif TCPBRIDGE
pktlen = (COUNTER)pkthdr_ptr->caplen;
#else
#error WTF???  We should not be here!
#endif
dbgx(2, "packet " COUNTER_SPEC " caplen " COUNTER_SPEC, packetnum, pktlen);
#if defined TCPREPLAY && defined TCPREPLAY_EDIT
if (tcpedit_packet(tcpedit, &pkthdr_ptr, &pktdata, sp->cache_dir) == -1) {
errx(-1, "Error editing packet #" COUNTER_SPEC ": %s", packetnum, tcpedit_geterr(tcpedit));
}
pktlen = options->use_pkthdr_len ? (COUNTER)pkthdr_ptr->len : (COUNTER)pkthdr_ptr->caplen;
#endif
if (ctx->options->unique_ip && ctx->unique_iteration &&
ctx->unique_iteration > ctx->last_unique_iteration) {
fast_edit_packet(pkthdr_ptr, &pktdata, ctx->unique_iteration - 1,
options->file_cache[cache_file_idx].cached, datalink);
}
if (options->flow_stats && !options->file_cache[cache_file_idx].cached)
update_flow_stats(ctx, sp, pkthdr_ptr, pktdata, datalink);
if (skip_length && pktlen < skip_length) {
skip_length -= pktlen;
} else if (ctx->skip_packets) {
--ctx->skip_packets;
} else {
dbgx(4, "This packet time: " TIMEVAL_FORMAT, pkthdr_ptr->ts.tv_sec,
pkthdr_ptr->ts.tv_usec);
skip_length = 0;
ctx->skip_packets = 0;
if (options->speed.mode == speed_multiplier) {
if (!timerisset(&last_pkt_ts)) {
TIMEVAL_SET(&last_pkt_ts, &pkthdr_ptr->ts);
} else if (timercmp(&pkthdr_ptr->ts, &last_pkt_ts, >)) {
struct timeval delta;
timersub(&pkthdr_ptr->ts, &last_pkt_ts, &delta);
timeradd(&stats->pkt_ts_delta, &delta, &stats->pkt_ts_delta);
TIMEVAL_SET(&last_pkt_ts, &pkthdr_ptr->ts);
}
if (!timerisset(&stats->time_delta))
TIMEVAL_SET(&stats->pkt_ts_delta, &stats->pkt_ts_delta);
}
if (!top_speed) {
gettimeofday(&now, NULL);
now_is_now = true;
}
calc_sleep_time(ctx, &stats->pkt_ts_delta, &stats->time_delta,
pktlen, sp, packetnum, &stats->end_time,
TIMEVAL_TO_MICROSEC(&stats->start_time), &skip_length);
if (timercmp(&stats->time_delta, &stats->pkt_ts_delta, <))
TIMEVAL_SET(&stats->time_delta, &stats->pkt_ts_delta);
if (!top_speed)
tcpr_sleep(ctx, sp, &ctx->nap, &now);
}
#ifdef ENABLE_VERBOSE
if (options->verbose)
tcpdump_print(options->tcpdump, pkthdr_ptr, pktdata);
#endif
dbgx(2, "Sending packet #" COUNTER_SPEC, packetnum);
if (sendpacket(sp, pktdata, pktlen, pkthdr_ptr) < (int)pktlen) {
warnx("Unable to send packet: %s", sendpacket_geterr(sp));
break;
}
TIMEVAL_SET(&stats->end_time, &now);
stats->pkts_sent++;
stats->bytes_sent += pktlen;
if (options->stats > 0) {
if (! timerisset(&stats->last_print)) {
TIMEVAL_SET(&stats->last_print, &now);
} else {
timersub(&now, &stats->last_print, &print_delta);
if (print_delta.tv_sec >= options->stats) {
TIMEVAL_SET(&stats->end_time, &now);
packet_stats(stats);
TIMEVAL_SET(&stats->last_print, &now);
}
}
}
#if defined HAVE_NETMAP
if (sp->first_packet || timesisset(&ctx->nap)) {
wake_send_queues(sp, options);
sp->first_packet = false;
}
#endif
if (sp == ctx->intf2) {
pktdata2 = get_next_packet(ctx, pcap2, &pkthdr2, cache_file_idx2, prev_packet2);
} else {
pktdata1 = get_next_packet(ctx, pcap1, &pkthdr1, cache_file_idx1, prev_packet1);
}
if ((end_us > 0 && (COUNTER)TIMEVAL_TO_MICROSEC(&now) > end_us) ||
(limit_send > 0 && stats->pkts_sent >= limit_send)) {
ctx->abort = true;
}
} 
#ifdef HAVE_NETMAP
if (options->netmap && (ctx->abort || options->loop == 1)) {
while (ctx->intf1 && !netmap_tx_queues_empty(ctx->intf1)) {
gettimeofday(&now, NULL);
now_is_now = true;
}
while (ctx->intf2 && !netmap_tx_queues_empty(ctx->intf2)) {
gettimeofday(&now, NULL);
now_is_now = true;
}
}
#endif 
if (!now_is_now)
gettimeofday(&now, NULL);
TIMEVAL_SET(&stats->end_time, &now);
increment_iteration(ctx);
}

static struct ext4_dir_entry_2 *do_split(handle_t *handle, struct inode *dir,
struct buffer_head **bh,struct dx_frame *frame,
struct dx_hash_info *hinfo)
{
unsigned blocksize = dir->i_sb->s_blocksize;
unsigned count, continued;
struct buffer_head *bh2;
ext4_lblk_t newblock;
u32 hash2;
struct dx_map_entry *map;
char *data1 = (*bh)->b_data, *data2;
unsigned split, move, size;
struct ext4_dir_entry_2 *de = NULL, *de2;
intcsum_size = 0;
interr = 0, i;
if (ext4_has_metadata_csum(dir->i_sb))
csum_size = sizeof(struct ext4_dir_entry_tail);
bh2 = ext4_append(handle, dir, &newblock);
if (IS_ERR(bh2)) {
brelse(*bh);
*bh = NULL;
return (struct ext4_dir_entry_2 *) bh2;
}
BUFFER_TRACE(*bh, "get_write_access");
err = ext4_journal_get_write_access(handle, *bh);
if (err)
goto journal_error;
BUFFER_TRACE(frame->bh, "get_write_access");
err = ext4_journal_get_write_access(handle, frame->bh);
if (err)
goto journal_error;
data2 = bh2->b_data;
map = (struct dx_map_entry *) (data2 + blocksize);
count = dx_make_map(dir, (struct ext4_dir_entry_2 *) data1,
blocksize, hinfo, map);
map -= count;
dx_sort_map(map, count);
size = 0;
move = 0;
for (i = count-1; i >= 0; i--) {
if (size + map[i].size/2 > blocksize/2)
break;
size += map[i].size;
move++;
}
split = count - move;
hash2 = map[split].hash;
continued = hash2 == map[split - 1].hash;
dxtrace(printk(KERN_INFO "Split block %lu at %x, %i/%i\n",
(unsigned long)dx_get_block(frame->at),
hash2, split, count-split));
de2 = dx_move_dirents(data1, data2, map + split, count - split,
blocksize);
de = dx_pack_dirents(data1, blocksize);
de->rec_len = ext4_rec_len_to_disk(data1 + (blocksize - csum_size) -
(char *) de,
blocksize);
de2->rec_len = ext4_rec_len_to_disk(data2 + (blocksize - csum_size) -
(char *) de2,
blocksize);
if (csum_size) {
ext4_initialize_dirent_tail(*bh, blocksize);
ext4_initialize_dirent_tail(bh2, blocksize);
}
dxtrace(dx_show_leaf(dir, hinfo, (struct ext4_dir_entry_2 *) data1,
blocksize, 1));
dxtrace(dx_show_leaf(dir, hinfo, (struct ext4_dir_entry_2 *) data2,
blocksize, 1));
if (hinfo->hash >= hash2) {
swap(*bh, bh2);
de = de2;
}
dx_insert_block(frame, hash2 + continued, newblock);
err = ext4_handle_dirty_dirblock(handle, dir, bh2);
if (err)
goto journal_error;
err = ext4_handle_dirty_dx_node(handle, dir, frame->bh);
if (err)
goto journal_error;
brelse(bh2);
dxtrace(dx_show_index("frame", frame->entries));
return de;
journal_error:
brelse(*bh);
brelse(bh2);
*bh = NULL;
ext4_std_error(dir->i_sb, err);
return ERR_PTR(err);
}

static int dissect_tsdns(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void* data _U_)
{
int         offset    = 0;
gboolean    request   = FALSE;
if (pinfo->destport == pinfo->match_uint) {
request = TRUE;
}
col_set_str(pinfo->cinfo, COL_PROTOCOL, "TSDNS");
int pLen = tvb_reported_length(tvb);
if (request) {
col_set_str(pinfo->cinfo, COL_INFO, "Request");
col_append_fstr(pinfo->cinfo, COL_INFO, " %.*s", pLen - 5, tvb_get_string_enc(wmem_packet_scope(), tvb, 0, pLen - 5, ENC_ASCII|ENC_NA));
} else {
col_set_str(pinfo->cinfo, COL_INFO, "Response");
col_append_fstr(pinfo->cinfo, COL_INFO, " %.*s", pLen, tvb_get_string_enc(wmem_packet_scope(), tvb, 0, pLen, ENC_ASCII|ENC_NA));
}
proto_tree *tsdns_tree;
proto_item *ti, *hidden_item, *address_item;
ti = proto_tree_add_item(tree, proto_tsdns, tvb, offset, -1, ENC_NA);
tsdns_tree = proto_item_add_subtree(ti, ett_tsdns);
hidden_item = proto_tree_add_item(tsdns_tree, hf_tsdns_data, tvb, offset, -1, ENC_ASCII|ENC_NA);
PROTO_ITEM_SET_HIDDEN(hidden_item);
if (request) {     hidden_item = proto_tree_add_boolean(tsdns_tree, hf_tsdns_request, tvb, 0, 0, 1);     proto_tree_add_item(tsdns_tree, hf_tsdns_request_domain, tvb, offset, pLen - 5, ENC_ASCII|ENC_NA);
} else {     hidden_item = proto_tree_add_boolean(tsdns_tree, hf_tsdns_response, tvb, 0, 0, 1);
address_item = proto_tree_add_item(tsdns_tree, hf_tsdns_response_address, tvb, offset, pLen, ENC_ASCII|ENC_NA);
gchar** splitAddress;
splitAddress = wmem_strsplit(wmem_packet_scope(), tvb_format_text(tvb, 0, pLen), ":", 1);     if (splitAddress[1] == NULL) {
expert_add_info(pinfo, address_item, &ei_response_port_malformed);
} else {
proto_tree_add_string(tsdns_tree, hf_tsdns_response_ip, tvb, 0, pLen, splitAddress[0]);
guint32 port;
if (ws_strtou32(splitAddress[1], NULL, &port))
proto_tree_add_uint(tsdns_tree, hf_tsdns_response_port, tvb, 0, pLen, port);
}
}
PROTO_ITEM_SET_HIDDEN(hidden_item);
return tvb_captured_length(tvb);
}

