int rsa_verify_hash_ex(const unsigned char *sig,      unsigned long siglen,
const unsigned char *hash,     unsigned long hashlen,
int            padding,
int            hash_idx, unsigned long saltlen,
int           *stat,     rsa_key      *key)
{
unsigned long modulus_bitlen, modulus_bytelen, x;
int           err;
unsigned char *tmpbuf;
LTC_ARGCHK(hash  != NULL);
LTC_ARGCHK(sig   != NULL);
LTC_ARGCHK(stat  != NULL);
LTC_ARGCHK(key   != NULL);
*stat = 0;
if ((padding != LTC_PKCS_1_V1_5) &&
(padding != LTC_PKCS_1_PSS)) {
return CRYPT_PK_INVALID_PADDING;
}
if (padding == LTC_PKCS_1_PSS) {
if ((err = hash_is_valid(hash_idx)) != CRYPT_OK) {
return err;
}
}
modulus_bitlen = mp_count_bits( (key->N));
modulus_bytelen = mp_unsigned_bin_size( (key->N));
if (modulus_bytelen != siglen) {
return CRYPT_INVALID_PACKET;
}
tmpbuf = XMALLOC(siglen);
if (tmpbuf == NULL) {
return CRYPT_MEM;
}
x = siglen;
if ((err = ltc_mp.rsa_me(sig, siglen, tmpbuf, &x, PK_PUBLIC, key)) != CRYPT_OK) {
XFREE(tmpbuf);
return err;
}
if (x != siglen) {
XFREE(tmpbuf);
return CRYPT_INVALID_PACKET;
}
if (padding == LTC_PKCS_1_PSS) {
if(modulus_bitlen%8 == 1){
err = pkcs_1_pss_decode(hash, hashlen, tmpbuf+1, x-1, saltlen, hash_idx, modulus_bitlen, stat);
}
else{
err = pkcs_1_pss_decode(hash, hashlen, tmpbuf, x, saltlen, hash_idx, modulus_bitlen, stat);
}
} else {
unsigned char *out;
unsigned long outlen, loid[16];
int           decoded;
ltc_asn1_list digestinfo[2], siginfo[2];
if (hash_descriptor[hash_idx].OIDlen == 0) {
err = CRYPT_INVALID_ARG;
goto bail_2;
}
outlen = ((modulus_bitlen >> 3) + (modulus_bitlen & 7 ? 1 : 0)) - 3;
out    = XMALLOC(outlen);
if (out == NULL) {
err = CRYPT_MEM;
goto bail_2;
}
if ((err = pkcs_1_v1_5_decode(tmpbuf, x, LTC_PKCS_1_EMSA, modulus_bitlen, out, &outlen, &decoded)) != CRYPT_OK) {
XFREE(out);
goto bail_2;
}
LTC_SET_ASN1(digestinfo, 0, LTC_ASN1_OBJECT_IDENTIFIER, loid, sizeof(loid)/sizeof(loid[0]));
LTC_SET_ASN1(digestinfo, 1, LTC_ASN1_NULL,              NULL,                          0);
LTC_SET_ASN1(siginfo,    0, LTC_ASN1_SEQUENCE,          digestinfo,                    2);
LTC_SET_ASN1(siginfo,    1, LTC_ASN1_OCTET_STRING,      tmpbuf,                        siglen);
if ((err = der_decode_sequence(out, outlen, siginfo, 2)) != CRYPT_OK) {
XFREE(out);
goto bail_2;
}
if ((digestinfo[0].size == hash_descriptor[hash_idx].OIDlen) &&
(XMEMCMP(digestinfo[0].data, hash_descriptor[hash_idx].OID, sizeof(unsigned long) * hash_descriptor[hash_idx].OIDlen) == 0) &&
(siginfo[1].size == hashlen) &&
(XMEMCMP(siginfo[1].data, hash, hashlen) == 0)) {
*stat = 1;
}
#ifdef LTC_CLEAN_STACK
zeromem(out, outlen);
#endif
XFREE(out);
}
bail_2:
#ifdef LTC_CLEAN_STACK
zeromem(tmpbuf, siglen);
#endif
XFREE(tmpbuf);
return err;
}

int hsr_dev_finalize(struct net_device *hsr_dev, struct net_device *slave[2],
unsigned char multicast_spec, u8 protocol_version)
{
struct hsr_priv *hsr;
struct hsr_port *port;
int res;
hsr = netdev_priv(hsr_dev);
INIT_LIST_HEAD(&hsr->ports);
INIT_LIST_HEAD(&hsr->node_db);
INIT_LIST_HEAD(&hsr->self_node_db);
ether_addr_copy(hsr_dev->dev_addr, slave[0]->dev_addr);
res = hsr_create_self_node(&hsr->self_node_db, hsr_dev->dev_addr,
slave[1]->dev_addr);
if (res < 0)
return res;
spin_lock_init(&hsr->seqnr_lock);
hsr->sequence_nr = HSR_SEQNR_START;
hsr->sup_sequence_nr = HSR_SUP_SEQNR_START;
timer_setup(&hsr->announce_timer, hsr_announce, 0);
timer_setup(&hsr->prune_timer, hsr_prune_nodes, 0);
ether_addr_copy(hsr->sup_multicast_addr, def_multicast_addr);
hsr->sup_multicast_addr[ETH_ALEN - 1] = multicast_spec;
hsr->protVersion = protocol_version;
netif_carrier_off(hsr_dev);
res = hsr_add_port(hsr, hsr_dev, HSR_PT_MASTER);
if (res)
return res;
res = register_netdevice(hsr_dev);
if (res)
goto fail;
res = hsr_add_port(hsr, slave[0], HSR_PT_SLAVE_A);
if (res)
goto fail;
res = hsr_add_port(hsr, slave[1], HSR_PT_SLAVE_B);
if (res)
goto fail;
mod_timer(&hsr->prune_timer, jiffies + msecs_to_jiffies(PRUNE_PERIOD));
return 0;
fail:
hsr_for_each_port(hsr, port)
hsr_del_port(port);
return res;
}

GF_EXPORT
GF_Descriptor *gf_isom_get_root_od(GF_ISOFile *movie)
{
GF_Descriptor *desc;
GF_ObjectDescriptor *od;
GF_InitialObjectDescriptor *iod;
GF_IsomObjectDescriptor *isom_od;
GF_IsomInitialObjectDescriptor *isom_iod;
GF_ESD *esd;
GF_ES_ID_Inc *inc;
u32 i;
u8 useIOD;
if (!movie || !movie->moov) return NULL;
if (!movie->moov->iods) return NULL;
if (movie->disable_odf_translate) {
movie->LastError = gf_odf_desc_copy((GF_Descriptor *) movie->moov->iods->descriptor, &desc);
if (movie->LastError) return NULL;
return desc;
}
od = NULL;
iod = NULL;
switch (movie->moov->iods->descriptor->tag) {
case GF_ODF_ISOM_OD_TAG:
od = (GF_ObjectDescriptor*)gf_malloc(sizeof(GF_ObjectDescriptor));
if (!od) return NULL;
memset(od, 0, sizeof(GF_ObjectDescriptor));
od->ESDescriptors = gf_list_new();
useIOD = 0;
break;
case GF_ODF_ISOM_IOD_TAG:
iod = (GF_InitialObjectDescriptor*)gf_malloc(sizeof(GF_InitialObjectDescriptor));
if (!iod) return NULL;
memset(iod, 0, sizeof(GF_InitialObjectDescriptor));
iod->ESDescriptors = gf_list_new();
useIOD = 1;
break;
default:
return NULL;
}
movie->LastError = gf_odf_desc_copy((GF_Descriptor *) movie->moov->iods->descriptor, &desc);
if (movie->LastError) return NULL;
if (!useIOD) {
isom_od = (GF_IsomObjectDescriptor *)desc;
od->objectDescriptorID = isom_od->objectDescriptorID;
od->extensionDescriptors = isom_od->extensionDescriptors;
isom_od->extensionDescriptors = NULL;
od->IPMP_Descriptors = isom_od->IPMP_Descriptors;
isom_od->IPMP_Descriptors = NULL;
od->OCIDescriptors = isom_od->OCIDescriptors;
isom_od->OCIDescriptors = NULL;
od->URLString = isom_od->URLString;
isom_od->URLString = NULL;
od->tag = GF_ODF_OD_TAG;
i=0;
while ((inc = (GF_ES_ID_Inc*)gf_list_enum(isom_od->ES_ID_IncDescriptors, &i))) {
movie->LastError = GetESDForTime(movie->moov, inc->trackID, 0, &esd);
if (!movie->LastError) movie->LastError = gf_list_add(od->ESDescriptors, esd);
if (movie->LastError) {
gf_odf_desc_del(desc);
gf_odf_desc_del((GF_Descriptor *) od);
return NULL;
}
}
gf_odf_desc_del(desc);
return (GF_Descriptor *)od;
} else {
isom_iod = (GF_IsomInitialObjectDescriptor *)desc;
iod->objectDescriptorID = isom_iod->objectDescriptorID;
iod->extensionDescriptors = isom_iod->extensionDescriptors;
isom_iod->extensionDescriptors = NULL;
iod->IPMP_Descriptors = isom_iod->IPMP_Descriptors;
isom_iod->IPMP_Descriptors = NULL;
iod->OCIDescriptors = isom_iod->OCIDescriptors;
isom_iod->OCIDescriptors = NULL;
iod->URLString = isom_iod->URLString;
isom_iod->URLString = NULL;
iod->tag = GF_ODF_IOD_TAG;
iod->audio_profileAndLevel = isom_iod->audio_profileAndLevel;
iod->graphics_profileAndLevel = isom_iod->graphics_profileAndLevel;
iod->inlineProfileFlag = isom_iod->inlineProfileFlag;
iod->OD_profileAndLevel = isom_iod->OD_profileAndLevel;
iod->scene_profileAndLevel = isom_iod->scene_profileAndLevel;
iod->visual_profileAndLevel = isom_iod->visual_profileAndLevel;
iod->IPMPToolList = isom_iod->IPMPToolList;
isom_iod->IPMPToolList = NULL;
i=0;
while ((inc = (GF_ES_ID_Inc*)gf_list_enum(isom_iod->ES_ID_IncDescriptors, &i))) {
movie->LastError = GetESDForTime(movie->moov, inc->trackID, 0, &esd);
if (!movie->LastError) movie->LastError = gf_list_add(iod->ESDescriptors, esd);
if (movie->LastError) {
gf_odf_desc_del(desc);
gf_odf_desc_del((GF_Descriptor *) iod);
return NULL;
}
}
gf_odf_desc_del(desc);
return (GF_Descriptor *)iod;
}
}

static UINT drdynvc_process_capability_request(drdynvcPlugin* drdynvc, int Sp,
int cbChId, wStream* s)
{
UINT status;
if (!drdynvc)
return CHANNEL_RC_BAD_INIT_HANDLE;
WLog_Print(drdynvc->log, WLOG_TRACE, "capability_request Sp=%d cbChId=%d", Sp, cbChId);
Stream_Seek(s, 1); 
Stream_Read_UINT16(s, drdynvc->version);
if ((drdynvc->version == 2) || (drdynvc->version == 3))
{
Stream_Read_UINT16(s, drdynvc->PriorityCharge0);
Stream_Read_UINT16(s, drdynvc->PriorityCharge1);
Stream_Read_UINT16(s, drdynvc->PriorityCharge2);
Stream_Read_UINT16(s, drdynvc->PriorityCharge3);
}
status = drdynvc_send_capability_response(drdynvc);
drdynvc->state = DRDYNVC_STATE_READY;
return status;
}

static void m2tsdmx_declare_pid(GF_M2TSDmxCtx *ctx, GF_M2TS_PES *stream, GF_ESD *esd)
{
u32 i, count, codecid=0, stype=0, orig_stype=0;
GF_FilterPid *opid;
Bool m4sys_stream = GF_FALSE;
Bool m4sys_iod_stream = GF_FALSE;
Bool has_scal_layer = GF_FALSE;
Bool unframed = GF_FALSE;
Bool unframed_latm = GF_FALSE;
char szName[20];
const char *stname;
if (stream->user) return;
if (stream->flags & GF_M2TS_GPAC_CODEC_ID) {
codecid = stream->stream_type;
stype = gf_codecid_type(codecid);
if (stream->gpac_meta_dsi)
stype = stream->gpac_meta_dsi[4];
if (!stype) {
GF_LOG(GF_LOG_WARNING, GF_LOG_CONTAINER, ("[M2TSDmx] Unrecognized gpac codec %s - ignoring pid\n", gf_4cc_to_str(codecid) ));
return;
}
} else {
switch (stream->stream_type) {
case GF_M2TS_VIDEO_MPEG1:
stype = GF_STREAM_VISUAL;
codecid = GF_CODECID_MPEG1;
unframed = GF_TRUE;
break;
case GF_M2TS_VIDEO_MPEG2:
case GF_M2TS_VIDEO_DCII:
stype = GF_STREAM_VISUAL;
codecid = GF_CODECID_MPEG2_MAIN;
unframed = GF_TRUE;
break;
case GF_M2TS_VIDEO_MPEG4:
stype = GF_STREAM_VISUAL;
codecid = GF_CODECID_MPEG4_PART2;
unframed = GF_TRUE;
break;
case GF_M2TS_VIDEO_H264:
stype = GF_STREAM_VISUAL;
codecid = GF_CODECID_AVC;
unframed = GF_TRUE;
if (stream->program->is_scalable)
has_scal_layer = GF_TRUE;
break;
case GF_M2TS_HLS_AVC_CRYPT:
stype = GF_STREAM_ENCRYPTED;
orig_stype = GF_STREAM_VISUAL;
codecid = GF_CODECID_AVC;
unframed = GF_TRUE;
break;
case GF_M2TS_VIDEO_SVC:
stype = GF_STREAM_VISUAL;
codecid = GF_CODECID_SVC;
has_scal_layer = GF_TRUE;
unframed = GF_TRUE;
break;
case GF_M2TS_VIDEO_HEVC:
case GF_M2TS_VIDEO_HEVC_TEMPORAL:
case GF_M2TS_VIDEO_HEVC_MCTS:
stype = GF_STREAM_VISUAL;
codecid = GF_CODECID_HEVC;
unframed = GF_TRUE;
if (stream->program->is_scalable)
has_scal_layer = GF_TRUE;
break;
case GF_M2TS_VIDEO_SHVC:
case GF_M2TS_VIDEO_SHVC_TEMPORAL:
case GF_M2TS_VIDEO_MHVC:
case GF_M2TS_VIDEO_MHVC_TEMPORAL:
stype = GF_STREAM_VISUAL;
codecid = GF_CODECID_LHVC;
has_scal_layer = GF_TRUE;
break;
case GF_M2TS_VIDEO_VVC:
case GF_M2TS_VIDEO_VVC_TEMPORAL:
stype = GF_STREAM_VISUAL;
codecid = GF_CODECID_VVC;
unframed = GF_TRUE;
break;
case GF_M2TS_VIDEO_VC1:
stype = GF_STREAM_VISUAL;
codecid = GF_CODECID_SMPTE_VC1;
stream->flags |= GF_M2TS_CHECK_VC1;
break;
case GF_M2TS_VIDEO_AV1:
stype = GF_STREAM_VISUAL;
codecid = GF_CODECID_AV1;
unframed = GF_TRUE;
break;
case GF_M2TS_AUDIO_MPEG1:
stype = GF_STREAM_AUDIO;
codecid = GF_CODECID_MPEG_AUDIO;
unframed = GF_TRUE;
break;
case GF_M2TS_AUDIO_MPEG2:
stype = GF_STREAM_AUDIO;
codecid = GF_CODECID_MPEG2_PART3;
unframed = GF_TRUE;
break;
case GF_M2TS_AUDIO_AAC:
case GF_CODECID_AAC_MPEG2_MP:
case GF_CODECID_AAC_MPEG2_LCP:
case GF_CODECID_AAC_MPEG2_SSRP:
stype = GF_STREAM_AUDIO;
codecid = GF_CODECID_AAC_MPEG4;
unframed = GF_TRUE;
break;
case GF_M2TS_AUDIO_LATM_AAC:
stype = GF_STREAM_AUDIO;
codecid = GF_CODECID_AAC_MPEG4;
unframed = GF_TRUE;
unframed_latm = GF_TRUE;
break;
case GF_M2TS_MHAS_MAIN:
case GF_M2TS_MHAS_AUX:
stype = GF_STREAM_AUDIO;
codecid = GF_CODECID_MHAS;
unframed = GF_TRUE;
break;
case GF_M2TS_AUDIO_AC3:
stype = GF_STREAM_AUDIO;
codecid = GF_CODECID_AC3;
unframed = GF_TRUE;
break;
case GF_M2TS_AUDIO_EC3:
stype = GF_STREAM_AUDIO;
codecid = GF_CODECID_EAC3;
unframed = GF_TRUE;
break;
case GF_M2TS_AUDIO_TRUEHD:
stype = GF_STREAM_AUDIO;
codecid = GF_CODECID_TRUEHD;
unframed = GF_TRUE;
break;
case GF_M2TS_AUDIO_DTS:
stype = GF_STREAM_AUDIO;
codecid = GF_CODECID_DTS_X;
break;
case GF_M2TS_AUDIO_OPUS:
stype = GF_STREAM_AUDIO;
codecid = GF_CODECID_OPUS;
break;
case GF_M2TS_SYSTEMS_MPEG4_SECTIONS:
((GF_M2TS_ES*)stream)->flags |= GF_M2TS_ES_SEND_REPEATED_SECTIONS;
case GF_M2TS_SYSTEMS_MPEG4_PES:
if (!esd) {
m4sys_iod_stream = GF_TRUE;
count = gf_list_count(stream->program->pmt_iod->ESDescriptors);
for (i=0; i<count; i++) {
esd = gf_list_get(stream->program->pmt_iod->ESDescriptors, i);
if (esd->ESID == stream->mpeg4_es_id) break;
esd = NULL;
}
}
m4sys_stream = GF_TRUE;
if (!esd) return;
break;
case GF_M2TS_METADATA_PES:
case GF_M2TS_METADATA_ID3_HLS:
stype = GF_STREAM_METADATA;
codecid = GF_CODECID_SIMPLE_TEXT;
break;
case 0xA1:
stype = GF_STREAM_AUDIO;
codecid = GF_CODECID_EAC3;
break;
case GF_M2TS_HLS_AAC_CRYPT:
stype = GF_STREAM_ENCRYPTED;
orig_stype = GF_STREAM_AUDIO;
codecid = GF_CODECID_AAC_MPEG4;
unframed = GF_TRUE;
break;
case GF_M2TS_HLS_AC3_CRYPT:
stype = GF_STREAM_ENCRYPTED;
orig_stype = GF_STREAM_AUDIO;
codecid = GF_CODECID_AC3;
unframed = GF_TRUE;
break;
case GF_M2TS_HLS_EC3_CRYPT:
stype = GF_STREAM_ENCRYPTED;
orig_stype = GF_STREAM_AUDIO;
codecid = GF_CODECID_EAC3;
break;
case GF_M2TS_DVB_SUBTITLE:
stype = GF_STREAM_TEXT;
codecid = GF_CODECID_DVB_SUBS;
stream->flags |= GF_M2TS_ES_FULL_AU;
break;
case GF_M2TS_DVB_TELETEXT:
if (!ctx->dvbtxt) {
GF_LOG(GF_LOG_WARNING, GF_LOG_CONTAINER, ("[M2TSDmx] DVB teletext pid skipped, use --dvbtxt to enable\n", stream->stream_type));
return;
}
stype = GF_STREAM_TEXT;
codecid = GF_CODECID_DVB_TELETEXT;
stream->flags |= GF_M2TS_ES_FULL_AU;
break;
default:
GF_LOG(GF_LOG_WARNING, GF_LOG_CONTAINER, ("[M2TSDmx] Stream type 0x%02X not supported - ignoring pid\n", stream->stream_type));
return;
}
}
opid = NULL;
for (i=0; i<gf_filter_get_opid_count(ctx->filter); i++) {
opid = gf_filter_get_opid(ctx->filter, i);
const GF_PropertyValue *p = gf_filter_pid_get_property(opid, GF_PROP_PID_ID);
if (p && (p->value.uint == stream->pid))
break;
opid = NULL;
}
if (!opid)
opid = gf_filter_pid_new(ctx->filter);
stream->user = opid;
stream->flags |= GF_M2TS_ES_ALREADY_DECLARED;
u32 d_type = orig_stype ? orig_stype : stype;
switch (d_type) {
case GF_STREAM_AUDIO:
case GF_STREAM_VISUAL:
stream->flags |= GF_M2TS_CHECK_DISC;
break;
default:
stream->flags &= ~GF_M2TS_CHECK_DISC;
break;
}
stname = gf_stream_type_name(stype);
sprintf(szName, "P%d%c%d", stream->program->number, stname[0], 1+gf_list_find(stream->program->streams, stream));
gf_filter_pid_set_name(opid, szName);
gf_filter_pid_set_property(opid, GF_PROP_PID_ID, &PROP_UINT(stream->pid) );
gf_filter_pid_set_property(opid, GF_PROP_PID_ESID, stream->mpeg4_es_id ? &PROP_UINT(stream->mpeg4_es_id) : NULL);
if (m4sys_stream) {
if (stream->slcfg) gf_free(stream->slcfg);
stream->slcfg = esd->slConfig;
esd->slConfig = NULL;
gf_filter_pid_set_property(opid, GF_PROP_PID_STREAM_TYPE, &PROP_UINT(esd->decoderConfig ? esd->decoderConfig->streamType : GF_STREAM_SCENE) );
gf_filter_pid_set_property(opid, GF_PROP_PID_CODECID, &PROP_UINT(esd->decoderConfig ? esd->decoderConfig->objectTypeIndication : GF_CODECID_BIFS) );
gf_filter_pid_set_property(opid, GF_PROP_PID_CLOCK_ID, &PROP_UINT(esd->OCRESID ? esd->OCRESID : esd->ESID) );
gf_filter_pid_set_property(opid, GF_PROP_PID_DEPENDENCY_ID, &PROP_UINT(esd->dependsOnESID) );
if (esd->decoderConfig && esd->decoderConfig->decoderSpecificInfo  && esd->decoderConfig->decoderSpecificInfo->dataLength)
gf_filter_pid_set_property(opid, GF_PROP_PID_DECODER_CONFIG, &PROP_DATA(esd->decoderConfig->decoderSpecificInfo->data, esd->decoderConfig->decoderSpecificInfo->dataLength) );
gf_filter_pid_set_property(opid, GF_PROP_PID_IN_IOD, &PROP_BOOL(m4sys_iod_stream) );
gf_filter_pid_set_property(opid, GF_PROP_PID_TIMESCALE, &PROP_UINT(((GF_M2TS_ES*)stream)->slcfg->timestampResolution) );
if (esd->decoderConfig && (esd->decoderConfig->streamType==GF_STREAM_OD))
stream->flags |= GF_M2TS_ES_IS_MPEG4_OD;
} else {
gf_filter_pid_set_property(opid, GF_PROP_PID_STREAM_TYPE, &PROP_UINT(stype) );
gf_filter_pid_set_property(opid, GF_PROP_PID_CODECID, &PROP_UINT(codecid) );
gf_filter_pid_set_property(opid, GF_PROP_PID_UNFRAMED, unframed ? &PROP_BOOL(GF_TRUE) : NULL);
gf_filter_pid_set_property(opid, GF_PROP_PID_UNFRAMED_LATM, unframed_latm ? &PROP_BOOL(GF_TRUE) : NULL );
if (orig_stype) {
gf_filter_pid_set_property(opid, GF_PROP_PID_ORIG_STREAM_TYPE, &PROP_UINT(orig_stype) );
gf_filter_pid_set_property(opid, GF_PROP_PID_PROTECTION_SCHEME_TYPE, &PROP_UINT(GF_HLS_SAMPLE_AES_SCHEME) );
} else {
gf_filter_pid_set_property(opid, GF_PROP_PID_ORIG_STREAM_TYPE, NULL);
gf_filter_pid_set_property(opid, GF_PROP_PID_PROTECTION_SCHEME_TYPE, NULL);
}
gf_filter_pid_set_property(opid, GF_PROP_PID_TIMESCALE, &PROP_UINT(90000) );
gf_filter_pid_set_property(opid, GF_PROP_PID_CLOCK_ID, &PROP_UINT(stream->program->pcr_pid) );
if (stream->gpac_meta_dsi) {
char *cname;
GF_BitStream *bs = gf_bs_new(stream->gpac_meta_dsi, stream->gpac_meta_dsi_size, GF_BITSTREAM_READ);
u32 val = gf_bs_read_u32(bs); gf_filter_pid_set_property(opid, GF_PROP_PID_CODECID, &PROP_UINT(val) );
gf_bs_read_u8(bs); gf_bs_read_u8(bs); val = gf_bs_read_u32(bs); gf_filter_pid_set_property(opid, GF_PROP_PID_META_DEMUX_CODEC_ID, &PROP_UINT(val) );
cname = gf_bs_read_utf8(bs); gf_filter_pid_set_property(opid, GF_PROP_PID_META_DEMUX_CODEC_NAME, cname ? &PROP_STRING_NO_COPY(cname) : NULL );
val = gf_bs_read_u32(bs); gf_filter_pid_set_property(opid, GF_PROP_PID_META_DEMUX_OPAQUE, &PROP_UINT(val) );
u32 dsi_len = gf_bs_read_u32(bs);
if (dsi_len) {
u32 pos = gf_bs_get_position(bs);
gf_filter_pid_set_property(opid, GF_PROP_PID_DECODER_CONFIG, &PROP_DATA(stream->gpac_meta_dsi+pos, dsi_len) );
gf_bs_skip_bytes(bs, dsi_len);
} else {
gf_filter_pid_set_property(opid, GF_PROP_PID_DECODER_CONFIG, NULL);
}
if (stype==GF_STREAM_VISUAL) {
val = gf_bs_read_u32(bs);
gf_filter_pid_set_property(opid, GF_PROP_PID_WIDTH, &PROP_UINT(val) );
val = gf_bs_read_u32(bs);
gf_filter_pid_set_property(opid, GF_PROP_PID_HEIGHT, &PROP_UINT(val) );
} else if (stype==GF_STREAM_AUDIO) {
val = gf_bs_read_u32(bs);
gf_filter_pid_set_property(opid, GF_PROP_PID_SAMPLE_RATE, &PROP_UINT(val) );
val = gf_bs_read_u32(bs);
gf_filter_pid_set_property(opid, GF_PROP_PID_NUM_CHANNELS, &PROP_UINT(val) );
}
gf_bs_del(bs);
}
}
gf_filter_pid_set_property(opid, GF_PROP_PID_SCALABLE, has_scal_layer ? &PROP_BOOL(GF_TRUE) : NULL);
gf_filter_pid_set_property(opid, GF_PROP_PID_SERVICE_ID, &PROP_UINT(stream->program->number) );
if (stream->lang) {
char szLang[4];
szLang[0] = (stream->lang>>16) & 0xFF;
szLang[1] = (stream->lang>>8) & 0xFF;
szLang[2] = stream->lang & 0xFF;
szLang[3] = 0;
if (szLang[2]==' ') szLang[2] = 0;
gf_filter_pid_set_property(opid, GF_PROP_PID_LANGUAGE, &PROP_STRING(szLang) );
}
if (codecid == GF_CODECID_DVB_SUBS) {
char szLang[4];
memcpy(szLang, stream->sub.language, 3);
szLang[3]=0;
gf_filter_pid_set_property(opid, GF_PROP_PID_LANGUAGE, &PROP_STRING(szLang) );
u8 dsi[5];
dsi[0] = stream->sub.composition_page_id>>8;
dsi[1] = stream->sub.composition_page_id & 0xFF;
dsi[2] = stream->sub.ancillary_page_id>>8;
dsi[3] = stream->sub.ancillary_page_id & 0xFF;
dsi[4] = stream->sub.type;
gf_filter_pid_set_property(opid, GF_PROP_PID_DECODER_CONFIG, &PROP_DATA(dsi, 5));
}
if (ctx->duration.num>1) {
gf_filter_pid_set_property(opid, GF_PROP_PID_DURATION, &PROP_FRAC64(ctx->duration) );
gf_filter_pid_set_property(opid, GF_PROP_PID_PLAYBACK_MODE, &PROP_UINT(GF_PLAYBACK_MODE_FASTFORWARD ) );
}
if (!m4sys_stream) {
if (stream->depends_on_pid) {
gf_filter_pid_set_property(opid, GF_PROP_PID_DEPENDENCY_ID, &PROP_UINT(stream->depends_on_pid) );
if ((stream->stream_type == GF_M2TS_VIDEO_HEVC_TEMPORAL) || (stream->stream_type == GF_M2TS_VIDEO_HEVC_MCTS)) {
gf_filter_pid_set_property(opid, GF_PROP_PID_SUBLAYER, &PROP_BOOL(GF_TRUE) );
}
} else {
gf_filter_pid_set_property(opid, GF_PROP_PID_DEPENDENCY_ID, NULL);
gf_filter_pid_set_property(opid, GF_PROP_PID_SUBLAYER, NULL);
}
}
if ((stream->flags & GF_M2TS_ES_IS_PES) && (stream->dv_info[0])) {
gf_filter_pid_set_property(opid, GF_PROP_PID_DOLBY_VISION, &PROP_DATA(stream->dv_info, 24) );
u32 dvtype=0;
if (stream->dv_info[24]) {
if (stream->stream_type == GF_M2TS_VIDEO_H264)
dvtype = GF_4CC('d','a','v','1');
else
dvtype = GF_4CC('d','v','h','1');
}
gf_filter_pid_set_property(opid, GF_PROP_PID_ISOM_SUBTYPE, dvtype ? &PROP_4CC(dvtype) : NULL);
} else {
gf_filter_pid_set_property(opid, GF_PROP_PID_DOLBY_VISION, NULL);
}
m2tsdmx_update_sdt(ctx->ts, opid);
gf_m2ts_set_pes_framing((GF_M2TS_PES *)stream, GF_M2TS_PES_FRAMING_DEFAULT);
}

static UINT serial_process_irp_create(SERIAL_DEVICE* serial, IRP* irp)
{
DWORD DesiredAccess;
DWORD SharedAccess;
DWORD CreateDisposition;
UINT32 PathLength;
if (Stream_GetRemainingLength(irp->input) < 32)
return ERROR_INVALID_DATA;
Stream_Read_UINT32(irp->input, DesiredAccess);     
Stream_Seek_UINT64(irp->input);                    
Stream_Seek_UINT32(irp->input);                    
Stream_Read_UINT32(irp->input, SharedAccess);      
Stream_Read_UINT32(irp->input, CreateDisposition); 
Stream_Seek_UINT32(irp->input);                    
Stream_Read_UINT32(irp->input, PathLength);        
if (Stream_GetRemainingLength(irp->input) < PathLength)
return ERROR_INVALID_DATA;
Stream_Seek(irp->input, PathLength); 
assert(PathLength == 0);             
#ifndef _WIN32
WLog_Print(serial->log, WLOG_DEBUG,
"DesiredAccess: 0x%" PRIX32 ", SharedAccess: 0x%" PRIX32
", CreateDisposition: 0x%" PRIX32 "",
DesiredAccess, SharedAccess, CreateDisposition);
DesiredAccess = GENERIC_READ | GENERIC_WRITE;
SharedAccess = 0;
CreateDisposition = OPEN_EXISTING;
#endif
serial->hComm =
CreateFile(serial->device.name, DesiredAccess, SharedAccess, NULL, 
CreateDisposition, 0,                                   
NULL);                                                  
if (!serial->hComm || (serial->hComm == INVALID_HANDLE_VALUE))
{
WLog_Print(serial->log, WLOG_WARN, "CreateFile failure: %s last-error: 0x%08" PRIX32 "",
serial->device.name, GetLastError());
irp->IoStatus = STATUS_UNSUCCESSFUL;
goto error_handle;
}
_comm_setServerSerialDriver(serial->hComm, serial->ServerSerialDriverId);
_comm_set_permissive(serial->hComm, serial->permissive);
assert(irp->FileId == 0);
irp->FileId = irp->devman->id_sequence++; 
irp->IoStatus = STATUS_SUCCESS;
WLog_Print(serial->log, WLOG_DEBUG, "%s (DeviceId: %" PRIu32 ", FileId: %" PRIu32 ") created.",
serial->device.name, irp->device->id, irp->FileId);
error_handle:
Stream_Write_UINT32(irp->output, irp->FileId); 
Stream_Write_UINT8(irp->output, 0);            
return CHANNEL_RC_OK;
}

static void naludmx_create_vvc_decoder_config(GF_NALUDmxCtx *ctx, u8 **dsi, u32 *dsi_size, u8 **dsi_enh, u32 *dsi_enh_size, u32 *max_width, u32 *max_height, u32 *max_enh_width, u32 *max_enh_height, GF_Fraction *sar, Bool *has_vvc_base)
{
u32 i, count;
u8 layer_id;
Bool first = GF_TRUE;
Bool first_lvvc = GF_TRUE;
GF_VVCConfig *cfg;
u32 max_w, max_h, max_ew, max_eh;
*has_vvc_base = GF_FALSE;
max_w = max_h = 0;
max_ew = max_eh = 0;
sar->num = sar->den = 0;
cfg = gf_odf_vvc_cfg_new();
cfg->nal_unit_size = ctx->nal_length;
count = gf_list_count(ctx->sps);
for (i=0; i<count; i++) {
GF_NALUFFParam *sl = gf_list_get(ctx->sps, i);
layer_id = (sl->data[0] & 0x3f);
if (!layer_id) {
*has_vvc_base = GF_TRUE;
break;
}
}
count = gf_list_count(ctx->pps);
for (i=0; i<count; i++) {
GF_NALUFFParam *sl = gf_list_get(ctx->pps, i);
layer_id = (sl->data[0] & 0x3f);
if (!layer_id) {
*has_vvc_base = GF_TRUE;
break;
}
}
count = gf_list_count(ctx->vps);
for (i=0; i<count; i++) {
GF_NALUFFParam *sl = gf_list_get(ctx->vps, i);
VVC_VPS *vps = &ctx->vvc_state->vps[sl->id];
if (!i) {
cfg->avgFrameRate = vps->rates[0].avg_pic_rate;
cfg->constantFrameRate = vps->rates[0].constant_pic_rate_idc;
cfg->numTemporalLayers = vps->max_sub_layers;
}
if (!ctx->analyze)
naludmx_add_param_nalu(cfg->param_array, sl, GF_VVC_NALU_VID_PARAM);
}
count = gf_list_count(ctx->sps);
for (i=0; i<count; i++) {
Bool is_lvvc = GF_FALSE;
GF_NALUFFParam *sl = gf_list_get(ctx->sps, i);
VVC_SPS *sps = &ctx->vvc_state->sps[sl->id];
layer_id = sl->data[0] & 0x3f;
if (!layer_id) *has_vvc_base = GF_TRUE;
if (ctx->explicit || layer_id) {
is_lvvc = GF_TRUE;
}
if (first || (is_lvvc && first_lvvc) ) {
VVC_VPS *vps = &ctx->vvc_state->vps[sps->vps_id];
cfg->avgFrameRate = 0;
cfg->constantFrameRate = 1;
cfg->numTemporalLayers = sps->max_sublayers;
cfg->nal_unit_size = ctx->nal_length;
cfg->ptl_present = vps->num_ptl ? 1 : 0;
if (vps->num_ptl) {
cfg->num_constraint_info = vps->ptl[0].gci_present ? 1 : 12;
cfg->general_profile_idc = vps->ptl[0].general_profile_idc;
cfg->general_tier_flag = vps->ptl[0].general_tier_flag;
cfg->general_level_idc = vps->ptl[0].general_level_idc;
cfg->ptl_frame_only_constraint = vps->ptl[0].frame_only_constraint;
cfg->ptl_multilayer_enabled = vps->ptl[0].multilayer_enabled;
cfg->general_constraint_info = gf_malloc(sizeof(u8) * cfg-> num_constraint_info);
if (cfg->general_constraint_info)
memcpy(cfg->general_constraint_info, vps->ptl[0].gci, cfg->num_constraint_info);
cfg->ptl_sublayer_present_mask = 0;
cfg->num_sub_profiles = 0;
cfg->ols_idx = 0;
}
cfg->chroma_format = sps->chroma_format_idc;
cfg->bit_depth = sps->bitdepth;
cfg->maxPictureWidth = sps->width;
cfg->maxPictureHeight = sps->height;
if (sps->aspect_ratio_info_present_flag && sps->sar_width && sps->sar_height) {
sar->num = sps->sar_width;
sar->den = sps->sar_height;
}
if (ctx->notime && first && (!ctx->fps.num || !ctx->fps.den) && sps->has_timing_info
&& (sps->time_scale <= 1000*sps->num_units_in_tick)
) {
ctx->cur_fps.num = sps->time_scale;
ctx->cur_fps.den = sps->num_units_in_tick;
gf_media_get_reduced_frame_rate(&ctx->cur_fps.num, &ctx->cur_fps.den);
if (!ctx->fps.num && ctx->dts==ctx->fps.den)
ctx->dts = ctx->cur_fps.den;
}
ctx->fps = ctx->cur_fps;
}
first = GF_FALSE;
if (is_lvvc) {
first_lvvc = GF_FALSE;
if (sps->width > max_ew) max_ew = sps->width;
if (sps->height > max_eh) max_eh = sps->height;
} else {
if (sps->width > max_w) max_w = sps->width;
if (sps->height > max_h) max_h = sps->height;
}
if (!ctx->analyze)
naludmx_add_param_nalu(cfg->param_array, sl, GF_VVC_NALU_SEQ_PARAM);
}
count = gf_list_count(ctx->pps);
for (i=0; i<count; i++) {
GF_NALUFFParam *sl = gf_list_get(ctx->pps, i);
layer_id = sl->data[0] & 0x3F;
if (!layer_id) *has_vvc_base = GF_TRUE;
if (!ctx->analyze)
naludmx_add_param_nalu(cfg->param_array, sl, GF_VVC_NALU_PIC_PARAM);
}
count = gf_list_count(ctx->vvc_dci);
for (i=0; i<count; i++) {
GF_NALUFFParam *sl = gf_list_get(ctx->vvc_dci, i);
layer_id = sl->data[0] & 0x3F;
if (!layer_id) *has_vvc_base = GF_TRUE;
if (!ctx->analyze)
naludmx_add_param_nalu(cfg->param_array, sl, GF_VVC_NALU_DEC_PARAM);
}
count = gf_list_count(ctx->vvc_opi);
for (i=0; i<count; i++) {
GF_NALUFFParam *sl = gf_list_get(ctx->vvc_opi, i);
layer_id = sl->data[0] & 0x3F;
if (!layer_id) *has_vvc_base = GF_TRUE;
if (!ctx->analyze)
naludmx_add_param_nalu(cfg->param_array, sl, GF_VVC_NALU_OPI);
}
count = gf_list_count(ctx->vvc_aps_pre);
for (i=0; i<count; i++) {
GF_NALUFFParam *sl = gf_list_get(ctx->vvc_aps_pre, i);
layer_id = sl->data[0] & 0x3F;
if (!layer_id) *has_vvc_base = GF_TRUE;
if (!ctx->analyze)
naludmx_add_param_nalu(cfg->param_array, sl, GF_VVC_NALU_APS_PREFIX);
}
*dsi = *dsi_enh = NULL;
*dsi_size = *dsi_enh_size = 0;
gf_odf_vvc_cfg_write(cfg, dsi, dsi_size);
*max_width = max_w;
*max_height = max_h;
*max_enh_width = max_ew;
*max_enh_height = max_eh;
count = gf_list_count(cfg->param_array);
for (i=0; i<count; i++) {
GF_NALUFFParamArray *pa = gf_list_get(cfg->param_array, i);
gf_list_reset(pa->nalus);
}
gf_odf_vvc_cfg_del(cfg);
}

static int
translate_compat_table(struct net *net,
struct xt_table_info **pinfo,
void **pentry0,
const struct compat_ipt_replace *compatr)
{
unsigned int i, j;
struct xt_table_info *newinfo, *info;
void *pos, *entry0, *entry1;
struct compat_ipt_entry *iter0;
struct ipt_replace repl;
unsigned int size;
int ret;
info = *pinfo;
entry0 = *pentry0;
size = compatr->size;
info->number = compatr->num_entries;
j = 0;
xt_compat_lock(AF_INET);
ret = xt_compat_init_offsets(AF_INET, compatr->num_entries);
if (ret)
goto out_unlock;
xt_entry_foreach(iter0, entry0, compatr->size) {
ret = check_compat_entry_size_and_hooks(iter0, info, &size,
entry0,
entry0 + compatr->size);
if (ret != 0)
goto out_unlock;
++j;
}
ret = -EINVAL;
if (j != compatr->num_entries)
goto out_unlock;
ret = -ENOMEM;
newinfo = xt_alloc_table_info(size);
if (!newinfo)
goto out_unlock;
newinfo->number = compatr->num_entries;
for (i = 0; i < NF_INET_NUMHOOKS; i++) {
newinfo->hook_entry[i] = compatr->hook_entry[i];
newinfo->underflow[i] = compatr->underflow[i];
}
entry1 = newinfo->entries;
pos = entry1;
size = compatr->size;
xt_entry_foreach(iter0, entry0, compatr->size)
compat_copy_entry_from_user(iter0, &pos, &size,
newinfo, entry1);
xt_compat_flush_offsets(AF_INET);
xt_compat_unlock(AF_INET);
memcpy(&repl, compatr, sizeof(*compatr));
for (i = 0; i < NF_INET_NUMHOOKS; i++) {
repl.hook_entry[i] = newinfo->hook_entry[i];
repl.underflow[i] = newinfo->underflow[i];
}
repl.num_counters = 0;
repl.counters = NULL;
repl.size = newinfo->size;
ret = translate_table(net, newinfo, entry1, &repl);
if (ret)
goto free_newinfo;
*pinfo = newinfo;
*pentry0 = entry1;
xt_free_table_info(info);
return 0;
free_newinfo:
xt_free_table_info(newinfo);
return ret;
out_unlock:
xt_compat_flush_offsets(AF_INET);
xt_compat_unlock(AF_INET);
xt_entry_foreach(iter0, entry0, compatr->size) {
if (j-- == 0)
break;
compat_release_entry(iter0);
}
return ret;
}

GF_Err afra_box_read(GF_Box *s, GF_BitStream *bs)
{
unsigned int i;
GF_AdobeFragRandomAccessBox *ptr = (GF_AdobeFragRandomAccessBox *)s;
ISOM_DECREASE_SIZE(ptr, 9)
ptr->long_ids = gf_bs_read_int(bs, 1);
ptr->long_offsets = gf_bs_read_int(bs, 1);
ptr->global_entries = gf_bs_read_int(bs, 1);
ptr->reserved = gf_bs_read_int(bs, 5);
ptr->time_scale = gf_bs_read_u32(bs);
ptr->entry_count = gf_bs_read_u32(bs);
if (ptr->size / ( (ptr->long_offsets ? 16 : 12) ) < ptr->entry_count)
return GF_ISOM_INVALID_FILE;
for (i=0; i<ptr->entry_count; i++) {
GF_AfraEntry *ae = gf_malloc(sizeof(GF_AfraEntry));
if (!ae) return GF_OUT_OF_MEM;
ISOM_DECREASE_SIZE(ptr, 8)
ae->time = gf_bs_read_u64(bs);
if (ptr->long_offsets) {
ISOM_DECREASE_SIZE(ptr, 8)
ae->offset = gf_bs_read_u64(bs);
} else {
ISOM_DECREASE_SIZE(ptr, 4)
ae->offset = gf_bs_read_u32(bs);
}
gf_list_insert(ptr->local_access_entries, ae, i);
}
if (ptr->global_entries) {
ISOM_DECREASE_SIZE(ptr, 4)
ptr->global_entry_count = gf_bs_read_u32(bs);
for (i=0; i<ptr->global_entry_count; i++) {
GF_GlobalAfraEntry *ae = gf_malloc(sizeof(GF_GlobalAfraEntry));
if (!ae) return GF_OUT_OF_MEM;
ISOM_DECREASE_SIZE(ptr, 8)
ae->time = gf_bs_read_u64(bs);
if (ptr->long_ids) {
ISOM_DECREASE_SIZE(ptr, 8)
ae->segment = gf_bs_read_u32(bs);
ae->fragment = gf_bs_read_u32(bs);
} else {
ISOM_DECREASE_SIZE(ptr, 4)
ae->segment = gf_bs_read_u16(bs);
ae->fragment = gf_bs_read_u16(bs);
}
if (ptr->long_offsets) {
ISOM_DECREASE_SIZE(ptr, 16)
ae->afra_offset = gf_bs_read_u64(bs);
ae->offset_from_afra = gf_bs_read_u64(bs);
} else {
ISOM_DECREASE_SIZE(ptr, 8)
ae->afra_offset = gf_bs_read_u32(bs);
ae->offset_from_afra = gf_bs_read_u32(bs);
}
gf_list_insert(ptr->global_access_entries, ae, i);
}
}
return GF_OK;
}

void js_newregexp(js_State *J, const char *pattern, int flags)
{
const char *error;
js_Object *obj;
Reprog *prog;
int opts;
obj = jsV_newobject(J, JS_CREGEXP, J->RegExp_prototype);
opts = 0;
if (flags & JS_REGEXP_I) opts |= REG_ICASE;
if (flags & JS_REGEXP_M) opts |= REG_NEWLINE;
prog = js_regcomp(pattern, opts, &error);
if (!prog)
js_syntaxerror(J, "regular expression: %s", error);
obj->u.r.prog = prog;
obj->u.r.source = js_strdup(J, pattern);
obj->u.r.flags = flags;
obj->u.r.last = 0;
js_pushobject(J, obj);
}

static int cqspi_setup_flash(struct cqspi_st *cqspi, struct device_node *np)
{
struct platform_device *pdev = cqspi->pdev;
struct device *dev = &pdev->dev;
struct cqspi_flash_pdata *f_pdata;
struct spi_nor *nor;
struct mtd_info *mtd;
unsigned int cs;
int i, ret;
for_each_available_child_of_node(dev->of_node, np) {
if (of_property_read_u32(np, "reg", &cs)) {
dev_err(dev, "Couldn't determine chip select.\n");
goto err;
}
if (cs > CQSPI_MAX_CHIPSELECT) {
dev_err(dev, "Chip select %d out of range.\n", cs);
goto err;
}
f_pdata = &cqspi->f_pdata[cs];
f_pdata->cqspi = cqspi;
f_pdata->cs = cs;
ret = cqspi_of_get_flash_pdata(pdev, f_pdata, np);
if (ret)
goto err;
nor = &f_pdata->nor;
mtd = &nor->mtd;
mtd->priv = nor;
nor->dev = dev;
spi_nor_set_flash_node(nor, np);
nor->priv = f_pdata;
nor->read_reg = cqspi_read_reg;
nor->write_reg = cqspi_write_reg;
nor->read = cqspi_read;
nor->write = cqspi_write;
nor->erase = cqspi_erase;
nor->prepare = cqspi_prep;
nor->unprepare = cqspi_unprep;
mtd->name = devm_kasprintf(dev, GFP_KERNEL, "%s.%d",
dev_name(dev), cs);
if (!mtd->name) {
ret = -ENOMEM;
goto err;
}
ret = spi_nor_scan(nor, NULL, SPI_NOR_QUAD);
if (ret)
goto err;
ret = mtd_device_register(mtd, NULL, 0);
if (ret)
goto err;
f_pdata->registered = true;
}
return 0;
err:
for (i = 0; i < CQSPI_MAX_CHIPSELECT; i++)
if (cqspi->f_pdata[i].registered)
mtd_device_unregister(&cqspi->f_pdata[i].nor.mtd);
return ret;
}

int32_t
conn_handler(uint8_t *packet, conn_param *cparam, size_t max)
{
uint32_t len, tmp, pos = 0, len_of_var = 0;
int      len_of_str = 0;
int32_t  rv         = 0;
if (packet[pos] != CMD_CONNECT) {
return PROTOCOL_ERROR;
} else {
pos++;
}
len = (uint32_t) get_var_integer(packet + pos, &len_of_var);
pos += len_of_var;
log_trace("fix header length: %d", len_of_str);
cparam->pro_name.body =
(char *) copyn_utf8_str(packet, &pos, &len_of_str, max-pos);
cparam->pro_name.len = len_of_str;
rv                   = len_of_str < 0 ? PROTOCOL_ERROR : 0;
log_trace("pro_name: %s", cparam->pro_name.body);
cparam->pro_ver = packet[pos];
pos++;
cparam->con_flag    = packet[pos];
cparam->clean_start = (cparam->con_flag & 0x02) >> 1;
cparam->will_flag   = (cparam->con_flag & 0x04) >> 2;
cparam->will_qos    = (cparam->con_flag & 0x18) >> 3;
cparam->will_retain = (cparam->con_flag & 0x20) >> 5;
log_trace("conn flag:%x", cparam->con_flag);
if (cparam->will_flag == 1 && cparam->will_qos > 2)
return PROTOCOL_ERROR;
pos++;
NNI_GET16(packet + pos, tmp);
cparam->keepalive_mqtt = tmp;
pos += 2;
if (cparam->pro_ver == MQTT_PROTOCOL_VERSION_v5) {
log_trace("Decoding MQTT V5 Properties");
if (pos >= max)
return PROTOCOL_ERROR;
len_of_var = 0;
cparam->prop_len = (uint32_t) get_var_integer(packet + pos, &len_of_var);
if (cparam->prop_len > (max - pos - 1 - cparam->will_flag*2 ))
return PROTOCOL_ERROR;
log_debug("remain len %d max len %d prop len %d pos %d", len, max, cparam->prop_len, pos);
cparam->properties = decode_buf_properties(
packet, len, &pos, &cparam->prop_len, true);
if (cparam->properties) {
conn_param_set_property(cparam, cparam->properties);
if ((rv = check_properties(cparam->properties)) !=
SUCCESS) {
return rv;
}
}
}
log_trace("pos after property: [%d]", pos);
cparam->clientid.body =
(char *) copyn_utf8_str(packet, &pos, &len_of_str, max-pos);
cparam->clientid.len = len_of_str;
if (len_of_str == 0) {
char clientid_r[20] = {0};
snprintf(clientid_r, 20, "nanomq-%08x", nni_random());
clientid_r[19]        = '\0';
cparam->clientid.body = nng_strdup(clientid_r);
cparam->clientid.len  = strlen(clientid_r);
cparam->assignedid    = true;
} else if (len_of_str < 0) {
return (PROTOCOL_ERROR);
}
log_trace("clientid: [%s] [%d]", cparam->clientid.body, len_of_str);
log_trace("pos after clientid: [%d]", pos);
if (cparam->pro_ver == MQTT_PROTOCOL_VERSION_v5 && cparam->assignedid) {
property *assigned_cid =
property_set_value_str(ASSIGNED_CLIENT_IDENTIFIER,
cparam->clientid.body, cparam->clientid.len, false);
if (cparam->properties == NULL) {
cparam->properties = property_alloc();
}
property_append(cparam->properties, assigned_cid);
}
if (rv == 0 && cparam->will_flag != 0) {
if (cparam->pro_ver == MQTT_PROTOCOL_VERSION_v5) {
cparam->will_properties = decode_buf_properties(
packet, len, &pos, &cparam->will_prop_len, true);
if (cparam->will_properties) {
conn_param_set_will_property(
cparam, cparam->will_properties);
if ((rv = check_properties(
cparam->will_properties)) !=
SUCCESS) {
return PROTOCOL_ERROR;
}
}
log_trace("pos after will property: [%d]", pos);
}
cparam->will_topic.body =
(char *) copyn_utf8_str(packet, &pos, &len_of_str, max-pos);
cparam->will_topic.len = len_of_str;
rv                     = len_of_str <= 0 ? 1 : 0;
if (cparam->will_topic.body == NULL || rv != 0) {
return PROTOCOL_ERROR;
}
log_trace("will_topic: %s %d", cparam->will_topic.body, rv);
log_trace("pos after will topic body: [%d]", pos);
if (rv == 0 && cparam->payload_format_indicator == 0) {
cparam->will_msg.body = (char *) copyn_str(
packet, &pos, &len_of_str, max - pos);
} else if (rv == 0 &&
cparam->payload_format_indicator == 0x01) {
cparam->will_msg.body = (char *) copyn_utf8_str(
packet, &pos, &len_of_str, max - pos);
}
rv = len_of_str <= 0 ? PAYLOAD_FORMAT_INVALID : 0;
if (cparam->will_msg.body == NULL || rv != 0) {
return PROTOCOL_ERROR;
}
cparam->will_msg.len = len_of_str;
log_trace("will_msg: %s %d", cparam->will_msg.body, rv);
log_trace("pos after will msg: [%d]", pos);
}
if (rv == 0 && (cparam->con_flag & 0x80) > 0) {
cparam->username.body =
(char *) copyn_utf8_str(packet, &pos, &len_of_str, max-pos);
cparam->username.len = len_of_str;
rv                   = len_of_str <= 0 ? PAYLOAD_FORMAT_INVALID : 0;
if (rv != 0) {
return rv;
}
log_trace(
"username: %s %d", cparam->username.body, len_of_str);
log_trace("pos after username: [%d]", pos);
}
if (rv == 0 && (cparam->con_flag & 0x40) > 0) {
cparam->password.body =
copyn_utf8_str(packet, &pos, &len_of_str, max-pos);
cparam->password.len = len_of_str;
rv                   = len_of_str <= 0 ? PAYLOAD_FORMAT_INVALID : 0;
if (rv != 0) {
log_warn("MQTT Packet parsing error!");
return rv;
}
log_trace(
"password: %s [%d]", cparam->password.body, len_of_str);
log_trace("pos after password: [%d]", pos);
}
log_trace("pos: [%d] len: [%d]", pos, len);
if (len + len_of_var + 1 != pos) {
log_error("inconnect handler");
rv = PROTOCOL_ERROR;
}
return rv;
}

static void
mbim_dissect_subscriber_ready_status(tvbuff_t *tvb, packet_info *pinfo _U_, proto_tree *tree, gint offset,
struct mbim_conv_info *mbim_conv)
{
proto_tree *subtree;
gint base_offset;
guint32 i, subscriber_id_offset, subscriber_id_size, sim_icc_id_offset, sim_icc_id_size, elem_count;
proto_item *it;
wmem_array_t *pair_list = NULL;
struct mbim_pair_list pair_list_item, *p_pair_list_item;
base_offset = offset;
proto_tree_add_item(tree, hf_mbim_subscr_ready_status_ready_state, tvb, offset, 4, ENC_LITTLE_ENDIAN);
offset += 4;
proto_tree_add_item_ret_uint(tree, hf_mbim_subscr_ready_status_susbcr_id_offset, tvb, offset, 4, ENC_LITTLE_ENDIAN, &subscriber_id_offset);
offset += 4;
proto_tree_add_item_ret_uint(tree, hf_mbim_subscr_ready_status_susbcr_id_size, tvb, offset, 4, ENC_LITTLE_ENDIAN, &subscriber_id_size);
offset += 4;
proto_tree_add_item_ret_uint(tree, hf_mbim_subscr_ready_status_sim_icc_id_offset, tvb, offset, 4, ENC_LITTLE_ENDIAN, &sim_icc_id_offset);
offset += 4;
proto_tree_add_item_ret_uint(tree, hf_mbim_subscr_ready_status_sim_icc_id_size, tvb, offset, 4, ENC_LITTLE_ENDIAN, &sim_icc_id_size);
offset += 4;
proto_tree_add_item(tree, hf_mbim_subscr_ready_status_ready_info, tvb, offset, 4, ENC_LITTLE_ENDIAN);
offset += 4;
proto_tree_add_item_ret_uint(tree, hf_mbim_subscr_ready_status_elem_count, tvb, offset, 4, ENC_LITTLE_ENDIAN, &elem_count);
offset += 4;
if (elem_count) {
pair_list = wmem_array_sized_new(wmem_packet_scope(), sizeof(struct mbim_pair_list), elem_count);
subtree = proto_tree_add_subtree(tree, tvb, offset, 8*elem_count, ett_mbim_pair_list, NULL, "Telephone Numbers Ref List");
for (i = 0; i < elem_count; i++) {
proto_tree_add_item_ret_uint(subtree, hf_mbim_subscr_ready_status_tel_nb_offset, tvb, offset, 4, ENC_LITTLE_ENDIAN, &pair_list_item.offset);
offset += 4;
proto_tree_add_item_ret_uint(subtree, hf_mbim_subscr_ready_status_tel_nb_size, tvb, offset, 4, ENC_LITTLE_ENDIAN, &pair_list_item.size);
offset += 4;
wmem_array_append_one(pair_list, pair_list_item);
}
}
if (subscriber_id_offset && subscriber_id_size) {
it = proto_tree_add_item(tree, hf_mbim_subscr_ready_status_susbcr_id, tvb, base_offset + subscriber_id_offset,
subscriber_id_size, ENC_LITTLE_ENDIAN|ENC_UTF_16);
if ((mbim_conv->cellular_class == MBIM_CELLULAR_CLASS_CDMA) && (subscriber_id_size > 20)) {
expert_add_info(pinfo, it, &ei_mbim_oversized_string);
} else if (subscriber_id_size > 30) {
expert_add_info(pinfo, it, &ei_mbim_oversized_string);
}
}
if (sim_icc_id_offset && sim_icc_id_size) {
it = proto_tree_add_item(tree, hf_mbim_subscr_ready_status_sim_icc_id, tvb, base_offset + sim_icc_id_offset,
sim_icc_id_size, ENC_LITTLE_ENDIAN|ENC_UTF_16);
if (sim_icc_id_size > 40) {
expert_add_info(pinfo, it, &ei_mbim_oversized_string);
}
}
for (i = 0; i < elem_count; i++) {
