int main(int argc, char * argv[]) {
int mode = MODE_ENCODE;
char *input = NULL, *output = NULL;
char *f1 = NULL, *f2 = NULL;
int force = 0;
int force_stdstreams = 0, workers = 0, batch = 0, verbose = 0;
u32 block_size = MiB(16);
#ifdef PTHREAD
const char * short_options = "Bb:cdefhj:ktvVz";
#else
const char * short_options = "Bb:cdefhktvVz";
#endif
static struct option long_options[] = { { "encode", no_argument, 0, 'e' },
{ "decode", no_argument, 0, 'd' },
{ "test", no_argument, 0, 't' },
{ "stdout", no_argument, 0, 'c' },
{ "force", no_argument, 0, 'f' },
{ "help", no_argument, 0, 'h' },
{ "keep", no_argument, 0, 'k' },
{ "version", no_argument, 0, 'V' },
{ "verbose", no_argument, 0, 'v' },
{ "block", required_argument, 0, 'b' },
{ "batch", no_argument, 0, 'B' },
#ifdef PTHREAD
{ "jobs", required_argument, 0, 'j' },
#endif
{ 0, 0, 0, 0 } };
while (1) {
int option_index = 0;
int c = getopt_long(argc, argv, short_options, long_options, &option_index);
if (c == -1) break;
switch (c) {
case '?':
fprintf(stderr, "Try 'bzip3 --help' for more information.\n");
return 1;
case 'e': case 'z':
mode = MODE_ENCODE;
break;
case 'd':
mode = MODE_DECODE;
break;
case 't':
mode = MODE_TEST;
break;
case 'c':
force_stdstreams = 1;
break;
case 'f':
force = 1;
break;
case 'k':
break;
case 'h':
help();
return 0;
case 'V':
version();
return 0;
case 'B':
batch = 1;
break;
case 'v':
verbose = 1;
break;
case 'b':
if (!is_numeric(optarg)) {
fprintf(stderr, "bzip3: invalid block size: %s\n", optarg);
return 1;
}
block_size = MiB(atoi(optarg));
break;
#ifdef PTHREAD
case 'j':
if (!is_numeric(optarg)) {
fprintf(stderr, "bzip3: invalid amount of jobs: %s\n", optarg);
return 1;
}
workers = atoi(optarg);
break;
#endif
}
}
#if defined(__MSVCRT__)
setmode(STDIN_FILENO, O_BINARY);
setmode(STDOUT_FILENO, O_BINARY);
#endif
if (block_size < KiB(65) || block_size > MiB(511)) {
fprintf(stderr, "Block size must be between 65 KiB and 511 MiB.\n");
return 1;
}
if (batch) {
switch (mode) {
case MODE_ENCODE:
while (optind < argc) {
char * arg = argv[optind++];
FILE * input_des = open_input(arg);
char * output_name;
if (force_stdstreams)
output_name = NULL;
else {
output_name = malloc(strlen(arg) + 5);
strcpy(output_name, arg);
strcat(output_name, ".bz3");
}
FILE * output_des = open_output(output_name, force);
process(input_des, output_des, mode, block_size, workers, verbose, arg);
fclose(input_des);
close_out_file(output_des);
if (!force_stdstreams) free(output_name);
}
break;
case MODE_DECODE:
while (optind < argc) {
char * arg = argv[optind++];
FILE * input_des = open_input(arg);
char * output_name;
if (force_stdstreams)
output_name = NULL;
else {
output_name = malloc(strlen(arg) + 1);
strcpy(output_name, arg);
if (strlen(output_name) > 4 && !strcmp(output_name + strlen(output_name) - 4, ".bz3"))
output_name[strlen(output_name) - 4] = 0;
else {
fprintf(stderr, "Warning: file %s has an unknown extension, skipping.\n", arg);
return 1;
}
}
FILE * output_des = open_output(output_name, force);
process(input_des, output_des, mode, block_size, workers, verbose, arg);
fclose(input_des);
close_out_file(output_des);
if (!force_stdstreams) free(output_name);
}
break;
case MODE_TEST:
while (optind < argc) {
char * arg = argv[optind++];
FILE * input_des = open_input(arg);
process(input_des, NULL, mode, block_size, workers, verbose, arg);
fclose(input_des);
}
break;
}
if (fclose(stdout)) {
fprintf(stderr, "Error: Failed on fclose(stdout): %s\n", strerror(errno));
return 1;
}
return 0;
}
while (optind < argc) {
char * arg = argv[optind++];
if (f1 != NULL && f2 != NULL) {
fprintf(stderr, "Error: too many files specified.\n");
return 1;
}
if (f1 == NULL)
f1 = arg;
else
f2 = arg;
}
if (f1 == NULL && f2 == NULL)
input = NULL, output = NULL;
else if (mode == MODE_TEST)
input = f1;
else {
if (mode == MODE_ENCODE) {
if (f2 == NULL) {
input = f1;
if (force_stdstreams)
output = NULL;
else {
output = malloc(strlen(f1) + 5);
strcpy(output, f1);
strcat(output, ".bz3");
}
} else {
input = f1;
output = f2;
}
} else if (mode == MODE_DECODE) {
if (f2 == NULL) {
input = f1;
if (force_stdstreams)
output = NULL;
else {
output = malloc(strlen(f1) + 1);
strcpy(output, f1);
if (strlen(output) > 4 && !strcmp(output + strlen(output) - 4, ".bz3"))
output[strlen(output) - 4] = 0;
else {
fprintf(stderr, "Warning: file %s has an unknown extension, skipping.\n", f1);
return 1;
}
}
} else {
input = f1;
output = f2;
}
}
}
FILE *input_des = NULL, *output_des = NULL;
output_des = mode != MODE_TEST ? open_output(output, force) : NULL;
input_des = open_input(input);
int r = process(input_des, output_des, mode, block_size, workers, verbose, input);
fclose(input_des);
close_out_file(output_des);
if (fclose(stdout)) {
fprintf(stderr, "Error: Failed on fclose(stdout): %s\n", strerror(errno));
return 1;
}
return r;
}

GF_Err latm_dmx_process(GF_Filter *filter)
{
GF_LATMDmxCtx *ctx = gf_filter_get_udta(filter);
GF_FilterPacket *pck, *dst_pck;
u32 pos;
u8 *data=NULL, *output;
u32 pck_size=0, prev_pck_size;
u64 cts = GF_FILTER_NO_TS;
if (ctx->in_error)
return ctx->in_error;
if (!ctx->duration.num)
latm_dmx_check_dur(filter, ctx);
if (ctx->opid && !ctx->is_playing)
return GF_OK;
pck = gf_filter_pid_get_packet(ctx->ipid);
if (!pck) {
if (gf_filter_pid_is_eos(ctx->ipid)) {
if (!ctx->latm_buffer_size) {
if (ctx->opid)
gf_filter_pid_set_eos(ctx->opid);
if (ctx->src_pck) gf_filter_pck_unref(ctx->src_pck);
ctx->src_pck = NULL;
return GF_EOS;
}
} else {
return GF_OK;
}
} else {
data = (char *) gf_filter_pck_get_data(pck, &pck_size);
}
if (ctx->timescale && pck) {
cts = gf_filter_pck_get_cts(pck);
if (!ctx->cts && (cts != GF_FILTER_NO_TS))
ctx->cts = cts;
}
prev_pck_size = ctx->latm_buffer_size;
if (pck && !ctx->resume_from) {
if (ctx->latm_buffer_size + pck_size > ctx->latm_buffer_alloc) {
ctx->latm_buffer_alloc = ctx->latm_buffer_size + pck_size;
ctx->latm_buffer = gf_realloc(ctx->latm_buffer, ctx->latm_buffer_alloc);
}
memcpy(ctx->latm_buffer + ctx->latm_buffer_size, data, pck_size);
ctx->latm_buffer_size += pck_size;
}
if (!ctx->bs) ctx->bs = gf_bs_new(ctx->latm_buffer, ctx->latm_buffer_size, GF_BITSTREAM_READ);
else gf_bs_reassign_buffer(ctx->bs, ctx->latm_buffer, ctx->latm_buffer_size);
if (ctx->resume_from) {
gf_bs_seek(ctx->bs, ctx->resume_from-1);
ctx->resume_from = 0;
}
if (cts == GF_FILTER_NO_TS)
prev_pck_size = 0;
while (1) {
pos = (u32) gf_bs_get_position(ctx->bs);
u8 latm_buffer[4096];
u32 latm_frame_size = 4096;
if (!latm_dmx_sync_frame_bs(ctx->bs,&ctx->acfg, &latm_frame_size, latm_buffer, NULL)) break;
if (ctx->in_seek) {
u64 nb_samples_at_seek = (u64) (ctx->start_range * GF_M4ASampleRates[ctx->sr_idx]);
if (ctx->cts + ctx->dts_inc >= nb_samples_at_seek) {
ctx->in_seek = GF_FALSE;
}
}
latm_dmx_check_pid(filter, ctx);
if (!ctx->is_playing) {
ctx->resume_from = pos+1;
return GF_OK;
}
if (!ctx->in_seek) {
GF_FilterSAPType sap = GF_FILTER_SAP_1;
dst_pck = gf_filter_pck_new_alloc(ctx->opid, latm_frame_size, &output);
if (!dst_pck) return GF_OUT_OF_MEM;
if (ctx->src_pck) gf_filter_pck_merge_properties(ctx->src_pck, dst_pck);
memcpy(output, latm_buffer, latm_frame_size);
gf_filter_pck_set_cts(dst_pck, ctx->cts);
gf_filter_pck_set_duration(dst_pck, ctx->dts_inc);
gf_filter_pck_set_framing(dst_pck, GF_TRUE, GF_TRUE);
if (ctx->acfg.base_object_type==GF_CODECID_USAC) {
if (latm_frame_size && (output[0] & 0x80) && !ctx->prev_sap) {
sap = GF_FILTER_SAP_1;
ctx->prev_sap = GF_TRUE;
} else {
sap = GF_FILTER_SAP_NONE;
ctx->prev_sap = GF_FALSE;
}
}
gf_filter_pck_set_sap(dst_pck, sap);
gf_filter_pck_send(dst_pck);
}
latm_dmx_update_cts(ctx);
if (prev_pck_size) {
pos = (u32) gf_bs_get_position(ctx->bs);
if (prev_pck_size<=pos) {
prev_pck_size=0;
if (ctx->src_pck) gf_filter_pck_unref(ctx->src_pck);
ctx->src_pck = pck;
if (pck)
gf_filter_pck_ref_props(&ctx->src_pck);
}
}
}
if (pck) {
pos = (u32) gf_bs_get_position(ctx->bs);
assert(ctx->latm_buffer_size >= pos);
memmove(ctx->latm_buffer, ctx->latm_buffer+pos, ctx->latm_buffer_size - pos);
ctx->latm_buffer_size -= pos;
gf_filter_pid_drop_packet(ctx->ipid);
assert(!ctx->resume_from);
} else {
ctx->latm_buffer_size = 0;
return latm_dmx_process(filter);
}
return GF_OK;
}

static int process(FILE * input_des, FILE * output_des, int mode, int block_size, int workers, int verbose, char * file_name) {
uint64_t bytes_read = 0, bytes_written = 0;
if ((mode == MODE_ENCODE && isatty(fileno(output_des))) ||
((mode == MODE_DECODE || mode == MODE_TEST) && isatty(fileno(input_des)))) {
fprintf(stderr, "Refusing to read/write binary data from/to the terminal.\n");
return 1;
}
errno = 0;
u8 byteswap_buf[4];
switch (mode) {
case MODE_ENCODE:
xwrite("BZ3v1", 5, 1, output_des);
write_neutral_s32(byteswap_buf, block_size);
xwrite(byteswap_buf, 4, 1, output_des);
bytes_written += 9;
break;
case MODE_DECODE:
case MODE_TEST: {
char signature[5];
if (xread(signature, 5, 1, input_des) != 1 || strncmp(signature, "BZ3v1", 5) != 0) {
fprintf(stderr, "Invalid signature.\n");
return 1;
}
xread_noeof(byteswap_buf, 4, 1, input_des);
block_size = read_neutral_s32(byteswap_buf);
if (block_size < KiB(65) || block_size > MiB(511)) {
fprintf(stderr,
"The input file is corrupted. Reason: Invalid block "
"size in the header.\n");
return 1;
}
bytes_read += 9;
break;
}
}
#ifdef PTHREAD
if (workers > 64 || workers < 0) {
fprintf(stderr, "Number of workers must be between 0 and 64.\n");
return 1;
}
if (workers <= 1) {
#endif
struct bz3_state * state = bz3_new(block_size);
if (state == NULL) {
fprintf(stderr, "Failed to create a block encoder state.\n");
return 1;
}
u8 * buffer = malloc(block_size + block_size / 50 + 32);
if (!buffer) {
fprintf(stderr, "Failed to allocate memory.\n");
return 1;
}
if (mode == MODE_ENCODE) {
s32 read_count;
while (!feof(input_des)) {
read_count = xread(buffer, 1, block_size, input_des);
bytes_read += read_count;
if(read_count == 0)
break;
s32 new_size = bz3_encode_block(state, buffer, read_count);
if (new_size == -1) {
fprintf(stderr, "Failed to encode a block: %s\n", bz3_strerror(state));
return 1;
}
write_neutral_s32(byteswap_buf, new_size);
xwrite(byteswap_buf, 4, 1, output_des);
write_neutral_s32(byteswap_buf, read_count);
xwrite(byteswap_buf, 4, 1, output_des);
xwrite(buffer, new_size, 1, output_des);
bytes_written += 8 + new_size;
}
fflush(output_des);
} else if (mode == MODE_DECODE) {
s32 new_size, old_size;
while (!feof(input_des)) {
if (!xread_eofcheck(&byteswap_buf, 1, 4, input_des)) continue;
new_size = read_neutral_s32(byteswap_buf);
xread_noeof(&byteswap_buf, 1, 4, input_des);
old_size = read_neutral_s32(byteswap_buf);
xread_noeof(buffer, 1, new_size, input_des);
bytes_read += 8 + new_size;
if (bz3_decode_block(state, buffer, new_size, old_size) == -1) {
fprintf(stderr, "Failed to decode a block: %s\n", bz3_strerror(state));
return 1;
}
xwrite(buffer, old_size, 1, output_des);
bytes_written += old_size;
}
fflush(output_des);
} else if (mode == MODE_TEST) {
s32 new_size, old_size;
while (!feof(input_des)) {
if (!xread_eofcheck(&byteswap_buf, 1, 4, input_des)) continue;
new_size = read_neutral_s32(byteswap_buf);
xread_noeof(&byteswap_buf, 1, 4, input_des);
old_size = read_neutral_s32(byteswap_buf);
xread_noeof(buffer, 1, new_size, input_des);
bytes_read += 8 + new_size;
if (bz3_decode_block(state, buffer, new_size, old_size) == -1) {
fprintf(stderr, "Failed to decode a block: %s\n", bz3_strerror(state));
return 1;
}
}
}
if (bz3_last_error(state) != BZ3_OK) {
fprintf(stderr, "Failed to read data: %s\n", bz3_strerror(state));
return 1;
}
free(buffer);
bz3_free(state);
#ifdef PTHREAD
} else {
struct bz3_state * states[workers];
u8 * buffers[workers];
s32 sizes[workers];
s32 old_sizes[workers];
for (s32 i = 0; i < workers; i++) {
states[i] = bz3_new(block_size);
if (states[i] == NULL) {
fprintf(stderr, "Failed to create a block encoder state.\n");
return 1;
}
buffers[i] = malloc(block_size + block_size / 50 + 32);
if (!buffers[i]) {
fprintf(stderr, "Failed to allocate memory.\n");
return 1;
}
}
if (mode == MODE_ENCODE) {
while (!feof(input_des)) {
s32 i = 0;
for (; i < workers; i++) {
size_t read_count = xread(buffers[i], 1, block_size, input_des);
bytes_read += read_count;
sizes[i] = old_sizes[i] = read_count;
if (read_count < block_size) {
i++;
break;
}
}
bz3_encode_blocks(states, buffers, sizes, i);
for (s32 j = 0; j < i; j++) {
if (bz3_last_error(states[j]) != BZ3_OK) {
fprintf(stderr, "Failed to encode data: %s\n", bz3_strerror(states[j]));
return 1;
}
}
for (s32 j = 0; j < i; j++) {
write_neutral_s32(byteswap_buf, sizes[j]);
xwrite(byteswap_buf, 4, 1, output_des);
write_neutral_s32(byteswap_buf, old_sizes[j]);
xwrite(byteswap_buf, 4, 1, output_des);
xwrite(buffers[j], sizes[j], 1, output_des);
bytes_written += 8 + sizes[j];
}
}
fflush(output_des);
} else if (mode == MODE_DECODE) {
while (!feof(input_des)) {
s32 i = 0;
for (; i < workers; i++) {
if (!xread_eofcheck(&byteswap_buf, 1, 4, input_des)) break;
sizes[i] = read_neutral_s32(byteswap_buf);
xread_noeof(&byteswap_buf, 1, 4, input_des);
old_sizes[i] = read_neutral_s32(byteswap_buf);
xread_noeof(buffers[i], 1, sizes[i], input_des);
bytes_read += 8 + sizes[i];
}
bz3_decode_blocks(states, buffers, sizes, old_sizes, i);
for (s32 j = 0; j < i; j++) {
if (bz3_last_error(states[j]) != BZ3_OK) {
fprintf(stderr, "Failed to decode data: %s\n", bz3_strerror(states[j]));
return 1;
}
}
for (s32 j = 0; j < i; j++) {
xwrite(buffers[j], old_sizes[j], 1, output_des);
bytes_written += old_sizes[j];
}
}
fflush(output_des);
} else if (mode == MODE_TEST) {
while (!feof(input_des)) {
s32 i = 0;
for (; i < workers; i++) {
if (!xread_eofcheck(&byteswap_buf, 1, 4, input_des)) break;
sizes[i] = read_neutral_s32(byteswap_buf);
xread_noeof(&byteswap_buf, 1, 4, input_des);
old_sizes[i] = read_neutral_s32(byteswap_buf);
xread_noeof(buffers[i], 1, sizes[i], input_des);
bytes_read += 8 + sizes[i];
}
bz3_decode_blocks(states, buffers, sizes, old_sizes, i);
for (s32 j = 0; j < i; j++) {
if (bz3_last_error(states[j]) != BZ3_OK) {
fprintf(stderr, "Failed to decode data: %s\n", bz3_strerror(states[j]));
return 1;
}
}
}
}
for (s32 i = 0; i < workers; i++) {
free(buffers[i]);
bz3_free(states[i]);
}
}
#endif
if(verbose) {
if(file_name) fprintf(stderr, " %s:", file_name);
if(mode == MODE_ENCODE)
fprintf(stderr, "\t%"PRIu64" -> %"PRIu64" bytes, %.2f%%, %.2f bpb\n", bytes_read, bytes_written, (double)bytes_written * 100.0 / bytes_read, (double)bytes_written * 8.0 / bytes_read);
else if(mode == MODE_DECODE)
fprintf(stderr, "\t%"PRIu64" -> %"PRIu64" bytes, %.2f%%, %.2f bpb\n", bytes_read, bytes_written, (double)bytes_read * 100.0 / bytes_written, (double)bytes_read * 8.0 / bytes_written);
else
fprintf(stderr, "OK, %"PRIu64" bytes read.\n", bytes_read);
}
return 0;
}

static int do_last(struct nameidata *nd,
struct file *file, const struct open_flags *op)
{
struct dentry *dir = nd->path.dentry;
int open_flag = op->open_flag;
bool will_truncate = (open_flag & O_TRUNC) != 0;
bool got_write = false;
int acc_mode = op->acc_mode;
unsigned seq;
struct inode *inode;
struct path path;
int error;
nd->flags &= ~LOOKUP_PARENT;
nd->flags |= op->intent;
if (nd->last_type != LAST_NORM) {
error = handle_dots(nd, nd->last_type);
if (unlikely(error))
return error;
goto finish_open;
}
if (!(open_flag & O_CREAT)) {
if (nd->last.name[nd->last.len])
nd->flags |= LOOKUP_FOLLOW | LOOKUP_DIRECTORY;
error = lookup_fast(nd, &path, &inode, &seq);
if (likely(error > 0))
goto finish_lookup;
if (error < 0)
return error;
BUG_ON(nd->inode != dir->d_inode);
BUG_ON(nd->flags & LOOKUP_RCU);
} else {
error = complete_walk(nd);
if (error)
return error;
audit_inode(nd->name, dir, AUDIT_INODE_PARENT);
if (unlikely(nd->last.name[nd->last.len]))
return -EISDIR;
}
if (open_flag & (O_CREAT | O_TRUNC | O_WRONLY | O_RDWR)) {
error = mnt_want_write(nd->path.mnt);
if (!error)
got_write = true;
}
if (open_flag & O_CREAT)
inode_lock(dir->d_inode);
else
inode_lock_shared(dir->d_inode);
error = lookup_open(nd, &path, file, op, got_write);
if (open_flag & O_CREAT)
inode_unlock(dir->d_inode);
else
inode_unlock_shared(dir->d_inode);
if (error)
goto out;
if (file->f_mode & FMODE_OPENED) {
if ((file->f_mode & FMODE_CREATED) ||
!S_ISREG(file_inode(file)->i_mode))
will_truncate = false;
audit_inode(nd->name, file->f_path.dentry, 0);
goto opened;
}
if (file->f_mode & FMODE_CREATED) {
open_flag &= ~O_TRUNC;
will_truncate = false;
acc_mode = 0;
path_to_nameidata(&path, nd);
goto finish_open_created;
}
if (got_write) {
mnt_drop_write(nd->path.mnt);
got_write = false;
}
error = follow_managed(&path, nd);
if (unlikely(error < 0))
return error;
audit_inode(nd->name, path.dentry, 0);
if (unlikely((open_flag & (O_EXCL | O_CREAT)) == (O_EXCL | O_CREAT))) {
path_to_nameidata(&path, nd);
return -EEXIST;
}
seq = 0;
inode = d_backing_inode(path.dentry);
finish_lookup:
error = step_into(nd, &path, 0, inode, seq);
if (unlikely(error))
return error;
finish_open:
error = complete_walk(nd);
if (error)
return error;
audit_inode(nd->name, nd->path.dentry, 0);
if (open_flag & O_CREAT) {
error = -EISDIR;
if (d_is_dir(nd->path.dentry))
goto out;
error = may_create_in_sticky(dir,
d_backing_inode(nd->path.dentry));
if (unlikely(error))
goto out;
}
error = -ENOTDIR;
if ((nd->flags & LOOKUP_DIRECTORY) && !d_can_lookup(nd->path.dentry))
goto out;
if (!d_is_reg(nd->path.dentry))
will_truncate = false;
if (will_truncate) {
error = mnt_want_write(nd->path.mnt);
if (error)
goto out;
got_write = true;
}
finish_open_created:
error = may_open(&nd->path, acc_mode, open_flag);
if (error)
goto out;
BUG_ON(file->f_mode & FMODE_OPENED); 
error = vfs_open(&nd->path, file);
if (error)
goto out;
opened:
error = ima_file_check(file, op->acc_mode);
if (!error && will_truncate)
error = handle_truncate(file);
out:
if (unlikely(error > 0)) {
WARN_ON(1);
error = -EINVAL;
}
if (got_write)
mnt_drop_write(nd->path.mnt);
return error;
}

TiledInputFile::TiledInputFile (const Header &header,
OPENEXR_IMF_INTERNAL_NAMESPACE::IStream *is,
int version,
int numThreads) :
_data (new Data (numThreads))
{
_data->_deleteStream=false;
_data->_streamData = new InputStreamMutex();
try
{
_data->_streamData->is = is;
_data->header = header;
_data->version = version;
initialize();
_data->tileOffsets.readFrom (*(_data->_streamData->is),_data->fileIsComplete,false,false);
_data->memoryMapped = is->isMemoryMapped();
_data->_streamData->currentPosition = _data->_streamData->is->tellg();
}
catch(...)
{
if (!_data->memoryMapped)
{
for (size_t i = 0; i < _data->tileBuffers.size(); i++)
{
delete [] _data->tileBuffers[i]->buffer;
}
}
delete _data->_streamData;
delete _data;
throw; 
}
}

private int
do_core_note(struct magic_set *ms, unsigned char *nbuf, uint32_t type,
int swap, uint32_t namesz, uint32_t descsz,
size_t noff, size_t doff, int *flags, size_t size, int clazz)
{
#ifdef ELFCORE
int os_style = -1;
if ((namesz == 4 && strncmp((char *)&nbuf[noff], "CORE", 4) == 0) ||
(namesz == 5 && strcmp((char *)&nbuf[noff], "CORE") == 0)) {
os_style = OS_STYLE_SVR4;
}
if ((namesz == 8 && strcmp((char *)&nbuf[noff], "FreeBSD") == 0)) {
os_style = OS_STYLE_FREEBSD;
}
if ((namesz >= 11 && strncmp((char *)&nbuf[noff], "NetBSD-CORE", 11)
== 0)) {
os_style = OS_STYLE_NETBSD;
}
if (os_style != -1 && (*flags & FLAGS_DID_CORE_STYLE) == 0) {
if (file_printf(ms, ", %s-style", os_style_names[os_style])
== -1)
return 1;
*flags |= FLAGS_DID_CORE_STYLE;
*flags |= os_style;
}
switch (os_style) {
case OS_STYLE_NETBSD:
if (type == NT_NETBSD_CORE_PROCINFO) {
char sbuf[512];
struct NetBSD_elfcore_procinfo pi;
memset(&pi, 0, sizeof(pi));
memcpy(&pi, nbuf + doff, descsz);
if (file_printf(ms, ", from '%.31s', pid=%u, uid=%u, "
"gid=%u, nlwps=%u, lwp=%u (signal %u/code %u)",
file_printable(sbuf, sizeof(sbuf),
RCAST(char *, pi.cpi_name)),
elf_getu32(swap, (uint32_t)pi.cpi_pid),
elf_getu32(swap, pi.cpi_euid),
elf_getu32(swap, pi.cpi_egid),
elf_getu32(swap, pi.cpi_nlwps),
elf_getu32(swap, (uint32_t)pi.cpi_siglwp),
elf_getu32(swap, pi.cpi_signo),
elf_getu32(swap, pi.cpi_sigcode)) == -1)
return 1;
*flags |= FLAGS_DID_CORE;
return 1;
}
break;
case OS_STYLE_FREEBSD:
if (type == NT_PRPSINFO && *flags & FLAGS_IS_CORE) {
size_t argoff, pidoff;
if (clazz == ELFCLASS32)
argoff = 4 + 4 + 17;
else
argoff = 4 + 4 + 8 + 17;
if (file_printf(ms, ", from '%.80s'", nbuf + doff +
argoff) == -1)
return 1;
pidoff = argoff + 81 + 2;
if (doff + pidoff + 4 <= size) {
if (file_printf(ms, ", pid=%u",
elf_getu32(swap, *RCAST(uint32_t *, (nbuf +
doff + pidoff)))) == -1)
return 1;
}
*flags |= FLAGS_DID_CORE;
}    
break;
default:
if (type == NT_PRPSINFO && *flags & FLAGS_IS_CORE) {
size_t i, j;
unsigned char c;
for (i = 0; i < NOFFSETS; i++) {
unsigned char *cname, *cp;
size_t reloffset = prpsoffsets(i);
size_t noffset = doff + reloffset;
size_t k;
for (j = 0; j < 16; j++, noffset++,
reloffset++) {
if (noffset >= size)
goto tryanother;
if (reloffset >= descsz)
goto tryanother;
c = nbuf[noffset];
if (c == '\0') {
if (j == 0)
goto tryanother;
else
break;
} else {
if (!isprint(c) || isquote(c))
goto tryanother;
}
}
for (k = i + 1 ; k < NOFFSETS; k++) {
size_t no;
int adjust = 1;
if (prpsoffsets(k) >= prpsoffsets(i))
continue;
for (no = doff + prpsoffsets(k);
no < doff + prpsoffsets(i); no++)
adjust = adjust
&& isprint(nbuf[no]);
if (adjust)
i = k;
}
cname = (unsigned char *)
&nbuf[doff + prpsoffsets(i)];
for (cp = cname; cp < nbuf + size && *cp
&& isprint(*cp); cp++)
continue;
while (cp > cname && isspace(cp[-1]))
cp--;
if (file_printf(ms, ", from '%.*s'",
(int)(cp - cname), cname) == -1)
return 1;
*flags |= FLAGS_DID_CORE;
return 1;
tryanother:
;
}
}
break;
}
#endif
return 0;
}

static Jsi_RC jsi_ArrayIndexSubCmd(Jsi_Interp *interp, Jsi_Value *args, Jsi_Value *_this,Jsi_Value **ret, Jsi_Func *funcPtr, int op) {
int istart = 0, n, i = 0, dir=1, idx=-1;
Jsi_Value *seq = Jsi_ValueArrayIndex(interp, args, 0),
*start = Jsi_ValueArrayIndex(interp, args, 1);
Jsi_Obj *obj = _this->d.obj;
if (_this->vt != JSI_VT_OBJECT || !Jsi_ObjIsArray(interp, _this->d.obj))
return Jsi_LogError("expected array object");
if (!seq) {
goto bail;
}
n = Jsi_ObjGetLength(interp, obj);    
if (n == 0) {
goto bail;
}
Jsi_Number nstart;
if (op == 2) {
istart = n-1;
}
if (start && Jsi_GetNumberFromValue(interp,start, &nstart)==JSI_OK) {
istart = (int)nstart;
if (istart > n)
goto bail;
if (istart < 0)
istart = (n+istart);
if (istart<0)
goto bail;
}
if (op == 2) {
istart = n-1;
dir = -1;
}
Jsi_ObjListifyArray(interp, obj);
for (i = istart; ; i+=dir)
{
if ((dir>0 && i>=n) || (dir<0 && i<0) || i>=(int)obj->arrCnt)
break;
if (obj->arr[i] && Jsi_ValueCmp(interp, obj->arr[i], seq, JSI_CMP_EXACT)==0) {
idx = i;
break;
}
}
bail:
if (op == 3)
Jsi_ValueMakeBool(interp, ret, (idx!=-1));
else
Jsi_ValueMakeNumber(interp, ret, idx);
return JSI_OK;
}

MAPI_Attr**
mapi_attr_read (size_t len, unsigned char *buf)
{
size_t idx = 0;
uint32 i,j;
assert(len > 4);
uint32 num_properties = GETINT32(buf+idx);
MAPI_Attr** attrs = CHECKED_XMALLOC (MAPI_Attr*, (num_properties + 1));
idx += 4;
if (!attrs) return NULL;
for (i = 0; i < num_properties; i++)
{
MAPI_Attr* a = attrs[i] = CHECKED_XCALLOC(MAPI_Attr, 1);
MAPI_Value* v = NULL;
CHECKINT16(idx, len); a->type = GETINT16(buf+idx); idx += 2;
CHECKINT16(idx, len); a->name = GETINT16(buf+idx); idx += 2;
if (a->name & GUID_EXISTS_FLAG)
{
a->guid = CHECKED_XMALLOC(GUID, 1);
copy_guid_from_buf(a->guid, buf+idx, len);
idx += sizeof (GUID);
CHECKINT32(idx, len); a->num_names = GETINT32(buf+idx); idx += 4;
if (a->num_names > 0)
{
size_t i;
a->names = CHECKED_XCALLOC(VarLenData, a->num_names);
for (i = 0; i < a->num_names; i++)
{
size_t j;
CHECKINT32(idx, len); a->names[i].len = GETINT32(buf+idx); idx += 4;
a->names[i].data 
= CHECKED_XMALLOC(unsigned char, a->names[i].len);
for (j = 0; j < (a->names[i].len >> 1); j++)
a->names[i].data[j] = (buf+idx)[j*2];
idx += pad_to_4byte(a->names[i].len);
}
}
else
{
CHECKINT32(idx, len); a->name = GETINT32(buf+idx); idx+= 4;
}
}
if (a->type & MULTI_VALUE_FLAG ||
a->type == szMAPI_STRING ||
a->type == szMAPI_UNICODE_STRING ||
a->type == szMAPI_OBJECT ||
a->type == szMAPI_BINARY)
{
CHECKINT32(idx, len); a->num_values = GETINT32(buf+idx);
idx += 4;
}
else
{
a->num_values = 1;
}
if (a->type & MULTI_VALUE_FLAG)
{
a->type -= MULTI_VALUE_FLAG;
}
v = alloc_mapi_values (a);
for (j = 0; j < a->num_values; j++) 
{
switch (a->type)
{
case szMAPI_SHORT:
v->len = 2;
CHECKINT16(idx, len); v->data.bytes2 = GETINT16(buf+idx);
idx += 4;
break;
case szMAPI_INT:
v->len = 4;
CHECKINT32(idx, len); v->data.bytes4 = GETINT32(buf+idx);
idx += 4;
v++;
break;
case szMAPI_FLOAT:
case szMAPI_BOOLEAN: 
v->len = 4;
CHECKINT32(idx, len); v->data.bytes4 = GETINT32(buf+idx);
idx += v->len;
break;
case szMAPI_SYSTIME: 
v->len = 8;
CHECKINT32(idx, len); v->data.bytes8[0] = GETINT32(buf+idx);
CHECKINT32(idx+4, len); v->data.bytes8[1] = GETINT32(buf+idx+4);
idx += 8;
v++;
break;
case szMAPI_DOUBLE:
case szMAPI_APPTIME:
case szMAPI_CURRENCY:
case szMAPI_INT8BYTE:
v->len = 8;
CHECKINT32(idx, len); v->data.bytes8[0] = GETINT32(buf+idx);
CHECKINT32(idx+4, len); v->data.bytes8[1] = GETINT32(buf+idx+4);
idx += v->len;
break;
case szMAPI_CLSID:
v->len = sizeof (GUID);
copy_guid_from_buf(&v->data.guid, buf+idx, len);
idx += v->len;
break;
case szMAPI_STRING:
case szMAPI_UNICODE_STRING:
case szMAPI_OBJECT:
case szMAPI_BINARY:
CHECKINT32(idx, len); v->len = GETINT32(buf+idx); idx += 4;
if (a->type == szMAPI_UNICODE_STRING)
{
v->data.buf = (unsigned char*)unicode_to_utf8(v->len, buf+idx);
}
else
{
v->data.buf = CHECKED_XMALLOC(unsigned char, v->len);
memmove (v->data.buf, buf+idx, v->len);
}
idx += pad_to_4byte(v->len);
v++;
break;
case szMAPI_NULL:
case szMAPI_ERROR:
case szMAPI_UNSPECIFIED:
fprintf (stderr,
"Invalid attribute, input file may be corrupted\n");
if (!ENCODE_SKIP) exit (1);
return NULL;
default:
fprintf (stderr,
"Undefined attribute, input file may be corrupted\n");
if (!ENCODE_SKIP) exit (1);
return NULL;
}
if (DEBUG_ON) mapi_attr_dump (attrs[i]);
}
}
attrs[i] = NULL;
return attrs;
}

static int
make_month(const char *s)
{
