Error ImageLoaderTGA::convert_to_image(Ref<Image> p_image, const uint8_t *p_buffer, const tga_header_s &p_header, const uint8_t *p_palette, const bool p_is_monochrome) {
#define TGA_PUT_PIXEL(r, g, b, a)             \
int image_data_ofs = ((y * width) + x);   \
image_data_w[image_data_ofs * 4 + 0] = r; \
image_data_w[image_data_ofs * 4 + 1] = g; \
image_data_w[image_data_ofs * 4 + 2] = b; \
image_data_w[image_data_ofs * 4 + 3] = a;
uint32_t width = p_header.image_width;
uint32_t height = p_header.image_height;
tga_origin_e origin = static_cast<tga_origin_e>((p_header.image_descriptor & TGA_ORIGIN_MASK) >> TGA_ORIGIN_SHIFT);
uint32_t x_start;
int32_t x_step;
uint32_t x_end;
uint32_t y_start;
int32_t y_step;
uint32_t y_end;
if (origin == TGA_ORIGIN_TOP_LEFT || origin == TGA_ORIGIN_TOP_RIGHT) {
y_start = 0;
y_step = 1;
y_end = height;
} else {
y_start = height - 1;
y_step = -1;
y_end = -1;
}
if (origin == TGA_ORIGIN_TOP_LEFT || origin == TGA_ORIGIN_BOTTOM_LEFT) {
x_start = 0;
x_step = 1;
x_end = width;
} else {
x_start = width - 1;
x_step = -1;
x_end = -1;
}
Vector<uint8_t> image_data;
image_data.resize(width * height * sizeof(uint32_t));
uint8_t *image_data_w = image_data.ptrw();
size_t i = 0;
uint32_t x = x_start;
uint32_t y = y_start;
if (p_header.pixel_depth == 8) {
if (p_is_monochrome) {
while (y != y_end) {
while (x != x_end) {
uint8_t shade = p_buffer[i];
TGA_PUT_PIXEL(shade, shade, shade, 0xff)
x += x_step;
i += 1;
}
x = x_start;
y += y_step;
}
} else {
while (y != y_end) {
while (x != x_end) {
uint8_t index = p_buffer[i];
uint8_t r = 0x00;
uint8_t g = 0x00;
uint8_t b = 0x00;
uint8_t a = 0xff;
if (p_header.color_map_depth == 24) {
r = (p_palette[(index * 3) + 2]);
g = (p_palette[(index * 3) + 1]);
b = (p_palette[(index * 3) + 0]);
} else {
return ERR_INVALID_DATA;
}
TGA_PUT_PIXEL(r, g, b, a)
x += x_step;
i += 1;
}
x = x_start;
y += y_step;
}
}
} else if (p_header.pixel_depth == 24) {
while (y != y_end) {
while (x != x_end) {
uint8_t r = p_buffer[i + 2];
uint8_t g = p_buffer[i + 1];
uint8_t b = p_buffer[i + 0];
TGA_PUT_PIXEL(r, g, b, 0xff)
x += x_step;
i += 3;
}
x = x_start;
y += y_step;
}
} else if (p_header.pixel_depth == 32) {
while (y != y_end) {
while (x != x_end) {
uint8_t a = p_buffer[i + 3];
uint8_t r = p_buffer[i + 2];
uint8_t g = p_buffer[i + 1];
uint8_t b = p_buffer[i + 0];
TGA_PUT_PIXEL(r, g, b, a)
x += x_step;
i += 4;
}
x = x_start;
y += y_step;
}
}
p_image->create(width, height, false, Image::FORMAT_RGBA8, image_data);
return OK;
}

GF_Err ilst_item_box_read(GF_Box *s,GF_BitStream *bs)
{
GF_Err e;
u32 sub_type;
GF_Box *a = NULL;
GF_ListItemBox *ptr = (GF_ListItemBox *)s;
sub_type = gf_bs_peek_bits(bs, 32, 4);
if (sub_type == GF_ISOM_BOX_TYPE_DATA ) {
e = gf_isom_box_parse(&a, bs);
if (!e && ptr->size < a->size) {
GF_LOG(GF_LOG_ERROR, GF_LOG_CONTAINER, ("[isom] not enough bytes in box %s: %d left, reading %d (file %s, line %d)\n", gf_4cc_to_str(ptr->type), ptr->size, a->size, __FILE__, __LINE__ )); \
e = GF_ISOM_INVALID_FILE;
}
if (e) {
if (a) gf_isom_box_del(a);
return e;
}
ISOM_DECREASE_SIZE(ptr, a->size);
if (a && ptr->data) gf_isom_box_del_parent(&ptr->child_boxes, (GF_Box *) ptr->data);
if (a && a->size > 4 && a->type != GF_ISOM_BOX_TYPE_VOID) {
ptr->data = (GF_DataBox *)a;
if (!ptr->child_boxes) ptr->child_boxes = gf_list_new();
gf_list_add(ptr->child_boxes, ptr->data);
} else {
ptr->data = NULL;
gf_isom_box_del(a);
}
}
else {
u64 pos = gf_bs_get_position(bs);
u64 prev_size = s->size;
e = gf_isom_box_array_read(s, bs, NULL);
if (e==GF_OK) return GF_OK;
gf_isom_box_array_del(s->child_boxes);
s->child_boxes=NULL;
gf_bs_seek(bs, pos);
s->size = prev_size;
ptr->data = (GF_DataBox *)gf_isom_box_new_parent(&ptr->child_boxes, GF_ISOM_BOX_TYPE_DATA);
ptr->data->qt_style = GF_TRUE;
ISOM_DECREASE_SIZE(ptr, 2);
ptr->data->dataSize = gf_bs_read_u16(bs);
gf_bs_read_u16(bs);
ptr->data->data = (char *) gf_malloc(sizeof(char)*(ptr->data->dataSize + 1));
gf_bs_read_data(bs, ptr->data->data, ptr->data->dataSize);
ptr->data->data[ptr->data->dataSize] = 0;
ISOM_DECREASE_SIZE(ptr, ptr->data->dataSize);
}
return GF_OK;
}

MmsValue*
MmsValue_decodeMmsData(uint8_t* buffer, int bufPos, int bufferLength, int* endBufPos)
{
MmsValue* value = NULL;
int dataEndBufPos = bufPos + bufferLength;
uint8_t tag = buffer[bufPos++];
int dataLength;
bufPos = BerDecoder_decodeLength(buffer, &dataLength, bufPos, dataEndBufPos);
if (bufPos < 0)
goto exit_with_error;
switch (tag) {
case 0xa1: 
case 0xa2: 
{
int elementCount = getNumberOfElements(buffer, bufPos, dataLength);
if (tag == 0xa1)
value = MmsValue_createEmptyArray(elementCount);
else
value = MmsValue_createEmptyStructure(elementCount);
int i;
for (i = 0; i < elementCount; i++) {
int elementLength;
int newBufPos = BerDecoder_decodeLength(buffer, &elementLength, bufPos + 1, dataEndBufPos);
if (newBufPos < 0)
goto exit_with_error;
MmsValue* elementValue = MmsValue_decodeMmsData(buffer, bufPos, dataLength, NULL);
if (elementValue == NULL)
goto exit_with_error;
MmsValue_setElement(value, i, elementValue);
bufPos = newBufPos + elementLength;
}
if (value == NULL)
goto exit_with_error;
}
break;
case 0x80: 
value = MmsValue_newDataAccessError((MmsDataAccessError) BerDecoder_decodeUint32(buffer, dataLength, bufPos));
bufPos += dataLength;
break;
case 0x83: 
value = MmsValue_newBoolean(BerDecoder_decodeBoolean(buffer, bufPos));
bufPos += dataLength;
break;
case 0x84: 
{
int padding = buffer[bufPos];
int bitStringLength = (8 * (dataLength - 1)) - padding;
value = MmsValue_newBitString(bitStringLength);
memcpy(value->value.bitString.buf, buffer + bufPos + 1, dataLength - 1);
bufPos += dataLength;
}
break;
case 0x85: 
value = MmsValue_newInteger(dataLength * 8);
memcpy(value->value.integer->octets, buffer + bufPos, dataLength);
value->value.integer->size = dataLength;
bufPos += dataLength;
break;
case 0x86: 
value = MmsValue_newUnsigned(dataLength * 8);
memcpy(value->value.integer->octets, buffer + bufPos, dataLength);
value->value.integer->size = dataLength;
bufPos += dataLength;
break;
case 0x87: 
if (dataLength == 9)
value = MmsValue_newDouble(BerDecoder_decodeDouble(buffer, bufPos));
else if (dataLength == 5)
value = MmsValue_newFloat(BerDecoder_decodeFloat(buffer, bufPos));
bufPos += dataLength;
break;
case 0x89: 
value = MmsValue_newOctetString(dataLength, dataLength);
memcpy(value->value.octetString.buf, buffer + bufPos, dataLength);
bufPos += dataLength;
break;
case 0x8a: 
value = MmsValue_newVisibleStringFromByteArray(buffer + bufPos, dataLength);
bufPos += dataLength;
break;
case 0x8c: 
if (dataLength == 4)
value = MmsValue_newBinaryTime(true);
else if (dataLength == 6)
value = MmsValue_newBinaryTime(false);
if ((dataLength == 4) || (dataLength == 6))
memcpy(value->value.binaryTime.buf, buffer + bufPos, dataLength);
bufPos += dataLength;
break;
case 0x90: 
value = MmsValue_newVisibleStringFromByteArray(buffer + bufPos, dataLength);
value->type = MMS_STRING;
bufPos += dataLength;
break;
case 0x91: 
if (dataLength == 8) {
value = MmsValue_newUtcTime(0);
MmsValue_setUtcTimeByBuffer(value, buffer + bufPos);
bufPos += dataLength;
}
else
goto exit_with_error;
break;
default: 
goto exit_with_error;
}
if (endBufPos != NULL)
*endBufPos = bufPos;
return value;
exit_with_error:
if (value != NULL)
MmsValue_delete(value);
return NULL;
}

