bool DNP3_Base::AddToBuffer(Endpoint* endp, int target_len, const u_char** data, int* len)
{
if ( ! target_len )
return true;
int to_copy = min(*len, target_len - endp->buffer_len);
memcpy(endp->buffer + endp->buffer_len, *data, to_copy);
*data += to_copy;
*len -= to_copy;
endp->buffer_len += to_copy;
return endp->buffer_len == target_len;
}

static int
image_load_gif(image_t *img,
FILE    *fp,
int     gray,
int     load_data)
{
ucharbuf[1024];
gif_cmap_tcmap;
intncolors,
transparent;
fread(buf, 13, 1, fp);
img->width  = (buf[7] << 8) | buf[6];
img->height = (buf[9] << 8) | buf[8];
ncolors     = 2 << (buf[10] & 0x07);
if (img->width <= 0 || img->width > 32767 || img->height <= 0 || img->height > 32767)
return (-1);
if (Encryption)
img->use ++;
if (buf[10] & GIF_COLORMAP)
if (gif_read_cmap(fp, ncolors, cmap, &gray))
return (-1);
transparent = -1;
while (1)
{
switch (getc(fp))
{
case ';' :
return (-1);
case '!' :
buf[0] = (uchar)getc(fp);
if (buf[0] == 0xf9)
{
gif_get_block(fp, buf);
if (buf[0] & 1)
transparent = buf[3];
}
while (gif_get_block(fp, buf) != 0);
break;
case ',' :
fread(buf, 9, 1, fp);
if (buf[8] & GIF_COLORMAP)
{
ncolors = 2 << (buf[8] & 0x07);
if (gif_read_cmap(fp, ncolors, cmap, &gray))
return (-1);
}
img->width  = (buf[5] << 8) | buf[4];
img->height = (buf[7] << 8) | buf[6];
img->depth  = gray ? 1 : 3;
if (img->width <= 0 || img->width > 32767 || img->height <= 0 || img->height > 32767)
return (-1);
if (transparent >= 0)
{
if (BodyColor[0])
{
float rgb[3]; 
get_color((uchar *)BodyColor, rgb);
cmap[transparent][0] = (uchar)(rgb[0] * 255.0f + 0.5f);
cmap[transparent][1] = (uchar)(rgb[1] * 255.0f + 0.5f);
cmap[transparent][2] = (uchar)(rgb[2] * 255.0f + 0.5f);
}
else
{
cmap[transparent][0] = 255;
cmap[transparent][1] = 255;
cmap[transparent][2] = 255;
}
image_need_mask(img);
}
if (!load_data)
return (0);
img->pixels = (uchar *)malloc((size_t)(img->width * img->height * img->depth));
if (img->pixels == NULL)
return (-1);
return (gif_read_image(fp, img, cmap, buf[8] & GIF_INTERLACE, transparent));
}
}
}

static COUNTER
process_raw_packets(pcap_t * pcap)
{
ipv4_hdr_t *ip_hdr = NULL;
ipv6_hdr_t *ip6_hdr = NULL;
eth_hdr_t *eth_hdr = NULL;
struct pcap_pkthdr pkthdr;
const u_char *pktdata = NULL;
COUNTER packetnum = 0;
int l2len;
u_char ipbuff[MAXPACKET], *buffptr;
tcpr_dir_t direction = TCPR_DIR_ERROR;
tcpprep_opt_t *options = tcpprep->options;
assert(pcap);
while ((pktdata = pcap_next(pcap, &pkthdr)) != NULL) {
packetnum++;
dbgx(1, "Packet " COUNTER_SPEC, packetnum);
if (options->xX.list != NULL) {
if (options->xX.mode < xXExclude) {
if (!check_list(options->xX.list, packetnum)) {
add_cache(&(options->cachedata), DONT_SEND, 0);
continue;
}
}
else if (check_list(options->xX.list, packetnum)) {
add_cache(&(options->cachedata), DONT_SEND, 0);
continue;
}
}
if (options->mode != MAC_MODE) {
dbg(3, "Looking for IPv4/v6 header in non-MAC mode");
buffptr = ipbuff;
if ((ip_hdr = (ipv4_hdr_t *)get_ipv4(pktdata, pkthdr.caplen, 
pcap_datalink(pcap), &buffptr))) {
dbg(2, "Packet is IPv4");
} else if ((ip6_hdr = (ipv6_hdr_t *)get_ipv6(pktdata, pkthdr.caplen,
pcap_datalink(pcap), &buffptr))) {
dbg(2, "Packet is IPv6");    
} else {
dbg(2, "Packet isn't IPv4/v6");
if (options->mode != AUTO_MODE) {
dbg(3, "Adding to cache using options for Non-IP packets");
add_cache(&options->cachedata, SEND, options->nonip);
}
continue;
}
l2len = get_l2len(pktdata, pkthdr.caplen, pcap_datalink(pcap));
if (l2len < 0) {
continue;
}
if (options->xX.cidr != NULL) {
if (ip_hdr) {
if (!process_xX_by_cidr_ipv4(options->xX.mode, options->xX.cidr, ip_hdr)) {
add_cache(&options->cachedata, DONT_SEND, 0);
continue;
}
} else if (ip6_hdr) {
if (!process_xX_by_cidr_ipv6(options->xX.mode, options->xX.cidr, ip6_hdr)) {
add_cache(&options->cachedata, DONT_SEND, 0);
continue;
}
}
}
}
switch (options->mode) {
case REGEX_MODE:
dbg(2, "processing regex mode...");
if (ip_hdr) {
direction = check_ipv4_regex(ip_hdr->ip_src.s_addr);
} else if (ip6_hdr) {
direction = check_ipv6_regex(&ip6_hdr->ip_src);
}
if (HAVE_OPT(REVERSE) && (direction == TCPR_DIR_C2S || direction == TCPR_DIR_S2C))
direction = direction == TCPR_DIR_C2S ? TCPR_DIR_S2C : TCPR_DIR_C2S;
add_cache(&options->cachedata, SEND, direction);
break;
case CIDR_MODE:
dbg(2, "processing cidr mode...");
if (ip_hdr) {
direction = check_ip_cidr(options->cidrdata, ip_hdr->ip_src.s_addr) ? TCPR_DIR_C2S : TCPR_DIR_S2C;
} else if (ip6_hdr) {
direction = check_ip6_cidr(options->cidrdata, &ip6_hdr->ip_src) ? TCPR_DIR_C2S : TCPR_DIR_S2C;
}
if (HAVE_OPT(REVERSE) && (direction == TCPR_DIR_C2S || direction == TCPR_DIR_S2C))
direction = direction == TCPR_DIR_C2S ? TCPR_DIR_S2C : TCPR_DIR_C2S;
add_cache(&options->cachedata, SEND, direction);
break;
case MAC_MODE:
dbg(2, "processing mac mode...");
if (pkthdr.caplen < sizeof(*eth_hdr)) {
dbg(2, "capture length too short for mac mode processing");
break;
}
eth_hdr = (eth_hdr_t *)pktdata;
direction = macinstring(options->maclist, (u_char *)eth_hdr->ether_shost);
if (HAVE_OPT(REVERSE) && (direction == TCPR_DIR_C2S || direction == TCPR_DIR_S2C))
direction = direction == TCPR_DIR_C2S ? TCPR_DIR_S2C : TCPR_DIR_C2S;
add_cache(&options->cachedata, SEND, direction);
break;
case AUTO_MODE:
dbg(2, "processing first pass of auto mode...");
if (options->automode != FIRST_MODE) {
if (ip_hdr) {
add_tree_ipv4(ip_hdr->ip_src.s_addr, pktdata, pkthdr.caplen);
} else if (ip6_hdr) {
add_tree_ipv6(&ip6_hdr->ip_src, pktdata, pkthdr.caplen);
}
} else {
if (ip_hdr) {
add_tree_first_ipv4(pktdata, pkthdr.caplen);
} else if (ip6_hdr) {
add_tree_first_ipv6(pktdata, pkthdr.caplen);
}
}  
break;
case ROUTER_MODE:
dbg(2, "processing second pass of auto: router mode...");
if (ip_hdr) {
add_cache(&options->cachedata, SEND,
check_ip_tree(options->nonip, ip_hdr->ip_src.s_addr));
} else {
add_cache(&options->cachedata, SEND,
check_ip6_tree(options->nonip, &ip6_hdr->ip_src));
}
break;
case BRIDGE_MODE:
dbg(2, "processing second pass of auto: bridge mode...");
if (ip_hdr) {
add_cache(&options->cachedata, SEND,
check_ip_tree(DIR_UNKNOWN, ip_hdr->ip_src.s_addr));
} else {
add_cache(&options->cachedata, SEND,
check_ip6_tree(DIR_UNKNOWN, &ip6_hdr->ip_src));
}
break;
case SERVER_MODE:
dbg(2, "processing second pass of auto: server mode...");
if (ip_hdr) {
add_cache(&options->cachedata, SEND,
check_ip_tree(DIR_SERVER, ip_hdr->ip_src.s_addr));
} else {
add_cache(&options->cachedata, SEND,
check_ip6_tree(DIR_SERVER, &ip6_hdr->ip_src));
}
break;
case CLIENT_MODE:
dbg(2, "processing second pass of auto: client mode...");
if (ip_hdr) {
add_cache(&options->cachedata, SEND,
check_ip_tree(DIR_CLIENT, ip_hdr->ip_src.s_addr));
} else {
add_cache(&options->cachedata, SEND,
check_ip6_tree(DIR_CLIENT, &ip6_hdr->ip_src));
}
break;
case PORT_MODE:
dbg(2, "processing port mode...");
add_cache(&options->cachedata, SEND,
check_dst_port(ip_hdr, ip6_hdr, (pkthdr.caplen - l2len)));
break;
case FIRST_MODE:
dbg(2, "processing second pass of auto: first packet mode...");
if (ip_hdr) {
add_cache(&options->cachedata, SEND,
check_ip_tree(DIR_UNKNOWN, ip_hdr->ip_src.s_addr));
} else {
add_cache(&options->cachedata, SEND,
check_ip6_tree(DIR_UNKNOWN, &ip6_hdr->ip_src));
}
break;
default:
errx(-1, "Whoops!  What mode are we in anyways? %d", options->mode);
}
#ifdef ENABLE_VERBOSE
if (options->verbose)
tcpdump_print(&tcpprep->tcpdump, &pkthdr, pktdata);
#endif
}
return packetnum;
}

static char *parse_name(struct state *state) {
const char *s = state->pos;
char *result;
while (*state->pos != '\0' && strchr(name_follow, *state->pos) == NULL) {
if (STREQLEN(state->pos, " or ", strlen(" or ")) ||
STREQLEN(state->pos, " and ", strlen(" and ")))
break;
if (*state->pos == '\\') {
state->pos += 1;
if (*state->pos == '\0') {
STATE_ERROR(state, PATHX_ENAME);
return NULL;
}
}
state->pos += 1;
}
if (state->pos > s) {
state->pos -= 1;
while (isspace(*state->pos) && state->pos >= s)
state->pos -= 1;
state->pos += 1;
}
if (state->pos == s) {
STATE_ERROR(state, PATHX_ENAME);
return NULL;
}
result = strndup(s, state->pos - s);
if (result == NULL) {
STATE_ENOMEM;
return NULL;
}
char *p = result;
for (char *t = result; *t != '\0'; t++, p++) {
if (*t == '\\')
t += 1;
*p = *t;
}
*p = '\0';
return result;
}

