sdp_payload_attr_t *payload;
char *cur, *tmp, *buff, temp;
struct lump * lmp;
str found;
int ret, i,match, buff_len, is_static;
regmatch_t pmatch;
lmp = get_associated_lump(msg, cell);
if( lmp == NULL)
{
