goto end;
}
memcpy(tmp, " 0 ", 3);
if (!insert_new_lump_after(lmp, tmp, 3, 0))
LM_ERR("could not insert lump to disable stream!\n");
}
end:
pkg_free(buff);
return ret;
}

static int nf_tables_delchain(struct sk_buff *skb, const struct nfnl_info *info,
const struct nlattr * const nla[])
{
struct netlink_ext_ack *extack = info->extack;
u8 genmask = nft_genmask_next(info->net);
u8 family = info->nfmsg->nfgen_family;
struct net *net = info->net;
const struct nlattr *attr;
struct nft_table *table;
struct nft_chain *chain;
struct nft_rule *rule;
struct nft_ctx ctx;
u64 handle;
u32 use;
int err;
table = nft_table_lookup(net, nla[NFTA_CHAIN_TABLE], family, genmask,
NETLINK_CB(skb).portid);
if (IS_ERR(table)) {
NL_SET_BAD_ATTR(extack, nla[NFTA_CHAIN_TABLE]);
return PTR_ERR(table);
}
if (nla[NFTA_CHAIN_HANDLE]) {
attr = nla[NFTA_CHAIN_HANDLE];
handle = be64_to_cpu(nla_get_be64(attr));
chain = nft_chain_lookup_byhandle(table, handle, genmask);
} else {
attr = nla[NFTA_CHAIN_NAME];
chain = nft_chain_lookup(net, table, attr, genmask);
}
if (IS_ERR(chain)) {
if (PTR_ERR(chain) == -ENOENT &&
NFNL_MSG_TYPE(info->nlh->nlmsg_type) == NFT_MSG_DESTROYCHAIN)
return 0;
NL_SET_BAD_ATTR(extack, attr);
return PTR_ERR(chain);
}
nft_ctx_init(&ctx, net, skb, info->nlh, family, table, chain, nla);
if (nla[NFTA_CHAIN_HOOK]) {
if (chain->flags & NFT_CHAIN_HW_OFFLOAD)
return -EOPNOTSUPP;
if (nft_is_base_chain(chain)) {
struct nft_base_chain *basechain = nft_base_chain(chain);
if (nft_base_chain_netdev(table->family, basechain->ops.hooknum))
return nft_delchain_hook(&ctx, basechain, extack);
}
}
if (info->nlh->nlmsg_flags & NLM_F_NONREC &&
chain->use > 0)
return -EBUSY;
use = chain->use;
list_for_each_entry(rule, &chain->rules, list) {
if (!nft_is_active_next(net, rule))
continue;
use--;
err = nft_delrule(&ctx, rule);
if (err < 0)
return err;
}
if (use > 0) {
NL_SET_BAD_ATTR(extack, attr);
return -EBUSY;
}
return nft_delchain(&ctx);
}

static int cuse_channel_open(struct inode *inode, struct file *file)
{
struct cuse_conn *cc;
int rc;
cc = kzalloc(sizeof(*cc), GFP_KERNEL);
if (!cc)
return -ENOMEM;
fuse_conn_init(&cc->fc);
INIT_LIST_HEAD(&cc->list);
cc->fc.release = cuse_fc_release;
cc->fc.initialized = 1;
rc = cuse_send_init(cc);
if (rc) {
fuse_conn_put(&cc->fc);
return rc;
}
file->private_data = &cc->fc;
return 0;
}

static size_t transcodeQ23ToFloat(uint8_t* buffer, size_t length,
BtifAvrcpAudioTrack* trackHolder) {
size_t sampleSize = sampleSizeFor(trackHolder);
size_t i = 0;
for (; i <= length / sampleSize; i++) {
size_t offset = i * sampleSize;
int32_t sample = *((int32_t*)(buffer + offset - 1)) & 0x00FFFFFF;
trackHolder->buffer[i] = sample * kScaleQ23ToFloat;
}
return i * sampleSize;
}

void CompactProtocolReader::readStringBody(StrType& str, int32_t size) {
if (static_cast<int32_t>(in_.length()) < size) {
str.reserve(size);   }
str.clear();
size_t size_left = size;
while (size_left > 0) {
auto data = in_.peekBytes();
auto data_avail = std::min(data.size(), size_left);
if (data.empty()) {
TProtocolException::throwExceededSizeLimit();
}
str.append((const char*)data.data(), data_avail);
size_left -= data_avail;
in_.skipNoAdvance(data_avail);
}
}

static jobject
getMethodAt(JNIEnv *env, jobject constantPoolOop, jint cpIndex, UDATA resolveFlags)
{
jobject returnValue = NULL;
J9VMThread *vmThread = (J9VMThread *) env;
J9InternalVMFunctions *vmFunctions = vmThread->javaVM->internalVMFunctions;
SunReflectCPResult result = NULL_POINTER_EXCEPTION;
jmethodID methodID = NULL;
UDATA cpType = J9CPTYPE_UNUSED;
if (NULL != constantPoolOop) {
J9RAMConstantRef *ramConstantRef = NULL;
jclass jlClass = NULL;
vmFunctions->internalEnterVMFromJNI(vmThread);
result = getRAMConstantRefAndType(vmThread, constantPoolOop, cpIndex, &cpType, &ramConstantRef);
if (OK == result) {
J9Method *method = NULL;
J9Class *cpClass = J9CLASS_FROMCPINTERNALRAMCLASS(vmThread, constantPoolOop);
J9ConstantPool *constantPool = J9_CP_FROM_CLASS(cpClass);
switch (cpType) {
case J9CPTYPE_HANDLE_METHOD: 
case J9CPTYPE_INSTANCE_METHOD: 
case J9CPTYPE_INTERFACE_INSTANCE_METHOD:
method = ((J9RAMMethodRef *) ramConstantRef)->method;
if ((NULL == method) || (NULL == method->constantPool)) {
if (0 == vmFunctions->resolveVirtualMethodRef(vmThread, constantPool, cpIndex, resolveFlags, &method)) {
clearException(vmThread);
method = vmFunctions->resolveSpecialMethodRef(vmThread, constantPool, cpIndex, resolveFlags);
}
if (NULL == method) {
clearException(vmThread);
method = vmFunctions->resolveStaticMethodRefInto(vmThread, constantPool, cpIndex, resolveFlags, NULL);
}
}
break;
case J9CPTYPE_STATIC_METHOD: 
case J9CPTYPE_INTERFACE_STATIC_METHOD:
method = ((J9RAMStaticMethodRef *) ramConstantRef)->method;
if ((NULL == method) || (NULL == method->constantPool)) {
method = vmFunctions->resolveStaticMethodRef(vmThread, constantPool, cpIndex, resolveFlags);
if (NULL == method) {
clearException(vmThread);
vmFunctions->resolveVirtualMethodRef(vmThread, constantPool, cpIndex, resolveFlags, &method);
}
}
break;
case J9CPTYPE_INTERFACE_METHOD:
method = vmFunctions->resolveInterfaceMethodRef(vmThread, constantPool, cpIndex, resolveFlags);
break;
default:
result = WRONG_CP_ENTRY_TYPE_EXCEPTION;
break;
}
if (NULL != method) {
methodID = (jmethodID) vmFunctions->getJNIMethodID(vmThread, method);
jlClass = vmFunctions->j9jni_createLocalRef(env, cpClass->classObject);
}
}
vmFunctions->internalExitVMToJNI(vmThread);
if (NULL != methodID) {
if (NULL != jlClass) {
const jboolean isStatic = (J9CPTYPE_STATIC_METHOD == cpType) || (J9CPTYPE_INTERFACE_STATIC_METHOD == cpType);
returnValue = (*env)->ToReflectedMethod(env, jlClass, methodID, isStatic);
} else {
vmFunctions->throwNativeOOMError(env, 0, 0);
}
}
}
checkResult(env, result);
return returnValue;
}

