static void dump_od_to_saf(GF_SceneDumper *dumper, GF_AUContext *au, u32 indent)
{
u32 i, count;
count = gf_list_count(au->commands);
for (i=0; i<count; i++) {
u32 j, c2;
GF_ODUpdate *com = (GF_ODUpdate *)gf_list_get(au->commands, i);
if (com->tag != GF_ODF_OD_UPDATE_TAG) continue;
c2 = gf_list_count(com->objectDescriptors);
for (j=0; j<c2; j++) {
GF_ObjectDescriptor *od = (GF_ObjectDescriptor *)gf_list_get(com->objectDescriptors, j);
GF_ESD *esd = (GF_ESD *) gf_list_get(od->ESDescriptors, 0);
GF_MuxInfo *mux;
if (!esd) {
if (od->URLString) {
gf_fprintf(dumper->trace, "<saf:RemoteStreamHeader streamID=\"stream%d\" url=\"%s\"", au->owner->ESID, od->URLString);
if (au->timing) gf_fprintf(dumper->trace, " time=\""LLD"\"", au->timing);
gf_fprintf(dumper->trace, "/>\n");
}
continue;
}
mux = (GF_MuxInfo *)gf_list_get(esd->extensionDescriptors, 0);
if (!mux || (mux->tag!=GF_ODF_MUXINFO_TAG)) mux = NULL;
gf_fprintf(dumper->trace, "<saf:mediaHeader streamID=\"stream%d\"", esd->ESID);
gf_fprintf(dumper->trace, " streamType=\"%d\" objectTypeIndication=\"%d\" timeStampResolution=\"%d\"", esd->decoderConfig->streamType, esd->decoderConfig->objectTypeIndication, au->owner->timeScale);
if (au->timing) gf_fprintf(dumper->trace, " time=\""LLD"\"", au->timing);
if (mux && mux->file_name) gf_fprintf(dumper->trace, " source=\"%s\"", mux->file_name);
gf_fprintf(dumper->trace, "/>\n");
}
}
gf_fprintf(dumper->trace, "</saf:mediaUnit>\n");
}

bfd_boolean
load_debug_section (enum dwarf_section_display_enum debug, void * data)
{
struct dwarf_section * section = &debug_displays [debug].section;
Elf_Internal_Shdr * sec;
Filedata * filedata = (Filedata *) data;
if (filedata->string_table == NULL)
{
Elf_Internal_Shdr * strs;
strs = filedata->section_headers + filedata->file_header.e_shstrndx;
if (strs != NULL && strs->sh_size != 0)
{
filedata->string_table = (char *) get_data (NULL, filedata, strs->sh_offset,
1, strs->sh_size,
_("string table"));
filedata->string_table_length = filedata->string_table != NULL ? strs->sh_size : 0;
}
}
sec = find_section_in_set (filedata, section->uncompressed_name, section_subset);
if (sec != NULL)
section->name = section->uncompressed_name;
else
{
sec = find_section_in_set (filedata, section->compressed_name, section_subset);
if (sec != NULL)
section->name = section->compressed_name;
}
if (sec == NULL)
return FALSE;
if (section_subset != NULL)
free_debug_section (debug);
return load_specific_debug_section (debug, sec, data);
}

WireToErrorType XESetWireToError(
Display *dpy,
int error_number,
WireToErrorType proc)
{
register WireToErrorType oldproc = NULL;
if (proc == NULL) proc = (WireToErrorType)_XDefaultWireError;
LockDisplay (dpy);
if (!dpy->error_vec) {
int i;
dpy->error_vec = Xmalloc(256 * sizeof(oldproc));
for (i = 1; i < 256; i++)
dpy->error_vec[i] = _XDefaultWireError;
}
if (dpy->error_vec) {
oldproc = dpy->error_vec[error_number];
dpy->error_vec[error_number] = proc;
}
UnlockDisplay (dpy);
return (WireToErrorType)oldproc;
}

