static int sanity_check_raw_super(struct f2fs_sb_info *sbi,
struct buffer_head *bh)
{
block_t segment_count, segs_per_sec, secs_per_zone;
block_t total_sections, blocks_per_seg;
struct f2fs_super_block *raw_super = (struct f2fs_super_block *)
(bh->b_data + F2FS_SUPER_OFFSET);
struct super_block *sb = sbi->sb;
unsigned int blocksize;
if (F2FS_SUPER_MAGIC != le32_to_cpu(raw_super->magic)) {
f2fs_msg(sb, KERN_INFO,
"Magic Mismatch, valid(0x%x) - read(0x%x)",
F2FS_SUPER_MAGIC, le32_to_cpu(raw_super->magic));
return 1;
}
if (F2FS_BLKSIZE != PAGE_SIZE) {
f2fs_msg(sb, KERN_INFO,
"Invalid page_cache_size (%lu), supports only 4KB\n",
PAGE_SIZE);
return 1;
}
blocksize = 1 << le32_to_cpu(raw_super->log_blocksize);
if (blocksize != F2FS_BLKSIZE) {
f2fs_msg(sb, KERN_INFO,
"Invalid blocksize (%u), supports only 4KB\n",
blocksize);
return 1;
}
if (le32_to_cpu(raw_super->log_blocks_per_seg) != 9) {
f2fs_msg(sb, KERN_INFO,
"Invalid log blocks per segment (%u)\n",
le32_to_cpu(raw_super->log_blocks_per_seg));
return 1;
}
if (le32_to_cpu(raw_super->log_sectorsize) >
F2FS_MAX_LOG_SECTOR_SIZE ||
le32_to_cpu(raw_super->log_sectorsize) <
F2FS_MIN_LOG_SECTOR_SIZE) {
f2fs_msg(sb, KERN_INFO, "Invalid log sectorsize (%u)",
le32_to_cpu(raw_super->log_sectorsize));
return 1;
}
if (le32_to_cpu(raw_super->log_sectors_per_block) +
le32_to_cpu(raw_super->log_sectorsize) !=
F2FS_MAX_LOG_SECTOR_SIZE) {
f2fs_msg(sb, KERN_INFO,
"Invalid log sectors per block(%u) log sectorsize(%u)",
le32_to_cpu(raw_super->log_sectors_per_block),
le32_to_cpu(raw_super->log_sectorsize));
return 1;
}
segment_count = le32_to_cpu(raw_super->segment_count);
segs_per_sec = le32_to_cpu(raw_super->segs_per_sec);
secs_per_zone = le32_to_cpu(raw_super->secs_per_zone);
total_sections = le32_to_cpu(raw_super->section_count);
blocks_per_seg = 1 << le32_to_cpu(raw_super->log_blocks_per_seg);
if (segment_count > F2FS_MAX_SEGMENT ||
segment_count < F2FS_MIN_SEGMENTS) {
f2fs_msg(sb, KERN_INFO,
"Invalid segment count (%u)",
segment_count);
return 1;
}
if (total_sections > segment_count ||
total_sections < F2FS_MIN_SEGMENTS ||
segs_per_sec > segment_count || !segs_per_sec) {
f2fs_msg(sb, KERN_INFO,
"Invalid segment/section count (%u, %u x %u)",
segment_count, total_sections, segs_per_sec);
return 1;
}
if ((segment_count / segs_per_sec) < total_sections) {
f2fs_msg(sb, KERN_INFO,
"Small segment_count (%u < %u * %u)",
segment_count, segs_per_sec, total_sections);
return 1;
}
if (segment_count > (le32_to_cpu(raw_super->block_count) >> 9)) {
f2fs_msg(sb, KERN_INFO,
"Wrong segment_count / block_count (%u > %u)",
segment_count, le32_to_cpu(raw_super->block_count));
return 1;
}
if (secs_per_zone > total_sections) {
f2fs_msg(sb, KERN_INFO,
"Wrong secs_per_zone (%u > %u)",
secs_per_zone, total_sections);
return 1;
}
if (le32_to_cpu(raw_super->extension_count) > F2FS_MAX_EXTENSION ||
raw_super->hot_ext_count > F2FS_MAX_EXTENSION ||
(le32_to_cpu(raw_super->extension_count) +
raw_super->hot_ext_count) > F2FS_MAX_EXTENSION) {
f2fs_msg(sb, KERN_INFO,
"Corrupted extension count (%u + %u > %u)",
le32_to_cpu(raw_super->extension_count),
raw_super->hot_ext_count,
F2FS_MAX_EXTENSION);
return 1;
}
if (le32_to_cpu(raw_super->cp_payload) >
(blocks_per_seg - F2FS_CP_PACKS)) {
f2fs_msg(sb, KERN_INFO,
"Insane cp_payload (%u > %u)",
le32_to_cpu(raw_super->cp_payload),
blocks_per_seg - F2FS_CP_PACKS);
return 1;
}
if (le32_to_cpu(raw_super->node_ino) != 1 ||
le32_to_cpu(raw_super->meta_ino) != 2 ||
le32_to_cpu(raw_super->root_ino) != 3) {
f2fs_msg(sb, KERN_INFO,
"Invalid Fs Meta Ino: node(%u) meta(%u) root(%u)",
le32_to_cpu(raw_super->node_ino),
le32_to_cpu(raw_super->meta_ino),
le32_to_cpu(raw_super->root_ino));
return 1;
}
if (sanity_check_area_boundary(sbi, bh))
return 1;
return 0;
}

bool outline_stroke(ASS_Outline *result, ASS_Outline *result1,
const ASS_Outline *path, int xbord, int ybord, int eps)
{
outline_alloc(result,  2 * path->n_points, 2 * path->n_segments);
outline_alloc(result1, 2 * path->n_points, 2 * path->n_segments);
if (!result->max_points || !result1->max_points)
return false;
const int dir = 3;
int rad = FFMAX(xbord, ybord);
assert(rad >= eps);
StrokerState str;
str.result[0] = result;
str.result[1] = result1;
str.contour_first[0] = 0;
str.contour_first[1] = 0;
str.xbord = xbord;
str.ybord = ybord;
str.xscale = 1.0 / FFMAX(eps, xbord);
str.yscale = 1.0 / FFMAX(eps, ybord);
str.eps = eps;
str.contour_start = true;
double rel_err = (double) eps / rad;
str.merge_cos = 1 - rel_err;
double e = sqrt(2 * rel_err);
str.split_cos = 1 + 8 * rel_err - 4 * (1 + rel_err) * e;
str.min_len = rel_err / 4;
str.err_q = 8 * (1 + rel_err) * (1 + rel_err);
str.err_c = 390 * rel_err * rel_err;
str.err_a = e;
for (size_t i = 0; i < path->n_points; i++) {
if (path->points[i].x < OUTLINE_MIN || path->points[i].x > OUTLINE_MAX)
return false;
if (path->points[i].y < OUTLINE_MIN || path->points[i].y > OUTLINE_MAX)
return false;
}
ASS_Vector *start = path->points, *cur = start;
for (size_t i = 0; i < path->n_segments; i++) {
if (start == cur)
str.last_point = *start;
int n = path->segments[i] & OUTLINE_COUNT_MASK;
cur += n;
ASS_Vector *end = cur;
if (path->segments[i] & OUTLINE_CONTOUR_END) {
end = start;
start = cur;
}
switch (n) {
case OUTLINE_LINE_SEGMENT:
if (!add_line(&str, *end, dir))
return false;
break;
case OUTLINE_QUADRATIC_SPLINE:
if (!add_quadratic(&str, cur[-1], *end, dir))
return false;
break;
case OUTLINE_CUBIC_SPLINE:
if (!add_cubic(&str, cur[-2], cur[-1], *end, dir))
return false;
break;
default:
return false;
}
if (start == cur && !close_contour(&str, dir))
return false;
}
assert(start == cur && cur == path->points + path->n_points);
return true;
}

FT_LOCAL_DEF( FT_Error )
sfnt_init_face( FT_Stream      stream,
TT_Face        face,
FT_Int         face_instance_index,
FT_Int         num_params,
FT_Parameter*  params )
{
FT_Error      error;
FT_Memory     memory = face->root.memory;
FT_Library    library = face->root.driver->root.library;
SFNT_Service  sfnt;
FT_Int        face_index;
FT_UNUSED( num_params );
FT_UNUSED( params );
sfnt = (SFNT_Service)face->sfnt;
if ( !sfnt )
{
sfnt = (SFNT_Service)FT_Get_Module_Interface( library, "sfnt" );
if ( !sfnt )
{
FT_ERROR(( "sfnt_init_face: cannot access `sfnt' module\n" ));
return FT_THROW( Missing_Module );
}
face->sfnt       = sfnt;
face->goto_table = sfnt->goto_table;
}
FT_FACE_FIND_GLOBAL_SERVICE( face, face->psnames, POSTSCRIPT_CMAPS );
#ifdef TT_CONFIG_OPTION_GX_VAR_SUPPORT
if ( !face->mm )
{
FT_Module  tt_module = FT_Get_Module( library, "truetype" );
face->mm = ft_module_get_service( tt_module,
FT_SERVICE_ID_MULTI_MASTERS,
0 );
}
if ( !face->var )
{
FT_Module  tt_module = FT_Get_Module( library, "truetype" );
face->var = ft_module_get_service( tt_module,
FT_SERVICE_ID_METRICS_VARIATIONS,
0 );
}
#endif
FT_TRACE2(( "SFNT driver\n" ));
error = sfnt_open_font( stream, face );
if ( error )
return error;
stream = face->root.stream;
FT_TRACE2(( "sfnt_init_face: %08p, %d\n", face, face_instance_index ));
face_index = FT_ABS( face_instance_index ) & 0xFFFF;
if ( face_instance_index < 0 )
face_index--;
if ( face_index >= face->ttc_header.count )
{
if ( face_instance_index >= 0 )
return FT_THROW( Invalid_Argument );
else
face_index = 0;
}
if ( FT_STREAM_SEEK( face->ttc_header.offsets[face_index] ) )
return error;
error = sfnt->load_font_dir( face, stream );
if ( error )
return error;
#ifdef TT_CONFIG_OPTION_GX_VAR_SUPPORT
{
FT_ULong  fvar_len;
FT_ULong  version;
FT_ULong  offset;
FT_UShort  num_axes;
FT_UShort  axis_size;
FT_UShort  num_instances;
FT_UShort  instance_size;
FT_Int  instance_index;
FT_Byte*  default_values  = NULL;
FT_Byte*  instance_values = NULL;
face->is_default_instance = 1;
instance_index = FT_ABS( face_instance_index ) >> 16;
if ( face->goto_table( face, TTAG_fvar, stream, &fvar_len ) ||
fvar_len < 20                                          ||
FT_READ_ULONG( version )                               ||
FT_READ_USHORT( offset )                               ||
FT_STREAM_SKIP( 2 )                      ||
FT_READ_USHORT( num_axes )                             ||
FT_READ_USHORT( axis_size )                            ||
FT_READ_USHORT( num_instances )                        ||
FT_READ_USHORT( instance_size )                        )
{
version       = 0;
offset        = 0;
num_axes      = 0;
axis_size     = 0;
num_instances = 0;
instance_size = 0;
}
if ( version != 0x00010000UL                    ||
axis_size != 20                            ||
num_axes == 0                              ||
num_axes > 0x3FFE                          ||
!( instance_size == 4 + 4 * num_axes ||
instance_size == 6 + 4 * num_axes )     ||
num_instances > 0x7EFF                     ||
offset                          +
axis_size * num_axes          +
instance_size * num_instances > fvar_len )
num_instances = 0;
else
face->variation_support |= TT_FACE_FLAG_VAR_FVAR;
if ( !face->goto_table( face, TTAG_CFF, stream, 0 ) )
num_instances = 0;
if ( !( FT_ALLOC( default_values, num_axes * 2 )  ||
FT_ALLOC( instance_values, num_axes * 2 ) ) )
{
FT_ULong  array_start = FT_STREAM_POS() - 16 + offset;
FT_ULong  default_value_offset, instance_offset;
FT_Byte*  p;
FT_UInt   i;
default_value_offset = array_start + 8;
p                    = default_values;
for ( i = 0; i < num_axes; i++ )
{
(void)FT_STREAM_READ_AT( default_value_offset, p, 2 );
default_value_offset += axis_size;
p                    += 2;
}
instance_offset = array_start + axis_size * num_axes + 4;
for ( i = 0; i < num_instances; i++ )
{
(void)FT_STREAM_READ_AT( instance_offset,
instance_values,
num_axes * 2 );
if ( !ft_memcmp( default_values, instance_values, num_axes * 2 ) )
break;
instance_offset += instance_size;
}
if ( i == num_instances )
{
num_instances++;
}
}
FT_FREE( default_values );
FT_FREE( instance_values );
if ( instance_index > num_instances )
{
if ( face_instance_index >= 0 )
return FT_THROW( Invalid_Argument );
else
num_instances = 0;
}
face->root.style_flags = (FT_Long)num_instances << 16;
}
#endif
face->root.num_faces  = face->ttc_header.count;
face->root.face_index = face_instance_index;
return error;
}

static void
HTMLlineproc2body(Buffer *buf, Str (*feed) (), int llimit)
{
static char *outc = NULL;
static Lineprop *outp = NULL;
static int out_size = 0;
Anchor *a_href = NULL, *a_img = NULL, *a_form = NULL;
char *p, *q, *r, *s, *t, *str;
Lineprop mode, effect, ex_effect;
int pos;
int nlines;
#ifdef DEBUG
FILE *debug = NULL;
#endif
struct frameset *frameset_s[FRAMESTACK_SIZE];
int frameset_sp = -1;
union frameset_element *idFrame = NULL;
char *id = NULL;
int hseq, form_id;
Str line;
char *endp;
char symbol = '\0';
int internal = 0;
Anchor **a_textarea = NULL;
#ifdef MENU_SELECT
Anchor **a_select = NULL;
#endif
#if defined(USE_M17N) || defined(USE_IMAGE)
ParsedURL *base = baseURL(buf);
#endif
#ifdef USE_M17N
wc_ces name_charset = url_to_charset(NULL, &buf->currentURL,
buf->document_charset);
#endif
if (out_size == 0) {
out_size = LINELEN;
outc = NewAtom_N(char, out_size);
outp = NewAtom_N(Lineprop, out_size);
}
n_textarea = -1;
if (!max_textarea) {
max_textarea = MAX_TEXTAREA;
textarea_str = New_N(Str, max_textarea);
a_textarea = New_N(Anchor *, max_textarea);
}
#ifdef MENU_SELECT
n_select = -1;
if (!max_select) {
max_select = MAX_SELECT;
select_option = New_N(FormSelectOption, max_select);
a_select = New_N(Anchor *, max_select);
}
#endif
#ifdef DEBUG
if (w3m_debug)
debug = fopen("zzzerr", "a");
#endif
effect = 0;
ex_effect = 0;
nlines = 0;
while ((line = feed()) != NULL) {
#ifdef DEBUG
if (w3m_debug) {
Strfputs(line, debug);
fputc('\n', debug);
}
#endif
if (n_textarea >= 0 && *(line->ptr) != '<') {
Strcat(textarea_str[n_textarea], line);
continue;
}
proc_again:
if (++nlines == llimit)
break;
pos = 0;
#ifdef ENABLE_REMOVE_TRAILINGSPACES
Strremovetrailingspaces(line);
#endif
str = line->ptr;
endp = str + line->length;
while (str < endp) {
PSIZE;
mode = get_mctype(str);
if ((effect | ex_efct(ex_effect)) & PC_SYMBOL && *str != '<') {
#ifdef USE_M17N
char **buf = set_symbol(symbol_width0);
int len;
p = buf[(int)symbol];
len = get_mclen(p);
mode = get_mctype(p);
PPUSH(mode | effect | ex_efct(ex_effect), *(p++));
if (--len) {
mode = (mode & ~PC_WCHAR1) | PC_WCHAR2;
while (len--) {
PSIZE;
PPUSH(mode | effect | ex_efct(ex_effect), *(p++));
}
}
#else
PPUSH(PC_ASCII | effect | ex_efct(ex_effect), SYMBOL_BASE + symbol);
#endif
str += symbol_width;
}
#ifdef USE_M17N
else if (mode == PC_CTRL || mode == PC_UNDEF) {
#else
else if (mode == PC_CTRL || IS_INTSPACE(*str)) {
#endif
PPUSH(PC_ASCII | effect | ex_efct(ex_effect), ' ');
str++;
}
#ifdef USE_M17N
else if (mode & PC_UNKNOWN) {
PPUSH(PC_ASCII | effect | ex_efct(ex_effect), ' ');
str += get_mclen(str);
}
#endif
else if (*str != '<' && *str != '&') {
#ifdef USE_M17N
int len = get_mclen(str);
#endif
PPUSH(mode | effect | ex_efct(ex_effect), *(str++));
#ifdef USE_M17N
if (--len) {
mode = (mode & ~PC_WCHAR1) | PC_WCHAR2;
while (len--) {
PSIZE;
PPUSH(mode | effect | ex_efct(ex_effect), *(str++));
}
}
#endif
}
else if (*str == '&') {
p = getescapecmd(&str);
while (*p) {
PSIZE;
mode = get_mctype((unsigned char *)p);
#ifdef USE_M17N
if (mode == PC_CTRL || mode == PC_UNDEF) {
#else
if (mode == PC_CTRL || IS_INTSPACE(*str)) {
#endif
PPUSH(PC_ASCII | effect | ex_efct(ex_effect), ' ');
p++;
}
#ifdef USE_M17N
else if (mode & PC_UNKNOWN) {
PPUSH(PC_ASCII | effect | ex_efct(ex_effect), ' ');
p += get_mclen(p);
}
#endif
else {
#ifdef USE_M17N
int len = get_mclen(p);
#endif
PPUSH(mode | effect | ex_efct(ex_effect), *(p++));
#ifdef USE_M17N
if (--len) {
mode = (mode & ~PC_WCHAR1) | PC_WCHAR2;
while (len--) {
PSIZE;
PPUSH(mode | effect | ex_efct(ex_effect), *(p++));
}
}
#endif
}
}
}
else {
struct parsed_tag *tag;
if (!(tag = parse_tag(&str, TRUE)))
continue;
switch (tag->tagid) {
case HTML_B:
effect |= PE_BOLD;
break;
case HTML_N_B:
effect &= ~PE_BOLD;
break;
case HTML_I:
ex_effect |= PE_EX_ITALIC;
break;
case HTML_N_I:
ex_effect &= ~PE_EX_ITALIC;
break;
case HTML_INS:
ex_effect |= PE_EX_INSERT;
break;
case HTML_N_INS:
ex_effect &= ~PE_EX_INSERT;
break;
case HTML_U:
effect |= PE_UNDER;
break;
case HTML_N_U:
effect &= ~PE_UNDER;
break;
case HTML_S:
ex_effect |= PE_EX_STRIKE;
break;
case HTML_N_S:
ex_effect &= ~PE_EX_STRIKE;
break;
case HTML_A:
if (renderFrameSet &&
parsedtag_get_value(tag, ATTR_FRAMENAME, &p)) {
p = url_quote_conv(p, buf->document_charset);
if (!idFrame || strcmp(idFrame->body->name, p)) {
idFrame = search_frame(renderFrameSet, p);
if (idFrame && idFrame->body->attr != F_BODY)
idFrame = NULL;
}
}
p = r = s = NULL;
q = buf->baseTarget;
t = "";
hseq = 0;
id = NULL;
if (parsedtag_get_value(tag, ATTR_NAME, &id)) {
id = url_quote_conv(id, name_charset);
registerName(buf, id, currentLn(buf), pos);
}
if (parsedtag_get_value(tag, ATTR_HREF, &p))
p = url_encode(remove_space(p), base,
buf->document_charset);
if (parsedtag_get_value(tag, ATTR_TARGET, &q))
q = url_quote_conv(q, buf->document_charset);
if (parsedtag_get_value(tag, ATTR_REFERER, &r))
r = url_encode(r, base,
buf->document_charset);
parsedtag_get_value(tag, ATTR_TITLE, &s);
parsedtag_get_value(tag, ATTR_ACCESSKEY, &t);
parsedtag_get_value(tag, ATTR_HSEQ, &hseq);
if (hseq > 0)
buf->hmarklist =
putHmarker(buf->hmarklist, currentLn(buf),
pos, hseq - 1);
else if (hseq < 0) {
int h = -hseq - 1;
if (buf->hmarklist &&
h < buf->hmarklist->nmark &&
buf->hmarklist->marks[h].invalid) {
buf->hmarklist->marks[h].pos = pos;
buf->hmarklist->marks[h].line = currentLn(buf);
buf->hmarklist->marks[h].invalid = 0;
hseq = -hseq;
}
}
if (id && idFrame)
idFrame->body->nameList =
putAnchor(idFrame->body->nameList, id, NULL,
(Anchor **)NULL, NULL, NULL, '\0',
currentLn(buf), pos);
if (p) {
effect |= PE_ANCHOR;
a_href = registerHref(buf, p, q, r, s,
*t, currentLn(buf), pos);
a_href->hseq = ((hseq > 0) ? hseq : -hseq) - 1;
a_href->slave = (hseq > 0) ? FALSE : TRUE;
}
break;
case HTML_N_A:
effect &= ~PE_ANCHOR;
if (a_href) {
a_href->end.line = currentLn(buf);
a_href->end.pos = pos;
if (a_href->start.line == a_href->end.line &&
a_href->start.pos == a_href->end.pos) {
if (buf->hmarklist &&
a_href->hseq < buf->hmarklist->nmark)
buf->hmarklist->marks[a_href->hseq].invalid = 1;
a_href->hseq = -1;
}
a_href = NULL;
}
break;
case HTML_LINK:
addLink(buf, tag);
break;
case HTML_IMG_ALT:
if (parsedtag_get_value(tag, ATTR_SRC, &p)) {
#ifdef USE_IMAGE
int w = -1, h = -1, iseq = 0, ismap = 0;
int xoffset = 0, yoffset = 0, top = 0, bottom = 0;
parsedtag_get_value(tag, ATTR_HSEQ, &iseq);
parsedtag_get_value(tag, ATTR_WIDTH, &w);
parsedtag_get_value(tag, ATTR_HEIGHT, &h);
parsedtag_get_value(tag, ATTR_XOFFSET, &xoffset);
parsedtag_get_value(tag, ATTR_YOFFSET, &yoffset);
parsedtag_get_value(tag, ATTR_TOP_MARGIN, &top);
parsedtag_get_value(tag, ATTR_BOTTOM_MARGIN, &bottom);
if (parsedtag_exists(tag, ATTR_ISMAP))
ismap = 1;
q = NULL;
parsedtag_get_value(tag, ATTR_USEMAP, &q);
if (iseq > 0) {
buf->imarklist = putHmarker(buf->imarklist,
currentLn(buf), pos,
iseq - 1);
}
#endif
s = NULL;
parsedtag_get_value(tag, ATTR_TITLE, &s);
p = url_quote_conv(remove_space(p),
buf->document_charset);
a_img = registerImg(buf, p, s, currentLn(buf), pos);
#ifdef USE_IMAGE
a_img->hseq = iseq;
a_img->image = NULL;
if (iseq > 0) {
ParsedURL u;
Image *image;
parseURL2(a_img->url, &u, base);
a_img->image = image = New(Image);
image->url = parsedURL2Str(&u)->ptr;
if (!uncompressed_file_type(u.file, &image->ext))
image->ext = filename_extension(u.file, TRUE);
image->cache = NULL;
image->width =
(w > MAX_IMAGE_SIZE) ? MAX_IMAGE_SIZE : w;
image->height =
(h > MAX_IMAGE_SIZE) ? MAX_IMAGE_SIZE : h;
image->xoffset = xoffset;
image->yoffset = yoffset;
image->y = currentLn(buf) - top;
if (image->xoffset < 0 && pos == 0)
image->xoffset = 0;
if (image->yoffset < 0 && image->y == 1)
image->yoffset = 0;
image->rows = 1 + top + bottom;
image->map = q;
image->ismap = ismap;
image->touch = 0;
image->cache = getImage(image, base,
IMG_FLAG_SKIP);
}
else if (iseq < 0) {
BufferPoint *po = buf->imarklist->marks - iseq - 1;
Anchor *a = retrieveAnchor(buf->img,
po->line, po->pos);
if (a) {
a_img->url = a->url;
a_img->image = a->image;
}
}
#endif
}
effect |= PE_IMAGE;
break;
case HTML_N_IMG_ALT:
effect &= ~PE_IMAGE;
if (a_img) {
a_img->end.line = currentLn(buf);
a_img->end.pos = pos;
}
a_img = NULL;
break;
case HTML_INPUT_ALT:
{
FormList *form;
int top = 0, bottom = 0;
int textareanumber = -1;
#ifdef MENU_SELECT
int selectnumber = -1;
#endif
hseq = 0;
form_id = -1;
parsedtag_get_value(tag, ATTR_HSEQ, &hseq);
parsedtag_get_value(tag, ATTR_FID, &form_id);
parsedtag_get_value(tag, ATTR_TOP_MARGIN, &top);
parsedtag_get_value(tag, ATTR_BOTTOM_MARGIN, &bottom);
if (form_id < 0 || form_id > form_max || forms == NULL)
break;
form = forms[form_id];
if (hseq > 0) {
int hpos = pos;
if (*str == '[')
hpos++;
buf->hmarklist =
putHmarker(buf->hmarklist, currentLn(buf),
hpos, hseq - 1);
}
else if (hseq < 0) {
int h = -hseq - 1;
int hpos = pos;
if (*str == '[')
hpos++;
if (buf->hmarklist &&
h < buf->hmarklist->nmark &&
buf->hmarklist->marks[h].invalid) {
buf->hmarklist->marks[h].pos = hpos;
buf->hmarklist->marks[h].line = currentLn(buf);
buf->hmarklist->marks[h].invalid = 0;
hseq = -hseq;
}
}
if (!form->target)
form->target = buf->baseTarget;
if (a_textarea &&
parsedtag_get_value(tag, ATTR_TEXTAREANUMBER,
&textareanumber)) {
if (textareanumber >= max_textarea) {
max_textarea = 2 * textareanumber;
textarea_str = New_Reuse(Str, textarea_str,
max_textarea);
a_textarea = New_Reuse(Anchor *, a_textarea,
max_textarea);
}
}
#ifdef MENU_SELECT
if (a_select &&
parsedtag_get_value(tag, ATTR_SELECTNUMBER,
&selectnumber)) {
if (selectnumber >= max_select) {
max_select = 2 * selectnumber;
select_option = New_Reuse(FormSelectOption,
select_option,
max_select);
a_select = New_Reuse(Anchor *, a_select,
max_select);
}
}
#endif
a_form =
registerForm(buf, form, tag, currentLn(buf), pos);
if (a_textarea && textareanumber >= 0)
a_textarea[textareanumber] = a_form;
#ifdef MENU_SELECT
if (a_select && selectnumber >= 0)
a_select[selectnumber] = a_form;
#endif
if (a_form) {
a_form->hseq = hseq - 1;
a_form->y = currentLn(buf) - top;
a_form->rows = 1 + top + bottom;
if (!parsedtag_exists(tag, ATTR_NO_EFFECT))
effect |= PE_FORM;
break;
}
}
case HTML_N_INPUT_ALT:
effect &= ~PE_FORM;
if (a_form) {
a_form->end.line = currentLn(buf);
a_form->end.pos = pos;
if (a_form->start.line == a_form->end.line &&
a_form->start.pos == a_form->end.pos)
a_form->hseq = -1;
}
a_form = NULL;
break;
case HTML_MAP:
if (parsedtag_get_value(tag, ATTR_NAME, &p)) {
MapList *m = New(MapList);
m->name = Strnew_charp(p);
m->area = newGeneralList();
m->next = buf->maplist;
buf->maplist = m;
}
break;
case HTML_N_MAP:
break;
case HTML_AREA:
if (buf->maplist == NULL)
break;
if (parsedtag_get_value(tag, ATTR_HREF, &p)) {
MapArea *a;
p = url_encode(remove_space(p), base,
buf->document_charset);
t = NULL;
parsedtag_get_value(tag, ATTR_TARGET, &t);
q = "";
parsedtag_get_value(tag, ATTR_ALT, &q);
r = NULL;
s = NULL;
#ifdef USE_IMAGE
parsedtag_get_value(tag, ATTR_SHAPE, &r);
parsedtag_get_value(tag, ATTR_COORDS, &s);
#endif
a = newMapArea(p, t, q, r, s);
pushValue(buf->maplist->area, (void *)a);
}
break;
case HTML_FRAMESET:
frameset_sp++;
if (frameset_sp >= FRAMESTACK_SIZE)
break;
frameset_s[frameset_sp] = newFrameSet(tag);
if (frameset_s[frameset_sp] == NULL)
break;
if (frameset_sp == 0) {
if (buf->frameset == NULL) {
buf->frameset = frameset_s[frameset_sp];
}
else
pushFrameTree(&(buf->frameQ),
frameset_s[frameset_sp], NULL);
}
else
addFrameSetElement(frameset_s[frameset_sp - 1],
*(union frameset_element *)
&frameset_s[frameset_sp]);
break;
case HTML_N_FRAMESET:
if (frameset_sp >= 0)
frameset_sp--;
break;
case HTML_FRAME:
if (frameset_sp >= 0 && frameset_sp < FRAMESTACK_SIZE) {
union frameset_element element;
element.body = newFrame(tag, buf);
addFrameSetElement(frameset_s[frameset_sp], element);
}
break;
case HTML_BASE:
if (parsedtag_get_value(tag, ATTR_HREF, &p)) {
p = url_encode(remove_space(p), NULL,
buf->document_charset);
if (!buf->baseURL)
buf->baseURL = New(ParsedURL);
parseURL(p, buf->baseURL, NULL);
#if defined(USE_M17N) || defined(USE_IMAGE)
base = buf->baseURL;
#endif
}
if (parsedtag_get_value(tag, ATTR_TARGET, &p))
buf->baseTarget =
url_quote_conv(p, buf->document_charset);
break;
case HTML_META:
p = q = NULL;
parsedtag_get_value(tag, ATTR_HTTP_EQUIV, &p);
parsedtag_get_value(tag, ATTR_CONTENT, &q);
if (p && q && !strcasecmp(p, "refresh") && MetaRefresh) {
Str tmp = NULL;
int refresh_interval = getMetaRefreshParam(q, &tmp);
#ifdef USE_ALARM
if (tmp) {
p = url_encode(remove_space(tmp->ptr), base,
buf->document_charset);
buf->event = setAlarmEvent(buf->event,
refresh_interval,
AL_IMPLICIT_ONCE,
FUNCNAME_gorURL, p);
}
else if (refresh_interval > 0)
buf->event = setAlarmEvent(buf->event,
refresh_interval,
AL_IMPLICIT,
FUNCNAME_reload, NULL);
#else
if (tmp && refresh_interval == 0) {
p = url_encode(remove_space(tmp->ptr), base,
buf->document_charset);
pushEvent(FUNCNAME_gorURL, p);
}
#endif
}
break;
case HTML_INTERNAL:
internal = HTML_INTERNAL;
break;
case HTML_N_INTERNAL:
internal = HTML_N_INTERNAL;
break;
case HTML_FORM_INT:
if (parsedtag_get_value(tag, ATTR_FID, &form_id))
process_form_int(tag, form_id);
break;
case HTML_TEXTAREA_INT:
if (parsedtag_get_value(tag, ATTR_TEXTAREANUMBER,
&n_textarea)
&& n_textarea >= 0 && n_textarea < max_textarea) {
textarea_str[n_textarea] = Strnew();
}
else
n_textarea = -1;
break;
case HTML_N_TEXTAREA_INT:
if (n_textarea >= 0) {
FormItemList *item =
(FormItemList *)a_textarea[n_textarea]->url;
item->init_value = item->value =
textarea_str[n_textarea];
}
break;
#ifdef MENU_SELECT
case HTML_SELECT_INT:
if (parsedtag_get_value(tag, ATTR_SELECTNUMBER, &n_select)
&& n_select >= 0 && n_select < max_select) {
select_option[n_select].first = NULL;
select_option[n_select].last = NULL;
}
else
n_select = -1;
break;
case HTML_N_SELECT_INT:
if (n_select >= 0) {
FormItemList *item =
(FormItemList *)a_select[n_select]->url;
item->select_option = select_option[n_select].first;
chooseSelectOption(item, item->select_option);
item->init_selected = item->selected;
item->init_value = item->value;
item->init_label = item->label;
}
break;
case HTML_OPTION_INT:
if (n_select >= 0) {
int selected;
q = "";
parsedtag_get_value(tag, ATTR_LABEL, &q);
p = q;
parsedtag_get_value(tag, ATTR_VALUE, &p);
selected = parsedtag_exists(tag, ATTR_SELECTED);
addSelectOption(&select_option[n_select],
Strnew_charp(p), Strnew_charp(q),
selected);
}
break;
#endif
case HTML_TITLE_ALT:
if (parsedtag_get_value(tag, ATTR_TITLE, &p))
buf->buffername = html_unquote(p);
break;
case HTML_SYMBOL:
effect |= PC_SYMBOL;
if (parsedtag_get_value(tag, ATTR_TYPE, &p))
symbol = (char)atoi(p);
break;
case HTML_N_SYMBOL:
effect &= ~PC_SYMBOL;
break;
}
#ifdefID_EXT
id = NULL;
if (parsedtag_get_value(tag, ATTR_ID, &id)) {
id = url_quote_conv(id, name_charset);
registerName(buf, id, currentLn(buf), pos);
}
if (renderFrameSet &&
parsedtag_get_value(tag, ATTR_FRAMENAME, &p)) {
p = url_quote_conv(p, buf->document_charset);
if (!idFrame || strcmp(idFrame->body->name, p)) {
idFrame = search_frame(renderFrameSet, p);
if (idFrame && idFrame->body->attr != F_BODY)
idFrame = NULL;
}
}
if (id && idFrame)
idFrame->body->nameList =
putAnchor(idFrame->body->nameList, id, NULL,
(Anchor **)NULL, NULL, NULL, '\0',
currentLn(buf), pos);
#endif
}
}
if (!internal)
addnewline(buf, outc, outp, NULL, pos, -1, nlines);
if (internal == HTML_N_INTERNAL)
internal = 0;
if (str != endp) {
line = Strsubstr(line, str - line->ptr, endp - str);
goto proc_again;
}
}
#ifdef DEBUG
if (w3m_debug)
fclose(debug);
#endif
for (form_id = 1; form_id <= form_max; form_id++)
if (forms[form_id])
forms[form_id]->next = forms[form_id - 1];
buf->formlist = (form_max >= 0) ? forms[form_max] : NULL;
if (n_textarea)
addMultirowsForm(buf, buf->formitem);
#ifdef USE_IMAGE
addMultirowsImg(buf, buf->img);
#endif
}

static int llcp_sock_connect(struct socket *sock, struct sockaddr *_addr,
int len, int flags)
{
struct sock *sk = sock->sk;
struct nfc_llcp_sock *llcp_sock = nfc_llcp_sock(sk);
struct sockaddr_nfc_llcp *addr = (struct sockaddr_nfc_llcp *)_addr;
struct nfc_dev *dev;
struct nfc_llcp_local *local;
int ret = 0;
pr_debug("sock %p sk %p flags 0x%x\n", sock, sk, flags);
if (!addr || len < sizeof(*addr) || addr->sa_family != AF_NFC)
return -EINVAL;
if (addr->service_name_len == 0 && addr->dsap == 0)
return -EINVAL;
pr_debug("addr dev_idx=%u target_idx=%u protocol=%u\n", addr->dev_idx,
addr->target_idx, addr->nfc_protocol);
lock_sock(sk);
if (sk->sk_state == LLCP_CONNECTED) {
ret = -EISCONN;
goto error;
}
if (sk->sk_state == LLCP_CONNECTING) {
ret = -EINPROGRESS;
goto error;
}
dev = nfc_get_device(addr->dev_idx);
if (dev == NULL) {
ret = -ENODEV;
goto error;
}
local = nfc_llcp_find_local(dev);
if (local == NULL) {
ret = -ENODEV;
goto put_dev;
}
device_lock(&dev->dev);
if (dev->dep_link_up == false) {
ret = -ENOLINK;
device_unlock(&dev->dev);
goto put_dev;
}
device_unlock(&dev->dev);
if (local->rf_mode == NFC_RF_INITIATOR &&
addr->target_idx != local->target_idx) {
ret = -ENOLINK;
goto put_dev;
}
llcp_sock->dev = dev;
llcp_sock->local = nfc_llcp_local_get(local);
llcp_sock->ssap = nfc_llcp_get_local_ssap(local);
if (llcp_sock->ssap == LLCP_SAP_MAX) {
nfc_llcp_local_put(llcp_sock->local);
ret = -ENOMEM;
goto put_dev;
}
llcp_sock->reserved_ssap = llcp_sock->ssap;
if (addr->service_name_len == 0)
llcp_sock->dsap = addr->dsap;
else
llcp_sock->dsap = LLCP_SAP_SDP;
llcp_sock->nfc_protocol = addr->nfc_protocol;
llcp_sock->service_name_len = min_t(unsigned int,
addr->service_name_len,
NFC_LLCP_MAX_SERVICE_NAME);
llcp_sock->service_name = kmemdup(addr->service_name,
llcp_sock->service_name_len,
GFP_KERNEL);
if (!llcp_sock->service_name) {
ret = -ENOMEM;
goto sock_llcp_release;
}
nfc_llcp_sock_link(&local->connecting_sockets, sk);
ret = nfc_llcp_send_connect(llcp_sock);
if (ret)
goto sock_unlink;
sk->sk_state = LLCP_CONNECTING;
ret = sock_wait_state(sk, LLCP_CONNECTED,
sock_sndtimeo(sk, flags & O_NONBLOCK));
if (ret && ret != -EINPROGRESS)
goto sock_unlink;
release_sock(sk);
return ret;
sock_unlink:
nfc_llcp_sock_unlink(&local->connecting_sockets, sk);
kfree(llcp_sock->service_name);
llcp_sock->service_name = NULL;
sock_llcp_release:
nfc_llcp_put_ssap(local, llcp_sock->ssap);
nfc_llcp_local_put(llcp_sock->local);
put_dev:
nfc_put_device(dev);
error:
release_sock(sk);
return ret;
}

int
_dwarf_internal_get_pubnames_like_data(Dwarf_Debug dbg,
const char *secname,
Dwarf_Small * section_data_ptr,
Dwarf_Unsigned section_length,
Dwarf_Global ** globals,
Dwarf_Signed * return_count,
Dwarf_Error * error,
int context_DLA_code,
int global_DLA_code,
int length_err_num,
int version_err_num)
{
Dwarf_Small *pubnames_like_ptr = 0;
Dwarf_Off pubnames_section_offset = 0;
Dwarf_Small *section_end_ptr = section_data_ptr +section_length;
Dwarf_Global_Context pubnames_context = 0;
Dwarf_Bool           pubnames_context_on_list = FALSE;
Dwarf_Unsigned version = 0;
Dwarf_Off die_offset_in_cu = 0;
Dwarf_Unsigned global_count = 0;
Dwarf_Chain head_chain = 0;
Dwarf_Chain *plast_chain = &head_chain;
Dwarf_Global *ret_globals = 0;
int mres = 0;
Dwarf_Unsigned i = 0;
if (!dbg || dbg->de_magic != DBG_IS_VALID) {
_dwarf_error_string(NULL, error, DW_DLE_DBG_NULL,
"DW_DLE_DBG_NULL: "
"calling for pubnames-like data Dwarf_Debug "
"either null or it contains"
"a stale Dwarf_Debug pointer");
return DW_DLV_ERROR;
}
if (!dbg->de_debug_info.dss_data) {
int res = _dwarf_load_debug_info(dbg, error);
if (res != DW_DLV_OK) {
return res;
}
}
if (section_data_ptr == NULL) {
return DW_DLV_NO_ENTRY;
}
pubnames_like_ptr = section_data_ptr;
do {
Dwarf_Unsigned length = 0;
int local_extension_size = 0;
int local_length_size = 0;
Dwarf_Small *pubnames_ptr_past_end_cu = 0;
pubnames_context_on_list = FALSE;
pubnames_context = (Dwarf_Global_Context)
_dwarf_get_alloc(dbg, context_DLA_code, 1);
if (pubnames_context == NULL) {
dealloc_globals_chain(dbg,head_chain);
_dwarf_error(dbg, error, DW_DLE_ALLOC_FAIL);
return DW_DLV_ERROR;
}
if ((pubnames_like_ptr + DWARF_32BIT_SIZE +
DWARF_HALF_SIZE + DWARF_32BIT_SIZE) >
section_end_ptr) {
pubnames_error_length(dbg,error,
DWARF_32BIT_SIZE + DWARF_HALF_SIZE + DWARF_32BIT_SIZE,
secname,
"header-record");
dealloc_globals_chain(dbg,head_chain);
if (!pubnames_context_on_list) {
dwarf_dealloc(dbg,pubnames_context,context_DLA_code);
}
return DW_DLV_ERROR;
}
mres = _dwarf_read_area_length_ck_wrapper(dbg,
&length,&pubnames_like_ptr,&local_length_size,
&local_extension_size,section_length,section_end_ptr,
error);
if (mres != DW_DLV_OK) {
dealloc_globals_chain(dbg,head_chain);
if (!pubnames_context_on_list) {
dwarf_dealloc(dbg,pubnames_context,context_DLA_code);
}
return mres;
}
pubnames_context->pu_alloc_type = context_DLA_code;
pubnames_context->pu_length_size = local_length_size;
pubnames_context->pu_length = length;
pubnames_context->pu_extension_size = local_extension_size;
pubnames_context->pu_dbg = dbg;
pubnames_context->pu_pub_offset = pubnames_section_offset;
pubnames_ptr_past_end_cu = pubnames_like_ptr + length;
pubnames_context->pu_pub_entries_end_ptr =
pubnames_ptr_past_end_cu;
if ((pubnames_like_ptr + (DWARF_HALF_SIZE) ) >
section_end_ptr) {
pubnames_error_length(dbg,error,
DWARF_HALF_SIZE,
secname,"version-number");
dealloc_globals_chain(dbg,head_chain);
if (!pubnames_context_on_list) {
dwarf_dealloc(dbg,pubnames_context,context_DLA_code);
}
return DW_DLV_ERROR;
}
mres = _dwarf_read_unaligned_ck_wrapper(dbg,
&version,pubnames_like_ptr,DWARF_HALF_SIZE,
section_end_ptr,error);
if (mres != DW_DLV_OK) {
dealloc_globals_chain(dbg,head_chain);
if (!pubnames_context_on_list) {
dwarf_dealloc(dbg,pubnames_context,context_DLA_code);
}
return mres;
}
pubnames_context->pu_version = version;
pubnames_like_ptr += DWARF_HALF_SIZE;
if (version != DW_PUBNAMES_VERSION2) {
dealloc_globals_chain(dbg,head_chain);
if (!pubnames_context_on_list) {
dwarf_dealloc(dbg,pubnames_context,context_DLA_code);
}
_dwarf_error(dbg, error, version_err_num);
return DW_DLV_ERROR;
}
if ((pubnames_like_ptr + 3*pubnames_context->pu_length_size)>
section_end_ptr) {
pubnames_error_length(dbg,error,
3*pubnames_context->pu_length_size,
secname,
"header/DIE offsets");
dealloc_globals_chain(dbg,head_chain);
if (!pubnames_context_on_list) {
dwarf_dealloc(dbg,pubnames_context,context_DLA_code);
}
return DW_DLV_ERROR;
}
mres = _dwarf_read_unaligned_ck_wrapper(dbg,
&pubnames_context->pu_offset_of_cu_header,
pubnames_like_ptr,
pubnames_context->pu_length_size,
section_end_ptr,error);
if (mres != DW_DLV_OK) {
dealloc_globals_chain(dbg,head_chain);
if (!pubnames_context_on_list) {
dwarf_dealloc(dbg,pubnames_context,context_DLA_code);
}
return mres;
}
pubnames_like_ptr += pubnames_context->pu_length_size;
FIX_UP_OFFSET_IRIX_BUG(dbg,
pubnames_context->pu_offset_of_cu_header,
"pubnames cu header offset");
mres = _dwarf_read_unaligned_ck_wrapper(dbg,
&pubnames_context->pu_info_length,
pubnames_like_ptr,
pubnames_context->pu_length_size,
section_end_ptr,error);
if (mres != DW_DLV_OK) {
dealloc_globals_chain(dbg,head_chain);
if (!pubnames_context_on_list) {
dwarf_dealloc(dbg,pubnames_context,context_DLA_code);
}
return mres;
}
pubnames_like_ptr += pubnames_context->pu_length_size;
if (pubnames_like_ptr > (section_data_ptr + section_length)) {
dealloc_globals_chain(dbg,head_chain);
if (!pubnames_context_on_list) {
dwarf_dealloc(dbg,pubnames_context,context_DLA_code);
}
_dwarf_error(dbg, error, length_err_num);
return DW_DLV_ERROR;
}
mres = _dwarf_read_unaligned_ck_wrapper(dbg,
&die_offset_in_cu,
pubnames_like_ptr,
pubnames_context->pu_length_size,
pubnames_context->pu_pub_entries_end_ptr,error);
if (mres != DW_DLV_OK) {
dealloc_globals_chain(dbg,head_chain);
if (!pubnames_context_on_list) {
dwarf_dealloc(dbg,pubnames_context,context_DLA_code);
}
return mres;
}
pubnames_like_ptr += pubnames_context->pu_length_size;
FIX_UP_OFFSET_IRIX_BUG(dbg,
die_offset_in_cu, "offset of die in cu");
if (pubnames_like_ptr > (section_data_ptr + section_length)) {
dealloc_globals_chain(dbg,head_chain);
if (!pubnames_context_on_list) {
dwarf_dealloc(dbg,pubnames_context,context_DLA_code);
}
_dwarf_error(dbg, error, length_err_num);
return DW_DLV_ERROR;
}
if (!die_offset_in_cu) {
if (dbg->de_return_empty_pubnames) {
int res = 0;
res = _dwarf_make_global_add_to_chain(dbg,
global_DLA_code,
pubnames_context,
die_offset_in_cu,
(unsigned char *)"",
&global_count,
&pubnames_context_on_list,
&plast_chain,
error);
if (res != DW_DLV_OK) {
dealloc_globals_chain(dbg,head_chain);
if (!pubnames_context_on_list) {
dwarf_dealloc(dbg,pubnames_context,
context_DLA_code);
}
return res;
}
} else {
dwarf_dealloc(dbg,pubnames_context,context_DLA_code);
pubnames_context = 0;
continue;
}
}
while (die_offset_in_cu) {
int res = 0;
unsigned char *glname = 0;
res = _dwarf_check_string_valid(dbg,section_data_ptr,
pubnames_like_ptr,
pubnames_context->pu_pub_entries_end_ptr,
DW_DLE_STRING_OFF_END_PUBNAMES_LIKE,error);
if (res != DW_DLV_OK) {
dealloc_globals_chain(dbg,head_chain);
if (!pubnames_context_on_list) {
dwarf_dealloc(dbg,pubnames_context,
context_DLA_code);
}
return res;
}
glname = (unsigned char *)pubnames_like_ptr;
pubnames_like_ptr = pubnames_like_ptr +
strlen((char *) pubnames_like_ptr) + 1;
res = _dwarf_make_global_add_to_chain(dbg,
global_DLA_code,
pubnames_context,
die_offset_in_cu,
glname,
&global_count,
&pubnames_context_on_list,
&plast_chain,
error);
if (res != DW_DLV_OK) {
dealloc_globals_chain(dbg,head_chain);
if (!pubnames_context_on_list) {
dwarf_dealloc(dbg,pubnames_context,
context_DLA_code);
}
return res;
}
if ((pubnames_like_ptr +
pubnames_context->pu_length_size ) >
section_end_ptr) {
pubnames_error_length(dbg,error,
2*pubnames_context->pu_length_size,
secname,
"global record offset");
dealloc_globals_chain(dbg,head_chain);
if (!pubnames_context_on_list) {
dwarf_dealloc(dbg,pubnames_context,
context_DLA_code);
}
return DW_DLV_ERROR;
}
mres = _dwarf_read_unaligned_ck_wrapper(dbg,
&die_offset_in_cu,
pubnames_like_ptr,
pubnames_context->pu_length_size,
pubnames_context->pu_pub_entries_end_ptr,
error);
if (mres != DW_DLV_OK) {
if (!pubnames_context_on_list) {
dwarf_dealloc(dbg,pubnames_context,
context_DLA_code);
}
dealloc_globals_chain(dbg,head_chain);
return mres;
}
pubnames_like_ptr += pubnames_context->pu_length_size;
FIX_UP_OFFSET_IRIX_BUG(dbg,
die_offset_in_cu, "offset of next die in cu");
if (pubnames_like_ptr >
(section_data_ptr + section_length)) {
if (!pubnames_context_on_list) {
dwarf_dealloc(dbg,pubnames_context,
context_DLA_code);
}
dealloc_globals_chain(dbg,head_chain);
_dwarf_error(dbg, error, length_err_num);
return DW_DLV_ERROR;
}
}
if (pubnames_like_ptr > pubnames_ptr_past_end_cu) {
_dwarf_error(dbg, error, length_err_num);
if (!pubnames_context_on_list) {
dwarf_dealloc(dbg,pubnames_context,context_DLA_code);
}
dealloc_globals_chain(dbg,head_chain);
return DW_DLV_ERROR;
}
{
Dwarf_Unsigned increment =
pubnames_context->pu_length_size +
pubnames_context->pu_length +
pubnames_context->pu_extension_size;
pubnames_section_offset += increment;
}
pubnames_like_ptr = pubnames_ptr_past_end_cu;
} while (pubnames_like_ptr < section_end_ptr);
ret_globals = (Dwarf_Global *)
_dwarf_get_alloc(dbg, DW_DLA_LIST, global_count);
if (ret_globals == NULL) {
if (!pubnames_context_on_list) {
dwarf_dealloc(dbg,pubnames_context,context_DLA_code);
}
dealloc_globals_chain(dbg,head_chain);
_dwarf_error(dbg, error, DW_DLE_ALLOC_FAIL);
return DW_DLV_ERROR;
}
{
Dwarf_Chain curr_chain = 0;
curr_chain = head_chain;
for (i = 0; i < global_count; i++) {
Dwarf_Chain prev = 0;
*(ret_globals + i) = curr_chain->ch_item;
prev = curr_chain;
curr_chain = curr_chain->ch_next;
prev->ch_item = 0; 
dwarf_dealloc(dbg, prev, DW_DLA_CHAIN);
}
}
*globals = ret_globals;
*return_count = (Dwarf_Signed) global_count;
return DW_DLV_OK;
}

int main(int argc, char** argv) {
WinsockContext context;
string tmpDir = GetTempDirectory();
el::Configurations defaultConf = LogHandler::setupLogHandler(&argc, &argv);
LogHandler::setupStdoutLogger();
et::HandleTerminate();
::signal(SIGINT, et::InterruptSignalHandler);
cxxopts::Options options("et", "Remote shell for the busy and impatient");
try {
options.allow_unrecognised_options();
options.positional_help("");
options.custom_help(
"[OPTION...] [user@]host[:port]\n\n"
"  Note that 'host' can be a hostname or ipv4 address with or without "
"a port\n  or an ipv6 address. If the ipv6 address is abbreviated with "
":: then it must\n  be specfied without a port (use -p,--port).");
options.add_options()                     ("h,help", "Print help")              ("version", "Print version")          ("u,username", "Username")            ("host", "Remote host name",
cxxopts::value<std::string>())          ("p,port", "Remote machine etserver port",
cxxopts::value<int>()->default_value("2022"))          ("c,command", "Run command on connect",
cxxopts::value<std::string>())          ("terminal-path",
"Path to etterminal on server side. "
"Use if etterminal is not on the system path.",
cxxopts::value<std::string>())          ("t,tunnel",
"Tunnel: Array of source:destination ports or "
"srcStart-srcEnd:dstStart-dstEnd (inclusive) port ranges (e.g. "
"10080:80,10443:443, 10090-10092:8000-8002)",
cxxopts::value<std::string>())          ("r,reversetunnel",
"Reverse Tunnel: Array of source:destination ports or "
"srcStart-srcEnd:dstStart-dstEnd (inclusive) port ranges",
cxxopts::value<std::string>())          ("jumphost", "jumphost between localhost and destination",
cxxopts::value<std::string>())          ("jport", "Jumphost machine port",
cxxopts::value<int>()->default_value("2022"))          ("x,kill-other-sessions",
"kill all old sessions belonging to the user")          ("macserver",
"Set when connecting to an macOS server.  Sets "
"--terminal-path=/usr/local/bin/etterminal")          ("v,verbose", "Enable verbose logging",
cxxopts::value<int>()->default_value("0"))          ("k,keepalive", "Client keepalive duration in seconds",
cxxopts::value<int>())                                      ("logtostdout", "Write log to stdout")                       ("silent", "Disable logging")                                ("N,no-terminal", "Do not create a terminal")                ("f,forward-ssh-agent", "Forward ssh-agent socket")          ("ssh-socket", "The ssh-agent socket to forward",
cxxopts::value<std::string>())          ("telemetry",
"Allow et to anonymously send errors to guide future improvements",
cxxopts::value<bool>()->default_value("true"))          ("serverfifo",
"If set, communicate to etserver on the matching fifo name",
cxxopts::value<std::string>()->default_value(""))          ("ssh-option", "Options to pass down to `ssh -o`",
cxxopts::value<std::vector<std::string>>());
options.parse_positional({"host"});
auto result = options.parse(argc, argv);
if (result.count("help")) {
CLOG(INFO, "stdout") << options.help({}) << endl;
