if (colormap == (unsigned char *) NULL)
return(MagickFalse);
q=colormap;
for (i=0; i < (ssize_t) image->colors; i++)
{
switch (depth)
{
default:
ThrowWriterException(CorruptImageError,"ImageDepthNotSupported");
case 32:
{
unsigned int
pixel;
pixel=ScaleQuantumToLong(ClampToQuantum(image->colormap[i].red));
q=PopLongPixel(MSBEndian,pixel,q);
pixel=ScaleQuantumToLong(ClampToQuantum(
image->colormap[i].green));
q=PopLongPixel(MSBEndian,pixel,q);
pixel=ScaleQuantumToLong(ClampToQuantum(image->colormap[i].blue));
q=PopLongPixel(MSBEndian,pixel,q);
break;
}
case 16:
{
unsigned short
pixel;
pixel=ScaleQuantumToShort(ClampToQuantum(image->colormap[i].red));
q=PopShortPixel(MSBEndian,pixel,q);
pixel=ScaleQuantumToShort(ClampToQuantum(
image->colormap[i].green));
q=PopShortPixel(MSBEndian,pixel,q);
pixel=ScaleQuantumToShort(ClampToQuantum(
image->colormap[i].blue));
q=PopShortPixel(MSBEndian,pixel,q);
break;
}
case 8:
{
unsigned char
pixel;
pixel=(unsigned char) ScaleQuantumToChar(ClampToQuantum(
image->colormap[i].red));
q=PopCharPixel(pixel,q);
pixel=(unsigned char) ScaleQuantumToChar(ClampToQuantum(
image->colormap[i].green));
q=PopCharPixel(pixel,q);
pixel=(unsigned char) ScaleQuantumToChar(ClampToQuantum(
image->colormap[i].blue));
q=PopCharPixel(pixel,q);
break;
}
}
}
(void) WriteBlob(image,packet_size*image->colors,colormap);
colormap=(unsigned char *) RelinquishMagickMemory(colormap);
}
status=PersistPixelCache(image,cache_filename,MagickFalse,&offset,
exception);
if (status == MagickFalse)
ThrowWriterException(CacheError,"UnableToPersistPixelCache");
if (GetNextImageInList(image) == (Image *) NULL)
break;
image=SyncNextImageInList(image);
if (image->progress_monitor != (MagickProgressMonitor) NULL)
{
status=image->progress_monitor(SaveImagesTag,scene,
imageListLength,image->client_data);
if (status == MagickFalse)
break;
}
scene++;
} while (image_info->adjoin != MagickFalse);
(void) CloseBlob(image);
return(status);
}

void
mmsServer_handleFileDeleteRequest(
MmsServerConnection connection,
uint8_t* buffer, int bufPos, int maxBufPos,
uint32_t invokeId,
ByteBuffer* response)
{
if (buffer[bufPos++] != 0x19)
goto exit_reject_invalid_pdu;
int length;
bufPos = BerDecoder_decodeLength(buffer, &length, bufPos, maxBufPos);
if (bufPos == -1)
goto exit_reject_invalid_pdu;
if (length > 255) {
mmsMsg_createMmsRejectPdu(&invokeId, MMS_ERROR_REJECT_REQUEST_INVALID_ARGUMENT, response);
return;
}
char filename[256];
memcpy(filename, buffer + bufPos, length);
filename[length] = 0;
if (DEBUG_MMS_SERVER)
printf("MMS_SERVER: mms_file_service.c: Delete file (%s)\n", filename);
if (connection->server->fileAccessHandler != NULL) {
MmsError access = connection->server->fileAccessHandler(connection->server->fileAccessHandlerParameter,
connection, MMS_FILE_ACCESS_TYPE_DELETE, filename, NULL);
if (access != MMS_ERROR_NONE) {
mmsMsg_createServiceErrorPdu(invokeId, response, access);
return;
}
}
if (!getFileInfo(MmsServerConnection_getFilesystemBasepath(connection), filename, NULL, NULL)) {
if (DEBUG_MMS_SERVER)
printf("MMS_SERVER: mms_file_service.c:  File (%s) not found\n", filename);
mmsMsg_createServiceErrorPdu(invokeId, response, MMS_ERROR_FILE_FILE_NON_EXISTENT);
return;
}
if (!deleteFile(MmsServerConnection_getFilesystemBasepath(connection), filename)) {
if (DEBUG_MMS_SERVER)
printf("MMS_SERVER: mms_file_service.c:  Delete file (%s) failed\n", filename);
mmsMsg_createServiceErrorPdu(invokeId, response, MMS_ERROR_FILE_FILE_ACCESS_DENIED);
return;
}
createNullResponseExtendedTag(invokeId, response, 0x4c);
return;
exit_reject_invalid_pdu:
mmsMsg_createMmsRejectPdu(&invokeId, MMS_ERROR_REJECT_INVALID_PDU, response);
}

int nfc_disable_se(struct nfc_dev *dev, u32 se_idx)
{
struct nfc_se *se;
int rc;
pr_debug("%s se index %d\n", dev_name(&dev->dev), se_idx);
device_lock(&dev->dev);
if (!device_is_registered(&dev->dev)) {
rc = -ENODEV;
goto error;
}
if (!dev->dev_up) {
rc = -ENODEV;
goto error;
}
if (!dev->ops->enable_se || !dev->ops->disable_se) {
rc = -EOPNOTSUPP;
goto error;
}
se = nfc_find_se(dev, se_idx);
if (!se) {
rc = -EINVAL;
goto error;
}
if (se->state == NFC_SE_DISABLED) {
rc = -EALREADY;
goto error;
}
rc = dev->ops->disable_se(dev, se_idx);
if (rc >= 0)
se->state = NFC_SE_DISABLED;
error:
device_unlock(&dev->dev);
return rc;
}

