MOBI_RET mobi_reconstruct_infl(char *outstring, const MOBIIndx *infl, const MOBIIndexEntry *orth_entry) {
const char *label = orth_entry->label;
uint32_t *infl_groups = NULL;
size_t infl_count = mobi_get_indxentry_tagarray(&infl_groups, orth_entry, INDX_TAGARR_ORTH_INFL);
if (infl_count == 0 || !infl_groups) {
return MOBI_SUCCESS;
}    
const char *start_tag = "<idx:infl>";
const char *end_tag = "</idx:infl>";
const char *iform_tag = "<idx:iform%s value=\"%s\"/>";
char name_attr[INDX_INFLBUF_SIZEMAX + 1];
char infl_tag[INDX_INFLBUF_SIZEMAX + 1];
strcpy(outstring, start_tag);
size_t initlen = strlen(start_tag) + strlen(end_tag);
size_t outlen = initlen;
size_t label_length = strlen(label);
if (label_length > INDX_INFLBUF_SIZEMAX) {
debug_print("Entry label too long (%s)\n", label);
return MOBI_DATA_CORRUPT;
}
if (infl->cncx_record == NULL) {
debug_print("%s\n", "Missing cncx record");
return MOBI_DATA_CORRUPT;
}
for (size_t i = 0; i < infl_count; i++) {
size_t offset = infl_groups[i];
if (offset >= infl->entries_count) {
debug_print("%s\n", "Invalid entry offset");
return MOBI_DATA_CORRUPT;
}
uint32_t *groups;
size_t group_cnt = mobi_get_indxentry_tagarray(&groups, &infl->entries[offset], INDX_TAGARR_INFL_GROUPS);
uint32_t *parts;
size_t part_cnt = mobi_get_indxentry_tagarray(&parts, &infl->entries[offset], INDX_TAGARR_INFL_PARTS_V2);
if (group_cnt != part_cnt) {
return MOBI_DATA_CORRUPT;
}
for (size_t j = 0; j < part_cnt; j++) {
name_attr[0] = '\0';
char *group_name = mobi_get_cncx_string(infl->cncx_record, groups[j]);
if (group_name == NULL) {
debug_print("%s\n", "Memory allocation failed");
return MOBI_MALLOC_FAILED;
}
if (strlen(group_name)) {
snprintf(name_attr, INDX_INFLBUF_SIZEMAX, " name=\"%s\"", group_name);
}
free(group_name);
unsigned char decoded[INDX_INFLBUF_SIZEMAX + 1];
memset(decoded, 0, INDX_INFLBUF_SIZEMAX + 1);
unsigned char *rule = (unsigned char *) infl->entries[parts[j]].label;
memcpy(decoded, label, label_length);
int decoded_length = (int) label_length;
MOBI_RET ret = mobi_decode_infl(decoded, &decoded_length, rule);
if (ret != MOBI_SUCCESS) {
return ret;
}
if (decoded_length == 0) {
continue;
}
int n = snprintf(infl_tag, INDX_INFLBUF_SIZEMAX, iform_tag, name_attr, decoded);
if (n > INDX_INFLBUF_SIZEMAX) {
debug_print("Skipping truncated tag: %s\n", infl_tag);
continue;
}
outlen += strlen(infl_tag);
if (outlen > INDX_INFLTAG_SIZEMAX) {
debug_print("Inflections text in %s too long (%zu)\n", label, outlen);
return MOBI_ERROR;
}
strcat(outstring, infl_tag);
}
}
if (outlen == initlen) {
outstring[0] = '\0';
} else {
strcat(outstring, end_tag);
}
return MOBI_SUCCESS;
}

static int
lambda_function_body(
char_u    **arg,
typval_T    *rettv,
evalarg_T   *evalarg,
garray_T    *newargs,
garray_T    *argtypes,
int    varargs,
garray_T    *default_args,
char_u    *ret_type)
{
intevaluate = (evalarg->eval_flags & EVAL_EVALUATE);
garray_T*gap = &evalarg->eval_ga;
garray_T*freegap = &evalarg->eval_freega;
ufunc_T*ufunc = NULL;
exarg_Teap;
garray_Tnewlines;
char_u*cmdline = NULL;
intret = FAIL;
char_u*line_to_free = NULL;
partial_T*pt;
char_u*name;
intlnum_save = -1;
linenr_Tsourcing_lnum_top = SOURCING_LNUM;
if (!ends_excmd2(*arg, skipwhite(*arg + 1)))
{
semsg(_(e_trailing_arg), *arg + 1);
return FAIL;
}
CLEAR_FIELD(eap);
eap.cmdidx = CMD_block;
eap.forceit = FALSE;
eap.cmdlinep = &cmdline;
eap.skip = !evaluate;
if (evalarg->eval_cctx != NULL)
fill_exarg_from_cctx(&eap, evalarg->eval_cctx);
else
{
eap.getline = evalarg->eval_getline;
eap.cookie = evalarg->eval_cookie;
}
ga_init2(&newlines, (int)sizeof(char_u *), 10);
if (get_function_body(&eap, &newlines, NULL, &line_to_free) == FAIL)
{
vim_free(cmdline);
goto erret;
}
evalarg->eval_break_count += newlines.ga_len;
if (gap->ga_itemsize > 0)
{
intidx;
char_u*last;
size_t  plen;
char_u  *pnl;
for (idx = 0; idx < newlines.ga_len; ++idx)
{
char_u  *p = skipwhite(((char_u **)newlines.ga_data)[idx]);
if (ga_grow(gap, 1) == FAIL || ga_grow(freegap, 1) == FAIL)
goto erret;
if (*p == NUL || vim9_comment_start(p))
p = (char_u *)"";
plen = STRLEN(p);
pnl = vim_strnsave((char_u *)"\n", plen + 1);
if (pnl != NULL)
mch_memmove(pnl + 1, p, plen + 1);
((char_u **)gap->ga_data)[gap->ga_len++] = pnl;
((char_u **)freegap->ga_data)[freegap->ga_len++] = pnl;
}
if (ga_grow(gap, 1) == FAIL || ga_grow(freegap, 1) == FAIL)
goto erret;
if (cmdline != NULL)
last = cmdline;
else
last = (char_u *)"}";
plen = STRLEN(last);
pnl = vim_strnsave((char_u *)"\n", plen + 1);
if (pnl != NULL)
mch_memmove(pnl + 1, last, plen + 1);
((char_u **)gap->ga_data)[gap->ga_len++] = pnl;
((char_u **)freegap->ga_data)[freegap->ga_len++] = pnl;
}
if (cmdline != NULL)
{
garray_T *tfgap = &evalarg->eval_tofree_ga;
*arg = eap.nextcmd;
if (ga_grow(tfgap, 1) == OK)
{
((char_u **)(tfgap->ga_data))[tfgap->ga_len++] = cmdline;
evalarg->eval_using_cmdline = TRUE;
}
}
else
*arg = (char_u *)"";
if (!evaluate)
{
ret = OK;
goto erret;
}
name = get_lambda_name();
ufunc = alloc_clear(offsetof(ufunc_T, uf_name) + STRLEN(name) + 1);
if (ufunc == NULL)
goto erret;
set_ufunc_name(ufunc, name);
if (hash_add(&func_hashtab, UF2HIKEY(ufunc)) == FAIL)
goto erret;
ufunc->uf_flags = FC_LAMBDA;
ufunc->uf_refcount = 1;
ufunc->uf_args = *newargs;
newargs->ga_data = NULL;
ufunc->uf_def_args = *default_args;
default_args->ga_data = NULL;
ufunc->uf_func_type = &t_func_any;
lnum_save = SOURCING_LNUM;
SOURCING_LNUM = sourcing_lnum_top;
if (parse_argument_types(ufunc, argtypes, varargs) == FAIL)
{
SOURCING_LNUM = lnum_save;
goto erret;
}
if (parse_return_type(ufunc, ret_type) == FAIL)
goto erret;
pt = ALLOC_CLEAR_ONE(partial_T);
if (pt == NULL)
goto erret;
pt->pt_func = ufunc;
pt->pt_refcount = 1;
ufunc->uf_lines = newlines;
newlines.ga_data = NULL;
if (sandbox)
ufunc->uf_flags |= FC_SANDBOX;
if (!ASCII_ISUPPER(*ufunc->uf_name))
ufunc->uf_flags |= FC_VIM9;
ufunc->uf_script_ctx = current_sctx;
ufunc->uf_script_ctx_version = current_sctx.sc_version;
ufunc->uf_script_ctx.sc_lnum += sourcing_lnum_top;
set_function_type(ufunc);
function_using_block_scopes(ufunc, evalarg->eval_cstack);
rettv->vval.v_partial = pt;
rettv->v_type = VAR_PARTIAL;
ufunc = NULL;
ret = OK;
erret:
if (lnum_save >= 0)
SOURCING_LNUM = lnum_save;
vim_free(line_to_free);
ga_clear_strings(&newlines);
if (newargs != NULL)
ga_clear_strings(newargs);
ga_clear_strings(default_args);
if (ufunc != NULL)
{
func_clear(ufunc, TRUE);
func_free(ufunc, TRUE);
}
return ret;
}

int init_aliases(void)
{
FILE *fp;
char alias[MAXALIASLEN + 1U];
char dir[PATH_MAX + 1U];
if ((fp = fopen(ALIASES_FILE, "r")) == NULL) {
return 0;
}
while (fgets(alias, sizeof alias, fp) != NULL) {
if (*alias == '#' || *alias == '\n' || *alias == 0) {
continue;
}
{
char * const z = alias + strlen(alias) - 1U;
if (*z != '\n') {
goto bad;
}
*z = 0;
}
do {
if (fgets(dir, sizeof dir, fp) == NULL || *dir == 0) {
goto bad;
}
{
char * const z = dir + strlen(dir) - 1U;
if (*z == '\n') {
*z = 0;
}
}
} while (*dir == '#' || *dir == 0);
if (head == NULL) {
if ((head = tail = malloc(sizeof *head)) == NULL ||
(tail->alias = strdup(alias)) == NULL ||
(tail->dir = strdup(dir)) == NULL) {
die_mem();
}
tail->next = NULL;
} else {
DirAlias *curr;
if ((curr = malloc(sizeof *curr)) == NULL ||
(curr->alias = strdup(alias)) == NULL ||
(curr->dir = strdup(dir)) == NULL) {
die_mem();
}
tail->next = curr;
tail = curr;
}
}
fclose(fp);
aliases_up++;
return 0;
bad:
fclose(fp);
logfile(LOG_ERR, MSG_ALIASES_BROKEN_FILE " [" ALIASES_FILE "]");
return -1;
}

