void
FloydSteinbergDitheringC(gx_device_bjc_printer *dev,
byte *row, byte *dithered, uint width,
uint raster, bool limit_extr, bool composeK)
{   byte byteC=0, byteM=0, byteY=0, byteK=0, bitmask = 0x80; 
int i;
int errorC = 0, errorM = 0, errorY = 0, delta;
int err_corrC, err_corrM, err_corrY;
int *err_vect;
if (dev->FloydSteinbergDirectionForward) {
err_vect = dev->FloydSteinbergErrorsC + 3;         
for( i=width; i>0; i--, row+=4, err_vect+=3) { 
err_corrC = dev->bjc_gamma_tableC[ (*row)    + (*(row+3))]
+ dev->FloydSteinbergC;
err_corrM = dev->bjc_gamma_tableM[(*(row+1)) + (*(row+3))]
+ dev->FloydSteinbergM;
err_corrY = dev->bjc_gamma_tableY[(*(row+2)) + (*(row+3))]
+ dev->FloydSteinbergY;
if(err_corrC > 4080 && limit_extr) err_corrC = 4080;
if(err_corrM > 4080 && limit_extr) err_corrM = 4080;
if(err_corrY > 4080 && limit_extr) err_corrY = 4080;
errorC += err_corrC + (*(err_vect + 3));       
errorM += err_corrM + (*(err_vect + 4));       
errorY += err_corrY + (*(err_vect + 5));
if(errorC > dev->bjc_treshold[bjc_rand(dev)])  {
errorC -=  4080;
byteC |=  bitmask;
}
if(errorM > dev->bjc_treshold[bjc_rand(dev)])  {
errorM -=  4080;
byteM |=  bitmask;
}
if(errorY > dev->bjc_treshold[bjc_rand(dev)])  {
errorY -=  4080;
byteY |=  bitmask;
}
*(err_vect+3) = (errorC + 8) >> 4;                   
delta = errorC << 1;                                 
errorC += delta;
*(err_vect-3) += (errorC + 8) >> 4;                  
errorC += delta;
*err_vect += (errorC + 8) >> 4;                           
errorC += delta + 8;                                  
errorC >>= 4;
*(err_vect+4) = (errorM + 8) >> 4;                    
delta = errorM << 1;                                 
errorM += delta;
*(err_vect-2) += (errorM + 8) >> 4;                       
errorM += delta;
*(err_vect+1) += (errorM + 8) >> 4;                           
errorM += delta + 8;                                     
errorM >>= 4;
*(err_vect+5) = (errorY + 8) >> 4;                      
delta = errorY << 1;                                 
errorY += delta;
*(err_vect-1) += (errorY + 8) >> 4;                       
errorY += delta;
*(err_vect+2) += (errorY + 8) >> 4;                           
errorY += delta + 8;                                     
errorY >>= 4;
if (bitmask == 0x01) {
bitmask = 0x80;
if(composeK) {
byteK = byteC & byteM & byteY;
byteC = byteC & ~byteK;
byteM = byteM & ~byteK;
byteY = byteY & ~byteK;
}                               
*dithered            = byteC;
*(dithered+  raster) = byteM;
*(dithered+2*raster) = byteY;
*(dithered+3*raster) = byteK;
byteC = byteM = byteY = byteK = 0;
dithered++;
}
else if(i == 1) {
if(composeK) {
byteK = byteC & byteM & byteY;
byteC = byteC & ~byteK;
byteM = byteM & ~byteK;
byteY = byteY & ~byteK;
}                               
*dithered            = byteC;
*(dithered+  raster) = byteM;
*(dithered+2*raster) = byteY;
*(dithered+3*raster) = byteK;
}
else bitmask >>= 1;
}
dev->FloydSteinbergDirectionForward=false;
}
else {
row += (width << 2) - 4;   
dithered += raster - 1;
err_vect = dev->FloydSteinbergErrorsC + 3 * width + 3;       
bitmask = 1 << ((raster << 3 ) - width) ;
for( i=width; i>0; i--, row-=4, err_vect-=3) {
err_corrC = dev->bjc_gamma_tableC[  (*row)   + (*(row+3))]
+ dev->FloydSteinbergC;
err_corrM = dev->bjc_gamma_tableM[(*(row+1)) + (*(row+3))]
+ dev->FloydSteinbergM;
err_corrY = dev->bjc_gamma_tableY[(*(row+2)) + (*(row+3))]
+ dev->FloydSteinbergY;
if(err_corrC > 4080 && limit_extr) err_corrC = 4080;
if(err_corrM > 4080 && limit_extr) err_corrM = 4080;
if(err_corrY > 4080 && limit_extr) err_corrY = 4080;
errorC += err_corrC + (*(err_vect - 3));       
errorM += err_corrM + (*(err_vect - 2));       
errorY += err_corrY + (*(err_vect - 1));
if(errorC > dev->bjc_treshold[bjc_rand(dev)])  {
errorC -=  4080;
byteC |=  bitmask;
}
if(errorM > dev->bjc_treshold[bjc_rand(dev)])  {
errorM -=  4080;
byteM |=  bitmask;
}
if(errorY > dev->bjc_treshold[bjc_rand(dev)])  {
errorY -=  4080;
byteY |=  bitmask;
}
*(err_vect-3) = (errorC + 8) >> 4;                      
delta = errorC << 1;                                 
errorC += delta;
*(err_vect+3) += (errorC + 8) >> 4;                       
errorC += delta;
*err_vect += (errorC + 8) >> 4;                           
errorC += delta + 8;                                     
errorC >>= 4;
*(err_vect-2) = (errorM + 8) >> 4;                      
delta = errorM << 1;                                 
errorM += delta;
*(err_vect+4) += (errorM + 8) >> 4;                       
errorM += delta;
*(err_vect+1) += (errorM + 8) >> 4;                           
errorM += delta + 8;                                     
errorM >>= 4;
*(err_vect-1) = (errorY + 8) >> 4;                      
delta = errorY << 1;                                 
errorY += delta;
*(err_vect+5) += (errorY + 8) >> 4;                       
errorY += delta;
*(err_vect+2) += (errorY + 8) >> 4;                           
errorY += delta + 8;                                     
errorY >>= 4;
if (bitmask == 0x80) {
bitmask = 0x01;
if(composeK) {
byteK = byteC & byteM & byteY;
byteC = byteC & ~byteK;
byteM = byteM & ~byteK;
byteY = byteY & ~byteK;
}                               
*dithered            = byteC;
*(dithered+  raster) = byteM;
*(dithered+2*raster) = byteY;
*(dithered+3*raster) = byteK;
byteC = byteM = byteY = byteK = 0;
dithered--;
}
else if(i == 1) {
if(composeK) {
byteK = byteC & byteM & byteY;
byteC = byteC & ~byteK;
byteM = byteM & ~byteK;
byteY = byteY & ~byteK;
}                               
*dithered            = byteC;
*(dithered+  raster) = byteM;
*(dithered+2*raster) = byteY;
*(dithered+3*raster) = byteK;
}
else bitmask <<= 1;
}
dev->FloydSteinbergDirectionForward=true;
}
}

int ntlm_read_message_fields(wStream* s, NTLM_MESSAGE_FIELDS* fields)
{
if (Stream_GetRemainingLength(s) < 8)
return -1;
Stream_Read_UINT16(s, fields->Len); 
Stream_Read_UINT16(s, fields->MaxLen); 
Stream_Read_UINT32(s, fields->BufferOffset); 
return 1;
}

Status RangeSize(const Tensor* start_t, const Tensor* limit_t,
const Tensor* delta_t, InferenceContext* const c) {
T start = start_t->scalar<T>()();
T limit = limit_t->scalar<T>()();
T delta = delta_t->scalar<T>()();
if (start > limit && delta > T(0)) {
return errors::InvalidArgument(
"Requires start <= limit when delta > 0: ", start, "/", limit);
}
if (start < limit && delta < T(0)) {
return errors::InvalidArgument(
"Requires start >= limit when delta < 0: ", start, "/", limit);
}
if (delta == T(0)) {
return errors::InvalidArgument("Requires delta != 0");
}
auto size = (std::is_integral<T>::value
? ((Eigen::numext::abs(limit - start) +
Eigen::numext::abs(delta) - T(1)) /
Eigen::numext::abs(delta))
: (Eigen::numext::ceil(
Eigen::numext::abs((limit - start) / delta))));
if (size > std::numeric_limits<int64_t>::max()) {
return errors::InvalidArgument("Requires ((limit - start) / delta) <= ",
std::numeric_limits<int64_t>::max());
}
c->set_output(0, c->Vector(static_cast<int64_t>(size)));
return Status::OK();
}

int nvmx_handle_vmptrst(struct cpu_user_regs *regs)
{
struct vcpu *v = current;
struct vmx_inst_decoded decode;
struct nestedvcpu *nvcpu = &vcpu_nestedhvm(v);
pagefault_info_t pfinfo;
unsigned long gpa = 0;
int rc;
rc = decode_vmx_inst(regs, &decode, &gpa, 0);
if ( rc != X86EMUL_OKAY )
return rc;
gpa = nvcpu->nv_vvmcxaddr;
rc = hvm_copy_to_guest_linear(decode.mem, &gpa, decode.len, 0, &pfinfo);
if ( rc == HVMTRANS_bad_linear_to_gfn )
hvm_inject_page_fault(pfinfo.ec, pfinfo.linear);
if ( rc != HVMTRANS_okay )
return X86EMUL_EXCEPTION;
vmsucceed(regs);
return X86EMUL_OKAY;
}

int main(int argc, char** argv) {
el::Configurations defaultConf = LogHandler::setupLogHandler(&argc, &argv);
LogHandler::setupStdoutLogger();
et::HandleTerminate();
::signal(SIGINT, et::InterruptSignalHandler);
cxxopts::Options options("etterminal", "User terminal for Eternal Terminal.");
try {
options.allow_unrecognised_options();
options.add_options()                 ("h,help", "Print help")          ("idpasskey",
"If set, uses IPC to send a client id/key to the server daemon. "
"Alternatively, pass in via stdin.",
cxxopts::value<std::string>()->default_value(""))          ("idpasskeyfile",
"If set, uses IPC to send a client id/key to the server daemon from a "
"file. Alternatively, pass in via stdin.",
cxxopts::value<std::string>()->default_value(""))          ("jump",
"If set, forward all packets between client and dst terminal")          ("dsthost", "Must be set if jump is set to true",
cxxopts::value<std::string>()->default_value(""))          ("dstport", "Must be set if jump is set to true",
cxxopts::value<int>()->default_value("2022"))                  ("v,verbose", "Enable verbose logging",
cxxopts::value<int>()->default_value("0"))          ("logtostdout", "Write log to stdout")               ("serverfifo",
"If set, connects to the etserver instance listening on the matching "
"fifo name",                                                cxxopts::value<std::string>()->default_value(""))          ;
auto result = options.parse(argc, argv);
if (result.count("help")) {
CLOG(INFO, "stdout") << options.help({}) << endl;
exit(0);
}
el::Loggers::setVerboseLevel(result["verbose"].as<int>());
GOOGLE_PROTOBUF_VERIFY_VERSION;
srand(1);
ServerFifoPath serverFifo;
if (!result["serverfifo"].as<string>().empty()) {
serverFifo.setPathOverride(result["serverfifo"].as<string>());
}
shared_ptr<SocketHandler> ipcSocketHandler(new PipeSocketHandler());
shared_ptr<PsuedoUserTerminal> term(new PsuedoUserTerminal());
string idpasskey;
if (result.count("idpasskey") == 0 && result.count("idpasskeyfile") == 0) {
struct timeval timeout;
timeout.tv_sec = 1;
timeout.tv_usec = 0;
fd_set readfds;
FD_ZERO(&readfds);
FD_SET(STDIN_FILENO, &readfds);
int selectResult = 0;
do {
selectResult = select(1, &readfds, NULL, NULL, &timeout);
} while (selectResult < 0 && errno == EINTR);
FATAL_FAIL(selectResult);
if (selectResult == 0) {
CLOG(INFO, "stdout")
<< "Call etterminal with --idpasskey or --idpasskeyfile, or feed "
"this information on stdin\n";
exit(1);
}
string stdinData;
if (!getline(cin, stdinData)) {
CLOG(INFO, "stdout")
<< "Call etterminal with --idpasskey or --idpasskeyfile, or feed "
"this information on stdin\n";
exit(1);
}
auto tokens = split(stdinData, '_');
if (tokens.size() == 2) {
idpasskey = tokens[0];
if (idpasskey.substr(0, 3) == std::string("XXX")) {
string passkey = genRandomAlphaNum(32);
string id = genRandomAlphaNum(16);
idpasskey = id + string("/") + passkey;
}
FATAL_FAIL(setenv("TERM", tokens[1].c_str(), 1));
} else {
STFATAL << "Invalid number of tokens: " << tokens.size();
}
} else {
string idpasskey = result["idpasskey"].as<string>();
if (result.count("idpasskeyfile")) {
std::ifstream t(result["idpasskeyfile"].as<string>().c_str());
std::stringstream buffer;
buffer << t.rdbuf();
idpasskey = buffer.str();
idpasskey.erase(idpasskey.find_last_not_of(" \n\r\t") + 1);
}
}
string id = split(idpasskey, '/')[0];
string username = string(ssh_get_local_username());
if (result.count("jump")) {
LogHandler::setupLogFiles(&defaultConf, GetTempDirectory(),
("etjump-" + username + "-" + id),
result.count("logtostdout"), false);
el::Loggers::reconfigureLogger("default", defaultConf);
el::Helpers::setThreadName("jump-main");
el::Helpers::installPreRollOutCallback(LogHandler::rolloutHandler);
CLOG(INFO, "stdout") << "IDPASSKEY:" << idpasskey << endl;
if (DaemonCreator::createSessionLeader() == -1) {
STFATAL << "Error creating daemon: " << strerror(GetErrno());
}
SocketEndpoint destinationEndpoint;
destinationEndpoint.set_name(result["dsthost"].as<string>());
destinationEndpoint.set_port(result["dstport"].as<int>());
shared_ptr<SocketHandler> jumpClientSocketHandler(new TcpSocketHandler());
UserJumphostHandler ujh(jumpClientSocketHandler, idpasskey,
destinationEndpoint, ipcSocketHandler,
serverFifo.getEndpointForConnect());
ujh.run();
el::Helpers::uninstallPreRollOutCallback();
return 0;
}
LogHandler::setupLogFiles(&defaultConf, GetTempDirectory(),
("etterminal-" + username + "-" + id),
result.count("logtostdout"), false);
el::Loggers::reconfigureLogger("default", defaultConf);
el::Helpers::setThreadName("terminal-main");
el::Helpers::installPreRollOutCallback(LogHandler::rolloutHandler);
UserTerminalHandler uth(ipcSocketHandler, term, true,
serverFifo.getEndpointForConnect(), idpasskey);
CLOG(INFO, "stdout") << "IDPASSKEY:" << idpasskey << endl;
if (DaemonCreator::createSessionLeader() == -1) {
STFATAL << "Error creating daemon: " << strerror(GetErrno());
}
uth.run();
} catch (cxxopts::OptionException& oe) {
CLOG(INFO, "stdout") << "Exception: " << oe.what() << "\n" << endl;
CLOG(INFO, "stdout") << options.help({}) << endl;
exit(1);
}
el::Helpers::uninstallPreRollOutCallback();
return 0;
}

