int extract_status_code(char *buffer, size_t size)
{
char *buf_code;
char *begin;
char *end = buffer + size;
size_t inc = 0;
int code;
buf_code = (char *)MALLOC(10);
while (buffer < end && *buffer++ != ' ') ;
begin = buffer;
while (buffer < end && *buffer++ != ' ')
inc++;
strncat(buf_code, begin, inc);
code = atoi(buf_code);
FREE(buf_code);
return code;
}

bfd_byte *
bfd_generic_get_relocated_section_contents (bfd *abfd,
struct bfd_link_info *link_info,
struct bfd_link_order *link_order,
bfd_byte *data,
bfd_boolean relocatable,
asymbol **symbols)
{
bfd *input_bfd = link_order->u.indirect.section->owner;
asection *input_section = link_order->u.indirect.section;
long reloc_size;
arelent **reloc_vector;
long reloc_count;
reloc_size = bfd_get_reloc_upper_bound (input_bfd, input_section);
if (reloc_size < 0)
return NULL;
if (!bfd_get_full_section_contents (input_bfd, input_section, &data))
return NULL;
if (data == NULL)
return NULL;
if (reloc_size == 0)
return data;
reloc_vector = (arelent **) bfd_malloc (reloc_size);
if (reloc_vector == NULL)
return NULL;
reloc_count = bfd_canonicalize_reloc (input_bfd,
input_section,
reloc_vector,
symbols);
if (reloc_count < 0)
goto error_return;
if (reloc_count > 0)
{
arelent **parent;
for (parent = reloc_vector; *parent != NULL; parent++)
{
char *error_message = NULL;
asymbol *symbol;
bfd_reloc_status_type r;
symbol = *(*parent)->sym_ptr_ptr;
if (symbol == NULL)
{
link_info->callbacks->einfo
(_("%X%P: %pB(%pA): error: relocation for offset %V has no value\n"),
abfd, input_section, (* parent)->address);
goto error_return;
}
if ((symbol->section != NULL && discarded_section (symbol->section))
|| (symbol->section == bfd_und_section_ptr
&& (input_section->flags & SEC_DEBUGGING) != 0
&& link_info->input_bfds == link_info->output_bfd))
{
bfd_byte *p;
static reloc_howto_type none_howto
= HOWTO (0, 0, 0, 0, FALSE, 0, complain_overflow_dont, NULL,
"unused", FALSE, 0, 0, FALSE);
p = data + (*parent)->address * bfd_octets_per_byte (input_bfd);
_bfd_clear_contents ((*parent)->howto, input_bfd, input_section,
p);
(*parent)->sym_ptr_ptr = bfd_abs_section_ptr->symbol_ptr_ptr;
(*parent)->addend = 0;
(*parent)->howto = &none_howto;
r = bfd_reloc_ok;
}
else
r = bfd_perform_relocation (input_bfd,
*parent,
data,
input_section,
relocatable ? abfd : NULL,
&error_message);
if (relocatable)
{
asection *os = input_section->output_section;
os->orelocation[os->reloc_count] = *parent;
os->reloc_count++;
}
if (r != bfd_reloc_ok)
{
switch (r)
{
case bfd_reloc_undefined:
(*link_info->callbacks->undefined_symbol)
(link_info, bfd_asymbol_name (*(*parent)->sym_ptr_ptr),
input_bfd, input_section, (*parent)->address, TRUE);
break;
case bfd_reloc_dangerous:
BFD_ASSERT (error_message != NULL);
(*link_info->callbacks->reloc_dangerous)
(link_info, error_message,
input_bfd, input_section, (*parent)->address);
break;
case bfd_reloc_overflow:
(*link_info->callbacks->reloc_overflow)
(link_info, NULL,
bfd_asymbol_name (*(*parent)->sym_ptr_ptr),
(*parent)->howto->name, (*parent)->addend,
input_bfd, input_section, (*parent)->address);
break;
case bfd_reloc_outofrange:
link_info->callbacks->einfo
(_("%X%P: %pB(%pA): relocation \"%pR\" goes out of range\n"),
abfd, input_section, * parent);
goto error_return;
case bfd_reloc_notsupported:
link_info->callbacks->einfo
(_("%X%P: %pB(%pA): relocation \"%pR\" is not supported\n"),
abfd, input_section, * parent);
goto error_return;
default:
link_info->callbacks->einfo
(_("%X%P: %pB(%pA): relocation \"%pR\" returns an unrecognized value %x\n"),
abfd, input_section, * parent, r);
break;
}
}
}
}
free (reloc_vector);
return data;
error_return:
free (reloc_vector);
return NULL;
}

long
video_usercopy(struct file *file, unsigned int orig_cmd, unsigned long arg,
v4l2_kioctl func)
{
charsbuf[128];
void    *mbuf = NULL;
void*parg = (void *)arg;
longerr  = -EINVAL;
boolhas_array_args;
boolalways_copy = false;
size_t  array_size = 0;
void __user *user_ptr = NULL;
void**kernel_ptr = NULL;
unsigned int cmd = video_translate_cmd(orig_cmd);
const size_t ioc_size = _IOC_SIZE(cmd);
if (_IOC_DIR(cmd) != _IOC_NONE) {
if (ioc_size <= sizeof(sbuf)) {
parg = sbuf;
} else {
mbuf = kvmalloc(ioc_size, GFP_KERNEL);
if (NULL == mbuf)
return -ENOMEM;
parg = mbuf;
}
err = video_get_user((void __user *)arg, parg, cmd,
orig_cmd, &always_copy);
if (err)
goto out;
}
err = check_array_args(cmd, parg, &array_size, &user_ptr, &kernel_ptr);
if (err < 0)
goto out;
has_array_args = err;
if (has_array_args) {
mbuf = kvmalloc(array_size, GFP_KERNEL);
err = -ENOMEM;
if (NULL == mbuf)
goto out_array_args;
err = -EFAULT;
if (in_compat_syscall())
err = v4l2_compat_get_array_args(file, mbuf, user_ptr,
array_size, orig_cmd,
parg);
else
err = copy_from_user(mbuf, user_ptr, array_size) ?
-EFAULT : 0;
if (err)
goto out_array_args;
*kernel_ptr = mbuf;
}
err = func(file, cmd, parg);
if (err == -ENOTTY || err == -ENOIOCTLCMD) {
err = -ENOTTY;
goto out;
}
if (err == 0) {
if (cmd == VIDIOC_DQBUF)
trace_v4l2_dqbuf(video_devdata(file)->minor, parg);
else if (cmd == VIDIOC_QBUF)
trace_v4l2_qbuf(video_devdata(file)->minor, parg);
}
if (has_array_args) {
*kernel_ptr = (void __force *)user_ptr;
if (in_compat_syscall()) {
int put_err;
put_err = v4l2_compat_put_array_args(file, user_ptr, mbuf,
array_size, orig_cmd,
parg);
if (put_err)
err = put_err;
} else if (copy_to_user(user_ptr, mbuf, array_size)) {
err = -EFAULT;
}
goto out_array_args;
}
if (err < 0 && !always_copy)
goto out;
out_array_args:
if (video_put_user((void __user *)arg, parg, cmd, orig_cmd))
err = -EFAULT;
out:
kvfree(mbuf);
return err;
}

static void
input_l2cap_frame_flow_channel(l2cap_channel_t *channel, uint8_t *data, uint16_t data_len)
{
uint16_t frame_len;
uint16_t payload_len;
if(data_len < 4) {
LOG_WARN("l2cap_frame: illegal L2CAP frame data_len: %d\n", data_len);
return;
}
if(channel->rx_buffer.sdu_length == 0) {
memcpy(&frame_len, &data[0], 2);
payload_len = frame_len - 2;
if(payload_len > BLE_L2CAP_NODE_MTU) {
LOG_WARN("l2cap_frame: illegal L2CAP frame payload_len: %d\n", payload_len);
return;
}
memcpy(&channel->rx_buffer.sdu_length, &data[4], 2);
memcpy(channel->rx_buffer.sdu, &data[6], payload_len);
channel->rx_buffer.current_index = payload_len;
} else {
memcpy(&frame_len, &data[0], 2);
payload_len = frame_len;
if(payload_len > BLE_L2CAP_NODE_MTU - channel->rx_buffer.current_index) {
LOG_WARN("l2cap_frame: illegal L2CAP frame payload_len: %d\n", payload_len);
return;
}
memcpy(&channel->rx_buffer.sdu[channel->rx_buffer.current_index], &data[4], payload_len);
channel->rx_buffer.current_index += payload_len;
}
if((channel->rx_buffer.sdu_length > 0) &&
(channel->rx_buffer.sdu_length == channel->rx_buffer.current_index)) {
memcpy(packetbuf_dataptr(), channel->rx_buffer.sdu, channel->rx_buffer.sdu_length);
packetbuf_set_datalen(channel->rx_buffer.sdu_length);
NETSTACK_NETWORK.input();
channel->rx_buffer.sdu_length = 0;
channel->rx_buffer.current_index = 0;
}
}

static void
wstran_pipe_recv_cb(void *arg)
{
ws_pipe *p = arg;
nni_iov  iov[2];
uint8_t  rv;
uint32_t pos = 1;
uint64_t len = 0;
uint8_t *ptr;
nni_msg *smsg = NULL, *msg = NULL;
nni_aio *raio = p->rxaio;
nni_aio *uaio = NULL;
bool     ack  = false;
nni_mtx_lock(&p->mtx);
if (p->user_rxaio != NULL) {
uaio = p->user_rxaio;
}
if ((rv = nni_aio_result(raio)) != 0) {
log_warn(" recv aio error %s", nng_strerror(rv));
goto reset;
}
msg = nni_aio_get_msg(raio);
if (nni_msg_header_len(msg) == 0 && nni_msg_len(msg) == 0) {
log_trace("empty msg received! continue next receive");
goto recv;
}
ptr = nni_msg_body(msg);
p->gotrxhead += nni_msg_len(msg);
log_trace("#### wstran_pipe_recv_cb got %ld msg: %p %x %ld",
p->gotrxhead, ptr, *ptr, nni_msg_len(msg));
if (p->tmp_msg == NULL && p->gotrxhead > 0) {
if ((rv = nni_msg_alloc(&p->tmp_msg, 0)) != 0) {
log_error("mem error %ld\n", (size_t) len);
goto reset;
}
}
nni_msg_append(p->tmp_msg, ptr, nni_msg_len(msg));
ptr = nni_msg_body(p->tmp_msg); 
if (p->wantrxhead == 0) {
if (p->gotrxhead == 1) {
goto recv;
}
len = get_var_integer(ptr, &pos);
if (*(ptr + pos - 1) > 0x7f) {
if (p->gotrxhead >= NNI_NANO_MAX_HEADER_SIZE) {
rv = NNG_EMSGSIZE;
goto reset;
}
} else {
p->wantrxhead = len + pos;
nni_msg_set_cmd_type(p->tmp_msg, *ptr & 0xf0);
}
}
if (p->gotrxhead >= p->wantrxhead) {
goto done;
}
recv:
nni_msg_free(msg);
nng_stream_recv(p->ws, raio);
nni_mtx_unlock(&p->mtx);
return;
done:
if (uaio == NULL) {
uaio = p->ep_aio;
}
if (uaio != NULL) {
if (p->gotrxhead+p->wantrxhead > p->conf->max_packet_size) {
log_trace("size error 0x95\n");
rv = NMQ_PACKET_TOO_LARGE;
goto recv_error;
}
p->gotrxhead  = 0;
p->wantrxhead = 0;
nni_msg_free(msg);
if (nni_msg_cmd_type(p->tmp_msg) == CMD_CONNECT) {
if (p->ws_param == NULL) {
conn_param_alloc(&p->ws_param);
}
if (conn_handler(nni_msg_body(p->tmp_msg), p->ws_param,
nni_msg_len(p->tmp_msg)) != 0) {
conn_param_free(p->ws_param);
rv = NNG_ECONNRESET;
goto reset;
}
if (p->ws_param->pro_ver == 5) {
p->qsend_quota = p->ws_param->rx_max;
}
if (p->ws_param->max_packet_size == 0) {
p->ws_param->max_packet_size =
p->conf->client_max_packet_size;
}
nni_msg_free(p->tmp_msg);
p->tmp_msg = NULL;
nni_aio_set_output(uaio, 0, p);
nni_aio_finish(uaio, 0, 0);
nni_mtx_unlock(&p->mtx);
return;
} else {
if (nni_msg_alloc(&smsg, 0) != 0) {
goto reset;
}
ws_msg_adaptor(ptr, smsg);
nni_msg_free(p->tmp_msg);
p->tmp_msg = NULL;
nni_msg_set_conn_param(smsg, p->ws_param);
}
uint8_t   qos_pac;
property *prop        = NULL;
uint8_t   reason_code = 0;
uint8_t   ack_cmd     = 0;
uint16_t packet_id = 0;
nni_msg *qmsg;
uint8_t  cmd = nni_msg_cmd_type(smsg);
if (cmd == CMD_PUBLISH) {
qos_pac = nni_msg_get_pub_qos(smsg);
if (qos_pac > 0) {
if (p->ws_param->pro_ver == 5) {
if (p->qrecv_quota > 0) {
p->qrecv_quota--;
} else {
rv = NMQ_RECEIVE_MAXIMUM_EXCEEDED;
goto recv_error;
}
}
if (qos_pac == 1) {
ack_cmd = CMD_PUBACK;
} else if (qos_pac == 2) {
ack_cmd = CMD_PUBREC;
}
packet_id = nni_msg_get_pub_pid(smsg);
ack       = true;
}
} else if (cmd == CMD_PUBREC) {
if (nni_mqtt_pubres_decode(smsg, &packet_id, &reason_code, &prop,
p->ws_param->pro_ver) != 0) {
log_trace("decode PUBREC variable header failed!");
}
ack_cmd = CMD_PUBREL;
ack     = true;
} else if (cmd == CMD_PUBREL) {
if (nni_mqtt_pubres_decode(smsg, &packet_id, &reason_code, &prop,
p->ws_param->pro_ver) != 0) {
log_trace("decode PUBREL variable header failed!");
}
ack_cmd = CMD_PUBCOMP;
ack     = true;
} else if (cmd == CMD_PUBACK || cmd == CMD_PUBCOMP) {
if (nni_mqtt_pubres_decode(smsg, &packet_id, &reason_code, &prop,
p->ws_param->pro_ver) != 0) {
log_trace("decode PUBACK or PUBCOMP variable header "
"failed!");
}
if (p->ws_param->pro_ver == 5) {
property_free(prop);
p->qsend_quota++;
}
} else if (cmd == CMD_PINGREQ) {
ack = true;
}
if (ack == true) {
if ((rv = nni_msg_alloc(&qmsg, 0)) != 0) {
ack = false;
rv  = NMQ_SERVER_BUSY;
log_error("ERROR: OOM in WebSocket");
goto recv_error;
}
if (cmd == CMD_PINGREQ) {
uint8_t buf[2] = { CMD_PINGRESP, 0x00 };
nni_msg_set_cmd_type(qmsg, CMD_PINGRESP);
nni_msg_header_append(qmsg, buf, 2);
nng_aio_wait(p->qsaio);
iov[0].iov_len = nni_msg_header_len(qmsg);
iov[0].iov_buf = nni_msg_header(qmsg);
nni_aio_set_msg(p->qsaio, qmsg);
nni_aio_set_iov(p->qsaio, 1, iov);
nng_stream_send(p->ws, p->qsaio);
} else {
nni_msg_set_cmd_type(qmsg, ack_cmd);
nni_mqtt_msgack_encode(qmsg, packet_id, reason_code,
prop, p->ws_param->pro_ver);
nni_mqtt_pubres_header_encode(qmsg, ack_cmd);
nng_aio_wait(p->qsaio);
iov[0].iov_len = nni_msg_header_len(qmsg);
iov[0].iov_buf = nni_msg_header(qmsg);
iov[1].iov_len = nni_msg_len(qmsg);
iov[1].iov_buf = nni_msg_body(qmsg);
nni_aio_set_msg(p->qsaio, qmsg);
nni_aio_set_iov(p->qsaio, 2, iov);
nng_stream_send(p->ws, p->qsaio);
}
}
nni_aio_set_msg(uaio, smsg);
nni_aio_set_output(uaio, 0, p);
} else {
goto reset;
}
nni_mtx_unlock(&p->mtx);
nni_aio_finish(uaio, 0, nni_msg_len(smsg));
return;
reset:
p->gotrxhead  = 0;
p->wantrxhead = 0;
nng_stream_close(p->ws);
if (uaio != NULL) {
nni_aio_finish_error(uaio, rv);
} else if (p->ep_aio != NULL) {
nni_aio_finish_error(p->ep_aio, rv);
}
if (p->tmp_msg != NULL) {
smsg = p->tmp_msg;
nni_msg_free(smsg);
p->tmp_msg = NULL;
}
nni_mtx_unlock(&p->mtx);
return;
recv_error:
nni_pipe_bump_error(p->npipe, rv);
nni_mtx_unlock(&p->mtx);
nni_msg_free(msg);
log_error("tcptran_pipe_recv_cb: recv error rv: %d\n", rv);
return;
}

GF_Err txtc_Read(GF_Box *s, GF_BitStream *bs)
{
u32 size, i;
char *str;
GF_TextConfigBox *ptr = (GF_TextConfigBox*)s;
size = (u32) ptr->size;
str = (char *)gf_malloc(sizeof(char)*size);
i=0;
while (size) {
str[i] = gf_bs_read_u8(bs);
size--;
if (!str[i])
break;
i++;
}
if (i) ptr->config = gf_strdup(str);
gf_free(str);
return GF_OK;
}

void nf_tables_deactivate_set(const struct nft_ctx *ctx, struct nft_set *set,
struct nft_set_binding *binding,
enum nft_trans_phase phase)
{
switch (phase) {
case NFT_TRANS_PREPARE:
set->use--;
return;
case NFT_TRANS_ABORT:
case NFT_TRANS_RELEASE:
set->use--;
fallthrough;
default:
nf_tables_unbind_set(ctx, set, binding,
phase == NFT_TRANS_COMMIT);
}
}

u_int
juniper_pppoe_atm_print(netdissect_options *ndo,
const struct pcap_pkthdr *h, register const u_char *p)
{
struct juniper_l2info_t l2info;
uint16_t extracted_ethertype;
l2info.pictype = DLT_JUNIPER_PPPOE_ATM;
if (juniper_parse_header(ndo, p, h, &l2info) == 0)
return l2info.header_len;
p+=l2info.header_len;
extracted_ethertype = EXTRACT_16BITS(p);
if (ethertype_print(ndo, extracted_ethertype,
p+ETHERTYPE_LEN,
l2info.length-ETHERTYPE_LEN,
l2info.caplen-ETHERTYPE_LEN,
NULL, NULL) == 0)
ND_PRINT((ndo, "unknown ethertype 0x%04x", extracted_ethertype));
return l2info.header_len;
}

static int mcryptd_create_hash(struct crypto_template *tmpl, struct rtattr **tb,
struct mcryptd_queue *queue)
{
struct hashd_instance_ctx *ctx;
struct ahash_instance *inst;
struct hash_alg_common *halg;
struct crypto_alg *alg;
u32 type = 0;
u32 mask = 0;
int err;
mcryptd_check_internal(tb, &type, &mask);
halg = ahash_attr_alg(tb[1], type, mask);
if (IS_ERR(halg))
return PTR_ERR(halg);
alg = &halg->base;
pr_debug("crypto: mcryptd hash alg: %s\n", alg->cra_name);
inst = mcryptd_alloc_instance(alg, ahash_instance_headroom(),
sizeof(*ctx));
err = PTR_ERR(inst);
if (IS_ERR(inst))
goto out_put_alg;
ctx = ahash_instance_ctx(inst);
ctx->queue = queue;
err = crypto_init_ahash_spawn(&ctx->spawn, halg,
ahash_crypto_instance(inst));
if (err)
goto out_free_inst;
type = CRYPTO_ALG_ASYNC;
if (alg->cra_flags & CRYPTO_ALG_INTERNAL)
type |= CRYPTO_ALG_INTERNAL;
inst->alg.halg.base.cra_flags = type;
inst->alg.halg.digestsize = halg->digestsize;
inst->alg.halg.statesize = halg->statesize;
inst->alg.halg.base.cra_ctxsize = sizeof(struct mcryptd_hash_ctx);
inst->alg.halg.base.cra_init = mcryptd_hash_init_tfm;
inst->alg.halg.base.cra_exit = mcryptd_hash_exit_tfm;
inst->alg.init   = mcryptd_hash_init_enqueue;
inst->alg.update = mcryptd_hash_update_enqueue;
inst->alg.final  = mcryptd_hash_final_enqueue;
inst->alg.finup  = mcryptd_hash_finup_enqueue;
inst->alg.export = mcryptd_hash_export;
inst->alg.import = mcryptd_hash_import;
inst->alg.setkey = mcryptd_hash_setkey;
inst->alg.digest = mcryptd_hash_digest_enqueue;
err = ahash_register_instance(tmpl, inst);
if (err) {
crypto_drop_ahash(&ctx->spawn);
out_free_inst:
kfree(inst);
}
out_put_alg:
crypto_mod_put(alg);
return err;
}

StaticSlice ContentTypeMetadata::Encode(ValueType x) {
switch (x) {
case kEmpty:
return StaticSlice::FromStaticString("");
case kApplicationGrpc:
return StaticSlice::FromStaticString("application/grpc");
case kInvalid:
return StaticSlice::FromStaticString("application/grpc+unknown");
}
GPR_UNREACHABLE_CODE(
return StaticSlice::FromStaticString("unrepresentable value"));
}
const char* ContentTypeMetadata::DisplayValue(ValueType content_type) {
switch (content_type) {
case ValueType::kApplicationGrpc:
return "application/grpc";
case ValueType::kEmpty:
return "";
default:
return "<discarded-invalid-value>";
}
}
GrpcTimeoutMetadata::MementoType GrpcTimeoutMetadata::ParseMemento(
Slice value, MetadataParseErrorFn on_error) {
auto timeout = ParseTimeout(value);
if (!timeout.has_value()) {
on_error("invalid value", value);
return Duration::Infinity();
}
return *timeout;
}
GrpcTimeoutMetadata::ValueType GrpcTimeoutMetadata::MementoToValue(
MementoType timeout) {
if (timeout == Duration::Infinity()) {
return Timestamp::InfFuture();
}
return Timestamp::Now() + timeout;
}
Slice GrpcTimeoutMetadata::Encode(ValueType x) {
return Timeout::FromDuration(x - Timestamp::Now()).Encode();
}
TeMetadata::MementoType TeMetadata::ParseMemento(
Slice value, MetadataParseErrorFn on_error) {
auto out = kInvalid;
if (value == "trailers") {
out = kTrailers;
} else {
on_error("invalid value", value);
}
return out;
}
const char* TeMetadata::DisplayValue(ValueType te) {
switch (te) {
case ValueType::kTrailers:
return "trailers";
default:
return "<discarded-invalid-value>";
}
}
HttpSchemeMetadata::ValueType HttpSchemeMetadata::Parse(
absl::string_view value, MetadataParseErrorFn on_error) {
if (value == "http") {
return kHttp;
} else if (value == "https") {
return kHttps;
}
on_error("invalid value", Slice::FromCopiedBuffer(value));
return kInvalid;
}
StaticSlice HttpSchemeMetadata::Encode(ValueType x) {
switch (x) {
case kHttp:
return StaticSlice::FromStaticString("http");
case kHttps:
return StaticSlice::FromStaticString("https");
default:
abort();
}
}
const char* HttpSchemeMetadata::DisplayValue(ValueType content_type) {
switch (content_type) {
case kHttp:
return "http";
case kHttps:
return "https";
default:
return "<discarded-invalid-value>";
}
}
HttpMethodMetadata::MementoType HttpMethodMetadata::ParseMemento(
Slice value, MetadataParseErrorFn on_error) {
auto out = kInvalid;
auto value_string = value.as_string_view();
if (value_string == "POST") {
out = kPost;
} else if (value_string == "PUT") {
out = kPut;
} else if (value_string == "GET") {
out = kGet;
} else {
on_error("invalid value", value);
}
return out;
}
