static void parse_outhdr_string(const guchar *outhdr_string, gint outhdr_string_len)
{
int   n                 = 0;
for (outhdr_values_found=0; outhdr_values_found < MAX_OUTHDR_VALUES; ) {
guint  digit_array[MAX_OUTHDR_VALUES];
guint  number_digits = 0;
guint   number = 0;
guint   multiplier = 1;
guint   d;
for ( ; n < outhdr_string_len; n++) {
if (!g_ascii_isdigit(outhdr_string[n])) {
break;
}
else {
digit_array[number_digits++] = outhdr_string[n] - '0';
}
}
if (number_digits == 0) {
break;
}
for (d=number_digits; d > 0; d--) {
number += ((digit_array[d-1]) * multiplier);
multiplier *= 10;
}
outhdr_values[outhdr_values_found++] = number;
n++;
}
}

ANeuralNetworksModel* convertSubgraphFromHAL(
const NnApiSupportLibrary* nnapi,
const std::vector<std::unique_ptr<::android::nn::sl_wrapper::Memory>>& memoryPools,
const neuralnetworks::Model& model,
std::vector<std::optional<::android::nn::sl_wrapper::Model>>* allModels,
size_t subgraphIndex, const std::vector<uint8_t>& copiedOperandValues,
ErrorStatus* errorStatus) {
*errorStatus = ErrorStatus::NONE;
if ((*allModels)[subgraphIndex].has_value()) {
return (*allModels)[subgraphIndex]->getHandle();
}
const auto& subgraph = subgraphIndex == 0 ? model.main : model.referenced[subgraphIndex - 1];
::android::nn::sl_wrapper::Model resultModel(nnapi);
resultModel.relaxComputationFloat32toFloat16(model.relaxComputationFloat32toFloat16);
auto getExtensionName = [&](uint16_t prefix) -> const std::string* {
for (const auto& nameToPrefix : model.extensionNameToPrefix) {
if (prefix == nameToPrefix.prefix) {
return &nameToPrefix.name;
}
}
return nullptr;
};
for (int i = 0; i < subgraph.operands.size(); ++i) {
const auto& operand = subgraph.operands[i];
const std::vector<uint32_t> dimensions =
::android::nn::toUnsigned(operand.dimensions).value();
::android::nn::wrapper::OperandType operandType(
static_cast<::android::nn::wrapper::Type>(operand.type), dimensions, operand.scale,
operand.zeroPoint);
if (operand.type == OperandType::TENSOR_QUANT8_SYMM_PER_CHANNEL) {
const auto& params = operand.extraParams->get<OperandExtraParams::Tag::channelQuant>();
operandType.channelQuant = ::android::nn::wrapper::SymmPerChannelQuantParams(
params.scales, static_cast<uint32_t>(params.channelDim));
}
if (::android::nn::isExtension(static_cast<::android::nn::OperandType>(operand.type))) {
uint16_t extensionPrefix =
::android::nn::getExtensionPrefix(static_cast<uint32_t>(operand.type));
uint16_t typeWithinExtension =
::android::nn::getTypeWithinExtension(static_cast<uint32_t>(operand.type));
auto* extensionName = getExtensionName(extensionPrefix);
if (extensionName == nullptr) {
LOG(ERROR) << "Unknown extension prefix " << extensionPrefix;
*errorStatus = ErrorStatus::INVALID_ARGUMENT;
return nullptr;
}
resultModel.getExtensionOperandType(*extensionName, typeWithinExtension,
&operandType.operandType.type);
if (!resultModel.isValid()) {
LOG(ERROR) << "Failed to get extension operand with index " << i;
*errorStatus = ErrorStatus::INVALID_ARGUMENT;
return nullptr;
}
}
uint32_t operandIndex = resultModel.addOperand(&operandType);
if (!resultModel.isValid()) {
LOG(ERROR) << "Failed to add operand with index " << i;
*errorStatus = ErrorStatus::INVALID_ARGUMENT;
return nullptr;
}
if (operand.extraParams &&
operand.extraParams->getTag() == OperandExtraParams::Tag::extension) {
const auto& extensionData =
operand.extraParams->get<OperandExtraParams::Tag::extension>();
resultModel.setOperandExtensionData(operandIndex, extensionData.data(),
extensionData.size());
if (!resultModel.isValid()) {
LOG(ERROR) << "Failed to add extension data for operand with index " << i;
*errorStatus = ErrorStatus::INVALID_ARGUMENT;
return nullptr;
}
}
switch (operand.lifetime) {
case OperandLifeTime::CONSTANT_COPY: {
if (operand.location.length + operand.location.offset >
model.operandValues.size()) {
*errorStatus = ErrorStatus::INVALID_ARGUMENT;
return nullptr;
}
if (operand.location.length <=
ANEURALNETWORKS_MAX_SIZE_OF_IMMEDIATELY_COPIED_VALUES) {
resultModel.setOperandValue(
i, model.operandValues.data() + operand.location.offset,
operand.location.length);
} else {
resultModel.setOperandValue(
i, copiedOperandValues.data() + operand.location.offset,
operand.location.length);
}
break;
}
case OperandLifeTime::CONSTANT_POOL: {
resultModel.setOperandValueFromMemory(
i, memoryPools[operand.location.poolIndex].get(), operand.location.offset,
operand.location.length);
break;
}
case OperandLifeTime::SUBGRAPH: {
ErrorStatus otherErrorStatus = ErrorStatus::NONE;
auto subgraph = convertSubgraphFromHAL(nnapi, memoryPools, model, allModels,
operand.location.offset + 1,
copiedOperandValues, &otherErrorStatus);
if (subgraph) {
resultModel.setOperandValueFromModel(i, subgraph);
} else {
LOG(ERROR) << "Failed to set subgraph operand value";
*errorStatus = otherErrorStatus;
return nullptr;
}
break;
}
case OperandLifeTime::NO_VALUE: {
resultModel.setOperandValue(i, nullptr, 0);
break;
}
case OperandLifeTime::TEMPORARY_VARIABLE:
case OperandLifeTime::SUBGRAPH_OUTPUT:
case OperandLifeTime::SUBGRAPH_INPUT: {
break;
}
default:
LOG(ERROR) << "Invalid operand type: " << static_cast<int>(operand.lifetime);
*errorStatus = ErrorStatus::INVALID_ARGUMENT;
return nullptr;
}
if (!resultModel.isValid()) {
LOG(ERROR) << "Failed to add operand with index " << i;
*errorStatus = ErrorStatus::INVALID_ARGUMENT;
return nullptr;
}
}
for (int i = 0; i < subgraph.operations.size(); ++i) {
const auto& operation = subgraph.operations[i];
std::vector<uint32_t> inputs(operation.inputs.begin(), operation.inputs.end());
std::vector<uint32_t> outputs(operation.outputs.begin(), operation.outputs.end());
int operationType = static_cast<int>(operation.type);
if (::android::nn::isExtension(static_cast<::android::nn::OperationType>(operationType))) {
uint16_t extensionPrefix =
::android::nn::getExtensionPrefix(static_cast<uint32_t>(operationType));
uint16_t typeWithinExtension =
::android::nn::getTypeWithinExtension(static_cast<uint32_t>(operationType));
auto* extensionName = getExtensionName(extensionPrefix);
if (extensionName == nullptr) {
LOG(ERROR) << "Unknown extension prefix " << extensionPrefix;
*errorStatus = ErrorStatus::INVALID_ARGUMENT;
return nullptr;
}
resultModel.getExtensionOperationType(*extensionName, typeWithinExtension,
&operationType);
if (!resultModel.isValid()) {
LOG(ERROR) << "Failed to get extension operation with index " << i;
*errorStatus = ErrorStatus::INVALID_ARGUMENT;
return nullptr;
}
}
resultModel.addOperation(operationType, inputs, outputs);
if (!resultModel.isValid()) {
LOG(ERROR) << "Failed to add operation with index " << i;
*errorStatus = ErrorStatus::INVALID_ARGUMENT;
return nullptr;
}
}
std::vector<uint32_t> inputIndexes(subgraph.inputIndexes.begin(), subgraph.inputIndexes.end());
std::vector<uint32_t> outputIndexes(subgraph.outputIndexes.begin(),
subgraph.outputIndexes.end());
resultModel.identifyInputsAndOutputs(inputIndexes, outputIndexes);
if (!resultModel.isValid()) {
LOG(ERROR) << "Model identifyInputsAndOutputs failed";
*errorStatus = ErrorStatus::INVALID_ARGUMENT;
return nullptr;
}
if (resultModel.finish() != Result::NO_ERROR) {
LOG(ERROR) << "Model finish failed";
*errorStatus = ErrorStatus::INVALID_ARGUMENT;
return nullptr;
}
if (!resultModel.isValid()) {
LOG(ERROR) << "Invalid model";
*errorStatus = ErrorStatus::INVALID_ARGUMENT;
return nullptr;
}
(*allModels)[subgraphIndex] = std::move(resultModel);
return (*allModels)[subgraphIndex]->getHandle();
}

static ssize_t
get_uncompressed_data(struct archive_read *a, const void **buff, size_t size,
size_t minimum)
{
struct _7zip *zip = (struct _7zip *)a->format->data;
ssize_t bytes_avail;
if (zip->codec == _7Z_COPY && zip->codec2 == (unsigned long)-1) {
*buff = __archive_read_ahead(a, 1, &bytes_avail);
if (bytes_avail <= 0) {
archive_set_error(&a->archive,
ARCHIVE_ERRNO_FILE_FORMAT,
"Truncated 7-Zip file data");
return (ARCHIVE_FATAL);
}
if ((size_t)bytes_avail >
zip->uncompressed_buffer_bytes_remaining)
bytes_avail = (ssize_t)
zip->uncompressed_buffer_bytes_remaining;
if ((size_t)bytes_avail > size)
bytes_avail = (ssize_t)size;
zip->pack_stream_bytes_unconsumed = bytes_avail;
} else if (zip->uncompressed_buffer_pointer == NULL) {
archive_set_error(&(a->archive),
ARCHIVE_ERRNO_MISC, "Damaged 7-Zip archive");
return (ARCHIVE_FATAL);
} else {
if (minimum > zip->uncompressed_buffer_bytes_remaining) {
if (extract_pack_stream(a, minimum) < 0)
return (ARCHIVE_FATAL);
}
if (size > zip->uncompressed_buffer_bytes_remaining)
bytes_avail = (ssize_t)
zip->uncompressed_buffer_bytes_remaining;
else
bytes_avail = (ssize_t)size;
*buff = zip->uncompressed_buffer_pointer;
zip->uncompressed_buffer_pointer += bytes_avail;
}
zip->uncompressed_buffer_bytes_remaining -= bytes_avail;
return (bytes_avail);
}

void Archive::ProcessExtra50(RawRead *Raw,size_t ExtraSize,BaseBlock *bb)
{
size_t ExtraStart=Raw->Size()-ExtraSize;
if (ExtraStart<Raw->GetPos())
return;
Raw->SetPos(ExtraStart);
while (Raw->DataLeft()>=2)
{
int64 FieldSize=Raw->GetV();     if (FieldSize<=0 || Raw->DataLeft()==0 || FieldSize>(int64)Raw->DataLeft())
break;
size_t NextPos=size_t(Raw->GetPos()+FieldSize);
uint64 FieldType=Raw->GetV();
FieldSize=int64(NextPos-Raw->GetPos()); 
if (FieldSize<0)       break;
if (bb->HeaderType==HEAD_MAIN)
{
MainHeader *hd=(MainHeader *)bb;
if (FieldType==MHEXTRA_LOCATOR)
{
hd->Locator=true;
uint Flags=(uint)Raw->GetV();
if ((Flags & MHEXTRA_LOCATOR_QLIST)!=0)
{
uint64 Offset=Raw->GetV();
if (Offset!=0)             hd->QOpenOffset=Offset+CurBlockPos;
}
if ((Flags & MHEXTRA_LOCATOR_RR)!=0)
{
uint64 Offset=Raw->GetV();
if (Offset!=0)             hd->RROffset=Offset+CurBlockPos;
}
}
}
if (bb->HeaderType==HEAD_FILE || bb->HeaderType==HEAD_SERVICE)
{
FileHeader *hd=(FileHeader *)bb;
switch(FieldType)
{
case FHEXTRA_CRYPT:
{
FileHeader *hd=(FileHeader *)bb;
uint EncVersion=(uint)Raw->GetV();
if (EncVersion > CRYPT_VERSION)
UnkEncVerMsg(hd->FileName);
else
{
uint Flags=(uint)Raw->GetV();
hd->UsePswCheck=(Flags & FHEXTRA_CRYPT_PSWCHECK)!=0;
hd->UseHashKey=(Flags & FHEXTRA_CRYPT_HASHMAC)!=0;
hd->Lg2Count=Raw->Get1();
if (hd->Lg2Count>CRYPT5_KDF_LG2_COUNT_MAX)
UnkEncVerMsg(hd->FileName);
Raw->GetB(hd->Salt,SIZE_SALT50);
Raw->GetB(hd->InitV,SIZE_INITV);
if (hd->UsePswCheck)
{
Raw->GetB(hd->PswCheck,SIZE_PSWCHECK);
byte csum[SIZE_PSWCHECK_CSUM];
Raw->GetB(csum,SIZE_PSWCHECK_CSUM);
sha256_context ctx;
sha256_init(&ctx);
sha256_process(&ctx, hd->PswCheck, SIZE_PSWCHECK);
byte Digest[SHA256_DIGEST_SIZE];
sha256_done(&ctx, Digest);
hd->UsePswCheck=memcmp(csum,Digest,SIZE_PSWCHECK_CSUM)==0;
if (bb->HeaderType==HEAD_SERVICE && memcmp(hd->PswCheck,"\0\0\0\0\0\0\0\0",SIZE_PSWCHECK)==0)
hd->UsePswCheck=0;
}
hd->SaltSet=true;
hd->CryptMethod=CRYPT_RAR50;
hd->Encrypted=true;
}
}
break;
case FHEXTRA_HASH:
{
FileHeader *hd=(FileHeader *)bb;
uint Type=(uint)Raw->GetV();
if (Type==FHEXTRA_HASH_BLAKE2)
{
hd->FileHash.Type=HASH_BLAKE2;
Raw->GetB(hd->FileHash.Digest,BLAKE2_DIGEST_SIZE);
}
}
break;
case FHEXTRA_HTIME:
if (FieldSize>=5)
{
byte Flags=(byte)Raw->GetV();
bool UnixTime=(Flags & FHEXTRA_HTIME_UNIXTIME)!=0;
if ((Flags & FHEXTRA_HTIME_MTIME)!=0)
if (UnixTime)
hd->mtime.SetUnix(Raw->Get4());
else
hd->mtime.SetWin(Raw->Get8());
if ((Flags & FHEXTRA_HTIME_CTIME)!=0)
if (UnixTime)
hd->ctime.SetUnix(Raw->Get4());
else
hd->ctime.SetWin(Raw->Get8());
if ((Flags & FHEXTRA_HTIME_ATIME)!=0)
if (UnixTime)
hd->atime.SetUnix((time_t)Raw->Get4());
else
hd->atime.SetWin(Raw->Get8());
if (UnixTime && (Flags & FHEXTRA_HTIME_UNIX_NS)!=0)             {
uint ns;
if ((Flags & FHEXTRA_HTIME_MTIME)!=0 && (ns=(Raw->Get4() & 0x3fffffff))<1000000000)
hd->mtime.Adjust(ns);
if ((Flags & FHEXTRA_HTIME_CTIME)!=0 && (ns=(Raw->Get4() & 0x3fffffff))<1000000000)
hd->ctime.Adjust(ns);
if ((Flags & FHEXTRA_HTIME_ATIME)!=0 && (ns=(Raw->Get4() & 0x3fffffff))<1000000000)
hd->atime.Adjust(ns);
}
}
break;
case FHEXTRA_VERSION:
if (FieldSize>=1)
{
Raw->GetV();             uint Version=(uint)Raw->GetV();
if (Version!=0)
{
hd->Version=true;
wchar VerText[20];
swprintf(VerText,ASIZE(VerText),L";%u",Version);
wcsncatz(FileHead.FileName,VerText,ASIZE(FileHead.FileName));
}
}
break;
case FHEXTRA_REDIR:
{
hd->RedirType=(FILE_SYSTEM_REDIRECT)Raw->GetV();
uint Flags=(uint)Raw->GetV();
hd->DirTarget=(Flags & FHEXTRA_REDIR_DIR)!=0;
size_t NameSize=(size_t)Raw->GetV();
char UtfName[NM*4];
*UtfName=0;
if (NameSize<ASIZE(UtfName)-1)
{
Raw->GetB(UtfName,NameSize);
UtfName[NameSize]=0;
}
#ifdef _WIN_ALL
UnixSlashToDos(UtfName,UtfName,ASIZE(UtfName));
#endif
UtfToWide(UtfName,hd->RedirName,ASIZE(hd->RedirName));
}
break;
case FHEXTRA_UOWNER:
{
uint Flags=(uint)Raw->GetV();
hd->UnixOwnerNumeric=(Flags & FHEXTRA_UOWNER_NUMUID)!=0;
hd->UnixGroupNumeric=(Flags & FHEXTRA_UOWNER_NUMGID)!=0;
*hd->UnixOwnerName=*hd->UnixGroupName=0;
if ((Flags & FHEXTRA_UOWNER_UNAME)!=0)
{
size_t Length=(size_t)Raw->GetV();
Length=Min(Length,ASIZE(hd->UnixOwnerName)-1);
Raw->GetB(hd->UnixOwnerName,Length);
hd->UnixOwnerName[Length]=0;
}
if ((Flags & FHEXTRA_UOWNER_GNAME)!=0)
{
size_t Length=(size_t)Raw->GetV();
Length=Min(Length,ASIZE(hd->UnixGroupName)-1);
Raw->GetB(hd->UnixGroupName,Length);
hd->UnixGroupName[Length]=0;
}
#ifdef _UNIX
if (hd->UnixOwnerNumeric)
hd->UnixOwnerID=(uid_t)Raw->GetV();
if (hd->UnixGroupNumeric)
hd->UnixGroupID=(gid_t)Raw->GetV();
#else
if (hd->UnixOwnerNumeric)
hd->UnixOwnerID=(uint)Raw->GetV();
if (hd->UnixGroupNumeric)
hd->UnixGroupID=(uint)Raw->GetV();
#endif
hd->UnixOwnerSet=true;
}
break;
case FHEXTRA_SUBDATA:
{
if (bb->HeaderType==HEAD_SERVICE && Raw->Size()-NextPos==1)
FieldSize++;
hd->SubData.Alloc((size_t)FieldSize);
Raw->GetB(hd->SubData.Addr(0),(size_t)FieldSize);
}
break;
}
}
Raw->SetPos(NextPos);
}
}

njs_token_t
njs_regexp_literal(njs_vm_t *vm, njs_parser_t *parser, njs_value_t *value)
{
u_char                *p;
njs_str_t             text;
njs_lexer_t           *lexer;
njs_regexp_flags_t    flags;
njs_regexp_pattern_t  *pattern;
lexer = parser->lexer;
for (p = lexer->start; p < lexer->end; p++) {
switch (*p) {
case '\n':
case '\r':
goto failed;
case '[':
while (++p < lexer->end && *p != ']') {
switch (*p) {
case '\n':
case '\r':
goto failed;
case '\\':
if (++p < lexer->end && (*p == '\n' || *p == '\r')) {
goto failed;
}
break;
}
}
break;
case '\\':
if (++p < lexer->end && (*p == '\n' || *p == '\r')) {
goto failed;
}
break;
case '/':
text.start = lexer->start;
text.length = p - text.start;
p++;
lexer->start = p;
flags = njs_regexp_flags(&p, lexer->end, 0);
if (njs_slow_path(flags < 0)) {
njs_parser_syntax_error(vm, parser,
"Invalid RegExp flags \"%*s\"",
p - lexer->start, lexer->start);
return NJS_TOKEN_ILLEGAL;
}
lexer->start = p;
pattern = njs_regexp_pattern_create(vm, text.start, text.length,
flags);
if (njs_slow_path(pattern == NULL)) {
return NJS_TOKEN_ILLEGAL;
}
value->data.u.data = pattern;
return NJS_TOKEN_REGEXP;
}
}
failed:
njs_parser_syntax_error(vm, parser, "Unterminated RegExp \"%*s\"",
p - (lexer->start - 1), lexer->start - 1);
return NJS_TOKEN_ILLEGAL;
}

int sock_setsockopt(struct socket *sock, int level, int optname,
char __user *optval, unsigned int optlen)
{
struct sock *sk = sock->sk;
int val;
int valbool;
struct linger ling;
int ret = 0;
if (optname == SO_BINDTODEVICE)
return sock_setbindtodevice(sk, optval, optlen);
if (optlen < sizeof(int))
return -EINVAL;
if (get_user(val, (int __user *)optval))
return -EFAULT;
valbool = val ? 1 : 0;
lock_sock(sk);
switch (optname) {
case SO_DEBUG:
if (val && !capable(CAP_NET_ADMIN))
ret = -EACCES;
else
sock_valbool_flag(sk, SOCK_DBG, valbool);
break;
case SO_REUSEADDR:
sk->sk_reuse = (valbool ? SK_CAN_REUSE : SK_NO_REUSE);
break;
case SO_REUSEPORT:
sk->sk_reuseport = valbool;
break;
case SO_TYPE:
case SO_PROTOCOL:
case SO_DOMAIN:
case SO_ERROR:
ret = -ENOPROTOOPT;
break;
case SO_DONTROUTE:
sock_valbool_flag(sk, SOCK_LOCALROUTE, valbool);
break;
case SO_BROADCAST:
sock_valbool_flag(sk, SOCK_BROADCAST, valbool);
break;
case SO_SNDBUF:
val = min_t(u32, val, sysctl_wmem_max);
set_sndbuf:
sk->sk_userlocks |= SOCK_SNDBUF_LOCK;
sk->sk_sndbuf = max_t(u32, val * 2, SOCK_MIN_SNDBUF);
sk->sk_write_space(sk);
break;
case SO_SNDBUFFORCE:
if (!capable(CAP_NET_ADMIN)) {
ret = -EPERM;
break;
}
goto set_sndbuf;
case SO_RCVBUF:
val = min_t(u32, val, sysctl_rmem_max);
set_rcvbuf:
sk->sk_userlocks |= SOCK_RCVBUF_LOCK;
sk->sk_rcvbuf = max_t(u32, val * 2, SOCK_MIN_RCVBUF);
break;
case SO_RCVBUFFORCE:
if (!capable(CAP_NET_ADMIN)) {
ret = -EPERM;
break;
}
goto set_rcvbuf;
case SO_KEEPALIVE:
#ifdef CONFIG_INET
if (sk->sk_protocol == IPPROTO_TCP &&
sk->sk_type == SOCK_STREAM)
tcp_set_keepalive(sk, valbool);
#endif
sock_valbool_flag(sk, SOCK_KEEPOPEN, valbool);
break;
case SO_OOBINLINE:
sock_valbool_flag(sk, SOCK_URGINLINE, valbool);
break;
case SO_NO_CHECK:
sk->sk_no_check_tx = valbool;
break;
case SO_PRIORITY:
if ((val >= 0 && val <= 6) ||
ns_capable(sock_net(sk)->user_ns, CAP_NET_ADMIN))
sk->sk_priority = val;
else
ret = -EPERM;
break;
case SO_LINGER:
if (optlen < sizeof(ling)) {
ret = -EINVAL;
break;
}
if (copy_from_user(&ling, optval, sizeof(ling))) {
ret = -EFAULT;
break;
}
if (!ling.l_onoff)
sock_reset_flag(sk, SOCK_LINGER);
else {
#if (BITS_PER_LONG == 32)
if ((unsigned int)ling.l_linger >= MAX_SCHEDULE_TIMEOUT/HZ)
sk->sk_lingertime = MAX_SCHEDULE_TIMEOUT;
else
#endif
sk->sk_lingertime = (unsigned int)ling.l_linger * HZ;
sock_set_flag(sk, SOCK_LINGER);
}
break;
case SO_BSDCOMPAT:
sock_warn_obsolete_bsdism("setsockopt");
break;
case SO_PASSCRED:
if (valbool)
set_bit(SOCK_PASSCRED, &sock->flags);
else
clear_bit(SOCK_PASSCRED, &sock->flags);
break;
case SO_TIMESTAMP:
case SO_TIMESTAMPNS:
if (valbool)  {
if (optname == SO_TIMESTAMP)
sock_reset_flag(sk, SOCK_RCVTSTAMPNS);
else
sock_set_flag(sk, SOCK_RCVTSTAMPNS);
sock_set_flag(sk, SOCK_RCVTSTAMP);
sock_enable_timestamp(sk, SOCK_TIMESTAMP);
} else {
sock_reset_flag(sk, SOCK_RCVTSTAMP);
sock_reset_flag(sk, SOCK_RCVTSTAMPNS);
}
break;
case SO_TIMESTAMPING:
if (val & ~SOF_TIMESTAMPING_MASK) {
ret = -EINVAL;
break;
}
if (val & SOF_TIMESTAMPING_OPT_ID &&
!(sk->sk_tsflags & SOF_TIMESTAMPING_OPT_ID)) {
if (sk->sk_protocol == IPPROTO_TCP &&
sk->sk_type == SOCK_STREAM) {
if ((1 << sk->sk_state) &
(TCPF_CLOSE | TCPF_LISTEN)) {
ret = -EINVAL;
break;
}
sk->sk_tskey = tcp_sk(sk)->snd_una;
} else {
sk->sk_tskey = 0;
}
}
sk->sk_tsflags = val;
if (val & SOF_TIMESTAMPING_RX_SOFTWARE)
sock_enable_timestamp(sk,
SOCK_TIMESTAMPING_RX_SOFTWARE);
else
sock_disable_timestamp(sk,
(1UL << SOCK_TIMESTAMPING_RX_SOFTWARE));
break;
case SO_RCVLOWAT:
if (val < 0)
val = INT_MAX;
sk->sk_rcvlowat = val ? : 1;
break;
case SO_RCVTIMEO:
ret = sock_set_timeout(&sk->sk_rcvtimeo, optval, optlen);
break;
case SO_SNDTIMEO:
ret = sock_set_timeout(&sk->sk_sndtimeo, optval, optlen);
break;
case SO_ATTACH_FILTER:
ret = -EINVAL;
if (optlen == sizeof(struct sock_fprog)) {
struct sock_fprog fprog;
ret = -EFAULT;
if (copy_from_user(&fprog, optval, sizeof(fprog)))
break;
ret = sk_attach_filter(&fprog, sk);
}
break;
case SO_ATTACH_BPF:
ret = -EINVAL;
if (optlen == sizeof(u32)) {
u32 ufd;
ret = -EFAULT;
if (copy_from_user(&ufd, optval, sizeof(ufd)))
break;
ret = sk_attach_bpf(ufd, sk);
}
break;
case SO_ATTACH_REUSEPORT_CBPF:
ret = -EINVAL;
if (optlen == sizeof(struct sock_fprog)) {
struct sock_fprog fprog;
ret = -EFAULT;
if (copy_from_user(&fprog, optval, sizeof(fprog)))
break;
ret = sk_reuseport_attach_filter(&fprog, sk);
}
break;
case SO_ATTACH_REUSEPORT_EBPF:
ret = -EINVAL;
if (optlen == sizeof(u32)) {
u32 ufd;
ret = -EFAULT;
if (copy_from_user(&ufd, optval, sizeof(ufd)))
break;
ret = sk_reuseport_attach_bpf(ufd, sk);
}
break;
case SO_DETACH_FILTER:
ret = sk_detach_filter(sk);
break;
case SO_LOCK_FILTER:
if (sock_flag(sk, SOCK_FILTER_LOCKED) && !valbool)
ret = -EPERM;
else
sock_valbool_flag(sk, SOCK_FILTER_LOCKED, valbool);
break;
case SO_PASSSEC:
if (valbool)
set_bit(SOCK_PASSSEC, &sock->flags);
else
clear_bit(SOCK_PASSSEC, &sock->flags);
break;
case SO_MARK:
if (!ns_capable(sock_net(sk)->user_ns, CAP_NET_ADMIN))
ret = -EPERM;
else
sk->sk_mark = val;
break;
case SO_RXQ_OVFL:
sock_valbool_flag(sk, SOCK_RXQ_OVFL, valbool);
break;
case SO_WIFI_STATUS:
sock_valbool_flag(sk, SOCK_WIFI_STATUS, valbool);
break;
case SO_PEEK_OFF:
if (sock->ops->set_peek_off)
ret = sock->ops->set_peek_off(sk, val);
else
ret = -EOPNOTSUPP;
break;
case SO_NOFCS:
sock_valbool_flag(sk, SOCK_NOFCS, valbool);
break;
case SO_SELECT_ERR_QUEUE:
sock_valbool_flag(sk, SOCK_SELECT_ERR_QUEUE, valbool);
break;
#ifdef CONFIG_NET_RX_BUSY_POLL
case SO_BUSY_POLL:
if ((val > sk->sk_ll_usec) && !capable(CAP_NET_ADMIN))
ret = -EPERM;
else {
if (val < 0)
ret = -EINVAL;
else
sk->sk_ll_usec = val;
}
break;
#endif
case SO_MAX_PACING_RATE:
sk->sk_max_pacing_rate = val;
sk->sk_pacing_rate = min(sk->sk_pacing_rate,
sk->sk_max_pacing_rate);
break;
case SO_INCOMING_CPU:
sk->sk_incoming_cpu = val;
break;
case SO_CNX_ADVICE:
if (val == 1)
dst_negative_advice(sk);
break;
default:
ret = -ENOPROTOOPT;
break;
}
release_sock(sk);
return ret;
}

static guint32 OALMarshal_UncompressValue(guint8 maxSize, guint32 *bufLength, const guint8 *buffer)
{
guint32 value = 0;
guint8 used = 0;
guint8 size = maxSize;
guint8 mask;
switch (buffer[0] >> 6)
{
case 0x02:
if (maxSize > 2)
mask = 0x3F;
else
mask = 0x7F;
size = 2;
break;
case 0x03:
if (maxSize > 2)
mask = 0x3F;
else
mask = 0x7F;
break;
default:
size = 1;
mask = 0x7F;
break;
}
value = buffer[used++] & mask;
while (used < size)
value = (value << 8) | buffer[used++];
*bufLength = used;
return (value);
}

void
cifs_put_tcp_session(struct TCP_Server_Info *server, int from_reconnect)
{
struct task_struct *task;
spin_lock(&cifs_tcp_ses_lock);
if (--server->srv_count > 0) {
spin_unlock(&cifs_tcp_ses_lock);
return;
}
WARN_ON(server->srv_count < 0);
put_net(cifs_net_ns(server));
list_del_init(&server->tcp_ses_list);
spin_unlock(&cifs_tcp_ses_lock);
if (CIFS_SERVER_IS_CHAN(server))
cifs_put_tcp_session(server->primary_server, from_reconnect);
cancel_delayed_work_sync(&server->echo);
cancel_delayed_work_sync(&server->resolve);
if (from_reconnect)
cancel_delayed_work(&server->reconnect);
else
cancel_delayed_work_sync(&server->reconnect);
spin_lock(&server->srv_lock);
server->tcpStatus = CifsExiting;
spin_unlock(&server->srv_lock);
cifs_crypto_secmech_release(server);
kfree_sensitive(server->session_key.response);
server->session_key.response = NULL;
server->session_key.len = 0;
kfree(server->hostname);
task = xchg(&server->tsk, NULL);
if (task)
send_sig(SIGKILL, task, 1);
}

int nft_expr_inner_parse(const struct nft_ctx *ctx, const struct nlattr *nla,
struct nft_expr_info *info)
{
struct nlattr *tb[NFTA_EXPR_MAX + 1];
const struct nft_expr_type *type;
int err;
err = nla_parse_nested_deprecated(tb, NFTA_EXPR_MAX, nla,
nft_expr_policy, NULL);
if (err < 0)
return err;
if (!tb[NFTA_EXPR_DATA])
return -EINVAL;
type = __nft_expr_type_get(ctx->family, tb[NFTA_EXPR_NAME]);
if (!type)
return -ENOENT;
if (!type->inner_ops)
return -EOPNOTSUPP;
err = nla_parse_nested_deprecated(info->tb, type->maxattr,
tb[NFTA_EXPR_DATA],
type->policy, NULL);
if (err < 0)
goto err_nla_parse;
info->attr = nla;
info->ops = type->inner_ops;
return 0;
err_nla_parse:
return err;
}

STATIC regnode *
S_handle_regex_sets(pTHX_ RExC_state_t *pRExC_state, SV** return_invlist,
I32 *flagp, U32 depth,
char * const oregcomp_parse)
{
U8 curchar;                     
UV start, end;            
SV* final = NULL;               
SV* result_string;              
AV* stack;                      
AV* fence_stack = NULL;         
volatile IV fence = 0;          
STRLEN len;                     
regnode* node;                  
const bool save_fold = FOLD;    
char *save_end, *save_parse;    
const bool in_locale = LOC;     
AV* posix_warnings = NULL;
GET_RE_DEBUG_FLAGS_DECL;
PERL_ARGS_ASSERT_HANDLE_REGEX_SETS;
DEBUG_PARSE("xcls");
if (in_locale) {
set_regex_charset(&RExC_flags, REGEX_UNICODE_CHARSET);
}
REQUIRE_UNI_RULES(flagp, NULL);   
if (SIZE_ONLY) {
UV nest_depth = 0; 
while (RExC_parse < RExC_end) {
SV* current = NULL;
skip_to_be_ignored_text(pRExC_state, &RExC_parse,
TRUE  );
switch (*RExC_parse) {
case '?':
if (RExC_parse[1] == '[') nest_depth++, RExC_parse++;
default:
break;
case '\\':
RExC_parse++;
if (*RExC_parse == 'c') {
RExC_parse += UTF ? UTF8SKIP(RExC_parse) : 1;
}
break;
case '[':
{
bool is_posix_class = (OOB_NAMEDCLASS
< handle_possible_posix(pRExC_state,
RExC_parse + 1,
NULL,
NULL,
TRUE ));
if (! is_posix_class) {
RExC_parse++;
}
if (!regclass(pRExC_state, flagp,depth+1,
is_posix_class, 
FALSE, 
TRUE, 
TRUE, 
FALSE, 
&current,
&posix_warnings
))
FAIL2("panic: regclass returned NULL to handle_sets, "
"flags=%#" UVxf, (UV) *flagp);
if (is_posix_class) {
RExC_parse--;
}
SvREFCNT_dec(current);   
break;
}
case ']':
if (nest_depth--) break;
RExC_parse++;
if (*RExC_parse == ')') {
node = reganode(pRExC_state, ANYOF, 0);
RExC_size += ANYOF_SKIP;
nextchar(pRExC_state);
Set_Node_Length(node,
RExC_parse - oregcomp_parse + 1); 
if (in_locale) {
set_regex_charset(&RExC_flags, REGEX_LOCALE_CHARSET);
}
return node;
}
goto no_close;
}
RExC_parse += UTF ? UTF8SKIP(RExC_parse) : 1;
}
no_close:
if (posix_warnings && av_tindex_skip_len_mg(posix_warnings) >= 0) {
output_or_return_posix_warnings(pRExC_state, posix_warnings, NULL);
}
FAIL("Syntax error in (?[...])");
}
Perl_ck_warner_d(aTHX_
packWARN(WARN_EXPERIMENTAL__REGEX_SETS),
"The regex_sets feature is experimental" REPORT_LOCATION,
REPORT_LOCATION_ARGS(RExC_parse));
#define IS_OPERATOR(a) SvIOK(a)
#define IS_OPERAND(a)  (! IS_OPERATOR(a))
sv_2mortal((SV *)(stack = newAV()));
sv_2mortal((SV *)(fence_stack = newAV()));
while (RExC_parse < RExC_end) {
I32 top_index;              
SV** top_ptr;               
SV* current = NULL;         
SV* only_to_avoid_leaks;
skip_to_be_ignored_text(pRExC_state, &RExC_parse,
TRUE  );
if (RExC_parse >= RExC_end) {
Perl_croak(aTHX_ "panic: Read past end of '(?[ ])'");
}
curchar = UCHARAT(RExC_parse);
redo_curchar:
#ifdef ENABLE_REGEX_SETS_DEBUGGING
DEBUG_U(dump_regex_sets_structures(pRExC_state,
stack, fence, fence_stack));
#endif
top_index = av_tindex_skip_len_mg(stack);
switch (curchar) {
SV** stacked_ptr;       
char stacked_operator;  
SV* lhs;                
SV* rhs;                
SV* fence_ptr;          
case '(':
if (   RExC_parse < RExC_end - 1
&& (UCHARAT(RExC_parse + 1) == '?'))
{
U32 save_flags = RExC_flags;
const char * save_parse;
RExC_parse += 2;        
save_parse = RExC_parse;
parse_lparen_question_flags(pRExC_state);
if (RExC_parse == save_parse  
|| RExC_parse >= RExC_end - 4
|| UCHARAT(RExC_parse) != ':'
|| UCHARAT(++RExC_parse) != '('
|| UCHARAT(++RExC_parse) != '?'
|| UCHARAT(++RExC_parse) != '[')
{
if (RExC_parse >= RExC_end - 4) {
RExC_parse = RExC_end;
}
else if (RExC_parse != save_parse) {
RExC_parse += (UTF) ? UTF8SKIP(RExC_parse) : 1;
}
vFAIL("Expecting '(?flags:(?[...'");
}
RExC_parse++;
(void) handle_regex_sets(pRExC_state, &current, flagp,
depth+1, oregcomp_parse);
RExC_parse++;
assert(UCHARAT(RExC_parse) == ')');
RExC_parse++;
assert(UCHARAT(RExC_parse) == ')');
RExC_parse++;
RExC_flags = save_flags;
goto handle_operand;
}
if (top_index - fence >= 0) {
if (   ! (top_ptr = av_fetch(stack, top_index, FALSE))
|| (IS_OPERATOR(*top_ptr) && SvUV(*top_ptr) != '!')
|| (   IS_OPERAND(*top_ptr)
&& (   top_index - fence < 1
|| ! (stacked_ptr = av_fetch(stack,
top_index - 1,
FALSE))
|| ! IS_OPERATOR(*stacked_ptr))))
{
RExC_parse++;
vFAIL("Unexpected '(' with no preceding operator");
}
}
av_push(fence_stack, newSViv(fence));
fence = top_index + 1;
break;
case '\\':
if (!regclass(pRExC_state, flagp,depth+1,
TRUE, 
FALSE, 
FALSE, 
TRUE,  
FALSE, 
&current,
NULL))
{
FAIL2("panic: regclass returned NULL to handle_sets, "
"flags=%#" UVxf, (UV) *flagp);
}
RExC_parse--;
goto handle_operand;
case '[':   
{
bool is_posix_class = (OOB_NAMEDCLASS
< handle_possible_posix(pRExC_state,
RExC_parse + 1,
NULL,
NULL,
TRUE ));
if (! is_posix_class) {
RExC_parse++;
}
if (!regclass(pRExC_state, flagp,depth+1,
is_posix_class, 
FALSE, 
TRUE, 
TRUE, 
FALSE, 
&current,
NULL
))
{
FAIL2("panic: regclass returned NULL to handle_sets, "
"flags=%#" UVxf, (UV) *flagp);
}
if (is_posix_class) {
RExC_parse--;
}
goto handle_operand;
}
case ']':
if (top_index >= 1) {
goto join_operators;
}
goto done;
case ')':
if (av_tindex_skip_len_mg(fence_stack) < 0) {
RExC_parse++;
vFAIL("Unexpected ')'");
}
if (top_index - fence < 0) {
RExC_parse++;
goto bad_syntax;
}
if (top_index - fence >= 1) {
goto join_operators;
}
fence_ptr = av_pop(fence_stack);
assert(fence_ptr);
fence = SvIV(fence_ptr) - 1;
SvREFCNT_dec_NN(fence_ptr);
fence_ptr = NULL;
if (fence < 0) {
fence = 0;
}
current = av_pop(stack);
if (IS_OPERAND(current)) {
goto handle_operand;
}
RExC_parse++;
goto bad_syntax;
case '&':
case '|':
case '+':
case '-':
case '^':
if (   top_index - fence < 0
|| top_index - fence == 1
|| ( ! (top_ptr = av_fetch(stack, top_index, FALSE)))
|| ! IS_OPERAND(*top_ptr))
{
goto unexpected_binary;
}
if (top_index - fence < 2) {
SV* lhs = av_pop(stack);
av_push(stack, newSVuv(curchar));
av_push(stack, lhs);
break;
}
join_operators:
if (   ! (stacked_ptr = av_fetch(stack, top_index - 2, FALSE))
|| IS_OPERAND(*stacked_ptr))
{
if (curchar == ']') {
goto done;
}
unexpected_binary:
RExC_parse++;
vFAIL2("Unexpected binary operator '%c' with no "
"preceding operand", curchar);
}
stacked_operator = (char) SvUV(*stacked_ptr);
if (regex_set_precedence(curchar)
> regex_set_precedence(stacked_operator))
{
lhs = av_pop(stack);
assert(IS_OPERAND(lhs));
av_push(stack, newSVuv(curchar));
av_push(stack, lhs);
break;
}
rhs = av_pop(stack);
if (! IS_OPERAND(rhs)) {
goto bad_syntax;
}
lhs = av_pop(stack);
if (! IS_OPERAND(lhs)) {
goto bad_syntax;
}
switch (stacked_operator) {
case '&':
_invlist_intersection(lhs, rhs, &rhs);
break;
case '|':
case '+':
_invlist_union(lhs, rhs, &rhs);
break;
case '-':
_invlist_subtract(lhs, rhs, &rhs);
break;
case '^':   
{
SV* i = NULL;
SV* u = NULL;
_invlist_union(lhs, rhs, &u);
_invlist_intersection(lhs, rhs, &i);
_invlist_subtract(u, i, &rhs);
SvREFCNT_dec_NN(i);
SvREFCNT_dec_NN(u);
break;
}
}
SvREFCNT_dec(lhs);
only_to_avoid_leaks = av_pop(stack);
SvREFCNT_dec(only_to_avoid_leaks);
av_push(stack, rhs);
goto redo_curchar;
case '!':   
if (   (top_ptr = av_fetch(stack, top_index, FALSE))
&& (IS_OPERATOR(*top_ptr) && SvUV(*top_ptr) == '!'))
{
only_to_avoid_leaks = av_pop(stack);
SvREFCNT_dec(only_to_avoid_leaks);
}
else { 
av_push(stack, newSVuv(curchar));
}
break;
default:
RExC_parse += (UTF) ? UTF8SKIP(RExC_parse) : 1;
vFAIL("Unexpected character");
handle_operand:
top_index = av_tindex_skip_len_mg(stack);
if (top_index - fence >= 0) {
top_ptr = av_fetch(stack, top_index, FALSE);
assert(top_ptr);
if (IS_OPERATOR(*top_ptr)) {
curchar = (char) SvUV(*top_ptr);
if (curchar != '!') {
SvREFCNT_dec(current);
vFAIL2("Unexpected binary operator '%c' with no "
"preceding operand", curchar);
}
_invlist_invert(current);
only_to_avoid_leaks = av_pop(stack);
SvREFCNT_dec(only_to_avoid_leaks);
goto handle_operand;
}
else if ((top_index - fence == 0 && curchar != ')')
|| (top_index - fence > 0
&& (! (stacked_ptr = av_fetch(stack,
top_index - 1,
FALSE))
|| IS_OPERAND(*stacked_ptr))))
{
SvREFCNT_dec(current);
vFAIL("Operand with no preceding operator");
}
}
av_push(stack, current);
} 
RExC_parse += (UTF) ? UTF8SKIP(RExC_parse) : 1;
} 
done:
if (av_tindex_skip_len_mg(fence_stack) >= 0) {
vFAIL("Unmatched (");
}
if (av_tindex_skip_len_mg(stack) < 0   
|| ((final = av_pop(stack)) == NULL)
