bool CmkjPlayer::load(const std::string &filename, const CFileProvider &fp)
{
binistream *f = fp.open(filename); if(!f) return false;
charid[6];
floatver;
inti, j;
f->readString(id, 6);
if(strncmp(id,"MKJamz",6)) { fp.close(f); return false; }
ver = f->readFloat(binio::Single);
if(ver > 1.12) { fp.close(f); return false; }
maxchannel = f->readInt(2);
for(i = 0; i < maxchannel; i++) {
for (j = 0; j < 8; j++) {
inst[i].value[j] = f->readInt(2);
}
}
maxnotes = f->readInt(2);
songbuf = new short [(maxchannel+1)*maxnotes];
for(i = 0; i < maxchannel; i++) channel[i].defined = f->readInt(2);
for(i = 0; i < (maxchannel + 1) * maxnotes; i++)
songbuf[i] = f->readInt(2);
AdPlug_LogWrite("CmkjPlayer::load(\"%s\"): loaded file ver %.2f, %d channels,"
" %d notes/channel.\n", filename.c_str(), ver, maxchannel,
maxnotes);
fp.close(f);
rewind(0);
return true;
}

static void voutf(struct GlobalConfig *config,
const char *prefix,
const char *fmt,
va_list ap)
{
size_t width = (79 - strlen(prefix));
if(!config->mute) {
size_t len;
char *ptr;
char *print_buffer;
print_buffer = curlx_mvaprintf(fmt, ap);
if(!print_buffer)
return;
len = strlen(print_buffer);
ptr = print_buffer;
while(len > 0) {
fputs(prefix, config->errors);
if(len > width) {
size_t cut = width-1;
while(!ISSPACE(ptr[cut]) && cut) {
cut--;
}
if(0 == cut)
cut = width-1;
(void)fwrite(ptr, cut + 1, 1, config->errors);
fputs("\n", config->errors);
ptr += cut + 1; 
len -= cut;
}
else {
fputs(ptr, config->errors);
len = 0;
}
}
curl_free(print_buffer);
}
}

int ParseDsfHeaderConfig (FILE *infile, char *infilename, char *fourcc, WavpackContext *wpc, WavpackConfig *config)
{
int64_t infilesize, total_samples, total_blocks, leftover_samples;
DSFFileChunk file_chunk;
DSFFormatChunk format_chunk;
DSFChunkHeader chunk_header;
uint32_t bcount;
infilesize = DoGetFileSize (infile);
memcpy (&file_chunk, fourcc, 4);
if ((!DoReadFile (infile, ((char *) &file_chunk) + 4, sizeof (DSFFileChunk) - 4, &bcount) ||
bcount != sizeof (DSFFileChunk) - 4)) {
error_line ("%s is not a valid .DSF file!", infilename);
return WAVPACK_SOFT_ERROR;
}
else if (!(config->qmode & QMODE_NO_STORE_WRAPPER) &&
!WavpackAddWrapper (wpc, &file_chunk, sizeof (DSFFileChunk))) {
error_line ("%s", WavpackGetErrorMessage (wpc));
return WAVPACK_SOFT_ERROR;
}
#if 1       WavpackLittleEndianToNative (&file_chunk, DSFFileChunkFormat);
if (debug_logging_mode)
error_line ("file header lengths = %lld, %lld, %lld", file_chunk.ckSize, file_chunk.fileSize, file_chunk.metaOffset);
if (infilesize && !(config->qmode & QMODE_IGNORE_LENGTH) &&
file_chunk.fileSize && file_chunk.fileSize + 1 && file_chunk.fileSize != infilesize) {
error_line ("%s is not a valid .DSF file (by total size)!", infilename);
return WAVPACK_SOFT_ERROR;
}
#endif
if (config->channel_mask || (config->qmode & QMODE_CHANS_UNASSIGNED)) {
error_line ("this DSF file already has channel order information!");
return WAVPACK_SOFT_ERROR;
}
if (!DoReadFile (infile, ((char *) &format_chunk), sizeof (DSFFormatChunk), &bcount) ||
bcount != sizeof (DSFFormatChunk) || strncmp (format_chunk.ckID, "fmt ", 4)) {
error_line ("%s is not a valid .DSF file!", infilename);
return WAVPACK_SOFT_ERROR;
}
else if (!(config->qmode & QMODE_NO_STORE_WRAPPER) &&
!WavpackAddWrapper (wpc, &format_chunk, sizeof (DSFFormatChunk))) {
error_line ("%s", WavpackGetErrorMessage (wpc));
return WAVPACK_SOFT_ERROR;
}
WavpackLittleEndianToNative (&format_chunk, DSFFormatChunkFormat);
if (format_chunk.ckSize != sizeof (DSFFormatChunk) || format_chunk.formatVersion != 1 ||
format_chunk.formatID != 0 || format_chunk.blockSize != DSF_BLOCKSIZE || format_chunk.reserved ||
(format_chunk.bitsPerSample != 1 && format_chunk.bitsPerSample != 8) ||
format_chunk.numChannels < 1 || format_chunk.numChannels > 6 ||
format_chunk.chanType < 1 || format_chunk.chanType > NUM_CHAN_TYPES) {
error_line ("%s is not a valid .DSF file!", infilename);
return WAVPACK_SOFT_ERROR;
}
if (debug_logging_mode) {
error_line ("sampling rate = %d Hz", format_chunk.sampleRate);
error_line ("channel type = %d, channel count = %d", format_chunk.chanType, format_chunk.numChannels);
error_line ("block size = %d, bits per sample = %d", format_chunk.blockSize, format_chunk.bitsPerSample);
error_line ("sample count = %lld", format_chunk.sampleCount);
}
if (!DoReadFile (infile, ((char *) &chunk_header), sizeof (DSFChunkHeader), &bcount) ||
bcount != sizeof (DSFChunkHeader) || strncmp (chunk_header.ckID, "data", 4)) {
error_line ("%s is not a valid .DSF file!", infilename);
return WAVPACK_SOFT_ERROR;
}
else if (!(config->qmode & QMODE_NO_STORE_WRAPPER) &&
!WavpackAddWrapper (wpc, &chunk_header, sizeof (DSFChunkHeader))) {
error_line ("%s", WavpackGetErrorMessage (wpc));
return WAVPACK_SOFT_ERROR;
}
WavpackLittleEndianToNative (&chunk_header, DSFChunkHeaderFormat);
total_samples = format_chunk.sampleCount;
total_blocks = total_samples / (format_chunk.blockSize * 8);
leftover_samples = total_samples - (total_blocks * format_chunk.blockSize * 8);
if (leftover_samples)
total_blocks++;
if (debug_logging_mode) {
error_line ("leftover samples = %lld, leftover bits = %d", leftover_samples, (int)(leftover_samples % 8));
error_line ("data chunk size (specified) = %lld", chunk_header.ckSize - 12);
error_line ("data chunk size (calculated) = %lld", total_blocks * DSF_BLOCKSIZE * format_chunk.numChannels);
}
if (total_samples & 0x7)
error_line ("warning: DSF file has partial-byte leftover samples!");
if (format_chunk.sampleRate & 0x7)
error_line ("warning: DSF file has non-integer bytes/second!");
config->bits_per_sample = 8;
config->bytes_per_sample = 1;
config->num_channels = format_chunk.numChannels;
config->channel_mask = channel_masks [format_chunk.chanType - 1];
config->sample_rate = format_chunk.sampleRate / 8;
if (format_chunk.bitsPerSample == 1)
config->qmode |= QMODE_DSD_LSB_FIRST | QMODE_DSD_IN_BLOCKS;
else
config->qmode |= QMODE_DSD_MSB_FIRST | QMODE_DSD_IN_BLOCKS;
if (!WavpackSetConfiguration64 (wpc, config, (total_samples + 7) / 8, NULL)) {
error_line ("%s: %s", infilename, WavpackGetErrorMessage (wpc));
return WAVPACK_SOFT_ERROR;
}
return WAVPACK_NO_ERROR;
}

guint32
s7comm_decode_ud_cpu_szl_subfunc(tvbuff_t *tvb,
packet_info *pinfo,
proto_tree *data_tree,
guint8 type,                
guint8 ret_val,             
guint16 len,                
guint16 dlength,            
guint8 data_unit_ref,       
guint8 last_data_unit,      
guint32 offset)             
{
guint16 id;
guint16 idx;
guint16 list_len;
guint16 list_count;
guint16 i;
guint16 tbytes = 0;
proto_item *szl_item = NULL;
proto_tree *szl_item_tree = NULL;
proto_item *szl_item_entry = NULL;
const gchar* szl_index_description;
gboolean know_data = FALSE;
gboolean szl_decoded = FALSE;
if (type == S7COMM_UD_TYPE_REQ) {                   
id = tvb_get_ntohs(tvb, offset);
proto_tree_add_bitmask(data_tree, tvb, offset, hf_s7comm_userdata_szl_id,
ett_s7comm_userdata_szl_id, s7comm_userdata_szl_id_fields, ENC_BIG_ENDIAN);
offset += 2;
idx = tvb_get_ntohs(tvb, offset);
szl_item_entry = proto_tree_add_item(data_tree, hf_s7comm_userdata_szl_index, tvb, offset, 2, ENC_BIG_ENDIAN);
offset += 2;
szl_index_description = s7comm_get_szl_id_index_description_text(id, idx);
if (szl_index_description != NULL) {
proto_item_append_text(szl_item_entry, " [%s]", szl_index_description);
}
proto_item_append_text(data_tree, " (SZL-ID: 0x%04x, Index: 0x%04x)", id, idx);
col_append_fstr(pinfo->cinfo, COL_INFO, " ID=0x%04x Index=0x%04x" , id, idx);
know_data = TRUE;
} else if (type == S7COMM_UD_TYPE_RES) {            
if (ret_val == S7COMM_ITEM_RETVAL_DATA_OK) {
if (data_unit_ref != 0 && last_data_unit == 0) {
szl_item = proto_tree_add_item(data_tree, hf_s7comm_userdata_szl_tree, tvb, offset, len, ENC_NA);
szl_item_tree = proto_item_add_subtree(szl_item, ett_s7comm_szl);
proto_item_append_text(szl_item, " [Fragment, continuation of previous data]");
proto_tree_add_item(szl_item_tree, hf_s7comm_userdata_szl_data, tvb, offset, len, ENC_NA);
offset += len;
col_append_fstr(pinfo->cinfo, COL_INFO, " SZL data fragment");
} else {
id = tvb_get_ntohs(tvb, offset);
proto_tree_add_bitmask(data_tree, tvb, offset, hf_s7comm_userdata_szl_id,
ett_s7comm_userdata_szl_id, s7comm_userdata_szl_id_fields, ENC_BIG_ENDIAN);
offset += 2;
idx = tvb_get_ntohs(tvb, offset);
szl_item_entry = proto_tree_add_item(data_tree, hf_s7comm_userdata_szl_index, tvb, offset, 2, ENC_BIG_ENDIAN);
offset += 2;
szl_index_description = s7comm_get_szl_id_index_description_text(id, idx);
if (szl_index_description != NULL) {
proto_item_append_text(szl_item_entry, " [%s]", szl_index_description);
}
proto_item_append_text(data_tree, " (SZL-ID: 0x%04x, Index: 0x%04x)", id, idx);
col_append_fstr(pinfo->cinfo, COL_INFO, " ID=0x%04x Index=0x%04x" , id, idx);
list_len = tvb_get_ntohs(tvb, offset); 
proto_tree_add_uint(data_tree, hf_s7comm_userdata_szl_id_partlist_len, tvb, offset, 2, list_len);
offset += 2;
list_count = tvb_get_ntohs(tvb, offset); 
proto_tree_add_uint(data_tree, hf_s7comm_userdata_szl_id_partlist_cnt, tvb, offset, 2, list_count);
tbytes = 0;
if ((list_count * list_len) > (len - 8)) {
list_count = (len - 8) / list_len;
if (list_count > 0) {
tbytes = (len - 8) % list_count;
}
}
offset += 2;
if (len > 8) {      
for (i = 1; i <= list_count; i++) {
szl_item = proto_tree_add_item(data_tree, hf_s7comm_userdata_szl_tree, tvb, offset, list_len, ENC_NA);
szl_item_tree = proto_item_add_subtree(szl_item, ett_s7comm_szl);
proto_item_append_text(szl_item, " (list count no. %d)", i);
szl_decoded = FALSE;
switch (id) {
case 0x0000:
offset = s7comm_decode_szl_id_xy00(tvb, szl_item_tree, id, idx, offset);
szl_decoded = TRUE;
break;
case 0x0013:
if (idx == 0x0000) {
offset = s7comm_decode_szl_id_0013_idx_0000(tvb, szl_item_tree, offset);
szl_decoded = TRUE;
}
break;
case 0x0011:
case 0x0111:
if ((idx == 0x0001) || (idx == 0x0000)) {
offset = s7comm_decode_szl_id_0111_idx_0001(tvb, szl_item_tree, offset);
szl_decoded = TRUE;
}
break;
case 0x0131:
if (idx == 0x0001) {
offset = s7comm_decode_szl_id_0131_idx_0001(tvb, szl_item_tree, offset);
szl_decoded = TRUE;
} else if (idx == 0x0002) {
offset = s7comm_decode_szl_id_0131_idx_0002(tvb, szl_item_tree, offset);
szl_decoded = TRUE;
} else if (idx == 0x0003) {
offset = s7comm_decode_szl_id_0131_idx_0003(tvb, szl_item_tree, offset);
szl_decoded = TRUE;
} else if (idx == 0x0004) {
offset = s7comm_decode_szl_id_0131_idx_0004(tvb, szl_item_tree, offset);
szl_decoded = TRUE;
} else if (idx == 0x0006) {
offset = s7comm_decode_szl_id_0131_idx_0006(tvb, szl_item_tree, offset);
szl_decoded = TRUE;
} else if (idx == 0x0010) {
offset = s7comm_decode_szl_id_0131_idx_0010(tvb, szl_item_tree, offset);
szl_decoded = TRUE;
}
break;
case 0x0132:
if (idx == 0x0001) {
offset = s7comm_decode_szl_id_0132_idx_0001(tvb, szl_item_tree, offset);
szl_decoded = TRUE;
} else if (idx == 0x0002) {
offset = s7comm_decode_szl_id_0132_idx_0002(tvb, szl_item_tree, offset);
szl_decoded = TRUE;
} else if (idx == 0x0004) {
offset = s7comm_decode_szl_id_0132_idx_0004(tvb, szl_item_tree, offset);
szl_decoded = TRUE;
} else if (idx == 0x0005) {
offset = s7comm_decode_szl_id_0132_idx_0005(tvb, szl_item_tree, offset);
szl_decoded = TRUE;
} else if (idx == 0x0006) {
offset = s7comm_decode_szl_id_0132_idx_0006(tvb, szl_item_tree, offset);
szl_decoded = TRUE;
}
break;
case 0x0019:
case 0x0119:
case 0x0074:
case 0x0174:
offset = s7comm_decode_szl_id_xy74_idx_0000(tvb, szl_item_tree, offset);
szl_decoded = TRUE;
break;
case 0x0124:
case 0x0424:
if (idx == 0x0000) {
offset = s7comm_decode_szl_id_0424_idx_0000(tvb, szl_item_tree, offset);
szl_decoded = TRUE;
}
break;
default:
szl_decoded = FALSE;
break;
}
if (szl_decoded == FALSE) {
proto_tree_add_item(szl_item_tree, hf_s7comm_userdata_szl_partial_list, tvb, offset, list_len, ENC_NA);
offset += list_len;
}
} 
}
}
} else {
col_append_fstr(pinfo->cinfo, COL_INFO, " Return value:[%s]", val_to_str(ret_val, s7comm_item_return_valuenames, "Unknown return value:0x%02x"));
}
know_data = TRUE;
}
if (know_data == TRUE && tbytes > 0) {
szl_item = proto_tree_add_item(data_tree, hf_s7comm_userdata_szl_tree, tvb, offset, tbytes, ENC_NA);
szl_item_tree = proto_item_add_subtree(szl_item, ett_s7comm_szl);
proto_item_append_text(szl_item, " [Fragment, complete response doesn't fit one PDU]");
proto_tree_add_item(szl_item_tree, hf_s7comm_userdata_szl_data, tvb, offset, tbytes, ENC_NA);
offset += tbytes;
}
if (know_data == FALSE && dlength > 4) {
proto_tree_add_item(data_tree, hf_s7comm_userdata_szl_data, tvb, offset, dlength - 4, ENC_NA);
offset += dlength;
}
return offset;
}

