uint32_t n = (uint32_t)VALUE_AS_INT(GET_VALUE(1));
gravity_list_t *list = gravity_list_new(vm, n);
for (uint32_t i=0; i<n; ++i) marray_push(gravity_value_t, list->array, VALUE_FROM_NULL);
