&(hDecoder->__r1), &(hDecoder->__r2));
}
ms_decode(ics1, ics2, spec_coef1, spec_coef2, hDecoder->frameLength);
#if 0
{
int i;
for (i = 0; i < 1024; i++)
{
printf("0x%.8X\n", spec_coef1[i]);
}
for (i = 0; i < 1024; i++)
{
