struct iphdr* iph,
__u8 tos,
__u32 saddr,
__u32 daddr,
__u16 pkt_bytes,
__u8 proto) {
__u64 csum = 0;
iph->version = 4;
iph->ihl = 5;
iph->frag_off = 0;
iph->protocol = proto;
iph->check = 0;
#ifdef COPY_INNER_PACKET_TOS
iph->tos = tos;
#else
iph->tos = DEFAULT_TOS;
#endif
iph->tot_len = bpf_htons(pkt_bytes + sizeof(struct iphdr));
iph->daddr = daddr;
iph->saddr = saddr;
iph->ttl = DEFAULT_TTL;
ipv4_csum_inline(iph, &csum);
iph->check = csum;
}

