TEE_Result TEE_MACComputeFinal(TEE_OperationHandle operation,
const void *message, uint32_t messageLen,
void *mac, uint32_t *macLen)
{
TEE_Result res;
uint64_t ml;
if (operation == TEE_HANDLE_NULL ||
(message == NULL && messageLen != 0) ||
mac == NULL ||
macLen == NULL) {
res = TEE_ERROR_BAD_PARAMETERS;
goto out;
}
if (operation->info.operationClass != TEE_OPERATION_MAC) {
res = TEE_ERROR_BAD_PARAMETERS;
goto out;
}
if ((operation->info.handleState & TEE_HANDLE_FLAG_INITIALIZED) == 0) {
res = TEE_ERROR_BAD_PARAMETERS;
goto out;
}
if (operation->operationState != TEE_OPERATION_STATE_ACTIVE) {
res = TEE_ERROR_BAD_PARAMETERS;
goto out;
}
ml = *macLen;
res = utee_hash_final(operation->state, message, messageLen, mac, &ml);
*macLen = ml;
if (res != TEE_SUCCESS)
goto out;
operation->info.handleState &= ~TEE_HANDLE_FLAG_INITIALIZED;
operation->operationState = TEE_OPERATION_STATE_INITIAL;
out:
if (res != TEE_SUCCESS &&
res != TEE_ERROR_SHORT_BUFFER)
TEE_Panic(res);
return res;
}

int Adjust::adjustDateTime(Exiv2::ExifData& exifData,
const std::string& key,
const std::string& path) const
{
Exiv2::ExifKey ek(key);
Exiv2::ExifData::iterator md = exifData.findKey(ek);
if (md == exifData.end()) {
return 0;
}
std::string timeStr = md->toString();
if (timeStr == "" || timeStr[0] == ' ') {
std::cerr << path << ": " << _("Timestamp of metadatum with key") << " `"
<< ek << "' " << _("not set\n");
return 1;
}
if (Params::instance().verbose_) {
bool comma = false;
std::cout << _("Adjusting") << " `" << ek << "' " << _("by");
if (yearAdjustment_ != 0) {
std::cout << (yearAdjustment_ < 0 ? " " : " +") << yearAdjustment_ << " ";
if (yearAdjustment_ < -1 || yearAdjustment_ > 1) {
std::cout << _("years");
}
else {
std::cout << _("year");
}
comma = true;
}
if (monthAdjustment_ != 0) {
if (comma) std::cout << ",";
std::cout << (monthAdjustment_ < 0 ? " " : " +") << monthAdjustment_ << " ";
if (monthAdjustment_ < -1 || monthAdjustment_ > 1) {
std::cout << _("months");
}
else {
std::cout << _("month");
}
comma = true;
}
if (dayAdjustment_ != 0) {
if (comma) std::cout << ",";
std::cout << (dayAdjustment_ < 0 ? " " : " +") << dayAdjustment_ << " ";
if (dayAdjustment_ < -1 || dayAdjustment_ > 1) {
std::cout << _("days");
}
else {
std::cout << _("day");
}
comma = true;
}
if (adjustment_ != 0) {
if (comma) std::cout << ",";
std::cout << " " << adjustment_ << _("s");
}
}
struct tm tm;
if (str2Tm(timeStr, &tm) != 0) {
if (Params::instance().verbose_) std::cout << std::endl;
std::cerr << path << ": " << _("Failed to parse timestamp") << " `"
<< timeStr << "'\n";
return 1;
}
const long monOverflow = (tm.tm_mon + monthAdjustment_) / 12;
tm.tm_mon = (tm.tm_mon + monthAdjustment_) % 12;
tm.tm_year += yearAdjustment_ + monOverflow;
if (tm.tm_year > 9999 - 1900 || tm.tm_year < 1000 - 1900) {
if (Params::instance().verbose_) std::cout << std::endl;
std::cerr << path << ": " << _("Can't adjust timestamp by") << " "
<< yearAdjustment_ + monOverflow
<< " " << _("years") << "\n";
return 1;
}
time_t time = mktime(&tm);
time += adjustment_ + dayAdjustment_ * 86400;
timeStr = time2Str(time);
if (Params::instance().verbose_) {
std::cout << " " << _("to") << " " << timeStr << std::endl;
}
md->setValue(timeStr);
return 0;
}

static Image *ComputeResizeImage(const Image* image,MagickCLEnv clEnv,
const size_t resizedColumns,const size_t resizedRows,
const ResizeFilter *resizeFilter,ExceptionInfo *exception)
{
cl_command_queue
queue;
cl_mem
cubicCoefficientsBuffer,
filteredImageBuffer,
imageBuffer,
tempImageBuffer;
cl_uint
number_channels;
const double
*resizeFilterCoefficient;
float
coefficientBuffer[7],
xFactor,
yFactor;
MagickBooleanType
outputReady;
MagickCLDevice
device;
MagickSizeType
length;
Image
*filteredImage;
size_t
i;
filteredImage=NULL;
imageBuffer=NULL;
filteredImageBuffer=NULL;
tempImageBuffer=NULL;
cubicCoefficientsBuffer=NULL;
outputReady=MagickFalse;
device=RequestOpenCLDevice(clEnv);
queue=AcquireOpenCLCommandQueue(device);
filteredImage=CloneImage(image,resizedColumns,resizedRows,MagickTrue,
exception);
if (filteredImage == (Image *) NULL)
goto cleanup;
if (filteredImage->number_channels != image->number_channels)
goto cleanup;
imageBuffer=GetAuthenticOpenCLBuffer(image,device,exception);
if (imageBuffer == (cl_mem) NULL)
goto cleanup;
filteredImageBuffer=GetAuthenticOpenCLBuffer(filteredImage,device,exception);
if (filteredImageBuffer == (cl_mem) NULL)
goto cleanup;
resizeFilterCoefficient=GetResizeFilterCoefficient(resizeFilter);
for (i = 0; i < 7; i++)
coefficientBuffer[i]=(float) resizeFilterCoefficient[i];
cubicCoefficientsBuffer=CreateOpenCLBuffer(device,CL_MEM_COPY_HOST_PTR |
CL_MEM_READ_ONLY,7*sizeof(*cubicCoefficientsBuffer),&coefficientBuffer);
if (cubicCoefficientsBuffer == (cl_mem) NULL)
{
(void) OpenCLThrowMagickException(device,exception,GetMagickModule(),
ResourceLimitWarning,"CreateOpenCLBuffer failed.",".");
goto cleanup;
}
number_channels=(cl_uint) image->number_channels;
xFactor=(float) resizedColumns/(float) image->columns;
yFactor=(float) resizedRows/(float) image->rows;
if (xFactor > yFactor)
{
length=resizedColumns*image->rows*number_channels;
tempImageBuffer=CreateOpenCLBuffer(device,CL_MEM_READ_WRITE,length*
sizeof(CLQuantum),(void *) NULL);
if (tempImageBuffer == (cl_mem) NULL)
{
(void) OpenCLThrowMagickException(device,exception,GetMagickModule(),
ResourceLimitWarning,"CreateOpenCLBuffer failed.",".");
goto cleanup;
}
outputReady=resizeHorizontalFilter(device,queue,image,filteredImage,
imageBuffer,number_channels,(cl_uint) image->columns,
(cl_uint) image->rows,tempImageBuffer,(cl_uint) resizedColumns,
(cl_uint) image->rows,resizeFilter,cubicCoefficientsBuffer,xFactor,
exception);
if (outputReady == MagickFalse)
goto cleanup;
outputReady=resizeVerticalFilter(device,queue,image,filteredImage,
tempImageBuffer,number_channels,(cl_uint) resizedColumns,
(cl_uint) image->rows,filteredImageBuffer,(cl_uint) resizedColumns,
(cl_uint) resizedRows,resizeFilter,cubicCoefficientsBuffer,yFactor,
exception);
if (outputReady == MagickFalse)
goto cleanup;
}
else
{
length=image->columns*resizedRows*number_channels;
tempImageBuffer=CreateOpenCLBuffer(device,CL_MEM_READ_WRITE,length*
sizeof(CLQuantum),(void *) NULL);
if (tempImageBuffer == (cl_mem) NULL)
{
(void) OpenCLThrowMagickException(device,exception,GetMagickModule(),
ResourceLimitWarning,"CreateOpenCLBuffer failed.",".");
goto cleanup;
}
outputReady=resizeVerticalFilter(device,queue,image,filteredImage,
imageBuffer,number_channels,(cl_uint) image->columns,
(cl_int) image->rows,tempImageBuffer,(cl_uint) image->columns,
(cl_uint) resizedRows,resizeFilter,cubicCoefficientsBuffer,yFactor,
exception);
if (outputReady == MagickFalse)
goto cleanup;
outputReady=resizeHorizontalFilter(device,queue,image,filteredImage,
tempImageBuffer,number_channels,(cl_uint) image->columns,
(cl_uint) resizedRows,filteredImageBuffer,(cl_uint) resizedColumns,
(cl_uint) resizedRows,resizeFilter,cubicCoefficientsBuffer,xFactor,
exception);
if (outputReady == MagickFalse)
goto cleanup;
}
cleanup:
if (imageBuffer != (cl_mem) NULL)
ReleaseOpenCLMemObject(imageBuffer);
if (filteredImageBuffer != (cl_mem) NULL)
ReleaseOpenCLMemObject(filteredImageBuffer);
if (tempImageBuffer != (cl_mem) NULL)
ReleaseOpenCLMemObject(tempImageBuffer);
if (cubicCoefficientsBuffer != (cl_mem) NULL)
ReleaseOpenCLMemObject(cubicCoefficientsBuffer);
if (queue != (cl_command_queue) NULL)
ReleaseOpenCLCommandQueue(device,queue);
if (device != (MagickCLDevice) NULL)
ReleaseOpenCLDevice(device);
if ((outputReady == MagickFalse) && (filteredImage != (Image *) NULL))
filteredImage=DestroyImage(filteredImage);
return(filteredImage);
}

static int
sampled_data_continue(i_ctx_t *i_ctx_p)
{
os_ptr op = osp;
gs_sampled_data_enum *penum = senum;
gs_function_Sd_params_t * params =
(gs_function_Sd_params_t *)&penum->pfn->params;
int i, j, num_out = params->n;
int code = 0;
byte * data_ptr;
double sampled_data_value_max = (double)((1 << params->BitsPerSample) - 1);
int bps = bits2bytes(params->BitsPerSample), stack_depth_adjust = 0;
if (num_out + O_STACK_PAD + penum->o_stack_depth != ref_stack_count(&o_stack)) {
stack_depth_adjust = ref_stack_count(&o_stack) - penum->o_stack_depth;
if (stack_depth_adjust < 0) {
push(-stack_depth_adjust);
ifree_object(penum->pfn, "sampled_data_continue(pfn)");
ifree_object(penum, "sampled_data_continue((enum)");
return_error(gs_error_undefinedresult);
}
}
data_ptr = cube_ptr_from_index(params, penum->indexes);
for (i=0; i < num_out; i++) {
ulong cv;
double value;
double rmin = params->Range[2 * i];
double rmax = params->Range[2 * i + 1];
code = real_param(op + i - num_out + 1, &value);
if (code < 0) {
esp -= estack_storage;
return code;
}
if (value < rmin)
value = rmin;
else if (value > rmax)
value = rmax;
value = (value - rmin) / (rmax - rmin);
cv = (int) (value * sampled_data_value_max + 0.5);
for (j = 0; j < bps; j++)
data_ptr[bps * i + j] = (byte)(cv >> ((bps - 1 - j) * 8));
}
pop(num_out);    
if (increment_cube_indexes(params, penum->indexes)) {
if (stack_depth_adjust == 0)
pop(O_STACK_PAD);    
else
pop(stack_depth_adjust - num_out);
code = 0;
if (esp_finish_proc != 0)
code = esp_finish_proc(i_ctx_p);
return code;
} else {
if (stack_depth_adjust) {
stack_depth_adjust -= num_out;
if ((O_STACK_PAD - stack_depth_adjust) < 0) {
stack_depth_adjust = -(O_STACK_PAD - stack_depth_adjust);
check_op(stack_depth_adjust);
pop(stack_depth_adjust);
}
else {
check_ostack(O_STACK_PAD - stack_depth_adjust);
push(O_STACK_PAD - stack_depth_adjust);
for (i=0;i<O_STACK_PAD - stack_depth_adjust;i++)
make_null(op - i);
}
}
}
return sampled_data_sample(i_ctx_p);
}

static struct prog_entry *
predicate_parse(const char *str, int nr_parens, int nr_preds,
parse_pred_fn parse_pred, void *data,
struct filter_parse_error *pe)
{
struct prog_entry *prog_stack;
struct prog_entry *prog;
const char *ptr = str;
char *inverts = NULL;
int *op_stack;
int *top;
int invert = 0;
int ret = -ENOMEM;
int len;
int N = 0;
int i;
nr_preds += 2; 
op_stack = kmalloc_array(nr_parens, sizeof(*op_stack), GFP_KERNEL);
if (!op_stack)
return ERR_PTR(-ENOMEM);
prog_stack = kmalloc_array(nr_preds, sizeof(*prog_stack), GFP_KERNEL);
if (!prog_stack) {
parse_error(pe, -ENOMEM, 0);
goto out_free;
}
inverts = kmalloc_array(nr_preds, sizeof(*inverts), GFP_KERNEL);
if (!inverts) {
parse_error(pe, -ENOMEM, 0);
goto out_free;
}
top = op_stack;
prog = prog_stack;
*top = 0;
while (*ptr) {
const char *next = ptr++;
if (isspace(*next))
continue;
switch (*next) {
case '(':
if (top - op_stack > nr_parens)
return ERR_PTR(-EINVAL);
*(++top) = invert;
continue;
case '!':
if (!is_not(next))
break;
invert = !invert;
continue;
}
if (N >= nr_preds) {
parse_error(pe, FILT_ERR_TOO_MANY_PREDS, next - str);
goto out_free;
}
inverts[N] = invert;
prog[N].target = N-1;
len = parse_pred(next, data, ptr - str, pe, &prog[N].pred);
if (len < 0) {
ret = len;
goto out_free;
}
ptr = next + len;
N++;
ret = -1;
while (1) {
next = ptr++;
if (isspace(*next))
continue;
switch (*next) {
case ')':
case '\0':
break;
case '&':
case '|':
if (next[1] == next[0]) {
ptr++;
break;
}
default:
parse_error(pe, FILT_ERR_TOO_MANY_PREDS,
next - str);
goto out_free;
}
invert = *top & INVERT;
if (*top & PROCESS_AND) {
update_preds(prog, N - 1, invert);
*top &= ~PROCESS_AND;
}
if (*next == '&') {
*top |= PROCESS_AND;
break;
}
if (*top & PROCESS_OR) {
update_preds(prog, N - 1, !invert);
*top &= ~PROCESS_OR;
}
if (*next == '|') {
*top |= PROCESS_OR;
break;
}
if (!*next)
goto out;
if (top == op_stack) {
ret = -1;
parse_error(pe, FILT_ERR_TOO_MANY_CLOSE, ptr - str);
goto out_free;
}
top--;
}
}
out:
if (top != op_stack) {
parse_error(pe, FILT_ERR_TOO_MANY_OPEN, ptr - str);
goto out_free;
}
prog[N].pred = NULL;
prog[N].target = 1;
prog[N+1].pred = NULL;
prog[N+1].target = 0;
prog[N-1].target = N;
prog[N-1].when_to_branch = false;
for (i = N-1 ; i--; ) {
int target = prog[i].target;
if (prog[i].when_to_branch == prog[target].when_to_branch)
prog[i].target = prog[target].target;
}
for (i = 0; i < N; i++) {
invert = inverts[i] ^ prog[i].when_to_branch;
prog[i].when_to_branch = invert;
if (WARN_ON(prog[i].target <= i)) {
ret = -EINVAL;
goto out_free;
}
}
return prog;
out_free:
kfree(op_stack);
kfree(prog_stack);
kfree(inverts);
return ERR_PTR(ret);
}

static int exif_process_IFD_in_MAKERNOTE(image_info_type *ImageInfo, char * value_ptr, int value_len, char *offset_base, size_t IFDlength, size_t displacement TSRMLS_DC)
{
int de, i=0, section_index = SECTION_MAKERNOTE;
int NumDirEntries, old_motorola_intel, offset_diff;
const maker_note_type *maker_note;
char *dir_start;
for (i=0; i<=sizeof(maker_note_array)/sizeof(maker_note_type); i++) {
if (i==sizeof(maker_note_array)/sizeof(maker_note_type)) {
#ifdef EXIF_DEBUG
exif_error_docref(NULL EXIFERR_CC, ImageInfo, E_NOTICE, "No maker note data found. Detected maker: %s (length = %d)", ImageInfo->make, strlen(ImageInfo->make));
#endif
return TRUE;
}
maker_note = maker_note_array+i;
if (maker_note->make && (!ImageInfo->make || strcmp(maker_note->make, ImageInfo->make)))
continue;
if (maker_note->model && (!ImageInfo->model || strcmp(maker_note->model, ImageInfo->model)))
continue;
if (maker_note->id_string && strncmp(maker_note->id_string, value_ptr, maker_note->id_string_len))
continue;
break;
}
if (maker_note->offset >= value_len) {
exif_error_docref("exif_read_data#error_ifd" EXIFERR_CC, ImageInfo, E_WARNING, "IFD data too short: 0x%04X offset 0x%04X", value_len, maker_note->offset);
return FALSE;
}
dir_start = value_ptr + maker_note->offset;
#ifdef EXIF_DEBUG
exif_error_docref(NULL EXIFERR_CC, ImageInfo, E_NOTICE, "Process %s @x%04X + 0x%04X=%d: %s", exif_get_sectionname(section_index), (int)dir_start-(int)offset_base+maker_note->offset+displacement, value_len, value_len, exif_char_dump(value_ptr, value_len, (int)dir_start-(int)offset_base+maker_note->offset+displacement));
#endif
ImageInfo->sections_found |= FOUND_MAKERNOTE;
old_motorola_intel = ImageInfo->motorola_intel;
switch (maker_note->byte_order) {
case MN_ORDER_INTEL:
ImageInfo->motorola_intel = 0;
break;
case MN_ORDER_MOTOROLA:
ImageInfo->motorola_intel = 1;
break;
default:
case MN_ORDER_NORMAL:
break;
}
NumDirEntries = php_ifd_get16u(dir_start, ImageInfo->motorola_intel);
switch (maker_note->offset_mode) {
case MN_OFFSET_MAKER:
offset_base = value_ptr;
break;
case MN_OFFSET_GUESS:
if (maker_note->offset + 10 + 4 >= value_len) {
exif_error_docref("exif_read_data#error_ifd" EXIFERR_CC, ImageInfo, E_WARNING, "IFD data too short: 0x%04X", value_len);
return FALSE;
}
offset_diff = 2 + NumDirEntries*12 + 4 - php_ifd_get32u(dir_start+10, ImageInfo->motorola_intel);
#ifdef EXIF_DEBUG
exif_error_docref(NULL EXIFERR_CC, ImageInfo, E_NOTICE, "Using automatic offset correction: 0x%04X", ((int)dir_start-(int)offset_base+maker_note->offset+displacement) + offset_diff);
#endif
if (offset_diff < 0 || offset_diff >= value_len ) {
exif_error_docref("exif_read_data#error_ifd" EXIFERR_CC, ImageInfo, E_WARNING, "IFD data bad offset: 0x%04X length 0x%04X", offset_diff, value_len);
return FALSE;
}
offset_base = value_ptr + offset_diff;
break;
default:
case MN_OFFSET_NORMAL:
break;
}
if ((2+NumDirEntries*12) > value_len) {
exif_error_docref("exif_read_data#error_ifd" EXIFERR_CC, ImageInfo, E_WARNING, "Illegal IFD size: 2 + 0x%04X*12 = 0x%04X > 0x%04X", NumDirEntries, 2+NumDirEntries*12, value_len);
return FALSE;
}
for (de=0;de<NumDirEntries;de++) {
if (!exif_process_IFD_TAG(ImageInfo, dir_start + 2 + 12 * de,
offset_base, IFDlength, displacement, section_index, 0, maker_note->tag_table TSRMLS_CC)) {
return FALSE;
}
}
ImageInfo->motorola_intel = old_motorola_intel;
#ifdef EXIF_DEBUG
exif_error_docref(NULL EXIFERR_CC, ImageInfo, E_NOTICE, "Subsection %s done", exif_get_sectionname(SECTION_MAKERNOTE));
#endif
return TRUE;
}

int
read_fru_area_section(struct ipmi_intf * intf, struct fru_info *fru, uint8_t id,
uint32_t offset, uint32_t length, uint8_t *frubuf)
{
static uint32_t fru_data_rqst_size = 20;
uint32_t off = offset, tmp, finish;
struct ipmi_rs * rsp;
struct ipmi_rq req;
uint8_t msg_data[4];
if (offset > fru->size) {
lprintf(LOG_ERR, "Read FRU Area offset incorrect: %d > %d",
offset, fru->size);
return -1;
}
finish = offset + length;
if (finish > fru->size) {
finish = fru->size;
lprintf(LOG_NOTICE, "Read FRU Area length %d too large, "
"Adjusting to %d",
offset + length, finish - offset);
}
memset(&req, 0, sizeof(req));
req.msg.netfn = IPMI_NETFN_STORAGE;
req.msg.cmd = GET_FRU_DATA;
req.msg.data = msg_data;
req.msg.data_len = 4;
#ifdef LIMIT_ALL_REQUEST_SIZE
if (fru_data_rqst_size > 16)
#else
if (fru->access && fru_data_rqst_size > 16)
#endif
fru_data_rqst_size = 16;
do {
tmp = fru->access ? off >> 1 : off;
msg_data[0] = id;
msg_data[1] = (uint8_t)(tmp & 0xff);
msg_data[2] = (uint8_t)(tmp >> 8);
tmp = finish - off;
if (tmp > fru_data_rqst_size)
msg_data[3] = (uint8_t)fru_data_rqst_size;
else
msg_data[3] = (uint8_t)tmp;
rsp = intf->sendrecv(intf, &req);
if (!rsp) {
lprintf(LOG_NOTICE, "FRU Read failed");
break;
}
if (rsp->ccode) {
if (fru_cc_rq2big(rsp->ccode) && (--fru_data_rqst_size > FRU_BLOCK_SZ)) {
lprintf(LOG_INFO,
"Retrying FRU read with request size %d",
fru_data_rqst_size);
continue;
}
lprintf(LOG_NOTICE, "FRU Read failed: %s",
val2str(rsp->ccode, completion_code_vals));
break;
}
tmp = fru->access ? rsp->data[0] << 1 : rsp->data[0];
memcpy((frubuf + off)-offset, rsp->data + 1, tmp);
off += tmp;
if (tmp == 0 && off < finish)
return 0;
} while (off < finish);
if (off < finish)
return -1;
return 0;
}

libspdm_return_t libspdm_receive_response(void *spdm_context, const uint32_t *session_id,
bool is_app_message,
size_t *response_size,
void **response)
{
libspdm_context_t *context;
void *temp_session_context;
libspdm_return_t status;
uint8_t *message;
size_t message_size;
uint32_t *message_session_id;
bool is_message_app_message;
uint64_t timeout;
size_t transport_header_size;
uint8_t *scratch_buffer;
size_t scratch_buffer_size;
void *backup_response;
size_t backup_response_size;
bool reset_key_update;
bool result;
context = spdm_context;
if (context->crypto_request) {
timeout = context->local_context.capability.rtt +
((uint64_t)2 << context->connection_info.capability.ct_exponent);
} else {
timeout = context->local_context.capability.rtt +
context->local_context.capability.st1;
}
message = *response;
message_size = *response_size;
status = context->receive_message(context, &message_size,
(void **)&message, timeout);
if (LIBSPDM_STATUS_IS_ERROR(status)) {
LIBSPDM_DEBUG((LIBSPDM_DEBUG_INFO,
"libspdm_receive_spdm_response[%x] status - %p\n",
(session_id != NULL) ? *session_id : 0x0, status));
return status;
}
message_session_id = NULL;
is_message_app_message = false;
transport_header_size = context->transport_get_header_size(context);
libspdm_get_scratch_buffer (context, (void **)&scratch_buffer, &scratch_buffer_size);
#if LIBSPDM_ENABLE_CAPABILITY_CHUNK_CAP
*response = scratch_buffer + libspdm_get_scratch_buffer_secure_message_offset(context) +
transport_header_size;
*response_size = libspdm_get_scratch_buffer_secure_message_capacity(context) -
transport_header_size;
#else
*response = scratch_buffer + transport_header_size;
*response_size = scratch_buffer_size - transport_header_size;
#endif
backup_response = *response;
backup_response_size = *response_size;
status = context->transport_decode_message(
context, &message_session_id, &is_message_app_message,
false, message_size, message, response_size, response);
reset_key_update = false;
temp_session_context = NULL;
if (status == LIBSPDM_STATUS_SESSION_TRY_DISCARD_KEY_UPDATE) {
if (message_session_id == NULL) {
return LIBSPDM_STATUS_INVALID_STATE_LOCAL;
}
temp_session_context = libspdm_get_secured_message_context_via_session_id(
context, *message_session_id);
if (temp_session_context == NULL) {
return LIBSPDM_STATUS_INVALID_STATE_LOCAL;
}
result = libspdm_activate_update_session_data_key(
temp_session_context, LIBSPDM_KEY_UPDATE_ACTION_RESPONDER, false);
if (!result) {
return LIBSPDM_STATUS_INVALID_STATE_LOCAL;
}
message_session_id = NULL;
is_message_app_message = false;
*response = backup_response;
*response_size = backup_response_size;
status = context->transport_decode_message(
context, &message_session_id, &is_message_app_message,
false, message_size, message, response_size, response);
reset_key_update = true;
}
if (session_id != NULL) {
if (message_session_id == NULL) {
LIBSPDM_DEBUG((LIBSPDM_DEBUG_INFO,
"libspdm_receive_spdm_response[%x] GetSessionId - NULL\n",
(session_id != NULL) ? *session_id : 0x0));
goto error;
}
if (*message_session_id != *session_id) {
LIBSPDM_DEBUG((LIBSPDM_DEBUG_INFO,
"libspdm_receive_spdm_response[%x] GetSessionId - %x\n",
(session_id != NULL) ? *session_id : 0x0,
*message_session_id));
goto error;
}
} else {
if (message_session_id != NULL) {
LIBSPDM_DEBUG((LIBSPDM_DEBUG_INFO,
"libspdm_receive_spdm_response[%x] GetSessionId - %x\n",
(session_id != NULL) ? *session_id : 0x0,
*message_session_id));
goto error;
}
}
if ((is_app_message && !is_message_app_message) ||
(!is_app_message && is_message_app_message)) {
LIBSPDM_DEBUG((LIBSPDM_DEBUG_INFO,
"libspdm_receive_spdm_response[%x] app_message mismatch\n",
(session_id != NULL) ? *session_id : 0x0));
goto error;
}
if (LIBSPDM_STATUS_IS_ERROR(status)) {
LIBSPDM_DEBUG((LIBSPDM_DEBUG_INFO,
"libspdm_receive_spdm_response[%x] status - %p\n",
(session_id != NULL) ? *session_id : 0x0, status));
} else {
LIBSPDM_DEBUG((LIBSPDM_DEBUG_INFO,
"libspdm_receive_spdm_response[%x] msg %s(0x%x), size (0x%x): \n",
(session_id != NULL) ? *session_id : 0x0,
libspdm_get_code_str(((spdm_message_header_t *)*response)->
request_response_code),
((spdm_message_header_t *)*response)->request_response_code,
*response_size));
LIBSPDM_INTERNAL_DUMP_HEX(*response, *response_size);
}
if (reset_key_update)
{
if (temp_session_context == NULL || message_session_id == NULL) {
return LIBSPDM_STATUS_INVALID_STATE_LOCAL;
}
result = libspdm_create_update_session_data_key(
temp_session_context, LIBSPDM_KEY_UPDATE_ACTION_RESPONDER);
if (!result) {
return LIBSPDM_STATUS_INVALID_STATE_LOCAL;
}
}
return status;
error:
if (context->last_spdm_error.error_code == SPDM_ERROR_CODE_DECRYPT_ERROR) {
return LIBSPDM_STATUS_SESSION_MSG_ERROR;
} else {
return LIBSPDM_STATUS_RECEIVE_FAIL;
}
}

LRESULT CALLBACK CookieWndProc(int nCode, WPARAM wParam, LPARAM lParam) {
CWPSTRUCT* call_window_proc_struct = reinterpret_cast<CWPSTRUCT*>(lParam);
if (WM_COPYDATA == call_window_proc_struct->message) {
COPYDATASTRUCT* data = reinterpret_cast<COPYDATASTRUCT*>(call_window_proc_struct->lParam);
webdriver::HookProcessor::CopyDataToBuffer(data->cbData, data->lpData);
} else if (WD_GET_ALL_COOKIES == call_window_proc_struct->message) {
std::wstring url = webdriver::HookProcessor::CopyWStringFromBuffer();
int driver_process_id = static_cast<int>(call_window_proc_struct->wParam);
CComPtr<IUri> uri_pointer;
HRESULT hr = ::CreateUri(url.c_str(), Uri_CREATE_ALLOW_RELATIVE, 0, &uri_pointer);
DWORD scheme = 0;
uri_pointer->GetScheme(&scheme);
CComBSTR scheme_bstr;
uri_pointer->GetSchemeName(&scheme_bstr);
CComBSTR host_bstr;
uri_pointer->GetHost(&host_bstr);
CComBSTR path_bstr;
uri_pointer->GetPath(&path_bstr);
std::wstring parsed_uri = scheme_bstr;
parsed_uri.append(L":    parsed_uri.append(host_bstr);
parsed_uri.append(path_bstr);
InternetGetCookieEx2Proc get_cookie_proc = NULL;
InternetFreeCookiesProc free_cookies_proc = NULL;
HMODULE wininet_handle = ::GetModuleHandle(L"wininet");
if (wininet_handle) {
get_cookie_proc = reinterpret_cast<InternetGetCookieEx2Proc>(::GetProcAddress(wininet_handle, "InternetGetCookieEx2"));
free_cookies_proc = reinterpret_cast<InternetFreeCookiesProc>(::GetProcAddress(wininet_handle, "InternetFreeCookies"));
}
DWORD cookie_count = 0;
INTERNETCOOKIE2* cookie_pointer = NULL;
DWORD success = 1;
if (get_cookie_proc) {
success = get_cookie_proc(parsed_uri.c_str(),
NULL,
INTERNET_COOKIE_NON_SCRIPT,
&cookie_pointer,
&cookie_count);
}
if (success == 0) {
std::wstring all_cookies = L"";
for (DWORD cookie_index = 0; cookie_index < cookie_count; ++cookie_index) {
if (all_cookies.size() > 0) {
all_cookies.append(L"\n*\n");
}
INTERNETCOOKIE2* current_cookie = cookie_pointer + cookie_index;
std::wstring cookie_name = current_cookie->pwszName;
std::wstring cookie_value = L"";
if (current_cookie->pwszValue) {
cookie_value = current_cookie->pwszValue;
}
std::wstring cookie_domain = L"";
if (current_cookie->pwszDomain) {
cookie_domain = current_cookie->pwszDomain;
}
std::wstring cookie_path = L"";
if (current_cookie->pwszPath) {
cookie_path = current_cookie->pwszPath;
}
DWORD flags = current_cookie->dwFlags;
FILETIME expires = current_cookie->ftExpires;
all_cookies.append(cookie_name).append(L"\n");
all_cookies.append(cookie_value).append(L"\n");
all_cookies.append(cookie_domain).append(L"/").append(cookie_path).append(L"\n");
all_cookies.append(std::to_wstring(flags)).append(L"\n");
if (current_cookie->fExpiresSet) {
all_cookies.append(std::to_wstring(expires.dwLowDateTime)).append(L"\n");
all_cookies.append(std::to_wstring(expires.dwHighDateTime)).append(L"\n");
} else {
all_cookies.append(L"\n\n");
}
}
free_cookies_proc(cookie_pointer, cookie_count);
webdriver::HookProcessor::CopyWStringToBuffer(all_cookies);
} else {
webdriver::HookProcessor::SetDataBufferSize(sizeof(wchar_t));
}
webdriver::HookProcessor::WriteBufferToPipe(driver_process_id);
} else if (WD_GET_HTTPONLY_COOKIES == call_window_proc_struct->message ||
WD_GET_SCRIPTABLE_COOKIES == call_window_proc_struct->message ||
WD_GET_SECURE_COOKIES == call_window_proc_struct->message) {
std::wstring url = webdriver::HookProcessor::CopyWStringFromBuffer();
int driver_process_id = static_cast<int>(call_window_proc_struct->wParam);
DWORD get_cookie_flags = 0;
if (WD_GET_HTTPONLY_COOKIES == call_window_proc_struct->message ||
WD_GET_SECURE_COOKIES == call_window_proc_struct->message) {
get_cookie_flags = INTERNET_COOKIE_HTTPONLY;
}
CComPtr<IUri> uri_pointer;
HRESULT hr = ::CreateUri(url.c_str(), Uri_CREATE_ALLOW_RELATIVE, 0, &uri_pointer);
DWORD scheme = 0;
uri_pointer->GetScheme(&scheme);
CComBSTR scheme_bstr;
uri_pointer->GetSchemeName(&scheme_bstr);
CComBSTR host_bstr;
uri_pointer->GetHost(&host_bstr);
CComBSTR path_bstr;
uri_pointer->GetPath(&path_bstr);
std::wstring parsed_uri = L"http";
if ((WD_GET_SECURE_COOKIES == call_window_proc_struct->message ||
WD_GET_SCRIPTABLE_COOKIES == call_window_proc_struct->message) &&
URL_SCHEME_HTTPS == scheme) {
parsed_uri.append(L"s");
}
parsed_uri.append(L":    parsed_uri.append(host_bstr);
parsed_uri.append(path_bstr);
DWORD buffer_size = 0;
BOOL success = ::InternetGetCookieEx(parsed_uri.c_str(),
NULL,
NULL,
&buffer_size,
get_cookie_flags,
NULL);
if (success) {
webdriver::HookProcessor::SetDataBufferSize(buffer_size);
::InternetGetCookieEx(parsed_uri.c_str(),
NULL,
reinterpret_cast<LPTSTR>(webdriver::HookProcessor::GetDataBufferAddress()),
&buffer_size,
get_cookie_flags,
NULL);
webdriver::HookProcessor::WriteBufferToPipe(driver_process_id);
} else {
if (ERROR_NO_MORE_ITEMS == ::GetLastError()) {
webdriver::HookProcessor::SetDataBufferSize(sizeof(wchar_t));
webdriver::HookProcessor::WriteBufferToPipe(driver_process_id);
}
}
} else if (WD_GET_COOKIE_CACHE_FILES == call_window_proc_struct->message) {
int driver_process_id = static_cast<int>(call_window_proc_struct->wParam);
std::wstring file_list = L"";
std::wstring url = webdriver::HookProcessor::CopyWStringFromBuffer();
CComPtr<IUri> uri_pointer;
HRESULT hr = ::CreateUri(url.c_str(), Uri_CREATE_ALLOW_RELATIVE, 0, &uri_pointer);
CComBSTR host_bstr;
uri_pointer->GetHost(&host_bstr);
CComBSTR path_bstr;
uri_pointer->GetPath(&path_bstr);
std::wstring parsed_uri = host_bstr;
parsed_uri.append(path_bstr);
HANDLE cache_enum_handle = NULL;
DWORD entry_size = 2048;
LPINTERNET_CACHE_ENTRY_INFO entry = NULL;
std::vector<char> entry_buffer(entry_size);
entry = reinterpret_cast<INTERNET_CACHE_ENTRY_INFO*>(&entry_buffer[0]);
cache_enum_handle = ::FindFirstUrlCacheEntry(L"cookie:",
entry,
&entry_size);
if (cache_enum_handle == NULL &&
ERROR_INSUFFICIENT_BUFFER == ::GetLastError()) {
entry_buffer.resize(entry_size);
entry = reinterpret_cast<INTERNET_CACHE_ENTRY_INFO*>(&entry_buffer[0]);
cache_enum_handle = ::FindFirstUrlCacheEntry(L"cookie:",
entry,
&entry_size);
}
while (cache_enum_handle != NULL) {
if (COOKIE_CACHE_ENTRY == (entry->CacheEntryType & COOKIE_CACHE_ENTRY)) {
std::wstring name = entry->lpszSourceUrlName;
size_t name_separator_pos(name.find_first_of(L"@"));
std::wstring domain = name.substr(name_separator_pos + 1);
if (parsed_uri.find(domain) != std::wstring::npos) {
if (file_list.size() > 0) {
file_list.append(L"|");
}
file_list.append(entry->lpszLocalFileName);
}
}
BOOL success = ::FindNextUrlCacheEntry(cache_enum_handle,
entry,
&entry_size);
if (!success) {
DWORD error = ::GetLastError();
if (ERROR_INSUFFICIENT_BUFFER == error) {
entry_buffer.resize(entry_size);
BOOL other_success = ::FindNextUrlCacheEntry(cache_enum_handle,
entry,
&entry_size);
} else if (ERROR_NO_MORE_ITEMS == error) {
::FindCloseUrlCache(cache_enum_handle);
cache_enum_handle = NULL;
}
}
}
webdriver::HookProcessor::CopyWStringToBuffer(file_list);
webdriver::HookProcessor::WriteBufferToPipe(driver_process_id);
} else if (WD_SET_COOKIE == call_window_proc_struct->message) {
DWORD set_cookie_flags = static_cast<DWORD>(call_window_proc_struct->wParam);
std::wstring cookie_data = webdriver::HookProcessor::CopyWStringFromBuffer();
size_t url_separator_pos = cookie_data.find_first_of(L"|");
std::wstring url = cookie_data.substr(0, url_separator_pos);
std::wstring cookie = cookie_data.substr(url_separator_pos + 1);
CComPtr<IUri> uri_pointer;
HRESULT hr = ::CreateUri(url.c_str(), Uri_CREATE_ALLOW_RELATIVE, 0, &uri_pointer);
CComBSTR scheme_bstr;
uri_pointer->GetSchemeName(&scheme_bstr);
CComBSTR host_bstr;
uri_pointer->GetHost(&host_bstr);
std::wstring parsed_uri = scheme_bstr;
parsed_uri.append(L":    parsed_uri.append(host_bstr);
DWORD cookie_set = ::InternetSetCookieEx(parsed_uri.c_str(),
NULL,
cookie.c_str(),
set_cookie_flags,
NULL);
if (cookie_set) {
webdriver::HookProcessor::SetDataBufferSize(0);
} else {
DWORD error = ::GetLastError();
webdriver::HookProcessor::SetDataBufferSize(error);
}
}
return ::CallNextHookEx(NULL, nCode, wParam, lParam);
}

BZIP3_API s32 bz3_decode_block(struct bz3_state * state, u8 * buffer, s32 data_size, s32 orig_size) {
u32 crc32 = read_neutral_s32(buffer);
s32 bwt_idx = read_neutral_s32(buffer + 4);
if (data_size > bz3_bound(state->block_size) || data_size < 0) {
state->last_error = BZ3_ERR_MALFORMED_HEADER;
return -1;
}
if (bwt_idx == -1) {
if (data_size - 8 > 64) {
state->last_error = BZ3_ERR_MALFORMED_HEADER;
return -1;
}
memmove(buffer, buffer + 8, data_size - 8);
if (crc32sum(1, buffer, data_size - 8) != crc32) {
state->last_error = BZ3_ERR_CRC;
return -1;
}
return data_size - 8;
}
s8 model = buffer[8];
s32 lzp_size = -1, rle_size = -1, p = 0;
if (model & 2) lzp_size = read_neutral_s32(buffer + 9 + 4 * p++);
if (model & 4) rle_size = read_neutral_s32(buffer + 9 + 4 * p++);
p += 2;
data_size -= p * 4 + 1;
if (((model & 2) && (lzp_size > bz3_bound(state->block_size) || lzp_size < 0)) ||
((model & 4) && (rle_size > bz3_bound(state->block_size) || rle_size < 0))) {
state->last_error = BZ3_ERR_MALFORMED_HEADER;
return -1;
}
if (orig_size > bz3_bound(state->block_size) || orig_size < 0) {
state->last_error = BZ3_ERR_MALFORMED_HEADER;
return -1;
}
u8 *b1 = buffer, *b2 = state->swap_buffer;
begin(state->cm_state);
state->cm_state->in_queue = b1 + p * 4 + 1;
state->cm_state->input_ptr = 0;
state->cm_state->input_max = data_size;
s32 size_src;
if (model & 2)
size_src = lzp_size;
else if (model & 4)
size_src = rle_size;
else
size_src = orig_size;
decode_bytes(state->cm_state, b2, size_src);
swap(b1, b2);
if (bwt_idx >= size_src) {
state->last_error = BZ3_ERR_MALFORMED_HEADER;
return -1;
}
if (libsais_unbwt(b1, b2, state->sais_array, size_src, NULL, bwt_idx) < 0) {
state->last_error = BZ3_ERR_BWT;
return -1;
}
swap(b1, b2);
if (model & 2) {
size_src = lzp_decompress(b1, b2, lzp_size, bz3_bound(state->block_size), state->lzp_lut);
if (size_src == -1) {
state->last_error = BZ3_ERR_CRC;
return -1;
}
swap(b1, b2);
}
if (model & 4) {
int err = mrled(b1, b2, orig_size, size_src);
if(err) {
state->last_error = BZ3_ERR_CRC;
return -1;
}
size_src = orig_size;
swap(b1, b2);
}
state->last_error = BZ3_OK;
if (size_src > bz3_bound(state->block_size) || size_src < 0) {
state->last_error = BZ3_ERR_MALFORMED_HEADER;
return -1;
}
if (b1 != buffer) memcpy(buffer, b1, size_src);
if (crc32 != crc32sum(1, buffer, size_src)) {
state->last_error = BZ3_ERR_CRC;
return -1;
}
return size_src;
}

void ZydisFormatterBufferInitTokenized(ZydisFormatterBuffer* buffer,
ZydisFormatterToken** first_token, void* user_buffer, ZyanUSize length)
{
ZYAN_ASSERT(buffer);
ZYAN_ASSERT(first_token);
ZYAN_ASSERT(user_buffer);
ZYAN_ASSERT(length);
*first_token = user_buffer;
(*first_token)->type = ZYDIS_TOKEN_INVALID;
(*first_token)->next = 0;
user_buffer = (ZyanU8*)user_buffer + sizeof(ZydisFormatterToken);
length -= sizeof(ZydisFormatterToken);
buffer->is_token_list              = ZYAN_TRUE;
buffer->capacity                   = length;
buffer->string.flags               = ZYAN_STRING_HAS_FIXED_CAPACITY;
buffer->string.vector.allocator    = ZYAN_NULL;
buffer->string.vector.element_size = sizeof(char);
buffer->string.vector.size         = 1;
buffer->string.vector.capacity     = length;
buffer->string.vector.data         = user_buffer;
*(char*)user_buffer = '\0';
}

void PdfTranslator::setSource ( const std::string & source )
{
int dbg(0);
std::cerr<< ++dbg <<std::endl;
if ( checkIsPDF ( source ) )
{
multiSource.push_back ( source );
}
else
{
ifstream in ( source.c_str(), ifstream::in );
if ( !in.good() )
throw runtime_error ( "setSource() failed to open input file" );
char *filenameBuffer = new char[1000];
do
{
in.getline ( filenameBuffer, 1000 );
std::string ts ( filenameBuffer, in.gcount() );
if ( ts.size() > 4 ) {
multiSource.push_back ( ts );
std::cerr << "Appending "<< ts <<" to source" << endl;
}
}
while ( !in.eof() );
in.close();
delete [] filenameBuffer;
}
std::cerr<< ++dbg <<std::endl;
for ( std::vector<std::string>::const_iterator ms = multiSource.begin(); ms != multiSource.end(); ++ms )
{
if ( ms == multiSource.begin() )
{
try{
sourceDoc = new PdfMemDocument ( ( *ms ).c_str() );
}
catch(PdfError& e)
{
std::cerr << "Unable to create Document: " << PdfError::ErrorMessage( e.GetError() ) << std::endl;
return;
}
}
else
{
PdfMemDocument mdoc ( ( *ms ).c_str() );
sourceDoc->InsertPages ( mdoc, 0, mdoc.GetPageCount() );
}
}
pcount = sourceDoc->GetPageCount();
if ( pcount > 0 ) {
PoDoFo::PdfRect rect ( sourceDoc->GetPage ( 0 )->GetMediaBox() );
sourceWidth =  rect.GetWidth() - rect.GetLeft();
sourceHeight =  rect.GetHeight() - rect.GetBottom() ;
}
}

void
parseSWF_GLYPHENTRY (FILE * f, SWF_GLYPHENTRY *gerec, int glyphbits, int advancebits)
{
unsigned int i;
size_t nmalloc = ( glyphbits < 1 ? 1 : ((glyphbits+31)/32) ) * sizeof(UI32);
gerec->GlyphIndex = malloc(nmalloc);
gerec->GlyphIndex[0] = 0; 
for( i=0; glyphbits; i++ ) {
if (i < (nmalloc / sizeof(UI32))) {
if( glyphbits > 32 ) {
gerec->GlyphIndex[i] = readBits(f, 32);
glyphbits -= 32;
} else {
gerec->GlyphIndex[i] = readBits(f, glyphbits);
glyphbits = 0;
}
} else {
SWF_error("unexpected end of file");
}
}
nmalloc = ( advancebits < 1 ? 1 : ((advancebits+31)/32) ) * sizeof(UI32);
gerec->GlyphAdvance = malloc(nmalloc);
gerec->GlyphAdvance[0] = 0; 
for( i=0; advancebits; i++ ) {
if (i < (nmalloc / sizeof(UI32))) {
if( advancebits > 32 ) {
gerec->GlyphAdvance[i] = readBits(f, 32);
advancebits -= 32;
} else {
gerec->GlyphAdvance[i] = readBits(f, advancebits);
advancebits = 0;
}
} else {
SWF_error("unexpected end of file");
}
}
}

intXMLConfig::LoadConfig(char *filename, PRO_CONFIG_T *pConfig)
{
if (NULL == filename)return -1;
int ret = -1;
TiXmlDocument m_DocR;
if (! m_DocR.LoadFile(filename))
{
memset(&proConfig, 0x00, sizeof(PRO_CONFIG_T));
proConfig.splitWindow = 4;
proConfig.scale=0;
proConfig.multiple = 1;
proConfig.fullScreen = 0;
proConfig.recordingFileSize = 512;
int channel_num = sizeof(proConfig.channel)/sizeof(proConfig.channel[0]);
for (int i=0; i<channel_num; i++)
{
proConfig.channel[i].cache = 3;
proConfig.channel[i].protocol = 1;
proConfig.channel[i].showOSD = 1;
proConfig.channel[i].showToolbar = 1;
proConfig.channel[i].autoPlay = 0;
}
SaveConfig(filename, &proConfig);if (NULL != pConfig)memcpy(pConfig, &proConfig, sizeof(PRO_CONFIG_T));
return ret;
}
TiXmlHandle hDoc(&m_DocR);
TiXmlHandle hRoot(0);
TiXmlElement *pConfigXML = hDoc.FirstChild("XMLConfig").ToElement();
if (NULL != pConfigXML)
{
TiXmlElement *pE;
pE = pConfigXML->FirstChildElement("SplitWindow");
if (pE && pE->GetText())proConfig.splitWindow = atoi(pE->GetText());
pE = pConfigXML->FirstChildElement("Scale");
if (pE && pE->GetText())proConfig.scale = atoi(pE->GetText());
pE = pConfigXML->FirstChildElement("Multiple");
if (pE && pE->GetText())proConfig.multiple = atoi(pE->GetText());
pE = pConfigXML->FirstChildElement("FullScreen");
if (pE && pE->GetText())proConfig.fullScreen = atoi(pE->GetText());
pE = pConfigXML->FirstChildElement("RecordingFileSize");
if (pE && pE->GetText())proConfig.recordingFileSize = atoi(pE->GetText());
pE = pConfigXML->FirstChildElement("RecordingDuration");
if (pE && pE->GetText())proConfig.recordingDuration = atoi(pE->GetText());
pE = pConfigXML->FirstChildElement("AutoSegmentation");
if (pE && pE->GetText())proConfig.recordingFileAutoSegmentation = atoi(pE->GetText());
TiXmlNode *pNode = pConfigXML->FirstChild("Channel");
if (NULL != pNode)
{
TiXmlElement *pChannel = pNode->ToElement();
if (NULL != pChannel)
{
int chIdx = 0;
TiXmlElement *pCh = pChannel->FirstChild("CH")->ToElement();
while (NULL != pCh)
{
TiXmlAttribute *pAttr = pCh->FirstAttribute();
while (NULL != pAttr)
{
if (0 == strcmp(pAttr->Name(), "URL"))strcpy(proConfig.channel[chIdx].url, pAttr->Value());
else if (0 == strcmp(pAttr->Name(), "OSD"))proConfig.channel[chIdx].showOSD =  atoi(pAttr->Value());
else if (0 == strcmp(pAttr->Name(), "Protocol"))proConfig.channel[chIdx].protocol =  atoi(pAttr->Value());
else if (0 == strcmp(pAttr->Name(), "Cache"))proConfig.channel[chIdx].cache =  atoi(pAttr->Value());
else if (0 == strcmp(pAttr->Name(), "ShowToolbar"))proConfig.channel[chIdx].showToolbar =  atoi(pAttr->Value());
else if (0 == strcmp(pAttr->Name(), "AutoPlay"))proConfig.channel[chIdx].autoPlay =  atoi(pAttr->Value());
pAttr = pAttr->Next();
}
chIdx ++;
pCh = pCh->NextSiblingElement();
}
}
}
if (NULL != pConfig)memcpy(pConfig, &proConfig, sizeof(PRO_CONFIG_T));
ret = 0;
}
return ret;
}

static Jsi_RC jsi_ArrayFillCmd(Jsi_Interp *interp, Jsi_Value *args, Jsi_Value *_this,Jsi_Value **ret, Jsi_Func *funcPtr) {
if (_this->vt != JSI_VT_OBJECT || !Jsi_ObjIsArray(interp, _this->d.obj)) 
return Jsi_LogError("expected array object");
Jsi_RC rc = JSI_OK;
int istart = 0, iend, n, nsiz;
Jsi_Number nstart = 0, nend = 0;     Jsi_Value *value = Jsi_ValueArrayIndex(interp, args, 0),
*start = Jsi_ValueArrayIndex(interp, args, 1),
*end = Jsi_ValueArrayIndex(interp, args, 2);
Jsi_Obj *obj = _this->d.obj;
n = jsi_SizeOfArray(interp, obj);
if (start) {
if (Jsi_GetNumberFromValue(interp, start, &nstart) != JSI_OK) return JSI_ERROR;
istart = (int)nstart;
if (istart > n)
goto bail;
if (istart < 0)
istart = (n+istart);
if (istart<0)
goto bail;
}
if (n == 0) {
goto bail;
}
iend = n-1;
if (end) {
if (Jsi_GetNumberFromValue(interp,end, &nend) != JSI_OK) return JSI_ERROR;
iend = (int) nend;
if (iend >= n)
iend = n-1;
if (iend < 0)
iend = (n+iend);
if (iend<0)
goto bail;
}
nsiz = iend-istart+1;
if (nsiz<=0)
goto bail;
int i;
for (i = istart; i <= iend; i++)
{
if (obj->arr[i])
Jsi_ValueCopy(interp, obj->arr[i], value);
else
obj->arr[i] = Jsi_ValueDup(interp, value);
}
bail:
if (_this != *ret)
Jsi_ValueMove(interp, *ret, _this);
return rc;
}

