fz_pixmap *
fz_new_pixmap_with_data(fz_context *ctx, fz_colorspace *colorspace, int w, int h, fz_separations *seps, int alpha, int stride, unsigned char *samples)
{
fz_pixmap *pix;
int s = fz_count_active_separations(ctx, seps);
int n;
if (w < 0 || h < 0)
fz_throw(ctx, FZ_ERROR_GENERIC, "Illegal dimensions for pixmap %d %d", w, h);
n = alpha + s + fz_colorspace_n(ctx, colorspace);
if (stride < n*w && stride > -n*w)
fz_throw(ctx, FZ_ERROR_GENERIC, "Illegal stride for pixmap (n=%d w=%d, stride=%d)", n, w, stride);
if (samples == NULL && stride < n*w)
fz_throw(ctx, FZ_ERROR_GENERIC, "Illegal -ve stride for pixmap without data");
if (n > FZ_MAX_COLORS)
fz_throw(ctx, FZ_ERROR_GENERIC, "Illegal number of colorants");
pix = fz_malloc_struct(ctx, fz_pixmap);
FZ_INIT_STORABLE(pix, 1, fz_drop_pixmap_imp);
pix->x = 0;
pix->y = 0;
pix->w = w;
pix->h = h;
pix->alpha = alpha = !!alpha;
pix->flags = FZ_PIXMAP_FLAG_INTERPOLATE;
pix->xres = 96;
pix->yres = 96;
pix->colorspace = NULL;
pix->n = n;
pix->s = s;
pix->seps = fz_keep_separations(ctx, seps);
pix->stride = stride;
if (colorspace)
{
pix->colorspace = fz_keep_colorspace(ctx, colorspace);
}
else
{
assert(alpha || s);
}
pix->samples = samples;
if (!samples)
{
fz_try(ctx)
{
if (pix->stride - 1 > INT_MAX / pix->n)
fz_throw(ctx, FZ_ERROR_GENERIC, "overly wide image");
pix->samples = Memento_label(fz_malloc(ctx, pix->h * pix->stride), "pixmap_data");
}
fz_catch(ctx)
{
fz_drop_separations(ctx, pix->seps);
fz_drop_colorspace(ctx, pix->colorspace);
fz_free(ctx, pix);
fz_rethrow(ctx);
}
pix->flags |= FZ_PIXMAP_FLAG_FREE_SAMPLES;
}
return pix;
}

ret_t
cherokee_validator_parse_basic (cherokee_validator_t *validator, char *str, cuint_t str_len)
{
char              *colon;
cherokee_buffer_t  auth = CHEROKEE_BUF_INIT;
cherokee_buffer_add (&auth, str, str_len);
cherokee_buffer_decode_base64 (&auth);
colon = strchr (auth.buf, ':');
if (colon == NULL)
goto error;
cherokee_buffer_add (&validator->user, auth.buf, colon - auth.buf);
cherokee_buffer_add (&validator->passwd, colon+1, auth.len  - ((colon+1) - auth.buf));
TRACE (ENTRIES, "Parse basic auth got user=%s, passwd=%s\n", validator->user.buf, validator->passwd.buf);
cherokee_buffer_mrproper (&auth);
return ret_ok;
error:
cherokee_buffer_mrproper (&auth);
return ret_error;
}

static void
esis_print(netdissect_options *ndo,
const uint8_t *pptr, u_int length)
{
const uint8_t *optr;
u_int li,esis_pdu_type,source_address_length, source_address_number;
const struct esis_header_t *esis_header;
if (!ndo->ndo_eflag)
ND_PRINT((ndo, "ES-IS"));
if (length <= 2) {
ND_PRINT((ndo, ndo->ndo_qflag ? "bad pkt!" : "no header at all!"));
return;
}
esis_header = (const struct esis_header_t *) pptr;
ND_TCHECK(*esis_header);
li = esis_header->length_indicator;
optr = pptr;
if (esis_header->nlpid != NLPID_ESIS) {
ND_PRINT((ndo, " nlpid 0x%02x packet not supported", esis_header->nlpid));
return;
}
if (esis_header->version != ESIS_VERSION) {
ND_PRINT((ndo, " version %d packet not supported", esis_header->version));
return;
}
if (li > length) {
ND_PRINT((ndo, " length indicator(%u) > PDU size (%u)!", li, length));
return;
}
if (li < sizeof(struct esis_header_t) + 2) {
ND_PRINT((ndo, " length indicator %u < min PDU size:", li));
while (pptr < ndo->ndo_snapend)
ND_PRINT((ndo, "%02X", *pptr++));
return;
}
esis_pdu_type = esis_header->type & ESIS_PDU_TYPE_MASK;
if (ndo->ndo_vflag < 1) {
ND_PRINT((ndo, "%s%s, length %u",
ndo->ndo_eflag ? "" : ", ",
tok2str(esis_pdu_values,"unknown type (%u)",esis_pdu_type),
length));
return;
} else
ND_PRINT((ndo, "%slength %u\n\t%s (%u)",
ndo->ndo_eflag ? "" : ", ",
length,
tok2str(esis_pdu_values,"unknown type: %u", esis_pdu_type),
esis_pdu_type));
ND_PRINT((ndo, ", v: %u%s", esis_header->version, esis_header->version == ESIS_VERSION ? "" : "unsupported" ));
ND_PRINT((ndo, ", checksum: 0x%04x", EXTRACT_16BITS(esis_header->cksum)));
osi_print_cksum(ndo, pptr, EXTRACT_16BITS(esis_header->cksum), 7, li);
ND_PRINT((ndo, ", holding time: %us, length indicator: %u",
EXTRACT_16BITS(esis_header->holdtime), li));
if (ndo->ndo_vflag > 1)
print_unknown_data(ndo, optr, "\n\t", sizeof(struct esis_header_t));
pptr += sizeof(struct esis_header_t);
li -= sizeof(struct esis_header_t);
switch (esis_pdu_type) {
case ESIS_PDU_REDIRECT: {
const uint8_t *dst, *snpa, *neta;
u_int dstl, snpal, netal;
ND_TCHECK(*pptr);
if (li < 1) {
ND_PRINT((ndo, ", bad redirect/li"));
return;
}
dstl = *pptr;
pptr++;
li--;
ND_TCHECK2(*pptr, dstl);
if (li < dstl) {
ND_PRINT((ndo, ", bad redirect/li"));
return;
}
dst = pptr;
pptr += dstl;
li -= dstl;
ND_PRINT((ndo, "\n\t  %s", isonsap_string(ndo, dst, dstl)));
ND_TCHECK(*pptr);
if (li < 1) {
ND_PRINT((ndo, ", bad redirect/li"));
return;
}
snpal = *pptr;
pptr++;
li--;
ND_TCHECK2(*pptr, snpal);
if (li < snpal) {
ND_PRINT((ndo, ", bad redirect/li"));
return;
}
snpa = pptr;
pptr += snpal;
li -= snpal;
ND_TCHECK(*pptr);
if (li < 1) {
ND_PRINT((ndo, ", bad redirect/li"));
return;
}
netal = *pptr;
pptr++;
ND_TCHECK2(*pptr, netal);
if (li < netal) {
ND_PRINT((ndo, ", bad redirect/li"));
return;
}
neta = pptr;
pptr += netal;
li -= netal;
if (netal == 0)
ND_PRINT((ndo, "\n\t  %s", etheraddr_string(ndo, snpa)));
else
ND_PRINT((ndo, "\n\t  %s", isonsap_string(ndo, neta, netal)));
break;
}
case ESIS_PDU_ESH:
ND_TCHECK(*pptr);
if (li < 1) {
ND_PRINT((ndo, ", bad esh/li"));
return;
}
source_address_number = *pptr;
pptr++;
li--;
ND_PRINT((ndo, "\n\t  Number of Source Addresses: %u", source_address_number));
while (source_address_number > 0) {
ND_TCHECK(*pptr);
if (li < 1) {
ND_PRINT((ndo, ", bad esh/li"));
return;
}
source_address_length = *pptr;
pptr++;
li--;
ND_TCHECK2(*pptr, source_address_length);
if (li < source_address_length) {
ND_PRINT((ndo, ", bad esh/li"));
return;
}
ND_PRINT((ndo, "\n\t  NET (length: %u): %s",
source_address_length,
isonsap_string(ndo, pptr, source_address_length)));
pptr += source_address_length;
li -= source_address_length;
source_address_number--;
}
break;
case ESIS_PDU_ISH: {
ND_TCHECK(*pptr);
if (li < 1) {
ND_PRINT((ndo, ", bad ish/li"));
return;
}
source_address_length = *pptr;
pptr++;
li--;
ND_TCHECK2(*pptr, source_address_length);
if (li < source_address_length) {
ND_PRINT((ndo, ", bad ish/li"));
return;
}
ND_PRINT((ndo, "\n\t  NET (length: %u): %s", source_address_length, isonsap_string(ndo, pptr, source_address_length)));
pptr += source_address_length;
li -= source_address_length;
break;
}
default:
if (ndo->ndo_vflag <= 1) {
if (pptr < ndo->ndo_snapend)
print_unknown_data(ndo, pptr, "\n\t  ", ndo->ndo_snapend - pptr);
}
return;
}
while (li != 0) {
u_int op, opli;
const uint8_t *tptr;
if (li < 2) {
ND_PRINT((ndo, ", bad opts/li"));
return;
}
ND_TCHECK2(*pptr, 2);
op = *pptr++;
opli = *pptr++;
li -= 2;
if (opli > li) {
ND_PRINT((ndo, ", opt (%d) too long", op));
return;
}
li -= opli;
tptr = pptr;
ND_PRINT((ndo, "\n\t  %s Option #%u, length %u, value: ",
tok2str(esis_option_values,"Unknown",op),
op,
opli));
switch (op) {
case ESIS_OPTION_ES_CONF_TIME:
if (opli == 2) {
ND_TCHECK2(*pptr, 2);
ND_PRINT((ndo, "%us", EXTRACT_16BITS(tptr)));
} else
ND_PRINT((ndo, "(bad length)"));
break;
case ESIS_OPTION_PROTOCOLS:
while (opli>0) {
ND_TCHECK(*pptr);
ND_PRINT((ndo, "%s (0x%02x)",
tok2str(nlpid_values,
"unknown",
*tptr),
*tptr));
if (opli>1) 
ND_PRINT((ndo, ", "));
tptr++;
opli--;
}
break;
case ESIS_OPTION_QOS_MAINTENANCE:
case ESIS_OPTION_SECURITY:
case ESIS_OPTION_PRIORITY:
case ESIS_OPTION_ADDRESS_MASK:
case ESIS_OPTION_SNPA_MASK:
default:
print_unknown_data(ndo, tptr, "\n\t  ", opli);
break;
}
if (ndo->ndo_vflag > 1)
print_unknown_data(ndo, pptr, "\n\t  ", opli);
pptr += opli;
}
trunc:
return;
}

static int
dissect_rtcp_rtpfb_transport_cc( tvbuff_t *tvb, int offset, proto_tree *rtcp_tree, int pkt_len)
{
proto_tree *fci_tree, *pkt_chunk_tree, *recv_delta_tree;
proto_item *item       = NULL;
guint8  *delta_array;
guint16 *pkt_seq_array;
guint32 i, pkt_base_seq, pkt_seq_num, pkt_count;
gint fci_length        = pkt_len - RTCP_HEADER_LENGTH;
int delta_index        = 0;
int padding_length     = offset;
fci_tree = proto_tree_add_subtree_format( rtcp_tree, tvb, offset, fci_length, ett_ssrc, NULL, "Transport-cc" );
proto_tree_add_item_ret_uint( fci_tree, hf_rtcp_rtpfb_transport_cc_fci_base_seq, tvb, offset, 2, ENC_BIG_ENDIAN, &pkt_base_seq );
offset += 2;
pkt_seq_num = pkt_base_seq;
proto_tree_add_item_ret_uint( fci_tree, hf_rtcp_rtpfb_transport_cc_fci_pkt_stats_cnt, tvb, offset, 2, ENC_BIG_ENDIAN, &pkt_count );
offset += 2;
delta_array   = wmem_alloc0_array( wmem_packet_scope(), gint8, pkt_count );
pkt_seq_array = wmem_alloc0_array( wmem_packet_scope(), gint16, pkt_count );
proto_tree_add_item( fci_tree, hf_rtcp_rtpfb_transport_cc_fci_ref_time, tvb, offset, 3, ENC_BIG_ENDIAN );
offset += 3;
proto_tree_add_item( fci_tree, hf_rtcp_rtpfb_transport_cc_fci_fb_pkt_cnt, tvb, offset, 1, ENC_BIG_ENDIAN );
offset += 1;
pkt_chunk_tree = proto_tree_add_subtree_format( fci_tree, tvb, offset, 0, ett_ssrc, NULL, "Packet Chunks" );
for (i = 0; i < pkt_count; )
{
guint32 chunk = 0;
item = proto_tree_add_item_ret_uint( pkt_chunk_tree, hf_rtcp_rtpfb_transport_cc_fci_pkt_chunk, tvb, offset, 2, ENC_BIG_ENDIAN, &chunk );
if ( !(chunk & 0x8000) )
{
int length = chunk & 0x1FFF;
if ( length <= 0 )
{
delta_array = NULL;
pkt_seq_array = NULL;
offset += 2;
return offset;
}
if ( !(chunk & 0x6000) )
{
proto_item_append_text( item, " [Run Length Chunk] Packet not received. Length : %d", length);
pkt_seq_num += length;
}
else if ( chunk & 0x2000 )
{
proto_item_append_text( item, " [Run Length Chunk] Small Delta. Length : %d", length);
for (int j = 0; j < length; j++)
{
delta_array[delta_index+j] = 1;
pkt_seq_array[delta_index+j] = pkt_seq_num++;
}
delta_index += length;
}
else if ( chunk & 0x4000 )
{
proto_item_append_text( item, " [Run Length Chunk] Large or Negative Delta. Length : %d", length);
for (int j = 0; j < length; j++)
{
delta_array[delta_index+j] = 2;
pkt_seq_array[delta_index+j] = pkt_seq_num++;
}
delta_index += length;
}
else
{
proto_item_append_text( item, " [Run Length Chunk] [Reserved]. Length : %d", length);
pkt_seq_num += length;
}
i += length;
}
else
{
wmem_strbuf_t* status = wmem_strbuf_new(wmem_packet_scope(), "|");
if ( !(chunk & 0x4000) )
{
int data = chunk & 0x3FFF;
int chunk_count = 14;
for (int k = 0; k < chunk_count; k++)
{
if ( (data & (0x2000>>k)) == 0 )
{
if ( i + k < pkt_count )
{
wmem_strbuf_append(status, " N |");
pkt_seq_num++;
}
else
{
wmem_strbuf_append(status, " _ |");
}
}
else
{
wmem_strbuf_append(status, " R |");
delta_array[delta_index] = 1;
pkt_seq_array[delta_index] = pkt_seq_num++;
delta_index++;
}
}
proto_item_append_text( item, " [1 bit Status Vector Chunk]: %s", wmem_strbuf_get_str(status));
i += chunk_count;
}
else
{
int chunk_count = 7;
int data = chunk & 0x3FFF;
for (int k = 0; k < chunk_count; k++)
{
switch ( (data & (0x3000 >> (2*k))) >> ( 2 * (6-k) ) )
{
case 0: 
if ( i + k < pkt_count )
{
wmem_strbuf_append(status, " NR |");
pkt_seq_num++;
}
else
{
wmem_strbuf_append(status, " __ |");
}
break;
case 1: 
wmem_strbuf_append(status, " SD |");
delta_array[delta_index] = 1;
pkt_seq_array[delta_index] = pkt_seq_num++;
delta_index++;
break;
case 2: 
wmem_strbuf_append(status, " LD |");
delta_array[delta_index] = 2;
pkt_seq_array[delta_index] = pkt_seq_num++;
delta_index++;
break;
case 3: 
default:
wmem_strbuf_append(status, " WO |");
pkt_seq_num++;
break;
}
}
proto_item_append_text( item, " [2 bits Status Vector Chunk]: %s", wmem_strbuf_get_str(status));
i += chunk_count;
}
}
offset += 2;
}
recv_delta_tree = proto_tree_add_subtree_format( fci_tree, tvb, offset, 0, ett_ssrc, NULL, "Recv Delta" );
for (i = 0; i < pkt_count; i++ )
{
if ( delta_array[i] == 1 )
{
guint32 delta;
item = proto_tree_add_item_ret_uint( recv_delta_tree, hf_rtcp_rtpfb_transport_cc_fci_recv_delta_1_byte, tvb, offset, 1, ENC_BIG_ENDIAN, &delta );
proto_item_append_text( item, " Small Delta: [seq: %d] %lf ms", pkt_seq_array[i], delta*250.0/1000);
offset += 1;
}
else if ( delta_array[i] == 2 )
{
gint16 delta;
item = proto_tree_add_item( recv_delta_tree, hf_rtcp_rtpfb_transport_cc_fci_recv_delta_2_bytes, tvb, offset, 2, ENC_BIG_ENDIAN);
delta = tvb_get_ntohs(tvb, offset);
if ( delta < 0 )
{
proto_item_append_text( item, " Negative Delta: [seq: %d] %lf ms", pkt_seq_array[i], delta*250.0/1000 );
}
else
{
proto_item_append_text( item, " Large Delta: [seq: %d] %lf ms", pkt_seq_array[i], delta*250.0/1000 );
}
offset += 2;
}
else
{
break;
}
}
padding_length = fci_length - (offset - padding_length);
if ( padding_length > 0 )
{
proto_tree_add_item( recv_delta_tree, hf_rtcp_rtpfb_transport_cc_fci_recv_delta_padding, tvb, offset, padding_length, ENC_BIG_ENDIAN );
offset += padding_length;
}
delta_array = NULL;
pkt_seq_array = NULL;
return offset;
}

maybe_t<size_t> read_unquoted_escape(const wchar_t *input, wcstring *result, bool allow_incomplete,
bool unescape_special) {
assert(input[0] == L'\\' && "Not an escape");
maybe_t<wchar_t> result_char_or_none = none();
bool errored = false;
size_t in_pos = 1;                          
std::string byte_buff;
while (true) {
const wchar_t c = input[in_pos++];
switch (c) {
case L'\0': {
assert(in_pos > 0);
in_pos--;
if (!allow_incomplete) errored = true;
break;
}
case L'0':
case L'1':
case L'2':
case L'3':
case L'4':
case L'5':
case L'6':
case L'7':
case L'u':
case L'U':
case L'x':
case L'X': {
long long res = 0;
size_t chars = 2;
int base = 16;
bool byte_literal = false;
wchar_t max_val = ASCII_MAX;
switch (c) {
case L'u': {
chars = 4;
max_val = UCS2_MAX;
break;
}
case L'U': {
chars = 8;
max_val = WCHAR_MAX;
if (0x10FFFF < max_val) max_val = static_cast<wchar_t>(0x10FFFF);
break;
}
case L'x':
case L'X': {
byte_literal = true;
max_val = BYTE_MAX;
break;
}
default: {
base = 8;
chars = 3;
assert(in_pos > 0);
in_pos--;
break;
}
}
for (size_t i = 0; i < chars; i++) {
long d = convert_digit(input[in_pos], base);
if (d < 0) {
if (i == 0) errored = true;
break;
}
res = (res * base) + d;
in_pos++;
}
if (!errored && res <= max_val) {
if (byte_literal) {
byte_buff.push_back(static_cast<char>(res));
result_char_or_none = none();
if (input[in_pos] == L'\\'
&& (input[in_pos + 1] == L'X' || input[in_pos + 1] == L'x')) {
in_pos++;
continue;
}
} else {
result_char_or_none = static_cast<wchar_t>(res);
}
} else {
errored = true;
}
break;
}
case L'a': {
result_char_or_none = L'\a';
break;
}
case L'b': {
result_char_or_none = L'\b';
break;
}
case L'c': {
const wchar_t sequence_char = input[in_pos++];
if (sequence_char >= L'a' && sequence_char <= (L'a' + 32)) {
result_char_or_none = sequence_char - L'a' + 1;
} else if (sequence_char >= L'A' && sequence_char <= (L'A' + 32)) {
result_char_or_none = sequence_char - L'A' + 1;
} else {
errored = true;
}
break;
}
case L'e': {
result_char_or_none = L'\x1B';
break;
}
case L'f': {
result_char_or_none = L'\f';
break;
}
case L'n': {
result_char_or_none = L'\n';
break;
}
case L'r': {
result_char_or_none = L'\r';
break;
}
case L't': {
result_char_or_none = L'\t';
break;
}
case L'v': {
result_char_or_none = L'\v';
break;
}
case L'\n': {
result_char_or_none = none();
break;
}
default: {
if (unescape_special) result->push_back(INTERNAL_SEPARATOR);
result_char_or_none = c;
break;
}
}
if (errored) return none();
if (!byte_buff.empty()) {
result->append(str2wcstring(byte_buff));
}
break;
}
if (result_char_or_none.has_value()) {
result->push_back(*result_char_or_none);
}
return in_pos;
}

