if (heredoc_concat_len > 0)
{
ga_concat(&heredoc_ga, theline);
ga_concat(&heredoc_ga, (char_u *)"\n");
p = vim_strsave((char_u *)"");
}
else
{
p = vim_strsave(theline);
}
if (p == NULL)
goto theend;
((char_u **)(newlines->ga_data))[newlines->ga_len++] = p;
while (sourcing_lnum_off-- > 0)
((char_u **)(newlines->ga_data))[newlines->ga_len++] = NULL;
if (line_arg != NULL && *line_arg == NUL)
line_arg = NULL;
}
if (!did_emsg)
ret = OK;
theend:
vim_free(skip_until);
vim_free(heredoc_trimmed);
vim_free(heredoc_ga.ga_data);
need_wait_return |= saved_wait_return;
return ret;
}

const char* skip_over_scopes(const char* src, const char* end) {
size_t level = 0;
bool in_squote = false;
bool in_dquote = false;
while (*src) {
if (end && src >= end) break;
if (*src == '\\') {
++ src;         }
else if (*src == '"') {
in_dquote = ! in_dquote;
}
else if (*src == '\'') {
in_squote = ! in_squote;
}
else if (in_dquote || in_squote) {
}
else if (const char* pos = start(src)) {
++ level;           src = pos - 1;         }
else if (const char* final = stop(src)) {
if (level > 0) -- level;
else return final;
src = final - 1;
}
++ src;
}
return 0;
}

