void ntlm_print_av_pair_list(NTLM_AV_PAIR* pAvPairList, size_t cbAvPairList)
{
size_t cbAvPair = cbAvPairList;
NTLM_AV_PAIR* pAvPair = pAvPairList;
if (!ntlm_av_pair_check(pAvPair, cbAvPair))
return;
WLog_INFO(TAG, "AV_PAIRs =");
while (pAvPair && ntlm_av_pair_get_id(pAvPair) != MsvAvEOL)
{
WLog_INFO(TAG, "\t%s AvId: %" PRIu16 " AvLen: %" PRIu16 "",
AV_PAIR_STRINGS[ntlm_av_pair_get_id(pAvPair)], ntlm_av_pair_get_id(pAvPair),
ntlm_av_pair_get_len(pAvPair));
winpr_HexDump(TAG, WLOG_INFO, ntlm_av_pair_get_value_pointer(pAvPair),
ntlm_av_pair_get_len(pAvPair));
pAvPair = ntlm_av_pair_next(pAvPair, &cbAvPair);
}
}

static gboolean
check_permission (GVfsBackendAdmin *self,
GVfsJob *job)
{
GVfsJobDBus *dbus_job = G_VFS_JOB_DBUS (job);
GError *error = NULL;
GDBusMethodInvocation *invocation;
GDBusConnection *connection;
GCredentials *credentials;
pid_t pid;
uid_t uid;
PolkitSubject *subject;
PolkitAuthorizationResult *result;
gboolean is_authorized;
invocation = dbus_job->invocation;
connection = g_dbus_method_invocation_get_connection (invocation);
credentials = g_dbus_connection_get_peer_credentials (connection);
pid = g_credentials_get_unix_pid (credentials, &error);
if (error != NULL)
{
g_vfs_job_failed_from_error (job, error);
g_error_free (error);
return FALSE;
}
uid = g_credentials_get_unix_user (credentials, &error);
if (error != NULL)
{
g_vfs_job_failed_from_error (job, error);
g_error_free (error);
return FALSE;
}
g_mutex_lock (&self->polkit_mutex);
subject = polkit_unix_process_new_for_owner (pid, 0, uid);
result = polkit_authority_check_authorization_sync (self->authority,
subject,
"org.gtk.vfs.file-operations",
NULL, POLKIT_CHECK_AUTHORIZATION_FLAGS_ALLOW_USER_INTERACTION,
NULL, &error);
g_object_unref (subject);
g_mutex_unlock (&self->polkit_mutex);
if (error != NULL)
{
g_vfs_job_failed_from_error (job, error);
g_error_free (error);
return FALSE;
}
is_authorized = polkit_authorization_result_get_is_authorized (result) ||
polkit_authorization_result_get_is_challenge (result);
g_object_unref (result);
if (!is_authorized)
g_vfs_job_failed_literal (job, G_IO_ERROR, G_IO_ERROR_PERMISSION_DENIED,
_("Permission denied"));
return is_authorized;
}

