char *RootdExpandPathName(const char *name)
{
const char *patbuf = name;
while (*patbuf == ' ')
patbuf++;
for (const char *p = patbuf; *p; p++)
if (strchr(shellMeta, *p))
goto needshell;
return strdup(name);
needshell:
char escPatbuf[kMAXPATHLEN];
EscChar(patbuf, escPatbuf, sizeof(escPatbuf), shellStuff, shellEscape);
char cmd[kMAXPATHLEN];
#ifdef __hpux
strlcpy(cmd, "/bin/echo ", sizeof(cmd));
#else
strlcpy(cmd, "echo ", sizeof(cmd));
#endif
if (escPatbuf[0] == '~') {
const char *hd;
if (escPatbuf[1] != '\0' && escPatbuf[1] != '/') {
char uname[70], *p, *q;
for (p = &escPatbuf[1], q = uname; *p && *p !='/';)
*q++ = *p++;
*q = '\0';
hd = HomeDirectory(uname);
if (hd == 0)
strcat(cmd, escPatbuf);
else {
strcat(cmd, hd);
strcat(cmd, p);
}
} else {
hd = HomeDirectory(0);
if (hd == 0) {
Error(ErrSys, kErrFatal, "RootdExpandPathName: no home directory");
return 0;
}
strcat(cmd, hd);
strcat(cmd, &escPatbuf[1]);
}
} else
strcat(cmd, escPatbuf);
FILE *pf;
if ((pf = ::popen(&cmd[0], "r")) == 0) {
Error(ErrSys, kErrFatal, "RootdExpandPathName: error in popen(%s)", cmd);
return 0;
}
char expPatbuf[kMAXPATHLEN];
int  ch, i, cnt = 0;
again:
for (i = 0, ch = fgetc(pf); ch != EOF && ch != ' ' && ch != '\n'; i++, ch = fgetc(pf)) {
expPatbuf[i] = ch;
cnt++;
}
if (cnt == 0 && ch == EOF) goto again;
expPatbuf[cnt] = '\0';
while (ch != EOF) {
ch = fgetc(pf);
if (ch == ' ' || ch == '\t') {
::pclose(pf);
Error(ErrFatal, kErrFatal, "RootdExpandPathName: expression ambigous");
return 0;
}
}
::pclose(pf);
return strdup(expPatbuf);
}

char *RootdExpandPathName(const char *name)
{
const char *patbuf = name;
while (*patbuf == ' ')
patbuf++;
for (const char *p = patbuf; *p; p++)
if (strchr(shellMeta, *p))
goto needshell;
return strdup(name);
needshell:
char escPatbuf[kMAXPATHLEN];
EscChar(patbuf, escPatbuf, sizeof(escPatbuf), shellStuff, shellEscape);
char cmd[kMAXPATHLEN];
#ifdef __hpux
strlcpy(cmd, "/bin/echo ", sizeof(cmd));
#else
strlcpy(cmd, "echo ", sizeof(cmd));
#endif
if (escPatbuf[0] == '~') {
const char *hd;
if (escPatbuf[1] != '\0' && escPatbuf[1] != '/') {
char uname[70], *p, *q;
for (p = &escPatbuf[1], q = uname; *p && *p !='/';)
*q++ = *p++;
*q = '\0';
hd = HomeDirectory(uname);
if (hd == 0)
strcat(cmd, escPatbuf);
else {
strcat(cmd, hd);
strcat(cmd, p);
}
} else {
hd = HomeDirectory(0);
if (hd == 0) {
Error(ErrSys, kErrFatal, "RootdExpandPathName: no home directory");
return 0;
}
strcat(cmd, hd);
strcat(cmd, &escPatbuf[1]);
}
} else
strcat(cmd, escPatbuf);
FILE *pf;
if ((pf = ::popen(&cmd[0], "r")) == 0) {
Error(ErrSys, kErrFatal, "RootdExpandPathName: error in popen(%s)", cmd);
return 0;
}
char expPatbuf[kMAXPATHLEN];
int  ch, i, cnt = 0;
again:
for (i = 0, ch = fgetc(pf); ch != EOF && ch != ' ' && ch != '\n'; i++, ch = fgetc(pf)) {
expPatbuf[i] = ch;
cnt++;
}
if (cnt == 0 && ch == EOF) goto again;
expPatbuf[cnt] = '\0';
while (ch != EOF) {
ch = fgetc(pf);
if (ch == ' ' || ch == '\t') {
::pclose(pf);
Error(ErrFatal, kErrFatal, "RootdExpandPathName: expression ambigous");
return 0;
}
}
::pclose(pf);
return strdup(expPatbuf);
}

LOCAL int populate_description_metadata(MMDB_s *mmdb, MMDB_s *metadata_db,
MMDB_entry_s *metadata_start)
{
MMDB_entry_data_s entry_data;
const char *path[] = { "description", NULL };
int status = MMDB_aget_value(metadata_start, &entry_data, path);
if (MMDB_SUCCESS != status) {
return status;
}
if (MMDB_DATA_TYPE_MAP != entry_data.type) {
DEBUG_MSGF("Unexpected entry_data type: %d", entry_data.type);
return MMDB_INVALID_METADATA_ERROR;
}
MMDB_entry_s map_start = {
.mmdb   = metadata_db,
.offset = entry_data.offset
};
MMDB_entry_data_list_s *member;
status = MMDB_get_entry_data_list(&map_start, &member);
if (MMDB_SUCCESS != status) {
DEBUG_MSGF(
"MMDB_get_entry_data_list failed while populating description."
" status = %d (%s)", status, MMDB_strerror(status));
return status;
}
MMDB_entry_data_list_s *first_member = member;
uint32_t map_size = member->entry_data.data_size;
mmdb->metadata.description.count = 0;
if (0 == map_size) {
mmdb->metadata.description.descriptions = NULL;
goto cleanup;
}
MAYBE_CHECK_SIZE_OVERFLOW(map_size, SIZE_MAX / sizeof(MMDB_description_s *),
MMDB_INVALID_METADATA_ERROR);
mmdb->metadata.description.descriptions =
malloc(map_size * sizeof(MMDB_description_s *));
if (NULL == mmdb->metadata.description.descriptions) {
status = MMDB_OUT_OF_MEMORY_ERROR;
goto cleanup;
}
for (uint32_t i = 0; i < map_size; i++) {
mmdb->metadata.description.descriptions[i] =
malloc(sizeof(MMDB_description_s));
if (NULL == mmdb->metadata.description.descriptions[i]) {
status = MMDB_OUT_OF_MEMORY_ERROR;
goto cleanup;
}
mmdb->metadata.description.count = i + 1;
mmdb->metadata.description.descriptions[i]->language = NULL;
mmdb->metadata.description.descriptions[i]->description = NULL;
member = member->next;
if (MMDB_DATA_TYPE_UTF8_STRING != member->entry_data.type) {
status = MMDB_INVALID_METADATA_ERROR;
goto cleanup;
}
mmdb->metadata.description.descriptions[i]->language =
mmdb_strndup((char *)member->entry_data.utf8_string,
member->entry_data.data_size);
if (NULL == mmdb->metadata.description.descriptions[i]->language) {
status = MMDB_OUT_OF_MEMORY_ERROR;
goto cleanup;
}
member = member->next;
if (MMDB_DATA_TYPE_UTF8_STRING != member->entry_data.type) {
status = MMDB_INVALID_METADATA_ERROR;
goto cleanup;
}
mmdb->metadata.description.descriptions[i]->description =
mmdb_strndup((char *)member->entry_data.utf8_string,
member->entry_data.data_size);
if (NULL == mmdb->metadata.description.descriptions[i]->description) {
status = MMDB_OUT_OF_MEMORY_ERROR;
goto cleanup;
}
}
cleanup:
MMDB_free_entry_data_list(first_member);
return status;
}

static int
lmp_print_data_link_subobjs(netdissect_options *ndo, const u_char *obj_tptr,
int total_subobj_len, int offset)
{
int hexdump = FALSE;
int subobj_type, subobj_len;
union { 
float f;
uint32_t i;
} bw;
while (total_subobj_len > 0 && hexdump == FALSE ) {
subobj_type = EXTRACT_8BITS(obj_tptr + offset);
subobj_len  = EXTRACT_8BITS(obj_tptr + offset + 1);
ND_PRINT((ndo, "\n\t    Subobject, Type: %s (%u), Length: %u",
tok2str(lmp_data_link_subobj,
"Unknown",
subobj_type),
subobj_type,
subobj_len));
if (subobj_len < 4) {
ND_PRINT((ndo, " (too short)"));
break;
}
if ((subobj_len % 4) != 0) {
ND_PRINT((ndo, " (not a multiple of 4)"));
break;
}
if (total_subobj_len < subobj_len) {
ND_PRINT((ndo, " (goes past the end of the object)"));
break;
}
switch(subobj_type) {
case INT_SWITCHING_TYPE_SUBOBJ:
ND_PRINT((ndo, "\n\t      Switching Type: %s (%u)",
tok2str(gmpls_switch_cap_values,
"Unknown",
EXTRACT_8BITS(obj_tptr + offset + 2)),
EXTRACT_8BITS(obj_tptr + offset + 2)));
ND_PRINT((ndo, "\n\t      Encoding Type: %s (%u)",
tok2str(gmpls_encoding_values,
"Unknown",
EXTRACT_8BITS(obj_tptr + offset + 3)),
EXTRACT_8BITS(obj_tptr + offset + 3)));
ND_TCHECK_32BITS(obj_tptr + offset + 4);
bw.i = EXTRACT_32BITS(obj_tptr+offset+4);
ND_PRINT((ndo, "\n\t      Min Reservable Bandwidth: %.3f Mbps",
bw.f*8/1000000));
bw.i = EXTRACT_32BITS(obj_tptr+offset+8);
ND_PRINT((ndo, "\n\t      Max Reservable Bandwidth: %.3f Mbps",
bw.f*8/1000000));
break;
case WAVELENGTH_SUBOBJ:
ND_PRINT((ndo, "\n\t      Wavelength: %u",
EXTRACT_32BITS(obj_tptr+offset+4)));
break;
default:
hexdump=TRUE;
break;
}
total_subobj_len-=subobj_len;
offset+=subobj_len;
}
return (hexdump);
trunc:
return -1;
}

static int atm_tc_enqueue(struct sk_buff *skb, struct Qdisc *sch,
struct sk_buff **to_free)
{
struct atm_qdisc_data *p = qdisc_priv(sch);
struct atm_flow_data *flow;
struct tcf_result res;
int result;
int ret = NET_XMIT_SUCCESS | __NET_XMIT_BYPASS;
pr_debug("atm_tc_enqueue(skb %p,sch %p,[qdisc %p])\n", skb, sch, p);
result = TC_ACT_OK;
flow = NULL;
if (TC_H_MAJ(skb->priority) != sch->handle ||
!(flow = (struct atm_flow_data *)atm_tc_find(sch, skb->priority))) {
struct tcf_proto *fl;
list_for_each_entry(flow, &p->flows, list) {
fl = rcu_dereference_bh(flow->filter_list);
if (fl) {
result = tcf_classify(skb, NULL, fl, &res, true);
if (result < 0)
continue;
flow = (struct atm_flow_data *)res.class;
if (!flow)
flow = lookup_flow(sch, res.classid);
goto done;
}
}
flow = NULL;
done:
;
}
if (!flow) {
flow = &p->link;
} else {
if (flow->vcc)
ATM_SKB(skb)->atm_options = flow->vcc->atm_options;
#ifdef CONFIG_NET_CLS_ACT
switch (result) {
case TC_ACT_QUEUED:
case TC_ACT_STOLEN:
case TC_ACT_TRAP:
__qdisc_drop(skb, to_free);
return NET_XMIT_SUCCESS | __NET_XMIT_STOLEN;
case TC_ACT_SHOT:
__qdisc_drop(skb, to_free);
goto drop;
case TC_ACT_RECLASSIFY:
if (flow->excess)
flow = flow->excess;
else
ATM_SKB(skb)->atm_options |= ATM_ATMOPT_CLP;
break;
}
#endif
}
ret = qdisc_enqueue(skb, flow->q, to_free);
if (ret != NET_XMIT_SUCCESS) {
drop: __maybe_unused
if (net_xmit_drop_count(ret)) {
qdisc_qstats_drop(sch);
if (flow)
flow->qstats.drops++;
}
return ret;
}
if (flow == &p->link) {
sch->q.qlen++;
return NET_XMIT_SUCCESS;
}
tasklet_schedule(&p->task);
return NET_XMIT_SUCCESS | __NET_XMIT_BYPASS;
}

