fail:
drm_free_large(temp);
return ret;
}

static int crypto_ccm_auth(struct aead_request *req, struct scatterlist *plain,
unsigned int cryptlen)
{
struct crypto_ccm_req_priv_ctx *pctx = crypto_ccm_reqctx(req);
struct crypto_aead *aead = crypto_aead_reqtfm(req);
struct crypto_ccm_ctx *ctx = crypto_aead_ctx(aead);
AHASH_REQUEST_ON_STACK(ahreq, ctx->mac);
unsigned int assoclen = req->assoclen;
struct scatterlist sg[3];
u8 odata[16];
u8 idata[16];
int ilen, err;
err = format_input(odata, req, cryptlen);
if (err)
goto out;
sg_init_table(sg, 3);
sg_set_buf(&sg[0], odata, 16);
if (assoclen) {
ilen = format_adata(idata, assoclen);
sg_set_buf(&sg[1], idata, ilen);
sg_chain(sg, 3, req->src);
} else {
ilen = 0;
sg_chain(sg, 2, req->src);
}
ahash_request_set_tfm(ahreq, ctx->mac);
ahash_request_set_callback(ahreq, pctx->flags, NULL, NULL);
ahash_request_set_crypt(ahreq, sg, NULL, assoclen + ilen + 16);
err = crypto_ahash_init(ahreq);
if (err)
goto out;
err = crypto_ahash_update(ahreq);
if (err)
goto out;
ilen = 16 - (assoclen + ilen) % 16;
if (ilen < 16) {
memset(idata, 0, ilen);
sg_init_table(sg, 2);
sg_set_buf(&sg[0], idata, ilen);
if (plain)
sg_chain(sg, 2, plain);
plain = sg;
cryptlen += ilen;
}
ahash_request_set_crypt(ahreq, plain, pctx->odata, cryptlen);
err = crypto_ahash_finup(ahreq);
out:
return err;
}

bool parse(char* ptr)
{
CV_Assert( fs != 0 );
std::string key, key2, type_name;
int tag_type = 0;
bool ok = false;
ptr = skipSpaces( ptr, CV_XML_INSIDE_TAG );
if( memcmp( ptr, "<?xml", 5 ) != 0 )              CV_PARSE_ERROR_CPP( "Valid XML should start with \'<?xml ...?>\'" );
ptr = parseTag( ptr, key, type_name, tag_type );
FileNode root_collection(fs->getFS(), 0, 0);
while( ptr && *ptr != '\0' )
{
ptr = skipSpaces( ptr, 0 );
if( *ptr != '\0' )
{
ptr = parseTag( ptr, key, type_name, tag_type );
if( tag_type != CV_XML_OPENING_TAG || key != "opencv_storage" )
CV_PARSE_ERROR_CPP( "<opencv_storage> tag is missing" );
FileNode root = fs->addNode(root_collection, std::string(), FileNode::MAP, 0);
ptr = parseValue( ptr, root );
ptr = parseTag( ptr, key2, type_name, tag_type );
if( tag_type != CV_XML_CLOSING_TAG || key != key2 )
CV_PARSE_ERROR_CPP( "</opencv_storage> tag is missing" );
ptr = skipSpaces( ptr, 0 );
ok = true;
}
}
CV_Assert( fs->eof() );
return ok;
}

static int
md_is_link_label(MD_CTX* ctx, const MD_LINE* lines, int n_lines, OFF beg,
OFF* p_end, int* p_beg_line_index, int* p_end_line_index,
OFF* p_contents_beg, OFF* p_contents_end)
{
OFF off = beg;
OFF contents_beg = 0;
OFF contents_end = 0;
int line_index = 0;
int len = 0;
if(CH(off) != _T('['))
return FALSE;
off++;
while(line_index < n_lines) {
OFF line_end = lines[line_index].end;
while(off < line_end) {
if(CH(off) == _T('\\')  &&  off+1 < ctx->size  &&  (ISPUNCT(off+1) || ISNEWLINE(off+1))) {
if(contents_end == 0)
contents_beg = off;
contents_end = off + 2;
off += 2;
} else if(CH(off) == _T('[')) {
return FALSE;
} else if(CH(off) == _T(']')) {
if(contents_beg < contents_end) {
*p_contents_beg = contents_beg;
*p_contents_end = contents_end;
*p_end = off+1;
*p_end_line_index = line_index;
return TRUE;
} else {
return FALSE;
}
} else {
int codepoint;
SZ char_size;
codepoint = md_decode_unicode(ctx->text, off, ctx->size, &char_size);
if(!ISUNICODEWHITESPACE_(codepoint)) {
if(contents_end == 0) {
contents_beg = off;
*p_beg_line_index = line_index;
}
contents_end = off + char_size;
}
off += char_size;
}
len++;
if(len > 999)
return FALSE;
}
line_index++;
len++;
off = lines[line_index].beg;
}
return FALSE;
}

static PyObject* getfactor(PyObject *self, PyObject *args)
{
PyObject *F;
cholmod_factor *Lf;
cholmod_sparse *Ls;
#if PY_MAJOR_VERSION >= 3
const char *descr;
#else
char *descr;
#endif
if (!set_options()) return NULL;
if (!PyArg_ParseTuple(args, "O", &F)) return NULL;
#if PY_MAJOR_VERSION >= 3
if (!PyCapsule_CheckExact(F) || !(descr = PyCapsule_GetName(F)))
err_CO("F");
if (strncmp(descr, "CHOLMOD FACTOR", 14))
PY_ERR_TYPE("F is not a CHOLMOD factor");
Lf = (cholmod_factor *) PyCapsule_GetPointer(F, descr);
#else
if (!PyCObject_Check(F)) err_CO("F");
descr = PyCObject_GetDesc(F);
if (!descr || strncmp(descr, "CHOLMOD FACTOR", 14))
PY_ERR_TYPE("F is not a CHOLMOD factor");
Lf = (cholmod_factor *) PyCObject_AsVoidPtr(F);
#endif
if (Lf->xtype == CHOLMOD_PATTERN)
PY_ERR(PyExc_ValueError, "F must be a numeric Cholesky factor");
if (!(Ls = CHOL(factor_to_sparse)(Lf, &Common)))
return PyErr_NoMemory();
spmatrix *ret = SpMatrix_New(Ls->nrow, Ls->ncol, Ls->nzmax,
(Ls->xtype == CHOLMOD_REAL ? DOUBLE : COMPLEX));
if (!ret) {
CHOL(free_sparse)(&Ls, &Common);
return NULL;
}
memcpy(SP_COL(ret), Ls->p, (Ls->ncol+1)*sizeof(int_t));
memcpy(SP_ROW(ret), Ls->i, (Ls->nzmax)*sizeof(int_t));
memcpy(SP_VAL(ret), Ls->x, (Ls->nzmax)*E_SIZE[SP_ID(ret)]);
CHOL(free_sparse)(&Ls, &Common);
return (PyObject *)ret;
}

