private int
mcopy(struct magic_set *ms, union VALUETYPE *p, int type, int indir,
const unsigned char *s, uint32_t offset, size_t nbytes, struct magic *m)
{
if (indir == 0) {
switch (type) {
case FILE_SEARCH:
ms->search.s = RCAST(const char *, s) + offset;
ms->search.s_len = nbytes - offset;
ms->search.offset = offset;
return 0;
case FILE_REGEX: {
const char *b;
const char *c;
const char *last;
const char *buf;
const char *end;
size_t lines, linecnt, bytecnt;
linecnt = m->str_range;
bytecnt = linecnt * 80;
if (bytecnt == 0) {
bytecnt = 8192;
}
if (bytecnt > nbytes) {
bytecnt = nbytes;
}
if (s == NULL) {
ms->search.s_len = 0;
ms->search.s = NULL;
return 0;
}
buf = RCAST(const char *, s) + offset;
end = last = RCAST(const char *, s) + bytecnt;
for (lines = linecnt, b = buf; lines && b < end &&
((b = CAST(const char *,
memchr(c = b, '\n', CAST(size_t, (end - b)))))
|| (b = CAST(const char *,
memchr(c, '\r', CAST(size_t, (end - c))))));
lines--, b++) {
last = b;
if (b[0] == '\r' && b[1] == '\n')
b++;
}
if (lines)
last = RCAST(const char *, s) + bytecnt;
ms->search.s = buf;
ms->search.s_len = last - buf;
ms->search.offset = offset;
ms->search.rm_len = 0;
return 0;
}
case FILE_BESTRING16:
case FILE_LESTRING16: {
const unsigned char *src = s + offset;
const unsigned char *esrc = s + nbytes;
char *dst = p->s;
char *edst = &p->s[sizeof(p->s) - 1];
if (type == FILE_BESTRING16)
src++;
if (offset >= nbytes) {
file_magerror(ms, "invalid offset %u in mcopy()",
offset);
return -1;
}
for (; src < esrc; src += 2, dst++) {
if (dst < edst)
*dst = *src;
else
break;
if (*dst == '\0') {
if (type == FILE_BESTRING16 ?
*(src - 1) != '\0' :
*(src + 1) != '\0')
*dst = ' ';
}
}
*edst = '\0';
return 0;
}
case FILE_STRING:
case FILE_PSTRING:
default:
break;
}
}
if (offset >= nbytes) {
(void)memset(p, '\0', sizeof(*p));
return 0;
}
if (nbytes - offset < sizeof(*p))
nbytes = nbytes - offset;
else
nbytes = sizeof(*p);
(void)memcpy(p, s + offset, nbytes);
if (nbytes < sizeof(*p))
(void)memset(((char *)(void *)p) + nbytes, '\0',
sizeof(*p) - nbytes);
return 0;
}

int VvcVpsUnit::deserialize()
{
int rez = VvcUnit::deserialize();
if (rez)
return rez;
try
{
vps_id = m_reader.getBits(4);
vps_max_layers = m_reader.getBits(6) + 1;
vector<vector<bool>> vps_direct_ref_layer_flag(vps_max_layers, vector<bool>(vps_max_layers));
vps_max_sublayers = m_reader.getBits(3) + 1;
bool vps_default_ptl_dpb_hrd_max_tid_flag =
(vps_max_layers > 1 && vps_max_sublayers > 1) ? m_reader.getBit() : 1;
int vps_all_independent_layers_flag = (vps_max_layers > 1) ? m_reader.getBit() : 1;
for (int i = 0; i < vps_max_layers; i++)
{
m_reader.skipBits(6);              if (i > 0 && !vps_all_independent_layers_flag)
{
if (!m_reader.getBit())                  {
bool vps_max_tid_ref_present_flag = m_reader.getBit();
for (int j = 0; j < i; j++)
{
vps_direct_ref_layer_flag[i][j] = m_reader.getBit();
if (vps_max_tid_ref_present_flag && vps_direct_ref_layer_flag[i][j])
m_reader.skipBits(3);                      }
}
}
}
bool vps_each_layer_is_an_ols_flag = 1;
int vps_num_ptls = 1;
int vps_ols_mode_idc = 2;
int olsModeIdc = 4;
int TotalNumOlss = vps_max_layers;
int vps_num_output_layer_sets = 0;
vector<vector<bool>> vps_ols_output_layer_flag;
if (vps_max_layers > 1)
{
vps_each_layer_is_an_ols_flag = (vps_all_independent_layers_flag ? m_reader.getBit() : 0);
if (!vps_each_layer_is_an_ols_flag)
{
if (!vps_all_independent_layers_flag)
vps_ols_mode_idc = m_reader.getBits(2);
olsModeIdc = vps_ols_mode_idc;
if (vps_ols_mode_idc == 2)
{
vps_num_output_layer_sets = m_reader.getBits(8) + 2;
vps_ols_output_layer_flag.resize(vps_num_output_layer_sets, vector<bool>(vps_max_layers));
if (olsModeIdc == 2)
TotalNumOlss = vps_num_output_layer_sets;
for (int i = 1; i < vps_num_output_layer_sets; i++)
for (int j = 0; j < vps_max_layers; j++) vps_ols_output_layer_flag[i][j] = m_reader.getBit();
}
}
vps_num_ptls = m_reader.getBits(8) + 1;
}
vector<bool> vps_pt_present_flag(vps_num_ptls, true);
vector<int> vps_ptl_max_tid(vps_num_ptls, vps_max_sublayers - 1);
if (!vps_default_ptl_dpb_hrd_max_tid_flag)
vps_ptl_max_tid[0] = m_reader.getBits(3);
for (int i = 1; i < vps_num_ptls; i++)
{
vps_pt_present_flag[i] = m_reader.getBit();
if (!vps_default_ptl_dpb_hrd_max_tid_flag)
vps_ptl_max_tid[i] = m_reader.getBits(3);
}
m_reader.skipBits(m_reader.getBitsLeft() % 8);  
for (int i = 0; i < vps_num_ptls; i++)
if (profile_tier_level(vps_pt_present_flag[i], vps_ptl_max_tid[i]) != 0)
return 1;
for (int i = 0; i < TotalNumOlss; i++)
if (vps_num_ptls > 1 && vps_num_ptls != TotalNumOlss)
m_reader.skipBits(8);  
if (!vps_each_layer_is_an_ols_flag)
{
vector<vector<bool>> layerIncludedInOlsFlag;
if (vps_ols_mode_idc == 2)
{
layerIncludedInOlsFlag.resize(TotalNumOlss, vector<bool>(vps_max_layers));
vector<vector<bool>> dependencyFlag(vps_max_layers, vector<bool>(vps_max_layers));
vector<vector<bool>> ReferenceLayerIdx(vps_max_layers, vector<bool>(vps_max_layers));
vector<vector<bool>> OutputLayerIdx(TotalNumOlss, vector<bool>(vps_max_layers));
vector<int> NumRefLayers(vps_max_layers, 0);
for (int i = 0; i < vps_max_layers; i++)
{
for (int j = 0; j < vps_max_layers; j++)
{
dependencyFlag[i][j] = vps_direct_ref_layer_flag[i][j];
for (int k = 0; k < i; k++)
if (vps_direct_ref_layer_flag[i][k] && dependencyFlag[k][j])
dependencyFlag[i][j] = 1;
}
}
int r = 0;
for (int i = 0; i < vps_max_layers; i++)
{
for (int j = 0; j < vps_max_layers; j++)
{
if (dependencyFlag[i][j])
ReferenceLayerIdx[i][r++] = j;
}
NumRefLayers[i] = r;
}
for (int i = 1; i < TotalNumOlss; i++)
{
for (int j = 0; j < vps_max_layers; j++) layerIncludedInOlsFlag[i][j] = 0;
int j = 0;
for (int k = 0; k < vps_max_layers; k++)
{
if (vps_ols_output_layer_flag[i][k])
{
layerIncludedInOlsFlag[i][k] = 1;
OutputLayerIdx[i][j++] = k;
}
}
for (int l = 0; l < j; l++)
{
int idx = OutputLayerIdx[i][l];
for (int k = 0; k < NumRefLayers[idx]; k++)
{
if (!layerIncludedInOlsFlag[i][ReferenceLayerIdx[idx][k]])
layerIncludedInOlsFlag[i][ReferenceLayerIdx[idx][k]] = 1;
}
}
}
}
unsigned NumMultiLayerOlss = 0;
for (int i = 1; i < TotalNumOlss; i++)
{
int NumLayersInOls = 0;
if (vps_each_layer_is_an_ols_flag)
NumLayersInOls = 1;
else if (vps_ols_mode_idc == 0 || vps_ols_mode_idc == 1)
NumLayersInOls = i + 1;
else if (vps_ols_mode_idc == 2)
{
int j = 0;
for (int k = 0; k < vps_max_layers; k++) j += layerIncludedInOlsFlag[i][k];
NumLayersInOls = j;
}
if (NumLayersInOls > 1)
NumMultiLayerOlss++;
}
unsigned vps_num_dpb_params = extractUEGolombCode() + 1;
if (vps_num_dpb_params >= NumMultiLayerOlss)
return 1;
unsigned VpsNumDpbParams = (vps_each_layer_is_an_ols_flag ? 0 : vps_num_dpb_params);
bool vps_sublayer_dpb_params_present_flag = (vps_max_sublayers > 1) ? m_reader.getBit() : 0;
for (size_t i = 0; i < VpsNumDpbParams; i++)
{
int vps_dpb_max_tid =
(vps_default_ptl_dpb_hrd_max_tid_flag ? vps_max_sublayers - 1 : m_reader.getBits(3));
if (dpb_parameters(vps_dpb_max_tid, vps_sublayer_dpb_params_present_flag))
return 1;
}
for (size_t i = 0; i < NumMultiLayerOlss; i++)
{
extractUEGolombCode();                          extractUEGolombCode();                          m_reader.skipBits(2);                           if (extractUEGolombCode() > 2)                      return 1;
if (VpsNumDpbParams > 1 && VpsNumDpbParams != NumMultiLayerOlss)
{
if (extractUEGolombCode() >= VpsNumDpbParams)                          return 1;
}
}
if (m_reader.getBit())              {
if (general_timing_hrd_parameters(m_vps_hrd))
return 1;
bool vps_sublayer_cpb_params_present_flag = (vps_max_sublayers > 1) ? m_reader.getBit() : 0;
unsigned vps_num_ols_timing_hrd_params = extractUEGolombCode() + 1;
if (vps_num_ols_timing_hrd_params > NumMultiLayerOlss)
return 1;
for (size_t i = 0; i <= vps_num_ols_timing_hrd_params; i++)
{
int vps_hrd_max_tid =
(vps_default_ptl_dpb_hrd_max_tid_flag ? vps_max_sublayers - 1 : m_reader.getBits(3));
int firstSubLayer = vps_sublayer_cpb_params_present_flag ? 0 : vps_hrd_max_tid;
ols_timing_hrd_parameters(m_vps_hrd, firstSubLayer, vps_hrd_max_tid);
}
if (vps_num_ols_timing_hrd_params > 1 && vps_num_ols_timing_hrd_params != NumMultiLayerOlss)
{
for (size_t i = 0; i < NumMultiLayerOlss; i++)
{
if (extractUEGolombCode() >= vps_num_ols_timing_hrd_params)                              return 1;
}
}
}
}
return rez;
}
catch (VodCoreException& e)
{
(void)e;
return NOT_ENOUGH_BUFFER;
}
}

static int tls_decrypt_ticket(SSL *s, const unsigned char *etick,
int eticklen, const unsigned char *sess_id,
int sesslen, SSL_SESSION **psess)
{
SSL_SESSION *sess;
unsigned char *sdec;
const unsigned char *p;
int slen, mlen, renew_ticket = 0, ret = -1;
unsigned char tick_hmac[EVP_MAX_MD_SIZE];
HMAC_CTX *hctx = NULL;
EVP_CIPHER_CTX *ctx;
SSL_CTX *tctx = s->initial_ctx;
if (eticklen < 48)
return 2;
hctx = HMAC_CTX_new();
if (hctx == NULL)
return -2;
ctx = EVP_CIPHER_CTX_new();
if (ctx == NULL) {
ret = -2;
goto err;
}
if (tctx->tlsext_ticket_key_cb) {
unsigned char *nctick = (unsigned char *)etick;
int rv = tctx->tlsext_ticket_key_cb(s, nctick, nctick + 16,
ctx, hctx, 0);
if (rv < 0)
goto err;
if (rv == 0) {
ret = 2;
goto err;
}
if (rv == 2)
renew_ticket = 1;
} else {
if (memcmp(etick, tctx->tlsext_tick_key_name,
sizeof(tctx->tlsext_tick_key_name)) != 0) {
ret = 2;
goto err;
}
if (HMAC_Init_ex(hctx, tctx->tlsext_tick_hmac_key,
sizeof(tctx->tlsext_tick_hmac_key),
EVP_sha256(), NULL) <= 0
|| EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL,
tctx->tlsext_tick_aes_key,
etick + sizeof(tctx->tlsext_tick_key_name)) <=
0) {
goto err;
}
}
mlen = HMAC_size(hctx);
if (mlen < 0) {
goto err;
}
eticklen -= mlen;
if (HMAC_Update(hctx, etick, eticklen) <= 0
|| HMAC_Final(hctx, tick_hmac, NULL) <= 0) {
goto err;
}
HMAC_CTX_free(hctx);
if (CRYPTO_memcmp(tick_hmac, etick + eticklen, mlen)) {
EVP_CIPHER_CTX_free(ctx);
return 2;
}
p = etick + 16 + EVP_CIPHER_CTX_iv_length(ctx);
eticklen -= 16 + EVP_CIPHER_CTX_iv_length(ctx);
sdec = OPENSSL_malloc(eticklen);
if (sdec == NULL || EVP_DecryptUpdate(ctx, sdec, &slen, p, eticklen) <= 0) {
EVP_CIPHER_CTX_free(ctx);
OPENSSL_free(sdec);
return -1;
}
if (EVP_DecryptFinal(ctx, sdec + slen, &mlen) <= 0) {
EVP_CIPHER_CTX_free(ctx);
OPENSSL_free(sdec);
return 2;
}
slen += mlen;
EVP_CIPHER_CTX_free(ctx);
ctx = NULL;
p = sdec;
sess = d2i_SSL_SESSION(NULL, &p, slen);
OPENSSL_free(sdec);
if (sess) {
if (sesslen)
memcpy(sess->session_id, sess_id, sesslen);
sess->session_id_length = sesslen;
*psess = sess;
if (renew_ticket)
return 4;
else
return 3;
}
ERR_clear_error();
return 2;
err:
EVP_CIPHER_CTX_free(ctx);
HMAC_CTX_free(hctx);
return ret;
}

int cli_auth_pubkey() {
enum signature_type sigtype = DROPBEAR_SIGNATURE_NONE;
TRACE(("enter cli_auth_pubkey"))
#if DROPBEAR_CLI_AGENTFWD
if (!cli_opts.agent_keys_loaded) {
cli_load_agent_keys(cli_opts.privkeys);
cli_opts.agent_keys_loaded = 1;
TRACE(("cli_auth_pubkey: agent keys loaded"))
}
#endif
while (cli_opts.privkeys->first) {
sign_key * key = (sign_key*)cli_opts.privkeys->first->item;
if (cli_ses.server_sig_algs) {
#if DROPBEAR_RSA
if (key->type == DROPBEAR_SIGNKEY_RSA) {
#if DROPBEAR_RSA_SHA256
if (buf_has_algo(cli_ses.server_sig_algs, SSH_SIGNATURE_RSA_SHA256) 
== DROPBEAR_SUCCESS) {
sigtype = DROPBEAR_SIGNATURE_RSA_SHA256;
TRACE(("server-sig-algs allows rsa sha256"))
break;
}
#endif 
#if DROPBEAR_RSA_SHA1
if (buf_has_algo(cli_ses.server_sig_algs, SSH_SIGNKEY_RSA)
== DROPBEAR_SUCCESS) {
sigtype = DROPBEAR_SIGNATURE_RSA_SHA1;
TRACE(("server-sig-algs allows rsa sha1"))
break;
}
#endif 
} else
#endif 
{
const char *name = NULL;
sigtype = signature_type_from_signkey(key->type);
name = signature_name_from_type(sigtype, NULL);
if (buf_has_algo(cli_ses.server_sig_algs, name)
== DROPBEAR_SUCCESS) {
TRACE(("server-sig-algs allows %s", name))
break;
}
}
TRACE(("server-sig-algs no match keytype %d, skipping", key->type))
key = list_remove(cli_opts.privkeys->first);
sign_key_free(key); 
continue;
} else {
#if DROPBEAR_RSA
if (key->type == DROPBEAR_SIGNKEY_RSA) {
#if DROPBEAR_RSA_SHA1
sigtype = DROPBEAR_SIGNATURE_RSA_SHA1;
TRACE(("no server-sig-algs, using rsa sha1"))
break;
#else
TRACE(("no server-sig-algs, skipping rsa sha256"))
key = list_remove(cli_opts.privkeys->first);
sign_key_free(key); 
continue;
#endif
} 
#endif 
sigtype = signature_type_from_signkey(key->type);
TRACE(("no server-sig-algs, using key"))
break;
}
}
if (cli_opts.privkeys->first) {
sign_key * key = (sign_key*)cli_opts.privkeys->first->item;
send_msg_userauth_pubkey(key, sigtype, 0);
cli_ses.lastprivkey = key;
cli_ses.is_trivial_auth = 0;
TRACE(("leave cli_auth_pubkey-success"))
return 1;
} else {
TRACE(("leave cli_auth_pubkey-failure"))
return 0;
}
}

