(long long)nPktNum,
(long long)nPktNumNackBegin, (long long)( nPktNumNackBegin + numNacks ),
(long long)nPktNumAckBegin, (long long)( nPktNumAckBegin + numAcks )
);
}
Assert( nPktNumAckBegin >= 0 );
while ( inFlightPkt->first >= nPktNumAckBegin )
{
Assert( inFlightPkt->first < nPktNumAckEnd );
for ( const SNPRange_t &relRange: inFlightPkt->second.m_vecReliableSegments )
{
if ( m_senderState.m_listInFlightReliableRange.erase( relRange ) == 0 )
{
if ( m_senderState.m_listReadyRetryReliableRange.erase( relRange ) > 0 )
{
m_senderState.m_cbPendingReliable -= int( relRange.length() );
Assert( m_senderState.m_cbPendingReliable >= 0 );
bAckedReliableRange = true;
}
}
else
{
bAckedReliableRange = true;
Assert( m_senderState.m_listReadyRetryReliableRange.count( relRange ) == 0 );
}
}
if ( inFlightPkt == m_senderState.m_itNextInFlightPacketToTimeout )
++m_senderState.m_itNextInFlightPacketToTimeout;
inFlightPkt = m_senderState.m_mapInFlightPacketsByPktNum.erase( inFlightPkt );
--inFlightPkt;
m_senderState.MaybeCheckInFlightPacketMap();
}
if ( nPktNumAckBegin <= m_statsEndToEnd.m_pktNumInFlight && m_statsEndToEnd.m_pktNumInFlight < nPktNumAckEnd )
m_statsEndToEnd.InFlightPktAck( usecNow );
Assert( nPktNumNackBegin >= 0 );
while ( inFlightPkt->first >= nPktNumNackBegin )
{
Assert( inFlightPkt->first < nPktNumAckEnd );
SNP_SenderProcessPacketNack( inFlightPkt->first, inFlightPkt->second, "NACK" );
--inFlightPkt;
}
nPktNumAckEnd = nPktNumNackBegin;
--nBlocks;
}
if ( bAckedReliableRange )
{
m_senderState.RemoveAckedReliableMessageFromUnackedList();
if ( nLogLevelPacketDecode >= k_ESteamNetworkingSocketsDebugOutputType_Debug )
{
int64 nPeerReliablePos = m_senderState.m_nReliableStreamPos;
if ( !m_senderState.m_listInFlightReliableRange.empty() )
nPeerReliablePos = std::min( nPeerReliablePos, m_senderState.m_listInFlightReliableRange.begin()->first.m_nBegin );
if ( !m_senderState.m_listReadyRetryReliableRange.empty() )
nPeerReliablePos = std::min( nPeerReliablePos, m_senderState.m_listReadyRetryReliableRange.begin()->first.m_nBegin );
SpewDebugGroup( nLogLevelPacketDecode, "[%s]   decode pkt %lld peer reliable pos = %lld\n",
GetDescription(),
(long long)nPktNum, (long long)nPeerReliablePos );
}
}
if ( nLatestRecvSeqNum > m_senderState.m_nMinPktWaitingOnAck )
{
SpewVerboseGroup( nLogLevelPacketDecode, "[%s]   updating min_waiting_on_ack %lld -> %lld\n",
GetDescription(),
(long long)m_senderState.m_nMinPktWaitingOnAck, (long long)nLatestRecvSeqNum );
m_senderState.m_nMinPktWaitingOnAck = nLatestRecvSeqNum;
}
}
else
{
DECODE_ERROR( "Invalid SNP frame lead byte 0x%02x", nFrameType );
}
}
if ( bInhibitMarkReceived )
{
}
else
{
bool bScheduleAck = nDecodeReliablePos > 0;
SNP_RecordReceivedPktNum( nPktNum, usecNow, bScheduleAck );
}
m_statsEndToEnd.TrackProcessSequencedPacket( nPktNum, usecNow, usecTimeSinceLast );
return true;
#undef DECODE_ERROR
#undef EXPECT_BYTES
#undef READ_8BITU
#undef READ_16BITU
#undef READ_24BITU
#undef READ_32BITU
#undef READ_64BITU
#undef READ_VARINT
#undef READ_SEGMENT_DATA_SIZE
}

static Jsi_RC jsi_ArrayFillCmd(Jsi_Interp *interp, Jsi_Value *args, Jsi_Value *_this,Jsi_Value **ret, Jsi_Func *funcPtr) {
if (_this->vt != JSI_VT_OBJECT || !Jsi_ObjIsArray(interp, _this->d.obj)) 
return Jsi_LogError("expected array object");
Jsi_RC rc = JSI_OK;
int istart = 0, iend, n, nsiz;
Jsi_Number nstart = 0, nend = 0;     Jsi_Value *value = Jsi_ValueArrayIndex(interp, args, 0),
*start = Jsi_ValueArrayIndex(interp, args, 1),
*end = Jsi_ValueArrayIndex(interp, args, 2);
Jsi_Obj *obj = _this->d.obj;
n = Jsi_ObjGetLength(interp, obj);
if (start && Jsi_GetNumberFromValue(interp, start, &nstart) == JSI_OK) {
istart = (int)nstart;
if (istart > n)
goto bail;
if (istart < 0)
istart = (n+istart);
if (istart<0)
goto bail;
}
if (n == 0) {
goto bail;
}
iend = n-1;
if (end && Jsi_GetNumberFromValue(interp,end, &nend) == JSI_OK) {
iend = (int) nend;
if (iend >= n)
iend = n;
if (iend < 0)
iend = (n+iend);
if (iend<0)
goto bail;
}
nsiz = iend-istart+1;
if (nsiz<=0)
goto bail;
int i;
for (i = istart; i <= iend; i++)
{
if (obj->arr[i])
Jsi_ValueCopy(interp, obj->arr[i], value);
else
obj->arr[i] = Jsi_ValueDup(interp, value);
}
bail:
if (_this != *ret) {
Jsi_ValueMove(interp, *ret, _this);
}
return rc;
}

int main(int argc, char *argv[])
{
int opt;
int sock_pollfd_idx = -1;
bool dofork = true;
bool outputpid = false;
bool no_domain_init = false;
bool live_update = false;
const char *pidfile = NULL;
int timeout;
orig_argc = argc;
orig_argv = argv;
while ((opt = getopt_long(argc, argv, "DE:F:HKNPS:t:A:M:Q:q:T:RVW:w:U",
options, NULL)) != -1) {
switch (opt) {
case 'D':
no_domain_init = true;
break;
case 'E':
quota_nb_entry_per_domain = strtol(optarg, NULL, 10);
break;
case 'F':
pidfile = optarg;
break;
case 'H':
usage();
return 0;
case 'N':
dofork = false;
break;
case 'P':
outputpid = true;
break;
case 'R':
recovery = false;
break;
case 'S':
quota_max_entry_size = strtol(optarg, NULL, 10);
break;
case 't':
quota_max_transaction = strtol(optarg, NULL, 10);
break;
case 'T':
tracefile = optarg;
break;
case 'I':
tdb_flags = TDB_INTERNAL|TDB_NOLOCK;
break;
case 'K':
keep_orphans = true;
break;
case 'V':
verbose = true;
break;
case 'W':
quota_nb_watch_per_domain = strtol(optarg, NULL, 10);
break;
case 'A':
quota_nb_perms_per_node = strtol(optarg, NULL, 10);
break;
case 'M':
quota_max_path_len = strtol(optarg, NULL, 10);
quota_max_path_len = min(XENSTORE_REL_PATH_MAX,
quota_max_path_len);
break;
case 'Q':
set_quota(optarg, false);
break;
case 'q':
set_quota(optarg, true);
break;
case 'w':
set_timeout(optarg);
break;
case 'e':
dom0_event = strtol(optarg, NULL, 10);
break;
case 'm':
dom0_domid = strtol(optarg, NULL, 10);
break;
case 'p':
priv_domid = strtol(optarg, NULL, 10);
break;
#ifndef NO_LIVE_UPDATE
case 'U':
live_update = true;
break;
#endif
}
}
if (optind != argc)
barf("%s: No arguments desired", argv[0]);
reopen_log();
mkdir(xs_daemon_rundir(), 0755);
mkdir(xs_daemon_rootdir(), 0755);
if (dofork) {
openlog("xenstored", 0, LOG_DAEMON);
if (!live_update)
daemonize();
}
if (pidfile)
write_pidfile(pidfile);
if (!dofork)
talloc_enable_leak_report_full();
signal(SIGPIPE, SIG_IGN);
talloc_enable_null_tracking();
#ifndef NO_SOCKETS
if (!live_update)
init_sockets();
#endif
init_pipe(reopen_log_pipe);
if (!no_domain_init && !live_update) {
domain_init(-1);
dom0_init();
}
if (outputpid) {
printf("%ld\n", (long)getpid());
fflush(stdout);
}
if (dofork && !live_update)
finish_daemonize();
#ifndef __MINIOS__
if (dofork)
xprintf = trace;
#endif
signal(SIGHUP, trigger_reopen_log);
if (tracefile)
tracefile = talloc_strdup(NULL, tracefile);
#ifndef NO_LIVE_UPDATE
if (live_update)
lu_read_state();
#endif
initialize_fds(&sock_pollfd_idx, &timeout);
#if defined(XEN_SYSTEMD_ENABLED)
if (!live_update) {
sd_notify(1, "READY=1");
fprintf(stderr, SD_NOTICE "xenstored is ready\n");
}
#endif
for (;;) {
struct connection *conn, *next;
if (poll(fds, nr_fds, timeout) < 0) {
if (errno == EINTR)
continue;
barf_perror("Poll failed");
}
if (reopen_log_pipe0_pollfd_idx != -1) {
if (fds[reopen_log_pipe0_pollfd_idx].revents
& ~POLLIN) {
close(reopen_log_pipe[0]);
close(reopen_log_pipe[1]);
init_pipe(reopen_log_pipe);
} else if (fds[reopen_log_pipe0_pollfd_idx].revents
& POLLIN) {
char c;
if (read(reopen_log_pipe[0], &c, 1) != 1)
barf_perror("read failed");
reopen_log();
}
reopen_log_pipe0_pollfd_idx = -1;
}
if (sock_pollfd_idx != -1) {
if (fds[sock_pollfd_idx].revents & ~POLLIN) {
barf_perror("sock poll failed");
break;
} else if (fds[sock_pollfd_idx].revents & POLLIN) {
accept_connection(sock);
sock_pollfd_idx = -1;
}
}
if (xce_pollfd_idx != -1) {
if (fds[xce_pollfd_idx].revents & ~POLLIN) {
barf_perror("xce_handle poll failed");
break;
} else if (fds[xce_pollfd_idx].revents & POLLIN) {
handle_event();
xce_pollfd_idx = -1;
}
}
list_for_each_entry_safe(conn, next, &connections, list) {
talloc_increase_ref_count(conn);
if (conn_can_read(conn))
handle_input(conn);
if (talloc_free(conn) == 0)
continue;
talloc_increase_ref_count(conn);
if (conn_can_write(conn))
handle_output(conn);
if (talloc_free(conn) == 0)
continue;
conn->pollfd_idx = -1;
}
if (delayed_requests) {
list_for_each_entry(conn, &connections, list) {
struct delayed_request *req, *tmp;
list_for_each_entry_safe(req, tmp,
&conn->delayed, list)
call_delayed(req);
}
}
initialize_fds(&sock_pollfd_idx, &timeout);
}
}

static void
mbim_dissect_phonebook_read_info(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, gint offset)
{
proto_tree *subtree;
gint base_offset;
guint32 i, element_count;
wmem_array_t *pair_list;
struct mbim_pair_list pair_list_item, *p_pair_list_item;
base_offset = offset;
proto_tree_add_item_ret_uint(tree, hf_mbim_phonebook_read_info_element_count, tvb, offset, 4, ENC_LITTLE_ENDIAN, &element_count);
offset += 4;
if (element_count) {
pair_list = wmem_array_sized_new(wmem_packet_scope(), sizeof(struct mbim_pair_list), element_count);
subtree = proto_tree_add_subtree(tree, tvb, offset, 8*element_count, ett_mbim_pair_list, NULL, "Phonebook Ref List");
for (i = 0; i < element_count; i++) {
proto_tree_add_item_ret_uint(subtree, hf_mbim_phonebook_read_info_phonebook_offset,
tvb, offset, 4, ENC_LITTLE_ENDIAN, &pair_list_item.offset);
offset += 4;
proto_tree_add_item_ret_uint(subtree, hf_mbim_phonebook_read_info_phonebook_size,
tvb, offset, 4, ENC_LITTLE_ENDIAN, &pair_list_item.size);
offset += 4;
wmem_array_append_one(pair_list, pair_list_item);
}
for (i = 0; i < element_count; i++) {
p_pair_list_item = (struct mbim_pair_list*)wmem_array_index(pair_list, i);
if (p_pair_list_item->offset && p_pair_list_item->size) {
subtree = proto_tree_add_subtree_format(tree, tvb, base_offset + p_pair_list_item->offset,
p_pair_list_item->size, ett_mbim_pair_list, NULL, "Phonebook Element #%u", i+1);
mbim_dissect_phonebook_entry(tvb, pinfo, subtree, base_offset + p_pair_list_item->offset);
}
}
}
}

void *load_device_tree(const char *filename_path, int *sizep)
{
int dt_size;
int dt_file_load_size;
int ret;
void *fdt = NULL;
*sizep = 0;
dt_size = get_image_size(filename_path);
if (dt_size < 0) {
error_report("Unable to get size of device tree file '%s'",
filename_path);
goto fail;
}
dt_size += 10000;
dt_size *= 2;
fdt = g_malloc0(dt_size);
dt_file_load_size = load_image(filename_path, fdt);
if (dt_file_load_size < 0) {
error_report("Unable to open device tree file '%s'",
filename_path);
goto fail;
}
ret = fdt_open_into(fdt, fdt, dt_size);
if (ret) {
error_report("Unable to copy device tree in memory");
goto fail;
}
if (fdt_check_header(fdt)) {
error_report("Device tree file loaded into memory is invalid: %s",
filename_path);
goto fail;
}
*sizep = dt_size;
return fdt;
fail:
g_free(fdt);
return NULL;
}

static void *stbi__pic_load(stbi__context *s,int *px,int *py,int *comp,int req_comp, stbi__result_info *ri)
{
stbi_uc *result;
int i, x,y, internal_comp;
STBI_NOTUSED(ri);
if (!comp) comp = &internal_comp;
for (i=0; i<92; ++i)
stbi__get8(s);
x = stbi__get16be(s);
y = stbi__get16be(s);
if (y > STBI_MAX_DIMENSIONS) return stbi__errpuc("too large","Very large image (corrupt?)");
if (x > STBI_MAX_DIMENSIONS) return stbi__errpuc("too large","Very large image (corrupt?)");
if (stbi__at_eof(s))  return stbi__errpuc("bad file","file too short (pic header)");
if (!stbi__mad3sizes_valid(x, y, 4, 0)) return stbi__errpuc("too large", "PIC image too large to decode");
stbi__get32be(s);    stbi__get16be(s);    stbi__get16be(s); 
result = (stbi_uc *) stbi__malloc_mad3(x, y, 4, 0);
if (!result) return stbi__errpuc("outofmem", "Out of memory");
memset(result, 0xff, x*y*4);
if (!stbi__pic_load_core(s,x,y,comp, result)) {
STBI_FREE(result);
result=0;
}
*px = x;
*py = y;
if (req_comp == 0) req_comp = *comp;
result=stbi__convert_format(result,4,req_comp,x,y);
return result;
}

