static int
tiff12_print_page(gx_device_printer * pdev, gp_file * file)
{
gx_device_tiff *const tfdev = (gx_device_tiff *)pdev;
int code;
if (gdev_prn_file_is_new(pdev)) {
tfdev->tif = tiff_from_filep(pdev, pdev->dname, file, tfdev->BigEndian, tfdev->UseBigTIFF);
if (!tfdev->tif)
return_error(gs_error_invalidfileaccess);
}
code = gdev_tiff_begin_page(tfdev, file);
if (code < 0)
return code;
TIFFSetField(tfdev->tif, TIFFTAG_BITSPERSAMPLE, 4);
tiff_set_rgb_fields(tfdev);
TIFFCheckpointDirectory(tfdev->tif);
{
int y;
int size = gdev_prn_raster(pdev);
byte *data = gs_alloc_bytes(pdev->memory, size, "tiff12_print_page");
if (data == 0)
return_error(gs_error_VMerror);
memset(data, 0, size);
for (y = 0; y < pdev->height; ++y) {
const byte *src;
byte *dest;
int x;
code = gdev_prn_copy_scan_lines(pdev, y, data, size);
if (code < 0)
break;
for (src = data, dest = data, x = 0; x < size;
src += 6, dest += 3, x += 6
) {
dest[0] = (src[0] & 0xf0) | (src[1] >> 4);
dest[1] = (src[2] & 0xf0) | (src[3] >> 4);
dest[2] = (src[4] & 0xf0) | (src[5] >> 4);
}
TIFFWriteScanline(tfdev->tif, data, y, 0);
}
gs_free_object(pdev->memory, data, "tiff12_print_page");
TIFFWriteDirectory(tfdev->tif);
}
return code;
}

void
bc_str2num (bc_num *num, char *str, int scale)
{
int digits, strscale;
char *ptr, *nptr;
char zero_int;
bc_free_num (num);
ptr = str;
digits = 0;
strscale = 0;
zero_int = FALSE;
if ( (*ptr == '+') || (*ptr == '-'))  ptr++;  
while (*ptr == '0') ptr++;
while (isdigit((int)*ptr)) ptr++, digits++;
if (*ptr == '.') ptr++;
while (isdigit((int)*ptr)) ptr++, strscale++;
if ((*ptr != '\0') || (digits+strscale == 0))
{
*num = bc_copy_num (BCG(_zero_));
return;
}
strscale = MIN(strscale, scale);
if (digits == 0)
{
zero_int = TRUE;
digits = 1;
}
*num = bc_new_num (digits, strscale);
ptr = str;
if (*ptr == '-')
{
(*num)->n_sign = MINUS;
ptr++;
}
else
{
(*num)->n_sign = PLUS;
if (*ptr == '+') ptr++;
}
while (*ptr == '0') ptr++;
nptr = (*num)->n_value;
if (zero_int)
{
*nptr++ = 0;
digits = 0;
}
for (;digits > 0; digits--)
*nptr++ = CH_VAL(*ptr++);
if (strscale > 0)
{
ptr++;  
for (;strscale > 0; strscale--)
*nptr++ = CH_VAL(*ptr++);
}
if (bc_is_zero (*num))
(*num)->n_sign = PLUS;
}

static void prekey_handler(const char *userid,
const uint8_t *key, size_t key_len,
uint16_t id, const char *clientid,
bool last, void *arg)
{
struct session *sess;
char lclientid[64];
int err;
output("prekey_handler: %zu bytes, user:%s[%u] -> %s\n",
key_len, userid, id, clientid);
err = client_id_load(lclientid, sizeof(lclientid));
if (err) {
debug("my clientid not set -- cannot store prekeys\n");
return;
}
sess = cryptobox_session_find(g_cryptobox, userid, clientid, lclientid);
if (sess) {
output("prekey: session found\n");
}
else {
info("conv: adding key to cryptobox for clientid=%s\n",
clientid);
err = cryptobox_session_add_send(g_cryptobox, userid, clientid, lclientid,
key, key_len);
if (err) {
warning("cryptobox_session_add_send failed (%m)\n",
err);
}
}
}

