BZIP3_API s32 bz3_decode_block(struct bz3_state * state, u8 * buffer, s32 data_size, s32 orig_size) {
u32 crc32 = read_neutral_s32(buffer);
s32 bwt_idx = read_neutral_s32(buffer + 4);
if (data_size > bz3_bound(state->block_size) || data_size < 0) {
state->last_error = BZ3_ERR_MALFORMED_HEADER;
return -1;
}
if (bwt_idx == -1) {
if (data_size - 8 > 64 || data_size < 8) {
state->last_error = BZ3_ERR_MALFORMED_HEADER;
return -1;
}
memmove(buffer, buffer + 8, data_size - 8);
if (crc32sum(1, buffer, data_size - 8) != crc32) {
state->last_error = BZ3_ERR_CRC;
return -1;
}
return data_size - 8;
}
s8 model = buffer[8];
s32 lzp_size = -1, rle_size = -1, p = 0;
if (model & 2) lzp_size = read_neutral_s32(buffer + 9 + 4 * p++);
if (model & 4) rle_size = read_neutral_s32(buffer + 9 + 4 * p++);
p += 2;
data_size -= p * 4 + 1;
if (((model & 2) && (lzp_size > bz3_bound(state->block_size) || lzp_size < 0)) ||
((model & 4) && (rle_size > bz3_bound(state->block_size) || rle_size < 0))) {
state->last_error = BZ3_ERR_MALFORMED_HEADER;
return -1;
}
if (orig_size > bz3_bound(state->block_size) || orig_size < 0) {
state->last_error = BZ3_ERR_MALFORMED_HEADER;
return -1;
}
u8 *b1 = buffer, *b2 = state->swap_buffer;
begin(state->cm_state);
state->cm_state->in_queue = b1 + p * 4 + 1;
state->cm_state->input_ptr = 0;
state->cm_state->input_max = data_size;
s32 size_src;
if (model & 2)
size_src = lzp_size;
else if (model & 4)
size_src = rle_size;
else
size_src = orig_size;
decode_bytes(state->cm_state, b2, size_src);
swap(b1, b2);
if (bwt_idx >= size_src) {
state->last_error = BZ3_ERR_MALFORMED_HEADER;
return -1;
}
if (libsais_unbwt(b1, b2, state->sais_array, size_src, NULL, bwt_idx) < 0) {
state->last_error = BZ3_ERR_BWT;
return -1;
}
swap(b1, b2);
if (model & 2) {
size_src = lzp_decompress(b1, b2, lzp_size, bz3_bound(state->block_size), state->lzp_lut);
if (size_src == -1) {
state->last_error = BZ3_ERR_CRC;
return -1;
}
swap(b1, b2);
}
if (model & 4) {
int err = mrled(b1, b2, orig_size, size_src);
if(err) {
state->last_error = BZ3_ERR_CRC;
return -1;
}
size_src = orig_size;
swap(b1, b2);
}
state->last_error = BZ3_OK;
if (size_src > state->block_size || size_src < 0) {
state->last_error = BZ3_ERR_MALFORMED_HEADER;
return -1;
}
if (b1 != buffer) memcpy(buffer, b1, size_src);
if (crc32 != crc32sum(1, buffer, size_src)) {
state->last_error = BZ3_ERR_CRC;
return -1;
}
return size_src;
}

static void
dissect_hsdsch_type_2_channel_info(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree,
int offset, struct fp_info *p_fp_info,
void *data)
{
gboolean is_control_frame;
guint16 header_crc = 0;
proto_item * header_crc_pi = NULL;
guint16 header_length = 0;
header_crc = tvb_get_bits8(tvb, 0, 7);
header_crc_pi = proto_tree_add_item(tree, hf_fp_header_crc, tvb, offset, 1, ENC_BIG_ENDIAN);
is_control_frame = tvb_get_guint8(tvb, offset) & 0x01;
proto_tree_add_item(tree, hf_fp_ft, tvb, offset, 1, ENC_BIG_ENDIAN);
offset++;
col_append_str(pinfo->cinfo, COL_INFO, is_control_frame ? " [Control] " : " [Data] ");
if (is_control_frame) {
dissect_common_control(tvb, pinfo, tree, offset, p_fp_info);
if (preferences_header_checksum) {
verify_control_frame_crc(tvb, pinfo, header_crc_pi, header_crc);
}
}
else {
guint8 number_of_pdu_blocks;
gboolean drt_present = FALSE;
gboolean fach_present = FALSE;
guint16 user_buffer_size;
int n;
guint j;
#define MAX_PDU_BLOCKS 31
guint64 lchid[MAX_PDU_BLOCKS];
guint64 pdu_length[MAX_PDU_BLOCKS];
guint64 no_of_pdus[MAX_PDU_BLOCKS];
umts_mac_info *macinf;
rlc_info *rlcinf;
rlcinf = (rlc_info *)p_get_proto_data(wmem_file_scope(), pinfo, proto_rlc, 0);
macinf = (umts_mac_info *)p_get_proto_data(wmem_file_scope(), pinfo, proto_umts_mac, 0);
col_append_str(pinfo->cinfo, COL_INFO, "(ehs)");
if ((p_fp_info->release == 6) ||
(p_fp_info->release == 7)) {
guint8 frame_seq_no = (tvb_get_guint8(tvb, offset) & 0xf0) >> 4;
proto_tree_add_item(tree, hf_fp_frame_seq_nr, tvb, offset, 1, ENC_BIG_ENDIAN);
col_append_fstr(pinfo->cinfo, COL_INFO, "  seqno=%u", frame_seq_no);
}
proto_tree_add_item(tree, hf_fp_cmch_pi, tvb, offset, 1, ENC_BIG_ENDIAN);
offset++;
number_of_pdu_blocks = (tvb_get_guint8(tvb, offset) >> 3);
proto_tree_add_item(tree, hf_fp_total_pdu_blocks, tvb, offset, 1, ENC_BIG_ENDIAN);
if (p_fp_info->release == 7) {
proto_tree_add_item(tree, hf_fp_flush, tvb, offset, 1, ENC_BIG_ENDIAN);
proto_tree_add_item(tree, hf_fp_fsn_drt_reset, tvb, offset, 1, ENC_BIG_ENDIAN);
drt_present = tvb_get_guint8(tvb, offset) & 0x01;
proto_tree_add_item(tree, hf_fp_drt_indicator, tvb, offset, 1, ENC_BIG_ENDIAN);
}
offset++;
fach_present = (tvb_get_guint8(tvb, offset) & 0x80) >> 7;
proto_tree_add_item(tree, hf_fp_fach_indicator, tvb, offset, 1, ENC_BIG_ENDIAN);
offset++;
user_buffer_size = tvb_get_ntohs(tvb, offset);
proto_tree_add_item(tree, hf_fp_user_buffer_size, tvb, offset, 2, ENC_BIG_ENDIAN);
offset += 2;
col_append_fstr(pinfo->cinfo, COL_INFO, "  User-Buffer-Size=%u", user_buffer_size);
for (n=0; n < number_of_pdu_blocks; n++) {
proto_item *pdu_block_header_ti;
proto_tree *pdu_block_header_tree;
int        block_header_start_offset = offset;
pdu_block_header_ti = proto_tree_add_string_format(tree, hf_fp_hsdsch_pdu_block_header,
tvb, offset, 0,
"",
"PDU Block Header");
pdu_block_header_tree = proto_item_add_subtree(pdu_block_header_ti,
ett_fp_hsdsch_pdu_block_header);
proto_tree_add_bits_ret_val(pdu_block_header_tree, hf_fp_pdu_length_in_block, tvb,
(offset*8) + ((n % 2) ? 4 : 0), 11,
&pdu_length[n], ENC_BIG_ENDIAN);
if ((n % 2) == 0)
offset++;
else
offset += 2;
proto_tree_add_bits_ret_val(pdu_block_header_tree, hf_fp_pdus_in_block, tvb,
(offset*8) + ((n % 2) ? 0 : 4), 4,
&no_of_pdus[n], ENC_BIG_ENDIAN);
if ((n % 2) == 0) {
offset++;
}
proto_tree_add_bits_ret_val(pdu_block_header_tree, hf_fp_lchid, tvb,
(offset*8) + ((n % 2) ? 4 : 0), 4,
&lchid[n], ENC_BIG_ENDIAN);
if ((n % 2) == 1) {
offset++;
}
else {
if (n == (number_of_pdu_blocks-1)) {
offset++;
}
}
proto_item_append_text(pdu_block_header_ti,
" (lch:%u, %u pdus of %u bytes)",
(guint16)lchid[n],
(guint16)no_of_pdus[n],
(guint16)pdu_length[n]);
if (((n % 2) == 0) && (n < (number_of_pdu_blocks-1))) {
proto_item_set_len(pdu_block_header_ti,
offset - block_header_start_offset+1);
}
else {
proto_item_set_len(pdu_block_header_ti,
offset - block_header_start_offset);
}
}
if (header_length == 0) {
header_length = offset;
}
if (drt_present) {
proto_tree_add_item(tree, hf_fp_drt, tvb, offset, 2, ENC_BIG_ENDIAN);
offset += 2;
}
if (fach_present) {
proto_tree_add_item(tree, hf_fp_hrnti, tvb, offset, 2, ENC_BIG_ENDIAN);
offset += 2;
proto_tree_add_item(tree, hf_fp_rach_measurement_result, tvb, offset, 2, ENC_BIG_ENDIAN);
offset++;
}
for (n=0; n < number_of_pdu_blocks; n++) {
for (j=0;j<no_of_pdus[n];j++) {
macinf->content[j] = lchId_type_table[lchid[n]+1]; 
macinf->lchid[j] = (guint8)lchid[n]+1;    
macinf->macdflow_id[j] = p_fp_info->hsdsch_macflowd_id;
rlcinf->mode[j] = lchId_rlc_map[lchid[n]+1];
macinf->ctmux[n] = FALSE;
rlcinf->li_size[j] = RLC_LI_7BITS;
#if 0
if ( rrc_ciph_inf && g_tree_lookup(rrc_ciph_inf, GINT_TO_POINTER((gint)p_fp_info->com_context_id)) ) {
rlcinf->ciphered[j] = TRUE;
} else {
rlcinf->ciphered[j] = FALSE;
}
#endif
rlcinf->ciphered[j] = FALSE;
rlcinf->deciphered[j] = FALSE;
rlcinf->rbid[j] = (guint8)lchid[n]+1;
rlcinf->urnti[j] = p_fp_info->com_context_id;    
}
offset = dissect_macd_pdu_data_type_2(tvb, pinfo, tree, offset,
(guint16)pdu_length[n],
(guint16)no_of_pdus[n],
p_fp_info, data);
}
if (preferences_header_checksum) {
verify_header_crc(tvb, pinfo, header_crc_pi, header_crc, header_length);
}
dissect_spare_extension_and_crc(tvb, pinfo, tree, 1, offset, header_length);
}
}

static gboolean
parse_report_descriptor(report_descriptor_t *rdesc)
{
hid_field_t field;
guint8 *data = rdesc->desc_body;
unsigned int tag, type, size;
guint8 prefix;
guint32 defined = 0, usage = 0, usage_min = 0, usage_max = 0;
wmem_allocator_t *scope = wmem_file_scope();
gboolean first_item = TRUE;
memset(&field, 0, sizeof(field));
field.usages = wmem_array_new(scope, sizeof(guint32));
rdesc->fields_in = wmem_array_new(scope, sizeof(hid_field_t));
rdesc->fields_out = wmem_array_new(scope, sizeof(hid_field_t));
int i = 0;
while (i < rdesc->desc_length)
{
prefix = data[i];
tag = (prefix & 0b11110000) >> 4;
type = (prefix & 0b00001100) >> 2;
size = prefix & 0b00000011;
if (size == 3)  
size = 4;
switch (type)
{
case USBHID_ITEMTYPE_MAIN:
switch (tag)
{
case USBHID_MAINITEM_TAG_INPUT:
field.properties = hid_unpack_value(data, i, size);
if ((defined & HID_REQUIRED_MASK) != HID_REQUIRED_MASK)
goto err;
wmem_array_append_one(rdesc->fields_in, field);
field.usages = wmem_array_new(scope, sizeof(guint32));
first_item = FALSE;
defined &= HID_GLOBAL_MASK;
break;
case USBHID_MAINITEM_TAG_OUTPUT:
field.properties = hid_unpack_value(data, i, size);
if ((defined & HID_REQUIRED_MASK) != HID_REQUIRED_MASK)
goto err;
wmem_array_append_one(rdesc->fields_out, field);
field.usages = wmem_array_new(scope, sizeof(guint32));
first_item = FALSE;
defined &= HID_GLOBAL_MASK;
break;
case USBHID_MAINITEM_TAG_FEATURE:
break;
case USBHID_MAINITEM_TAG_COLLECTION:
wmem_free(scope, field.usages);
field.usages = wmem_array_new(scope, sizeof(guint32));
break;
default:
break;
}
break;
case USBHID_ITEMTYPE_GLOBAL:
switch (tag)
{
case USBHID_GLOBALITEM_TAG_USAGE_PAGE:
field.usage_page = hid_unpack_value(data, i, size);
defined |= HID_USAGE_PAGE;
break;
case USBHID_GLOBALITEM_TAG_LOG_MIN:
if (hid_unpack_signed(data, i, size, &field.logical_min))
goto err;
defined |= HID_LOGICAL_MIN;
break;
case USBHID_GLOBALITEM_TAG_LOG_MAX:
if (hid_unpack_signed(data, i, size, &field.logical_max))
goto err;
defined |= HID_LOGICAL_MAX;
break;
case USBHID_GLOBALITEM_TAG_REPORT_SIZE:
field.report_size = hid_unpack_value(data, i, size);
defined |= HID_REPORT_SIZE;
break;
case USBHID_GLOBALITEM_TAG_REPORT_ID:
if (!first_item && !rdesc->uses_report_id)
goto err;
rdesc->uses_report_id = TRUE;
field.report_id = hid_unpack_value(data, i, size);
defined |= HID_REPORT_ID;
break;
case USBHID_GLOBALITEM_TAG_REPORT_COUNT:
field.report_count = hid_unpack_value(data, i, size);
defined |= HID_REPORT_COUNT;
break;
case USBHID_GLOBALITEM_TAG_PUSH:
case USBHID_GLOBALITEM_TAG_POP:
goto err;
default:
break;
}
break;
case USBHID_ITEMTYPE_LOCAL:
switch (tag)
{
case USBHID_LOCALITEM_TAG_USAGE:
if (!(defined & HID_USAGE_PAGE))
return FALSE;
usage = hid_unpack_value(data, i, size);
wmem_array_append_one(field.usages, usage);
break;
case USBHID_LOCALITEM_TAG_USAGE_MIN:
usage_min = hid_unpack_value(data, i, size);
defined |= HID_USAGE_MIN;
break;
case USBHID_LOCALITEM_TAG_USAGE_MAX:
if (!(defined & HID_USAGE_MIN))
return FALSE;
usage_max = hid_unpack_value(data, i, size);
if (usage_min > usage_max) {
goto err;
}
wmem_array_grow(field.usages, usage_max - usage_min + 1);
for (guint32 j = usage_min; j <= usage_max; j++) {
wmem_array_append_one(field.usages, j);
}
defined ^= HID_USAGE_MIN;
break;
default: 
goto err;
}
break;
default: 
goto err;
}
i += size + 1;
}
return TRUE;
err:
for (unsigned int j = 0; j < wmem_array_get_count(rdesc->fields_in); j++)
wmem_free(scope, ((hid_field_t*) wmem_array_index(rdesc->fields_in, j))->usages);
for (unsigned int j = 0; j < wmem_array_get_count(rdesc->fields_out); j++)
wmem_free(scope, ((hid_field_t*) wmem_array_index(rdesc->fields_out, j))->usages);
wmem_free(scope, rdesc->fields_in);
wmem_free(scope, rdesc->fields_out);
return FALSE;
}

static int fill_thread_core_info(struct elf_thread_core_info *t,
const struct user_regset_view *view,
long signr, size_t *total)
{
unsigned int i;
unsigned int regset0_size = regset_size(t->task, &view->regsets[0]);
fill_prstatus(&t->prstatus, t->task, signr);
(void) view->regsets[0].get(t->task, &view->regsets[0], 0, regset0_size,
&t->prstatus.pr_reg, NULL);
fill_note(&t->notes[0], "CORE", NT_PRSTATUS,
PRSTATUS_SIZE(t->prstatus, regset0_size), &t->prstatus);
*total += notesize(&t->notes[0]);
do_thread_regset_writeback(t->task, &view->regsets[0]);
for (i = 1; i < view->n; ++i) {
const struct user_regset *regset = &view->regsets[i];
do_thread_regset_writeback(t->task, regset);
if (regset->core_note_type && regset->get &&
(!regset->active || regset->active(t->task, regset) > 0)) {
int ret;
size_t size = regset_size(t->task, regset);
void *data = kmalloc(size, GFP_KERNEL);
if (unlikely(!data))
return 0;
ret = regset->get(t->task, regset,
0, size, data, NULL);
if (unlikely(ret))
kfree(data);
else {
if (regset->core_note_type != NT_PRFPREG)
fill_note(&t->notes[i], "LINUX",
regset->core_note_type,
size, data);
else {
SET_PR_FPVALID(&t->prstatus,
1, regset0_size);
fill_note(&t->notes[i], "CORE",
NT_PRFPREG, size, data);
}
*total += notesize(&t->notes[i]);
}
}
}
return 1;
}

static int
dissect_kafka_compact_array(proto_tree *tree, tvbuff_t *tvb, packet_info *pinfo, int offset,
kafka_api_version_t api_version,
int(*func)(tvbuff_t*, packet_info*, proto_tree*, int, kafka_api_version_t),
int *p_count)
{
gint64 count;
gint32 len;
len = tvb_get_varint(tvb, offset, FT_VARINT_MAX_LEN, &count, ENC_VARINT_PROTOBUF);
if (len == 0 || count > 0x7ffffffL) {
expert_add_info(pinfo, proto_tree_get_parent(tree), &ei_kafka_bad_array_length);
return offset;
}
offset += len;
offset = dissect_kafka_array_elements(tree, tvb, pinfo, offset, api_version, func, (int)count - 1);
if (p_count != NULL) *p_count = (int)count - 1;
return offset;
}

static int
forward_search_range(regex_t* reg, const UChar* str, const UChar* end, UChar* s,
UChar* range, UChar** low, UChar** high, UChar** low_prev)
{
UChar *p, *pprev = (UChar* )NULL;
#ifdef ONIG_DEBUG_SEARCH
fprintf(stderr, "forward_search_range: str: %d, end: %d, s: %d, range: %d\n",
(int )str, (int )end, (int )s, (int )range);
#endif
p = s;
if (reg->dmin > 0) {
if (ONIGENC_IS_SINGLEBYTE(reg->enc)) {
p += reg->dmin;
}
else {
UChar *q = p + reg->dmin;
while (p < q) p += enclen(reg->enc, p);
}
}
retry:
switch (reg->optimize) {
case ONIG_OPTIMIZE_EXACT:
p = slow_search(reg->enc, reg->exact, reg->exact_end, p, end, range);
break;
case ONIG_OPTIMIZE_EXACT_IC:
p = slow_search_ic(reg->enc, reg->case_fold_flag,
reg->exact, reg->exact_end, p, end, range);
break;
case ONIG_OPTIMIZE_EXACT_BM:
p = bm_search(reg, reg->exact, reg->exact_end, p, end, range);
break;
case ONIG_OPTIMIZE_EXACT_BM_NOT_REV:
p = bm_search_notrev(reg, reg->exact, reg->exact_end, p, end, range);
break;
case ONIG_OPTIMIZE_MAP:
p = map_search(reg->enc, reg->map, p, range);
break;
}
if (p && p < range) {
if (p - reg->dmin < s) {
retry_gate:
pprev = p;
p += enclen(reg->enc, p);
goto retry;
}
if (reg->sub_anchor) {
UChar* prev;
switch (reg->sub_anchor) {
case ANCHOR_BEGIN_LINE:
if (!ON_STR_BEGIN(p)) {
prev = onigenc_get_prev_char_head(reg->enc,
(pprev ? pprev : str), p);
if (!ONIGENC_IS_MBC_NEWLINE(reg->enc, prev, end))
goto retry_gate;
}
break;
case ANCHOR_END_LINE:
if (ON_STR_END(p)) {
#ifndef USE_NEWLINE_AT_END_OF_STRING_HAS_EMPTY_LINE
prev = (UChar* )onigenc_get_prev_char_head(reg->enc,
(pprev ? pprev : str), p);
if (prev && ONIGENC_IS_MBC_NEWLINE(reg->enc, prev, end))
goto retry_gate;
#endif
}
else if (! ONIGENC_IS_MBC_NEWLINE(reg->enc, p, end)
#ifdef USE_CRNL_AS_LINE_TERMINATOR
&& ! ONIGENC_IS_MBC_CRNL(reg->enc, p, end)
#endif
)
goto retry_gate;
break;
}
}
if (reg->dmax == 0) {
*low = p;
if (low_prev) {
if (*low > s)
*low_prev = onigenc_get_prev_char_head(reg->enc, s, p);
else
*low_prev = onigenc_get_prev_char_head(reg->enc,
(pprev ? pprev : str), p);
}
}
else {
if (reg->dmax != ONIG_INFINITE_DISTANCE) {
*low = p - reg->dmax;
if (*low > s) {
*low = onigenc_get_right_adjust_char_head_with_prev(reg->enc, s,
*low, (const UChar** )low_prev);
if (low_prev && IS_NULL(*low_prev))
*low_prev = onigenc_get_prev_char_head(reg->enc,
(pprev ? pprev : s), *low);
}
else {
if (low_prev)
*low_prev = onigenc_get_prev_char_head(reg->enc,
(pprev ? pprev : str), *low);
}
}
}
*high = p - reg->dmin;
#ifdef ONIG_DEBUG_SEARCH
fprintf(stderr,
"forward_search_range success: low: %d, high: %d, dmin: %d, dmax: %d\n",
(int )(*low - str), (int )(*high - str), reg->dmin, reg->dmax);
#endif
return 1; 
}
return 0; 
}

static grub_err_t
find_file (const char *currpath, grub_fshelp_node_t currroot,
grub_fshelp_node_t *currfound,
struct grub_fshelp_find_file_closure *c)
{
#ifndef _MSC_VER
char fpath[grub_strlen (currpath) + 1];
#else
char *fpath = grub_malloc (grub_strlen (currpath) + 1);
#endif
char *name = fpath;
char *next;
enum grub_fshelp_filetype type = GRUB_FSHELP_DIR;
grub_fshelp_node_t currnode = currroot;
grub_fshelp_node_t oldnode = currroot;
c->currroot = currroot;
grub_strncpy (fpath, currpath, grub_strlen (currpath) + 1);
while (*name == '/')
name++;
if (! *name)
{
*currfound = currnode;
return 0;
}
for (;;)
{
int found;
struct find_file_closure cc;
next = grub_strchr (name, '/');
if (next)
{
while (*next == '/')
*(next++) = '\0';
}
if (type != GRUB_FSHELP_DIR)
{
free_node (currnode, c);
return grub_error (GRUB_ERR_BAD_FILE_TYPE, "not a directory");
}
cc.name = name;
cc.type = &type;
cc.oldnode = &oldnode;
cc.currnode = &currnode;
found = c->iterate_dir (currnode, iterate, &cc);
if (! found)
{
if (grub_errno)
return grub_errno;
break;
}
if (type == GRUB_FSHELP_SYMLINK)
{
char *symlink;
if (++(c->symlinknest) == 8)
{
free_node (currnode, c);
free_node (oldnode, c);
return grub_error (GRUB_ERR_SYMLINK_LOOP,
"too deep nesting of symlinks");
}
symlink = c->read_symlink (currnode);
free_node (currnode, c);
if (!symlink)
{
free_node (oldnode, c);
return grub_errno;
}
if (symlink[0] == '/')
{
free_node (oldnode, c);
oldnode = c->rootnode;
}
find_file (symlink, oldnode, &currnode, c);
type = c->foundtype;
grub_free (symlink);
if (grub_errno)
{
free_node (oldnode, c);
return grub_errno;
}
}
free_node (oldnode, c);
if (! next || *next == '\0')
{
*currfound = currnode;
c->foundtype = type;
return 0;
}
name = next;
}
return grub_error (GRUB_ERR_FILE_NOT_FOUND, "file not found");
}

static struct line_info_table*
decode_line_info (struct comp_unit *unit, struct dwarf2_debug *stash)
{
bfd *abfd = unit->abfd;
struct line_info_table* table;
bfd_byte *line_ptr;
bfd_byte *line_end;
struct line_head lh;
unsigned int i, bytes_read, offset_size;
char *cur_file, *cur_dir;
unsigned char op_code, extended_op, adj_opcode;
unsigned int exop_len;
bfd_size_type amt;
if (! read_section (abfd, &stash->debug_sections[debug_line],
stash->syms, unit->line_offset,
&stash->dwarf_line_buffer, &stash->dwarf_line_size))
return NULL;
amt = sizeof (struct line_info_table);
table = (struct line_info_table *) bfd_alloc (abfd, amt);
if (table == NULL)
return NULL;
table->abfd = abfd;
table->comp_dir = unit->comp_dir;
table->num_files = 0;
table->files = NULL;
table->num_dirs = 0;
table->dirs = NULL;
table->num_sequences = 0;
table->sequences = NULL;
table->lcl_head = NULL;
if (stash->dwarf_line_size < 16)
{
_bfd_error_handler
(_("Dwarf Error: Line info section is too small (%Ld)"),
stash->dwarf_line_size);
bfd_set_error (bfd_error_bad_value);
return NULL;
}
line_ptr = stash->dwarf_line_buffer + unit->line_offset;
line_end = stash->dwarf_line_buffer + stash->dwarf_line_size;
lh.total_length = read_4_bytes (abfd, line_ptr, line_end);
line_ptr += 4;
offset_size = 4;
if (lh.total_length == 0xffffffff)
{
lh.total_length = read_8_bytes (abfd, line_ptr, line_end);
line_ptr += 8;
offset_size = 8;
}
else if (lh.total_length == 0 && unit->addr_size == 8)
{
lh.total_length = read_4_bytes (abfd, line_ptr, line_end);
line_ptr += 4;
offset_size = 8;
}
if (lh.total_length > (size_t) (line_end - line_ptr))
{
_bfd_error_handler
(_("Dwarf Error: Line info data is bigger (%#Lx)"
" than the space remaining in the section (%#lx)"),
lh.total_length, (unsigned long) (line_end - line_ptr));
bfd_set_error (bfd_error_bad_value);
return NULL;
}
line_end = line_ptr + lh.total_length;
lh.version = read_2_bytes (abfd, line_ptr, line_end);
if (lh.version < 2 || lh.version > 5)
{
_bfd_error_handler
(_("Dwarf Error: Unhandled .debug_line version %d."), lh.version);
bfd_set_error (bfd_error_bad_value);
return NULL;
}
line_ptr += 2;
if (line_ptr + offset_size + (lh.version >= 5 ? 8 : (lh.version >= 4 ? 6 : 5))
>= line_end)
{
_bfd_error_handler
(_("Dwarf Error: Ran out of room reading prologue"));
bfd_set_error (bfd_error_bad_value);
return NULL;
}
if (lh.version >= 5)
{
unsigned int segment_selector_size;
read_1_byte (abfd, line_ptr, line_end);
line_ptr += 1;
segment_selector_size = read_1_byte (abfd, line_ptr, line_end);
line_ptr += 1;
if (segment_selector_size != 0)
{
_bfd_error_handler
(_("Dwarf Error: Line info unsupported segment selector size %u."),
segment_selector_size);
bfd_set_error (bfd_error_bad_value);
return NULL;
}
}
if (offset_size == 4)
lh.prologue_length = read_4_bytes (abfd, line_ptr, line_end);
else
lh.prologue_length = read_8_bytes (abfd, line_ptr, line_end);
line_ptr += offset_size;
lh.minimum_instruction_length = read_1_byte (abfd, line_ptr, line_end);
line_ptr += 1;
if (lh.version >= 4)
{
lh.maximum_ops_per_insn = read_1_byte (abfd, line_ptr, line_end);
line_ptr += 1;
}
else
lh.maximum_ops_per_insn = 1;
if (lh.maximum_ops_per_insn == 0)
{
_bfd_error_handler
(_("Dwarf Error: Invalid maximum operations per instruction."));
bfd_set_error (bfd_error_bad_value);
return NULL;
}
lh.default_is_stmt = read_1_byte (abfd, line_ptr, line_end);
line_ptr += 1;
lh.line_base = read_1_signed_byte (abfd, line_ptr, line_end);
line_ptr += 1;
lh.line_range = read_1_byte (abfd, line_ptr, line_end);
line_ptr += 1;
lh.opcode_base = read_1_byte (abfd, line_ptr, line_end);
line_ptr += 1;
if (line_ptr + (lh.opcode_base - 1) >= line_end)
{
_bfd_error_handler (_("Dwarf Error: Ran out of room reading opcodes"));
bfd_set_error (bfd_error_bad_value);
return NULL;
}
amt = lh.opcode_base * sizeof (unsigned char);
lh.standard_opcode_lengths = (unsigned char *) bfd_alloc (abfd, amt);
lh.standard_opcode_lengths[0] = 1;
for (i = 1; i < lh.opcode_base; ++i)
{
lh.standard_opcode_lengths[i] = read_1_byte (abfd, line_ptr, line_end);
line_ptr += 1;
}
if (lh.version >= 5)
{
if (!read_formatted_entries (unit, &line_ptr, line_end, table,
line_info_add_include_dir_stub))
goto fail;
if (!read_formatted_entries (unit, &line_ptr, line_end, table,
line_info_add_file_name))
goto fail;
}
else
{
while ((cur_dir = read_string (abfd, line_ptr, line_end, &bytes_read)) != NULL)
{
line_ptr += bytes_read;
if (!line_info_add_include_dir (table, cur_dir))
goto fail;
}
line_ptr += bytes_read;
while ((cur_file = read_string (abfd, line_ptr, line_end, &bytes_read)) != NULL)
{
unsigned int dir, xtime, size;
line_ptr += bytes_read;
dir = _bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read, FALSE, line_end);
line_ptr += bytes_read;
xtime = _bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read, FALSE, line_end);
line_ptr += bytes_read;
size = _bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read, FALSE, line_end);
line_ptr += bytes_read;
if (!line_info_add_file_name (table, cur_file, dir, xtime, size))
goto fail;
}
line_ptr += bytes_read;
}
while (line_ptr < line_end)
{
bfd_vma address = 0;
unsigned char op_index = 0;
char * filename = table->num_files ? concat_filename (table, 1) : NULL;
unsigned int line = 1;
unsigned int column = 0;
unsigned int discriminator = 0;
int is_stmt = lh.default_is_stmt;
int end_sequence = 0;
bfd_vma low_pc  = (bfd_vma) -1;
bfd_vma high_pc = 0;
while (! end_sequence)
{
op_code = read_1_byte (abfd, line_ptr, line_end);
line_ptr += 1;
if (op_code >= lh.opcode_base)
{
adj_opcode = op_code - lh.opcode_base;
if (lh.line_range == 0)
goto line_fail;
if (lh.maximum_ops_per_insn == 1)
address += (adj_opcode / lh.line_range
* lh.minimum_instruction_length);
else
{
address += ((op_index + adj_opcode / lh.line_range)
/ lh.maximum_ops_per_insn
* lh.minimum_instruction_length);
op_index = ((op_index + adj_opcode / lh.line_range)
% lh.maximum_ops_per_insn);
}
line += lh.line_base + (adj_opcode % lh.line_range);
if (!add_line_info (table, address, op_index, filename,
line, column, discriminator, 0))
goto line_fail;
discriminator = 0;
if (address < low_pc)
low_pc = address;
if (address > high_pc)
high_pc = address;
}
else switch (op_code)
{
case DW_LNS_extended_op:
exop_len = _bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read,
FALSE, line_end);
line_ptr += bytes_read;
extended_op = read_1_byte (abfd, line_ptr, line_end);
line_ptr += 1;
switch (extended_op)
{
case DW_LNE_end_sequence:
end_sequence = 1;
if (!add_line_info (table, address, op_index, filename, line,
column, discriminator, end_sequence))
goto line_fail;
discriminator = 0;
if (address < low_pc)
low_pc = address;
if (address > high_pc)
high_pc = address;
if (!arange_add (unit, &unit->arange, low_pc, high_pc))
goto line_fail;
break;
case DW_LNE_set_address:
address = read_address (unit, line_ptr, line_end);
op_index = 0;
line_ptr += unit->addr_size;
break;
case DW_LNE_define_file:
cur_file = read_string (abfd, line_ptr, line_end, &bytes_read);
line_ptr += bytes_read;
if ((table->num_files % FILE_ALLOC_CHUNK) == 0)
{
struct fileinfo *tmp;
amt = table->num_files + FILE_ALLOC_CHUNK;
amt *= sizeof (struct fileinfo);
tmp = (struct fileinfo *) bfd_realloc (table->files, amt);
if (tmp == NULL)
goto line_fail;
table->files = tmp;
}
table->files[table->num_files].name = cur_file;
table->files[table->num_files].dir =
_bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read,
FALSE, line_end);
line_ptr += bytes_read;
table->files[table->num_files].time =
_bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read,
FALSE, line_end);
line_ptr += bytes_read;
table->files[table->num_files].size =
_bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read,
FALSE, line_end);
line_ptr += bytes_read;
table->num_files++;
break;
case DW_LNE_set_discriminator:
discriminator =
_bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read,
FALSE, line_end);
line_ptr += bytes_read;
break;
case DW_LNE_HP_source_file_correlation:
line_ptr += exop_len - 1;
break;
default:
_bfd_error_handler
(_("Dwarf Error: mangled line number section."));
bfd_set_error (bfd_error_bad_value);
line_fail:
if (filename != NULL)
free (filename);
goto fail;
}
break;
case DW_LNS_copy:
if (!add_line_info (table, address, op_index,
filename, line, column, discriminator, 0))
goto line_fail;
discriminator = 0;
if (address < low_pc)
low_pc = address;
if (address > high_pc)
high_pc = address;
break;
case DW_LNS_advance_pc:
if (lh.maximum_ops_per_insn == 1)
address += (lh.minimum_instruction_length
* _bfd_safe_read_leb128 (abfd, line_ptr,
&bytes_read,
FALSE, line_end));
else
{
bfd_vma adjust = _bfd_safe_read_leb128 (abfd, line_ptr,
&bytes_read,
FALSE, line_end);
address = ((op_index + adjust) / lh.maximum_ops_per_insn
* lh.minimum_instruction_length);
op_index = (op_index + adjust) % lh.maximum_ops_per_insn;
}
line_ptr += bytes_read;
break;
case DW_LNS_advance_line:
line += _bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read,
TRUE, line_end);
line_ptr += bytes_read;
break;
case DW_LNS_set_file:
{
unsigned int file;
file = _bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read,
FALSE, line_end);
line_ptr += bytes_read;
if (filename)
free (filename);
filename = concat_filename (table, file);
break;
}
case DW_LNS_set_column:
column = _bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read,
FALSE, line_end);
line_ptr += bytes_read;
break;
case DW_LNS_negate_stmt:
is_stmt = (!is_stmt);
break;
case DW_LNS_set_basic_block:
break;
case DW_LNS_const_add_pc:
if (lh.line_range == 0)
goto line_fail;
if (lh.maximum_ops_per_insn == 1)
address += (lh.minimum_instruction_length
* ((255 - lh.opcode_base) / lh.line_range));
else
{
bfd_vma adjust = ((255 - lh.opcode_base) / lh.line_range);
address += (lh.minimum_instruction_length
* ((op_index + adjust)
/ lh.maximum_ops_per_insn));
op_index = (op_index + adjust) % lh.maximum_ops_per_insn;
}
break;
case DW_LNS_fixed_advance_pc:
address += read_2_bytes (abfd, line_ptr, line_end);
op_index = 0;
line_ptr += 2;
break;
default:
for (i = 0; i < lh.standard_opcode_lengths[op_code]; i++)
{
(void) _bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read,
FALSE, line_end);
line_ptr += bytes_read;
}
break;
}
}
if (filename)
free (filename);
}
if (sort_line_sequences (table))
return table;
fail:
while (table->sequences != NULL)
{
struct line_sequence* seq = table->sequences;
table->sequences = table->sequences->prev_sequence;
free (seq);
}
if (table->files != NULL)
free (table->files);
if (table->dirs != NULL)
free (table->dirs);
return NULL;
}

static  void  FTPs_ProcessCtrlCmd (FTPs_SESSION_STRUCT  *ftp_session)
{
CPU_CHAR       *p_cmd_arg;
CPU_CHAR       *p_file_time;
void           *p_file;
void           *p_dir;
NET_FS_ENTRY    dirent;
CPU_INT32U      path_name_len;
CPU_INT08U     *p_addr;
CPU_INT08U     *p_port;
NET_IPv4_ADDR   addr;
NET_PORT_NBR    port;
CPU_INT16S      cmp_val;
CPU_BOOLEAN     dig;
CPU_BOOLEAN     rtn_val;
CPU_INT32U      i;
NET_ERR         net_err;
CPU_SR_ALLOC();
p_dir = (void *)0;
switch (ftp_session->CtrlCmd) {
case FTP_CMD_NOOP:
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_OKAY, (CPU_CHAR *)0);
break;
case FTP_CMD_QUIT:
FTPs_StopPasvMode(ftp_session);
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_SERVERCLOSING, (CPU_CHAR *)0);
break;
case FTP_CMD_REIN:
FTPs_StopPasvMode(ftp_session);
ftp_session->CtrlState = FTPs_STATE_LOGOUT;
ftp_session->DtpMode   = FTP_MODE_STREAM;
ftp_session->DtpType   = FTP_TYPE_ASCII;
ftp_session->DtpForm   = FTP_FORM_NONPRINT;
ftp_session->DtpStru   = FTP_STRU_FILE;
ftp_session->DtpCmd    = FTP_CMD_NOOP;
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_OKAY, (CPU_CHAR *)0);
break;
case FTP_CMD_SYST:
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_SYSTEMTYPE, (CPU_CHAR *)0);
break;
case FTP_CMD_FEAT:
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_SYSTEMSTATUS, (CPU_CHAR *)0);
break;
case FTP_CMD_HELP:
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_HELPMESSAGE, (CPU_CHAR *)0);
break;
case FTP_CMD_USER:
p_cmd_arg = FTPs_FindArg(&ftp_session->CtrlCmdArgs);
if (*p_cmd_arg != (CPU_CHAR)0) {
Str_Copy_N(ftp_session->User, p_cmd_arg, sizeof(ftp_session->User));
ftp_session->CtrlState = FTPs_STATE_GOTUSER;
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_NEEDPASSWORD, (CPU_CHAR *)0);
} else {
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_PARMSYNTAXERR, (CPU_CHAR *)0);
}
break;
case FTP_CMD_PASS:
p_cmd_arg = FTPs_FindArg(&ftp_session->CtrlCmdArgs);
if (*p_cmd_arg != (CPU_CHAR)0) {
Str_Copy_N(ftp_session->Pass, p_cmd_arg, sizeof(ftp_session->Pass));
rtn_val = FTPs_AuthUser(ftp_session);
if (rtn_val == DEF_OK) {
ftp_session->CtrlState = FTPs_STATE_LOGIN;
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_LOGGEDIN, (CPU_CHAR *)0);
} else {
ftp_session->CtrlState = FTPs_STATE_LOGOUT;
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_NOTLOGGEDIN, (CPU_CHAR *)0);
}
} else {
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_PARMSYNTAXERR, (CPU_CHAR *)0);
}
break;
case FTP_CMD_MODE:
p_cmd_arg = FTPs_FindArg(&ftp_session->CtrlCmdArgs);
switch (*p_cmd_arg) {
case FTP_MODE_STREAM:
ftp_session->DtpMode = FTP_MODE_STREAM;
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_OKAY, (CPU_CHAR *)0);
break;
case FTP_MODE_BLOCK:
case FTP_MODE_COMPRESSED:
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_PARMNOSUPPORT, (CPU_CHAR *)0);
break;
default:
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_PARMSYNTAXERR, (CPU_CHAR *)0);
break;
}
break;
case FTP_CMD_TYPE:
p_cmd_arg = FTPs_FindArg(&ftp_session->CtrlCmdArgs);
switch (*p_cmd_arg) {
case FTP_TYPE_ASCII:
p_cmd_arg = FTPs_FindArg(&ftp_session->CtrlCmdArgs);
switch (*p_cmd_arg) {
case (CPU_CHAR)0:
case FTP_FORM_NONPRINT:
ftp_session->DtpType = FTP_TYPE_ASCII;
ftp_session->DtpForm = FTP_FORM_NONPRINT;
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_OKAY, (CPU_CHAR *)0);
break;
case FTP_FORM_TELNET:
case FTP_FORM_CARGCTRL:
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_PARMNOSUPPORT, (CPU_CHAR *)0);
break;
default:
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_PARMSYNTAXERR, (CPU_CHAR *)0);
break;
}
break;
case FTP_TYPE_IMAGE:
ftp_session->DtpType = FTP_TYPE_IMAGE;
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_OKAY, (CPU_CHAR *)0);
break;
case FTP_TYPE_LOCAL:
case FTP_TYPE_EBCDIC:
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_PARMNOSUPPORT, (CPU_CHAR *)0);
break;
default:
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_PARMSYNTAXERR, (CPU_CHAR *)0);
break;
}
break;
case FTP_CMD_STRU:
p_cmd_arg = FTPs_FindArg(&ftp_session->CtrlCmdArgs);
switch (*p_cmd_arg) {
case FTP_STRU_FILE:
ftp_session->DtpStru = FTP_STRU_FILE;
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_OKAY, (CPU_CHAR *)0);
break;
case FTP_STRU_RECORD:
case FTP_STRU_PAGE:
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_PARMNOSUPPORT, (CPU_CHAR *)0);
break;
default:
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_PARMSYNTAXERR, (CPU_CHAR *)0);
break;
}
break;
case FTP_CMD_PASV:
CPU_CRITICAL_ENTER();
addr = FTPs_PublicAddr;
port = FTPs_PublicPort;
CPU_CRITICAL_EXIT();
ftp_session->DtpSockAddr.Addr = NET_UTIL_HOST_TO_NET_32(NET_IPv4_ADDR_ANY);
ftp_session->DtpSockAddr.Port = NET_UTIL_HOST_TO_NET_16(port);
FTPs_StartPasvMode(ftp_session, &net_err);
if (ftp_session->DtpPasv == DEF_YES) {
addr = NET_UTIL_HOST_TO_NET_32(addr);
port = NET_UTIL_HOST_TO_NET_16(port);
p_addr = (CPU_INT08U *)&addr;
p_port = (CPU_INT08U *)&port;
Str_FmtPrint((char       *)FTPs_NetBufCtrlCmdPtr,
FTPs_NET_BUF_LEN,
(char       *)FTPs_Reply[FTP_REPLY_ENTERPASVMODE].ReplyStr,
(unsigned int)p_addr[0],
(unsigned int)p_addr[1],
(unsigned int)p_addr[2],
(unsigned int)p_addr[3],
(unsigned int)p_port[0],
(unsigned int)p_port[1]);
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_ENTERPASVMODE, FTPs_NetBufCtrlCmdPtr);
} else {
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_CANTOPENDATA, (CPU_CHAR *)0);
}
break;
case FTP_CMD_PORT:
FTPs_StopPasvMode(ftp_session);
if (ftp_session->DtpPasv == DEF_NO) {
p_addr = (CPU_INT08U *)&ftp_session->DtpSockAddr.Addr;
p_port = (CPU_INT08U *)&ftp_session->DtpSockAddr.Port;
for (i = 0; i <= 3; i++) {
dig = ASCII_IsDig(*ftp_session->CtrlCmdArgs);
while ((dig == DEF_NO) && (ftp_session->CtrlCmdArgs != (CPU_CHAR *)0)) {
ftp_session->CtrlCmdArgs++;
dig = ASCII_IsDig(*ftp_session->CtrlCmdArgs);
}
p_addr[i] = Str_ParseNbr_Int32U(ftp_session->CtrlCmdArgs, &ftp_session->CtrlCmdArgs, 10);
}
for (i = 0; i <= 1; i++) {
dig = ASCII_IsDig(*ftp_session->CtrlCmdArgs);
while ((dig == DEF_NO) && (ftp_session->CtrlCmdArgs != 0)) {
ftp_session->CtrlCmdArgs++;
dig = ASCII_IsDig(*ftp_session->CtrlCmdArgs);
}
p_port[i] = Str_ParseNbr_Int32U(ftp_session->CtrlCmdArgs, &ftp_session->CtrlCmdArgs, 10);
}
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_OKAY, (CPU_CHAR *)0);
} else {
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_CANTOPENDATA, (CPU_CHAR *)0);
}
break;
case FTP_CMD_REST:
p_cmd_arg = FTPs_FindArg(&ftp_session->CtrlCmdArgs);
if (*p_cmd_arg != (CPU_CHAR)0) {
ftp_session->DtpOffset = Str_ParseNbr_Int32U(p_cmd_arg, 0, 10);
ftp_session->CtrlState = FTPs_STATE_GOTREST;
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_NEEDMOREINFO, (CPU_CHAR *)0);
}
break;
case FTP_CMD_PWD:
case FTP_CMD_CWD:
case FTP_CMD_CDUP:
case FTP_CMD_MKD:
case FTP_CMD_RMD:
case FTP_CMD_NLST:
case FTP_CMD_LIST:
case FTP_CMD_RETR:
case FTP_CMD_STOR:
case FTP_CMD_APPE:
case FTP_CMD_DELE:
case FTP_CMD_RNFR:
case FTP_CMD_RNTO:
case FTP_CMD_SIZE:
case FTP_CMD_MDTM:
if (ftp_session->CtrlCmd == FTP_CMD_PWD) {
p_cmd_arg = (CPU_CHAR *)".";
} else if (ftp_session->CtrlCmd == FTP_CMD_CDUP) {
p_cmd_arg = (CPU_CHAR *)"..";
} else if (ftp_session->CtrlCmd == FTP_CMD_MDTM) {
p_cmd_arg   = FTPs_FindFileName(&ftp_session->CtrlCmdArgs);
p_file_time = FTPs_FindArg(&ftp_session->CtrlCmdArgs);
cmp_val = Str_Len(p_file_time);
if (cmp_val == 14) {
for (i = 0; i < 14; i++) {
dig = ASCII_IsDig(p_file_time[i]);
if (dig == DEF_NO) {
break;
}
}
if (i == 14) {
p_cmd_arg = FTPs_FindFileName(&ftp_session->CtrlCmdArgs);
} else {
p_file_time = "";
}
} else {
p_file_time = "";
}
} else {
p_cmd_arg = FTPs_FindFileName(&ftp_session->CtrlCmdArgs);
}
if (*p_cmd_arg != (CPU_CHAR)0) {
FTPs_ToFTPStylePath(p_cmd_arg);
}
if (*p_cmd_arg == '-') {
p_cmd_arg = (CPU_CHAR *)".";
}
path_name_len = NetFS_CfgPathGetLenMax();
rtn_val = FTPs_BuildPath(FTPs_FullAbsPathPtr,   path_name_len,
FTPs_FullRelPathPtr,   path_name_len,
FTPs_ParentAbsPathPtr, path_name_len,
FTPs_CurEntryPtr,      path_name_len,
ftp_session->BasePath,
ftp_session->RelPath,
p_cmd_arg);
FTPs_ToFSStylePath(FTPs_FullAbsPathPtr);
FTPs_ToFSStylePath(FTPs_ParentAbsPathPtr);
if (rtn_val == DEF_OK) {
switch (ftp_session->CtrlCmd) {
case FTP_CMD_PWD:
case FTP_CMD_CWD:
case FTP_CMD_CDUP:
case FTP_CMD_RMD:
case FTP_CMD_NLST:
case FTP_CMD_LIST:
p_dir = NetFS_DirOpen(FTPs_FullAbsPathPtr);
if (p_dir == (void *)0) {
rtn_val = DEF_FAIL;
} else {
rtn_val = DEF_OK;
}
NetFS_DirClose(p_dir);
break;
case FTP_CMD_DELE:
p_dir = NetFS_DirOpen(FTPs_ParentAbsPathPtr);
if (p_dir == (void *)0) {
rtn_val = DEF_FAIL;
}
NetFS_DirClose(p_dir);
break;
case FTP_CMD_MKD:
case FTP_CMD_RETR:
case FTP_CMD_STOR:
case FTP_CMD_APPE:
case FTP_CMD_RNFR:
case FTP_CMD_RNTO:
case FTP_CMD_SIZE:
case FTP_CMD_MDTM:
p_file = NetFS_FileOpen(FTPs_FullAbsPathPtr,
NET_FS_FILE_MODE_OPEN,
NET_FS_FILE_ACCESS_RD);
if (p_file != (void *)0) {
switch (ftp_session->CtrlCmd) {
case FTP_CMD_MKD:
case FTP_CMD_APPE:
case FTP_CMD_RNTO:
rtn_val = DEF_FAIL;
break;
case FTP_CMD_SIZE:
NetFS_FileSizeGet(p_file, &dirent.Size);
break;
case FTP_CMD_MDTM:
NetFS_FileDateTimeCreateGet(p_file, &dirent.DateTimeCreate);
break;
default:
rtn_val = DEF_OK;
break;
}
NetFS_FileClose(p_file);
} else {
switch (ftp_session->CtrlCmd) {
case FTP_CMD_MKD:
case FTP_CMD_STOR:
case FTP_CMD_APPE:
case FTP_CMD_RNTO:
rtn_val = DEF_OK;
break;
default:
rtn_val = DEF_FAIL;
break;
}
}
break;
default:
break;
}
if (rtn_val == DEF_OK) {
switch (ftp_session->CtrlCmd) {
case FTP_CMD_PWD:
Str_FmtPrint((char *)FTPs_NetBufCtrlCmdPtr,
FTPs_NET_BUF_LEN,
(char *)"257 \"%s\" is current directory.",
FTPs_FullRelPathPtr);
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_PATHNAME, FTPs_NetBufCtrlCmdPtr);
break;
case FTP_CMD_CWD:
case FTP_CMD_CDUP:
Str_Copy_N(ftp_session->RelPath,  FTPs_FullRelPathPtr, FTPs_CFG_FS_PATH_LEN_MAX);
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_ACTIONCOMPLETE, (CPU_CHAR *)0);
break;
case FTP_CMD_NLST:
case FTP_CMD_LIST:
case FTP_CMD_RETR:
case FTP_CMD_STOR:
case FTP_CMD_APPE:
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_OKAYOPENING, (CPU_CHAR *)0);
ftp_session->DtpCmd = ftp_session->CtrlCmd;
Str_Copy_N(ftp_session->CurEntry, FTPs_FullAbsPathPtr, FTPs_CFG_FS_PATH_LEN_MAX);
FTPs_DtpTask((void *)ftp_session);
ftp_session->DtpOffset = 0;
ftp_session->CtrlState = FTPs_STATE_LOGIN;
break;
case FTP_CMD_MKD:
rtn_val = NetFS_EntryCreate(FTPs_FullAbsPathPtr, DEF_YES);
if (rtn_val == DEF_OK) {
Str_FmtPrint((char *)FTPs_NetBufCtrlCmdPtr,
FTPs_NET_BUF_LEN,
(char *)FTPs_Reply[FTP_REPLY_PATHNAME].ReplyStr,
FTPs_FullRelPathPtr);
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_PATHNAME, FTPs_NetBufCtrlCmdPtr);
} else {
Str_FmtPrint((char *)FTPs_NetBufCtrlCmdPtr,
FTPs_NET_BUF_LEN,
(char *)FTPs_Reply[FTP_REPLY_NOTFOUND].ReplyStr,
FTPs_FullRelPathPtr);
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_NOTFOUND, FTPs_NetBufCtrlCmdPtr);
}
break;
case FTP_CMD_RMD:
rtn_val = NetFS_EntryDel(FTPs_FullAbsPathPtr, DEF_NO);
if (rtn_val == DEF_OK) {
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_ACTIONCOMPLETE, (CPU_CHAR *)0);
} else {
Str_FmtPrint((char *)FTPs_NetBufCtrlCmdPtr,
FTPs_NET_BUF_LEN,
(char *)FTPs_Reply[FTP_REPLY_NOTFOUND].ReplyStr,
FTPs_FullRelPathPtr);
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_NOTFOUND, FTPs_NetBufCtrlCmdPtr);
}
break;
case FTP_CMD_DELE:
rtn_val = NetFS_EntryDel(FTPs_FullAbsPathPtr, DEF_YES);
if (rtn_val == DEF_OK) {
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_ACTIONCOMPLETE, (CPU_CHAR *)0);
} else {
Str_FmtPrint((char *)FTPs_NetBufCtrlCmdPtr,
FTPs_NET_BUF_LEN,
(char *)FTPs_Reply[FTP_REPLY_NOTFOUND].ReplyStr,
FTPs_FullRelPathPtr);
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_NOTFOUND, FTPs_NetBufCtrlCmdPtr);
}
break;
case FTP_CMD_RNFR:
Str_Copy_N(FTPs_RenAbsPathPtr, FTPs_FullAbsPathPtr, FTPs_CFG_FS_PATH_LEN_MAX);
Str_Copy_N(FTPs_RenRelPathPtr, FTPs_FullRelPathPtr, FTPs_CFG_FS_PATH_LEN_MAX);
ftp_session->CtrlState = FTPs_STATE_GOTRNFR;
FTPs_SendReply(ftp_session->CtrlSockID, FTP_REPLY_NEEDMOREINFO, (CPU_CHAR *)0);
break;
case FTP_CMD_RNTO:
