{
ThrowFileException(exception,CacheError,"UnableToExtendCache",
image->filename);
return(MagickFalse);
}
length=number_pixels*(cache_info->number_channels*sizeof(Quantum)+
cache_info->metacontent_extent);
if (length != (MagickSizeType) ((size_t) length))
cache_info->type=DiskCache;
else
{
status=AcquireMagickResource(MapResource,cache_info->length);
if ((status == MagickFalse) && (cache_info->type != MapCache) &&
(cache_info->type != MemoryCache))
cache_info->type=DiskCache;
else
{
cache_info->pixels=(Quantum *) MapBlob(cache_info->file,mode,
cache_info->offset,(size_t) cache_info->length);
if (cache_info->pixels == (Quantum *) NULL)
{
cache_info->type=DiskCache;
cache_info->pixels=source_info.pixels;
}
else
{
status=MagickTrue;
(void) ClosePixelCacheOnDisk(cache_info);
cache_info->type=MapCache;
cache_info->mapped=MagickTrue;
cache_info->metacontent=(void *) NULL;
if (cache_info->metacontent_extent != 0)
cache_info->metacontent=(void *) (cache_info->pixels+
number_pixels*cache_info->number_channels);
if ((source_info.storage_class != UndefinedClass) &&
(mode != ReadMode))
{
status=ClonePixelCacheRepository(cache_info,&source_info,
exception);
RelinquishPixelCachePixels(&source_info);
}
if (image->debug != MagickFalse)
{
(void) FormatMagickSize(cache_info->length,MagickTrue,"B",
MagickPathExtent,format);
type=CommandOptionToMnemonic(MagickCacheOptions,(ssize_t)
cache_info->type);
(void) FormatLocaleString(message,MagickPathExtent,
"open %s (%s[%d], %s, %.20gx%.20gx%.20g %s)",
cache_info->filename,cache_info->cache_filename,
cache_info->file,type,(double) cache_info->columns,(double)
cache_info->rows,(double) cache_info->number_channels,
format);
(void) LogMagickEvent(CacheEvent,GetMagickModule(),"%s",
message);
}
return(status);
}
}
RelinquishMagickResource(MapResource,cache_info->length);
}
status=MagickTrue;
if ((source_info.storage_class != UndefinedClass) && (mode != ReadMode))
{
status=ClonePixelCacheRepository(cache_info,&source_info,exception);
RelinquishPixelCachePixels(&source_info);
}
if (image->debug != MagickFalse)
{
(void) FormatMagickSize(cache_info->length,MagickFalse,"B",
MagickPathExtent,format);
type=CommandOptionToMnemonic(MagickCacheOptions,(ssize_t)
cache_info->type);
(void) FormatLocaleString(message,MagickPathExtent,
"open %s (%s[%d], %s, %.20gx%.20gx%.20g %s)",cache_info->filename,
cache_info->cache_filename,cache_info->file,type,(double)
cache_info->columns,(double) cache_info->rows,(double)
cache_info->number_channels,format);
(void) LogMagickEvent(CacheEvent,GetMagickModule(),"%s",message);
}
return(status);
}

Host* NetworkInterface::getHost(char *host_ip, u_int16_t vlan_id) {
struct in_addr  a4;
struct in6_addr a6;
Host *h = NULL;
if((inet_pton(AF_INET, (const char*)host_ip, &a4) == 0)
&& (inet_pton(AF_INET6, (const char*)host_ip, &a6) == 0)) {
struct host_find_info info;
memset(&info, 0, sizeof(info));
info.host_to_find = host_ip, info.vlan_id = vlan_id;
walker(walker_hosts, find_host_by_name, (void*)&info);
h = info.h;
} else {
IpAddress *ip = new IpAddress();
if(ip) {
ip->set(host_ip);
if(!isView())
h = hosts_hash->get(vlan_id, ip);
else {
for(u_int8_t s = 0; s<numSubInterfaces; s++) {
h = subInterfaces[s]->get_hosts_hash()->get(vlan_id, ip);
if(h) break;
}
}
delete ip;
}
}
return(h);
}

static void
gif_out_code(
gif_t            *g,
unsigned short   code
)
{
if (g->codes[code].prefix >= 0) {
gif_out_code(g, (unsigned short)g->codes[code].prefix);
}
if (g->cur_y >= g->max_y) {
return;
}
g->out[g->cur_x + g->cur_y * g->line_size] = g->codes[code].suffix;
if (g->cur_x >= g->actual_width) {
g->actual_width = g->cur_x + 1;
}
if (g->cur_y >= g->actual_height) {
g->actual_height = g->cur_y + 1;
}
g->cur_x++;
if (g->cur_x >= g->max_x) {
g->cur_x = g->start_x;
g->cur_y += g->step;
while (g->cur_y >= g->max_y && g->parse > 0) {
g->step = 1 << g->parse;
g->cur_y = g->start_y + (g->step >> 1);
--g->parse;
}
}
}

static int ahci_dma_rw_buf(IDEDMA *dma, int is_write)
{
AHCIDevice *ad = DO_UPCAST(AHCIDevice, dma, dma);
IDEState *s = &ad->port.ifs[0];
uint8_t *p = s->io_buffer + s->io_buffer_index;
int l = s->io_buffer_size - s->io_buffer_index;
if (ahci_populate_sglist(ad, &s->sg, s->io_buffer_offset)) {
return 0;
}
if (is_write) {
dma_buf_read(p, l, &s->sg);
} else {
dma_buf_write(p, l, &s->sg);
}
qemu_sglist_destroy(&s->sg);
ad->cur_cmd->status = cpu_to_le32(le32_to_cpu(ad->cur_cmd->status) + l);
s->io_buffer_index += l;
s->io_buffer_offset += l;
DPRINTF(ad->port_no, "len=%#x\n", l);
return 1;
}

bool
XmlRpcClient::readHeader()
{
if ( ! XmlRpcSocket::nbRead(this->getfd(), _header, &_eof) ||
(_eof && _header.length() == 0)) {
if (getKeepOpen() && _header.length() == 0 && _sendAttempts++ == 0) {
XmlRpcUtil::log(4, "XmlRpcClient::readHeader: re-trying connection");
XmlRpcSource::close();
_connectionState = NO_CONNECTION;
_eof = false;
return setupConnection();
}
XmlRpcUtil::error("Error in XmlRpcClient::readHeader: error while reading "
"header (%s) on fd %d.",
XmlRpcSocket::getErrorMsg().c_str(), getfd());
close();
return false;
}
XmlRpcUtil::log(4, "XmlRpcClient::readHeader: client has read %d bytes", _header.length());
char *hp = (char*)_header.c_str();    char *ep = hp + _header.length();     char *bp = 0;                         char *lp = 0;                       
for (char *cp = hp; (bp == 0) && (cp < ep); ++cp) {
if ((ep - cp > 16) && (strncasecmp(cp, "Content-length: ", 16) == 0))
lp = cp + 16;
else if ((ep - cp > 4) && (strncmp(cp, "\r\n\r\n", 4) == 0))
bp = cp + 4;
else if ((ep - cp > 2) && (strncmp(cp, "\n\n", 2) == 0))
bp = cp + 2;
}
if (bp == 0) {
if (_eof)              {
XmlRpcUtil::error("Error in XmlRpcClient::readHeader: EOF while reading header");
close();
return false;       }
return true;    }
if (lp == 0) {
XmlRpcUtil::error("Error XmlRpcClient::readHeader: No Content-length specified");
close();
return false;     }
_contentLength = atoi(lp);
if (_contentLength <= 0) {
XmlRpcUtil::error("Error in XmlRpcClient::readHeader: Invalid Content-length specified (%d).", _contentLength);
close();
return false;
}
XmlRpcUtil::log(4, "client read content length: %d", _contentLength);
_response = bp;
_header = "";     _connectionState = READ_RESPONSE;
return true;    }

static gboolean
imapx_connect_to_server (CamelIMAPXServer *is,
GCancellable *cancellable,
GError **error)
{
CamelNetworkSettings *network_settings;
CamelNetworkSecurityMethod method;
CamelIMAPXStore *store;
CamelSettings *settings;
GIOStream *connection = NULL;
GIOStream *tls_stream;
GSocket *socket;
guint len;
guchar *token;
gint tok;
CamelIMAPXCommand *ic;
gchar *shell_command = NULL;
gboolean use_shell_command;
gboolean success = TRUE;
gchar *host;
GError *local_error = NULL;
store = camel_imapx_server_ref_store (is);
settings = camel_service_ref_settings (CAMEL_SERVICE (store));
network_settings = CAMEL_NETWORK_SETTINGS (settings);
host = camel_network_settings_dup_host (network_settings);
method = camel_network_settings_get_security_method (network_settings);
use_shell_command = camel_imapx_settings_get_use_shell_command (
CAMEL_IMAPX_SETTINGS (settings));
if (use_shell_command)
shell_command = camel_imapx_settings_dup_shell_command (
CAMEL_IMAPX_SETTINGS (settings));
g_object_unref (settings);
if (shell_command != NULL) {
success = connect_to_server_process (is, shell_command, error);
g_free (shell_command);
if (success)
goto connected;
else
goto exit;
}
connection = camel_network_service_connect_sync (
CAMEL_NETWORK_SERVICE (store), cancellable, error);
if (connection != NULL) {
GInputStream *input_stream;
GOutputStream *output_stream;
socket = g_socket_connection_get_socket (
G_SOCKET_CONNECTION (connection));
g_socket_set_option (
socket, IPPROTO_TCP, TCP_NODELAY, 1, &local_error);
if (local_error != NULL) {
g_warning ("%s: %s", G_STRFUNC, local_error->message);
g_clear_error (&local_error);
}
g_mutex_lock (&is->priv->stream_lock);
g_warn_if_fail (is->priv->connection == NULL);
is->priv->connection = g_object_ref (connection);
g_mutex_unlock (&is->priv->stream_lock);
input_stream = g_io_stream_get_input_stream (connection);
output_stream = g_io_stream_get_output_stream (connection);
imapx_server_set_streams (is, input_stream, output_stream);
} else {
success = FALSE;
goto exit;
}
connected:
while (1) {
GInputStream *input_stream;
input_stream = camel_imapx_server_ref_input_stream (is);
token = NULL;
tok = camel_imapx_input_stream_token (
CAMEL_IMAPX_INPUT_STREAM (input_stream),
&token, &len, cancellable, error);
if (tok < 0) {
success = FALSE;
} else if (tok == '*') {
success = imapx_untagged (
is, input_stream, cancellable, error);
if (success) {
g_object_unref (input_stream);
break;
}
} else {
camel_imapx_input_stream_ungettoken (
CAMEL_IMAPX_INPUT_STREAM (input_stream),
tok, token, len);
success = camel_imapx_input_stream_text (
CAMEL_IMAPX_INPUT_STREAM (input_stream),
&token, cancellable, error);
g_free (token);
}
g_object_unref (input_stream);
if (!success)
goto exit;
}
g_mutex_lock (&is->priv->stream_lock);
if (!is->priv->cinfo) {
g_mutex_unlock (&is->priv->stream_lock);
ic = camel_imapx_command_new (is, CAMEL_IMAPX_JOB_CAPABILITY, "CAPABILITY");
success = camel_imapx_server_process_command_sync (is, ic, _("Failed to get capabilities"), cancellable, error);
camel_imapx_command_unref (ic);
if (!success)
goto exit;
} else {
g_mutex_unlock (&is->priv->stream_lock);
}
if (method == CAMEL_NETWORK_SECURITY_METHOD_STARTTLS_ON_STANDARD_PORT) {
g_mutex_lock (&is->priv->stream_lock);
if (CAMEL_IMAPX_LACK_CAPABILITY (is->priv->cinfo, STARTTLS)) {
g_mutex_unlock (&is->priv->stream_lock);
g_set_error (
&local_error, CAMEL_ERROR,
CAMEL_ERROR_GENERIC,
_("Failed to connect to IMAP server %s in secure mode: %s"),
host, _("STARTTLS not supported"));
goto exit;
} else {
g_mutex_unlock (&is->priv->stream_lock);
}
ic = camel_imapx_command_new (is, CAMEL_IMAPX_JOB_STARTTLS, "STARTTLS");
success = camel_imapx_server_process_command_sync (is, ic, _("Failed to issue STARTTLS"), cancellable, error);
if (success) {
g_mutex_lock (&is->priv->stream_lock);
imapx_free_capability (is->priv->cinfo);
is->priv->cinfo = NULL;
if (ic->status->condition == IMAPX_CAPABILITY) {
is->priv->cinfo = ic->status->u.cinfo;
ic->status->u.cinfo = NULL;
c (is->priv->tagprefix, "got capability flags %08x\n", is->priv->cinfo ? is->priv->cinfo->capa : 0xFFFFFFFF);
imapx_server_stash_command_arguments (is);
}
g_mutex_unlock (&is->priv->stream_lock);
}
camel_imapx_command_unref (ic);
if (!success)
goto exit;
tls_stream = camel_network_service_starttls (
CAMEL_NETWORK_SERVICE (store), connection, error);
if (tls_stream != NULL) {
GInputStream *input_stream;
GOutputStream *output_stream;
g_mutex_lock (&is->priv->stream_lock);
g_object_unref (is->priv->connection);
is->priv->connection = g_object_ref (tls_stream);
g_mutex_unlock (&is->priv->stream_lock);
input_stream =
g_io_stream_get_input_stream (tls_stream);
output_stream =
g_io_stream_get_output_stream (tls_stream);
imapx_server_set_streams (
is, input_stream, output_stream);
g_object_unref (tls_stream);
} else {
g_prefix_error (
error,
_("Failed to connect to IMAP server %s in secure mode: "),
host);
success = FALSE;
goto exit;
}
g_mutex_lock (&is->priv->stream_lock);
if (is->priv->cinfo == NULL) {
g_mutex_unlock (&is->priv->stream_lock);
ic = camel_imapx_command_new (is, CAMEL_IMAPX_JOB_CAPABILITY, "CAPABILITY");
success = camel_imapx_server_process_command_sync (is, ic, _("Failed to get capabilities"), cancellable, error);
camel_imapx_command_unref (ic);
if (!success)
goto exit;
} else {
g_mutex_unlock (&is->priv->stream_lock);
}
}
exit:
if (!success) {
g_mutex_lock (&is->priv->stream_lock);
g_clear_object (&is->priv->input_stream);
g_clear_object (&is->priv->output_stream);
g_clear_object (&is->priv->connection);
g_clear_object (&is->priv->subprocess);
if (is->priv->cinfo != NULL) {
imapx_free_capability (is->priv->cinfo);
is->priv->cinfo = NULL;
}
g_mutex_unlock (&is->priv->stream_lock);
}
g_free (host);
g_clear_object (&connection);
g_clear_object (&store);
return success;
}

