static ssize_t virtio_net_receive_rcu(NetClientState *nc, const uint8_t *buf,
size_t size, bool no_rss)
{
VirtIONet *n = qemu_get_nic_opaque(nc);
VirtIONetQueue *q = virtio_net_get_subqueue(nc);
VirtIODevice *vdev = VIRTIO_DEVICE(n);
VirtQueueElement *elems[VIRTQUEUE_MAX_SIZE];
size_t lens[VIRTQUEUE_MAX_SIZE];
struct iovec mhdr_sg[VIRTQUEUE_MAX_SIZE];
struct virtio_net_hdr_mrg_rxbuf mhdr;
unsigned mhdr_cnt = 0;
size_t offset, i, guest_offset, j;
ssize_t err;
if (!virtio_net_can_receive(nc)) {
return -1;
}
if (!no_rss && n->rss_data.enabled && n->rss_data.enabled_software_rss) {
int index = virtio_net_process_rss(nc, buf, size);
if (index >= 0) {
NetClientState *nc2 = qemu_get_subqueue(n->nic, index);
return virtio_net_receive_rcu(nc2, buf, size, true);
}
}
if (!virtio_net_has_buffers(q, size + n->guest_hdr_len - n->host_hdr_len)) {
return 0;
}
if (!receive_filter(n, buf, size))
return size;
offset = i = 0;
while (offset < size) {
VirtQueueElement *elem;
int len, total;
const struct iovec *sg;
total = 0;
if (i == VIRTQUEUE_MAX_SIZE) {
virtio_error(vdev, "virtio-net unexpected long buffer chain");
err = size;
goto err;
}
elem = virtqueue_pop(q->rx_vq, sizeof(VirtQueueElement));
if (!elem) {
if (i) {
virtio_error(vdev, "virtio-net unexpected empty queue: "
"i %zd mergeable %d offset %zd, size %zd, "
"guest hdr len %zd, host hdr len %zd "
"guest features 0x%" PRIx64,
i, n->mergeable_rx_bufs, offset, size,
n->guest_hdr_len, n->host_hdr_len,
vdev->guest_features);
}
err = -1;
goto err;
}
if (elem->in_num < 1) {
virtio_error(vdev,
"virtio-net receive queue contains no in buffers");
virtqueue_detach_element(q->rx_vq, elem, 0);
g_free(elem);
err = -1;
goto err;
}
sg = elem->in_sg;
if (i == 0) {
assert(offset == 0);
if (n->mergeable_rx_bufs) {
mhdr_cnt = iov_copy(mhdr_sg, ARRAY_SIZE(mhdr_sg),
sg, elem->in_num,
offsetof(typeof(mhdr), num_buffers),
sizeof(mhdr.num_buffers));
}
receive_header(n, sg, elem->in_num, buf, size);
if (n->rss_data.populate_hash) {
offset = sizeof(mhdr);
iov_from_buf(sg, elem->in_num, offset,
buf + offset, n->host_hdr_len - sizeof(mhdr));
}
offset = n->host_hdr_len;
total += n->guest_hdr_len;
guest_offset = n->guest_hdr_len;
} else {
guest_offset = 0;
}
len = iov_from_buf(sg, elem->in_num, guest_offset,
buf + offset, size - offset);
total += len;
offset += len;
if (!n->mergeable_rx_bufs && offset < size) {
virtqueue_unpop(q->rx_vq, elem, total);
g_free(elem);
err = size;
goto err;
}
elems[i] = elem;
lens[i] = total;
i++;
}
if (mhdr_cnt) {
virtio_stw_p(vdev, &mhdr.num_buffers, i);
iov_from_buf(mhdr_sg, mhdr_cnt,
0,
&mhdr.num_buffers, sizeof mhdr.num_buffers);
}
for (j = 0; j < i; j++) {
virtqueue_fill(q->rx_vq, elems[j], lens[j], j);
g_free(elems[j]);
}
virtqueue_flush(q->rx_vq, i);
virtio_notify(vdev, q->rx_vq);
return size;
err:
for (j = 0; j < i; j++) {
g_free(elems[j]);
}
return err;
}

CallResult<HermesValue>
hermesBuiltinApply(void *, Runtime *runtime, NativeArgs args) {
GCScopeMarkerRAII marker{runtime};
Handle<Callable> fn = args.dyncastArg<Callable>(0);
if (LLVM_UNLIKELY(!fn)) {
return runtime->raiseTypeErrorForValue(
args.getArgHandle(0), " is not a function");
}
Handle<JSArray> argArray = args.dyncastArg<JSArray>(1);
if (LLVM_UNLIKELY(!argArray)) {
return runtime->raiseTypeError("args must be an array");
}
uint32_t len = JSArray::getLength(*argArray);
bool isConstructor = args.getArgCount() == 2;
MutableHandle<> thisVal{runtime};
if (isConstructor) {
auto thisValRes = Callable::createThisForConstruct(fn, runtime);
if (LLVM_UNLIKELY(thisValRes == ExecutionStatus::EXCEPTION)) {
return ExecutionStatus::EXCEPTION;
}
thisVal = *thisValRes;
} else {
thisVal = args.getArg(2);
}
ScopedNativeCallFrame newFrame{
runtime, len, *fn, isConstructor, thisVal.getHermesValue()};
for (uint32_t i = 0; i < len; ++i) {
newFrame->getArgRef(i) = argArray->at(runtime, i);
}
return isConstructor ? Callable::construct(fn, runtime, thisVal)
: Callable::call(fn, runtime);
}

static int
allocate_trace_buffer(struct trace_array *tr, struct trace_buffer *buf, int size)
{
enum ring_buffer_flags rb_flags;
rb_flags = tr->trace_flags & TRACE_ITER_OVERWRITE ? RB_FL_OVERWRITE : 0;
buf->tr = tr;
buf->buffer = ring_buffer_alloc(size, rb_flags);
if (!buf->buffer)
return -ENOMEM;
buf->data = alloc_percpu(struct trace_array_cpu);
if (!buf->data) {
ring_buffer_free(buf->buffer);
return -ENOMEM;
}
set_buffer_entries(&tr->trace_buffer,
ring_buffer_size(tr->trace_buffer.buffer, 0));
return 0;
}

void BTM_BlePeriodicSyncTransfer(RawAddress addr, uint16_t service_data,
uint16_t sync_handle, SyncTransferCb cb) {
uint16_t conn_handle = BTM_GetHCIConnHandle(addr, BT_TRANSPORT_LE);
tACL_CONN* p_acl = btm_acl_for_bda(addr, BT_TRANSPORT_LE);
BTM_TRACE_DEBUG("[PAST]%s for connection_handle = %x", __func__, conn_handle);
if (conn_handle == 0xFFFF || p_acl == NULL) {
BTM_TRACE_ERROR("[PAST]%s:Invalid connection handle or no LE ACL link",
__func__);
cb.Run(BTM_UNKNOWN_ADDR, addr);
return;
}
if (!HCI_LE_PERIODIC_ADVERTISING_SYNC_TRANSFER_RECIPIENT(
p_acl->peer_le_features)) {
BTM_TRACE_ERROR("[PAST]%s:Remote doesn't support PAST", __func__);
cb.Run(BTM_MODE_UNSUPPORTED, addr);
return;
}
int index = btm_ble_get_free_sync_transfer_index();
tBTM_BLE_PERIODIC_SYNC_TRANSFER* p_sync_transfer =
&btm_ble_pa_sync_cb.sync_transfer[index];
p_sync_transfer->in_use = true;
p_sync_transfer->conn_handle = conn_handle;
p_sync_transfer->addr = addr;
p_sync_transfer->cb = cb;
if (BleScanningManager::IsInitialized()) {
BleScanningManager::Get()->PeriodicAdvSyncTransfer(
addr, service_data, sync_handle,
base::Bind(&btm_ble_periodic_syc_transfer_cmd_cmpl));
}
}

static struct dump_dir *open_directory_for_modification_of_element(
GDBusMethodInvocation *invocation,
uid_t caller_uid,
const char *problem_id,
const char *element)
{
static const char *const protected_elements[] = {
FILENAME_TIME,
FILENAME_UID,
NULL,
};
for (const char *const *protected = protected_elements; *protected; ++protected)
{
if (strcmp(*protected, element) == 0)
{
log_notice("'%s' element of '%s' can't be modified", element, problem_id);
char *error = xasprintf(_("'%s' element can't be modified"), element);
g_dbus_method_invocation_return_dbus_error(invocation,
"org.freedesktop.problems.ProtectedElement",
error);
free(error);
return NULL;
}
}
if (!dump_dir_accessible_by_uid(problem_id, caller_uid))
{
if (errno == ENOTDIR)
{
log_notice("'%s' is not a valid problem directory", problem_id);
return_InvalidProblemDir_error(invocation, problem_id);
}
else
{
log_notice("UID(%d) is not Authorized to access '%s'", caller_uid, problem_id);
g_dbus_method_invocation_return_dbus_error(invocation,
"org.freedesktop.problems.AuthFailure",
_("Not Authorized"));
}
return NULL;
}
struct dump_dir *dd = dd_opendir(problem_id,  0);
if (!dd)
{   
log_notice("Can't access the problem '%s' for modification", problem_id);
g_dbus_method_invocation_return_dbus_error(invocation,
"org.freedesktop.problems.Failure",
_("Can't access the problem for modification"));
return NULL;
}
return dd;
}

static gint
dissect_rfc7468(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void *data _U_)
{
int offset;
int linelen;
int next_offset;
const guchar *line;
const guchar *labelp;
int labellen;
char *label;
proto_tree *rfc7468_tree, *preeb_tree, *posteb_tree;
proto_item *rfc7468_item, *ti;
offset = 0;
rfc7468_item = proto_tree_add_item(tree, proto_rfc7468, tvb, offset, -1, ENC_NA);
rfc7468_tree = proto_item_add_subtree(rfc7468_item, ett_rfc7468);
col_set_str(pinfo->cinfo, COL_PROTOCOL, "rfc7468");
for (;;) {
linelen = tvb_find_line_end(tvb, offset, -1, &next_offset, FALSE);
if (linelen == -1) {
return tvb_captured_length(tvb);
}
line = tvb_get_ptr(tvb, offset, linelen);
if (line_is_eb(line, linelen, preeb_prefix, sizeof preeb_prefix - 1,
&labelp, &labellen)) {
break;
}
proto_tree_add_format_text(rfc7468_tree, tvb, offset, next_offset - offset);
offset = next_offset;
}
ti = proto_tree_add_format_text(rfc7468_tree, tvb, offset, next_offset - offset);
preeb_tree = proto_item_add_subtree(ti, ett_rfc7468_preeb);
label = wmem_strndup(pinfo->pool, labelp, labellen);
proto_tree_add_item(preeb_tree, hf_rfc7468_preeb_label, tvb,
offset + (int)preeb_prefix_len, labellen,  ENC_ASCII|ENC_NA);
col_add_fstr(pinfo->cinfo, COL_INFO, "Label: %s", label);
offset = next_offset;
for (;;) {
linelen = tvb_find_line_end(tvb, offset, -1, &next_offset, FALSE);
if (linelen == -1) {
return tvb_captured_length(tvb);
}
line = tvb_get_ptr(tvb, offset, linelen);
if (!line_is_blank(line, linelen)) {
break;
}
proto_tree_add_format_text(rfc7468_tree, tvb, offset, next_offset - offset);
offset = next_offset;
}
guint8 *databuf = NULL;
gsize databufsize = 0;
gint base64_state = 0;
guint base64_save = 0;
guint datasize = 0;
for (;;) {
linelen = tvb_find_line_end(tvb, offset, -1, &next_offset, FALSE);
if (linelen == -1) {
return tvb_captured_length(tvb);
}
line = tvb_get_ptr(tvb, offset, linelen);
if (line_is_eb(line, linelen, posteb_prefix, sizeof posteb_prefix - 1,
&labelp, &labellen)) {
break;
}
proto_tree_add_format_text(rfc7468_tree, tvb, offset, next_offset - offset);
databufsize += (linelen / 4) * 3 + 3;
databuf = (guint8 *)wmem_realloc(pinfo->pool, databuf, databufsize);
guint decodesize = (guint)g_base64_decode_step(line, linelen,
&databuf[datasize],
&base64_state,
&base64_save);
datasize += decodesize;
offset = next_offset;
}
if (datasize != 0) {
tvbuff_t *data_tvb;
data_tvb = tvb_new_child_real_data(tvb, databuf, datasize, datasize);
add_new_data_source(pinfo, data_tvb, "Base64-encoded data");
if (dissector_try_string(rfc7468_label_table, label, data_tvb, pinfo,
tree, NULL) == 0) {
proto_tree *data_tree;
ti = proto_tree_add_item(tree, hf_rfc7468_ber_data, data_tvb, 0, -1, ENC_NA);
data_tree = proto_item_add_subtree(ti, ett_rfc7468_data);
call_dissector(ber_handle, data_tvb, pinfo, data_tree);
}
}
ti = proto_tree_add_format_text(rfc7468_tree, tvb, offset, next_offset - offset);
posteb_tree = proto_item_add_subtree(ti, ett_rfc7468_posteb);
proto_tree_add_item(posteb_tree, hf_rfc7468_posteb_label, tvb,
offset + (int)posteb_prefix_len, labellen,  ENC_ASCII|ENC_NA);
return tvb_captured_length(tvb);
}

static int expandrow(UINT8* dest, UINT8* src, int n, int z, int xsize)
{
UINT8 pixel, count;
for (;n > 0; n--)
{
pixel = *src++;
if (n == 1 && pixel != 0)
return n;
count = pixel & RLE_MAX_RUN;
if (!count)
return count;
if (count > xsize) {
return -1;
}
if (pixel & RLE_COPY_FLAG) {
while(count--) {
*dest = *src++;
dest += z;
}
}
else {
pixel = *src++;
while (count--) {
*dest = pixel;
dest += z;
}
}
}
return 0;
}

size_t mg_mqtt_next_prop(struct mg_mqtt_message *msg, struct mg_mqtt_prop *prop,
size_t ofs) {
uint8_t *i = (uint8_t *) msg->dgram.ptr + msg->props_start + ofs;
size_t new_pos = ofs;
uint32_t bytes_consumed;
prop->id = i[0];
if (ofs >= msg->dgram.len || ofs >= msg->props_start + msg->props_size)
return 0;
i++, new_pos++;
switch (mqtt_prop_type_by_id(prop->id)) {
case MQTT_PROP_TYPE_STRING_PAIR:
prop->key.len = (uint16_t) ((((uint16_t) i[0]) << 8) | i[1]);
prop->key.ptr = (char *) i + 2;
i += 2 + prop->key.len;
prop->val.len = (uint16_t) ((((uint16_t) i[0]) << 8) | i[1]);
prop->val.ptr = (char *) i + 2;
new_pos += 2 * sizeof(uint16_t) + prop->val.len + prop->key.len;
break;
case MQTT_PROP_TYPE_BYTE:
prop->iv = (uint8_t) i[0];
new_pos++;
break;
case MQTT_PROP_TYPE_SHORT:
prop->iv = (uint16_t) ((((uint16_t) i[0]) << 8) | i[1]);
new_pos += sizeof(uint16_t);
break;
case MQTT_PROP_TYPE_INT:
prop->iv = ((uint32_t) i[0] << 24) | ((uint32_t) i[1] << 16) |
((uint32_t) i[2] << 8) | i[3];
new_pos += sizeof(uint32_t);
break;
case MQTT_PROP_TYPE_STRING:
prop->val.len = (uint16_t) ((((uint16_t) i[0]) << 8) | i[1]);
prop->val.ptr = (char *) i + 2;
new_pos += 2 + prop->val.len;
break;
case MQTT_PROP_TYPE_BINARY_DATA:
prop->val.len = (uint16_t) ((((uint16_t) i[0]) << 8) | i[1]);
prop->val.ptr = (char *) i + 2;
new_pos += 2 + prop->val.len;
break;
case MQTT_PROP_TYPE_VARIABLE_INT:
prop->iv = decode_variable_length((char *) i, &bytes_consumed);
new_pos += bytes_consumed;
break;
default:
new_pos = 0;
}
return new_pos;
}

static int output_frame(H264Context *h, AVFrame *dst, Picture *srcp)
{
AVFrame *src = &srcp->f;
int i;
int ret = av_frame_ref(dst, src);
if (ret < 0)
return ret;
av_dict_set(&dst->metadata, "stereo_mode", ff_h264_sei_stereo_mode(h), 0);
if (!srcp->crop)
return 0;
for (i = 0; i < 3; i++) {
int hshift = (i > 0) ? h->chroma_x_shift : 0;
int vshift = (i > 0) ? h->chroma_y_shift : 0;
int off    = ((srcp->crop_left >> hshift) << h->pixel_shift) +
(srcp->crop_top  >> vshift) * dst->linesize[i];
dst->data[i] += off;
}
return 0;
}

void CExifParse::ProcessGpsInfo(
const unsigned char* const DirStart,
int ByteCountUnused,
const unsigned char* const OffsetBase,
unsigned ExifLength)
{
int NumDirEntries = Get16(DirStart, m_MotorolaOrder);
for (int de=0;de<NumDirEntries;de++)
{
const unsigned char* DirEntry = DIR_ENTRY_ADDR(DirStart, de);
if (DirEntry + 12 > OffsetBase + ExifLength)
{
ErrNonfatal("GPS info directory goes past end of exif", 0, 0);
return;
}
unsigned Tag        = Get16(DirEntry, m_MotorolaOrder);
unsigned Format     = Get16(DirEntry+2, m_MotorolaOrder);
unsigned Components = (unsigned)Get32(DirEntry+4, m_MotorolaOrder);
if (Format == 0 || Format > NUM_FORMATS)
{
ErrNonfatal("Illegal number format %d for tag %04x", Format, Tag);
continue;
}
unsigned ComponentSize = BytesPerFormat[Format - 1];
unsigned ByteCount = Components * ComponentSize;
const unsigned char* ValuePtr;
if (ByteCount > 4)
{
unsigned OffsetVal = (unsigned)Get32(DirEntry+8, m_MotorolaOrder);
if (OffsetVal+ByteCount > ExifLength)
{
ErrNonfatal("Illegal value pointer for tag %04x", Tag,0);
continue;
}
ValuePtr = OffsetBase+OffsetVal;
}
else
{
ValuePtr = DirEntry+8;
}
switch(Tag)
{
case TAG_GPS_LAT_REF:
m_ExifInfo->GpsLat[0] = ValuePtr[0];
m_ExifInfo->GpsLat[1] = 0;
break;
case TAG_GPS_LONG_REF:
m_ExifInfo->GpsLong[0] = ValuePtr[0];
m_ExifInfo->GpsLong[1] = 0;
break;
case TAG_GPS_LAT:
GetLatLong(Format, ValuePtr, ComponentSize, m_ExifInfo->GpsLat);
break;
case TAG_GPS_LONG:
GetLatLong(Format, ValuePtr, ComponentSize, m_ExifInfo->GpsLong);
break;
case TAG_GPS_ALT_REF:
if (ValuePtr[0] != 0)
m_ExifInfo->GpsAlt[0] = '-';
m_ExifInfo->GpsAlt[1] = 0;
break;
case TAG_GPS_ALT:
{
char temp[18];
sprintf(temp, "%.2fm", static_cast<double>(ConvertAnyFormat(ValuePtr, Format)));
strcat(m_ExifInfo->GpsAlt, temp);
}
break;
}
}
}

