traf->tfhd->trackID = trak->Header->trackID;
}
}
}

static int action_getconfig(struct mansession *s, const struct message *m)
{
struct ast_config *cfg;
const char *fn = astman_get_header(m, "Filename");
const char *category = astman_get_header(m, "Category");
const char *filter = astman_get_header(m, "Filter");
const char *category_name;
int catcount = 0;
int lineno = 0;
struct ast_category *cur_category = NULL;
struct ast_variable *v;
struct ast_flags config_flags = { CONFIG_FLAG_WITHCOMMENTS | CONFIG_FLAG_NOCACHE };
if (ast_strlen_zero(fn)) {
astman_send_error(s, m, "Filename not specified");
return 0;
}
if (restrictedFile(fn)) {
astman_send_error(s, m, "File requires escalated priveledges");
return 0;
}
cfg = ast_config_load2(fn, "manager", config_flags);
if (cfg == CONFIG_STATUS_FILEMISSING) {
astman_send_error(s, m, "Config file not found");
return 0;
} else if (cfg == CONFIG_STATUS_FILEINVALID) {
astman_send_error(s, m, "Config file has invalid format");
return 0;
}
astman_start_ack(s, m);
while ((cur_category = ast_category_browse_filtered(cfg, category, cur_category, filter))) {
struct ast_str *templates;
category_name = ast_category_get_name(cur_category);
lineno = 0;
astman_append(s, "Category-%06d: %s\r\n", catcount, category_name);
if (ast_category_is_template(cur_category)) {
astman_append(s, "IsTemplate-%06d: %d\r\n", catcount, 1);
}
if ((templates = ast_category_get_templates(cur_category))
&& ast_str_strlen(templates) > 0) {
astman_append(s, "Templates-%06d: %s\r\n", catcount, ast_str_buffer(templates));
ast_free(templates);
}
for (v = ast_category_first(cur_category); v; v = v->next) {
astman_append(s, "Line-%06d-%06d: %s=%s\r\n", catcount, lineno++, v->name, v->value);
}
catcount++;
}
if (!ast_strlen_zero(category) && catcount == 0) { 
astman_append(s, "No categories found\r\n");
}
ast_config_destroy(cfg);
astman_append(s, "\r\n");
return 0;
}

char *
XkbAtomText(Atom atm, unsigned format)
{
const char *atmstr;
char *rtrn, *tmp;
atmstr = NameForAtom(atm);
if (atmstr != NULL) {
int len;
len = strlen(atmstr) + 1;
if (len > BUFFER_SIZE)
len = BUFFER_SIZE - 2;
rtrn = tbGetBuffer(len);
strlcpy(rtrn, atmstr, len);
}
else {
rtrn = tbGetBuffer(1);
rtrn[0] = '\0';
}
if (format == XkbCFile) {
for (tmp = rtrn; *tmp != '\0'; tmp++) {
if ((tmp == rtrn) && (!isalpha(*tmp)))
*tmp = '_';
else if (!isalnum(*tmp))
*tmp = '_';
}
}
return XkbStringText(rtrn, format);
}

static void
mqtt_tcptran_pipe_recv_cb(void *arg)
{
nni_aio *          aio;
nni_iov            iov[2];
uint8_t            type, pos, flags;
uint32_t           len = 0, rv;
size_t             n;
nni_msg *          msg, *qmsg;
mqtt_tcptran_pipe *p     = arg;
nni_aio *          rxaio = p->rxaio;
bool               ack   = false;
nni_mtx_lock(&p->mtx);
aio = nni_list_first(&p->recvq);
if ((rv = nni_aio_result(rxaio)) != 0) {
rv = SERVER_UNAVAILABLE;
goto recv_error;
}
n = nni_aio_count(rxaio);
p->gotrxhead += n;
nni_aio_iov_advance(rxaio, n);
if (nni_aio_iov_count(rxaio) > 0) {
nng_stream_recv(p->conn, rxaio);
nni_mtx_unlock(&p->mtx);
return;
}
rv = mqtt_get_remaining_length(p->rxlen, p->gotrxhead, &len, &pos);
p->wantrxhead = len + 1 + pos;
if (p->gotrxhead <= 5 && p->rxlen[p->gotrxhead - 1] > 0x7f) {
if (p->gotrxhead == NNI_NANO_MAX_HEADER_SIZE) {
rv = PACKET_TOO_LARGE;
goto recv_error;
}
iov[0].iov_buf = &p->rxlen[p->gotrxhead];
iov[0].iov_len = 1;
nni_aio_set_iov(rxaio, 1, iov);
nng_stream_recv(p->conn, rxaio);
nni_mtx_unlock(&p->mtx);
return;
}
if (NULL == p->rxmsg) {
if ((len > p->rcvmax) && (p->rcvmax > 0)) {
rv = PACKET_TOO_LARGE;
goto recv_error;
}
if ((rv = nni_msg_alloc(&p->rxmsg, (size_t) len)) != 0) {
rv = UNSPECIFIED_ERROR;
goto recv_error;
}
nni_msg_set_remaining_len(p->rxmsg, len);
if (len != 0) {
iov[0].iov_buf = nni_msg_body(p->rxmsg);
iov[0].iov_len = (size_t) len;
nni_aio_set_iov(rxaio, 1, iov);
nng_stream_recv(p->conn, rxaio);
nni_mtx_unlock(&p->mtx);
return;
}
}
nni_aio_list_remove(aio);
nni_msg_header_append(p->rxmsg, p->rxlen, pos + 1);
msg      = p->rxmsg;
p->rxmsg = NULL;
n        = nni_msg_len(msg);
type     = p->rxlen[0] & 0xf0;
flags    = p->rxlen[0] & 0x0f;
uint8_t   qos_pac;
uint16_t  packet_id   = 0;
uint8_t   reason_code = 0;
property *prop        = NULL;
uint8_t   ack_cmd     = 0;
switch (type) {
case CMD_PUBLISH:
qos_pac = nni_msg_get_pub_qos(msg);
if (qos_pac > 0) {
if (qos_pac == 1) {
ack_cmd = CMD_PUBACK;
} else if (qos_pac == 2) {
ack_cmd = CMD_PUBREC;
}
packet_id = nni_msg_get_pub_pid(msg);
ack = true;
}
break;
case CMD_PUBREC:
if (nni_mqtt_pubres_decode(msg, &packet_id, &reason_code, &prop,
p->proto) != 0) {
rv = PROTOCOL_ERROR;
goto recv_error;
}
ack_cmd = CMD_PUBREL;
ack     = true;
break;
case CMD_PUBREL:
if (flags == 0x02) {
if (nni_mqtt_pubres_decode(msg, &packet_id, &reason_code,
&prop, p->proto) != 0) {
rv = PROTOCOL_ERROR;
goto recv_error;
}
ack_cmd = CMD_PUBCOMP;
ack     = true;
break;
} else {
rv = PROTOCOL_ERROR;
goto recv_error;
}
case CMD_PUBACK:
case CMD_PUBCOMP:
if (nni_mqtt_pubres_decode(
msg, &packet_id, &reason_code, &prop, p->proto) != 0) {
rv = PROTOCOL_ERROR;
goto recv_error;
}
if (p->proto == MQTT_PROTOCOL_VERSION_v5) {
p->sndmax++;
}
break;
case CMD_PINGRESP:
break;
case CMD_DISCONNECT:
break;
default:
break;
}
if (ack == true) {
if ((rv = nni_msg_alloc(&qmsg, 0)) != 0) {
ack = false;
rv  = UNSPECIFIED_ERROR;
goto recv_error;
}
nni_mqtt_msgack_encode(
qmsg, packet_id, reason_code, prop, p->proto);
nni_mqtt_pubres_header_encode(qmsg, ack_cmd);
if (p->proto == MQTT_PROTOCOL_VERSION_v5) {
property_free(prop);
}
if (p->busy == false) {
iov[0].iov_len = nni_msg_header_len(qmsg);
iov[0].iov_buf = nni_msg_header(qmsg);
iov[1].iov_len = nni_msg_len(qmsg);
iov[1].iov_buf = nni_msg_body(qmsg);
p->busy        = true;
nni_aio_set_msg(p->qsaio, qmsg);
nni_aio_set_iov(p->qsaio, 2, iov);
nng_stream_send(p->conn, p->qsaio);
} else {
if (nni_lmq_full(&p->rslmq)) {
if (nni_lmq_cap(&p->rslmq) <=
NNG_TRAN_MAX_LMQ_SIZE) {
if ((rv = nni_lmq_resize(&p->rslmq,
nni_lmq_cap(&p->rslmq) *
2)) == 0) {
nni_lmq_put(&p->rslmq, qmsg);
} else {
nni_msg_free(qmsg);
}
} else {
nni_msg *old;
(void) nni_lmq_get(&p->rslmq, &old);
nni_msg_free(old);
nni_lmq_put(&p->rslmq, qmsg);
}
} else {
nni_lmq_put(&p->rslmq, qmsg);
}
}
ack = false;
}
nni_pipe_bump_rx(p->npipe, n);
if (!nni_list_empty(&p->recvq)) {
mqtt_tcptran_pipe_recv_start(p);
}
#ifdef NNG_HAVE_MQTT_BROKER
nni_msg_set_conn_param(msg, p->cparam);
#endif
nni_aio_set_msg(aio, msg);
p->pingcnt = 0;
nni_mtx_unlock(&p->mtx);
nni_aio_finish_sync(aio, 0, n);
return;
recv_error:
nni_aio_list_remove(aio);
msg      = p->rxmsg;
p->rxmsg = NULL;
nni_pipe_bump_error(p->npipe, rv);
nni_mtx_unlock(&p->mtx);
nni_msg_free(msg);
nni_aio_finish_error(aio, SERVER_UNAVAILABLE);
}

enum ImapAuthRes imap_auth_cram_md5(struct ImapData *idata, const char *method)
{
char ibuf[LONG_STRING * 2], obuf[LONG_STRING];
unsigned char hmac_response[MD5_DIGEST_LEN];
int len;
int rc;
if (!mutt_bit_isset(idata->capabilities, ACRAM_MD5))
return IMAP_AUTH_UNAVAIL;
mutt_message(_("Authenticating (CRAM-MD5)..."));
if (mutt_account_getlogin(&idata->conn->account) < 0)
return IMAP_AUTH_FAILURE;
if (mutt_account_getpass(&idata->conn->account) < 0)
return IMAP_AUTH_FAILURE;
imap_cmd_start(idata, "AUTHENTICATE CRAM-MD5");
do
rc = imap_cmd_step(idata);
while (rc == IMAP_CMD_CONTINUE);
if (rc != IMAP_CMD_RESPOND)
{
mutt_debug(1, "Invalid response from server: %s\n", ibuf);
goto bail;
}
len = mutt_b64_decode(obuf, idata->buf + 2);
if (len == -1)
{
mutt_debug(1, "Error decoding base64 response.\n");
goto bail;
}
obuf[len] = '\0';
mutt_debug(2, "CRAM challenge: %s\n", obuf);
hmac_md5(idata->conn->account.pass, obuf, hmac_response);
int off = snprintf(obuf, sizeof(obuf), "%s ", idata->conn->account.user);
mutt_md5_toascii(hmac_response, obuf + off);
mutt_debug(2, "CRAM response: %s\n", obuf);
mutt_b64_encode(ibuf, obuf, strlen(obuf), sizeof(ibuf) - 2);
mutt_str_strcat(ibuf, sizeof(ibuf), "\r\n");
mutt_socket_send(idata->conn, ibuf);
do
rc = imap_cmd_step(idata);
while (rc == IMAP_CMD_CONTINUE);
if (rc != IMAP_CMD_OK)
{
mutt_debug(1, "Error receiving server response.\n");
goto bail;
}
if (imap_code(idata->buf))
return IMAP_AUTH_SUCCESS;
bail:
mutt_error(_("CRAM-MD5 authentication failed."));
return IMAP_AUTH_FAILURE;
}

static int async_polkit_callback(sd_bus_message *reply, void *userdata, sd_bus_error *error) {
_cleanup_(sd_bus_error_free) sd_bus_error error_buffer = SD_BUS_ERROR_NULL;
AsyncPolkitQuery *q = userdata;
int r;
assert(reply);
assert(q);
q->slot = sd_bus_slot_unref(q->slot);
q->reply = sd_bus_message_ref(reply);
r = sd_bus_message_rewind(q->request, true);
if (r < 0) {
r = sd_bus_reply_method_errno(q->request, r, NULL);
goto finish;
}
r = q->callback(q->request, q->userdata, &error_buffer);
r = bus_maybe_reply_error(q->request, r, &error_buffer);
finish:
async_polkit_query_free(q);
return r;
}

