static int pkcs7_bio_add_digest(BIO **pbio, X509_ALGOR *alg,
const PKCS7_CTX *ctx)
{
BIO *btmp;
char name[OSSL_MAX_NAME_SIZE];
EVP_MD *fetched = NULL;
const EVP_MD *md;
if ((btmp = BIO_new(BIO_f_md())) == NULL) {
ERR_raise(ERR_LIB_PKCS7, ERR_R_BIO_LIB);
goto err;
}
OBJ_obj2txt(name, sizeof(name), alg->algorithm, 0);
(void)ERR_set_mark();
fetched = EVP_MD_fetch(ossl_pkcs7_ctx_get0_libctx(ctx), name,
ossl_pkcs7_ctx_get0_propq(ctx));
if (fetched != NULL)
md = fetched;
else
md = EVP_get_digestbyname(name);
if (md == NULL) {
(void)ERR_clear_last_mark();
ERR_raise(ERR_LIB_PKCS7, PKCS7_R_UNKNOWN_DIGEST_TYPE);
goto err;
}
(void)ERR_pop_to_mark();
BIO_set_md(btmp, md);
EVP_MD_free(fetched);
if (*pbio == NULL)
*pbio = btmp;
else if (!BIO_push(*pbio, btmp)) {
ERR_raise(ERR_LIB_PKCS7, ERR_R_BIO_LIB);
goto err;
}
btmp = NULL;
return 1;
err:
BIO_free(btmp);
return 0;
}

TfLiteStatus GatherNd(const TfLiteEvalTensor* params,
const TfLiteEvalTensor* indices,
TfLiteEvalTensor* output) {
const int indices_dims = indices->dims->size;
const int indices_nd = indices->dims->data[indices_dims - 1];
const int params_dims = params->dims->size;
const IndicesT* index_data = tflite::micro::GetTensorData<IndicesT>(indices);
const ParamsT* param_data = tflite::micro::GetTensorData<ParamsT>(params);
ParamsT* output_data = tflite::micro::GetTensorData<ParamsT>(output);
int n_slices = 1;
for (int i = 0; i < indices_dims - 1; ++i) {
n_slices *= indices->dims->data[i];
}
int slice_size = 1;
for (int i = indices_nd; i < params_dims; ++i) {
slice_size *= params->dims->data[i];
}
int remain_flat_size = ElementCount(*params->dims);
int dims_to_count[MAX_INDICES_ND];
for (int i = 0; i < indices_nd; ++i) {
dims_to_count[i] = remain_flat_size / params->dims->data[i];
remain_flat_size = dims_to_count[i];
}
for (int i = 0; i < n_slices; ++i) {
int from_pos = 0;
for (int j = 0; j < indices_nd; ++j) {
int offset = i * indices_nd + j;
IndicesT index = index_data[offset];
from_pos += index * dims_to_count[j];
}
std::memcpy(output_data + i * slice_size, param_data + from_pos,
sizeof(ParamsT) * slice_size);
}
return kTfLiteOk;
}

static void
image_set_mask(image_t *img,
int     x,
int     y,
uchar   alpha)
{
inti, j;
uchar*maskptr;
static ucharmasks[8] =
{
0x80, 0x40, 0x20, 0x10,
0x08, 0x04, 0x02, 0x01
};
static uchardither[4][4] = {
{ 0,  2,  15, 6 },
{ 4,  12, 9,  11 },
{ 14, 7,  1,  3 },
{ 8,  10, 5,  13 }
};
if (img == NULL || img->mask == NULL || x < 0 || x >= img->width ||
y < 0 || y > img->height)
return;
if (img->maskscale == 8)
{
if (PSLevel)
img->mask[y * img->maskwidth + x] = 255 - alpha;
else
img->mask[y * img->maskwidth + x] = alpha;
}
else
{
x *= img->maskscale;
y *= img->maskscale;
alpha >>= 4;
for (i = 0; i < img->maskscale; i ++, y ++, x -= img->maskscale)
for (j = 0; j < img->maskscale; j ++, x ++)
{
maskptr  = img->mask + y * img->maskwidth + x / 8;
if (alpha <= dither[x & 3][y & 3])
*maskptr |= masks[x & 7];
}
}
}

void fx_TypedArray(txMachine* the)
{
txSlot* instance = fxConstructTypedArray(the);
txSlot* dispatch = instance->next;
txSlot* view = dispatch->next;
txSlot* buffer = view->next;
txSlot* data = C_NULL;
txU2 shift = dispatch->value.typedArray.dispatch->shift;
txSlot* slot;
if ((mxArgc > 0) && (mxArgv(0)->kind == XS_REFERENCE_KIND)) {
slot = mxArgv(0)->value.reference->next;
if (slot && ((slot->kind == XS_ARRAY_BUFFER_KIND) || (slot->kind == XS_HOST_KIND))) {
txInteger offset = fxArgToByteLength(the, 1, 0);
txInteger size;
txSlot* info;
if (offset & ((1 << shift) - 1))
mxRangeError("invalid byteOffset %ld", offset);
size = fxArgToByteLength(the, 2, -1);
info = fxGetBufferInfo(the, mxArgv(0));
if (size >= 0) {
size <<= shift;
if (info->value.bufferInfo.length < (offset + size))
mxRangeError("out of range byteLength %ld", size);
}
else {
if (info->value.bufferInfo.length & ((1 << shift) - 1))
mxRangeError("invalid byteLength %ld", info->value.bufferInfo.length);
size = info->value.bufferInfo.length - offset;
if (size < 0)
mxRangeError("out of range byteLength %ld", size);
if (info->value.bufferInfo.maxLength >= 0)
size = -1;
}
view->value.dataView.offset = offset;
view->value.dataView.size = size;
buffer->kind = XS_REFERENCE_KIND;
buffer->value.reference = mxArgv(0)->value.reference;
}
else if (slot && (slot->kind == XS_TYPED_ARRAY_KIND)) {
txSlot* sourceDispatch = slot;
txSlot* sourceView = sourceDispatch->next;
txSlot* sourceBuffer = sourceView->next;
txU2 sourceShift = sourceDispatch->value.typedArray.dispatch->shift;
txInteger sourceLength = fxCheckDataViewSize(the, sourceView, sourceBuffer, XS_IMMUTABLE) >> sourceShift;
txSlot* sourceData = sourceBuffer->value.reference->next;
txInteger sourceDelta = sourceDispatch->value.typedArray.dispatch->size;
txInteger sourceOffset = sourceView->value.dataView.offset;
txInteger offset = 0;
txInteger size = sourceLength << shift;
mxPushUninitialized();
mxPush(mxArrayBufferConstructor);
if (sourceData->kind == XS_ARRAY_BUFFER_KIND) {
mxPushSlot(sourceBuffer);
mxGetID(mxID(_constructor));
fxToSpeciesConstructor(the, &mxArrayBufferConstructor);
}
else
mxPush(mxArrayBufferConstructor);
mxPushUndefined();
mxPushUninitialized();
mxPushUninitialized();
sourceLength = fxGetDataViewSize(the, sourceView, sourceBuffer) >> sourceShift;
size = sourceLength << shift;
mxPushInteger(size);
mxRunCount(1);
mxPullSlot(buffer);
sourceLength = fxCheckDataViewSize(the, sourceView, sourceBuffer, XS_IMMUTABLE) >> sourceShift;
size = sourceLength << shift;
data = fxCheckArrayBufferDetached(the, buffer, XS_MUTABLE);
view->value.dataView.offset = offset;
view->value.dataView.size = size;
if (dispatch == sourceDispatch)
c_memcpy(data->value.arrayBuffer.address + offset, sourceData->value.arrayBuffer.address + sourceOffset, size);
else {
txBoolean contentType = (dispatch->value.typedArray.dispatch->constructorID == _BigInt64Array)
|| (dispatch->value.typedArray.dispatch->constructorID == _BigUint64Array);
txBoolean sourceContentType = (sourceDispatch->value.typedArray.dispatch->constructorID == _BigInt64Array)
|| (sourceDispatch->value.typedArray.dispatch->constructorID == _BigUint64Array);
if (contentType != sourceContentType)
mxTypeError("incompatible content type");
mxPushUndefined();
while (offset < size) {
(*sourceDispatch->value.typedArray.dispatch->getter)(the, sourceData, sourceOffset, the->stack, EndianNative);
(*dispatch->value.typedArray.dispatch->coerce)(the, the->stack);
(*dispatch->value.typedArray.dispatch->setter)(the, data, offset, the->stack, EndianNative);
sourceOffset += sourceDelta;
offset += 1 << shift;
}
mxPop();
}
}
else {
fx_TypedArray_from_object(the, instance, C_NULL, C_NULL);
}
}
else {
txInteger length = fxArgToByteLength(the, 0, 0);
if (length & (((1 << shift) - 1) << (32 - shift)))
mxRangeError("out of range byteLength");
length <<= shift;
mxPush(mxArrayBufferConstructor);
mxNew();
mxPushInteger(length);
mxRunCount(1);
mxPullSlot(buffer);
view->value.dataView.offset = 0;
view->value.dataView.size = length;
}
}

int SEIUnit::removePicTimingSEI(SPSUnit& sps)
{
uint8_t* nalEnd = m_nalBuffer + m_nalBufferLen;
uint8_t* curBuff = m_nalBuffer + 1;
uint8_t tmpBuffer[1024 * 4];
tmpBuffer[0] = m_nalBuffer[0];
int tmpBufferLen = 1;
while (curBuff < nalEnd)
{
int payloadType = 0;
for (; *curBuff == 0xFF && curBuff < nalEnd; curBuff++)
{
payloadType += 0xFF;
tmpBuffer[tmpBufferLen++] = 0xff;
}
if (curBuff >= nalEnd)
break;
payloadType += *curBuff++;
tmpBuffer[tmpBufferLen++] = payloadType;
if (curBuff >= nalEnd)
break;
int payloadSize = 0;
for (; *curBuff == 0xFF && curBuff < nalEnd; curBuff++)
{
payloadSize += 0xFF;
tmpBuffer[tmpBufferLen++] = 0xff;
}
if (curBuff >= nalEnd)
break;
payloadSize += *curBuff++;
tmpBuffer[tmpBufferLen++] = payloadSize;
if (curBuff >= nalEnd)
break;
if (payloadType == SEI_MSG_PIC_TIMING)
{
tmpBufferLen -= 2;          }
else if (payloadType == SEI_MSG_BUFFERING_PERIOD)
{
tmpBufferLen -= 2;          }
else
{
memcpy(tmpBuffer + tmpBufferLen, curBuff, payloadSize);
tmpBufferLen += payloadSize;
}
curBuff += payloadSize;
}
if (m_nalBufferLen < tmpBufferLen)
{
delete[] m_nalBuffer;
m_nalBuffer = new uint8_t[tmpBufferLen];
}
memcpy(m_nalBuffer, tmpBuffer, tmpBufferLen);
m_nalBufferLen = tmpBufferLen;
return tmpBufferLen;
}

