void lustre_dump_dentry(struct dentry *dentry, int recur)
{
struct list_head *tmp;
int subdirs = 0;
LASSERT(dentry != NULL);
list_for_each(tmp, &dentry->d_subdirs)
subdirs++;
CERROR("dentry %p dump: name=%.*s parent=%.*s (%p), inode=%p, count=%u,"
" flags=0x%x, fsdata=%p, %d subdirs\n", dentry,
dentry->d_name.len, dentry->d_name.name,
dentry->d_parent->d_name.len, dentry->d_parent->d_name.name,
dentry->d_parent, dentry->d_inode, d_count(dentry),
dentry->d_flags, dentry->d_fsdata, subdirs);
if (dentry->d_inode != NULL)
ll_dump_inode(dentry->d_inode);
if (recur == 0)
return;
list_for_each(tmp, &dentry->d_subdirs) {
struct dentry *d = list_entry(tmp, struct dentry, d_u.d_child);
lustre_dump_dentry(d, recur - 1);
}
}

void
adjust_skipcol(void)
{
if (!curwin->w_p_wrap
|| !curwin->w_p_sms
|| curwin->w_cursor.lnum != curwin->w_topline)
return;
int    width1 = curwin->w_width - curwin_col_off();
int    width2 = width1 + curwin_col_off2();
long    so = get_scrolloff_value();
int    scrolloff_cols = so == 0 ? 0 : width1 + (so - 1) * width2;
int    scrolled = FALSE;
validate_cheight();
if (curwin->w_cline_height == curwin->w_height
&& plines_win(curwin, curwin->w_cursor.lnum, FALSE)
<= curwin->w_height)
{
reset_skipcol();
return;
}
validate_virtcol();
while (curwin->w_skipcol > 0
&& curwin->w_virtcol < curwin->w_skipcol + 3 + scrolloff_cols)
{
if (curwin->w_skipcol >= width1 + width2)
curwin->w_skipcol -= width2;
else
curwin->w_skipcol -= width1;
redraw_later(UPD_NOT_VALID);
scrolled = TRUE;
validate_virtcol();
}
if (scrolled)
return;  
int col = curwin->w_virtcol - curwin->w_skipcol + scrolloff_cols;
int row = 0;
if (col >= width1)
{
col -= width1;
++row;
}
if (col > width2)
{
row += col / width2;
col = col % width2;
}
if (row >= curwin->w_height)
{
if (curwin->w_skipcol == 0)
{
curwin->w_skipcol += width1;
--row;
}
if (row >= curwin->w_height)
curwin->w_skipcol += (row - curwin->w_height) * width2;
redraw_later(UPD_NOT_VALID);
}
}

Jsi_RC jsi_UserObjDelete(Jsi_Interp *interp, void *data)
{
UserObjReg* ptr = (UserObjReg*)data;
SIGASSERT(ptr, USER_REG);
Jsi_Hash *tblPtr = ptr->hashPtr;
Jsi_HashEntry *hPtr;
Jsi_HashSearch search;
for (hPtr = Jsi_HashSearchFirst(tblPtr, &search);
hPtr != NULL; hPtr = Jsi_HashSearchNext(&search)) {
void *dptr;
Jsi_Obj *obj = (Jsi_Obj*)Jsi_HashValueGet(hPtr);
SIGASSERT(obj, OBJ);
assert(obj && obj->ot == JSI_OT_USEROBJ);
Jsi_UserObj *uobj = obj->d.uobj;
dptr = uobj->data;
if (hPtr == uobj->hPtr)
uobj->hPtr = NULL;
Jsi_HashEntryDelete(hPtr);
if (dptr && ptr->reg->freefun)
ptr->reg->freefun(interp, dptr);
}
Jsi_HashDelete(tblPtr);
Jsi_Free(ptr);
return JSI_OK;
}

static int DecodeBasicOcspResponse(byte* source, word32* ioIndex,
OcspResponse* resp, word32 size, void* cm, void* heap, int noVerify)
{
int    length;
word32 idx = *ioIndex;
word32 end_index;
int    ret;
int    sigLength;
WOLFSSL_ENTER("DecodeBasicOcspResponse");
(void)heap;
if (GetSequence(source, &idx, &length, size) < 0)
return ASN_PARSE_E;
if (idx + length > size)
return ASN_INPUT_E;
end_index = idx + length;
if ((ret = DecodeResponseData(source, &idx, resp, size)) < 0)
return ret; 
