border_info.width=(size_t) floor(2.0*sigma+0.5);
border_info.height=(size_t) floor(2.0*sigma+0.5);
border_info.x=0;
border_info.y=0;
(void) QueryColorCompliance("none",AllCompliance,&clone_image->border_color,
exception);
clone_image->alpha_trait=BlendPixelTrait;
border_image=BorderImage(clone_image,&border_info,OverCompositeOp,exception);
clone_image=DestroyImage(clone_image);
if (border_image == (Image *) NULL)
return((Image *) NULL);
if (border_image->alpha_trait == UndefinedPixelTrait)
(void) SetImageAlphaChannel(border_image,OpaqueAlphaChannel,exception);
status=MagickTrue;
background_color=border_image->background_color;
background_color.alpha_trait=BlendPixelTrait;
image_view=AcquireAuthenticCacheView(border_image,exception);
for (y=0; y < (ssize_t) border_image->rows; y++)
{
Quantum
*magick_restrict q;
ssize_t
x;
if (status == MagickFalse)
continue;
q=QueueCacheViewAuthenticPixels(image_view,0,y,border_image->columns,1,
exception);
if (q == (Quantum *) NULL)
{
status=MagickFalse;
continue;
}
for (x=0; x < (ssize_t) border_image->columns; x++)
{
if (border_image->alpha_trait != UndefinedPixelTrait)
background_color.alpha=GetPixelAlpha(border_image,q)*alpha/100.0;
SetPixelViaPixelInfo(border_image,&background_color,q);
q+=GetPixelChannels(border_image);
}
if (SyncCacheViewAuthenticPixels(image_view,exception) == MagickFalse)
status=MagickFalse;
}
image_view=DestroyCacheView(image_view);
if (status == MagickFalse)
{
border_image=DestroyImage(border_image);
return((Image *) NULL);
}
channel_mask=SetImageChannelMask(border_image,AlphaChannel);
shadow_image=BlurImage(border_image,0.0,sigma,exception);
border_image=DestroyImage(border_image);
if (shadow_image == (Image *) NULL)
return((Image *) NULL);
(void) SetPixelChannelMask(shadow_image,channel_mask);
if (shadow_image->page.width == 0)
shadow_image->page.width=shadow_image->columns;
if (shadow_image->page.height == 0)
shadow_image->page.height=shadow_image->rows;
shadow_image->page.width+=x_offset-(ssize_t) border_info.width;
shadow_image->page.height+=y_offset-(ssize_t) border_info.height;
shadow_image->page.x+=x_offset-(ssize_t) border_info.width;
shadow_image->page.y+=y_offset-(ssize_t) border_info.height;
return(shadow_image);
}

static int do_format(int drive, struct format_descr *tmp_format_req)
{
int ret;
if (lock_fdc(drive, true))
return -EINTR;
set_floppy(drive);
if (!_floppy ||
_floppy->track > DP->tracks ||
tmp_format_req->track >= _floppy->track ||
tmp_format_req->head >= _floppy->head ||
(_floppy->sect << 2) % (1 << FD_SIZECODE(_floppy)) ||
!_floppy->fmt_gap) {
process_fd_request();
return -EINVAL;
}
format_req = *tmp_format_req;
format_errors = 0;
cont = &format_cont;
errors = &format_errors;
ret = wait_til_done(redo_format, true);
if (ret == -EINTR)
return -EINTR;
process_fd_request();
return ret;
}

static bool ok_jpg_decode_scan(ok_jpg_decoder *decoder) {
decoder->next_restart = 0;
ok_jpg_decode_restart(decoder);
if (decoder->restart_intervals_remaining > 0) {
decoder->restart_intervals_remaining++;
}
if (decoder->progressive) {
void (*decode_function)(ok_jpg_decoder *decoder, ok_jpg_component *c, int16_t *block);
if (decoder->scan_prev_scale > 0) {
decode_function = ok_jpg_decode_block_subsequent_scan;
} else {
decode_function = ok_jpg_decode_block_progressive;
}
if (decoder->num_scan_components == 1) {
ok_jpg_component *c = decoder->components + decoder->scan_components[0];
c->next_block = 0;
for (int data_unit_y = 0; data_unit_y < c->blocks_v; data_unit_y++) {
int16_t *block = c->blocks + (c->next_block * 64);
for (int data_unit_x = 0; data_unit_x < c->blocks_h; data_unit_x++) {
ok_jpg_decode_restart_if_needed(decoder);
decode_function(decoder, c, block);
block += 64;
}
if (decoder->eof_found || decoder->huffman_error) {
return false;
}
c->next_block += (size_t)(c->H * decoder->data_units_x);
}
} else {
for (int i = 0; i < decoder->num_scan_components; i++) {
ok_jpg_component *c = decoder->components + decoder->scan_components[i];
c->next_block = 0;
}
for (int data_unit_y = 0; data_unit_y < decoder->data_units_y; data_unit_y++) {
for (int data_unit_x = 0; data_unit_x < decoder->data_units_x; data_unit_x++) {
ok_jpg_decode_restart_if_needed(decoder);
for (int i = 0; i < decoder->num_scan_components; i++) {
ok_jpg_component *c = decoder->components + decoder->scan_components[i];
size_t block_index = c->next_block;
for (int y = 0; y < c->V; y++) {
for (int x = 0; x < c->H; x++) {
decode_function(decoder, c, c->blocks + (block_index * 64));
block_index++;
}
block_index += (size_t)(c->H * (decoder->data_units_x - 1));
}
c->next_block += c->H;
}
}
if (decoder->eof_found || decoder->huffman_error) {
return false;
}
for (int i = 0; i < decoder->num_scan_components; i++) {
ok_jpg_component *c = decoder->components + decoder->scan_components[i];
c->next_block += (size_t)((c->V - 1) * c->H * decoder->data_units_x);
}
}
}
} else {
int16_t block[64];
for (int data_unit_y = 0; data_unit_y < decoder->data_units_y; data_unit_y++) {
for (int data_unit_x = 0; data_unit_x < decoder->data_units_x; data_unit_x++) {
ok_jpg_decode_restart_if_needed(decoder);
for (int i = 0; i < decoder->num_scan_components; i++) {
ok_jpg_component *c = decoder->components + decoder->scan_components[i];
int offset_y = 0;
for (int y = 0; y < c->V; y++) {
int offset_x = 0;
for (int x = 0; x < c->H; x++) {
ok_jpg_decode_block(decoder, c, block);
c->idct(block, c->output + offset_x + offset_y);
offset_x += 8;
}
offset_y += C_WIDTH * 8;
}
}
if (decoder->huffman_error) {
return false;
}
ok_jpg_convert_data_unit(decoder, data_unit_x, data_unit_y);
}
if (decoder->eof_found) {
return false;
}
}
}
ok_jpg_dump_bits(decoder);
for (int i = 0; i < decoder->num_scan_components; i++) {
ok_jpg_component *c = decoder->components + decoder->scan_components[i];
if (!c->complete) {
c->complete = decoder->scan_end == 63 && decoder->scan_scale == 0;
}
}
return true;
}

static int redisAeAttach(aeEventLoop *loop, redisAsyncContext *ac) {
redisContext *c = &(ac->c);
redisAeEvents *e;
if (ac->ev.data != NULL)
return REDIS_ERR;
e = (redisAeEvents*)hiredis_safe_malloc(sizeof(*e));
e->context = ac;
e->loop = loop;
e->fd = c->fd;
e->reading = e->writing = 0;
ac->ev.addRead = redisAeAddRead;
ac->ev.delRead = redisAeDelRead;
ac->ev.addWrite = redisAeAddWrite;
ac->ev.delWrite = redisAeDelWrite;
ac->ev.cleanup = redisAeCleanup;
ac->ev.data = e;
return REDIS_OK;
}

static char *
getName(struct SWF_ACTIONPUSHPARAM *act)
{
char *t;
switch( act->Type ) 
{
case PUSH_STRING: 
t=malloc(strlen(act->p.String)+3); 
strcpy(t,act->p.String);
if(strlen(t)) 
return t;
else
return "this";
#if 0
case 4: 
t=malloc(4); 
sprintf(t,"R%d", act->p.RegisterNumber );
return t;
#endif
case PUSH_CONSTANT: 
if (act->p.Constant8 > poolcounter)
{
SWF_warn("WARNING: retrieving constants not present in the pool.\n");
break;
}
t=malloc(strlenext(pool[act->p.Constant8])+1);
strcpyext(t,pool[act->p.Constant8]);
if(strlen(t)) 
return t;
else
{
t=realloc(t,6);
return strcpy(t,"this");
}
case PUSH_CONSTANT16: 
if (act->p.Constant16 > poolcounter)
{
SWF_warn("WARNING: retrieving constants not present in the pool.\n");
break;
}
t=malloc(strlenext(pool[act->p.Constant16])+1);
strcpyext(t,pool[act->p.Constant16]);
if(strlen(t)) 
return t;
else
{
t=realloc(t,6);
return strcpy(t,"this");
}
default: 
return getString(act);
}
t = malloc(sizeof(char));
strcpyext(t,"");
return t;
}

bool zmq::stream_engine_base_t::in_event_internal ()
{
zmq_assert (!_io_error);
if (unlikely (_handshaking)) {
if (handshake ()) {
_handshaking = false;
} else
return false;
}
zmq_assert (_decoder);
if (_input_stopped) {
rm_fd (_handle);
_io_error = true;
return true;     }
if (!_insize) {
size_t bufsize = 0;
_decoder->get_buffer (&_inpos, &bufsize);
const int rc = read (_inpos, bufsize);
if (rc == -1) {
if (errno != EAGAIN) {
error (connection_error);
return false;
}
return true;
}
_insize = static_cast<size_t> (rc);
_decoder->resize_buffer (_insize);
}
int rc = 0;
size_t processed = 0;
while (_insize > 0) {
rc = _decoder->decode (_inpos, _insize, processed);
zmq_assert (processed <= _insize);
_inpos += processed;
_insize -= processed;
if (rc == 0 || rc == -1)
break;
rc = (this->*_process_msg) (_decoder->msg ());
if (rc == -1)
break;
}
if (rc == -1) {
if (errno != EAGAIN) {
error (protocol_error);
return false;
}
_input_stopped = true;
reset_pollin (_handle);
}
_session->flush ();
return true;
}

void gdImageLine (gdImagePtr im, int x1, int y1, int x2, int y2, int color)
{
int dx, dy, incr1, incr2, d, x, y, xend, yend, xdirflag, ydirflag;
int wid;
int w, wstart;
int thick = im->thick;
if (color == gdAntiAliased) {
gdImageAALine(im, x1, y1, x2, y2, im->AA_color); 
return;
}
if (!clip_1d(&x1,&y1,&x2,&y2,gdImageSX(im)) || !clip_1d(&y1,&x1,&y2,&x2,gdImageSY(im))) {
return;
}
dx = abs (x2 - x1);
dy = abs (y2 - y1);
if (dx == 0) {
gdImageVLine(im, x1, y1, y2, color);
return;
} else if (dy == 0) {
gdImageHLine(im, y1, x1, x2, color);
return;
}
if (dy <= dx) {
if ((dx == 0) && (dy == 0)) {
wid = 1;
} else {
double ac = cos (atan2 (dy, dx));
if (ac != 0) {
wid = thick / ac;
} else {
wid = 1;
}
if (wid == 0) {
wid = 1;
}
}
d = 2 * dy - dx;
incr1 = 2 * dy;
incr2 = 2 * (dy - dx);
if (x1 > x2) {
x = x2;
y = y2;
ydirflag = (-1);
xend = x1;
} else {
x = x1;
y = y1;
ydirflag = 1;
xend = x2;
}
wstart = y - wid / 2;
for (w = wstart; w < wstart + wid; w++) {
gdImageSetPixel(im, x, w, color);
}
if (((y2 - y1) * ydirflag) > 0) {
while (x < xend) {
x++;
if (d < 0) {
d += incr1;
} else {
y++;
d += incr2;
}
wstart = y - wid / 2;
for (w = wstart; w < wstart + wid; w++) {
gdImageSetPixel (im, x, w, color);
}
}
} else {
while (x < xend) {
x++;
if (d < 0) {
d += incr1;
} else {
y--;
d += incr2;
}
wstart = y - wid / 2;
for (w = wstart; w < wstart + wid; w++) {
gdImageSetPixel (im, x, w, color);
}
}
}
} else {
double as = sin (atan2 (dy, dx));
if (as != 0) {
wid = thick / as;
} else {
wid = 1;
}
if (wid == 0) {
wid = 1;
}
d = 2 * dx - dy;
incr1 = 2 * dx;
incr2 = 2 * (dx - dy);
if (y1 > y2) {
y = y2;
x = x2;
yend = y1;
xdirflag = (-1);
} else {
y = y1;
x = x1;
yend = y2;
xdirflag = 1;
}
wstart = x - wid / 2;
for (w = wstart; w < wstart + wid; w++) {
gdImageSetPixel (im, w, y, color);
}
if (((x2 - x1) * xdirflag) > 0) {
while (y < yend) {
y++;
if (d < 0) {
d += incr1;
} else {
x++;
d += incr2;
}
wstart = x - wid / 2;
for (w = wstart; w < wstart + wid; w++) {
gdImageSetPixel (im, w, y, color);
}
}
} else {
while (y < yend) {
y++;
if (d < 0) {
d += incr1;
} else {
x--;
d += incr2;
}
wstart = x - wid / 2;
for (w = wstart; w < wstart + wid; w++) {
gdImageSetPixel (im, w, y, color);
}
}
}
}
}

METHODDEF(JDIMENSION)
get_word_rgb_row(j_compress_ptr cinfo, cjpeg_source_ptr sinfo)
{
ppm_source_ptr source = (ppm_source_ptr)sinfo;
register JSAMPROW ptr;
register U_CHAR *bufferptr;
register JSAMPLE *rescale = source->rescale;
JDIMENSION col;
unsigned int maxval = source->maxval;
if (!ReadOK(source->pub.input_file, source->iobuffer, source->buffer_width))
ERREXIT(cinfo, JERR_INPUT_EOF);
ptr = source->pub.buffer[0];
bufferptr = source->iobuffer;
for (col = cinfo->image_width; col > 0; col--) {
register unsigned int temp;
temp  = UCH(*bufferptr++) << 8;
temp |= UCH(*bufferptr++);
if (temp > maxval)
ERREXIT(cinfo, JERR_PPM_TOOLARGE);
*ptr++ = rescale[temp];
temp  = UCH(*bufferptr++) << 8;
temp |= UCH(*bufferptr++);
if (temp > maxval)
ERREXIT(cinfo, JERR_PPM_TOOLARGE);
*ptr++ = rescale[temp];
temp  = UCH(*bufferptr++) << 8;
temp |= UCH(*bufferptr++);
if (temp > maxval)
ERREXIT(cinfo, JERR_PPM_TOOLARGE);
*ptr++ = rescale[temp];
}
return 1;
}

int
ldbm_config_search_entry_callback(Slapi_PBlock *pb __attribute__((unused)),
Slapi_Entry *e,
Slapi_Entry *entryAfter __attribute__((unused)),
int *returncode,
char *returntext,
void *arg)
{
char buf[BUFSIZ];
struct berval *vals[2];
struct berval val;
struct ldbminfo *li = (struct ldbminfo *)arg;
config_info *config;
int scope;
vals[0] = &val;
vals[1] = NULL;
returntext[0] = '\0';
PR_Lock(li->li_config_mutex);
if (pb) {
slapi_pblock_get(pb, SLAPI_SEARCH_SCOPE, &scope);
if (scope == LDAP_SCOPE_BASE) {
char **attrs = NULL;
slapi_pblock_get(pb, SLAPI_SEARCH_ATTRS, &attrs);
if (attrs) {
for (size_t i = 0; attrs[i]; i++) {
if (ldbm_config_moved_attr(attrs[i])) {
slapi_pblock_set(pb, SLAPI_PB_RESULT_TEXT, "at least one required attribute has been moved to the BDB scecific configuration entry");
break;
}
}
}
}
}
for (config = ldbm_config; config->config_name != NULL; config++) {
if (!(config->config_flags & (CONFIG_FLAG_ALWAYS_SHOW | CONFIG_FLAG_PREVIOUSLY_SET))) {
continue;
}
ldbm_config_get((void *)li, config, buf);
val.bv_val = buf;
val.bv_len = strlen(buf);
slapi_entry_attr_replace(e, config->config_name, vals);
}
PR_Unlock(li->li_config_mutex);
*returncode = LDAP_SUCCESS;
return SLAPI_DSE_CALLBACK_OK;
}

