static Str
process_form_int(struct parsed_tag *tag, int fid)
{
char *p, *q, *r, *s, *tg, *n;
p = "get";
parsedtag_get_value(tag, ATTR_METHOD, &p);
q = "!CURRENT_URL!";
parsedtag_get_value(tag, ATTR_ACTION, &q);
q = url_encode(remove_space(q), cur_baseURL, cur_document_charset);
r = NULL;
#ifdef USE_M17N
if (parsedtag_get_value(tag, ATTR_ACCEPT_CHARSET, &r))
r = check_accept_charset(r);
if (!r && parsedtag_get_value(tag, ATTR_CHARSET, &r))
r = check_charset(r);
#endif
s = NULL;
parsedtag_get_value(tag, ATTR_ENCTYPE, &s);
tg = NULL;
parsedtag_get_value(tag, ATTR_TARGET, &tg);
n = NULL;
parsedtag_get_value(tag, ATTR_NAME, &n);
if (fid < 0) {
form_max++;
form_sp++;
fid = form_max;
}
else {
if (form_max < fid)
form_max = fid;
form_sp = fid;
}
if (forms_size == 0) {
forms_size = INITIAL_FORM_SIZE;
forms = New_N(FormList *, forms_size);
form_stack = NewAtom_N(int, forms_size);
}
else if (forms_size <= form_max) {
forms_size += form_max;
forms = New_Reuse(FormList *, forms, forms_size);
form_stack = New_Reuse(int, form_stack, forms_size);
}
form_stack[form_sp] = fid;
if (w3m_halfdump) {
Str tmp = Sprintf("<form_int fid=\"%d\" action=\"%s\" method=\"%s\"",
fid, html_quote(q), html_quote(p));
if (s)
Strcat(tmp, Sprintf(" enctype=\"%s\"", html_quote(s)));
if (tg)
Strcat(tmp, Sprintf(" target=\"%s\"", html_quote(tg)));
if (n)
Strcat(tmp, Sprintf(" name=\"%s\"", html_quote(n)));
#ifdef USE_M17N
if (r)
Strcat(tmp, Sprintf(" accept-charset=\"%s\"", html_quote(r)));
#endif
Strcat_charp(tmp, ">");
return tmp;
}
forms[fid] = newFormList(q, p, r, s, tg, n, NULL);
return NULL;
}

static char *
getName(struct SWF_ACTIONPUSHPARAM *act)
{
char *t;
switch( act->Type ) 
{
case PUSH_STRING: 
if (!act->p.String) 
{
SWF_warn("WARNING: Call to getName with NULL string.\n");
break;
}
else if (strlen(act->p.String)) 
{
t=malloc(strlen(act->p.String)+3);
strcpyext(t,act->p.String);
return t;
}
else
{
char *return_string = "this";
t=malloc(strlen(return_string)+1); 
strcpyext(t,return_string);
return t;
}
#if 0
case 4: 
t=malloc(4); 
sprintf(t,"R%d", act->p.RegisterNumber );
return t;
#endif
case PUSH_CONSTANT: 
if (act->p.Constant8 > poolcounter)
{
SWF_warn("WARNING: retrieving constants not present in the pool.\n");
break;
}
t=malloc(strlenext(pool[act->p.Constant8])+1);
strcpyext(t,pool[act->p.Constant8]);
if(strlen(t)) 
return t;
else
{
t=realloc(t,6);
return strcpy(t,"this");
}
case PUSH_CONSTANT16: 
if (act->p.Constant16 > poolcounter)
{
SWF_warn("WARNING: retrieving constants not present in the pool.\n");
break;
}
t=malloc(strlenext(pool[act->p.Constant16])+1);
strcpyext(t,pool[act->p.Constant16]);
if(strlen(t)) 
return t;
else
{
t=realloc(t,6);
return strcpy(t,"this");
}
default: 
return getString(act);
}
t = malloc(sizeof(char));
strcpyext(t,"");
return t;
}

static int
dissect_smb2_find_response(tvbuff_t *tvb, packet_info *pinfo _U_, proto_tree *tree, int offset, smb2_info_t *si _U_)
{
offset_length_buffer_t olb;
proto_item *item = NULL;
gboolean continue_dissection;
if (si->saved) {
item = proto_tree_add_uint(tree, hf_smb2_find_info_level, tvb, offset, 0, si->saved->infolevel);
PROTO_ITEM_SET_GENERATED(item);
}
if (!pinfo->fd->flags.visited && si->saved && si->saved->extra_info_type == SMB2_EI_FINDPATTERN) {
col_append_fstr(pinfo->cinfo, COL_INFO, " %s Pattern: %s",
val_to_str(si->saved->infolevel, smb2_find_info_levels, "(Level:0x%02x)"),
(const char *)si->saved->extra_info);
g_free(si->saved->extra_info);
si->saved->extra_info_type = SMB2_EI_NONE;
si->saved->extra_info = NULL;
}
switch (si->status) {
case 0x00000000: offset = dissect_smb2_buffercode(tree, tvb, offset, NULL); break;
default: offset = dissect_smb2_error_response(tvb, pinfo, tree, offset, si, &continue_dissection);
if (!continue_dissection) return offset;
}
offset = dissect_smb2_olb_length_offset(tvb, offset, &olb, OLB_O_UINT16_S_UINT32, hf_smb2_find_info_blob);
dissect_smb2_olb_buffer(pinfo, tree, tvb, &olb, si, dissect_smb2_find_data);
offset = dissect_smb2_olb_tvb_max_offset(offset, &olb);
return offset;
}

Status ImportGenericFunction(
GraphFuncOp func_op, const FunctionDef& func,
llvm::StringMap<llvm::StringMap<SmallVector<Value, 1>>>& values_map,
OpBuilder& builder) {
const OpDef& signature = func.signature();
Location unknown_loc = builder.getUnknownLoc();
MLIRContext* context = builder.getContext();
NamedAttrList attrs;
DictionaryAttr func_attrs = builder.getDictionaryAttr({});
if (signature.name().empty())
return InvalidArgument("generic function without a name");
attrs.append("sym_name", builder.getStringAttr(signature.name()));
attrs.append("generic", builder.getUnitAttr());
if (!signature.description().empty())
attrs.append("description", builder.getStringAttr(signature.description()));
if (signature.is_stateful())
attrs.append("is_stateful", builder.getUnitAttr());
if (signature.control_output_size()) {
SmallVector<Attribute> control_outputs;
for (const std::string& output : signature.control_output())
control_outputs.push_back(builder.getStringAttr(output));
attrs.append("control_output", builder.getArrayAttr(control_outputs));
}
{
NamedAttrList attr_defs;
for (const OpDef_AttrDef& attr : signature.attr()) {
NamedAttrList attr_def;
if (attr.name().empty())
return InvalidArgument("Missing name for function attribute");
if (!attr.type().empty())
attr_def.append(builder.getNamedAttr(
"function_type", builder.getStringAttr(attr.type())));
if (attr.has_default_value()) {
TF_ASSIGN_OR_RETURN(Attribute attr, ConvertAttributeValue(
attr.default_value(), builder));
attr_def.append(builder.getNamedAttr("default_value", attr));
}
if (!attr.description().empty())
attr_def.append(builder.getNamedAttr(
"description", builder.getStringAttr(attr.description())));
if (attr.has_minimum() || attr.minimum())
attr_def.append(builder.getNamedAttr(
"minimum", builder.getI32IntegerAttr(attr.minimum())));
if (attr.has_allowed_values()) {
TF_ASSIGN_OR_RETURN(
Attribute attr,
ConvertAttributeValue(attr.allowed_values(), builder));
attr_def.append(builder.getNamedAttr("allowed_values", attr));
}
attr_defs.append(builder.getNamedAttr(
attr.name(), attr_def.getDictionary(builder.getContext())));
}
if (!attr_defs.empty()) {
func_attrs = attr_defs.getDictionary(builder.getContext());
attrs.append("tfg.func_attrs", func_attrs);
}
}
if (func.resource_arg_unique_id_size()) {
SmallVector<int32_t> resource_arg_unique_ids_keys;
SmallVector<int32_t> resource_arg_unique_ids_values;
for (const auto& unique_id : func.resource_arg_unique_id()) {
resource_arg_unique_ids_keys.push_back(unique_id.first);
resource_arg_unique_ids_values.push_back(unique_id.second);
}
attrs.append("resource_arg_unique_ids_keys",
builder.getI32TensorAttr(resource_arg_unique_ids_keys));
attrs.append("resource_arg_unique_ids_values",
builder.getI32TensorAttr(resource_arg_unique_ids_values));
}
for (const auto& namedAttr : func.attr()) {
if (namedAttr.first.empty())
return InvalidArgument("Invalid function attribute name");
const std::string& name = "tf." + namedAttr.first;
const AttrValue& tf_attr = namedAttr.second;
TF_ASSIGN_OR_RETURN(Attribute attr,
ConvertAttributeValue(tf_attr, builder));
attrs.append(name, attr);
}
SmallString<8> arg_or_res_attr_name;
SmallString<8> sub_arg_attr_name;
int arg_num = 0;
SmallVector<StringRef> arg_names;
SmallVector<Type> arg_types;
SmallVector<Attribute> args_attrs;
SmallVector<Attribute> res_attrs;
for (const auto& enumerated_input : llvm::enumerate(signature.input_arg())) {
const OpDef::ArgDef& input = enumerated_input.value();
TF_ASSIGN_OR_RETURN(NamedAttrList input_attrs,
ConvertArgDefAttributes(input, builder));
auto it = func.arg_attr().find(enumerated_input.index());
if (it != func.arg_attr().end()) {
NamedAttrList arg_attr;
for (const auto& named_attr : it->second.attr()) {
TF_ASSIGN_OR_RETURN(Attribute attr,
ConvertAttributeValue(named_attr.second, builder));
arg_attr.append(named_attr.first, attr);
}
input_attrs.append("tfg.arg_attrs",
arg_attr.getDictionary(builder.getContext()));
}
arg_names.push_back(builder.getStringAttr(input.name()).getValue());
arg_types.push_back(OpaqueTensorType::get(context));
args_attrs.push_back(input_attrs.getDictionary(context));
args_attrs.push_back(NamedAttrList{}.getDictionary(context));
arg_num++;
}
attrs.push_back(builder.getNamedAttr(func_op.getArgAttrsAttrName(),
builder.getArrayAttr(args_attrs)));
int res_num = 0;
for (const OpDef::ArgDef& output : signature.output_arg()) {
TF_ASSIGN_OR_RETURN(NamedAttrList output_attrs,
ConvertArgDefAttributes(output, builder));
res_attrs.push_back(output_attrs.getDictionary(context));
++res_num;
}
for (const std::string& output : signature.control_output()) {
NamedAttrList output_attrs;
output_attrs.append("tfg.name", builder.getStringAttr(output));
res_attrs.push_back(output_attrs.getDictionary(context));
++res_num;
}
attrs.push_back(builder.getNamedAttr(func_op.getResAttrsAttrName(),
builder.getArrayAttr(res_attrs)));
values_map.clear();
Block* body = new Block();
func_op.getBody().push_back(body);
Type control_ty = ControlType::get(context);
for (auto type_and_name : llvm::zip(arg_types, arg_names)) {
Value arg = body->addArgument(std::get<0>(type_and_name), unknown_loc);
llvm::StringMap<SmallVector<Value, 1>>& values =
values_map[std::get<1>(type_and_name)];
Value ctl = body->addArgument(control_ty, unknown_loc);
values[""].push_back(arg);
values["^"].push_back(ctl);
}
OpBuilder body_builder = OpBuilder::atBlockEnd(body);
OperationName mlir_placeholder("tfg.__mlir_placeholder", context);
Type placeholder_ty = OpaqueTensorType::get(context);
ValueMapManager value_manager(values_map, body_builder, mlir_placeholder,
placeholder_ty, control_ty, unknown_loc);
TF_RETURN_WITH_CONTEXT_IF_ERROR(
ImportNodes(value_manager, func.node_def(), body_builder),
" when importing function ", func.signature().name());
res_num = 0;
llvm::StringMap<int> output_name_to_position;
for (const OpDef::ArgDef& output : signature.output_arg()) {
if (output_name_to_position.count(output.name()))
return InvalidArgument("Duplicated output_arg entry", output.name());
output_name_to_position[output.name()] = res_num;
++res_num;
}
res_num = 0;
llvm::StringMap<int> control_output_to_position;
for (const std::string& output : signature.control_output()) {
if (control_output_to_position.count(output))
return InvalidArgument("Duplicated control_output entry", output);
control_output_to_position[output] = res_num;
++res_num;
}
SmallVector<Value> ret_vals(func.ret_size() + func.control_ret_size(),
Value());
for (const auto& ret_val : func.ret()) {
auto position = output_name_to_position.find(ret_val.first);
if (position == output_name_to_position.end()) {
return InvalidArgument(
"Can't import function, returned value references unknown output "
"argument ",
ret_val.first);
}
if (ret_val.second.empty()) {
return InvalidArgument("Function '", func.signature().name(),
"' has empty result name");
}
ret_vals[position->second] =
value_manager.GetValueOrCreatePlaceholder(ret_val.second);
}
for (const auto& ret_val : func.control_ret()) {
auto position = control_output_to_position.find(ret_val.first);
if (position == control_output_to_position.end()) {
return InvalidArgument(
"Can't import function, returned value references unknown output "
"argument ",
ret_val.first);
}
if (ret_val.second.empty()) {
return InvalidArgument("Function '", func.signature().name(),
"' has empty control result name");
}
Value result = value_manager.GetValueOrCreatePlaceholder(
(Twine("^") + ret_val.second).str());
if (!result.getType().isa<ControlType>())
return InvalidArgument("failed to map returned value ", ret_val.second,
", isn't a control output");
ret_vals[func.ret_size() + position->second] = result;
}
for (auto& indexed_val : llvm::enumerate(ret_vals)) {
if (indexed_val.value()) continue;
return InvalidArgument(
"Failed to import function, missing output for position ",
indexed_val.index());
}
MutableArrayRef<Value> operands = ret_vals;
ReturnOp ret_op = body_builder.create<ReturnOp>(
unknown_loc, operands.slice(0, func.ret_size()),
operands.slice(func.ret_size()));
{
SmallVector<Type> arg_types_with_ctl;
for (Type type : arg_types) {
arg_types_with_ctl.push_back(type);
arg_types_with_ctl.push_back(control_ty);
}
attrs.append("function_type",
TypeAttr::get(builder.getFunctionType(
arg_types_with_ctl, ret_op.getOperandTypes())));
}
func_op->setAttrs(attrs);
return ::tensorflow::OkStatus();
}

static u32 crc32sum(u32 crc, u8 * RESTRICT buf, size_t size) {
while (size--) crc = crc32Table[(crc ^ *(buf++)) & 0xff] ^ (crc >> 8);
return crc;
}

SecureElementStatus_t SecureElementProcessJoinAccept( JoinReqIdentifier_t joinReqType, uint8_t* joinEui,
uint16_t devNonce, uint8_t* encJoinAccept,
uint8_t encJoinAcceptSize, uint8_t* decJoinAccept,
uint8_t* versionMinor )
{
if( ( encJoinAccept == NULL ) || ( decJoinAccept == NULL ) || ( versionMinor == NULL ) )
{
return SECURE_ELEMENT_ERROR_NPE;
}
KeyIdentifier_t encKeyID = NWK_KEY;
if( joinReqType != JOIN_REQ )
{
encKeyID = J_S_ENC_KEY;
}
memcpy1( decJoinAccept, encJoinAccept, encJoinAcceptSize );
if( SecureElementAesEncrypt( encJoinAccept + LORAMAC_MHDR_FIELD_SIZE, encJoinAcceptSize - LORAMAC_MHDR_FIELD_SIZE,
encKeyID, decJoinAccept + LORAMAC_MHDR_FIELD_SIZE ) != SECURE_ELEMENT_SUCCESS )
{
return SECURE_ELEMENT_FAIL_ENCRYPT;
}
*versionMinor = ( ( decJoinAccept[11] & 0x80 ) == 0x80 ) ? 1 : 0;
uint32_t mic = 0;
mic = ( ( uint32_t ) decJoinAccept[encJoinAcceptSize - LORAMAC_MIC_FIELD_SIZE] << 0 );
mic |= ( ( uint32_t ) decJoinAccept[encJoinAcceptSize - LORAMAC_MIC_FIELD_SIZE + 1] << 8 );
mic |= ( ( uint32_t ) decJoinAccept[encJoinAcceptSize - LORAMAC_MIC_FIELD_SIZE + 2] << 16 );
mic |= ( ( uint32_t ) decJoinAccept[encJoinAcceptSize - LORAMAC_MIC_FIELD_SIZE + 3] << 24 );
if( *versionMinor == 0 )
{
if( SecureElementVerifyAesCmac( decJoinAccept, ( encJoinAcceptSize - LORAMAC_MIC_FIELD_SIZE ), mic, NWK_KEY ) !=
SECURE_ELEMENT_SUCCESS )
{
return SECURE_ELEMENT_FAIL_CMAC;
}
}
#if( USE_LRWAN_1_1_X_CRYPTO == 1 )
else if( *versionMinor == 1 )
{
uint8_t  micHeader11[JOIN_ACCEPT_MIC_COMPUTATION_OFFSET] = { 0 };
uint16_t bufItr                                          = 0;
micHeader11[bufItr++] = ( uint8_t ) joinReqType;
memcpyr( micHeader11 + bufItr, joinEui, LORAMAC_JOIN_EUI_FIELD_SIZE );
bufItr += LORAMAC_JOIN_EUI_FIELD_SIZE;
micHeader11[bufItr++] = devNonce & 0xFF;
micHeader11[bufItr++] = ( devNonce >> 8 ) & 0xFF;
uint8_t localBuffer[LORAMAC_JOIN_ACCEPT_FRAME_MAX_SIZE + JOIN_ACCEPT_MIC_COMPUTATION_OFFSET] = { 0 };
memcpy1( localBuffer, micHeader11, JOIN_ACCEPT_MIC_COMPUTATION_OFFSET );
memcpy1( localBuffer + JOIN_ACCEPT_MIC_COMPUTATION_OFFSET - 1, decJoinAccept, encJoinAcceptSize );
if( SecureElementVerifyAesCmac( localBuffer,
encJoinAcceptSize + JOIN_ACCEPT_MIC_COMPUTATION_OFFSET -
LORAMAC_MHDR_FIELD_SIZE - LORAMAC_MIC_FIELD_SIZE,
mic, J_S_INT_KEY ) != SECURE_ELEMENT_SUCCESS )
{
return SECURE_ELEMENT_FAIL_CMAC;
}
}
#endif
else
{
return SECURE_ELEMENT_ERROR_INVALID_LORAWAM_SPEC_VERSION;
}
return SECURE_ELEMENT_SUCCESS;
}

void Compute(OpKernelContext* context) override {
const Tensor& input = context->input(0);
OP_REQUIRES(context, input.dims() == 1 || input.dims() == 2,
errors::InvalidArgument(
"input must be a vector or 2D tensor, but got shape ",
input.shape().DebugString()));
if (input.dims() == 1) {
OP_REQUIRES(context,
input.NumElements() == 2 || input.NumElements() == 4 ||
input.NumElements() == 5,
errors::InvalidArgument(
"1D input must be of size 2, 4 or 5, but got shape ",
input.shape().DebugString()));
} else if (input.dims() == 2) {
OP_REQUIRES(context, input.dim_size(0) == 2 || input.dim_size(0) == 4,
errors::InvalidArgument("First dimension of 2D input must be "
"of size 2 or 4, but got shape ",
input.shape().DebugString()));
OP_REQUIRES(
context, input.dim_size(1) == 2,
errors::InvalidArgument(
"Second dimension of 2D input must be of size 2, but got shape ",
input.shape().DebugString()));
}
Tensor* output = nullptr;
OP_REQUIRES_OK(context,
context->allocate_output(0, input.shape(), &output));
Eigen::DSizes<Eigen::DenseIndex, 8> dst_idx;
string src_format_str = src_format_;
string dst_format_str = dst_format_;
if (input.dim_size(0) == 2) {
auto keep_only_spatial_dimensions = [](string* format_str) -> void {
auto new_end = std::remove_if(
format_str->begin(), format_str->end(),
[](const char dim) { return dim != 'H' && dim != 'W'; });
format_str->erase(new_end, format_str->end());
};
keep_only_spatial_dimensions(&src_format_str);
keep_only_spatial_dimensions(&dst_format_str);
}
ComputeDstIndex(src_format_str, dst_format_str, input.dims(), &dst_idx);
functor::DataFormatVecPermute<Device, T>()(context->eigen_device<Device>(),
input.flat<T>(),
output->flat<T>(), dst_idx);
}

void l2cap_recv_acldata(struct hci_conn *hcon, struct sk_buff *skb, u16 flags)
{
struct l2cap_conn *conn = hcon->l2cap_data;
int len;
if (!conn && hcon->hdev->dev_type != HCI_PRIMARY)
goto drop;
if (!conn)
conn = l2cap_conn_add(hcon);
if (!conn)
goto drop;
BT_DBG("conn %p len %u flags 0x%x", conn, skb->len, flags);
switch (flags) {
case ACL_START:
case ACL_START_NO_FLUSH:
case ACL_COMPLETE:
if (conn->rx_skb) {
BT_ERR("Unexpected start frame (len %d)", skb->len);
l2cap_recv_reset(conn);
l2cap_conn_unreliable(conn, ECOMM);
}
if (skb->len < L2CAP_LEN_SIZE) {
if (l2cap_recv_frag(conn, skb, conn->mtu) < 0)
goto drop;
return;
}
len = get_unaligned_le16(skb->data) + L2CAP_HDR_SIZE;
if (len == skb->len) {
l2cap_recv_frame(conn, skb);
return;
}
BT_DBG("Start: total len %d, frag len %u", len, skb->len);
if (skb->len > len) {
BT_ERR("Frame is too long (len %u, expected len %d)",
skb->len, len);
l2cap_conn_unreliable(conn, ECOMM);
goto drop;
}
if (l2cap_recv_frag(conn, skb, len) < 0)
goto drop;
break;
case ACL_CONT:
BT_DBG("Cont: frag len %u (expecting %u)", skb->len, conn->rx_len);
if (!conn->rx_skb) {
BT_ERR("Unexpected continuation frame (len %d)", skb->len);
l2cap_conn_unreliable(conn, ECOMM);
goto drop;
}
if (conn->rx_skb->len < L2CAP_LEN_SIZE) {
if (l2cap_recv_len(conn, skb) < 0) {
l2cap_conn_unreliable(conn, ECOMM);
goto drop;
}
if (conn->rx_skb->len < L2CAP_LEN_SIZE)
return;
}
if (skb->len > conn->rx_len) {
BT_ERR("Fragment is too long (len %u, expected %u)",
skb->len, conn->rx_len);
l2cap_recv_reset(conn);
l2cap_conn_unreliable(conn, ECOMM);
goto drop;
}
l2cap_recv_frag(conn, skb, skb->len);
if (!conn->rx_len) {
struct sk_buff *rx_skb = conn->rx_skb;
conn->rx_skb = NULL;
l2cap_recv_frame(conn, rx_skb);
}
break;
}
drop:
kfree_skb(skb);
}

bool static ProcessMessage(CNode* pfrom, string strCommand, CDataStream& vRecv)
{
static map<CService, CPubKey> mapReuseKey;
RandAddSeedPerfmon();
if (fDebug)
printf("received: %s (%d bytes)\n", strCommand.c_str(), vRecv.size());
if (mapArgs.count("-dropmessagestest") && GetRand(atoi(mapArgs["-dropmessagestest"])) == 0)
{
printf("dropmessagestest DROPPING RECV MESSAGE\n");
return true;
}
if (strCommand == "version")
{
if(pfrom->nVersion)
return(true);
int64 nTime;
CAddress addrMe;
CAddress addrFrom;
uint64 nNonce = 1;
vRecv >> pfrom->nVersion >> pfrom->nServices >> nTime >> addrMe;
if((pfrom->nVersion > MAX_PROTOCOL_VERSION) || (pfrom->nVersion < MIN_PROTOCOL_VERSION)) {
printf("peer %s reports incompatible version %i; disconnecting\n", pfrom->addr.ToString().c_str(), pfrom->nVersion);
pfrom->fDisconnect = true;
return false;
}
if (!vRecv.empty())
vRecv >> addrFrom >> nNonce;
if (!vRecv.empty())
vRecv >> pfrom->strSubVer;
if (!vRecv.empty())
vRecv >> pfrom->nStartingHeight;
if (pfrom->fInbound && addrMe.IsRoutable())
{
pfrom->addrLocal = addrMe;
SeenLocal(addrMe);
}
if (nNonce == nLocalHostNonce && nNonce > 1)
{
printf("connected to self at %s; disconnecting\n", pfrom->addr.ToString().c_str());
pfrom->fDisconnect = true;
return true;
}
if(addrFrom.IsRoutable() && addrMe.IsRoutable()) addrExternal = addrMe;
if (pfrom->fInbound)
pfrom->PushVersion();
pfrom->fClient = !(pfrom->nServices & NODE_NETWORK);
AddTimeData(pfrom->addr, nTime);
pfrom->PushMessage("verack");
pfrom->vSend.SetVersion(min(pfrom->nVersion, PROTOCOL_VERSION));
if (!pfrom->fInbound)
{
if (!fNoListen && !IsInitialBlockDownload())
{
CAddress addr = GetLocalAddress(&pfrom->addr);
if (addr.IsRoutable())
pfrom->PushAddress(addr);
}
int nAddrSize;
if(fBerkeleyAddrDB)
nAddrSize = mapAddresses.size();
else
nAddrSize = addrman.size();
if(pfrom->fOneShot || (nAddrSize < 1000)) {
pfrom->PushMessage("getaddr");
pfrom->fGetAddr = true;
}
if(!fBerkeleyAddrDB)
addrman.Good(pfrom->addr);
} else {
if(!fBerkeleyAddrDB && ((CNetAddr)pfrom->addr == (CNetAddr)addrFrom)) {
addrman.Add(addrFrom, addrFrom);
addrman.Good(addrFrom);
}
}
long nRefHeight = 745000, nRefTime = 1438677830;         long nOurTime = GetAdjustedTime();
long nHeightOffset = (nOurTime - nRefTime) / nTargetSpacingFour;
if(pfrom->nStartingHeight > (nRefHeight + nHeightOffset + 10000)) {
printf("peer %s reports height %i, estimated height is %i; disconnecting\n",
pfrom->addr.ToString().c_str(), pfrom->nStartingHeight, nRefHeight + nHeightOffset);
pfrom->fDisconnect = true;
return false;
}
static int nAskedForBlocks = 0;
if (!pfrom->fClient && !pfrom->fOneShot &&
(pfrom->nVersion < NOBLKS_VERSION_START ||
pfrom->nVersion >= NOBLKS_VERSION_END) &&
(nAskedForBlocks < 1 || vNodes.size() <= 1))
{
nAskedForBlocks++;
pfrom->PushGetBlocks(pindexBest, uint256(0));
}
{
LOCK(cs_mapAlerts);
BOOST_FOREACH(PAIRTYPE(const uint256, CAlert)& item, mapAlerts)
item.second.RelayTo(pfrom);
}
{
LOCK(cs_hashSyncCheckpoint);
if (!checkpointMessage.IsNull())
checkpointMessage.RelayTo(pfrom);
}
pfrom->fSuccessfullyConnected = true;
printf("received version message from %s, version %d, blocks=%d, us=%s, them=%s\n",
pfrom->addr.ToString().c_str(), pfrom->nVersion, pfrom->nStartingHeight, addrMe.ToString().c_str(), addrFrom.ToString().c_str());
cPeerBlockCounts.input(pfrom->nStartingHeight);
if (!IsInitialBlockDownload())
AskForPendingSyncCheckpoint(pfrom);
}
else if (pfrom->nVersion == 0)
{
pfrom->Misbehaving(1);
return false;
}
else if (strCommand == "verack")
{
pfrom->vRecv.SetVersion(min(pfrom->nVersion, PROTOCOL_VERSION));
}
else if (strCommand == "addr")
{
vector<CAddress> vAddr;
vRecv >> vAddr;
if(vAddr.size() > 1000) {
pfrom->Misbehaving(20);
return(error("Address message size = %d", vAddr.size()));
}
int64 nNow = GetAdjustedTime();
int64 nSince = nNow - 10 * 60;
bool fReachable;
if(fBerkeleyAddrDB) {
CBerkeleyAddrDB adb;
adb.TxnBegin();
BOOST_FOREACH(CAddress& addr, vAddr) {
if(fShutdown)
return(true);
ushort nPort = addr.GetPort();
if(nPort != GetDefaultPort())
continue;
if((addr.nTime <= 100000000) || (addr.nTime > nNow + 10 * 60))
addr.nTime = nNow - 5 * 24 * 60 * 60;
fReachable = IsReachable(addr);
if(fReachable)
AddAddress(addr, 2 * 60 * 60, &adb);
pfrom->AddAddressKnown(addr);
if((addr.nTime > nSince) && !pfrom->fGetAddr &&
(vAddr.size() <= 10) && addr.IsRoutable())
RelayAddress(addr, fReachable);
}
adb.TxnCommit();
} else {
vector<CAddress> vAddrOk;
BOOST_FOREACH(CAddress& addr, vAddr) {
if(fShutdown)
return(true);
ushort nPort = addr.GetPort();
if(nPort != GetDefaultPort())
continue;
if((addr.nTime <= 100000000) || (addr.nTime > nNow + 10 * 60))
addr.nTime = nNow - 5 * 24 * 60 * 60;
fReachable = IsReachable(addr);
if(fReachable)
vAddrOk.push_back(addr);
pfrom->AddAddressKnown(addr);
if((addr.nTime > nSince) && !pfrom->fGetAddr &&
(vAddr.size() <= 10) && addr.IsRoutable())
RelayAddress(addr, fReachable);
}
addrman.Add(vAddrOk, pfrom->addr, 2 * 60 * 60);
}
if(vAddr.size() < 1000)
pfrom->fGetAddr = false;
if(pfrom->fOneShot)
pfrom->fDisconnect = true;
}
else if (strCommand == "inv")
{
vector<CInv> vInv;
vRecv >> vInv;
if (vInv.size() > 50000)
{
pfrom->Misbehaving(20);
return error("message inv size() = %d", vInv.size());
}
unsigned int nLastBlock = (unsigned int)(-1);
for (unsigned int nInv = 0; nInv < vInv.size(); nInv++) {
if (vInv[vInv.size() - 1 - nInv].type == MSG_BLOCK) {
nLastBlock = vInv.size() - 1 - nInv;
break;
}
}
CTxDB txdb("r");
for (unsigned int nInv = 0; nInv < vInv.size(); nInv++)
{
const CInv &inv = vInv[nInv];
if (fShutdown)
return true;
pfrom->AddInventoryKnown(inv);
bool fAlreadyHave = AlreadyHave(txdb, inv);
if (fDebug)
printf("  got inventory: %s  %s\n", inv.ToString().c_str(), fAlreadyHave ? "have" : "new");
if (!fAlreadyHave)
pfrom->AskFor(inv);
else if (inv.type == MSG_BLOCK && mapOrphanBlocks.count(inv.hash)) {
pfrom->PushGetBlocks(pindexBest, GetOrphanRoot(mapOrphanBlocks[inv.hash]));
} else if (nInv == nLastBlock) {
std::vector<CInv> vGetData(1,inv);
pfrom->PushGetBlocks(mapBlockIndex[inv.hash], uint256(0));
if (fDebug)
printf("force request: %s\n", inv.ToString().c_str());
}
Inventory(inv.hash);
}
}
else if (strCommand == "getdata")
{
vector<CInv> vInv;
vRecv >> vInv;
if (vInv.size() > 50000)
{
pfrom->Misbehaving(20);
return error("message getdata size() = %d", vInv.size());
}
if (fDebugNet || (vInv.size() != 1))
printf("received getdata (%d invsz)\n", vInv.size());
BOOST_FOREACH(const CInv& inv, vInv)
{
if (fShutdown)
return true;
if (fDebugNet || (vInv.size() == 1))
printf("received getdata for: %s\n", inv.ToString().c_str());
if (inv.type == MSG_BLOCK)
{
map<uint256, CBlockIndex*>::iterator mi = mapBlockIndex.find(inv.hash);
if (mi != mapBlockIndex.end())
{
CBlock block;
block.ReadFromDisk((*mi).second);
pfrom->PushMessage("block", block);
if (inv.hash == pfrom->hashContinue)
{
vector<CInv> vInv;
vInv.push_back(CInv(MSG_BLOCK, hashBestChain));
pfrom->PushMessage("inv", vInv);
pfrom->hashContinue = 0;
}
}
}
else if (inv.IsKnownType())
{
{
LOCK(cs_mapRelay);
map<CInv, CDataStream>::iterator mi = mapRelay.find(inv);
if (mi != mapRelay.end())
pfrom->PushMessage(inv.GetCommand(), (*mi).second);
}
}
Inventory(inv.hash);
}
}
else if (strCommand == "getblocks")
{
CBlockLocator locator;
uint256 hashStop;
vRecv >> locator >> hashStop;
CBlockIndex* pindex = locator.GetBlockIndex();
if (pindex)
pindex = pindex->pnext;
int nLimit = 1000;
printf("getblocks %d to %s limit %d\n", (pindex ? pindex->nHeight : -1), hashStop.ToString().substr(0,20).c_str(), nLimit);
for (; pindex; pindex = pindex->pnext)
{
if (pindex->GetBlockHash() == hashStop)
{
printf("  getblocks stopping at %d %s\n", pindex->nHeight, pindex->GetBlockHash().ToString().substr(0,20).c_str());
break;
}
pfrom->PushInventory(CInv(MSG_BLOCK, pindex->GetBlockHash()));
if (--nLimit <= 0)
{
printf("  getblocks stopping at limit %d %s\n", pindex->nHeight, pindex->GetBlockHash().ToString().substr(0,20).c_str());
pfrom->hashContinue = pindex->GetBlockHash();
break;
}
}
}
else if (strCommand == "getheaders")
{
CBlockLocator locator;
uint256 hashStop;
vRecv >> locator >> hashStop;
CBlockIndex* pindex = NULL;
if (locator.IsNull())
{
map<uint256, CBlockIndex*>::iterator mi = mapBlockIndex.find(hashStop);
if (mi == mapBlockIndex.end())
return true;
pindex = (*mi).second;
}
else
{
pindex = locator.GetBlockIndex();
if (pindex)
pindex = pindex->pnext;
}
vector<CBlock> vHeaders;
int nLimit = 2000;
printf("getheaders %d to %s\n", (pindex ? pindex->nHeight : -1), hashStop.ToString().substr(0,20).c_str());
for (; pindex; pindex = pindex->pnext)
{
vHeaders.push_back(pindex->GetBlockHeader());
if (--nLimit <= 0 || pindex->GetBlockHash() == hashStop)
break;
}
pfrom->PushMessage("headers", vHeaders);
}
else if (strCommand == "tx")
{
vector<uint256> vWorkQueue;
vector<uint256> vEraseQueue;
CDataStream vMsg(vRecv);
CTxDB txdb("r");
CTransaction tx;
vRecv >> tx;
CInv inv(MSG_TX, tx.GetHash());
pfrom->AddInventoryKnown(inv);
unsigned int nSize = ::GetSerializeSize(tx, SER_NETWORK, PROTOCOL_VERSION);
unsigned int oldSize = vMsg.size();
if(nSize < oldSize) {
printf("truncating oversized transaction message %s (%u -> %u)\n",
tx.GetHash().ToString().c_str(), oldSize, nSize);
vMsg.resize(nSize);
}
bool fMissingInputs = false;
if (tx.AcceptToMemoryPool(txdb, true, &fMissingInputs))
{
SyncWithWallets(tx, NULL, true);
RelayMessage(inv, vMsg);
mapAlreadyAskedFor.erase(inv);
vWorkQueue.push_back(inv.hash);
vEraseQueue.push_back(inv.hash);
for (unsigned int i = 0; i < vWorkQueue.size(); i++)
{
uint256 hashPrev = vWorkQueue[i];
for (map<uint256, CDataStream*>::iterator mi = mapOrphanTransactionsByPrev[hashPrev].begin();
mi != mapOrphanTransactionsByPrev[hashPrev].end();
++mi)
{
const CDataStream& vMsg = *((*mi).second);
CTransaction tx;
CDataStream(vMsg) >> tx;
CInv inv(MSG_TX, tx.GetHash());
bool fMissingInputs2 = false;
if (tx.AcceptToMemoryPool(txdb, true, &fMissingInputs2))
{
printf("   accepted orphan tx %s\n", inv.hash.ToString().substr(0,10).c_str());
SyncWithWallets(tx, NULL, true);
RelayMessage(inv, vMsg);
mapAlreadyAskedFor.erase(inv);
vWorkQueue.push_back(inv.hash);
vEraseQueue.push_back(inv.hash);
}
else if (!fMissingInputs2)
{
vEraseQueue.push_back(inv.hash);
printf("   removed invalid orphan tx %s\n", inv.hash.ToString().substr(0,10).c_str());
}
}
}
BOOST_FOREACH(uint256 hash, vEraseQueue)
EraseOrphanTx(hash);
}
else if (fMissingInputs)
{
AddOrphanTx(vMsg);
unsigned int nEvicted = LimitOrphanTxSize(MAX_ORPHAN_TRANSACTIONS);
if (nEvicted > 0)
printf("mapOrphan overflow, removed %u tx\n", nEvicted);
}
if (tx.nDoS) pfrom->Misbehaving(tx.nDoS);
}
else if (strCommand == "block")
{
CBlock block;
vRecv >> block;
uint256 hashBlock = block.GetHash();
int nBlockHeight = block.GetBlockHeight();
printf("received block %s height %d\n",
hashBlock.ToString().substr(0,20).c_str(), nBlockHeight);
CInv inv(MSG_BLOCK, hashBlock);
pfrom->AddInventoryKnown(inv);
if(ProcessBlock(pfrom, &block))
mapAlreadyAskedFor.erase(inv);
if(block.nDoS)
pfrom->Misbehaving(block.nDoS);
}
else if (strCommand == "getaddr")
{
pfrom->vAddrToSend.clear();
vector<CAddress> vAddr = addrman.GetAddr();
BOOST_FOREACH(const CAddress &addr, vAddr)
pfrom->PushAddress(addr);
}
else if (strCommand == "checkorder")
{
uint256 hashReply;
vRecv >> hashReply;
if (!GetBoolArg("-allowreceivebyip"))
{
pfrom->PushMessage("reply", hashReply, (int)2, string(""));
return true;
}
CWalletTx order;
vRecv >> order;
if (!mapReuseKey.count(pfrom->addr))
pwalletMain->GetKeyFromPool(mapReuseKey[pfrom->addr], true);
CScript scriptPubKey;
scriptPubKey << mapReuseKey[pfrom->addr] << OP_CHECKSIG;
pfrom->PushMessage("reply", hashReply, (int)0, scriptPubKey);
}
else if (strCommand == "reply")
{
uint256 hashReply;
vRecv >> hashReply;
CRequestTracker tracker;
{
LOCK(pfrom->cs_mapRequests);
map<uint256, CRequestTracker>::iterator mi = pfrom->mapRequests.find(hashReply);
if (mi != pfrom->mapRequests.end())
{
tracker = (*mi).second;
pfrom->mapRequests.erase(mi);
}
}
if (!tracker.IsNull())
tracker.fn(tracker.param1, vRecv);
}
else if (strCommand == "ping")
{
if (pfrom->nVersion > BIP0031_VERSION)
{
uint64 nonce = 0;
vRecv >> nonce;
pfrom->PushMessage("pong", nonce);
}
}
else if (strCommand == "alert")
{
if(pfrom->fDisconnect) {
printf("alert received from a disconnected peer %s of version %i; ignoring\n",
pfrom->addr.ToString().c_str(), pfrom->nVersion);
return false;
}
CAlert alert;
vRecv >> alert;
if (alert.ProcessAlert())
{
pfrom->setKnown.insert(alert.GetHash());
{
LOCK(cs_vNodes);
BOOST_FOREACH(CNode* pnode, vNodes)
alert.RelayTo(pnode);
}
} else {
pfrom->Misbehaving(20);
}
}
else if (strCommand == "checkpoint")
{
if(pfrom->fDisconnect) {
printf("sync-checkpoint received from a disconnected peer %s of version %i; ignoring\n",
pfrom->addr.ToString().c_str(), pfrom->nVersion);
return false;
}
CSyncCheckpoint checkpoint;
vRecv >> checkpoint;
if (checkpoint.ProcessSyncCheckpoint(pfrom))
{
pfrom->hashCheckpointKnown = checkpoint.hashCheckpoint;
LOCK(cs_vNodes);
BOOST_FOREACH(CNode* pnode, vNodes)
checkpoint.RelayTo(pnode);
}
}
else
{
}
if (pfrom->fNetworkNode)
if (strCommand == "version" || strCommand == "addr" || strCommand == "inv" || strCommand == "getdata" || strCommand == "ping")
AddressCurrentlyConnected(pfrom->addr);
return true;
}

bool Utility::UnZip(const QString &zippath, const QString &destpath)
{
int res = 0;
QDir dir(destpath);
if (!cp437) {
cp437 = new QCodePage437Codec();
}
#ifdef Q_OS_WIN32
zlib_filefunc64_def ffunc;
fill_win32_filefunc64W(&ffunc);
unzFile zfile = unzOpen2_64(Utility::QStringToStdWString(QDir::toNativeSeparators(zippath)).c_str(), &ffunc);
#else
unzFile zfile = unzOpen64(QDir::toNativeSeparators(zippath).toUtf8().constData());
#endif
if ((zfile == NULL) || (!IsFileReadable(zippath)) || (!dir.exists())) {
return false;
}
res = unzGoToFirstFile(zfile);
if (res == UNZ_OK) {
do {
char file_name[MAX_PATH] = {0};
unz_file_info64 file_info;
unzGetCurrentFileInfo64(zfile, &file_info, file_name, MAX_PATH, NULL, 0, NULL, 0);
QString qfile_name;
QString cp437_file_name;
qfile_name = QString::fromUtf8(file_name);
if (!(file_info.flag & (1<<11))) {
cp437_file_name = cp437->toUnicode(file_name);
}
if (!qfile_name.isEmpty()) {
QString file_path = destpath + "/" + qfile_name;
QFileInfo qfile_info(file_path);
if (file_info.uncompressed_size == 0 && qfile_name.endsWith('/')) {
dir.mkpath(qfile_name);
continue;
} else {
dir.mkpath(qfile_info.path());
}
if (unzOpenCurrentFile(zfile) != UNZ_OK) {
unzClose(zfile);
return false;
}
QFile entry(file_path);
if (!entry.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
unzCloseCurrentFile(zfile);
unzClose(zfile);
return false;
}
char buff[BUFF_SIZE] = {0};
int read = 0;
while ((read = unzReadCurrentFile(zfile, buff, BUFF_SIZE)) > 0) {
entry.write(buff, read);
}
entry.close();
if (read < 0) {
unzCloseCurrentFile(zfile);
unzClose(zfile);
return false;
}
if (unzCloseCurrentFile(zfile) == UNZ_CRCERROR) {
unzClose(zfile);
return false;
}
if (!cp437_file_name.isEmpty() && cp437_file_name != qfile_name) {
QString cp437_file_path = destpath + "/" + cp437_file_name;
QFile::copy(file_path, cp437_file_path);
}
}
} while ((res = unzGoToNextFile(zfile)) == UNZ_OK);
}
if (res != UNZ_END_OF_LIST_OF_FILE) {
unzClose(zfile);
return false;
}
unzClose(zfile);
return true;
}

static int
gdev_pdf_put_params_impl(gx_device * dev, const gx_device_pdf * save_dev, gs_param_list * plist)
{
int ecode, code;
gx_device_pdf *pdev = (gx_device_pdf *) dev;
float cl = (float)pdev->CompatibilityLevel;
bool locked = pdev->params.LockDistillerParams, ForOPDFRead;
gs_param_name param_name;
pdev->pdf_memory = gs_memory_stable(pdev->memory);
{
gs_param_string_array ppa;
gs_param_string pps;
code = param_read_string_array(plist, (param_name = "pdfmark"), &ppa);
switch (code) {
case 0:
code = pdfwrite_pdf_open_document(pdev);
if (code < 0)
return code;
code = pdfmark_process(pdev, &ppa);
if (code >= 0)
return code;
default:
param_signal_error(plist, param_name, code);
return code;
case 1:
break;
}
code = param_read_string_array(plist, (param_name = "DSC"), &ppa);
switch (code) {
case 0:
code = pdfwrite_pdf_open_document(pdev);
if (code < 0)
return code;
code = pdf_dsc_process(pdev, &ppa);
if (code >= 0)
return code;
default:
param_signal_error(plist, param_name, code);
return code;
case 1:
break;
}
code = param_read_string(plist, (param_name = "pdfpagelabels"), &pps);
switch (code) {
case 0:
{
if (!pdev->ForOPDFRead) {
cos_dict_t *const pcd = pdev->Catalog;
code = pdfwrite_pdf_open_document(pdev);
if (code < 0)
return code;
code = cos_dict_put_string(pcd, (const byte *)"/PageLabels", 11,
pps.data, pps.size);
if (code >= 0)
return code;
} else
return 0;
}
default:
param_signal_error(plist, param_name, code);
return code;
case 1:
break;
}
}
ecode = param_read_bool(plist, "LockDistillerParams", &locked);
if (ecode < 0)
param_signal_error(plist, param_name, ecode);
{
int efo = 1;
ecode = param_put_int(plist, (param_name = ".EmbedFontObjects"), &efo, ecode);
if (ecode < 0)
param_signal_error(plist, param_name, ecode);
if (efo != 1)
param_signal_error(plist, param_name, ecode = gs_error_rangecheck);
}
{
int cdv = CoreDistVersion;
ecode = param_put_int(plist, (param_name = "CoreDistVersion"), &cdv, ecode);
if (ecode < 0)
return gs_note_error(ecode);
if (cdv != CoreDistVersion)
param_signal_error(plist, param_name, ecode = gs_error_rangecheck);
}
switch (code = param_read_float(plist, (param_name = "CompatibilityLevel"), &cl)) {
default:
ecode = code;
param_signal_error(plist, param_name, ecode);
break;
case 0:
if (!(locked && pdev->params.LockDistillerParams)) {
if (cl < (float)1.15)
cl = (float)1.1;
else if (cl < (float)1.25)
cl = (float)1.2;
else if (cl < (float)1.35)
cl = (float)1.3;
else if (cl < (float)1.45)
cl = (float)1.4;
else if (cl < (float)1.55)
cl = (float)1.5;
else if (cl < (float)1.65)
cl = (float)1.6;
else if (cl < (float)1.75)
cl = (float)1.7;
else {
cl = (float)2.0;
if (pdev->params.TransferFunctionInfo == tfi_Preserve)
pdev->params.TransferFunctionInfo = tfi_Apply;
}
}
case 1:
break;
}
{   
gs_memory_t *mem = plist->memory;
plist->memory = pdev->pdf_memory;
code = gs_param_read_items(plist, pdev, pdf_param_items);
if (code < 0 || (code = param_read_bool(plist, "ForOPDFRead", &ForOPDFRead)) < 0)
{
}
if (code == 0 && !pdev->is_ps2write && !(locked && pdev->params.LockDistillerParams))
pdev->ForOPDFRead = ForOPDFRead;
plist->memory = mem;
}
if (code < 0)
ecode = code;
{
long fon = pdev->FirstObjectNumber;
if (fon != save_dev->FirstObjectNumber) {
if (fon <= 0 || fon > 0x7fff0000 ||
(pdev->next_id != 0 &&
pdev->next_id !=
save_dev->FirstObjectNumber + pdf_num_initial_ids)
) {
ecode = gs_error_rangecheck;
param_signal_error(plist, "FirstObjectNumber", ecode);
}
}
}
{
static const char *const pcm_names[] = {
"DeviceGray", "DeviceRGB", "DeviceCMYK", "DeviceN", 0
};
int pcm = -1;
ecode = param_put_enum(plist, "ProcessColorModel", &pcm,
pcm_names, ecode);
if (pcm >= 0) {
pdf_set_process_color_model(pdev, pcm);
rc_decrement(pdev->icc_struct, "gdev_pdf_put_params_impl, ProcessColorModel changed");
pdev->icc_struct = 0;
}
}
if (ecode < 0)
goto fail;
if (pdev->is_ps2write && (code = param_read_bool(plist, "ProduceDSC", &pdev->ProduceDSC)) < 0) {
param_signal_error(plist, param_name, code);
}
if (pdev->PDFA < 0 || pdev->PDFA > 3){
ecode = gs_note_error(gs_error_rangecheck);
param_signal_error(plist, "PDFA", ecode);
goto fail;
}
if(pdev->PDFA != 0 && pdev->AbortPDFAX)
pdev->PDFA = 0;
if(pdev->PDFX && pdev->AbortPDFAX)
pdev->PDFX = 0;
if (pdev->PDFX && pdev->PDFA != 0) {
ecode = gs_note_error(gs_error_rangecheck);
param_signal_error(plist, "PDFA", ecode);
goto fail;
}
if (pdev->PDFX && pdev->ForOPDFRead) {
ecode = gs_note_error(gs_error_rangecheck);
param_signal_error(plist, "PDFX", ecode);
goto fail;
}
if (pdev->PDFA != 0 && pdev->ForOPDFRead) {
ecode = gs_note_error(gs_error_rangecheck);
param_signal_error(plist, "PDFA", ecode);
goto fail;
}
if (pdev->PDFA == 1 || pdev->PDFX || pdev->CompatibilityLevel < 1.4) {
pdev->HaveTransparency = false;
pdev->PreserveSMask = false;
}
if (pdev->PDFX)
cl = (float)1.3; 
if (pdev->PDFA != 0 && cl < 1.4)
cl = (float)1.4;
pdev->version = (cl < 1.2 ? psdf_version_level2 : psdf_version_ll3);
if (pdev->ForOPDFRead) {
pdev->ResourcesBeforeUsage = true;
pdev->HaveCFF = false;
pdev->HavePDFWidths = false;
pdev->HaveStrokeColor = false;
cl = (float)1.2; 
pdev->MaxInlineImageSize = max_long; 
pdev->version = psdf_version_level2;
} else {
pdev->ResourcesBeforeUsage = false;
pdev->HaveCFF = true;
pdev->HavePDFWidths = true;
pdev->HaveStrokeColor = true;
}
pdev->ParamCompatibilityLevel = cl;
if (cl < 1.2) {
pdev->HaveCFF = false;
}
ecode = gdev_psdf_put_params(dev, plist);
if (ecode < 0)
goto fail;
if (pdev->CompatibilityLevel > 1.7 && pdev->params.TransferFunctionInfo == tfi_Preserve) {
pdev->params.TransferFunctionInfo = tfi_Apply;
emprintf(pdev->memory, "\nIt is not possible to preserve transfer functions in PDF 2.0\ntransfer functions will be applied instead\n");
}
if (pdev->params.ConvertCMYKImagesToRGB) {
if (pdev->params.ColorConversionStrategy == ccs_CMYK) {
emprintf(pdev->memory, "ConvertCMYKImagesToRGB is not compatible with ColorConversionStrategy of CMYK\n");
} else {
if (pdev->params.ColorConversionStrategy == ccs_Gray) {
emprintf(pdev->memory, "ConvertCMYKImagesToRGB is not compatible with ColorConversionStrategy of Gray\n");
} else {
if (pdev->icc_struct)
rc_decrement(pdev->icc_struct,
"reset default profile\n");
pdf_set_process_color_model(pdev,1);
ecode = gsicc_init_device_profile_struct((gx_device *)pdev, NULL, 0);
if (ecode < 0)
goto fail;
}
}
}
switch (pdev->params.ColorConversionStrategy) {
case ccs_ByObjectType:
case ccs_LeaveColorUnchanged:
break;
case ccs_UseDeviceDependentColor:
case ccs_UseDeviceIndependentColor:
case ccs_UseDeviceIndependentColorForImages:
pdev->params.TransferFunctionInfo = tfi_Apply;
break;
case ccs_CMYK:
pdev->params.TransferFunctionInfo = tfi_Apply;
if (pdev->icc_struct)
rc_decrement(pdev->icc_struct,
"reset default profile\n");
pdf_set_process_color_model(pdev, 2);
ecode = gsicc_init_device_profile_struct((gx_device *)pdev, NULL, 0);
if (ecode < 0)
goto fail;
break;
case ccs_Gray:
pdev->params.TransferFunctionInfo = tfi_Apply;
if (pdev->icc_struct)
rc_decrement(pdev->icc_struct,
"reset default profile\n");
pdf_set_process_color_model(pdev,0);
ecode = gsicc_init_device_profile_struct((gx_device *)pdev, NULL, 0);
if (ecode < 0)
goto fail;
break;
case ccs_sRGB:
case ccs_RGB:
pdev->params.TransferFunctionInfo = tfi_Apply;
if (!pdev->params.ConvertCMYKImagesToRGB) {
if (pdev->icc_struct)
rc_decrement(pdev->icc_struct,
"reset default profile\n");
pdf_set_process_color_model(pdev,1);
ecode = gsicc_init_device_profile_struct((gx_device *)pdev, NULL, 0);
if (ecode < 0)
goto fail;
}
break;
default:
break;
}
if (cl < 1.5f && pdev->params.ColorImage.Filter != NULL &&
!strcmp(pdev->params.ColorImage.Filter, "JPXEncode")) {
emprintf(pdev->memory,
"JPXEncode requires CompatibilityLevel >= 1.5 .\n");
ecode = gs_note_error(gs_error_rangecheck);
}
if (cl < 1.5f && pdev->params.GrayImage.Filter != NULL &&
!strcmp(pdev->params.GrayImage.Filter, "JPXEncode")) {
emprintf(pdev->memory,
"JPXEncode requires CompatibilityLevel >= 1.5 .\n");
ecode = gs_note_error(gs_error_rangecheck);
}
if (cl < 1.4f && pdev->params.MonoImage.Filter != NULL &&
!strcmp(pdev->params.MonoImage.Filter, "JBIG2Encode")) {
emprintf(pdev->memory,
"JBIG2Encode requires CompatibilityLevel >= 1.4 .\n");
ecode = gs_note_error(gs_error_rangecheck);
}
if (pdev->HaveTrueTypes && pdev->version == psdf_version_level2) {
pdev->version = psdf_version_level2_with_TT ;
}
if (ecode < 0)
goto fail;
if (pdev->FirstObjectNumber != save_dev->FirstObjectNumber) {
if (pdev->xref.file != 0) {
if (gp_fseek_64(pdev->xref.file, 0L, SEEK_SET) != 0) {
ecode = gs_error_ioerror;
goto fail;
}
pdf_initialize_ids(pdev);
}
}
pdev->CompatibilityLevel = (int)(cl * 10 + 0.5) / 10.0;
if(pdev->OwnerPassword.size != save_dev->OwnerPassword.size ||
(pdev->OwnerPassword.size != 0 &&
memcmp(pdev->OwnerPassword.data, save_dev->OwnerPassword.data,
pdev->OwnerPassword.size) != 0)) {
if (pdev->is_open) {
if (pdev->PageCount == 0) {
gs_closedevice((gx_device *)save_dev);
return 0;
}
else
emprintf(pdev->memory, "Owner Password changed mid-job, ignoring.\n");
}
}
if (pdev->Linearise && pdev->is_ps2write) {
emprintf(pdev->memory, "Can't linearise PostScript output, ignoring\n");
pdev->Linearise = false;
}
if (pdev->Linearise && pdev->OwnerPassword.size != 0) {
emprintf(pdev->memory, "Can't linearise encrypted PDF, ignoring\n");
pdev->Linearise = false;
}
if (pdev->FlattenFonts)
pdev->PreserveTrMode = false;
return 0;
fail:
pdev->version = save_dev->version;
pdf_set_process_color_model(pdev, save_dev->pcm_color_info_index);
pdev->saved_fill_color = save_dev->saved_fill_color;
pdev->saved_stroke_color = save_dev->saved_fill_color;
{
const gs_param_item_t *ppi = pdf_param_items;
for (; ppi->key; ++ppi)
memcpy((char *)pdev + ppi->offset,
(char *)save_dev + ppi->offset,
gs_param_type_sizes[ppi->type]);
pdev->ForOPDFRead = save_dev->ForOPDFRead;
}
return ecode;
}

