static Image *ReadMATImage(const ImageInfo *image_info,ExceptionInfo *exception)
{
Image *image, *image2=NULL,
*rotated_image;
register Quantum *q;
unsigned int status;
MATHeader MATLAB_HDR;
size_t size;
size_t CellType;
QuantumInfo *quantum_info;
ImageInfo *clone_info;
int i;
ssize_t ldblk;
unsigned char *BImgBuff = NULL;
double MinVal, MaxVal;
unsigned z, z2;
unsigned Frames;
int logging;
int sample_size;
MagickOffsetType filepos=0x80;
BlobInfo *blob;
size_t one;
unsigned int (*ReadBlobXXXLong)(Image *image);
unsigned short (*ReadBlobXXXShort)(Image *image);
void (*ReadBlobDoublesXXX)(Image * image, size_t len, double *data);
void (*ReadBlobFloatsXXX)(Image * image, size_t len, float *data);
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickCoreSignature);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
logging = LogMagickEvent(CoderEvent,GetMagickModule(),"enter");
image = AcquireImage(image_info,exception);
status = OpenBlob(image_info, image, ReadBinaryBlobMode, exception);
if (status == MagickFalse)
{
image=DestroyImageList(image);
return((Image *) NULL);
}
quantum_info=(QuantumInfo *) NULL;
clone_info=CloneImageInfo(image_info);
if (ReadBlob(image,124,(unsigned char *) &MATLAB_HDR.identific) != 124)
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
if (strncmp(MATLAB_HDR.identific,"MATLAB",6) != 0)
{
image2=ReadMATImageV4(image_info,image,exception);
if (image2  == NULL)
goto MATLAB_KO;
image=image2;
goto END_OF_READING;
}
MATLAB_HDR.Version = ReadBlobLSBShort(image);
if(ReadBlob(image,2,(unsigned char *) &MATLAB_HDR.EndianIndicator) != 2)
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
if (logging)
(void) LogMagickEvent(CoderEvent,GetMagickModule(),"  Endian %c%c",
MATLAB_HDR.EndianIndicator[0],MATLAB_HDR.EndianIndicator[1]);
if (!strncmp(MATLAB_HDR.EndianIndicator, "IM", 2))
{
ReadBlobXXXLong = ReadBlobLSBLong;
ReadBlobXXXShort = ReadBlobLSBShort;
ReadBlobDoublesXXX = ReadBlobDoublesLSB;
ReadBlobFloatsXXX = ReadBlobFloatsLSB;
image->endian = LSBEndian;
}
else if (!strncmp(MATLAB_HDR.EndianIndicator, "MI", 2))
{
ReadBlobXXXLong = ReadBlobMSBLong;
ReadBlobXXXShort = ReadBlobMSBShort;
ReadBlobDoublesXXX = ReadBlobDoublesMSB;
ReadBlobFloatsXXX = ReadBlobFloatsMSB;
image->endian = MSBEndian;
}
else
goto MATLAB_KO;    
if (strncmp(MATLAB_HDR.identific, "MATLAB", 6))
MATLAB_KO: ThrowReaderException(CorruptImageError,"ImproperImageHeader");
filepos = TellBlob(image);
while(!EOFBlob(image)) 
{
Frames = 1;
(void) SeekBlob(image,filepos,SEEK_SET);
MATLAB_HDR.DataType = ReadBlobXXXLong(image);
if(EOFBlob(image)) break;
MATLAB_HDR.ObjectSize = ReadBlobXXXLong(image);
if(EOFBlob(image)) break;
filepos += MATLAB_HDR.ObjectSize + 4 + 4;
image2 = image;
#if defined(MAGICKCORE_ZLIB_DELEGATE)
if(MATLAB_HDR.DataType == miCOMPRESSED)
{
image2 = DecompressBlock(image,MATLAB_HDR.ObjectSize,clone_info,exception);
if(image2==NULL) continue;
MATLAB_HDR.DataType = ReadBlobXXXLong(image2); 
}
#endif
if(MATLAB_HDR.DataType!=miMATRIX) continue;  
MATLAB_HDR.unknown1 = ReadBlobXXXLong(image2);
MATLAB_HDR.unknown2 = ReadBlobXXXLong(image2);
MATLAB_HDR.unknown5 = ReadBlobXXXLong(image2);
MATLAB_HDR.StructureClass = MATLAB_HDR.unknown5 & 0xFF;
MATLAB_HDR.StructureFlag = (MATLAB_HDR.unknown5>>8) & 0xFF;
MATLAB_HDR.unknown3 = ReadBlobXXXLong(image2);
if(image!=image2)
MATLAB_HDR.unknown4 = ReadBlobXXXLong(image2);  
MATLAB_HDR.unknown4 = ReadBlobXXXLong(image2);
MATLAB_HDR.DimFlag = ReadBlobXXXLong(image2);
MATLAB_HDR.SizeX = ReadBlobXXXLong(image2);
MATLAB_HDR.SizeY = ReadBlobXXXLong(image2);
switch(MATLAB_HDR.DimFlag)
{
case  8: z2=z=1; break;      
case 12: z2=z = ReadBlobXXXLong(image2);  
(void) ReadBlobXXXLong(image2);
if(z!=3) ThrowReaderException(CoderError, "MultidimensionalMatricesAreNotSupported");
break;
case 16: z2=z = ReadBlobXXXLong(image2);  
if(z!=3 && z!=1)
ThrowReaderException(CoderError, "MultidimensionalMatricesAreNotSupported");
Frames = ReadBlobXXXLong(image2);
if (Frames == 0)
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
break;
default: ThrowReaderException(CoderError, "MultidimensionalMatricesAreNotSupported");
}
MATLAB_HDR.Flag1 = ReadBlobXXXShort(image2);
MATLAB_HDR.NameFlag = ReadBlobXXXShort(image2);
if (logging) (void)LogMagickEvent(CoderEvent,GetMagickModule(),
"MATLAB_HDR.StructureClass %d",MATLAB_HDR.StructureClass);
if (MATLAB_HDR.StructureClass != mxCHAR_CLASS &&
MATLAB_HDR.StructureClass != mxSINGLE_CLASS &&    
MATLAB_HDR.StructureClass != mxDOUBLE_CLASS &&    
MATLAB_HDR.StructureClass != mxINT8_CLASS &&
MATLAB_HDR.StructureClass != mxUINT8_CLASS &&    
MATLAB_HDR.StructureClass != mxINT16_CLASS &&
MATLAB_HDR.StructureClass != mxUINT16_CLASS &&    
MATLAB_HDR.StructureClass != mxINT32_CLASS &&
MATLAB_HDR.StructureClass != mxUINT32_CLASS &&    
MATLAB_HDR.StructureClass != mxINT64_CLASS &&
MATLAB_HDR.StructureClass != mxUINT64_CLASS)    
ThrowReaderException(CoderError,"UnsupportedCellTypeInTheMatrix");
switch (MATLAB_HDR.NameFlag)
{
case 0:
size = ReadBlobXXXLong(image2);  
size = 4 * (ssize_t) ((size + 3 + 1) / 4);
(void) SeekBlob(image2, size, SEEK_CUR);
break;
case 1:
case 2:
case 3:
case 4:
(void) ReadBlob(image2, 4, (unsigned char *) &size); 
break;
default:
goto MATLAB_KO;
}
CellType = ReadBlobXXXLong(image2);    
if (logging)
(void) LogMagickEvent(CoderEvent,GetMagickModule(),
"MATLAB_HDR.CellType: %.20g",(double) CellType);
(void) ReadBlob(image2, 4, (unsigned char *) &size);     
NEXT_FRAME:
switch (CellType)
{
case miINT8:
case miUINT8:
sample_size = 8;
if(MATLAB_HDR.StructureFlag & FLAG_LOGICAL)
image->depth = 1;
else
image->depth = 8;         
ldblk = (ssize_t) MATLAB_HDR.SizeX;
break;
case miINT16:
case miUINT16:
sample_size = 16;
image->depth = 16;        
ldblk = (ssize_t) (2 * MATLAB_HDR.SizeX);
break;
case miINT32:
case miUINT32:
sample_size = 32;
image->depth = 32;        
ldblk = (ssize_t) (4 * MATLAB_HDR.SizeX);
break;
case miINT64:
case miUINT64:
sample_size = 64;
image->depth = 64;        
ldblk = (ssize_t) (8 * MATLAB_HDR.SizeX);
break;
case miSINGLE:
sample_size = 32;
image->depth = 32;        
(void) SetImageOption(clone_info,"quantum:format","floating-point");
if (MATLAB_HDR.StructureFlag & FLAG_COMPLEX)
{              
}
ldblk = (ssize_t) (4 * MATLAB_HDR.SizeX);
break;
case miDOUBLE:
sample_size = 64;
image->depth = 64;        
(void) SetImageOption(clone_info,"quantum:format","floating-point");
DisableMSCWarning(4127)
if (sizeof(double) != 8)
RestoreMSCWarning
ThrowReaderException(CoderError, "IncompatibleSizeOfDouble");
if (MATLAB_HDR.StructureFlag & FLAG_COMPLEX)
{                         
}
ldblk = (ssize_t) (8 * MATLAB_HDR.SizeX);
break;
default:
ThrowReaderException(CoderError, "UnsupportedCellTypeInTheMatrix");
}
(void) sample_size;
image->columns = MATLAB_HDR.SizeX;
image->rows = MATLAB_HDR.SizeY;
one=1;
image->colors = one << image->depth;
if (image->columns == 0 || image->rows == 0)
goto MATLAB_KO;
if ((MATLAB_HDR.DimFlag == 8) &&
((MATLAB_HDR.StructureFlag & FLAG_COMPLEX) == 0))
{
image->type=GrayscaleType;
SetImageColorspace(image,GRAYColorspace,exception);
}
if (image_info->ping)
{
size_t temp = image->columns;
image->columns = image->rows;
image->rows = temp;
goto done_reading; 
}
status=SetImageExtent(image,image->columns,image->rows,exception);
if (status == MagickFalse)
return(DestroyImageList(image));
quantum_info=AcquireQuantumInfo(clone_info,image);
if (quantum_info == (QuantumInfo *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
BImgBuff = (unsigned char *) AcquireQuantumMemory((size_t) (ldblk),sizeof(double));    
if (BImgBuff == NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
(void) ResetMagickMemory(BImgBuff,0,ldblk*sizeof(double));
MinVal = 0;
MaxVal = 0;
if (CellType==miDOUBLE || CellType==miSINGLE)        
{
CalcMinMax(image2, image_info->endian,  MATLAB_HDR.SizeX, MATLAB_HDR.SizeY, CellType, ldblk, BImgBuff, &quantum_info->minimum, &quantum_info->maximum);
}
if(z==1) z=0; 
do
{
for (i = 0; i < (ssize_t) MATLAB_HDR.SizeY; i++)
{
q=GetAuthenticPixels(image,0,MATLAB_HDR.SizeY-i-1,image->columns,1,exception);
if (q == (Quantum *) NULL)
{
if (logging) (void)LogMagickEvent(CoderEvent,GetMagickModule(),
"  MAT set image pixels returns unexpected NULL on a row %u.", (unsigned)(MATLAB_HDR.SizeY-i-1));
goto done_reading;    
}
if(ReadBlob(image2,ldblk,(unsigned char *)BImgBuff) != (ssize_t) ldblk)
{
if (logging) (void)LogMagickEvent(CoderEvent,GetMagickModule(),
"  MAT cannot read scanrow %u from a file.", (unsigned)(MATLAB_HDR.SizeY-i-1));
goto ExitLoop;
}
if((CellType==miINT8 || CellType==miUINT8) && (MATLAB_HDR.StructureFlag & FLAG_LOGICAL))
{
FixLogical((unsigned char *)BImgBuff,ldblk);
if(ImportQuantumPixels(image,(CacheView *) NULL,quantum_info,z2qtype[z],BImgBuff,exception) <= 0)
{
ImportQuantumPixelsFailed:
if (logging) (void)LogMagickEvent(CoderEvent,GetMagickModule(),
"  MAT failed to ImportQuantumPixels for a row %u", (unsigned)(MATLAB_HDR.SizeY-i-1));
break;
}
}
else
{
if(ImportQuantumPixels(image,(CacheView *) NULL,quantum_info,z2qtype[z],BImgBuff,exception) <= 0)
goto ImportQuantumPixelsFailed;
if (z<=1 &&       
(CellType==miINT8 || CellType==miINT16 || CellType==miINT32 || CellType==miINT64))
FixSignedValues(image,q,MATLAB_HDR.SizeX);
}
if (!SyncAuthenticPixels(image,exception))
{
if (logging) (void)LogMagickEvent(CoderEvent,GetMagickModule(),
"  MAT failed to sync image pixels for a row %u", (unsigned)(MATLAB_HDR.SizeY-i-1));
goto ExitLoop;
}
}
} while(z-- >= 2);
ExitLoop:
if (MATLAB_HDR.StructureFlag & FLAG_COMPLEX)
{        
CellType = ReadBlobXXXLong(image2);    
i = ReadBlobXXXLong(image2);           
if (CellType==miDOUBLE || CellType==miSINGLE)
{
CalcMinMax(image2,  image_info->endian, MATLAB_HDR.SizeX, MATLAB_HDR.SizeY, CellType, ldblk, BImgBuff, &MinVal, &MaxVal);
}
if (CellType==miDOUBLE)
for (i = 0; i < (ssize_t) MATLAB_HDR.SizeY; i++)
{
ReadBlobDoublesXXX(image2, ldblk, (double *)BImgBuff);
InsertComplexDoubleRow(image, (double *)BImgBuff, i, MinVal, MaxVal,
exception);
}
if (CellType==miSINGLE)
for (i = 0; i < (ssize_t) MATLAB_HDR.SizeY; i++)
{
ReadBlobFloatsXXX(image2, ldblk, (float *)BImgBuff);
InsertComplexFloatRow(image,(float *)BImgBuff,i,MinVal,MaxVal,
exception);
}
}
if ((MATLAB_HDR.DimFlag == 8) &&
((MATLAB_HDR.StructureFlag & FLAG_COMPLEX) == 0))
image->type=GrayscaleType;
if (image->depth == 1)
image->type=BilevelType;
if(image2==image)
image2 = NULL;    
rotated_image = RotateImage(image, 90.0, exception);
if (rotated_image != (Image *) NULL)
{
rotated_image->page.x=0;
rotated_image->page.y=0;
blob = rotated_image->blob;
rotated_image->blob = image->blob;
rotated_image->colors = image->colors;
image->blob = blob;
AppendImageToList(&image,rotated_image);
DeleteImageFromList(&image);
}
done_reading:
if(image2!=NULL)
if(image2!=image)
{
DeleteImageFromList(&image2);
if(clone_info)
{
if(clone_info->file)
{
fclose(clone_info->file);
clone_info->file = NULL;
(void) remove_utf8(clone_info->filename);
}
}
}
AcquireNextImage(image_info,image,exception);
if (image->next == (Image *) NULL) break;
image=SyncNextImageInList(image);
image->columns=image->rows=0;
image->colors=0;
RelinquishMagickMemory(BImgBuff);
BImgBuff = NULL;
if(--Frames>0)
{
z = z2;
if(image2==NULL) image2 = image;
goto NEXT_FRAME;
}
if ((image2!=NULL) && (image2!=image))   
{
DeleteImageFromList(&image2);
if(clone_info)
{
if(clone_info->file)
{
fclose(clone_info->file);
clone_info->file = NULL;
(void) remove_utf8(clone_info->filename);
}
}
}
}
RelinquishMagickMemory(BImgBuff);
if (quantum_info != (QuantumInfo *) NULL)
quantum_info=DestroyQuantumInfo(quantum_info);
END_OF_READING:
clone_info=DestroyImageInfo(clone_info);
CloseBlob(image);
{
Image *p;
ssize_t scene=0;
p=image;
image=NULL;
while (p != (Image *) NULL)
{
Image *tmp=p;
if ((p->rows == 0) || (p->columns == 0)) {
p=p->previous;
DeleteImageFromList(&tmp);
} else {
image=p;
p=p->previous;
}
}
for (p=image; p != (Image *) NULL; p=p->next)
p->scene=scene++;
}
if(clone_info != NULL)  
{
if(clone_info->file)
{
fclose(clone_info->file);
clone_info->file = NULL;
(void) remove_utf8(clone_info->filename);
}
DestroyImageInfo(clone_info);
clone_info = NULL;
}
if (logging) (void)LogMagickEvent(CoderEvent,GetMagickModule(),"return");
if(image==NULL)
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
return (image);
}

int effect_command(effect_handle_t self, uint32_t cmdCode, uint32_t cmdSize,
void *pCmdData, uint32_t *replySize, void *pReplyData)
{
effect_context_t * context = (effect_context_t *)self;
int retsize;
int status = 0;
pthread_mutex_lock(&lock);
if (!effect_exists(context)) {
status = -ENOSYS;
goto exit;
}
if (context == NULL || context->state == EFFECT_STATE_UNINITIALIZED) {
status = -ENOSYS;
goto exit;
}
switch (cmdCode) {
case EFFECT_CMD_INIT:
if (pReplyData == NULL || *replySize != sizeof(int)) {
status = -EINVAL;
goto exit;
}
if (context->ops.init)
*(int *) pReplyData = context->ops.init(context);
else
*(int *) pReplyData = 0;
break;
case EFFECT_CMD_SET_CONFIG:
if (pCmdData == NULL || cmdSize != sizeof(effect_config_t)
|| pReplyData == NULL || *replySize != sizeof(int)) {
status = -EINVAL;
goto exit;
}
*(int *) pReplyData = set_config(context, (effect_config_t *) pCmdData);
break;
case EFFECT_CMD_GET_CONFIG:
if (pReplyData == NULL ||
*replySize != sizeof(effect_config_t)) {
status = -EINVAL;
goto exit;
}
if (!context->offload_enabled) {
status = -EINVAL;
goto exit;
}
get_config(context, (effect_config_t *)pReplyData);
break;
case EFFECT_CMD_RESET:
if (context->ops.reset)
context->ops.reset(context);
break;
case EFFECT_CMD_ENABLE:
if (pReplyData == NULL || *replySize != sizeof(int)) {
status = -EINVAL;
goto exit;
}
if (context->state != EFFECT_STATE_INITIALIZED) {
status = -ENOSYS;
goto exit;
}
context->state = EFFECT_STATE_ACTIVE;
if (context->ops.enable)
context->ops.enable(context);
ALOGV("%s EFFECT_CMD_ENABLE", __func__);
*(int *)pReplyData = 0;
break;
case EFFECT_CMD_DISABLE:
if (pReplyData == NULL || *replySize != sizeof(int)) {
status = -EINVAL;
goto exit;
}
if (context->state != EFFECT_STATE_ACTIVE) {
status = -ENOSYS;
goto exit;
}
context->state = EFFECT_STATE_INITIALIZED;
if (context->ops.disable)
context->ops.disable(context);
ALOGV("%s EFFECT_CMD_DISABLE", __func__);
*(int *)pReplyData = 0;
break;
case EFFECT_CMD_GET_PARAM: {
if (pCmdData == NULL ||
cmdSize < (int)(sizeof(effect_param_t) + sizeof(uint32_t)) ||
pReplyData == NULL ||
*replySize < (int)(sizeof(effect_param_t) + sizeof(uint32_t) +
sizeof(uint16_t))) {
status = -EINVAL;
ALOGV("EFFECT_CMD_GET_PARAM invalid command cmdSize %d *replySize %d",
cmdSize, *replySize);
goto exit;
}
if (!context->offload_enabled) {
status = -EINVAL;
goto exit;
}
effect_param_t *q = (effect_param_t *)pCmdData;
memcpy(pReplyData, pCmdData, sizeof(effect_param_t) + q->psize);
effect_param_t *p = (effect_param_t *)pReplyData;
if (context->ops.get_parameter)
context->ops.get_parameter(context, p, replySize);
} break;
case EFFECT_CMD_SET_PARAM: {
if (pCmdData == NULL ||
cmdSize < (int)(sizeof(effect_param_t) + sizeof(uint32_t) +
sizeof(uint16_t)) ||
pReplyData == NULL || *replySize != sizeof(int32_t)) {
status = -EINVAL;
ALOGV("EFFECT_CMD_SET_PARAM invalid command cmdSize %d *replySize %d",
cmdSize, *replySize);
goto exit;
}
*(int32_t *)pReplyData = 0;
effect_param_t *p = (effect_param_t *)pCmdData;
if (context->ops.set_parameter)
*(int32_t *)pReplyData = context->ops.set_parameter(context, p,
*replySize);
} break;
case EFFECT_CMD_SET_DEVICE: {
uint32_t device;
ALOGV("\t EFFECT_CMD_SET_DEVICE start");
if (pCmdData == NULL || cmdSize < sizeof(uint32_t)) {
status = -EINVAL;
ALOGV("EFFECT_CMD_SET_DEVICE invalid command cmdSize %d", cmdSize);
goto exit;
}
device = *(uint32_t *)pCmdData;
if (context->ops.set_device)
context->ops.set_device(context, device);
} break;
case EFFECT_CMD_SET_VOLUME:
case EFFECT_CMD_SET_AUDIO_MODE:
break;
case EFFECT_CMD_OFFLOAD: {
output_context_t *out_ctxt;
if (cmdSize != sizeof(effect_offload_param_t) || pCmdData == NULL
|| pReplyData == NULL || *replySize != sizeof(int)) {
ALOGV("%s EFFECT_CMD_OFFLOAD bad format", __func__);
status = -EINVAL;
break;
}
effect_offload_param_t* offload_param = (effect_offload_param_t*)pCmdData;
ALOGV("%s EFFECT_CMD_OFFLOAD offload %d output %d", __func__,
offload_param->isOffload, offload_param->ioHandle);
*(int *)pReplyData = 0;
context->offload_enabled = offload_param->isOffload;
if (context->out_handle == offload_param->ioHandle)
break;
out_ctxt = get_output(context->out_handle);
if (out_ctxt != NULL)
remove_effect_from_output(out_ctxt, context);
context->out_handle = offload_param->ioHandle;
out_ctxt = get_output(context->out_handle);
if (out_ctxt != NULL)
add_effect_to_output(out_ctxt, context);
} break;
default:
if (cmdCode >= EFFECT_CMD_FIRST_PROPRIETARY && context->ops.command)
status = context->ops.command(context, cmdCode, cmdSize,
pCmdData, replySize, pReplyData);
else {
ALOGW("%s invalid command %d", __func__, cmdCode);
status = -EINVAL;
}
break;
}
exit:
pthread_mutex_unlock(&lock);
return status;
}

static SplineFont *SFD_GetFont( FILE *sfd,SplineFont *cidmaster,char *tok,
int fromdir, char *dirname, float sfdversion )
{
SplineFont *sf;
int realcnt, i, eof, mappos=-1, ch;
struct table_ordering *lastord = NULL;
struct axismap *lastaxismap = NULL;
struct named_instance *lastnamedinstance = NULL;
int pushedbacktok = false;
Encoding *enc = &custom;
struct remap *remap = NULL;
int haddupenc;
int old_style_order2 = false;
int had_layer_cnt=false;
orig_pos = 0;
sf = SplineFontEmpty();
if ( sfdversion>0 && sfdversion<2 ) {
sf = realloc(sf,sizeof(SplineFont1));
memset(((uint8 *) sf) + sizeof(SplineFont),0,sizeof(SplineFont1)-sizeof(SplineFont));
}
sf->sfd_version = sfdversion;
sf->cidmaster = cidmaster;
sf->uni_interp = ui_unset;
SFD_GetFontMetaDataData d;
SFD_GetFontMetaDataData_Init( &d );
while ( 1 ) {
if ( pushedbacktok )
pushedbacktok = false;
else if ( (eof = getname(sfd,tok))!=1 ) {
if ( eof==-1 )
break;
geteol(sfd,tok);
continue;
}
bool wasMetadata = SFD_GetFontMetaData( sfd, tok, sf, &d );
had_layer_cnt = d.had_layer_cnt;
if( wasMetadata )
{
continue;
}
if ( strmatch(tok,"DisplaySize:")==0 )
{
getint(sfd,&sf->display_size);
}
else if ( strmatch(tok,"DisplayLayer:")==0 )
{
getint(sfd,&sf->display_layer);
}
else if ( strmatch(tok,"ExtremaBound:")==0 )
{
getint(sfd,&sf->extrema_bound);
}
else if ( strmatch(tok,"WidthSeparation:")==0 )
{
getint(sfd,&sf->width_separation);
}
else if ( strmatch(tok,"WinInfo:")==0 )
{
int temp1, temp2;
getint(sfd,&sf->top_enc);
getint(sfd,&temp1);
getint(sfd,&temp2);
if ( sf->top_enc<=0 ) sf->top_enc=-1;
if ( temp1<=0 ) temp1 = 16;
if ( temp2<=0 ) temp2 = 4;
sf->desired_col_cnt = temp1;
sf->desired_row_cnt = temp2;
}
else if ( strmatch(tok,"AntiAlias:")==0 )
{
int temp;
getint(sfd,&temp);
sf->display_antialias = temp;
}
else if ( strmatch(tok,"FitToEm:")==0 )
{
int temp;
getint(sfd,&temp);
sf->display_bbsized = temp;
}
else if ( strmatch(tok,"OnlyBitmaps:")==0 )
{
int temp;
getint(sfd,&temp);
sf->onlybitmaps = temp;
}
else if ( strmatch(tok,"Order2:")==0 )
{
getint(sfd,&old_style_order2);
sf->grid.order2 = old_style_order2;
sf->layers[ly_back].order2 = old_style_order2;
sf->layers[ly_fore].order2 = old_style_order2;
}
else if ( strmatch(tok,"GridOrder2:")==0 )
{
int o2;
getint(sfd,&o2);
sf->grid.order2 = o2;
}
else if ( strmatch(tok,"Encoding:")==0 )
{
enc = SFDGetEncoding(sfd,tok);
if ( sf->map!=NULL ) sf->map->enc = enc;
}
else if ( strmatch(tok,"OldEncoding:")==0 )
{
(void) SFDGetEncoding(sfd,tok);
}
else if ( strmatch(tok,"UnicodeInterp:")==0 )
{
sf->uni_interp = SFDGetUniInterp(sfd,tok,sf);
}
else if ( strmatch(tok,"NameList:")==0 )
{
SFDGetNameList(sfd,tok,sf);
}
else if ( strmatch(tok,"Compacted:")==0 )
{
int temp;
getint(sfd,&temp);
sf->compacted = temp;
}
else if ( strmatch(tok,"Registry:")==0 )
{
geteol(sfd,tok);
sf->cidregistry = copy(tok);
}
else if ( strmatch(tok,"Ordering:")==0 ) {
geteol(sfd,tok);
sf->ordering = copy(tok);
} else if ( strmatch(tok,"Supplement:")==0 ) {
getint(sfd,&sf->supplement);
} else if ( strmatch(tok,"RemapN:")==0 ) {
int n;
getint(sfd,&n);
remap = calloc(n+1,sizeof(struct remap));
remap[n].infont = -1;
mappos = 0;
if ( sf->map!=NULL ) sf->map->remap = remap;
} else if ( strmatch(tok,"Remap:")==0 ) {
uint32 f, l; int p;
gethex(sfd,&f);
gethex(sfd,&l);
getint(sfd,&p);
if ( remap!=NULL && remap[mappos].infont!=-1 ) {
remap[mappos].firstenc = f;
remap[mappos].lastenc = l;
remap[mappos].infont = p;
mappos++;
}
} else if ( strmatch(tok,"CIDVersion:")==0 ) {
real temp;
getreal(sfd,&temp);
sf->cidversion = temp;
} else if ( strmatch(tok,"Grid")==0 ) {
sf->grid.splines = SFDGetSplineSet(sfd,sf->grid.order2);
} else if ( strmatch(tok,"ScriptLang:")==0 ) {
int i,j,k;
int imax, jmax, kmax;
if ( sf->sfd_version==0 || sf->sfd_version>=2 ) {
IError( "Script lang lists should not happen in version 2 sfd files." );
SplineFontFree(sf);
return NULL;
}
getint(sfd,&imax);
((SplineFont1 *) sf)->sli_cnt = imax;
((SplineFont1 *) sf)->script_lang = malloc((imax+1)*sizeof(struct script_record *));
((SplineFont1 *) sf)->script_lang[imax] = NULL;
for ( i=0; i<imax; ++i ) {
getint(sfd,&jmax);
((SplineFont1 *) sf)->script_lang[i] = malloc((jmax+1)*sizeof(struct script_record));
((SplineFont1 *) sf)->script_lang[i][jmax].script = 0;
for ( j=0; j<jmax; ++j ) {
((SplineFont1 *) sf)->script_lang[i][j].script = gettag(sfd);
getint(sfd,&kmax);
((SplineFont1 *) sf)->script_lang[i][j].langs = malloc((kmax+1)*sizeof(uint32));
((SplineFont1 *) sf)->script_lang[i][j].langs[kmax] = 0;
for ( k=0; k<kmax; ++k ) {
((SplineFont1 *) sf)->script_lang[i][j].langs[k] = gettag(sfd);
}
}
}
} else if ( strmatch(tok,"TeXData:")==0 ) {
int temp;
getint(sfd,&temp);
sf->texdata.type = temp;
getint(sfd, &temp);
if ( sf->design_size==0 ) {
sf->design_size = (5*temp+(1<<18))>>19;
}
for ( i=0; i<22; ++i ) {
int foo;
getint(sfd,&foo);
sf->texdata.params[i]=foo;
}
} else if ( strnmatch(tok,"AnchorClass",11)==0 ) {
char *name;
AnchorClass *lastan = NULL, *an;
int old = strchr(tok,'2')==NULL;
while ( (name=SFDReadUTF7Str(sfd))!=NULL ) {
an = chunkalloc(old ? sizeof(AnchorClass1) : sizeof(AnchorClass));
an->name = name;
if ( old ) {
getname(sfd,tok);
if ( tok[0]=='0' && tok[1]=='\0' )
((AnchorClass1 *) an)->feature_tag = 0;
else {
if ( tok[1]=='\0' ) { tok[1]=' '; tok[2] = 0; }
if ( tok[2]=='\0' ) { tok[2]=' '; tok[3] = 0; }
if ( tok[3]=='\0' ) { tok[3]=' '; tok[4] = 0; }
((AnchorClass1 *) an)->feature_tag = (tok[0]<<24) | (tok[1]<<16) | (tok[2]<<8) | tok[3];
}
while ( (ch=nlgetc(sfd))==' ' || ch=='\t' );
ungetc(ch,sfd);
if ( isdigit(ch)) {
int temp;
getint(sfd,&temp);
((AnchorClass1 *) an)->flags = temp;
}
while ( (ch=nlgetc(sfd))==' ' || ch=='\t' );
ungetc(ch,sfd);
if ( isdigit(ch)) {
int temp;
getint(sfd,&temp);
((AnchorClass1 *) an)->script_lang_index = temp;
} else
((AnchorClass1 *) an)->script_lang_index = 0xffff;
while ( (ch=nlgetc(sfd))==' ' || ch=='\t' );
ungetc(ch,sfd);
if ( isdigit(ch)) {
int temp;
getint(sfd,&temp);
((AnchorClass1 *) an)->merge_with = temp;
} else
((AnchorClass1 *) an)->merge_with = 0xffff;
} else {
char *subtable_name = SFDReadUTF7Str(sfd);
if ( subtable_name!=NULL)                                           
an->subtable = SFFindLookupSubtableAndFreeName(sf,subtable_name);
}
while ( (ch=nlgetc(sfd))==' ' || ch=='\t' );
ungetc(ch,sfd);
if ( isdigit(ch) ) {
int temp;
getint(sfd,&temp);
an->type = temp;
} else if ( old ) {
if ( ((AnchorClass1 *) an)->feature_tag==CHR('c','u','r','s'))
an->type = act_curs;
else if ( ((AnchorClass1 *) an)->feature_tag==CHR('m','k','m','k'))
an->type = act_mkmk;
else
an->type = act_mark;
} else {
an->type = act_mark;
if( an->subtable && an->subtable->lookup )
{
switch ( an->subtable->lookup->lookup_type )
{
case gpos_cursive:
an->type = act_curs;
break;
case gpos_mark2base:
an->type = act_mark;
break;
case gpos_mark2ligature:
an->type = act_mklg;
break;
case gpos_mark2mark:
an->type = act_mkmk;
break;
default:
an->type = act_mark;
break;
}
}
}
if ( lastan==NULL )
sf->anchor = an;
else
lastan->next = an;
lastan = an;
}
} else if ( strncmp(tok,"MATH:",5)==0 ) {
SFDParseMathItem(sfd,sf,tok);
} else if ( strmatch(tok,"TableOrder:")==0 ) {
int temp;
struct table_ordering *ord;
if ( sfdversion==0 || sfdversion>=2 ) {
IError("Table ordering specified in version 2 sfd file.\n" );
SplineFontFree(sf);
return NULL;
}
ord = chunkalloc(sizeof(struct table_ordering));
ord->table_tag = gettag(sfd);
getint(sfd,&temp);
ord->ordered_features = malloc((temp+1)*sizeof(uint32));
ord->ordered_features[temp] = 0;
for ( i=0; i<temp; ++i ) {
while ( isspace((ch=nlgetc(sfd))) );
if ( ch=='\'' ) {
ungetc(ch,sfd);
ord->ordered_features[i] = gettag(sfd);
} else if ( ch=='<' ) {
int f,s;
fscanf(sfd,"%d,%d>", &f, &s );
ord->ordered_features[i] = (f<<16)|s;
}
}
if ( lastord==NULL )
((SplineFont1 *) sf)->orders = ord;
else
lastord->next = ord;
lastord = ord;
} else if ( strmatch(tok,"BeginPrivate:")==0 ) {
SFDGetPrivate(sfd,sf);
} else if ( strmatch(tok,"BeginSubrs:")==0 ) {
SFDGetSubrs(sfd);
} else if ( strmatch(tok,"PickledData:")==0 ) {
if (sf->python_persistent != NULL) {
#if defined(_NO_PYTHON)
free( sf->python_persistent );
#else
PyFF_FreePythonPersistent(sf->python_persistent);
#endif
sf->python_persistent = NULL;
}
sf->python_persistent = SFDUnPickle(sfd, 0);
sf->python_persistent_has_lists = 0;
} else if ( strmatch(tok,"PickledDataWithLists:")==0 ) {
if (sf->python_persistent != NULL) {
#if defined(_NO_PYTHON)
free( sf->python_persistent );
#else
PyFF_FreePythonPersistent(sf->python_persistent);
#endif
sf->python_persistent = NULL;
}
sf->python_persistent = SFDUnPickle(sfd, 1);
sf->python_persistent_has_lists = 1;
} else if ( strmatch(tok,"MMCounts:")==0 ) {
MMSet *mm = sf->mm = chunkalloc(sizeof(MMSet));
getint(sfd,&mm->instance_count);
getint(sfd,&mm->axis_count);
ch = nlgetc(sfd);
if ( ch!=' ' )
ungetc(ch,sfd);
else { int temp;
getint(sfd,&temp);
mm->apple = temp;
getint(sfd,&mm->named_instance_count);
}
mm->instances = calloc(mm->instance_count,sizeof(SplineFont *));
mm->positions = malloc(mm->instance_count*mm->axis_count*sizeof(real));
mm->defweights = malloc(mm->instance_count*sizeof(real));
mm->axismaps = calloc(mm->axis_count,sizeof(struct axismap));
if ( mm->named_instance_count!=0 )
mm->named_instances = calloc(mm->named_instance_count,sizeof(struct named_instance));
} else if ( strmatch(tok,"MMAxis:")==0 ) {
MMSet *mm = sf->mm;
if ( mm!=NULL ) {
for ( i=0; i<mm->axis_count; ++i ) {
getname(sfd,tok);
mm->axes[i] = copy(tok);
}
}
} else if ( strmatch(tok,"MMPositions:")==0 ) {
MMSet *mm = sf->mm;
if ( mm!=NULL ) {
for ( i=0; i<mm->axis_count*mm->instance_count; ++i )
getreal(sfd,&mm->positions[i]);
}
} else if ( strmatch(tok,"MMWeights:")==0 ) {
MMSet *mm = sf->mm;
if ( mm!=NULL ) {
for ( i=0; i<mm->instance_count; ++i )
getreal(sfd,&mm->defweights[i]);
}
} else if ( strmatch(tok,"MMAxisMap:")==0 ) {
MMSet *mm = sf->mm;
if ( mm!=NULL ) {
int index, points;
getint(sfd,&index); getint(sfd,&points);
mm->axismaps[index].points = points;
mm->axismaps[index].blends = malloc(points*sizeof(real));
mm->axismaps[index].designs = malloc(points*sizeof(real));
for ( i=0; i<points; ++i ) {
getreal(sfd,&mm->axismaps[index].blends[i]);
while ( (ch=nlgetc(sfd))!=EOF && isspace(ch));
ungetc(ch,sfd);
if ( (ch=nlgetc(sfd))!='=' )
ungetc(ch,sfd);
else if ( (ch=nlgetc(sfd))!='>' )
ungetc(ch,sfd);
getreal(sfd,&mm->axismaps[index].designs[i]);
}
lastaxismap = &mm->axismaps[index];
lastnamedinstance = NULL;
}
} else if ( strmatch(tok,"MMNamedInstance:")==0 ) {
MMSet *mm = sf->mm;
if ( mm!=NULL ) {
int index;
getint(sfd,&index);
mm->named_instances[index].coords = malloc(mm->axis_count*sizeof(real));
for ( i=0; i<mm->axis_count; ++i )
getreal(sfd,&mm->named_instances[index].coords[i]);
lastnamedinstance = &mm->named_instances[index];
lastaxismap = NULL;
}
} else if ( strmatch(tok,"MacName:")==0 ) {
struct macname *names = SFDParseMacNames(sfd,tok);
if ( lastaxismap!=NULL )
lastaxismap->axisnames = names;
else if ( lastnamedinstance !=NULL )
lastnamedinstance->names = names;
pushedbacktok = true;
} else if ( strmatch(tok,"MMCDV:")==0 ) {
MMSet *mm = sf->mm;
if ( mm!=NULL )
mm->cdv = SFDParseMMSubroutine(sfd);
} else if ( strmatch(tok,"MMNDV:")==0 ) {
MMSet *mm = sf->mm;
if ( mm!=NULL )
mm->ndv = SFDParseMMSubroutine(sfd);
} else if ( strmatch(tok,"BeginMMFonts:")==0 ) {
int cnt;
getint(sfd,&cnt);
getint(sfd,&realcnt);
ff_progress_change_stages(cnt);
ff_progress_change_total(realcnt);
MMInferStuff(sf->mm);
break;
} else if ( strmatch(tok,"BeginSubFonts:")==0 ) {
getint(sfd,&sf->subfontcnt);
sf->subfonts = calloc(sf->subfontcnt,sizeof(SplineFont *));
getint(sfd,&realcnt);
sf->map = EncMap1to1(realcnt);
ff_progress_change_stages(2);
ff_progress_change_total(realcnt);
break;
} else if ( strmatch(tok,"BeginChars:")==0 ) {
int charcnt;
getint(sfd,&charcnt);
if (charcnt<enc->char_cnt) {
IError("SFD file specifies too few slots for its encoding.\n" );
exit( 1 );
}
if ( getint(sfd,&realcnt)!=1 || realcnt==-1 )
realcnt = charcnt;
else
++realcnt;
ff_progress_change_total(realcnt);
sf->glyphcnt = sf->glyphmax = realcnt;
sf->glyphs = calloc(realcnt,sizeof(SplineChar *));
if ( cidmaster!=NULL ) {
sf->map = cidmaster->map;
} else {
sf->map = EncMapNew(charcnt,realcnt,enc);
sf->map->remap = remap;
}
SFDSizeMap(sf->map,sf->glyphcnt,charcnt);
break;
#if HANYANG
} else if ( strmatch(tok,"BeginCompositionRules")==0 ) {
sf->rules = SFDReadCompositionRules(sfd);
#endif
} else {
geteol(sfd,tok);
}
}
if ( fromdir )
sf = SFD_FigureDirType(sf,tok,dirname,enc,remap,had_layer_cnt);
else if ( sf->subfontcnt!=0 ) {
ff_progress_change_stages(2*sf->subfontcnt);
for ( i=0; i<sf->subfontcnt; ++i ) {
if ( i!=0 )
ff_progress_next_stage();
sf->subfonts[i] = SFD_GetFont(sfd,sf,tok,fromdir,dirname,sfdversion);
}
} else if ( sf->mm!=NULL ) {
MMSet *mm = sf->mm;
ff_progress_change_stages(2*(mm->instance_count+1));
for ( i=0; i<mm->instance_count; ++i ) {
if ( i!=0 )
ff_progress_next_stage();
mm->instances[i] = SFD_GetFont(sfd,NULL,tok,fromdir,dirname,sfdversion);
EncMapFree(mm->instances[i]->map); mm->instances[i]->map=NULL;
mm->instances[i]->mm = mm;
}
ff_progress_next_stage();
mm->normal = SFD_GetFont(sfd,NULL,tok,fromdir,dirname,sfdversion);
mm->normal->mm = mm;
sf->mm = NULL;
SplineFontFree(sf);
sf = mm->normal;
if ( sf->map->enc!=&custom ) {
EncMap *map;
MMMatchGlyphs(mm);
map = EncMapFromEncoding(sf,sf->map->enc);
EncMapFree(sf->map);
sf->map = map;
}
} else {
while ( SFDGetChar(sfd,sf,had_layer_cnt)!=NULL ) {
ff_progress_next();
}
ff_progress_next_stage();
}
haddupenc = false;
while ( getname(sfd,tok)==1 ) {
if ( strcmp(tok,"EndSplineFont")==0 || strcmp(tok,"EndSubSplineFont")==0 )
break;
else if ( strcmp(tok,"BitmapFont:")==0 )
SFDGetBitmapFont(sfd,sf,false,NULL);
else if ( strmatch(tok,"DupEnc:")==0 ) {
int enc, orig;
haddupenc = true;
if ( getint(sfd,&enc) && getint(sfd,&orig) && sf->map!=NULL ) {
SFDSetEncMap(sf,orig,enc);
}
}
}
if ( sf->cidmaster==NULL )
SFDFixupRefs(sf);
if ( !haddupenc )
SFD_DoAltUnis(sf);
else
AltUniFigure(sf,sf->map,true);
if ( sf->sfd_version<2 )
SFD_AssignLookups((SplineFont1 *) sf);
if ( !d.hadtimes )
SFTimesFromFile(sf,sfd);
if (sf->map == NULL) sf->map = EncMapNew(sf->glyphcnt,sf->glyphcnt,&custom);
SFDFixupUndoRefs(sf);
return( sf );
}

static int ext4_init_block_bitmap(struct super_block *sb,
struct buffer_head *bh,
ext4_group_t block_group,
struct ext4_group_desc *gdp)
{
unsigned int bit, bit_max;
struct ext4_sb_info *sbi = EXT4_SB(sb);
ext4_fsblk_t start, tmp;
int flex_bg = 0;
J_ASSERT_BH(bh, buffer_locked(bh));
if (!ext4_group_desc_csum_verify(sb, block_group, gdp)) {
ext4_mark_group_bitmap_corrupted(sb, block_group,
EXT4_GROUP_INFO_BBITMAP_CORRUPT |
EXT4_GROUP_INFO_IBITMAP_CORRUPT);
return -EFSBADCRC;
}
memset(bh->b_data, 0, sb->s_blocksize);
bit_max = ext4_num_base_meta_clusters(sb, block_group);
if ((bit_max >> 3) >= bh->b_size)
return -EFSCORRUPTED;
for (bit = 0; bit < bit_max; bit++)
ext4_set_bit(bit, bh->b_data);
start = ext4_group_first_block_no(sb, block_group);
if (ext4_has_feature_flex_bg(sb))
flex_bg = 1;
tmp = ext4_block_bitmap(sb, gdp);
if (!flex_bg || ext4_block_in_group(sb, tmp, block_group))
ext4_set_bit(EXT4_B2C(sbi, tmp - start), bh->b_data);
tmp = ext4_inode_bitmap(sb, gdp);
if (!flex_bg || ext4_block_in_group(sb, tmp, block_group))
ext4_set_bit(EXT4_B2C(sbi, tmp - start), bh->b_data);
tmp = ext4_inode_table(sb, gdp);
for (; tmp < ext4_inode_table(sb, gdp) +
sbi->s_itb_per_group; tmp++) {
if (!flex_bg || ext4_block_in_group(sb, tmp, block_group))
ext4_set_bit(EXT4_B2C(sbi, tmp - start), bh->b_data);
}
ext4_mark_bitmap_end(num_clusters_in_group(sb, block_group),
sb->s_blocksize * 8, bh->b_data);
return 0;
}

GlyphCache::Loader::Loader(const Face & face, const bool dumb_font)
: _head(face, Tag::head),
_hhea(face, Tag::hhea),
_hmtx(face, Tag::hmtx),
_glyf(face, Tag::glyf),
_loca(face, Tag::loca),
_long_fmt(false),
_has_boxes(false),
_num_glyphs_graphics(0),
_num_glyphs_attributes(0),
_num_attrs(0)
{
if (!operator bool())
return;
const Face::Table maxp = Face::Table(face, Tag::maxp);
if (!maxp) { _head = Face::Table(); return; }
_num_glyphs_graphics = TtfUtil::GlyphCount(maxp);
if (_glyf && TtfUtil::LocaLookup(_num_glyphs_graphics-1, _loca, _loca.size(), _head) == size_t(-2))
{
_head = Face::Table();
return;
}
if (!dumb_font)
{
if ((m_pGlat = Face::Table(face, Tag::Glat, 0x00030000)) == NULL
|| (m_pGloc = Face::Table(face, Tag::Gloc)) == NULL
|| m_pGloc.size() < 8)
{
_head = Face::Table();
return;
}
const byte    * p = m_pGloc;
int       version = be::read<uint32>(p);
const uint16    flags = be::read<uint16>(p);
_num_attrs = be::read<uint16>(p);
_long_fmt              = flags & 1;
int tmpnumgattrs       = (m_pGloc.size()
- (p - m_pGloc)
- sizeof(uint16)*(flags & 0x2 ? _num_attrs : 0))
/ (_long_fmt ? sizeof(uint32) : sizeof(uint16)) - 1;
if (version >= 0x00020000 || tmpnumgattrs < 0 || tmpnumgattrs > 65535
|| _num_attrs == 0 || _num_attrs > 0x3000              || _num_glyphs_graphics > tmpnumgattrs
|| m_pGlat.size() < 4)
{
_head = Face::Table();
return;
}
_num_glyphs_attributes = static_cast<unsigned short>(tmpnumgattrs);
p = m_pGlat;
version = be::read<uint32>(p);
if (version >= 0x00040000 || (version >= 0x00030000 && m_pGlat.size() < 8))               {
_head = Face::Table();
return;
}
else if (version >= 0x00030000)
{
unsigned int glatflags = be::read<uint32>(p);
_has_boxes = glatflags & 1;
_has_boxes = true;
}
}
}

static ssize_t store_int_with_restart(struct device *s,
struct device_attribute *attr,
const char *buf, size_t size)
{
ssize_t ret = device_store_int(s, attr, buf, size);
mce_restart();
return ret;
}

bool read_ujpg( void )
{
using namespace IOUtil;
using namespace Sirikata;
unsigned char ujpg_mrk[ 64 ];
write_byte_bill(Billing::HEADER, true, 24); 
str_out->call_size_callback(max_file_size);
uint32_t compressed_header_size = 0;
if (ReadFull(str_in, ujpg_mrk, 4) != 4) {
custom_exit(ExitCode::SHORT_READ);
}
write_byte_bill(Billing::HEADER, true, 4);
compressed_header_size = LEtoUint32(ujpg_mrk);
if (compressed_header_size > 128 * 1024 * 1024 || max_file_size > 128 * 1024 * 1024) {
always_assert(false && "Only support images < 128 megs");
return false;     }
bool pending_header_reads = false;
if (header_reader == NULL) {
std::vector<uint8_t, JpegAllocator<uint8_t> > compressed_header_buffer(compressed_header_size);
IOUtil::ReadFull(str_in, compressed_header_buffer.data(), compressed_header_buffer.size());
header_reader = new MemReadWriter((JpegAllocator<uint8_t>()));
{
if (ujgversion == 1) {
JpegAllocator<uint8_t> no_free_allocator;
#if !defined(USE_STANDARD_MEMORY_ALLOCATORS) && !defined(_WIN32) && !defined(EMSCRIPTEN)
no_free_allocator.setup_memory_subsystem(32 * 1024 * 1024,
16,
&mem_init_nop,
&MemMgrAllocatorMalloc,
&mem_nop,
&mem_realloc_nop,
&MemMgrAllocatorMsize);
#endif
std::pair<std::vector<uint8_t,
Sirikata::JpegAllocator<uint8_t> >,
JpegError> uncompressed_header_buffer(
ZlibDecoderDecompressionReader::Decompress(compressed_header_buffer.data(),
compressed_header_buffer.size(),
no_free_allocator,
max_file_size + 2048));
if (uncompressed_header_buffer.second) {
always_assert(false && "Data not properly zlib coded");
return false;
}
zlib_hdrs = compressed_header_buffer.size();
header_reader->SwapIn(uncompressed_header_buffer.first, 0);
} else {
std::pair<std::vector<uint8_t,
Sirikata::JpegAllocator<uint8_t> >,
JpegError> uncompressed_header_buffer(
Sirikata::BrotliCodec::Decompress(compressed_header_buffer.data(),
compressed_header_buffer.size(),
JpegAllocator<uint8_t>(),
max_file_size * 2 + 128 * 1024 * 1024));
if (uncompressed_header_buffer.second) {
always_assert(false && "Data not properly zlib coded");
return false;
}
zlib_hdrs = compressed_header_buffer.size();
header_reader->SwapIn(uncompressed_header_buffer.first, 0);            
}
}
write_byte_bill(Billing::HEADER,
true,
compressed_header_buffer.size());
} else {
always_assert(compressed_header_size == 0 && "Special concatenation requires 0 size header");
}
grbs = sizeof(EOI);
grbgdata = EOI;         ReadFull(header_reader, ujpg_mrk, 3 ) ;
if ( memcmp( ujpg_mrk, "HDR", 3 ) == 0 ) {
ReadFull(header_reader, ujpg_mrk, 4 );
hdrs = LEtoUint32(ujpg_mrk);
hdrdata = (unsigned char*) aligned_alloc(hdrs);
memset(hdrdata, 0, hdrs);
if ( hdrdata == NULL ) {
fprintf( stderr, MEM_ERRMSG );
errorlevel.store(2);
return false;
}
ReadFull(header_reader, hdrdata, hdrs );
}
else {
fprintf( stderr, "HDR marker not found" );
errorlevel.store(2);
return false;
}
bool memory_optimized_image = (filetype != UJG) && !g_allow_progressive;
if ( !setup_imginfo_jpg(memory_optimized_image) )
return false;
ReadFull(header_reader, ujpg_mrk, 3 );
if ( memcmp( ujpg_mrk, "P0D", 3 ) == 0 ) {
header_reader->Read( reinterpret_cast<unsigned char*>(&padbit), 1 );
}
else if ( memcmp( ujpg_mrk, "PAD", 3 ) == 0 ) {
header_reader->Read( reinterpret_cast<unsigned char*>(&padbit), 1 );
if (!(padbit == 0 || padbit == 1 ||padbit == -1)) {
while (write(2,
"Legacy Padbit must be 0, 1 or -1\n",
strlen("Legacy Padbit must be 0, 1 or -1\n")) < 0
&& errno == EINTR) {
}
custom_exit(ExitCode::STREAM_INCONSISTENT);
}
if (padbit == 1) {
padbit = 0x7f;         }
}
else {
fprintf( stderr, "PAD marker not found" );
errorlevel.store(2);
return false;
}
std::vector<ThreadHandoff> thread_handoff;
while ( ReadFull(header_reader, ujpg_mrk, 3 ) == 3 ) {
if ( memcmp( ujpg_mrk, "CRS", 3 ) == 0 ) {
rst_cnt_set = true;
ReadFull(header_reader, ujpg_mrk, 4);
rst_cnt.resize(LEtoUint32(ujpg_mrk));
for (size_t i = 0; i < rst_cnt.size(); ++i) {
ReadFull(header_reader, ujpg_mrk, 4);
rst_cnt.at(i) = LEtoUint32(ujpg_mrk);
}
} else if ( memcmp( ujpg_mrk, "HHX", 2 ) == 0 ) {             size_t to_alloc = ThreadHandoff::get_remaining_data_size_from_two_bytes(ujpg_mrk + 1) + 2;
if(to_alloc) {
std::vector<unsigned char> data(to_alloc);
data[0] = ujpg_mrk[1];
data[1] = ujpg_mrk[2];
ReadFull(header_reader, &data[2], to_alloc - 2);
thread_handoff = ThreadHandoff::deserialize(&data[0], to_alloc);
}
} else if ( memcmp( ujpg_mrk, "FRS", 3 ) == 0 ) {
ReadFull(header_reader, ujpg_mrk, 4);
scnc = LEtoUint32(ujpg_mrk);
rst_err.insert(rst_err.end(), scnc - rst_err.size(), 0);
ReadFull(header_reader, rst_err.data(), scnc );
}
else if ( memcmp( ujpg_mrk, "GRB", 3 ) == 0 ) {
ReadFull(header_reader, ujpg_mrk, 4);
grbs = LEtoUint32(ujpg_mrk);
grbgdata = aligned_alloc(grbs);
memset(grbgdata, 0, sizeof(grbs));
if ( grbgdata == NULL ) {
fprintf( stderr, MEM_ERRMSG );
errorlevel.store(2);
return false;
}
ReadFull(header_reader, grbgdata, grbs );
}
else if ( memcmp( ujpg_mrk, "PGR", 3 ) == 0 || memcmp( ujpg_mrk, "PGE", 3 ) == 0 ) {
if (ujpg_mrk[2] == 'E') {
embedded_jpeg = true;
}
ReadFull(header_reader, ujpg_mrk, 4);
prefix_grbs = LEtoUint32(ujpg_mrk);
prefix_grbgdata = aligned_alloc(prefix_grbs);
memset(prefix_grbgdata, 0, sizeof(prefix_grbs));
if ( prefix_grbgdata == NULL ) {
fprintf( stderr, MEM_ERRMSG );
errorlevel.store(2);
return false;
}
ReadFull(header_reader, prefix_grbgdata, prefix_grbs );
}
else if ( memcmp( ujpg_mrk, "SIZ", 3 ) == 0 ) {
ReadFull(header_reader, ujpg_mrk, 4);
max_file_size = LEtoUint32(ujpg_mrk);
}
else if ( memcmp( ujpg_mrk, "EEE", 3) == 0) {
ReadFull(header_reader, ujpg_mrk, 28);
max_cmp = LEtoUint32(ujpg_mrk);
max_bpos = LEtoUint32(ujpg_mrk + 4);
max_sah = LEtoUint32(ujpg_mrk + 8);
max_dpos[0] = LEtoUint32(ujpg_mrk + 12);
max_dpos[1] = LEtoUint32(ujpg_mrk + 16);
max_dpos[2] = LEtoUint32(ujpg_mrk + 20);
max_dpos[3] = LEtoUint32(ujpg_mrk + 24);
early_eof_encountered = true;
colldata.set_truncation_bounds(max_cmp, max_bpos, max_dpos, max_sah);
}
else {
if (memcmp(ujpg_mrk, "CNT", 3) == 0 ) {
pending_header_reads = true;
break;
} else if (memcmp(ujpg_mrk, "CMP", 3) == 0 ) {
break;
} else {
fprintf( stderr, "unknown data found" );
errorlevel.store(2);
}
return false;
}
}
if (!pending_header_reads) {
delete header_reader;
header_reader = NULL;
}
write_byte_bill(Billing::HEADER,
false,
2 + hdrs + prefix_grbs + grbs);
ReadFull(str_in, ujpg_mrk, 3 ) ;
write_byte_bill(Billing::HEADER, true, 3);
write_byte_bill(Billing::DELIMITERS, true, 4 * NUM_THREADS);     write_byte_bill(Billing::HEADER, true, 4); 
if (memcmp(ujpg_mrk, "CMP", 3) != 0) {
always_assert(false && "CMP must be present (uncompressed) in the file or CNT continue marker");
return false;     }
colldata.signal_worker_should_begin();
g_decoder->initialize(str_in, thread_handoff);
colldata.start_decoder(g_decoder);
return true;
}

static int decode_hextile(VmncContext *c, uint8_t* dst, GetByteContext *gb,
int w, int h, int stride)
{
int i, j, k;
int bg = 0, fg = 0, rects, color, flags, xy, wh;
const int bpp = c->bpp2;
uint8_t *dst2;
int bw = 16, bh = 16;
for (j = 0; j < h; j += 16) {
dst2 = dst;
bw   = 16;
if (j + 16 > h)
bh = h - j;
for (i = 0; i < w; i += 16, dst2 += 16 * bpp) {
if (bytestream2_get_bytes_left(gb) <= 0) {
av_log(c->avctx, AV_LOG_ERROR, "Premature end of data!\n");
return AVERROR_INVALIDDATA;
}
if (i + 16 > w)
bw = w - i;
flags = bytestream2_get_byte(gb);
if (flags & HT_RAW) {
if (bytestream2_get_bytes_left(gb) < bw * bh * bpp) {
av_log(c->avctx, AV_LOG_ERROR, "Premature end of data!\n");
return AVERROR_INVALIDDATA;
}
paint_raw(dst2, bw, bh, gb, bpp, c->bigendian, stride);
} else {
if (flags & HT_BKG)
bg = vmnc_get_pixel(gb, bpp, c->bigendian);
if (flags & HT_FG)
fg = vmnc_get_pixel(gb, bpp, c->bigendian);
rects = 0;
if (flags & HT_SUB)
rects = bytestream2_get_byte(gb);
color = !!(flags & HT_CLR);
paint_rect(dst2, 0, 0, bw, bh, bg, bpp, stride);
if (bytestream2_get_bytes_left(gb) < rects * (color * bpp + 2)) {
av_log(c->avctx, AV_LOG_ERROR, "Premature end of data!\n");
return AVERROR_INVALIDDATA;
}
for (k = 0; k < rects; k++) {
if (color)
fg = vmnc_get_pixel(gb, bpp, c->bigendian);
xy = bytestream2_get_byte(gb);
wh = bytestream2_get_byte(gb);
paint_rect(dst2, xy >> 4, xy & 0xF,
(wh>>4)+1, (wh & 0xF)+1, fg, bpp, stride);
}
}
}
dst += stride * 16;
}
return 0;
}

int
dwarf_getaranges (Dwarf *dbg, Dwarf_Aranges **aranges, size_t *naranges)
{
if (dbg == NULL)
return -1;
if (dbg->aranges != NULL)
{
*aranges = dbg->aranges;
if (naranges != NULL)
*naranges = dbg->aranges->naranges;
return 0;
}
if (dbg->sectiondata[IDX_debug_aranges] == NULL)
{
*aranges = NULL;
if (naranges != NULL)
*naranges = 0;
return 0;
}
if (dbg->sectiondata[IDX_debug_aranges]->d_buf == NULL)
return -1;
struct arangelist *arangelist = NULL;
unsigned int narangelist = 0;
const unsigned char *readp = dbg->sectiondata[IDX_debug_aranges]->d_buf;
const unsigned char *readendp
= readp + dbg->sectiondata[IDX_debug_aranges]->d_size;
while (readp < readendp)
{
const unsigned char *hdrstart = readp;
if (unlikely (readp + 4 > readendp))
goto invalid;
Dwarf_Word length = read_4ubyte_unaligned_inc (dbg, readp);
unsigned int length_bytes = 4;
if (length == DWARF3_LENGTH_64_BIT)
{
if (unlikely (readp + 8 > readendp))
goto invalid;
length = read_8ubyte_unaligned_inc (dbg, readp);
length_bytes = 8;
}
else if (unlikely (length >= DWARF3_LENGTH_MIN_ESCAPE_CODE
&& length <= DWARF3_LENGTH_MAX_ESCAPE_CODE))
goto invalid;
if (unlikely (readp + 2 > readendp))
goto invalid;
unsigned int version = read_2ubyte_unaligned_inc (dbg, readp);
if (version != 2)
{
invalid:
__libdw_seterrno (DWARF_E_INVALID_DWARF);
fail:
while (arangelist != NULL)
{
struct arangelist *next = arangelist->next;
free (arangelist);
arangelist = next;
}
return -1;
}
Dwarf_Word offset = 0;
if (__libdw_read_offset_inc (dbg,
IDX_debug_aranges, &readp,
length_bytes, &offset, IDX_debug_info, 4))
goto fail;
unsigned int address_size = *readp++;
if (unlikely (address_size != 4 && address_size != 8))
goto invalid;
unsigned int segment_size = *readp++;
if (segment_size != 0)
goto invalid;
readp += ((2 * address_size - ((readp - hdrstart) % (2 * address_size)))
% (2 * address_size));
while (1)
{
Dwarf_Word range_address;
Dwarf_Word range_length;
if (__libdw_read_address_inc (dbg, IDX_debug_aranges, &readp,
address_size, &range_address))
goto fail;
if (readp + address_size > readendp)
goto invalid;
if (address_size == 4)
range_length = read_4ubyte_unaligned_inc (dbg, readp);
else
range_length = read_8ubyte_unaligned_inc (dbg, readp);
if (range_address == 0 && range_length == 0)
break;
struct arangelist *new_arange = malloc (sizeof *new_arange);
if (unlikely (new_arange == NULL))
{
__libdw_seterrno (DWARF_E_NOMEM);
goto fail;
}
new_arange->arange.addr = range_address;
new_arange->arange.length = range_length;
Dwarf_CU *cu = __libdw_findcu (dbg, offset, false);
if (unlikely (cu == NULL))
{
free (new_arange);
goto fail;
}
new_arange->arange.offset = __libdw_first_die_off_from_cu (cu);
new_arange->next = arangelist;
arangelist = new_arange;
++narangelist;
if (unlikely (new_arange->arange.offset
>= dbg->sectiondata[IDX_debug_info]->d_size))
goto invalid;
}
}
if (narangelist == 0)
{
assert (arangelist == NULL);
if (naranges != NULL)
*naranges = 0;
*aranges = NULL;
return 0;
}
void *buf = libdw_alloc (dbg, Dwarf_Aranges,
sizeof (Dwarf_Aranges)
+ narangelist * sizeof (Dwarf_Arange), 1);
assert (sizeof (Dwarf_Arange) >= sizeof (Dwarf_Arange *));
struct arangelist **sortaranges
= (buf + sizeof (Dwarf_Aranges)
+ ((sizeof (Dwarf_Arange) - sizeof sortaranges[0]) * narangelist));
unsigned int i = narangelist;
while (i-- > 0)
{
sortaranges[i] = arangelist;
arangelist = arangelist->next;
}
assert (arangelist == NULL);
qsort (sortaranges, narangelist, sizeof sortaranges[0], &compare_aranges);
*aranges = buf;
(*aranges)->dbg = dbg;
(*aranges)->naranges = narangelist;
dbg->aranges = *aranges;
if (naranges != NULL)
*naranges = narangelist;
for (i = 0; i < narangelist; ++i)
{
struct arangelist *elt = sortaranges[i];
(*aranges)->info[i] = elt->arange;
free (elt);
}
return 0;
}

static int LZWDecode(TIFF *tif, uint8_t *op0, tmsize_t occ0, uint16_t s)
{
static const char module[] = "LZWDecode";
LZWCodecState *sp = DecoderState(tif);
uint8_t *op = (uint8_t *)op0;
tmsize_t occ = occ0;
uint8_t *bp;
long nbits, nextbits, nbitsmask;
WordType nextdata;
code_t *free_entp, *maxcodep, *oldcodep;
(void)s;
assert(sp != NULL);
assert(sp->dec_codetab != NULL);
if (sp->read_error)
{
return 0;
}
if (sp->dec_restart)
{
tmsize_t residue;
code_t *codep = sp->dec_codep;
residue = codep->length - sp->dec_restart;
if (residue > occ)
{
sp->dec_restart += occ;
do
{
codep = codep->next;
} while (--residue > occ && codep);
if (codep)
{
uint8_t *tp = op + occ;
do
{
*--tp = codep->value;
codep = codep->next;
} while (--occ && codep);
}
return (1);
}
op += residue;
occ -= residue;
uint8_t *tp = op;
do
{
*--tp = codep->value;
codep = codep->next;
} while (--residue && codep);
sp->dec_restart = 0;
}
bp = (uint8_t *)tif->tif_rawcp;
sp->dec_bitsleft += (((uint64_t)tif->tif_rawcc - sp->old_tif_rawcc) << 3);
uint64_t dec_bitsleft = sp->dec_bitsleft;
nbits = sp->lzw_nbits;
nextdata = sp->lzw_nextdata;
nextbits = sp->lzw_nextbits;
nbitsmask = sp->dec_nbitsmask;
oldcodep = sp->dec_oldcodep;
free_entp = sp->dec_free_entp;
maxcodep = sp->dec_maxcodep;
code_t *const dec_codetab = sp->dec_codetab;
code_t *codep;
if (occ == 0)
{
goto after_loop;
}
begin:
{
WordType code;
GetNextCodeLZW();
codep = dec_codetab + code;
if (code >= CODE_FIRST)
goto code_above_or_equal_to_258;
if (code < 256)
goto code_below_256;
if (code == CODE_EOI)
goto after_loop;
goto code_clear;
code_below_256:
{
if (codep > free_entp)
goto error_code;
free_entp->next = oldcodep;
free_entp->firstchar = oldcodep->firstchar;
free_entp->length = oldcodep->length + 1;
free_entp->value = (uint8_t)code;
free_entp->repeated =
(bool)(oldcodep->repeated & (oldcodep->value == code));
if (++free_entp > maxcodep)
{
if (++nbits > BITS_MAX) 
nbits = BITS_MAX;
nbitsmask = MAXCODE(nbits);
maxcodep = dec_codetab + nbitsmask - 1;
if (free_entp >= &dec_codetab[CSIZE])
{
free_entp = dec_codetab - 1;
}
}
oldcodep = codep;
*op++ = (uint8_t)code;
occ--;
if (occ == 0)
goto after_loop;
goto begin;
}
code_above_or_equal_to_258:
{
if (codep >= free_entp)
{
if (codep != free_entp)
goto error_code;
free_entp->value = oldcodep->firstchar;
}
else
{
free_entp->value = codep->firstchar;
}
free_entp->repeated =
(bool)(oldcodep->repeated & (oldcodep->value == free_entp->value));
free_entp->next = oldcodep;
free_entp->firstchar = oldcodep->firstchar;
free_entp->length = oldcodep->length + 1;
if (++free_entp > maxcodep)
{
if (++nbits > BITS_MAX) 
nbits = BITS_MAX;
nbitsmask = MAXCODE(nbits);
maxcodep = dec_codetab + nbitsmask - 1;
if (free_entp >= &dec_codetab[CSIZE])
{
free_entp = dec_codetab - 1;
}
}
oldcodep = codep;
unsigned short len = codep->length;
if (len < 3) 
{
if (occ <= 2)
{
if (occ == 2)
{
memcpy(op, &(codep->firstchar), 2);
op += 2;
occ -= 2;
goto after_loop;
}
goto too_short_buffer;
}
memcpy(op, &(codep->firstchar), 2);
op += 2;
occ -= 2;
goto begin; 
}
if (len == 3)
{
if (occ <= 3)
{
if (occ == 3)
{
op[0] = codep->firstchar;
op[1] = codep->next->value;
op[2] = codep->value;
op += 3;
occ -= 3;
goto after_loop;
}
goto too_short_buffer;
}
op[0] = codep->firstchar;
op[1] = codep->next->value;
op[2] = codep->value;
op += 3;
occ -= 3;
goto begin; 
}
if (len > occ)
{
goto too_short_buffer;
}
if (codep->repeated)
{
memset(op, codep->value, len);
op += len;
occ -= len;
if (occ == 0)
goto after_loop;
goto begin;
}
uint8_t *tp = op + len;
assert(len >= 4);
*--tp = codep->value;
codep = codep->next;
*--tp = codep->value;
codep = codep->next;
*--tp = codep->value;
codep = codep->next;
*--tp = codep->value;
if (tp > op)
{
do
{
codep = codep->next;
*--tp = codep->value;
} while (tp > op);
}
assert(occ >= len);
op += len;
occ -= len;
if (occ == 0)
goto after_loop;
goto begin;
}
code_clear:
{
free_entp = dec_codetab + CODE_FIRST;
nbits = BITS_MIN;
nbitsmask = MAXCODE(BITS_MIN);
maxcodep = dec_codetab + nbitsmask - 1;
do
{
GetNextCodeLZW();
} while (code == CODE_CLEAR); 
if (code == CODE_EOI)
goto after_loop;
if (code > CODE_EOI)
{
goto error_code;
}
*op++ = (uint8_t)code;
occ--;
oldcodep = dec_codetab + code;
if (occ == 0)
goto after_loop;
goto begin;
}
}
too_short_buffer:
{
sp->dec_codep = codep;
do
{
codep = codep->next;
} while (codep->length > occ);
sp->dec_restart = occ;
uint8_t *tp = op + occ;
do
{
*--tp = codep->value;
codep = codep->next;
} while (--occ);
}
after_loop:
tif->tif_rawcc -= (tmsize_t)((uint8_t *)bp - tif->tif_rawcp);
tif->tif_rawcp = (uint8_t *)bp;
sp->old_tif_rawcc = tif->tif_rawcc;
sp->dec_bitsleft = dec_bitsleft;
sp->lzw_nbits = (unsigned short)nbits;
sp->lzw_nextdata = nextdata;
sp->lzw_nextbits = nextbits;
sp->dec_nbitsmask = nbitsmask;
sp->dec_oldcodep = oldcodep;
sp->dec_free_entp = free_entp;
sp->dec_maxcodep = maxcodep;
if (occ > 0)
{
TIFFErrorExtR(tif, module,
"Not enough data at scanline %" PRIu32 " (short %" PRIu64
" bytes)",
tif->tif_row, (uint64_t)occ);
return (0);
}
return (1);
no_eoi:
TIFFErrorExtR(tif, module,
"LZWDecode: Strip %" PRIu32 " not terminated with EOI code",
tif->tif_curstrip);
return 0;
error_code:
sp->read_error = 1;
TIFFErrorExtR(tif, tif->tif_name, "Using code not yet in table");
return 0;
}

static int del_accepted(TCP_Server *tcp_server, int index)
{
if ((uint32_t)index >= tcp_server->size_accepted_connections) {
return -1;
}
if (tcp_server->accepted_connection_array[index].status == TCP_STATUS_NO_STATUS) {
return -1;
}
if (!bs_list_remove(&tcp_server->accepted_key_list, tcp_server->accepted_connection_array[index].public_key, index)) {
return -1;
}
crypto_memzero(&tcp_server->accepted_connection_array[index], sizeof(TCP_Secure_Connection));
--tcp_server->num_accepted_connections;
if (tcp_server->num_accepted_connections == 0) {
realloc_connection(tcp_server, 0);
}
return 0;
}

static Image *ReadPALMImage(const ImageInfo *image_info,
ExceptionInfo *exception)
{
Image
*image;
IndexPacket
index;
MagickBooleanType
status;
MagickOffsetType
totalOffset,
seekNextDepth;
MagickPixelPacket
transpix;
register IndexPacket
*indexes;
register ssize_t
i,
x;
register PixelPacket
*q;
size_t
bytes_per_row,
flags,
bits_per_pixel,
version,
nextDepthOffset,
transparentIndex,
compressionType,
byte,
mask,
redbits,
greenbits,
bluebits,
one,
pad,
size,
bit;
ssize_t
count,
y;
unsigned char
*lastrow,
*one_row,
*ptr;
unsigned short
color16;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickSignature);
if (image_info->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
image_info->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickSignature);
image=AcquireImage(image_info);
status=OpenBlob(image_info,image,ReadBinaryBlobMode,exception);
if (status == MagickFalse)
{
(void) DestroyImageList(image);
return((Image *) NULL);
}
totalOffset=0;
do
{
image->columns=ReadBlobMSBShort(image);
image->rows=ReadBlobMSBShort(image);
if (EOFBlob(image) != MagickFalse)
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
if ((image->columns == 0) || (image->rows == 0))
ThrowReaderException(CorruptImageError,"NegativeOrZeroImageSize");
status=SetImageExtent(image,image->columns,image->rows);
if (status == MagickFalse)
{
InheritException(exception,&image->exception);
return(DestroyImageList(image));
}
bytes_per_row=ReadBlobMSBShort(image);
flags=ReadBlobMSBShort(image);
bits_per_pixel=(size_t) ReadBlobByte(image);
if ((bits_per_pixel != 1) && (bits_per_pixel != 2) &&
(bits_per_pixel != 4) && (bits_per_pixel != 8) &&
(bits_per_pixel != 16))
ThrowReaderException(CorruptImageError,"UnrecognizedBitsPerPixel");
version=(size_t) ReadBlobByte(image);
if ((version != 0) && (version != 1) && (version != 2))
ThrowReaderException(CorruptImageError,"FileFormatVersionMismatch");
nextDepthOffset=(size_t) ReadBlobMSBShort(image);
transparentIndex=(size_t) ReadBlobByte(image);
compressionType=(size_t) ReadBlobByte(image);
if ((compressionType != PALM_COMPRESSION_NONE) &&
(compressionType != PALM_COMPRESSION_SCANLINE ) &&
(compressionType != PALM_COMPRESSION_RLE))
ThrowReaderException(CorruptImageError,"UnrecognizedImageCompression");
pad=ReadBlobMSBShort(image);
(void) pad;
one=1;
if ((bits_per_pixel < 16) &&
(AcquireImageColormap(image,one << bits_per_pixel) == MagickFalse))
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
GetMagickPixelPacket(image,&transpix);
if (bits_per_pixel == 16)  
{
redbits=(size_t) ReadBlobByte(image);  
(void) redbits;
greenbits=(size_t) ReadBlobByte(image);  
(void) greenbits;
bluebits=(size_t) ReadBlobByte(image);  
(void) bluebits;
ReadBlobByte(image);  
ReadBlobByte(image);  
transpix.red=(MagickRealType) (QuantumRange*ReadBlobByte(image)/31);
transpix.green=(MagickRealType) (QuantumRange*ReadBlobByte(image)/63);
transpix.blue=(MagickRealType) (QuantumRange*ReadBlobByte(image)/31);
}
if (bits_per_pixel == 8)
{
IndexPacket
index;
if (flags & PALM_HAS_COLORMAP_FLAG)
{
count=(ssize_t) ReadBlobMSBShort(image);
for (i=0; i < (ssize_t) count; i++)
{
ReadBlobByte(image);
index=ConstrainColormapIndex(image,(size_t) (255-i));
image->colormap[(int) index].red=ScaleCharToQuantum(
(unsigned char) ReadBlobByte(image));
image->colormap[(int) index].green=ScaleCharToQuantum(
(unsigned char) ReadBlobByte(image));
image->colormap[(int) index].blue=ScaleCharToQuantum(
(unsigned char) ReadBlobByte(image));
}
}
else
for (i=0; i < (ssize_t) (1L << bits_per_pixel); i++)
{
index=ConstrainColormapIndex(image,(size_t) (255-i));
image->colormap[(int) index].red=ScaleCharToQuantum(
PalmPalette[i][0]);
image->colormap[(int) index].green=ScaleCharToQuantum(
PalmPalette[i][1]);
image->colormap[(int) index].blue=ScaleCharToQuantum(
PalmPalette[i][2]);
}
}
if (flags & PALM_IS_COMPRESSED_FLAG)
size=ReadBlobMSBShort(image);
(void) size;
image->storage_class=DirectClass;
if (bits_per_pixel < 16)
{
image->storage_class=PseudoClass;
image->depth=8;
}
if (image_info->ping != MagickFalse) 
{
(void) CloseBlob(image);
return(image);
}
status=SetImageExtent(image,image->columns,image->rows);
if (status == MagickFalse)
{
InheritException(exception,&image->exception);
return(DestroyImageList(image));
}
one_row=(unsigned char *) AcquireQuantumMemory(MagickMax(bytes_per_row,
2*image->columns),sizeof(*one_row));
if (one_row == (unsigned char *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
lastrow=(unsigned char *) NULL;
if (compressionType == PALM_COMPRESSION_SCANLINE)
{
lastrow=(unsigned char *) AcquireQuantumMemory(MagickMax(bytes_per_row,
2*image->columns),sizeof(*lastrow));
if (lastrow == (unsigned char *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
}
mask=(size_t) (1U << bits_per_pixel)-1;
for (y=0; y < (ssize_t) image->rows; y++)
{
if ((flags & PALM_IS_COMPRESSED_FLAG) == 0)
{
image->compression=NoCompression;
count=ReadBlob(image,bytes_per_row,one_row);
if (count != (ssize_t) bytes_per_row)
break;
}
else
{
if (compressionType == PALM_COMPRESSION_RLE)
{
image->compression=RLECompression;
for (i=0; i < (ssize_t) bytes_per_row; )
{
count=(ssize_t) ReadBlobByte(image);
if (count < 0)
break;
count=MagickMin(count,(ssize_t) bytes_per_row-i);
byte=(size_t) ReadBlobByte(image);
(void) ResetMagickMemory(one_row+i,(int) byte,(size_t) count);
i+=count;
}
}
else
if (compressionType == PALM_COMPRESSION_SCANLINE)
{
size_t
one;
one=1;
image->compression=FaxCompression;
for (i=0; i < (ssize_t) bytes_per_row; i+=8)
{
count=(ssize_t) ReadBlobByte(image);
if (count < 0)
break;
byte=(size_t) MagickMin((ssize_t) bytes_per_row-i,8);
for (bit=0; bit < byte; bit++)
{
if ((y == 0) || (count & (one << (7 - bit))))
one_row[i+bit]=(unsigned char) ReadBlobByte(image);
else
one_row[i+bit]=lastrow[i+bit];
}
}
(void) CopyMagickMemory(lastrow, one_row, bytes_per_row);
}
}
ptr=one_row;
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (PixelPacket *) NULL)
break;
indexes=GetAuthenticIndexQueue(image);
if (bits_per_pixel == 16)
{
if (image->columns > (2*bytes_per_row))
ThrowReaderException(CorruptImageError,"CorruptImage");
for (x=0; x < (ssize_t) image->columns; x++)
{
color16=(*ptr++ << 8);
color16|=(*ptr++);
SetPixelRed(q,(QuantumRange*((color16 >> 11) & 0x1f))/0x1f);
SetPixelGreen(q,(QuantumRange*((color16 >> 5) & 0x3f))/0x3f);
SetPixelBlue(q,(QuantumRange*((color16 >> 0) & 0x1f))/0x1f);
SetPixelOpacity(q,OpaqueOpacity);
q++;
}
}
else
{
bit=8-bits_per_pixel;
for (x=0; x < (ssize_t) image->columns; x++)
{
if ((size_t) (ptr-one_row) >= bytes_per_row)
ThrowReaderException(CorruptImageError,"CorruptImage");
index=(IndexPacket) (mask-(((*ptr) & (mask << bit)) >> bit));
SetPixelIndex(indexes+x,index);
SetPixelRGBO(q,image->colormap+(ssize_t) index);
if (bit)
bit-=bits_per_pixel;
else
{
ptr++;
bit=8-bits_per_pixel;
}
q++;
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
}
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
if (flags & PALM_HAS_TRANSPARENCY_FLAG)
{
IndexPacket index=ConstrainColormapIndex(image,(mask-transparentIndex));
if (bits_per_pixel != 16)
SetMagickPixelPacket(image,image->colormap+(ssize_t) index,
(const IndexPacket *) NULL,&transpix);
(void) TransparentPaintImage(image,&transpix,(Quantum)
TransparentOpacity,MagickFalse);
}
one_row=(unsigned char *) RelinquishMagickMemory(one_row);
if (compressionType == PALM_COMPRESSION_SCANLINE)
lastrow=(unsigned char *) RelinquishMagickMemory(lastrow);
if (EOFBlob(image) != MagickFalse)
{
ThrowFileException(exception,CorruptImageError,"UnexpectedEndOfFile",
image->filename);
break;
}
if (image_info->number_scenes != 0)
if (image->scene >= (image_info->scene+image_info->number_scenes-1))
break;
if (nextDepthOffset != 0)
{
totalOffset+=(MagickOffsetType) (nextDepthOffset*4);
if (totalOffset >= (MagickOffsetType) GetBlobSize(image))
ThrowReaderException(CorruptImageError,"ImproperImageHeader")
else
seekNextDepth=SeekBlob(image,totalOffset,SEEK_SET);
if (seekNextDepth != totalOffset)
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
AcquireNextImage(image_info,image);
if (GetNextImageInList(image) == (Image *) NULL)
{
(void) DestroyImageList(image);
return((Image *) NULL);
}
image=SyncNextImageInList(image);
status=SetImageProgress(image,LoadImagesTag,TellBlob(image),
GetBlobSize(image));
if (status == MagickFalse)
break;
}
} while (nextDepthOffset != 0);
(void) CloseBlob(image);
return(GetFirstImageInList(image));
}

static int rev_body(char *hostname, int s, int stype, unsigned char *context)
{
char *buf = NULL;
int i;
int ret = 1;
SSL *con;
BIO *io, *ssl_bio, *sbio;
#ifndef OPENSSL_NO_KRB5
KSSL_CTX *kctx;
#endif
buf = OPENSSL_malloc(bufsize);
if (buf == NULL)
return (0);
io = BIO_new(BIO_f_buffer());
ssl_bio = BIO_new(BIO_f_ssl());
if ((io == NULL) || (ssl_bio == NULL))
goto err;
if (!BIO_set_write_buffer_size(io, bufsize))
goto err;
if ((con = SSL_new(ctx)) == NULL)
goto err;
#ifndef OPENSSL_NO_TLSEXT
if (s_tlsextdebug) {
SSL_set_tlsext_debug_callback(con, tlsext_cb);
SSL_set_tlsext_debug_arg(con, bio_s_out);
}
#endif
#ifndef OPENSSL_NO_KRB5
if ((kctx = kssl_ctx_new()) != NULL) {
kssl_ctx_setstring(kctx, KSSL_SERVICE, KRB5SVC);
kssl_ctx_setstring(kctx, KSSL_KEYTAB, KRB5KEYTAB);
}
#endif                          
if (context)
SSL_set_session_id_context(con, context, strlen((char *)context));
sbio = BIO_new_socket(s, BIO_NOCLOSE);
SSL_set_bio(con, sbio, sbio);
SSL_set_accept_state(con);
BIO_set_ssl(ssl_bio, con, BIO_CLOSE);
BIO_push(io, ssl_bio);
#ifdef CHARSET_EBCDIC
io = BIO_push(BIO_new(BIO_f_ebcdic_filter()), io);
#endif
if (s_debug) {
SSL_set_debug(con, 1);
BIO_set_callback(SSL_get_rbio(con), bio_dump_callback);
BIO_set_callback_arg(SSL_get_rbio(con), (char *)bio_s_out);
}
if (s_msg) {
#ifndef OPENSSL_NO_SSL_TRACE
if (s_msg == 2)
SSL_set_msg_callback(con, SSL_trace);
else
#endif
SSL_set_msg_callback(con, msg_cb);
SSL_set_msg_callback_arg(con, bio_s_msg ? bio_s_msg : bio_s_out);
}
for (;;) {
i = BIO_do_handshake(io);
if (i > 0)
break;
if (!BIO_should_retry(io)) {
BIO_puts(bio_err, "CONNECTION FAILURE\n");
ERR_print_errors(bio_err);
goto end;
}
#ifndef OPENSSL_NO_SRP
if (BIO_should_io_special(io)
&& BIO_get_retry_reason(io) == BIO_RR_SSL_X509_LOOKUP) {
BIO_printf(bio_s_out, "LOOKUP renego during accept\n");
srp_callback_parm.user =
SRP_VBASE_get_by_user(srp_callback_parm.vb,
srp_callback_parm.login);
if (srp_callback_parm.user)
BIO_printf(bio_s_out, "LOOKUP done %s\n",
srp_callback_parm.user->info);
else
BIO_printf(bio_s_out, "LOOKUP not successful\n");
continue;
}
#endif
}
BIO_printf(bio_err, "CONNECTION ESTABLISHED\n");
print_ssl_summary(bio_err, con);
for (;;) {
i = BIO_gets(io, buf, bufsize - 1);
if (i < 0) {            
if (!BIO_should_retry(io)) {
if (!s_quiet)
ERR_print_errors(bio_err);
goto err;
} else {
BIO_printf(bio_s_out, "read R BLOCK\n");
#ifndef OPENSSL_NO_SRP
if (BIO_should_io_special(io)
&& BIO_get_retry_reason(io) == BIO_RR_SSL_X509_LOOKUP) {
BIO_printf(bio_s_out, "LOOKUP renego during read\n");
srp_callback_parm.user =
SRP_VBASE_get_by_user(srp_callback_parm.vb,
srp_callback_parm.login);
if (srp_callback_parm.user)
BIO_printf(bio_s_out, "LOOKUP done %s\n",
srp_callback_parm.user->info);
else
BIO_printf(bio_s_out, "LOOKUP not successful\n");
continue;
}
#endif
#if defined(OPENSSL_SYS_NETWARE)
delay(1000);
#elif !defined(OPENSSL_SYS_MSDOS) && !defined(__DJGPP__)
sleep(1);
#endif
continue;
}
} else if (i == 0) {    
ret = 1;
BIO_printf(bio_err, "CONNECTION CLOSED\n");
goto end;
} else {
char *p = buf + i - 1;
while (i && (*p == '\n' || *p == '\r')) {
p--;
i--;
}
if (!s_ign_eof && i == 5 && !strncmp(buf, "CLOSE", 5)) {
ret = 1;
BIO_printf(bio_err, "CONNECTION CLOSED\n");
goto end;
}
BUF_reverse((unsigned char *)buf, NULL, i);
buf[i] = '\n';
BIO_write(io, buf, i + 1);
for (;;) {
i = BIO_flush(io);
if (i > 0)
break;
if (!BIO_should_retry(io))
goto end;
}
}
}
end:
SSL_set_shutdown(con, SSL_SENT_SHUTDOWN | SSL_RECEIVED_SHUTDOWN);
err:
if (buf != NULL)
OPENSSL_free(buf);
if (io != NULL)
BIO_free_all(io);
return (ret);
}

static bool io_identity_cow(struct io_kiocb *req)
{
struct io_uring_task *tctx = current->io_uring;
const struct cred *creds = NULL;
struct io_identity *id;
if (req->work.flags & IO_WQ_WORK_CREDS)
creds = req->work.identity->creds;
id = kmemdup(req->work.identity, sizeof(*id), GFP_KERNEL);
if (unlikely(!id)) {
req->work.flags |= IO_WQ_WORK_CANCEL;
return false;
}
io_init_identity(id);
if (creds)
id->creds = creds;
refcount_inc(&id->count);
if (tctx->identity != &tctx->__identity &&
refcount_dec_and_test(&tctx->identity->count))
kfree(tctx->identity);
if (req->work.identity != &tctx->__identity &&
refcount_dec_and_test(&req->work.identity->count))
kfree(req->work.identity);
req->work.identity = id;
tctx->identity = id;
return true;
}

BUILT_IN(selector_append)
{
List_Ptr arglist = ARG("$selectors", List);
if( arglist->length() == 0 )
error("$selectors: At least one selector must be passed for `selector-append'", pstate, traces);
SelectorStack parsedSelectors;
for (size_t i = 0, L = arglist->length(); i < L; ++i) {
Expression_Obj exp = Cast<Expression>(arglist->value_at_index(i));
if (exp->concrete_type() == Expression::NULL_VAL) {
std::stringstream msg;
msg << "$selectors: null is not a valid selector: it must be a string,\n";
msg << "a list of strings, or a list of lists of strings for 'selector-append'";
error(msg.str(), pstate, traces);
}
if (String_Constant_Ptr str = Cast<String_Constant>(exp)) {
str->quote_mark(0);
}
std::string exp_src = exp->to_string();
Selector_List_Obj sel = Parser::parse_selector(exp_src.c_str(), ctx, traces,
exp->pstate(), pstate.src,
false);
parsedSelectors.push_back(sel);
}
if( parsedSelectors.empty() ) {
return SASS_MEMORY_NEW(Null, pstate);
}
SelectorStack::iterator itr = parsedSelectors.begin();
Selector_List_Obj result = *itr;
++itr;
for(;itr != parsedSelectors.end(); ++itr) {
Selector_List_Obj child = *itr;
std::vector<Complex_Selector_Obj> newElements;
for (size_t i = 0, resultLen = result->length(); i < resultLen; ++i) {
for (size_t j = 0, childLen = child->length(); j < childLen; ++j) {
Complex_Selector_Obj parentSeqClone = SASS_MEMORY_CLONE((*result)[i]);
Complex_Selector_Obj childSeq = (*child)[j];
Complex_Selector_Obj base = childSeq->tail();
if( childSeq->combinator() != Complex_Selector::Combinator::ANCESTOR_OF ) {
std::string msg("Can't append \"");
msg += childSeq->to_string();
msg += "\" to \"";
msg += parentSeqClone->to_string();
msg += "\" for `selector-append'";
error(msg, pstate, traces);
}
Element_Selector_Obj pType = Cast<Element_Selector>(childSeq->head()->first());
if(pType && pType->name() == "*") {
std::string msg("Can't append \"");
msg += childSeq->to_string();
msg += "\" to \"";
msg += parentSeqClone->to_string();
msg += "\" for `selector-append'";
error(msg, pstate, traces);
}
parentSeqClone->mutable_last()->head()->concat(base->head());
parentSeqClone->mutable_last()->tail( base->tail() );
newElements.push_back(parentSeqClone);
}
}
result->elements(newElements);
}
Listize listize;
return Cast<Value>(result->perform(&listize));
}

char_u *
do_string_sub(
char_u*str,
char_u*pat,
char_u*sub,
typval_T*expr,
char_u*flags)
{
intsublen;
regmatch_Tregmatch;
inti;
intdo_all;
char_u*tail;
char_u*end;
garray_Tga;
char_u*ret;
char_u*save_cpo;
char_u*zero_width = NULL;
save_cpo = p_cpo;
p_cpo = empty_option;
ga_init2(&ga, 1, 200);
do_all = (flags[0] == 'g');
regmatch.rm_ic = p_ic;
regmatch.regprog = vim_regcomp(pat, RE_MAGIC + RE_STRING);
if (regmatch.regprog != NULL)
{
tail = str;
end = str + STRLEN(str);
while (vim_regexec_nl(&regmatch, str, (colnr_T)(tail - str)))
{
if (regmatch.startp[0] == regmatch.endp[0])
{
if (zero_width == regmatch.startp[0])
{
i = mb_ptr2len(tail);
mch_memmove((char_u *)ga.ga_data + ga.ga_len, tail,
(size_t)i);
ga.ga_len += i;
tail += i;
continue;
}
zero_width = regmatch.startp[0];
}
sublen = vim_regsub(&regmatch, sub, expr, tail, 0, REGSUB_MAGIC);
if (ga_grow(&ga, (int)((end - tail) + sublen -
(regmatch.endp[0] - regmatch.startp[0]))) == FAIL)
{
ga_clear(&ga);
break;
}
i = (int)(regmatch.startp[0] - tail);
mch_memmove((char_u *)ga.ga_data + ga.ga_len, tail, (size_t)i);
(void)vim_regsub(&regmatch, sub, expr,
(char_u *)ga.ga_data + ga.ga_len + i, sublen,
REGSUB_COPY | REGSUB_MAGIC);
ga.ga_len += i + sublen - 1;
tail = regmatch.endp[0];
if (*tail == NUL)
break;
if (!do_all)
break;
}
if (ga.ga_data != NULL)
STRCPY((char *)ga.ga_data + ga.ga_len, tail);
vim_regfree(regmatch.regprog);
}
ret = vim_strsave(ga.ga_data == NULL ? str : (char_u *)ga.ga_data);
ga_clear(&ga);
if (p_cpo == empty_option)
p_cpo = save_cpo;
else
{
if (*p_cpo == NUL)
set_option_value_give_err((char_u *)"cpo", 0L, save_cpo, 0);
free_string_option(save_cpo);
}
return ret;
}

AP4_Result
AP4_DescriptorFactory::CreateDescriptorFromStream(AP4_ByteStream&  stream, 
AP4_Descriptor*& descriptor)
{
AP4_Result result;
descriptor = NULL;
AP4_Position offset;
stream.Tell(offset);
unsigned char tag;
result = stream.ReadUI08(tag);
if (AP4_FAILED(result)) {
stream.Seek(offset);
return result;
}
AP4_UI32      payload_size = 0;
unsigned int  header_size = 1;
unsigned int  max  = 4;
unsigned char ext  = 0;
do {
header_size++;
result = stream.ReadUI08(ext);
if (AP4_FAILED(result)) {
stream.Seek(offset);
return result;
}
payload_size = (payload_size<<7) + (ext&0x7F);
} while (--max && (ext&0x80));
if (payload_size) {
switch (tag) {
case AP4_DESCRIPTOR_TAG_OD:
case AP4_DESCRIPTOR_TAG_MP4_OD:
descriptor = new AP4_ObjectDescriptor(stream, tag, header_size, payload_size);
break;
case AP4_DESCRIPTOR_TAG_IOD:
case AP4_DESCRIPTOR_TAG_MP4_IOD:
descriptor = new AP4_InitialObjectDescriptor(stream, tag, header_size, payload_size);
break;
case AP4_DESCRIPTOR_TAG_ES_ID_INC:
descriptor = new AP4_EsIdIncDescriptor(stream, header_size, payload_size);
break;
case AP4_DESCRIPTOR_TAG_ES_ID_REF:
descriptor = new AP4_EsIdRefDescriptor(stream, header_size, payload_size);
break;
case AP4_DESCRIPTOR_TAG_ES:
descriptor = new AP4_EsDescriptor(stream, header_size, payload_size);
break;
case AP4_DESCRIPTOR_TAG_DECODER_CONFIG:
descriptor = new AP4_DecoderConfigDescriptor(stream, header_size, payload_size);
break;
case AP4_DESCRIPTOR_TAG_DECODER_SPECIFIC_INFO:
descriptor = new AP4_DecoderSpecificInfoDescriptor(stream, header_size, payload_size);
break;
case AP4_DESCRIPTOR_TAG_SL_CONFIG:
if (payload_size != 1) return AP4_ERROR_INVALID_FORMAT;
descriptor = new AP4_SLConfigDescriptor(header_size);
break;
case AP4_DESCRIPTOR_TAG_IPMP_DESCRIPTOR_POINTER:
descriptor = new AP4_IpmpDescriptorPointer(stream, header_size, payload_size);
break;
case AP4_DESCRIPTOR_TAG_IPMP_DESCRIPTOR:
descriptor = new AP4_IpmpDescriptor(stream, header_size, payload_size);
break;
default:
descriptor = new AP4_UnknownDescriptor(stream, tag, header_size, payload_size);
break;
}
}
stream.Seek(offset+header_size+payload_size);
return AP4_SUCCESS;
}

void
ngx_gmtime(time_t t, ngx_tm_t *tp)
{
ngx_int_t   yday;
ngx_uint_t  sec, min, hour, mday, mon, year, wday, days, leap;
if (t < 0) {
t = 0;
}
days = t / 86400;
sec = t % 86400;
wday = (4 + days) % 7;
hour = sec / 3600;
sec %= 3600;
min = sec / 60;
sec %= 60;
days = days - (31 + 28) + 719527;
year = (days + 2) * 400 / (365 * 400 + 100 - 4 + 1);
yday = days - (365 * year + year / 4 - year / 100 + year / 400);
if (yday < 0) {
leap = (year % 4 == 0) && (year % 100 || (year % 400 == 0));
yday = 365 + leap + yday;
year--;
}
mon = (yday + 31) * 10 / 306;
mday = yday - (367 * mon / 12 - 30) + 1;
if (yday >= 306) {
year++;
mon -= 10;
} else {
mon += 2;
}
tp->ngx_tm_sec = (ngx_tm_sec_t) sec;
tp->ngx_tm_min = (ngx_tm_min_t) min;
tp->ngx_tm_hour = (ngx_tm_hour_t) hour;
tp->ngx_tm_mday = (ngx_tm_mday_t) mday;
tp->ngx_tm_mon = (ngx_tm_mon_t) mon;
tp->ngx_tm_year = (ngx_tm_year_t) year;
tp->ngx_tm_wday = (ngx_tm_wday_t) wday;
}

static int dxtory_decode_v1_420(AVCodecContext *avctx, AVFrame *pic,
const uint8_t *src, int src_size)
{
int h, w;
uint8_t *Y1, *Y2, *U, *V;
int ret;
if (src_size < avctx->width * avctx->height * 3 / 2) {
av_log(avctx, AV_LOG_ERROR, "packet too small\n");
return AVERROR_INVALIDDATA;
}
avctx->pix_fmt = AV_PIX_FMT_YUV420P;
if ((ret = ff_get_buffer(avctx, pic, 0)) < 0)
return ret;
Y1 = pic->data[0];
Y2 = pic->data[0] + pic->linesize[0];
U  = pic->data[1];
V  = pic->data[2];
for (h = 0; h < avctx->height; h += 2) {
for (w = 0; w < avctx->width; w += 2) {
AV_COPY16(Y1 + w, src);
AV_COPY16(Y2 + w, src + 2);
U[w >> 1] = src[4] + 0x80;
V[w >> 1] = src[5] + 0x80;
src += 6;
}
Y1 += pic->linesize[0] << 1;
Y2 += pic->linesize[0] << 1;
U  += pic->linesize[1];
V  += pic->linesize[2];
}
return 0;
}

