log_error_errno(r, "Failed to open data file stream: %m");
goto fail;
}
r = take_fdopen_unlocked(&entry_fd, "w+", &entry_fp);
if (r < 0) {
log_error_errno(r, "Failed to open entry file stream: %m");
goto fail;
