le64toh(f->header->data_hash_table_size));
if (r < 0)
goto fail;
break;
case OBJECT_FIELD_HASH_TABLE:
r = verify_hash_table(o, p, &n_field_hash_tables,
le64toh(f->header->field_hash_table_offset),
le64toh(f->header->field_hash_table_size));
if (r < 0)
goto fail;
break;
