r = -EBADMSG;
goto fail;
}
if (entry_seqnum_set &&
entry_seqnum != le64toh(f->header->tail_entry_seqnum)) {
error(offsetof(Header, tail_entry_seqnum),
"Tail entry sequence number incorrect (%"PRIu64" != %"PRIu64")",
entry_seqnum,
le64toh(f->header->tail_entry_seqnum));
r = -EBADMSG;
goto fail;
}
