}
(void) memset(&dib_info,0,sizeof(dib_info));
dib_info.size=ReadBlobLSBLong(image);
if (dib_info.size != 40)
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
dib_info.width=ReadBlobLSBSignedLong(image);
dib_info.height=ReadBlobLSBSignedLong(image);
dib_info.planes=ReadBlobLSBShort(image);
dib_info.bits_per_pixel=ReadBlobLSBShort(image);
if (dib_info.bits_per_pixel > 32)
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
dib_info.compression=ReadBlobLSBLong(image);
dib_info.image_size=ReadBlobLSBLong(image);
dib_info.x_pixels=ReadBlobLSBLong(image);
dib_info.y_pixels=ReadBlobLSBLong(image);
dib_info.number_colors=ReadBlobLSBLong(image);
dib_info.colors_important=ReadBlobLSBLong(image);
if ((dib_info.bits_per_pixel != 1) && (dib_info.bits_per_pixel != 4) &&
(dib_info.bits_per_pixel != 8) && (dib_info.bits_per_pixel != 16) &&
(dib_info.bits_per_pixel != 24) && (dib_info.bits_per_pixel != 32))
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
if ((dib_info.compression == BI_BITFIELDS) &&
((dib_info.bits_per_pixel == 16) || (dib_info.bits_per_pixel == 32)))
{
dib_info.red_mask=(unsigned short) ReadBlobLSBLong(image);
dib_info.green_mask=(unsigned short) ReadBlobLSBLong(image);
dib_info.blue_mask=(unsigned short) ReadBlobLSBLong(image);
}
if (EOFBlob(image) != MagickFalse)
ThrowReaderException(CorruptImageError,"UnexpectedEndOfFile");
if (dib_info.width <= 0)
ThrowReaderException(CorruptImageError,"NegativeOrZeroImageSize");
if (dib_info.height == 0)
ThrowReaderException(CorruptImageError,"NegativeOrZeroImageSize");
if (dib_info.planes != 1)
ThrowReaderException(CorruptImageError,"StaticPlanesValueNotEqualToOne");
if ((dib_info.bits_per_pixel != 1) && (dib_info.bits_per_pixel != 4) &&
(dib_info.bits_per_pixel != 8) && (dib_info.bits_per_pixel != 16) &&
(dib_info.bits_per_pixel != 24) && (dib_info.bits_per_pixel != 32))
ThrowReaderException(CorruptImageError,"UnrecognizedBitsPerPixel");
if ((dib_info.bits_per_pixel < 16) &&
(dib_info.number_colors > (unsigned int) (1UL << dib_info.bits_per_pixel)))
ThrowReaderException(CorruptImageError,"UnrecognizedNumberOfColors");
if ((dib_info.compression == 1) && (dib_info.bits_per_pixel != 8))
ThrowReaderException(CorruptImageError,"UnrecognizedBitsPerPixel");
if ((dib_info.compression == 2) && (dib_info.bits_per_pixel != 4))
ThrowReaderException(CorruptImageError,"UnrecognizedBitsPerPixel");
if ((dib_info.compression == 3) && (dib_info.bits_per_pixel < 16))
ThrowReaderException(CorruptImageError,"UnrecognizedBitsPerPixel");
switch (dib_info.compression)
{
case BI_RGB:
case BI_RLE8:
case BI_RLE4:
case BI_BITFIELDS:
break;
case BI_JPEG:
ThrowReaderException(CoderError,"JPEGCompressNotSupported");
case BI_PNG:
ThrowReaderException(CoderError,"PNGCompressNotSupported");
default:
ThrowReaderException(CorruptImageError,"UnrecognizedImageCompression");
}
image->columns=(size_t) MagickAbsoluteValue((ssize_t) dib_info.width);
image->rows=(size_t) MagickAbsoluteValue((ssize_t) dib_info.height);
image->depth=8;
image->alpha_trait=dib_info.bits_per_pixel == 32 ? BlendPixelTrait :
UndefinedPixelTrait;
if ((dib_info.number_colors > 256) || (dib_info.colors_important > 256))
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
if ((dib_info.number_colors != 0) || (dib_info.bits_per_pixel < 16))
{
size_t
one;
image->storage_class=PseudoClass;
image->colors=dib_info.number_colors;
one=1;
if (image->colors == 0)
image->colors=one << dib_info.bits_per_pixel;
}
if (image_info->size)
{
RectangleInfo
geometry;
MagickStatusType
flags;
flags=ParseAbsoluteGeometry(image_info->size,&geometry);
if (flags & WidthValue)
if ((geometry.width != 0) && (geometry.width < image->columns))
image->columns=geometry.width;
if (flags & HeightValue)
if ((geometry.height != 0) && (geometry.height < image->rows))
image->rows=geometry.height;
}
status=SetImageExtent(image,image->columns,image->rows,exception);
if (status == MagickFalse)
return(DestroyImageList(image));
if (image->storage_class == PseudoClass)
{
size_t
packet_size;
unsigned char
*dib_colormap;
if (AcquireImageColormap(image,image->colors,exception) == MagickFalse)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
length=(size_t) image->colors;
dib_colormap=(unsigned char *) AcquireQuantumMemory(length,
4*sizeof(*dib_colormap));
if (dib_colormap == (unsigned char *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
packet_size=4;
count=ReadBlob(image,packet_size*image->colors,dib_colormap);
if (count != (ssize_t) (packet_size*image->colors))
{
dib_colormap=(unsigned char *) RelinquishMagickMemory(dib_colormap);
ThrowReaderException(CorruptImageError,"InsufficientImageDataInFile");
}
p=dib_colormap;
for (i=0; i < (ssize_t) image->colors; i++)
{
image->colormap[i].blue=(MagickRealType) ScaleCharToQuantum(*p++);
image->colormap[i].green=(MagickRealType) ScaleCharToQuantum(*p++);
image->colormap[i].red=(MagickRealType) ScaleCharToQuantum(*p++);
if (packet_size == 4)
p++;
}
dib_colormap=(unsigned char *) RelinquishMagickMemory(dib_colormap);
}
if (dib_info.compression == BI_RLE4)
dib_info.bits_per_pixel<<=1;
bytes_per_line=4*((image->columns*dib_info.bits_per_pixel+31)/32);
length=bytes_per_line*image->rows;
pixel_info=AcquireVirtualMemory((size_t) image->rows,MagickMax(
bytes_per_line,image->columns+256UL)*sizeof(*pixels));
if (pixel_info == (MemoryInfo *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
pixels=(unsigned char *) GetVirtualMemoryBlob(pixel_info);
if ((dib_info.compression == BI_RGB) ||
(dib_info.compression == BI_BITFIELDS))
{
count=ReadBlob(image,length,pixels);
if (count != (ssize_t) (length))
{
pixel_info=RelinquishVirtualMemory(pixel_info);
ThrowReaderException(CorruptImageError,"InsufficientImageDataInFile");
}
}
else
{
status=DecodeImage(image,dib_info.compression ? MagickTrue : MagickFalse,
pixels,image->columns*image->rows);
if (status == MagickFalse)
{
pixel_info=RelinquishVirtualMemory(pixel_info);
ThrowReaderException(CorruptImageError,
"UnableToRunlengthDecodeImage");
}
}
image->units=PixelsPerCentimeterResolution;
image->resolution.x=(double) dib_info.x_pixels/100.0;
image->resolution.y=(double) dib_info.y_pixels/100.0;
switch (dib_info.bits_per_pixel)
{
case 1:
{
for (y=(ssize_t) image->rows-1; y >= 0; y--)
{
p=pixels+(image->rows-y-1)*bytes_per_line;
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < ((ssize_t) image->columns-7); x+=8)
{
for (bit=0; bit < 8; bit++)
{
index=(Quantum) ((*p) & (0x80 >> bit) ? 0x01 : 0x00);
SetPixelIndex(image,index,q);
q+=GetPixelChannels(image);
}
p++;
}
if ((image->columns % 8) != 0)
{
for (bit=0; bit < (ssize_t) (image->columns % 8); bit++)
{
index=(Quantum) ((*p) & (0x80 >> bit) ? 0x01 : 0x00);
SetPixelIndex(image,index,q);
q+=GetPixelChannels(image);
}
p++;
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType)
image->rows-y-1,image->rows);
if (status == MagickFalse)
break;
}
}
(void) SyncImage(image,exception);
break;
}
case 4:
{
for (y=(ssize_t) image->rows-1; y >= 0; y--)
{
p=pixels+(image->rows-y-1)*bytes_per_line;
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < ((ssize_t) image->columns-1); x+=2)
{
index=(Quantum) ConstrainColormapIndex(image,(ssize_t) (*p >> 4) &
0xf,exception);
SetPixelIndex(image,index,q);
q+=GetPixelChannels(image);
index=(Quantum) ConstrainColormapIndex(image,(ssize_t) *p & 0xf,
exception);
SetPixelIndex(image,index,q);
p++;
q+=GetPixelChannels(image);
}
if ((image->columns % 2) != 0)
{
index=(Quantum) ConstrainColormapIndex(image,(ssize_t) (*p >> 4) &
0xf,exception);
SetPixelIndex(image,index,q);
q+=GetPixelChannels(image);
p++;
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType)
image->rows-y-1,image->rows);
if (status == MagickFalse)
break;
}
}
(void) SyncImage(image,exception);
break;
}
case 8:
{
if ((dib_info.compression == BI_RLE8) ||
(dib_info.compression == BI_RLE4))
bytes_per_line=image->columns;
for (y=(ssize_t) image->rows-1; y >= 0; y--)
{
p=pixels+(image->rows-y-1)*bytes_per_line;
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < (ssize_t) image->columns; x++)
{
index=(Quantum) ConstrainColormapIndex(image,(ssize_t) *p,exception);
SetPixelIndex(image,index,q);
p++;
q+=GetPixelChannels(image);
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType)
image->rows-y-1,image->rows);
if (status == MagickFalse)
break;
}
}
(void) SyncImage(image,exception);
break;
}
case 16:
{
unsigned short
word;
image->storage_class=DirectClass;
if (dib_info.compression == BI_RLE8)
bytes_per_line=2*image->columns;
for (y=(ssize_t) image->rows-1; y >= 0; y--)
{
p=pixels+(image->rows-y-1)*bytes_per_line;
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < (ssize_t) image->columns; x++)
{
word=(*p++);
word|=(*p++ << 8);
if (dib_info.red_mask == 0)
{
SetPixelRed(image,ScaleCharToQuantum(ScaleColor5to8(
(unsigned char) ((word >> 10) & 0x1f))),q);
SetPixelGreen(image,ScaleCharToQuantum(ScaleColor5to8(
(unsigned char) ((word >> 5) & 0x1f))),q);
SetPixelBlue(image,ScaleCharToQuantum(ScaleColor5to8(
(unsigned char) (word & 0x1f))),q);
}
else
{
SetPixelRed(image,ScaleCharToQuantum(ScaleColor5to8(
(unsigned char) ((word >> 11) & 0x1f))),q);
SetPixelGreen(image,ScaleCharToQuantum(ScaleColor6to8(
(unsigned char) ((word >> 5) & 0x3f))),q);
SetPixelBlue(image,ScaleCharToQuantum(ScaleColor5to8(
(unsigned char) (word & 0x1f))),q);
}
q+=GetPixelChannels(image);
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType)
image->rows-y-1,image->rows);
if (status == MagickFalse)
break;
}
}
break;
}
case 24:
case 32:
{
for (y=(ssize_t) image->rows-1; y >= 0; y--)
{
p=pixels+(image->rows-y-1)*bytes_per_line;
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < (ssize_t) image->columns; x++)
{
SetPixelBlue(image,ScaleCharToQuantum(*p++),q);
SetPixelGreen(image,ScaleCharToQuantum(*p++),q);
SetPixelRed(image,ScaleCharToQuantum(*p++),q);
if (image->alpha_trait != UndefinedPixelTrait)
SetPixelAlpha(image,ScaleCharToQuantum(*p++),q);
q+=GetPixelChannels(image);
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType)
image->rows-y-1,image->rows);
if (status == MagickFalse)
break;
}
}
break;
}
default:
pixel_info=RelinquishVirtualMemory(pixel_info);
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
}
pixel_info=RelinquishVirtualMemory(pixel_info);
if (strcmp(image_info->magick,"ICODIB") == 0)
{
int
c;
image->storage_class=DirectClass;
image->alpha_trait=BlendPixelTrait;
for (y=0; y < (ssize_t) image->rows; y++)
{
register ssize_t
x;
register Quantum
*magick_restrict q;
q=GetAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < ((ssize_t) image->columns-7); x+=8)
{
c=ReadBlobByte(image);
for (bit=0; bit < 8; bit++)
SetPixelAlpha(image,c & (0x80 >> bit) ? TransparentAlpha :
OpaqueAlpha,q+x*GetPixelChannels(image)+bit);
}
if ((image->columns % 8) != 0)
{
c=ReadBlobByte(image);
for (bit=0; bit < (ssize_t) (image->columns % 8); bit++)
SetPixelAlpha(image,c & (0x80 >> bit) ? TransparentAlpha :
OpaqueAlpha,q+x*GetPixelChannels(image)+bit);
}
if (image->columns % 32)
for (x=0; x < (ssize_t) ((32-(image->columns % 32))/8); x++)
c=ReadBlobByte(image);
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
}
}
if (EOFBlob(image) != MagickFalse)
ThrowFileException(exception,CorruptImageError,"UnexpectedEndOfFile",
image->filename);
if (dib_info.height < 0)
{
Image
*flipped_image;
flipped_image=FlipImage(image,exception);
if (flipped_image != (Image *) NULL)
{
DuplicateBlob(flipped_image,image);
image=DestroyImage(image);
image=flipped_image;
}
}
(void) CloseBlob(image);
return(GetFirstImageInList(image));
}

void cff_parseOutline(uint8_t *data, uint32_t len, cff_Index gsubr, cff_Index lsubr,
cff_Stack *stack, void *outline, cff_IOutlineBuilder methods,
const otfcc_Options *options) {
uint16_t gsubr_bias = compute_subr_bias(gsubr.count);
uint16_t lsubr_bias = compute_subr_bias(lsubr.count);
uint8_t *start = data;
uint32_t advance, i, cnt_bezier;
cff_Value val;
void (*setWidth)(void *context, double width) = methods.setWidth;
void (*newContour)(void *context) = methods.newContour;
void (*lineTo)(void *context, double x1, double y1) = methods.lineTo;
void (*curveTo)(void *context, double x1, double y1, double x2, double y2, double x3,
double y3) = methods.curveTo;
void (*setHint)(void *context, bool isVertical, double position, double width) =
methods.setHint;
void (*setMask)(void *context, bool isContourMask, bool *mask) = methods.setMask;
double (*getrand)(void *context) = methods.getrand;
if (!setWidth) setWidth = callback_nopSetWidth;
if (!newContour) newContour = callback_nopNewContour;
if (!lineTo) lineTo = callback_nopLineTo;
if (!curveTo) curveTo = callback_nopCurveTo;
if (!setHint) setHint = callback_nopsetHint;
if (!setMask) setMask = callback_nopsetMask;
if (!getrand) getrand = callback_nopgetrand;
while (start < data + len) {
advance = cff_decodeCS2Token(start, &val);
switch (val.t) {
case CS2_OPERATOR:
switch (val.i) {
case op_hstem:
case op_vstem:
case op_hstemhm:
case op_vstemhm:
if (stack->index % 2) setWidth(outline, stack->stack[0].d);
stack->stem += stack->index >> 1;
double hintBase = 0;
for (uint16_t j = stack->index % 2; j < stack->index; j += 2) {
double pos = stack->stack[j].d;
double width = stack->stack[j + 1].d;
setHint(outline, (val.i == op_vstem || val.i == op_vstemhm),
pos + hintBase, width);
hintBase += pos + width;
}
stack->index = 0;
break;
case op_hintmask:
case op_cntrmask: {
if (stack->index % 2) setWidth(outline, stack->stack[0].d);
bool isVertical = stack->stem > 0;
stack->stem += stack->index >> 1;
double hintBase = 0;
for (uint16_t j = stack->index % 2; j < stack->index; j += 2) {
double pos = stack->stack[j].d;
double width = stack->stack[j + 1].d;
setHint(outline, isVertical, pos + hintBase, width);
hintBase += pos + width;
}
uint32_t maskLength = (stack->stem + 7) >> 3;
bool *mask;
NEW(mask, stack->stem + 7);
for (uint32_t byte = 0; byte < maskLength; byte++) {
uint8_t maskByte = start[advance + byte];
mask[(byte << 3) + 0] = maskByte >> 7 & 1;
mask[(byte << 3) + 1] = maskByte >> 6 & 1;
mask[(byte << 3) + 2] = maskByte >> 5 & 1;
mask[(byte << 3) + 3] = maskByte >> 4 & 1;
mask[(byte << 3) + 4] = maskByte >> 3 & 1;
mask[(byte << 3) + 5] = maskByte >> 2 & 1;
mask[(byte << 3) + 6] = maskByte >> 1 & 1;
mask[(byte << 3) + 7] = maskByte >> 0 & 1;
}
setMask(outline, (val.i == op_cntrmask), mask);
advance += maskLength;
stack->index = 0;
break;
}
case op_vmoveto: {
CHECK_STACK_TOP(op_vmoveto, 1);
if (stack->index > 1) setWidth(outline, stack->stack[stack->index - 2].d);
newContour(outline);
lineTo(outline, 0.0, stack->stack[stack->index - 1].d);
stack->index = 0;
break;
}
case op_rmoveto: {
CHECK_STACK_TOP(op_rmoveto, 2);
if (stack->index > 2) setWidth(outline, stack->stack[stack->index - 3].d);
newContour(outline);
lineTo(outline, stack->stack[stack->index - 2].d,
stack->stack[stack->index - 1].d);
stack->index = 0;
break;
}
case op_hmoveto: {
CHECK_STACK_TOP(op_hmoveto, 1);
if (stack->index > 1) setWidth(outline, stack->stack[stack->index - 2].d);
newContour(outline);
lineTo(outline, stack->stack[stack->index - 1].d, 0.0);
stack->index = 0;
break;
}
case op_endchar: {
if (stack->index > 0) setWidth(outline, stack->stack[stack->index - 1].d);
break;
}
case op_rlineto: {
for (i = 0; i < stack->index; i += 2)
lineTo(outline, stack->stack[i].d, stack->stack[i + 1].d);
stack->index = 0;
break;
}
case op_vlineto: {
if (stack->index % 2 == 1) {
lineTo(outline, 0.0, stack->stack[0].d);
for (i = 1; i < stack->index; i += 2) {
lineTo(outline, stack->stack[i].d, 0.0);
lineTo(outline, 0.0, stack->stack[i + 1].d);
}
} else {
for (i = 0; i < stack->index; i += 2) {
lineTo(outline, 0.0, stack->stack[i].d);
lineTo(outline, stack->stack[i + 1].d, 0.0);
}
}
stack->index = 0;
break;
}
case op_hlineto: {
if (stack->index % 2 == 1) {
lineTo(outline, stack->stack[0].d, 0.0);
for (i = 1; i < stack->index; i += 2) {
lineTo(outline, 0.0, stack->stack[i].d);
lineTo(outline, stack->stack[i + 1].d, 0.0);
}
} else {
for (i = 0; i < stack->index; i += 2) {
lineTo(outline, stack->stack[i].d, 0.0);
lineTo(outline, 0.0, stack->stack[i + 1].d);
}
}
stack->index = 0;
break;
}
case op_rrcurveto: {
for (i = 0; i < stack->index; i += 6)
curveTo(outline, stack->stack[i].d, stack->stack[i + 1].d,
stack->stack[i + 2].d, stack->stack[i + 3].d,
stack->stack[i + 4].d, stack->stack[i + 5].d);
stack->index = 0;
break;
}
case op_rcurveline: {
for (i = 0; i < stack->index - 2; i += 6)
curveTo(outline, stack->stack[i].d, stack->stack[i + 1].d,
stack->stack[i + 2].d, stack->stack[i + 3].d,
stack->stack[i + 4].d, stack->stack[i + 5].d);
lineTo(outline, stack->stack[stack->index - 2].d,
stack->stack[stack->index - 1].d);
stack->index = 0;
break;
}
case op_rlinecurve: {
for (i = 0; i < stack->index - 6; i += 2)
lineTo(outline, stack->stack[i].d, stack->stack[i + 1].d);
curveTo(outline, stack->stack[stack->index - 6].d,
stack->stack[stack->index - 5].d, stack->stack[stack->index - 4].d,
stack->stack[stack->index - 3].d, stack->stack[stack->index - 2].d,
stack->stack[stack->index - 1].d);
stack->index = 0;
break;
}
case op_vvcurveto: {
if (stack->index % 4 == 1) {
curveTo(outline, stack->stack[0].d, stack->stack[1].d,
stack->stack[2].d, stack->stack[3].d, 0.0, stack->stack[4].d);
for (i = 5; i < stack->index; i += 4)
curveTo(outline, 0.0, stack->stack[i].d, stack->stack[i + 1].d,
stack->stack[i + 2].d, 0.0, stack->stack[i + 3].d);
} else {
for (i = 0; i < stack->index; i += 4)
curveTo(outline, 0.0, stack->stack[i].d, stack->stack[i + 1].d,
stack->stack[i + 2].d, 0.0, stack->stack[i + 3].d);
}
stack->index = 0;
break;
}
case op_hhcurveto: {
if (stack->index % 4 == 1) {
curveTo(outline, stack->stack[1].d, stack->stack[0].d,
stack->stack[2].d, stack->stack[3].d, stack->stack[4].d, 0.0);
for (i = 5; i < stack->index; i += 4)
curveTo(outline, stack->stack[i].d, 0.0, stack->stack[i + 1].d,
stack->stack[i + 2].d, stack->stack[i + 3].d, 0.0);
} else {
for (i = 0; i < stack->index; i += 4)
curveTo(outline, stack->stack[i].d, 0.0, stack->stack[i + 1].d,
stack->stack[i + 2].d, stack->stack[i + 3].d, 0.0);
}
stack->index = 0;
break;
}
case op_vhcurveto: {
if (stack->index % 4 == 1)
cnt_bezier = (stack->index - 5) / 4;
else
cnt_bezier = (stack->index / 4);
for (i = 0; i < 4 * cnt_bezier; i += 4) {
if ((i / 4) % 2 == 0)
curveTo(outline, 0.0, stack->stack[i].d, stack->stack[i + 1].d,
stack->stack[i + 2].d, stack->stack[i + 3].d, 0.0);
else
curveTo(outline, stack->stack[i].d, 0.0, stack->stack[i + 1].d,
stack->stack[i + 2].d, 0.0, stack->stack[i + 3].d);
}
if (stack->index % 8 == 5) {
curveTo(
outline, 0.0, stack->stack[stack->index - 5].d,
stack->stack[stack->index - 4].d, stack->stack[stack->index - 3].d,
stack->stack[stack->index - 2].d, stack->stack[stack->index - 1].d);
}
if (stack->index % 8 == 1) {
curveTo(
outline, stack->stack[stack->index - 5].d, 0.0,
stack->stack[stack->index - 4].d, stack->stack[stack->index - 3].d,
stack->stack[stack->index - 1].d, stack->stack[stack->index - 2].d);
}
stack->index = 0;
break;
}
case op_hvcurveto: {
if (stack->index % 4 == 1)
cnt_bezier = (stack->index - 5) / 4;
else
cnt_bezier = (stack->index / 4);
for (i = 0; i < 4 * cnt_bezier; i += 4) {
if ((i / 4) % 2 == 0)
curveTo(outline, stack->stack[i].d, 0.0, stack->stack[i + 1].d,
stack->stack[i + 2].d, 0.0, stack->stack[i + 3].d);
else
curveTo(outline, 0.0, stack->stack[i].d, stack->stack[i + 1].d,
stack->stack[i + 2].d, stack->stack[i + 3].d, 0.0);
}
if (stack->index % 8 == 5) {
curveTo(
outline, stack->stack[stack->index - 5].d, 0.0,
stack->stack[stack->index - 4].d, stack->stack[stack->index - 3].d,
stack->stack[stack->index - 1].d, stack->stack[stack->index - 2].d);
}
if (stack->index % 8 == 1) {
curveTo(
outline, 0.0, stack->stack[stack->index - 5].d,
stack->stack[stack->index - 4].d, stack->stack[stack->index - 3].d,
stack->stack[stack->index - 2].d, stack->stack[stack->index - 1].d);
}
stack->index = 0;
break;
}
case op_hflex: {
CHECK_STACK_TOP(op_hflex, 7);
curveTo(outline, stack->stack[0].d, 0.0, stack->stack[1].d,
stack->stack[2].d, stack->stack[3].d, 0.0);
curveTo(outline, stack->stack[4].d, 0.0, stack->stack[5].d,
-stack->stack[2].d, stack->stack[6].d, 0.0);
stack->index = 0;
break;
}
case op_flex: {
CHECK_STACK_TOP(op_flex, 12);
curveTo(outline, stack->stack[0].d, stack->stack[1].d, stack->stack[2].d,
stack->stack[3].d, stack->stack[4].d, stack->stack[5].d);
curveTo(outline, stack->stack[6].d, stack->stack[7].d, stack->stack[8].d,
stack->stack[9].d, stack->stack[10].d, stack->stack[11].d);
stack->index = 0;
break;
}
case op_hflex1: {
CHECK_STACK_TOP(op_hflex1, 9);
curveTo(outline, stack->stack[0].d, stack->stack[1].d, stack->stack[2].d,
stack->stack[3].d, stack->stack[4].d, 0.0);
curveTo(outline, stack->stack[5].d, 0.0, stack->stack[6].d,
stack->stack[7].d, stack->stack[8].d,
-(stack->stack[1].d + stack->stack[3].d + stack->stack[7].d));
stack->index = 0;
break;
}
case op_flex1: {
CHECK_STACK_TOP(op_flex1, 11);
double dx = stack->stack[0].d + stack->stack[2].d + stack->stack[4].d +
stack->stack[6].d + stack->stack[8].d;
double dy = stack->stack[1].d + stack->stack[3].d + stack->stack[5].d +
stack->stack[7].d + stack->stack[9].d;
if (fabs(dx) > fabs(dy)) {
dx = stack->stack[10].d;
dy = -dy;
} else {
dx = -dx;
dy = stack->stack[10].d;
}
curveTo(outline, stack->stack[0].d, stack->stack[1].d, stack->stack[2].d,
stack->stack[3].d, stack->stack[4].d, stack->stack[5].d);
curveTo(outline, stack->stack[6].d, stack->stack[7].d, stack->stack[8].d,
stack->stack[9].d, dx, dy);
stack->index = 0;
break;
}
case op_and: {
CHECK_STACK_TOP(op_and, 2);
double num1 = stack->stack[stack->index - 1].d;
double num2 = stack->stack[stack->index - 2].d;
stack->stack[stack->index - 2].d = (num1 && num2) ? 1.0 : 0.0;
stack->index -= 1;
break;
}
case op_or: {
CHECK_STACK_TOP(op_or, 2);
double num1 = stack->stack[stack->index - 1].d;
double num2 = stack->stack[stack->index - 2].d;
stack->stack[stack->index - 2].d = (num1 || num2) ? 1.0 : 0.0;
stack->index -= 1;
break;
}
case op_not: {
CHECK_STACK_TOP(op_not, 1);
double num = stack->stack[stack->index - 1].d;
stack->stack[stack->index - 1].d = num ? 0.0 : 1.0;
break;
}
case op_abs: {
CHECK_STACK_TOP(op_abs, 1);
double num = stack->stack[stack->index - 1].d;
stack->stack[stack->index - 1].d = (num < 0.0) ? -num : num;
break;
}
case op_add: {
CHECK_STACK_TOP(op_add, 2);
double num1 = stack->stack[stack->index - 1].d;
double num2 = stack->stack[stack->index - 2].d;
stack->stack[stack->index - 2].d = num1 + num2;
stack->index -= 1;
break;
}
case op_sub: {
CHECK_STACK_TOP(op_sub, 2);
double num1 = stack->stack[stack->index - 2].d;
double num2 = stack->stack[stack->index - 1].d;
stack->stack[stack->index - 2].d = num1 - num2;
stack->index -= 1;
break;
}
case op_div: {
CHECK_STACK_TOP(op_div, 2);
double num1 = stack->stack[stack->index - 2].d;
double num2 = stack->stack[stack->index - 1].d;
stack->stack[stack->index - 2].d = num1 / num2;
stack->index -= 1;
break;
}
case op_neg: {
CHECK_STACK_TOP(op_neg, 1);
double num = stack->stack[stack->index - 1].d;
stack->stack[stack->index - 1].d = -num;
break;
}
case op_eq: {
CHECK_STACK_TOP(op_eq, 2);
double num1 = stack->stack[stack->index - 1].d;
double num2 = stack->stack[stack->index - 2].d;
stack->stack[stack->index - 2].d = (num1 == num2) ? 1.0 : 0.0;
stack->index -= 1;
break;
}
case op_drop: {
CHECK_STACK_TOP(op_drop, 1);
stack->index -= 1;
break;
}
case op_put: {
CHECK_STACK_TOP(op_put, 2);
double val = stack->stack[stack->index - 2].d;
int32_t i = (int32_t)stack->stack[stack->index - 1].d;
stack->transient[i % type2_transient_array].d = val;
stack->index -= 2;
break;
}
case op_get: {
CHECK_STACK_TOP(op_get, 1);
int32_t i = (int32_t)stack->stack[stack->index - 1].d;
stack->stack[stack->index - 1].d =
stack->transient[i % type2_transient_array].d;
break;
}
case op_ifelse: {
CHECK_STACK_TOP(op_ifelse, 4);
double v2 = stack->stack[stack->index - 1].d;
double v1 = stack->stack[stack->index - 2].d;
double s2 = stack->stack[stack->index - 3].d;
double s1 = stack->stack[stack->index - 4].d;
stack->stack[stack->index - 4].d = (v1 <= v2) ? s1 : s2;
stack->index -= 3;
break;
}
case op_random: {
stack->stack[stack->index].t = cff_DOUBLE;
stack->stack[stack->index].d = getrand(outline);
stack->index += 1;
break;
}
case op_mul: {
CHECK_STACK_TOP(op_mul, 2);
double num1 = stack->stack[stack->index - 1].d;
double num2 = stack->stack[stack->index - 2].d;
stack->stack[stack->index - 2].d = num1 * num2;
stack->index -= 1;
break;
}
case op_sqrt: {
CHECK_STACK_TOP(op_sqrt, 1);
double num = stack->stack[stack->index - 1].d;
stack->stack[stack->index - 1].d = sqrt(num);
break;
}
case op_dup: {
CHECK_STACK_TOP(op_dup, 1);
stack->stack[stack->index] = stack->stack[stack->index - 1];
stack->index += 1;
break;
}
case op_exch: {
CHECK_STACK_TOP(op_exch, 2);
double num1 = stack->stack[stack->index - 1].d;
double num2 = stack->stack[stack->index - 2].d;
stack->stack[stack->index - 1].d = num2;
stack->stack[stack->index - 2].d = num1;
break;
}
case op_index: {
CHECK_STACK_TOP(op_index, 2);
uint8_t n = stack->index - 1;
uint8_t j = n - 1 - (uint8_t)(stack->stack[n].d) % n;
stack->stack[n] = stack->stack[j];
break;
}
case op_roll: {
CHECK_STACK_TOP(op_roll, 2);
int32_t j = stack->stack[stack->index - 1].d;
uint32_t n = stack->stack[stack->index - 2].d;
CHECK_STACK_TOP(op_roll, 2 + n);
j = -j % n;
if (j < 0) j += n;
if (!j) break;
uint8_t last = stack->index - 3;
uint8_t first = stack->index - 2 - n;
reverseStack(stack, first, last);
reverseStack(stack, last - j + 1, last);
reverseStack(stack, first, last - j);
stack->index -= 2;
break;
}
case op_return:
return;
case op_callsubr: {
CHECK_STACK_TOP(op_callsubr, 1);
uint32_t subr = (uint32_t)stack->stack[--(stack->index)].d;
cff_parseOutline(lsubr.data + lsubr.offset[lsubr_bias + subr] - 1,
lsubr.offset[lsubr_bias + subr + 1] -
lsubr.offset[lsubr_bias + subr],
gsubr, lsubr, stack, outline, methods, options);
break;
}
case op_callgsubr: {
CHECK_STACK_TOP(op_callgsubr, 1);
uint32_t subr = (uint32_t)stack->stack[--(stack->index)].d;
cff_parseOutline(gsubr.data + gsubr.offset[gsubr_bias + subr] - 1,
gsubr.offset[gsubr_bias + subr + 1] -
gsubr.offset[gsubr_bias + subr],
gsubr, lsubr, stack, outline, methods, options);
break;
}
}
break;
case CS2_OPERAND:
case CS2_FRACTION:
stack->stack[(stack->index)++] = val;
break;
}
start += advance;
}
}

static int http_read_stream(URLContext *h, uint8_t *buf, int size)
{
HTTPContext *s = h->priv_data;
int err, new_location, read_ret;
int64_t seek_ret;
if (!s->hd)
return AVERROR_EOF;
if (s->end_chunked_post && !s->end_header) {
err = http_read_header(h, &new_location);
if (err < 0)
return err;
}
if (s->chunksize >= 0) {
if (!s->chunksize) {
char line[32];
do {
if ((err = http_get_line(s, line, sizeof(line))) < 0)
return err;
} while (!*line);    
s->chunksize = strtoll(line, NULL, 16);
av_log(NULL, AV_LOG_TRACE, "Chunked encoding data size: %"PRId64"'\n",
s->chunksize);
if (!s->chunksize)
return 0;
}
size = FFMIN(size, s->chunksize);
}
#if CONFIG_ZLIB
if (s->compressed)
return http_buf_read_compressed(h, buf, size);
#endif 
read_ret = http_buf_read(h, buf, size);
if (   (read_ret  < 0 && s->reconnect        && (!h->is_streamed || s->reconnect_streamed) && s->filesize > 0 && s->off < s->filesize)
|| (read_ret == 0 && s->reconnect_at_eof && (!h->is_streamed || s->reconnect_streamed))) {
int64_t target = h->is_streamed ? 0 : s->off;
if (s->reconnect_delay > s->reconnect_delay_max)
return AVERROR(EIO);
av_log(h, AV_LOG_INFO, "Will reconnect at %"PRId64" error=%s.\n", s->off, av_err2str(read_ret));
av_usleep(1000U*1000*s->reconnect_delay);
s->reconnect_delay = 1 + 2*s->reconnect_delay;
seek_ret = http_seek_internal(h, target, SEEK_SET, 1);
if (seek_ret != target) {
av_log(h, AV_LOG_ERROR, "Failed to reconnect at %"PRId64".\n", target);
return read_ret;
}
read_ret = http_buf_read(h, buf, size);
} else
s->reconnect_delay = 0;
return read_ret;
}

static Image *ReadVIFFImage(const ImageInfo *image_info,
ExceptionInfo *exception)
{
#define VFF_CM_genericRGB  15
#define VFF_CM_ntscRGB  1
#define VFF_CM_NONE  0
#define VFF_DEP_DECORDER  0x4
#define VFF_DEP_NSORDER  0x8
#define VFF_DES_RAW  0
#define VFF_LOC_IMPLICIT  1
#define VFF_MAPTYP_NONE  0
#define VFF_MAPTYP_1_BYTE  1
#define VFF_MAPTYP_2_BYTE  2
#define VFF_MAPTYP_4_BYTE  4
#define VFF_MAPTYP_FLOAT  5
#define VFF_MAPTYP_DOUBLE  7
#define VFF_MS_NONE  0
#define VFF_MS_ONEPERBAND  1
#define VFF_MS_SHARED  3
#define VFF_TYP_BIT  0
#define VFF_TYP_1_BYTE  1
#define VFF_TYP_2_BYTE  2
#define VFF_TYP_4_BYTE  4
#define VFF_TYP_FLOAT  5
#define VFF_TYP_DOUBLE  9
typedef struct _ViffInfo
{
unsigned char
identifier,
file_type,
release,
version,
machine_dependency,
reserve[3];
char
comment[512];
unsigned int
rows,
columns,
subrows;
int
x_offset,
y_offset;
float
x_bits_per_pixel,
y_bits_per_pixel;
unsigned int
location_type,
location_dimension,
number_of_images,
number_data_bands,
data_storage_type,
data_encode_scheme,
map_scheme,
map_storage_type,
map_rows,
map_columns,
map_subrows,
map_enable,
maps_per_cycle,
color_space_model;
} ViffInfo;
double
min_value,
scale_factor,
value;
Image
*image;
int
bit;
MagickBooleanType
status;
MagickSizeType
number_pixels;
register ssize_t
x;
register Quantum
*q;
register ssize_t
i;
register unsigned char
*p;
size_t
bytes_per_pixel,
max_packets,
quantum;
ssize_t
count,
y;
unsigned char
*pixels;
unsigned long
lsb_first;
ViffInfo
viff_info;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickCoreSignature);
if (image_info->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
image_info->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
image=AcquireImage(image_info,exception);
status=OpenBlob(image_info,image,ReadBinaryBlobMode,exception);
if (status == MagickFalse)
{
image=DestroyImageList(image);
return((Image *) NULL);
}
count=ReadBlob(image,1,&viff_info.identifier);
do
{
if ((count != 1) || ((unsigned char) viff_info.identifier != 0xab))
ThrowReaderException(CorruptImageError,"NotAVIFFImage");
(void) ReadBlob(image,sizeof(viff_info.file_type),&viff_info.file_type);
(void) ReadBlob(image,sizeof(viff_info.release),&viff_info.release);
(void) ReadBlob(image,sizeof(viff_info.version),&viff_info.version);
(void) ReadBlob(image,sizeof(viff_info.machine_dependency),
&viff_info.machine_dependency);
(void) ReadBlob(image,sizeof(viff_info.reserve),viff_info.reserve);
count=ReadBlob(image,512,(unsigned char *) viff_info.comment);
viff_info.comment[511]='\0';
if (strlen(viff_info.comment) > 4)
(void) SetImageProperty(image,"comment",viff_info.comment,exception);
if ((viff_info.machine_dependency == VFF_DEP_DECORDER) ||
(viff_info.machine_dependency == VFF_DEP_NSORDER))
image->endian=LSBEndian;
else
image->endian=MSBEndian;
viff_info.rows=ReadBlobLong(image);
viff_info.columns=ReadBlobLong(image);
viff_info.subrows=ReadBlobLong(image);
viff_info.x_offset=(int) ReadBlobLong(image);
viff_info.y_offset=(int) ReadBlobLong(image);
viff_info.x_bits_per_pixel=(float) ReadBlobLong(image);
viff_info.y_bits_per_pixel=(float) ReadBlobLong(image);
viff_info.location_type=ReadBlobLong(image);
viff_info.location_dimension=ReadBlobLong(image);
viff_info.number_of_images=ReadBlobLong(image);
viff_info.number_data_bands=ReadBlobLong(image);
viff_info.data_storage_type=ReadBlobLong(image);
viff_info.data_encode_scheme=ReadBlobLong(image);
viff_info.map_scheme=ReadBlobLong(image);
viff_info.map_storage_type=ReadBlobLong(image);
viff_info.map_rows=ReadBlobLong(image);
viff_info.map_columns=ReadBlobLong(image);
viff_info.map_subrows=ReadBlobLong(image);
viff_info.map_enable=ReadBlobLong(image);
viff_info.maps_per_cycle=ReadBlobLong(image);
viff_info.color_space_model=ReadBlobLong(image);
for (i=0; i < 420; i++)
(void) ReadBlobByte(image);
if (EOFBlob(image) != MagickFalse)
ThrowReaderException(CorruptImageError,"UnexpectedEndOfFile");
image->columns=viff_info.rows;
image->rows=viff_info.columns;
image->depth=viff_info.x_bits_per_pixel <= 8 ? 8UL :
MAGICKCORE_QUANTUM_DEPTH;
number_pixels=(MagickSizeType) viff_info.columns*viff_info.rows;
if (number_pixels != (size_t) number_pixels)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
if (number_pixels == 0)
ThrowReaderException(CoderError,"ImageColumnOrRowSizeIsNotSupported");
if ((viff_info.number_data_bands < 1) || (viff_info.number_data_bands > 4))
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
if ((viff_info.data_storage_type != VFF_TYP_BIT) &&
(viff_info.data_storage_type != VFF_TYP_1_BYTE) &&
(viff_info.data_storage_type != VFF_TYP_2_BYTE) &&
(viff_info.data_storage_type != VFF_TYP_4_BYTE) &&
(viff_info.data_storage_type != VFF_TYP_FLOAT) &&
(viff_info.data_storage_type != VFF_TYP_DOUBLE))
ThrowReaderException(CoderError,"DataStorageTypeIsNotSupported");
if (viff_info.data_encode_scheme != VFF_DES_RAW)
ThrowReaderException(CoderError,"DataEncodingSchemeIsNotSupported");
if ((viff_info.map_storage_type != VFF_MAPTYP_NONE) &&
(viff_info.map_storage_type != VFF_MAPTYP_1_BYTE) &&
(viff_info.map_storage_type != VFF_MAPTYP_2_BYTE) &&
(viff_info.map_storage_type != VFF_MAPTYP_4_BYTE) &&
(viff_info.map_storage_type != VFF_MAPTYP_FLOAT) &&
(viff_info.map_storage_type != VFF_MAPTYP_DOUBLE))
ThrowReaderException(CoderError,"MapStorageTypeIsNotSupported");
if ((viff_info.color_space_model != VFF_CM_NONE) &&
(viff_info.color_space_model != VFF_CM_ntscRGB) &&
(viff_info.color_space_model != VFF_CM_genericRGB))
ThrowReaderException(CoderError,"ColorspaceModelIsNotSupported");
if (viff_info.location_type != VFF_LOC_IMPLICIT)
ThrowReaderException(CoderError,"LocationTypeIsNotSupported");
if (viff_info.number_of_images != 1)
ThrowReaderException(CoderError,"NumberOfImagesIsNotSupported");
if (viff_info.map_rows == 0)
viff_info.map_scheme=VFF_MS_NONE;
switch ((int) viff_info.map_scheme)
{
case VFF_MS_NONE:
{
if (viff_info.number_data_bands < 3)
{
if (viff_info.data_storage_type == VFF_TYP_BIT)
image->colors=2;
else
if (viff_info.data_storage_type == VFF_MAPTYP_1_BYTE)
image->colors=256UL;
else
image->colors=image->depth <= 8 ? 256UL : 65536UL;
status=AcquireImageColormap(image,image->colors,exception);
if (status == MagickFalse)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
}
break;
}
case VFF_MS_ONEPERBAND:
case VFF_MS_SHARED:
{
unsigned char
*viff_colormap;
switch ((int) viff_info.map_storage_type)
{
case VFF_MAPTYP_1_BYTE: bytes_per_pixel=1; break;
case VFF_MAPTYP_2_BYTE: bytes_per_pixel=2; break;
case VFF_MAPTYP_4_BYTE: bytes_per_pixel=4; break;
case VFF_MAPTYP_FLOAT: bytes_per_pixel=4; break;
case VFF_MAPTYP_DOUBLE: bytes_per_pixel=8; break;
default: bytes_per_pixel=1; break;
}
image->colors=viff_info.map_columns;
if (AcquireImageColormap(image,image->colors,exception) == MagickFalse)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
if (viff_info.map_rows >
(viff_info.map_rows*bytes_per_pixel*sizeof(*viff_colormap)))
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
viff_colormap=(unsigned char *) AcquireQuantumMemory(image->colors,
viff_info.map_rows*bytes_per_pixel*sizeof(*viff_colormap));
if (viff_colormap == (unsigned char *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
count=ReadBlob(image,bytes_per_pixel*image->colors*viff_info.map_rows,
viff_colormap);
lsb_first=1;
if (*(char *) &lsb_first &&
((viff_info.machine_dependency != VFF_DEP_DECORDER) &&
(viff_info.machine_dependency != VFF_DEP_NSORDER)))
switch ((int) viff_info.map_storage_type)
{
case VFF_MAPTYP_2_BYTE:
{
MSBOrderShort(viff_colormap,(bytes_per_pixel*image->colors*
viff_info.map_rows));
break;
}
case VFF_MAPTYP_4_BYTE:
case VFF_MAPTYP_FLOAT:
{
MSBOrderLong(viff_colormap,(bytes_per_pixel*image->colors*
viff_info.map_rows));
break;
}
default: break;
}
for (i=0; i < (ssize_t) (viff_info.map_rows*image->colors); i++)
{
switch ((int) viff_info.map_storage_type)
{
case VFF_MAPTYP_2_BYTE: value=1.0*((short *) viff_colormap)[i]; break;
case VFF_MAPTYP_4_BYTE: value=1.0*((int *) viff_colormap)[i]; break;
case VFF_MAPTYP_FLOAT: value=((float *) viff_colormap)[i]; break;
case VFF_MAPTYP_DOUBLE: value=((double *) viff_colormap)[i]; break;
default: value=1.0*viff_colormap[i]; break;
}
if (i < (ssize_t) image->colors)
{
image->colormap[i].red=ScaleCharToQuantum((unsigned char) value);
image->colormap[i].green=
ScaleCharToQuantum((unsigned char) value);
image->colormap[i].blue=ScaleCharToQuantum((unsigned char) value);
}
else
if (i < (ssize_t) (2*image->colors))
image->colormap[i % image->colors].green=
ScaleCharToQuantum((unsigned char) value);
else
if (i < (ssize_t) (3*image->colors))
image->colormap[i % image->colors].blue=
ScaleCharToQuantum((unsigned char) value);
}
viff_colormap=(unsigned char *) RelinquishMagickMemory(viff_colormap);
break;
}
default:
ThrowReaderException(CoderError,"ColormapTypeNotSupported");
}
image->alpha_trait=viff_info.number_data_bands == 4 ? BlendPixelTrait : 
UndefinedPixelTrait;
image->storage_class=(viff_info.number_data_bands < 3 ? PseudoClass :
DirectClass);
image->columns=viff_info.rows;
image->rows=viff_info.columns;
if ((image_info->ping != MagickFalse) && (image_info->number_scenes != 0))
if (image->scene >= (image_info->scene+image_info->number_scenes-1))
break;
status=SetImageExtent(image,image->columns,image->rows,exception);
if (status == MagickFalse)
return(DestroyImageList(image));
switch ((int) viff_info.data_storage_type)
{
case VFF_TYP_2_BYTE: bytes_per_pixel=2; break;
case VFF_TYP_4_BYTE: bytes_per_pixel=4; break;
case VFF_TYP_FLOAT: bytes_per_pixel=4; break;
case VFF_TYP_DOUBLE: bytes_per_pixel=8; break;
default: bytes_per_pixel=1; break;
}
if (viff_info.data_storage_type == VFF_TYP_BIT)
max_packets=((image->columns+7UL) >> 3UL)*image->rows;
else
max_packets=(size_t) (number_pixels*viff_info.number_data_bands);
pixels=(unsigned char *) AcquireQuantumMemory(MagickMax(number_pixels,
max_packets),bytes_per_pixel*sizeof(*pixels));
if (pixels == (unsigned char *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
count=ReadBlob(image,bytes_per_pixel*max_packets,pixels);
lsb_first=1;
if (*(char *) &lsb_first &&
((viff_info.machine_dependency != VFF_DEP_DECORDER) &&
(viff_info.machine_dependency != VFF_DEP_NSORDER)))
switch ((int) viff_info.data_storage_type)
{
case VFF_TYP_2_BYTE:
{
MSBOrderShort(pixels,bytes_per_pixel*max_packets);
break;
}
case VFF_TYP_4_BYTE:
case VFF_TYP_FLOAT:
{
MSBOrderLong(pixels,bytes_per_pixel*max_packets);
break;
}
default: break;
}
min_value=0.0;
scale_factor=1.0;
if ((viff_info.data_storage_type != VFF_TYP_1_BYTE) &&
(viff_info.map_scheme == VFF_MS_NONE))
{
double
max_value;
switch ((int) viff_info.data_storage_type)
{
case VFF_TYP_2_BYTE: value=1.0*((short *) pixels)[0]; break;
case VFF_TYP_4_BYTE: value=1.0*((int *) pixels)[0]; break;
case VFF_TYP_FLOAT: value=((float *) pixels)[0]; break;
case VFF_TYP_DOUBLE: value=((double *) pixels)[0]; break;
default: value=1.0*pixels[0]; break;
}
max_value=value;
min_value=value;
for (i=0; i < (ssize_t) max_packets; i++)
{
switch ((int) viff_info.data_storage_type)
{
case VFF_TYP_2_BYTE: value=1.0*((short *) pixels)[i]; break;
case VFF_TYP_4_BYTE: value=1.0*((int *) pixels)[i]; break;
case VFF_TYP_FLOAT: value=((float *) pixels)[i]; break;
case VFF_TYP_DOUBLE: value=((double *) pixels)[i]; break;
default: value=1.0*pixels[i]; break;
}
if (value > max_value)
max_value=value;
else
if (value < min_value)
min_value=value;
}
if ((min_value == 0) && (max_value == 0))
scale_factor=0;
else
if (min_value == max_value)
{
scale_factor=(double) QuantumRange/min_value;
min_value=0;
}
else
scale_factor=(double) QuantumRange/(max_value-min_value);
}
p=(unsigned char *) pixels;
for (i=0; i < (ssize_t) max_packets; i++)
{
switch ((int) viff_info.data_storage_type)
{
case VFF_TYP_2_BYTE: value=1.0*((short *) pixels)[i]; break;
case VFF_TYP_4_BYTE: value=1.0*((int *) pixels)[i]; break;
case VFF_TYP_FLOAT: value=((float *) pixels)[i]; break;
case VFF_TYP_DOUBLE: value=((double *) pixels)[i]; break;
default: value=1.0*pixels[i]; break;
}
if (viff_info.map_scheme == VFF_MS_NONE)
{
value=(value-min_value)*scale_factor;
if (value > QuantumRange)
value=QuantumRange;
else
if (value < 0)
value=0;
}
*p=(unsigned char) ((Quantum) value);
p++;
}
p=(unsigned char *) pixels;
if (viff_info.data_storage_type == VFF_TYP_BIT)
{
for (y=0; y < (ssize_t) image->rows; y++)
{
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < (ssize_t) (image->columns-7); x+=8)
{
for (bit=0; bit < 8; bit++)
{
quantum=(size_t) ((*p) & (0x01 << bit) ? 0 : 1);
SetPixelRed(image,quantum == 0 ? 0 : QuantumRange,q);
SetPixelGreen(image,quantum == 0 ? 0 : QuantumRange,q);
SetPixelBlue(image,quantum == 0 ? 0 : QuantumRange,q);
if (image->storage_class == PseudoClass)
SetPixelIndex(image,(Quantum) quantum,q);
q+=GetPixelChannels(image);
}
p++;
}
if ((image->columns % 8) != 0)
{
for (bit=0; bit < (int) (image->columns % 8); bit++)
{
quantum=(size_t) ((*p) & (0x01 << bit) ? 0 : 1);
SetPixelRed(image,quantum == 0 ? 0 : QuantumRange,q);
SetPixelGreen(image,quantum == 0 ? 0 : QuantumRange,q);
SetPixelBlue(image,quantum == 0 ? 0 : QuantumRange,q);
if (image->storage_class == PseudoClass)
SetPixelIndex(image,(Quantum) quantum,q);
q+=GetPixelChannels(image);
}
p++;
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
}
else
if (image->storage_class == PseudoClass)
for (y=0; y < (ssize_t) image->rows; y++)
{
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < (ssize_t) image->columns; x++)
{
SetPixelIndex(image,*p++,q);
q+=GetPixelChannels(image);
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
else
{
number_pixels=(MagickSizeType) image->columns*image->rows;
for (y=0; y < (ssize_t) image->rows; y++)
{
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < (ssize_t) image->columns; x++)
{
SetPixelRed(image,ScaleCharToQuantum(*p),q);
SetPixelGreen(image,ScaleCharToQuantum(*(p+number_pixels)),q);
SetPixelBlue(image,ScaleCharToQuantum(*(p+2*number_pixels)),q);
if (image->colors != 0)
{
ssize_t
index;
index=(ssize_t) GetPixelRed(image,q);
SetPixelRed(image,image->colormap[
ConstrainColormapIndex(image,index,exception)].red,q);
index=(ssize_t) GetPixelGreen(image,q);
SetPixelGreen(image,image->colormap[
ConstrainColormapIndex(image,index,exception)].green,q);
index=(ssize_t) GetPixelBlue(image,q);
SetPixelBlue(image,image->colormap[
ConstrainColormapIndex(image,index,exception)].blue,q);
}
SetPixelAlpha(image,image->alpha_trait != UndefinedPixelTrait ?
ScaleCharToQuantum(*(p+number_pixels*3)) : OpaqueAlpha,q);
p++;
q+=GetPixelChannels(image);
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
}
pixels=(unsigned char *) RelinquishMagickMemory(pixels);
if (image->storage_class == PseudoClass)
(void) SyncImage(image,exception);
if (EOFBlob(image) != MagickFalse)
{
ThrowFileException(exception,CorruptImageError,"UnexpectedEndOfFile",
image->filename);
break;
}
if (image_info->number_scenes != 0)
if (image->scene >= (image_info->scene+image_info->number_scenes-1))
break;
count=ReadBlob(image,1,&viff_info.identifier);
if ((count != 0) && (viff_info.identifier == 0xab))
{
AcquireNextImage(image_info,image,exception);
if (GetNextImageInList(image) == (Image *) NULL)
{
image=DestroyImageList(image);
return((Image *) NULL);
}
image=SyncNextImageInList(image);
status=SetImageProgress(image,LoadImagesTag,TellBlob(image),
GetBlobSize(image));
if (status == MagickFalse)
break;
}
} while ((count != 0) && (viff_info.identifier == 0xab));
(void) CloseBlob(image);
return(GetFirstImageInList(image));
}

static Image *ReadVIFFImage(const ImageInfo *image_info,
ExceptionInfo *exception)
{
#define VFF_CM_genericRGB  15
#define VFF_CM_ntscRGB  1
#define VFF_CM_NONE  0
#define VFF_DEP_DECORDER  0x4
#define VFF_DEP_NSORDER  0x8
#define VFF_DES_RAW  0
#define VFF_LOC_IMPLICIT  1
#define VFF_MAPTYP_NONE  0
#define VFF_MAPTYP_1_BYTE  1
#define VFF_MAPTYP_2_BYTE  2
#define VFF_MAPTYP_4_BYTE  4
