EXTRACT_32BITS(tptr + 4),
EXTRACT_32BITS(tptr + 8),
EXTRACT_32BITS(tptr + 12)));
tptr += VTP_MD5_DIGEST_LEN;
break;
case VTP_SUBSET_ADV:
ND_PRINT((ndo, ", Config Rev %x", EXTRACT_32BITS(tptr)));
tptr += 4;
while (tptr < (pptr+length)) {
len = *tptr;
if (len == 0)
break;
ND_TCHECK2(*tptr, len);
vtp_vlan = (const struct vtp_vlan_*)tptr;
ND_TCHECK(*vtp_vlan);
ND_PRINT((ndo, "\n\tVLAN info status %s, type %s, VLAN-id %u, MTU %u, SAID 0x%08x, Name ",
tok2str(vtp_vlan_status,"Unknown",vtp_vlan->status),
tok2str(vtp_vlan_type_values,"Unknown",vtp_vlan->type),
EXTRACT_16BITS(&vtp_vlan->vlanid),
EXTRACT_16BITS(&vtp_vlan->mtu),
EXTRACT_32BITS(&vtp_vlan->index)));
fn_printzp(ndo, tptr + VTP_VLAN_INFO_OFFSET, vtp_vlan->name_len, NULL);
len  -= VTP_VLAN_INFO_OFFSET + 4*((vtp_vlan->name_len + 3)/4);
tptr += VTP_VLAN_INFO_OFFSET + 4*((vtp_vlan->name_len + 3)/4);
while (len > 0) {
type = *tptr;
tlv_len = *(tptr+1);
ND_PRINT((ndo, "\n\t\t%s (0x%04x) TLV",
tok2str(vtp_vlan_tlv_values, "Unknown", type),
type));
if (type == 0 || tlv_len == 0) {
return;
}
ND_TCHECK2(*tptr, tlv_len * 2 +2);
tlv_value = EXTRACT_16BITS(tptr+2);
switch (type) {
case VTP_VLAN_STE_HOP_COUNT:
ND_PRINT((ndo, ", %u", tlv_value));
break;
case VTP_VLAN_PRUNING:
ND_PRINT((ndo, ", %s (%u)",
tlv_value == 1 ? "Enabled" : "Disabled",
tlv_value));
break;
case VTP_VLAN_STP_TYPE:
ND_PRINT((ndo, ", %s (%u)",
tok2str(vtp_stp_type_values, "Unknown", tlv_value),
tlv_value));
break;
case VTP_VLAN_BRIDGE_TYPE:
ND_PRINT((ndo, ", %s (%u)",
tlv_value == 1 ? "SRB" : "SRT",
tlv_value));
break;
case VTP_VLAN_BACKUP_CRF_MODE:
ND_PRINT((ndo, ", %s (%u)",
tlv_value == 1 ? "Backup" : "Not backup",
tlv_value));
break;
case VTP_VLAN_SOURCE_ROUTING_RING_NUMBER:
case VTP_VLAN_SOURCE_ROUTING_BRIDGE_NUMBER:
case VTP_VLAN_PARENT_VLAN:
case VTP_VLAN_TRANS_BRIDGED_VLAN:
case VTP_VLAN_ARP_HOP_COUNT:
default:
print_unknown_data(ndo, tptr, "\n\t\t  ", 2 + tlv_len*2);
break;
}
len -= 2 + tlv_len*2;
tptr += 2 + tlv_len*2;
}
}
break;
case VTP_ADV_REQUEST:
ND_TCHECK2(*tptr, 4);
ND_PRINT((ndo, "\n\tStart value: %u", EXTRACT_32BITS(tptr)));
break;
case VTP_JOIN_MESSAGE:
break;
default:
break;
}
return;
trunc:
ND_PRINT((ndo, "[|vtp]"));
}

int IMA::decodeBlockWAVE(const uint8_t *encoded, int16_t *decoded)
{
int channelCount = m_track->f.channelCount;
for (int c=0; c<channelCount; c++)
{
m_adpcmState[c].previousValue = (encoded[1]<<8) | encoded[0];
if (encoded[1] & 0x80)
m_adpcmState[c].previousValue -= 0x10000;
m_adpcmState[c].index = encoded[2];
*decoded++ = m_adpcmState[c].previousValue;
encoded += 4;
}
for (int n=0; n<m_framesPerPacket - 1; n += 8)
{
for (int c=0; c<channelCount; c++)
{
int16_t *output = decoded + c;
for (int s=0; s<4; s++)
{
*output = decodeSample(m_adpcmState[c], *encoded & 0xf);
output += channelCount;
*output = decodeSample(m_adpcmState[c], *encoded >> 4);
output += channelCount;
encoded++;
}
}
decoded += channelCount * 8;
}
return m_framesPerPacket * channelCount * sizeof (int16_t);
}

static bfd_boolean
scan_unit_for_symbols (struct comp_unit *unit)
{
bfd *abfd = unit->abfd;
bfd_byte *info_ptr = unit->first_child_die_ptr;
bfd_byte *info_ptr_end = unit->end_ptr;
int nesting_level = 0;
struct nest_funcinfo {
struct funcinfo *func;
} *nested_funcs;
int nested_funcs_size;
nested_funcs_size = 32;
nested_funcs = (struct nest_funcinfo *)
bfd_malloc (nested_funcs_size * sizeof (*nested_funcs));
if (nested_funcs == NULL)
return FALSE;
nested_funcs[nesting_level].func = 0;
while (nesting_level >= 0)
{
unsigned int abbrev_number, bytes_read, i;
struct abbrev_info *abbrev;
struct attribute attr;
struct funcinfo *func;
struct varinfo *var;
bfd_vma low_pc = 0;
bfd_vma high_pc = 0;
bfd_boolean high_pc_relative = FALSE;
bfd_uint64_t current_offset;
if (info_ptr >= info_ptr_end)
goto fail;
current_offset = info_ptr - unit->info_ptr_unit;
abbrev_number = _bfd_safe_read_leb128 (abfd, info_ptr, &bytes_read,
FALSE, info_ptr_end);
info_ptr += bytes_read;
if (! abbrev_number)
{
nesting_level--;
continue;
}
abbrev = lookup_abbrev (abbrev_number, unit->abbrevs);
if (! abbrev)
{
static unsigned int previous_failed_abbrev = -1U;
if (abbrev_number != previous_failed_abbrev)
{
_bfd_error_handler
(_("DWARF error: could not find abbrev number %u"),
abbrev_number);
previous_failed_abbrev = abbrev_number;
}
bfd_set_error (bfd_error_bad_value);
goto fail;
}
if (abbrev->tag == DW_TAG_subprogram
|| abbrev->tag == DW_TAG_entry_point
|| abbrev->tag == DW_TAG_inlined_subroutine)
{
size_t amt = sizeof (struct funcinfo);
var = NULL;
func = (struct funcinfo *) bfd_zalloc (abfd, amt);
if (func == NULL)
goto fail;
func->tag = abbrev->tag;
func->prev_func = unit->function_table;
unit->function_table = func;
unit->number_of_functions++;
BFD_ASSERT (!unit->cached);
if (func->tag == DW_TAG_inlined_subroutine)
for (i = nesting_level; i-- != 0; )
if (nested_funcs[i].func)
{
func->caller_func = nested_funcs[i].func;
break;
}
nested_funcs[nesting_level].func = func;
}
else
{
func = NULL;
if (abbrev->tag == DW_TAG_variable)
{
size_t amt = sizeof (struct varinfo);
var = (struct varinfo *) bfd_zalloc (abfd, amt);
if (var == NULL)
goto fail;
var->tag = abbrev->tag;
var->stack = TRUE;
var->prev_var = unit->variable_table;
unit->variable_table = var;
var->unit_offset = current_offset;
}
else
var = NULL;
nested_funcs[nesting_level].func = 0;
}
for (i = 0; i < abbrev->num_attrs; ++i)
{
info_ptr = read_attribute (&attr, &abbrev->attrs[i],
unit, info_ptr, info_ptr_end);
if (info_ptr == NULL)
goto fail;
if (func)
{
switch (attr.name)
{
case DW_AT_call_file:
func->caller_file = concat_filename (unit->line_table,
attr.u.val);
break;
case DW_AT_call_line:
func->caller_line = attr.u.val;
break;
case DW_AT_abstract_origin:
case DW_AT_specification:
if (!find_abstract_instance (unit, &attr, 0,
&func->name,
&func->is_linkage,
&func->file,
&func->line))
goto fail;
break;
case DW_AT_name:
if (func->name == NULL && is_str_attr (attr.form))
{
func->name = attr.u.str;
if (non_mangled (unit->lang))
func->is_linkage = TRUE;
}
break;
case DW_AT_linkage_name:
case DW_AT_MIPS_linkage_name:
if (is_str_attr (attr.form))
{
func->name = attr.u.str;
func->is_linkage = TRUE;
}
break;
case DW_AT_low_pc:
low_pc = attr.u.val;
break;
case DW_AT_high_pc:
high_pc = attr.u.val;
high_pc_relative = attr.form != DW_FORM_addr;
break;
case DW_AT_ranges:
if (!read_rangelist (unit, &func->arange, attr.u.val))
goto fail;
break;
case DW_AT_decl_file:
func->file = concat_filename (unit->line_table,
attr.u.val);
break;
case DW_AT_decl_line:
func->line = attr.u.val;
break;
default:
break;
}
}
else if (var)
{
switch (attr.name)
{
case DW_AT_specification:
if (attr.u.val)
{
struct varinfo * spec_var;
spec_var = lookup_var_by_offset (attr.u.val, unit->variable_table);
if (spec_var == NULL)
{
_bfd_error_handler
(_("DWARF error: could not find variable specification at offset %lx"),
(unsigned long) attr.u.val);
break;
}
if (var->name == NULL)
var->name = spec_var->name;
if (var->file == NULL)
var->file = strdup (spec_var->file);
if (var->line == 0)
var->line = spec_var->line;
if (var->sec == NULL)
var->sec = spec_var->sec;
}
break;
case DW_AT_name:
if (is_str_attr (attr.form))
var->name = attr.u.str;
break;
case DW_AT_decl_file:
var->file = concat_filename (unit->line_table,
attr.u.val);
break;
case DW_AT_decl_line:
var->line = attr.u.val;
break;
case DW_AT_external:
if (attr.u.val != 0)
var->stack = FALSE;
break;
case DW_AT_location:
switch (attr.form)
{
case DW_FORM_block:
case DW_FORM_block1:
case DW_FORM_block2:
case DW_FORM_block4:
case DW_FORM_exprloc:
if (attr.u.blk->data != NULL
&& *attr.u.blk->data == DW_OP_addr)
{
var->stack = FALSE;
if (attr.u.blk->size == unit->addr_size + 1U)
var->addr = bfd_get (unit->addr_size * 8,
unit->abfd,
attr.u.blk->data + 1);
}
break;
default:
break;
}
break;
default:
break;
}
}
}
if (high_pc_relative)
high_pc += low_pc;
if (func && high_pc != 0)
{
if (!arange_add (unit, &func->arange, low_pc, high_pc))
goto fail;
}
if (abbrev->has_children)
{
nesting_level++;
if (nesting_level >= nested_funcs_size)
{
struct nest_funcinfo *tmp;
nested_funcs_size *= 2;
tmp = (struct nest_funcinfo *)
bfd_realloc (nested_funcs,
nested_funcs_size * sizeof (*nested_funcs));
if (tmp == NULL)
goto fail;
nested_funcs = tmp;
}
nested_funcs[nesting_level].func = 0;
}
}
free (nested_funcs);
return TRUE;
fail:
free (nested_funcs);
return FALSE;
}

static bool
parse_module (bfd *abfd, struct module *module, unsigned char *ptr,
bfd_size_type length)
{
unsigned char *maxptr = ptr + length;
unsigned char *src_ptr, *pcl_ptr;
unsigned int prev_linum = 0, curr_linenum = 0;
bfd_vma prev_pc = 0, curr_pc = 0;
struct srecinfo *curr_srec, *srec;
struct lineinfo *curr_line, *line;
struct funcinfo *funcinfo;
curr_srec = (struct srecinfo *) bfd_zalloc (abfd, sizeof (struct srecinfo));
if (!curr_srec)
return false;
module->srec_table = curr_srec;
curr_line = (struct lineinfo *) bfd_zalloc (abfd, sizeof (struct lineinfo));
if (!curr_line)
return false;
module->line_table = curr_line;
while (ptr + 3 < maxptr)
{
int rec_length = bfd_getl16 (ptr) + 1;
int rec_type = bfd_getl16 (ptr + 2);
vms_debug2 ((2, "DST record: leng %d, type %d\n", rec_length, rec_type));
if (rec_length > maxptr - ptr)
break;
if (rec_type == DST__K_MODEND)
break;
switch (rec_type)
{
case DST__K_MODBEG:
if (rec_length <= DST_S_B_MODBEG_NAME)
break;
module->name
= _bfd_vms_save_counted_string (abfd, ptr + DST_S_B_MODBEG_NAME,
rec_length - DST_S_B_MODBEG_NAME);
curr_pc = 0;
prev_pc = 0;
curr_linenum = 0;
prev_linum = 0;
vms_debug2 ((3, "module: %s\n", module->name));
break;
case DST__K_MODEND:
break;
case DST__K_RTNBEG:
if (rec_length <= DST_S_B_RTNBEG_NAME)
break;
funcinfo = (struct funcinfo *)
bfd_zalloc (abfd, sizeof (struct funcinfo));
if (!funcinfo)
return false;
funcinfo->name
= _bfd_vms_save_counted_string (abfd, ptr + DST_S_B_RTNBEG_NAME,
rec_length - DST_S_B_RTNBEG_NAME);
funcinfo->low = bfd_getl32 (ptr + DST_S_L_RTNBEG_ADDRESS);
funcinfo->next = module->func_table;
module->func_table = funcinfo;
vms_debug2 ((3, "routine: %s at 0x%lx\n",
funcinfo->name, (unsigned long) funcinfo->low));
break;
case DST__K_RTNEND:
if (rec_length < DST_S_L_RTNEND_SIZE + 4)
break;
if (!module->func_table)
return false;
module->func_table->high = module->func_table->low
+ bfd_getl32 (ptr + DST_S_L_RTNEND_SIZE) - 1;
if (module->func_table->high > module->high)
module->high = module->func_table->high;
vms_debug2 ((3, "end routine\n"));
break;
case DST__K_PROLOG:
vms_debug2 ((3, "prologue\n"));
break;
case DST__K_EPILOG:
vms_debug2 ((3, "epilog\n"));
break;
case DST__K_BLKBEG:
vms_debug2 ((3, "block\n"));
break;
case DST__K_BLKEND:
vms_debug2 ((3, "end block\n"));
break;
case DST__K_SOURCE:
src_ptr = ptr + DST_S_C_SOURCE_HEADER_SIZE;
vms_debug2 ((3, "source info\n"));
while (src_ptr - ptr < rec_length)
{
int cmd = src_ptr[0], cmd_length, data;
switch (cmd)
{
case DST__K_SRC_DECLFILE:
if (src_ptr - ptr + DST_S_B_SRC_DF_LENGTH >= rec_length)
cmd_length = 0x10000;
else
cmd_length = src_ptr[DST_S_B_SRC_DF_LENGTH] + 2;
break;
case DST__K_SRC_DEFLINES_B:
cmd_length = 2;
break;
case DST__K_SRC_DEFLINES_W:
cmd_length = 3;
break;
case DST__K_SRC_INCRLNUM_B:
cmd_length = 2;
break;
case DST__K_SRC_SETFILE:
cmd_length = 3;
break;
case DST__K_SRC_SETLNUM_L:
cmd_length = 5;
break;
case DST__K_SRC_SETLNUM_W:
cmd_length = 3;
break;
case DST__K_SRC_SETREC_L:
cmd_length = 5;
break;
case DST__K_SRC_SETREC_W:
cmd_length = 3;
break;
case DST__K_SRC_FORMFEED:
cmd_length = 1;
break;
default:
cmd_length = 2;
break;
}
if (src_ptr - ptr + cmd_length > rec_length)
break;
switch (cmd)
{
case DST__K_SRC_DECLFILE:
{
unsigned int fileid
= bfd_getl16 (src_ptr + DST_S_W_SRC_DF_FILEID);
char *filename = _bfd_vms_save_counted_string
(abfd,
src_ptr + DST_S_B_SRC_DF_FILENAME,
ptr + rec_length - (src_ptr + DST_S_B_SRC_DF_FILENAME));
while (fileid >= module->file_table_count)
{
module->file_table_count *= 2;
module->file_table
= bfd_realloc_or_free (module->file_table,
module->file_table_count
* sizeof (struct fileinfo));
if (module->file_table == NULL)
return false;
}
module->file_table [fileid].name = filename;
module->file_table [fileid].srec = 1;
vms_debug2 ((4, "DST_S_C_SRC_DECLFILE: %d, %s\n",
fileid, module->file_table [fileid].name));
}
break;
case DST__K_SRC_DEFLINES_B:
data = src_ptr[DST_S_B_SRC_UNSBYTE];
srec = (struct srecinfo *)
bfd_zalloc (abfd, sizeof (struct srecinfo));
srec->line = curr_srec->line + data;
srec->srec = curr_srec->srec + data;
srec->sfile = curr_srec->sfile;
curr_srec->next = srec;
curr_srec = srec;
vms_debug2 ((4, "DST_S_C_SRC_DEFLINES_B: %d\n", data));
break;
case DST__K_SRC_DEFLINES_W:
data = bfd_getl16 (src_ptr + DST_S_W_SRC_UNSWORD);
srec = (struct srecinfo *)
bfd_zalloc (abfd, sizeof (struct srecinfo));
srec->line = curr_srec->line + data;
srec->srec = curr_srec->srec + data,
srec->sfile = curr_srec->sfile;
curr_srec->next = srec;
curr_srec = srec;
vms_debug2 ((4, "DST_S_C_SRC_DEFLINES_W: %d\n", data));
break;
case DST__K_SRC_INCRLNUM_B:
data = src_ptr[DST_S_B_SRC_UNSBYTE];
curr_srec->line += data;
vms_debug2 ((4, "DST_S_C_SRC_INCRLNUM_B: %d\n", data));
break;
case DST__K_SRC_SETFILE:
data = bfd_getl16 (src_ptr + DST_S_W_SRC_UNSWORD);
curr_srec->sfile = data;
curr_srec->srec = module->file_table[data].srec;
vms_debug2 ((4, "DST_S_C_SRC_SETFILE: %d\n", data));
break;
case DST__K_SRC_SETLNUM_L:
data = bfd_getl32 (src_ptr + DST_S_L_SRC_UNSLONG);
curr_srec->line = data;
vms_debug2 ((4, "DST_S_C_SRC_SETLNUM_L: %d\n", data));
break;
case DST__K_SRC_SETLNUM_W:
data = bfd_getl16 (src_ptr + DST_S_W_SRC_UNSWORD);
curr_srec->line = data;
vms_debug2 ((4, "DST_S_C_SRC_SETLNUM_W: %d\n", data));
break;
case DST__K_SRC_SETREC_L:
data = bfd_getl32 (src_ptr + DST_S_L_SRC_UNSLONG);
curr_srec->srec = data;
module->file_table[curr_srec->sfile].srec = data;
vms_debug2 ((4, "DST_S_C_SRC_SETREC_L: %d\n", data));
break;
case DST__K_SRC_SETREC_W:
data = bfd_getl16 (src_ptr + DST_S_W_SRC_UNSWORD);
curr_srec->srec = data;
module->file_table[curr_srec->sfile].srec = data;
vms_debug2 ((4, "DST_S_C_SRC_SETREC_W: %d\n", data));
break;
case DST__K_SRC_FORMFEED:
vms_debug2 ((4, "DST_S_C_SRC_FORMFEED\n"));
break;
default:
_bfd_error_handler (_("unknown source command %d"),
cmd);
break;
}
src_ptr += cmd_length;
}
break;
case DST__K_LINE_NUM:
pcl_ptr = ptr + DST_S_C_LINE_NUM_HEADER_SIZE;
vms_debug2 ((3, "line info\n"));
while (pcl_ptr - ptr < rec_length)
{
int cmd = ((signed char *)pcl_ptr)[0], cmd_length, data;
switch (cmd)
{
case DST__K_DELTA_PC_W:
cmd_length = 3;
break;
case DST__K_DELTA_PC_L:
cmd_length = 5;
break;
case DST__K_INCR_LINUM:
cmd_length = 2;
break;
case DST__K_INCR_LINUM_W:
cmd_length = 3;
break;
case DST__K_INCR_LINUM_L:
cmd_length = 5;
break;
case DST__K_SET_LINUM_INCR:
cmd_length = 2;
break;
case DST__K_SET_LINUM_INCR_W:
cmd_length = 3;
break;
case DST__K_RESET_LINUM_INCR:
cmd_length = 1;
break;
case DST__K_BEG_STMT_MODE:
cmd_length = 1;
break;
case DST__K_END_STMT_MODE:
cmd_length = 1;
break;
case DST__K_SET_LINUM_B:
cmd_length = 2;
break;
case DST__K_SET_LINUM:
cmd_length = 3;
break;
case DST__K_SET_LINUM_L:
cmd_length = 5;
break;
case DST__K_SET_PC:
cmd_length = 2;
break;
case DST__K_SET_PC_W:
cmd_length = 3;
break;
case DST__K_SET_PC_L:
cmd_length = 5;
break;
case DST__K_SET_STMTNUM:
cmd_length = 2;
break;
case DST__K_TERM:
cmd_length = 2;
break;
case DST__K_TERM_W:
cmd_length = 3;
break;
case DST__K_TERM_L:
cmd_length = 5;
break;
case DST__K_SET_ABS_PC:
cmd_length = 5;
break;
default:
if (cmd <= 0)
cmd_length = 1;
else
cmd_length = 2;
break;
}
if (pcl_ptr - ptr + cmd_length > rec_length)
break;
switch (cmd)
{
case DST__K_DELTA_PC_W:
data = bfd_getl16 (pcl_ptr + DST_S_W_PCLINE_UNSWORD);
curr_pc += data;
curr_linenum += 1;
vms_debug2 ((4, "DST__K_DELTA_PC_W: %d\n", data));
break;
case DST__K_DELTA_PC_L:
data = bfd_getl32 (pcl_ptr + DST_S_L_PCLINE_UNSLONG);
curr_pc += data;
curr_linenum += 1;
vms_debug2 ((4, "DST__K_DELTA_PC_L: %d\n", data));
break;
case DST__K_INCR_LINUM:
data = pcl_ptr[DST_S_B_PCLINE_UNSBYTE];
curr_linenum += data;
vms_debug2 ((4, "DST__K_INCR_LINUM: %d\n", data));
break;
case DST__K_INCR_LINUM_W:
data = bfd_getl16 (pcl_ptr + DST_S_W_PCLINE_UNSWORD);
curr_linenum += data;
vms_debug2 ((4, "DST__K_INCR_LINUM_W: %d\n", data));
break;
case DST__K_INCR_LINUM_L:
data = bfd_getl32 (pcl_ptr + DST_S_L_PCLINE_UNSLONG);
curr_linenum += data;
vms_debug2 ((4, "DST__K_INCR_LINUM_L: %d\n", data));
break;
case DST__K_SET_LINUM_INCR:
_bfd_error_handler
(_("%s not implemented"), "DST__K_SET_LINUM_INCR");
break;
case DST__K_SET_LINUM_INCR_W:
_bfd_error_handler
(_("%s not implemented"), "DST__K_SET_LINUM_INCR_W");
break;
case DST__K_RESET_LINUM_INCR:
_bfd_error_handler
(_("%s not implemented"), "DST__K_RESET_LINUM_INCR");
break;
case DST__K_BEG_STMT_MODE:
_bfd_error_handler
(_("%s not implemented"), "DST__K_BEG_STMT_MODE");
break;
case DST__K_END_STMT_MODE:
_bfd_error_handler
(_("%s not implemented"), "DST__K_END_STMT_MODE");
break;
case DST__K_SET_LINUM_B:
data = pcl_ptr[DST_S_B_PCLINE_UNSBYTE];
curr_linenum = data;
vms_debug2 ((4, "DST__K_SET_LINUM_B: %d\n", data));
break;
case DST__K_SET_LINUM:
data = bfd_getl16 (pcl_ptr + DST_S_W_PCLINE_UNSWORD);
curr_linenum = data;
vms_debug2 ((4, "DST__K_SET_LINE_NUM: %d\n", data));
break;
case DST__K_SET_LINUM_L:
data = bfd_getl32 (pcl_ptr + DST_S_L_PCLINE_UNSLONG);
curr_linenum = data;
vms_debug2 ((4, "DST__K_SET_LINUM_L: %d\n", data));
break;
case DST__K_SET_PC:
_bfd_error_handler
(_("%s not implemented"), "DST__K_SET_PC");
break;
case DST__K_SET_PC_W:
_bfd_error_handler
(_("%s not implemented"), "DST__K_SET_PC_W");
break;
case DST__K_SET_PC_L:
_bfd_error_handler
(_("%s not implemented"), "DST__K_SET_PC_L");
break;
case DST__K_SET_STMTNUM:
_bfd_error_handler
(_("%s not implemented"), "DST__K_SET_STMTNUM");
break;
case DST__K_TERM:
data = pcl_ptr[DST_S_B_PCLINE_UNSBYTE];
curr_pc += data;
vms_debug2 ((4, "DST__K_TERM: %d\n", data));
break;
case DST__K_TERM_W:
data = bfd_getl16 (pcl_ptr + DST_S_W_PCLINE_UNSWORD);
curr_pc += data;
vms_debug2 ((4, "DST__K_TERM_W: %d\n", data));
break;
case DST__K_TERM_L:
data = bfd_getl32 (pcl_ptr + DST_S_L_PCLINE_UNSLONG);
curr_pc += data;
vms_debug2 ((4, "DST__K_TERM_L: %d\n", data));
break;
case DST__K_SET_ABS_PC:
data = bfd_getl32 (pcl_ptr + DST_S_L_PCLINE_UNSLONG);
curr_pc = data;
vms_debug2 ((4, "DST__K_SET_ABS_PC: 0x%x\n", data));
break;
default:
if (cmd <= 0)
{
curr_pc -= cmd;
curr_linenum += 1;
vms_debug2 ((4, "bump pc to 0x%lx and line to %d\n",
(unsigned long)curr_pc, curr_linenum));
}
else
_bfd_error_handler (_("unknown line command %d"), cmd);
break;
}
if ((curr_linenum != prev_linum && curr_pc != prev_pc)
|| cmd <= 0
|| cmd == DST__K_DELTA_PC_L
|| cmd == DST__K_DELTA_PC_W)
{
line = (struct lineinfo *)
bfd_zalloc (abfd, sizeof (struct lineinfo));
line->address = curr_pc;
line->line = curr_linenum;
curr_line->next = line;
curr_line = line;
prev_linum = curr_linenum;
prev_pc = curr_pc;
vms_debug2 ((4, "-> correlate pc 0x%lx with line %d\n",
(unsigned long)curr_pc, curr_linenum));
}
pcl_ptr += cmd_length;
}
break;
case 0x17: 
vms_debug2 ((3, "undocumented type 0x17\n"));
break;
default:
vms_debug2 ((3, "ignoring record\n"));
break;
}
ptr += rec_length;
}
srec = (struct srecinfo *) bfd_zalloc (abfd, sizeof (struct srecinfo));
srec->line = (unsigned int) -1;
srec->srec = (unsigned int) -1;
curr_srec->next = srec;
line = (struct lineinfo *) bfd_zalloc (abfd, sizeof (struct lineinfo));
line->line = (unsigned int) -1;
line->address = (bfd_vma) -1;
curr_line->next = line;
SET_MODULE_PARSED (module);
return true;
}

