return;
}
assert(
curScopeDepth && curScopeDepth.getValue() >= instScopeDepth.getValue() &&
"Cannot access variables in inner scopes");
int32_t delta = curScopeDepth.getValue() - instScopeDepth.getValue();
assert(delta > 0 && "HBCResolveEnvironment for current scope");
BCFGen_->emitGetEnvironment(encodeValue(Inst), delta - 1);
}

int
eval0_retarg(
char_u*arg,
typval_T*rettv,
exarg_T*eap,
evalarg_T*evalarg,
char_u**retarg)
{
intret;
char_u*p;
char_u*expr_end;
intdid_emsg_before = did_emsg;
intcalled_emsg_before = called_emsg;
intflags = evalarg == NULL ? 0 : evalarg->eval_flags;
intcheck_for_end = retarg == NULL;
intend_error = FALSE;
p = skipwhite(arg);
ret = eval1(&p, rettv, evalarg);
expr_end = p;
p = skipwhite(p);
if (in_vim9script() && p > expr_end && retarg == NULL)
while (*p == '#')
{
char_u *nl = vim_strchr(p, NL);
if (nl == NULL)
break;
p = skipwhite(nl + 1);
if (eap != NULL && *p != NUL)
eap->nextcmd = p;
check_for_end = FALSE;
}
if (ret != FAIL && check_for_end)
end_error = !ends_excmd2(arg, p);
if (ret == FAIL || end_error)
{
if (ret != FAIL)
clear_tv(rettv);
if (!aborting()
&& did_emsg == did_emsg_before
&& called_emsg == called_emsg_before
&& (flags & EVAL_CONSTANT) == 0
&& (!in_vim9script() || !vim9_bad_comment(p)))
{
if (end_error)
semsg(_(e_trailing_characters_str), p);
else
semsg(_(e_invalid_expression_str), arg);
}
if (eap != NULL && skipwhite(p)[0] == '|' && skipwhite(p)[1] != '|')
eap->nextcmd = check_nextcmd(p);
return FAIL;
}
if (retarg != NULL)
*retarg = p;
else if (check_for_end && eap != NULL)
set_nextcmd(eap, p);
return ret;
}

static ssize_t
next_line(struct archive_read *a,
const char **b, ssize_t *avail, ssize_t *ravail, ssize_t *nl)
{
ssize_t len;
int quit;
quit = 0;
if (*avail == 0) {
*nl = 0;
len = 0;
} else
len = get_line_size(*b, *avail, nl);
while (*nl == 0 && len == *avail && !quit) {
ssize_t diff = *ravail - *avail;
size_t nbytes_req = (*ravail+1023) & ~1023U;
ssize_t tested;
if (nbytes_req < (size_t)*ravail + 160)
nbytes_req <<= 1;
*b = __archive_read_ahead(a, nbytes_req, avail);
if (*b == NULL) {
if (*ravail >= *avail)
return (0);
*b = __archive_read_ahead(a, *avail, avail);
quit = 1;
}
*ravail = *avail;
*b += diff;
*avail -= diff;
tested = len;
len = get_line_size(*b, *avail, nl);
if (len >= 0)
len += tested;
}
return (len);
}

void JTL::send( Session* session, int resolution, int tile ){
Timer function_timer;
if( session->loglevel >= 3 ) (*session->logfile) << "JTL handler reached" << endl;
this->session = session;
checkImage();
if( session->loglevel >= 2 ) command_timer.start();
if( (int)((session->view)->getRotation()) % 360 == 90 ){
}
else if( (int)((session->view)->getRotation()) % 360 == 270 ){
}
else if( (int)((session->view)->getRotation()) % 360 == 180 ){
int num_res = (*session->image)->getNumResolutions();
unsigned int im_width = (*session->image)->image_widths[num_res-resolution-1];
unsigned int im_height = (*session->image)->image_heights[num_res-resolution-1];
unsigned int tw = (*session->image)->getTileWidth();
int ntiles = (int) ceil( (double)im_width/tw ) * (int) ceil( (double)im_height/tw );
tile = ntiles - tile - 1;
}
if( (resolution<0) || (tile<0) ){
ostringstream error;
error << "JTL :: Invalid resolution/tile number: " << resolution << "," << tile;
throw error.str();
}
CompressionType ct = session->view->output_format;
Compressor *compressor;
if( session->view->output_format == JPEG ) compressor = session->jpeg;
#ifdef HAVE_PNG
else if( session->view->output_format == PNG ) compressor = session->png;
#endif
else compressor = session->jpeg;
TileManager tilemanager( session->tileCache, *session->image, session->watermark, compressor, session->logfile, session->loglevel );
if( session->view->requireHistogram() && (*session->image)->histogram.size()==0 ){
if( session->loglevel >= 4 ) function_timer.start();
RawTile thumbnail = tilemanager.getTile( 0, 0, 0, session->view->yangle, session->view->getLayers(), UNCOMPRESSED );
(*session->image)->histogram =
session->processor->histogram( thumbnail, (*session->image)->max, (*session->image)->min );
if( session->loglevel >= 4 ){
*(session->logfile) << "JTL :: Calculated histogram in "
<< function_timer.getTime() << " microseconds" << endl;
}
const string key = (*session->image)->getImagePath();
imageCacheMapType::iterator i = session->imageCache->find(key);
if( i != session->imageCache->end() ) (i->second).histogram = (*session->image)->histogram;
}
if( (*session->image)->getNumBitsPerPixel() > 8 || (*session->image)->getColourSpace() == CIELAB
|| (*session->image)->getNumChannels() == 2 || (*session->image)->getNumChannels() > 3
|| ( (session->view->colourspace==GREYSCALE || session->view->colourspace==BINARY) && (*session->image)->getNumChannels()==3 &&
(*session->image)->getNumBitsPerPixel()==8 )
|| session->view->floatProcessing() || session->view->equalization
|| session->view->getRotation() != 0.0 || session->view->flip != 0
) ct = UNCOMPRESSED;
int num_res = (*session->image)->getNumResolutions();
unsigned int im_width = (*session->image)->image_widths[num_res-resolution-1];
unsigned int im_height = (*session->image)->image_heights[num_res-resolution-1];
float dpi_x = (*session->image)->dpi_x * (float) im_width / (float) (*session->image)->getImageWidth();
float dpi_y = (*session->image)->dpi_y * (float) im_height / (float) (*session->image)->getImageHeight();
compressor->setResolution( dpi_x, dpi_y, (*session->image)->dpi_units );
if( session->loglevel >= 5 ){
*(session->logfile) << "JTL :: Setting physical resolution of tile to " <<  dpi_x << " x " << dpi_y
<< ( ((*session->image)->dpi_units==1) ? " pixels/inch" : " pixels/cm" ) << endl;
}
if( session->view->embedICC() && ((*session->image)->getMetadata("icc").size()>0) ){
if( session->loglevel >= 3 ){
*(session->logfile) << "JTL :: Embedding ICC profile with size "
<< (*session->image)->getMetadata("icc").size() << " bytes" << endl;
}
compressor->setICCProfile( (*session->image)->getMetadata("icc") );
}
RawTile rawtile = tilemanager.getTile( resolution, tile, session->view->xangle,
session->view->yangle, session->view->getLayers(), ct );
int len = rawtile.dataLength;
if( session->loglevel >= 2 ){
*(session->logfile) << "JTL :: Tile size: " << rawtile.width << " x " << rawtile.height << endl
<< "JTL :: Channels per sample: " << rawtile.channels << endl
<< "JTL :: Bits per channel: " << rawtile.bpc << endl
<< "JTL :: Data size is " << len << " bytes" << endl;
}
if( (*session->image)->getColourSpace() == CIELAB ){
if( session->loglevel >= 4 ){
*(session->logfile) << "JTL :: Converting from CIELAB->sRGB";
function_timer.start();
}
session->processor->LAB2sRGB( rawtile );
if( session->loglevel >= 4 ){
*(session->logfile) << " in " << function_timer.getTime() << " microseconds" << endl;
}
}
if( rawtile.bpc > 8 || session->view->floatProcessing() ){
vector <float> min = (*session->image)->min;
vector <float> max = (*session->image)->max;
if( session->view->contrast == -1 ){
unsigned int n0 = 0;
while( (*session->image)->histogram[n0] == 0 ) ++n0;
unsigned int n1 = (*session->image)->histogram.size() - 1;
while( (*session->image)->histogram[n1] == 0 ) --n1;
if( rawtile.bpc > 8 && rawtile.sampleType == FIXEDPOINT ){
n0 = n0 << (rawtile.bpc-8);
n1 = n1 << (rawtile.bpc-8);
}
min.assign( rawtile.bpc, (float)n0 );
max.assign( rawtile.bpc, (float)n1 );
session->view->contrast = 1.0;
if( session->loglevel >= 5 ){
*(session->logfile) << "JTL :: Applying contrast stretch for image range of "
<< n0 << " - " << n1 << endl;
}
}
if( session->loglevel >= 4 ){
*(session->logfile) << "JTL :: Normalizing and converting to float";
function_timer.start();
}
session->processor->normalize( rawtile, max, min );
if( session->loglevel >= 4 ){
*(session->logfile) << " in " << function_timer.getTime() << " microseconds" << endl;
}
if( session->view->shaded ){
if( session->loglevel >= 4 ){
*(session->logfile) << "JTL :: Applying hill-shading";
function_timer.start();
}
session->processor->shade( rawtile, session->view->shade[0], session->view->shade[1] );
if( session->loglevel >= 4 ){
*(session->logfile) << " in " << function_timer.getTime() << " microseconds" << endl;
}
}
if( session->view->ctw.size() ){
if( session->loglevel >= 4 ){
*(session->logfile) << "JTL :: Applying color twist";
function_timer.start();
}
session->processor->twist( rawtile, session->view->ctw );
if( session->loglevel >= 4 ){
*(session->logfile) << " in " << function_timer.getTime() << " microseconds" << endl;
}
}
if( session->view->gamma != 1.0 ){
float gamma = session->view->gamma;
if( session->loglevel >= 4 ) function_timer.start();
if( gamma == -1 ) session->processor->log( rawtile );
else session->processor->gamma( rawtile, gamma );
if( session->loglevel >= 4 ){
if( gamma == -1 ) *(session->logfile) << "JTL :: Applying logarithm transform in ";
else *(session->logfile) << "JTL :: Applying gamma of " << gamma << " in ";
*(session->logfile) << function_timer.getTime() << " microseconds" << endl;
}
}
if( session->view->inverted ){
if( session->loglevel >= 4 ){
*(session->logfile) << "JTL :: Applying inversion";
function_timer.start();
}
session->processor->inv( rawtile );
if( session->loglevel >= 4 ){
*(session->logfile) << " in " << function_timer.getTime() << " microseconds" << endl;
}
}
if( session->view->cmapped ){
if( session->loglevel >= 4 ){
*(session->logfile) << "JTL :: Applying color map";
function_timer.start();
}
session->processor->cmap( rawtile, session->view->cmap );
if( session->loglevel >= 4 ){
*(session->logfile) << " in " << function_timer.getTime() << " microseconds" << endl;
}
}
float contrast = session->view->contrast;
if( session->loglevel >= 4 ){
*(session->logfile) << "JTL :: Applying contrast of " << contrast << " and converting to 8 bit";
function_timer.start();
}
session->processor->contrast( rawtile, contrast );
if( session->loglevel >= 4 ){
*(session->logfile) << " in " << function_timer.getTime() << " microseconds" << endl;
}
}
if( ( (session->view->output_format == JPEG) && (rawtile.channels == 2 || rawtile.channels > 3) ) ||
( (session->view->output_format == PNG) && (rawtile.channels > 4) ) ){
unsigned int bands = (rawtile.channels==2) ? 1 : 3;
if( session->loglevel >= 4 ){
*(session->logfile) << "JTL :: Flattening channels to " << bands;
function_timer.start();
}
session->processor->flatten( rawtile, bands );
if( session->loglevel >= 4 ){
*(session->logfile) << " in " << function_timer.getTime() << " microseconds" << endl;
}
}
if( (*session->image)->getColourSpace() == sRGB && session->view->colourspace == GREYSCALE ){
if( session->loglevel >= 4 ){
*(session->logfile) << "JTL :: Converting to greyscale";
function_timer.start();
}
session->processor->greyscale( rawtile );
if( session->loglevel >= 4 ){
*(session->logfile) << " in " << function_timer.getTime() << " microseconds" << endl;
}
}
if( (*session->image)->getColourSpace() != BINARY && session->view->colourspace == BINARY ){
if( session->loglevel >= 4 ){
*(session->logfile) << "JTL :: Converting to binary with threshold ";
function_timer.start();
}
unsigned int threshold = session->processor->threshold( (*session->image)->histogram );
session->processor->binary( rawtile, threshold );
if( session->loglevel >= 4 ){
*(session->logfile) << threshold << " in " << function_timer.getTime() << " microseconds" << endl;
}
}
if( session->view->equalization ){
if( session->loglevel >= 4 ) function_timer.start();
session->processor->equalize( rawtile, (*session->image)->histogram );
if( session->loglevel >= 4 ){
*(session->logfile) << "JTL :: Applying histogram equalization in "
<< function_timer.getTime() << " microseconds" << endl;
}
}
if( session->view->flip != 0 ){
Timer flip_timer;
if( session->loglevel >= 5 ){
flip_timer.start();
}
session->processor->flip( rawtile, session->view->flip  );
if( session->loglevel >= 5 ){
*(session->logfile) << "JTL :: Flipping image ";
if( session->view->flip == 1 ) *(session->logfile) << "horizontally";
else *(session->logfile) << "vertically";
*(session->logfile) << " in " << flip_timer.getTime() << " microseconds" << endl;
}
}
if( session->view->getRotation() != 0.0 ){
float rotation = session->view->getRotation();
if( session->loglevel >= 4 ){
*(session->logfile) << "JTL :: Rotating image by " << rotation << " degrees";
function_timer.start();
}
session->processor->rotate( rawtile, rotation );
if( session->loglevel >= 4 ){
*(session->logfile) << " in " << function_timer.getTime() << " microseconds" << endl;
}
}
if( rawtile.compressionType == UNCOMPRESSED ){
if( session->loglevel >= 4 ){
*(session->logfile) << "JTL :: Encoding UNCOMPRESSED tile";
function_timer.start();
}
len = compressor->Compress( rawtile );
if( session->loglevel >= 4 ){
*(session->logfile) << " in " << function_timer.getTime() << " microseconds to "
<< rawtile.dataLength << " bytes" << endl;
}
}
#ifndef DEBUG
stringstream header;
header << session->response->createHTTPHeader( compressor->getMimeType(), (*session->image)->getTimestamp(), len );
if( session->out->putStr( (const char*) header.str().c_str(), header.tellp() ) == -1 ){
if( session->loglevel >= 1 ){
*(session->logfile) << "JTL :: Error writing HTTP header" << endl;
}
}
#endif
if( session->out->putStr( static_cast<const char*>(rawtile.data), len ) != len ){
if( session->loglevel >= 1 ){
*(session->logfile) << "JTL :: Error writing JPEG tile" << endl;
}
}
if( session->out->flush() == -1 ) {
if( session->loglevel >= 1 ){
*(session->logfile) << "JTL :: Error flushing JPEG tile" << endl;
}
}
session->response->setImageSent();
if( session->loglevel >= 2 ){
*(session->logfile) << "JTL :: Total command time " << command_timer.getTime() << " microseconds" << endl;
}
}

static int llcp_sock_bind(struct socket *sock, struct sockaddr *addr, int alen)
{
struct sock *sk = sock->sk;
struct nfc_llcp_sock *llcp_sock = nfc_llcp_sock(sk);
struct nfc_llcp_local *local;
struct nfc_dev *dev;
struct sockaddr_nfc_llcp llcp_addr;
int len, ret = 0;
if (!addr || alen < offsetofend(struct sockaddr, sa_family) ||
addr->sa_family != AF_NFC)
return -EINVAL;
pr_debug("sk %p addr %p family %d\n", sk, addr, addr->sa_family);
memset(&llcp_addr, 0, sizeof(llcp_addr));
len = min_t(unsigned int, sizeof(llcp_addr), alen);
memcpy(&llcp_addr, addr, len);
if (llcp_addr.dsap != 0)
return -EINVAL;
lock_sock(sk);
if (sk->sk_state != LLCP_CLOSED) {
ret = -EBADFD;
goto error;
}
dev = nfc_get_device(llcp_addr.dev_idx);
if (dev == NULL) {
ret = -ENODEV;
goto error;
}
local = nfc_llcp_find_local(dev);
if (local == NULL) {
ret = -ENODEV;
goto put_dev;
}
llcp_sock->dev = dev;
llcp_sock->local = nfc_llcp_local_get(local);
llcp_sock->nfc_protocol = llcp_addr.nfc_protocol;
llcp_sock->service_name_len = min_t(unsigned int,
llcp_addr.service_name_len,
NFC_LLCP_MAX_SERVICE_NAME);
llcp_sock->service_name = kmemdup(llcp_addr.service_name,
llcp_sock->service_name_len,
GFP_KERNEL);
if (!llcp_sock->service_name) {
nfc_llcp_local_put(llcp_sock->local);
ret = -ENOMEM;
goto put_dev;
}
llcp_sock->ssap = nfc_llcp_get_sdp_ssap(local, llcp_sock);
if (llcp_sock->ssap == LLCP_SAP_MAX) {
nfc_llcp_local_put(llcp_sock->local);
kfree(llcp_sock->service_name);
llcp_sock->service_name = NULL;
ret = -EADDRINUSE;
goto put_dev;
}
llcp_sock->reserved_ssap = llcp_sock->ssap;
nfc_llcp_sock_link(&local->sockets, sk);
pr_debug("Socket bound to SAP %d\n", llcp_sock->ssap);
sk->sk_state = LLCP_BOUND;
put_dev:
nfc_put_device(dev);
error:
release_sock(sk);
return ret;
}

static int exif_process_IFD_TAG(image_info_type *ImageInfo, char *dir_entry, char *offset_base, size_t IFDlength, size_t displacement, int section_index, int ReadNextIFD, tag_table_type tag_table)
{
size_t length;
int tag, format, components;
char *value_ptr, tagname[64], cbuf[32], *outside=NULL;
size_t byte_count, offset_val, fpos, fgot;
int64_t byte_count_signed;
xp_field_type *tmp_xp;
#ifdef EXIF_DEBUG
char *dump_data;
int dump_free;
#endif 
if (ImageInfo->ifd_nesting_level > MAX_IFD_NESTING_LEVEL) {
exif_error_docref("exif_read_data#error_ifd" EXIFERR_CC, ImageInfo, E_WARNING, "corrupt EXIF header: maximum directory nesting level reached");
return FALSE;
}
ImageInfo->ifd_nesting_level++;
tag = php_ifd_get16u(dir_entry, ImageInfo->motorola_intel);
format = php_ifd_get16u(dir_entry+2, ImageInfo->motorola_intel);
components = php_ifd_get32u(dir_entry+4, ImageInfo->motorola_intel);
if (!format || format > NUM_FORMATS) {
exif_error_docref("exif_read_data#error_ifd" EXIFERR_CC, ImageInfo, E_WARNING, "Process tag(x%04X=%s): Illegal format code 0x%04X, suppose BYTE", tag, exif_get_tagname(tag, tagname, -12, tag_table), format);
format = TAG_FMT_BYTE;
}
if (components <= 0) {
exif_error_docref("exif_read_data#error_ifd" EXIFERR_CC, ImageInfo, E_WARNING, "Process tag(x%04X=%s): Illegal components(%d)", tag, exif_get_tagname(tag, tagname, -12, tag_table), components);
return FALSE;
}
byte_count_signed = (int64_t)components * php_tiff_bytes_per_format[format];
if (byte_count_signed < 0 || (byte_count_signed > INT32_MAX)) {
exif_error_docref("exif_read_data#error_ifd" EXIFERR_CC, ImageInfo, E_WARNING, "Process tag(x%04X=%s): Illegal byte_count", tag, exif_get_tagname(tag, tagname, -12, tag_table));
return FALSE;
}
byte_count = (size_t)byte_count_signed;
if (byte_count > 4) {
offset_val = php_ifd_get32u(dir_entry+8, ImageInfo->motorola_intel);
value_ptr = offset_base+offset_val;
if (byte_count > IFDlength || offset_val > IFDlength-byte_count || value_ptr < dir_entry || offset_val < (size_t)(dir_entry-offset_base)) {
if (byte_count > ImageInfo->FileSize || offset_val>ImageInfo->FileSize-byte_count || (ImageInfo->FileType!=IMAGE_FILETYPE_TIFF_II && ImageInfo->FileType!=IMAGE_FILETYPE_TIFF_MM && ImageInfo->FileType!=IMAGE_FILETYPE_JPEG)) {
if (value_ptr < dir_entry) {
exif_error_docref("exif_read_data#error_ifd" EXIFERR_CC, ImageInfo, E_WARNING, "Process tag(x%04X=%s): Illegal pointer offset(x%04X < x%04X)", tag, exif_get_tagname(tag, tagname, -12, tag_table), offset_val, dir_entry);
} else {
exif_error_docref("exif_read_data#error_ifd" EXIFERR_CC, ImageInfo, E_WARNING, "Process tag(x%04X=%s): Illegal pointer offset(x%04X + x%04X = x%04X > x%04X)", tag, exif_get_tagname(tag, tagname, -12, tag_table), offset_val, byte_count, offset_val+byte_count, IFDlength);
}
return FALSE;
}
if (byte_count>sizeof(cbuf)) {
value_ptr = safe_emalloc(byte_count, 1, 0);
outside = value_ptr;
} else {
memset(&cbuf, 0, sizeof(cbuf));
value_ptr = cbuf;
}
fpos = php_stream_tell(ImageInfo->infile);
php_stream_seek(ImageInfo->infile, displacement+offset_val, SEEK_SET);
fgot = php_stream_tell(ImageInfo->infile);
if (fgot!=displacement+offset_val) {
EFREE_IF(outside);
exif_error_docref(NULL EXIFERR_CC, ImageInfo, E_WARNING, "Wrong file pointer: 0x%08X != 0x%08X", fgot, displacement+offset_val);
return FALSE;
}
fgot = php_stream_read(ImageInfo->infile, value_ptr, byte_count);
php_stream_seek(ImageInfo->infile, fpos, SEEK_SET);
if (fgot<byte_count) {
EFREE_IF(outside);
EXIF_ERRLOG_FILEEOF(ImageInfo)
return FALSE;
}
}
} else {
value_ptr = dir_entry+8;
offset_val= value_ptr-offset_base;
}
ImageInfo->sections_found |= FOUND_ANY_TAG;
#ifdef EXIF_DEBUG
dump_data = exif_dump_data(&dump_free, format, components, length, ImageInfo->motorola_intel, value_ptr);
exif_error_docref(NULL EXIFERR_CC, ImageInfo, E_NOTICE, "Process tag(x%04X=%s,@x%04X + x%04X(=%d)): %s%s %s", tag, exif_get_tagname(tag, tagname, -12, tag_table), offset_val+displacement, byte_count, byte_count, (components>1)&&format!=TAG_FMT_UNDEFINED&&format!=TAG_FMT_STRING?"ARRAY OF ":"", exif_get_tagformat(format), dump_data);
if (dump_free) {
efree(dump_data);
}
#endif
if (section_index==SECTION_THUMBNAIL) {
if (!ImageInfo->Thumbnail.data) {
switch(tag) {
case TAG_IMAGEWIDTH:
case TAG_COMP_IMAGE_WIDTH:
ImageInfo->Thumbnail.width = exif_convert_any_to_int(value_ptr, exif_rewrite_tag_format_to_unsigned(format), ImageInfo->motorola_intel);
break;
case TAG_IMAGEHEIGHT:
case TAG_COMP_IMAGE_HEIGHT:
ImageInfo->Thumbnail.height = exif_convert_any_to_int(value_ptr, exif_rewrite_tag_format_to_unsigned(format), ImageInfo->motorola_intel);
break;
case TAG_STRIP_OFFSETS:
case TAG_JPEG_INTERCHANGE_FORMAT:
ImageInfo->Thumbnail.offset = exif_convert_any_to_int(value_ptr, exif_rewrite_tag_format_to_unsigned(format), ImageInfo->motorola_intel);
break;
case TAG_STRIP_BYTE_COUNTS:
if (ImageInfo->FileType == IMAGE_FILETYPE_TIFF_II || ImageInfo->FileType == IMAGE_FILETYPE_TIFF_MM) {
ImageInfo->Thumbnail.filetype = ImageInfo->FileType;
} else {
ImageInfo->Thumbnail.filetype = IMAGE_FILETYPE_TIFF_MM;
}
ImageInfo->Thumbnail.size = exif_convert_any_to_int(value_ptr, exif_rewrite_tag_format_to_unsigned(format), ImageInfo->motorola_intel);
break;
case TAG_JPEG_INTERCHANGE_FORMAT_LEN:
if (ImageInfo->Thumbnail.filetype == IMAGE_FILETYPE_UNKNOWN) {
ImageInfo->Thumbnail.filetype = IMAGE_FILETYPE_JPEG;
ImageInfo->Thumbnail.size = exif_convert_any_to_int(value_ptr, exif_rewrite_tag_format_to_unsigned(format), ImageInfo->motorola_intel);
}
break;
}
}
} else {
if (section_index==SECTION_IFD0 || section_index==SECTION_EXIF)
switch(tag) {
case TAG_COPYRIGHT:
if (byte_count>1 && (length=php_strnlen(value_ptr, byte_count)) > 0) {
if (length<byte_count-1) {
ImageInfo->CopyrightPhotographer  = estrdup(value_ptr);
ImageInfo->CopyrightEditor        = estrndup(value_ptr+length+1, byte_count-length-1);
spprintf(&ImageInfo->Copyright, 0, "%s, %s", ImageInfo->CopyrightPhotographer, ImageInfo->CopyrightEditor);
} else {
ImageInfo->Copyright = estrndup(value_ptr, byte_count);
}
}
break;
case TAG_USERCOMMENT:
EFREE_IF(ImageInfo->UserComment);
ImageInfo->UserComment = NULL;
EFREE_IF(ImageInfo->UserCommentEncoding);
ImageInfo->UserCommentEncoding = NULL;
ImageInfo->UserCommentLength = exif_process_user_comment(ImageInfo, &(ImageInfo->UserComment), &(ImageInfo->UserCommentEncoding), value_ptr, byte_count);
break;
case TAG_XP_TITLE:
case TAG_XP_COMMENTS:
case TAG_XP_AUTHOR:
case TAG_XP_KEYWORDS:
case TAG_XP_SUBJECT:
tmp_xp = (xp_field_type*)safe_erealloc(ImageInfo->xp_fields.list, (ImageInfo->xp_fields.count+1), sizeof(xp_field_type), 0);
ImageInfo->sections_found |= FOUND_WINXP;
ImageInfo->xp_fields.list = tmp_xp;
ImageInfo->xp_fields.count++;
exif_process_unicode(ImageInfo, &(ImageInfo->xp_fields.list[ImageInfo->xp_fields.count-1]), tag, value_ptr, byte_count);
break;
case TAG_FNUMBER:
ImageInfo->ApertureFNumber = (float)exif_convert_any_format(value_ptr, format, ImageInfo->motorola_intel);
break;
case TAG_APERTURE:
case TAG_MAX_APERTURE:
if (ImageInfo->ApertureFNumber == 0) {
ImageInfo->ApertureFNumber
= (float)exp(exif_convert_any_format(value_ptr, format, ImageInfo->motorola_intel)*log(2)*0.5);
}
break;
case TAG_SHUTTERSPEED:
if (ImageInfo->ExposureTime == 0) {
ImageInfo->ExposureTime
= (float)(1/exp(exif_convert_any_format(value_ptr, format, ImageInfo->motorola_intel)*log(2)));
}
break;
case TAG_EXPOSURETIME:
ImageInfo->ExposureTime = -1;
break;
case TAG_COMP_IMAGE_WIDTH:
ImageInfo->ExifImageWidth = exif_convert_any_to_int(value_ptr, exif_rewrite_tag_format_to_unsigned(format), ImageInfo->motorola_intel);
break;
case TAG_FOCALPLANE_X_RES:
ImageInfo->FocalplaneXRes = exif_convert_any_format(value_ptr, format, ImageInfo->motorola_intel);
break;
case TAG_SUBJECT_DISTANCE:
ImageInfo->Distance = (float)exif_convert_any_format(value_ptr, format, ImageInfo->motorola_intel);
break;
case TAG_FOCALPLANE_RESOLUTION_UNIT:
switch((int)exif_convert_any_format(value_ptr, format, ImageInfo->motorola_intel)) {
case 1: ImageInfo->FocalplaneUnits = 25.4; break; 
case 2:
ImageInfo->FocalplaneUnits = 25.4;
break;
case 3: ImageInfo->FocalplaneUnits = 10;   break;  
case 4: ImageInfo->FocalplaneUnits = 1;    break;  
case 5: ImageInfo->FocalplaneUnits = .001; break;  
}
break;
case TAG_SUB_IFD:
if (format==TAG_FMT_IFD) {
exif_error_docref(NULL EXIFERR_CC, ImageInfo, E_NOTICE, "Skip SUB IFD");
}
break;
case TAG_MAKE:
ImageInfo->make = estrndup(value_ptr, byte_count);
break;
case TAG_MODEL:
ImageInfo->model = estrndup(value_ptr, byte_count);
break;
case TAG_MAKER_NOTE:
if (!exif_process_IFD_in_MAKERNOTE(ImageInfo, value_ptr, byte_count, offset_base, IFDlength, displacement)) {
EFREE_IF(outside);
return FALSE;
}
break;
case TAG_EXIF_IFD_POINTER:
case TAG_GPS_IFD_POINTER:
case TAG_INTEROP_IFD_POINTER:
if (ReadNextIFD) {
char *Subdir_start;
int sub_section_index = 0;
switch(tag) {
case TAG_EXIF_IFD_POINTER:
#ifdef EXIF_DEBUG
exif_error_docref(NULL EXIFERR_CC, ImageInfo, E_NOTICE, "Found EXIF");
#endif
ImageInfo->sections_found |= FOUND_EXIF;
sub_section_index = SECTION_EXIF;
break;
case TAG_GPS_IFD_POINTER:
#ifdef EXIF_DEBUG
exif_error_docref(NULL EXIFERR_CC, ImageInfo, E_NOTICE, "Found GPS");
#endif
ImageInfo->sections_found |= FOUND_GPS;
sub_section_index = SECTION_GPS;
break;
case TAG_INTEROP_IFD_POINTER:
#ifdef EXIF_DEBUG
exif_error_docref(NULL EXIFERR_CC, ImageInfo, E_NOTICE, "Found INTEROPERABILITY");
#endif
ImageInfo->sections_found |= FOUND_INTEROP;
sub_section_index = SECTION_INTEROP;
break;
}
Subdir_start = offset_base + php_ifd_get32u(value_ptr, ImageInfo->motorola_intel);
if (Subdir_start < offset_base || Subdir_start > offset_base+IFDlength) {
exif_error_docref("exif_read_data#error_ifd" EXIFERR_CC, ImageInfo, E_WARNING, "Illegal IFD Pointer");
return FALSE;
}
if (!exif_process_IFD_in_JPEG(ImageInfo, Subdir_start, offset_base, IFDlength, displacement, sub_section_index, tag)) {
return FALSE;
}
#ifdef EXIF_DEBUG
exif_error_docref(NULL EXIFERR_CC, ImageInfo, E_NOTICE, "Subsection %s done", exif_get_sectionname(sub_section_index));
#endif
}
}
}
exif_iif_add_tag(ImageInfo, section_index, exif_get_tagname(tag, tagname, sizeof(tagname), tag_table), tag, format, components, value_ptr);
EFREE_IF(outside);
return TRUE;
}

static int
_gd2GetHeader (gdIOCtxPtr in, int *sx, int *sy,
int *cs, int *vers, int *fmt, int *ncx, int *ncy,
t_chunk_info ** chunkIdx)
{
int i;
int ch;
char id[5];
t_chunk_info *cidx;
int sidx;
int nc;
GD2_DBG (printf ("Reading gd2 header info\n"));
for (i = 0; i < 4; i++) {
ch = gdGetC (in);
if (ch == EOF) {
goto fail1;
};
id[i] = ch;
};
id[4] = 0;
GD2_DBG (printf ("Got file code: %s\n", id));
if (strcmp (id, GD2_ID) != 0) {
GD2_DBG (printf ("Not a valid gd2 file\n"));
goto fail1;
};
if (gdGetWord (vers, in) != 1) {
goto fail1;
};
GD2_DBG (printf ("Version: %d\n", *vers));
if ((*vers != 1) && (*vers != 2)) {
GD2_DBG (printf ("Bad version: %d\n", *vers));
goto fail1;
};
if (!gdGetWord (sx, in)) {
GD2_DBG (printf ("Could not get x-size\n"));
goto fail1;
}
if (!gdGetWord (sy, in)) {
GD2_DBG (printf ("Could not get y-size\n"));
goto fail1;
}
GD2_DBG (printf ("Image is %dx%d\n", *sx, *sy));
if (gdGetWord (cs, in) != 1) {
goto fail1;
};
GD2_DBG (printf ("ChunkSize: %d\n", *cs));
if ((*cs < GD2_CHUNKSIZE_MIN) || (*cs > GD2_CHUNKSIZE_MAX)) {
GD2_DBG (printf ("Bad chunk size: %d\n", *cs));
goto fail1;
};
if (gdGetWord (fmt, in) != 1) {
goto fail1;
};
GD2_DBG (printf ("Format: %d\n", *fmt));
if ((*fmt != GD2_FMT_RAW) && (*fmt != GD2_FMT_COMPRESSED) &&
(*fmt != GD2_FMT_TRUECOLOR_RAW) &&
(*fmt != GD2_FMT_TRUECOLOR_COMPRESSED)) {
GD2_DBG (printf ("Bad data format: %d\n", *fmt));
goto fail1;
};
if (gdGetWord (ncx, in) != 1) {
goto fail1;
};
GD2_DBG (printf ("%d Chunks Wide\n", *ncx));
if (gdGetWord (ncy, in) != 1) {
goto fail1;
};
GD2_DBG (printf ("%d Chunks vertically\n", *ncy));
if (gd2_compressed (*fmt)) {
nc = (*ncx) * (*ncy);
GD2_DBG (printf ("Reading %d chunk index entries\n", nc));
if (overflow2(sizeof(t_chunk_info), nc)) {
goto fail1;
}
sidx = sizeof (t_chunk_info) * nc;
if (sidx <= 0) {
goto fail1;
}
cidx = gdCalloc (sidx, 1);
if (cidx == NULL) {
goto fail1;
}
for (i = 0; i < nc; i++) {
if (gdGetInt (&cidx[i].offset, in) != 1) {
goto fail2;
};
if (gdGetInt (&cidx[i].size, in) != 1) {
goto fail2;
};
if (cidx[i].offset < 0 || cidx[i].size < 0)
goto fail2;
};
*chunkIdx = cidx;
};
GD2_DBG (printf ("gd2 header complete\n"));
return 1;
fail2:
gdFree(cidx);
fail1:
return 0;
}

R_API void r_core_fortune_list(RCore *core) {
const char *types = (char *)r_config_get (core->config, "cfg.fortunes.type");
int i, j;
for (i = 0; i < R_ARRAY_SIZE (fortunes); i++) {
if (strstr (types, fortunes[i])) {
