void Compute(OpKernelContext* context) override {
const Tensor& input = context->input(0);
const TensorShape& input_shape = input.shape();
const int32_t input_dims = input_shape.dims();
const Tensor& segment_id = context->input(1);
const TensorShape& segment_id_shape = segment_id.shape();
const int32_t segment_dims = segment_id_shape.dims();
const Tensor& num_segments_tensor = context->input(2);
OP_REQUIRES(context, num_segments_tensor.NumElements() != 0,
errors::InvalidArgument("Number of segments cannot be empty."));
auto num_segments = num_segments_tensor.scalar<NUM_SEGMENTS_TYPE>()();
OP_REQUIRES(
context, num_segments >= 0,
errors::InvalidArgument(
"Number of segments must be non-negative but got ", num_segments));
OP_REQUIRES(context, segment_dims != 0,
errors::InvalidArgument("Segment_id cannot have rank 0"));
OP_REQUIRES(
context, segment_dims <= input_dims,
errors::OutOfRange("Invalid segment_id rank ", segment_dims,
" for input with ", input_dims, " dimension(s)"));
for (auto i = 0; i < segment_dims; i++) {
OP_REQUIRES(
context, segment_id_shape.dim_size(i) == input_shape.dim_size(i),
errors::InvalidArgument(
"Segment dimension is ", segment_id_shape.dim_size(i),
" while input dimension is ", input_dims, " in rank ", i));
}
Tensor* output_tensor = nullptr;
TensorShape output_shape =
GetOutputShape(input_shape, segment_id_shape, num_segments);
OP_REQUIRES_OK(context, context->allocate_output("output", output_shape,
&output_tensor));
auto output_flat = output_tensor->flat<tstring>();
auto flat_segment_id = segment_id.flat<INDICES_TYPE>();
auto flat_input = input.flat<tstring>();
for (int i = 0; i < flat_segment_id.size(); i++) {
OP_REQUIRES(
context,
((flat_segment_id(i) < num_segments) && (flat_segment_id(i) >= 0)),
errors::InvalidArgument(
"segment_ids are not allowed to exceed num_segments or"
" to have negative values."));
}
int64_t big_stride;
int64_t small_stride;
std::tie(big_stride, small_stride) =
GetStrides<INDICES_TYPE>(input_shape, segment_id_shape);
auto relative_offset_set =
GetFlattenedRelativeOffsets<INDICES_TYPE>(small_stride, big_stride);
for (auto start_offset = 0; start_offset < big_stride; start_offset++) {
for (auto i = 0; i < relative_offset_set.size(); i++) {
auto output_index = start_offset + flat_segment_id(i) * big_stride;
auto offset = start_offset + relative_offset_set[i];
if (output_flat(output_index).length() != 0)
output_flat(output_index).append(separator_.c_str());
output_flat(output_index).append(flat_input(offset));
}
}
}

char_u *
eval_next_non_blank(char_u *arg, evalarg_T *evalarg, int *getnext)
{
char_u *p = skipwhite(arg);
*getnext = FALSE;
if (in_vim9script()
&& evalarg != NULL
&& (evalarg->eval_cookie != NULL || evalarg->eval_cctx != NULL
|| *p == NL)
&& (*p == NUL || *p == NL
|| (vim9_comment_start(p) && VIM_ISWHITE(p[-1]))))
{
char_u *next;
if (*p == NL)
next = newline_skip_comments(p);
else if (evalarg->eval_cookie != NULL)
next = getline_peek_skip_comments(evalarg);
else
next = peek_next_line_from_context(evalarg->eval_cctx);
if (next != NULL)
{
*getnext = TRUE;
return skipwhite(next);
}
}
return p;
}

int gx_scan_convert_app(gx_device     * restrict pdev,
gx_path       * restrict path,
const gs_fixed_rect * restrict clip,
gx_edgebuffer * restrict edgebuffer,
fixed                    fixed_flat)
{
gs_fixed_rect  ibox;
int            scanlines;
const subpath *psub;
int           *index;
int           *table;
int            i;
cursor         cr;
int            code;
edgebuffer->index = NULL;
edgebuffer->table = NULL;
if (path->first_subpath == NULL)
return 0;
code = make_bbox(path, clip, &ibox, 0);
if (code < 0)
return code;
if (ibox.q.y <= ibox.p.y)
return 0;
code = make_table_app(pdev, path, &ibox, &scanlines, &index, &table);
if (code < 0)
return code;
cr.scanlines = scanlines;
cr.index     = index;
cr.table     = table;
cr.base      = ibox.p.y;
for (psub = path->first_subpath; psub != 0;) {
const segment *pseg = (const segment *)psub;
fixed ex = pseg->pt.x;
fixed ey = pseg->pt.y;
fixed ix = ex;
fixed iy = ey;
fixed sx, sy;
cr.left = cr.right = ex;
cr.y = ey;
cr.d = DIRN_UNSET;
cr.first = 1;
cr.saved = 0;
while ((pseg = pseg->next) != 0 &&
pseg->type != s_start
) {
sx = ex;
sy = ey;
ex = pseg->pt.x;
ey = pseg->pt.y;
switch (pseg->type) {
default:
case s_start: 
case s_dash:  
assert("This should never happen" == NULL);
break;
case s_curve: {
const curve_segment *const pcur = (const curve_segment *)pseg;
int k = gx_curve_log2_samples(sx, sy, pcur, fixed_flat);
mark_curve_app(&cr, sx, sy, pcur->p1.x, pcur->p1.y, pcur->p2.x, pcur->p2.y, ex, ey, k);
break;
}
case s_gap:
case s_line:
case s_line_close:
mark_line_app(&cr, sx, sy, ex, ey);
break;
}
}
mark_line_app(&cr, ex, ey, ix, iy);
cursor_flush(&cr, ex);
psub = (const subpath *)pseg;
}
edgebuffer->base   = ibox.p.y;
edgebuffer->height = scanlines;
edgebuffer->xmin   = ibox.p.x;
edgebuffer->xmax   = ibox.q.x;
edgebuffer->index  = index;
edgebuffer->table  = table;
#ifdef DEBUG_SCAN_CONVERTER
if (debugging_scan_converter) {
dlprintf("Before sorting:\n");
gx_edgebuffer_print_app(edgebuffer);
}
#endif
for (i=0; i < scanlines; i++) {
int *row = &table[index[i]];
int  rowlen = *row++;
if (rowlen <= 6) {
int j, k;
for (j = 0; j < rowlen-1; j++) {
int * restrict t = &row[j<<1];
for (k = j+1; k < rowlen; k++) {
int * restrict s = &row[k<<1];
int tmp;
if (t[0] < s[0])
continue;
if (t[0] > s[0])
goto swap01;
if (t[1] <= s[1])
continue;
if (0) {
swap01:
tmp = t[0], t[0] = s[0], s[0] = tmp;
}
tmp = t[1], t[1] = s[1], s[1] = tmp;
}
}
} else
qsort(row, rowlen, 2*sizeof(int), edgecmp);
}
return 0;
}

static void scalar32_min_max_or(struct bpf_reg_state *dst_reg,
struct bpf_reg_state *src_reg)
{
bool src_known = tnum_subreg_is_const(src_reg->var_off);
bool dst_known = tnum_subreg_is_const(dst_reg->var_off);
struct tnum var32_off = tnum_subreg(dst_reg->var_off);
s32 smin_val = src_reg->smin_value;
u32 umin_val = src_reg->umin_value;
if (src_known && dst_known)
return;
dst_reg->u32_min_value = max(dst_reg->u32_min_value, umin_val);
dst_reg->u32_max_value = var32_off.value | var32_off.mask;
if (dst_reg->s32_min_value < 0 || smin_val < 0) {
dst_reg->s32_min_value = S32_MIN;
dst_reg->s32_max_value = S32_MAX;
} else {
dst_reg->s32_min_value = dst_reg->umin_value;
dst_reg->s32_max_value = dst_reg->umax_value;
}
}

