ret_t
cherokee_services_client_spawn (cherokee_buffer_t         *binary,
cherokee_buffer_t         *user,
uid_t                      uid,
gid_t                      gid,
cherokee_buffer_t         *chroot,
cherokee_buffer_t         *chdir,
int                        env_inherited,
char                     **envp,
cherokee_logger_writer_t  *error_writer,
pid_t                     *pid_ret,
cherokee_services_fdmap_t *fd_map)
{
char             **n;
int                pid_new;
int                k;
int                phase;
int                envs     = 0;
ret_t              ret;
cherokee_buffer_t  tmp      = CHEROKEE_BUF_INIT;
#define ALIGN4(buf)                                    \
while (buf.len & 0x3) {                        \
cherokee_buffer_add_char (&buf, '\0'); \
}
if (_fd == -1)
{
TRACE (ENTRIES, "Spawner is not active. Returning: %s\n", binary->buf);
return ret_deny;
}
k = CHEROKEE_MUTEX_TRY_LOCK (&client_mutex);
if (k) {
return ret_eagain;
}
cherokee_buffer_ensure_size (&tmp, SERVICES_MESSAGE_MAX_SIZE);
phase = (int)service_id_spawn_request;
cherokee_buffer_add        (&tmp, (char *)&phase, sizeof(int));
phase = service_magic_executable;
cherokee_buffer_add        (&tmp, (char *)&phase, sizeof(int));
cherokee_buffer_add        (&tmp, (char *)&binary->len,   sizeof(int));
cherokee_buffer_add_buffer (&tmp, binary);
cherokee_buffer_add_char   (&tmp, '\0');
ALIGN4 (tmp);
phase = service_magic_uid_gid;
cherokee_buffer_add        (&tmp, (char *)&phase, sizeof(int));
cherokee_buffer_add        (&tmp, (char *)&user->len, sizeof(int));
cherokee_buffer_add_buffer (&tmp, user);
cherokee_buffer_add_char   (&tmp, '\0');
ALIGN4(tmp);
cherokee_buffer_add (&tmp, (char *)&uid, sizeof(uid_t));
cherokee_buffer_add (&tmp, (char *)&gid, sizeof(gid_t));
phase = service_magic_chroot;
cherokee_buffer_add (&tmp, (char *)&phase, sizeof(int));
cherokee_buffer_add        (&tmp, (char *)&chroot->len, sizeof(int));
cherokee_buffer_add_buffer (&tmp, chroot);
cherokee_buffer_add_char   (&tmp, '\0');
ALIGN4(tmp);
phase = service_magic_chdir;
cherokee_buffer_add (&tmp, (char *)&phase, sizeof(int));
cherokee_buffer_add        (&tmp, (char *)&chdir->len, sizeof(int));
cherokee_buffer_add_buffer (&tmp, chdir);
cherokee_buffer_add_char   (&tmp, '\0');
ALIGN4(tmp);
phase = service_magic_environment;
cherokee_buffer_add (&tmp, (char *)&phase, sizeof(int));
for (n = envp; *n; n++) {
envs ++;
}
cherokee_buffer_add (&tmp, (char *)&env_inherited, sizeof(int));
cherokee_buffer_add (&tmp, (char *)&envs, sizeof(int));
for (n = envp; *n; n++) {
int len = strlen(*n);
cherokee_buffer_add      (&tmp, (char *)&len, sizeof(int));
cherokee_buffer_add      (&tmp, *n, len);
cherokee_buffer_add_char (&tmp, '\0');
ALIGN4(tmp);
}
phase = service_magic_error_log;
cherokee_buffer_add (&tmp, (char *)&phase, sizeof(int));
write_logger (&tmp, error_writer);
ALIGN4 (tmp);
phase = service_magic_pid;
cherokee_buffer_add (&tmp, (char *)&phase, sizeof(int));
cherokee_buffer_add (&tmp, (char *)pid_ret, sizeof(int));
phase = service_magic_fdmap;
cherokee_buffer_add (&tmp, (char *)&phase, sizeof(int));
if (fd_map != NULL) {
int fd = 3;
cherokee_buffer_add (&tmp, (char *)&fd,sizeof(int));
fd = 0;
cherokee_buffer_add (&tmp, (char *)&fd, sizeof(int));
fd = 1;
cherokee_buffer_add (&tmp, (char *)&fd, sizeof(int));
fd = 2;
cherokee_buffer_add (&tmp, (char *)&fd, sizeof(int));
} else {
phase = 0;
cherokee_buffer_add (&tmp, (char *)&phase, sizeof(int));
}
if (unlikely (tmp.len > SERVICES_MESSAGE_MAX_SIZE)) {
goto error;
}
ret = cherokee_services_send(_fd, &tmp, fd_map);
cherokee_buffer_mrproper (&tmp);
if (ret != ret_ok) {
goto error;
}
cherokee_buffer_ensure_size (&tmp, SERVICES_MESSAGE_MAX_SIZE);
ret = cherokee_services_receive(_fd, &tmp, NULL);
if (ret != ret_ok) {
goto error;
}
if (tmp.len != (sizeof(int) * 2)) {
goto error;
}
if (*((int *)tmp.buf) != service_id_spawn_reply)
goto error;
pid_new = *(((int *)tmp.buf)+1);
if (pid_new == -1) {
TRACE(ENTRIES, "Could not get the PID of: '%s'\n", binary->buf);
goto error;
}
if (*pid_ret == pid_new) {
TRACE(ENTRIES, "Could not the new PID, previously it was %d\n", *pid_ret);
goto error;
}
TRACE(ENTRIES, "Successfully launched PID=%d\n", pid_new);
*pid_ret = pid_new;
CHEROKEE_MUTEX_UNLOCK (&client_mutex);
return ret_ok;
error:
CHEROKEE_MUTEX_UNLOCK (&client_mutex);
return ret_error;
}

static char *
getString(struct SWF_ACTIONPUSHPARAM *act)
{
char *t;
#ifdef DEBUG
printf("*getString* type=%d\n",act->Type);
#endif
switch( act->Type ) 
{
case PUSH_STRING: 
if (!act->p.String) 
{
SWF_warn("WARNING: Call to getString with NULL string.\n");
break;
}
t=malloc(strlen(act->p.String)+3); 
strcpy(t,"'");
strcat(t,act->p.String);
strcat(t,"'");
return t;
case PUSH_NULL: 
return "null";
case PUSH_UNDEF: 
return "undefined";
case PUSH_REGISTER: 
if( regs[act->p.RegisterNumber] &&
regs[act->p.RegisterNumber]->Type != 4 &&
regs[act->p.RegisterNumber]->Type != 7 )
{
return getName(regs[act->p.RegisterNumber]);
}
else
{
t=malloc(5); 
sprintf(t,"R%d", act->p.RegisterNumber );
return t;
}
case PUSH_BOOLEAN: 
if( act->p.Boolean )
return "true";
else
return "false";
case PUSH_DOUBLE: 
{
char length_finder[1];
int needed_length = snprintf(length_finder, 1, "%g", act->p.Double) + 1;
if (needed_length <= 0)
{
SWF_warn("WARNING: could not evaluate size of buffer (memory issue ?).\n");
break;
}
t = malloc(needed_length);
sprintf(t, "%g", act->p.Double );
return t;
}
case PUSH_INT: 
t=malloc(10); 
sprintf(t,"%ld", act->p.Integer );
return t;
case PUSH_CONSTANT: 
if (act->p.Constant8 > poolcounter)
{
SWF_warn("WARNING: retrieving constants not present in the pool.\n");
break;
}
t=malloc(strlenext(pool[act->p.Constant8])+3); 
strcpy(t,"'");
strcatext(t,pool[act->p.Constant8]);
strcat(t,"'");
return t;
case PUSH_CONSTANT16: 
if (act->p.Constant16 > poolcounter)
{
SWF_warn("WARNING: retrieving constants not present in the pool.\n");
break;
}
t=malloc(strlenext(pool[act->p.Constant16])+3); 
strcpy(t,"'");
strcatext(t,pool[act->p.Constant16]);
strcat(t,"'");
return t;
case 12:
case 11: 
case PUSH_VARIABLE: 
return act->p.String;
default: 
fprintf (stderr,"  Can't get string for type: %d\n", act->Type);
break;
}
t = malloc(sizeof(char));
strcpyext(t,"");
return t;
}

static int core2_vpmu_do_wrmsr(unsigned int msr, uint64_t msr_content,
uint64_t supported)
{
int i, tmp;
int type = -1, index = -1;
struct vcpu *v = current;
struct vpmu_struct *vpmu = vcpu_vpmu(v);
struct xen_pmu_intel_ctxt *core2_vpmu_cxt;
uint64_t *enabled_cntrs;
if ( !core2_vpmu_msr_common_check(msr, &type, &index) )
{
if ( msr == MSR_IA32_DEBUGCTLMSR )
{
supported |= IA32_DEBUGCTLMSR_TR | IA32_DEBUGCTLMSR_BTS |
IA32_DEBUGCTLMSR_BTINT;
if ( cpu_has(&current_cpu_data, X86_FEATURE_DSCPL) )
supported |= IA32_DEBUGCTLMSR_BTS_OFF_OS |
IA32_DEBUGCTLMSR_BTS_OFF_USR;
if ( !(msr_content & ~supported) &&
vpmu_is_set(vpmu, VPMU_CPU_HAS_BTS) )
return 0;
if ( (msr_content & supported) &&
!vpmu_is_set(vpmu, VPMU_CPU_HAS_BTS) )
printk(XENLOG_G_WARNING
"%pv: Debug Store unsupported on this CPU\n",
current);
}
return -EINVAL;
}
ASSERT(!supported);
if ( (type == MSR_TYPE_COUNTER) && (msr_content & fixed_counters_mask) )
return -EINVAL;
core2_vpmu_cxt = vpmu->context;
enabled_cntrs = vpmu->priv_context;
switch ( msr )
{
case MSR_CORE_PERF_GLOBAL_OVF_CTRL:
if ( msr_content & global_ovf_ctrl_mask )
return -EINVAL;
core2_vpmu_cxt->global_status &= ~msr_content;
wrmsrl(MSR_CORE_PERF_GLOBAL_OVF_CTRL, msr_content);
return 0;
case MSR_CORE_PERF_GLOBAL_STATUS:
gdprintk(XENLOG_INFO, "Can not write readonly MSR: "
"MSR_PERF_GLOBAL_STATUS(0x38E)!\n");
return -EINVAL;
case MSR_IA32_PEBS_ENABLE:
if ( vpmu_features & (XENPMU_FEATURE_IPC_ONLY |
XENPMU_FEATURE_ARCH_ONLY) )
return -EINVAL;
if ( msr_content )
return -EINVAL;
return 0;
case MSR_IA32_DS_AREA:
if ( !(vpmu_features & XENPMU_FEATURE_INTEL_BTS) )
return -EINVAL;
if ( vpmu_is_set(vpmu, VPMU_CPU_HAS_DS) )
{
if ( !(is_hvm_vcpu(v) ? is_canonical_address(msr_content)
: __addr_ok(msr_content)) )
{
gdprintk(XENLOG_WARNING,
"Illegal address for IA32_DS_AREA: %#" PRIx64 "x\n",
msr_content);
return -EINVAL;
}
core2_vpmu_cxt->ds_area = msr_content;
break;
}
gdprintk(XENLOG_WARNING, "Guest setting of DTS is ignored.\n");
return 0;
case MSR_CORE_PERF_GLOBAL_CTRL:
if ( msr_content & global_ctrl_mask )
return -EINVAL;
core2_vpmu_cxt->global_ctrl = msr_content;
break;
case MSR_CORE_PERF_FIXED_CTR_CTRL:
if ( msr_content & fixed_ctrl_mask )
return -EINVAL;
if ( is_hvm_vcpu(v) )
vmx_read_guest_msr(v, MSR_CORE_PERF_GLOBAL_CTRL,
&core2_vpmu_cxt->global_ctrl);
else
rdmsrl(MSR_CORE_PERF_GLOBAL_CTRL, core2_vpmu_cxt->global_ctrl);
*enabled_cntrs &= ~(((1ULL << fixed_pmc_cnt) - 1) << 32);
if ( msr_content != 0 )
{
u64 val = msr_content;
for ( i = 0; i < fixed_pmc_cnt; i++ )
{
if ( val & 3 )
*enabled_cntrs |= (1ULL << 32) << i;
val >>= FIXED_CTR_CTRL_BITS;
}
}
core2_vpmu_cxt->fixed_ctrl = msr_content;
break;
default:
tmp = msr - MSR_P6_EVNTSEL(0);
if ( tmp >= 0 && tmp < arch_pmc_cnt )
{
bool_t blocked = 0;
uint64_t umaskevent = msr_content & MSR_IA32_CMT_EVTSEL_UE_MASK;
struct xen_pmu_cntr_pair *xen_pmu_cntr_pair =
vpmu_reg_pointer(core2_vpmu_cxt, arch_counters);
if ( msr_content & ARCH_CTRL_MASK )
return -EINVAL;
if ( vpmu_features & (XENPMU_FEATURE_IPC_ONLY |
XENPMU_FEATURE_ARCH_ONLY) )
{
blocked = 1;
switch ( umaskevent )
{
case 0x003c:
case 0x013c:
case 0x00c0:
blocked = 0;
break;
}
}
if ( vpmu_features & XENPMU_FEATURE_ARCH_ONLY )
{
switch ( umaskevent )
{
case 0x4f2e:
case 0x412e:
case 0x00c4:
case 0x00c5:
blocked = 0;
break;
}
}
if ( blocked )
return -EINVAL;
if ( is_hvm_vcpu(v) )
vmx_read_guest_msr(v, MSR_CORE_PERF_GLOBAL_CTRL,
&core2_vpmu_cxt->global_ctrl);
else
rdmsrl(MSR_CORE_PERF_GLOBAL_CTRL, core2_vpmu_cxt->global_ctrl);
if ( msr_content & ARCH_CNTR_ENABLED )
*enabled_cntrs |= 1ULL << tmp;
else
*enabled_cntrs &= ~(1ULL << tmp);
xen_pmu_cntr_pair[tmp].control = msr_content;
}
}
if ( type != MSR_TYPE_GLOBAL )
wrmsrl(msr, msr_content);
else
{
if ( is_hvm_vcpu(v) )
vmx_write_guest_msr(v, MSR_CORE_PERF_GLOBAL_CTRL, msr_content);
else
wrmsrl(MSR_CORE_PERF_GLOBAL_CTRL, msr_content);
}
if ( (core2_vpmu_cxt->global_ctrl & *enabled_cntrs) ||
(core2_vpmu_cxt->ds_area != 0) )
vpmu_set(vpmu, VPMU_RUNNING);
else
vpmu_reset(vpmu, VPMU_RUNNING);
return 0;
}

