}
if (sk->sk_state == TCP_CLOSE || sk->sk_state == TCP_CLOSING) {
if (!(sk->sk_shutdown & SEND_SHUTDOWN))
mask |= EPOLLOUT | EPOLLWRNORM;
}
release_sock(sk);
}
return mask;
}

static int read_entry(
git_index_entry **out,
size_t *out_size,
git_index *index,
const void *buffer,
size_t buffer_size,
const char *last)
{
size_t path_length, entry_size;
const char *path_ptr;
struct entry_short source;
git_index_entry entry = {{0}};
bool compressed = index->version >= INDEX_VERSION_NUMBER_COMP;
char *tmp_path = NULL;
if (INDEX_FOOTER_SIZE + minimal_entry_size > buffer_size)
return -1;
memcpy(&source, buffer, sizeof(struct entry_short));
entry.ctime.seconds = (git_time_t)ntohl(source.ctime.seconds);
entry.ctime.nanoseconds = ntohl(source.ctime.nanoseconds);
entry.mtime.seconds = (git_time_t)ntohl(source.mtime.seconds);
entry.mtime.nanoseconds = ntohl(source.mtime.nanoseconds);
entry.dev = ntohl(source.dev);
entry.ino = ntohl(source.ino);
entry.mode = ntohl(source.mode);
entry.uid = ntohl(source.uid);
entry.gid = ntohl(source.gid);
entry.file_size = ntohl(source.file_size);
git_oid_cpy(&entry.id, &source.oid);
entry.flags = ntohs(source.flags);
if (entry.flags & GIT_IDXENTRY_EXTENDED) {
uint16_t flags_raw;
size_t flags_offset;
flags_offset = offsetof(struct entry_long, flags_extended);
memcpy(&flags_raw, (const char *) buffer + flags_offset,
sizeof(flags_raw));
flags_raw = ntohs(flags_raw);
memcpy(&entry.flags_extended, &flags_raw, sizeof(flags_raw));
path_ptr = (const char *) buffer + offsetof(struct entry_long, path);
} else
path_ptr = (const char *) buffer + offsetof(struct entry_short, path);
if (!compressed) {
path_length = entry.flags & GIT_IDXENTRY_NAMEMASK;
if (path_length == 0xFFF) {
const char *path_end;
path_end = memchr(path_ptr, '\0', buffer_size);
if (path_end == NULL)
return -1;
path_length = path_end - path_ptr;
}
entry_size = index_entry_size(path_length, 0, entry.flags);
entry.path = (char *)path_ptr;
} else {
size_t varint_len, last_len, prefix_len, suffix_len, path_len;
uintmax_t strip_len;
strip_len = git_decode_varint((const unsigned char *)path_ptr, &varint_len);
last_len = strlen(last);
if (varint_len == 0 || last_len < strip_len)
return index_error_invalid("incorrect prefix length");
prefix_len = last_len - strip_len;
suffix_len = strlen(path_ptr + varint_len);
GITERR_CHECK_ALLOC_ADD(&path_len, prefix_len, suffix_len);
GITERR_CHECK_ALLOC_ADD(&path_len, path_len, 1);
tmp_path = git__malloc(path_len);
GITERR_CHECK_ALLOC(tmp_path);
memcpy(tmp_path, last, prefix_len);
memcpy(tmp_path + prefix_len, path_ptr + varint_len, suffix_len + 1);
entry_size = index_entry_size(suffix_len, varint_len, entry.flags);
entry.path = tmp_path;
}
if (entry_size == 0)
return -1;
if (INDEX_FOOTER_SIZE + entry_size > buffer_size)
return -1;
if (index_entry_dup(out, index, &entry) < 0) {
git__free(tmp_path);
return -1;
}
git__free(tmp_path);
*out_size = entry_size;
return 0;
}

static bfd_boolean
assign_file_positions_for_non_load_sections (bfd *abfd,
struct bfd_link_info *link_info)
{
const struct elf_backend_data *bed = get_elf_backend_data (abfd);
Elf_Internal_Shdr **i_shdrpp;
Elf_Internal_Shdr **hdrpp, **end_hdrpp;
Elf_Internal_Phdr *phdrs;
Elf_Internal_Phdr *p;
struct elf_segment_map *m;
struct elf_segment_map *hdrs_segment;
bfd_vma filehdr_vaddr, filehdr_paddr;
bfd_vma phdrs_vaddr, phdrs_paddr;
file_ptr off;
unsigned int count;
i_shdrpp = elf_elfsections (abfd);
end_hdrpp = i_shdrpp + elf_numsections (abfd);
off = elf_next_file_pos (abfd);
for (hdrpp = i_shdrpp + 1; hdrpp < end_hdrpp; hdrpp++)
{
Elf_Internal_Shdr *hdr;
hdr = *hdrpp;
if (hdr->bfd_section != NULL
&& (hdr->bfd_section->filepos != 0
|| (hdr->sh_type == SHT_NOBITS
&& hdr->contents == NULL)))
BFD_ASSERT (hdr->sh_offset == hdr->bfd_section->filepos);
else if ((hdr->sh_flags & SHF_ALLOC) != 0)
{
if (hdr->sh_size != 0)
_bfd_error_handler
(_("%pB: warning: allocated section `%s' not in segment"),
abfd,
(hdr->bfd_section == NULL
? "*unknown*"
: hdr->bfd_section->name));
if ((abfd->flags & D_PAGED) != 0 && hdr->sh_size != 0)
off += vma_page_aligned_bias (hdr->sh_addr, off,
bed->maxpagesize);
else
off += vma_page_aligned_bias (hdr->sh_addr, off,
hdr->sh_addralign);
off = _bfd_elf_assign_file_position_for_section (hdr, off,
FALSE);
}
else if (((hdr->sh_type == SHT_REL || hdr->sh_type == SHT_RELA)
&& hdr->bfd_section == NULL)
|| (hdr->bfd_section != NULL
&& (hdr->bfd_section->flags & SEC_ELF_COMPRESS))
|| hdr == i_shdrpp[elf_onesymtab (abfd)]
|| (elf_symtab_shndx_list (abfd) != NULL
&& hdr == i_shdrpp[elf_symtab_shndx_list (abfd)->ndx])
|| hdr == i_shdrpp[elf_strtab_sec (abfd)]
|| hdr == i_shdrpp[elf_shstrtab_sec (abfd)])
hdr->sh_offset = -1;
else
off = _bfd_elf_assign_file_position_for_section (hdr, off, TRUE);
}
count = 0;
filehdr_vaddr = 0;
filehdr_paddr = 0;
phdrs_vaddr = bed->maxpagesize + bed->s->sizeof_ehdr;
phdrs_paddr = 0;
hdrs_segment = NULL;
phdrs = elf_tdata (abfd)->phdr;
for (m = elf_seg_map (abfd), p = phdrs; m != NULL; m = m->next, p++)
{
++count;
if (p->p_type != PT_LOAD)
continue;
if (m->includes_filehdr)
{
filehdr_vaddr = p->p_vaddr;
filehdr_paddr = p->p_paddr;
}
if (m->includes_phdrs)
{
phdrs_vaddr = p->p_vaddr;
phdrs_paddr = p->p_paddr;
if (m->includes_filehdr)
{
hdrs_segment = m;
phdrs_vaddr += bed->s->sizeof_ehdr;
phdrs_paddr += bed->s->sizeof_ehdr;
}
}
}
if (hdrs_segment != NULL && link_info != NULL)
{
struct elf_link_hash_entry *hash
= elf_link_hash_lookup (elf_hash_table (link_info), "__ehdr_start",
FALSE, FALSE, TRUE);
if (hash != NULL
&& (hash->root.type == bfd_link_hash_new
|| hash->root.type == bfd_link_hash_undefined
|| hash->root.type == bfd_link_hash_undefweak
|| hash->root.type == bfd_link_hash_common))
{
asection *s = NULL;
if (hdrs_segment->count != 0)
s = hdrs_segment->sections[0];
else
for (m = elf_seg_map (abfd); m != NULL; m = m->next)
if (m->count != 0)
{
s = m->sections[0];
break;
}
if (s != NULL)
{
hash->root.u.def.value = filehdr_vaddr - s->vma;
hash->root.u.def.section = s;
}
else
{
hash->root.u.def.value = filehdr_vaddr;
hash->root.u.def.section = bfd_abs_section_ptr;
}
hash->root.type = bfd_link_hash_defined;
hash->def_regular = 1;
hash->non_elf = 0;
}
}
for (m = elf_seg_map (abfd), p = phdrs; m != NULL; m = m->next, p++)
{
if (p->p_type == PT_GNU_RELRO)
{
bfd_vma start, end;
if (link_info != NULL)
{
start = link_info->relro_start;
end = link_info->relro_end;
}
else if (m->count != 0)
{
if (!m->p_size_valid)
abort ();
start = m->sections[0]->vma;
end = start + m->p_size;
}
else
{
start = 0;
end = 0;
}
if (start < end)
{
struct elf_segment_map *lm;
const Elf_Internal_Phdr *lp;
unsigned int i;
for (lm = elf_seg_map (abfd), lp = phdrs;
lm != NULL;
lm = lm->next, lp++)
{
if (lp->p_type == PT_LOAD
&& lm->count != 0
&& (lm->sections[lm->count - 1]->vma
+ (!IS_TBSS (lm->sections[lm->count - 1])
? lm->sections[lm->count - 1]->size
: 0)) > start
&& lm->sections[0]->vma < end)
break;
}
BFD_ASSERT (lm != NULL);
for (i = 0; i < lm->count; i++)
{
asection *s = lm->sections[i];
if (s->vma >= start
&& s->vma < end
&& s->size != 0)
break;
}
BFD_ASSERT (i < lm->count);
p->p_vaddr = lm->sections[i]->vma;
p->p_paddr = lm->sections[i]->lma;
p->p_offset = lm->sections[i]->filepos;
p->p_memsz = end - p->p_vaddr;
p->p_filesz = p->p_memsz;
if (p->p_filesz > lp->p_vaddr + lp->p_filesz - p->p_vaddr)
p->p_filesz = lp->p_vaddr + lp->p_filesz - p->p_vaddr;
if (!m->p_align_valid)
p->p_align = 1;
if (!m->p_flags_valid)
p->p_flags = PF_R;
}
else
{
memset (p, 0, sizeof *p);
p->p_type = PT_NULL;
}
}
else if (p->p_type == PT_GNU_STACK)
{
if (m->p_size_valid)
p->p_memsz = m->p_size;
}
else if (m->count != 0)
{
unsigned int i;
if (p->p_type != PT_LOAD
&& (p->p_type != PT_NOTE
|| bfd_get_format (abfd) != bfd_core))
{
if (p->p_type == PT_PHDR)
{
m->count = 0;
continue;
}
if (m->includes_filehdr || m->includes_phdrs)
{
_bfd_error_handler
(_("%pB: error: non-load segment %d includes file header "
"and/or program header"),
abfd, (int) (p - phdrs));
return FALSE;
}
p->p_filesz = 0;
p->p_offset = m->sections[0]->filepos;
for (i = m->count; i-- != 0;)
{
asection *sect = m->sections[i];
Elf_Internal_Shdr *hdr = &elf_section_data (sect)->this_hdr;
if (hdr->sh_type != SHT_NOBITS)
{
p->p_filesz = (sect->filepos - m->sections[0]->filepos
+ hdr->sh_size);
break;
}
}
}
}
else if (m->includes_filehdr)
{
p->p_vaddr = filehdr_vaddr;
if (! m->p_paddr_valid)
p->p_paddr = filehdr_paddr;
}
else if (m->includes_phdrs)
{
p->p_vaddr = phdrs_vaddr;
if (! m->p_paddr_valid)
p->p_paddr = phdrs_paddr;
}
}
elf_next_file_pos (abfd) = off;
return TRUE;
}

BOOL transport_accept_nla(rdpTransport* transport)
{
freerdp* instance;
rdpSettings* settings;
if (transport->TlsIn == NULL)
transport->TlsIn = tls_new(transport->settings);
if (transport->TlsOut == NULL)
transport->TlsOut = transport->TlsIn;
transport->layer = TRANSPORT_LAYER_TLS;
transport->TlsIn->sockfd = transport->TcpIn->sockfd;
if (tls_accept(transport->TlsIn, transport->settings->CertificateFile, transport->settings->PrivateKeyFile) != TRUE)
return FALSE;
if (transport->settings->Authentication != TRUE)
return TRUE;
settings = transport->settings;
instance = (freerdp*) settings->instance;
if (transport->credssp == NULL)
transport->credssp = credssp_new(instance, transport, settings);
if (credssp_authenticate(transport->credssp) < 0)
{
fprintf(stderr, "client authentication failure\n");
credssp_free(transport->credssp);
return FALSE;
}
return TRUE;
}

bool CmkjPlayer::update()
{
int c, i;
short note;
for(c = 0; c < maxchannel; c++) {
if(!channel[c].defined)      continue;
if(channel[c].pstat) {
channel[c].pstat--;
continue;
}
opl->write(0xb0 + c, 0);    do {
assert(channel[c].songptr < (maxchannel + 1) * maxnotes);
note = songbuf[channel[c].songptr];
if(channel[c].songptr - c > maxchannel)
if(note && note < 250)
channel[c].pstat = channel[c].speed;
switch(note) {
case 68: opl->write(0xa0 + c,0x81); opl->write(0xb0 + c,0x21 + 4 * channel[c].octave); break;
case 69: opl->write(0xa0 + c,0xb0); opl->write(0xb0 + c,0x21 + 4 * channel[c].octave); break;
case 70: opl->write(0xa0 + c,0xca); opl->write(0xb0 + c,0x21 + 4 * channel[c].octave); break;
case 71: opl->write(0xa0 + c,0x2); opl->write(0xb0 + c,0x22 + 4 * channel[c].octave); break;
case 65: opl->write(0xa0 + c,0x41); opl->write(0xb0 + c,0x22 + 4 * channel[c].octave); break;
case 66: opl->write(0xa0 + c,0x87); opl->write(0xb0 + c,0x22 + 4 * channel[c].octave); break;
case 67: opl->write(0xa0 + c,0xae); opl->write(0xb0 + c,0x22 + 4 * channel[c].octave); break;
case 17: opl->write(0xa0 + c,0x6b); opl->write(0xb0 + c,0x21 + 4 * channel[c].octave); break;
case 18: opl->write(0xa0 + c,0x98); opl->write(0xb0 + c,0x21 + 4 * channel[c].octave); break;
case 20: opl->write(0xa0 + c,0xe5); opl->write(0xb0 + c,0x21 + 4 * channel[c].octave); break;
case 21: opl->write(0xa0 + c,0x20); opl->write(0xb0 + c,0x22 + 4 * channel[c].octave); break;
case 15: opl->write(0xa0 + c,0x63); opl->write(0xb0 + c,0x22 + 4 * channel[c].octave); break;
case 255:channel[c].songptr += maxchannel;
channel[c].pstat = songbuf[channel[c].songptr];
break;
case 254:channel[c].songptr += maxchannel;
channel[c].octave = songbuf[channel[c].songptr];
break;
case 253:channel[c].songptr += maxchannel;
channel[c].speed = songbuf[channel[c].songptr];
break;
case 252:channel[c].songptr += maxchannel;
channel[c].waveform = songbuf[channel[c].songptr] - 300;
if(c > 2)
opl->write(0xe0 + c + (c+6),channel[c].waveform);
else
opl->write(0xe0 + c,channel[c].waveform);
break;
case 251:for(i = 0; i < maxchannel; i++) channel[i].songptr = i;
songend = true;
return false;
}
if(channel[c].songptr - c < maxnotes)
channel[c].songptr += maxchannel;
else
channel[c].songptr = c;
} while(!channel[c].pstat);
}
return !songend;
}

gsize
lzw_decoder_feed (LZWDecoder *self,
guint8     *input,
gsize       input_length,
guint8     *output,
gsize       output_length)
{
gsize i, n_written = 0;
g_return_val_if_fail (LZW_IS_DECODER (self), 0);
if (self->last_code == self->eoi_code)
return 0;
for (i = 0; i < input_length; i++) {
guint8 d = input[i];
int n_available;
for (n_available = 8; n_available > 0; ) {
int n_bits, new_bits;
n_bits = MIN (self->code_size - self->code_bits, n_available);
new_bits = d & ((1 << n_bits) - 1);
d = d >> n_bits;
n_available -= n_bits;
self->code = new_bits << self->code_bits | self->code;
self->code_bits += n_bits;
if (self->code_bits < self->code_size)
continue;
if (self->code == self->eoi_code) {
self->last_code = self->code;
return n_written;
}
if (self->code == self->clear_code) {
self->code_table_size = self->eoi_code + 1;
self->code_size = self->min_code_size;
} else {
if (self->last_code != self->clear_code && self->code_table_size < MAX_CODES) {
if (self->code < self->code_table_size)
add_code (self, self->code);
else if (self->code == self->code_table_size)
add_code (self, self->last_code);
else {
self->last_code = self->eoi_code;
return output_length;
}
if (self->code_table_size == (1 << self->code_size) && self->code_size < LZW_CODE_MAX)
self->code_size++;
}
n_written += write_indexes (self, output + n_written, output_length - n_written);
}
self->last_code = self->code;
self->code = 0;
self->code_bits = 0;
if (n_written >= output_length)
return output_length;
}
}
return n_written;
}

static MagickBooleanType WriteGIFImage(const ImageInfo *image_info,Image *image,
ExceptionInfo *exception)
{
int
c;
ImageInfo
*write_info;
MagickBooleanType
status;
MagickOffsetType
scene;
RectangleInfo
page;
register ssize_t
i;
register unsigned char
*q;
size_t
bits_per_pixel,
delay,
length,
one;
ssize_t
j,
opacity;
unsigned char
*colormap,
*global_colormap;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickCoreSignature);
assert(image != (Image *) NULL);
assert(image->signature == MagickCoreSignature);
if (image->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",image->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
status=OpenBlob(image_info,image,WriteBinaryBlobMode,exception);
if (status == MagickFalse)
return(status);
global_colormap=(unsigned char *) AcquireQuantumMemory(768UL,
sizeof(*global_colormap));
colormap=(unsigned char *) AcquireQuantumMemory(768UL,sizeof(*colormap));
if ((global_colormap == (unsigned char *) NULL) ||
(colormap == (unsigned char *) NULL))
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
for (i=0; i < 768; i++)
colormap[i]=(unsigned char) 0;
write_info=CloneImageInfo(image_info);
if (LocaleCompare(write_info->magick,"GIF87") != 0)
(void) WriteBlob(image,6,(unsigned char *) "GIF89a");
else
{
(void) WriteBlob(image,6,(unsigned char *) "GIF87a");
write_info->adjoin=MagickFalse;
}
page.width=image->columns;
if (image->page.width > page.width)
page.width=image->page.width;
page.height=image->rows;
if (image->page.height > page.height)
page.height=image->page.height;
page.x=image->page.x;
page.y=image->page.y;
(void) WriteBlobLSBShort(image,(unsigned short) page.width);
(void) WriteBlobLSBShort(image,(unsigned short) page.height);
if ((write_info->adjoin != MagickFalse) &&
(GetNextImageInList(image) != (Image *) NULL))
write_info->interlace=NoInterlace;
scene=0;
one=1;
do
{
(void) TransformImageColorspace(image,sRGBColorspace,exception);
opacity=(-1);
if (IsImageOpaque(image,exception) != MagickFalse)
{
if ((image->storage_class == DirectClass) || (image->colors > 256))
(void) SetImageType(image,PaletteType,exception);
}
else
{
double
alpha,
beta;
if ((image->storage_class == DirectClass) || (image->colors > 256))
(void) SetImageType(image,PaletteBilevelAlphaType,exception);
for (i=0; i < (ssize_t) image->colors; i++)
if (image->colormap[i].alpha != OpaqueAlpha)
{
if (opacity < 0)
{
opacity=i;
continue;
}
alpha=fabs(image->colormap[i].alpha-TransparentAlpha);
beta=fabs(image->colormap[opacity].alpha-TransparentAlpha);
if (alpha < beta)
opacity=i;
}
if (opacity == -1)
{
(void) SetImageType(image,PaletteBilevelAlphaType,exception);
for (i=0; i < (ssize_t) image->colors; i++)
if (image->colormap[i].alpha != OpaqueAlpha)
{
if (opacity < 0)
{
opacity=i;
continue;
}
alpha=fabs(image->colormap[i].alpha-TransparentAlpha);
beta=fabs(image->colormap[opacity].alpha-TransparentAlpha);
if (alpha < beta)
opacity=i;
}
}
if (opacity >= 0)
{
image->colormap[opacity].red=image->transparent_color.red;
image->colormap[opacity].green=image->transparent_color.green;
image->colormap[opacity].blue=image->transparent_color.blue;
}
}
if ((image->storage_class == DirectClass) || (image->colors > 256))
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
for (bits_per_pixel=1; bits_per_pixel < 8; bits_per_pixel++)
if ((one << bits_per_pixel) >= image->colors)
break;
q=colormap;
for (i=0; i < (ssize_t) image->colors; i++)
{
*q++=ScaleQuantumToChar(ClampToQuantum(image->colormap[i].red));
*q++=ScaleQuantumToChar(ClampToQuantum(image->colormap[i].green));
*q++=ScaleQuantumToChar(ClampToQuantum(image->colormap[i].blue));
}
for ( ; i < (ssize_t) (one << bits_per_pixel); i++)
{
*q++=(unsigned char) 0x0;
*q++=(unsigned char) 0x0;
*q++=(unsigned char) 0x0;
}
if ((GetPreviousImageInList(image) == (Image *) NULL) ||
(write_info->adjoin == MagickFalse))
{
c=0x80;
c|=(8-1) << 4;  
c|=(bits_per_pixel-1);   
(void) WriteBlobByte(image,(unsigned char) c);
for (j=0; j < (ssize_t) image->colors; j++)
if (IsPixelInfoEquivalent(&image->background_color,image->colormap+j))
break;
(void) WriteBlobByte(image,(unsigned char)
(j == (ssize_t) image->colors ? 0 : j));  
(void) WriteBlobByte(image,(unsigned char) 0x00);  
length=(size_t) (3*(one << bits_per_pixel));
(void) WriteBlob(image,length,colormap);
for (j=0; j < 768; j++)
global_colormap[j]=colormap[j];
}
if (LocaleCompare(write_info->magick,"GIF87") != 0)
{
const char
*value;
(void) WriteBlobByte(image,(unsigned char) 0x21);
(void) WriteBlobByte(image,(unsigned char) 0xf9);
(void) WriteBlobByte(image,(unsigned char) 0x04);
c=image->dispose << 2;
if (opacity >= 0)
c|=0x01;
(void) WriteBlobByte(image,(unsigned char) c);
delay=(size_t) (100*image->delay/MagickMax((size_t)
image->ticks_per_second,1));
(void) WriteBlobLSBShort(image,(unsigned short) delay);
(void) WriteBlobByte(image,(unsigned char) (opacity >= 0 ? opacity :
0));
(void) WriteBlobByte(image,(unsigned char) 0x00);
value=GetImageProperty(image,"comment",exception);
if ((LocaleCompare(write_info->magick,"GIF87") != 0) &&
(value != (const char *) NULL))
{
register const char 
*p;
size_t
count;
(void) WriteBlobByte(image,(unsigned char) 0x21);
(void) WriteBlobByte(image,(unsigned char) 0xfe);
for (p=value; *p != '\0'; )
{
count=MagickMin(strlen(p),255);
(void) WriteBlobByte(image,(unsigned char) count);
for (i=0; i < (ssize_t) count; i++)
(void) WriteBlobByte(image,(unsigned char) *p++);
}
(void) WriteBlobByte(image,(unsigned char) 0x00);
}
if ((GetPreviousImageInList(image) == (Image *) NULL) &&
(GetNextImageInList(image) != (Image *) NULL) &&
(image->iterations != 1))
{
(void) LogMagickEvent(CoderEvent,GetMagickModule(),
"  Writing GIF Extension %s","NETSCAPE2.0");
(void) WriteBlobByte(image,(unsigned char) 0x21);
(void) WriteBlobByte(image,(unsigned char) 0xff);
(void) WriteBlobByte(image,(unsigned char) 0x0b);
(void) WriteBlob(image,11,(unsigned char *) "NETSCAPE2.0");
(void) WriteBlobByte(image,(unsigned char) 0x03);
(void) WriteBlobByte(image,(unsigned char) 0x01);
(void) WriteBlobLSBShort(image,(unsigned short) (image->iterations ?
image->iterations-1 : 0));
(void) WriteBlobByte(image,(unsigned char) 0x00);
}
if ((image->gamma != 1.0f/2.2f))
{
char
attributes[MagickPathExtent];
ssize_t
count;
(void) LogMagickEvent(CoderEvent,GetMagickModule(),
"  Writing GIF Extension %s","ImageMagick");
(void) WriteBlobByte(image,(unsigned char) 0x21);
(void) WriteBlobByte(image,(unsigned char) 0xff);
(void) WriteBlobByte(image,(unsigned char) 0x0b);
(void) WriteBlob(image,11,(unsigned char *) "ImageMagick");
count=FormatLocaleString(attributes,MagickPathExtent,"gamma=%g",
image->gamma);
(void) WriteBlobByte(image,(unsigned char) count);
(void) WriteBlob(image,(size_t) count,(unsigned char *) attributes);
(void) WriteBlobByte(image,(unsigned char) 0x00);
}
ResetImageProfileIterator(image);
for ( ; ; )
{
char
*name;
const StringInfo
*profile;
name=GetNextImageProfile(image);
if (name == (const char *) NULL)
break;
profile=GetImageProfile(image,name);
if (profile != (StringInfo *) NULL)
{
if ((LocaleCompare(name,"ICC") == 0) ||
(LocaleCompare(name,"ICM") == 0) ||
(LocaleCompare(name,"IPTC") == 0) ||
(LocaleCompare(name,"8BIM") == 0) ||
(LocaleNCompare(name,"gif:",4) == 0))
{
ssize_t
offset;
unsigned char
*datum;
datum=GetStringInfoDatum(profile);
length=GetStringInfoLength(profile);
(void) WriteBlobByte(image,(unsigned char) 0x21);
(void) WriteBlobByte(image,(unsigned char) 0xff);
(void) WriteBlobByte(image,(unsigned char) 0x0b);
if ((LocaleCompare(name,"ICC") == 0) ||
(LocaleCompare(name,"ICM") == 0))
{
(void) WriteBlob(image,11,(unsigned char *) "ICCRGBG1012");
(void) LogMagickEvent(CoderEvent,GetMagickModule(),
"  Writing GIF Extension %s","ICCRGBG1012");
}
else
if ((LocaleCompare(name,"IPTC") == 0))
{
(void) WriteBlob(image,11,(unsigned char *) "MGKIPTC0000");
(void) LogMagickEvent(CoderEvent,GetMagickModule(),
"  Writing GIF Extension %s","MGKIPTC0000");
}
else
if ((LocaleCompare(name,"8BIM") == 0))
{
(void) WriteBlob(image,11,(unsigned char *)
"MGK8BIM0000");
(void) LogMagickEvent(CoderEvent,GetMagickModule(),
"  Writing GIF Extension %s","MGK8BIM0000");
}
else
{
char
extension[MagickPathExtent];
(void) CopyMagickString(extension,name+4,
sizeof(extension));
(void) WriteBlob(image,11,(unsigned char *) extension);
(void) LogMagickEvent(CoderEvent,GetMagickModule(),
"  Writing GIF Extension %s",name);
}
offset=0;
while ((ssize_t) length > offset)
{
size_t
block_length;
if ((length-offset) < 255)
block_length=length-offset;
else
block_length=255;
(void) WriteBlobByte(image,(unsigned char) block_length);
(void) WriteBlob(image,(size_t) block_length,datum+offset);
offset+=(ssize_t) block_length;
}
(void) WriteBlobByte(image,(unsigned char) 0x00);
}
}
}
}
(void) WriteBlobByte(image,',');  
page.x=image->page.x;
page.y=image->page.y;
if ((image->page.width != 0) && (image->page.height != 0))
page=image->page;
(void) WriteBlobLSBShort(image,(unsigned short) (page.x < 0 ? 0 : page.x));
(void) WriteBlobLSBShort(image,(unsigned short) (page.y < 0 ? 0 : page.y));
(void) WriteBlobLSBShort(image,(unsigned short) image->columns);
(void) WriteBlobLSBShort(image,(unsigned short) image->rows);
c=0x00;
if (write_info->interlace != NoInterlace)
c|=0x40;  
for (j=0; j < (ssize_t) (3*image->colors); j++)
if (colormap[j] != global_colormap[j])
break;
if (j == (ssize_t) (3*image->colors))
(void) WriteBlobByte(image,(unsigned char) c);
else
{
c|=0x80;
c|=(bits_per_pixel-1);   
(void) WriteBlobByte(image,(unsigned char) c);
length=(size_t) (3*(one << bits_per_pixel));
(void) WriteBlob(image,length,colormap);
}
c=(int) MagickMax(bits_per_pixel,2);
(void) WriteBlobByte(image,(unsigned char) c);
status=EncodeImage(write_info,image,(size_t) MagickMax(bits_per_pixel,2)+1,
exception);
if (status == MagickFalse)
{
global_colormap=(unsigned char *) RelinquishMagickMemory(
global_colormap);
colormap=(unsigned char *) RelinquishMagickMemory(colormap);
write_info=DestroyImageInfo(write_info);
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
}
(void) WriteBlobByte(image,(unsigned char) 0x00);
if (GetNextImageInList(image) == (Image *) NULL)
break;
image=SyncNextImageInList(image);
scene++;
status=SetImageProgress(image,SaveImagesTag,scene,
GetImageListLength(image));
if (status == MagickFalse)
break;
} while (write_info->adjoin != MagickFalse);
(void) WriteBlobByte(image,';'); 
global_colormap=(unsigned char *) RelinquishMagickMemory(global_colormap);
colormap=(unsigned char *) RelinquishMagickMemory(colormap);
write_info=DestroyImageInfo(write_info);
(void) CloseBlob(image);
return(MagickTrue);
}

static krb5_error_code
tgs_issue_ticket(kdc_realm_t *realm, struct tgs_req_info *t,
krb5_flags tktflags, krb5_ticket_times *times, krb5_data *pkt,
const krb5_fulladdr *from,
struct kdc_request_state *fast_state,
krb5_audit_state *au_state, const char **status,
krb5_data **response)
{
krb5_context context = realm->realm_context;
krb5_error_code ret;
krb5_keyblock session_key = { 0 }, server_key = { 0 };
krb5_keyblock *ticket_encrypting_key, *subject_key;
krb5_keyblock *initial_reply_key, *fast_reply_key = NULL;
krb5_enc_tkt_part enc_tkt_reply = { 0 };
krb5_ticket ticket_reply = { 0 };
krb5_enc_kdc_rep_part reply_encpart = { 0 };
krb5_kdc_rep reply = { 0 };
krb5_pac subject_pac;
krb5_db_entry *subject_server;
krb5_enc_tkt_part *header_enc_tkt = t->header_tkt->enc_part2;
krb5_last_req_entry nolrentry = { KV5M_LAST_REQ_ENTRY, KRB5_LRQ_NONE, 0 };
krb5_last_req_entry *nolrarray[2] = { &nolrentry, NULL };
au_state->stage = ISSUE_TKT;
ret = gen_session_key(context, t->req, t->server, &session_key, status);
if (ret)
goto cleanup;
if (t->flags & KRB5_KDB_FLAG_CONSTRAINED_DELEGATION) {
subject_pac = t->stkt_pac;
subject_server = t->stkt_server;
subject_key = t->stkt_server_key;
} else {
subject_pac = t->header_pac;
subject_server = t->header_server;
subject_key = t->header_key;
}
initial_reply_key = (t->subkey != NULL) ? t->subkey :
t->header_tkt->enc_part2->session;
if (t->req->kdc_options & KDC_OPT_ENC_TKT_IN_SKEY) {
ticket_encrypting_key = t->stkt->enc_part2->session;
} else {
ret = get_first_current_key(context, t->server, &server_key);
if (ret) {
*status = "FINDING_SERVER_KEY";
goto cleanup;
}
ticket_encrypting_key = &server_key;
}
if (t->req->kdc_options & (KDC_OPT_VALIDATE | KDC_OPT_RENEW)) {
ticket_reply = *t->header_tkt;
enc_tkt_reply = *t->header_tkt->enc_part2;
enc_tkt_reply.authorization_data = NULL;
} else {
if (t->req->kdc_options & (KDC_OPT_FORWARDED | KDC_OPT_PROXY)) {
enc_tkt_reply.caddrs = t->req->addresses;
reply_encpart.caddrs = t->req->addresses;
} else {
enc_tkt_reply.caddrs = header_enc_tkt->caddrs;
reply_encpart.caddrs = NULL;
}
ticket_reply.server = t->is_referral ? t->sprinc : t->req->server;
}
enc_tkt_reply.flags = tktflags;
enc_tkt_reply.times = *times;
enc_tkt_reply.client = t->tkt_client;
enc_tkt_reply.session = &session_key;
enc_tkt_reply.transited = t->transited;
ret = handle_authdata(realm, t->flags, t->client, t->server,
subject_server, t->local_tgt, &t->local_tgt_key,
initial_reply_key, ticket_encrypting_key,
subject_key, NULL, pkt, t->req, t->s4u_cprinc,
subject_pac, t->subject_tkt, &t->auth_indicators,
&enc_tkt_reply);
if (ret) {
krb5_klog_syslog(LOG_INFO, _("TGS_REQ : handle_authdata (%d)"), ret);
*status = "HANDLE_AUTHDATA";
goto cleanup;
}
ticket_reply.enc_part2 = &enc_tkt_reply;
ret = krb5_encrypt_tkt_part(context, ticket_encrypting_key, &ticket_reply);
if (ret)
goto cleanup;
if (t->req->kdc_options & KDC_OPT_ENC_TKT_IN_SKEY) {
ticket_reply.enc_part.kvno = 0;
kau_u2u(context, TRUE, au_state);
} else {
ticket_reply.enc_part.kvno = current_kvno(t->server);
}
au_state->stage = ENCR_REP;
if (t->s4u2self != NULL &&
krb5int_find_pa_data(context, t->req->padata,
KRB5_PADATA_S4U_X509_USER) != NULL) {
ret = kdc_make_s4u2self_rep(context, t->subkey,
t->header_tkt->enc_part2->session,
t->s4u2self, &reply, &reply_encpart);
if (ret)
goto cleanup;
}
reply_encpart.session = &session_key;
reply_encpart.nonce = t->req->nonce;
reply_encpart.times = enc_tkt_reply.times;
reply_encpart.last_req = nolrarray;
reply_encpart.key_exp = 0;
reply_encpart.flags = enc_tkt_reply.flags;
reply_encpart.server = ticket_reply.server;
reply.msg_type = KRB5_TGS_REP;
reply.client = enc_tkt_reply.client;
reply.ticket = &ticket_reply;
reply.enc_part.kvno = 0;
reply.enc_part.enctype = initial_reply_key->enctype;
ret = kdc_fast_response_handle_padata(fast_state, t->req, &reply,
initial_reply_key->enctype);
if (ret)
goto cleanup;
ret = kdc_fast_handle_reply_key(fast_state, initial_reply_key,
&fast_reply_key);
if (ret)
goto cleanup;
ret = return_enc_padata(context, pkt, t->req, fast_reply_key, t->server,
&reply_encpart,
t->is_referral &&
(t->req->kdc_options & KDC_OPT_CANONICALIZE));
if (ret) {
*status = "KDC_RETURN_ENC_PADATA";
goto cleanup;
}
ret = kau_make_tkt_id(context, &ticket_reply, &au_state->tkt_out_id);
if (ret)
goto cleanup;
if (kdc_fast_hide_client(fast_state))
reply.client = (krb5_principal)krb5_anonymous_principal();
ret = krb5_encode_kdc_rep(context, KRB5_TGS_REP, &reply_encpart,
t->subkey != NULL, fast_reply_key, &reply,
response);
if (ret)
goto cleanup;
log_tgs_req(context, from, t->req, &reply, t->cprinc, t->sprinc,
t->s4u_cprinc, t->authtime, t->flags, "ISSUE", 0, NULL);
au_state->status = "ISSUE";
au_state->reply = &reply;
if (t->flags & KRB5_KDB_FLAG_CONSTRAINED_DELEGATION)
kau_s4u2proxy(context, TRUE, au_state);
kau_tgs_req(context, TRUE, au_state);
au_state->reply = NULL;
cleanup:
zapfree(ticket_reply.enc_part.ciphertext.data,
ticket_reply.enc_part.ciphertext.length);
zapfree(reply.enc_part.ciphertext.data, reply.enc_part.ciphertext.length);
krb5_free_pa_data(context, reply.padata);
krb5_free_pa_data(context, reply_encpart.enc_padata);
krb5_free_authdata(context, enc_tkt_reply.authorization_data);
krb5_free_keyblock_contents(context, &session_key);
krb5_free_keyblock_contents(context, &server_key);
krb5_free_keyblock(context, fast_reply_key);
return ret;
}

R_API char *r_cons_editor(const char *file, const char *str) {
const char *line;
_n = 0;
if (I->cb_editor) {
return I->cb_editor (I->user, file, str);
}
free (path);
if (file) {
path = strdup (file);
bytes = 0;
lines = r_file_slurp (file, &bytes);
nlines = r_str_split (lines, '\n');
eprintf ("Loaded %d lines on %d byte(s)\n",
(nlines? (nlines - 1): 0), bytes);
} else {
path = NULL;
}
I->line->hist_up = up;
I->line->hist_down = down;
I->line->contents = I->line->buffer.data;
for (;;) {
setnewline (_n);
snprintf (prompt, sizeof (prompt), "%d: ", _n);
r_line_set_prompt (prompt);
line = r_line_readline ();
saveline (_n, line);
_n++;
if (!line) {
break;
}
}
filesave ();
I->line->hist_up = NULL;
I->line->hist_down = NULL;
I->line->contents = NULL;
return lines;
}

int gx_scan_convert(gx_device     * restrict pdev,
gx_path       * restrict path,
const gs_fixed_rect * restrict clip,
gx_edgebuffer * restrict edgebuffer,
fixed                    fixed_flat)
{
gs_fixed_rect  ibox;
int            scanlines;
const subpath *psub;
int           *index;
int           *table;
int            i;
int            code;
edgebuffer->index = NULL;
edgebuffer->table = NULL;
if (path->first_subpath == NULL)
return 0;
code = make_bbox(path, clip, &ibox, fixed_half);
if (code < 0)
return code;
if (ibox.q.y <= ibox.p.y)
return 0;
code = make_table(pdev, path, &ibox, &scanlines, &index, &table);
if (code < 0)
return code;
for (psub = path->first_subpath; psub != 0;) {
const segment *pseg = (const segment *)psub;
fixed ex = pseg->pt.x;
fixed ey = pseg->pt.y;
fixed ix = ex;
fixed iy = ey;
while ((pseg = pseg->next) != 0 &&
pseg->type != s_start
) {
fixed sx = ex;
fixed sy = ey;
ex = pseg->pt.x;
ey = pseg->pt.y;
switch (pseg->type) {
default:
case s_start: 
case s_dash:  
assert("This should never happen" == NULL);
break;
case s_curve: {
const curve_segment *const pcur = (const curve_segment *)pseg;
int k = gx_curve_log2_samples(sx, sy, pcur, fixed_flat);
mark_curve(sx, sy, pcur->p1.x, pcur->p1.y, pcur->p2.x, pcur->p2.y, ex, ey, ibox.p.y, scanlines, table, index, k);
break;
}
case s_gap:
case s_line:
case s_line_close:
if (sy != ey)
mark_line(sx, sy, ex, ey, ibox.p.y, scanlines, table, index);
break;
}
}
if (iy != ey)
mark_line(ex, ey, ix, iy, ibox.p.y, scanlines, table, index);
psub = (const subpath *)pseg;
}
edgebuffer->base   = ibox.p.y;
edgebuffer->height = scanlines;
edgebuffer->xmin   = ibox.p.x;
edgebuffer->xmax   = ibox.q.x;
edgebuffer->index  = index;
edgebuffer->table  = table;
#ifdef DEBUG_SCAN_CONVERTER
if (debugging_scan_converter) {
dlprintf("Before sorting:\n");
gx_edgebuffer_print(edgebuffer);
}
#endif
for (i=0; i < scanlines; i++) {
int *row = &table[index[i]];
int  rowlen = *row++;
if (rowlen <= 6) {
int j, k;
for (j = 0; j < rowlen-1; j++) {
int t = row[j];
for (k = j+1; k < rowlen; k++) {
int s = row[k];
if (t > s)
row[k] = t, t = row[j] = s;
}
}
} else
qsort(row, rowlen, sizeof(int), intcmp);
}
return 0;
}

static inline int is_in_region(u32_t r_index, u32_t start, u32_t size)
{
u32_t r_addr_start;
u32_t r_addr_end;
r_addr_start = SYSMPU->WORD[r_index][0];
r_addr_end = SYSMPU->WORD[r_index][1];
if (start >= r_addr_start && (start + size - 1) <= r_addr_end) {
return 1;
}
return 0;
}

bool CDataFileReader::Open(class IStorage *pStorage, const char *pFilename, int StorageType)
{
dbg_msg("datafile", "loading. filename='%s'", pFilename);
IOHANDLE File = pStorage->OpenFile(pFilename, IOFLAG_READ, StorageType);
if(!File)
{
dbg_msg("datafile", "could not open '%s'", pFilename);
return false;
}
SHA256_CTX Sha256Ctx;
sha256_init(&Sha256Ctx);
unsigned Crc = crc32(0L, 0x0, 0);
{
enum
{
BUFFER_SIZE = 64*1024
};
unsigned char aBuffer[BUFFER_SIZE];
while(1)
{
unsigned Bytes = io_read(File, aBuffer, BUFFER_SIZE);
if(Bytes == 0)
break;
sha256_update(&Sha256Ctx, aBuffer, Bytes);
Crc = crc32(Crc, aBuffer, Bytes); }
io_seek(File, 0, IOSEEK_START);
}
CDatafileHeader Header;
io_read(File, &Header, sizeof(Header));
if(Header.m_aID[0] != 'A' || Header.m_aID[1] != 'T' || Header.m_aID[2] != 'A' || Header.m_aID[3] != 'D')
{
if(Header.m_aID[0] != 'D' || Header.m_aID[1] != 'A' || Header.m_aID[2] != 'T' || Header.m_aID[3] != 'A')
{
dbg_msg("datafile", "wrong signature. %x %x %x %x", Header.m_aID[0], Header.m_aID[1], Header.m_aID[2], Header.m_aID[3]);
io_close(File);
return 0;
}
}
#if defined(CONF_ARCH_ENDIAN_BIG)
swap_endian(&Header, sizeof(int), sizeof(Header)/sizeof(int));
#endif
if(Header.m_Version != 3 && Header.m_Version != 4)
{
dbg_msg("datafile", "wrong version. version=%x", Header.m_Version);
io_close(File);
return 0;
}
unsigned Size = 0;
Size += Header.m_NumItemTypes*sizeof(CDatafileItemType);
Size += (Header.m_NumItems+Header.m_NumRawData)*sizeof(int);
if(Header.m_Version == 4)
Size += Header.m_NumRawData*sizeof(int); Size += Header.m_ItemSize;
unsigned AllocSize = Size;
AllocSize += sizeof(CDatafile); AllocSize += Header.m_NumRawData*sizeof(void*); 
CDatafile *pTmpDataFile = (CDatafile*)mem_alloc(AllocSize, 1);
pTmpDataFile->m_Header = Header;
pTmpDataFile->m_DataStartOffset = sizeof(CDatafileHeader) + Size;
pTmpDataFile->m_ppDataPtrs = (char**)(pTmpDataFile+1);
pTmpDataFile->m_pData = (char *)(pTmpDataFile+1)+Header.m_NumRawData*sizeof(char *);
pTmpDataFile->m_File = File;
pTmpDataFile->m_Sha256 = sha256_finish(&Sha256Ctx);
pTmpDataFile->m_Crc = Crc;
mem_zero(pTmpDataFile->m_ppDataPtrs, Header.m_NumRawData*sizeof(void*));
unsigned ReadSize = io_read(File, pTmpDataFile->m_pData, Size);
if(ReadSize != Size)
{
io_close(pTmpDataFile->m_File);
mem_free(pTmpDataFile);
pTmpDataFile = 0;
dbg_msg("datafile", "couldn't load the whole thing, wanted=%d got=%d", Size, ReadSize);
return false;
}
Close();
m_pDataFile = pTmpDataFile;
#if defined(CONF_ARCH_ENDIAN_BIG)
swap_endian(m_pDataFile->m_pData, sizeof(int), min(static_cast<unsigned>(Header.m_Swaplen), Size) / sizeof(int));
#endif
{
dbg_msg("datafile", "allocsize=%d", AllocSize);
dbg_msg("datafile", "readsize=%d", ReadSize);
dbg_msg("datafile", "swaplen=%d", Header.m_Swaplen);
dbg_msg("datafile", "item_size=%d", m_pDataFile->m_Header.m_ItemSize);
}
m_pDataFile->m_Info.m_pItemTypes = (CDatafileItemType *)m_pDataFile->m_pData;
m_pDataFile->m_Info.m_pItemOffsets = (int *)&m_pDataFile->m_Info.m_pItemTypes[m_pDataFile->m_Header.m_NumItemTypes];
m_pDataFile->m_Info.m_pDataOffsets = (int *)&m_pDataFile->m_Info.m_pItemOffsets[m_pDataFile->m_Header.m_NumItems];
m_pDataFile->m_Info.m_pDataSizes = (int *)&m_pDataFile->m_Info.m_pDataOffsets[m_pDataFile->m_Header.m_NumRawData];
if(Header.m_Version == 4)
m_pDataFile->m_Info.m_pItemStart = (char *)&m_pDataFile->m_Info.m_pDataSizes[m_pDataFile->m_Header.m_NumRawData];
else
m_pDataFile->m_Info.m_pItemStart = (char *)&m_pDataFile->m_Info.m_pDataOffsets[m_pDataFile->m_Header.m_NumRawData];
m_pDataFile->m_Info.m_pDataStart = m_pDataFile->m_Info.m_pItemStart + m_pDataFile->m_Header.m_ItemSize;
dbg_msg("datafile", "loading done. datafile='%s'", pFilename);
if(DEBUG)
{
}
return true;
}

uint8_t _ReadStaticFiles(HTTPReqMessage *req, HTTPResMessage *res) {
uint8_t found = 0;
int8_t depth = 0;
char *uri = req->Header.URI;
size_t n = strlen(uri);
size_t i;
FILE *fp;
int size;
char path[128] = {STATIC_FILE_FOLDER};
char header[] = "HTTP/1.1 200 OK\r\nConnection: close\r\n"
"Content-Type: text/html; charset=UTF-8\r\n\r\n";
for(i=0; i<n; i++) {
if(uri[i] == '/') {
if(((n-i) > 2) && (uri[i+1] == '.') && ((uri[i+2] == '.'))) {
depth -= 1;
if(depth < 0)
break;
}
else if (((n-i) > 1) && (uri[i+1] == '.'))
continue;
else
depth += 1;
}
}
if((depth >= 0) && (uri[i-1] != '/')) {
memcpy(path + strlen(STATIC_FILE_FOLDER), uri, strlen(uri));
fp = fopen(path, "r");
if(fp != NULL) {
fseek(fp, 0, SEEK_END);
size = ftell(fp);
fseek(fp, 0, SEEK_SET);
if(size < MAX_BODY_SIZE) {
n = strlen(header);
memcpy(res->_buf, header, n);
i = n;
n = fread(res->_buf + i, 1, size, fp);
i += n;
res->_index = i;
found = 1;
}
fclose(fp);
}
}
return found;
}

static int huffcode(int *qs ,
int len,
int bnum,
CoderInfo *coder)
{
static hcode16_t * const hmap[12] = {0, book01, book02, book03, book04,
book05, book06, book07, book08, book09, book10, book11};
hcode16_t *book;
int cnt;
int bits = 0, blen;
int ofs, *qp;
int data;
int idx;
int datacnt;
#ifdef DRM
int drmbits = 0;
int maxesc = 0;
#endif
if (coder)
datacnt = coder->datacnt;
else
datacnt = 0;
book = hmap[bnum];
switch (bnum)
{
#ifdef DRM
case HCB_ZERO:
case HCB_INTENSITY:
case HCB_INTENSITY2:
for(ofs = 0; ofs < len; ofs += 4)
{
coder->s[datacnt].data = 0;
coder->s[datacnt++].len = 0;
coder->num_data_cw[coder->cur_cw++] = 1;
}
break;
#endif
case 1:
case 2:
for(ofs = 0; ofs < len; ofs += 4)
{
qp = qs+ofs;
idx = 27 * qp[0] + 9 * qp[1] + 3 * qp[2] + qp[3] + 40;
blen = book[idx].len;
if (coder)
{
data = book[idx].data;
coder->s[datacnt].data = data;
coder->s[datacnt++].len = blen;
DRMDATA;
}
bits += blen;
}
break;
case 3:
case 4:
for(ofs = 0; ofs < len; ofs += 4)
{
qp = qs+ofs;
idx = 27 * abs(qp[0]) + 9 * abs(qp[1]) + 3 * abs(qp[2]) + abs(qp[3]);
blen = book[idx].len;
if (!coder)
{
for(cnt = 0; cnt < 4; cnt++)
if(qp[cnt])
blen++;
}
else
{
data = book[idx].data;
for(cnt = 0; cnt < 4; cnt++)
{
if(qp[cnt])
{
blen++;
data <<= 1;
if (qp[cnt] < 0)
data |= 1;
}
}
coder->s[datacnt].data = data;
coder->s[datacnt++].len = blen;
DRMDATA;
}
bits += blen;
}
break;
case 5:
case 6:
for(ofs = 0; ofs < len; ofs += 2)
{
qp = qs+ofs;
idx = 9 * qp[0] + qp[1] + 40;
blen = book[idx].len;
if (coder)
{
data = book[idx].data;
coder->s[datacnt].data = data;
coder->s[datacnt++].len = blen;
DRMDATA;
}
bits += blen;
}
break;
case 7:
case 8:
for(ofs = 0; ofs < len; ofs += 2)
{
qp = qs+ofs;
idx = 8 * abs(qp[0]) + abs(qp[1]);
blen = book[idx].len;
if (!coder)
{
for(cnt = 0; cnt < 2; cnt++)
if(qp[cnt])
blen++;
}
else
{
data = book[idx].data;
for(cnt = 0; cnt < 2; cnt++)
{
if(qp[cnt])
{
blen++;
data <<= 1;
if (qp[cnt] < 0)
data |= 1;
}
}
coder->s[datacnt].data = data;
coder->s[datacnt++].len = blen;
DRMDATA;
}
bits += blen;
}
break;
case 9:
case 10:
for(ofs = 0; ofs < len; ofs += 2)
{
qp = qs+ofs;
idx = 13 * abs(qp[0]) + abs(qp[1]);
blen = book[idx].len;
if (!coder)
{
for(cnt = 0; cnt < 2; cnt++)
if(qp[cnt])
blen++;
}
else
{
data = book[idx].data;
for(cnt = 0; cnt < 2; cnt++)
{
if(qp[cnt])
{
blen++;
data <<= 1;
if (qp[cnt] < 0)
data |= 1;
}
}
coder->s[datacnt].data = data;
coder->s[datacnt++].len = blen;
DRMDATA;
}
bits += blen;
}
break;
case HCB_ESC:
for(ofs = 0; ofs < len; ofs += 2)
{
int x0, x1;
qp = qs+ofs;
x0 = abs(qp[0]);
x1 = abs(qp[1]);
if (x0 > 16)
x0 = 16;
if (x1 > 16)
x1 = 16;
idx = 17 * x0 + x1;
blen = book[idx].len;
if (!coder)
{
for(cnt = 0; cnt < 2; cnt++)
if(qp[cnt])
blen++;
}
else
{
data = book[idx].data;
for(cnt = 0; cnt < 2; cnt++)
{
if(qp[cnt])
{
blen++;
data <<= 1;
if (qp[cnt] < 0)
data |= 1;
}
}
coder->s[datacnt].data = data;
coder->s[datacnt++].len = blen;
#ifdef DRM
coder->num_data_cw[coder->cur_cw] = 1;
drmbits = blen;
#endif
}
bits += blen;
if (x0 >= 16)
{
blen = escape(abs(qp[0]), &data);
if (coder)
{
coder->s[datacnt].data = data;
coder->s[datacnt++].len = blen;
#ifdef DRM
coder->num_data_cw[coder->cur_cw]++;
drmbits += blen;
