#endif
}
bits += blen;
}
if (x1 >= 16)
{
blen = escape(abs(qp[1]), &data);
if (coder)
{
coder->s[datacnt].data = data;
coder->s[datacnt++].len = blen;
#ifdef DRM
coder->num_data_cw[coder->cur_cw]++;
drmbits += blen;
if (maxesc < data)
maxesc = data;
#endif
}
bits += blen;
}
#ifdef DRM
coder->iLenReordSpData += drmbits;
if (coder->iLenLongestCW < drmbits)
coder->iLenLongestCW = drmbits;
coder->cur_cw++;
#endif
}
#ifdef DRM
if (maxesc <= 15)
vcb11 = 16;
else if (maxesc <= 31)
vcb11 = 17;
else if (maxesc <= 47)
vcb11 = 18;
else if (maxesc <= 63)
vcb11 = 19;
else if (maxesc <= 95)
vcb11 = 20;
else if (maxesc <= 127)
vcb11 = 21;
else if (maxesc <= 159)
vcb11 = 22;
else if (maxesc <= 191)
