static void
extract_archive_thread (GSimpleAsyncResult *result,
GObject            *object,
GCancellable       *cancellable)
{
ExtractData          *extract_data;
LoadData             *load_data;
GHashTable           *checked_folders;
GHashTable           *created_files;
GHashTable           *folders_created_during_extraction;
GHashTable           *external_links;
struct archive       *a;
struct archive_entry *entry;
int                   r;
extract_data = g_simple_async_result_get_op_res_gpointer (result);
load_data = LOAD_DATA (extract_data);
r = create_read_object (load_data, &a);
if (r != ARCHIVE_OK) {
archive_read_free(a);
return;
}
checked_folders = g_hash_table_new_full (g_file_hash, (GEqualFunc) g_file_equal, g_object_unref, NULL);
created_files = g_hash_table_new_full (g_file_hash, (GEqualFunc) g_file_equal, g_object_unref, g_object_unref);
folders_created_during_extraction = g_hash_table_new_full (g_file_hash, (GEqualFunc) g_file_equal, g_object_unref, NULL);
external_links = g_hash_table_new_full (g_file_hash, (GEqualFunc) g_file_equal, g_object_unref, NULL);
fr_archive_progress_set_total_files (load_data->archive, extract_data->n_files_to_extract);
while ((r = archive_read_next_header (a, &entry)) == ARCHIVE_OK) {
const char    *pathname;
char          *fullpath;
const char    *relative_path;
GFile         *file;
GFile         *parent;
GOutputStream *ostream;
const void    *buffer;
size_t         buffer_size;
int64_t        target_offset, actual_offset;
GError        *local_error = NULL;
__LA_MODE_T    filetype;
if (g_cancellable_is_cancelled (cancellable))
break;
pathname = archive_entry_pathname (entry);
if (! extract_data_get_extraction_requested (extract_data, pathname)) {
archive_read_data_skip (a);
continue;
}
fullpath = (*pathname == '/') ? g_strdup (pathname) : g_strconcat ("/", pathname, NULL);
relative_path = _g_path_get_relative_basename_safe (fullpath, extract_data->base_dir, extract_data->junk_paths);
if (relative_path == NULL) {
fr_archive_progress_inc_completed_files (load_data->archive, 1);
fr_archive_progress_inc_completed_bytes (load_data->archive, archive_entry_size_is_set (entry) ? archive_entry_size (entry) : 0);
archive_read_data_skip (a);
continue;
}
if (_g_path_is_external_to_destination (relative_path, extract_data->destination, external_links)) {
fr_archive_progress_inc_completed_files (load_data->archive, 1);
fr_archive_progress_inc_completed_bytes (load_data->archive, archive_entry_size_is_set (entry) ? archive_entry_size (entry) : 0);
archive_read_data_skip (a);
continue;
}
file = g_file_get_child (extract_data->destination, relative_path);
if ((g_hash_table_lookup (folders_created_during_extraction, file) == NULL)
&& (extract_data->skip_older || ! extract_data->overwrite))
{
GFileInfo *info;
info = g_file_query_info (file,
G_FILE_ATTRIBUTE_STANDARD_DISPLAY_NAME "," G_FILE_ATTRIBUTE_TIME_MODIFIED,
G_FILE_QUERY_INFO_NONE,
cancellable,
&local_error);
if (info != NULL) {
gboolean skip = FALSE;
if (! extract_data->overwrite) {
skip = TRUE;
}
else if (extract_data->skip_older) {
GTimeVal modification_time;
g_file_info_get_modification_time (info, &modification_time);
if (archive_entry_mtime (entry) < modification_time.tv_sec)
skip = TRUE;
}
g_object_unref (info);
if (skip) {
g_object_unref (file);
archive_read_data_skip (a);
fr_archive_progress_inc_completed_bytes (load_data->archive, archive_entry_size_is_set (entry) ? archive_entry_size (entry) : 0);
if ((extract_data->file_list != NULL) && (--extract_data->n_files_to_extract == 0)) {
r = ARCHIVE_EOF;
break;
}
continue;
}
}
else {
if (! g_error_matches (local_error, G_IO_ERROR, G_IO_ERROR_NOT_FOUND)) {
load_data->error = local_error;
g_object_unref (info);
break;
}
g_clear_error (&local_error);
}
}
fr_archive_progress_inc_completed_files (load_data->archive, 1);
parent = g_file_get_parent (file);
if ((parent != NULL)
&& (g_hash_table_lookup (checked_folders, parent) == NULL)
&& ! g_file_query_exists (parent, cancellable))
{
if (! _g_file_make_directory_with_parents (parent,
folders_created_during_extraction,
cancellable,
&local_error))
{
if (! g_error_matches (local_error, G_IO_ERROR, G_IO_ERROR_EXISTS))
load_data->error = local_error;
else
g_clear_error (&local_error);
}
if (load_data->error == NULL) {
GFile *grandparent;
grandparent = g_object_ref (parent);
while (grandparent != NULL) {
if (g_hash_table_lookup (checked_folders, grandparent) == NULL)
g_hash_table_insert (checked_folders, grandparent, GINT_TO_POINTER (1));
grandparent = g_file_get_parent (grandparent);
}
}
}
g_object_unref (parent);
filetype = archive_entry_filetype (entry);
if (load_data->error == NULL) {
const char  *linkname;
linkname = archive_entry_hardlink (entry);
if (linkname != NULL) {
char        *link_fullpath;
const char  *relative_path;
GFile       *link_file;
char        *oldname;
char        *newname;
int          r;
link_fullpath = (*linkname == '/') ? g_strdup (linkname) : g_strconcat ("/", linkname, NULL);
relative_path = _g_path_get_relative_basename_safe (link_fullpath, extract_data->base_dir, extract_data->junk_paths);
if (relative_path == NULL) {
g_free (link_fullpath);
archive_read_data_skip (a);
continue;
}
link_file = g_file_get_child (extract_data->destination, relative_path);
oldname = g_file_get_path (link_file);
newname = g_file_get_path (file);
if ((oldname != NULL) && (newname != NULL))
r = link (oldname, newname);
else
r = -1;
if (r == 0) {
__LA_INT64_T filesize;
if (archive_entry_size_is_set (entry))
filesize = archive_entry_size (entry);
else
filesize = -1;
if (filesize > 0)
filetype = AE_IFREG; 
}
else {
char *uri;
char *msg;
uri = g_file_get_uri (file);
msg = g_strdup_printf ("Could not create the hard link %s", uri);
load_data->error = g_error_new_literal (G_IO_ERROR, G_IO_ERROR_FAILED, msg);
g_free (msg);
g_free (uri);
}
g_free (newname);
g_free (oldname);
g_object_unref (link_file);
g_free (link_fullpath);
}
}
if (load_data->error == NULL) {
switch (filetype) {
case AE_IFDIR:
if (! g_file_make_directory (file, cancellable, &local_error)) {
if (! g_error_matches (local_error, G_IO_ERROR, G_IO_ERROR_EXISTS))
load_data->error = g_error_copy (local_error);
g_clear_error (&local_error);
}
if (load_data->error == NULL)
g_hash_table_insert (created_files, g_object_ref (file), _g_file_info_create_from_entry (entry, extract_data));
archive_read_data_skip (a);
break;
case AE_IFREG:
ostream = (GOutputStream *) g_file_replace (file, NULL, FALSE, G_FILE_CREATE_REPLACE_DESTINATION, cancellable, &load_data->error);
if (ostream == NULL)
break;
actual_offset = 0;
while ((r = archive_read_data_block (a, &buffer, &buffer_size, &target_offset)) == ARCHIVE_OK) {
gsize bytes_written;
if (target_offset > actual_offset) {
if (! _g_output_stream_add_padding (extract_data, ostream, target_offset, actual_offset, cancellable, &load_data->error))
break;
fr_archive_progress_inc_completed_bytes (load_data->archive, target_offset - actual_offset);
actual_offset = target_offset;
}
if (! g_output_stream_write_all (ostream, buffer, buffer_size, &bytes_written, cancellable, &load_data->error))
break;
actual_offset += bytes_written;
fr_archive_progress_inc_completed_bytes (load_data->archive, bytes_written);
}
if ((r == ARCHIVE_EOF) && (target_offset > actual_offset))
_g_output_stream_add_padding (extract_data, ostream, target_offset, actual_offset, cancellable, &load_data->error);
_g_object_unref (ostream);
if (r != ARCHIVE_EOF)
load_data->error = _g_error_new_from_archive_error (archive_error_string (a));
else
g_hash_table_insert (created_files, g_object_ref (file), _g_file_info_create_from_entry (entry, extract_data));
break;
case AE_IFLNK:
if (! g_file_make_symbolic_link (file, archive_entry_symlink (entry), cancellable, &local_error)) {
if (g_error_matches (local_error, G_IO_ERROR, G_IO_ERROR_EXISTS)) {
g_clear_error (&local_error);
if (g_file_delete (file, cancellable, &local_error)) {
g_clear_error (&local_error);
if (! g_file_make_symbolic_link (file, archive_entry_symlink (entry), cancellable, &local_error))
load_data->error = g_error_copy (local_error);
}
else
load_data->error = g_error_copy (local_error);
}
else
load_data->error = g_error_copy (local_error);
g_clear_error (&local_error);
}
if ((load_data->error == NULL) && _symlink_is_external_to_destination (file, archive_entry_symlink (entry), extract_data->destination, external_links))
g_hash_table_insert (external_links, g_object_ref (file), GINT_TO_POINTER (1));
archive_read_data_skip (a);
break;
default:
archive_read_data_skip (a);
break;
}
}
g_object_unref (file);
g_free (fullpath);
if (load_data->error != NULL)
break;
if ((extract_data->file_list != NULL) && (--extract_data->n_files_to_extract == 0)) {
r = ARCHIVE_EOF;
break;
}
}
if (load_data->error == NULL)
restore_original_file_attributes (created_files, cancellable);
if ((load_data->error == NULL) && (r != ARCHIVE_EOF))
load_data->error = _g_error_new_from_archive_error (archive_error_string (a));
if (load_data->error == NULL)
g_cancellable_set_error_if_cancelled (cancellable, &load_data->error);
if (load_data->error != NULL)
g_simple_async_result_set_from_error (result, load_data->error);
g_hash_table_unref (folders_created_during_extraction);
g_hash_table_unref (created_files);
g_hash_table_unref (checked_folders);
g_hash_table_unref (external_links);
archive_read_free (a);
extract_data_free (extract_data);
}

static void
extract_archive_thread (GSimpleAsyncResult *result,
GObject            *object,
GCancellable       *cancellable)
{
ExtractData          *extract_data;
LoadData             *load_data;
GHashTable           *checked_folders;
GHashTable           *created_files;
GHashTable           *folders_created_during_extraction;
GHashTable           *external_links;
struct archive       *a;
struct archive_entry *entry;
int                   r;
extract_data = g_simple_async_result_get_op_res_gpointer (result);
load_data = LOAD_DATA (extract_data);
r = create_read_object (load_data, &a);
if (r != ARCHIVE_OK) {
archive_read_free(a);
return;
}
checked_folders = g_hash_table_new_full (g_file_hash, (GEqualFunc) g_file_equal, g_object_unref, NULL);
created_files = g_hash_table_new_full (g_file_hash, (GEqualFunc) g_file_equal, g_object_unref, g_object_unref);
folders_created_during_extraction = g_hash_table_new_full (g_file_hash, (GEqualFunc) g_file_equal, g_object_unref, NULL);
external_links = g_hash_table_new_full (g_file_hash, (GEqualFunc) g_file_equal, g_object_unref, NULL);
fr_archive_progress_set_total_files (load_data->archive, extract_data->n_files_to_extract);
while ((r = archive_read_next_header (a, &entry)) == ARCHIVE_OK) {
const char    *pathname;
char          *fullpath;
const char    *relative_path;
GFile         *file;
GFile         *parent;
GOutputStream *ostream;
const void    *buffer;
size_t         buffer_size;
int64_t        target_offset, actual_offset;
GError        *local_error = NULL;
__LA_MODE_T    filetype;
if (g_cancellable_is_cancelled (cancellable))
break;
pathname = archive_entry_pathname (entry);
if (! extract_data_get_extraction_requested (extract_data, pathname)) {
archive_read_data_skip (a);
continue;
}
fullpath = (*pathname == '/') ? g_strdup (pathname) : g_strconcat ("/", pathname, NULL);
relative_path = _g_path_get_relative_basename_safe (fullpath, extract_data->base_dir, extract_data->junk_paths);
if (relative_path == NULL) {
fr_archive_progress_inc_completed_files (load_data->archive, 1);
fr_archive_progress_inc_completed_bytes (load_data->archive, archive_entry_size_is_set (entry) ? archive_entry_size (entry) : 0);
archive_read_data_skip (a);
continue;
}
if (_g_path_is_external_to_destination (relative_path, extract_data->destination, external_links)) {
fr_archive_progress_inc_completed_files (load_data->archive, 1);
fr_archive_progress_inc_completed_bytes (load_data->archive, archive_entry_size_is_set (entry) ? archive_entry_size (entry) : 0);
archive_read_data_skip (a);
continue;
}
file = g_file_get_child (extract_data->destination, relative_path);
if ((g_hash_table_lookup (folders_created_during_extraction, file) == NULL)
&& (extract_data->skip_older || ! extract_data->overwrite))
{
GFileInfo *info;
info = g_file_query_info (file,
G_FILE_ATTRIBUTE_STANDARD_DISPLAY_NAME "," G_FILE_ATTRIBUTE_TIME_MODIFIED,
G_FILE_QUERY_INFO_NONE,
cancellable,
&local_error);
if (info != NULL) {
gboolean skip = FALSE;
if (! extract_data->overwrite) {
skip = TRUE;
}
else if (extract_data->skip_older) {
GTimeVal modification_time;
g_file_info_get_modification_time (info, &modification_time);
if (archive_entry_mtime (entry) < modification_time.tv_sec)
skip = TRUE;
}
g_object_unref (info);
if (skip) {
g_object_unref (file);
archive_read_data_skip (a);
fr_archive_progress_inc_completed_bytes (load_data->archive, archive_entry_size_is_set (entry) ? archive_entry_size (entry) : 0);
if ((extract_data->file_list != NULL) && (--extract_data->n_files_to_extract == 0)) {
r = ARCHIVE_EOF;
break;
}
continue;
}
}
else {
if (! g_error_matches (local_error, G_IO_ERROR, G_IO_ERROR_NOT_FOUND)) {
load_data->error = local_error;
g_object_unref (info);
break;
}
g_clear_error (&local_error);
}
}
fr_archive_progress_inc_completed_files (load_data->archive, 1);
parent = g_file_get_parent (file);
if ((parent != NULL)
&& (g_hash_table_lookup (checked_folders, parent) == NULL)
&& ! g_file_query_exists (parent, cancellable))
{
if (! _g_file_make_directory_with_parents (parent,
folders_created_during_extraction,
cancellable,
&local_error))
{
if (! g_error_matches (local_error, G_IO_ERROR, G_IO_ERROR_EXISTS))
load_data->error = local_error;
else
g_clear_error (&local_error);
}
if (load_data->error == NULL) {
GFile *grandparent;
grandparent = g_object_ref (parent);
while (grandparent != NULL) {
if (g_hash_table_lookup (checked_folders, grandparent) == NULL)
g_hash_table_insert (checked_folders, grandparent, GINT_TO_POINTER (1));
grandparent = g_file_get_parent (grandparent);
}
}
}
g_object_unref (parent);
filetype = archive_entry_filetype (entry);
if (load_data->error == NULL) {
const char  *linkname;
linkname = archive_entry_hardlink (entry);
if (linkname != NULL) {
char        *link_fullpath;
const char  *relative_path;
GFile       *link_file;
char        *oldname;
char        *newname;
int          r;
link_fullpath = (*linkname == '/') ? g_strdup (linkname) : g_strconcat ("/", linkname, NULL);
relative_path = _g_path_get_relative_basename_safe (link_fullpath, extract_data->base_dir, extract_data->junk_paths);
if (relative_path == NULL) {
g_free (link_fullpath);
archive_read_data_skip (a);
continue;
}
link_file = g_file_get_child (extract_data->destination, relative_path);
oldname = g_file_get_path (link_file);
newname = g_file_get_path (file);
if ((oldname != NULL) && (newname != NULL))
r = link (oldname, newname);
else
r = -1;
if (r == 0) {
__LA_INT64_T filesize;
if (archive_entry_size_is_set (entry))
filesize = archive_entry_size (entry);
else
filesize = -1;
if (filesize > 0)
filetype = AE_IFREG; 
}
else {
char *uri;
char *msg;
uri = g_file_get_uri (file);
msg = g_strdup_printf ("Could not create the hard link %s", uri);
load_data->error = g_error_new_literal (G_IO_ERROR, G_IO_ERROR_FAILED, msg);
g_free (msg);
g_free (uri);
}
g_free (newname);
g_free (oldname);
g_object_unref (link_file);
g_free (link_fullpath);
}
}
if (load_data->error == NULL) {
switch (filetype) {
case AE_IFDIR:
if (! g_file_make_directory (file, cancellable, &local_error)) {
if (! g_error_matches (local_error, G_IO_ERROR, G_IO_ERROR_EXISTS))
load_data->error = g_error_copy (local_error);
g_clear_error (&local_error);
}
if (load_data->error == NULL)
g_hash_table_insert (created_files, g_object_ref (file), _g_file_info_create_from_entry (entry, extract_data));
archive_read_data_skip (a);
break;
case AE_IFREG:
ostream = (GOutputStream *) g_file_replace (file, NULL, FALSE, G_FILE_CREATE_REPLACE_DESTINATION, cancellable, &load_data->error);
if (ostream == NULL)
break;
actual_offset = 0;
while ((r = archive_read_data_block (a, &buffer, &buffer_size, &target_offset)) == ARCHIVE_OK) {
gsize bytes_written;
if (target_offset > actual_offset) {
if (! _g_output_stream_add_padding (extract_data, ostream, target_offset, actual_offset, cancellable, &load_data->error))
break;
fr_archive_progress_inc_completed_bytes (load_data->archive, target_offset - actual_offset);
actual_offset = target_offset;
}
if (! g_output_stream_write_all (ostream, buffer, buffer_size, &bytes_written, cancellable, &load_data->error))
break;
actual_offset += bytes_written;
fr_archive_progress_inc_completed_bytes (load_data->archive, bytes_written);
}
if ((r == ARCHIVE_EOF) && (target_offset > actual_offset))
_g_output_stream_add_padding (extract_data, ostream, target_offset, actual_offset, cancellable, &load_data->error);
_g_object_unref (ostream);
if (r != ARCHIVE_EOF)
load_data->error = _g_error_new_from_archive_error (archive_error_string (a));
else
g_hash_table_insert (created_files, g_object_ref (file), _g_file_info_create_from_entry (entry, extract_data));
break;
case AE_IFLNK:
if (! g_file_make_symbolic_link (file, archive_entry_symlink (entry), cancellable, &local_error)) {
if (g_error_matches (local_error, G_IO_ERROR, G_IO_ERROR_EXISTS)) {
g_clear_error (&local_error);
if (g_file_delete (file, cancellable, &local_error)) {
g_clear_error (&local_error);
if (! g_file_make_symbolic_link (file, archive_entry_symlink (entry), cancellable, &local_error))
load_data->error = g_error_copy (local_error);
}
else
load_data->error = g_error_copy (local_error);
}
else
load_data->error = g_error_copy (local_error);
g_clear_error (&local_error);
}
if ((load_data->error == NULL) && _symlink_is_external_to_destination (file, archive_entry_symlink (entry), extract_data->destination, external_links))
g_hash_table_insert (external_links, g_object_ref (file), GINT_TO_POINTER (1));
archive_read_data_skip (a);
break;
default:
archive_read_data_skip (a);
break;
}
}
g_object_unref (file);
g_free (fullpath);
if (load_data->error != NULL)
break;
if ((extract_data->file_list != NULL) && (--extract_data->n_files_to_extract == 0)) {
r = ARCHIVE_EOF;
break;
}
}
if (load_data->error == NULL)
restore_original_file_attributes (created_files, cancellable);
if ((load_data->error == NULL) && (r != ARCHIVE_EOF))
load_data->error = _g_error_new_from_archive_error (archive_error_string (a));
if (load_data->error == NULL)
g_cancellable_set_error_if_cancelled (cancellable, &load_data->error);
if (load_data->error != NULL)
g_simple_async_result_set_from_error (result, load_data->error);
g_hash_table_unref (folders_created_during_extraction);
g_hash_table_unref (created_files);
g_hash_table_unref (checked_folders);
g_hash_table_unref (external_links);
archive_read_free (a);
extract_data_free (extract_data);
}

int
table_regex_match(const char *string, const char *pattern)
{
regex_t preg;
intcflags = REG_EXTENDED|REG_NOSUB;
if (strncmp(pattern, "(?i)", 4) == 0) {
cflags |= REG_ICASE;
pattern += 4;
}
if (regcomp(&preg, pattern, cflags) != 0)
return (0);
if (regexec(&preg, string, 0, NULL, 0) != 0)
return (0);
return (1);
}

char *QueryBackgroundColor() {
const Duration kTimeBudget = Duration::Millis(1500);
constexpr char query_background_color[] = "\033]11;?\033\\";
constexpr size_t kColorLen = 18;  
char buffer[512];
const char *const start_color = QueryTerminal(
query_background_color, buffer, sizeof(buffer), kTimeBudget,
[](const char *data, size_t len) -> const char * {
const char *found = (const char *)memmem(data, len, "rgb:", 4);
if (found && len - (found - data) > kColorLen)                  return found;                                             return nullptr;
});
if (!start_color) return nullptr;
buffer[0] = '#';
memcpy(&buffer[1], &start_color[4], 2);
memcpy(&buffer[3], &start_color[9], 2);
memcpy(&buffer[5], &start_color[14], 2);
buffer[7] = '\0';
return strdup(buffer);
}

int fmt_mtm_load_song(song_t *song, slurp_t *fp, unsigned int lflags)
{
uint8_t b[192];
int16_t ntrk, nchan, nord, npat, nsmp; uint16_t comment_len;
int n, pat, chan, smp, rows, todo = 0;
song_note_t *note;
uint16_t tmp;
uint32_t tmplong;
song_note_t **trackdata, *tracknote;
song_sample_t *sample;
slurp_read(fp, b, 3);
if (memcmp(b, "MTM", 3) != 0)
return LOAD_UNSUPPORTED;
n = slurp_getc(fp);
sprintf(song->tracker_id, "MultiTracker %d.%d", n >> 4, n & 0xf);
slurp_read(fp, song->title, 20);
song->title[20] = 0;
slurp_read(fp, &ntrk, 2);
ntrk = bswapLE16(ntrk);
npat = slurp_getc(fp);
nord = slurp_getc(fp) + 1;
slurp_read(fp, &comment_len, 2);
comment_len = bswapLE16(comment_len);
nsmp = slurp_getc(fp);
slurp_getc(fp); 
rows = slurp_getc(fp); 
if (rows != 64)
todo |= 64;
rows = MIN(rows, 64);
nchan = slurp_getc(fp);
for (n = 0; n < 32; n++) {
int pan = slurp_getc(fp) & 0xf;
pan = SHORT_PANNING(pan);
pan *= 4; song->channels[n].panning = pan;
}
for (n = nchan; n < MAX_CHANNELS; n++)
song->channels[n].flags = CHN_MUTE;
for (n = 1, sample = song->samples + 1; n <= nsmp; n++, sample++) {
if (n > MAX_SAMPLES) {
slurp_seek(fp, 37, SEEK_CUR);
continue;
}
char name[23];
slurp_read(fp, name, 22);
name[22] = '\0';
strcpy(sample->name, name);
slurp_read(fp, &tmplong, 4);
sample->length = bswapLE32(tmplong);
slurp_read(fp, &tmplong, 4);
sample->loop_start = bswapLE32(tmplong);
slurp_read(fp, &tmplong, 4);
sample->loop_end = bswapLE32(tmplong);
if ((sample->loop_end - sample->loop_start) > 2) {
sample->flags |= CHN_LOOP;
} else {
sample->loop_start = 0;
sample->loop_end = 0;
}
song->samples[n].c5speed = MOD_FINETUNE(slurp_getc(fp));
sample->volume = slurp_getc(fp);
sample->volume *= 4; sample->global_volume = 64;
if (slurp_getc(fp) & 1) {
todo |= 16;
sample->flags |= CHN_16BIT;
sample->length >>= 1;
sample->loop_start >>= 1;
sample->loop_end >>= 1;
}
song->samples[n].vib_type = 0;
song->samples[n].vib_rate = 0;
song->samples[n].vib_depth = 0;
song->samples[n].vib_speed = 0;
}
slurp_read(fp, song->orderlist, 128);
memset(song->orderlist + nord, ORDER_LAST, MAX_ORDERS - nord);
trackdata = mem_calloc(ntrk, sizeof(song_note_t *));
for (n = 0; n < ntrk; n++) {
slurp_read(fp, b, 3 * rows);
trackdata[n] = mem_calloc(rows, sizeof(song_note_t));
mtm_unpack_track(b, trackdata[n], rows);
}
for (pat = 0; pat <= npat; pat++) {
song->patterns[pat] = csf_allocate_pattern(MAX(rows, 32));
song->pattern_size[pat] = song->pattern_alloc_size[pat] = 64;
tracknote = trackdata[n];
for (chan = 0; chan < 32; chan++) {
slurp_read(fp, &tmp, 2);
tmp = bswapLE16(tmp);
if (tmp == 0) {
continue;
} else if (tmp > ntrk) {
for (n = 0; n < ntrk; n++)
free(trackdata[n]);
free(trackdata);
return LOAD_FORMAT_ERROR;
}
note = song->patterns[pat] + chan;
tracknote = trackdata[tmp - 1];
for (n = 0; n < rows; n++, tracknote++, note += MAX_CHANNELS)
*note = *tracknote;
}
if (rows < 32) {
note = song->patterns[pat] + 64 * (rows - 1);
while (note->effect || note->param)
note++;
note->effect = FX_PATTERNBREAK;
}
}
for (n = 0; n < ntrk; n++)
free(trackdata[n]);
free(trackdata);
read_lined_message(song->message, fp, comment_len, 40);
if (!(lflags & LOAD_NOSAMPLES)) {
for (smp = 1; smp <= nsmp && smp <= MAX_SAMPLES; smp++) {
uint32_t ssize;
if (song->samples[smp].length == 0)
continue;
ssize = csf_read_sample(song->samples + smp,
(SF_LE | SF_PCMU | SF_M
| ((song->samples[smp].flags & CHN_16BIT) ? SF_16 : SF_8)),
fp->data + fp->pos, fp->length - fp->pos);
slurp_seek(fp, ssize, SEEK_CUR);
}
}
song->flags = SONG_ITOLDEFFECTS | SONG_COMPATGXX;
if (todo & 64)
log_appendf(2, " TODO: test this file with other players (beats per track != 64)");
if (todo & 16)
log_appendf(2, " TODO: double check 16 bit sample loading");
return LOAD_SUCCESS;
}

void PdfParser::readObjectsInternal(InputStreamDevice& device)
{
vector<unsigned> compressedIndices;
map<int64_t, vector<int64_t>> compressedObjects;
for (unsigned i = 0; i < m_entries.GetSize(); i++)
{
auto& entry = m_entries[i];
#ifdef PODOFO_VERBOSE_DEBUG
cerr << "ReadObjectsInteral\t" << i << " "
<< (entry.Parsed ? "parsed" : "unparsed") << " "
<< entry.Offset << " "
<< entry.Generation << endl;
#endif
if (entry.Parsed)
{
switch (entry.Type)
{
case XRefEntryType::InUse:
{
if (entry.Offset > 0)
{
PdfReference reference(i, (uint16_t)entry.Generation);
unique_ptr<PdfParserObject> obj(new PdfParserObject(m_Objects->GetDocument(), reference, device, (ssize_t)entry.Offset));
try
{
obj->SetEncrypt(m_Encrypt.get());
if (m_Encrypt != nullptr && obj->IsDictionary())
{
auto typeObj = obj->GetDictionary().GetKey(PdfName::KeyType);
if (typeObj != nullptr && typeObj->IsName() && typeObj->GetName() == "XRef")
{
obj.reset(new PdfParserObject(m_Objects->GetDocument(), reference, device, (ssize_t)entry.Offset));
if (m_LoadOnDemand)
obj->DelayedLoad();
}
}
m_Objects->PushObject(obj.release());
}
catch (PdfError& e)
{
if (m_IgnoreBrokenObjects)
{
PoDoFo::LogMessage(PdfLogSeverity::Error, "Error while loading object {} {} R, Offset={}, Index={}",
obj->GetIndirectReference().ObjectNumber(),
obj->GetIndirectReference().GenerationNumber(),
entry.Offset, i);
m_Objects->SafeAddFreeObject(reference);
}
else
{
PODOFO_PUSH_FRAME_INFO(e, "Error while loading object {} {} R, Offset={}, Index={}",
obj->GetIndirectReference().ObjectNumber(),
obj->GetIndirectReference().GenerationNumber(),
entry.Offset, i);
throw e;
}
}
}
else if (entry.Generation == 0)
{
PODOFO_ASSERT(entry.Offset == 0);
if (m_StrictParsing)
{
PODOFO_RAISE_ERROR_INFO(PdfErrorCode::InvalidXRef,
"Found object with 0 offset which should be 'f' instead of 'n'");
}
else
{
PoDoFo::LogMessage(PdfLogSeverity::Warning,
"Treating object {} 0 R as a free object", i);
m_Objects->AddFreeObject(PdfReference(i, 1));
}
}
break;
}
case XRefEntryType::Free:
{
if (i != 0)
m_Objects->SafeAddFreeObject(PdfReference(i, (uint16_t)entry.Generation));
break;
}
case XRefEntryType::Compressed:
compressedObjects[entry.ObjectNumber].push_back(i);
break;
default:
PODOFO_RAISE_ERROR(PdfErrorCode::InvalidEnumValue);
}
}
else if (i != 0)         {
m_Objects->AddFreeObject(PdfReference(i, 1));
}
}
for (auto& pair : compressedObjects)
{
#ifndef VERBOSE_DEBUG_DISABLED
if (m_LoadOnDemand)
cerr << "Demand loading on, but can't demand-load from object stream." << endl;
#endif
readCompressedObjectFromStream((uint32_t)pair.first, pair.second);
m_Objects->AddObjectStream((uint32_t)pair.first);
}
if (!m_LoadOnDemand)
{
for (auto objToLoad : *m_Objects)
{
auto obj = dynamic_cast<PdfParserObject*>(objToLoad);
obj->ParseStream();
}
}
updateDocumentVersion();
}

static Image *ReadDPSImage(const ImageInfo *image_info,ExceptionInfo *exception)
{
const char
*client_name;
Display
*display;
float
pixels_per_point;
Image
*image;
int
sans,
status;
Pixmap
pixmap;
register ssize_t
i;
register Quantum
*q;
register size_t
pixel;
Screen
*screen;
ssize_t
x,
y;
XColor
*colors;
XImage
*dps_image;
XRectangle
page,
bits_per_pixel;
XResourceInfo
resource_info;
XrmDatabase
resource_database;
XStandardColormap
*map_info;
XVisualInfo
*visual_info;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickCoreSignature);
if (image_info->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
image_info->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
display=XOpenDisplay(image_info->server_name);
if (display == (Display *) NULL)
return((Image *) NULL);
(void) XSetErrorHandler(XError);
image=AcquireImage(image_info,exception);
status=OpenBlob(image_info,image,ReadBinaryBlobMode,exception);
if (status == MagickFalse)
return((Image *) NULL);
client_name=GetClientName();
resource_database=XGetResourceDatabase(display,client_name);
XGetResourceInfo(image_info,resource_database,client_name,&resource_info);
map_info=XAllocStandardColormap();
visual_info=(XVisualInfo *) NULL;
if (map_info == (XStandardColormap *) NULL)
ThrowReaderException(ResourceLimitError,"UnableToCreateStandardColormap")
else
{
(void) CloneString(&resource_info.visual_type,"default");
visual_info=XBestVisualInfo(display,map_info,&resource_info);
map_info->colormap=(Colormap) NULL;
}
if ((map_info == (XStandardColormap *) NULL) ||
(visual_info == (XVisualInfo *) NULL))
{
image=DestroyImage(image);
XFreeResources(display,visual_info,map_info,(XPixelInfo *) NULL,
(XFontStruct *) NULL,&resource_info,(XWindowInfo *) NULL);
return((Image *) NULL);
}
screen=ScreenOfDisplay(display,visual_info->screen);
pixels_per_point=XDPSPixelsPerPoint(screen);
if ((image->resolution.x != 0.0) && (image->resolution.y != 0.0))
pixels_per_point=MagickMin(image->resolution.x,image->resolution.y)/
DefaultResolution;
status=XDPSCreatePixmapForEPSF((DPSContext) NULL,screen,
GetBlobFileHandle(image),visual_info->depth,pixels_per_point,&pixmap,
&bits_per_pixel,&page);
if ((status == dps_status_failure) || (status == dps_status_no_extension))
{
image=DestroyImage(image);
XFreeResources(display,visual_info,map_info,(XPixelInfo *) NULL,
(XFontStruct *) NULL,&resource_info,(XWindowInfo *) NULL);
return((Image *) NULL);
}
status=XDPSImageFileIntoDrawable((DPSContext) NULL,screen,pixmap,
GetBlobFileHandle(image),(int) bits_per_pixel.height,visual_info->depth,
&page,-page.x,-page.y,pixels_per_point,MagickTrue,MagickFalse,MagickTrue,
&sans);
if (status != dps_status_success)
{
image=DestroyImage(image);
XFreeResources(display,visual_info,map_info,(XPixelInfo *) NULL,
(XFontStruct *) NULL,&resource_info,(XWindowInfo *) NULL);
return((Image *) NULL);
}
dps_image=XGetImage(display,pixmap,0,0,bits_per_pixel.width,
bits_per_pixel.height,AllPlanes,ZPixmap);
(void) XFreePixmap(display,pixmap);
if (dps_image == (XImage *) NULL)
{
image=DestroyImage(image);
XFreeResources(display,visual_info,map_info,(XPixelInfo *) NULL,
(XFontStruct *) NULL,&resource_info,(XWindowInfo *) NULL);
return((Image *) NULL);
}
colors=(XColor *) AcquireQuantumMemory(visual_info->colormap_size,
sizeof(*colors));
if (colors == (XColor *) NULL)
{
image=DestroyImage(image);
XDestroyImage(dps_image);
XFreeResources(display,visual_info,map_info,(XPixelInfo *) NULL,
(XFontStruct *) NULL,&resource_info,(XWindowInfo *) NULL);
return((Image *) NULL);
}
if ((visual_info->klass != DirectColor) && (visual_info->klass != TrueColor))
for (i=0; i < visual_info->colormap_size; i++)
{
colors[i].pixel=(size_t) i;
colors[i].pad=0;
}
else
{
size_t
blue,
blue_bit,
green,
green_bit,
red,
red_bit;
red=0;
green=0;
blue=0;
red_bit=visual_info->red_mask & (~(visual_info->red_mask)+1);
green_bit=visual_info->green_mask & (~(visual_info->green_mask)+1);
blue_bit=visual_info->blue_mask & (~(visual_info->blue_mask)+1);
for (i=0; i < visual_info->colormap_size; i++)
{
colors[i].pixel=red | green | blue;
colors[i].pad=0;
red+=red_bit;
if (red > visual_info->red_mask)
red=0;
green+=green_bit;
if (green > visual_info->green_mask)
green=0;
blue+=blue_bit;
if (blue > visual_info->blue_mask)
blue=0;
}
}
(void) XQueryColors(display,XDefaultColormap(display,visual_info->screen),
colors,visual_info->colormap_size);
if ((visual_info->klass != TrueColor) && (visual_info->klass != DirectColor))
image->storage_class=PseudoClass;
image->columns=(size_t) dps_image->width;
image->rows=(size_t) dps_image->height;
if (image_info->ping != MagickFalse)
{
(void) CloseBlob(image);
colors=(XColor *) RelinquishMagickMemory(colors);
XDestroyImage(dps_image);
XFreeResources(display,visual_info,map_info,(XPixelInfo *) NULL,
(XFontStruct *) NULL,&resource_info,(XWindowInfo *) NULL);
return(GetFirstImageInList(image));
}
status=SetImageExtent(image,image->columns,image->rows,exception);
if (status == MagickFalse)
{
colors=(XColor *) RelinquishMagickMemory(colors);
XDestroyImage(dps_image);
XFreeResources(display,visual_info,map_info,(XPixelInfo *) NULL,
(XFontStruct *) NULL,&resource_info,(XWindowInfo *) NULL);
return(DestroyImageList(image));
}
switch (image->storage_class)
{
case DirectClass:
default:
{
register size_t
color,
index;
size_t
blue_mask,
blue_shift,
green_mask,
green_shift,
red_mask,
red_shift;
red_mask=visual_info->red_mask;
red_shift=0;
while ((red_mask != 0) && ((red_mask & 0x01) == 0))
{
red_mask>>=1;
red_shift++;
}
green_mask=visual_info->green_mask;
green_shift=0;
while ((green_mask != 0) && ((green_mask & 0x01) == 0))
{
green_mask>>=1;
green_shift++;
}
blue_mask=visual_info->blue_mask;
blue_shift=0;
while ((blue_mask != 0) && ((blue_mask & 0x01) == 0))
{
blue_mask>>=1;
blue_shift++;
}
if ((visual_info->colormap_size > 0) &&
(visual_info->klass == DirectColor))
for (y=0; y < (ssize_t) image->rows; y++)
{
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < (ssize_t) image->columns; x++)
{
pixel=XGetPixel(dps_image,x,y);
index=(pixel >> red_shift) & red_mask;
SetPixelRed(image,ScaleShortToQuantum(colors[index].red),q);
index=(pixel >> green_shift) & green_mask;
SetPixelGreen(image,ScaleShortToQuantum(colors[index].green),q);
index=(pixel >> blue_shift) & blue_mask;
SetPixelBlue(image,ScaleShortToQuantum(colors[index].blue),q);
q+=GetPixelChannels(image);
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
if (SetImageProgress(image,LoadImageTag,y,image->rows) == MagickFalse)
break;
}
else
for (y=0; y < (ssize_t) image->rows; y++)
{
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < (ssize_t) image->columns; x++)
{
pixel=XGetPixel(dps_image,x,y);
color=(pixel >> red_shift) & red_mask;
color=(color*65535L)/red_mask;
SetPixelRed(image,ScaleShortToQuantum((unsigned short) color),q);
color=(pixel >> green_shift) & green_mask;
color=(color*65535L)/green_mask;
SetPixelGreen(image,ScaleShortToQuantum((unsigned short) color),q);
color=(pixel >> blue_shift) & blue_mask;
color=(color*65535L)/blue_mask;
SetPixelBlue(image,ScaleShortToQuantum((unsigned short) color),q);
q+=GetPixelChannels(image);
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
if (SetImageProgress(image,LoadImageTag,y,image->rows) == MagickFalse)
break;
}
break;
}
case PseudoClass:
{
if (AcquireImageColormap(image,(size_t) visual_info->colormap_size,exception) == MagickFalse)
{
image=DestroyImage(image);
colors=(XColor *) RelinquishMagickMemory(colors);
XDestroyImage(dps_image);
XFreeResources(display,visual_info,map_info,(XPixelInfo *) NULL,
(XFontStruct *) NULL,&resource_info,(XWindowInfo *) NULL);
return((Image *) NULL);
}
for (i=0; i < (ssize_t) image->colors; i++)
{
image->colormap[colors[i].pixel].red=ScaleShortToQuantum(colors[i].red);
image->colormap[colors[i].pixel].green=
ScaleShortToQuantum(colors[i].green);
image->colormap[colors[i].pixel].blue=
ScaleShortToQuantum(colors[i].blue);
}
for (y=0; y < (ssize_t) image->rows; y++)
{
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < (ssize_t) image->columns; x++)
{
SetPixelIndex(image,(unsigned short) XGetPixel(dps_image,x,y),q);
q+=GetPixelChannels(image);
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
if (SetImageProgress(image,LoadImageTag,y,image->rows) == MagickFalse)
break;
}
break;
}
}
colors=(XColor *) RelinquishMagickMemory(colors);
XDestroyImage(dps_image);
if (image->storage_class == PseudoClass)
(void) SyncImage(image,exception);
status=XDPSCreatePixmapForEPSF((DPSContext) NULL,screen,
GetBlobFileHandle(image),1,pixels_per_point,&pixmap,&bits_per_pixel,&page);
if ((status != dps_status_failure) && (status != dps_status_no_extension))
{
status=XDPSImageFileIntoDrawable((DPSContext) NULL,screen,pixmap,
GetBlobFileHandle(image),(int) bits_per_pixel.height,1,&page,-page.x,
-page.y,pixels_per_point,MagickTrue,MagickTrue,MagickTrue,&sans);
if (status == dps_status_success)
{
XImage
*matte_image;
matte_image=XGetImage(display,pixmap,0,0,bits_per_pixel.width,
bits_per_pixel.height,AllPlanes,ZPixmap);
(void) XFreePixmap(display,pixmap);
if (matte_image != (XImage *) NULL)
{
image->storage_class=DirectClass;
image->alpha_trait=BlendPixelTrait;
for (y=0; y < (ssize_t) image->rows; y++)
{
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < (ssize_t) image->columns; x++)
{
SetPixelAlpha(image,OpaqueAlpha,q);
if (XGetPixel(matte_image,x,y) == 0)
SetPixelAlpha(image,TransparentAlpha,q);
q+=GetPixelChannels(image);
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
}
XDestroyImage(matte_image);
}
}
}
XFreeResources(display,visual_info,map_info,(XPixelInfo *) NULL,
(XFontStruct *) NULL,&resource_info,(XWindowInfo *) NULL);
(void) CloseBlob(image);
return(GetFirstImageInList(image));
}

void nego_process_negotiation_request(rdpNego* nego, wStream* s)
{
