}
hdr->sample_rate = freq;
hdr->framesize += framesize;
if (strmtyp != 1) {
assert(cur_main_id == substreamid);
hdr->streams[substreamid].lfon = lfon;
hdr->streams[substreamid].bsid = bsid;
hdr->streams[substreamid].bsmod = bsmod;
hdr->streams[substreamid].acmod = acmod;
hdr->streams[substreamid].fscod = fscod;
hdr->brcode = 0;
hdr->nb_streams++;
}
else {
hdr->streams[cur_main_id].nb_dep_sub = substreamid;
hdr->streams[cur_main_id].chan_loc |= chanmap;
}
hdr->brcode += ((frmsiz+1) * freq) / (numblks[numblkscod]*16) / 1000;
if (!full_parse) {
eac3_update_channels(hdr);
gf_bs_seek(bs, pos);
return GF_TRUE;
}
if (gf_bs_read_int(bs, 1)) {
if (acmod > 0x2) gf_bs_read_int(bs, 2);
if ((acmod & 0x1) && (acmod > 0x2)) gf_bs_read_int(bs, 6);
if (acmod & 0x4) gf_bs_read_int(bs, 6);
if (lfon) {
if (gf_bs_read_int(bs, 1))
gf_bs_read_int(bs, 5);
}
if (strmtyp == 0) {
if (gf_bs_read_int(bs, 1))
gf_bs_read_int(bs, 6);
if (acmod==0) {
if (gf_bs_read_int(bs, 1))
gf_bs_read_int(bs, 6);
}
if (gf_bs_read_int(bs, 1))
gf_bs_read_int(bs, 6);
u8 mixdef = gf_bs_read_int(bs, 2);
if (mixdef == 0x1) {
gf_bs_read_int(bs, 5);
} else if (mixdef == 0x2) {
gf_bs_read_int(bs, 12);
} else if (mixdef == 0x3) {
u32 mixdeflen = gf_bs_read_int(bs, 5);
mixdeflen = 8 * (mixdeflen + 2);
while (mixdeflen) {
gf_bs_read_int(bs, 1);
mixdeflen--;
}
}
if (acmod < 0x2) {
if (gf_bs_read_int(bs, 1))
gf_bs_read_int(bs, 14);
if (acmod == 0) {
if (gf_bs_read_int(bs, 1))
gf_bs_read_int(bs, 14);
}
}
if (gf_bs_read_int(bs, 1)) {
if (numblkscod == 0x0) {
gf_bs_read_int(bs, 5);
} else {
u32 i, nb_blocks = numblks[numblkscod];
for (i=0; i<nb_blocks; i++) {
if (gf_bs_read_int(bs, 1))
gf_bs_read_int(bs, 5);
}
}
}
}
}
if (gf_bs_read_int(bs, 1)) {
gf_bs_read_int(bs, 5);
if (acmod == 0x2) gf_bs_read_int(bs, 4);
if (acmod >= 0x6) gf_bs_read_int(bs, 2);
if (gf_bs_read_int(bs, 1)) gf_bs_read_int(bs, 8);
if (acmod == 0x0) {
if (gf_bs_read_int(bs, 1)) gf_bs_read_int(bs, 8);
}
if (fscod < 0x3)  gf_bs_read_int(bs, 1);
}
if ((strmtyp == 0) && (numblkscod != 0x3)) gf_bs_read_int(bs, 1);
if (strmtyp == 0x2) {
u32 blkid=0;
if (numblkscod == 0x3) blkid=1;
else blkid = gf_bs_read_int(bs, 1);
if (blkid) gf_bs_read_int(bs, 6);
}
u8 addbsie = gf_bs_read_int(bs, 1);
if (addbsie) {
u32 addbsil = gf_bs_read_int(bs, 6) + 1;
if (addbsil>=2) {
gf_bs_read_int(bs, 7);
if (gf_bs_read_int(bs, 1)) {
hdr->atmos_ec3_ext = 1;
hdr->complexity_index_type = gf_bs_read_int(bs, 8);
}
}
}
if (strmtyp!=0x1) {
nb_blocks_main += numblks[numblkscod];
}
if (gf_bs_seek(bs, hdr_pos + framesize) != GF_OK) {
gf_bs_seek(bs, pos);
return GF_FALSE;
}
if (!AC3_FindSyncCodeBS(bs)) {
gf_bs_seek(bs, pos);
return GF_FALSE;
}
goto next_block;
}

static u8 BS_ReadByte(GF_BitStream *bs)
{
Bool is_eos;
if (bs->bsmode == GF_BITSTREAM_READ) {
u8 res;
if (bs->position >= bs->size) {
if (bs->EndOfStream) bs->EndOfStream(bs->par);
if (!bs->overflow_state) bs->overflow_state = 1;
return 0;
}
res = bs->original[bs->position++];
if (bs->remove_emul_prevention_byte) {
if ((bs->nb_zeros==2) && (res==0x03) && (bs->position<bs->size) && (bs->original[bs->position]<0x04)) {
bs->nb_zeros = 0;
res = bs->original[bs->position++];
}
if (!res) bs->nb_zeros++;
else bs->nb_zeros = 0;
}
return res;
}
if (bs->cache_write)
bs_flush_write_cache(bs);
is_eos = gf_feof(bs->stream);
if (!is_eos || bs->cache_read) {
u8 res;
Bool loc_eos=GF_FALSE;
assert(bs->position<=bs->size);
bs->position++;
res = gf_bs_load_byte(bs, &loc_eos);
if (loc_eos) goto bs_eof;
if (bs->remove_emul_prevention_byte) {
if ((bs->nb_zeros==2) && (res==0x03) && (bs->position<bs->size)) {
u8 next = gf_bs_load_byte(bs, &loc_eos);
if (next < 0x04) {
bs->nb_zeros = 0;
res = next;
bs->position++;
} else {
gf_bs_seek(bs, bs->position);
}
}
if (!res) bs->nb_zeros++;
else bs->nb_zeros = 0;
}
return res;
}
bs_eof:
if (bs->EndOfStream) {
bs->EndOfStream(bs->par);
if (!bs->overflow_state) bs->overflow_state = 1;
} else {
GF_LOG(GF_LOG_ERROR, GF_LOG_CORE, ("[BS] Attempt to overread bitstream\n"));
}
assert(bs->position <= 1+bs->size);
return 0;
}

static int __ipmi_bmc_register(struct ipmi_smi *intf,
struct ipmi_device_id *id,
bool guid_set, guid_t *guid, int intf_num)
{
int               rv;
struct bmc_device *bmc;
struct bmc_device *old_bmc;
intf->in_bmc_register = true;
mutex_unlock(&intf->bmc_reg_mutex);
mutex_lock(&ipmidriver_mutex);
if (guid_set)
old_bmc = ipmi_find_bmc_guid(&ipmidriver.driver, guid);
else
old_bmc = ipmi_find_bmc_prod_dev_id(&ipmidriver.driver,
id->product_id,
id->device_id);
if (old_bmc) {
bmc = old_bmc;
intf->bmc = old_bmc;
mutex_lock(&bmc->dyn_mutex);
list_add_tail(&intf->bmc_link, &bmc->intfs);
mutex_unlock(&bmc->dyn_mutex);
dev_info(intf->si_dev,
"interfacing existing BMC (man_id: 0x%6.6x, prod_id: 0x%4.4x, dev_id: 0x%2.2x)\n",
bmc->id.manufacturer_id,
bmc->id.product_id,
bmc->id.device_id);
} else {
bmc = kzalloc(sizeof(*bmc), GFP_KERNEL);
if (!bmc) {
rv = -ENOMEM;
goto out;
}
INIT_LIST_HEAD(&bmc->intfs);
mutex_init(&bmc->dyn_mutex);
INIT_WORK(&bmc->remove_work, cleanup_bmc_work);
bmc->id = *id;
bmc->dyn_id_set = 1;
bmc->dyn_guid_set = guid_set;
bmc->guid = *guid;
bmc->dyn_id_expiry = jiffies + IPMI_DYN_DEV_ID_EXPIRY;
bmc->pdev.name = "ipmi_bmc";
rv = ida_simple_get(&ipmi_bmc_ida, 0, 0, GFP_KERNEL);
if (rv < 0)
goto out;
bmc->pdev.dev.driver = &ipmidriver.driver;
bmc->pdev.id = rv;
bmc->pdev.dev.release = release_bmc_device;
bmc->pdev.dev.type = &bmc_device_type;
kref_init(&bmc->usecount);
intf->bmc = bmc;
mutex_lock(&bmc->dyn_mutex);
list_add_tail(&intf->bmc_link, &bmc->intfs);
mutex_unlock(&bmc->dyn_mutex);
rv = platform_device_register(&bmc->pdev);
if (rv) {
dev_err(intf->si_dev,
"Unable to register bmc device: %d\n",
rv);
goto out_list_del;
}
dev_info(intf->si_dev,
"Found new BMC (man_id: 0x%6.6x, prod_id: 0x%4.4x, dev_id: 0x%2.2x)\n",
bmc->id.manufacturer_id,
bmc->id.product_id,
bmc->id.device_id);
}
rv = sysfs_create_link(&intf->si_dev->kobj, &bmc->pdev.dev.kobj, "bmc");
if (rv) {
dev_err(intf->si_dev, "Unable to create bmc symlink: %d\n", rv);
goto out_put_bmc;
}
if (intf_num == -1)
intf_num = intf->intf_num;
intf->my_dev_name = kasprintf(GFP_KERNEL, "ipmi%d", intf_num);
if (!intf->my_dev_name) {
rv = -ENOMEM;
dev_err(intf->si_dev, "Unable to allocate link from BMC: %d\n",
rv);
goto out_unlink1;
}
rv = sysfs_create_link(&bmc->pdev.dev.kobj, &intf->si_dev->kobj,
intf->my_dev_name);
if (rv) {
kfree(intf->my_dev_name);
intf->my_dev_name = NULL;
dev_err(intf->si_dev, "Unable to create symlink to bmc: %d\n",
rv);
goto out_free_my_dev_name;
}
intf->bmc_registered = true;
out:
mutex_unlock(&ipmidriver_mutex);
mutex_lock(&intf->bmc_reg_mutex);
intf->in_bmc_register = false;
return rv;
out_free_my_dev_name:
