if ((runlength == (unsigned char *) NULL) ||
(buffer == (unsigned char *) NULL) ||
(scanline == (unsigned char *) NULL))
{
if (runlength != (unsigned char *) NULL)
runlength=(unsigned char *) RelinquishMagickMemory(runlength);
if (buffer != (unsigned char *) NULL)
buffer=(unsigned char *) RelinquishMagickMemory(buffer);
if (scanline != (unsigned char *) NULL)
scanline=(unsigned char *) RelinquishMagickMemory(scanline);
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
}
(void) ResetMagickMemory(buffer,0,512*sizeof(*buffer));
if (IssRGBCompatibleColorspace(image->colorspace) == MagickFalse)
(void) TransformImageColorspace(image,sRGBColorspace);
quantum_info=AcquireQuantumInfo(image_info,image);
if (quantum_info == (QuantumInfo *) NULL)
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
status=SetQuantumDepth(image,quantum_info,image->depth > 8 ? 16 : 8);
bits=8/(int) bits_per_pixel-1;  
literal=0;
repeat=0;
q=runlength;
buffer[0]=0x00;
for (y=0; y < (ssize_t) image->rows; y++)
{
p=GetVirtualPixels(image,0,y,image->columns,1,&image->exception);
if (p == (const PixelPacket *) NULL)
break;
(void) ExportQuantumPixels(image,(const CacheView *) NULL,quantum_info,
GrayQuantum,scanline,&image->exception);
for (x=0; x < (ssize_t) pdb_image.width; x++)
{
if (x < (ssize_t) image->columns)
buffer[literal+repeat]|=(0xff-scanline[x*packet_size]) >>
(8-bits_per_pixel) << bits*bits_per_pixel;
bits--;
if (bits < 0)
{
if (((literal+repeat) > 0) &&
(buffer[literal+repeat] == buffer[literal+repeat-1]))
{
if (repeat == 0)
{
literal--;
repeat++;
}
repeat++;
if (0x7f < repeat)
{
q=EncodeRLE(q,buffer,literal,repeat);
literal=0;
repeat=0;
}
}
else
{
if (repeat >= 2)
literal+=repeat;
else
{
q=EncodeRLE(q,buffer,literal,repeat);
buffer[0]=buffer[literal+repeat];
literal=0;
}
literal++;
repeat=0;
if (0x7f < literal)
{
q=EncodeRLE(q,buffer,(literal < 0x80 ? literal : 0x80),0);
(void) memmove(buffer,buffer+literal+repeat,0x80);
literal-=0x80;
}
}
bits=8/(int) bits_per_pixel-1;
buffer[literal+repeat]=0x00;
}
}
status=SetImageProgress(image,SaveImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
q=EncodeRLE(q,buffer,literal,repeat);
scanline=(unsigned char *) RelinquishMagickMemory(scanline);
buffer=(unsigned char *) RelinquishMagickMemory(buffer);
quantum_info=DestroyQuantumInfo(quantum_info);
(void) WriteBlobMSBLong(image,(unsigned int) (TellBlob(image)+8*
pdb_info.number_records));
(void) WriteBlobByte(image,0x40);
(void) WriteBlobByte(image,0x6f);
(void) WriteBlobByte(image,0x80);
(void) WriteBlobByte(image,0);
if (pdb_info.number_records > 1)
{
(void) WriteBlobMSBLong(image,(unsigned int) (TellBlob(image)+8+58+q-
runlength));
(void) WriteBlobByte(image,0x40);
(void) WriteBlobByte(image,0x6f);
(void) WriteBlobByte(image,0x80);
(void) WriteBlobByte(image,1);
}
(void) WriteBlob(image,sizeof(pdb_image.name),(unsigned char *)
pdb_image.name);
(void) WriteBlobByte(image,(unsigned char) pdb_image.version);
(void) WriteBlobByte(image,pdb_image.type);
(void) WriteBlobMSBLong(image,(unsigned int) pdb_image.reserved_1);
(void) WriteBlobMSBLong(image,(unsigned int) pdb_image.note);
(void) WriteBlobMSBShort(image,(unsigned short) pdb_image.x_last);
(void) WriteBlobMSBShort(image,(unsigned short) pdb_image.y_last);
(void) WriteBlobMSBLong(image,(unsigned int) pdb_image.reserved_2);
(void) WriteBlobMSBShort(image,pdb_image.x_anchor);
(void) WriteBlobMSBShort(image,pdb_image.y_anchor);
(void) WriteBlobMSBShort(image,(unsigned short) pdb_image.width);
(void) WriteBlobMSBShort(image,(unsigned short) pdb_image.height);
(void) WriteBlob(image,(size_t) (q-runlength),runlength);
runlength=(unsigned char *) RelinquishMagickMemory(runlength);
if (pdb_info.number_records > 1)
(void) WriteBlobString(image,comment);
(void) CloseBlob(image);
return(MagickTrue);
}

void vmx_vmexit_handler(struct cpu_user_regs *regs)
{
unsigned long exit_qualification, exit_reason, idtv_info, intr_info = 0;
unsigned int vector = 0, mode;
struct vcpu *v = current;
__vmread(GUEST_RIP,    &regs->rip);
__vmread(GUEST_RSP,    &regs->rsp);
__vmread(GUEST_RFLAGS, &regs->rflags);
hvm_invalidate_regs_fields(regs);
if ( paging_mode_hap(v->domain) )
{
__vmread(GUEST_CR4, &v->arch.hvm.hw_cr[4]);
v->arch.hvm.guest_cr[4] &= v->arch.hvm.vmx.cr4_host_mask;
v->arch.hvm.guest_cr[4] |= (v->arch.hvm.hw_cr[4] &
~v->arch.hvm.vmx.cr4_host_mask);
__vmread(GUEST_CR3, &v->arch.hvm.hw_cr[3]);
if ( vmx_unrestricted_guest(v) || hvm_paging_enabled(v) )
v->arch.hvm.guest_cr[3] = v->arch.hvm.hw_cr[3];
}
__vmread(VM_EXIT_REASON, &exit_reason);
if ( hvm_long_mode_active(v) )
HVMTRACE_ND(VMEXIT64, 0, 1, 3, exit_reason,
regs->eip, regs->rip >> 32, 0, 0, 0);
else
HVMTRACE_ND(VMEXIT, 0, 1, 2, exit_reason,
regs->eip, 0, 0, 0, 0);
perfc_incra(vmexits, exit_reason);
switch ( (uint16_t)exit_reason )
{
case EXIT_REASON_EXTERNAL_INTERRUPT:
vmx_do_extint(regs);
break;
case EXIT_REASON_EXCEPTION_NMI:
__vmread(VM_EXIT_INTR_INFO, &intr_info);
BUG_ON(!(intr_info & INTR_INFO_VALID_MASK));
vector = intr_info & INTR_INFO_VECTOR_MASK;
if ( vector == TRAP_machine_check )
do_machine_check(regs);
if ( (vector == TRAP_nmi) &&
((intr_info & INTR_INFO_INTR_TYPE_MASK) ==
MASK_INSR(X86_EVENTTYPE_NMI, INTR_INFO_INTR_TYPE_MASK)) )
{
exception_table[TRAP_nmi](regs);
enable_nmis();
}
break;
case EXIT_REASON_MCE_DURING_VMENTRY:
do_machine_check(regs);
break;
}
local_irq_enable();
if ( altp2m_active(v->domain) &&
(v->arch.hvm.vmx.secondary_exec_control &
SECONDARY_EXEC_ENABLE_VM_FUNCTIONS) )
{
unsigned long idx;
if ( v->arch.hvm.vmx.secondary_exec_control &
SECONDARY_EXEC_ENABLE_VIRT_EXCEPTIONS )
__vmread(EPTP_INDEX, &idx);
else
{
unsigned long eptp;
__vmread(EPT_POINTER, &eptp);
if ( (idx = p2m_find_altp2m_by_eptp(v->domain, eptp)) ==
INVALID_ALTP2M )
{
gdprintk(XENLOG_ERR, "EPTP not found in alternate p2m list\n");
domain_crash(v->domain);
return;
}
}
if ( idx != vcpu_altp2m(v).p2midx )
{
BUG_ON(idx >= MAX_ALTP2M);
atomic_dec(&p2m_get_altp2m(v)->active_vcpus);
vcpu_altp2m(v).p2midx = idx;
atomic_inc(&p2m_get_altp2m(v)->active_vcpus);
}
}
vcpu_nestedhvm(v).nv_vmswitch_in_progress = 0;
if ( nestedhvm_vcpu_in_guestmode(v) )
{
paging_update_nestedmode(v);
if ( nvmx_n2_vmexit_handler(regs, exit_reason) )
goto out;
}
if ( unlikely(exit_reason & VMX_EXIT_REASONS_FAILED_VMENTRY) )
return vmx_failed_vmentry(exit_reason, regs);
if ( v->arch.hvm.vmx.vmx_realmode )
{
regs->eflags &= ~(X86_EFLAGS_VM | X86_EFLAGS_IOPL);
regs->eflags |= (v->arch.hvm.vmx.vm86_saved_eflags & X86_EFLAGS_IOPL);
switch ( exit_reason )
{
case EXIT_REASON_EXCEPTION_NMI:
if ( vector != TRAP_page_fault
&& vector != TRAP_nmi 
&& vector != TRAP_machine_check ) 
{
default:
perfc_incr(realmode_exits);
v->arch.hvm.vmx.vmx_emulate = 1;
HVMTRACE_0D(REALMODE_EMULATE);
return;
}
case EXIT_REASON_EXTERNAL_INTERRUPT:
case EXIT_REASON_INIT:
case EXIT_REASON_SIPI:
case EXIT_REASON_PENDING_VIRT_INTR:
case EXIT_REASON_PENDING_VIRT_NMI:
case EXIT_REASON_MCE_DURING_VMENTRY:
case EXIT_REASON_GETSEC:
case EXIT_REASON_ACCESS_GDTR_OR_IDTR:
case EXIT_REASON_ACCESS_LDTR_OR_TR:
case EXIT_REASON_VMX_PREEMPTION_TIMER_EXPIRED:
case EXIT_REASON_INVEPT:
case EXIT_REASON_INVVPID:
break;
}
}
hvm_maybe_deassert_evtchn_irq();
__vmread(IDT_VECTORING_INFO, &idtv_info);
if ( exit_reason != EXIT_REASON_TASK_SWITCH )
vmx_idtv_reinject(idtv_info);
switch ( exit_reason )
{
unsigned long ecode;
case EXIT_REASON_EXCEPTION_NMI:
{
if ( unlikely(intr_info & INTR_INFO_NMI_UNBLOCKED_BY_IRET) &&
!(idtv_info & INTR_INFO_VALID_MASK) &&
(vector != TRAP_double_fault) )
{
unsigned long guest_info;
__vmread(GUEST_INTERRUPTIBILITY_INFO, &guest_info);
__vmwrite(GUEST_INTERRUPTIBILITY_INFO,
guest_info | VMX_INTR_SHADOW_NMI);
}
perfc_incra(cause_vector, vector);
switch ( vector )
{
case TRAP_debug:
__vmread(EXIT_QUALIFICATION, &exit_qualification);
HVMTRACE_1D(TRAP_DEBUG, exit_qualification);
__restore_debug_registers(v);
write_debugreg(6, exit_qualification | DR_STATUS_RESERVED_ONE);
if ( !v->domain->debugger_attached )
{
unsigned long insn_len = 0;
int rc;
unsigned long trap_type = MASK_EXTR(intr_info,
INTR_INFO_INTR_TYPE_MASK);
if ( trap_type >= X86_EVENTTYPE_SW_INTERRUPT )
__vmread(VM_EXIT_INSTRUCTION_LEN, &insn_len);
rc = hvm_monitor_debug(regs->rip,
HVM_MONITOR_DEBUG_EXCEPTION,
trap_type, insn_len);
if ( rc < 0 )
goto exit_and_crash;
if ( !rc )
vmx_propagate_intr(intr_info);
}
else
domain_pause_for_debugger();
break;
case TRAP_int3:
HVMTRACE_1D(TRAP, vector);
if ( !v->domain->debugger_attached )
{
unsigned long insn_len;
int rc;
__vmread(VM_EXIT_INSTRUCTION_LEN, &insn_len);
rc = hvm_monitor_debug(regs->rip,
HVM_MONITOR_SOFTWARE_BREAKPOINT,
X86_EVENTTYPE_SW_EXCEPTION,
insn_len);
if ( rc < 0 )
goto exit_and_crash;
if ( !rc )
vmx_propagate_intr(intr_info);
}
else
{
update_guest_eip(); 
v->arch.gdbsx_vcpu_event = TRAP_int3;
domain_pause_for_debugger();
}
break;
case TRAP_no_device:
HVMTRACE_1D(TRAP, vector);
vmx_fpu_dirty_intercept();
break;
case TRAP_page_fault:
__vmread(EXIT_QUALIFICATION, &exit_qualification);
__vmread(VM_EXIT_INTR_ERROR_CODE, &ecode);
regs->error_code = ecode;
HVM_DBG_LOG(DBG_LEVEL_VMMU,
"eax=%lx, ebx=%lx, ecx=%lx, edx=%lx, esi=%lx, edi=%lx",
regs->rax, regs->rbx, regs->rcx,
regs->rdx, regs->rsi, regs->rdi);
if ( paging_fault(exit_qualification, regs) )
{
if ( trace_will_trace_event(TRC_SHADOW) )
break;
if ( hvm_long_mode_active(v) )
HVMTRACE_LONG_2D(PF_XEN, regs->error_code,
TRC_PAR_LONG(exit_qualification) );
else
HVMTRACE_2D(PF_XEN,
regs->error_code, exit_qualification );
break;
}
hvm_inject_page_fault(regs->error_code, exit_qualification);
break;
case TRAP_alignment_check:
HVMTRACE_1D(TRAP, vector);
vmx_propagate_intr(intr_info);
break;
case TRAP_nmi:
if ( MASK_EXTR(intr_info, INTR_INFO_INTR_TYPE_MASK) !=
X86_EVENTTYPE_NMI )
goto exit_and_crash;
HVMTRACE_0D(NMI);
break;
case TRAP_machine_check:
HVMTRACE_0D(MCE);
break;
case TRAP_invalid_op:
HVMTRACE_1D(TRAP, vector);
hvm_ud_intercept(regs);
break;
default:
HVMTRACE_1D(TRAP, vector);
goto exit_and_crash;
}
break;
}
case EXIT_REASON_EXTERNAL_INTERRUPT:
break;
case EXIT_REASON_TRIPLE_FAULT:
hvm_triple_fault();
break;
case EXIT_REASON_PENDING_VIRT_INTR:
v->arch.hvm.vmx.exec_control &= ~CPU_BASED_VIRTUAL_INTR_PENDING;
vmx_update_cpu_exec_control(v);
break;
case EXIT_REASON_PENDING_VIRT_NMI:
v->arch.hvm.vmx.exec_control &= ~CPU_BASED_VIRTUAL_NMI_PENDING;
vmx_update_cpu_exec_control(v);
break;
case EXIT_REASON_TASK_SWITCH: {
static const enum hvm_task_switch_reason reasons[] = {
TSW_call_or_int, TSW_iret, TSW_jmp, TSW_call_or_int
};
unsigned int inst_len, source;
__vmread(EXIT_QUALIFICATION, &exit_qualification);
source = (exit_qualification >> 30) & 3;
WARN_ON((source == 3) && !(idtv_info & INTR_INFO_VALID_MASK));
inst_len = ((source != 3) ||        
(MASK_EXTR(idtv_info, INTR_INFO_INTR_TYPE_MASK)
> 3)) 
? get_instruction_length()  : 0;
if ( (source == 3) && (idtv_info & INTR_INFO_DELIVER_CODE_MASK) )
__vmread(IDT_VECTORING_ERROR_CODE, &ecode);
else
ecode = -1;
regs->rip += inst_len;
hvm_task_switch((uint16_t)exit_qualification, reasons[source], ecode);
break;
}
case EXIT_REASON_CPUID:
{
int rc = vmx_do_cpuid(regs);
if ( rc < 0 )
goto exit_and_crash;
if ( !rc )
update_guest_eip(); 
break;
}
case EXIT_REASON_HLT:
update_guest_eip(); 
hvm_hlt(regs->eflags);
break;
case EXIT_REASON_INVLPG:
update_guest_eip(); 
__vmread(EXIT_QUALIFICATION, &exit_qualification);
vmx_invlpg_intercept(exit_qualification);
break;
case EXIT_REASON_RDTSCP:
regs->rcx = hvm_msr_tsc_aux(v);
case EXIT_REASON_RDTSC:
update_guest_eip(); 
hvm_rdtsc_intercept(regs);
break;
case EXIT_REASON_VMCALL:
HVMTRACE_1D(VMMCALL, regs->eax);
if ( hvm_hypercall(regs) == HVM_HCALL_completed )
update_guest_eip(); 
break;
case EXIT_REASON_CR_ACCESS:
{
__vmread(EXIT_QUALIFICATION, &exit_qualification);
if ( vmx_cr_access(exit_qualification) == X86EMUL_OKAY )
update_guest_eip(); 
break;
}
case EXIT_REASON_DR_ACCESS:
__vmread(EXIT_QUALIFICATION, &exit_qualification);
vmx_dr_access(exit_qualification, regs);
break;
case EXIT_REASON_MSR_READ:
{
uint64_t msr_content = 0;
switch ( hvm_msr_read_intercept(regs->ecx, &msr_content) )
{
case X86EMUL_OKAY:
msr_split(regs, msr_content);
update_guest_eip(); 
break;
case X86EMUL_EXCEPTION:
hvm_inject_hw_exception(TRAP_gp_fault, 0);
break;
}
break;
}
case EXIT_REASON_MSR_WRITE:
switch ( hvm_msr_write_intercept(regs->ecx, msr_fold(regs), 1) )
{
case X86EMUL_OKAY:
update_guest_eip(); 
break;
case X86EMUL_EXCEPTION:
hvm_inject_hw_exception(TRAP_gp_fault, 0);
break;
}
break;
case EXIT_REASON_VMXOFF:
if ( nvmx_handle_vmxoff(regs) == X86EMUL_OKAY )
update_guest_eip();
break;
case EXIT_REASON_VMXON:
if ( nvmx_handle_vmxon(regs) == X86EMUL_OKAY )
update_guest_eip();
break;
case EXIT_REASON_VMCLEAR:
if ( nvmx_handle_vmclear(regs) == X86EMUL_OKAY )
update_guest_eip();
break;
case EXIT_REASON_VMPTRLD:
if ( nvmx_handle_vmptrld(regs) == X86EMUL_OKAY )
update_guest_eip();
break;
case EXIT_REASON_VMPTRST:
if ( nvmx_handle_vmptrst(regs) == X86EMUL_OKAY )
update_guest_eip();
break;
case EXIT_REASON_VMREAD:
if ( nvmx_handle_vmread(regs) == X86EMUL_OKAY )
update_guest_eip();
break;
case EXIT_REASON_VMWRITE:
if ( nvmx_handle_vmwrite(regs) == X86EMUL_OKAY )
update_guest_eip();
break;
case EXIT_REASON_VMLAUNCH:
if ( nvmx_handle_vmlaunch(regs) == X86EMUL_OKAY )
update_guest_eip();
break;
case EXIT_REASON_VMRESUME:
if ( nvmx_handle_vmresume(regs) == X86EMUL_OKAY )
update_guest_eip();
break;
case EXIT_REASON_INVEPT:
if ( nvmx_handle_invept(regs) == X86EMUL_OKAY )
update_guest_eip();
break;
case EXIT_REASON_INVVPID:
if ( nvmx_handle_invvpid(regs) == X86EMUL_OKAY )
update_guest_eip();
break;
case EXIT_REASON_VMFUNC:
if ( vmx_vmfunc_intercept(regs) != X86EMUL_OKAY )
hvm_inject_hw_exception(TRAP_invalid_op, X86_EVENT_NO_EC);
else
update_guest_eip();
break;
case EXIT_REASON_MWAIT_INSTRUCTION:
case EXIT_REASON_MONITOR_INSTRUCTION:
case EXIT_REASON_GETSEC:
WARN_ON(exit_reason == EXIT_REASON_GETSEC);
hvm_inject_hw_exception(TRAP_invalid_op, X86_EVENT_NO_EC);
break;
case EXIT_REASON_TPR_BELOW_THRESHOLD:
break;
case EXIT_REASON_APIC_ACCESS:
if ( !vmx_handle_eoi_write() && !handle_mmio() )
hvm_inject_hw_exception(TRAP_gp_fault, 0);
break;
case EXIT_REASON_EOI_INDUCED:
__vmread(EXIT_QUALIFICATION, &exit_qualification);
ASSERT(cpu_has_vmx_virtual_intr_delivery);
vlapic_handle_EOI(vcpu_vlapic(v), exit_qualification);
break;
case EXIT_REASON_IO_INSTRUCTION:
__vmread(EXIT_QUALIFICATION, &exit_qualification);
if ( exit_qualification & 0x10 )
{
if ( !hvm_emulate_one_insn(x86_insn_is_portio, "port I/O") )
hvm_inject_hw_exception(TRAP_gp_fault, 0);
}
else
{
uint16_t port = (exit_qualification >> 16) & 0xFFFF;
int bytes = (exit_qualification & 0x07) + 1;
int dir = (exit_qualification & 0x08) ? IOREQ_READ : IOREQ_WRITE;
if ( handle_pio(port, bytes, dir) )
update_guest_eip(); 
}
break;
case EXIT_REASON_INVD:
case EXIT_REASON_WBINVD:
{
update_guest_eip(); 
vmx_wbinvd_intercept();
break;
}
case EXIT_REASON_EPT_VIOLATION:
{
paddr_t gpa;
__vmread(GUEST_PHYSICAL_ADDRESS, &gpa);
__vmread(EXIT_QUALIFICATION, &exit_qualification);
ept_handle_violation(exit_qualification, gpa);
break;
}
case EXIT_REASON_EPT_MISCONFIG:
{
paddr_t gpa;
__vmread(GUEST_PHYSICAL_ADDRESS, &gpa);
if ( !ept_handle_misconfig(gpa) )
goto exit_and_crash;
break;
}
case EXIT_REASON_MONITOR_TRAP_FLAG:
v->arch.hvm.vmx.exec_control &= ~CPU_BASED_MONITOR_TRAP_FLAG;
vmx_update_cpu_exec_control(v);
if ( v->arch.hvm.single_step )
{
hvm_monitor_debug(regs->rip,
HVM_MONITOR_SINGLESTEP_BREAKPOINT,
0, 0);
if ( v->domain->debugger_attached )
domain_pause_for_debugger();
}
break;
case EXIT_REASON_PAUSE_INSTRUCTION:
perfc_incr(pauseloop_exits);
do_sched_op(SCHEDOP_yield, guest_handle_from_ptr(NULL, void));
break;
case EXIT_REASON_XSETBV:
if ( hvm_handle_xsetbv(regs->ecx, msr_fold(regs)) == X86EMUL_OKAY )
update_guest_eip(); 
break;
case EXIT_REASON_APIC_WRITE:
vmx_handle_apic_write();
break;
case EXIT_REASON_PML_FULL:
vmx_vcpu_flush_pml_buffer(v);
break;
case EXIT_REASON_XSAVES:
vmx_handle_xsaves();
break;
case EXIT_REASON_XRSTORS:
vmx_handle_xrstors();
break;
case EXIT_REASON_ACCESS_GDTR_OR_IDTR:
case EXIT_REASON_ACCESS_LDTR_OR_TR:
vmx_handle_descriptor_access(exit_reason);
break;
case EXIT_REASON_VMX_PREEMPTION_TIMER_EXPIRED:
case EXIT_REASON_INVPCID:
default:
exit_and_crash:
gprintk(XENLOG_ERR, "Unexpected vmexit: reason %lu\n", exit_reason);
if ( vmx_get_cpl() )
hvm_inject_hw_exception(TRAP_invalid_op,
X86_EVENT_NO_EC);
else
domain_crash(v->domain);
break;
}
out:
if ( nestedhvm_vcpu_in_guestmode(v) )
nvmx_idtv_handling();
mode = vmx_guest_x86_mode(v);
if ( mode == 8 ? !is_canonical_address(regs->rip)
: regs->rip != regs->eip )
{
gprintk(XENLOG_WARNING, "Bad rIP %lx for mode %u\n", regs->rip, mode);
if ( vmx_get_cpl() )
{
__vmread(VM_ENTRY_INTR_INFO, &intr_info);
if ( !(intr_info & INTR_INFO_VALID_MASK) )
hvm_inject_hw_exception(TRAP_gp_fault, 0);
if ( mode == 8 )
regs->rip = (long)(regs->rip << (64 - VADDR_BITS)) >>
(64 - VADDR_BITS);
else
regs->rip = regs->eip;
}
else
domain_crash(v->domain);
}
}

static Jsi_RC CDataStructDefineCmd(Jsi_Interp *interp, Jsi_Value *args, Jsi_Value *_this,
Jsi_Value **ret, Jsi_Func *funcPtr)
{
Jsi_RC rc = JSI_OK;
Jsi_OptionTypedef *st = NULL;
jsi_csInitType(interp);
Jsi_Value *eval = NULL, *val = Jsi_ValueArrayIndex(interp, args, 0),
*flds = Jsi_ValueArrayIndex(interp, args, 1);
int vlen, flen, i, argc, clen = 0, arrCnt=0;
Jsi_DString fStr = {};
char **argv = NULL, *cmt, *eq, *cp, *ce, *cpval, ocp;
const char *vstr = Jsi_ValueString(interp, val, &vlen),
*fstr = Jsi_ValueString(interp, flds, &flen);
if (vstr) {
cmt = Jsi_Strstr(fstr, "        eq = Jsi_Strchr(fstr, '=');
Jsi_DString tStr = {fstr};
fstr=jsi_TrimStr(Jsi_DSValue(&tStr));
Jsi_SplitStr(fstr, &argc, &argv, (cmt?"\n":";"), &fStr);
Jsi_DSFree(&tStr);
if (!cmt && argc>0 && !argv[argc-1][0])
argc--;
if (eq) {
eval = Jsi_ValueNewArray(interp, NULL, 0);
Jsi_IncrRefCount(interp, eval);
}
} else if (!Jsi_ValueIsArray(interp,flds) || (argc=Jsi_ValueGetLength(interp, flds))<1)
return Jsi_LogError("arg 2 must be string or non-empty array");
if (argc>200)
return Jsi_LogError("too many fields: %d>200", argc);
Jsi_StructSpec *sl, *sf, recs[argc+2];
memset(recs, 0, sizeof(recs));
sl = recs+argc+1;
sf = recs;
SIGINIT(sl, OPTS_STRUCT);
if (vstr) {
sl->name = Jsi_KeyAdd(interp, vstr);
} else if (Jsi_OptionsProcess(interp, StructOptions, sl, val, 0) < 0) {
rc = JSI_ERROR;
goto bail;
}
if (!Jsi_StrIsAlnum(sl->name)) {
rc = Jsi_LogError("invalid struct name: %s", sl->name);
goto bail;
}
if (jsi_csStructGet(interp, sl->name)) {
rc = Jsi_LogError("struct already exists: %s", sl->name);
goto bail;
}
for (i = 0; i<argc; i++) {
Jsi_Number numVal = 0;
bool bVal, isbitset = 0;
Jsi_Value *inival = NULL;
sf = recs+i;
SIGINIT(sf, OPTS_FIELD);
if (!argv) {
val = Jsi_ValueArrayIndex(interp, flds, i);
if (!val || Jsi_OptionsProcess(interp, StructFieldOptions, sf, val, 0) < 0) {
rc = JSI_ERROR;
goto bail;
}
if (!Jsi_StrIsAlnum(sf->name) || !sf->type) {
rc = Jsi_LogError("invalid struct field name: %s", sf->name);
goto bail;
}
if (!Jsi_ValueObjLookup(interp, val, "init", 0) && (sf->type->flags&jsi_CTYP_STRUCT))
inival = Jsi_ValueNewBoolean(interp, true);
} else {
if (cmt) {
cp = Jsi_Strstr(argv[i], "                if (cp) {
*cp = 0;
cp += 2;
cp = jsi_TrimStr(cp);
sf->help = Jsi_KeyAdd(interp, cp);
}
cp = Jsi_Strchr(argv[i], ';'); 
if (cp) *cp = 0;
}
cp = Jsi_Strchr(argv[i], '='); 
if (cp) {
if (!eval)
goto bail;
*cp++ = 0;
cp = jsi_TrimStr(cp);
int cplen = Jsi_Strlen(cp);
if (cplen>1 && (cp[0] == '\'' || cp[0] == '"') && cp[0] == cp[cplen-1]) {
cpval = cp+1;
cp[cplen-1] = 0;
inival = Jsi_ValueNewStringDup(interp, cpval);
}
else if (Jsi_GetDouble(interp, cp, &numVal) == JSI_OK)
inival = Jsi_ValueNewNumber(interp, numVal);
else if (Jsi_GetBool(interp, cp, &bVal) == JSI_OK)
inival = Jsi_ValueNewBoolean(interp, bVal);
else
inival = Jsi_ValueNewStringDup(interp, cp);
}
cp = argv[i];
while (*cp && isspace(*cp)) cp++;
ce = cp;
while (*ce && !isspace(*ce)) ce++;
ocp = *ce;
if (!ocp) {
rc = Jsi_LogError("bad field: %s", cp);
goto bail;
}
*ce = 0;
sf->type = Jsi_TypeLookup(interp, cp);
*ce = ocp;
if (!sf->type) {
rc = Jsi_LogError("unknown type: %s", argv[i]);
goto bail;
}
if (!inival && (sf->type->flags&jsi_CTYP_STRUCT))
inival = Jsi_ValueNewBoolean(interp, true);
cp = ce+1;
while (*cp && isspace(*cp)) cp++;
ce = cp;
while (*ce && (isalnum(*ce) || *ce == '_')) ce++;
ocp = *ce;
*ce = 0;
if (!*cp) {
rc = Jsi_LogError("missing or bad struct field name");
goto bail;
}
sf->name = Jsi_KeyAdd(interp, cp);
if (ocp) {
ce++;
clen = Jsi_Strlen(ce);
}
if (ocp == '@') {
isbitset = 1;
} else
if (ocp == ':') {
int bsiz = -1;
if (Jsi_GetInt(interp, ce, &bsiz,10) != JSI_OK || bsiz<=0 || bsiz>64) {
rc = Jsi_LogError("bad bit size: %s", ce);
goto bail;
}
sf->bits = bsiz;
} else if (ocp == '[' && clen>1 && ce[clen-1]==']') {
int asiz = -1;
ce[clen-1] = 0;
if (Jsi_GetInt(interp, ce, &asiz, 10) != JSI_OK || asiz<=0) {
rc = Jsi_LogError("bad size: %s", cp);
goto bail;
}
sf->arrSize = asiz;
} else if (ocp) {
rc = Jsi_LogError("bad field: %s", cp);
goto bail;
}
val = NULL;            
}
if (inival) {
Jsi_Value *sval = Jsi_ValueNewObj(interp, NULL);
Jsi_ValueInsert(interp, sval, "init", inival, 0);
Jsi_ValueArraySet(interp, eval, sval, i);
}
bool isEnum = (sf->type && (sf->type->flags&jsi_CTYP_ENUM));
if (isbitset) {
if (!isEnum) {
rc = Jsi_LogError("bitset type is not an enum");
goto bail;
}
sf->flags |= JSI_OPT_BITSET_ENUM;
}
if (sf->arrSize) {
if (sf->arrSize>MAX_ARRAY_LIST) {
rc = Jsi_LogError("array size too big: %d >= %d", sf->arrSize, MAX_ARRAY_LIST);
goto bail;
}
if (sf->bits || isEnum) {
rc = Jsi_LogError("array of %s unsupported", (sf->bits?"bits":"enums"));
goto bail;
}
arrCnt++;
}
}
recs[argc].id = JSI_OPTION_END;
rc = jsi_csSetupStruct(interp, sl, recs, recs, argc, &st, arrCnt);
if (rc != JSI_OK || !st) {
rc = JSI_ERROR;
goto bail;
}
sl = jsi_csGetStructSpec(st->extData);
sf = jsi_csGetFieldSpec(sl->extData);
if (vstr)
flds = eval;
for (i = 0; i<argc && flds; i++) {
val = Jsi_ValueArrayIndex(interp, flds, i);
if (val && Jsi_OptionsProcess(interp, StructFieldOptions, sf+i, val, JSI_OPT_PASS2) < 0) {
rc = JSI_ERROR;
goto bail;
}
}
bail:
if (eval)
Jsi_DecrRefCount(interp, eval);
Jsi_DSFree(&fStr);
if (rc != JSI_OK && st)
Jsi_HashEntryDelete(st->hPtr);
return rc;
}

int HevcVpsUnit::deserialize()
{
int rez = HevcUnit::deserialize();
if (rez)
return rez;
try
{
vps_id = m_reader.getBits(4);
m_reader.skipBits(2);          vps_max_layers = m_reader.getBits(6) + 1;
vps_max_sub_layers = m_reader.getBits(3) + 1;
int vps_temporal_id_nesting_flag = m_reader.getBit();
m_reader.skipBits(16);          profile_tier_level(vps_max_sub_layers);
bool vps_sub_layer_ordering_info_present_flag = m_reader.getBit();
for (int i = (vps_sub_layer_ordering_info_present_flag ? 0 : vps_max_sub_layers - 1);
i <= vps_max_sub_layers - 1; i++)
{
unsigned vps_max_dec_pic_buffering_minus1 = extractUEGolombCode();
unsigned vps_max_num_reorder_pics = extractUEGolombCode();
if (vps_max_num_reorder_pics > vps_max_dec_pic_buffering_minus1)
return 1;
unsigned vps_max_latency_increase_plus1 = extractUEGolombCode();
if (vps_max_latency_increase_plus1 == 0xffffffff)
return 1;
}
int vps_max_layer_id = m_reader.getBits(6);
unsigned vps_num_layer_sets_minus1 = extractUEGolombCode();
if (vps_num_layer_sets_minus1 > 1023)
return 1;
for (size_t i = 1; i <= vps_num_layer_sets_minus1; i++)
{
for (int j = 0; j <= vps_max_layer_id; j++) m_reader.skipBit();          }
bool vps_timing_info_present_flag = m_reader.getBit();
if (vps_timing_info_present_flag)
{
num_units_in_tick_bit_pos = m_reader.getBitsCount();
num_units_in_tick = m_reader.getBits(32);
time_scale = m_reader.getBits(32);
}
return rez;
}
catch (VodCoreException& e)
{
return NOT_ENOUGH_BUFFER;
}
}

static int SetupSavePath(const DetectEngineCtx *de_ctx,
char *save, size_t save_size)
{
SCLogDebug("save %s", save);
if (PathIsAbsolute(save)) {
return 0;
}
const char *dir = ConfigGetDataDirectory();
BUG_ON(dir == NULL);     char path[PATH_MAX];
if (snprintf(path, sizeof(path), "%s/%s", dir, save) >= (int)sizeof(path))         return -1;
strlcpy(save, path, save_size);
return 0;
}

int hvm_map_io_range_to_ioreq_server(struct domain *d, ioservid_t id,
uint32_t type, uint64_t start,
uint64_t end)
{
struct hvm_ioreq_server *s;
int rc;
spin_lock_recursive(&d->arch.hvm_domain.ioreq_server.lock);
rc = -ENOENT;
list_for_each_entry ( s,
&d->arch.hvm_domain.ioreq_server.list,
list_entry )
{
if ( s == d->arch.hvm_domain.default_ioreq_server )
continue;
if ( s->id == id )
{
struct rangeset *r;
switch ( type )
{
case XEN_DMOP_IO_RANGE_PORT:
case XEN_DMOP_IO_RANGE_MEMORY:
case XEN_DMOP_IO_RANGE_PCI:
r = s->range[type];
break;
default:
r = NULL;
break;
}
rc = -EINVAL;
if ( !r )
break;
rc = -EEXIST;
if ( rangeset_overlaps_range(r, start, end) )
break;
rc = rangeset_add_range(r, start, end);
break;
}
}
spin_unlock_recursive(&d->arch.hvm_domain.ioreq_server.lock);
return rc;
}

int
ProcRRChangeOutputProperty(ClientPtr client)
{
REQUEST(xRRChangeOutputPropertyReq);
RROutputPtr output;
char format, mode;
unsigned long len;
int sizeInBytes;
int totalSize;
int err;
REQUEST_AT_LEAST_SIZE(xRRChangeOutputPropertyReq);
UpdateCurrentTime();
format = stuff->format;
mode = stuff->mode;
if ((mode != PropModeReplace) && (mode != PropModeAppend) &&
(mode != PropModePrepend)) {
client->errorValue = mode;
return BadValue;
}
if ((format != 8) && (format != 16) && (format != 32)) {
client->errorValue = format;
return BadValue;
}
len = stuff->nUnits;
if (len > bytes_to_int32((0xffffffff - sizeof(xChangePropertyReq))))
return BadLength;
sizeInBytes = format >> 3;
totalSize = len * sizeInBytes;
REQUEST_FIXED_SIZE(xRRChangeOutputPropertyReq, totalSize);
VERIFY_RR_OUTPUT(stuff->output, output, DixReadAccess);
if (!ValidAtom(stuff->property)) {
client->errorValue = stuff->property;
return BadAtom;
}
if (!ValidAtom(stuff->type)) {
client->errorValue = stuff->type;
return BadAtom;
}
err = RRChangeOutputProperty(output, stuff->property,
stuff->type, (int) format,
(int) mode, len, (void *) &stuff[1], TRUE,
TRUE);
if (err != Success)
return err;
else
return Success;
}

static int DecodeGifImg(struct ngiflib_img * i) {
struct ngiflib_decode_context context;
long npix;
u8 * stackp;
u8 * stack_top;
u16 clr;
u16 eof;
u16 free;
u16 act_code = 0;
u16 old_code = 0;
u16 read_byt;
u16 ab_prfx[4096];
u8 ab_suffx[4096];
u8 ab_stack[4096];
u8 flags;
u8 casspecial = 0;
if(!i) return -1;
i->posX = GetWord(i->parent);
i->posY = GetWord(i->parent);
i->width = GetWord(i->parent);
i->height = GetWord(i->parent);
if((i->width > i->parent->width) || (i->height > i->parent->height)) {
#if !defined(NGIFLIB_NO_FILE)
if(i->parent->log) fprintf(i->parent->log, "*** ERROR *** Image bigger than global GIF canvas !\n");
#endif
return -1;
}
if((i->posX + i->width) > i->parent->width) {
#if !defined(NGIFLIB_NO_FILE)
if(i->parent->log) fprintf(i->parent->log, "*** WARNING *** Adjusting X position\n");
#endif
i->posX = i->parent->width - i->width;
}
if((i->posY + i->height) > i->parent->height) {
#if !defined(NGIFLIB_NO_FILE)
if(i->parent->log) fprintf(i->parent->log, "*** WARNING *** Adjusting Y position\n");
#endif
i->posY = i->parent->height - i->height;
}
context.Xtogo = i->width;
context.curY = i->posY;
#ifdef NGIFLIB_INDEXED_ONLY
#ifdef NGIFLIB_ENABLE_CALLBACKS
context.line_p.p8 = i->parent->frbuff.p8 + (u32)i->posY*i->parent->width;
context.frbuff_p.p8 = context.line_p.p8 + i->posX;
#else
context.frbuff_p.p8 = i->parent->frbuff.p8 + (u32)i->posY*i->parent->width + i->posX;
#endif 
#else
if(i->parent->mode & NGIFLIB_MODE_INDEXED) {
#ifdef NGIFLIB_ENABLE_CALLBACKS
context.line_p.p8 = i->parent->frbuff.p8 + (u32)i->posY*i->parent->width;
context.frbuff_p.p8 = context.line_p.p8 + i->posX;
#else
context.frbuff_p.p8 = i->parent->frbuff.p8 + (u32)i->posY*i->parent->width + i->posX;
#endif 
} else {
#ifdef NGIFLIB_ENABLE_CALLBACKS
context.line_p.p32 = i->parent->frbuff.p32 + (u32)i->posY*i->parent->width;
context.frbuff_p.p32 = context.line_p.p32 + i->posX;
#else
context.frbuff_p.p32 = i->parent->frbuff.p32 + (u32)i->posY*i->parent->width + i->posX;
#endif 
}
#endif 
npix = (long)i->width * i->height;
flags = GetByte(i->parent);
i->interlaced = (flags & 64) >> 6;
context.pass = i->interlaced ? 1 : 0;
i->sort_flag = (flags & 32) >> 5;
i->localpalbits = (flags & 7) + 1;
if(flags&128) { 
int k;
int localpalsize = 1 << i->localpalbits;
#if !defined(NGIFLIB_NO_FILE)
if(i->parent && i->parent->log) fprintf(i->parent->log, "Local palette\n");
#endif 
i->palette = (struct ngiflib_rgb *)ngiflib_malloc(sizeof(struct ngiflib_rgb)*localpalsize);
for(k=0; k<localpalsize; k++) {
i->palette[k].r = GetByte(i->parent);
i->palette[k].g = GetByte(i->parent);
i->palette[k].b = GetByte(i->parent);
}
#ifdef NGIFLIB_ENABLE_CALLBACKS
if(i->parent->palette_cb) i->parent->palette_cb(i->parent, i->palette, localpalsize);
#endif 
} else {
i->palette = i->parent->palette;
i->localpalbits = i->parent->imgbits;
}
i->ncolors = 1 << i->localpalbits;
i->imgbits = GetByte(i->parent);
if (i->imgbits > 11) {
#if !defined(NGIFLIB_NO_FILE)
if(i->parent->log) fprintf(i->parent->log, "*** ERROR *** Invalid LZW Minimum Code Size : %d\n", (int)i->imgbits);
#endif
return -1;
}
#if !defined(NGIFLIB_NO_FILE)
if(i->parent && i->parent->log) {
if(i->interlaced) fprintf(i->parent->log, "interlaced ");
fprintf(i->parent->log, "img pos(%hu,%hu) size %hux%hu palbits=%hhu imgbits=%hhu ncolors=%hu\n",
i->posX, i->posY, i->width, i->height, i->localpalbits, i->imgbits, i->ncolors);
}
#endif 
if(i->imgbits==1) {
i->imgbits = 2;
}
clr = 1 << i->imgbits;
eof = clr + 1;
free = clr + 2;
context.nbbit = i->imgbits + 1;
context.max = clr + clr - 1; 
stackp = stack_top = ab_stack + 4096;
context.restbits = 0;
context.restbyte = 0;
context.lbyte = 0;
for(;;) {
act_code = GetGifWord(i, &context);
if(act_code==eof) {
#if !defined(NGIFLIB_NO_FILE)
if(i->parent && i->parent->log) fprintf(i->parent->log, "End of image code 0x%x (nbbit=%u)\n", eof, context.nbbit);
#endif 
return 0;
}
if(npix==0) {
#if !defined(NGIFLIB_NO_FILE)
if(i->parent && i->parent->log) fprintf(i->parent->log, "assez de pixels, On se casse !\n");
#endif 
return 1;
}
if(act_code==clr) {
#if !defined(NGIFLIB_NO_FILE)
if(i->parent && i->parent->log) fprintf(i->parent->log, "Code clear (%hu) (free=%hu) npix=%ld\n", clr, free, npix);
#endif 
free = clr + 2;
context.nbbit = i->imgbits + 1;
context.max = clr + clr - 1; 
act_code = GetGifWord(i, &context);
if (act_code >= clr)
{
#if !defined(NGIFLIB_NO_FILE)
if(i->parent && i->parent->log) fprintf(i->parent->log, "Invalid code %hu just after clear(%hu) !\n", act_code, clr);
#endif 
return -1;
}
casspecial = (u8)act_code;
old_code = act_code;
if(npix > 0) WritePixel(i, &context, casspecial);
npix--;
} else if(act_code > free) {
#if !defined(NGIFLIB_NO_FILE)
if(i->parent && i->parent->log) fprintf(i->parent->log, "Invalid code %hu (free=%hu) !\n", act_code, free);
#endif 
return -1;
} else {
read_byt = act_code;
if(act_code == free) {
*(--stackp) = casspecial; 
act_code = old_code;
}
while(act_code > clr) { 
*(--stackp) = ab_suffx[act_code];
act_code = ab_prfx[act_code];
}
casspecial = (u8)act_code;
*(--stackp) = casspecial;
if(npix >= (stack_top - stackp)) {
WritePixels(i, &context, stackp, stack_top - stackp);
} else if(npix > 0) {
WritePixels(i, &context, stackp, npix);
}
npix -= (stack_top - stackp);
stackp = stack_top;
if(free < 4096) { 
ab_prfx[free] = old_code;
ab_suffx[free] = (u8)act_code;
free++;
if((free > context.max) && (context.nbbit < 12)) {
context.nbbit++;
context.max += context.max + 1;
}
}
old_code = read_byt;
}
}
return 0;
}

void
QPDF::read_xref(qpdf_offset_t xref_offset)
{
std::map<int, int> free_table;
while (xref_offset)
{
char buf[7];
memset(buf, 0, sizeof(buf));
this->m->file->seek(xref_offset, SEEK_SET);
this->m->file->read(buf, sizeof(buf) - 1);
if ((strncmp(buf, "xref", 4) == 0) &&
QUtil::is_space(buf[4]))
{
QTC::TC("qpdf", "QPDF xref space",
((buf[4] == '\n') ? 0 :
(buf[4] == '\r') ? 1 :
(buf[4] == ' ') ? 2 : 9999));
int skip = 4;
while (QUtil::is_space(buf[skip]))
{
++skip;
}
xref_offset = read_xrefTable(xref_offset + skip);
}
else
{
xref_offset = read_xrefStream(xref_offset);
}
}
if (! this->m->trailer.isInitialized())
{
throw QPDFExc(qpdf_e_damaged_pdf, this->m->file->getName(), "", 0,
"unable to find trailer while reading xref");
}
int size = this->m->trailer.getKey("/Size").getIntValue();
int max_obj = 0;
if (! this->m->xref_table.empty())
{
max_obj = (*(this->m->xref_table.rbegin())).first.getObj();
}
if (! this->m->deleted_objects.empty())
{
max_obj = std::max(max_obj, *(this->m->deleted_objects.rbegin()));
}
if (size != max_obj + 1)
{
QTC::TC("qpdf", "QPDF xref size mismatch");
warn(QPDFExc(qpdf_e_damaged_pdf, this->m->file->getName(), "", 0,
std::string("reported number of objects (") +
QUtil::int_to_string(size) +
") inconsistent with actual number of objects (" +
QUtil::int_to_string(max_obj + 1) + ")"));
}
this->m->deleted_objects.clear();
}

VTermState *vterm_obtain_state(VTerm *vt)
{
VTermState *state;
if(vt->state)
return vt->state;
state = vterm_state_new(vt);
vt->state = state;
state->combine_chars_size = 16;
state->combine_chars = vterm_allocator_malloc(state->vt, state->combine_chars_size * sizeof(state->combine_chars[0]));
state->tabstops = vterm_allocator_malloc(state->vt, (state->cols + 7) / 8);
state->lineinfo = vterm_allocator_malloc(state->vt, state->rows * sizeof(VTermLineInfo));
state->encoding_utf8.enc = vterm_lookup_encoding(ENC_UTF8, 'u');
if(*state->encoding_utf8.enc->init != NULL)
(*state->encoding_utf8.enc->init)(state->encoding_utf8.enc, state->encoding_utf8.data);
vterm_parser_set_callbacks(vt, &parser_callbacks, state);
return state;
}

static inline void
fast_edit_packet(struct pcap_pkthdr *pkthdr, u_char **pktdata,
COUNTER iteration, bool cached, int datalink)
{
uint16_t ether_type;
ipv4_hdr_t *ip_hdr = NULL;
ipv6_hdr_t *ip6_hdr = NULL;
uint32_t src_ip, dst_ip;
uint32_t src_ip_orig, dst_ip_orig;
int l2_len;
u_char *packet = *pktdata;
if (datalink != DLT_EN10MB && datalink != DLT_JUNIPER_ETHER)
fast_edit_packet_dl(pkthdr, pktdata, iteration, cached, datalink);
if (pkthdr->caplen < (bpf_u_int32)TCPR_IPV6_H) {
dbgx(2, "Packet too short for Unique IP feature: %u", pkthdr->caplen);
return;
}
l2_len = 0;
if (datalink == DLT_JUNIPER_ETHER) {
if (memcmp(packet, "MGC", 3))
warnx("No Magic Number found: %s (0x%x)",
pcap_datalink_val_to_description(datalink), datalink);
if ((packet[3] & 0x80) == 0x80) {
l2_len = ntohs(*((uint16_t*)&packet[4]));
if (l2_len > 1024) {
warnx("L2 length too long: %u", l2_len);
return;
}
l2_len += 6;
} else
l2_len = 4; 
}
ether_type = ntohs(((eth_hdr_t*)(packet + l2_len))->ether_type);
l2_len += sizeof(eth_hdr_t);
while (ether_type == ETHERTYPE_VLAN) {
vlan_hdr_t *vlan_hdr = (vlan_hdr_t*)(pktdata + l2_len);
ether_type = ntohs(vlan_hdr->vlan_tpid);
l2_len += 4;
}
switch (ether_type) {
case ETHERTYPE_IP:
ip_hdr = (ipv4_hdr_t *)(packet + l2_len);
src_ip_orig = src_ip = ntohl(ip_hdr->ip_src.s_addr);
dst_ip_orig = dst_ip = ntohl(ip_hdr->ip_dst.s_addr);
break;
case ETHERTYPE_IP6:
ip6_hdr = (ipv6_hdr_t *)(packet + l2_len);
src_ip_orig = src_ip = ntohl(ip6_hdr->ip_src.__u6_addr.__u6_addr32[3]);
dst_ip_orig = dst_ip = ntohl(ip6_hdr->ip_dst.__u6_addr.__u6_addr32[3]);
break;
default:
return; 
}
dbgx(2, "Layer 3 protocol type is: 0x%04x", ether_type);
if ((!cached && dst_ip > src_ip) ||
(cached && (dst_ip - iteration) > (src_ip - 1 - iteration))) {
if (cached) {
--src_ip;
++dst_ip;
} else {
src_ip -= iteration;
dst_ip += iteration;
}
if (src_ip > src_ip_orig && dst_ip > dst_ip_orig) {
dbgx(1, "dst_ip > src_ip(" COUNTER_SPEC "): before(1) src_ip=0x%08x dst_ip=0x%08x", iteration, src_ip, dst_ip);
--src_ip;
dbgx(1, "dst_ip > src_ip(" COUNTER_SPEC "): after(1)  src_ip=0x%08x dst_ip=0x%08x", iteration, src_ip, dst_ip);
} else if (dst_ip < dst_ip_orig && src_ip < src_ip_orig) {
dbgx(1, "dst_ip > src_ip(" COUNTER_SPEC "): before(2) src_ip=0x%08x dst_ip=0x%08x", iteration, src_ip, dst_ip);
++dst_ip;
dbgx(1, "dst_ip > src_ip(" COUNTER_SPEC "): after(2)  src_ip=0x%08x dst_ip=0x%08x", iteration, src_ip, dst_ip);
}
} else {
if (cached) {
++src_ip;
--dst_ip;
} else {
src_ip += iteration;
dst_ip -= iteration;
}
if (dst_ip > dst_ip_orig && src_ip > src_ip_orig) {
dbgx(1, "src_ip > dst_ip(" COUNTER_SPEC "): before(1) dst_ip=0x%08x src_ip=0x%08x", iteration, dst_ip, src_ip);
--dst_ip;
dbgx(1, "src_ip > dst_ip(" COUNTER_SPEC "): after(1)  dst_ip=0x%08x src_ip=0x%08x", iteration, dst_ip, src_ip);
} else if (src_ip < src_ip_orig && dst_ip < dst_ip_orig) {
dbgx(1, "src_ip > dst_ip(" COUNTER_SPEC "): before(2) dst_ip=0x%08x src_ip=0x%08x", iteration, dst_ip, src_ip);
++src_ip;
dbgx(1, "src_ip > dst_ip(" COUNTER_SPEC "): after(2)  dst_ip=0x%08x src_ip=0x%08x", iteration, dst_ip, src_ip);
}
}
dbgx(1, "(" COUNTER_SPEC "): final src_ip=0x%08x dst_ip=0x%08x", iteration, src_ip, dst_ip);
switch (ether_type) {
case ETHERTYPE_IP:
ip_hdr->ip_src.s_addr = htonl(src_ip);
ip_hdr->ip_dst.s_addr = htonl(dst_ip);
break;
case ETHERTYPE_IP6:
ip6_hdr->ip_src.__u6_addr.__u6_addr32[3] = htonl(src_ip);
ip6_hdr->ip_dst.__u6_addr.__u6_addr32[3] = htonl(dst_ip);
break;
}
}

Error HeifContext::get_id_of_non_virtual_child_image(heif_item_id id, heif_item_id& out) const
{
std::string image_type = m_heif_file->get_item_type(id);
if (image_type=="grid" ||
image_type=="iden" ||
image_type=="iovl") {
auto iref_box = m_heif_file->get_iref_box();
std::vector<heif_item_id> image_references = iref_box->get_references(id, fourcc("dimg"));
if (image_references.empty()) {
return Error(heif_error_Invalid_input,
heif_suberror_No_item_data,
"Derived image does not reference any other image items");
}
else {
return get_id_of_non_virtual_child_image(image_references[0], out);
}
}
else {
out = id;
return Error::Ok;
}
}

static gboolean
is_link_trusted (NautilusFile *file,
gboolean      is_launcher)
{
GFile *location;
gboolean res;
if (!is_launcher)
{
return TRUE;
}
if (nautilus_file_can_execute (file))
{
return TRUE;
}
res = FALSE;
