}

static int
dissect_docsis (tvbuff_t * tvb, packet_info * pinfo, proto_tree * tree, void* data _U_)
{
guint8 fc;
guint8 fctype;
guint8 fcparm;
guint8 ehdron;
gint mac_parm;
gint hdrlen;
guint16 len_sid;
tvbuff_t *next_tvb, *mgt_tvb;
gint pdulen, captured_length;
gint framelen;
gboolean isfrag = FALSE;
gint oldconcatlen;
proto_item *ti;
proto_tree *docsis_tree;
static gint concatlen;
static gint concatpos;
fc = tvb_get_guint8 (tvb, 0); 
fctype = (fc >> 6) & 0x03;    
fcparm = (fc >> 1) & 0x1F;    
ehdron = (fc & 0x01);         
if (fcparm == 0x04) {
mac_parm = tvb_get_ntohs (tvb, 1);
len_sid = tvb_get_ntohs (tvb, 3);
} else {
mac_parm = tvb_get_guint8 (tvb, 1);
len_sid = tvb_get_ntohs (tvb, 2);
}
if (ehdron == 0x00) {
if (fcparm == 0x04)
hdrlen = 7;
else
hdrlen = 6;
} else {
hdrlen = 6 + mac_parm;
}
captured_length = tvb_captured_length_remaining (tvb, hdrlen);
if ((fctype == FCTYPE_MACSPC) && (fcparm == 0x02 || fcparm == 0x04))
{
pdulen = 0;
framelen = 6;
}
else
{
framelen = 6 + len_sid;
pdulen = len_sid - (mac_parm + 2);
}
if ((fctype == FCTYPE_MACSPC) && (fcparm == 0x1c))
{
concatlen = len_sid;
concatpos = 6;
}
col_set_str (pinfo->cinfo, COL_PROTOCOL, "DOCSIS");
switch (fctype)
{
case FCTYPE_PACKET:
col_set_str (pinfo->cinfo, COL_INFO, "Packet PDU");
break;
case FCTYPE_ATMPDU:
col_set_str (pinfo->cinfo, COL_INFO, "ATM PDU");
break;
case FCTYPE_RESRVD:
col_set_str (pinfo->cinfo, COL_INFO, "Reserved PDU");
break;
case FCTYPE_MACSPC:
if (fcparm == 0x02)
col_add_fstr (pinfo->cinfo, COL_INFO,
"Request Frame SID = %u Mini Slots = %u", len_sid,
mac_parm);
else if (fcparm == 0x04)
col_add_fstr (pinfo->cinfo, COL_INFO,
"Request Frame SID = %u Bytes Requested = %u", len_sid,
mac_parm);
else if (fcparm == 0x03)
col_set_str (pinfo->cinfo, COL_INFO, "Fragmented Frame");
else
col_set_str (pinfo->cinfo, COL_INFO, "Mac Specific");
break;
}  
if (tree)
{
ti = proto_tree_add_protocol_format (tree, proto_docsis, tvb, 0,
hdrlen, "DOCSIS");
docsis_tree = proto_item_add_subtree (ti, ett_docsis);
proto_tree_add_item (docsis_tree, hf_docsis_fctype, tvb, 0, 1, ENC_BIG_ENDIAN);
switch (fctype)
{
case FCTYPE_PACKET:
case FCTYPE_ATMPDU:
case FCTYPE_RESRVD:
proto_tree_add_item (docsis_tree, hf_docsis_fcparm, tvb, 0, 1,
ENC_BIG_ENDIAN);
proto_tree_add_item (docsis_tree, hf_docsis_ehdron, tvb, 0, 1,
ENC_BIG_ENDIAN);
if (ehdron == 0x01)
{
proto_tree_add_item (docsis_tree, hf_docsis_ehdrlen, tvb, 1, 1,
ENC_BIG_ENDIAN);
proto_tree_add_item (docsis_tree, hf_docsis_len, tvb, 2, 2,
ENC_BIG_ENDIAN);
dissect_ehdr (tvb, docsis_tree, isfrag);
proto_tree_add_item (docsis_tree, hf_docsis_hcs, tvb,
4 + mac_parm, 2, ENC_BIG_ENDIAN);
}
else
{
proto_tree_add_item (docsis_tree, hf_docsis_macparm, tvb, 1, 1,
ENC_BIG_ENDIAN);
proto_tree_add_item (docsis_tree, hf_docsis_len, tvb, 2, 2,
ENC_BIG_ENDIAN);
proto_tree_add_item (docsis_tree, hf_docsis_hcs, tvb, 4, 2,
ENC_BIG_ENDIAN);
}
break;
case FCTYPE_MACSPC:
proto_tree_add_item (docsis_tree, hf_docsis_machdr_fcparm, tvb, 0,
1, ENC_BIG_ENDIAN);
proto_tree_add_item (docsis_tree, hf_docsis_ehdron, tvb, 0, 1,
ENC_BIG_ENDIAN);
if (fcparm == 0x02)
{
proto_tree_add_uint (docsis_tree, hf_docsis_mini_slots, tvb, 1,
1, mac_parm);
proto_tree_add_uint (docsis_tree, hf_docsis_sid, tvb, 2, 2,
len_sid);
proto_tree_add_item (docsis_tree, hf_docsis_hcs, tvb, 4, 2,
ENC_BIG_ENDIAN);
break;
}
if (fcparm == 0x04)
{
proto_tree_add_uint (docsis_tree, hf_docsis_requested_size, tvb, 1,
2, mac_parm);
proto_tree_add_uint (docsis_tree, hf_docsis_sid, tvb, 3, 2,
len_sid);
proto_tree_add_item (docsis_tree, hf_docsis_hcs, tvb, 5, 2,
ENC_BIG_ENDIAN);
break;
}
if (fcparm == 0x03)
{
isfrag = TRUE;
}
if (fcparm == 0x1c)
{
proto_item_append_text (ti, " (Concatenated Header)");
proto_tree_add_item (docsis_tree, hf_docsis_concat_cnt, tvb, 1,
1, ENC_BIG_ENDIAN);
proto_tree_add_item (docsis_tree, hf_docsis_len, tvb, 2, 2,
ENC_BIG_ENDIAN);
proto_tree_add_item (docsis_tree, hf_docsis_hcs, tvb, 4, 2,
ENC_BIG_ENDIAN);
break;
}
if (ehdron == 0x01)
{
proto_tree_add_item (docsis_tree, hf_docsis_ehdrlen, tvb, 1, 1,
ENC_BIG_ENDIAN);
proto_tree_add_item (docsis_tree, hf_docsis_len, tvb, 2, 2,
ENC_BIG_ENDIAN);
dissect_ehdr (tvb, docsis_tree, isfrag);
proto_tree_add_item (docsis_tree, hf_docsis_hcs, tvb,
4 + mac_parm, 2, ENC_BIG_ENDIAN);
break;
}
proto_tree_add_item (docsis_tree, hf_docsis_macparm, tvb, 1, 1,
ENC_BIG_ENDIAN);
proto_tree_add_item (docsis_tree, hf_docsis_len, tvb, 2, 2,
ENC_BIG_ENDIAN);
proto_tree_add_item (docsis_tree, hf_docsis_hcs, tvb, 4, 2, ENC_BIG_ENDIAN);
break;
}
}
switch (fctype)
{
case FCTYPE_PACKET:
case FCTYPE_RESRVD:
if (pdulen >= 0)
{
if (pdulen > 0)
{
next_tvb = tvb_new_subset (tvb, hdrlen, captured_length, pdulen);
call_dissector (eth_withoutfcs_handle, next_tvb, pinfo, tree);
}
if (concatlen > 0)
{
concatlen = concatlen - framelen;
concatpos += framelen;
}
}
break;
case FCTYPE_MACSPC:
switch (fcparm)
{
case 0x00:
case 0x01:
if (pdulen > 0)
{
mgt_tvb = tvb_new_subset (tvb, hdrlen, captured_length, pdulen);
call_dissector (docsis_mgmt_handle, mgt_tvb, pinfo, tree);
}
if (concatlen > 0)
{
concatlen = concatlen - framelen;
concatpos += framelen;
}
break;
case 0x02:
break;
case 0x03:
if (pdulen > 0)
{
mgt_tvb = tvb_new_subset (tvb, hdrlen, captured_length, pdulen);
call_data_dissector(mgt_tvb, pinfo, tree);
}
if (concatlen > 0)
{
concatlen = concatlen - framelen;
concatpos += framelen;
}
break;
case 0x1c:
while (concatlen > 0)
{
oldconcatlen = concatlen;
next_tvb = tvb_new_subset (tvb, concatpos, -1, concatlen);
call_dissector (docsis_handle, next_tvb, pinfo, tree);
if (oldconcatlen <= concatlen)
THROW(ReportedBoundsError);
}
concatlen = 0;
concatpos = 0;
col_set_str(pinfo->cinfo, COL_INFO, "Concatenated Frame");
break;
}
break;
}
return tvb_captured_length(tvb);
}

static int
lldp_private_8023_print(netdissect_options *ndo,
const u_char *tptr, u_int tlv_len)
{
int subtype, hexdump = FALSE;
if (tlv_len < 4) {
return hexdump;
}
subtype = *(tptr+3);
ND_PRINT((ndo, "\n\t  %s Subtype (%u)",
tok2str(lldp_8023_subtype_values, "unknown", subtype),
subtype));
switch (subtype) {
case LLDP_PRIVATE_8023_SUBTYPE_MACPHY:
if (tlv_len < 9) {
return hexdump;
}
ND_PRINT((ndo, "\n\t    autonegotiation [%s] (0x%02x)",
bittok2str(lldp_8023_autonegotiation_values, "none", *(tptr+4)),
*(tptr + 4)));
ND_PRINT((ndo, "\n\t    PMD autoneg capability [%s] (0x%04x)",
bittok2str(lldp_pmd_capability_values,"unknown", EXTRACT_16BITS(tptr+5)),
EXTRACT_16BITS(tptr + 5)));
ND_PRINT((ndo, "\n\t    MAU type %s (0x%04x)",
tok2str(lldp_mau_types_values, "unknown", EXTRACT_16BITS(tptr+7)),
EXTRACT_16BITS(tptr + 7)));
break;
case LLDP_PRIVATE_8023_SUBTYPE_MDIPOWER:
if (tlv_len < 7) {
return hexdump;
}
ND_PRINT((ndo, "\n\t    MDI power support [%s], power pair %s, power class %s",
bittok2str(lldp_mdi_values, "none", *(tptr+4)),
tok2str(lldp_mdi_power_pairs_values, "unknown", *(tptr+5)),
tok2str(lldp_mdi_power_class_values, "unknown", *(tptr + 6))));
break;
case LLDP_PRIVATE_8023_SUBTYPE_LINKAGGR:
if (tlv_len < 9) {
return hexdump;
}
ND_PRINT((ndo, "\n\t    aggregation status [%s], aggregation port ID %u",
bittok2str(lldp_aggregation_values, "none", *(tptr+4)),
EXTRACT_32BITS(tptr + 5)));
break;
case LLDP_PRIVATE_8023_SUBTYPE_MTU:
ND_PRINT((ndo, "\n\t    MTU size %u", EXTRACT_16BITS(tptr + 4)));
break;
default:
hexdump = TRUE;
break;
}
return hexdump;
}

void processRtpPayload(PNV_VIDEO_PACKET videoPacket, int length) {
BUFFER_DESC currentPos;
int frameIndex;
char flags;
int firstPacket;
int streamPacketIndex;
videoPacket->streamPacketIndex >>= 8;
videoPacket->streamPacketIndex &= 0xFFFFFF;
currentPos.data = (char*)(videoPacket + 1);
currentPos.offset = 0;
currentPos.length = length - sizeof(*videoPacket);
frameIndex = videoPacket->frameIndex;
flags = videoPacket->flags;
firstPacket = isFirstPacket(flags);
streamPacketIndex = videoPacket->streamPacketIndex;
if (isBeforeSignedInt((short)streamPacketIndex, (short)(lastPacketInStream + 1), 0)) {
return;
}
if (isBeforeSignedInt(frameIndex, nextFrameNumber, 0)) {
return;
}
connectionSawFrame(frameIndex);
if (firstPacket && decodingFrame)
{
Limelog("Network dropped end of a frame\n");
nextFrameNumber = frameIndex;
waitingForNextSuccessfulFrame = 1;
dropFrameState();
}
else if (!firstPacket && !decodingFrame) {
if (flags == FLAG_CONTAINS_PIC_DATA ||
flags == FLAG_EOF ||
currentPos.length < nominalPacketDataLength)
{
Limelog("Network dropped beginning of a frame\n");
nextFrameNumber = frameIndex + 1;
waitingForNextSuccessfulFrame = 1;
dropFrameState();
decodingFrame = 0;
return;
}
else {
return;
}
}
else if (firstPacket) {
if (isBeforeSignedInt(nextFrameNumber, frameIndex, 1)) {
Limelog("Network dropped an entire frame\n");
nextFrameNumber = frameIndex;
waitingForNextSuccessfulFrame = 1;
dropFrameState();
}
else if (nextFrameNumber != frameIndex) {
decodingFrame = 0;
return;
}
decodingFrame = 1;
}
if (!firstPacket && decodingFrame) {
if (streamPacketIndex != (int)(lastPacketInStream + 1)) {
Limelog("Network dropped middle of a frame\n");
nextFrameNumber = frameIndex + 1;
waitingForNextSuccessfulFrame = 1;
dropFrameState();
decodingFrame = 0;
return;
}
}
if (streamPacketIndex != (int)(lastPacketInStream + 1)) {
connectionLostPackets(lastPacketInStream, streamPacketIndex);
}
lastPacketInStream = streamPacketIndex;
if (firstPacket && ServerMajorVersion >= 5) {
currentPos.offset += 8;
currentPos.length -= 8;
}
if (firstPacket && isIdrFrameStart(&currentPos))
{
processRtpPayloadSlow(videoPacket, &currentPos);
}
else
{
processRtpPayloadFast(currentPos);
}
if (flags & FLAG_EOF) {
decodingFrame = 0;
nextFrameNumber = frameIndex + 1;
if (waitingForNextSuccessfulFrame) {
connectionDetectedFrameLoss(startFrameNumber, nextFrameNumber - 1);
waitingForNextSuccessfulFrame = 0;
}
if (waitingForIdrFrame) {
Limelog("Waiting for IDR frame\n");
dropFrameState();
return;
}
reassembleFrame(frameIndex);
startFrameNumber = nextFrameNumber;
}
}

void Compute(OpKernelContext* context) override {
typedef Eigen::Map<const Eigen::Matrix<T, Eigen::Dynamic, Eigen::Dynamic>>
ConstEigenMatrixMap;
typedef Eigen::Map<Eigen::Matrix<T, Eigen::Dynamic, Eigen::Dynamic>>
EigenMatrixMap;
typedef Eigen::Map<Eigen::Matrix<int64, Eigen::Dynamic, Eigen::Dynamic>>
EigenIndexMatrixMap;
const Tensor& tensor_in = context->input(0);
const Tensor& tensor_out = context->input(1);
const Tensor& out_backprop = context->input(2);
const Tensor& height_seq_tensor = context->input(3);
const Tensor& width_seq_tensor = context->input(4);
constexpr int tensor_in_and_out_dims = 4;
std::vector<int64> input_size(tensor_in_and_out_dims);
std::vector<int64> output_size(tensor_in_and_out_dims);
for (int i = 0; i < tensor_in_and_out_dims; ++i) {
input_size[i] = tensor_in.dim_size(i);
}
for (int i = 0; i < tensor_in_and_out_dims; ++i) {
output_size[i] = tensor_out.dim_size(i);
}
Tensor tensor_out_dup;
OP_REQUIRES_OK(context, context->forward_input_or_allocate_temp(
{1}, DataTypeToEnum<T>::v(), tensor_out.shape(),
&tensor_out_dup));
Tensor tensor_out_arg_max;
OP_REQUIRES_OK(context, context->allocate_temp(DataTypeToEnum<int64>::v(),
tensor_out.shape(),
&tensor_out_arg_max));
ConstEigenMatrixMap tensor_in_mat(
tensor_in.flat<T>().data(), input_size[3],
input_size[2] * input_size[1] * input_size[0]);
EigenMatrixMap tensor_out_dup_mat(
tensor_out_dup.flat<T>().data(), output_size[3],
output_size[2] * output_size[1] * output_size[0]);
EigenIndexMatrixMap tensor_out_arg_max_mat(
tensor_out_arg_max.flat<int64>().data(), output_size[3],
output_size[2] * output_size[1] * output_size[0]);
tensor_out_arg_max.flat<int64>().setConstant(kInvalidMaxPoolingIndex);
tensor_out_dup.flat<T>().setConstant(Eigen::NumTraits<T>::lowest());
auto height_seq_tensor_flat = height_seq_tensor.flat<int64>();
auto width_seq_tensor_flat = width_seq_tensor.flat<int64>();
const int64 height_max = input_size[1] - 1;
const int64 width_max = input_size[2] - 1;
for (int64 b = 0; b < input_size[0]; ++b) {
for (int64 hs = 0; hs < height_seq_tensor.dim_size(0) - 1; ++hs) {
const int64 height_start = height_seq_tensor_flat(hs);
int64 height_end = overlapping_ ? height_seq_tensor_flat(hs + 1)
: height_seq_tensor_flat(hs + 1) - 1;
height_end = std::min(height_end, height_max);
for (int64 ws = 0; ws < width_seq_tensor.dim_size(0) - 1; ++ws) {
const int64 out_index =
(b * output_size[1] + hs) * output_size[2] + ws;
const int64 width_start = width_seq_tensor_flat(ws);
int64 width_end = overlapping_ ? width_seq_tensor_flat(ws + 1)
: width_seq_tensor_flat(ws + 1) - 1;
width_end = std::min(width_end, width_max);
for (int64 h = height_start; h <= height_end; ++h) {
for (int64 w = width_start; w <= width_end; ++w) {
const int64 in_index =
(b * input_size[1] + h) * input_size[2] + w;
for (int64 d = 0; d < input_size[3]; ++d) {
const T& input_ref = tensor_in_mat.coeffRef(d, in_index);
T& output_ref = tensor_out_dup_mat.coeffRef(d, out_index);
int64& out_arg_max_ref =
tensor_out_arg_max_mat.coeffRef(d, out_index);
if (output_ref < input_ref ||
out_arg_max_ref == kInvalidMaxPoolingIndex) {
output_ref = input_ref;
int input_offset = in_index * input_size[3] + d;
out_arg_max_ref = input_offset;
}
}
}
}
}
}
}
ConstEigenMatrixMap tensor_out_mat(
tensor_out.flat<T>().data(), output_size[3],
output_size[2] * output_size[1] * output_size[0]);
const int64 num_reshaped_cols =
output_size[2] * output_size[1] * output_size[0];
for (int64 i = 0; i < num_reshaped_cols; ++i) {
for (int64 j = 0; j < output_size[3]; ++j) {
DCHECK_EQ(tensor_out_dup_mat(j, i), tensor_out_mat(j, i));
}
}
Tensor* output = nullptr;
OP_REQUIRES_OK(context, context->forward_input_or_allocate_output(
{0}, 0, tensor_in.shape(), &output));
output->flat<T>().setZero();
auto out_backprop_flat = out_backprop.flat<T>();
auto input_backprop_flat = output->flat<T>();
auto out_arg_max_flat = tensor_out_arg_max.flat<int64>();
int num_total_outputs = out_backprop_flat.size();
int num_total_inputs = input_backprop_flat.size();
for (int index = 0; index < num_total_outputs; ++index) {
int input_backprop_index = out_arg_max_flat(index);
CHECK(input_backprop_index >= 0 &&
input_backprop_index < num_total_inputs)
<< "Invalid input backprop index: " << input_backprop_index << ", "
<< num_total_inputs;
input_backprop_flat(input_backprop_index) += out_backprop_flat(index);
}
}

void Compute(OpKernelContext* context) override {
OpInputList rt_nested_splits_in;
OP_REQUIRES_OK(
context, context->input_list("rt_nested_splits", &rt_nested_splits_in));
const int rt_nested_splits_len = rt_nested_splits_in.size();
DCHECK_GT(rt_nested_splits_len, 0);      std::vector<ConstFlatSplits> rt_nested_splits;
rt_nested_splits.reserve(rt_nested_splits_len);
for (int i = 0; i < rt_nested_splits_len; ++i) {
rt_nested_splits.push_back(rt_nested_splits_in[i].flat<SPLITS_TYPE>());
}
const Tensor& rt_dense_values_in = context->input(rt_nested_splits_len);
OP_REQUIRES_OK(context,
ValidateInputs(rt_nested_splits, rt_dense_values_in));
std::vector<int64> index_prefix(rt_nested_splits_len);
std::vector<std::vector<int64>> index_suffixes =
MakeIndexSuffixes(rt_dense_values_in.shape());
const int64_t nvals =
(rt_nested_splits.back()(rt_nested_splits.back().size() - 1) *
index_suffixes.size());
const int64_t indices_len =
rt_nested_splits_len + rt_dense_values_in.dims();
Tensor* sparse_indices_out = nullptr;
OP_REQUIRES_OK(
context, context->allocate_output(0, TensorShape({nvals, indices_len}),
&sparse_indices_out));
auto sparse_indices = sparse_indices_out->tensor<int64, 2>();
std::vector<int64> pos(rt_nested_splits_len);
int64& final_pos = pos[rt_nested_splits_len - 1];
int next_index = 0;
int max_final_pos = rt_nested_splits.back().size() - 1;
for (; final_pos < max_final_pos; ++final_pos) {
for (int dim = rt_nested_splits_len - 2; dim >= 0; --dim) {
while (IsCompleted(pos, dim, rt_nested_splits)) {
pos[dim] += 1;
}
}
for (int dim = 0; dim < index_prefix.size(); ++dim) {
int start = dim > 0 ? rt_nested_splits[dim - 1](pos[dim - 1]) : 0;
index_prefix[dim] = pos[dim] - start;
}
const auto& final_splits = rt_nested_splits[rt_nested_splits_len - 1];
int64_t slice_len = final_splits(final_pos + 1) - final_splits(final_pos);
for (int64_t i = 0; i < slice_len; ++i) {
for (const auto& index_suffix : index_suffixes) {
int dim = 0;
for (int64_t index : index_prefix) {              sparse_indices(next_index, dim++) = index;
}
sparse_indices(next_index, dim++) = i;            for (int64_t index : index_suffix) {                sparse_indices(next_index, dim++) = index;
}
DCHECK_EQ(dim, indices_len);
++next_index;
}
}
}
DCHECK_EQ(next_index, nvals);
if (rt_dense_values_in.dims() == 1) {
context->set_output(1, rt_dense_values_in);
} else {
Tensor sparse_values_out(rt_dense_values_in.dtype());
bool shapes_match = sparse_values_out.CopyFrom(
rt_dense_values_in, {rt_dense_values_in.NumElements()});
DCHECK(shapes_match);
context->set_output(1, sparse_values_out);
}
int64_t ndims = rt_nested_splits_len + rt_dense_values_in.dims();
Tensor* sparse_dense_shape_out = nullptr;
OP_REQUIRES_OK(context, context->allocate_output(2, TensorShape({ndims}),
&sparse_dense_shape_out));
auto sparse_dense_shape = sparse_dense_shape_out->vec<int64>();
sparse_dense_shape(0) = rt_nested_splits_in[0].dim_size(0) - 1;
for (int dim = 0; dim < rt_nested_splits_len; ++dim) {
const auto& splits = rt_nested_splits[dim];
SPLITS_TYPE max_width = 0;
for (int i = 1; i < splits.size(); ++i) {
max_width = std::max(max_width, splits(i) - splits(i - 1));
}
sparse_dense_shape(dim + 1) = max_width;
}
for (int dim = 1; dim < rt_dense_values_in.dims(); ++dim) {
sparse_dense_shape(dim + rt_nested_splits_len) =
rt_dense_values_in.dim_size(dim);
}
}

