}
}
if (load_raw == &LibRaw::lossy_dng_load_raw)
{
maximum = 0xffff;
FORC4 imgdata.color.linear_max[c] = imgdata.color.dng_levels.dng_whitelevel[c] = 0xffff;
}
else
{
maximum = imgdata.color.dng_levels.dng_whitelevel[0];
}
black = imgdata.color.dng_levels.dng_black;
if (tiff_samples == 2 && imgdata.color.dng_levels.dng_cblack[4] * imgdata.color.dng_levels.dng_cblack[5] * tiff_samples
== imgdata.color.dng_levels.dng_cblack[LIBRAW_CBLACK_SIZE - 1])
{
unsigned ff = filters;
if (filters > 999 && colors == 3)
filters |= ((filters >> 2 & 0x22222222) | (filters << 2 & 0x88888888)) &
filters << 1;
int csum[4] = { 0,0,0,0 }, ccount[4] = { 0,0,0,0 };
int i = 6 + shot_select;
for (unsigned row = 0; row < imgdata.color.dng_levels.dng_cblack[4]; row++)
for (unsigned col = 0; col < imgdata.color.dng_levels.dng_cblack[5]; col++)
{
csum[FC(row, col)] += imgdata.color.dng_levels.dng_cblack[i];
ccount[FC(row, col)]++;
i += tiff_samples;
}
for (int c = 0; c < 4; c++)
if (ccount[c])
imgdata.color.dng_levels.dng_cblack[c] += csum[c] / ccount[c];
imgdata.color.dng_levels.dng_cblack[4] = imgdata.color.dng_levels.dng_cblack[5] = 0;
filters = ff;
}
else if (tiff_samples > 2 && tiff_samples <= 4 && imgdata.color.dng_levels.dng_cblack[4] * imgdata.color.dng_levels.dng_cblack[5] * tiff_samples
== imgdata.color.dng_levels.dng_cblack[LIBRAW_CBLACK_SIZE - 1])
{
int csum[4] = { 0,0,0,0 }, ccount[4] = { 0,0,0,0 };
int i = 6;
for (unsigned row = 0; row < imgdata.color.dng_levels.dng_cblack[4]; row++)
for (unsigned col = 0; col < imgdata.color.dng_levels.dng_cblack[5]; col++)
for (unsigned c = 0; c < tiff_samples; c++)
{
csum[c] += imgdata.color.dng_levels.dng_cblack[i];
ccount[c]++;
i++;
}
for (int c = 0; c < 4; c++)
if (ccount[c])
imgdata.color.dng_levels.dng_cblack[c] += csum[c] / ccount[c];
imgdata.color.dng_levels.dng_cblack[4] = imgdata.color.dng_levels.dng_cblack[5] = 0;
}
memmove(cblack, imgdata.color.dng_levels.dng_cblack, sizeof(cblack));
if (iifd < (int)tiff_nifds && iifd >= 0)
{
int sidx = IFDLEVELINDEX(iifd, LIBRAW_DNGFM_LINEARRESPONSELIMIT);
if (sidx >= 0)
{
imgdata.color.dng_levels.LinearResponseLimit =
tiff_ifd[sidx].dng_levels.LinearResponseLimit;
if (imgdata.color.dng_levels.LinearResponseLimit > 0.1 &&
imgdata.color.dng_levels.LinearResponseLimit <= 1.0)
{
int bl4 = 0, bl64 = 0;
for (int chan = 0; chan < colors && chan < 4; chan++)
bl4 += cblack[chan];
bl4 /= LIM(colors, 1, 4);
if (cblack[4] * cblack[5] > 0)
{
unsigned cnt = 0;
for (unsigned c = 0; c < 4096 && c < cblack[4] * cblack[5]; c++)
{
bl64 += cblack[c + 6];
cnt++;
}
bl64 /= LIM(cnt, 1, 4096);
}
int rblack = black + bl4 + bl64;
for (int chan = 0; chan < colors && chan < 4; chan++)
imgdata.color.linear_max[chan] =
(maximum - rblack) *
imgdata.color.dng_levels.LinearResponseLimit +
rblack;
}
}
}
}
}

static MagickBooleanType WriteAnimatedWEBPImage(const ImageInfo *image_info,
Image *image,WebPConfig *configure,WebPData *webp_data,
ExceptionInfo *exception)
{
Image
*first_image;
size_t
effective_delta,
frame_timestamp;
WebPAnimEncoder
*enc;
WebPAnimEncoderOptions
enc_options;
WebPPicture
picture;
MagickBooleanType
status;
first_image=CoalesceImages(image,exception);
if (first_image == (Image *) NULL)
return(MagickFalse);
image=first_image;
effective_delta=0;
frame_timestamp=0;
(void) WebPAnimEncoderOptionsInit(&enc_options);
if (image_info->verbose)
enc_options.verbose=1;
enc=WebPAnimEncoderNew((int) image->page.width,(int) image->page.height,
&enc_options);
status=MagickTrue;
while (image != NULL)
{
status=(MagickBooleanType) WebPPictureInit(&picture);
if (status == MagickFalse)
{
(void) ThrowMagickException(exception,GetMagickModule(),
ResourceLimitError,"UnableToEncodeImageFile","`%s'",image->filename);
break;
}
status=WriteSingleWEBPPicture(image_info,image,configure,&picture,
exception);
if (status == MagickFalse)
break;
status=(MagickBooleanType) WebPAnimEncoderAdd(enc,&picture,
(int) frame_timestamp,configure);
WebPPictureFree(&picture);
if (status == MagickFalse)
{
(void) ThrowMagickException(exception,GetMagickModule(),
CoderError,WebPAnimEncoderGetError(enc),"`%s'",image->filename);
break;
}
effective_delta=image->delay*1000/image->ticks_per_second;
if (effective_delta < 10)
effective_delta=100; 
frame_timestamp+=effective_delta;
image=GetNextImageInList(image);
}
if (status != MagickFalse)
{
status=(MagickBooleanType) WebPAnimEncoderAdd(enc,(WebPPicture *) NULL,
(int) frame_timestamp,configure);
if (status != MagickFalse)
status=(MagickBooleanType) WebPAnimEncoderAssemble(enc,webp_data);
if (status == MagickFalse)
(void) ThrowMagickException(exception,GetMagickModule(),
CoderError,WebPAnimEncoderGetError(enc),"`%s'",
first_image->filename);
}
WebPAnimEncoderDelete(enc);
DestroyImageList(first_image);
return(status);
}

static Gif_Stream *
read_gif(Gif_Reader *grr, int read_flags,
const char* landmark, Gif_ReadErrorHandler handler)
{
Gif_Stream *gfs;
Gif_Image *gfi;
Gif_Context gfc;
int unknown_block_type = 0;
if (gifgetc(grr) != 'G' ||
gifgetc(grr) != 'I' ||
gifgetc(grr) != 'F')
return 0;
(void)gifgetc(grr);
(void)gifgetc(grr);
(void)gifgetc(grr);
gfs = Gif_NewStream();
gfi = Gif_NewImage();
gfc.stream = gfs;
gfc.prefix = Gif_NewArray(Gif_Code, GIF_MAX_CODE);
gfc.suffix = Gif_NewArray(uint8_t, GIF_MAX_CODE);
gfc.length = Gif_NewArray(uint16_t, GIF_MAX_CODE);
gfc.handler = handler;
gfc.gfi = gfi;
gfc.errors[0] = gfc.errors[1] = 0;
if (!gfs || !gfi || !gfc.prefix || !gfc.suffix || !gfc.length)
goto done;
gfs->landmark = landmark;
GIF_DEBUG(("\nGIF "));
if (!read_logical_screen_descriptor(gfs, grr))
goto done;
GIF_DEBUG(("logscrdesc "));
while (!gifeof(grr)) {
uint8_t block = gifgetbyte(grr);
switch (block) {
case ',': 
GIF_DEBUG(("imageread %d ", gfs->nimages));
gfi->identifier = last_name;
last_name = 0;
if (!Gif_AddImage(gfs, gfi))
goto done;
else if (!read_image(grr, &gfc, gfi, read_flags)) {
Gif_RemoveImage(gfs, gfs->nimages - 1);
goto done;
}
gfc.gfi = gfi = Gif_NewImage();
if (!gfi)
goto done;
break;
case ';': 
GIF_DEBUG(("term\n"));
goto done;
case '!': 
block = gifgetbyte(grr);
GIF_DEBUG(("ext(0x%02X) ", block));
switch (block) {
case 0xF9:
read_graphic_control_extension(&gfc, gfi, grr);
break;
case 0xCE:
last_name = suck_data(last_name, 0, grr);
break;
case 0xFE:
if (!read_comment_extension(gfi, grr)) goto done;
break;
case 0xFF:
read_application_extension(&gfc, grr);
break;
default:
read_unknown_extension(&gfc, grr, block, 0, 0);
break;
}
break;
default:
if (!unknown_block_type) {
char buf[256];
sprintf(buf, "unknown block type %d at file offset %u", block, grr->pos - 1);
gif_read_error(&gfc, 1, buf);
unknown_block_type = 1;
}
break;
}
}
done:
if (gfs && gfi) {
Gif_Extension* gfex;
gfs->end_comment = gfi->comment;
gfi->comment = 0;
gfs->end_extension_list = gfi->extension_list;
gfi->extension_list = 0;
for (gfex = gfs->end_extension_list; gfex; gfex = gfex->next)
gfex->image = NULL;
}
Gif_DeleteImage(gfi);
Gif_DeleteArray(last_name);
Gif_DeleteArray(gfc.prefix);
Gif_DeleteArray(gfc.suffix);
Gif_DeleteArray(gfc.length);
gfc.gfi = 0;
if (gfs)
gfs->errors = gfc.errors[1];
if (gfs && gfc.errors[1] == 0
&& !(read_flags & GIF_READ_TRAILING_GARBAGE_OK)
&& !grr->eofer(grr))
gif_read_error(&gfc, 0, "trailing garbage after GIF ignored");
gif_read_error(&gfc, -1, 0);
return gfs;
}

