m_iLastEntry ++;
m_pHeap[m_iLastEntry] = n;
n->m_llTimeStamp_tk = ts;
int q = m_iLastEntry;
int p = q;
while (p != 0)
{
p = (q - 1) >> 1;
if (m_pHeap[p]->m_llTimeStamp_tk > m_pHeap[q]->m_llTimeStamp_tk)
{
CSNode* t = m_pHeap[p];
m_pHeap[p] = m_pHeap[q];
m_pHeap[q] = t;
t->m_iHeapLoc = q;
q = p;
}
else
break;
}
n->m_iHeapLoc = q;
if (n->m_iHeapLoc == 0)
m_pTimer->interrupt();
if (0 == m_iLastEntry)
{
pthread_mutex_lock(m_pWindowLock);
pthread_cond_signal(m_pWindowCond);
pthread_mutex_unlock(m_pWindowLock);
}
}

void CSndUList::insert_(int64_t ts, const CUDT* u)
{
CSNode* n = u->m_pSNode;
if (n->m_iHeapLoc >= 0)
return;
m_iLastEntry ++;
m_pHeap[m_iLastEntry] = n;
n->m_llTimeStamp_tk = ts;
int q = m_iLastEntry;
int p = q;
while (p != 0)
{
p = (q - 1) >> 1;
if (m_pHeap[p]->m_llTimeStamp_tk > m_pHeap[q]->m_llTimeStamp_tk)
{
CSNode* t = m_pHeap[p];
m_pHeap[p] = m_pHeap[q];
m_pHeap[q] = t;
t->m_iHeapLoc = q;
q = p;
}
else
break;
}
n->m_iHeapLoc = q;
if (n->m_iHeapLoc == 0)
m_pTimer->interrupt();
if (0 == m_iLastEntry)
{
pthread_mutex_lock(m_pWindowLock);
pthread_cond_signal(m_pWindowCond);
pthread_mutex_unlock(m_pWindowLock);
}
}

static const ut8 *parse_attr_value(const ut8 *obuf, int obuf_len,
RBinDwarfAttrDef *def, RBinDwarfAttrValue *value,
const RBinDwarfCompUnitHdr *hdr,
const ut8 *debug_str, size_t debug_str_len) {
r_return_val_if_fail (def && value && hdr && obuf, NULL);
value->attr_form = def->attr_form;
value->attr_name = def->attr_name;
value->block.data = NULL;
value->string.content = NULL;
value->string.offset = 0;
const ut8 *buf = obuf;
const ut8 *buf_end = obuf + obuf_len;
size_t j;
if (obuf_len < 1) {
return NULL;
}
switch (def->attr_form) {
case DW_FORM_addr:
value->kind = DW_AT_KIND_ADDRESS;
switch (hdr->address_size) {
case 1:
value->address = READ8 (buf);
break;
case 2:
value->address = READ16 (buf);
break;
case 4:
value->address = READ32 (buf);
break;
case 8:
value->address = READ64 (buf);
break;
default:
R_LOG_WARN ("DWARF: Unexpected pointer size: %u", (unsigned)hdr->address_size);
return NULL;
}
break;
case DW_FORM_data1:
value->kind = DW_AT_KIND_CONSTANT;
value->uconstant = READ8 (buf);
break;
case DW_FORM_data2:
value->kind = DW_AT_KIND_CONSTANT;
value->uconstant = READ16 (buf);
break;
case DW_FORM_data4:
value->kind = DW_AT_KIND_CONSTANT;
value->uconstant = READ32 (buf);
break;
case DW_FORM_data8:
value->kind = DW_AT_KIND_CONSTANT;
value->uconstant = READ64 (buf);
break;
case DW_FORM_data16: value->kind = DW_AT_KIND_CONSTANT;
value->uconstant = READ64 (buf);
value->uconstant = READ64 (buf);
break;
case DW_FORM_sdata:
value->kind = DW_AT_KIND_CONSTANT;
buf = r_leb128 (buf, buf_end - buf, &value->sconstant);
break;
case DW_FORM_udata:
value->kind = DW_AT_KIND_CONSTANT;
buf = r_uleb128 (buf, buf_end - buf, &value->uconstant, NULL);
break;
case DW_FORM_string:
value->kind = DW_AT_KIND_STRING;
value->string.content = *buf ? r_str_ndup ((const char *)buf, buf_end - buf) : NULL;
if (value->string.content) {
buf += strlen (value->string.content) + 1;
}
break;
case DW_FORM_block1:
value->kind = DW_AT_KIND_BLOCK;
value->block.length = READ8 (buf);
buf = fill_block_data (buf, buf_end, &value->block);
break;
case DW_FORM_block2:
value->kind = DW_AT_KIND_BLOCK;
value->block.length = READ16 (buf);
if (value->block.length > 0) {
value->block.data = calloc (sizeof (ut8), value->block.length);
if (!value->block.data) {
return NULL;
}
for (j = 0; j < value->block.length; j++) {
value->block.data[j] = READ (buf, ut8);
}
}
break;
case DW_FORM_block4:
value->kind = DW_AT_KIND_BLOCK;
value->block.length = READ32 (buf);
buf = fill_block_data (buf, buf_end, &value->block);
break;
case DW_FORM_block: value->kind = DW_AT_KIND_BLOCK;
buf = r_uleb128 (buf, buf_end - buf, &value->block.length, NULL);
if (!buf || buf >= buf_end) {
return NULL;
}
buf = fill_block_data (buf, buf_end, &value->block);
break;
case DW_FORM_flag:
value->kind = DW_AT_KIND_FLAG;
value->flag = READ (buf, ut8);
break;
case DW_FORM_strp:
value->kind = DW_AT_KIND_STRING;
value->string.offset = dwarf_read_offset (hdr->is_64bit, &buf, buf_end);
if (debug_str && value->string.offset < debug_str_len) {
const char *ds = (const char *)(debug_str + value->string.offset);
value->string.content = strdup (ds); } else {
value->string.content = NULL; }
break;
case DW_FORM_ref_addr:
value->kind = DW_AT_KIND_REFERENCE;
value->reference = dwarf_read_offset (hdr->is_64bit, &buf, buf_end);
break;
case DW_FORM_ref1:
value->kind = DW_AT_KIND_REFERENCE;
value->reference = hdr->unit_offset + READ8 (buf);
break;
case DW_FORM_ref2:
value->kind = DW_AT_KIND_REFERENCE;
value->reference = hdr->unit_offset + READ16 (buf);
break;
case DW_FORM_ref4:
value->kind = DW_AT_KIND_REFERENCE;
value->reference = hdr->unit_offset + READ32 (buf);
break;
case DW_FORM_ref8:
value->kind = DW_AT_KIND_REFERENCE;
value->reference = hdr->unit_offset + READ64 (buf);
break;
case DW_FORM_ref_udata:
value->kind = DW_AT_KIND_REFERENCE;
buf = r_uleb128 (buf, buf_end - buf, &value->reference, NULL);
value->reference += hdr->unit_offset;
break;
case DW_FORM_sec_offset:
value->kind = DW_AT_KIND_REFERENCE;
value->reference = dwarf_read_offset(hdr->is_64bit, &buf, buf_end);
break;
case DW_FORM_exprloc:
value->kind = DW_AT_KIND_BLOCK;
buf = r_uleb128 (buf, buf_end - buf, &value->block.length, NULL);
if (!buf || buf >= buf_end) {
return NULL;
}
buf = fill_block_data (buf, buf_end, &value->block);
break;
case DW_FORM_flag_present:
value->kind = DW_AT_KIND_FLAG;
value->flag = true;
break;
case DW_FORM_ref_sig8:
value->kind = DW_AT_KIND_REFERENCE;
value->reference = READ64 (buf);
break;
case DW_FORM_strx:
value->kind = DW_AT_KIND_STRING;
break;
case DW_FORM_strx1:
value->kind = DW_AT_KIND_STRING;
value->string.offset = READ8 (buf);
break;
case DW_FORM_strx2:
value->kind = DW_AT_KIND_STRING;
value->string.offset = READ16 (buf);
break;
case DW_FORM_strx3: value->kind = DW_AT_KIND_STRING;
buf += 3;
break;
case DW_FORM_strx4:
value->kind = DW_AT_KIND_STRING;
value->string.offset = READ32 (buf);
break;
case DW_FORM_implicit_const:
value->kind = DW_AT_KIND_CONSTANT;
value->uconstant = def->special;
break;
case DW_FORM_addrx:
value->kind = DW_AT_KIND_ADDRESS;
buf = r_uleb128 (buf, buf_end - buf, &value->address, NULL);
break;
case DW_FORM_addrx1:
value->kind = DW_AT_KIND_ADDRESS;
value->address = READ8 (buf);
break;
case DW_FORM_addrx2:
value->kind = DW_AT_KIND_ADDRESS;
value->address = READ16 (buf);
break;
case DW_FORM_addrx3:
value->kind = DW_AT_KIND_ADDRESS;
buf += 3;
break;
case DW_FORM_addrx4:
value->kind = DW_AT_KIND_ADDRESS;
value->address = READ32 (buf);
break;
case DW_FORM_line_ptr: case DW_FORM_strp_sup: value->kind = DW_AT_KIND_STRING;
value->string.offset = dwarf_read_offset (hdr->is_64bit, &buf, buf_end);
break;
case DW_FORM_ref_sup4:
value->kind = DW_AT_KIND_REFERENCE;
value->reference = READ32 (buf);
break;
case DW_FORM_ref_sup8:
value->kind = DW_AT_KIND_REFERENCE;
value->reference = READ64 (buf);
break;
case DW_FORM_loclistx:
value->kind = DW_AT_KIND_LOCLISTPTR;
value->reference = dwarf_read_offset (hdr->is_64bit, &buf, buf_end);
break;
case DW_FORM_rnglistx:
value->kind = DW_AT_KIND_ADDRESS;
buf = r_uleb128 (buf, buf_end - buf, &value->address, NULL);
break;
case 0:
value->uconstant = 0;
return NULL;
default:
R_LOG_WARN ("Unknown DW_FORM 0x%02" PFMT64x, def->attr_form);
value->uconstant = 0;
return NULL;
}
return buf;
}

boolean NET_ReadSettings(net_packet_t *packet, net_gamesettings_t *settings)
{
boolean success;
int i;
success = NET_ReadInt8(packet, (unsigned int *) &settings->ticdup)
&& NET_ReadInt8(packet, (unsigned int *) &settings->extratics)
&& NET_ReadInt8(packet, (unsigned int *) &settings->deathmatch)
&& NET_ReadInt8(packet, (unsigned int *) &settings->nomonsters)
&& NET_ReadInt8(packet, (unsigned int *) &settings->fast_monsters)
&& NET_ReadInt8(packet, (unsigned int *) &settings->respawn_monsters)
&& NET_ReadInt8(packet, (unsigned int *) &settings->episode)
&& NET_ReadInt8(packet, (unsigned int *) &settings->map)
&& NET_ReadSInt8(packet, &settings->skill)
&& NET_ReadInt8(packet, (unsigned int *) &settings->gameversion)
&& NET_ReadInt8(packet, (unsigned int *) &settings->lowres_turn)
&& NET_ReadInt8(packet, (unsigned int *) &settings->new_sync)
&& NET_ReadInt32(packet, (unsigned int *) &settings->timelimit)
&& NET_ReadSInt8(packet, (signed int *) &settings->loadgame)
&& NET_ReadInt8(packet, (unsigned int *) &settings->random)
&& NET_ReadInt8(packet, (unsigned int *) &settings->num_players)
&& NET_ReadSInt8(packet, (signed int *) &settings->consoleplayer);
if (!success)
{
return false;
}
for (i = 0; i < settings->num_players; ++i)
{
if (!NET_ReadInt8(packet,
(unsigned int *) &settings->player_classes[i]))
{
return false;
}
}
return true;
}

