void Compute(OpKernelContext* context) override {
const Tensor& input = context->input(0);
const Tensor& filter = context->input(1);
const Tensor& out_backprop = context->input(2);
int stride_rows = 0, stride_cols = 0;
int rate_rows = 0, rate_cols = 0;
int64 pad_top = 0, pad_left = 0;
int64 out_rows = 0, out_cols = 0;
ParseSizes(context, strides_, rates_, padding_, &stride_rows, &stride_cols,
&rate_rows, &rate_cols, &pad_top, &pad_left, &out_rows,
&out_cols);
const int batch = input.dim_size(0);
const int depth = input.dim_size(3);
OP_REQUIRES(context,
batch == out_backprop.dim_size(0) &&
out_rows == out_backprop.dim_size(1) &&
out_cols == out_backprop.dim_size(2) &&
depth == out_backprop.dim_size(3),
errors::InvalidArgument("out_backprop has incompatible size."));
Tensor* filter_backprop = nullptr;
OP_REQUIRES_OK(
context, context->allocate_output(0, filter.shape(), &filter_backprop));
if (filter.shape().num_elements() == 0) {
return;
}
functor::DilationBackpropFilter<Device, T>()(
context->eigen_device<Device>(), input.tensor<T, 4>(),
filter.tensor<T, 3>(), out_backprop.tensor<T, 4>(), stride_rows,
stride_cols, rate_rows, rate_cols, pad_top, pad_left,
filter_backprop->tensor<T, 3>());
}

int blkcg_init_queue(struct request_queue *q)
{
struct blkcg_gq *new_blkg, *blkg;
bool preloaded;
int ret;
new_blkg = blkg_alloc(&blkcg_root, q, GFP_KERNEL);
if (!new_blkg)
return -ENOMEM;
preloaded = !radix_tree_preload(GFP_KERNEL);
rcu_read_lock();
spin_lock_irq(q->queue_lock);
blkg = blkg_create(&blkcg_root, q, new_blkg);
spin_unlock_irq(q->queue_lock);
rcu_read_unlock();
if (preloaded)
radix_tree_preload_end();
if (IS_ERR(blkg)) {
blkg_free(new_blkg);
return PTR_ERR(blkg);
}
q->root_blkg = blkg;
q->root_rl.blkg = blkg;
ret = blk_throtl_init(q);
if (ret) {
spin_lock_irq(q->queue_lock);
blkg_destroy_all(q);
spin_unlock_irq(q->queue_lock);
}
return ret;
}

static int relinquish_memory(
struct domain *d, struct page_list_head *list, unsigned long type)
{
struct page_info  *page;
unsigned long     x, y;
int               ret = 0;
spin_lock_recursive(&d->page_alloc_lock);
while ( (page = page_list_remove_head(list)) )
{
if ( unlikely(!get_page(page, d)) )
{
page_list_add_tail(page, &d->arch.relmem_list);
continue;
}
if ( test_and_clear_bit(_PGT_pinned, &page->u.inuse.type_info) )
ret = put_page_and_type_preemptible(page);
switch ( ret )
{
case 0:
break;
case -ERESTART:
case -EINTR:
if ( ret == -EINTR )
{
ASSERT(page->u.inuse.type_info & PGT_validated);
set_bit(_PGT_pinned, &page->u.inuse.type_info);
}
else
put_page(page);
ret = -ERESTART;
page_list_add(page, list);
put_page(page);
goto out;
default:
BUG();
}
put_page_alloc_ref(page);
y = page->u.inuse.type_info;
for ( ; ; )
{
x = y;
if ( likely((x & PGT_type_mask) != type) ||
likely(!(x & (PGT_validated|PGT_partial))) )
break;
y = cmpxchg(&page->u.inuse.type_info, x,
x & ~(PGT_validated|PGT_partial));
if ( likely(y == x) )
{
switch ( ret = free_page_type(page, x, 1) )
{
case 0:
break;
case -EINTR:
page_list_add(page, list);
page->u.inuse.type_info |= PGT_validated;
if ( x & PGT_partial )
put_page(page);
put_page(page);
ret = -ERESTART;
goto out;
case -ERESTART:
page_list_add(page, list);
page->u.inuse.type_info |= PGT_partial;
if ( x & PGT_partial )
put_page(page);
goto out;
default:
BUG();
}
if ( x & PGT_partial )
{
page->u.inuse.type_info--;
put_page(page);
}
break;
}
}
page_list_add_tail(page, &d->arch.relmem_list);
put_page(page);
if ( hypercall_preempt_check() )
{
ret = -ERESTART;
goto out;
}
}
page_list_move(list, &d->arch.relmem_list);
out:
spin_unlock_recursive(&d->page_alloc_lock);
return ret;
}

static void process_COM (const uchar * Data, int length)
{
int ch;
char Comment[MAX_COMMENT_SIZE+1];
int nch;
int a;
nch = 0;
if (length > MAX_COMMENT_SIZE) length = MAX_COMMENT_SIZE; 
for (a=2;a<length;a++){
ch = Data[a];
if (ch == '\r' && Data[a+1] == '\n') continue; 
if (ch >= 32 || ch == '\n' || ch == '\t'){
Comment[nch++] = (char)ch;
}else{
Comment[nch++] = '?';
}
}
Comment[nch] = '\0'; 
if (ShowTags){
printf("COM marker comment: %s\n",Comment);
}
strcpy(ImageInfo.Comments,Comment);
}

static coap_oscore_conf_t *
coap_parse_oscore_conf_mem(coap_str_const_t conf_mem) {
const char *start = (const char *)conf_mem.s;
const char *end = start + conf_mem.length;
coap_str_const_t keyword;
oscore_value_t value;
coap_oscore_conf_t *oscore_conf;
oscore_conf = coap_malloc_type(COAP_STRING, sizeof(coap_oscore_conf_t));
if (oscore_conf == NULL)
return NULL;
memset(oscore_conf, 0, sizeof(coap_oscore_conf_t));
memset(&value, 0, sizeof(value));
oscore_conf->replay_window = COAP_OSCORE_DEFAULT_REPLAY_WINDOW;
oscore_conf->ssn_freq = 1;
oscore_conf->aead_alg = COSE_ALGORITHM_AES_CCM_16_64_128;
oscore_conf->hkdf_alg = COSE_HKDF_ALG_HKDF_SHA_256;
oscore_conf->rfc8613_b_1_2 = 1;
oscore_conf->rfc8613_b_2 = 0;
oscore_conf->break_sender_key = 0;
oscore_conf->break_recipient_key = 0;
while (end > start &&
get_split_entry(&start, end - start, &keyword, &value)) {
size_t i;
size_t j;
for (i = 0; i < sizeof(oscore_config) / sizeof(oscore_config[0]); i++) {
if (memcmp(oscore_config[i].keyword, keyword.s, keyword.length) == 0 &&
value.encoding & oscore_config[i].encoding) {
if (memcmp(keyword.s, "recipient_id", keyword.length) == 0) {
if (value.u.value_bin->length > 7) {
coap_log_warn(
"oscore_conf: Maximum size of recipient_id is 7 bytes\n");
goto error_free_value_bin;
}
oscore_conf->recipient_id =
coap_realloc_type(COAP_STRING,
oscore_conf->recipient_id,
sizeof(oscore_conf->recipient_id[0]) *
(oscore_conf->recipient_id_count + 1));
if (oscore_conf->recipient_id == NULL) {
goto error_free_value_bin;
}
oscore_conf->recipient_id[oscore_conf->recipient_id_count++] =
value.u.value_bin;
} else {
coap_bin_const_t *unused_check;
switch (value.encoding) {
case COAP_ENC_HEX:
case COAP_ENC_ASCII:
memcpy(&unused_check,
&(((char *)oscore_conf)[oscore_config[i].offset]),
sizeof(unused_check));
if (unused_check != NULL) {
coap_log_warn(
"oscore_conf: Keyword '%.*s' duplicated\n",
(int)keyword.length,
(const char *)keyword.s);
goto error;
}
memcpy(&(((char *)oscore_conf)[oscore_config[i].offset]),
&value.u.value_bin,
sizeof(value.u.value_bin));
break;
case COAP_ENC_INTEGER:
case COAP_ENC_BOOL:
memcpy(&(((char *)oscore_conf)[oscore_config[i].offset]),
&value.u.value_int,
sizeof(value.u.value_int));
break;
case COAP_ENC_TEXT:
for (j = 0; oscore_config[i].text_mapping[j].text != NULL; j++) {
if (memcmp(value.u.value_str.s,
oscore_config[i].text_mapping[j].text,
value.u.value_str.length) == 0) {
memcpy(&(((char *)oscore_conf)[oscore_config[i].offset]),
&oscore_config[i].text_mapping[j].value,
sizeof(oscore_config[i].text_mapping[j].value));
break;
}
}
if (oscore_config[i].text_mapping[j].text == NULL) {
coap_log_warn(
"oscore_conf: Keyword '%.*s': value '%.*s' unknown\n",
(int)keyword.length,
(const char *)keyword.s,
(int)value.u.value_str.length,
(const char *)value.u.value_str.s);
goto error;
}
break;
case COAP_ENC_LAST:
default:
assert(0);
break;
}
}
break;
}
}
if (i == sizeof(oscore_config) / sizeof(oscore_config[0])) {
coap_log_warn(
"oscore_conf: Keyword '%.*s', type '%s' unknown\n",
(int)keyword.length,
(const char *)keyword.s,
value.encoding_name);
if (value.encoding == COAP_ENC_HEX || value.encoding == COAP_ENC_ASCII)
coap_delete_bin_const(value.u.value_bin);
goto error;
}
}
if (!oscore_conf->master_secret) {
coap_log_warn(
"oscore_conf: master_secret not defined\n");
goto error;
}
if (!oscore_conf->sender_id) {
coap_log_warn(
"oscore_conf: sender_id not defined\n");
goto error;
}
if (oscore_conf->sender_id->length > 7) {
coap_log_warn(
"oscore_conf: Maximum size of sender_id is 7 bytes\n");
goto error;
}
if (oscore_conf->recipient_id && oscore_conf->recipient_id[0]->length > 7) {
coap_log_warn(
"oscore_conf: Maximum size of recipient_id is 7 bytes\n");
goto error;
}
return oscore_conf;
error_free_value_bin:
coap_delete_bin_const(value.u.value_bin);
error:
coap_delete_oscore_conf(oscore_conf);
return NULL;
}

uint32_t
guest_walk_tables(struct vcpu *v, struct p2m_domain *p2m,
unsigned long va, walk_t *gw, 
uint32_t pfec, mfn_t top_mfn, void *top_map)
{
struct domain *d = v->domain;
p2m_type_t p2mt;
guest_l1e_t *l1p = NULL;
guest_l2e_t *l2p = NULL;
#if GUEST_PAGING_LEVELS >= 4 
guest_l3e_t *l3p = NULL;
guest_l4e_t *l4p;
#endif
unsigned int pkey;
uint32_t gflags, mflags, iflags, rc = 0;
bool_t smep = 0, smap = 0;
bool_t pse1G = 0, pse2M = 0;
p2m_query_t qt = P2M_ALLOC | P2M_UNSHARE;
perfc_incr(guest_walk);
memset(gw, 0, sizeof(*gw));
gw->va = va;
mflags = mandatory_flags(v, pfec);
iflags = (_PAGE_NX_BIT | _PAGE_INVALID_BITS);
if ( is_hvm_domain(d) && !(pfec & PFEC_user_mode) )
{
struct segment_register seg;
const struct cpu_user_regs *regs = guest_cpu_user_regs();
smep =  hvm_smep_enabled(v) && (pfec & PFEC_insn_fetch);
switch ( v->arch.smap_check_policy )
{
case SMAP_CHECK_HONOR_CPL_AC:
hvm_get_segment_register(v, x86_seg_ss, &seg);
smap = hvm_smap_enabled(v) &&
((seg.attr.fields.dpl == 3) ||
!(regs->eflags & X86_EFLAGS_AC));
break;
case SMAP_CHECK_ENABLED:
smap = hvm_smap_enabled(v);
break;
default:
ASSERT(v->arch.smap_check_policy == SMAP_CHECK_DISABLED);
break;
}
}
if ( smep || smap )
mflags |= _PAGE_USER;
#if GUEST_PAGING_LEVELS >= 3 
#if GUEST_PAGING_LEVELS >= 4 
gw->l4mfn = top_mfn;
l4p = (guest_l4e_t *) top_map;
gw->l4e = l4p[guest_l4_table_offset(va)];
gflags = guest_l4e_get_flags(gw->l4e) ^ iflags;
if ( !(gflags & _PAGE_PRESENT) ) {
rc |= _PAGE_PRESENT;
goto out;
}
rc |= ((gflags & mflags) ^ mflags);
l3p = map_domain_gfn(p2m, 
guest_l4e_get_gfn(gw->l4e), 
&gw->l3mfn,
&p2mt,
qt,
&rc); 
if(l3p == NULL)
goto out;
gw->l3e = l3p[guest_l3_table_offset(va)];
pkey = guest_l3e_get_pkey(gw->l3e);
gflags = guest_l3e_get_flags(gw->l3e) ^ iflags;
if ( !(gflags & _PAGE_PRESENT) ) {
rc |= _PAGE_PRESENT;
goto out;
}
rc |= ((gflags & mflags) ^ mflags);
pse1G = (gflags & _PAGE_PSE) && guest_supports_1G_superpages(v); 
if ( pse1G )
{
gfn_t start = guest_l3e_get_gfn(gw->l3e);
int flags = (_PAGE_PRESENT|_PAGE_USER|_PAGE_RW|
_PAGE_ACCESSED|_PAGE_DIRTY);
flags |= (guest_l3e_get_flags(gw->l3e)
& (_PAGE_PAT|_PAGE_PWT|_PAGE_PCD));
if ( !(gfn_x(start) & 1) )
flags &= ~_PAGE_PAT;
if ( gfn_x(start) & GUEST_L3_GFN_MASK & ~0x1 )
rc |= _PAGE_INVALID_BITS;
start = _gfn((gfn_x(start) & ~GUEST_L3_GFN_MASK) +
((va >> PAGE_SHIFT) & GUEST_L3_GFN_MASK));
gw->l1e = guest_l1e_from_gfn(start, flags);
gw->l2mfn = gw->l1mfn = _mfn(INVALID_MFN);
goto set_ad;
}
#else 
gw->l3e = ((guest_l3e_t *) top_map)[guest_l3_table_offset(va)];
if ( !(guest_l3e_get_flags(gw->l3e) & _PAGE_PRESENT) ) 
{
rc |= _PAGE_PRESENT;
goto out;
}
#endif 
l2p = map_domain_gfn(p2m, 
guest_l3e_get_gfn(gw->l3e), 
&gw->l2mfn,
&p2mt, 
qt,
&rc); 
if(l2p == NULL)
goto out;
gw->l2e = l2p[guest_l2_table_offset(va)];
#else 
gw->l2mfn = top_mfn;
l2p = (guest_l2e_t *) top_map;
gw->l2e = l2p[guest_l2_table_offset(va)];
#endif 
pkey = guest_l2e_get_pkey(gw->l2e);
gflags = guest_l2e_get_flags(gw->l2e) ^ iflags;
if ( !(gflags & _PAGE_PRESENT) ) {
rc |= _PAGE_PRESENT;
goto out;
}
rc |= ((gflags & mflags) ^ mflags);
pse2M = (gflags & _PAGE_PSE) && guest_supports_superpages(v); 
if ( pse2M )
{
gfn_t start = guest_l2e_get_gfn(gw->l2e);
int flags = (_PAGE_PRESENT|_PAGE_USER|_PAGE_RW|
_PAGE_ACCESSED|_PAGE_DIRTY);
flags |= (guest_l2e_get_flags(gw->l2e)
& (_PAGE_PAT|_PAGE_PWT|_PAGE_PCD));
if ( !(gfn_x(start) & 1) )
flags &= ~_PAGE_PAT;
if ( gfn_x(start) & GUEST_L2_GFN_MASK & ~0x1 )
rc |= _PAGE_INVALID_BITS;
start = _gfn((gfn_x(start) & ~GUEST_L2_GFN_MASK) +
guest_l1_table_offset(va));
gw->l1e = guest_l1e_from_gfn(start, flags);
gw->l1mfn = _mfn(INVALID_MFN);
} 
else 
{
l1p = map_domain_gfn(p2m, 
guest_l2e_get_gfn(gw->l2e), 
&gw->l1mfn,
&p2mt,
qt,
&rc);
if(l1p == NULL)
goto out;
gw->l1e = l1p[guest_l1_table_offset(va)];
pkey = guest_l1e_get_pkey(gw->l1e);
gflags = guest_l1e_get_flags(gw->l1e) ^ iflags;
if ( !(gflags & _PAGE_PRESENT) ) {
rc |= _PAGE_PRESENT;
goto out;
}
rc |= ((gflags & mflags) ^ mflags);
}
#if GUEST_PAGING_LEVELS >= 4 
set_ad:
if ( pkey_fault(v, pfec, gflags, pkey) )
rc |= _PAGE_PKEY_BITS;
#endif
if ( smep || smap )
rc ^= _PAGE_USER;
if ( rc == 0 ) 
{
#if GUEST_PAGING_LEVELS == 4 
if ( set_ad_bits(l4p + guest_l4_table_offset(va), &gw->l4e, 0) )
paging_mark_dirty(d, mfn_x(gw->l4mfn));
if ( set_ad_bits(l3p + guest_l3_table_offset(va), &gw->l3e,
(pse1G && (pfec & PFEC_write_access))) )
paging_mark_dirty(d, mfn_x(gw->l3mfn));
#endif
if ( !pse1G ) 
{
if ( set_ad_bits(l2p + guest_l2_table_offset(va), &gw->l2e,
(pse2M && (pfec & PFEC_write_access))) )
paging_mark_dirty(d, mfn_x(gw->l2mfn));            
if ( !pse2M ) 
{
if ( set_ad_bits(l1p + guest_l1_table_offset(va), &gw->l1e, 
(pfec & PFEC_write_access)) )
paging_mark_dirty(d, mfn_x(gw->l1mfn));
}
}
}
out:
#if GUEST_PAGING_LEVELS == 4
if ( l3p ) 
{
unmap_domain_page(l3p);
put_page(mfn_to_page(mfn_x(gw->l3mfn)));
}
#endif
#if GUEST_PAGING_LEVELS >= 3
if ( l2p ) 
{
unmap_domain_page(l2p);
put_page(mfn_to_page(mfn_x(gw->l2mfn)));
}
#endif
if ( l1p ) 
{
unmap_domain_page(l1p);
put_page(mfn_to_page(mfn_x(gw->l1mfn)));
}
if ( !(rc & _PAGE_PRESENT)
&& gfn_x(guest_l1e_get_gfn(gw->l1e)) >> d->arch.paging.gfn_bits )
rc |= _PAGE_INVALID_BITS;
return rc;
}

int ksmbd_decode_ntlmssp_auth_blob(struct authenticate_message *authblob,
int blob_len, struct ksmbd_conn *conn,
struct ksmbd_session *sess)
{
char *domain_name;
unsigned int nt_off, dn_off;
unsigned short nt_len, dn_len;
#ifdef CONFIG_SMB_INSECURE_SERVER
unsigned int lm_off;
unsigned short lm_len;
#endif
int ret;
if (blob_len < sizeof(struct authenticate_message)) {
ksmbd_debug(AUTH, "negotiate blob len %d too small\n",
blob_len);
return -EINVAL;
}
if (memcmp(authblob->Signature, "NTLMSSP", 8)) {
ksmbd_debug(AUTH, "blob signature incorrect %s\n",
authblob->Signature);
return -EINVAL;
}
nt_off = le32_to_cpu(authblob->NtChallengeResponse.BufferOffset);
nt_len = le16_to_cpu(authblob->NtChallengeResponse.Length);
dn_off = le32_to_cpu(authblob->DomainName.BufferOffset);
dn_len = le16_to_cpu(authblob->DomainName.Length);
if (blob_len < (u64)dn_off + dn_len || blob_len < (u64)nt_off + nt_len)
return -EINVAL;
#ifdef CONFIG_SMB_INSECURE_SERVER
lm_off = le32_to_cpu(authblob->LmChallengeResponse.BufferOffset);
lm_len = le16_to_cpu(authblob->LmChallengeResponse.Length);
if (blob_len < (u64)lm_off + lm_len)
return -EINVAL;
if (nt_len == CIFS_AUTH_RESP_SIZE) {
if (le32_to_cpu(authblob->NegotiateFlags) &
NTLMSSP_NEGOTIATE_EXTENDED_SEC)
return __ksmbd_auth_ntlmv2(sess,
(char *)authblob + lm_off,
(char *)authblob + nt_off,
conn->ntlmssp.cryptkey);
else
return ksmbd_auth_ntlm(sess, (char *)authblob +
nt_off, conn->ntlmssp.cryptkey);
}
#endif
domain_name = smb_strndup_from_utf16((const char *)authblob + dn_off,
dn_len, true, conn->local_nls);
if (IS_ERR(domain_name))
return PTR_ERR(domain_name);
ksmbd_debug(AUTH, "decode_ntlmssp_authenticate_blob dname%s\n",
domain_name);
ret = ksmbd_auth_ntlmv2(conn, sess,
(struct ntlmv2_resp *)((char *)authblob + nt_off),
nt_len - CIFS_ENCPWD_SIZE,
domain_name, conn->ntlmssp.cryptkey);
kfree(domain_name);
if (conn->ntlmssp.client_flags & NTLMSSP_NEGOTIATE_KEY_XCH) {
struct arc4_ctx *ctx_arc4;
unsigned int sess_key_off, sess_key_len;
sess_key_off = le32_to_cpu(authblob->SessionKey.BufferOffset);
sess_key_len = le16_to_cpu(authblob->SessionKey.Length);
if (blob_len < (u64)sess_key_off + sess_key_len)
return -EINVAL;
ctx_arc4 = kmalloc(sizeof(*ctx_arc4), GFP_KERNEL);
if (!ctx_arc4)
return -ENOMEM;
cifs_arc4_setkey(ctx_arc4, sess->sess_key,
SMB2_NTLMV2_SESSKEY_SIZE);
cifs_arc4_crypt(ctx_arc4, sess->sess_key,
(char *)authblob + sess_key_off, sess_key_len);
#if LINUX_VERSION_CODE >= KERNEL_VERSION(5, 9, 0)
kfree_sensitive(ctx_arc4);
#else
memzero_explicit((void *)ctx_arc4, sizeof(*ctx_arc4));
kfree(ctx_arc4);
#endif
}
return ret;
}

int
add_mibfile(const char* tmpstr, const char* d_name, FILE *ip )
{
FILE           *fp;
char            token[MAXTOKEN], token2[MAXTOKEN];
if ((fp = fopen(tmpstr, "r")) == NULL) {
snmp_log_perror(tmpstr);
return 1;
}
DEBUGMSGTL(("parse-mibs", "Checking file: %s...\n",
tmpstr));
mibLine = 1;
File = tmpstr;
if (get_token(fp, token, MAXTOKEN) != LABEL) {
fclose(fp);
return 1;
}
if (get_token(fp, token2, MAXTOKEN) == DEFINITIONS) {
new_module(token, tmpstr);
if (ip)
fprintf(ip, "%s %s\n", token, d_name);
fclose(fp);
return 0;
} else {
fclose(fp);
return 1;
}
}

