opj_image_t* tgatoimage(const char *filename, opj_cparameters_t *parameters)
{
FILE *f;
opj_image_t *image;
unsigned int image_width, image_height, pixel_bit_depth;
unsigned int x, y;
int flip_image = 0;
opj_image_cmptparm_t cmptparm[4];   
int numcomps;
OPJ_COLOR_SPACE color_space;
OPJ_BOOL mono ;
OPJ_BOOL save_alpha;
int subsampling_dx, subsampling_dy;
int i;
f = fopen(filename, "rb");
if (!f) {
fprintf(stderr, "Failed to open %s for reading !!\n", filename);
return 0;
}
if (!tga_readheader(f, &pixel_bit_depth, &image_width, &image_height,
&flip_image)) {
fclose(f);
return NULL;
}
if (!((pixel_bit_depth == 24) || (pixel_bit_depth == 32))) {
fclose(f);
return NULL;
}
memset(&cmptparm[0], 0, 4 * sizeof(opj_image_cmptparm_t));
mono = (pixel_bit_depth == 8) ||
(pixel_bit_depth == 16);  
save_alpha = (pixel_bit_depth == 16) ||
(pixel_bit_depth == 32); 
if (mono) {
color_space = OPJ_CLRSPC_GRAY;
numcomps = save_alpha ? 2 : 1;
} else {
numcomps = save_alpha ? 4 : 3;
color_space = OPJ_CLRSPC_SRGB;
}
subsampling_dx = parameters->subsampling_dx;
subsampling_dy = parameters->subsampling_dy;
for (i = 0; i < numcomps; i++) {
cmptparm[i].prec = 8;
cmptparm[i].bpp = 8;
cmptparm[i].sgnd = 0;
cmptparm[i].dx = (OPJ_UINT32)subsampling_dx;
cmptparm[i].dy = (OPJ_UINT32)subsampling_dy;
cmptparm[i].w = image_width;
cmptparm[i].h = image_height;
}
image = opj_image_create((OPJ_UINT32)numcomps, &cmptparm[0], color_space);
if (!image) {
fclose(f);
return NULL;
}
image->x0 = (OPJ_UINT32)parameters->image_offset_x0;
image->y0 = (OPJ_UINT32)parameters->image_offset_y0;
image->x1 = !image->x0 ? (OPJ_UINT32)(image_width - 1)  *
(OPJ_UINT32)subsampling_dx + 1 : image->x0 + (OPJ_UINT32)(image_width - 1)  *
(OPJ_UINT32)subsampling_dx + 1;
image->y1 = !image->y0 ? (OPJ_UINT32)(image_height - 1) *
(OPJ_UINT32)subsampling_dy + 1 : image->y0 + (OPJ_UINT32)(image_height - 1) *
(OPJ_UINT32)subsampling_dy + 1;
for (y = 0; y < image_height; y++) {
int index;
if (flip_image) {
index = (int)((image_height - y - 1) * image_width);
} else {
index = (int)(y * image_width);
}
if (numcomps == 3) {
for (x = 0; x < image_width; x++) {
unsigned char r, g, b;
if (!fread(&b, 1, 1, f)) {
fprintf(stderr,
"\nError: fread return a number of element different from the expected.\n");
opj_image_destroy(image);
fclose(f);
return NULL;
}
if (!fread(&g, 1, 1, f)) {
fprintf(stderr,
"\nError: fread return a number of element different from the expected.\n");
opj_image_destroy(image);
fclose(f);
return NULL;
}
if (!fread(&r, 1, 1, f)) {
fprintf(stderr,
"\nError: fread return a number of element different from the expected.\n");
opj_image_destroy(image);
fclose(f);
return NULL;
}
image->comps[0].data[index] = r;
image->comps[1].data[index] = g;
image->comps[2].data[index] = b;
index++;
}
} else if (numcomps == 4) {
for (x = 0; x < image_width; x++) {
unsigned char r, g, b, a;
if (!fread(&b, 1, 1, f)) {
fprintf(stderr,
"\nError: fread return a number of element different from the expected.\n");
opj_image_destroy(image);
fclose(f);
return NULL;
}
if (!fread(&g, 1, 1, f)) {
fprintf(stderr,
"\nError: fread return a number of element different from the expected.\n");
opj_image_destroy(image);
fclose(f);
return NULL;
}
if (!fread(&r, 1, 1, f)) {
fprintf(stderr,
"\nError: fread return a number of element different from the expected.\n");
opj_image_destroy(image);
fclose(f);
return NULL;
}
if (!fread(&a, 1, 1, f)) {
fprintf(stderr,
"\nError: fread return a number of element different from the expected.\n");
opj_image_destroy(image);
fclose(f);
return NULL;
}
image->comps[0].data[index] = r;
image->comps[1].data[index] = g;
image->comps[2].data[index] = b;
image->comps[3].data[index] = a;
index++;
}
} else {
fprintf(stderr, "Currently unsupported bit depth : %s\n", filename);
}
}
fclose(f);
return image;
}

void CLASS panasonic_load_raw()
{
int row, col, i, j, sh = 0, pred[2], nonz[2];
pana_bits(0);
for (row = 0; row < height; row++)
{
#ifdef LIBRAW_LIBRARY_BUILD
checkCancel();
#endif
for (col = 0; col < raw_width; col++)
{
if ((i = col % 14) == 0)
pred[0] = pred[1] = nonz[0] = nonz[1] = 0;
if (i % 3 == 2)
sh = 4 >> (3 - pana_bits(2));
if (nonz[i & 1])
{
if ((j = pana_bits(8)))
{
if ((pred[i & 1] -= 0x80 << sh) < 0 || sh == 4)
pred[i & 1] &= ~((~0u) << sh);
pred[i & 1] += j << sh;
}
}
else if ((nonz[i & 1] = pana_bits(8)) || i > 11)
pred[i & 1] = nonz[i & 1] << 4 | pana_bits(4);
if ((RAW(row, col) = pred[col & 1]) > 4098 && col < width)
derror();
}
}
}

static CACHE_BITMAP_V3_ORDER* update_read_cache_bitmap_v3_order(rdpUpdate* update, wStream* s,
UINT16 flags)
{
BYTE bitsPerPixelId;
BITMAP_DATA_EX* bitmapData;
UINT32 new_len;
BYTE* new_data;
CACHE_BITMAP_V3_ORDER* cache_bitmap_v3;
if (!update || !s)
return NULL;
cache_bitmap_v3 = calloc(1, sizeof(CACHE_BITMAP_V3_ORDER));
if (!cache_bitmap_v3)
goto fail;
cache_bitmap_v3->cacheId = flags & 0x00000003;
cache_bitmap_v3->flags = (flags & 0x0000FF80) >> 7;
bitsPerPixelId = (flags & 0x00000078) >> 3;
cache_bitmap_v3->bpp = CBR23_BPP[bitsPerPixelId];
if (Stream_GetRemainingLength(s) < 21)
goto fail;
Stream_Read_UINT16(s, cache_bitmap_v3->cacheIndex); 
Stream_Read_UINT32(s, cache_bitmap_v3->key1);       
Stream_Read_UINT32(s, cache_bitmap_v3->key2);       
bitmapData = &cache_bitmap_v3->bitmapData;
Stream_Read_UINT8(s, bitmapData->bpp);
if ((bitmapData->bpp < 1) || (bitmapData->bpp > 32))
{
WLog_Print(update->log, WLOG_ERROR, "invalid bpp value %" PRIu32 "", bitmapData->bpp);
goto fail;
}
Stream_Seek_UINT8(s);                      
Stream_Seek_UINT8(s);                      
Stream_Read_UINT8(s, bitmapData->codecID); 
Stream_Read_UINT16(s, bitmapData->width);  
Stream_Read_UINT16(s, bitmapData->height); 
Stream_Read_UINT32(s, new_len);            
if ((new_len == 0) || (Stream_GetRemainingLength(s) < new_len))
goto fail;
new_data = (BYTE*)realloc(bitmapData->data, new_len);
if (!new_data)
goto fail;
bitmapData->data = new_data;
bitmapData->length = new_len;
Stream_Read(s, bitmapData->data, bitmapData->length);
return cache_bitmap_v3;
fail:
free_cache_bitmap_v3_order(update->context, cache_bitmap_v3);
return NULL;
}

static bool ok_jpg_read_sof(ok_jpg_decoder *decoder) {
ok_jpg *jpg = decoder->jpg;
uint8_t buffer[3 * 3];
if (!ok_read(decoder, buffer, 8)) {
return false;
}
int length = readBE16(buffer) - 8;
int P = buffer[2];
if (P != 8) {
ok_jpg_error(jpg, OK_JPG_ERROR_INVALID, "Invalid component size");
return false;
}
decoder->in_height = readBE16(buffer + 3);
decoder->in_width = readBE16(buffer + 5);
if (decoder->in_width == 0 || decoder->in_height == 0) {
ok_jpg_error(jpg, OK_JPG_ERROR_INVALID, "Invalid image dimensions");
return false;
}
jpg->width = decoder->rotate ? decoder->in_height : decoder->in_width;
jpg->height = decoder->rotate ? decoder->in_width : decoder->in_height;
jpg->bpp = 4;     decoder->num_components = buffer[7];
uint64_t stride = (uint64_t)jpg->width * jpg->bpp;
if (stride > INT32_MAX) {
ok_jpg_error(jpg, OK_JPG_ERROR_UNSUPPORTED, "Width too large");
return false;
}
jpg->stride = (uint32_t)stride;
if (decoder->num_components == 4) {
ok_jpg_error(jpg, OK_JPG_ERROR_UNSUPPORTED, "Unsupported format (CMYK)");
return false;
}
if (decoder->num_components != 1 && decoder->num_components != 3) {
ok_jpg_error(jpg, OK_JPG_ERROR_UNSUPPORTED, "Invalid component count");
return false;
}
if (length < 3 * decoder->num_components) {
ok_jpg_error(jpg, OK_JPG_ERROR_INVALID, "SOF segment too short");
return false;
}
if (!ok_read(decoder, buffer, 3 * (size_t)decoder->num_components)) {
return false;
}
int maxH = 1;
int maxV = 1;
int minH = 4;
int minV = 4;
for (int i = 0; i < decoder->num_components; i++) {
ok_jpg_component *c = decoder->components + i;
c->id = buffer[i * 3 + 0];
c->H = buffer[i * 3 + 1] >> 4;
c->V = buffer[i * 3 + 1] & 0x0F;
c->Tq = buffer[i * 3 + 2];
if (c->H == 0 || c->V == 0 || c->H > 4 || c->V > 4 || c->Tq > 3) {
ok_jpg_error(jpg, OK_JPG_ERROR_INVALID, "Bad component");
return false;
}
if (c->H > MAX_SAMPLING_FACTOR || c->V > MAX_SAMPLING_FACTOR) {
ok_jpg_error(jpg, OK_JPG_ERROR_UNSUPPORTED, "Unsupported sampling factor");
return false;
}
maxH = max(maxH, c->H);
maxV = max(maxV, c->V);
minH = min(minH, c->H);
minV = min(minV, c->V);
length -= 3;
}
if (minH > 1 || minV > 1) {
maxH = 1;
maxV = 1;
for (int i = 0; i < decoder->num_components; i++) {
ok_jpg_component *c = decoder->components + i;
c->H /= minH;
c->V /= minV;
maxH = max(maxH, c->H);
maxV = max(maxV, c->V);
}
}
decoder->data_units_x = intDivCeil(decoder->in_width, maxH * 8);
decoder->data_units_y = intDivCeil(decoder->in_height, maxV * 8);
if (length > 0) {
if (!ok_seek(decoder, length)) {
return false;
}
}
for (int i = 0; i < decoder->num_components; i++) {
ok_jpg_component *c = decoder->components + i;
c->blocks_h = intDivCeil(decoder->in_width, (maxH / c->H) * 8);
c->blocks_v = intDivCeil(decoder->in_height, (maxV / c->V) * 8);
if (c->H == maxH && c->V == maxV) {
c->idct = ok_jpg_idct_8x8;
} else if (c->H * 2 == maxH && c->V * 2 == maxV) {
c->idct = ok_jpg_idct_16x16;
} else if (c->H == maxH && c->V * 2 == maxV) {
c->idct = ok_jpg_idct_8x16;
} else if (c->H * 2 == maxH && c->V == maxV) {
c->idct = ok_jpg_idct_16x8;
} else {
ok_jpg_error(jpg, OK_JPG_ERROR_UNSUPPORTED, "Unsupported IDCT sampling factor");
return false;
}
}
if (!decoder->info_only) {
if (decoder->sof_found) {
ok_jpg_error(jpg, OK_JPG_ERROR_INVALID, "Invalid JPEG (Multiple SOF markers)");
return false;
}
decoder->sof_found = true;
if (decoder->progressive) {
for (int i = 0; i < decoder->num_components; i++) {
ok_jpg_component *c = decoder->components + i;
size_t num_blocks = (size_t)(decoder->data_units_x * c->H *
decoder->data_units_y * c->V);
size_t size = num_blocks * 64 * sizeof(*c->blocks) + OK_JPG_BLOCK_EXTRA_SPACE;
c->blocks = decoder->allocator.alloc(decoder->allocator_user_data, size);
if (!c->blocks) {
ok_jpg_error(jpg, OK_JPG_ERROR_ALLOCATION,
"Couldn't allocate internal block memory for image");
return false;
}
}
}
if (!jpg->data) {
if (decoder->allocator.image_alloc) {
decoder->allocator.image_alloc(decoder->allocator_user_data,
jpg->width, jpg->height, jpg->bpp,
&jpg->data, &jpg->stride);
} else {
uint64_t size = (uint64_t)jpg->stride * jpg->height;
size_t platform_size = (size_t)size;
if (platform_size == size) {
jpg->data = decoder->allocator.alloc(decoder->allocator_user_data, platform_size);
}
}
if (!jpg->data) {
ok_jpg_error(jpg, OK_JPG_ERROR_ALLOCATION, "Couldn't allocate memory for image");
return false;
}
if (jpg->stride < jpg->width * jpg->bpp) {
ok_jpg_error(jpg, OK_JPG_ERROR_API, "Invalid stride");
return false;
}
}
}
#if 0
printf("SOF: Components %i (", decoder->num_components);
for (int i = 0; i < decoder->num_components; i++) {
ok_jpg_component *c = decoder->components + i;
if (i != 0) {
printf(",");
}
printf("%ix%i", maxH/c->H, maxV/c->V);
}
printf(")\n");
#endif
return true;
}

static int unimac_mdio_probe(struct platform_device *pdev)
{
struct unimac_mdio_pdata *pdata = pdev->dev.platform_data;
struct unimac_mdio_priv *priv;
struct device_node *np;
struct mii_bus *bus;
struct resource *r;
int ret;
np = pdev->dev.of_node;
priv = devm_kzalloc(&pdev->dev, sizeof(*priv), GFP_KERNEL);
if (!priv)
return -ENOMEM;
r = platform_get_resource(pdev, IORESOURCE_MEM, 0);
priv->base = devm_ioremap(&pdev->dev, r->start, resource_size(r));
if (!priv->base) {
dev_err(&pdev->dev, "failed to remap register\n");
return -ENOMEM;
}
priv->mii_bus = mdiobus_alloc();
if (!priv->mii_bus)
return -ENOMEM;
bus = priv->mii_bus;
bus->priv = priv;
if (pdata) {
bus->name = pdata->bus_name;
priv->wait_func = pdata->wait_func;
priv->wait_func_data = pdata->wait_func_data;
bus->phy_mask = ~pdata->phy_mask;
} else {
bus->name = "unimac MII bus";
priv->wait_func_data = priv;
priv->wait_func = unimac_mdio_poll;
}
bus->parent = &pdev->dev;
bus->read = unimac_mdio_read;
bus->write = unimac_mdio_write;
bus->reset = unimac_mdio_reset;
snprintf(bus->id, MII_BUS_ID_SIZE, "%s-%d", pdev->name, pdev->id);
ret = of_mdiobus_register(bus, np);
if (ret) {
dev_err(&pdev->dev, "MDIO bus registration failed\n");
goto out_mdio_free;
}
platform_set_drvdata(pdev, priv);
dev_info(&pdev->dev, "Broadcom UniMAC MDIO bus at 0x%p\n", priv->base);
return 0;
out_mdio_free:
mdiobus_free(bus);
return ret;
}

