static int propagate_one(struct mount *m)
{
struct mount *child;
int type;
if (IS_MNT_NEW(m))
return 0;
if (!is_subdir(mp->m_dentry, m->mnt.mnt_root))
return 0;
if (peers(m, last_dest)) {
type = CL_MAKE_SHARED;
} else {
struct mount *n, *p;
bool done;
for (n = m; ; n = p) {
p = n->mnt_master;
if (p == dest_master || IS_MNT_MARKED(p))
break;
}
do {
struct mount *parent = last_source->mnt_parent;
if (last_source == first_source)
break;
done = parent->mnt_master == p;
if (done && peers(n, parent))
break;
last_source = last_source->mnt_master;
} while (!done);
type = CL_SLAVE;
if (IS_MNT_SHARED(m))
type |= CL_MAKE_SHARED;
}
if (m->mnt_ns->user_ns != user_ns)
type |= CL_UNPRIVILEGED;
child = copy_tree(last_source, last_source->mnt.mnt_root, type);
if (IS_ERR(child))
return PTR_ERR(child);
child->mnt.mnt_flags &= ~MNT_LOCKED;
mnt_set_mountpoint(m, mp, child);
last_dest = m;
last_source = child;
if (m->mnt_master != dest_master) {
read_seqlock_excl(&mount_lock);
SET_MNT_MARK(m->mnt_master);
read_sequnlock_excl(&mount_lock);
}
hlist_add_head(&child->mnt_hash, list);
return 0;
}

bool PDFDoc::setup(const GooString *ownerPassword, const GooString *userPassword) {
pdfdocLocker();
if (str->getLength() <= 0)
{
error(errSyntaxError, -1, "Document stream is empty");
return false;
}
str->setPos(0, -1);
if (str->getPos() < 0)
{
error(errSyntaxError, -1, "Document base stream is not seekable");
return false;
}
str->reset();
checkHeader();
bool wasReconstructed = false;
xref = new XRef(str, getStartXRef(), getMainXRefEntriesOffset(), &wasReconstructed);
if (!xref->isOk()) {
if (wasReconstructed) {
delete xref;
startXRefPos = -1;
xref = new XRef(str, getStartXRef(true), getMainXRefEntriesOffset(true), &wasReconstructed);
}
if (!xref->isOk()) {
error(errSyntaxError, -1, "Couldn't read xref table");
errCode = xref->getErrorCode();
return false;
}
}
if (!checkEncryption(ownerPassword, userPassword)) {
errCode = errEncrypted;
return false;
}
catalog = new Catalog(this);
if (catalog && !catalog->isOk()) {
if (!wasReconstructed)
{
delete catalog;
delete xref;
xref = new XRef(str, 0, 0, nullptr, true);
catalog = new Catalog(this);
}
if (catalog && !catalog->isOk()) {
error(errSyntaxError, -1, "Couldn't read page catalog");
errCode = errBadCatalog;
return false;
}
}
extractPDFSubtype();
return true;
}

void SoftAACEncoder2::onQueueFilled(OMX_U32 ) {
if (mSignalledError) {
return;
}
List<BufferInfo *> &inQueue = getPortQueue(0);
List<BufferInfo *> &outQueue = getPortQueue(1);
if (!mSentCodecSpecificData) {
if (outQueue.empty()) {
return;
}
if (AACENC_OK != aacEncEncode(mAACEncoder, NULL, NULL, NULL, NULL)) {
ALOGE("Unable to initialize encoder for profile / sample-rate / bit-rate / channels");
notify(OMX_EventError, OMX_ErrorUndefined, 0, NULL);
mSignalledError = true;
return;
}
OMX_U32 actualBitRate  = aacEncoder_GetParam(mAACEncoder, AACENC_BITRATE);
if (mBitRate != actualBitRate) {
ALOGW("Requested bitrate %u unsupported, using %u", mBitRate, actualBitRate);
}
AACENC_InfoStruct encInfo;
if (AACENC_OK != aacEncInfo(mAACEncoder, &encInfo)) {
ALOGE("Failed to get AAC encoder info");
notify(OMX_EventError, OMX_ErrorUndefined, 0, NULL);
mSignalledError = true;
return;
}
BufferInfo *outInfo = *outQueue.begin();
OMX_BUFFERHEADERTYPE *outHeader = outInfo->mHeader;
outHeader->nFilledLen = encInfo.confSize;
outHeader->nFlags = OMX_BUFFERFLAG_CODECCONFIG;
uint8_t *out = outHeader->pBuffer + outHeader->nOffset;
memcpy(out, encInfo.confBuf, encInfo.confSize);
outQueue.erase(outQueue.begin());
outInfo->mOwnedByUs = false;
notifyFillBufferDone(outHeader);
mSentCodecSpecificData = true;
}
size_t numBytesPerInputFrame =
mNumChannels * kNumSamplesPerFrame * sizeof(int16_t);
if (mAACProfile == OMX_AUDIO_AACObjectELD && numBytesPerInputFrame > 512) {
numBytesPerInputFrame = 512;
}
for (;;) {
while (mInputSize < numBytesPerInputFrame) {
if (mSawInputEOS || inQueue.empty()) {
return;
}
BufferInfo *inInfo = *inQueue.begin();
OMX_BUFFERHEADERTYPE *inHeader = inInfo->mHeader;
const void *inData = inHeader->pBuffer + inHeader->nOffset;
size_t copy = numBytesPerInputFrame - mInputSize;
if (copy > inHeader->nFilledLen) {
copy = inHeader->nFilledLen;
}
if (mInputFrame == NULL) {
mInputFrame = new int16_t[numBytesPerInputFrame / sizeof(int16_t)];
}
if (mInputSize == 0) {
mInputTimeUs = inHeader->nTimeStamp;
}
memcpy((uint8_t *)mInputFrame + mInputSize, inData, copy);
mInputSize += copy;
inHeader->nOffset += copy;
inHeader->nFilledLen -= copy;
inHeader->nTimeStamp +=
(copy * 1000000ll / mSampleRate)
/ (mNumChannels * sizeof(int16_t));
if (inHeader->nFilledLen == 0) {
if (inHeader->nFlags & OMX_BUFFERFLAG_EOS) {
mSawInputEOS = true;
memset((uint8_t *)mInputFrame + mInputSize,
0,
numBytesPerInputFrame - mInputSize);
mInputSize = numBytesPerInputFrame;
}
inQueue.erase(inQueue.begin());
inInfo->mOwnedByUs = false;
notifyEmptyBufferDone(inHeader);
inData = NULL;
inHeader = NULL;
inInfo = NULL;
}
}
if (outQueue.empty()) {
return;
}
BufferInfo *outInfo = *outQueue.begin();
OMX_BUFFERHEADERTYPE *outHeader = outInfo->mHeader;
uint8_t *outPtr = (uint8_t *)outHeader->pBuffer + outHeader->nOffset;
size_t outAvailable = outHeader->nAllocLen - outHeader->nOffset;
AACENC_InArgs inargs;
AACENC_OutArgs outargs;
memset(&inargs, 0, sizeof(inargs));
memset(&outargs, 0, sizeof(outargs));
inargs.numInSamples = numBytesPerInputFrame / sizeof(int16_t);
void* inBuffer[]        = { (unsigned char *)mInputFrame };
INT   inBufferIds[]     = { IN_AUDIO_DATA };
INT   inBufferSize[]    = { (INT)numBytesPerInputFrame };
INT   inBufferElSize[]  = { sizeof(int16_t) };
AACENC_BufDesc inBufDesc;
inBufDesc.numBufs           = sizeof(inBuffer) / sizeof(void*);
inBufDesc.bufs              = (void**)&inBuffer;
inBufDesc.bufferIdentifiers = inBufferIds;
inBufDesc.bufSizes          = inBufferSize;
inBufDesc.bufElSizes        = inBufferElSize;
void* outBuffer[]       = { outPtr };
INT   outBufferIds[]    = { OUT_BITSTREAM_DATA };
INT   outBufferSize[]   = { 0 };
INT   outBufferElSize[] = { sizeof(UCHAR) };
AACENC_BufDesc outBufDesc;
outBufDesc.numBufs           = sizeof(outBuffer) / sizeof(void*);
outBufDesc.bufs              = (void**)&outBuffer;
outBufDesc.bufferIdentifiers = outBufferIds;
outBufDesc.bufSizes          = outBufferSize;
outBufDesc.bufElSizes        = outBufferElSize;
AACENC_ERROR encoderErr = AACENC_OK;
size_t nOutputBytes = 0;
do {
memset(&outargs, 0, sizeof(outargs));
outBuffer[0] = outPtr;
outBufferSize[0] = outAvailable - nOutputBytes;
encoderErr = aacEncEncode(mAACEncoder,
&inBufDesc,
&outBufDesc,
&inargs,
&outargs);
if (encoderErr == AACENC_OK) {
outPtr += outargs.numOutBytes;
nOutputBytes += outargs.numOutBytes;
if (outargs.numInSamples > 0) {
int numRemainingSamples = inargs.numInSamples - outargs.numInSamples;
if (numRemainingSamples > 0) {
memmove(mInputFrame,
&mInputFrame[outargs.numInSamples],
sizeof(int16_t) * numRemainingSamples);
}
inargs.numInSamples -= outargs.numInSamples;
}
}
} while (encoderErr == AACENC_OK && inargs.numInSamples > 0);
outHeader->nFilledLen = nOutputBytes;
outHeader->nFlags = OMX_BUFFERFLAG_ENDOFFRAME;
if (mSawInputEOS) {
outHeader->nFlags = OMX_BUFFERFLAG_EOS;
}
outHeader->nTimeStamp = mInputTimeUs;
#if 0
ALOGI("sending %d bytes of data (time = %lld us, flags = 0x%08lx)",
nOutputBytes, mInputTimeUs, outHeader->nFlags);
hexdump(outHeader->pBuffer + outHeader->nOffset, outHeader->nFilledLen);
#endif
outQueue.erase(outQueue.begin());
outInfo->mOwnedByUs = false;
notifyFillBufferDone(outHeader);
outHeader = NULL;
outInfo = NULL;
mInputSize = 0;
}
}

void
server_cb(void *arg)
{
nano_work     *work = arg;
nng_msg       *msg  = NULL;
nng_msg       *smsg = NULL;
int            rv;
mqtt_msg_info *msg_info;
switch (work->state) {
case INIT:
work->state = RECV;
if (work->proto == PROTO_MQTT_BROKER) {
log_debug("INIT ^^^^^^^^ ctx [%d] ^^^^^^^^ \n", work->ctx.id);
nng_ctx_recv(work->ctx, work->aio);
} else {
log_debug("INIT ^^^^^^^^ extra ctx [%d] ^^^^^^^^ \n", work->extra_ctx.id);
nng_ctx_recv(work->extra_ctx, work->aio);
}
break;
case RECV:
log_debug("RECV  ^^^^ ctx%d ^^^^\n", work->ctx.id);
if ((rv = nng_aio_result(work->aio)) != 0) {
log_warn("RECV nng aio result error: %d", rv);
work->state = RECV;
if (work->proto == PROTO_MQTT_BROKER) {
nng_ctx_recv(work->ctx, work->aio);
break;
} else {
log_info("bridge connection closed with reason %d\n", rv);
if (rv != NNG_ECONNSHUT) {
nng_ctx_recv(work->extra_ctx, work->aio);
break;
}
}
}
if ((msg = nng_aio_get_msg(work->aio)) == NULL) {
nng_fatal("RECV NULL MSG", rv);
}
if (work->proto == PROTO_MQTT_BRIDGE) {
uint8_t type;
type = nng_msg_get_type(msg);
if (type == CMD_CONNACK) {
log_info("bridge client is connected!");
} else if (type != CMD_PUBLISH) {
work->state = RECV;
nng_msg_free(msg);
nng_ctx_recv(work->extra_ctx, work->aio);
break;
} else {
conn_param_clone(nng_msg_get_conn_param(msg));
}
} else if (work->proto == PROTO_HTTP_SERVER ||
work->proto == PROTO_AWS_BRIDGE) {
nng_msg *decode_msg = NULL;
if (decode_common_mqtt_msg(&decode_msg, msg) != 0 ||
nng_msg_get_type(decode_msg) != CMD_PUBLISH) {
conn_param_free(nng_msg_get_conn_param(decode_msg));
work->state = RECV;
nng_ctx_recv(work->extra_ctx, work->aio);
break;
}
msg = decode_msg;
nng_msg_set_cmd_type(msg, CMD_PUBLISH);
}
work->msg       = msg;
work->pid       = nng_msg_get_pipe(work->msg);
work->cparam    = nng_msg_get_conn_param(work->msg);
work->proto_ver = conn_param_get_protover(work->cparam);
work->flag      = nng_msg_cmd_type(msg);
if (work->flag == CMD_SUBSCRIBE) {
smsg = work->msg;
work->msg_ret = NULL;
if ((work->sub_pkt = nng_alloc(
sizeof(packet_subscribe))) == NULL)
log_error("nng_alloc");
memset(work->sub_pkt, '\0', sizeof(packet_subscribe));
if ((rv = decode_sub_msg(work)) != 0 ||
(rv = sub_ctx_handle(work)) != 0) {
work->code = rv;
log_error("sub_handler: [%d]", rv);
}
if (work->code != SUCCESS) {
if (work->msg_ret)
cvector_free(work->msg_ret);
if (work->sub_pkt)
sub_pkt_free(work->sub_pkt);
conn_param_free(work->cparam);
work->state = CLOSE;
nng_aio_finish(work->aio, 0);
break;
}
if (0 != (rv = encode_suback_msg(smsg, work)))
log_error("error in encode suback: [%d]", rv);
sub_pkt_free(work->sub_pkt);
work->msg = NULL;
if (work->msg_ret) {
log_debug("retain msg [%p] size [%ld] \n",
work->msg_ret,
cvector_size(work->msg_ret));
for (int i = 0;
i < cvector_size(work->msg_ret) &&
check_msg_exp(work->msg_ret[i],
nng_mqtt_msg_get_publish_property(
work->msg_ret[i]));
i++) {
nng_msg *m = work->msg_ret[i];
if (!work->config->sqlite.enable) {
nng_msg_clone(m);
}
work->msg = m;
nng_aio_set_msg(work->aio, work->msg);
nng_aio_set_prov_data(work->aio, &work->pid.id);
nng_ctx_send(work->ctx, work->aio);
}
cvector_free(work->msg_ret);
}
nng_msg_set_cmd_type(smsg, CMD_SUBACK);
nng_aio_set_prov_data(work->aio, &work->pid.id);
nng_aio_set_msg(work->aio, smsg);
work->msg   = NULL;
work->state = SEND;
nng_ctx_send(work->ctx, work->aio);
smsg = NULL;
nng_aio_finish(work->aio, 0);
break;
} else if (work->flag == CMD_UNSUBSCRIBE) {
smsg = work->msg;
if ((work->unsub_pkt = nng_alloc(
sizeof(packet_unsubscribe))) == NULL)
log_error("nng_alloc");
if ((rv = decode_unsub_msg(work)) != 0 ||
(rv = unsub_ctx_handle(work)) != 0) {
log_error("unsub_handler [%d]", rv);
}
if (0 != (rv = encode_unsuback_msg(smsg, work)))
log_error("in unsuback [%d]", rv);
unsub_pkt_free(work->unsub_pkt);
nng_aio_set_prov_data(work->aio, &work->pid.id);
nng_aio_set_msg(work->aio, work->msg);
work->msg   = NULL;
work->state = SEND;
nng_ctx_send(work->ctx, work->aio);
smsg = NULL;
nng_aio_finish(work->aio, 0);
break;
} else if (work->flag == CMD_PUBLISH) {
if (work->proto_ver == 5) {
nng_msg_set_cmd_type(msg, CMD_PUBLISH_V5);
} else {
nng_msg_set_cmd_type(msg, CMD_PUBLISH);
}
work->code = handle_pub(
work, work->pipe_ct, work->proto_ver, false);
if (work->proto == PROTO_HTTP_SERVER ||
work->proto == PROTO_AWS_BRIDGE) {
nng_msg *rep_msg;
nng_msg_alloc(&rep_msg, 0);
nng_aio_set_msg(work->aio, rep_msg);
if (work->code == SUCCESS)
work->state = WAIT;
else
work->state = SEND;
nng_ctx_send(work->extra_ctx, work->aio);
break;
}
if (work->code != SUCCESS) {
if (work->proto != PROTO_MQTT_BROKER) {
work->state = SEND;
nng_aio_finish(work->aio, 0);
break;
}
work->state = CLOSE;
free_pub_packet(work->pub_packet);
work->pub_packet = NULL;
cvector_free(work->pipe_ct->msg_infos);
conn_param_free(work->cparam);
nng_aio_finish(work->aio, 0);
break;
}
} else if (work->flag == CMD_CONNACK) {
uint8_t *body        = nng_msg_body(work->msg);
uint8_t  reason_code = *(body + 1);
if (work->proto == PROTO_MQTT_BROKER) {
nng_aio_set_prov_data(work->aio, &work->pid.id);
nng_msg_clone(work->msg);
nng_aio_set_msg(work->aio, work->msg);
nng_ctx_send(work->ctx, work->aio);
}
smsg = nano_msg_notify_connect(work->cparam, reason_code);
webhook_entry(work, reason_code);
nng_msg_set_cmd_type(smsg, CMD_PUBLISH);
work->flag = CMD_PUBLISH;
nng_msg_free(work->msg);
work->msg = smsg;
handle_pub(work, work->pipe_ct,
MQTT_PROTOCOL_VERSION_v311, true);
} else if (work->flag == CMD_DISCONNECT_EV) {
webhook_entry(work, 0);
nng_msg_set_cmd_type(msg, CMD_PUBLISH);
work->flag = CMD_PUBLISH;
handle_pub(work, work->pipe_ct,
MQTT_PROTOCOL_VERSION_v311, true);
if (dbhash_check_id(work->pid.id)) {
destroy_sub_client(work->pid.id, work->db);
}
if (conn_param_get_will_flag(work->cparam) == 0 ||
!conn_param_get_will_topic(work->cparam) ||
!conn_param_get_will_msg(work->cparam)) {
conn_param_free(work->cparam);
} else {
work->state = END;
nng_aio_finish(work->aio, 0);
break;
}
}
work->state = WAIT;
nng_aio_finish(work->aio, 0);
break;
case WAIT:
log_debug("WAIT ^^^^ ctx%d ^^^^", work->ctx.id);
if (nng_msg_get_type(work->msg) == CMD_PUBLISH) {
if ((rv = nng_aio_result(work->aio)) != 0) {
log_error("WAIT nng aio result error: %d", rv);
nng_fatal("WAIT nng_ctx_recv/send", rv);
}
smsg      = work->msg; cvector(mqtt_msg_info) msg_infos;
msg_infos = work->pipe_ct->msg_infos;
log_trace("total pipes: %ld", cvector_size(msg_infos));
if (cvector_size(msg_infos))
if (encode_pub_message(smsg, work, PUBLISH))
for (int i = 0; i < cvector_size(msg_infos) && rv== 0; ++i) {
msg_info = &msg_infos[i];
nng_msg_clone(smsg);
work->pid.id = msg_info->pipe;
nng_aio_set_prov_data(work->aio, &work->pid.id);
work->msg = smsg;
nng_aio_set_msg(work->aio, work->msg);
nng_ctx_send(work->ctx, work->aio);
}
work->msg = smsg;
if (work->config->bridge_mode) {
bridge_handler(work);
#if defined(SUPP_AWS_BRIDGE)
aws_bridge_forward(work);
#endif
}
conf_web_hook *hook_conf   = &(work->config->web_hook);
uint8_t rule_opt = RULE_ENG_OFF;
#if defined(SUPP_RULE_ENGINE)
rule_opt = work->config->rule_eng.option;
#endif
if (hook_conf->enable || rule_opt != RULE_ENG_OFF) {
work->state = SEND;
nng_aio_finish(work->aio, 0);
break;
}
nng_msg_free(work->msg);
smsg = NULL;
work->msg = NULL;
conn_param_free(work->cparam);
free_pub_packet(work->pub_packet);
work->pub_packet = NULL;
cvector_free(msg_infos);
work->pipe_ct->msg_infos = NULL;
init_pipe_content(work->pipe_ct);
work->state = RECV;
if (work->proto != PROTO_MQTT_BROKER) {
nng_ctx_recv(work->extra_ctx, work->aio);
} else {
nng_ctx_recv(work->ctx, work->aio);
}
} else if (nng_msg_cmd_type(work->msg) == CMD_PUBACK ||
nng_msg_cmd_type(work->msg) == CMD_PUBREL ||
nng_msg_cmd_type(work->msg) == CMD_PUBCOMP) {
nng_msg_free(work->msg);
work->msg   = NULL;
work->state = RECV;
nng_ctx_recv(work->ctx, work->aio);
break;
} else {
log_debug("broker has nothing to do");
if (work->msg != NULL)
nng_msg_free(work->msg);
work->msg   = NULL;
work->state = RECV;
nng_ctx_recv(work->ctx, work->aio);
break;
}
break;
case SEND:
log_debug("SEND ^^^^ ctx%d ^^^^", work->ctx.id);
#if defined(SUPP_RULE_ENGINE)
if (work->flag == CMD_PUBLISH && work->config->rule_eng.option != RULE_ENG_OFF) {
rule_engine_insert_sql(work);
}
#endif
webhook_entry(work, 0);
if (NULL != work->msg) {
nng_msg_free(work->msg);
work->msg = NULL;
}
if ((rv = nng_aio_result(work->aio)) != 0) {
nng_fatal("SEND nng_ctx_send", rv);
}
if (work->pub_packet != NULL) {
free_pub_packet(work->pub_packet);
work->pub_packet = NULL;
}
if (work->pipe_ct->msg_infos != NULL) {
cvector_free(work->pipe_ct->msg_infos);
work->pipe_ct->msg_infos = NULL;
init_pipe_content(work->pipe_ct);
}
conn_param_free(work->cparam);
work->state = RECV;
work->flag  = 0;
if (work->proto == PROTO_MQTT_BROKER) {
nng_ctx_recv(work->ctx, work->aio);
} else{
nng_ctx_recv(work->extra_ctx, work->aio);
}
break;
case END:
log_debug("END ^^^^ ctx%d ^^^^ ", work->ctx.id);
if (nng_msg_get_type(work->msg) == CMD_PUBLISH) {
if ((rv = nng_aio_result(work->aio)) != 0) {
log_error("WAIT nng aio result error: %d", rv);
nng_fatal("WAIT nng_ctx_recv/send", rv);
}
smsg      = work->msg; work->msg = NULL;
cvector(mqtt_msg_info) msg_infos;
msg_infos = work->pipe_ct->msg_infos;
log_debug("total pipes: %ld", cvector_size(msg_infos));
if (cvector_size(msg_infos))
if (encode_pub_message(smsg, work, PUBLISH))
for (int i=0; i<cvector_size(msg_infos); ++i) {
msg_info = &msg_infos[i];
nng_msg_clone(smsg);
work->pid.id = msg_info->pipe;
nng_aio_set_prov_data(work->aio, &work->pid.id);
work->msg = smsg;
nng_aio_set_msg(work->aio, work->msg);
nng_ctx_send(work->ctx, work->aio);
}
webhook_entry(work, 0);
nng_msg_free(smsg);
smsg = NULL;
work->msg = NULL;
free_pub_packet(work->pub_packet);
work->pub_packet = NULL;
cvector_free(work->pipe_ct->msg_infos);
work->pipe_ct->msg_infos = NULL;
init_pipe_content(work->pipe_ct);
if (conn_param_get_will_flag(work->cparam) &&
(msg = nano_pubmsg_composer(&msg,
conn_param_get_will_retain(work->cparam),
conn_param_get_will_qos(work->cparam),
(mqtt_string *) conn_param_get_will_msg(
work->cparam),
(mqtt_string *) conn_param_get_will_topic(
work->cparam),
conn_param_get_protover(work->cparam),
nng_clock())) != NULL) {
work->msg = msg;
work->flag = CMD_PUBLISH;
if (conn_param_get_protover(work->cparam) == 5) {
property *will_property =
conn_param_get_will_property(
work->cparam);
nng_msg_set_cmd_type(
msg, CMD_PUBLISH_V5);
handle_pub(work, work->pipe_ct,
MQTT_PROTOCOL_VERSION_v5, false);
work->pub_packet->var_header.publish
.properties = property_pub_by_will(
will_property);
work->pub_packet->var_header.publish
.prop_len = get_properties_len(
work->pub_packet->var_header
.publish.properties);
} else {
nng_msg_set_cmd_type(msg, CMD_PUBLISH);
handle_pub(work, work->pipe_ct,
MQTT_PROTOCOL_VERSION_v311, false);
}
work->state = WAIT;
nng_aio_finish(work->aio, 0);
} else {
conn_param_free(work->cparam);
if (work->msg != NULL)
nng_msg_free(work->msg);
work->msg = NULL;
work->state = RECV;
if (work->proto == PROTO_MQTT_BROKER) {
nng_ctx_recv(work->ctx, work->aio);
} else {
nng_ctx_recv(work->extra_ctx, work->aio);
}
}
}
conn_param_free(work->cparam);
break;
case CLOSE:
log_debug(" CLOSE ^^^^ ctx%d ^^^^", work->ctx.id);
smsg = nano_dismsg_composer(work->code, NULL, NULL, NULL);
nng_msg_free(work->msg);
work->msg = smsg;
nng_aio_set_prov_data(work->aio, &work->pid.id);
nng_aio_set_msg(work->aio, work->msg);
nng_ctx_send(work->ctx, work->aio); 
work->code = SUCCESS;
work->state = RECV;
nng_ctx_recv(work->ctx, work->aio);
break;
default:
nng_fatal("bad state!", NNG_ESTATE);
break;
}
}

static int ntlm_decode_field(struct wire_field_hdr *hdr,
struct ntlm_buffer *buffer,
size_t payload_offs,
struct ntlm_buffer *field)
{
struct ntlm_buffer b = { NULL, 0 };
uint32_t offs;
uint16_t len;
len = le16toh(hdr->len);
if (len == 0) goto done;
offs = le32toh(hdr->offset);
if ((offs < payload_offs) ||
(offs > buffer->length) ||
(offs + len > buffer->length)) {
return ERR_DECODE;
}
b.data = malloc(len);
if (!b.data) return ENOMEM;
b.length = len;
memcpy(b.data, &buffer->data[offs], b.length);
done:
*field = b;
return 0;
}

static int llcp_sock_bind(struct socket *sock, struct sockaddr *addr, int alen)
{
struct sock *sk = sock->sk;
struct nfc_llcp_sock *llcp_sock = nfc_llcp_sock(sk);
struct nfc_llcp_local *local;
struct nfc_dev *dev;
struct sockaddr_nfc_llcp llcp_addr;
int len, ret = 0;
if (!addr || alen < offsetofend(struct sockaddr, sa_family) ||
addr->sa_family != AF_NFC)
return -EINVAL;
pr_debug("sk %p addr %p family %d\n", sk, addr, addr->sa_family);
memset(&llcp_addr, 0, sizeof(llcp_addr));
len = min_t(unsigned int, sizeof(llcp_addr), alen);
memcpy(&llcp_addr, addr, len);
if (llcp_addr.dsap != 0)
return -EINVAL;
lock_sock(sk);
if (sk->sk_state != LLCP_CLOSED) {
ret = -EBADFD;
goto error;
}
dev = nfc_get_device(llcp_addr.dev_idx);
if (dev == NULL) {
ret = -ENODEV;
goto error;
}
local = nfc_llcp_find_local(dev);
if (local == NULL) {
ret = -ENODEV;
goto put_dev;
}
llcp_sock->dev = dev;
llcp_sock->local = nfc_llcp_local_get(local);
llcp_sock->nfc_protocol = llcp_addr.nfc_protocol;
llcp_sock->service_name_len = min_t(unsigned int,
llcp_addr.service_name_len,
NFC_LLCP_MAX_SERVICE_NAME);
llcp_sock->service_name = kmemdup(llcp_addr.service_name,
llcp_sock->service_name_len,
GFP_KERNEL);
if (!llcp_sock->service_name) {
nfc_llcp_local_put(llcp_sock->local);
llcp_sock->local = NULL;
ret = -ENOMEM;
goto put_dev;
}
llcp_sock->ssap = nfc_llcp_get_sdp_ssap(local, llcp_sock);
if (llcp_sock->ssap == LLCP_SAP_MAX) {
nfc_llcp_local_put(llcp_sock->local);
llcp_sock->local = NULL;
kfree(llcp_sock->service_name);
llcp_sock->service_name = NULL;
ret = -EADDRINUSE;
goto put_dev;
}
llcp_sock->reserved_ssap = llcp_sock->ssap;
nfc_llcp_sock_link(&local->sockets, sk);
pr_debug("Socket bound to SAP %d\n", llcp_sock->ssap);
sk->sk_state = LLCP_BOUND;
put_dev:
nfc_put_device(dev);
error:
release_sock(sk);
return ret;
}

static BOOL autodetect_recv_bandwidth_measure_results(rdpRdp* rdp, wStream* s,
AUTODETECT_RSP_PDU* autodetectRspPdu)
{
BOOL success = TRUE;
if (autodetectRspPdu->headerLength != 0x0E)
return FALSE;
WLog_VRB(AUTODETECT_TAG, "received Bandwidth Measure Results PDU");
Stream_Read_UINT32(s, rdp->autodetect->bandwidthMeasureTimeDelta); 
Stream_Read_UINT32(s, rdp->autodetect->bandwidthMeasureByteCount); 
if (rdp->autodetect->bandwidthMeasureTimeDelta > 0)
rdp->autodetect->netCharBandwidth = rdp->autodetect->bandwidthMeasureByteCount * 8 /
rdp->autodetect->bandwidthMeasureTimeDelta;
else
rdp->autodetect->netCharBandwidth = 0;
IFCALLRET(rdp->autodetect->BandwidthMeasureResults, success, rdp->context,
autodetectRspPdu->sequenceNumber);
return success;
}

