if (new_vts_array == NULL)
{
new_vts_array = curbuf->b_p_vts_array;
new_ts_str = NULL;
}
else
new_ts_str = vim_strnsave(new_ts_str, eap->arg - new_ts_str);
#else
new_ts = getdigits(&(eap->arg));
if (new_ts < 0)
{
emsg(_(e_positive));
return;
}
if (new_ts == 0)
new_ts = curbuf->b_p_ts;
#endif
for (lnum = eap->line1; !got_int && lnum <= eap->line2; ++lnum)
{
ptr = ml_get(lnum);
col = 0;
vcol = 0;
did_undo = FALSE;
for (;;)
{
if (VIM_ISWHITE(ptr[col]))
{
if (!got_tab && num_spaces == 0)
{
start_vcol = vcol;
start_col = col;
}
if (ptr[col] == ' ')
num_spaces++;
else
got_tab = TRUE;
}
else
{
if (got_tab || (eap->forceit && num_spaces > 1))
{
len = num_spaces = vcol - start_vcol;
num_tabs = 0;
if (!curbuf->b_p_et)
{
#ifdef FEAT_VARTABS
int t, s;
tabstop_fromto(start_vcol, vcol,
curbuf->b_p_ts, new_vts_array, &t, &s);
num_tabs = t;
num_spaces = s;
#else
temp = new_ts - (start_vcol % new_ts);
if (num_spaces >= temp)
{
num_spaces -= temp;
num_tabs++;
}
num_tabs += num_spaces / new_ts;
num_spaces -= (num_spaces / new_ts) * new_ts;
#endif
}
if (curbuf->b_p_et || got_tab ||
(num_spaces + num_tabs < len))
{
if (did_undo == FALSE)
{
did_undo = TRUE;
if (u_save((linenr_T)(lnum - 1),
(linenr_T)(lnum + 1)) == FAIL)
{
new_line = NULL;break;
}
}
len = num_spaces + num_tabs;
old_len = (long)STRLEN(ptr);
new_line = alloc(old_len - col + start_col + len + 1);
if (new_line == NULL)
break;
if (start_col > 0)
mch_memmove(new_line, ptr, (size_t)start_col);
mch_memmove(new_line + start_col + len,
ptr + col, (size_t)(old_len - col + 1));
ptr = new_line + start_col;
for (col = 0; col < len; col++)
ptr[col] = (col < num_tabs) ? '\t' : ' ';
if (ml_replace(lnum, new_line, FALSE) == OK)
new_line = curbuf->b_ml.ml_line_ptr;
if (first_line == 0)
first_line = lnum;
last_line = lnum;
ptr = new_line;
col = start_col + len;
}
}
got_tab = FALSE;
num_spaces = 0;
}
if (ptr[col] == NUL)
break;
vcol += chartabsize(ptr + col, (colnr_T)vcol);
if (has_mbyte)
col += (*mb_ptr2len)(ptr + col);
else
++col;
}
if (new_line == NULL)        break;
line_breakcheck();
}
if (got_int)
emsg(_(e_interr));
#ifdef FEAT_VARTABS
if (tabstop_count(curbuf->b_p_vts_array) == 0
&& tabstop_count(new_vts_array) == 1
&& curbuf->b_p_ts == tabstop_first(new_vts_array))
;     else if (tabstop_count(curbuf->b_p_vts_array) > 0
&& tabstop_eq(curbuf->b_p_vts_array, new_vts_array))
;     else
redraw_curbuf_later(NOT_VALID);
#else
if (curbuf->b_p_ts != new_ts)
redraw_curbuf_later(NOT_VALID);
#endif
if (first_line != 0)
changed_lines(first_line, 0, last_line + 1, 0L);
curwin->w_p_list = save_list;
#ifdef FEAT_VARTABS
if (new_ts_str != NULL)    {
int *old_vts_ary = curbuf->b_p_vts_array;
if (tabstop_count(old_vts_ary) > 0 || tabstop_count(new_vts_array) > 1)
{
set_string_option_direct((char_u *)"vts", -1, new_ts_str,
OPT_FREE|OPT_LOCAL, 0);
curbuf->b_p_vts_array = new_vts_array;
vim_free(old_vts_ary);
}
else
{
curbuf->b_p_ts = tabstop_first(new_vts_array);
vim_free(new_vts_array);
}
vim_free(new_ts_str);
}
#else
curbuf->b_p_ts = new_ts;
#endif
coladvance(curwin->w_curswant);
u_clearline();
}

size_t Archive::ReadHeader50()
{
RawRead Raw(this);
bool Decrypt=Encrypted && CurBlockPos>(int64)SFXSize+SIZEOF_MARKHEAD5;
if (Decrypt)
{
#if defined(RAR_NOCRYPT)
return 0;
#else
byte HeadersInitV[SIZE_INITV];
if (Read(HeadersInitV,SIZE_INITV)!=SIZE_INITV)
{
UnexpEndArcMsg();
return 0;
}
while (true)     {
RequestArcPassword();
byte PswCheck[SIZE_PSWCHECK];
HeadersCrypt.SetCryptKeys(false,CRYPT_RAR50,&Cmd->Password,CryptHead.Salt,HeadersInitV,CryptHead.Lg2Count,NULL,PswCheck);
if (CryptHead.UsePswCheck && memcmp(PswCheck,CryptHead.PswCheck,SIZE_PSWCHECK)!=0)
{
uiMsg(UIWAIT_BADPSW,FileName);
Cmd->Password.Clean();
continue;
}
break;
}
Raw.SetCrypt(&HeadersCrypt);
#endif
}
const size_t FirstReadSize=7;   if (Raw.Read(FirstReadSize)<FirstReadSize)
{
UnexpEndArcMsg();
return 0;
}
ShortBlock.Reset();
ShortBlock.HeadCRC=Raw.Get4();
uint SizeBytes=Raw.GetVSize(4);
uint64 BlockSize=Raw.GetV();
if (BlockSize==0 || SizeBytes==0)
{
BrokenHeaderMsg();
return 0;
}
int SizeToRead=int(BlockSize);
SizeToRead-=FirstReadSize-SizeBytes-4;   uint HeaderSize=4+SizeBytes+(uint)BlockSize;
if (SizeToRead<0 || HeaderSize<SIZEOF_SHORTBLOCKHEAD5)
{
BrokenHeaderMsg();
return 0;
}
Raw.Read(SizeToRead);
if (Raw.Size()<HeaderSize)
{
UnexpEndArcMsg();
return 0;
}
uint HeaderCRC=Raw.GetCRC50();
ShortBlock.HeaderType=(HEADER_TYPE)Raw.GetV();
ShortBlock.Flags=(uint)Raw.GetV();
ShortBlock.SkipIfUnknown=(ShortBlock.Flags & HFL_SKIPIFUNKNOWN)!=0;
ShortBlock.HeadSize=HeaderSize;
CurHeaderType=ShortBlock.HeaderType;
bool BadCRC=(ShortBlock.HeadCRC!=HeaderCRC);
if (BadCRC)
{
BrokenHeaderMsg(); 
BrokenHeader=true;
ErrHandler.SetErrorCode(RARX_CRC);
if (Decrypt)
{
uiMsg(UIERROR_CHECKSUMENC,FileName,FileName);
FailedHeaderDecryption=true;
return 0;
}
}
uint64 ExtraSize=0;
if ((ShortBlock.Flags & HFL_EXTRA)!=0)
{
ExtraSize=Raw.GetV();
if (ExtraSize>=ShortBlock.HeadSize)
{
BrokenHeaderMsg();
return 0;
}
}
uint64 DataSize=0;
if ((ShortBlock.Flags & HFL_DATA)!=0)
DataSize=Raw.GetV();
NextBlockPos=CurBlockPos+FullHeaderSize(ShortBlock.HeadSize);
NextBlockPos=SafeAdd(NextBlockPos,DataSize,0);
switch(ShortBlock.HeaderType)
{
case HEAD_CRYPT:
{
*(BaseBlock *)&CryptHead=ShortBlock;
uint CryptVersion=(uint)Raw.GetV();
if (CryptVersion>CRYPT_VERSION)
{
UnkEncVerMsg(FileName);
return 0;
}
uint EncFlags=(uint)Raw.GetV();
CryptHead.UsePswCheck=(EncFlags & CHFL_CRYPT_PSWCHECK)!=0;
CryptHead.Lg2Count=Raw.Get1();
if (CryptHead.Lg2Count>CRYPT5_KDF_LG2_COUNT_MAX)
{
UnkEncVerMsg(FileName);
return 0;
}
Raw.GetB(CryptHead.Salt,SIZE_SALT50);
if (CryptHead.UsePswCheck)
{
Raw.GetB(CryptHead.PswCheck,SIZE_PSWCHECK);
byte csum[SIZE_PSWCHECK_CSUM];
Raw.GetB(csum,SIZE_PSWCHECK_CSUM);
sha256_context ctx;
sha256_init(&ctx);
sha256_process(&ctx, CryptHead.PswCheck, SIZE_PSWCHECK);
byte Digest[SHA256_DIGEST_SIZE];
sha256_done(&ctx, Digest);
CryptHead.UsePswCheck=memcmp(csum,Digest,SIZE_PSWCHECK_CSUM)==0;
}
Encrypted=true;
}
break;
case HEAD_MAIN:
{
MainHead.Reset();
*(BaseBlock *)&MainHead=ShortBlock;
uint ArcFlags=(uint)Raw.GetV();
Volume=(ArcFlags & MHFL_VOLUME)!=0;
Solid=(ArcFlags & MHFL_SOLID)!=0;
Locked=(ArcFlags & MHFL_LOCK)!=0;
Protected=(ArcFlags & MHFL_PROTECT)!=0;
Signed=false;
NewNumbering=true;
if ((ArcFlags & MHFL_VOLNUMBER)!=0)
VolNumber=(uint)Raw.GetV();
else
VolNumber=0;
FirstVolume=Volume && VolNumber==0;
if (ExtraSize!=0)
ProcessExtra50(&Raw,(size_t)ExtraSize,&MainHead);
#ifdef USE_QOPEN
if (MainHead.Locator && MainHead.QOpenOffset>0 && Cmd->QOpenMode!=QOPEN_NONE)
{
int64 SaveCurBlockPos=CurBlockPos,SaveNextBlockPos=NextBlockPos;
HEADER_TYPE SaveCurHeaderType=CurHeaderType;
QOpen.Init(this,false);
QOpen.Load(MainHead.QOpenOffset);
CurBlockPos=SaveCurBlockPos;
NextBlockPos=SaveNextBlockPos;
CurHeaderType=SaveCurHeaderType;
}
#endif
}
break;
case HEAD_FILE:
case HEAD_SERVICE:
{
FileHeader *hd=ShortBlock.HeaderType==HEAD_FILE ? &FileHead:&SubHead;
hd->Reset();
*(BaseBlock *)hd=ShortBlock;
bool FileBlock=ShortBlock.HeaderType==HEAD_FILE;
hd->LargeFile=true;
hd->PackSize=DataSize;
hd->FileFlags=(uint)Raw.GetV();
hd->UnpSize=Raw.GetV();
hd->UnknownUnpSize=(hd->FileFlags & FHFL_UNPUNKNOWN)!=0;
if (hd->UnknownUnpSize)
hd->UnpSize=INT64NDF;
hd->MaxSize=Max(hd->PackSize,hd->UnpSize);
hd->FileAttr=(uint)Raw.GetV();
if ((hd->FileFlags & FHFL_UTIME)!=0)
hd->mtime.SetUnix((time_t)Raw.Get4());
hd->FileHash.Type=HASH_NONE;
if ((hd->FileFlags & FHFL_CRC32)!=0)
{
hd->FileHash.Type=HASH_CRC32;
hd->FileHash.CRC32=Raw.Get4();
}
hd->RedirType=FSREDIR_NONE;
uint CompInfo=(uint)Raw.GetV();
hd->Method=(CompInfo>>7) & 7;
hd->UnpVer=(CompInfo & 0x3f) + 50;
hd->HostOS=(byte)Raw.GetV();
size_t NameSize=(size_t)Raw.GetV();
hd->Inherited=(ShortBlock.Flags & HFL_INHERITED)!=0;
hd->HSType=HSYS_UNKNOWN;
if (hd->HostOS==HOST5_UNIX)
hd->HSType=HSYS_UNIX;
else
if (hd->HostOS==HOST5_WINDOWS)
hd->HSType=HSYS_WINDOWS;
hd->SplitBefore=(hd->Flags & HFL_SPLITBEFORE)!=0;
hd->SplitAfter=(hd->Flags & HFL_SPLITAFTER)!=0;
hd->SubBlock=(hd->Flags & HFL_CHILD)!=0;
hd->Solid=FileBlock && (CompInfo & FCI_SOLID)!=0;
hd->Dir=(hd->FileFlags & FHFL_DIRECTORY)!=0;
hd->WinSize=hd->Dir ? 0:size_t(0x20000)<<((CompInfo>>10)&0xf);
hd->CryptMethod=hd->Encrypted ? CRYPT_RAR50:CRYPT_NONE;
char FileName[NM*4];
size_t ReadNameSize=Min(NameSize,ASIZE(FileName)-1);
Raw.GetB((byte *)FileName,ReadNameSize);
FileName[ReadNameSize]=0;
UtfToWide(FileName,hd->FileName,ASIZE(hd->FileName));
if (ExtraSize!=0)
ProcessExtra50(&Raw,(size_t)ExtraSize,hd);
if (FileBlock)
{
#ifndef SFX_MODULE
ConvertNameCase(hd->FileName);
#endif
ConvertFileHeader(hd);
}
if (!FileBlock && hd->CmpName(SUBHEAD_TYPE_CMT))
MainComment=true;
#if 0
if (!FileBlock && hd->CmpName(SUBHEAD_TYPE_RR) && hd->SubData.Size()>0)
{
RecoveryPercent=hd->SubData[0];
RSBlockHeader Header;
GetRRInfo(this,&Header);
RecoverySize=Header.RecSectionSize*Header.RecCount;
}
#endif
if (BadCRC)           uiMsg(UIERROR_FHEADERBROKEN,Archive::FileName,hd->FileName);
}
break;
case HEAD_ENDARC:
{
*(BaseBlock *)&EndArcHead=ShortBlock;
uint ArcFlags=(uint)Raw.GetV();
EndArcHead.NextVolume=(ArcFlags & EHFL_NEXTVOLUME)!=0;
EndArcHead.StoreVolNumber=false;
EndArcHead.DataCRC=false;
EndArcHead.RevSpace=false;
}
break;
}
return Raw.Size();
}

struct qmp *qmp_get(struct device *dev)
{
struct platform_device *pdev;
struct device_node *np;
struct qmp *qmp;
if (!dev || !dev->of_node)
return ERR_PTR(-EINVAL);
np = of_parse_phandle(dev->of_node, "qcom,qmp", 0);
if (!np)
return ERR_PTR(-ENODEV);
pdev = of_find_device_by_node(np);
of_node_put(np);
if (!pdev)
return ERR_PTR(-EINVAL);
qmp = platform_get_drvdata(pdev);
return qmp ? qmp : ERR_PTR(-EPROBE_DEFER);
}

static Jsi_RC jsi_ArrayShiftCmd(Jsi_Interp *interp, Jsi_Value *args, Jsi_Value *_this,Jsi_Value **ret, Jsi_Func *funcPtr) {
if (_this->vt != JSI_VT_OBJECT || !Jsi_ObjIsArray(interp, _this->d.obj))
return Jsi_LogError("expected array object");
Jsi_Value *v;
Jsi_Obj *obj = _this->d.obj;
Jsi_ObjListifyArray(interp, obj);
uint n = Jsi_ObjGetLength(interp, obj);
assert(n <= obj->arrCnt);
if (n<=0) {
Jsi_ValueMakeUndef(interp, ret);
} else {
n--;
v = obj->arr[0];
memmove(obj->arr, obj->arr+1, n*sizeof(Jsi_Value*));
obj->arr[n] = NULL;
Jsi_ValueDup2(interp, ret, v);
Jsi_DecrRefCount(interp, v);
Jsi_ObjSetLength(interp, obj, n);
}
return JSI_OK;
}

static bool parseOperands(char* str, ArmOp *op) {
char *t = strdup (str);
int operand = 0;
char *token = t;
char *x;
int imm_count = 0;
int mem_opt = 0;
if (!token) {
return false;
}
while (token) {
char *next = strchr (token, ',');
if (next) {
*next++ = 0;
}
while (token[0] == ' ') {
token++;
}
if (operand >= MAX_OPERANDS) {
eprintf ("Too many operands\n");
return false;
}
op->operands[operand].type = ARM_NOTYPE;
op->operands[operand].reg_type = ARM_UNDEFINED;
op->operands[operand].shift = ARM_NO_SHIFT;
while (token[0] == ' ' || token[0] == '[' || token[0] == ']') {
token ++;
}
if (!strncmp (token, "lsl", 3)) {
op->operands[operand].shift = ARM_LSL;
} else if (!strncmp (token, "lsr", 3)) {
op->operands[operand].shift = ARM_LSR;
} else if (!strncmp (token, "asr", 3)) {
op->operands[operand].shift = ARM_ASR;
}
if (op->operands[operand].shift != ARM_NO_SHIFT) {
op->operands_count ++;
op->operands[operand].shift_amount = r_num_math (NULL, token + 4);
if (op->operands[operand].shift_amount > 63) {
return false;
}
operand ++;
token = next;
continue;
}
switch (token[0]) {
case 'x':
x = strchr (token, ',');
if (x) {
x[0] = '\0';
}
op->operands_count ++;
op->operands[operand].type = ARM_GPR;
op->operands[operand].reg_type = ARM_REG64;
op->operands[operand].reg = r_num_math (NULL, token + 1);
if (op->operands[operand].reg > 31) {
return false;
}
break;
case 'w':
op->operands_count ++;
op->operands[operand].type = ARM_GPR;
op->operands[operand].reg_type = ARM_REG32;
op->operands[operand].reg = r_num_math (NULL, token + 1);
if (op->operands[operand].reg > 31) {
return false;
}
break;
case 'v':
op->operands_count ++;
op->operands[operand].type = ARM_FP;
op->operands[operand].reg = r_num_math (NULL, token + 1);
break;
case 's':
case 'S':
if (token[1] == 'P' || token [1] == 'p') {
int i;
for (i = 0; msr_const[i].name; i++) {
if (!r_str_ncasecmp (token, msr_const[i].name, strlen (msr_const[i].name))) {
op->operands[operand].sp_val = msr_const[i].val;
break;
}
}
op->operands_count ++;
op->operands[operand].type = ARM_GPR;
op->operands[operand].reg_type = ARM_SP | ARM_REG64;
op->operands[operand].reg = 31;
break;
}
mem_opt = get_mem_option (token);
if (mem_opt != -1) {
op->operands_count ++;
op->operands[operand].type = ARM_MEM_OPT;
op->operands[operand].mem_option = mem_opt;
}
break;
case 'L':
case 'l':
case 'I':
case 'i':
case 'N':
case 'n':
case 'O':
case 'o':
case 'p':
case 'P':
mem_opt = get_mem_option (token);
if (mem_opt != -1) {
op->operands_count ++;
op->operands[operand].type = ARM_MEM_OPT;
op->operands[operand].mem_option = mem_opt;
}
break;
case '-':
op->operands[operand].sign = -1;
default:
op->operands_count ++;
op->operands[operand].type = ARM_CONSTANT;
op->operands[operand].immediate = r_num_math (NULL, token);
imm_count++;
break;
}
token = next;
operand ++;
if (operand > MAX_OPERANDS) {
free (t);
return false;
}
}
free (t);
return true;
}

int mlx4_register_mac(struct mlx4_dev *dev, u8 port, u64 mac, int *index)
{
struct mlx4_mac_table *table = &mlx4_priv(dev)->port[port].mac_table;
int i, err = 0;
int free = -1;
mlx4_dbg(dev, "Registering MAC: 0x%llx\n", (unsigned long long) mac);
mutex_lock(&table->mutex);
for (i = 0; i < MLX4_MAX_MAC_NUM - 1; i++) {
if (free < 0 && !table->refs[i]) {
free = i;
continue;
}
if (mac == (MLX4_MAC_MASK & be64_to_cpu(table->entries[i]))) {
*index = i;
++table->refs[i];
goto out;
}
}
mlx4_dbg(dev, "Free MAC index is %d\n", free);
if (table->total == table->max) {
err = -ENOSPC;
goto out;
}
table->refs[free] = 1;
table->entries[free] = cpu_to_be64(mac | MLX4_MAC_VALID);
err = mlx4_set_port_mac_table(dev, port, table->entries);
if (unlikely(err)) {
mlx4_err(dev, "Failed adding MAC: 0x%llx\n", (unsigned long long) mac);
table->refs[free] = 0;
table->entries[free] = 0;
goto out;
}
*index = free;
++table->total;
out:
mutex_unlock(&table->mutex);
return err;
}

static inline char* parse_to_param(char *buffer, char *end,
struct to_body *to_b,
int *returned_status,
int multi)
{
struct to_param *param;
int status;
int saved_status;
char  *tmp;
param=0;
status=E_PARA_VALUE;
saved_status=E_PARA_VALUE;
for( tmp=buffer; tmp<end; tmp++)
{
switch(*tmp)
{
case ' ':
case '\t':
switch (status)
{
case TAG3:
param->type=TAG_PARAM;
case PARA_NAME:
case TAG1:
case TAG2:
param->name.len = tmp-param->name.s;
status = S_EQUAL;
break;
case PARA_VALUE_TOKEN:
param->value.len = tmp-param->value.s;
status = E_PARA_VALUE;
add_param( param , to_b );
break;
case F_CRLF:
case F_LF:
case F_CR:
status=saved_status;
break;
}
break;
case '\n':
switch (status)
{
case S_PARA_NAME:
case S_EQUAL:
case S_PARA_VALUE:
case E_PARA_VALUE:
saved_status=status;
status=F_LF;
break;
case TAG3:
param->type=TAG_PARAM;
case PARA_NAME:
case TAG1:
case TAG2:
param->name.len = tmp-param->name.s;
saved_status = S_EQUAL;
status = F_LF;
break;
case PARA_VALUE_TOKEN:
param->value.len = tmp-param->value.s;
saved_status = E_PARA_VALUE;
status = F_LF;
add_param( param , to_b );
break;
case F_CR:
status=F_CRLF;
break;
case F_CRLF:
case F_LF:
status=saved_status;
goto endofheader;
default:
goto parse_error;
}
break;
case '\r':
switch (status)
{
case S_PARA_NAME:
case S_EQUAL:
case S_PARA_VALUE:
case E_PARA_VALUE:
saved_status=status;
status=F_CR;
break;
case TAG3:
param->type=TAG_PARAM;
case PARA_NAME:
case TAG1:
case TAG2:
param->name.len = tmp-param->name.s;
saved_status = S_EQUAL;
status = F_CR;
break;
case PARA_VALUE_TOKEN:
param->value.len = tmp-param->value.s;
saved_status = E_PARA_VALUE;
status = F_CR;
add_param( param , to_b );
break;
case F_CRLF:
case F_CR:
case F_LF:
status=saved_status;
goto endofheader;
default:
goto parse_error;
}
break;
case  0:
case ',':
switch (status)
{
case PARA_VALUE_QUOTED:
break;
case PARA_NAME:
param->name.len = tmp-param->name.s;
case S_EQUAL:
case S_PARA_VALUE:
if (param->type==TAG_PARAM)
goto parse_error;
param->value.s = tmp;
case PARA_VALUE_TOKEN:
status = E_PARA_VALUE;
param->value.len = tmp-param->value.s;
add_param( param , to_b );
case E_PARA_VALUE:
saved_status = status;
if ( !multi && *tmp==',')
goto parse_error;
goto endofheader;
break;
default:
goto parse_error;
}
break;
case '\\':
switch (status)
{
case PARA_VALUE_QUOTED:
switch (*(tmp+1))
{
case '\r':
case '\n':
break;
default:
tmp++;
break;
}
break;
default:
goto parse_error;
}
break;
case '"':
switch (status)
{
case S_PARA_VALUE:
param->value.s = tmp+1;
status = PARA_VALUE_QUOTED;
break;
case PARA_VALUE_QUOTED:
param->value.len=tmp-param->value.s ;
add_param( param , to_b );
status = E_PARA_VALUE;
break;
case F_CRLF:
case F_LF:
case F_CR:
goto endofheader;
default:
goto parse_error;
}
break;
case ';' :
switch (status)
{
case PARA_VALUE_QUOTED:
break;
case PARA_NAME:
param->name.len = tmp-param->name.s;
case S_EQUAL:
case S_PARA_VALUE:
if (param->type==TAG_PARAM)
goto parse_error;
param->value.s = tmp;
case PARA_VALUE_TOKEN:
param->value.len=tmp-param->value.s;
add_param(param,to_b);
case E_PARA_VALUE:
param = (struct to_param*)
pkg_malloc(sizeof(struct to_param));
if (!param){
LM_ERR("out of pkg memory\n" );
goto error;
}
memset(param,0,sizeof(struct to_param));
param->type=GENERAL_PARAM;
status = S_PARA_NAME;
break;
case F_CRLF:
case F_LF:
case F_CR:
goto endofheader;
default:
goto parse_error;
}
break;
case 'T':
case 't' :
switch (status)
{
case PARA_VALUE_QUOTED:
case PARA_VALUE_TOKEN:
case PARA_NAME:
break;
case S_PARA_NAME:
param->name.s = tmp;
status = TAG1;
break;
case S_PARA_VALUE:
param->value.s = tmp;
status = PARA_VALUE_TOKEN;
break;
case TAG1:
case TAG2:
case TAG3:
status = PARA_NAME;
break;
case F_CRLF:
case F_LF:
case F_CR:
goto endofheader;
default:
goto parse_error;
}
break;
case 'A':
case 'a' :
switch (status)
{
case PARA_VALUE_QUOTED:
case PARA_VALUE_TOKEN:
case PARA_NAME:
break;
case S_PARA_NAME:
param->name.s = tmp;
status = PARA_NAME;
break;
case S_PARA_VALUE:
param->value.s = tmp;
status = PARA_VALUE_TOKEN;
break;
case TAG1:
status = TAG2;
break;
case TAG2:
case TAG3:
status = PARA_NAME;
break;
case F_CRLF:
case F_LF:
case F_CR:
goto endofheader;
default:
goto parse_error;
}
break;
case 'G':
case 'g' :
switch (status)
{
case PARA_VALUE_QUOTED:
case PARA_VALUE_TOKEN:
case PARA_NAME:
break;
case S_PARA_NAME:
param->name.s = tmp;
status = PARA_NAME;
break;
case S_PARA_VALUE:
param->value.s = tmp;
status = PARA_VALUE_TOKEN;
break;
case TAG1:
case TAG3:
status = PARA_NAME;
break;
case TAG2:
status = TAG3;
break;
case F_CRLF:
case F_LF:
case F_CR:
goto endofheader;
default:
goto parse_error;
}
break;
case '=':
switch (status)
{
case PARA_VALUE_QUOTED:
break;
case TAG3:
param->type=TAG_PARAM;
case PARA_NAME:
case TAG1:
case TAG2:
param->name.len = tmp-param->name.s;
status = S_PARA_VALUE;
break;
case S_EQUAL:
status = S_PARA_VALUE;
break;
case F_CRLF:
case F_LF:
case F_CR:
goto endofheader;
default:
goto parse_error;
}
break;
default:
switch (status)
{
case TAG1:
case TAG2:
case TAG3:
status = PARA_NAME;
break;
case PARA_VALUE_TOKEN:
case PARA_NAME:
case PARA_VALUE_QUOTED:
break;
case S_PARA_NAME:
param->name.s = tmp;
status = PARA_NAME;
break;
case S_PARA_VALUE:
param->value.s = tmp;
status = PARA_VALUE_TOKEN;
break;
case F_CRLF:
case F_LF:
case F_CR:
goto endofheader;
default:
LM_ERR("spitting out [%c] in status %d\n",*tmp,status );
goto error;
}
}
}
endofheader:
if (param) {
if (saved_status==S_EQUAL||saved_status==S_PARA_VALUE) {
saved_status = E_PARA_VALUE;
param->value.s= 0;
param->value.len=0;
if (param->type==TAG_PARAM)
goto parse_error;
add_param(param, to_b);
} else {
pkg_free(param);
}
}
*returned_status=saved_status;
return tmp;
parse_error:
LM_ERR("unexpected char [%c] in status %d: <<%.*s>> .\n",
*tmp,status, (int)(tmp-buffer), ZSW(buffer));
error:
if (param) pkg_free(param);
free_to_params(to_b);
to_b->error=PARSE_ERROR;
*returned_status = status;
return tmp;
}

