void Jp2Image::encodeJp2Header(const DataBuf& boxBuf,DataBuf& outBuf)
{
DataBuf output(boxBuf.size_ + iccProfile_.size_ + 100);         int     outlen = sizeof(Jp2BoxHeader) ;         int      inlen = sizeof(Jp2BoxHeader) ;         Jp2BoxHeader* pBox   = (Jp2BoxHeader*) boxBuf.pData_;
int32_t       length = getLong((byte*)&pBox->length, bigEndian);
int32_t       count  = sizeof (Jp2BoxHeader);
char*         p      = (char*) boxBuf.pData_;
bool          bWroteColor = false ;
while ( count < length || !bWroteColor ) {
Jp2BoxHeader* pSubBox = (Jp2BoxHeader*) (p+count) ;
Jp2BoxHeader   subBox ; memcpy(&subBox,pSubBox,sizeof(subBox));
Jp2BoxHeader   newBox =  subBox;
if ( count < length ) {
subBox.length = getLong((byte*)&subBox.length, bigEndian);
subBox.type   = getLong((byte*)&subBox.type  , bigEndian);
#ifdef EXIV2_DEBUG_MESSAGES
std::cout << "Jp2Image::encodeJp2Header subbox: "<< toAscii(subBox.type) << " length = " << subBox.length << std::endl;
#endif
count        += subBox.length;
newBox.type   = subBox.type;
} else {
subBox.length=0;
newBox.type = kJp2BoxTypeColorHeader;
count = length;
}
int32_t newlen = subBox.length;
if ( newBox.type == kJp2BoxTypeColorHeader ) {
bWroteColor = true ;
if ( ! iccProfileDefined() ) {
const char* pad   = "\x01\x00\x00\x00\x00\x00\x10\x00\x00\x05\x1cuuid";
uint32_t    psize = 15;
newlen            = sizeof(newBox) + psize ;
ul2Data((byte*)&newBox.length,psize      ,bigEndian);
ul2Data((byte*)&newBox.type  ,newBox.type,bigEndian);
::memcpy(output.pData_+outlen                     ,&newBox            ,sizeof(newBox));
::memcpy(output.pData_+outlen+sizeof(newBox)      ,pad                ,psize         );
} else {
const char* pad   = "\x02\x00\x00";
uint32_t    psize = 3;
newlen            = sizeof(newBox) + psize + iccProfile_.size_;
ul2Data((byte*)&newBox.length,newlen,bigEndian);
ul2Data((byte*)&newBox.type,newBox.type,bigEndian);
::memcpy(output.pData_+outlen                     ,&newBox            ,sizeof(newBox)  );
::memcpy(output.pData_+outlen+sizeof(newBox)      , pad               ,psize           );
::memcpy(output.pData_+outlen+sizeof(newBox)+psize,iccProfile_.pData_,iccProfile_.size_);
}
} else {
::memcpy(output.pData_+outlen,boxBuf.pData_+inlen,subBox.length);
}
outlen += newlen;
inlen  += subBox.length;
}
outBuf.alloc(outlen);
::memcpy(outBuf.pData_,output.pData_,outlen);
pBox   = (Jp2BoxHeader*) outBuf.pData_;
ul2Data((byte*)&pBox->type,kJp2BoxTypeJp2Header,bigEndian);
ul2Data((byte*)&pBox->length,outlen,bigEndian);
}

mp_err mp_2expt(mp_int *a, int b)
{
mp_err    err;
mp_zero(a);
if ((err = mp_grow(a, (b / MP_DIGIT_BIT) + 1)) != MP_OKAY) {
return err;
}
a->used = (b / MP_DIGIT_BIT) + 1;
a->dp[b / MP_DIGIT_BIT] = (mp_digit)1 << (mp_digit)(b % MP_DIGIT_BIT);
return MP_OKAY;
}

static void ok_wav_decode_ms_adpcm_data(ok_wav_decoder *decoder) {
static const int adaptation_coeff1[7] = {
256, 512, 0, 192, 240, 460, 392
};
static const int adaptation_coeff2[7] = {
0, -256, 0, 64, 0, -208, -232
};
ok_wav *wav = decoder->wav;
struct ok_wav_ms_adpcm_state *channel_states = NULL;
uint8_t *block = NULL;
uint8_t num_channels = wav->num_channels;
const bool is_le = wav->little_endian;
const uint64_t max_output_frames = (wav->num_frames + 1) & ~1u;
const uint64_t output_data_length = max_output_frames * sizeof(int16_t) * num_channels;
const size_t platform_data_length = (size_t)output_data_length;
channel_states = calloc(num_channels, sizeof(struct ok_wav_ms_adpcm_state));
if (!channel_states) {
ok_wav_error(wav, "Couldn't allocate channel_state buffer");
goto done;
}
block = malloc(decoder->block_size);
if (!block) {
ok_wav_error(wav, "Couldn't allocate block");
goto done;
}
if (platform_data_length > 0 && platform_data_length == output_data_length) {
wav->data = malloc(platform_data_length);
}
if (!wav->data) {
ok_wav_error(wav, "Couldn't allocate memory for audio");
goto done;
}
uint64_t remaining_frames = wav->num_frames;
int16_t *output = wav->data;
while (remaining_frames > 0) {
uint64_t block_frames = min(remaining_frames, decoder->frames_per_block);
int64_t frames = (int64_t)block_frames;
if (!ok_read(decoder, block, decoder->block_size)) {
goto done;
}
uint8_t *input = block;
for (int channel = 0; channel < num_channels; channel++) {
const uint8_t coeff_index = min(*input, 6);
channel_states[channel].coeff1 = adaptation_coeff1[coeff_index];
channel_states[channel].coeff2 = adaptation_coeff2[coeff_index];
input++;
}
for (int channel = 0; channel < num_channels; channel++) {
channel_states[channel].delta = (is_le ? readLE16(input) : readBE16(input));
input += 2;
}
for (int channel = 0; channel < num_channels; channel++) {
channel_states[channel].sample1 = (int16_t)(is_le ? readLE16(input) : readBE16(input));
input += 2;
}
for (int channel = 0; channel < num_channels; channel++) {
channel_states[channel].sample2 = (int16_t)(is_le ? readLE16(input) : readBE16(input));
input += 2;
}
for (int channel = 0; channel < num_channels; channel++) {
*output++ = channel_states[channel].sample2;
}
for (int channel = 0; channel < num_channels; channel++) {
*output++ = channel_states[channel].sample1;
}
frames -= 2;
int64_t samples = frames * num_channels;
if (num_channels <= 2) {
struct ok_wav_ms_adpcm_state *channel_state1 = channel_states;
struct ok_wav_ms_adpcm_state *channel_state2 = channel_states + (num_channels - 1);
while (samples > 0) {
*output++ = ok_wav_decode_ms_adpcm_nibble(channel_state1, (*input) >> 4);
*output++ = ok_wav_decode_ms_adpcm_nibble(channel_state2, (*input) & 0x0f);
input++;
samples -= 2;
}
} else {
int channel = 0;
while (samples > 0) {
*output++ = ok_wav_decode_ms_adpcm_nibble(channel_states + channel, (*input) >> 4);
channel = (channel + 1) % num_channels;
*output++ = ok_wav_decode_ms_adpcm_nibble(channel_states + channel,
(*input) & 0x0f);
channel = (channel + 1) % num_channels;
input++;
samples -= 2;
}
}
remaining_frames -= block_frames;
}
const int n = 1;
const bool system_is_little_endian = *(const char *)&n == 1;
wav->little_endian = system_is_little_endian;
wav->bit_depth = 16;
done:
free(block);
free(channel_states);
}

static ssize_t k90_show_macro_mode(struct device *dev,
struct device_attribute *attr, char *buf)
{
int ret;
struct usb_interface *usbif = to_usb_interface(dev->parent);
struct usb_device *usbdev = interface_to_usbdev(usbif);
const char *macro_mode;
char data[8];
ret = usb_control_msg(usbdev, usb_rcvctrlpipe(usbdev, 0),
K90_REQUEST_GET_MODE,
USB_DIR_IN | USB_TYPE_VENDOR |
USB_RECIP_DEVICE, 0, 0, data, 2,
USB_CTRL_SET_TIMEOUT);
if (ret < 0) {
dev_warn(dev, "Failed to get K90 initial mode (error %d).\n",
ret);
return -EIO;
}
switch (data[0]) {
case K90_MACRO_MODE_HW:
macro_mode = "HW";
break;
case K90_MACRO_MODE_SW:
macro_mode = "SW";
break;
default:
dev_warn(dev, "K90 in unknown mode: %02hhx.\n",
data[0]);
return -EIO;
}
return snprintf(buf, PAGE_SIZE, "%s\n", macro_mode);
}

int
_gdGetColors (gdIOCtx * in, gdImagePtr im, int gd2xFlag)
{
int i;
if (gd2xFlag) {
int trueColorFlag;
if (!gdGetByte (&trueColorFlag, in)) {
goto fail1;
}
if (trueColorFlag != im->trueColor) {
goto fail1;
}
if (!im->trueColor) {
if (!gdGetWord (&im->colorsTotal, in)) {
goto fail1;
}
if (im->colorsTotal > gdMaxColors) {
goto fail1;
}
}
if (!gdGetInt (&im->transparent, in)) {
goto fail1;
}
} else {
if (!gdGetByte (&im->colorsTotal, in)) {
goto fail1;
}
if (!gdGetWord (&im->transparent, in)) {
goto fail1;
}
if (im->transparent == 257) {
im->transparent = (-1);
}
}
GD2_DBG (printf
("Palette had %d colours (T=%d)\n", im->colorsTotal,
im->transparent));
if (im->trueColor) {
return TRUE;
}
for (i = 0; (i < gdMaxColors); i++) {
if (!gdGetByte (&im->red[i], in)) {
goto fail1;
}
if (!gdGetByte (&im->green[i], in)) {
goto fail1;
}
if (!gdGetByte (&im->blue[i], in)) {
goto fail1;
}
if (gd2xFlag) {
if (!gdGetByte (&im->alpha[i], in)) {
goto fail1;
}
}
}
for (i = 0; (i < im->colorsTotal); i++) {
im->open[i] = 0;
};
return TRUE;
fail1:
return FALSE;
}

static struct dentry *ecryptfs_mount(struct file_system_type *fs_type, int flags,
const char *dev_name, void *raw_data)
{
struct super_block *s;
struct ecryptfs_sb_info *sbi;
struct ecryptfs_dentry_info *root_info;
const char *err = "Getting sb failed";
struct inode *inode;
struct path path;
uid_t check_ruid;
int rc;
sbi = kmem_cache_zalloc(ecryptfs_sb_info_cache, GFP_KERNEL);
if (!sbi) {
rc = -ENOMEM;
goto out;
}
rc = ecryptfs_parse_options(sbi, raw_data, &check_ruid);
if (rc) {
err = "Error parsing options";
goto out;
}
s = sget(fs_type, NULL, set_anon_super, flags, NULL);
if (IS_ERR(s)) {
rc = PTR_ERR(s);
goto out;
}
rc = bdi_setup_and_register(&sbi->bdi, "ecryptfs", BDI_CAP_MAP_COPY);
if (rc)
goto out1;
ecryptfs_set_superblock_private(s, sbi);
s->s_bdi = &sbi->bdi;
sbi = NULL;
s->s_op = &ecryptfs_sops;
s->s_d_op = &ecryptfs_dops;
err = "Reading sb failed";
rc = kern_path(dev_name, LOOKUP_FOLLOW | LOOKUP_DIRECTORY, &path);
if (rc) {
ecryptfs_printk(KERN_WARNING, "kern_path() failed\n");
goto out1;
}
if (path.dentry->d_sb->s_type == &ecryptfs_fs_type) {
rc = -EINVAL;
printk(KERN_ERR "Mount on filesystem of type "
"eCryptfs explicitly disallowed due to "
"known incompatibilities\n");
goto out_free;
}
if (check_ruid && !uid_eq(path.dentry->d_inode->i_uid, current_uid())) {
rc = -EPERM;
printk(KERN_ERR "Mount of device (uid: %d) not owned by "
"requested user (uid: %d)\n",
i_uid_read(path.dentry->d_inode),
from_kuid(&init_user_ns, current_uid()));
goto out_free;
}
ecryptfs_set_superblock_lower(s, path.dentry->d_sb);
s->s_flags = flags & ~MS_POSIXACL;
s->s_flags |= path.dentry->d_sb->s_flags & (MS_RDONLY | MS_POSIXACL);
s->s_maxbytes = path.dentry->d_sb->s_maxbytes;
s->s_blocksize = path.dentry->d_sb->s_blocksize;
s->s_magic = ECRYPTFS_SUPER_MAGIC;
inode = ecryptfs_get_inode(path.dentry->d_inode, s);
rc = PTR_ERR(inode);
if (IS_ERR(inode))
goto out_free;
s->s_root = d_make_root(inode);
if (!s->s_root) {
rc = -ENOMEM;
goto out_free;
}
rc = -ENOMEM;
root_info = kmem_cache_zalloc(ecryptfs_dentry_info_cache, GFP_KERNEL);
if (!root_info)
goto out_free;
ecryptfs_set_dentry_private(s->s_root, root_info);
root_info->lower_path = path;
s->s_flags |= MS_ACTIVE;
return dget(s->s_root);
out_free:
path_put(&path);
out1:
deactivate_locked_super(s);
out:
if (sbi) {
ecryptfs_destroy_mount_crypt_stat(&sbi->mount_crypt_stat);
kmem_cache_free(ecryptfs_sb_info_cache, sbi);
}
printk(KERN_ERR "%s; rc = [%d]\n", err, rc);
return ERR_PTR(rc);
}

static RList *patch_relocs(RBin *b) {
r_return_val_if_fail (b && b->iob.io && b->iob.io->desc, NULL);
RBinObject *bo = r_bin_cur_object (b);
RIO *io = b->iob.io;
if (!bo || !bo->bin_obj) {
return NULL;
}
struct r_bin_coff_obj *bin = (struct r_bin_coff_obj*)bo->bin_obj;
if (bin->hdr.f_flags & COFF_FLAGS_TI_F_EXEC) {
return NULL;
}
if (!(io->cached & R_PERM_W)) {
eprintf (
"Warning: please run r2 with -e io.cache=true to patch "
"relocations\n");
return NULL;
}
size_t nimports = 0;
int i;
for (i = 0; i < bin->hdr.f_nsyms; i++) {
if (is_imported_symbol (&bin->symbols[i])) {
nimports++;
}
i += bin->symbols[i].n_numaux;
}
ut64 m_vaddr = UT64_MAX;
if (nimports) {
ut64 offset = 0;
RIOBank *bank = b->iob.bank_get (io, io->bank);
RListIter *iter;
RIOMapRef *mapref;
r_list_foreach (bank->maprefs, iter, mapref) {
RIOMap *map = b->iob.map_get (io, mapref->id);
if (r_io_map_end (map) > offset) {
offset = r_io_map_end (map);
}
}
m_vaddr = R_ROUND (offset, 16);
ut64 size = nimports * BYTES_PER_IMP_RELOC;
char *muri = r_str_newf ("malloc:RIODesc *desc = b->iob.open_at (io, muri, R_PERM_R, 0664, m_vaddr);
free (muri);
if (!desc) {
return NULL;
}
RIOMap *map = b->iob.map_get_at (io, m_vaddr);
if (!map) {
return NULL;
}
map->name = strdup (".imports.r2");
}
return _relocs_list (b, bin, true, m_vaddr);
}

static int alloc_l3_table(struct page_info *page)
{
struct domain *d = page_get_owner(page);
unsigned long  pfn = mfn_x(page_to_mfn(page));
l3_pgentry_t  *pl3e;
unsigned int   i;
int            rc = 0, partial = page->partial_pte;
pl3e = map_domain_page(_mfn(pfn));
if ( is_pv_32bit_domain(d) )
memset(pl3e + 4, 0, (L3_PAGETABLE_ENTRIES - 4) * sizeof(*pl3e));
for ( i = page->nr_validated_ptes; i < L3_PAGETABLE_ENTRIES;
i++, partial = 0 )
{
if ( is_pv_32bit_domain(d) && (i == 3) )
{
if ( !(l3e_get_flags(pl3e[i]) & _PAGE_PRESENT) ||
(l3e_get_flags(pl3e[i]) & l3_disallow_mask(d)) )
rc = -EINVAL;
else
rc = get_page_and_type_from_mfn(
l3e_get_mfn(pl3e[i]),
PGT_l2_page_table | PGT_pae_xen_l2, d, partial, 1);
}
else if ( (rc = get_page_from_l3e(pl3e[i], pfn, d, partial)) > 0 )
continue;
if ( rc == -ERESTART )
{
page->nr_validated_ptes = i;
page->partial_pte = partial ?: 1;
}
else if ( rc == -EINTR && i )
{
page->nr_validated_ptes = i;
page->partial_pte = 0;
rc = -ERESTART;
}
if ( rc < 0 )
break;
pl3e[i] = adjust_guest_l3e(pl3e[i], d);
}
if ( rc >= 0 && !create_pae_xen_mappings(d, pl3e) )
rc = -EINVAL;
if ( rc < 0 && rc != -ERESTART && rc != -EINTR )
{
gdprintk(XENLOG_WARNING, "Failure in alloc_l3_table: slot %#x\n", i);
if ( i )
{
page->nr_validated_ptes = i;
page->partial_pte = 0;
current->arch.old_guest_table = page;
}
while ( i-- > 0 )
pl3e[i] = unadjust_guest_l3e(pl3e[i], d);
}
unmap_domain_page(pl3e);
return rc > 0 ? 0 : rc;
}

void *    
resolveStaticFieldRefInto(J9VMThread *vmStruct, J9Method *method, J9ConstantPool *ramCP, UDATA cpIndex, UDATA resolveFlags, J9ROMFieldShape **resolvedField, J9RAMStaticFieldRef *ramCPEntry)
{
void *staticAddress;
J9ROMFieldRef *romFieldRef;
J9Class *resolvedClass;
bool jitCompileTimeResolve = J9_ARE_ANY_BITS_SET(resolveFlags, J9_RESOLVE_FLAG_JIT_COMPILE_TIME);
bool canRunJavaCode = !jitCompileTimeResolve && J9_ARE_NO_BITS_SET(resolveFlags, J9_RESOLVE_FLAG_REDEFINE_CLASS);
bool throwException = canRunJavaCode && J9_ARE_NO_BITS_SET(resolveFlags, J9_RESOLVE_FLAG_NO_THROW_ON_FAIL);
UDATA lookupOptions = 0;
if (canRunJavaCode) {
if (!throwException) {
lookupOptions = J9_LOOK_NO_THROW;
}
} else {
lookupOptions = J9_LOOK_NO_JAVA;
}
Trc_VM_resolveStaticFieldRef_Entry(vmStruct, method, ramCP, cpIndex, resolveFlags, resolvedField);
tryAgain:
staticAddress = NULL;
romFieldRef = (J9ROMFieldRef *)&ramCP->romConstantPool[cpIndex];
resolvedClass = resolveClassRef(vmStruct, ramCP, romFieldRef->classRefCPIndex, resolveFlags);
if (resolvedClass != NULL) {
J9JavaVM *javaVM = vmStruct->javaVM;
J9Class *classFromCP = J9_CLASS_FROM_CP(ramCP);
J9ROMFieldShape *field;
J9Class *definingClass;
J9ROMNameAndSignature *nameAndSig;
J9UTF8 *name;
J9UTF8 *signature;
IDATA checkResult = J9_VISIBILITY_NON_MODULE_ACCESS_ERROR;
IDATA badMemberModifier = 0;
J9Class *targetClass = NULL;
UDATA modifiers = 0;
J9Class *localClassAndFlags = NULL;
UDATA initStatus = 0;
checkResult = checkVisibility(vmStruct, classFromCP, resolvedClass, resolvedClass->romClass->modifiers, lookupOptions);
if (checkResult < J9_VISIBILITY_ALLOWED) {
targetClass = resolvedClass;
badMemberModifier = resolvedClass->romClass->modifiers;
goto illegalAccess;
}
nameAndSig = J9ROMFIELDREF_NAMEANDSIGNATURE(romFieldRef);
name = J9ROMNAMEANDSIGNATURE_NAME(nameAndSig);
signature = J9ROMNAMEANDSIGNATURE_SIGNATURE(nameAndSig);
staticAddress = staticFieldAddress(vmStruct, resolvedClass, J9UTF8_DATA(name), J9UTF8_LENGTH(name), J9UTF8_DATA(signature), J9UTF8_LENGTH(signature), &definingClass, (UDATA *)&field, lookupOptions, classFromCP);
if (staticAddress != NULL) {
modifiers = field->modifiers;
localClassAndFlags = definingClass;
initStatus = definingClass->initializeStatus;
if (resolvedField != NULL) {
*resolvedField = field;
}
if (J9_ARE_NO_BITS_SET(resolveFlags, J9_RESOLVE_FLAG_NO_CLASS_INIT)) {
if (initStatus != J9ClassInitSucceeded && initStatus != (UDATA) vmStruct) {
if (canRunJavaCode) {
UDATA preCount = javaVM->hotSwapCount;
initializeClass(vmStruct, definingClass);
if (threadEventsPending(vmStruct)) {
staticAddress = NULL;
goto done;
}
if (preCount != javaVM->hotSwapCount) {
goto tryAgain;
}
} else {
staticAddress = NULL;
goto done;
}
}
}
if ((resolveFlags & J9_RESOLVE_FLAG_FIELD_SETTER) != 0 && (modifiers & J9AccFinal) != 0) {
checkResult = checkVisibility(vmStruct, classFromCP, definingClass, J9AccPrivate, lookupOptions | J9_LOOK_NO_NESTMATES);
if (checkResult < J9_VISIBILITY_ALLOWED) {
targetClass = definingClass;
badMemberModifier = J9AccPrivate;
illegalAccess:
staticAddress = NULL;
if (canRunJavaCode && !threadEventsPending(vmStruct)) {
char *errorMsg = NULL;
PORT_ACCESS_FROM_VMC(vmStruct);
if (J9_VISIBILITY_NON_MODULE_ACCESS_ERROR == checkResult) {
errorMsg = illegalAccessMessage(vmStruct, badMemberModifier, classFromCP, targetClass, J9_VISIBILITY_NON_MODULE_ACCESS_ERROR);
} else {
errorMsg = illegalAccessMessage(vmStruct, -1, classFromCP, targetClass, checkResult);
}
setCurrentExceptionUTF(vmStruct, J9VMCONSTANTPOOL_JAVALANGILLEGALACCESSERROR, errorMsg);
j9mem_free_memory(errorMsg);
}
goto done;
}
if (!finalFieldSetAllowed(vmStruct, true, method, definingClass, classFromCP, field, canRunJavaCode)) {
staticAddress = NULL;
goto done;
} else { 
if (jitCompileTimeResolve) {
staticAddress = NULL;
goto done;
}
VM_VMHelpers::reportFinalFieldModified(vmStruct, definingClass);
}
}
if ((javaVM->runtimeFlags & J9_RUNTIME_VERIFY) != 0) {
J9ClassLoader *cl1 = classFromCP->classLoader;
J9ClassLoader *cl2 = definingClass->classLoader;
if (cl1 == NULL) {
cl1 = javaVM->systemClassLoader;
}
if (cl1 != cl2) {
J9UTF8 *fieldSignature = J9ROMFIELDSHAPE_SIGNATURE(field);
if (j9bcv_checkClassLoadingConstraintsForSignature(vmStruct, cl1, cl2, signature, fieldSignature) != 0) {
if (throwException) {
setCurrentException(vmStruct, J9VMCONSTANTPOOL_JAVALANGVERIFYERROR, NULL);
}
staticAddress = NULL;
goto done;
}
}
}
if (jitCompileTimeResolve && (J9ClassInitSucceeded != initStatus)) {
goto done;
}
if (ramCPEntry != NULL) {
UDATA localClassAndFlagsData = (UDATA)localClassAndFlags;
if ((modifiers & J9FieldFlagObject) != J9FieldFlagObject) {
localClassAndFlagsData |= J9StaticFieldRefBaseType;
if ((modifiers & J9FieldSizeDouble) == J9FieldSizeDouble) {
localClassAndFlagsData |= J9StaticFieldRefDouble;
} else if (J9FieldTypeBoolean == (modifiers & J9FieldTypeMask)) {
localClassAndFlagsData |= J9StaticFieldRefBoolean;
}
}
if ((modifiers & J9AccVolatile) == J9AccVolatile) {
localClassAndFlagsData |= J9StaticFieldRefVolatile;
}
if ((modifiers & J9AccFinal) == J9AccFinal) {
localClassAndFlagsData |= J9StaticFieldRefFinal;
}
if (0 != (resolveFlags & J9_RESOLVE_FLAG_FIELD_SETTER)) {
localClassAndFlagsData |= J9StaticFieldRefPutResolved;
}
ramCPEntry->flagsAndClass = J9FLAGSANDCLASS_FROM_CLASSANDFLAGS(localClassAndFlagsData);
ramCPEntry->valueOffset = ((UDATA) staticAddress - (UDATA) localClassAndFlags->ramStatics) | (UDATA) IDATA_MIN;
}
}
}
done:
Trc_VM_resolveStaticFieldRef_Exit(vmStruct, staticAddress);
return staticAddress;
}

