static int php_mb_parse_encoding_list(const char *value, int value_length,
mbfl_encoding ***return_list,
int *return_size, int persistent) {
int n, l, size, bauto, ret = 1;
char *p, *p1, *p2, *endp, *tmpstr;
mbfl_encoding *encoding;
mbfl_no_encoding *src;
mbfl_encoding **entry, **list;
list = nullptr;
if (value == nullptr || value_length <= 0) {
if (return_list) {
*return_list = nullptr;
}
if (return_size) {
*return_size = 0;
}
return 0;
} else {
mbfl_no_encoding *identify_list;
int identify_list_size;
identify_list = MBSTRG(default_detect_order_list);
identify_list_size = MBSTRG(default_detect_order_list_size);
if (value[0]=='"' && value[value_length-1]=='"' && value_length>2) {
tmpstr = (char *)strndup(value+1, value_length-2);
value_length -= 2;
}
else
tmpstr = (char *)strndup(value, value_length);
if (tmpstr == nullptr) {
return 0;
}
endp = tmpstr + value_length;
n = 1;
p1 = tmpstr;
while ((p2 = (char*)string_memnstr(p1, ",", 1, endp)) != nullptr) {
p1 = p2 + 1;
n++;
}
size = n + identify_list_size;
list = (mbfl_encoding **)calloc(size, sizeof(mbfl_encoding*));
if (list != nullptr) {
entry = list;
n = 0;
bauto = 0;
p1 = tmpstr;
do {
p2 = p = (char*)string_memnstr(p1, ",", 1, endp);
if (p == nullptr) {
p = endp;
}
*p = '\0';
while (p1 < p && (*p1 == ' ' || *p1 == '\t')) {
p1++;
}
p--;
while (p > p1 && (*p == ' ' || *p == '\t')) {
*p = '\0';
p--;
}
if (strcasecmp(p1, "auto") == 0) {
if (!bauto) {
bauto = 1;
l = identify_list_size;
src = identify_list;
for (int i = 0; i < l; i++) {
*entry++ = (mbfl_encoding*) mbfl_no2encoding(*src++);
n++;
}
}
} else {
encoding = (mbfl_encoding*) mbfl_name2encoding(p1);
if (encoding != nullptr) {
*entry++ = encoding;
n++;
} else {
ret = 0;
}
}
p1 = p2 + 1;
} while (n < size && p2 != nullptr);
if (n > 0) {
if (return_list) {
*return_list = list;
} else {
free(list);
}
} else {
free(list);
if (return_list) {
*return_list = nullptr;
}
ret = 0;
}
if (return_size) {
*return_size = n;
}
} else {
if (return_list) {
*return_list = nullptr;
}
if (return_size) {
*return_size = 0;
}
ret = 0;
}
free(tmpstr);
}
return ret;
}

static bool
parse_cmdline(int argc, char **argv)
{
int c;
bool reopen_log = false;
int signum;
struct utsname uname_buf;
int longindex;
int curind;
bool bad_option = false;
unsigned facility;
struct option long_options[] = {
{"use-file",required_argument,NULL, 'f'},
#if defined _WITH_VRRP_ && defined _WITH_LVS_
{"vrrp",no_argument,NULL, 'P'},
{"check",no_argument,NULL, 'C'},
#endif
#ifdef _WITH_BFD_
{"no_bfd",no_argument,NULL, 'B'},
#endif
{"all",no_argument,NULL,  3 },
{"log-console",no_argument,NULL, 'l'},
{"log-detail",no_argument,NULL, 'D'},
{"log-facility",required_argument,NULL, 'S'},
{"log-file",optional_argument,NULL, 'g'},
{"flush-log-file",no_argument,NULL,  2 },
{"no-syslog",no_argument,NULL, 'G'},
#ifdef _WITH_VRRP_
{"release-vips",no_argument,NULL, 'X'},
{"dont-release-vrrp",no_argument,NULL, 'V'},
#endif
#ifdef _WITH_LVS_
{"dont-release-ipvs",no_argument,NULL, 'I'},
#endif
{"dont-respawn",no_argument,NULL, 'R'},
{"dont-fork",no_argument,NULL, 'n'},
{"dump-conf",no_argument,NULL, 'd'},
{"pid",required_argument,NULL, 'p'},
#ifdef _WITH_VRRP_
{"vrrp_pid",required_argument,NULL, 'r'},
#endif
#ifdef _WITH_LVS_
{"checkers_pid",required_argument,NULL, 'c'},
{"address-monitoring",no_argument,NULL, 'a'},
#endif
#ifdef _WITH_BFD_
{"bfd_pid",required_argument,NULL, 'b'},
#endif
#ifdef _WITH_SNMP_
{"snmp",no_argument,NULL, 'x'},
{"snmp-agent-socket",required_argument,NULL, 'A'},
#endif
{"core-dump",no_argument,NULL, 'm'},
{"core-dump-pattern",optional_argument,NULL, 'M'},
#ifdef _MEM_CHECK_LOG_
{"mem-check-log",no_argument,NULL, 'L'},
#endif
#if HAVE_DECL_CLONE_NEWNET
{"namespace",required_argument,NULL, 's'},
#endif
{"config-id",required_argument,NULL, 'i'},
{"signum",required_argument,NULL,  4 },
{"config-test",optional_argument,NULL, 't'},
#ifdef _WITH_PERF_
{"perf",optional_argument,NULL,  5 },
#endif
#ifdef WITH_DEBUG_OPTIONS
{"debug",optional_argument,NULL,  6 },
#endif
{"version",no_argument,NULL, 'v'},
{"help",no_argument,NULL, 'h'},
{NULL,0,NULL,  0 }
};
curind = optind;
while (longindex = -1, (c = getopt_long(argc, argv, ":vhlndDRS:f:p:i:mM::g::Gt::"
#if defined _WITH_VRRP_ && defined _WITH_LVS_
"PC"
#endif
#ifdef _WITH_VRRP_
"r:VX"
#endif
#ifdef _WITH_LVS_
"ac:I"
#endif
#ifdef _WITH_BFD_
"Bb:"
#endif
#ifdef _WITH_SNMP_
"xA:"
#endif
#ifdef _MEM_CHECK_LOG_
"L"
#endif
#if HAVE_DECL_CLONE_NEWNET
"s:"
#endif
, long_options, &longindex)) != -1) {
if (longindex >= 0 && long_options[longindex].has_arg == required_argument && optarg && !optarg[0]) {
c = ':';
optarg = NULL;
}
switch (c) {
case 'v':
fprintf(stderr, "%s", version_string);
#ifdef GIT_COMMIT
fprintf(stderr, ", git commit %s", GIT_COMMIT);
#endif
fprintf(stderr, "\n\n%s\n\n", COPYRIGHT_STRING);
fprintf(stderr, "Built with kernel headers for Linux %d.%d.%d\n",
(LINUX_VERSION_CODE >> 16) & 0xff,
(LINUX_VERSION_CODE >>  8) & 0xff,
(LINUX_VERSION_CODE      ) & 0xff);
uname(&uname_buf);
fprintf(stderr, "Running on %s %s %s\n\n", uname_buf.sysname, uname_buf.release, uname_buf.version);
fprintf(stderr, "configure options: %s\n\n", KEEPALIVED_CONFIGURE_OPTIONS);
fprintf(stderr, "Config options: %s\n\n", CONFIGURATION_OPTIONS);
fprintf(stderr, "System options: %s\n", SYSTEM_OPTIONS);
exit(0);
break;
case 'h':
usage(argv[0]);
exit(0);
break;
case 'l':
__set_bit(LOG_CONSOLE_BIT, &debug);
reopen_log = true;
break;
case 'n':
__set_bit(DONT_FORK_BIT, &debug);
break;
case 'd':
__set_bit(DUMP_CONF_BIT, &debug);
break;
#ifdef _WITH_VRRP_
case 'V':
__set_bit(DONT_RELEASE_VRRP_BIT, &debug);
break;
#endif
#ifdef _WITH_LVS_
case 'I':
__set_bit(DONT_RELEASE_IPVS_BIT, &debug);
break;
#endif
case 'D':
if (__test_bit(LOG_DETAIL_BIT, &debug))
__set_bit(LOG_EXTRA_DETAIL_BIT, &debug);
else
__set_bit(LOG_DETAIL_BIT, &debug);
break;
case 'R':
__set_bit(DONT_RESPAWN_BIT, &debug);
break;
#ifdef _WITH_VRRP_
case 'X':
__set_bit(RELEASE_VIPS_BIT, &debug);
break;
#endif
case 'S':
if (!read_unsigned(optarg, &facility, 0, LOG_FACILITY_MAX, false))
fprintf(stderr, "Invalid log facility '%s'\n", optarg);
else {
log_facility = LOG_FACILITY[facility].facility;
reopen_log = true;
}
break;
case 'g':
if (optarg && optarg[0])
log_file_name = optarg;
else
log_file_name = "/tmp/keepalived.log";
open_log_file(log_file_name, NULL, NULL, NULL);
break;
case 'G':
__set_bit(NO_SYSLOG_BIT, &debug);
reopen_log = true;
break;
case 't':
__set_bit(CONFIG_TEST_BIT, &debug);
__set_bit(DONT_RESPAWN_BIT, &debug);
__set_bit(DONT_FORK_BIT, &debug);
__set_bit(NO_SYSLOG_BIT, &debug);
if (optarg && optarg[0]) {
int fd = open(optarg, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
if (fd == -1) {
fprintf(stderr, "Unable to open config-test log file %s\n", optarg);
exit(EXIT_FAILURE);
}
dup2(fd, STDERR_FILENO);
close(fd);
}
break;
case 'f':
conf_file = optarg;
break;
case 2:
set_flush_log_file();
break;
#if defined _WITH_VRRP_ && defined _WITH_LVS_
case 'P':
__clear_bit(DAEMON_CHECKERS, &daemon_mode);
break;
case 'C':
__clear_bit(DAEMON_VRRP, &daemon_mode);
break;
#endif
#ifdef _WITH_BFD_
case 'B':
__clear_bit(DAEMON_BFD, &daemon_mode);
break;
#endif
case 'p':
main_pidfile = optarg;
break;
#ifdef _WITH_LVS_
case 'c':
checkers_pidfile = optarg;
break;
case 'a':
__set_bit(LOG_ADDRESS_CHANGES, &debug);
break;
#endif
#ifdef _WITH_VRRP_
case 'r':
vrrp_pidfile = optarg;
break;
#endif
#ifdef _WITH_BFD_
case 'b':
bfd_pidfile = optarg;
break;
#endif
#ifdef _WITH_SNMP_
case 'x':
snmp = 1;
break;
case 'A':
snmp_socket = optarg;
break;
#endif
case 'M':
set_core_dump_pattern = true;
if (optarg && optarg[0])
core_dump_pattern = optarg;
case 'm':
create_core_dump = true;
break;
#ifdef _MEM_CHECK_LOG_
case 'L':
__set_bit(MEM_CHECK_LOG_BIT, &debug);
break;
#endif
#if HAVE_DECL_CLONE_NEWNET
case 's':
override_namespace = MALLOC(strlen(optarg) + 1);
strcpy(override_namespace, optarg);
break;
#endif
case 'i':
FREE_PTR(config_id);
config_id = MALLOC(strlen(optarg) + 1);
strcpy(config_id, optarg);
break;
case 4:
signum = get_signum(optarg);
if (signum == -1) {
fprintf(stderr, "Unknown sigfunc %s\n", optarg);
exit(1);
}
printf("%d\n", signum);
exit(0);
break;
case 3:
__set_bit(RUN_ALL_CHILDREN, &daemon_mode);
#ifdef _WITH_VRRP_
__set_bit(DAEMON_VRRP, &daemon_mode);
#endif
#ifdef _WITH_LVS_
__set_bit(DAEMON_CHECKERS, &daemon_mode);
#endif
#ifdef _WITH_BFD_
__set_bit(DAEMON_BFD, &daemon_mode);
#endif
break;
#ifdef _WITH_PERF_
case 5:
if (optarg && optarg[0]) {
if (!strcmp(optarg, "run"))
perf_run = PERF_RUN;
else if (!strcmp(optarg, "all"))
perf_run = PERF_ALL;
else if (!strcmp(optarg, "end"))
perf_run = PERF_END;
else
log_message(LOG_INFO, "Unknown perf start point %s", optarg);
}
else
perf_run = PERF_RUN;
break;
#endif
#ifdef WITH_DEBUG_OPTIONS
case 6:
set_debug_options(optarg && optarg[0] ? optarg : NULL);
break;
#endif
case '?':
if (optopt && argv[curind][1] != '-')
fprintf(stderr, "Unknown option -%c\n", optopt);
else
fprintf(stderr, "Unknown option %s\n", argv[curind]);
bad_option = true;
break;
case ':':
if (optopt && argv[curind][1] != '-')
fprintf(stderr, "Missing parameter for option -%c\n", optopt);
else
fprintf(stderr, "Missing parameter for option --%s\n", long_options[longindex].name);
bad_option = true;
break;
default:
exit(1);
break;
}
curind = optind;
}
if (optind < argc) {
printf("Unexpected argument(s): ");
while (optind < argc)
printf("%s ", argv[optind++]);
printf("\n");
}
if (bad_option)
exit(1);
return reopen_log;
}

int
dwarf_hasattr (Dwarf_Die *die, unsigned int search_name)
{
if (die == NULL)
return 0;
Dwarf_Abbrev *abbrevp = __libdw_dieabbrev (die, NULL);
if (unlikely (abbrevp == DWARF_END_ABBREV))
{
__libdw_seterrno (DWARF_E_INVALID_DWARF);
return 0;
}
const unsigned char *attrp = abbrevp->attrp;
while (1)
{
unsigned int attr_name;
get_uleb128_unchecked (attr_name, attrp);
unsigned int attr_form;
get_uleb128_unchecked (attr_form, attrp);
if (attr_name == 0 || attr_form == 0)
return 0;
if (attr_name == search_name)
return 1;
if (attr_form == DW_FORM_implicit_const)
{
int64_t attr_value __attribute__ ((unused));
get_sleb128_unchecked (attr_value, attrp);
}
}
}

int _option_parse(gnrc_tcp_tcb_t *tcb, tcp_hdr_t *hdr)
{
uint8_t offset = GET_OFFSET(byteorder_ntohs(hdr->off_ctl));
if (offset <= TCP_HDR_OFFSET_MIN) {
return 0;
}
uint8_t *opt_ptr = (uint8_t *) hdr + sizeof(tcp_hdr_t);
uint8_t opt_left = (offset - TCP_HDR_OFFSET_MIN) * 4;
while (opt_left > 0) {
tcp_hdr_opt_t *option = (tcp_hdr_opt_t *) opt_ptr;
switch (option->kind) {
case TCP_OPTION_KIND_EOL:
DEBUG("gnrc_tcp_option.c : _option_parse() : EOL option found\n");
return 0;
case TCP_OPTION_KIND_NOP:
DEBUG("gnrc_tcp_option.c : _option_parse() : NOP option found\n");
opt_ptr += 1;
opt_left -= 1;
continue;
case TCP_OPTION_KIND_MSS:
if (option->length != TCP_OPTION_LENGTH_MSS) {
DEBUG("gnrc_tcp_option.c : _option_parse() : invalid MSS Option length.\n");
return -1;
}
tcb->mss = (option->value[0] << 8) | option->value[1];
DEBUG("gnrc_tcp_option.c : _option_parse() : MSS option found. MSS=%"PRIu16"\n",
tcb->mss);
break;
default:
DEBUG("gnrc_tcp_option.c : _option_parse() : Unknown option found.\
KIND=%"PRIu8", LENGTH=%"PRIu8"\n", option->kind, option->length);
}
if (option->length > opt_left) {
DEBUG("gnrc_tcp_option.c : _option_parse() : invalid option length\n");
return 0;
}
opt_ptr += option->length;
opt_left -= option->length;
}
return 0;
}

R_API int java_print_opcode(RBinJavaObj *obj, ut64 addr, int idx, const ut8 *bytes, int len, char *output, int outlen) {
if (idx < 0 || idx >= JAVA_OPS_COUNT) {
return -1;
}
char *arg = NULL;
int sz = 0;
ut32 val_one = 0;
ut32 val_two = 0;
ut8 op_byte = JAVA_OPS[idx].byte;
if (IN_SWITCH_OP) {
return handle_switch_op (addr, bytes, len, output, outlen);
}
R_LOG_DEBUG ("Handling the following opcode %s expects: %d byte(s), BYTES_CONSUMED: 0x%04"PFMT64x,
JAVA_OPS[idx].name, JAVA_OPS[idx].size, BYTES_CONSUMED);
switch (op_byte) {
case 0x10: if (len > 1) {
snprintf (output, outlen, "%s %d", JAVA_OPS[idx].name, (char) bytes[1]);
output[outlen - 1] = 0;
return update_bytes_consumed (JAVA_OPS[idx].size);
}
return -1;
case 0x11:
if (len > 2) {
snprintf (output, outlen, "%s %d", JAVA_OPS[idx].name, (int)USHORT (bytes, 1));
output[outlen - 1] = 0;
return update_bytes_consumed (JAVA_OPS[idx].size);
}
return -1;
case 0x15: case 0x16: case 0x17: case 0x18: case 0x19: case 0x37: case 0x38: case 0x39: case 0x3a: case 0xbc: case 0xa9: if (len > 1) {
snprintf (output, outlen, "%s %d", JAVA_OPS[idx].name, bytes[1]);
output[outlen-1] = 0;
return update_bytes_consumed (JAVA_OPS[idx].size);
} else {
return 0;
}
break;
case 0x12: if (len > 1) {
arg = r_bin_java_resolve_without_space (obj, (ut16)bytes[1]);
if (arg) {
snprintf (output, outlen, "%s %s", JAVA_OPS[idx].name, arg);
free (arg);
} else {
snprintf (output, outlen, "%s #%d", JAVA_OPS[idx].name, USHORT (bytes, 1));
}
output[outlen - 1] = 0;
return update_bytes_consumed (JAVA_OPS[idx].size);
}
return -1;
case 0x13:
case 0x14:
if (len > 2) {
arg = r_bin_java_resolve_without_space (obj, (int)USHORT (bytes, 1));
if (arg) {
snprintf (output, outlen, "%s %s", JAVA_OPS[idx].name, arg);
free (arg);
} else {
snprintf (output, outlen, "%s #%d", JAVA_OPS[idx].name, USHORT (bytes, 1));
}
output[outlen-1] = 0;
return update_bytes_consumed (JAVA_OPS[idx].size);
}
return -1;
case 0x84: if (len > 2) {
val_one = (ut32)bytes[1];
val_two = (ut32) bytes[2];
snprintf (output, outlen, "%s %d %d", JAVA_OPS[idx].name, val_one, val_two);
output[outlen-1] = 0;
return update_bytes_consumed (JAVA_OPS[idx].size);
}
return -1;
case 0x99: case 0x9a: case 0x9b: case 0x9c: case 0x9d: case 0x9e: case 0x9f: case 0xa0: case 0xa1: case 0xa2: case 0xa3: case 0xa4: case 0xa5: case 0xa6: case 0xa7: case 0xa8: if (len > 1) {
snprintf (output, outlen, "%s 0x%04"PFMT64x, JAVA_OPS[idx].name,
(addr + (short)USHORT (bytes, 1)));
output[outlen - 1] = 0;
return update_bytes_consumed (JAVA_OPS[idx].size);
}
return -1;
case 0xab: case 0xaa: sz = enter_switch_op (addr, bytes, len);
snprintf (output, outlen, "%s default: 0x%04"PFMT64x,
JAVA_OPS[idx].name,
(ut64)(SWITCH_OP.def_jmp+SWITCH_OP.addr));
return update_bytes_consumed (sz);
case 0xb6: case 0xb7: case 0xb8: case 0xb9: case 0xba: if (len > 2) {
arg = r_bin_java_resolve_without_space (obj, (int)USHORT (bytes, 1));
if (arg) {
snprintf (output, outlen, "%s %s", JAVA_OPS[idx].name, arg);
free (arg);
} else {
snprintf (output, outlen, "%s #%d", JAVA_OPS[idx].name, USHORT (bytes, 1) );
}
output[outlen - 1] = 0;
return update_bytes_consumed (JAVA_OPS[idx].size);
}
return -1;
case 0xbb: case 0xbd: case 0xc0: case 0xc1: if (len > 2) {
arg = r_bin_java_resolve_without_space (obj, (int)USHORT (bytes, 1));
if (arg) {
snprintf (output, outlen, "%s %s", JAVA_OPS[idx].name, arg);
free (arg);
} else {
snprintf (output, outlen, "%s #%d", JAVA_OPS[idx].name, USHORT (bytes, 1) );
}
output[outlen-1] = 0;
return update_bytes_consumed (JAVA_OPS[idx].size);
}
return -1;
case 0xb2: case 0xb3: case 0xb4: case 0xb5: if (len > 2) {
arg = r_bin_java_resolve_with_space (obj, (int)USHORT (bytes, 1));
if (arg) {
snprintf (output, outlen, "%s %s", JAVA_OPS[idx].name, arg);
free (arg);
} else {
snprintf (output, outlen, "%s #%d", JAVA_OPS[idx].name, USHORT (bytes, 1) );
}
output[outlen - 1] = 0;
return update_bytes_consumed (JAVA_OPS[idx].size);
}
return -1;
}
if (JAVA_OPS[idx].size > len) {
snprintf (output, outlen, "truncated");
return -1;
}
switch (JAVA_OPS[idx].size) {
case 1: snprintf (output, outlen, "%s", JAVA_OPS[idx].name);
break;
case 2: snprintf (output, outlen, "%s %d", JAVA_OPS[idx].name, bytes[1]);
break;
case 3: snprintf (output, outlen, "%s 0x%04x 0x%04x", JAVA_OPS[idx].name, bytes[0], bytes[1]);
break;
case 5: snprintf (output, outlen, "%s %d", JAVA_OPS[idx].name, bytes[1]);
break;
}
return update_bytes_consumed (JAVA_OPS[idx].size);
}

static gboolean
parse_cosine_packet(FILE_T fh, struct wtap_pkthdr *phdr, Buffer *buf,
char *line, int *err, gchar **err_info)
{
union wtap_pseudo_header *pseudo_header = &phdr->pseudo_header;
intnum_items_scanned;
intyy, mm, dd, hr, min, sec, csec;
guintpkt_len;
intpro, off, pri, rm, error;
guintcode1, code2;
charif_name[COSINE_MAX_IF_NAME_LEN] = "", direction[6] = "";
structtm tm;
guint8 *pd;
inti, hex_lines, n, caplen = 0;
if (sscanf(line, "%4d-%2d-%2d,%2d:%2d:%2d.%9d:",
&yy, &mm, &dd, &hr, &min, &sec, &csec) == 7) {
num_items_scanned = sscanf(line,
"%4d-%2d-%2d,%2d:%2d:%2d.%9d: %5s (%127[A-Za-z0-9/:]), Length:%9u, Pro:%9d, Off:%9d, Pri:%9d, RM:%9d, Err:%9d [%8x, %8x]",
&yy, &mm, &dd, &hr, &min, &sec, &csec,
direction, if_name, &pkt_len,
&pro, &off, &pri, &rm, &error,
&code1, &code2);
if (num_items_scanned != 17) {
*err = WTAP_ERR_BAD_FILE;
*err_info = g_strdup("cosine: purported control blade line doesn't have code values");
return FALSE;
}
} else {
num_items_scanned = sscanf(line,
"%5s (%127[A-Za-z0-9/:]), Length:%9u, Pro:%9d, Off:%9d, Pri:%9d, RM:%9d, Err:%9d [%8x, %8x]",
direction, if_name, &pkt_len,
&pro, &off, &pri, &rm, &error,
&code1, &code2);
if (num_items_scanned != 10) {
*err = WTAP_ERR_BAD_FILE;
*err_info = g_strdup("cosine: header line is neither control blade nor PE output");
return FALSE;
}
yy = mm = dd = hr = min = sec = csec = 0;
}
if (pkt_len > WTAP_MAX_PACKET_SIZE) {
*err = WTAP_ERR_BAD_FILE;
*err_info = g_strdup_printf("cosine: File has %u-byte packet, bigger than maximum of %u",
pkt_len, WTAP_MAX_PACKET_SIZE);
return FALSE;
}
phdr->rec_type = REC_TYPE_PACKET;
phdr->presence_flags = WTAP_HAS_TS|WTAP_HAS_CAP_LEN;
tm.tm_year = yy - 1900;
tm.tm_mon = mm - 1;
tm.tm_mday = dd;
tm.tm_hour = hr;
tm.tm_min = min;
tm.tm_sec = sec;
tm.tm_isdst = -1;
phdr->ts.secs = mktime(&tm);
phdr->ts.nsecs = csec * 10000000;
phdr->len = pkt_len;
if (strncmp(if_name, "TEST:", 5) == 0) {
pseudo_header->cosine.encap = COSINE_ENCAP_TEST;
} else if (strncmp(if_name, "PPoATM:", 7) == 0) {
pseudo_header->cosine.encap = COSINE_ENCAP_PPoATM;
} else if (strncmp(if_name, "PPoFR:", 6) == 0) {
pseudo_header->cosine.encap = COSINE_ENCAP_PPoFR;
} else if (strncmp(if_name, "ATM:", 4) == 0) {
pseudo_header->cosine.encap = COSINE_ENCAP_ATM;
} else if (strncmp(if_name, "FR:", 3) == 0) {
pseudo_header->cosine.encap = COSINE_ENCAP_FR;
} else if (strncmp(if_name, "HDLC:", 5) == 0) {
pseudo_header->cosine.encap = COSINE_ENCAP_HDLC;
} else if (strncmp(if_name, "PPP:", 4) == 0) {
pseudo_header->cosine.encap = COSINE_ENCAP_PPP;
} else if (strncmp(if_name, "ETH:", 4) == 0) {
pseudo_header->cosine.encap = COSINE_ENCAP_ETH;
} else {
pseudo_header->cosine.encap = COSINE_ENCAP_UNKNOWN;
}
if (strncmp(direction, "l2-tx", 5) == 0) {
pseudo_header->cosine.direction = COSINE_DIR_TX;
} else if (strncmp(direction, "l2-rx", 5) == 0) {
pseudo_header->cosine.direction = COSINE_DIR_RX;
}
g_strlcpy(pseudo_header->cosine.if_name, if_name,
COSINE_MAX_IF_NAME_LEN);
pseudo_header->cosine.pro = pro;
pseudo_header->cosine.off = off;
pseudo_header->cosine.pri = pri;
pseudo_header->cosine.rm = rm;
pseudo_header->cosine.err = error;
ws_buffer_assure_space(buf, pkt_len);
pd = ws_buffer_start_ptr(buf);
hex_lines = pkt_len / 16 + ((pkt_len % 16) ? 1 : 0);
for (i = 0; i < hex_lines; i++) {
if (file_gets(line, COSINE_LINE_LENGTH, fh) == NULL) {
*err = file_error(fh, err_info);
if (*err == 0) {
*err = WTAP_ERR_SHORT_READ;
}
return FALSE;
}
if (empty_line(line)) {
break;
}
if ((n = parse_single_hex_dump_line(line, pd, i*16)) == -1) {
*err = WTAP_ERR_BAD_FILE;
*err_info = g_strdup("cosine: hex dump line doesn't have 16 numbers");
return FALSE;
}
caplen += n;
}
phdr->caplen = caplen;
return TRUE;
}

static int rtsx_usb_ms_drv_remove(struct platform_device *pdev)
{
struct rtsx_usb_ms *host = platform_get_drvdata(pdev);
struct memstick_host *msh = host->msh;
int err;
host->eject = true;
cancel_work_sync(&host->handle_req);
mutex_lock(&host->host_mutex);
if (host->req) {
dev_dbg(ms_dev(host),
"%s: Controller removed during transfer\n",
dev_name(&msh->dev));
host->req->error = -ENOMEDIUM;
do {
err = memstick_next_req(msh, &host->req);
if (!err)
host->req->error = -ENOMEDIUM;
} while (!err);
}
mutex_unlock(&host->host_mutex);
memstick_remove_host(msh);
memstick_free_host(msh);
if (pm_runtime_active(ms_dev(host)))
pm_runtime_put(ms_dev(host));
pm_runtime_disable(ms_dev(host));
platform_set_drvdata(pdev, NULL);
dev_dbg(ms_dev(host),
": Realtek USB Memstick controller has been removed\n");
return 0;
}

void LibRaw::parseSonySRF(unsigned len)
{
if ((len > 0xfffff) || (len == 0))
return;
INT64 save = ftell(ifp);
INT64 offset =
0x0310c0 - save; 
if (len < offset || offset < 0)
return;
INT64 decrypt_len = offset >> 2; 
unsigned i, nWB;
unsigned MasterKey, SRF2Key, RawDataKey;
INT64 srf_offset, tag_offset, tag_data, tag_dataoffset;
int tag_dataunitlen;
uchar *srf_buf;
short entries;
unsigned tag_id, tag_type, tag_datalen;
srf_buf = (uchar *)malloc(len);
fread(srf_buf, len, 1, ifp);
offset += srf_buf[offset] << 2;
#define CHECKBUFFER_SGET4(offset)                                              \
do                                                                           \
{                                                                            \
if ((((offset) + 4) > len) || ((offset) < 0))                              \
goto restore_after_parseSonySRF;                                         \
} while (0)
#define CHECKBUFFER_SGET2(offset)                                              \
do                                                                           \
{                                                                            \
if ( ((offset + 2) > len) || ((offset) < 0))                               \
goto restore_after_parseSonySRF;                                         \
} while (0)
CHECKBUFFER_SGET4(offset);
MasterKey = ((unsigned)srf_buf[offset] << 24) |
((unsigned)srf_buf[offset + 1] << 16) |
((unsigned)srf_buf[offset + 2] << 8) |
(unsigned)srf_buf[offset + 3];
srf_offset = 0;
CHECKBUFFER_SGET2(srf_offset);
entries = sget2(srf_buf + srf_offset);
if (entries > 1000)
goto restore_after_parseSonySRF;
offset = srf_offset + 2;
CHECKBUFFER_SGET4(offset);
CHECKBUFFER_SGET4(offset + 12 * entries);
srf_offset = sget4(srf_buf + offset + 12 * entries) -
save; 
if (srf_offset < 0 || decrypt_len < srf_offset / 4)
goto restore_after_parseSonySRF;
sony_decrypt((unsigned *)(srf_buf + srf_offset), decrypt_len - srf_offset / 4,
1, MasterKey);
CHECKBUFFER_SGET2(srf_offset);
entries = sget2(srf_buf + srf_offset);
if (entries > 1000)
goto restore_after_parseSonySRF;
offset = srf_offset + 2;
tag_offset = offset;
while (entries--) {
if (tiff_sget (save, srf_buf, len,
&tag_offset, &tag_id, &tag_type, &tag_dataoffset,
&tag_datalen, &tag_dataunitlen) == 0) {
if (tag_id == 0x0000) {
SRF2Key = sget4(srf_buf + tag_dataoffset);
} else if (tag_id == 0x0001) {
RawDataKey = sget4(srf_buf + tag_dataoffset);
}
} else goto restore_after_parseSonySRF;
}
offset = tag_offset;
CHECKBUFFER_SGET4(offset);
srf_offset =
sget4(srf_buf + offset) - save; 
if (srf_offset < 0 || decrypt_len < srf_offset / 4)
goto restore_after_parseSonySRF;
sony_decrypt((unsigned *)(srf_buf + srf_offset), decrypt_len - srf_offset / 4,
1, SRF2Key);
CHECKBUFFER_SGET2(srf_offset);
entries = sget2(srf_buf + srf_offset);
if (entries > 1000)
goto restore_after_parseSonySRF;
offset = srf_offset + 2;
tag_offset = offset;
while (entries--) {
if (tiff_sget (save, srf_buf, len,
&tag_offset, &tag_id, &tag_type, &tag_dataoffset,
&tag_datalen, &tag_dataunitlen) == 0) {
if ((tag_id >= 0x00c0) && (tag_id <= 0x00ce)) {
i = (tag_id - 0x00c0) % 3;
nWB = (tag_id - 0x00c0) / 3;
icWBC[Sony_SRF_wb_list[nWB]][i] = sget4(srf_buf + tag_dataoffset);
if (i == 1) {
icWBC[Sony_SRF_wb_list[nWB]][3] =
icWBC[Sony_SRF_wb_list[nWB]][i];
}
} else if ((tag_id >= 0x00d0) && (tag_id <= 0x00d2)) {
i = (tag_id - 0x00d0) % 3;
cam_mul[i] = sget4(srf_buf + tag_dataoffset);
if (i == 1) {
cam_mul[3] = cam_mul[i];
}
} else switch (tag_id) {
case 0x0043:
ilm.MaxAp4MaxFocal = sgetreal(tag_type, srf_buf + tag_dataoffset);
break;
case 0x0044:
ilm.MaxAp4MinFocal = sgetreal(tag_type, srf_buf + tag_dataoffset);
break;
case 0x0045:
ilm.MinFocal = sgetreal(tag_type, srf_buf + tag_dataoffset);
break;
case 0x0046:
ilm.MaxFocal = sgetreal(tag_type, srf_buf + tag_dataoffset);
break;
}
} else goto restore_after_parseSonySRF;
}
offset = tag_offset;
restore_after_parseSonySRF:
free(srf_buf);
fseek(ifp, save, SEEK_SET);
#undef CHECKBUFFER_SGET4
#undef CHECKBUFFER_SGET2
}

static gint
dissect_ac_if_hdr_body(tvbuff_t *tvb, gint offset, packet_info *pinfo _U_,
proto_tree *tree, usb_conv_info_t *usb_conv_info)
{
gint     offset_start;
guint16  bcdADC;
guint8   ver_major;
double   ver;
guint8   if_in_collection, i;
audio_conv_info_t *audio_conv_info;
offset_start = offset;
bcdADC = tvb_get_letohs(tvb, offset);
ver_major = USB_AUDIO_BCD44_TO_DEC(bcdADC>>8);
ver = ver_major + USB_AUDIO_BCD44_TO_DEC(bcdADC&0xFF) / 100.0;
proto_tree_add_double_format_value(tree, hf_ac_if_hdr_ver,
tvb, offset, 2, ver, "%2.2f", ver);
audio_conv_info = (audio_conv_info_t *)usb_conv_info->class_data;
if(!audio_conv_info) {
audio_conv_info = wmem_new(wmem_file_scope(), audio_conv_info_t);
usb_conv_info->class_data = audio_conv_info;
}
audio_conv_info->ver_major = ver_major;
offset += 2;
if (ver_major==1) {
proto_tree_add_item(tree, hf_ac_if_hdr_total_len,
tvb, offset, 2, ENC_LITTLE_ENDIAN);
offset += 2;
if_in_collection = tvb_get_guint8(tvb, offset);
proto_tree_add_item(tree, hf_ac_if_hdr_bInCollection,
tvb, offset, 1, ENC_LITTLE_ENDIAN);
offset++;
for (i=0; i<if_in_collection; i++) {
proto_tree_add_item(tree, hf_ac_if_hdr_if_num,
tvb, offset, 1, ENC_LITTLE_ENDIAN);
offset++;
}
}
return offset-offset_start;
}

static int
PixarLogSetupDecode(TIFF* tif)
{
static const char module[] = "PixarLogSetupDecode";
TIFFDirectory *td = &tif->tif_dir;
PixarLogState* sp = DecoderState(tif);
tmsize_t tbuf_size;
assert(sp != NULL);
tif->tif_postdecode = _TIFFNoPostDecode;  
sp->stride = (td->td_planarconfig == PLANARCONFIG_CONTIG ?
td->td_samplesperpixel : 1);
tbuf_size = multiply_ms(multiply_ms(multiply_ms(sp->stride, td->td_imagewidth),
td->td_rowsperstrip), sizeof(uint16));
tbuf_size = add_ms(tbuf_size, sizeof(uint16) * sp->stride);
if (tbuf_size == 0)
return (0);   
sp->tbuf = (uint16 *) _TIFFmalloc(tbuf_size);
if (sp->tbuf == NULL)
return (0);
if (sp->user_datafmt == PIXARLOGDATAFMT_UNKNOWN)
sp->user_datafmt = PixarLogGuessDataFmt(td);
if (sp->user_datafmt == PIXARLOGDATAFMT_UNKNOWN) {
TIFFErrorExt(tif->tif_clientdata, module,
"PixarLog compression can't handle bits depth/data format combination (depth: %d)", 
td->td_bitspersample);
return (0);
}
if (inflateInit(&sp->stream) != Z_OK) {
TIFFErrorExt(tif->tif_clientdata, module, "%s", sp->stream.msg ? sp->stream.msg : "(null)");
return (0);
} else {
sp->state |= PLSTATE_INIT;
return (1);
}
}

