smb_sdrc_t
smb_com_flush(smb_request_t *sr)
{
smb_ofile_t*file;
smb_llist_t*flist;
intrc;
if (smb_flush_required == 0) {
rc = smbsr_encode_empty_result(sr);
return ((rc == 0) ? SDRC_SUCCESS : SDRC_ERROR);
}
if (sr->smb_fid != 0xffff) {
smbsr_lookup_file(sr);
if (sr->fid_ofile == NULL) {
smbsr_error(sr, NT_STATUS_INVALID_HANDLE,
ERRDOS, ERRbadfid);
return (SDRC_ERROR);
}
smb_flush_file(sr, sr->fid_ofile);
} else {
flist = &sr->tid_tree->t_ofile_list;
smb_llist_enter(flist, RW_READER);
file = smb_llist_head(flist);
while (file) {
mutex_enter(&file->f_mutex);
smb_flush_file(sr, file);
mutex_exit(&file->f_mutex);
file = smb_llist_next(flist, file);
}
smb_llist_exit(flist);
}
rc = smbsr_encode_empty_result(sr);
return ((rc == 0) ? SDRC_SUCCESS : SDRC_ERROR);
}

void SmallVectorTemplateBase<T, isPodLike>::grow(size_t MinSize) {
if (MinSize > UINT32_MAX)
report_bad_alloc_error("SmallVector capacity overflow during allocation");
size_t NewCapacity = size_t(NextPowerOf2(this->capacity() + 2));
NewCapacity = std::min(std::max(NewCapacity, MinSize), size_t(UINT32_MAX));
T *NewElts = static_cast<T*>(llvh::safe_malloc(NewCapacity*sizeof(T)));
this->uninitialized_move(this->begin(), this->end(), NewElts);
destroy_range(this->begin(), this->end());
if (!this->isSmall())
free(this->begin());
this->BeginX = NewElts;
this->Capacity = NewCapacity;
}

size_t mobi_get_attribute_value(char *value, const unsigned char *data, const size_t size, const char *attribute, bool only_quoted) {
if (!data) {
debug_print("Data is null%s", "\n");
return SIZE_MAX;
}
size_t length = size;
size_t attr_length = strlen(attribute);
if (attr_length > MOBI_ATTRNAME_MAXSIZE) {
debug_print("Attribute too long: %zu\n", attr_length);
return SIZE_MAX;
}
char attr[MOBI_ATTRNAME_MAXSIZE + 2];
strcpy(attr, attribute);
strcat(attr, "=");
attr_length++;
if (size < attr_length) {
return SIZE_MAX;
}
unsigned char last_border = '\0';
do {
if (*data == '<' || *data == '>') {
last_border = *data;
}
if (length > attr_length + 1 && memcmp(data, attr, attr_length) == 0) {
size_t offset = size - length;
if (last_border == '>') {
data += attr_length;
length -= attr_length - 1;
continue;
}
if (offset > 0) {
if (data[-1] != '<' && !isspace(data[-1])) {
data += attr_length;
length -= attr_length - 1;
continue;
}
}
data += attr_length;
length -= attr_length;
unsigned char separator;
if (*data != '\'' && *data != '"') {
if (only_quoted) {
continue;
}
separator = ' ';
} else {
separator = *data;
data++;
length--;
}
size_t j;
for (j = 0; j < MOBI_ATTRVALUE_MAXSIZE && length && *data != separator && *data != '>'; j++) {
*value++ = (char) *data++;
length--;
}
if (*(data - 1) == '/' && *data == '>') {
value--;
}
*value = '\0';
return size - length - j;
}
data++;
} while (--length);
value[0] = '\0';
return SIZE_MAX;
}

static int rndis_query_response(USBNetState *s,
rndis_query_msg_type *buf, unsigned int length)
{
rndis_query_cmplt_type *resp;
uint8_t infobuf[sizeof(oid_supported_list)];
uint32_t bufoffs, buflen;
int infobuflen;
unsigned int resplen;
bufoffs = le32_to_cpu(buf->InformationBufferOffset) + 8;
buflen = le32_to_cpu(buf->InformationBufferLength);
if (bufoffs + buflen > length)
return USB_RET_STALL;
infobuflen = ndis_query(s, le32_to_cpu(buf->OID),
bufoffs + (uint8_t *) buf, buflen, infobuf,
sizeof(infobuf));
resplen = sizeof(rndis_query_cmplt_type) +
((infobuflen < 0) ? 0 : infobuflen);
resp = rndis_queue_response(s, resplen);
if (!resp)
return USB_RET_STALL;
resp->MessageType = cpu_to_le32(RNDIS_QUERY_CMPLT);
resp->RequestID = buf->RequestID; 
resp->MessageLength = cpu_to_le32(resplen);
if (infobuflen < 0) {
resp->Status = cpu_to_le32(RNDIS_STATUS_NOT_SUPPORTED);
resp->InformationBufferLength = cpu_to_le32(0);
resp->InformationBufferOffset = cpu_to_le32(0);
return 0;
}
resp->Status = cpu_to_le32(RNDIS_STATUS_SUCCESS);
resp->InformationBufferOffset =
cpu_to_le32(infobuflen ? sizeof(rndis_query_cmplt_type) - 8 : 0);
resp->InformationBufferLength = cpu_to_le32(infobuflen);
memcpy(resp + 1, infobuf, infobuflen);
return 0;
}

