static int hmac_setkey(struct crypto_shash *parent,
const u8 *inkey, unsigned int keylen)
{
int bs = crypto_shash_blocksize(parent);
int ds = crypto_shash_digestsize(parent);
int ss = crypto_shash_statesize(parent);
char *ipad = crypto_shash_ctx_aligned(parent);
char *opad = ipad + ss;
struct hmac_ctx *ctx = align_ptr(opad + ss,
crypto_tfm_ctx_alignment());
struct crypto_shash *hash = ctx->hash;
SHASH_DESC_ON_STACK(shash, hash);
unsigned int i;
shash->tfm = hash;
shash->flags = crypto_shash_get_flags(parent)
& CRYPTO_TFM_REQ_MAY_SLEEP;
if (keylen > bs) {
int err;
err = crypto_shash_digest(shash, inkey, keylen, ipad);
if (err)
return err;
keylen = ds;
} else
memcpy(ipad, inkey, keylen);
memset(ipad + keylen, 0, bs - keylen);
memcpy(opad, ipad, bs);
for (i = 0; i < bs; i++) {
ipad[i] ^= HMAC_IPAD_VALUE;
opad[i] ^= HMAC_OPAD_VALUE;
}
return crypto_shash_init(shash) ?:
crypto_shash_update(shash, ipad, bs) ?:
crypto_shash_export(shash, ipad) ?:
crypto_shash_init(shash) ?:
crypto_shash_update(shash, opad, bs) ?:
crypto_shash_export(shash, opad);
}
static int hmac_export(struct shash_desc *pdesc, void *out)
{
struct shash_desc *desc = shash_desc_ctx(pdesc);
desc->flags = pdesc->flags & CRYPTO_TFM_REQ_MAY_SLEEP;
return crypto_shash_export(desc, out);
}
static int hmac_import(struct shash_desc *pdesc, const void *in)
{
struct shash_desc *desc = shash_desc_ctx(pdesc);
struct hmac_ctx *ctx = hmac_ctx(pdesc->tfm);
desc->tfm = ctx->hash;
desc->flags = pdesc->flags & CRYPTO_TFM_REQ_MAY_SLEEP;
return crypto_shash_import(desc, in);
}
static int hmac_init(struct shash_desc *pdesc)
{
return hmac_import(pdesc, crypto_shash_ctx_aligned(pdesc->tfm));
}
static int hmac_update(struct shash_desc *pdesc,
const u8 *data, unsigned int nbytes)
{
struct shash_desc *desc = shash_desc_ctx(pdesc);
desc->flags = pdesc->flags & CRYPTO_TFM_REQ_MAY_SLEEP;
return crypto_shash_update(desc, data, nbytes);
}
static int hmac_final(struct shash_desc *pdesc, u8 *out)
{
struct crypto_shash *parent = pdesc->tfm;
int ds = crypto_shash_digestsize(parent);
int ss = crypto_shash_statesize(parent);
char *opad = crypto_shash_ctx_aligned(parent) + ss;
struct shash_desc *desc = shash_desc_ctx(pdesc);
desc->flags = pdesc->flags & CRYPTO_TFM_REQ_MAY_SLEEP;
return crypto_shash_final(desc, out) ?:
crypto_shash_import(desc, opad) ?:
crypto_shash_finup(desc, out, ds, out);
}
static int hmac_finup(struct shash_desc *pdesc, const u8 *data,
unsigned int nbytes, u8 *out)
{
struct crypto_shash *parent = pdesc->tfm;
int ds = crypto_shash_digestsize(parent);
int ss = crypto_shash_statesize(parent);
char *opad = crypto_shash_ctx_aligned(parent) + ss;
struct shash_desc *desc = shash_desc_ctx(pdesc);
desc->flags = pdesc->flags & CRYPTO_TFM_REQ_MAY_SLEEP;
return crypto_shash_finup(desc, data, nbytes, out) ?:
crypto_shash_import(desc, opad) ?:
crypto_shash_finup(desc, out, ds, out);
}
static int hmac_init_tfm(struct crypto_tfm *tfm)
{
struct crypto_shash *parent = __crypto_shash_cast(tfm);
struct crypto_shash *hash;
struct crypto_instance *inst = (void *)tfm->__crt_alg;
struct crypto_shash_spawn *spawn = crypto_instance_ctx(inst);
struct hmac_ctx *ctx = hmac_ctx(parent);
hash = crypto_spawn_shash(spawn);
if (IS_ERR(hash))
return PTR_ERR(hash);
parent->descsize = sizeof(struct shash_desc) +
crypto_shash_descsize(hash);
ctx->hash = hash;
return 0;
}
static void hmac_exit_tfm(struct crypto_tfm *tfm)
{
struct hmac_ctx *ctx = hmac_ctx(__crypto_shash_cast(tfm));
crypto_free_shash(ctx->hash);
}
static int hmac_create(struct crypto_template *tmpl, struct rtattr **tb)
{
struct shash_instance *inst;
struct crypto_alg *alg;
struct shash_alg *salg;
int err;
int ds;
int ss;
err = crypto_check_attr_type(tb, CRYPTO_ALG_TYPE_SHASH);
if (err)
return err;
salg = shash_attr_alg(tb[1], 0, 0);
if (IS_ERR(salg))
return PTR_ERR(salg);
err = -EINVAL;
ds = salg->digestsize;
ss = salg->statesize;
alg = &salg->base;
if (ds > alg->cra_blocksize ||
ss < alg->cra_blocksize)
goto out_put_alg;
inst = shash_alloc_instance("hmac", alg);
err = PTR_ERR(inst);
if (IS_ERR(inst))
goto out_put_alg;
err = crypto_init_shash_spawn(shash_instance_ctx(inst), salg,
shash_crypto_instance(inst));
if (err)
goto out_free_inst;
inst->alg.base.cra_priority = alg->cra_priority;
inst->alg.base.cra_blocksize = alg->cra_blocksize;
inst->alg.base.cra_alignmask = alg->cra_alignmask;
ss = ALIGN(ss, alg->cra_alignmask + 1);
inst->alg.digestsize = ds;
inst->alg.statesize = ss;
inst->alg.base.cra_ctxsize = sizeof(struct hmac_ctx) +
ALIGN(ss * 2, crypto_tfm_ctx_alignment());
inst->alg.base.cra_init = hmac_init_tfm;
inst->alg.base.cra_exit = hmac_exit_tfm;
inst->alg.init = hmac_init;
inst->alg.update = hmac_update;
inst->alg.final = hmac_final;
inst->alg.finup = hmac_finup;
inst->alg.export = hmac_export;
inst->alg.import = hmac_import;
inst->alg.setkey = hmac_setkey;
err = shash_register_instance(tmpl, inst);
if (err) {
out_free_inst:
shash_free_instance(shash_crypto_instance(inst));
}
out_put_alg:
crypto_mod_put(alg);
return err;
}
static struct crypto_template hmac_tmpl = {
.name = "hmac",
.create = hmac_create,
.free = shash_free_instance,
.module = THIS_MODULE,
};
static int __init hmac_module_init(void)
{
return crypto_register_template(&hmac_tmpl);
}
static void __exit hmac_module_exit(void)
{
crypto_unregister_template(&hmac_tmpl);
}
module_init(hmac_module_init);
module_exit(hmac_module_exit);
MODULE_LICENSE("GPL");
MODULE_DESCRIPTION("HMAC hash algorithm");
MODULE_ALIAS_CRYPTO("hmac");

static GF_Err swf_def_font(SWFReader *read, u32 revision)
{
u32 i, count;
GF_Err e;
SWFFont *ft;
u32 *offset_table = NULL;
u32 start;
GF_SAFEALLOC(ft, SWFFont);
if (!ft) return GF_OUT_OF_MEM;
ft->glyphs = gf_list_new();
ft->fontID = swf_get_16(read);
e = GF_OK;
gf_list_add(read->fonts, ft);
if (revision==0) {
start = swf_get_file_pos(read);
count = swf_get_16(read);
ft->nbGlyphs = count / 2;
offset_table = (u32*)gf_malloc(sizeof(u32) * ft->nbGlyphs);
offset_table[0] = 0;
for (i=1; i<ft->nbGlyphs; i++) offset_table[i] = swf_get_16(read);
for (i=0; i<ft->nbGlyphs; i++) {
swf_align(read);
e = swf_seek_file_to(read, start + offset_table[i]);
if (e) break;
swf_parse_shape_def(read, ft, 0);
}
gf_free(offset_table);
if (e) return e;
} else if (revision==1) {
SWFRec rc;
Bool wide_offset, wide_codes;
u32 code_offset, checkpos;
ft->has_layout = swf_read_int(read, 1);
ft->has_shiftJIS = swf_read_int(read, 1);
ft->is_unicode = swf_read_int(read, 1);
ft->is_ansi = swf_read_int(read, 1);
wide_offset = swf_read_int(read, 1);
wide_codes = swf_read_int(read, 1);
ft->is_italic = swf_read_int(read, 1);
ft->is_bold = swf_read_int(read, 1);
swf_read_int(read, 8);
count = swf_read_int(read, 8);
ft->fontName = (char*)gf_malloc(sizeof(u8)*count+1);
ft->fontName[count] = 0;
for (i=0; i<count; i++) ft->fontName[i] = swf_read_int(read, 8);
ft->nbGlyphs = swf_get_16(read);
start = swf_get_file_pos(read);
if (ft->nbGlyphs) {
offset_table = (u32*)gf_malloc(sizeof(u32) * ft->nbGlyphs);
for (i=0; i<ft->nbGlyphs; i++) {
if (wide_offset) offset_table[i] = swf_get_32(read);
else offset_table[i] = swf_get_16(read);
}
}
if (wide_offset) {
code_offset = swf_get_32(read);
} else {
code_offset = swf_get_16(read);
}
if (ft->nbGlyphs) {
for (i=0; i<ft->nbGlyphs; i++) {
swf_align(read);
e = swf_seek_file_to(read, start + offset_table[i]);
if (e) break;
swf_parse_shape_def(read, ft, 0);
}
gf_free(offset_table);
if (e) return e;
checkpos = swf_get_file_pos(read);
if (checkpos != start + code_offset) {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[SWF Parsing] bad code offset in font\n"));
return GF_NON_COMPLIANT_BITSTREAM;
}
ft->glyph_codes = (u16*)gf_malloc(sizeof(u16) * ft->nbGlyphs);
for (i=0; i<ft->nbGlyphs; i++) {
if (wide_codes) ft->glyph_codes[i] = swf_get_16(read);
else ft->glyph_codes[i] = swf_read_int(read, 8);
}
}
if (ft->has_layout) {
ft->ascent = swf_get_s16(read);
ft->descent = swf_get_s16(read);
ft->leading = swf_get_s16(read);
if (ft->nbGlyphs) {
ft->glyph_adv = (s16*)gf_malloc(sizeof(s16) * ft->nbGlyphs);
for (i=0; i<ft->nbGlyphs; i++) ft->glyph_adv[i] = swf_get_s16(read);
for (i=0; i<ft->nbGlyphs; i++) swf_get_rec(read, &rc);
}
count = swf_get_16(read);
for (i=0; i<count; i++) {
if (wide_codes) {
swf_get_16(read);
swf_get_16(read);
} else {
swf_read_int(read, 8);
swf_read_int(read, 8);
}
swf_get_s16(read);
}
}
}
return GF_OK;
}

static cairo_path_t *
_rsvg_node_poly_build_path (const char *value,
gboolean close_path)
{
double *pointlist;
guint pointlist_len, i;
GString *d;
cairo_path_t *path;
char buf[G_ASCII_DTOSTR_BUF_SIZE];
pointlist = rsvg_css_parse_number_list (value, &pointlist_len);
if (pointlist == NULL)
return NULL;
if (pointlist_len < 2) {
g_free (pointlist);
return NULL;
}
d = g_string_new (NULL);
g_string_append (d, " M ");
g_string_append (d, g_ascii_dtostr (buf, sizeof (buf), pointlist[0]));
g_string_append_c (d, ' ');
g_string_append (d, g_ascii_dtostr (buf, sizeof (buf), pointlist[1]));
for (i = 2; i < pointlist_len; i += 2) {
g_string_append (d, " L ");
g_string_append (d, g_ascii_dtostr (buf, sizeof (buf), pointlist[i]));
g_string_append_c (d, ' ');
g_string_append (d, g_ascii_dtostr (buf, sizeof (buf), pointlist[i + 1]));
}
if (close_path)
g_string_append (d, " Z");
path = rsvg_parse_path (d->str);
g_string_free (d, TRUE);
g_free (pointlist);
return path;
}

MOBI_RET mobi_search_links_kf7(MOBIResult *result, const unsigned char *data_start, const unsigned char *data_end) {
if (!result) {
debug_print("Result structure is null%s", "\n");
return MOBI_PARAM_ERR;
}
result->start = result->end = NULL;
*(result->value) = '\0';
if (!data_start || !data_end) {
debug_print("Data is null%s", "\n");
return MOBI_PARAM_ERR;
}
const char *needle1 = "filepos=";
const char *needle2 = "recindex=";
const size_t needle1_length = strlen(needle1);
const size_t needle2_length = strlen(needle2);
const size_t needle_length = max(needle1_length,needle2_length);
if (data_start + needle_length > data_end) {
return MOBI_SUCCESS;
}
unsigned char *data = (unsigned char *) data_start;
const unsigned char tag_open = '<';
const unsigned char tag_close = '>';
unsigned char last_border = tag_open;
while (data <= data_end) {
if (*data == tag_open || *data == tag_close) {
last_border = *data;
}
if (data + needle_length <= data_end &&
(memcmp(data, needle1, needle1_length) == 0 ||
memcmp(data, needle2, needle2_length) == 0)) {
if (last_border != tag_open) {
data += needle_length;
continue;
}
while (data >= data_start && !isspace(*data) && *data != tag_open) {
data--;
}
result->start = ++data;
int i = 0;
while (data <= data_end && !isspace(*data) && *data != tag_close && i < MOBI_ATTRVALUE_MAXSIZE) {
result->value[i++] = (char) *data++;
}
if (*(data - 1) == '/' && *data == '>') {
--data; --i;
}
result->end = data;
result->value[i] = '\0';
return MOBI_SUCCESS;
}
data++;
}
return MOBI_SUCCESS;
}

TEE_Result syscall_hash_init(unsigned long state,
const void *iv __maybe_unused,
size_t iv_len __maybe_unused)
{
TEE_Result res;
struct tee_cryp_state *cs;
struct tee_ta_session *sess;
res = tee_ta_get_current_session(&sess);
if (res != TEE_SUCCESS)
return res;
res = tee_svc_cryp_get_state(sess, tee_svc_uref_to_vaddr(state), &cs);
if (res != TEE_SUCCESS)
return res;
switch (TEE_ALG_GET_CLASS(cs->algo)) {
case TEE_OPERATION_DIGEST:
res = crypto_hash_init(cs->ctx, cs->algo);
if (res != TEE_SUCCESS)
return res;
break;
case TEE_OPERATION_MAC:
{
struct tee_obj *o;
struct tee_cryp_obj_secret *key;
res = tee_obj_get(to_user_ta_ctx(sess->ctx),
cs->key1, &o);
if (res != TEE_SUCCESS)
return res;
if ((o->info.handleFlags &
TEE_HANDLE_FLAG_INITIALIZED) == 0)
return TEE_ERROR_BAD_PARAMETERS;
key = (struct tee_cryp_obj_secret *)o->attr;
res = crypto_mac_init(cs->ctx, cs->algo,
(void *)(key + 1), key->key_size);
if (res != TEE_SUCCESS)
return res;
break;
}
default:
return TEE_ERROR_BAD_PARAMETERS;
}
return TEE_SUCCESS;
}

