int ndlz4_decompress(const uint8_t *input, int32_t input_len, uint8_t *output, int32_t output_len,
uint8_t meta, blosc2_dparams *dparams) {
BLOSC_UNUSED_PARAM(meta);
BLOSC_UNUSED_PARAM(dparams);
uint8_t *ip = (uint8_t *) input;
uint8_t *ip_limit = ip + input_len;
uint8_t *op = (uint8_t *) output;
uint8_t ndim;
uint32_t blockshape[2];
uint32_t eshape[2];
uint8_t *buffercpy;
uint8_t local_buffer[16];
uint8_t token;
if (NDLZ_UNEXPECT_CONDITIONAL(input_len < 8)) {
return 0;
}
ndim = *ip;
ip++;
if (ndim != 2) {
BLOSC_TRACE_ERROR("This codec only works for ndim = 2");
return BLOSC2_ERROR_FAILURE;
}
memcpy(&blockshape[0], ip, 4);
ip += 4;
memcpy(&blockshape[1], ip, 4);
ip += 4;
eshape[0] = ((blockshape[0] + 3) / 4) * 4;
eshape[1] = ((blockshape[1] + 3) / 4) * 4;
if (NDLZ_UNEXPECT_CONDITIONAL(output_len < (int32_t) (blockshape[0] * blockshape[1]))) {
return 0;
}
memset(op, 0, blockshape[0] * blockshape[1]);
uint32_t i_stop[2];
for (int i = 0; i < 2; ++i) {
i_stop[i] = eshape[i] / 4;
}
uint32_t ii[2];
uint32_t padding[2] = {0};
uint32_t ind = 0;
uint8_t cell_aux[16];
for (ii[0] = 0; ii[0] < i_stop[0]; ++ii[0]) {
for (ii[1] = 0; ii[1] < i_stop[1]; ++ii[1]) {            if (NDLZ_UNEXPECT_CONDITIONAL(ip > ip_limit)) {
BLOSC_TRACE_ERROR("Exceeding input length");
return BLOSC2_ERROR_FAILURE;
}
if (ii[0] == i_stop[0] - 1) {
padding[0] = (blockshape[0] % 4 == 0) ? 4 : blockshape[0] % 4;
} else {
padding[0] = 4;
}
if (ii[1] == i_stop[1] - 1) {
padding[1] = (blockshape[1] % 4 == 0) ? 4 : blockshape[1] % 4;
} else {
padding[1] = 4;
}
token = *ip++;
if (token == 0) {            buffercpy = ip;
ip += padding[0] * padding[1];
} else if (token == (uint8_t) ((1U << 7U) | (1U << 6U))) {          uint16_t offset = *((uint16_t *) ip);
buffercpy = ip - offset - 1;
ip += 2;
} else if (token == (uint8_t) (1U << 6U)) {         buffercpy = cell_aux;
memset(buffercpy, *ip, 16);
ip++;
} else if (token >= 224) {         buffercpy = local_buffer;
uint16_t offset = *((uint16_t *) ip);
offset += 3;
ip += 2;
int i, j, k;
if ((token >> 3U) == 28) {
i = 1;
j = 2;
k = 3;
} else {
i = 0;
if ((token >> 3U) < 30) {
j = 1;
k = 2;
} else {
k = 3;
if ((token >> 3U) == 30) {
j = 1;
} else {
j = 2;
}
}
}
memcpy(&buffercpy[i * 4], ip - offset, 4);
memcpy(&buffercpy[j * 4], ip - offset + 4, 4);
memcpy(&buffercpy[k * 4], ip - offset + 8, 4);
for (int l = 0; l < 4; l++) {
if ((l != i) && (l != j) && (l != k)) {
memcpy(&buffercpy[l * 4], ip, 4);
ip += 4;
break;
}
}
} else if ((token >= 128) && (token <= 191)) {         buffercpy = local_buffer;
uint16_t offset = *((uint16_t *) ip);
offset += 3;
ip += 2;
int i, j;
if (token == 128) {
i = 2;
j = 3;
} else {
i = (token - 128) >> 5U;
j = ((token - 128) >> 3U) - (i << 2U);
}
memcpy(&buffercpy[i * 4], ip - offset, 4);
memcpy(&buffercpy[j * 4], ip - offset + 4, 4);
for (int k = 0; k < 4; k++) {
if ((k != i) && (k != j)) {
memcpy(&buffercpy[k * 4], ip, 4);
ip += 4;
}
}
} else if ((token >= 40) && (token <= 63)) {          buffercpy = local_buffer;
uint16_t offset_1 = *((uint16_t *) ip);
offset_1 += 5;
ip += 2;
uint16_t offset_2 = *((uint16_t *) ip);
offset_2 += 5;
ip += 2;
int i, j, k, l, m;
i = 0;
j = ((token - 32) >> 3U);
l = -1;
for (k = 1; k < 4; k++) {
if ((k != i) && (k != j)) {
if (l == -1) {
l = k;
} else {
m = k;
}
}
}
memcpy(&buffercpy[i * 4], ip - offset_1, 4);
memcpy(&buffercpy[j * 4], ip - offset_1 + 4, 4);
memcpy(&buffercpy[l * 4], ip - offset_2, 4);
memcpy(&buffercpy[m * 4], ip - offset_2 + 4, 4);
} else {
BLOSC_TRACE_ERROR("Invalid token: %u at cell [%d, %d]\n", token, ii[0], ii[1]);
return BLOSC2_ERROR_FAILURE;
}
uint32_t orig = ii[0] * 4 * blockshape[1] + ii[1] * 4;
for (uint32_t i = 0; i < 4; i++) {
if (i < padding[0]) {
ind = orig + i * blockshape[1];
memcpy(&op[ind], buffercpy, padding[1]);
}
buffercpy += padding[1];
}
if (ind > (uint32_t) output_len) {
BLOSC_TRACE_ERROR("Exceeding output size");
return BLOSC2_ERROR_FAILURE;
}
}
}
ind += padding[1];
if (ind != (blockshape[0] * blockshape[1])) {
BLOSC_TRACE_ERROR("Output size is not compatible with embedded blockshape");
return BLOSC2_ERROR_FAILURE;
}
if (ind > (uint32_t) output_len) {
BLOSC_TRACE_ERROR("Exceeding output size");
return BLOSC2_ERROR_FAILURE;
}
return (int) ind;
}

void PackTmt::pack(OutputFile *fo) {
big_relocs = 0;
Packer::handleStub(fi, fo, adam_offset);
const unsigned usize = ih.imagesize;
const unsigned rsize = ih.relocsize;
ibuf.alloc(usize + rsize + 128);
obuf.allocForCompression(usize + rsize + 128);
MemBuffer mb_wrkmem;
mb_wrkmem.alloc(rsize + EXTRA_INFO);     SPAN_S_VAR(upx_byte, wrkmem, mb_wrkmem);
fi->seek(adam_offset + sizeof(ih), SEEK_SET);
fi->readx(ibuf, usize);
fi->readx(wrkmem + 4, rsize);
const unsigned overlay = file_size - fi->tell();
if (find_le32(ibuf, 128, get_le32("UPX ")) >= 0)
throwAlreadyPacked();
if (rsize == 0)
throwCantPack("file is already compressed with another packer");
checkOverlay(overlay);
unsigned relocsize = 0;
{
for (unsigned ic = 4; ic <= rsize; ic += 4)
set_le32(wrkmem + ic, get_le32(wrkmem + ic) - 4);
relocsize =
optimizeReloc32(wrkmem + 4, rsize / 4, wrkmem, ibuf, file_size, true, &big_relocs);
}
wrkmem[relocsize++] = 0;
set_le32(wrkmem + relocsize, ih.entry);     relocsize += 4;
set_le32(wrkmem + relocsize, relocsize + 4);
relocsize += 4;
memcpy(ibuf + usize, wrkmem, relocsize);
ph.u_len = usize + relocsize;
Filter ft(ph.level);
ft.buf_len = usize;
upx_compress_config_t cconf;
cconf.reset();
cconf.conf_lzma.max_num_probs = 1846 + (768 << 4);     compressWithFilters(&ft, 512, &cconf);
const unsigned lsize = getLoaderSize();
const unsigned s_point = getLoaderSection("TMTMAIN1");
int e_len = getLoaderSectionStart("TMTCUTPO");
const unsigned d_len = lsize - e_len;
assert(e_len > 0 && s_point > 0);
linker->defineSymbol("original_entry", ih.entry);
defineDecompressorSymbols();
defineFilterSymbols(&ft);
linker->defineSymbol("bytes_to_copy", ph.c_len + d_len);
linker->defineSymbol("copy_dest", 0u - (ph.u_len + ph.overlap_overhead + d_len - 1));
linker->defineSymbol("copy_source", ph.c_len + lsize - 1);
linker->defineSymbol("TMTCUTPO", ph.u_len + ph.overlap_overhead);
relocateLoader();
MemBuffer loader(lsize);
memcpy(loader, getLoader(), lsize);
patchPackHeader(loader, e_len);
memcpy(&oh, &ih, sizeof(oh));
oh.imagesize = ph.c_len + lsize;     oh.entry = s_point;                  oh.relocsize = 4;
fo->write(&oh, sizeof(oh));
fo->write(loader, e_len);
fo->write(obuf, ph.c_len);
fo->write(loader + lsize - d_len, d_len);     char rel_entry[4];
set_le32(rel_entry, 5 + s_point);
fo->write(rel_entry, sizeof(rel_entry));
verifyOverlappingDecompression();
copyOverlay(fo, overlay, obuf);
if (!checkFinalCompressionRatio(fo))
throwNotCompressible();
}

static const char *parse_string(cJSON *item,const char *str,const char **ep)
{
const char *ptr=str+1,*end_ptr=str+1;char *ptr2;char *out;int len=0;unsigned uc,uc2;
if (*str!='\"') {*ep=str;return 0;}
while (*end_ptr!='\"' && *end_ptr && ++len) if (*end_ptr++ == '\\') end_ptr++;
out=(char*)cJSON_malloc(len+1);
if (!out) return 0;
item->valuestring=out; 
item->type=cJSON_String;
ptr=str+1;ptr2=out;
while (ptr < end_ptr)
{
if (*ptr!='\\') *ptr2++=*ptr++;
else
{
ptr++;
switch (*ptr)
{
case 'b': *ptr2++='\b';break;
case 'f': *ptr2++='\f';break;
case 'n': *ptr2++='\n';break;
case 'r': *ptr2++='\r';break;
case 't': *ptr2++='\t';break;
case 'u': 
uc=parse_hex4(ptr+1);ptr+=4;
if (ptr >= end_ptr) {*ep=str;return 0;}
if ((uc>=0xDC00 && uc<=0xDFFF) || uc==0)    {*ep=str;return 0;}
if (uc>=0xD800 && uc<=0xDBFF)
{
if (ptr+6 > end_ptr)    {*ep=str;return 0;}
if (ptr[1]!='\\' || ptr[2]!='u')    {*ep=str;return 0;}
uc2=parse_hex4(ptr+3);ptr+=6;
if (uc2<0xDC00 || uc2>0xDFFF)       {*ep=str;return 0;}
uc=0x10000 + (((uc&0x3FF)<<10) | (uc2&0x3FF));
}
len=4;if (uc<0x80) len=1;else if (uc<0x800) len=2;else if (uc<0x10000) len=3; ptr2+=len;
switch (len) {
case 4: *--ptr2 =((uc | 0x80) & 0xBF); uc >>= 6;
case 3: *--ptr2 =((uc | 0x80) & 0xBF); uc >>= 6;
case 2: *--ptr2 =((uc | 0x80) & 0xBF); uc >>= 6;
case 1: *--ptr2 =(uc | firstByteMark[len]);
}
ptr2+=len;
break;
default:  *ptr2++=*ptr; break;
}
ptr++;
}
}
*ptr2=0;
if (*ptr=='\"') ptr++;
return ptr;
}

void context__cleanup(struct mosquitto *context, bool force_free)
{
struct mosquitto__packet *packet;
if(!context) return;
if(force_free){
context->clean_start = true;
}
#ifdef WITH_BRIDGE
if(context->bridge){
bridge__cleanup(context);
}
#endif
alias__free_all(context);
mosquitto__free(context->auth_method);
context->auth_method = NULL;
mosquitto__free(context->username);
context->username = NULL;
mosquitto__free(context->password);
context->password = NULL;
net__socket_close(context);
if(force_free){
sub__clean_session(context);
}
db__messages_delete(context, force_free);
mosquitto__free(context->address);
context->address = NULL;
context__send_will(context);
if(context->id){
context__remove_from_by_id(context);
mosquitto__free(context->id);
context->id = NULL;
}
packet__cleanup(&(context->in_packet));
if(context->current_out_packet){
packet__cleanup(context->current_out_packet);
mosquitto__free(context->current_out_packet);
context->current_out_packet = NULL;
}
while(context->out_packet){
packet__cleanup(context->out_packet);
packet = context->out_packet;
context->out_packet = context->out_packet->next;
mosquitto__free(packet);
}
context->out_packet_count = 0;
#if defined(WITH_BROKER) && defined(__GLIBC__) && defined(WITH_ADNS)
if(context->adns){
gai_cancel(context->adns);
mosquitto__free((struct addrinfo *)context->adns->ar_request);
mosquitto__free(context->adns);
}
#endif
if(force_free){
mosquitto__free(context);
}
}

static int rtnl_dump_ifinfo(struct sk_buff *skb, struct netlink_callback *cb)
{
struct net *net = sock_net(skb->sk);
struct net *tgt_net = net;
int h, s_h;
int idx = 0, s_idx;
struct net_device *dev;
struct hlist_head *head;
struct nlattr *tb[IFLA_MAX+1];
u32 ext_filter_mask = 0;
const struct rtnl_link_ops *kind_ops = NULL;
unsigned int flags = NLM_F_MULTI;
int master_idx = 0;
int netnsid = -1;
int err;
int hdrlen;
s_h = cb->args[0];
s_idx = cb->args[1];
hdrlen = nlmsg_len(cb->nlh) < sizeof(struct ifinfomsg) ?
sizeof(struct rtgenmsg) : sizeof(struct ifinfomsg);
if (nlmsg_parse(cb->nlh, hdrlen, tb, IFLA_MAX,
ifla_policy, NULL) >= 0) {
if (tb[IFLA_IF_NETNSID]) {
netnsid = nla_get_s32(tb[IFLA_IF_NETNSID]);
tgt_net = get_target_net(skb, netnsid);
if (IS_ERR(tgt_net)) {
tgt_net = net;
netnsid = -1;
}
}
if (tb[IFLA_EXT_MASK])
ext_filter_mask = nla_get_u32(tb[IFLA_EXT_MASK]);
if (tb[IFLA_MASTER])
master_idx = nla_get_u32(tb[IFLA_MASTER]);
if (tb[IFLA_LINKINFO])
kind_ops = linkinfo_to_kind_ops(tb[IFLA_LINKINFO]);
if (master_idx || kind_ops)
flags |= NLM_F_DUMP_FILTERED;
}
for (h = s_h; h < NETDEV_HASHENTRIES; h++, s_idx = 0) {
idx = 0;
head = &tgt_net->dev_index_head[h];
hlist_for_each_entry(dev, head, index_hlist) {
if (link_dump_filtered(dev, master_idx, kind_ops))
goto cont;
if (idx < s_idx)
goto cont;
err = rtnl_fill_ifinfo(skb, dev, net,
RTM_NEWLINK,
NETLINK_CB(cb->skb).portid,
cb->nlh->nlmsg_seq, 0,
flags,
ext_filter_mask, 0, NULL,
netnsid);
if (err < 0) {
if (likely(skb->len))
goto out;
goto out_err;
}
cont:
idx++;
}
}
out:
err = skb->len;
out_err:
cb->args[1] = idx;
cb->args[0] = h;
cb->seq = net->dev_base_seq;
nl_dump_check_consistent(cb, nlmsg_hdr(skb));
if (netnsid >= 0)
put_net(tgt_net);
return err;
}

static struct page_info *get_free_buddy(unsigned int zone_lo,
unsigned int zone_hi,
unsigned int order, unsigned int memflags,
const struct domain *d)
{
nodeid_t first_node, node = MEMF_get_node(memflags), req_node = node;
nodemask_t nodemask = d ? d->node_affinity : node_online_map;
unsigned int j, zone, nodemask_retry = 0;
struct page_info *pg;
bool use_unscrubbed = (memflags & MEMF_no_scrub);
if ( node == NUMA_NO_NODE )
{
if ( d != NULL )
{
node = next_node(d->last_alloc_node, nodemask);
if ( node >= MAX_NUMNODES )
node = first_node(nodemask);
}
if ( node >= MAX_NUMNODES )
node = cpu_to_node(smp_processor_id());
}
first_node = node;
ASSERT(node < MAX_NUMNODES);
for ( ; ; )
{
zone = zone_hi;
do {
if ( !avail[node] || (avail[node][zone] < (1UL << order)) )
continue;
for ( j = order; j <= MAX_ORDER; j++ )
{
if ( (pg = page_list_remove_head(&heap(node, zone, j))) )
{
if ( pg->u.free.first_dirty == INVALID_DIRTY_IDX )
return pg;
if ( (order == 0) || use_unscrubbed )
{
check_and_stop_scrub(pg);
return pg;
}
page_list_add_tail(pg, &heap(node, zone, j));
}
}
} while ( zone-- > zone_lo ); 
if ( (memflags & MEMF_exact_node) && req_node != NUMA_NO_NODE )
return NULL;
if ( !node_isset(node, nodemask) )
{
ASSERT(!nodemask_retry);
first_node = node = first_node(nodemask);
if ( node < MAX_NUMNODES )
continue;
}
else if ( (node = next_node(node, nodemask)) >= MAX_NUMNODES )
node = first_node(nodemask);
if ( node == first_node )
{
if ( (memflags & MEMF_exact_node) || nodemask_retry++ )
return NULL;
nodes_andnot(nodemask, node_online_map, nodemask);
first_node = node = first_node(nodemask);
if ( node >= MAX_NUMNODES )
return NULL;
}
}
}

