static av_cold int rl2_read_header(AVFormatContext *s)
{
AVIOContext *pb = s->pb;
AVStream *st;
unsigned int frame_count;
unsigned int audio_frame_counter = 0;
unsigned int video_frame_counter = 0;
unsigned int back_size;
unsigned short sound_rate;
unsigned short rate;
unsigned short channels;
unsigned short def_sound_size;
unsigned int signature;
unsigned int pts_den = 11025; 
unsigned int pts_num = 1103;
unsigned int* chunk_offset = NULL;
int* chunk_size = NULL;
int* audio_size = NULL;
int i;
int ret = 0;
avio_skip(pb,4);          
back_size = avio_rl32(pb); 
signature = avio_rb32(pb);
avio_skip(pb, 4);         
frame_count = avio_rl32(pb);
if(back_size > INT_MAX/2  || frame_count > INT_MAX / sizeof(uint32_t))
return AVERROR_INVALIDDATA;
avio_skip(pb, 2);         
sound_rate = avio_rl16(pb);
rate = avio_rl16(pb);
channels = avio_rl16(pb);
def_sound_size = avio_rl16(pb);
st = avformat_new_stream(s, NULL);
if(!st)
return AVERROR(ENOMEM);
st->codecpar->codec_type = AVMEDIA_TYPE_VIDEO;
st->codecpar->codec_id = AV_CODEC_ID_RL2;
st->codecpar->codec_tag = 0;  
st->codecpar->width = 320;
st->codecpar->height = 200;
st->codecpar->extradata_size = EXTRADATA1_SIZE;
if(signature == RLV3_TAG && back_size > 0)
st->codecpar->extradata_size += back_size;
if(ff_get_extradata(s, st->codecpar, pb, st->codecpar->extradata_size) < 0)
return AVERROR(ENOMEM);
if(sound_rate){
if (!channels || channels > 42) {
av_log(s, AV_LOG_ERROR, "Invalid number of channels: %d\n", channels);
return AVERROR_INVALIDDATA;
}
pts_num = def_sound_size;
pts_den = rate;
st = avformat_new_stream(s, NULL);
if (!st)
return AVERROR(ENOMEM);
st->codecpar->codec_type = AVMEDIA_TYPE_AUDIO;
st->codecpar->codec_id = AV_CODEC_ID_PCM_U8;
st->codecpar->codec_tag = 1;
st->codecpar->channels = channels;
st->codecpar->bits_per_coded_sample = 8;
st->codecpar->sample_rate = rate;
st->codecpar->bit_rate = st->codecpar->channels * st->codecpar->sample_rate *
st->codecpar->bits_per_coded_sample;
st->codecpar->block_align = st->codecpar->channels *
st->codecpar->bits_per_coded_sample / 8;
avpriv_set_pts_info(st,32,1,rate);
}
avpriv_set_pts_info(s->streams[0], 32, pts_num, pts_den);
chunk_size =   av_malloc(frame_count * sizeof(uint32_t));
audio_size =   av_malloc(frame_count * sizeof(uint32_t));
chunk_offset = av_malloc(frame_count * sizeof(uint32_t));
if(!chunk_size || !audio_size || !chunk_offset){
av_free(chunk_size);
av_free(audio_size);
av_free(chunk_offset);
return AVERROR(ENOMEM);
}
for(i=0; i < frame_count;i++)
chunk_size[i] = avio_rl32(pb);
for(i=0; i < frame_count;i++)
chunk_offset[i] = avio_rl32(pb);
for(i=0; i < frame_count;i++)
audio_size[i] = avio_rl32(pb) & 0xFFFF;
for(i=0;i<frame_count;i++){
if(chunk_size[i] < 0 || audio_size[i] > chunk_size[i]){
ret = AVERROR_INVALIDDATA;
break;
}
if(sound_rate && audio_size[i]){
av_add_index_entry(s->streams[1], chunk_offset[i],
audio_frame_counter,audio_size[i], 0, AVINDEX_KEYFRAME);
audio_frame_counter += audio_size[i] / channels;
}
av_add_index_entry(s->streams[0], chunk_offset[i] + audio_size[i],
video_frame_counter,chunk_size[i]-audio_size[i],0,AVINDEX_KEYFRAME);
++video_frame_counter;
}
av_free(chunk_size);
av_free(audio_size);
av_free(chunk_offset);
return ret;
}

void frontend(unsigned char *s,
int ftype,
char *fname,
int linenum)
{
unsigned char *p, *q, c, *begin_end, sep;
int i, l, str_cnv_p, histo, end_len;
char prefix_sav[4];
int latin_sav = 0;
begin_end = NULL;
end_len = 0;
histo = 0;
if (ftype == FE_ABC
&& strncmp((char *) s, "%abc-", 5) == 0) {
get_vers((char *) s + 5);
while (*s != '\0'
&& *s != '\r'
&& *s != '\n')
s++;
if (*s != '\0') {
s++;
if (s[-1] == '\r' && *s == '\n')
s++;
}
linenum++;
}
if (ftype == FE_ABC
&& parse.abc_vers >= ((2 << 16) | (1 << 8))) {latin = 0;} else {
for (p = s; *p != '\0'; p++) {
c = *p;
if (c == '\\') {
if (!isdigit(p[1]))
continue;
if ((p[1] == '0' || p[1] == '2')
&& p[2] == '0')
continue;
latin = 1;
break;
}
if (c < 0x80)
continue;
if (c >= 0xc2) {
if ((p[1] & 0xc0) == 0x80) {
latin = 0;
break;
}
}
latin = 1;
break;
}
}
latin_sav = latin;
skip = 0;
while (*s != '\0') {
str_cnv_p = 0;
p = s;
while (*p != '\0'
&& *p != '\r'
&& *p != '\n') {
if (*p == '\\'
|| *p == '%'
|| (latin > 0 && *p >= 0x80))
str_cnv_p = 1;
p++;
}
l = p - s;
if (*p != '\0') {
p++;
if (p[-1] == '\r' && *p == '\n')
p++;
}
linenum++;
if (skip) {
if (l != 0)
goto ignore;
skip = 0;
}
if (begin_end) {
if (ftype == FE_FMT) {
if (strncmp((char *) s, "end", 3) == 0
&& strncmp((char *) s + 3,
(char *) begin_end, end_len) == 0) {
begin_end = NULL;
goto next_eol;
}
if (*s == '%')
goto ignore;
goto next;
}
if (*s == '%' && strchr(prefix, s[1])) {
q = s + 2;
while (*q == ' ' || *q == '\t')
q++;
if (strncmp((char *) q, "end", 3) == 0
&& strncmp((char *) q + 3,
(char *) begin_end, end_len) == 0) {
begin_end = NULL;
goto next_eol;
}
}
if (strncmp("ps", (char *) begin_end, end_len) == 0) {
if (*s == '%')
goto ignore;
} else {
if (*s == '%' && strchr(prefix, s[1])) {
s += 2;
l -= 2;
}
}
goto next;
}
while (l > 0 && isspace(s[l - 1]))
l--;
if (l == 0) {
if (ftype == FE_FMT)
goto next_eol;
switch (state) {
default:
goto ignore;
case 1:
fprintf(stderr,
"Line %d: Empty line in tune header - K:C added\n",
linenum);
txt_add((unsigned char *) "K:C", 3);
txt_add_eos(fname, linenum);
case 2:
state = 0;
strcpy(prefix, prefix_sav);
latin = latin_sav;
break;
}
goto next_eol;
}
if (histo) {
if ((s[1] == ':' && isalpha(*s))
|| (*s == '%' && strchr(prefix, s[1]))) {
histo = 0;
} else {
if (*s != '+' || s[1] != ':')
txt_add((unsigned char *) "+:", 2);
goto next;
}
}
if (*s == ' ' || *s == '\t') {
q = s;
do {
q++;
} while (*q == ' ' || *q == '\t');
if (*q == '%')
goto ignore;
}
if (ftype == FE_PS) {
if (*s == '%')
goto ignore;
goto next;
}
if (ftype == FE_FMT) {
if (*s == '%')
goto ignore;
goto pscom;
}
if (*s == 'I' && s[1] == ':') {
s += 2;
l -= 2;
while (*s == ' ' || *s == '\t') {
s++;
l--;
}
txt_add((unsigned char *) "%%", 2);
goto pcinfo;
}
if (*s == '%') {
if (!strchr(prefix, s[1]))
goto ignore;
s += 2;
l -= 2;
if (strncmp((char *) s, "abc ", 4) == 0) {
s += 4;
l -= 4;
goto info;
}
if (strncmp((char *) s, "abcm2ps ", 8) == 0
|| strncmp((char *) s, "ss-pref ", 8) == 0) {
s += 8;
l -= 8;
while (*s == ' ' || *s == '\t') {
s++;
l--;
}
for (i = 0; i < sizeof prefix - 1; i++) {
if (*s == ' ' || *s == '\t'
|| --l < 0)
break;
prefix[i] = *s++;
}
if (i == 0)
prefix[i++] = '%';
prefix[i] = '\0';
goto ignore;
}
if (strncmp((char *) s, "abc-version ", 12) == 0) {
get_vers((char *) s + 12);
goto ignore;
}
pscom:
while (*s == ' ' || *s == '\t') {
s++;
l--;
}
txt_add((unsigned char *) "%%", 2);
if (strncmp((char *) s, "begin", 5) == 0) {
q = begin_end = s + 5;
while (!isspace(*q))
q++;
end_len = q - begin_end;
goto next;
}
pcinfo:
if (strncmp((char *) s, "encoding ", 9) == 0
|| strncmp((char *) s, "abc-charset ", 12) == 0) {
if (*s == 'e')
q = s + 9;
else
q = s + 12;
while (*q == ' ' || *q == '\t')
q++;
if (strncasecmp((char *) q, "latin", 5) == 0) {
q += 5;
} else if (strncasecmp((char *) q, "iso-8859-", 9) == 0) {
q += 9;
} else if (strncasecmp((char *) q, "utf-8", 5) == 0
|| strncasecmp((char *) q, "native", 6) == 0) {
latin = 0;
goto next;
} else if (!isdigit(*q)) {
goto next;
}
switch (*q) {
case '1':
if (q[1] == '0')
latin = 6;
else
latin = 1;
break;
case '2': latin = 2; break;
case '3': latin = 3; break;
case '4': latin = 4; break;
case '5':
if (q[-1] != '-')
latin = 5;
break;
case '6':
if (q[-1] != '-')
latin = 6;
break;
case '9': latin = 5; break;
}
goto next;
}
if (strncmp((char *) s, "format ", 7) == 0
|| strncmp((char *) s, "abc-include ", 12) == 0) {
int skip_sav;
if (*s == 'f')
s += 7;
else
s += 12;
while (*s == ' ' || *s == '\t')
s++;
q = s;
while (*q != '\0'
&& *q != '%'
&& *q != '\n'
&& *q != '\r')
q++;
while (q[-1] == ' ')
q--;
sep = *q;
*q = '\0';
skip_sav = skip;
offset = 0;
include_file(s);
skip = skip_sav;
*q = sep;
goto ignore;
}
if (strncmp((char *) s, "select", 6) == 0) {
s += 6;
if (*s == '\n') {
q = s;
} else if (*s != ' ' && *s != '\t') {
goto next;
} else {
while (*s == ' ' || *s == '\t')
s++;
q = s;
while (*q != '\0'
&& *q != '%'
&& *q != '\n'
&& *q != '\r')
q++;
while (q[-1] == ' ' || q[-1] == '\t')
q--;
if (strncmp((char *) q - 5, " lock", 5) == 0)
q -= 5;
}
if (selection) {
free(selection);
selection = NULL;
}
if (q != s) {
sep = *q;
*q = '\0';
selection = (unsigned char *) strdup((char *) s);
*q = sep;
}
offset = 0;
goto ignore;
}
goto next;
}
info:
if (s[1] == ':' && (isalpha(*s) || *s == '+')) {
c = *s;
switch (c) {
case 'I':
s += 2;
l -= 2;
goto pscom;
case 'X':
switch (state) {
case 1:
fprintf(stderr,
"Line %d: X: found in tune header - K:C added\n",
linenum);
txt_add((unsigned char *) "K:C", 3);
txt_add_eos(fname, linenum);
txt_add_eos(fname, linenum);
break;
case 2:
txt_add_eos(fname, linenum);
break;
}
if (selection) {
skip = !tune_select(s);
if (skip)
goto ignore;
}
state = 1;
strcpy(prefix_sav, prefix);
latin_sav = latin;
break;
case 'U':
break;
case 'H':
histo = 1;
break;
default:
if (state == 0
&& strchr("dKPQsVWw", *s) != NULL)
goto ignore;
if (*s == 'K')
state = 2;
break;
}
txt_add(s, 2);
s += 2;
l -= 2;
while (*s == ' ' || *s == '\t') {
s++;
l--;
}
str_cnv_p = 1;
goto next;
}
if (state == 0)
goto ignore;
next:
if (str_cnv_p)
txt_add_cnv(s, l, !begin_end);
else
txt_add(s, l);
if (begin_end)
txt_add((unsigned char *) "\n", 1);
else
next_eol:
txt_add_eos(fname, linenum);
ignore:
s = p;
}
if (begin_end)
fprintf(stderr,
"Line %d: No %%%%end after %%%%begin\n",
linenum);
if (ftype == FE_FMT)
return;
if (state == 1)
fprintf(stderr,
"Line %d: Unexpected EOF in header definition\n",
linenum);
abc_eof();
}

static void save_segments(struct vcpu *v)
{
struct cpu_user_regs *regs = &v->arch.user_regs;
unsigned int dirty_segment_mask = 0;
regs->ds = read_sreg(ds);
regs->es = read_sreg(es);
regs->fs = read_sreg(fs);
regs->gs = read_sreg(gs);
if ( cpu_has_fsgsbase && !is_pv_32bit_vcpu(v) )
{
v->arch.pv.fs_base = __rdfsbase();
if ( v->arch.flags & TF_kernel_mode )
v->arch.pv.gs_base_kernel = __rdgsbase();
else
v->arch.pv.gs_base_user = __rdgsbase();
}
if ( regs->ds )
dirty_segment_mask |= DIRTY_DS;
if ( regs->es )
dirty_segment_mask |= DIRTY_ES;
if ( regs->fs || is_pv_32bit_vcpu(v) )
{
dirty_segment_mask |= DIRTY_FS;
if ( regs->fs & ~3 )
v->arch.pv.fs_base = 0;
}
if ( v->arch.pv.fs_base )
dirty_segment_mask |= DIRTY_FS_BASE;
if ( regs->gs || is_pv_32bit_vcpu(v) )
{
dirty_segment_mask |= DIRTY_GS;
if ( regs->gs & ~3 )
v->arch.pv.gs_base_user = 0;
}
if ( v->arch.flags & TF_kernel_mode ? v->arch.pv.gs_base_kernel
: v->arch.pv.gs_base_user )
dirty_segment_mask |= DIRTY_GS_BASE;
this_cpu(dirty_segment_mask) = dirty_segment_mask;
}

char* parseKey( char* ptr, FileNode& collection, FileNode& value_placeholder )
{
if( *ptr != '"' )
CV_PARSE_ERROR_CPP( "Key must start with \'\"\'" );
char * beg = ptr + 1;
do {
++ptr;
CV_PERSISTENCE_CHECK_END_OF_BUFFER_BUG_CPP();
} while( cv_isprint(*ptr) && *ptr != '"' );
if( *ptr != '"' )
CV_PARSE_ERROR_CPP( "Key must end with \'\"\'" );
const char * end = ptr;
ptr++;
ptr = skipSpaces( ptr );
if( !ptr || !*ptr )
return 0;
if( *ptr != ':' )
CV_PARSE_ERROR_CPP( "Missing \':\' between key and value" );
if( end <= beg )
CV_PARSE_ERROR_CPP( "Key is empty" );
value_placeholder = fs->addNode(collection, std::string(beg, (size_t)(end - beg)), FileNode::NONE);
return ++ptr;
}

