void
PackLinuxElf64::invert_pt_dynamic(Elf64_Dyn const *dynp)
{
if (dt_table[Elf64_Dyn::DT_NULL]) {
return;      }
Elf64_Dyn const *const dynp0 = dynp;
unsigned ndx = 1+ 0;
if (dynp)
for (; ; ++ndx, ++dynp) {
upx_uint64_t const d_tag = get_te64(&dynp->d_tag);
if (d_tag>>32) {             char msg[50]; snprintf(msg, sizeof(msg),
"bad Elf64_Dyn[%d].d_tag %#lx", -1+ ndx, (long unsigned)d_tag);
throwCantPack(msg);
}
if (d_tag < DT_NUM) {
if (Elf64_Dyn::DT_NEEDED != d_tag
&&  dt_table[d_tag]
&&    get_te64(&dynp->d_val)
!= get_te64(&dynp0[-1+ dt_table[d_tag]].d_val)) {
char msg[50]; snprintf(msg, sizeof(msg),
"duplicate DT_%#x: [%#x] [%#x]",
(unsigned)d_tag, -1+ dt_table[d_tag], -1+ ndx);
throwCantPack(msg);
}
dt_table[d_tag] = ndx;
}
if (Elf64_Dyn::DT_NULL == d_tag) {
break;          }
}
upx_dt_init = 0;
if (dt_table[Elf64_Dyn::DT_INIT])          upx_dt_init = Elf64_Dyn::DT_INIT;
else if (dt_table[Elf64_Dyn::DT_PREINIT_ARRAY]) upx_dt_init = Elf64_Dyn::DT_PREINIT_ARRAY;
else if (dt_table[Elf64_Dyn::DT_INIT_ARRAY])    upx_dt_init = Elf64_Dyn::DT_INIT_ARRAY;
unsigned const z_str = dt_table[Elf64_Dyn::DT_STRSZ];
if (z_str) {
strtab_end = get_te64(&dynp0[-1+ z_str].d_val);
if ((u64_t)file_size <= strtab_end) {             char msg[50]; snprintf(msg, sizeof(msg),
"bad DT_STRSZ %#x", strtab_end);
throwCantPack(msg);
}
}
unsigned const x_sym = dt_table[Elf64_Dyn::DT_SYMTAB];
unsigned const x_str = dt_table[Elf64_Dyn::DT_STRTAB];
if (x_sym && x_str) {
upx_uint64_t const v_sym = get_te64(&dynp0[-1+ x_sym].d_val);
upx_uint64_t const v_str = get_te64(&dynp0[-1+ x_str].d_val);
unsigned const  z_sym = dt_table[Elf64_Dyn::DT_SYMENT];
unsigned const sz_sym = !z_sym ? sizeof(Elf64_Sym)
: get_te64(&dynp0[-1+ z_sym].d_val);
if (sz_sym < sizeof(Elf64_Sym)) {
char msg[50]; snprintf(msg, sizeof(msg),
"bad DT_SYMENT %x", sz_sym);
throwCantPack(msg);
}
if (v_sym < v_str) {
symnum_end = (v_str - v_sym) / sz_sym;
}
if (symnum_end < 1) {
throwCantPack("bad DT_SYMTAB");
}
}
unsigned const v_hsh = elf_unsigned_dynamic(Elf64_Dyn::DT_HASH);
if (v_hsh && file_image) {
hashtab = (unsigned const *)elf_find_dynamic(Elf64_Dyn::DT_HASH);
if (!hashtab) {
char msg[40]; snprintf(msg, sizeof(msg),
"bad DT_HASH %#x", v_hsh);
throwCantPack(msg);
}
unsigned const nbucket = get_te32(&hashtab[0]);
unsigned const *const buckets = &hashtab[2];
unsigned const *const chains = &buckets[nbucket]; (void)chains;
unsigned const v_sym = get_te32(&dynp0[-1+ x_sym].d_val);
if (!nbucket
|| (nbucket>>31) || (file_size/sizeof(unsigned)) <= (2*nbucket)          || ((v_hsh < v_sym) && (v_sym - v_hsh) < (sizeof(unsigned)*2                  + sizeof(*buckets)*nbucket                  + sizeof(*chains) *nbucket             ))
) {
char msg[90]; snprintf(msg, sizeof(msg),
"bad DT_HASH nbucket=%#x  len=%#x",
nbucket, (v_sym - v_hsh));
throwCantPack(msg);
}
}
unsigned const v_gsh = elf_unsigned_dynamic(Elf64_Dyn::DT_GNU_HASH);
if (v_gsh && file_image) {
gashtab = (unsigned const *)elf_find_dynamic(Elf64_Dyn::DT_GNU_HASH);
if (!gashtab) {
char msg[40]; snprintf(msg, sizeof(msg),
"bad DT_GNU_HASH %#x", v_gsh);
throwCantPack(msg);
}
unsigned const n_bucket = get_te32(&gashtab[0]);
unsigned const n_bitmask = get_te32(&gashtab[2]);
unsigned const gnu_shift = get_te32(&gashtab[3]);
upx_uint64_t const *const bitmask = (upx_uint64_t const *)(void const *)&gashtab[4];
unsigned     const *const buckets = (unsigned const *)&bitmask[n_bitmask];
unsigned     const *const hasharr = &buckets[n_bucket]; (void)hasharr;
upx_uint64_t const v_sym = get_te64(&dynp0[-1+ x_sym].d_val);
if (!n_bucket || !n_bitmask
|| (-1+ n_bitmask) & n_bitmask          || 8*sizeof(upx_uint64_t) <= gnu_shift          || (n_bucket>>30)          || (n_bitmask>>30)
|| (file_size/sizeof(unsigned)) <= ((sizeof(*bitmask)/sizeof(unsigned))*n_bitmask + 2*n_bucket)                  || ((v_gsh < v_sym) && (v_sym - v_gsh) < (sizeof(unsigned)*4                  + sizeof(*bitmask)*n_bitmask                  + sizeof(*buckets)*n_bucket                  + sizeof(*hasharr)*n_bucket              ))
) {
char msg[90]; snprintf(msg, sizeof(msg),
"bad DT_GNU_HASH n_bucket=%#x  n_bitmask=%#x  len=%#lx",
n_bucket, n_bitmask, (long unsigned)(v_sym - v_gsh));
throwCantPack(msg);
}
}
unsigned const e_shstrndx = get_te16(&ehdri.e_shstrndx);
if (e_shnum <= e_shstrndx
&&  !(0==e_shnum && 0==e_shstrndx) ) {
char msg[40]; snprintf(msg, sizeof(msg),
"bad .e_shstrndx %d >= .e_shnum %d", e_shstrndx, e_shnum);
throwCantPack(msg);
}
}

AP4_StsdAtom::AP4_StsdAtom(AP4_UI32         size,
AP4_UI08         version,
AP4_UI32         flags,
AP4_ByteStream&  stream,
AP4_AtomFactory& atom_factory) :
AP4_ContainerAtom(AP4_ATOM_TYPE_STSD, size, false, version, flags)
{
AP4_UI32 entry_count;
stream.ReadUI32(entry_count);
atom_factory.PushContext(m_Type);
AP4_LargeSize bytes_available = size-AP4_FULL_ATOM_HEADER_SIZE-4;
for (unsigned int i=0; i<entry_count; i++) {
AP4_Atom* atom;
if (AP4_SUCCEEDED(atom_factory.CreateAtomFromStream(stream, 
bytes_available,
atom))) {
atom->SetParent(this);
m_Children.Add(atom);
}
}
atom_factory.PopContext();
m_SampleDescriptions.EnsureCapacity(m_Children.ItemCount());
for (AP4_Ordinal i=0; i<m_Children.ItemCount(); i++) {
m_SampleDescriptions.Append(NULL);
}
}

int dnn_execute_layer_pad(DnnOperand *operands, const int32_t *input_operand_indexes,
int32_t output_operand_index, const void *parameters)
{
int32_t before_paddings;
int32_t after_paddings;
float* output;
const LayerPadParams *params = (const LayerPadParams *)parameters;
int32_t input_operand_index = input_operand_indexes[0];
int number = operands[input_operand_index].dims[0];
int height = operands[input_operand_index].dims[1];
int width = operands[input_operand_index].dims[2];
int channel = operands[input_operand_index].dims[3];
const float *input = operands[input_operand_index].data;
int new_number = number + params->paddings[0][0] + params->paddings[0][1];
int new_height = height + params->paddings[1][0] + params->paddings[1][1];
int new_width = width + params->paddings[2][0] + params->paddings[2][1];
int new_channel = channel + params->paddings[3][0] + params->paddings[3][1];
int c_stride = channel;
int wc_stride = c_stride * width;
int hwc_stride = wc_stride * height;
int new_c_stride = new_channel;
int new_wc_stride = new_c_stride * new_width;
int new_hwc_stride = new_wc_stride * new_height;
DnnOperand *output_operand = &operands[output_operand_index];
output_operand->dims[0] = new_number;
output_operand->dims[1] = new_height;
output_operand->dims[2] = new_width;
output_operand->dims[3] = new_channel;
output_operand->data_type = operands[input_operand_index].data_type;
output_operand->length = calculate_operand_data_length(output_operand);
output_operand->data = av_realloc(output_operand->data, output_operand->length);
if (!output_operand->data)
return -1;
output = output_operand->data;
for (int n = 0; n < number; n++) {
for (int h = 0; h < height; h++) {
for (int w = 0; w < width; w++) {
const float *src = input + n * hwc_stride + h * wc_stride + w * c_stride;
float *dst = output + (n + params->paddings[0][0]) * new_hwc_stride
+ (h + params->paddings[1][0]) * new_wc_stride
+ (w + params->paddings[2][0]) * new_c_stride
+ params->paddings[3][0];
memcpy(dst, src, channel * sizeof(float));
}
}
}
before_paddings = params->paddings[0][0];
after_paddings = params->paddings[0][1];
for (int n = 0; n < before_paddings; n++) {
float *dst = output + n * new_hwc_stride;
if (params->mode == LPMP_CONSTANT) {
for (int i = 0; i < new_hwc_stride; i++) {
dst[i] = params->constant_values;
}
}
else {
int buddy = before_get_buddy(n, before_paddings, params->mode);
float *src = output + buddy * new_hwc_stride;
memcpy(dst, src, new_hwc_stride * sizeof(float));
}
}
for (int n = 0; n < after_paddings; n++) {
int given = number + before_paddings + n;
float *dst = output + given * new_hwc_stride;
if (params->mode == LPMP_CONSTANT) {
for (int i = 0; i < new_hwc_stride; i++) {
dst[i] = params->constant_values;
}
} else {
int buddy = after_get_buddy(given, number + before_paddings, params->mode);
float *src = output + buddy * new_hwc_stride;
memcpy(dst, src, new_hwc_stride * sizeof(float));
}
}
before_paddings = params->paddings[1][0];
after_paddings = params->paddings[1][1];
for (int n = 0; n < new_number; n++) {
float *start = output + n * new_hwc_stride;
for (int h = 0; h < before_paddings; h++) {
float *dst = start + h * new_wc_stride;
if (params->mode == LPMP_CONSTANT) {
for (int i = 0; i < new_wc_stride; i++) {
dst[i] = params->constant_values;
}
} else {
int buddy = before_get_buddy(h, before_paddings, params->mode);
float *src = start + buddy * new_wc_stride;
memcpy(dst, src, new_wc_stride * sizeof(float));
}
}
for (int h = 0; h < after_paddings; h++) {
int given = height + before_paddings + h;
float *dst = start + given * new_wc_stride;
if (params->mode == LPMP_CONSTANT) {
for (int i = 0; i < new_wc_stride; i++) {
dst[i] = params->constant_values;
}
} else {
int buddy = after_get_buddy(given, height + before_paddings, params->mode);
float *src = start + buddy * new_wc_stride;
memcpy(dst, src, new_wc_stride * sizeof(float));
}
}
}
before_paddings = params->paddings[2][0];
after_paddings = params->paddings[2][1];
for (int n = 0; n < new_number; n++) {
for (int h = 0; h < new_height; h++) {
float *start = output + n * new_hwc_stride + h * new_wc_stride;
for (int w = 0; w < before_paddings; w++) {
float *dst = start + w * new_c_stride;
if (params->mode == LPMP_CONSTANT) {
for (int i = 0; i < new_c_stride; i++) {
dst[i] = params->constant_values;
}
} else {
int buddy = before_get_buddy(w, before_paddings, params->mode);
float *src = start + buddy * new_c_stride;
memcpy(dst, src, new_c_stride * sizeof(float));
}
}
for (int w = 0; w < after_paddings; w++) {
int given = width + before_paddings + w;
float *dst = start + given * new_c_stride;
if (params->mode == LPMP_CONSTANT) {
for (int i = 0; i < new_c_stride; i++) {
dst[i] = params->constant_values;
}
} else {
int buddy = after_get_buddy(given, width + before_paddings, params->mode);
float *src = start + buddy * new_c_stride;
memcpy(dst, src, new_c_stride * sizeof(float));
}
}
}
}
before_paddings = params->paddings[3][0];
after_paddings = params->paddings[3][1];
for (int n = 0; n < new_number; n++) {
for (int h = 0; h < new_height; h++) {
for (int w = 0; w < new_width; w++) {
float *start = output + n * new_hwc_stride + h * new_wc_stride + w * new_c_stride;
for (int c = 0; c < before_paddings; c++) {
float *dst = start + c;
if (params->mode == LPMP_CONSTANT) {
*dst = params->constant_values;
} else {
int buddy = before_get_buddy(c, before_paddings, params->mode);
float *src = start + buddy;
*dst = *src;
}
}
for (int c = 0; c < after_paddings; c++) {
int given = channel + before_paddings + c;
float *dst = start + given;
if (params->mode == LPMP_CONSTANT) {
*dst = params->constant_values;
} else {
int buddy = after_get_buddy(given, channel + before_paddings, params->mode);
float *src = start + buddy;
*dst = *src;
}
}
}
}
}
return 0;
}

static int
myeid_enc_dec_sym(struct sc_card *card, const u8 *data, size_t datalen,
u8 *out, size_t *outlen, int decipher)
{
struct sc_context *ctx;
struct sc_apdu apdu;
u8 rbuf[SC_MAX_APDU_BUFFER_SIZE];
u8 sbuf[SC_MAX_APDU_BUFFER_SIZE];
u8 *sdata;
int r, padding = 0, cbc = 0;
size_t block_size;
size_t len, rest_len;
size_t return_len = 0;
size_t max_apdu_datalen;
size_t apdu_datalen;
assert(card != NULL);
ctx = card->ctx;
LOG_FUNC_CALLED(ctx);
myeid_private_data_t *priv;
priv = (myeid_private_data_t *)card->drv_data;
max_apdu_datalen = sc_get_max_send_size(card);
if (max_apdu_datalen > sc_get_max_recv_size(card))
max_apdu_datalen = sc_get_max_recv_size(card);
if (max_apdu_datalen > SC_MAX_APDU_BUFFER_SIZE)
max_apdu_datalen = SC_MAX_APDU_BUFFER_SIZE;
sc_log(ctx, "algorithm %d algorithm_flags %x", priv->algorithm, priv->algorithm_flags);
if (outlen == NULL) {
sc_log(ctx, "%s (symmetric key) initialized", decipher ? "C_DecryptInit" : "C_EncryptInit");
priv->sym_crypt_buffer_len = 0;
priv->sym_plain_buffer_len = 0;
return SC_SUCCESS;
}
switch (priv->algorithm) {
case SC_ALGORITHM_AES:
block_size = 16;
if (priv->algorithm_flags & SC_ALGORITHM_AES_ECB) {
padding = 0;
cbc = 0;
} else if (priv->algorithm_flags & SC_ALGORITHM_AES_CBC) {
padding = 0;
cbc = 1;
} else if (priv->algorithm_flags & SC_ALGORITHM_AES_CBC_PAD) {
padding = 1;
cbc = 1;
}
break;
default:
LOG_FUNC_RETURN(ctx, SC_ERROR_NOT_SUPPORTED);
}
if (cbc)
max_apdu_datalen -= max_apdu_datalen % block_size;
else
max_apdu_datalen = block_size;
rest_len = priv->sym_crypt_buffer_len;
if (data == NULL) {
if (datalen != 0)
LOG_FUNC_RETURN(ctx, SC_ERROR_WRONG_LENGTH);
if (decipher) {
if (priv->sym_plain_buffer_len != block_size)
LOG_FUNC_RETURN(ctx, SC_ERROR_WRONG_LENGTH);
if (rest_len)
LOG_FUNC_RETURN(ctx, SC_ERROR_WRONG_LENGTH);
return_len = block_size;
if (padding) {
uint8_t i, pad_byte = *(priv->sym_plain_buffer + block_size - 1);
sc_log(ctx, "Found padding byte %02x", pad_byte);
if (pad_byte == 0 || pad_byte > block_size)
LOG_FUNC_RETURN(ctx, SC_ERROR_WRONG_PADDING);
sdata = priv->sym_plain_buffer + block_size - pad_byte;
for (i = 0; i < pad_byte; i++)
if (sdata[i] != pad_byte)
LOG_FUNC_RETURN(ctx, SC_ERROR_WRONG_PADDING);
return_len = block_size - pad_byte;
}
*outlen = return_len;
if (out == NULL)
LOG_FUNC_RETURN(ctx, SC_SUCCESS);
if (return_len > *outlen)
LOG_FUNC_RETURN(ctx, SC_ERROR_BUFFER_TOO_SMALL);
memcpy(out, priv->sym_plain_buffer, return_len);
sc_log(ctx, "C_DecryptFinal %zu bytes", *outlen);
return SC_SUCCESS;
} else {
if (padding) {
uint8_t pad_byte = block_size - rest_len;
sc_log(ctx, "Generating padding, padding byte: %d", pad_byte);
sdata = priv->sym_crypt_buffer + rest_len;
memset(sdata, pad_byte, pad_byte);
rest_len = block_size;
} else if (rest_len) {
LOG_FUNC_RETURN(ctx, SC_ERROR_WRONG_LENGTH);
}
}
}
len = datalen + rest_len;
sc_log(ctx, "datalen=%zu rest_len=%zu len=%zu outlen=%zu", datalen, rest_len, len, *outlen);
len -= (len % block_size);
*outlen = len;
if (out == NULL)
LOG_FUNC_RETURN(ctx, SC_SUCCESS);
if (*outlen < len)
LOG_FUNC_RETURN(ctx, SC_ERROR_BUFFER_TOO_SMALL);
while (len >= block_size) {
if (!decipher)
sc_format_apdu(card, &apdu, SC_APDU_CASE_4_SHORT, 0x2A, 0x84, 0x80);
else
sc_format_apdu(card, &apdu, SC_APDU_CASE_4_SHORT, 0x2A, 0x80, 0x84);
apdu.cla = 0;
if (len > max_apdu_datalen)
apdu_datalen = max_apdu_datalen;
else
apdu_datalen = len;
if (cbc)
apdu.cla = 0x10;
len -= apdu_datalen;
sdata = sbuf;
apdu.le = apdu_datalen;
apdu.lc = apdu_datalen;
apdu.datalen = apdu_datalen;
apdu.data = sbuf;
apdu.resplen = sizeof(rbuf);
apdu.resp = rbuf;
if (rest_len) {
memcpy(sbuf, priv->sym_crypt_buffer, rest_len);
sdata += rest_len;
apdu_datalen -= rest_len;
priv->sym_crypt_buffer_len = 0;
rest_len = 0;
}
if (data) {
memcpy(sdata, data, apdu_datalen);
data += apdu_datalen;
datalen -= apdu_datalen;
}
r = sc_transmit_apdu(card, &apdu);
LOG_TEST_RET(ctx, r, "APDU transmit failed");
r = sc_check_sw(card, apdu.sw1, apdu.sw2);
LOG_TEST_RET(ctx, r, "decrypt_sym/encrypt_sym failed");
if (apdu.resplen != apdu.datalen)
LOG_FUNC_RETURN(ctx, SC_ERROR_WRONG_LENGTH);
memcpy(out, apdu.resp, apdu.resplen);
out += apdu.resplen;
return_len += apdu.resplen;
}
if (decipher) {
uint8_t tmp_buf[16];
if (return_len >= block_size) {
memcpy(tmp_buf, out - block_size, block_size);
if (priv->sym_plain_buffer_len) {
sc_log(ctx, "inserting block from previous decrypt");
memmove(out - return_len + block_size, out - return_len, return_len - block_size);
memcpy(out - return_len, priv->sym_plain_buffer, block_size);
} else
return_len -= block_size;
memcpy(priv->sym_plain_buffer, tmp_buf, block_size);
priv->sym_plain_buffer_len = block_size;
} else
priv->sym_plain_buffer_len = 0;
}
priv->sym_crypt_buffer_len = datalen;
sc_log(ctx, "rest data len = %zu", datalen);
if (data)
memcpy(priv->sym_crypt_buffer, data, datalen);
sc_log(ctx, "return data len = %zu", return_len);
*outlen = return_len;
return SC_SUCCESS;
}

static int llcp_raw_sock_bind(struct socket *sock, struct sockaddr *addr,
int alen)
{
struct sock *sk = sock->sk;
struct nfc_llcp_sock *llcp_sock = nfc_llcp_sock(sk);
struct nfc_llcp_local *local;
struct nfc_dev *dev;
struct sockaddr_nfc_llcp llcp_addr;
int len, ret = 0;
if (!addr || alen < offsetofend(struct sockaddr, sa_family) ||
addr->sa_family != AF_NFC)
return -EINVAL;
pr_debug("sk %p addr %p family %d\n", sk, addr, addr->sa_family);
memset(&llcp_addr, 0, sizeof(llcp_addr));
len = min_t(unsigned int, sizeof(llcp_addr), alen);
memcpy(&llcp_addr, addr, len);
lock_sock(sk);
if (sk->sk_state != LLCP_CLOSED) {
ret = -EBADFD;
goto error;
}
dev = nfc_get_device(llcp_addr.dev_idx);
if (dev == NULL) {
ret = -ENODEV;
goto error;
}
local = nfc_llcp_find_local(dev);
if (local == NULL) {
ret = -ENODEV;
goto put_dev;
}
llcp_sock->dev = dev;
llcp_sock->local = nfc_llcp_local_get(local);
llcp_sock->nfc_protocol = llcp_addr.nfc_protocol;
nfc_llcp_sock_link(&local->raw_sockets, sk);
sk->sk_state = LLCP_BOUND;
put_dev:
nfc_put_device(dev);
error:
release_sock(sk);
return ret;
}

AP4_Stz2Atom::AP4_Stz2Atom(AP4_UI32        size, 
AP4_UI08        version,
AP4_UI32        flags,
AP4_ByteStream& stream) :
AP4_Atom(AP4_ATOM_TYPE_STZ2, size, version, flags)
{
AP4_UI08 reserved;
stream.ReadUI08(reserved);
stream.ReadUI08(reserved);
stream.ReadUI08(reserved);
stream.ReadUI08(m_FieldSize);
stream.ReadUI32(m_SampleCount);
if (m_FieldSize != 4 && m_FieldSize != 8 && m_FieldSize != 16) {
return;
}
AP4_Cardinal sample_count = m_SampleCount;
m_Entries.SetItemCount(sample_count);
unsigned int table_size = (sample_count*m_FieldSize+7)/8;
if ((table_size+8) > size) return;
unsigned char* buffer = new unsigned char[table_size];
AP4_Result result = stream.Read(buffer, table_size);
if (AP4_FAILED(result)) {
delete[] buffer;
return;
}
switch (m_FieldSize) {
case 4:
for (unsigned int i=0; i<sample_count; i++) {
if ((i%2) == 0) {
m_Entries[i] = (buffer[i/2]>>4)&0x0F;
} else {
m_Entries[i] = buffer[i/2]&0x0F;
}
}
break;
case 8:
for (unsigned int i=0; i<sample_count; i++) {
m_Entries[i] = buffer[i];
}
break;
case 16:
for (unsigned int i=0; i<sample_count; i++) {
m_Entries[i] = AP4_BytesToUInt16BE(&buffer[i*2]);
}
break;
}
delete[] buffer;
}

bool DataItemFormatExplicit::getText(std::string &strResult, std::string &strHeader, const unsigned int formatType,
unsigned char *pData, long nLength) {
std::list<DataItemFormat *>::iterator it;
int bodyLength = 0;
bool ret = false;
pData++; 
for (it = m_lSubItems.begin(); it != m_lSubItems.end(); it++) {
DataItemFormat *di = (DataItemFormat *) (*it);
bodyLength += di->getLength(pData + bodyLength);     }
int nFullLength = nLength - 1; 
if (bodyLength == 0 || nFullLength % bodyLength != 0) {
Tracer::Error("Wrong data length in Explicit. Needed=%d and there is %d bytes.", bodyLength, nFullLength);
}
std::string tmpStr = "";
if (nFullLength != bodyLength) {
switch (formatType) {
case CAsterixFormat::EJSON:
case CAsterixFormat::EJSONH:
case CAsterixFormat::EJSONE: {
tmpStr += format("[");
}
}
}
for (int i = 0; i < nFullLength; i += bodyLength) {
for (it = m_lSubItems.begin(); it != m_lSubItems.end(); it++) {
DataItemFormat *di = (DataItemFormat *) (*it);
ret |= di->getText(tmpStr, strHeader, formatType, pData, bodyLength);
pData += bodyLength;
if (nFullLength != bodyLength) {
switch (formatType) {
case CAsterixFormat::EJSON:
case CAsterixFormat::EJSONH:
case CAsterixFormat::EJSONE: {
tmpStr += format(",");
}
}
}
}
}
if (nFullLength != bodyLength) {
switch (formatType) {
case CAsterixFormat::EJSON:
case CAsterixFormat::EJSONH:
case CAsterixFormat::EJSONE: {
if (tmpStr[tmpStr.length() - 1] == ',') {
tmpStr[tmpStr.length() - 1] = ']';
} else {
tmpStr += ']';
}
}
}
}
strResult += tmpStr;
return ret;
}

static void gf_media_update_bitrate_ex(GF_ISOFile *file, u32 track, Bool use_esd)
{
#ifndef GPAC_DISABLE_ISOM_WRITE
u32 i, count, timescale, db_size, cdur, csize;
u64 time_wnd, max_rate, avg_rate, bitrate;
Double br;
GF_ISOSample sample;
db_size = 0;
max_rate = avg_rate = time_wnd = bitrate = 0;
csize = 0;
cdur = 0;
if (gf_isom_get_media_type(file, track)==GF_ISOM_MEDIA_AUDIO) {
csize = gf_isom_get_constant_sample_size(file, track);
cdur = gf_isom_get_constant_sample_duration(file, track);
if (cdur > 1) cdur = 0;
}
memset(&sample, 0, sizeof(GF_ISOSample));
timescale = gf_isom_get_media_timescale(file, track);
count = gf_isom_get_sample_count(file, track);
if (csize && cdur) {
db_size = 0;
avg_rate = 8 * csize * timescale / cdur;
bitrate = avg_rate;
} else {
u32 rate = 0;
for (i=0; i<count; i++) {
u32 di;
GF_ISOSample *samp = gf_isom_get_sample_info_ex(file, track, i+1, &di, NULL, &sample);
if (!samp) break;
if (samp->dataLength > db_size) db_size = samp->dataLength;
avg_rate += samp->dataLength;
rate += samp->dataLength;
if (samp->DTS > time_wnd + timescale) {
if (rate > max_rate) max_rate = rate;
time_wnd = samp->DTS;
rate = 0;
}
}
}
br = (Double) (s64) gf_isom_get_media_duration(file, track);
br /= timescale;
if (br) {
GF_ESD *esd = NULL;
if (!csize || !cdur) {
bitrate = (u32) ((Double) (s64)avg_rate / br);
bitrate *= 8;
max_rate *= 8;
}
if (!max_rate) max_rate = bitrate;
if (use_esd) esd = gf_isom_get_esd(file, track, 1);
if (esd && esd->decoderConfig) {
esd->decoderConfig->avgBitrate = (u32) bitrate;
esd->decoderConfig->maxBitrate = (u32) max_rate;
esd->decoderConfig->bufferSizeDB = db_size;
gf_isom_change_mpeg4_description(file, track, 1, esd);
} else {
gf_isom_update_bitrate(file, track, 1, (u32) bitrate, (u32) max_rate, db_size);
}
if (esd) gf_odf_desc_del((GF_Descriptor *)esd);
}
#endif
}

static int spl2sw_nvmem_get_mac_address(struct device *dev, struct device_node *np,
void *addrbuf)
{
struct nvmem_cell *cell;
ssize_t len;
u8 *mac;
cell = of_nvmem_cell_get(np, "mac-address");
if (IS_ERR(cell))
return PTR_ERR(cell);
mac = nvmem_cell_read(cell, &len);
nvmem_cell_put(cell);
if (IS_ERR(mac))
return PTR_ERR(mac);
if (len != ETH_ALEN) {
kfree(mac);
dev_info(dev, "Invalid length of mac address in nvmem!\n");
return -EINVAL;
}
spl2sw_check_mac_vendor_id_and_convert(mac);
if (!is_valid_ether_addr(mac)) {
kfree(mac);
dev_info(dev, "Invalid mac address in nvmem (%pM)!\n", mac);
return -EINVAL;
}
ether_addr_copy(addrbuf, mac);
kfree(mac);
return 0;
}

LIBXSMM_API_INTERN
void libxsmm_sparse_csr_reader( libxsmm_generated_code* io_generated_code,
const char*             i_csr_file_in,
unsigned int**          o_row_idx,
unsigned int**          o_column_idx,
double**                o_values,
unsigned int*           io_row_count,
unsigned int*           io_column_count,
unsigned int*           o_element_count ) {
FILE *l_csr_file_handle;
const unsigned int l_line_length = 512;
char l_line[512+1];
unsigned int l_header_read = 0;
unsigned int* l_row_idx_id = NULL;
unsigned int l_i = 0;
l_csr_file_handle = fopen( i_csr_file_in, "r" );
if ( l_csr_file_handle == NULL ) {
LIBXSMM_HANDLE_ERROR( io_generated_code, LIBXSMM_ERR_CSR_INPUT );
return;
}
while (fgets(l_line, l_line_length, l_csr_file_handle) != NULL) {
if ( strlen(l_line) == l_line_length ) {
free(*o_row_idx); free(*o_column_idx); free(*o_values); free(l_row_idx_id);
*o_row_idx = 0; *o_column_idx = 0; *o_values = 0;
fclose(l_csr_file_handle); 
LIBXSMM_HANDLE_ERROR( io_generated_code, LIBXSMM_ERR_CSR_READ_LEN );
return;
}
if ( l_line[0] == '%' ) {
continue;
} else {
if ( l_header_read == 0 ) {
unsigned int row_count, column_count;
if (3 == sscanf(l_line, "%u %u %u", &row_count, &column_count, o_element_count) &&
0 != row_count && 0 != column_count && 0 != *o_element_count)
{
*io_column_count = LIBXSMM_MAX(*io_column_count, column_count);
*io_row_count = LIBXSMM_MAX(*io_row_count, row_count);
*o_column_idx = (unsigned int*) malloc(sizeof(unsigned int) * (*o_element_count));
*o_row_idx = (unsigned int*) malloc(sizeof(unsigned int) * ((size_t)(*io_row_count) + 1));
*o_values = (double*) malloc(sizeof(double) * (*o_element_count));
l_row_idx_id = (unsigned int*) malloc(sizeof(unsigned int) * (*io_row_count));
if ( ( *o_row_idx == NULL )      ||
( *o_column_idx == NULL )   ||
( *o_values == NULL )       ||
( l_row_idx_id == NULL ) ) {
free(*o_row_idx); free(*o_column_idx); free(*o_values); free(l_row_idx_id);
*o_row_idx = 0; *o_column_idx = 0; *o_values = 0;
fclose(l_csr_file_handle); 
LIBXSMM_HANDLE_ERROR( io_generated_code, LIBXSMM_ERR_CSC_ALLOC_DATA );
return;
}
memset(*o_row_idx, 0, sizeof(unsigned int) * ((size_t)(*io_row_count) + 1));
memset(*o_column_idx, 0, sizeof(unsigned int) * (*o_element_count));
memset(*o_values, 0, sizeof(double) * (*o_element_count));
memset(l_row_idx_id, 0, sizeof(unsigned int) * (*io_row_count));
for ( l_i = 0; l_i <= *io_row_count; ++l_i )
(*o_row_idx)[l_i] = (*o_element_count);
(*o_row_idx)[0] = 0;
l_i = 0;
l_header_read = 1;
} else {
LIBXSMM_HANDLE_ERROR( io_generated_code, LIBXSMM_ERR_CSR_READ_DESC );
fclose( l_csr_file_handle ); 
return;
}
} else {
unsigned int l_row = 0, l_column = 0;
double l_value = 0;
if ( sscanf(l_line, "%u %u %lf", &l_row, &l_column, &l_value) != 3 ) {
free(*o_row_idx); free(*o_column_idx); free(*o_values); free(l_row_idx_id);
*o_row_idx = 0; *o_column_idx = 0; *o_values = 0;
fclose(l_csr_file_handle); 
LIBXSMM_HANDLE_ERROR( io_generated_code, LIBXSMM_ERR_CSR_READ_ELEMS );
return;
}
LIBXSMM_ASSERT(0 != l_row && 0 != l_column);
l_row--; l_column--;
(*o_column_idx)[l_i] = l_column;
(*o_values)[l_i] = l_value;
l_i++;
l_row_idx_id[l_row] = 1;
(*o_row_idx)[l_row+1] = l_i;
}
}
}
fclose( l_csr_file_handle );
if ( l_i != (*o_element_count) ) {
free(*o_row_idx); free(*o_column_idx); free(*o_values); free(l_row_idx_id);
*o_row_idx = 0; *o_column_idx = 0; *o_values = 0;
LIBXSMM_HANDLE_ERROR( io_generated_code, LIBXSMM_ERR_CSR_LEN );
return;
}
if ( l_row_idx_id != NULL ) {
for ( l_i = 0; l_i < (*io_row_count); l_i++) {
if ( l_row_idx_id[l_i] == 0 ) {
(*o_row_idx)[l_i+1] = (*o_row_idx)[l_i];
}
}
free( l_row_idx_id );
}
}

int vrend_renderer_transfer_iov(const struct vrend_transfer_info *info,
int transfer_mode)
{
struct vrend_resource *res;
struct vrend_context *ctx;
struct iovec *iov;
int num_iovs;
if (!info->box)
return EINVAL;
ctx = vrend_lookup_renderer_ctx(info->ctx_id);
if (!ctx)
return EINVAL;
if (info->ctx_id == 0)
res = vrend_resource_lookup(info->handle, 0);
else
res = vrend_renderer_ctx_res_lookup(ctx, info->handle);
if (!res) {
if (info->ctx_id)
report_context_error(ctx, VIRGL_ERROR_CTX_ILLEGAL_RESOURCE, info->handle);
return EINVAL;
}
iov = info->iovec;
num_iovs = info->iovec_cnt;
if (res->iov && (!iov || num_iovs == 0)) {
iov = res->iov;
num_iovs = res->num_iovs;
}
if (!iov) {
if (info->ctx_id)
report_context_error(ctx, VIRGL_ERROR_CTX_ILLEGAL_RESOURCE, info->handle);
return EINVAL;
}
#ifdef ENABLE_GBM_ALLOCATION
if (res->gbm_bo)
return virgl_gbm_transfer(res->gbm_bo, transfer_mode, iov, num_iovs, info);
#endif
if (!check_transfer_bounds(res, info))
return EINVAL;
if (!check_iov_bounds(res, info, iov, num_iovs))
return EINVAL;
if (info->context0) {
vrend_renderer_force_ctx_0();
ctx = NULL;
}
switch (transfer_mode) {
case VIRGL_TRANSFER_TO_HOST:
return vrend_renderer_transfer_write_iov(ctx, res, iov, num_iovs, info);
case VIRGL_TRANSFER_FROM_HOST:
return vrend_renderer_transfer_send_iov(res, iov, num_iovs, info);
default:
assert(0);
}
return 0;
}

static ssize_t compress(zckCtx *zck, zckComp *comp, const char *src,
const size_t src_size, char **dst, size_t *dst_size,
bool use_dict) {
VALIDATE_INT(zck);
ALLOCD_INT(zck, dst);
ALLOCD_INT(zck, src);
ALLOCD_INT(zck, dst_size);
ALLOCD_INT(zck, comp);
comp->dc_data = zrealloc(comp->dc_data, comp->dc_data_size + src_size);
if (!comp->dc_data) {
zck_log(ZCK_LOG_ERROR, "OOM in %s", __func__);
return -1;
}
memcpy(comp->dc_data + comp->dc_data_size, src, src_size);
*dst = NULL;
*dst_size = 0;
return 0;
}

AP4_StszAtom::AP4_StszAtom(AP4_UI32        size, 
AP4_UI08        version,
AP4_UI32        flags,
AP4_ByteStream& stream) :
AP4_Atom(AP4_ATOM_TYPE_STSZ, size, version, flags)
{
stream.ReadUI32(m_SampleSize);
stream.ReadUI32(m_SampleCount);
if (m_SampleSize == 0) {                 if (m_SampleCount > (size-8)/4) {
m_SampleCount = 0;
return;
}
AP4_Cardinal sample_count = m_SampleCount;
m_Entries.SetItemCount(sample_count);
unsigned char* buffer = new unsigned char[sample_count*4];
AP4_Result result = stream.Read(buffer, sample_count*4);
if (AP4_FAILED(result)) {
delete[] buffer;
m_Entries.Clear();
m_SampleCount = 0;
return;
}
for (unsigned int i=0; i<sample_count; i++) {
m_Entries[i] = AP4_BytesToUInt32BE(&buffer[i*4]);
}
delete[] buffer;
}
}

static void
exif_mnote_data_pentax_load (ExifMnoteData *en,
const unsigned char *buf, unsigned int buf_size)
{
ExifMnoteDataPentax *n = (ExifMnoteDataPentax *) en;
size_t i, tcount, o, datao, base = 0;
ExifShort c;
if (!n || !buf || !buf_size) {
exif_log (en->log, EXIF_LOG_CODE_CORRUPT_DATA,
"ExifMnoteDataPentax", "Short MakerNote");
return;
}
datao = 6 + n->offset;
if ((datao + 8 < datao) || (datao + 8 < 8) || (datao + 8 > buf_size)) {
exif_log (en->log, EXIF_LOG_CODE_CORRUPT_DATA,
"ExifMnoteDataPentax", "Short MakerNote");
return;
}
if (!memcmp(buf + datao, "AOC", 4)) {
if ((buf[datao + 4] == 'I') && (buf[datao + 5] == 'I')) {
n->version = pentaxV3;
n->order = EXIF_BYTE_ORDER_INTEL;
} else if ((buf[datao + 4] == 'M') && (buf[datao + 5] == 'M')) {
n->version = pentaxV3;
n->order = EXIF_BYTE_ORDER_MOTOROLA;
} else {
n->version = pentaxV2;
}
exif_log (en->log, EXIF_LOG_CODE_DEBUG, "ExifMnoteDataPentax",
"Parsing Pentax maker note v%d...", (int)n->version);
datao += 4 + 2;
base = MNOTE_PENTAX2_TAG_BASE;
} else if (!memcmp(buf + datao, "QVC", 4)) {
exif_log (en->log, EXIF_LOG_CODE_DEBUG, "ExifMnoteDataPentax",
"Parsing Casio maker note v2...");
n->version = casioV2;
base = MNOTE_CASIO2_TAG_BASE;
datao += 4 + 2;
} else {
exif_log (en->log, EXIF_LOG_CODE_DEBUG, "ExifMnoteDataPentax",
"Parsing Pentax maker note v1...");
n->version = pentaxV1;
}
c = exif_get_short (buf + datao, n->order);
datao += 2;
exif_mnote_data_pentax_clear (n);
n->entries = exif_mem_alloc (en->mem, sizeof (MnotePentaxEntry) * c);
if (!n->entries) {
EXIF_LOG_NO_MEMORY(en->log, "ExifMnoteDataPentax", sizeof (MnotePentaxEntry) * c);
return;
}
tcount = 0;
for (i = c, o = datao; i; --i, o += 12) {
size_t s;
if ((o + 12 < o) || (o + 12 < 12) || (o + 12 > buf_size)) {
exif_log (en->log, EXIF_LOG_CODE_CORRUPT_DATA,
"ExifMnoteDataPentax", "Short MakerNote");
break;
}
n->entries[tcount].tag        = exif_get_short (buf + o + 0, n->order) + base;
n->entries[tcount].format     = exif_get_short (buf + o + 2, n->order);
n->entries[tcount].components = exif_get_long  (buf + o + 4, n->order);
n->entries[tcount].order      = n->order;
exif_log (en->log, EXIF_LOG_CODE_DEBUG, "ExifMnotePentax",
"Loading entry 0x%x ('%s')...", n->entries[tcount].tag,
mnote_pentax_tag_get_name (n->entries[tcount].tag));
s = exif_format_get_size (n->entries[tcount].format) *
n->entries[tcount].components;
n->entries[tcount].size = s;
if (s) {
size_t dataofs = o + 8;
if (s > 4)
dataofs = exif_get_long (buf + dataofs, n->order) + 6;
if ((dataofs + s < dataofs) || (dataofs + s < s) ||
(dataofs + s > buf_size)) {
exif_log (en->log, EXIF_LOG_CODE_DEBUG,
"ExifMnoteDataPentax", "Tag data past end "
"of buffer (%u > %u)", (unsigned)(dataofs + s), buf_size);
continue;
}
n->entries[tcount].data = exif_mem_alloc (en->mem, s);
if (!n->entries[tcount].data) {
EXIF_LOG_NO_MEMORY(en->log, "ExifMnoteDataPentax", s);
continue;
}
memcpy (n->entries[tcount].data, buf + dataofs, s);
}
++tcount;
}
n->count = tcount;
}

static MagickBooleanType WriteDIBImage(const ImageInfo *image_info,Image *image,
ExceptionInfo *exception)
{
DIBInfo
dib_info;
MagickBooleanType
status;
register const Quantum
*p;
register ssize_t
i,
x;
register unsigned char
*q;
size_t
bytes_per_line;
ssize_t
y;
unsigned char
*dib_data,
*pixels;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickCoreSignature);
assert(image != (Image *) NULL);
assert(image->signature == MagickCoreSignature);
if (image->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",image->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
status=OpenBlob(image_info,image,WriteBinaryBlobMode,exception);
if (status == MagickFalse)
return(status);
(void) TransformImageColorspace(image,sRGBColorspace,exception);
if (image->storage_class == DirectClass)
{
dib_info.number_colors=0;
dib_info.bits_per_pixel=(unsigned short) (image->alpha_trait ? 32 : 24);
}
else
{
dib_info.bits_per_pixel=8;
if (image_info->depth > 8)
dib_info.bits_per_pixel=16;
if (SetImageMonochrome(image,exception) != MagickFalse)
dib_info.bits_per_pixel=1;
dib_info.number_colors=(unsigned int) (dib_info.bits_per_pixel == 16 ? 0 :
(1UL << dib_info.bits_per_pixel));
}
bytes_per_line=4*((image->columns*dib_info.bits_per_pixel+31)/32);
dib_info.size=40;
dib_info.width=(int) image->columns;
dib_info.height=(int) image->rows;
dib_info.planes=1;
dib_info.compression=(unsigned int) (dib_info.bits_per_pixel == 16 ?
BI_BITFIELDS : BI_RGB);
dib_info.image_size=(unsigned int) (bytes_per_line*image->rows);
dib_info.x_pixels=75*39;
dib_info.y_pixels=75*39;
switch (image->units)
{
case UndefinedResolution:
case PixelsPerInchResolution:
{
dib_info.x_pixels=(unsigned int) (100.0*image->resolution.x/2.54);
dib_info.y_pixels=(unsigned int) (100.0*image->resolution.y/2.54);
break;
}
case PixelsPerCentimeterResolution:
{
dib_info.x_pixels=(unsigned int) (100.0*image->resolution.x);
dib_info.y_pixels=(unsigned int) (100.0*image->resolution.y);
break;
}
}
dib_info.colors_important=dib_info.number_colors;
pixels=(unsigned char *) AcquireQuantumMemory(image->rows,MagickMax(
bytes_per_line,image->columns+256UL)*sizeof(*pixels));
if (pixels == (unsigned char *) NULL)
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
(void) memset(pixels,0,dib_info.image_size);
switch (dib_info.bits_per_pixel)
{
case 1:
{
register unsigned char
bit,
byte;
for (y=0; y < (ssize_t) image->rows; y++)
{
p=GetVirtualPixels(image,0,y,image->columns,1,exception);
if (p == (const Quantum *) NULL)
break;
q=pixels+(image->rows-y-1)*bytes_per_line;
bit=0;
byte=0;
for (x=0; x < (ssize_t) image->columns; x++)
{
byte<<=1;
byte|=GetPixelIndex(image,p) != 0 ? 0x01 : 0x00;
bit++;
if (bit == 8)
{
*q++=byte;
bit=0;
byte=0;
}
p+=GetPixelChannels(image);
}
if (bit != 0)
{
*q++=(unsigned char) (byte << (8-bit));
x++;
}
for (x=(ssize_t) (image->columns+7)/8; x < (ssize_t) bytes_per_line; x++)
*q++=0x00;
status=SetImageProgress(image,SaveImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
break;
}
case 8:
{
for (y=0; y < (ssize_t) image->rows; y++)
{
p=GetVirtualPixels(image,0,y,image->columns,1,exception);
if (p == (const Quantum *) NULL)
break;
q=pixels+(image->rows-y-1)*bytes_per_line;
for (x=0; x < (ssize_t) image->columns; x++)
{
*q++=(unsigned char) GetPixelIndex(image,p);
p+=GetPixelChannels(image);
}
for ( ; x < (ssize_t) bytes_per_line; x++)
*q++=0x00;
status=SetImageProgress(image,SaveImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
break;
}
case 16:
{
unsigned short
word;
for (y=0; y < (ssize_t) image->rows; y++)
{
p=GetVirtualPixels(image,0,y,image->columns,1,exception);
if (p == (const Quantum *) NULL)
break;
q=pixels+(image->rows-y-1)*bytes_per_line;
for (x=0; x < (ssize_t) image->columns; x++)
{
word=(unsigned short) ((ScaleColor8to5((unsigned char)
ScaleQuantumToChar(GetPixelRed(image,p))) << 11) | (ScaleColor8to6(
(unsigned char) ScaleQuantumToChar(GetPixelGreen(image,p))) << 5) |
(ScaleColor8to5((unsigned char) ScaleQuantumToChar((unsigned char)
GetPixelBlue(image,p)) << 0)));
*q++=(unsigned char)(word & 0xff);
*q++=(unsigned char)(word >> 8);
p+=GetPixelChannels(image);
}
for (x=(ssize_t) (2*image->columns); x < (ssize_t) bytes_per_line; x++)
*q++=0x00;
status=SetImageProgress(image,SaveImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
break;
}
case 24:
case 32:
{
for (y=0; y < (ssize_t) image->rows; y++)
{
p=GetVirtualPixels(image,0,y,image->columns,1,exception);
if (p == (const Quantum *) NULL)
break;
q=pixels+(image->rows-y-1)*bytes_per_line;
for (x=0; x < (ssize_t) image->columns; x++)
{
*q++=ScaleQuantumToChar(GetPixelBlue(image,p));
*q++=ScaleQuantumToChar(GetPixelGreen(image,p));
*q++=ScaleQuantumToChar(GetPixelRed(image,p));
if (image->alpha_trait != UndefinedPixelTrait)
*q++=ScaleQuantumToChar(GetPixelAlpha(image,p));
p+=GetPixelChannels(image);
}
if (dib_info.bits_per_pixel == 24)
for (x=(ssize_t) (3*image->columns); x < (ssize_t) bytes_per_line; x++)
*q++=0x00;
status=SetImageProgress(image,SaveImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
break;
}
}
if (dib_info.bits_per_pixel == 8)
if (image_info->compression != NoCompression)
{
size_t
length;
length=2UL*(bytes_per_line+2UL)+2UL;
dib_data=(unsigned char *) AcquireQuantumMemory(length,
(image->rows+2UL)*sizeof(*dib_data));
if (dib_data == (unsigned char *) NULL)
{
pixels=(unsigned char *) RelinquishMagickMemory(pixels);
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
}
dib_info.image_size=(unsigned int) EncodeImage(image,bytes_per_line,
pixels,dib_data);
pixels=(unsigned char *) RelinquishMagickMemory(pixels);
pixels=dib_data;
dib_info.compression = BI_RLE8;
}
(void) WriteBlobLSBLong(image,dib_info.size);
(void) WriteBlobLSBLong(image,(unsigned int) dib_info.width);
(void) WriteBlobLSBLong(image,(unsigned int) dib_info.height);
(void) WriteBlobLSBShort(image,(unsigned short) dib_info.planes);
(void) WriteBlobLSBShort(image,dib_info.bits_per_pixel);
(void) WriteBlobLSBLong(image,dib_info.compression);
(void) WriteBlobLSBLong(image,dib_info.image_size);
(void) WriteBlobLSBLong(image,dib_info.x_pixels);
(void) WriteBlobLSBLong(image,dib_info.y_pixels);
(void) WriteBlobLSBLong(image,dib_info.number_colors);
(void) WriteBlobLSBLong(image,dib_info.colors_important);
if (image->storage_class == PseudoClass)
{
if (dib_info.bits_per_pixel <= 8)
{
unsigned char
*dib_colormap;
dib_colormap=(unsigned char *) AcquireQuantumMemory((size_t)
(1UL << dib_info.bits_per_pixel),4*sizeof(*dib_colormap));
if (dib_colormap == (unsigned char *) NULL)
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
q=dib_colormap;
for (i=0; i < (ssize_t) MagickMin(image->colors,dib_info.number_colors); i++)
{
*q++=ScaleQuantumToChar(ClampToQuantum(image->colormap[i].blue));
*q++=ScaleQuantumToChar(ClampToQuantum(image->colormap[i].green));
*q++=ScaleQuantumToChar(ClampToQuantum(image->colormap[i].red));
*q++=(Quantum) 0x0;
}
for ( ; i < (ssize_t) (1L << dib_info.bits_per_pixel); i++)
{
*q++=(Quantum) 0x0;
*q++=(Quantum) 0x0;
*q++=(Quantum) 0x0;
*q++=(Quantum) 0x0;
}
(void) WriteBlob(image,(size_t) (4*(1 << dib_info.bits_per_pixel)),
dib_colormap);
dib_colormap=(unsigned char *) RelinquishMagickMemory(dib_colormap);
}
else
if ((dib_info.bits_per_pixel == 16) &&
(dib_info.compression == BI_BITFIELDS))
{
(void) WriteBlobLSBLong(image,0xf800);
(void) WriteBlobLSBLong(image,0x07e0);
(void) WriteBlobLSBLong(image,0x001f);
}
}
(void) WriteBlob(image,dib_info.image_size,pixels);
pixels=(unsigned char *) RelinquishMagickMemory(pixels);
(void) CloseBlob(image);
return(MagickTrue);
}

static int
write_node(FILE   *out,
tree_t *t,
int    col)
{
inti;
uchar*ptr,
*entity,
*src,
*realsrc,
newsrc[1024];
if (out == NULL)
return (0);
switch (t->markup)
{
case MARKUP_NONE :
if (t->data == NULL)
break;
if (t->preformatted)
{
for (ptr = t->data; *ptr; ptr ++)
fputs((char *)iso8859(*ptr), out);
if (t->data[strlen((char *)t->data) - 1] == '\n')
col = 0;
else
col += strlen((char *)t->data);
}
else
{
if ((col + (int)strlen((char *)t->data)) > 72 && col > 0)
{
putc('\n', out);
col = 0;
}
for (ptr = t->data; *ptr; ptr ++)
fputs((char *)iso8859(*ptr), out);
col += strlen((char *)t->data);
if (col > 72)
{
putc('\n', out);
col = 0;
}
}
break;
case MARKUP_COMMENT :
case MARKUP_UNKNOWN :
fputs("\n<!--", out);
for (ptr = t->data; *ptr; ptr ++)
fputs((char *)iso8859(*ptr), out);
fputs("-->\n", out);
col = 0;
break;
case MARKUP_AREA :
case MARKUP_BODY :
case MARKUP_DOCTYPE :
case MARKUP_ERROR :
case MARKUP_FILE :
case MARKUP_HEAD :
case MARKUP_HTML :
case MARKUP_MAP :
case MARKUP_META :
case MARKUP_TITLE :
break;
case MARKUP_BR :
case MARKUP_CENTER :
case MARKUP_DD :
case MARKUP_DL :
case MARKUP_DT :
case MARKUP_H1 :
case MARKUP_H2 :
case MARKUP_H3 :
case MARKUP_H4 :
case MARKUP_H5 :
case MARKUP_H6 :
case MARKUP_H7 :
case MARKUP_H8 :
case MARKUP_H9 :
case MARKUP_H10 :
case MARKUP_H11 :
case MARKUP_H12 :
case MARKUP_H13 :
case MARKUP_H14 :
case MARKUP_H15 :
case MARKUP_HR :
case MARKUP_LI :
case MARKUP_OL :
case MARKUP_P :
case MARKUP_PRE :
case MARKUP_TABLE :
case MARKUP_TR :
case MARKUP_UL :
if (col > 0)
{
putc('\n', out);
col = 0;
}
default :
if (t->markup == MARKUP_IMG && OutputFiles &&
(src = htmlGetVariable(t, (uchar *)"SRC")) != NULL &&
(realsrc = htmlGetVariable(t, (uchar *)"REALSRC")) != NULL)
{
if (file_method((char *)src) == NULL &&
src[0] != '/' && src[0] != '\\' &&
(!isalpha(src[0]) || src[1] != ':'))
{
image_copy((char *)src, (char *)realsrc, OutputPath);
strlcpy((char *)newsrc, file_basename((char *)src), sizeof(newsrc));
htmlSetVariable(t, (uchar *)"SRC", newsrc);
}
}
if (t->markup != MARKUP_EMBED)
{
col += fprintf(out, "<%s", _htmlMarkups[t->markup]);
for (i = 0; i < t->nvars; i ++)
{
if (strcasecmp((char *)t->vars[i].name, "BREAK") == 0 &&
t->markup == MARKUP_HR)
continue;
if (strcasecmp((char *)t->vars[i].name, "REALSRC") == 0 &&
t->markup == MARKUP_IMG)
continue;
if (strncasecmp((char *)t->vars[i].name, "_HD_", 4) == 0)
continue;
if (col > 72 && !t->preformatted)
{
putc('\n', out);
col = 0;
}
if (col > 0)
{
putc(' ', out);
col ++;
}
if (t->vars[i].value == NULL)
col += fprintf(out, "%s", t->vars[i].name);
else
{
col += fprintf(out, "%s=\"", t->vars[i].name);
for (ptr = t->vars[i].value; *ptr; ptr ++)
{
entity = iso8859(*ptr);
fputs((char *)entity, out);
col += strlen((char *)entity);
}
putc('\"', out);
col ++;
}
}
putc('>', out);
col ++;
if (col > 72 && !t->preformatted)
{
putc('\n', out);
col = 0;
}
}
break;
}
return (col);
}

void
server_cb(void *arg)
{
nano_work     *work = arg;
nng_msg       *msg  = NULL;
nng_msg       *smsg = NULL;
int            rv;
mqtt_msg_info *msg_info;
switch (work->state) {
case INIT:
work->state = RECV;
if (work->proto == PROTO_MQTT_BROKER) {
log_debug("INIT ^^^^^^^^ ctx [%d] ^^^^^^^^ \n", work->ctx.id);
nng_ctx_recv(work->ctx, work->aio);
} else {
log_debug("INIT ^^^^^^^^ extra ctx [%d] ^^^^^^^^ \n", work->extra_ctx.id);
nng_ctx_recv(work->extra_ctx, work->aio);
}
break;
case RECV:
log_debug("RECV  ^^^^ ctx%d ^^^^\n", work->ctx.id);
if ((rv = nng_aio_result(work->aio)) != 0) {
log_warn("RECV nng aio result error: %d", rv);
work->state = RECV;
if (work->proto == PROTO_MQTT_BROKER) {
nng_ctx_recv(work->ctx, work->aio);
break;
} else {
log_info("bridge connection closed with reason %d\n", rv);
if (rv != NNG_ECONNSHUT) {
nng_ctx_recv(work->extra_ctx, work->aio);
break;
}
}
}
if ((msg = nng_aio_get_msg(work->aio)) == NULL) {
nng_fatal("RECV NULL MSG", rv);
}
if (work->proto == PROTO_MQTT_BRIDGE) {
uint8_t type;
type = nng_msg_get_type(msg);
if (type == CMD_CONNACK) {
log_info("bridge client is connected!");
} else if (type != CMD_PUBLISH) {
work->state = RECV;
nng_msg_free(msg);
nng_ctx_recv(work->extra_ctx, work->aio);
break;
} else {
conn_param_clone(nng_msg_get_conn_param(msg));
}
} else if (work->proto == PROTO_HTTP_SERVER ||
work->proto == PROTO_AWS_BRIDGE) {
nng_msg *decode_msg = NULL;
if (decode_common_mqtt_msg(&decode_msg, msg) != 0 ||
nng_msg_get_type(decode_msg) != CMD_PUBLISH) {
conn_param_free(nng_msg_get_conn_param(decode_msg));
work->state = RECV;
nng_ctx_recv(work->extra_ctx, work->aio);
break;
}
msg = decode_msg;
nng_msg_set_cmd_type(msg, CMD_PUBLISH);
}
work->msg       = msg;
work->pid       = nng_msg_get_pipe(work->msg);
work->cparam    = nng_msg_get_conn_param(work->msg);
work->proto_ver = conn_param_get_protover(work->cparam);
work->flag      = nng_msg_cmd_type(msg);
if (work->flag == CMD_SUBSCRIBE) {
smsg = work->msg;
work->msg_ret = NULL;
if ((work->sub_pkt = nng_alloc(
sizeof(packet_subscribe))) == NULL)
log_error("nng_alloc");
memset(work->sub_pkt, '\0', sizeof(packet_subscribe));
if ((rv = decode_sub_msg(work)) != 0 ||
(rv = sub_ctx_handle(work)) != 0) {
work->code = rv;
log_error("sub_handler: [%d]", rv);
}
if (work->code != SUCCESS) {
if (work->msg_ret)
cvector_free(work->msg_ret);
if (work->sub_pkt)
sub_pkt_free(work->sub_pkt);
conn_param_free(work->cparam);
work->state = CLOSE;
nng_aio_finish(work->aio, 0);
break;
}
if (0 != (rv = encode_suback_msg(smsg, work)))
log_error("error in encode suback: [%d]", rv);
sub_pkt_free(work->sub_pkt);
work->msg = NULL;
if (work->msg_ret) {
log_debug("retain msg [%p] size [%ld] \n",
work->msg_ret,
cvector_size(work->msg_ret));
for (int i = 0;
i < cvector_size(work->msg_ret) &&
check_msg_exp(work->msg_ret[i],
nng_mqtt_msg_get_publish_property(
work->msg_ret[i]));
i++) {
nng_msg *m = work->msg_ret[i];
if (!work->config->sqlite.enable) {
nng_msg_clone(m);
}
work->msg = m;
nng_aio_set_msg(work->aio, work->msg);
nng_aio_set_prov_data(work->aio, &work->pid.id);
nng_ctx_send(work->ctx, work->aio);
}
cvector_free(work->msg_ret);
}
nng_msg_set_cmd_type(smsg, CMD_SUBACK);
nng_aio_set_prov_data(work->aio, &work->pid.id);
nng_aio_set_msg(work->aio, smsg);
work->msg   = NULL;
work->state = SEND;
nng_ctx_send(work->ctx, work->aio);
smsg = NULL;
nng_aio_finish(work->aio, 0);
break;
} else if (work->flag == CMD_UNSUBSCRIBE) {
smsg = work->msg;
if ((work->unsub_pkt = nng_alloc(
sizeof(packet_unsubscribe))) == NULL)
log_error("nng_alloc");
if ((rv = decode_unsub_msg(work)) != 0 ||
(rv = unsub_ctx_handle(work)) != 0) {
log_error("unsub_handler [%d]", rv);
}
if (0 != (rv = encode_unsuback_msg(smsg, work)))
log_error("in unsuback [%d]", rv);
unsub_pkt_free(work->unsub_pkt);
nng_aio_set_prov_data(work->aio, &work->pid.id);
nng_aio_set_msg(work->aio, work->msg);
work->msg   = NULL;
work->state = SEND;
nng_ctx_send(work->ctx, work->aio);
smsg = NULL;
nng_aio_finish(work->aio, 0);
break;
} else if (work->flag == CMD_PUBLISH) {
if (work->proto_ver == 5) {
nng_msg_set_cmd_type(msg, CMD_PUBLISH_V5);
} else {
nng_msg_set_cmd_type(msg, CMD_PUBLISH);
}
work->code = handle_pub(
work, work->pipe_ct, work->proto_ver, false);
if (work->proto == PROTO_HTTP_SERVER ||
work->proto == PROTO_AWS_BRIDGE) {
nng_msg *rep_msg;
nng_msg_alloc(&rep_msg, 0);
nng_aio_set_msg(work->aio, rep_msg);
if (work->code == SUCCESS)
work->state = WAIT;
else
work->state = SEND;
nng_ctx_send(work->extra_ctx, work->aio);
break;
}
if (work->code != SUCCESS) {
if (work->proto != PROTO_MQTT_BROKER) {
work->state = SEND;
nng_aio_finish(work->aio, 0);
break;
}
work->state = CLOSE;
free_pub_packet(work->pub_packet);
work->pub_packet = NULL;
cvector_free(work->pipe_ct->msg_infos);
conn_param_free(work->cparam);
nng_aio_finish(work->aio, 0);
break;
}
} else if (work->flag == CMD_CONNACK) {
uint8_t *body        = nng_msg_body(work->msg);
uint8_t  reason_code = *(body + 1);
if (work->proto == PROTO_MQTT_BROKER) {
nng_aio_set_prov_data(work->aio, &work->pid.id);
nng_msg_clone(work->msg);
nng_aio_set_msg(work->aio, work->msg);
nng_ctx_send(work->ctx, work->aio);
}
smsg = nano_msg_notify_connect(work->cparam, reason_code);
webhook_entry(work, reason_code);
nng_msg_set_cmd_type(smsg, CMD_PUBLISH);
work->flag = CMD_PUBLISH;
nng_msg_free(work->msg);
work->msg = smsg;
handle_pub(work, work->pipe_ct,
MQTT_PROTOCOL_VERSION_v311, true);
} else if (work->flag == CMD_DISCONNECT_EV) {
webhook_entry(work, 0);
nng_msg_set_cmd_type(msg, CMD_PUBLISH);
work->flag = CMD_PUBLISH;
handle_pub(work, work->pipe_ct,
MQTT_PROTOCOL_VERSION_v311, true);
if (dbhash_check_id(work->pid.id)) {
destroy_sub_client(work->pid.id, work->db);
}
if (conn_param_get_will_flag(work->cparam) == 0 ||
!conn_param_get_will_topic(work->cparam) ||
!conn_param_get_will_msg(work->cparam)) {
conn_param_free(work->cparam);
} else {
work->state = END;
nng_aio_finish(work->aio, 0);
break;
}
}
work->state = WAIT;
nng_aio_finish(work->aio, 0);
break;
case WAIT:
log_debug("WAIT ^^^^ ctx%d ^^^^", work->ctx.id);
if (nng_msg_get_type(work->msg) == CMD_PUBLISH) {
if ((rv = nng_aio_result(work->aio)) != 0) {
log_error("WAIT nng aio result error: %d", rv);
nng_fatal("WAIT nng_ctx_recv/send", rv);
}
smsg      = work->msg; cvector(mqtt_msg_info) msg_infos;
msg_infos = work->pipe_ct->msg_infos;
log_trace("total pipes: %ld", cvector_size(msg_infos));
if (cvector_size(msg_infos))
if (encode_pub_message(smsg, work, PUBLISH))
for (int i = 0; i < cvector_size(msg_infos) && rv== 0; ++i) {
msg_info = &msg_infos[i];
nng_msg_clone(smsg);
work->pid.id = msg_info->pipe;
nng_aio_set_prov_data(work->aio, &work->pid.id);
work->msg = smsg;
nng_aio_set_msg(work->aio, work->msg);
nng_ctx_send(work->ctx, work->aio);
}
work->msg = smsg;
if (work->config->bridge_mode) {
bridge_handler(work);
#if defined(SUPP_AWS_BRIDGE)
aws_bridge_forward(work);
#endif
}
conf_web_hook *hook_conf   = &(work->config->web_hook);
uint8_t rule_opt = RULE_ENG_OFF;
#if defined(SUPP_RULE_ENGINE)
rule_opt = work->config->rule_eng.option;
#endif
if (hook_conf->enable || rule_opt != RULE_ENG_OFF) {
work->state = SEND;
nng_aio_finish(work->aio, 0);
break;
}
nng_msg_free(work->msg);
smsg = NULL;
work->msg = NULL;
conn_param_free(work->cparam);
free_pub_packet(work->pub_packet);
work->pub_packet = NULL;
cvector_free(msg_infos);
work->pipe_ct->msg_infos = NULL;
init_pipe_content(work->pipe_ct);
work->state = RECV;
if (work->proto != PROTO_MQTT_BROKER) {
nng_ctx_recv(work->extra_ctx, work->aio);
} else {
nng_ctx_recv(work->ctx, work->aio);
}
} else if (nng_msg_cmd_type(work->msg) == CMD_PUBACK ||
nng_msg_cmd_type(work->msg) == CMD_PUBREL ||
nng_msg_cmd_type(work->msg) == CMD_PUBCOMP) {
nng_msg_free(work->msg);
work->msg   = NULL;
work->state = RECV;
nng_ctx_recv(work->ctx, work->aio);
break;
} else {
log_debug("broker has nothing to do");
if (work->msg != NULL)
nng_msg_free(work->msg);
work->msg   = NULL;
work->state = RECV;
nng_ctx_recv(work->ctx, work->aio);
break;
}
break;
case SEND:
log_debug("SEND ^^^^ ctx%d ^^^^", work->ctx.id);
#if defined(SUPP_RULE_ENGINE)
if (work->flag == CMD_PUBLISH && work->config->rule_eng.option != RULE_ENG_OFF) {
rule_engine_insert_sql(work);
}
#endif
webhook_entry(work, 0);
if (NULL != work->msg) {
nng_msg_free(work->msg);
work->msg = NULL;
}
if ((rv = nng_aio_result(work->aio)) != 0) {
nng_fatal("SEND nng_ctx_send", rv);
}
if (work->pub_packet != NULL) {
free_pub_packet(work->pub_packet);
work->pub_packet = NULL;
}
if (work->pipe_ct->msg_infos != NULL) {
cvector_free(work->pipe_ct->msg_infos);
work->pipe_ct->msg_infos = NULL;
init_pipe_content(work->pipe_ct);
}
conn_param_free(work->cparam);
work->state = RECV;
work->flag  = 0;
if (work->proto == PROTO_MQTT_BROKER) {
nng_ctx_recv(work->ctx, work->aio);
} else{
nng_ctx_recv(work->extra_ctx, work->aio);
}
break;
case END:
log_debug("END ^^^^ ctx%d ^^^^ ", work->ctx.id);
if (nng_msg_get_type(work->msg) == CMD_PUBLISH) {
if ((rv = nng_aio_result(work->aio)) != 0) {
log_error("WAIT nng aio result error: %d", rv);
nng_fatal("WAIT nng_ctx_recv/send", rv);
}
smsg      = work->msg; work->msg = NULL;
cvector(mqtt_msg_info) msg_infos;
msg_infos = work->pipe_ct->msg_infos;
log_debug("total pipes: %ld", cvector_size(msg_infos));
if (cvector_size(msg_infos))
if (encode_pub_message(smsg, work, PUBLISH))
for (int i=0; i<cvector_size(msg_infos); ++i) {
msg_info = &msg_infos[i];
nng_msg_clone(smsg);
work->pid.id = msg_info->pipe;
nng_aio_set_prov_data(work->aio, &work->pid.id);
work->msg = smsg;
nng_aio_set_msg(work->aio, work->msg);
nng_ctx_send(work->ctx, work->aio);
}
webhook_entry(work, 0);
nng_msg_free(smsg);
smsg = NULL;
work->msg = NULL;
free_pub_packet(work->pub_packet);
work->pub_packet = NULL;
cvector_free(work->pipe_ct->msg_infos);
work->pipe_ct->msg_infos = NULL;
init_pipe_content(work->pipe_ct);
if (conn_param_get_will_flag(work->cparam)) {
msg = nano_pubmsg_composer(&msg,
conn_param_get_will_retain(work->cparam),
conn_param_get_will_qos(work->cparam),
(mqtt_string *) conn_param_get_will_msg(
work->cparam),
(mqtt_string *) conn_param_get_will_topic(
work->cparam),
conn_param_get_protover(work->cparam),
nng_clock());
work->msg = msg;
work->flag = CMD_PUBLISH;
if (conn_param_get_protover(work->cparam) == 5) {
property *will_property =
conn_param_get_will_property(
work->cparam);
nng_msg_set_cmd_type(
msg, CMD_PUBLISH_V5);
handle_pub(work, work->pipe_ct,
MQTT_PROTOCOL_VERSION_v5, false);
work->pub_packet->var_header.publish
.properties = property_pub_by_will(
will_property);
work->pub_packet->var_header.publish
.prop_len = get_properties_len(
work->pub_packet->var_header
.publish.properties);
} else {
nng_msg_set_cmd_type(msg, CMD_PUBLISH);
handle_pub(work, work->pipe_ct,
MQTT_PROTOCOL_VERSION_v311, false);
}
work->state = WAIT;
nng_aio_finish(work->aio, 0);
} else {
if (work->msg != NULL)
nng_msg_free(work->msg);
work->msg = NULL;
work->state = RECV;
if (work->proto == PROTO_MQTT_BROKER) {
nng_ctx_recv(work->ctx, work->aio);
} else {
nng_ctx_recv(work->extra_ctx, work->aio);
}
}
}
conn_param_free(work->cparam);
break;
case CLOSE:
log_debug(" CLOSE ^^^^ ctx%d ^^^^", work->ctx.id);
smsg = nano_dismsg_composer(work->code, NULL, NULL, NULL);
nng_msg_free(work->msg);
work->msg = smsg;
nng_aio_set_prov_data(work->aio, &work->pid.id);
nng_aio_set_msg(work->aio, work->msg);
nng_ctx_send(work->ctx, work->aio); 
work->code = SUCCESS;
work->state = RECV;
nng_ctx_recv(work->ctx, work->aio);
break;
default:
nng_fatal("bad state!", NNG_ESTATE);
break;
}
}

static GF_Err nhmldmx_send_sample(GF_Filter *filter, GF_NHMLDmxCtx *ctx)
{
GF_XMLNode *node, *childnode;
u64 sample_duration = 0;
char szMediaTemp[GF_MAX_PATH], szXmlFrom[1000], szXmlTo[1000];
char *szSubSampleName = ctx->is_dims ? "DIMSSubUnit" : "NHNTSubSample";
while ((node = (GF_XMLNode *) gf_list_enum(ctx->root->content, &ctx->current_child_idx))) {
u8 *data;
GF_FilterPacket *pck;
u32 j, dims_flags;
GF_FilterSAPType sap_type;
GF_XMLAttribute *att;
u64 dts=0;
GF_Err e=GF_OK;
s32 cts_offset;
u64 offset=0, byte_offset = GF_FILTER_NO_BO;
u32 nb_subsamples = 0;
Bool redundant_rap, append, has_subbs, first_subsample_is_first = GF_FALSE;
u32 compress_type;
char *base_data = NULL;
if (node->type) continue;
if (stricmp(node->name, ctx->is_dims ? "DIMSUnit" : "NHNTSample") ) continue;
strcpy(szMediaTemp, "");
strcpy(szXmlFrom, "");
strcpy(szXmlTo, "");
ctx->samp_buffer_size = 0;
dims_flags = 0;
append = GF_FALSE;
compress_type = ctx->compress_type;
sample_duration = 0;
redundant_rap = 0;
sap_type = ctx->has_sap ? GF_FILTER_SAP_NONE : GF_FILTER_SAP_1;
cts_offset = 0;
if (ctx->last_dts != GF_FILTER_NO_TS)
dts = ctx->last_dts;
else
dts = 0;
ctx->sample_num++;
j=0;
while ( (att = (GF_XMLAttribute *)gf_list_enum(node->attributes, &j))) {
if (!stricmp(att->name, "DTS") || !stricmp(att->name, "time")) {
u32 h, m, s, ms;
u64 dst_val;
if (strchr(att->value, ':') && sscanf(att->value, "%u:%u:%u.%u", &h, &m, &s, &ms) == 4) {
dts = (u64) ( (Double) ( ((h*3600.0 + m*60.0 + s)*1000 + ms) / 1000.0) * ctx->timescale );
} else if (sscanf(att->value, ""LLU, &dst_val)==1) {
dts = dst_val;
}
}
else if (!stricmp(att->name, "CTSOffset")) cts_offset = atoi(att->value);
else if (!stricmp(att->name, "isRAP") ) {
sap_type = (!stricmp(att->value, "yes")) ? GF_FILTER_SAP_1 : GF_FILTER_SAP_NONE;
}
else if (!stricmp(att->name, "isSyncShadow")) redundant_rap = !stricmp(att->value, "yes") ? 1 : 0;
else if (!stricmp(att->name, "SAPType") ) sap_type = atoi(att->value);
else if (!stricmp(att->name, "mediaOffset")) offset = (s64) atof(att->value) ;
else if (!stricmp(att->name, "dataLength")) ctx->samp_buffer_size = atoi(att->value);
else if (!stricmp(att->name, "mediaFile")) {
if (!strncmp(att->value, "data:", 5)) {
char *base = strstr(att->value, "base64,");
if (!base) {
GF_LOG(GF_LOG_WARNING, GF_LOG_PARSER, ("[NHMLDmx] Data encoding scheme not recognized in sample %d - skipping\n", ctx->sample_num));
} else {
base_data = att->value;
}
} else if (!strnicmp(att->value, "gmem:GF_LOG(GF_LOG_WARNING, GF_LOG_PARSER, ("[NHMLDmx] Invalid url %s for NHML import\n", att->value));
} else {
char *url = gf_url_concatenate(ctx->src_url, att->value);
if (!url) {
GF_LOG(GF_LOG_WARNING, GF_LOG_PARSER, ("[NHMLDmx] Failed to get full url for %s\n", att->value));
} else {
strncpy(szMediaTemp, url, GF_MAX_PATH-1);
szMediaTemp[GF_MAX_PATH-1] = 0;
gf_free(url);
}
}
}
else if (!stricmp(att->name, "xmlFrom")) strcpy(szXmlFrom, att->value);
else if (!stricmp(att->name, "xmlTo")) strcpy(szXmlTo, att->value);
else if (!stricmp(att->name, "is-Scene") && !stricmp(att->value, "yes"))
dims_flags |= GF_DIMS_UNIT_S;
else if (!stricmp(att->name, "is-RAP") && !stricmp(att->value, "yes")) {
dims_flags |= GF_DIMS_UNIT_M;
sap_type = GF_FILTER_SAP_1;
}
else if (!stricmp(att->name, "is-redundant") && !stricmp(att->value, "yes"))
dims_flags |= GF_DIMS_UNIT_I;
else if (!stricmp(att->name, "redundant-exit") && !stricmp(att->value, "yes"))
dims_flags |= GF_DIMS_UNIT_D;
else if (!stricmp(att->name, "priority") && !stricmp(att->value, "high"))
dims_flags |= GF_DIMS_UNIT_P;
else if (!stricmp(att->name, "compress") && !stricmp(att->value, "yes"))
dims_flags |= GF_DIMS_UNIT_C;
else if (!stricmp(att->name, "duration") )
sscanf(att->value, ""LLU, &sample_duration);
}
if (sap_type==GF_FILTER_SAP_1)
dims_flags |= GF_DIMS_UNIT_M;
if (ctx->is_dims)
compress_type = (dims_flags & GF_DIMS_UNIT_C) ? 2 : 0 ;
if (ctx->is_img) sample_duration = ctx->duration.den;
has_subbs = GF_FALSE;
j=0;
while ((childnode = (GF_XMLNode *) gf_list_enum(node->content, &j))) {
if (childnode->type) continue;
if (!stricmp(childnode->name, "BS")) {
has_subbs = GF_TRUE;
break;
}
}
if (strlen(szXmlFrom) && strlen(szXmlTo)) {
char *xml_file;
if (strlen(szMediaTemp)) xml_file = szMediaTemp;
else xml_file = ctx->media_file;
ctx->samp_buffer_size = 0;
e = nhml_sample_from_xml(ctx, xml_file, szXmlFrom, szXmlTo);
} else if (ctx->is_dims && !strlen(szMediaTemp)) {
char *content = gf_xml_dom_serialize(node, GF_TRUE, GF_FALSE);
ctx->samp_buffer_size = 3 + (u32) strlen(content);
if (ctx->samp_buffer_alloc < ctx->samp_buffer_size) {
ctx->samp_buffer_alloc = ctx->samp_buffer_size;
ctx->samp_buffer = gf_realloc(ctx->samp_buffer, ctx->samp_buffer_size);
}
nhml_get_bs(&ctx->bs_w, ctx->samp_buffer, ctx->samp_buffer_size, GF_BITSTREAM_WRITE);
gf_bs_write_u16(ctx->bs_w, ctx->samp_buffer_size - 2);
gf_bs_write_u8(ctx->bs_w, (u8) dims_flags);
gf_bs_write_data(ctx->bs_w, content, (ctx->samp_buffer_size - 3));
gf_free(content);
if (ctx->last_dts == dts)
append = GF_TRUE;
} else if (has_subbs) {
gf_bs_reassign_buffer(ctx->bs_w, ctx->samp_buffer, ctx->samp_buffer_alloc);
gf_xml_parse_bit_sequence_bs(node, ctx->src_url, ctx->bs_w);
gf_bs_get_content(ctx->bs_w, &ctx->samp_buffer, &ctx->samp_buffer_size);
if (ctx->samp_buffer_size > ctx->samp_buffer_alloc)
ctx->samp_buffer_alloc = ctx->samp_buffer_size;
} else if (base_data) {
char *start = strchr(base_data, ',');
if (start) {
u32 len = (u32)strlen(start+1);
if (len > ctx->samp_buffer_alloc) {
ctx->samp_buffer_alloc = len;
ctx->samp_buffer = gf_realloc(ctx->samp_buffer, sizeof(char)*ctx->samp_buffer_alloc);
}
ctx->samp_buffer_size = gf_base64_decode(start, len, ctx->samp_buffer, ctx->samp_buffer_alloc);
}
} else {
Bool close = GF_FALSE;
FILE *f = ctx->mdia;
j = 0;
while ((childnode = (GF_XMLNode *)gf_list_enum(node->content, &j))) {
if (childnode->type) continue;
if (!stricmp(childnode->name, szSubSampleName)) {
nb_subsamples++;
}
}
if (strlen(szMediaTemp)) {
f = gf_fopen(szMediaTemp, "rb");
if (!f) {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[NHMLDmx] import failure in sample %d: file %s not found", ctx->sample_num, close ? szMediaTemp : ctx->media_file));
return GF_NON_COMPLIANT_BITSTREAM;
}
close = GF_TRUE;
if (offset) gf_fseek(f, offset, SEEK_SET);
} else {
if (!offset) offset = ctx->media_done;
byte_offset = offset;
}
if (f) {
if (!ctx->samp_buffer_size) {
u64 ssize = gf_fsize(f);
assert(ssize < 0x80000000);
ctx->samp_buffer_size = (u32) ssize;
}
gf_fseek(f, offset, SEEK_SET);
if (ctx->is_dims) {
u32 read;
if (ctx->samp_buffer_size + 3 > ctx->samp_buffer_alloc) {
ctx->samp_buffer_alloc = ctx->samp_buffer_size + 3;
ctx->samp_buffer = (char*)gf_realloc(ctx->samp_buffer, sizeof(char) * ctx->samp_buffer_alloc);
}
nhml_get_bs(&ctx->bs_w, ctx->samp_buffer, ctx->samp_buffer_alloc, GF_BITSTREAM_WRITE);
gf_bs_write_u16(ctx->bs_w, ctx->samp_buffer_size+1);
gf_bs_write_u8(ctx->bs_w, (u8) dims_flags);
read = (u32) gf_fread( ctx->samp_buffer + 3, ctx->samp_buffer_size, f);
if (ctx->samp_buffer_size != read) {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[NHMLDmx] Failed to fully read sample %d: dataLength %d read %d\n", ctx->sample_num, ctx->samp_buffer_size, read));
}
ctx->samp_buffer_size += 3;
if (ctx->last_dts == dts)
append = GF_TRUE;
} else {
u32 read;
if (ctx->samp_buffer_alloc < ctx->samp_buffer_size) {
ctx->samp_buffer_alloc = ctx->samp_buffer_size;
ctx->samp_buffer = (char*)gf_realloc(ctx->samp_buffer, sizeof(char) * ctx->samp_buffer_alloc);
}
read = (u32) gf_fread(ctx->samp_buffer, ctx->samp_buffer_size, f);
if (ctx->samp_buffer_size != read) {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[NHMLDmx] Failed to fully read sample %d: dataLength %d read %d\n", ctx->sample_num, ctx->samp_buffer_size, read));
}
}
if (close) gf_fclose(f);
} else if (!nb_subsamples) {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[NHMLDmx] No media file associated with sample %d!\n", ctx->sample_num));
e = GF_URL_ERROR;
}
}
if (e) return e;
if (ctx->is_dims) {
if (strstr(ctx->samp_buffer + 3, "svg ")) dims_flags |= GF_DIMS_UNIT_S;
if (dims_flags & GF_DIMS_UNIT_S) dims_flags |= GF_DIMS_UNIT_P;
ctx->samp_buffer[2] = dims_flags;
}
if (compress_type) {
#ifndef GPAC_DISABLE_ZLIB
e = compress_sample_data(ctx, compress_type, ctx->use_dict ? &ctx->dictionary : NULL, ctx->is_dims ? 3 : 0);
if (e) return e;
if (ctx->is_dims) {
nhml_get_bs(&ctx->bs_w, ctx->samp_buffer, ctx->samp_buffer_size, GF_BITSTREAM_WRITE);
gf_bs_write_u16(ctx->bs_w, ctx->samp_buffer_size-2);
}
#else
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[NHMLDmx] Error: your version of GPAC was compiled with no libz support. Abort."));
return GF_NOT_SUPPORTED;
#endif
}
if (ctx->is_dims && (ctx->samp_buffer_size > 0xFFFF)) {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[NHMLDmx] DIMS import failure: sample %d data is too long - maximum size allowed: 65532 bytes", ctx->sample_num));
return GF_NON_COMPLIANT_BITSTREAM;
}
if (ctx->samp_buffer_size) {
pck = gf_filter_pck_new_alloc(ctx->opid, ctx->samp_buffer_size, &data);
if (!pck) return GF_OUT_OF_MEM;
memcpy(data, ctx->samp_buffer, ctx->samp_buffer_size);
gf_filter_pck_set_framing(pck, append ? GF_FALSE : GF_TRUE, nb_subsamples ? GF_FALSE : GF_TRUE);
if (!append) {
gf_filter_pck_set_sap(pck, sap_type);
gf_filter_pck_set_dts(pck, dts);
gf_filter_pck_set_cts(pck, dts+cts_offset);
if (redundant_rap && !ctx->is_dims) gf_filter_pck_set_dependency_flags(pck, 0x1);
if (sample_duration || ctx->dts_inc)
gf_filter_pck_set_duration(pck, sample_duration ? (u32) sample_duration : ctx->dts_inc);
if (byte_offset != GF_FILTER_NO_BO)
gf_filter_pck_set_byte_offset(pck, byte_offset);
if (ctx->in_seek) {
if (dts+cts_offset >= ctx->start_range * ctx->timescale)
ctx->in_seek = GF_FALSE;
else
gf_filter_pck_set_seek_flag(pck, GF_TRUE);
}
}
gf_filter_pck_send(pck);
} else {
first_subsample_is_first = GF_TRUE;
}
if (nb_subsamples) {
if (ctx->samp_buffer_alloc<14*nb_subsamples) {
ctx->samp_buffer_alloc = 14*nb_subsamples;
ctx->samp_buffer = gf_realloc(ctx->samp_buffer, ctx->samp_buffer_alloc);
}
assert(ctx->samp_buffer);
nhml_get_bs(&ctx->bs_w, ctx->samp_buffer, ctx->samp_buffer_alloc, GF_BITSTREAM_WRITE);
}
j = 0;
while (!append && nb_subsamples && (childnode = (GF_XMLNode *)gf_list_enum(node->content, &j))) {
if (childnode->type) continue;
if (!stricmp(childnode->name, szSubSampleName)) {
u32 k = 0;
while ((att = (GF_XMLAttribute *)gf_list_enum(childnode->attributes, &k))) {
if (!stricmp(att->name, "mediaFile")) {
u64 subsMediaFileSize = 0;
FILE *f = NULL;
char *sub_file_url = gf_url_concatenate(ctx->src_url, att->value);
if (sub_file_url) {
f = gf_fopen(sub_file_url, "rb");
gf_free(sub_file_url);
}
if (!f) {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[NHMLDmx] Error: mediaFile \"%s\" not found for subsample in sample %d. Abort.\n", att->value, ctx->sample_num));
return GF_URL_ERROR;
}
subsMediaFileSize = gf_fsize(f);
assert(subsMediaFileSize < 0x80000000);
pck = gf_filter_pck_new_alloc(ctx->opid, (u32) subsMediaFileSize, &data);
if (!pck) {
gf_fclose(f);
return GF_OUT_OF_MEM;
}
subsMediaFileSize = (u32) gf_fread(data, (u32) subsMediaFileSize, f);
gf_fclose(f);
nb_subsamples--;
if (first_subsample_is_first) {
gf_filter_pck_set_framing(pck, GF_TRUE, nb_subsamples ? GF_FALSE : GF_TRUE);
gf_filter_pck_set_sap(pck, sap_type);
gf_filter_pck_set_dts(pck, dts);
gf_filter_pck_set_cts(pck, dts+cts_offset);
if (redundant_rap && !ctx->is_dims) gf_filter_pck_set_dependency_flags(pck, 0x1);
if (sample_duration || ctx->dts_inc)
gf_filter_pck_set_duration(pck, sample_duration ? (u32) sample_duration : ctx->dts_inc);
if (ctx->in_seek) {
if (dts+cts_offset >= ctx->start_range * ctx->timescale)
ctx->in_seek = GF_FALSE;
else
gf_filter_pck_set_seek_flag(pck, GF_TRUE);
}
first_subsample_is_first = GF_FALSE;
} else {
gf_filter_pck_set_framing(pck, GF_FALSE, nb_subsamples ? GF_FALSE : GF_TRUE);
}
gf_bs_write_u32(ctx->bs_w, 0); gf_bs_write_u32(ctx->bs_w, (u32) subsMediaFileSize);
gf_bs_write_u32(ctx->bs_w, 0); gf_bs_write_u8(ctx->bs_w, 0); gf_bs_write_u8(ctx->bs_w, 0); 
if (!nb_subsamples) {
u32 subs_size = (u32) gf_bs_get_position(ctx->bs_w);
gf_filter_pck_set_property(pck, GF_PROP_PCK_SUBS, &PROP_DATA(ctx->samp_buffer, subs_size) );
}
gf_filter_pck_send(pck);
}
}
}
}
ctx->last_dts = dts;
if (sample_duration)
ctx->last_dts += sample_duration;
else
ctx->last_dts += ctx->dts_inc;
ctx->media_done += ctx->samp_buffer_size;
if (gf_filter_pid_would_block(ctx->opid))
return GF_OK;
}
ctx->parsing_state = 2;
return GF_OK;
}

uint32_t
njs_string_trim(const njs_value_t *value, njs_string_prop_t *string,
unsigned mode)
{
uint32_t              cp, trim;
const u_char          *p, *prev, *start, *end;
njs_unicode_decode_t  ctx;
trim = 0;
njs_string_prop(string, value);
start = string->start;
end = string->start + string->size;
if (njs_is_byte_or_ascii_string(string)) {
if (mode & NJS_TRIM_START) {
for ( ;; ) {
if (start == end) {
break;
}
if (njs_is_whitespace(*start)) {
start++;
trim++;
continue;
}
break;
}
}
if (mode & NJS_TRIM_END) {
for ( ;; ) {
if (start == end) {
break;
}
end--;
if (njs_is_whitespace(*end)) {
trim++;
continue;
}
end++;
break;
}
}
} else {
if (mode & NJS_TRIM_START) {
njs_utf8_decode_init(&ctx);
for ( ;; ) {
if (start == end) {
break;
}
p = start;
cp = njs_utf8_decode(&ctx, &start, end);
if (njs_utf8_is_whitespace(cp)) {
trim++;
continue;
}
start = p;
break;
}
}
if (mode & NJS_TRIM_END) {
prev = end;
njs_utf8_decode_init(&ctx);
for ( ;; ) {
if (start == prev) {
break;
}
prev = njs_utf8_prev(prev);
p = prev;
cp = njs_utf8_decode(&ctx, &p, end);
if (njs_utf8_is_whitespace(cp)) {
trim++;
continue;
}
end = p;
break;
}
}
}
if (start == end) {
string->length = 0;
string->size = 0;
return trim;
}
string->start = (u_char *) start;
string->size = end - start;
if (string->length != 0) {
string->length -= trim;
}
return trim;
}

njs_int_t
njs_await_fulfilled(njs_vm_t *vm, njs_value_t *args, njs_uint_t nargs,
njs_index_t unused)
{
njs_int_t           ret;
njs_value_t         **cur_local, **cur_closures, **cur_temp, *value;
njs_frame_t         *frame, *async_frame;
njs_function_t      *function;
njs_async_ctx_t     *ctx;
njs_native_frame_t  *top, *async;
ctx = vm->top_frame->function->context;
value = njs_arg(args, nargs, 1);
if (njs_is_error(value)) {
goto failed;
}
async_frame = ctx->await;
async = &async_frame->native;
async->previous = vm->top_frame;
function = async->function;
cur_local = vm->levels[NJS_LEVEL_LOCAL];
cur_closures = vm->levels[NJS_LEVEL_CLOSURE];
cur_temp = vm->levels[NJS_LEVEL_TEMP];
top = vm->top_frame;
frame = vm->active_frame;
vm->levels[NJS_LEVEL_LOCAL] = async->local;
vm->levels[NJS_LEVEL_CLOSURE] = njs_function_closures(async->function);
vm->levels[NJS_LEVEL_TEMP] = async->temp;
vm->top_frame = async;
vm->active_frame = async_frame;
*njs_scope_value(vm, ctx->index) = *value;
vm->retval = *value;
vm->top_frame->retval = &vm->retval;
function->context = ctx->capability;
function->await = ctx;
ret = njs_vmcode_interpreter(vm, ctx->pc);
function->context = NULL;
function->await = NULL;
vm->levels[NJS_LEVEL_LOCAL] = cur_local;
vm->levels[NJS_LEVEL_CLOSURE] = cur_closures;
vm->levels[NJS_LEVEL_TEMP] = cur_temp;
vm->top_frame = top;
vm->active_frame = frame;
if (ret == NJS_OK) {
ret = njs_function_call(vm, njs_function(&ctx->capability->resolve),
&njs_value_undefined, &vm->retval, 1, &vm->retval);
njs_async_context_free(vm, ctx);
} else if (ret == NJS_AGAIN) {
ret = NJS_OK;
} else if (ret == NJS_ERROR) {
if (njs_is_memory_error(vm, &vm->retval)) {
return NJS_ERROR;
}
value = &vm->retval;
goto failed;
}
return ret;
failed:
(void) njs_function_call(vm, njs_function(&ctx->capability->reject),
&njs_value_undefined, value, 1, &vm->retval);
njs_async_context_free(vm, ctx);
return NJS_ERROR;
}

static int l2cap_stream_rx(struct l2cap_chan *chan, struct l2cap_ctrl *control,
struct sk_buff *skb)
{
BT_DBG("chan %p, control %p, skb %p, state %d", chan, control, skb,
chan->rx_state);
if (l2cap_classify_txseq(chan, control->txseq) ==
L2CAP_TXSEQ_EXPECTED) {
l2cap_pass_to_tx(chan, control);
BT_DBG("buffer_seq %u->%u", chan->buffer_seq,
__next_seq(chan, chan->buffer_seq));
chan->buffer_seq = __next_seq(chan, chan->buffer_seq);
l2cap_reassemble_sdu(chan, skb, control);
} else {
if (chan->sdu) {
kfree_skb(chan->sdu);
chan->sdu = NULL;
}
chan->sdu_last_frag = NULL;
chan->sdu_len = 0;
if (skb) {
BT_DBG("Freeing %p", skb);
kfree_skb(skb);
}
}
chan->last_acked_seq = control->txseq;
chan->expected_tx_seq = __next_seq(chan, control->txseq);
return 0;
}

void *ishtp_cl_get_dma_send_buf(struct ishtp_device *dev,
uint32_t size)
{
unsigned longflags;
int i, j, free;
int required_slots = (size / DMA_SLOT_SIZE)
+ 1 * (size % DMA_SLOT_SIZE != 0);
spin_lock_irqsave(&dev->ishtp_dma_tx_lock, flags);
for (i = 0; i <= (dev->ishtp_dma_num_slots - required_slots); i++) {
free = 1;
for (j = 0; j < required_slots; j++)
if (dev->ishtp_dma_tx_map[i+j]) {
free = 0;
i += j;
break;
}
if (free) {
for (j = 0; j < required_slots; j++)
dev->ishtp_dma_tx_map[i+j] = 1;
spin_unlock_irqrestore(&dev->ishtp_dma_tx_lock, flags);
return (i * DMA_SLOT_SIZE) +
(unsigned char *)dev->ishtp_host_dma_tx_buf;
}
}
spin_unlock_irqrestore(&dev->ishtp_dma_tx_lock, flags);
dev_err(dev->devc, "No free DMA buffer to send msg\n");
return NULL;
}

static const u_char *
ikev2_t_print(netdissect_options *ndo, int tcount,
const struct isakmp_gen *ext, u_int item_len,
const u_char *ep)
{
const struct ikev2_t *p;
struct ikev2_t t;
uint16_t  t_id;
const u_char *cp;
const char *idstr;
const struct attrmap *map;
size_t nmap;
const u_char *ep2;
p = (const struct ikev2_t *)ext;
ND_TCHECK(*p);
UNALIGNED_MEMCPY(&t, ext, sizeof(t));
ikev2_pay_print(ndo, NPSTR(ISAKMP_NPTYPE_T), t.h.critical);
t_id = ntohs(t.t_id);
map = NULL;
nmap = 0;
switch (t.t_type) {
case IV2_T_ENCR:
idstr = STR_OR_ID(t_id, esp_p_map);
map = encr_t_map;
nmap = sizeof(encr_t_map)/sizeof(encr_t_map[0]);
break;
case IV2_T_PRF:
idstr = STR_OR_ID(t_id, prf_p_map);
break;
case IV2_T_INTEG:
idstr = STR_OR_ID(t_id, integ_p_map);
break;
case IV2_T_DH:
idstr = STR_OR_ID(t_id, dh_p_map);
break;
case IV2_T_ESN:
idstr = STR_OR_ID(t_id, esn_p_map);
break;
default:
idstr = NULL;
break;
}
if (idstr)
ND_PRINT((ndo," #%u type=%s id=%s ", tcount,
STR_OR_ID(t.t_type, ikev2_t_type_map),
idstr));
else
ND_PRINT((ndo," #%u type=%s id=%u ", tcount,
STR_OR_ID(t.t_type, ikev2_t_type_map),
t.t_id));
cp = (const u_char *)(p + 1);
ep2 = (const u_char *)p + item_len;
while (cp < ep && cp < ep2) {
if (map && nmap) {
cp = ikev1_attrmap_print(ndo, cp, (ep < ep2) ? ep : ep2,
map, nmap);
} else
cp = ikev1_attr_print(ndo, cp, (ep < ep2) ? ep : ep2);
}
if (ep < ep2)
ND_PRINT((ndo,"..."));
return cp;
trunc:
ND_PRINT((ndo," [|%s]", NPSTR(ISAKMP_NPTYPE_T)));
return NULL;
}

static njs_ret_t
njs_string_prototype_to_lower_case(njs_vm_t *vm, njs_value_t *args,
nxt_uint_t nargs, njs_index_t unused)
{
size_t             size;
u_char             *p, *start;
const u_char       *s, *end;
njs_string_prop_t  string;
(void) njs_string_prop(&string, &args[0]);
start = njs_string_alloc(vm, &vm->retval, string.size, string.length);
if (nxt_slow_path(start == NULL)) {
return NXT_ERROR;
}
p = start;
s = string.start;
size = string.size;
if (string.length == 0 || string.length == size) {
while (size != 0) {
*p++ = nxt_lower_case(*s++);
size--;
}
} else {
end = s + size;
while (size != 0) {
p = nxt_utf8_encode(p, nxt_utf8_lower_case(&s, end));
size--;
}
}
return NXT_OK;
}

static int pn533_usb_probe(struct usb_interface *interface,
const struct usb_device_id *id)
{
struct pn533 *priv;
struct pn533_usb_phy *phy;
struct usb_host_interface *iface_desc;
struct usb_endpoint_descriptor *endpoint;
int in_endpoint = 0;
int out_endpoint = 0;
int rc = -ENOMEM;
int i;
u32 protocols;
enum pn533_protocol_type protocol_type = PN533_PROTO_REQ_ACK_RESP;
struct pn533_frame_ops *fops = NULL;
unsigned char *in_buf;
int in_buf_len = PN533_EXT_FRAME_HEADER_LEN +
PN533_STD_FRAME_MAX_PAYLOAD_LEN +
PN533_STD_FRAME_TAIL_LEN;
phy = devm_kzalloc(&interface->dev, sizeof(*phy), GFP_KERNEL);
if (!phy)
return -ENOMEM;
in_buf = kzalloc(in_buf_len, GFP_KERNEL);
if (!in_buf)
return -ENOMEM;
phy->udev = usb_get_dev(interface_to_usbdev(interface));
phy->interface = interface;
iface_desc = interface->cur_altsetting;
for (i = 0; i < iface_desc->desc.bNumEndpoints; ++i) {
endpoint = &iface_desc->endpoint[i].desc;
if (!in_endpoint && usb_endpoint_is_bulk_in(endpoint))
in_endpoint = endpoint->bEndpointAddress;
if (!out_endpoint && usb_endpoint_is_bulk_out(endpoint))
out_endpoint = endpoint->bEndpointAddress;
}
if (!in_endpoint || !out_endpoint) {
nfc_err(&interface->dev,
"Could not find bulk-in or bulk-out endpoint\n");
rc = -ENODEV;
goto error;
}
phy->in_urb = usb_alloc_urb(0, GFP_KERNEL);
phy->out_urb = usb_alloc_urb(0, GFP_KERNEL);
phy->ack_urb = usb_alloc_urb(0, GFP_KERNEL);
if (!phy->in_urb || !phy->out_urb || !phy->ack_urb)
goto error;
usb_fill_bulk_urb(phy->in_urb, phy->udev,
usb_rcvbulkpipe(phy->udev, in_endpoint),
in_buf, in_buf_len, NULL, phy);
usb_fill_bulk_urb(phy->out_urb, phy->udev,
usb_sndbulkpipe(phy->udev, out_endpoint),
NULL, 0, pn533_send_complete, phy);
usb_fill_bulk_urb(phy->ack_urb, phy->udev,
usb_sndbulkpipe(phy->udev, out_endpoint),
NULL, 0, pn533_send_complete, phy);
switch (id->driver_info) {
case PN533_DEVICE_STD:
protocols = PN533_ALL_PROTOCOLS;
break;
case PN533_DEVICE_PASORI:
protocols = PN533_NO_TYPE_B_PROTOCOLS;
break;
case PN533_DEVICE_ACR122U:
protocols = PN533_NO_TYPE_B_PROTOCOLS;
fops = &pn533_acr122_frame_ops;
protocol_type = PN533_PROTO_REQ_RESP,
rc = pn533_acr122_poweron_rdr(phy);
if (rc < 0) {
nfc_err(&interface->dev,
"Couldn't poweron the reader (error %d)\n", rc);
goto error;
}
break;
default:
nfc_err(&interface->dev, "Unknown device type %lu\n",
id->driver_info);
rc = -EINVAL;
goto error;
}
priv = pn533_register_device(id->driver_info, protocols, protocol_type,
phy, &usb_phy_ops, fops,
&phy->udev->dev, &interface->dev);
if (IS_ERR(priv)) {
rc = PTR_ERR(priv);
goto error;
}
phy->priv = priv;
rc = pn533_finalize_setup(priv);
if (rc)
goto error;
usb_set_intfdata(interface, phy);
return 0;
error:
usb_free_urb(phy->in_urb);
usb_free_urb(phy->out_urb);
usb_free_urb(phy->ack_urb);
usb_put_dev(phy->udev);
kfree(in_buf);
return rc;
}

int
xfs_setattr_nonsize(
struct xfs_inode*ip,
struct iattr*iattr,
intflags)
{
xfs_mount_t*mp = ip->i_mount;
struct inode*inode = VFS_I(ip);
intmask = iattr->ia_valid;
xfs_trans_t*tp;
interror;
kuid_tuid = GLOBAL_ROOT_UID, iuid = GLOBAL_ROOT_UID;
kgid_tgid = GLOBAL_ROOT_GID, igid = GLOBAL_ROOT_GID;
struct xfs_dquot*udqp = NULL, *gdqp = NULL;
struct xfs_dquot*olddquot1 = NULL, *olddquot2 = NULL;
ASSERT((mask & ATTR_SIZE) == 0);
if (XFS_IS_QUOTA_ON(mp) && (mask & (ATTR_UID|ATTR_GID))) {
uintqflags = 0;
if ((mask & ATTR_UID) && XFS_IS_UQUOTA_ON(mp)) {
uid = iattr->ia_uid;
qflags |= XFS_QMOPT_UQUOTA;
} else {
uid = inode->i_uid;
}
if ((mask & ATTR_GID) && XFS_IS_GQUOTA_ON(mp)) {
gid = iattr->ia_gid;
qflags |= XFS_QMOPT_GQUOTA;
}  else {
gid = inode->i_gid;
}
ASSERT(udqp == NULL);
ASSERT(gdqp == NULL);
error = xfs_qm_vop_dqalloc(ip, xfs_kuid_to_uid(uid),
xfs_kgid_to_gid(gid),
xfs_get_projid(ip),
qflags, &udqp, &gdqp, NULL);
if (error)
return error;
}
error = xfs_trans_alloc(mp, &M_RES(mp)->tr_ichange, 0, 0, 0, &tp);
if (error)
goto out_dqrele;
xfs_ilock(ip, XFS_ILOCK_EXCL);
xfs_trans_ijoin(tp, ip, 0);
if (mask & (ATTR_UID|ATTR_GID)) {
iuid = inode->i_uid;
igid = inode->i_gid;
gid = (mask & ATTR_GID) ? iattr->ia_gid : igid;
uid = (mask & ATTR_UID) ? iattr->ia_uid : iuid;
if (XFS_IS_QUOTA_RUNNING(mp) &&
((XFS_IS_UQUOTA_ON(mp) && !uid_eq(iuid, uid)) ||
(XFS_IS_GQUOTA_ON(mp) && !gid_eq(igid, gid)))) {
ASSERT(tp);
error = xfs_qm_vop_chown_reserve(tp, ip, udqp, gdqp,
NULL, capable(CAP_FOWNER) ?
XFS_QMOPT_FORCE_RES : 0);
if (error)
goto out_cancel;
}
}
if (mask & (ATTR_UID|ATTR_GID)) {
if ((inode->i_mode & (S_ISUID|S_ISGID)) &&
!capable(CAP_FSETID))
inode->i_mode &= ~(S_ISUID|S_ISGID);
if (!uid_eq(iuid, uid)) {
if (XFS_IS_QUOTA_RUNNING(mp) && XFS_IS_UQUOTA_ON(mp)) {
ASSERT(mask & ATTR_UID);
ASSERT(udqp);
olddquot1 = xfs_qm_vop_chown(tp, ip,
&ip->i_udquot, udqp);
}
ip->i_d.di_uid = xfs_kuid_to_uid(uid);
inode->i_uid = uid;
}
if (!gid_eq(igid, gid)) {
if (XFS_IS_QUOTA_RUNNING(mp) && XFS_IS_GQUOTA_ON(mp)) {
ASSERT(xfs_sb_version_has_pquotino(&mp->m_sb) ||
!XFS_IS_PQUOTA_ON(mp));
ASSERT(mask & ATTR_GID);
ASSERT(gdqp);
olddquot2 = xfs_qm_vop_chown(tp, ip,
&ip->i_gdquot, gdqp);
}
ip->i_d.di_gid = xfs_kgid_to_gid(gid);
inode->i_gid = gid;
}
}
if (mask & ATTR_MODE)
xfs_setattr_mode(ip, iattr);
if (mask & (ATTR_ATIME|ATTR_CTIME|ATTR_MTIME))
xfs_setattr_time(ip, iattr);
xfs_trans_log_inode(tp, ip, XFS_ILOG_CORE);
XFS_STATS_INC(mp, xs_ig_attrchg);
if (mp->m_flags & XFS_MOUNT_WSYNC)
xfs_trans_set_sync(tp);
error = xfs_trans_commit(tp);
xfs_iunlock(ip, XFS_ILOCK_EXCL);
xfs_qm_dqrele(olddquot1);
xfs_qm_dqrele(olddquot2);
xfs_qm_dqrele(udqp);
xfs_qm_dqrele(gdqp);
if (error)
return error;
if ((mask & ATTR_MODE) && !(flags & XFS_ATTR_NOACL)) {
error = posix_acl_chmod(inode, inode->i_mode);
if (error)
return error;
}
return 0;
out_cancel:
xfs_trans_cancel(tp);
out_dqrele:
xfs_qm_dqrele(udqp);
xfs_qm_dqrele(gdqp);
return error;
}

int flb_gzip_compress(void *in_data, size_t in_len,
void **out_data, size_t *out_len)
{
int flush;
int status;
int footer_start;
uint8_t *pb;
size_t out_size;
void *out_buf;
z_stream strm;
mz_ulong crc;
out_size = in_len + 32;
out_buf = flb_malloc(out_size);
if (!out_buf) {
flb_errno();
flb_error("[gzip] could not allocate outgoing buffer");
return -1;
}
memset(&strm, '\0', sizeof(strm));
strm.zalloc    = Z_NULL;
strm.zfree     = Z_NULL;
strm.opaque    = Z_NULL;
strm.next_in   = in_data;
strm.avail_in  = in_len;
strm.total_out = 0;
deflateInit2(&strm, Z_DEFAULT_COMPRESSION,
Z_DEFLATED, -Z_DEFAULT_WINDOW_BITS, 9, Z_DEFAULT_STRATEGY);
gzip_header(out_buf);
pb = (uint8_t *) out_buf + FLB_GZIP_HEADER_OFFSET;
flush = Z_NO_FLUSH;
while (1) {
strm.next_out  = pb + strm.total_out;
strm.avail_out = out_size - (pb - (uint8_t *) out_buf);
if (strm.avail_in == 0) {
flush = Z_FINISH;
}
status = deflate(&strm, flush);
if (status == Z_STREAM_END) {
break;
}
else if (status != Z_OK) {
deflateEnd(&strm);
return -1;
}
}
if (deflateEnd(&strm) != Z_OK) {
flb_free(out_buf);
return -1;
}
*out_len = strm.total_out;
footer_start = FLB_GZIP_HEADER_OFFSET + *out_len;
pb = (uint8_t *) out_buf + footer_start;
crc = mz_crc32(MZ_CRC32_INIT, in_data, in_len);
*pb++ = crc & 0xFF;
*pb++ = (crc >> 8) & 0xFF;
*pb++ = (crc >> 16) & 0xFF;
*pb++ = (crc >> 24) & 0xFF;
*pb++ = in_len & 0xFF;
*pb++ = (in_len >> 8) & 0xFF;
*pb++ = (in_len >> 16) & 0xFF;
*pb++ = (in_len >> 24) & 0xFF;
*out_len += FLB_GZIP_HEADER_OFFSET + 8;
*out_data = out_buf;
return 0;
}

void kill_TCP_connection(TCP_Client_Connection *tcp_connection)
{
if (tcp_connection == nullptr) {
return;
}
wipe_priority_list(tcp_connection);
kill_sock(tcp_connection->sock);
crypto_memzero(tcp_connection, sizeof(TCP_Client_Connection));
free(tcp_connection);
}

int wolfSSH_SFTP_RecvOpen(WOLFSSH* ssh, int reqId, byte* data, word32 maxSz)
#ifndef USE_WINDOWS_API
{
WS_SFTP_FILEATRB atr;
WFD    fd;
word32 sz;
char*  dir;
word32 reason;
word32 idx = 0;
int m = 0;
int ret = WS_SUCCESS;
word32 outSz = sizeof(WFD) + UINT32_SZ + WOLFSSH_SFTP_HEADER;
byte*  out = NULL;
char* res   = NULL;
char  ier[] = "Internal Failure";
char  oer[] = "Open File Error";
if (ssh == NULL) {
return WS_BAD_ARGUMENT;
}
WLOG(WS_LOG_SFTP, "Receiving WOLFSSH_FTP_OPEN");
if (sizeof(WFD) > WOLFSSH_MAX_HANDLE) {
WLOG(WS_LOG_SFTP, "Handle size is too large");
return WS_FATAL_ERROR;
}
ato32(data + idx, &sz); idx += UINT32_SZ;
if (sz + idx > maxSz) {
return WS_BUFFER_E;
}
dir = (char*)WMALLOC(sz + 1, ssh->ctx->heap, DYNTYPE_BUFFER);
if (dir == NULL) {
return WS_MEMORY_E;
}
WMEMCPY(dir, data + idx, sz);
dir[sz] = '\0';
idx += sz;
ato32(data + idx, &reason); idx += UINT32_SZ;
SFTP_ParseAtributes_buffer(ssh, &atr, data, &idx, maxSz);
if ((reason & WOLFSSH_FXF_READ) && (reason & WOLFSSH_FXF_WRITE)) {
m |= WOLFSSH_O_RDWR;
}
else {
if (reason & WOLFSSH_FXF_READ) {
m |= WOLFSSH_O_RDONLY;
}
if (reason & WOLFSSH_FXF_WRITE) {
m |= WOLFSSH_O_WRONLY;
}
}
if (reason & WOLFSSH_FXF_APPEND) {
m |= WOLFSSH_O_APPEND;
}
if (reason & WOLFSSH_FXF_CREAT) {
m |= WOLFSSH_O_CREAT;
}
if (reason & WOLFSSH_FXF_TRUNC) {
m |= WOLFSSH_O_TRUNC;
}
if (reason & WOLFSSH_FXF_EXCL) {
m |= WOLFSSH_O_EXCL;
}
if (!(atr.flags & WOLFSSH_FILEATRB_PERM)) {
atr.per = 0644;
}
if (wolfSSH_CleanPath(ssh, dir) < 0) {
WFREE(dir, ssh->ctx->heap, DYNTYPE_BUFFER);
return WS_FATAL_ERROR;
}
fd = WOPEN(dir, m, atr.per);
if (fd < 0) {
WLOG(WS_LOG_SFTP, "Error opening file %s", dir);
res = oer;
if (wolfSSH_SFTP_CreateStatus(ssh, WOLFSSH_FTP_FAILURE, reqId, res,
"English", NULL, &outSz) != WS_SIZE_ONLY) {
WFREE(dir, ssh->ctx->heap, DYNTYPE_BUFFER);
return WS_FATAL_ERROR;
}
ret = WS_BAD_FILE_E;
}
#ifdef WOLFSSH_STOREHANDLE
if (ret == WS_SUCCESS) {
if ((ret = SFTP_AddHandleNode(ssh, (byte*)&fd, sizeof(WFD), dir)) != WS_SUCCESS) {
WLOG(WS_LOG_SFTP, "Unable to store handle");
res = ier;
if (wolfSSH_SFTP_CreateStatus(ssh, WOLFSSH_FTP_FAILURE, reqId, res,
"English", NULL, &outSz) != WS_SIZE_ONLY) {
WFREE(dir, ssh->ctx->heap, DYNTYPE_BUFFER);
return WS_FATAL_ERROR;
}
ret = WS_FATAL_ERROR;
}
}
#endif
WFREE(dir, ssh->ctx->heap, DYNTYPE_BUFFER);
out = (byte*)WMALLOC(outSz, ssh->ctx->heap, DYNTYPE_BUFFER);
if (out == NULL) {
return WS_MEMORY_E;
}
if (ret == WS_SUCCESS) {
if (SFTP_CreatePacket(ssh, WOLFSSH_FTP_HANDLE, out, outSz,
(byte*)&fd, sizeof(WFD)) != WS_SUCCESS) {
return WS_FATAL_ERROR;
}
}
else {
if (wolfSSH_SFTP_CreateStatus(ssh, WOLFSSH_FTP_FAILURE, reqId, res,
"English", out, &outSz) != WS_SUCCESS) {
WFREE(out, ssh->ctx->heap, DYNTYPE_BUFFER);
return WS_FATAL_ERROR;
}
}
wolfSSH_SFTP_RecvSetSend(ssh, out, outSz);
(void)ier;
return ret;
}

void flush_tlb_page(struct vm_area_struct *vma, unsigned long start)
{
struct mm_struct *mm = vma->vm_mm;
preempt_disable();
if (current->active_mm == mm) {
if (current->mm)
__flush_tlb_one(start);
else
leave_mm(smp_processor_id());
}
if (cpumask_any_but(mm_cpumask(mm), smp_processor_id()) < nr_cpu_ids)
flush_tlb_others(mm_cpumask(mm), mm, start, 0UL);
preempt_enable();
}

static int dwa_uncompress(EXRContext *s, const uint8_t *src, int compressed_size,
int uncompressed_size, EXRThreadData *td)
{
int64_t version, lo_usize, lo_size;
int64_t ac_size, dc_size, rle_usize, rle_csize, rle_raw_size;
int64_t ac_count, dc_count, ac_compression;
const int dc_w = td->xsize >> 3;
const int dc_h = td->ysize >> 3;
GetByteContext gb, agb;
int skip, ret;
if (compressed_size <= 88)
return AVERROR_INVALIDDATA;
version = AV_RL64(src + 0);
if (version != 2)
return AVERROR_INVALIDDATA;
lo_usize = AV_RL64(src + 8);
lo_size = AV_RL64(src + 16);
ac_size = AV_RL64(src + 24);
dc_size = AV_RL64(src + 32);
rle_csize = AV_RL64(src + 40);
rle_usize = AV_RL64(src + 48);
rle_raw_size = AV_RL64(src + 56);
ac_count = AV_RL64(src + 64);
dc_count = AV_RL64(src + 72);
ac_compression = AV_RL64(src + 80);
if (compressed_size < 88LL + lo_size + ac_size + dc_size + rle_csize)
return AVERROR_INVALIDDATA;
bytestream2_init(&gb, src + 88, compressed_size - 88);
skip = bytestream2_get_le16(&gb);
if (skip < 2)
return AVERROR_INVALIDDATA;
bytestream2_skip(&gb, skip - 2);
if (lo_size > 0) {
if (lo_usize > uncompressed_size)
return AVERROR_INVALIDDATA;
bytestream2_skip(&gb, lo_size);
}
if (ac_size > 0) {
unsigned long dest_len = ac_count * 2LL;
GetByteContext agb = gb;
if (ac_count > 3LL * td->xsize * s->scan_lines_per_block)
return AVERROR_INVALIDDATA;
av_fast_padded_malloc(&td->ac_data, &td->ac_size, dest_len);
if (!td->ac_data)
return AVERROR(ENOMEM);
switch (ac_compression) {
case 0:
ret = huf_uncompress(s, td, &agb, (int16_t *)td->ac_data, ac_count);
if (ret < 0)
return ret;
break;
case 1:
if (uncompress(td->ac_data, &dest_len, agb.buffer, ac_size) != Z_OK ||
dest_len != ac_count * 2LL)
return AVERROR_INVALIDDATA;
break;
default:
return AVERROR_INVALIDDATA;
}
bytestream2_skip(&gb, ac_size);
}
if (dc_size > 0) {
unsigned long dest_len = dc_count * 2LL;
GetByteContext agb = gb;
if (dc_count > (6LL * td->xsize * td->ysize + 63) / 64)
return AVERROR_INVALIDDATA;
av_fast_padded_malloc(&td->dc_data, &td->dc_size, FFALIGN(dest_len, 64) * 2);
if (!td->dc_data)
return AVERROR(ENOMEM);
if (uncompress(td->dc_data + FFALIGN(dest_len, 64), &dest_len, agb.buffer, dc_size) != Z_OK ||
(dest_len != dc_count * 2LL))
return AVERROR_INVALIDDATA;
s->dsp.predictor(td->dc_data + FFALIGN(dest_len, 64), dest_len);
s->dsp.reorder_pixels(td->dc_data, td->dc_data + FFALIGN(dest_len, 64), dest_len);
bytestream2_skip(&gb, dc_size);
}
if (rle_raw_size > 0 && rle_csize > 0 && rle_usize > 0) {
unsigned long dest_len = rle_usize;
av_fast_padded_malloc(&td->rle_data, &td->rle_size, rle_usize);
if (!td->rle_data)
return AVERROR(ENOMEM);
av_fast_padded_malloc(&td->rle_raw_data, &td->rle_raw_size, rle_raw_size);
if (!td->rle_raw_data)
return AVERROR(ENOMEM);
if (uncompress(td->rle_data, &dest_len, gb.buffer, rle_csize) != Z_OK ||
(dest_len != rle_usize))
return AVERROR_INVALIDDATA;
ret = rle(td->rle_raw_data, td->rle_data, rle_usize, rle_raw_size);
if (ret < 0)
return ret;
bytestream2_skip(&gb, rle_csize);
}
bytestream2_init(&agb, td->ac_data, ac_count * 2);
for (int y = 0; y < td->ysize; y += 8) {
for (int x = 0; x < td->xsize; x += 8) {
memset(td->block, 0, sizeof(td->block));
for (int j = 0; j < 3; j++) {
float *block = td->block[j];
const int idx = (x >> 3) + (y >> 3) * dc_w + dc_w * dc_h * j;
uint16_t *dc = (uint16_t *)td->dc_data;
union av_intfloat32 dc_val;
dc_val.i = half2float(dc[idx], s->mantissatable,
s->exponenttable, s->offsettable);
block[0] = dc_val.f;
ac_uncompress(s, &agb, block);
dct_inverse(block);
}
{
const float scale = s->pixel_type == EXR_FLOAT ? 2.f : 1.f;
const int o = s->nb_channels == 4;
float *bo = ((float *)td->uncompressed_data) +
y * td->xsize * s->nb_channels + td->xsize * (o + 0) + x;
float *go = ((float *)td->uncompressed_data) +
y * td->xsize * s->nb_channels + td->xsize * (o + 1) + x;
float *ro = ((float *)td->uncompressed_data) +
y * td->xsize * s->nb_channels + td->xsize * (o + 2) + x;
float *yb = td->block[0];
float *ub = td->block[1];
float *vb = td->block[2];
for (int yy = 0; yy < 8; yy++) {
for (int xx = 0; xx < 8; xx++) {
const int idx = xx + yy * 8;
convert(yb[idx], ub[idx], vb[idx], &bo[xx], &go[xx], &ro[xx]);
bo[xx] = to_linear(bo[xx], scale);
go[xx] = to_linear(go[xx], scale);
ro[xx] = to_linear(ro[xx], scale);
}
bo += td->xsize * s->nb_channels;
go += td->xsize * s->nb_channels;
ro += td->xsize * s->nb_channels;
}
}
}
}
if (s->nb_channels < 4)
return 0;
for (int y = 0; y < td->ysize && td->rle_raw_data; y++) {
uint32_t *ao = ((uint32_t *)td->uncompressed_data) + y * td->xsize * s->nb_channels;
uint8_t *ai0 = td->rle_raw_data + y * td->xsize;
uint8_t *ai1 = td->rle_raw_data + y * td->xsize + rle_raw_size / 2;
for (int x = 0; x < td->xsize; x++) {
uint16_t ha = ai0[x] | (ai1[x] << 8);
ao[x] = half2float(ha, s->mantissatable, s->exponenttable, s->offsettable);
}
}
return 0;
}

