static bool tcp_shifted_skb(struct sock *sk, struct sk_buff *prev,
struct sk_buff *skb,
struct tcp_sacktag_state *state,
unsigned int pcount, int shifted, int mss,
bool dup_sack)
{
struct tcp_sock *tp = tcp_sk(sk);
u32 start_seq = TCP_SKB_CB(skb)->seq;
u32 end_seq = start_seq + shifted;
BUG_ON(!pcount);
tcp_sacktag_one(sk, state, TCP_SKB_CB(skb)->sacked,
start_seq, end_seq, dup_sack, pcount,
tcp_skb_timestamp_us(skb));
tcp_rate_skb_delivered(sk, skb, state->rate);
if (skb == tp->lost_skb_hint)
tp->lost_cnt_hint += pcount;
TCP_SKB_CB(prev)->end_seq += shifted;
TCP_SKB_CB(skb)->seq += shifted;
tcp_skb_pcount_add(prev, pcount);
BUG_ON(tcp_skb_pcount(skb) < pcount);
tcp_skb_pcount_add(skb, -pcount);
if (!TCP_SKB_CB(prev)->tcp_gso_size)
TCP_SKB_CB(prev)->tcp_gso_size = mss;
if (tcp_skb_pcount(skb) <= 1)
TCP_SKB_CB(skb)->tcp_gso_size = 0;
TCP_SKB_CB(prev)->sacked |= (TCP_SKB_CB(skb)->sacked & TCPCB_EVER_RETRANS);
if (skb->len > 0) {
BUG_ON(!tcp_skb_pcount(skb));
NET_INC_STATS(sock_net(sk), LINUX_MIB_SACKSHIFTED);
return false;
}
if (skb == tp->retransmit_skb_hint)
tp->retransmit_skb_hint = prev;
if (skb == tp->lost_skb_hint) {
tp->lost_skb_hint = prev;
tp->lost_cnt_hint -= tcp_skb_pcount(prev);
}
TCP_SKB_CB(prev)->tcp_flags |= TCP_SKB_CB(skb)->tcp_flags;
TCP_SKB_CB(prev)->eor = TCP_SKB_CB(skb)->eor;
if (TCP_SKB_CB(skb)->tcp_flags & TCPHDR_FIN)
TCP_SKB_CB(prev)->end_seq++;
if (skb == tcp_highest_sack(sk))
tcp_advance_highest_sack(sk, skb);
tcp_skb_collapse_tstamp(prev, skb);
if (unlikely(TCP_SKB_CB(prev)->tx.delivered_mstamp))
TCP_SKB_CB(prev)->tx.delivered_mstamp = 0;
tcp_rtx_queue_unlink_and_free(skb, sk);
NET_INC_STATS(sock_net(sk), LINUX_MIB_SACKMERGED);
return true;
}

static int run_post_create(const char *dirname)
{
if (!dir_is_in_dump_location(dirname))
{
error_msg("Bad problem directory name '%s', should start with: '%s'", dirname, g_settings_dump_location);
return 400; 
}
if (!dump_dir_accessible_by_uid(dirname, client_uid))
{
if (errno == ENOTDIR)
{
error_msg("Path '%s' isn't problem directory", dirname);
return 404; 
}
error_msg("Problem directory '%s' can't be accessed by user with uid %ld", dirname, (long)client_uid);
return 403; 
}
int child_stdout_fd;
int child_pid = spawn_event_handler_child(dirname, "post-create", &child_stdout_fd);
char *dup_of_dir = NULL;
struct strbuf *cmd_output = strbuf_new();
bool child_is_post_create = 1; 
read_child_output:
for (;;)
{
char buf[250]; 
errno = 0;
int r = safe_read(child_stdout_fd, buf, sizeof(buf) - 1);
if (r <= 0)
break;
buf[r] = '\0';
char *raw = buf;
char *newline;
while ((newline = strchr(raw, '\n')) != NULL)
{
*newline = '\0';
strbuf_append_str(cmd_output, raw);
char *msg = cmd_output->buf;
log("%s", msg);
if (child_is_post_create
&& prefixcmp(msg, "DUP_OF_DIR: ") == 0
) {
free(dup_of_dir);
dup_of_dir = xstrdup(msg + strlen("DUP_OF_DIR: "));
}
strbuf_clear(cmd_output);
raw = newline + 1;
}
strbuf_append_str(cmd_output, raw);
}
int status = 0;
if (safe_waitpid(child_pid, &status, 0) <= 0)
perror_msg("waitpid(%d)", child_pid);
if (!child_is_post_create)
goto ret;
if (status != 0)
{
if (WIFSIGNALED(status))
{
log("'post-create' on '%s' killed by signal %d",
dirname, WTERMSIG(status));
goto delete_bad_dir;
}
if (!dup_of_dir)
{
log("'post-create' on '%s' exited with %d",
dirname, WEXITSTATUS(status));
goto delete_bad_dir;
}
}
const char *work_dir = (dup_of_dir ? dup_of_dir : dirname);
struct dump_dir *dd = dd_opendir(work_dir,  0);
if (!dd)
goto delete_bad_dir;
char *count_str = dd_load_text_ext(dd, FILENAME_COUNT, DD_FAIL_QUIETLY_ENOENT);
unsigned long count = strtoul(count_str, NULL, 10);
if ((status != 0 && dup_of_dir) || count == 0)
{
count++;
char new_count_str[sizeof(long)*3 + 2];
sprintf(new_count_str, "%lu", count);
dd_save_text(dd, FILENAME_COUNT, new_count_str);
if (strcmp(dd->dd_dirname, dirname) != 0)
{
struct dump_dir *new_dd = dd_opendir(dirname, DD_OPEN_READONLY);
char *last_ocr = NULL;
if (new_dd)
{
last_ocr = dd_load_text_ext(new_dd, FILENAME_TIME,
DD_LOAD_TEXT_RETURN_NULL_ON_FAILURE | DD_FAIL_QUIETLY_ENOENT);
dd_close(new_dd);
}
else
{   
error_msg("Can't read the last occurrence file from the new dump directory.");
}
if (!last_ocr)
{   
log("Using current time for the last occurrence file which may be incorrect.");
time_t t = time(NULL);
last_ocr = xasprintf("%lu", (long)t);
}
dd_save_text(dd, FILENAME_LAST_OCCURRENCE, last_ocr);
free(last_ocr);
}
}
dd_sanitize_mode_and_owner(dd);
dd_close(dd);
if (!dup_of_dir)
log_notice("New problem directory %s, processing", work_dir);
else
{
log_warning("Deleting problem directory %s (dup of %s)",
strrchr(dirname, '/') + 1,
strrchr(dup_of_dir, '/') + 1);
delete_dump_dir(dirname);
}
int fd;
child_pid = spawn_event_handler_child(
work_dir,
(dup_of_dir ? "notify-dup" : "notify"),
&fd
);
xmove_fd(fd, child_stdout_fd);
child_is_post_create = 0;
strbuf_clear(cmd_output);
free(dup_of_dir);
dup_of_dir = NULL;
goto read_child_output;
delete_bad_dir:
log_warning("Deleting problem directory '%s'", dirname);
delete_dump_dir(dirname);
ret:
strbuf_free(cmd_output);
free(dup_of_dir);
close(child_stdout_fd);
return 0;
}

static DNNReturnType set_input_output_native(void *model, DNNData *input, const char *input_name, const char **output_names, uint32_t nb_output)
{
ConvolutionalNetwork *network = (ConvolutionalNetwork *)model;
DnnOperand *oprd = NULL;
if (network->layers_num <= 0 || network->operands_num <= 0)
return DNN_ERROR;
for (int i = 0; i < network->operands_num; ++i) {
oprd = &network->operands[i];
if (strcmp(oprd->name, input_name) == 0) {
if (oprd->type != DOT_INPUT)
return DNN_ERROR;
break;
}
oprd = NULL;
}
if (!oprd)
return DNN_ERROR;
oprd->dims[0] = 1;
oprd->dims[1] = input->height;
oprd->dims[2] = input->width;
oprd->dims[3] = input->channels;
av_freep(&oprd->data);
oprd->length = calculate_operand_data_length(oprd);
oprd->data = av_malloc(oprd->length);
if (!oprd->data)
return DNN_ERROR;
input->data = oprd->data;
network->nb_output = 0;
av_freep(&network->output_indexes);
network->output_indexes = av_mallocz_array(nb_output, sizeof(*network->output_indexes));
if (!network->output_indexes)
return DNN_ERROR;
for (uint32_t i = 0; i < nb_output; ++i) {
const char *output_name = output_names[i];
for (int j = 0; j < network->operands_num; ++j) {
oprd = &network->operands[j];
if (strcmp(oprd->name, output_name) == 0) {
network->output_indexes[network->nb_output++] = j;
break;
}
}
}
if (network->nb_output != nb_output)
return DNN_ERROR;
return DNN_SUCCESS;
}

static tvbuff_t *wcp_uncompress( tvbuff_t *src_tvb, int offset, packet_info *pinfo, proto_tree *tree, circuit_type ctype, guint32 circuit_id) {
proto_tree*cd_tree, *sub_tree;
proto_item*cd_item, *ti;
int len, i;
int cnt = tvb_reported_length( src_tvb)-1;
guint8 *dst, *src, *buf_start, *buf_end, comp_flag_bits = 0;
guint16 data_offset, data_cnt;
guint8 src_buf[ MAX_WCP_BUF_LEN];
tvbuff_t *tvb;
wcp_window_t *buf_ptr = 0;
wcp_pdata_t *pdata_ptr;
buf_ptr = get_wcp_window_ptr(pinfo, ctype, circuit_id);
buf_start = buf_ptr->buffer;
buf_end = buf_start + MAX_WIN_BUF_LEN;
cd_item = proto_tree_add_item(tree, hf_wcp_compressed_data,
src_tvb, offset, cnt - offset, ENC_NA);
cd_tree = proto_item_add_subtree(cd_item, ett_wcp_comp_data);
if (cnt - offset > MAX_WCP_BUF_LEN) {
expert_add_info_format(pinfo, cd_item, &ei_wcp_compressed_data_exceeds,
"Compressed data exceeds maximum buffer length (%d > %d)",
cnt - offset, MAX_WCP_BUF_LEN);
return NULL;
}
src = (guint8 *)tvb_memcpy(src_tvb, src_buf, offset, cnt - offset);
dst = buf_ptr->buf_cur;
len = 0;
i = -1;
while( offset < cnt){
if ( --i >= 0){
if ( comp_flag_bits & 0x80){
if (!(offset + 1 < cnt)) {
return NULL;
}
data_offset = pntoh16(src) & WCP_OFFSET_MASK;
if ((*src & 0xf0) == 0x10){
if (!(offset + 2 < cnt)) {
return NULL;
}
data_cnt = *(src + 2) + 1;
if ( tree) {
ti = proto_tree_add_item( cd_tree, hf_wcp_long_run, src_tvb,
offset, 3, ENC_NA);
sub_tree = proto_item_add_subtree(ti, ett_wcp_field);
proto_tree_add_uint(sub_tree, hf_wcp_offset, src_tvb,
offset, 2, data_offset);
proto_tree_add_item( sub_tree, hf_wcp_long_len, src_tvb,
offset+2, 1, ENC_BIG_ENDIAN);
}
src += 3;
offset += 3;
}else{
data_cnt = (*src >> 4) + 1;
if ( tree) {
ti = proto_tree_add_item( cd_tree, hf_wcp_short_run, src_tvb,
offset, 2, ENC_NA);
sub_tree = proto_item_add_subtree(ti, ett_wcp_field);
proto_tree_add_uint( sub_tree, hf_wcp_short_len, src_tvb,
offset, 1, *src);
proto_tree_add_uint(sub_tree, hf_wcp_offset, src_tvb,
offset, 2, data_offset);
}
src += 2;
offset += 2;
}
if (data_offset + 1 > buf_ptr->initialized) {
expert_add_info_format(pinfo, cd_item, &ei_wcp_invalid_window_offset,
"Data offset exceeds valid window size (%d > %d)",
data_offset+1, buf_ptr->initialized);
return NULL;
}
if (data_offset + 1 < data_cnt) {
expert_add_info_format(pinfo, cd_item, &ei_wcp_invalid_window_offset,
"Data count exceeds offset (%d > %d)",
data_cnt, data_offset+1);
return NULL;
}
if ( !pinfo->fd->flags.visited){
dst = decompressed_entry(dst,
data_offset, data_cnt, &len,
buf_ptr);
if (dst == NULL){
expert_add_info_format(pinfo, cd_item, &ei_wcp_uncompressed_data_exceeds,
"Uncompressed data exceeds maximum buffer length (%d > %d)",
len, MAX_WCP_BUF_LEN);
return NULL;
}
}
}else {
if ( ++len >MAX_WCP_BUF_LEN){
expert_add_info_format(pinfo, cd_item, &ei_wcp_uncompressed_data_exceeds,
"Uncompressed data exceeds maximum buffer length (%d > %d)",
len, MAX_WCP_BUF_LEN);
return NULL;
}
if ( !pinfo->fd->flags.visited){
*dst = *src;
if ( dst++ == buf_end)
dst = buf_start;
if (buf_ptr->initialized < MAX_WIN_BUF_LEN)
buf_ptr->initialized++;
}
++src;
++offset;
}
comp_flag_bits <<= 1;
}else {
comp_flag_bits = *src++;
proto_tree_add_uint(cd_tree, hf_wcp_comp_bits,  src_tvb, offset, 1,
comp_flag_bits);
offset++;
i = 8;
}
}
if ( pinfo->fd->flags.visited){
pdata_ptr = (wcp_pdata_t *)p_get_proto_data(wmem_file_scope(), pinfo, proto_wcp, 0);
if ( !pdata_ptr) {
REPORT_DISSECTOR_BUG("Can't find uncompressed data");
return NULL;
}
len = pdata_ptr->len;
} else {
pdata_ptr = wmem_new(wmem_file_scope(), wcp_pdata_t);
memcpy( &pdata_ptr->buffer, buf_ptr->buf_cur,  len);
pdata_ptr->len = len;
p_add_proto_data(wmem_file_scope(), pinfo, proto_wcp, 0, (void*)pdata_ptr);
buf_ptr->buf_cur = dst;
}
tvb = tvb_new_child_real_data(src_tvb,  pdata_ptr->buffer, pdata_ptr->len, pdata_ptr->len);
add_new_data_source( pinfo, tvb, "Uncompressed WCP");
return tvb;
}

status_t CursorWindow::maybeInflate() {
int ashmemFd = 0;
void* newData = nullptr;
if (mReadOnly || mSize == mInflatedSize) {
return INVALID_OPERATION;
}
String8 ashmemName("CursorWindow: ");
ashmemName.append(mName);
ashmemFd = ashmem_create_region(ashmemName.string(), mInflatedSize);
if (ashmemFd < 0) {
PLOG(ERROR) << "Failed ashmem_create_region";
goto fail_silent;
}
if (ashmem_set_prot_region(ashmemFd, PROT_READ | PROT_WRITE) < 0) {
PLOG(ERROR) << "Failed ashmem_set_prot_region";
goto fail_silent;
}
newData = ::mmap(nullptr, mInflatedSize, PROT_READ | PROT_WRITE, MAP_SHARED, ashmemFd, 0);
if (newData == MAP_FAILED) {
PLOG(ERROR) << "Failed mmap";
goto fail_silent;
}
if (ashmem_set_prot_region(ashmemFd, PROT_READ) < 0) {
PLOG(ERROR) << "Failed ashmem_set_prot_region";
goto fail_silent;
}
{
uint32_t slotsSize = mSize - mSlotsOffset;
uint32_t newSlotsOffset = mInflatedSize - slotsSize;
memcpy(static_cast<uint8_t*>(newData),
static_cast<uint8_t*>(mData), mAllocOffset);
memcpy(static_cast<uint8_t*>(newData) + newSlotsOffset,
static_cast<uint8_t*>(mData) + mSlotsOffset, slotsSize);
free(mData);
mAshmemFd = ashmemFd;
mData = newData;
mSize = mInflatedSize;
mSlotsOffset = newSlotsOffset;
updateSlotsData();
}
LOG(DEBUG) << "Inflated: " << this->toString();
return OK;
fail:
LOG(ERROR) << "Failed maybeInflate";
fail_silent:
::munmap(newData, mInflatedSize);
::close(ashmemFd);
return UNKNOWN_ERROR;
}

static void
paste_option_changed(void)
{
