static int h264_slice_header_init(H264Context *h)
{
int nb_slices = (HAVE_THREADS &&
h->avctx->active_thread_type & FF_THREAD_SLICE) ?
h->avctx->thread_count : 1;
int i, ret;
ff_set_sar(h->avctx, h->sps.sar);
av_pix_fmt_get_chroma_sub_sample(h->avctx->pix_fmt,
&h->chroma_x_shift, &h->chroma_y_shift);
if (h->sps.timing_info_present_flag) {
int64_t den = h->sps.time_scale;
if (h->x264_build < 44U)
den *= 2;
av_reduce(&h->avctx->framerate.den, &h->avctx->framerate.num,
h->sps.num_units_in_tick * h->avctx->ticks_per_frame, den, 1 << 30);
}
ff_h264_free_tables(h);
h->first_field           = 0;
h->prev_interlaced_frame = 1;
init_scan_tables(h);
ret = ff_h264_alloc_tables(h);
if (ret < 0) {
av_log(h->avctx, AV_LOG_ERROR, "Could not allocate memory\n");
goto fail;
}
#if FF_API_CAP_VDPAU
if (h->avctx->codec &&
h->avctx->codec->capabilities & AV_CODEC_CAP_HWACCEL_VDPAU &&
(h->sps.bit_depth_luma != 8 || h->sps.chroma_format_idc > 1)) {
av_log(h->avctx, AV_LOG_ERROR,
"VDPAU decoding does not support video colorspace.\n");
ret = AVERROR_INVALIDDATA;
goto fail;
}
#endif
if (h->sps.bit_depth_luma < 8 || h->sps.bit_depth_luma > 14 ||
h->sps.bit_depth_luma == 11 || h->sps.bit_depth_luma == 13
) {
av_log(h->avctx, AV_LOG_ERROR, "Unsupported bit depth %d\n",
h->sps.bit_depth_luma);
ret = AVERROR_INVALIDDATA;
goto fail;
}
h->cur_bit_depth_luma         =
h->avctx->bits_per_raw_sample = h->sps.bit_depth_luma;
h->cur_chroma_format_idc      = h->sps.chroma_format_idc;
h->pixel_shift                = h->sps.bit_depth_luma > 8;
h->chroma_format_idc          = h->sps.chroma_format_idc;
h->bit_depth_luma             = h->sps.bit_depth_luma;
ff_h264dsp_init(&h->h264dsp, h->sps.bit_depth_luma,
h->sps.chroma_format_idc);
ff_h264chroma_init(&h->h264chroma, h->sps.bit_depth_chroma);
ff_h264qpel_init(&h->h264qpel, h->sps.bit_depth_luma);
ff_h264_pred_init(&h->hpc, h->avctx->codec_id, h->sps.bit_depth_luma,
h->sps.chroma_format_idc);
ff_videodsp_init(&h->vdsp, h->sps.bit_depth_luma);
if (nb_slices > H264_MAX_THREADS || (nb_slices > h->mb_height && h->mb_height)) {
int max_slices;
if (h->mb_height)
max_slices = FFMIN(H264_MAX_THREADS, h->mb_height);
else
max_slices = H264_MAX_THREADS;
av_log(h->avctx, AV_LOG_WARNING, "too many threads/slices %d,"
" reducing to %d\n", nb_slices, max_slices);
nb_slices = max_slices;
}
h->slice_context_count = nb_slices;
if (!HAVE_THREADS || !(h->avctx->active_thread_type & FF_THREAD_SLICE)) {
ret = ff_h264_slice_context_init(h, &h->slice_ctx[0]);
if (ret < 0) {
av_log(h->avctx, AV_LOG_ERROR, "context_init() failed.\n");
goto fail;
}
} else {
for (i = 0; i < h->slice_context_count; i++) {
H264SliceContext *sl = &h->slice_ctx[i];
sl->h264               = h;
sl->intra4x4_pred_mode = h->intra4x4_pred_mode + i * 8 * 2 * h->mb_stride;
sl->mvd_table[0]       = h->mvd_table[0]       + i * 8 * 2 * h->mb_stride;
sl->mvd_table[1]       = h->mvd_table[1]       + i * 8 * 2 * h->mb_stride;
if ((ret = ff_h264_slice_context_init(h, sl)) < 0) {
av_log(h->avctx, AV_LOG_ERROR, "context_init() failed.\n");
goto fail;
}
}
}
h->context_initialized = 1;
return 0;
fail:
ff_h264_free_tables(h);
h->context_initialized = 0;
return ret;
}

static GF_Err av1_parse_tile_group(GF_BitStream *bs, AV1State *state, u64 obu_start, u64 obu_size)
{
u32 TileNum, tg_start=0, tg_end=0;
Bool numTiles = state->tileCols * state->tileRows;
Bool tile_start_and_end_present_flag = GF_FALSE;
GF_Err e = GF_OK;
if (numTiles > 1)
tile_start_and_end_present_flag = gf_bs_read_int(bs, 1);
if (numTiles == 1 || !tile_start_and_end_present_flag) {
tg_start = 0;
tg_end = numTiles - 1;
} else {
u32 tileBits = state->tileColsLog2 + state->tileRowsLog2;
tg_start = gf_bs_read_int(bs, tileBits);
tg_end = gf_bs_read_int(bs, tileBits);
}
gf_bs_align(bs);
state->frame_state.nb_tiles_in_obu = 0;
for (TileNum = tg_start; TileNum <= tg_end; TileNum++) {
u32 tile_start_offset, tile_size;
Bool lastTile = TileNum == tg_end;
u64 pos = gf_bs_get_position(bs);
if (lastTile) {
tile_start_offset = (u32) (pos - obu_start);
tile_size = (u32)(obu_size - (pos - obu_start) );
} else {
u64 tile_size_minus_1 = aom_av1_le(bs, state->tile_size_bytes);
pos = gf_bs_get_position(bs);
tile_start_offset = (u32) (pos - obu_start);
tile_size = (u32)(tile_size_minus_1 + 1);
}
if (tile_start_offset + tile_size > obu_size) {
GF_LOG(GF_LOG_ERROR, GF_LOG_CODING, ("[AV1]Error parsing tile group, tile %d start %d + size %d exceeds OBU length %d\n", TileNum, tile_start_offset, tile_size, obu_size));
e = GF_NON_COMPLIANT_BITSTREAM;
break;
}
state->frame_state.tiles[state->frame_state.nb_tiles_in_obu].obu_start_offset = tile_start_offset;
state->frame_state.tiles[state->frame_state.nb_tiles_in_obu].size = tile_size;
gf_bs_skip_bytes(bs, tile_size);
state->frame_state.nb_tiles_in_obu++;
}
if (tg_end == numTiles-1) {
av1_decode_frame_wrapup(state);
}
return e;
}

static response vg_lookup(lvmetad_state *s, request r)
{
struct dm_config_tree *cft;
struct dm_config_node *metadata, *n;
struct vg_info *info;
response res = { 0 };
const char *uuid = daemon_request_str(r, "uuid", NULL);
const char *name = daemon_request_str(r, "name", NULL);
int count = 0;
buffer_init( &res.buffer );
if (!uuid && !name) {
ERROR(s, "vg_lookup with no uuid or name");
return reply_unknown("VG not found");
} else if (!uuid || !name) {
DEBUGLOG(s, "vg_lookup vgid %s name %s needs lookup",
uuid ?: "none", name ?: "none");
if (name && !uuid)
uuid = dm_hash_lookup_with_count(s->vgname_to_vgid, name, &count);
else if (uuid && !name)
name = dm_hash_lookup(s->vgid_to_vgname, uuid);
if (name && uuid && (count > 1)) {
DEBUGLOG(s, "vg_lookup name %s vgid %s found %d vgids",
name, uuid, count);
return daemon_reply_simple("multiple", "reason = %s", "Multiple VGs found with same name", NULL);
}
if (!uuid || !name)
return reply_unknown("VG not found");
} else {
char *name_lookup = dm_hash_lookup(s->vgid_to_vgname, uuid);
char *uuid_lookup = dm_hash_lookup_with_val(s->vgname_to_vgid, name, uuid, strlen(uuid) + 1);
if (!name_lookup || !uuid_lookup) {
ERROR(s, "vg_lookup vgid %s name %s found incomplete mapping uuid %s name %s",
uuid, name, uuid_lookup ?: "none", name_lookup ?: "none");
return reply_unknown("VG mapping incomplete");
} else if (strcmp(name_lookup, name) || strcmp(uuid_lookup, uuid)) {
ERROR(s, "vg_lookup vgid %s name %s found inconsistent mapping uuid %s name %s",
uuid, name, uuid_lookup, name_lookup);
return reply_unknown("VG mapping inconsistent");
}
}
DEBUGLOG(s, "vg_lookup vgid %s name %s", uuid ?: "none", name ?: "none");
cft = dm_hash_lookup(s->vgid_to_metadata, uuid);
if (!cft || !cft->root) {
return reply_unknown("UUID not found");
}
metadata = cft->root;
if (!(res.cft = dm_config_create()))
goto nomem_un;
if (!(res.cft->root = n = dm_config_create_node(res.cft, "response")))
goto nomem_un;
if (!(n->v = dm_config_create_value(cft)))
goto nomem_un;
n->parent = res.cft->root;
n->v->type = DM_CFG_STRING;
n->v->v.str = "OK";
if (!(n = n->sib = dm_config_create_node(res.cft, "name")))
goto nomem_un;
if (!(n->v = dm_config_create_value(res.cft)))
goto nomem_un;
n->parent = res.cft->root;
n->v->type = DM_CFG_STRING;
n->v->v.str = name;
if (!(n = n->sib = dm_config_clone_node(res.cft, metadata, 1)))
goto nomem_un;
n->parent = res.cft->root;
if (!update_pv_status(s, res.cft, n))
goto nomem;
chain_outdated_pvs(s, uuid, res.cft, n);
if (s->flags & GLFL_INVALID)
add_last_node(res.cft, "global_invalid");
info = dm_hash_lookup(s->vgid_to_info, uuid);
if (info && (info->flags & VGFL_INVALID)) {
if (!add_last_node(res.cft, "vg_invalid"))
goto nomem;
}
return res;
nomem_un:
nomem:
reply_fail("out of memory");
ERROR(s, "vg_lookup vgid %s name %s out of memory.", uuid ?: "none", name ?: "none");
ERROR(s, "lvmetad could not be updated and is aborting.");
exit(EXIT_FAILURE);
}

static int f2fs_mpage_readpages(struct address_space *mapping,
struct list_head *pages, struct page *page,
unsigned nr_pages, bool is_readahead)
{
struct bio *bio = NULL;
sector_t last_block_in_bio = 0;
struct inode *inode = mapping->host;
struct f2fs_map_blocks map;
int ret = 0;
map.m_pblk = 0;
map.m_lblk = 0;
map.m_len = 0;
map.m_flags = 0;
map.m_next_pgofs = NULL;
map.m_next_extent = NULL;
map.m_seg_type = NO_CHECK_TYPE;
map.m_may_create = false;
for (; nr_pages; nr_pages--) {
if (pages) {
page = list_last_entry(pages, struct page, lru);
prefetchw(&page->flags);
list_del(&page->lru);
if (add_to_page_cache_lru(page, mapping,
page->index,
readahead_gfp_mask(mapping)))
goto next_page;
}
ret = f2fs_read_single_page(inode, page, nr_pages, &map, &bio,
&last_block_in_bio, is_readahead);
if (ret) {
SetPageError(page);
zero_user_segment(page, 0, PAGE_SIZE);
unlock_page(page);
}
next_page:
if (pages)
put_page(page);
}
BUG_ON(pages && !list_empty(pages));
if (bio)
__submit_bio(F2FS_I_SB(inode), bio, DATA);
return pages ? 0 : ret;
}

GF_EXPORT
char *gf_utf_get_utf8_string_from_bom(u8 *data, u32 size, char **out_ptr)
{
u32 unicode_type = 0;
*out_ptr = NULL;
if (size>=5) {
if ((data[0]==0xFF) && (data[1]==0xFE)) {
if (!data[2] && !data[3]) {
return NULL;
} else {
unicode_type = 2;
}
} else if ((data[0]==0xFE) && (data[1]==0xFF)) {
if (!data[2] && !data[3]) {
return NULL;
} else {
unicode_type = 1;
}
} else if ((data[0]==0xEF) && (data[1]==0xBB) && (data[2]==0xBF)) {
return data+4;
}
}
if (!unicode_type) return data;
if (size%2) size--;
u16 *str_wc = gf_malloc(size+2);
u16 *srcwc;
char *dst = gf_malloc(size+2);
*out_ptr = dst;
u32 i;
for (i=0; i<size; i+=2) {
u16 wchar=0;
u8 c1 = data[i];
u8 c2 = data[i+1];
if (unicode_type==2) {
if (c2) {
wchar = c2;
wchar <<=8;
wchar |= c1;
}
else wchar = c1;
} else {
wchar = c1;
if (c2) {
wchar <<= 8;
wchar |= c2;
}
}
str_wc[i/2] = wchar;
}
str_wc[i/2] = 0;
srcwc = str_wc;
gf_utf8_wcstombs(dst, size, (const unsigned short **) &srcwc);
gf_free(str_wc);
return dst;
}

static void
get_bitmap_glyph(ASS_Renderer *render_priv, GlyphInfo *info,
ASS_Vector *pos, ASS_Vector *pos_o,
ASS_DVector *offset, bool first, int flags)
{
if (!info->outline || info->symbol == '\n' || info->symbol == 0 || info->skip) {
ass_cache_dec_ref(info->outline);
return;
}
double m1[3][3], m2[3][3], m[3][3];
const ASS_Transform *tr = &info->transform;
calc_transform_matrix(render_priv, info, m1);
for (int i = 0; i < 3; i++) {
m2[i][0] = m1[i][0] * tr->scale.x;
m2[i][1] = m1[i][1] * tr->scale.y;
m2[i][2] = m1[i][0] * tr->offset.x + m1[i][1] * tr->offset.y + m1[i][2];
}
memcpy(m, m2, sizeof(m));
BitmapHashKey key;
key.outline = info->outline;
if (!quantize_transform(m, pos, offset, first, &key)) {
ass_cache_dec_ref(info->outline);
return;
}
info->bm = ass_cache_get(render_priv->cache.bitmap_cache, &key, render_priv);
if (!info->bm || !info->bm->buffer) {
ass_cache_dec_ref(info->bm);
info->bm = NULL;
}
*pos_o = *pos;
OutlineHashKey ol_key;
if (flags & FILTER_BORDER_STYLE_3) {
if (!(flags & (FILTER_NONZERO_BORDER | FILTER_NONZERO_SHADOW)))
return;
ol_key.type = OUTLINE_BOX;
double w = 64 * render_priv->border_scale;
ASS_DVector bord = { info->border_x * w, info->border_y * w };
double width = info->hspacing_scaled + info->advance.x;
double height = info->asc + info->desc;
ASS_DVector orig_scale;
orig_scale.x = info->scale_x * info->scale_fix;
orig_scale.y = info->scale_y * info->scale_fix;
bord.x *= orig_scale.x;
bord.y *= orig_scale.y;
width  *= orig_scale.x;
height *= orig_scale.y;
bord.x = FFMAX(64, bord.x);
bord.y = FFMAX(64, bord.y);
ASS_DVector scale = {
(width  + 2 * bord.x) / 64,
(height + 2 * bord.y) / 64,
};
ASS_DVector offset = { -bord.x, -bord.y - info->asc };
for (int i = 0; i < 3; i++) {
m[i][0] = m1[i][0] * scale.x;
m[i][1] = m1[i][1] * scale.y;
m[i][2] = m1[i][0] * offset.x + m1[i][1] * offset.y + m1[i][2];
}
} else {
if (!(flags & FILTER_NONZERO_BORDER))
return;
ol_key.type = OUTLINE_BORDER;
BorderHashKey *k = &ol_key.u.border;
k->outline = info->outline;
double w = 64 * render_priv->border_scale;
double bord_x = w * info->border_x / tr->scale.x;
double bord_y = w * info->border_y / tr->scale.y;
const ASS_Rect *bbox = &info->outline->cbox;
double dx = (bbox->x_max - bbox->x_min) / 2.0 + (bord_x + 64);
double dy = (bbox->y_max - bbox->y_min) / 2.0 + (bord_y + 64);
double mxx = fabs(m[0][0]), mxy = fabs(m[0][1]);
double myx = fabs(m[1][0]), myy = fabs(m[1][1]);
double mzx = fabs(m[2][0]), mzy = fabs(m[2][1]);
double z0 = m[2][2] - mzx * dx - mzy * dy;
w = 1 / FFMAX(z0, m[2][2] / MAX_PERSP_SCALE);
double x_lim = mxx * dx + mxy * dy;
double y_lim = myx * dx + myy * dy;
double rz = FFMAX(x_lim, y_lim) * w;
w *= STROKER_PRECISION / POSITION_PRECISION;
frexp(w * (FFMAX(mxx, myx) + mzx * rz), &k->scale_ord_x);
frexp(w * (FFMAX(mxy, myy) + mzy * rz), &k->scale_ord_y);
k->border.x = lrint(ldexp(bord_x, k->scale_ord_x) / STROKER_PRECISION);
k->border.y = lrint(ldexp(bord_y, k->scale_ord_y) / STROKER_PRECISION);
if (!k->border.x && !k->border.y) {
ass_cache_inc_ref(info->bm);
info->bm_o = info->bm;
return;
}
for (int i = 0; i < 3; i++) {
m[i][0] = ldexp(m2[i][0], -k->scale_ord_x);
m[i][1] = ldexp(m2[i][1], -k->scale_ord_y);
m[i][2] = m2[i][2];
}
}
key.outline = ass_cache_get(render_priv->cache.outline_cache, &ol_key, render_priv);
if (!key.outline || !key.outline->valid ||
!quantize_transform(m, pos_o, offset, false, &key)) {
ass_cache_dec_ref(key.outline);
return;
}
info->bm_o = ass_cache_get(render_priv->cache.bitmap_cache, &key, render_priv);
if (!info->bm_o || !info->bm_o->buffer) {
ass_cache_dec_ref(info->bm_o);
info->bm_o = NULL;
*pos_o = *pos;
} else if (!info->bm)
*pos = *pos_o;
}

int CLASS parse_jpeg(int offset)
{
int len, save, hlen, mark;
fseek(ifp, offset, SEEK_SET);
if (fgetc(ifp) != 0xff || fgetc(ifp) != 0xd8)
return 0;
while (fgetc(ifp) == 0xff && (mark = fgetc(ifp)) != 0xda)
{
order = 0x4d4d;
len = get2() - 2;
save = ftell(ifp);
if (mark == 0xc0 || mark == 0xc3 || mark == 0xc9)
{
fgetc(ifp);
raw_height = get2();
raw_width = get2();
}
order = get2();
hlen = get4();
if (get4() == 0x48454150) 
{
#ifdef LIBRAW_LIBRARY_BUILD
imgdata.lens.makernotes.CameraMount = LIBRAW_MOUNT_FixedLens;
imgdata.lens.makernotes.LensMount = LIBRAW_MOUNT_FixedLens;
#endif
parse_ciff(save + hlen, len - hlen, 0);
}
if (parse_tiff(save + 6))
apply_tiff();
fseek(ifp, save + len, SEEK_SET);
}
return 1;
}

static void
diffuse_stucki(unsigned char *data, int width, int height,
int x, int y, int depth, int error)
{
int pos;
pos = y * width + x;
if (pos < (height - 2) * width - 2) {
error_diffuse(data, pos + width * 0 + 1, depth, error, 1, 6);
error_diffuse(data, pos + width * 0 + 2, depth, error, 1, 12);
error_diffuse(data, pos + width * 1 - 2, depth, error, 1, 24);
error_diffuse(data, pos + width * 1 - 1, depth, error, 1, 12);
error_diffuse(data, pos + width * 1 + 0, depth, error, 1, 6);
error_diffuse(data, pos + width * 1 + 1, depth, error, 1, 12);
error_diffuse(data, pos + width * 1 + 2, depth, error, 1, 24);
error_diffuse(data, pos + width * 2 - 2, depth, error, 1, 48);
error_diffuse(data, pos + width * 2 - 1, depth, error, 1, 24);
error_diffuse(data, pos + width * 2 + 0, depth, error, 1, 12);
error_diffuse(data, pos + width * 2 + 1, depth, error, 1, 24);
error_diffuse(data, pos + width * 2 + 2, depth, error, 1, 48);
}
}

static zval **spl_array_get_dimension_ptr_ptr(int check_inherited, zval *object, zval *offset, int type TSRMLS_DC) 
{
spl_array_object *intern = (spl_array_object*)zend_object_store_get_object(object TSRMLS_CC);
zval **retval;
char *key;
uint len;
long index;
HashTable *ht = spl_array_get_hash_table(intern, 0 TSRMLS_CC);
if (!offset) {
return &EG(uninitialized_zval_ptr);
}
if ((type == BP_VAR_W || type == BP_VAR_RW) && (ht->nApplyCount > 0)) {
zend_error(E_WARNING, "Modification of ArrayObject during sorting is prohibited");
return &EG(error_zval_ptr);;
}
switch (Z_TYPE_P(offset)) {
case IS_STRING:
key = Z_STRVAL_P(offset);
len = Z_STRLEN_P(offset) + 1;
string_offest:
if (zend_symtable_find(ht, key, len, (void **) &retval) == FAILURE) {
switch (type) {
case BP_VAR_R:
zend_error(E_NOTICE, "Undefined index: %s", key);
case BP_VAR_UNSET:
case BP_VAR_IS:
retval = &EG(uninitialized_zval_ptr);
break;
case BP_VAR_RW:
zend_error(E_NOTICE,"Undefined index: %s", key);
case BP_VAR_W: {
zval *value;
ALLOC_INIT_ZVAL(value);
zend_symtable_update(ht, key, len, (void**)&value, sizeof(void*), (void **)&retval);
}
}
}
return retval;
case IS_NULL:
key = "";
len = 1;
goto string_offest;
case IS_RESOURCE:
zend_error(E_STRICT, "Resource ID#%ld used as offset, casting to integer (%ld)", Z_LVAL_P(offset), Z_LVAL_P(offset));
case IS_DOUBLE:
case IS_BOOL:
case IS_LONG:
if (offset->type == IS_DOUBLE) {
index = (long)Z_DVAL_P(offset);
} else {
index = Z_LVAL_P(offset);
}
if (zend_hash_index_find(ht, index, (void **) &retval) == FAILURE) {
switch (type) {
case BP_VAR_R:
zend_error(E_NOTICE, "Undefined offset: %ld", index);
case BP_VAR_UNSET:
case BP_VAR_IS:
retval = &EG(uninitialized_zval_ptr);
break;
case BP_VAR_RW:
zend_error(E_NOTICE, "Undefined offset: %ld", index);
case BP_VAR_W: {
zval *value;
ALLOC_INIT_ZVAL(value);
zend_hash_index_update(ht, index, (void**)&value, sizeof(void*), (void **)&retval);
}
}
}
return retval;
default:
zend_error(E_WARNING, "Illegal offset type");
return (type == BP_VAR_W || type == BP_VAR_RW) ?
&EG(error_zval_ptr) : &EG(uninitialized_zval_ptr);
}
}

void
vrrp_print(netdissect_options *ndo,
register const u_char *bp, register u_int len,
register const u_char *bp2, int ttl)
{
int version, type, auth_type = VRRP_AUTH_NONE; 
const char *type_s;
ND_TCHECK(bp[0]);
version = (bp[0] & 0xf0) >> 4;
type = bp[0] & 0x0f;
type_s = tok2str(type2str, "unknown type (%u)", type);
ND_PRINT((ndo, "VRRPv%u, %s", version, type_s));
if (ttl != 255)
ND_PRINT((ndo, ", (ttl %u)", ttl));
if (version < 2 || version > 3 || type != VRRP_TYPE_ADVERTISEMENT)
return;
ND_TCHECK(bp[2]);
ND_PRINT((ndo, ", vrid %u, prio %u", bp[1], bp[2]));
ND_TCHECK(bp[5]);
if (version == 2) {
auth_type = bp[4];
ND_PRINT((ndo, ", authtype %s", tok2str(auth2str, NULL, auth_type)));
ND_PRINT((ndo, ", intvl %us, length %u", bp[5], len));
} else { 
uint16_t intvl = (bp[4] & 0x0f) << 8 | bp[5];
ND_PRINT((ndo, ", intvl %ucs, length %u", intvl, len));
}
if (ndo->ndo_vflag) {
int naddrs = bp[3];
int i;
char c;
if (version == 2 && ND_TTEST2(bp[0], len)) {
struct cksum_vec vec[1];
vec[0].ptr = bp;
vec[0].len = len;
if (in_cksum(vec, 1)) {
ND_TCHECK_16BITS(&bp[6]);
ND_PRINT((ndo, ", (bad vrrp cksum %x)",
EXTRACT_16BITS(&bp[6])));
}
}
if (version == 3 && ND_TTEST2(bp[0], len)) {
uint16_t cksum = nextproto4_cksum(ndo, (const struct ip *)bp2, bp,
len, len, IPPROTO_VRRP);
if (cksum)
ND_PRINT((ndo, ", (bad vrrp cksum %x)",
EXTRACT_16BITS(&bp[6])));
}
ND_PRINT((ndo, ", addrs"));
if (naddrs > 1)
ND_PRINT((ndo, "(%d)", naddrs));
ND_PRINT((ndo, ":"));
c = ' ';
bp += 8;
for (i = 0; i < naddrs; i++) {
ND_TCHECK(bp[3]);
ND_PRINT((ndo, "%c%s", c, ipaddr_string(ndo, bp)));
c = ',';
bp += 4;
}
if (version == 2 && auth_type == VRRP_AUTH_SIMPLE) { 
ND_TCHECK(bp[7]);
ND_PRINT((ndo, " auth \""));
if (fn_printn(ndo, bp, 8, ndo->ndo_snapend)) {
ND_PRINT((ndo, "\""));
goto trunc;
}
ND_PRINT((ndo, "\""));
}
}
return;
trunc:
ND_PRINT((ndo, "[|vrrp]"));
}

WORD32 ih264d_decode_gaps_in_frame_num(dec_struct_t *ps_dec,
UWORD16 u2_frame_num)
{
UWORD32 u4_next_frm_num, u4_start_frm_num;
UWORD32 u4_max_frm_num;
pocstruct_t s_tmp_poc;
WORD32 i4_poc;
dec_slice_params_t *ps_cur_slice;
dec_pic_params_t *ps_pic_params;
WORD8 i1_gap_idx;
WORD32 *i4_gaps_start_frm_num;
dpb_manager_t *ps_dpb_mgr;
WORD32 i4_frame_gaps;
WORD8 *pi1_gaps_per_seq;
WORD32 ret;
ps_cur_slice = ps_dec->ps_cur_slice;
if(ps_cur_slice->u1_field_pic_flag)
{
if(ps_dec->u2_prev_ref_frame_num == u2_frame_num)
return 0;
}
u4_next_frm_num = ps_dec->u2_prev_ref_frame_num + 1;
u4_max_frm_num = ps_dec->ps_cur_sps->u2_u4_max_pic_num_minus1 + 1;
if(u4_next_frm_num >= u4_max_frm_num)
{
u4_next_frm_num -= u4_max_frm_num;
}
if(u4_next_frm_num == u2_frame_num)
{
return (0);
}
if((ps_dec->u1_nal_unit_type == IDR_SLICE_NAL)
&& (u4_next_frm_num >= u2_frame_num))
{
return (0);
}
u4_start_frm_num = u4_next_frm_num;
s_tmp_poc.i4_pic_order_cnt_lsb = 0;
s_tmp_poc.i4_delta_pic_order_cnt_bottom = 0;
s_tmp_poc.i4_pic_order_cnt_lsb = 0;
s_tmp_poc.i4_delta_pic_order_cnt_bottom = 0;
s_tmp_poc.i4_delta_pic_order_cnt[0] = 0;
s_tmp_poc.i4_delta_pic_order_cnt[1] = 0;
ps_cur_slice = ps_dec->ps_cur_slice;
ps_pic_params = ps_dec->ps_cur_pps;
ps_cur_slice->u1_field_pic_flag = 0;
i4_frame_gaps = 0;
ps_dpb_mgr = ps_dec->ps_dpb_mgr;
i4_gaps_start_frm_num = ps_dpb_mgr->ai4_gaps_start_frm_num;
for(i1_gap_idx = 0; i1_gap_idx < MAX_FRAMES; i1_gap_idx++)
{
if(INVALID_FRAME_NUM == i4_gaps_start_frm_num[i1_gap_idx])
break;
}
if(MAX_FRAMES == i1_gap_idx)
{
UWORD32 i4_error_code;
i4_error_code = ERROR_DBP_MANAGER_T;
return i4_error_code;
}
i4_poc = 0;
i4_gaps_start_frm_num[i1_gap_idx] = u4_start_frm_num;
ps_dpb_mgr->ai4_gaps_end_frm_num[i1_gap_idx] = u2_frame_num - 1;
pi1_gaps_per_seq = ps_dpb_mgr->ai1_gaps_per_seq;
pi1_gaps_per_seq[i1_gap_idx] = 0;
while(u4_next_frm_num != u2_frame_num)
{
ih264d_delete_nonref_nondisplay_pics(ps_dpb_mgr);
if(ps_pic_params->ps_sps->u1_pic_order_cnt_type)
{
ret = ih264d_decode_pic_order_cnt(0, u4_next_frm_num,
&ps_dec->s_prev_pic_poc,
&s_tmp_poc, ps_cur_slice,
ps_pic_params, 1, 0, 0,
&i4_poc);
if(ret != OK)
return ret;
if(i4_poc >= ps_dec->i4_max_poc)
ps_dec->i4_max_poc = i4_poc;
if(i4_poc == 0)
{
ps_dec->i4_prev_max_display_seq =
ps_dec->i4_prev_max_display_seq
+ ps_dec->i4_max_poc
+ ps_dec->u1_max_dec_frame_buffering
+ 1;
ps_dec->i4_max_poc = 0;
}
ps_cur_slice->u1_mmco_equalto5 = 0;
ps_cur_slice->u2_frame_num = u4_next_frm_num;
}
if(ps_dpb_mgr->i1_poc_buf_id_entries
>= ps_dec->u1_max_dec_frame_buffering)
{
ret = ih264d_assign_display_seq(ps_dec);
if(ret != OK)
return ret;
}
ret = ih264d_insert_pic_in_display_list(
ps_dec->ps_dpb_mgr, (WORD8) DO_NOT_DISP,
(WORD32)(ps_dec->i4_prev_max_display_seq + i4_poc),
u4_next_frm_num);
if(ret != OK)
return ret;
pi1_gaps_per_seq[i1_gap_idx]++;
ret = ih264d_do_mmco_for_gaps(ps_dpb_mgr,
ps_dec->ps_cur_sps->u1_num_ref_frames);
if(ret != OK)
return ret;
ih264d_delete_nonref_nondisplay_pics(ps_dpb_mgr);
u4_next_frm_num++;
if(u4_next_frm_num >= u4_max_frm_num)
{
u4_next_frm_num -= u4_max_frm_num;
}
i4_frame_gaps++;
}
return OK;
}

x3f_return_t x3f_delete(x3f_t *x3f)
{
x3f_directory_section_t *DS;
int d;
if (x3f == NULL)
return X3F_ARGUMENT_ERROR;
DS = &x3f->directory_section;
if (DS->num_directory_entries > 50)
return X3F_ARGUMENT_ERROR;
for (d=0; d<DS->num_directory_entries; d++) {
x3f_directory_entry_t *DE = &DS->directory_entry[d];
x3f_directory_entry_header_t *DEH = &DE->header;
if (DEH->identifier == X3F_SECp) {
x3f_property_list_t *PL = &DEH->data_subsection.property_list;
if (PL)
{
int i;
for (i = 0; i < PL->property_table.size; i++) {
FREE(PL->property_table.element[i].name_utf8);
FREE(PL->property_table.element[i].value_utf8);
}
}
FREE(PL->property_table.element);
FREE(PL->data);
}
if (DEH->identifier == X3F_SECi) {
x3f_image_data_t *ID = &DEH->data_subsection.image_data;
if (ID)
{
cleanup_huffman(&ID->huffman);
cleanup_true(&ID->tru);
cleanup_quattro(&ID->quattro);
FREE(ID->data);
}
}
if (DEH->identifier == X3F_SECc) {
x3f_camf_t *CAMF = &DEH->data_subsection.camf;
int i;
if (CAMF)
{
FREE(CAMF->data);
FREE(CAMF->table.element);
cleanup_huffman_tree(&CAMF->tree);
FREE(CAMF->decoded_data);
for (i = 0; i < CAMF->entry_table.size; i++) {
free_camf_entry(&CAMF->entry_table.element[i]);
}
}
FREE(CAMF->entry_table.element);
}
}
FREE(DS->directory_entry);
FREE(x3f);
return X3F_OK;
}

static int __dcache_readdir(struct file *file,  struct dir_context *ctx,
u32 shared_gen)
{
struct ceph_file_info *fi = file->private_data;
struct dentry *parent = file->f_dentry;
struct inode *dir = parent->d_inode;
struct list_head *p;
struct dentry *dentry, *last;
struct ceph_dentry_info *di;
int err = 0;
last = fi->dentry;
fi->dentry = NULL;
dout("__dcache_readdir %p v%u at %llu (last %p)\n",
dir, shared_gen, ctx->pos, last);
spin_lock(&parent->d_lock);
if (ctx->pos == 2 || last == NULL ||
fpos_cmp(ctx->pos, ceph_dentry(last)->offset) < 0) {
if (list_empty(&parent->d_subdirs))
goto out_unlock;
p = parent->d_subdirs.prev;
dout(" initial p %p/%p\n", p->prev, p->next);
} else {
p = last->d_u.d_child.prev;
}
more:
dentry = list_entry(p, struct dentry, d_u.d_child);
di = ceph_dentry(dentry);
while (1) {
dout(" p %p/%p %s d_subdirs %p/%p\n", p->prev, p->next,
d_unhashed(dentry) ? "!hashed" : "hashed",
parent->d_subdirs.prev, parent->d_subdirs.next);
if (p == &parent->d_subdirs) {
fi->flags |= CEPH_F_ATEND;
goto out_unlock;
}
spin_lock_nested(&dentry->d_lock, DENTRY_D_LOCK_NESTED);
if (di->lease_shared_gen == shared_gen &&
!d_unhashed(dentry) && dentry->d_inode &&
ceph_snap(dentry->d_inode) != CEPH_SNAPDIR &&
ceph_ino(dentry->d_inode) != CEPH_INO_CEPH &&
fpos_cmp(ctx->pos, di->offset) <= 0)
break;
dout(" skipping %p %.*s at %llu (%llu)%s%s\n", dentry,
dentry->d_name.len, dentry->d_name.name, di->offset,
ctx->pos, d_unhashed(dentry) ? " unhashed" : "",
!dentry->d_inode ? " null" : "");
spin_unlock(&dentry->d_lock);
p = p->prev;
dentry = list_entry(p, struct dentry, d_u.d_child);
di = ceph_dentry(dentry);
}
dget_dlock(dentry);
spin_unlock(&dentry->d_lock);
spin_unlock(&parent->d_lock);
if (!ceph_dir_is_complete(dir)) {
dout(" lost dir complete on %p; falling back to mds\n", dir);
dput(dentry);
err = -EAGAIN;
goto out;
}
dout(" %llu (%llu) dentry %p %.*s %p\n", di->offset, ctx->pos,
dentry, dentry->d_name.len, dentry->d_name.name, dentry->d_inode);
if (!dir_emit(ctx, dentry->d_name.name,
dentry->d_name.len,
ceph_translate_ino(dentry->d_sb, dentry->d_inode->i_ino),
dentry->d_inode->i_mode >> 12)) {
if (last) {
fi->dentry = last;
fi->next_offset = fpos_off(di->offset);
}
dput(dentry);
return 0;
}
ctx->pos = di->offset + 1;
if (last)
dput(last);
last = dentry;
spin_lock(&parent->d_lock);
p = p->prev;
goto more;
out_unlock:
spin_unlock(&parent->d_lock);
out:
if (last)
dput(last);
return err;
}

void tee_shm_free(struct tee_shm *shm)
{
