static void gmc_mmx(uint8_t *dst, uint8_t *src,
int stride, int h, int ox, int oy,
int dxx, int dxy, int dyx, int dyy,
int shift, int r, int width, int height)
{
const int w    = 8;
const int ix   = ox  >> (16 + shift);
const int iy   = oy  >> (16 + shift);
const int oxs  = ox  >> 4;
const int oys  = oy  >> 4;
const int dxxs = dxx >> 4;
const int dxys = dxy >> 4;
const int dyxs = dyx >> 4;
const int dyys = dyy >> 4;
const uint16_t r4[4]   = { r, r, r, r };
const uint16_t dxy4[4] = { dxys, dxys, dxys, dxys };
const uint16_t dyy4[4] = { dyys, dyys, dyys, dyys };
const uint64_t shift2  = 2 * shift;
#define MAX_STRIDE 4096U
#define MAX_H 8U
uint8_t edge_buf[(MAX_H + 1) * MAX_STRIDE];
int x, y;
const int dxw = (dxx - (1 << (16 + shift))) * (w - 1);
const int dyh = (dyy - (1 << (16 + shift))) * (h - 1);
const int dxh = dxy * (h - 1);
const int dyw = dyx * (w - 1);
int need_emu  =  (unsigned) ix >= width  - w ||
(unsigned) iy >= height - h;
if (         ((ox ^ (ox + dxw)) | (ox ^ (ox + dxh)) | (ox ^ (ox + dxw + dxh)) |
(oy ^ (oy + dyw)) | (oy ^ (oy + dyh)) | (oy ^ (oy + dyw + dyh))) >> (16 + shift) ||
(dxx | dxy | dyx | dyy) & 15 ||
(need_emu && (h > MAX_H || stride > MAX_STRIDE))) {
ff_gmc_c(dst, src, stride, h, ox, oy, dxx, dxy, dyx, dyy,
shift, r, width, height);
return;
}
src += ix + iy * stride;
if (need_emu) {
ff_emulated_edge_mc_8(edge_buf, src, stride, stride, w + 1, h + 1, ix, iy, width, height);
src = edge_buf;
}
__asm__ volatile (
"movd         %0, %%mm6         \n\t"
"pxor      %%mm7, %%mm7         \n\t"
"punpcklwd %%mm6, %%mm6         \n\t"
"punpcklwd %%mm6, %%mm6         \n\t"
:: "r" (1 << shift));
for (x = 0; x < w; x += 4) {
uint16_t dx4[4] = { oxs - dxys + dxxs * (x + 0),
oxs - dxys + dxxs * (x + 1),
oxs - dxys + dxxs * (x + 2),
oxs - dxys + dxxs * (x + 3) };
uint16_t dy4[4] = { oys - dyys + dyxs * (x + 0),
oys - dyys + dyxs * (x + 1),
oys - dyys + dyxs * (x + 2),
oys - dyys + dyxs * (x + 3) };
for (y = 0; y < h; y++) {
__asm__ volatile (
"movq      %0, %%mm4    \n\t"
"movq      %1, %%mm5    \n\t"
"paddw     %2, %%mm4    \n\t"
"paddw     %3, %%mm5    \n\t"
"movq   %%mm4, %0       \n\t"
"movq   %%mm5, %1       \n\t"
"psrlw    $12, %%mm4    \n\t"
"psrlw    $12, %%mm5    \n\t"
: "+m" (*dx4), "+m" (*dy4)
: "m" (*dxy4), "m" (*dyy4));
__asm__ volatile (
"movq      %%mm6, %%mm2 \n\t"
"movq      %%mm6, %%mm1 \n\t"
"psubw     %%mm4, %%mm2 \n\t"
"psubw     %%mm5, %%mm1 \n\t"
"movq      %%mm2, %%mm0 \n\t"
"movq      %%mm4, %%mm3 \n\t"
"pmullw    %%mm1, %%mm0 \n\t"                 "pmullw    %%mm5, %%mm3 \n\t"                 "pmullw    %%mm5, %%mm2 \n\t"                 "pmullw    %%mm4, %%mm1 \n\t" 
"movd         %4, %%mm5 \n\t"
"movd         %3, %%mm4 \n\t"
"punpcklbw %%mm7, %%mm5 \n\t"
"punpcklbw %%mm7, %%mm4 \n\t"
"pmullw    %%mm5, %%mm3 \n\t"                 "pmullw    %%mm4, %%mm2 \n\t" 
"movd         %2, %%mm5 \n\t"
"movd         %1, %%mm4 \n\t"
"punpcklbw %%mm7, %%mm5 \n\t"
"punpcklbw %%mm7, %%mm4 \n\t"
"pmullw    %%mm5, %%mm1 \n\t"                 "pmullw    %%mm4, %%mm0 \n\t"                 "paddw        %5, %%mm1 \n\t"
"paddw     %%mm3, %%mm2 \n\t"
"paddw     %%mm1, %%mm0 \n\t"
"paddw     %%mm2, %%mm0 \n\t"
"psrlw        %6, %%mm0 \n\t"
"packuswb  %%mm0, %%mm0 \n\t"
"movd      %%mm0, %0    \n\t"
: "=m" (dst[x + y * stride])
: "m" (src[0]), "m" (src[1]),
"m" (src[stride]), "m" (src[stride + 1]),
"m" (*r4), "m" (shift2));
src += stride;
}
src += 4 - h * stride;
}
}

int
setup_sched(struct tcp_sched* sched){
input_addr sip, dip;   
input_addr local_ip, remote_ip;    
struct pcap_pkthdr header;      const u_char *packet;           pcap_t *local_handle;
unsigned int pkt_counter=0;
ether_hdr *etherhdr = NULL;
tcp_hdr *tcphdr = NULL;
ipv4_hdr *iphdr = NULL;
local_ip.byte1=0; 
local_ip.byte2=0; 
local_ip.byte3=0; 
local_ip.byte4=0; 
remote_ip.byte1=0; 
remote_ip.byte2=0; 
remote_ip.byte3=0; 
remote_ip.byte4=0; 
unsigned int size_ip, i = 0; 
unsigned int size_tcp; 
unsigned int size_payload; 
char errbuf[PCAP_ERRBUF_SIZE];
unsigned int flags=0; 
bool remote = false;    
bool local = false; 
local_handle = pcap_open_offline("newfile.pcap", errbuf);   
if (local_handle == NULL) {
fprintf(stderr,"Couldn't open pcap file %s: %s\n", "newfile.pcap", errbuf);
return(2);
}
while((packet = pcap_next(local_handle,&header))) {
pkt_counter++; 
memcpy(&sched[i].pkthdr, &header, sizeof(struct pcap_pkthdr));
sched[i].packet_ptr = safe_malloc(sched[i].pkthdr.len);
memcpy(sched[i].packet_ptr, packet, sched[i].pkthdr.len);
etherhdr = (ether_hdr*)(sched[i].packet_ptr);
iphdr = (ipv4_hdr *)(sched[i].packet_ptr + SIZE_ETHERNET);
size_ip = iphdr->ip_hl << 2;
if (size_ip < 20) {
printf("ERROR: Invalid IP header length: %u bytes\n", size_ip);
return 0;
}
tcphdr = (tcp_hdr *)(sched[i].packet_ptr + SIZE_ETHERNET + size_ip);
size_tcp = tcphdr->th_off*4; 
if (size_tcp < 20) {
printf("ERROR: Invalid TCP header length: %u bytes\n", size_tcp);
return 0;
}
size_payload = ntohs(iphdr->ip_len) - (size_ip + (size_tcp));
sip = iphdr->ip_src;
dip = iphdr->ip_dst;
flags = tcphdr->th_flags;
if (flags == TH_SYN){   
local_ip = sip;
remote_ip = dip;
}
if(compip(&local_ip, &remote_ip, &sip)==LOCAL_IP_MATCH){
local = true;
remote = false;
}
if(compip(&local_ip, &remote_ip, &sip)==REMOTE_IP_MATCH){
local = false;
remote = true;
}
sched[i].etherhdr = etherhdr; 
sched[i].iphdr = iphdr; 
sched[i].tcphdr = tcphdr; 
sched[i].size_ip = size_ip; 
sched[i].size_tcp = size_tcp;  
sched[i].size_payload = size_payload;
sched[i].sent_counter = 0; 
if(i==0){
sched[i].length_last_ldata = 0;
sched[i].length_curr_ldata = 0; 
sched[i].length_last_rdata = 0;
sched[i].length_curr_rdata = 0; 
sched[i].local = true; 
sched[i].remote = false;
sched[i].curr_lseq = ntohl(sched[i].tcphdr->th_seq); 
sched[i].curr_lack = 0;
sched[i].exp_rseq = 0;  
sched[i].exp_rack = 0;
} 
else if(local){
sched[i].length_last_ldata = sched[i-1].length_curr_ldata; 
sched[i].length_curr_ldata = size_payload; 
sched[i].length_last_rdata = sched[i-1].length_curr_rdata;
sched[i].length_curr_rdata = 0; 
sched[i].local = true; 
sched[i].remote = false;
sched[i].curr_lseq = ntohl(sched[i].tcphdr->th_seq); 
sched[i].curr_lack = ntohl(sched[i].tcphdr->th_ack);
sched[i].exp_rseq = sched[i-1].exp_rseq;    
sched[i].exp_rack = sched[i-1].exp_rack;
}
else if(remote){
sched[i].length_last_ldata = sched[i-1].length_curr_ldata;
sched[i].length_curr_ldata = 0; 
sched[i].length_last_rdata = sched[i-1].length_curr_rdata;
sched[i].length_curr_rdata = size_payload; 
sched[i].local = false; 
sched[i].remote = true;
sched[i].curr_lseq = sched[i-1].curr_lseq; 
sched[i].curr_lack = sched[i-1].curr_lack;
sched[i].exp_rseq = ntohl(sched[i].tcphdr->th_seq);     
sched[i].exp_rack = ntohl(sched[i].tcphdr->th_ack);
if(flags == (TH_FIN|TH_ACK)) finack_rindex = i;
}
i++; 
} 
pcap_close(local_handle);  
return pkt_counter; 
}

static gint16
rlc_decode_li(enum rlc_mode mode, tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree,
struct rlc_li *li, guint8 max_li, gboolean li_on_2_bytes)
{
guint8      ext, hdr_len, offs  = 0, num_li = 0, li_offs;
guint16     next_bytes, prev_li = 0;
proto_item *malformed;
guint16     total_len;
switch (mode) {
case RLC_AM:
offs = 1;
break;
case RLC_UM:
offs = 0;
break;
case RLC_TM:
case RLC_UNKNOWN_MODE:
default:
return -1;
}
hdr_len = offs;
ext = tvb_get_guint8(tvb, hdr_len++) & 0x01;
while (ext) {
next_bytes = li_on_2_bytes ? tvb_get_ntohs(tvb, hdr_len) : tvb_get_guint8(tvb, hdr_len);
ext = next_bytes & 0x01;
hdr_len += li_on_2_bytes ? 2 : 1;
}
total_len = tvb_captured_length_remaining(tvb, hdr_len);
ext = tvb_get_guint8(tvb, offs++) & 0x01;
li_offs = offs;
while (ext) {
if (li_on_2_bytes) {
next_bytes = tvb_get_ntohs(tvb, offs);
offs += 2;
} else {
next_bytes = tvb_get_guint8(tvb, offs++);
}
ext = next_bytes & 0x01;
li[num_li].ext = ext;
li[num_li].li = next_bytes >> 1;
if (li_on_2_bytes) {
switch (li[num_li].li) {
case 0x0000: 
case 0x7ffb: 
case 0x7ffe: 
case 0x7fff: 
li[num_li].len = 0;
break;
case 0x7ffa: 
case 0x7ffc: 
case 0x7ffd: 
if (mode == RLC_UM) {
li[num_li].len = 0;
break;
}
malformed = tree_add_li(mode, &li[num_li], num_li, li_offs, li_on_2_bytes, tvb, tree);
expert_add_info(pinfo, malformed, &ei_rlc_li_reserved);
return -1; 
default:
if (((li[num_li].li > total_len) && !global_rlc_headers_expected)
|| (li[num_li].li < prev_li)) {
malformed = tree_add_li(mode, &li[num_li], num_li, li_offs, li_on_2_bytes, tvb, tree);
expert_add_info(pinfo, malformed, &ei_rlc_li_incorrect_warn);
return -1; 
}
li[num_li].len = li[num_li].li - prev_li;
prev_li = li[num_li].li;
}
} else {
switch (li[num_li].li) {
case 0x00: 
case 0x7e: 
case 0x7f: 
li[num_li].len = 0;
break;
case 0x7c: 
case 0x7d: 
if (mode == RLC_UM) {
li[num_li].len = 0;
break;
}
malformed = tree_add_li(mode, &li[num_li], num_li, li_offs, li_on_2_bytes, tvb, tree);
expert_add_info(pinfo, malformed, &ei_rlc_li_reserved);
return -1; 
default:
li[num_li].len = li[num_li].li - prev_li;
if (((li[num_li].li > total_len) && !global_rlc_headers_expected)
|| (li[num_li].li < prev_li)) {
malformed = tree_add_li(mode, &li[num_li], num_li, li_offs, li_on_2_bytes, tvb, tree);
expert_add_info_format(pinfo, malformed, &ei_rlc_li_incorrect_mal, "Incorrect LI value 0x%x", li[num_li].li);
return -1; 
}
prev_li = li[num_li].li;
}
}
li[num_li].tree = tree_add_li(mode, &li[num_li], num_li, li_offs, li_on_2_bytes, tvb, tree);
num_li++;
if (num_li >= max_li) {
expert_add_info(pinfo, li[num_li-1].tree, &ei_rlc_li_too_many);
return -1;
}
}
return num_li;
}

int ModPlug_InstrumentName(ModPlugFile* file, unsigned int qual, char* buff)
{
const char* str;
unsigned int retval;
size_t tmpretval;
if(!file) return 0;
str = openmpt_module_get_instrument_name(file->mod,qual-1);
if(!str){
if(buff){
*buff = '\0';
}
return 0;
}
tmpretval = strlen(str);
if(tmpretval>=INT_MAX){
tmpretval = INT_MAX-1;
}
retval = (int)tmpretval;
if(buff){
memcpy(buff,str,retval+1);
buff[retval] = '\0';
}
openmpt_free_string(str);
return retval;
}

void
PackLinuxElf32::invert_pt_dynamic(Elf32_Dyn const *dynp)
{
if (dt_table[Elf32_Dyn::DT_NULL]) {
return;      }
Elf32_Dyn const *const dynp0 = dynp;
unsigned ndx = 1+ 0;
if (dynp)
for (; ; ++ndx, ++dynp) {
unsigned const d_tag = get_te32(&dynp->d_tag);
if (d_tag < DT_NUM) {
if (Elf32_Dyn::DT_NEEDED != d_tag
&&  dt_table[d_tag]
&&    get_te32(&dynp->d_val)
!= get_te32(&dynp0[-1+ dt_table[d_tag]].d_val)) {
char msg[50]; snprintf(msg, sizeof(msg),
"duplicate DT_%#x: [%#x] [%#x]",
d_tag, -1+ dt_table[d_tag], -1+ ndx);
throwCantPack(msg);
}
dt_table[d_tag] = ndx;
}
if (Elf32_Dyn::DT_NULL == d_tag) {
break;          }
}
upx_dt_init = 0;
if (dt_table[Elf32_Dyn::DT_INIT])          upx_dt_init = Elf32_Dyn::DT_INIT;
else if (dt_table[Elf32_Dyn::DT_PREINIT_ARRAY]) upx_dt_init = Elf32_Dyn::DT_PREINIT_ARRAY;
else if (dt_table[Elf32_Dyn::DT_INIT_ARRAY])    upx_dt_init = Elf32_Dyn::DT_INIT_ARRAY;
unsigned const z_str = dt_table[Elf32_Dyn::DT_STRSZ];
if (z_str) {
strtab_end = get_te32(&dynp0[-1+ z_str].d_val);
if ((u32_t)file_size <= strtab_end) {             char msg[50]; snprintf(msg, sizeof(msg),
"bad DT_STRSZ %#x", strtab_end);
throwCantPack(msg);
}
}
unsigned const x_sym = dt_table[Elf32_Dyn::DT_SYMTAB];
unsigned const x_str = dt_table[Elf32_Dyn::DT_STRTAB];
if (x_sym && x_str) {
upx_uint32_t const v_sym = get_te32(&dynp0[-1+ x_sym].d_val);
upx_uint32_t const v_str = get_te32(&dynp0[-1+ x_str].d_val);
unsigned const  z_sym = dt_table[Elf32_Dyn::DT_SYMENT];
unsigned const sz_sym = !z_sym ? sizeof(Elf32_Sym)
: get_te32(&dynp0[-1+ z_sym].d_val);
if (sz_sym < sizeof(Elf32_Sym)) {
char msg[50]; snprintf(msg, sizeof(msg),
"bad DT_SYMENT %x", sz_sym);
throwCantPack(msg);
}
if (v_sym < v_str) {
symnum_end = (v_str - v_sym) / sz_sym;
}
if (symnum_end < 1) {
throwCantPack("bad DT_SYMTAB");
}
}
unsigned const v_hsh = elf_unsigned_dynamic(Elf32_Dyn::DT_HASH);
if (v_hsh && file_image) {
hashtab = (unsigned const *)elf_find_dynamic(Elf32_Dyn::DT_HASH);
if (!hashtab) {
char msg[40]; snprintf(msg, sizeof(msg),
"bad DT_HASH %#x", v_hsh);
throwCantPack(msg);
}
unsigned const nbucket = get_te32(&hashtab[0]);
unsigned const *const buckets = &hashtab[2];
unsigned const *const chains = &buckets[nbucket]; (void)chains;
unsigned const v_sym = get_te32(&dynp0[-1+ x_sym].d_val);
if (!nbucket
|| (nbucket>>31) || (file_size/sizeof(unsigned)) <= (2*nbucket)          || ((v_hsh < v_sym) && (v_sym - v_hsh) < (sizeof(unsigned)*2                  + sizeof(*buckets)*nbucket                  + sizeof(*chains) *nbucket             ))
) {
char msg[90]; snprintf(msg, sizeof(msg),
"bad DT_HASH nbucket=%#x  len=%#x",
nbucket, (v_sym - v_hsh));
throwCantPack(msg);
}
}
unsigned const v_gsh = elf_unsigned_dynamic(Elf32_Dyn::DT_GNU_HASH);
if (v_gsh && file_image) {
gashtab = (unsigned const *)elf_find_dynamic(Elf32_Dyn::DT_GNU_HASH);
if (!gashtab) {
char msg[40]; snprintf(msg, sizeof(msg),
"bad DT_GNU_HASH %#x", v_gsh);
throwCantPack(msg);
}
unsigned const n_bucket = get_te32(&gashtab[0]);
unsigned const n_bitmask = get_te32(&gashtab[2]);
unsigned const gnu_shift = get_te32(&gashtab[3]);
unsigned const *const bitmask = (unsigned const *)(void const *)&gashtab[4];
unsigned     const *const buckets = (unsigned const *)&bitmask[n_bitmask];
unsigned     const *const hasharr = &buckets[n_bucket]; (void)hasharr;
unsigned const v_sym = get_te32(&dynp0[-1+ x_sym].d_val);
if (!n_bucket || !n_bitmask
|| (-1+ n_bitmask) & n_bitmask          || 8*sizeof(unsigned) <= gnu_shift          || (n_bucket>>30)          || (n_bitmask>>30)
|| (file_size / sizeof(unsigned)) <= (n_bitmask + 2*n_bucket)                  || ((v_gsh < v_sym) && (v_sym - v_gsh) < (sizeof(unsigned)*4                  + sizeof(*bitmask)*n_bitmask                  + sizeof(*buckets)*n_bucket                  + sizeof(*hasharr)*n_bucket              ))
) {
char msg[90]; snprintf(msg, sizeof(msg),
"bad DT_GNU_HASH n_bucket=%#x  n_bitmask=%#x  len=%#x",
n_bucket, n_bitmask, v_sym - v_gsh);
throwCantPack(msg);
}
}
unsigned const e_shstrndx = get_te16(&ehdri.e_shstrndx);
if (e_shnum <= e_shstrndx
&&  !(0==e_shnum && 0==e_shstrndx) ) {
char msg[40]; snprintf(msg, sizeof(msg),
"bad .e_shstrndx %d >= .e_shnum %d", e_shstrndx, e_shnum);
throwCantPack(msg);
}
}

static void
mldv2_query_print(netdissect_options *ndo, const u_char *bp, u_int len)
{
const struct icmp6_hdr *icp = (const struct icmp6_hdr *) bp;
u_int mrc;
int mrt, qqi;
u_int nsrcs;
register u_int i;
if (len < 28) {
ND_PRINT((ndo," [invalid len %d]", len));
return;
}
ND_TCHECK(icp->icmp6_data16[0]);
mrc = EXTRACT_16BITS(&icp->icmp6_data16[0]);
if (mrc < 32768) {
mrt = mrc;
} else {
mrt = ((mrc & 0x0fff) | 0x1000) << (((mrc & 0x7000) >> 12) + 3);
}
if (ndo->ndo_vflag) {
ND_PRINT((ndo," [max resp delay=%d]", mrt));
}
ND_TCHECK2(bp[8], sizeof(struct in6_addr));
ND_PRINT((ndo," [gaddr %s", ip6addr_string(ndo, &bp[8])));
if (ndo->ndo_vflag) {
ND_TCHECK(bp[25]);
if (bp[24] & 0x08) {
ND_PRINT((ndo," sflag"));
}
if (bp[24] & 0x07) {
ND_PRINT((ndo," robustness=%d", bp[24] & 0x07));
}
if (bp[25] < 128) {
qqi = bp[25];
} else {
qqi = ((bp[25] & 0x0f) | 0x10) << (((bp[25] & 0x70) >> 4) + 3);
}
ND_PRINT((ndo," qqi=%d", qqi));
}
ND_TCHECK2(bp[26], 2);
nsrcs = EXTRACT_16BITS(&bp[26]);
if (nsrcs > 0) {
if (len < 28 + nsrcs * sizeof(struct in6_addr))
ND_PRINT((ndo," [invalid number of sources]"));
else if (ndo->ndo_vflag > 1) {
ND_PRINT((ndo," {"));
for (i = 0; i < nsrcs; i++) {
ND_TCHECK2(bp[28 + i * sizeof(struct in6_addr)],
sizeof(struct in6_addr));
ND_PRINT((ndo," %s", ip6addr_string(ndo, &bp[28 + i * sizeof(struct in6_addr)])));
}
ND_PRINT((ndo," }"));
} else
ND_PRINT((ndo,", %d source(s)", nsrcs));
}
ND_PRINT((ndo,"]"));
return;
trunc:
ND_PRINT((ndo,"[|icmp6]"));
return;
}

void
renderTable(struct table *t, int max_width, struct html_feed_environ *h_env)
{
int i, j, w, r, h;
Str renderbuf;
short new_tabwidth[MAXCOL];
#ifdef MATRIX
int itr;
VEC *newwidth;
MAT *mat, *minv;
PERM *pivot;
#endif
int width;
int rulewidth;
Str vrulea = NULL, vruleb = NULL, vrulec = NULL;
#ifdef ID_EXT
Str idtag;
#endif
t->total_height = 0;
if (t->maxcol < 0) {
make_caption(t, h_env);
return;
}
if (t->sloppy_width > max_width)
max_width = t->sloppy_width;
rulewidth = table_rule_width(t);
max_width -= table_border_width(t);
if (rulewidth > 1)
max_width = floor_at_intervals(max_width, rulewidth);
if (max_width < rulewidth)
max_width = rulewidth;
check_maximum_width(t);
#ifdef MATRIX
if (t->maxcol == 0) {
if (t->tabwidth[0] > max_width)
t->tabwidth[0] = max_width;
if (t->total_width > 0)
t->tabwidth[0] = max_width;
else if (t->fixed_width[0] > 0)
t->tabwidth[0] = t->fixed_width[0];
if (t->tabwidth[0] < t->minimum_width[0])
t->tabwidth[0] = t->minimum_width[0];
}
else {
set_table_matrix(t, max_width);
itr = 0;
mat = m_get(t->maxcol + 1, t->maxcol + 1);
pivot = px_get(t->maxcol + 1);
newwidth = v_get(t->maxcol + 1);
minv = m_get(t->maxcol + 1, t->maxcol + 1);
do {
m_copy(t->matrix, mat);
LUfactor(mat, pivot);
LUsolve(mat, pivot, t->vector, newwidth);
LUinverse(mat, pivot, minv);
#ifdef TABLE_DEBUG
set_integered_width(t, newwidth->ve, new_tabwidth);
fprintf(stderr, "itr=%d\n", itr);
fprintf(stderr, "max_width=%d\n", max_width);
fprintf(stderr, "minimum : ");
for (i = 0; i <= t->maxcol; i++)
fprintf(stderr, "%2d ", t->minimum_width[i]);
fprintf(stderr, "\nfixed : ");
for (i = 0; i <= t->maxcol; i++)
fprintf(stderr, "%2d ", t->fixed_width[i]);
fprintf(stderr, "\ndecided : ");
for (i = 0; i <= t->maxcol; i++)
fprintf(stderr, "%2d ", new_tabwidth[i]);
fprintf(stderr, "\n");
#endif
itr++;
} while (check_table_width(t, newwidth->ve, minv, itr));
set_integered_width(t, newwidth->ve, new_tabwidth);
check_minimum_width(t, new_tabwidth);
v_free(newwidth);
px_free(pivot);
m_free(mat);
m_free(minv);
m_free(t->matrix);
v_free(t->vector);
for (i = 0; i <= t->maxcol; i++) {
t->tabwidth[i] = new_tabwidth[i];
}
}
#else
set_table_width(t, new_tabwidth, max_width);
for (i = 0; i <= t->maxcol; i++) {
t->tabwidth[i] = new_tabwidth[i];
}
#endif
check_minimum_width(t, t->tabwidth);
for (i = 0; i <= t->maxcol; i++)
t->tabwidth[i] = ceil_at_intervals(t->tabwidth[i], rulewidth);
renderCoTable(t, h_env->limit);
for (i = 0; i <= t->maxcol; i++) {
for (j = 0; j <= t->maxrow; j++) {
check_row(t, j);
if (t->tabattr[j][i] & HTT_Y)
continue;
do_refill(t, j, i, h_env->limit);
}
}
check_minimum_width(t, t->tabwidth);
t->total_width = 0;
for (i = 0; i <= t->maxcol; i++) {
t->tabwidth[i] = ceil_at_intervals(t->tabwidth[i], rulewidth);
t->total_width += t->tabwidth[i];
}
t->total_width += table_border_width(t);
check_table_height(t);
for (i = 0; i <= t->maxcol; i++) {
for (j = 0; j <= t->maxrow; j++) {
TextLineList *l;
int k;
if ((t->tabattr[j][i] & HTT_Y) ||
(t->tabattr[j][i] & HTT_TOP) || (t->tabdata[j][i] == NULL))
continue;
h = t->tabheight[j];
for (k = j + 1; k <= t->maxrow; k++) {
if (!(t->tabattr[k][i] & HTT_Y))
break;
h += t->tabheight[k];
switch (t->border_mode) {
case BORDER_THIN:
case BORDER_THICK:
case BORDER_NOWIN:
h += 1;
break;
}
}
h -= t->tabdata[j][i]->nitem;
if (t->tabattr[j][i] & HTT_MIDDLE)
h /= 2;
if (h <= 0)
continue;
l = newTextLineList();
for (k = 0; k < h; k++)
pushTextLine(l, newTextLine(NULL, 0));
t->tabdata[j][i] = appendGeneralList((GeneralList *)l,
t->tabdata[j][i]);
}
}
width = t->total_width;
make_caption(t, h_env);
HTMLlineproc1("<pre for_table>", h_env);
#ifdef ID_EXT
if (t->id != NULL) {
idtag = Sprintf("<_id id=\"%s\">", html_quote((t->id)->ptr));
HTMLlineproc1(idtag->ptr, h_env);
}
#endif
switch (t->border_mode) {
case BORDER_THIN:
case BORDER_THICK:
renderbuf = Strnew();
print_sep(t, -1, T_TOP, t->maxcol, renderbuf);
push_render_image(renderbuf, width, t->total_width, h_env);
t->total_height += 1;
break;
}
vruleb = Strnew();
switch (t->border_mode) {
case BORDER_THIN:
case BORDER_THICK:
vrulea = Strnew();
vrulec = Strnew();
push_symbol(vrulea, TK_VERTICALBAR(t->border_mode), symbol_width, 1);
for (i = 0; i < t->cellpadding; i++) {
Strcat_char(vrulea, ' ');
Strcat_char(vruleb, ' ');
Strcat_char(vrulec, ' ');
}
push_symbol(vrulec, TK_VERTICALBAR(t->border_mode), symbol_width, 1);
case BORDER_NOWIN:
push_symbol(vruleb, TK_VERTICALBAR(BORDER_THIN), symbol_width, 1);
for (i = 0; i < t->cellpadding; i++)
Strcat_char(vruleb, ' ');
break;
case BORDER_NONE:
for (i = 0; i < t->cellspacing; i++)
Strcat_char(vruleb, ' ');
}
for (r = 0; r <= t->maxrow; r++) {
for (h = 0; h < t->tabheight[r]; h++) {
renderbuf = Strnew();
if (t->border_mode == BORDER_THIN
|| t->border_mode == BORDER_THICK)
Strcat(renderbuf, vrulea);
#ifdef ID_EXT
if (t->tridvalue[r] != NULL && h == 0) {
idtag = Sprintf("<_id id=\"%s\">",
html_quote((t->tridvalue[r])->ptr));
Strcat(renderbuf, idtag);
}
#endif
for (i = 0; i <= t->maxcol; i++) {
check_row(t, r);
#ifdef ID_EXT
if (t->tabidvalue[r][i] != NULL && h == 0) {
idtag = Sprintf("<_id id=\"%s\">",
html_quote((t->tabidvalue[r][i])->ptr));
Strcat(renderbuf, idtag);
}
#endif
if (!(t->tabattr[r][i] & HTT_X)) {
w = t->tabwidth[i];
for (j = i + 1;
j <= t->maxcol && (t->tabattr[r][j] & HTT_X); j++)
w += t->tabwidth[j] + t->cellspacing;
if (t->tabattr[r][i] & HTT_Y) {
for (j = r - 1; j >= 0 && t->tabattr[j]
&& (t->tabattr[j][i] & HTT_Y); j--) ;
print_item(t, j, i, w, renderbuf);
}
else
print_item(t, r, i, w, renderbuf);
}
if (i < t->maxcol && !(t->tabattr[r][i + 1] & HTT_X))
Strcat(renderbuf, vruleb);
}
switch (t->border_mode) {
case BORDER_THIN:
case BORDER_THICK:
Strcat(renderbuf, vrulec);
t->total_height += 1;
break;
}
push_render_image(renderbuf, width, t->total_width, h_env);
}
if (r < t->maxrow && t->border_mode != BORDER_NONE) {
renderbuf = Strnew();
print_sep(t, r, T_MIDDLE, t->maxcol, renderbuf);
push_render_image(renderbuf, width, t->total_width, h_env);
}
t->total_height += t->tabheight[r];
}
switch (t->border_mode) {
case BORDER_THIN:
case BORDER_THICK:
renderbuf = Strnew();
print_sep(t, t->maxrow, T_BOTTOM, t->maxcol, renderbuf);
push_render_image(renderbuf, width, t->total_width, h_env);
t->total_height += 1;
break;
}
if (t->total_height == 0) {
renderbuf = Strnew_charp(" ");
t->total_height++;
t->total_width = 1;
push_render_image(renderbuf, 1, t->total_width, h_env);
}
HTMLlineproc1("</pre>", h_env);
}

static Image *ReadCAPTIONImage(const ImageInfo *image_info,
ExceptionInfo *exception)
{
char
*caption,
geometry[MagickPathExtent],
*text;
const char
*gravity,
*option;
DrawInfo
*draw_info;
Image
*image;
MagickBooleanType
left_bearing,
split,
status;
size_t
height,
width;
ssize_t
i;
TypeMetric
metrics;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickCoreSignature);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
if (IsEventLogging() != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
image_info->filename);
image=AcquireImage(image_info,exception);
(void) ResetImagePage(image,"0x0+0+0");
if ((image->columns != 0) && (image->rows != 0))
(void) SetImageBackgroundColor(image,exception);
option=GetImageOption(image_info,"filename");
if (option == (const char *) NULL)
caption=InterpretImageProperties((ImageInfo *) image_info,image,
image_info->filename,exception);
else
if (LocaleNCompare(option,"caption:",8) == 0)
caption=InterpretImageProperties((ImageInfo *) image_info,image,option+8,
exception);
else
caption=InterpretImageProperties((ImageInfo *) image_info,image,option,
exception);
if (caption == (char *) NULL)
return(DestroyImageList(image));
(void) SetImageProperty(image,"caption",caption,exception);
draw_info=CloneDrawInfo(image_info,(DrawInfo *) NULL);
width=(size_t) floor(0.5*draw_info->pointsize*strlen(caption)+0.5);
if (AcquireMagickResource(WidthResource,width) == MagickFalse)
{
caption=DestroyString(caption);
draw_info=DestroyDrawInfo(draw_info);
ThrowReaderException(ImageError,"WidthOrHeightExceedsLimit");
}
(void) CloneString(&draw_info->text,caption);
gravity=GetImageOption(image_info,"gravity");
if (gravity != (char *) NULL)
draw_info->gravity=(GravityType) ParseCommandOption(MagickGravityOptions,
MagickFalse,gravity);
split=IsStringTrue(GetImageOption(image_info,"caption:split"));
status=MagickTrue;
(void) memset(&metrics,0,sizeof(metrics));
if (image->columns == 0)
{
text=AcquireString(caption);
i=FormatMagickCaption(image,draw_info,split,&metrics,&text,exception);
AdjustTypeMetricBounds(&metrics);
(void) CloneString(&draw_info->text,text);
text=DestroyString(text);
(void) FormatLocaleString(geometry,MagickPathExtent,"%+g%+g",
metrics.bounds.x1,metrics.ascent);
if (draw_info->gravity == UndefinedGravity)
(void) CloneString(&draw_info->geometry,geometry);
status=GetMultilineTypeMetrics(image,draw_info,&metrics,exception);
AdjustTypeMetricBounds(&metrics);
image->columns=(size_t) floor(metrics.width+draw_info->stroke_width+0.5);
}
if (image->rows == 0)
{
split=MagickTrue;
text=AcquireString(caption);
i=FormatMagickCaption(image,draw_info,split,&metrics,&text,exception);
AdjustTypeMetricBounds(&metrics);
(void) CloneString(&draw_info->text,text);
text=DestroyString(text);
(void) FormatLocaleString(geometry,MagickPathExtent,"%+g%+g",
metrics.bounds.x1,metrics.ascent);
if (draw_info->gravity == UndefinedGravity)
(void) CloneString(&draw_info->geometry,geometry);
status=GetMultilineTypeMetrics(image,draw_info,&metrics,exception);
AdjustTypeMetricBounds(&metrics);
image->rows=(size_t) ((i+1)*(metrics.ascent-metrics.descent+
draw_info->interline_spacing+draw_info->stroke_width)+0.5);
}
if (status != MagickFalse)
status=SetImageExtent(image,image->columns,image->rows,exception);
if (status == MagickFalse)
{ 
caption=DestroyString(caption);
draw_info=DestroyDrawInfo(draw_info);
return(DestroyImageList(image));
}
if (SetImageBackgroundColor(image,exception) == MagickFalse)
{
caption=DestroyString(caption);
draw_info=DestroyDrawInfo(draw_info);
image=DestroyImageList(image);
return((Image *) NULL);
}
if ((fabs(image_info->pointsize) < MagickEpsilon) && (strlen(caption) > 0))
{
double
high,
low;
ssize_t
n;
low=1.0;
option=GetImageOption(image_info,"caption:max-pointsize");
if (option != (const char*) NULL)
{
high=StringToDouble(option,(char**) NULL);
if (high < 1.0)
high=1.0;
high+=1.0;
}
else
{
option=GetImageOption(image_info,"caption:start-pointsize");
if (option != (const char *) NULL)
{
draw_info->pointsize=StringToDouble(option,(char**) NULL);
if (draw_info->pointsize < 1.0)
draw_info->pointsize=1.0;
}
for (n=0; n < 32; n++, draw_info->pointsize*=2.0)
{
text=AcquireString(caption);
i=FormatMagickCaption(image,draw_info,split,&metrics,&text,
exception);
AdjustTypeMetricBounds(&metrics);
(void) CloneString(&draw_info->text,text);
text=DestroyString(text);
(void) FormatLocaleString(geometry,MagickPathExtent,"%+g%+g",
metrics.bounds.x1,metrics.ascent);
if (draw_info->gravity == UndefinedGravity)
(void) CloneString(&draw_info->geometry,geometry);
status=GetMultilineTypeMetrics(image,draw_info,&metrics,exception);
if (status == MagickFalse)
break;
AdjustTypeMetricBounds(&metrics);
width=(size_t) floor(metrics.width+draw_info->stroke_width+0.5);
height=(size_t) floor(metrics.height-metrics.underline_position+
draw_info->interline_spacing+draw_info->stroke_width+0.5);
if ((image->columns != 0) && (image->rows != 0))
{
if ((width >= image->columns) || (height >= image->rows))
break;
if ((width < image->columns) && (height < image->rows))
low=draw_info->pointsize;
}
else
if (((image->columns != 0) && (width >= image->columns)) ||
((image->rows != 0) && (height >= image->rows)))
break;
}
high=draw_info->pointsize;
}
while ((high-low) > 0.5)
{
draw_info->pointsize=(low+high)/2.0;
text=AcquireString(caption);
i=FormatMagickCaption(image,draw_info,split,&metrics,&text,exception);
AdjustTypeMetricBounds(&metrics);
(void) CloneString(&draw_info->text,text);
text=DestroyString(text);
(void) FormatLocaleString(geometry,MagickPathExtent,"%+g%+g",
metrics.bounds.x1,metrics.ascent);
if (draw_info->gravity == UndefinedGravity)
(void) CloneString(&draw_info->geometry,geometry);
status=GetMultilineTypeMetrics(image,draw_info,&metrics,exception);
if (status == MagickFalse)
break;
AdjustTypeMetricBounds(&metrics);
width=(size_t) floor(metrics.width+draw_info->stroke_width+0.5);
height=(size_t) floor(metrics.height-metrics.underline_position+
draw_info->interline_spacing+draw_info->stroke_width+0.5);
if ((image->columns != 0) && (image->rows != 0))
{
if ((width < image->columns) && (height < image->rows))
low=draw_info->pointsize+0.5;
else
high=draw_info->pointsize-0.5;
}
else
if (((image->columns != 0) && (width < image->columns)) ||
((image->rows != 0) && (height < image->rows)))
low=draw_info->pointsize+0.5;
else
high=draw_info->pointsize-0.5;
}
draw_info->pointsize=floor((low+high)/2.0-0.5);
}
i=FormatMagickCaption(image,draw_info,split,&metrics,&caption,exception);
AdjustTypeMetricBounds(&metrics);
(void) CloneString(&draw_info->text,caption);
caption=DestroyString(caption);
left_bearing=((draw_info->gravity == UndefinedGravity) ||
(draw_info->gravity == NorthWestGravity) || 
(draw_info->gravity == WestGravity) ||
(draw_info->gravity == SouthWestGravity)) ? MagickTrue : MagickFalse;
(void) FormatLocaleString(geometry,MagickPathExtent,"%+g%+g",
(draw_info->direction == RightToLeftDirection ? (double) image->columns-
(draw_info->gravity == UndefinedGravity ? metrics.bounds.x2 : 0.0) : 
(left_bearing != MagickFalse ? metrics.bounds.x1 : 0.0)),
(draw_info->gravity == UndefinedGravity ? 
MagickMax(metrics.ascent,metrics.bounds.y2) : 0.0));
(void) CloneString(&draw_info->geometry,geometry);
status=AnnotateImage(image,draw_info,exception);
if (image_info->pointsize == 0.0)
(void) FormatImageProperty(image,"caption:pointsize","%.*g",
GetMagickPrecision(),draw_info->pointsize);
(void) FormatImageProperty(image,"caption:lines","%.*g",GetMagickPrecision(),
(double) (i+1));
draw_info=DestroyDrawInfo(draw_info);
if (status == MagickFalse)
{
image=DestroyImageList(image);
return((Image *) NULL);
}
return(GetFirstImageInList(image));
}

static int get_cert_name(gnutls_x509_crt_t cert, char *name, size_t namelen)
{
if (gnutls_x509_crt_get_dn_by_oid(cert, GNUTLS_OID_X520_COMMON_NAME,
0, 0, name, &namelen) &&
gnutls_x509_crt_get_dn(cert, name, &namelen)) {
name[namelen-1] = 0;
snprintf(name, namelen-1, "<unknown>");
return -EINVAL;
}
return 0;
}

static MagickBooleanType WriteMAPImage(const ImageInfo *image_info,Image *image,
ExceptionInfo *exception)
{
MagickBooleanType
status;
register const Quantum
*p;
register ssize_t
i,
x;
register unsigned char
*q;
size_t
depth,
packet_size;
ssize_t
y;
unsigned char
*colormap,
*pixels;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickCoreSignature);
assert(image != (Image *) NULL);
assert(image->signature == MagickCoreSignature);
if (image->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",image->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
status=OpenBlob(image_info,image,WriteBinaryBlobMode,exception);
if (status == MagickFalse)
return(status);
(void) TransformImageColorspace(image,sRGBColorspace,exception);
if (IsPaletteImage(image) == MagickFalse)
(void) SetImageType(image,PaletteType,exception);
depth=GetImageQuantumDepth(image,MagickTrue);
packet_size=(size_t) (depth/8);
pixels=(unsigned char *) AcquireQuantumMemory(image->columns,packet_size*
sizeof(*pixels));
packet_size=(size_t) (image->colors > 256 ? 6UL : 3UL);
colormap=(unsigned char *) AcquireQuantumMemory(image->colors,packet_size*
sizeof(*colormap));
if ((pixels == (unsigned char *) NULL) ||
(colormap == (unsigned char *) NULL))
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
q=colormap;
q=colormap;
if (image->colors <= 256)
for (i=0; i < (ssize_t) image->colors; i++)
{
*q++=(unsigned char) ScaleQuantumToChar(image->colormap[i].red);
*q++=(unsigned char) ScaleQuantumToChar(image->colormap[i].green);
*q++=(unsigned char) ScaleQuantumToChar(image->colormap[i].blue);
}
else
for (i=0; i < (ssize_t) image->colors; i++)
{
*q++=(unsigned char) (ScaleQuantumToShort(image->colormap[i].red) >> 8);
*q++=(unsigned char) (ScaleQuantumToShort(image->colormap[i].red) & 0xff);
*q++=(unsigned char) (ScaleQuantumToShort(image->colormap[i].green) >> 8);
*q++=(unsigned char) (ScaleQuantumToShort(image->colormap[i].green) & 0xff);;
*q++=(unsigned char) (ScaleQuantumToShort(image->colormap[i].blue) >> 8);
*q++=(unsigned char) (ScaleQuantumToShort(image->colormap[i].blue) & 0xff);
}
(void) WriteBlob(image,packet_size*image->colors,colormap);
colormap=(unsigned char *) RelinquishMagickMemory(colormap);
for (y=0; y < (ssize_t) image->rows; y++)
{
p=GetVirtualPixels(image,0,y,image->columns,1,exception);
if (p == (const Quantum *) NULL)
break;
q=pixels;
for (x=0; x < (ssize_t) image->columns; x++)
{
if (image->colors > 256)
*q++=(unsigned char) ((size_t) GetPixelIndex(image,p) >> 8);
*q++=(unsigned char) GetPixelIndex(image,p);
p+=GetPixelChannels(image);
}
(void) WriteBlob(image,(size_t) (q-pixels),pixels);
}
pixels=(unsigned char *) RelinquishMagickMemory(pixels);
(void) CloseBlob(image);
return(status);
}

static Image *ReadPATTERNImage(const ImageInfo *image_info,
ExceptionInfo *exception)
{
const void
*blob;
Image
*image;
ImageInfo
*blob_info;
register ssize_t
i;
size_t
extent;
blob_info=CloneImageInfo(image_info);
image=(Image *) NULL;
blob=(const void *) NULL;
extent=0;
for (i=0; PatternImageList[i].blob != (const void *) NULL; i++)
if (LocaleCompare(blob_info->filename,PatternImageList[i].name) == 0)
{
(void) CopyMagickString(blob_info->magick,PatternImageList[i].magick,
MaxTextExtent);
blob=PatternImageList[i].blob;
extent=PatternImageList[i].extent;
break;
}
if (blob == (const void *) NULL)
ThrowReaderException(OptionError,"UnrecognizedImageFormat");
image=BlobToImage(blob_info,blob,extent,exception);
if (image_info->size != (char *) NULL)
{
Image
*pattern_image;
pattern_image=image;
image=AcquireImage(image_info);
