input_max_float, actual_min_float, actual_max_float, output);
}
}
output_min->flat<float>().setConstant(actual_min_float);
output_max->flat<float>().setConstant(actual_max_float);
}

int rad_packet_recv(int fd, struct rad_packet_t **p, struct sockaddr_in *addr)
{
struct rad_packet_t *pack;
struct rad_attr_t *attr;
struct rad_dict_attr_t *da;
struct rad_dict_vendor_t *vendor;
uint8_t *ptr;
int n, id, len, vendor_id;
socklen_t addr_len = sizeof(*addr);
*p = NULL;
pack = rad_packet_alloc(0);
if (!pack)
return 0;
ptr = mempool_alloc(buf_pool);
if (ptr == MAP_FAILED) {
log_emerg("radius:packet: out of memory\n");
goto out_err;
}
pack->buf = ptr;
clock_gettime(CLOCK_MONOTONIC, &pack->tv);
while (1) {
if (addr)
n = recvfrom(fd, pack->buf, REQ_LENGTH_MAX, 0, addr, &addr_len);
else
n = read(fd, pack->buf, REQ_LENGTH_MAX);
if (n < 0) {
rad_packet_free(pack);
if (errno == EAGAIN)
return 1;
if (errno != ECONNREFUSED)
log_ppp_error("radius:packet:read: %s\n", strerror(errno));
return -1;
}
break;
}
if (n < 20) {
log_ppp_warn("radius:packet: short packed received (%i)\n", n);
goto out_err;
}
pack->code = *ptr; ptr++;
pack->id = *ptr; ptr++;
pack->len = ntohs(*(uint16_t*)ptr); ptr += 2;
if (pack->len > n) {
log_ppp_warn("radius:packet: short packet received %i, expected %i\n", pack->len, n);
goto out_err;
}
ptr += 16;
n -= 20;
while (n>0) {
id = *ptr; ptr++;
len = *ptr - 2; ptr++;
if (len < 0) {
log_ppp_warn("radius:packet short attribute len received\n");
goto out_err;
}
if (2 + len > n) {
log_ppp_warn("radius:packet: too long attribute received (%i, %i)\n", id, len);
goto out_err;
}
if (id == 26) {
vendor_id = ntohl(*(uint32_t *)ptr);
vendor = rad_dict_find_vendor_id(vendor_id);
if (vendor) {
ptr += 4;
if (vendor->tag == 2)
id = (uint16_t)ntohs(*(uint16_t *)ptr);
else
id = *ptr;
ptr += vendor->tag;
if (vendor->len == 2)
len = (uint16_t)ntohs(*(uint16_t *)ptr);
else
len = *ptr;
ptr += vendor->len;
len -= vendor->tag + vendor->len;
n -= 4 + vendor->tag + vendor->len;
if (len < 0) {
log_ppp_warn("radius:packet invalid vendor attribute len received\n");
goto out_err;
}
if (2 + len > n) {
log_ppp_warn("radius:packet: too long vendor attribute received (%i, %i)\n", id, len);
goto out_err;
}
} else
log_ppp_warn("radius:packet: vendor %i not found\n", id);
} else
vendor = NULL;
da = rad_dict_find_attr_id(vendor, id);
if (da) {
attr = mempool_alloc(attr_pool);
if (!attr) {
log_emerg("radius:packet: out of memory\n");
goto out_err;
}
memset(attr, 0, sizeof(*attr));
attr->vendor = vendor;
attr->attr = da;
attr->len = len;
attr->raw = ptr;
if (!da->array) {
switch (da->type) {
case ATTR_TYPE_STRING:
attr->alloc = 1;
attr->val.string = _malloc(len + 1);
memcpy(attr->val.string, ptr, len);
attr->val.string[len] = 0;
break;
case ATTR_TYPE_OCTETS:
case ATTR_TYPE_ETHER:
case ATTR_TYPE_TLV:
attr->val.octets = ptr;
break;
case ATTR_TYPE_INTEGER:
if (len != da->size)
log_ppp_warn("radius:packet: attribute %s has invalid length %i (must be %i)\n", da->name, len, da->size);
case ATTR_TYPE_DATE:
if (len == 4)
attr->val.integer = ntohl(*(uint32_t*)ptr);
else if (len == 2)
attr->val.integer = ntohs(*(uint16_t*)ptr);
else if (len == 1)
attr->val.integer = *ptr;
break;
case ATTR_TYPE_IPADDR:
case ATTR_TYPE_IFID:
case ATTR_TYPE_IPV6ADDR:
memcpy(&attr->val.integer, ptr, len);
break;
case ATTR_TYPE_IPV6PREFIX:
attr->val.ipv6prefix.len = ptr[1];
memset(&attr->val.ipv6prefix.prefix, 0, sizeof(attr->val.ipv6prefix.prefix));
memcpy(&attr->val.ipv6prefix.prefix, ptr + 2, len - 2);
break;
}
}
list_add_tail(&attr->entry, &pack->attrs);
} else
log_ppp_warn("radius:packet: unknown attribute received (%i,%i)\n", vendor ? vendor->id : 0, id);
ptr += len;
n -= 2 + len;
}
*p = pack;
return 0;
out_err:
rad_packet_free(pack);
return 1;
}

service_info *FindServiceEventURLPath(
service_table *table, const char *eventURLPath)
{
service_info *finger = NULL;
uri_type parsed_url;
uri_type parsed_url_in;
if (table &&
parse_uri(eventURLPath, strlen(eventURLPath), &parsed_url_in) ==
HTTP_SUCCESS) {
finger = table->serviceList;
while (finger) {
if (finger->eventURL) {
if (parse_uri(finger->eventURL,
strlen(finger->eventURL),
&parsed_url) == HTTP_SUCCESS) {
if (!token_cmp(&parsed_url.pathquery,
&parsed_url_in.pathquery)) {
return finger;
}
}
}
finger = finger->next;
}
}
return NULL;
}

static GLboolean
alloc_back_shm_ximage(XMesaBuffer b, GLuint width, GLuint height)
{
GC gc;
int (*old_handler)(XMesaDisplay *, XErrorEvent *);
if (width == 0 || height == 0) {
return GL_FALSE;
}
b->backxrb->ximage = XShmCreateImage(b->xm_visual->display,
b->xm_visual->visinfo->visual,
b->xm_visual->visinfo->depth,
ZPixmap, NULL, &b->shminfo,
width, height);
if (b->backxrb->ximage == NULL) {
_mesa_warning(NULL, "alloc_back_buffer: Shared memory error (XShmCreateImage), disabling.\n");
b->shm = 0;
return GL_FALSE;
}
b->shminfo.shmid = shmget(IPC_PRIVATE, b->backxrb->ximage->bytes_per_line
* b->backxrb->ximage->height, IPC_CREAT|0777);
if (b->shminfo.shmid < 0) {
_mesa_warning(NULL, "shmget failed while allocating back buffer.\n");
XDestroyImage(b->backxrb->ximage);
b->backxrb->ximage = NULL;
_mesa_warning(NULL, "alloc_back_buffer: Shared memory error (shmget), disabling.\n");
b->shm = 0;
return GL_FALSE;
}
b->shminfo.shmaddr = b->backxrb->ximage->data
= (char*)shmat(b->shminfo.shmid, 0, 0);
if (b->shminfo.shmaddr == (char *) -1) {
_mesa_warning(NULL, "shmat() failed while allocating back buffer.\n");
XDestroyImage(b->backxrb->ximage);
shmctl(b->shminfo.shmid, IPC_RMID, 0);
b->backxrb->ximage = NULL;
_mesa_warning(NULL, "alloc_back_buffer: Shared memory error (shmat), disabling.\n");
b->shm = 0;
return GL_FALSE;
}
b->shminfo.readOnly = False;
mesaXErrorFlag = 0;
old_handler = XSetErrorHandler(mesaHandleXError);
XShmAttach(b->xm_visual->display, &b->shminfo);
XSync(b->xm_visual->display, False);
if (mesaXErrorFlag) {
XFlush(b->xm_visual->display);
mesaXErrorFlag = 0;
XDestroyImage(b->backxrb->ximage);
shmdt(b->shminfo.shmaddr);
shmctl(b->shminfo.shmid, IPC_RMID, 0);
b->backxrb->ximage = NULL;
b->shm = 0;
(void) XSetErrorHandler(old_handler);
return GL_FALSE;
}
shmctl(b->shminfo.shmid, IPC_RMID, 0); 
gc = XCreateGC(b->xm_visual->display, b->frontxrb->drawable, 0, NULL);
XShmPutImage(b->xm_visual->display, b->frontxrb->drawable, gc,
b->backxrb->ximage, 0, 0, 0, 0, 1, 1 , False);
XSync(b->xm_visual->display, False);
XFreeGC(b->xm_visual->display, gc);
(void) XSetErrorHandler(old_handler);
if (mesaXErrorFlag) {
XFlush(b->xm_visual->display);
mesaXErrorFlag = 0;
XDestroyImage(b->backxrb->ximage);
shmdt(b->shminfo.shmaddr);
shmctl(b->shminfo.shmid, IPC_RMID, 0);
b->backxrb->ximage = NULL;
b->shm = 0;
return GL_FALSE;
}
return GL_TRUE;
}

