mesaXErrorFlag = 0;
XDestroyImage(b->backxrb->ximage);
shmdt(b->shminfo.shmaddr);
shmctl(b->shminfo.shmid, IPC_RMID, 0);
b->backxrb->ximage = NULL;
b->shm = 0;
return GL_FALSE;
}
return GL_TRUE;
}

int bus_verify_polkit_async(
sd_bus_message *call,
int capability,
const char *action,
const char **details,
bool interactive,
uid_t good_user,
Hashmap **registry,
sd_bus_error *ret_error) {
#if ENABLE_POLKIT
_cleanup_(sd_bus_message_unrefp) sd_bus_message *pk = NULL;
AsyncPolkitQuery *q;
const char *sender;
sd_bus_message_handler_t callback;
void *userdata;
int c;
#endif
int r;
assert(call);
assert(action);
assert(registry);
r = check_good_user(call, good_user);
if (r != 0)
return r;
#if ENABLE_POLKIT
q = hashmap_get(*registry, call);
if (q) {
int authorized, challenge;
assert(q->reply);
if (!streq(q->action, action) ||
!strv_equal(q->details, (char**) details))
return -ESTALE;
if (sd_bus_message_is_method_error(q->reply, NULL)) {
const sd_bus_error *e;
e = sd_bus_message_get_error(q->reply);
if (sd_bus_error_has_name(e, SD_BUS_ERROR_SERVICE_UNKNOWN) ||
sd_bus_error_has_name(e, SD_BUS_ERROR_NAME_HAS_NO_OWNER))
return -EACCES;
sd_bus_error_copy(ret_error, e);
return -sd_bus_error_get_errno(e);
}
r = sd_bus_message_enter_container(q->reply, 'r', "bba{ss}");
if (r >= 0)
r = sd_bus_message_read(q->reply, "bb", &authorized, &challenge);
if (r < 0)
return r;
if (authorized)
return 1;
if (challenge)
return sd_bus_error_set(ret_error, SD_BUS_ERROR_INTERACTIVE_AUTHORIZATION_REQUIRED, "Interactive authentication required.");
return -EACCES;
}
#endif
r = sd_bus_query_sender_privilege(call, capability);
if (r < 0)
return r;
else if (r > 0)
return 1;
#if ENABLE_POLKIT
if (sd_bus_get_current_message(call->bus) != call)
return -EINVAL;
callback = sd_bus_get_current_handler(call->bus);
if (!callback)
return -EINVAL;
userdata = sd_bus_get_current_userdata(call->bus);
sender = sd_bus_message_get_sender(call);
if (!sender)
return -EBADMSG;
c = sd_bus_message_get_allow_interactive_authorization(call);
if (c < 0)
return c;
if (c > 0)
interactive = true;
r = hashmap_ensure_allocated(registry, NULL);
if (r < 0)
return r;
r = sd_bus_message_new_method_call(
call->bus,
&pk,
"org.freedesktop.PolicyKit1",
"/org/freedesktop/PolicyKit1/Authority",
"org.freedesktop.PolicyKit1.Authority",
"CheckAuthorization");
if (r < 0)
return r;
r = sd_bus_message_append(
pk,
"(sa{sv})s",
"system-bus-name", 1, "name", "s", sender,
action);
if (r < 0)
return r;
r = bus_message_append_strv_key_value(pk, details);
if (r < 0)
return r;
r = sd_bus_message_append(pk, "us", interactive, NULL);
if (r < 0)
return r;
q = new(AsyncPolkitQuery, 1);
if (!q)
return -ENOMEM;
*q = (AsyncPolkitQuery) {
.request = sd_bus_message_ref(call),
.callback = callback,
.userdata = userdata,
};
q->action = strdup(action);
if (!q->action) {
async_polkit_query_free(q);
return -ENOMEM;
}
q->details = strv_copy((char**) details);
if (!q->details) {
async_polkit_query_free(q);
return -ENOMEM;
}
r = hashmap_put(*registry, call, q);
if (r < 0) {
async_polkit_query_free(q);
return r;
}
q->registry = *registry;
r = sd_bus_call_async(call->bus, &q->slot, pk, async_polkit_callback, q, 0);
if (r < 0) {
async_polkit_query_free(q);
return r;
}
return 0;
#endif
return -EACCES;
}

static int f_midi_set_alt(struct usb_function *f, unsigned intf, unsigned alt)
{
struct f_midi *midi = func_to_midi(f);
unsigned i;
int err;
if (intf != midi->ms_id)
return 0;
err = f_midi_start_ep(midi, f, midi->in_ep);
if (err)
return err;
err = f_midi_start_ep(midi, f, midi->out_ep);
if (err)
return err;
while (kfifo_avail(&midi->in_req_fifo)) {
struct usb_request *req =
midi_alloc_ep_req(midi->in_ep, midi->buflen);
if (req == NULL)
return -ENOMEM;
req->length = 0;
req->complete = f_midi_complete;
kfifo_put(&midi->in_req_fifo, req);
}
for (i = 0; i < midi->qlen && err == 0; i++) {
struct usb_request *req =
midi_alloc_ep_req(midi->out_ep, midi->buflen);
if (req == NULL)
return -ENOMEM;
req->complete = f_midi_complete;
err = usb_ep_queue(midi->out_ep, req, GFP_ATOMIC);
if (err) {
ERROR(midi, "%s: couldn't enqueue request: %d\n",
midi->out_ep->name, err);
free_ep_req(midi->out_ep, req);
return err;
}
}
return 0;
}

static enum hrtimer_restart posix_timer_fn(struct hrtimer *timer)
{
struct k_itimer *timr;
unsigned long flags;
int si_private = 0;
enum hrtimer_restart ret = HRTIMER_NORESTART;
timr = container_of(timer, struct k_itimer, it.real.timer);
spin_lock_irqsave(&timr->it_lock, flags);
timr->it_active = 0;
if (timr->it_interval != 0)
si_private = ++timr->it_requeue_pending;
if (posix_timer_event(timr, si_private)) {
if (timr->it_interval != 0) {
ktime_t now = hrtimer_cb_get_time(timer);
#ifdef CONFIG_HIGH_RES_TIMERS
{
ktime_t kj = NSEC_PER_SEC / HZ;
if (timr->it_interval < kj)
now = ktime_add(now, kj);
}
#endif
timr->it_overrun += (unsigned int)
hrtimer_forward(timer, now,
timr->it_interval);
ret = HRTIMER_RESTART;
++timr->it_requeue_pending;
timr->it_active = 1;
}
}
unlock_timer(timr, flags);
return ret;
}

void
flushline(struct html_feed_environ *h_env, struct readbuffer *obuf, int indent,
int force, int width)
{
TextLineList *buf = h_env->buf;
FILE *f = h_env->f;
Str line = obuf->line, pass = NULL;
char *hidden_anchor = NULL, *hidden_img = NULL, *hidden_bold = NULL,
*hidden_under = NULL, *hidden_italic = NULL, *hidden_strike = NULL,
*hidden_ins = NULL, *hidden_input = NULL, *hidden = NULL;
#ifdef DEBUG
if (w3m_debug) {
FILE *df = fopen("zzzproc1", "a");
fprintf(df, "flushline(%s,%d,%d,%d)\n", obuf->line->ptr, indent, force,
width);
if (buf) {
TextLineListItem *p;
for (p = buf->first; p; p = p->next) {
fprintf(df, "buf=\"%s\"\n", p->ptr->line->ptr);
}
}
fclose(df);
}
#endif
if (!(obuf->flag & (RB_SPECIAL & ~RB_NOBR)) && Strlastchar(line) == ' ') {
Strshrink(line, 1);
obuf->pos--;
}
append_tags(obuf);
if (obuf->anchor.url)
hidden = hidden_anchor = has_hidden_link(obuf, HTML_A);
if (obuf->img_alt) {
if ((hidden_img = has_hidden_link(obuf, HTML_IMG_ALT)) != NULL) {
if (!hidden || hidden_img < hidden)
hidden = hidden_img;
}
}
if (obuf->input_alt.in) {
if ((hidden_input = has_hidden_link(obuf, HTML_INPUT_ALT)) != NULL) {
if (!hidden || hidden_input < hidden)
hidden = hidden_input;
}
}
if (obuf->in_bold) {
if ((hidden_bold = has_hidden_link(obuf, HTML_B)) != NULL) {
if (!hidden || hidden_bold < hidden)
hidden = hidden_bold;
}
}
if (obuf->in_italic) {
if ((hidden_italic = has_hidden_link(obuf, HTML_I)) != NULL) {
if (!hidden || hidden_italic < hidden)
hidden = hidden_italic;
}
}
if (obuf->in_under) {
if ((hidden_under = has_hidden_link(obuf, HTML_U)) != NULL) {
if (!hidden || hidden_under < hidden)
hidden = hidden_under;
}
}
if (obuf->in_strike) {
if ((hidden_strike = has_hidden_link(obuf, HTML_S)) != NULL) {
if (!hidden || hidden_strike < hidden)
hidden = hidden_strike;
}
}
if (obuf->in_ins) {
if ((hidden_ins = has_hidden_link(obuf, HTML_INS)) != NULL) {
if (!hidden || hidden_ins < hidden)
hidden = hidden_ins;
}
}
if (hidden) {
pass = Strnew_charp(hidden);
Strshrink(line, line->ptr + line->length - hidden);
}
if (!(obuf->flag & (RB_SPECIAL & ~RB_NOBR)) && obuf->pos > width) {
char *tp = &line->ptr[obuf->bp.len - obuf->bp.tlen];
char *ep = &line->ptr[line->length];
if (obuf->bp.pos == obuf->pos && tp <= ep &&
tp > line->ptr && tp[-1] == ' ') {
bcopy(tp, tp - 1, ep - tp + 1);
line->length--;
obuf->pos--;
}
}
if (obuf->anchor.url && !hidden_anchor)
Strcat_charp(line, "</a>");
if (obuf->img_alt && !hidden_img)
Strcat_charp(line, "</img_alt>");
if (obuf->input_alt.in && !hidden_input)
Strcat_charp(line, "</input_alt>");
if (obuf->in_bold && !hidden_bold)
Strcat_charp(line, "</b>");
if (obuf->in_italic && !hidden_italic)
Strcat_charp(line, "</i>");
if (obuf->in_under && !hidden_under)
Strcat_charp(line, "</u>");
if (obuf->in_strike && !hidden_strike)
Strcat_charp(line, "</s>");
if (obuf->in_ins && !hidden_ins)
Strcat_charp(line, "</ins>");
if (obuf->top_margin > 0) {
int i;
struct html_feed_environ h;
struct readbuffer o;
struct environment e[1];
init_henv(&h, &o, e, 1, NULL, width, indent);
o.line = Strnew_size(width + 20);
o.pos = obuf->pos;
o.flag = obuf->flag;
o.top_margin = -1;
o.bottom_margin = -1;
Strcat_charp(o.line, "<pre_int>");
for (i = 0; i < o.pos; i++)
Strcat_char(o.line, ' ');
Strcat_charp(o.line, "</pre_int>");
for (i = 0; i < obuf->top_margin; i++)
flushline(h_env, &o, indent, force, width);
}
if (force == 1 || obuf->flag & RB_NFLUSHED) {
TextLine *lbuf = newTextLine(line, obuf->pos);
if (RB_GET_ALIGN(obuf) == RB_CENTER) {
align(lbuf, width, ALIGN_CENTER);
}
else if (RB_GET_ALIGN(obuf) == RB_RIGHT) {
align(lbuf, width, ALIGN_RIGHT);
}
else if (RB_GET_ALIGN(obuf) == RB_LEFT && obuf->flag & RB_INTABLE) {
align(lbuf, width, ALIGN_LEFT);
}
#ifdef FORMAT_NICE
else if (obuf->flag & RB_FILL) {
char *p;
int rest, rrest;
int nspace, d, i;
rest = width - get_Str_strwidth(line);
if (rest > 1) {
nspace = 0;
for (p = line->ptr + indent; *p; p++) {
if (*p == ' ')
nspace++;
}
if (nspace > 0) {
int indent_here = 0;
d = rest / nspace;
p = line->ptr;
while (IS_SPACE(*p)) {
p++;
indent_here++;
}
rrest = rest - d * nspace;
line = Strnew_size(width + 1);
for (i = 0; i < indent_here; i++)
Strcat_char(line, ' ');
for (; *p; p++) {
Strcat_char(line, *p);
if (*p == ' ') {
for (i = 0; i < d; i++)
Strcat_char(line, ' ');
if (rrest > 0) {
Strcat_char(line, ' ');
rrest--;
}
}
}
lbuf = newTextLine(line, width);
}
}
}
#endif
#ifdef TABLE_DEBUG
if (w3m_debug) {
FILE *f = fopen("zzzproc1", "a");
fprintf(f, "pos=%d,%d, maxlimit=%d\n",
visible_length(lbuf->line->ptr), lbuf->pos,
h_env->maxlimit);
fclose(f);
}
#endif
if (lbuf->pos > h_env->maxlimit)
h_env->maxlimit = lbuf->pos;
if (buf)
pushTextLine(buf, lbuf);
else if (f) {
Strfputs(Str_conv_to_halfdump(lbuf->line), f);
fputc('\n', f);
}
if (obuf->flag & RB_SPECIAL || obuf->flag & RB_NFLUSHED)
h_env->blank_lines = 0;
else
h_env->blank_lines++;
}
else {
char *p = line->ptr, *q;
Str tmp = Strnew(), tmp2 = Strnew();
#define APPEND(str) \
if (buf) \
appendTextLine(buf,(str),0); \
else if (f) \
Strfputs((str),f)
while (*p) {
q = p;
if (sloppy_parse_line(&p)) {
Strcat_charp_n(tmp, q, p - q);
if (force == 2) {
APPEND(tmp);
}
else
Strcat(tmp2, tmp);
Strclear(tmp);
}
}
if (force == 2) {
if (pass) {
APPEND(pass);
}
pass = NULL;
}
else {
if (pass)
Strcat(tmp2, pass);
pass = tmp2;
}
}
if (obuf->bottom_margin > 0) {
int i;
struct html_feed_environ h;
struct readbuffer o;
struct environment e[1];
init_henv(&h, &o, e, 1, NULL, width, indent);
o.line = Strnew_size(width + 20);
o.pos = obuf->pos;
o.flag = obuf->flag;
o.top_margin = -1;
o.bottom_margin = -1;
Strcat_charp(o.line, "<pre_int>");
for (i = 0; i < o.pos; i++)
Strcat_char(o.line, ' ');
Strcat_charp(o.line, "</pre_int>");
for (i = 0; i < obuf->bottom_margin; i++)
flushline(h_env, &o, indent, force, width);
}
if (obuf->top_margin < 0 || obuf->bottom_margin < 0)
return;
obuf->line = Strnew_size(256);
obuf->pos = 0;
obuf->top_margin = 0;
obuf->bottom_margin = 0;
set_space_to_prevchar(obuf->prevchar);
obuf->bp.init_flag = 1;
obuf->flag &= ~RB_NFLUSHED;
set_breakpoint(obuf, 0);
obuf->prev_ctype = PC_ASCII;
link_stack = NULL;
fillline(obuf, indent);
if (pass)
passthrough(obuf, pass->ptr, 0);
if (!hidden_anchor && obuf->anchor.url) {
Str tmp;
if (obuf->anchor.hseq > 0)
obuf->anchor.hseq = -obuf->anchor.hseq;
tmp = Sprintf("<A HSEQ=\"%d\" HREF=\"", obuf->anchor.hseq);
Strcat_charp(tmp, html_quote(obuf->anchor.url));
if (obuf->anchor.target) {
Strcat_charp(tmp, "\" TARGET=\"");
Strcat_charp(tmp, html_quote(obuf->anchor.target));
}
if (obuf->anchor.referer) {
Strcat_charp(tmp, "\" REFERER=\"");
Strcat_charp(tmp, html_quote(obuf->anchor.referer));
}
if (obuf->anchor.title) {
Strcat_charp(tmp, "\" TITLE=\"");
Strcat_charp(tmp, html_quote(obuf->anchor.title));
}
if (obuf->anchor.accesskey) {
char *c = html_quote_char(obuf->anchor.accesskey);
Strcat_charp(tmp, "\" ACCESSKEY=\"");
if (c)
Strcat_charp(tmp, c);
else
Strcat_char(tmp, obuf->anchor.accesskey);
}
Strcat_charp(tmp, "\">");
push_tag(obuf, tmp->ptr, HTML_A);
}
if (!hidden_img && obuf->img_alt) {
Str tmp = Strnew_charp("<IMG_ALT SRC=\"");
Strcat_charp(tmp, html_quote(obuf->img_alt->ptr));
Strcat_charp(tmp, "\">");
push_tag(obuf, tmp->ptr, HTML_IMG_ALT);
}
if (!hidden_input && obuf->input_alt.in) {
Str tmp;
if (obuf->input_alt.hseq > 0)
obuf->input_alt.hseq = - obuf->input_alt.hseq;
tmp = Sprintf("<INPUT_ALT hseq=\"%d\" fid=\"%d\" name=\"%s\" type=\"%s\" value=\"%s\">",
obuf->input_alt.hseq,
obuf->input_alt.fid,
obuf->input_alt.name->ptr,
obuf->input_alt.type->ptr,
obuf->input_alt.value->ptr);
push_tag(obuf, tmp->ptr, HTML_INPUT_ALT);
}
if (!hidden_bold && obuf->in_bold)
push_tag(obuf, "<B>", HTML_B);
if (!hidden_italic && obuf->in_italic)
push_tag(obuf, "<I>", HTML_I);
if (!hidden_under && obuf->in_under)
push_tag(obuf, "<U>", HTML_U);
if (!hidden_strike && obuf->in_strike)
push_tag(obuf, "<S>", HTML_S);
if (!hidden_ins && obuf->in_ins)
push_tag(obuf, "<INS>", HTML_INS);
}

GF_Err mhas_dmx_process(GF_Filter *filter)
{
GF_MHASDmxCtx *ctx = gf_filter_get_udta(filter);
GF_FilterPacket *in_pck;
u8 *output;
u8 *start;
Bool final_flush=GF_FALSE;
u32 pck_size, remain, prev_pck_size;
u64 cts = GF_FILTER_NO_TS;
u32 au_start = 0;
u32 consumed = 0;
u32 nb_trunc_samples = 0;
Bool trunc_from_begin = 0;
Bool has_cfg = 0;
if (!ctx->duration.num)
mhas_dmx_check_dur(filter, ctx);
if (ctx->opid && !ctx->is_playing)
return GF_OK;
in_pck = gf_filter_pid_get_packet(ctx->ipid);
if (!in_pck) {
if (gf_filter_pid_is_eos(ctx->ipid)) {
if (!ctx->mhas_buffer_size) {
if (ctx->opid)
gf_filter_pid_set_eos(ctx->opid);
if (ctx->src_pck) gf_filter_pck_unref(ctx->src_pck);
ctx->src_pck = NULL;
return GF_EOS;
}
final_flush = GF_TRUE;
} else if (!ctx->resume_from) {
return GF_OK;
}
}
prev_pck_size = ctx->mhas_buffer_size;
if (ctx->resume_from)
in_pck = NULL;
if (in_pck) {
u8 *data = (u8 *) gf_filter_pck_get_data(in_pck, &pck_size);
if (ctx->byte_offset != GF_FILTER_NO_BO) {
u64 byte_offset = gf_filter_pck_get_byte_offset(in_pck);
if (!ctx->mhas_buffer_size) {
ctx->byte_offset = byte_offset;
} else if (ctx->byte_offset + ctx->mhas_buffer_size != byte_offset) {
ctx->byte_offset = GF_FILTER_NO_BO;
if ((byte_offset != GF_FILTER_NO_BO) && (byte_offset>ctx->mhas_buffer_size) ) {
ctx->byte_offset = byte_offset - ctx->mhas_buffer_size;
}
}
}
if (ctx->mhas_buffer_size + pck_size > ctx->mhas_buffer_alloc) {
ctx->mhas_buffer_alloc = ctx->mhas_buffer_size + pck_size;
ctx->mhas_buffer = gf_realloc(ctx->mhas_buffer, ctx->mhas_buffer_alloc);
}
memcpy(ctx->mhas_buffer + ctx->mhas_buffer_size, data, pck_size);
ctx->mhas_buffer_size += pck_size;
}
if (ctx->timescale && in_pck) {
cts = gf_filter_pck_get_cts(in_pck);
if (!ctx->cts && (cts != GF_FILTER_NO_TS))
ctx->cts = cts;
}
if (cts == GF_FILTER_NO_TS) {
prev_pck_size = 0;
}
remain = ctx->mhas_buffer_size;
start = ctx->mhas_buffer;
if (ctx->resume_from) {
start += ctx->resume_from - 1;
remain -= ctx->resume_from - 1;
ctx->resume_from = 0;
}
while (ctx->nosync && (remain>3)) {
u8 *hdr_start = memchr(start, 0xC0, remain);
if (!hdr_start) {
remain=0;
break;
}
if ((hdr_start[1]==0x01) && (hdr_start[2]==0xA5)) {
GF_LOG(GF_LOG_DEBUG, GF_LOG_MEDIA, ("[MHASDmx] Sync found !\n"));
ctx->nosync = GF_FALSE;
break;
}
GF_LOG(GF_LOG_DEBUG, GF_LOG_MEDIA, ("[MHASDmx] not sync, skipping byte\n"));
start++;
remain--;
}
if (ctx->nosync)
goto skip;
gf_bs_reassign_buffer(ctx->bs, start, remain);
ctx->buffer_too_small = GF_FALSE;
while (remain > consumed) {
u32 pay_start, parse_end, mhas_size, mhas_label;
Bool mhas_sap = 0;
u32 mhas_type;
if (!ctx->is_playing && ctx->opid) {
ctx->resume_from = 1;
consumed = 0;
break;
}
mhas_type = (u32) gf_mpegh_escaped_value(ctx->bs, 3, 8, 8);
mhas_label = (u32) gf_mpegh_escaped_value(ctx->bs, 2, 8, 32);
mhas_size = (u32) gf_mpegh_escaped_value(ctx->bs, 11, 24, 24);
if (ctx->buffer_too_small)
break;
if (mhas_type>18) {
ctx->nb_unknown_pck++;
if (ctx->nb_unknown_pck > ctx->pcksync) {
GF_LOG(ctx->is_sync ? GF_LOG_WARNING : GF_LOG_DEBUG, GF_LOG_MEDIA, ("[MHASDmx] %d packets of unknown type, considering sync was lost\n"));
ctx->is_sync = GF_FALSE;
consumed = 0;
ctx->nosync = GF_TRUE;
ctx->nb_unknown_pck = 0;
break;
}
} else if (!mhas_size) {
GF_LOG(ctx->is_sync ? GF_LOG_WARNING : GF_LOG_DEBUG, GF_LOG_MEDIA, ("[MHASDmx] MHAS packet with 0 payload size, considering sync was lost\n"));
ctx->is_sync = GF_FALSE;
consumed = 0;
ctx->nosync = GF_TRUE;
ctx->nb_unknown_pck = 0;
break;
}
pay_start = (u32) gf_bs_get_position(ctx->bs);
if (ctx->buffer_too_small) break;
if (mhas_size > gf_bs_available(ctx->bs)) {
GF_LOG(GF_LOG_DEBUG, GF_LOG_MEDIA, ("[MHASDmx] incomplete packet type %d %s label "LLU" size "LLU" - keeping in buffer\n", mhas_type, mhas_pck_name(mhas_type), mhas_label, mhas_size));
break;
}
ctx->is_sync = GF_TRUE;
if (mhas_type==2) {
mhas_sap = gf_bs_peek_bits(ctx->bs, 1, 0);
ctx->nb_unknown_pck = 0;
}
else if (mhas_type==1) {
s32 CICPspeakerLayoutIdx = -1;
s32 numSpeakers = -1;
u32 sr = 0;
u32 frame_len;
u32 pl = gf_bs_read_u8(ctx->bs);
u32 idx = gf_bs_read_int(ctx->bs, 5);
if (idx==0x1f)
sr = gf_bs_read_int(ctx->bs, 24);
else if (sr < nb_usac_sr) {
sr = USACSampleRates[idx];
}
ctx->nb_unknown_pck = 0;
idx = gf_bs_read_int(ctx->bs, 3);
if ((idx==0) || (idx==2) ) frame_len = 768;
else frame_len = 1024;
gf_bs_read_int(ctx->bs, 1);
gf_bs_read_int(ctx->bs, 1);
u32 speakerLayoutType = gf_bs_read_int(ctx->bs, 2);
if (speakerLayoutType == 0) {
CICPspeakerLayoutIdx = gf_bs_read_int(ctx->bs, 6);
} else {
numSpeakers = (s32) gf_mpegh_escaped_value(ctx->bs, 5, 8, 16) + 1;
}
mhas_dmx_check_pid(filter, ctx, pl, sr, frame_len, CICPspeakerLayoutIdx, numSpeakers, start + pay_start, (u32) mhas_size);
has_cfg = GF_TRUE;
}
else if (mhas_type==17) {
Bool isActive = gf_bs_read_int(ctx->bs, 1);
gf_bs_read_int(ctx->bs, 1);
trunc_from_begin = gf_bs_read_int(ctx->bs, 1);
nb_trunc_samples = gf_bs_read_int(ctx->bs, 13);
if (!isActive) {
nb_trunc_samples = 0;
}
}
else if ((mhas_type==6) || (mhas_type==7)) {
ctx->nb_unknown_pck = 0;
}
#if 0
else if (mhas_type==8) {
u8 marker_type = gf_bs_read_u8(ctx->bs);
if (marker_type==0x01) {}
else if (marker_type==0x02) {
has_marker = GF_TRUE;
}
}
#endif
gf_bs_align(ctx->bs);
parse_end = (u32) gf_bs_get_position(ctx->bs) - pay_start;
gf_bs_skip_bytes(ctx->bs, mhas_size - parse_end);
GF_LOG(GF_LOG_DEBUG, GF_LOG_MEDIA, ("[MHASDmx] MHAS Packet type %d %s label "LLU" size "LLU"\n", mhas_type, mhas_pck_name(mhas_type), mhas_label, mhas_size));
if (ctx->timescale && !prev_pck_size && (cts != GF_FILTER_NO_TS) ) {
ctx->cts = cts;
cts = GF_FILTER_NO_TS;
}
if ((mhas_type==2) && ctx->opid) {
GF_FilterPacket *dst;
u64 pck_dur = ctx->frame_len;
u32 au_size;
if (ctx->mpha) {
au_start = pay_start;
au_size = mhas_size;
} else {
au_size = (u32) gf_bs_get_position(ctx->bs) - au_start;
}
if (nb_trunc_samples) {
if (trunc_from_begin) {
if (!ctx->nb_frames) {
s64 offset = trunc_from_begin;
if (ctx->timescale) {
offset *= ctx->timescale;
offset /= ctx->sample_rate;
}
gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_DELAY , &PROP_LONGSINT( -offset));
}
} else {
pck_dur -= nb_trunc_samples;
}
nb_trunc_samples = 0;
}
if (ctx->timescale) {
pck_dur *= ctx->timescale;
pck_dur /= ctx->sample_rate;
}
dst = gf_filter_pck_new_alloc(ctx->opid, au_size, &output);
if (!dst) break;
if (ctx->src_pck) gf_filter_pck_merge_properties(ctx->src_pck, dst);
memcpy(output, start + au_start, au_size);
if (!has_cfg)
mhas_sap = 0;
if (mhas_sap) {
gf_filter_pck_set_sap(dst, GF_FILTER_SAP_1);
}
gf_filter_pck_set_dts(dst, ctx->cts);
gf_filter_pck_set_cts(dst, ctx->cts);
gf_filter_pck_set_duration(dst, (u32) pck_dur);
if (ctx->byte_offset != GF_FILTER_NO_BO) {
u64 offset = (u64) (start - ctx->mhas_buffer);
offset += ctx->byte_offset + au_start;
gf_filter_pck_set_byte_offset(dst, offset);
}
GF_LOG(GF_LOG_DEBUG, GF_LOG_MEDIA, ("[MHASDmx] Send AU CTS "LLU" size %d dur %d sap %d\n", ctx->cts, au_size, (u32) pck_dur, mhas_sap));
gf_filter_pck_send(dst);
au_start += au_size;
consumed = au_start;
ctx->nb_frames ++;
mhas_dmx_update_cts(ctx);
has_cfg = 0;
if (prev_pck_size) {
u64 next_pos = (u64) (start + au_start - ctx->mhas_buffer);
if (prev_pck_size <= next_pos) {
prev_pck_size = 0;
if (ctx->src_pck) gf_filter_pck_unref(ctx->src_pck);
ctx->src_pck = in_pck;
if (in_pck)
gf_filter_pck_ref_props(&ctx->src_pck);
if (ctx->timescale && (cts != GF_FILTER_NO_TS) ) {
ctx->cts = cts;
cts = GF_FILTER_NO_TS;
}
}
}
if (remain==consumed)
break;
if (gf_filter_pid_would_block(ctx->opid)) {
ctx->resume_from = 1;
final_flush = GF_FALSE;
break;
}
}
}
if (consumed) {
assert(remain>=consumed);
remain -= consumed;
start += consumed;
}
skip:
if (remain < ctx->mhas_buffer_size) {
memmove(ctx->mhas_buffer, start, remain);
if (ctx->byte_offset != GF_FILTER_NO_BO)
ctx->byte_offset += ctx->mhas_buffer_size - remain;
}
ctx->mhas_buffer_size = remain;
if (final_flush)
ctx->mhas_buffer_size = 0;
if (!ctx->mhas_buffer_size) {
if (ctx->src_pck) gf_filter_pck_unref(ctx->src_pck);
ctx->src_pck = NULL;
}
if (in_pck)
gf_filter_pid_drop_packet(ctx->ipid);
return GF_OK;
}

flb_sds_t flb_pack_msgpack_to_json_format(const char *data, uint64_t bytes,
int json_format, int date_format,
flb_sds_t date_key)
{
int i;
int len;
int ok = MSGPACK_UNPACK_SUCCESS;
int records = 0;
int map_size;
size_t off = 0;
char time_formatted[32];
size_t s;
flb_sds_t out_tmp;
flb_sds_t out_js;
flb_sds_t out_buf = NULL;
msgpack_unpacked result;
msgpack_object root;
msgpack_object map;
msgpack_sbuffer tmp_sbuf;
msgpack_packer tmp_pck;
msgpack_object *obj;
msgpack_object *k;
msgpack_object *v;
struct tm tm;
struct flb_time tms;
records = flb_mp_count(data, bytes);
if (records <= 0) {
return NULL;
}
if (json_format == FLB_PACK_JSON_FORMAT_LINES ||
json_format == FLB_PACK_JSON_FORMAT_STREAM) {
out_buf = flb_sds_create_size(bytes + bytes / 4);
if (!out_buf) {
flb_errno();
return NULL;
}
}
msgpack_sbuffer_init(&tmp_sbuf);
msgpack_packer_init(&tmp_pck, &tmp_sbuf, msgpack_sbuffer_write);
if (json_format == FLB_PACK_JSON_FORMAT_JSON) {
msgpack_pack_array(&tmp_pck, records);
}
msgpack_unpacked_init(&result);
while (msgpack_unpack_next(&result, data, bytes, &off) == ok) {
root = result.data;
if (root.via.array.size != 2) {
continue;
}
flb_time_pop_from_msgpack(&tms, &result, &obj);
map = root.via.array.ptr[1];
map_size = map.via.map.size;
if (date_key != NULL) {
msgpack_pack_map(&tmp_pck, map_size + 1);
}
else {
msgpack_pack_map(&tmp_pck, map_size);
}
if (date_key != NULL) {
msgpack_pack_str(&tmp_pck, flb_sds_len(date_key));
msgpack_pack_str_body(&tmp_pck, date_key, flb_sds_len(date_key));
switch (date_format) {
case FLB_PACK_JSON_DATE_DOUBLE:
msgpack_pack_double(&tmp_pck, flb_time_to_double(&tms));
break;
case FLB_PACK_JSON_DATE_ISO8601:
gmtime_r(&tms.tm.tv_sec, &tm);
s = strftime(time_formatted, sizeof(time_formatted) - 1,
FLB_PACK_JSON_DATE_ISO8601_FMT, &tm);
len = snprintf(time_formatted + s,
sizeof(time_formatted) - 1 - s,
".%06" PRIu64 "Z",
(uint64_t) tms.tm.tv_nsec / 1000);
s += len;
msgpack_pack_str(&tmp_pck, s);
msgpack_pack_str_body(&tmp_pck, time_formatted, s);
break;
case FLB_PACK_JSON_DATE_EPOCH:
msgpack_pack_uint64(&tmp_pck, (long long unsigned)(tms.tm.tv_sec));
break;
}
}
for (i = 0; i < map_size; i++) {
k = &map.via.map.ptr[i].key;
v = &map.via.map.ptr[i].val;
msgpack_pack_object(&tmp_pck, *k);
msgpack_pack_object(&tmp_pck, *v);
}
if (json_format == FLB_PACK_JSON_FORMAT_JSON) {
continue;
}
if (json_format == FLB_PACK_JSON_FORMAT_LINES ||
json_format == FLB_PACK_JSON_FORMAT_STREAM) {
out_js = flb_msgpack_raw_to_json_sds(tmp_sbuf.data, tmp_sbuf.size);
if (!out_js) {
msgpack_sbuffer_destroy(&tmp_sbuf);
flb_sds_destroy(out_buf);
return NULL;
}
out_tmp = flb_sds_cat(out_buf, out_js, flb_sds_len(out_js));
if (!out_tmp) {
msgpack_sbuffer_destroy(&tmp_sbuf);
flb_sds_destroy(out_js);
flb_sds_destroy(out_buf);
return NULL;
}
flb_sds_destroy(out_js);
if (out_tmp != out_buf) {
out_buf = out_tmp;
}
if (json_format == FLB_PACK_JSON_FORMAT_LINES) {
out_tmp = flb_sds_cat(out_buf, "\n", 1);
if (!out_tmp) {
msgpack_sbuffer_destroy(&tmp_sbuf);
flb_sds_destroy(out_buf);
return NULL;
}
if (out_tmp != out_buf) {
out_buf = out_tmp;
}
}
msgpack_sbuffer_clear(&tmp_sbuf);
}
}
msgpack_unpacked_destroy(&result);
if (json_format == FLB_PACK_JSON_FORMAT_JSON) {
out_buf = flb_msgpack_raw_to_json_sds(tmp_sbuf.data, tmp_sbuf.size);
msgpack_sbuffer_destroy(&tmp_sbuf);
if (!out_buf) {
return NULL;
}
}
else {
msgpack_sbuffer_destroy(&tmp_sbuf);
}
if (out_buf && flb_sds_len(out_buf) == 0) {
flb_sds_destroy(out_buf);
return NULL;
}
return out_buf;
}

