}
process_info->isIPv6 = ((pletoh32(&tmp32) == 0) ? FALSE : TRUE);
if (process_info->isIPv6) {
if (!wtap_read_bytes(wth->fh, &process_info->localAddr.ipv6, 16, err, err_info)) {
