static MagickBooleanType load_tile(Image *image,Image *tile_image,
XCFDocInfo *inDocInfo,XCFLayerInfo *inLayerInfo,size_t data_length,
ExceptionInfo *exception)
{
ssize_t
y;
register ssize_t
x;
register Quantum
*q;
ssize_t
count;
unsigned char
*graydata;
XCFPixelInfo
*xcfdata,
*xcfodata;
xcfdata=(XCFPixelInfo *) AcquireQuantumMemory(data_length,sizeof(*xcfdata));
if (xcfdata == (XCFPixelInfo *) NULL)
ThrowBinaryException(ResourceLimitError,"MemoryAllocationFailed",
image->filename);
xcfodata=xcfdata;
graydata=(unsigned char *) xcfdata;  
count=ReadBlob(image,data_length,(unsigned char *) xcfdata);
if (count != (ssize_t) data_length)
ThrowBinaryException(CorruptImageError,"NotEnoughPixelData",
image->filename);
for (y=0; y < (ssize_t) tile_image->rows; y++)
{
q=GetAuthenticPixels(tile_image,0,y,tile_image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
if (inDocInfo->image_type == GIMP_GRAY)
{
for (x=0; x < (ssize_t) tile_image->columns; x++)
{
SetPixelGray(tile_image,ScaleCharToQuantum(*graydata),q);
SetPixelAlpha(tile_image,ScaleCharToQuantum((unsigned char)
inLayerInfo->alpha),q);
graydata++;
q+=GetPixelChannels(tile_image);
}
}
else
if (inDocInfo->image_type == GIMP_RGB)
{
for (x=0; x < (ssize_t) tile_image->columns; x++)
{
SetPixelRed(tile_image,ScaleCharToQuantum(xcfdata->red),q);
SetPixelGreen(tile_image,ScaleCharToQuantum(xcfdata->green),q);
SetPixelBlue(tile_image,ScaleCharToQuantum(xcfdata->blue),q);
SetPixelAlpha(tile_image,xcfdata->alpha == 255U ? TransparentAlpha :
ScaleCharToQuantum((unsigned char) inLayerInfo->alpha),q);
xcfdata++;
q+=GetPixelChannels(tile_image);
}
}
if (SyncAuthenticPixels(tile_image,exception) == MagickFalse)
break;
}
xcfodata=(XCFPixelInfo *) RelinquishMagickMemory(xcfodata);
return MagickTrue;
}

static int
lp8000_print_page(gx_device_printer *pdev, gp_file *prn_stream)
{
int line_size = gdev_mem_bytes_per_scan_line((gx_device *)pdev);
int in_size = line_size;
unsigned int report_size;
byte *buf1 = (byte *)gs_malloc(pdev->memory, in_size, 1, "lp8000_print_page(buf1)");
byte *buf2 = (byte *)gs_malloc(pdev->memory, in_size, 1, "lp8000_print_page(buf2)");
byte *in = buf1;
byte *out = buf2;
int lnum, top, bottom, left, width;
int count, left1, left2, left0;
if ( buf1 == 0 || buf2 == 0 )
{       if ( buf1 )
gs_free(pdev->memory, (char *)buf1, in_size, 1, "lp8000_print_page(buf1)");
if ( buf2 )
gs_free(pdev->memory, (char *)buf2, in_size, 1, "lp8000_print_page(buf2)");
return_error(gs_error_VMerror);
}
gp_fwrite("\033\001@EJL \n",1,8,prn_stream);
gp_fwrite("@EJL EN LA=ESC/PAGE\n",1,20,prn_stream);
gp_fwrite("\035rhE\033\001@EJL \n",1,12,prn_stream);
gp_fwrite("@EJL SE LA=ESC/PAGE\n",1,20,prn_stream);
gp_fwrite("@EJL SET PU=1 PS=A4 ZO=OFF\n",1,27,prn_stream);
gp_fwrite("@EJL EN LA=ESC/PAGE\n",1,20,prn_stream);
gp_fwrite("\0350;0.24muE\0352;300;300drE",1,23,prn_stream);
gp_fwrite("\0350;300;300drE\0351tsE\0351mmE",1,23,prn_stream);
gp_fwrite("\0357isE\0355iaF\0355ipP\03514psE\0350poE",1,26,prn_stream);
gp_fwrite("\03560;60loE\0350X\0350Y",1,15,prn_stream);
gp_fwrite("\0350;0;2360;3388caE",1,17,prn_stream);
gp_fwrite("\0351cmE\0350alfP",1,11,prn_stream);
gp_fwrite("\0350affP\0350boP\0350abP",1,16,prn_stream);
gp_fwrite("\0354ilG\0350bcI\0350sarG",1,16,prn_stream);
gp_fwrite("\0351;0;100spE\0352owE",1,16,prn_stream);
left1  =  (int) (L_MARGIN * pdev->x_pixels_per_inch) - 60;
left1 = (left1 >> 3) << 3;
left0 = left1;
gp_fwrite("\035",1,1,prn_stream);
gp_fprintf(prn_stream,"%d",left1);
gp_fwrite("X",1,1,prn_stream);
gp_fwrite("\0353bcI",1,5,prn_stream);
top = T_MARGIN * pdev->y_pixels_per_inch;
bottom = pdev->height - B_MARGIN * pdev->y_pixels_per_inch;
left  = ( (int) (L_MARGIN * pdev->x_pixels_per_inch) ) >> 3 ;
width = ((pdev->width - (int)(R_MARGIN * pdev->x_pixels_per_inch)) >> 3) - left;
for ( lnum = top; lnum < bottom ; )
{
byte *in_data;
byte *inp;
byte *in_end;
byte *outp;
register byte *p, *q;
gdev_prn_get_bits(pdev, lnum, in, &in_data);
while ( in_data[0] == 0 &&
!memcmp((char *)in_data, (char *)in_data + 1, line_size - 1) &&
lnum < bottom )
{
lnum++;
gdev_prn_get_bits(pdev, lnum, in, &in_data);
}
if(lnum == bottom ) break;
(void)gdev_prn_copy_scan_lines(pdev, lnum, in, in_size);
inp = in  + left;
in_end = inp + width;
while (in_end > inp &&  in_end[-1] == 0)
{
in_end--;
}
for(left2 = 0; inp < in_end && inp[0] == 0; inp++,left2++);
left2 = left1 + (left2 << 3);
outp = out;
for( p = inp, q = inp + 1 ; q < in_end ; )
{
if( *p != *q++ )
{
*outp++ = *p++;
}
else
{
for (count = 2; ( *p == *q ) && (q < in_end); q++, count++)
{}
while (count > 257)
{
*outp++ = *p;
*outp++ = *p;
*outp++ = 255;
p += 257;
count -=257;
}
*outp++ = *p;
*outp++ = *p;
*outp++ = count - 2;
p += count;
q = p+1;
}
}
if (p == (in_end - 1)) *outp++ = *p;
if (left2 != left0)
{
left0 = left2;
gp_fwrite("\035",1,1,prn_stream);
gp_fprintf(prn_stream,"%d",left2);
gp_fwrite("X",1,1,prn_stream);
}
gp_fwrite("\035",1,1,prn_stream);
gp_fprintf(prn_stream,"%d",lnum-60);
gp_fwrite("Y\035",1,2,prn_stream);
report_size = outp - out;
gp_fprintf(prn_stream,"%d;",report_size);
report_size = (in_end - inp) << 3;
gp_fprintf(prn_stream,"%d;",report_size);
gp_fwrite("1;0bi{I",1,7,prn_stream);
gp_fwrite(out,1,(outp - out),prn_stream);
lnum++;
}
gp_fwrite("\0350bcI",1,5,prn_stream);
gp_fwrite("\0351coO",1,5,prn_stream);
gp_fwrite("\035rhE",1,4,prn_stream);
gp_fwrite("\033\001@EJL \n",1,8,prn_stream);
gp_fwrite("@EJL SE LA=ESC/PAGE\n",1,20,prn_stream);
gp_fwrite("@EJL SET PU=1 PS=A4 ZO=OFF\n",1,27,prn_stream);
gp_fwrite("@EJL EN LA=ESC/PAGE\n",1,20,prn_stream);
gp_fwrite("\0350;0.24muE\0352;300;300drE",1,23,prn_stream);
gp_fwrite("\0350;300;300drE\0351tsE\0351mmE",1,23,prn_stream);
gp_fwrite("\0357isE\0355iaF\0355ipP\03514psE\0350poE",1,26,prn_stream);
gp_fwrite("\03560;60loE\0350X\0350Y",1,15,prn_stream);
gp_fwrite("\0350;0;2360;3388caE",1,17,prn_stream);
gp_fwrite("\0351cmE\0350alfP",1,11,prn_stream);
gp_fwrite("\0350affP\0350boP\0350abP",1,16,prn_stream);
gp_fwrite("\0354ilG\0350bcI\0350sarG",1,16,prn_stream);
gp_fwrite("\035rhE",1,4,prn_stream);
gp_fwrite("\033\001@EJL \n",1,8,prn_stream);
gp_fwrite("\033\001@EJL \n",1,8,prn_stream);
gp_fflush(prn_stream);
gs_free(pdev->memory, (char *)buf2, in_size, 1, "lp8000_print_page(buf2)");
gs_free(pdev->memory, (char *)buf1, in_size, 1, "lp8000_print_page(buf1)");
return 0;
}

void
init_rc(void)
{
int i;
struct stat st;
FILE *f;
if (rc_dir != NULL)
goto open_rc;
rc_dir = expandPath(RC_DIR);
i = strlen(rc_dir);
if (i > 1 && rc_dir[i - 1] == '/')
rc_dir[i - 1] = '\0';
#ifdef USE_M17N
display_charset_str = wc_get_ces_list();
document_charset_str = display_charset_str;
system_charset_str = display_charset_str;
#endif
if (stat(rc_dir, &st) < 0) {
if (errno == ENOENT) {
if (do_mkdir(rc_dir, 0700) < 0) {
goto rc_dir_err;
}
else {
stat(rc_dir, &st);
}
}
else {
goto rc_dir_err;
}
}
if (!S_ISDIR(st.st_mode)) {
goto rc_dir_err;
}
if (!(st.st_mode & S_IWUSR)) {
goto rc_dir_err;
}
no_rc_dir = FALSE;
tmp_dir = rc_dir;
if (config_file == NULL)
config_file = rcFile(CONFIG_FILE);
create_option_search_table();
open_rc:
if ((f = fopen(etcFile(W3MCONFIG), "rt")) != NULL) {
interpret_rc(f);
fclose(f);
}
if ((f = fopen(confFile(CONFIG_FILE), "rt")) != NULL) {
interpret_rc(f);
fclose(f);
}
if (config_file && (f = fopen(config_file, "rt")) != NULL) {
interpret_rc(f);
fclose(f);
}
return;
rc_dir_err:
no_rc_dir = TRUE;
if (((tmp_dir = getenv("TMPDIR")) == NULL || *tmp_dir == '\0') &&
((tmp_dir = getenv("TMP")) == NULL || *tmp_dir == '\0') &&
((tmp_dir = getenv("TEMP")) == NULL || *tmp_dir == '\0'))
tmp_dir = "/tmp";
create_option_search_table();
goto open_rc;
}

