MagickExport MemoryInfo *AcquireVirtualMemory(const size_t count,
const size_t quantum)
{
MemoryInfo
*memory_info;
size_t
extent;
if (CheckMemoryOverflow(count,quantum) != MagickFalse)
return((MemoryInfo *) NULL);
memory_info=(MemoryInfo *) MagickAssumeAligned(AcquireAlignedMemory(1,
sizeof(*memory_info)));
if (memory_info == (MemoryInfo *) NULL)
ThrowFatalException(ResourceLimitFatalError,"MemoryAllocationFailed");
(void) ResetMagickMemory(memory_info,0,sizeof(*memory_info));
extent=count*quantum;
memory_info->length=extent;
memory_info->signature=MagickSignature;
if (AcquireMagickResource(MemoryResource,extent) != MagickFalse)
{
memory_info->blob=AcquireAlignedMemory(1,extent);
if (memory_info->blob != NULL)
{
memory_info->type=AlignedVirtualMemory;
return(memory_info);
}
}
RelinquishMagickResource(MemoryResource,extent);
if (AcquireMagickResource(MapResource,extent) != MagickFalse)
{
memory_info->blob=MapBlob(-1,IOMode,0,extent);
if (memory_info->blob != NULL)
{
memory_info->type=MapVirtualMemory;
return(memory_info);
}
if (AcquireMagickResource(DiskResource,extent) != MagickFalse)
{
int
file;
file=AcquireUniqueFileResource(memory_info->filename);
if (file != -1)
{
MagickOffsetType
offset;
offset=(MagickOffsetType) lseek(file,extent-1,SEEK_SET);
if ((offset == (MagickOffsetType) (extent-1)) &&
(write(file,"",1) == 1))
{
memory_info->blob=MapBlob(file,IOMode,0,extent);
if (memory_info->blob != NULL)
{
(void) close(file);
memory_info->type=MapVirtualMemory;
return(memory_info);
}
}
(void) close(file);
(void) RelinquishUniqueFileResource(memory_info->filename);
*memory_info->filename='\0';
}
}
RelinquishMagickResource(DiskResource,extent);
}
RelinquishMagickResource(MapResource,extent);
if (memory_info->blob == NULL)
{
memory_info->blob=AcquireMagickMemory(extent);
if (memory_info->blob != NULL)
memory_info->type=UnalignedVirtualMemory;
}
if (memory_info->blob == NULL)
memory_info=RelinquishVirtualMemory(memory_info);
return(memory_info);
}

static zval **spl_array_get_dimension_ptr_ptr(int check_inherited, zval *object, zval *offset, int type TSRMLS_DC) 
{
spl_array_object *intern = (spl_array_object*)zend_object_store_get_object(object TSRMLS_CC);
zval **retval;
char *key;
uint len;
long index;
HashTable *ht = spl_array_get_hash_table(intern, 0 TSRMLS_CC);
if (!offset) {
return &EG(uninitialized_zval_ptr);
}
if ((type == BP_VAR_W || type == BP_VAR_RW) && (ht->nApplyCount > 0)) {
zend_error(E_WARNING, "Modification of ArrayObject during sorting is prohibited");
return &EG(error_zval_ptr);;
}
switch (Z_TYPE_P(offset)) {
case IS_STRING:
key = Z_STRVAL_P(offset);
len = Z_STRLEN_P(offset) + 1;
string_offest:
if (zend_symtable_find(ht, key, len, (void **) &retval) == FAILURE) {
switch (type) {
case BP_VAR_R:
zend_error(E_NOTICE, "Undefined index: %s", key);
case BP_VAR_UNSET:
case BP_VAR_IS:
retval = &EG(uninitialized_zval_ptr);
break;
case BP_VAR_RW:
zend_error(E_NOTICE,"Undefined index: %s", key);
case BP_VAR_W: {
zval *value;
ALLOC_INIT_ZVAL(value);
zend_symtable_update(ht, key, len, (void**)&value, sizeof(void*), (void **)&retval);
}
}
}
return retval;
case IS_NULL:
key = "";
len = 1;
goto string_offest;
case IS_RESOURCE:
zend_error(E_STRICT, "Resource ID#%ld used as offset, casting to integer (%ld)", Z_LVAL_P(offset), Z_LVAL_P(offset));
case IS_DOUBLE:
case IS_BOOL:
case IS_LONG:
if (offset->type == IS_DOUBLE) {
index = (long)Z_DVAL_P(offset);
} else {
index = Z_LVAL_P(offset);
}
if (zend_hash_index_find(ht, index, (void **) &retval) == FAILURE) {
switch (type) {
case BP_VAR_R:
zend_error(E_NOTICE, "Undefined offset: %ld", index);
case BP_VAR_UNSET:
case BP_VAR_IS:
retval = &EG(uninitialized_zval_ptr);
break;
case BP_VAR_RW:
zend_error(E_NOTICE, "Undefined offset: %ld", index);
case BP_VAR_W: {
zval *value;
ALLOC_INIT_ZVAL(value);
zend_hash_index_update(ht, index, (void**)&value, sizeof(void*), (void **)&retval);
}
}
}
return retval;
default:
zend_error(E_WARNING, "Illegal offset type");
return (type == BP_VAR_W || type == BP_VAR_RW) ?
&EG(error_zval_ptr) : &EG(uninitialized_zval_ptr);
}
}

static rfbBool
HandleUltraZipBPP (rfbClient* client, int rx, int ry, int rw, int rh)
{
rfbZlibHeader hdr;
int i=0;
int toRead=0;
int inflateResult=0;
unsigned char *ptr=NULL;
lzo_uint uncompressedBytes = ry + (rw * 65535);
unsigned int numCacheRects = rx;
if (!ReadFromRFBServer(client, (char *)&hdr, sz_rfbZlibHeader))
return FALSE;
toRead = rfbClientSwap32IfLE(hdr.nBytes);
if (toRead==0) return TRUE;
if (uncompressedBytes==0)
{
rfbClientLog("ultrazip error: rectangle has 0 uncomressed bytes (%dy + (%dw * 65535)) (%d rectangles)\n", ry, rw, rx); 
return FALSE;
}
if ( client->raw_buffer_size < (int)(uncompressedBytes + 500)) {
if ( client->raw_buffer != NULL ) {
free( client->raw_buffer );
}
client->raw_buffer_size = uncompressedBytes + 500;
if ((client->raw_buffer_size % 4)!=0)
client->raw_buffer_size += (4-(client->raw_buffer_size % 4));
client->raw_buffer = (char*) malloc( client->raw_buffer_size );
}
if ( client->ultra_buffer_size < toRead ) {
if ( client->ultra_buffer != NULL ) {
free( client->ultra_buffer );
}
client->ultra_buffer_size = toRead;
client->ultra_buffer = (char*) malloc( client->ultra_buffer_size );
}
if (!ReadFromRFBServer(client, client->ultra_buffer, toRead))
return FALSE;
uncompressedBytes = client->raw_buffer_size;
inflateResult = lzo1x_decompress(
(lzo_byte *)client->ultra_buffer, toRead,
(lzo_byte *)client->raw_buffer, &uncompressedBytes, NULL);
if ( inflateResult != LZO_E_OK ) 
{
rfbClientLog("ultra decompress returned error: %d\n",
inflateResult);
return FALSE;
}
ptr = (unsigned char *)client->raw_buffer;
for (i=0; i<numCacheRects; i++)
{
unsigned short sx, sy, sw, sh;
unsigned int se;
memcpy((char *)&sx, ptr, 2); ptr += 2;
memcpy((char *)&sy, ptr, 2); ptr += 2;
memcpy((char *)&sw, ptr, 2); ptr += 2;
memcpy((char *)&sh, ptr, 2); ptr += 2;
memcpy((char *)&se, ptr, 4); ptr += 4;
sx = rfbClientSwap16IfLE(sx);
sy = rfbClientSwap16IfLE(sy);
sw = rfbClientSwap16IfLE(sw);
sh = rfbClientSwap16IfLE(sh);
se = rfbClientSwap32IfLE(se);
if (se == rfbEncodingRaw)
{
CopyRectangle(client, (unsigned char *)ptr, sx, sy, sw, sh);
ptr += ((sw * sh) * (BPP / 8));
}
}  
return TRUE;
}

flb_sds_t flb_msgpack_to_gelf(flb_sds_t *s, msgpack_object *o,
struct flb_time *tm,
struct flb_gelf_fields *fields)
{
int i;
int loop;
flb_sds_t tmp;
int host_key_found = FLB_FALSE;
int timestamp_key_found = FLB_FALSE;
int level_key_found = FLB_FALSE;
int short_message_key_found = FLB_FALSE;
int full_message_key_found = FLB_FALSE;
char *host_key = NULL;
char *timestamp_key = NULL;
char *level_key = NULL;
char *short_message_key = NULL;
char *full_message_key = NULL;
int host_key_len = 0;
int timestamp_key_len = false;
int level_key_len = 0;
int short_message_key_len = 0;
int full_message_key_len = 0;
if (s == NULL || o == NULL) {
return NULL;
}
if (o->type != MSGPACK_OBJECT_MAP) {
return NULL;
}
if (fields != NULL && fields->host_key != NULL) {
host_key = fields->host_key;
host_key_len = flb_sds_len(fields->host_key);
}
else {
host_key = "host";
host_key_len = 4;
}
if (fields != NULL && fields->timestamp_key != NULL) {
timestamp_key = fields->timestamp_key;
timestamp_key_len = flb_sds_len(fields->timestamp_key);
}
else {
timestamp_key = "timestamp";
timestamp_key_len = 9;
}
if (fields != NULL && fields->level_key != NULL) {
level_key = fields->level_key;
level_key_len = flb_sds_len(fields->level_key);
}
else {
level_key = "level";
level_key_len = 5;
}
if (fields != NULL && fields->short_message_key != NULL) {
short_message_key = fields->short_message_key;
short_message_key_len = flb_sds_len(fields->short_message_key);
}
else {
short_message_key = "short_message";
short_message_key_len = 13;
}
if (fields != NULL && fields->full_message_key != NULL) {
full_message_key = fields->full_message_key;
full_message_key_len = flb_sds_len(fields->full_message_key);
}
else {
full_message_key = "full_message";
full_message_key_len = 12;
}
tmp = flb_sds_cat(*s, "{\"version\":\"1.1\"", 16);
if (tmp == NULL) {
return NULL;
}
*s = tmp;
loop = o->via.map.size;
if (loop != 0) {
msgpack_object_kv *p = o->via.map.ptr;
for (i = 0; i < loop; i++) {
const char *key = NULL;
int key_len;
const char *val = NULL;
int val_len = 0;
int quote = FLB_FALSE;
int custom_key = FLB_FALSE;
msgpack_object *k = &p[i].key;
msgpack_object *v = &p[i].val;
msgpack_object vtmp; 
if (k->type != MSGPACK_OBJECT_BIN && k->type != MSGPACK_OBJECT_STR) {
continue;
}
if (k->type == MSGPACK_OBJECT_STR) {
key = k->via.str.ptr;
key_len = k->via.str.size;
}
else {
key = k->via.bin.ptr;
key_len = k->via.bin.size;
}
if ((key_len == host_key_len) &&
!strncmp(key, host_key, host_key_len)) {
if (host_key_found == FLB_TRUE) {
continue;
}
host_key_found = FLB_TRUE;
key = "host";
key_len = 4;
}
else if ((key_len == short_message_key_len) &&
!strncmp(key, short_message_key, short_message_key_len)) {
if (short_message_key_found == FLB_TRUE) {
continue;
}
short_message_key_found = FLB_TRUE;
key = "short_message";
key_len = 13;
}
else if ((key_len == timestamp_key_len) &&
!strncmp(key, timestamp_key, timestamp_key_len)) {
if (timestamp_key_found == FLB_TRUE) {
continue;
}
timestamp_key_found = FLB_TRUE;
key = "timestamp";
key_len = 9;
}
else if ((key_len == level_key_len) &&
!strncmp(key, level_key, level_key_len )) {
if (level_key_found == FLB_TRUE) {
continue;
}
level_key_found = FLB_TRUE;
key = "level";
key_len = 5;
if (v->type == MSGPACK_OBJECT_POSITIVE_INTEGER) {
if ( v->via.u64 > 7 ) {
flb_warn("[flb_msgpack_to_gelf] level is %" PRIu64 ", "
"but should be in 0..7 or a syslog keyword", v->via.u64);
}
}
else if (v->type == MSGPACK_OBJECT_STR) {
val     = v->via.str.ptr;
val_len = v->via.str.size;
if (val_len == 1 && val[0] >= '0' && val[0] <= '7') {
v = &vtmp;
v->type = MSGPACK_OBJECT_POSITIVE_INTEGER;
v->via.u64 = (uint64_t)(val[0] - '0');
}
else {
int n;
char* allowed_levels[] = {
"emerg", "alert", "crit", "err",
"warning", "notice", "info", "debug",
NULL
};
for (n = 0; allowed_levels[n] != NULL; ++n) {
if (val_len == strlen(allowed_levels[n]) &&
!strncasecmp(val, allowed_levels[n], val_len)) {
v = &vtmp;
v->type = MSGPACK_OBJECT_POSITIVE_INTEGER;
v->via.u64 = (uint64_t)n;
break;
}
}
if (allowed_levels[n] == NULL) {
flb_warn("[flb_msgpack_to_gelf] level is '%.*s', "
"but should be in 0..7 or a syslog keyword", val_len, val);
}
}
}
else {
flb_error("[flb_msgpack_to_gelf] level must be a non-negative integer or a string");
return NULL;
}
}
else if ((key_len == full_message_key_len) &&
!strncmp(key, full_message_key, full_message_key_len)) {
if (full_message_key_found == FLB_TRUE) {
continue;
}
full_message_key_found = FLB_TRUE;
key = "full_message";
key_len = 12;
}
else if ((key_len == 2)  && !strncmp(key, "id", 2)) {
continue;
}
else {
custom_key = FLB_TRUE;
}
if (v->type == MSGPACK_OBJECT_MAP) {
char *prefix = NULL;
int prefix_len = 0;
prefix_len = key_len + 1;
prefix = flb_calloc(1, prefix_len + 1);
if (prefix == NULL) {
return NULL;
}
prefix[0] = '_';
strncpy(prefix + 1, key, key_len);
prefix[prefix_len] = '\0';
tmp = flb_msgpack_gelf_flatten(s, v,
prefix, prefix_len, FLB_FALSE);
if (tmp == NULL) {
flb_free(prefix);
return NULL;
}
*s = tmp;
flb_free(prefix);
}
else if (v->type == MSGPACK_OBJECT_ARRAY) {
if (custom_key == FLB_TRUE) {
tmp = flb_msgpack_gelf_key(s, FLB_FALSE, "_", 1, FLB_FALSE,
key, key_len);
}
else {
tmp = flb_msgpack_gelf_key(s, FLB_FALSE, NULL, 0, FLB_FALSE,
key, key_len);
}
if (tmp == NULL) {
return NULL;
}
*s = tmp;
tmp = flb_msgpack_gelf_flatten(s, v, NULL, 0, FLB_FALSE);
if (tmp == NULL) {
return NULL;
}
*s = tmp;
}
else {
char temp[48] = {0};
if (v->type == MSGPACK_OBJECT_NIL) {
val = "null";
val_len = 4;
continue;
}
else if (v->type == MSGPACK_OBJECT_BOOLEAN) {
quote   = FLB_TRUE;
val = v->via.boolean ? "true" : "false";
val_len = v->via.boolean ? 4 : 5;
}
else if (v->type == MSGPACK_OBJECT_POSITIVE_INTEGER) {
val = temp;
val_len = snprintf(temp, sizeof(temp) - 1,
"%" PRIu64, v->via.u64);
if (val_len > sizeof(temp)) {
return NULL;
}
}
else if (v->type == MSGPACK_OBJECT_NEGATIVE_INTEGER) {
val = temp;
val_len = snprintf(temp, sizeof(temp) - 1,
"%" PRId64, v->via.i64);
if (val_len > sizeof(temp)) {
return NULL;
}
}
else if (v->type == MSGPACK_OBJECT_FLOAT) {
val = temp;
val_len = snprintf(temp, sizeof(temp) - 1,
"%f", v->via.f64);
if (val_len > sizeof(temp)) {
return NULL;
}
}
else if (v->type == MSGPACK_OBJECT_STR) {
quote   = FLB_TRUE;
val     = v->via.str.ptr;
val_len = v->via.str.size;
}
else if (v->type == MSGPACK_OBJECT_BIN) {
quote   = FLB_TRUE;
val     = v->via.bin.ptr;
val_len = v->via.bin.size;
}
else if (v->type == MSGPACK_OBJECT_EXT) {
quote   = FLB_TRUE;
val     = o->via.ext.ptr;
val_len = o->via.ext.size;
}
if (!val || !key) {
continue;
}
if (custom_key == FLB_TRUE) {
tmp = flb_msgpack_gelf_key(s, FLB_FALSE, "_", 1, FLB_FALSE,
key, key_len);
}
else {
tmp = flb_msgpack_gelf_key(s, FLB_FALSE, NULL, 0, FLB_FALSE,
key, key_len);
}
if (tmp == NULL) {
return NULL;
}
*s = tmp;
if (v->type == MSGPACK_OBJECT_EXT) {
tmp = flb_msgpack_gelf_value_ext(s, quote, val, val_len);
}
else {
tmp = flb_msgpack_gelf_value(s, quote, val, val_len);
}
if (tmp == NULL) {
return NULL;
}
*s = tmp;
}
}
}
if (timestamp_key_found == FLB_FALSE && tm != NULL) {
tmp = flb_msgpack_gelf_key(s, FLB_FALSE, NULL, 0, FLB_FALSE,
"timestamp", 9);
if (tmp == NULL) {
return NULL;
}
*s = tmp;
tmp = flb_sds_printf(s, "%" PRIu32".%lu",
tm->tm.tv_sec, tm->tm.tv_nsec / 1000000);
if (tmp == NULL) {
return NULL;
}
*s = tmp;
}
if (short_message_key_found == FLB_FALSE) {
flb_error("[flb_msgpack_to_gelf] missing short_message key");
return NULL;
}
tmp = flb_sds_cat(*s, "}", 1);
if (tmp == NULL) {
return NULL;
}
*s = tmp;
return *s;
}

int button_open(Button *b) {
char *p, name[256];
int r;
assert(b);
b->fd = safe_close(b->fd);
p = strjoina("/dev/input/", b->name);
b->fd = open(p, O_RDWR|O_CLOEXEC|O_NOCTTY|O_NONBLOCK);
if (b->fd < 0)
return log_warning_errno(errno, "Failed to open %s: %m", p);
r = button_suitable(b);
if (r < 0)
return log_warning_errno(r, "Failed to determine whether input device is relevant to us: %m");
if (r == 0)
return log_debug_errno(SYNTHETIC_ERRNO(EADDRNOTAVAIL),
"Device %s does not expose keys or switches relevant to us, ignoring.",
p);
if (ioctl(b->fd, EVIOCGNAME(sizeof(name)), name) < 0) {
r = log_error_errno(errno, "Failed to get input name: %m");
goto fail;
}
(void) button_set_mask(b);
r = sd_event_add_io(b->manager->event, &b->io_event_source, b->fd, EPOLLIN, button_dispatch, b);
if (r < 0) {
log_error_errno(r, "Failed to add button event: %m");
goto fail;
}
log_info("Watching system buttons on /dev/input/%s (%s)", b->name, name);
return 0;
fail:
b->fd = safe_close(b->fd);
return r;
}

static ecma_value_t
ecma_op_function_call_simple (ecma_object_t *func_obj_p, 
ecma_value_t this_binding, 
const ecma_value_t *arguments_list_p, 
uint32_t arguments_list_len) 
{
JERRY_ASSERT (ecma_get_object_type (func_obj_p) == ECMA_OBJECT_TYPE_FUNCTION);
vm_frame_ctx_shared_args_t shared_args;
shared_args.header.status_flags = VM_FRAME_CTX_SHARED_HAS_ARG_LIST;
shared_args.header.function_object_p = func_obj_p;
shared_args.arg_list_p = arguments_list_p;
shared_args.arg_list_len = arguments_list_len;
ecma_extended_object_t *ext_func_p = (ecma_extended_object_t *) func_obj_p;
ecma_object_t *scope_p = ECMA_GET_NON_NULL_POINTER_FROM_POINTER_TAG (ecma_object_t, ext_func_p->u.function.scope_cp);
const ecma_compiled_code_t *bytecode_data_p = ecma_op_function_get_compiled_code (ext_func_p);
uint16_t status_flags = bytecode_data_p->status_flags;
shared_args.header.bytecode_header_p = bytecode_data_p;
#if JERRY_BUILTIN_REALMS
ecma_global_object_t *realm_p = ecma_op_function_get_realm (bytecode_data_p);
#endif 
if (!(status_flags & CBC_CODE_FLAGS_LEXICAL_ENV_NOT_NEEDED))
{
shared_args.header.status_flags |= VM_FRAME_CTX_SHARED_FREE_LOCAL_ENV;
scope_p = ecma_create_decl_lex_env (scope_p);
}
switch (CBC_FUNCTION_GET_TYPE (status_flags))
{
#if JERRY_ESNEXT
case CBC_FUNCTION_CONSTRUCTOR:
{
return ecma_op_function_call_constructor (&shared_args, scope_p, this_binding);
}
case CBC_FUNCTION_ARROW:
{
ecma_arrow_function_t *arrow_func_p = (ecma_arrow_function_t *) func_obj_p;
if (ecma_is_value_undefined (arrow_func_p->new_target))
{
JERRY_CONTEXT (current_new_target_p) = NULL;
}
else
{
JERRY_CONTEXT (current_new_target_p) = ecma_get_object_from_value (arrow_func_p->new_target);
}
this_binding = arrow_func_p->this_binding;
break;
}
#endif 
default:
{
#if JERRY_ESNEXT
shared_args.header.status_flags |= VM_FRAME_CTX_SHARED_NON_ARROW_FUNC;
#endif 
if (status_flags & CBC_CODE_FLAGS_STRICT_MODE)
{
break;
}
if (ecma_is_value_undefined (this_binding) || ecma_is_value_null (this_binding))
{
#if JERRY_BUILTIN_REALMS
this_binding = realm_p->this_binding;
#else 
this_binding = ecma_make_object_value (ecma_builtin_get_global ());
#endif 
}
else if (!ecma_is_value_object (this_binding))
{
this_binding = ecma_op_to_object (this_binding);
shared_args.header.status_flags |= VM_FRAME_CTX_SHARED_FREE_THIS;
JERRY_ASSERT (!ECMA_IS_VALUE_ERROR (this_binding));
}
break;
}
}
#if JERRY_BUILTIN_REALMS
ecma_global_object_t *saved_global_object_p = JERRY_CONTEXT (global_object_p);
JERRY_CONTEXT (global_object_p) = realm_p;
#endif 
ecma_value_t ret_value = vm_run (&shared_args.header, this_binding, scope_p);
#if JERRY_BUILTIN_REALMS
JERRY_CONTEXT (global_object_p) = saved_global_object_p;
#endif 
if (JERRY_UNLIKELY (shared_args.header.status_flags & VM_FRAME_CTX_SHARED_FREE_LOCAL_ENV))
{
ecma_deref_object (scope_p);
}
if (JERRY_UNLIKELY (shared_args.header.status_flags & VM_FRAME_CTX_SHARED_FREE_THIS))
{
ecma_free_value (this_binding);
}
return ret_value;
}

