int parse_mpls(const u_char *pktdata,
const uint32_t datalen,
uint16_t *next_protocol,
uint32_t *l2len,
uint32_t *l2offset)
{
struct tcpr_mpls_label *mpls_label;
int len_remaining = (int)datalen;
u_char first_nibble;
eth_hdr_t *eth_hdr;
bool bos = false;
uint32_t label;
int len;
assert(next_protocol);
assert(l2len);
assert(l2offset);
len = (int)*l2len;
while (!bos) {
if (len_remaining < (int)sizeof(*mpls_label))
return -1;
mpls_label = (struct tcpr_mpls_label*)(pktdata + len);
len += sizeof(*mpls_label);
len_remaining -= sizeof(*mpls_label);
bos = (ntohl(mpls_label->entry) & MPLS_LS_S_MASK) != 0;
label = ntohl(mpls_label->entry) >> MPLS_LS_LABEL_SHIFT;
if (label == MPLS_LABEL_GACH) {
warn("GACH MPLS label not supported at this time");
return -1;
}
}
if (len_remaining < 4)
return -1;
first_nibble = *((u_char *)(mpls_label + 1)) >> 4;
switch(first_nibble) {
case 4:
*next_protocol = ETHERTYPE_IP;
break;
case 6:
*next_protocol = ETHERTYPE_IP6;
break;
case 0:
len += 4;
len_remaining -= 4;
if (len_remaining < (int)sizeof(*eth_hdr))
return -1;
*l2offset = len;
eth_hdr = (eth_hdr_t*)(pktdata + len);
len += sizeof(*eth_hdr);
*next_protocol = ntohs(eth_hdr->ether_type);
break;
default:
return -1;
}
*l2len = (uint32_t)len;
return 0;
}

Status InferenceContext::Multiply(DimensionHandle first,
DimensionOrConstant second,
DimensionHandle* out) {
const int64_t first_value = Value(first);
const int64_t second_value = Value(second);
if (first_value == 0) {
*out = first;
} else if (second_value == 0) {
*out = MakeDim(second);
} else if (first_value == 1) {
*out = MakeDim(second);
} else if (second_value == 1) {
*out = first;
} else if (first_value == kUnknownDim || second_value == kUnknownDim) {
*out = UnknownDim();
} else {
const int64_t product = first_value * second_value;
if (product < 0) {
return errors::InvalidArgument(
"Negative dimension size caused by overflow when multiplying ",
first_value, " and ", second_value);
}
*out = MakeDim(product);
}
return Status::OK();
}

static struct task_struct *_pick_next_task_rt(struct rq *rq)
{
struct sched_rt_entity *rt_se;
struct rt_rq *rt_rq  = &rq->rt;
do {
rt_se = pick_next_rt_entity(rt_rq);
BUG_ON(!rt_se);
rt_rq = group_rt_rq(rt_se);
} while (rt_rq);
return rt_task_of(rt_se);
}

static struct task_struct *_pick_next_task_rt(struct rq *rq)
{
struct sched_rt_entity *rt_se;
struct rt_rq *rt_rq  = &rq->rt;
do {
rt_se = pick_next_rt_entity(rt_rq);
BUG_ON(!rt_se);
rt_rq = group_rt_rq(rt_se);
} while (rt_rq);
return rt_task_of(rt_se);
}

static void ok_csv_decode2(ok_csv_decoder *decoder) {
ok_csv *csv = decoder->csv;
size_t peek = 0;
uint8_t prev_char = 0;
ok_csv_decoder_state state = OK_CSV_RECORD_START;
bool is_eof = false;
while (true) {
if (decoder->input_buffer.length - peek == 0) {
size_t writeable = ok_csv_circular_buffer_writable(&decoder->input_buffer);
if (writeable == 0) {
ok_csv_circular_buffer_expand(&decoder->input_buffer);
writeable = ok_csv_circular_buffer_writable(&decoder->input_buffer);
}
uint8_t *end = decoder->input_buffer.data +
((decoder->input_buffer.start + decoder->input_buffer.length) %
decoder->input_buffer.capacity);
size_t bytesRead = decoder->input_read_func(decoder->input_data, end, writeable);
decoder->input_buffer.length += bytesRead;
}
uint8_t curr_char = 0;
if (decoder->input_buffer.length - peek > 0) {
size_t offset = (decoder->input_buffer.start + peek) % decoder->input_buffer.capacity;
curr_char = decoder->input_buffer.data[offset];
peek++;
} else {
is_eof = true;
}
switch (state) {
case OK_CSV_RECORD_START:
default: {
if (is_eof) {
return;
} else if (curr_char == '\n' && prev_char == '\r') {
ok_csv_circular_buffer_skip(&decoder->input_buffer, peek);
peek = 0;
} else if (curr_char == '\"') {
ok_csv_ensure_record_capcity(csv);
csv->num_fields[csv->num_records] = 0;
csv->fields[csv->num_records] = NULL;
csv->num_records++;
state = OK_CSV_ESCAPED_FIELD;
ok_csv_circular_buffer_skip(&decoder->input_buffer, peek);
peek = 0;
} else if (curr_char == ',' || curr_char == '\r' || curr_char == '\n') {
size_t curr_record = csv->num_records;
ok_csv_ensure_record_capcity(csv);
csv->num_fields[csv->num_records] = 0;
csv->fields[csv->num_records] = NULL;
csv->num_records++;
char *blank_field = malloc(1);
if (!blank_field) {
ok_csv_error(csv, "Couldn't allocate field");
return;
}
blank_field[0] = 0;
ok_csv_ensure_field_capcity(csv, curr_record);
csv->fields[curr_record][0] = blank_field;
csv->num_fields[curr_record] = 1;
if (curr_char == ',') {
state = OK_CSV_FIELD_START;
} else {
state = OK_CSV_RECORD_START;
}
ok_csv_circular_buffer_skip(&decoder->input_buffer, peek);
peek = 0;
} else {
ok_csv_ensure_record_capcity(csv);
csv->num_fields[csv->num_records] = 0;
csv->fields[csv->num_records] = NULL;
csv->num_records++;
state = OK_CSV_NONESCAPED_FIELD;
}
break;
}
case OK_CSV_FIELD_START: {
if (curr_char == ',' || curr_char == '\r' || curr_char == '\n' || is_eof) {
char *blank_field = malloc(1);
if (!blank_field) {
ok_csv_error(csv, "Couldn't allocate field");
return;
}
blank_field[0] = 0;
size_t curr_record = csv->num_records - 1;
ok_csv_ensure_field_capcity(csv, curr_record);
csv->fields[curr_record][csv->num_fields[curr_record]] = blank_field;
csv->num_fields[curr_record]++;
ok_csv_circular_buffer_skip(&decoder->input_buffer, peek);
peek = 0;
if (curr_char == ',') {
state = OK_CSV_FIELD_START;
} else {
state = OK_CSV_RECORD_START;
}
} else if (curr_char == '\"') {
state = OK_CSV_ESCAPED_FIELD;
ok_csv_circular_buffer_skip(&decoder->input_buffer, peek);
peek = 0;
} else {
state = OK_CSV_NONESCAPED_FIELD;
}
break;
}
case OK_CSV_ESCAPED_FIELD: {
if (is_eof || (prev_char == '\"' && peek > 1 &&
(curr_char == ',' || curr_char == '\r' || curr_char == '\n'))) {
if (prev_char == '\"') {
peek--;
}
char *field = malloc(peek + 1);
if (!field) {
ok_csv_error(csv, "Couldn't allocate field");
return;
}
char *field_ptr = field;
bool dquote_escape = false;
while (peek > 0) {
char ch = (char)decoder->input_buffer.data[decoder->input_buffer.start];
if (ch == '\"') {
if (dquote_escape) {
*field_ptr++ = '\"';
dquote_escape = false;
} else {
dquote_escape = true;
}
} else if (dquote_escape) {
*field_ptr++ = '\"';
dquote_escape = false;
*field_ptr++ = ch;
} else if (ch == '\n' && field_ptr > field && *(field_ptr - 1) == '\r') {
*(field_ptr - 1) = '\n';
} else {
*field_ptr++ = ch;
}
peek--;
ok_csv_circular_buffer_skip(&decoder->input_buffer, 1);
}
*field_ptr++ = 0;
if (prev_char == '\"') {
ok_csv_circular_buffer_skip(&decoder->input_buffer, 1);
}
size_t curr_record = csv->num_records - 1;
ok_csv_ensure_field_capcity(csv, curr_record);
csv->fields[curr_record][csv->num_fields[curr_record]] = field;
csv->num_fields[curr_record]++;
if (curr_char == ',') {
state = OK_CSV_FIELD_START;
} else if (curr_char == '\r' || curr_char == '\n') {
state = OK_CSV_RECORD_START;
}
}
break;
}
case OK_CSV_NONESCAPED_FIELD: {
if (curr_char == ',' || curr_char == '\r' || curr_char == '\n' || is_eof) {
char *field = malloc(peek);
if (!field) {
ok_csv_error(csv, "Couldn't allocate field");
return;
}
ok_csv_circular_buffer_read(&decoder->input_buffer, (unsigned char *)field,
peek - 1);
ok_csv_circular_buffer_skip(&decoder->input_buffer, 1);
field[peek - 1] = 0;
peek = 0;
size_t curr_record = csv->num_records - 1;
ok_csv_ensure_field_capcity(csv, curr_record);
csv->fields[curr_record][csv->num_fields[curr_record]] = field;
csv->num_fields[curr_record]++;
if (curr_char == ',') {
state = OK_CSV_FIELD_START;
} else if (curr_char == '\r' || curr_char == '\n') {
state = OK_CSV_RECORD_START;
}
}
break;
}
}
prev_char = curr_char;
if (is_eof) {
return;
}
}
}

static int readOHDRHeaderMessageDataLayout(struct READER *reader,
struct DATAOBJECT *data) {
int i, err;
unsigned size;
uint8_t dimensionality, layout_class;
uint32_t dataset_element_size;
uint64_t data_address, store, data_size;
UNUSED(dataset_element_size);
UNUSED(data_size);
if (fgetc(reader->fhd) != 3) {
mylog("object OHDR message data layout message must have version 3\n");
return MYSOFA_INVALID_FORMAT;
}
layout_class = (uint8_t)fgetc(reader->fhd);
mylog("data layout %d\n", layout_class);
switch (layout_class) {
#if 0
case 0:
data_size = readValue(reader, 2);
fseek(reader->fhd, data_size, SEEK_CUR);
mylog("TODO 0 SIZE %u\n", data_size);
break;
#endif
case 1:
data_address = readValue(reader, reader->superblock.size_of_offsets);
data_size = readValue(reader, reader->superblock.size_of_lengths);
mylog("CHUNK Contiguous SIZE %" PRIu64 "\n", data_size);
if (validAddress(reader, data_address)) {
store = ftell(reader->fhd);
if (fseek(reader->fhd, data_address, SEEK_SET) < 0)
return errno;       if (!data->data) {
if (data_size > 0x10000000)
return MYSOFA_INVALID_FORMAT;
data->data_len = data_size;
data->data = calloc(1, data_size);
if (!data->data)
return MYSOFA_NO_MEMORY;       }
err = fread(data->data, 1, data_size, reader->fhd);
if (err != data_size)
return MYSOFA_READ_ERROR;       if (fseek(reader->fhd, store, SEEK_SET) < 0)
return errno;     }
break;
case 2:
dimensionality = (uint8_t)fgetc(reader->fhd);
mylog("dimensionality %d\n", dimensionality);
if (dimensionality < 1 || dimensionality > DATAOBJECT_MAX_DIMENSIONALITY) {
mylog("data layout 2: invalid dimensionality %d %lu %lu\n",
dimensionality, sizeof(data->datalayout_chunk),
sizeof(data->datalayout_chunk[0]));
return MYSOFA_INVALID_FORMAT;     }
data_address = readValue(reader, reader->superblock.size_of_offsets);
mylog(" CHUNK %" PRIX64 "\n", data_address);
for (i = 0; i < dimensionality; i++) {
data->datalayout_chunk[i] = readValue(reader, 4);
mylog(" %d\n", data->datalayout_chunk[i]);
}
size = data->datalayout_chunk[dimensionality - 1];
for (i = 0; i < data->ds.dimensionality; i++)
size *= data->ds.dimension_size[i];
if (validAddress(reader, data_address) && dimensionality <= 4) {
store = ftell(reader->fhd);
if (fseek(reader->fhd, data_address, SEEK_SET) < 0)
return errno;       if (!data->data) {
if (size > 0x10000000)
return MYSOFA_INVALID_FORMAT;         data->data_len = size;
data->data = calloc(1, size);
if (!data->data)
return MYSOFA_NO_MEMORY;       }
err = treeRead(reader, data);
if (err)
return err;       if (fseek(reader->fhd, store, SEEK_SET) < 0)
return errno;     }
break;
default:
mylog("object OHDR message data layout message has unknown layout class "
"%d\n",
layout_class);
return MYSOFA_INVALID_FORMAT;
}
return MYSOFA_OK;
}

static void _gtpv1_u_recv_cb(short when, ogs_socket_t fd, void *data)
{
int len;
ssize_t size;
char buf[OGS_ADDRSTRLEN];
sgwu_sess_t *sess = NULL;
ogs_pkbuf_t *pkbuf = NULL;
ogs_sockaddr_t from;
ogs_gtp_header_t *gtp_h = NULL;
ogs_pfcp_user_plane_report_t report;
uint32_t teid;
uint8_t qfi;
ogs_assert(fd != INVALID_SOCKET);
pkbuf = ogs_pkbuf_alloc(packet_pool, OGS_MAX_PKT_LEN);
ogs_assert(pkbuf);
ogs_pkbuf_put(pkbuf, OGS_MAX_PKT_LEN);
size = ogs_recvfrom(fd, pkbuf->data, pkbuf->len, 0, &from);
if (size <= 0) {
ogs_log_message(OGS_LOG_ERROR, ogs_socket_errno,
"ogs_recv() failed");
goto cleanup;
}
ogs_pkbuf_trim(pkbuf, size);
ogs_assert(pkbuf);
ogs_assert(pkbuf->len);
gtp_h = (ogs_gtp_header_t *)pkbuf->data;
if (gtp_h->version != OGS_GTP_VERSION_1) {
ogs_error("[DROP] Invalid GTPU version [%d]", gtp_h->version);
ogs_log_hexdump(OGS_LOG_ERROR, pkbuf->data, pkbuf->len);
goto cleanup;
}
if (gtp_h->type == OGS_GTPU_MSGTYPE_ECHO_REQ) {
ogs_pkbuf_t *echo_rsp;
ogs_debug("[RECV] Echo Request from [%s]", OGS_ADDR(&from, buf));
echo_rsp = ogs_gtp_handle_echo_req(pkbuf);
ogs_expect(echo_rsp);
if (echo_rsp) {
ssize_t sent;
ogs_debug("[SEND] Echo Response to [%s]", OGS_ADDR(&from, buf));
sent = ogs_sendto(fd, echo_rsp->data, echo_rsp->len, 0, &from);
if (sent < 0 || sent != echo_rsp->len) {
ogs_log_message(OGS_LOG_ERROR, ogs_socket_errno,
"ogs_sendto() failed");
}
ogs_pkbuf_free(echo_rsp);
}
goto cleanup;
}
teid = be32toh(gtp_h->teid);
ogs_debug("[RECV] GPU-U Type [%d] from [%s] : TEID[0x%x]",
gtp_h->type, OGS_ADDR(&from, buf), teid);
qfi = 0;
if (gtp_h->flags & OGS_GTPU_FLAGS_E) {
ogs_gtp_extension_header_t *extension_header =
(ogs_gtp_extension_header_t *)(pkbuf->data + OGS_GTPV1U_HEADER_LEN);
ogs_assert(extension_header);
if (extension_header->type ==
OGS_GTP_EXTENSION_HEADER_TYPE_PDU_SESSION_CONTAINER) {
if (extension_header->pdu_type ==
OGS_GTP_EXTENSION_HEADER_PDU_TYPE_UL_PDU_SESSION_INFORMATION) {
ogs_debug("   QFI [0x%x]",
extension_header->qos_flow_identifier);
qfi = extension_header->qos_flow_identifier;
}
}
}
len = ogs_gtpu_header_len(pkbuf);
if (len < 0) {
ogs_error("[DROP] Cannot decode GTPU packet");
ogs_log_hexdump(OGS_LOG_ERROR, pkbuf->data, pkbuf->len);
goto cleanup;
}
ogs_assert(ogs_pkbuf_pull(pkbuf, len));
if (gtp_h->type == OGS_GTPU_MSGTYPE_END_MARKER) {
} else if (gtp_h->type == OGS_GTPU_MSGTYPE_ERR_IND) {
ogs_pfcp_far_t *far = NULL;
far = ogs_pfcp_far_find_by_error_indication(pkbuf);
if (far) {
ogs_assert(true ==
ogs_pfcp_up_handle_error_indication(far, &report));
if (report.type.error_indication_report) {
ogs_assert(far->sess);
sess = SGWU_SESS(far->sess);
ogs_assert(sess);
ogs_assert(OGS_OK ==
sgwu_pfcp_send_session_report_request(sess, &report));
}
} else {
ogs_error("[DROP] Cannot find FAR by Error-Indication");
ogs_log_hexdump(OGS_LOG_ERROR, pkbuf->data, pkbuf->len);
}
} else if (gtp_h->type == OGS_GTPU_MSGTYPE_GPDU) {
struct ip *ip_h = NULL;
ogs_pfcp_object_t *pfcp_object = NULL;
ogs_pfcp_sess_t *pfcp_sess = NULL;
ogs_pfcp_pdr_t *pdr = NULL;
ip_h = (struct ip *)pkbuf->data;
ogs_assert(ip_h);
pfcp_object = ogs_pfcp_object_find_by_teid(teid);
if (!pfcp_object) {
goto cleanup;
}
switch(pfcp_object->type) {
case OGS_PFCP_OBJ_PDR_TYPE:
pdr = (ogs_pfcp_pdr_t *)pfcp_object;
ogs_assert(pdr);
break;
case OGS_PFCP_OBJ_SESS_TYPE:
pfcp_sess = (ogs_pfcp_sess_t *)pfcp_object;
ogs_assert(pfcp_sess);
ogs_list_for_each(&pfcp_sess->pdr_list, pdr) {
if (pdr->src_if != OGS_PFCP_INTERFACE_ACCESS &&
pdr->src_if != OGS_PFCP_INTERFACE_CP_FUNCTION)
continue;
if (teid != pdr->f_teid.teid)
continue;
if (qfi && pdr->qfi != qfi)
continue;
if (ogs_list_first(&pdr->rule_list) &&
ogs_pfcp_pdr_rule_find_by_packet(pdr, pkbuf) == NULL)
continue;
break;
}
if (!pdr) {
goto cleanup;
}
break;
default:
ogs_fatal("Unknown type [%d]", pfcp_object->type);
ogs_assert_if_reached();
}
ogs_assert(pdr);
ogs_assert(true == ogs_pfcp_up_handle_pdr(pdr, pkbuf, &report));
if (report.type.downlink_data_report) {
ogs_assert(pdr->sess);
ogs_assert(pdr->sess->obj.type == OGS_PFCP_OBJ_SESS_TYPE);
sess = SGWU_SESS(pdr->sess);
ogs_assert(sess);
report.downlink_data.pdr_id = pdr->id;
report.downlink_data.qfi = qfi; 
ogs_assert(OGS_OK ==
sgwu_pfcp_send_session_report_request(sess, &report));
}
} else {
ogs_error("[DROP] Invalid GTPU Type [%d]", gtp_h->type);
ogs_log_hexdump(OGS_LOG_ERROR, pkbuf->data, pkbuf->len);
}
cleanup:
ogs_pkbuf_free(pkbuf);
}

