*ptr2 = 0;
off = r_num_math (core->num, ptr2+1);
}
input = (char *)r_str_trim_ro (input);
ptr = (char*)r_str_trim_ro (ptr);
if (!r_fs_mount (core->fs, input, ptr, off)) {
