static int set_core_reg(struct kvm_vcpu *vcpu, const struct kvm_one_reg *reg)
{
__u32 __user *uaddr = (__u32 __user *)(unsigned long)reg->addr;
struct kvm_regs *regs = vcpu_gp_regs(vcpu);
int nr_regs = sizeof(*regs) / sizeof(__u32);
__uint128_t tmp;
void *valp = &tmp;
u64 off;
int err = 0;
off = core_reg_offset_from_id(reg->id);
if (off >= nr_regs ||
(off + (KVM_REG_SIZE(reg->id) / sizeof(__u32))) >= nr_regs)
return -ENOENT;
if (KVM_REG_SIZE(reg->id) > sizeof(tmp))
return -EINVAL;
if (copy_from_user(valp, uaddr, KVM_REG_SIZE(reg->id))) {
err = -EFAULT;
goto out;
}
if (off == KVM_REG_ARM_CORE_REG(regs.pstate)) {
u32 mode = (*(u32 *)valp) & PSR_AA32_MODE_MASK;
switch (mode) {
case PSR_AA32_MODE_USR:
case PSR_AA32_MODE_FIQ:
case PSR_AA32_MODE_IRQ:
case PSR_AA32_MODE_SVC:
case PSR_AA32_MODE_ABT:
case PSR_AA32_MODE_UND:
case PSR_MODE_EL0t:
case PSR_MODE_EL1t:
case PSR_MODE_EL1h:
break;
default:
err = -EINVAL;
goto out;
}
}
memcpy((u32 *)regs + off, valp, KVM_REG_SIZE(reg->id));
out:
return err;
}

int read_next_sample(int ifd, int action, int curr, char *file, int *rtype, int tab,
struct file_magic *file_magic, struct file_activity *file_actlst,
struct tm *rectime, struct tm *loctime, int oneof)
{
int rc;
char rec_hdr_tmp[MAX_RECORD_HEADER_SIZE];
if ((rc = read_record_hdr(ifd, rec_hdr_tmp, &record_hdr[curr], &file_hdr,
arch_64, endian_mismatch, oneof)) != 0)
return rc;
*rtype = record_hdr[curr].record_type;
if (*rtype == R_COMMENT) {
if (action & IGNORE_COMMENT) {
if (lseek(ifd, MAX_COMMENT_LEN, SEEK_CUR) < MAX_COMMENT_LEN) {
perror("lseek");
if (oneof == UEOF_CONT)
return 2;
close(ifd);
exit(2);
}
if (action & SET_TIMESTAMPS) {
sa_get_record_timestamp_struct(flags, &record_hdr[curr],
rectime, loctime);
}
}
else {
print_special_record(&record_hdr[curr], flags, &tm_start, &tm_end,
*rtype, ifd, rectime, loctime, file, tab,
file_magic, &file_hdr, act, fmt[f_position],
endian_mismatch, arch_64);
}
}
else if (*rtype == R_RESTART) {
if (action & IGNORE_RESTART) {
if (!(action & DONT_READ_CPU_NR)) {
file_hdr.sa_cpu_nr = read_nr_value(ifd, file, file_magic,
endian_mismatch, arch_64, TRUE);
}
if (action & SET_TIMESTAMPS) {
sa_get_record_timestamp_struct(flags, &record_hdr[curr],
rectime, loctime);
}
}
else {
print_special_record(&record_hdr[curr], flags, &tm_start, &tm_end,
*rtype, ifd, rectime, loctime, file, tab,
file_magic, &file_hdr, act, fmt[f_position],
endian_mismatch, arch_64);
}
}
else {
if (read_file_stat_bunch(act, curr, ifd, file_hdr.sa_act_nr, file_actlst,
endian_mismatch, arch_64, file, file_magic, oneof) > 0)
return 2;
sa_get_record_timestamp_struct(flags, &record_hdr[curr], rectime, loctime);
}
return 0;
}

BatchBlock::BatchBlock(int32_t device_id, size_t avail_mem, int32_t max_sequences_per_poa, int8_t output_mask, bool banded_alignment)
: max_sequences_per_poa_(throw_on_negative(max_sequences_per_poa, "Maximum sequences per POA has to be non-negative"))
, banded_alignment_(banded_alignment)
, device_id_(throw_on_negative(device_id, "Device ID has to be non-negative"))
, output_mask_(output_mask)
{
matrix_sequence_dimension_ = banded_alignment_ ? CUDAPOA_BANDED_MAX_MATRIX_SEQUENCE_DIMENSION : CUDAPOA_MAX_MATRIX_SEQUENCE_DIMENSION;
max_graph_dimension_       = banded_alignment_ ? CUDAPOA_MAX_MATRIX_GRAPH_DIMENSION_BANDED : CUDAPOA_MAX_MATRIX_GRAPH_DIMENSION;
max_nodes_per_window_      = banded_alignment_ ? CUDAPOA_MAX_NODES_PER_WINDOW_BANDED : CUDAPOA_MAX_NODES_PER_WINDOW;
size_t host_size_fixed, device_size_fixed;
size_t host_size_per_poa, device_size_per_poa;
std::tie(host_size_fixed, device_size_fixed, host_size_per_poa, device_size_per_poa) = calculate_space_per_poa();
size_t minimum_device_mem = 2 * (device_size_fixed + device_size_per_poa);
if (avail_mem < minimum_device_mem)
{
std::string msg = std::string("Require at least ")
.append(std::to_string(minimum_device_mem))
.append(" bytes of device memory per CUDAPOA batch to process correctly.");
throw std::runtime_error(msg);
}
const float fraction_for_metadata = 0.4f;
max_poas_                         = (avail_mem * fraction_for_metadata) / device_size_per_poa;
output_size_ = max_poas_ * static_cast<size_t>(CUDAPOA_MAX_CONSENSUS_SIZE);
input_size_  = max_poas_ * max_sequences_per_poa_ * static_cast<size_t>(CUDAPOA_MAX_SEQUENCE_SIZE);
total_h_     = max_poas_ * host_size_per_poa + host_size_fixed;
total_d_     = avail_mem;
CGA_CU_CHECK_ERR(cudaSetDevice(device_id_));
CGA_CU_CHECK_ERR(cudaHostAlloc((void**)&block_data_h_, total_h_, cudaHostAllocDefault));
CGA_CU_CHECK_ERR(cudaMalloc((void**)&block_data_d_, total_d_));
}

void APar_ExtractTrackDetails(char *uint32_buffer,
FILE *isofile,
Trackage *track,
TrackInfo *track_info) {
uint64_t _offset = 0;
APar_TrackLevelInfo(track, "tkhd");
if (APar_read8(isofile, parsedAtoms[track->track_atom].AtomicStart + 8) ==
0) {
if (APar_read8(isofile, parsedAtoms[track->track_atom].AtomicStart + 11) &
1) {
track_info->track_enabled = true;
}
track_info->creation_time =
APar_read32(uint32_buffer,
isofile,
parsedAtoms[track->track_atom].AtomicStart + 12);
track_info->modified_time =
APar_read32(uint32_buffer,
isofile,
parsedAtoms[track->track_atom].AtomicStart + 16);
track_info->duration =
APar_read32(uint32_buffer,
isofile,
parsedAtoms[track->track_atom].AtomicStart + 28);
} else {
track_info->creation_time =
APar_read64(uint32_buffer,
isofile,
parsedAtoms[track->track_atom].AtomicStart + 12);
track_info->modified_time =
APar_read64(uint32_buffer,
isofile,
parsedAtoms[track->track_atom].AtomicStart + 20);
track_info->duration =
APar_read64(uint32_buffer,
isofile,
parsedAtoms[track->track_atom].AtomicStart + 36);
}
APar_TrackLevelInfo(track, "mdhd");
memset(uint32_buffer, 0, 5);
uint16_t packed_language = APar_read16(
uint32_buffer, isofile, parsedAtoms[track->track_atom].AtomicStart + 28);
memset(track_info->unpacked_lang, 0, 4);
APar_UnpackLanguage(
track_info->unpacked_lang,
packed_language); 
APar_TrackLevelInfo(track, "hdlr");
memset(uint32_buffer, 0, 5);
track_info->track_type = APar_read32(
uint32_buffer, isofile, parsedAtoms[track->track_atom].AtomicStart + 16);
if (track_info->track_type == 0x736F756E) {     track_info->type_of_track = AUDIO_TRACK;
} else if (track_info->track_type == 0x76696465) {     track_info->type_of_track = VIDEO_TRACK;
}
if (parsedAtoms[track->track_atom].AtomicLength > 34) {
memset(track_info->track_hdlr_name, 0, 100);
APar_readX(track_info->track_hdlr_name,
isofile,
parsedAtoms[track->track_atom].AtomicStart + 32,
parsedAtoms[track->track_atom].AtomicLength - 32);
}
APar_TrackLevelInfo(track, "stsd");
memset(uint32_buffer, 0, 5);
track_info->track_codec = APar_read32(
uint32_buffer, isofile, parsedAtoms[track->track_atom].AtomicStart + 20);
if (track_info->type_of_track & VIDEO_TRACK) {     track_info->video_width =
APar_read16(uint32_buffer,
isofile,
parsedAtoms[track->track_atom + 1].AtomicStart + 32);
track_info->video_height =
APar_read16(uint32_buffer,
isofile,
parsedAtoms[track->track_atom + 1].AtomicStart + 34);
track_info->macroblocks =
(track_info->video_width / 16) * (track_info->video_height / 16);
if (track_info->track_codec == 0x61766331 ||
track_info->track_codec == 0x64726D69) {       track_info->contains_esds = false;
APar_TrackLevelInfo(track, "avcC");
track_info->avc_version =
APar_read8(isofile, parsedAtoms[track->track_atom].AtomicStart + 8);
if (track_info->avc_version == 1) {
track_info->profile =
APar_read8(isofile, parsedAtoms[track->track_atom].AtomicStart + 9);
track_info->level = APar_read8(
isofile, parsedAtoms[track->track_atom].AtomicStart + 11);
}
} else if (track_info->track_codec == 0x73323633) {       APar_TrackLevelInfo(track, "d263");
if (memcmp(parsedAtoms[track->track_atom].AtomicName, "d263", 4) == 0) {
APar_Extract_d263_Info(
uint32_buffer, isofile, track->track_atom, track_info);
}
} else {       APar_TrackLevelInfo(track, "esds");
if (memcmp(parsedAtoms[track->track_atom].AtomicName, "esds", 4) == 0) {
APar_Extract_esds_Info(
uint32_buffer,
isofile,
track->track_atom - 1,
track_info);                                } else if (track_info->track_codec == 0x73323633) {         track_info->type_of_track = VIDEO_TRACK;
} else if (track_info->track_codec == 0x73616D72 ||
track_info->track_codec == 0x73617762 ||
track_info->track_codec == 0x73617770 ||
track_info->track_codec ==
0x73766D72) {         track_info->type_of_track = AUDIO_TRACK;
} else {
track_info->type_of_track = OTHER_TRACK;                                                        }
}
} else if (track_info->type_of_track & AUDIO_TRACK) {
if (track_info->track_codec == 0x73616D72 ||
track_info->track_codec == 0x73617762 ||
track_info->track_codec == 0x73617770 ||
track_info->track_codec ==
0x73766D72) {       APar_Extract_AMR_Info(
uint32_buffer, isofile, track->track_atom + 2, track_info);
} else if (track_info->track_codec == 0x73657663) {       APar_TrackLevelInfo(track, "devc");
if (memcmp(parsedAtoms[track->track_atom].AtomicName, "devc", 4) == 0) {
APar_Extract_devc_Info(isofile, track->track_atom, track_info);
}
} else if (track_info->track_codec == 0x73716370) {       APar_TrackLevelInfo(track, "dqcp");
if (memcmp(parsedAtoms[track->track_atom].AtomicName, "dqcp", 4) == 0) {
APar_Extract_devc_Info(isofile,
track->track_atom,
track_info);       }
} else if (track_info->track_codec == 0x73736D76) {       APar_TrackLevelInfo(track, "dsmv");
if (memcmp(parsedAtoms[track->track_atom].AtomicName, "dsmv", 4) == 0) {
APar_Extract_devc_Info(isofile,
track->track_atom,
track_info);       }
} else {
APar_Extract_esds_Info(
uint32_buffer, isofile, track->track_atom, track_info);
}
}
if ((track_info->type_of_track & AUDIO_TRACK ||
track_info->type_of_track & VIDEO_TRACK) &&
track_info->avg_bitrate == 0) {
if (track_info->track_codec == 0x616C6163) {       track_info->channels =
APar_read16(uint32_buffer,
isofile,
parsedAtoms[track->track_atom + 1].AtomicStart + 24);
}
}
APar_TrackLevelInfo(track, "stsz");
if (memcmp(parsedAtoms[track->track_atom].AtomicName, "stsz", 4) == 0) {
track_info->sample_aggregate =
calcuate_sample_size(uint32_buffer, isofile, track->track_atom);
}
if (track_info->track_codec >= 0x64726D00 &&
track_info->track_codec <= 0x64726DFF) {
track_info->type_of_track += DRM_PROTECTED_TRACK;
APar_TrackLevelInfo(track, "frma");
memset(uint32_buffer, 0, 5);
track_info->protected_codec = APar_read32(
uint32_buffer, isofile, parsedAtoms[track->track_atom].AtomicStart + 8);
}
if (track_info->contains_esds) {
APar_TrackLevelInfo(track, "esds");
_offset = APar_FindValueInAtom(
uint32_buffer, isofile, track->track_atom, 24, 0x01B2);
if (_offset > 0 && _offset < parsedAtoms[track->track_atom].AtomicLength) {
_offset += 2;
memset(track_info->encoder_name,
0,
parsedAtoms[track->track_atom].AtomicLength - _offset);
APar_readX(track_info->encoder_name,
isofile,
parsedAtoms[track->track_atom].AtomicStart + _offset,
parsedAtoms[track->track_atom].AtomicLength - _offset);
}
}
return;
}

static void coroutine_fn v9fs_write(void *opaque)
{
ssize_t err;
int32_t fid;
uint64_t off;
uint32_t count;
int32_t len = 0;
int32_t total = 0;
size_t offset = 7;
V9fsFidState *fidp;
V9fsPDU *pdu = opaque;
V9fsState *s = pdu->s;
QEMUIOVector qiov_full;
QEMUIOVector qiov;
err = pdu_unmarshal(pdu, offset, "dqd", &fid, &off, &count);
if (err < 0) {
pdu_complete(pdu, err);
return;
}
offset += err;
v9fs_init_qiov_from_pdu(&qiov_full, pdu, offset, count, true);
trace_v9fs_write(pdu->tag, pdu->id, fid, off, count, qiov_full.niov);
fidp = get_fid(pdu, fid);
if (fidp == NULL) {
err = -EINVAL;
goto out_nofid;
}
if (fidp->fid_type == P9_FID_FILE) {
if (fidp->fs.fd == -1) {
err = -EINVAL;
goto out;
}
} else if (fidp->fid_type == P9_FID_XATTR) {
err = v9fs_xattr_write(s, pdu, fidp, off, count,
qiov_full.iov, qiov_full.niov);
goto out;
} else {
err = -EINVAL;
goto out;
}
qemu_iovec_init(&qiov, qiov_full.niov);
do {
qemu_iovec_reset(&qiov);
qemu_iovec_concat(&qiov, &qiov_full, total, qiov_full.size - total);
if (0) {
print_sg(qiov.iov, qiov.niov);
}
do {
len = v9fs_co_pwritev(pdu, fidp, qiov.iov, qiov.niov, off);
if (len >= 0) {
off   += len;
total += len;
}
} while (len == -EINTR && !pdu->cancelled);
if (len < 0) {
err = len;
goto out_qiov;
}
} while (total < count && len > 0);
offset = 7;
err = pdu_marshal(pdu, offset, "d", total);
if (err < 0) {
goto out;
}
err += offset;
trace_v9fs_write_return(pdu->tag, pdu->id, total, err);
out_qiov:
qemu_iovec_destroy(&qiov);
out:
put_fid(pdu, fidp);
out_nofid:
qemu_iovec_destroy(&qiov_full);
pdu_complete(pdu, err);
}

MagickExport Image *WaveletDenoiseImage(const Image *image,
const double threshold,const double softness,ExceptionInfo *exception)
{
CacheView
*image_view,
*noise_view;
float
*kernel,
*pixels;
Image
*noise_image;
MagickBooleanType
status;
MagickSizeType
number_pixels;
MemoryInfo
*pixels_info;
ssize_t
channel;
static const float
noise_levels[] = { 0.8002f, 0.2735f, 0.1202f, 0.0585f, 0.0291f, 0.0152f,
0.0080f, 0.0044f };
assert(image != (const Image *) NULL);
assert(image->signature == MagickCoreSignature);
if (image->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",image->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
#if defined(MAGICKCORE_OPENCL_SUPPORT)
noise_image=AccelerateWaveletDenoiseImage(image,threshold,exception);
if (noise_image != (Image *) NULL)
return(noise_image);
#endif
noise_image=CloneImage(image,0,0,MagickTrue,exception);
if (noise_image == (Image *) NULL)
return((Image *) NULL);
if (SetImageStorageClass(noise_image,DirectClass,exception) == MagickFalse)
{
noise_image=DestroyImage(noise_image);
return((Image *) NULL);
}
if (AcquireMagickResource(WidthResource,4*image->columns) == MagickFalse)
ThrowImageException(ResourceLimitError,"MemoryAllocationFailed");
pixels_info=AcquireVirtualMemory(3*image->columns,image->rows*
sizeof(*pixels));
kernel=(float *) AcquireQuantumMemory(MagickMax(image->rows,image->columns),
GetOpenMPMaximumThreads()*sizeof(*kernel));
if ((pixels_info == (MemoryInfo *) NULL) || (kernel == (float *) NULL))
{
if (kernel != (float *) NULL)
kernel=(float *) RelinquishMagickMemory(kernel);
if (pixels_info != (MemoryInfo *) NULL)
pixels_info=RelinquishVirtualMemory(pixels_info);
ThrowImageException(ResourceLimitError,"MemoryAllocationFailed");
}
pixels=(float *) GetVirtualMemoryBlob(pixels_info);
status=MagickTrue;
number_pixels=(MagickSizeType) image->columns*image->rows;
image_view=AcquireAuthenticCacheView(image,exception);
noise_view=AcquireAuthenticCacheView(noise_image,exception);
for (channel=0; channel < (ssize_t) GetPixelChannels(image); channel++)
{
register ssize_t
i;
size_t
high_pass,
low_pass;
ssize_t
level,
y;
PixelChannel
pixel_channel;
PixelTrait
traits;
if (status == MagickFalse)
continue;
traits=GetPixelChannelTraits(image,(PixelChannel) channel);
if (traits == UndefinedPixelTrait)
continue;
pixel_channel=GetPixelChannelChannel(image,channel);
if ((pixel_channel != RedPixelChannel) &&
(pixel_channel != GreenPixelChannel) &&
(pixel_channel != BluePixelChannel))
continue;
i=0;
for (y=0; y < (ssize_t) image->rows; y++)
{
register const Quantum
*magick_restrict p;
ssize_t
x;
p=GetCacheViewAuthenticPixels(image_view,0,y,image->columns,1,exception);
if (p == (const Quantum *) NULL)
{
status=MagickFalse;
break;
}
for (x=0; x < (ssize_t) image->columns; x++)
{
pixels[i++]=(float) p[channel];
p+=GetPixelChannels(image);
}
}
high_pass=0;
for (level=0; level < 5; level++)
{
double
magnitude;
ssize_t
x,
y;
low_pass=(size_t) (number_pixels*((level & 0x01)+1));
#if defined(MAGICKCORE_OPENMP_SUPPORT)
#pragma omp parallel for schedule(static,1) \
magick_threads(image,image,image->rows,1)
#endif
for (y=0; y < (ssize_t) image->rows; y++)
{
const int
id = GetOpenMPThreadId();
register float
*magick_restrict p,
*magick_restrict q;
register ssize_t
x;
p=kernel+id*image->columns;
q=pixels+y*image->columns;
HatTransform(q+high_pass,1,image->columns,(size_t) (1 << level),p);
q+=low_pass;
for (x=0; x < (ssize_t) image->columns; x++)
*q++=(*p++);
}
#if defined(MAGICKCORE_OPENMP_SUPPORT)
#pragma omp parallel for schedule(static,1) \
magick_threads(image,image,image->columns,1)
#endif
for (x=0; x < (ssize_t) image->columns; x++)
{
const int
id = GetOpenMPThreadId();
register float
*magick_restrict p,
*magick_restrict q;
register ssize_t
y;
p=kernel+id*image->rows;
q=pixels+x+low_pass;
HatTransform(q,image->columns,image->rows,(size_t) (1 << level),p);
for (y=0; y < (ssize_t) image->rows; y++)
{
*q=(*p++);
q+=image->columns;
}
}
magnitude=threshold*noise_levels[level];
for (i=0; i < (ssize_t) number_pixels; ++i)
{
pixels[high_pass+i]-=pixels[low_pass+i];
if (pixels[high_pass+i] < -magnitude)
pixels[high_pass+i]+=magnitude-softness*magnitude;
else
if (pixels[high_pass+i] > magnitude)
pixels[high_pass+i]-=magnitude-softness*magnitude;
else
pixels[high_pass+i]*=softness;
if (high_pass != 0)
pixels[i]+=pixels[high_pass+i];
}
high_pass=low_pass;
}
i=0;
for (y=0; y < (ssize_t) image->rows; y++)
{
MagickBooleanType
sync;
register Quantum
*magick_restrict q;
register ssize_t
x;
ssize_t
offset;
q=GetCacheViewAuthenticPixels(noise_view,0,y,noise_image->columns,1,
exception);
if (q == (Quantum *) NULL)
{
status=MagickFalse;
break;
}
offset=GetPixelChannelOffset(noise_image,pixel_channel);
for (x=0; x < (ssize_t) image->columns; x++)
{
MagickRealType
pixel;
pixel=(MagickRealType) pixels[i]+pixels[low_pass+i];
q[offset]=ClampToQuantum(pixel);
i++;
q+=GetPixelChannels(noise_image);
}
sync=SyncCacheViewAuthenticPixels(noise_view,exception);
if (sync == MagickFalse)
status=MagickFalse;
}
if (image->progress_monitor != (MagickProgressMonitor) NULL)
{
MagickBooleanType
proceed;
proceed=SetImageProgress(image,AddNoiseImageTag,(MagickOffsetType)
channel,GetPixelChannels(image));
if (proceed == MagickFalse)
status=MagickFalse;
}
}
noise_view=DestroyCacheView(noise_view);
image_view=DestroyCacheView(image_view);
kernel=(float *) RelinquishMagickMemory(kernel);
pixels_info=RelinquishVirtualMemory(pixels_info);
if (status == MagickFalse)
noise_image=DestroyImage(noise_image);
return(noise_image);
}

static void
inflate_http2_header_block(tvbuff_t *tvb, packet_info *pinfo, guint offset,
proto_tree *tree, size_t headlen,
http2_session_t *h2session, guint8 flags)
{
guint8 *headbuf;
proto_tree *header_tree;
proto_item *header, *ti;
int header_name_length;
int header_value_length;
const gchar *header_name;
const gchar *header_value;
int hoffset = 0;
nghttp2_hd_inflater *hd_inflater;
tvbuff_t *header_tvb = tvb_new_composite();
int rv;
int header_len = 0;
int final;
int flow_index;
http2_header_data_t *header_data;
http2_header_repr_info_t *header_repr_info;
wmem_list_t *header_list;
wmem_array_t *headers;
guint i;
if (!http2_hdrcache_map) {
http2_hdrcache_map = wmem_map_new(wmem_file_scope(), http2_hdrcache_hash, http2_hdrcache_equal);
}
header_data = (http2_header_data_t*)p_get_proto_data(wmem_file_scope(), pinfo, proto_http2, 0);
header_list = header_data->header_list;
if(!PINFO_FD_VISITED(pinfo)) {
int decompressed_bytes = 0;
headbuf = (guint8*)wmem_alloc(wmem_packet_scope(), headlen);
tvb_memcpy(tvb, headbuf, offset, headlen);
flow_index = select_http2_flow_index(pinfo, h2session);
hd_inflater = h2session->hd_inflater[flow_index];
header_repr_info = &h2session->header_repr_info[flow_index];
final = flags & HTTP2_FLAGS_END_HEADERS;
headers = wmem_array_sized_new(wmem_file_scope(), sizeof(http2_header_t), 16);
for(;;) {
nghttp2_nv nv;
int inflate_flags = 0;
if (wmem_array_get_count(headers) >= MAX_HTTP2_HEADER_LINES) {
header_data->header_lines_exceeded = TRUE;
break;
}
rv = (int)nghttp2_hd_inflate_hd(hd_inflater, &nv,
&inflate_flags, headbuf, headlen, final);
if(rv < 0) {
break;
}
headbuf += rv;
headlen -= rv;
rv -= process_http2_header_repr_info(headers, header_repr_info, headbuf - rv, rv);
if(inflate_flags & NGHTTP2_HD_INFLATE_EMIT) {
char *cached_pstr;
guint32 len;
guint datalen = (guint)(4 + nv.namelen + 4 + nv.valuelen);
http2_header_t *out;
if (decompressed_bytes + datalen >= MAX_HTTP2_HEADER_SIZE) {
header_data->header_size_reached = decompressed_bytes;
header_data->header_size_attempted = decompressed_bytes + datalen;
break;
}
out = wmem_new(wmem_file_scope(), http2_header_t);
out->type = header_repr_info->type;
out->length = rv;
out->table.data.idx = header_repr_info->integer;
out->table.data.datalen = datalen;
decompressed_bytes += datalen;
http2_header_pstr = (char *)wmem_realloc(wmem_file_scope(), http2_header_pstr, out->table.data.datalen);
len = (guint32)nv.namelen;
phton32(&http2_header_pstr[0], len);
memcpy(&http2_header_pstr[4], nv.name, nv.namelen);
len = (guint32)nv.valuelen;
phton32(&http2_header_pstr[4 + nv.namelen], len);
memcpy(&http2_header_pstr[4 + nv.namelen + 4], nv.value, nv.valuelen);
cached_pstr = (char *)wmem_map_lookup(http2_hdrcache_map, http2_header_pstr);
if (cached_pstr) {
out->table.data.data = cached_pstr;
} else {
wmem_map_insert(http2_hdrcache_map, http2_header_pstr, http2_header_pstr);
out->table.data.data = http2_header_pstr;
http2_header_pstr = NULL;
}
wmem_array_append(headers, out, 1);
reset_http2_header_repr_info(header_repr_info);
}
if(inflate_flags & NGHTTP2_HD_INFLATE_FINAL) {
nghttp2_hd_inflate_end_headers(hd_inflater);
break;
}
if((inflate_flags & NGHTTP2_HD_INFLATE_EMIT) == 0 &&
headlen == 0) {
break;
}
}
wmem_list_append(header_list, headers);
if(!header_data->current) {
header_data->current = wmem_list_head(header_list);
}
} else {
headers = (wmem_array_t*)wmem_list_frame_data(header_data->current);
header_data->current = wmem_list_frame_next(header_data->current);
if(!header_data->current) {
header_data->current = wmem_list_head(header_list);
}
}
if(wmem_array_get_count(headers) == 0) {
return;
}
for(i = 0; i < wmem_array_get_count(headers); ++i) {
http2_header_t *in;
tvbuff_t *next_tvb;
in = (http2_header_t*)wmem_array_index(headers, i);
if(in->type == HTTP2_HD_HEADER_TABLE_SIZE_UPDATE) {
continue;
}
header_len += in->table.data.datalen;
next_tvb = tvb_new_child_real_data(tvb, in->table.data.data, in->table.data.datalen, in->table.data.datalen);
tvb_composite_append(header_tvb, next_tvb);
}
tvb_composite_finalize(header_tvb);
add_new_data_source(pinfo, header_tvb, "Decompressed Header");
ti = proto_tree_add_uint(tree, hf_http2_header_length, header_tvb, hoffset, 1, header_len);
PROTO_ITEM_SET_GENERATED(ti);
if (header_data->header_size_attempted > 0) {
expert_add_info_format(pinfo, ti, &ei_http2_header_size,
"Decompression stopped after %u bytes (%u attempted).",
header_data->header_size_reached,
header_data->header_size_attempted);
}
ti = proto_tree_add_uint(tree, hf_http2_header_count, header_tvb, hoffset, 1, wmem_array_get_count(headers));
PROTO_ITEM_SET_GENERATED(ti);
if (header_data->header_lines_exceeded) {
expert_add_info(pinfo, ti, &ei_http2_header_lines);
}
for(i = 0; i < wmem_array_get_count(headers); ++i) {
http2_header_t *in = (http2_header_t*)wmem_array_index(headers, i);
if(in->type == HTTP2_HD_HEADER_TABLE_SIZE_UPDATE) {
header = proto_tree_add_item(tree, hf_http2_header_table_size_update, tvb, offset, in->length, ENC_NA);
header_tree = proto_item_add_subtree(header, ett_http2_headers);
proto_tree_add_uint(header_tree, hf_http2_header_table_size, tvb, offset, in->length, in->table.header_table_size);
offset += in->length;
continue;
}
header = proto_tree_add_item(tree, hf_http2_header, tvb, offset, in->length, ENC_NA);
header_tree = proto_item_add_subtree(header, ett_http2_headers);
header_name_length = tvb_get_ntohl(header_tvb, hoffset);
proto_tree_add_uint(header_tree, hf_http2_header_name_length, tvb, offset, in->length, header_name_length);
hoffset += 4;
header_name = (gchar *)tvb_get_string_enc(wmem_packet_scope(), header_tvb, hoffset, header_name_length, ENC_ASCII|ENC_NA);
proto_tree_add_string(header_tree, hf_http2_header_name, tvb, offset, in->length, header_name);
hoffset += header_name_length;
header_value_length = tvb_get_ntohl(header_tvb, hoffset);
proto_tree_add_uint(header_tree, hf_http2_header_value_length, tvb, offset, in->length, header_value_length);
hoffset += 4;
header_value = (gchar *)tvb_get_string_enc(wmem_packet_scope(),header_tvb, hoffset, header_value_length, ENC_ASCII|ENC_NA);
proto_tree_add_string(header_tree, hf_http2_header_value, tvb, offset, in->length, header_value);
hoffset += header_value_length;
proto_tree_add_string(header_tree, hf_http2_header_repr, tvb, offset, in->length, http2_header_repr_type[in->type].strptr);
if(in->type == HTTP2_HD_INDEXED ||
in->type == HTTP2_HD_LITERAL_INDEXING_INDEXED_NAME ||
in->type == HTTP2_HD_LITERAL_INDEXED_NAME ||
in->type == HTTP2_HD_LITERAL_NEVER_INDEXING_INDEXED_NAME) {
proto_tree_add_uint(header_tree, hf_http2_header_index, tvb, offset, in->length, in->table.data.idx);
}
proto_item_append_text(header, ": %s: %s", header_name, header_value);
offset += in->length;
}
}

static gboolean
canonify_unencrypted_header(guchar *buff, guint32 *offset, guint32 buffsize)
{
const TOP_ELEMENT_CONTROL *t = canonifyTable;
guint32 len;
for (t = canonifyTable; t->element != NULL; t++)
{
len = *(t->length);
if (t->required && *(t->element) == NULL)
return FALSE;
if (*(t->element) != NULL) {
if (t->addtag) {
buff[(*offset)++] = t->tag;
(*offset) += encode_ber_len(&buff[*offset], len, 4);
}
if (t->truncate) {
len = 3+2*get_ber_len_size(len);
}
if (buffsize < *offset + len) {
return FALSE;
}
memcpy(&buff[*offset], *(t->element), len);
(*offset) += len;
if (t->addtag) {
*(t->element) = NULL;
}
}
}
return TRUE;
}

