void
formUpdateBuffer(Anchor *a, Buffer *buf, FormItemList *form)
{
Buffer save;
char *p;
int spos, epos, rows, c_rows, pos, col = 0;
Line *l;
copyBuffer(&save, buf);
gotoLine(buf, a->start.line);
switch (form->type) {
case FORM_TEXTAREA:
case FORM_INPUT_TEXT:
case FORM_INPUT_FILE:
case FORM_INPUT_PASSWORD:
case FORM_INPUT_CHECKBOX:
case FORM_INPUT_RADIO:
#ifdef MENU_SELECT
case FORM_SELECT:
#endif
spos = a->start.pos;
epos = a->end.pos;
break;
default:
spos = a->start.pos + 1;
epos = a->end.pos - 1;
}
switch (form->type) {
case FORM_INPUT_CHECKBOX:
case FORM_INPUT_RADIO:
if (form->checked)
buf->currentLine->lineBuf[spos] = '*';
else
buf->currentLine->lineBuf[spos] = ' ';
break;
case FORM_INPUT_TEXT:
case FORM_INPUT_FILE:
case FORM_INPUT_PASSWORD:
case FORM_TEXTAREA:
#ifdef MENU_SELECT
case FORM_SELECT:
if (form->type == FORM_SELECT) {
p = form->label->ptr;
updateSelectOption(form, form->select_option);
}
else
#endif
p = form->value->ptr;
l = buf->currentLine;
if (!l)
break;
if (form->type == FORM_TEXTAREA) {
int n = a->y - buf->currentLine->linenumber;
if (n > 0)
for (; l && n; l = l->prev, n--) ;
else if (n < 0)
for (; l && n; l = l->prev, n++) ;
if (!l)
break;
}
rows = form->rows ? form->rows : 1;
col = COLPOS(l, a->start.pos);
for (c_rows = 0; c_rows < rows; c_rows++, l = l->next) {
if (rows > 1) {
pos = columnPos(l, col);
a = retrieveAnchor(buf->formitem, l->linenumber, pos);
if (a == NULL)
break;
spos = a->start.pos;
epos = a->end.pos;
}
if (a->start.line != a->end.line || spos > epos || epos > l->len)
epos = spos;
pos = form_update_line(l, &p, spos, epos, COLPOS(l, epos) - col,
rows > 1,
form->type == FORM_INPUT_PASSWORD);
if (pos != epos) {
shiftAnchorPosition(buf->href, buf->hmarklist,
a->start.line, spos, pos - epos);
shiftAnchorPosition(buf->name, buf->hmarklist,
a->start.line, spos, pos - epos);
shiftAnchorPosition(buf->img, buf->hmarklist,
a->start.line, spos, pos - epos);
shiftAnchorPosition(buf->formitem, buf->hmarklist,
a->start.line, spos, pos - epos);
}
}
break;
}
copyBuffer(buf, &save);
arrangeLine(buf);
}

static void pt_lock(struct periodic_time *pt)
{
struct vcpu *v;
for ( ; ; )
{
v = pt->vcpu;
spin_lock(&v->arch.hvm.tm_lock);
if ( likely(pt->vcpu == v) )
break;
spin_unlock(&v->arch.hvm.tm_lock);
}
}

ADDRESS *rfc822_parse_adrlist (ADDRESS *top, const char *s)
{
int ws_pending, nl;
#ifdef EXACT_ADDRESS
const char *begin;
#endif
const char *ps;
char comment[LONG_STRING], phrase[LONG_STRING];
size_t phraselen = 0, commentlen = 0;
ADDRESS *cur, *last = NULL;
RFC822Error = 0;
last = top;
while (last && last->next)
last = last->next;
ws_pending = is_email_wsp (*s);
if ((nl = mutt_strlen (s)))
nl = s[nl - 1] == '\n';
s = skip_email_wsp(s);
#ifdef EXACT_ADDRESS
begin = s;
#endif
while (*s)
{
if (*s == ',')
{
if (phraselen)
{
terminate_buffer (phrase, phraselen);
add_addrspec (&top, &last, phrase, comment, &commentlen, sizeof (comment) - 1);
}
else if (commentlen && last && !last->personal)
{
terminate_buffer (comment, commentlen);
last->personal = safe_strdup (comment);
}
#ifdef EXACT_ADDRESS
if (last && !last->val)
last->val = mutt_substrdup (begin, s);
#endif
commentlen = 0;
phraselen = 0;
s++;
#ifdef EXACT_ADDRESS
begin = skip_email_wsp(s);
#endif
}
else if (*s == '(')
{
if (commentlen && commentlen < sizeof (comment) - 1)
comment[commentlen++] = ' ';
if ((ps = next_token (s, comment, &commentlen, sizeof (comment) - 1)) == NULL)
{
rfc822_free_address (&top);
return NULL;
}
s = ps;
}
else if (*s == '"')
{
if (phraselen && phraselen < sizeof (phrase) - 1)
phrase[phraselen++] = ' ';
if ((ps = parse_quote (s + 1, phrase, &phraselen, sizeof (phrase) - 1)) == NULL)
{
rfc822_free_address (&top);
return NULL;
}
s = ps;
}
else if (*s == '[')
{
if (phraselen && phraselen < sizeof (phrase) - 1 && ws_pending)
phrase[phraselen++] = ' ';
if (phraselen < sizeof (phrase) - 1)
phrase[phraselen++] = '[';
if ((ps = parse_literal (s + 1, phrase, &phraselen, sizeof (phrase) - 1)) == NULL)
{
rfc822_free_address (&top);
return NULL;
}
s = ps;
}
else if (*s == ':')
{
cur = rfc822_new_address ();
terminate_buffer (phrase, phraselen);
cur->mailbox = safe_strdup (phrase);
cur->group = 1;
if (last)
last->next = cur;
else
top = cur;
last = cur;
#ifdef EXACT_ADDRESS
last->val = mutt_substrdup (begin, s);
#endif
phraselen = 0;
commentlen = 0;
s++;
#ifdef EXACT_ADDRESS
begin = skip_email_wsp(s);
#endif
}
else if (*s == ';')
{
if (phraselen)
{
terminate_buffer (phrase, phraselen);
add_addrspec (&top, &last, phrase, comment, &commentlen, sizeof (comment) - 1);
}
else if (commentlen && last && !last->personal)
{
terminate_buffer (comment, commentlen);
last->personal = safe_strdup (comment);
}
#ifdef EXACT_ADDRESS
if (last && !last->val)
last->val = mutt_substrdup (begin, s);
#endif
if (last)
{
last->next = rfc822_new_address ();
last = last->next;
}
phraselen = 0;
commentlen = 0;
#ifdef EXACT_ADDRESS
begin = s;
#endif
s++;
}
else if (*s == '<')
{
terminate_buffer (phrase, phraselen);
cur = rfc822_new_address ();
if (phraselen)
cur->personal = safe_strdup (phrase);
if ((ps = parse_route_addr (s + 1, comment, &commentlen, sizeof (comment) - 1, cur)) == NULL)
{
rfc822_free_address (&top);
rfc822_free_address (&cur);
return NULL;
}
if (last)
last->next = cur;
else
top = cur;
last = cur;
phraselen = 0;
commentlen = 0;
s = ps;
}
else
{
if (phraselen && phraselen < sizeof (phrase) - 1 && ws_pending)
phrase[phraselen++] = ' ';
if ((ps = next_token (s, phrase, &phraselen, sizeof (phrase) - 1)) == NULL)
{
rfc822_free_address (&top);
return NULL;
}
s = ps;
}
ws_pending = is_email_wsp(*s);
s = skip_email_wsp(s);
}
if (phraselen)
{
terminate_buffer (phrase, phraselen);
terminate_buffer (comment, commentlen);
add_addrspec (&top, &last, phrase, comment, &commentlen, sizeof (comment) - 1);
}
else if (commentlen && last && !last->personal)
{
terminate_buffer (comment, commentlen);
last->personal = safe_strdup (comment);
}
#ifdef EXACT_ADDRESS
if (last && !last->val)
last->val = mutt_substrdup (begin, s - nl < begin ? begin : s - nl);
#endif
return top;
}

int build_segment_manager(struct f2fs_sb_info *sbi)
{
struct f2fs_super_block *raw_super = F2FS_RAW_SUPER(sbi);
struct f2fs_checkpoint *ckpt = F2FS_CKPT(sbi);
struct f2fs_sm_info *sm_info;
int err;
sm_info = kzalloc(sizeof(struct f2fs_sm_info), GFP_KERNEL);
if (!sm_info)
return -ENOMEM;
sbi->sm_info = sm_info;
sm_info->seg0_blkaddr = le32_to_cpu(raw_super->segment0_blkaddr);
sm_info->main_blkaddr = le32_to_cpu(raw_super->main_blkaddr);
sm_info->segment_count = le32_to_cpu(raw_super->segment_count);
sm_info->reserved_segments = le32_to_cpu(ckpt->rsvd_segment_count);
sm_info->ovp_segments = le32_to_cpu(ckpt->overprov_segment_count);
sm_info->main_segments = le32_to_cpu(raw_super->segment_count_main);
sm_info->ssa_blkaddr = le32_to_cpu(raw_super->ssa_blkaddr);
sm_info->rec_prefree_segments = sm_info->main_segments *
DEF_RECLAIM_PREFREE_SEGMENTS / 100;
if (sm_info->rec_prefree_segments > DEF_MAX_RECLAIM_PREFREE_SEGMENTS)
sm_info->rec_prefree_segments = DEF_MAX_RECLAIM_PREFREE_SEGMENTS;
if (!test_opt(sbi, LFS))
sm_info->ipu_policy = 1 << F2FS_IPU_FSYNC;
sm_info->min_ipu_util = DEF_MIN_IPU_UTIL;
sm_info->min_fsync_blocks = DEF_MIN_FSYNC_BLOCKS;
sm_info->min_hot_blocks = DEF_MIN_HOT_BLOCKS;
sm_info->trim_sections = DEF_BATCHED_TRIM_SECTIONS;
INIT_LIST_HEAD(&sm_info->sit_entry_set);
if (test_opt(sbi, FLUSH_MERGE) && !f2fs_readonly(sbi->sb)) {
err = create_flush_cmd_control(sbi);
if (err)
return err;
}
err = create_discard_cmd_control(sbi);
if (err)
return err;
err = build_sit_info(sbi);
if (err)
return err;
err = build_free_segmap(sbi);
if (err)
return err;
err = build_curseg(sbi);
if (err)
return err;
build_sit_entries(sbi);
init_free_segmap(sbi);
err = build_dirty_segmap(sbi);
if (err)
return err;
init_min_max_mtime(sbi);
return 0;
}

static int _redisContextConnectTcp(redisContext *c, const char *addr, int port,
const struct timeval *timeout,
const char *source_addr) {
redisFD s;
int rv, n;
char _port[6];  
struct addrinfo hints, *servinfo, *bservinfo, *p, *b;
int blocking = (c->flags & REDIS_BLOCK);
int reuseaddr = (c->flags & REDIS_REUSEADDR);
int reuses = 0;
long timeout_msec = -1;
servinfo = NULL;
c->connection_type = REDIS_CONN_TCP;
c->tcp.port = port;
if (c->tcp.host != addr) {
free(c->tcp.host);
c->tcp.host = strdup(addr);
}
if (timeout) {
if (c->timeout != timeout) {
if (c->timeout == NULL)
c->timeout = malloc(sizeof(struct timeval));
memcpy(c->timeout, timeout, sizeof(struct timeval));
}
} else {
free(c->timeout);
c->timeout = NULL;
}
if (redisContextTimeoutMsec(c, &timeout_msec) != REDIS_OK) {
__redisSetError(c, REDIS_ERR_IO, "Invalid timeout specified");
goto error;
}
if (source_addr == NULL) {
free(c->tcp.source_addr);
c->tcp.source_addr = NULL;
} else if (c->tcp.source_addr != source_addr) {
free(c->tcp.source_addr);
c->tcp.source_addr = strdup(source_addr);
}
snprintf(_port, 6, "%d", port);
memset(&hints,0,sizeof(hints));
hints.ai_family = AF_INET;
hints.ai_socktype = SOCK_STREAM;
if ((rv = getaddrinfo(c->tcp.host,_port,&hints,&servinfo)) != 0) {
hints.ai_family = AF_INET6;
if ((rv = getaddrinfo(addr,_port,&hints,&servinfo)) != 0) {
__redisSetError(c,REDIS_ERR_OTHER,gai_strerror(rv));
return REDIS_ERR;
}
}
for (p = servinfo; p != NULL; p = p->ai_next) {
addrretry:
if ((s = socket(p->ai_family,p->ai_socktype,p->ai_protocol)) == REDIS_INVALID_FD)
continue;
c->fd = s;
if (redisSetBlocking(c,0) != REDIS_OK)
goto error;
if (c->tcp.source_addr) {
int bound = 0;
if ((rv = getaddrinfo(c->tcp.source_addr, NULL, &hints, &bservinfo)) != 0) {
char buf[128];
snprintf(buf,sizeof(buf),"Can't get addr: %s",gai_strerror(rv));
__redisSetError(c,REDIS_ERR_OTHER,buf);
goto error;
}
if (reuseaddr) {
n = 1;
if (setsockopt(s, SOL_SOCKET, SO_REUSEADDR, (char*) &n,
sizeof(n)) < 0) {
freeaddrinfo(bservinfo);
goto error;
}
}
for (b = bservinfo; b != NULL; b = b->ai_next) {
if (bind(s,b->ai_addr,b->ai_addrlen) != -1) {
bound = 1;
break;
}
}
freeaddrinfo(bservinfo);
if (!bound) {
char buf[128];
snprintf(buf,sizeof(buf),"Can't bind socket: %s",strerror(errno));
__redisSetError(c,REDIS_ERR_OTHER,buf);
goto error;
}
}
free(c->saddr);
c->saddr = malloc(p->ai_addrlen);
memcpy(c->saddr, p->ai_addr, p->ai_addrlen);
c->addrlen = p->ai_addrlen;
if (connect(s,p->ai_addr,p->ai_addrlen) == -1) {
if (errno == EHOSTUNREACH) {
redisNetClose(c);
continue;
} else if (errno == EINPROGRESS) {
if (blocking) {
goto wait_for_ready;
}
} else if (errno == EADDRNOTAVAIL && reuseaddr) {
if (++reuses >= REDIS_CONNECT_RETRIES) {
goto error;
} else {
redisNetClose(c);
goto addrretry;
}
} else {
wait_for_ready:
if (redisContextWaitReady(c,timeout_msec) != REDIS_OK)
goto error;
}
}
if (blocking && redisSetBlocking(c,1) != REDIS_OK)
goto error;
if (redisSetTcpNoDelay(c) != REDIS_OK)
goto error;
c->flags |= REDIS_CONNECTED;
rv = REDIS_OK;
goto end;
}
if (p == NULL) {
char buf[128];
snprintf(buf,sizeof(buf),"Can't create socket: %s",strerror(errno));
__redisSetError(c,REDIS_ERR_OTHER,buf);
goto error;
}
error:
rv = REDIS_ERR;
end:
if(servinfo) {
freeaddrinfo(servinfo);
}
return rv;  }

static const u_char *
smb_fdata1(netdissect_options *ndo,
const u_char *buf, const char *fmt, const u_char *maxbuf,
int unicodestr)
{
int reverse = 0;
const char *attrib_fmt = "READONLY|HIDDEN|SYSTEM|VOLUME|DIR|ARCHIVE|";
char strbuf[MAX_UNISTR_SIZE+1];
while (*fmt && buf<maxbuf) {
switch (*fmt) {
case 'a':
write_bits(ndo, GET_U_1(buf), attrib_fmt);
buf++;
fmt++;
break;
case 'A':
write_bits(ndo, GET_LE_U_2(buf), attrib_fmt);
buf += 2;
fmt++;
break;
case '{':
{
char bitfmt[128];
char *p;
u_int l;
p = strchr(++fmt, '}');
l = ND_BYTES_BETWEEN(p, fmt);
if (l > sizeof(bitfmt) - 1)
l = sizeof(bitfmt)-1;
strncpy(bitfmt, fmt, l);
bitfmt[l] = '\0';
fmt = p + 1;
write_bits(ndo, GET_U_1(buf), bitfmt);
buf++;
break;
}
case 'P':
{
int l = atoi(fmt + 1);
ND_TCHECK_LEN(buf, l);
buf += l;
fmt++;
while (ND_ASCII_ISDIGIT(*fmt))
fmt++;
break;
}
case 'r':
reverse = !reverse;
fmt++;
break;
case 'b':
{
unsigned int x;
x = GET_U_1(buf);
ND_PRINT("%u (0x%x)", x, x);
buf += 1;
fmt++;
break;
}
case 'd':
{
int x;
x = reverse ? GET_BE_S_2(buf) :
GET_LE_S_2(buf);
ND_PRINT("%d (0x%x)", x, x);
buf += 2;
fmt++;
break;
}
case 'D':
{
int x;
x = reverse ? GET_BE_S_4(buf) :
GET_LE_S_4(buf);
ND_PRINT("%d (0x%x)", x, x);
buf += 4;
fmt++;
break;
}
case 'L':
{
uint64_t x;
x = reverse ? GET_BE_U_8(buf) :
GET_LE_U_8(buf);
ND_PRINT("%" PRIu64 " (0x%" PRIx64 ")", x, x);
buf += 8;
fmt++;
break;
}
case 'u':
{
unsigned int x;
x = reverse ? GET_BE_U_2(buf) :
GET_LE_U_2(buf);
ND_PRINT("%u (0x%x)", x, x);
buf += 2;
fmt++;
break;
}
case 'U':
{
unsigned int x;
x = reverse ? GET_BE_U_4(buf) :
GET_LE_U_4(buf);
ND_PRINT("%u (0x%x)", x, x);
buf += 4;
fmt++;
break;
}
case 'M':
{
uint32_t x1, x2;
uint64_t x;
ND_TCHECK_8(buf);
x1 = reverse ? GET_BE_U_4(buf) :
GET_LE_U_4(buf);
x2 = reverse ? GET_BE_U_4(buf + 4) :
GET_LE_U_4(buf + 4);
x = (((uint64_t)x1) << 32) | x2;
ND_PRINT("%" PRIu64 " (0x%" PRIx64 ")", x, x);
buf += 8;
fmt++;
break;
}
case 'B':
{
unsigned int x;
x = GET_U_1(buf);
ND_PRINT("0x%X", x);
buf += 1;
fmt++;
break;
}
case 'w':
{
unsigned int x;
x = reverse ? GET_BE_U_2(buf) :
GET_LE_U_2(buf);
ND_PRINT("0x%X", x);
buf += 2;
fmt++;
break;
}
case 'W':
{
unsigned int x;
x = reverse ? GET_BE_U_4(buf) :
GET_LE_U_4(buf);
ND_PRINT("0x%X", x);
buf += 4;
fmt++;
break;
}
case 'l':
{
fmt++;
switch (*fmt) {
case 'b':
stringlen = GET_U_1(buf);
stringlen_is_set = 1;
ND_PRINT("%u", stringlen);
buf += 1;
break;
case 'd':
case 'u':
stringlen = reverse ? GET_BE_U_2(buf) :
GET_LE_U_2(buf);
stringlen_is_set = 1;
ND_PRINT("%u", stringlen);
buf += 2;
break;
case 'D':
case 'U':
stringlen = reverse ? GET_BE_U_4(buf) :
GET_LE_U_4(buf);
stringlen_is_set = 1;
ND_PRINT("%u", stringlen);
buf += 4;
break;
}
fmt++;
break;
}
case 'S':
case 'R':
{
buf = unistr(ndo, &strbuf, buf, 0, 1, (*fmt == 'R') ? 0 : unicodestr);
ND_PRINT("%s", strbuf);
if (buf == NULL)
goto trunc;
fmt++;
break;
}
case 'Z':
case 'Y':
{
if (GET_U_1(buf) != 4 && GET_U_1(buf) != 2) {
ND_PRINT("Error! ASCIIZ buffer of type %u", GET_U_1(buf));
return maxbuf;
}
buf = unistr(ndo, &strbuf, buf + 1, 0, 1, (*fmt == 'Y') ? 0 : unicodestr);
ND_PRINT("%s", strbuf);
if (buf == NULL)
goto trunc;
fmt++;
break;
}
case 's':
{
int l = atoi(fmt + 1);
ND_TCHECK_LEN(buf, l);
ND_PRINT("%-*.*s", l, l, buf);
buf += l;
fmt++;
while (ND_ASCII_ISDIGIT(*fmt))
fmt++;
break;
}
case 'c':
{
if (!stringlen_is_set) {
ND_PRINT("{stringlen not set}");
goto trunc;
}
ND_TCHECK_LEN(buf, stringlen);
ND_PRINT("%-*.*s", (int)stringlen, (int)stringlen, buf);
buf += stringlen;
fmt++;
while (ND_ASCII_ISDIGIT(*fmt))
fmt++;
break;
}
case 'C':
{
if (!stringlen_is_set) {
ND_PRINT("{stringlen not set}");
goto trunc;
}
buf = unistr(ndo, &strbuf, buf, stringlen, 0, unicodestr);
ND_PRINT("%s", strbuf);
if (buf == NULL)
goto trunc;
fmt++;
break;
}
case 'h':
{
int l = atoi(fmt + 1);
ND_TCHECK_LEN(buf, l);
while (l--) {
ND_PRINT("%02x", GET_U_1(buf));
buf++;
}
fmt++;
while (ND_ASCII_ISDIGIT(*fmt))
fmt++;
break;
}
case 'n':
{
int t = atoi(fmt+1);
char nbuf[255];
int name_type;
int len;
switch (t) {
case 1:
name_type = name_extract(ndo, startbuf, ND_BYTES_BETWEEN(buf, startbuf),
maxbuf, nbuf);
if (name_type < 0)
goto trunc;
len = name_len(ndo, buf, maxbuf);
if (len < 0)
goto trunc;
buf += len;
ND_PRINT("%-15.15s NameType=0x%02X (%s)", nbuf, name_type,
name_type_str(name_type));
break;
case 2:
name_type = GET_U_1(buf + 15);
ND_PRINT("%-15.15s NameType=0x%02X (%s)", buf, name_type,
name_type_str(name_type));
buf += 16;
break;
}
fmt++;
while (ND_ASCII_ISDIGIT(*fmt))
fmt++;
break;
}
case 'T':
{
time_t t;
struct tm *lt;
const char *tstring;
char buffer[sizeof("Www Mmm dd hh:mm:ss yyyyy\n")];
uint32_t x;
switch (atoi(fmt + 1)) {
case 1:
x = GET_LE_U_4(buf);
if (x == 0 || x == 0xFFFFFFFF)
t = 0;
else
t = make_unix_date(ndo, buf);
buf += 4;
break;
case 2:
x = GET_LE_U_4(buf);
if (x == 0 || x == 0xFFFFFFFF)
t = 0;
else
t = make_unix_date2(ndo, buf);
buf += 4;
break;
case 3:
ND_TCHECK_8(buf);
t = interpret_long_date(ndo, buf);
buf += 8;
break;
default:
t = 0;
break;
}
if (t != 0) {
lt = localtime(&t);
if (lt != NULL) {
strftime(buffer, sizeof(buffer), "%a %b %e %T %Y%n", lt);
tstring = buffer;
}
else
tstring = "(Can't convert time)\n";
} else
tstring = "NULL\n";
ND_PRINT("%s", tstring);
fmt++;
while (ND_ASCII_ISDIGIT(*fmt))
fmt++;
break;
}
default:
ND_PRINT("%c", *fmt);
fmt++;
break;
}
}
if (buf >= maxbuf && *fmt)
ND_PRINT("END OF BUFFER\n");
return(buf);
trunc:
nd_print_trunc(ndo);
return(NULL);
}

void APar_ExtractBrands(char *filepath) {
FILE *a_file = APar_OpenISOBaseMediaFile(filepath, true);
char *buffer = (char *)calloc(1, sizeof(char) * 16);
uint32_t atom_length = 0;
uint8_t file_type_offset = 0;
uint32_t compatible_brand = 0;
bool cb_V2ISOBMFF = false;
APar_read32(buffer, a_file, 4);
if (memcmp(buffer, "ftyp", 4) == 0) {
atom_length = APar_read32(buffer, a_file, 0);
} else {
APar_readX(buffer, a_file, 0, 12);
if (memcmp(buffer,
"\x00\x00\x00\x0C\x6A\x50\x20\x20\x0D\x0A\x87\x0A",
12) == 0) {
APar_readX(buffer, a_file, 12, 12);
if (memcmp(buffer + 4, "ftypmjp2", 8) == 0 ||
memcmp(buffer + 4, "ftypmj2s", 8) == 0) {
atom_length = UInt32FromBigEndian(buffer);
file_type_offset = 12;
}
}
}
if (atom_length > 0) {
memset(buffer, 0, 16);
APar_readX(buffer, a_file, 8 + file_type_offset, 4);
printBOM();
fprintf(stdout, " Major Brand: %s", buffer);
APar_IdentifyBrand(buffer);
if (memcmp(buffer, "isom", 4) == 0) {
APar_ScanAtoms(filepath);     }
uint32_t minor_version = APar_read32(buffer, a_file, 12 + file_type_offset);
fprintf(stdout, "  -  version %" PRIu32 "\n", minor_version);
fprintf(stdout, " Compatible Brands:");
for (uint64_t i = 16 + file_type_offset; i < atom_length; i += 4) {
APar_readX(buffer, a_file, i, 4);
compatible_brand = UInt32FromBigEndian(buffer);
if (compatible_brand != 0) {
fprintf(stdout, " %s", buffer);
if (compatible_brand == 0x6D703432 || compatible_brand == 0x69736F32) {
cb_V2ISOBMFF = true;
}
}
}
fprintf(stdout, "\n");
}
APar_OpenISOBaseMediaFile(filepath, false);
fprintf(stdout, " Tagging schemes available:\n");
switch (metadata_style) {
case ITUNES_STYLE: {
fprintf(stdout, "   iTunes-style metadata allowed.\n");
break;
}
case THIRD_GEN_PARTNER:
case THIRD_GEN_PARTNER_VER1_REL6:
case THIRD_GEN_PARTNER_VER1_REL7:
case THIRD_GEN_PARTNER_VER2: {
fprintf(stdout, "   3GP-style asset metadata allowed.\n");
break;
}
case THIRD_GEN_PARTNER_VER2_REL_A: {
fprintf(stdout,
"   3GP-style asset metadata allowed [& unimplemented GAD "
"(Geographical Area Description) asset].\n");
break;
}
}
if (cb_V2ISOBMFF || metadata_style == THIRD_GEN_PARTNER_VER1_REL7) {
fprintf(stdout,
"   ID3 tags on ID32 atoms @ file/movie/track level allowed.\n");
}
fprintf(stdout,
"   ISO-copyright notices @ movie and/or track level "
"allowed.\n   uuid private user extension tags allowed.\n");
free(buffer);
buffer = NULL;
return;
}

