n_tags != le64toh(f->header->n_tags)) {
error(offsetof(Header, n_tags),
"Tag number mismatch (%"PRIu64" != %"PRIu64")",
n_tags,
le64toh(f->header->n_tags));
r = -EBADMSG;
goto fail;
}
