mmap_cache_fd_free(cache_data_fd);
if (cache_entry_fd)
mmap_cache_fd_free(cache_entry_fd);
if (cache_entry_array_fd)
mmap_cache_fd_free(cache_entry_array_fd);
return r;
}

int journal_file_verify(
