n_fields != le64toh(f->header->n_fields)) {
error(offsetof(Header, n_fields),
"Field number mismatch (%"PRIu64" != %"PRIu64")",
n_fields,
le64toh(f->header->n_fields));
r = -EBADMSG;
goto fail;
