static gboolean k12_read(wtap *wth, int *err, gchar **err_info, gint64 *data_offset) {
k12_t *k12 = (k12_t *)wth->priv;
k12_src_desc_t* src_desc;
guint8* buffer;
gint64 offset;
gint len;
guint32 type;
guint32 src_id;
offset = file_tell(wth->fh);
do {
if ( k12->num_of_records == 0 ) {
*err = 0;
return FALSE;
}
K12_DBG(5,("k12_read: offset=%i",offset));
*data_offset = offset;
len = get_record(k12, wth->fh, offset, FALSE, err, err_info);
if (len < 0) {
return FALSE;
} else if (len == 0) {
*err = WTAP_ERR_SHORT_READ;
return FALSE;
} else if (len < K12_RECORD_SRC_ID + 4) {
*err = WTAP_ERR_BAD_FILE;
*err_info = g_strdup_printf("data record length %d too short", len);
return FALSE;
}
k12->num_of_records--;
buffer = k12->seq_read_buff;
type = pntoh32(buffer + K12_RECORD_TYPE);
src_id = pntoh32(buffer + K12_RECORD_SRC_ID);
if ( ! (src_desc = (k12_src_desc_t*)g_hash_table_lookup(k12->src_by_id,GUINT_TO_POINTER(src_id))) ) {
src_desc = (k12_src_desc_t*)g_hash_table_lookup(k12->src_by_id,GUINT_TO_POINTER(src_id&K12_RECORD_SRC_ID_MASK));
}
K12_DBG(5,("k12_read: record type=%x src_id=%x",type,src_id));
offset += len;
} while ( ((type & K12_MASK_PACKET) != K12_REC_PACKET && (type & K12_MASK_PACKET) != K12_REC_D0020) || !src_id || !src_desc );
process_packet_data(&wth->phdr, wth->frame_buffer, buffer, len, k12);
return TRUE;
}

char *ogs_nas_5gs_suci_from_mobile_identity(
ogs_nas_5gs_mobile_identity_t *mobile_identity)
{
ogs_nas_5gs_mobile_identity_suci_t *mobile_identity_suci = NULL;
ogs_plmn_id_t plmn_id;
char tmp[OGS_MAX_IMSI_BCD_LEN+1];
char routing_indicator[5];
char *suci = NULL;
ogs_assert(mobile_identity);
mobile_identity_suci =
(ogs_nas_5gs_mobile_identity_suci_t *)mobile_identity->buffer;
ogs_assert(mobile_identity_suci);
ogs_expect_or_return_val(mobile_identity_suci->h.supi_format ==
OGS_NAS_5GS_SUPI_FORMAT_IMSI, NULL);
ogs_expect_or_return_val(mobile_identity_suci->protection_scheme_id ==
OGS_NAS_5GS_NULL_SCHEME, NULL);
suci = ogs_msprintf("suci-%d-", mobile_identity_suci->h.supi_format);
ogs_expect_or_return_val(suci, NULL);
ogs_nas_to_plmn_id(&plmn_id, &mobile_identity_suci->nas_plmn_id);
if (ogs_plmn_id_mnc_len(&plmn_id) == 2) {
suci = ogs_mstrcatf(suci, "%03d-%02d-",
ogs_plmn_id_mcc(&plmn_id), ogs_plmn_id_mnc(&plmn_id));
ogs_expect_or_return_val(suci, NULL);
} else {
suci = ogs_mstrcatf(suci, "%03d-%03d-",
ogs_plmn_id_mcc(&plmn_id), ogs_plmn_id_mnc(&plmn_id));
ogs_expect_or_return_val(suci, NULL);
}
memset(routing_indicator, 0, sizeof(routing_indicator));
if (mobile_identity_suci->routing_indicator1 != 0xf) {
routing_indicator[0] =
mobile_identity_suci->routing_indicator1 + '0';
if (mobile_identity_suci->routing_indicator2 != 0xf) {
routing_indicator[1] =
mobile_identity_suci->routing_indicator2 + '0';
if (mobile_identity_suci->routing_indicator3 != 0xf) {
routing_indicator[2] =
mobile_identity_suci->routing_indicator3 + '0';
if (mobile_identity_suci->routing_indicator4 != 0xf)
routing_indicator[3] =
mobile_identity_suci->routing_indicator4 + '0';
}
}
}
ogs_expect_or_return_val(mobile_identity->length > 8, NULL);
ogs_buffer_to_bcd(mobile_identity_suci->scheme_output,
mobile_identity->length - 8, tmp);
suci = ogs_mstrcatf(suci, "%s-%d-%d-%s",
routing_indicator,
mobile_identity_suci->protection_scheme_id,
mobile_identity_suci->home_network_pki_value,
tmp);
ogs_expect(suci);
return suci;
}

static void
do_pdf_save_document(fz_context *ctx, pdf_document *doc, pdf_write_state *opts, pdf_write_options *in_opts)
{
int lastfree;
int num;
int xref_len;
if (in_opts->do_incremental)
{
if (doc->num_incremental_sections == 0)
return;
if (opts->out)
{
fz_seek_output(ctx, opts->out, 0, SEEK_END);
fz_write_string(ctx, opts->out, "\n");
}
}
xref_len = pdf_xref_len(ctx, doc);
fz_try(ctx)
{
initialise_write_state(ctx, doc, in_opts, opts);
if (!opts->do_incremental)
{
pdf_ensure_solid_xref(ctx, doc, xref_len);
preloadobjstms(ctx, doc);
}
if (opts->do_garbage >= 1 || opts->do_linear)
(void)markobj(ctx, doc, opts, pdf_trailer(ctx, doc));
else
for (num = 0; num < xref_len; num++)
opts->use_list[num] = 1;
if (opts->do_garbage >= 3)
removeduplicateobjs(ctx, doc, opts);
if (opts->do_garbage >= 2 || opts->do_linear)
compactxref(ctx, doc, opts);
if (opts->do_garbage >= 2 || opts->do_linear)
renumberobjs(ctx, doc, opts);
if ((opts->do_garbage >= 2 || opts->do_linear) && !opts->do_incremental)
while (xref_len > 0 && !opts->use_list[xref_len-1])
xref_len--;
if (opts->do_linear)
linearize(ctx, doc, opts);
if (opts->do_incremental)
{
int i;
doc->disallow_new_increments = 1;
for (i = 0; i < doc->num_incremental_sections; i++)
{
doc->xref_base = doc->num_incremental_sections - i - 1;
writeobjects(ctx, doc, opts, 0);
#ifdef DEBUG_WRITING
dump_object_details(ctx, doc, opts);
#endif
for (num = 0; num < xref_len; num++)
{
if (!opts->use_list[num] && pdf_xref_is_incremental(ctx, doc, num))
{
opts->gen_list[num] = 65535;
opts->ofs_list[num] = 0;
}
}
opts->first_xref_offset = fz_tell_output(ctx, opts->out);
if (doc->has_xref_streams)
writexrefstream(ctx, doc, opts, 0, xref_len, 1, 0, opts->first_xref_offset);
else
writexref(ctx, doc, opts, 0, xref_len, 1, 0, opts->first_xref_offset);
doc->xref_sections[doc->xref_base].end_ofs = fz_tell_output(ctx, opts->out);
}
doc->xref_base = 0;
doc->disallow_new_increments = 0;
}
else
{
writeobjects(ctx, doc, opts, 0);
#ifdef DEBUG_WRITING
dump_object_details(ctx, doc, opts);
#endif
lastfree = 0;
for (num = 0; num < xref_len; num++)
{
if (!opts->use_list[num])
{
opts->gen_list[num]++;
opts->ofs_list[lastfree] = num;
lastfree = num;
}
}
if (opts->do_linear && opts->page_count > 0)
{
opts->main_xref_offset = fz_tell_output(ctx, opts->out);
writexref(ctx, doc, opts, 0, opts->start, 0, 0, opts->first_xref_offset);
opts->file_len = fz_tell_output(ctx, opts->out);
make_hint_stream(ctx, doc, opts);
if (opts->do_ascii)
{
opts->hintstream_len *= 2;
opts->hintstream_len += 1 + ((opts->hintstream_len+63)>>6);
}
opts->file_len += opts->hintstream_len;
opts->main_xref_offset += opts->hintstream_len;
update_linearization_params(ctx, doc, opts);
fz_seek_output(ctx, opts->out, 0, 0);
writeobjects(ctx, doc, opts, 1);
padto(ctx, opts->out, opts->main_xref_offset);
writexref(ctx, doc, opts, 0, opts->start, 0, 0, opts->first_xref_offset);
}
else
{
opts->first_xref_offset = fz_tell_output(ctx, opts->out);
writexref(ctx, doc, opts, 0, xref_len, 1, 0, opts->first_xref_offset);
}
doc->xref_sections[0].end_ofs = fz_tell_output(ctx, opts->out);
}
doc->dirty = 0;
}
fz_always(ctx)
{
#ifdef DEBUG_LINEARIZATION
page_objects_dump(opts);
objects_dump(ctx, doc, opts);
#endif
finalise_write_state(ctx, opts);
doc->freeze_updates = 0;
}
fz_catch(ctx)
{
fz_rethrow(ctx);
}
}

