msg->u.confconn.status);
jzon_add_bool(jobj, "selective_audio",
msg->u.confconn.selective_audio);
jzon_add_bool(jobj, "selective_video",
msg->u.confconn.selective_video);
jzon_add_int(jobj, "vstreams",
msg->u.confconn.vstreams);
break;
case ECONN_CONF_START:
jzon_add_str(jobj, "sft_url", "%s", msg->u.confstart.sft_url);
jzon_add_base64(jobj, "secret",
msg->u.confstart.secret, msg->u.confstart.secretlen);
jzon_add_str(jobj, "timestamp", "%llu", msg->u.confstart.timestamp);
jzon_add_str(jobj, "seqno", "%u", msg->u.confstart.seqno);
if (msg->u.confstart.props) {
err = econn_props_encode(jobj, msg->u.confstart.props);
if (err)
goto out;
}
break;
case ECONN_CONF_CHECK:
jzon_add_str(jobj, "sft_url", "%s", msg->u.confcheck.sft_url);
jzon_add_base64(jobj, "secret",
msg->u.confcheck.secret, msg->u.confcheck.secretlen);
jzon_add_str(jobj, "timestamp", "%llu", msg->u.confcheck.timestamp);
jzon_add_str(jobj, "seqno", "%u", msg->u.confcheck.seqno);
break;
case ECONN_CONF_END:
break;
case ECONN_CONF_PART:
jzon_add_bool(jobj, "should_start",
msg->u.confpart.should_start);
jzon_add_str(jobj, "timestamp", "%llu", msg->u.confpart.timestamp);
jzon_add_str(jobj, "seqno", "%u", msg->u.confpart.seqno);
jzon_add_base64(jobj, "entropy",
msg->u.confpart.entropy, msg->u.confpart.entropylen);
econn_parts_encode(jobj, &msg->u.confpart.partl);
break;
case ECONN_CONF_KEY:
econn_keys_encode(jobj, &msg->u.confkey.keyl);
break;
case ECONN_DEVPAIR_PUBLISH:
err = zapi_iceservers_encode(jobj,
msg->u.devpair_publish.turnv,
msg->u.devpair_publish.turnc);
if (err)
goto out;
err = jzon_add_str(jobj, "sdp",
"%s", msg->u.devpair_publish.sdp);
err |= jzon_add_str(jobj, "username",
"%s", msg->u.devpair_publish.username);
if (err)
goto out;
break;
case ECONN_DEVPAIR_ACCEPT:
err = jzon_add_str(jobj, "sdp",
"%s", msg->u.devpair_accept.sdp);
if (err)
goto out;
break;
case ECONN_ALERT:
err  = jzon_add_int(jobj, "level", msg->u.alert.level);
err |= jzon_add_str(jobj, "descr", "%s", msg->u.alert.descr);
if (err)
goto out;
break;
case ECONN_PING:
break;
default:
warning("econn: dont know how to encode %d\n", msg->msg_type);
err = EBADMSG;
break;
}
if (err)
goto out;
err = jzon_encode(&str, jobj);
if (err)
goto out;
out:
mem_deref(jobj);
if (err)
mem_deref(str);
else
*strp = str;
return err;
}

int main(int argc, char *argv[]) {
GooString *fileName;
UnicodeMap *uMap;
GooString *ownerPW, *userPW;
PDFDoc *doc;
char uBuf[8];
char path[1024];
char *p;
bool ok;
int exitCode;
GooList *embeddedFiles = nullptr;
int nFiles, nPages, n, i, j;
FileSpec *fileSpec;
Page *page;
Annots *annots;
Annot *annot;
const GooString *s1;
Unicode u;
bool isUnicode;
Win32Console win32Console(&argc, &argv);
exitCode = 99;
ok = parseArgs(argDesc, &argc, argv);
if ((doList ? 1 : 0) +
((saveNum != 0) ? 1 : 0) +
(saveAll ? 1 : 0) != 1) {
ok = false;
}
if (!ok || argc != 2 || printVersion || printHelp) {
fprintf(stderr, "pdfdetach version %s\n", PACKAGE_VERSION);
fprintf(stderr, "%s\n", popplerCopyright);
fprintf(stderr, "%s\n", xpdfCopyright);
if (!printVersion) {
printUsage("pdfdetach", "<PDF-file>", argDesc);
}
goto err0;
}
fileName = new GooString(argv[1]);
globalParams = new GlobalParams();
if (textEncName[0]) {
globalParams->setTextEncoding(textEncName);
}
if (!(uMap = globalParams->getTextEncoding())) {
error(errConfig, -1, "Couldn't get text encoding");
delete fileName;
goto err1;
}
if (ownerPassword[0] != '\001') {
ownerPW = new GooString(ownerPassword);
} else {
ownerPW = nullptr;
}
if (userPassword[0] != '\001') {
userPW = new GooString(userPassword);
} else {
userPW = nullptr;
}
doc = PDFDocFactory().createPDFDoc(*fileName, ownerPW, userPW);
if (userPW) {
delete userPW;
}
if (ownerPW) {
delete ownerPW;
}
if (!doc->isOk()) {
exitCode = 1;
goto err2;
}
embeddedFiles = new GooList();
for (i = 0; i < doc->getCatalog()->numEmbeddedFiles(); ++i)
embeddedFiles->push_back(doc->getCatalog()->embeddedFile(i));
nPages = doc->getCatalog()->getNumPages();
for (i = 0; i < nPages; ++i) {
page = doc->getCatalog()->getPage(i + 1);
if (!page)
continue;
annots = page->getAnnots();
if (!annots)
break;
for (j = 0; j < annots->getNumAnnots(); ++j) {
annot = annots->getAnnot(j);
if (annot->getType() != Annot::typeFileAttachment)
continue;
embeddedFiles->push_back(new FileSpec(static_cast<AnnotFileAttachment *>(annot)->getFile()));
}
}
nFiles = embeddedFiles->getLength();
if (doList) {
printf("%d embedded files\n", nFiles);
for (i = 0; i < nFiles; ++i) {
fileSpec = static_cast<FileSpec *>(embeddedFiles->get(i));
printf("%d: ", i+1);
s1 = fileSpec->getFileName();
if ((s1->getChar(0) & 0xff) == 0xfe && (s1->getChar(1) & 0xff) == 0xff) {
isUnicode = true;
j = 2;
} else {
isUnicode = false;
j = 0;
}
while (j < fileSpec->getFileName()->getLength()) {
if (isUnicode) {
u = ((s1->getChar(j) & 0xff) << 8) | (s1->getChar(j+1) & 0xff);
j += 2;
} else {
u = pdfDocEncoding[s1->getChar(j) & 0xff];
++j;
}
n = uMap->mapUnicode(u, uBuf, sizeof(uBuf));
fwrite(uBuf, 1, n, stdout);
}
fputc('\n', stdout);
}
} else if (saveAll) {
for (i = 0; i < nFiles; ++i) {
fileSpec = static_cast<FileSpec *>(embeddedFiles->get(i));
if (savePath[0]) {
n = strlen(savePath);
if (n > (int)sizeof(path) - 2) {
n = sizeof(path) - 2;
}
memcpy(path, savePath, n);
path[n] = '/';
p = path + n + 1;
} else {
p = path;
}
s1 = fileSpec->getFileName();
if ((s1->getChar(0) & 0xff) == 0xfe && (s1->getChar(1) & 0xff) == 0xff) {
isUnicode = true;
j = 2;
} else {
isUnicode = false;
j = 0;
}
while (j < fileSpec->getFileName()->getLength()) {
if (isUnicode) {
u = ((s1->getChar(j) & 0xff) << 8) | (s1->getChar(j+1) & 0xff);
j += 2;
} else {
u = pdfDocEncoding[s1->getChar(j) & 0xff];
++j;
}
n = uMap->mapUnicode(u, uBuf, sizeof(uBuf));
if (p + n >= path + sizeof(path))
break;
memcpy(p, uBuf, n);
p += n;
}
*p = '\0';
auto *embFile = fileSpec->getEmbeddedFile();
if (!embFile || !embFile->isOk()) {
exitCode = 3;
goto err2;
}
if (!embFile->save(path)) {
error(errIO, -1, "Error saving embedded file as '{0:s}'", p);
exitCode = 2;
goto err2;
}
}
} else {
if (saveNum < 1 || saveNum > nFiles) {
error(errCommandLine, -1, "Invalid file number");
goto err2;
}
fileSpec = static_cast<FileSpec *>(embeddedFiles->get(saveNum - 1));
if (savePath[0]) {
p = savePath;
} else {
p = path;
s1 = fileSpec->getFileName();
if ((s1->getChar(0) & 0xff) == 0xfe && (s1->getChar(1) & 0xff) == 0xff) {
isUnicode = true;
j = 2;
} else {
isUnicode = false;
j = 0;
}
while (j < fileSpec->getFileName()->getLength()) {
if (isUnicode) {
u = ((s1->getChar(j) & 0xff) << 8) | (s1->getChar(j+1) & 0xff);
j += 2;
} else {
u = pdfDocEncoding[s1->getChar(j) & 0xff];
++j;
}
n = uMap->mapUnicode(u, uBuf, sizeof(uBuf));
if (p + n >= path + sizeof(path))
break;
memcpy(p, uBuf, n);
p += n;
}
*p = '\0';
p = path;
}
auto *embFile = fileSpec->getEmbeddedFile();
if (!embFile || !embFile->isOk()) {
exitCode = 3;
goto err2;
}
if (!embFile->save(p)) {
error(errIO, -1, "Error saving embedded file as '{0:s}'", p);
exitCode = 2;
goto err2;
}
}
exitCode = 0;
err2:
if (embeddedFiles)
deleteGooList<FileSpec>(embeddedFiles);
uMap->decRefCnt();
delete doc;
err1:
delete globalParams;
err0:
return exitCode;
}

int __sys_recvmmsg(int fd, struct mmsghdr __user *mmsg, unsigned int vlen,
unsigned int flags, struct timespec *timeout)
{
int fput_needed, err, datagrams;
struct socket *sock;
struct mmsghdr __user *entry;
struct compat_mmsghdr __user *compat_entry;
struct msghdr msg_sys;
struct timespec end_time;
if (timeout &&
poll_select_set_timeout(&end_time, timeout->tv_sec,
timeout->tv_nsec))
return -EINVAL;
datagrams = 0;
sock = sockfd_lookup_light(fd, &err, &fput_needed);
if (!sock)
return err;
err = sock_error(sock->sk);
if (err)
goto out_put;
entry = mmsg;
compat_entry = (struct compat_mmsghdr __user *)mmsg;
while (datagrams < vlen) {
if (MSG_CMSG_COMPAT & flags) {
err = ___sys_recvmsg(sock, (struct user_msghdr __user *)compat_entry,
&msg_sys, flags & ~MSG_WAITFORONE,
datagrams);
if (err < 0)
break;
err = __put_user(err, &compat_entry->msg_len);
++compat_entry;
} else {
err = ___sys_recvmsg(sock,
(struct user_msghdr __user *)entry,
&msg_sys, flags & ~MSG_WAITFORONE,
datagrams);
if (err < 0)
break;
err = put_user(err, &entry->msg_len);
++entry;
}
if (err)
break;
++datagrams;
if (flags & MSG_WAITFORONE)
flags |= MSG_DONTWAIT;
if (timeout) {
ktime_get_ts(timeout);
*timeout = timespec_sub(end_time, *timeout);
if (timeout->tv_sec < 0) {
timeout->tv_sec = timeout->tv_nsec = 0;
break;
}
if (timeout->tv_nsec == 0 && timeout->tv_sec == 0)
break;
}
if (msg_sys.msg_flags & MSG_OOB)
break;
cond_resched();
}
out_put:
fput_light(sock->file, fput_needed);
if (err == 0)
return datagrams;
if (datagrams != 0) {
if (err != -EAGAIN) {
sock->sk->sk_err = -err;
}
return datagrams;
}
return err;
}

