static int slice_get_derivative(AVFilterContext* ctx, void* arg, int jobnr, int nb_jobs)
{
ColorConstancyContext *s = ctx->priv;
ThreadData *td = arg;
AVFrame *in = td->in;
const int ord = td->meta_data[INDEX_ORD];
const int dir = td->meta_data[INDEX_DIR];
const int src_index  = td->meta_data[INDEX_SRC];
const int dst_index  = td->meta_data[INDEX_DST];
const int filtersize = s->filtersize;
const double *gauss  = s->gauss[ord];
int plane;
for (plane = 0; plane < NUM_PLANES; ++plane) {
const int height      = s->planeheight[plane];
const int width       = s->planewidth[plane];
const int in_linesize = in->linesize[plane];
double *dst = td->data[dst_index][plane];
int slice_start, slice_end;
int r, c, g;
if (dir == DIR_X) {
const uint8_t *src = in->data[plane];
slice_start = (height * jobnr      ) / nb_jobs;
slice_end   = (height * (jobnr + 1)) / nb_jobs;
for (r = slice_start; r < slice_end; ++r) {
for (c = 0; c < width; ++c) {
dst[INDX2D(r, c, width)] = 0;
for (g = 0; g < filtersize; ++g) {
dst[INDX2D(r, c, width)] += GAUSS(src, r,                        c + GINDX(filtersize, g),
in_linesize, height, width, gauss[GINDX(filtersize, g)]);
}
}
}
} else {
const double *src = td->data[src_index][plane];
slice_start = (width * jobnr      ) / nb_jobs;
slice_end   = (width * (jobnr + 1)) / nb_jobs;
for (c = slice_start; c < slice_end; ++c) {
for (r = 0; r < height; ++r) {
dst[INDX2D(r, c, width)] = 0;
for (g = 0; g < filtersize; ++g) {
dst[INDX2D(r, c, width)] += GAUSS(src, r + GINDX(filtersize, g), c,
width, height, width, gauss[GINDX(filtersize, g)]);
}
}
}
}
}
return 0;
}

int yr_re_fast_exec(
uint8_t* code,
uint8_t* input_data,
size_t input_forwards_size,
size_t input_backwards_size,
int flags,
RE_MATCH_CALLBACK_FUNC callback,
void* callback_args,
int* matches)
{
RE_REPEAT_ANY_ARGS* repeat_any_args;
uint8_t* code_stack[MAX_FAST_RE_STACK];
uint8_t* input_stack[MAX_FAST_RE_STACK];
int matches_stack[MAX_FAST_RE_STACK];
uint8_t* ip = code;
uint8_t* input = input_data;
uint8_t* next_input;
uint8_t* next_opcode;
uint8_t mask;
uint8_t value;
int i;
int stop;
int input_incr;
int sp = 0;
int bytes_matched;
int max_bytes_matched;
max_bytes_matched = flags & RE_FLAGS_BACKWARDS ?
(int) input_backwards_size :
(int) input_forwards_size;
input_incr = flags & RE_FLAGS_BACKWARDS ? -1 : 1;
if (flags & RE_FLAGS_BACKWARDS)
input--;
code_stack[sp] = code;
input_stack[sp] = input;
matches_stack[sp] = 0;
sp++;
while (sp > 0)
{
sp--;
ip = code_stack[sp];
input = input_stack[sp];
bytes_matched = matches_stack[sp];
stop = FALSE;
while(!stop)
{
if (*ip == RE_OPCODE_MATCH)
{
if (flags & RE_FLAGS_EXHAUSTIVE)
{
FAIL_ON_ERROR(callback(
flags & RE_FLAGS_BACKWARDS ? input + 1 : input_data,
bytes_matched,
flags,
callback_args));
break;
}
else
{
if (matches != NULL)
*matches = bytes_matched;
return ERROR_SUCCESS;
}
}
if (bytes_matched >= max_bytes_matched)
break;
switch(*ip)
{
case RE_OPCODE_LITERAL:
if (*input == *(ip + 1))
{
bytes_matched++;
input += input_incr;
ip += 2;
}
else
{
stop = TRUE;
}
break;
case RE_OPCODE_MASKED_LITERAL:
value = *(int16_t*)(ip + 1) & 0xFF;
mask = *(int16_t*)(ip + 1) >> 8;
if ((*input & mask) == value)
{
bytes_matched++;
input += input_incr;
ip += 3;
}
else
{
stop = TRUE;
}
break;
case RE_OPCODE_ANY:
bytes_matched++;
input += input_incr;
ip += 1;
break;
case RE_OPCODE_REPEAT_ANY_UNGREEDY:
repeat_any_args = (RE_REPEAT_ANY_ARGS*)(ip + 1);
next_opcode = ip + 1 + sizeof(RE_REPEAT_ANY_ARGS);
for (i = repeat_any_args->min + 1; i <= repeat_any_args->max; i++)
{
next_input = input + i * input_incr;
if (bytes_matched + i >= max_bytes_matched)
break;
if ( *(next_opcode) != RE_OPCODE_LITERAL ||
(*(next_opcode) == RE_OPCODE_LITERAL &&
*(next_opcode + 1) == *next_input))
{
if (sp >= MAX_FAST_RE_STACK)
return -4;
code_stack[sp] = next_opcode;
input_stack[sp] = next_input;
matches_stack[sp] = bytes_matched + i;
sp++;
}
}
input += input_incr * repeat_any_args->min;
bytes_matched += repeat_any_args->min;
ip = next_opcode;
break;
default:
assert(FALSE);
}
}
}
if (matches != NULL)
*matches = -1;
return ERROR_SUCCESS;
}

status_t CursorWindow::writeToParcel(Parcel* parcel) {
LOG(DEBUG) << "Writing to parcel: " << this->toString();
if (parcel->writeString8(mName)) goto fail;
if (parcel->writeUint32(mNumRows)) goto fail;
if (parcel->writeUint32(mNumColumns)) goto fail;
if (mAshmemFd != -1) {
if (parcel->writeUint32(mSize)) goto fail;
if (parcel->writeBool(true)) goto fail;
if (parcel->writeDupFileDescriptor(mAshmemFd)) goto fail;
} else {
size_t slotsSize = mSize - mSlotsOffset;
size_t compactedSize = mAllocOffset + slotsSize;
compactedSize = (compactedSize + 3) & ~3;
if (parcel->writeUint32(compactedSize)) goto fail;
if (parcel->writeBool(false)) goto fail;
void* dest = parcel->writeInplace(compactedSize);
if (!dest) goto fail;
memcpy(static_cast<uint8_t*>(dest),
static_cast<uint8_t*>(mData), mAllocOffset);
memcpy(static_cast<uint8_t*>(dest) + compactedSize - slotsSize,
static_cast<uint8_t*>(mData) + mSlotsOffset, slotsSize);
}
return OK;
fail:
LOG(ERROR) << "Failed writeToParcel";
fail_silent:
return UNKNOWN_ERROR;
}

libspdm_return_t libspdm_get_response_capabilities(libspdm_context_t *spdm_context,
size_t request_size,
const void *request,
size_t *response_size,
void *response)
{
const spdm_get_capabilities_request_t *spdm_request;
spdm_capabilities_response_t *spdm_response;
libspdm_return_t status;
spdm_request = request;
if (spdm_context->response_state != LIBSPDM_RESPONSE_STATE_NORMAL) {
return libspdm_responder_handle_response_state(
spdm_context, spdm_request->header.request_response_code,  response_size, response);
}
if (spdm_context->connection_info.connection_state != LIBSPDM_CONNECTION_STATE_AFTER_VERSION) {
return libspdm_generate_error_response(spdm_context,
SPDM_ERROR_CODE_UNEXPECTED_REQUEST,
0, response_size, response);
}
if (!libspdm_check_request_version_compatibility(
spdm_context, spdm_request->header.spdm_version)) {
return libspdm_generate_error_response(spdm_context,
SPDM_ERROR_CODE_VERSION_MISMATCH, 0,
response_size, response);
}
if (spdm_request->header.spdm_version >= SPDM_MESSAGE_VERSION_12) {
if (request_size < sizeof(spdm_get_capabilities_request_t)) {
return libspdm_generate_error_response(
spdm_context, SPDM_ERROR_CODE_INVALID_REQUEST, 0, response_size, response);
} else {
request_size = sizeof(spdm_get_capabilities_request_t);
}
} else if (spdm_request->header.spdm_version >= SPDM_MESSAGE_VERSION_11) {
if (request_size < sizeof(spdm_get_capabilities_request_t) -
sizeof(spdm_request->data_transfer_size) - sizeof(spdm_request->max_spdm_msg_size)) {
return libspdm_generate_error_response(
spdm_context, SPDM_ERROR_CODE_INVALID_REQUEST, 0, response_size, response);
} else {
request_size = sizeof(spdm_get_capabilities_request_t) -
sizeof(spdm_request->data_transfer_size) -
sizeof(spdm_request->max_spdm_msg_size);
}
} else {
if (request_size < sizeof(spdm_message_header_t)) {
return libspdm_generate_error_response(
spdm_context, SPDM_ERROR_CODE_INVALID_REQUEST, 0, response_size, response);
} else {
request_size = sizeof(spdm_message_header_t);
}
}
if (!libspdm_check_request_flag_compatibility(
spdm_request->flags, spdm_request->header.spdm_version)) {
return libspdm_generate_error_response(spdm_context,
SPDM_ERROR_CODE_INVALID_REQUEST, 0,
response_size, response);
}
if (spdm_request->header.spdm_version >= SPDM_MESSAGE_VERSION_12) {
if ((spdm_request->data_transfer_size < SPDM_MIN_DATA_TRANSFER_SIZE_VERSION_12) ||
(spdm_request->data_transfer_size > spdm_request->max_spdm_msg_size)) {
return libspdm_generate_error_response(spdm_context,
SPDM_ERROR_CODE_INVALID_REQUEST, 0,
response_size, response);
}
if (((spdm_request->flags & SPDM_GET_CAPABILITIES_REQUEST_FLAGS_CHUNK_CAP) == 0) &&
(spdm_request->data_transfer_size != spdm_request->max_spdm_msg_size)) {
return libspdm_generate_error_response(spdm_context,
SPDM_ERROR_CODE_INVALID_REQUEST, 0,
response_size, response);
}
}
libspdm_reset_message_buffer_via_request_code(spdm_context, NULL,
spdm_request->header.request_response_code);
LIBSPDM_ASSERT(*response_size >= sizeof(spdm_capabilities_response_t));
*response_size = sizeof(spdm_capabilities_response_t);
libspdm_zero_mem(response, *response_size);
spdm_response = response;
spdm_response->header.spdm_version = spdm_request->header.spdm_version;
spdm_response->header.request_response_code = SPDM_CAPABILITIES;
spdm_response->header.param1 = 0;
spdm_response->header.param2 = 0;
spdm_response->ct_exponent = spdm_context->local_context.capability.ct_exponent;
spdm_response->flags = spdm_context->local_context.capability.flags;
spdm_response->data_transfer_size = spdm_context->local_context.capability.data_transfer_size;
spdm_response->max_spdm_msg_size = spdm_context->local_context.capability.max_spdm_msg_size;
if (spdm_response->header.spdm_version >= SPDM_MESSAGE_VERSION_12) {
*response_size = sizeof(spdm_capabilities_response_t);
} else {
*response_size = sizeof(spdm_capabilities_response_t) -
sizeof(spdm_response->data_transfer_size) -
sizeof(spdm_response->max_spdm_msg_size);
}
status = libspdm_append_message_a(spdm_context, spdm_request, request_size);
if (LIBSPDM_STATUS_IS_ERROR(status)) {
return libspdm_generate_error_response(spdm_context,
SPDM_ERROR_CODE_UNSPECIFIED, 0,
response_size, response);
}
status = libspdm_append_message_a(spdm_context, spdm_response, *response_size);
if (LIBSPDM_STATUS_IS_ERROR(status)) {
return libspdm_generate_error_response(spdm_context,
SPDM_ERROR_CODE_UNSPECIFIED, 0,
response_size, response);
}
if (spdm_response->header.spdm_version >= SPDM_MESSAGE_VERSION_11) {
spdm_context->connection_info.capability.ct_exponent = spdm_request->ct_exponent;
spdm_context->connection_info.capability.flags = spdm_request->flags;
} else {
spdm_context->connection_info.capability.ct_exponent = 0;
spdm_context->connection_info.capability.flags = 0;
}
if (spdm_response->header.spdm_version >= SPDM_MESSAGE_VERSION_12) {
spdm_context->connection_info.capability.data_transfer_size =
spdm_request->data_transfer_size;
spdm_context->connection_info.capability.max_spdm_msg_size =
spdm_request->max_spdm_msg_size;
} else {
spdm_context->connection_info.capability.data_transfer_size = 0;
spdm_context->connection_info.capability.max_spdm_msg_size = 0;
}
libspdm_set_connection_state(spdm_context, LIBSPDM_CONNECTION_STATE_AFTER_CAPABILITIES);
return LIBSPDM_STATUS_SUCCESS;
}

