static int
zstatus(i_ctx_t *i_ctx_p)
{
os_ptr op = osp;
switch (r_type(op)) {
case t_file:
{
stream *s;
make_bool(op, (file_is_valid(s, op) ? 1 : 0));
}
return 0;
case t_string:
{
gs_parsed_file_name_t pname;
struct stat fstat;
int code = parse_file_name(op, &pname,
i_ctx_p->LockFilePermissions, imemory);
if (code < 0) {
if (code == gs_error_undefinedfilename) {
make_bool(op, 0);
code = 0;
}
return code;
}
code = gs_terminate_file_name(&pname, imemory, "status");
if (code < 0)
return code;
code = (*pname.iodev->procs.file_status)(pname.iodev,
pname.fname, &fstat);
switch (code) {
case 0:
check_ostack(4);
push(4);
make_int(op - 4, stat_blocks(&fstat));
make_int(op - 3, fstat.st_size);
if ((double)op[-4].value.intval !=
(double)stat_blocks(&fstat) ||
(double)op[-3].value.intval !=
(double)fstat.st_size
)
return_error(gs_error_limitcheck);
make_int(op - 2, fstat.st_mtime);
make_int(op - 1, fstat.st_ctime);
make_bool(op, 1);
break;
case gs_error_undefinedfilename:
make_bool(op, 0);
code = 0;
}
gs_free_file_name(&pname, "status");
return code;
}
default:
return_op_typecheck(op);
}
}

void ndpi_search_oracle(struct ndpi_detection_module_struct *ndpi_struct, struct ndpi_flow_struct *flow)
{
struct ndpi_packet_struct *packet = &flow->packet;
u_int16_t dport = 0, sport = 0;
NDPI_LOG_DBG(ndpi_struct, "search ORACLE\n");
if(packet->tcp != NULL) {
sport = ntohs(packet->tcp->source), dport = ntohs(packet->tcp->dest);
NDPI_LOG_DBG2(ndpi_struct, "calculating ORACLE over tcp\n");
if ((dport == 1521 || sport == 1521)
&&  (((packet->payload[0] == 0x07) && (packet->payload[1] == 0xff) && (packet->payload[2] == 0x00))
|| ((packet->payload_packet_len >= 232) && ((packet->payload[0] == 0x00) || (packet->payload[0] == 0x01)) 
&& (packet->payload[1] != 0x00)
&& (packet->payload[2] == 0x00)
&& (packet->payload[3] == 0x00)))) {
NDPI_LOG_INFO(ndpi_struct, "found oracle\n");
ndpi_int_oracle_add_connection(ndpi_struct, flow);
} else if (packet->payload_packet_len == 213 && packet->payload[0] == 0x00 &&
packet->payload[1] == 0xd5 && packet->payload[2] == 0x00 &&
packet->payload[3] == 0x00 ) {
NDPI_LOG_INFO(ndpi_struct, "found oracle\n");
ndpi_int_oracle_add_connection(ndpi_struct, flow);
}
} else {
NDPI_EXCLUDE_PROTO(ndpi_struct, flow);
}
}

int main (int argc, char **argv)
{
int i, nomoreoptions;
int seenFiles = 0, processedFiles = 0;
if (argc == 1 || !strncmp(argv[1], "-h", 2) || !strncmp(argv[1], "--help", 6))
{
printf ("PNGdefry version 1.1 by [Jongware], 21-Jan-2012\n");
printf ("\n");
printf ("Removes -iphone specific data chunk, reverses colors from BGRA to RGBA, and de-multiplies alpha\n");
printf ("\n");
printf ("usage: pngdefry [-soaplvid] file.png [...]\n");
printf ("\n");
printf ("Options:\n");
printf ("  -h         show this help\n");
printf ("  -          use this if your first input file starts with an '-'\n");
printf ("  -s(suffix) append suffix to output file name\n");
printf ("  -o(path)   write output file(s) to path\n");
printf ("             Note: without -s or -o, NO output will be created.\n");
printf ("  -a         do NOT de-multiply alpha\n");
printf ("  -l         list all chunks\n");
printf ("  -v         verbose processing\n");
printf ("  -i(value)  max IDAT chunk size in bytes (minimum: 1024; default: %u)\n", repack_IDAT_size);
printf ("  -p         process all files, not just -iphone ones (for debugging purposed only)\n");
printf ("  -d         very verbose processing (for debugging purposes only)\n");
return 0;
}
nomoreoptions = 0;
for (i=1; i<argc; i++)
{
if (argv[i][0] != '-')
break;
switch (argv[i][1])
{
case 0:
nomoreoptions = 1;
break;
case 'd': flag_Debug = 1; flag_Verbose = 1; flag_List_Chunks = 1; break;
case 'a': flag_UpdateAlpha = 0; break;
case 'l': flag_List_Chunks = 1; break;
case 'p': flag_Process_Anyway = 1; break;
case 'v': flag_Verbose = 1; break;
case 's':
if (argv[i][2])
{
suffix = (char *)malloc(strlen(argv[i])+2);
if (suffix == NULL)
{
printf ("pngdefry : unexpected memory allocation error on line %d\n", __LINE__);
return -1;
}
strcpy (suffix, argv[i]+2);
} else
{
if (i < argc-1)
{
i++;
suffix = (char *)malloc(strlen(argv[i])+2);
if (suffix == NULL)
{
printf ("pngdefry : unexpected memory allocation error on line %d\n", __LINE__);
return -1;
}
strcpy (suffix, argv[i]);
} else
{
printf ("pngdefry : -s is missing suffix\n");
return -1;
}
}
argv[i][2] = 0;
flag_Rewrite = 1;
break;
case 'o':
if (argv[i][2])
{
outputPath = (char *)malloc(strlen(argv[i])+2);
if (outputPath == NULL)
{
printf ("pngdefry : unexpected memory allocation error on line %d\n", __LINE__);
return -1;
}
strcpy (outputPath, argv[i]+2);
} else
{
if (i < argc-1)
{
i++;
outputPath = (char *)malloc(strlen(argv[i])+2);
if (outputPath == NULL)
{
printf ("pngdefry : unexpected memory allocation error on line %d\n", __LINE__);
return -1;
}
strcpy (outputPath, argv[i]);
} else
{
printf ("pngdefry : -o is missing output path\n");
return -1;
}
}
argv[i][2] = 0;
flag_Rewrite = 1;
break;
case 'i':
if (argv[i][2])
{
char *endptr;
repack_IDAT_size = strtol(argv[i]+2, &endptr, 10);
if (*endptr || repack_IDAT_size < 1024)
{
printf ("pngdefry : invalid repack size '%s'\n", argv[i]+2);
return -1;
}
argv[i][2] = 0;
break;
} else
{
if (i < argc-1)
{
char *endptr;
i++;
repack_IDAT_size = strtol(argv[i], &endptr, 10);
if (*endptr || repack_IDAT_size < 1024)
{
printf ("pngdefry : invalid repack size '%s'\n", argv[i]);
return -1;
}
argv[i][2] = 0;
} else
{
printf ("pngdefry : -i is missing repack size\n");
return -1;
}
}
break;
default:
printf ("pngdefry : unknown option '%s'\n", argv[i]);
return -1;
}
if (nomoreoptions)
{
i++;
break;
}
if (argv[i][2] != 0)
{
printf ("pngdefry : unknown option '%s'\n", argv[i]);
return -1;
}
}
if (i == argc)
{
printf ("pngdefry : no file name(s) provided\n");
return -1;
}
for (; i<argc; i++)
{
seenFiles++;
if (process (argv[i]))
processedFiles++;
}
if (flag_Rewrite)
printf ("pngdefry : seen %d file(s), wrote %d file(s)\n", seenFiles, processedFiles);
else
printf ("pngdefry : seen %d file(s), processed %d file(s)\n", seenFiles, processedFiles);
return 0;
}

static gboolean
netscreen_seek_read(wtap *wth, gint64 seek_off,
struct wtap_pkthdr *phdr, Buffer *buf,
int *err, gchar **err_info)
{
