pairing_cb.is_ssp = TRUE;
cod = COD_UNCLASSIFIED;
HAL_CBACK(bt_hal_cbacks, ssp_request_cb, &bd_addr, &bd_name, cod,
BT_SSP_VARIANT_CONSENT, 0);
}

