static Jsi_RC jsiEvalSubscript(Jsi_Interp *interp, Jsi_Value *src, Jsi_Value *idx, jsi_OpCode *ip,  jsi_OpCode *end,
Jsi_Value *currentScope)
{
Jsi_RC rc = JSI_OK;
Jsi_String *str = jsi_ValueString(src);
if (str && Jsi_ValueIsNumber(interp, idx)) {
int bLen, cLen;
char bbuf[10], *cp = Jsi_ValueString(interp, src, &bLen);
int n = (int)idx->d.num;
cLen = bLen;
#if JSI__UTF8
if (str->flags&JSI_IS_UTF || !(str->flags&JSI_UTF_CHECKED)) {
cLen = Jsi_NumUtfChars(cp, bLen);
str->flags |= JSI_UTF_CHECKED;
if (cLen != bLen)
str->flags |= JSI_IS_UTF;
}
#endif
if (n<0 || n>=cLen) {
Jsi_ValueMakeUndef(interp, &src);
} else {
if (cLen != bLen)
Jsi_UtfGetIndex(cp, n, bbuf);
else {
bbuf[0] = cp[n];
bbuf[1] = 0;
}
Jsi_ValueMakeStringDup(interp, &src, bbuf);
}
return rc;
}
uint flags = (uintptr_t)ip->data, right_val = flags&1;     bool ro = src->f.bits.readonly;
Jsi_Obj *obj = (src->vt==JSI_VT_OBJECT && src->d.obj->ot == JSI_OT_OBJECT?src->d.obj:NULL);
int bsc = (src->vt==JSI_VT_OBJECT && src->d.obj->ot == JSI_OT_NUMBER); 
if (bsc == 0 && interp->lastSubscriptFail && interp->lastSubscriptFail->vt != JSI_VT_UNDEF)
Jsi_ValueReset(interp, &interp->lastSubscriptFail);
rc = Jsi_ValueToObject(interp, src);
if (rc != JSI_OK)
return rc;
Jsi_Value res = VALINIT, 
*resPtr = &res,
*vp = jsi_ValueSubscript(interp, src, idx, &resPtr, right_val);
if (!vp && bsc == 0) {
if (idx->vt == JSI_VT_STRING)
interp->lastSubscriptFailStr = idx->d.s.str;
Jsi_ValueDup2(interp, &interp->lastSubscriptFail, src);
}
if (!vp) {
Jsi_ValueMakeUndef(interp, &src);
if (obj && obj->freeze && obj->freezeReadCheck) {
const char *keyStr = Jsi_ValueToString(interp, idx, NULL);
if (!jsi_isDebugKey(keyStr))
rc = Jsi_LogError("object freeze: read undefined \"%s\"", keyStr);
}
}
else {
Jsi_IncrRefCount(interp, vp);
if (right_val || vp->f.bits.readonly) {
if (vp == resPtr && (res.vt == JSI_VT_OBJECT || res.vt == JSI_VT_STRING))                  Jsi_ValueMove(interp, src, vp);
else
Jsi_ValueCopy(interp, src, vp);
} else {
assert(vp != resPtr);
res.vt = JSI_VT_VARIABLE;
res.d.lval = vp;
if (ro)
vp->f.bits.readonly = 1;
Jsi_ValueCopy(interp, src, resPtr);
}
Jsi_DecrRefCount(interp, vp);
}
return rc;
}

int GENERAL_NAME_cmp(GENERAL_NAME *a, GENERAL_NAME *b)
{
int result = -1;
if (!a || !b || a->type != b->type)
return -1;
switch (a->type) {
case GEN_X400:
case GEN_EDIPARTY:
result = ASN1_TYPE_cmp(a->d.other, b->d.other);
break;
case GEN_OTHERNAME:
result = OTHERNAME_cmp(a->d.otherName, b->d.otherName);
break;
case GEN_EMAIL:
case GEN_DNS:
case GEN_URI:
result = ASN1_STRING_cmp(a->d.ia5, b->d.ia5);
break;
case GEN_DIRNAME:
result = X509_NAME_cmp(a->d.dirn, b->d.dirn);
break;
case GEN_IPADD:
result = ASN1_OCTET_STRING_cmp(a->d.ip, b->d.ip);
break;
case GEN_RID:
result = OBJ_cmp(a->d.rid, b->d.rid);
break;
}
return result;
}

int nfc_llcp_send_symm(struct nfc_dev *dev)
{
struct sk_buff *skb;
struct nfc_llcp_local *local;
u16 size = 0;
local = nfc_llcp_find_local(dev);
if (local == NULL)
return -ENODEV;
size += LLCP_HEADER_SIZE;
size += dev->tx_headroom + dev->tx_tailroom + NFC_HEADER_SIZE;
skb = alloc_skb(size, GFP_KERNEL);
if (skb == NULL)
return -ENOMEM;
skb_reserve(skb, dev->tx_headroom + NFC_HEADER_SIZE);
skb = llcp_add_header(skb, 0, 0, LLCP_PDU_SYMM);
__net_timestamp(skb);
nfc_llcp_send_to_raw_sock(local, skb, NFC_DIRECTION_TX);
return nfc_data_exchange(dev, local->target_idx, skb,
nfc_llcp_recv, local);
}

int
jsonparse_next(struct jsonparse_state *state)
{
char c;
char s;
char v;
skip_ws(state);
c = state->json[state->pos];
s = jsonparse_get_type(state);
v = state->vtype;
state->pos++;
switch(c) {
case '{':
if((s == 0 && v == 0) || s == '[' || s == ':') {
push(state, c);
} else {
state->error = JSON_ERROR_UNEXPECTED_OBJECT;
return JSON_TYPE_ERROR;
}
return c;
case '}':
if((s == ':' && v != ',' && v != 0 ) || (s == '{' && v == 0)) {
pop(state);
} else {
state->error = JSON_ERROR_UNEXPECTED_END_OF_OBJECT;
return JSON_TYPE_ERROR;
}
return c;
case ']':
if(s == '[' && v != ',') {
pop(state);
} else {
state->error = JSON_ERROR_UNEXPECTED_END_OF_ARRAY;
return JSON_TYPE_ERROR;
}
return c;
case ':':
if(s == '{' && v == 'N') {
modify(state, ':');
state->vtype = 0;
} else {
state->error = JSON_ERROR_SYNTAX;
return JSON_TYPE_ERROR;
}
return jsonparse_next(state);
case ',':
if(s == ':' && v != 0) {
modify(state, '{');
state->vtype = c;
} else if(s == '[') {
state->vtype = c;
} else {
state->error = JSON_ERROR_SYNTAX;
return JSON_TYPE_ERROR;
}
return c;
case '"':
if((s == 0 && v == 0) || s == '{' || s == '[' || s == ':') {
return atomic(state, c = (s == '{' ? JSON_TYPE_PAIR_NAME : c));
} else {
state->error = JSON_ERROR_UNEXPECTED_STRING;
return JSON_TYPE_ERROR;
}
return c;
case '[':
if((s == 0 && v == 0) || s == '[' || s == ':') {
push(state, c);
} else {
state->error = JSON_ERROR_UNEXPECTED_ARRAY;
return JSON_TYPE_ERROR;
}
return c;
case 0:
if(v == 0 || state->depth > 0) {
state->error = JSON_ERROR_SYNTAX;
}
return JSON_TYPE_ERROR;
default:
if(s == 0 || s == ':' || s == '[') {
if (v != 0 && v != ',') {
state->error = JSON_ERROR_SYNTAX;
return JSON_TYPE_ERROR;
}
if(c == '-' || (c <= '9' && c >= '0')) {
return atomic(state, JSON_TYPE_NUMBER);
} else if(c == 'n') {
return atomic(state, JSON_TYPE_NULL);
} else if(c == 't') {
return atomic(state, JSON_TYPE_TRUE);
} else if(c == 'f') {
return atomic(state, JSON_TYPE_FALSE);
} else {
state->error = JSON_ERROR_SYNTAX;
return JSON_TYPE_ERROR;
}
} else if(s == '{') {
state->error = JSON_ERROR_SYNTAX;
return JSON_TYPE_ERROR;
}
}
return 0;
}

static Image *ReadMVGImage(const ImageInfo *image_info,ExceptionInfo *exception)
{
#define BoundingBox  "viewbox"
DrawInfo
*draw_info;
Image
*image;
MagickBooleanType
status;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickSignature);
if (image_info->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
image_info->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickSignature);
image=AcquireImage(image_info);
status=OpenBlob(image_info,image,ReadBinaryBlobMode,exception);
if (status == MagickFalse)
{
image=DestroyImageList(image);
return((Image *) NULL);
}
if ((image->columns == 0) || (image->rows == 0))
{
char
primitive[MaxTextExtent];
register char
*p;
SegmentInfo
bounds;
while (ReadBlobString(image,primitive) != (char *) NULL)
{
for (p=primitive; (*p == ' ') || (*p == '\t'); p++) ;
if (LocaleNCompare(BoundingBox,p,strlen(BoundingBox)) != 0)
continue;
(void) sscanf(p,"viewbox %lf %lf %lf %lf",&bounds.x1,&bounds.y1,
&bounds.x2,&bounds.y2);
image->columns=(size_t) floor((bounds.x2-bounds.x1)+0.5);
image->rows=(size_t) floor((bounds.y2-bounds.y1)+0.5);
break;
}
}
if ((image->columns == 0) || (image->rows == 0))
ThrowReaderException(OptionError,"MustSpecifyImageSize");
draw_info=CloneDrawInfo(image_info,(DrawInfo *) NULL);
draw_info->affine.sx=image->x_resolution == 0.0 ? 1.0 : image->x_resolution/
96.0;
draw_info->affine.sy=image->y_resolution == 0.0 ? 1.0 : image->y_resolution/
96.0;
image->columns=(size_t) (draw_info->affine.sx*image->columns);
image->rows=(size_t) (draw_info->affine.sy*image->rows);
status=SetImageExtent(image,image->columns,image->rows);
if (status == MagickFalse)
{
InheritException(exception,&image->exception);
return(DestroyImageList(image));
}
if (SetImageBackgroundColor(image) == MagickFalse)
{
InheritException(exception,&image->exception);
image=DestroyImageList(image);
return((Image *) NULL);
}
if (GetBlobStreamData(image) == (unsigned char *) NULL)
draw_info->primitive=FileToString(image->filename,~0UL,exception);
else
{
draw_info->primitive=(char *) AcquireMagickMemory(GetBlobSize(image)+1);
if (draw_info->primitive != (char *) NULL)
{
CopyMagickMemory(draw_info->primitive,GetBlobStreamData(image),
GetBlobSize(image));
draw_info->primitive[GetBlobSize(image)]='\0';
}
}
if (draw_info->primitive == (char *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
(void) DrawImage(image,draw_info);
(void) SetImageArtifact(image,"MVG",draw_info->primitive);
draw_info=DestroyDrawInfo(draw_info);
(void) CloseBlob(image);
return(GetFirstImageInList(image));
}

static char *
convert_to_decimal (mpn_t a, size_t extra_zeroes)
{
mp_limb_t *a_ptr = a.limbs;
size_t a_len = a.nlimbs;
size_t c_len = 9 * ((size_t)(a_len * (GMP_LIMB_BITS * 0.03345f)) + 1);
char *c_ptr = (char *) malloc (xsum (c_len, extra_zeroes));
if (c_ptr != NULL)
{
char *d_ptr = c_ptr;
for (; extra_zeroes > 0; extra_zeroes--)
*d_ptr++ = '0';
while (a_len > 0)
{
mp_limb_t remainder = 0;
mp_limb_t *ptr = a_ptr + a_len;
size_t count;
for (count = a_len; count > 0; count--)
{
mp_twolimb_t num =
((mp_twolimb_t) remainder << GMP_LIMB_BITS) | *--ptr;
*ptr = num / 1000000000;
remainder = num % 1000000000;
}
for (count = 9; count > 0; count--)
{
*d_ptr++ = '0' + (remainder % 10);
remainder = remainder / 10;
}
if (a_ptr[a_len - 1] == 0)
a_len--;
}
while (d_ptr > c_ptr && d_ptr[-1] == '0')
d_ptr--;
if (d_ptr == c_ptr)
*d_ptr++ = '0';
*d_ptr = '\0';
}
return c_ptr;
}

static int check_policy(X509_STORE_CTX *ctx)
{
int ret;
if (ctx->parent)
return 1;
if (ctx->bare_ta_signed && !sk_X509_push(ctx->chain, NULL))
goto memerr;
ret = X509_policy_check(&ctx->tree, &ctx->explicit_policy, ctx->chain,
ctx->param->policies, ctx->param->flags);
if (ctx->bare_ta_signed)
(void)sk_X509_pop(ctx->chain);
if (ret == X509_PCY_TREE_INTERNAL)
goto memerr;
if (ret == X509_PCY_TREE_INVALID) {
int i;
for (i = 1; i < sk_X509_num(ctx->chain); i++) {
X509 *x = sk_X509_value(ctx->chain, i);
CB_FAIL_IF((x->ex_flags & EXFLAG_INVALID_POLICY) != 0,
ctx, x, i, X509_V_ERR_INVALID_POLICY_EXTENSION);
}
return 1;
}
if (ret == X509_PCY_TREE_FAILURE) {
ctx->current_cert = NULL;
ctx->error = X509_V_ERR_NO_EXPLICIT_POLICY;
return ctx->verify_cb(0, ctx);
}
if (ret != X509_PCY_TREE_VALID) {
ERR_raise(ERR_LIB_X509, ERR_R_INTERNAL_ERROR);
return 0;
}
if ((ctx->param->flags & X509_V_FLAG_NOTIFY_POLICY) != 0) {
ctx->current_cert = NULL;
if (!ctx->verify_cb(2, ctx))
return 0;
}
return 1;
memerr:
ERR_raise(ERR_LIB_X509, ERR_R_MALLOC_FAILURE);
ctx->error = X509_V_ERR_OUT_OF_MEM;
return -1;
}

static ut8 read_module_referenced_functions(RFlirtModule *module, RBuffer *b) {
int i, j;
ut8 number_of_referenced_functions;
ut32 ref_function_name_length;
RFlirtFunction *ref_function = NULL;
module->referenced_functions = r_list_new ();
if (version >= 8) { number_of_referenced_functions = read_byte (b); if (buf_eof || buf_err) {
goto err_exit;
}
} else { number_of_referenced_functions = 1;
}
for (i = 0; i < number_of_referenced_functions; i++) {
ref_function = R_NEW0 (RFlirtFunction);
if (!ref_function) {
goto err_exit;
}
if (version >= 9) {
ref_function->offset = read_multiple_bytes (b);
if (buf_eof || buf_err) {
goto err_exit;
}
} else {
ref_function->offset = read_max_2_bytes (b);
if (buf_eof || buf_err) {
goto err_exit;
}
}
ref_function_name_length = read_byte (b);
if (buf_eof || buf_err) {
goto err_exit;
}
if (!ref_function_name_length) {
ref_function_name_length = read_multiple_bytes (b); if (buf_eof || buf_err) {
goto err_exit;
}
}
if ((int) ref_function_name_length < 0 || ref_function_name_length > R_FLIRT_NAME_MAX) {
goto err_exit;
}
for (j = 0; j < ref_function_name_length; j++) {
ref_function->name[j] = read_byte (b);
if (buf_eof || buf_err) {
goto err_exit;
}
}
if (!ref_function->name[ref_function_name_length]) {
ref_function->negative_offset = true;
} else {
ref_function->name[ref_function_name_length] = '\0';
}
r_list_append (module->referenced_functions, ref_function);
#if DEBUG
eprintf ("(REF: %04X: %s)\n", ref_function->offset, ref_function->name);
#endif
}
return true;
err_exit:
free (ref_function);
return false;
}

Elf32_Sym const *PackLinuxElf32::elf_lookup(char const *name) const
{
if (hashtab && dynsym && dynstr) {
unsigned const nbucket = get_te32(&hashtab[0]);
unsigned const *const buckets = &hashtab[2];
unsigned const *const chains = &buckets[nbucket];
unsigned const m = elf_hash(name) % nbucket;
unsigned si;
for (si= get_te32(&buckets[m]); 0!=si; si= get_te32(&chains[si])) {
char const *const p= get_dynsym_name(si, (unsigned)-1);
if (0==strcmp(name, p)) {
return &dynsym[si];
}
}
}
if (gashtab && dynsym && dynstr) {
unsigned const n_bucket = get_te32(&gashtab[0]);
unsigned const symbias  = get_te32(&gashtab[1]);
unsigned const n_bitmask = get_te32(&gashtab[2]);
unsigned const gnu_shift = get_te32(&gashtab[3]);
unsigned const *const bitmask = &gashtab[4];
unsigned const *const buckets = &bitmask[n_bitmask];
unsigned const *const hasharr = &buckets[n_bucket];
unsigned const h = gnu_hash(name);
unsigned const hbit1 = 037& h;
unsigned const hbit2 = 037& (h>>gnu_shift);
unsigned const w = get_te32(&bitmask[(n_bitmask -1) & (h>>5)]);
if (1& (w>>hbit1) & (w>>hbit2)) {
unsigned bucket = get_te32(&buckets[h % n_bucket]);
if (n_bucket <= bucket) {
char msg[80]; snprintf(msg, sizeof(msg),
"bad DT_GNU_HASH n_bucket{%#x} <= buckets[%d]{%#x}\n",
n_bucket, h % n_bucket, bucket);
throwCantPack(msg);
}
if (0!=bucket) {
Elf32_Sym const *dsp = &dynsym[bucket];
unsigned const *hp = &hasharr[bucket - symbias];
do if (0==((h ^ get_te32(hp))>>1)) {
unsigned st_name = get_te32(&dsp->st_name);
char const *const p = get_str_name(st_name, (unsigned)-1);
if (0==strcmp(name, p)) {
return dsp;
}
} while (++dsp, 0==(1u& get_te32(hp++)));
}
}
}
return 0;
}

void add_pair(const uint8_t *addr1,const uint8_t *addr2,size_t addrlen,uint64_t val){
uint8_t addr[32];
memset(addr,0,sizeof(addr));
for(size_t i=0;i<addrlen*8;i++){
if(iptreet<uint64_t,32>::bit(addr1,i)) iptreet<uint64_t,32>::setbit(addr,i*2);
if(iptreet<uint64_t,32>::bit(addr2,i)) iptreet<uint64_t,32>::setbit(addr,i*2+1);
}
add(addr,addrlen*2,val); 
}

static Jsi_RC jsi_ArrayFillCmd(Jsi_Interp *interp, Jsi_Value *args, Jsi_Value *_this,Jsi_Value **ret, Jsi_Func *funcPtr) {
if (_this->vt != JSI_VT_OBJECT || !Jsi_ObjIsArray(interp, _this->d.obj)) 
return Jsi_LogError("expected array object");
Jsi_RC rc = JSI_OK;
int istart = 0, iend, n, nsiz;
Jsi_Number nstart = 0, nend = 0;     Jsi_Value *value = Jsi_ValueArrayIndex(interp, args, 0),
*start = Jsi_ValueArrayIndex(interp, args, 1),
*end = Jsi_ValueArrayIndex(interp, args, 2);
Jsi_Obj *obj = _this->d.obj;
n = jsi_SizeOfArray(interp, obj);
if (start && Jsi_GetNumberFromValue(interp, start, &nstart) == JSI_OK) {
istart = (int)nstart;
if (istart > n)
goto bail;
if (istart < 0)
istart = (n+istart);
if (istart<0)
goto bail;
}
if (n == 0) {
goto bail;
}
iend = n-1;
if (end && Jsi_GetNumberFromValue(interp,end, &nend) == JSI_OK) {
iend = (int) nend;
if (iend >= n)
iend = n;
if (iend < 0)
iend = (n+iend);
if (iend<0)
goto bail;
}
nsiz = iend-istart+1;
if (nsiz<=0)
goto bail;
int i;
for (i = istart; i <= iend; i++)
{
if (obj->arr[i])
Jsi_ValueCopy(interp, obj->arr[i], value);
else
obj->arr[i] = Jsi_ValueDup(interp, value);
}
bail:
if (_this != *ret)
Jsi_ValueMove(interp, *ret, _this);
return rc;
}

