static gnrc_pktsnip_t *_iphc_encode(gnrc_pktsnip_t *pkt,
const gnrc_netif_hdr_t *netif_hdr,
gnrc_netif_t *iface)
{
assert(pkt != NULL);
uint8_t *iphc_hdr;
gnrc_pktsnip_t *dispatch, *ptr = pkt->next;
size_t dispatch_size = 0;
uint16_t inline_pos = 0;
uint8_t nh;
dispatch = NULL;    
while ((ptr != NULL) && _compressible(ptr)) {
gnrc_pktsnip_t *tmp = gnrc_pktbuf_start_write(ptr);
if (tmp == NULL) {
DEBUG("6lo iphc: unable to write protect compressible header\n");
return NULL;
}
ptr = tmp;
if (dispatch == NULL) {
pkt->next = ptr;    
}
else {
dispatch->next = ptr;
}
if (ptr->type == GNRC_NETTYPE_UNDEF) {
dispatch_size += sizeof(udp_hdr_t);
break;  
}
else {
dispatch_size += ptr->size;
}
dispatch = ptr; 
ptr = ptr->next;
}
assert(dispatch_size > 0);
dispatch = gnrc_pktbuf_add(NULL, NULL, dispatch_size + 1,
GNRC_NETTYPE_SIXLOWPAN);
if (dispatch == NULL) {
DEBUG("6lo iphc: error allocating dispatch space\n");
return NULL;
}
iphc_hdr = dispatch->data;
inline_pos = _iphc_ipv6_encode(pkt, netif_hdr, iface, iphc_hdr);
if (inline_pos == 0) {
DEBUG("6lo iphc: error encoding IPv6 header\n");
gnrc_pktbuf_release(dispatch);
return NULL;
}
nh = ((ipv6_hdr_t *)pkt->next->data)->nh;
#ifdef MODULE_GNRC_SIXLOWPAN_IPHC_NHC
while (_compressible_nh(nh)) {
ssize_t local_pos = 0;
switch (nh) {
case PROTNUM_UDP:
local_pos = _nhc_udp_encode_snip(pkt, &iphc_hdr[inline_pos]);
nh = PROTNUM_RESERVED;
break;
case PROTNUM_IPV6: {    
local_pos = _nhc_ipv6_encode_snip(pkt, netif_hdr, iface,
&iphc_hdr[inline_pos], &nh);
break;
}
case PROTNUM_IPV6_EXT_HOPOPT:
case PROTNUM_IPV6_EXT_RH:
case PROTNUM_IPV6_EXT_FRAG:
case PROTNUM_IPV6_EXT_DST:
case PROTNUM_IPV6_EXT_MOB:
local_pos = _nhc_ipv6_ext_encode_snip(pkt,
&iphc_hdr[inline_pos],
&nh);
if (local_pos == 0) {
nh = PROTNUM_RESERVED;
}
break;
default:
nh = PROTNUM_RESERVED;
break;
}
if (local_pos < 0) {
DEBUG("6lo iphc: error on compressing next header\n");
gnrc_pktbuf_release(dispatch);
return NULL;
}
inline_pos += local_pos;
}
#endif
gnrc_pktbuf_realloc_data(dispatch, (size_t)inline_pos);
pkt = gnrc_pktbuf_remove_snip(pkt, pkt->next);
dispatch->next = pkt->next;
pkt->next = dispatch;
return pkt;
}

Status ModelWeights::Initialize(OpKernelContext* const context) {
OpInputList sparse_indices_inputs;
TF_RETURN_IF_ERROR(
context->input_list("sparse_indices", &sparse_indices_inputs));
OpInputList sparse_weights_inputs;
TF_RETURN_IF_ERROR(
context->input_list("sparse_weights", &sparse_weights_inputs));
OpInputList dense_weights_inputs;
TF_RETURN_IF_ERROR(
context->input_list("dense_weights", &dense_weights_inputs));
OpOutputList sparse_weights_outputs;
TF_RETURN_IF_ERROR(context->output_list("out_delta_sparse_weights",
&sparse_weights_outputs));
OpOutputList dense_weights_outputs;
TF_RETURN_IF_ERROR(
context->output_list("out_delta_dense_weights", &dense_weights_outputs));
for (int i = 0; i < sparse_weights_inputs.size(); ++i) {
Tensor* delta_t;
TF_RETURN_IF_ERROR(sparse_weights_outputs.allocate(
i, sparse_weights_inputs[i].shape(), &delta_t));
auto deltas = delta_t->shaped<float, 2>({1, delta_t->NumElements()});
deltas.setZero();
sparse_weights_.emplace_back(FeatureWeightsSparseStorage{
sparse_indices_inputs[i].flat<int64>(),
sparse_weights_inputs[i].shaped<float, 2>(
{1, sparse_weights_inputs[i].NumElements()}),
deltas});
}
const auto initialize_weights =
[&](const OpInputList& weight_inputs, OpOutputList* const weight_outputs,
std::vector<FeatureWeightsDenseStorage>* const feature_weights) {
for (int i = 0; i < weight_inputs.size(); ++i) {
Tensor* delta_t;
TF_RETURN_IF_ERROR(
weight_outputs->allocate(i, weight_inputs[i].shape(), &delta_t));
auto deltas = delta_t->shaped<float, 2>({1, delta_t->NumElements()});
deltas.setZero();
feature_weights->emplace_back(FeatureWeightsDenseStorage{
weight_inputs[i].shaped<float, 2>(
{1, weight_inputs[i].NumElements()}),
deltas});
}
return Status::OK();
};
return initialize_weights(dense_weights_inputs, &dense_weights_outputs,
&dense_weights_);
}

PCRE_EXP_DEFN pcre * PCRE_CALL_CONVENTION
erts_pcre_compile2(const char *pattern, int options, int *errorcodeptr,
const char **errorptr, int *erroroffset, const unsigned char *tables)
#else
PCRE_EXP_DEFN pcre * PCRE_CALL_CONVENTION
pcre_compile2(const char *pattern, int options, int *errorcodeptr,
const char **errorptr, int *erroroffset, const unsigned char *tables)
#endif
#elif defined COMPILE_PCRE16
PCRE_EXP_DEFN pcre16 * PCRE_CALL_CONVENTION
pcre16_compile2(PCRE_SPTR16 pattern, int options, int *errorcodeptr,
const char **errorptr, int *erroroffset, const unsigned char *tables)
#elif defined COMPILE_PCRE32
PCRE_EXP_DEFN pcre32 * PCRE_CALL_CONVENTION
pcre32_compile2(PCRE_SPTR32 pattern, int options, int *errorcodeptr,
const char **errorptr, int *erroroffset, const unsigned char *tables)
#endif
{
