{
pcre_uint32 c = 0;
int p = skipatstart + 18;
while (isdigit(ptr[p]))
{
if (c > PCRE_UINT32_MAX / 10 - 1) break;   
c = c*10 + ptr[p++] - CHAR_0;
}
if (ptr[p++] != CHAR_RIGHT_PARENTHESIS) break;
if (c < limit_recursion)
{
limit_recursion = c;
cd->external_flags |= PCRE_RLSET;
}
skipatstart = p;
continue;
}
