DataType GetDataTypeFromNodeOrProps(const NodeDef& node,
const GraphProperties& properties) {
DataType dtype = DT_INVALID;
if (node.attr().count("T") == 1) {
dtype = node.attr().at("T").type();
} else if (node.attr().count("dtype") == 1) {
dtype = node.attr().at("dtype").type();
} else if (IsLogicalOr(node) || IsLogicalAnd(node)) {
dtype = DT_BOOL;
} else {
auto output_props = properties.GetOutputProperties(node.name());
if (!output_props.empty()) {
dtype = output_props[0].dtype();
}
}
return dtype;
}
bool IsValidConstShapeForMulConvPushDown(
const string& data_format, const TensorShapeProto& filter_shape,
const TensorShapeProto& mul_const_input_shape) {
if (mul_const_input_shape.dim_size() <=
static_cast<int>(data_format.size()) &&
TensorShape(mul_const_input_shape).num_elements() == 1) {
return true;
}
if (data_format == "NHWC" || data_format == "NDHWC") {
TensorShapeProto new_filter_shape;
if (!ShapeAfterBroadcast(filter_shape, mul_const_input_shape,
&new_filter_shape)) {
return false;
}
if (!ShapesSymbolicallyEqual(filter_shape, new_filter_shape)) {
return false;
}
for (int i = 0; i < mul_const_input_shape.dim_size() - 1; ++i) {
if (mul_const_input_shape.dim(i).size() > 1) return false;
}
return true;
} else if (data_format == "NCHW" || data_format == "NCDHW") {
return false;
}
return false;
}
}  
Status ConstantFolding::CreateNodeDef(const string& name,
const TensorValue& tensor, NodeDef* node,
size_t original_size) {
node->set_name(name);
node->set_op("Const");
AttrValue attr_type;
attr_type.set_type(tensor->dtype());
node->mutable_attr()->insert({"dtype", attr_type});
AttrValue attr_tensor;
TensorProto* t = attr_tensor.mutable_tensor();
bool optimized = false;
size_t encoded_size;
if (tensor->NumElements() > 4) {
#define POPULATE_TENSOR_PROTO(tensor, t, TYPE, FIELDTYPE)                      \
{                                                                            \
const auto* val_ptr = tensor->flat<TYPE>().data();                         \
auto last = *val_ptr;                                                      \
int64_t last_index = 0;                                                    \
for (int64_t i = 0; i < tensor->NumElements(); ++i) {                      \
TYPE cur = *val_ptr++;                                                   \
if (PackedValuesNotEqual(cur, last)) {                                   \
last = cur;                                                            \
last_index = i;                                                        \
}                                                                        \
}                                                                          \
encoded_size = (last_index + 1) * sizeof(FIELDTYPE);                       \
if (encoded_size < kint32max) {                                            \
optimized = true;                                                        \
t->mutable_##FIELDTYPE##_val()->Reserve(last_index + 1);                 \
const auto* src_ptr = tensor->flat<TYPE>().data();                       \
auto* dst_ptr =                                                          \
t->mutable_##FIELDTYPE##_val()->AddNAlreadyReserved(last_index + 1); \
std::copy(src_ptr, src_ptr + last_index + 1, dst_ptr);                   \
}                                                                          \
}                                                                            \
break
switch (tensor->dtype()) {
case DT_FLOAT:
POPULATE_TENSOR_PROTO(tensor, t, float, float);
case DT_DOUBLE:
POPULATE_TENSOR_PROTO(tensor, t, double, double);
case DT_INT64:
POPULATE_TENSOR_PROTO(tensor, t, int64_t, int64);
case DT_UINT64:
POPULATE_TENSOR_PROTO(tensor, t, uint64, uint64);
case DT_INT32:
POPULATE_TENSOR_PROTO(tensor, t, int32_t, int);
case DT_UINT32:
POPULATE_TENSOR_PROTO(tensor, t, uint32, uint32);
case DT_INT16:
POPULATE_TENSOR_PROTO(tensor, t, int16_t, int);
case DT_UINT16:
POPULATE_TENSOR_PROTO(tensor, t, uint16, int);
case DT_INT8:
POPULATE_TENSOR_PROTO(tensor, t, int8_t, int);
case DT_UINT8:
POPULATE_TENSOR_PROTO(tensor, t, uint8, int);
case DT_BOOL:
POPULATE_TENSOR_PROTO(tensor, t, bool, bool);
default:
break;
}
}
if (optimized) {
t->set_dtype(tensor->dtype());
tensor->shape().AsProto(t->mutable_tensor_shape());
} else {
tensor->AsProtoTensorContent(t);
encoded_size = t->tensor_content().size();
}
node->mutable_attr()->insert({"value", attr_tensor});
if (encoded_size > original_size && encoded_size >= kMaxConstantSize) {
return errors::InvalidArgument(
strings::StrCat("Can't fold ", name, ", its size would be too large (",
encoded_size, " >= ", kMaxConstantSize, " bytes)"));
}
return Status::OK();
}
Status ConstantFolding::EvaluateNode(const NodeDef& node,
const TensorVector& inputs,
TensorVector* output) const {
return ::tensorflow::grappler::EvaluateNode(node, inputs, cpu_device_,
resource_mgr_.get(), output);
}
Status ConstantFolding::EvaluateOneFoldable(const NodeDef& node,
std::vector<NodeDef>* outputs,
bool* result_too_large) {
TensorVector inputs;
TensorVector output_tensors;
auto inputs_cleanup = gtl::MakeCleanup([&inputs, &output_tensors] {
for (const auto& input : inputs) {
delete input.tensor;
}
for (const auto& output : output_tensors) {
if (output.tensor) {
delete output.tensor;
}
}
});
size_t total_inputs_size = 0;
for (const auto& input : node.input()) {
const TensorId input_tensor = ParseTensorName(input);
if (input_tensor.index() < 0) {
break;
}
const NodeDef* input_node = node_map_->GetNode(input);
if (!IsReallyConstant(*input_node)) {
return Status(error::INVALID_ARGUMENT,
strings::StrCat("Can't fold ", node.name(), ", its ", input,
" isn't constant"));
}
TF_RETURN_IF_ERROR(CheckAttrExists(*input_node, "value"));
const TensorProto& raw_val = input_node->attr().at("value").tensor();
if (raw_val.dtype() == DT_INVALID) {
return Status(
error::INVALID_ARGUMENT,
strings::StrCat("A tensor in the input node, with TensorId of ",
input_tensor.ToString(),
" has a dtype of DT_INVALID."));
}
Tensor* value = new Tensor(raw_val.dtype(), raw_val.tensor_shape());
if (!value->FromProto(raw_val)) {
delete (value);
return errors::InvalidArgument("Unable to make Tensor from proto for ",
node.name(), " with shape ",
raw_val.tensor_shape().DebugString());
}
inputs.emplace_back(value);
total_inputs_size += value->TotalBytes();
}
TF_RETURN_IF_ERROR(EvaluateNode(node, inputs, &output_tensors));
if (output_tensors.empty()) {
return Status(error::INVALID_ARGUMENT, "Expected at least one output.");
}
outputs->resize(output_tensors.size());
for (size_t i = 0; i < output_tensors.size(); i++) {
string node_name = OptimizedNodeName(node, "-folded");
if (output_tensors.size() > 1) {
node_name = strings::StrCat(node_name, "-", i);
}
if (output_tensors[i].tensor) {
Status s = CreateNodeDef(node_name, output_tensors[i], &outputs->at(i),
total_inputs_size);
if (!s.ok()) {
*result_too_large = true;
return s;
}
} else {
outputs->at(i) = NodeDef();
}
}
return Status::OK();
}
Status ConstantFolding::FoldMergeNode(NodeDef* node, GraphDef* output_graph) {
for (int input_index = 0; input_index < node->input_size(); ++input_index) {
const auto& input = node->input(input_index);
if (IsControlInput(input)) {
continue;
}
NodeDef* input_node = node_map_->GetNode(input);
if (!IsReallyConstant(*input_node)) {
continue;
}
bool valid_input = true;
for (const string& fanin_of_input : input_node->input()) {
if (IsControlInput(fanin_of_input)) {
valid_input = false;
break;
}
}
if (!valid_input) {
continue;
}
string const_out_name = OptimizedNodeName(*node, "_const");
string const_index_name = OptimizedNodeName(*node, "_index");
if (node_map_->GetNode(const_out_name) ||
node_map_->GetNode(const_index_name)) {
return errors::AlreadyExists(
strings::StrCat(const_out_name, " or ", const_index_name,
" already present in the graph"));
}
NodeDef* const_out = output_graph->add_node();
*const_out = *input_node;
const_out->set_name(const_out_name);
const_out->set_device(node->device());
*const_out->add_input() = AsControlDependency(*node);
node_map_->AddNode(const_out->name(), const_out);
node_map_->AddOutput(node->name(), const_out->name());
NodeDef* const_index = output_graph->add_node();
const_index->set_op("Const");
Tensor index(DT_INT32, TensorShape({}));
index.flat<int32>()(0) = input_index;
(*const_index->mutable_attr())["dtype"].set_type(DT_INT32);
index.AsProtoTensorContent(
(*const_index->mutable_attr())["value"].mutable_tensor());
const_index->set_name(const_index_name);
const_index->set_device(node->device());
*const_index->add_input() = AsControlDependency(*node);
node_map_->AddNode(const_index->name(), const_index);
node_map_->AddOutput(node->name(), const_index->name());
auto outputs = node_map_->GetOutputs(node->name());
for (NodeDef* output : outputs) {
for (int i = 0; i < output->input_size(); i++) {
int port;
string node_name = ParseNodeName(output->input(i), &port);
if (node_name == node->name()) {
if (port == 0) {
*output->mutable_input(i) = const_out->name();
node_map_->AddOutput(const_out->name(), output->name());
} else if (port == 1) {
*output->mutable_input(i) = const_index->name();
node_map_->AddOutput(const_index->name(), output->name());
} else {
}
}
}
}
return Status::OK();
}
return Status::OK();
}
Status ConstantFolding::FoldNode(NodeDef* node, GraphDef* output_graph,
bool* result_too_large) {
*result_too_large = false;
if (IsMerge(*node)) {
return FoldMergeNode(node, output_graph);
}
std::vector<NodeDef> const_nodes;
TF_RETURN_IF_ERROR(
EvaluateOneFoldable(*node, &const_nodes, result_too_large));
VLOG(2) << "Folded node: " << SummarizeNodeDef(*node);
NodeDef* constant_output = nullptr;
for (int i = 0, end = const_nodes.size(); i < end; i++) {
NodeDef* const_node = &const_nodes[i];
VLOG(3) << "Generated constant node: " << SummarizeNodeDef(*const_node);
if (const_node->name().empty()) {
continue;
}
const auto is_duplicate_control_input = [&](const string& input) -> bool {
auto it = absl::c_find(const_node->input(), input);
return it != const_node->input().end();
};
for (const string& input : node->input()) {
if (IsControlInput(input)) {
if (!is_duplicate_control_input(input)) {
*const_node->add_input() = input;
}
}
if (!IsControlInput(input)) {
NodeDef* input_node = node_map_->GetNode(input);
for (const string& fanin_of_input : input_node->input()) {
if (!is_duplicate_control_input(fanin_of_input)) {
*const_node->add_input() = fanin_of_input;
}
}
}
}
if (const_nodes.size() == 1) {
node->set_op("Const");
node_map_->RemoveInputs(node->name());
node->clear_input();
*node->mutable_input() = const_node->input();
for (const auto& input : node->input()) {
node_map_->AddOutput(NodeName(input), node->name());
}
*node->mutable_attr() = const_node->attr();
break;
} else {
if (node_map_->GetNode(const_node->name())) {
return errors::AlreadyExists(strings::StrCat(
const_node->name(), " already present in the graph"));
}
NodeDef* added_node = output_graph->add_node();
*added_node = *const_node;
added_node->set_device(node->device());
node_map_->AddNode(added_node->name(), added_node);
for (const auto& input : added_node->input()) {
node_map_->AddOutput(NodeName(input), added_node->name());
}
constant_output = added_node;
}
}
if (const_nodes.size() > 1) {
auto outputs = node_map_->GetOutputs(node->name());
for (NodeDef* output : outputs) {
for (int i = 0; i < output->input_size(); i++) {
int port;
string node_name = ParseNodeName(output->input(i), &port);
if (node_name == node->name()) {
if (port < 0) {
if (constant_output != nullptr) {
node_map_->UpdateInput(node_name, NodeName(output->input(i)),
constant_output->name());
*output->mutable_input(i) = AsControlDependency(*constant_output);
}
} else if (port < static_cast<int>(const_nodes.size()) &&
!const_nodes[port].name().empty()) {
node_map_->UpdateInput(output->name(), NodeName(output->input(i)),
const_nodes[port].name());
*output->mutable_input(i) = const_nodes[port].name();
} else {
VLOG(3) << "Preserving edge from " << node->name() << ":" << port
<< "[" << node->op() << "] to " << output->name() << ":"
<< i << "[" << output->op() << "]";
}
}
}
}
outputs = node_map_->GetOutputs(node->name());
if (outputs.empty() && has_fetch_ &&
nodes_to_preserve_.find(node->name()) == nodes_to_preserve_.end()) {
node_map_->RemoveInputs(node->name());
node->clear_input();
}
}
return Status::OK();
}
Status ConstantFolding::FoldGraph(
const GraphProperties& properties, GraphDef* optimized_graph,
absl::flat_hash_set<string>* nodes_to_not_simplify) {
absl::flat_hash_set<string> processed_nodes;
std::deque<NodeDef*> queue;
for (int i = 0; i < graph_->node_size(); i++) {
const NodeDef& node = graph_->node(i);
if (IsFoldable(node, &properties) &&
!nodes_to_not_simplify->count(node.name())) {
queue.push_back(graph_->mutable_node(i));
}
}
while (!queue.empty()) {
NodeDef* node = queue.front();
queue.pop_front();
if (processed_nodes.count(node->name())) {
continue;
}
std::vector<NodeDef*> fanout =
node_map_->GetOutputsOrderedByNodeName(node->name());
bool result_too_large = false;
Status s = FoldNode(node, optimized_graph, &result_too_large);
processed_nodes.insert(node->name());
if (!s.ok()) {
VLOG(1) << "Failed to fold node " << node->DebugString()
<< "\nError message: " << s;
if (result_too_large) {
nodes_to_not_simplify->emplace(node->name());
}
} else {
for (auto& fanout_node : fanout) {
if (IsFoldable(*fanout_node, &properties) &&
!nodes_to_not_simplify->count(fanout_node->name())) {
queue.push_back(fanout_node);
}
}
}
}
std::vector<int> nodes_to_delete;
for (int i = 0; i < optimized_graph->node_size(); i++) {
const auto& fanout = node_map_->GetOutputs(optimized_graph->node(i).name());
if (fanout.empty()) nodes_to_delete.push_back(i);
}
EraseNodesFromGraph(std::move(nodes_to_delete), optimized_graph);
for (int i = 0; i < graph_->node_size(); ++i) {
NodeDef* node = graph_->mutable_node(i);
const auto& fanout = node_map_->GetOutputs(node->name());
if (!fanout.empty() || !has_fetch_ ||
nodes_to_preserve_.find(node->name()) != nodes_to_preserve_.end()) {
*(optimized_graph->add_node()) = std::move(*node);
}
}
return Status::OK();
}
bool ConstantFolding::IsSimplifiableReshape(
const NodeDef& node, const GraphProperties& properties) const {
if (!IsReshape(node)) {
return false;
}
CHECK_LE(2, node.input_size());
const NodeDef* new_shape = node_map_->GetNode(node.input(1));
if (!IsReallyConstant(*new_shape)) {
return false;
}
TensorVector outputs;
auto outputs_cleanup = gtl::MakeCleanup([&outputs] {
for (const auto& output : outputs) {
delete output.tensor;
}
});
Status s = EvaluateNode(*new_shape, TensorVector(), &outputs);
if (!s.ok()) {
return false;
}
CHECK_EQ(1, outputs.size());
const std::vector<OpInfo::TensorProperties>& props =
properties.GetInputProperties(node.name());
if (props.empty()) {
return false;
}
const OpInfo::TensorProperties& prop = props[0];
if (prop.dtype() == DT_INVALID) {
return false;
}
const PartialTensorShape shape(prop.shape());
if (!shape.IsFullyDefined()) {
return false;
}
PartialTensorShape new_dims;
if (outputs[0]->dtype() == DT_INT32) {
std::vector<int32> shp;
for (int i = 0; i < outputs[0]->NumElements(); ++i) {
int32_t dim = outputs[0]->flat<int32>()(i);
shp.push_back(dim);
}
TF_CHECK_OK(TensorShapeUtils::MakeShape(shp, &new_dims));
} else {
std::vector<int64_t> shp;
for (int i = 0; i < outputs[0]->NumElements(); ++i) {
int64_t dim = outputs[0]->flat<int64_t>()(i);
shp.push_back(dim);
}
TF_CHECK_OK(TensorShapeUtils::MakeShape(shp, &new_dims));
}
return shape.IsCompatibleWith(new_dims);
}
#define IS_VALUE_CASE(DTYPE, VALUE)                   \
case DTYPE:                                         \
return AllValuesAre<EnumToDataType<DTYPE>::Type>( \
node.attr().at("value").tensor(), EnumToDataType<DTYPE>::Type(VALUE))
#define IS_ONES_CASE(TYPE) IS_VALUE_CASE(TYPE, 1)
#define IS_ZEROS_CASE(TYPE) IS_VALUE_CASE(TYPE, 0)
bool ConstantFolding::IsOnes(const NodeDef& node) const {
if (feed_nodes_.find(node.name()) != feed_nodes_.end()) {
return false;
}
if (IsOnesLike(node)) return true;
if (IsZerosLike(node)) return false;
if (node.op() == "Fill") {
NodeDef* values = node_map_->GetNode(NodeName(node.input(1)));
return values != nullptr && IsOnes(*values);
}
if (node.op() != "Const") return false;
if (node.attr().count("dtype") == 0) return false;
const auto dtype = node.attr().at("dtype").type();
switch (dtype) {
IS_ONES_CASE(DT_BOOL);
IS_ONES_CASE(DT_HALF);
IS_ONES_CASE(DT_BFLOAT16);
IS_ONES_CASE(DT_FLOAT);
IS_ONES_CASE(DT_DOUBLE);
IS_ONES_CASE(DT_COMPLEX64);
IS_ONES_CASE(DT_COMPLEX128);
IS_ONES_CASE(DT_UINT8);
IS_ONES_CASE(DT_INT8);
IS_ONES_CASE(DT_UINT16);
IS_ONES_CASE(DT_INT16);
IS_ONES_CASE(DT_INT32);
IS_ONES_CASE(DT_INT64);
IS_ONES_CASE(DT_QINT32);
IS_ONES_CASE(DT_QINT16);
IS_ONES_CASE(DT_QUINT16);
IS_ONES_CASE(DT_QINT8);
IS_ONES_CASE(DT_QUINT8);
default:
VLOG(1) << "Unsupported type " << DataTypeString(dtype);
return false;
}
return false;
}

void PDFDoc::markObject (Object* obj, XRef *xRef, XRef *countRef, unsigned int numOffset, int oldRefNum, int newRefNum, std::set<Dict*> *alreadyMarkedDicts)
{
Array *array;
switch (obj->getType()) {
case objArray:
array = obj->getArray();
for (int i=0; i<array->getLength(); i++) {
Object obj1 = array->getNF(i).copy();
markObject(&obj1, xRef, countRef, numOffset, oldRefNum, newRefNum);
}
break;
case objDict:
markDictionnary (obj->getDict(), xRef, countRef, numOffset, oldRefNum, newRefNum, alreadyMarkedDicts);
break;
case objStream: 
{
Stream *stream = obj->getStream();
markDictionnary (stream->getDict(), xRef, countRef, numOffset, oldRefNum, newRefNum, alreadyMarkedDicts);
}
break;
case objRef:
{
if (obj->getRef().num + (int) numOffset >= xRef->getNumObjects() || xRef->getEntry(obj->getRef().num + numOffset)->type == xrefEntryFree) {
if (getXRef()->getEntry(obj->getRef().num)->type == xrefEntryFree) {
return;            }
xRef->add(obj->getRef().num + numOffset, obj->getRef().gen, 0, true);
if (getXRef()->getEntry(obj->getRef().num)->type == xrefEntryCompressed) {
xRef->getEntry(obj->getRef().num + numOffset)->type = xrefEntryCompressed;
}
}
if (obj->getRef().num + (int) numOffset >= countRef->getNumObjects() || 
countRef->getEntry(obj->getRef().num + numOffset)->type == xrefEntryFree)
{
countRef->add(obj->getRef().num + numOffset, 1, 0, true);
} else {
XRefEntry *entry = countRef->getEntry(obj->getRef().num + numOffset);
entry->gen++;
if (entry->gen > 9)
break;
} 
Object obj1 = getXRef()->fetch(obj->getRef());
markObject(&obj1, xRef, countRef, numOffset, oldRefNum, newRefNum);
}
break;
default:
break;
}
}

static int
PyMemoTable_Set(PyMemoTable *self, PyObject *key, Py_ssize_t value)
{
PyMemoEntry *entry;
assert(key != NULL);
entry = _PyMemoTable_Lookup(self, key);
if (entry->me_key != NULL) {
entry->me_value = value;
return 0;
}
Py_INCREF(key);
entry->me_key = key;
entry->me_value = value;
self->mt_used++;
if (!(self->mt_used * 3 >= (self->mt_mask + 1) * 2))
return 0;
return _PyMemoTable_ResizeTable(self,
(self->mt_used > 50000 ? 2 : 4) * self->mt_used);
}

static GF_Err nhmldmx_send_sample(GF_Filter *filter, GF_NHMLDmxCtx *ctx)
{
GF_XMLNode *node, *childnode;
u64 sample_duration = 0;
char szMediaTemp[GF_MAX_PATH], szXmlFrom[1000], szXmlTo[1000];
char *szSubSampleName = ctx->is_dims ? "DIMSSubUnit" : "NHNTSubSample";
while ((node = (GF_XMLNode *) gf_list_enum(ctx->root->content, &ctx->current_child_idx))) {
u8 *data;
GF_FilterPacket *pck;
u32 j, dims_flags;
GF_FilterSAPType sap_type;
GF_XMLAttribute *att;
u64 dts=0;
GF_Err e=GF_OK;
s32 cts_offset;
u64 offset=0, byte_offset = GF_FILTER_NO_BO;
u32 nb_subsamples = 0;
Bool redundant_rap, append, has_subbs, first_subsample_is_first = GF_FALSE;
u32 compress_type;
char *base_data = NULL;
if (node->type) continue;
if (stricmp(node->name, ctx->is_dims ? "DIMSUnit" : "NHNTSample") ) continue;
strcpy(szMediaTemp, "");
strcpy(szXmlFrom, "");
strcpy(szXmlTo, "");
ctx->samp_buffer_size = 0;
dims_flags = 0;
append = GF_FALSE;
compress_type = ctx->compress_type;
sample_duration = 0;
redundant_rap = 0;
sap_type = ctx->has_sap ? GF_FILTER_SAP_NONE : GF_FILTER_SAP_1;
cts_offset = 0;
if (ctx->last_dts != GF_FILTER_NO_TS)
dts = ctx->last_dts;
else
dts = 0;
ctx->sample_num++;
j=0;
while ( (att = (GF_XMLAttribute *)gf_list_enum(node->attributes, &j))) {
if (!stricmp(att->name, "DTS") || !stricmp(att->name, "time")) {
u32 h, m, s, ms;
u64 dst_val;
if (strchr(att->value, ':') && sscanf(att->value, "%u:%u:%u.%u", &h, &m, &s, &ms) == 4) {
dts = (u64) ( (Double) ( ((h*3600.0 + m*60.0 + s)*1000 + ms) / 1000.0) * ctx->timescale );
} else if (sscanf(att->value, ""LLU, &dst_val)==1) {
dts = dst_val;
}
}
else if (!stricmp(att->name, "CTSOffset")) cts_offset = atoi(att->value);
else if (!stricmp(att->name, "isRAP") ) {
sap_type = (!stricmp(att->value, "yes")) ? GF_FILTER_SAP_1 : GF_FILTER_SAP_NONE;
}
else if (!stricmp(att->name, "isSyncShadow")) redundant_rap = !stricmp(att->value, "yes") ? 1 : 0;
else if (!stricmp(att->name, "SAPType") ) sap_type = atoi(att->value);
else if (!stricmp(att->name, "mediaOffset")) offset = (s64) atof(att->value) ;
else if (!stricmp(att->name, "dataLength")) ctx->samp_buffer_size = atoi(att->value);
else if (!stricmp(att->name, "mediaFile")) {
if (!strncmp(att->value, "data:", 5)) {
char *base = strstr(att->value, "base64,");
if (!base) {
GF_LOG(GF_LOG_WARNING, GF_LOG_PARSER, ("[NHMLDmx] Data encoding scheme not recognized in sample %d - skipping\n", ctx->sample_num));
} else {
base_data = att->value;
}
} else if (!strnicmp(att->value, "gmem:GF_LOG(GF_LOG_WARNING, GF_LOG_PARSER, ("[NHMLDmx] Invalid url %s for NHML import\n", att->value));
} else {
char *url = gf_url_concatenate(ctx->src_url, att->value);
if (!url) {
GF_LOG(GF_LOG_WARNING, GF_LOG_PARSER, ("[NHMLDmx] Failed to get full url for %s\n", att->value));
} else {
strncpy(szMediaTemp, url, GF_MAX_PATH-1);
szMediaTemp[GF_MAX_PATH-1] = 0;
gf_free(url);
}
}
}
else if (!stricmp(att->name, "xmlFrom")) strcpy(szXmlFrom, att->value);
else if (!stricmp(att->name, "xmlTo")) strcpy(szXmlTo, att->value);
else if (!stricmp(att->name, "is-Scene") && !stricmp(att->value, "yes"))
dims_flags |= GF_DIMS_UNIT_S;
else if (!stricmp(att->name, "is-RAP") && !stricmp(att->value, "yes")) {
dims_flags |= GF_DIMS_UNIT_M;
sap_type = GF_FILTER_SAP_1;
}
else if (!stricmp(att->name, "is-redundant") && !stricmp(att->value, "yes"))
dims_flags |= GF_DIMS_UNIT_I;
else if (!stricmp(att->name, "redundant-exit") && !stricmp(att->value, "yes"))
dims_flags |= GF_DIMS_UNIT_D;
else if (!stricmp(att->name, "priority") && !stricmp(att->value, "high"))
dims_flags |= GF_DIMS_UNIT_P;
else if (!stricmp(att->name, "compress") && !stricmp(att->value, "yes"))
dims_flags |= GF_DIMS_UNIT_C;
else if (!stricmp(att->name, "duration") )
sscanf(att->value, ""LLU, &sample_duration);
}
if (sap_type==GF_FILTER_SAP_1)
dims_flags |= GF_DIMS_UNIT_M;
if (ctx->is_dims)
compress_type = (dims_flags & GF_DIMS_UNIT_C) ? 2 : 0 ;
if (ctx->is_img) sample_duration = ctx->duration.den;
has_subbs = GF_FALSE;
j=0;
while ((childnode = (GF_XMLNode *) gf_list_enum(node->content, &j))) {
if (childnode->type) continue;
if (!stricmp(childnode->name, "BS")) {
has_subbs = GF_TRUE;
break;
}
}
if (strlen(szXmlFrom) && strlen(szXmlTo)) {
char *xml_file;
if (strlen(szMediaTemp)) xml_file = szMediaTemp;
else xml_file = ctx->szMedia;
ctx->samp_buffer_size = 0;
e = nhml_sample_from_xml(ctx, xml_file, szXmlFrom, szXmlTo);
} else if (ctx->is_dims && !strlen(szMediaTemp)) {
char *content = gf_xml_dom_serialize(node, GF_TRUE, GF_FALSE);
ctx->samp_buffer_size = 3 + (u32) strlen(content);
if (ctx->samp_buffer_alloc < ctx->samp_buffer_size) {
ctx->samp_buffer_alloc = ctx->samp_buffer_size;
ctx->samp_buffer = gf_realloc(ctx->samp_buffer, ctx->samp_buffer_size);
}
nhml_get_bs(&ctx->bs_w, ctx->samp_buffer, ctx->samp_buffer_size, GF_BITSTREAM_WRITE);
gf_bs_write_u16(ctx->bs_w, ctx->samp_buffer_size - 2);
gf_bs_write_u8(ctx->bs_w, (u8) dims_flags);
gf_bs_write_data(ctx->bs_w, content, (ctx->samp_buffer_size - 3));
gf_free(content);
if (ctx->last_dts == dts)
append = GF_TRUE;
} else if (has_subbs) {
gf_bs_reassign_buffer(ctx->bs_w, ctx->samp_buffer, ctx->samp_buffer_alloc);
gf_xml_parse_bit_sequence_bs(node, ctx->src_url, ctx->bs_w);
gf_bs_get_content(ctx->bs_w, &ctx->samp_buffer, &ctx->samp_buffer_size);
if (ctx->samp_buffer_size > ctx->samp_buffer_alloc)
ctx->samp_buffer_alloc = ctx->samp_buffer_size;
} else if (base_data) {
char *start = strchr(base_data, ',');
if (start) {
u32 len = (u32)strlen(start+1);
if (len > ctx->samp_buffer_alloc) {
ctx->samp_buffer_alloc = len;
ctx->samp_buffer = gf_realloc(ctx->samp_buffer, sizeof(char)*ctx->samp_buffer_alloc);
}
ctx->samp_buffer_size = gf_base64_decode(start, len, ctx->samp_buffer, ctx->samp_buffer_alloc);
}
} else {
Bool close = GF_FALSE;
FILE *f = ctx->mdia;
j = 0;
while ((childnode = (GF_XMLNode *)gf_list_enum(node->content, &j))) {
if (childnode->type) continue;
if (!stricmp(childnode->name, szSubSampleName)) {
nb_subsamples++;
}
}
if (strlen(szMediaTemp)) {
f = gf_fopen(szMediaTemp, "rb");
if (!f) {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[NHMLDmx] import failure in sample %d: file %s not found", ctx->sample_num, close ? szMediaTemp : ctx->szMedia));
return GF_NON_COMPLIANT_BITSTREAM;
}
close = GF_TRUE;
if (offset) gf_fseek(f, offset, SEEK_SET);
} else {
if (!offset) offset = ctx->media_done;
byte_offset = offset;
}
if (f) {
if (!ctx->samp_buffer_size) {
u64 ssize = gf_fsize(f);
assert(ssize < 0x80000000);
ctx->samp_buffer_size = (u32) ssize;
}
gf_fseek(f, offset, SEEK_SET);
if (ctx->is_dims) {
u32 read;
if (ctx->samp_buffer_size + 3 > ctx->samp_buffer_alloc) {
ctx->samp_buffer_alloc = ctx->samp_buffer_size + 3;
ctx->samp_buffer = (char*)gf_realloc(ctx->samp_buffer, sizeof(char) * ctx->samp_buffer_alloc);
}
nhml_get_bs(&ctx->bs_w, ctx->samp_buffer, ctx->samp_buffer_alloc, GF_BITSTREAM_WRITE);
gf_bs_write_u16(ctx->bs_w, ctx->samp_buffer_size+1);
gf_bs_write_u8(ctx->bs_w, (u8) dims_flags);
read = (u32) gf_fread( ctx->samp_buffer + 3, ctx->samp_buffer_size, f);
if (ctx->samp_buffer_size != read) {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[NHMLDmx] Failed to fully read sample %d: dataLength %d read %d\n", ctx->sample_num, ctx->samp_buffer_size, read));
}
ctx->samp_buffer_size += 3;
if (ctx->last_dts == dts)
append = GF_TRUE;
} else {
u32 read;
if (ctx->samp_buffer_alloc < ctx->samp_buffer_size) {
ctx->samp_buffer_alloc = ctx->samp_buffer_size;
ctx->samp_buffer = (char*)gf_realloc(ctx->samp_buffer, sizeof(char) * ctx->samp_buffer_alloc);
}
read = (u32) gf_fread(ctx->samp_buffer, ctx->samp_buffer_size, f);
if (ctx->samp_buffer_size != read) {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[NHMLDmx] Failed to fully read sample %d: dataLength %d read %d\n", ctx->sample_num, ctx->samp_buffer_size, read));
}
}
if (close) gf_fclose(f);
} else if (!nb_subsamples) {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[NHMLDmx] No media file associated with sample %d!\n", ctx->sample_num));
e = GF_URL_ERROR;
}
}
if (e) return e;
if (ctx->is_dims) {
if (strstr(ctx->samp_buffer + 3, "svg ")) dims_flags |= GF_DIMS_UNIT_S;
if (dims_flags & GF_DIMS_UNIT_S) dims_flags |= GF_DIMS_UNIT_P;
ctx->samp_buffer[2] = dims_flags;
}
if (compress_type) {
#ifndef GPAC_DISABLE_ZLIB
e = compress_sample_data(ctx, compress_type, ctx->use_dict ? &ctx->dictionary : NULL, ctx->is_dims ? 3 : 0);
if (e) return e;
if (ctx->is_dims) {
nhml_get_bs(&ctx->bs_w, ctx->samp_buffer, ctx->samp_buffer_size, GF_BITSTREAM_WRITE);
gf_bs_write_u16(ctx->bs_w, ctx->samp_buffer_size-2);
}
#else
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[NHMLDmx] Error: your version of GPAC was compiled with no libz support. Abort."));
return GF_NOT_SUPPORTED;
#endif
}
if (ctx->is_dims && (ctx->samp_buffer_size > 0xFFFF)) {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[NHMLDmx] DIMS import failure: sample %d data is too long - maximum size allowed: 65532 bytes", ctx->sample_num));
return GF_NON_COMPLIANT_BITSTREAM;
}
if (ctx->samp_buffer_size) {
pck = gf_filter_pck_new_alloc(ctx->opid, ctx->samp_buffer_size, &data);
if (!pck) return GF_OUT_OF_MEM;
memcpy(data, ctx->samp_buffer, ctx->samp_buffer_size);
gf_filter_pck_set_framing(pck, append ? GF_FALSE : GF_TRUE, nb_subsamples ? GF_FALSE : GF_TRUE);
if (!append) {
gf_filter_pck_set_sap(pck, sap_type);
gf_filter_pck_set_dts(pck, dts);
gf_filter_pck_set_cts(pck, dts+cts_offset);
if (redundant_rap && !ctx->is_dims) gf_filter_pck_set_dependency_flags(pck, 0x1);
if (sample_duration || ctx->dts_inc)
gf_filter_pck_set_duration(pck, sample_duration ? (u32) sample_duration : ctx->dts_inc);
if (byte_offset != GF_FILTER_NO_BO)
gf_filter_pck_set_byte_offset(pck, byte_offset);
if (ctx->in_seek) {
if (dts+cts_offset >= ctx->start_range * ctx->timescale)
ctx->in_seek = GF_FALSE;
else
gf_filter_pck_set_seek_flag(pck, GF_TRUE);
}
}
gf_filter_pck_send(pck);
} else {
first_subsample_is_first = GF_TRUE;
}
if (nb_subsamples) {
if (ctx->samp_buffer_alloc<14*nb_subsamples) {
ctx->samp_buffer_alloc = 14*nb_subsamples;
ctx->samp_buffer = gf_realloc(ctx->samp_buffer, ctx->samp_buffer_alloc);
}
assert(ctx->samp_buffer);
nhml_get_bs(&ctx->bs_w, ctx->samp_buffer, ctx->samp_buffer_alloc, GF_BITSTREAM_WRITE);
}
j = 0;
while (!append && nb_subsamples && (childnode = (GF_XMLNode *)gf_list_enum(node->content, &j))) {
if (childnode->type) continue;
if (!stricmp(childnode->name, szSubSampleName)) {
u32 k = 0;
while ((att = (GF_XMLAttribute *)gf_list_enum(childnode->attributes, &k))) {
if (!stricmp(att->name, "mediaFile")) {
u64 subsMediaFileSize = 0;
FILE *f = NULL;
char *sub_file_url = gf_url_concatenate(ctx->src_url, att->value);
if (sub_file_url) {
f = gf_fopen(sub_file_url, "rb");
gf_free(sub_file_url);
}
if (!f) {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[NHMLDmx] Error: mediaFile \"%s\" not found for subsample in sample %d. Abort.\n", att->value, ctx->sample_num));
return GF_URL_ERROR;
}
subsMediaFileSize = gf_fsize(f);
assert(subsMediaFileSize < 0x80000000);
pck = gf_filter_pck_new_alloc(ctx->opid, (u32) subsMediaFileSize, &data);
if (!pck) {
gf_fclose(f);
return GF_OUT_OF_MEM;
}
subsMediaFileSize = (u32) gf_fread(data, (u32) subsMediaFileSize, f);
gf_fclose(f);
nb_subsamples--;
if (first_subsample_is_first) {
gf_filter_pck_set_framing(pck, GF_TRUE, nb_subsamples ? GF_FALSE : GF_TRUE);
gf_filter_pck_set_sap(pck, sap_type);
gf_filter_pck_set_dts(pck, dts);
gf_filter_pck_set_cts(pck, dts+cts_offset);
if (redundant_rap && !ctx->is_dims) gf_filter_pck_set_dependency_flags(pck, 0x1);
if (sample_duration || ctx->dts_inc)
gf_filter_pck_set_duration(pck, sample_duration ? (u32) sample_duration : ctx->dts_inc);
if (ctx->in_seek) {
if (dts+cts_offset >= ctx->start_range * ctx->timescale)
ctx->in_seek = GF_FALSE;
else
gf_filter_pck_set_seek_flag(pck, GF_TRUE);
}
first_subsample_is_first = GF_FALSE;
} else {
gf_filter_pck_set_framing(pck, GF_FALSE, nb_subsamples ? GF_FALSE : GF_TRUE);
}
gf_bs_write_u32(ctx->bs_w, 0); gf_bs_write_u32(ctx->bs_w, (u32) subsMediaFileSize);
gf_bs_write_u32(ctx->bs_w, 0); gf_bs_write_u8(ctx->bs_w, 0); gf_bs_write_u8(ctx->bs_w, 0); 
if (!nb_subsamples) {
u32 subs_size = (u32) gf_bs_get_position(ctx->bs_w);
gf_filter_pck_set_property(pck, GF_PROP_PCK_SUBS, &PROP_DATA(ctx->samp_buffer, subs_size) );
}
gf_filter_pck_send(pck);
}
}
}
}
ctx->last_dts = dts;
if (sample_duration)
ctx->last_dts += sample_duration;
else
ctx->last_dts += ctx->dts_inc;
ctx->media_done += ctx->samp_buffer_size;
if (gf_filter_pid_would_block(ctx->opid))
return GF_OK;
}
ctx->parsing_state = 2;
return GF_OK;
}

static void brcmf_msgbuf_process_event(struct brcmf_msgbuf *msgbuf, void *buf)
{
struct msgbuf_rx_event *event;
u32 idx;
u16 buflen;
struct sk_buff *skb;
struct brcmf_if *ifp;
event = (struct msgbuf_rx_event *)buf;
idx = le32_to_cpu(event->msg.request_id);
buflen = le16_to_cpu(event->event_data_len);
if (msgbuf->cur_eventbuf)
msgbuf->cur_eventbuf--;
brcmf_msgbuf_rxbuf_event_post(msgbuf);
skb = brcmf_msgbuf_get_pktid(msgbuf->drvr->bus_if->dev,
msgbuf->rx_pktids, idx);
if (!skb)
return;
if (msgbuf->rx_dataoffset)
skb_pull(skb, msgbuf->rx_dataoffset);
skb_trim(skb, buflen);
ifp = brcmf_get_ifp(msgbuf->drvr, event->msg.ifidx);
if (!ifp || !ifp->ndev) {
brcmf_err("Received pkt for invalid ifidx %d\n",
event->msg.ifidx);
goto exit;
}
skb->protocol = eth_type_trans(skb, ifp->ndev);
brcmf_fweh_process_skb(ifp->drvr, skb);
exit:
brcmu_pkt_buf_free_skb(skb);
}

int nego_recv(rdpTransport* transport, wStream* s, void* extra)
{
BYTE li;
BYTE type;
UINT16 length;
rdpNego* nego = (rdpNego*)extra;
if (!tpkt_read_header(s, &length))
return -1;
if (!tpdu_read_connection_confirm(s, &li, length))
return -1;
if (li > 6)
{
Stream_Read_UINT8(s, type); 
switch (type)
{
case TYPE_RDP_NEG_RSP:
nego_process_negotiation_response(nego, s);
WLog_DBG(TAG, "selected_protocol: %" PRIu32 "", nego->SelectedProtocol);
if (nego->SelectedProtocol)
{
if ((nego->SelectedProtocol == PROTOCOL_HYBRID) &&
(!nego->EnabledProtocols[PROTOCOL_HYBRID]))
{
nego->state = NEGO_STATE_FAIL;
}
if ((nego->SelectedProtocol == PROTOCOL_SSL) &&
(!nego->EnabledProtocols[PROTOCOL_SSL]))
{
nego->state = NEGO_STATE_FAIL;
}
}
else if (!nego->EnabledProtocols[PROTOCOL_RDP])
{
nego->state = NEGO_STATE_FAIL;
}
break;
case TYPE_RDP_NEG_FAILURE:
nego_process_negotiation_failure(nego, s);
break;
}
}
else if (li == 6)
{
WLog_DBG(TAG, "no rdpNegData");
if (!nego->EnabledProtocols[PROTOCOL_RDP])
nego->state = NEGO_STATE_FAIL;
else
nego->state = NEGO_STATE_FINAL;
}
else
{
WLog_ERR(TAG, "invalid negotiation response");
nego->state = NEGO_STATE_FAIL;
}
if (!tpkt_ensure_stream_consumed(s, length))
return -1;
return 0;
}

