char*  fullp  = full;
char*  family = cffface->family_name;
if ( full && family )
{
while ( *fullp )
{
if ( *fullp == *family )
{
family++;
fullp++;
continue;
}
if ( *fullp == ' ' || *fullp == '-' )
{
fullp++;
continue;
}
if ( *family == ' ' || *family == '-' )
{
family++;
continue;
