static size_t
ReadNextFunctionHandle(mat_t *mat, matvar_t *matvar)
{
int err;
size_t nelems = 1;
err = Mat_MulDims(matvar, &nelems);
matvar->data_size = sizeof(matvar_t *);
err |= Mul(&matvar->nbytes, nelems, matvar->data_size);
if ( err )
return 0;
matvar->data = malloc(matvar->nbytes);
if ( matvar->data != NULL ) {
size_t i;
matvar_t **functions = (matvar_t **)matvar->data;
for ( i = 0; i < nelems; i++ ) {
functions[i] = Mat_VarReadNextInfo(mat);
err = NULL == functions[i];
if ( err )
break;
}
if ( err ) {
free(matvar->data);
matvar->data = NULL;
matvar->data_size = 0;
matvar->nbytes = 0;
}
} else {
matvar->data_size = 0;
matvar->nbytes = 0;
}
return 0;
}

int
keepalived_main(int argc, char **argv)
{
bool report_stopped = true;
struct utsname uname_buf;
char *end;
set_time_now();
save_cmd_line_options(argc, argv);
debug = 0;
#ifndef _DEBUG_
prog_type = PROG_TYPE_PARENT;
#endif
#ifdef _WITH_VRRP_
__set_bit(DAEMON_VRRP, &daemon_mode);
#endif
#ifdef _WITH_LVS_
__set_bit(DAEMON_CHECKERS, &daemon_mode);
#endif
#ifdef _WITH_BFD_
__set_bit(DAEMON_BFD, &daemon_mode);
#endif
openlog(PACKAGE_NAME, LOG_PID, log_facility);
#ifdef _MEM_CHECK_
mem_log_init(PACKAGE_NAME, "Parent process");
#endif
if (uname(&uname_buf))
log_message(LOG_INFO, "Unable to get uname() information - error %d", errno);
else {
os_major = (unsigned)strtoul(uname_buf.release, &end, 10);
if (*end != '.')
os_major = 0;
else {
os_minor = (unsigned)strtoul(end + 1, &end, 10);
if (*end != '.')
os_major = 0;
else {
if (!isdigit(end[1]))
os_major = 0;
else
os_release = (unsigned)strtoul(end + 1, &end, 10);
}
}
if (!os_major)
log_message(LOG_INFO, "Unable to parse kernel version %s", uname_buf.release);
if (!config_id) {
end = strchrnul(uname_buf.nodename, '.');
config_id = MALLOC((size_t)(end - uname_buf.nodename) + 1);
strncpy(config_id, uname_buf.nodename, (size_t)(end - uname_buf.nodename));
config_id[end - uname_buf.nodename] = '\0';
}
}
if (parse_cmdline(argc, argv)) {
closelog();
if (!__test_bit(NO_SYSLOG_BIT, &debug))
openlog(PACKAGE_NAME, LOG_PID | ((__test_bit(LOG_CONSOLE_BIT, &debug)) ? LOG_CONS : 0) , log_facility);
}
if (__test_bit(LOG_CONSOLE_BIT, &debug))
enable_console_log();
#ifdef GIT_COMMIT
log_message(LOG_INFO, "Starting %s, git commit %s", version_string, GIT_COMMIT);
#else
log_message(LOG_INFO, "Starting %s", version_string);
#endif
core_dump_init();
if (os_major) {
if (KERNEL_VERSION(os_major, os_minor, os_release) < LINUX_VERSION_CODE) {
log_message(LOG_INFO, "WARNING - keepalived was build for newer Linux %d.%d.%d, running on %s %s %s",
(LINUX_VERSION_CODE >> 16) & 0xff,
(LINUX_VERSION_CODE >>  8) & 0xff,
(LINUX_VERSION_CODE      ) & 0xff,
uname_buf.sysname, uname_buf.release, uname_buf.version);
} else {
log_message(LOG_INFO, "Running on %s %s %s (built for Linux %d.%d.%d)",
uname_buf.sysname, uname_buf.release, uname_buf.version,
(LINUX_VERSION_CODE >> 16) & 0xff,
(LINUX_VERSION_CODE >>  8) & 0xff,
(LINUX_VERSION_CODE      ) & 0xff);
}
}
#ifndef _DEBUG_
log_command_line(0);
#endif
if (!check_conf_file(conf_file)) {
if (__test_bit(CONFIG_TEST_BIT, &debug))
config_test_exit();
goto end;
}
global_data = alloc_global_data();
read_config_file();
init_global_data(global_data, NULL);
#if HAVE_DECL_CLONE_NEWNET
if (override_namespace) {
if (global_data->network_namespace) {
log_message(LOG_INFO, "Overriding config net_namespace '%s' with command line namespace '%s'", global_data->network_namespace, override_namespace);
FREE(global_data->network_namespace);
}
global_data->network_namespace = override_namespace;
override_namespace = NULL;
}
#endif
if (!__test_bit(CONFIG_TEST_BIT, &debug) &&
(global_data->instance_name
#if HAVE_DECL_CLONE_NEWNET
|| global_data->network_namespace
#endif
)) {
if ((syslog_ident = make_syslog_ident(PACKAGE_NAME))) {
log_message(LOG_INFO, "Changing syslog ident to %s", syslog_ident);
closelog();
openlog(syslog_ident, LOG_PID | ((__test_bit(LOG_CONSOLE_BIT, &debug)) ? LOG_CONS : 0), log_facility);
}
else
log_message(LOG_INFO, "Unable to change syslog ident");
use_pid_dir = true;
open_log_file(log_file_name,
NULL,
#if HAVE_DECL_CLONE_NEWNET
global_data->network_namespace,
#else
NULL,
#endif
global_data->instance_name);
}
set_child_finder_name(find_keepalived_child_name);
if (!__test_bit(CONFIG_TEST_BIT, &debug)) {
if (use_pid_dir) {
create_pid_dir();
}
}
#if HAVE_DECL_CLONE_NEWNET
if (global_data->network_namespace) {
if (global_data->network_namespace && !set_namespaces(global_data->network_namespace)) {
log_message(LOG_ERR, "Unable to set network namespace %s - exiting", global_data->network_namespace);
goto end;
}
}
#endif
if (!__test_bit(CONFIG_TEST_BIT, &debug)) {
if (global_data->instance_name) {
if (!main_pidfile && (main_pidfile = make_pidfile_name(KEEPALIVED_PID_DIR KEEPALIVED_PID_FILE, global_data->instance_name, PID_EXTENSION)))
free_main_pidfile = true;
#ifdef _WITH_LVS_
if (!checkers_pidfile && (checkers_pidfile = make_pidfile_name(KEEPALIVED_PID_DIR CHECKERS_PID_FILE, global_data->instance_name, PID_EXTENSION)))
free_checkers_pidfile = true;
#endif
#ifdef _WITH_VRRP_
if (!vrrp_pidfile && (vrrp_pidfile = make_pidfile_name(KEEPALIVED_PID_DIR VRRP_PID_FILE, global_data->instance_name, PID_EXTENSION)))
free_vrrp_pidfile = true;
#endif
#ifdef _WITH_BFD_
if (!bfd_pidfile && (bfd_pidfile = make_pidfile_name(KEEPALIVED_PID_DIR VRRP_PID_FILE, global_data->instance_name, PID_EXTENSION)))
free_bfd_pidfile = true;
#endif
}
if (use_pid_dir) {
if (!main_pidfile)
main_pidfile = KEEPALIVED_PID_DIR KEEPALIVED_PID_FILE PID_EXTENSION;
#ifdef _WITH_LVS_
if (!checkers_pidfile)
checkers_pidfile = KEEPALIVED_PID_DIR CHECKERS_PID_FILE PID_EXTENSION;
#endif
#ifdef _WITH_VRRP_
if (!vrrp_pidfile)
vrrp_pidfile = KEEPALIVED_PID_DIR VRRP_PID_FILE PID_EXTENSION;
#endif
#ifdef _WITH_BFD_
if (!bfd_pidfile)
bfd_pidfile = KEEPALIVED_PID_DIR BFD_PID_FILE PID_EXTENSION;
#endif
}
else
{
if (!main_pidfile)
main_pidfile = PID_DIR KEEPALIVED_PID_FILE PID_EXTENSION;
#ifdef _WITH_LVS_
if (!checkers_pidfile)
checkers_pidfile = PID_DIR CHECKERS_PID_FILE PID_EXTENSION;
#endif
#ifdef _WITH_VRRP_
if (!vrrp_pidfile)
vrrp_pidfile = PID_DIR VRRP_PID_FILE PID_EXTENSION;
#endif
#ifdef _WITH_BFD_
if (!bfd_pidfile)
bfd_pidfile = PID_DIR BFD_PID_FILE PID_EXTENSION;
#endif
}
if (keepalived_running(daemon_mode)) {
log_message(LOG_INFO, "daemon is already running");
report_stopped = false;
goto end;
}
}
if (!__test_bit(DONT_FORK_BIT, &debug) &&
xdaemon(false, false, true) > 0) {
closelog();
FREE_PTR(config_id);
FREE_PTR(orig_core_dump_pattern);
close_std_fd();
exit(0);
}
umask(0);
#ifdef _MEM_CHECK_
enable_mem_log_termination();
#endif
if (__test_bit(CONFIG_TEST_BIT, &debug)) {
validate_config();
config_test_exit();
}
if (!pidfile_write(main_pidfile, getpid()))
goto end;
master = thread_make_master();
signal_init();
if (!start_keepalived())
log_message(LOG_INFO, "Warning - keepalived has no configuration to run");
initialise_debug_options();
#ifdef THREAD_DUMP
register_parent_thread_addresses();
#endif
launch_thread_scheduler(master);
stop_keepalived();
#ifdef THREAD_DUMP
deregister_thread_addresses();
#endif
end:
if (report_stopped) {
#ifdef GIT_COMMIT
log_message(LOG_INFO, "Stopped %s, git commit %s", version_string, GIT_COMMIT);
#else
log_message(LOG_INFO, "Stopped %s", version_string);
#endif
}
#if HAVE_DECL_CLONE_NEWNET
if (global_data && global_data->network_namespace)
clear_namespaces();
#endif
if (use_pid_dir)
remove_pid_dir();
if (orig_core_dump_pattern)
update_core_dump_pattern(orig_core_dump_pattern);
free_parent_mallocs_startup(false);
free_parent_mallocs_exit();
free_global_data(global_data);
closelog();
#ifndef _MEM_CHECK_LOG_
FREE_PTR(syslog_ident);
#else
if (syslog_ident)
free(syslog_ident);
#endif
close_std_fd();
exit(KEEPALIVED_EXIT_OK);
}

void CLASS parse_fuji(int offset)
{
unsigned entries, tag, len, save, c;
fseek(ifp, offset, SEEK_SET);
entries = get4();
if (entries > 255)
return;
while (entries--)
{
tag = get2();
len = get2();
save = ftell(ifp);
if (tag == 0x100)
{
raw_height = get2();
raw_width = get2();
}
else if (tag == 0x121)
{
height = get2();
if ((width = get2()) == 4284)
width += 3;
}
else if (tag == 0x130)
{
fuji_layout = fgetc(ifp) >> 7;
fuji_width = !(fgetc(ifp) & 8);
}
else if (tag == 0x131)
{
filters = 9;
FORC(36)
{
int q = fgetc(ifp);
xtrans_abs[0][35 - c] = MAX(0,MIN(q,2)); 
}
}
else if (tag == 0x2ff0)
{
FORC4 cam_mul[c ^ 1] = get2();
#ifdef LIBRAW_LIBRARY_BUILD
}
else if (tag == 0x9650)
{
short a = (short)get2();
float b = fMAX(1.0f, get2());
imgdata.makernotes.fuji.FujiExpoMidPointShift = a / b;
}
else if (tag == 0x2f00)
{
int nWBs = get4();
nWBs = MIN(nWBs, 6);
for (int wb_ind = 0; wb_ind < nWBs; wb_ind++)
{
FORC4 imgdata.color.WB_Coeffs[LIBRAW_WBI_Custom1 + wb_ind][c ^ 1] = get2();
fseek(ifp, 8, SEEK_CUR);
}
}
else if (tag == 0x2000)
{
FORC4 imgdata.color.WB_Coeffs[LIBRAW_WBI_Auto][c ^ 1] = get2();
}
else if (tag == 0x2100)
{
FORC4 imgdata.color.WB_Coeffs[LIBRAW_WBI_FineWeather][c ^ 1] = get2();
}
else if (tag == 0x2200)
{
FORC4 imgdata.color.WB_Coeffs[LIBRAW_WBI_Shade][c ^ 1] = get2();
}
else if (tag == 0x2300)
{
FORC4 imgdata.color.WB_Coeffs[LIBRAW_WBI_FL_D][c ^ 1] = get2();
}
else if (tag == 0x2301)
{
FORC4 imgdata.color.WB_Coeffs[LIBRAW_WBI_FL_N][c ^ 1] = get2();
}
else if (tag == 0x2302)
{
FORC4 imgdata.color.WB_Coeffs[LIBRAW_WBI_FL_WW][c ^ 1] = get2();
}
else if (tag == 0x2310)
{
FORC4 imgdata.color.WB_Coeffs[LIBRAW_WBI_FL_L][c ^ 1] = get2();
}
else if (tag == 0x2400)
{
FORC4 imgdata.color.WB_Coeffs[LIBRAW_WBI_Tungsten][c ^ 1] = get2();
}
else if (tag == 0x2410)
{
FORC4 imgdata.color.WB_Coeffs[LIBRAW_WBI_Flash][c ^ 1] = get2();
#endif
}
else if (tag == 0xc000)
{
c = order;
order = 0x4949;
if ((tag = get4()) > 10000)
tag = get4();
if (tag > 10000)
tag = get4();
width = tag;
height = get4();
#ifdef LIBRAW_LIBRARY_BUILD
if (!strcmp(model, "X-A3") || !strcmp(model, "X-A10"))
{
int wb[4];
int nWB, tWB, pWB;
int iCCT = 0;
int cnt;
fseek(ifp, save + 0x200, SEEK_SET);
for (int wb_ind = 0; wb_ind < 42; wb_ind++)
{
nWB = get4();
tWB = get4();
wb[0] = get4() << 1;
wb[1] = get4();
wb[3] = get4();
wb[2] = get4() << 1;
if (tWB && (iCCT < 255))
{
imgdata.color.WBCT_Coeffs[iCCT][0] = tWB;
for (cnt = 0; cnt < 4; cnt++)
imgdata.color.WBCT_Coeffs[iCCT][cnt + 1] = wb[cnt];
iCCT++;
}
if (nWB != 70)
{
for (pWB = 1; pWB < nFuji_wb_list2; pWB += 2)
{
if (Fuji_wb_list2[pWB] == nWB)
{
for (cnt = 0; cnt < 4; cnt++)
imgdata.color.WB_Coeffs[Fuji_wb_list2[pWB - 1]][cnt] = wb[cnt];
break;
}
}
}
}
}
else
{
libraw_internal_data.unpacker_data.posRAFData = save;
libraw_internal_data.unpacker_data.lenRAFData = (len >> 1);
}
#endif
order = c;
}
fseek(ifp, save + len, SEEK_SET);
}
height <<= fuji_layout;
width >>= fuji_layout;
}

static enum rules_token
lex(struct scanner *s, union lvalue *val)
{
skip_more_whitespace_and_comments:
while (is_space(peek(s)))
if (next(s) == '\n')
return TOK_END_OF_LINE;
if (chr(s, '#')) {
skip_to_eol(s);
goto skip_more_whitespace_and_comments;
}
if (eof(s)) return TOK_END_OF_FILE;
s->token_line = s->line;
s->token_column = s->column;
s->buf_pos = 0;
if (chr(s, '<')) {
while (peek(s) != '>' && !eol(s))
buf_append(s, next(s));
if (!chr(s, '>')) {
scanner_err(s, "unterminated keysym literal");
return TOK_ERROR;
}
if (!buf_append(s, '\0')) {
scanner_err(s, "keysym literal is too long");
return TOK_ERROR;
}
val->string.str = s->buf;
val->string.len = s->buf_pos;
return TOK_LHS_KEYSYM;
}
if (chr(s, ':'))
return TOK_COLON;
if (chr(s, '!'))
return TOK_BANG;
if (chr(s, '~'))
return TOK_TILDE;
if (chr(s, '\"')) {
while (!eof(s) && !eol(s) && peek(s) != '\"') {
if (chr(s, '\\')) {
uint8_t o;
if (chr(s, '\\')) {
buf_append(s, '\\');
}
else if (chr(s, '"')) {
buf_append(s, '"');
}
else if (chr(s, 'x') || chr(s, 'X')) {
if (hex(s, &o))
buf_append(s, (char) o);
else
scanner_warn(s, "illegal hexadecimal escape sequence in string literal");
}
else if (oct(s, &o)) {
buf_append(s, (char) o);
}
else {
scanner_warn(s, "unknown escape sequence (%c) in string literal", peek(s));
}
} else {
buf_append(s, next(s));
}
}
if (!chr(s, '\"')) {
scanner_err(s, "unterminated string literal");
return TOK_ERROR;
}
if (!buf_append(s, '\0')) {
scanner_err(s, "string literal is too long");
return TOK_ERROR;
}
if (!is_valid_utf8(s->buf, s->buf_pos - 1)) {
scanner_err(s, "string literal is not a valid UTF-8 string");
return TOK_ERROR;
}
val->string.str = s->buf;
val->string.len = s->buf_pos;
return TOK_STRING;
}
if (is_alpha(peek(s)) || peek(s) == '_') {
s->buf_pos = 0;
while (is_alnum(peek(s)) || peek(s) == '_')
buf_append(s, next(s));
if (!buf_append(s, '\0')) {
scanner_err(s, "identifier is too long");
return TOK_ERROR;
}
if (streq(s->buf, "include"))
return TOK_INCLUDE;
val->string.str = s->buf;
val->string.len = s->buf_pos;
return TOK_IDENT;
}
skip_to_eol(s);
scanner_err(s, "unrecognized token");
return TOK_ERROR;
}

static int
decode_command(tvbuff_t *tvb, packet_info* pinfo, int msglen, int offset, int dst, proto_tree *pt)
{
guint32         cmd;
guint32         context, ioctl_command;
proto_tree      *ft;
proto_item      *hi;
gryphon_pkt_info_t *pkt_info;
hi = proto_tree_add_item_ret_uint(pt, hf_gryphon_cmd, tvb, offset, 1, ENC_BIG_ENDIAN, &cmd);
proto_item_set_hidden(hi);
if (cmd > 0x3F)
cmd += dst * 256;
if (!pinfo->fd->visited) {
gryphon_conversation *conv_data = get_conversation_data(pinfo);
pkt_info = wmem_new0(wmem_file_scope(), gryphon_pkt_info_t);
pkt_info->cmd = cmd;
pkt_info->req_frame_num = pinfo->num;
pkt_info->req_time = pinfo->abs_ts;
wmem_list_prepend(conv_data->request_frame_data, pkt_info);
p_add_proto_data(wmem_file_scope(), pinfo, proto_gryphon, (guint32)tvb_raw_offset(tvb), pkt_info);
} else {
pkt_info = (gryphon_pkt_info_t*)p_get_proto_data(wmem_file_scope(), pinfo, proto_gryphon, (guint32)tvb_raw_offset(tvb));
}
proto_tree_add_uint(pt, hf_gryphon_command, tvb, offset, 1, cmd);
proto_tree_add_item_ret_uint(pt, hf_gryphon_cmd_context, tvb, offset + 1, 1, ENC_NA, &context);
if (!pinfo->fd->visited) {
pkt_info->cmd_context = context;
}
proto_tree_add_item(pt, hf_gryphon_reserved, tvb, offset + 2, 2, ENC_NA);
if (pkt_info->rsp_frame_num > 0) {
proto_item* it = proto_tree_add_uint(pt, hf_gryphon_response_in,
tvb, 0, 0, pkt_info->rsp_frame_num);
proto_item_set_generated(it);
}
offset += 4;
msglen -= 4;
if (msglen > 0)
{
ft = proto_tree_add_subtree_format(pt, tvb, offset, msglen, ett_gryphon_command_data, NULL,
"Data: (%d byte%s)", msglen, plurality(msglen, "", "s"));
switch (cmd)
{
case CMD_INIT:
offset = cmd_init(tvb, offset, ft);
break;
case CMD_EVENT_ENABLE:
case CMD_EVENT_DISABLE:
offset = eventnum(tvb, offset, ft);
break;
case CMD_SET_TIME:
offset = resp_time(tvb, offset, ft);
break;
case CMD_CARD_SET_SPEED:
offset = speed(tvb, offset, ft);
break;
case CMD_CARD_SET_FILTER:
offset = cmd_setfilt(tvb, offset, ft);
break;
case CMD_CARD_GET_FILTER:
offset = resp_addfilt(tvb, offset, ft);
break;
case CMD_CARD_TX:
offset = decode_data(tvb, offset, ft);
break;
case CMD_CARD_ADD_FILTER:
offset = cmd_addfilt(tvb, offset, ft);
break;
case CMD_CARD_MODIFY_FILTER:
offset = cmd_modfilt(tvb, offset, ft);
break;
case CMD_CARD_SET_DEFAULT_FILTER:
offset = dfiltmode(tvb, offset, ft);
break;
case CMD_CARD_SET_FILTER_MODE:
offset = filtmode(tvb, offset, ft);
break;
case CMD_SERVER_REG:
offset = cmd_register(tvb, offset, ft);
break;
case CMD_SERVER_SET_SORT:
offset = cmd_sort(tvb, offset, ft);
break;
case CMD_SERVER_SET_OPT:
offset = cmd_optimize(tvb, offset, ft);
break;
case CMD_BLM_SET_MODE:
offset = blm_mode(tvb, offset, ft);
break;
case CMD_LDF_LIST:
offset = cmd_ldf_list(tvb, offset, ft);
break;
case CMD_LDF_DELETE:
offset = cmd_ldf_delete(tvb, offset, ft);
break;
case CMD_LDF_DESC:
offset = cmd_ldf_desc(tvb, offset, ft);
break;
case CMD_LDF_UPLOAD:
offset = cmd_ldf_upload(tvb, offset, ft);
break;
case CMD_LDF_PARSE:
offset = cmd_ldf_parse(tvb, offset, ft);
break;
case CMD_GET_NODE_SIGNALS:
offset = cmd_ldf_get_node_signals(tvb, offset, ft);
break;
case CMD_GET_FRAMES:
offset = cmd_ldf_get_frames(tvb, offset, ft);
break;
case CMD_GET_FRAME_INFO:
offset = cmd_ldf_get_frame_info(tvb, pinfo, offset, ft);
break;
case CMD_GET_SIGNAL_INFO:
offset = cmd_ldf_get_signal_info(tvb, offset, ft);
break;
case CMD_GET_SIGNAL_DETAIL:
offset = cmd_ldf_get_signal_detail(tvb, offset, ft);
break;
case CMD_GET_ENCODING_INFO:
offset = cmd_ldf_get_encoding_info(tvb, offset, ft);
break;
case CMD_SAVE_SESSION:
offset = cmd_ldf_save_session(tvb, offset, ft);
break;
case CMD_EMULATE_NODES:
offset = cmd_ldf_emulate_nodes(tvb, pinfo, offset, ft);
break;
case CMD_START_SCHEDULE:
offset = cmd_ldf_start_schedule(tvb, offset, ft);
break;
case CMD_RESTORE_SESSION:
offset = cmd_restore_session(tvb, offset, ft);
break;
case CMD_CNVT_GET_VALUES:
offset = cmd_cnvt_get_values(tvb, offset, ft);
break;
case CMD_CNVT_GET_UNITS:
offset = cmd_cnvt_get_units(tvb, offset, ft);
break;
case CMD_CNVT_SET_VALUES:
offset = cmd_cnvt_set_values(tvb, offset, ft);
break;
case CMD_CNVT_SAVE_SESSION:
offset = cmd_ldf_save_session(tvb, offset, ft);
break;
case CMD_CNVT_RESTORE_SESSION:
offset = cmd_restore_session(tvb, offset, ft);
break;
case CMD_CNVT_DESTROY_SESSION:
offset = cmd_cnvt_destroy_session(tvb, offset, ft);
break;
case CMD_CNVT_GET_NODE_SIGNALS:
offset = cmd_ldf_get_node_signals(tvb, offset, ft);
break;
case CMD_MSGRESP_ADD:
offset = cmd_addresp(tvb, offset, pinfo, ft);
break;
case CMD_MSGRESP_GET:
offset = resp_addresp(tvb, offset, ft);
break;
case CMD_MSGRESP_MODIFY:
offset = cmd_modresp(tvb, offset, ft);
break;
case CMD_PGM_DESC:
offset = cmd_desc(tvb, offset, ft);
break;
case CMD_PGM_UPLOAD:
offset = cmd_upload(tvb, offset, ft);
break;
case CMD_PGM_DELETE:
offset = cmd_delete(tvb, offset, ft);
break;
case CMD_PGM_LIST:
offset = cmd_list(tvb, offset, ft);
break;
case CMD_PGM_START:
offset = cmd_start(tvb, pinfo, offset, ft);
break;
case CMD_PGM_STOP:
offset = resp_start(tvb, offset, ft);
break;
case CMD_PGM_STATUS:
offset = cmd_delete(tvb, offset, ft);
break;
case CMD_PGM_OPTIONS:
offset = cmd_options(tvb, offset, ft);
break;
case CMD_PGM_FILES:
offset = cmd_files(tvb, offset, ft);
break;
case CMD_SCHED_TX:
offset = cmd_sched(tvb, offset, ft);
break;
case CMD_SCHED_KILL_TX:
offset = resp_sched(tvb, offset, ft);
break;
case CMD_SCHED_MSG_REPLACE:
offset = cmd_sched_rep(tvb, offset, ft);
break;
case CMD_USDT_REGISTER:
offset = cmd_usdt(tvb, offset, ft);
break;
case CMD_USDT_SET_FUNCTIONAL:
offset = cmd_usdt(tvb, offset, ft);
break;
case CMD_USDT_SET_STMIN_MULT:
offset = cmd_usdt_set_stmin_mul(tvb, offset, ft);
break;
case CMD_USDT_REGISTER_NON_LEGACY:
offset = cmd_usdt_register_non_legacy(tvb, offset, ft);
break;
case CMD_USDT_SET_STMIN_FC:
offset = cmd_usdt_stmin_fc(tvb, offset, ft);
break;
case CMD_USDT_SET_BSMAX_FC:
offset = cmd_usdt_bsmax_fc(tvb, offset, ft);
break;
case CMD_USDT_SET_STMIN_OVERRIDE:
offset = cmd_usdt_stmin_override(tvb, offset, ft);
break;
case CMD_USDT_ACTIVATE_STMIN_OVERRIDE:
offset = cmd_usdt_stmin_override_activate(tvb, offset, ft);
break;
case CMD_IOPWR_CLRLATCH:
offset = cmd_bits_in(tvb, offset, ft);
break;
case CMD_IOPWR_SETOUT:
case CMD_IOPWR_SETBIT:
case CMD_IOPWR_CLRBIT:
offset = cmd_bits_out(tvb, offset, ft);
break;
case CMD_UTIL_SET_INIT_STRATEGY:
offset = cmd_init_strat(tvb, offset, ft);
break;
case CMD_CARD_IOCTL:
ioctl_command = tvb_get_ntohl(tvb, offset);
if (!pinfo->fd->visited) {
pkt_info->ioctl_command = ioctl_command;
}
offset = cmd_ioctl(tvb, pinfo, offset, ft, ioctl_command);
break;
default:
proto_tree_add_item(ft, hf_gryphon_data, tvb, offset, msglen, ENC_NA);
offset += msglen;
break;
}
}
return offset;
}

int dvb_ca_en50221_init(struct dvb_adapter *dvb_adapter,
struct dvb_ca_en50221 *pubca, int flags, int slot_count)
{
int ret;
struct dvb_ca_private *ca = NULL;
int i;
dprintk("%s\n", __func__);
if (slot_count < 1)
return -EINVAL;
ca = kzalloc(sizeof(*ca), GFP_KERNEL);
if (!ca) {
ret = -ENOMEM;
goto exit;
}
kref_init(&ca->refcount);
ca->pub = pubca;
ca->flags = flags;
ca->slot_count = slot_count;
ca->slot_info = kcalloc(slot_count, sizeof(struct dvb_ca_slot),
GFP_KERNEL);
if (!ca->slot_info) {
ret = -ENOMEM;
goto free_ca;
}
init_waitqueue_head(&ca->wait_queue);
ca->open = 0;
ca->wakeup = 0;
ca->next_read_slot = 0;
pubca->private = ca;
ret = dvb_register_device(dvb_adapter, &ca->dvbdev, &dvbdev_ca, ca,
DVB_DEVICE_CA, 0);
if (ret)
goto free_slot_info;
for (i = 0; i < slot_count; i++) {
struct dvb_ca_slot *sl = &ca->slot_info[i];
memset(sl, 0, sizeof(struct dvb_ca_slot));
sl->slot_state = DVB_CA_SLOTSTATE_NONE;
atomic_set(&sl->camchange_count, 0);
sl->camchange_type = DVB_CA_EN50221_CAMCHANGE_REMOVED;
mutex_init(&sl->slot_lock);
}
mutex_init(&ca->ioctl_mutex);
if (signal_pending(current)) {
ret = -EINTR;
goto unregister_device;
}
mb();
ca->thread = kthread_run(dvb_ca_en50221_thread, ca, "kdvb-ca-%i:%i",
ca->dvbdev->adapter->num, ca->dvbdev->id);
if (IS_ERR(ca->thread)) {
ret = PTR_ERR(ca->thread);
pr_err("dvb_ca_init: failed to start kernel_thread (%d)\n",
ret);
goto unregister_device;
}
return 0;
unregister_device:
dvb_unregister_device(ca->dvbdev);
free_slot_info:
kfree(ca->slot_info);
free_ca:
kfree(ca);
exit:
pubca->private = NULL;
return ret;
}

GF_Err afra_box_read(GF_Box *s, GF_BitStream *bs)
{
unsigned int i;
GF_AdobeFragRandomAccessBox *ptr = (GF_AdobeFragRandomAccessBox *)s;
ISOM_DECREASE_SIZE(ptr, 9)
ptr->long_ids = gf_bs_read_int(bs, 1);
ptr->long_offsets = gf_bs_read_int(bs, 1);
ptr->global_entries = gf_bs_read_int(bs, 1);
ptr->reserved = gf_bs_read_int(bs, 5);
ptr->time_scale = gf_bs_read_u32(bs);
ptr->entry_count = gf_bs_read_u32(bs);
if (ptr->size / ( (ptr->long_offsets ? 16 : 12) ) < ptr->entry_count)
return GF_ISOM_INVALID_FILE;
for (i=0; i<ptr->entry_count; i++) {
GF_AfraEntry *ae = gf_malloc(sizeof(GF_AfraEntry));
if (!ae) return GF_OUT_OF_MEM;
gf_list_insert(ptr->local_access_entries, ae, i);
ISOM_DECREASE_SIZE(ptr, 8)
ae->time = gf_bs_read_u64(bs);
if (ptr->long_offsets) {
ISOM_DECREASE_SIZE(ptr, 8)
ae->offset = gf_bs_read_u64(bs);
} else {
ISOM_DECREASE_SIZE(ptr, 4)
ae->offset = gf_bs_read_u32(bs);
}
}
if (ptr->global_entries) {
ISOM_DECREASE_SIZE(ptr, 4)
ptr->global_entry_count = gf_bs_read_u32(bs);
for (i=0; i<ptr->global_entry_count; i++) {
GF_GlobalAfraEntry *ae = gf_malloc(sizeof(GF_GlobalAfraEntry));
if (!ae) return GF_OUT_OF_MEM;
gf_list_insert(ptr->global_access_entries, ae, i);
ISOM_DECREASE_SIZE(ptr, 8)
ae->time = gf_bs_read_u64(bs);
if (ptr->long_ids) {
ISOM_DECREASE_SIZE(ptr, 8)
ae->segment = gf_bs_read_u32(bs);
ae->fragment = gf_bs_read_u32(bs);
} else {
ISOM_DECREASE_SIZE(ptr, 4)
ae->segment = gf_bs_read_u16(bs);
ae->fragment = gf_bs_read_u16(bs);
}
if (ptr->long_offsets) {
ISOM_DECREASE_SIZE(ptr, 16)
ae->afra_offset = gf_bs_read_u64(bs);
ae->offset_from_afra = gf_bs_read_u64(bs);
} else {
ISOM_DECREASE_SIZE(ptr, 8)
ae->afra_offset = gf_bs_read_u32(bs);
ae->offset_from_afra = gf_bs_read_u32(bs);
}
}
}
return GF_OK;
}

void APar_ExtractDetails(FILE *isofile, uint8_t optional_output) {
char *uint32_buffer = (char *)malloc(sizeof(char) * 5);
Trackage track = {0};
AtomicInfo *mvhdAtom = APar_FindAtom("moov.mvhd", false, VERSIONED_ATOM, 0);
if (mvhdAtom != NULL) {
APar_ExtractMovieDetails(uint32_buffer, isofile, mvhdAtom);
fprintf(stdout,
"Movie duration: %.3lf seconds (%s) - %.2lf* kbp/sec bitrate "
"(*=approximate)\n",
movie_info.seconds,
secsTOtime(movie_info.seconds),
movie_info.simple_bitrate_calc);
if (optional_output & SHOW_DATE_INFO) {
fprintf(stdout,
"  Presentation Creation Date (UTC):     %s\n",
APar_extract_UTC(movie_info.creation_time));
fprintf(stdout,
"  Presentation Modification Date (UTC): %s\n",
APar_extract_UTC(movie_info.modified_time));
}
}
AtomicInfo *iodsAtom = APar_FindAtom("moov.iods", false, VERSIONED_ATOM, 0);
if (iodsAtom != NULL) {
movie_info.contains_iods = true;
APar_Extract_iods_Info(isofile, iodsAtom);
}
if (optional_output & SHOW_TRACK_INFO) {
APar_TrackLevelInfo(&track,
NULL);                                
fprintf(
stdout, "Low-level details. Total tracks: %u\n", track.total_tracks);
fprintf(stdout,
"Trk  Type  Handler                    Kind  Lang  Bytes\n");
if (track.total_tracks > 0) {
while (track.total_tracks > track.track_num) {
track.track_num += 1;
TrackInfo track_info = {0};
APar_ExtractTrackDetails(uint32_buffer, isofile, &track, &track_info);
uint16_t more_whitespace =
purge_extraneous_characters(track_info.track_hdlr_name);
if (strlen(track_info.track_hdlr_name) == 0) {
memcpy(track_info.track_hdlr_name, "[none listed]", 13);
}
fprintf(stdout,
"%u    %s  %s",
track.track_num,
uint32tochar4(track_info.track_type, uint32_buffer),
track_info.track_hdlr_name);
uint16_t handler_len = strlen(track_info.track_hdlr_name);
if (handler_len < 25 + more_whitespace) {
for (uint16_t i = handler_len; i < 25 + more_whitespace; i++) {
fprintf(stdout, " ");
}
}
fprintf(stdout,
"  %s  %s   %" PRIu64,
uint32tochar4(track_info.track_codec, uint32_buffer),
track_info.unpacked_lang,
track_info.sample_aggregate);
if (track_info.encoder_name[0] != 0 && track_info.contains_esds) {
purge_extraneous_characters(track_info.encoder_name);
fprintf(stdout, "   Encoder: %s", track_info.encoder_name);
}
if (track_info.type_of_track & DRM_PROTECTED_TRACK) {
fprintf(stdout,
" (protected %s)",
uint32tochar4(track_info.protected_codec, uint32_buffer));
}
fprintf(stdout, "\n");
if (track_info.type_of_track & VIDEO_TRACK ||
track_info.type_of_track & AUDIO_TRACK) {
APar_Print_TrackDetails(&track_info);
}
if (optional_output & SHOW_DATE_INFO) {
fprintf(stdout,
"       Creation Date (UTC):     %s\n",
APar_extract_UTC(track_info.creation_time));
fprintf(stdout,
"       Modification Date (UTC): %s\n",
APar_extract_UTC(track_info.modified_time));
}
}
}
}
return;
}

PJ_DEF(pj_status_t)
pjmedia_avi_player_create_streams(pj_pool_t *pool,
const char *filename,
unsigned options,
pjmedia_avi_streams **p_streams)
{
pjmedia_avi_hdr avi_hdr;
struct avi_reader_port *fport[PJMEDIA_AVI_MAX_NUM_STREAMS];
pj_off_t pos;
unsigned i, nstr = 0;
pj_status_t status = PJ_SUCCESS;
PJ_ASSERT_RETURN(pool && filename && p_streams, PJ_EINVAL);
if (!pj_file_exists(filename)) {
return PJ_ENOTFOUND;
}
fport[0] = create_avi_port(pool);
if (!fport[0]) {
return PJ_ENOMEM;
}
fport[0]->fsize = pj_file_size(filename);
if (fport[0]->fsize <= sizeof(riff_hdr_t) + sizeof(avih_hdr_t) + 
sizeof(strl_hdr_t))
{
return PJMEDIA_EINVALIMEDIATYPE;
}
status = pj_file_open(pool, filename, PJ_O_RDONLY, &fport[0]->fd);
if (status != PJ_SUCCESS)
return status;
status = file_read(fport[0]->fd, &avi_hdr,
sizeof(riff_hdr_t) + sizeof(avih_hdr_t));
if (status != PJ_SUCCESS)
goto on_error;
if (!COMPARE_TAG(avi_hdr.riff_hdr.riff, PJMEDIA_AVI_RIFF_TAG) ||
!COMPARE_TAG(avi_hdr.riff_hdr.avi, PJMEDIA_AVI_AVI_TAG) ||
!COMPARE_TAG(avi_hdr.avih_hdr.list_tag, PJMEDIA_AVI_LIST_TAG) ||
!COMPARE_TAG(avi_hdr.avih_hdr.hdrl_tag, PJMEDIA_AVI_HDRL_TAG) ||
!COMPARE_TAG(avi_hdr.avih_hdr.avih, PJMEDIA_AVI_AVIH_TAG))
{
status = PJMEDIA_EINVALIMEDIATYPE;
goto on_error;
}
PJ_LOG(5, (THIS_FILE, "The AVI file has %d streams.",
avi_hdr.avih_hdr.num_streams));
if (avi_hdr.avih_hdr.num_streams > PJMEDIA_AVI_MAX_NUM_STREAMS) {
status = PJMEDIA_EAVIUNSUPP;
goto on_error;
}
if (avi_hdr.avih_hdr.flags & AVIF_MUSTUSEINDEX ||
avi_hdr.avih_hdr.pad > 1)
{
PJ_LOG(3, (THIS_FILE, "Warning!!! Possibly unsupported AVI format: "
"flags:%d, pad:%d", avi_hdr.avih_hdr.flags, 
avi_hdr.avih_hdr.pad));
}
for (i = 0; i < avi_hdr.avih_hdr.num_streams; i++) {
pj_size_t elem = 0;
pj_ssize_t size_to_read;
status = file_read(fport[0]->fd, &avi_hdr.strl_hdr[i],
sizeof(strl_hdr_t));
if (status != PJ_SUCCESS)
goto on_error;
elem = COMPARE_TAG(avi_hdr.strl_hdr[i].data_type, 
PJMEDIA_AVI_VIDS_TAG) ? 
sizeof(strf_video_hdr_t) :
COMPARE_TAG(avi_hdr.strl_hdr[i].data_type, 
PJMEDIA_AVI_AUDS_TAG) ?
sizeof(strf_audio_hdr_t) : 0;
status = file_read2(fport[0]->fd, &avi_hdr.strf_hdr[i],
elem, 0);
if (status != PJ_SUCCESS)
goto on_error;
if (elem == sizeof(strf_video_hdr_t))
data_to_host2(&avi_hdr.strf_hdr[i],
sizeof(strf_video_hdr_sizes)/
sizeof(strf_video_hdr_sizes[0]),
strf_video_hdr_sizes);
else if (elem == sizeof(strf_audio_hdr_t))
data_to_host2(&avi_hdr.strf_hdr[i],
sizeof(strf_audio_hdr_sizes)/
sizeof(strf_audio_hdr_sizes[0]),
strf_audio_hdr_sizes);
size_to_read = avi_hdr.strl_hdr[i].list_sz - (sizeof(strl_hdr_t) -
8) - elem;
status = pj_file_setpos(fport[0]->fd, size_to_read, PJ_SEEK_CUR);
if (status != PJ_SUCCESS) {
goto on_error;
}
}
status = pj_file_setpos(fport[0]->fd, avi_hdr.avih_hdr.list_sz +
sizeof(riff_hdr_t) + 8, PJ_SEEK_SET);
if (status != PJ_SUCCESS) {
goto on_error;
}
do {
pjmedia_avi_subchunk ch;
int read = 0;
status = file_read(fport[0]->fd, &ch, sizeof(pjmedia_avi_subchunk));
if (status != PJ_SUCCESS) {
goto on_error;
}
if (COMPARE_TAG(ch.id, PJMEDIA_AVI_LIST_TAG))
{
read = 4;
status = file_read(fport[0]->fd, &ch, read);
if (COMPARE_TAG(ch.id, PJMEDIA_AVI_MOVI_TAG))
break;
}
status = pj_file_setpos(fport[0]->fd, ch.len-read, PJ_SEEK_CUR);
if (status != PJ_SUCCESS) {
goto on_error;
}
} while(1);
status = pj_file_getpos(fport[0]->fd, &pos);
if (status != PJ_SUCCESS)
goto on_error;
for (i = 0, nstr = 0; i < avi_hdr.avih_hdr.num_streams; i++) {
pjmedia_format_id fmt_id;
if ((!COMPARE_TAG(avi_hdr.strl_hdr[i].data_type, 
PJMEDIA_AVI_VIDS_TAG) &&
!COMPARE_TAG(avi_hdr.strl_hdr[i].data_type, 
PJMEDIA_AVI_AUDS_TAG)) ||
avi_hdr.strl_hdr[i].flags & AVISF_DISABLED)
{
continue;
}
if (COMPARE_TAG(avi_hdr.strl_hdr[i].data_type, 
PJMEDIA_AVI_VIDS_TAG))
{
int j;
if (avi_hdr.strl_hdr[i].flags & AVISF_VIDEO_PALCHANGES) {
PJ_LOG(4, (THIS_FILE, "Unsupported video stream"));
continue;
}
fmt_id = avi_hdr.strl_hdr[i].codec;
for (j = sizeof(avi_fmts)/sizeof(avi_fmts[0])-1; j >= 0; j--) {
if (fmt_id == avi_fmts[j].fmt_id) {
if (avi_fmts[j].eff_fmt_id)
fmt_id = avi_fmts[j].eff_fmt_id;
break;
}
}
if (j < 0) {
PJ_LOG(4, (THIS_FILE, "Unsupported video stream"));
continue;
}
} else {
strf_audio_hdr_t *hdr = (strf_audio_hdr_t*)
&avi_hdr.strf_hdr[i].strf_audio_hdr;
if (hdr->fmt_tag == PJMEDIA_WAVE_FMT_TAG_PCM &&
hdr->bits_per_sample == 16)
{
fmt_id = PJMEDIA_FORMAT_PCM;
}
else if (hdr->fmt_tag == PJMEDIA_WAVE_FMT_TAG_ALAW)
{
fmt_id = PJMEDIA_FORMAT_PCMA;
}
else if (hdr->fmt_tag == PJMEDIA_WAVE_FMT_TAG_ULAW)
{
fmt_id = PJMEDIA_FORMAT_PCMU;
}
else
{
PJ_LOG(4, (THIS_FILE, "Unsupported audio stream"));
continue;
}
}
if (nstr > 0) {
fport[nstr] = create_avi_port(pool);
if (!fport[nstr]) {
status = PJ_ENOMEM;
goto on_error;
}
status = pj_file_open(pool, filename, PJ_O_RDONLY,
&fport[nstr]->fd);
if (status != PJ_SUCCESS)
goto on_error;
status = pj_file_setpos(fport[nstr]->fd, pos, PJ_SEEK_SET);
if (status != PJ_SUCCESS) {
goto on_error;
}
}
fport[nstr]->stream_id = i;
fport[nstr]->fmt_id = fmt_id;
nstr++;
}
if (nstr == 0) {
status = PJMEDIA_EAVIUNSUPP;
goto on_error;
}
for (i = 0; i < nstr; i++) {
strl_hdr_t *strl_hdr = &avi_hdr.strl_hdr[fport[i]->stream_id];
fport[i]->options = options;
fport[i]->fsize = fport[0]->fsize;
fport[i]->start_data = pos;
if (COMPARE_TAG(strl_hdr->data_type, PJMEDIA_AVI_VIDS_TAG)) {
strf_video_hdr_t *strf_hdr =
&avi_hdr.strf_hdr[fport[i]->stream_id].strf_video_hdr;
const pjmedia_video_format_info *vfi;
vfi = pjmedia_get_video_format_info(
pjmedia_video_format_mgr_instance(),
strl_hdr->codec);
fport[i]->bits_per_sample = (vfi ? vfi->bpp : 0);
fport[i]->usec_per_frame = avi_hdr.avih_hdr.usec_per_frame;
pjmedia_format_init_video(&fport[i]->base.info.fmt,
fport[i]->fmt_id,
strf_hdr->biWidth,
strf_hdr->biHeight,
strl_hdr->rate,
strl_hdr->scale);
#if 0
bps = strf_hdr->biSizeImage * 8 * strl_hdr->rate / strl_hdr->scale;
if (bps==0) {
bps = strf_hdr->biWidth * strf_hdr->biHeight *
strf_hdr->biBitCount *
strl_hdr->rate / strl_hdr->scale;
}
fport[i]->base.info.fmt.det.vid.avg_bps = bps;
fport[i]->base.info.fmt.det.vid.max_bps = bps;
#endif
} else {
strf_audio_hdr_t *strf_hdr =
&avi_hdr.strf_hdr[fport[i]->stream_id].strf_audio_hdr;
fport[i]->bits_per_sample = strf_hdr->bits_per_sample;
fport[i]->usec_per_frame = avi_hdr.avih_hdr.usec_per_frame;
pjmedia_format_init_audio(&fport[i]->base.info.fmt,
fport[i]->fmt_id,
strf_hdr->sample_rate,
strf_hdr->nchannels,
strf_hdr->bits_per_sample,
20000 ,
strf_hdr->bytes_per_sec * 8,
strf_hdr->bytes_per_sec * 8);
if (fport[i]->fmt_id == PJMEDIA_FORMAT_PCMA ||
fport[i]->fmt_id == PJMEDIA_FORMAT_PCMU)
{
fport[i]->base.info.fmt.id = PJMEDIA_FORMAT_PCM;
fport[i]->base.info.fmt.det.aud.bits_per_sample = 16;
}
}
pj_strdup2(pool, &fport[i]->base.info.name, filename);
}
*p_streams = pj_pool_alloc(pool, sizeof(pjmedia_avi_streams));
(*p_streams)->num_streams = nstr;
(*p_streams)->streams = pj_pool_calloc(pool, (*p_streams)->num_streams,
sizeof(pjmedia_port *));
for (i = 0; i < nstr; i++)
(*p_streams)->streams[i] = &fport[i]->base;
PJ_LOG(4,(THIS_FILE, 
"AVI file player '%.*s' created with "
"%d media ports",
(int)fport[0]->base.info.name.slen,
fport[0]->base.info.name.ptr,
(*p_streams)->num_streams));
return PJ_SUCCESS;
on_error:
fport[0]->base.on_destroy(&fport[0]->base);
for (i = 1; i < nstr; i++)
fport[i]->base.on_destroy(&fport[i]->base);
if (status == AVI_EOF)
return PJMEDIA_EINVALIMEDIATYPE;
return status;
}

zzip__new__ ZZIP_MEM_DISK_FILE *
zzip_mem_entry_fopen(ZZIP_MEM_DISK * dir, ZZIP_MEM_ENTRY * entry)
{
ZZIP_DISK_FILE *file = malloc(sizeof(ZZIP_MEM_DISK_FILE));
if (! file)
return file;
file->buffer = dir->disk->buffer;
file->endbuf = dir->disk->endbuf;
file->avail = zzip_mem_entry_usize(entry);
if (! file->avail || zzip_mem_entry_data_stored(entry))
{ file->stored = zzip_mem_entry_to_data (entry); return file; }
file->stored = 0;
file->zlib.opaque = 0;
file->zlib.zalloc = Z_NULL;
file->zlib.zfree = Z_NULL;
file->zlib.avail_in = zzip_mem_entry_csize(entry);
file->zlib.next_in = zzip_mem_entry_to_data(entry);
if (! zzip_mem_entry_data_deflated(entry) ||
inflateInit2(&file->zlib, -MAX_WBITS) != Z_OK)
{ free (file); return 0; }
return file;
}

static Image *ReadAVSImage(const ImageInfo *image_info,ExceptionInfo *exception)
{
Image
*image;
MagickBooleanType
status;
MemoryInfo
*pixel_info;
register Quantum
*q;
register ssize_t
x;
register unsigned char
*p;
size_t
height,
length,
width;
ssize_t
count,
y;
unsigned char
*pixels;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickCoreSignature);
if (image_info->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
image_info->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
image=AcquireImage(image_info,exception);
status=OpenBlob(image_info,image,ReadBinaryBlobMode,exception);
if (status == MagickFalse)
{
image=DestroyImageList(image);
return((Image *) NULL);
}
width=ReadBlobMSBLong(image);
height=ReadBlobMSBLong(image);
if (EOFBlob(image) != MagickFalse)
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
if ((width == 0UL) || (height == 0UL))
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
do
{
image->columns=width;
image->rows=height;
image->depth=8;
if ((image_info->ping != MagickFalse) && (image_info->number_scenes != 0))
if (image->scene >= (image_info->scene+image_info->number_scenes-1))
break;
status=SetImageExtent(image,image->columns,image->rows,exception);
if (status == MagickFalse)
return(DestroyImageList(image));
pixel_info=AcquireVirtualMemory(image->columns,4*sizeof(*pixels));
if (pixel_info == (MemoryInfo *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
pixels=(unsigned char *) GetVirtualMemoryBlob(pixel_info);
length=(size_t) 4*image->columns;
for (y=0; y < (ssize_t) image->rows; y++)
{
count=ReadBlob(image,length,pixels);
if ((size_t) count != length)
ThrowReaderException(CorruptImageError,"UnableToReadImageData");
p=pixels;
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < (ssize_t) image->columns; x++)
{
SetPixelAlpha(image,ScaleCharToQuantum(*p++),q);
SetPixelRed(image,ScaleCharToQuantum(*p++),q);
SetPixelGreen(image,ScaleCharToQuantum(*p++),q);
SetPixelBlue(image,ScaleCharToQuantum(*p++),q);
if (GetPixelAlpha(image,q) != OpaqueAlpha)
image->alpha_trait=BlendPixelTrait;
q+=GetPixelChannels(image);
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
pixel_info=RelinquishVirtualMemory(pixel_info);
if (EOFBlob(image) != MagickFalse)
{
ThrowFileException(exception,CorruptImageError,"UnexpectedEndOfFile",
image->filename);
break;
}
if (image_info->number_scenes != 0)
if (image->scene >= (image_info->scene+image_info->number_scenes-1))
break;
width=ReadBlobMSBLong(image);
height=ReadBlobMSBLong(image);
if ((width != 0UL) && (height != 0UL))
{
AcquireNextImage(image_info,image,exception);
if (GetNextImageInList(image) == (Image *) NULL)
{
image=DestroyImageList(image);
return((Image *) NULL);
}
image=SyncNextImageInList(image);
status=SetImageProgress(image,LoadImagesTag,TellBlob(image),
GetBlobSize(image));
if (status == MagickFalse)
break;
}
} while ((width != 0UL) && (height != 0UL));
(void) CloseBlob(image);
return(GetFirstImageInList(image));
}

static GF_Err gf_xml_sax_parse_intern(GF_SAXParser *parser, char *current)
{
u32 count;
count = gf_list_count(parser->entities);
while (count) {
char *entityEnd;
XML_Entity *ent;
char *entityStart = strstr(current, "&");
Bool needs_text;
u32 line_num;
if (parser->in_entity) {
u32 len;
char *name;
entityEnd = strstr(current, ";");
if (!entityEnd) return xml_sax_append_string(parser, current);
entityStart = strrchr(parser->buffer, '&');
entityEnd[0] = 0;
len = (u32) strlen(entityStart) + (u32) strlen(current) + 1;
name = (char*)gf_malloc(sizeof(char)*len);
sprintf(name, "%s%s;", entityStart+1, current);
ent = gf_xml_locate_entity(parser, name, &needs_text);
gf_free(name);
if (!ent && !needs_text) {
xml_sax_append_string(parser, current);
xml_sax_parse(parser, GF_TRUE);
entityEnd[0] = ';';
current = entityEnd;
continue;
}
assert(ent);
parser->line_size -= (u32) strlen(entityStart);
entityStart[0] = 0;
parser->in_entity = GF_FALSE;
entityEnd[0] = ';';
current = entityEnd+1;
} else {
if (!entityStart) break;
ent = gf_xml_locate_entity(parser, entityStart+1, &needs_text);
entityStart[0] = 0;
xml_sax_append_string(parser, current);
xml_sax_parse(parser, GF_TRUE);
entityStart[0] = '&';
if (!ent && !needs_text) {
xml_sax_append_string(parser, "&");
current = entityStart+1;
continue;
}
if (!ent) {
parser->in_entity = GF_TRUE;
return xml_sax_append_string(parser, entityStart);
}
current = entityStart + ent->namelen + 2;
}
line_num = parser->line;
xml_sax_append_string(parser, ent->value);
GF_Err e = xml_sax_parse(parser, GF_TRUE);
parser->line = line_num;
if (e) return e;
}
xml_sax_append_string(parser, current);
return xml_sax_parse(parser, GF_FALSE);
}

