static char *
resolveSubtable(const char *table, const char *base, const char *searchPath) {
char *tableFile;
static struct stat info;
#define MAX_TABLEFILE_SIZE MAXSTRING * sizeof(char) * 2
if (table == NULL || table[0] == '\0') return NULL;
tableFile = (char *)malloc(MAX_TABLEFILE_SIZE);
if (base) {
int k;
if (strlen(base) >= MAX_TABLEFILE_SIZE) goto failure;
strcpy(tableFile, base);
k = (int)strlen(tableFile);
while (k >= 0 && tableFile[k] != '/' && tableFile[k] != '\\') k--;
tableFile[++k] = '\0';
if (strlen(tableFile) + strlen(table) >= MAX_TABLEFILE_SIZE) goto failure;
strcat(tableFile, table);
if (stat(tableFile, &info) == 0 && !(info.st_mode & S_IFDIR)) {
_lou_logMessage(LOU_LOG_DEBUG, "found table %s", tableFile);
return tableFile;
}
}
if (strlen(table) >= MAX_TABLEFILE_SIZE) goto failure;
strcpy(tableFile, table);
if (stat(tableFile, &info) == 0 && !(info.st_mode & S_IFDIR)) {
_lou_logMessage(LOU_LOG_DEBUG, "found table %s", tableFile);
return tableFile;
}
if (searchPath[0] != '\0') {
char *dir;
int last;
char *cp;
char *searchPath_copy = strdup(searchPath);
for (dir = searchPath_copy;; dir = cp + 1) {
for (cp = dir; *cp != '\0' && *cp != ','; cp++)
;
last = (*cp == '\0');
*cp = '\0';
if (dir == cp) dir = ".";
if (strlen(dir) + strlen(table) + 1 >= MAX_TABLEFILE_SIZE) {
free(searchPath_copy);
goto failure;
}
sprintf(tableFile, "%s%c%s", dir, DIR_SEP, table);
if (stat(tableFile, &info) == 0 && !(info.st_mode & S_IFDIR)) {
_lou_logMessage(LOU_LOG_DEBUG, "found table %s", tableFile);
free(searchPath_copy);
return tableFile;
}
if (last) break;
if (strlen(dir) + strlen("liblouis") + strlen("tables") + strlen(table) + 3 >=
MAX_TABLEFILE_SIZE) {
free(searchPath_copy);
goto failure;
}
sprintf(tableFile, "%s%c%s%c%s%c%s", dir, DIR_SEP, "liblouis", DIR_SEP,
"tables", DIR_SEP, table);
if (stat(tableFile, &info) == 0 && !(info.st_mode & S_IFDIR)) {
_lou_logMessage(LOU_LOG_DEBUG, "found table %s", tableFile);
free(searchPath_copy);
return tableFile;
}
if (last) break;
}
free(searchPath_copy);
}
failure:
free(tableFile);
return NULL;
}

static void WriteTo8BimProfile(Image *image,const char *name,
const StringInfo *profile)
{
const unsigned char
*datum,
*q;
register const unsigned char
*p;
size_t
length;
StringInfo
*profile_8bim;
ssize_t
count;
unsigned char
length_byte;
unsigned int
value;
unsigned short
id,
profile_id;
if (LocaleCompare(name,"icc") == 0)
profile_id=0x040f;
else
if (LocaleCompare(name,"iptc") == 0)
profile_id=0x0404;
else
if (LocaleCompare(name,"xmp") == 0)
profile_id=0x0424;
else
return;
profile_8bim=(StringInfo *) GetValueFromSplayTree((SplayTreeInfo *)
image->profiles,"8bim");
if (profile_8bim == (StringInfo *) NULL)
return;
datum=GetStringInfoDatum(profile_8bim);
length=GetStringInfoLength(profile_8bim);
for (p=datum; p < (datum+length-16); )
{
q=p;
if (LocaleNCompare((char *) p,"8BIM",4) != 0)
break;
p+=4;
p=ReadResourceShort(p,&id);
p=ReadResourceByte(p,&length_byte);
p+=length_byte;
if (((length_byte+1) & 0x01) != 0)
p++;
if (p > (datum+length-4))
break;
p=ReadResourceLong(p,&value);
count=(ssize_t) value;
if ((count & 0x01) != 0)
count++;
if ((p > (datum+length-count)) || (count > (ssize_t) length))
break;
if (id != profile_id)
p+=count;
else
{
size_t
extent,
offset;
ssize_t
extract_extent;
StringInfo
*extract_profile;
extract_extent=0;
extent=(datum+length)-(p+count);
if (profile == (StringInfo *) NULL)
{
offset=(q-datum);
extract_profile=AcquireStringInfo(offset+extent);
(void) CopyMagickMemory(extract_profile->datum,datum,offset);
}
else
{
offset=(p-datum);
extract_extent=profile->length;
if ((extract_extent & 0x01) != 0)
extract_extent++;
extract_profile=AcquireStringInfo(offset+extract_extent+extent);
(void) CopyMagickMemory(extract_profile->datum,datum,offset-4);
(void) WriteResourceLong(extract_profile->datum+offset-4,
(unsigned int) profile->length);
(void) CopyMagickMemory(extract_profile->datum+offset,
profile->datum,profile->length);
}
(void) CopyMagickMemory(extract_profile->datum+offset+extract_extent,
p+count,extent);
(void) AddValueToSplayTree((SplayTreeInfo *) image->profiles,
ConstantString("8bim"),CloneStringInfo(extract_profile));
extract_profile=DestroyStringInfo(extract_profile);
break;
}
}
}

bool
bfd_init_section_decompress_status (bfd *abfd, sec_ptr sec)
{
bfd_byte header[MAX_COMPRESSION_HEADER_SIZE];
int compression_header_size;
int header_size;
bfd_size_type uncompressed_size;
unsigned int uncompressed_alignment_power = 0;
unsigned int ch_type;
z_stream strm;
compression_header_size = bfd_get_compression_header_size (abfd, sec);
if (compression_header_size > MAX_COMPRESSION_HEADER_SIZE)
abort ();
header_size = compression_header_size ? compression_header_size : 12;
if (sec->rawsize != 0
|| sec->contents != NULL
|| sec->compress_status != COMPRESS_SECTION_NONE
|| !bfd_get_section_contents (abfd, sec, header, 0, header_size))
{
bfd_set_error (bfd_error_invalid_operation);
return false;
}
if (compression_header_size == 0)
{
if (! startswith ((char*) header, "ZLIB"))
{
bfd_set_error (bfd_error_wrong_format);
return false;
}
uncompressed_size = bfd_getb64 (header + 4);
}
else if (!bfd_check_compression_header (abfd, header, sec,
&ch_type,
&uncompressed_size,
&uncompressed_alignment_power))
{
bfd_set_error (bfd_error_wrong_format);
return false;
}
strm.avail_in = sec->size;
strm.avail_out = uncompressed_size;
if (strm.avail_in != sec->size || strm.avail_out != uncompressed_size)
{
bfd_set_error (bfd_error_nonrepresentable_section);
return false;
}
sec->compressed_size = sec->size;
sec->size = uncompressed_size;
bfd_set_section_alignment (sec, uncompressed_alignment_power);
sec->compress_status = (ch_type == ELFCOMPRESS_ZSTD
? DECOMPRESS_SECTION_ZSTD : DECOMPRESS_SECTION_ZLIB);
return true;
}

void
send_ldap_result_ext(
Slapi_PBlock *pb,
int err,
char *matched,
char *text,
int nentries,
struct berval **urls,
BerElement *ber)
{
Slapi_Operation *operation;
passwdPolicy *pwpolicy = NULL;
Connection *conn = NULL;
Slapi_DN *sdn = NULL;
const char *dn = NULL;
ber_tag_t tag;
int flush_ber_element = 1;
ber_tag_t bind_method = 0;
int internal_op;
int i, rc, logit = 0;
char *pbtext;
slapi_pblock_get(pb, SLAPI_BIND_METHOD, &bind_method);
slapi_pblock_get(pb, SLAPI_OPERATION, &operation);
slapi_pblock_get(pb, SLAPI_CONNECTION, &conn);
if (text) {
pbtext = text;
} else {
slapi_pblock_get(pb, SLAPI_PB_RESULT_TEXT, &pbtext);
}
if (operation == NULL) {
slapi_log_err(SLAPI_LOG_ERR, "send_ldap_result_ext", "No operation found: slapi_search_internal_set_pb was incomplete (invalid 'base' ?)\n");
return;
}
if (operation->o_status == SLAPI_OP_STATUS_RESULT_SENT) {
return; 
}
if (ber != NULL) {
flush_ber_element = 0;
}
if (err != LDAP_SUCCESS) {
if (err == LDAP_INVALID_CREDENTIALS || err == LDAP_INAPPROPRIATE_AUTH || err == LDAP_AUTH_METHOD_NOT_SUPPORTED || err == LDAP_STRONG_AUTH_NOT_SUPPORTED || err == LDAP_STRONG_AUTH_REQUIRED || err == LDAP_CONFIDENTIALITY_REQUIRED || err == LDAP_INSUFFICIENT_ACCESS || err == LDAP_AUTH_UNKNOWN) {
slapi_counter_increment(g_get_global_snmp_vars()->ops_tbl.dsSecurityErrors);
} else if (err != LDAP_REFERRAL && err != LDAP_OPT_REFERRALS && err != LDAP_PARTIAL_RESULTS) {
slapi_counter_increment(g_get_global_snmp_vars()->ops_tbl.dsErrors);
}
}
slapi_log_err(SLAPI_LOG_TRACE, "send_ldap_result_ext", "=> %d:%s:%s\n", err,
matched ? matched : "", text ? text : "");
switch (operation->o_tag) {
case LBER_DEFAULT:
tag = LBER_SEQUENCE;
break;
case LDAP_REQ_SEARCH:
tag = LDAP_RES_SEARCH_RESULT;
break;
case LDAP_REQ_DELETE:
tag = LDAP_RES_DELETE;
break;
case LDAP_REFERRAL:
if (conn && conn->c_ldapversion > LDAP_VERSION2) {
tag = LDAP_TAG_REFERRAL;
break;
}
default:
tag = operation->o_tag + 1;
break;
}
internal_op = operation_is_flag_set(operation, OP_FLAG_INTERNAL);
if ((conn == NULL) || (internal_op)) {
if (operation->o_result_handler != NULL) {
operation->o_result_handler(conn, operation, err,
matched, text, nentries, urls);
logit = 1;
}
goto log_and_return;
}
if ((err == LDAP_INVALID_CREDENTIALS) && (bind_method != LDAP_AUTH_SASL)) {
slapi_pblock_get(pb, SLAPI_TARGET_SDN, &sdn);
dn = slapi_sdn_get_dn(sdn);
pwpolicy = new_passwdPolicy(pb, dn);
if (pwpolicy && (pwpolicy->pw_lockout == 1)) {
if (update_pw_retry(pb) == LDAP_CONSTRAINT_VIOLATION && !pwpolicy->pw_is_legacy) {
err = LDAP_CONSTRAINT_VIOLATION;
text = "Invalid credentials, you now have exceeded the password retry limit.";
}
}
}
if (ber == NULL) {
if ((ber = der_alloc()) == NULL) {
slapi_log_err(SLAPI_LOG_ERR, "send_ldap_result_ext", "ber_alloc failed\n");
goto log_and_return;
}
}
if (err == LDAP_ADMINLIMIT_EXCEEDED &&
conn->c_ldapversion < LDAP_VERSION3) {
err = LDAP_SIZELIMIT_EXCEEDED;
}
if (conn->c_ldapversion < LDAP_VERSION3 || urls == NULL) {
char *save, *buf = NULL;
if (urls != NULL) {
int len;
slapi_counter_increment(g_get_global_snmp_vars()->ops_tbl.dsReferrals);
len = 10; 
for (i = 0; urls[i] != NULL; i++) {
len += urls[i]->bv_len + 1; 
}
if (text != NULL) {
len += strlen(text) + 1; 
}
buf = slapi_ch_malloc(len);
*buf = '\0';
if (text != NULL) {
strcpy(buf, text);
strcat(buf, "\n");
}
strcat(buf, "Referral:");
for (i = 0; urls[i] != NULL; i++) {
strcat(buf, "\n");
strcat(buf, urls[i]->bv_val);
}
save = text;
text = buf;
}
if ((conn->c_ldapversion < LDAP_VERSION3 &&
err == LDAP_REFERRAL) ||
urls != NULL) {
err = LDAP_PARTIAL_RESULTS;
}
rc = ber_printf(ber, "{it{ess", operation->o_msgid, tag, err,
matched ? matched : "", pbtext ? pbtext : "");
if (rc != LBER_ERROR) {
rc = check_and_send_extended_result(pb, tag, ber);
}
if (rc != LBER_ERROR) {
rc = check_and_send_SASL_response(pb, tag, ber, conn);
}
if (rc != LBER_ERROR) {
rc = ber_printf(ber, "}"); 
}
if (buf != NULL) {
text = save;
slapi_ch_free((void **)&buf);
}
} else {
if (!config_check_referral_mode())
slapi_counter_increment(g_get_global_snmp_vars()->ops_tbl.dsReferrals);
rc = ber_printf(ber, "{it{esst{s", operation->o_msgid, tag, err,
matched ? matched : "", text ? text : "", LDAP_TAG_REFERRAL,
urls[0]->bv_val);
for (i = 1; urls[i] != NULL && rc != LBER_ERROR; i++) {
rc = ber_printf(ber, "s", urls[i]->bv_val);
}
if (rc != LBER_ERROR) {
rc = ber_printf(ber, "}"); 
}
if (rc != LBER_ERROR) {
rc = check_and_send_extended_result(pb, tag, ber);
}
if (rc != LBER_ERROR) {
rc = check_and_send_SASL_response(pb, tag, ber, conn);
}
if (rc != LBER_ERROR) {
rc = ber_printf(ber, "}"); 
}
}
if (err == LDAP_SUCCESS) {
if (process_read_entry_controls(pb, LDAP_CONTROL_PRE_READ_ENTRY)) {
err = LDAP_UNAVAILABLE_CRITICAL_EXTENSION;
goto log_and_return;
}
if (process_read_entry_controls(pb, LDAP_CONTROL_POST_READ_ENTRY)) {
err = LDAP_UNAVAILABLE_CRITICAL_EXTENSION;
goto log_and_return;
}
}
if (operation->o_results.result_controls != NULL && conn->c_ldapversion >= LDAP_VERSION3 && write_controls(ber, operation->o_results.result_controls) != 0) {
rc = (int)LBER_ERROR;
}
if (rc != LBER_ERROR) { 
rc = ber_put_seq(ber);
}
if (rc == LBER_ERROR) {
slapi_log_err(SLAPI_LOG_ERR, "send_ldap_result_ext", "ber_printf failed 1\n");
if (flush_ber_element == 1) {
ber_free(ber, 1 );
}
goto log_and_return;
}
if (flush_ber_element) {
if (flush_ber(pb, conn, operation, ber, _LDAP_SEND_RESULT) == 0) {
logit = 1;
}
}
log_and_return:
operation->o_status = SLAPI_OP_STATUS_RESULT_SENT; 
if (logit && (operation_is_flag_set(operation, OP_FLAG_ACTION_LOG_ACCESS) ||
(internal_op && config_get_plugin_logging()))) {
log_result(pb, operation, err, tag, nentries);
}
slapi_log_err(SLAPI_LOG_TRACE, "send_ldap_result_ext", "<= %d\n", err);
}

