void Converter::cnvExifDate(const char* from, const char* to)
{
Exiv2::ExifData::iterator pos = exifData_->findKey(ExifKey(from));
if (pos == exifData_->end()) return;
if (!prepareXmpTarget(to)) return;
int year=0, month=0, day=0, hour=0, min=0, sec=0;
std::string subsec;
char buf[30];
if (std::string(from) != "Exif.GPSInfo.GPSTimeStamp") {
std::string value = pos->toString();
if (!pos->value().ok()) {
#ifndef SUPPRESS_WARNINGS
EXV_WARNING << "Failed to convert " << from << " to " << to << "\n";
#endif
return;
}
if (sscanf(value.c_str(), "%d:%d:%d %d:%d:%d", &year, &month, &day, &hour, &min, &sec) != 6) {
#ifndef SUPPRESS_WARNINGS
EXV_WARNING << "Failed to convert " << from << " to " << to
<< ", unable to parse '" << value << "'\n";
#endif
return;
}
}
else { 
bool ok = true;
if (pos->count() != 3) ok = false;
if (ok) {
for (int i = 0; i < 3; ++i) {
if (pos->toRational(i).second == 0) {
ok = false;
break;
}
}
}
if (!ok) {
#ifndef SUPPRESS_WARNINGS
EXV_WARNING << "Failed to convert " << from << " to " << to << "\n";
#endif
return;
}
double dhour = pos->toFloat(0);
double dmin = pos->toFloat(1);
Rational r = pos->toRational(2);
double dsec = static_cast<double>(r.first)/r.second;
if (!pos->value().ok()) {
#ifndef SUPPRESS_WARNINGS
EXV_WARNING << "Failed to convert " << from << " to " << to << "\n";
#endif
return;
}
dsec = dhour * 3600.0 + dmin * 60.0 + dsec;
hour = static_cast<int>(dsec / 3600.0);
dsec -= hour * 3600;
min = static_cast<int>(dsec / 60.0);
dsec -= min * 60;
sec = static_cast<int>(dsec);
dsec -= sec;
snprintf(buf, sizeof(buf), "%.9f", dsec);
buf[sizeof(buf) - 1] = 0;
buf[1] = '.';             subsec = buf + 1;
Exiv2::ExifData::iterator datePos = exifData_->findKey(ExifKey("Exif.GPSInfo.GPSDateStamp"));
if (datePos == exifData_->end()) {
datePos = exifData_->findKey(ExifKey("Exif.Photo.DateTimeOriginal"));
}
if (datePos == exifData_->end()) {
datePos = exifData_->findKey(ExifKey("Exif.Photo.DateTimeDigitized"));
}
if (datePos == exifData_->end()) {
#ifndef SUPPRESS_WARNINGS
EXV_WARNING << "Failed to convert " << from << " to " << to << "\n";
#endif
return;
}
std::string value = datePos->toString();
if (sscanf(value.c_str(), "%d:%d:%d", &year, &month, &day) != 3) {
#ifndef SUPPRESS_WARNINGS
EXV_WARNING << "Failed to convert " << from << " to " << to
<< ", unable to parse '" << value << "'\n";
#endif
return;
}
}
const char* subsecTag = 0;
if (std::string(from) == "Exif.Image.DateTime") {
subsecTag = "Exif.Photo.SubSecTime";
}
else if (std::string(from) == "Exif.Photo.DateTimeOriginal") {
subsecTag = "Exif.Photo.SubSecTimeOriginal";
}
else if (std::string(from) == "Exif.Photo.DateTimeDigitized") {
subsecTag = "Exif.Photo.SubSecTimeDigitized";
}
if (subsecTag) {
ExifData::iterator subsec_pos = exifData_->findKey(ExifKey(subsecTag));
if (   subsec_pos != exifData_->end()
&& subsec_pos->typeId() == asciiString) {
std::string ss = subsec_pos->toString();
if (!ss.empty()) {
bool ok = false;
stringTo<long>(ss, ok);
if (ok) subsec = std::string(".") + ss;
}
}
if (erase_) exifData_->erase(subsec_pos);
}
if (subsec.size() > 10) subsec = subsec.substr(0, 10);
snprintf(buf, sizeof(buf), "%4d-%02d-%02dT%02d:%02d:%02d%s",
year, month, day, hour, min, sec, subsec.c_str());
buf[sizeof(buf) - 1] = 0;
(*xmpData_)[to] = buf;
if (erase_) exifData_->erase(pos);
}

int AVI_read_frame(avi_t *AVI, u8 *vidbuf, int *keyframe)
{
int n;
if(AVI->mode==AVI_MODE_WRITE) {
AVI_errno = AVI_ERR_NOT_PERM;
return -1;
}
if(!AVI->video_index)         {
AVI_errno = AVI_ERR_NO_IDX;
return -1;
}
if(AVI->video_pos < 0 || AVI->video_pos >= AVI->video_frames) return -1;
n = (u32) AVI->video_index[AVI->video_pos].len;
*keyframe = (AVI->video_index[AVI->video_pos].key==0x10) ? 1:0;
if (vidbuf == NULL) {
AVI->video_pos++;
return n;
}
gf_fseek(AVI->fdes, AVI->video_index[AVI->video_pos].pos, SEEK_SET);
if (avi_read(AVI->fdes,vidbuf,n) != (u32) n)
{
AVI_errno = AVI_ERR_READ;
return -1;
}
AVI->video_pos++;
return n;
}

void *
get_layer4_v6(const ipv6_hdr_t *ip6_hdr, const int l3len)
{
struct tcpr_ipv6_ext_hdr_base *next, *exthdr;
bool done = false;
uint32_t maxlen;
uint8_t proto;
int min_len;
assert(ip6_hdr);
min_len = TCPR_IPV6_H + sizeof(struct tcpr_ipv6_ext_hdr_base);
if (l3len < min_len)
return NULL;
next = (struct tcpr_ipv6_ext_hdr_base *)((u_char *)ip6_hdr + TCPR_IPV6_H);
proto = ip6_hdr->ip_nh;
while (!done) {
dbgx(3, "Processing proto: 0x%hx", (uint16_t)proto);
switch (proto) {
case TCPR_IPV6_NH_IPV6:
dbg(3, "recursing due to v6-in-v6");
next = get_layer4_v6((ipv6_hdr_t *)next, l3len - min_len);
break;
case TCPR_IPV6_NH_AH:
case TCPR_IPV6_NH_ROUTING:
case TCPR_IPV6_NH_DESTOPTS:
case TCPR_IPV6_NH_HBH:
dbgx(3, "Going deeper due to extension header 0x%02X", proto);
maxlen = l3len - (int)((u_char *)ip6_hdr - (u_char *)next);
exthdr = get_ipv6_next(next, maxlen);
if (exthdr == NULL) {
done = true;
break;
}
proto = exthdr->ip_nh;
next = exthdr;
break;
case TCPR_IPV6_NH_FRAGMENT:
case TCPR_IPV6_NH_ESP:
next = NULL;
done = true;
break;
default:
if (proto != ip6_hdr->ip_nh) {
dbgx(3, "Returning byte offset of this ext header: %u", 
IPV6_EXTLEN_TO_BYTES(next->ip_len));
next =  (void *)((u_char *)next + IPV6_EXTLEN_TO_BYTES(next->ip_len));
} else {
dbgx(3, "%s", "Returning end of IPv6 Header");
}
done = true;
} 
} 
if (!next || (u_char*)next > (u_char*)ip6_hdr + l3len)
return NULL;
return next;
}

int fuse_dev_release(struct inode *inode, struct file *file)
{
struct fuse_conn *fc = fuse_get_conn(file);
if (fc) {
WARN_ON(!list_empty(&fc->pq.io));
WARN_ON(fc->iq.fasync != NULL);
fuse_abort_conn(fc);
fuse_conn_put(fc);
}
return 0;
}

static void check_multi_info(ogs_sbi_client_t *client)
{
CURLM *multi = NULL;
CURLMsg *resource;
int pending;
CURL *easy = NULL;
CURLcode res;
connection_t *conn = NULL;
ogs_sbi_response_t *response = NULL;
ogs_assert(client);
multi = client->multi;
ogs_assert(multi);
while ((resource = curl_multi_info_read(multi, &pending))) {
char *url;
char *content_type = NULL;
long res_status;
ogs_assert(resource);
switch (resource->msg) {
case CURLMSG_DONE:
easy = resource->easy_handle;
ogs_assert(easy);
curl_easy_getinfo(easy, CURLINFO_PRIVATE, &conn);
ogs_assert(conn);
curl_easy_getinfo(easy, CURLINFO_EFFECTIVE_URL, &url);
curl_easy_getinfo(easy, CURLINFO_RESPONSE_CODE, &res_status);
curl_easy_getinfo(easy, CURLINFO_CONTENT_TYPE, &content_type);
res = resource->data.result;
if (res == CURLE_OK) {
response = ogs_sbi_response_new();
ogs_assert(response);
response->status = res_status;
ogs_assert(conn->method);
response->h.method = ogs_strdup(conn->method);
ogs_assert(response->h.method);
/* remove https:                response->h.uri = ogs_strdup(url);
ogs_assert(response->h.uri);
ogs_debug("[%d:%s] %s",
response->status, response->h.method, response->h.uri);
if (conn->memory) {
response->http.content =
ogs_memdup(conn->memory, conn->size + 1);
ogs_assert(response->http.content);
response->http.content_length = conn->size;
ogs_assert(response->http.content_length);
}
ogs_debug("RECEIVED[%d]", (int)response->http.content_length);
if (response->http.content_length && response->http.content)
ogs_debug("%s", response->http.content);
if (content_type)
ogs_sbi_header_set(response->http.headers,
OGS_SBI_CONTENT_TYPE, content_type);
if (conn->location)
ogs_sbi_header_set(response->http.headers,
OGS_SBI_LOCATION, conn->location);
} else
ogs_warn("[%d] %s", res, conn->error);
ogs_assert(conn->client_cb);
conn->client_cb(res == CURLE_OK ? OGS_OK : OGS_ERROR,
response, conn->data);
connection_remove(conn);
break;
default:
ogs_error("Unknown CURL resource[%d]", resource->msg);
break;
}
}
