{
if (ufunc->uf_ret_type->tt_type == VAR_UNKNOWN)
ufunc->uf_ret_type = &t_void;
else if (ufunc->uf_ret_type->tt_type != VAR_VOID)
{
emsg(_(e_missing_return_statement));
goto erret;
}
generate_instr(&cctx, ISN_RETURN_VOID);
}
if (emsg_silent == 0 || did_emsg_silent == did_emsg_silent_before)
{
dfunc_T*dfunc = ((dfunc_T *)def_functions.ga_data)
+ ufunc->uf_dfunc_idx;
dfunc->df_deleted = FALSE;
dfunc->df_script_seq = current_sctx.sc_seq;
#ifdef FEAT_PROFILE
if (cctx.ctx_compile_type == CT_PROFILE)
{
dfunc->df_instr_prof = instr->ga_data;
dfunc->df_instr_prof_count = instr->ga_len;
}
else
#endif
if (cctx.ctx_compile_type == CT_DEBUG)
{
dfunc->df_instr_debug = instr->ga_data;
dfunc->df_instr_debug_count = instr->ga_len;
}
else
{
dfunc->df_instr = instr->ga_data;
dfunc->df_instr_count = instr->ga_len;
}
dfunc->df_varcount = dfunc->df_var_names.ga_len;
dfunc->df_has_closure = cctx.ctx_has_closure;
if (cctx.ctx_outer_used)
ufunc->uf_flags |= FC_CLOSURE;
ufunc->uf_def_status = UF_COMPILED;
}
ret = OK;
erret:
if (ufunc->uf_def_status == UF_COMPILING)
{
dfunc_T*dfunc = ((dfunc_T *)def_functions.ga_data)
+ ufunc->uf_dfunc_idx;
clear_instr_ga(instr);
VIM_CLEAR(dfunc->df_name);
ga_clear_strings(&dfunc->df_var_names);
if (!dfunc->df_deleted && new_def_function
&& ufunc->uf_dfunc_idx == def_functions.ga_len - 1)
{
--def_functions.ga_len;
ufunc->uf_dfunc_idx = 0;
}
ufunc->uf_def_status = UF_COMPILE_ERROR;
while (cctx.ctx_scope != NULL)
drop_scope(&cctx);
if (errormsg != NULL)
emsg(errormsg);
else if (did_emsg == did_emsg_before)
emsg(_(e_compiling_def_function_failed));
}
if (cctx.ctx_redir_lhs.lhs_name != NULL)
{
if (ret == OK)
{
emsg(_(e_missing_redir_end));
ret = FAIL;
}
vim_free(cctx.ctx_redir_lhs.lhs_name);
vim_free(cctx.ctx_redir_lhs.lhs_whole);
}
current_sctx = save_current_sctx;
estack_compiling = save_estack_compiling;
cmdmod.cmod_flags =save_cmod_flags;
if (do_estack_push)
estack_pop();
vim_free(line_to_free);
free_imported(&cctx);
free_locals(&cctx);
ga_clear(&cctx.ctx_type_stack);
return ret;
}

static int stream_process(struct sip_msg * msg, struct sdp_stream_cell *cell,
str * s, str* ss, regex_t* re, int op,int description)
{
static sdp_payload_attr_t static_payloads[] = {
{ NULL,0,{ "3",1},{ "GSM",3},{ "8000",4},{NULL,0},{NULL,0} },   
{ NULL,0,{ "4",1},{"G723",4},{ "8000",4},{NULL,0},{NULL,0} },   
{ NULL,0,{ "5",1},{"DVI4",4},{ "8000",4},{NULL,0},{NULL,0} },   
{ NULL,0,{ "6",1},{"DVI4",4},{"16000",5},{NULL,0},{NULL,0} },   
{ NULL,0,{ "7",1},{ "LPC",3},{ "8000",4},{NULL,0},{NULL,0} },   
{ NULL,0,{ "8",1},{"PCMA",4},{ "8000",4},{NULL,0},{NULL,0} },   
{ NULL,0,{ "9",1},{"G722",4},{ "8000",4},{NULL,0},{NULL,0} },   
{ NULL,0,{"10",2},{ "L16",3},{"44100",5},{NULL,0},{NULL,0} },   
{ NULL,0,{"11",2},{ "L16",3},{"44100",5},{NULL,0},{NULL,0} },   
{ NULL,0,{"12",2},{"QCELP",5},{"8000",4},{NULL,0},{NULL,0} },   
{ NULL,0,{"13",2},{  "CN",2},{ "8000",4},{NULL,0},{NULL,0} },   
{ NULL,0,{"14",2},{ "MPA",3},{"90000",5},{NULL,0},{NULL,0} },   
{ NULL,0,{"15",2},{"G728",4},{ "8000",4},{NULL,0},{NULL,0} },   
{ NULL,0,{"16",2},{"DVI4",4},{"11025",5},{NULL,0},{NULL,0} },   
{ NULL,0,{"17",2},{"DVI4",4},{"22050",5},{NULL,0},{NULL,0} },   
{ NULL,0,{"18",2},{"G729",4},{ "8000",4},{NULL,0},{NULL,0} },   
{ NULL,0,{"25",2},{"CelB",4},{ "8000",4},{NULL,0},{NULL,0} },   
{ NULL,0,{"26",2},{"JPEG",4},{"90000",5},{NULL,0},{NULL,0} },   
{ NULL,0,{"28",2},{  "nv",2},{"90000",5},{NULL,0},{NULL,0} },   
{ NULL,0,{"31",2},{"H261",4},{"90000",5},{NULL,0},{NULL,0} },   
{ NULL,0,{"32",2},{ "MPV",3},{"90000",5},{NULL,0},{NULL,0} },   
{ NULL,0,{"33",2},{"MP2T",4},{"90000",5},{NULL,0},{NULL,0} },   
{ NULL,0,{"34",2},{"H263",4},{"90000",5},{NULL,0},{NULL,0} },   
{ NULL,0,{"t38",3},{"t38",3},{     "",0},{NULL,0},{NULL,0} },   
{ NULL,0,{NULL,0},{  NULL,0},{   NULL,0},{NULL,0},{NULL,0} }
};
sdp_payload_attr_t *payload;
char *cur, *tmp, *buff, temp;
struct lump * lmp;
str found;
int ret, i,match, buff_len, is_static;
regmatch_t pmatch;
lmp = get_associated_lump(msg, cell);
if( lmp == NULL)
{
LM_ERR("There is no lump for this sdp cell\n");
return -1;
}
if (lmp->len == 0)
return -1;
buff_len = 0;
ret = 0;
buff = pkg_malloc(lmp->len+1);
if( buff == NULL)
{
LM_ERR("Out of memory\n");
return -1;
}
is_static = 0;
payload = cell->payload_attr;
while(payload)
{
if( payload->rtp_enc.s == NULL
|| (payload->rtp_clock.s == NULL && ss != NULL)
|| payload->rtp_payload.s == NULL)
{
goto next_payload;
}
match = 0;
if( description == DESC_REGEXP ||description == DESC_REGEXP_COMPLEMENT )
{
if (is_static) {
match = regexec( re, payload->rtp_enc.s, 1, &pmatch, 0) == 0;
} else {
temp = payload->rtp_enc.s[payload->rtp_enc.len];
payload->rtp_enc.s[payload->rtp_enc.len] = 0;
match = regexec( re, payload->rtp_enc.s, 1, &pmatch, 0) == 0;
payload->rtp_enc.s[payload->rtp_enc.len] = temp;
}
}
if( description == DESC_REGEXP_COMPLEMENT)
match = !match;
if( description == DESC_NAME  )
{
match = s->len == payload->rtp_enc.len &&
strncasecmp( s->s, payload->rtp_enc.s ,payload->rtp_enc.len) == 0;
}
if( description == DESC_NAME_AND_CLOCK)
{
match = s->len == payload->rtp_enc.len &&
strncasecmp( s->s, payload->rtp_enc.s ,
payload->rtp_enc.len) == 0
&&
(ss == NULL || ( ss->len == payload->rtp_clock.len &&
strncasecmp( ss->s, payload->rtp_clock.s ,
payload->rtp_clock.len) == 0
) );
}
if (match) {
match = 0;
cur = lmp->u.value;
while( !match && cur < lmp->u.value + lmp->len)
{
found.s = cur;
while(  cur < lmp->u.value + lmp->len &&  *cur != ' ' )
cur++;
found.len = cur - found.s;
if ( found.len == payload->rtp_payload.len &&
strncmp( found.s,payload->rtp_payload.s,found.len) == 0) {
match = 1;
} else {
while( cur < lmp->u.value + lmp->len && * cur == ' '  )
cur++;
}
}
if (match) {
if(op == FIND)
{
ret = 1;
goto end;
}
if( op == DELETE && !is_static )
{
if( delete_sdp_line( msg, payload->rtp_enc.s, cell) < 0 )
{
LM_ERR("Unable to add delete lump for a=\n");
ret = -1;
goto end;
}
if( delete_sdp_line( msg, payload->fmtp_string.s, cell) < 0 )
{
LM_ERR("Unable to add delete lump for a=\n");
ret = -1;
goto end;
}
}
{
while (found.s > lmp->u.value && *(found.s - 1) == ' ') {
found.s--;
found.len++;
}
if (cur == lmp->u.value + lmp->len) {
tmp = found.s;
while (*(--tmp) == ' ') {
found.s--;
found.len++;
}
}
for(tmp=found.s ; tmp< lmp->u.value + lmp->len ; tmp++ )
*tmp  = *(tmp+found.len);
lmp->len -= found.len;
}
if( op == ADD_TO_FRONT  || op == ADD_TO_BACK)
{
memcpy(&buff[buff_len]," ",1);
buff_len++;
memcpy(&buff[buff_len],payload->rtp_payload.s,
payload->rtp_payload.len);
buff_len += payload->rtp_payload.len;
}
ret = 1;
}
}
next_payload:
if (!is_static) {
payload = payload->next;
if (payload==NULL) {
payload = static_payloads;
is_static = 1;
}
} else {
payload ++;
if (payload->rtp_payload.s==NULL)
payload=NULL;
}
}
if( op == ADD_TO_FRONT && buff_len >0 )
{
lmp->u.value = (char*)pkg_realloc(lmp->u.value, lmp->len+buff_len);
if(!lmp->u.value) {
LM_ERR("No more pkg memory\n");
ret = -1;
goto end;
}
for( i = lmp->len -1 ; i>=0;i--)
lmp->u.value[i+buff_len] = lmp->u.value[i];
memcpy(lmp->u.value,buff,buff_len);
lmp->len += buff_len;
}
if( op == ADD_TO_BACK && buff_len >0 )
{
lmp->u.value = (char*)pkg_realloc(lmp->u.value, lmp->len+buff_len);
if(!lmp->u.value) {
LM_ERR("No more pkg memory\n");
ret = -1;
goto end;
}
memcpy(&lmp->u.value[lmp->len],buff,buff_len);
lmp->len += buff_len;
}
if (lmp->len == 0) {
lmp = del_lump(msg, cell->port.s - msg->buf - 1, cell->port.len + 2, 0);
if (!lmp) {
LM_ERR("could not add lump to disable stream!\n");
goto end;
}
tmp = pkg_malloc(3);
if (!tmp) {
LM_ERR("oom for port 0\n");
goto end;
}
memcpy(tmp, " 0 ", 3);
if (!insert_new_lump_after(lmp, tmp, 3, 0))
LM_ERR("could not insert lump to disable stream!\n");
}
end:
pkg_free(buff);
return ret;
}

Id
repodata_schema2id(Repodata *data, Id *schema, int create)
{
int h, len, i;
Id *sp, cid;
Id *schematahash;
if (!*schema)
return 0;
if ((schematahash = data->schematahash) == 0)
{
data->schematahash = schematahash = solv_calloc(256, sizeof(Id));
for (i = 1; i < data->nschemata; i++)
{
for (sp = data->schemadata + data->schemata[i], h = 0; *sp;)
h = h * 7 + *sp++;
h &= 255;
schematahash[h] = i;
}
data->schemadata = solv_extend_resize(data->schemadata, data->schemadatalen, sizeof(Id), SCHEMATADATA_BLOCK);
data->schemata = solv_extend_resize(data->schemata, data->nschemata, sizeof(Id), SCHEMATA_BLOCK);
}
for (sp = schema, len = 0, h = 0; *sp; len++)
h = h * 7 + *sp++;
h &= 255;
len++;
cid = schematahash[h];
if (cid)
{
if (!memcmp(data->schemadata + data->schemata[cid], schema, len * sizeof(Id)))
return cid;
for (cid = 1; cid < data->nschemata; cid++)
if (!memcmp(data->schemadata + data->schemata[cid], schema, len * sizeof(Id)))
return cid;
}
if (!create)
return 0;
data->schemadata = solv_extend(data->schemadata, data->schemadatalen, len, sizeof(Id), SCHEMATADATA_BLOCK);
data->schemata = solv_extend(data->schemata, data->nschemata, 1, sizeof(Id), SCHEMATA_BLOCK);
memcpy(data->schemadata + data->schemadatalen, schema, len * sizeof(Id));
data->schemata[data->nschemata] = data->schemadatalen;
data->schemadatalen += len;
schematahash[h] = data->nschemata;
#if 0
fprintf(stderr, "schema2id: new schema\n");
#endif
return data->nschemata++;
}

static MagickBooleanType WriteMAPImage(const ImageInfo *image_info,Image *image)
{
MagickBooleanType
status;
register const IndexPacket
*indexes;
register const PixelPacket
*p;
register ssize_t
i,
x;
register unsigned char
*q;
size_t
depth,
packet_size;
ssize_t
y;
unsigned char
*colormap,
*pixels;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickSignature);
assert(image != (Image *) NULL);
assert(image->signature == MagickSignature);
if (image->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",image->filename);
status=OpenBlob(image_info,image,WriteBinaryBlobMode,&image->exception);
if (status == MagickFalse)
return(status);
(void) TransformImageColorspace(image,sRGBColorspace);
if (IsPaletteImage(image,&image->exception) == MagickFalse)
(void) SetImageType(image,PaletteType);
depth=GetImageQuantumDepth(image,MagickTrue);
packet_size=(size_t) (depth/8);
pixels=(unsigned char *) AcquireQuantumMemory(image->columns,packet_size*
sizeof(*pixels));
packet_size=(size_t) (image->colors > 256 ? 6UL : 3UL);
colormap=(unsigned char *) AcquireQuantumMemory(image->colors,packet_size*
sizeof(*colormap));
if ((pixels == (unsigned char *) NULL) ||
(colormap == (unsigned char *) NULL))
{
if (colormap != (unsigned char *) NULL)
colormap=(unsigned char *) RelinquishMagickMemory(colormap);
if (pixels != (unsigned char *) NULL)
pixels=(unsigned char *) RelinquishMagickMemory(pixels);
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
}
q=colormap;
if (image->colors <= 256)
for (i=0; i < (ssize_t) image->colors; i++)
{
*q++=(unsigned char) ScaleQuantumToChar(image->colormap[i].red);
*q++=(unsigned char) ScaleQuantumToChar(image->colormap[i].green);
*q++=(unsigned char) ScaleQuantumToChar(image->colormap[i].blue);
}
else
for (i=0; i < (ssize_t) image->colors; i++)
{
*q++=(unsigned char) (ScaleQuantumToShort(image->colormap[i].red) >> 8);
*q++=(unsigned char) (ScaleQuantumToShort(image->colormap[i].red) & 0xff);
*q++=(unsigned char) (ScaleQuantumToShort(image->colormap[i].green) >> 8);
*q++=(unsigned char) (ScaleQuantumToShort(image->colormap[i].green) &
0xff);
*q++=(unsigned char) (ScaleQuantumToShort(image->colormap[i].blue) >> 8);
*q++=(unsigned char) (ScaleQuantumToShort(image->colormap[i].blue) &
0xff);
}
(void) WriteBlob(image,packet_size*image->colors,colormap);
colormap=(unsigned char *) RelinquishMagickMemory(colormap);
for (y=0; y < (ssize_t) image->rows; y++)
{
p=GetVirtualPixels(image,0,y,image->columns,1,&image->exception);
if (p == (const PixelPacket *) NULL)
break;
indexes=GetVirtualIndexQueue(image);
q=pixels;
for (x=0; x < (ssize_t) image->columns; x++)
{
if (image->colors > 256)
*q++=(unsigned char) ((size_t) GetPixelIndex(indexes+x) >> 8);
*q++=(unsigned char) GetPixelIndex(indexes+x);
}
(void) WriteBlob(image,(size_t) (q-pixels),pixels);
}
pixels=(unsigned char *) RelinquishMagickMemory(pixels);
(void) CloseBlob(image);
return(status);
}

std::string encodeBase64(const std::string& input) {
using namespace boost::archive::iterators;
using b64it = base64_from_binary<transform_width<const char*, 6, 8>>;
auto data = input.data();
std::string encoded(b64it(data), b64it(data + (input.length())));
encoded.append((3 - (input.length() % 3)) % 3, '=');
return encoded;
}

