# if defined(MSWIN)
|| vim_ispathsep(ff_file_to_find[0])
|| (ff_file_to_find[0] != NUL && ff_file_to_find[1] == ':')
# endif
# ifdef AMIGA
|| ff_file_to_find[0] == ':'
# endif
)
{
if (first == TRUE)
{
intl;
intrun;
if (path_with_url(ff_file_to_find))
{
file_name = vim_strsave(ff_file_to_find);
goto theend;
}
for (run = 1; run <= 2; ++run)
{
l = (int)STRLEN(ff_file_to_find);
if (run == 1
&& rel_to_curdir
&& (options & FNAME_REL)
&& rel_fname != NULL
&& STRLEN(rel_fname) + l < MAXPATHL)
{
STRCPY(NameBuff, rel_fname);
STRCPY(gettail(NameBuff), ff_file_to_find);
l = (int)STRLEN(NameBuff);
}
else
{
STRCPY(NameBuff, ff_file_to_find);
run = 2;
}
buf = suffixes;
for (;;)
{
if (mch_getperm(NameBuff) >= 0
&& (find_what == FINDFILE_BOTH
|| ((find_what == FINDFILE_DIR)
== mch_isdir(NameBuff))))
{
file_name = vim_strsave(NameBuff);
goto theend;
}
if (*buf == NUL)
break;
copy_option_part(&buf, NameBuff + l, MAXPATHL - l, ",");
}
}
}
}
else
{
if (first == TRUE)
{
vim_findfile_free_visited(fdip_search_ctx);
dir = path_option;
did_findfile_init = FALSE;
}
for (;;)
{
if (did_findfile_init)
{
file_name = vim_findfile(fdip_search_ctx);
if (file_name != NULL)
break;
did_findfile_init = FALSE;
}
else
{
char_u  *r_ptr;
if (dir == NULL || *dir == NUL)
{
vim_findfile_cleanup(fdip_search_ctx);
fdip_search_ctx = NULL;
break;
}
if ((buf = alloc(MAXPATHL)) == NULL)
break;
buf[0] = 0;
copy_option_part(&dir, buf, MAXPATHL, " ,");
# ifdef FEAT_PATH_EXTRA
r_ptr = vim_findfile_stopdir(buf);
# else
r_ptr = NULL;
# endif
fdip_search_ctx = vim_findfile_init(buf, ff_file_to_find,
r_ptr, 100, FALSE, find_what,
fdip_search_ctx, FALSE, rel_fname);
if (fdip_search_ctx != NULL)
did_findfile_init = TRUE;
vim_free(buf);
}
}
}
if (file_name == NULL && (options & FNAME_MESS))
{
if (first == TRUE)
{
if (find_what == FINDFILE_DIR)
semsg(_("E344: Can't find directory \"%s\" in cdpath"),
ff_file_to_find);
else
semsg(_("E345: Can't find file \"%s\" in path"),
ff_file_to_find);
}
else
{
if (find_what == FINDFILE_DIR)
semsg(_("E346: No more directory \"%s\" found in cdpath"),
ff_file_to_find);
else
semsg(_("E347: No more file \"%s\" found in path"),
ff_file_to_find);
}
}
theend:
# ifdef AMIGA
proc->pr_WindowPtr = save_winptr;
# endif
return file_name;
}

void
wiki_handle_rest_call(HttpRequest  *req, 
HttpResponse *res,
char         *func)
{
if (func != NULL && *func != '\0')
{
if (!strcmp(func, "page/get"))
{
char *page = http_request_param_get(req, "page");
if (page == NULL)
page = http_request_get_query_string(req);
if (page && (access(page, R_OK) == 0)) 
{
http_response_printf(res, "%s", file_read(page));
http_response_send(res);
return;
}  
}
else if (!strcmp(func, "page/set"))
{
char *wikitext = NULL, *page = NULL;
if( ( (wikitext = http_request_param_get(req, "text")) != NULL)
&& ( (page = http_request_param_get(req, "page")) != NULL))
{
file_write(page, wikitext);      
http_response_printf(res, "success");
http_response_send(res);
return;
}
}
else if (!strcmp(func, "page/delete"))
{
char *page = http_request_param_get(req, "page");
if (page == NULL)
page = http_request_get_query_string(req);
if (page && (unlink(page) > 0))
{
http_response_printf(res, "success");
http_response_send(res);
return;  
}
}
else if (!strcmp(func, "page/exists"))
{
char *page = http_request_param_get(req, "page");
if (page == NULL)
page = http_request_get_query_string(req);
if (page && (access(page, R_OK) == 0)) 
{
http_response_printf(res, "success");
http_response_send(res);
return;  
}
}
else if (!strcmp(func, "pages") || !strcmp(func, "search"))
{
WikiPageList **pages = NULL;
int            n_pages, i;
char          *expr = http_request_param_get(req, "expr");
if (expr == NULL)
expr = http_request_get_query_string(req);
pages = wiki_get_pages(&n_pages, expr);
if (pages)
{
for (i=0; i<n_pages; i++)
{
struct tm   *pTm;
char   datebuf[64];
pTm = localtime(&pages[i]->mtime);
strftime(datebuf, sizeof(datebuf), "%Y-%m-%d %H:%M", pTm);
http_response_printf(res, "%s\t%s\n", pages[i]->name, datebuf);
}
http_response_send(res);
return;  
}
}
}
http_response_set_status(res, 500, "Error");
http_response_printf(res, "<html><body>Failed</body></html>\n");
http_response_send(res);
return;  
}

static GF_Err gf_sm_load_run_isom(GF_SceneLoader *load)
{
GF_Err e;
FILE *logs;
u32 i, j, di, nbBifs, nbLaser, nb_samp, samp_done, init_offset;
GF_StreamContext *sc;
GF_ESD *esd;
GF_ODCodec *od_dec;
#ifndef GPAC_DISABLE_BIFS
GF_BifsDecoder *bifs_dec;
#endif
#ifndef GPAC_DISABLE_LASER
GF_LASeRCodec *lsr_dec;
#endif
if (!load || !load->isom) return GF_BAD_PARAM;
nbBifs = nbLaser = 0;
e = GF_OK;
#ifndef GPAC_DISABLE_BIFS
bifs_dec = gf_bifs_decoder_new(load->scene_graph, 1);
#endif
od_dec = gf_odf_codec_new();
logs = NULL;
#ifndef GPAC_DISABLE_LASER
lsr_dec = gf_laser_decoder_new(load->scene_graph);
#endif
esd = NULL;
nb_samp = 0;
for (i=0; i<gf_isom_get_track_count(load->isom); i++) {
u32 type = gf_isom_get_media_type(load->isom, i+1);
u32 subtype = gf_isom_get_mpeg4_subtype(load->isom, i+1, 1);
switch (type) {
case GF_ISOM_MEDIA_SCENE:
case GF_ISOM_MEDIA_OD:
nb_samp += gf_isom_get_sample_count(load->isom, i+1);
break;
default:
if (subtype==GF_ISOM_SUBTYPE_MP4S) {
nb_samp += gf_isom_get_sample_count(load->isom, i+1);
}
break;
}
}
samp_done = 1;
gf_isom_text_set_streaming_mode(load->isom, 1);
for (i=0; i<gf_isom_get_track_count(load->isom); i++) {
u32 type = gf_isom_get_media_type(load->isom, i+1);
u32 subtype = gf_isom_get_mpeg4_subtype(load->isom, i+1, 1);
switch (type) {
case GF_ISOM_MEDIA_SCENE:
case GF_ISOM_MEDIA_OD:
break;
default:
if (subtype!=GF_ISOM_SUBTYPE_MP4S)
continue;
break;
}
esd = gf_isom_get_esd(load->isom, i+1, 1);
if (!esd) continue;
if (!esd->decoderConfig || (esd->decoderConfig->objectTypeIndication==GF_CODECID_TEXT_MPEG4)) {
gf_odf_desc_del((GF_Descriptor *) esd);
continue;
}
if ((esd->decoderConfig->objectTypeIndication == GF_CODECID_AFX) ||
(esd->decoderConfig->objectTypeIndication == GF_CODECID_SYNTHESIZED_TEXTURE)
) {
nb_samp += gf_isom_get_sample_count(load->isom, i+1);
gf_odf_desc_del((GF_Descriptor *) esd);
continue;
}
sc = gf_sm_stream_new(load->ctx, esd->ESID, esd->decoderConfig->streamType, esd->decoderConfig->objectTypeIndication);
sc->streamType = esd->decoderConfig->streamType;
sc->ESID = esd->ESID;
sc->codec_id = esd->decoderConfig->objectTypeIndication;
sc->timeScale = gf_isom_get_media_timescale(load->isom, i+1);
if (esd->decoderConfig->streamType==GF_STREAM_SCENE) {
#ifndef GPAC_DISABLE_BIFS
if (esd->decoderConfig->objectTypeIndication<=2) {
if (!esd->dependsOnESID && nbBifs && !i)
mp4_report(load, GF_OK, "several scene namespaces used or improper scene dependencies in file - import may be incorrect");
if (!esd->decoderConfig->decoderSpecificInfo) {
e = gf_bifs_decoder_configure_stream(bifs_dec, esd->ESID, NULL, 0, esd->decoderConfig->objectTypeIndication);
} else {
e = gf_bifs_decoder_configure_stream(bifs_dec, esd->ESID, esd->decoderConfig->decoderSpecificInfo->data, esd->decoderConfig->decoderSpecificInfo->dataLength, esd->decoderConfig->objectTypeIndication);
}
if (e) goto exit;
nbBifs++;
}
#endif
#ifndef GPAC_DISABLE_LASER
if (esd->decoderConfig->objectTypeIndication==0x09) {
if (!esd->dependsOnESID && nbBifs && !i)
mp4_report(load, GF_OK, "several scene namespaces used or improper scene dependencies in file - import may be incorrect");
if (!esd->decoderConfig->decoderSpecificInfo)
e = GF_NON_COMPLIANT_BITSTREAM;
else
e = gf_laser_decoder_configure_stream(lsr_dec, esd->ESID, esd->decoderConfig->decoderSpecificInfo->data, esd->decoderConfig->decoderSpecificInfo->dataLength);
if (e) goto exit;
nbLaser++;
}
#endif
}
init_offset = 0;
for (j=0; j<gf_isom_get_sample_count(load->isom, i+1); j++) {
GF_AUContext *au;
GF_ISOSample *samp = gf_isom_get_sample(load->isom, i+1, j+1, &di);
if (!samp) {
mp4_report(load, gf_isom_last_error(load->isom), "Unable to fetch sample %d from track ID %d - aborting track import", j+1, gf_isom_get_track_id(load->isom, i+1));
break;
}
if (!j && gf_isom_get_edits_count(load->isom, i+1)) {
u64 EditTime, dur, mtime;
GF_ISOEditType mode;
gf_isom_get_edit(load->isom, i+1, 1, &EditTime, &dur, &mtime, &mode);
if (mode==GF_ISOM_EDIT_EMPTY) {
init_offset = (u32) (dur * sc->timeScale / gf_isom_get_timescale(load->isom) );
}
}
samp->DTS += init_offset;
au = gf_sm_stream_au_new(sc, samp->DTS, ((Double)(s64) samp->DTS) / sc->timeScale, (samp->IsRAP==RAP) ? 1 : 0);
if (esd->decoderConfig->streamType==GF_STREAM_SCENE) {
#ifndef GPAC_DISABLE_BIFS
if (esd->decoderConfig->objectTypeIndication<=2)
e = gf_bifs_decode_command_list(bifs_dec, esd->ESID, samp->data, samp->dataLength, au->commands);
#endif
#ifndef GPAC_DISABLE_LASER
if (esd->decoderConfig->objectTypeIndication==0x09)
e = gf_laser_decode_command_list(lsr_dec, esd->ESID, samp->data, samp->dataLength, au->commands);
#endif
} else {
e = gf_odf_codec_set_au(od_dec, samp->data, samp->dataLength);
if (!e) e = gf_odf_codec_decode(od_dec);
if (!e) {
while (1) {
GF_ODCom *odc = gf_odf_codec_get_com(od_dec);
if (!odc) break;
UpdateODCommand(load->isom, odc);
gf_list_add(au->commands, odc);
}
}
}
gf_isom_sample_del(&samp);
if (e) {
mp4_report(load, gf_isom_last_error(load->isom), "decoding sample %d from track ID %d failed", j+1, gf_isom_get_track_id(load->isom, i+1));
goto exit;
}
samp_done++;
gf_set_progress("MP4 Loading", samp_done, nb_samp);
}
gf_odf_desc_del((GF_Descriptor *) esd);
esd = NULL;
}
gf_isom_text_set_streaming_mode(load->isom, 0);
exit:
#ifndef GPAC_DISABLE_BIFS
gf_bifs_decoder_del(bifs_dec);
#endif
gf_odf_codec_del(od_dec);
#ifndef GPAC_DISABLE_LASER
gf_laser_decoder_del(lsr_dec);
#endif
if (esd) gf_odf_desc_del((GF_Descriptor *) esd);
if (logs) gf_fclose(logs);
return e;
}

static void bigben_worker(struct work_struct *work)
{
struct bigben_device *bigben = container_of(work,
struct bigben_device, worker);
struct hid_field *report_field = bigben->report->field[0];
bool do_work_led = false;
bool do_work_ff = false;
u8 *buf;
u32 len;
unsigned long flags;
if (bigben->removed)
return;
buf = hid_alloc_report_buf(bigben->report, GFP_KERNEL);
if (!buf)
return;
len = hid_report_len(bigben->report);
spin_lock_irqsave(&bigben->lock, flags);
if (bigben->work_led) {
bigben->work_led = false;
do_work_led = true;
report_field->value[0] = 0x01; 
report_field->value[1] = 0x08; 
report_field->value[2] = bigben->led_state;
report_field->value[3] = 0x00; 
report_field->value[4] = 0x00; 
report_field->value[5] = 0x00; 
report_field->value[6] = 0x00; 
report_field->value[7] = 0x00; 
hid_output_report(bigben->report, buf);
}
spin_unlock_irqrestore(&bigben->lock, flags);
if (do_work_led) {
hid_hw_raw_request(bigben->hid, bigben->report->id, buf, len,
bigben->report->type, HID_REQ_SET_REPORT);
}
spin_lock_irqsave(&bigben->lock, flags);
if (bigben->work_ff) {
bigben->work_ff = false;
do_work_ff = true;
report_field->value[0] = 0x02; 
report_field->value[1] = 0x08; 
report_field->value[2] = bigben->right_motor_on;
report_field->value[3] = bigben->left_motor_force;
report_field->value[4] = 0xff; 
report_field->value[5] = 0x00; 
report_field->value[6] = 0x00; 
report_field->value[7] = 0x00; 
hid_output_report(bigben->report, buf);
}
spin_unlock_irqrestore(&bigben->lock, flags);
if (do_work_ff) {
hid_hw_raw_request(bigben->hid, bigben->report->id, buf, len,
bigben->report->type, HID_REQ_SET_REPORT);
}
kfree(buf);
}

static void
render_table_row(hdtable_t &table,
tree_t    ***cells,
int       row,
uchar     *height_var,
float     left,                 float     right,                 float     bottom,                 float     top,                 float     *x,
float     *y,
int       *page)
{
intcol,
tcol,
colspan,
rowspan,
tempspace;
floatwidth,
temp_y;
inttemp_page;
uchar*var;
intdo_valign;  int           row_page;
floatrow_y,
row_starty,
row_height,temp_height;  uchar*bgcolor;
floatbgrgb[3];
do_valign  = 1;
row_height = 0.0f;
row_page   = *page;
row_y      = *y - table.cellpadding;
row_starty = row_y;
DEBUG_printf(("BEFORE row_y = %.1f, *y = %.1f, row_page = %d\n",
row_y, *y, row_page));
for (col = 0, rowspan = 9999; col < table.num_cols; col += colspan)
{
if (table.row_spans[col] == 0)
{
if ((var = htmlGetVariable(cells[row][col], (uchar *)"ROWSPAN")) != NULL)
table.row_spans[col] = atoi((char *)var);
if (table.row_spans[col] == 1)
table.row_spans[col] = 0;
if (table.row_spans[col] > (table.num_rows - row))
table.row_spans[col] = table.num_rows - row;
table.span_heights[col] = 0.0f;
}
if (table.row_spans[col] < rowspan)
rowspan = table.row_spans[col];
for (colspan = 1; (col + colspan) < table.num_cols; colspan ++)
if (cells[row][col] != cells[row][col + colspan])
break;
}
if (!rowspan)
rowspan = 1;
for (col = 0; col < table.num_cols;)
{
for (colspan = 1; (col + colspan) < table.num_cols; colspan ++)
if (cells[row][col] != cells[row][col + colspan])
break;
colspan --;
DEBUG_printf(("    col = %d, colspan = %d, left = %.1f, right = %.1f, cell = %p\n", col, colspan, table.col_lefts[col], table.col_rights[col + colspan], (void *)cells[row][col]));
*x        = table.col_lefts[col];
temp_y    = *y - table.cellpadding;
temp_page = *page;
tempspace = 0;
if (row == 0 || cells[row][col] != cells[row - 1][col])
{
check_pages(*page);
if (cells[row][col] == NULL)
bgcolor = NULL;
else if ((bgcolor = htmlGetVariable(cells[row][col], (uchar *)"BGCOLOR")) != NULL)
{
memcpy(bgrgb, background_color, sizeof(bgrgb));
get_color(bgcolor, bgrgb, 0);
width       = table.col_rights[col + colspan] - table.col_lefts[col] + 2 * table.cellpadding;
table.border_left = table.col_lefts[col] - table.cellpadding;
table.cell_bg[col] = new_render(*page, RENDER_BOX, table.border_left, row_y, width + table.border, 0.0, bgrgb);
}
else
{
table.cell_bg[col] = NULL;
new_render(*page, RENDER_TEXT, -1.0f, -1.0f, 0.0, 0.0, (void *)"");
}
DEBUG_printf(("cell_bg[%d] = %p, pages[%d].end = %p\n", col, (void *)table.cell_bg[col], *page, (void *)pages[*page].end));
table.cell_start[col] = pages[*page].end;
table.cell_page[col]  = temp_page;
table.cell_y[col]     = temp_y;
if (table.debug)
{
check_pages(*page);
render_t *r;
char table_text[255];
snprintf(table_text, sizeof(table_text), "cell=%p [%d,%d]",
(void *)cells[row][col], row, col);
r = new_render(temp_page, RENDER_TEXT, *x, temp_y,
get_width((uchar *)table_text, TYPE_COURIER, STYLE_NORMAL, 1),
_htmlSizes[1], table_text);
r->data.text.typeface = TYPE_COURIER;
r->data.text.style    = STYLE_NORMAL;
r->data.text.size     = (float)_htmlSizes[1];
}
if (cells[row][col] != NULL && cells[row][col]->child != NULL)
{
DEBUG_printf(("    parsing cell %d,%d; width = %.1f\n", row, col, table.col_rights[col + colspan] - table.col_lefts[col]));
bottom += table.cellpadding;
top    -= table.cellpadding;
parse_doc(cells[row][col]->child, table.col_lefts + col, table.col_rights + col + colspan, &bottom, &top, x, &temp_y, &temp_page, NULL, &tempspace);
bottom -= table.cellpadding;
top    += table.cellpadding;
}
table.cell_endpage[col] = temp_page;
table.cell_endy[col]    = temp_y;
table.cell_height[col]  = *y - table.cellpadding - temp_y;
table.cell_end[col]     = pages[*page].end;
if (table.cell_start[col] == NULL)
table.cell_start[col] = pages[*page].start;
DEBUG_printf(("row = %d, col = %d, y = %.1f, cell_y = %.1f, cell_height = %.1f\n", row, col, *y - table.cellpadding, temp_y, table.cell_height[col]));
DEBUG_printf(("cell_start[%d] = %p, cell_end[%d] = %p\n", col, (void *)table.cell_start[col], col, (void *)table.cell_end[col]));
}
if (table.row_spans[col] == 0 &&
table.cell_page[col] == table.cell_endpage[col] &&
table.cell_height[col] > row_height)
row_height = table.cell_height[col];
if (table.row_spans[col] <= rowspan)
{
if (table.cell_page[col] != table.cell_endpage[col])
do_valign = 0;
if (table.cell_endpage[col] > row_page)
{
row_page = table.cell_endpage[col];
row_y    = table.cell_endy[col];
}
else if (table.cell_endy[col] < row_y && table.cell_endpage[col] == row_page)
row_y = table.cell_endy[col];
}
DEBUG_printf(("**** col = %d, row = %d, row_y = %.1f, row_page = %d\n", col, row, row_y, row_page));
for (col ++; colspan > 0; colspan --, col ++)
{
table.cell_start[col]   = NULL;
table.cell_page[col]    = table.cell_page[col - 1];
table.cell_y[col]       = table.cell_y[col - 1];
table.cell_end[col]     = NULL;
table.cell_endpage[col] = table.cell_endpage[col - 1];
table.cell_endy[col]    = table.cell_endy[col - 1];
table.cell_height[col]  = table.cell_height[col - 1];
}
}
DEBUG_printf(("row = %d, row_y = %.1f, row_height = %.1f\n", row, row_y, row_height));
for (col = 0; col < table.num_cols; col += colspan)
{
for (colspan = 1; (col + colspan) < table.num_cols; colspan ++)
if (cells[row][col] != cells[row][col + colspan])
break;
if (table.row_spans[col])
table.span_heights[col] += row_height;
DEBUG_printf(("col = %d, cell_y = %.1f, cell_page = %d, cell_endpage = %d, row_spans = %d, span_heights = %.1f, cell_height = %.1f\n", col, table.cell_y[col], table.cell_page[col], table.cell_endpage[col], table.row_spans[col], table.span_heights[col], table.cell_height[col]));
}
for (col = 0; col < table.num_cols; col += colspan)
{
for (colspan = 1; (col + colspan) < table.num_cols; colspan ++)
if (cells[row][col] != cells[row][col + colspan])
break;
if (table.row_spans[col] == rowspan &&
table.cell_page[col] == table.cell_endpage[col] &&
table.cell_height[col] > table.span_heights[col])
{
temp_height = table.cell_height[col] - table.span_heights[col];
row_height  += temp_height;
DEBUG_printf(("Adjusting row-span height by %.1f, new row_height = %.1f\n", temp_height, row_height));
for (tcol = 0; tcol < table.num_cols; tcol ++)
if (table.row_spans[tcol])
{
table.span_heights[tcol] += temp_height;
DEBUG_printf(("col = %d, span_heights = %.1f\n", tcol, table.span_heights[tcol]));
}
}
}
DEBUG_printf(("AFTER row = %d, row_page = %d, row_y = %.1f, row_height = %.1f, *y = %.1f, do_valign = %d\n", row, row_page, row_y, row_height, *y, do_valign));
if (do_valign)
{
height_var = NULL;
if (cells[row][0] != NULL)
{
if ((height_var = htmlGetVariable(cells[row][0]->parent, (uchar *)"HEIGHT")) == NULL)
for (col = 0; col < table.num_cols; col ++)
if (htmlGetVariable(cells[row][col], (uchar *)"ROWSPAN") == NULL)
if ((height_var = htmlGetVariable(cells[row][col], (uchar *)"HEIGHT")) != NULL)
break;
}
if (height_var != NULL)
{
if (height_var[strlen((char *)height_var) - 1] == '%')
temp_height = (float)(atof((char *)height_var) * 0.01f * PagePrintLength);
else
temp_height = (float)(atof((char *)height_var) * PagePrintWidth / _htmlBrowserWidth);
if (table.height > 0 && temp_height > table.height)
temp_height = table.height;
temp_height -= 2 * table.cellpadding;
if (temp_height > row_height)
{
row_height = temp_height;
row_y      = *y - temp_height;
}
}
for (col = 0; col < table.num_cols; col += colspan + 1)
{
render_t*p;
floatdelta_y;
for (colspan = 1; (col + colspan) < table.num_cols; colspan ++)
if (cells[row][col] != cells[row][col + colspan])
break;
colspan --;
if (table.cell_start[col] == NULL || table.row_spans[col] > rowspan ||
cells[row][col] == NULL || cells[row][col]->child == NULL)
continue;
if (table.row_spans[col] == 1)
{
int tcol;
float span_height = 0.0f;
for (tcol = 0; tcol < table.num_cols; tcol ++)
{
if (table.row_spans[col] == 1 && table.span_heights[col] > span_height)
span_height = table.span_heights[col];
}
switch (cells[row][col]->valignment)
{
case ALIGN_MIDDLE :
delta_y = (span_height - table.cell_height[col]) * 0.5f;
break;
case ALIGN_BOTTOM :
delta_y = span_height - table.cell_height[col];
break;
default :
delta_y = 0.0f;
break;
}
}
else if (table.row_spans[col])
{
delta_y = 0.0f;
}
else
{
switch (cells[row][col]->valignment)
{
case ALIGN_MIDDLE :
delta_y = (row_height - table.cell_height[col]) * 0.5f;
break;
case ALIGN_BOTTOM :
delta_y = row_height - table.cell_height[col];
break;
default :
delta_y = 0.0f;
break;
}
}
DEBUG_printf(("row = %d, col = %d, valign = %d, rowspans = %d, cell_height = %.1f, span_heights = %.1f, delta_y = %.1f\n", row, col, cells[row][col]->valignment, table.row_spans[col], table.cell_height[col], table.span_heights[col], delta_y));
if (delta_y > 0.0f)
{
if (table.cell_start[col] == table.cell_end[col])
p = table.cell_start[col];
else
p = table.cell_start[col]->next;
for (; p != NULL; p = p->next)
{
DEBUG_printf(("aligning %p (%s), y was %.1f, now %.1f\n",
(void *)p, p->data.text.buffer, p->y, p->y - delta_y));
p->y -= delta_y;
if (p == table.cell_end[col])
break;
}
}
#ifdef DEBUG
else
{
if (table.cell_start[col] == table.cell_end[col])
p = table.cell_start[col];
else
p = table.cell_start[col]->next;
for (; p != NULL; p = p->next)
{
printf("NOT aligning %p (%s)\n", (void *)p, p->data.text.buffer);
if (p == table.cell_end[col])
break;
}
}
#endif 
}
}
for (col = 0, temp_page = -1, temp_y = 99999999; col < table.num_cols; col ++)
if (table.row_spans[col] <= rowspan &&
cells[row][col] != NULL && cells[row][col]->child != NULL)
{
if (table.cell_endpage[col] > temp_page)
{
temp_page = table.cell_endpage[col];
temp_y    = table.cell_endy[col];
}
else if (table.cell_endpage[col] == temp_page && table.cell_endy[col] < temp_y)
temp_y = table.cell_endy[col];
}
for (col = 0; col < table.num_cols; col ++)
if (table.row_spans[col] <= rowspan &&
cells[row][col] != NULL && cells[row][col]->child != NULL)
{
table.cell_endpage[col] = temp_page;
table.cell_endy[col]    = temp_y;
}
row_y -= table.cellpadding;
table.border_left = table.col_lefts[0] - table.cellpadding;
width       = table.col_rights[table.num_cols - 1] - table.col_lefts[0] + 2 * table.cellpadding;
for (bgcolor = NULL, col = 0; col < table.num_cols; col ++)
if (table.row_spans[col] <= rowspan &&
cells[row][col] &&
!htmlGetVariable(cells[row][col], (uchar *)"ROWSPAN") &&
(bgcolor = htmlGetVariable(cells[row][col]->parent,
(uchar *)"BGCOLOR")) != NULL)
break;
if (bgcolor)
{
memcpy(bgrgb, background_color, sizeof(bgrgb));
get_color(bgcolor, bgrgb, 0);
if (row_page > *page)
{
new_render(*page, RENDER_BOX, table.border_left, bottom,
width, row_starty - bottom + table.cellpadding, bgrgb,
pages[*page].start);
for (temp_page = *page + 1; temp_page < row_page; temp_page ++)
{
new_render(temp_page, RENDER_BOX, table.border_left, bottom,
width, top - bottom, bgrgb, pages[temp_page].start);
}
check_pages(*page);
new_render(row_page, RENDER_BOX, table.border_left, row_y,
width, top - row_y, bgrgb,
pages[row_page].start);
}
else
{
new_render(row_page, RENDER_BOX, table.border_left, row_y,
width, row_height + 2 * table.cellpadding, bgrgb,
pages[row_page].start);
}
}
for (col = 0; col < table.num_cols; col += colspan + 1)
{
for (colspan = 0; (col + colspan) < table.num_cols; colspan ++)
if (cells[row][col] != cells[row][col + colspan])
break;
else if (table.row_spans[col + colspan] > 0)
{
DEBUG_printf(("row = %d, col = %d, decrementing row_spans (%d) to %d...\n", row,
col, table.row_spans[col + colspan],
table.row_spans[col + colspan] - rowspan));
table.row_spans[col + colspan] -= rowspan;
}
colspan --;
width = table.col_rights[col + colspan] - table.col_lefts[col] +
2 * table.cellpadding;
if (cells[row][col] == NULL || cells[row][col]->child == NULL ||
table.row_spans[col] > 0)
continue;
DEBUG_printf(("DRAWING BORDER+BACKGROUND: col=%d, row=%d, cell_page=%d, cell_y=%.1f\n"
"                           cell_endpage=%d, cell_endy=%.1f\n",
col, row, table.cell_page[col], table.cell_y[col],
table.cell_endpage[col], table.cell_endy[col]));
if ((bgcolor = htmlGetVariable(cells[row][col],
(uchar *)"BGCOLOR")) != NULL)
{
memcpy(bgrgb, background_color, sizeof(bgrgb));
get_color(bgcolor, bgrgb, 0);
}
table.border_left = table.col_lefts[col] - table.cellpadding;
if (table.cell_page[col] != table.cell_endpage[col])
{
if (table.border > 0)
{
new_render(table.cell_page[col], RENDER_BOX, table.border_left,
table.cell_y[col] + table.cellpadding,
width + table.border, table.border, table.border_rgb);
new_render(table.cell_page[col], RENDER_BOX, table.border_left, bottom,
table.border, table.cell_y[col] - bottom + table.cellpadding + table.border, table.border_rgb);
new_render(table.cell_page[col], RENDER_BOX,
table.border_left + width, bottom,
table.border, table.cell_y[col] - bottom + table.cellpadding + table.border, table.border_rgb);
}
if (bgcolor != NULL)
{
table.cell_bg[col]->y      = bottom;
table.cell_bg[col]->height = table.cell_y[col] - bottom + table.cellpadding + table.border;
}
for (temp_page = table.cell_page[col] + 1; temp_page < table.cell_endpage[col]; temp_page ++)
{
if (table.border > 0.0f)
{
new_render(temp_page, RENDER_BOX, table.border_left, bottom,
table.border, top - bottom, table.border_rgb);
new_render(temp_page, RENDER_BOX,
table.border_left + width, bottom,
table.border, top - bottom, table.border_rgb);
}
if (bgcolor != NULL)
new_render(temp_page, RENDER_BOX, table.border_left, bottom,
width + table.border, top - bottom, bgrgb,
pages[temp_page].start);
}
if (table.border > 0.0f)
{
new_render(table.cell_endpage[col], RENDER_BOX, table.border_left, row_y,
table.border, top - row_y, table.border_rgb);
new_render(table.cell_endpage[col], RENDER_BOX,
table.border_left + width, row_y,
table.border, top - row_y, table.border_rgb);
new_render(table.cell_endpage[col], RENDER_BOX, table.border_left, row_y,
width + table.border, table.border, table.border_rgb);
}
if (bgcolor != NULL)
{
check_pages(table.cell_endpage[col]);
new_render(table.cell_endpage[col], RENDER_BOX, table.border_left, row_y,
width + table.border, top - row_y, bgrgb,
pages[table.cell_endpage[col]].start);
}
}
else
{
if (table.border > 0.0f)
{
new_render(table.cell_page[col], RENDER_BOX, table.border_left,
table.cell_y[col] + table.cellpadding,
width + table.border, table.border, table.border_rgb);
new_render(table.cell_page[col], RENDER_BOX, table.border_left, row_y,
table.border, table.cell_y[col] - row_y + table.cellpadding + table.border, table.border_rgb);
new_render(table.cell_page[col], RENDER_BOX,
table.border_left + width, row_y,
table.border, table.cell_y[col] - row_y + table.cellpadding + table.border, table.border_rgb);
new_render(table.cell_page[col], RENDER_BOX, table.border_left, row_y,
width + table.border, table.border, table.border_rgb);
}
if (bgcolor != NULL)
{
table.cell_bg[col]->y      = row_y;
table.cell_bg[col]->height = table.cell_y[col] - row_y + table.cellpadding + table.border;
}
}
}
*page = row_page;
*y    = row_y;
}

void hrandfieldCommand(client *c) {
long l;
int withvalues = 0;
robj *hash;
listpackEntry ele;
if (c->argc >= 3) {
if (getLongFromObjectOrReply(c,c->argv[2],&l,NULL) != C_OK) return;
if (c->argc > 4 || (c->argc == 4 && strcasecmp(c->argv[3]->ptr,"withvalues"))) {
addReplyErrorObject(c,shared.syntaxerr);
return;
} else if (c->argc == 4)
withvalues = 1;
hrandfieldWithCountCommand(c, l, withvalues);
return;
}
if ((hash = lookupKeyReadOrReply(c,c->argv[1],shared.null[c->resp]))== NULL ||
checkType(c,hash,OBJ_HASH)) {
return;
}
hashTypeRandomElement(hash,hashTypeLength(hash),&ele,NULL);
hashReplyFromListpackEntry(c, &ele);
}

static GF_Err gf_filter_pid_configure(GF_Filter *filter, GF_FilterPid *pid, GF_PidConnectType ctype)
{
u32 i, count;
GF_Err e;
Bool refire_events=GF_FALSE;
Bool new_pid_inst=GF_FALSE;
Bool remove_filter=GF_FALSE;
GF_FilterPidInst *pidinst=NULL;
GF_Filter *alias_orig = NULL;
if (filter->multi_sink_target) {
alias_orig = filter;
filter = filter->multi_sink_target;
}
assert(filter->freg->configure_pid);
if (filter->finalized) {
GF_LOG(GF_LOG_ERROR, GF_LOG_FILTER, ("Trying to configure PID %s in finalized filter %s\n",  pid->name, filter->name));
if (ctype==GF_PID_CONF_CONNECT) {
assert(pid->filter->out_pid_connection_pending);
safe_int_dec(&pid->filter->out_pid_connection_pending);
}
return GF_SERVICE_ERROR;
}
if (filter->detached_pid_inst) {
count = gf_list_count(filter->detached_pid_inst);
for (i=0; i<count; i++) {
pidinst = gf_list_get(filter->detached_pid_inst, i);
if (pidinst->filter==filter) {
gf_list_rem(filter->detached_pid_inst, i);
pidinst->filter = filter;
pidinst->pid = pid;
assert(!pidinst->props);
if (ctype == GF_PID_CONF_CONNECT) {
new_pid_inst=GF_TRUE;
if (!pid->filter->nb_pids_playing && (pidinst->is_playing || pidinst->is_paused))
refire_events = GF_TRUE;
}
assert(pidinst->detach_pending);
safe_int_dec(&pidinst->detach_pending);
if (filter->sticky == 2)
filter->sticky = 0;
break;
}
pidinst=NULL;
}
if (! gf_list_count(filter->detached_pid_inst)) {
gf_list_del(filter->detached_pid_inst);
filter->detached_pid_inst = NULL;
}
}
if (!pidinst) {
count = pid->num_destinations;
for (i=0; i<count; i++) {
pidinst = gf_list_get(pid->destinations, i);
if (pidinst->filter==filter) {
break;
}
pidinst=NULL;
}
}
if (!pidinst) {
if (ctype != GF_PID_CONF_CONNECT) {
GF_LOG(GF_LOG_ERROR, GF_LOG_FILTER, ("Trying to disconnect PID %s not present in filter %s inputs\n",  pid->name, filter->name));
return GF_SERVICE_ERROR;
}
pidinst = gf_filter_pid_inst_new(filter, pid);
new_pid_inst=GF_TRUE;
}
if (!pidinst->alias_orig)
pidinst->alias_orig = alias_orig;
if (new_pid_inst) {
assert(pidinst);
gf_mx_p(pid->filter->tasks_mx);
GF_LOG(GF_LOG_DEBUG, GF_LOG_FILTER, ("Registering %s:%s as destination for %s:%s\n", pid->filter->name, pid->name, pidinst->filter->name, pidinst->pid->name));
gf_list_add(pid->destinations, pidinst);
pid->num_destinations = gf_list_count(pid->destinations);
gf_mx_v(pid->filter->tasks_mx);
gf_mx_p(filter->tasks_mx);
if (!filter->input_pids) filter->input_pids = gf_list_new();
gf_list_add(filter->input_pids, pidinst);
filter->num_input_pids = gf_list_count(filter->input_pids);
if (filter->num_input_pids==1) {
filter->single_source = pidinst->pid->filter;
} else if (filter->single_source != pidinst->pid->filter) {
filter->single_source = NULL;
}
gf_mx_v(filter->tasks_mx);
gf_filter_pid_update_caps(pid);
}
if (filter->swap_pending) {
gf_filter_pid_inst_swap(filter, pidinst);
filter->swap_pending = GF_FALSE;
}
filter->in_connect_err = GF_EOS;
#if 0
FSESS_CHECK_THREAD(filter)
#endif
GF_LOG(GF_LOG_DEBUG, GF_LOG_FILTER, ("Filter %s PID %s reconfigure\n", pidinst->filter->name, pidinst->pid->name));
e = filter->freg->configure_pid(filter, (GF_FilterPid*) pidinst, (ctype==GF_PID_CONF_REMOVE) ? GF_TRUE : GF_FALSE);
#ifdef GPAC_MEMORY_TRACKING
if (filter->session->check_allocs) {
if (filter->nb_consecutive_process >= filter->max_nb_consecutive_process) {
filter->max_nb_consecutive_process = filter->nb_consecutive_process;
filter->max_nb_process = filter->nb_process_since_reset;
filter->max_stats_nb_alloc = filter->stats_nb_alloc;
filter->max_stats_nb_calloc = filter->stats_nb_calloc;
filter->max_stats_nb_realloc = filter->stats_nb_realloc;
filter->max_stats_nb_free = filter->stats_nb_free;
}
filter->stats_mem_allocated = 0;
filter->stats_nb_alloc = filter->stats_nb_realloc = filter->stats_nb_free = 0;
filter->nb_process_since_reset = filter->nb_consecutive_process = 0;
}
#endif
if ((e==GF_OK) && (filter->in_connect_err<GF_OK))
e = filter->in_connect_err;
filter->in_connect_err = GF_OK;
if (e==GF_OK) {
if (new_pid_inst) {
GF_LOG(GF_LOG_INFO, GF_LOG_FILTER, ("Filter %s (%p) PID %s (%p) (%d fan-out) connected to filter %s (%p)\n", pid->filter->name, pid->filter, pid->name, pid, pid->num_destinations, filter->name, filter));
}
gf_list_reset(pidinst->pid->filter->blacklisted);
}
else if ((ctype==GF_PID_CONF_RECONFIG) && (e != GF_FILTER_NOT_SUPPORTED)) {
pidinst->is_end_of_stream = GF_TRUE;
if (e==GF_BAD_PARAM) {
GF_LOG(GF_LOG_ERROR, GF_LOG_FILTER, ("Failed to reconfigure PID %s:%s in filter %s: %s\n", pid->filter->name, pid->name, filter->name, gf_error_to_string(e) ));
filter->session->last_connect_error = e;
} else {
GF_LOG(GF_LOG_INFO, GF_LOG_FILTER, ("Failed to reconfigure PID %s:%s in filter %s: %s, reloading filter graph\n", pid->filter->name, pid->name, filter->name, gf_error_to_string(e) ));
gf_list_add(pid->filter->blacklisted, (void *) filter->freg);
gf_filter_relink_dst(pidinst, e);
}
} else {
gf_mx_p(filter->tasks_mx);
gf_list_del_item(filter->input_pids, pidinst);
filter->num_input_pids = gf_list_count(filter->input_pids);
if (!filter->num_input_pids)
filter->single_source = NULL;
filter->freg->configure_pid(filter, (GF_FilterPid *) pidinst, GF_TRUE);
gf_mx_v(filter->tasks_mx);
gf_mx_p(pidinst->pid->filter->tasks_mx);
gf_list_del_item(pidinst->pid->destinations, pidinst);
pidinst->pid->num_destinations = gf_list_count(pidinst->pid->destinations);
gf_filter_instance_detach_pid(pidinst);
gf_mx_v(pidinst->pid->filter->tasks_mx);
if (new_pid_inst) {
gf_mx_p(pid->filter->tasks_mx);
gf_list_del_item(pid->destinations, pidinst);
pid->num_destinations = gf_list_count(pid->destinations);
gf_mx_p(pid->filter->tasks_mx);
count = gf_fq_count(pid->filter->tasks);
for (i=0; i<count; i++) {
GF_FSTask *t = gf_fq_get(pid->filter->tasks, i);
if (t->pid == (GF_FilterPid *) pidinst) {
t->run_task = task_canceled;
}
}
gf_mx_v(pid->filter->tasks_mx);
gf_filter_pid_inst_del(pidinst);
gf_mx_v(pid->filter->tasks_mx);
}
if (e==GF_REQUIRES_NEW_INSTANCE) {
GF_Filter *new_filter = gf_filter_clone(filter, pid->filter);
if (new_filter) {
GF_LOG(GF_LOG_DEBUG, GF_LOG_FILTER, ("Clone filter %s, new instance for pid %s\n", filter->name, pid->name));
gf_filter_pid_post_connect_task(new_filter, pid);
return GF_OK;
} else {
GF_LOG(GF_LOG_ERROR, GF_LOG_FILTER, ("Failed to clone filter %s\n", filter->name));
e = GF_OUT_OF_MEM;
}
}
if (e && (ctype==GF_PID_CONF_REMOVE)) {
GF_LOG(GF_LOG_ERROR, GF_LOG_FILTER, ("Failed to disconnect filter %s PID %s from filter %s: %s\n", pid->filter->name, pid->name, filter->name, gf_error_to_string(e) ));
}
else if (e) {
if (e!= GF_EOS) {
GF_LOG(GF_LOG_ERROR, GF_LOG_FILTER, ("Failed to connect filter %s PID %s to filter %s: %s\n", pid->filter->name, pid->name, filter->name, gf_error_to_string(e) ));
}
if ((e==GF_BAD_PARAM)
|| (e==GF_SERVICE_ERROR)
|| (e==GF_REMOTE_SERVICE_ERROR)
|| (e==GF_FILTER_NOT_SUPPORTED)
|| (e==GF_EOS)
|| (filter->session->flags & GF_FS_FLAG_NO_REASSIGN)
) {
if (filter->session->flags & GF_FS_FLAG_NO_REASSIGN) {
GF_LOG(GF_LOG_ERROR, GF_LOG_FILTER, ("Filter reassignment disabled, skippping chain reload for filter %s PID %s\n", pid->filter->name, pid->name ));
}
if (e!= GF_EOS) {
filter->session->last_connect_error = e;
}
if (ctype==GF_PID_CONF_CONNECT) {
GF_FilterEvent evt;
GF_FEVT_INIT(evt, GF_FEVT_PLAY, pid);
gf_filter_pid_send_event_internal(pid, &evt, GF_TRUE);
GF_FEVT_INIT(evt, GF_FEVT_STOP, pid);
gf_filter_pid_send_event_internal(pid, &evt, GF_TRUE);
gf_filter_pid_set_eos(pid);
if (pid->filter->freg->process_event) {
GF_FEVT_INIT(evt, GF_FEVT_CONNECT_FAIL, pid);
gf_filter_pid_send_event_internal(pid, &evt, GF_TRUE);
}
if (!filter->num_input_pids && !filter->num_output_pids) {
remove_filter = GF_TRUE;
}
}
} else if (filter->has_out_caps) {
Bool unload_filter = GF_TRUE;
GF_LOG(GF_LOG_WARNING, GF_LOG_FILTER, ("Blacklisting %s as output from %s and retrying connections\n", filter->name, pid->filter->name));
gf_list_add(pid->filter->blacklisted, (void *) filter->freg);
gf_mx_p(filter->tasks_mx);
while (gf_list_count(filter->input_pids)) {
GF_FilterPidInst *a_pidinst = gf_list_pop_back(filter->input_pids);
FSESS_CHECK_THREAD(filter)
filter->num_input_pids--;
filter->freg->configure_pid(filter, (GF_FilterPid *) a_pidinst, GF_TRUE);
gf_filter_pid_post_init_task(a_pidinst->pid->filter, a_pidinst->pid);
gf_fs_post_task(filter->session, gf_filter_pid_inst_delete_task, a_pidinst->pid->filter, a_pidinst->pid, "pid_inst_delete", a_pidinst);
unload_filter = GF_FALSE;
}
filter->num_input_pids = 0;
filter->single_source = NULL;
filter->removed = 1;
filter->has_pending_pids = GF_FALSE;
gf_mx_v(filter->tasks_mx);
if (ctype==GF_PID_CONF_CONNECT) {
assert(pid->filter->out_pid_connection_pending);
safe_int_dec(&pid->filter->out_pid_connection_pending);
}
gf_filter_pid_post_init_task(pid->filter, pid);
if (unload_filter) {
assert(!gf_list_count(filter->input_pids));
if (filter->num_output_pids) {
for (i=0; i<filter->num_output_pids; i++) {
u32 j;
GF_FilterPid *opid = gf_list_get(filter->output_pids, i);
for (j=0; j< opid->num_destinations; j++) {
GF_FilterPidInst *a_pidi = gf_list_get(opid->destinations, j);
a_pidi->pid = NULL;
}
gf_list_reset(opid->destinations);
opid->num_destinations = 0;
gf_filter_pid_remove(opid);
}
}
filter->swap_pidinst_src = NULL;
if (filter->swap_pidinst_dst) {
GF_Filter *target = filter->swap_pidinst_dst->filter;
assert(target);
if (!target->detached_pid_inst) {
target->detached_pid_inst = gf_list_new();
}
if (filter->swap_pidinst_dst->props) {
filter->swap_pidinst_dst->props = NULL;
}
filter->swap_pidinst_dst->pid = NULL;
if (gf_list_find(target->detached_pid_inst, filter->swap_pidinst_dst)<0)
gf_list_add(target->detached_pid_inst, filter->swap_pidinst_dst);
}
filter->swap_pidinst_dst = NULL;
if (filter->on_setup_error) {
gf_filter_notification_failure(filter, e, GF_TRUE);
} else {
gf_filter_post_remove(filter);
}
}
return e;
} else {
GF_LOG(GF_LOG_ERROR, GF_LOG_FILTER, ("Failed to reconfigure input of sink %s, cannot rebuild graph\n", filter->name));
if (pid->filter->freg->process_event) {
GF_FilterEvent evt;
GF_FEVT_INIT(evt, GF_FEVT_CONNECT_FAIL, pid);
pid->filter->freg->process_event(pid->filter, &evt);
}
filter->session->last_connect_error = e;
}
} else {
filter->session->last_connect_error = GF_OK;
}
if (filter->session->requires_solved_graph)
return e;
}
if (filter->has_pending_pids) {
filter->has_pending_pids = GF_FALSE;
while (gf_fq_count(filter->pending_pids)) {
GF_FilterPid *a_pid=gf_fq_pop(filter->pending_pids);
if (pid->is_playing && filter->is_pid_adaptation_filter)
a_pid->is_playing = GF_TRUE;
gf_filter_pid_post_init_task(filter, a_pid);
}
}
if (ctype==GF_PID_CONF_REMOVE) {
gf_mx_p(filter->tasks_mx);
gf_list_del_item(filter->input_pids, pidinst);
filter->num_input_pids = gf_list_count(filter->input_pids);
if (!filter->num_input_pids)
filter->single_source = NULL;
gf_mx_v(filter->tasks_mx);
gf_mx_p(pidinst->pid->filter->tasks_mx);
pidinst->pid->num_pidinst_del_pending ++;
gf_list_del_item(pidinst->pid->destinations, pidinst);
pidinst->pid->num_destinations = gf_list_count(pidinst->pid->destinations);
gf_filter_instance_detach_pid(pidinst);
gf_mx_v(pidinst->pid->filter->tasks_mx);
if (!filter->num_input_pids && !filter->sticky) {
gf_filter_reset_pending_packets(filter);
filter->removed = 1;
}
gf_fs_post_task(filter->session, gf_filter_pid_inst_delete_task, pid->filter, pid, "pid_inst_delete", pidinst);
return e;
}
if (ctype==GF_PID_CONF_CONNECT) {
assert(pid->filter->out_pid_connection_pending);
if (safe_int_dec(&pid->filter->out_pid_connection_pending) == 0) {
if (refire_events) {
GF_FilterEvent evt;
if (pidinst->is_playing) {
pidinst->is_playing = GF_FALSE;
GF_FEVT_INIT(evt, GF_FEVT_PLAY, (GF_FilterPid*)pidinst);
gf_filter_pid_send_event((GF_FilterPid *)pidinst, &evt);
}
if (pidinst->is_paused) {
pidinst->is_paused = GF_FALSE;
GF_FEVT_INIT(evt, GF_FEVT_PAUSE, (GF_FilterPid*)pidinst);
gf_filter_pid_send_event((GF_FilterPid *)pidinst, &evt);
}
}
if (e==GF_OK) {
if (pid->filter->postponed_packets || pid->filter->pending_packets || pid->filter->nb_caps_renegociate) {
gf_filter_post_process_task(pid->filter);
}
}
}
if (remove_filter && !filter->sticky)
gf_filter_post_remove(filter);
}
gf_filter_pid_update_caps(pid);
return e;
}

static Image *ReadRLEImage(const ImageInfo *image_info,ExceptionInfo *exception)
{
#define SkipLinesOp  0x01
#define SetColorOp  0x02
#define SkipPixelsOp  0x03
#define ByteDataOp  0x05
#define RunDataOp  0x06
#define EOFOp  0x07
char
magick[12];
Image
*image;
int
opcode,
operand,
status;
MagickStatusType
flags;
MagickSizeType
number_pixels;
MemoryInfo
*pixel_info;
Quantum
index;
register ssize_t
x;
register Quantum
*q;
register ssize_t
i;
register unsigned char
*p;
size_t
bits_per_pixel,
map_length,
number_colormaps,
number_planes,
number_planes_filled,
one,
offset,
pixel_info_length;
ssize_t
count,
y;
unsigned char
background_color[256],
*colormap,
pixel,
plane,
*pixels;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickCoreSignature);
if (image_info->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
image_info->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
image=AcquireImage(image_info,exception);
status=OpenBlob(image_info,image,ReadBinaryBlobMode,exception);
if (status == MagickFalse)
return(DestroyImageList(image));
count=ReadBlob(image,2,(unsigned char *) magick);
if ((count != 2) || (memcmp(magick,"\122\314",2) != 0))
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
do
{
image->page.x=ReadBlobLSBShort(image);
image->page.y=ReadBlobLSBShort(image);
image->columns=ReadBlobLSBShort(image);
image->rows=ReadBlobLSBShort(image);
flags=(MagickStatusType) ReadBlobByte(image);
image->alpha_trait=flags & 0x04 ? BlendPixelTrait : UndefinedPixelTrait;
number_planes=(size_t) ReadBlobByte(image);
bits_per_pixel=(size_t) ReadBlobByte(image);
number_colormaps=(size_t) ReadBlobByte(image);
map_length=(unsigned char) ReadBlobByte(image);
if (map_length >= 64)
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
one=1;
map_length=one << map_length;
if ((number_planes == 0) || (number_planes == 2) ||
((flags & 0x04) && (number_colormaps > 254)) || (bits_per_pixel != 8) ||
(image->columns == 0))
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
if (flags & 0x02)
{
for (i=0; i < (ssize_t) number_planes; i++)
background_color[i]=0;
(void) ReadBlobByte(image);
}
else
{
p=background_color;
for (i=0; i < (ssize_t) number_planes; i++)
*p++=(unsigned char) ReadBlobByte(image);
}
if ((number_planes & 0x01) == 0)
(void) ReadBlobByte(image);
if (EOFBlob(image) != MagickFalse)
{
ThrowFileException(exception,CorruptImageError,"UnexpectedEndOfFile",
image->filename);
break;
}
colormap=(unsigned char *) NULL;
if (number_colormaps != 0)
{
colormap=(unsigned char *) AcquireQuantumMemory(number_colormaps,
3*map_length*sizeof(*colormap));
if (colormap == (unsigned char *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
p=colormap;
for (i=0; i < (ssize_t) number_colormaps; i++)
for (x=0; x < (ssize_t) map_length; x++)
*p++=(unsigned char) ScaleShortToQuantum(ReadBlobLSBShort(image));
}
if ((flags & 0x08) != 0)
{
char
*comment;
size_t
length;
length=ReadBlobLSBShort(image);
if (length != 0)
{
comment=(char *) AcquireQuantumMemory(length,sizeof(*comment));
if (comment == (char *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
count=ReadBlob(image,length-1,(unsigned char *) comment);
comment[length-1]='\0';
(void) SetImageProperty(image,"comment",comment,exception);
comment=DestroyString(comment);
if ((length & 0x01) == 0)
(void) ReadBlobByte(image);
}
}
if ((image_info->ping != MagickFalse) && (image_info->number_scenes != 0))
if (image->scene >= (image_info->scene+image_info->number_scenes-1))
break;
status=SetImageExtent(image,image->columns,image->rows,exception);
if (status == MagickFalse)
return(DestroyImageList(image));
if (image->alpha_trait != UndefinedPixelTrait)
number_planes++;
number_pixels=(MagickSizeType) image->columns*image->rows;
number_planes_filled=(number_planes % 2 == 0) ? number_planes :
number_planes+1;
if ((number_pixels*number_planes_filled) != (size_t) (number_pixels*
number_planes_filled))
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
pixel_info=AcquireVirtualMemory(image->columns,image->rows*
MagickMax(number_planes_filled,4)*sizeof(*pixels));
if (pixel_info == (MemoryInfo *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
pixel_info_length=image->columns*image->rows*
MagickMax(number_planes_filled,4);
pixels=(unsigned char *) GetVirtualMemoryBlob(pixel_info);
if ((flags & 0x01) && !(flags & 0x02))
{
ssize_t
j;
p=pixels;
for (i=0; i < (ssize_t) number_pixels; i++)
{
if (image->alpha_trait == UndefinedPixelTrait)
for (j=0; j < (ssize_t) number_planes; j++)
*p++=background_color[j];
else
{
for (j=0; j < (ssize_t) (number_planes-1); j++)
*p++=background_color[j];
*p++=0;  
}
}
}
plane=0;
x=0;
y=0;
opcode=ReadBlobByte(image);
do
{
switch (opcode & 0x3f)
{
case SkipLinesOp:
{
operand=ReadBlobByte(image);
if (opcode & 0x40)
operand=ReadBlobLSBSignedShort(image);
x=0;
y+=operand;
break;
}
case SetColorOp:
{
operand=ReadBlobByte(image);
plane=(unsigned char) operand;
if (plane == 255)
plane=(unsigned char) (number_planes-1);
x=0;
break;
}
case SkipPixelsOp:
{
operand=ReadBlobByte(image);
if (opcode & 0x40)
operand=ReadBlobLSBSignedShort(image);
x+=operand;
break;
}
case ByteDataOp:
{
operand=ReadBlobByte(image);
if (opcode & 0x40)
operand=ReadBlobLSBSignedShort(image);
offset=((image->rows-y-1)*image->columns*number_planes)+x*
number_planes+plane;
operand++;
if (offset+((size_t) operand*number_planes) > pixel_info_length)
{
if (number_colormaps != 0)
colormap=(unsigned char *) RelinquishMagickMemory(colormap);
pixel_info=RelinquishVirtualMemory(pixel_info);
ThrowReaderException(CorruptImageError,"UnableToReadImageData");
}
p=pixels+offset;
for (i=0; i < (ssize_t) operand; i++)
{
pixel=(unsigned char) ReadBlobByte(image);
if ((y < (ssize_t) image->rows) &&
((x+i) < (ssize_t) image->columns))
*p=pixel;
p+=number_planes;
}
if (operand & 0x01)
(void) ReadBlobByte(image);
x+=operand;
break;
}
case RunDataOp:
{
operand=ReadBlobByte(image);
if (opcode & 0x40)
operand=ReadBlobLSBSignedShort(image);
pixel=(unsigned char) ReadBlobByte(image);
(void) ReadBlobByte(image);
offset=((image->rows-y-1)*image->columns*number_planes)+x*
number_planes+plane;
operand++;
if (offset+((size_t) operand*number_planes) > pixel_info_length)
{
if (number_colormaps != 0)
colormap=(unsigned char *) RelinquishMagickMemory(colormap);
pixel_info=RelinquishVirtualMemory(pixel_info);
ThrowReaderException(CorruptImageError,"UnableToReadImageData");
}
p=pixels+offset;
for (i=0; i < (ssize_t) operand; i++)
{
if ((y < (ssize_t) image->rows) &&
((x+i) < (ssize_t) image->columns))
*p=pixel;
p+=number_planes;
}
x+=operand;
break;
}
default:
break;
}
opcode=ReadBlobByte(image);
} while (((opcode & 0x3f) != EOFOp) && (opcode != EOF));
if (number_colormaps != 0)
{
MagickStatusType
mask;
mask=(MagickStatusType) (map_length-1);
p=pixels;
x=(ssize_t) number_planes;
if (number_colormaps == 1)
for (i=0; i < (ssize_t) number_pixels; i++)
{
ValidateColormapValue(image,*p & mask,&index,exception);
*p=colormap[(ssize_t) index];
p++;
}
else
if ((number_planes >= 3) && (number_colormaps >= 3))
for (i=0; i < (ssize_t) number_pixels; i++)
for (x=0; x < (ssize_t) number_planes; x++)
{
ValidateColormapValue(image,(size_t) (x*map_length+
(*p & mask)),&index,exception);
*p=colormap[(ssize_t) index];
p++;
}
if ((i < (ssize_t) number_pixels) || (x < (ssize_t) number_planes))
{
colormap=(unsigned char *) RelinquishMagickMemory(colormap);
pixel_info=RelinquishVirtualMemory(pixel_info);
ThrowReaderException(CorruptImageError,"UnableToReadImageData");
}
}
if (number_planes >= 3)
{
p=pixels;
for (y=0; y < (ssize_t) image->rows; y++)
{
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < (ssize_t) image->columns; x++)
{
SetPixelRed(image,ScaleCharToQuantum(*p++),q);
SetPixelGreen(image,ScaleCharToQuantum(*p++),q);
SetPixelBlue(image,ScaleCharToQuantum(*p++),q);
if (image->alpha_trait != UndefinedPixelTrait)
SetPixelAlpha(image,ScaleCharToQuantum(*p++),q);
q+=GetPixelChannels(image);
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
}
else
{
if (number_colormaps == 0)
map_length=256;
if (AcquireImageColormap(image,map_length,exception) == MagickFalse)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
p=colormap;
if (number_colormaps == 1)
for (i=0; i < (ssize_t) image->colors; i++)
{
image->colormap[i].red=(MagickRealType)
ScaleCharToQuantum((unsigned char) i);
image->colormap[i].green=(MagickRealType)
ScaleCharToQuantum((unsigned char) i);
image->colormap[i].blue=(MagickRealType)
ScaleCharToQuantum((unsigned char) i);
}
else
if (number_colormaps > 1)
for (i=0; i < (ssize_t) image->colors; i++)
{
image->colormap[i].red=(MagickRealType)
ScaleCharToQuantum(*p);
image->colormap[i].green=(MagickRealType)
ScaleCharToQuantum(*(p+map_length));
image->colormap[i].blue=(MagickRealType)
ScaleCharToQuantum(*(p+map_length*2));
p++;
}
p=pixels;
if (image->alpha_trait == UndefinedPixelTrait)
{
for (y=0; y < (ssize_t) image->rows; y++)
{
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < (ssize_t) image->columns; x++)
{
SetPixelIndex(image,*p++,q);
q+=GetPixelChannels(image);
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType)
y,image->rows);
if (status == MagickFalse)
break;
}
}
(void) SyncImage(image,exception);
}
else
{
for (y=0; y < (ssize_t) image->rows; y++)
{
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < (ssize_t) image->columns; x++)
{
ValidateColormapValue(image,(ssize_t) *p++,&index,exception);
SetPixelRed(image,ClampToQuantum(image->colormap[(ssize_t)
index].red),q);
ValidateColormapValue(image,(ssize_t) *p++,&index,exception);
SetPixelGreen(image,ClampToQuantum(image->colormap[(ssize_t)
index].green),q);
ValidateColormapValue(image,(ssize_t) *p++,&index,exception);
SetPixelBlue(image,ClampToQuantum(image->colormap[(ssize_t)
index].blue),q);
SetPixelAlpha(image,ScaleCharToQuantum(*p++),q);
q+=GetPixelChannels(image);
}
if (x < (ssize_t) image->columns)
break;
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType)
y,image->rows);
if (status == MagickFalse)
break;
}
}
image->colormap=(PixelInfo *) RelinquishMagickMemory(
image->colormap);
image->storage_class=DirectClass;
image->colors=0;
}
}
if (number_colormaps != 0)
colormap=(unsigned char *) RelinquishMagickMemory(colormap);
pixel_info=RelinquishVirtualMemory(pixel_info);
if (EOFBlob(image) != MagickFalse)
{
ThrowFileException(exception,CorruptImageError,"UnexpectedEndOfFile",
image->filename);
break;
}
if (image_info->number_scenes != 0)
if (image->scene >= (image_info->scene+image_info->number_scenes-1))
break;
(void) ReadBlobByte(image);
count=ReadBlob(image,2,(unsigned char *) magick);
if ((count != 0) && (memcmp(magick,"\122\314",2) == 0))
{
AcquireNextImage(image_info,image,exception);
if (GetNextImageInList(image) == (Image *) NULL)
{
image=DestroyImageList(image);
return((Image *) NULL);
}
image=SyncNextImageInList(image);
status=SetImageProgress(image,LoadImagesTag,TellBlob(image),
GetBlobSize(image));
if (status == MagickFalse)
break;
}
} while ((count != 0) && (memcmp(magick,"\122\314",2) == 0));
(void) CloseBlob(image);
return(GetFirstImageInList(image));
}

struct razer_report razer_chroma_standard_matrix_set_custom_frame(unsigned char row_index, unsigned char start_col, unsigned char stop_col, unsigned char *rgb_data)
{
size_t row_length = (size_t) (((stop_col + 1) - start_col) * 3);
struct razer_report report = get_razer_report(0x03, 0x0B, 0x46); 
report.arguments[0] = 0xFF;     report.arguments[1] = row_index;
report.arguments[2] = start_col;
report.arguments[3] = stop_col;
memcpy(&report.arguments[4], rgb_data, row_length);
return report;
}

bool 
XmlRpcUtil::findTag(const char* tag, std::string const& xml, int* offset)
{
if (*offset >= int(xml.length())) return false;
size_t istart = xml.find(tag, *offset);
if (istart == std::string::npos)
return false;
*offset = int(istart + strlen(tag));
return true;
}

ecma_value_t
re_parse_char_class (re_parser_ctx_t *parser_ctx_p, 
re_char_class_callback append_char_class, 
void *re_ctx_p, 
re_token_t *out_token_p) 
{
re_token_type_t token_type = ((re_compiler_ctx_t *) re_ctx_p)->current_token.type;
out_token_p->qmax = out_token_p->qmin = 1;
ecma_char_t start = LIT_CHAR_UNDEF;
bool is_range = false;
parser_ctx_p->num_of_classes = 0;
const ecma_char_t prev_char = lit_utf8_peek_prev (parser_ctx_p->input_curr_p);
if (prev_char != LIT_CHAR_LEFT_SQUARE && prev_char != LIT_CHAR_CIRCUMFLEX)
{
lit_utf8_decr (&parser_ctx_p->input_curr_p);
lit_utf8_decr (&parser_ctx_p->input_curr_p);
}
do
{
if (parser_ctx_p->input_curr_p >= parser_ctx_p->input_end_p)
{
return ecma_raise_syntax_error (ECMA_ERR_MSG ("invalid character class, end of string"));
}
ecma_char_t ch = lit_utf8_read_next (&parser_ctx_p->input_curr_p);
if (ch == LIT_CHAR_RIGHT_SQUARE)
{
if (start != LIT_CHAR_UNDEF)
{
append_char_class (re_ctx_p, start, start);
}
break;
}
else if (ch == LIT_CHAR_MINUS)
{
if (parser_ctx_p->input_curr_p >= parser_ctx_p->input_end_p)
{
return ecma_raise_syntax_error (ECMA_ERR_MSG ("invalid character class, end of string after '-'"));
}
if (start != LIT_CHAR_UNDEF
&& !is_range
&& *parser_ctx_p->input_curr_p != LIT_CHAR_RIGHT_SQUARE)
{
is_range = true;
continue;
}
}
else if (ch == LIT_CHAR_BACKSLASH)
{
if (parser_ctx_p->input_curr_p >= parser_ctx_p->input_end_p)
{
return ecma_raise_syntax_error (ECMA_ERR_MSG ("invalid character class, end of string after '\\'"));
}
ch = lit_utf8_read_next (&parser_ctx_p->input_curr_p);
if (ch == LIT_CHAR_LOWERCASE_B)
{
ch = LIT_CHAR_BS;
}
else if (ch == LIT_CHAR_LOWERCASE_F)
{
ch = LIT_CHAR_FF;
}
else if (ch == LIT_CHAR_LOWERCASE_N)
{
ch = LIT_CHAR_LF;
}
else if (ch == LIT_CHAR_LOWERCASE_T)
{
ch = LIT_CHAR_TAB;
}
else if (ch == LIT_CHAR_LOWERCASE_R)
{
ch = LIT_CHAR_CR;
}
else if (ch == LIT_CHAR_LOWERCASE_V)
{
ch = LIT_CHAR_VTAB;
}
else if (ch == LIT_CHAR_LOWERCASE_C)
{
if (parser_ctx_p->input_curr_p < parser_ctx_p->input_end_p)
{
ch = *parser_ctx_p->input_curr_p;
if ((ch >= LIT_CHAR_ASCII_UPPERCASE_LETTERS_BEGIN && ch <= LIT_CHAR_ASCII_UPPERCASE_LETTERS_END)
|| (ch >= LIT_CHAR_ASCII_LOWERCASE_LETTERS_BEGIN && ch <= LIT_CHAR_ASCII_LOWERCASE_LETTERS_END)
|| (ch >= LIT_CHAR_0 && ch <= LIT_CHAR_9))
{
ch = (ch % 32);
parser_ctx_p->input_curr_p++;
}
else
{
ch = LIT_CHAR_LOWERCASE_C;
}
}
}
else if (ch == LIT_CHAR_LOWERCASE_X)
{
ecma_char_t code_unit;
if (!lit_read_code_unit_from_hex (parser_ctx_p->input_curr_p, 2, &code_unit))
{
return ecma_raise_syntax_error (ECMA_ERR_MSG ("invalid character class, end of string after '\\x'"));
}
parser_ctx_p->input_curr_p += 2;
if (is_range == false && lit_utf8_peek_next (parser_ctx_p->input_curr_p) == LIT_CHAR_MINUS)
{
start = code_unit;
continue;
}
ch = code_unit;
}
else if (ch == LIT_CHAR_LOWERCASE_U)
{
ecma_char_t code_unit;
if (!lit_read_code_unit_from_hex (parser_ctx_p->input_curr_p, 4, &code_unit))
{
return ecma_raise_syntax_error (ECMA_ERR_MSG ("invalid character class, end of string after '\\u'"));
}
parser_ctx_p->input_curr_p += 4;
if (is_range == false && lit_utf8_peek_next (parser_ctx_p->input_curr_p) == LIT_CHAR_MINUS)
{
start = code_unit;
continue;
}
ch = code_unit;
}
else if (ch == LIT_CHAR_LOWERCASE_D)
{
append_char_class (re_ctx_p, LIT_CHAR_ASCII_DIGITS_BEGIN, LIT_CHAR_ASCII_DIGITS_END);
ch = LIT_CHAR_UNDEF;
}
else if (ch == LIT_CHAR_UPPERCASE_D)
{
append_char_class (re_ctx_p, LIT_CHAR_NULL, LIT_CHAR_ASCII_DIGITS_BEGIN - 1);
append_char_class (re_ctx_p, LIT_CHAR_ASCII_DIGITS_END + 1, LIT_UTF16_CODE_UNIT_MAX);
ch = LIT_CHAR_UNDEF;
}
else if (ch == LIT_CHAR_LOWERCASE_S)
{
append_char_class (re_ctx_p, LIT_CHAR_TAB, LIT_CHAR_CR);
append_char_class (re_ctx_p, LIT_CHAR_SP, LIT_CHAR_SP);
append_char_class (re_ctx_p, LIT_CHAR_NBSP, LIT_CHAR_NBSP);
append_char_class (re_ctx_p, 0x1680UL, 0x1680UL); 
append_char_class (re_ctx_p, 0x180EUL, 0x180EUL); 
append_char_class (re_ctx_p, 0x2000UL, 0x200AUL); 
append_char_class (re_ctx_p, LIT_CHAR_LS, LIT_CHAR_PS);
append_char_class (re_ctx_p, 0x202FUL, 0x202FUL); 
append_char_class (re_ctx_p, 0x205FUL, 0x205FUL); 
append_char_class (re_ctx_p, 0x3000UL, 0x3000UL); 
append_char_class (re_ctx_p, LIT_CHAR_BOM, LIT_CHAR_BOM);
ch = LIT_CHAR_UNDEF;
}
else if (ch == LIT_CHAR_UPPERCASE_S)
{
append_char_class (re_ctx_p, LIT_CHAR_NULL, LIT_CHAR_TAB - 1);
append_char_class (re_ctx_p, LIT_CHAR_CR + 1, LIT_CHAR_SP - 1);
append_char_class (re_ctx_p, LIT_CHAR_SP + 1, LIT_CHAR_NBSP - 1);
append_char_class (re_ctx_p, LIT_CHAR_NBSP + 1, 0x167FUL);
append_char_class (re_ctx_p, 0x1681UL, 0x180DUL);
append_char_class (re_ctx_p, 0x180FUL, 0x1FFFUL);
append_char_class (re_ctx_p, 0x200BUL, LIT_CHAR_LS - 1);
append_char_class (re_ctx_p, LIT_CHAR_PS + 1, 0x202EUL);
append_char_class (re_ctx_p, 0x2030UL, 0x205EUL);
append_char_class (re_ctx_p, 0x2060UL, 0x2FFFUL);
append_char_class (re_ctx_p, 0x3001UL, LIT_CHAR_BOM - 1);
append_char_class (re_ctx_p, LIT_CHAR_BOM + 1, LIT_UTF16_CODE_UNIT_MAX);
ch = LIT_CHAR_UNDEF;
}
else if (ch == LIT_CHAR_LOWERCASE_W)
{
append_char_class (re_ctx_p, LIT_CHAR_0, LIT_CHAR_9);
append_char_class (re_ctx_p, LIT_CHAR_UPPERCASE_A, LIT_CHAR_UPPERCASE_Z);
append_char_class (re_ctx_p, LIT_CHAR_UNDERSCORE, LIT_CHAR_UNDERSCORE);
append_char_class (re_ctx_p, LIT_CHAR_LOWERCASE_A, LIT_CHAR_LOWERCASE_Z);
ch = LIT_CHAR_UNDEF;
}
else if (ch == LIT_CHAR_UPPERCASE_W)
{
append_char_class (re_ctx_p, LIT_CHAR_NULL, LIT_CHAR_0 - 1);
append_char_class (re_ctx_p, LIT_CHAR_9 + 1, LIT_CHAR_UPPERCASE_A - 1);
append_char_class (re_ctx_p, LIT_CHAR_UPPERCASE_Z + 1, LIT_CHAR_UNDERSCORE - 1);
append_char_class (re_ctx_p, LIT_CHAR_UNDERSCORE + 1, LIT_CHAR_LOWERCASE_A - 1);
append_char_class (re_ctx_p, LIT_CHAR_LOWERCASE_Z + 1, LIT_UTF16_CODE_UNIT_MAX);
ch = LIT_CHAR_UNDEF;
}
else if (lit_char_is_octal_digit ((ecma_char_t) ch)
&& ch != LIT_CHAR_0)
{
lit_utf8_decr (&parser_ctx_p->input_curr_p);
ch = (ecma_char_t) re_parse_octal (parser_ctx_p);
}
} 
if (start != LIT_CHAR_UNDEF)
{
if (is_range)
{
if (start > ch)
{
return ecma_raise_syntax_error (ECMA_ERR_MSG ("invalid character class, wrong order"));
}
else
{
append_char_class (re_ctx_p, start, ch);
start = LIT_CHAR_UNDEF;
is_range = false;
}
}
else
{
append_char_class (re_ctx_p, start, start);
start = ch;
}
}
else
{
start = ch;
}
}
while (token_type == RE_TOK_START_CHAR_CLASS || token_type == RE_TOK_START_INV_CHAR_CLASS);
return re_parse_iterator (parser_ctx_p, out_token_p);
}

static int msOGRFileWhichShapes(layerObj *layer, rectObj rect, msOGRFileInfo *psInfo)
{
if (psInfo == NULL || psInfo->hLayer == NULL) {
msSetError(MS_MISCERR, "Assertion failed: OGR layer not opened!!!", "msOGRFileWhichShapes()");
return(MS_FAILURE);
}
char *select = (psInfo->pszSelect) ? msStrdup(psInfo->pszSelect) : NULL;
if ( psInfo->bIsOKForSQLCompose && (psInfo->nLayerIndex == -1 ||
layer->sortBy.nProperties > 0 ||
layer->filter.native_string ||
(psInfo->bPaging && layer->maxfeatures > 0)) ) {
if( psInfo->nLayerIndex == -1 && select == NULL ) {
select = msStrdup(psInfo->pszLayerDef);
OGR_DS_ReleaseResultSet( psInfo->hDS, psInfo->hLayer );
psInfo->hLayer = NULL;
}
else if( select == NULL ) {
const char* pszGeometryColumn;
int i;
select = msStringConcatenate(select, "SELECT ");
for(i = 0; i < layer->numitems; i++) {
if( i > 0 )
select = msStringConcatenate(select, ", ");
select = msStringConcatenate(select, "\"");
select = msStringConcatenate(select, layer->items[i]);
select = msStringConcatenate(select, "\"");
}
if( layer->numitems > 0 )
select = msStringConcatenate(select, ", ");
pszGeometryColumn = OGR_L_GetGeometryColumn(psInfo->hLayer);
if( pszGeometryColumn != NULL && pszGeometryColumn[0] != '\0' ) {
select = msStringConcatenate(select, "\"");
select = msStringConcatenate(select, pszGeometryColumn);
select = msStringConcatenate(select, "\"");
} else {
select = msStringConcatenate(select, "*");
}
select = msStringConcatenate(select, " FROM ");
if( psInfo->nLayerIndex == -1 )
{
select = msStringConcatenate(select, "(");
select = msStringConcatenate(select, psInfo->pszLayerDef);
select = msStringConcatenate(select, ") MSSUBSELECT");
}
else
{
select = msStringConcatenate(select, "\"");
select = msStringConcatenate(select, OGR_FD_GetName(OGR_L_GetLayerDefn(psInfo->hLayer)));
select = msStringConcatenate(select, "\"");
}
}
char *filter = NULL;
if (msLayerGetProcessingKey(layer, "NATIVE_FILTER") != NULL) {
filter = msStringConcatenate(filter, "(");
filter = msStringConcatenate(filter, msLayerGetProcessingKey(layer, "NATIVE_FILTER"));
filter = msStringConcatenate(filter, ")");
}
if (psInfo->dialect) {
if (EQUAL(psInfo->dialect, "Spatialite") || EQUAL(psInfo->dialect, "PostgreSQL")) {
const char *sql = layer->filter.native_string;
if (sql && *sql != '\0') {
if (filter) filter = msStringConcatenate(filter, "AND ");
filter = msStringConcatenate(filter, "(");
filter = msStringConcatenate(filter, sql);
filter = msStringConcatenate(filter, ")");
}
}
}
if (psInfo->rect_is_defined) {
rect.minx = MAX(psInfo->rect.minx, rect.minx);
rect.miny = MAX(psInfo->rect.miny, rect.miny);
rect.maxx = MIN(psInfo->rect.maxx, rect.maxx);
rect.maxy = MIN(psInfo->rect.maxy, rect.maxy);
}
psInfo->rect = rect;
bool bOffsetAlreadyAdded = false;
if (psInfo->dialect) {
if (EQUAL(psInfo->dialect, "PostgreSQL")) {
if (filter) filter = msStringConcatenate(filter, " AND");
const char *col = OGR_L_GetGeometryColumn(psInfo->hLayer);                 filter = msStringConcatenate(filter, " (");
filter = msStringConcatenate(filter, col);
filter = msStringConcatenate(filter, " && ST_MakeEnvelope(");
char *points = (char *)msSmallMalloc(30*2*5);
snprintf(points, 30*4, "%lf,%lf,%lf,%lf", rect.minx, rect.miny, rect.maxx, rect.maxy);
filter = msStringConcatenate(filter, points);
msFree(points);
filter = msStringConcatenate(filter, "))");
} else if (EQUAL(psInfo->dialect, "Spatialite")) {
if (filter) filter = msStringConcatenate(filter, " AND");
filter = msStringConcatenate(filter, " ");
filter = msStringConcatenate(filter, psInfo->pszMainTableName);
filter = msStringConcatenate(filter, ".");
const char* pszFIDColumn = OGR_L_GetFIDColumn(psInfo->hLayer);
if( psInfo->pszRowId )
filter = msStringConcatenate(filter, psInfo->pszRowId);
else if( pszFIDColumn != NULL && pszFIDColumn[0] != '\0' )
filter = msStringConcatenate(filter, pszFIDColumn);
else
filter = msStringConcatenate(filter, "ROWID");
filter = msStringConcatenate(filter, " IN (SELECT ROWID FROM SpatialIndex WHERE f_table_name = '");
filter = msStringConcatenate(filter, psInfo->pszSpatialFilterTableName);
filter = msStringConcatenate(filter, "' ");
const char* pszGeometryColumn = OGR_L_GetGeometryColumn(psInfo->hLayer);
if( pszGeometryColumn != NULL && pszGeometryColumn[0] != '\0' ) {
filter = msStringConcatenate(filter, "AND f_geometry_column = '");
filter = msStringConcatenate(filter, pszGeometryColumn);
filter = msStringConcatenate(filter, "' ");
}
filter = msStringConcatenate(filter, "AND search_frame = GeomFromText('POLYGON((");
char *points = (char *)msSmallMalloc(30*2*5);
snprintf(points, 30*2*5, "%lf %lf,%lf %lf,%lf %lf,%lf %lf,%lf %lf", rect.minx, rect.miny, rect.maxx, rect.miny, rect.maxx, rect.maxy, rect.minx, rect.maxy, rect.minx, rect.miny);
filter = msStringConcatenate(filter, points);
msFree(points);
filter = msStringConcatenate(filter, "))')");
if ( psInfo->bPaging && layer->maxfeatures >= 0 &&
(layer->startindex <= 0 || layer->filter.native_string == NULL) &&
layer->sortBy.nProperties == 0 )
{
char szLimit[50];
snprintf(szLimit, sizeof(szLimit), " LIMIT %d", layer->maxfeatures);
filter = msStringConcatenate(filter, szLimit);
if( layer->startindex > 0 && layer->filter.native_string == NULL )
{
bOffsetAlreadyAdded = true;
char szOffset[50];
snprintf(szOffset, sizeof(szOffset), " OFFSET %d", layer->startindex);
filter = msStringConcatenate(filter, szOffset);
}
}
filter = msStringConcatenate(filter, ")");
}
}
char *sort = NULL;
if( layer->sortBy.nProperties > 0) {
char *strOrderBy = msLayerBuildSQLOrderBy(layer);
if (strOrderBy) {
if( psInfo->nLayerIndex == -1 ) {
if( strcasestr(psInfo->pszLayerDef, " ORDER BY ") == NULL )
sort = msStringConcatenate(sort, " ORDER BY ");
else
sort = msStringConcatenate(sort, ", ");
} else {
sort = msStringConcatenate(sort, " ORDER BY ");
}
sort = msStringConcatenate(sort, strOrderBy);
msFree(strOrderBy);
}
}
if (filter) {
select = msStringConcatenate(select, " WHERE ");
select = msStringConcatenate(select, filter);
msFree(filter);
}
if (sort) {
select = msStringConcatenate(select, " ");
select = msStringConcatenate(select, sort);
msFree(sort);
}
if ( psInfo->bPaging && layer->maxfeatures >= 0 ) {
char szLimit[50];
snprintf(szLimit, sizeof(szLimit), " LIMIT %d", layer->maxfeatures);
select = msStringConcatenate(select, szLimit);
}
if ( !bOffsetAlreadyAdded && psInfo->bPaging && layer->startindex > 0 ) {
char szOffset[50];
snprintf(szOffset, sizeof(szOffset), " OFFSET %d", layer->startindex);
select = msStringConcatenate(select, szOffset);
}
if( layer->debug )
msDebug("msOGRFileWhichShapes: SQL = %s.\n", select);
ACQUIRE_OGR_LOCK;
if( psInfo->nLayerIndex == -1 && psInfo->hLayer != NULL )
{
OGR_DS_ReleaseResultSet( psInfo->hDS, psInfo->hLayer );
}
psInfo->hLayer = OGR_DS_ExecuteSQL( psInfo->hDS, select, NULL, NULL );
psInfo->nLayerIndex = -1;
if( psInfo->hLayer == NULL ) {
RELEASE_OGR_LOCK;
msSetError(MS_OGRERR, "ExecuteSQL(%s) failed.\n%s", "msOGRFileWhichShapes()", select, CPLGetLastErrorMsg());
msFree(select);
return MS_FAILURE;
}
msOGRLayerInitItemInfo(layer);
} 
else {
char *pszOGRFilter = NULL;
if (msLayerGetProcessingKey(layer, "NATIVE_FILTER") != NULL) {
pszOGRFilter = msStringConcatenate(pszOGRFilter, "(");
pszOGRFilter = msStringConcatenate(pszOGRFilter, msLayerGetProcessingKey(layer, "NATIVE_FILTER"));
pszOGRFilter = msStringConcatenate(pszOGRFilter, ")");
}
ACQUIRE_OGR_LOCK;
if( OGR_L_GetGeomType( psInfo->hLayer ) != wkbNone ) {
if (rect.minx == rect.maxx && rect.miny == rect.maxy) {
OGRGeometryH hSpatialFilterPoint = OGR_G_CreateGeometry( wkbPoint );
OGR_G_SetPoint_2D( hSpatialFilterPoint, 0, rect.minx, rect.miny );    
OGR_L_SetSpatialFilter( psInfo->hLayer, hSpatialFilterPoint );
OGR_G_DestroyGeometry( hSpatialFilterPoint );
} else if (rect.minx == rect.maxx || rect.miny == rect.maxy) {
OGRGeometryH hSpatialFilterLine = OGR_G_CreateGeometry( wkbLineString );
OGR_G_AddPoint_2D( hSpatialFilterLine, rect.minx, rect.miny );
OGR_G_AddPoint_2D( hSpatialFilterLine, rect.maxx, rect.maxy );
OGR_L_SetSpatialFilter( psInfo->hLayer, hSpatialFilterLine );
OGR_G_DestroyGeometry( hSpatialFilterLine );
} else {
OGRGeometryH hSpatialFilterPolygon = OGR_G_CreateGeometry( wkbPolygon );
OGRGeometryH hRing = OGR_G_CreateGeometry( wkbLinearRing );
OGR_G_AddPoint_2D( hRing, rect.minx, rect.miny);
OGR_G_AddPoint_2D( hRing, rect.maxx, rect.miny);
OGR_G_AddPoint_2D( hRing, rect.maxx, rect.maxy);
OGR_G_AddPoint_2D( hRing, rect.minx, rect.maxy);
OGR_G_AddPoint_2D( hRing, rect.minx, rect.miny);
OGR_G_AddGeometryDirectly( hSpatialFilterPolygon, hRing );
OGR_L_SetSpatialFilter( psInfo->hLayer, hSpatialFilterPolygon );
OGR_G_DestroyGeometry( hSpatialFilterPolygon );
}
}
psInfo->rect = rect;
if (layer->debug >= MS_DEBUGLEVEL_VVV)
msDebug("msOGRFileWhichShapes: Setting spatial filter to %f %f %f %f\n", rect.minx, rect.miny, rect.maxx, rect.maxy );
if( pszOGRFilter != NULL ) {
if (layer->debug >= MS_DEBUGLEVEL_VVV)
msDebug("msOGRFileWhichShapes: Setting attribute filter to %s\n", pszOGRFilter );
CPLErrorReset();
if( OGR_L_SetAttributeFilter( psInfo->hLayer, pszOGRFilter ) != OGRERR_NONE ) {
msSetError(MS_OGRERR, "SetAttributeFilter(%s) failed on layer %s.\n%s", "msOGRFileWhichShapes()", layer->filter.string+6, layer->name?layer->name:"(null)", CPLGetLastErrorMsg() );
RELEASE_OGR_LOCK;
msFree(pszOGRFilter);
msFree(select);
return MS_FAILURE;
}
msFree(pszOGRFilter);
} else
OGR_L_SetAttributeFilter( psInfo->hLayer, NULL );
}
msFree(select);
OGR_L_ResetReading( psInfo->hLayer );
psInfo->last_record_index_read = -1;
RELEASE_OGR_LOCK;
return MS_SUCCESS;
}

bool DependencyOptimizer::SafeToRemoveIdentity(const NodeDef& node) const {
if (!IsIdentity(node) && !IsIdentityN(node)) {
return true;
}
if (nodes_to_preserve_.find(node.name()) != nodes_to_preserve_.end()) {
return false;
}
if (!fetch_nodes_known_) {
return false;
}
const NodeDef* input = node_map_->GetNode(NodeName(node.input(0)));
CHECK(input != nullptr) << "node = " << node.name()
<< " input = " << node.input(0);
if (IsVariable(*input) || IsRecv(*input)) {
return false;
}
for (const auto& consumer : node_map_->GetOutputs(node.name())) {
if (node.input_size() > 1 && (IsRetval(*consumer) || IsMerge(*consumer))) {
return false;
}
if (IsSwitch(*input)) {
for (const string& consumer_input : consumer->input()) {
if (consumer_input == AsControlDependency(node.name())) {
return false;
}
}
}
}
return true;
}

Str
process_input(struct parsed_tag *tag)
{
int i, w, v, x, y, z, iw, ih;
char *q, *p, *r, *p2, *s;
Str tmp = NULL;
char *qq = "";
int qlen = 0;
if (cur_form_id < 0) {
char *s = "<form_int method=internal action=none>";
tmp = process_form(parse_tag(&s, TRUE));
}
if (tmp == NULL)
tmp = Strnew();
p = "text";
parsedtag_get_value(tag, ATTR_TYPE, &p);
q = NULL;
parsedtag_get_value(tag, ATTR_VALUE, &q);
r = "";
parsedtag_get_value(tag, ATTR_NAME, &r);
w = 20;
parsedtag_get_value(tag, ATTR_SIZE, &w);
i = 20;
parsedtag_get_value(tag, ATTR_MAXLENGTH, &i);
p2 = NULL;
parsedtag_get_value(tag, ATTR_ALT, &p2);
x = parsedtag_exists(tag, ATTR_CHECKED);
y = parsedtag_exists(tag, ATTR_ACCEPT);
z = parsedtag_exists(tag, ATTR_READONLY);
v = formtype(p);
if (v == FORM_UNKNOWN)
return NULL;
if (!q) {
switch (v) {
case FORM_INPUT_IMAGE:
case FORM_INPUT_SUBMIT:
case FORM_INPUT_BUTTON:
q = "SUBMIT";
break;
case FORM_INPUT_RESET:
q = "RESET";
break;
case FORM_INPUT_CHECKBOX:
q = "on";
}
}
if (v == FORM_INPUT_FILE)
q = NULL;
if (q) {
qq = html_quote(q);
qlen = get_strwidth(q);
}
Strcat_charp(tmp, "<pre_int>");
switch (v) {
case FORM_INPUT_PASSWORD:
case FORM_INPUT_TEXT:
case FORM_INPUT_FILE:
case FORM_INPUT_CHECKBOX:
if (displayLinkNumber)
Strcat(tmp, getLinkNumberStr(0));
Strcat_char(tmp, '[');
break;
case FORM_INPUT_RADIO:
if (displayLinkNumber)
Strcat(tmp, getLinkNumberStr(0));
Strcat_char(tmp, '(');
}
Strcat(tmp, Sprintf("<input_alt hseq=\"%d\" fid=\"%d\" type=%s "
"name=\"%s\" width=%d maxlength=%d value=\"%s\"",
cur_hseq++, cur_form_id, p, html_quote(r), w, i, qq));
if (x)
Strcat_charp(tmp, " checked");
if (y)
Strcat_charp(tmp, " accept");
if (z)
Strcat_charp(tmp, " readonly");
Strcat_char(tmp, '>');
if (v == FORM_INPUT_HIDDEN)
Strcat_charp(tmp, "</input_alt></pre_int>");
else {
switch (v) {
case FORM_INPUT_PASSWORD:
case FORM_INPUT_TEXT:
case FORM_INPUT_FILE:
Strcat_charp(tmp, "<u>");
break;
case FORM_INPUT_IMAGE:
s = NULL;
parsedtag_get_value(tag, ATTR_SRC, &s);
if (s) {
Strcat(tmp, Sprintf("<img src=\"%s\"", html_quote(s)));
if (p2)
Strcat(tmp, Sprintf(" alt=\"%s\"", html_quote(p2)));
if (parsedtag_get_value(tag, ATTR_WIDTH, &iw))
Strcat(tmp, Sprintf(" width=\"%d\"", iw));
if (parsedtag_get_value(tag, ATTR_HEIGHT, &ih))
Strcat(tmp, Sprintf(" height=\"%d\"", ih));
Strcat_charp(tmp, " pre_int>");
Strcat_charp(tmp, "</input_alt></pre_int>");
return tmp;
}
case FORM_INPUT_SUBMIT:
case FORM_INPUT_BUTTON:
case FORM_INPUT_RESET:
if (displayLinkNumber)
Strcat(tmp, getLinkNumberStr(-1));
Strcat_charp(tmp, "[");
break;
}
switch (v) {
case FORM_INPUT_PASSWORD:
i = 0;
if (q) {
for (; i < qlen && i < w; i++)
Strcat_char(tmp, '*');
}
for (; i < w; i++)
Strcat_char(tmp, ' ');
break;
case FORM_INPUT_TEXT:
case FORM_INPUT_FILE:
if (q)
Strcat(tmp, textfieldrep(Strnew_charp(q), w));
else {
for (i = 0; i < w; i++)
Strcat_char(tmp, ' ');
}
break;
case FORM_INPUT_SUBMIT:
case FORM_INPUT_BUTTON:
if (p2)
Strcat_charp(tmp, html_quote(p2));
else
Strcat_charp(tmp, qq);
break;
case FORM_INPUT_RESET:
Strcat_charp(tmp, qq);
break;
case FORM_INPUT_RADIO:
case FORM_INPUT_CHECKBOX:
if (x)
Strcat_char(tmp, '*');
else
Strcat_char(tmp, ' ');
break;
}
switch (v) {
case FORM_INPUT_PASSWORD:
case FORM_INPUT_TEXT:
case FORM_INPUT_FILE:
Strcat_charp(tmp, "</u>");
break;
case FORM_INPUT_IMAGE:
case FORM_INPUT_SUBMIT:
case FORM_INPUT_BUTTON:
case FORM_INPUT_RESET:
Strcat_charp(tmp, "]");
}
Strcat_charp(tmp, "</input_alt>");
switch (v) {
case FORM_INPUT_PASSWORD:
case FORM_INPUT_TEXT:
case FORM_INPUT_FILE:
case FORM_INPUT_CHECKBOX:
Strcat_char(tmp, ']');
break;
case FORM_INPUT_RADIO:
Strcat_char(tmp, ')');
}
Strcat_charp(tmp, "</pre_int>");
}
return tmp;
}

static void __mctp_key_remove(struct mctp_sk_key *key, struct net *net,
unsigned long flags, unsigned long reason)
__releases(&key->lock)
__must_hold(&net->mctp.keys_lock)
{
struct sk_buff *skb;
trace_mctp_key_release(key, reason);
skb = key->reasm_head;
key->reasm_head = NULL;
key->reasm_dead = true;
key->valid = false;
mctp_dev_release_key(key->dev, key);
spin_unlock_irqrestore(&key->lock, flags);
hlist_del(&key->hlist);
hlist_del(&key->sklist);
mctp_key_unref(key);
kfree_skb(skb);
}

const u_char *
ns_nprint(netdissect_options *ndo,
register const u_char *cp, register const u_char *bp)
{
register u_int i, l;
register const u_char *rp = NULL;
register int compress = 0;
int chars_processed;
int elt;
int data_size = ndo->ndo_snapend - bp;
if ((l = labellen(ndo, cp)) == (u_int)-1)
return(NULL);
if (!ND_TTEST2(*cp, 1))
return(NULL);
chars_processed = 1;
if (((i = *cp++) & INDIR_MASK) != INDIR_MASK) {
compress = 0;
rp = cp + l;
}
if (i != 0)
while (i && cp < ndo->ndo_snapend) {
if ((i & INDIR_MASK) == INDIR_MASK) {
if (!compress) {
rp = cp + 1;
compress = 1;
}
if (!ND_TTEST2(*cp, 1))
return(NULL);
cp = bp + (((i << 8) | *cp) & 0x3fff);
if ((l = labellen(ndo, cp)) == (u_int)-1)
return(NULL);
if (!ND_TTEST2(*cp, 1))
return(NULL);
i = *cp++;
chars_processed++;
if (chars_processed >= data_size) {
ND_PRINT((ndo, "<LOOP>"));
return (NULL);
}
continue;
}
if ((i & INDIR_MASK) == EDNS0_MASK) {
elt = (i & ~INDIR_MASK);
switch(elt) {
case EDNS0_ELT_BITLABEL:
if (blabel_print(ndo, cp) == NULL)
return (NULL);
break;
default:
ND_PRINT((ndo, "<ELT %d>", elt));
return(NULL);
}
} else {
if (fn_printn(ndo, cp, l, ndo->ndo_snapend))
return(NULL);
}
cp += l;
chars_processed += l;
ND_PRINT((ndo, "."));
if ((l = labellen(ndo, cp)) == (u_int)-1)
return(NULL);
if (!ND_TTEST2(*cp, 1))
return(NULL);
i = *cp++;
chars_processed++;
if (!compress)
rp += l + 1;
}
else
ND_PRINT((ndo, "."));
return (rp);
}

GF_EXPORT
char *gf_seng_get_base64_iod(GF_SceneEngine *seng)
{
u32 size, size64;
u8 *buffer, *buf64;
u32 i=0;
GF_StreamContext*sc = NULL;
if (!seng->ctx->root_od) return NULL;
while ((sc = (GF_StreamContext*)gf_list_enum(seng->ctx->streams, &i))) {
if ((sc->streamType == GF_STREAM_SCENE) && (sc->codec_id != GF_CODECID_DIMS))
break;
}
if (!sc) return NULL;
size = 0;
gf_odf_desc_write((GF_Descriptor *) seng->ctx->root_od, &buffer, &size);
buf64 = gf_malloc(size*2);
size64 = gf_base64_encode( buffer, size, buf64, size*2);
buf64[size64] = 0;
gf_free(buffer);
return buf64;
}

int http_connect(int sockfd, const char *host, int port, AyProxyData *proxy)
{
char cmd[512];
char *inputline = NULL;
char *proxy_auth = NULL;
char debug_buff[512];
int remaining = sizeof(cmd) - 1;
