GF_EXPORT
u32 gf_isom_guess_specification(GF_ISOFile *file)
{
u32 count, i, nb_any, nb_m4s, nb_a, nb_v, nb_auxv,nb_scene, nb_od, nb_mp3, nb_aac, nb_m4v, nb_avc, nb_amr, nb_h263, nb_qcelp, nb_evrc, nb_smv, nb_text, nb_pict;
nb_m4s = nb_a = nb_v = nb_auxv = nb_any = nb_scene = nb_od = nb_mp3 = nb_aac = nb_m4v = nb_avc = nb_amr = nb_h263 = nb_qcelp = nb_evrc = nb_smv = nb_text = nb_pict = 0;
if (file->is_jp2) {
if (file->moov) return GF_ISOM_BRAND_MJP2;
return GF_ISOM_BRAND_JP2;
}
if (!file->moov) {
if (!file->meta || !file->meta->handler) return 0;
return file->meta->handler->handlerType;
}
count = gf_isom_get_track_count(file);
for (i=0; i<count; i++) {
u32 mtype = gf_isom_get_media_type(file, i+1);
u32 mstype = gf_isom_get_media_subtype(file, i+1, 1);
if (mtype==GF_ISOM_MEDIA_SCENE) {
nb_scene++;
if (gf_isom_get_sample_count(file, i+1)>1) nb_m4s++;
} else if (mtype==GF_ISOM_MEDIA_OD) {
nb_od++;
if (gf_isom_get_sample_count(file, i+1)>1) nb_m4s++;
}
else if ((mtype==GF_ISOM_MEDIA_TEXT) || (mtype==GF_ISOM_MEDIA_SUBT)) nb_text++;
else if ((mtype==GF_ISOM_MEDIA_AUDIO) || gf_isom_is_video_handler_type(mtype) ) {
switch (mstype) {
case GF_ISOM_SUBTYPE_3GP_AMR:
case GF_ISOM_SUBTYPE_3GP_AMR_WB:
nb_amr++;
break;
case GF_ISOM_SUBTYPE_3GP_H263:
nb_h263++;
break;
case GF_ISOM_SUBTYPE_3GP_EVRC:
nb_evrc++;
break;
case GF_ISOM_SUBTYPE_3GP_QCELP:
nb_qcelp++;
break;
case GF_ISOM_SUBTYPE_3GP_SMV:
nb_smv++;
break;
case GF_ISOM_SUBTYPE_AVC_H264:
case GF_ISOM_SUBTYPE_AVC2_H264:
case GF_ISOM_SUBTYPE_AVC3_H264:
case GF_ISOM_SUBTYPE_AVC4_H264:
nb_avc++;
break;
case GF_ISOM_SUBTYPE_SVC_H264:
case GF_ISOM_SUBTYPE_MVC_H264:
nb_avc++;
break;
case GF_ISOM_SUBTYPE_MPEG4:
case GF_ISOM_SUBTYPE_MPEG4_CRYP:
{
GF_DecoderConfig *dcd = gf_isom_get_decoder_config(file, i+1, 1);
switch (dcd->streamType) {
case GF_STREAM_VISUAL:
if (dcd->objectTypeIndication==GF_CODECID_MPEG4_PART2) nb_m4v++;
else if ((dcd->objectTypeIndication==GF_CODECID_AVC) || (dcd->objectTypeIndication==GF_CODECID_SVC) || (dcd->objectTypeIndication==GF_CODECID_MVC)) nb_avc++;
else nb_v++;
break;
case GF_STREAM_AUDIO:
switch (dcd->objectTypeIndication) {
case GF_CODECID_AAC_MPEG2_MP:
case GF_CODECID_AAC_MPEG2_LCP:
case GF_CODECID_AAC_MPEG2_SSRP:
case GF_CODECID_AAC_MPEG4:
nb_aac++;
break;
case GF_CODECID_MPEG2_PART3:
case GF_CODECID_MPEG_AUDIO:
nb_mp3++;
break;
case GF_CODECID_EVRC:
nb_evrc++;
break;
case GF_CODECID_SMV:
nb_smv++;
break;
case GF_CODECID_QCELP:
nb_qcelp++;
break;
default:
nb_a++;
break;
}
break;
default:
nb_any++;
break;
}
gf_odf_desc_del((GF_Descriptor *)dcd);
}
break;
default:
if (mtype==GF_ISOM_MEDIA_VISUAL) nb_v++;
else if (mtype==GF_ISOM_MEDIA_AUXV) nb_auxv++;
else if (mtype==GF_ISOM_MEDIA_PICT) nb_pict++;
else nb_a++;
break;
}
} else if ((mtype==GF_ISOM_SUBTYPE_MPEG4) || (mtype==GF_ISOM_SUBTYPE_MPEG4_CRYP)) nb_m4s++;
else nb_any++;
}
if (nb_any) return GF_ISOM_BRAND_ISOM;
if (nb_qcelp || nb_evrc || nb_smv) {
if (nb_m4s || nb_avc || nb_scene || nb_od || nb_mp3 || nb_a || nb_v) return GF_ISOM_BRAND_ISOM;
return GF_ISOM_BRAND_3G2A;
}
if (nb_v || nb_a || nb_m4s) return GF_ISOM_BRAND_MP42;
nb_v = nb_m4v + nb_avc + nb_h263;
nb_a = nb_mp3 + nb_aac + nb_amr;
if (nb_avc) {
if (!nb_scene && !nb_od) return GF_ISOM_BRAND_AVC1;
return GF_ISOM_BRAND_MP42;
}
if (nb_mp3) {
if (!nb_text && (nb_v<=1) && (nb_a<=1) && (nb_scene==1) && (nb_od==1))
return GF_ISOM_BRAND_ISMA;
return GF_ISOM_BRAND_MP42;
}
if (nb_scene || nb_od) {
if (nb_amr || nb_h263) return GF_ISOM_BRAND_ISOM;
return GF_ISOM_BRAND_MP42;
}
if (!nb_amr && !nb_h263 && !nb_text) {
if ((nb_v<=1) && (nb_a<=1)) return GF_ISOM_BRAND_ISMA;
return GF_ISOM_BRAND_MP42;
}
if ((nb_v<=1) && (nb_a<=1) && (nb_text<=1)) return nb_text ? GF_ISOM_BRAND_3GP6 : GF_ISOM_BRAND_3GP5;
return GF_ISOM_BRAND_3GG6;
}

cmdopts_t *cmdopts_parse(int argc, char **argv)
{
enum {
CMDOPT_HELP = 0,
CMDOPT_VERBOSE,
CMDOPT_QUIET,
CMDOPT_INFILE,
CMDOPT_INFMT,
CMDOPT_INOPT,
CMDOPT_OUTFILE,
CMDOPT_OUTFMT,
CMDOPT_OUTOPT,
CMDOPT_VERSION,
CMDOPT_DEBUG,
CMDOPT_CMPTNO,
CMDOPT_SRGB,
CMDOPT_MAXMEM,
CMDOPT_LIST_ENABLED_CODECS,
CMDOPT_LIST_ALL_CODECS,
CMDOPT_ENABLE_FORMAT,
CMDOPT_ENABLE_ALL_FORMATS,
};
static const jas_opt_t cmdoptions[] = {
{CMDOPT_HELP, "help", 0},
{CMDOPT_VERBOSE, "verbose", 0},
{CMDOPT_QUIET, "quiet", 0},
{CMDOPT_QUIET, "q", 0},
{CMDOPT_INFILE, "input", JAS_OPT_HASARG},
{CMDOPT_INFILE, "f", JAS_OPT_HASARG},
{CMDOPT_INFMT, "input-format", JAS_OPT_HASARG},
{CMDOPT_INFMT, "t", JAS_OPT_HASARG},
{CMDOPT_INOPT, "input-option", JAS_OPT_HASARG},
{CMDOPT_INOPT, "o", JAS_OPT_HASARG},
{CMDOPT_OUTFILE, "output", JAS_OPT_HASARG},
{CMDOPT_OUTFILE, "F", JAS_OPT_HASARG},
{CMDOPT_OUTFMT, "output-format", JAS_OPT_HASARG},
{CMDOPT_OUTFMT, "T", JAS_OPT_HASARG},
{CMDOPT_OUTOPT, "output-option", JAS_OPT_HASARG},
{CMDOPT_OUTOPT, "O", JAS_OPT_HASARG},
{CMDOPT_VERSION, "version", 0},
{CMDOPT_DEBUG, "debug-level", JAS_OPT_HASARG},
{CMDOPT_CMPTNO, "cmptno", JAS_OPT_HASARG},
{CMDOPT_SRGB, "force-srgb", 0},
{CMDOPT_SRGB, "S", 0},
{CMDOPT_MAXMEM, "memory-limit", JAS_OPT_HASARG},
{CMDOPT_LIST_ENABLED_CODECS, "list-enabled-formats", 0},
{CMDOPT_LIST_ALL_CODECS, "list-all-formats", 0},
{CMDOPT_ENABLE_FORMAT, "enable-format", JAS_OPT_HASARG},
{CMDOPT_ENABLE_ALL_FORMATS, "enable-all-formats", 0},
{-1, 0, 0}
};
cmdopts_t *cmdopts;
int c;
if (!(cmdopts = malloc(sizeof(cmdopts_t)))) {
fprintf(stderr, "error: insufficient memory\n");
exit(EXIT_FAILURE);
}
cmdopts->infile = 0;
cmdopts->infmt = -1;
cmdopts->infmt_str = 0;
cmdopts->inopts = 0;
cmdopts->inoptsbuf[0] = '\0';
cmdopts->outfile = 0;
cmdopts->outfmt = -1;
cmdopts->outfmt_str = 0;
cmdopts->outopts = 0;
cmdopts->outoptsbuf[0] = '\0';
cmdopts->verbose = 0;
cmdopts->version = 0;
cmdopts->cmptno = -1;
cmdopts->debug = 0;
cmdopts->srgb = 0;
cmdopts->list_codecs = 0;
cmdopts->list_codecs_all = 0;
cmdopts->help = 0;
cmdopts->max_mem = get_default_max_mem_usage();
cmdopts->enable_format = 0;
cmdopts->enable_all_formats = 0;
while ((c = jas_getopt(argc, argv, cmdoptions)) != EOF) {
switch (c) {
case CMDOPT_HELP:
cmdopts->help = 1;
break;
case CMDOPT_VERBOSE:
cmdopts->verbose = 1;
break;
case CMDOPT_QUIET:
cmdopts->verbose = -1;
break;
case CMDOPT_VERSION:
cmdopts->version = 1;
break;
case CMDOPT_LIST_ENABLED_CODECS:
cmdopts->list_codecs = 1;
cmdopts->list_codecs_all = 0;
break;
case CMDOPT_LIST_ALL_CODECS:
cmdopts->list_codecs = 1;
cmdopts->list_codecs_all = 1;
break;
case CMDOPT_DEBUG:
cmdopts->debug = atoi(jas_optarg);
break;
case CMDOPT_INFILE:
cmdopts->infile = jas_optarg;
break;
case CMDOPT_INFMT:
cmdopts->infmt_str= jas_optarg;
break;
case CMDOPT_INOPT:
addopt(cmdopts->inoptsbuf, OPTSMAX, jas_optarg);
cmdopts->inopts = cmdopts->inoptsbuf;
break;
case CMDOPT_OUTFILE:
cmdopts->outfile = jas_optarg;
break;
case CMDOPT_OUTFMT:
cmdopts->outfmt_str = jas_optarg;
break;
case CMDOPT_OUTOPT:
addopt(cmdopts->outoptsbuf, OPTSMAX, jas_optarg);
cmdopts->outopts = cmdopts->outoptsbuf;
break;
case CMDOPT_CMPTNO:
cmdopts->cmptno = atoi(jas_optarg);
break;
case CMDOPT_SRGB:
cmdopts->srgb = 1;
break;
case CMDOPT_MAXMEM:
cmdopts->max_mem = strtoull(jas_optarg, 0, 10);
break;
case CMDOPT_ENABLE_FORMAT:
cmdopts->enable_format = jas_optarg;
break;
case CMDOPT_ENABLE_ALL_FORMATS:
cmdopts->enable_all_formats = 1;
break;
default:
badusage();
break;
}
}
while (jas_optind < argc) {
fprintf(stderr,
"warning: ignoring bogus command line argument %s\n",
argv[jas_optind]);
++jas_optind;
}
if (cmdopts->version || cmdopts->list_codecs || cmdopts->help) {
goto done;
}
if (!cmdopts->outfmt_str && !cmdopts->outfile) {
fprintf(stderr, "error: cannot determine output format\n");
badusage();
}
done:
return cmdopts;
}

char *format_timespan(char *buf, size_t l, usec_t t, usec_t accuracy) {
static const struct {
const char *suffix;
usec_t usec;
} table[] = {
{ "y",     USEC_PER_YEAR   },
{ "month", USEC_PER_MONTH  },
{ "w",     USEC_PER_WEEK   },
{ "d",     USEC_PER_DAY    },
{ "h",     USEC_PER_HOUR   },
{ "min",   USEC_PER_MINUTE },
{ "s",     USEC_PER_SEC    },
{ "ms",    USEC_PER_MSEC   },
{ "us",    1               },
};
char *p = buf;
bool something = false;
assert(buf);
assert(l > 0);
if (t == USEC_INFINITY) {
strncpy(p, "infinity", l-1);
p[l-1] = 0;
return p;
}
if (t <= 0) {
strncpy(p, "0", l-1);
p[l-1] = 0;
return p;
}
for (size_t i = 0; i < ELEMENTSOF(table); i++) {
int k = 0;
size_t n;
bool done = false;
usec_t a, b;
if (t <= 0)
break;
if (t < accuracy && something)
break;
if (t < table[i].usec)
continue;
if (l <= 1)
break;
a = t / table[i].usec;
b = t % table[i].usec;
if (t < USEC_PER_MINUTE && b > 0) {
signed char j = 0;
for (usec_t cc = table[i].usec; cc > 1; cc /= 10)
j++;
for (usec_t cc = accuracy; cc > 1; cc /= 10) {
b /= 10;
j--;
}
if (j > 0) {
k = snprintf(p, l,
"%s"USEC_FMT".%0*"PRI_USEC"%s",
p > buf ? " " : "",
a,
j,
b,
table[i].suffix);
t = 0;
done = true;
}
}
if (!done) {
k = snprintf(p, l,
"%s"USEC_FMT"%s",
p > buf ? " " : "",
a,
table[i].suffix);
t = b;
}
n = MIN((size_t) k, l);
l -= n;
p += n;
something = true;
}
*p = 0;
return buf;
}

