de265_error read_scaling_list(bitreader* br, const seq_parameter_set* sps,
scaling_list_data* sclist, bool inPPS)
{
int dc_coeff[4][6];
for (int sizeId=0;sizeId<4;sizeId++) {
uint8_t scaling_list[6][32*32];
for (int matrixId=0 ; matrixId<6 ; matrixId += (sizeId==3 ? 3 : 1)) {
uint8_t* curr_scaling_list = scaling_list[matrixId];
int scaling_list_dc_coef;
int canonicalMatrixId = matrixId;
if (sizeId==3 && matrixId==1) { canonicalMatrixId=3; }
char scaling_list_pred_mode_flag = get_bits(br,1);
if (!scaling_list_pred_mode_flag) {
int scaling_list_pred_matrix_id_delta = get_uvlc(br);
if (scaling_list_pred_matrix_id_delta == UVLC_ERROR ||
scaling_list_pred_matrix_id_delta > matrixId) {
return DE265_ERROR_CODED_PARAMETER_OUT_OF_RANGE;
}
dc_coeff[sizeId][matrixId] = 16;
scaling_list_dc_coef       = 16;
if (scaling_list_pred_matrix_id_delta==0) {
if (sizeId==0) {
memcpy(curr_scaling_list, default_ScalingList_4x4, 16);
}
else {
if (canonicalMatrixId<3)
{ memcpy(curr_scaling_list, default_ScalingList_8x8_intra,64); }
else
{ memcpy(curr_scaling_list, default_ScalingList_8x8_inter,64); }
}
}
else {
if (sizeId==3) { assert(scaling_list_pred_matrix_id_delta==1); }
int mID = matrixId - scaling_list_pred_matrix_id_delta;
int len = (sizeId == 0 ? 16 : 64);
memcpy(curr_scaling_list, scaling_list[mID], len);
scaling_list_dc_coef       = dc_coeff[sizeId][mID];
dc_coeff[sizeId][matrixId] = dc_coeff[sizeId][mID];
}
}
else {
int nextCoef=8;
int coefNum = (sizeId==0 ? 16 : 64);
if (sizeId>1) {
scaling_list_dc_coef = get_svlc(br);
if (scaling_list_dc_coef < -7 ||
scaling_list_dc_coef > 247) {
return DE265_ERROR_CODED_PARAMETER_OUT_OF_RANGE;
}
scaling_list_dc_coef += 8;
nextCoef=scaling_list_dc_coef;
dc_coeff[sizeId][matrixId] = scaling_list_dc_coef;
}
else {
scaling_list_dc_coef = 16;
}
for (int i=0;i<coefNum;i++) {
int scaling_list_delta_coef = get_svlc(br);
if (scaling_list_delta_coef < -128 ||
scaling_list_delta_coef >  127) {
return DE265_ERROR_CODED_PARAMETER_OUT_OF_RANGE;
}
nextCoef = (nextCoef + scaling_list_delta_coef + 256) % 256;
curr_scaling_list[i] = nextCoef;
}
}
switch (sizeId) {
case 0:
fill_scaling_factor(&sclist->ScalingFactor_Size0[matrixId][0][0], curr_scaling_list, 0);
break;
case 1:
fill_scaling_factor(&sclist->ScalingFactor_Size1[matrixId][0][0], curr_scaling_list, 1);
break;
case 2:
fill_scaling_factor(&sclist->ScalingFactor_Size2[matrixId][0][0], curr_scaling_list, 2);
sclist->ScalingFactor_Size2[matrixId][0][0] = scaling_list_dc_coef;
break;
case 3:
fill_scaling_factor(&sclist->ScalingFactor_Size3[matrixId][0][0], curr_scaling_list, 3);
sclist->ScalingFactor_Size3[matrixId][0][0] = scaling_list_dc_coef;
break;
}
}
}
const position* scan = get_scan_order(3, 0 );
for (int matrixId=0;matrixId<6;matrixId++)
if (matrixId!=0 && matrixId!=3) {
for (int i=0;i<64;i++) {
int x = scan[i].x;
int y = scan[i].y;
int v = sclist->ScalingFactor_Size1[matrixId][y][x];
for (int dy=0;dy<4;dy++)
for (int dx=0;dx<4;dx++) {
sclist->ScalingFactor_Size3[matrixId][4*y+dy][4*x+dx] = v;
}
}
sclist->ScalingFactor_Size3[matrixId][0][0] = sclist->ScalingFactor_Size1[matrixId][0][0];
}
return DE265_OK;
}

flb_sds_t flb_msgpack_raw_to_avro_sds(const void *in_buf, size_t in_size, struct flb_avro_fields *ctx)
{
msgpack_unpacked result;
msgpack_object *root;
size_t avro_buffer_size = in_size * 3;
char *out_buff = flb_malloc(avro_buffer_size);
avro_writer_t awriter;
flb_debug("in flb_msgpack_raw_to_avro_sds\n");
flb_debug("schemaID:%s:\n", ctx->schema_id);
flb_debug("schema string:%s:\n", ctx->schema_str);
size_t schema_json_len = flb_sds_len(ctx->schema_str);
avro_value_t  aobject;
assert(in_buf != NULL);
avro_value_iface_t  *aclass = NULL;
avro_schema_t aschema;
aclass = flb_avro_init(&aobject, (char *)ctx->schema_str, schema_json_len, &aschema);
if (!aclass) {
flb_error("Failed init avro:%s:n", avro_strerror());
flb_free(out_buff);
return NULL;
}
msgpack_unpacked_init(&result);
if (msgpack_unpack_next(&result, in_buf, in_size, NULL) != MSGPACK_UNPACK_SUCCESS) {
flb_error("msgpack_unpack problem\n");
avro_value_decref(&aobject);
avro_value_iface_decref(aclass);
avro_schema_decref(aschema);
flb_free(out_buff);
return NULL;
}
root = &result.data;
flb_debug("calling flb_msgpack_to_avro\n");
if (flb_msgpack_to_avro(&aobject, root) != FLB_TRUE) {
flb_errno();
flb_error("Failed msgpack to avro\n");
msgpack_unpacked_destroy(&result);
avro_value_decref(&aobject);
avro_value_iface_decref(aclass);
avro_schema_decref(aschema);
flb_free(out_buff);
return NULL;
}
flb_debug("before avro_writer_memory\n");
awriter = avro_writer_memory(out_buff, avro_buffer_size);
if (awriter == NULL) {
flb_error("Unable to init avro writer\n");
msgpack_unpacked_destroy(&result);
avro_value_decref(&aobject);
avro_value_iface_decref(aclass);
avro_schema_decref(aschema);
flb_free(out_buff);
return NULL;
}
int rval;
rval = avro_write(awriter, "\0", 1);
if (rval != 0) {
flb_error("Unable to write magic byte\n");
avro_writer_free(awriter);
avro_value_decref(&aobject);
avro_value_iface_decref(aclass);
avro_schema_decref(aschema);
msgpack_unpacked_destroy(&result);
flb_free(out_buff);
return NULL;
}
const char *pos = ctx->schema_id;
unsigned char val[16];
size_t count;
for (count = 0; count < sizeof val/sizeof *val; count++) {
sscanf(pos, "%2hhx", &val[count]);
pos += 2;
}
rval = avro_write(awriter, val, 16);
if (rval != 0) {
flb_error("Unable to write schemaid\n");
avro_writer_free(awriter);
avro_value_decref(&aobject);
avro_value_iface_decref(aclass);
avro_schema_decref(aschema);
msgpack_unpacked_destroy(&result);
flb_free(out_buff);
return NULL;
}
if (avro_value_write(awriter, &aobject)) {
flb_error("Unable to write avro value to memory buffer\nMessage: %s\n", avro_strerror());
avro_writer_free(awriter);
avro_value_decref(&aobject);
avro_value_iface_decref(aclass);
avro_schema_decref(aschema);
msgpack_unpacked_destroy(&result);
flb_free(out_buff);
return NULL;
}
flb_debug("before avro_writer_flush\n");
avro_writer_flush(awriter);
int64_t bytes_written = avro_writer_tell(awriter);
avro_writer_free(awriter);
avro_value_decref(&aobject);
avro_value_iface_decref(aclass);
avro_schema_decref(aschema);
msgpack_unpacked_destroy(&result);
flb_debug("after memory free:bytes written:%zu:\n", bytes_written);
flb_sds_t ret =  flb_sds_create_len(out_buff, bytes_written);
flb_free(out_buff);
flb_debug("shrunk flb sds:\n");
flb_debug("sds len:%zu:\n", flb_sds_len(ret));
flb_debug("sds alloc:%zu:\n", flb_sds_alloc(ret));
flb_debug("sds avail:%zu:\n", flb_sds_avail(ret));
return ret;
}

static bfd_boolean
aout_get_external_symbols (bfd *abfd)
{
