static int pfkey_register(struct sock *sk, struct sk_buff *skb, const struct sadb_msg *hdr, void * const *ext_hdrs)
{
struct pfkey_sock *pfk = pfkey_sk(sk);
struct sk_buff *supp_skb;
if (hdr->sadb_msg_satype > SADB_SATYPE_MAX)
return -EINVAL;
if (hdr->sadb_msg_satype != SADB_SATYPE_UNSPEC) {
if (pfk->registered&(1<<hdr->sadb_msg_satype))
return -EEXIST;
pfk->registered |= (1<<hdr->sadb_msg_satype);
}
xfrm_probe_algs();
supp_skb = compose_sadb_supported(hdr, GFP_KERNEL);
if (!supp_skb) {
if (hdr->sadb_msg_satype != SADB_SATYPE_UNSPEC)
pfk->registered &= ~(1<<hdr->sadb_msg_satype);
return -ENOBUFS;
}
pfkey_broadcast(supp_skb, GFP_KERNEL, BROADCAST_REGISTERED, sk,
sock_net(sk));
return 0;
}

asmlinkage int arm_syscall(int no, struct pt_regs *regs)
{
struct thread_info *thread = current_thread_info();
siginfo_t info;
if ((no >> 16) != (__ARM_NR_BASE>> 16))
return bad_syscall(no, regs);
switch (no & 0xffff) {
case 0: 
info.si_signo = SIGSEGV;
info.si_errno = 0;
info.si_code  = SEGV_MAPERR;
info.si_addr  = NULL;
arm_notify_die("branch through zero", regs, &info, 0, 0);
return 0;
case NR(breakpoint): 
regs->ARM_pc -= thumb_mode(regs) ? 2 : 4;
ptrace_break(current, regs);
return regs->ARM_r0;
case NR(cacheflush):
return do_cache_op(regs->ARM_r0, regs->ARM_r1, regs->ARM_r2);
case NR(usr26):
if (!(elf_hwcap & HWCAP_26BIT))
break;
regs->ARM_cpsr &= ~MODE32_BIT;
return regs->ARM_r0;
case NR(usr32):
if (!(elf_hwcap & HWCAP_26BIT))
break;
regs->ARM_cpsr |= MODE32_BIT;
return regs->ARM_r0;
case NR(set_tls):
thread->tp_value = regs->ARM_r0;
if (tls_emu)
return 0;
if (has_tls_reg) {
asm ("mcr p15, 0, %0, c13, c0, 3"
: : "r" (regs->ARM_r0));
} else {
*((unsigned int *)0xffff0ff0) = regs->ARM_r0;
}
return 0;
#ifdef CONFIG_NEEDS_SYSCALL_FOR_CMPXCHG
case NR(cmpxchg):
for (;;) {
extern void do_DataAbort(unsigned long addr, unsigned int fsr,
struct pt_regs *regs);
unsigned long val;
unsigned long addr = regs->ARM_r2;
struct mm_struct *mm = current->mm;
pgd_t *pgd; pmd_t *pmd; pte_t *pte;
spinlock_t *ptl;
regs->ARM_cpsr &= ~PSR_C_BIT;
down_read(&mm->mmap_sem);
pgd = pgd_offset(mm, addr);
if (!pgd_present(*pgd))
goto bad_access;
pmd = pmd_offset(pgd, addr);
if (!pmd_present(*pmd))
goto bad_access;
pte = pte_offset_map_lock(mm, pmd, addr, &ptl);
if (!pte_present(*pte) || !pte_write(*pte) || !pte_dirty(*pte)) {
pte_unmap_unlock(pte, ptl);
goto bad_access;
}
val = *(unsigned long *)addr;
val -= regs->ARM_r0;
if (val == 0) {
*(unsigned long *)addr = regs->ARM_r1;
regs->ARM_cpsr |= PSR_C_BIT;
}
pte_unmap_unlock(pte, ptl);
up_read(&mm->mmap_sem);
return val;
bad_access:
up_read(&mm->mmap_sem);
do_DataAbort(addr, 15 + (1 << 11), regs);
}
#endif
default:
if ((no & 0xffff) <= 0x7ff)
return -ENOSYS;
break;
}
#ifdef CONFIG_DEBUG_USER
if (user_debug & UDBG_SYSCALL) {
printk("[%d] %s: arm syscall %d\n",
task_pid_nr(current), current->comm, no);
dump_instr("", regs);
if (user_mode(regs)) {
__show_regs(regs);
c_backtrace(regs->ARM_fp, processor_mode(regs));
}
}
#endif
info.si_signo = SIGILL;
info.si_errno = 0;
info.si_code  = ILL_ILLTRP;
info.si_addr  = (void __user *)instruction_pointer(regs) -
(thumb_mode(regs) ? 2 : 4);
arm_notify_die("Oops - bad syscall(2)", regs, &info, no, 0);
return 0;
}

uint32_t
guest_walk_tables(struct vcpu *v, struct p2m_domain *p2m,
unsigned long va, walk_t *gw, 
uint32_t pfec, mfn_t top_mfn, void *top_map)
{
struct domain *d = v->domain;
p2m_type_t p2mt;
guest_l1e_t *l1p = NULL;
guest_l2e_t *l2p = NULL;
#if GUEST_PAGING_LEVELS >= 4 
guest_l3e_t *l3p = NULL;
guest_l4e_t *l4p;
#endif
unsigned int pkey;
uint32_t gflags, mflags, iflags, rc = 0;
bool_t smep = 0, smap = 0;
bool_t pse1G = 0, pse2M = 0;
p2m_query_t qt = P2M_ALLOC | P2M_UNSHARE;
perfc_incr(guest_walk);
memset(gw, 0, sizeof(*gw));
gw->va = va;
mflags = mandatory_flags(v, pfec);
iflags = (_PAGE_NX_BIT | _PAGE_INVALID_BITS);
if ( is_hvm_domain(d) && !(pfec & PFEC_user_mode) )
{
struct segment_register seg;
const struct cpu_user_regs *regs = guest_cpu_user_regs();
smep =  hvm_smep_enabled(v) && (pfec & PFEC_insn_fetch);
switch ( v->arch.smap_check_policy )
{
case SMAP_CHECK_HONOR_CPL_AC:
hvm_get_segment_register(v, x86_seg_ss, &seg);
smap = hvm_smap_enabled(v) &&
((seg.attr.fields.dpl == 3) ||
!(regs->eflags & X86_EFLAGS_AC));
break;
case SMAP_CHECK_ENABLED:
smap = hvm_smap_enabled(v);
break;
default:
ASSERT(v->arch.smap_check_policy == SMAP_CHECK_DISABLED);
break;
}
}
if ( smep || smap )
mflags |= _PAGE_USER;
#if GUEST_PAGING_LEVELS >= 3 
#if GUEST_PAGING_LEVELS >= 4 
gw->l4mfn = top_mfn;
l4p = (guest_l4e_t *) top_map;
gw->l4e = l4p[guest_l4_table_offset(va)];
gflags = guest_l4e_get_flags(gw->l4e) ^ iflags;
if ( !(gflags & _PAGE_PRESENT) ) {
rc |= _PAGE_PRESENT;
goto out;
}
rc |= ((gflags & mflags) ^ mflags);
l3p = map_domain_gfn(p2m, 
guest_l4e_get_gfn(gw->l4e), 
&gw->l3mfn,
&p2mt,
qt,
&rc); 
if(l3p == NULL)
goto out;
gw->l3e = l3p[guest_l3_table_offset(va)];
pkey = guest_l3e_get_pkey(gw->l3e);
gflags = guest_l3e_get_flags(gw->l3e) ^ iflags;
if ( !(gflags & _PAGE_PRESENT) ) {
rc |= _PAGE_PRESENT;
goto out;
}
rc |= ((gflags & mflags) ^ mflags);
pse1G = (gflags & _PAGE_PSE) && guest_supports_1G_superpages(v); 
if ( pse1G )
{
gfn_t start = guest_l3e_get_gfn(gw->l3e);
int flags = (_PAGE_PRESENT|_PAGE_USER|_PAGE_RW|
_PAGE_ACCESSED|_PAGE_DIRTY);
flags |= (guest_l3e_get_flags(gw->l3e)
& (_PAGE_PAT|_PAGE_PWT|_PAGE_PCD));
if ( !(gfn_x(start) & 1) )
flags &= ~_PAGE_PAT;
if ( gfn_x(start) & GUEST_L3_GFN_MASK & ~0x1 )
rc |= _PAGE_INVALID_BITS;
start = _gfn((gfn_x(start) & ~GUEST_L3_GFN_MASK) +
((va >> PAGE_SHIFT) & GUEST_L3_GFN_MASK));
gw->l1e = guest_l1e_from_gfn(start, flags);
gw->l2mfn = gw->l1mfn = _mfn(INVALID_MFN);
goto set_ad;
}
#else 
gw->l3e = ((guest_l3e_t *) top_map)[guest_l3_table_offset(va)];
if ( !(guest_l3e_get_flags(gw->l3e) & _PAGE_PRESENT) ) 
{
rc |= _PAGE_PRESENT;
goto out;
}
#endif 
l2p = map_domain_gfn(p2m, 
guest_l3e_get_gfn(gw->l3e), 
&gw->l2mfn,
&p2mt, 
qt,
&rc); 
if(l2p == NULL)
goto out;
gw->l2e = l2p[guest_l2_table_offset(va)];
#else 
gw->l2mfn = top_mfn;
l2p = (guest_l2e_t *) top_map;
gw->l2e = l2p[guest_l2_table_offset(va)];
#endif 
pkey = guest_l2e_get_pkey(gw->l2e);
gflags = guest_l2e_get_flags(gw->l2e) ^ iflags;
if ( !(gflags & _PAGE_PRESENT) ) {
rc |= _PAGE_PRESENT;
goto out;
}
rc |= ((gflags & mflags) ^ mflags);
pse2M = (gflags & _PAGE_PSE) && guest_supports_superpages(v); 
if ( pse2M )
{
gfn_t start = guest_l2e_get_gfn(gw->l2e);
int flags = (_PAGE_PRESENT|_PAGE_USER|_PAGE_RW|
_PAGE_ACCESSED|_PAGE_DIRTY);
flags |= (guest_l2e_get_flags(gw->l2e)
& (_PAGE_PAT|_PAGE_PWT|_PAGE_PCD));
if ( !(gfn_x(start) & 1) )
flags &= ~_PAGE_PAT;
if ( gfn_x(start) & GUEST_L2_GFN_MASK & ~0x1 )
{
#if GUEST_PAGING_LEVELS == 2
#endif
rc |= _PAGE_INVALID_BITS;
}
start = _gfn((gfn_x(start) & ~GUEST_L2_GFN_MASK) +
guest_l1_table_offset(va));
gw->l1e = guest_l1e_from_gfn(start, flags);
gw->l1mfn = _mfn(INVALID_MFN);
} 
else 
{
l1p = map_domain_gfn(p2m, 
guest_l2e_get_gfn(gw->l2e), 
&gw->l1mfn,
&p2mt,
qt,
&rc);
if(l1p == NULL)
goto out;
gw->l1e = l1p[guest_l1_table_offset(va)];
pkey = guest_l1e_get_pkey(gw->l1e);
gflags = guest_l1e_get_flags(gw->l1e) ^ iflags;
if ( !(gflags & _PAGE_PRESENT) ) {
rc |= _PAGE_PRESENT;
goto out;
}
rc |= ((gflags & mflags) ^ mflags);
}
#if GUEST_PAGING_LEVELS >= 4 
set_ad:
if ( pkey_fault(v, pfec, gflags, pkey) )
rc |= _PAGE_PKEY_BITS;
#endif
if ( smep || smap )
rc ^= _PAGE_USER;
if ( rc == 0 ) 
{
#if GUEST_PAGING_LEVELS == 4 
if ( set_ad_bits(l4p + guest_l4_table_offset(va), &gw->l4e, 0) )
paging_mark_dirty(d, mfn_x(gw->l4mfn));
if ( set_ad_bits(l3p + guest_l3_table_offset(va), &gw->l3e,
(pse1G && (pfec & PFEC_write_access))) )
paging_mark_dirty(d, mfn_x(gw->l3mfn));
#endif
if ( !pse1G ) 
{
if ( set_ad_bits(l2p + guest_l2_table_offset(va), &gw->l2e,
(pse2M && (pfec & PFEC_write_access))) )
paging_mark_dirty(d, mfn_x(gw->l2mfn));            
if ( !pse2M ) 
{
if ( set_ad_bits(l1p + guest_l1_table_offset(va), &gw->l1e, 
(pfec & PFEC_write_access)) )
paging_mark_dirty(d, mfn_x(gw->l1mfn));
}
}
}
out:
#if GUEST_PAGING_LEVELS == 4
if ( l3p ) 
{
unmap_domain_page(l3p);
put_page(mfn_to_page(mfn_x(gw->l3mfn)));
}
#endif
#if GUEST_PAGING_LEVELS >= 3
if ( l2p ) 
{
unmap_domain_page(l2p);
put_page(mfn_to_page(mfn_x(gw->l2mfn)));
}
#endif
if ( l1p ) 
{
unmap_domain_page(l1p);
put_page(mfn_to_page(mfn_x(gw->l1mfn)));
}
return rc;
}

void DecodeGifV2(OpKernelContext* context, StringPiece input) {
OP_REQUIRES(context, channels_ == 0 || channels_ == 3,
errors::InvalidArgument("channels must be 0 or 3 for GIF, got ",
channels_));
if (op_type_ == "DecodeBmp") {
OP_REQUIRES(context, false,
errors::InvalidArgument(
"Trying to decode GIF format using DecodeBmp op. Use "
"`decode_gif` or `decode_image` instead."));
} else if (op_type_ == "DecodeAndCropJpeg") {
OP_REQUIRES(context, false,
errors::InvalidArgument(
"DecodeAndCropJpeg operation can run on JPEG only, but "
"detected GIF."));
}
Tensor* output = nullptr;
int buffer_size = 0;
string error_string;
uint8* buffer = gif::Decode(
input.data(), input.size(),
[&](int num_frames, int width, int height, int channels) -> uint8* {
buffer_size = num_frames * height * width * channels;
Status status;
if (op_type_ == "DecodePng" || op_type_ == "DecodeJpeg") {
if (num_frames == 1) {
status = context->allocate_output(
0, TensorShape({height, width, channels}), &output);
} else {
status = errors::InvalidArgument(
"Got ", num_frames, " frames, but animated gifs ",
"can only be decoded by tf.io.decode_gif or ",
"tf.io.decode_image");
}
} else if (op_type_ == "DecodeGif" ||
(op_type_ == "DecodeImage" && expand_animations_)) {
status = context->allocate_output(
0, TensorShape({num_frames, height, width, channels}), &output);
} else if (op_type_ == "DecodeImage" && !expand_animations_) {
status = context->allocate_output(
0, TensorShape({height, width, channels}), &output);
} else {
status = errors::InvalidArgument("Bad op type ", op_type_);
}
if (!status.ok()) {
VLOG(1) << status;
context->SetStatus(status);
return nullptr;
}
if (data_type_ == DataType::DT_UINT8) {
return output->flat<uint8>().data();
} else {
return new uint8[buffer_size];
}
},
&error_string, expand_animations_);
OP_REQUIRES(context, buffer,
errors::InvalidArgument("Invalid GIF data (size ", input.size(),
"), ", error_string));
if (data_type_ == DataType::DT_UINT8) {
return;
}
std::unique_ptr<uint8[]> buffer_unique_ptr(buffer);
TTypes<uint8>::UnalignedConstFlat buffer_view(buffer, buffer_size);
const auto& device = context->eigen_device<Eigen::ThreadPoolDevice>();
if (data_type_ == DataType::DT_UINT16) {
uint16 scale = floor((std::numeric_limits<uint16>::max() + 1) /
(std::numeric_limits<uint8>::max() + 1));
output->flat<uint16>().device(device) =
buffer_view.cast<uint16>() * scale;
} else if (data_type_ == DataType::DT_FLOAT) {
float scale = 1. / std::numeric_limits<uint8>::max();
output->flat<float>().device(device) = buffer_view.cast<float>() * scale;
}
}

deepin_reader::Document *deepin_reader::DocumentFactory::getDocument(const int &fileType,
const QString &filePath,
const QString &convertedFileDir,
const QString &password,
QProcess **pprocess,
deepin_reader::Document::Error &error)
{
deepin_reader::Document *document = nullptr;
qDebug() << "需要转换的文档: " << filePath;
if (Dr::PDF == fileType) {
qDebug() << "当前文档类型为: PDF";
document = deepin_reader::PDFDocument::loadDocument(filePath, password, error);
} else if (Dr::DJVU == fileType) {
qDebug() << "当前文档类型为: DJVU";
document = deepin_reader::DjVuDocument::loadDocument(filePath, error);
} else if (Dr::DOCX == fileType) {
qDebug() << "当前文档类型为: DOCX";
if (nullptr == pprocess) {
error = deepin_reader::Document::ConvertFailed;
return nullptr;
}
QString targetDoc = convertedFileDir + "/temp.docx";
QString tmpHtmlFilePath = convertedFileDir + "/word/temp.html";
QString realFilePath = convertedFileDir + "/temp.pdf";
QFile file(filePath);
if (!file.copy(targetDoc)) {
qInfo() << QString("copy %1 failed.").arg(filePath);
error = deepin_reader::Document::ConvertFailed;
return nullptr;
}
QProcess decompressor;
*pprocess = &decompressor;
decompressor.setWorkingDirectory(convertedFileDir);
qDebug() << "正在解压文档..." << targetDoc;
QString unzipCommand = "unzip " + targetDoc;
qDebug() << "执行命令: " << unzipCommand;
decompressor.start(unzipCommand);
if (!decompressor.waitForStarted()) {
qInfo() << "start unzip failed";
error = deepin_reader::Document::ConvertFailed;
*pprocess = nullptr;
return nullptr;
}
if (!decompressor.waitForFinished()) {
qInfo() << "unzip failed";
error = deepin_reader::Document::ConvertFailed;
*pprocess = nullptr;
return nullptr;
}
if (!QDir(convertedFileDir + "/word").exists()) {
qInfo() << "unzip failed! " << (convertedFileDir + "/word") << "is not exists!";
error = deepin_reader::Document::ConvertFailed;
if (!(QProcess::CrashExit == decompressor.exitStatus() && 9 == decompressor.exitCode())) {
*pprocess = nullptr;
}
return nullptr;
}
qDebug() << "文档解压完成";
QProcess converter;
*pprocess = &converter;
converter.setWorkingDirectory(convertedFileDir + "/word");
qDebug() << "正在将docx文档转换成html..." << tmpHtmlFilePath;
QString pandocCommand = "pandoc " +  targetDoc + " -o " + tmpHtmlFilePath;
qDebug() << "执行命令: " << pandocCommand;
converter.start(pandocCommand);
if (!converter.waitForStarted()) {
qInfo() << "start pandoc failed";
error = deepin_reader::Document::ConvertFailed;
*pprocess = nullptr;
return nullptr;
}
if (!converter.waitForFinished()) {
qInfo() << "pandoc failed";
error = deepin_reader::Document::ConvertFailed;
*pprocess = nullptr;
return nullptr;
}
QFile tmpHtmlFile(tmpHtmlFilePath);
if (!tmpHtmlFile.exists()) {
qInfo() <<  "pandoc failed! " << tmpHtmlFilePath << " doesn't exist";
error = deepin_reader::Document::ConvertFailed;
if (!(QProcess::CrashExit == converter.exitStatus() && 9 == converter.exitCode())) {
*pprocess = nullptr;
}
return nullptr;
}
qDebug() << "docx转html完成";
QProcess converter2;
*pprocess = &converter2;
converter2.setWorkingDirectory(convertedFileDir + "/word");
qDebug() << "正在将html转换成pdf..." << realFilePath;
QString htmltopdfCommand = "/usr/lib/deepin-reader/htmltopdf " +  tmpHtmlFilePath + " " + realFilePath;
qDebug() << "执行命令: " << htmltopdfCommand;
converter2.start(htmltopdfCommand);
if (!converter2.waitForStarted()) {
qInfo() << "start htmltopdf failed";
error = deepin_reader::Document::ConvertFailed;
*pprocess = nullptr;
return nullptr;
}
if (!converter2.waitForFinished()) {
qInfo() << "htmltopdf failed";
error = deepin_reader::Document::ConvertFailed;
*pprocess = nullptr;
return nullptr;
}
QFile realFile(realFilePath);
if (!realFile.exists()) {
qInfo() <<  "htmltopdf failed! " << realFilePath << " doesn't exist";
error = deepin_reader::Document::ConvertFailed;
if (!(QProcess::CrashExit == converter.exitStatus() && 9 == converter.exitCode())) {
*pprocess = nullptr;
}
return nullptr;
}
qDebug() << "html转pdf完成";
*pprocess = nullptr;
document = deepin_reader::PDFDocument::loadDocument(realFilePath, password, error);
}
return document;
}

static inline int ldsem_cmpxchg(long *old, long new, struct ld_semaphore *sem)
{
long tmp = *old;
*old = atomic_long_cmpxchg(&sem->count, *old, new);
return *old == tmp;
}

static int check_passwd(unsigned char *passwd, size_t length)
{
struct digest *d = NULL;
unsigned char *passwd1_sum;
unsigned char *passwd2_sum;
int ret = 0;
int hash_len;
if (IS_ENABLED(CONFIG_PASSWD_CRYPTO_PBKDF2)) {
hash_len = PBKDF2_LENGTH;
} else {
d = digest_alloc(PASSWD_SUM);
if (!d) {
pr_err("No such digest: %s\n",
PASSWD_SUM ? PASSWD_SUM : "NULL");
return -ENOENT;
}
hash_len = digest_length(d);
}
passwd1_sum = calloc(hash_len * 2, sizeof(unsigned char));
if (!passwd1_sum)
return -ENOMEM;
passwd2_sum = passwd1_sum + hash_len;
if (is_passwd_env_enable())
ret = read_env_passwd(passwd2_sum, hash_len);
else if (is_passwd_default_enable())
ret = read_default_passwd(passwd2_sum, hash_len);
else
ret = -EINVAL;
if (ret < 0)
goto err;
if (IS_ENABLED(CONFIG_PASSWD_CRYPTO_PBKDF2)) {
char *key = passwd2_sum + PBKDF2_SALT_LEN;
char *salt = passwd2_sum;
int keylen = PBKDF2_LENGTH - PBKDF2_SALT_LEN;
ret = pkcs5_pbkdf2_hmac_sha1(passwd, length, salt,
PBKDF2_SALT_LEN, PBKDF2_COUNT, keylen, passwd1_sum);
if (ret)
goto err;
if (strncmp(passwd1_sum, key, keylen) == 0)
ret = 1;
} else {
ret = digest_digest(d, passwd, length, passwd1_sum);
if (ret)
goto err;
if (strncmp(passwd1_sum, passwd2_sum, hash_len) == 0)
ret = 1;
}
err:
free(passwd1_sum);
digest_free(d);
return ret;
}

