static void
privileged_op (int         privileged_op_socket,
uint32_t    op,
uint32_t    flags,
const char *arg1,
const char *arg2)
{
if (privileged_op_socket != -1)
{
uint32_t buffer[2048];  
PrivSepOp *op_buffer = (PrivSepOp *) buffer;
size_t buffer_size = sizeof (PrivSepOp);
uint32_t arg1_offset = 0, arg2_offset = 0;
if (arg1 != NULL)
{
arg1_offset = buffer_size;
buffer_size += strlen (arg1) + 1;
}
if (arg2 != NULL)
{
arg2_offset = buffer_size;
buffer_size += strlen (arg2) + 1;
}
if (buffer_size >= sizeof (buffer))
die ("privilege separation operation to large");
op_buffer->op = op;
op_buffer->flags = flags;
op_buffer->arg1_offset = arg1_offset;
op_buffer->arg2_offset = arg2_offset;
if (arg1 != NULL)
strcpy ((char *) buffer + arg1_offset, arg1);
if (arg2 != NULL)
strcpy ((char *) buffer + arg2_offset, arg2);
if (write (privileged_op_socket, buffer, buffer_size) != buffer_size)
die ("Can't write to privileged_op_socket");
if (read (privileged_op_socket, buffer, 1) != 1)
die ("Can't read from privileged_op_socket");
return;
}
switch (op)
{
case PRIV_SEP_OP_DONE:
break;
case PRIV_SEP_OP_REMOUNT_RO_NO_RECURSIVE:
if (bind_mount (proc_fd, arg1, arg2, flags) != 0)
die_with_error ("Can't bind mount %s on %s", arg1, arg2);
break;
case PRIV_SEP_OP_BIND_MOUNT:
if (bind_mount (proc_fd, arg1, arg2, BIND_RECURSIVE | flags) != 0)
die_with_error ("Can't bind mount %s on %s", arg1, arg2);
break;
case PRIV_SEP_OP_PROC_MOUNT:
if (mount ("proc", arg1, "proc", MS_MGC_VAL | MS_NOSUID | MS_NOEXEC | MS_NODEV, NULL) != 0)
die_with_error ("Can't mount proc on %s", arg1);
break;
case PRIV_SEP_OP_TMPFS_MOUNT:
{
cleanup_free char *opt = label_mount ("mode=0755", opt_file_label);
if (mount ("tmpfs", arg1, "tmpfs", MS_MGC_VAL | MS_NOSUID | MS_NODEV, opt) != 0)
die_with_error ("Can't mount tmpfs on %s", arg1);
break;
}
case PRIV_SEP_OP_DEVPTS_MOUNT:
if (mount ("devpts", arg1, "devpts", MS_MGC_VAL | MS_NOSUID | MS_NOEXEC,
"newinstance,ptmxmode=0666,mode=620") != 0)
die_with_error ("Can't mount devpts on %s", arg1);
break;
case PRIV_SEP_OP_MQUEUE_MOUNT:
if (mount ("mqueue", arg1, "mqueue", 0, NULL) != 0)
die_with_error ("Can't mount mqueue on %s", arg1);
break;
case PRIV_SEP_OP_SET_HOSTNAME:
if (sethostname (arg1, strlen(arg1)) != 0)
die_with_error ("Can't set hostname to %s", arg1);
break;
default:
die ("Unexpected privileged op %d", op);
}
}

static void
dwg_free_eed(Dwg_Object* obj)
{
unsigned int i;
if (obj->supertype == DWG_SUPERTYPE_OBJECT) {
Dwg_Object_Object* _obj = obj->tio.object;
for (i=0; i < _obj->num_eed; i++) {
if (_obj->eed[i].size)
FREE_IF(_obj->eed[i].raw);
if (_obj->eed[i].data)
FREE_IF(_obj->eed[i].data);
}
FREE_IF(_obj->eed);
}
else if (obj->supertype == DWG_SUPERTYPE_ENTITY) {
Dwg_Object_Entity* _obj = obj->tio.entity;
for (i=0; i < _obj->num_eed; i++) {
if (_obj->eed[i].size)
FREE_IF(_obj->eed[i].raw);
if (_obj->eed[i].data)
FREE_IF(_obj->eed[i].data);
}
FREE_IF(_obj->eed);
}
}

void APar_ExtractDetails(FILE *isofile, uint8_t optional_output) {
char *uint32_buffer = (char *)malloc(sizeof(char) * 5);
Trackage track = {0};
AtomicInfo *mvhdAtom = APar_FindAtom("moov.mvhd", false, VERSIONED_ATOM, 0);
if (mvhdAtom != NULL) {
APar_ExtractMovieDetails(uint32_buffer, isofile, mvhdAtom);
fprintf(stdout,
"Movie duration: %.3lf seconds (%s) - %.2lf* kbp/sec bitrate "
"(*=approximate)\n",
movie_info.seconds,
secsTOtime(movie_info.seconds),
movie_info.simple_bitrate_calc);
if (optional_output & SHOW_DATE_INFO) {
fprintf(stdout,
"  Presentation Creation Date (UTC):     %s\n",
APar_extract_UTC(movie_info.creation_time));
fprintf(stdout,
"  Presentation Modification Date (UTC): %s\n",
APar_extract_UTC(movie_info.modified_time));
}
}
AtomicInfo *iodsAtom = APar_FindAtom("moov.iods", false, VERSIONED_ATOM, 0);
if (iodsAtom != NULL) {
movie_info.contains_iods = true;
APar_Extract_iods_Info(isofile, iodsAtom);
}
if (optional_output & SHOW_TRACK_INFO) {
APar_TrackLevelInfo(&track,
NULL);                                
fprintf(
stdout, "Low-level details. Total tracks: %u\n", track.total_tracks);
fprintf(stdout,
"Trk  Type  Handler                    Kind  Lang  Bytes\n");
if (track.total_tracks > 0) {
while (track.total_tracks > track.track_num) {
track.track_num += 1;
TrackInfo track_info = {0};
APar_ExtractTrackDetails(uint32_buffer, isofile, &track, &track_info);
uint16_t more_whitespace =
purge_extraneous_characters(track_info.track_hdlr_name);
if (strlen(track_info.track_hdlr_name) == 0) {
memcpy(track_info.track_hdlr_name, "[none listed]", 13);
}
fprintf(stdout,
"%u    %s  %s",
track.track_num,
uint32tochar4(track_info.track_type, uint32_buffer),
track_info.track_hdlr_name);
uint16_t handler_len = strlen(track_info.track_hdlr_name);
if (handler_len < 25 + more_whitespace) {
for (uint16_t i = handler_len; i < 25 + more_whitespace; i++) {
fprintf(stdout, " ");
}
}
fprintf(stdout,
"  %s  %s   %" PRIu64,
uint32tochar4(track_info.track_codec, uint32_buffer),
track_info.unpacked_lang,
track_info.sample_aggregate);
if (track_info.encoder_name[0] != 0 && track_info.contains_esds) {
purge_extraneous_characters(track_info.encoder_name);
fprintf(stdout, "   Encoder: %s", track_info.encoder_name);
}
if (track_info.type_of_track & DRM_PROTECTED_TRACK) {
fprintf(stdout,
" (protected %s)",
uint32tochar4(track_info.protected_codec, uint32_buffer));
}
fprintf(stdout, "\n");
if (track_info.type_of_track & VIDEO_TRACK ||
track_info.type_of_track & AUDIO_TRACK) {
APar_Print_TrackDetails(&track_info);
}
if (optional_output & SHOW_DATE_INFO) {
fprintf(stdout,
"       Creation Date (UTC):     %s\n",
APar_extract_UTC(track_info.creation_time));
fprintf(stdout,
"       Modification Date (UTC): %s\n",
APar_extract_UTC(track_info.modified_time));
}
}
}
}
return;
}

static int oidc_handle_session_management_iframe_rp(request_rec *r, oidc_cfg *c,
oidc_session_t *session, const char *client_id,
const char *check_session_iframe) {
oidc_debug(r, "enter");
const char *java_script =
"    <script type=\"text/javascript\">\n"
"      var targetOrigin  = '%s';\n"
"      var message = '%s' + ' ' + '%s';\n"
"   var timerID;\n"
"\n"
"      function checkSession() {\n"
"        console.debug('checkSession: posting ' + message + ' to ' + targetOrigin);\n"
"        var win = window.parent.document.getElementById('%s').contentWindow;\n"
"        win.postMessage( message, targetOrigin);\n"
"      }\n"
"\n"
"      function setTimer() {\n"
"        checkSession();\n"
"        timerID = setInterval('checkSession()', %s);\n"
"      }\n"
"\n"
"      function receiveMessage(e) {\n"
"        console.debug('receiveMessage: ' + e.data + ' from ' + e.origin);\n"
"        if (e.origin !== targetOrigin ) {\n"
"          console.debug('receiveMessage: cross-site scripting attack?');\n"
"          return;\n"
"        }\n"
"        if (e.data != 'unchanged') {\n"
"          clearInterval(timerID);\n"
"          if (e.data == 'changed') {\n"
"     window.location.href = '%s?session=check';\n"
"          } else {\n"
"     window.location.href = '%s?session=logout';\n"
"          }\n"
"        }\n"
"      }\n"
"\n"
"      window.addEventListener('message', receiveMessage, false);\n"
"\n"
"    </script>\n";
char *origin = apr_pstrdup(r->pool, check_session_iframe);
apr_uri_t uri;
apr_uri_parse(r->pool, check_session_iframe, &uri);
char *p = strstr(origin, uri.path);
*p = '\0';
const char *op_iframe_id = "openidc-op";
const char *session_state = oidc_session_get_session_state(r, session);
if (session_state == NULL) {
oidc_warn(r,
"no session_state found in the session; the OP does probably not support session management!?");
return DONE;
}
char *s_poll_interval = NULL;
oidc_util_get_request_parameter(r, "poll", &s_poll_interval);
if (s_poll_interval == NULL)
s_poll_interval = "3000";
const char *redirect_uri = oidc_get_redirect_uri(r, c);
java_script = apr_psprintf(r->pool, java_script, origin, client_id,
session_state, op_iframe_id, s_poll_interval, redirect_uri,
redirect_uri);
return oidc_util_html_send(r, NULL, java_script, "setTimer", NULL, DONE);
}

