FT_FREE( default_values );
FT_FREE( instance_values );
if ( face->goto_table( face, TTAG_glyf, stream, 0 ) &&
face->goto_table( face, TTAG_CFF2, stream, 0 ) &&
!face->goto_table( face, TTAG_CFF, stream, 0 ) )
num_instances = 0;
if ( instance_index > num_instances )
{
if ( face_instance_index >= 0 )
return FT_THROW( Invalid_Argument );
else
num_instances = 0;
}
face->root.style_flags = (FT_Long)num_instances << 16;
}
#endif
face->root.num_faces  = face->ttc_header.count;
face->root.face_index = face_instance_index;
if ( woff2_num_faces )
face->root.num_faces = woff2_num_faces;
return error;
}

static char *decode_text_string(const char *str, size_t str_len)
{
int   idx, is_hex, is_utf16be, ascii_idx;
char *ascii, hex_buf[5] = {0};
is_hex = is_utf16be = idx = ascii_idx = 0;
if (str[0] == '(')
{
ascii = malloc(strlen(str) + 1);
strncpy(ascii, str, strlen(str) + 1);
return ascii;
}
else if (str[0] == '<')
{
is_hex = 1;
++idx;
}
if (is_hex && (str_len > 5) && 
(str[idx] == 'F') && (str[idx+1] == 'E') &&
(str[idx+2] == 'F') && (str[idx+3] == 'F'))
{
is_utf16be = 1;
idx += 4;
}
else
return NULL;
ascii = malloc(str_len);
for ( ; idx<str_len; ++idx)
{
hex_buf[0] = str[idx++];
hex_buf[1] = str[idx++];
hex_buf[2] = str[idx++];
hex_buf[3] = str[idx];
ascii[ascii_idx++] = strtol(hex_buf, NULL, 16);
}
return ascii;
}

static s32 gf_avc_read_sps_bs_internal(GF_BitStream *bs, AVCState *avc, u32 subseq_sps, u32 *vui_flag_pos, u32 nal_hdr)
{
AVC_SPS *sps;
s32 mb_width, mb_height, sps_id = -1;
u32 profile_idc, level_idc, pcomp, i, chroma_format_idc, cl = 0, cr = 0, ct = 0, cb = 0, luma_bd, chroma_bd;
u8 separate_colour_plane_flag = 0;
if (!vui_flag_pos) {
gf_bs_enable_emulation_byte_removal(bs, GF_TRUE);
}
if (!bs) {
return -1;
}
if (!nal_hdr) {
gf_bs_read_int_log(bs, 1, "forbidden_zero_bit");
gf_bs_read_int_log(bs, 2, "nal_ref_idc");
gf_bs_read_int_log(bs, 5, "nal_unit_type");
}
profile_idc = gf_bs_read_int_log(bs, 8, "profile_idc");
pcomp = gf_bs_read_int_log(bs, 8, "profile_compatibility");
if (pcomp & 0x3)
return -1;
level_idc = gf_bs_read_int_log(bs, 8, "level_idc");
sps_id = gf_bs_read_ue_log(bs, "sps_id") + GF_SVC_SSPS_ID_SHIFT * subseq_sps;
if ((sps_id < 0) || (sps_id >= 32)) {
return -1;
}
luma_bd = chroma_bd = 0;
sps = &avc->sps[sps_id];
chroma_format_idc = sps->ChromaArrayType = 1;
sps->state |= subseq_sps ? AVC_SUBSPS_PARSED : AVC_SPS_PARSED;
switch (profile_idc) {
case 100:
case 110:
case 122:
case 244:
case 44:
if (pcomp & 0xE0)
return -1;
case 83:
case 86:
case 118:
case 128:
chroma_format_idc = gf_bs_read_ue_log(bs, "chroma_format_idc");
sps->ChromaArrayType = chroma_format_idc;
if (chroma_format_idc == 3) {
separate_colour_plane_flag = gf_bs_read_int_log(bs, 1, "separate_colour_plane_flag");
if (separate_colour_plane_flag) sps->ChromaArrayType = 0;
}
luma_bd = gf_bs_read_ue_log(bs, "luma_bit_depth");
chroma_bd = gf_bs_read_ue_log(bs, "chroma_bit_depth");
gf_bs_read_int_log(bs, 1, "qpprime_y_zero_transform_bypass_flag");
if (gf_bs_read_int_log(bs, 1, "seq_scaling_matrix_present_flag")) {
u32 k;
for (k = 0; k < 8; k++) {
if (gf_bs_read_int_log_idx(bs, 1, "seq_scaling_list_present_flag", k)) {
u32 z, last = 8, next = 8;
u32 sl = k < 6 ? 16 : 64;
for (z = 0; z < sl; z++) {
if (next) {
s32 delta = gf_bs_read_se(bs);
next = (last + delta + 256) % 256;
}
last = next ? next : last;
}
}
}
}
break;
}
sps->profile_idc = profile_idc;
sps->level_idc = level_idc;
sps->prof_compat = pcomp;
sps->log2_max_frame_num = gf_bs_read_ue_log(bs, "log2_max_frame_num") + 4;
sps->poc_type = gf_bs_read_ue_log(bs, "poc_type");
sps->chroma_format = chroma_format_idc;
sps->luma_bit_depth_m8 = luma_bd;
sps->chroma_bit_depth_m8 = chroma_bd;
if (sps->poc_type == 0) {
sps->log2_max_poc_lsb = gf_bs_read_ue_log(bs, "log2_max_poc_lsb") + 4;
}
else if (sps->poc_type == 1) {
sps->delta_pic_order_always_zero_flag = gf_bs_read_int_log(bs, 1, "delta_pic_order_always_zero_flag");
sps->offset_for_non_ref_pic = gf_bs_read_se_log(bs, "offset_for_non_ref_pic");
sps->offset_for_top_to_bottom_field = gf_bs_read_se_log(bs, "offset_for_top_to_bottom_field");
sps->poc_cycle_length = gf_bs_read_ue_log(bs, "poc_cycle_length");
if (sps->poc_cycle_length > GF_ARRAY_LENGTH(sps->offset_for_ref_frame)) {
sps->poc_cycle_length = 255;
GF_LOG(GF_LOG_ERROR, GF_LOG_CODING, ("[avc-h264] offset_for_ref_frame overflow from poc_cycle_length\n"));
return -1;
}
for (i = 0; i < sps->poc_cycle_length; i++)
sps->offset_for_ref_frame[i] = gf_bs_read_se_log_idx(bs, "offset_for_ref_frame", i);
}
if (sps->poc_type > 2) {
return -1;
}
sps->max_num_ref_frames = gf_bs_read_ue_log(bs, "max_num_ref_frames");
sps->gaps_in_frame_num_value_allowed_flag = gf_bs_read_int_log(bs, 1, "gaps_in_frame_num_value_allowed_flag");
mb_width = gf_bs_read_ue_log(bs, "pic_width_in_mbs_minus1") + 1;
mb_height = gf_bs_read_ue_log(bs, "pic_height_in_map_units_minus1") + 1;
sps->frame_mbs_only_flag = gf_bs_read_int_log(bs, 1, "frame_mbs_only_flag");
sps->width = mb_width * 16;
sps->height = (2 - sps->frame_mbs_only_flag) * mb_height * 16;
if (!sps->frame_mbs_only_flag) sps->mb_adaptive_frame_field_flag = gf_bs_read_int_log(bs, 1, "mb_adaptive_frame_field_flag");
gf_bs_read_int_log(bs, 1, "direct_8x8_inference_flag");
if (gf_bs_read_int_log(bs, 1, "frame_cropping_flag")) {
int CropUnitX, CropUnitY, SubWidthC = -1, SubHeightC = -1;
if (chroma_format_idc == 1) {
SubWidthC = 2; SubHeightC = 2;
}
else if (chroma_format_idc == 2) {
SubWidthC = 2; SubHeightC = 1;
}
else if ((chroma_format_idc == 3) && (separate_colour_plane_flag == 0)) {
SubWidthC = 1; SubHeightC = 1;
}
if (sps->ChromaArrayType == 0) {
assert(SubWidthC == -1);
CropUnitX = 1;
CropUnitY = 2 - sps->frame_mbs_only_flag;
}
else {
CropUnitX = SubWidthC;
CropUnitY = SubHeightC * (2 - sps->frame_mbs_only_flag);
}
cl = gf_bs_read_ue_log(bs, "frame_crop_left_offset");
cr = gf_bs_read_ue_log(bs, "frame_crop_right_offset");
ct = gf_bs_read_ue_log(bs, "frame_crop_top_offset");
cb = gf_bs_read_ue_log(bs, "frame_crop_bottom_offset");
sps->width -= CropUnitX * (cl + cr);
sps->height -= CropUnitY * (ct + cb);
cl *= CropUnitX;
cr *= CropUnitX;
ct *= CropUnitY;
cb *= CropUnitY;
}
sps->crop.left = cl;
sps->crop.right = cr;
sps->crop.top = ct;
sps->crop.bottom = cb;
if (vui_flag_pos) {
*vui_flag_pos = (u32)gf_bs_get_bit_offset(bs);
}
sps->vui_parameters_present_flag = gf_bs_read_int_log(bs, 1, "vui_parameters_present_flag");
if (sps->vui_parameters_present_flag) {
sps->vui.aspect_ratio_info_present_flag = gf_bs_read_int_log(bs, 1, "aspect_ratio_info_present_flag");
if (sps->vui.aspect_ratio_info_present_flag) {
s32 aspect_ratio_idc = gf_bs_read_int_log(bs, 8, "aspect_ratio_idc");
if (aspect_ratio_idc == 255) {
sps->vui.par_num = gf_bs_read_int_log(bs, 16, "aspect_ratio_num");
sps->vui.par_den = gf_bs_read_int_log(bs, 16, "aspect_ratio_den");
}
else if (aspect_ratio_idc < GF_ARRAY_LENGTH(avc_hevc_sar) ) {
sps->vui.par_num = avc_hevc_sar[aspect_ratio_idc].w;
sps->vui.par_den = avc_hevc_sar[aspect_ratio_idc].h;
}
else {
GF_LOG(GF_LOG_WARNING, GF_LOG_CODING, ("[avc-h264] Unknown aspect_ratio_idc: your video may have a wrong aspect ratio. Contact the GPAC team!\n"));
}
}
sps->vui.overscan_info_present_flag = gf_bs_read_int_log(bs, 1, "overscan_info_present_flag");
if (sps->vui.overscan_info_present_flag)
gf_bs_read_int_log(bs, 1, "overscan_appropriate_flag");
sps->vui.video_format = 5;
sps->vui.colour_primaries = 2;
sps->vui.transfer_characteristics = 2;
sps->vui.matrix_coefficients = 2;
sps->vui.video_signal_type_present_flag = gf_bs_read_int_log(bs, 1, "video_signal_type_present_flag");
if (sps->vui.video_signal_type_present_flag) {
sps->vui.video_format = gf_bs_read_int_log(bs, 3, "video_format");
sps->vui.video_full_range_flag = gf_bs_read_int_log(bs, 1, "video_full_range_flag");
sps->vui.colour_description_present_flag = gf_bs_read_int_log(bs, 1, "colour_description_present_flag");
if (sps->vui.colour_description_present_flag) {
sps->vui.colour_primaries = gf_bs_read_int_log(bs, 8, "colour_primaries");
sps->vui.transfer_characteristics = gf_bs_read_int_log(bs, 8, "transfer_characteristics");
sps->vui.matrix_coefficients = gf_bs_read_int_log(bs, 8, "matrix_coefficients");
}
}
if (gf_bs_read_int_log(bs, 1, "chroma_location_info_present_flag")) {
gf_bs_read_ue_log(bs, "chroma_sample_location_type_top_field");
gf_bs_read_ue_log(bs, "chroma_sample_location_type_bottom_field");
}
sps->vui.timing_info_present_flag = gf_bs_read_int_log(bs, 1, "timing_info_present_flag");
if (sps->vui.timing_info_present_flag) {
sps->vui.num_units_in_tick = gf_bs_read_int_log(bs, 32, "num_units_in_tick");
sps->vui.time_scale = gf_bs_read_int_log(bs, 32, "time_scale");
sps->vui.fixed_frame_rate_flag = gf_bs_read_int_log(bs, 1, "fixed_frame_rate_flag");
}
sps->vui.nal_hrd_parameters_present_flag = gf_bs_read_int_log(bs, 1, "nal_hrd_parameters_present_flag");
if (sps->vui.nal_hrd_parameters_present_flag)
avc_parse_hrd_parameters(bs, &sps->vui.hrd);
sps->vui.vcl_hrd_parameters_present_flag = gf_bs_read_int_log(bs, 1, "vcl_hrd_parameters_present_flag");
if (sps->vui.vcl_hrd_parameters_present_flag)
avc_parse_hrd_parameters(bs, &sps->vui.hrd);
if (sps->vui.nal_hrd_parameters_present_flag || sps->vui.vcl_hrd_parameters_present_flag)
sps->vui.low_delay_hrd_flag = gf_bs_read_int_log(bs, 1, "low_delay_hrd_flag");
sps->vui.pic_struct_present_flag = gf_bs_read_int_log(bs, 1, "pic_struct_present_flag");
}
if (subseq_sps) {
if ((profile_idc == 83) || (profile_idc == 86)) {
u8 extended_spatial_scalability_idc;
gf_bs_read_int_log(bs, 1, "inter_layer_deblocking_filter_control_present_flag");
extended_spatial_scalability_idc = gf_bs_read_int_log(bs, 2, "extended_spatial_scalability_idc");
if (sps->ChromaArrayType == 1 || sps->ChromaArrayType == 2) {
gf_bs_read_int_log(bs, 1, "chroma_phase_x_plus1_flag");
}
if (sps->ChromaArrayType == 1) {
gf_bs_read_int_log(bs, 2, "chroma_phase_y_plus1");
}
if (extended_spatial_scalability_idc == 1) {
if (sps->ChromaArrayType > 0) {
gf_bs_read_int_log(bs, 1, "seq_ref_layer_chroma_phase_x_plus1_flag");
gf_bs_read_int_log(bs, 2, "seq_ref_layer_chroma_phase_y_plus1");
}
gf_bs_read_se_log(bs, "seq_scaled_ref_layer_left_offset");
gf_bs_read_se_log(bs, "seq_scaled_ref_layer_top_offset");
gf_bs_read_se_log(bs, "seq_scaled_ref_layer_right_offset");
gf_bs_read_se_log(bs, "seq_scaled_ref_layer_bottom_offset");
}
if (gf_bs_read_int_log(bs, 1, "seq_tcoeff_level_prediction_flag")) {
gf_bs_read_int_log(bs, 1, "adaptive_tcoeff_level_prediction_flag");
}
gf_bs_read_int_log(bs, 1, "slice_header_restriction_flag");
if (gf_bs_read_int_log(bs, 1, "svc_vui_parameters_present")) {
u32 vui_ext_num_entries_minus1 = gf_bs_read_ue_log(bs, "vui_ext_num_entries_minus1");
for (i = 0; i <= vui_ext_num_entries_minus1; i++) {
u8 vui_ext_nal_hrd_parameters_present_flag, vui_ext_vcl_hrd_parameters_present_flag, vui_ext_timing_info_present_flag;
gf_bs_read_int_log(bs, 3, "vui_ext_dependency_id");
gf_bs_read_int_log(bs, 4, "vui_ext_quality_id");
gf_bs_read_int_log(bs, 3, "vui_ext_temporal_id");
vui_ext_timing_info_present_flag = gf_bs_read_int_log(bs, 1, "vui_ext_timing_info_present_flag");
if (vui_ext_timing_info_present_flag) {
gf_bs_read_int_log(bs, 32, "vui_ext_num_units_in_tick");
gf_bs_read_int_log(bs, 32, "vui_ext_time_scale");
gf_bs_read_int_log(bs, 1, "vui_ext_fixed_frame_rate_flag");
}
vui_ext_nal_hrd_parameters_present_flag = gf_bs_read_int_log(bs, 1, "vui_ext_nal_hrd_parameters_present_flag");
if (vui_ext_nal_hrd_parameters_present_flag) {
}
vui_ext_vcl_hrd_parameters_present_flag = gf_bs_read_int_log(bs, 1, "vui_ext_vcl_hrd_parameters_present_flag");
if (vui_ext_vcl_hrd_parameters_present_flag) {
}
if (vui_ext_nal_hrd_parameters_present_flag || vui_ext_vcl_hrd_parameters_present_flag) {
gf_bs_read_int_log(bs, 1, "vui_ext_low_delay_hrd_flag");
}
gf_bs_read_int_log(bs, 1, "vui_ext_pic_struct_present_flag");
}
}
}
else if ((profile_idc == 118) || (profile_idc == 128)) {
GF_LOG(GF_LOG_INFO, GF_LOG_CODING, ("[avc-h264] MVC parsing not implemented - skipping parsing end of Subset SPS\n"));
return sps_id;
}
if (gf_bs_read_int_log(bs, 1, "additional_extension2")) {
GF_LOG(GF_LOG_WARNING, GF_LOG_CODING, ("[avc-h264] skipping parsing end of Subset SPS (additional_extension2)\n"));
return sps_id;
}
}
return sps_id;
}

static ssize_t fuse_dev_splice_write(struct pipe_inode_info *pipe,
struct file *out, loff_t *ppos,
size_t len, unsigned int flags)
{
unsigned nbuf;
unsigned idx;
struct pipe_buffer *bufs;
struct fuse_copy_state cs;
struct fuse_conn *fc;
size_t rem;
ssize_t ret;
fc = fuse_get_conn(out);
if (!fc)
return -EPERM;
bufs = kmalloc(pipe->buffers * sizeof(struct pipe_buffer), GFP_KERNEL);
if (!bufs)
return -ENOMEM;
pipe_lock(pipe);
nbuf = 0;
rem = 0;
for (idx = 0; idx < pipe->nrbufs && rem < len; idx++)
rem += pipe->bufs[(pipe->curbuf + idx) & (pipe->buffers - 1)].len;
ret = -EINVAL;
if (rem < len) {
pipe_unlock(pipe);
goto out;
}
rem = len;
while (rem) {
struct pipe_buffer *ibuf;
struct pipe_buffer *obuf;
BUG_ON(nbuf >= pipe->buffers);
BUG_ON(!pipe->nrbufs);
ibuf = &pipe->bufs[pipe->curbuf];
obuf = &bufs[nbuf];
if (rem >= ibuf->len) {
*obuf = *ibuf;
ibuf->ops = NULL;
pipe->curbuf = (pipe->curbuf + 1) & (pipe->buffers - 1);
pipe->nrbufs--;
} else {
ibuf->ops->get(pipe, ibuf);
*obuf = *ibuf;
obuf->flags &= ~PIPE_BUF_FLAG_GIFT;
obuf->len = rem;
ibuf->offset += obuf->len;
ibuf->len -= obuf->len;
}
nbuf++;
rem -= obuf->len;
}
pipe_unlock(pipe);
fuse_copy_init(&cs, 0, NULL);
cs.pipebufs = bufs;
cs.nr_segs = nbuf;
cs.pipe = pipe;
if (flags & SPLICE_F_MOVE)
cs.move_pages = 1;
ret = fuse_dev_do_write(fc, &cs, len);
for (idx = 0; idx < nbuf; idx++) {
struct pipe_buffer *buf = &bufs[idx];
buf->ops->release(pipe, buf);
}
out:
kfree(bufs);
return ret;
}

static int ref_pic_list_struct(GetBitContext *gb, RefPicListStruct *rpl)
{
uint32_t delta_poc_st, strp_entry_sign_flag = 0;
rpl->ref_pic_num = get_ue_golomb_long(gb);
if (rpl->ref_pic_num > 0) {
delta_poc_st = get_ue_golomb_long(gb);
rpl->ref_pics[0] = delta_poc_st;
if (rpl->ref_pics[0] != 0) {
strp_entry_sign_flag = get_bits(gb, 1);
rpl->ref_pics[0] *= 1 - (strp_entry_sign_flag << 1);
}
}
for (int i = 1; i < rpl->ref_pic_num; ++i) {
delta_poc_st = get_ue_golomb_long(gb);
if (delta_poc_st != 0)
strp_entry_sign_flag = get_bits(gb, 1);
rpl->ref_pics[i] = rpl->ref_pics[i - 1] + delta_poc_st * (1 - (strp_entry_sign_flag << 1));
}
return 0;
}

void PSIR_FileWriter::ParseFileResources ( XMP_IO* fileRef, XMP_Uns32 length )
{
static const size_t kMinPSIRSize = 12;
this->DeleteExistingInfo();
this->fileParsed = true;
if ( length == 0 ) return;
XMP_Int64 psirOrigin = fileRef->Offset();XMP_Int64 fileEnd = psirOrigin + length;
char nameBuffer [260];
while ( fileRef->Offset() < fileEnd ) {
if ( ! XIO::CheckFileSpace ( fileRef, kMinPSIRSize ) ) break;
XMP_Int64 thisRsrcPos = fileRef->Offset();
XMP_Uns32 type = XIO::ReadUns32_BE ( fileRef );
XMP_Uns16 id   = XIO::ReadUns16_BE ( fileRef );
XMP_Uns8 nameLen = XIO::ReadUns8 ( fileRef );XMP_Uns16 paddedLen = (nameLen + 2) & 0xFFFE;if ( ! XIO::CheckFileSpace ( fileRef, paddedLen+4 ) ) break;
nameBuffer[0] = nameLen;
fileRef->ReadAll ( &nameBuffer[1], paddedLen-1 );
XMP_Uns32 dataLen   = XIO::ReadUns32_BE ( fileRef );
XMP_Uns32 dataTotal = ((dataLen + 1) & 0xFFFFFFFEUL);if ( ! XIO::CheckFileSpace ( fileRef, dataTotal ) ) break;
XMP_Int64 thisDataPos = fileRef->Offset();
XMP_Int64 nextRsrcPos = thisDataPos + dataTotal;
if ( type != k8BIM ) {
XMP_Uns32 fullRsrcLen = (XMP_Uns32) (nextRsrcPos - thisRsrcPos);
this->otherRsrcs.push_back ( OtherRsrcInfo ( (XMP_Uns32)thisRsrcPos, fullRsrcLen ) );
fileRef->Seek ( nextRsrcPos, kXMP_SeekFromStart );
continue;
}
InternalRsrcInfo newInfo ( id, dataLen, kIsFileBased );
InternalRsrcMap::iterator rsrcPos = this->imgRsrcs.find ( id );
if ( rsrcPos == this->imgRsrcs.end() ) {
rsrcPos = this->imgRsrcs.insert ( rsrcPos, InternalRsrcMap::value_type ( id, newInfo ) );
} else if ( (rsrcPos->second.dataLen == 0) && (newInfo.dataLen != 0) ) {
rsrcPos->second = newInfo;
} else {
fileRef->Seek ( nextRsrcPos, kXMP_SeekFromStart );
continue;
}
InternalRsrcInfo* rsrcPtr = &rsrcPos->second;
rsrcPtr->origOffset = (XMP_Uns32)thisDataPos;
if ( nameLen > 0 ) {
rsrcPtr->rsrcName = (XMP_Uns8*) malloc ( paddedLen );
if ( rsrcPtr->rsrcName == 0 ) XMP_Throw ( "Out of memory", kXMPErr_NoMemory );
memcpy ( (void*)rsrcPtr->rsrcName, nameBuffer, paddedLen );}
if ( ! IsMetadataImgRsrc ( id ) ) {
fileRef->Seek ( nextRsrcPos, kXMP_SeekFromStart );
continue;
}
rsrcPtr->dataPtr = malloc ( dataTotal );if ( rsrcPtr->dataPtr == 0 ) XMP_Throw ( "Out of memory", kXMPErr_NoMemory );
fileRef->ReadAll ( (void*)rsrcPtr->dataPtr, dataTotal );
}
#if 0
{
printf ( "\nPSIR_FileWriter::ParseFileResources, count = %d\n", this->imgRsrcs.size() );
InternalRsrcMap::iterator irPos = this->imgRsrcs.begin();
InternalRsrcMap::iterator irEnd = this->imgRsrcs.end();
for ( ; irPos != irEnd; ++irPos ) {
InternalRsrcInfo& thisRsrc = irPos->second;
printf ( "  #%d, dataLen %d, origOffset %d (0x%X)%s\n",
thisRsrc.id, thisRsrc.dataLen, thisRsrc.origOffset, thisRsrc.origOffset,
(thisRsrc.changed ? ", changed" : "") );
}
}
#endif
}

int
vq_getchain(struct virtio_vq_info *vq, uint16_t *pidx,
struct iovec *iov, int n_iov, uint16_t *flags)
{
int i;
u_int ndesc, n_indir;
u_int idx, next;
volatile struct vring_desc *vdir, *vindir, *vp;
struct vmctx *ctx;
struct virtio_base *base;
const char *name;
base = vq->base;
name = base->vops->name;
idx = vq->last_avail;
ndesc = (uint16_t)((u_int)vq->avail->idx - idx);
if (ndesc == 0)
return 0;
if (ndesc > vq->qsize) {
pr_err("%s: ndesc (%u) out of range, driver confused?\r\n",
name, (u_int)ndesc);
return -1;
}
ctx = base->dev->vmctx;
*pidx = next = vq->avail->ring[idx & (vq->qsize - 1)];
vq->last_avail++;
for (i = 0; i < VQ_MAX_DESCRIPTORS; next = vdir->next) {
if (next >= vq->qsize) {
pr_err("%s: descriptor index %u out of range, "
"driver confused?\r\n",
name, next);
return -1;
}
vdir = &vq->desc[next];
if ((vdir->flags & VRING_DESC_F_INDIRECT) == 0) {
_vq_record(i, vdir, ctx, iov, n_iov, flags);
i++;
} else if ((base->device_caps &
(1 << VIRTIO_RING_F_INDIRECT_DESC)) == 0) {
pr_err("%s: descriptor has forbidden INDIRECT flag, "
"driver confused?\r\n",
name);
return -1;
} else {
n_indir = vdir->len / 16;
if ((vdir->len & 0xf) || n_indir == 0) {
pr_err("%s: invalid indir len 0x%x, "
"driver confused?\r\n",
name, (u_int)vdir->len);
return -1;
}
vindir = paddr_guest2host(ctx,
vdir->addr, vdir->len);
next = 0;
for (;;) {
vp = &vindir[next];
if (vp->flags & VRING_DESC_F_INDIRECT) {
pr_err("%s: indirect desc has INDIR flag,"
" driver confused?\r\n",
name);
return -1;
}
_vq_record(i, vp, ctx, iov, n_iov, flags);
if (++i > VQ_MAX_DESCRIPTORS)
goto loopy;
if ((vp->flags & VRING_DESC_F_NEXT) == 0)
break;
next = vp->next;
if (next >= n_indir) {
pr_err("%s: invalid next %u > %u, "
"driver confused?\r\n",
name, (u_int)next, n_indir);
return -1;
}
}
}
if ((vdir->flags & VRING_DESC_F_NEXT) == 0)
return i;
}
loopy:
pr_err("%s: descriptor loop? count > %d - driver confused?\r\n",
name, i);
return -1;
}

static int instance_rmdir(struct inode *inode, struct dentry *dentry)
{
struct dentry *parent;
int ret;
parent = hlist_entry(inode->i_dentry.first, struct dentry, d_alias);
if (WARN_ON_ONCE(parent != trace_instance_dir))
return -ENOENT;
mutex_unlock(&dentry->d_inode->i_mutex);
mutex_unlock(&inode->i_mutex);
ret = instance_delete(dentry->d_iname);
mutex_lock_nested(&inode->i_mutex, I_MUTEX_PARENT);
mutex_lock(&dentry->d_inode->i_mutex);
return ret;
}

static GF_Err shift_chunk_offsets(GF_SampleToChunkBox *stsc, GF_MediaBox *mdia, GF_Box *_stco, u64 offset, Bool force_co64, GF_Box **new_stco)
{
u32 j, k, l, last;
GF_StscEntry *ent;
if (!stsc || !_stco) return GF_ISOM_INVALID_FILE;
for (j=0; j<stsc->nb_entries; j++) {
ent = &stsc->entries[j];
if (!Media_IsSelfContained(mdia, ent->sampleDescriptionIndex))
continue;
if (_stco->type == GF_ISOM_BOX_TYPE_STCO) {
GF_ChunkLargeOffsetBox *new_stco64 = NULL;
GF_ChunkOffsetBox *stco = (GF_ChunkOffsetBox *) _stco;
last = ent->nextChunk ? ent->nextChunk : stco->nb_entries + 1;
for (k = ent->firstChunk; k < last; k++) {
if (new_stco64 || force_co64 || (stco->offsets[k-1] + offset > 0xFFFFFFFF)) {
if (!new_stco64) {
new_stco64 = (GF_ChunkLargeOffsetBox *) gf_isom_box_new(GF_ISOM_BOX_TYPE_CO64);
if (!new_stco64) return GF_OUT_OF_MEM;
new_stco64->nb_entries = stco->nb_entries;
new_stco64->offsets = (u64 *) gf_malloc(new_stco64->nb_entries * sizeof(u64));
if (!new_stco64->offsets) return GF_OUT_OF_MEM;
for (l = 0; l < new_stco64->nb_entries; l++) {
new_stco64->offsets[l] = (u64) stco->offsets[l];
}
}
new_stco64->offsets[k-1] += offset;
} else {
stco->offsets[k-1] += (u32) offset;
}
}
if (new_stco64) {
*new_stco = (GF_Box *) new_stco64;
_stco = (GF_Box *) new_stco64;
new_stco64 = NULL;
}
} else {
GF_ChunkLargeOffsetBox *stco64 = (GF_ChunkLargeOffsetBox *) _stco;
last = ent->nextChunk ? ent->nextChunk : stco64->nb_entries + 1;
for (k = ent->firstChunk; k < last; k++) {
stco64->offsets[k-1] += offset;
}
}
}
return GF_OK;
}

static void nhmldump_send_frame(GF_NHMLDumpCtx *ctx, char *data, u32 data_size, GF_FilterPacket *pck)
{
GF_FilterPacket *dst_pck;
char nhml[1024];
const GF_PropertyValue *p;
u32 size;
u8 *output;
GF_FilterSAPType sap = gf_filter_pck_get_sap(pck);
u64 dts = gf_filter_pck_get_dts(pck);
u64 cts = gf_filter_pck_get_cts(pck);
if (dts==GF_FILTER_NO_TS) dts = cts;
if (cts==GF_FILTER_NO_TS) cts = dts;
ctx->pck_num++;
sprintf(nhml, "<NHNTSample number=\"%d\" DTS=\""LLU"\" dataLength=\"%d\" ", ctx->pck_num, dts, data_size);
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
if (ctx->pckp || (cts != dts) ) {
sprintf(nhml, "CTSOffset=\"%d\" ", (s32) ((s64)cts - (s64)dts));
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
}
if (sap==GF_FILTER_SAP_1) {
sprintf(nhml, "isRAP=\"yes\" ");
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
} else if (sap) {
sprintf(nhml, "SAPType=\"%d\" ", sap);
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
} else if (ctx->pckp) {
sprintf(nhml, "isRAP=\"no\" ");
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
if ((sap==GF_FILTER_SAP_4) || (sap==GF_FILTER_SAP_4_PROL)) {
s32 roll = gf_filter_pck_get_roll_info(pck);
sprintf(nhml, "SAPType=\"4\" %s=\"%d\" ", (sap==GF_FILTER_SAP_4_PROL) ? "prol" : "roll", roll);
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
}
}
if (ctx->pckp) {
u64 bo;
u32 duration, idx;
sprintf(nhml, "mediaOffset=\""LLU"\" ", ctx->mdia_pos);
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
bo = gf_filter_pck_get_byte_offset(pck);
if (bo!=GF_FILTER_NO_BO) {
sprintf(nhml, "sourceByteOffset=\""LLU"\" ", bo);
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
}
duration = gf_filter_pck_get_duration(pck);
if (duration) {
sprintf(nhml, "duration=\"%d\" ", duration);
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
}
idx = gf_filter_pck_get_carousel_version(pck);
if (idx) {
sprintf(nhml, "carouselVersion=\"%d\" ", idx);
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
}
idx = 0;
while (1) {
u32 prop_4cc;
const char *prop_name;
p = gf_filter_pck_enum_properties(pck, &idx, &prop_4cc, &prop_name);
if (!p) break;
if (prop_4cc == GF_PROP_PCK_SUBS) continue;
nhmldump_pck_property(ctx, prop_4cc, prop_name, p);
}
}
if (ctx->chksum) {
if (ctx->chksum==1) {
u32 crc = gf_crc_32(data, data_size);
sprintf(nhml, "crc=\"%08X\" ", crc);
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
} else {
u32 j;
u8 hash[GF_SHA1_DIGEST_SIZE];
gf_sha1_csum(data, data_size, hash);
sprintf(nhml, "sha1=\"");
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
for (j=0; j<20; j++) {
sprintf(nhml, "%02X", hash[j]);
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
}
sprintf(nhml, "\" ");
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
}
}
sprintf(nhml, ">\n");
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
p = gf_filter_pck_get_property(pck, GF_PROP_PCK_SUBS);
if (p) {
u32 offset_in_sample = 0;
Bool first_subs = GF_TRUE;
if (!ctx->bs_r) ctx->bs_r = gf_bs_new(p->value.data.ptr, p->value.data.size, GF_BITSTREAM_READ);
else gf_bs_reassign_buffer(ctx->bs_r, p->value.data.ptr, p->value.data.size);
while (gf_bs_available(ctx->bs_r)) {
u32 s_flags = gf_bs_read_u32(ctx->bs_r);
u32 s_size = gf_bs_read_u32(ctx->bs_r);
u32 s_res = gf_bs_read_u32(ctx->bs_r);
u8 s_prio = gf_bs_read_u8(ctx->bs_r);
u8 s_discard = gf_bs_read_u8(ctx->bs_r);
if (offset_in_sample + s_size > data_size) {
GF_LOG(GF_LOG_ERROR, GF_LOG_MEDIA, ("Wrong subsample info: sample size %d vs subsample offset+size %dn", data_size, offset_in_sample + s_size));
break;
}
if (ctx->is_stpp && ctx->nhmlonly) {
if (first_subs) {
sprintf(nhml, "<NHNTSubSample>\n");
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
gf_bs_write_data(ctx->bs_w, data, s_size);
sprintf(nhml, "</NHNTSubSample>\n");
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
} else {
u32 d_size;
if (ctx->b64_buffer_size<2*s_size) {
ctx->b64_buffer_size = 2 * s_size;
ctx->b64_buffer = gf_realloc(ctx->b64_buffer, ctx->b64_buffer_size);
}
d_size = gf_base64_encode(data + offset_in_sample, s_size, ctx->b64_buffer, ctx->b64_buffer_size);
ctx->b64_buffer[d_size] = 0;
sprintf(nhml, "<NHNTSubSample data=\"data:application/octet-string;base64,");
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
gf_bs_write_data(ctx->bs_w, ctx->b64_buffer, d_size);
sprintf(nhml, "\">\n");
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
}
} else {
sprintf(nhml, "<NHNTSubSample size=\"%d\" flags=\"%d\" reserved=\"%d\" priority=\"%d\" discard=\"%d\" />\n", s_size, s_flags, s_res, s_prio, s_discard);
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
}
first_subs = GF_FALSE;
}
} else if (ctx->is_stpp && ctx->nhmlonly) {
sprintf(nhml, "<NHNTSubSample><![CDATA[\n");
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
gf_bs_write_data(ctx->bs_w, data, data_size);
sprintf(nhml, "]]></NHNTSubSample>\n");
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
}
sprintf(nhml, "</NHNTSample>\n");
gf_bs_write_data(ctx->bs_w, nhml, (u32) strlen(nhml));
gf_bs_get_content_no_truncate(ctx->bs_w, &ctx->nhml_buffer, &size, &ctx->nhml_buffer_size);
if (ctx->filep) {
gf_fwrite(ctx->nhml_buffer, size, ctx->filep);
return;
}
dst_pck = gf_filter_pck_new_alloc(ctx->opid_nhml, size, &output);
if (dst_pck) {
memcpy(output, ctx->nhml_buffer, size);
gf_filter_pck_set_framing(dst_pck, GF_FALSE, GF_FALSE);
gf_filter_pck_send(dst_pck);
}
ctx->mdia_pos += data_size;
if (ctx->opid_mdia) {
dst_pck = gf_filter_pck_new_ref(ctx->opid_mdia, 0, data_size, pck);
if (!dst_pck) return;
gf_filter_pck_merge_properties(pck, dst_pck);
gf_filter_pck_set_framing(dst_pck, ctx->first, GF_FALSE);
gf_filter_pck_send(dst_pck);
}
}

struct lyxml_elem *
lyxml_parse_elem(struct ly_ctx *ctx, const char *data, unsigned int *len, struct lyxml_elem *parent, int options)
{
const char *c = data, *start, *e;
const char *lws;    
int uc;
char *str;
char *prefix = NULL;
unsigned int prefix_len = 0;
struct lyxml_elem *elem = NULL, *child;
struct lyxml_attr *attr;
unsigned int size;
int nons_flag = 0, closed_flag = 0;
*len = 0;
if (*c != '<') {
return NULL;
}
c++;
e = c;
uc = lyxml_getutf8(ctx, e, &size);
if (!is_xmlnamestartchar(uc)) {
LOGVAL(ctx, LYE_XML_INVAL, LY_VLOG_NONE, NULL, "NameStartChar of the element");
return NULL;
}
e += size;
uc = lyxml_getutf8(ctx, e, &size);
while (is_xmlnamechar(uc)) {
if (*e == ':') {
if (prefix_len) {
LOGVAL(ctx, LYE_XML_INVAL, LY_VLOG_NONE, NULL, "element name, multiple colons found");
goto error;
}
start = e + 1;
prefix_len = e - c;
LY_CHECK_ERR_GOTO(prefix, LOGVAL(ctx, LYE_XML_INCHAR, LY_VLOG_NONE, NULL, e), error);
prefix = malloc((prefix_len + 1) * sizeof *prefix);
LY_CHECK_ERR_GOTO(!prefix, LOGMEM(ctx), error);
memcpy(prefix, c, prefix_len);
prefix[prefix_len] = '\0';
c = start;
}
e += size;
uc = lyxml_getutf8(ctx, e, &size);
}
if (!*e) {
LOGVAL(ctx, LYE_EOF, LY_VLOG_NONE, NULL);
free(prefix);
return NULL;
}
elem = calloc(1, sizeof *elem);
LY_CHECK_ERR_RETURN(!elem, free(prefix); LOGMEM(ctx), NULL);
elem->next = NULL;
elem->prev = elem;
if (parent) {
lyxml_add_child(ctx, parent, elem);
}
elem->name = lydict_insert(ctx, c, e - c);
c = e;
process:
ign_xmlws(c);
if (!strncmp("/>", c, 2)) {
c += 2;
elem->content = lydict_insert(ctx, "", 0);
closed_flag = 1;
} else if (*c == '>') {
c++;
lws = NULL;
while (*c) {
if (!strncmp(c, "</", 2)) {
if (lws && !elem->child) {
goto store_content;
}
c += 2;
e = c;
uc = lyxml_getutf8(ctx, e, &size);
if (!is_xmlnamestartchar(uc)) {
LOGVAL(ctx, LYE_XML_INVAL, LY_VLOG_XML, elem, "NameStartChar of the element");
goto error;
}
e += size;
uc = lyxml_getutf8(ctx, e, &size);
while (is_xmlnamechar(uc)) {
if (*e == ':') {
start = e + 1;
if (!prefix || memcmp(prefix, c, e - c)) {
LOGVAL(ctx, LYE_SPEC, LY_VLOG_XML, elem,
"Invalid (different namespaces) opening (%s) and closing element tags.", elem->name);
goto error;
}
c = start;
}
e += size;
uc = lyxml_getutf8(ctx, e, &size);
}
if (!*e) {
LOGVAL(ctx, LYE_EOF, LY_VLOG_NONE, NULL);
goto error;
}
size = e - c;
str = malloc((size + 1) * sizeof *str);
LY_CHECK_ERR_GOTO(!str, LOGMEM(ctx), error);
memcpy(str, c, e - c);
str[e - c] = '\0';
if (size != strlen(elem->name) || memcmp(str, elem->name, size)) {
LOGVAL(ctx, LYE_SPEC, LY_VLOG_XML, elem,
"Invalid (mixed names) opening (%s) and closing (%s) element tags.", elem->name, str);
free(str);
goto error;
}
free(str);
c = e;
ign_xmlws(c);
if (*c != '>') {
LOGVAL(ctx, LYE_SPEC, LY_VLOG_XML, elem, "Data after closing element tag \"%s\".", elem->name);
goto error;
}
c++;
if (!(elem->flags & LYXML_ELEM_MIXED) && !elem->content) {
elem->content = lydict_insert(ctx, "", 0);
}
closed_flag = 1;
break;
} else if (!strncmp(c, "<?", 2)) {
if (lws) {
lws = NULL;
}
c += 2;
if (parse_ignore(ctx, c, "?>", &size)) {
goto error;
}
c += size;
} else if (!strncmp(c, "<!--", 4)) {
if (lws) {
lws = NULL;
}
c += 4;
if (parse_ignore(ctx, c, "-->", &size)) {
goto error;
}
c += size;
} else if (!strncmp(c, "<![CDATA[", 9)) {
goto store_content;
} else if (*c == '<') {
if (lws) {
if (elem->flags & LYXML_ELEM_MIXED) {
goto store_content;
} else {
lws = NULL;
}
}
if (elem->content) {
if (options & LYXML_PARSE_NOMIXEDCONTENT) {
LOGVAL(ctx, LYE_XML_INVAL, LY_VLOG_XML, elem, "XML element with mixed content");
goto error;
}
child = calloc(1, sizeof *child);
LY_CHECK_ERR_GOTO(!child, LOGMEM(ctx), error);
child->content = elem->content;
elem->content = NULL;
lyxml_add_child(ctx, elem, child);
elem->flags |= LYXML_ELEM_MIXED;
}
child = lyxml_parse_elem(ctx, c, &size, elem, options);
if (!child) {
goto error;
}
c += size;      
} else if (is_xmlws(*c)) {
lws = c;
ign_xmlws(c);
} else {
store_content:
if (lws) {
c = lws;
lws = NULL;
}
str = parse_text(ctx, c, '<', &size);
if (!str && !size) {
goto error;
}
elem->content = lydict_insert_zc(ctx, str);
c += size;      
if (elem->child) {
if (options & LYXML_PARSE_NOMIXEDCONTENT) {
LOGVAL(ctx, LYE_XML_INVAL, LY_VLOG_XML, elem, "XML element with mixed content");
goto error;
}
child = calloc(1, sizeof *child);
LY_CHECK_ERR_GOTO(!child, LOGMEM(ctx), error);
child->content = elem->content;
elem->content = NULL;
lyxml_add_child(ctx, elem, child);
elem->flags |= LYXML_ELEM_MIXED;
}
}
}
} else {
attr = parse_attr(ctx, c, &size, elem);
if (!attr) {
goto error;
}
c += size;              
if (attr->type == LYXML_ATTR_NS) {
if ((!prefix || !prefix[0]) && !attr->name) {
if (attr->value) {
elem->ns = (struct lyxml_ns *)attr;
} else {
nons_flag = 1;
}
} else if (prefix && prefix[0] && attr->name && !strncmp(attr->name, prefix, prefix_len + 1)) {
elem->ns = (struct lyxml_ns *)attr;
}
}
goto process;
}
*len = c - data;
if (!closed_flag) {
LOGVAL(ctx, LYE_XML_MISS, LY_VLOG_XML, elem, "closing element tag", elem->name);
goto error;
}
LY_TREE_FOR(elem->attr, attr) {
if (attr->type == LYXML_ATTR_STD_UNRES) {
str = (char *)attr->ns;
attr->ns = lyxml_get_ns(elem, str);
free(str);
attr->type = LYXML_ATTR_STD;
}
}
if (!elem->ns && !nons_flag && parent) {
elem->ns = lyxml_get_ns(parent, prefix_len ? prefix : NULL);
}
free(prefix);
return elem;
error:
lyxml_free(ctx, elem);
free(prefix);
return NULL;
}

static int __dcache_readdir(struct file *file,  struct dir_context *ctx,
u32 shared_gen)
{
struct ceph_file_info *fi = file->private_data;
struct dentry *parent = file->f_dentry;
struct inode *dir = parent->d_inode;
struct list_head *p;
struct dentry *dentry, *last;
struct ceph_dentry_info *di;
int err = 0;
last = fi->dentry;
fi->dentry = NULL;
dout("__dcache_readdir %p v%u at %llu (last %p)\n",
dir, shared_gen, ctx->pos, last);
spin_lock(&parent->d_lock);
if (ctx->pos == 2 || last == NULL ||
fpos_cmp(ctx->pos, ceph_dentry(last)->offset) < 0) {
if (list_empty(&parent->d_subdirs))
goto out_unlock;
p = parent->d_subdirs.prev;
dout(" initial p %p/%p\n", p->prev, p->next);
} else {
p = last->d_u.d_child.prev;
}
more:
dentry = list_entry(p, struct dentry, d_u.d_child);
di = ceph_dentry(dentry);
while (1) {
dout(" p %p/%p %s d_subdirs %p/%p\n", p->prev, p->next,
d_unhashed(dentry) ? "!hashed" : "hashed",
parent->d_subdirs.prev, parent->d_subdirs.next);
if (p == &parent->d_subdirs) {
fi->flags |= CEPH_F_ATEND;
goto out_unlock;
}
spin_lock_nested(&dentry->d_lock, DENTRY_D_LOCK_NESTED);
if (di->lease_shared_gen == shared_gen &&
!d_unhashed(dentry) && dentry->d_inode &&
ceph_snap(dentry->d_inode) != CEPH_SNAPDIR &&
ceph_ino(dentry->d_inode) != CEPH_INO_CEPH &&
fpos_cmp(ctx->pos, di->offset) <= 0)
break;
dout(" skipping %p %.*s at %llu (%llu)%s%s\n", dentry,
dentry->d_name.len, dentry->d_name.name, di->offset,
ctx->pos, d_unhashed(dentry) ? " unhashed" : "",
!dentry->d_inode ? " null" : "");
spin_unlock(&dentry->d_lock);
p = p->prev;
dentry = list_entry(p, struct dentry, d_u.d_child);
di = ceph_dentry(dentry);
}
dget_dlock(dentry);
spin_unlock(&dentry->d_lock);
spin_unlock(&parent->d_lock);
if (!ceph_dir_is_complete(dir)) {
dout(" lost dir complete on %p; falling back to mds\n", dir);
dput(dentry);
err = -EAGAIN;
goto out;
}
dout(" %llu (%llu) dentry %p %.*s %p\n", di->offset, ctx->pos,
dentry, dentry->d_name.len, dentry->d_name.name, dentry->d_inode);
if (!dir_emit(ctx, dentry->d_name.name,
dentry->d_name.len,
ceph_translate_ino(dentry->d_sb, dentry->d_inode->i_ino),
dentry->d_inode->i_mode >> 12)) {
if (last) {
fi->dentry = last;
fi->next_offset = fpos_off(di->offset);
}
dput(dentry);
return 0;
}
ctx->pos = di->offset + 1;
if (last)
dput(last);
last = dentry;
spin_lock(&parent->d_lock);
p = p->prev;
goto more;
out_unlock:
spin_unlock(&parent->d_lock);
out:
if (last)
