static void process_constructors(RKernelCacheObj *obj, struct MACH0_(obj_t) *mach0, RList *ret, ut64 paddr, bool is_first, int mode, const char *prefix) {
const RVector *sections = MACH0_(load_sections) (mach0);
if (!sections) {
return;
}
int type;
struct section_t *section;
r_vector_foreach (sections, section) {
if (section->size == 0) {
continue;
}
if (strstr (section->name, "_mod_fini_func") || strstr (section->name, "_mod_term_func")) {
type  = R_BIN_ENTRY_TYPE_FINI;
} else if (strstr (section->name, "_mod_init_func")) {
type  = is_first ? 0 : R_BIN_ENTRY_TYPE_INIT;
is_first = false;
} else {
continue;
}
ut8 *buf = calloc (section->size, 1);
if (!buf) {
break;
}
if (r_buf_read_at (obj->cache_buf, section->paddr + paddr, buf, section->size) < section->size) {
free (buf);
break;
}
int j;
int count = 0;
for (j = 0; j < section->size; j += 8) {
ut64 addr64 = K_RPTR (buf + j);
ut64 paddr64 = section->paddr + paddr + j;
if (mode == R_K_CONSTRUCTOR_TO_ENTRY) {
RBinAddr *ba = newEntry (paddr64, addr64, type);
r_list_append (ret, ba);
} else if (mode == R_K_CONSTRUCTOR_TO_SYMBOL) {
RBinSymbol *sym = R_NEW0 (RBinSymbol);
if (!sym) {
break;
}
sym->name = r_str_newf ("%s.%s.%d", prefix, (type == R_BIN_ENTRY_TYPE_INIT) ? "init" : "fini", count++);
sym->vaddr = addr64;
sym->paddr = paddr64;
sym->size = 0;
sym->forwarder = "NONE";
sym->bind = "GLOBAL";
sym->type = "FUNC";
r_list_append (ret, sym);
}
}
free (buf);
}
}

static void SFDGetSpiros(FILE *sfd,SplineSet *cur) {
int ch;
spiro_cp cp;
ch = nlgetc(sfd);
ch = nlgetc(sfd);
ch = nlgetc(sfd);
ch = nlgetc(sfd);
ch = nlgetc(sfd);
while ( fscanf(sfd,"%lg %lg %c", &cp.x, &cp.y, &cp.ty )==3 ) {
if ( cur!=NULL ) {
if ( cur->spiro_cnt>=cur->spiro_max )
cur->spiros = realloc(cur->spiros,(cur->spiro_max+=10)*sizeof(spiro_cp));
cur->spiros[cur->spiro_cnt++] = cp;
}
}
if ( cur!=NULL && (cur->spiros[cur->spiro_cnt-1].ty&0x7f)!=SPIRO_END ) {
if ( cur->spiro_cnt>=cur->spiro_max )
cur->spiros = realloc(cur->spiros,(cur->spiro_max+=1)*sizeof(spiro_cp));
memset(&cur->spiros[cur->spiro_cnt],0,sizeof(spiro_cp));
cur->spiros[cur->spiro_cnt++].ty = SPIRO_END;
}
ch = nlgetc(sfd);
if ( ch=='E' ) {
ch = nlgetc(sfd);
ch = nlgetc(sfd);
ch = nlgetc(sfd);
ch = nlgetc(sfd);
ch = nlgetc(sfd);
ch = nlgetc(sfd);
ch = nlgetc(sfd);
} else
ungetc(ch,sfd);
}

static size_t optsize (lua_State *L, char opt, const char **fmt) {
switch (opt) {
case 'B': case 'b': return sizeof(char);
case 'H': case 'h': return sizeof(short);
case 'L': case 'l': return sizeof(long);
case 'T': return sizeof(size_t);
case 'f':  return sizeof(float);
case 'd':  return sizeof(double);
case 'x': return 1;
case 'c': return getnum(fmt, 1);
case 'i': case 'I': {
int sz = getnum(fmt, sizeof(int));
if (sz > MAXINTSIZE)
luaL_error(L, "integral size %d is larger than limit of %d",
sz, MAXINTSIZE);
return sz;
}
default: return 0;  
}
}

int
auth_password(Authctxt *authctxt, const char *password)
{
struct passwd * pw = authctxt->pw;
int result, ok = authctxt->valid;
#if defined(USE_SHADOW) && defined(HAS_SHADOW_EXPIRE)
static int expire_checked = 0;
#endif
#ifndef HAVE_CYGWIN
if (pw->pw_uid == 0 && options.permit_root_login != PERMIT_YES)
ok = 0;
#endif
if (*password == '\0' && options.permit_empty_passwd == 0)
return 0;
#ifdef KRB5
if (options.kerberos_authentication == 1) {
int ret = auth_krb5_password(authctxt, password);
if (ret == 1 || ret == 0)
return ret && ok;
}
#endif
#ifdef HAVE_CYGWIN
{
HANDLE hToken = cygwin_logon_user(pw, password);
if (hToken == INVALID_HANDLE_VALUE)
return 0;
cygwin_set_impersonation_token(hToken);
return ok;
}
#endif
#ifdef USE_PAM
if (options.use_pam)
return (sshpam_auth_passwd(authctxt, password) && ok);
#endif
#if defined(USE_SHADOW) && defined(HAS_SHADOW_EXPIRE)
if (!expire_checked) {
expire_checked = 1;
if (auth_shadow_pwexpired(authctxt))
authctxt->force_pwchange = 1;
}
#endif
result = sys_auth_passwd(authctxt, password);
if (authctxt->force_pwchange)
disable_forwarding();
return (result && ok);
}

string SummarizeArray<bool>(int64_t limit, int64_t num_elts,
const TensorShape& tensor_shape, const char* data,
const bool print_v2) {
auto mutable_data = std::unique_ptr<char[]>(new char[num_elts]);
for (int64_t i = 0; i < num_elts; ++i)
mutable_data.get()[i] = data[i] ? 1 : 0;
bool* array = reinterpret_cast<bool*>(mutable_data.get());
return SummarizeArrayInternal<bool>(limit, num_elts, tensor_shape, array,
print_v2);
}

BGD_DECLARE(void) gdImageFillToBorder (gdImagePtr im, int x, int y, int border, int color)
{
int lastBorder;
int leftLimit, rightLimit;
int i;
int restoreAlphaBleding;
if (border < 0) {
return;
}
leftLimit = (-1);
restoreAlphaBleding = im->alphaBlendingFlag;
im->alphaBlendingFlag = 0;
if (x >= im->sx) {
x = im->sx - 1;
} else if (x < 0) {
x = 0;
}
if (y >= im->sy) {
y = im->sy - 1;
} else if (y < 0) {
y = 0;
}
for (i = x; (i >= 0); i--) {
if (gdImageGetPixel (im, i, y) == border) {
break;
}
gdImageSetPixel (im, i, y, color);
leftLimit = i;
}
if (leftLimit == (-1)) {
im->alphaBlendingFlag = restoreAlphaBleding;
return;
}
rightLimit = x;
for (i = (x + 1); (i < im->sx); i++) {
if (gdImageGetPixel (im, i, y) == border) {
break;
}
gdImageSetPixel (im, i, y, color);
rightLimit = i;
}
if (y > 0) {
lastBorder = 1;
for (i = leftLimit; (i <= rightLimit); i++) {
int c;
c = gdImageGetPixel (im, i, y - 1);
if (lastBorder) {
if ((c != border) && (c != color)) {
gdImageFillToBorder (im, i, y - 1, border, color);
lastBorder = 0;
}
} else if ((c == border) || (c == color)) {
lastBorder = 1;
}
}
}
if (y < ((im->sy) - 1)) {
lastBorder = 1;
for (i = leftLimit; (i <= rightLimit); i++) {
int c = gdImageGetPixel (im, i, y + 1);
if (lastBorder) {
if ((c != border) && (c != color)) {
gdImageFillToBorder (im, i, y + 1, border, color);
lastBorder = 0;
}
} else if ((c == border) || (c == color)) {
lastBorder = 1;
}
}
}
im->alphaBlendingFlag = restoreAlphaBleding;
}

static guint32
parse_wbxml_attribute_list_defined (proto_tree *tree, tvbuff_t *tvb, packet_info *pinfo,
guint32 offset, guint32 str_tbl, guint8 level, guint8 *codepage_attr,
const wbxml_decoding *map)
{
guint32     tvb_len = tvb_reported_length (tvb);
guint32     off     = offset;
guint32     len;
guint       str_len;
guint32     ent;
guint32     idx;
guint8      peek;
guint8      attr_save_known   = 0; 
const char *attr_save_literal = NULL; 
gchar      *str;
DebugLog(("parse_wbxml_attr_defined (level = %u, offset = %u)\n", level, offset));
while (off < tvb_len) {
peek = tvb_get_guint8 (tvb, off);
DebugLog(("ATTR: (top of while) level = %3u, peek = 0x%02X, "
"off = %u, tvb_len = %u\n", level, peek, off, tvb_len));
if ((peek & 0x3F) < 5) switch (peek) { 
case 0x00: 
*codepage_attr = tvb_get_guint8 (tvb, off+1);
proto_tree_add_uint_format(tree, hf_wbxml_switch_page, tvb, off, 2, *codepage_attr,
"      |  Attr | A -->%3d | SWITCH_PAGE (Attr code page)    |",
*codepage_attr);
off += 2;
break;
case 0x01: 
off++;
DebugLog(("ATTR: level = %u, Return: len = %u\n",
level, off - offset));
return (off - offset);
case 0x02: 
ent = tvb_get_guintvar (tvb, off+1, &len, pinfo, &ei_wbxml_oversized_uintvar);
proto_tree_add_uint_format(tree, hf_wbxml_entity, tvb, off, 1+len, ent,
"  %3d |  Attr | A %3d    | ENTITY                          |     %s'&#%u;'",
level, *codepage_attr, Indent (level), ent);
off += 1+len;
break;
case 0x03: 
len = tvb_strsize (tvb, off+1);
str = tvb_format_text (tvb, off+1, len-1);
proto_tree_add_string_format(tree, hf_wbxml_str_i, tvb, off, 1+len, str,
"  %3d |  Attr | A %3d    | STR_I (Inline string)           |     %s\'%s\'",
level, *codepage_attr, Indent (level), str);
off += 1+len;
break;
case 0x04: 
idx = tvb_get_guintvar (tvb, off+1, &len, pinfo, &ei_wbxml_oversized_uintvar);
str_len = tvb_strsize (tvb, str_tbl+idx);
attr_save_known = 0;
attr_save_literal = tvb_format_text (tvb,
str_tbl+idx, str_len-1);
proto_tree_add_string_format(tree, hf_wbxml_literal, tvb, off, 1+len, attr_save_literal,
"  %3d |  Attr | A %3d    | LITERAL (Literal Attribute)     |   %s<%s />",
level, *codepage_attr, Indent (level), attr_save_literal);
off += 1+len;
break;
case 0x40: 
case 0x41: 
case 0x42: 
len = tvb_strsize (tvb, off+1);
str = tvb_format_text (tvb, off+1, len-1);
proto_tree_add_string_format(tree, hf_wbxml_ext_i, tvb, off, 1+len, str,
"  %3d |  Attr | A %3d    | EXT_I_%1x    (Extension Token)    |     %s(%s: \'%s\')",
level, *codepage_attr, peek & 0x0f, Indent (level),
((map != NULL) ? map_token (map->global, 0, peek) : "Inline string extension"), str);
off += 1+len;
break;
case 0x80: 
case 0x81: 
case 0x82: 
idx = tvb_get_guintvar (tvb, off+1, &len, pinfo, &ei_wbxml_oversized_uintvar);
{
char *s;
if (map != NULL) {
if (map->ext_t[peek & 0x03])
s = (map->ext_t[peek & 0x03])(tvb, idx, str_tbl);
else
s = wmem_strdup_printf(wmem_packet_scope(), "EXT_T_%1x (%s)", peek & 0x03,
map_token (map->global, 0, peek));
} else {
s = wmem_strdup_printf(wmem_packet_scope(), "Extension Token, integer value: (%u", idx);
}
proto_tree_add_string_format(tree, hf_wbxml_ext_t, tvb, off, 1+len, s,
"  %3d | Tag   | T %3d    | EXT_T_%1x    (Extension Token)    | %s%s)",
level, *codepage_attr, peek & 0x0f, Indent (level),
s);
}
off += 1+len;
break;
case 0x83: 
idx = tvb_get_guintvar (tvb, off+1, &len, pinfo, &ei_wbxml_oversized_uintvar);
str_len = tvb_strsize (tvb, str_tbl+idx);
str = tvb_format_text (tvb, str_tbl+idx, str_len-1);
proto_tree_add_string_format(tree, hf_wbxml_str_t, tvb, off, 1+len, str,
"  %3d |  Attr | A %3d    | STR_T (Tableref string)         |     %s\'%s\'",
level, *codepage_attr, Indent (level), str);
off += 1+len;
break;
case 0xC0: 
case 0xC1: 
case 0xC2: 
str = (char*)((map != NULL) ? map_token (map->global, 0, peek) : "Single-byte extension");
proto_tree_add_string_format(tree, hf_wbxml_extension_token, tvb, off, 1, str,
"  %3d |  Attr | A %3d    | EXT_%1x      (Extension Token)    |     %s(%s)",
level, *codepage_attr, peek & 0x0f, Indent (level), str);
off++;
break;
case 0xC3: 
if (tvb_get_guint8 (tvb, 0)) { 
if (map != NULL) {
char *tmp_str;
if (attr_save_known) { 
if (map->opaque_binary_attr) {
tmp_str = map->opaque_binary_attr(tvb, off + 1,
attr_save_known, *codepage_attr, &len, pinfo);
} else {
tmp_str = default_opaque_binary_attr(tvb, off + 1,
attr_save_known, *codepage_attr, &len, pinfo);
}
} else { 
if (map->opaque_literal_tag) {
tmp_str = map->opaque_literal_attr(tvb, off + 1,
attr_save_literal, *codepage_attr, &len, pinfo);
} else {
tmp_str = default_opaque_literal_attr(tvb, off + 1,
attr_save_literal, *codepage_attr, &len, pinfo);
}
}
proto_tree_add_bytes_format(tree, hf_wbxml_opaque_data, tvb, off, 1 + len, NULL,
"  %3d |  Attr | A %3d    | OPAQUE (Opaque data)            |       %s%s",
level, *codepage_attr, Indent (level), tmp_str);
off += 1 + len;
} else {
idx = tvb_get_guintvar (tvb, off+1, &len, pinfo, &ei_wbxml_oversized_uintvar);
proto_tree_add_bytes_format(tree, hf_wbxml_opaque_data, tvb, off, 1 + len + idx, NULL,
"  %3d |  Attr | A %3d    | OPAQUE (Opaque data)            |       %s(%u bytes of opaque data)",
level, *codepage_attr, Indent (level), idx);
off += 1+len+idx;
}
} else { 
proto_tree_add_none_format(tree, hf_wbxml_reserved_2, tvb, off, 1,
"  %3d |  Attr | A %3d    | RESERVED_2     (Invalid Token!) | WBXML 1.0 parsing stops here.",
level, *codepage_attr);
off = tvb_len;
DebugLog(("ATTR: level = %u, Return: len = %u\n",
level, off - offset));
return (off - offset);
}
break;
default:
proto_tree_add_none_format(tree, hf_wbxml_invalid_token, tvb, off, 1,
"  %3d |  Attr | A %3d    | %-10s     (Invalid Token!) | WBXML parsing stops here.",
level, *codepage_attr, val_to_str_ext (peek, &vals_wbxml1x_global_tokens_ext, "(unknown 0x%x)"));
off = tvb_len;
break;
} else { 
char* s;
if (peek & 0x80) { 
if (map != NULL) {
s = (char*)map_token (map->attrValue, *codepage_attr, peek);
} else {
s = wmem_strdup_printf(wmem_packet_scope(), "attrValue_0x%02X", peek);
}
proto_tree_add_string_format(tree, hf_wbxml_known_attrvalue, tvb, off, 1, s,
"  %3d |  Attr | A %3d    |   Known attrValue 0x%02X          |       %s%s",
level, *codepage_attr, peek & 0x7f, Indent (level),
s);
off++;
} else { 
if (map != NULL) {
s = (char*)map_token (map->attrStart, *codepage_attr, peek);
} else {
s = wmem_strdup_printf(wmem_packet_scope(), "attrStart_0x%02X", peek);
}
proto_tree_add_string_format(tree, hf_wbxml_known_attrstart, tvb, off, 1, s,
"  %3d |  Attr | A %3d    |   Known attrStart 0x%02X          |   %s%s",
level, *codepage_attr, peek & 0x7f, Indent (level),
s);
off++;
}
}
} 
DebugLog(("ATTR: level = %u, Return: len = %u (end of function body)\n",
level, off - offset));
return (off - offset);
}

static ssize_t map_write(struct file *file, const char __user *buf,
size_t count, loff_t *ppos,
int cap_setid,
struct uid_gid_map *map,
struct uid_gid_map *parent_map)
{
struct seq_file *seq = file->private_data;
struct user_namespace *ns = seq->private;
struct uid_gid_map new_map;
unsigned idx;
struct uid_gid_extent extent;
char *kbuf = NULL, *pos, *next_line;
ssize_t ret;
if ((*ppos != 0) || (count >= PAGE_SIZE))
return -EINVAL;
kbuf = memdup_user_nul(buf, count);
if (IS_ERR(kbuf))
return PTR_ERR(kbuf);
mutex_lock(&userns_state_mutex);
memset(&new_map, 0, sizeof(struct uid_gid_map));
ret = -EPERM;
if (map->nr_extents != 0)
goto out;
if (cap_valid(cap_setid) && !file_ns_capable(file, ns, CAP_SYS_ADMIN))
goto out;
ret = -EINVAL;
pos = kbuf;
for (; pos; pos = next_line) {
next_line = strchr(pos, '\n');
if (next_line) {
*next_line = '\0';
next_line++;
if (*next_line == '\0')
next_line = NULL;
}
pos = skip_spaces(pos);
extent.first = simple_strtoul(pos, &pos, 10);
if (!isspace(*pos))
goto out;
pos = skip_spaces(pos);
extent.lower_first = simple_strtoul(pos, &pos, 10);
if (!isspace(*pos))
goto out;
pos = skip_spaces(pos);
extent.count = simple_strtoul(pos, &pos, 10);
if (*pos && !isspace(*pos))
goto out;
pos = skip_spaces(pos);
if (*pos != '\0')
goto out;
if ((extent.first == (u32) -1) ||
(extent.lower_first == (u32) -1))
goto out;
if ((extent.first + extent.count) <= extent.first)
goto out;
if ((extent.lower_first + extent.count) <=
extent.lower_first)
goto out;
if (mappings_overlap(&new_map, &extent))
goto out;
if ((new_map.nr_extents + 1) == UID_GID_MAP_MAX_EXTENTS &&
(next_line != NULL))
goto out;
ret = insert_extent(&new_map, &extent);
if (ret < 0)
goto out;
ret = -EINVAL;
}
if (new_map.nr_extents == 0)
goto out;
ret = -EPERM;
if (!new_idmap_permitted(file, ns, cap_setid, &new_map))
goto out;
ret = sort_idmaps(&new_map);
if (ret < 0)
goto out;
ret = -EPERM;
for (idx = 0; idx < new_map.nr_extents; idx++) {
struct uid_gid_extent *e;
u32 lower_first;
if (new_map.nr_extents <= UID_GID_MAP_MAX_BASE_EXTENTS)
e = &new_map.extent[idx];
else
e = &new_map.forward[idx];
lower_first = map_id_range_down(parent_map,
e->lower_first,
e->count);
if (lower_first == (u32) -1)
goto out;
e->lower_first = lower_first;
}
if (new_map.nr_extents <= UID_GID_MAP_MAX_BASE_EXTENTS) {
memcpy(map->extent, new_map.extent,
new_map.nr_extents * sizeof(new_map.extent[0]));
} else {
map->forward = new_map.forward;
map->reverse = new_map.reverse;
}
smp_wmb();
map->nr_extents = new_map.nr_extents;
*ppos = count;
ret = count;
out:
if (ret < 0 && new_map.nr_extents > UID_GID_MAP_MAX_BASE_EXTENTS) {
kfree(new_map.forward);
kfree(new_map.reverse);
map->forward = NULL;
map->reverse = NULL;
map->nr_extents = 0;
}
mutex_unlock(&userns_state_mutex);
kfree(kbuf);
return ret;
}

