static void *janus_voicemail_handler(void *data) {
JANUS_LOG(LOG_VERB, "Joining VoiceMail handler thread\n");
janus_voicemail_message *msg = NULL;
int error_code = 0;
char error_cause[512];
json_t *root = NULL;
while(g_atomic_int_get(&initialized) && !g_atomic_int_get(&stopping)) {
msg = g_async_queue_pop(messages);
if(msg == &exit_message)
break;
if(msg->handle == NULL) {
janus_voicemail_message_free(msg);
continue;
}
janus_mutex_lock(&sessions_mutex);
janus_voicemail_session *session = janus_voicemail_lookup_session(msg->handle);
if(!session) {
janus_mutex_unlock(&sessions_mutex);
JANUS_LOG(LOG_ERR, "No session associated with this handle...\n");
janus_voicemail_message_free(msg);
continue;
}
if(g_atomic_int_get(&session->destroyed)) {
janus_mutex_unlock(&sessions_mutex);
janus_voicemail_message_free(msg);
continue;
}
janus_mutex_unlock(&sessions_mutex);
error_code = 0;
root = msg->message;
if(msg->message == NULL) {
JANUS_LOG(LOG_ERR, "No message??\n");
error_code = JANUS_VOICEMAIL_ERROR_NO_MESSAGE;
g_snprintf(error_cause, 512, "%s", "No message??");
goto error;
}
if(!json_is_object(root)) {
JANUS_LOG(LOG_ERR, "JSON error: not an object\n");
error_code = JANUS_VOICEMAIL_ERROR_INVALID_JSON;
g_snprintf(error_cause, 512, "JSON error: not an object");
goto error;
}
JANUS_VALIDATE_JSON_OBJECT(root, request_parameters,
error_code, error_cause, TRUE,
JANUS_VOICEMAIL_ERROR_MISSING_ELEMENT, JANUS_VOICEMAIL_ERROR_INVALID_ELEMENT);
if(error_code != 0)
goto error;
json_t *request = json_object_get(root, "request");
const char *request_text = json_string_value(request);
json_t *event = NULL;
gboolean sdp_update = FALSE;
if(json_object_get(msg->jsep, "update") != NULL)
sdp_update = json_is_true(json_object_get(msg->jsep, "update"));
if(!strcasecmp(request_text, "record")) {
JANUS_LOG(LOG_VERB, "Starting new recording\n");
if(session->file != NULL) {
JANUS_LOG(LOG_ERR, "Already recording (%s)\n", session->filename ? session->filename : "??");
error_code = JANUS_VOICEMAIL_ERROR_ALREADY_RECORDING;
g_snprintf(error_cause, 512, "Already recording");
goto error;
}
session->stream = g_malloc0(sizeof(ogg_stream_state));
if(ogg_stream_init(session->stream, rand()) < 0) {
JANUS_LOG(LOG_ERR, "Couldn't initialize Ogg stream state\n");
error_code = JANUS_VOICEMAIL_ERROR_LIBOGG_ERROR;
g_snprintf(error_cause, 512, "Couldn't initialize Ogg stream state\n");
goto error;
}
session->file = fopen(session->filename, "wb");
if(session->file == NULL) {
JANUS_LOG(LOG_ERR, "Couldn't open output file\n");
error_code = JANUS_VOICEMAIL_ERROR_IO_ERROR;
g_snprintf(error_cause, 512, "Couldn't open output file");
goto error;
}
session->seq = 0;
ogg_packet *op = op_opushead();
ogg_stream_packetin(session->stream, op);
op_free(op);
op = op_opustags();
ogg_stream_packetin(session->stream, op);
op_free(op);
ogg_flush(session);
event = json_object();
json_object_set_new(event, "voicemail", json_string("event"));
json_object_set_new(event, "status", json_string(session->started ? "started" : "starting"));
if(notify_events && gateway->events_is_enabled()) {
json_t *info = json_object();
json_object_set_new(info, "event", json_string("starting"));
gateway->notify_event(&janus_voicemail_plugin, session->handle, info);
}
} else if(!strcasecmp(request_text, "update")) {
JANUS_LOG(LOG_VERB, "Updating existing recording\n");
if(session->stream == NULL || !session->started) {
JANUS_LOG(LOG_ERR, "Invalid state (not recording)\n");
error_code = JANUS_VOICEMAIL_ERROR_INVALID_STATE;
g_snprintf(error_cause, 512, "Invalid state (not recording)");
goto error;
}
sdp_update = TRUE;
event = json_object();
json_object_set_new(event, "voicemail", json_string("event"));
json_object_set_new(event, "status", json_string("updating"));
} else if(!strcasecmp(request_text, "stop")) {
session->started = FALSE;
session->stopping = TRUE;
if(session->file)
fclose(session->file);
session->file = NULL;
if(session->stream)
ogg_stream_destroy(session->stream);
session->stream = NULL;
event = json_object();
json_object_set_new(event, "voicemail", json_string("event"));
json_object_set_new(event, "status", json_string("done"));
char url[1024];
g_snprintf(url, 1024, "%s/janus-voicemail-%"SCNu64".opus", recordings_base, session->recording_id);
json_object_set_new(event, "recording", json_string(url));
if(notify_events && gateway->events_is_enabled()) {
json_t *info = json_object();
json_object_set_new(info, "event", json_string("done"));
gateway->notify_event(&janus_voicemail_plugin, session->handle, info);
}
} else {
JANUS_LOG(LOG_ERR, "Unknown request '%s'\n", request_text);
error_code = JANUS_VOICEMAIL_ERROR_INVALID_REQUEST;
g_snprintf(error_cause, 512, "Unknown request '%s'", request_text);
goto error;
}
JANUS_LOG(LOG_VERB, "Preparing JSON event as a reply\n");
const char *msg_sdp_type = json_string_value(json_object_get(msg->jsep, "type"));
const char *msg_sdp = json_string_value(json_object_get(msg->jsep, "sdp"));
if(!msg_sdp) {
int ret = gateway->push_event(msg->handle, &janus_voicemail_plugin, msg->transaction, event, NULL);
JANUS_LOG(LOG_VERB, "  >> %d (%s)\n", ret, janus_get_api_error(ret));
json_decref(event);
} else {
JANUS_LOG(LOG_VERB, "This is involving a negotiation (%s) as well:\n%s\n", msg_sdp_type, msg_sdp);
const char *type = NULL;
if(!strcasecmp(msg_sdp_type, "offer"))
type = "answer";
if(!strcasecmp(msg_sdp_type, "answer"))
type = "offer";
if(sdp_update) {
JANUS_LOG(LOG_VERB, "Request to update existing connection\n");
session->sdp_version++;
} else {
session->sdp_version = 1;
session->sdp_sessid = janus_get_real_time();
}
char sdp[1024];
int opus_pt = janus_get_codec_pt(msg_sdp, "opus");
JANUS_LOG(LOG_VERB, "Opus payload type is %d\n", opus_pt);
g_snprintf(sdp, 1024, sdp_template,
session->sdp_sessid,
session->sdp_version,
session->recording_id,
opus_pt,
opus_pt);
if(strstr(msg_sdp, "m=video") != NULL) {
g_strlcat(sdp, "m=video 0 RTP/SAVPF 0\r\n", 1024);
}
json_t *jsep = json_pack("{ssss}", "type", type, "sdp", sdp);
g_atomic_int_set(&session->hangingup, 0);
gint64 start = janus_get_monotonic_time();
int res = gateway->push_event(msg->handle, &janus_voicemail_plugin, msg->transaction, event, jsep);
JANUS_LOG(LOG_VERB, "  >> Pushing event: %d (took %"SCNu64" us)\n", res, janus_get_monotonic_time()-start);
json_decref(event);
json_decref(jsep);
if(res != JANUS_OK) {
}
}
janus_voicemail_message_free(msg);
if(session->stopping) {
gateway->end_session(session->handle);
}
continue;
error:
{
json_t *event = json_object();
json_object_set_new(event, "voicemail", json_string("event"));
json_object_set_new(event, "error_code", json_integer(error_code));
json_object_set_new(event, "error", json_string(error_cause));
int ret = gateway->push_event(msg->handle, &janus_voicemail_plugin, msg->transaction, event, NULL);
JANUS_LOG(LOG_VERB, "  >> Pushing event: %d (%s)\n", ret, janus_get_api_error(ret));
json_decref(event);
janus_voicemail_message_free(msg);
}
}
JANUS_LOG(LOG_VERB, "Leaving VoiceMail handler thread\n");
return NULL;
}

static gint32
load_image (const gchar  *filename,
GError      **error)
{
FILE     *fp;
tga_info  info;
guchar    header[18];
guchar    footer[26];
guchar    extension[495];
long      offset;
gint32 image_ID = -1;
fp = g_fopen (filename, "rb");
if (! fp)
{
g_set_error (error, G_FILE_ERROR, g_file_error_from_errno (errno),
_("Could not open '%s' for reading: %s"),
gimp_filename_to_utf8 (filename), g_strerror (errno));
return -1;
}
gimp_progress_init_printf (_("Opening '%s'"),
gimp_filename_to_utf8 (filename));
if (!fseek (fp, -26L, SEEK_END))
{
if (fread (footer, sizeof (footer), 1, fp) != 1)
{
g_message (_("Cannot read footer from '%s'"),
gimp_filename_to_utf8 (filename));
return -1;
}
else if (memcmp (footer + 8, magic, sizeof (magic)) == 0)
{
offset = (footer[0]          +
footer[1] * 256L   +
footer[2] * 65536L +
footer[3] * 16777216L);
if (offset != 0)
{
if (fseek (fp, offset, SEEK_SET) ||
fread (extension, sizeof (extension), 1, fp) != 1)
{
g_message (_("Cannot read extension from '%s'"),
gimp_filename_to_utf8 (filename));
return -1;
}
}
}
}
if (fseek (fp, 0, SEEK_SET) ||
fread (header, sizeof (header), 1, fp) != 1)
{
g_message (_("Cannot read header from '%s'"),
gimp_filename_to_utf8 (filename));
return -1;
}
switch (header[2])
{
case 1:
info.imageType        = TGA_TYPE_MAPPED;
info.imageCompression = TGA_COMP_NONE;
break;
case 2:
info.imageType        = TGA_TYPE_COLOR;
info.imageCompression = TGA_COMP_NONE;
break;
case 3:
info.imageType        = TGA_TYPE_GRAY;
info.imageCompression = TGA_COMP_NONE;
break;
case 9:
info.imageType        = TGA_TYPE_MAPPED;
info.imageCompression = TGA_COMP_RLE;
break;
case 10:
info.imageType        = TGA_TYPE_COLOR;
info.imageCompression = TGA_COMP_RLE;
break;
case 11:
info.imageType        = TGA_TYPE_GRAY;
info.imageCompression = TGA_COMP_RLE;
break;
default:
info.imageType = 0;
}
info.idLength     = header[0];
info.colorMapType = header[1];
info.colorMapIndex  = header[3] + header[4] * 256;
info.colorMapLength = header[5] + header[6] * 256;
info.colorMapSize   = header[7];
info.xOrigin = header[8]  + header[9] * 256;
info.yOrigin = header[10] + header[11] * 256;
info.width   = header[12] + header[13] * 256;
info.height  = header[14] + header[15] * 256;
info.bpp       = header[16];
info.bytes     = (info.bpp + 7) / 8;
info.alphaBits = header[17] & 0x0f; 
info.flipHoriz = (header[17] & 0x10) ? 1 : 0;
info.flipVert  = (header[17] & 0x20) ? 0 : 1;
if (info.alphaBits == info.bpp)
info.alphaBits = 0;
if (info.alphaBits == 0)
{
if (info.imageType == TGA_TYPE_COLOR && info.bpp == 32)
info.alphaBits = 8;
if (info.imageType == TGA_TYPE_GRAY && info.bpp == 16)
info.alphaBits = 8;
}
switch (info.imageType)
{
case TGA_TYPE_MAPPED:
if (info.bpp != 8)
{
g_message ("Unhandled sub-format in '%s' (type = %u, bpp = %u)",
gimp_filename_to_utf8 (filename),
info.imageType, info.bpp);
return -1;
}
break;
case TGA_TYPE_COLOR:
if ((info.bpp != 15 && info.bpp != 16 &&
info.bpp != 24 && info.bpp != 32)      ||
((info.bpp == 15 || info.bpp == 24) &&
info.alphaBits != 0)                   ||
(info.bpp == 16 && info.alphaBits != 1) ||
(info.bpp == 32 && info.alphaBits != 8))
{
g_message ("Unhandled sub-format in '%s' (type = %u, bpp = %u, alpha = %u)",
gimp_filename_to_utf8 (filename),
info.imageType, info.bpp, info.alphaBits);
return -1;
}
break;
case TGA_TYPE_GRAY:
if (info.bpp != 8 &&
(info.alphaBits != 8 || (info.bpp != 16 && info.bpp != 15)))
{
g_message ("Unhandled sub-format in '%s' (type = %u, bpp = %u)",
gimp_filename_to_utf8 (filename),
info.imageType, info.bpp);
return -1;
}
break;
default:
g_message ("Unknown image type %u for '%s'",
info.imageType, gimp_filename_to_utf8 (filename));
return -1;
}
if (info.bytes * 8 != info.bpp && info.bpp != 15)
{
g_message ("Unhandled sub-format in '%s' (type = %u, bpp = %u)",
gimp_filename_to_utf8 (filename),
info.imageType, info.bpp);
return -1;
}
if (info.imageType == TGA_TYPE_MAPPED && info.colorMapType != 1)
{
g_message ("Indexed image has invalid color map type %u",
info.colorMapType);
return -1;
}
else if (info.imageType != TGA_TYPE_MAPPED && info.colorMapType != 0)
{
g_message ("Non-indexed image has invalid color map type %u",
info.colorMapType);
return -1;
}
if (info.idLength && fseek (fp, info.idLength, SEEK_CUR))
{
g_message ("File '%s' is truncated or corrupted",
gimp_filename_to_utf8 (filename));
return -1;
}
image_ID = ReadImage (fp, &info, filename);
fclose (fp);
return image_ID;
}

static inline int object_common2(UNSERIALIZE_PARAMETER, long elements)
{
zval *retval_ptr = NULL;
zval fname;
if (Z_TYPE_PP(rval) != IS_OBJECT) {
return 0;
}
if (!process_nested_data(UNSERIALIZE_PASSTHRU, Z_OBJPROP_PP(rval), elements, 1)) {
return 0;
}
if (Z_OBJCE_PP(rval) != PHP_IC_ENTRY &&
zend_hash_exists(&Z_OBJCE_PP(rval)->function_table, "__wakeup", sizeof("__wakeup"))) {
INIT_PZVAL(&fname);
ZVAL_STRINGL(&fname, "__wakeup", sizeof("__wakeup") - 1, 0);
BG(serialize_lock)++;
call_user_function_ex(CG(function_table), rval, &fname, &retval_ptr, 0, 0, 1, NULL TSRMLS_CC);
BG(serialize_lock)--;
}
if (retval_ptr) {
zval_ptr_dtor(&retval_ptr);
}
if (EG(exception)) {
return 0;
}
return finish_nested_data(UNSERIALIZE_PASSTHRU);
}

