*a = p2m_mem_access_radix_get(p2m, gfn);
mfn = lpae_get_mfn(entry);
mfn = mfn_add(mfn, gfn_x(gfn) & ((1UL << level_orders[level]) - 1));
if ( valid )
*valid = lpae_is_valid(entry);
}
out_unmap:
unmap_domain_page(table);
out:
if ( page_order )
*page_order = level_orders[level];
return mfn;
}

mfn_t p2m_get_entry(struct p2m_domain *p2m, gfn_t gfn,
p2m_type_t *t, p2m_access_t *a,
unsigned int *page_order,
bool *valid)
{
paddr_t addr = gfn_to_gaddr(gfn);
unsigned int level = 0;
lpae_t entry, *table;
int rc;
mfn_t mfn = INVALID_MFN;
p2m_type_t _t;
DECLARE_OFFSETS(offsets, addr);
ASSERT(p2m_is_locked(p2m));
BUILD_BUG_ON(THIRD_MASK != PAGE_MASK);
t = t ?: &_t;
*t = p2m_invalid;
if ( valid )
*valid = false;
if ( gfn_x(gfn) > gfn_x(p2m->max_mapped_gfn) )
{
for ( level = P2M_ROOT_LEVEL; level < 3; level++ )
if ( (gfn_x(gfn) & (level_masks[level] >> PAGE_SHIFT)) >
gfn_x(p2m->max_mapped_gfn) )
break;
goto out;
}
table = p2m_get_root_pointer(p2m, gfn);
BUG_ON(table == NULL);
for ( level = P2M_ROOT_LEVEL; level < 3; level++ )
{
rc = p2m_next_level(p2m, true, level, &table, offsets[level]);
if ( rc == GUEST_TABLE_MAP_FAILED )
goto out_unmap;
else if ( rc != GUEST_TABLE_NORMAL_PAGE )
break;
}
entry = table[offsets[level]];
if ( p2m_is_valid(entry) )
{
*t = entry.p2m.type;
if ( a )
*a = p2m_mem_access_radix_get(p2m, gfn);
mfn = lpae_get_mfn(entry);
mfn = mfn_add(mfn, gfn_x(gfn) & ((1UL << level_orders[level]) - 1));
if ( valid )
*valid = lpae_is_valid(entry);
}
out_unmap:
unmap_domain_page(table);
out:
if ( page_order )
*page_order = level_orders[level];
return mfn;
}

Datum
tsl_subscription_exec(PG_FUNCTION_ARGS)
{
Oid save_userid;
int save_sec_context;
const char *subscription_cmd = PG_ARGISNULL(0) ? NULL : text_to_cstring(PG_GETARG_TEXT_P(0));
int res;
List *parsetree_list;
ListCell *parsetree_item;
if (!subscription_cmd)
PG_RETURN_VOID();
if (!superuser() && !has_rolreplication(GetUserId()))
ereport(ERROR,
(errcode(ERRCODE_INSUFFICIENT_PRIVILEGE),
(errmsg("must be superuser or replication role to use this function"))));
GetUserIdAndSecContext(&save_userid, &save_sec_context);
SetUserIdAndSecContext(BOOTSTRAP_SUPERUSERID, save_sec_context | SECURITY_LOCAL_USERID_CHANGE);
parsetree_list = pg_parse_query(subscription_cmd);
foreach (parsetree_item, parsetree_list)
{
RawStmt *parsetree = lfirst_node(RawStmt, parsetree_item);
switch (nodeTag(parsetree->stmt))
{
case T_CreateSubscriptionStmt:
break;
case T_AlterSubscriptionStmt:
break;
case T_DropSubscriptionStmt:
break;
default:
ereport(ERROR,
(errcode(ERRCODE_FEATURE_NOT_SUPPORTED),
errmsg("this function only accepts SUBSCRIPTION commands")));
}
}
if (SPI_connect() != SPI_OK_CONNECT)
elog(ERROR, "could not connect to SPI");
res = SPI_execute(subscription_cmd, false , 0 );
if (res < 0)
ereport(ERROR,
(errcode(ERRCODE_INTERNAL_ERROR),
(errmsg("error in subscription cmd \"%s\"", subscription_cmd))));
if ((res = SPI_finish()) != SPI_OK_FINISH)
elog(ERROR, "SPI_finish failed: %s", SPI_result_code_string(res));
SetUserIdAndSecContext(save_userid, save_sec_context);
PG_RETURN_VOID();
}

