static void coroutine_fn mirror_wait_on_conflicts(MirrorOp *self,
MirrorBlockJob *s,
uint64_t offset,
uint64_t bytes)
{
uint64_t self_start_chunk = offset / s->granularity;
uint64_t self_end_chunk = DIV_ROUND_UP(offset + bytes, s->granularity);
uint64_t self_nb_chunks = self_end_chunk - self_start_chunk;
while (find_next_bit(s->in_flight_bitmap, self_end_chunk,
self_start_chunk) < self_end_chunk &&
s->ret >= 0)
{
MirrorOp *op;
QTAILQ_FOREACH(op, &s->ops_in_flight, next) {
uint64_t op_start_chunk = op->offset / s->granularity;
uint64_t op_nb_chunks = DIV_ROUND_UP(op->offset + op->bytes,
s->granularity) -
op_start_chunk;
if (op == self) {
continue;
}
if (ranges_overlap(self_start_chunk, self_nb_chunks,
op_start_chunk, op_nb_chunks))
{
if (op->waiting_for_op) {
continue;
}
self->waiting_for_op = op;
qemu_co_queue_wait(&op->waiting_requests, NULL);
self->waiting_for_op = NULL;
break;
}
}
}
}

int
SMB2_negotiate(const unsigned int xid, struct cifs_ses *ses)
{
struct smb_rqst rqst;
struct smb2_negotiate_req *req;
struct smb2_negotiate_rsp *rsp;
struct kvec iov[1];
struct kvec rsp_iov;
int rc = 0;
int resp_buftype;
struct TCP_Server_Info *server = ses->server;
int blob_offset, blob_length;
char *security_blob;
int flags = CIFS_NEG_OP;
unsigned int total_len;
cifs_dbg(FYI, "Negotiate protocol\n");
if (!server) {
WARN(1, "%s: server is NULL!\n", __func__);
return -EIO;
}
rc = smb2_plain_req_init(SMB2_NEGOTIATE, NULL, (void **) &req, &total_len);
if (rc)
return rc;
req->sync_hdr.SessionId = 0;
memset(server->preauth_sha_hash, 0, SMB2_PREAUTH_HASH_SIZE);
memset(ses->preauth_sha_hash, 0, SMB2_PREAUTH_HASH_SIZE);
if (strcmp(ses->server->vals->version_string,
SMB3ANY_VERSION_STRING) == 0) {
req->Dialects[0] = cpu_to_le16(SMB30_PROT_ID);
req->Dialects[1] = cpu_to_le16(SMB302_PROT_ID);
req->DialectCount = cpu_to_le16(2);
total_len += 4;
} else if (strcmp(ses->server->vals->version_string,
SMBDEFAULT_VERSION_STRING) == 0) {
req->Dialects[0] = cpu_to_le16(SMB21_PROT_ID);
req->Dialects[1] = cpu_to_le16(SMB30_PROT_ID);
req->Dialects[2] = cpu_to_le16(SMB302_PROT_ID);
req->Dialects[3] = cpu_to_le16(SMB311_PROT_ID);
req->DialectCount = cpu_to_le16(4);
total_len += 8;
} else {
req->Dialects[0] = cpu_to_le16(ses->server->vals->protocol_id);
req->DialectCount = cpu_to_le16(1);
total_len += 2;
}
if (ses->sign)
req->SecurityMode = cpu_to_le16(SMB2_NEGOTIATE_SIGNING_REQUIRED);
else if (global_secflags & CIFSSEC_MAY_SIGN)
req->SecurityMode = cpu_to_le16(SMB2_NEGOTIATE_SIGNING_ENABLED);
else
req->SecurityMode = 0;
req->Capabilities = cpu_to_le32(ses->server->vals->req_capabilities);
if (ses->server->vals->protocol_id == SMB20_PROT_ID)
memset(req->ClientGUID, 0, SMB2_CLIENT_GUID_SIZE);
else {
memcpy(req->ClientGUID, server->client_guid,
SMB2_CLIENT_GUID_SIZE);
if ((ses->server->vals->protocol_id == SMB311_PROT_ID) ||
(strcmp(ses->server->vals->version_string,
SMBDEFAULT_VERSION_STRING) == 0))
assemble_neg_contexts(req, &total_len);
}
iov[0].iov_base = (char *)req;
iov[0].iov_len = total_len;
memset(&rqst, 0, sizeof(struct smb_rqst));
rqst.rq_iov = iov;
rqst.rq_nvec = 1;
rc = cifs_send_recv(xid, ses, &rqst, &resp_buftype, flags, &rsp_iov);
cifs_small_buf_release(req);
rsp = (struct smb2_negotiate_rsp *)rsp_iov.iov_base;
if (rc == -EOPNOTSUPP) {
cifs_dbg(VFS, "Dialect not supported by server. Consider "
"specifying vers=1.0 or vers=2.0 on mount for accessing"
" older servers\n");
goto neg_exit;
} else if (rc != 0)
goto neg_exit;
if (strcmp(ses->server->vals->version_string,
SMB3ANY_VERSION_STRING) == 0) {
if (rsp->DialectRevision == cpu_to_le16(SMB20_PROT_ID)) {
cifs_dbg(VFS,
"SMB2 dialect returned but not requested\n");
return -EIO;
} else if (rsp->DialectRevision == cpu_to_le16(SMB21_PROT_ID)) {
cifs_dbg(VFS,
"SMB2.1 dialect returned but not requested\n");
return -EIO;
}
} else if (strcmp(ses->server->vals->version_string,
SMBDEFAULT_VERSION_STRING) == 0) {
if (rsp->DialectRevision == cpu_to_le16(SMB20_PROT_ID)) {
cifs_dbg(VFS,
"SMB2 dialect returned but not requested\n");
return -EIO;
} else if (rsp->DialectRevision == cpu_to_le16(SMB21_PROT_ID)) {
ses->server->ops = &smb21_operations;
} else if (rsp->DialectRevision == cpu_to_le16(SMB311_PROT_ID))
ses->server->ops = &smb311_operations;
} else if (le16_to_cpu(rsp->DialectRevision) !=
ses->server->vals->protocol_id) {
cifs_dbg(VFS, "Illegal 0x%x dialect returned: not requested\n",
le16_to_cpu(rsp->DialectRevision));
return -EIO;
}
cifs_dbg(FYI, "mode 0x%x\n", rsp->SecurityMode);
if (rsp->DialectRevision == cpu_to_le16(SMB20_PROT_ID))
cifs_dbg(FYI, "negotiated smb2.0 dialect\n");
else if (rsp->DialectRevision == cpu_to_le16(SMB21_PROT_ID))
cifs_dbg(FYI, "negotiated smb2.1 dialect\n");
else if (rsp->DialectRevision == cpu_to_le16(SMB30_PROT_ID))
cifs_dbg(FYI, "negotiated smb3.0 dialect\n");
else if (rsp->DialectRevision == cpu_to_le16(SMB302_PROT_ID))
cifs_dbg(FYI, "negotiated smb3.02 dialect\n");
else if (rsp->DialectRevision == cpu_to_le16(SMB311_PROT_ID))
cifs_dbg(FYI, "negotiated smb3.1.1 dialect\n");
else {
cifs_dbg(VFS, "Illegal dialect returned by server 0x%x\n",
le16_to_cpu(rsp->DialectRevision));
rc = -EIO;
goto neg_exit;
}
server->dialect = le16_to_cpu(rsp->DialectRevision);
memcpy(server->preauth_sha_hash, ses->preauth_sha_hash,
SMB2_PREAUTH_HASH_SIZE);
server->negflavor = CIFS_NEGFLAVOR_EXTENDED;
server->maxBuf = min_t(unsigned int, le32_to_cpu(rsp->MaxTransactSize),
SMB2_MAX_BUFFER_SIZE);
server->max_read = le32_to_cpu(rsp->MaxReadSize);
server->max_write = le32_to_cpu(rsp->MaxWriteSize);
server->sec_mode = le16_to_cpu(rsp->SecurityMode);
if ((server->sec_mode & SMB2_SEC_MODE_FLAGS_ALL) != server->sec_mode)
cifs_dbg(FYI, "Server returned unexpected security mode 0x%x\n",
server->sec_mode);
server->capabilities = le32_to_cpu(rsp->Capabilities);
server->capabilities |= SMB2_NT_FIND | SMB2_LARGE_FILES;
security_blob = smb2_get_data_area_len(&blob_offset, &blob_length,
(struct smb2_sync_hdr *)rsp);
if (blob_length == 0) {
cifs_dbg(FYI, "missing security blob on negprot\n");
server->sec_ntlmssp = true;
}
rc = cifs_enable_signing(server, ses->sign);
if (rc)
goto neg_exit;
if (blob_length) {
rc = decode_negTokenInit(security_blob, blob_length, server);
if (rc == 1)
rc = 0;
else if (rc == 0)
rc = -EIO;
}
if (rsp->DialectRevision == cpu_to_le16(SMB311_PROT_ID)) {
if (rsp->NegotiateContextCount)
rc = smb311_decode_neg_context(rsp, server,
rsp_iov.iov_len);
else
cifs_dbg(VFS, "Missing expected negotiate contexts\n");
}
neg_exit:
free_rsp_buf(resp_buftype, rsp);
return rc;
}

void CharCodeToUnicode::addMapping(CharCode code, char *uStr, int n,
int offset) {
CharCode oldLen, i;
Unicode u;
char uHex[5];
int j;
if (code >= mapLen) {
oldLen = mapLen;
mapLen = (code + 256) & ~255;
map = (Unicode *)greallocn(map, mapLen, sizeof(Unicode));
for (i = oldLen; i < mapLen; ++i) {
map[i] = 0;
}
}
if (n <= 4) {
if (sscanf(uStr, "%x", &u) != 1) {
error(-1, "Illegal entry in ToUnicode CMap");
return;
}
map[code] = u + offset;
} else {
if (sMapLen >= sMapSize) {
sMapSize = sMapSize + 16;
sMap = (CharCodeToUnicodeString *)
greallocn(sMap, sMapSize, sizeof(CharCodeToUnicodeString));
}
map[code] = 0;
sMap[sMapLen].c = code;
sMap[sMapLen].len = n / 4;
for (j = 0; j < sMap[sMapLen].len && j < maxUnicodeString; ++j) {
strncpy(uHex, uStr + j*4, 4);
uHex[4] = '\0';
if (sscanf(uHex, "%x", &sMap[sMapLen].u[j]) != 1) {
error(-1, "Illegal entry in ToUnicode CMap");
}
}
sMap[sMapLen].u[sMap[sMapLen].len - 1] += offset;
++sMapLen;
}
}

int treeRead(struct READER *reader, struct DATAOBJECT *data) {
int i, j, err, olen, elements, size, x, y, z, b, e, dy, dz, sx, sy, sz, dzy,
szy;
char *input, *output;
uint8_t node_type, node_level;
uint16_t entries_used;
uint32_t size_of_chunk;
uint32_t filter_mask;
uint64_t address_of_left_sibling, address_of_right_sibling, start[4],
child_pointer, key, store;
char buf[4];
UNUSED(node_level);
UNUSED(address_of_right_sibling);
UNUSED(address_of_left_sibling);
UNUSED(key);
if (data->ds.dimensionality > 3) {
log("TREE dimensions > 3");
return MYSOFA_INVALID_FORMAT;
}
if (fread(buf, 1, 4, reader->fhd) != 4 || strncmp(buf, "TREE", 4)) {
log("cannot read signature of TREE\n");
return MYSOFA_INVALID_FORMAT;
} log("%08lX %.4s\n", (uint64_t )ftell(reader->fhd) - 4, buf);
node_type = (uint8_t)fgetc(reader->fhd);
node_level = (uint8_t)fgetc(reader->fhd);
entries_used = (uint16_t)readValue(reader, 2);
if(entries_used>0x1000)
return MYSOFA_UNSUPPORTED_FORMAT;
address_of_left_sibling = readValue(reader,
reader->superblock.size_of_offsets);
address_of_right_sibling = readValue(reader,
reader->superblock.size_of_offsets);
elements = 1;
for (j = 0; j < data->ds.dimensionality; j++)
elements *= data->datalayout_chunk[j];
dy = data->datalayout_chunk[1];
dz = data->datalayout_chunk[2];
sx = data->ds.dimension_size[0];
sy = data->ds.dimension_size[1];
sz = data->ds.dimension_size[2];
dzy = dz * dy;
szy = sz * sy;
size = data->datalayout_chunk[data->ds.dimensionality];
log("elements %d size %d\n",elements,size);
if (!(output = malloc(elements * size))) {
return MYSOFA_NO_MEMORY;
}
for (e = 0; e < entries_used * 2; e++) {
if (node_type == 0) {
key = readValue(reader, reader->superblock.size_of_lengths);
} else {
size_of_chunk = (uint32_t)readValue(reader, 4);
filter_mask = (uint32_t)readValue(reader, 4);
if (filter_mask) {
log("TREE all filters must be enabled\n");
free(output);
return MYSOFA_INVALID_FORMAT;
}
for (j = 0; j < data->ds.dimensionality; j++) {
start[j] = readValue(reader, 8);
log("start %d %lu\n",j,start[j]);
}
if (readValue(reader, 8)) {
break;
}
child_pointer = readValue(reader,
reader->superblock.size_of_offsets);
log(" data at %lX len %u\n", child_pointer, size_of_chunk);
store = ftell(reader->fhd);
if (fseek(reader->fhd, child_pointer, SEEK_SET)<0) {
free(output);
return errno;
}
if (!(input = malloc(size_of_chunk))) {
free(output);
return MYSOFA_NO_MEMORY;
}
if (fread(input, 1, size_of_chunk, reader->fhd) != size_of_chunk) {
free(output);
free(input);
return MYSOFA_INVALID_FORMAT;
}
olen = elements * size;
err = gunzip(size_of_chunk, input, &olen, output);
free(input);
log("   gunzip %d %d %d\n",err, olen, elements*size);
if (err || olen != elements * size) {
free(output);
return MYSOFA_INVALID_FORMAT;
}
switch (data->ds.dimensionality) {
case 1:
for (i = 0; i < olen; i++) {
b = i / elements;
x = i % elements + start[0];
if (x < sx) {
j = x * size + b;
((char*)data->data)[j] = output[i];
}
}
break;
case 2:
for (i = 0; i < olen; i++) {
b = i / elements;
x = i % elements;
y = x % dy + start[1];
x = x / dy + start[0];
if (y < sy && x < sx) {
j = ((x * sy + y) * size) + b;
((char*)data->data)[j] = output[i];
}
}
break;
case 3:
for (i = 0; i < olen; i++) {
b = i / elements;
x = i % elements;
z = x % dz + start[2];
y = (x / dz) % dy + start[1];
x = (x / dzy) + start[0];
if (z < sz && y < sy && x < sx) {
j = (x * szy + y * sz + z) * size + b;
((char*)data->data)[j] = output[i];
}
}
break;
default:
log("invalid dim\n");
return MYSOFA_INTERNAL_ERROR;
}
if(fseek(reader->fhd, store, SEEK_SET)<0) {
free(output);
return errno;
}
}
}
free(output);
if(fseek(reader->fhd, 4, SEEK_CUR)<0) 
return errno;
return MYSOFA_OK;
}

static int compat_copy_entries_to_user(unsigned int total_size,
struct xt_table *table,
void __user *userptr)
{
struct xt_counters *counters;
const struct xt_table_info *private = table->private;
void __user *pos;
unsigned int size;
int ret = 0;
unsigned int i = 0;
struct arpt_entry *iter;
counters = alloc_counters(table);
if (IS_ERR(counters))
return PTR_ERR(counters);
pos = userptr;
size = total_size;
xt_entry_foreach(iter, private->entries, total_size) {
ret = compat_copy_entry_to_user(iter, &pos,
&size, counters, i++);
if (ret != 0)
break;
}
vfree(counters);
return ret;
}

static int
dwg_decode_eed(Bit_Chain * dat, Dwg_Object_Object * obj)
{
BITCODE_BS size;
unsigned int idx = 0;
int error = 0;
Dwg_Data *dwg = obj->dwg;
obj->num_eed = 0;
while ((size = bit_read_BS(dat)))
{
int i;
BITCODE_BS j;
BITCODE_RC code = 0;
long unsigned int end, offset;
long unsigned int sav_byte;
Dwg_Object *_obj = &dwg->object[obj->objid];
LOG_TRACE("EED[%u] size: " FORMAT_BS "\n", idx, size);
if (size > _obj->size)
{
LOG_ERROR("Invalid EED size " FORMAT_BS " > %u", size, _obj->size)
obj->num_eed = 0;
return DWG_ERR_INVALIDEED; 
}
if (idx) {
obj->eed = (Dwg_Eed*)realloc(obj->eed, (idx+1) * sizeof(Dwg_Eed));
memset(&obj->eed[idx], 0, sizeof(Dwg_Eed));
} else {
obj->eed = (Dwg_Eed*)calloc(1, sizeof(Dwg_Eed));
}
obj->eed[idx].size = size;
error = bit_read_H(dat, &obj->eed[idx].handle);
if (error) {
LOG_ERROR("No EED[%d].handle", idx);
obj->num_eed = 0;
free(obj->eed);
return error;
} else {
end = dat->byte + size;
LOG_TRACE("EED[%u] handle: %d.%d.%lX\n", idx,
obj->eed[idx].handle.code, obj->eed[idx].handle.size,
obj->eed[idx].handle.value);
if (_obj->supertype == DWG_SUPERTYPE_OBJECT &&
_obj->dxfname &&
!strcmp(_obj->dxfname, "MLEADERSTYLE"))
{             Dwg_Object_Ref ref;
ref.obj = NULL;
ref.handleref = obj->eed[idx].handle;
ref.absolute_ref = 0L;
if (dwg_resolve_handleref(&ref, _obj))
{
Dwg_Object_APPID_CONTROL *appid = &dwg->appid_control;
for (j=0; j < appid->num_entries; j++)
{
if ( appid->apps[j]->absolute_ref == ref.absolute_ref )
{
Dwg_Object_MLEADERSTYLE *this = obj->tio.MLEADERSTYLE;
this->is_new_format = 1;
LOG_TRACE("EED found ACAD_MLEADERVER %lu: new format\n",
ref.absolute_ref);
}
}
}
}
}
sav_byte = dat->byte;
obj->eed[idx].raw = bit_read_TF(dat, size);
LOG_INSANE_TF(obj->eed[idx].raw, size);
dat->byte = sav_byte;
while (dat->byte < end)
{
int lenc;
BITCODE_RS lens;
obj->eed[idx].data = (Dwg_Eed_Data*)calloc(size + 8, 1);
obj->eed[idx].data->code = code = bit_read_RC(dat);
LOG_TRACE("EED[%u] code: %d\n", idx, (int)code);
switch (code)
{
case 0:
PRE(R_2007) {
obj->eed[idx].data->u.eed_0.length = lenc = bit_read_RC(dat);
obj->eed[idx].data->u.eed_0.codepage = bit_read_RS_LE(dat);
if (lenc > size-4)
{
LOG_ERROR("Invalid EED string len %d, max %d", lenc, size-4);
dat->byte = end;
break;
#if 0
obj->num_eed = 0;
if (obj->eed[idx].size)
free(obj->eed[idx].raw);
free(obj->eed[idx].data);
free(obj->eed);
dat->byte = end;
return DWG_ERR_VALUEOUTOFBOUNDS; 
#endif
}
bit_read_fixed(dat, obj->eed[idx].data->u.eed_0.string, lenc);
obj->eed[idx].data->u.eed_0.string[lenc] = '\0';
LOG_TRACE("EED[%u] string: \"%s\" len=%d cp=%d\n", idx,
obj->eed[idx].data->u.eed_0.string, (int)lenc,
(int)obj->eed[idx].data->u.eed_0.codepage);
} LATER_VERSIONS {
obj->eed[idx].data->u.eed_0_r2007.length = lens = bit_read_RS(dat);
for (j=0; j < MIN(lens,(size-3)/2); j++)
obj->eed[idx].data->u.eed_0_r2007.string[j] = bit_read_RS_LE(dat);
#ifdef _WIN32
LOG_TRACE("EED[%u] string: \"" FORMAT_TU "\" len=%d\n", idx,
obj->eed[idx].data->u.eed_0_r2007.string, (int)lens);
#endif
}
break;
case 2:
obj->eed[idx].data->u.eed_2.byte = bit_read_RC(dat);
LOG_TRACE("EED[%u] byte: " FORMAT_RC "\n", idx,
obj->eed[idx].data->u.eed_2.byte);
break;
case 3:
case 5:
obj->eed[idx].data->u.eed_3.layer = bit_read_RL(dat);
LOG_TRACE("EED[%u] layer/...: " FORMAT_RL "\n", idx,
obj->eed[idx].data->u.eed_3.layer);
break;
case 4:
obj->eed[idx].data->u.eed_4.length = lenc = bit_read_RC(dat);
for (j=0; j < MIN(lenc,size-2); j++)
obj->eed[idx].data->u.eed_4.data[j] = bit_read_RC(dat);
LOG_TRACE("EED[%u] raw: %s\n", idx, obj->eed[idx].data->u.eed_4.data);
break;
case 10: case 11: case 12: case 13: 
obj->eed[idx].data->u.eed_10.point.x = bit_read_RD(dat);
obj->eed[idx].data->u.eed_10.point.y = bit_read_RD(dat);
obj->eed[idx].data->u.eed_10.point.z = bit_read_RD(dat);
LOG_TRACE("EED[%u] 3dpoint: %f, %f, %f\n", idx,
obj->eed[idx].data->u.eed_10.point.x,
obj->eed[idx].data->u.eed_10.point.y,
obj->eed[idx].data->u.eed_10.point.z);
break;
case 40: case 41: case 42: 
obj->eed[idx].data->u.eed_40.real = bit_read_RD(dat);
LOG_TRACE("EED[%u] real: %f\n", idx,
obj->eed[idx].data->u.eed_40.real);
break;
case 70:
obj->eed[idx].data->u.eed_70.rs = bit_read_RS(dat);
LOG_TRACE("EED[%u] short: " FORMAT_RS "\n", idx,
obj->eed[idx].data->u.eed_70.rs);
break;
case 71:
obj->eed[idx].data->u.eed_71.rl = bit_read_RL(dat);
LOG_TRACE("EED[%u] long: " FORMAT_RL "\n", idx,
obj->eed[idx].data->u.eed_71.rl);
break;
default:
LOG_ERROR("Unknown EED code %d", code);
dat->byte = end;
return DWG_ERR_INVALIDTYPE; 
}
#ifdef DEBUG
if (code == 0 || code == 4)
assert(obj->eed[idx].data->u.eed_0.length <= size-1);
if (code == 10)             assert(size >= 1 + 3*8);
#endif
idx++;
obj->num_eed++;
if (dat->byte < end-1)
{
size = (long)(end - dat->byte + 1);
LOG_INSANE("EED[%u] size remaining: %ld\n", idx, (long)size);
obj->eed = (Dwg_Eed*)realloc(obj->eed, (idx+1) * sizeof(Dwg_Eed));
obj->eed[idx].handle = obj->eed[idx-1].handle;
obj->eed[idx].size = 0;
obj->eed[idx].raw = NULL;
}
}
dat->byte = end;
}
return error;
}

inline typename V::VariantType FBUnserializer<V>::unserializeThing() {
size_t code = nextCode();
switch (code) {
case FB_SERIALIZE_BYTE:
case FB_SERIALIZE_I16:
case FB_SERIALIZE_I32:
case FB_SERIALIZE_I64:
return V::fromInt64(unserializeInt64());
case FB_SERIALIZE_VARCHAR:
case FB_SERIALIZE_STRING:
return V::fromString(unserializeString());
case FB_SERIALIZE_STRUCT:
return V::fromMap(unserializeMap());
case FB_SERIALIZE_NULL:
++p_;
return V::createNull();
case FB_SERIALIZE_DOUBLE:
return V::fromDouble(unserializeDouble());
case FB_SERIALIZE_BOOLEAN:
return V::fromBool(unserializeBoolean());
case FB_SERIALIZE_VECTOR:
return V::fromVector(unserializeVector());
case FB_SERIALIZE_LIST:
return V::fromVector(unserializeList());
case FB_SERIALIZE_SET:
return V::fromSet(unserializeSet());
default:
throw UnserializeError("Invalid code: " + folly::to<std::string>(code)
+ " at location " + folly::to<std::string>(p_));
}
}

static int kvaser_usb_leaf_set_opt_mode(const struct kvaser_usb_net_priv *priv)
{
struct kvaser_cmd *cmd;
int rc;
cmd = kmalloc(sizeof(*cmd), GFP_KERNEL);
if (!cmd)
return -ENOMEM;
cmd->id = CMD_SET_CTRL_MODE;
cmd->len = CMD_HEADER_LEN + sizeof(struct kvaser_cmd_ctrl_mode);
cmd->u.ctrl_mode.tid = 0xff;
cmd->u.ctrl_mode.channel = priv->channel;
if (priv->can.ctrlmode & CAN_CTRLMODE_LISTENONLY)
cmd->u.ctrl_mode.ctrl_mode = KVASER_CTRL_MODE_SILENT;
else
cmd->u.ctrl_mode.ctrl_mode = KVASER_CTRL_MODE_NORMAL;
rc = kvaser_usb_send_cmd(priv->dev, cmd, cmd->len);
kfree(cmd);
return rc;
}

int ecall_answer(struct ecall *ecall, enum icall_call_type call_type,
bool audio_cbr)
{
int err = 0;
if (!ecall)
return EINVAL;
#ifdef ECALL_CBR_ALWAYS_ON
audio_cbr = true;
#endif
info("ecall(%p): answer on pending econn %p call_type=%d\n", ecall, ecall->econn, call_type);
if (!ecall->econn) {
warning("ecall: answer: econn does not exist!\n");
return ENOENT;
}
if (ECONN_PENDING_INCOMING != econn_current_state(ecall->econn)) {
info("ecall(%p): answer: invalid state (%s)\n", ecall,
econn_state_name(econn_current_state(ecall->econn)));
return EPROTO;
}
if (!ecall->flow) {
warning("ecall: answer: no mediaflow\n");
return EPROTO;
}
ecall->call_type = call_type;
IFLOW_CALL(ecall->flow, set_call_type, call_type);
ecall->audio_cbr = audio_cbr;
IFLOW_CALL(ecall->flow, set_audio_cbr, audio_cbr);
#if 0
if (ecall->props_local) {
const char *vstate_string =
call_type == ICALL_CALL_TYPE_VIDEO ? "true" : "false";
int err2 = econn_props_update(ecall->props_local, "videosend", vstate_string);
if (err2) {
warning("ecall(%p): econn_props_update(videosend)",
" failed (%m)\n", ecall, err2);
}
}
#endif
err = generate_or_gather_answer(ecall, ecall->econn);
if (err) {
warning("ecall: answer: failed to gather_or_answer\n");
goto out;
}
ecall->answered = true;
ecall->audio_setup_time = -1;
ecall->call_estab_time = -1;
ecall->ts_answered = tmr_jiffies();
out:
return err;
}

