break;
}
}

static Jsi_RC jsiInterpDelete(Jsi_Interp* interp, void *unused)
{
SIGASSERT(interp,INTERP);
bool isMainInt = (interp == jsiIntData.mainInterp);
int mainFlag = (isMainInt ? 2 : 1);
if (isMainInt)
DeleteAllInterps();
if (interp->opts.initProc)
(*interp->opts.initProc)(interp, mainFlag);
jsiIntData.delInterp = interp;
if (interp->gsc) jsi_ScopeChainFree(interp, interp->gsc);
if (interp->csc) Jsi_DecrRefCount(interp, interp->csc);
if (interp->ps) jsi_PstateFree(interp->ps);
int i;
for (i=0; i<interp->maxStack; i++) {
if (interp->Stack[i]) Jsi_DecrRefCount(interp, interp->Stack[i]);
if (interp->Obj_this[i]) Jsi_DecrRefCount(interp, interp->Obj_this[i]);
}
if (interp->Stack) {
Jsi_Free(interp->Stack);
Jsi_Free(interp->Obj_this);
}
Jsi_DecrRefCountIF(interp, interp->argv0);
Jsi_DecrRefCountIF(interp, interp->console);
Jsi_DecrRefCountIF(interp, interp->lastSubscriptFail);
Jsi_DecrRefCountIF(interp, interp->nullFuncRet);
Jsi_HashDeleteIF(interp->codeTbl);
if (interp->cmdSpecTbl) Jsi_MapDelete(interp->cmdSpecTbl);
Jsi_HashDeleteIF(interp->funcObjTbl);
Jsi_HashDeleteIF(interp->funcsTbl);
Jsi_HashDeleteIF(interp->fileTbl);
if (interp->profileCnt) {         double endTime = jsi_GetTimestamp();
double coverage = (int)(100.0*interp->coverHit/interp->coverAll);
Jsi_DString dStr;
Jsi_DSInit(&dStr);
Jsi_DSPrintf(&dStr, "PROFILE: TOTAL: time=%.6f, func=%.6f, cmd=%.6f, #funcs=%d, #cmds=%d, cover=%2.1f%%, #values=%d, #objs=%d %s%s\n",
endTime-interp->startTime, interp->funcSelfTime, interp->cmdSelfTime, interp->funcCallCnt, interp->cmdCallCnt,
coverage, interp->dbPtr->valueAllocCnt,  interp->dbPtr->objAllocCnt,
interp->parent?" ::":"", (interp->parent&&interp->name?interp->name:""));
Jsi_Puts(interp, jsi_Stderr, Jsi_DSValue(&dStr), -1);
Jsi_DSFree(&dStr);
}
if (isMainInt)
Jsi_HashDeleteIF(interp->lexkeyTbl);
Jsi_HashDeleteIF(interp->protoTbl);
if (interp->subthread)
jsiIntData.mainInterp->threadCnt--;
if (interp->subthread && interp->strKeyTbl == jsiIntData.mainInterp->strKeyTbl)
jsiIntData.mainInterp->threadShrCnt--;
if (!jsiIntData.mainInterp->threadShrCnt)
#ifdef JSI_USE_MANY_STRKEY
jsiIntData.mainInterp->strKeyTbl->v.tree->opts.lockTreeProc = NULL;
#else
jsiIntData.mainInterp->strKeyTbl->v.hash->opts.lockHashProc = NULL;
#endif
Jsi_HashDeleteIF(interp->thisTbl);
Jsi_HashDeleteIF(interp->varTbl);
Jsi_HashDeleteIF(interp->genValueTbl);
Jsi_HashDeleteIF(interp->genObjTbl);
Jsi_HashDeleteIF(interp->aliasHash);
Jsi_DecrRefCountIF(interp, interp->GetterValue);
Jsi_HashDeleteIF(interp->staticFuncsTbl);
Jsi_HashDeleteIF(interp->breakpointHash);
if (interp->preserveTbl->numEntries!=0)
Jsi_LogBug("Preserves unbalanced");
Jsi_HashDeleteIF(interp->preserveTbl);
if (interp->curDir)
Jsi_Free(interp->curDir);
if (isMainInt) {
jsi_InitFilesys(interp, mainFlag);
}
#ifndef JSI_OMIT_VFS
jsi_InitVfs(interp, 1);
#endif
#ifndef JSI_OMIT_CDATA
jsi_InitCData(interp, mainFlag);
#endif
#if JSI__MYSQL==1
Jsi_InitMySql(interp, mainFlag);
#endif
while (interp->interpStrEvents) {
InterpStrEvent *se = interp->interpStrEvents;
interp->interpStrEvents = se->next;
if (se->acfunc)
Jsi_DecrRefCount(interp, se->acfunc);
if (se->acdata)
Jsi_Free(se->acdata);
Jsi_Free(se);
}
if (interp->Mutex)
Jsi_MutexDelete(interp, interp->Mutex);
if (interp->QMutex) {
Jsi_MutexDelete(interp, interp->QMutex);
Jsi_DSFree(&interp->interpEvalQ);
}
Jsi_DecrRefCountIF(interp, interp->nullFuncArg);
Jsi_DecrRefCountIF(interp, interp->NullValue);
Jsi_OptionsFree(interp, InterpOptions, interp, 0);
if (interp->Function_prototype_prototype) {
if (interp->Function_prototype_prototype->refCnt>1)
Jsi_DecrRefCountIF(interp, interp->Function_prototype_prototype);
Jsi_DecrRefCountIF(interp, interp->Function_prototype_prototype);
}
Jsi_DecrRefCountIF(interp, interp->Object_prototype);
Jsi_HashDeleteIF(interp->regexpTbl);
Jsi_HashDeleteIF(interp->userdataTbl);
Jsi_HashDeleteIF(interp->eventTbl);
Jsi_DecrRefCountIF(interp, interp->inopts);
Jsi_DecrRefCountIF(interp, interp->safeWriteDirs);
Jsi_DecrRefCountIF(interp, interp->safeReadDirs);
Jsi_DecrRefCountIF(interp, interp->pkgDirs);
for (i=0; interp->cleanObjs[i]; i++) {
interp->cleanObjs[i]->tree->opts.freeHashProc = 0;
Jsi_ObjFree(interp, interp->cleanObjs[i]);
}
Jsi_HashDeleteIF(interp->bindTbl);
for (i = 0; i <= interp->cur_scope; i++)
jsi_ScopeStrsFree(interp, interp->scopes[i]);
#if JSI__ZVFS==1
Jsi_InitZvfs(interp, mainFlag);
#endif
Jsi_HashDeleteIF(interp->loadTbl);
Jsi_HashDeleteIF(interp->packageHash);
Jsi_HashDeleteIF(interp->assocTbl);
interp->cleanup = 1;
#ifdef JSI_MEM_DEBUG
jsi_DebugDumpValues(interp);
#endif
if (isMainInt || interp->strKeyTbl != jsiIntData.mainInterp->strKeyTbl)
Jsi_MapDelete(interp->strKeyTbl);
if (isMainInt)
jsiIntData.mainInterp = NULL;
_JSI_MEMCLEAR(interp);
jsiIntData.delInterp = NULL;
Jsi_Free(interp);
return JSI_OK;
}

FLAC_API FLAC__bool FLAC__stream_encoder_process(FLAC__StreamEncoder *encoder, const FLAC__int32 * const buffer[], uint32_t samples)
{
uint32_t i, j = 0, channel;
const uint32_t channels = encoder->protected_->channels, blocksize = encoder->protected_->blocksize;
FLAC__ASSERT(0 != encoder);
FLAC__ASSERT(0 != encoder->private_);
FLAC__ASSERT(0 != encoder->protected_);
FLAC__ASSERT(encoder->protected_->state == FLAC__STREAM_ENCODER_OK);
do {
const uint32_t n = flac_min(blocksize+OVERREAD_-encoder->private_->current_sample_number, samples-j);
if(encoder->protected_->verify)
append_to_verify_fifo_(&encoder->private_->verify.input_fifo, buffer, j, channels, n);
for(channel = 0; channel < channels; channel++) {
if (buffer[channel] == NULL) {
return false;
}
memcpy(&encoder->private_->integer_signal[channel][encoder->private_->current_sample_number], &buffer[channel][j], sizeof(buffer[channel][0]) * n);
}
if(encoder->protected_->do_mid_side_stereo) {
FLAC__ASSERT(channels == 2);
for(i = encoder->private_->current_sample_number; i <= blocksize && j < samples; i++, j++) {
encoder->private_->integer_signal_mid_side[1][i] = buffer[0][j] - buffer[1][j];
encoder->private_->integer_signal_mid_side[0][i] = (buffer[0][j] + buffer[1][j]) >> 1; 
}
}
else
j += n;
encoder->private_->current_sample_number += n;
if(encoder->private_->current_sample_number > blocksize) {
FLAC__ASSERT(encoder->private_->current_sample_number == blocksize+OVERREAD_);
FLAC__ASSERT(OVERREAD_ == 1); 
if(!process_frame_(encoder, false, false))
return false;
for(channel = 0; channel < channels; channel++)
encoder->private_->integer_signal[channel][0] = encoder->private_->integer_signal[channel][blocksize];
if(encoder->protected_->do_mid_side_stereo) {
encoder->private_->integer_signal_mid_side[0][0] = encoder->private_->integer_signal_mid_side[0][blocksize];
encoder->private_->integer_signal_mid_side[1][0] = encoder->private_->integer_signal_mid_side[1][blocksize];
}
encoder->private_->current_sample_number = 1;
}
} while(j < samples);
return true;
}

void SparseBitSet::initFromRanges(const uint32_t* ranges, size_t nRanges) {
if (nRanges == 0) {
mMaxVal = 0;
mIndices.reset();
mBitmaps.reset();
return;
}
mMaxVal = ranges[nRanges * 2 - 1];
size_t indexSize = (mMaxVal + kPageMask) >> kLogValuesPerPage;
mIndices.reset(new uint32_t[indexSize]);
uint32_t nPages = calcNumPages(ranges, nRanges);
mBitmaps.reset(new element[nPages << (kLogValuesPerPage - kLogBitsPerEl)]);
memset(mBitmaps.get(), 0, nPages << (kLogValuesPerPage - 3));
mZeroPageIndex = noZeroPage;
uint32_t nonzeroPageEnd = 0;
uint32_t currentPage = 0;
for (size_t i = 0; i < nRanges; i++) {
uint32_t start = ranges[i * 2];
uint32_t end = ranges[i * 2 + 1];
uint32_t startPage = start >> kLogValuesPerPage;
uint32_t endPage = (end - 1) >> kLogValuesPerPage;
if (startPage >= nonzeroPageEnd) {
if (startPage > nonzeroPageEnd) {
if (mZeroPageIndex == noZeroPage) {
mZeroPageIndex = (currentPage++) << (kLogValuesPerPage - kLogBitsPerEl);
}
for (uint32_t j = nonzeroPageEnd; j < startPage; j++) {
mIndices[j] = mZeroPageIndex;
}
}
mIndices[startPage] = (currentPage++) << (kLogValuesPerPage - kLogBitsPerEl);
}
size_t index = ((currentPage - 1) << (kLogValuesPerPage - kLogBitsPerEl)) +
((start & kPageMask) >> kLogBitsPerEl);
size_t nElements = (end - (start & ~kElMask) + kElMask) >> kLogBitsPerEl;
if (nElements == 1) {
mBitmaps[index] |= (kElAllOnes >> (start & kElMask)) &
(kElAllOnes << ((-end) & kElMask));
} else {
mBitmaps[index] |= kElAllOnes >> (start & kElMask);
for (size_t j = 1; j < nElements - 1; j++) {
mBitmaps[index + j] = kElAllOnes;
}
mBitmaps[index + nElements - 1] |= kElAllOnes << ((-end) & kElMask);
}
for (size_t j = startPage + 1; j < endPage + 1; j++) {
mIndices[j] = (currentPage++) << (kLogValuesPerPage - kLogBitsPerEl);
}
nonzeroPageEnd = endPage + 1;
}
}

xfs_failaddr_t
xfs_attr_shortform_verify(
struct xfs_inode*ip)
{
struct xfs_attr_shortform*sfp;
struct xfs_attr_sf_entry*sfep;
struct xfs_attr_sf_entry*next_sfep;
char*endp;
struct xfs_ifork*ifp;
inti;
int64_tsize;
ASSERT(ip->i_afp->if_format == XFS_DINODE_FMT_LOCAL);
ifp = XFS_IFORK_PTR(ip, XFS_ATTR_FORK);
sfp = (struct xfs_attr_shortform *)ifp->if_u1.if_data;
size = ifp->if_bytes;
if (size < sizeof(struct xfs_attr_sf_hdr))
return __this_address;
endp = (char *)sfp + size;
sfep = &sfp->list[0];
for (i = 0; i < sfp->hdr.count; i++) {
if (((char *)sfep + sizeof(*sfep)) >= endp)
return __this_address;
if (sfep->namelen == 0)
return __this_address;
next_sfep = XFS_ATTR_SF_NEXTENTRY(sfep);
if ((char *)next_sfep > endp)
return __this_address;
if (sfep->flags & ~XFS_ATTR_NSP_ONDISK_MASK)
return __this_address;
if (hweight8(sfep->flags & XFS_ATTR_NSP_ONDISK_MASK) > 1)
return __this_address;
sfep = next_sfep;
}
if ((void *)sfep != (void *)endp)
return __this_address;
return NULL;
}

