static int php_zip_extract_file(struct zip * za, char *dest, char *file, int file_len TSRMLS_DC)
{
php_stream_statbuf ssb;
struct zip_file *zf;
struct zip_stat sb;
char b[8192];
int n, len, ret;
php_stream *stream;
char *fullpath;
char *file_dirname_fullpath;
char file_dirname[MAXPATHLEN];
size_t dir_len;
char *file_basename;
size_t file_basename_len;
int is_dir_only = 0;
char *path_cleaned;
size_t path_cleaned_len;
cwd_state new_state;
new_state.cwd = (char*)malloc(1);
new_state.cwd[0] = '\0';
new_state.cwd_length = 0;
virtual_file_ex(&new_state, file, NULL, CWD_EXPAND TSRMLS_CC);
path_cleaned =  php_zip_make_relative_path(new_state.cwd, new_state.cwd_length);
if(!path_cleaned) {
return 0;
}
path_cleaned_len = strlen(path_cleaned);
if (path_cleaned_len >= MAXPATHLEN || zip_stat(za, file, 0, &sb) != 0) {
return 0;
}
if (path_cleaned_len > 1 && IS_SLASH(path_cleaned[path_cleaned_len - 1])) {
len = spprintf(&file_dirname_fullpath, 0, "%s/%s", dest, file);
is_dir_only = 1;
} else {
memcpy(file_dirname, path_cleaned, path_cleaned_len);
dir_len = php_dirname(file_dirname, path_cleaned_len);
if (dir_len <= 0 || (dir_len == 1 && file_dirname[0] == '.')) {
len = spprintf(&file_dirname_fullpath, 0, "%s", dest);
} else {
len = spprintf(&file_dirname_fullpath, 0, "%s/%s", dest, file_dirname);
}
php_basename(path_cleaned, path_cleaned_len, NULL, 0, &file_basename, (size_t *)&file_basename_len TSRMLS_CC);
if (ZIP_OPENBASEDIR_CHECKPATH(file_dirname_fullpath)) {
efree(file_dirname_fullpath);
efree(file_basename);
free(new_state.cwd);
return 0;
}
}
if (php_stream_stat_path_ex(file_dirname_fullpath, PHP_STREAM_URL_STAT_QUIET, &ssb, NULL) < 0) {
#if defined(PHP_WIN32) && (PHP_MAJOR_VERSION == 5 && PHP_MINOR_VERSION == 1)
char *e;
e = file_dirname_fullpath;
while (*e) {
if (*e == '/') {
*e = DEFAULT_SLASH;
}
e++;
}
#endif
ret = php_stream_mkdir(file_dirname_fullpath, 0777,  PHP_STREAM_MKDIR_RECURSIVE|REPORT_ERRORS, NULL);
if (!ret) {
efree(file_dirname_fullpath);
if (!is_dir_only) {
efree(file_basename);
free(new_state.cwd);
}
return 0;
}
}
if (is_dir_only) {
efree(file_dirname_fullpath);
free(new_state.cwd);
return 1;
}
len = spprintf(&fullpath, 0, "%s/%s", file_dirname_fullpath, file_basename);
if (!len) {
efree(file_dirname_fullpath);
efree(file_basename);
free(new_state.cwd);
return 0;
} else if (len > MAXPATHLEN) {
php_error_docref(NULL TSRMLS_CC, E_WARNING, "Full extraction path exceed MAXPATHLEN (%i)", MAXPATHLEN);
efree(file_dirname_fullpath);
efree(file_basename);
free(new_state.cwd);
return 0;
}
if (ZIP_OPENBASEDIR_CHECKPATH(fullpath)) {
efree(fullpath);
efree(file_dirname_fullpath);
efree(file_basename);
free(new_state.cwd);
return 0;
}
#if PHP_API_VERSION < 20100412
stream = php_stream_open_wrapper(fullpath, "w+b", REPORT_ERRORS|ENFORCE_SAFE_MODE, NULL);
#else
stream = php_stream_open_wrapper(fullpath, "w+b", REPORT_ERRORS, NULL);
#endif
if (stream == NULL) {
n = -1;
goto done;
}
zf = zip_fopen(za, file, 0);
if (zf == NULL) {
n = -1;
php_stream_close(stream);
goto done;
}
n = 0;
while ((n=zip_fread(zf, b, sizeof(b))) > 0) {
php_stream_write(stream, b, n);
}
php_stream_close(stream);
n = zip_fclose(zf);
done:
efree(fullpath);
efree(file_basename);
efree(file_dirname_fullpath);
free(new_state.cwd);
if (n<0) {
return 0;
} else {
return 1;
}
}

char *
XkbVModMaskText(XkbDescPtr xkb,
unsigned modMask, unsigned mask, unsigned format)
{
register int i, bit;
int len;
char *mm, *rtrn;
char *str, buf[BUFFER_SIZE];
if ((modMask == 0) && (mask == 0)) {
rtrn = tbGetBuffer(5);
if (format == XkbCFile)
sprintf(rtrn, "0");
else
sprintf(rtrn, "none");
return rtrn;
}
if (modMask != 0)
mm = XkbModMaskText(modMask, format);
else
mm = NULL;
str = buf;
buf[0] = '\0';
if (mask) {
char *tmp;
for (i = 0, bit = 1; i < XkbNumVirtualMods; i++, bit <<= 1) {
if (mask & bit) {
tmp = XkbVModIndexText(xkb, i, format);
len = strlen(tmp) + 1 + (str == buf ? 0 : 1);
if (format == XkbCFile)
len += 4;
if ((str - (buf + len)) <= BUFFER_SIZE) {
if (str != buf) {
if (format == XkbCFile)
*str++ = '|';
else
*str++ = '+';
len--;
}
}
if (format == XkbCFile)
sprintf(str, "%sMask", tmp);
else
strcpy(str, tmp);
str = &str[len - 1];
}
}
str = buf;
}
else
str = NULL;
if (mm)
len = strlen(mm);
else
len = 0;
if (str)
len += strlen(str) + (mm == NULL ? 0 : 1);
if (len >= BUFFER_SIZE)
len = BUFFER_SIZE - 1;
rtrn = tbGetBuffer(len + 1);
rtrn[0] = '\0';
if (mm != NULL) {
i = strlen(mm);
if (i > len)
i = len;
strcpy(rtrn, mm);
}
else {
i = 0;
}
if (str != NULL) {
if (mm != NULL) {
if (format == XkbCFile)
strcat(rtrn, "|");
else
strcat(rtrn, "+");
}
strncat(rtrn, str, len - i);
}
rtrn[len] = '\0';
return rtrn;
}

bool p2m_resolve_translation_fault(struct domain *d, gfn_t gfn)
{
struct p2m_domain *p2m = p2m_get_hostp2m(d);
unsigned int level = 0;
bool resolved = false;
lpae_t entry, *table;
DECLARE_OFFSETS(offsets, gfn_to_gaddr(gfn));
p2m_write_lock(p2m);
if ( gfn_x(gfn) > gfn_x(p2m->max_mapped_gfn) )
goto out;
table = p2m_get_root_pointer(p2m, gfn);
BUG_ON(table == NULL);
for ( level = P2M_ROOT_LEVEL; level <= 3; level++ )
{
int rc;
entry = table[offsets[level]];
if ( level == 3 )
break;
if ( !lpae_is_valid(entry) )
break;
rc = p2m_next_level(p2m, true, level, &table, offsets[level]);
if ( rc == GUEST_TABLE_MAP_FAILED )
goto out_unmap;
else if ( rc != GUEST_TABLE_NORMAL_PAGE )
break;
}
if ( lpae_is_valid(entry) )
{
resolved = true;
goto out_unmap;
}
if ( !p2m_is_valid(entry) )
goto out_unmap;
if ( lpae_is_table(entry, level) )
p2m_invalidate_table(p2m, lpae_get_mfn(entry));
resolved = true;
entry.p2m.valid = 1;
p2m_write_pte(table + offsets[level], entry, p2m->clean_pte);
out_unmap:
unmap_domain_page(table);
out:
p2m_write_unlock(p2m);
return resolved;
}

