dlclose(p);
return true;
}

static gboolean vwr_read_s2_s3_W_rec(vwr_t *vwr, struct wtap_pkthdr *phdr,
Buffer *buf, const guint8 *rec, int rec_size,
int IS_TX, int *err, gchar **err_info)
{
guint8           *data_ptr;
int              bytes_written = 0;                   
register int     i;                                   
const guint8     *s_start_ptr,*s_trail_ptr, *plcp_ptr, *m_ptr; 
guint32          msdu_length, actual_octets;          
guint8           l1p_1,l1p_2, plcp_type, mcs_index, nss;   
guint            flow_seq;
guint64          s_time = LL_ZERO, e_time = LL_ZERO;  
guint64          latency = LL_ZERO;
guint64          start_time, s_sec, s_usec = LL_ZERO; 
guint64          end_time;                            
guint16          info;                                
guint32          errors;
gint8            rssi[] = {0,0,0,0};                  
int              f_tx;                                
guint16          vc_id, ht_len=0;                     
guint32          flow_id, d_time;                     
int              sig_off, pay_off;                    
guint64          sig_ts, tsid;                        
guint16          chanflags = 0;                       
guint16          radioflags = 0;                      
guint64          delta_b;                             
guint16          phyRate;
guint16          vw_flags;                            
guint8           vht_ndp_flag = 0;
if ((guint)rec_size < vwr->MPDU_OFF + vVW510021_W_STATS_TRAILER_LEN) {
*err_info = g_strdup_printf("vwr: Invalid record length %d (must be at least %u)",
rec_size,
vwr->MPDU_OFF + vVW510021_W_STATS_TRAILER_LEN);
*err = WTAP_ERR_BAD_FILE;
return FALSE;
}
s_start_ptr = &(rec[0]);                              
s_trail_ptr = &(rec[rec_size - vVW510021_W_STATS_TRAILER_LEN]);      
l1p_1 = s_start_ptr[vVW510021_W_L1P_1_OFF];
l1p_2 = s_start_ptr[vVW510021_W_L1P_2_OFF];
if (vwr->FPGA_VERSION == S2_W_FPGA)
{
mcs_index = vVW510021_W_S2_MCS_INDEX(l1p_1);
plcp_type = vVW510021_W_S2_PLCP_TYPE(l1p_2);
msdu_length = ((s_start_ptr[vVW510021_W_MSDU_LENGTH_OFF+1] & 0x1f) << 8)
+ s_start_ptr[vVW510021_W_MSDU_LENGTH_OFF];
vc_id = pntoh16(&s_start_ptr[vVW510021_W_VCID_OFF]);
if (IS_TX)
{
rssi[0] = (s_start_ptr[vVW510021_W_RSSI_TXPOWER_OFF] & 0x80) ?
-1 * (s_start_ptr[vVW510021_W_RSSI_TXPOWER_OFF] & 0x7f) :
s_start_ptr[vVW510021_W_RSSI_TXPOWER_OFF] & 0x7f;
}
else
{
rssi[0] = (s_start_ptr[vVW510021_W_RSSI_TXPOWER_OFF] & 0x80) ?
(s_start_ptr[vVW510021_W_RSSI_TXPOWER_OFF]- 256) :
s_start_ptr[vVW510021_W_RSSI_TXPOWER_OFF];
}
rssi[1] = 100;
rssi[2] = 100;
rssi[3] = 100;
nss = 0;
plcp_ptr = &(rec[8]);
}
else
{
radioflags |= FLAGS_FCS;
plcp_type = vVW510021_W_S3_PLCP_TYPE(l1p_2);
if (plcp_type == vVW510021_W_PLCP_VHT_MIXED)
{
mcs_index = vVW510021_W_S3_MCS_INDEX_VHT(l1p_1);
nss = vVW510021_W_S3_NSS_VHT(l1p_1);
}
else
{
mcs_index = vVW510021_W_S3_MCS_INDEX_HT(l1p_1);
nss = 0;
}
if (!IS_TX){
vht_ndp_flag = s_start_ptr[8];
}
msdu_length = pntoh24(&s_start_ptr[9]);
vc_id = pntoh16(&s_start_ptr[14]) & vVW510024_W_VCID_MASK;
for (i = 0; i < 4; i++)
{
if (IS_TX)
{
rssi[i] = (s_start_ptr[4+i] & 0x80) ? -1 * (s_start_ptr[4+i] & 0x7f) : s_start_ptr[4+i] & 0x7f;
}
else
{
rssi[i] = (s_start_ptr[4+i] >= 128) ? (s_start_ptr[4+i] - 256) : s_start_ptr[4+i];
}
}
plcp_ptr = &(rec[16]);
}
actual_octets = msdu_length;
if (actual_octets > rec_size - (vwr->MPDU_OFF + vVW510021_W_STATS_TRAILER_LEN)) {
*err_info = g_strdup_printf("vwr: Invalid data length %u (runs past the end of the record)",
actual_octets);
*err = WTAP_ERR_BAD_FILE;
return FALSE;
}
f_tx = IS_TX;
flow_seq = s_trail_ptr[vVW510021_W_FLOWSEQ_OFF];
latency = 0x00000000;                        
flow_id = pntoh24(&s_trail_ptr[vVW510021_W_FLOWID_OFF]);         
tsid = pcorey48tohll(&s_trail_ptr[vVW510021_W_LATVAL_OFF]);
errors = pntoh32(&s_trail_ptr[vVW510021_W_ERRORS_OFF]);
info = pntoh16(&s_trail_ptr[vVW510021_W_INFO_OFF]);
if ((info & v22_W_AGGREGATE_FLAGS) != 0)
ht_len = pletoh16(&s_start_ptr[vwr->PLCP_LENGTH_OFF]);
if (plcp_type == vVW510021_W_PLCP_LEGACY){
if (mcs_index < 4) {
chanflags |= CHAN_CCK;
}
else {
chanflags |= CHAN_OFDM;
}
}
else if (plcp_type == vVW510021_W_PLCP_MIXED) {
radioflags |= FLAGS_CHAN_HT | ((plcp_ptr[3] & 0x80) ? FLAGS_CHAN_40MHZ : 0) |
((l1p_1 & vVW510021_W_IS_LONGGI) ? 0 : FLAGS_CHAN_SHORTGI);
chanflags  |= CHAN_OFDM;
}
else if (plcp_type == vVW510021_W_PLCP_GREENFIELD) {
radioflags |= FLAGS_CHAN_HT | ((plcp_ptr[0] & 0x80) ? FLAGS_CHAN_40MHZ : 0) |
((l1p_1 & vVW510021_W_IS_LONGGI) ?  0 : FLAGS_CHAN_SHORTGI);
chanflags  |= CHAN_OFDM;
}
else if (plcp_type == vVW510021_W_PLCP_VHT_MIXED) {
guint8 SBW = vVW510021_W_BANDWIDTH_VHT(l1p_2);
radioflags |= FLAGS_CHAN_VHT | ((l1p_1 & vVW510021_W_IS_LONGGI) ?  0 : FLAGS_CHAN_SHORTGI);
chanflags |= CHAN_OFDM;
if (SBW == 3)
radioflags |= FLAGS_CHAN_40MHZ;
else if (SBW == 4)
radioflags |= FLAGS_CHAN_80MHZ;
}
s_time = pcoreytohll(&s_trail_ptr[vVW510021_W_STARTT_OFF]);
e_time = pcoreytohll(&s_trail_ptr[vVW510021_W_ENDT_OFF]);
d_time = (guint32)((e_time - s_time) / NS_IN_US);  
start_time = s_time / NS_IN_US;                     
s_sec = (start_time / US_IN_SEC);                   
s_usec = start_time - (s_sec * US_IN_SEC);          
end_time = e_time / NS_IN_US;                       
m_ptr = &(rec[8+12]);
pay_off = 42;         
sig_off = find_signature(m_ptr, rec_size - 20, pay_off, flow_id, flow_seq);
if ((m_ptr[sig_off] == 0xdd) && (sig_off + 15 <= (rec_size - vVW510021_W_STATS_TRAILER_LEN)))
sig_ts = get_signature_ts(m_ptr, sig_off);
else
sig_ts = 0;
if (!IS_TX) {
if (tsid < s_time) {
latency = s_time - tsid;
} else {
delta_b = tsid - s_time;
if (delta_b >  0x10000000)
latency = 0;
else
latency = delta_b;
}
}
phdr->len = STATS_COMMON_FIELDS_LEN + EXT_WLAN_FIELDS_LEN + 1 + 16 + actual_octets;
phdr->caplen = STATS_COMMON_FIELDS_LEN + EXT_WLAN_FIELDS_LEN + 1 + 16 + actual_octets;
if (phdr->caplen > WTAP_MAX_PACKET_SIZE) {
*err_info = g_strdup_printf("vwr: File has %u-byte packet, bigger than maximum of %u",
phdr->caplen, WTAP_MAX_PACKET_SIZE);
*err = WTAP_ERR_BAD_FILE;
return FALSE;
}
phdr->ts.secs   = (time_t)s_sec;
phdr->ts.nsecs  = (int)(s_usec * 1000);
phdr->pkt_encap = WTAP_ENCAP_IXVERIWAVE;
phdr->rec_type = REC_TYPE_PACKET;
phdr->presence_flags = WTAP_HAS_TS;
ws_buffer_assure_space(buf, phdr->caplen);
data_ptr = ws_buffer_start_ptr(buf);
phtoles(&data_ptr[bytes_written], 0); 
bytes_written += 2;
phtoles(&data_ptr[bytes_written], STATS_COMMON_FIELDS_LEN); 
bytes_written += 2;
phtoles(&data_ptr[bytes_written], msdu_length);
bytes_written += 2;
phtolel(&data_ptr[bytes_written], flow_id);
bytes_written += 4;
phtoles(&data_ptr[bytes_written], vc_id);
bytes_written += 2;
phtoles(&data_ptr[bytes_written], flow_seq);
bytes_written += 2;
if (!f_tx && sig_ts != 0) {
phtolel(&data_ptr[bytes_written], latency);
} else {
phtolel(&data_ptr[bytes_written], 0);
}
bytes_written += 4;
phtolel(&data_ptr[bytes_written], sig_ts); 
bytes_written += 4;
phtolell(&data_ptr[bytes_written], start_time); 
bytes_written += 8;
phtolell(&data_ptr[bytes_written], end_time);
bytes_written += 8;
phtolel(&data_ptr[bytes_written], d_time);
bytes_written += 4;
phtoles(&data_ptr[bytes_written], EXT_WLAN_FIELDS_LEN);
bytes_written += 2;
if (info & vVW510021_W_IS_WEP)
radioflags |= FLAGS_WEP;
if (!(l1p_1 & vVW510021_W_IS_LONGPREAMBLE) && (plcp_type == vVW510021_W_PLCP_LEGACY))
radioflags |= FLAGS_SHORTPRE;
phtoles(&data_ptr[bytes_written], radioflags);
bytes_written += 2;
phtoles(&data_ptr[bytes_written], chanflags);
bytes_written += 2;
phyRate = (guint16)(getRate(plcp_type, mcs_index, radioflags, nss) * 10);
phtoles(&data_ptr[bytes_written], phyRate);
bytes_written += 2;
if (!IS_TX) {
plcp_type = vht_ndp_flag  + plcp_type;
}
data_ptr[bytes_written] = plcp_type;
bytes_written += 1;
data_ptr[bytes_written] = mcs_index;
bytes_written += 1;
data_ptr[bytes_written] = nss;
bytes_written += 1;
data_ptr[bytes_written] = rssi[0];
bytes_written += 1;
data_ptr[bytes_written] = rssi[1];
bytes_written += 1;
data_ptr[bytes_written] = rssi[2];
bytes_written += 1;
data_ptr[bytes_written] = rssi[3];
bytes_written += 1;
data_ptr[bytes_written] = 0;
bytes_written += 1;
vw_flags  = 0;
if (f_tx)
vw_flags |= VW_FLAGS_TXF;
if (errors & 0x1f)  
vw_flags |= VW_FLAGS_FCSERR;
if (!f_tx && (errors & vwr->CRYPTO_ERR))
vw_flags |= VW_FLAGS_DCRERR;
if (!f_tx && (errors & vwr->RETRY_ERR))
vw_flags |= VW_FLAGS_RETRERR;
if (info & vwr->WEPTYPE)
vw_flags |= VW_FLAGS_IS_WEP;
else if (info & vwr->TKIPTYPE)
vw_flags |= VW_FLAGS_IS_TKIP;
else if (info & vwr->CCMPTYPE)
vw_flags |= VW_FLAGS_IS_CCMP;
phtoles(&data_ptr[bytes_written], vw_flags);
bytes_written += 2;
phtoles(&data_ptr[bytes_written], ht_len);
bytes_written += 2;
phtoles(&data_ptr[bytes_written], info);
bytes_written += 2;
phtolel(&data_ptr[bytes_written], errors);
bytes_written += 4;
if (!IS_TX){
data_ptr[bytes_written] = vht_ndp_flag;
} else {
data_ptr[bytes_written] = 0;
}
bytes_written += 1;
memcpy(&data_ptr[bytes_written], &rec[16], 16);
bytes_written += 16;
memcpy(&data_ptr[bytes_written], &rec[vwr->MPDU_OFF], actual_octets);
return TRUE;
}

static int
dot24_print_page (gx_device_printer *pdev, gp_file *prn_stream, char *init_string, int init_len)
{
int xres = (int)pdev->x_pixels_per_inch;
int yres = (int)pdev->y_pixels_per_inch;
int x_high = (xres == 360);
int y_high = (yres == 360);
int bits_per_column = (y_high ? 48 : 24);
uint line_size = gdev_prn_raster (pdev);
uint in_size = line_size * bits_per_column;
byte *in = (byte *) gs_malloc (pdev->memory, in_size, 1, "dot24_print_page (in)");
uint out_size = ((pdev->width + 7) & -8) * 3;
byte *out = (byte *) gs_malloc (pdev->memory, out_size, 1, "dot24_print_page (out)");
int y_passes = (y_high ? 2 : 1);
int dots_per_space = xres / 10;
int bytes_per_space = dots_per_space * 3;
int skip = 0, lnum = 0, ypass;
if (in == 0 || out == 0)
{
if (out)
gs_free (pdev->memory, (char *) out, out_size, 1, "dot24_print_page (out)");
if (in)
gs_free (pdev->memory, (char *) in, in_size, 1, "dot24_print_page (in)");
return_error (gs_error_VMerror);
}
gp_fwrite (init_string, init_len - 1, sizeof (char), prn_stream);
gp_fputc ((int) (pdev->width / pdev->x_pixels_per_inch * 10) + 2,
prn_stream);
while (lnum < pdev->height)
{
byte *inp;
byte *in_end;
byte *out_end;
byte *out_blk;
register byte *outp;
int lcnt;
gdev_prn_copy_scan_lines (pdev, lnum, in, line_size);
if (in[0] == 0
&& !memcmp ((char *) in, (char *) in + 1, line_size - 1))
{
lnum++;
skip += 2 - y_high;
continue;
}
while ((skip >> 1) > 255)
{
gp_fputs ("\033J\377", prn_stream);
skip -= 255 * 2;
}
if (skip)
{
if (skip >> 1)
gp_fprintf (prn_stream, "\033J%c", skip >> 1);
if (skip & 1)
gp_fputc ('\n', prn_stream);
}
if (y_high)
{
inp = in + line_size;
for (lcnt = 1; lcnt < 24; lcnt++, inp += line_size)
if (!gdev_prn_copy_scan_lines (pdev, lnum + lcnt * 2, inp,
line_size))
{
memset (inp, 0, (24 - lcnt) * line_size);
break;
}
inp = in + line_size * 24;
for (lcnt = 0; lcnt < 24; lcnt++, inp += line_size)
if (!gdev_prn_copy_scan_lines (pdev, lnum + lcnt * 2 + 1, inp,
line_size))
{
memset (inp, 0, (24 - lcnt) * line_size);
break;
}
}
else
{
lcnt = 1 + gdev_prn_copy_scan_lines (pdev, lnum + 1, in + line_size,
in_size - line_size);
if (lcnt < 24)
memset (in + lcnt * line_size, 0, in_size - lcnt * line_size);
}
for (ypass = 0; ypass < y_passes; ypass++)
{
out_end = out;
inp = in;
if (ypass)
inp += line_size * 24;
in_end = inp + line_size;
for (; inp < in_end; inp++, out_end += 24)
{
memflip8x8 (inp, line_size, out_end, 3);
memflip8x8 (inp + line_size * 8, line_size, out_end + 1, 3);
memflip8x8 (inp + line_size * 16, line_size, out_end + 2, 3);
}
while (out_end - 3 >= out && out_end[-1] == 0
&& out_end[-2] == 0 && out_end[-3] == 0)
out_end -= 3;
for (out_blk = outp = out; outp < out_end;)
{
if (outp[0] == 0 && outp + 12 <= out_end
&& outp[1] == 0 && outp[2] == 0
&& outp[3] == 0 && outp[4] == 0 && outp[5] == 0
&& outp[6] == 0 && outp[7] == 0 && outp[8] == 0
&& outp[9] == 0 && outp[10] == 0 && outp[11] == 0)
{
byte *zp = outp;
int tpos;
byte *newp;
outp += 12;
while (outp + 3 <= out_end
&& outp[0] == 0 && outp[1] == 0 && outp[2] == 0)
outp += 3;
tpos = (outp - out) / bytes_per_space;
newp = out + tpos * bytes_per_space;
if (newp > zp + 10)
{
if (zp > out_blk)
{
if (x_high)
dot24_improve_bitmap (out_blk, (int) (zp - out_blk));
dot24_output_run (out_blk, (int) (zp - out_blk),
x_high, prn_stream);
}
gp_fprintf (prn_stream, "\033D%c%c\t", tpos, 0);
out_blk = outp = newp;
}
}
else
outp += 3;
}
if (outp > out_blk)
{
if (x_high)
dot24_improve_bitmap (out_blk, (int) (outp - out_blk));
dot24_output_run (out_blk, (int) (outp - out_blk), x_high,
prn_stream);
}
gp_fputc ('\r', prn_stream);
if (ypass < y_passes - 1)
gp_fputc ('\n', prn_stream);
}
skip = 48 - y_high;
lnum += bits_per_column;
}
gp_fputs ("\f\033@", prn_stream);
gp_fflush (prn_stream);
gs_free (pdev->memory, (char *) out, out_size, 1, "dot24_print_page (out)");
gs_free (pdev->memory, (char *) in, in_size, 1, "dot24_print_page (in)");
return 0;
}

status_t MyOpusExtractor::readNextPacket(MediaBuffer **out) {
if (mOffset <= mFirstDataOffset && mStartGranulePosition < 0) {
MediaBuffer *mBuf;
uint32_t numSamples = 0;
uint64_t curGranulePosition = 0;
while (true) {
status_t err = _readNextPacket(&mBuf, false);
if (err != OK && err != ERROR_END_OF_STREAM) {
return err;
}
if (err == ERROR_END_OF_STREAM || mCurrentPage.mPageNo > 2) {
break;
}
curGranulePosition = mCurrentPage.mGranulePosition;
numSamples += getNumSamplesInPacket(mBuf);
mBuf->release();
mBuf = NULL;
}
if (curGranulePosition > numSamples) {
mStartGranulePosition = curGranulePosition - numSamples;
} else {
mStartGranulePosition = 0;
}
seekToOffset(0);
}
status_t err = _readNextPacket(out, false);
if (err != OK) {
return err;
}
int32_t currentPageSamples;
if ((*out)->meta_data()->findInt32(kKeyValidSamples, &currentPageSamples)) {
if (mOffset == mFirstDataOffset) {
currentPageSamples -= mStartGranulePosition;
(*out)->meta_data()->setInt32(kKeyValidSamples, currentPageSamples);
}
mCurGranulePosition = mCurrentPage.mGranulePosition - currentPageSamples;
}
int64_t timeUs = getTimeUsOfGranule(mCurGranulePosition);
(*out)->meta_data()->setInt64(kKeyTime, timeUs);
uint32_t frames = getNumSamplesInPacket(*out);
mCurGranulePosition += frames;
return OK;
}

bool MfccMelFilterbank::Initialize(int input_length, double input_sample_rate,
int output_channel_count,
double lower_frequency_limit,
double upper_frequency_limit) {
num_channels_ = output_channel_count;
sample_rate_ = input_sample_rate;
input_length_ = input_length;
if (num_channels_ < 1) {
LOG(ERROR) << "Number of filterbank channels must be positive.";
return false;
}
if (sample_rate_ <= 0) {
LOG(ERROR) << "Sample rate must be positive.";
return false;
}
if (input_length < 2) {
LOG(ERROR) << "Input length must greater than 1.";
return false;
}
if (lower_frequency_limit < 0) {
LOG(ERROR) << "Lower frequency limit must be nonnegative.";
return false;
}
if (upper_frequency_limit <= lower_frequency_limit) {
LOG(ERROR) << "Upper frequency limit must be greater than "
<< "lower frequency limit.";
return false;
}
center_frequencies_.resize(num_channels_ + 1);
const double mel_low = FreqToMel(lower_frequency_limit);
const double mel_hi = FreqToMel(upper_frequency_limit);
const double mel_span = mel_hi - mel_low;
const double mel_spacing = mel_span / static_cast<double>(num_channels_ + 1);
for (int i = 0; i < num_channels_ + 1; ++i) {
center_frequencies_[i] = mel_low + (mel_spacing * (i + 1));
}
const double hz_per_sbin =
0.5 * sample_rate_ / static_cast<double>(input_length_ - 1);
start_index_ = static_cast<int>(1.5 + (lower_frequency_limit / hz_per_sbin));
end_index_ = static_cast<int>(upper_frequency_limit / hz_per_sbin);
band_mapper_.resize(input_length_);
int channel = 0;
for (int i = 0; i < input_length_; ++i) {
double melf = FreqToMel(i * hz_per_sbin);
if ((i < start_index_) || (i > end_index_)) {
band_mapper_[i] = -2;      } else {
while ((channel < num_channels_) &&
(center_frequencies_[channel] < melf)) {
++channel;
}
band_mapper_[i] = channel - 1;      }
}
weights_.resize(input_length_);
for (int i = 0; i < input_length_; ++i) {
channel = band_mapper_[i];
if ((i < start_index_) || (i > end_index_)) {
weights_[i] = 0.0;
} else {
if (channel >= 0) {
weights_[i] =
(center_frequencies_[channel + 1] - FreqToMel(i * hz_per_sbin)) /
(center_frequencies_[channel + 1] - center_frequencies_[channel]);
} else {
weights_[i] = (center_frequencies_[0] - FreqToMel(i * hz_per_sbin)) /
(center_frequencies_[0] - mel_low);
}
}
}
std::vector<int> bad_channels;
for (int c = 0; c < num_channels_; ++c) {
float band_weights_sum = 0.0;
for (int i = 0; i < input_length_; ++i) {
if (band_mapper_[i] == c - 1) {
band_weights_sum += (1.0 - weights_[i]);
} else if (band_mapper_[i] == c) {
band_weights_sum += weights_[i];
}
}
if (band_weights_sum < 0.5) {
bad_channels.push_back(c);
}
}
if (!bad_channels.empty()) {
LOG(ERROR) << "Missing " << bad_channels.size() << " bands "
<< " starting at " << bad_channels[0]
<< " in mel-frequency design. "
<< "Perhaps too many channels or "
<< "not enough frequency resolution in spectrum. ("
<< "input_length: " << input_length
<< " input_sample_rate: " << input_sample_rate
<< " output_channel_count: " << output_channel_count
<< " lower_frequency_limit: " << lower_frequency_limit
<< " upper_frequency_limit: " << upper_frequency_limit;
}
initialized_ = true;
return true;
}

