!(s->s3->flags & SSL3_FLAGS_NO_RENEGOTIATE_CIPHERS)) {
ossl_statem_set_in_init(s, 1);
s->renegotiate = 1;
s->new_session = 1;
}
i = s->handshake_func(s);
if (i < 0)
return (i);
if (i == 0) {
SSLerr(SSL_F_DTLS1_READ_BYTES, SSL_R_SSL_HANDSHAKE_FAILURE);
return (-1);
}
if (!(s->mode & SSL_MODE_AUTO_RETRY)) {
if (SSL3_BUFFER_get_left(&s->rlayer.rbuf) == 0) {
BIO *bio;
s->rwstate = SSL_READING;
bio = SSL_get_rbio(s);
BIO_clear_retry_flags(bio);
BIO_set_retry_read(bio);
return (-1);
}
}
goto start;
}
switch (SSL3_RECORD_get_type(rr)) {
default:
if (s->version == TLS1_VERSION) {
SSL3_RECORD_set_length(rr, 0);
goto start;
}
al = SSL_AD_UNEXPECTED_MESSAGE;
SSLerr(SSL_F_DTLS1_READ_BYTES, SSL_R_UNEXPECTED_RECORD);
goto f_err;
case SSL3_RT_CHANGE_CIPHER_SPEC:
case SSL3_RT_ALERT:
case SSL3_RT_HANDSHAKE:
al = SSL_AD_UNEXPECTED_MESSAGE;
SSLerr(SSL_F_DTLS1_READ_BYTES, ERR_R_INTERNAL_ERROR);
goto f_err;
case SSL3_RT_APPLICATION_DATA:
if (s->s3->in_read_app_data &&
(s->s3->total_renegotiations != 0) &&
ossl_statem_app_data_allowed(s)) {
s->s3->in_read_app_data = 2;
return (-1);
} else {
al = SSL_AD_UNEXPECTED_MESSAGE;
SSLerr(SSL_F_DTLS1_READ_BYTES, SSL_R_UNEXPECTED_RECORD);
goto f_err;
}
}
f_err:
ssl3_send_alert(s, SSL3_AL_FATAL, al);
return (-1);
}

int bgp_nlri_parse_flowspec(struct peer *peer, struct attr *attr,
struct bgp_nlri *packet, int withdraw)
{
uint8_t *pnt;
uint8_t *lim;
afi_t afi;
safi_t safi;
int psize = 0;
struct prefix p;
void *temp;
pnt = packet->nlri;
lim = pnt + packet->length;
afi = packet->afi;
safi = packet->safi;
if (packet->length >= FLOWSPEC_NLRI_SIZELIMIT_EXTENDED) {
flog_err(EC_BGP_FLOWSPEC_PACKET,
"BGP flowspec nlri length maximum reached (%u)",
packet->length);
return BGP_NLRI_PARSE_ERROR_FLOWSPEC_NLRI_SIZELIMIT;
}
for (; pnt < lim; pnt += psize) {
memset(&p, 0, sizeof(p));
if (pnt + 1 > lim)
return BGP_NLRI_PARSE_ERROR_PACKET_OVERFLOW;
psize = *pnt++;
if (psize >= FLOWSPEC_NLRI_SIZELIMIT) {
psize &= 0x0f;
psize = psize << 8;
psize |= *pnt++;
}
if (pnt + psize > lim) {
flog_err(
EC_BGP_FLOWSPEC_PACKET,
"Flowspec NLRI length inconsistent ( size %u seen)",
psize);
return BGP_NLRI_PARSE_ERROR_PACKET_OVERFLOW;
}
if (psize == 0) {
flog_err(EC_BGP_FLOWSPEC_PACKET,
"Flowspec NLRI length 0 which makes no sense");
return BGP_NLRI_PARSE_ERROR_PACKET_OVERFLOW;
}
if (bgp_fs_nlri_validate(pnt, psize, afi) < 0) {
flog_err(
EC_BGP_FLOWSPEC_PACKET,
"Bad flowspec format or NLRI options not supported");
return BGP_NLRI_PARSE_ERROR_FLOWSPEC_BAD_FORMAT;
}
p.family = AF_FLOWSPEC;
p.prefixlen = 0;
p.u.prefix_flowspec.prefixlen = psize;
p.u.prefix_flowspec.family = afi2family(afi);
temp = XCALLOC(MTYPE_TMP, psize);
memcpy(temp, pnt, psize);
p.u.prefix_flowspec.ptr = (uintptr_t) temp;
if (BGP_DEBUG(flowspec, FLOWSPEC)) {
char return_string[BGP_FLOWSPEC_NLRI_STRING_MAX];
char local_string[BGP_FLOWSPEC_NLRI_STRING_MAX*2+16];
char ec_string[BGP_FLOWSPEC_NLRI_STRING_MAX];
char *s = NULL;
bgp_fs_nlri_get_string((unsigned char *)
p.u.prefix_flowspec.ptr,
p.u.prefix_flowspec.prefixlen,
return_string,
NLRI_STRING_FORMAT_MIN, NULL,
afi);
snprintf(ec_string, sizeof(ec_string),
"EC{none}");
if (attr && bgp_attr_get_ecommunity(attr)) {
s = ecommunity_ecom2str(
bgp_attr_get_ecommunity(attr),
ECOMMUNITY_FORMAT_ROUTE_MAP, 0);
snprintf(ec_string, sizeof(ec_string),
"EC{%s}",
s == NULL ? "none" : s);
if (s)
ecommunity_strfree(&s);
}
snprintf(local_string, sizeof(local_string),
"FS Rx %s %s %s %s", withdraw ?
"Withdraw":"Update",
afi2str(afi), return_string,
attr != NULL ? ec_string : "");
zlog_info("%s", local_string);
}
if (!withdraw)
bgp_update(peer, &p, 0, attr, afi, safi,
ZEBRA_ROUTE_BGP, BGP_ROUTE_NORMAL, NULL,
NULL, 0, 0, NULL);
else
bgp_withdraw(peer, &p, 0, afi, safi, ZEBRA_ROUTE_BGP,
BGP_ROUTE_NORMAL, NULL, NULL, 0, NULL);
}
return BGP_NLRI_PARSE_OK;
}

void Compile(XlaOpKernelContext* ctx) override {
std::vector<xla::Literal> indices_input;
OP_REQUIRES_OK(ctx, ctx->ConstantInputList("indices", &indices_input));
std::vector<xla::XlaOp> data;
std::vector<TensorShape> data_shapes;
OP_REQUIRES_OK(ctx, ctx->InputList("data", &data, &data_shapes));
std::vector<xla::Literal> indices(indices_input.size());
const TensorShape& data0_shape = data_shapes[0];
TensorShape indices0_shape;
OP_REQUIRES_OK(
ctx, XLAShapeToTensorShape(indices_input[0].shape(), &indices0_shape));
for (int input_num = 0; input_num < indices_input.size(); input_num++) {
TensorShape indices_shape;
OP_REQUIRES_OK(ctx,
XLAShapeToTensorShape(indices_input[input_num].shape(),
&indices_shape));
TensorShape& data_shape = data_shapes[input_num];
if (!TensorShapeUtils::StartsWith(data_shape, indices_shape)) {
for (int64_t i = 0; i < indices_shape.dims(); ++i) {
data_shape.set_dim(i, indices_shape.dim_size(i));
data[input_num] = xla::SliceInDim(data[input_num], 0,
indices_shape.dim_size(i), 1, i);
}
}
OP_REQUIRES(
ctx, TensorShapeUtils::StartsWith(data_shape, indices_shape),
errors::InvalidArgument("data[", input_num,
"].shape = ", data_shape.DebugString(),
" does not start with indices[", input_num,
"].shape = ", indices_shape.DebugString()));
OP_REQUIRES(
ctx,
input_num == 0 || SameExtraShape(data0_shape, indices0_shape,
data_shape, indices_shape),
errors::InvalidArgument(
"Need data[0].shape[", indices0_shape.dims(), ":] = data[",
input_num, "].shape[", indices_shape.dims(),
":], got data[0].shape = ", data0_shape.DebugString(), ", data[",
input_num, "].shape = ", data_shape.DebugString(),
", indices[0].shape = ", indices0_shape.DebugString(),
", indices[", input_num,
"].shape = ", indices_shape.DebugString()));
OP_REQUIRES_OK(ctx,
XlaHelpers::ReshapeLiteral(indices_input[input_num],
{indices_shape.num_elements()},
&indices[input_num]));
}
int max_index = -1;
for (int input_num = 0; input_num < indices.size(); input_num++) {
for (int i = 0; i < indices[input_num].shape().dimensions(0); ++i) {
max_index = std::max(max_index, indices[input_num].Get<int>({i}));
}
}
int number_of_indices = max_index + 1;
int64_t result_rank = 1 + data0_shape.dims() - indices0_shape.dims();
if (number_of_indices == 0) {
std::vector<int64_t> result_shape(result_rank);
for (int d = indices0_shape.dims(); d < data0_shape.dims(); d++) {
result_shape[d - indices0_shape.dims() + 1] = data0_shape.dim_size(d);
}
xla::PrimitiveType element_type =
ctx->input_xla_type(ctx->num_inputs() - 1);
xla::Literal empty_literal = xla::Literal::CreateFromShape(
xla::ShapeUtil::MakeShape(element_type, result_shape));
ctx->SetOutput(0, xla::ConstantLiteral(ctx->builder(), empty_literal));
return;
}
std::vector<int32> src_input_vector(number_of_indices);
std::vector<int32> src_slice_vector(number_of_indices);
std::vector<bool> src_index_used(number_of_indices);
int index_used_count = 0;
for (int input_num = 0; input_num < indices.size(); input_num++) {
for (int i = 0; i < indices[input_num].shape().dimensions(0); ++i) {
int index = indices[input_num].Get<int>({i});
src_input_vector[index] = input_num;
src_slice_vector[index] = i;
if (!src_index_used[index]) {
src_index_used[index] = true;
++index_used_count;
}
}
}
OP_REQUIRES(ctx, index_used_count == number_of_indices,
errors::InvalidArgument("not all indices are used"));
std::vector<xla::XlaOp> input(indices.size());
for (int input_num = 0; input_num < indices.size(); input_num++) {
TensorShape new_shape;
new_shape.AddDim(indices[input_num].shape().dimensions(0));
for (int d = indices0_shape.dims(); d < data0_shape.dims(); d++) {
new_shape.AddDim(data0_shape.dim_size(d));
}
auto handle = data[input_num];
if (new_shape == data_shapes[input_num]) {
input[input_num] = handle;
} else {
input[input_num] = xla::Reshape(handle, new_shape.dim_sizes());
}
}
std::vector<int64_t> slice_start(result_rank);
std::vector<int64_t> slice_limit(result_rank);
std::vector<int64_t> stride(result_rank, 1);
for (int d = indices0_shape.dims(); d < data0_shape.dims(); d++) {
slice_limit[1 + d - indices0_shape.dims()] = data0_shape.dim_size(d);
}
std::vector<xla::XlaOp> to_concat(number_of_indices);
for (int index_num = 0; index_num < number_of_indices; index_num++) {
const auto& expression = input[src_input_vector[index_num]];
slice_start[0] = src_slice_vector[index_num];
slice_limit[0] = src_slice_vector[index_num] + 1;
to_concat[index_num] =
xla::Slice(expression, slice_start, slice_limit, stride);
}
ctx->SetOutput(0, xla::ConcatInDim(ctx->builder(), to_concat, 0));
}

Status SubstituteForEach(AttrMap& attrs, FullTypeDef& t) {
DCHECK_EQ(t.args_size(), 3);
const auto& cont = t.args(0);
const auto& tmpl = t.args(1);
const auto& t_var = t.args(2);
StringPiece var_name = t_var.s();
if (!attrs.contains(var_name)) {
return Status(
error::INVALID_ARGUMENT,
absl::StrCat("could not find an attribute for key '", var_name, "'"));
}
const AttrValue* attr = attrs.at(var_name);
FullTypeDef result;
result.set_type_id(cont.type_id());
const auto attr_type = attr->value_case();
if (attr_type == AttrValue::kType) {
FullTypeDef* target = result.add_args();
*target = tmpl;
TF_RETURN_WITH_CONTEXT_IF_ERROR(
SubstituteFromAttrs(attrs, *target), "while substituting '", var_name,
"' from\n", attr->DebugString(), "\ninto ", target->DebugString());
} else if (attr_type == AttrValue::kList) {
const auto& attr_list = attr->list();
int tsize = attr_list.type_size();
if (tsize == 0) {
return Status(error::UNIMPLEMENTED,
absl::StrCat("unsupported list attribute type\n",
attr_list.DebugString(), "\nkey=", var_name));
}
AttrValue replacement;
attrs[var_name] = &replacement;
for (int i = 0; i < tsize; i++) {
replacement.set_type(attr_list.type(i));
FullTypeDef* target = result.add_args();
*target = tmpl;
TF_RETURN_WITH_CONTEXT_IF_ERROR(SubstituteFromAttrs(attrs, *target),
"while substituting '", var_name,
"' from\n", attr->DebugString(), "\n[", i,
"] into\n", target->DebugString());
}
attrs[var_name] = attr;
} else {
return Status(error::UNIMPLEMENTED,
absl::StrCat("unsupported attribute type\n",
attr->DebugString(), "\nfor name ", var_name));
}
t = result;
return OkStatus();
}

static int
pj_common_print_page(gx_device_printer *pdev, gp_file *prn_stream, int y_origin,
const char *end_page)
{
#define DATA_SIZE (LINE_SIZE * 8)
byte *data =
(byte *)gs_malloc(pdev->memory, DATA_SIZE, 1,
"paintjet_print_page(data)");
byte *plane_data =
(byte *)gs_malloc(pdev->memory, LINE_SIZE * 3, 1,
"paintjet_print_page(plane_data)");
if ( data == 0 || plane_data == 0 )
{if ( data )
gs_free(pdev->memory, (char *)data, DATA_SIZE, 1,
"paintjet_print_page(data)");
if ( plane_data )
gs_free(pdev->memory, (char *)plane_data, LINE_SIZE * 3, 1,
"paintjet_print_page(plane_data)");
return_error(gs_error_VMerror);
}
gp_fprintf(prn_stream, "\033*t%dR", X_DPI);
gp_fprintf(prn_stream, "\033*r%dS", DATA_SIZE);
gp_fprintf(prn_stream, "\033*r%dU", 3);
gp_fprintf(prn_stream, "\033&a0H\033&a%dV", y_origin);
gp_fputs("\033*b1M", prn_stream);
gp_fputs("\033*r1A", prn_stream);
{int lnum;
int line_size = gdev_mem_bytes_per_scan_line((gx_device *)pdev);
int num_blank_lines = 0;
for ( lnum = 0; lnum < pdev->height; lnum++ )
{byte *end_data = data + line_size;
gdev_prn_copy_scan_lines(pdev, lnum,
(byte *)data, line_size);
while ( end_data > data && end_data[-1] == 0 )
end_data--;
if ( end_data == data )
{
num_blank_lines++;
}
else
{int i;
byte *odp;
byte *row;
memset(end_data, 0, 7);
for ( i = 0, odp = plane_data; i < DATA_SIZE;
i += 8, odp++
)
{ 
#define spread3(c)\
{ 0, c, c*0x100, c*0x101, c*0x10000L, c*0x10001L, c*0x10100L, c*0x10101L }
static ulong spr40[8] = spread3(0x40);
static ulong spr8[8] = spread3(8);
static ulong spr2[8] = spread3(2);
register byte *dp = data + i;
register ulong pword =
(spr40[dp[0]] << 1) +
(spr40[dp[1]]) +
(spr40[dp[2]] >> 1) +
(spr8[dp[3]] << 1) +
(spr8[dp[4]]) +
(spr8[dp[5]] >> 1) +
(spr2[dp[6]]) +
(spr2[dp[7]] >> 1);
odp[0] = (byte)(pword >> 16);
odp[LINE_SIZE] = (byte)(pword >> 8);
odp[LINE_SIZE*2] = (byte)(pword);
}
if ( num_blank_lines > 0 )
{
gp_fprintf(prn_stream, "\033&a+%dV",
num_blank_lines * (720 / Y_DPI));
num_blank_lines = 0;
}
for ( row = plane_data + LINE_SIZE * 2, i = 0;
i < 3; row -= LINE_SIZE, i++
)
{byte temp[LINE_SIZE * 2];
int count = compress1_row(row, row + LINE_SIZE, temp);
gp_fprintf(prn_stream, "\033*b%d%c",
count, "VVW"[i]);
gp_fwrite(temp, sizeof(byte),
count, prn_stream);
}
}
}
}
gp_fputs(end_page, prn_stream);
gs_free(pdev->memory, (char *)data, DATA_SIZE, 1, "paintjet_print_page(data)");
gs_free(pdev->memory, (char *)plane_data, LINE_SIZE * 3, 1, "paintjet_print_page(plane_data)");
return 0;
}

