static void
_joinW(WCHAR *dest_path, const WCHAR *root, const WCHAR *rest)
{
size_t root_len;
if (_is_absW(rest)) {
wcscpy(dest_path, rest);
return;
}
root_len = wcslen(root);
wcscpy(dest_path, root);
if(root_len) {
dest_path[root_len] = L'\\';
root_len++;
}
wcscpy(dest_path+root_len, rest);
}

static gboolean
default_authenticate (GstRTSPAuth * auth, GstRTSPContext * ctx)
{
GstRTSPAuthPrivate *priv = auth->priv;
GstRTSPAuthCredential **credentials, **credential;
GST_DEBUG_OBJECT (auth, "authenticate");
g_mutex_lock (&priv->lock);
ctx->token = priv->default_token;
g_mutex_unlock (&priv->lock);
credentials =
gst_rtsp_message_parse_auth_credentials (ctx->request,
GST_RTSP_HDR_AUTHORIZATION);
if (!credentials)
goto no_auth;
credential = credentials;
while (*credential) {
if ((*credential)->scheme == GST_RTSP_AUTH_BASIC) {
GstRTSPToken *token;
GST_DEBUG_OBJECT (auth, "check Basic auth");
g_mutex_lock (&priv->lock);
if ((token =
g_hash_table_lookup (priv->basic,
(*credential)->authorization))) {
GST_DEBUG_OBJECT (auth, "setting token %p", token);
ctx->token = token;
g_mutex_unlock (&priv->lock);
break;
}
g_mutex_unlock (&priv->lock);
} else if ((*credential)->scheme == GST_RTSP_AUTH_DIGEST) {
if (default_digest_auth (auth, ctx, (*credential)->params))
break;
}
credential++;
}
gst_rtsp_auth_credentials_free (credentials);
return TRUE;
no_auth:
{
GST_DEBUG_OBJECT (auth, "no authorization header found");
return TRUE;
}
}

static gint rtps_util_add_typecode(proto_tree *tree, tvbuff_t *tvb, gint offset, const guint encoding,
int      indent_level, int is_pointer, guint16 bitfield, int is_key, const gint offset_begin,
char    *name,
int      seq_max_len,   
guint32 *arr_dimension, 
int      ndds_40_hack) {
const gint    original_offset = offset;
guint32       tk_id;
guint16       tk_size;
unsigned int  i;
char         *indent_string;
gint          retVal;
char          type_name[40];
indent_string = (char *)wmem_alloc(wmem_epan_scope(), (indent_level*2)+1);
memset(indent_string, ' ', (indent_level*2)+1);
indent_string[indent_level*2] = '\0';
LONG_ALIGN(offset);
tk_id = tvb_get_guint32(tvb, offset, encoding);
offset += 4;
tk_size = tvb_get_guint16(tvb, offset, encoding);
offset += 2;
retVal = tk_size + 6; 
tk_id &= 0x7fffffff;
if (indent_level == 0) {
if (tk_id == RTI_CDR_TK_OCTET) {
ndds_40_hack = 1;
}
}
if (ndds_40_hack) {
++tk_id;
}
(void) g_strlcpy(type_name, rtps_util_typecode_id_to_string(tk_id), 40);
switch(tk_id) {
case RTI_CDR_TK_UNION: {
guint32     struct_name_len;
guint8      *struct_name;
const char *discriminator_name      = "<unknown>"; 
char       *discriminator_enum_name = NULL;        
guint32     disc_id;                               
guint16     disc_size;                             
guint32     disc_offset_begin, num_members, member_name_len;
guint16     member_length;
guint8     *member_name             = NULL;
guint32     next_offset, field_offset_begin, member_label_count, discriminator_enum_name_length;
gint32      member_label;
guint       j;
LONG_ALIGN(offset);
struct_name_len = tvb_get_guint32(tvb, offset, encoding);
offset += 4;
struct_name = tvb_get_string_enc(wmem_packet_scope(), tvb, offset, struct_name_len, ENC_ASCII);
offset = check_offset_addition(offset, struct_name_len, tree, NULL, tvb);
LONG_ALIGN(offset);
offset += 4;
disc_id = tvb_get_guint32(tvb, offset, encoding);
offset += 4;
disc_size = tvb_get_guint16(tvb, offset, encoding);
offset += 2;
disc_offset_begin = offset;
disc_id &= 0x7fffffff;
discriminator_name = rtps_util_typecode_id_to_string(disc_id);
if (disc_id == RTI_CDR_TK_ENUM) {
