BGD_DECLARE(void) gdImageXbmCtx(gdImagePtr image, char* file_name, int fg, gdIOCtx * out)
{
int x, y, c, b, sx, sy, p;
char *name, *f;
size_t i, l;
name = file_name;
if ((f = strrchr(name, '/')) != NULL) name = f+1;
if ((f = strrchr(name, '\\')) != NULL) name = f+1;
name = strdup(name);
if ((f = strrchr(name, '.')) != NULL && !strcasecmp(f, ".XBM")) *f = '\0';
if ((l = strlen(name)) == 0) {
free(name);
name = strdup("image");
} else {
for (i=0; i<l; i++) {
if (!isupper(name[i]) && !islower(name[i]) && !isdigit(name[i])) {
name[i] = '_';
}
}
}
gdCtxPrintf(out, "#define %s_width %d\n", name, gdImageSX(image));
gdCtxPrintf(out, "#define %s_height %d\n", name, gdImageSY(image));
gdCtxPrintf(out, "static unsigned char %s_bits[] = {\n  ", name);
free(name);
b = 1;
p = 0;
c = 0;
sx = gdImageSX(image);
sy = gdImageSY(image);
for (y = 0; y < sy; y++) {
for (x = 0; x < sx; x++) {
if (gdImageGetPixel(image, x, y) == fg) {
c |= b;
}
if ((b == 128) || (x == sx && y == sy)) {
b = 1;
if (p) {
gdCtxPrintf(out, ", ");
if (!(p%12)) {
gdCtxPrintf(out, "\n  ");
p = 12;
}
}
p++;
gdCtxPrintf(out, "0x%02X", c);
c = 0;
} else {
b <<= 1;
}
}
}
gdCtxPrintf(out, "};\n");
}

void
beep_print(netdissect_options *ndo, const u_char *bp, u_int length)
{
if (l_strnstart("MSG", 4, (const char *)bp, length)) 
ND_PRINT((ndo, " BEEP MSG"));
else if (l_strnstart("RPY ", 4, (const char *)bp, length))
ND_PRINT((ndo, " BEEP RPY"));
else if (l_strnstart("ERR ", 4, (const char *)bp, length))
ND_PRINT((ndo, " BEEP ERR"));
else if (l_strnstart("ANS ", 4, (const char *)bp, length))
ND_PRINT((ndo, " BEEP ANS"));
else if (l_strnstart("NUL ", 4, (const char *)bp, length))
ND_PRINT((ndo, " BEEP NUL"));
else if (l_strnstart("SEQ ", 4, (const char *)bp, length))
ND_PRINT((ndo, " BEEP SEQ"));
else if (l_strnstart("END", 4, (const char *)bp, length))
ND_PRINT((ndo, " BEEP END"));
else
ND_PRINT((ndo, " BEEP (payload or undecoded)"));
}

static void cryptinfo_node_start(void *sax_cbck, const char *node_name, const char *name_space, const GF_XMLAttribute *attributes, u32 nb_attributes)
{
GF_XMLAttribute *att;
GF_TrackCryptInfo *tkc;
u32 i;
GF_CryptInfo *info = (GF_CryptInfo *)sax_cbck;
if (!strcmp(node_name, "OMATextHeader")) {
info->in_text_header = 1;
return;
}
if (!strcmp(node_name, "GPACDRM")) {
for (i=0; i<nb_attributes; i++) {
att = (GF_XMLAttribute *) &attributes[i];
if (!stricmp(att->name, "type")) {
info->def_crypt_type = cryptinfo_get_crypt_type(att->value);
}
}
return;
}
if (!strcmp(node_name, "CrypTrack")) {
Bool has_key = GF_FALSE;
Bool has_common_key = GF_TRUE;
GF_SAFEALLOC(tkc, GF_TrackCryptInfo);
if (!tkc) {
GF_LOG(GF_LOG_WARNING, GF_LOG_PARSER, ("[CENC] Cannnot allocate crypt track, skipping\n"));
info->last_parse_error = GF_OUT_OF_MEM;
return;
}
tkc->IsEncrypted = 1;
tkc->sai_saved_box_type = GF_ISOM_BOX_TYPE_SENC;
tkc->scheme_type = info->def_crypt_type;
tkc->keys = gf_malloc(sizeof(GF_CryptKeyInfo));
if (!tkc->keys) {
GF_LOG(GF_LOG_WARNING, GF_LOG_PARSER, ("[CENC] Cannnot allocate key IDs\n"));
gf_free(tkc);
info->last_parse_error = GF_OUT_OF_MEM;
return;
}
memset(tkc->keys, 0, sizeof(GF_CryptKeyInfo));
gf_list_add(info->tcis, tkc);
for (i=0; i<nb_attributes; i++) {
att = (GF_XMLAttribute *) &attributes[i];
if (!stricmp(att->name, "trackID") || !stricmp(att->name, "ID")) {
if (!strcmp(att->value, "*")) info->has_common_key = 1;
else {
tkc->trackID = atoi(att->value);
has_common_key = GF_FALSE;
}
}
else if (!stricmp(att->name, "type")) {
tkc->scheme_type = cryptinfo_get_crypt_type(att->value);
}
else if (!stricmp(att->name, "forceType")) {
tkc->force_type = GF_TRUE;
}
else if (!stricmp(att->name, "key")) {
GF_Err e;
has_key = GF_TRUE;
e = gf_bin128_parse(att->value, tkc->keys[0].key );
if (e != GF_OK) {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[CENC] Cannnot parse key value in CrypTrack\n"));
info->last_parse_error = GF_BAD_PARAM;
return;
}
}
else if (!stricmp(att->name, "salt")) {
u32 len, j;
char *sKey = att->value;
if (!strnicmp(sKey, "0x", 2)) sKey += 2;
len = (u32) strlen(sKey);
for (j=0; j<len; j+=2) {
char szV[5];
u32 v;
sprintf(szV, "%c%c", sKey[j], sKey[j+1]);
sscanf(szV, "%x", &v);
tkc->keys[0].IV[j/2] = v;
if (j>=30) break;
}
}
else if (!stricmp(att->name, "kms_URI") || !stricmp(att->name, "rightsIssuerURL")) {
if (tkc->KMS_URI) gf_free(tkc->KMS_URI);
tkc->KMS_URI = gf_strdup(att->value);
}
else if (!stricmp(att->name, "scheme_URI") || !stricmp(att->name, "contentID")) {
if (tkc->Scheme_URI) gf_free(tkc->Scheme_URI);
tkc->Scheme_URI = gf_strdup(att->value);
}
else if (!stricmp(att->name, "selectiveType")) {
if (!stricmp(att->value, "Rap")) tkc->sel_enc_type = GF_CRYPT_SELENC_RAP;
else if (!stricmp(att->value, "Non-Rap")) tkc->sel_enc_type = GF_CRYPT_SELENC_NON_RAP;
else if (!stricmp(att->value, "Rand")) tkc->sel_enc_type = GF_CRYPT_SELENC_RAND;
else if (!strnicmp(att->value, "Rand", 4)) {
tkc->sel_enc_type = GF_CRYPT_SELENC_RAND_RANGE;
tkc->sel_enc_range = atoi(&att->value[4]);
}
else if (sscanf(att->value, "%u", &tkc->sel_enc_range)==1) {
if (tkc->sel_enc_range==1) tkc->sel_enc_range = 0;
else tkc->sel_enc_type = GF_CRYPT_SELENC_RANGE;
}
else if (!strnicmp(att->value, "Preview", 7)) {
tkc->sel_enc_type = GF_CRYPT_SELENC_PREVIEW;
}
else if (!strnicmp(att->value, "Clear", 5)) {
tkc->sel_enc_type = GF_CRYPT_SELENC_CLEAR;
}
else if (!strnicmp(att->value, "ForceClear", 10)) {
char *sep = strchr(att->value, '=');
if (sep) tkc->sel_enc_range = atoi(sep+1);
tkc->sel_enc_type = GF_CRYPT_SELENC_CLEAR_FORCED;
}
else if (!stricmp(att->value, "None")) {
} else {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[CENC] Unrecognized selective mode %s, ignoring\n", att->value));
}
}
else if (!stricmp(att->name, "clearStsd")) {
if (!strcmp(att->value, "none")) tkc->force_clear_stsd_idx = 0;
else if (!strcmp(att->value, "before")) tkc->force_clear_stsd_idx = 1;
else if (!strcmp(att->value, "after")) tkc->force_clear_stsd_idx = 2;
else {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[CENC] Unrecognized clear stsd type %s, defaulting to no stsd for clear samples\n", att->value));
}
}
else if (!stricmp(att->name, "Preview")) {
tkc->sel_enc_type = GF_CRYPT_SELENC_PREVIEW;
sscanf(att->value, "%u", &tkc->sel_enc_range);
}
else if (!stricmp(att->name, "ipmpType")) {
if (!stricmp(att->value, "None")) tkc->ipmp_type = 0;
else if (!stricmp(att->value, "IPMP")) tkc->sel_enc_type = 1;
else if (!stricmp(att->value, "IPMPX")) tkc->sel_enc_type = 2;
}
else if (!stricmp(att->name, "ipmpDescriptorID")) tkc->ipmp_desc_id = atoi(att->value);
else if (!stricmp(att->name, "encryptionMethod")) {
if (!strcmp(att->value, "AES_128_CBC")) tkc->encryption = 1;
else if (!strcmp(att->value, "None")) tkc->encryption = 0;
else if (!strcmp(att->value, "AES_128_CTR") || !strcmp(att->value, "default")) tkc->encryption = 2;
else {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[CENC] Unrecognized encryption algo %s, ignoring\n", att->value));
}
}
else if (!stricmp(att->name, "transactionID")) {
if (strlen(att->value)<=16) strcpy(tkc->TransactionID, att->value);
}
else if (!stricmp(att->name, "textualHeaders")) {
}
else if (!stricmp(att->name, "IsEncrypted")) {
if (!stricmp(att->value, "1"))
tkc->IsEncrypted = 1;
else
tkc->IsEncrypted = 0;
}
else if (!stricmp(att->name, "IV_size")) {
tkc->keys[0].IV_size = atoi(att->value);
}
else if (!stricmp(att->name, "first_IV")) {
char *sKey = att->value;
if (!strnicmp(sKey, "0x", 2)) sKey += 2;
if ((strlen(sKey) == 16) || (strlen(sKey) == 32)) {
u32 j;
for (j=0; j<strlen(sKey); j+=2) {
u32 v;
char szV[5];
sprintf(szV, "%c%c", sKey[j], sKey[j+1]);
sscanf(szV, "%x", &v);
tkc->keys[0].IV[j/2] = v;
}
if (!tkc->keys[0].IV_size) tkc->keys[0].IV_size = (u8) strlen(sKey) / 2;
}
}
else if (!stricmp(att->name, "saiSavedBox")) {
if (!stricmp(att->value, "uuid_psec")) tkc->sai_saved_box_type = GF_ISOM_BOX_UUID_PSEC;
else if (!stricmp(att->value, "senc")) tkc->sai_saved_box_type = GF_ISOM_BOX_TYPE_SENC;
else {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[CENC] Unrecognized SAI location %s, ignoring\n", att->value));
}
}
else if (!stricmp(att->name, "keyRoll")) {
if (!strncmp(att->value, "idx=", 4))
tkc->defaultKeyIdx = atoi(att->value+4);
else if (!strncmp(att->value, "roll", 4) || !strncmp(att->value, "samp", 4)) {
tkc->roll_type = GF_KEYROLL_SAMPLES;
if (att->value[4]=='=') tkc->keyRoll = atoi(att->value+5);
if (!tkc->keyRoll) tkc->keyRoll = 1;
}
else if (!strncmp(att->value, "seg", 3)) {
tkc->roll_type = GF_KEYROLL_SEGMENTS;
if (att->value[3]=='=') tkc->keyRoll = atoi(att->value+4);
if (!tkc->keyRoll) tkc->keyRoll = 1;
} else if (!strncmp(att->value, "period", 6)) {
tkc->roll_type = GF_KEYROLL_PERIODS;
if (att->value[6]=='=') tkc->keyRoll = atoi(att->value+7);
if (!tkc->keyRoll) tkc->keyRoll = 1;
} else if (!strcmp(att->value, "rap")) {
tkc->roll_type = GF_KEYROLL_SAPS;
if (att->value[3]=='=') tkc->keyRoll = atoi(att->value+4);
if (!tkc->keyRoll) tkc->keyRoll = 1;
} else {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[CENC] Unrecognized roll parameter %s, ignoring\n", att->value));
}
}
else if (!stricmp(att->name, "random")) {
if (!strcmp(att->value, "true") || !strcmp(att->value, "1") || !strcmp(att->value, "yes")) {
tkc->rand_keys=GF_TRUE;
}
else if (!strcmp(att->value, "false") || !strcmp(att->value, "0") || !strcmp(att->value, "no")) {
tkc->rand_keys=GF_FALSE;
}
else {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[CENC] Unrecognized random parameter %s, ignoring\n", att->value));
}
}
else if (!stricmp(att->name, "metadata")) {
u32 l = 2 * (u32) strlen(att->value);
tkc->metadata = gf_malloc(sizeof(char) * l);
l = gf_base64_encode(att->value, (u32) strlen(att->value), tkc->metadata, l);
tkc->metadata[l] = 0;
}
else if (!stricmp(att->name, "crypt_byte_block")) {
tkc->crypt_byte_block = atoi(att->value);
}
else if (!stricmp(att->name, "skip_byte_block")) {
tkc->skip_byte_block = atoi(att->value);
}
else if (!stricmp(att->name, "clear_bytes")) {
tkc->clear_bytes = atoi(att->value);
}
else if (!stricmp(att->name, "constant_IV_size")) {
tkc->keys[0].constant_IV_size = atoi(att->value);
if ((tkc->keys[0].constant_IV_size != 8) && (tkc->keys[0].constant_IV_size != 16)) {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[CENC] Constant IV size %d is not 8 or 16\n", att->value));
}
}
else if (!stricmp(att->name, "constant_IV")) {
char *sKey = att->value;
if (!strnicmp(sKey, "0x", 2)) sKey += 2;
if ((strlen(sKey) == 16) || (strlen(sKey) == 32)) {
u32 j;
for (j=0; j<strlen(sKey); j+=2) {
u32 v;
char szV[5];
sprintf(szV, "%c%c", sKey[j], sKey[j+1]);
sscanf(szV, "%x", &v);
tkc->keys[0].IV[j/2] = v;
}
if (!tkc->keys[0].constant_IV_size) tkc->keys[0].constant_IV_size = (u8) strlen(sKey) / 2;
}
}
else if (!stricmp(att->name, "encryptSliceHeader")) {
tkc->allow_encrypted_slice_header = !strcmp(att->value, "yes") ? GF_TRUE : GF_FALSE;
}
else if (!stricmp(att->name, "blockAlign")) {
if (!strcmp(att->value, "disable")) tkc->block_align = 1;
else if (!strcmp(att->value, "always")) tkc->block_align = 2;
else tkc->block_align = 0;
}
else if (!stricmp(att->name, "subsamples")) {
char *val = att->value;
while (val) {
char *sep = strchr(val, ';');
if (sep) sep[0] = 0;
if (!strncmp(val, "subs=", 5)) {
if (tkc->subs_crypt) gf_free(tkc->subs_crypt);
tkc->subs_crypt = gf_strdup(val+4);
}
else if (!strncmp(val, "rand", 4)) {
tkc->subs_rand = 2;
if (val[4]=='=')
tkc->subs_rand = atoi(val+5);
}
else {
GF_LOG(GF_LOG_WARNING, GF_LOG_PARSER, ("[CENC] unrecognized attribute value %s for `subsamples`, ignoring\n", val));
}
if (!sep) break;
sep[0] = ';';
val = sep+1;
}
}
else if (!stricmp(att->name, "multiKey")) {
if (!strcmp(att->value, "all") || !strcmp(att->value, "on")) tkc->multi_key = GF_TRUE;
else if (!strcmp(att->value, "no")) tkc->multi_key = GF_FALSE;
else {
char *val = att->value;
tkc->multi_key = GF_TRUE;
while (val) {
char *sep = strchr(val, ';');
if (sep) sep[0] = 0;
if (!strncmp(val, "roll=", 5)) {
tkc->mkey_roll_plus_one = 1 + atoi(val+5);
}
else if (!strncmp(val, "subs=", 5)) {
if (tkc->mkey_subs) gf_free(tkc->mkey_subs);
tkc->mkey_subs = gf_strdup(val+5);
}
else {
GF_LOG(GF_LOG_WARNING, GF_LOG_PARSER, ("[CENC] unrecognized attribute value %s for `multiKey`, ignoring\n", val));
tkc->multi_key = GF_FALSE;
if (sep) sep[0] = ';';
break;
}
if (!sep) break;
sep[0] = ';';
val = sep+1;
}
}
}
}
if (tkc->scheme_type==GF_CRYPT_TYPE_PIFF) {
tkc->sai_saved_box_type = GF_ISOM_BOX_UUID_PSEC;
}
if (has_common_key) info->has_common_key = 1;
if ((tkc->keys[0].IV_size != 0) && (tkc->keys[0].IV_size != 8) && (tkc->keys[0].IV_size != 16)) {
GF_LOG(GF_LOG_WARNING, GF_LOG_PARSER, ("[CENC] wrong IV size %d for AES-128, using 16\n", (u32) tkc->keys[0].IV_size));
tkc->keys[0].IV_size = 16;
}
if ((tkc->scheme_type == GF_CRYPT_TYPE_CENC) || (tkc->scheme_type == GF_CRYPT_TYPE_CBC1)) {
if (tkc->crypt_byte_block || tkc->skip_byte_block) {
GF_LOG(GF_LOG_WARNING, GF_LOG_PARSER, ("[CENC] Using scheme type %s, crypt_byte_block and skip_byte_block shall be 0\n", gf_4cc_to_str(tkc->scheme_type) ));
tkc->crypt_byte_block = tkc->skip_byte_block = 0;
}
}
if ((tkc->scheme_type == GF_CRYPT_TYPE_CENC) || (tkc->scheme_type == GF_CRYPT_TYPE_CBC1) || (tkc->scheme_type == GF_CRYPT_TYPE_CENS)) {
if (tkc->keys[0].constant_IV_size) {
if (!tkc->keys[0].IV_size) {
tkc->keys[0].IV_size = tkc->keys[0].constant_IV_size;
GF_LOG(GF_LOG_WARNING, GF_LOG_PARSER, ("[CENC] Using scheme type %s, constant IV shall not be used, using constant IV as first IV\n", gf_4cc_to_str(tkc->scheme_type)));
tkc->keys[0].constant_IV_size = 0;
} else {
tkc->keys[0].constant_IV_size = 0;
GF_LOG(GF_LOG_WARNING, GF_LOG_PARSER, ("[CENC] Using scheme type %s, constant IV shall not be used, ignoring\n", gf_4cc_to_str(tkc->scheme_type)));
}
}
}
if (tkc->scheme_type == GF_ISOM_OMADRM_SCHEME) {
tkc->encryption = 2;
}
if (has_key) tkc->nb_keys = 1;
}
if (!strcmp(node_name, "key")) {
u32 IV_size, const_IV_size;
Bool kas_civ = GF_FALSE;
tkc = (GF_TrackCryptInfo *)gf_list_last(info->tcis);
if (!tkc) return;
if (tkc->nb_keys) {
tkc->keys = (GF_CryptKeyInfo *)gf_realloc(tkc->keys, sizeof(GF_CryptKeyInfo)*(tkc->nb_keys+1));
memset(&tkc->keys[tkc->nb_keys], 0, sizeof(GF_CryptKeyInfo));
}
IV_size = tkc->keys[0].IV_size;
const_IV_size = tkc->keys[0].constant_IV_size;
for (i=0; i<nb_attributes; i++) {
att = (GF_XMLAttribute *) &attributes[i];
if (!stricmp(att->name, "KID")) {
GF_Err e = gf_bin128_parse(att->value, tkc->keys[tkc->nb_keys].KID);
if (e != GF_OK) {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[CENC] Cannnot parse KID\n"));
return;
}
}
else if (!stricmp(att->name, "value")) {
GF_Err e = gf_bin128_parse(att->value, tkc->keys[tkc->nb_keys].key);
if (e != GF_OK) {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[CENC] Cannnot parse key value\n"));
return;
}
}
else if (!stricmp(att->name, "hlsInfo")) {
if (!strstr(att->value, "URI=\"")) {
GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[CENC] Missing URI in HLS info %s\n", att->value));
return;
}
tkc->keys[tkc->nb_keys].hls_info = gf_strdup(att->value);
}
else if (!stricmp(att->name, "IV_size")) {
IV_size = atoi(att->value);
}
else if (!stricmp(att->name, "constant_IV")) {
char *sKey = att->value;
if (!strnicmp(sKey, "0x", 2)) sKey += 2;
if ((strlen(sKey) == 16) || (strlen(sKey) == 32)) {
u32 j;
for (j=0; j<strlen(sKey); j+=2) {
u32 v;
char szV[5];
sprintf(szV, "%c%c", sKey[j], sKey[j+1]);
sscanf(szV, "%x", &v);
tkc->keys[tkc->nb_keys].IV[j/2] = v;
}
const_IV_size = (u8) strlen(sKey) / 2;
kas_civ = GF_TRUE;
}
}
}
tkc->keys[tkc->nb_keys].IV_size = IV_size;
tkc->keys[tkc->nb_keys].constant_IV_size = const_IV_size;
if (!kas_civ && tkc->nb_keys)
memcpy(tkc->keys[tkc->nb_keys].IV, tkc->keys[0].IV, 16);
tkc->nb_keys++;
}
}

uint64_t
vi_pci_read(UNUSED int vcpu, struct pci_devinst *pi, int baridx,
uint64_t offset, int size)
{
struct virtio_softc *vs = pi->pi_arg;
struct virtio_consts *vc;
struct config_reg *cr;
uint64_t virtio_config_size, max;
const char *name;
uint32_t newoff;
uint32_t value;
int error;
if (vs->vs_flags & VIRTIO_USE_MSIX) {
if (baridx == pci_msix_table_bar(pi) ||
baridx == pci_msix_pba_bar(pi)) {
return (pci_emul_msix_tread(pi, offset, size));
}
}
assert(baridx == 0);
if (vs->vs_mtx)
pthread_mutex_lock(vs->vs_mtx);
vc = vs->vs_vc;
name = vc->vc_name;
value = size == 1 ? 0xff : size == 2 ? 0xffff : 0xffffffff;
if (size != 1 && size != 2 && size != 4)
goto bad;
if (pci_msix_enabled(pi))
virtio_config_size = VTCFG_R_CFG1;
else
virtio_config_size = VTCFG_R_CFG0;
if (offset >= virtio_config_size) {
newoff = (uint32_t) (offset - virtio_config_size);
max = vc->vc_cfgsize ? vc->vc_cfgsize : 0x100000000;
if ((newoff + ((unsigned) size)) > max)
goto bad;
error = (*vc->vc_cfgread)(DEV_SOFTC(vs), ((int) newoff), size, &value);
if (!error)
goto done;
}
bad:
cr = vi_find_cr((int) offset);
if (cr == NULL || cr->cr_size != size) {
if (cr != NULL) {
fprintf(stderr,
"%s: read from %s: bad size %d\r\n",
name, cr->cr_name, size);
} else {
fprintf(stderr,
"%s: read from bad offset/size %jd/%d\r\n",
name, (uintmax_t)offset, size);
}
goto done;
}
switch (offset) {
case VTCFG_R_HOSTCAP:
value = (uint32_t) vc->vc_hv_caps;
break;
case VTCFG_R_GUESTCAP:
value = vs->vs_negotiated_caps;
break;
case VTCFG_R_PFN:
if (vs->vs_curq < vc->vc_nvq)
value = vs->vs_queues[vs->vs_curq].vq_pfn;
break;
case VTCFG_R_QNUM:
value = vs->vs_curq < vc->vc_nvq ?
vs->vs_queues[vs->vs_curq].vq_qsize : 0;
break;
case VTCFG_R_QSEL:
value = (uint32_t) (vs->vs_curq);
break;
case VTCFG_R_QNOTIFY:
value = 0;
break;
case VTCFG_R_STATUS:
value = vs->vs_status;
break;
case VTCFG_R_ISR:
value = vs->vs_isr;
vs->vs_isr = 0;
if (value)
pci_lintr_deassert(pi);
break;
case VTCFG_R_CFGVEC:
value = vs->vs_msix_cfg_idx;
break;
case VTCFG_R_QVEC:
value = vs->vs_curq < vc->vc_nvq ?
vs->vs_queues[vs->vs_curq].vq_msix_idx :
VIRTIO_MSI_NO_VECTOR;
break;
}
done:
if (vs->vs_mtx)
pthread_mutex_unlock(vs->vs_mtx);
return (value);
}

GF_Err BM_ParseCommand(GF_BifsDecoder *codec, GF_BitStream *bs, GF_List *com_list)
{
u8 go, type;
GF_Err e;
go = 1;
e = GF_OK;
GF_SceneGraph *cur_graph = codec->current_graph;
GF_Proto *cur_proto = codec->pCurrentProto;
codec->LastError = GF_OK;
while (go) {
type = gf_bs_read_int(bs, 2);
switch (type) {
case 0:
e = BM_ParseInsert(codec, bs, com_list);
break;
case 1:
e = BM_ParseDelete(codec, bs, com_list);
break;
case 2:
e = BM_ParseReplace(codec, bs, com_list);
break;
case 3:
e = BM_SceneReplace(codec, bs, com_list);
break;
}
if (e) break;
go = gf_bs_read_int(bs, 1);
}
while (gf_list_count(codec->QPs)) {
gf_bifs_dec_qp_remove(codec, GF_TRUE);
}
codec->current_graph = cur_graph;
codec->pCurrentProto = cur_proto;
return e;
}

void *malloc(size_t size)
{
struct free_arena_header *fp;
struct free_arena_header *pah;
size_t fsize;
if (size == 0)
return NULL;
size = (size + 2 * sizeof(struct arena_header) - 1) & ARENA_SIZE_MASK;
for (fp = __malloc_head.next_free; fp->a.type != ARENA_TYPE_HEAD;
fp = fp->next_free) {
if (fp->a.size >= size) {
return __malloc_from_block(fp, size);
}
}
fsize = (size + MALLOC_CHUNK_MASK) & ~MALLOC_CHUNK_MASK;
#if _KLIBC_MALLOC_USES_SBRK
fp = (struct free_arena_header *)sbrk(fsize);
#else
fp = (struct free_arena_header *)
mmap(NULL, fsize, PROT_READ | PROT_WRITE,
MAP_PRIVATE | MAP_ANONYMOUS, 0, 0);
#endif
if (fp == (struct free_arena_header *)MAP_FAILED) {
errno = ENOMEM;
return NULL;
}
fp->a.type = ARENA_TYPE_FREE;
fp->a.size = fsize;
for (pah = __malloc_head.a.prev; pah->a.type != ARENA_TYPE_HEAD;
pah = pah->a.prev) {
if (pah < fp)
break;
}
fp->a.next = pah->a.next;
fp->a.prev = pah;
pah->a.next = fp;
fp->a.next->a.prev = fp;
fp = __free_block(fp);
return __malloc_from_block(fp, size);
}

void ModifiablePixelBuffer::fillRect(const Rect& r, const void* pix)
{
int stride;
U8 *buf;
int w, h, b;
w = r.width();
h = r.height();
b = format.bpp/8;
if (h == 0)
return;
buf = getBufferRW(r, &stride);
if (b == 1) {
while (h--) {
memset(buf, *(const U8*)pix, w);
buf += stride * b;
}
} else {
U8 *start;
int w1;
start = buf;
w1 = w;
while (w1--) {
memcpy(buf, pix, b);
buf += b;
}
buf += (stride - w) * b;
h--;
while (h--) {
memcpy(buf, start, w * b);
buf += stride * b;
}
}
commitBufferRW(r);
}

static int redisLibevAttach(EV_P_ redisAsyncContext *ac) {
redisContext *c = &(ac->c);
redisLibevEvents *e;
if (ac->ev.data != NULL)
return REDIS_ERR;
e = (redisLibevEvents*)malloc(sizeof(*e));
e->context = ac;
#if EV_MULTIPLICITY
e->loop = loop;
#else
e->loop = NULL;
#endif
e->reading = e->writing = 0;
e->rev.data = e;
e->wev.data = e;
ac->ev.addRead = redisLibevAddRead;
ac->ev.delRead = redisLibevDelRead;
ac->ev.addWrite = redisLibevAddWrite;
ac->ev.delWrite = redisLibevDelWrite;
ac->ev.cleanup = redisLibevCleanup;
ac->ev.data = e;
ev_io_init(&e->rev,redisLibevReadEvent,c->fd,EV_READ);
ev_io_init(&e->wev,redisLibevWriteEvent,c->fd,EV_WRITE);
return REDIS_OK;
}

static int
grub_ext2_iterate_dir (grub_fshelp_node_t dir,
grub_fshelp_iterate_dir_hook_t hook, void *hook_data)
{
unsigned int fpos = 0;
struct grub_fshelp_node *diro = (struct grub_fshelp_node *) dir;
if (! diro->inode_read)
{
grub_ext2_read_inode (diro->data, diro->ino, &diro->inode);
if (grub_errno)
return 0;
}
while (fpos < grub_le_to_cpu32 (diro->inode.size))
{
struct ext2_dirent dirent;
grub_ext2_read_file (diro, 0, 0, fpos, sizeof (struct ext2_dirent),
(char *) &dirent);
if (grub_errno)
return 0;
if (dirent.direntlen == 0)
return 0;
if (dirent.inode != 0 && dirent.namelen != 0)
{
char filename[dirent.namelen + 1];
struct grub_fshelp_node *fdiro;
enum grub_fshelp_filetype type = GRUB_FSHELP_UNKNOWN;
grub_ext2_read_file (diro, 0, 0, fpos + sizeof (struct ext2_dirent),
dirent.namelen, filename);
if (grub_errno)
return 0;
fdiro = grub_malloc (sizeof (struct grub_fshelp_node));
if (! fdiro)
return 0;
fdiro->data = diro->data;
fdiro->ino = grub_le_to_cpu32 (dirent.inode);
filename[dirent.namelen] = '\0';
if (dirent.filetype != FILETYPE_UNKNOWN)
{
fdiro->inode_read = 0;
if (dirent.filetype == FILETYPE_DIRECTORY)
type = GRUB_FSHELP_DIR;
else if (dirent.filetype == FILETYPE_SYMLINK)
type = GRUB_FSHELP_SYMLINK;
else if (dirent.filetype == FILETYPE_REG)
type = GRUB_FSHELP_REG;
}
else
{
grub_ext2_read_inode (diro->data,
grub_le_to_cpu32 (dirent.inode),
&fdiro->inode);
if (grub_errno)
{
grub_free (fdiro);
return 0;
}
fdiro->inode_read = 1;
if ((grub_le_to_cpu16 (fdiro->inode.mode)
& FILETYPE_INO_MASK) == FILETYPE_INO_DIRECTORY)
type = GRUB_FSHELP_DIR;
else if ((grub_le_to_cpu16 (fdiro->inode.mode)
& FILETYPE_INO_MASK) == FILETYPE_INO_SYMLINK)
type = GRUB_FSHELP_SYMLINK;
else if ((grub_le_to_cpu16 (fdiro->inode.mode)
& FILETYPE_INO_MASK) == FILETYPE_INO_REG)
type = GRUB_FSHELP_REG;
}
if (hook (filename, type, fdiro, hook_data))
return 1;
}
fpos += grub_le_to_cpu16 (dirent.direntlen);
}
return 0;
}

static s32 naludmx_parse_nal_hevc(GF_NALUDmxCtx *ctx, char *data, u32 size, Bool *skip_nal, Bool *is_slice, Bool *is_islice)
{
#ifdef GPAC_DISABLE_HEVC
return -1;
#else
s32 ps_idx = 0;
s32 res;
u8 nal_unit_type, temporal_id, layer_id;
*skip_nal = GF_FALSE;
if (size<2) return -1;
gf_bs_reassign_buffer(ctx->bs_r, data, size);
res = gf_hevc_parse_nalu_bs(ctx->bs_r, ctx->hevc_state, &nal_unit_type, &temporal_id, &layer_id);
ctx->nb_nalus++;
if (res < 0) {
if (res == -1) {
GF_LOG(GF_LOG_ERROR, GF_LOG_MEDIA, ("[%s] Warning: Error parsing NAL unit\n", ctx->log_name));
}
*skip_nal = GF_TRUE;
}
if (layer_id && ctx->nosvc) {
*skip_nal = GF_TRUE;
return 0;
}
switch (nal_unit_type) {
case GF_HEVC_NALU_VID_PARAM:
if (ctx->novpsext) {
ps_idx = gf_hevc_read_vps_ex(data, &size, ctx->hevc_state, GF_TRUE);
} else {
ps_idx = ctx->hevc_state->last_parsed_vps_id;
}
if (ps_idx<0) {
GF_LOG(GF_LOG_ERROR, GF_LOG_MEDIA, ("[%s] Error parsing Video Param Set\n", ctx->log_name));
} else {
naludmx_queue_param_set(ctx, data, size, GF_HEVC_NALU_VID_PARAM, ps_idx, temporal_id, layer_id);
}
*skip_nal = GF_TRUE;
break;
case GF_HEVC_NALU_SEQ_PARAM:
ps_idx = ctx->hevc_state->last_parsed_sps_id;
if (ps_idx<0) {
GF_LOG(GF_LOG_ERROR, GF_LOG_MEDIA, ("[%s] Error parsing Sequence Param Set\n", ctx->log_name));
} else {
naludmx_queue_param_set(ctx, data, size, GF_HEVC_NALU_SEQ_PARAM, ps_idx, temporal_id, layer_id);
}
*skip_nal = GF_TRUE;
break;
case GF_HEVC_NALU_PIC_PARAM:
ps_idx = ctx->hevc_state->last_parsed_pps_id;
if (ps_idx<0) {
GF_LOG(GF_LOG_ERROR, GF_LOG_MEDIA, ("[%s] Error parsing Picture Param Set\n", ctx->log_name));
} else {
naludmx_queue_param_set(ctx, data, size, GF_HEVC_NALU_PIC_PARAM, ps_idx, temporal_id, layer_id);
}
*skip_nal = GF_TRUE;
break;
case GF_HEVC_NALU_SEI_PREFIX:
gf_hevc_parse_sei(data, size, ctx->hevc_state);
if (!ctx->nosei) {
ctx->nb_sei++;
naludmx_push_prefix(ctx, data, size, GF_FALSE);
} else {
ctx->nb_nalus--;
}
*skip_nal = GF_TRUE;
break;
case GF_HEVC_NALU_SEI_SUFFIX:
if (! ctx->is_playing) return 0;
if (ctx->nosei) {
*skip_nal = GF_TRUE;
ctx->nb_nalus--;
} else {
ctx->nb_sei++;
}
break;
case GF_HEVC_NALU_SLICE_STSA_N:
case GF_HEVC_NALU_SLICE_STSA_R:
case GF_HEVC_NALU_SLICE_RADL_R:
case GF_HEVC_NALU_SLICE_RASL_R:
case GF_HEVC_NALU_SLICE_RADL_N:
case GF_HEVC_NALU_SLICE_RASL_N:
case GF_HEVC_NALU_SLICE_TRAIL_N:
case GF_HEVC_NALU_SLICE_TRAIL_R:
case GF_HEVC_NALU_SLICE_TSA_N:
case GF_HEVC_NALU_SLICE_TSA_R:
case GF_HEVC_NALU_SLICE_BLA_W_LP:
case GF_HEVC_NALU_SLICE_BLA_W_DLP:
case GF_HEVC_NALU_SLICE_BLA_N_LP:
case GF_HEVC_NALU_SLICE_IDR_W_DLP:
case GF_HEVC_NALU_SLICE_IDR_N_LP:
case GF_HEVC_NALU_SLICE_CRA:
if (! ctx->is_playing) return 0;
*is_slice = GF_TRUE;
ctx->last_layer_id = layer_id;
ctx->last_temporal_id = temporal_id;
if (! *skip_nal) {
switch (ctx->hevc_state->s_info.slice_type) {
case GF_HEVC_SLICE_TYPE_P:
if (layer_id) ctx->nb_e_p++;
else ctx->nb_p++;
break;
case GF_HEVC_SLICE_TYPE_I:
if (layer_id) ctx->nb_e_i++;
else ctx->nb_i++;
*is_islice = GF_TRUE;
break;
case GF_HEVC_SLICE_TYPE_B:
if (layer_id) ctx->nb_e_b++;
else ctx->nb_b++;
break;
}
}
break;
case GF_HEVC_NALU_ACCESS_UNIT:
ctx->nb_aud++;
if (!ctx->audelim) {
*skip_nal = GF_TRUE;
} else if (!ctx->opid) {
ctx->has_initial_aud = GF_TRUE;
memcpy(ctx->init_aud, data, 3);
}
break;
case GF_HEVC_NALU_FILLER_DATA:
case GF_HEVC_NALU_END_OF_SEQ:
case GF_HEVC_NALU_END_OF_STREAM:
*skip_nal = GF_TRUE;
break;
case GF_HEVC_NALU_DV_RPU:
if (ctx->dv_mode==DVMODE_CLEAN) {
*skip_nal = GF_TRUE;
} else {
ctx->nb_dv_rpu ++;
if (ctx->nb_dv_rpu==1)
naludmx_set_dolby_vision(ctx);
}
break;
case GF_HEVC_NALU_DV_EL:
if ((ctx->dv_mode==DVMODE_CLEAN) || (ctx->dv_mode==DVMODE_SINGLE)) {
*skip_nal = GF_TRUE;
} else {
ctx->nb_dv_el ++;
if (ctx->nb_dv_el==1)
naludmx_set_dolby_vision(ctx);
}
break;
default:
if (! ctx->is_playing) return 0;
GF_LOG(GF_LOG_WARNING, GF_LOG_MEDIA, ("[%s] NAL Unit type %d not handled - adding\n", ctx->log_name, nal_unit_type));
break;
}
if (*skip_nal) return res;
ctx->linf[layer_id].layer_id_plus_one = layer_id + 1;
if (! ctx->linf[layer_id].max_temporal_id ) ctx->linf[layer_id].max_temporal_id = temporal_id;
else if (ctx->linf[layer_id].max_temporal_id < temporal_id) ctx->linf[layer_id].max_temporal_id = temporal_id;
if (! ctx->linf[layer_id].min_temporal_id ) ctx->linf[layer_id].min_temporal_id = temporal_id;
else if (ctx->linf[layer_id].min_temporal_id > temporal_id) ctx->linf[layer_id].min_temporal_id = temporal_id;
if (ctx->max_temporal_id[layer_id] < temporal_id)
ctx->max_temporal_id[layer_id] = temporal_id;
if (ctx->min_layer_id > layer_id) ctx->min_layer_id = layer_id;
return res;
#endif }

static int
dissect_geonw(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void *data _U_)
{
guint8 bh_next_header;
guint32 ch_next_header;
guint32 header_type;
guint32 rhl;
guint32 tmp_val;
gint offset = 0;
proto_item *ti;
proto_item *top_item;
gint hdr_len = 0;
guint32 payload_len = 0;
guint32 reserved;
guint32 timestamp;
guint32 sequence_number = SN_MAX + 1;
struct geonwheader *geonwh;
gint32 latlon;
geonwh = wmem_new0(pinfo->pool, struct geonwheader);
col_set_str(pinfo->cinfo, COL_PROTOCOL, "GEONW");
col_clear(pinfo->cinfo,COL_INFO);
bh_next_header = tvb_get_guint8(tvb, 0) & 0x0f;
header_type = tvb_get_guint8(tvb, 5);
if (bh_next_header == BH_NH_SECURED_PKT) {
hdr_len = BH_LEN;
}
else {
hdr_len = BH_LEN + CH_LEN;
switch(header_type & HT_MASK) {
case HT_BEACON:
hdr_len += BEACON_LEN;
break;
case HT_GEOUNICAST:
hdr_len += GUC_LEN;
break;
case HT_GEOANYCAST:
hdr_len += GAC_LEN;
break;
case HT_GEOBROADCAST:
hdr_len += GBC_LEN;
break;
case HT_TSB:
hdr_len += TSB_LEN;
break;
case HT_LS:
hdr_len += LS_REQUEST_LEN;
if (header_type == HTST_LS_REPLY) {
hdr_len += (LS_REPLY_LEN - LS_REQUEST_LEN);
}
break;
default:
hdr_len = -1;
}
}
top_item = proto_tree_add_item(tree, proto_geonw, tvb, 0, hdr_len, ENC_NA);
proto_tree *geonw_tree = proto_item_add_subtree(top_item, ett_geonw);
ti = proto_tree_add_item(geonw_tree, hf_geonw_bh, tvb, 0, 4, ENC_NA);
proto_tree *geonw_bh_tree = proto_item_add_subtree(ti, ett_geonw_bh);
ti = proto_tree_add_item_ret_uint(geonw_bh_tree, hf_geonw_bh_version, tvb, offset, 1, ENC_BIG_ENDIAN, &tmp_val);
geonwh->gnw_ver = tmp_val;
if (tmp_val > 1) {
col_add_fstr(pinfo->cinfo, COL_INFO,
"Bogus GeoNetworking version (%u, must be less than 2)", tmp_val);
expert_add_info_format(pinfo, ti, &ei_geonw_version_err, "Bogus GeoNetworking version");
return tvb_captured_length(tvb);
}
proto_tree_add_item(geonw_bh_tree, hf_geonw_bh_next_header, tvb, offset, 1, ENC_BIG_ENDIAN);
offset += 1;
ti = proto_tree_add_item_ret_uint(geonw_bh_tree, hf_geonw_bh_reserved, tvb, offset, 1, ENC_NA, &reserved);
if (reserved) {
expert_add_info(pinfo, ti, &ei_geonw_nz_reserved);
}
offset += 1;
ti = proto_tree_add_item_ret_uint(geonw_bh_tree, hf_geonw_bh_life_time, tvb, offset, 1, ENC_BIG_ENDIAN, &tmp_val);
geonwh->gnw_lt = tmp_val;
proto_tree *geonw_bh_lt_tree = proto_item_add_subtree(ti, ett_geonw_bh_lt);
proto_tree_add_item(geonw_bh_lt_tree, hf_geonw_bh_lt_mult, tvb, offset, 1, ENC_BIG_ENDIAN);
proto_tree_add_item(geonw_bh_lt_tree, hf_geonw_bh_lt_base, tvb, offset, 1, ENC_BIG_ENDIAN);
offset += 1;
proto_item *rhl_ti = proto_tree_add_item_ret_uint(geonw_bh_tree, hf_geonw_bh_remain_hop_limit, tvb, offset, 1, ENC_BIG_ENDIAN, &rhl);
geonwh->gnw_rhl = rhl;
if (rhl < 5 && bh_next_header != BH_NH_COMMON_HDR) {
expert_add_info_format(pinfo, rhl_ti, &ei_geonw_rhl_too_low, "\"Remain Hop Limit\" only %u", rhl);
}
offset += 1;
if (bh_next_header == BH_NH_SECURED_PKT) {
dissect_secured_message(tvb, offset, pinfo, geonw_tree, NULL);
tvbuff_t *next_tvb = (tvbuff_t*)p_get_proto_data(wmem_file_scope(), pinfo, proto_geonw, 0);
if (next_tvb) {
tvb = next_tvb;
bh_next_header = BH_NH_COMMON_HDR;
offset = 0;
header_type = tvb_get_guint8(tvb, 1);
hdr_len = CH_LEN;
switch(header_type & HT_MASK) {
case HT_BEACON:
hdr_len += BEACON_LEN;
break;
case HT_GEOUNICAST:
hdr_len += GUC_LEN;
break;
case HT_GEOANYCAST:
hdr_len += GAC_LEN;
break;
case HT_GEOBROADCAST:
hdr_len += GBC_LEN;
break;
case HT_TSB:
hdr_len += TSB_LEN;
break;
case HT_LS:
hdr_len += LS_REQUEST_LEN;
if (header_type == HTST_LS_REPLY) {
hdr_len += (LS_REPLY_LEN - LS_REQUEST_LEN);
}
break;
default:
hdr_len = -1;
}
p_add_proto_data(wmem_file_scope(), pinfo, proto_geonw, 0, NULL);
}
}
if (bh_next_header == BH_NH_COMMON_HDR) {
ti = proto_tree_add_item(geonw_tree, hf_geonw_ch, tvb, offset, 8, ENC_NA);
proto_tree *geonw_ch_tree = proto_item_add_subtree(ti, ett_geonw_ch);
proto_tree_add_item_ret_uint(geonw_ch_tree, hf_geonw_ch_next_header, tvb, offset, 1, ENC_BIG_ENDIAN, &ch_next_header);
geonwh->gnw_proto = ch_next_header;
ti = proto_tree_add_item_ret_uint(geonw_ch_tree, hf_geonw_ch_reserved1, tvb, offset, 1, ENC_NA, &reserved);
if (reserved) {
expert_add_info(pinfo, ti, &ei_geonw_nz_reserved);
}
offset += 1;
proto_tree_add_item_ret_uint(geonw_ch_tree, hf_geonw_ch_header_type, tvb, offset, 1, ENC_BIG_ENDIAN, &header_type);
geonwh->gnw_htype = header_type;
col_add_str(pinfo->cinfo, COL_INFO, val_to_str(header_type, ch_header_type_names, "Unknown (%u)"));
offset += 1;
if (header_type == HTST_BEACON || header_type == HTST_TSB_SINGLE) {
if (rhl > 1) {
expert_add_info_format(pinfo, rhl_ti, &ei_geonw_rhl_lncb, "\"Remain Hop Limit\" != 1 for BEACON or SHB (%u)", rhl);
}
} else if (rhl < 5) {
expert_add_info_format(pinfo, rhl_ti, &ei_geonw_rhl_too_low, "\"Remain Hop Limit\" only %u", rhl);
}
ti = proto_tree_add_item_ret_uint(geonw_ch_tree, hf_geonw_ch_traffic_class, tvb, offset, 1, ENC_BIG_ENDIAN, &tmp_val);
geonwh->gnw_tc = tmp_val;
proto_tree *geonw_ch_tc_tree = proto_item_add_subtree(ti, ett_geonw_ch_tc);
proto_tree_add_item(geonw_ch_tc_tree, hf_geonw_ch_tc_scf, tvb, offset, 1, ENC_BIG_ENDIAN);
proto_tree_add_item(geonw_ch_tc_tree, hf_geonw_ch_tc_offload, tvb, offset, 1, ENC_BIG_ENDIAN);
proto_tree_add_item(geonw_ch_tc_tree, hf_geonw_ch_tc_id, tvb, offset, 1, ENC_BIG_ENDIAN);
offset += 1;
ti = proto_tree_add_item(geonw_ch_tree, hf_geonw_ch_flags, tvb, offset, 1, ENC_NA);
proto_tree *geonw_ch_flag_tree = proto_item_add_subtree(ti, ett_geonw_ch_tc);
proto_tree_add_item_ret_uint(geonw_ch_flag_tree, hf_geonw_ch_flags_mob, tvb, offset, 1, ENC_BIG_ENDIAN, &tmp_val);
geonwh->gnw_flags = tmp_val;
ti = proto_tree_add_item_ret_uint(geonw_ch_flag_tree, hf_geonw_ch_flags_reserved, tvb, offset, 1, ENC_BIG_ENDIAN, &reserved);
if (reserved & 0x7f) {
expert_add_info(pinfo, ti, &ei_geonw_nz_reserved);
}
offset += 1;
ti = proto_tree_add_item_ret_uint(geonw_ch_tree, hf_geonw_ch_payload_length, tvb, offset, 2, ENC_BIG_ENDIAN, &payload_len);
geonwh->gnw_len = payload_len;
if (hdr_len > 0) {             if (payload_len) {
if (((header_type & HT_MASK) == HT_LS) || (header_type == HT_BEACON)) {
expert_add_info(pinfo, ti, &ei_geonw_nz_reserved);
}
else if ((payload_len + (unsigned) hdr_len) > tvb_reported_length(tvb)) {
expert_add_info(pinfo, ti, &ei_geonw_payload_len);
}
else {
set_actual_length(tvb, hdr_len + payload_len);
}
}
else {
set_actual_length(tvb, hdr_len);
}
}
offset += 2;
proto_tree_add_item_ret_uint(geonw_ch_tree, hf_geonw_ch_max_hop_limit, tvb, offset, 1, ENC_BIG_ENDIAN, &tmp_val);
geonwh->gnw_mhl = tmp_val;
if (tmp_val < rhl) {
expert_add_info_format(pinfo, rhl_ti, &ei_geonw_mhl_lt_rhl, "Ignored: \"Remain Hop Limit\" > %u (mhl)", tmp_val);
}
offset += 1;
ti = proto_tree_add_item_ret_uint(geonw_ch_tree, hf_geonw_ch_reserved2, tvb, offset, 1, ENC_NA, &reserved);
if (reserved) {
expert_add_info(pinfo, ti, &ei_geonw_nz_reserved);
}
offset += 1;
if (!IS_HT_KNOWN(header_type)) {
proto_item_set_end(top_item, tvb, offset);
return tvb_reported_length(tvb);
}
geonwh->gnw_sn = SN_MAX+1;
proto_tree *geonw_sh_tree;
switch(header_type & HT_MASK) {
case HT_BEACON:
ti = proto_tree_add_item(geonw_tree, hf_geonw_beacon, tvb, offset, hdr_len-offset, ENC_NA);
break;
case HT_GEOUNICAST:
ti = proto_tree_add_item(geonw_tree, hf_geonw_guc, tvb, offset, hdr_len-offset, ENC_NA);
break;
case HT_GEOANYCAST:
ti = proto_tree_add_item(geonw_tree, hf_geonw_gac, tvb, offset, hdr_len-offset, ENC_NA);
break;
case HT_GEOBROADCAST:
ti = proto_tree_add_item(geonw_tree, hf_geonw_gbc, tvb, offset, hdr_len-offset, ENC_NA);
break;
case HT_TSB:
ti = proto_tree_add_item(geonw_tree, hf_geonw_tsb, tvb, offset, hdr_len-offset, ENC_NA);
break;
case HT_LS:
ti = proto_tree_add_item(geonw_tree, hf_geonw_ls, tvb, offset, hdr_len-offset, ENC_NA);
break;
default:
return tvb_captured_length(tvb);
}
geonw_sh_tree = proto_item_add_subtree(ti, ett_geonw_sh);
switch(header_type) {
case HTST_GEOUNICAST:
case HTST_GAC_CIRCLE:
case HTST_GAC_RECT:
case HTST_GAC_ELLIPSE:
case HTST_GBC_CIRCLE:
case HTST_GBC_RECT:
case HTST_GBC_ELLIPSE:
case HTST_TSB_MULT:
case HTST_LS_REQUEST:
case HTST_LS_REPLY:
proto_tree_add_item_ret_uint(geonw_sh_tree, hf_geonw_seq_num, tvb, offset, 2, ENC_BIG_ENDIAN, &sequence_number);
geonwh->gnw_sn = sequence_number;
offset += 2;
ti = proto_tree_add_item_ret_uint(geonw_sh_tree, hf_geonw_reserved, tvb, offset, 2, ENC_BIG_ENDIAN, &reserved);
if (reserved) {
expert_add_info(pinfo, ti, &ei_geonw_nz_reserved);
}
offset += 2;
case HTST_TSB_SINGLE:
case HTST_BEACON:
break;
}
ti = proto_tree_add_item(geonw_sh_tree, hf_geonw_so_pv, tvb, offset, 24, ENC_NA);
proto_tree *geonw_so_tree = proto_item_add_subtree(ti, ett_geonw_so);
ti = proto_tree_add_item(geonw_so_tree, hf_geonw_so_pv_addr, tvb, offset, 8, ENC_NA);
proto_tree *geonw_so_add_tree = proto_item_add_subtree(ti, ett_geonw_so);
set_address_tvb(&pinfo->net_src, geonw_address_type, 8, tvb, offset);
copy_address_shallow(&pinfo->src, &pinfo->net_src);
copy_address_shallow(&geonwh->gnw_src, &pinfo->src);
proto_tree_add_item(geonw_so_add_tree, hf_geonw_so_pv_addr_manual, tvb, offset, 1, ENC_BIG_ENDIAN);
proto_tree_add_item(geonw_so_add_tree, hf_geonw_so_pv_addr_type, tvb, offset, 1, ENC_BIG_ENDIAN);
ti = proto_tree_add_item_ret_uint(geonw_so_add_tree, hf_geonw_so_pv_addr_country, tvb, offset, 2, ENC_BIG_ENDIAN, &reserved);
if (reserved > 999) {
expert_add_info(pinfo, ti, &ei_geonw_scc_too_big);
}
offset += 2;
proto_tree_add_item(geonw_so_add_tree, hf_geonw_so_pv_addr_mid, tvb, offset, 6, ENC_NA);
offset += 6;
proto_tree_add_item_ret_uint(geonw_so_tree, hf_geonw_so_pv_time, tvb, offset, 4, ENC_BIG_ENDIAN, &timestamp);
geonwh->gnw_tst = timestamp;
if(geonw_analyze_seq && (geonwh->gnw_ver==0) && !(pinfo->fd->visited)) {
hashgeonw_t *tp = (hashgeonw_t *)wmem_map_lookup(geonw_hashtable, pinfo->net_src.data);
if (tp == NULL) {
tp = geonw_hash_new_entry((const guint8 *)pinfo->net_src.data, FALSE);
tp->sequence_number = sequence_number;
tp->timestamp = timestamp;
} else {
if ((sequence_number <= SN_MAX) && (tp->sequence_number > SN_MAX)) {
tp->sequence_number = sequence_number;
tp->timestamp = timestamp;
}
else if (sequence_number <= SN_MAX) {
if (((timestamp > tp->timestamp) && (((guint64)timestamp - (guint64)tp->timestamp) <= (guint64)TST_MAX/2)) ||
((tp->timestamp > timestamp) && (((guint64)tp->timestamp - (guint64)timestamp) > (guint64)TST_MAX/2))) {
tp->sequence_number = sequence_number;
tp->timestamp = timestamp;                                      } else if (timestamp == tp->timestamp) {
if (((sequence_number > tp->sequence_number) && ((sequence_number - tp->sequence_number) <= SN_MAX/2)) ||
((tp->sequence_number > sequence_number) && ((tp->sequence_number - sequence_number) > SN_MAX/2))) {
tp->timestamp = timestamp;
tp->sequence_number = sequence_number;                          } else {
ti = proto_tree_add_item(geonw_tree, hf_geonw_analysis_flags, tvb, 0, 0, ENC_NA);
proto_item_set_generated(ti);
expert_add_info(pinfo, ti, &ei_geonw_analysis_duplicate);
col_prepend_fence_fstr(pinfo->cinfo, COL_INFO, "[Duplicate packet] ");
}
}                 }
else {
if (((timestamp > tp->timestamp) && (((guint64)timestamp - (guint64)tp->timestamp) <= (guint64)TST_MAX/2)) ||
((tp->timestamp > timestamp) && (((guint64)tp->timestamp - (guint64)timestamp) > (guint64)TST_MAX/2))) {
tp->timestamp = timestamp;                          } else {
ti = proto_tree_add_item(geonw_tree, hf_geonw_analysis_flags, tvb, 0, 0, ENC_NA);
proto_item_set_generated(ti);
expert_add_info(pinfo, ti, &ei_geonw_analysis_duplicate);
col_prepend_fence_fstr(pinfo->cinfo, COL_INFO, "[Duplicate packet] ");
}
}
}
}
offset += 4;
ti = proto_tree_add_item_ret_int(geonw_so_tree, hf_geonw_so_pv_lat, tvb, offset, 4, ENC_BIG_ENDIAN, &latlon);
if (latlon < -900000000 || latlon > 900000000) {
expert_add_info_format(pinfo, ti, &ei_geonw_out_of_range, "Latitude out of range (%f)", (float)latlon/10000000);
}
geonwh->gnw_lat = latlon;
offset += 4;
ti = proto_tree_add_item_ret_int(geonw_so_tree, hf_geonw_so_pv_lon, tvb, offset, 4, ENC_BIG_ENDIAN, &latlon);
if (latlon < -1800000000 || latlon > 1800000000) {
expert_add_info_format(pinfo, ti, &ei_geonw_out_of_range, "Longitude out of range (%f)", (float)latlon/10000000);
}
geonwh->gnw_lon = latlon;
offset += 4;
proto_tree_add_item(geonw_so_tree, hf_geonw_so_pv_pai, tvb, offset, 1, ENC_BIG_ENDIAN);
proto_tree_add_item(geonw_so_tree, hf_geonw_so_pv_speed, tvb, offset, 2, ENC_BIG_ENDIAN);
offset += 2;
ti = proto_tree_add_item_ret_uint(geonw_so_tree, hf_geonw_so_pv_heading, tvb, offset, 2, ENC_BIG_ENDIAN, &tmp_val);
if (tmp_val > 3600) {
expert_add_info_format(pinfo, ti, &ei_geonw_out_of_range, "Out of range [0..360] (%f)", (float)tmp_val/10);
}
offset += 2;
proto_tree *geonw_de_tree = NULL;
proto_tree *geonw_de_add_tree = NULL;
switch(header_type) {
case HTST_GEOUNICAST:
case HTST_LS_REPLY:
ti = proto_tree_add_item(geonw_sh_tree, hf_geonw_de_pv, tvb, offset, 20, ENC_NA);
geonw_de_tree = proto_item_add_subtree(ti, ett_geonw_de);
ti = proto_tree_add_item(geonw_de_tree, hf_geonw_de_pv_addr, tvb, offset, 8, ENC_NA);
geonw_de_add_tree = proto_item_add_subtree(ti, ett_geonw_de);
set_address_tvb(&pinfo->net_dst, geonw_address_type, 8, tvb, offset);
copy_address_shallow(&pinfo->dst, &pinfo->net_dst);
copy_address_shallow(&geonwh->gnw_dst, &pinfo->dst);
if (header_type == HTST_LS_REPLY) {
transaction_end(pinfo, geonw_tree);
}
proto_tree_add_item(geonw_de_add_tree, hf_geonw_de_pv_addr_manual, tvb, offset, 1, ENC_BIG_ENDIAN);
proto_tree_add_item(geonw_de_add_tree, hf_geonw_de_pv_addr_type, tvb, offset, 1, ENC_BIG_ENDIAN);
ti = proto_tree_add_item_ret_uint(geonw_de_add_tree, hf_geonw_de_pv_addr_country, tvb, offset, 2, ENC_BIG_ENDIAN, &reserved);
if (reserved > 999) {
expert_add_info(pinfo, ti, &ei_geonw_scc_too_big);
}
offset += 2;
proto_tree_add_item(geonw_de_add_tree, hf_geonw_de_pv_addr_mid, tvb, offset, 6, ENC_NA);
offset += 6;
proto_tree_add_item(geonw_de_tree, hf_geonw_de_pv_time, tvb, offset, 4, ENC_BIG_ENDIAN);
offset += 4;
ti = proto_tree_add_item_ret_int(geonw_de_tree, hf_geonw_de_pv_lat, tvb, offset, 4, ENC_BIG_ENDIAN, &latlon);
if (latlon < -900000000 || latlon > 900000000) {
expert_add_info_format(pinfo, ti, &ei_geonw_out_of_range, "Latitude out of range (%f)", (float)latlon/10000000);
}
offset += 4;
ti = proto_tree_add_item_ret_int(geonw_de_tree, hf_geonw_de_pv_lon, tvb, offset, 4, ENC_BIG_ENDIAN, &latlon);
if (latlon < -1800000000 || latlon > 1800000000) {
expert_add_info_format(pinfo, ti, &ei_geonw_out_of_range, "Longitude out of range (%f)", (float)latlon/10000000);
}
offset += 4;
break;
case HTST_TSB_SINGLE:
reserved = tvb_get_guint32(tvb, offset, ENC_BIG_ENDIAN);
if (reserved) {
ti = proto_tree_add_item(geonw_sh_tree, hf_geonw_dccmco, tvb, offset, 4, ENC_NA);
proto_tree *dccmco = proto_item_add_subtree(ti, ett_geonw_dccmco);
proto_tree_add_item(dccmco, hf_geonw_dccmco_cbr_l_0_hop, tvb, offset, 1, ENC_BIG_ENDIAN);
proto_tree_add_item(dccmco, hf_geonw_dccmco_cbr_l_1_hop, tvb, offset+1, 1, ENC_BIG_ENDIAN);
proto_tree_add_item(dccmco, hf_geonw_dccmco_output_power, tvb, offset+2, 1, ENC_BIG_ENDIAN);
proto_tree_add_item(dccmco, hf_geonw_dccmco_reserved, tvb, offset+2, 1, ENC_BIG_ENDIAN);
proto_tree_add_item(dccmco, hf_geonw_shb_reserved, tvb, offset+3, 1, ENC_BIG_ENDIAN);
}
else {
proto_tree_add_item(geonw_sh_tree, hf_geonw_shb_reserved, tvb, offset, 4, ENC_BIG_ENDIAN);
}
offset += 4;
break;
case HTST_GAC_CIRCLE:
case HTST_GAC_RECT:
case HTST_GAC_ELLIPSE:
case HTST_GBC_CIRCLE:
case HTST_GBC_RECT:
case HTST_GBC_ELLIPSE:
ti = proto_tree_add_item_ret_int(geonw_sh_tree, hf_geonw_gxc_latitude, tvb, offset, 4, ENC_BIG_ENDIAN, &latlon);
if (latlon < -900000000 || latlon > 900000000) {
expert_add_info_format(pinfo, ti, &ei_geonw_out_of_range, "Latitude out of range (%f)", (float)latlon/10000000);
}
offset += 4;
ti = proto_tree_add_item_ret_int(geonw_sh_tree, hf_geonw_gxc_longitude, tvb, offset, 4, ENC_BIG_ENDIAN, &latlon);
if (latlon < -1800000000 || latlon > 1800000000) {
expert_add_info_format(pinfo, ti, &ei_geonw_out_of_range, "Longitude out of range (%f)", (float)latlon/10000000);
}
offset += 4;
switch(header_type&0x0f) {
case HST_CIRCULAR:
proto_tree_add_item(geonw_sh_tree, hf_geonw_gxc_radius, tvb, offset, 2, ENC_BIG_ENDIAN);
offset += 2;
ti = proto_tree_add_item_ret_uint(geonw_sh_tree, hf_geonw_gxc_distanceb, tvb, offset, 2, ENC_BIG_ENDIAN, &reserved);
if (reserved) {
expert_add_info(pinfo, ti, &ei_geonw_nz_reserved);
}
offset += 2;
ti = proto_tree_add_item_ret_uint(geonw_sh_tree, hf_geonw_gxc_angle, tvb, offset, 2, ENC_BIG_ENDIAN, &reserved);
if (reserved) {
expert_add_info(pinfo, ti, &ei_geonw_nz_reserved);
}
offset += 2;
break;
case HST_RECTANGULAR:
case HST_ELLIPSOIDAL:
proto_tree_add_item(geonw_sh_tree, hf_geonw_gxc_distancea, tvb, offset, 2, ENC_BIG_ENDIAN);
offset += 2;
proto_tree_add_item(geonw_sh_tree, hf_geonw_gxc_distanceb, tvb, offset, 2, ENC_BIG_ENDIAN);
offset += 2;
ti = proto_tree_add_item_ret_uint(geonw_sh_tree, hf_geonw_gxc_angle, tvb, offset, 2, ENC_BIG_ENDIAN, &tmp_val);
if (tmp_val > 360) {
expert_add_info_format(pinfo, ti, &ei_geonw_out_of_range, "Out of range [0..360] (%f)", (float)tmp_val);
}
offset += 2;
}
ti = proto_tree_add_item_ret_uint(geonw_sh_tree, hf_geonw_gxc_reserved, tvb, offset, 2, ENC_BIG_ENDIAN, &reserved);
if (reserved) {
expert_add_info(pinfo, ti, &ei_geonw_nz_reserved);
}
offset += 2;
break;
case HTST_LS_REQUEST:
ti = proto_tree_add_item(geonw_sh_tree, hf_geonw_lsrq_addr, tvb, offset, 8, ENC_NA);
geonw_de_add_tree = proto_item_add_subtree(ti, ett_geonw_lsrq_add);
set_address_tvb(&pinfo->net_dst, geonw_address_type, 8, tvb, offset);
copy_address_shallow(&pinfo->dst, &pinfo->net_dst);
proto_tree_add_item(geonw_de_add_tree, hf_geonw_lsrq_addr_manual, tvb, offset, 1, ENC_BIG_ENDIAN);
proto_tree_add_item(geonw_de_add_tree, hf_geonw_lsrq_addr_type, tvb, offset, 1, ENC_BIG_ENDIAN);
ti = proto_tree_add_item_ret_uint(geonw_de_add_tree, hf_geonw_lsrq_addr_country, tvb, offset, 2, ENC_BIG_ENDIAN, &reserved);
if (reserved > 999) {
expert_add_info(pinfo, ti, &ei_geonw_scc_too_big);
}
offset += 2;
proto_tree_add_item(geonw_de_add_tree, hf_geonw_lsrq_addr_mid, tvb, offset, 6, ENC_NA);
offset += 6;
transaction_start(pinfo, geonw_tree);
break;
}
proto_item_set_end(top_item, tvb, offset);
tap_queue_packet(geonw_tap, pinfo, geonwh);
if (payload_len) {
tvbuff_t *next_tvb = tvb_new_subset_length(tvb, offset, payload_len);
switch(ch_next_header) {
case CH_NH_BTP_A:
call_dissector(btpa_handle, next_tvb, pinfo, tree);
break;
case CH_NH_BTP_B:
call_dissector(btpb_handle, next_tvb, pinfo, tree);
break;
case CH_NH_IPV6:
call_dissector(ipv6_handle, next_tvb, pinfo, tree);
break;
default:
if (!dissector_try_uint(geonw_subdissector_table, ch_next_header, next_tvb, pinfo, tree)) {
call_data_dissector(next_tvb, pinfo, tree);
}
}
}
}
return tvb_captured_length(tvb);
}

