void opj_get_all_encoding_parameters(   const opj_image_t *p_image,
const opj_cp_t *p_cp,
OPJ_UINT32 tileno,
OPJ_INT32 * p_tx0,
OPJ_INT32 * p_tx1,
OPJ_INT32 * p_ty0,
OPJ_INT32 * p_ty1,
OPJ_UINT32 * p_dx_min,
OPJ_UINT32 * p_dy_min,
OPJ_UINT32 * p_max_prec,
OPJ_UINT32 * p_max_res,
OPJ_UINT32 ** p_resolutions )
{
OPJ_UINT32 compno, resno;
const opj_tcp_t *tcp = 00;
const opj_tccp_t * l_tccp = 00;
const opj_image_comp_t * l_img_comp = 00;
OPJ_UINT32 * lResolutionPtr;
OPJ_UINT32 p, q;
assert(p_cp != 00);
assert(p_image != 00);
assert(tileno < p_cp->tw * p_cp->th);
tcp = &p_cp->tcps [tileno];
l_tccp = tcp->tccps;
l_img_comp = p_image->comps;
p = tileno % p_cp->tw;
q = tileno / p_cp->tw;
*p_tx0 = opj_int_max((OPJ_INT32)(p_cp->tx0 + p * p_cp->tdx), (OPJ_INT32)p_image->x0);
*p_tx1 = opj_int_min((OPJ_INT32)(p_cp->tx0 + (p + 1) * p_cp->tdx), (OPJ_INT32)p_image->x1);
*p_ty0 = opj_int_max((OPJ_INT32)(p_cp->ty0 + q * p_cp->tdy), (OPJ_INT32)p_image->y0);
*p_ty1 = opj_int_min((OPJ_INT32)(p_cp->ty0 + (q + 1) * p_cp->tdy), (OPJ_INT32)p_image->y1);
*p_max_prec = 0;
*p_max_res = 0;
*p_dx_min = 0x7fffffff;
*p_dy_min = 0x7fffffff;
for (compno = 0; compno < p_image->numcomps; ++compno) {
OPJ_UINT32 l_level_no;
OPJ_INT32 l_rx0, l_ry0, l_rx1, l_ry1;
OPJ_INT32 l_px0, l_py0, l_px1, py1;
OPJ_UINT32 l_product;
OPJ_INT32 l_tcx0, l_tcy0, l_tcx1, l_tcy1;
OPJ_UINT32 l_pdx, l_pdy , l_pw , l_ph;
lResolutionPtr = p_resolutions[compno];
l_tcx0 = opj_int_ceildiv(*p_tx0, (OPJ_INT32)l_img_comp->dx);
l_tcy0 = opj_int_ceildiv(*p_ty0, (OPJ_INT32)l_img_comp->dy);
l_tcx1 = opj_int_ceildiv(*p_tx1, (OPJ_INT32)l_img_comp->dx);
l_tcy1 = opj_int_ceildiv(*p_ty1, (OPJ_INT32)l_img_comp->dy);
if (l_tccp->numresolutions > *p_max_res) {
*p_max_res = l_tccp->numresolutions;
}
l_level_no = l_tccp->numresolutions - 1;
for (resno = 0; resno < l_tccp->numresolutions; ++resno) {
OPJ_UINT32 l_dx, l_dy;
l_pdx = l_tccp->prcw[resno];
l_pdy = l_tccp->prch[resno];
*lResolutionPtr++ = l_pdx;
*lResolutionPtr++ = l_pdy;
l_dx = l_img_comp->dx * (1u << (l_pdx + l_level_no));
l_dy = l_img_comp->dy * (1u << (l_pdy + l_level_no));
*p_dx_min = (OPJ_UINT32)opj_int_min((OPJ_INT32)*p_dx_min, (OPJ_INT32)l_dx);
*p_dy_min = (OPJ_UINT32)opj_int_min((OPJ_INT32)*p_dy_min, (OPJ_INT32)l_dy);
l_rx0 = opj_int_ceildivpow2(l_tcx0, (OPJ_INT32)l_level_no);
l_ry0 = opj_int_ceildivpow2(l_tcy0, (OPJ_INT32)l_level_no);
l_rx1 = opj_int_ceildivpow2(l_tcx1, (OPJ_INT32)l_level_no);
l_ry1 = opj_int_ceildivpow2(l_tcy1, (OPJ_INT32)l_level_no);
l_px0 = opj_int_floordivpow2(l_rx0, (OPJ_INT32)l_pdx) << l_pdx;
l_py0 = opj_int_floordivpow2(l_ry0, (OPJ_INT32)l_pdy) << l_pdy;
l_px1 = opj_int_ceildivpow2(l_rx1, (OPJ_INT32)l_pdx) << l_pdx;
py1 = opj_int_ceildivpow2(l_ry1, (OPJ_INT32)l_pdy) << l_pdy;
l_pw = (l_rx0==l_rx1)?0:(OPJ_UINT32)((l_px1 - l_px0) >> l_pdx);
l_ph = (l_ry0==l_ry1)?0:(OPJ_UINT32)((py1 - l_py0) >> l_pdy);
*lResolutionPtr++ = l_pw;
*lResolutionPtr++ = l_ph;
l_product = l_pw * l_ph;
if (l_product > *p_max_prec) {
*p_max_prec = l_product;
}
--l_level_no;
}
++l_tccp;
++l_img_comp;
}
}

int git_pkt_parse_line(
git_pkt **head, const char *line, const char **out, size_t bufflen)
{
int ret;
int32_t len;
if (bufflen > 0 && bufflen < PKT_LEN_SIZE)
return GIT_EBUFS;
len = parse_len(line);
if (len < 0) {
if (bufflen >= 4 && !git__prefixcmp(line, "PACK")) {
giterr_clear();
*out = line;
return pack_pkt(head);
}
return (int)len;
}
if (bufflen > 0 && bufflen < (size_t)len)
return GIT_EBUFS;
line += PKT_LEN_SIZE;
if (len == PKT_LEN_SIZE) {
*head = NULL;
*out = line;
return 0;
}
if (len == 0) { 
*out = line;
return flush_pkt(head);
}
len -= PKT_LEN_SIZE; 
if (*line == GIT_SIDE_BAND_DATA)
ret = data_pkt(head, line, len);
else if (*line == GIT_SIDE_BAND_PROGRESS)
ret = sideband_progress_pkt(head, line, len);
else if (*line == GIT_SIDE_BAND_ERROR)
ret = sideband_error_pkt(head, line, len);
else if (!git__prefixcmp(line, "ACK"))
ret = ack_pkt(head, line, len);
else if (!git__prefixcmp(line, "NAK"))
ret = nak_pkt(head);
else if (!git__prefixcmp(line, "ERR "))
ret = err_pkt(head, line, len);
else if (*line == '#')
ret = comment_pkt(head, line, len);
else if (!git__prefixcmp(line, "ok"))
ret = ok_pkt(head, line, len);
else if (!git__prefixcmp(line, "ng"))
ret = ng_pkt(head, line, len);
else if (!git__prefixcmp(line, "unpack"))
ret = unpack_pkt(head, line, len);
else
ret = ref_pkt(head, line, len);
*out = line + len;
return ret;
}

GInputStream *
gfbgraph_photo_download_default_size (GFBGraphPhoto       *photo,
GFBGraphAuthorizer  *authorizer,
GError             **error)
{
GInputStream *stream = NULL;
SoupSession *session;
SoupRequester *requester;
SoupRequest *request;
SoupMessage *message;
GFBGraphPhotoPrivate *priv;
g_return_val_if_fail (GFBGRAPH_IS_PHOTO (photo), NULL);
g_return_val_if_fail (GFBGRAPH_IS_AUTHORIZER (authorizer), NULL);
priv = GFBGRAPH_PHOTO_GET_PRIVATE (photo);
session = soup_session_sync_new ();
requester = soup_requester_new ();
soup_session_add_feature (session, SOUP_SESSION_FEATURE (requester));
request = soup_requester_request (requester, priv->source, error);
if (request != NULL) {
message = soup_request_http_get_message (SOUP_REQUEST_HTTP (request));
stream = soup_request_send (request, NULL, error);
if (stream != NULL) {
g_object_weak_ref (G_OBJECT (stream),
(GWeakNotify)g_object_unref,
session);
}
g_clear_object (&message);
g_clear_object (&request);
}
g_clear_object (&requester);
return stream;
}

Image *AutoResizeImage(const Image *image,const char *option,
MagickOffsetType *count,ExceptionInfo *exception)
{
#define MAX_SIZES 16
char
*q;
const char
*p;
Image
*resized,
*images;
register ssize_t
i;
size_t
sizes[MAX_SIZES]={256,192,128,96,64,48,40,32,24,16};
images=NULL;
*count=0;
i=0;
p=option;
while (*p != '\0' && i < MAX_SIZES)
{
size_t
size;
while ((isspace((int) ((unsigned char) *p)) != 0))
p++;
size=(size_t)strtol(p,&q,10);
if (p == q || size < 16 || size > 256)
return((Image *) NULL);
p=q;
sizes[i++]=size;
while ((isspace((int) ((unsigned char) *p)) != 0) || (*p == ','))
p++;
}
if (i==0)
i=10;
*count=i;
for (i=0; i < *count; i++)
{
resized=ResizeImage(image,sizes[i],sizes[i],image->filter,exception);
if (resized == (Image *) NULL)
return(DestroyImageList(images));
if (images == (Image *) NULL)
images=resized;
else
AppendImageToList(&images,resized);
}
return(images);
}

int main(int argc, char *argv[])
{
AACENC_CONFIG config;
WavInfo inputInfo;
FILE *inputFile;
FILE *hADTSFile;
int error;
int bitrate;
int nChannelsAAC, nChannelsSBR;
unsigned int sampleRateAAC;
int frmCnt;
int bandwidth = 0;
unsigned int numAncDataBytes = 0;
unsigned char ancDataBytes[MAX_PAYLOAD_SIZE];
unsigned int ancDataLength = 0;
short TimeDataPcm[AACENC_BLOCKSIZE * 2 * MAX_CHANNELS];
int numSamplesRead;
int bDoIIR2Downsample = 0;
int bDingleRate = 0;
int useParametricStereo = 0;
int coreWriteOffset = 0;
int coreReadOffset = 0;
int envWriteOffset = 0;
int envReadOffset = 0;
int writeOffset = INPUT_DELAY * MAX_CHANNELS;
int percent = -1;
struct AAC_ENCODER *aacEnc = 0;
int bDoUpsample = 0;
int upsampleReadOffset = 0;
int inSamples;
int bDoIIR32Resample = 0;
int nSamplesPerChannel;
const int nRuns = 4;
float *resamplerScratch = sbr_envRBuffer;
HANDLE_SBR_ENCODER hEnvEnc = NULL;
fprintf(stderr,
"\n"
"*************************************************************\n"
"* Enhanced aacPlus Encoder\n"
"* Build %s, %s\n"
"* Matteo Croce <rootkit85@yahoo.it>\n"
"*************************************************************\n\n",
__DATE__, __TIME__);
if (argc != 4) {
fprintf(stderr,
"\nUsage:   %s <source.wav> <destination.aac> <bitrate>\n",
argv[0]);
fprintf(stderr,
"\nUse - as filename for stdin and/or stdout.\n");
fprintf(stderr, "\nExample: %s song.wav song.aac 32\n",
argv[0]);
return 0;
}
bitrate = atoi(argv[3]) * 1000;;
fflush(stderr);
inputFile = AuChannelOpen(argv[1], &inputInfo);
if (!inputFile) {
fprintf(stderr, "could not open %s\n", argv[1]);
exit(10);
}
AacInitDefaultConfig(&config);
nChannelsAAC = nChannelsSBR = inputInfo.nChannels;
if ((inputInfo.nChannels == 2) && (bitrate >= 16000)
&& (bitrate < 44001))
useParametricStereo = 1;
if (useParametricStereo) {
nChannelsAAC = 1;
nChannelsSBR = 2;
}
if (((inputInfo.sampleRate == 48000) && (nChannelsAAC == 2)
&& (bitrate < 24000))
|| ((inputInfo.sampleRate == 48000) && (nChannelsAAC == 1)
&& (bitrate < 12000))
)
bDoIIR32Resample = 1;
if (inputInfo.sampleRate == 16000) {
bDoUpsample = 1;
inputInfo.sampleRate = 32000;
bDingleRate = 1;
}
sampleRateAAC = inputInfo.sampleRate;
if (bDoIIR32Resample)
sampleRateAAC = 32000;
config.bitRate = bitrate;
config.nChannelsIn = inputInfo.nChannels;
config.nChannelsOut = nChannelsAAC;
config.bandWidth = bandwidth;
if (!IsSbrSettingAvail
(bitrate, nChannelsAAC, sampleRateAAC, &sampleRateAAC)) {
fprintf(stderr,
"No valid SBR configuration found for:\n\t\t\tbitrate=%d\n\t\t\tchannels=%d\n\t\t\tsamplerate=%d\n",
bitrate, nChannelsAAC, sampleRateAAC);
exit(10);
}
{
sbrConfiguration sbrConfig;
envReadOffset = 0;
coreWriteOffset = 0;
if (useParametricStereo) {
envReadOffset =
(MAX_DS_FILTER_DELAY + INPUT_DELAY) * MAX_CHANNELS;
coreWriteOffset = CORE_INPUT_OFFSET_PS;
writeOffset = envReadOffset;
}
InitializeSbrDefaults(&sbrConfig);
sbrConfig.usePs = useParametricStereo;
AdjustSbrSettings(&sbrConfig,
bitrate,
nChannelsAAC,
sampleRateAAC, AACENC_TRANS_FAC, 24000);
EnvOpen(&hEnvEnc,
inputBuffer + coreWriteOffset,
&sbrConfig, &config.bandWidth);
bDoIIR2Downsample = (bDoUpsample) ? 0 : 1;
if (useParametricStereo)
bDoIIR2Downsample = 0;
}
if (bDoUpsample) {
if (inputInfo.nChannels > 1) {
fprintf(stderr,
"\n Stereo @ 16kHz input sample rate is not supported\n");
return -1;
}
InitIIR21_Resampler(IIR21_reSampler);
InitIIR21_Resampler(IIR21_reSampler + 1);
assert(IIR21_reSampler[0].delay <= MAX_DS_FILTER_DELAY);
if (useParametricStereo) {
writeOffset += AACENC_BLOCKSIZE * MAX_CHANNELS;
upsampleReadOffset = writeOffset;
envWriteOffset = envReadOffset;
} else {
writeOffset += AACENC_BLOCKSIZE * MAX_CHANNELS;
coreReadOffset = writeOffset;
upsampleReadOffset = writeOffset - (((INPUT_DELAY -  IIR21_reSampler[0].delay) >> 1) * MAX_CHANNELS);
envWriteOffset = ((INPUT_DELAY - IIR21_reSampler[0].delay) & 0x1) * MAX_CHANNELS;
envReadOffset = 0;
}
} else if (bDoIIR2Downsample) {
InitIIR21_Resampler(IIR21_reSampler);
InitIIR21_Resampler(IIR21_reSampler + 1);
assert(IIR21_reSampler[0].delay <= MAX_DS_FILTER_DELAY);
writeOffset += IIR21_reSampler[0].delay * MAX_CHANNELS;
}
if (bDoIIR32Resample)
IIR32Init();
config.sampleRate = sampleRateAAC;
error = AacEncOpen(&aacEnc, config);
if (error) {
fprintf(stderr, "\n Initialisation of AAC failed !\n");
AacEncClose(aacEnc);
AuChannelClose(inputFile);
return 1;
}
if (strcmp(argv[2], "-") == 0)
hADTSFile = stdout;
else
hADTSFile = fopen(argv[2], "wb");
if (!hADTSFile) {
fprintf(stderr, "\nFailed to create ADTS file\n");
exit(10);
}
fprintf(stderr, "input file %s: \nsr = %d, nc = %d\n\n", argv[1],
inputInfo.sampleRate, inputInfo.nChannels);
fprintf(stderr, "output file %s: \nbr = %d sr-OUT = %d  nc-OUT = %d\n\n",
argv[2], bitrate, sampleRateAAC * 2, nChannelsSBR);
fflush(stderr);
init_plans();
frmCnt = 0;
memset(TimeDataPcm, 0, sizeof(TimeDataPcm));
if (bDoIIR32Resample) {
inSamples = IIR32GetResamplerFeed(AACENC_BLOCKSIZE *  inputInfo.nChannels * 2) / nRuns;
assert(inSamples <= AACENC_BLOCKSIZE * 2);
} else {
inSamples = AACENC_BLOCKSIZE * inputInfo.nChannels * 2;
if (bDoUpsample)
inSamples = inSamples >> 1;
}
adts_hdr(outputBuffer, &config);
while (1) {
int i, ch, outSamples, numOutBytes, newpercent = -1;
if (bDoIIR32Resample) {
int stopLoop = 0;
int nSamplesProcessed = 0;
int r;
const int nDSOutBlockSize = AACENC_BLOCKSIZE * 2 / nRuns;
int stride = inputInfo.nChannels;
if (inputInfo.nChannels == 1)
stride = 2;
for (r = 0; r < nRuns; r++) {
if (AuChannelReadShort(inputFile, TimeDataPcm,  inSamples, &numSamplesRead)) {
stopLoop = 1;
break;
}
for (i = 0; i < numSamplesRead; i++)
resamplerScratch[i] = (float)TimeDataPcm[i];
switch (inputInfo.nChannels) {
case 1:
nSamplesPerChannel = numSamplesRead;
break;
case 2:
nSamplesPerChannel = numSamplesRead >> 1;
break;
default:
nSamplesPerChannel = numSamplesRead / inputInfo.nChannels;
}
nSamplesProcessed +=
IIR32Resample(resamplerScratch,
&inputBuffer[writeOffset +  r * nDSOutBlockSize * stride],
nSamplesPerChannel,
nDSOutBlockSize,
inputInfo.nChannels);
if (inputInfo.nChannels == 1 && stride == 2)
for (i = nDSOutBlockSize - 1; i >= 0;  i--)
inputBuffer[writeOffset + r * nDSOutBlockSize * 2 + 2 * i] =
inputBuffer[writeOffset + r * nDSOutBlockSize * 2 + i];
}
if (stopLoop)
break;
numSamplesRead = nSamplesProcessed;
} else {
if (AuChannelReadShort(inputFile, TimeDataPcm,
inSamples, &numSamplesRead))
break;
if (inputInfo.nChannels == nChannelsSBR)
for (i = 0; i < numSamplesRead; i++)
inputBuffer[i + writeOffset] = (float)TimeDataPcm[i];
if (inputInfo.nChannels == 1)
for (i = 0; i < numSamplesRead; i++)
inputBuffer[writeOffset + 2 * i] = (float)TimeDataPcm[i];
if ((inputInfo.nChannels == 2) && bEncodeMono)
for (i = 0; i < numSamplesRead / 2; i++)
inputBuffer[writeOffset + 2 * i] = ((float)TimeDataPcm[2 * i] + (float)TimeDataPcm[2 * i + 1]) * 0.5f;
}
if (bDoUpsample)
for (ch = 0; ch < inputInfo.nChannels; ch++)
IIR21_Upsample(&(IIR21_reSampler[ch]),
inputBuffer +
upsampleReadOffset + ch,
numSamplesRead /
inputInfo.nChannels,
MAX_CHANNELS,
inputBuffer + envWriteOffset +
ch, &outSamples, MAX_CHANNELS);
EnvEncodeFrame(hEnvEnc,
inputBuffer + envReadOffset,
inputBuffer + coreWriteOffset,
MAX_CHANNELS, &numAncDataBytes, ancDataBytes);
if (bDoIIR2Downsample)
for (ch = 0; ch < nChannelsAAC; ch++)
IIR21_Downsample(&(IIR21_reSampler[ch]),
inputBuffer + writeOffset + ch,
numSamplesRead /
inputInfo.nChannels,
MAX_CHANNELS, inputBuffer + ch,
&outSamples, MAX_CHANNELS);
if (numAncDataBytes == 0)
numAncDataBytes = ancDataLength;
if (hEnvEnc && useParametricStereo) {
AacEncEncode(aacEnc, inputBuffer, 1,
ancDataBytes,
&numAncDataBytes,
(unsigned *)(outputBuffer + ADTS_HEADER_SIZE),
&numOutBytes);
if (hEnvEnc)
memcpy(inputBuffer,
inputBuffer + AACENC_BLOCKSIZE,
CORE_INPUT_OFFSET_PS * sizeof(float));
} else {
AacEncEncode(aacEnc,
inputBuffer + coreReadOffset,
MAX_CHANNELS,
ancDataBytes,
&numAncDataBytes,
(unsigned *)(outputBuffer + ADTS_HEADER_SIZE),
&numOutBytes);
if (hEnvEnc) {
if (bDoUpsample) {
memmove(&inputBuffer[envReadOffset],
&inputBuffer[envReadOffset +  AACENC_BLOCKSIZE * MAX_CHANNELS * 2],
(envWriteOffset - envReadOffset) *
sizeof(float));
memmove(&inputBuffer
[upsampleReadOffset],
&inputBuffer[upsampleReadOffset + AACENC_BLOCKSIZE * MAX_CHANNELS],
(writeOffset - upsampleReadOffset) *
sizeof(float));
} else
memmove(inputBuffer,
inputBuffer +
AACENC_BLOCKSIZE * 2 *
MAX_CHANNELS,
writeOffset * sizeof(float));
}
}
if (numOutBytes) {
adts_hdr_up(outputBuffer, numOutBytes);
fwrite(outputBuffer, 1, numOutBytes + ADTS_HEADER_SIZE, hADTSFile);
}
frmCnt++;
newpercent = frmCnt * AACENC_BLOCKSIZE * inputInfo.nChannels / (inputInfo.nSamples / (4 * 100));
if (newpercent != percent) {
percent = newpercent;
fprintf(stderr, "[%d%%]\r", newpercent);
fflush(stderr);
}
}
fprintf(stderr, "\n");
fflush(stderr);
AacEncClose(aacEnc);
AuChannelClose(inputFile);
destroy_plans();
if (hEnvEnc)
EnvClose(hEnvEnc);
fprintf(stderr, "\nencoding finished\n");
fflush(stderr);
return 0;
}

SRP_user_pwd *SRP_VBASE_get_by_user(SRP_VBASE *vb, char *username)
{
int i;
SRP_user_pwd *user;
unsigned char digv[SHA_DIGEST_LENGTH];
unsigned char digs[SHA_DIGEST_LENGTH];
EVP_MD_CTX ctxt;
if (vb == NULL)
return NULL;
for (i = 0; i < sk_SRP_user_pwd_num(vb->users_pwd); i++) {
user = sk_SRP_user_pwd_value(vb->users_pwd, i);
if (strcmp(user->id, username) == 0)
return user;
}
if ((vb->seed_key == NULL) ||
(vb->default_g == NULL) || (vb->default_N == NULL))
return NULL;
if ((user = SRP_user_pwd_new()) == NULL)
return NULL;
SRP_user_pwd_set_gN(user, vb->default_g, vb->default_N);
if (!SRP_user_pwd_set_ids(user, username, NULL))
goto err;
if (RAND_pseudo_bytes(digv, SHA_DIGEST_LENGTH) < 0)
goto err;
EVP_MD_CTX_init(&ctxt);
EVP_DigestInit_ex(&ctxt, EVP_sha1(), NULL);
EVP_DigestUpdate(&ctxt, vb->seed_key, strlen(vb->seed_key));
EVP_DigestUpdate(&ctxt, username, strlen(username));
EVP_DigestFinal_ex(&ctxt, digs, NULL);
EVP_MD_CTX_cleanup(&ctxt);
if (SRP_user_pwd_set_sv_BN
(user, BN_bin2bn(digs, SHA_DIGEST_LENGTH, NULL),
BN_bin2bn(digv, SHA_DIGEST_LENGTH, NULL)))
return user;
err:SRP_user_pwd_free(user);
return NULL;
}

static int dynamicGetbuf(gdIOCtxPtr ctx, void *buf, int len)
{
int rlen, remain;
dpIOCtxPtr dctx;
dynamicPtr *dp;
dctx = (dpIOCtxPtr) ctx;
dp = dctx->dp;
remain = dp->logicalSize - dp->pos;
if(remain >= len) {
rlen = len;
} else {
if(remain == 0) {
return 0; 
}
rlen = remain;
}
memcpy(buf, (void *) ((char *)dp->data + dp->pos), rlen);
dp->pos += rlen;
return rlen;
}

static void SkipRGBMipmaps(Image *image, DDSInfo *dds_info, int pixel_size)
{
MagickOffsetType
offset;
register ssize_t
i;
size_t
h,
w;
if (dds_info->ddscaps1 & DDSCAPS_MIPMAP
&& (dds_info->ddscaps1 & DDSCAPS_TEXTURE
|| dds_info->ddscaps2 & DDSCAPS2_CUBEMAP))
{
w = DIV2(dds_info->width);
h = DIV2(dds_info->height);
for (i=1; (i < (ssize_t) dds_info->mipmapcount) && w && h; i++)
{
offset = (MagickOffsetType) w * h * pixel_size;
(void) SeekBlob(image, offset, SEEK_CUR);
w = DIV2(w);
h = DIV2(h);
}
}
}

void SoftOpus::onQueueFilled(OMX_U32 portIndex) {
List<BufferInfo *> &inQueue = getPortQueue(0);
List<BufferInfo *> &outQueue = getPortQueue(1);
if (mOutputPortSettingsChange != NONE) {
return;
}
if (portIndex == 0 && mInputBufferCount < 3) {
BufferInfo *info = *inQueue.begin();
OMX_BUFFERHEADERTYPE *header = info->mHeader;
const uint8_t *data = header->pBuffer + header->nOffset;
size_t size = header->nFilledLen;
if (mInputBufferCount == 0) {
CHECK(mHeader == NULL);
mHeader = new OpusHeader();
memset(mHeader, 0, sizeof(*mHeader));
if (!ParseOpusHeader(data, size, mHeader)) {
ALOGV("Parsing Opus Header failed.");
notify(OMX_EventError, OMX_ErrorUndefined, 0, NULL);
return;
}
uint8_t channel_mapping[kMaxChannels] = {0};
if (mHeader->channels <= kMaxChannelsWithDefaultLayout) {
memcpy(&channel_mapping,
kDefaultOpusChannelLayout,
kMaxChannelsWithDefaultLayout);
} else {
memcpy(&channel_mapping,
mHeader->stream_map,
mHeader->channels);
}
int status = OPUS_INVALID_STATE;
mDecoder = opus_multistream_decoder_create(kRate,
mHeader->channels,
mHeader->num_streams,
mHeader->num_coupled,
channel_mapping,
&status);
if (!mDecoder || status != OPUS_OK) {
ALOGV("opus_multistream_decoder_create failed status=%s",
opus_strerror(status));
notify(OMX_EventError, OMX_ErrorUndefined, 0, NULL);
return;
}
status =
opus_multistream_decoder_ctl(mDecoder,
OPUS_SET_GAIN(mHeader->gain_db));
if (status != OPUS_OK) {
ALOGV("Failed to set OPUS header gain; status=%s",
opus_strerror(status));
notify(OMX_EventError, OMX_ErrorUndefined, 0, NULL);
return;
}
} else if (mInputBufferCount == 1) {
mCodecDelay = ns_to_samples(
*(reinterpret_cast<int64_t*>(header->pBuffer +
header->nOffset)),
kRate);
mSamplesToDiscard = mCodecDelay;
} else {
mSeekPreRoll = ns_to_samples(
*(reinterpret_cast<int64_t*>(header->pBuffer +
header->nOffset)),
kRate);
notify(OMX_EventPortSettingsChanged, 1, 0, NULL);
mOutputPortSettingsChange = AWAITING_DISABLED;
}
inQueue.erase(inQueue.begin());
info->mOwnedByUs = false;
notifyEmptyBufferDone(header);
++mInputBufferCount;
return;
}
while (!inQueue.empty() && !outQueue.empty()) {
BufferInfo *inInfo = *inQueue.begin();
OMX_BUFFERHEADERTYPE *inHeader = inInfo->mHeader;
if (inHeader->nFlags & OMX_BUFFERFLAG_CODECCONFIG) {
inQueue.erase(inQueue.begin());
inInfo->mOwnedByUs = false;
notifyEmptyBufferDone(inHeader);
return;
}
BufferInfo *outInfo = *outQueue.begin();
OMX_BUFFERHEADERTYPE *outHeader = outInfo->mHeader;
if (inHeader->nFlags & OMX_BUFFERFLAG_EOS) {
inQueue.erase(inQueue.begin());
inInfo->mOwnedByUs = false;
notifyEmptyBufferDone(inHeader);
outHeader->nFilledLen = 0;
outHeader->nFlags = OMX_BUFFERFLAG_EOS;
outQueue.erase(outQueue.begin());
outInfo->mOwnedByUs = false;
notifyFillBufferDone(outHeader);
return;
}
if (inHeader->nOffset == 0) {
mAnchorTimeUs = inHeader->nTimeStamp;
mNumFramesOutput = 0;
}
if (inHeader->nTimeStamp == 0) {
mSamplesToDiscard = mCodecDelay;
}
const uint8_t *data = inHeader->pBuffer + inHeader->nOffset;
const uint32_t size = inHeader->nFilledLen;
int numFrames = opus_multistream_decode(mDecoder,
data,
size,
(int16_t *)outHeader->pBuffer,
kMaxOpusOutputPacketSizeSamples,
0);
if (numFrames < 0) {
ALOGE("opus_multistream_decode returned %d", numFrames);
notify(OMX_EventError, OMX_ErrorUndefined, 0, NULL);
return;
}
outHeader->nOffset = 0;
if (mSamplesToDiscard > 0) {
if (mSamplesToDiscard > numFrames) {
mSamplesToDiscard -= numFrames;
numFrames = 0;
} else {
numFrames -= mSamplesToDiscard;
outHeader->nOffset = mSamplesToDiscard * sizeof(int16_t) *
mHeader->channels;
mSamplesToDiscard = 0;
}
}
outHeader->nFilledLen = numFrames * sizeof(int16_t) * mHeader->channels;
outHeader->nFlags = 0;
outHeader->nTimeStamp = mAnchorTimeUs +
(mNumFramesOutput * 1000000ll) /
kRate;
mNumFramesOutput += numFrames;
inInfo->mOwnedByUs = false;
inQueue.erase(inQueue.begin());
inInfo = NULL;
notifyEmptyBufferDone(inHeader);
inHeader = NULL;
outInfo->mOwnedByUs = false;
outQueue.erase(outQueue.begin());
outInfo = NULL;
notifyFillBufferDone(outHeader);
outHeader = NULL;
++mInputBufferCount;
}
}

