static apr_status_t gnutls_io_input_read(mgs_handle_t * ctxt,
char *buf, apr_size_t * len)
{
apr_size_t wanted = *len;
apr_size_t bytes = 0;
*len = 0;
if ((bytes = char_buffer_read(&ctxt->input_cbuf, buf, wanted))) {
*len = bytes;
if (ctxt->input_mode == AP_MODE_SPECULATIVE) {
if (ctxt->input_cbuf.length > 0) {
ctxt->input_cbuf.value -= bytes;
ctxt->input_cbuf.length += bytes;
} else {
char_buffer_write(&ctxt->input_cbuf, buf,
(int) bytes);
}
return APR_SUCCESS;
}
if (*len >= wanted) {
return APR_SUCCESS;
}
if (ctxt->input_mode == AP_MODE_GETLINE) {
if (memchr(buf, APR_ASCII_LF, *len)) {
return APR_SUCCESS;
}
} else {
ctxt->input_block = APR_NONBLOCK_READ;
}
}
if (ctxt->session == NULL) {
ap_log_cerror(APLOG_MARK, APLOG_INFO, 0, ctxt->c,
"%s: GnuTLS session is NULL!", __func__);
return APR_EGENERAL;
}
while (1)
{
int rc = gnutls_record_recv(ctxt->session,
buf + bytes, wanted - bytes);
if (rc > 0) {
*len += rc;
if (ctxt->input_mode == AP_MODE_SPECULATIVE) {
char_buffer_write(&ctxt->input_cbuf, buf,
*len);
}
return ctxt->input_rc;
} else if (rc == 0) {
if (*len > 0) {
ctxt->input_rc = APR_SUCCESS;
} else {
ctxt->input_rc = APR_EOF;
}
break;
} else { 
if (rc == GNUTLS_E_INTERRUPTED || rc == GNUTLS_E_AGAIN)
{
ap_log_cerror(APLOG_MARK, APLOG_TRACE2, ctxt->input_rc, ctxt->c,
"%s: looping recv after '%s' (%d)",
__func__, gnutls_strerror(rc), rc);
if (ctxt->input_block != APR_NONBLOCK_READ)
continue;
else
ctxt->input_rc =
(rc == GNUTLS_E_AGAIN ? APR_EAGAIN : APR_EINTR);
} else if (rc == GNUTLS_E_REHANDSHAKE) {
ap_log_cerror(APLOG_MARK, APLOG_DEBUG,
ctxt->input_rc,
ctxt->c,
"GnuTLS: Error reading data. Client Requested a New Handshake."
" (%d) '%s'", rc,
gnutls_strerror(rc));
} else if (rc == GNUTLS_E_WARNING_ALERT_RECEIVED) {
rc = gnutls_alert_get(ctxt->session);
ap_log_cerror(APLOG_MARK, APLOG_DEBUG,
ctxt->input_rc,
ctxt->c,
"GnuTLS: Warning Alert From Client: "
" (%d) '%s'", rc,
gnutls_alert_get_name(rc));
} else if (rc == GNUTLS_E_FATAL_ALERT_RECEIVED) {
rc = gnutls_alert_get(ctxt->session);
ap_log_cerror(APLOG_MARK, APLOG_DEBUG,
ctxt->input_rc,
ctxt->c,
"GnuTLS: Fatal Alert From Client: "
"(%d) '%s'", rc,
gnutls_alert_get_name(rc));
ctxt->input_rc = APR_EGENERAL;
break;
} else {
if (gnutls_error_is_fatal(rc)) {
ap_log_cerror(
APLOG_MARK, APLOG_DEBUG,
ctxt->input_rc,
ctxt->c,
"GnuTLS: Error reading data. (%d) '%s'",
rc, gnutls_strerror(rc));
} else if (*len > 0) {
ctxt->input_rc = APR_SUCCESS;
break;
}
}
if (ctxt->input_rc == APR_SUCCESS) {
ap_log_cerror(APLOG_MARK, APLOG_INFO, ctxt->input_rc, ctxt->c,
"%s: GnuTLS error: %s (%d)",
__func__, gnutls_strerror(rc), rc);
ctxt->input_rc = APR_EGENERAL;
}
break;
}
}
return ctxt->input_rc;
}

HANDLE
lsaauth (cygsid &usersid, user_groups &new_groups)
{
cygsidlist tmp_gsids (cygsidlist_auto, 12);
cygpsid pgrpsid;
LSA_STRING name;
HANDLE lsa_hdl = NULL, lsa = NULL;
LSA_OPERATIONAL_MODE sec_mode;
NTSTATUS status, sub_status;
ULONG package_id, size;
LUID auth_luid = SYSTEM_LUID;
struct {
LSA_STRING str;
CHAR buf[16];
} origin;
DWORD ulen = UNLEN + 1;
DWORD dlen = MAX_DOMAIN_NAME_LEN + 1;
SID_NAME_USE use;
cyglsa_t *authinf = NULL;
ULONG authinf_size;
TOKEN_SOURCE ts;
PCYG_TOKEN_GROUPS gsids = NULL;
PTOKEN_PRIVILEGES privs = NULL;
PACL dacl = NULL;
PVOID profile = NULL;
LUID luid;
QUOTA_LIMITS quota;
size_t psize = 0, gsize = 0, dsize = 0;
OFFSET offset, sids_offset;
int tmpidx, non_well_known_cnt;
HANDLE user_token = NULL;
push_self_privilege (SE_TCB_PRIVILEGE, true);
RtlInitAnsiString (&name, "Cygwin");
SetLastError (0);
status = LsaRegisterLogonProcess (&name, &lsa_hdl, &sec_mode);
if (status != STATUS_SUCCESS)
{
debug_printf ("LsaRegisterLogonProcess: %y", status);
__seterrno_from_nt_status (status);
goto out;
}
else if (GetLastError () == ERROR_PROC_NOT_FOUND)
{
debug_printf ("Couldn't load Secur32.dll");
goto out;
}
RtlInitAnsiString (&name, CYG_LSA_PKGNAME);
status = LsaLookupAuthenticationPackage (lsa_hdl, &name, &package_id);
if (status != STATUS_SUCCESS)
{
debug_printf ("LsaLookupAuthenticationPackage: %y", status);
__seterrno_from_nt_status (status);
goto out;
}
if (!(lsa = lsa_open_policy (NULL, POLICY_EXECUTE)))
goto out;
stpcpy (origin.buf, "Cygwin");
RtlInitAnsiString (&origin.str, origin.buf);
memcpy (ts.SourceName, "Cygwin.1", 8);
ts.SourceIdentifier.HighPart = 0;
ts.SourceIdentifier.LowPart = 0x0103;
int auth_pos;
if (new_groups.issetgroups ())
get_setgroups_sidlist (tmp_gsids, usersid, NULL, new_groups, auth_luid,
auth_pos);
else if (!get_initgroups_sidlist (tmp_gsids, usersid, new_groups.pgsid,
NULL, auth_luid, auth_pos))
goto out;
tmp_gsids.debug_print ("tmp_gsids");
non_well_known_cnt =  tmp_gsids.non_well_known_count ();
gsize = sizeof (DWORD) + non_well_known_cnt * sizeof (SID_AND_ATTRIBUTES);
tmpidx = -1;
for (int i = 0; i < non_well_known_cnt; ++i)
if ((tmpidx = tmp_gsids.next_non_well_known_sid (tmpidx)) >= 0)
gsize += RtlLengthSid (tmp_gsids.sids[tmpidx]);
if (!(privs = get_priv_list (lsa, usersid, tmp_gsids, psize, NULL)))
goto out;
dsize = sizeof (ACL) + 3 * sizeof (ACCESS_ALLOWED_ACE)
+ RtlLengthSid (usersid)
+ RtlLengthSid (well_known_admins_sid)
+ RtlLengthSid (well_known_system_sid);
dacl = (PACL) alloca (dsize);
if (!NT_SUCCESS (RtlCreateAcl (dacl, dsize, ACL_REVISION)))
goto out;
if (!NT_SUCCESS (RtlAddAccessAllowedAce (dacl, ACL_REVISION, GENERIC_ALL,
usersid)))
goto out;
if (!NT_SUCCESS (RtlAddAccessAllowedAce (dacl, ACL_REVISION, GENERIC_ALL,
well_known_admins_sid)))
goto out;
if (!NT_SUCCESS (RtlAddAccessAllowedAce (dacl, ACL_REVISION, GENERIC_ALL,
well_known_system_sid)))
goto out;
authinf_size = (authinf->data - (PBYTE) authinf);
authinf_size += RtlLengthSid (usersid);    
authinf_size += gsize;    
if (new_groups.pgsid == well_known_admins_sid)
pgrpsid = well_known_local_sid;
else
pgrpsid = new_groups.pgsid;
authinf_size += RtlLengthSid (pgrpsid);    
authinf_size += psize;    
authinf_size += 0;    
authinf_size += dsize;    
authinf = (cyglsa_t *) alloca (authinf_size);
authinf->inf_size = authinf_size - ((PBYTE) &authinf->inf - (PBYTE) authinf);
authinf->magic = CYG_LSA_MAGIC;
if (!LookupAccountSidW (NULL, usersid, authinf->username, &ulen,
authinf->domain, &dlen, &use))
{
__seterrno ();
goto out;
}
offset = authinf->data - (PBYTE) &authinf->inf;
authinf->inf.ExpirationTime.LowPart = 0xffffffffL;
authinf->inf.ExpirationTime.HighPart = 0x7fffffffL;
authinf->inf.User.User.Sid = offset;
authinf->inf.User.User.Attributes = 0;
RtlCopySid (RtlLengthSid (usersid), (PSID) ((PBYTE) &authinf->inf + offset),
usersid);
offset += RtlLengthSid (usersid);
authinf->inf.Groups = offset;
gsids = (PCYG_TOKEN_GROUPS) ((PBYTE) &authinf->inf + offset);
sids_offset = offset + sizeof (ULONG) + non_well_known_cnt
* sizeof (SID_AND_ATTRIBUTES);
gsids->GroupCount = non_well_known_cnt;
tmpidx = -1;
for (int i = 0; i < non_well_known_cnt; ++i)
{
if ((tmpidx = tmp_gsids.next_non_well_known_sid (tmpidx)) < 0)
break;
gsids->Groups[i].Sid = sids_offset;
gsids->Groups[i].Attributes = SE_GROUP_MANDATORY
| SE_GROUP_ENABLED_BY_DEFAULT
| SE_GROUP_ENABLED;
RtlCopySid (RtlLengthSid (tmp_gsids.sids[tmpidx]),
(PSID) ((PBYTE) &authinf->inf + sids_offset),
tmp_gsids.sids[tmpidx]);
sids_offset += RtlLengthSid (tmp_gsids.sids[tmpidx]);
}
offset += gsize;
authinf->inf.PrimaryGroup.PrimaryGroup = offset;
RtlCopySid (RtlLengthSid (pgrpsid), (PSID) ((PBYTE) &authinf->inf + offset),
pgrpsid);
offset += RtlLengthSid (pgrpsid);
authinf->inf.Privileges = offset;
memcpy ((PBYTE) &authinf->inf + offset, privs, psize);
offset += psize;
authinf->inf.Owner.Owner = 0;
authinf->inf.DefaultDacl.DefaultDacl = offset;
memcpy ((PBYTE) &authinf->inf + offset, dacl, dsize);
authinf->checksum = CYG_LSA_MAGIC;
PDWORD csp;
PDWORD csp_end;
csp = (PDWORD) &authinf->username;
csp_end = (PDWORD) ((PBYTE) authinf + authinf_size);
while (csp < csp_end)
authinf->checksum += *csp++;
status = LsaLogonUser (lsa_hdl, (PLSA_STRING) &origin, Interactive,
package_id, authinf, authinf_size, NULL, &ts,
&profile, &size, &luid, &user_token, &quota,
&sub_status);
if (status != STATUS_SUCCESS)
{
debug_printf ("LsaLogonUser: %y (sub-status %y)", status, sub_status);
__seterrno_from_nt_status (status);
goto out;
}
if (profile)
{
#ifdef JUST_ANOTHER_NONWORKING_SOLUTION
cygprf_t *prf = (cygprf_t *) profile;
if (prf->magic_pre == MAGIC_PRE && prf->magic_post == MAGIC_POST
&& prf->token)
{
CloseHandle (user_token);
user_token = prf->token;
system_printf ("Got token through profile: %p", user_token);
}
#endif 
LsaFreeReturnBuffer (profile);
}
user_token = get_full_privileged_inheritable_token (user_token);
out:
if (privs)
free (privs);
lsa_close_policy (lsa);
if (lsa_hdl)
LsaDeregisterLogonProcess (lsa_hdl);
pop_self_privilege ();
debug_printf ("%p = lsaauth ()", user_token);
return user_token;
}

bool OMXNodeInstance::handleMessage(omx_message &msg) {
const sp<GraphicBufferSource>& bufferSource(getGraphicBufferSource());
if (msg.type == omx_message::FILL_BUFFER_DONE) {
OMX_BUFFERHEADERTYPE *buffer =
findBufferHeader(msg.u.extended_buffer_data.buffer);
{
Mutex::Autolock _l(mDebugLock);
mOutputBuffersWithCodec.remove(buffer);
CLOG_BUMPED_BUFFER(
FBD, WITH_STATS(FULL_BUFFER(
msg.u.extended_buffer_data.buffer, buffer, msg.fenceFd)));
unbumpDebugLevel_l(kPortIndexOutput);
}
BufferMeta *buffer_meta =
static_cast<BufferMeta *>(buffer->pAppPrivate);
if (buffer->nOffset + buffer->nFilledLen < buffer->nOffset
|| buffer->nOffset + buffer->nFilledLen > buffer->nAllocLen) {
CLOG_ERROR(onFillBufferDone, OMX_ErrorBadParameter,
FULL_BUFFER(NULL, buffer, msg.fenceFd));
}
buffer_meta->CopyFromOMX(buffer);
if (bufferSource != NULL) {
bufferSource->codecBufferFilled(buffer);
msg.u.extended_buffer_data.timestamp = buffer->nTimeStamp;
}
} else if (msg.type == omx_message::EMPTY_BUFFER_DONE) {
OMX_BUFFERHEADERTYPE *buffer =
findBufferHeader(msg.u.buffer_data.buffer);
{
Mutex::Autolock _l(mDebugLock);
mInputBuffersWithCodec.remove(buffer);
CLOG_BUMPED_BUFFER(
EBD, WITH_STATS(EMPTY_BUFFER(msg.u.buffer_data.buffer, buffer, msg.fenceFd)));
}
if (bufferSource != NULL) {
bufferSource->codecBufferEmptied(buffer, msg.fenceFd);
return true;
}
}
return false;
}

xmlXPathObjectPtr
xmlXPtrNewRangePoints(xmlXPathObjectPtr start, xmlXPathObjectPtr end) {
xmlXPathObjectPtr ret;
if (start == NULL)
return(NULL);
if (end == NULL)
return(NULL);
if (start->type != XPATH_POINT)
return(NULL);
if (end->type != XPATH_POINT)
return(NULL);
ret = (xmlXPathObjectPtr) xmlMalloc(sizeof(xmlXPathObject));
if (ret == NULL) {
xmlXPtrErrMemory("allocating range");
return(NULL);
}
memset(ret, 0 , (size_t) sizeof(xmlXPathObject));
ret->type = XPATH_RANGE;
ret->user = start->user;
ret->index = start->index;
ret->user2 = end->user;
ret->index2 = end->index;
xmlXPtrRangeCheckOrder(ret);
return(ret);
}

int ParseDsdiffHeaderConfig (FILE *infile, char *infilename, char *fourcc, WavpackContext *wpc, WavpackConfig *config)
{
