int crxSetupSubbandData(CrxImage *img, CrxPlaneComp *planeComp,
const CrxTile *tile, uint32_t mdatOffset)
{
long compDataSize = 0;
long waveletDataOffset = 0;
long compCoeffDataOffset = 0;
int32_t toSubbands = 3 * img->levels + 1;
int32_t transformWidth = 0;
CrxSubband *subbands = planeComp->subBands;
for (int32_t subbandNum = 0; subbandNum < toSubbands; subbandNum++)
{
subbands[subbandNum].bandSize =
subbands[subbandNum].width * sizeof(int32_t);     compDataSize += subbands[subbandNum].bandSize;
}
if (img->levels)
{
int32_t encLevels = img->levels ? img->levels : 1;
waveletDataOffset = (compDataSize + 7) & ~7;
compDataSize =
(sizeof(CrxWaveletTransform) * encLevels + waveletDataOffset + 7) & ~7;
compCoeffDataOffset = compDataSize;
for (int level = 0; level < img->levels; ++level)
if (level < img->levels - 1)
compDataSize += 8 * sizeof(int32_t) *
planeComp->subBands[3 * (level + 1) + 2].width;
else
compDataSize += 8 * sizeof(int32_t) * tile->width;
}
planeComp->compBuf = (uint8_t *)malloc(compDataSize);
if (!planeComp->compBuf)
return -1;
uint64_t subbandMdatOffset = img->mdatOffset + mdatOffset;
uint8_t *subbandBuf = planeComp->compBuf;
for (int32_t subbandNum = 0; subbandNum < toSubbands; subbandNum++)
{
subbands[subbandNum].bandBuf = subbandBuf;
subbandBuf += subbands[subbandNum].bandSize;
subbands[subbandNum].mdatOffset =
subbandMdatOffset + subbands[subbandNum].dataOffset;
}
if (img->levels)
{
CrxWaveletTransform *waveletTransforms =
(CrxWaveletTransform *)(planeComp->compBuf + waveletDataOffset);
int32_t *paramData = (int32_t *)(planeComp->compBuf + compCoeffDataOffset);
planeComp->waveletTransform = waveletTransforms;
waveletTransforms[0].subband0Buf = (int32_t *)subbands->bandBuf;
for (int level = 0; level < img->levels; ++level)
{
int32_t band = 3 * level + 1;
if (level >= img->levels - 1)
{
waveletTransforms[level].height = tile->height;
transformWidth = tile->width;
}
else
{
waveletTransforms[level].height = subbands[band + 3].height;
transformWidth = subbands[band + 4].width;
}
waveletTransforms[level].width = transformWidth;
waveletTransforms[level].lineBuf[0] = paramData;
waveletTransforms[level].lineBuf[1] =
waveletTransforms[level].lineBuf[0] + transformWidth;
waveletTransforms[level].lineBuf[2] =
waveletTransforms[level].lineBuf[1] + transformWidth;
waveletTransforms[level].lineBuf[3] =
waveletTransforms[level].lineBuf[2] + transformWidth;
waveletTransforms[level].lineBuf[4] =
waveletTransforms[level].lineBuf[3] + transformWidth;
waveletTransforms[level].lineBuf[5] =
waveletTransforms[level].lineBuf[4] + transformWidth;
waveletTransforms[level].lineBuf[6] =
waveletTransforms[level].lineBuf[5] + transformWidth;
waveletTransforms[level].lineBuf[7] =
waveletTransforms[level].lineBuf[6] + transformWidth;
waveletTransforms[level].curLine = 0;
waveletTransforms[level].curH = 0;
waveletTransforms[level].fltTapH = 0;
waveletTransforms[level].subband1Buf = (int32_t *)subbands[band].bandBuf;
waveletTransforms[level].subband2Buf =
(int32_t *)subbands[band + 1].bandBuf;
waveletTransforms[level].subband3Buf =
(int32_t *)subbands[band + 2].bandBuf;
paramData = waveletTransforms[level].lineBuf[7] + transformWidth;
}
}
for (int32_t subbandNum = 0; subbandNum < toSubbands; subbandNum++)
{
if (subbands[subbandNum].dataSize)
{
int32_t supportsPartial = 0;
uint32_t roundedBitsMask = 0;
if (planeComp->supportsPartial && subbandNum == 0)
{
roundedBitsMask = planeComp->roundedBitsMask;
supportsPartial = 1;
}
if (crxParamInit(&subbands[subbandNum].bandParam,
subbands[subbandNum].mdatOffset,
subbands[subbandNum].dataSize,
subbands[subbandNum].width, subbands[subbandNum].height,
supportsPartial, roundedBitsMask, img->input))
return -1;
}
}
return 0;
}

static unsigned int floppy_check_events(struct gendisk *disk,
unsigned int clearing)
{
int drive = (long)disk->private_data;
if (test_bit(FD_DISK_CHANGED_BIT, &UDRS->flags) ||
test_bit(FD_VERIFY_BIT, &UDRS->flags))
return DISK_EVENT_MEDIA_CHANGE;
if (time_after(jiffies, UDRS->last_checked + UDP->checkfreq)) {
lock_fdc(drive, false);
poll_drive(false, 0);
process_fd_request();
}
if (test_bit(FD_DISK_CHANGED_BIT, &UDRS->flags) ||
test_bit(FD_VERIFY_BIT, &UDRS->flags) ||
test_bit(drive, &fake_change) ||
drive_no_geom(drive))
return DISK_EVENT_MEDIA_CHANGE;
return 0;
}

gboolean
flatpak_dir_deploy_appstream (FlatpakDir          *self,
const char          *remote,
const char          *arch,
gboolean            *out_changed,
GCancellable        *cancellable,
GError             **error)
{
g_autoptr(GFile) appstream_dir = NULL;
g_autoptr(GFile) remote_dir = NULL;
g_autoptr(GFile) arch_dir = NULL;
g_autoptr(GFile) checkout_dir = NULL;
g_autoptr(GFile) real_checkout_dir = NULL;
g_autoptr(GFile) timestamp_file = NULL;
g_autofree char *arch_path = NULL;
gboolean checkout_exists;
g_autofree char *remote_and_branch = NULL;
const char *old_checksum = NULL;
g_autofree char *new_checksum = NULL;
g_autoptr(GFile) active_link = NULL;
g_autofree char *branch = NULL;
g_autoptr(GFile) old_checkout_dir = NULL;
g_autoptr(GFile) active_tmp_link = NULL;
g_autoptr(GError) tmp_error = NULL;
g_autofree char *checkout_dir_path = NULL;
OstreeRepoCheckoutAtOptions options = { 0, };
glnx_fd_close int dfd = -1;
g_autoptr(GFileInfo) file_info = NULL;
g_autofree char *tmpname = g_strdup (".active-XXXXXX");
appstream_dir = g_file_get_child (flatpak_dir_get_path (self), "appstream");
remote_dir = g_file_get_child (appstream_dir, remote);
arch_dir = g_file_get_child (remote_dir, arch);
active_link = g_file_get_child (arch_dir, "active");
timestamp_file = g_file_get_child (arch_dir, ".timestamp");
arch_path = g_file_get_path (arch_dir);
if (g_mkdir_with_parents (arch_path, 0755) != 0)
{
glnx_set_error_from_errno (error);
return FALSE;
}
if (!glnx_opendirat (AT_FDCWD, arch_path, TRUE, &dfd, error))
return FALSE;
old_checksum = NULL;
file_info = g_file_query_info (active_link, OSTREE_GIO_FAST_QUERYINFO,
G_FILE_QUERY_INFO_NOFOLLOW_SYMLINKS,
cancellable, NULL);
if (file_info != NULL)
old_checksum =  g_file_info_get_symlink_target (file_info);
branch = g_strdup_printf ("appstream/%s", arch);
remote_and_branch = g_strdup_printf ("%s:%s", remote, branch);
if (!ostree_repo_resolve_rev (self->repo, remote_and_branch, TRUE, &new_checksum, error))
return FALSE;
real_checkout_dir = g_file_get_child (arch_dir, new_checksum);
checkout_exists = g_file_query_exists (real_checkout_dir, NULL);
if (old_checksum != NULL && new_checksum != NULL &&
strcmp (old_checksum, new_checksum) == 0 &&
checkout_exists)
{
if (!g_file_replace_contents (timestamp_file, "", 0, NULL, FALSE,
G_FILE_CREATE_REPLACE_DESTINATION, NULL, NULL, error))
return FALSE;
if (out_changed)
*out_changed = FALSE;
return TRUE; 
}
{
g_autofree char *template = g_strdup_printf (".%s-XXXXXX", new_checksum);
g_autoptr(GFile) tmp_dir_template = g_file_get_child (arch_dir, template);
checkout_dir_path = g_file_get_path (tmp_dir_template);
if (g_mkdtemp_full (checkout_dir_path, 0755) == NULL)
{
g_set_error (error, G_IO_ERROR, G_IO_ERROR_FAILED,
_("Can't create deploy directory"));
return FALSE;
}
}
checkout_dir = g_file_new_for_path (checkout_dir_path);
options.mode = OSTREE_REPO_CHECKOUT_MODE_USER;
options.overwrite_mode = OSTREE_REPO_CHECKOUT_OVERWRITE_UNION_FILES;
options.enable_fsync = FALSE; 
if (!ostree_repo_checkout_at (self->repo, &options,
AT_FDCWD, checkout_dir_path, new_checksum,
cancellable, error))
return FALSE;
glnx_gen_temp_name (tmpname);
active_tmp_link = g_file_get_child (arch_dir, tmpname);
if (!g_file_make_symbolic_link (active_tmp_link, new_checksum, cancellable, error))
return FALSE;
if (syncfs (dfd) != 0)
{
glnx_set_error_from_errno (error);
return FALSE;
}
if (!g_file_move (checkout_dir, real_checkout_dir, G_FILE_COPY_NO_FALLBACK_FOR_MOVE,
cancellable, NULL, NULL, error))
return FALSE;
if (syncfs (dfd) != 0)
{
glnx_set_error_from_errno (error);
return FALSE;
}
if (!flatpak_file_rename (active_tmp_link,
active_link,
cancellable, error))
return FALSE;
if (old_checksum != NULL &&
g_strcmp0 (old_checksum, new_checksum) != 0)
{
old_checkout_dir = g_file_get_child (arch_dir, old_checksum);
if (!flatpak_rm_rf (old_checkout_dir, cancellable, &tmp_error))
g_warning ("Unable to remove old appstream checkout: %s\n", tmp_error->message);
}
if (!g_file_replace_contents (timestamp_file, "", 0, NULL, FALSE,
G_FILE_CREATE_REPLACE_DESTINATION, NULL, NULL, error))
return FALSE;
if (!checkout_exists)
{
g_autofree char *appstream_dir_path = g_file_get_path (appstream_dir);
utime (appstream_dir_path, NULL);
}
if (out_changed)
*out_changed = TRUE;
return TRUE;
}

