}
return;
trunc:
ND_PRINT((ndo, " [|ubik]"));
}

static void copyMultiCh24(short *dst, const int *const *src, unsigned nSamples, unsigned nChannels)
{
for (unsigned i = 0; i < nSamples; ++i) {
