static int
ospf6_decode_v3(netdissect_options *ndo,
register const struct ospf6hdr *op,
register const u_char *dataend)
{
register const rtrid_t *ap;
register const struct lsr6 *lsrp;
register const struct lsa6_hdr *lshp;
register const struct lsa6 *lsap;
register int i;
switch (op->ospf6_type) {
case OSPF_TYPE_HELLO: {
register const struct hello6 *hellop = (const struct hello6 *)((const uint8_t *)op + OSPF6HDR_LEN);
ND_PRINT((ndo, "\n\tOptions [%s]",
bittok2str(ospf6_option_values, "none",
EXTRACT_32BITS(&hellop->hello_options))));
ND_TCHECK(hellop->hello_deadint);
ND_PRINT((ndo, "\n\t  Hello Timer %us, Dead Timer %us, Interface-ID %s, Priority %u",
EXTRACT_16BITS(&hellop->hello_helloint),
EXTRACT_16BITS(&hellop->hello_deadint),
ipaddr_string(ndo, &hellop->hello_ifid),
hellop->hello_priority));
ND_TCHECK(hellop->hello_dr);
if (EXTRACT_32BITS(&hellop->hello_dr) != 0)
ND_PRINT((ndo, "\n\t  Designated Router %s",
ipaddr_string(ndo, &hellop->hello_dr)));
ND_TCHECK(hellop->hello_bdr);
if (EXTRACT_32BITS(&hellop->hello_bdr) != 0)
ND_PRINT((ndo, ", Backup Designated Router %s",
ipaddr_string(ndo, &hellop->hello_bdr)));
if (ndo->ndo_vflag > 1) {
ND_PRINT((ndo, "\n\t  Neighbor List:"));
ap = hellop->hello_neighbor;
while ((const u_char *)ap < dataend) {
ND_TCHECK(*ap);
ND_PRINT((ndo, "\n\t    %s", ipaddr_string(ndo, ap)));
++ap;
}
}
break;
}
case OSPF_TYPE_DD: {
register const struct dd6 *ddp = (const struct dd6 *)((const uint8_t *)op + OSPF6HDR_LEN);
ND_TCHECK(ddp->db_options);
ND_PRINT((ndo, "\n\tOptions [%s]",
bittok2str(ospf6_option_values, "none",
EXTRACT_32BITS(&ddp->db_options))));
ND_TCHECK(ddp->db_flags);
ND_PRINT((ndo, ", DD Flags [%s]",
bittok2str(ospf6_dd_flag_values,"none",ddp->db_flags)));
ND_TCHECK(ddp->db_seq);
ND_PRINT((ndo, ", MTU %u, DD-Sequence 0x%08x",
EXTRACT_16BITS(&ddp->db_mtu),
EXTRACT_32BITS(&ddp->db_seq)));
if (ndo->ndo_vflag > 1) {
lshp = ddp->db_lshdr;
while ((const u_char *)lshp < dataend) {
if (ospf6_print_lshdr(ndo, lshp++, dataend))
goto trunc;
}
}
break;
}
case OSPF_TYPE_LS_REQ:
if (ndo->ndo_vflag > 1) {
lsrp = (const struct lsr6 *)((const uint8_t *)op + OSPF6HDR_LEN);
while ((const u_char *)lsrp < dataend) {
ND_TCHECK(*lsrp);
ND_PRINT((ndo, "\n\t  Advertising Router %s",
ipaddr_string(ndo, &lsrp->ls_router)));
ospf6_print_ls_type(ndo, EXTRACT_16BITS(&lsrp->ls_type),
&lsrp->ls_stateid);
++lsrp;
}
}
break;
case OSPF_TYPE_LS_UPDATE:
if (ndo->ndo_vflag > 1) {
register const struct lsu6 *lsup = (const struct lsu6 *)((const uint8_t *)op + OSPF6HDR_LEN);
ND_TCHECK(lsup->lsu_count);
i = EXTRACT_32BITS(&lsup->lsu_count);
lsap = lsup->lsu_lsa;
while ((const u_char *)lsap < dataend && i--) {
if (ospf6_print_lsa(ndo, lsap, dataend))
goto trunc;
lsap = (const struct lsa6 *)((const u_char *)lsap +
EXTRACT_16BITS(&lsap->ls_hdr.ls_length));
}
}
break;
case OSPF_TYPE_LS_ACK:
if (ndo->ndo_vflag > 1) {
lshp = (const struct lsa6_hdr *)((const uint8_t *)op + OSPF6HDR_LEN);
while ((const u_char *)lshp < dataend) {
if (ospf6_print_lshdr(ndo, lshp++, dataend))
goto trunc;
}
}
break;
default:
break;
}
return (0);
trunc:
return (1);
}

static int set_core_reg(struct kvm_vcpu *vcpu, const struct kvm_one_reg *reg)
{
__u32 __user *uaddr = (__u32 __user *)(unsigned long)reg->addr;
struct kvm_regs *regs = vcpu_gp_regs(vcpu);
int nr_regs = sizeof(*regs) / sizeof(__u32);
__uint128_t tmp;
void *valp = &tmp;
u64 off;
int err = 0;
off = core_reg_offset_from_id(reg->id);
if (off >= nr_regs ||
(off + (KVM_REG_SIZE(reg->id) / sizeof(__u32))) >= nr_regs)
return -ENOENT;
if (validate_core_offset(reg))
return -EINVAL;
if (KVM_REG_SIZE(reg->id) > sizeof(tmp))
return -EINVAL;
if (copy_from_user(valp, uaddr, KVM_REG_SIZE(reg->id))) {
err = -EFAULT;
goto out;
}
if (off == KVM_REG_ARM_CORE_REG(regs.pstate)) {
u32 mode = (*(u32 *)valp) & PSR_AA32_MODE_MASK;
switch (mode) {
case PSR_AA32_MODE_USR:
case PSR_AA32_MODE_FIQ:
case PSR_AA32_MODE_IRQ:
case PSR_AA32_MODE_SVC:
case PSR_AA32_MODE_ABT:
case PSR_AA32_MODE_UND:
case PSR_MODE_EL0t:
case PSR_MODE_EL1t:
case PSR_MODE_EL1h:
break;
default:
err = -EINVAL;
goto out;
}
}
memcpy((u32 *)regs + off, valp, KVM_REG_SIZE(reg->id));
out:
return err;
}

void PackLinuxElf32::unpack(OutputFile *fo)
{
if (e_phoff != sizeof(Elf32_Ehdr)) {        throwCantUnpack("bad e_phoff");
}
unsigned const c_phnum = get_te16(&ehdri.e_phnum);
unsigned old_data_off = 0;
unsigned old_data_len = 0;
unsigned old_dtinit = 0;
unsigned is_asl = 0;  
unsigned szb_info = sizeof(b_info);
{
if (get_te32(&ehdri.e_entry) < 0x401180
&&  Elf32_Ehdr::EM_386 ==get_te16(&ehdri.e_machine)
&&  Elf32_Ehdr::ET_EXEC==get_te16(&ehdri.e_type)) {
szb_info = 2*sizeof(unsigned);
}
}
fi->seek(overlay_offset - sizeof(l_info), SEEK_SET);
fi->readx(&linfo, sizeof(linfo));
lsize = get_te16(&linfo.l_lsize);
if (UPX_MAGIC_LE32 != get_le32(&linfo.l_magic)) {
throwCantUnpack("l_info corrupted");
}
p_info hbuf;  fi->readx(&hbuf, sizeof(hbuf));
unsigned orig_file_size = get_te32(&hbuf.p_filesize);
blocksize = get_te32(&hbuf.p_blocksize);
if ((u32_t)file_size > orig_file_size || blocksize > orig_file_size
|| !mem_size_valid(1, blocksize, OVERHEAD))
throwCantUnpack("p_info corrupted");
ibuf.alloc(blocksize + OVERHEAD);
b_info bhdr; memset(&bhdr, 0, sizeof(bhdr));
fi->readx(&bhdr, szb_info);
ph.u_len = get_te32(&bhdr.sz_unc);
ph.c_len = get_te32(&bhdr.sz_cpr);
if (ph.c_len > (unsigned)file_size || ph.c_len == 0 || ph.u_len == 0
||  ph.u_len > orig_file_size)
throwCantUnpack("b_info corrupted");
ph.filter_cto = bhdr.b_cto8;
MemBuffer u(ph.u_len);
Elf32_Ehdr *const ehdr = (Elf32_Ehdr *)&u[0];
Elf32_Phdr const *phdr = 0;
if (ibuf.getSize() < ph.c_len) {
throwCompressedDataViolation();
}
fi->readx(ibuf, ph.c_len);
decompress(ibuf, (upx_byte *)ehdr, false);
if (ehdr->e_type   !=ehdri.e_type
||  ehdr->e_machine!=ehdri.e_machine
||  ehdr->e_version!=ehdri.e_version
||  ehdr->e_flags  !=ehdri.e_flags
||  ehdr->e_ehsize !=ehdri.e_ehsize
||  memcmp(ehdr->e_ident, ehdri.e_ident, Elf32_Ehdr::EI_OSABI)) {
throwCantUnpack("ElfXX_Ehdr corrupted");
}
fi->seek(- (off_t) (szb_info + ph.c_len), SEEK_CUR);
unsigned const u_phnum = get_te16(&ehdr->e_phnum);
unsigned total_in = 0;
unsigned total_out = 0;
unsigned c_adler = upx_adler32(NULL, 0);
unsigned u_adler = upx_adler32(NULL, 0);
#define MAX_ELF_HDR 512
if ((MAX_ELF_HDR - sizeof(Elf32_Ehdr))/sizeof(Elf32_Phdr) < u_phnum) {
throwCantUnpack("bad compressed e_phnum");
}
#undef MAX_ELF_HDR
Elf32_Phdr const *const dynhdr = elf_find_ptype(Elf32_Phdr::PT_DYNAMIC, phdri, c_phnum);
bool const is_shlib = !!dynhdr;
if (is_shlib) {
unpackExtent(ph.u_len, fo, total_in, total_out,
c_adler, u_adler, false, szb_info);
fi->seek(0, SEEK_SET);
fi->readx(ibuf, get_te32(&dynhdr->p_offset) + get_te32(&dynhdr->p_filesz));
overlay_offset -= sizeof(linfo);
xct_off = overlay_offset;
e_shoff = get_te32(&ehdri.e_shoff);
ibuf.subref("bad .e_shoff %#x for %#x", e_shoff, sizeof(Elf32_Shdr) * e_shnum);
if (e_shoff && e_shnum) {             shdri = (Elf32_Shdr  *)ibuf.subref(
"bad Shdr table", e_shoff, sizeof(Elf32_Shdr)*e_shnum);
unsigned xct_off2 = get_te32(&shdri->sh_offset);
if (e_shoff == xct_off2) {
xct_off = e_shoff;
}
dynseg = (Elf32_Dyn const *)ibuf.subref(
"bad DYNAMIC", get_te32(&dynhdr->p_offset), get_te32(&dynhdr->p_filesz));
dynstr = (char const *)elf_find_dynamic(Elf32_Dyn::DT_STRTAB);
sec_dynsym = elf_find_section_type(Elf32_Shdr::SHT_DYNSYM);
if (sec_dynsym) {
unsigned const off_dynsym = get_te32(&sec_dynsym->sh_offset);
unsigned const sz_dynsym  = get_te32(&sec_dynsym->sh_size);
Elf32_Sym *const sym0 = (Elf32_Sym *)ibuf.subref(
"bad dynsym", off_dynsym, sz_dynsym);
Elf32_Sym *sym = sym0;
for (int j = sz_dynsym / sizeof(Elf32_Sym); --j>=0; ++sym) {
unsigned symval = get_te32(&sym->st_value);
unsigned symsec = get_te16(&sym->st_shndx);
if (Elf32_Sym::SHN_UNDEF != symsec
&&  Elf32_Sym::SHN_ABS   != symsec
&&  xct_off <= symval) {
set_te32(&sym->st_value, symval - asl_delta);
}
if (Elf32_Sym::SHN_ABS == symsec && xct_off <= symval) {
adjABS(sym, 0u - asl_delta);
}
}
}
}
if (fo) {
fo->write(ibuf + ph.u_len, xct_off - ph.u_len);
}
int n_ptload = 0;
phdr = (Elf32_Phdr *) (void *) (1+ (Elf32_Ehdr *)(unsigned char *)ibuf);
for (unsigned j=0; j < u_phnum; ++phdr, ++j) {
if (PT_LOAD32==get_te32(&phdr->p_type) && 0!=n_ptload++) {
old_data_off = get_te32(&phdr->p_offset);
old_data_len = get_te32(&phdr->p_filesz);
break;
}
}
total_in  = xct_off;
total_out = xct_off;
ph.u_len = 0;
fi->seek(sizeof(linfo) + overlay_offset + sizeof(hbuf) + szb_info + ph.c_len, SEEK_SET);
phdr = (Elf32_Phdr *) (void *) (1+ ehdr);
for (unsigned j=0; j < u_phnum; ++phdr, ++j) {
if (PT_LOAD32==get_te32(&phdr->p_type)) {
ph.u_len = get_te32(&phdr->p_filesz) - xct_off;
break;
}
}
unpackExtent(ph.u_len, fo, total_in, total_out,
c_adler, u_adler, false, szb_info);
}
else {                  bool first_PF_X = true;
phdr = (Elf32_Phdr *) (void *) (1+ ehdr);          for (unsigned j=0; j < u_phnum; ++phdr, ++j) {
if (PT_LOAD32==get_te32(&phdr->p_type)) {
unsigned const filesz = get_te32(&phdr->p_filesz);
unsigned const offset = get_te32(&phdr->p_offset);
if (fo)
fo->seek(offset, SEEK_SET);
if (Elf32_Phdr::PF_X & get_te32(&phdr->p_flags)) {
unpackExtent(filesz, fo, total_in, total_out,
c_adler, u_adler, first_PF_X, szb_info);
first_PF_X = false;
}
else {
unpackExtent(filesz, fo, total_in, total_out,
c_adler, u_adler, false, szb_info);
}
}
}
}
phdr = phdri;
load_va = 0;
for (unsigned j=0; j < c_phnum; ++j) {
if (PT_LOAD32==get_te32(&phdr->p_type)) {
load_va = get_te32(&phdr->p_vaddr);
break;
}
}
if (0x1000==get_te32(&phdri[0].p_filesz)      &&  0==get_te32(&phdri[1].p_offset)
&&  0==get_te32(&phdri[0].p_offset)
&&     get_te32(&phdri[1].p_filesz) == get_te32(&phdri[1].p_memsz)) {
fi->seek(up4(get_te32(&phdr[1].p_memsz)), SEEK_SET);      }
else if (is_shlib
||  ((unsigned)(get_te32(&ehdri.e_entry) - load_va) + up4(lsize) +
ph.getPackHeaderSize() + sizeof(overlay_offset))
< up4(file_size)) {
funpad4(fi);          unsigned d_info[4]; fi->readx(d_info, sizeof(d_info));
if (0==old_dtinit) {
old_dtinit = get_te32(&d_info[2 + (0==d_info[0])]);
is_asl = 1u& get_te32(&d_info[0 + (0==d_info[0])]);
}
fi->seek(lsize - sizeof(d_info), SEEK_CUR);
}
phdr = (Elf32_Phdr *)&u[sizeof(*ehdr)];
unsigned hi_offset(0);
for (unsigned j = 0; j < u_phnum; ++j) {
if (PT_LOAD32==phdr[j].p_type
&&  hi_offset < phdr[j].p_offset)
hi_offset = phdr[j].p_offset;
}
for (unsigned j = 0; j < u_phnum; ++j) {
unsigned const size = find_LOAD_gap(phdr, j, u_phnum);
if (size) {
unsigned const where = get_te32(&phdr[j].p_offset) +
get_te32(&phdr[j].p_filesz);
if (fo)
fo->seek(where, SEEK_SET);
unpackExtent(size, fo, total_in, total_out,
c_adler, u_adler, false, szb_info,
(phdr[j].p_offset != hi_offset));
}
}
fi->readx(&bhdr, szb_info);
unsigned const sz_unc = ph.u_len = get_te32(&bhdr.sz_unc);
if (sz_unc == 0) {                 unsigned const sz_cpr = get_le32(&bhdr.sz_cpr);
if (sz_cpr != UPX_MAGIC_LE32)              throwCompressedDataViolation();
}
else {         throwCompressedDataViolation();
}
if (is_shlib) {
int n_ptload = 0;
unsigned load_off = 0;
phdr = (Elf32_Phdr *)&u[sizeof(*ehdr)];
for (unsigned j= 0; j < u_phnum; ++j, ++phdr) {
if (PT_LOAD32==get_te32(&phdr->p_type) && 0!=n_ptload++) {
load_off = get_te32(&phdr->p_offset);
load_va  = get_te32(&phdr->p_vaddr);
fi->seek(old_data_off, SEEK_SET);
fi->readx(ibuf, old_data_len);
total_in  += old_data_len;
total_out += old_data_len;
Elf32_Phdr const *udynhdr = (Elf32_Phdr *)&u[sizeof(*ehdr)];
for (unsigned j3= 0; j3 < u_phnum; ++j3, ++udynhdr)
if (Elf32_Phdr::PT_DYNAMIC==get_te32(&udynhdr->p_type)) {
unsigned dt_pltrelsz(0), dt_jmprel(0);
unsigned dt_relsz(0), dt_rel(0);
unsigned const dyn_len = get_te32(&udynhdr->p_filesz);
unsigned const dyn_off = get_te32(&udynhdr->p_offset);
if ((unsigned long)file_size < (dyn_len + dyn_off)) {
char msg[50]; snprintf(msg, sizeof(msg),
"bad PT_DYNAMIC .p_filesz %#x", dyn_len);
throwCantUnpack(msg);
}
if (dyn_off < load_off) {
continue;                      }
Elf32_Dyn *dyn = (Elf32_Dyn *)((unsigned char *)ibuf +
(dyn_off - load_off));
dynseg = dyn; invert_pt_dynamic(dynseg);
for (unsigned j2= 0; j2 < dyn_len; ++dyn, j2 += sizeof(*dyn)) {
unsigned const tag = get_te32(&dyn->d_tag);
unsigned       val = get_te32(&dyn->d_val);
if (is_asl) switch (tag) {
case Elf32_Dyn::DT_RELSZ:    { dt_relsz    = val; } break;
case Elf32_Dyn::DT_REL:      { dt_rel      = val; } break;
case Elf32_Dyn::DT_PLTRELSZ: { dt_pltrelsz = val; } break;
case Elf32_Dyn::DT_JMPREL:   { dt_jmprel   = val; } break;
case Elf32_Dyn::DT_PLTGOT:
case Elf32_Dyn::DT_PREINIT_ARRAY:
case Elf32_Dyn::DT_INIT_ARRAY:
case Elf32_Dyn::DT_FINI_ARRAY:
case Elf32_Dyn::DT_FINI: {
set_te32(&dyn->d_val, val -= asl_delta);
}; break;
}                         if (upx_dt_init == tag) {
if (Elf32_Dyn::DT_INIT == tag) {
set_te32(&dyn->d_val, old_dtinit);
if (!old_dtinit) {                                     dyn->d_tag = Elf32_Dyn::DT_NULL;
dyn->d_val = 0;
}
}
else if (Elf32_Dyn::DT_INIT_ARRAY    == tag
||       Elf32_Dyn::DT_PREINIT_ARRAY == tag) {
if (val < load_va || (unsigned)file_size < (unsigned)val) {
char msg[50]; snprintf(msg, sizeof(msg),
"Bad Dynamic tag %#x %#x",
(unsigned)tag, (unsigned)val);
throwCantUnpack(msg);
}
set_te32(&ibuf[val - load_va], old_dtinit
+ (is_asl ? asl_delta : 0));                              }
}
}
if (is_asl) {
lowmem.alloc(xct_off);
fi->seek(0, SEEK_SET);
fi->read(lowmem, xct_off);                          if (dt_relsz && dt_rel) {
Elf32_Rel *const rel0 = (Elf32_Rel *)lowmem.subref(
"bad Rel offset", dt_rel, dt_relsz);
unRel32(dt_rel, rel0, dt_relsz, ibuf, load_va, fo);
}
if (dt_pltrelsz && dt_jmprel) {                             Elf32_Rel *const jmp0 = (Elf32_Rel *)lowmem.subref(
"bad Jmprel offset", dt_jmprel, dt_pltrelsz);
unRel32(dt_jmprel, jmp0, dt_pltrelsz, ibuf, load_va, fo);
}
}
}
if (fo) {
fo->seek(get_te32(&phdr->p_offset), SEEK_SET);
fo->rewrite(ibuf, old_data_len);
}
}
}
}
ph.c_len = total_in;
ph.u_len = total_out;
if (total_out != orig_file_size)
throwEOFException();
if (ph.c_adler != c_adler || ph.u_adler != u_adler)
throwChecksumError();
}

static int
dissect_thrift_list(tvbuff_t* tvb, packet_info* pinfo _U_, proto_tree* tree, int offset, int length)
{
proto_tree *sub_tree;
proto_item *ti;
guint32 type;
int start_offset = offset, i;
guint32 list_len;
sub_tree = proto_tree_add_subtree(tree, tvb, offset, -1, ett_thrift, &ti, "List");
proto_tree_add_item_ret_uint(sub_tree, hf_thrift_type, tvb, offset, 1, ENC_BIG_ENDIAN, &type);
offset++;
proto_tree_add_item_ret_uint(sub_tree, hf_thrift_num_list_item, tvb, offset, 4, ENC_BIG_ENDIAN, &list_len);
offset += 4;
for (i = 0; i < (int)list_len; ++i) {
offset = dissect_thrift_type(tvb, pinfo, sub_tree, type, offset, length);
}
list_len = offset - start_offset;
proto_item_set_len(ti, list_len);
return offset;
}

uint32_t
wl_map_insert_new(struct wl_map *map, uint32_t flags, void *data)
{
union map_entry *start, *entry;
struct wl_array *entries;
uint32_t base;
if (map->side == WL_MAP_CLIENT_SIDE) {
entries = &map->client_entries;
base = 0;
} else {
entries = &map->server_entries;
base = WL_SERVER_ID_START;
}
if (map->free_list) {
start = entries->data;
entry = &start[map->free_list >> 1];
map->free_list = entry->next;
} else {
entry = wl_array_add(entries, sizeof *entry);
if (!entry)
return 0;
start = entries->data;
}
entry->data = data;
entry->next |= (flags & 0x1) << 1;
return (entry - start) + base;
}

const J9UTF8*
SH_CacheMap::getCachedUTFString(J9VMThread* currentThread, const char* local, U_16 localLen)
{
const char* fnName = "getCachedUTFString";
const J9UTF8* pathUTF = NULL;
U_8 temp[J9SH_MAXPATH + sizeof(J9UTF8)];
J9UTF8* temputf = (J9UTF8*)&temp;
char* tempstr = (char*)J9UTF8_DATA(temputf);
SH_ScopeManager* localSCM;
bool allowUpdate = true;
Trc_SHR_Assert_False(_ccHead->hasWriteMutex(currentThread));
if (!(localSCM = getScopeManager(currentThread))) {
return NULL;
}
Trc_SHR_CM_getCachedUTFString_entry(currentThread, localLen, local);
if (_ccHead->enterReadMutex(currentThread, fnName) != 0) {
Trc_SHR_CM_getCachedUTFString_FailedMutex(currentThread, localLen, local);
Trc_SHR_CM_getCachedUTFString_exit1(currentThread);
return NULL;
}
if (runEntryPointChecks(currentThread, NULL, NULL) == -1) {
_ccHead->exitReadMutex(currentThread, fnName);
Trc_SHR_CM_getCachedUTFString_exit1(currentThread);
return NULL;
}
if (J9_ARE_ANY_BITS_SET(*_runtimeFlags, RUNTIME_FLAGS_PREVENT_BLOCK_DATA_UPDATE)) {
allowUpdate = false;
}
J9UTF8_SET_LENGTH(temputf, localLen);
strncpy(tempstr, local, J9UTF8_LENGTH(temputf));
pathUTF = localSCM->findScopeForUTF(currentThread, temputf);
_ccHead->exitReadMutex(currentThread, fnName);
if (NULL == pathUTF) {
if (allowUpdate){
if (_ccHead->enterWriteMutex(currentThread, false, fnName) == 0) {
IDATA itemsRead;
if ((itemsRead = runEntryPointChecks(currentThread, NULL, NULL)) == -1) {
_ccHead->exitWriteMutex(currentThread, fnName);
Trc_SHR_CM_getCachedUTFString_exit3(currentThread);
return NULL;
}
if ((itemsRead == 0) || !(pathUTF = localSCM->findScopeForUTF(currentThread, temputf))) {
pathUTF = addScopeToCache(currentThread, temputf);
}
_ccHead->exitWriteMutex(currentThread, fnName);
}
} else {
increaseUnstoredBytes(J9UTF8_LENGTH(temputf) + sizeof(struct J9UTF8));
}
}
Trc_SHR_CM_getCachedUTFString_exit2(currentThread, pathUTF);
return pathUTF;
}

static int dict_load(const char *fname)
{
FILE *f;
char *ptr[4], *endptr;
int r, n = 0;
struct rad_dict_attr_t *attr = NULL;
struct rad_dict_value_t *val;
struct rad_dict_vendor_t *vendor;
struct list_head *items;
struct list_head *parent_items = NULL;
f = fopen(fname, "r");
if (!f) {
log_emerg("radius: open dictionary '%s': %s\n", fname, strerror(errno));
return -1;
}
items = &dict->items;
while (fgets(buf, BUF_SIZE, f)) {
n++;
if (buf[0] == '#' || buf[0] == '\n' || buf[0] == 0)
continue;
r = split(buf, ptr);
if (*ptr[r - 1] == '#')
r--;
if (!strcmp(buf, "VENDOR")) {
if (r < 2)
goto out_err_syntax;
vendor = malloc(sizeof(*vendor));
if (!vendor) {
log_emerg("radius: out of memory\n");
goto out_err;
}
vendor->id = strtol(ptr[1], &endptr, 10);
if (*endptr != 0)
goto out_err_syntax;
vendor->name = strdup(ptr[0]);
if (!vendor->name) {
log_emerg("radius: out of memory\n");
goto out_err;
}
if (r == 3) {
if (memcmp(ptr[2], "format=", 7))
goto out_err_syntax;
vendor->tag = strtoul(ptr[2] + 7, &endptr, 10);
if (*endptr != ',')
goto out_err_syntax;
vendor->len = strtoul(endptr + 1, &endptr, 10);
} else {
vendor->tag = 1;
vendor->len = 1;
}
INIT_LIST_HEAD(&vendor->items);
list_add_tail(&vendor->entry, &dict->vendors);
} else if (!strcmp(buf, "BEGIN-VENDOR")) {
if (r < 1)
goto out_err_syntax;
vendor = rad_dict_find_vendor_name(ptr[0]);
if (!vendor) {
log_emerg("radius:%s:%i: vendor not found\n", fname, n);
goto out_err;
}
items = &vendor->items;
} else if (!strcmp(buf, "END-VENDOR"))
items = &dict->items;
else if (!strcmp(buf, "$INCLUDE")) {
if (r < 1)
goto out_err_syntax;
for (r = strlen(path) - 1; r; r--)
if (path[r] == '/') {
path[r + 1] = 0;
break;
}
strcpy(fname1, path);
strcat(fname1, ptr[0]);
if (dict_load(fname1))
goto out_err;
} else if (!strcmp(buf, "BEGIN-TLV")) {
parent_items = items;
items = &attr->tlv;
} else if (!strcmp(buf, "END-TLV")) {
items = parent_items;
} else if (r > 2) {
if (!strcmp(buf, "ATTRIBUTE")) {
attr = malloc(sizeof(*attr));
if (!attr) {
log_emerg("radius: out of memory\n");
goto out_err;
}
memset(attr, 0, sizeof(*attr));
INIT_LIST_HEAD(&attr->values);
INIT_LIST_HEAD(&attr->tlv);
list_add_tail(&attr->entry, items);
attr->name = strdup(ptr[0]);
attr->id = strtol(ptr[1], &endptr, 10);
attr->array = 0;
attr->size = 0;
if (r > 3 && !strcmp(ptr[3], "array"))
attr->array = 1;
if (!strcmp(ptr[2], "integer")) {
attr->type = ATTR_TYPE_INTEGER;
attr->size = 4;
} else if (!strcmp(ptr[2], "short")) {
attr->type = ATTR_TYPE_INTEGER;
attr->size = 2;
} else if (!strcmp(ptr[2], "byte")) {
attr->type = ATTR_TYPE_INTEGER;
attr->size = 1;
} else if (!strcmp(ptr[2], "string"))
attr->type = ATTR_TYPE_STRING;
else if (!strcmp(ptr[2], "date"))
attr->type = ATTR_TYPE_DATE;
else if (!strcmp(ptr[2], "ipaddr"))
attr->type = ATTR_TYPE_IPADDR;
else if (!strcmp(ptr[2], "octets"))
attr->type = ATTR_TYPE_OCTETS;
else if (!strcmp(ptr[2], "ifid"))
attr->type = ATTR_TYPE_IFID;
else if (!strcmp(ptr[2], "ipv6addr"))
attr->type = ATTR_TYPE_IPV6ADDR;
else if (!strcmp(ptr[2], "ipv6prefix"))
attr->type = ATTR_TYPE_IPV6PREFIX;
else if (!strcmp(ptr[2], "ether"))
attr->type = ATTR_TYPE_ETHER;
else if (!strcmp(ptr[2], "tlv"))
attr->type = ATTR_TYPE_TLV;
else {
log_emerg("radius:%s:%i: unknown attribute type\n", fname, n);
goto out_err;
}
} else if (!strcmp(buf, "VALUE")) {
attr = find_attr(items, ptr[0]);
if (!attr) {
log_emerg("radius:%s:%i: unknown attribute\n", fname, n);
goto out_err;
}
val = malloc(sizeof(*val));
if (!val) {
log_emerg("radius: out of memory\n");
goto out_err;
}
memset(val, 0, sizeof(*val));
list_add_tail(&val->entry, &attr->values);
val->name = strdup(ptr[1]);
switch (attr->type) {
case ATTR_TYPE_INTEGER:
if (ptr[2][0] == '0' && ptr[2][1] == 'x')
val->val.integer = strtol(ptr[2] + 2, &endptr, 16);
else
val->val.integer = strtol(ptr[2], &endptr, 10);
if (*endptr != 0)
goto out_err_syntax;
break;
case ATTR_TYPE_STRING:
val->val.string = strdup(ptr[2]);
break;
case ATTR_TYPE_DATE:
log_warn("radius:%s:%i: VALUE of type 'date' is not implemented yet\n", fname, n);
break;
case ATTR_TYPE_IPADDR:
log_warn("radius:%s:%i: VALUE of type 'ipaddr' is not implemented yet\n", fname, n);
break;
}
} else
goto out_err_syntax;
} else
goto out_err_syntax;
}
fclose(f);
return 0;
out_err_syntax:
log_emerg("radius:%s:%i: syntax error\n", fname, n);
out_err:
fclose(f);
return -1;
}

static inline key_ref_t __key_update(key_ref_t key_ref,
struct key_preparsed_payload *prep)
{
struct key *key = key_ref_to_ptr(key_ref);
int ret;
ret = key_permission(key_ref, KEY_NEED_WRITE);
if (ret < 0)
goto error;
ret = -EEXIST;
if (!key->type->update)
goto error;
down_write(&key->sem);
ret = key->type->update(key, prep);
if (ret == 0)
clear_bit(KEY_FLAG_NEGATIVE, &key->flags);
up_write(&key->sem);
if (ret < 0)
goto error;
out:
return key_ref;
error:
key_put(key);
key_ref = ERR_PTR(ret);
goto out;
}

bool CdtmLoader::load(const std::string &filename, const CFileProvider &fp)
{
binistream *f = fp.open(filename); if(!f) return false;
const unsigned char conv_inst[11] = { 2,1,10,9,4,3,6,5,0,8,7 };
const unsigned short conv_note[12] = { 0x16B, 0x181, 0x198, 0x1B0, 0x1CA, 0x1E5, 0x202, 0x220, 0x241, 0x263, 0x287, 0x2AE };
int i,j,k,t=0;
f->readString(header.id, 12);
header.version = f->readInt(1);
f->readString(header.title, 20); f->readString(header.author, 20);
header.numpat = f->readInt(1); header.numinst = f->readInt(1);
if(memcmp(header.id,"DeFy DTM ",9) || header.version != 0x10)
{ fp.close (f); return false; }
header.numinst++;
memset(desc,0,80*16);
char bufstr[80];
for (i=0;i<16;i++)
{
unsigned char bufstr_length = f->readInt(1);
if(bufstr_length > 80) {
fp.close(f);
return false;
}
if (bufstr_length)
{
f->readString(bufstr,bufstr_length);
for (j=0;j<bufstr_length;j++)
if (!bufstr[j])
bufstr[j] = 0x20;
bufstr[bufstr_length] = 0;
strcat(desc,bufstr);
}
strcat(desc,"\n");
}
realloc_instruments(header.numinst);
realloc_order(100);
realloc_patterns(header.numpat,64,9);
init_notetable(conv_note);
init_trackord();
for (i=0;i<header.numinst;i++)
{
unsigned char name_length = f->readInt(1);
if (name_length)
f->readString(instruments[i].name, name_length);
instruments[i].name[name_length] = 0;
for(j = 0; j < 12; j++)
instruments[i].data[j] = f->readInt(1);
for (j=0;j<11;j++)
inst[i].data[conv_inst[j]] = instruments[i].data[j];
}
for(i = 0; i < 100; i++) order[i] = f->readInt(1);
nop = header.numpat;
unsigned char *pattern = new unsigned char [0x480];
for (i=0;i<nop;i++)
{
unsigned short packed_length;
packed_length = f->readInt(2);
unsigned char *packed_pattern = new unsigned char [packed_length];
for(j = 0; j < packed_length; j++)
packed_pattern[j] = f->readInt(1);
long unpacked_length = unpack_pattern(packed_pattern,packed_length,pattern,0x480);
delete [] packed_pattern;
if (!unpacked_length)
{
delete [] pattern;
fp.close(f);
return false;
}
for (j=0;j<9;j++)
{
for (k=0;k<64;k++)
{
dtm_event *event = (dtm_event *)&pattern[(k*9+j)*2];
if (event->byte0 == 0x80)
{
if (event->byte1 <= 0x80)
tracks[t][k].inst = event->byte1 + 1;
}
else
{
tracks[t][k].note = event->byte0;
if ((event->byte0 != 0) && (event->byte0 != 127))
tracks[t][k].note++;
switch (event->byte1 >> 4)
{
case 0x0:       if ((event->byte1 & 15) == 1)
tracks[t][k].command = 13;
break;
case 0x1:       tracks[t][k].command = 28;
tracks[t][k].param1 = event->byte1 & 15;
break;
case 0x2:       tracks[t][k].command = 28;
tracks[t][k].param2 = event->byte1 & 15;
break;
case 0xA:     case 0xC:       tracks[t][k].command = 22;
tracks[t][k].param1 = (0x3F - (event->byte1 & 15)) >> 4;
tracks[t][k].param2 = (0x3F - (event->byte1 & 15)) & 15;
break;
case 0xB:       tracks[t][k].command = 21;
tracks[t][k].param1 = (0x3F - (event->byte1 & 15)) >> 4;
tracks[t][k].param2 = (0x3F - (event->byte1 & 15)) & 15;
break;
case 0xE:       break;
case 0xF:       tracks[t][k].command = 13;
tracks[t][k].param2 = event->byte1 & 15;
break;
}
}
}
t++;
}
}
delete [] pattern;
fp.close(f);
for (i=0;i<100;i++)
{
if (order[i] >= 0x80)
{
length = i;
if (order[i] == 0xFF)
restartpos = 0;
else
restartpos = order[i] - 0x80;
break;
}
}
initspeed = 2;
rewind(0);
return true;
}

