int ksmbd_conn_handler_loop(void *p)
{
struct ksmbd_conn *conn = (struct ksmbd_conn *)p;
struct ksmbd_transport *t = conn->transport;
unsigned int pdu_size, max_allowed_pdu_size;
char hdr_buf[4] = {0,};
int size;
mutex_init(&conn->srv_mutex);
__module_get(THIS_MODULE);
if (t->ops->prepare && t->ops->prepare(t))
goto out;
conn->last_active = jiffies;
while (ksmbd_conn_alive(conn)) {
if (try_to_freeze())
continue;
kvfree(conn->request_buf);
conn->request_buf = NULL;
size = t->ops->read(t, hdr_buf, sizeof(hdr_buf), -1);
if (size != sizeof(hdr_buf))
break;
pdu_size = get_rfc1002_len(hdr_buf);
ksmbd_debug(CONN, "RFC1002 header %u bytes\n", pdu_size);
if (ksmbd_conn_good(conn))
max_allowed_pdu_size =
SMB3_MAX_MSGSIZE + conn->vals->max_write_size;
else
max_allowed_pdu_size = SMB3_MAX_MSGSIZE;
if (pdu_size > max_allowed_pdu_size) {
pr_err_ratelimited("PDU length(%u) exceeded maximum allowed pdu size(%u) on connection(%d)\n",
pdu_size, max_allowed_pdu_size,
READ_ONCE(conn->status));
break;
}
if (pdu_size > MAX_STREAM_PROT_LEN)
break;
if (pdu_size < SMB1_MIN_SUPPORTED_HEADER_SIZE)
break;
size = pdu_size + 4 + 1;
conn->request_buf = kvmalloc(size, GFP_KERNEL);
if (!conn->request_buf)
break;
memcpy(conn->request_buf, hdr_buf, sizeof(hdr_buf));
if (!ksmbd_smb_request(conn))
break;
size = t->ops->read(t, conn->request_buf + 4, pdu_size, 2);
if (size < 0) {
pr_err("sock_read failed: %d\n", size);
break;
}
if (size != pdu_size) {
pr_err("PDU error. Read: %d, Expected: %d\n",
size, pdu_size);
continue;
}
if (((struct smb2_hdr *)smb2_get_msg(conn->request_buf))->ProtocolId ==
SMB2_PROTO_NUMBER) {
if (pdu_size < SMB2_MIN_SUPPORTED_HEADER_SIZE)
break;
}
if (!default_conn_ops.process_fn) {
pr_err("No connection request callback\n");
break;
}
if (default_conn_ops.process_fn(conn)) {
pr_err("Cannot handle request\n");
break;
}
}
out:
ksmbd_conn_set_releasing(conn);
wait_event(conn->r_count_q, atomic_read(&conn->r_count) == 0);
if (IS_ENABLED(CONFIG_UNICODE))
utf8_unload(conn->um);
unload_nls(conn->local_nls);
if (default_conn_ops.terminate_fn)
default_conn_ops.terminate_fn(conn);
t->ops->disconnect(t);
module_put(THIS_MODULE);
return 0;
}

static int ms_lib_process_bootblock(struct us_data *us, u16 PhyBlock, u8 *PageData)
{
struct ms_bootblock_sysent *SysEntry;
struct ms_bootblock_sysinf *SysInfo;
u32 i, result;
u8 PageNumber;
u8 *PageBuffer;
struct ms_lib_type_extdat ExtraData;
struct ene_ub6250_info *info = (struct ene_ub6250_info *) us->extra;
PageBuffer = kmalloc(MS_BYTES_PER_PAGE, GFP_KERNEL);
if (PageBuffer == NULL)
return (u32)-1;
result = (u32)-1;
SysInfo = &(((struct ms_bootblock_page0 *)PageData)->sysinf);
if ((SysInfo->bMsClass != MS_SYSINF_MSCLASS_TYPE_1) ||
(be16_to_cpu(SysInfo->wPageSize) != MS_SYSINF_PAGE_SIZE) ||
((SysInfo->bSecuritySupport & MS_SYSINF_SECURITY) == MS_SYSINF_SECURITY_SUPPORT) ||
(SysInfo->bReserved1 != MS_SYSINF_RESERVED1) ||
(SysInfo->bReserved2 != MS_SYSINF_RESERVED2) ||
(SysInfo->bFormatType != MS_SYSINF_FORMAT_FAT) ||
(SysInfo->bUsage != MS_SYSINF_USAGE_GENERAL))
goto exit;
switch (info->MS_Lib.cardType = SysInfo->bCardType) {
case MS_SYSINF_CARDTYPE_RDONLY:
ms_lib_ctrl_set(info, MS_LIB_CTRL_RDONLY);
break;
case MS_SYSINF_CARDTYPE_RDWR:
ms_lib_ctrl_reset(info, MS_LIB_CTRL_RDONLY);
break;
case MS_SYSINF_CARDTYPE_HYBRID:
default:
goto exit;
}
info->MS_Lib.blockSize = be16_to_cpu(SysInfo->wBlockSize);
info->MS_Lib.NumberOfPhyBlock = be16_to_cpu(SysInfo->wBlockNumber);
info->MS_Lib.NumberOfLogBlock = be16_to_cpu(SysInfo->wTotalBlockNumber)-2;
info->MS_Lib.PagesPerBlock = info->MS_Lib.blockSize * SIZE_OF_KIRO / MS_BYTES_PER_PAGE;
info->MS_Lib.NumberOfSegment = info->MS_Lib.NumberOfPhyBlock / MS_PHYSICAL_BLOCKS_PER_SEGMENT;
info->MS_Model = be16_to_cpu(SysInfo->wMemorySize);
if (ms_lib_alloc_logicalmap(us))
goto exit;
ms_lib_set_bootblockmark(us, PhyBlock);
SysEntry = &(((struct ms_bootblock_page0 *)PageData)->sysent);
for (i = 0; i < MS_NUMBER_OF_SYSTEM_ENTRY; i++) {
u32  EntryOffset, EntrySize;
EntryOffset = be32_to_cpu(SysEntry->entry[i].dwStart);
if (EntryOffset == 0xffffff)
continue;
EntrySize = be32_to_cpu(SysEntry->entry[i].dwSize);
if (EntrySize == 0)
continue;
if (EntryOffset + MS_BYTES_PER_PAGE + EntrySize > info->MS_Lib.blockSize * (u32)SIZE_OF_KIRO)
continue;
if (i == 0) {
u8 PrevPageNumber = 0;
u16 phyblk;
if (SysEntry->entry[i].bType != MS_SYSENT_TYPE_INVALID_BLOCK)
goto exit;
while (EntrySize > 0) {
PageNumber = (u8)(EntryOffset / MS_BYTES_PER_PAGE + 1);
if (PageNumber != PrevPageNumber) {
switch (ms_read_readpage(us, PhyBlock, PageNumber, (u32 *)PageBuffer, &ExtraData)) {
case MS_STATUS_SUCCESS:
break;
case MS_STATUS_WRITE_PROTECT:
case MS_ERROR_FLASH_READ:
case MS_STATUS_ERROR:
default:
goto exit;
}
PrevPageNumber = PageNumber;
}
phyblk = be16_to_cpu(*(u16 *)(PageBuffer + (EntryOffset % MS_BYTES_PER_PAGE)));
if (phyblk < 0x0fff)
ms_lib_set_initialerrorblock(us, phyblk);
EntryOffset += 2;
EntrySize -= 2;
}
} else if (i == 1) {  
struct ms_bootblock_idi *idi;
if (SysEntry->entry[i].bType != MS_SYSENT_TYPE_CIS_IDI)
goto exit;
switch (ms_read_readpage(us, PhyBlock, (u8)(EntryOffset / MS_BYTES_PER_PAGE + 1), (u32 *)PageBuffer, &ExtraData)) {
case MS_STATUS_SUCCESS:
break;
case MS_STATUS_WRITE_PROTECT:
case MS_ERROR_FLASH_READ:
case MS_STATUS_ERROR:
default:
goto exit;
}
idi = &((struct ms_bootblock_cis_idi *)(PageBuffer + (EntryOffset % MS_BYTES_PER_PAGE)))->idi.idi;
if (le16_to_cpu(idi->wIDIgeneralConfiguration) != MS_IDI_GENERAL_CONF)
goto exit;
info->MS_Lib.BytesPerSector = le16_to_cpu(idi->wIDIbytesPerSector);
if (info->MS_Lib.BytesPerSector != MS_BYTES_PER_PAGE)
goto exit;
}
} 
result = 0;
exit:
if (result)
ms_lib_free_logicalmap(us);
kfree(PageBuffer);
result = 0;
return result;
}

ssize_t enc_untrusted_recvmsg(int sockfd, struct msghdr *msg, int flags) {
size_t total_buffer_size = CalculateTotalMessageSize(msg);
MessageWriter input;
input.Push(sockfd);
input.Push<uint64_t>(msg->msg_namelen);
input.Push<uint64_t>(total_buffer_size);
input.Push<uint64_t>(msg->msg_controllen);
input.Push(msg->msg_flags);
input.Push(flags);
MessageReader output;
const auto status = NonSystemCallDispatcher(
::asylo::host_call::kRecvMsgHandler, &input, &output);
CheckStatusAndParamCount(status, output, "enc_untrusted_recvmsg", 2,
false);
ssize_t result = output.next<ssize_t>();
int klinux_errno = output.next<int>();
if (result == -1) {
errno = FromkLinuxErrorNumber(klinux_errno);
return result;
}
auto msg_name_extent = output.next();
if (msg_name_extent.size() <= msg->msg_namelen) {
msg->msg_namelen = msg_name_extent.size();
}
memcpy(msg->msg_name, msg_name_extent.As<char>(), msg->msg_namelen);
auto msg_iov_extent = output.next();
size_t total_bytes = msg_iov_extent.size();
size_t bytes_copied = 0;
for (int i = 0; i < msg->msg_iovlen && bytes_copied < total_bytes; ++i) {
size_t bytes_to_copy =
std::min(msg->msg_iov[i].iov_len, total_bytes - bytes_copied);
memcpy(msg->msg_iov[i].iov_base, msg_iov_extent.As<char>() + bytes_copied,
bytes_to_copy);
bytes_copied += bytes_to_copy;
}
auto msg_control_extent = output.next();
if (msg_control_extent.size() <= msg->msg_controllen) {
msg->msg_controllen = msg_control_extent.size();
}
memcpy(msg->msg_control, msg_control_extent.As<char>(), msg->msg_controllen);
return result;
}

void WebPImage::doWriteMetadata(BasicIo& outIo)
{
if (!io_->isopen()) throw Error(kerInputDataReadFailed);
if (!outIo.isopen()) throw Error(kerImageWriteFailed);
#ifdef EXIV2_DEBUG_MESSAGES
std::cout << "Writing metadata" << std::endl;
#endif
byte    data   [WEBP_TAG_SIZE*3];
DataBuf chunkId(WEBP_TAG_SIZE+1);
chunkId.pData_ [WEBP_TAG_SIZE] = '\0';
io_->read(data, WEBP_TAG_SIZE * 3);
uint64_t filesize = Exiv2::getULong(data + WEBP_TAG_SIZE, littleEndian);
if (outIo.write(data, WEBP_TAG_SIZE * 3) != WEBP_TAG_SIZE * 3)
throw Error(kerImageWriteFailed);
bool has_size  = false;
bool has_xmp   = false;
bool has_exif  = false;
bool has_vp8x  = false;
bool has_alpha = false;
bool has_icc   = iccProfileDefined();
int width      = 0;
int height     = 0;
byte       size_buff[WEBP_TAG_SIZE];
Blob       blob;
if (exifData_.count() > 0) {
ExifParser::encode(blob, littleEndian, exifData_);
if (blob.size() > 0) {
has_exif = true;
}
}
if (xmpData_.count() > 0 && !writeXmpFromPacket()) {
XmpParser::encode(xmpPacket_, xmpData_,
XmpParser::useCompactFormat |
XmpParser::omitAllFormatting);
}
has_xmp = xmpPacket_.size() > 0;
std::string xmp(xmpPacket_);
while ( !io_->eof() && (uint64_t) io_->tell() < filesize) {
io_->read(chunkId.pData_, WEBP_TAG_SIZE);
io_->read(size_buff, WEBP_TAG_SIZE);
long size = Exiv2::getULong(size_buff, littleEndian);
DataBuf payload(size);
io_->read(payload.pData_, payload.size_);
byte c;
if ( payload.size_ % 2 ) io_->read(&c,1);
if (equalsWebPTag(chunkId, WEBP_CHUNK_HEADER_VP8X) && !has_vp8x) {
has_vp8x = true;
}
if (equalsWebPTag(chunkId, WEBP_CHUNK_HEADER_VP8X) && !has_size) {
has_size = true;
byte size_buf[WEBP_TAG_SIZE];
memcpy(&size_buf, &payload.pData_[4], 3);
size_buf[3] = 0;
width = Exiv2::getULong(size_buf, littleEndian) + 1;
memcpy(&size_buf, &payload.pData_[7], 3);
size_buf[3] = 0;
height = Exiv2::getULong(size_buf, littleEndian) + 1;
}
#ifdef __CHECK_FOR_ALPHA__              if (equalsWebPTag(chunkId, WEBP_CHUNK_HEADER_ANIM) && !has_alpha) {
has_alpha = true;
}
#endif
#ifdef __CHECK_FOR_ALPHA__             if (equalsWebPTag(chunkId, WEBP_CHUNK_HEADER_VP8) && !has_alpha) {
has_alpha = true;
}
#endif
if (equalsWebPTag(chunkId, WEBP_CHUNK_HEADER_VP8) && !has_size) {
has_size = true;
byte size_buf[2];
memcpy(&size_buf, &payload.pData_[6], 2);
width = Exiv2::getUShort(size_buf, littleEndian) & 0x3fff;
memcpy(&size_buf, &payload.pData_[8], 2);
height = Exiv2::getUShort(size_buf, littleEndian) & 0x3fff;
}
if (equalsWebPTag(chunkId, WEBP_CHUNK_HEADER_VP8L) && !has_alpha) {
if ((payload.pData_[4] & WEBP_VP8X_ALPHA_BIT) == WEBP_VP8X_ALPHA_BIT) {
has_alpha = true;
}
}
if (equalsWebPTag(chunkId, WEBP_CHUNK_HEADER_VP8L) && !has_size) {
has_size = true;
byte size_buf_w[2];
byte size_buf_h[3];
if (equalsWebPTag(chunkId, WEBP_CHUNK_HEADER_ANMF) && !has_alpha) {
if ((payload.pData_[5] & 0x2) == 0x2) {
has_alpha = true;
}
}
if (equalsWebPTag(chunkId, WEBP_CHUNK_HEADER_ANMF) && !has_size) {
has_size = true;
byte size_buf[WEBP_TAG_SIZE];
memcpy(&size_buf, &payload.pData_[6], 3);
size_buf[3] = 0;
width = Exiv2::getULong(size_buf, littleEndian) + 1;
memcpy(&size_buf, &payload.pData_[9], 3);
size_buf[3] = 0;
height = Exiv2::getULong(size_buf, littleEndian) + 1;
}
if (equalsWebPTag(chunkId, "ALPH") && !has_alpha) {
has_alpha = true;
}
}
if (!has_vp8x) {
inject_VP8X(outIo, has_xmp, has_exif, has_alpha,
has_icc, width, height);
}
io_->seek(12, BasicIo::beg);
while ( !io_->eof() && (uint64_t) io_->tell() < filesize) {
io_->read(chunkId.pData_, 4);
io_->read(size_buff, 4);
long size = Exiv2::getULong(size_buff, littleEndian);
DataBuf payload(size);
io_->read(payload.pData_, size);
if ( io_->tell() % 2 ) io_->seek(+1,BasicIo::cur); 
if (equalsWebPTag(chunkId, WEBP_CHUNK_HEADER_VP8X)) {
if (has_icc){
payload.pData_[0] |= WEBP_VP8X_ICC_BIT;
} else {
payload.pData_[0] &= ~WEBP_VP8X_ICC_BIT;
}
if (has_xmp){
payload.pData_[0] |= WEBP_VP8X_XMP_BIT;
} else {
payload.pData_[0] &= ~WEBP_VP8X_XMP_BIT;
}
if (has_exif) {
payload.pData_[0] |= WEBP_VP8X_EXIF_BIT;
} else {
payload.pData_[0] &= ~WEBP_VP8X_EXIF_BIT;
}
if (outIo.write(chunkId.pData_, WEBP_TAG_SIZE) != WEBP_TAG_SIZE)
throw Error(kerImageWriteFailed);
if (outIo.write(size_buff, WEBP_TAG_SIZE) != WEBP_TAG_SIZE)
throw Error(kerImageWriteFailed);
if (outIo.write(payload.pData_, payload.size_) != payload.size_)
throw Error(kerImageWriteFailed);
if (outIo.tell() % 2) {
if (outIo.write(&WEBP_PAD_ODD, 1) != 1) throw Error(kerImageWriteFailed);
}
if (has_icc) {
if (outIo.write((const byte*)WEBP_CHUNK_HEADER_ICCP, WEBP_TAG_SIZE) != WEBP_TAG_SIZE) throw Error(kerImageWriteFailed);
ul2Data(data, (uint32_t) iccProfile_.size_, littleEndian);
if (outIo.write(data, WEBP_TAG_SIZE) != WEBP_TAG_SIZE) throw Error(kerImageWriteFailed);
if (outIo.write(iccProfile_.pData_, iccProfile_.size_) != iccProfile_.size_) {
throw Error(kerImageWriteFailed);
}
has_icc = false;
}
} else if (equalsWebPTag(chunkId, WEBP_CHUNK_HEADER_ICCP)) {
} else if (equalsWebPTag(chunkId, WEBP_CHUNK_HEADER_EXIF)) {
} else if (equalsWebPTag(chunkId, WEBP_CHUNK_HEADER_XMP)) {
} else {
if (outIo.write(chunkId.pData_, WEBP_TAG_SIZE) != WEBP_TAG_SIZE)
throw Error(kerImageWriteFailed);
if (outIo.write(size_buff, WEBP_TAG_SIZE) != WEBP_TAG_SIZE)
throw Error(kerImageWriteFailed);
if (outIo.write(payload.pData_, payload.size_) != payload.size_)
throw Error(kerImageWriteFailed);
}
if (outIo.tell() % 2) {
if (outIo.write(&WEBP_PAD_ODD, 1) != 1) throw Error(kerImageWriteFailed);
}
}
if (has_exif) {
if (outIo.write((const byte*)WEBP_CHUNK_HEADER_EXIF, WEBP_TAG_SIZE) != WEBP_TAG_SIZE) throw Error(kerImageWriteFailed);
us2Data(data, (uint16_t) blob.size()+8, bigEndian);
ul2Data(data, (uint32_t) blob.size(), littleEndian);
if (outIo.write(data, WEBP_TAG_SIZE) != WEBP_TAG_SIZE) throw Error(kerImageWriteFailed);
if (outIo.write((const byte*)&blob[0], static_cast<long>(blob.size())) != (long)blob.size())
{
throw Error(kerImageWriteFailed);
}
if (outIo.tell() % 2) {
if (outIo.write(&WEBP_PAD_ODD, 1) != 1) throw Error(kerImageWriteFailed);
}
}
if (has_xmp) {
if (outIo.write((const byte*)WEBP_CHUNK_HEADER_XMP, WEBP_TAG_SIZE) != WEBP_TAG_SIZE) throw Error(kerImageWriteFailed);
ul2Data(data, (uint32_t) xmpPacket().size(), littleEndian);
if (outIo.write(data, WEBP_TAG_SIZE) != WEBP_TAG_SIZE) throw Error(kerImageWriteFailed);
if (outIo.write((const byte*)xmp.data(), static_cast<long>(xmp.size())) != (long)xmp.size()) {
throw Error(kerImageWriteFailed);
}
if (outIo.tell() % 2) {
if (outIo.write(&WEBP_PAD_ODD, 1) != 1) throw Error(kerImageWriteFailed);
}
}
outIo.seek(0, BasicIo::beg);
filesize = outIo.size() - 8;
outIo.seek(4, BasicIo::beg);
ul2Data(data, (uint32_t) filesize, littleEndian);
if (outIo.write(data, WEBP_TAG_SIZE) != WEBP_TAG_SIZE) throw Error(kerImageWriteFailed);
}

int
commonio_sort (struct commonio_db *db, int (*cmp) (const void *, const void *))
{
struct commonio_entry **entries, *ptr;
size_t n = 0, i;
#if KEEP_NIS_AT_END
struct commonio_entry *nis = NULL;
#endif
for (ptr = db->head;
(NULL != ptr)
#if KEEP_NIS_AT_END
&& (NULL != ptr->line)
&& (   ('+' != ptr->line[0])
&& ('-' != ptr->line[0]))
#endif
;
ptr = ptr->next) {
n++;
}
#if KEEP_NIS_AT_END
if ((NULL != ptr) && (NULL != ptr->line)) {
nis = ptr;
}
#endif
if (n <= 1) {
return 0;
}
entries = malloc (n * sizeof (struct commonio_entry *));
if (entries == NULL) {
return -1;
}
n = 0;
for (ptr = db->head;
#if KEEP_NIS_AT_END
nis != ptr;
#else
NULL != ptr;
#endif
ptr = ptr->next
) {
entries[n] = ptr;
n++;
}
qsort (entries, n, sizeof (struct commonio_entry *), cmp);
db->head = entries[0];
n--;
#if KEEP_NIS_AT_END
if (NULL == nis)
#endif
{
db->tail = entries[n];
}
db->head->prev = NULL;
db->head->next = entries[1];
entries[n]->prev = entries[n - 1];
#if KEEP_NIS_AT_END
entries[n]->next = nis;
#else
entries[n]->next = NULL;
#endif
for (i = 1; i < n; i++) {
entries[i]->prev = entries[i - 1];
entries[i]->next = entries[i + 1];
}
free (entries);
db->changed = true;
return 0;
}

void posixtimer_rearm(struct siginfo *info)
{
struct k_itimer *timr;
unsigned long flags;
timr = lock_timer(info->si_tid, &flags);
if (!timr)
return;
if (timr->it_requeue_pending == info->si_sys_private) {
timr->kclock->timer_rearm(timr);
timr->it_active = 1;
timr->it_overrun_last = timr->it_overrun;
timr->it_overrun = -1;
++timr->it_requeue_pending;
info->si_overrun += timr->it_overrun_last;
}
unlock_timer(timr, flags);
}

BZIP3_API s32 bz3_decode_block(struct bz3_state * state, u8 * buffer, s32 data_size, s32 orig_size) {
u32 crc32 = read_neutral_s32(buffer);
s32 bwt_idx = read_neutral_s32(buffer + 4);
if (data_size > bz3_bound(state->block_size) || data_size < 0) {
state->last_error = BZ3_ERR_MALFORMED_HEADER;
return -1;
}
if (bwt_idx == -1) {
if (data_size - 8 > 64) {
state->last_error = BZ3_ERR_MALFORMED_HEADER;
return -1;
}
memmove(buffer, buffer + 8, data_size - 8);
if (crc32sum(1, buffer, data_size - 8) != crc32) {
state->last_error = BZ3_ERR_CRC;
return -1;
}
return data_size - 8;
}
s8 model = buffer[8];
s32 lzp_size = -1, rle_size = -1, p = 0;
if (model & 2) lzp_size = read_neutral_s32(buffer + 9 + 4 * p++);
if (model & 4) rle_size = read_neutral_s32(buffer + 9 + 4 * p++);
p += 2;
data_size -= p * 4 + 1;
if (((model & 2) && (lzp_size > bz3_bound(state->block_size) || lzp_size < 0)) ||
((model & 4) && (rle_size > bz3_bound(state->block_size) || rle_size < 0))) {
state->last_error = BZ3_ERR_MALFORMED_HEADER;
return -1;
}
if (orig_size > bz3_bound(state->block_size) || orig_size < 0) {
state->last_error = BZ3_ERR_MALFORMED_HEADER;
return -1;
}
u8 *b1 = buffer, *b2 = state->swap_buffer;
begin(state->cm_state);
state->cm_state->in_queue = b1 + p * 4 + 1;
state->cm_state->input_ptr = 0;
state->cm_state->input_max = data_size;
s32 size_src;
if (model & 2)
size_src = lzp_size;
else if (model & 4)
size_src = rle_size;
else
size_src = orig_size;
decode_bytes(state->cm_state, b2, size_src);
swap(b1, b2);
if (bwt_idx >= size_src) {
state->last_error = BZ3_ERR_MALFORMED_HEADER;
return -1;
}
if (libsais_unbwt(b1, b2, state->sais_array, size_src, NULL, bwt_idx) < 0) {
state->last_error = BZ3_ERR_BWT;
return -1;
}
swap(b1, b2);
if (model & 2) {
size_src = lzp_decompress(b1, b2, lzp_size, bz3_bound(state->block_size), state->lzp_lut);
if (size_src == -1) {
state->last_error = BZ3_ERR_CRC;
return -1;
}
swap(b1, b2);
}
if (model & 4) {
mrled(b1, b2, orig_size);
size_src = orig_size;
swap(b1, b2);
}
state->last_error = BZ3_OK;
if (size_src > bz3_bound(state->block_size) || size_src < 0) {
state->last_error = BZ3_ERR_MALFORMED_HEADER;
return -1;
}
if (b1 != buffer) memcpy(buffer, b1, size_src);
if (crc32 != crc32sum(1, buffer, size_src)) {
state->last_error = BZ3_ERR_CRC;
return -1;
}
return size_src;
}

static void
input_l2cap_frame_flow_channel(l2cap_channel_t *channel, uint8_t *data, uint16_t data_len)
{
uint16_t frame_len;
uint16_t payload_len;
if(data_len < 4) {
LOG_WARN("l2cap_frame: illegal L2CAP frame data_len: %d\n", data_len);
return;
}
if(channel->rx_buffer.sdu_length == 0) {
memcpy(&frame_len, &data[0], 2);
payload_len = frame_len - 2;
if(payload_len > BLE_L2CAP_NODE_MTU) {
LOG_WARN("l2cap_frame: illegal L2CAP frame payload_len: %d\n", payload_len);
return;
}
memcpy(&channel->rx_buffer.sdu_length, &data[4], 2);
memcpy(channel->rx_buffer.sdu, &data[6], payload_len);
channel->rx_buffer.current_index = payload_len;
} else {
memcpy(&frame_len, &data[0], 2);
payload_len = frame_len;
if(channel->rx_buffer.current_index + payload_len > BLE_L2CAP_NODE_MTU) {
LOG_WARN("l2cap_frame: illegal L2CAP frame payload_len: %d\n", payload_len);
return;
}
memcpy(&channel->rx_buffer.sdu[channel->rx_buffer.current_index], &data[4], payload_len);
channel->rx_buffer.current_index += payload_len;
}
if((channel->rx_buffer.sdu_length > 0) &&
(channel->rx_buffer.sdu_length == channel->rx_buffer.current_index)) {
memcpy(packetbuf_dataptr(), channel->rx_buffer.sdu, channel->rx_buffer.sdu_length);
packetbuf_set_datalen(channel->rx_buffer.sdu_length);
NETSTACK_NETWORK.input();
channel->rx_buffer.sdu_length = 0;
channel->rx_buffer.current_index = 0;
}
}

static void queue_delete(struct snd_seq_queue *q)
{
snd_seq_timer_stop(q->timer);
snd_seq_timer_close(q);
snd_use_lock_sync(&q->use_lock);
snd_seq_prioq_delete(&q->tickq);
snd_seq_prioq_delete(&q->timeq);
snd_seq_timer_delete(&q->timer);
kfree(q);
}

MRB_API mrb_value
mrb_obj_clone(mrb_state *mrb, mrb_value self)
{
struct RObject *p;
mrb_value clone;
if (mrb_immediate_p(self)) {
mrb_raisef(mrb, E_TYPE_ERROR, "can't clone %S", self);
}
if (mrb_type(self) == MRB_TT_SCLASS) {
mrb_raise(mrb, E_TYPE_ERROR, "can't clone singleton class");
}
p = (struct RObject*)mrb_obj_alloc(mrb, mrb_type(self), mrb_obj_class(mrb, self));
p->c = mrb_singleton_class_clone(mrb, self);
mrb_field_write_barrier(mrb, (struct RBasic*)p, (struct RBasic*)p->c);
clone = mrb_obj_value(p);
init_copy(mrb, clone, self);
p->flags = mrb_obj_ptr(self)->flags;
return clone;
}

MmsValue*
MmsValue_decodeMmsData(uint8_t* buffer, int bufPos, int bufferLength, int* endBufPos)
{
MmsValue* value = NULL;
int dataEndBufPos = bufPos + bufferLength;
uint8_t tag = buffer[bufPos++];
int dataLength;
bufPos = BerDecoder_decodeLength(buffer, &dataLength, bufPos, dataEndBufPos);
if (bufPos < 0)
goto exit_with_error;
switch (tag) {
case 0xa1: 
case 0xa2: 
{
int elementCount = getNumberOfElements(buffer, bufPos, dataLength);
if (elementCount < 0)
goto exit_with_error;
if (tag == 0xa1)
value = MmsValue_createEmptyArray(elementCount);
else
value = MmsValue_createEmptyStructure(elementCount);
int i;
for (i = 0; i < elementCount; i++) {
int elementLength;
int newBufPos = BerDecoder_decodeLength(buffer, &elementLength, bufPos + 1, dataEndBufPos);
if (newBufPos < 0)
goto exit_with_error;
if (newBufPos + elementLength > dataEndBufPos)
goto exit_with_error;
int elementBufLength = newBufPos - bufPos + elementLength;
MmsValue* elementValue = MmsValue_decodeMmsData(buffer, bufPos, elementBufLength, NULL);
if (elementValue == NULL)
goto exit_with_error;
MmsValue_setElement(value, i, elementValue);
bufPos = newBufPos + elementLength;
}
if (value == NULL)
goto exit_with_error;
}
break;
case 0x80: 
value = MmsValue_newDataAccessError((MmsDataAccessError) BerDecoder_decodeUint32(buffer, dataLength, bufPos));
bufPos += dataLength;
break;
case 0x83: 
value = MmsValue_newBoolean(BerDecoder_decodeBoolean(buffer, bufPos));
bufPos += dataLength;
break;
case 0x84: 
{
int padding = buffer[bufPos];
int bitStringLength = (8 * (dataLength - 1)) - padding;
value = MmsValue_newBitString(bitStringLength);
memcpy(value->value.bitString.buf, buffer + bufPos + 1, dataLength - 1);
bufPos += dataLength;
}
break;
case 0x85: 
if (dataLength > 8)
goto exit_with_error;
value = MmsValue_newInteger(dataLength * 8);
memcpy(value->value.integer->octets, buffer + bufPos, dataLength);
value->value.integer->size = dataLength;
bufPos += dataLength;
break;
case 0x86: 
if (dataLength > 8)
goto exit_with_error;
value = MmsValue_newUnsigned(dataLength * 8);
memcpy(value->value.integer->octets, buffer + bufPos, dataLength);
value->value.integer->size = dataLength;
bufPos += dataLength;
break;
case 0x87: 
if (dataLength == 9)
value = MmsValue_newDouble(BerDecoder_decodeDouble(buffer, bufPos));
else if (dataLength == 5)
value = MmsValue_newFloat(BerDecoder_decodeFloat(buffer, bufPos));
bufPos += dataLength;
break;
case 0x89: 
value = MmsValue_newOctetString(dataLength, dataLength);
memcpy(value->value.octetString.buf, buffer + bufPos, dataLength);
bufPos += dataLength;
break;
case 0x8a: 
value = MmsValue_newVisibleStringFromByteArray(buffer + bufPos, dataLength);
bufPos += dataLength;
break;
case 0x8c: 
if (dataLength == 4)
value = MmsValue_newBinaryTime(true);
else if (dataLength == 6)
value = MmsValue_newBinaryTime(false);
if ((dataLength == 4) || (dataLength == 6))
memcpy(value->value.binaryTime.buf, buffer + bufPos, dataLength);
bufPos += dataLength;
break;
case 0x90: 
value = MmsValue_newVisibleStringFromByteArray(buffer + bufPos, dataLength);
value->type = MMS_STRING;
bufPos += dataLength;
break;
case 0x91: 
if (dataLength == 8) {
value = MmsValue_newUtcTime(0);
MmsValue_setUtcTimeByBuffer(value, buffer + bufPos);
bufPos += dataLength;
}
else
goto exit_with_error;
break;
default: 
goto exit_with_error;
}
if (endBufPos != NULL)
*endBufPos = bufPos;
return value;
exit_with_error:
if (value != NULL)
MmsValue_delete(value);
return NULL;
}

static int32_t pkg_createWithAssemblyCode(const char *targetDir, const char mode, const char *gencFilePath) {
char tempObjectFile[SMALL_BUFFER_MAX_SIZE] = "";
char *cmd;
int32_t result = 0;
int32_t length = 0;
uprv_strcpy(tempObjectFile, gencFilePath);
tempObjectFile[uprv_strlen(tempObjectFile)-1] = 'o';
length = static_cast<int32_t>(uprv_strlen(pkgDataFlags[COMPILER]) + uprv_strlen(pkgDataFlags[LIBFLAGS])
+ uprv_strlen(tempObjectFile) + uprv_strlen(gencFilePath) + BUFFER_PADDING_SIZE);
cmd = (char *)uprv_malloc(sizeof(char) * length);
if (cmd == NULL) {
return -1;
}
sprintf(cmd, "%s %s -o %s %s",
pkgDataFlags[COMPILER],
pkgDataFlags[LIBFLAGS],
tempObjectFile,
gencFilePath);
result = runCommand(cmd);
uprv_free(cmd);
if (result != 0) {
fprintf(stderr, "Error creating with assembly code. Failed command: %s\n", cmd);
return result;
}
return pkg_generateLibraryFile(targetDir, mode, tempObjectFile);
}

static void pci_vtsock_proc_tx(struct pci_vtsock_softc *sc,
struct vqueue_info *vq)
{
struct pci_vtsock_sock *sock;
struct iovec iov_array[VTSOCK_MAXSEGS], *iov = iov_array;
uint16_t idx, flags[VTSOCK_MAXSEGS];
struct virtio_sock_hdr hdr;
int iovec_len;
size_t pulled;
iovec_len = vq_getchain(vq, &idx, iov, VTSOCK_MAXSEGS, flags);
assert(iovec_len <= VTSOCK_MAXSEGS);
DPRINTF(("TX: chain with %d buffers at idx %"PRIx16"\n",
iovec_len, idx));
dprint_chain(iov, iovec_len, "TX");
pulled = iovec_pull(&iov, &iovec_len, &hdr, sizeof(hdr));
assert(pulled == sizeof(hdr));
dprint_header(&hdr, 1, "TX");
dprint_iovec(iov, iovec_len, "TX");
if (hdr.src_cid != sc->vssc_cfg.guest_cid ||
hdr.dst_cid != VMADDR_CID_HOST ||
hdr.type != VIRTIO_VSOCK_TYPE_STREAM) {
DPRINTF(("TX: Bad src/dst address/type\n"));
send_response_nosock(sc, VIRTIO_VSOCK_OP_RST,
hdr.type,
(struct vsock_addr) {
.cid = hdr.dst_cid,
.port =hdr.dst_port
},
(struct vsock_addr) {
.cid = hdr.src_cid,
.port =hdr.src_port
});
vq_relchain(vq, idx, 0);
return;
}
sock = lookup_sock(sc, VIRTIO_VSOCK_TYPE_STREAM,
(struct vsock_addr) {
.cid = hdr.dst_cid,
.port =hdr.dst_port
},
(struct vsock_addr) {
.cid = hdr.src_cid,
.port =hdr.src_port
});
if (sock) {
sock->peer_buf_alloc = hdr.buf_alloc;
sock->peer_fwd_cnt = hdr.fwd_cnt;
}
switch (hdr.op) {
case VIRTIO_VSOCK_OP_INVALID:
PPRINTF(("TX: => INVALID\n"));
goto do_rst;
case VIRTIO_VSOCK_OP_REQUEST:
if (sock) {
PPRINTF(("TX: Attempt to reconnect sock\n"));
goto do_rst;
}
if (hdr.dst_cid == sc->vssc_cfg.guest_cid) {
PPRINTF(("TX: Attempt to connect back to guest\n!"));
goto do_rst;
}
sock = connect_sock(sc,
(struct vsock_addr){
.cid = hdr.dst_cid, .port = hdr.dst_port
},
(struct vsock_addr){
.cid = hdr.src_cid, .port = hdr.src_port
}, hdr.buf_alloc, hdr.fwd_cnt);
if (!sock) {
PPRINTF(("TX: Failed to open sock\n"));
goto do_rst;
}
send_response_sock(sc, VIRTIO_VSOCK_OP_RESPONSE, 0, sock);
vq_relchain(vq, idx, 0);
break;
case VIRTIO_VSOCK_OP_RESPONSE:
if (!sock) {
PPRINTF(("TX: RESPONSE to non-existent sock\n"));
goto do_rst;
}
if (sock->state != SOCK_CONNECTING) {
PPRINTF(("TX: RESPONSE to non-connecting sock (state %d)\n",
sock->state));
goto do_rst;
}
PPRINTF(("TX: SOCK connected (%d) "PRIaddr" <=> "PRIaddr"\n",
sock->fd, FMTADDR(sock->local_addr), FMTADDR(sock->peer_addr)));
sock->state = SOCK_CONNECTED;
vq_relchain(vq, idx, 0);
kick_rx(sc, "new outgoing sock");
break;
case VIRTIO_VSOCK_OP_RST:
if (!sock)
PPRINTF(("TX: RST to non-existent sock\n"));
close_sock(sc, sock, "TX");
vq_relchain(vq, idx, 0);
break;
case VIRTIO_VSOCK_OP_SHUTDOWN:
if (!sock) {
DPRINTF(("TX: SHUTDOWN to non-existent sock "PRIcid"."PRIport"\n",
hdr.dst_cid, hdr.dst_port));
goto do_rst;
}
if (sock->state != SOCK_CONNECTED) {
PPRINTF(("TX: SHUTDOWN to non-connected sock (state %d)\n",
sock->state));
goto do_rst;
}
if (hdr.flags & ~VIRTIO_VSOCK_FLAG_SHUTDOWN_ALL) {
PPRINTF(("TX: SHUTDOWN with reserved flags %"PRIx32"\n",
hdr.flags));
goto do_rst; 
}
if (!(hdr.flags & VIRTIO_VSOCK_FLAG_SHUTDOWN_ALL)) {
PPRINTF(("TX: SHUTDOWN with no flags %"PRIx32"\n",
hdr.flags));
goto do_rst; 
}
shutdown_peer_local_fd(sock, hdr.flags, "TX");
if (sock->peer_shutdown == VIRTIO_VSOCK_FLAG_SHUTDOWN_ALL)
goto do_rst;
vq_relchain(vq, idx, 0);
break;
case VIRTIO_VSOCK_OP_RW:
{
int rc;
if (!sock) {
PPRINTF(("TX: RW with no sock\n"));
goto do_rst;
}
if (sock->state != SOCK_CONNECTED) {
PPRINTF(("TX: RW to non-connected sock (state %d)\n",
sock->state));
goto do_rst;
}
if (sock->peer_shutdown & VIRTIO_VSOCK_FLAG_SHUTDOWN_TX) {
PPRINTF(("TX: RW to socket with peer_shutdown.TX\n"));
goto do_rst;
}
if (sock->local_shutdown & VIRTIO_VSOCK_FLAG_SHUTDOWN_RX) {
PPRINTF(("TX: RW to socket with local_shutdown.RX\n"));
goto do_rst;
}
rc = handle_write(sc, sock, hdr.len, iov, iovec_len);
if (rc < 0) goto do_rst;
vq_relchain(vq, idx, 0);
if (rc == 1)
set_credit_update_required(sc, sock);
break;
}
case VIRTIO_VSOCK_OP_CREDIT_UPDATE:
if (!sock) {
PPRINTF(("TX: CREDIT_UPDATE to non-existent sock\n"));
goto do_rst;
}
if (sock->state != SOCK_CONNECTED) {
PPRINTF(("TX: CREDIT_UPDATE to non-connected sock (state %d)\n",
sock->state));
goto do_rst;
}
vq_relchain(vq, idx, 0);
sc->rx_kick_pending = true;
break;
case VIRTIO_VSOCK_OP_CREDIT_REQUEST:
if (!sock) {
PPRINTF(("TX: CREDIT_REQUEST to non-existent sock\n"));
goto do_rst;
}
if (sock->state != SOCK_CONNECTED) {
PPRINTF(("TX: CREDIT_REQUEST to non-connected sock (state %d)\n",
sock->state));
goto do_rst;
}
vq_relchain(vq, idx, 0);
set_credit_update_required(sc, sock);
break;
}
if (sock)
put_sock(sock);
return;
do_rst:
if (sock)
send_response_sock(sc, VIRTIO_VSOCK_OP_RST, 0, sock);
else
send_response_nosock(sc, VIRTIO_VSOCK_OP_RST, hdr.type,
(struct vsock_addr) {
.cid = hdr.dst_cid,
.port =hdr.dst_port
},
(struct vsock_addr) {
.cid = hdr.src_cid,
.port =hdr.src_port
});
vq_relchain(vq, idx, 0);
close_sock(sc, sock, "TX");
if (sock) put_sock(sock);
return;
}

static void pci_vtsock_proc_tx(struct pci_vtsock_softc *sc,
struct vqueue_info *vq)
{
struct pci_vtsock_sock *sock;
struct iovec iov_array[VTSOCK_MAXSEGS], *iov = iov_array;
uint16_t idx, flags[VTSOCK_MAXSEGS];
struct virtio_sock_hdr hdr;
int iovec_len;
size_t pulled;
iovec_len = vq_getchain(vq, &idx, iov, VTSOCK_MAXSEGS, flags);
assert(iovec_len <= VTSOCK_MAXSEGS);
DPRINTF(("TX: chain with %d buffers at idx %"PRIx16"\n",
iovec_len, idx));
dprint_chain(iov, iovec_len, "TX");
pulled = iovec_pull(&iov, &iovec_len, &hdr, sizeof(hdr));
assert(pulled == sizeof(hdr));
dprint_header(&hdr, 1, "TX");
dprint_iovec(iov, iovec_len, "TX");
if (hdr.src_cid != sc->vssc_cfg.guest_cid ||
hdr.dst_cid != VMADDR_CID_HOST ||
hdr.type != VIRTIO_VSOCK_TYPE_STREAM) {
DPRINTF(("TX: Bad src/dst address/type\n"));
send_response_nosock(sc, VIRTIO_VSOCK_OP_RST,
hdr.type,
(struct vsock_addr) {
.cid = hdr.dst_cid,
.port =hdr.dst_port
},
(struct vsock_addr) {
.cid = hdr.src_cid,
.port =hdr.src_port
});
vq_relchain(vq, idx, 0);
return;
}
sock = lookup_sock(sc, VIRTIO_VSOCK_TYPE_STREAM,
(struct vsock_addr) {
.cid = hdr.dst_cid,
.port =hdr.dst_port
},
(struct vsock_addr) {
.cid = hdr.src_cid,
.port =hdr.src_port
});
if (sock) {
sock->peer_buf_alloc = hdr.buf_alloc;
sock->peer_fwd_cnt = hdr.fwd_cnt;
}
switch (hdr.op) {
case VIRTIO_VSOCK_OP_INVALID:
PPRINTF(("TX: => INVALID\n"));
goto do_rst;
case VIRTIO_VSOCK_OP_REQUEST:
if (sock) {
PPRINTF(("TX: Attempt to reconnect sock\n"));
goto do_rst;
}
if (hdr.dst_cid == sc->vssc_cfg.guest_cid) {
PPRINTF(("TX: Attempt to connect back to guest\n!"));
goto do_rst;
}
sock = connect_sock(sc,
(struct vsock_addr){
.cid = hdr.dst_cid, .port = hdr.dst_port
},
(struct vsock_addr){
.cid = hdr.src_cid, .port = hdr.src_port
}, hdr.buf_alloc, hdr.fwd_cnt);
if (!sock) {
PPRINTF(("TX: Failed to open sock\n"));
goto do_rst;
}
send_response_sock(sc, VIRTIO_VSOCK_OP_RESPONSE, 0, sock);
vq_relchain(vq, idx, 0);
break;
case VIRTIO_VSOCK_OP_RESPONSE:
if (!sock) {
PPRINTF(("TX: RESPONSE to non-existent sock\n"));
goto do_rst;
}
if (sock->state != SOCK_CONNECTING) {
PPRINTF(("TX: RESPONSE to non-connecting sock (state %d)\n",
sock->state));
goto do_rst;
}
PPRINTF(("TX: SOCK connected (%d) "PRIaddr" <=> "PRIaddr"\n",
sock->fd, FMTADDR(sock->local_addr), FMTADDR(sock->peer_addr)));
sock->state = SOCK_CONNECTED;
vq_relchain(vq, idx, 0);
kick_rx(sc, "new outgoing sock");
break;
case VIRTIO_VSOCK_OP_RST:
if (!sock)
PPRINTF(("TX: RST to non-existent sock\n"));
close_sock(sc, sock, "TX");
vq_relchain(vq, idx, 0);
break;
case VIRTIO_VSOCK_OP_SHUTDOWN:
if (!sock) {
DPRINTF(("TX: SHUTDOWN to non-existent sock "PRIcid"."PRIport"\n",
hdr.dst_cid, hdr.dst_port));
goto do_rst;
}
if (sock->state != SOCK_CONNECTED) {
PPRINTF(("TX: SHUTDOWN to non-connected sock (state %d)\n",
sock->state));
goto do_rst;
}
if (hdr.flags & ~VIRTIO_VSOCK_FLAG_SHUTDOWN_ALL) {
PPRINTF(("TX: SHUTDOWN with reserved flags %"PRIx32"\n",
hdr.flags));
goto do_rst; 
}
if (!(hdr.flags & VIRTIO_VSOCK_FLAG_SHUTDOWN_ALL)) {
PPRINTF(("TX: SHUTDOWN with no flags %"PRIx32"\n",
hdr.flags));
goto do_rst; 
}
shutdown_peer_local_fd(sock, hdr.flags, "TX");
if (sock->peer_shutdown == VIRTIO_VSOCK_FLAG_SHUTDOWN_ALL)
goto do_rst;
vq_relchain(vq, idx, 0);
break;
case VIRTIO_VSOCK_OP_RW:
{
int rc;
if (!sock) {
PPRINTF(("TX: RW with no sock\n"));
goto do_rst;
}
if (sock->state != SOCK_CONNECTED) {
PPRINTF(("TX: RW to non-connected sock (state %d)\n",
sock->state));
goto do_rst;
}
if (sock->peer_shutdown & VIRTIO_VSOCK_FLAG_SHUTDOWN_TX) {
PPRINTF(("TX: RW to socket with peer_shutdown.TX\n"));
goto do_rst;
}
if (sock->local_shutdown & VIRTIO_VSOCK_FLAG_SHUTDOWN_RX) {
PPRINTF(("TX: RW to socket with local_shutdown.RX\n"));
goto do_rst;
}
rc = handle_write(sc, sock, hdr.len, iov, iovec_len);
if (rc < 0) goto do_rst;
vq_relchain(vq, idx, 0);
if (rc == 1)
set_credit_update_required(sc, sock);
break;
}
case VIRTIO_VSOCK_OP_CREDIT_UPDATE:
if (!sock) {
PPRINTF(("TX: CREDIT_UPDATE to non-existent sock\n"));
goto do_rst;
}
if (sock->state != SOCK_CONNECTED) {
PPRINTF(("TX: CREDIT_UPDATE to non-connected sock (state %d)\n",
sock->state));
goto do_rst;
}
vq_relchain(vq, idx, 0);
sc->rx_kick_pending = true;
break;
case VIRTIO_VSOCK_OP_CREDIT_REQUEST:
if (!sock) {
PPRINTF(("TX: CREDIT_REQUEST to non-existent sock\n"));
goto do_rst;
}
if (sock->state != SOCK_CONNECTED) {
PPRINTF(("TX: CREDIT_REQUEST to non-connected sock (state %d)\n",
sock->state));
goto do_rst;
}
vq_relchain(vq, idx, 0);
set_credit_update_required(sc, sock);
break;
}
if (sock)
put_sock(sock);
return;
do_rst:
if (sock)
send_response_sock(sc, VIRTIO_VSOCK_OP_RST, 0, sock);
else
send_response_nosock(sc, VIRTIO_VSOCK_OP_RST, hdr.type,
(struct vsock_addr) {
.cid = hdr.dst_cid,
.port =hdr.dst_port
},
(struct vsock_addr) {
.cid = hdr.src_cid,
.port =hdr.src_port
});
vq_relchain(vq, idx, 0);
close_sock(sc, sock, "TX");
if (sock) put_sock(sock);
return;
}

static void setbit(uint8_t *addr,size_t i){
addr[i / 8] |= (1<<((7-i)&7));
}

static OPJ_BOOL opj_pi_next_cprl(opj_pi_iterator_t * pi) {
opj_pi_comp_t *comp = NULL;
opj_pi_resolution_t *res = NULL;
OPJ_UINT32 index = 0;
if (!pi->first) {
comp = &pi->comps[pi->compno];
goto LABEL_SKIP;
} else {
pi->first = 0;
}
for (pi->compno = pi->poc.compno0; pi->compno < pi->poc.compno1; pi->compno++) {
OPJ_UINT32 resno;
comp = &pi->comps[pi->compno];
pi->dx = 0;
pi->dy = 0;
for (resno = 0; resno < comp->numresolutions; resno++) {
OPJ_UINT32 dx, dy;
res = &comp->resolutions[resno];
dx = comp->dx * (1u << (res->pdx + comp->numresolutions - 1 - resno));
dy = comp->dy * (1u << (res->pdy + comp->numresolutions - 1 - resno));
pi->dx = !pi->dx ? dx : opj_uint_min(pi->dx, dx);
pi->dy = !pi->dy ? dy : opj_uint_min(pi->dy, dy);
}
if (!pi->tp_on){
pi->poc.ty0 = pi->ty0;
pi->poc.tx0 = pi->tx0;
pi->poc.ty1 = pi->ty1;
pi->poc.tx1 = pi->tx1;
}
for (pi->y = pi->poc.ty0; pi->y < pi->poc.ty1; pi->y += (OPJ_INT32)(pi->dy - (OPJ_UINT32)(pi->y % (OPJ_INT32)pi->dy))) {
for (pi->x = pi->poc.tx0; pi->x < pi->poc.tx1; pi->x += (OPJ_INT32)(pi->dx - (OPJ_UINT32)(pi->x % (OPJ_INT32)pi->dx))) {
for (pi->resno = pi->poc.resno0; pi->resno < opj_uint_min(pi->poc.resno1, comp->numresolutions); pi->resno++) {
OPJ_UINT32 levelno;
OPJ_INT32 trx0, try0;
OPJ_INT32 trx1, try1;
OPJ_UINT32 rpx, rpy;
OPJ_INT32 prci, prcj;
res = &comp->resolutions[pi->resno];
levelno = comp->numresolutions - 1 - pi->resno;
trx0 = opj_int_ceildiv(pi->tx0, (OPJ_INT32)(comp->dx << levelno));
try0 = opj_int_ceildiv(pi->ty0, (OPJ_INT32)(comp->dy << levelno));
trx1 = opj_int_ceildiv(pi->tx1, (OPJ_INT32)(comp->dx << levelno));
try1 = opj_int_ceildiv(pi->ty1, (OPJ_INT32)(comp->dy << levelno));
rpx = res->pdx + levelno;
rpy = res->pdy + levelno;
if (!((pi->y % (OPJ_INT32)(comp->dy << rpy) == 0) || ((pi->y == pi->ty0) && ((try0 << levelno) % (1 << rpy))))){
continue;
}
if (!((pi->x % (OPJ_INT32)(comp->dx << rpx) == 0) || ((pi->x == pi->tx0) && ((trx0 << levelno) % (1 << rpx))))){
continue;
}
if ((res->pw==0)||(res->ph==0)) continue;
if ((trx0==trx1)||(try0==try1)) continue;
prci = opj_int_floordivpow2(opj_int_ceildiv(pi->x, (OPJ_INT32)(comp->dx << levelno)), (OPJ_INT32)res->pdx)
- opj_int_floordivpow2(trx0, (OPJ_INT32)res->pdx);
prcj = opj_int_floordivpow2(opj_int_ceildiv(pi->y, (OPJ_INT32)(comp->dy << levelno)), (OPJ_INT32)res->pdy)
- opj_int_floordivpow2(try0, (OPJ_INT32)res->pdy);
pi->precno = (OPJ_UINT32)(prci + prcj * (OPJ_INT32)res->pw);
for (pi->layno = pi->poc.layno0; pi->layno < pi->poc.layno1; pi->layno++) {
index = pi->layno * pi->step_l + pi->resno * pi->step_r + pi->compno * pi->step_c + pi->precno * pi->step_p;
if (!pi->include[index]) {
pi->include[index] = 1;
return OPJ_TRUE;
}
LABEL_SKIP:;
}
}
}
}
}
return OPJ_FALSE;
}

