static int uvesafb_setcmap(struct fb_cmap *cmap, struct fb_info *info)
{
struct uvesafb_pal_entry *entries;
int shift = 16 - dac_width;
int i, err = 0;
if (info->var.bits_per_pixel == 8) {
if (cmap->start + cmap->len > info->cmap.start +
info->cmap.len || cmap->start < info->cmap.start)
return -EINVAL;
entries = kmalloc(sizeof(*entries) * cmap->len, GFP_KERNEL);
if (!entries)
return -ENOMEM;
for (i = 0; i < cmap->len; i++) {
entries[i].red   = cmap->red[i]   >> shift;
entries[i].green = cmap->green[i] >> shift;
entries[i].blue  = cmap->blue[i]  >> shift;
entries[i].pad   = 0;
}
err = uvesafb_setpalette(entries, cmap->len, cmap->start, info);
kfree(entries);
} else {
for (i = 0; i < cmap->len; i++) {
err |= uvesafb_setcolreg(cmap->start + i, cmap->red[i],
cmap->green[i], cmap->blue[i],
0, info);
}
}
return err;
}

static void intel_hda_response(HDACodecDevice *dev, bool solicited, uint32_t response)
{
const MemTxAttrs attrs = MEMTXATTRS_UNSPECIFIED;
HDACodecBus *bus = HDA_BUS(dev->qdev.parent_bus);
IntelHDAState *d = container_of(bus, IntelHDAState, codecs);
hwaddr addr;
uint32_t wp, ex;
MemTxResult res = MEMTX_OK;
if (d->ics & ICH6_IRS_BUSY) {
dprint(d, 2, "%s: [irr] response 0x%x, cad 0x%x\n",
__func__, response, dev->cad);
d->irr = response;
d->ics &= ~(ICH6_IRS_BUSY | 0xf0);
d->ics |= (ICH6_IRS_VALID | (dev->cad << 4));
return;
}
if (!(d->rirb_ctl & ICH6_RBCTL_DMA_EN)) {
dprint(d, 1, "%s: rirb dma disabled, drop codec response\n", __func__);
return;
}
ex = (solicited ? 0 : (1 << 4)) | dev->cad;
wp = (d->rirb_wp + 1) & 0xff;
addr = intel_hda_addr(d->rirb_lbase, d->rirb_ubase);
res |= stl_le_pci_dma(&d->pci, addr + 8 * wp, response, attrs);
res |= stl_le_pci_dma(&d->pci, addr + 8 * wp + 4, ex, attrs);
if (res != MEMTX_OK && (d->rirb_ctl & ICH6_RBCTL_OVERRUN_EN)) {
d->rirb_sts |= ICH6_RBSTS_OVERRUN;
intel_hda_update_irq(d);
}
d->rirb_wp = wp;
dprint(d, 2, "%s: [wp 0x%x] response 0x%x, extra 0x%x\n",
__func__, wp, response, ex);
d->rirb_count++;
if (d->rirb_count == d->rirb_cnt) {
dprint(d, 2, "%s: rirb count reached (%d)\n", __func__, d->rirb_count);
if (d->rirb_ctl & ICH6_RBCTL_IRQ_EN) {
d->rirb_sts |= ICH6_RBSTS_IRQ;
intel_hda_update_irq(d);
}
} else if ((d->corb_rp & 0xff) == d->corb_wp) {
dprint(d, 2, "%s: corb ring empty (%d/%d)\n", __func__,
d->rirb_count, d->rirb_cnt);
if (d->rirb_ctl & ICH6_RBCTL_IRQ_EN) {
d->rirb_sts |= ICH6_RBSTS_IRQ;
intel_hda_update_irq(d);
}
}
}

void
pdf_repair_xref(fz_context *ctx, pdf_document *doc)
{
pdf_obj *dict, *obj = NULL;
pdf_obj *length;
pdf_obj *encrypt = NULL;
pdf_obj *id = NULL;
pdf_obj **roots = NULL;
pdf_obj *info = NULL;
struct entry *list = NULL;
int listlen;
int listcap;
int maxnum = 0;
int num = 0;
int gen = 0;
int64_t tmpofs, stm_ofs, numofs = 0, genofs = 0;
int stm_len;
pdf_token tok;
int next;
int i;
size_t j, n;
int c;
pdf_lexbuf *buf = &doc->lexbuf.base;
int num_roots = 0;
int max_roots = 0;
fz_var(encrypt);
fz_var(id);
fz_var(roots);
fz_var(num_roots);
fz_var(max_roots);
fz_var(info);
fz_var(list);
fz_var(obj);
fz_warn(ctx, "repairing PDF document");
if (doc->repair_attempted)
fz_throw(ctx, FZ_ERROR_GENERIC, "Repair failed already - not trying again");
doc->repair_attempted = 1;
doc->dirty = 1;
doc->freeze_updates = 1; 
pdf_forget_xref(ctx, doc);
fz_seek(ctx, doc->file, 0, 0);
fz_try(ctx)
{
pdf_xref_entry *entry;
listlen = 0;
listcap = 1024;
list = fz_malloc_array(ctx, listcap, sizeof(struct entry));
n = fz_read(ctx, doc->file, (unsigned char *)buf->scratch, fz_mini(buf->size, 1024));
fz_seek(ctx, doc->file, 0, 0);
if (n >= 4)
{
for (j = 0; j < n - 4; j++)
{
if (memcmp(&buf->scratch[j], "%PDF", 4) == 0)
{
fz_seek(ctx, doc->file, (int64_t)(j + 8), 0); 
break;
}
}
}
c = fz_read_byte(ctx, doc->file);
while (c >= 0 && (c == ' ' || c == '%'))
c = fz_read_byte(ctx, doc->file);
fz_unread_byte(ctx, doc->file);
while (1)
{
tmpofs = fz_tell(ctx, doc->file);
if (tmpofs < 0)
fz_throw(ctx, FZ_ERROR_GENERIC, "cannot tell in file");
fz_try(ctx)
tok = pdf_lex_no_string(ctx, doc->file, buf);
fz_catch(ctx)
{
fz_rethrow_if(ctx, FZ_ERROR_TRYLATER);
fz_warn(ctx, "skipping ahead to next token");
do
c = fz_read_byte(ctx, doc->file);
while (c != EOF && !is_white(c));
continue;
}
have_next_token:
if (tok == PDF_TOK_INT)
{
if (buf->i < 0)
{
num = 0;
gen = 0;
continue;
}
numofs = genofs;
num = gen;
genofs = tmpofs;
gen = buf->i;
}
else if (tok == PDF_TOK_OBJ)
{
pdf_obj *root = NULL;
fz_try(ctx)
{
stm_len = 0;
stm_ofs = 0;
tok = pdf_repair_obj(ctx, doc, buf, &stm_ofs, &stm_len, &encrypt, &id, NULL, &tmpofs, &root);
if (root)
add_root(ctx, root, &roots, &num_roots, &max_roots);
}
fz_always(ctx)
{
pdf_drop_obj(ctx, root);
}
fz_catch(ctx)
{
fz_rethrow_if(ctx, FZ_ERROR_TRYLATER);
if (!roots)
fz_rethrow(ctx);
fz_warn(ctx, "cannot parse object (%d %d R) - ignoring rest of file", num, gen);
break;
}
if (num <= 0 || num > MAX_OBJECT_NUMBER)
{
fz_warn(ctx, "ignoring object with invalid object number (%d %d R)", num, gen);
goto have_next_token;
}
gen = fz_clampi(gen, 0, 65535);
if (listlen + 1 == listcap)
{
listcap = (listcap * 3) / 2;
list = fz_resize_array(ctx, list, listcap, sizeof(struct entry));
}
list[listlen].num = num;
list[listlen].gen = gen;
list[listlen].ofs = numofs;
list[listlen].stm_ofs = stm_ofs;
list[listlen].stm_len = stm_len;
listlen ++;
if (num > maxnum)
maxnum = num;
goto have_next_token;
}
else if (tok == PDF_TOK_OPEN_DICT)
{
fz_try(ctx)
{
dict = pdf_parse_dict(ctx, doc, doc->file, buf);
}
fz_catch(ctx)
{
fz_rethrow_if(ctx, FZ_ERROR_TRYLATER);
continue;
}
fz_try(ctx)
{
obj = pdf_dict_get(ctx, dict, PDF_NAME_Encrypt);
if (obj)
{
pdf_drop_obj(ctx, encrypt);
encrypt = pdf_keep_obj(ctx, obj);
}
obj = pdf_dict_get(ctx, dict, PDF_NAME_ID);
if (obj && (!id || !encrypt || pdf_dict_get(ctx, dict, PDF_NAME_Encrypt)))
{
pdf_drop_obj(ctx, id);
id = pdf_keep_obj(ctx, obj);
}
obj = pdf_dict_get(ctx, dict, PDF_NAME_Root);
if (obj)
add_root(ctx, obj, &roots, &num_roots, &max_roots);
obj = pdf_dict_get(ctx, dict, PDF_NAME_Info);
if (obj)
{
pdf_drop_obj(ctx, info);
info = pdf_keep_obj(ctx, obj);
}
}
fz_always(ctx)
pdf_drop_obj(ctx, dict);
fz_catch(ctx)
fz_rethrow(ctx);
obj = NULL;
}
else if (tok == PDF_TOK_EOF)
break;
else
{
if (tok == PDF_TOK_ERROR)
fz_read_byte(ctx, doc->file);
num = 0;
gen = 0;
}
}
if (listlen == 0)
fz_throw(ctx, FZ_ERROR_GENERIC, "no objects found");
pdf_ensure_solid_xref(ctx, doc, maxnum);
for (i = 1; i < maxnum; i++)
{
entry = pdf_get_populating_xref_entry(ctx, doc, i);
if (entry->obj != NULL)
continue;
entry->type = 'f';
entry->ofs = 0;
entry->gen = 0;
entry->num = 0;
entry->stm_ofs = 0;
}
for (i = 0; i < listlen; i++)
{
entry = pdf_get_populating_xref_entry(ctx, doc, list[i].num);
entry->type = 'n';
entry->ofs = list[i].ofs;
entry->gen = list[i].gen;
entry->num = list[i].num;
entry->stm_ofs = list[i].stm_ofs;
if (!encrypt && list[i].stm_len >= 0)
{
pdf_obj *old_obj = NULL;
dict = pdf_load_object(ctx, doc, list[i].num);
fz_try(ctx)
{
length = pdf_new_int(ctx, doc, list[i].stm_len);
pdf_dict_get_put_drop(ctx, dict, PDF_NAME_Length, length, &old_obj);
if (old_obj)
orphan_object(ctx, doc, old_obj);
}
fz_always(ctx)
pdf_drop_obj(ctx, dict);
fz_catch(ctx)
fz_rethrow(ctx);
}
}
entry = pdf_get_populating_xref_entry(ctx, doc, 0);
entry->type = 'f';
entry->ofs = 0;
entry->gen = 65535;
entry->num = 0;
entry->stm_ofs = 0;
next = 0;
for (i = pdf_xref_len(ctx, doc) - 1; i >= 0; i--)
{
entry = pdf_get_populating_xref_entry(ctx, doc, i);
if (entry->type == 'f')
{
entry->ofs = next;
if (entry->gen < 65535)
entry->gen ++;
next = i;
}
}
obj = pdf_new_dict(ctx, doc, 5);
pdf_set_populating_xref_trailer(ctx, doc, obj);
pdf_drop_obj(ctx, obj);
obj = NULL;
obj = pdf_new_int(ctx, doc, maxnum + 1);
pdf_dict_put(ctx, pdf_trailer(ctx, doc), PDF_NAME_Size, obj);
pdf_drop_obj(ctx, obj);
obj = NULL;
if (roots)
{
for (i = num_roots-1; i > 0; i--)
{
if (pdf_is_dict(ctx, roots[i]))
break;
}
if (i >= 0)
{
pdf_dict_put(ctx, pdf_trailer(ctx, doc), PDF_NAME_Root, roots[i]);
}
}
if (info)
{
pdf_dict_put(ctx, pdf_trailer(ctx, doc), PDF_NAME_Info, info);
pdf_drop_obj(ctx, info);
info = NULL;
}
if (encrypt)
{
if (pdf_is_indirect(ctx, encrypt))
{
obj = pdf_new_indirect(ctx, doc, pdf_to_num(ctx, encrypt), pdf_to_gen(ctx, encrypt));
pdf_drop_obj(ctx, encrypt);
encrypt = obj;
obj = NULL;
}
pdf_dict_put(ctx, pdf_trailer(ctx, doc), PDF_NAME_Encrypt, encrypt);
pdf_drop_obj(ctx, encrypt);
encrypt = NULL;
}
if (id)
{
if (pdf_is_indirect(ctx, id))
{
obj = pdf_new_indirect(ctx, doc, pdf_to_num(ctx, id), pdf_to_gen(ctx, id));
pdf_drop_obj(ctx, id);
id = obj;
obj = NULL;
}
pdf_dict_put(ctx, pdf_trailer(ctx, doc), PDF_NAME_ID, id);
pdf_drop_obj(ctx, id);
id = NULL;
}
fz_free(ctx, list);
}
fz_always(ctx)
{
for (i = 0; i < num_roots; i++)
pdf_drop_obj(ctx, roots[i]);
fz_free(ctx, roots);
}
fz_catch(ctx)
{
pdf_drop_obj(ctx, encrypt);
pdf_drop_obj(ctx, id);
pdf_drop_obj(ctx, obj);
pdf_drop_obj(ctx, info);
fz_free(ctx, list);
fz_rethrow(ctx);
}
}

MagickExport Image *CloneImage(const Image *image,const size_t columns,
const size_t rows,const MagickBooleanType detach,ExceptionInfo *exception)
{
Image
*clone_image;
double
scale;
size_t
length;
assert(image != (const Image *) NULL);
assert(image->signature == MagickCoreSignature);
if (image->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",image->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
if ((image->columns == 0) || (image->rows == 0))
{
(void) ThrowMagickException(exception,GetMagickModule(),CorruptImageError,
"NegativeOrZeroImageSize","`%s'",image->filename);
return((Image *) NULL);
}
clone_image=(Image *) AcquireMagickMemory(sizeof(*clone_image));
if (clone_image == (Image *) NULL)
ThrowImageException(ResourceLimitError,"MemoryAllocationFailed");
(void) ResetMagickMemory(clone_image,0,sizeof(*clone_image));
clone_image->signature=MagickCoreSignature;
clone_image->storage_class=image->storage_class;
clone_image->number_channels=image->number_channels;
clone_image->number_meta_channels=image->number_meta_channels;
clone_image->metacontent_extent=image->metacontent_extent;
clone_image->colorspace=image->colorspace;
clone_image->read_mask=image->read_mask;
clone_image->write_mask=image->write_mask;
clone_image->alpha_trait=image->alpha_trait;
clone_image->columns=image->columns;
clone_image->rows=image->rows;
clone_image->dither=image->dither;
if (image->colormap != (PixelInfo *) NULL)
{
clone_image->colors=image->colors;
length=(size_t) image->colors;
clone_image->colormap=(PixelInfo *) AcquireQuantumMemory(length,
sizeof(*clone_image->colormap));
if (clone_image->colormap == (PixelInfo *) NULL)
ThrowImageException(ResourceLimitError,"MemoryAllocationFailed");
(void) CopyMagickMemory(clone_image->colormap,image->colormap,length*
sizeof(*clone_image->colormap));
}
clone_image->image_info=CloneImageInfo(image->image_info);
(void) CloneImageProfiles(clone_image,image);
(void) CloneImageProperties(clone_image,image);
(void) CloneImageArtifacts(clone_image,image);
GetTimerInfo(&clone_image->timer);
if (image->ascii85 != (void *) NULL)
Ascii85Initialize(clone_image);
clone_image->magick_columns=image->magick_columns;
clone_image->magick_rows=image->magick_rows;
clone_image->type=image->type;
clone_image->channel_mask=image->channel_mask;
clone_image->channel_map=ClonePixelChannelMap(image->channel_map);
(void) CopyMagickString(clone_image->magick_filename,image->magick_filename,
MagickPathExtent);
(void) CopyMagickString(clone_image->magick,image->magick,MagickPathExtent);
(void) CopyMagickString(clone_image->filename,image->filename,
MagickPathExtent);
clone_image->progress_monitor=image->progress_monitor;
clone_image->client_data=image->client_data;
clone_image->reference_count=1;
clone_image->next=image->next;
clone_image->previous=image->previous;
clone_image->list=NewImageList();
if (detach == MagickFalse)
clone_image->blob=ReferenceBlob(image->blob);
else
{
clone_image->next=NewImageList();
clone_image->previous=NewImageList();
clone_image->blob=CloneBlobInfo((BlobInfo *) NULL);
}
clone_image->ping=image->ping;
clone_image->debug=IsEventLogging();
clone_image->semaphore=AcquireSemaphoreInfo();
if ((columns == 0) || (rows == 0))
{
if (image->montage != (char *) NULL)
(void) CloneString(&clone_image->montage,image->montage);
if (image->directory != (char *) NULL)
(void) CloneString(&clone_image->directory,image->directory);
clone_image->cache=ReferencePixelCache(image->cache);
return(clone_image);
}
scale=1.0;
if (image->columns != 0)
scale=(double) columns/(double) image->columns;
clone_image->page.width=(size_t) floor(scale*image->page.width+0.5);
clone_image->page.x=(ssize_t) ceil(scale*image->page.x-0.5);
clone_image->tile_offset.x=(ssize_t) ceil(scale*image->tile_offset.x-0.5);
scale=1.0;
if (image->rows != 0)
scale=(double) rows/(double) image->rows;
clone_image->page.height=(size_t) floor(scale*image->page.height+0.5);
clone_image->page.y=(ssize_t) ceil(scale*image->page.y-0.5);
clone_image->tile_offset.y=(ssize_t) ceil(scale*image->tile_offset.y-0.5);
clone_image->columns=columns;
clone_image->rows=rows;
clone_image->cache=ClonePixelCache(image->cache);
return(clone_image);
}

void dump_isom_sdp(GF_ISOFile *file, char *inName, Bool is_final_name)
{
const char *sdp;
u32 size, i;
FILE *dump;
if (inName) {
char szBuf[1024];
strcpy(szBuf, inName);
if (!is_final_name) {
char *ext = strchr(szBuf, '.');
if (ext) ext[0] = 0;
strcat(szBuf, "_sdp.txt");
}
dump = gf_fopen(szBuf, "wt");
if (!dump) {
fprintf(stderr, "Failed to open %s for dumping\n", szBuf);
return;
}
} else {
dump = stdout;
fprintf(dump, "* File SDP content *\n\n");
}
gf_isom_sdp_get(file, &sdp, &size);
fprintf(dump, "%s", sdp);
fprintf(dump, "\r\n");
for (i=0; i<gf_isom_get_track_count(file); i++) {
if (gf_isom_get_media_type(file, i+1) != GF_ISOM_MEDIA_HINT) continue;
gf_isom_sdp_track_get(file, i+1, &sdp, &size);
fprintf(dump, "%s", sdp);
}
fprintf(dump, "\n\n");
if (inName) gf_fclose(dump);
}

