literal = false;
if (i == 1) {
token = (uint8_t) (7U << 5U);
} else {
token = (uint8_t) ((7U << 5U) | ((j + k - 2) << 3U));
}
*op++ = token;
memcpy(op, &offset, 2);
op += 2;
for (int l = 0; l < 4; l++) {
