static int ntlm_read_ntlm_v2_client_challenge(wStream* s, NTLMv2_CLIENT_CHALLENGE* challenge)
{
size_t size;
Stream_Read_UINT8(s, challenge->RespType);
Stream_Read_UINT8(s, challenge->HiRespType);
Stream_Read_UINT16(s, challenge->Reserved1);
Stream_Read_UINT32(s, challenge->Reserved2);
Stream_Read(s, challenge->Timestamp, 8);
Stream_Read(s, challenge->ClientChallenge, 8);
Stream_Read_UINT32(s, challenge->Reserved3);
size = Stream_Length(s) - Stream_GetPosition(s);
if (size > UINT32_MAX)
return -1;
challenge->cbAvPairs = size;
challenge->AvPairs = (NTLM_AV_PAIR*)malloc(challenge->cbAvPairs);
if (!challenge->AvPairs)
return -1;
Stream_Read(s, challenge->AvPairs, size);
return 1;
}

static char ** split(const char *arg, const char *delim) {
char *copy = dupstr(arg);
char **result = NULL;
int i = 0;
for (char *cptr = strtok(copy, delim); cptr; cptr = strtok(NULL, delim)) {
char **tmp = realloc (result, sizeof *result * (i + 1));
if (!tmp && result) {
while (i > 0) {
free(result[--i]);
}
free(result);
free(copy);
return NULL;
}
result = tmp;
result[i++] = dupstr(cptr);
}
free(copy);
if (i) {
char **tmp = realloc(result, sizeof *result * (i + 1));
if (!tmp) {
while (i > 0) {
free(result[--i]);
}
free(result);
free(copy);
return NULL;
}
result = tmp;
result[i++] = NULL;
}
return result;
}

static int
decode_preR13_section (Dwg_Section_Type_r11 id, Bit_Chain *restrict dat,
Dwg_Data *restrict dwg)
{
Dwg_Section *tbl = &dwg->header.section[id];
Bit_Chain *hdl_dat = dat;
int i;
BITCODE_BL vcount;
int error = 0;
long unsigned int num = dwg->num_objects;
long unsigned int pos = tbl->address;
BITCODE_RC flag;
BITCODE_TF name;
LOG_TRACE ("contents table %-8s [%2d]: size:%-4u num:%-3ld (0x%lx-0x%lx)\n",
tbl->name, id, tbl->size, (long)tbl->number, (unsigned long)tbl->address,
(unsigned long)(tbl->address + ((unsigned long long)tbl->number * tbl->size)))
dat->byte = tbl->address;
dat->bit = 0;
if ((unsigned long)(tbl->number * tbl->size) > dat->size - dat->byte)
{
LOG_ERROR ("Overlarge table num_entries %ld or size %ld for %-8s [%2d]",
(long)tbl->number, (long)tbl->size, tbl->name, id);
return DWG_ERR_INVALIDDWG;
}
tbl->objid_r11 = num;
if (dwg->num_alloced_objects < dwg->num_objects + tbl->number)
{
dwg->num_alloced_objects = dwg->num_objects + tbl->number;
dwg->object = (Dwg_Object*)realloc (dwg->object,
dwg->num_alloced_objects * sizeof (Dwg_Object));
dwg->dirty_refs = 1;
}
#define PREP_TABLE(token)                                                     \
Dwg_Object *obj;                                                            \
Dwg_Object_##token *_obj;                                                   \
Dwg_Object *ctrl = dwg_get_first_object (dwg, DWG_TYPE_##token##_CONTROL);  \
Dwg_Object_##token##_CONTROL *_ctrl                                         \
= ctrl->tio.object->tio.token##_CONTROL;                                \
if (dat->byte > dat->size || (num + i) > dwg->num_objects)                  \
return DWG_ERR_INVALIDDWG;                                                \
flag = bit_read_RC (dat);                                                   \
name = bit_read_TF (dat, 32);                                               \
_obj = dwg_add_##token (dwg, (const char *)name);                           \
obj = dwg_obj_generic_to_object (_obj, &error);                             \
_ctrl->entries[i] = dwg_add_handleref (dwg, 2, obj->handle.value, obj);     \
obj->size = tbl->size;                                                      \
obj->address = pos;                                                         \
_obj->flag = flag;                                                          \
LOG_TRACE ("\n-- table entry " #token " [%d]: 0x%lx\n", i, pos);            \
LOG_TRACE ("flag: %u [RC 70]\n", flag);                                     \
LOG_TRACE ("name: \"%s\" [TF 32 2]\n", name);                               \
free (name)
#define CHK_ENDPOS                                                            \
SINCE (R_11) {                                                              \
BITCODE_RS crc16 = bit_read_RS (dat);                                     \
LOG_TRACE ("crc16: %04X\n", crc16);                                       \
}                                                                           \
pos = tbl->address + (long)((i + 1) * tbl->size);                           \
if (pos != dat->byte)                                                       \
{                                                                         \
LOG_ERROR ("offset %ld", pos - dat->byte);                              \
\
}                                                                         \
dat->byte = pos
switch (id)
{
case SECTION_BLOCK:
for (i = 0; i < tbl->number; i++)
{
Dwg_Object *obj;
Dwg_Object_BLOCK_HEADER *_obj;
Dwg_Object *ctrl;
Dwg_Object_BLOCK_CONTROL *_ctrl;
if (dat->byte > dat->size || (num + i) > dwg->num_objects)
return DWG_ERR_INVALIDDWG;
flag = bit_read_RC (dat);
name = bit_read_TF (dat, 32);
_obj = dwg_add_BLOCK_HEADER (dwg, (const char *)name);
_obj->flag = flag;
LOG_TRACE ("\n-- table entry BLOCK_HEADER [%d]: 0x%lx\n", i, pos);
LOG_TRACE ("flag: %u [RC 70]\n", flag);
LOG_TRACE ("name: \"%s\" [TF 32 2]\n", name);
free (name);
obj = dwg_obj_generic_to_object (_obj, &error);
if (obj)
{
obj->size = tbl->size;
obj->address = pos;
}
ctrl = dwg_get_first_object (dwg, DWG_TYPE_BLOCK_CONTROL);
if (ctrl)
{
_ctrl = ctrl->tio.object->tio.BLOCK_CONTROL;
_ctrl->entries[i]
= dwg_add_handleref (dwg, 2, obj->handle.value, obj);
}
FIELD_RC (block_scaling, 0);
PRE (R_11) {
FIELD_CAST (num_owned, RS, BL, 0);
FIELD_RC (flag2, 0);
if (dwg->header.numheader_vars == 74)
FIELD_CAST (unknown_r11, RC, RS, 0);
}
SINCE (R_11) {               FIELD_RS (unknown_r11, 0);
FIELD_HANDLE (block_entity, 2, 0);               FIELD_RC (flag2, 0);
FIELD_RSd (used, 0);
FIELD_RSd (unknown1_r11, 0);
}
CHK_ENDPOS;
}
break;
case SECTION_LAYER:
for (i = 0; i < tbl->number; i++)
{
Bit_Chain *str_dat = dat;
PREP_TABLE (LAYER);
FIELD_CMC (color, 62);             PRE (R_11) {
FIELD_HANDLE (ltype, 2, 6);
if (dwg->header.numheader_vars == 74)
FIELD_RC (flag0, 0);
}
LATER_VERSIONS {
FIELD_RS (linewt, 370);
FIELD_HANDLE (ltype, 2, 6);
}
CHK_ENDPOS;
}
break;
case SECTION_STYLE:
for (i = 0; i < tbl->number; i++)
{
PREP_TABLE (STYLE);
FIELD_RD (text_size, 40);             FIELD_RD (width_factor, 41);
FIELD_RD (oblique_angle, 50);
FIELD_RC (generation, 71);
FIELD_RD (last_height, 42);
SINCE (R_11)
FIELD_RS (unknown, 0);
FIELD_TFv (font_file, 64, 3)                SINCE (R_11)
FIELD_TFv (bigfont_file, 64, 4);             CHK_ENDPOS;
}
break;
case SECTION_LTYPE:
{
for (i = 0; i < tbl->number; i++)
{
Bit_Chain abs_dat = *dat;
bit_reset_chain (dat);
{
PREP_TABLE (LTYPE);
if (dwg->header.version == R_11)
FIELD_RSd (used, 0);               FIELD_TFv (description, 48, 3);
FIELD_RC (alignment, 72);
FIELD_RCu (num_dashes, 73);               FIELD_RD (pattern_len, 40);
#ifndef IS_JSON
FIELD_RD (dashes_r11[0], 49);
FIELD_RD (dashes_r11[1], 49);
FIELD_RD (dashes_r11[2], 49);
FIELD_RD (dashes_r11[3], 49);
FIELD_RD (dashes_r11[4], 49);
FIELD_RD (dashes_r11[5], 49);
FIELD_RD (dashes_r11[6], 49);
FIELD_RD (dashes_r11[7], 49);
FIELD_RD (dashes_r11[8], 49);
FIELD_RD (dashes_r11[9], 49);
FIELD_RD (dashes_r11[10], 49);
FIELD_RD (dashes_r11[11], 49);
#else
FIELD_VECTOR_N (dashes_r11, RD, 12, 49);
#endif
if (dwg->header.version < R_11 && tbl->size > 187)
FIELD_RC (unknown_r11, 0);
}
pos = dat->byte;
*dat = abs_dat;
dat->byte += pos;
CHK_ENDPOS;
}
}
break;
case SECTION_VIEW:
{
for (i = 0; i < tbl->number; i++)
{
PREP_TABLE (VIEW);
FIELD_RD (VIEWSIZE, 40);
FIELD_2RD (VIEWCTR, 10);
if (tbl->size > 58)
FIELD_RD (view_width, 41);
if (tbl->size > 66)
FIELD_3RD (VIEWDIR, 11);
if (tbl->size > 89)
FIELD_RS (flag_3d, 0);
PRE (R_10) {
if (dwg->header.numheader_vars == 74)
FIELD_RC (unknown_r2, 0);
}
SINCE (R_10) {
FIELD_3RD (view_target, 12);
FIELD_CAST (VIEWMODE, RS, 4BITS, 71);
FIELD_RD (lens_length, 42);
FIELD_RD (front_clip_z, 43);
FIELD_RD (back_clip_z, 44);
FIELD_RD (twist_angle, 50);
}
CHK_ENDPOS;
}
}
break;
case SECTION_UCS:
{
for (i = 0; i < tbl->number; i++)
{
Dwg_Object *obj;
Dwg_Object_UCS *_obj;
dwg_point_3d ucsorg, ucsxdir, ucsydir;
Dwg_Object *ctrl
= dwg_get_first_object (dwg, DWG_TYPE_UCS_CONTROL);
Dwg_Object_UCS_CONTROL *_ctrl
= ctrl->tio.object->tio.UCS_CONTROL;
if (dat->byte > dat->size || (num + i) > dwg->num_objects)
return DWG_ERR_INVALIDDWG;
flag = bit_read_RC (dat);
name = bit_read_TF (dat, 32);
ucsorg.x = bit_read_RD (dat);
ucsorg.y = bit_read_RD (dat);
ucsxdir.x = bit_read_RD (dat);
ucsxdir.y = bit_read_RD (dat);
ucsydir.x = bit_read_RD (dat);
ucsydir.y = bit_read_RD (dat);
_obj = dwg_add_UCS (dwg, &ucsorg, &ucsxdir, &ucsydir, (const char *)name);
obj = dwg_obj_generic_to_object (_obj, &error);
_ctrl->entries[i]
= dwg_add_handleref (dwg, 2, obj->handle.value, obj);
obj->size = tbl->size;
obj->address = pos;
_obj->flag = flag;
LOG_TRACE ("\n-- table entry UCS [%d]: 0x%lx\n", i, pos);
LOG_TRACE ("flag: %u [RC 70]\n", flag);
LOG_TRACE ("name: \"%s\" [TF 32 2]\n", name);
free (name);
CHK_ENDPOS;
}
break;
case SECTION_VPORT:
{
for (i = 0; i < tbl->number; i++)
{
PREP_TABLE (VPORT);
FIELD_RD (VIEWSIZE, 40);
FIELD_RD (aspect_ratio, 41);
FIELD_2RD (VIEWCTR, 12);
FIELD_3RD (view_target, 17);
FIELD_3RD (VIEWDIR, 16);
FIELD_RD (view_twist, 50);
FIELD_RD (lens_length, 42);
FIELD_RD (front_clip_z, 43);
FIELD_RD (back_clip_z, 33);
FIELD_CAST (VIEWMODE, RS, 4BITS, 71);
FIELD_2RD (lower_left, 10);
FIELD_2RD (upper_right, 11);
FIELD_RC (UCSFOLLOW, 71);
FIELD_RS (circle_zoom, 72);
FIELD_RC (FASTZOOM, 73);
FIELD_RC (UCSICON, 74);
FIELD_RC (GRIDMODE, 76);
FIELD_2RD (GRIDUNIT, 15);
FIELD_CAST (SNAPMODE, RS, B, 70);               FIELD_RC (SNAPSTYLE, 70);                       FIELD_RS (SNAPISOPAIR, 78);
FIELD_RD (SNAPANG, 50);
FIELD_2RD (SNAPBASE, 13);
FIELD_2RD (SNAPUNIT, 14);
CHK_ENDPOS;
}
}
break;
case SECTION_APPID:
{
for (i = 0; i < tbl->number; i++)
{
PREP_TABLE (APPID);
CHK_ENDPOS;
}
}
break;
case SECTION_DIMSTYLE:
{
for (i = 0; i < tbl->number; i++)
{
PREP_TABLE (DIMSTYLE);               FIELD_RD (DIMSCALE, 40);               FIELD_RD (DIMASZ, 41);
FIELD_RD (DIMEXO, 42);
FIELD_RD (DIMDLI, 43);
FIELD_RD (DIMEXE, 44);
FIELD_RD (DIMRND, 45);
FIELD_RD (DIMDLE, 46);
FIELD_RD (DIMTP, 47);
FIELD_RD (DIMTM, 48);               FIELD_RD (DIMTXT, 140);
FIELD_RD (DIMCEN, 141);               FIELD_RD (DIMTSZ, 142);
FIELD_RD (DIMALTF, 143);
FIELD_RD (DIMLFAC, 144);
FIELD_RD (DIMTVP, 145);               FIELD_RC (DIMTOL, 71);                FIELD_RC (DIMLIM, 72);                FIELD_RC (DIMTIH, 73);
FIELD_RC (DIMTOH, 74);
FIELD_RC (DIMSE1, 75);
FIELD_RC (DIMSE2, 76);
FIELD_CAST (DIMTAD, RC, RS, 77);               FIELD_CAST (DIMZIN, RC, BS, 78);               FIELD_RC (DIMALT, 170);
FIELD_CAST (DIMALTD, RC, BS, 171);               FIELD_RC (DIMTOFL, 172);                         FIELD_RC (DIMSAH, 173);                          FIELD_RC (DIMTIX, 174);                          FIELD_RC (DIMSOXD, 175);                         FIELD_TFv (DIMPOST, 16, 3);                      FIELD_TFv (DIMAPOST, 16, 4);                     FIELD_TFv (DIMBLK_T, 16, 5);                     FIELD_TFv (DIMBLK1_T, 16, 6);                    FIELD_TFv (DIMBLK2_T, 66, 7);                                                FIELD_RS (DIMCLRD_N, 176);               FIELD_RS (DIMCLRE_N, 177);
FIELD_RS (DIMCLRT_N, 178);               FIELD_RC (DIMUPT, 0);                    FIELD_RD (DIMTFAC, 146);                 FIELD_RD (DIMGAP, 147);                  CHK_ENDPOS;                            }
}
break;
case SECTION_VX:
{
if (tbl->number)
{
LOG_WARN ("VX table ignored");
tbl->number = 0;
}
}
break;
case SECTION_HEADER_R11:
default:
LOG_ERROR ("Invalid table id %d", id);
tbl->number = 0;
break;
}
dat->byte = tbl->address + (tbl->number * tbl->size);
}
return error;
}

static int read_entry(
git_index_entry **out,
size_t *out_size,
git_index *index,
const void *buffer,
size_t buffer_size,
const char *last)
{
size_t path_length, entry_size;
const char *path_ptr;
struct entry_short source;
git_index_entry entry = {{0}};
bool compressed = index->version >= INDEX_VERSION_NUMBER_COMP;
char *tmp_path = NULL;
if (INDEX_FOOTER_SIZE + minimal_entry_size > buffer_size)
return -1;
memcpy(&source, buffer, sizeof(struct entry_short));
entry.ctime.seconds = (git_time_t)ntohl(source.ctime.seconds);
entry.ctime.nanoseconds = ntohl(source.ctime.nanoseconds);
entry.mtime.seconds = (git_time_t)ntohl(source.mtime.seconds);
entry.mtime.nanoseconds = ntohl(source.mtime.nanoseconds);
entry.dev = ntohl(source.dev);
entry.ino = ntohl(source.ino);
entry.mode = ntohl(source.mode);
entry.uid = ntohl(source.uid);
entry.gid = ntohl(source.gid);
entry.file_size = ntohl(source.file_size);
git_oid_cpy(&entry.id, &source.oid);
entry.flags = ntohs(source.flags);
if (entry.flags & GIT_IDXENTRY_EXTENDED) {
uint16_t flags_raw;
size_t flags_offset;
flags_offset = offsetof(struct entry_long, flags_extended);
memcpy(&flags_raw, (const char *) buffer + flags_offset,
sizeof(flags_raw));
flags_raw = ntohs(flags_raw);
memcpy(&entry.flags_extended, &flags_raw, sizeof(flags_raw));
path_ptr = (const char *) buffer + offsetof(struct entry_long, path);
} else
path_ptr = (const char *) buffer + offsetof(struct entry_short, path);
if (!compressed) {
path_length = entry.flags & GIT_IDXENTRY_NAMEMASK;
if (path_length == 0xFFF) {
const char *path_end;
path_end = memchr(path_ptr, '\0', buffer_size);
if (path_end == NULL)
return -1;
path_length = path_end - path_ptr;
}
entry_size = index_entry_size(path_length, 0, entry.flags);
entry.path = (char *)path_ptr;
} else {
size_t varint_len;
size_t strip_len = git_decode_varint((const unsigned char *)path_ptr,
&varint_len);
size_t last_len = strlen(last);
size_t prefix_len = last_len - strip_len;
size_t suffix_len = strlen(path_ptr + varint_len);
size_t path_len;
if (varint_len == 0)
return index_error_invalid("incorrect prefix length");
GITERR_CHECK_ALLOC_ADD(&path_len, prefix_len, suffix_len);
GITERR_CHECK_ALLOC_ADD(&path_len, path_len, 1);
tmp_path = git__malloc(path_len);
GITERR_CHECK_ALLOC(tmp_path);
memcpy(tmp_path, last, prefix_len);
memcpy(tmp_path + prefix_len, path_ptr + varint_len, suffix_len + 1);
entry_size = index_entry_size(suffix_len, varint_len, entry.flags);
entry.path = tmp_path;
}
if (entry_size == 0)
return -1;
if (INDEX_FOOTER_SIZE + entry_size > buffer_size)
return -1;
if (index_entry_dup(out, index, &entry) < 0) {
git__free(tmp_path);
return -1;
}
git__free(tmp_path);
*out_size = entry_size;
return 0;
}

void rw_i93_send_to_upper(NFC_HDR* p_resp) {
uint8_t *p = (uint8_t*)(p_resp + 1) + p_resp->offset, *p_uid;
uint16_t length = p_resp->len;
tRW_I93_CB* p_i93 = &rw_cb.tcb.i93;
tRW_DATA rw_data;
uint8_t event = RW_I93_MAX_EVT;
uint8_t flags;
NFC_HDR* p_buff;
DLOG_IF(INFO, nfc_debug_enabled) << __func__;
if (length == 0) {
android_errorWriteLog(0x534e4554, "121035878");
rw_data.i93_cmd_cmpl.status = NFC_STATUS_FAILED;
rw_data.i93_cmd_cmpl.command = p_i93->sent_cmd;
rw_cb.tcb.i93.sent_cmd = 0;
(*(rw_cb.p_cback))(RW_I93_CMD_CMPL_EVT, &rw_data);
return;
}
STREAM_TO_UINT8(flags, p);
length--;
if (flags & I93_FLAG_ERROR_DETECTED) {
if ((length) && (rw_i93_check_sys_info_prot_ext(*p))) {
p_i93->intl_flags |= RW_I93_FLAG_16BIT_NUM_BLOCK;
p_i93->state = RW_I93_STATE_BUSY;
} else if (length) {
rw_data.i93_cmd_cmpl.status = NFC_STATUS_FAILED;
rw_data.i93_cmd_cmpl.command = p_i93->sent_cmd;
STREAM_TO_UINT8(rw_data.i93_cmd_cmpl.error_code, p);
rw_cb.tcb.i93.sent_cmd = 0;
(*(rw_cb.p_cback))(RW_I93_CMD_CMPL_EVT, &rw_data);
}
return;
}
switch (p_i93->sent_cmd) {
case I93_CMD_INVENTORY:
if (length < I93_INFO_DSFID_LEN + I93_UID_BYTE_LEN) return;
rw_data.i93_inventory.status = NFC_STATUS_OK;
STREAM_TO_UINT8(rw_data.i93_inventory.dsfid, p);
p_uid = rw_data.i93_inventory.uid;
STREAM_TO_ARRAY8(p_uid, p);
rw_i93_get_product_version(p_uid);
event = RW_I93_INVENTORY_EVT;
break;
case I93_CMD_READ_SINGLE_BLOCK:
case I93_CMD_EXT_READ_SINGLE_BLOCK:
case I93_CMD_READ_MULTI_BLOCK:
case I93_CMD_EXT_READ_MULTI_BLOCK:
case I93_CMD_GET_MULTI_BLK_SEC:
case I93_CMD_EXT_GET_MULTI_BLK_SEC:
p_buff = (NFC_HDR*)GKI_getbuf((uint16_t)(length + NFC_HDR_SIZE));
if (p_buff) {
p_buff->offset = 0;
p_buff->len = length;
memcpy((p_buff + 1), p, length);
rw_data.i93_data.status = NFC_STATUS_OK;
rw_data.i93_data.command = p_i93->sent_cmd;
rw_data.i93_data.p_data = p_buff;
event = RW_I93_DATA_EVT;
} else {
rw_data.i93_cmd_cmpl.status = NFC_STATUS_NO_BUFFERS;
rw_data.i93_cmd_cmpl.command = p_i93->sent_cmd;
rw_data.i93_cmd_cmpl.error_code = 0;
event = RW_I93_CMD_CMPL_EVT;
}
break;
case I93_CMD_WRITE_SINGLE_BLOCK:
case I93_CMD_EXT_WRITE_SINGLE_BLOCK:
case I93_CMD_LOCK_BLOCK:
case I93_CMD_EXT_LOCK_BLOCK:
case I93_CMD_WRITE_MULTI_BLOCK:
case I93_CMD_EXT_WRITE_MULTI_BLOCK:
case I93_CMD_SELECT:
case I93_CMD_RESET_TO_READY:
case I93_CMD_WRITE_AFI:
case I93_CMD_LOCK_AFI:
case I93_CMD_WRITE_DSFID:
case I93_CMD_LOCK_DSFID:
rw_data.i93_cmd_cmpl.status = NFC_STATUS_OK;
rw_data.i93_cmd_cmpl.command = p_i93->sent_cmd;
rw_data.i93_cmd_cmpl.error_code = 0;
event = RW_I93_CMD_CMPL_EVT;
break;
case I93_CMD_GET_SYS_INFO:
if (rw_i93_process_sys_info(p, length)) {
rw_data.i93_sys_info.status = NFC_STATUS_OK;
rw_data.i93_sys_info.info_flags = p_i93->info_flags;
rw_data.i93_sys_info.dsfid = p_i93->dsfid;
rw_data.i93_sys_info.afi = p_i93->afi;
rw_data.i93_sys_info.num_block = p_i93->num_block;
rw_data.i93_sys_info.block_size = p_i93->block_size;
rw_data.i93_sys_info.IC_reference = p_i93->ic_reference;
memcpy(rw_data.i93_sys_info.uid, p_i93->uid, I93_UID_BYTE_LEN);
p_i93->i93_t5t_mode = RW_I93_GET_SYS_INFO_MEM_INFO;
event = RW_I93_SYS_INFO_EVT;
} else {
p_i93->state = RW_I93_STATE_BUSY;
return;
}
break;
case I93_CMD_EXT_GET_SYS_INFO:
if (rw_i93_process_ext_sys_info(p, length)) {
rw_data.i93_sys_info.status = NFC_STATUS_OK;
rw_data.i93_sys_info.info_flags = p_i93->info_flags;
rw_data.i93_sys_info.dsfid = p_i93->dsfid;
rw_data.i93_sys_info.afi = p_i93->afi;
rw_data.i93_sys_info.num_block = p_i93->num_block;
rw_data.i93_sys_info.block_size = p_i93->block_size;
rw_data.i93_sys_info.IC_reference = p_i93->ic_reference;
memcpy(rw_data.i93_sys_info.uid, p_i93->uid, I93_UID_BYTE_LEN);
p_i93->i93_t5t_mode = RW_I93_GET_SYS_INFO_MEM_INFO;
event = RW_I93_SYS_INFO_EVT;
} else {
p_i93->state = RW_I93_STATE_BUSY;
return;
}
break;
default:
break;
}
rw_cb.tcb.i93.sent_cmd = 0;
if (event != RW_I93_MAX_EVT) {
(*(rw_cb.p_cback))(event, &rw_data);
} else {
LOG(ERROR) << StringPrintf("Invalid response");
}
}

static int cond_hash(tvbparse_t* tt, const int offset, const tvbparse_wanted_t* wanted, tvbparse_elem_t** tok) {
int key_len;
gchar* key = NULL;
tvbparse_elem_t* key_elem = NULL;
tvbparse_wanted_t* value_wanted = NULL;
int value_len;
tvbparse_elem_t* value_elem = NULL;
int tot_len;
tvbparse_elem_t* ret_tok;
#ifdef TVBPARSE_DEBUG
if (TVBPARSE_DEBUG & TVBPARSE_DEBUG_HASH) g_warning("cond_hash: START");
#endif
if ( offset > tt->end_offset )
return -1;
if (++tt->recursion_depth > TVBPARSE_MAX_RECURSION_DEPTH)
return -1;
key_len = wanted->control.hash.key->condition(tt, offset, wanted->control.hash.key,  &key_elem);
if (key_len < 0)
return -1;
key = tvb_get_string_enc(wmem_packet_scope(),key_elem->tvb,key_elem->offset,key_elem->len, ENC_ASCII);
#ifdef TVBPARSE_DEBUG
if (TVBPARSE_DEBUG & TVBPARSE_DEBUG_HASH) g_warning("cond_hash: got key='%s'",key);
#endif
if ((value_wanted = (tvbparse_wanted_t *)wmem_map_lookup(wanted->control.hash.table,key))) {
value_len = value_wanted->condition(tt, offset + key_len, value_wanted,  &value_elem);
} else if (wanted->control.hash.other) {
value_len = wanted->control.hash.other->condition(tt, offset+key_len, wanted->control.hash.other,  &value_elem);
if (value_len < 0)
return -1;
} else {
return -1;
}
tot_len = key_len + value_len;
ret_tok = new_tok(tt, value_elem->id, offset, tot_len, wanted);
ret_tok->sub = key_elem;
ret_tok->sub->last->next = value_elem;
*tok = ret_tok;
#ifdef TVBPARSE_DEBUG
if (TVBPARSE_DEBUG & TVBPARSE_DEBUG_HASH) g_warning("cond_hash: GOT len=%i",tot_len);
#endif
return tot_len;
}

static netdev_tx_t ems_usb_start_xmit(struct sk_buff *skb, struct net_device *netdev)
{
struct ems_usb *dev = netdev_priv(netdev);
struct ems_tx_urb_context *context = NULL;
struct net_device_stats *stats = &netdev->stats;
struct can_frame *cf = (struct can_frame *)skb->data;
struct ems_cpc_msg *msg;
struct urb *urb;
u8 *buf;
int i, err;
size_t size = CPC_HEADER_SIZE + CPC_MSG_HEADER_LEN
+ sizeof(struct cpc_can_msg);
if (can_dropped_invalid_skb(netdev, skb))
return NETDEV_TX_OK;
urb = usb_alloc_urb(0, GFP_ATOMIC);
if (!urb)
goto nomem;
buf = usb_alloc_coherent(dev->udev, size, GFP_ATOMIC, &urb->transfer_dma);
if (!buf) {
netdev_err(netdev, "No memory left for USB buffer\n");
usb_free_urb(urb);
goto nomem;
}
msg = (struct ems_cpc_msg *)&buf[CPC_HEADER_SIZE];
msg->msg.can_msg.id = cpu_to_le32(cf->can_id & CAN_ERR_MASK);
msg->msg.can_msg.length = cf->len;
if (cf->can_id & CAN_RTR_FLAG) {
msg->type = cf->can_id & CAN_EFF_FLAG ?
CPC_CMD_TYPE_EXT_RTR_FRAME : CPC_CMD_TYPE_RTR_FRAME;
msg->length = CPC_CAN_MSG_MIN_SIZE;
} else {
msg->type = cf->can_id & CAN_EFF_FLAG ?
CPC_CMD_TYPE_EXT_CAN_FRAME : CPC_CMD_TYPE_CAN_FRAME;
for (i = 0; i < cf->len; i++)
msg->msg.can_msg.msg[i] = cf->data[i];
msg->length = CPC_CAN_MSG_MIN_SIZE + cf->len;
}
for (i = 0; i < MAX_TX_URBS; i++) {
if (dev->tx_contexts[i].echo_index == MAX_TX_URBS) {
context = &dev->tx_contexts[i];
break;
}
}
if (!context) {
usb_free_coherent(dev->udev, size, buf, urb->transfer_dma);
usb_free_urb(urb);
netdev_warn(netdev, "couldn't find free context\n");
return NETDEV_TX_BUSY;
}
context->dev = dev;
context->echo_index = i;
usb_fill_bulk_urb(urb, dev->udev, usb_sndbulkpipe(dev->udev, 2), buf,
size, ems_usb_write_bulk_callback, context);
urb->transfer_flags |= URB_NO_TRANSFER_DMA_MAP;
usb_anchor_urb(urb, &dev->tx_submitted);
can_put_echo_skb(skb, netdev, context->echo_index, 0);
atomic_inc(&dev->active_tx_urbs);
err = usb_submit_urb(urb, GFP_ATOMIC);
if (unlikely(err)) {
can_free_echo_skb(netdev, context->echo_index, NULL);
usb_unanchor_urb(urb);
usb_free_coherent(dev->udev, size, buf, urb->transfer_dma);
dev_kfree_skb(skb);
atomic_dec(&dev->active_tx_urbs);
if (err == -ENODEV) {
netif_device_detach(netdev);
} else {
netdev_warn(netdev, "failed tx_urb %d\n", err);
stats->tx_dropped++;
}
} else {
netif_trans_update(netdev);
if (atomic_read(&dev->active_tx_urbs) >= MAX_TX_URBS ||
dev->free_slots < CPC_TX_QUEUE_TRIGGER_LOW) {
netif_stop_queue(netdev);
}
}
usb_free_urb(urb);
return NETDEV_TX_OK;
nomem:
dev_kfree_skb(skb);
stats->tx_dropped++;
return NETDEV_TX_OK;
}

