BatchBlock::BatchBlock(int32_t device_id, size_t avail_mem, int32_t max_sequences_per_poa, int8_t output_mask, bool banded_alignment)
: max_sequences_per_poa_(throw_on_negative(max_sequences_per_poa, "Maximum sequences per POA has to be non-negative"))
, banded_alignment_(banded_alignment)
, device_id_(throw_on_negative(device_id, "Device ID has to be non-negative"))
, output_mask_(output_mask)
{
matrix_sequence_dimension_ = banded_alignment_ ? CUDAPOA_BANDED_MAX_MATRIX_SEQUENCE_DIMENSION : CUDAPOA_MAX_MATRIX_SEQUENCE_DIMENSION;
max_graph_dimension_       = banded_alignment_ ? CUDAPOA_MAX_MATRIX_GRAPH_DIMENSION_BANDED : CUDAPOA_MAX_MATRIX_GRAPH_DIMENSION;
max_nodes_per_window_      = banded_alignment_ ? CUDAPOA_MAX_NODES_PER_WINDOW_BANDED : CUDAPOA_MAX_NODES_PER_WINDOW;
size_t host_size_fixed, device_size_fixed;
size_t host_size_per_poa, device_size_per_poa;
std::tie(host_size_fixed, device_size_fixed, host_size_per_poa, device_size_per_poa) = calculate_space_per_poa();
size_t minimum_device_mem = 2 * (device_size_fixed + device_size_per_poa);
if (avail_mem < minimum_device_mem)
{
std::string msg = std::string("Require at least ")
.append(std::to_string(minimum_device_mem))
.append(" bytes of device memory per CUDAPOA batch to process correctly.");
throw std::runtime_error(msg);
}
const float fraction_for_metadata = 0.4f;
max_poas_                         = (avail_mem * fraction_for_metadata) / device_size_per_poa;
output_size_ = max_poas_ * CUDAPOA_MAX_CONSENSUS_SIZE;
input_size_  = max_poas_ * max_sequences_per_poa_ * CUDAPOA_MAX_SEQUENCE_SIZE;
total_h_     = max_poas_ * host_size_per_poa + host_size_fixed;
total_d_     = avail_mem;
CGA_CU_CHECK_ERR(cudaSetDevice(device_id_));
CGA_CU_CHECK_ERR(cudaHostAlloc((void**)&block_data_h_, total_h_, cudaHostAllocDefault));
CGA_CU_CHECK_ERR(cudaMalloc((void**)&block_data_d_, total_d_));
}

static PyObject* patch(PyObject* self, PyObject* args)
{
char *origData, *newData, *diffBlock, *extraBlock, *diffPtr, *extraPtr;
Py_ssize_t origDataLength, newDataLength, diffBlockLength, extraBlockLength;
PyObject *controlTuples, *tuple, *results;
off_t oldpos, newpos, x, y, z;
int i, j, numTuples;
if (!PyArg_ParseTuple(args, "s#nO!s#s#",
&origData, &origDataLength, &newDataLength,
&PyList_Type, &controlTuples,
&diffBlock, &diffBlockLength,
&extraBlock, &extraBlockLength))
return NULL;
newData = PyMem_Malloc(newDataLength + 1);
if (!newData)
return PyErr_NoMemory();
oldpos = 0;
newpos = 0;
diffPtr = diffBlock;
extraPtr = extraBlock;
numTuples = PyList_GET_SIZE(controlTuples);
for (i = 0; i < numTuples; i++) {
tuple = PyList_GET_ITEM(controlTuples, i);
if (!PyTuple_Check(tuple)) {
PyMem_Free(newData);
PyErr_SetString(PyExc_TypeError, "expecting tuple");
return NULL;
}
if (PyTuple_GET_SIZE(tuple) != 3) {
PyMem_Free(newData);
PyErr_SetString(PyExc_TypeError, "expecting tuple of size 3");
return NULL;
}
x = PyLong_AsLong(PyTuple_GET_ITEM(tuple, 0));
y = PyLong_AsLong(PyTuple_GET_ITEM(tuple, 1));
z = PyLong_AsLong(PyTuple_GET_ITEM(tuple, 2));
if (newpos + x > newDataLength ||
diffPtr + x > diffBlock + diffBlockLength ||
extraPtr + y > extraBlock + extraBlockLength) {
PyMem_Free(newData);
PyErr_SetString(PyExc_ValueError, "corrupt patch (overflow)");
return NULL;
}
memcpy(newData + newpos, diffPtr, x);
diffPtr += x;
for (j = 0; j < x; j++)
if ((oldpos + j >= 0) && (oldpos + j < origDataLength))
newData[newpos + j] += origData[oldpos + j];
newpos += x;
oldpos += x;
memcpy(newData + newpos, extraPtr, y);
extraPtr += y;
newpos += y;
oldpos += z;
}
if (newpos != newDataLength ||
diffPtr != diffBlock + diffBlockLength ||
extraPtr != extraBlock + extraBlockLength) {
PyMem_Free(newData);
PyErr_SetString(PyExc_ValueError, "corrupt patch (underflow)");
return NULL;
}
results = PyBytes_FromStringAndSize(newData, newDataLength);
PyMem_Free(newData);
return results;
}

static void btm_ble_start_sync_timeout(void* data) {
LOG_DEBUG("%s", "");
sync_node_t* p_head = (sync_node_t*)list_front(sync_queue);
uint8_t adv_sid = p_head->sid;
RawAddress address = p_head->address;
int index = btm_ble_get_psync_index(adv_sid, address);
tBTM_BLE_PERIODIC_SYNC* p = &btm_ble_pa_sync_cb.p_sync[index];
if (BleScanningManager::IsInitialized()) {
BleScanningManager::Get()->PeriodicScanCancelStart();
}
p->sync_start_cb.Run(0x3C, 0, p->sid, 0, p->remote_bda, 0, 0);
p->sync_state = PERIODIC_SYNC_IDLE;
p->in_use = false;
p->remote_bda = RawAddress::kEmpty;
p->sid = 0;
p->sync_handle = 0;
p->in_use = false;
}

