static inline int add_post_vars(zval *arr, post_var_data_t *vars, zend_bool eof TSRMLS_DC)
{
uint64_t max_vars = PG(max_input_vars);
vars->ptr = vars->str.c;
vars->end = vars->str.c + vars->str.len;
while (add_post_var(arr, vars, eof TSRMLS_CC)) {
if (++vars->cnt > max_vars) {
php_error_docref(NULL TSRMLS_CC, E_WARNING,
"Input variables exceeded %" PRIu64 ". "
"To increase the limit change max_input_vars in php.ini.",
max_vars);
return FAILURE;
}
}
if (!eof) {
memmove(vars->str.c, vars->ptr, vars->str.len = vars->end - vars->ptr);
}
return SUCCESS;
}

void UncompressElementOp::Compute(OpKernelContext* ctx) {
Tensor tensor = ctx->input(0);
const Variant& variant = tensor.scalar<Variant>()();
const CompressedElement* compressed = variant.get<CompressedElement>();
std::vector<Tensor> components;
OP_REQUIRES_OK(ctx, UncompressElement(*compressed, &components));
OP_REQUIRES(ctx, components.size() == output_types_.size(),
errors::FailedPrecondition("Expected ", output_types_.size(),
" outputs from uncompress, but got ",
components.size()));
for (int i = 0; i < components.size(); ++i) {
OP_REQUIRES(
ctx, components[i].dtype() == output_types_[i],
errors::FailedPrecondition("Expected a tensor of type ",
DataTypeString(output_types_[i]),
" but got a tensor of type ",
DataTypeString(components[i].dtype())));
ctx->set_output(i, components[i]);
}
}

int
ImagingPcdDecode(Imaging im, ImagingCodecState state, UINT8* buf, int bytes)
{
int x;
int chunk;
UINT8* out;
UINT8* ptr;
ptr = buf;
chunk = 3 * state->xsize;
for (;;) {
if (bytes < chunk)
return ptr - buf;
out = state->buffer;
for (x = 0; x < state->xsize; x++) {
out[0] = ptr[x];
out[1] = ptr[(x+4*state->xsize)/2];
out[2] = ptr[(x+5*state->xsize)/2];
out += 4;
}
state->shuffle((UINT8*) im->image[state->y],
state->buffer, state->xsize);
if (++state->y >= state->ysize)
return -1; 
out = state->buffer;
for (x = 0; x < state->xsize; x++) {
out[0] = ptr[x+state->xsize];
out[1] = ptr[(x+4*state->xsize)/2];
out[2] = ptr[(x+5*state->xsize)/2];
out += 4;
}
state->shuffle((UINT8*) im->image[state->y],
state->buffer, state->xsize);
if (++state->y >= state->ysize)
return -1;
ptr += chunk;
bytes -= chunk;
}
}

AP4_AvccAtom* 
AP4_AvccAtom::Create(AP4_Size size, AP4_ByteStream& stream)
{
unsigned int payload_size = size-AP4_ATOM_HEADER_SIZE;
AP4_DataBuffer payload_data(payload_size);
AP4_Result result = stream.Read(payload_data.UseData(), payload_size);
if (AP4_FAILED(result)) return NULL;
const AP4_UI08* payload = payload_data.GetData();
if (payload[0] != 1) {
return NULL;
}
if (payload_size < 6) return NULL;
unsigned int num_seq_params = payload[5]&31;
unsigned int cursor = 6;
for (unsigned int i=0; i<num_seq_params; i++) {
if (cursor+2 > payload_size) return NULL;
cursor += 2+AP4_BytesToInt16BE(&payload[cursor]);
if (cursor > payload_size) return NULL;
}
unsigned int num_pic_params = payload[cursor++];
if (cursor > payload_size) return NULL;
for (unsigned int i=0; i<num_pic_params; i++) {
if (cursor+2 > payload_size) return NULL;
cursor += 2+AP4_BytesToInt16BE(&payload[cursor]);
if (cursor > payload_size) return NULL;
}
return new AP4_AvccAtom(size, payload);
}

int regexec(Reprog *prog, const char *sp, Resub *sub, int eflags)
