{
emsg(_(e_missing_return_statement));
goto erret;
}
generate_instr(&cctx, ISN_RETURN_VOID);
}
if (emsg_silent == 0 || did_emsg_silent == did_emsg_silent_before)
{
dfunc_T*dfunc = ((dfunc_T *)def_functions.ga_data)
+ ufunc->uf_dfunc_idx;
dfunc->df_deleted = FALSE;
dfunc->df_script_seq = current_sctx.sc_seq;
#ifdef FEAT_PROFILE
if (cctx.ctx_compile_type == CT_PROFILE)
{
dfunc->df_instr_prof = instr->ga_data;
dfunc->df_instr_prof_count = instr->ga_len;
}
else
#endif
if (cctx.ctx_compile_type == CT_DEBUG)
{
dfunc->df_instr_debug = instr->ga_data;
dfunc->df_instr_debug_count = instr->ga_len;
}
else
{
dfunc->df_instr = instr->ga_data;
dfunc->df_instr_count = instr->ga_len;
}
dfunc->df_varcount = dfunc->df_var_names.ga_len;
dfunc->df_has_closure = cctx.ctx_has_closure;
if (cctx.ctx_outer_used)
ufunc->uf_flags |= FC_CLOSURE;
ufunc->uf_def_status = UF_COMPILED;
}
ret = OK;
erret:
if (ufunc->uf_def_status == UF_COMPILING)
{
dfunc_T*dfunc = ((dfunc_T *)def_functions.ga_data)
+ ufunc->uf_dfunc_idx;
clear_instr_ga(instr);
VIM_CLEAR(dfunc->df_name);
ga_clear_strings(&dfunc->df_var_names);
if (!dfunc->df_deleted && new_def_function
&& ufunc->uf_dfunc_idx == def_functions.ga_len - 1)
{
--def_functions.ga_len;
ufunc->uf_dfunc_idx = 0;
}
ufunc->uf_def_status = UF_COMPILE_ERROR;
while (cctx.ctx_scope != NULL)
drop_scope(&cctx);
if (errormsg != NULL)
emsg(errormsg);
else if (did_emsg == did_emsg_before)
emsg(_(e_compiling_def_function_failed));
}
if (cctx.ctx_redir_lhs.lhs_name != NULL)
{
if (ret == OK)
{
emsg(_(e_missing_redir_end));
ret = FAIL;
}
vim_free(cctx.ctx_redir_lhs.lhs_name);
vim_free(cctx.ctx_redir_lhs.lhs_whole);
}
current_sctx = save_current_sctx;
estack_compiling = save_estack_compiling;
cmdmod.cmod_flags =save_cmod_flags;
if (do_estack_push)
estack_pop();
vim_free(line_to_free);
free_imported(&cctx);
free_locals(&cctx);
ga_clear(&cctx.ctx_type_stack);
return ret;
}

static int
dissect_smb2_create_response(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, int offset, smb2_info_t *si)
{
guint64 end_of_file;
guint32attr_mask;
offset_length_buffer_t e_olb;
static const int *create_rep_flags_fields[] = {
&hf_smb2_create_rep_flags_reparse_point,
NULL
};
gboolean continue_dissection;
switch (si->status) {
case 0x00000000: offset = dissect_smb2_buffercode(tree, tvb, offset, NULL); break;
default: offset = dissect_smb2_error_response(tvb, pinfo, tree, offset, si, &continue_dissection);
if (!continue_dissection) return offset;
}
offset = dissect_smb2_oplock(tree, tvb, offset);
proto_tree_add_bitmask(tree, tvb, offset, hf_smb2_create_rep_flags,
ett_smb2_create_rep_flags, create_rep_flags_fields, ENC_LITTLE_ENDIAN);
offset += 1;
proto_tree_add_item(tree, hf_smb2_create_action, tvb, offset, 4, ENC_LITTLE_ENDIAN);
offset += 4;
offset = dissect_nt_64bit_time(tvb, tree, offset, hf_smb2_create_timestamp);
offset = dissect_nt_64bit_time(tvb, tree, offset, hf_smb2_last_access_timestamp);
offset = dissect_nt_64bit_time(tvb, tree, offset, hf_smb2_last_write_timestamp);
offset = dissect_nt_64bit_time(tvb, tree, offset, hf_smb2_last_change_timestamp);
proto_tree_add_item(tree, hf_smb2_allocation_size, tvb, offset, 8, ENC_LITTLE_ENDIAN);
offset += 8;
end_of_file = tvb_get_letoh64(tvb, offset);
if (si->eo_file_info) {
si->eo_file_info->end_of_file = tvb_get_letoh64(tvb, offset);
}
proto_tree_add_item(tree, hf_smb2_end_of_file, tvb, offset, 8, ENC_LITTLE_ENDIAN);
offset += 8;
attr_mask=tvb_get_letohl(tvb, offset);
offset = dissect_file_ext_attr(tvb, tree, offset);
proto_tree_add_item(tree, hf_smb2_reserved, tvb, offset, 4, ENC_NA);
offset += 4;
offset = dissect_smb2_fid(tvb, pinfo, tree, offset, si, FID_MODE_OPEN);
if (si->eo_file_info) {
si->eo_file_info->end_of_file = end_of_file;
si->eo_file_info->attr_mask = attr_mask;
}
offset = dissect_smb2_olb_length_offset(tvb, offset, &e_olb, OLB_O_UINT32_S_UINT32, hf_smb2_extrainfo);
dissect_smb2_olb_buffer(pinfo, tree, tvb, &e_olb, si, dissect_smb2_create_extra_info);
offset = dissect_smb2_olb_tvb_max_offset(offset, &e_olb);
if (si->saved && si->saved->extra_info_type == SMB2_EI_FILENAME) {
g_free(si->saved->extra_info);
si->saved->extra_info = NULL;
si->saved->extra_info_type = SMB2_EI_NONE;
}
return offset;
}

long readSInt32(FILE *f)
{
long result = 0;
result |= readUInt8(f);
result |= readUInt8(f) << 8;
result |= readUInt8(f) << 16;
result |= readUInt8(f) << 24;
return result;
}

static void ExportRGBQuantum(QuantumInfo *quantum_info,
const MagickSizeType number_pixels,const PixelPacket *magick_restrict p,
unsigned char *magick_restrict q)
{
QuantumAny
range;
ssize_t
x;
ssize_t
bit;
switch (quantum_info->depth)
{
case 8:
{
for (x=0; x < (ssize_t) number_pixels; x++)
{
q=PopCharPixel(ScaleQuantumToChar(GetPixelRed(p)),q);
q=PopCharPixel(ScaleQuantumToChar(GetPixelGreen(p)),q);
q=PopCharPixel(ScaleQuantumToChar(GetPixelBlue(p)),q);
p++;
q+=quantum_info->pad;
}
break;
}
case 10:
{
unsigned int
pixel;
range=GetQuantumRange(quantum_info->depth);
if (quantum_info->pack == MagickFalse)
{
for (x=0; x < (ssize_t) number_pixels; x++)
{
pixel=(unsigned int) (
ScaleQuantumToAny(GetPixelRed(p),range) << 22 |
ScaleQuantumToAny(GetPixelGreen(p),range) << 12 |
ScaleQuantumToAny(GetPixelBlue(p),range) << 2);
q=PopLongPixel(quantum_info->endian,pixel,q);
p++;
q+=quantum_info->pad;
}
break;
}
if (quantum_info->quantum == 32UL)
{
for (x=0; x < (ssize_t) number_pixels; x++)
{
pixel=(unsigned int) ScaleQuantumToAny(GetPixelRed(p),range);
q=PopQuantumLongPixel(quantum_info,pixel,q);
pixel=(unsigned int) ScaleQuantumToAny(GetPixelGreen(p),range);
q=PopQuantumLongPixel(quantum_info,pixel,q);
pixel=(unsigned int) ScaleQuantumToAny(GetPixelBlue(p),range);
q=PopQuantumLongPixel(quantum_info,pixel,q);
p++;
q+=quantum_info->pad;
}
break;
}
for (x=0; x < (ssize_t) number_pixels; x++)
{
pixel=(unsigned int) ScaleQuantumToAny(GetPixelRed(p),range);
q=PopQuantumPixel(quantum_info,pixel,q);
pixel=(unsigned int) ScaleQuantumToAny(GetPixelGreen(p),range);
q=PopQuantumPixel(quantum_info,pixel,q);
pixel=(unsigned int) ScaleQuantumToAny(GetPixelBlue(p),range);
q=PopQuantumPixel(quantum_info,pixel,q);
p++;
q+=quantum_info->pad;
}
break;
}
case 12:
{
unsigned int
pixel;
range=GetQuantumRange(quantum_info->depth);
if (quantum_info->pack == MagickFalse)
{
for (x=0; x < (ssize_t) (3*number_pixels-1); x+=2)
{
switch (x % 3)
{
default:
case 0:
{
pixel=(unsigned int) ScaleQuantumToAny(GetPixelRed(p),range);
break;
}
case 1:
{
pixel=(unsigned int) ScaleQuantumToAny(GetPixelGreen(p),range);
break;
}
case 2:
{
pixel=(unsigned int) ScaleQuantumToAny(GetPixelBlue(p),range);
p++;
break;
}
}
q=PopShortPixel(quantum_info->endian,(unsigned short) (pixel << 4),q);
switch ((x+1) % 3)
{
default:
case 0:
{
pixel=(unsigned int) ScaleQuantumToAny(GetPixelRed(p),range);
break;
}
case 1:
{
pixel=(unsigned int) ScaleQuantumToAny(GetPixelGreen(p),range);
break;
}
case 2:
{
pixel=(unsigned int) ScaleQuantumToAny(GetPixelBlue(p),range);
p++;
break;
}
}
q=PopShortPixel(quantum_info->endian,(unsigned short) (pixel << 4),q);
q+=quantum_info->pad;
}
for (bit=0; bit < (ssize_t) (3*number_pixels % 2); bit++)
{
switch ((x+bit) % 3)
{
default:
case 0:
{
pixel=(unsigned int) ScaleQuantumToAny(GetPixelRed(p),range);
break;
}
case 1:
{
pixel=(unsigned int) ScaleQuantumToAny(GetPixelGreen(p),range);
break;
}
case 2:
{
pixel=(unsigned int) ScaleQuantumToAny(GetPixelBlue(p),range);
p++;
break;
}
}
q=PopShortPixel(quantum_info->endian,(unsigned short) (pixel << 4),q);
q+=quantum_info->pad;
}
if (bit != 0)
p++;
break;
}
if (quantum_info->quantum == 32UL)
{
for (x=0; x < (ssize_t) number_pixels; x++)
{
pixel=(unsigned int) ScaleQuantumToAny(GetPixelRed(p),range);
q=PopQuantumLongPixel(quantum_info,pixel,q);
pixel=(unsigned int) ScaleQuantumToAny(GetPixelGreen(p),range);
q=PopQuantumLongPixel(quantum_info,pixel,q);
pixel=(unsigned int) ScaleQuantumToAny(GetPixelBlue(p),range);
q=PopQuantumLongPixel(quantum_info,pixel,q);
p++;
q+=quantum_info->pad;
}
break;
}
for (x=0; x < (ssize_t) number_pixels; x++)
{
pixel=(unsigned int) ScaleQuantumToAny(GetPixelRed(p),range);
q=PopQuantumPixel(quantum_info,pixel,q);
pixel=(unsigned int) ScaleQuantumToAny(GetPixelGreen(p),range);
q=PopQuantumPixel(quantum_info,pixel,q);
pixel=(unsigned int) ScaleQuantumToAny(GetPixelBlue(p),range);
q=PopQuantumPixel(quantum_info,pixel,q);
p++;
q+=quantum_info->pad;
}
break;
}
case 16:
{
unsigned short
pixel;
if (quantum_info->format == FloatingPointQuantumFormat)
{
for (x=0; x < (ssize_t) number_pixels; x++)
{
pixel=SinglePrecisionToHalf(QuantumScale*GetPixelRed(p));
q=PopShortPixel(quantum_info->endian,pixel,q);
pixel=SinglePrecisionToHalf(QuantumScale*GetPixelGreen(p));
q=PopShortPixel(quantum_info->endian,pixel,q);
pixel=SinglePrecisionToHalf(QuantumScale*GetPixelBlue(p));
q=PopShortPixel(quantum_info->endian,pixel,q);
p++;
q+=quantum_info->pad;
}
break;
}
for (x=0; x < (ssize_t) number_pixels; x++)
{
pixel=ScaleQuantumToShort(GetPixelRed(p));
q=PopShortPixel(quantum_info->endian,pixel,q);
pixel=ScaleQuantumToShort(GetPixelGreen(p));
q=PopShortPixel(quantum_info->endian,pixel,q);
pixel=ScaleQuantumToShort(GetPixelBlue(p));
q=PopShortPixel(quantum_info->endian,pixel,q);
p++;
q+=quantum_info->pad;
}
break;
}
case 32:
{
unsigned int
pixel;
if (quantum_info->format == FloatingPointQuantumFormat)
{
for (x=0; x < (ssize_t) number_pixels; x++)
{
q=PopFloatPixel(quantum_info,(float) GetPixelRed(p),q);
q=PopFloatPixel(quantum_info,(float) GetPixelGreen(p),q);
q=PopFloatPixel(quantum_info,(float) GetPixelBlue(p),q);
p++;
q+=quantum_info->pad;
}
break;
}
for (x=0; x < (ssize_t) number_pixels; x++)
{
pixel=ScaleQuantumToLong(GetPixelRed(p));
q=PopLongPixel(quantum_info->endian,pixel,q);
pixel=ScaleQuantumToLong(GetPixelGreen(p));
q=PopLongPixel(quantum_info->endian,pixel,q);
pixel=ScaleQuantumToLong(GetPixelBlue(p));
q=PopLongPixel(quantum_info->endian,pixel,q);
p++;
q+=quantum_info->pad;
}
break;
}
case 64:
{
if (quantum_info->format == FloatingPointQuantumFormat)
{
for (x=0; x < (ssize_t) number_pixels; x++)
{
q=PopDoublePixel(quantum_info,(double) GetPixelRed(p),q);
q=PopDoublePixel(quantum_info,(double) GetPixelGreen(p),q);
q=PopDoublePixel(quantum_info,(double) GetPixelBlue(p),q);
p++;
q+=quantum_info->pad;
}
break;
}
}
default:
{
range=GetQuantumRange(quantum_info->depth);
for (x=0; x < (ssize_t) number_pixels; x++)
{
q=PopQuantumPixel(quantum_info,
ScaleQuantumToAny(GetPixelRed(p),range),q);
q=PopQuantumPixel(quantum_info,
ScaleQuantumToAny(GetPixelGreen(p),range),q);
q=PopQuantumPixel(quantum_info,
ScaleQuantumToAny(GetPixelBlue(p),range),q);
p++;
q+=quantum_info->pad;
}
break;
}
}
}

int new_guest_cr3(mfn_t mfn)
{
struct vcpu *curr = current;
struct domain *d = curr->domain;
int rc;
mfn_t old_base_mfn;
if ( is_pv_32bit_domain(d) )
{
mfn_t gt_mfn = pagetable_get_mfn(curr->arch.guest_table);
l4_pgentry_t *pl4e = map_domain_page(gt_mfn);
rc = mod_l4_entry(pl4e,
l4e_from_mfn(mfn,
(_PAGE_PRESENT | _PAGE_RW |
_PAGE_USER | _PAGE_ACCESSED)),
mfn_x(gt_mfn), 0, curr);
unmap_domain_page(pl4e);
switch ( rc )
{
case 0:
break;
case -EINTR:
case -ERESTART:
return -ERESTART;
default:
gdprintk(XENLOG_WARNING,
"Error while installing new compat baseptr %" PRI_mfn "\n",
mfn_x(mfn));
return rc;
}
invalidate_shadow_ldt(curr, 0);
write_ptbase(curr);
return 0;
}
rc = put_old_guest_table(curr);
if ( unlikely(rc) )
return rc;
old_base_mfn = pagetable_get_mfn(curr->arch.guest_table);
if ( mfn_eq(old_base_mfn, mfn) )
{
write_ptbase(curr);
return 0;
}
rc = paging_mode_refcounts(d)
? (get_page_from_mfn(mfn, d) ? 0 : -EINVAL)
: get_page_and_type_from_mfn(mfn, PGT_root_page_table, d, 0, 1);
switch ( rc )
{
case 0:
break;
case -EINTR:
case -ERESTART:
return -ERESTART;
default:
gdprintk(XENLOG_WARNING,
"Error while installing new baseptr %" PRI_mfn "\n",
mfn_x(mfn));
return rc;
}
invalidate_shadow_ldt(curr, 0);
if ( !VM_ASSIST(d, m2p_strict) && !paging_mode_refcounts(d) )
fill_ro_mpt(mfn);
curr->arch.guest_table = pagetable_from_mfn(mfn);
update_cr3(curr);
write_ptbase(curr);
if ( likely(mfn_x(old_base_mfn) != 0) )
{
struct page_info *page = mfn_to_page(old_base_mfn);
if ( paging_mode_refcounts(d) )
put_page(page);
else
switch ( rc = put_page_and_type_preemptible(page) )
{
case -EINTR:
rc = -ERESTART;
case -ERESTART:
curr->arch.old_guest_table = page;
break;
default:
BUG_ON(rc);
break;
}
}
return rc;
}

static void GTextFieldSave(GTextField *gt,int utf8) {
unichar_t *ret;
char *cret;
FILE *file;
unichar_t *pt;
if ( _ggadget_use_gettext ) {
char *temp = GWidgetOpenFile8(_("Save"),NULL,"*.{txt,py}",NULL,NULL);
ret = utf82u_copy(temp);
free(temp);
} else
ret = GWidgetSaveAsFile(GStringGetResource(_STR_Save,NULL),NULL,
txt,NULL,NULL);
if ( ret==NULL )
return;
cret = u2def_copy(ret);
free(ret);
file = fopen(cret,"w");
if ( file==NULL ) {
if ( _ggadget_use_gettext )
GWidgetError8(_("Could not open file"), _("Could not open %.100s"),cret);
else
GWidgetError(errort,error,cret);
free(cret);
return;
}
free(cret);
if ( utf8 ) {
putc(0xef,file);
putc(0xbb,file);
putc(0xbf,file);
for ( pt = gt->text ; *pt; ++pt ) {
if ( *pt<0x80 )
putc(*pt,file);
else if ( *pt<0x800 ) {
putc(0xc0 | (*pt>>6), file);
putc(0x80 | (*pt&0x3f), file);
} else if ( *pt>=0xd800 && *pt<0xdc00 && pt[1]>=0xdc00 && pt[1]<0xe000 ) {
int u = ((*pt>>6)&0xf)+1, y = ((*pt&3)<<4) | ((pt[1]>>6)&0xf);
putc( 0xf0 | (u>>2),file );
putc( 0x80 | ((u&3)<<4) | ((*pt>>2)&0xf),file );
putc( 0x80 | y,file );
putc( 0x80 | (pt[1]&0x3f),file );
} else {
putc( 0xe0 | (*pt>>12),file );
putc( 0x80 | ((*pt>>6)&0x3f),file );
putc( 0x80 | (*pt&0x3f),file );
}
}
} else {
putc(0xfeff>>8,file);
putc(0xfeff&0xff,file);
for ( pt = gt->text ; *pt; ++pt ) {
putc(*pt>>8,file);
putc(*pt&0xff,file);
}
}
fclose(file);
}

bool SDP_AddAttribute(uint32_t handle, uint16_t attr_id, uint8_t attr_type,
uint32_t attr_len, uint8_t* p_val) {
uint16_t xx, yy, zz;
tSDP_RECORD* p_rec = &sdp_cb.server_db.record[0];
if (sdp_cb.trace_level >= BT_TRACE_LEVEL_DEBUG) {
if ((attr_type == UINT_DESC_TYPE) ||
(attr_type == TWO_COMP_INT_DESC_TYPE) ||
(attr_type == UUID_DESC_TYPE) ||
(attr_type == DATA_ELE_SEQ_DESC_TYPE) ||
(attr_type == DATA_ELE_ALT_DESC_TYPE)) {
uint8_t num_array[400];
uint32_t len = (attr_len > 200) ? 200 : attr_len;
num_array[0] = '\0';
for (uint32_t i = 0; i < len; i++) {
snprintf((char*)&num_array[i * 2], sizeof(num_array) - i * 2, "%02X",
(uint8_t)(p_val[i]));
}
SDP_TRACE_DEBUG(
"SDP_AddAttribute: handle:%X, id:%04X, type:%d, len:%d, p_val:%p, "
"*p_val:%s",
handle, attr_id, attr_type, attr_len, p_val, num_array);
} else if (attr_type == BOOLEAN_DESC_TYPE) {
SDP_TRACE_DEBUG(
"SDP_AddAttribute: handle:%X, id:%04X, type:%d, len:%d, p_val:%p, "
"*p_val:%d",
handle, attr_id, attr_type, attr_len, p_val, *p_val);
} else if ((attr_type == TEXT_STR_DESC_TYPE) ||
(attr_type == URL_DESC_TYPE)) {
if (p_val[attr_len - 1] == '\0') {
SDP_TRACE_DEBUG(
"SDP_AddAttribute: handle:%X, id:%04X, type:%d, len:%d, p_val:%p, "
"*p_val:%s",
handle, attr_id, attr_type, attr_len, p_val, (char*)p_val);
} else {
SDP_TRACE_DEBUG(
"SDP_AddAttribute: handle:%X, id:%04X, type:%d, len:%d, p_val:%p",
handle, attr_id, attr_type, attr_len, p_val);
}
} else {
SDP_TRACE_DEBUG(
"SDP_AddAttribute: handle:%X, id:%04X, type:%d, len:%d, p_val:%p",
handle, attr_id, attr_type, attr_len, p_val);
}
}
for (zz = 0; zz < sdp_cb.server_db.num_records; zz++, p_rec++) {
if (p_rec->record_handle == handle) {
tSDP_ATTRIBUTE* p_attr = &p_rec->attribute[0];
for (xx = 0; xx < p_rec->num_attributes; xx++, p_attr++) {
if (p_attr->id == attr_id) {
SDP_DeleteAttribute(handle, attr_id);
break;
}
if (p_attr->id > attr_id) break;
}
if (p_rec->num_attributes == SDP_MAX_REC_ATTR) return (false);
if (xx == p_rec->num_attributes)
p_attr = &p_rec->attribute[p_rec->num_attributes];
else {
for (yy = p_rec->num_attributes; yy > xx; yy--)
p_rec->attribute[yy] = p_rec->attribute[yy - 1];
}
p_attr->id = attr_id;
p_attr->type = attr_type;
p_attr->len = attr_len;
if (p_rec->free_pad_ptr + attr_len >= SDP_MAX_PAD_LEN) {
if (attr_type == TEXT_STR_DESC_TYPE) {
SDP_TRACE_WARNING(
"SDP_AddAttribute: attr_len:%d too long. truncate to (%d)",
attr_len, SDP_MAX_PAD_LEN - p_rec->free_pad_ptr);
attr_len = SDP_MAX_PAD_LEN - p_rec->free_pad_ptr;
p_val[SDP_MAX_PAD_LEN - p_rec->free_pad_ptr - 1] = '\0';
} else
attr_len = 0;
}
if ((attr_len > 0) && (p_val != 0)) {
p_attr->len = attr_len;
memcpy(&p_rec->attr_pad[p_rec->free_pad_ptr], p_val, (size_t)attr_len);
p_attr->value_ptr = &p_rec->attr_pad[p_rec->free_pad_ptr];
p_rec->free_pad_ptr += attr_len;
} else if ((attr_len == 0 &&
p_attr->len !=
0) || 
p_val == 0) {
SDP_TRACE_ERROR(
"SDP_AddAttribute fail, length exceed maximum: ID %d: attr_len:%d ",
attr_id, attr_len);
p_attr->id = p_attr->type = p_attr->len = 0;
return (false);
}
p_rec->num_attributes++;
return (true);
}
}
return (false);
}

