if (shdr->sh_size < 1 || shdr->sh_size > SIZE_MAX) {
return false;
}
Elf_(Verdef) *defs = calloc (shdr->sh_size, sizeof (char));
if (!defs) {
return false;
}
if (bin->shstrtab && shdr->sh_name < bin->shstrtab_size) {
section_name = &bin->shstrtab[shdr->sh_name];
}
if (link_shdr && bin->shstrtab && link_shdr->sh_name < bin->shstrtab_size) {
link_section_name = &bin->shstrtab[link_shdr->sh_name];
}
if (!defs) {
bprintf ("Warning: Cannot allocate memory (Check Elf_(Verdef))\n");
return NULL;
}
sdb = sdb_new0 ();
end = (char *)defs + shdr->sh_size;
sdb_set (sdb, "section_name", section_name, 0);
sdb_num_set (sdb, "entries", shdr->sh_info, 0);
sdb_num_set (sdb, "addr", shdr->sh_addr, 0);
sdb_num_set (sdb, "offset", shdr->sh_offset, 0);
sdb_num_set (sdb, "link", shdr->sh_link, 0);
sdb_set (sdb, "link_section_name", link_section_name, 0);
for (cnt = 0, i = 0; i >= 0 && cnt < shdr->sh_info && ((char *)defs + i < end); ++cnt) {
Sdb *sdb_verdef = sdb_new0 ();
char *vstart = ((char*)defs) + i;
char key[32] = {0};
Elf_(Verdef) *verdef = (Elf_(Verdef)*)vstart;
Elf_(Verdaux) aux = {0};
int j = 0;
int isum = 0;
r_buf_read_at (bin->b, shdr->sh_offset + i, dfs, sizeof (Elf_(Verdef)));
verdef->vd_version = READ16 (dfs, j)
verdef->vd_flags = READ16 (dfs, j)
verdef->vd_ndx = READ16 (dfs, j)
verdef->vd_cnt = READ16 (dfs, j)
verdef->vd_hash = READ32 (dfs, j)
verdef->vd_aux = READ32 (dfs, j)
verdef->vd_next = READ32 (dfs, j)
int vdaux = verdef->vd_aux;
if (vdaux < 1) {
sdb_free (sdb_verdef);
goto out_error;
}
vstart += vdaux;
if (vstart > end || vstart + sizeof (Elf_(Verdaux)) > end) {
sdb_free (sdb_verdef);
goto out_error;
}
j = 0;
aux.vda_name = READ32 (vstart, j)
aux.vda_next = READ32 (vstart, j)
isum = i + verdef->vd_aux;
if (aux.vda_name > bin->dynstr_size) {
sdb_free (sdb_verdef);
goto out_error;
}
sdb_num_set (sdb_verdef, "idx", i, 0);
sdb_num_set (sdb_verdef, "vd_version", verdef->vd_version, 0);
sdb_num_set (sdb_verdef, "vd_ndx", verdef->vd_ndx, 0);
sdb_num_set (sdb_verdef, "vd_cnt", verdef->vd_cnt, 0);
sdb_set (sdb_verdef, "vda_name", &bin->dynstr[aux.vda_name], 0);
sdb_set (sdb_verdef, "flags", get_ver_flags (verdef->vd_flags), 0);
for (j = 1; j < verdef->vd_cnt; ++j) {
int k;
Sdb *sdb_parent = sdb_new0 ();
isum += aux.vda_next;
vstart += aux.vda_next;
if (vstart > end || vstart + sizeof(Elf_(Verdaux)) > end) {
sdb_free (sdb_verdef);
sdb_free (sdb_parent);
goto out_error;
}
k = 0;
aux.vda_name = READ32 (vstart, k)
aux.vda_next = READ32 (vstart, k)
if (aux.vda_name > bin->dynstr_size) {
sdb_free (sdb_verdef);
sdb_free (sdb_parent);
goto out_error;
}
sdb_num_set (sdb_parent, "idx", isum, 0);
sdb_num_set (sdb_parent, "parent", j, 0);
sdb_set (sdb_parent, "vda_name", &bin->dynstr[aux.vda_name], 0);
snprintf (key, sizeof (key), "parent%d", j - 1);
sdb_ns_set (sdb_verdef, key, sdb_parent);
}
snprintf (key, sizeof (key), "verdef%d", cnt);
sdb_ns_set (sdb, key, sdb_verdef);
if (!verdef->vd_next) {
sdb_free (sdb_verdef);
goto out_error;
}
if ((st32)verdef->vd_next < 1) {
eprintf ("Warning: Invalid vd_next in the ELF version\n");
break;
}
i += verdef->vd_next;
}

static void get_ivar_list_t(mach0_ut p, RBinFile *bf, RBinClass *klass) {
struct MACH0_(SIVarList) il;
struct MACH0_(SIVar) i;
mach0_ut r;
ut32 offset, left, j;
char *name = NULL;
char *type = NULL;
int len;
bool bigendian;
mach0_ut ivar_offset_p, ivar_offset;
RBinField *field = NULL;
ut8 sivarlist[sizeof (struct MACH0_(SIVarList))] = {0};
ut8 sivar[sizeof (struct MACH0_(SIVar))] = {0};
ut8 offs[sizeof (mach0_ut)] = {0};
if (!bf || !bf->o || !bf->o->bin_obj || !bf->o->info) {
eprintf ("uncorrect RBinFile pointer\n");
return;
}
bigendian = bf->o->info->big_endian;
if (!(r = get_pointer (p, &offset, &left, bf))) {
return;
}
memset (&il, '\0', sizeof (struct MACH0_(SIVarList)));
if (r + left < r || r + sizeof (struct MACH0_(SIVarList)) < r) {
return;
}
if (r > bf->size || r + left > bf->size) {
return;
}
if (r + sizeof (struct MACH0_(SIVarList)) > bf->size) {
return;
}
if (left < sizeof (struct MACH0_(SIVarList))) {
if (r_buf_read_at (bf->buf, r, sivarlist, left) != left) {
return;
}
} else {
len = r_buf_read_at (bf->buf, r, sivarlist, sizeof (struct MACH0_(SIVarList)));
if (len != sizeof (struct MACH0_(SIVarList))) {
return;
}
}
il.entsize = r_read_ble (&sivarlist[0], bigendian, 32);
il.count = r_read_ble (&sivarlist[4], bigendian, 32);
p += sizeof (struct MACH0_(SIVarList));
offset += sizeof (struct MACH0_(SIVarList));
for (j = 0; j < il.count; j++) {
r = get_pointer (p, &offset, &left, bf);
if (!r) {
return;
}
if (!(field = R_NEW0 (RBinField))) {
return;
}
memset (&i, '\0', sizeof (struct MACH0_(SIVar)));
if (r + left < r || r + sizeof (struct MACH0_(SIVar)) < r) {
goto error;
}
if (r > bf->size || r + left > bf->size) {
goto error;
}
if (r + sizeof (struct MACH0_(SIVar)) > bf->size) {
goto error;
}
if (left < sizeof (struct MACH0_(SIVar))) {
if (r_buf_read_at (bf->buf, r, sivar, left) != left) {
goto error;
}
} else {
len = r_buf_read_at (bf->buf, r, sivar, sizeof (struct MACH0_(SIVar)));
if (len != sizeof (struct MACH0_(SIVar))) {
goto error;
}
}
switch (sizeof (mach0_ut)) {
case 4:
i.offset = r_read_ble (&sivar[0], bigendian, 32);
i.name = r_read_ble (&sivar[4], bigendian, 32);
i.type = r_read_ble (&sivar[8], bigendian, 32);
i.alignment = r_read_ble (&sivar[12], bigendian, 32);
i.size = r_read_ble (&sivar[16], bigendian, 32);
break;
case 8:
i.offset = r_read_ble (&sivar[0], bigendian, 64);
i.name = r_read_ble (&sivar[8], bigendian, 64);
i.type = r_read_ble (&sivar[16], bigendian, 64);
i.alignment = r_read_ble (&sivar[24], bigendian, 32);
i.size = r_read_ble (&sivar[28], bigendian, 32);
break;
}
ivar_offset_p = get_pointer (i.offset, NULL, &left, bf);
if (ivar_offset_p > bf->size) {
goto error;
}
if (ivar_offset_p + sizeof (ivar_offset) > bf->size) {
goto error;
}
if (ivar_offset_p != 0 && left >= sizeof (mach0_ut)) {
len = r_buf_read_at (bf->buf, ivar_offset_p, offs, sizeof (mach0_ut));
if (len != sizeof (mach0_ut)) {
eprintf ("Error reading\n");
goto error;
}
ivar_offset = r_read_ble (offs, bigendian, 8 * sizeof (mach0_ut));
field->vaddr = ivar_offset;
}
r = get_pointer (i.name, NULL, &left, bf);
if (r != 0) {
struct MACH0_(obj_t) *bin = (struct MACH0_(obj_t) *)bf->o->bin_obj;
if (r + left < r) {
goto error;
}
if (r > bf->size || r + left > bf->size) {
goto error;
}
if (bin->has_crypto) {
name = strdup ("some_encrypted_data");
left = strlen (name) + 1;
} else {
name = malloc (left + 1);
len = r_buf_read_at (bf->buf, r, (ut8 *)name, left);
if (len < 1) {
eprintf ("Error reading\n");
R_FREE (name);
goto error;
}
name[left] = 0;
}
field->name = r_str_newf ("%s::%s%s", klass->name, "(ivar)", name);
R_FREE (name);
}
r = get_pointer (i.type, NULL, &left, bf);
if (r != 0) {
struct MACH0_(obj_t) *bin = (struct MACH0_(obj_t) *) bf->o->bin_obj;
int is_crypted = bin->has_crypto;
if (r + left < r) {
goto error;
}
if (r > bf->size || r + left > bf->size) {
goto error;
}
if (is_crypted == 1) {
type = strdup ("some_encrypted_data");
} else {
type = calloc (1, left);
r_buf_read_at (bf->buf, r, (ut8 *)type, left);
}
field->type = strdup (type);
R_FREE (type);
}
r_list_append (klass->fields, field);
p += sizeof (struct MACH0_(SIVar));
offset += sizeof (struct MACH0_(SIVar));
}
return;
error:
r_bin_field_free (field);
}

static void
on_handler_vanished(GDBusConnection *connection,
const gchar     *name,
gpointer         user_data)
{
struct tcmur_handler *handler = user_data;
struct dbus_info *info = handler->opaque;
if (info->register_invocation) {
char *reason;
reason = g_strdup_printf("Cannot find handler bus name: "
"org.kernel.TCMUService1.HandlerManager1.%s",
handler->subtype);
g_dbus_method_invocation_return_value(info->register_invocation,
g_variant_new("(bs)", FALSE, reason));
g_free(reason);
}
tcmur_unregister_handler(handler);
dbus_unexport_handler(handler);
}

xls_error_t xls_parseWorkBook(xlsWorkBook* pWB)
{
if(!pWB) return LIBXLS_ERROR_NULL_ARGUMENT;
BOF bof1 = { .id = 0, .size = 0 };
BOF bof2 = { .id = 0, .size = 0 };
BYTE* buf = NULL;
BYTE once = 0;
xls_error_t retval = LIBXLS_OK;
verbose ("xls_parseWorkBook");
do {
if(xls_debug > 10) {
printf("READ WORKBOOK filePos=%ld\n",  (long)pWB->filepos);
printf("  OLE: start=%d pos=%u size=%u fatPos=%u\n",
pWB->olestr->start, (unsigned int)pWB->olestr->pos,
(unsigned int)pWB->olestr->size, (unsigned int)pWB->olestr->fatpos); 
}
if (ole2_read(&bof1, 1, 4, pWB->olestr) != 4) {
retval = LIBXLS_ERROR_READ;
goto cleanup;
}
xlsConvertBof(&bof1);
if(xls_debug) xls_showBOF(&bof1);
if (bof1.size) {
if ((buf = realloc(buf, bof1.size)) == NULL) {
if (xls_debug) fprintf(stderr, "Error: failed to allocate buffer of size %d\n", (int)bof1.size);
retval = LIBXLS_ERROR_MALLOC;
goto cleanup;
}
if (ole2_read(buf, 1, bof1.size, pWB->olestr) != bof1.size) {
if (xls_debug) fprintf(stderr, "Error: failed to read OLE block\n");
retval = LIBXLS_ERROR_READ;
goto  cleanup;
}
}
if (xls_isRecordTooSmall(pWB, &bof1)) {
retval = LIBXLS_ERROR_PARSE;
goto cleanup;
}
switch (bof1.id) {
case XLS_RECORD_EOF:
break;
case XLS_RECORD_BOF:            pWB->is5ver = (buf[0] + (buf[1] << 8) != 0x600);
pWB->type = buf[2] + (buf[3] << 8);
if(xls_debug) {
printf("version: %s\n", pWB->is5ver ? "BIFF5" : "BIFF8" );
printf("   type: %.2X\n", pWB->type);
}
break;
case XLS_RECORD_CODEPAGE:
pWB->codepage = buf[0] + (buf[1] << 8);
if(xls_debug) printf("codepage: %d\n", pWB->codepage);
break;
case XLS_RECORD_CONTINUE:
if(once) {
if (bof2.id==XLS_RECORD_SST) {
if ((retval = xls_appendSST(pWB,buf,bof1.size)) != LIBXLS_OK)
goto cleanup;
}
bof1=bof2;
}
break;
case XLS_RECORD_WINDOW1:
{
WIND1 *w = (WIND1*)buf;
xlsConvertWindow(w);
pWB->activeSheetIdx = w->itabCur;
if(xls_debug) {
printf("WINDOW1: ");
printf("xWn    : %d\n", w->xWn/20);
printf("yWn    : %d\n", w->yWn/20);
printf("dxWn   : %d\n", w->dxWn/20);
printf("dyWn   : %d\n", w->dyWn/20);
printf("grbit  : %d\n", w->grbit);
printf("itabCur: %d\n", w->itabCur);
printf("itabFi : %d\n", w->itabFirst);
printf("ctabSel: %d\n", w->ctabSel);
printf("wTabRat: %d\n", w->wTabRatio);
}
}
break;
case XLS_RECORD_SST:
xlsConvertSst((SST *)buf);
if ((retval = xls_addSST(pWB,(SST*)buf,bof1.size)) != LIBXLS_OK) {
goto cleanup;
}
break;
case XLS_RECORD_EXTSST:
break;
case XLS_RECORD_BOUNDSHEET:
{
BOUNDSHEET *bs = (BOUNDSHEET *)buf;
xlsConvertBoundsheet(bs);
if ((retval = xls_addSheet(pWB, bs, bof1.size)) != LIBXLS_OK) {
goto cleanup;
}
}
break;
case XLS_RECORD_XF:
if(pWB->is5ver) {
XF5 *xf;
xf = (XF5 *)buf;
xlsConvertXf5(xf);
if ((retval = xls_addXF5(pWB,xf)) != LIBXLS_OK) {
goto cleanup;
}
if(xls_debug) {
printf("   font: %d\n", xf->font);
printf(" format: %d\n", xf->format);
printf("   type: %.4x\n", xf->type);
printf("  align: %.4x\n", xf->align);
printf("rotatio: %.4x\n", xf->color);
printf("  ident: %.4x\n", xf->fill);
printf("usedatt: %.4x\n", xf->border);
printf("linesty: %.4x\n", xf->linestyle);
}
} else {
XF8 *xf;
xf = (XF8 *)buf;
xlsConvertXf8(xf);
if ((retval = xls_addXF8(pWB,xf)) != LIBXLS_OK) {
goto cleanup;
}
if(xls_debug) {
xls_showXF(xf);
}
}
break;
case XLS_RECORD_FONT:
case XLS_RECORD_FONT_ALT:
{
char *s;
FONT *f = (FONT*)buf;
xlsConvertFont(f);
s = xls_addFont(pWB,f, bof1.size);
if(xls_debug) {
printf(" height: %d\n", f->height);
printf("   flag: 0x%x\n", f->flag);
printf("  color: 0x%x\n", f->color);
printf(" weight: %d\n", f->bold);
printf("escapem: 0x%x\n", f->escapement);
printf("underln: 0x%x\n", f->underline);
printf(" family: 0x%x\n", f->family);
printf("charset: 0x%x\n", f->charset);
if(s) printf("   name: %s\n", s);
}
}
break;
case XLS_RECORD_FORMAT:
xlsConvertFormat((FORMAT *)buf);
if ((retval = xls_addFormat(pWB, (FORMAT*)buf, bof1.size)) != LIBXLS_OK) {
goto cleanup;
}
break;
case XLS_RECORD_STYLE:
if(xls_debug) {
struct { unsigned short idx; unsigned char ident; unsigned char lvl; } *styl;
styl = (void *)buf;
printf("    idx: 0x%x\n", styl->idx & 0x07FF);
if(styl->idx & 0x8000) {
printf("  ident: 0x%x\n", styl->ident);
printf("  level: 0x%x\n", styl->lvl);
} else {
char *s = get_string((char *)&buf[2], bof1.size - 2, 1, pWB);
printf("  name=%s\n", s);
free(s);
}
}
break;
case XLS_RECORD_PALETTE:
if(xls_debug > 10) {
unsigned char *p = buf + 2;
int idx, len;
len = buf[0] + (buf[1] << 8);
for(idx=0; idx<len; ++idx) {
printf("   Index=0x%2.2x %2.2x%2.2x%2.2x\n", idx+8, p[0], p[1], p[2] );
p += 4;
}
}
break;
case XLS_RECORD_1904:
pWB->is1904 = *(BYTE *)buf;if(xls_debug) {
printf("   mode: 0x%x\n", pWB->is1904);
}
break;
case XLS_RECORD_FILEPASS:
retval = LIBXLS_ERROR_UNSUPPORTED_ENCRYPTION;
goto cleanup;
case XLS_RECORD_DEFINEDNAME:
if(xls_debug) {
int i;
printf("   DEFINEDNAME: ");
for(i=0; i<bof1.size; ++i) printf("%2.2x ", buf[i]);
printf("\n");
}
break;
default:
if(xls_debug)
{
printf("    Not Processed in parseWorkBook():  BOF=0x%4.4X size=%d\n", bof1.id, bof1.size);
}
break;
}
bof2=bof1;
once=1;
}
while ((!pWB->olestr->eof)&&(bof1.id!=XLS_RECORD_EOF));
cleanup:
if (buf)
free(buf);
return retval;
}

int write_output(void)
{
int fd;
struct filter_op *fop;
struct filter_header fh;
size_t ninst, i;
u_char *data;
ninst = compile_tree(&fop);
if (fop == NULL)
return -E_NOTHANDLED;
fd = open(EF_GBL_OPTIONS->output_file, O_CREAT | O_RDWR | O_TRUNC | O_BINARY, 0644);
ON_ERROR(fd, -1, "Can't create file %s", EF_GBL_OPTIONS->output_file);
fprintf(stdout, " Writing output to \'%s\' ", EF_GBL_OPTIONS->output_file);
fflush(stdout);
fh.magic = htons(EC_FILTER_MAGIC);
strncpy(fh.version, EC_VERSION, sizeof(fh.version));
fh.data = sizeof(fh);
data = create_data_segment(&fh, fop, ninst);
write(fd, &fh, sizeof(struct filter_header));
write(fd, data, fh.code - fh.data);
for (i = 0; i <= ninst; i++) {
print_progress_bar(&fop[i]);
write(fd, &fop[i], sizeof(struct filter_op));
}
close(fd);
fprintf(stdout, " done.\n\n");
fprintf(stdout, " -> Script encoded into %d instructions.\n\n", (int)(i - 1));
return E_SUCCESS;
}

int
ProcPutImage(ClientPtr client)
{
GC *pGC;
DrawablePtr pDraw;
long length;                
long lengthProto;           
char *tmpImage;
REQUEST(xPutImageReq);
REQUEST_AT_LEAST_SIZE(xPutImageReq);
VALIDATE_DRAWABLE_AND_GC(stuff->drawable, pDraw, DixWriteAccess);
if (stuff->format == XYBitmap) {
if ((stuff->depth != 1) ||
(stuff->leftPad >= (unsigned int) screenInfo.bitmapScanlinePad))
return BadMatch;
length = BitmapBytePad(stuff->width + stuff->leftPad);
}
else if (stuff->format == XYPixmap) {
if ((pDraw->depth != stuff->depth) ||
(stuff->leftPad >= (unsigned int) screenInfo.bitmapScanlinePad))
return BadMatch;
length = BitmapBytePad(stuff->width + stuff->leftPad);
length *= stuff->depth;
}
else if (stuff->format == ZPixmap) {
if ((pDraw->depth != stuff->depth) || (stuff->leftPad != 0))
return BadMatch;
length = PixmapBytePad(stuff->width, stuff->depth);
}
else {
client->errorValue = stuff->format;
return BadValue;
}
tmpImage = (char *) &stuff[1];
lengthProto = length;
if (lengthProto >= (INT32_MAX / stuff->height))
return BadLength;
if ((bytes_to_int32(lengthProto * stuff->height) +
bytes_to_int32(sizeof(xPutImageReq))) != client->req_len)
return BadLength;
ReformatImage(tmpImage, lengthProto * stuff->height,
stuff->format == ZPixmap ? BitsPerPixel(stuff->depth) : 1,
ClientOrder(client));
(*pGC->ops->PutImage) (pDraw, pGC, stuff->depth, stuff->dstX, stuff->dstY,
stuff->width, stuff->height,
stuff->leftPad, stuff->format, tmpImage);
return Success;
}

MagickExport ssize_t FormatMagickCaption(Image *image,DrawInfo *draw_info,
const MagickBooleanType split,TypeMetric *metrics,char **caption,
ExceptionInfo *exception)
{
char
*p,
*q,
*s;
MagickBooleanType
status;
size_t
width;
ssize_t
i,
n;
q=draw_info->text;
s=(char *) NULL;
width=0;
for (p=(*caption); GetUTFCode(p) != 0; p+=GetUTFOctets(p))
{
int
code;
code=GetUTFCode(p);
if (code == '\n')
{
q=draw_info->text;
continue;
}
if ((draw_info->word_break != BreakWordBreakType) &&
(IsUTFSpace(code) != MagickFalse) &&
(IsNonBreakingUTFSpace(code) == MagickFalse))
{
s=p;
if (width > image->columns)
p=ReplaceSpaceWithNewline(caption,s);
}
for (i=0; i < (ssize_t) GetUTFOctets(p); i++)
*q++=(*(p+i));
*q='\0';
status=GetTypeMetrics(image,draw_info,metrics,exception);
if (status == MagickFalse)
break;
width=(size_t) floor(metrics->width+draw_info->stroke_width+0.5);
if (width <= image->columns)
continue;
if (s != (char *) NULL)
p=ReplaceSpaceWithNewline(caption,s);
else
if ((split != MagickFalse) || (GetUTFOctets(p) > 2))
{
n=p-(*caption);
if ((n > 0) && ((*caption)[n-1] != '\n'))
{
char
*target;
target=AcquireString(*caption);
CopyMagickString(target,*caption,n+1);
ConcatenateMagickString(target,"\n",strlen(*caption)+1);
ConcatenateMagickString(target,p,strlen(*caption)+2);
(void) DestroyString(*caption);
*caption=target;
p=(*caption)+n;
}
}
q=draw_info->text;
s=(char *) NULL;
}
n=0;
for (p=(*caption); GetUTFCode(p) != 0; p+=GetUTFOctets(p))
if (GetUTFCode(p) == '\n')
n++;
return(n);
}

static int mwifiex_pcie_init_evt_ring(struct mwifiex_adapter *adapter)
{
struct pcie_service_card *card = adapter->card;
struct mwifiex_evt_buf_desc *desc;
struct sk_buff *skb;
dma_addr_t buf_pa;
int i;
for (i = 0; i < MWIFIEX_MAX_EVT_BD; i++) {
skb = dev_alloc_skb(MAX_EVENT_SIZE);
if (!skb) {
mwifiex_dbg(adapter, ERROR,
"Unable to allocate skb for EVENT buf.\n");
kfree(card->evtbd_ring_vbase);
return -ENOMEM;
}
skb_put(skb, MAX_EVENT_SIZE);
if (mwifiex_map_pci_memory(adapter, skb, MAX_EVENT_SIZE,
PCI_DMA_FROMDEVICE))
return -1;
buf_pa = MWIFIEX_SKB_DMA_ADDR(skb);
mwifiex_dbg(adapter, EVENT,
"info: EVT ring: skb=%p len=%d data=%p buf_pa=%#x:%x\n",
skb, skb->len, skb->data, (u32)buf_pa,
(u32)((u64)buf_pa >> 32));
card->evt_buf_list[i] = skb;
card->evtbd_ring[i] = (void *)(card->evtbd_ring_vbase +
(sizeof(*desc) * i));
desc = card->evtbd_ring[i];
desc->paddr = buf_pa;
desc->len = (u16)skb->len;
desc->flags = 0;
}
return 0;
}

static int sclp_ctl_ioctl_sccb(void __user *user_area)
{
struct sclp_ctl_sccb ctl_sccb;
struct sccb_header *sccb;
int rc;
if (copy_from_user(&ctl_sccb, user_area, sizeof(ctl_sccb)))
return -EFAULT;
if (!sclp_ctl_cmdw_supported(ctl_sccb.cmdw))
return -EOPNOTSUPP;
sccb = (void *) get_zeroed_page(GFP_KERNEL | GFP_DMA);
if (!sccb)
return -ENOMEM;
if (copy_from_user(sccb, u64_to_uptr(ctl_sccb.sccb), sizeof(*sccb))) {
rc = -EFAULT;
goto out_free;
}
if (sccb->length > PAGE_SIZE || sccb->length < 8)
return -EINVAL;
if (copy_from_user(sccb, u64_to_uptr(ctl_sccb.sccb), sccb->length)) {
rc = -EFAULT;
goto out_free;
}
rc = sclp_sync_request(ctl_sccb.cmdw, sccb);
if (rc)
goto out_free;
if (copy_to_user(u64_to_uptr(ctl_sccb.sccb), sccb, sccb->length))
rc = -EFAULT;
out_free:
free_page((unsigned long) sccb);
return rc;
}

int ossl_dh_compute_key(unsigned char *key, const BIGNUM *pub_key, DH *dh)
{
BN_CTX *ctx = NULL;
BN_MONT_CTX *mont = NULL;
BIGNUM *z = NULL, *pminus1;
int ret = -1;
if (BN_num_bits(dh->params.p) > OPENSSL_DH_MAX_MODULUS_BITS) {
ERR_raise(ERR_LIB_DH, DH_R_MODULUS_TOO_LARGE);
goto err;
}
if (BN_num_bits(dh->params.p) < DH_MIN_MODULUS_BITS) {
ERR_raise(ERR_LIB_DH, DH_R_MODULUS_TOO_SMALL);
return 0;
}
ctx = BN_CTX_new_ex(dh->libctx);
if (ctx == NULL)
goto err;
BN_CTX_start(ctx);
pminus1 = BN_CTX_get(ctx);
z = BN_CTX_get(ctx);
if (z == NULL)
goto err;
if (dh->priv_key == NULL) {
ERR_raise(ERR_LIB_DH, DH_R_NO_PRIVATE_VALUE);
goto err;
}
if (dh->flags & DH_FLAG_CACHE_MONT_P) {
mont = BN_MONT_CTX_set_locked(&dh->method_mont_p,
dh->lock, dh->params.p, ctx);
BN_set_flags(dh->priv_key, BN_FLG_CONSTTIME);
if (!mont)
goto err;
}
if (!dh->meth->bn_mod_exp(dh, z, pub_key, dh->priv_key, dh->params.p, ctx,
mont)) {
ERR_raise(ERR_LIB_DH, ERR_R_BN_LIB);
goto err;
}
if (BN_copy(pminus1, dh->params.p) == NULL
|| !BN_sub_word(pminus1, 1)
|| BN_cmp(z, BN_value_one()) <= 0
|| BN_cmp(z, pminus1) == 0) {
ERR_raise(ERR_LIB_DH, DH_R_INVALID_SECRET);
goto err;
}
ret = BN_bn2binpad(z, key, BN_num_bytes(dh->params.p));
err:
BN_clear(z); 
BN_CTX_end(ctx);
BN_CTX_free(ctx);
return ret;
}

