lineBits = readBits(f, 4);
byteAlign();
while(printShapeRec(f, &fillBits, &lineBits, 2)) ;
putchar('\n');
}
for(i=0; i<nGlyphs; ++i)
{
if(flags & FONTINFO2_WIDECODES)
