#ifdef USE_M17N
else if (mode == PC_CTRL || mode == PC_UNDEF) {
#else
else if (mode == PC_CTRL || IS_INTSPACE(*str)) {
#endif
PPUSH(PC_ASCII | effect | ex_efct(ex_effect), ' ');
