static int htc_config_pipe_credits(struct htc_target *target)
{
struct sk_buff *skb;
struct htc_config_pipe_msg *cp_msg;
int ret;
unsigned long time_left;
skb = alloc_skb(50 + sizeof(struct htc_frame_hdr), GFP_ATOMIC);
if (!skb) {
dev_err(target->dev, "failed to allocate send buffer\n");
return -ENOMEM;
}
skb_reserve(skb, sizeof(struct htc_frame_hdr));
cp_msg = skb_put(skb, sizeof(struct htc_config_pipe_msg));
cp_msg->message_id = cpu_to_be16(HTC_MSG_CONFIG_PIPE_ID);
cp_msg->pipe_id = USB_WLAN_TX_PIPE;
cp_msg->credits = target->credits;
target->htc_flags |= HTC_OP_CONFIG_PIPE_CREDITS;
ret = htc_issue_send(target, skb, skb->len, 0, ENDPOINT0);
if (ret)
goto err;
time_left = wait_for_completion_timeout(&target->cmd_wait, HZ);
if (!time_left) {
dev_err(target->dev, "HTC credit config timeout\n");
return -ETIMEDOUT;
}
return 0;
err:
kfree_skb(skb);
return -EINVAL;
}

static int ath6kl_wmi_pstream_timeout_event_rx(struct wmi *wmi, u8 *datap,
int len)
{
struct wmi_pstream_timeout_event *ev;
if (len < sizeof(struct wmi_pstream_timeout_event))
return -EINVAL;
ev = (struct wmi_pstream_timeout_event *) datap;
spin_lock_bh(&wmi->lock);
wmi->stream_exist_for_ac[ev->traffic_class] = 0;
wmi->fat_pipe_exist &= ~(1 << ev->traffic_class);
spin_unlock_bh(&wmi->lock);
ath6kl_indicate_tx_activity(wmi->parent_dev, ev->traffic_class, false);
return 0;
}

void jpc_qmfb_split_colgrp(jpc_fix_t *a, int numrows, int stride,
int parity)
{
int bufsize = JPC_CEILDIVPOW2(numrows, 1);
jpc_fix_t splitbuf[QMFB_SPLITBUFSIZE * JPC_QMFB_COLGRPSIZE];
jpc_fix_t *buf = splitbuf;
jpc_fix_t *srcptr;
jpc_fix_t *dstptr;
register jpc_fix_t *srcptr2;
register jpc_fix_t *dstptr2;
register int n;
register int i;
int m;
int hstartcol;
if (bufsize > QMFB_SPLITBUFSIZE) {
if (!(buf = jas_alloc2(bufsize, sizeof(jpc_fix_t)))) {
abort();
}
}
if (numrows >= 2) {
hstartcol = (numrows + 1 - parity) >> 1;
m = numrows - hstartcol;
n = m;
dstptr = buf;
srcptr = &a[(1 - parity) * stride];
while (n-- > 0) {
dstptr2 = dstptr;
srcptr2 = srcptr;
for (i = 0; i < JPC_QMFB_COLGRPSIZE; ++i) {
*dstptr2 = *srcptr2;
++dstptr2;
++srcptr2;
}
dstptr += JPC_QMFB_COLGRPSIZE;
srcptr += stride << 1;
}
dstptr = &a[(1 - parity) * stride];
srcptr = &a[(2 - parity) * stride];
n = numrows - m - (!parity);
while (n-- > 0) {
dstptr2 = dstptr;
srcptr2 = srcptr;
for (i = 0; i < JPC_QMFB_COLGRPSIZE; ++i) {
*dstptr2 = *srcptr2;
++dstptr2;
++srcptr2;
}
dstptr += stride;
srcptr += stride << 1;
}
dstptr = &a[hstartcol * stride];
srcptr = buf;
n = m;
while (n-- > 0) {
dstptr2 = dstptr;
srcptr2 = srcptr;
for (i = 0; i < JPC_QMFB_COLGRPSIZE; ++i) {
*dstptr2 = *srcptr2;
++dstptr2;
++srcptr2;
}
dstptr += stride;
srcptr += JPC_QMFB_COLGRPSIZE;
}
}
if (buf != splitbuf) {
jas_free(buf);
}
}

void
formUpdateBuffer(Anchor *a, Buffer *buf, FormItemList *form)
{
Buffer save;
char *p;
int spos, epos, rows, c_rows, pos, col = 0;
Line *l;
copyBuffer(&save, buf);
gotoLine(buf, a->start.line);
switch (form->type) {
case FORM_TEXTAREA:
case FORM_INPUT_TEXT:
case FORM_INPUT_FILE:
case FORM_INPUT_PASSWORD:
case FORM_INPUT_CHECKBOX:
case FORM_INPUT_RADIO:
#ifdef MENU_SELECT
case FORM_SELECT:
#endif
spos = a->start.pos;
epos = a->end.pos;
break;
default:
spos = a->start.pos + 1;
epos = a->end.pos - 1;
}
switch (form->type) {
case FORM_INPUT_CHECKBOX:
case FORM_INPUT_RADIO:
if (form->checked)
buf->currentLine->lineBuf[spos] = '*';
else
buf->currentLine->lineBuf[spos] = ' ';
break;
case FORM_INPUT_TEXT:
case FORM_INPUT_FILE:
case FORM_INPUT_PASSWORD:
case FORM_TEXTAREA:
#ifdef MENU_SELECT
case FORM_SELECT:
if (form->type == FORM_SELECT) {
p = form->label->ptr;
updateSelectOption(form, form->select_option);
}
else
#endif
p = form->value->ptr;
l = buf->currentLine;
if (form->type == FORM_TEXTAREA) {
int n = a->y - buf->currentLine->linenumber;
if (n > 0)
for (; l && n; l = l->prev, n--) ;
else if (n < 0)
for (; l && n; l = l->prev, n++) ;
if (!l)
break;
}
rows = form->rows ? form->rows : 1;
col = COLPOS(l, a->start.pos);
for (c_rows = 0; c_rows < rows; c_rows++, l = l->next) {
if (rows > 1) {
pos = columnPos(l, col);
a = retrieveAnchor(buf->formitem, l->linenumber, pos);
if (a == NULL)
break;
spos = a->start.pos;
epos = a->end.pos;
}
if (a->start.line != a->end.line || spos > epos)
epos = spos;
pos = form_update_line(l, &p, spos, epos, COLPOS(l, epos) - col,
rows > 1,
form->type == FORM_INPUT_PASSWORD);
if (pos != epos) {
shiftAnchorPosition(buf->href, buf->hmarklist,
a->start.line, spos, pos - epos);
shiftAnchorPosition(buf->name, buf->hmarklist,
a->start.line, spos, pos - epos);
shiftAnchorPosition(buf->img, buf->hmarklist,
a->start.line, spos, pos - epos);
shiftAnchorPosition(buf->formitem, buf->hmarklist,
a->start.line, spos, pos - epos);
}
}
break;
}
copyBuffer(buf, &save);
arrangeLine(buf);
}

static int dalvik_op(RAnal *anal, RAnalOp *op, ut64 addr, const ut8 *data, int len) {
int sz = dalvik_opcodes[data[0]].len;
if (!op) {
return sz;
}
memset (op, '\0', sizeof (RAnalOp));
op->type = R_ANAL_OP_TYPE_UNK;
op->ptr = UT64_MAX;
op->val = UT64_MAX;
op->jump = UT64_MAX;
op->fail = UT64_MAX;
op->refptr = 0;
op->size = sz;
op->nopcode = 1; op->id = data[0];
switch (data[0]) {
case 0xca: op->family = R_ANAL_OP_FAMILY_FPU;
case 0x1b: case 0x14: case 0x15: case 0x16: case 0x17: case 0x42: case 0x12: op->type = R_ANAL_OP_TYPE_MOV;
{
ut32 vB = (data[1] & 0x0f);
ut32 vA = (data[1] & 0xf0) >> 4;
op->ptr = -vA; op->val = vA;
esilprintf (op, "0x%"PFMT64x",v%d,=", vA, vB);
}
break;
case 0x01: case 0x07: case 0x04: op->type = R_ANAL_OP_TYPE_MOV;
{
ut32 vB = (data[1] & 0x0f);
ut32 vA = (data[1] & 0xf0) >> 4;
op->stackop = R_ANAL_STACK_SET;
op->ptr = -vA;
esilprintf (op, "v%d,v%d,=", vA, vB);
}
break;
case 0x02: case 0x03: case 0x05: case 0x06: case 0x08: case 0x09: case 0x13: case 0x18: case 0x19: op->type = R_ANAL_OP_TYPE_MOV;
if (len > 2) {
int vA = (int) data[1];
ut32 vB = (data[3] << 8) | data[2];
esilprintf (op, "v%d,v%d,=", vA, vB);
op->val = vB;
}
break;
case 0x0a: case 0x0d: case 0x0c: case 0x0b:  op->type = R_ANAL_OP_TYPE_MOV;
{
ut32 vA = data[1];
esilprintf (op, "sp,v%d,=[8],8,sp,+=,8", vA);
}
break;
case 0x1a: op->type = R_ANAL_OP_TYPE_MOV;
if (len > 2) {
ut32 vA = data[1];
ut32 vB = (data[3]<<8) | data[2];
ut64 offset = R_ANAL_GET_OFFSET (anal, 's', vB);
op->ptr = offset;
esilprintf (op, "0x%"PFMT64x",v%d,=", offset, vA);
}
break;
case 0x1c: op->type = R_ANAL_OP_TYPE_MOV;
break;
case 0x85: case 0x8e: case 0x89: case 0x8a: case 0x87: case 0x8c: case 0x8b: case 0x88: case 0x86: op->family = R_ANAL_OP_FAMILY_FPU;
case 0x81: case 0x82: case 0x83: case 0x84: case 0x8d: case 0x8f: case 0x20: op->type = R_ANAL_OP_TYPE_CAST;
break;
case 0x21: op->type = R_ANAL_OP_TYPE_LENGTH;
break;
case 0x44: case 0x45: case 0x46:
case 0x47: case 0x48: case 0x49: case 0x4a: case 0x52: case 0x58: case 0x53: case 0x56: case 0x57: case 0xea: case 0x63: case 0xf4: case 0x66: case 0xfd: case 0x55: case 0x60: case 0x61: case 0x62: case 0x64: case 0x65: case 0xe3: case 0xe4: case 0xe5: case 0xe6: case 0x54: case 0xe7: case 0xe8: case 0xf3: case 0xf8: case 0xf2: op->type = R_ANAL_OP_TYPE_LOAD;
break;
case 0x6b: case 0x6d: case 0xeb: case 0x4b: case 0x4c: case 0x4d: case 0x4e: case 0x4f: case 0x5e: case 0xfc: case 0xf5: case 0x5c: case 0x69: case 0x5f: case 0xe9: case 0xf6: case 0xf7: case 0x67: case 0x59: case 0x5a: case 0x5b: case 0x5d: case 0x50: case 0x51: case 0x68: case 0x6a: case 0x6c: case 0xfe: op->type = R_ANAL_OP_TYPE_STORE;
{
ut32 vA = (data[1] & 0x0f);
ut32 vB = (data[1] & 0xf0) >> 4;
esilprintf (op, "v%d,v%d,=", vA, vB);
}
break;
case 0x9d:
case 0xad: case 0xc8: op->family = R_ANAL_OP_FAMILY_FPU;
case 0xcd:
case 0xd2:
case 0x92:
case 0xb2:
op->type = R_ANAL_OP_TYPE_MUL;
break;
case 0x7c: case 0x7e: op->type = R_ANAL_OP_TYPE_NOT;
break;
case 0xa4: case 0xba: case 0xe2: case 0xa5: case 0x9a: case 0xc5: case 0xc4: case 0xe1: case 0x99: op->type = R_ANAL_OP_TYPE_SHR;
break;
case 0xaa: case 0xcf: case 0xaf: op->family = R_ANAL_OP_FAMILY_FPU;
case 0xb4: case 0xdc: case 0xd4: case 0xbf: case 0x9f: case 0x94: op->type = R_ANAL_OP_TYPE_MOD; break;
case 0xd7:
case 0xd9:
case 0xda:
case 0xde:
case 0xdf:
case 0x96:
case 0xc2: case 0x97: case 0xa2: op->type = R_ANAL_OP_TYPE_XOR;
break;
case 0xc9: op->family = R_ANAL_OP_FAMILY_FPU;
case 0x93: case 0xd3: case 0xdb: case 0xce: case 0x9e: case 0xbe: case 0xae: case 0xa9: case 0xb3: op->type = R_ANAL_OP_TYPE_DIV;
break;
case 0x0e: case 0x0f: case 0x10: case 0x11: case 0xf1: op->type = R_ANAL_OP_TYPE_RET;
op->eob = true;
if (data[0] == 0x0e) {esilprintf (op, "sp,[8],ip,=,8,sp,+=");
} else {
ut32 vA = data[1];
esilprintf (op, "sp,[8],ip,=,8,sp,+=,8,sp,-=,v%d,sp,=[8]", vA);
}
break;
case 0x28: op->jump = addr + ((char)data[1])*2;
op->type = R_ANAL_OP_TYPE_JMP;
op->eob = true;
esilprintf (op, "0x%"PFMT64x",ip,=", op->jump);
break;
case 0x29: if (len > 2) {
op->jump = addr + (short)(data[2]|data[3]<<8)*2;
op->type = R_ANAL_OP_TYPE_JMP;
op->eob = true;
esilprintf (op, "0x%"PFMT64x",ip,=", op->jump);
}
break;
case 0x2a: if (len > 2) {
op->jump = addr + (int)(data[2]|(data[3]<<8)|(data[4]<<16)|(data[5]<<24))*2;
op->type = R_ANAL_OP_TYPE_JMP;
op->eob = true;
esilprintf (op, "0x%"PFMT64x",ip,=", op->jump);
}
break;
case 0x2c:
case 0x2b:
op->type = R_ANAL_OP_TYPE_SWITCH;
break;
case 0x2d: case 0x2e: case 0x3f: case 0x2f: case 0x30: case 0x31: case 0x1f: op->type = R_ANAL_OP_TYPE_CMP;
break;
case 0x32: case 0x33: case 0x34: case 0x35: case 0x36: case 0x37: case 0x38: case 0x39: case 0x3a: case 0x3b: case 0x3c: case 0x3d: op->type = R_ANAL_OP_TYPE_CJMP;
if (len > 2) {
op->jump = addr + (len>3?(short)(data[2]|data[3]<<8)*2 : 0);
op->fail = addr + sz;
op->eob = true;
}
break;
case 0xec: case 0x1d: op->type = R_ANAL_OP_TYPE_UPUSH;
break;
case 0x1e: op->type = R_ANAL_OP_TYPE_POP;
break;
case 0x6f: case 0xfa: case 0x70: case 0x71: case 0x72: case 0x73: case 0x74: case 0x75: case 0x76: case 0x77: case 0x78: case 0xb9: case 0xb7: case 0xb8: case 0xb6: case 0x6e: case 0xf0: case 0xf9: case 0xfb: if (len > 2) {
ut32 vB = len > 3?(data[3] << 8) | data[2] : 0;
op->jump = anal->binb.get_offset (anal->binb.bin, 'm', vB);
op->fail = addr + sz;
op->type = R_ANAL_OP_TYPE_CALL;
esilprintf (op, "8,sp,-=,0x%"PFMT64x",sp,=[8],0x%"PFMT64x",ip,=", addr);
}
break;
case 0x27: case 0xee: case 0xef: case 0xed: op->type = R_ANAL_OP_TYPE_SWI;
break;
#if 0
case 0xbb: case 0xbc: case 0xc5: #endif
case 0x22: case 0x23: case 0x24: case 0x25: case 0x26: op->type = R_ANAL_OP_TYPE_NEW;
if (len > 2) {
int vB = (data[3] << 8) | data[2];
ut64 off = R_ANAL_GET_OFFSET (anal, 't', vB);
op->ptr = off;
}
break;
case 0x00: op->type = R_ANAL_OP_TYPE_NOP;
break;
case 0x90: case 0x9b: case 0xa6: case 0xac: case 0xb0: case 0xbb: case 0xc6: case 0xcb: case 0xd0: case 0xd8: op->type = R_ANAL_OP_TYPE_ADD;
break;
case 0xa7: case 0xcc: op->family = R_ANAL_OP_FAMILY_FPU;
case 0xc7:
case 0xbc:
case 0x91:
case 0xb1: case 0xd1: case 0x9c: op->type = R_ANAL_OP_TYPE_SUB;
break;
case 0x7b: case 0x7d: case 0x7f: case 0x80: op->type = R_ANAL_OP_TYPE_NOT;
break;
case 0xa0: case 0xc0: case 0xdd: case 0xd5: case 0x95:
case 0xb5: op->type = R_ANAL_OP_TYPE_AND;
break;
case 0xd6: case 0xc1: case 0xa1: op->type = R_ANAL_OP_TYPE_OR;
break;
case 0xe0: case 0xc3: case 0xa3: case 0x98: op->type = R_ANAL_OP_TYPE_SHL;
break;
}
return sz;
}

static int map_freeze(const union bpf_attr *attr)
{
int err = 0, ufd = attr->map_fd;
struct bpf_map *map;
struct fd f;
if (CHECK_ATTR(BPF_MAP_FREEZE))
return -EINVAL;
f = fdget(ufd);
map = __bpf_map_get(f);
if (IS_ERR(map))
return PTR_ERR(map);
if (map->map_type == BPF_MAP_TYPE_STRUCT_OPS ||
map_value_has_timer(map)) {
fdput(f);
return -ENOTSUPP;
}
mutex_lock(&map->freeze_mutex);
if (map->writecnt) {
err = -EBUSY;
goto err_put;
}
if (READ_ONCE(map->frozen)) {
err = -EBUSY;
goto err_put;
}
if (!bpf_capable()) {
err = -EPERM;
goto err_put;
}
WRITE_ONCE(map->frozen, true);
err_put:
mutex_unlock(&map->freeze_mutex);
fdput(f);
return err;
}

