int wolfSSH_SFTP_RecvRead(WOLFSSH* ssh, int reqId, byte* data, word32 maxSz)
#ifndef USE_WINDOWS_API
{
WFD    fd;
word32 sz;
int    ret;
word32 idx  = 0;
word32 ofst[2] = {0, 0};
byte*  out;
word32 outSz;
char* res  = NULL;
char err[] = "Read File Error";
char eof[] = "Read EOF";
byte type = WOLFSSH_FTP_FAILURE;
if (ssh == NULL) {
return WS_BAD_ARGUMENT;
}
WLOG(WS_LOG_SFTP, "Receiving WOLFSSH_FTP_READ");
ato32(data + idx, &sz); idx += UINT32_SZ;
if (sz + idx > maxSz || sz > WOLFSSH_MAX_HANDLE) {
return WS_BUFFER_E;
}
WMEMSET((byte*)&fd, 0, sizeof(WFD));
WMEMCPY((byte*)&fd, data + idx, sz); idx += sz;
ato32(data + idx, &ofst[1]); idx += UINT32_SZ;
ato32(data + idx, &ofst[0]); idx += UINT32_SZ;
ato32(data + idx, &sz);
out = (byte*)WMALLOC(sz + WOLFSSH_SFTP_HEADER + UINT32_SZ,
ssh->ctx->heap, DYNTYPE_BUFFER);
if (out == NULL) {
return WS_MEMORY_E;
}
ret = WPREAD(fd, out + UINT32_SZ + WOLFSSH_SFTP_HEADER, sz, ofst);
if (ret < 0 || (word32)ret > sz) {
WLOG(WS_LOG_SFTP, "Error reading from file");
res  = err;
type = WOLFSSH_FTP_FAILURE;
ret  = WS_BAD_FILE_E;
}
else {
outSz = (word32)ret + WOLFSSH_SFTP_HEADER + UINT32_SZ;
}
if (ret == 0) {
WLOG(WS_LOG_SFTP, "Error reading from file, EOF");
res = eof;
type = WOLFSSH_FTP_EOF;
ret = WS_SUCCESS; 
}
if (res != NULL) {
if (wolfSSH_SFTP_CreateStatus(ssh, type, reqId, res, "English", NULL,
&outSz) != WS_SIZE_ONLY) {
WFREE(out, ssh->ctx->heap, DYNTYPE_BUFFER);
return WS_FATAL_ERROR;
}
if (outSz > sz) {
WFREE(out, ssh->ctx->heap, DYNTYPE_BUFFER);
out = (byte*)WMALLOC(outSz, ssh->ctx->heap, DYNTYPE_BUFFER);
if (out == NULL) {
return WS_MEMORY_E;
}
}
if (wolfSSH_SFTP_CreateStatus(ssh, type, reqId, res, "English", out,
&outSz) != WS_SUCCESS) {
WFREE(out, ssh->ctx->heap, DYNTYPE_BUFFER);
return WS_FATAL_ERROR;
}
}
else {
SFTP_CreatePacket(ssh, WOLFSSH_FTP_DATA, out, outSz, NULL, 0);
}
wolfSSH_SFTP_RecvSetSend(ssh, out, outSz);
return ret;
}

static void
input(void)
{
uint16_t frag_size = 0;
uint8_t frag_offset = 0;
uint8_t *buffer;
#if SICSLOWPAN_CONF_FRAG
uint8_t is_fragment = 0;
int8_t frag_context = 0;
uint16_t frag_tag = 0;
uint8_t first_fragment = 0, last_fragment = 0;
#endif 
link_stats_input_callback(packetbuf_addr(PACKETBUF_ADDR_SENDER));
uncomp_hdr_len = 0;
packetbuf_hdr_len = 0;
packetbuf_ptr = packetbuf_dataptr();
if(packetbuf_datalen() == 0) {
LOG_WARN("input: empty packet\n");
return;
}
uipbuf_clear();
buffer = (uint8_t *)UIP_IP_BUF;
last_rssi = (signed short)packetbuf_attr(PACKETBUF_ATTR_RSSI);
#if SICSLOWPAN_CONF_FRAG
switch((GET16(PACKETBUF_FRAG_PTR, PACKETBUF_FRAG_DISPATCH_SIZE) >> 8) & SICSLOWPAN_DISPATCH_FRAG_MASK) {
case SICSLOWPAN_DISPATCH_FRAG1:
frag_offset = 0;
frag_size = GET16(PACKETBUF_FRAG_PTR, PACKETBUF_FRAG_DISPATCH_SIZE) & 0x07ff;
frag_tag = GET16(PACKETBUF_FRAG_PTR, PACKETBUF_FRAG_TAG);
packetbuf_hdr_len += SICSLOWPAN_FRAG1_HDR_LEN;
first_fragment = 1;
is_fragment = 1;
LOG_INFO("input: received first element of a fragmented packet (tag %d, len %d)\n",
frag_tag, frag_size);
frag_context = add_fragment(frag_tag, frag_size, frag_offset);
if(frag_context == -1) {
LOG_ERR("input: failed to allocate new reassembly context\n");
return;
}
buffer = frag_info[frag_context].first_frag;
break;
case SICSLOWPAN_DISPATCH_FRAGN:
frag_offset = PACKETBUF_FRAG_PTR[PACKETBUF_FRAG_OFFSET];
frag_tag = GET16(PACKETBUF_FRAG_PTR, PACKETBUF_FRAG_TAG);
frag_size = GET16(PACKETBUF_FRAG_PTR, PACKETBUF_FRAG_DISPATCH_SIZE) & 0x07ff;
packetbuf_hdr_len += SICSLOWPAN_FRAGN_HDR_LEN;
frag_context = add_fragment(frag_tag, frag_size, frag_offset);
if(frag_context == -1) {
LOG_ERR("input: reassembly context not found (tag %d)\n", frag_tag);
return;
}
buffer = NULL;
if(frag_info[frag_context].reassembled_len >= frag_size) {
last_fragment = 1;
}
is_fragment = 1;
break;
default:
break;
}
if(is_fragment && !first_fragment) {
goto copypayload;
}
#endif 
curr_page = 0;
digest_paging_dispatch();
if(curr_page == 1) {
LOG_INFO("input: page 1, 6LoRH\n");
digest_6lorh_hdr();
} else if (curr_page > 1) {
LOG_ERR("input: page %u not supported\n", curr_page);
return;
}
if(SICSLOWPAN_COMPRESSION > SICSLOWPAN_COMPRESSION_IPV6 &&
(PACKETBUF_6LO_PTR[PACKETBUF_6LO_DISPATCH] & SICSLOWPAN_DISPATCH_IPHC_MASK) == SICSLOWPAN_DISPATCH_IPHC) {
LOG_DBG("uncompression: IPHC dispatch\n");
uncompress_hdr_iphc(buffer, frag_size);
} else if(PACKETBUF_6LO_PTR[PACKETBUF_6LO_DISPATCH] == SICSLOWPAN_DISPATCH_IPV6) {
LOG_DBG("uncompression: IPV6 dispatch\n");
packetbuf_hdr_len += SICSLOWPAN_IPV6_HDR_LEN;
memcpy(buffer, packetbuf_ptr + packetbuf_hdr_len, UIP_IPH_LEN);
packetbuf_hdr_len += UIP_IPH_LEN;
uncomp_hdr_len += UIP_IPH_LEN;
} else {
LOG_ERR("uncompression: unknown dispatch: 0x%02x, or IPHC disabled\n",
PACKETBUF_6LO_PTR[PACKETBUF_6LO_DISPATCH] & SICSLOWPAN_DISPATCH_IPHC_MASK);
return;
}
#if SICSLOWPAN_CONF_FRAG
copypayload:
#endif 
if(packetbuf_datalen() < packetbuf_hdr_len) {
LOG_ERR("input: packet dropped due to header > total packet\n");
return;
}
packetbuf_payload_len = packetbuf_datalen() - packetbuf_hdr_len;
#if SICSLOWPAN_CONF_FRAG
if(is_fragment) {
LOG_INFO("input: fragment (tag %d, payload %d, offset %d) -- %u %u\n",
frag_tag, packetbuf_payload_len, frag_offset << 3, packetbuf_datalen(), packetbuf_hdr_len);
}
#endif 
{
int req_size = uncomp_hdr_len + (uint16_t)(frag_offset << 3)
+ packetbuf_payload_len;
if(req_size > sizeof(uip_buf)) {
#if SICSLOWPAN_CONF_FRAG
LOG_ERR(
"input: packet and fragment context %u dropped, minimum required IP_BUF size: %d+%d+%d=%d (current size: %u)\n",
frag_context,
uncomp_hdr_len, (uint16_t)(frag_offset << 3),
packetbuf_payload_len, req_size, (unsigned)sizeof(uip_buf));
clear_fragments(frag_context);
#endif 
return;
}
}
if(buffer != NULL) {
memcpy((uint8_t *)buffer + uncomp_hdr_len, packetbuf_ptr + packetbuf_hdr_len, packetbuf_payload_len);
}
#if SICSLOWPAN_CONF_FRAG
if(frag_size > 0) {
if(first_fragment != 0) {
frag_info[frag_context].reassembled_len = uncomp_hdr_len + packetbuf_payload_len;
frag_info[frag_context].first_frag_len = uncomp_hdr_len + packetbuf_payload_len;
}
if(last_fragment != 0) {
frag_info[frag_context].reassembled_len = frag_size;
if(!copy_frags2uip(frag_context)) {
return;
}
}
}
if(!is_fragment || last_fragment) {
if(is_fragment != 0 && last_fragment != 0) {
uip_len = frag_size;
} else {
uip_len = packetbuf_payload_len + uncomp_hdr_len;
}
#else
uip_len = packetbuf_payload_len + uncomp_hdr_len;
#endif 
LOG_INFO("input: received IPv6 packet with len %d\n",
uip_len);
if(LOG_DBG_ENABLED) {
uint16_t ndx;
LOG_DBG("uncompression: after (%u):", UIP_IP_BUF->len[1]);
for (ndx = 0; ndx < UIP_IP_BUF->len[1] + 40; ndx++) {
uint8_t data = ((uint8_t *) (UIP_IP_BUF))[ndx];
LOG_DBG_("%02x", data);
}
LOG_DBG_("\n");
}
if(callback) {
set_packet_attrs();
callback->input_callback();
}
#if LLSEC802154_USES_AUX_HEADER
uipbuf_set_attr(UIPBUF_ATTR_LLSEC_LEVEL,
packetbuf_attr(PACKETBUF_ATTR_SECURITY_LEVEL));
#if LLSEC802154_USES_EXPLICIT_KEYS
uipbuf_set_attr(UIPBUF_ATTR_LLSEC_KEY_ID,
packetbuf_attr(PACKETBUF_ATTR_KEY_INDEX));
#endif 
#endif 
tcpip_input();
#if SICSLOWPAN_CONF_FRAG
}
#endif 
}

static fz_stream *
build_filter_chain(fz_context *ctx, fz_stream *chain, pdf_document *doc, pdf_obj *fs, pdf_obj *ps, int num, int gen, fz_compression_params *params)
{
pdf_obj *f;
pdf_obj *p;
int i, n;
fz_try(ctx)
{
n = pdf_array_len(ctx, fs);
for (i = 0; i < n; i++)
{
fz_stream *chain2;
f = pdf_array_get(ctx, fs, i);
p = pdf_array_get(ctx, ps, i);
chain2 = chain;
chain = NULL;
chain = build_filter(ctx, chain2, doc, f, p, num, gen, (i == n-1 ? params : NULL));
}
}
fz_catch(ctx)
{
fz_drop_stream(ctx, chain);
fz_rethrow(ctx);
}
return chain;
}

static int
dissect_sec_payload(tvbuff_t *tvb, gint *offset, packet_info *pinfo, proto_tree *part_tree)
{
gint start = *offset;
guint32 tmp_val;
guint32 param_len;
proto_tree *field_tree;
proto_item *ti;
tmp_val = tvb_get_guint8(tvb, *offset);
if (tmp_val == signed_external) {
proto_tree_add_item(part_tree, hf_sgeonw_payload_field_type, tvb, *offset, 1, ENC_BIG_ENDIAN);
*offset += 1;
}
else {
ti = proto_tree_add_item(part_tree, hf_sgeonw_payload_field, tvb, *offset, 0, ENC_NA);
field_tree = proto_item_add_subtree(ti, ett_sgeonw_field);
proto_tree_add_item(field_tree, hf_sgeonw_payload_field_type, tvb, *offset, 1, ENC_BIG_ENDIAN);
*offset += 1;
switch(tmp_val) {
case unsecured:
case signed_pl:
param_len = dissect_sec_var_len(tvb, offset, pinfo, field_tree);
if (param_len) {
tvbuff_t *next_tvb = tvb_new_subset_length(tvb, *offset, param_len);
p_add_proto_data(wmem_file_scope(), pinfo, proto_geonw, 0, next_tvb);
}
*offset += param_len;
break;
case encrypted:
case signed_and_encrypted:
param_len = dissect_sec_var_len(tvb, offset, pinfo, field_tree);
proto_tree_add_item(field_tree, hf_sgeonw_opaque, tvb, *offset, param_len, ENC_NA);
*offset += param_len;
break;
default:
param_len = dissect_sec_var_len(tvb, offset, pinfo, field_tree);
proto_tree_add_item(field_tree, hf_sgeonw_opaque, tvb, *offset, param_len, ENC_NA);
*offset += param_len;
}
proto_item_set_end(ti, tvb, *offset);
}
return (*offset) - start;
}

static void copyin_link(struct new_cpio_header *file_hdr, int in_file_des)
{
char *link_name = NULL;
int res;
link_name = (char *)xmalloc((unsigned int)file_hdr->c_filesize + 1);
link_name[file_hdr->c_filesize] = '\0';
tape_buffered_read(link_name, in_file_des, file_hdr->c_filesize);
tape_skip_padding(in_file_des, file_hdr->c_filesize);
res = symlink(link_name, file_hdr->c_name);
if (res < 0) {
fprintf(stderr, "%s: symlink %s: %s\n",
progname, file_hdr->c_name, strerror(errno));
free(link_name);
return;
}
if ((lchown(file_hdr->c_name, file_hdr->c_uid, file_hdr->c_gid) < 0)
&& errno != EPERM) {
fprintf(stderr, "%s: lchown %s: %s\n",
progname, file_hdr->c_name, strerror(errno));
}
free(link_name);
}

static void
diffuse_fs(unsigned char *data, int width, int height,
int x, int y, int depth, int error)
{
int pos;
pos = y * width + x;
if (x < width - 1 && y < height - 1) {
error_diffuse(data, pos + width * 0 + 1, depth, error, 7, 16);
error_diffuse(data, pos + width * 1 - 1, depth, error, 3, 16);
error_diffuse(data, pos + width * 1 + 0, depth, error, 5, 16);
error_diffuse(data, pos + width * 1 + 1, depth, error, 1, 16);
}
}

int
TIFFReadRGBATileExt(TIFF* tif, uint32_t col, uint32_t row, uint32_t * raster, int stop_on_error )
{
char emsg[1024] = "";
TIFFRGBAImage img;
int ok;
uint32_ttile_xsize, tile_ysize;
uint32_tread_xsize, read_ysize;
uint32_ti_row;
if( !TIFFIsTiled( tif ) )
{
TIFFErrorExt(tif->tif_clientdata, TIFFFileName(tif),
"Can't use TIFFReadRGBATile() with striped file.");
return (0);
}
TIFFGetFieldDefaulted(tif, TIFFTAG_TILEWIDTH, &tile_xsize);
TIFFGetFieldDefaulted(tif, TIFFTAG_TILELENGTH, &tile_ysize);
if( (col % tile_xsize) != 0 || (row % tile_ysize) != 0 )
{
TIFFErrorExt(tif->tif_clientdata, TIFFFileName(tif),
"Row/col passed to TIFFReadRGBATile() must be top"
"left corner of a tile.");
return (0);
}
if (!TIFFRGBAImageOK(tif, emsg) 
|| !TIFFRGBAImageBegin(&img, tif, stop_on_error, emsg)) {
TIFFErrorExt(tif->tif_clientdata, TIFFFileName(tif), "%s", emsg);
return( 0 );
}
if( row + tile_ysize > img.height )
read_ysize = img.height - row;
else
read_ysize = tile_ysize;
if( col + tile_xsize > img.width )
read_xsize = img.width - col;
else
read_xsize = tile_xsize;
img.row_offset = row;
img.col_offset = col;
ok = TIFFRGBAImageGet(&img, raster, read_xsize, read_ysize );
TIFFRGBAImageEnd(&img);
if( read_xsize == tile_xsize && read_ysize == tile_ysize )
return( ok );
for( i_row = 0; i_row < read_ysize; i_row++ ) {
memmove( raster + (tile_ysize - i_row - 1) * tile_xsize,
raster + (read_ysize - i_row - 1) * read_xsize,
read_xsize * sizeof(uint32_t) );
_TIFFmemset( raster + (tile_ysize - i_row - 1) * tile_xsize+read_xsize,
0, sizeof(uint32_t) * (tile_xsize - read_xsize) );
}
for( i_row = read_ysize; i_row < tile_ysize; i_row++ ) {
_TIFFmemset( raster + (tile_ysize - i_row - 1) * tile_xsize,
0, sizeof(uint32_t) * tile_xsize );
}
return (ok);
}

