dev->buffers_number = dev->used_buffers = _max_buffers;
dev->write_position = 0;
MARK();
spin_lock_init(&dev->lock);
INIT_LIST_HEAD(&dev->outbufs_list);
if (list_empty(&dev->outbufs_list)) {
int i;
for (i = 0; i < dev->used_buffers; ++i)
list_add_tail(&dev->buffers[i].list_head,
&dev->outbufs_list);
}
memset(dev->bufpos2index, 0, sizeof(dev->bufpos2index));
atomic_set(&dev->open_count, 0);
dev->ready_for_capture = 0;
dev->ready_for_output = 1;
dev->buffer_size = 0;
dev->image = NULL;
dev->imagesize = 0;
#ifdef HAVE_TIMER_SETUP
timer_setup(&dev->sustain_timer, sustain_timer_clb, 0);
timer_setup(&dev->timeout_timer, timeout_timer_clb, 0);
#else
setup_timer(&dev->sustain_timer, sustain_timer_clb, nr);
setup_timer(&dev->timeout_timer, timeout_timer_clb, nr);
#endif
dev->reread_count = 0;
dev->timeout_jiffies = 0;
dev->timeout_image = NULL;
dev->timeout_happened = 0;
hdl = &dev->ctrl_handler;
err = v4l2_ctrl_handler_init(hdl, 4);
if (err)
goto out_unregister;
v4l2_ctrl_new_custom(hdl, &v4l2loopback_ctrl_keepformat, NULL);
v4l2_ctrl_new_custom(hdl, &v4l2loopback_ctrl_sustainframerate, NULL);
v4l2_ctrl_new_custom(hdl, &v4l2loopback_ctrl_timeout, NULL);
v4l2_ctrl_new_custom(hdl, &v4l2loopback_ctrl_timeoutimageio, NULL);
if (hdl->error) {
err = hdl->error;
goto out_free_handler;
}
dev->v4l2_dev.ctrl_handler = hdl;
err = v4l2_ctrl_handler_setup(hdl);
if (err)
goto out_free_handler;
dev->pix_format.width = 0; 
dev->pix_format.height = 0; 
dev->pix_format.pixelformat = formats[0].fourcc;
dev->pix_format.colorspace =
V4L2_COLORSPACE_SRGB; 
dev->pix_format.field = V4L2_FIELD_NONE;
dev->buffer_size = PAGE_ALIGN(dev->pix_format.sizeimage);
dprintk("buffer_size = %ld (=%d)\n", dev->buffer_size,
dev->pix_format.sizeimage);
if (dev->buffer_size && ((err = allocate_buffers(dev)) < 0))
goto out_free_handler;
init_waitqueue_head(&dev->read_event);
if (video_register_device(dev->vdev, VFL_TYPE_VIDEO, nr) < 0) {
printk(KERN_ERR
"v4l2loopback: failed video_register_device()\n");
err = -EFAULT;
goto out_free_device;
}
v4l2loopback_create_sysfs(dev->vdev);
MARK();
if (ret_nr)
*ret_nr = dev->vdev->num;
return 0;
out_free_device:
video_device_release(dev->vdev);
out_free_handler:
v4l2_ctrl_handler_free(&dev->ctrl_handler);
out_unregister:
video_set_drvdata(dev->vdev, NULL);
if (vdev_priv != NULL)
kfree(vdev_priv);
v4l2_device_unregister(&dev->v4l2_dev);
out_free_idr:
idr_remove(&v4l2loopback_index_idr, nr);
out_free_dev:
kfree(dev);
return err;
}

static int v4l2_loopback_add(struct v4l2_loopback_config *conf, int *ret_nr)
{
struct v4l2_loopback_device *dev;
struct v4l2_ctrl_handler *hdl;
struct v4l2loopback_private *vdev_priv = NULL;
int err = -ENOMEM;
int _max_width = DEFAULT_FROM_CONF(
max_width, < V4L2LOOPBACK_SIZE_MIN_WIDTH, max_width);
int _max_height = DEFAULT_FROM_CONF(
max_height, < V4L2LOOPBACK_SIZE_MIN_HEIGHT, max_height);
bool _announce_all_caps = (conf && conf->announce_all_caps >= 0) ?
(conf->announce_all_caps) :
V4L2LOOPBACK_DEFAULT_EXCLUSIVECAPS;
int _max_buffers = DEFAULT_FROM_CONF(max_buffers, <= 0, max_buffers);
int _max_openers = DEFAULT_FROM_CONF(max_openers, <= 0, max_openers);
int nr = -1;
_announce_all_caps = (!!_announce_all_caps);
if (conf) {
if (conf->capture_nr >= 0 &&
conf->output_nr == conf->capture_nr) {
nr = conf->capture_nr;
} else if (conf->capture_nr < 0 && conf->output_nr < 0) {
nr = -1;
} else if (conf->capture_nr < 0) {
nr = conf->output_nr;
} else if (conf->output_nr < 0) {
nr = conf->capture_nr;
} else {
printk(KERN_ERR
"split OUTPUT and CAPTURE devices not yet supported.");
printk(KERN_INFO
"both devices must have the same number (%d != %d).",
conf->output_nr, conf->capture_nr);
return -EINVAL;
}
}
if (idr_find(&v4l2loopback_index_idr, nr))
return -EEXIST;
dprintk("creating v4l2loopback-device #%d\n", nr);
dev = kzalloc(sizeof(*dev), GFP_KERNEL);
if (!dev)
return -ENOMEM;
if (nr >= 0) {
err = idr_alloc(&v4l2loopback_index_idr, dev, nr, nr + 1,
GFP_KERNEL);
if (err == -ENOSPC)
err = -EEXIST;
} else {
err = idr_alloc(&v4l2loopback_index_idr, dev, 0, 0, GFP_KERNEL);
}
if (err < 0)
goto out_free_dev;
nr = err;
err = -ENOMEM;
if (conf && conf->card_label && *(conf->card_label)) {
snprintf(dev->card_label, sizeof(dev->card_label), "%s",
conf->card_label);
} else {
snprintf(dev->card_label, sizeof(dev->card_label),
"Dummy video device (0x%04X)", nr);
}
snprintf(dev->v4l2_dev.name, sizeof(dev->v4l2_dev.name),
"v4l2loopback-%03d", nr);
err = v4l2_device_register(NULL, &dev->v4l2_dev);
if (err)
goto out_free_idr;
MARK();
dev->vdev = video_device_alloc();
if (dev->vdev == NULL) {
err = -ENOMEM;
goto out_unregister;
}
vdev_priv = kzalloc(sizeof(struct v4l2loopback_private), GFP_KERNEL);
if (vdev_priv == NULL) {
err = -ENOMEM;
goto out_unregister;
}
video_set_drvdata(dev->vdev, vdev_priv);
if (video_get_drvdata(dev->vdev) == NULL) {
err = -ENOMEM;
goto out_unregister;
}
MARK();
snprintf(dev->vdev->name, sizeof(dev->vdev->name), dev->card_label);
vdev_priv->device_nr = nr;
init_vdev(dev->vdev, nr);
dev->vdev->v4l2_dev = &dev->v4l2_dev;
init_capture_param(&dev->capture_param);
err = set_timeperframe(dev, &dev->capture_param.timeperframe);
if (err)
goto out_unregister;
dev->keep_format = 0;
dev->sustain_framerate = 0;
dev->announce_all_caps = _announce_all_caps;
dev->max_width = _max_width;
dev->max_height = _max_height;
dev->max_openers = _max_openers;
dev->buffers_number = dev->used_buffers = _max_buffers;
dev->write_position = 0;
MARK();
spin_lock_init(&dev->lock);
INIT_LIST_HEAD(&dev->outbufs_list);
if (list_empty(&dev->outbufs_list)) {
int i;
for (i = 0; i < dev->used_buffers; ++i)
list_add_tail(&dev->buffers[i].list_head,
&dev->outbufs_list);
}
memset(dev->bufpos2index, 0, sizeof(dev->bufpos2index));
atomic_set(&dev->open_count, 0);
dev->ready_for_capture = 0;
dev->ready_for_output = 1;
dev->buffer_size = 0;
dev->image = NULL;
dev->imagesize = 0;
#ifdef HAVE_TIMER_SETUP
timer_setup(&dev->sustain_timer, sustain_timer_clb, 0);
timer_setup(&dev->timeout_timer, timeout_timer_clb, 0);
#else
setup_timer(&dev->sustain_timer, sustain_timer_clb, nr);
setup_timer(&dev->timeout_timer, timeout_timer_clb, nr);
#endif
dev->reread_count = 0;
dev->timeout_jiffies = 0;
dev->timeout_image = NULL;
dev->timeout_happened = 0;
hdl = &dev->ctrl_handler;
err = v4l2_ctrl_handler_init(hdl, 4);
if (err)
goto out_unregister;
v4l2_ctrl_new_custom(hdl, &v4l2loopback_ctrl_keepformat, NULL);
v4l2_ctrl_new_custom(hdl, &v4l2loopback_ctrl_sustainframerate, NULL);
v4l2_ctrl_new_custom(hdl, &v4l2loopback_ctrl_timeout, NULL);
v4l2_ctrl_new_custom(hdl, &v4l2loopback_ctrl_timeoutimageio, NULL);
if (hdl->error) {
err = hdl->error;
goto out_free_handler;
}
dev->v4l2_dev.ctrl_handler = hdl;
err = v4l2_ctrl_handler_setup(hdl);
if (err)
goto out_free_handler;
dev->pix_format.width = 0; 
dev->pix_format.height = 0; 
dev->pix_format.pixelformat = formats[0].fourcc;
dev->pix_format.colorspace =
V4L2_COLORSPACE_SRGB; 
dev->pix_format.field = V4L2_FIELD_NONE;
dev->buffer_size = PAGE_ALIGN(dev->pix_format.sizeimage);
dprintk("buffer_size = %ld (=%d)\n", dev->buffer_size,
dev->pix_format.sizeimage);
if (dev->buffer_size && ((err = allocate_buffers(dev)) < 0))
goto out_free_handler;
init_waitqueue_head(&dev->read_event);
if (video_register_device(dev->vdev, VFL_TYPE_VIDEO, nr) < 0) {
printk(KERN_ERR
"v4l2loopback: failed video_register_device()\n");
err = -EFAULT;
goto out_free_device;
}
v4l2loopback_create_sysfs(dev->vdev);
MARK();
if (ret_nr)
*ret_nr = dev->vdev->num;
return 0;
out_free_device:
video_device_release(dev->vdev);
out_free_handler:
v4l2_ctrl_handler_free(&dev->ctrl_handler);
out_unregister:
video_set_drvdata(dev->vdev, NULL);
if (vdev_priv != NULL)
kfree(vdev_priv);
v4l2_device_unregister(&dev->v4l2_dev);
out_free_idr:
idr_remove(&v4l2loopback_index_idr, nr);
out_free_dev:
kfree(dev);
return err;
}

void
DeepTiledOutputFile::initialize (const Header &header)
{
_data->header = header;
_data->header.setType(DEEPTILE);
_data->lineOrder = _data->header.lineOrder();
_data->tileDesc = _data->header.tileDescription();
const Box2i &dataWindow = _data->header.dataWindow();
_data->minX = dataWindow.min.x;
_data->maxX = dataWindow.max.x;
_data->minY = dataWindow.min.y;
_data->maxY = dataWindow.max.y;
precalculateTileInfo (_data->tileDesc,
_data->minX, _data->maxX,
_data->minY, _data->maxY,
_data->numXTiles, _data->numYTiles,
_data->numXLevels, _data->numYLevels);
_data->nextTileToWrite = (_data->lineOrder == INCREASING_Y)?
TileCoord (0, 0, 0, 0):
TileCoord (0, _data->numYTiles[0] - 1, 0, 0);
Compressor* compressor = newTileCompressor
(_data->header.compression(),
0,
_data->tileDesc.ySize,
_data->header);
_data->format = defaultFormat (compressor);
if (compressor != 0)
delete compressor;
_data->tileOffsets = TileOffsets (_data->tileDesc.mode,
_data->numXLevels,
_data->numYLevels,
_data->numXTiles,
_data->numYTiles);
_data->header.setChunkCount(getChunkOffsetTableSize(_data->header,true));                                   
_data->maxSampleCountTableSize = _data->tileDesc.ySize *
_data->tileDesc.xSize *
sizeof(int);
for (size_t i = 0; i < _data->tileBuffers.size(); i++)
{
_data->tileBuffers[i] = new TileBuffer ();
_data->tileBuffers[i]->sampleCountTableBuffer.
resizeErase(_data->maxSampleCountTableSize);
char * p = &(_data->tileBuffers[i]->sampleCountTableBuffer[0]);
memset (p, 0, _data->maxSampleCountTableSize);
_data->tileBuffers[i]->sampleCountTableCompressor =
newCompressor (_data->header.compression(),
_data->maxSampleCountTableSize,
_data->header);
}
}

GF_EXPORT
GF_Err gf_filter_get_stats(GF_Filter *f, GF_FilterStats *stats)
{
u32 i;
Bool set_name=GF_FALSE;
if (!stats || !f) return GF_BAD_PARAM;
memset(stats, 0, sizeof(GF_FilterStats));
stats->filter = f;
stats->filter_alias = f->multi_sink_target;
if (f->multi_sink_target) return GF_OK;
stats->percent = f->status_percent>10000 ? -1 : (s32) f->status_percent;
stats->status = f->status_str;
stats->nb_pck_processed = f->nb_pck_processed;
stats->nb_bytes_processed = f->nb_bytes_processed;
stats->time_process = f->time_process;
stats->nb_hw_pck_sent = f->nb_hw_pck_sent;
stats->nb_pck_sent = f->nb_pck_sent;
stats->nb_bytes_sent = f->nb_bytes_sent;
stats->nb_tasks_done = f->nb_tasks_done;
stats->nb_errors = f->nb_errors;
stats->name = f->name;
stats->reg_name = f->freg->name;
stats->filter_id = f->id;
stats->done = f->removed || f->finalized;
if (stats->name && !strcmp(stats->name, stats->reg_name)) {
set_name=GF_TRUE;
}
stats->report_updated = f->report_updated;
f->report_updated = GF_FALSE;
if (!stats->nb_pid_out && stats->nb_pid_in) stats->type = GF_FS_STATS_FILTER_RAWOUT;
else if (!stats->nb_pid_in && stats->nb_pid_out) stats->type = GF_FS_STATS_FILTER_RAWIN;
stats->nb_pid_out = f->num_output_pids;
for (i=0; i<f->num_output_pids; i++) {
GF_FilterPid *pid = gf_list_get(f->output_pids, i);
stats->nb_out_pck += pid->nb_pck_sent;
if (pid->has_seen_eos) stats->in_eos = GF_TRUE;
if (pid->last_ts_sent.num * stats->last_ts_sent.den >= stats->last_ts_sent.num * pid->last_ts_sent.den)
stats->last_ts_sent = pid->last_ts_sent;
if (f->num_output_pids!=1) continue;
if (!stats->codecid)
stats->codecid = pid->codecid;
if (!stats->stream_type)
stats->stream_type = pid->stream_type;
if (set_name && strncmp(pid->name, "PID", 3)) {
stats->name = pid->name;
set_name = GF_FALSE;
}
}
gf_mx_p(f->tasks_mx);
stats->nb_pid_in = f->num_input_pids;
for (i=0; i<f->num_input_pids; i++) {
GF_FilterPidInst *pidi = gf_list_get(f->input_pids, i);
stats->nb_in_pck += pidi->nb_processed;
if (pidi->is_end_of_stream) stats->in_eos = GF_TRUE;
if (pidi->is_decoder_input) stats->type = GF_FS_STATS_FILTER_DECODE;
else if (pidi->is_encoder_input) stats->type = GF_FS_STATS_FILTER_ENCODE;
if (pidi->pid && (pidi->pid->stream_type==GF_STREAM_FILE))
stats->type = GF_FS_STATS_FILTER_DEMUX;
if (pidi->last_ts_drop.num * stats->last_ts_drop.den >= stats->last_ts_drop.num * pidi->last_ts_drop.den)
stats->last_ts_drop = pidi->last_ts_drop;
if ((f->num_input_pids!=1) && f->num_output_pids)
continue;
if (!stats->codecid)
stats->codecid = pidi->pid->codecid;
if (!stats->stream_type)
stats->stream_type = pidi->pid->stream_type;
if (set_name) {
stats->name = pidi->pid->name;
set_name = GF_FALSE;
}
}
gf_mx_v(f->tasks_mx);
if (!stats->type && stats->codecid) {
if (!stats->nb_pid_out) {
stats->type = GF_FS_STATS_FILTER_MEDIA_SINK;
} else if (!stats->nb_pid_in) {
stats->type = GF_FS_STATS_FILTER_MEDIA_SOURCE;
}
}
return GF_OK;
}

static void
map_grant_ref(
struct gnttab_map_grant_ref *op)
{
struct domain *ld, *rd, *owner = NULL;
struct grant_table *lgt, *rgt;
grant_ref_t ref;
grant_handle_t handle;
mfn_t mfn;
struct page_info *pg = NULL;
int            rc = GNTST_okay;
unsigned int   cache_flags, clear_flags = 0, refcnt = 0, typecnt = 0;
bool           host_map_created = false;
struct active_grant_entry *act = NULL;
struct grant_mapping *mt;
grant_entry_header_t *shah;
uint16_t *status;
bool_t need_iommu;
ld = current->domain;
if ( unlikely((op->flags & (GNTMAP_device_map|GNTMAP_host_map)) == 0) )
{
gdprintk(XENLOG_INFO, "Bad flags in grant map op: %x\n", op->flags);
op->status = GNTST_bad_gntref;
return;
}
if ( unlikely(paging_mode_external(ld) &&
(op->flags & (GNTMAP_device_map|GNTMAP_application_map|
GNTMAP_contains_pte))) )
{
gdprintk(XENLOG_INFO, "No device mapping in HVM domain\n");
op->status = GNTST_general_error;
return;
}
if ( unlikely((rd = rcu_lock_domain_by_id(op->dom)) == NULL) )
{
gdprintk(XENLOG_INFO, "Could not find domain %d\n", op->dom);
op->status = GNTST_bad_domain;
return;
}
rc = xsm_grant_mapref(XSM_HOOK, ld, rd, op->flags);
if ( rc )
{
rcu_unlock_domain(rd);
op->status = GNTST_permission_denied;
return;
}
lgt = ld->grant_table;
handle = get_maptrack_handle(lgt);
if ( unlikely(handle == INVALID_MAPTRACK_HANDLE) )
{
rcu_unlock_domain(rd);
gdprintk(XENLOG_INFO, "Failed to obtain maptrack handle\n");
op->status = GNTST_no_device_space;
return;
}
rgt = rd->grant_table;
grant_read_lock(rgt);
ref = op->ref;
if ( unlikely(ref >= nr_grant_entries(rgt)))
PIN_FAIL(unlock_out, GNTST_bad_gntref, "Bad ref %#x for d%d\n",
ref, rgt->domain->domain_id);
shah = shared_entry_header(rgt, ref);
act = active_entry_acquire(rgt, ref);
status = evaluate_nospec(rgt->gt_version == 1) ? &shah->flags
: &status_entry(rgt, ref);
if ( act->pin &&
((act->domid != ld->domain_id) ||
(act->pin & 0x80808080U) != 0 ||
(act->is_sub_page)) )
PIN_FAIL(act_release_out, GNTST_general_error,
"Bad domain (%d != %d), or risk of counter overflow %08x, or subpage %d\n",
act->domid, ld->domain_id, act->pin, act->is_sub_page);
if ( !act->pin ||
(!(op->flags & GNTMAP_readonly) &&
!(act->pin & (GNTPIN_hstw_mask|GNTPIN_devw_mask))) )
{
if ( (rc = _set_status(shah, status, rd, rgt->gt_version, act,
op->flags & GNTMAP_readonly, 1,
ld->domain_id) != GNTST_okay) )
goto act_release_out;
if ( !act->pin )
{
unsigned long gfn = evaluate_nospec(rgt->gt_version == 1) ?
shared_entry_v1(rgt, ref).frame :
shared_entry_v2(rgt, ref).full_page.frame;
rc = get_paged_frame(gfn, &mfn, &pg,
op->flags & GNTMAP_readonly, rd);
if ( rc != GNTST_okay )
goto unlock_out_clear;
act_set_gfn(act, _gfn(gfn));
act->domid = ld->domain_id;
act->mfn = mfn;
act->start = 0;
act->length = PAGE_SIZE;
act->is_sub_page = false;
act->trans_domain = rd;
act->trans_gref = ref;
}
}
if ( op->flags & GNTMAP_device_map )
act->pin += (op->flags & GNTMAP_readonly) ?
GNTPIN_devr_inc : GNTPIN_devw_inc;
if ( op->flags & GNTMAP_host_map )
act->pin += (op->flags & GNTMAP_readonly) ?
GNTPIN_hstr_inc : GNTPIN_hstw_inc;
mfn = act->mfn;
cache_flags = (shah->flags & (GTF_PAT | GTF_PWT | GTF_PCD) );
active_entry_release(act);
grant_read_unlock(rgt);
if ( !pg )
{
pg = mfn_valid(mfn) ? mfn_to_page(mfn) : NULL;
if ( pg )
owner = page_get_owner_and_reference(pg);
}
else
owner = page_get_owner(pg);
if ( owner )
refcnt++;
if ( !pg || (owner == dom_io) )
{
if ( pg )
{
put_page(pg);
refcnt--;
}
if ( paging_mode_external(ld) )
{
gdprintk(XENLOG_WARNING, "HVM guests can't grant map iomem\n");
rc = GNTST_general_error;
goto undo_out;
}
if ( !iomem_access_permitted(rd, mfn_x(mfn), mfn_x(mfn)) )
{
gdprintk(XENLOG_WARNING,
"Iomem mapping not permitted %#"PRI_mfn" (domain %d)\n",
mfn_x(mfn), rd->domain_id);
rc = GNTST_general_error;
goto undo_out;
}
if ( op->flags & GNTMAP_host_map )
{
rc = create_grant_host_mapping(op->host_addr, mfn, op->flags,
cache_flags);
if ( rc != GNTST_okay )
goto undo_out;
host_map_created = true;
}
}
else if ( owner == rd || (dom_cow && owner == dom_cow) )
{
if ( (op->flags & GNTMAP_device_map) && !(op->flags & GNTMAP_readonly) )
{
if ( (owner == dom_cow) ||
!get_page_type(pg, PGT_writable_page) )
goto could_not_pin;
typecnt++;
}
if ( op->flags & GNTMAP_host_map )
{
if ( op->flags & GNTMAP_device_map )
{
if ( !get_page(pg, rd) )
goto could_not_pin;
refcnt++;
}
if ( gnttab_host_mapping_get_page_type(op->flags & GNTMAP_readonly,
ld, rd) )
{
if ( (owner == dom_cow) ||
!get_page_type(pg, PGT_writable_page) )
goto could_not_pin;
typecnt++;
}
rc = create_grant_host_mapping(op->host_addr, mfn, op->flags, 0);
if ( rc != GNTST_okay )
goto undo_out;
host_map_created = true;
}
}
else
{
could_not_pin:
if ( !rd->is_dying )
gdprintk(XENLOG_WARNING, "Could not pin grant frame %#"PRI_mfn"\n",
mfn_x(mfn));
rc = GNTST_general_error;
goto undo_out;
}
need_iommu = gnttab_need_iommu_mapping(ld);
if ( need_iommu )
{
unsigned int kind;
double_gt_lock(lgt, rgt);
kind = mapkind(lgt, rd, mfn);
if ( !(op->flags & GNTMAP_readonly) &&
!(kind & MAPKIND_WRITE) )
kind = IOMMUF_readable | IOMMUF_writable;
else if ( !kind )
kind = IOMMUF_readable;
else
kind = 0;
if ( kind && iommu_legacy_map(ld, _dfn(mfn_x(mfn)), mfn, 0, kind) )
{
double_gt_unlock(lgt, rgt);
rc = GNTST_general_error;
goto undo_out;
}
}
TRACE_1D(TRC_MEM_PAGE_GRANT_MAP, op->dom);
mt = &maptrack_entry(lgt, handle);
mt->domid = op->dom;
mt->ref   = op->ref;
smp_wmb();
write_atomic(&mt->flags, op->flags);
if ( need_iommu )
double_gt_unlock(lgt, rgt);
op->dev_bus_addr = mfn_to_maddr(mfn);
op->handle       = handle;
op->status       = GNTST_okay;
rcu_unlock_domain(rd);
return;
undo_out:
if ( host_map_created )
{
replace_grant_host_mapping(op->host_addr, mfn, 0, op->flags);
