fromv[(i * 2) + 1] = opt.listen_port;
}
}
else {
fromv[0] = "0.0.0.0";
fromv[1] = opt.listen_port;
}
fromv[nfrom * 2] = NULL;
flag = 0;
if (opt.no_lookup)
flag |= VANESSA_SOCKET_NO_LOOKUP;
if (opt.tcp_keepalive)
flag |= VANESSA_SOCKET_TCP_KEEPALIVE;
g = vanessa_socket_server_bindv(fromv, flag);
