else{
flag = 0;
if (opt.tcp_keepalive)
flag |= VANESSA_SOCKET_TCP_KEEPALIVE;
s = vanessa_socket_server_acceptv(g, opt.connection_limit,
(struct sockaddr *) peername,
(struct sockaddr *) sockname, flag);
if(s < 0){
