R_API int r_egg_lang_parsechar(REgg *egg, char c) {
REggEmit *e = egg->remit;
char *ptr, str[64], *tmp_ptr = NULL;
int i, j;
if (c == '\n') {
egg->lang.line++;
egg->lang.elem_n = 0;
}
if (egg->lang.skipline) {
if (c != '\n') {
egg->lang.oc = c;
return 0;
}
egg->lang.skipline = 0;
}
if (egg->lang.mode == DATA) {
return parsedatachar (egg, c);
}
if (egg->lang.mode == INLINE) {
return parseinlinechar (egg, c);
}
if (egg->lang.quoteline) {
if (c != egg->lang.quoteline) {
if (egg->lang.quotelinevar == 1) {
if (c == '`') {
egg->lang.elem[egg->lang.elem_n] = 0;
egg->lang.elem_n = 0;
tmp_ptr = r_egg_mkvar (egg, str, egg->lang.elem, 0);
r_egg_printf (egg, "%s", tmp_ptr);
free (tmp_ptr);
egg->lang.quotelinevar = 0;
} else {
egg->lang.elem[egg->lang.elem_n++] = c;
}
} else {
if (c == '`') {
egg->lang.elem_n = 0;
egg->lang.quotelinevar = 1;
} else {
r_egg_printf (egg, "%c", c);
}
}
egg->lang.oc = c;
return 0;
} else {
r_egg_printf (egg, "\n");
egg->lang.quoteline = 0;
}
}
if (egg->lang.commentmode) {
if (c == '/' && egg->lang.oc == '*') {
egg->lang.commentmode = 0;
}
egg->lang.oc = c;
return 0;
} else if (c == '*' && egg->lang.oc == '/') {
egg->lang.commentmode = 1;
}
if (egg->lang.slurp) {
if (egg->lang.slurp != '"' && c == egg->lang.slurpin) {exit (eprintf (
"%s:%d Nesting of expressions not yet supported\n",
egg->lang.file, egg->lang.line));
}
if (c == egg->lang.slurp && egg->lang.oc != '\\') {egg->lang.elem[egg->lang.elem_n] = '\0';
if (egg->lang.elem_n > 0) {
rcc_element (egg, egg->lang.elem);
} else {
e->frame (egg, 0);
}
egg->lang.elem_n = 0;
egg->lang.slurp = 0;
} else {
egg->lang.elem[egg->lang.elem_n++] = c;
}
egg->lang.elem[egg->lang.elem_n] = '\0';
} else {
switch (c) {
case ';':
rcc_next (egg);
break;
case '"':
egg->lang.slurp = '"';
break;
case '(':
egg->lang.slurpin = '(';
egg->lang.slurp = ')';
break;
case '{':
if (CTX > 0) {
if (egg->lang.nested_callname[CTX] && strstr (egg->lang.nested_callname[CTX], "if") &&
strstr (egg->lang.elem, "else")) {
*egg->lang.elem = '\x00';
egg->lang.elem_n = 0;
R_FREE (egg->lang.ifelse_table[CTX][egg->lang.nestedi[CTX] - 1])
egg->lang.ifelse_table[CTX][egg->lang.nestedi[CTX] - 1] =
r_str_newf ("  __end_%d_%d_%d",
egg->lang.nfunctions, CTX, egg->lang.nestedi[CTX]);
}
r_egg_printf (egg, "  __begin_%d_%d_%d:\n",
egg->lang.nfunctions, CTX, egg->lang.nestedi[CTX]);}
rcc_context (egg, 1);
break;
case '}':
egg->lang.endframe = egg->lang.nested[CTX];
if (egg->lang.endframe) {
r_egg_printf (egg, "%s", egg->lang.endframe);
R_FREE (egg->lang.nested[CTX]);
}
if (CTX > 1) {
if (egg->lang.nested_callname[CTX - 1] && strstr (egg->lang.nested_callname[CTX - 1], "if")) {
tmp_ptr = r_str_newf ("__ifelse_%d_%d", CTX - 1, egg->lang.nestedi[CTX - 1] - 1);
e->jmp (egg, tmp_ptr, 0);
R_FREE (tmp_ptr);egg->lang.ifelse_table[CTX - 1][egg->lang.nestedi[CTX - 1] - 1] =
r_str_newf ("__end_%d_%d_%d",
egg->lang.nfunctions, CTX - 1, egg->lang.nestedi[CTX - 1] - 1);
}
r_egg_printf (egg, "  __end_%d_%d_%d:\n",
egg->lang.nfunctions, CTX - 1, egg->lang.nestedi[CTX - 1] - 1);
}
if (CTX > 0) {
egg->lang.nbrackets++;
}
rcc_context (egg, -1);
if (CTX == 0) {
r_egg_printf (egg, "\n");
for (i = 0; i < 32; i++) {
for (j = 0; j < egg->lang.nestedi[i] && j < 32; j++) {
if (egg->lang.ifelse_table[i][j]) {
r_egg_printf (egg, "  __ifelse_%d_%d:\n", i, j);
e->jmp (egg, egg->lang.ifelse_table[i][j], 0);
R_FREE (egg->lang.ifelse_table[i][j]);
}
}
}
egg->lang.nbrackets = 0;
egg->lang.nfunctions++;
}
break;
case ':':
if (egg->lang.oc == '\n' || egg->lang.oc == '}') {
egg->lang.quoteline = '\n';
} else {
egg->lang.elem[egg->lang.elem_n++] = c;
}
break;
case '#':
if (egg->lang.oc == '\n') {
egg->lang.skipline = 1;
}
break;
case '/':
if (egg->lang.oc == '/') {
egg->lang.skipline = 1;
} else {
egg->lang.elem[egg->lang.elem_n++] = c;
}
break;
default:
egg->lang.elem[egg->lang.elem_n++] = c;
}
if (egg->lang.slurp) {
if (egg->lang.elem_n) {
ptr = egg->lang.elem;
egg->lang.elem[egg->lang.elem_n] = '\0';
while (is_space (*ptr)) {
ptr++;
}
rcc_fun (egg, ptr);
}
egg->lang.elem_n = 0;
}
}
if (c != '\t' && c != ' ') {
egg->lang.oc = c;
}
return 0;
}

std::shared_ptr<node::Environment> NodeBindings::CreateEnvironment(
v8::Handle<v8::Context> context,
node::MultiIsolatePlatform* platform,
std::vector<std::string> args,
std::vector<std::string> exec_args,
absl::optional<base::RepeatingCallback<void()>> on_app_code_ready) {
std::string process_type;
switch (browser_env_) {
case BrowserEnvironment::kBrowser:
process_type = "browser";
break;
case BrowserEnvironment::kRenderer:
process_type = "renderer";
break;
case BrowserEnvironment::kWorker:
process_type = "worker";
break;
case BrowserEnvironment::kUtility:
process_type = "utility";
break;
}
v8::Isolate* isolate = context->GetIsolate();
gin_helper::Dictionary global(isolate, context->Global());
if (browser_env_ == BrowserEnvironment::kBrowser) {
const std::vector<std::string> search_paths = {"app.asar", "app",
"default_app.asar"};
const std::vector<std::string> app_asar_search_paths = {"app.asar"};
context->Global()->SetPrivate(
context,
v8::Private::ForApi(
isolate,
gin::ConvertToV8(isolate, "appSearchPaths").As<v8::String>()),
gin::ConvertToV8(isolate,
electron::fuses::IsOnlyLoadAppFromAsarEnabled()
? app_asar_search_paths
: search_paths));
}
base::FilePath resources_path = GetResourcesPath();
std::string init_script = "electron/js2c/" + process_type + "_init";
args.insert(args.begin() + 1, init_script);
auto* isolate_data = node::CreateIsolateData(isolate, uv_loop_, platform);
context->SetAlignedPointerInEmbedderData(kElectronContextEmbedderDataIndex,
static_cast<void*>(isolate_data));
node::Environment* env;
uint64_t flags = node::EnvironmentFlags::kDefaultFlags |
node::EnvironmentFlags::kHideConsoleWindows |
node::EnvironmentFlags::kNoGlobalSearchPaths |
node::EnvironmentFlags::kNoRegisterESMLoader;
if (browser_env_ == BrowserEnvironment::kRenderer ||
browser_env_ == BrowserEnvironment::kWorker) {
flags |= node::EnvironmentFlags::kNoBrowserGlobals |
node::EnvironmentFlags::kNoCreateInspector;
}
if (!electron::fuses::IsNodeCliInspectEnabled()) {
flags |= node::EnvironmentFlags::kNoStartDebugSignalHandler;
}
{
v8::TryCatch try_catch(isolate);
env = node::CreateEnvironment(
static_cast<node::IsolateData*>(isolate_data), context, args, exec_args,
static_cast<node::EnvironmentFlags::Flags>(flags));
if (try_catch.HasCaught()) {
std::string err_msg =
"Failed to initialize node environment in process: " + process_type;
v8::Local<v8::Message> message = try_catch.Message();
std::string msg;
if (!message.IsEmpty() &&
gin::ConvertFromV8(isolate, message->Get(), &msg))
err_msg += " , with error: " + msg;
LOG(ERROR) << err_msg;
}
}
DCHECK(env);
node::IsolateSettings is;
is.fatal_error_callback = V8FatalErrorCallback;
if (browser_env_ != BrowserEnvironment::kUtility) {
is.should_abort_on_uncaught_exception_callback = [](v8::Isolate*) {
return false;
};
}
is.allow_wasm_code_generation_callback = AllowWasmCodeGenerationCallback;
is.flags |= node::IsolateSettingsFlags::
ALLOW_MODIFY_CODE_GENERATION_FROM_STRINGS_CALLBACK;
is.modify_code_generation_from_strings_callback =
ModifyCodeGenerationFromStrings;
if (browser_env_ == BrowserEnvironment::kBrowser ||
browser_env_ == BrowserEnvironment::kUtility) {
is.policy = v8::MicrotasksPolicy::kExplicit;
} else {
is.policy = context->GetIsolate()->GetMicrotasksPolicy();
is.flags &= ~node::IsolateSettingsFlags::MESSAGE_LISTENER_WITH_ERROR_LEVEL;
context->GetIsolate()->AddMessageListenerWithErrorLevel(
ErrorMessageListener, v8::Isolate::kMessageError);
is.flags |=
node::IsolateSettingsFlags::SHOULD_NOT_SET_PROMISE_REJECTION_CALLBACK;
is.flags |=
node::IsolateSettingsFlags::SHOULD_NOT_SET_PREPARE_STACK_TRACE_CALLBACK;
}
node::SetIsolateUpForNode(context->GetIsolate(), is);
context->GetIsolate()->SetHostImportModuleDynamicallyCallback(
HostImportModuleDynamically);
context->GetIsolate()->SetHostInitializeImportMetaObjectCallback(
HostInitializeImportMetaObject);
gin_helper::Dictionary process(context->GetIsolate(), env->process_object());
process.SetReadOnly("type", process_type);
process.Set("resourcesPath", resources_path);
base::FilePath helper_exec_path;
base::PathService::Get(content::CHILD_PROCESS_EXE, &helper_exec_path);
process.Set("helperExecPath", helper_exec_path);
if (browser_env_ == BrowserEnvironment::kBrowser ||
browser_env_ == BrowserEnvironment::kRenderer) {
if (on_app_code_ready) {
process.SetMethod("appCodeLoaded", std::move(*on_app_code_ready));
} else {
process.SetMethod("appCodeLoaded",
base::BindRepeating(&NodeBindings::SetAppCodeLoaded,
base::Unretained(this)));
}
}
auto env_deleter = [isolate, isolate_data,
context = v8::Global<v8::Context>{isolate, context}](
node::Environment* nenv) mutable {
v8::HandleScope handle_scope{isolate};
context.Get(isolate)->SetAlignedPointerInEmbedderData(
kElectronContextEmbedderDataIndex, nullptr);
context.Reset();
node::FreeEnvironment(nenv);
node::FreeIsolateData(isolate_data);
};
return {env, std::move(env_deleter)};
}

