static int
PatternMatch(char *pat, int patdashes, char *string, int stringdashes)
{
char        c,
t;
if (stringdashes < patdashes)
return 0;
for (;;) {
switch (c = *pat++) {
case '*':
if (!(c = *pat++))
return 1;
if (c == XK_minus) {
patdashes--;
for (;;) {
while ((t = *string++) != XK_minus)
if (!t)
return 0;
stringdashes--;
if (PatternMatch(pat, patdashes, string, stringdashes))
return 1;
if (stringdashes == patdashes)
return 0;
}
} else {
for (;;) {
while ((t = *string++) != c) {
if (!t)
return 0;
if (t == XK_minus) {
if (stringdashes-- < patdashes)
return 0;
}
}
if (PatternMatch(pat, patdashes, string, stringdashes))
return 1;
}
}
case '?':
if (*string++ == XK_minus)
stringdashes--;
break;
case '\0':
return (*string == '\0');
case XK_minus:
if (*string++ == XK_minus) {
patdashes--;
stringdashes--;
break;
}
return 0;
default:
if (c == *string++)
break;
return 0;
}
}
}

sp<MediaSource> MPEG4Extractor::getTrack(size_t index) {
status_t err;
if ((err = readMetaData()) != OK) {
return NULL;
}
Track *track = mFirstTrack;
while (index > 0) {
if (track == NULL) {
return NULL;
}
track = track->next;
--index;
}
if (track == NULL) {
return NULL;
}
Trex *trex = NULL;
int32_t trackId;
if (track->meta->findInt32(kKeyTrackID, &trackId)) {
for (size_t i = 0; i < mTrex.size(); i++) {
Trex *t = &mTrex.editItemAt(index);
if (t->track_ID == (uint32_t) trackId) {
trex = t;
break;
}
}
}
ALOGV("getTrack called, pssh: %zu", mPssh.size());
return new MPEG4Source(this,
track->meta, mDataSource, track->timescale, track->sampleTable,
mSidxEntries, trex, mMoofOffset);
}

static void
process_file_name (char *file, language *lang)
{
FILE *inf;
fdesc *fdp;
compressor *compr;
char *compressed_name, *uncompressed_name;
char *ext, *real_name UNINIT, *tmp_name UNINIT;
int retval;
canonicalize_filename (file);
if (streq (file, tagfile) && !streq (tagfile, "-"))
{
error ("skipping inclusion of %s in self.", file);
return;
}
compr = get_compressor_from_suffix (file, &ext);
if (compr)
{
compressed_name = file;
uncompressed_name = savenstr (file, ext - file);
}
else
{
compressed_name = NULL;
uncompressed_name = file;
}
for (fdp = fdhead; fdp != NULL; fdp = fdp->next)
{
assert (fdp->infname != NULL);
if (streq (uncompressed_name, fdp->infname))
goto cleanup;
}
inf = fopen (file, "r" FOPEN_BINARY);
if (inf)
real_name = file;
else
{
int file_errno = errno;
if (compressed_name)
{
inf = fopen (uncompressed_name, "r" FOPEN_BINARY);
if (inf)
real_name = uncompressed_name;
}
else
{
for (compr = compressors; compr->suffix != NULL; compr++)
{
compressed_name = concat (file, ".", compr->suffix);
inf = fopen (compressed_name, "r" FOPEN_BINARY);
if (inf)
{
real_name = compressed_name;
break;
}
if (MSDOS)
{
char *suf = compressed_name + strlen (file);
size_t suflen = strlen (compr->suffix) + 1;
for ( ; suf[1]; suf++, suflen--)
{
memmove (suf, suf + 1, suflen);
inf = fopen (compressed_name, "r" FOPEN_BINARY);
if (inf)
{
real_name = compressed_name;
break;
}
}
if (inf)
break;
}
free (compressed_name);
compressed_name = NULL;
}
}
if (! inf)
{
errno = file_errno;
perror (file);
goto cleanup;
}
}
if (real_name == compressed_name)
{
fclose (inf);
tmp_name = etags_mktmp ();
if (!tmp_name)
inf = NULL;
else
{
#if MSDOS || defined (DOS_NT)
char *cmd1 = concat (compr->command, " \"", real_name);
char *cmd = concat (cmd1, "\" > ", tmp_name);
#else
char *cmd1 = concat (compr->command, " '", real_name);
char *cmd = concat (cmd1, "' > ", tmp_name);
#endif
free (cmd1);
inf = (system (cmd) == -1
? NULL
: fopen (tmp_name, "r" FOPEN_BINARY));
free (cmd);
}
if (!inf)
{
perror (real_name);
goto cleanup;
}
}
process_file (inf, uncompressed_name, lang);
retval = fclose (inf);
if (real_name == compressed_name)
{
remove (tmp_name);
free (tmp_name);
}
if (retval < 0)
pfatal (file);
cleanup:
if (compressed_name != file)
free (compressed_name);
if (uncompressed_name != file)
free (uncompressed_name);
last_node = NULL;
curfdp = NULL;
return;
}

