uint8_t* DTSStreamReader::findFrame(uint8_t* buff, uint8_t* end)
{
while (end - buff >= 16)
{
int64_t* ptr = (int64_t*)buff;
int64_t hdrType = my_ntohll(ptr[0]);
int64_t hdrSize = my_ntohll(ptr[1]) + 16;
if (hdrType == AUPRINFO || hdrType == BITSHVTB || hdrType == BLACKOUT || hdrType == BRANCHPT ||
hdrType == BUILDVER || hdrType == CORESSMD || hdrType == EXTSS_MD || hdrType == FILEINFO ||
hdrType == NAVI_TBL || hdrType == TIMECODE || hdrType == DTSHDHDR)
{
if (buff + hdrSize > end)
return 0;              buff += hdrSize;
}
else if (hdrType == AUPR_HDR)
{
if (buff + hdrSize > end)
return 0;                          m_skippingSamples = (buff[35] << 8) + buff[36];
buff += hdrSize;
}
else if (hdrType == STRMDATA)
{
m_dataSegmentLen = hdrSize;
buff += 16;
break;
}
else
{
break;          }
}
if (m_firstCall)
{
m_firstCall = false;
checkIfOnlyHDDataExists(buff, end);
}
if (!m_isCoreExists)
{
for (uint8_t* p_buf = buff; p_buf < end - 4; p_buf++)
{
if (p_buf[0] == 0x64 && p_buf[1] == 0x58 && p_buf[2] == 0x20 && p_buf[3] == 0x25)
{
return p_buf;
}
}
return 0;
}
for (uint8_t* p_buf = buff; p_buf < end - 4; p_buf++)
{
if (p_buf < end - 6)
{
if (p_buf[0] == 0xff && p_buf[1] == 0x1f && p_buf[2] == 0x00 && p_buf[3] == 0xe8 &&
(p_buf[4] & 0xf0) == 0xf0 && p_buf[5] == 0x07)
{
return p_buf;
}
else if (p_buf[0] == 0x1f && p_buf[1] == 0xff && p_buf[2] == 0xe8 && p_buf[3] == 0x00 && p_buf[4] == 0x07 &&
(p_buf[5] & 0xf0) == 0xf0)
{
return p_buf;
}
}
if (p_buf[0] == 0x7f && p_buf[1] == 0xfe && p_buf[2] == 0x80 && p_buf[3] == 0x01)
{
return p_buf;
}
else if (p_buf[0] == 0xfe && p_buf[1] == 0x7f && p_buf[2] == 0x01 && p_buf[3] == 0x80)
{
return p_buf;
}
}
return 0;
}

void operator()(OpKernelContext* context, const Tensor& x_input,
const Tensor& scale_input, const Tensor& offset_input,
const Tensor& estimated_mean_input,
const Tensor& estimated_variance_input,
const Tensor* side_input, U epsilon, U exponential_avg_factor,
FusedBatchNormActivationMode activation_mode,
Tensor* y_output, Tensor* batch_mean_output,
Tensor* batch_var_output, Tensor* saved_mean_output,
Tensor* saved_var_output, TensorFormat tensor_format,
bool use_reserved_space) {
OP_REQUIRES(context, side_input == nullptr,
errors::Internal(
"The CPU implementation of FusedBatchNorm does not support "
"side input."));
OP_REQUIRES(context,
activation_mode == FusedBatchNormActivationMode::kIdentity,
errors::Internal("The CPU implementation of FusedBatchNorm "
"does not support activations."));
if (use_reserved_space) {
Tensor* dummy_reserve_space = nullptr;
OP_REQUIRES_OK(context,
context->allocate_output(5, {}, &dummy_reserve_space));
dummy_reserve_space->flat<U>()(0) = U();
}
Tensor transformed_x;
Tensor transformed_y;
if (tensor_format == FORMAT_NCHW) {
const int64 in_batch = GetTensorDim(x_input, tensor_format, 'N');
const int64 in_rows = GetTensorDim(x_input, tensor_format, 'H');
const int64 in_cols = GetTensorDim(x_input, tensor_format, 'W');
const int64 in_depths = GetTensorDim(x_input, tensor_format, 'C');
OP_REQUIRES_OK(context, context->allocate_temp(
DataTypeToEnum<T>::value,
ShapeFromFormat(FORMAT_NHWC, in_batch,
in_rows, in_cols, in_depths),
&transformed_x));
OP_REQUIRES_OK(context, context->allocate_temp(
DataTypeToEnum<T>::value,
ShapeFromFormat(FORMAT_NHWC, in_batch,
in_rows, in_cols, in_depths),
&transformed_y));
std::vector<int32> perm = {0, 2, 3, 1};
OP_REQUIRES_OK(
context, ::tensorflow::DoTranspose(context->eigen_device<CPUDevice>(),
x_input, perm, &transformed_x));
} else {
transformed_x = x_input;
transformed_y = *y_output;
}
typename TTypes<T, 4>::Tensor x(transformed_x.tensor<T, 4>());
typename TTypes<U>::ConstVec scale(scale_input.vec<U>());
typename TTypes<U>::ConstVec offset(offset_input.vec<U>());
typename TTypes<U>::ConstVec estimated_mean(estimated_mean_input.vec<U>());
typename TTypes<U>::ConstVec estimated_variance(
estimated_variance_input.vec<U>());
typename TTypes<T, 4>::Tensor y(transformed_y.tensor<T, 4>());
typename TTypes<U>::Vec batch_mean(batch_mean_output->vec<U>());
typename TTypes<U>::Vec batch_variance(batch_var_output->vec<U>());
const CPUDevice& d = context->eigen_device<CPUDevice>();
const int depth = x.dimension(3);
const int size = x.size();
const int rest_size = size / depth;
Eigen::DSizes<Eigen::Index, 2> rest_by_depth(rest_size, depth);
#if !defined(EIGEN_HAS_INDEX_LIST)
Eigen::DSizes<Eigen::Index, 2> one_by_depth(1, depth);
Eigen::array<int, 1> reduce_dims({0});
Eigen::array<int, 2> bcast_spec({rest_size, 1});
#else
Eigen::IndexList<Eigen::type2index<1>, Eigen::Index> one_by_depth;
one_by_depth.set(1, depth);
Eigen::IndexList<Eigen::Index, Eigen::type2index<1>> bcast_spec;
bcast_spec.set(0, rest_size);
#endif
auto x_rest_by_depth = x.reshape(rest_by_depth).template cast<U>();
auto x_centered =
x_rest_by_depth -
estimated_mean.reshape(one_by_depth).broadcast(bcast_spec);
auto scaling_factor = ((estimated_variance + epsilon).rsqrt() * scale)
.eval()
.reshape(one_by_depth)
.broadcast(bcast_spec);
auto x_scaled = x_centered * scaling_factor;
auto x_shifted =
(x_scaled + offset.reshape(one_by_depth).broadcast(bcast_spec))
.template cast<T>();
y.reshape(rest_by_depth).device(d) = x_shifted;
batch_mean.device(d) = estimated_mean;
batch_variance.device(d) = estimated_variance;
if (tensor_format == FORMAT_NCHW) {
const std::vector<int32> perm = {0, 3, 1, 2};
const Status s = ::tensorflow::DoTranspose(
context->eigen_device<CPUDevice>(), transformed_y, perm, y_output);
if (!s.ok()) {
context->SetStatus(errors::InvalidArgument("Transpose failed: ", s));
}
}
}

void Compute(OpKernelContext* context) override {
const Tensor& a = context->input(0);
const Tensor& b = context->input(1);
const float min_a = context->input(2).flat<float>()(0);
const float max_a = context->input(3).flat<float>()(0);
const float min_b = context->input(4).flat<float>()(0);
const float max_b = context->input(5).flat<float>()(0);
OP_REQUIRES(context, (max_a > min_a),
errors::InvalidArgument("max_a must be larger than min_a."));
OP_REQUIRES(context, (max_b > min_b),
errors::InvalidArgument("max_b must be larger than min_b."));
const int32_t offset_a = FloatToQuantizedUnclamped<T1>(0.0f, min_a, max_a);
const int32_t offset_b = FloatToQuantizedUnclamped<T2>(0.0f, min_b, max_b);
const int32_t offset_c = 0;
const int32_t mult_c = 1;
const int32_t shift_c = 0;
OP_REQUIRES(context, TensorShapeUtils::IsMatrix(a.shape()),
errors::InvalidArgument("In[0] is not a matrix"));
OP_REQUIRES(context, TensorShapeUtils::IsMatrix(b.shape()),
errors::InvalidArgument("In[1] is not a matrix"));
Eigen::array<Eigen::IndexPair<Eigen::DenseIndex>, 1> dim_pair;
dim_pair[0].first = transpose_a_ ? 0 : 1;
dim_pair[0].second = transpose_b_ ? 1 : 0;
OP_REQUIRES(context,
a.dim_size(dim_pair[0].first) == b.dim_size(dim_pair[0].second),
errors::InvalidArgument("Matrix size-incompatible: In[0]: ",
a.shape().DebugString(),
", In[1]: ", b.shape().DebugString()));
OP_REQUIRES(context, ((shift_c >= 0) && (shift_c <= 31)),
errors::InvalidArgument("shift_c must be between 0 and 31, "
"inclusive."));
int a_dim_remaining = 1 - dim_pair[0].first;
int b_dim_remaining = 1 - dim_pair[0].second;
TensorShape out_shape(
{a.dim_size(a_dim_remaining), b.dim_size(b_dim_remaining)});
Tensor* c = nullptr;
OP_REQUIRES_OK(context, context->allocate_output(0, out_shape, &c));
CHECK(c);
const T1* a_data = a.flat<T1>().data();
const T2* b_data = b.flat<T2>().data();
Toutput* c_data = c->flat<Toutput>().data();
const bool transpose_c = false;
const size_t m = a.dim_size(a_dim_remaining);
const size_t n = b.dim_size(b_dim_remaining);
const size_t k = a.dim_size(dim_pair[0].first);
const size_t lda = a.dim_size(1);
const size_t ldb = b.dim_size(1);
const size_t ldc = n;
if (meta::IsSupportedAndEnabled() && std::is_same<T1, quint8>() &&
std::is_same<T2, quint8>() && std::is_same<Toutput, qint32>() &&
(offset_c == 0) && (mult_c == 1) && (shift_c == 0) &&
(transpose_c == false) && (k <= 2048)) {
meta::QuantizedGemm(context, transpose_a_, transpose_b_, a_data, b_data,
c_data, m, n, k, -offset_a, -offset_b, lda, ldb, ldc);
} else if (std::is_same<T1, quint8>() && std::is_same<T2, quint8>() &&
std::is_same<Toutput, qint32>() && (offset_c == 0) &&
(mult_c == 1) && (shift_c == 0) && (transpose_c == false)) {
if (transpose_a_) {
if (transpose_b_) {
GemmlowpMultiply<true, true, false>(context, a_data, b_data, c_data,
m, n, k, offset_a, offset_b, lda,
ldb, ldc);
} else {
GemmlowpMultiply<true, false, false>(context, a_data, b_data, c_data,
m, n, k, offset_a, offset_b, lda,
ldb, ldc);
}
} else {
if (transpose_b_) {
GemmlowpMultiply<false, true, false>(context, a_data, b_data, c_data,
m, n, k, offset_a, offset_b, lda,
ldb, ldc);
} else {
GemmlowpMultiply<false, false, false>(context, a_data, b_data, c_data,
m, n, k, offset_a, offset_b,
lda, ldb, ldc);
}
}
} else {
ReferenceGemm<T1, T2, Toutput>(
transpose_a_, transpose_b_, transpose_c, m, n, k, a_data, offset_a,
lda, b_data, offset_b, ldb, c_data, shift_c, offset_c, mult_c, ldc);
}
float min_c_value;
float max_c_value;
QuantizationRangeForMultiplication<T1, T2, Toutput>(
min_a, max_a, min_b, max_b, &min_c_value, &max_c_value);
Tensor* c_min = nullptr;
OP_REQUIRES_OK(context, context->allocate_output(1, {}, &c_min));
c_min->flat<float>()(0) = min_c_value;
Tensor* c_max = nullptr;
OP_REQUIRES_OK(context, context->allocate_output(2, {}, &c_max));
c_max->flat<float>()(0) = max_c_value;
}

Http::FilterDataStatus Context::onResponseBody(int body_buffer_length, bool end_of_stream) {
if (!wasm_->onResponseBody_) {
return Http::FilterDataStatus::Continue;
}
switch (wasm_
->onResponseBody_(this, id_, static_cast<uint32_t>(body_buffer_length),
static_cast<uint32_t>(end_of_stream))
.u64_) {
case 0:
return Http::FilterDataStatus::Continue;
case 1:
return Http::FilterDataStatus::StopIterationAndBuffer;
case 2:
return Http::FilterDataStatus::StopIterationAndWatermark;
default:
return Http::FilterDataStatus::StopIterationNoBuffer;
}
}

