static void CopyRectangleFromRectangle(rfbClient* client, int src_x, int src_y, int w, int h, int dest_x, int dest_y) {
int i,j;
if (client->frameBuffer == NULL) {
return;
}
#define COPY_RECT_FROM_RECT(BPP) \
{ \
uint##BPP##_t* _buffer=((uint##BPP##_t*)client->frameBuffer)+(src_y-dest_y)*client->width+src_x-dest_x; \
if (dest_y < src_y) { \
for(j = dest_y*client->width; j < (dest_y+h)*client->width; j += client->width) { \
if (dest_x < src_x) { \
for(i = dest_x; i < dest_x+w; i++) { \
((uint##BPP##_t*)client->frameBuffer)[j+i]=_buffer[j+i]; \
} \
} else { \
for(i = dest_x+w-1; i >= dest_x; i--) { \
((uint##BPP##_t*)client->frameBuffer)[j+i]=_buffer[j+i]; \
} \
} \
} \
} else { \
for(j = (dest_y+h-1)*client->width; j >= dest_y*client->width; j-=client->width) { \
if (dest_x < src_x) { \
for(i = dest_x; i < dest_x+w; i++) { \
((uint##BPP##_t*)client->frameBuffer)[j+i]=_buffer[j+i]; \
} \
} else { \
for(i = dest_x+w-1; i >= dest_x; i--) { \
((uint##BPP##_t*)client->frameBuffer)[j+i]=_buffer[j+i]; \
} \
} \
} \
} \
}
switch(client->format.bitsPerPixel) {
case  8: COPY_RECT_FROM_RECT(8);  break;
case 16: COPY_RECT_FROM_RECT(16); break;
case 32: COPY_RECT_FROM_RECT(32); break;
default:
rfbClientLog("Unsupported bitsPerPixel: %d\n",client->format.bitsPerPixel);
}
}

static int handle_recv_3(void *object, IP_Port source, const uint8_t *packet, uint16_t length, void *userdata)
{
Onion *onion = (Onion *)object;
if (length > ONION_MAX_PACKET_SIZE) {
return 1;
}
if (length <= 1 + RETURN_3) {
return 1;
}
change_symmetric_key(onion);
uint8_t plain[SIZE_IPPORT + RETURN_2];
int len = decrypt_data_symmetric(onion->secret_symmetric_key, packet + 1, packet + 1 + CRYPTO_NONCE_SIZE,
SIZE_IPPORT + RETURN_2 + CRYPTO_MAC_SIZE, plain);
if ((uint32_t)len != sizeof(plain)) {
return 1;
}
IP_Port send_to;
if (ipport_unpack(&send_to, plain, len, 0) == -1) {
return 1;
}
uint8_t data[ONION_MAX_PACKET_SIZE];
data[0] = NET_PACKET_ONION_RECV_2;
memcpy(data + 1, plain + SIZE_IPPORT, RETURN_2);
memcpy(data + 1 + RETURN_2, packet + 1 + RETURN_3, length - (1 + RETURN_3));
uint16_t data_len = 1 + RETURN_2 + (length - (1 + RETURN_3));
if ((uint32_t)sendpacket(onion->net, send_to, data, data_len) != data_len) {
return 1;
}
return 0;
}

static void free_heap_pages(
struct page_info *pg, unsigned int order, bool need_scrub)
{
unsigned long mask, mfn = page_to_mfn(pg);
unsigned int i, node = phys_to_nid(page_to_maddr(pg)), tainted = 0;
unsigned int zone = page_to_zone(pg);
ASSERT(order <= MAX_ORDER);
ASSERT(node >= 0);
spin_lock(&heap_lock);
for ( i = 0; i < (1 << order); i++ )
{
ASSERT(!page_state_is(&pg[i], offlined));
pg[i].count_info =
((pg[i].count_info & PGC_broken) |
(page_state_is(&pg[i], offlining)
? PGC_state_offlined : PGC_state_free));
if ( page_state_is(&pg[i], offlined) )
tainted = 1;
pg[i].u.free.need_tlbflush = (page_get_owner(&pg[i]) != NULL);
if ( pg[i].u.free.need_tlbflush )
pg[i].tlbflush_timestamp = tlbflush_current_time();
page_set_owner(&pg[i], NULL); 
set_gpfn_from_mfn(mfn + i, INVALID_M2P_ENTRY);
if ( need_scrub )
{
pg[i].count_info |= PGC_need_scrub;
poison_one_page(&pg[i]);
}
}
avail[node][zone] += 1 << order;
total_avail_pages += 1 << order;
if ( need_scrub )
{
node_need_scrub[node] += 1 << order;
pg->u.free.first_dirty = 0;
}
else
pg->u.free.first_dirty = INVALID_DIRTY_IDX;
if ( tmem_enabled() )
midsize_alloc_zone_pages = max(
midsize_alloc_zone_pages, total_avail_pages / MIDSIZE_ALLOC_FRAC);
while ( order < MAX_ORDER )
{
mask = 1UL << order;
if ( (page_to_mfn(pg) & mask) )
{
struct page_info *predecessor = pg - mask;
if ( !mfn_valid(_mfn(page_to_mfn(predecessor))) ||
!page_state_is(predecessor, free) ||
(PFN_ORDER(predecessor) != order) ||
(phys_to_nid(page_to_maddr(predecessor)) != node) )
break;
check_and_stop_scrub(predecessor);
page_list_del(predecessor, &heap(node, zone, order));
if ( predecessor->u.free.first_dirty == INVALID_DIRTY_IDX &&
pg->u.free.first_dirty != INVALID_DIRTY_IDX )
predecessor->u.free.first_dirty = (1U << order) +
pg->u.free.first_dirty;
pg = predecessor;
}
else
{
struct page_info *successor = pg + mask;
if ( !mfn_valid(_mfn(page_to_mfn(successor))) ||
!page_state_is(successor, free) ||
(PFN_ORDER(successor) != order) ||
(phys_to_nid(page_to_maddr(successor)) != node) )
break;
check_and_stop_scrub(successor);
page_list_del(successor, &heap(node, zone, order));
}
order++;
}
page_list_add_scrub(pg, node, zone, order, pg->u.free.first_dirty);
if ( tainted )
reserve_offlined_page(pg);
spin_unlock(&heap_lock);
}

static bool
load_specific_debug_section (enum dwarf_section_display_enum debug,
asection *sec, void *file)
{
struct dwarf_section *section = &debug_displays [debug].section;
bfd *abfd = (bfd *) file;
bfd_byte *contents;
bfd_size_type amt;
size_t alloced;
bool ret;
if (section->start != NULL)
{
if (streq (section->filename, bfd_get_filename (abfd)))
return true;
free (section->start);
}
section->filename = bfd_get_filename (abfd);
section->reloc_info = NULL;
section->num_relocs = 0;
section->address = bfd_section_vma (sec);
section->size = bfd_section_size (sec);
alloced = amt = section->size + 1;
if (alloced != amt || alloced == 0)
{
section->start = NULL;
free_debug_section (debug);
printf (_("\nSection '%s' has an invalid size: %#" PRIx64 ".\n"),
sanitize_string (section->name),
section->size);
return false;
}
section->start = contents = xmalloc (alloced);
section->start[section->size] = 0;
if ((abfd->flags & (EXEC_P | DYNAMIC)) == 0
&& debug_displays [debug].relocate)
{
ret = bfd_simple_get_relocated_section_contents (abfd,
sec,
section->start,
syms) != NULL;
if (ret)
{
long reloc_size = bfd_get_reloc_upper_bound (abfd, sec);
if (reloc_size > 0)
{
long reloc_count;
arelent **relocs;
relocs = (arelent **) xmalloc (reloc_size);
reloc_count = bfd_canonicalize_reloc (abfd, sec, relocs, syms);
if (reloc_count <= 0)
free (relocs);
else
{
section->reloc_info = relocs;
section->num_relocs = reloc_count;
}
}
}
}
else
ret = bfd_get_full_section_contents (abfd, sec, &contents);
if (!ret)
{
free_debug_section (debug);
printf (_("\nCan't get contents for section '%s'.\n"),
sanitize_string (section->name));
return false;
}
return true;
}

int mp_pack(lua_State *L) {
int nargs = lua_gettop(L);
int i;
mp_buf *buf;
if (nargs == 0)
return luaL_argerror(L, 0, "MessagePack pack needs input.");
buf = mp_buf_new(L);
for(i = 1; i <= nargs; i++) {
lua_pushvalue(L, i);
mp_encode_lua_type(L,buf,0);
lua_pushlstring(L,(char*)buf->b,buf->len);
buf->free += buf->len;
buf->len = 0;
}
mp_buf_free(L, buf);
lua_concat(L, nargs);
return 1;
}

static int
archive_read_format_zip_cleanup(struct archive_read *a)
{
struct zip *zip;
struct zip_entry *zip_entry, *next_zip_entry;
zip = (struct zip *)(a->format->data);
#ifdef HAVE_ZLIB_H
if (zip->stream_valid)
inflateEnd(&zip->stream);
#endif
#if HAVA_LZMA_H && HAVE_LIBLZMA
if (zip->zipx_lzma_valid) {
lzma_end(&zip->zipx_lzma_stream);
}
#endif
#ifdef HAVE_BZLIB_H
if (zip->bzstream_valid) {
BZ2_bzDecompressEnd(&zip->bzstream);
}
#endif
free(zip->uncompressed_buffer);
if (zip->ppmd8_valid)
__archive_ppmd8_functions.Ppmd8_Free(&zip->ppmd8);
if (zip->zip_entries) {
zip_entry = zip->zip_entries;
while (zip_entry != NULL) {
next_zip_entry = zip_entry->next;
archive_string_free(&zip_entry->rsrcname);
free(zip_entry);
zip_entry = next_zip_entry;
}
}
free(zip->decrypted_buffer);
if (zip->cctx_valid)
archive_decrypto_aes_ctr_release(&zip->cctx);
if (zip->hctx_valid)
archive_hmac_sha1_cleanup(&zip->hctx);
free(zip->iv);
free(zip->erd);
free(zip->v_data);
archive_string_free(&zip->format_name);
free(zip);
(a->format->data) = NULL;
return (ARCHIVE_OK);
}

GF_Err gp_rtp_builder_do_hevc(GP_RTPPacketizer *builder, u8 *nalu, u32 nalu_size, u8 IsAUEnd, u32 FullAUSize)
{
u32 do_flush, bytesLeft, size;
do_flush = 0;
if (!nalu) do_flush = 1;
else if (builder->sl_header.accessUnitStartFlag) do_flush = 1;
else if (builder->bytesInPacket + nalu_size + 4 >= builder->Path_MTU) do_flush = 2; 
else if (! (builder->flags & GP_RTP_PCK_USE_MULTI) ) do_flush = 2;
if (builder->bytesInPacket && do_flush) {
builder->rtp_header.Marker = (do_flush==1) ? 1 : 0;
if (strlen(builder->hevc_payload_hdr)) {
builder->OnData(builder->cbk_obj, (char *)builder->hevc_payload_hdr, 2, GF_TRUE);
memset(builder->hevc_payload_hdr, 0, 2);
}
builder->OnPacketDone(builder->cbk_obj, &builder->rtp_header);
builder->bytesInPacket = 0;
}
if (!nalu) return GF_OK;
if (!builder->bytesInPacket) {
builder->rtp_header.PayloadType = builder->PayloadType;
builder->rtp_header.TimeStamp = (u32) builder->sl_header.compositionTimeStamp;
builder->rtp_header.SequenceNumber += 1;
builder->OnNewPacket(builder->cbk_obj, &builder->rtp_header);
}
if (builder->bytesInPacket+nalu_size+4 < builder->Path_MTU) {
Bool use_AP = (builder->flags & GP_RTP_PCK_USE_MULTI) ? GF_TRUE : GF_FALSE;
if (IsAUEnd && !builder->bytesInPacket) use_AP = GF_FALSE;
if (use_AP) {
char nal_s[2];
if (!builder->bytesInPacket) {
builder->hevc_payload_hdr[0] = (nalu[0] & 0x81) | (48 << 1);
builder->hevc_payload_hdr[1] = nalu[1];
}
else {
u8 cur_LayerId, cur_TID, new_LayerId, new_TID;
builder->hevc_payload_hdr[0] |= (nalu[0] & 0x80);
cur_LayerId = ((builder->hevc_payload_hdr[0] & 0x01) << 5) + ((builder->hevc_payload_hdr[1] & 0xF8) >> 3);
new_LayerId = ((nalu[0] & 0x01) << 5) + ((nalu[1] & 0xF8) >> 3);
if (cur_LayerId > new_LayerId) {
builder->hevc_payload_hdr[0] = (builder->hevc_payload_hdr[0] & 0xFE) | (nalu[0] & 0x01);
builder->hevc_payload_hdr[1] = (builder->hevc_payload_hdr[1] & 0x07) | (nalu[1] & 0xF8);
}
cur_TID = builder->hevc_payload_hdr[1] & 0x07;
new_TID = nalu[1] & 0x07;
if (cur_TID > new_TID) {
builder->hevc_payload_hdr[1] = (builder->hevc_payload_hdr[1] & 0xF8) | (nalu[1] & 0x07);
}
}
nal_s[0] = nalu_size>>8;
nal_s[1] = nalu_size&0x00ff;
builder->OnData(builder->cbk_obj, (char *)nal_s, 2, GF_FALSE);
builder->bytesInPacket += 2;
}
if (builder->OnDataReference)
builder->OnDataReference(builder->cbk_obj, nalu_size, 0);
else
builder->OnData(builder->cbk_obj, nalu, nalu_size, GF_FALSE);
builder->bytesInPacket += nalu_size;
if (IsAUEnd) {
builder->rtp_header.Marker = 1;
if (strlen(builder->hevc_payload_hdr)) {
builder->OnData(builder->cbk_obj, (char *)builder->hevc_payload_hdr, 2, GF_TRUE);
memset(builder->hevc_payload_hdr, 0, 2);
}
builder->OnPacketDone(builder->cbk_obj, &builder->rtp_header);
builder->bytesInPacket = 0;
}
}
else {
u32 offset;
char payload_hdr[2];
char shdr;
assert(nalu_size + 4 >=builder->Path_MTU);
assert(!builder->bytesInPacket);
bytesLeft = nalu_size - 2;
offset = 2;
while (bytesLeft) {
if (3 + bytesLeft > builder->Path_MTU) {
size = builder->Path_MTU - 3;
} else {
size = bytesLeft;
}
memset(payload_hdr, 0, 2);
payload_hdr[0] = (nalu[0] & 0x81) | (49 << 1);
payload_hdr[1] = nalu[1];
builder->OnData(builder->cbk_obj, (char *)payload_hdr, 2, GF_FALSE);
shdr = 0;
shdr |= (nalu[0] & 0x7E) >> 1;
if (offset==2) shdr |= 0x80;
else if (size == bytesLeft) shdr |= 0x40;
builder->OnData(builder->cbk_obj, &shdr, 1, GF_FALSE);
if (builder->OnDataReference)
builder->OnDataReference(builder->cbk_obj, size, offset);
else
builder->OnData(builder->cbk_obj, nalu+offset, size, GF_FALSE);
offset += size;
bytesLeft -= size;
builder->rtp_header.Marker = (IsAUEnd && !bytesLeft) ? 1 : 0;
builder->OnPacketDone(builder->cbk_obj, &builder->rtp_header);
builder->bytesInPacket = 0;
if (bytesLeft) {
builder->rtp_header.PayloadType = builder->PayloadType;
builder->rtp_header.TimeStamp = (u32) builder->sl_header.compositionTimeStamp;
builder->rtp_header.SequenceNumber += 1;
builder->OnNewPacket(builder->cbk_obj, &builder->rtp_header);
}
}
}
return GF_OK;
}

static TEE_Result tee_svc_cipher_update_helper(unsigned long state,
bool last_block, const void *src, size_t src_len,
void *dst, uint64_t *dst_len)
{
TEE_Result res;
struct tee_cryp_state *cs;
struct tee_ta_session *sess;
size_t dlen = 0;
res = tee_ta_get_current_session(&sess);
if (res != TEE_SUCCESS)
return res;
res = tee_svc_cryp_get_state(sess, tee_svc_uref_to_vaddr(state), &cs);
if (res != TEE_SUCCESS)
return res;
res = tee_mmu_check_access_rights(to_user_ta_ctx(sess->ctx),
TEE_MEMORY_ACCESS_READ |
TEE_MEMORY_ACCESS_ANY_OWNER,
(uaddr_t)src, src_len);
if (res != TEE_SUCCESS)
return res;
if (!dst_len) {
dlen = 0;
} else {
res = get_user_u64_as_size_t(&dlen, dst_len);
if (res != TEE_SUCCESS)
return res;
res = tee_mmu_check_access_rights(to_user_ta_ctx(sess->ctx),
TEE_MEMORY_ACCESS_READ |
TEE_MEMORY_ACCESS_WRITE |
TEE_MEMORY_ACCESS_ANY_OWNER,
(uaddr_t)dst, dlen);
if (res != TEE_SUCCESS)
return res;
}
if (dlen < src_len) {
res = TEE_ERROR_SHORT_BUFFER;
goto out;
}
if (src_len > 0) {
res = tee_do_cipher_update(cs->ctx, cs->algo, cs->mode,
last_block, src, src_len, dst);
}
if (last_block && cs->ctx_finalize != NULL) {
cs->ctx_finalize(cs->ctx, cs->algo);
cs->ctx_finalize = NULL;
}
out:
if ((res == TEE_SUCCESS || res == TEE_ERROR_SHORT_BUFFER) &&
dst_len != NULL) {
TEE_Result res2;
res2 = put_user_u64(dst_len, src_len);
if (res2 != TEE_SUCCESS)
res = res2;
}
return res;
}

