static void
check_POLYLINE_handles (Dwg_Object *obj)
{
Dwg_Entity_POLYLINE_2D *_obj = obj->tio.entity->tio.POLYLINE_2D;
Dwg_Data *dwg = obj->parent;
if (dwg->header.version >= R_2004)
{
BITCODE_BL i = 0;
Dwg_Object_Ref *layer = obj->tio.entity->layer;
Dwg_Object_Ref *seqend = _obj->seqend;
if (layer && !layer->obj)
layer->obj = dwg_ref_object_relative (dwg, layer, obj);
if (!layer || !layer->obj)
{           LOG_WARN ("Wrong POLYLINE.layer %lX",
layer ? layer->handleref.value : 0L);
if (_obj->num_owned > 0 && _obj->vertex)
{
Dwg_Object_Ref *vertex = _obj->vertex[0];
if (vertex && !vertex->obj)
vertex->obj = dwg_ref_object_relative (dwg, vertex, obj);
if (vertex && vertex->obj 
&& vertex->obj->fixedtype == DWG_TYPE_LAYER)
{
Dwg_Object *seq;
obj->tio.entity->layer = layer = vertex;
LOG_WARN (
"POLYLINE.layer is vertex[0] %lX, shift em, NULL seqend",
layer->handleref.value);
for (i = 0; i < _obj->num_owned - 1; i++)
{
_obj->vertex[i] = _obj->vertex[i + 1];
}
_obj->vertex[_obj->num_owned - 1] = seqend;
_obj->seqend = NULL;
seq = dwg_next_object (obj);
if (seq && seq->type == DWG_TYPE_SEQEND)
{
LOG_WARN ("POLYLINE.seqend = POLYLINE+1 %lX",
seq->handle.value);
seqend = _obj->seqend = dwg_find_objectref (dwg, seq);
}
else
{
seq = dwg_next_object (seqend->obj);
if (seq && seq->type == DWG_TYPE_SEQEND)
{
LOG_WARN ("POLYLINE.seqend = VERTEX+1 %lX",
seq->handle.value);
seqend = _obj->seqend
= dwg_find_objectref (dwg, seq);
}
}
}
}
}
else if (layer->obj->fixedtype != DWG_TYPE_LAYER
&& layer->obj->fixedtype != DWG_TYPE_DICTIONARY)
{           LOG_WARN ("Wrong POLYLINE.layer %s", layer->obj->dxfname)
}
if (!seqend || !seqend->handleref.value)
{
LOG_WARN ("Empty POLYLINE.seqend")
}
else if (seqend->obj && seqend->obj->fixedtype != DWG_TYPE_SEQEND)
{           LOG_WARN ("Wrong POLYLINE.seqend %s", seqend->obj->dxfname)
}
if (!_obj->vertex)
return;
for (; i < _obj->num_owned; i++)
{
Dwg_Object_Ref *v = _obj->vertex[i];
if (!v || !v->handleref.value)
{
LOG_WARN ("Empty POLYLINE.vertex[%d]", i);
}
else if (v->obj && v->obj->fixedtype != DWG_TYPE_VERTEX_2D
&& v->obj->fixedtype != DWG_TYPE_VERTEX_3D
&& v->obj->fixedtype != DWG_TYPE_VERTEX_MESH
&& v->obj->fixedtype != DWG_TYPE_VERTEX_PFACE
&& v->obj->fixedtype != DWG_TYPE_VERTEX_PFACE_FACE)
{
LOG_WARN ("Wrong POLYLINE.vertex[%d] %lX %s", i,
v->handleref.value, v->obj->dxfname)
}
}
}
}

int LibRaw::ljpeg_start(struct jhead *jh, int info_only)
{
ushort c, tag, len;
int cnt = 0;
uchar data[0x10000];
const uchar *dp;
memset(jh, 0, sizeof *jh);
jh->restart = INT_MAX;
if ((fgetc(ifp), fgetc(ifp)) != 0xd8)
return 0;
do
{
if (feof(ifp))
return 0;
if (cnt++ > 1024)
return 0;     if (!fread(data, 2, 2, ifp))
return 0;
tag = data[0] << 8 | data[1];
len = (data[2] << 8 | data[3]) - 2;
if (tag <= 0xff00)
return 0;
fread(data, 1, len, ifp);
switch (tag)
{
case 0xffc3:       jh->sraw = ((data[7] >> 4) * (data[7] & 15) - 1) & 3;
case 0xffc1:
case 0xffc0:
jh->algo = tag & 0xff;
jh->bits = data[0];
jh->high = data[1] << 8 | data[2];
jh->wide = data[3] << 8 | data[4];
jh->clrs = data[5] + jh->sraw;
if (len == 9 && !dng_version)
getc(ifp);
break;
case 0xffc4:       if (info_only)
break;
for (dp = data; dp < data + len && !((c = *dp++) & -20);)
jh->free[c] = jh->huff[c] = make_decoder_ref(&dp);
break;
case 0xffda:       jh->psv = data[1 + data[0] * 2];
jh->bits -= data[3 + data[0] * 2] & 15;
break;
case 0xffdb:
FORC(64) jh->quant[c] = data[c * 2 + 1] << 8 | data[c * 2 + 2];
break;
case 0xffdd:
jh->restart = data[0] << 8 | data[1];
}
} while (tag != 0xffda);
if (jh->bits > 16 || jh->clrs > 6 || !jh->bits || !jh->high || !jh->wide ||
!jh->clrs)
return 0;
if (info_only)
return 1;
if (!jh->huff[0])
return 0;
FORC(19) if (!jh->huff[c + 1]) jh->huff[c + 1] = jh->huff[c];
if (jh->sraw)
{
FORC(4) jh->huff[2 + c] = jh->huff[1];
FORC(jh->sraw) jh->huff[1 + c] = jh->huff[0];
}
jh->row = (ushort *)calloc(jh->wide * jh->clrs, 4);
merror(jh->row, "ljpeg_start()");
return zero_after_ff = 1;
}

static port::StatusOr<CudnnRnnSequenceTensorDescriptor> Create(
GpuExecutor* parent, int max_seq_length, int batch_size, int data_size,
const absl::Span<const int>& seq_lengths, bool time_major,
cudnnDataType_t data_type) {
CHECK_GT(max_seq_length, 0);
int dims[] = {batch_size, data_size, 1};
int strides[] = {dims[1] * dims[2], dims[2], 1};
TensorDescriptor tensor_desc = CreateTensorDescriptor();
RETURN_IF_CUDNN_ERROR(cudnnSetTensorNdDescriptor(
tensor_desc.get(), data_type,
sizeof(dims) / sizeof(dims[0]), dims,
strides));
const int* seq_lengths_array = seq_lengths.data();
RNNDataDescriptor data_desc = CreateRNNDataDescriptor();
float padding_fill = 0.0f;
cudnnRNNDataLayout_t layout;
if (time_major) {
layout = CUDNN_RNN_DATA_LAYOUT_SEQ_MAJOR_UNPACKED;
} else {
layout = CUDNN_RNN_DATA_LAYOUT_BATCH_MAJOR_UNPACKED;
}
RETURN_IF_CUDNN_ERROR(cudnnSetRNNDataDescriptor(
data_desc.get(),  data_type,
layout,
max_seq_length,
batch_size, data_size,
seq_lengths_array,
(void*)&padding_fill));
return CudnnRnnSequenceTensorDescriptor(
parent, max_seq_length, batch_size, data_size, data_type,
std::move(data_desc), std::move(tensor_desc));
}

int ReadExecConfig()
{
int i = 0, j = 0, dup_entry = 0;
FILE *fp;
FILE *process_file;
char buffer[OS_MAXSTR + 1];
for (i = 0; i <= exec_size + 1; i++) {
memset(exec_names[i], '\0', OS_FLSIZE + 1);
memset(exec_cmd[i], '\0', OS_FLSIZE + 1);
exec_timeout[i] = 0;
}
exec_size = 0;
fp = fopen(DEFAULTARPATH, "r");
if (!fp) {
merror(FOPEN_ERROR, ARGV0, DEFAULTARPATH, errno, strerror(errno));
return (0);
}
while (fgets(buffer, OS_MAXSTR, fp) != NULL) {
char *str_pt;
char *tmp_str;
str_pt = buffer;
tmp_str = strchr(buffer, ' ');
if (!tmp_str) {
merror(EXEC_INV_CONF, ARGV0, DEFAULTARPATH);
continue;
}
*tmp_str = '\0';
tmp_str++;
if (*tmp_str == '-') {
tmp_str += 2;
} else {
merror(EXEC_INV_CONF, ARGV0, DEFAULTARPATH);
continue;
}
strncpy(exec_names[exec_size], str_pt, OS_FLSIZE);
exec_names[exec_size][OS_FLSIZE] = '\0';
str_pt = tmp_str;
tmp_str = strchr(tmp_str, ' ');
if (!tmp_str) {
merror(EXEC_INV_CONF, ARGV0, DEFAULTARPATH);
continue;
}
*tmp_str = '\0';
snprintf(exec_cmd[exec_size], OS_FLSIZE,
"%s/%s",
AR_BINDIRPATH,
str_pt);
process_file = fopen(exec_cmd[exec_size], "r");
if (!process_file) {
if (f_time_reading) {
verbose("%s: INFO: Active response command not present: '%s'. "
"Not using it on this system.",
ARGV0, exec_cmd[exec_size]);
}
exec_cmd[exec_size][0] = '\0';
} else {
fclose(process_file);
}
tmp_str++;
if (*tmp_str == '-') {
tmp_str += 2;
} else {
merror(EXEC_INV_CONF, ARGV0, DEFAULTARPATH);
continue;
}
str_pt = tmp_str;
tmp_str = strchr(tmp_str, '\n');
if (tmp_str) {
*tmp_str = '\0';
}
exec_timeout[exec_size] = atoi(str_pt);
dup_entry = 0;
for (j = 0; j < exec_size; j++) {
if (strcmp(exec_names[j], exec_names[exec_size]) == 0) {
if (exec_cmd[j][0] == '\0') {
strncpy(exec_cmd[j], exec_cmd[exec_size], OS_FLSIZE);
exec_cmd[j][OS_FLSIZE] = '\0';
dup_entry = 1;
break;
} else if (exec_cmd[exec_size][0] == '\0') {
dup_entry = 1;
}
}
}
if (dup_entry) {
exec_cmd[exec_size][0] = '\0';
exec_names[exec_size][0] = '\0';
exec_timeout[exec_size] = 0;
} else {
exec_size++;
}
}
fclose(fp);
f_time_reading = 0;
return (1);
}

long do_mmu_update(
XEN_GUEST_HANDLE_PARAM(mmu_update_t) ureqs,
unsigned int count,
XEN_GUEST_HANDLE_PARAM(uint) pdone,
unsigned int foreigndom)
{
struct mmu_update req;
void *va = NULL;
unsigned long gpfn, gmfn;
struct page_info *page;
unsigned int cmd, i = 0, done = 0, pt_dom;
struct vcpu *curr = current, *v = curr;
struct domain *d = v->domain, *pt_owner = d, *pg_owner;
mfn_t map_mfn = INVALID_MFN, mfn;
bool sync_guest = false;
uint32_t xsm_needed = 0;
uint32_t xsm_checked = 0;
int rc = put_old_guest_table(curr);
if ( unlikely(rc) )
{
if ( likely(rc == -ERESTART) )
rc = hypercall_create_continuation(
__HYPERVISOR_mmu_update, "hihi", ureqs, count, pdone,
foreigndom);
return rc;
}
if ( unlikely(count == MMU_UPDATE_PREEMPTED) &&
likely(guest_handle_is_null(ureqs)) )
{
return (int)foreigndom;
}
if ( unlikely(count & MMU_UPDATE_PREEMPTED) )
{
count &= ~MMU_UPDATE_PREEMPTED;
if ( unlikely(!guest_handle_is_null(pdone)) )
(void)copy_from_guest(&done, pdone, 1);
}
else
perfc_incr(calls_to_mmu_update);
if ( unlikely(!guest_handle_okay(ureqs, count)) )
return -EFAULT;
if ( (pt_dom = foreigndom >> 16) != 0 )
{
if ( (pt_owner = rcu_lock_domain_by_id(pt_dom - 1)) == NULL )
return -ESRCH;
if ( pt_owner == d )
rcu_unlock_domain(pt_owner);
else if ( !pt_owner->vcpu || (v = pt_owner->vcpu[0]) == NULL )
{
rc = -EINVAL;
goto out;
}
}
if ( (pg_owner = get_pg_owner((uint16_t)foreigndom)) == NULL )
{
rc = -ESRCH;
goto out;
}
for ( i = 0; i < count; i++ )
{
if ( curr->arch.old_guest_table || (i && hypercall_preempt_check()) )
{
rc = -ERESTART;
break;
}
if ( unlikely(__copy_from_guest(&req, ureqs, 1) != 0) )
{
rc = -EFAULT;
break;
}
cmd = req.ptr & (sizeof(l1_pgentry_t)-1);
switch ( cmd )
{
case MMU_NORMAL_PT_UPDATE:
case MMU_PT_UPDATE_PRESERVE_AD:
case MMU_PT_UPDATE_NO_TRANSLATE:
{
p2m_type_t p2mt;
rc = -EOPNOTSUPP;
if ( unlikely(paging_mode_refcounts(pt_owner)) )
break;
xsm_needed |= XSM_MMU_NORMAL_UPDATE;
if ( get_pte_flags(req.val) & _PAGE_PRESENT )
{
xsm_needed |= XSM_MMU_UPDATE_READ;
if ( get_pte_flags(req.val) & _PAGE_RW )
xsm_needed |= XSM_MMU_UPDATE_WRITE;
}
if ( xsm_needed != xsm_checked )
{
rc = xsm_mmu_update(XSM_TARGET, d, pt_owner, pg_owner, xsm_needed);
if ( rc )
break;
xsm_checked = xsm_needed;
}
rc = -EINVAL;
req.ptr -= cmd;
gmfn = req.ptr >> PAGE_SHIFT;
page = get_page_from_gfn(pt_owner, gmfn, &p2mt, P2M_ALLOC);
if ( unlikely(!page) || p2mt != p2m_ram_rw )
{
if ( page )
put_page(page);
if ( p2m_is_paged(p2mt) )
{
p2m_mem_paging_populate(pt_owner, _gfn(gmfn));
rc = -ENOENT;
}
else
gdprintk(XENLOG_WARNING,
"Could not get page for normal update\n");
break;
}
mfn = page_to_mfn(page);
if ( !mfn_eq(mfn, map_mfn) )
{
if ( va )
unmap_domain_page(va);
va = map_domain_page(mfn);
map_mfn = mfn;
}
va = _p(((unsigned long)va & PAGE_MASK) + (req.ptr & ~PAGE_MASK));
if ( page_lock(page) )
{
switch ( page->u.inuse.type_info & PGT_type_mask )
{
case PGT_l1_page_table:
rc = mod_l1_entry(va, l1e_from_intpte(req.val), mfn,
cmd, v, pg_owner);
break;
case PGT_l2_page_table:
if ( unlikely(pg_owner != pt_owner) )
break;
rc = mod_l2_entry(va, l2e_from_intpte(req.val), mfn,
cmd == MMU_PT_UPDATE_PRESERVE_AD, v);
break;
case PGT_l3_page_table:
if ( unlikely(pg_owner != pt_owner) )
break;
rc = mod_l3_entry(va, l3e_from_intpte(req.val), mfn,
cmd == MMU_PT_UPDATE_PRESERVE_AD, v);
break;
case PGT_l4_page_table:
if ( unlikely(pg_owner != pt_owner) )
break;
rc = mod_l4_entry(va, l4e_from_intpte(req.val), mfn,
cmd == MMU_PT_UPDATE_PRESERVE_AD, v);
if ( !rc && pt_owner->arch.pv.xpti )
{
bool local_in_use = false;
if ( mfn_eq(pagetable_get_mfn(curr->arch.guest_table),
mfn) )
{
local_in_use = true;
get_cpu_info()->root_pgt_changed = true;
}
if ( (page->u.inuse.type_info & PGT_count_mask) >
(1 + !!(page->u.inuse.type_info & PGT_pinned) +
mfn_eq(pagetable_get_mfn(curr->arch.guest_table_user),
mfn) + local_in_use) )
sync_guest = true;
}
break;
case PGT_writable_page:
perfc_incr(writable_mmu_updates);
paging_write_guest_entry(v, va, req.val, mfn);
rc = 0;
break;
}
page_unlock(page);
if ( rc == -EINTR )
rc = -ERESTART;
}
else if ( get_page_type(page, PGT_writable_page) )
{
perfc_incr(writable_mmu_updates);
paging_write_guest_entry(v, va, req.val, mfn);
put_page_type(page);
rc = 0;
}
put_page(page);
}
break;
case MMU_MACHPHYS_UPDATE:
if ( unlikely(d != pt_owner) )
{
rc = -EPERM;
break;
}
if ( unlikely(paging_mode_translate(pg_owner)) )
{
rc = -EINVAL;
break;
}
mfn = maddr_to_mfn(req.ptr);
gpfn = req.val;
xsm_needed |= XSM_MMU_MACHPHYS_UPDATE;
if ( xsm_needed != xsm_checked )
{
rc = xsm_mmu_update(XSM_TARGET, d, NULL, pg_owner, xsm_needed);
if ( rc )
break;
xsm_checked = xsm_needed;
}
page = get_page_from_mfn(mfn, pg_owner);
if ( unlikely(!page) )
{
gdprintk(XENLOG_WARNING,
"Could not get page for mach->phys update\n");
rc = -EINVAL;
break;
}
set_gpfn_from_mfn(mfn_x(mfn), gpfn);
paging_mark_pfn_dirty(pg_owner, _pfn(gpfn));
put_page(page);
break;
default:
rc = -ENOSYS;
break;
}
if ( unlikely(rc) )
break;
guest_handle_add_offset(ureqs, 1);
}
if ( rc == -ERESTART )
rc = hypercall_create_continuation(
__HYPERVISOR_mmu_update, "hihi",
ureqs, (count - i) | MMU_UPDATE_PREEMPTED, pdone, foreigndom);
else if ( curr->arch.old_guest_table )
{
XEN_GUEST_HANDLE_PARAM(void) null;
ASSERT(rc || i == count);
set_xen_guest_handle(null, NULL);
rc = hypercall_create_continuation(
__HYPERVISOR_mmu_update, "hihi", null,
MMU_UPDATE_PREEMPTED, null, rc);
}
put_pg_owner(pg_owner);
if ( va )
unmap_domain_page(va);
if ( sync_guest )
{
unsigned int cpu = smp_processor_id();
cpumask_t *mask = per_cpu(scratch_cpumask, cpu);
cpumask_andnot(mask, pt_owner->dirty_cpumask, cpumask_of(cpu));
if ( !cpumask_empty(mask) )
flush_mask(mask, FLUSH_ROOT_PGTBL);
}
perfc_add(num_page_updates, i);
out:
if ( pt_owner != d )
rcu_unlock_domain(pt_owner);
if ( unlikely(!guest_handle_is_null(pdone)) )
{
done += i;
copy_to_guest(pdone, &done, 1);
}
return rc;
}

int handle(int s, unsigned char* data, int len, struct sockaddr_in *s_in)
{
char buf[2048];
unsigned short *cmd = (unsigned short *)buf;
int plen;
struct in_addr *addr = &s_in->sin_addr;
unsigned short *pid = (unsigned short*) data;
if (len == S_HELLO_LEN && memcmp(data, "sorbo", 5) == 0) {
unsigned short *id = (unsigned short*) (data+5);
int x = 2+4+2;
*cmd = htons(S_CMD_INET_CHECK);
memcpy(cmd+1, addr, 4);
memcpy(cmd+1+2, id, 2);
printf("Inet check by %s %d\n",
inet_ntoa(*addr), ntohs(*id));
if (send(s, buf, x, 0) != x)
return 1;
return 0;
}
*cmd++ = htons(S_CMD_PACKET);
*cmd++ = *pid;
plen = len - 2;
last_id = ntohs(*pid);
if (last_id > 20000)
wrap = 1;
if (wrap && last_id < 100) {
wrap = 0;
memset(ids, 0, sizeof(ids));
}
printf("Got packet %d %d", last_id, plen);
if (is_dup(last_id)) {
printf(" (DUP)\n");
return 0;
}
printf("\n");
*cmd++ = htons(plen);
memcpy(cmd, data+2, plen);
plen += 2 + 2 + 2;
assert(plen <= (int) sizeof(buf));
if (send(s, buf, plen, 0) != plen)
return 1;
return 0;
}

static Image *ReadSUNImage(const ImageInfo *image_info,ExceptionInfo *exception)
{
#define RMT_EQUAL_RGB  1
#define RMT_NONE  0
#define RMT_RAW  2
#define RT_STANDARD  1
#define RT_ENCODED  2
#define RT_FORMAT_RGB  3
typedef struct _SUNInfo
{
unsigned int
magic,
width,
height,
depth,
length,
type,
maptype,
maplength;
} SUNInfo;
Image
*image;
int
bit;
MagickBooleanType
status;
MagickSizeType
number_pixels;
register Quantum
*q;
register ssize_t
i,
x;
register unsigned char
*p;
size_t
bytes_per_line,
extent,
length;
ssize_t
count,
y;
SUNInfo
sun_info;
unsigned char
*sun_data,
*sun_pixels;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickSignature);
if (image_info->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
image_info->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickSignature);
image=AcquireImage(image_info,exception);
status=OpenBlob(image_info,image,ReadBinaryBlobMode,exception);
if (status == MagickFalse)
{
image=DestroyImageList(image);
return((Image *) NULL);
}
(void) ResetMagickMemory(&sun_info,0,sizeof(sun_info));
sun_info.magic=ReadBlobMSBLong(image);
do
{
if (sun_info.magic != 0x59a66a95)
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
sun_info.width=ReadBlobMSBLong(image);
sun_info.height=ReadBlobMSBLong(image);
sun_info.depth=ReadBlobMSBLong(image);
sun_info.length=ReadBlobMSBLong(image);
sun_info.type=ReadBlobMSBLong(image);
sun_info.maptype=ReadBlobMSBLong(image);
sun_info.maplength=ReadBlobMSBLong(image);
extent=sun_info.height*sun_info.width;
if ((sun_info.height != 0) && (sun_info.width != extent/sun_info.height))
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
if ((sun_info.type != RT_STANDARD) && (sun_info.type != RT_ENCODED) &&
(sun_info.type != RT_FORMAT_RGB))
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
if ((sun_info.maptype == RMT_NONE) && (sun_info.maplength != 0))
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
if ((sun_info.depth == 0) || (sun_info.depth > 32))
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
if ((sun_info.maptype != RMT_NONE) && (sun_info.maptype != RMT_EQUAL_RGB) &&
(sun_info.maptype != RMT_RAW))
ThrowReaderException(CoderError,"ColormapTypeNotSupported");
image->columns=sun_info.width;
image->rows=sun_info.height;
image->depth=sun_info.depth <= 8 ? sun_info.depth :
MAGICKCORE_QUANTUM_DEPTH;
if (sun_info.depth < 24)
{
size_t
one;
image->storage_class=PseudoClass;
image->colors=sun_info.maplength;
one=1;
if (sun_info.maptype == RMT_NONE)
image->colors=one << sun_info.depth;
if (sun_info.maptype == RMT_EQUAL_RGB)
image->colors=sun_info.maplength/3;
}
switch (sun_info.maptype)
{
case RMT_NONE:
{
if (sun_info.depth < 24)
{
if (AcquireImageColormap(image,image->colors,exception) == MagickFalse)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
}
break;
}
case RMT_EQUAL_RGB:
{
unsigned char
*sun_colormap;
if (AcquireImageColormap(image,image->colors,exception) == MagickFalse)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
sun_colormap=(unsigned char *) AcquireQuantumMemory(image->colors,
sizeof(*sun_colormap));
if (sun_colormap == (unsigned char *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
count=ReadBlob(image,image->colors,sun_colormap);
if (count != (ssize_t) image->colors)
ThrowReaderException(CorruptImageError,"UnexpectedEndOfFile");
for (i=0; i < (ssize_t) image->colors; i++)
image->colormap[i].red=(MagickRealType) ScaleCharToQuantum(
sun_colormap[i]);
count=ReadBlob(image,image->colors,sun_colormap);
if (count != (ssize_t) image->colors)
ThrowReaderException(CorruptImageError,"UnexpectedEndOfFile");
for (i=0; i < (ssize_t) image->colors; i++)
image->colormap[i].green=(MagickRealType) ScaleCharToQuantum(
sun_colormap[i]);
count=ReadBlob(image,image->colors,sun_colormap);
if (count != (ssize_t) image->colors)
ThrowReaderException(CorruptImageError,"UnexpectedEndOfFile");
for (i=0; i < (ssize_t) image->colors; i++)
image->colormap[i].blue=(MagickRealType) ScaleCharToQuantum(
sun_colormap[i]);
sun_colormap=(unsigned char *) RelinquishMagickMemory(sun_colormap);
break;
}
case RMT_RAW:
{
unsigned char
*sun_colormap;
sun_colormap=(unsigned char *) AcquireQuantumMemory(sun_info.maplength,
sizeof(*sun_colormap));
if (sun_colormap == (unsigned char *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
count=ReadBlob(image,sun_info.maplength,sun_colormap);
if (count != (ssize_t) sun_info.maplength)
ThrowReaderException(CorruptImageError,"UnexpectedEndOfFile");
sun_colormap=(unsigned char *) RelinquishMagickMemory(sun_colormap);
break;
}
default:
ThrowReaderException(CoderError,"ColormapTypeNotSupported");
}
image->alpha_trait=sun_info.depth == 32 ? BlendPixelTrait :
UndefinedPixelTrait;
image->columns=sun_info.width;
image->rows=sun_info.height;
if (image_info->ping != MagickFalse)
{
(void) CloseBlob(image);
return(GetFirstImageInList(image));
}
status=SetImageExtent(image,image->columns,image->rows,exception);
if (status == MagickFalse)
return(DestroyImageList(image));
if ((sun_info.length*sizeof(*sun_data))/sizeof(*sun_data) !=
sun_info.length || !sun_info.length)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
number_pixels=(MagickSizeType) image->columns*image->rows;
if ((sun_info.type != RT_ENCODED) && (sun_info.depth >= 8) &&
((number_pixels*((sun_info.depth+7)/8)) > sun_info.length))
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
bytes_per_line=sun_info.width*sun_info.depth;
sun_data=(unsigned char *) AcquireQuantumMemory((size_t) MagickMax(
sun_info.length,bytes_per_line*sun_info.width),sizeof(*sun_data));
if (sun_data == (unsigned char *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
count=(ssize_t) ReadBlob(image,sun_info.length,sun_data);
if (count != (ssize_t) sun_info.length)
ThrowReaderException(CorruptImageError,"UnableToReadImageData");
sun_pixels=sun_data;
bytes_per_line=0;
if (sun_info.type == RT_ENCODED)
{
size_t
height;
height=sun_info.height;
if ((height == 0) || (sun_info.width == 0) || (sun_info.depth == 0) ||
((bytes_per_line/sun_info.depth) != sun_info.width))
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
bytes_per_line+=15;
bytes_per_line<<=1;
if ((bytes_per_line >> 1) != (sun_info.width*sun_info.depth+15))
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
bytes_per_line>>=4;
sun_pixels=(unsigned char *) AcquireQuantumMemory(height,
bytes_per_line*sizeof(*sun_pixels));
if (sun_pixels == (unsigned char *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
(void) DecodeImage(sun_data,sun_info.length,sun_pixels,bytes_per_line*
height);
sun_data=(unsigned char *) RelinquishMagickMemory(sun_data);
}
p=sun_pixels;
if (sun_info.depth == 1)
for (y=0; y < (ssize_t) image->rows; y++)
{
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < ((ssize_t) image->columns-7); x+=8)
{
for (bit=7; bit >= 0; bit--)
{
SetPixelIndex(image,(Quantum) ((*p) & (0x01 << bit) ? 0x00 : 0x01),
q);
q+=GetPixelChannels(image);
}
p++;
}
if ((image->columns % 8) != 0)
{
for (bit=7; bit >= (int) (8-(image->columns % 8)); bit--)
{
SetPixelIndex(image,(Quantum) ((*p) & (0x01 << bit) ? 0x00 :
0x01),q);
q+=GetPixelChannels(image);
}
p++;
}
if ((((image->columns/8)+(image->columns % 8 ? 1 : 0)) % 2) != 0)
p++;
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
else
if (image->storage_class == PseudoClass)
{
if (bytes_per_line == 0)
bytes_per_line=image->columns;
length=image->rows*(image->columns+image->columns % 2);
if (((sun_info.type == RT_ENCODED) &&
(length > (bytes_per_line*image->rows))) ||
((sun_info.type != RT_ENCODED) && (length > sun_info.length)))
ThrowReaderException(CorruptImageError,"UnableToReadImageData");
for (y=0; y < (ssize_t) image->rows; y++)
{
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < (ssize_t) image->columns; x++)
{
SetPixelIndex(image,*p++,q);
q+=GetPixelChannels(image);
}
if ((image->columns % 2) != 0)
p++;
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
}
else
{
size_t
bytes_per_pixel;
bytes_per_pixel=3;
if (image->alpha_trait != UndefinedPixelTrait)
bytes_per_pixel++;
if (bytes_per_line == 0)
bytes_per_line=bytes_per_pixel*image->columns;
length=image->rows*(bytes_per_line+image->columns % 2);
if (((sun_info.type == RT_ENCODED) &&
(length > (bytes_per_line*image->rows))) ||
((sun_info.type != RT_ENCODED) && (length > sun_info.length)))
ThrowReaderException(CorruptImageError,"UnableToReadImageData");
for (y=0; y < (ssize_t) image->rows; y++)
{
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < (ssize_t) image->columns; x++)
{
if (image->alpha_trait != UndefinedPixelTrait)
SetPixelAlpha(image,ScaleCharToQuantum(*p++),q);
if (sun_info.type == RT_STANDARD)
{
SetPixelBlue(image,ScaleCharToQuantum(*p++),q);
SetPixelGreen(image,ScaleCharToQuantum(*p++),q);
SetPixelRed(image,ScaleCharToQuantum(*p++),q);
}
else
{
SetPixelRed(image,ScaleCharToQuantum(*p++),q);
SetPixelGreen(image,ScaleCharToQuantum(*p++),q);
SetPixelBlue(image,ScaleCharToQuantum(*p++),q);
}
if (image->colors != 0)
{
SetPixelRed(image,ClampToQuantum(image->colormap[(ssize_t)
GetPixelRed(image,q)].red),q);
SetPixelGreen(image,ClampToQuantum(image->colormap[(ssize_t)
GetPixelGreen(image,q)].green),q);
SetPixelBlue(image,ClampToQuantum(image->colormap[(ssize_t)
GetPixelBlue(image,q)].blue),q);
}
q+=GetPixelChannels(image);
}
if (((bytes_per_pixel*image->columns) % 2) != 0)
p++;
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
}
if (image->storage_class == PseudoClass)
(void) SyncImage(image,exception);
sun_pixels=(unsigned char *) RelinquishMagickMemory(sun_pixels);
if (EOFBlob(image) != MagickFalse)
{
ThrowFileException(exception,CorruptImageError,"UnexpectedEndOfFile",
image->filename);
break;
}
if (image_info->number_scenes != 0)
if (image->scene >= (image_info->scene+image_info->number_scenes-1))
break;
sun_info.magic=ReadBlobMSBLong(image);
if (sun_info.magic == 0x59a66a95)
{
AcquireNextImage(image_info,image,exception);
if (GetNextImageInList(image) == (Image *) NULL)
{
image=DestroyImageList(image);
return((Image *) NULL);
}
image=SyncNextImageInList(image);
status=SetImageProgress(image,LoadImagesTag,TellBlob(image),
GetBlobSize(image));
if (status == MagickFalse)
break;
}
} while (sun_info.magic == 0x59a66a95);
(void) CloseBlob(image);
return(GetFirstImageInList(image));
}

void LibRaw::parse_x3f()
{
x3f_t *x3f = x3f_new_from_file(libraw_internal_data.internal_data.input);
if(!x3f)
return;
_x3f_data = x3f;
x3f_header_t *H = NULL;
x3f_directory_section_t *DS = NULL;
H = &x3f->header;
x3f_directory_entry_t *DE = x3f_get_raw(x3f);
if(!DE) return;
imgdata.sizes.flip = H->rotation;
x3f_directory_entry_header_t *DEH = &DE->header;
x3f_image_data_t *ID = &DEH->data_subsection.image_data;
imgdata.sizes.raw_width = ID->columns;
imgdata.sizes.raw_height = ID->rows;
DE = x3f_get_prop(x3f);
if((x3f_load_data(x3f,DE) == X3F_OK))
{
DEH = &DE->header;
x3f_property_list_t *PL = &DEH->data_subsection.property_list;
if (PL->property_table.size != 0) {
int i;
x3f_property_t *P = PL->property_table.element;
for (i=0; i<PL->num_properties; i++) {
char name[100], value[100];
utf2char(P[i].name,name);
utf2char(P[i].value,value);
if (!strcmp (name, "ISO"))
imgdata.other.iso_speed = atoi(value);
if (!strcmp (name, "CAMMANUF"))
strcpy (imgdata.idata.make, value);
if (!strcmp (name, "CAMMODEL"))
strcpy (imgdata.idata.model, value);
if (!strcmp (name, "CAMSERIAL"))
strcpy (imgdata.shootinginfo.BodySerial, value);
if (!strcmp (name, "WB_DESC"))
strcpy (imgdata.color.model2, value);
if (!strcmp (name, "TIME"))
imgdata.other.timestamp = atoi(value);
if (!strcmp (name, "SHUTTER"))
imgdata.other.shutter = atof(value);
if (!strcmp (name, "APERTURE"))
imgdata.other.aperture = atof(value);
if (!strcmp (name, "FLENGTH"))
imgdata.other.focal_len = atof(value);
if (!strcmp (name, "FLEQ35MM"))
imgdata.lens.makernotes.FocalLengthIn35mmFormat = atof(value);
if (!strcmp (name, "LENSARANGE"))
{
char *sp;
imgdata.lens.makernotes.MaxAp4CurFocal = imgdata.lens.makernotes.MinAp4CurFocal = atof(value);
sp = strrchr (value, ' ');
if (sp)
{
imgdata.lens.makernotes.MinAp4CurFocal = atof(sp);
if (imgdata.lens.makernotes.MaxAp4CurFocal > imgdata.lens.makernotes.MinAp4CurFocal)
my_swap (float, imgdata.lens.makernotes.MaxAp4CurFocal, imgdata.lens.makernotes.MinAp4CurFocal);
}
}
if (!strcmp (name, "LENSFRANGE"))
{
char *sp;
imgdata.lens.makernotes.MinFocal = imgdata.lens.makernotes.MaxFocal = atof(value);
sp = strrchr (value, ' ');
if (sp)
{
imgdata.lens.makernotes.MaxFocal = atof(sp);
if ((imgdata.lens.makernotes.MaxFocal + 0.17f) < imgdata.lens.makernotes.MinFocal)
my_swap (float, imgdata.lens.makernotes.MaxFocal, imgdata.lens.makernotes.MinFocal);
}
}
if (!strcmp (name, "LENSMODEL"))
{
char *sp;
imgdata.lens.makernotes.LensID = strtol (value, &sp, 16); if (imgdata.lens.makernotes.LensID)
imgdata.lens.makernotes.LensMount = Sigma_X3F;
}
}
imgdata.idata.raw_count=1;
load_raw = &LibRaw::x3f_load_raw;
imgdata.sizes.raw_pitch = imgdata.sizes.raw_width*6;
imgdata.idata.is_foveon = 1;
libraw_internal_data.internal_output_params.raw_color=1;   imgdata.color.maximum=0x3fff;   libraw_internal_data.unpacker_data.order = 0x4949;
}
}
else
{
if(imgdata.sizes.raw_width == 5888 ||imgdata.sizes.raw_width == 2944 
|| imgdata.sizes.raw_width == 6656 ||imgdata.sizes.raw_width == 3328   
|| imgdata.sizes.raw_width == 5504 ||imgdata.sizes.raw_width == 2752   
)   {
imgdata.idata.raw_count=1;
load_raw = &LibRaw::x3f_load_raw;
imgdata.sizes.raw_pitch = imgdata.sizes.raw_width*6;
imgdata.idata.is_foveon = 1;
libraw_internal_data.internal_output_params.raw_color=1;   libraw_internal_data.unpacker_data.order = 0x4949;
strcpy (imgdata.idata.make, "SIGMA");
#if 1
int pos = libraw_internal_data.internal_data.input->tell();
libraw_internal_data.internal_data.input->seek(0,SEEK_SET);
unsigned char buf[2048];
libraw_internal_data.internal_data.input->read(buf,2048,1);
libraw_internal_data.internal_data.input->seek(pos,SEEK_SET);
unsigned char *fnd=(unsigned char*)lr_memmem(buf,2048,"SIGMA dp",8);
unsigned char *fndsd=(unsigned char*)lr_memmem(buf,2048,"sd Quatt",8);
if(fnd)
{
unsigned char *nm = fnd+8;
snprintf(imgdata.idata.model,64,"dp%c Quattro",*nm<='9' && *nm >='0' ? *nm: '2');
}
else if(fndsd)
{
snprintf(imgdata.idata.model,64,"%s",fndsd);
}
else
#endif
if(imgdata.sizes.raw_width == 6656 ||imgdata.sizes.raw_width == 3328 )
strcpy (imgdata.idata.model, "sd Quattro H");
else
strcpy (imgdata.idata.model, "dp2 Quattro");
}
}
LibRaw_thumbnail_formats format = LIBRAW_THUMBNAIL_UNKNOWN;
if( (DE = x3f_get_thumb_jpeg(x3f)))
{
format = LIBRAW_THUMBNAIL_JPEG;
}
else if( (DE = x3f_get_thumb_plain(x3f)))
{
format = LIBRAW_THUMBNAIL_BITMAP;
}
if(DE)
{
x3f_directory_entry_header_t *DEH = &DE->header;
x3f_image_data_t *ID = &DEH->data_subsection.image_data;
imgdata.thumbnail.twidth = ID->columns;
imgdata.thumbnail.theight = ID->rows;
imgdata.thumbnail.tcolors = 3;
imgdata.thumbnail.tformat = format;
libraw_internal_data.internal_data.toffset = DE->input.offset;
write_thumb = &LibRaw::x3f_thumb_loader;
}
}

int mbedtls_x509_crt_verify_with_profile( mbedtls_x509_crt *crt,
mbedtls_x509_crt *trust_ca,
mbedtls_x509_crl *ca_crl,
const mbedtls_x509_crt_profile *profile,
const char *cn, uint32_t *flags,
int (*f_vrfy)(void *, mbedtls_x509_crt *, int, uint32_t *),
void *p_vrfy )
{
size_t cn_len;
int ret;
int pathlen = 0, selfsigned = 0;
mbedtls_x509_crt *parent;
mbedtls_x509_name *name;
mbedtls_x509_sequence *cur = NULL;
mbedtls_pk_type_t pk_type;
*flags = 0;
if( profile == NULL )
{
ret = MBEDTLS_ERR_X509_BAD_INPUT_DATA;
goto exit;
}
if( cn != NULL )
{
name = &crt->subject;
cn_len = strlen( cn );
if( crt->ext_types & MBEDTLS_X509_EXT_SUBJECT_ALT_NAME )
{
cur = &crt->subject_alt_names;
while( cur != NULL )
{
if( cur->buf.len == cn_len &&
x509_memcasecmp( cn, cur->buf.p, cn_len ) == 0 )
break;
if( cur->buf.len > 2 &&
memcmp( cur->buf.p, "*.", 2 ) == 0 &&
x509_check_wildcard( cn, &cur->buf ) == 0 )
{
break;
}
cur = cur->next;
}
if( cur == NULL )
*flags |= MBEDTLS_X509_BADCERT_CN_MISMATCH;
}
else
{
while( name != NULL )
{
if( MBEDTLS_OID_CMP( MBEDTLS_OID_AT_CN, &name->oid ) == 0 )
{
if( name->val.len == cn_len &&
x509_memcasecmp( name->val.p, cn, cn_len ) == 0 )
break;
if( name->val.len > 2 &&
memcmp( name->val.p, "*.", 2 ) == 0 &&
x509_check_wildcard( cn, &name->val ) == 0 )
break;
}
name = name->next;
}
if( name == NULL )
*flags |= MBEDTLS_X509_BADCERT_CN_MISMATCH;
}
}
pk_type = mbedtls_pk_get_type( &crt->pk );
if( x509_profile_check_pk_alg( profile, pk_type ) != 0 )
*flags |= MBEDTLS_X509_BADCERT_BAD_PK;
if( x509_profile_check_key( profile, pk_type, &crt->pk ) != 0 )
*flags |= MBEDTLS_X509_BADCERT_BAD_KEY;
for( parent = trust_ca; parent != NULL; parent = parent->next )
{
if( x509_crt_check_parent( crt, parent, 0, pathlen == 0 ) == 0 )
break;
}
if( parent != NULL )
{
ret = x509_crt_verify_top( crt, parent, ca_crl, profile,
pathlen, selfsigned, flags, f_vrfy, p_vrfy );
if( ret != 0 )
goto exit;
}
else
{
for( parent = crt->next; parent != NULL; parent = parent->next )
if( x509_crt_check_parent( crt, parent, 0, pathlen == 0 ) == 0 )
break;
if( parent != NULL )
{
ret = x509_crt_verify_child( crt, parent, trust_ca, ca_crl, profile,
pathlen, selfsigned, flags, f_vrfy, p_vrfy );
if( ret != 0 )
goto exit;
}
else
{
ret = x509_crt_verify_top( crt, trust_ca, ca_crl, profile,
pathlen, selfsigned, flags, f_vrfy, p_vrfy );
if( ret != 0 )
goto exit;
}
}
exit:
if( ret != 0 )
{
*flags = (uint32_t) -1;
return( ret );
}
if( *flags != 0 )
return( MBEDTLS_ERR_X509_CERT_VERIFY_FAILED );
return( 0 );
}

int mbedtls_x509_crt_verify_with_profile( mbedtls_x509_crt *crt,
mbedtls_x509_crt *trust_ca,
mbedtls_x509_crl *ca_crl,
const mbedtls_x509_crt_profile *profile,
const char *cn, uint32_t *flags,
int (*f_vrfy)(void *, mbedtls_x509_crt *, int, uint32_t *),
void *p_vrfy )
{
size_t cn_len;
int ret;
int pathlen = 0, selfsigned = 0;
mbedtls_x509_crt *parent;
mbedtls_x509_name *name;
mbedtls_x509_sequence *cur = NULL;
mbedtls_pk_type_t pk_type;
*flags = 0;
if( profile == NULL )
{
ret = MBEDTLS_ERR_X509_BAD_INPUT_DATA;
goto exit;
}
if( cn != NULL )
{
name = &crt->subject;
cn_len = strlen( cn );
if( crt->ext_types & MBEDTLS_X509_EXT_SUBJECT_ALT_NAME )
{
cur = &crt->subject_alt_names;
while( cur != NULL )
{
if( cur->buf.len == cn_len &&
x509_memcasecmp( cn, cur->buf.p, cn_len ) == 0 )
break;
if( cur->buf.len > 2 &&
memcmp( cur->buf.p, "*.", 2 ) == 0 &&
x509_check_wildcard( cn, &cur->buf ) == 0 )
{
break;
}
cur = cur->next;
}
if( cur == NULL )
*flags |= MBEDTLS_X509_BADCERT_CN_MISMATCH;
}
else
{
while( name != NULL )
{
if( MBEDTLS_OID_CMP( MBEDTLS_OID_AT_CN, &name->oid ) == 0 )
{
if( name->val.len == cn_len &&
x509_memcasecmp( name->val.p, cn, cn_len ) == 0 )
break;
if( name->val.len > 2 &&
memcmp( name->val.p, "*.", 2 ) == 0 &&
x509_check_wildcard( cn, &name->val ) == 0 )
break;
}
name = name->next;
}
if( name == NULL )
*flags |= MBEDTLS_X509_BADCERT_CN_MISMATCH;
}
}
pk_type = mbedtls_pk_get_type( &crt->pk );
if( x509_profile_check_pk_alg( profile, pk_type ) != 0 )
*flags |= MBEDTLS_X509_BADCERT_BAD_PK;
if( x509_profile_check_key( profile, pk_type, &crt->pk ) != 0 )
*flags |= MBEDTLS_X509_BADCERT_BAD_KEY;
for( parent = trust_ca; parent != NULL; parent = parent->next )
{
if( x509_crt_check_parent( crt, parent, 0, pathlen == 0 ) == 0 )
break;
}
if( parent != NULL )
{
ret = x509_crt_verify_top( crt, parent, ca_crl, profile,
pathlen, selfsigned, flags, f_vrfy, p_vrfy );
if( ret != 0 )
goto exit;
}
else
{
for( parent = crt->next; parent != NULL; parent = parent->next )
if( x509_crt_check_parent( crt, parent, 0, pathlen == 0 ) == 0 )
break;
if( parent != NULL )
{
ret = x509_crt_verify_child( crt, parent, trust_ca, ca_crl, profile,
pathlen, selfsigned, flags, f_vrfy, p_vrfy );
if( ret != 0 )
goto exit;
}
else
{
ret = x509_crt_verify_top( crt, trust_ca, ca_crl, profile,
pathlen, selfsigned, flags, f_vrfy, p_vrfy );
if( ret != 0 )
goto exit;
}
}
exit:
if( ret != 0 )
{
*flags = (uint32_t) -1;
return( ret );
}
if( *flags != 0 )
return( MBEDTLS_ERR_X509_CERT_VERIFY_FAILED );
return( 0 );
}

AsyncActions
EventHandler<ServerTypes, StateEnum::ExpectingClientHello, Event::ClientHello>::
handle(const State& state, Param param) {
ClientHello chlo = std::move(*param.asClientHello());
auto cookieState = getCookieState(chlo, state.context()->getCookieCipher());
if (state.handshakeContext() && cookieState.has_value()) {
throw FizzException(
"cookie after statefull hrr", AlertDescription::illegal_parameter);
}
ECHStatus echStatus;
ECHState echState;
std::tie(echStatus, echState) = processECH(cookieState, state, chlo);
addHandshakeLogging(state, chlo);
if (state.readRecordLayer()->hasUnparsedHandshakeData()) {
throw FizzException(
"data after client hello", AlertDescription::unexpected_message);
}
auto version =
negotiateVersion(chlo, state.context()->getSupportedVersions());
if (state.version().has_value() &&
(!version || *version != *state.version())) {
throw FizzException(
"version mismatch with previous negotiation",
AlertDescription::illegal_parameter);
}
if (!version) {
if (getExtension<ClientEarlyData>(chlo.extensions)) {
throw FizzException(
"supported version mismatch with early data",
AlertDescription::protocol_version);
}
if (state.context()->getVersionFallbackEnabled()) {
AttemptVersionFallback fallback;
fallback.clientHello =
PlaintextWriteRecordLayer()
.writeInitialClientHello(std::move(*chlo.originalEncoding))
.data;
return actions(
MutateState(&Transition<StateEnum::Error>), std::move(fallback));
} else {
throw FizzException(
"supported version mismatch", AlertDescription::protocol_version);
}
}
state.writeRecordLayer()->setProtocolVersion(*version);
validateClientHello(chlo);
auto cipher = negotiateCipher(chlo, state.context()->getSupportedCiphers());
verifyCookieState(cookieState, *version, cipher);
auto resStateResult = getResumptionState(
chlo,
state.context()->getTicketCipher(),
state.context()->getSupportedPskModes());
auto replayCacheResultFuture = getReplayCacheResult(
chlo,
state.context()->getAcceptEarlyData(*version),
state.context()->getReplayCache());
auto results =
collectAll(resStateResult.futureResState, replayCacheResultFuture);
using FutureResultType = std::tuple<
folly::Try<std::pair<PskType, Optional<ResumptionState>>>,
folly::Try<ReplayCacheResult>>;
return runOnCallerIfComplete(
state.executor(),
std::move(results),
[&state,
chlo = std::move(chlo),
cookieState = std::move(cookieState),
version = *version,
cipher,
pskMode = resStateResult.pskMode,
echStatus,
echState = std::move(echState),
obfuscatedAge =
resStateResult.obfuscatedAge](FutureResultType result) mutable {
auto& resumption = *std::get<0>(result);
auto pskType = resumption.first;
auto resState = std::move(resumption.second);
auto replayCacheResult = *std::get<1>(result);
if (resState) {
if (!validateResumptionState(*resState, *pskMode, version, cipher)) {
pskType = PskType::Rejected;
pskMode = folly::none;
resState = folly::none;
}
} else {
pskMode = folly::none;
}
auto legacySessionId = chlo.legacy_session_id->clone();
std::chrono::system_clock::time_point handshakeTime;
if (resState) {
handshakeTime = resState->handshakeTime;
} else {
handshakeTime = state.context()->getClock().getCurrentTime();
}
std::unique_ptr<KeyScheduler> scheduler;
std::unique_ptr<HandshakeContext> handshakeContext;
std::tie(scheduler, handshakeContext) = setupSchedulerAndContext(
*state.context()->getFactory(),
cipher,
chlo,
resState,
cookieState,
pskType,
std::move(state.handshakeContext()),
version);
if (state.cipher().has_value() && cipher != *state.cipher()) {
throw FizzException(
"cipher mismatch with previous negotiation",
AlertDescription::illegal_parameter);
}
auto alpn = negotiateAlpn(chlo, folly::none, *state.context());
auto clockSkew = getClockSkew(
resState,
obfuscatedAge,
state.context()->getClock().getCurrentTime());
auto appToken = getAppToken(resState);
auto earlyDataType = negotiateEarlyDataType(
state.context()->getAcceptEarlyData(version),
chlo,
resState,
cipher,
state.keyExchangeType(),
cookieState,
alpn,
replayCacheResult,
clockSkew,
state.context()->getClockSkewTolerance(),
state.appTokenValidator());
std::unique_ptr<EncryptedReadRecordLayer> earlyReadRecordLayer;
Buf earlyExporterMaster;
folly::Optional<SecretAvailable> earlyReadSecretAvailable;
if (earlyDataType == EarlyDataType::Accepted) {
auto earlyContext = handshakeContext->getHandshakeContext();
auto earlyReadSecret = scheduler->getSecret(
EarlySecrets::ClientEarlyTraffic, earlyContext->coalesce());
if (!state.context()->getOmitEarlyRecordLayer()) {
earlyReadRecordLayer =
state.context()->getFactory()->makeEncryptedReadRecordLayer(
EncryptionLevel::EarlyData);
earlyReadRecordLayer->setProtocolVersion(version);
Protocol::setAead(
*earlyReadRecordLayer,
cipher,
folly::range(earlyReadSecret.secret),
*state.context()->getFactory(),
*scheduler);
}
earlyReadSecretAvailable =
SecretAvailable(std::move(earlyReadSecret));
earlyExporterMaster = folly::IOBuf::copyBuffer(
scheduler
->getSecret(
EarlySecrets::EarlyExporter, earlyContext->coalesce())
.secret);
}
Optional<NamedGroup> group;
KeyExchangeType keyExchangeType;
SemiFuture<Optional<AsyncKeyExchange::DoKexResult>> kexResultFuture =
folly::none;
std::unique_ptr<KeyExchange> kex = nullptr;
if (!pskMode || *pskMode != PskKeyExchangeMode::psk_ke) {
Optional<Buf> clientShare;
std::tie(group, clientShare) = negotiateGroup(
version, chlo, state.context()->getSupportedGroups());
if (!clientShare) {
VLOG(8) << "Did not find key share for " << toString(*group);
if (state.group().has_value() || cookieState) {
throw FizzException(
"key share not found for already negotiated group",
AlertDescription::illegal_parameter);
}
if (earlyDataType == EarlyDataType::Accepted) {
earlyDataType = EarlyDataType::Rejected;
}
message_hash chloHash;
chloHash.hash = handshakeContext->getHandshakeContext();
handshakeContext =
state.context()->getFactory()->makeHandshakeContext(cipher);
handshakeContext->appendToTranscript(
encodeHandshake(std::move(chloHash)));
auto hrr = getHelloRetryRequest(
version,
cipher,
*group,
legacySessionId ? legacySessionId->clone() : nullptr,
*handshakeContext);
if (echStatus == ECHStatus::Accepted) {
auto echScheduler =
state.context()->getFactory()->makeKeyScheduler(cipher);
echScheduler->deriveEarlySecret(folly::range(chlo.random));
ech::setAcceptConfirmation(
hrr, handshakeContext->clone(), std::move(echScheduler));
}
auto encodedHelloRetryRequest = encodeHandshake(std::move(hrr));
handshakeContext->appendToTranscript(encodedHelloRetryRequest);
WriteToSocket serverFlight;
serverFlight.contents.emplace_back(
state.writeRecordLayer()->writeHandshake(
std::move(encodedHelloRetryRequest)));
if (legacySessionId && !legacySessionId->empty()) {
TLSContent writeCCS;
writeCCS.encryptionLevel = EncryptionLevel::Plaintext;
writeCCS.contentType = ContentType::change_cipher_spec;
writeCCS.data = folly::IOBuf::wrapBuffer(FakeChangeCipherSpec);
serverFlight.contents.emplace_back(std::move(writeCCS));
}
auto newReadRecordLayer =
state.context()->getFactory()->makePlaintextReadRecordLayer();
newReadRecordLayer->setSkipEncryptedRecords(
earlyDataType == EarlyDataType::Rejected);
return SemiFuture<Actions>(actions(
MutateState([handshakeContext = std::move(handshakeContext),
version,
cipher,
group,
earlyDataType,
replayCacheResult,
newReadRecordLayer = std::move(newReadRecordLayer),
echStatus,
echState =
std::move(echState)](State& newState) mutable {
newState.handshakeContext() = std::move(handshakeContext);
newState.version() = version;
newState.cipher() = cipher;
newState.group() = group;
newState.keyExchangeType() =
KeyExchangeType::HelloRetryRequest;
newState.earlyDataType() = earlyDataType;
newState.replayCacheResult() = replayCacheResult;
newState.readRecordLayer() = std::move(newReadRecordLayer);
newState.echStatus() = echStatus;
if (echStatus == ECHStatus::Accepted) {
newState.echState() = std::move(echState);
}
}),
std::move(serverFlight),
MutateState(&Transition<StateEnum::ExpectingClientHello>)));
}
if (state.keyExchangeType().has_value()) {
keyExchangeType = *state.keyExchangeType();
} else {
keyExchangeType = KeyExchangeType::OneRtt;
}
kex = state.context()->getFactory()->makeKeyExchange(
*group, Factory::KeyExchangeMode::Server);
kexResultFuture =
doKexFuture(kex.get(), std::move(clientShare.value()));
} else {
keyExchangeType = KeyExchangeType::None;
}
return runOnCallerIfComplete(
state.executor(),
std::move(kexResultFuture),
[&state,
scheduler = std::move(scheduler),
handshakeContext = std::move(handshakeContext),
cipher,
group,
echStatus,
earlyReadRecordLayer = std::move(earlyReadRecordLayer),
earlyReadSecretAvailable = std::move(earlyReadSecretAvailable),
earlyExporterMaster = std::move(earlyExporterMaster),
pskType,
pskMode,
version,
keyExchangeType,
earlyDataType,
replayCacheResult,
alpn = std::move(alpn),
clockSkew,
appToken = std::move(appToken),
legacySessionId = std::move(legacySessionId),
handshakeTime,
chlo = std::move(chlo),
cookieState = std::move(cookieState),
resState = std::move(resState),
kex = std::move(kex)](
Optional<AsyncKeyExchange::DoKexResult> kexResult) mutable {
Optional<Buf> serverShare;
if (kexResult.hasValue()) {
serverShare = std::move(kexResult.value().ourKeyShare);
scheduler->deriveHandshakeSecret(
kexResult.value().sharedSecret->coalesce());
} else {
DCHECK(keyExchangeType == KeyExchangeType::None);
scheduler->deriveHandshakeSecret();
}
std::vector<Extension> additionalExtensions;
if (state.extensions()) {
additionalExtensions = state.extensions()->getExtensions(chlo);
}
if (state.group().has_value() &&
(!group || *group != *state.group())) {
throw FizzException(
"group mismatch with previous negotiation",
AlertDescription::illegal_parameter);
}
if (cookieState && cookieState->group && group &&
*group != *cookieState->group) {
throw FizzException(
"group mismatch with cookie",
AlertDescription::illegal_parameter);
}
auto serverHello = getServerHello(
version,
state.context()->getFactory()->makeRandom(),
cipher,
resState.has_value(),
group,
std::move(serverShare),
legacySessionId ? legacySessionId->clone() : nullptr);
folly::Optional<std::vector<ech::ECHConfig>> echRetryConfigs;
if (echStatus == ECHStatus::Accepted) {
auto echScheduler =
state.context()->getFactory()->makeKeyScheduler(cipher);
echScheduler->deriveEarlySecret(folly::range(chlo.random));
ech::setAcceptConfirmation(
serverHello,
handshakeContext->clone(),
std::move(echScheduler));
} else if (echStatus == ECHStatus::Rejected) {
auto decrypter = state.context()->getECHDecrypter();
echRetryConfigs = decrypter->getRetryConfigs();
}
auto encodedServerHello = encodeHandshake(std::move(serverHello));
handshakeContext->appendToTranscript(encodedServerHello);
auto handshakeWriteRecordLayer =
state.context()->getFactory()->makeEncryptedWriteRecordLayer(
EncryptionLevel::Handshake);
handshakeWriteRecordLayer->setProtocolVersion(version);
auto handshakeWriteSecret = scheduler->getSecret(
HandshakeSecrets::ServerHandshakeTraffic,
handshakeContext->getHandshakeContext()->coalesce());
Protocol::setAead(
*handshakeWriteRecordLayer,
cipher,
folly::range(handshakeWriteSecret.secret),
*state.context()->getFactory(),
*scheduler);
auto handshakeReadRecordLayer =
state.context()->getFactory()->makeEncryptedReadRecordLayer(
EncryptionLevel::Handshake);
handshakeReadRecordLayer->setProtocolVersion(version);
handshakeReadRecordLayer->setSkipFailedDecryption(
earlyDataType == EarlyDataType::Rejected);
auto handshakeReadSecret = scheduler->getSecret(
HandshakeSecrets::ClientHandshakeTraffic,
handshakeContext->getHandshakeContext()->coalesce());
Protocol::setAead(
*handshakeReadRecordLayer,
cipher,
folly::range(handshakeReadSecret.secret),
*state.context()->getFactory(),
*scheduler);
auto clientHandshakeSecret =
folly::IOBuf::copyBuffer(handshakeReadSecret.secret);
auto encodedEncryptedExt = getEncryptedExt(
*handshakeContext,
alpn,
earlyDataType,
std::move(echRetryConfigs),
std::move(additionalExtensions));
bool requestClientAuth = state.context()->getClientAuthMode() !=
ClientAuthMode::None &&
!resState;
Optional<Buf> encodedCertRequest;
if (requestClientAuth) {
encodedCertRequest = getCertificateRequest(
state.context()->getSupportedSigSchemes(),
state.context()->getClientCertVerifier().get(),
*handshakeContext);
}
Optional<Buf> encodedCertificate;
SemiFuture<Optional<Buf>> signature = folly::none;
Optional<SignatureScheme> sigScheme;
Optional<std::shared_ptr<const Cert>> serverCert;
std::shared_ptr<const Cert> clientCert;
Optional<CertificateCompressionAlgorithm> certCompressionAlgo;
if (!resState) {                 std::shared_ptr<const SelfCert> originalSelfCert;
std::tie(originalSelfCert, sigScheme) =
chooseCert(*state.context(), chlo);
std::tie(encodedCertificate, certCompressionAlgo) =
getCertificate(
originalSelfCert,
*state.context(),
chlo,
*handshakeContext);
auto toBeSigned = handshakeContext->getHandshakeContext();
auto asyncSelfCert =
dynamic_cast<const AsyncSelfCert*>(originalSelfCert.get());
if (asyncSelfCert) {
signature = asyncSelfCert->signFuture(
*sigScheme,
CertificateVerifyContext::Server,
std::move(toBeSigned));
} else {
signature = folly::makeSemiFuture<Optional<Buf>>(
originalSelfCert->sign(
*sigScheme,
CertificateVerifyContext::Server,
toBeSigned->coalesce()));
}
serverCert = std::move(originalSelfCert);
} else {
serverCert = std::move(resState->serverCert);
clientCert = std::move(resState->clientCert);
}
auto clientRandom = std::move(chlo.random);
return runOnCallerIfComplete(
state.executor(),
std::move(signature),
[&state,
scheduler = std::move(scheduler),
handshakeContext = std::move(handshakeContext),
cipher,
clientRandom = std::move(clientRandom),
group,
echStatus,
encodedServerHello = std::move(encodedServerHello),
handshakeWriteRecordLayer =
std::move(handshakeWriteRecordLayer),
handshakeWriteSecret = std::move(handshakeWriteSecret),
handshakeReadRecordLayer =
std::move(handshakeReadRecordLayer),
handshakeReadSecret = std::move(handshakeReadSecret),
earlyReadRecordLayer = std::move(earlyReadRecordLayer),
earlyReadSecretAvailable =
std::move(earlyReadSecretAvailable),
earlyExporterMaster = std::move(earlyExporterMaster),
clientHandshakeSecret = std::move(clientHandshakeSecret),
encodedEncryptedExt = std::move(encodedEncryptedExt),
encodedCertificate = std::move(encodedCertificate),
encodedCertRequest = std::move(encodedCertRequest),
requestClientAuth,
pskType,
pskMode,
sigScheme,
version,
keyExchangeType,
earlyDataType,
replayCacheResult,
serverCert = std::move(serverCert),
clientCert = std::move(clientCert),
alpn = std::move(alpn),
clockSkew,
appToken = std::move(appToken),
legacySessionId = std::move(legacySessionId),
serverCertCompAlgo = certCompressionAlgo,
handshakeTime](Optional<Buf> sig) mutable {
Optional<Buf> encodedCertificateVerify;
if (sig) {
encodedCertificateVerify = getCertificateVerify(
*sigScheme, std::move(*sig), *handshakeContext);
}
auto encodedFinished = Protocol::getFinished(
folly::range(handshakeWriteSecret.secret),
*handshakeContext);
folly::IOBufQueue combined;
if (encodedCertificate) {
if (encodedCertRequest) {
combined.append(std::move(encodedEncryptedExt));
combined.append(std::move(*encodedCertRequest));
combined.append(std::move(*encodedCertificate));
combined.append(std::move(*encodedCertificateVerify));
combined.append(std::move(encodedFinished));
} else {
combined.append(std::move(encodedEncryptedExt));
combined.append(std::move(*encodedCertificate));
combined.append(std::move(*encodedCertificateVerify));
combined.append(std::move(encodedFinished));
}
} else {
combined.append(std::move(encodedEncryptedExt));
combined.append(std::move(encodedFinished));
}
auto serverEncrypted =
handshakeWriteRecordLayer->writeHandshake(
combined.splitAtMost(1000));
if (!combined.empty()) {
auto splitRecord =
handshakeWriteRecordLayer->writeHandshake(
combined.move());
DCHECK(
splitRecord.encryptionLevel ==
serverEncrypted.encryptionLevel);
serverEncrypted.data->prependChain(
std::move(splitRecord.data));
}
WriteToSocket serverFlight;
serverFlight.contents.emplace_back(
state.writeRecordLayer()->writeHandshake(
std::move(encodedServerHello)));
if (legacySessionId && !legacySessionId->empty()) {
TLSContent ccsWrite;
ccsWrite.encryptionLevel = EncryptionLevel::Plaintext;
ccsWrite.contentType = ContentType::change_cipher_spec;
ccsWrite.data =
folly::IOBuf::wrapBuffer(FakeChangeCipherSpec);
serverFlight.contents.emplace_back(std::move(ccsWrite));
}
serverFlight.contents.emplace_back(
std::move(serverEncrypted));
scheduler->deriveMasterSecret();
auto clientFinishedContext =
handshakeContext->getHandshakeContext();
auto exporterMasterVector = scheduler->getSecret(
MasterSecrets::ExporterMaster,
clientFinishedContext->coalesce());
auto exporterMaster = folly::IOBuf::copyBuffer(
folly::range(exporterMasterVector.secret));
scheduler->deriveAppTrafficSecrets(
clientFinishedContext->coalesce());
auto appTrafficWriteRecordLayer =
state.context()
->getFactory()
->makeEncryptedWriteRecordLayer(
EncryptionLevel::AppTraffic);
appTrafficWriteRecordLayer->setProtocolVersion(version);
auto writeSecret = scheduler->getSecret(
AppTrafficSecrets::ServerAppTraffic);
Protocol::setAead(
*appTrafficWriteRecordLayer,
cipher,
folly::range(writeSecret.secret),
*state.context()->getFactory(),
*scheduler);
auto earlyDataTypeSave = state.earlyDataType()
? *state.earlyDataType()
: earlyDataType;
SecretAvailable handshakeReadSecretAvailable(
std::move(handshakeReadSecret));
SecretAvailable handshakeWriteSecretAvailable(
std::move(handshakeWriteSecret));
SecretAvailable appWriteSecretAvailable(
std::move(writeSecret));
MutateState saveState(
[appTrafficWriteRecordLayer =
std::move(appTrafficWriteRecordLayer),
handshakeContext = std::move(handshakeContext),
scheduler = std::move(scheduler),
exporterMaster = std::move(exporterMaster),
serverCert = std::move(serverCert),
clientCert = std::move(clientCert),
cipher,
group,
sigScheme,
clientHandshakeSecret =
std::move(clientHandshakeSecret),
pskType,
pskMode,
version,
keyExchangeType,
alpn = std::move(alpn),
earlyDataTypeSave,
replayCacheResult,
clockSkew,
appToken = std::move(appToken),
serverCertCompAlgo,
echStatus,
clientRandom = std::move(clientRandom),
handshakeTime = std::move(handshakeTime)](
State& newState) mutable {
newState.writeRecordLayer() =
std::move(appTrafficWriteRecordLayer);
newState.handshakeContext() =
std::move(handshakeContext);
newState.keyScheduler() = std::move(scheduler);
newState.exporterMasterSecret() =
std::move(exporterMaster);
newState.serverCert() = std::move(*serverCert);
newState.clientCert() = std::move(clientCert);
newState.version() = version;
newState.cipher() = cipher;
newState.group() = group;
newState.sigScheme() = sigScheme;
newState.clientHandshakeSecret() =
std::move(clientHandshakeSecret);
newState.pskType() = pskType;
newState.pskMode() = pskMode;
newState.keyExchangeType() = keyExchangeType;
newState.earlyDataType() = earlyDataTypeSave;
newState.replayCacheResult() = replayCacheResult;
newState.alpn() = std::move(alpn);
newState.clientClockSkew() = clockSkew;
newState.appToken() = std::move(appToken);
newState.serverCertCompAlgo() = serverCertCompAlgo;
newState.handshakeTime() = std::move(handshakeTime);
newState.clientRandom() = std::move(clientRandom);
newState.echStatus() = echStatus;
newState.echState() = folly::none;
});
if (earlyDataType == EarlyDataType::Accepted) {
if (state.context()->getOmitEarlyRecordLayer()) {
return actions(
MutateState([handshakeReadRecordLayer = std::move(
handshakeReadRecordLayer),
earlyExporterMaster =
std::move(earlyExporterMaster)](
State& newState) mutable {
newState.readRecordLayer() =
std::move(handshakeReadRecordLayer);
newState.earlyExporterMasterSecret() =
std::move(earlyExporterMaster);
}),
std::move(saveState),
std::move(*earlyReadSecretAvailable),
std::move(handshakeReadSecretAvailable),
std::move(handshakeWriteSecretAvailable),
std::move(appWriteSecretAvailable),

static int gif_image_write_image(AVCodecContext *avctx,
uint8_t **bytestream, uint8_t *end,
const uint32_t *palette,
const uint8_t *buf, const int linesize,
AVPacket *pkt)
{
GIFContext *s = avctx->priv_data;
int len = 0, height = avctx->height, width = avctx->width, x, y;
int x_start = 0, y_start = 0, trans = s->transparent_index;
int honor_transparency = (s->flags & GF_TRANSDIFF) && s->last_frame;
const uint8_t *ptr;
if ((s->flags & GF_OFFSETTING) && s->last_frame && !palette) {
const uint8_t *ref = s->last_frame->data[0];
const int ref_linesize = s->last_frame->linesize[0];
int x_end = avctx->width  - 1,
y_end = avctx->height - 1;
while (y_start < y_end) {
if (memcmp(ref + y_start*ref_linesize, buf + y_start*linesize, width))
break;
y_start++;
}
while (y_end > y_start) {
if (memcmp(ref + y_end*ref_linesize, buf + y_end*linesize, width))
break;
y_end--;
}
height = y_end + 1 - y_start;
while (x_start < x_end) {
int same_column = 1;
for (y = y_start; y <= y_end; y++) {
if (ref[y*ref_linesize + x_start] != buf[y*linesize + x_start]) {
same_column = 0;
break;
}
}
if (!same_column)
break;
x_start++;
}
while (x_end > x_start) {
int same_column = 1;
for (y = y_start; y <= y_end; y++) {
if (ref[y*ref_linesize + x_end] != buf[y*linesize + x_end]) {
same_column = 0;
break;
}
}
if (!same_column)
break;
x_end--;
}
width = x_end + 1 - x_start;
av_log(avctx, AV_LOG_DEBUG,"%dx%d image at pos (%d;%d) [area:%dx%d]\n",
width, height, x_start, y_start, avctx->width, avctx->height);
}
bytestream_put_byte(bytestream, GIF_IMAGE_SEPARATOR);
bytestream_put_le16(bytestream, x_start);
bytestream_put_le16(bytestream, y_start);
bytestream_put_le16(bytestream, width);
bytestream_put_le16(bytestream, height);
if (!palette) {
bytestream_put_byte(bytestream, 0x00); 
} else {
unsigned i;
bytestream_put_byte(bytestream, 1<<7 | 0x7); 
for (i = 0; i < AVPALETTE_COUNT; i++) {
const uint32_t v = palette[i];
bytestream_put_be24(bytestream, v);
}
}
if (honor_transparency && trans < 0) {
trans = pick_palette_entry(buf + y_start*linesize + x_start,
linesize, width, height);
if (trans < 0) {             av_log(avctx, AV_LOG_DEBUG, "No available color, can not use transparency\n");
} else {
uint8_t *pal_exdata = s->pal_exdata;
if (!pal_exdata)
pal_exdata = av_packet_new_side_data(pkt, AV_PKT_DATA_PALETTE, AVPALETTE_SIZE);
if (!pal_exdata)
return AVERROR(ENOMEM);
memcpy(pal_exdata, s->palette, AVPALETTE_SIZE);
pal_exdata[trans*4 + 3*!HAVE_BIGENDIAN] = 0x00;
}
}
if (trans < 0)
honor_transparency = 0;
bytestream_put_byte(bytestream, 0x08);
ff_lzw_encode_init(s->lzw, s->buf, 2 * width * height,
12, FF_LZW_GIF, put_bits);
ptr = buf + y_start*linesize + x_start;
if (honor_transparency) {
const int ref_linesize = s->last_frame->linesize[0];
const uint8_t *ref = s->last_frame->data[0] + y_start*ref_linesize + x_start;
for (y = 0; y < height; y++) {
memcpy(s->tmpl, ptr, width);
for (x = 0; x < width; x++)
if (ref[x] == ptr[x])
s->tmpl[x] = trans;
len += ff_lzw_encode(s->lzw, s->tmpl, width);
ptr += linesize;
ref += ref_linesize;
}
} else {
for (y = 0; y < height; y++) {
len += ff_lzw_encode(s->lzw, ptr, width);
ptr += linesize;
}
}
len += ff_lzw_encode_flush(s->lzw, flush_put_bits);
ptr = s->buf;
while (len > 0) {
int size = FFMIN(255, len);
bytestream_put_byte(bytestream, size);
if (end - *bytestream < size)
return -1;
bytestream_put_buffer(bytestream, ptr, size);
ptr += size;
len -= size;
}
bytestream_put_byte(bytestream, 0x00); 
return 0;
}

