int zfp_rate_decompress(const uint8_t *input, int32_t input_len, uint8_t *output,
int32_t output_len, uint8_t meta, blosc2_dparams *dparams, const void *chunk) {
ZFP_ERROR_NULL(input);
ZFP_ERROR_NULL(output);
ZFP_ERROR_NULL(dparams);
BLOSC_UNUSED_PARAM(chunk);
blosc2_schunk *sc = dparams->schunk;
int32_t typesize = sc->typesize;
double ratio = (double) meta / 100.0;
int8_t ndim;
int64_t *shape = malloc(8 * sizeof(int64_t));
int32_t *chunkshape = malloc(8 * sizeof(int32_t));
int32_t *blockshape = malloc(8 * sizeof(int32_t));
uint8_t *smeta;
int32_t smeta_len;
if (blosc2_meta_get(sc, "b2nd", &smeta, &smeta_len) < 0) {
BLOSC_TRACE_ERROR("Cannot access b2nd meta info");
free(shape);
free(chunkshape);
free(blockshape);
return BLOSC2_ERROR_FAILURE;
}
deserialize_meta(smeta, smeta_len, &ndim, shape, chunkshape, blockshape);
free(smeta);
zfp_type type;     
zfp_field *field;  
zfp_stream *zfp;   
bitstream *stream; 
size_t zfpsize;    
switch (typesize) {
case sizeof(float):
type = zfp_type_float;
break;
case sizeof(double):
type = zfp_type_double;
break;
default:
free(shape);
free(chunkshape);
free(blockshape);
BLOSC_TRACE_ERROR("ZFP is not available for typesize: %d", typesize);
return BLOSC2_ERROR_FAILURE;
}
double rate =
ratio * (double) typesize * 8;       zfp = zfp_stream_open(NULL);
zfp_stream_set_rate(zfp, rate, type, ndim, zfp_false);
stream = stream_open((void *) input, input_len);
zfp_stream_set_bit_stream(zfp, stream);
zfp_stream_rewind(zfp);
switch (ndim) {
case 1:
field = zfp_field_1d((void *) output, type, blockshape[0]);
break;
case 2:
field = zfp_field_2d((void *) output, type, blockshape[1], blockshape[0]);
break;
case 3:
field = zfp_field_3d((void *) output, type, blockshape[2], blockshape[1], blockshape[0]);
break;
case 4:
field = zfp_field_4d((void *) output, type, blockshape[3], blockshape[2], blockshape[1], blockshape[0]);
break;
default:
free(shape);
free(chunkshape);
free(blockshape);
BLOSC_TRACE_ERROR("ZFP is not available for ndims: %d", ndim);
return BLOSC2_ERROR_FAILURE;
}
zfpsize = zfp_decompress(zfp, field);
zfp_field_free(field);
zfp_stream_close(zfp);
stream_close(stream);
free(shape);
free(chunkshape);
free(blockshape);
if (zfpsize == 0) {
BLOSC_TRACE_ERROR("\n ZFP: Decompression failed\n");
return (int) zfpsize;
}
return (int) output_len;
}

static wStream* rdg_receive_packet(rdpRdg* rdg)
{
wStream* s;
const size_t header = sizeof(RdgPacketHeader);
size_t packetLength;
assert(header <= INT_MAX);
s = Stream_New(NULL, 1024);
if (!s)
return NULL;
if (!rdg_read_all(rdg->tlsOut, Stream_Buffer(s), header))
{
Stream_Free(s, TRUE);
return NULL;
}
Stream_Seek(s, 4);
Stream_Read_UINT32(s, packetLength);
if ((packetLength > INT_MAX) || !Stream_EnsureCapacity(s, packetLength))
{
Stream_Free(s, TRUE);
return NULL;
}
if (!rdg_read_all(rdg->tlsOut, Stream_Buffer(s) + header, (int)packetLength - (int)header))
{
Stream_Free(s, TRUE);
return NULL;
}
Stream_SetLength(s, packetLength);
return s;
}

bool CmtkLoader::load(const std::string &filename, const CFileProvider &fp)
{
binistream *f = fp.open(filename); if(!f) return false;
struct {
char id[18];
unsigned short crc,size;
} header;
struct mtkdata {
char songname[34],composername[34],instname[0x80][34];
unsigned char insts[0x80][12],order[0x80],dummy,patterns[0x32][0x40][9];
} *data;
unsigned char *cmp,*org;
unsigned int i;
unsigned long cmpsize,cmpptr=0,orgptr=0;
unsigned short ctrlbits=0,ctrlmask=0,cmd,cnt,offs;
f->readString(header.id, 18);
header.crc = f->readInt(2);
header.size = f->readInt(2);
if(strncmp(header.id,"mpu401tr\x92kk\xeer@data",18))
{ fp.close(f); return false; }
cmpsize = fp.filesize(f) - 22;
cmp = new unsigned char[cmpsize];
org = new unsigned char[header.size];
for(i = 0; i < cmpsize; i++) cmp[i] = f->readInt(1);
fp.close(f);
while(cmpptr < cmpsize) {    ctrlmask >>= 1;
if(!ctrlmask) {
ctrlbits = cmp[cmpptr] + (cmp[cmpptr + 1] << 8);
cmpptr += 2;
ctrlmask = 0x8000;
}
if(!(ctrlbits & ctrlmask)) {      if(orgptr >= header.size)
goto err;
org[orgptr] = cmp[cmpptr];
orgptr++; cmpptr++;
continue;
}
cmd = (cmp[cmpptr] >> 4) & 0x0f;
cnt = cmp[cmpptr] & 0x0f;
cmpptr++;
switch(cmd) {
case 0:
if(orgptr + cnt > header.size) goto err;
cnt += 3;
memset(&org[orgptr],cmp[cmpptr],cnt);
cmpptr++; orgptr += cnt;
break;
case 1:
if(orgptr + cnt > header.size) goto err;
cnt += (cmp[cmpptr] << 4) + 19;
memset(&org[orgptr],cmp[++cmpptr],cnt);
cmpptr++; orgptr += cnt;
break;
case 2:
if(orgptr + cnt > header.size) goto err;
offs = (cnt+3) + (cmp[cmpptr] << 4);
cnt = cmp[++cmpptr] + 16; cmpptr++;
memcpy(&org[orgptr],&org[orgptr - offs],cnt);
orgptr += cnt;
break;
default:
if(orgptr + cmd > header.size) goto err;
offs = (cnt+3) + (cmp[cmpptr++] << 4);
memcpy(&org[orgptr],&org[orgptr-offs],cmd);
orgptr += cmd;
break;
}
}
delete [] cmp;
data = (struct mtkdata *) org;
memset(title,0,34); strncpy(title,data->songname+1,33);
memset(composer,0,34); strncpy(composer,data->composername+1,33);
memset(instname,0,0x80*34);
for(i=0;i<0x80;i++)
strncpy(instname[i],data->instname[i]+1,33);
memcpy(instr,data->insts,0x80 * 12);
memcpy(song,data->order,0x80);
memcpy(patterns,data->patterns,header.size-6084);
for (i=0;i<128;i++) {    instr[i][2] ^= (instr[i][2] & 0x40) << 1;
instr[i][3] ^= (instr[i][3] & 0x40) << 1;
instr[i][11] >>= 4;  }
delete [] org;
rewind(0);
return true;
err:
delete [] cmp;
delete [] org;
return false;
}

static int compat_copy_entry_to_user(struct ipt_entry *e,
void __user **dstptr, compat_uint_t *size)
{
struct ipt_entry_target __user *t;
struct compat_ipt_entry __user *ce;
u_int16_t target_offset, next_offset;
compat_uint_t origsize;
int ret;
ret = -EFAULT;
origsize = *size;
ce = (struct compat_ipt_entry __user *)*dstptr;
if (copy_to_user(ce, e, sizeof(struct ipt_entry)))
goto out;
*dstptr += sizeof(struct compat_ipt_entry);
ret = IPT_MATCH_ITERATE(e, compat_copy_match_to_user, dstptr, size);
target_offset = e->target_offset - (origsize - *size);
if (ret)
goto out;
t = ipt_get_target(e);
if (t->u.kernel.target->compat)
ret = t->u.kernel.target->compat(t, dstptr, size,
COMPAT_TO_USER);
else
ret = xt_compat_target(t, dstptr, size, COMPAT_TO_USER);
if (ret)
goto out;
ret = -EFAULT;
next_offset = e->next_offset - (origsize - *size);
if (put_user(target_offset, &ce->target_offset))
goto out;
if (put_user(next_offset, &ce->next_offset))
goto out;
return 0;
out:
return ret;
}

void CalculateOutputIndexValueRowID(
OpKernelContext* context, const RowPartitionTensor& value_rowids,
const vector<INDEX_TYPE>& parent_output_index,
INDEX_TYPE output_index_multiplier, INDEX_TYPE output_size,
vector<INDEX_TYPE>* result) {
const INDEX_TYPE index_size = value_rowids.size();
result->reserve(index_size);
if (index_size == 0) {
return;
}
INDEX_TYPE current_output_column = 0;
INDEX_TYPE current_value_rowid = value_rowids(0);
DCHECK_LT(current_value_rowid, parent_output_index.size());
INDEX_TYPE current_output_index = parent_output_index[current_value_rowid];
result->push_back(current_output_index);
for (INDEX_TYPE i = 1; i < index_size; ++i) {
INDEX_TYPE next_value_rowid = value_rowids(i);
if (next_value_rowid == current_value_rowid) {
if (current_output_index >= 0) {
++current_output_column;
if (current_output_column < output_size) {
current_output_index += output_index_multiplier;
} else {
current_output_index = -1;
}
}
} else {
current_output_column = 0;
current_value_rowid = next_value_rowid;
DCHECK_LT(next_value_rowid, parent_output_index.size());
current_output_index = parent_output_index[next_value_rowid];
}
result->push_back(current_output_index);
}
OP_REQUIRES(context, result->size() == value_rowids.size(),
errors::InvalidArgument("Invalid row ids."));
}

