int main(int argc, char *argv[])
{
int result;
int infoOnly = 0;
int writeToStdio = 0;
int readFromStdin = 0;
int object_type = LC;
int def_srate = 0;
int downMatrix = 0;
int format = 1;
int outputFormat = FAAD_FMT_16BIT;
int outfile_set = 0;
int adts_out = 0;
int old_format = 0;
int showHelp = 0;
int mp4file = 0;
int noGapless = 0;
char *fnp;
char aacFileName[255];
char audioFileName[255];
char adtsFileName[255];
unsigned char header[8];
float length = 0;
FILE *hMP4File;
#ifdef _WIN32
long begin;
#else
clock_t begin;
#endif
unsigned long cap = NeAACDecGetCapabilities();
progName = argv[0];
while (1) {
int c = -1;
int option_index = 0;
static struct option long_options[] = {
{ "quiet",      0, 0, 'q' },
{ "outfile",    0, 0, 'o' },
{ "adtsout",    0, 0, 'a' },
{ "oldformat",  0, 0, 't' },
{ "format",     0, 0, 'f' },
{ "bits",       0, 0, 'b' },
{ "samplerate", 0, 0, 's' },
{ "objecttype", 0, 0, 'l' },
{ "downmix",    0, 0, 'd' },
{ "info",       0, 0, 'i' },
{ "stdio",      0, 0, 'w' },
{ "stdio",      0, 0, 'g' },
{ "help",       0, 0, 'h' },
{ 0, 0, 0, 0 }
};
c = getopt_long(argc, argv, "o:a:s:f:b:l:wgdhitq",
long_options, &option_index);
if (c == -1)
break;
switch (c) {
case 'o':
if (optarg)
{
outfile_set = 1;
strcpy(audioFileName, optarg);
}
break;
case 'a':
if (optarg)
{
adts_out = 1;
strcpy(adtsFileName, optarg);
}
break;
case 's':
if (optarg)
{
char dr[10];
if (sscanf(optarg, "%s", dr) < 1) {
def_srate = 0;
} else {
def_srate = atoi(dr);
}
}
break;
case 'f':
if (optarg)
{
char dr[10];
if (sscanf(optarg, "%s", dr) < 1)
{
format = 1;
} else {
format = atoi(dr);
if ((format < 1) || (format > 2))
showHelp = 1;
}
}
break;
case 'b':
if (optarg)
{
char dr[10];
if (sscanf(optarg, "%s", dr) < 1)
{
outputFormat = FAAD_FMT_16BIT; 
} else {
outputFormat = atoi(dr);
if ((outputFormat < 1) || (outputFormat > 5))
showHelp = 1;
}
}
break;
case 'l':
if (optarg)
{
char dr[10];
if (sscanf(optarg, "%s", dr) < 1)
{
