DataBuf PngChunk::parseTXTChunk(const DataBuf& data,
int            keysize,
TxtChunkType   type)
{
DataBuf arr;
if(type == zTXt_Chunk)
{
const byte* compressionMethod = data.pData_ + keysize + 1;
if ( *compressionMethod != 0x00 )
{
#ifdef DEBUG
std::cerr << "Exiv2::PngChunk::parseTXTChunk: Non-standard zTXt compression method.\n";
#endif
throw Error(kerFailedToReadImageData);
}
const byte* compressedText      = data.pData_ + keysize + 2;
unsigned int compressedTextSize = data.size_  - keysize - 2;
zlibUncompress(compressedText, compressedTextSize, arr);
}
else if(type == tEXt_Chunk)
{
const byte* text = data.pData_ + keysize + 1;
long textsize    = data.size_  - keysize - 1;
arr = DataBuf(text, textsize);
}
else if(type == iTXt_Chunk)
{
const int nullSeparators = std::count(&data.pData_[keysize+3], &data.pData_[data.size_], '\0');
enforce(nullSeparators >= 2, Exiv2::kerCorruptedMetadata);
const byte compressionFlag   = data.pData_[keysize + 1];
const byte compressionMethod = data.pData_[keysize + 2];
enforce(compressionFlag == 0x00 || compressionFlag == 0x01, Exiv2::kerCorruptedMetadata);
enforce(compressionMethod == 0x00, Exiv2::kerCorruptedMetadata);
std::string languageText((const char*)(data.pData_ + keysize + 3));
unsigned int languageTextSize = static_cast<unsigned int>(languageText.size());
std::string translatedKeyText((const char*)(data.pData_ + keysize + 3 + languageTextSize +1));
unsigned int translatedKeyTextSize = static_cast<unsigned int>(translatedKeyText.size());
if ( compressionFlag == 0x00 )
{
#ifdef DEBUG
std::cout << "Exiv2::PngChunk::parseTXTChunk: We found an uncompressed iTXt field\n";
#endif
const byte* text = data.pData_ + keysize + 3 + languageTextSize + 1 + translatedKeyTextSize + 1;
long textsize    = data.size_ - (keysize + 3 + languageTextSize + 1 + translatedKeyTextSize + 1);
arr.alloc(textsize);
arr = DataBuf(text, textsize);
}
else if ( compressionFlag == 0x01 && compressionMethod == 0x00 )
{
#ifdef DEBUG
std::cout << "Exiv2::PngChunk::parseTXTChunk: We found a zlib compressed iTXt field\n";
#endif
const byte* compressedText = data.pData_ + keysize + 3 + languageTextSize + 1 + translatedKeyTextSize + 1;
long compressedTextSize    = data.size_ - (keysize + 3 + languageTextSize + 1 + translatedKeyTextSize + 1);
zlibUncompress(compressedText, compressedTextSize, arr);
}
else
{
#ifdef DEBUG
std::cerr << "Exiv2::PngChunk::parseTXTChunk: Non-standard iTXt compression method.\n";
#endif
throw Error(kerFailedToReadImageData);
}
}
else
{
#ifdef DEBUG
std::cerr << "Exiv2::PngChunk::parseTXTChunk: We found a field, not expected though\n";
#endif
throw Error(kerFailedToReadImageData);
}
return arr;
}

PJ_DEF(pj_status_t) pjmedia_rtp_decode_rtp2(
pjmedia_rtp_session *ses,
const void *pkt, int pkt_len,
const pjmedia_rtp_hdr **hdr,
pjmedia_rtp_dec_hdr *dec_hdr,
const void **payload,
unsigned *payloadlen)
{
int offset;
PJ_UNUSED_ARG(ses);
*hdr = (pjmedia_rtp_hdr*)pkt;
if ((*hdr)->v != RTP_VERSION) {
return PJMEDIA_RTP_EINVER;
}
offset = sizeof(pjmedia_rtp_hdr) + ((*hdr)->cc * sizeof(pj_uint32_t));
if ((*hdr)->x) {
dec_hdr->ext_hdr = (pjmedia_rtp_ext_hdr*)(((pj_uint8_t*)pkt) + offset);
dec_hdr->ext = (pj_uint32_t*)(dec_hdr->ext_hdr + 1);
dec_hdr->ext_len = pj_ntohs((dec_hdr->ext_hdr)->length);
offset += ((dec_hdr->ext_len + 1) * sizeof(pj_uint32_t));
} else {
dec_hdr->ext_hdr = NULL;
dec_hdr->ext = NULL;
dec_hdr->ext_len = 0;
}
if (offset > pkt_len)
return PJMEDIA_RTP_EINLEN;
*payload = ((pj_uint8_t*)pkt) + offset;
*payloadlen = pkt_len - offset;
if ((*hdr)->p && *payloadlen > 0) {
pj_uint8_t pad_len;
pad_len = ((pj_uint8_t*)(*payload))[*payloadlen - 1];
if (pad_len <= *payloadlen)
*payloadlen -= pad_len;
}
return PJ_SUCCESS;
}

int
yang_read_extcomplex_str(struct lys_module *module, struct lys_ext_instance_complex *ext, const char *arg_name,
const char *parent_name, char *value, int parent_stmt, LY_STMT stmt)
{
int c;
const char **str, ***p = NULL;
void *reallocated;
struct lyext_substmt *info;
c = 0;
if (stmt == LY_STMT_PREFIX && parent_stmt == LY_STMT_BELONGSTO) {
str = lys_ext_complex_get_substmt(LY_STMT_BELONGSTO, ext, &info);
if (info->cardinality < LY_STMT_CARD_SOME) {
str++;
} else {
p = (const char ***)str;
for (c = 0; p[0][c + 1]; c++);
str = p[1];
}
str[c] = lydict_insert_zc(module->ctx, value);
}  else {
str = lys_ext_complex_get_substmt(stmt, ext, &info);
if (!str) {
LOGVAL(module->ctx, LYE_INCHILDSTMT, LY_VLOG_NONE, NULL, arg_name, parent_name);
goto error;
}
if (info->cardinality < LY_STMT_CARD_SOME && *str) {
LOGVAL(module->ctx, LYE_TOOMANY, LY_VLOG_NONE, NULL, arg_name, parent_name);
goto error;
}
if (info->cardinality >= LY_STMT_CARD_SOME) {
p = (const char ***)str;
if (!p[0]) {
p[0] = calloc(2, sizeof(const char *));
LY_CHECK_ERR_GOTO(!p[0], LOGMEM(module->ctx), error);
if (stmt == LY_STMT_BELONGSTO) {
p[1] = calloc(2, sizeof(const char *));
LY_CHECK_ERR_GOTO(!p[1], LOGMEM(module->ctx), error);
} else if (stmt == LY_STMT_ARGUMENT) {
((uint8_t **)p)[1] = calloc(2, sizeof(uint8_t));
LY_CHECK_ERR_GOTO(!p[1], LOGMEM(module->ctx), error);
((uint8_t *)p[1])[0] = 2;
}
} else {
for (c = 0; p[0][c]; c++);
}
str = p[0];
}
str[c] = lydict_insert_zc(module->ctx, value);
value = NULL;
if (c) {
reallocated = realloc(p[0], (c + 2) * sizeof(const char *));
if (!reallocated) {
LOGMEM(module->ctx);
lydict_remove(module->ctx, p[0][c]);
p[0][c] = NULL;
return EXIT_FAILURE;
}
p[0] = reallocated;
p[0][c + 1] = NULL;
if (stmt == LY_STMT_BELONGSTO) {
reallocated = realloc(p[1], (c + 2) * sizeof(const char *));
if (!reallocated) {
LOGMEM(module->ctx);
lydict_remove(module->ctx, p[1][c]);
p[1][c] = NULL;
return EXIT_FAILURE;
}
p[1] = reallocated;
p[1][c + 1] = NULL;
} else if (stmt == LY_STMT_ARGUMENT) {
reallocated = realloc(p[1], (c + 2) * sizeof(uint8_t));
if (!reallocated) {
LOGMEM(module->ctx);
((uint8_t *)p[1])[c] = 0;
return EXIT_FAILURE;
}
p[1] = reallocated;
((uint8_t *)p[1])[c + 1] = 0;
}
}
}
return EXIT_SUCCESS;
error:
free(value);
return EXIT_FAILURE;
}

